INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'515be8da-62da-43d4-8676-0001fdf39350', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the core philosophy behind Qwik''s performance approach known as Resumability?', N'Fresher', N'Resumability allows an application to become interactive instantly without needing to download and execute all JavaScript upfront. Unlike hydration, which requires re-running framework logic on the client, Qwik serializes the state of the application into the HTML, allowing it to pause execution on the server and resume exactly where it left off in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d6cfbd5-229c-4ea3-9f4e-00026abbac29', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Can Webpack bundle images?', N'Junior', N'Yes, Webpack can handle images using asset modules. These modules allow you to import images directly into your JavaScript files, and Webpack can either emit the image as a separate file or inline it as a data URL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'358f2793-b074-480f-baf3-00054acab115', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the primary difference between metrics, logs, and traces in an observability stack?', N'Middle', N'Metrics provide aggregated numerical data over time to track trends and system health. Logs offer granular, event-based records of specific occurrences for debugging. Traces visualize the path of a request across multiple services to identify latency bottlenecks and service dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a03de521-4c76-49dd-a69c-00077a261171', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are the security implications of using Hono''s automatic request validation middleware versus manual schema validation?', N'Senior', N'Automatic validation, often paired with libraries like Zod, ensures that the request payload adheres to a defined contract before it reaches the business logic, drastically reducing injection-related vulnerabilities. While manual validation is more flexible, it is prone to human error and ''forgotten'' checks, whereas schema-driven validation enforces a ''deny-by-default'' security posture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46277381-d8b7-4a40-8a6a-000a439ea40a', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are the benefits of using Django''s environment variable management?', N'Middle', N'Managing sensitive configurations like database credentials and API keys via environment variables is a security best practice. It prevents hardcoding secrets into your codebase, making it easier to manage different configurations across development, staging, and production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b7a9973-102a-4ec1-9dbf-000adcb131d3', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are asked to estimate the number of windows in your city, how would you approach the problem?', N'Intern', N'I would start by estimating the total population of the city and dividing it by the average number of people per household to find the number of homes. Then, I would multiply that by an average estimate of windows per home and add a proportional estimate for office buildings and commercial spaces based on the city''s business density.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5470cdd2-1ad9-4265-8de3-000ca91316b8', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the primary security goal of infrastructure-as-code (IaC) scanning?', N'Middle', N'IaC scanning identifies security misconfigurations, such as open S3 buckets or overly permissive security groups, before infrastructure is deployed. It shifts security left, ensuring that the cloud environment is hardened by design before it is even created.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ee413b6-ea91-47b0-b466-000ee86508c8', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does the ''Show'' component optimize conditional rendering?', N'Middle', N'The Show component creates a reactive boundary that only updates when the condition changes. It avoids re-rendering the entire component, only toggling the visibility or existence of the children when the boolean trigger flips.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc216a06-c4bf-4613-bbfe-000f41f6944c', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your approach to handling data migrations in a live production database?', N'Middle', N'I use a multi-step migration process that keeps both the old and new schemas compatible during the transition. I perform the migration in small, reversible batches and implement comprehensive logging to track progress and rollback immediately if issues arise.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6f6b830-ce35-40cc-9670-000fe624f5d3', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus handle configuration properties?', N'Junior', N'Quarkus uses MicroProfile Config, which allows properties to be injected from various sources like environment variables, system properties, or an application.properties file. These properties are easily accessible within the code using the ConfigProperty annotation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff35cdec-eae5-4e3a-8785-00122e96ad67', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Describe the behavior of PHP''s internal string interning mechanism.', N'Senior', N'String interning stores unique string literals in a central buffer to save memory and speed up comparisons. When the engine encounters a string literal, it checks the interned string table to return a reference to the existing instance instead of allocating new memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bfd8bb3-7560-4fd9-affa-00124b6f6922', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a covering index and why is it beneficial?', N'Middle', N'A covering index contains all the columns required to satisfy a specific query, allowing the database engine to retrieve the data directly from the index structure. This avoids the need for a costly lookup to the actual table rows, significantly increasing query performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5d2d267-552c-4f84-a441-0012a22265f2', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the ''islands'' architecture in Nuxt?', N'Middle', N'Islands architecture allows you to selectively hydrate specific components on the page. By isolating interactive parts into ''islands'', Nuxt can keep the rest of the page as static HTML, drastically reducing the amount of JavaScript sent to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'698f573c-96d1-49b6-a743-001411e6a621', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When integrating with a third-party API, what is the trade-off between implementing a circuit breaker and simple retry logic?', N'Middle', N'Simple retry logic can overwhelm a failing service, potentially causing a cascade of failures. A circuit breaker prevents this by failing fast during outages, allowing the downstream system to recover, though it requires more complex configuration and state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd112399c-acac-4467-8c72-00177f47ac24', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is horizontal scaling in MongoDB?', N'Intern', N'Horizontal scaling, or sharding, is the process of distributing data across multiple servers. This allows MongoDB to handle increased data growth and traffic loads by adding more machines to the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6cefda7-01fd-4ed0-b74e-001b0ca5e905', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What metrics are most important when monitoring the health of a distributed system?', N'Middle', N'The golden signals—latency, traffic, errors, and saturation—are essential for understanding system health. Additionally, business-specific metrics like conversion rates or transaction success rates provide context on whether the system is meeting its operational objectives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'041a89c2-da15-450a-8ab0-001b15667112', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the disadvantages of NoSQL?', N'Fresher', N'Some disadvantages include a lack of standardized query language, potential issues with strong consistency, and the fact that it is not ideal for complex analytical or multi-table relational queries. Additionally, the lack of a strict schema can sometimes lead to data inconsistency if not managed properly by the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'101f0d40-05d8-48fb-9880-001beee9bd06', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does the TypeScript compiler''s ''incremental'' build flag work, and what are its limitations?', N'Senior', N'The incremental flag saves project build info to a file, allowing the compiler to re-use previous results for unchanged modules. While it significantly speeds up subsequent builds, it can sometimes lead to ''stale'' type errors if the internal dependency graph is not correctly identified, requiring occasional full clean builds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81f40909-40ae-499e-9ddb-001ded571e14', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the primary difference between a relational database and Elasticsearch?', N'Intern', N'Relational databases are optimized for transactional integrity and structured queries using SQL. Elasticsearch is optimized for unstructured data, full-text search, and horizontal scaling across distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf31c33d-ade7-47f6-9e33-002238c6d1de', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is an attribute in a database?', N'Fresher', N'An attribute is a characteristic or property of an entity that describes it. For example, if ''Employee'' is an entity, its attributes could be ''Name'', ''Email'', and ''EmployeeID''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfa04e4b-239b-4432-b600-002239b39d01', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does browser ''layerization'' impact mobile device performance?', N'Senior', N'Layerization is the process of creating independent compositor layers for specific elements. On mobile devices with limited GPU memory, creating too many layers can consume excessive RAM, leading to memory pressure, scrolling stutter, and potential page termination by the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3f5e449-3200-40fe-9ebf-00240da5d386', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is meant by the Atomicity property of a transaction?', N'Intern', N'Atomicity ensures that all operations within a transaction are completed successfully. If any part of the transaction fails, the entire transaction is aborted, and the database is left unchanged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03cb171b-f718-4f3b-b186-002674d56903', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the purpose of ''App::wrap'' in the Actix configuration?', N'Middle', N'App::wrap is used to apply middleware globally to all routes defined within an application. It provides a clean way to inject cross-cutting concerns like CORS headers, compression, or request logging without repeating code for every individual route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
