INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c094003-c75b-4ca5-877b-002a37be3be3', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the main advantage of using a ''Quorum-based'' consistency model?', N'Middle', N'Quorum-based models allow developers to tune the balance between read and write consistency by specifying the number of nodes that must participate in an operation. It provides flexibility to prioritize either speed or consistency based on the specific needs of a query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'314d32c7-7a0a-444c-a905-002b43f1c24f', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What does it mean for a framework like Hono to be ''platform-agnostic''?', N'Intern', N'Being platform-agnostic means the framework does not rely on a specific environment''s unique APIs. It uses standard Web APIs, such as the Fetch API, which allows the same code to run seamlessly across different serverless and local runtimes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e94742c1-8263-4d40-b0c9-002e9ec35525', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Explain the significance of Svelte''s reactivity system based on variable assignments.', N'Senior', N'Svelte uses static analysis during compilation to track dependencies and inject reactivity into assignments. By treating simple variable assignments as triggers for DOM updates, it avoids the overhead of proxy-based systems or explicit state setter functions, leading to a more natural developer experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba159dfb-8ded-4bb5-90d2-002f15e688c4', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the Java memory model handle visibility in multithreaded applications?', N'Middle', N'The memory model defines rules for how threads interact through main memory. Without proper synchronization or the use of the volatile keyword, changes made by one thread might not be visible to others due to thread-local caching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7aa790c7-4d96-4bca-b00d-0038faebb5e0', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the function of the ''filter'' context in a query, and how does it differ from ''must''?', N'Middle', N'The filter context is used for binary yes/no questions and does not affect the relevance score of the documents. Unlike the must clause, filter results are cached by Elasticsearch, providing better performance for repeated queries that do not require scoring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
