INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1807a101-ba32-4b32-bb1e-003eefdbb092', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the difference between Use and With in Chi?', N'Junior', N'The Use method applies middleware to the current router and all sub-routers created from it. The With method creates a new sub-router with the specified middleware applied only to the subsequent route definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
