INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'663e15dd-fabf-4a12-a1f5-0053eb14221b', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you balance the trade-off between developer experience and system performance?', N'Senior', N'I prioritize developer experience for non-critical paths to improve long-term maintainability and speed of iteration. For hot paths or latency-critical services, I accept increased complexity and reduced developer ergonomics in exchange for performance optimizations, such as lower-level language choices or specialized data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
