INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f78a1bc-1ad3-4a7e-99de-005d23b9cfdc', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a reference variable?', N'Intern', N'A reference is an alias for an existing variable, meaning it provides another name for the same memory location. Unlike a pointer, a reference must be initialized when it is created and cannot be changed to refer to a different variable later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a89af71a-2a0e-410a-a23d-0060da94c7d6', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the trade-offs of Go''s stack management strategy compared to fixed-size stacks.', N'Senior', N'Go uses growable, contiguous stacks that start small and expand as needed by copying the stack to a larger memory area. This avoids the memory waste associated with large, fixed-size stacks while preventing the risk of stack overflow common in languages without overflow checks. The trade-off is the complexity of managing stack pointers and the occasional performance cost of copying during stack growth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
