INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd39e9c17-9cff-410d-a348-007ce228e45c', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are Flask hooks?', N'Fresher', N'Hooks, or request lifecycle decorators like ''before_request'' and ''after_request'', allow you to execute code before or after a request is processed. They are useful for tasks like opening database connections or logging requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ef7bf6f-dc83-43a7-8c40-007e2ce2f5de', N'954a0331-deff-4399-b588-96f39fec001d', N'What happens if the custom id is not unique?', N'Junior', N'You need to define custom ids as unique. If you use the same id for two different text messages then only the first one is extracted. But its translation is used in place of both original text messages. For example, let''s define same custom id myCustomId for two messages, and the translation unit generated for first text in for German language as Since custom id is the same, both of the elements in the translation contain the same text as below', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'197dc4e4-3a1a-496e-b8eb-007e3d79b5a3', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is Entity Framework Core and why is it used?', N'Junior', N'Entity Framework Core is an Object-Relational Mapper (ORM) that allows developers to interact with databases using .NET objects rather than writing raw SQL queries. It simplifies data access by handling mappings between the database schema and application entities, making database operations more productive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'212ac4fd-e78a-471c-ad39-007e9f5041ef', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Describe the trade-offs between using Lit''s property ''reflect'' attribute and standard props.', N'Senior', N'Reflecting a property to an attribute makes it visible to CSS selectors and standard DOM APIs, which is useful for styling hooks or external integrations. However, it incurs a performance cost due to the synchronous DOM mutation and can potentially trigger infinite update loops if not managed carefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8c26797-c6f2-46ee-b80a-007ec88c7721', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the purpose of the ''package main'' declaration?', N'Junior', N'The ''package main'' declaration tells the Go compiler that this file should be compiled as an executable program rather than a shared library. It is required for the file containing the entry point function, main().', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'feb9055e-1a3e-43fb-b307-00803330306f', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do Error Boundaries work, and what are their limitations regarding asynchronous code?', N'Senior', N'Error Boundaries are class components that catch errors occurring in the lifecycle or render methods of their children. They cannot catch errors in asynchronous code such as event handlers or setTimeout, which must be handled with standard try-catch blocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84251864-0f1a-4723-ace1-0086bc1c8187', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the advantages of using ''namedtuple'' or ''dataclasses'' over standard dictionaries for data modeling?', N'Senior', N'Namedtuples and dataclasses provide structured, type-hinted, and immutable or semi-immutable containers that are more memory-efficient than dictionaries. They offer attribute-based access, which is more readable and less error-prone than string-based key lookups. These structures improve code quality by enforcing a schema and making the intent of data objects explicit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3599b63-915c-4397-be34-00874db6749f', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach database schema migrations in a production environment?', N'Junior', N'I prioritize backward compatibility by breaking changes into multiple, incremental steps that allow both the old and new code versions to run simultaneously. I also ensure that all migrations are automated, reversible, and tested in a staging environment to minimize the risk of downtime or data corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
