INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97ec27c1-e781-4bfd-9e29-0097f101b600', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the architectural impact of Hono’s ''RPC Mode'' on client-side integration and distributed system contract enforcement?', N'Senior', N'Hono''s RPC mode allows the server to export its type definitions, enabling the client to consume API endpoints with full autocompletion and type safety without manual contract maintenance. This drastically reduces the surface area for interface-mismatch bugs in distributed systems by treating the API surface as a shared, type-checked library rather than a loose set of HTTP endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
