INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'299c3466-4a31-4ae4-9a3a-00a105574f85', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Why is it important to keep the main isolate''s event loop clear of heavy computations?', N'Middle', N'The main isolate is responsible for the UI frame rendering; if it performs heavy calculations, the event loop will block, causing the UI to freeze and drop frames. Offloading heavy work to separate isolates ensures the UI remains responsive even under high computational load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3297a93a-f4d6-4e96-a640-00a27ea1c297', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the difference between static and dynamic rendering in SvelteKit?', N'Junior', N'Static rendering pre-generates pages at build time, while dynamic rendering generates them on-demand when a request is received. SvelteKit allows you to choose the rendering strategy based on the needs of each route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d6e292c-fd7e-48d9-ad3e-00a7e83604e3', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle a scenario where two services have a circular dependency?', N'Middle', N'I would look to decouple the services by introducing an intermediary, such as a message broker or an event bus, to facilitate asynchronous communication. If that is not possible, I would extract the shared logic into a separate, independent library or service. Breaking the circular dependency is critical to improving system modularity and simplifying deployment pipelines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b011a208-abbf-4687-a8ed-00a93ad7a54d', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Explain the significance of ''sideEffects'' in package.json for modern bundlers.', N'Senior', N'The sideEffects flag explicitly tells the bundler whether a module performs tasks like modifying global prototypes or CSS injection. Marking a package as side-effect-free allows Webpack to aggressively prune unused exports, even if they appear to be imported.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3669c11-87e1-49da-ab23-00a989ea31d7', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the role of the ''FromData'' trait?', N'Middle', N'The FromData trait allows custom types to be derived from the request body. This is the mechanism Rocket uses to support content types like JSON, allowing developers to extend the framework to support XML, YAML, or other data formats seamlessly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c995262-48a9-4f7e-bbb1-00ad932b2974', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How do you stop an event from propagating in jQuery?', N'Junior', N'You call event.stopPropagation() within the event handler function. This prevents the event from bubbling up to parent elements in the DOM tree, ensuring that only the specific element''s handler is triggered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca2dc0fb-7d88-4057-98f2-00adfdf157c0', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the ''DbContext'' class?', N'Junior', N'The DbContext class represents a session with the database, acting as the bridge between your application code and the database tables. It is responsible for tracking changes to entities and saving them to the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24765b75-371a-498e-b4cf-00b028824683', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the significance of the ''Hydration Mismatch'' warning, and how do you architect your app to avoid it?', N'Senior', N'Hydration mismatches occur when the server-rendered DOM differs from the initial client-side render, often due to non-deterministic data like random numbers or localized dates. To avoid this, developers should use lifecycle hooks like ''onMounted'' for browser-only logic or ensure that state generation logic is identical on both the server and client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'729e5283-e4a9-4fc5-9854-00b10a8b58f6', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle server-side data fetching compared to client-side fetching?', N'Middle', N'Qwik leverages server-side data fetching to ensure the initial HTML contains all necessary data for the first render. Once the app is running, it uses similar abstractions to fetch data on the client, ensuring a consistent developer experience across the full-stack boundary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd183f909-7566-443e-bab3-00b157f6fac2', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you handle a situation where you discover a bug in production that affects a small number of users?', N'Junior', N'I would report the issue to the team lead to assess the severity and impact scope. I would then document the reproduction steps, help isolate the root cause, and follow the team''s standard hotfix procedure while ensuring the fix is verified in a staging environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05ec6925-425b-4518-ac0e-00b1d0a5cf50', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite''s CSS handling differ from traditional build tools?', N'Senior', N'Vite treats CSS as a first-class citizen, injecting it directly into the DOM via style tags during development for rapid updates. In production, it extracts CSS into separate files to improve loading performance and cacheability, leveraging PostCSS for automatic vendor prefixing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
