INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39a02abd-edff-4832-b703-00b32f644fff', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What architectural problem does ''Bloom Filters'' solve when used in front of a database cache?', N'Senior', N'Bloom filters efficiently determine if a key definitely does not exist in the database, preventing unnecessary ''cache misses'' for requests seeking non-existent data. This protects the backend from ''negative hit'' attacks where malicious actors flood the system with requests for keys that do not exist.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5274bd7d-f912-4e00-b845-00b4c3f77e81', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does the ''Application'' callback module manage the lifecycle of a Phoenix server?', N'Senior', N'The Application module serves as the supervision tree root, defining how the application starts, stops, and recovers from failures. It ensures that critical dependencies like the database connection pool and the Phoenix Endpoint are started in the correct order, providing a predictable environment for the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1aaa2127-5db3-4e83-b8b7-00b50e2ab6b3', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Discuss the significance of the ''CatchBoundary'' or ''error handling'' patterns in Remix.', N'Senior', N'Remix distinguishes between expected errors, like a 404 or 401, and unexpected runtime errors. The framework''s design forces developers to handle these states explicitly, resulting in more resilient applications that degrade gracefully under adverse conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecf0c820-fca3-48ca-8ec7-00b8ba5aa426', N'954a0331-deff-4399-b588-96f39fec001d', N'What are Pipes in Angular and where would you use them?', N'Intern', N'Pipes in Angular allow you to transform displayed values in templates. Use them to format strings, dates, decimals; or to sort and filter arrays. Core Pipe Types String Use the string parameter to perform text transformations. In the template, use the pipe as follows: Numeric The built-in number pipes allow decimal and currency formatting, and the percent pipe displays a number as a percentage. Date The date pipe can format dates as per your requirements: Array The array pipe allows you to sort or filter an array in the view. For example, to sort a list of names: Custom Pipes You can create custom pipes when the built-in ones don''t meet your requirements. For example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd6b756f-d1e4-478e-927f-00c147fe5cb7', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Can Alpine.js be used with other frameworks?', N'Intern', N'Yes, Alpine.js is designed to be highly compatible with other frameworks and libraries. Since it is just a script that enhances HTML, it can coexist with server-side frameworks like Laravel or Django without conflict.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6cd8d9f-355b-4eea-94c4-00c610c17cf3', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Explain the role of the ''Entity Adapter'' pattern in Redux Toolkit.', N'Senior', N'The Entity Adapter pattern automates the management of normalized data by providing pre-built reducers and selectors for CRUD operations. It simplifies the boilerplate associated with maintaining items by ID and allows for performant lookups without manual iteration over arrays.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'768fc584-2c69-4dff-b52e-00c8455f151c', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the advantage of using ''layout groups'' in SvelteKit routing?', N'Middle', N'Layout groups allow you to organize routes into logical sections without affecting the URL structure. This lets you apply different layouts to specific sets of pages, such as applying an ''auth'' layout to login and register pages while keeping them in the root URL path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'020e5652-20f4-4473-97c6-00cffb57d234', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Can TypeScript catch errors that occur during runtime?', N'Junior', N'No, TypeScript''s type checking happens during compilation. It cannot prevent errors that are triggered by logic flaws, external API data, or user interactions that occur while the application is running.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
