INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3d06217-2683-4923-80a2-00d395779590', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the ''generateStaticParams'' function used for?', N'Middle', N'This function is used in dynamic segments to pre-render specific routes at build time rather than on-demand. It is useful for known, finite sets of data, such as blog posts or categories, to improve performance through static generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba6e6233-0009-4a70-a264-00d940f178ce', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum manage request body buffering?', N'Senior', N'Axum handles request body buffering through extractors, which can consume the request stream. It is important to note that bodies can only be consumed once, so developers must be careful when using multiple extractors that require the body, often necessitating the use of specialized types that support buffering or cloning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bc144a4-19c1-494a-92ee-00db1fb8fc7c', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the difference between stack and heap memory in Rust?', N'Intern', N'The stack stores data with a known, fixed size at compile time, while the heap stores data that may change in size during runtime. Rust uses the stack for performance and the heap for data that needs to persist beyond the current scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48313217-8000-4342-af0e-00de39908297', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the use of preventDefault method?', N'Intern', N'The preventDefault() method is used to prevent the browser from executing the default action of the selected element. It can prevent the user from processing the request by clicking the link. For example, prevent form submission when clicking on submit button and prevent opening the page URL when clicking on hyper link are some common usecases. *Note: Remember that not all events are cancelable*.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
