INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccc6292c-001b-4eab-bf66-00e04bef4688', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of tree shaking in Webpack, and what conditions must be met for it to work?', N'Middle', N'Tree shaking is a process that eliminates dead or unused code from the final bundle to reduce its size. For it to work, the project must use ES modules (import/export statements) instead of CommonJS, as ES modules have a static structure that allows Webpack to perform static analysis. Additionally, it typically requires the production mode to be enabled so that the minifier can effectively remove the unreachable code blocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4a920da-c24b-47aa-ba3b-00e0949984b7', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the difference between a character and a factor in R?', N'Fresher', N'A character stores text data as literal strings, while a factor stores text as integer codes associated with labels. Factors are more memory-efficient for categorical data and are required for many statistical models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79534dad-d639-49f0-9e2d-00e123f58b44', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are template engines and why are they used in Express?', N'Junior', N'Template engines like EJS or Pug allow you to generate dynamic HTML pages by replacing variables in template files with actual values. They are used in Express to render views on the server side before sending them to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92ef2f7b-04dd-44ca-9d61-00e2dbc3aa16', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the difference between Gin''s Default engine and New engine?', N'Fresher', N'The New engine creates a bare-bones Gin instance with no pre-configured middleware. The Default engine creates an instance that automatically includes the Logger and Recovery middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bccedf43-3dc9-4be7-b780-00e36e571466', N'a2838158-7305-480a-b22b-4dc35776b400', N'How do you reconcile the trade-off between consistency and availability in a distributed system during a network partition, specifically regarding the CAP theorem?', N'Senior', N'In the event of a network partition, a system must choose between consistency and availability. If you prioritize consistency, the system will reject requests to prevent stale reads, effectively sacrificing availability. If you prioritize availability, the system remains responsive but may return inconsistent data across different nodes, requiring conflict resolution mechanisms like vector clocks or CRDTs once the partition heals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa13dd85-9881-4fa1-9d84-00e42be9220b', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Explain the significance of the ''State'' object in Litestar.', N'Middle', N'The State object acts as a thread-safe, request-scoped dictionary that persists data across the lifetime of a request. It is the recommended way to pass information between middleware, dependency providers, and route handlers without using global variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5888ba8-144d-43ad-b71c-00e443e905b2', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Is Java a pure object-oriented language? Why or why not?', N'Junior', N'Java is not a pure object-oriented language. While it incorporates many object-oriented programming (OOP) principles, it retains some elements from procedural programming. Object-Oriented Features in Java Java supports the four main pillars of OOP: 1. Encapsulation: Achieved through access modifiers (public, private, protected). 2. Abstraction: Implemented via abstract classes and interfaces. 3. Inheritance: Supported using the extends keyword for classes and implements for interfaces. 4. Polymorphism: Realized through method overloading and overriding. Non-Pure OOP Elements in Java 1. Primitive Data Types: Java includes non-object primitives like int, boolean, char, etc. 2. Static Members: The static keyword allows for class-level fields and methods, not tied to object instances. 3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a782c70-2f3f-4ffb-9f4e-00e48560dcc0', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the purpose of the ''BeforeRequest'' and ''AfterResponse'' hooks?', N'Fresher', N'These are lifecycle hooks that allow you to execute logic before a request is processed or after a response has been generated. They are useful for tasks like timing requests or adding audit logs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2edc3ab1-ab1d-42d9-a2ab-00e5c5bf8c99', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Compare Hono’s request parsing mechanism to frameworks designed exclusively for Node.js.', N'Senior', N'Node-specific frameworks often rely on the ''http'' module''s internal streams and buffers, which are not available in V8 isolates used by edge runtimes. Hono uses the Fetch API''s standard ''ReadableStream'' and ''FormData'' implementations, ensuring that parsing logic remains consistent and performant across both V8 isolates and standard Node environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33a82e0b-2ff0-4358-817e-00e6857126f8', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why is it important to monitor cache eviction rates?', N'Middle', N'High eviction rates may indicate that the cache is too small for the working set of data, leading to ''cache thrashing.'' Tracking this metric helps architects decide when to increase memory allocation or optimize the key expiration logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0390d1f2-a90e-4f72-ba21-00e71c84004a', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Describe the impact of the ''deep'' dependency tree often found in Node.js projects.', N'Senior', N'Large dependency trees increase security risks through supply chain vulnerabilities and increase the risk of version conflicts. They also slow down installation times and increase the memory footprint of the application. Using lock files and performing regular audits is essential for managing these risks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdb31ffa-c0d2-4b6e-88b9-00e770b7de1d', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Why is Hono considered ''Zero-Dependency'' and how does this affect long-term maintenance?', N'Senior', N'By avoiding external dependencies, Hono minimizes the supply chain attack surface and eliminates ''dependency hell'' where conflicting versions of shared libraries occur. This design choice ensures long-term stability and easier auditing, as the framework''s entire behavior is contained within its own codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74380f43-4baf-4631-bc5d-00e799fa0560', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does message ordering work in a distributed queue?', N'Middle', N'Maintaining strict global message ordering is difficult in distributed systems due to partitioning and parallel processing. It is usually achieved by partitioning messages based on a key so that all messages with the same key are routed to the same consumer instance in sequential order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ef23e3d-d492-49e8-b376-00eafe6449d3', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using a strongly typed language versus a dynamically typed language?', N'Junior', N'Strongly typed languages catch errors at compile-time, which improves reliability and makes refactoring safer. Dynamically typed languages allow for faster prototyping and less boilerplate code, but they require more comprehensive testing to catch type-related errors at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f8da1d4-7594-4651-b9da-00eb352dbd2c', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are the benefits of using a CDN to link external files?', N'Junior', N'A Content Delivery Network (CDN) hosts files on servers closer to the user, which can improve loading speeds. It also increases the likelihood that a user''s browser has already cached the file from another site, further reducing load times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3f8a696-2c46-4213-8822-00ec476593eb', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a replica set in NoSQL?', N'Intern', N'A replica set is a group of database instances that maintain the same data, ensuring high availability and redundancy. If one node fails, another node in the replica set can automatically take over, preventing data loss and system downtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33f583c1-2118-42b8-9857-00f12c64f500', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the difference between an ''App'' and a ''Group'' in Fiber?', N'Fresher', N'An App is the root instance of the framework, while a Group is a way to logically organize routes under a common path. Groups inherit middleware and settings from the root App but allow for cleaner route management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ceea095b-6319-4b96-badb-00f1f1595e68', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a function, why is it better to have it perform only one task rather than multiple tasks?', N'Fresher', N'Following the single responsibility principle makes the function easier to test, debug, and maintain. If a function does too many things, it becomes complex, harder to reuse, and more prone to side effects when one part of its logic needs to change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f23d991-b7c6-45f1-9698-00f3b00befa1', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of the ''disconnectedCallback'' method?', N'Intern', N'The disconnectedCallback is a native web component lifecycle method that runs when the element is removed from the document. It is used for cleanup tasks like removing event listeners to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'915f6ea8-9e21-45ac-8a34-00f3c53c7eb2', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What advantage is there for using the JavaScript arrow syntax for a method in a constructor?', N'Middle', N'The main advantage of using an arrow function as a method inside a constructor is that the value of this gets set at the time of the function creation and can''t change after that. When the constructor is used to create a new object, this will always refer to that object. For example, let''s say we have a Person constructor that takes a first name as an argument and has two methods to console.log() that name, one as a regular function and one as an arrow function: The main takeaway here is that this can be changed for a normal function, but this always stays the same for an arrow function. So even if you are passing around your arrow function to different parts of your application, you wouldn''t have to worry about the value of this changing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e05b9d09-4a25-4dae-b00e-00f3c6d87ab4', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the CAP theorem, and how does it influence the choice of a NoSQL database?', N'Middle', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. In the context of NoSQL, developers must choose a database that prioritizes the requirements of their specific application, such as favoring availability over strict consistency for high-traffic web services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb0f1609-42d6-44a4-aa9e-00f4d1a5db47', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite implement CSS code splitting, and why is it beneficial for performance?', N'Senior', N'Vite automatically extracts CSS imported in asynchronous components into separate files. This prevents blocking the initial page load with unnecessary styles and ensures that CSS is only loaded when the corresponding component is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b885ced1-95de-4faf-8a04-00f8e1622c75', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a natural key?', N'Junior', N'A natural key is a column or set of columns that already exists in the real-world data and uniquely identifies a row. Examples include a Social Security Number or an email address, though these are sometimes avoided as primary keys due to potential changes or privacy concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23896781-21ae-4233-a354-00fa5d42e6be', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why is it recommended to use connection pooling in PostgreSQL?', N'Middle', N'PostgreSQL creates a new process for every client connection, which consumes significant memory and CPU resources. Connection pooling, using tools like PgBouncer, maintains a set of persistent connections that are reused by incoming requests, reducing the overhead of process creation and context switching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8e03b32-ab10-47b0-aea0-00fc7649596a', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the significance of the nil object in Ruby?', N'Intern', N'In Ruby, nil is a special object that represents the absence of a value. Unlike null in some other languages, nil is a first-class object that is an instance of the NilClass, allowing it to have its own methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ffad444-041c-44ba-a4fc-00fe2e3a0939', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What architectural benefits does Chi provide for building large-scale modular monoliths?', N'Senior', N'Chi supports ''Router Mounting,'' which allows developers to isolate routing logic into independent sub-routers. This modularity enables teams to define domain-specific middleware and route groups, significantly improving maintainability and reducing the cognitive load compared to a single, flat routing configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa855022-34a1-4579-bf48-0100a5f28444', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the ''loading=lazy'' attribute interact with the browser''s intersection observer logic?', N'Senior', N'The native lazy loading attribute uses the browser''s internal viewport calculations to defer the fetch of an image or iframe until it is near the viewport. This is more efficient than a manual Intersection Observer implementation because it is handled at the network layer before the main thread processes the layout.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7771f184-49ad-419e-a014-01012bb1b38d', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the core architectural philosophy of Qwik?', N'Middle', N'Qwik is designed for ''resumability'', which allows the application to pause execution on the server and resume it on the client without re-executing the entire component tree. This eliminates hydration, which is the process of re-running JS to attach event listeners and state to server-rendered HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'626a8def-9bc7-4e34-8f22-0105a82b633e', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are the considerations for implementing JWT authentication in a Flask application?', N'Senior', N'You must handle token expiration, revocation, and secure storage on the client side. The application should use a robust library for token verification to prevent common vulnerabilities like algorithm confusion attacks and ensure that the secret key used for signing is never exposed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9417fb76-5522-4393-9fed-0105aa06639d', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How do you handle hover states in Tailwind CSS?', N'Intern', N'Tailwind uses state modifiers, which are prefixes added to utility classes. By adding the ''hover:'' prefix before a class, you tell Tailwind to only apply that style when the user hovers over the element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23fe5832-6ff5-42cb-ae26-01070c98ea5e', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you style dynamic generated content using scoped css?', N'Fresher', N'The scoped css style doesn''t impact v-html directive''s dynamically generated content. In this case, you can use deep selectors to solve this styling issue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20c078e5-f8db-42e7-b045-010a5c2e87f6', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the purpose of Axum state?', N'Intern', N'State is a shared data structure that can be passed into handlers to provide access to resources like database connections or configuration settings. It allows different parts of the application to share information safely across multiple requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b471ed6-5084-420a-a670-010f57e7fa5f', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does ''Database Replication Lag'' affect application design?', N'Senior', N'Replication lag introduces a window where read replicas might return stale data, which can lead to application errors if the user expects immediate consistency. Developers must design their applications to either tolerate this staleness or route critical reads directly to the primary node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'704a28bf-bc46-4b07-af28-01166fffc716', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Why is idempotency critical for system reliability?', N'Middle', N'Idempotency ensures that performing the same operation multiple times results in the same state as performing it once. This is essential for reliability because it allows safe retries after network timeouts or partial failures without creating duplicate data or inconsistent states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db0521e5-b92a-4299-8f4d-011729b4dde8', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the difference between Primary Key and Partition Key?', N'Junior', N'The primary key is the unique identifier for a row, while the partition key is a subset of the primary key that determines data distribution across nodes. A primary key can also include clustering columns to define sorting within the partition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11e3e432-e62f-4b63-ae31-011c6d2858ca', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why would you choose to use an index on a database table?', N'Junior', N'Indexes are used to speed up data retrieval operations by creating a separate data structure that allows the database to locate rows without scanning the entire table. However, they come with a trade-off because they can slow down write operations like inserts and updates since the index must also be updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd41bc9f2-28c8-4adb-bb9c-011d718e0fef', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is a ''lifespan'' event in FastAPI?', N'Fresher', N'Lifespan events allow you to define code that runs when the application starts up and when it shuts down. This is useful for initializing resources like database connections or clearing cache before the server stops.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'858f38a9-9930-42e7-af80-011f6eaace2d', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are the benefits of using an In-Memory cache versus a Distributed cache?', N'Middle', N'In-Memory cache is extremely fast as it resides in the application''s local process memory but is limited to a single server instance. Distributed cache, such as Redis, allows data to be shared across multiple server instances, ensuring consistency in a load-balanced environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
