INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'350b57d9-dd30-4434-aabf-012286efd109', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the advantage of using path aliases in Vite?', N'Middle', N'Path aliases, configured via the ''resolve.alias'' option, allow you to use shorthand paths for deep directory structures. This makes imports cleaner and more resilient to project refactoring, as you don''t need to update relative paths when files are moved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'442c97c0-e48e-464b-a59a-01246fa43ae7', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact ensure compatibility with modern build tools like Vite or Webpack?', N'Senior', N'Preact is built to be modular and standard-compliant, allowing it to integrate seamlessly with modern ESM-based build tools. It relies on standard package resolution and tree-shaking, which allows developers to pull in only the features they need, effectively reducing the final production bundle size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'094c1ed6-f62d-4157-9c12-0124af61eb34', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact''s diffing algorithm handle list rendering performance?', N'Middle', N'Preact uses key-based diffing to track list items efficiently, similar to React, but with a more lightweight implementation. It attempts to reorder, add, or remove nodes in the DOM based on the keys provided, minimizing unnecessary DOM element recreation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be69b0bd-9162-4a79-a341-0125088fc092', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is an atomic transaction?', N'Intern', N'An atomic transaction is a series of database operations that are treated as a single unit of work. Either all operations succeed, or none of them are applied, ensuring the database does not end up in a partially updated state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e49b7500-15d5-441f-98ce-01261f37f934', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the primary difference between dynamic dispatch and static dispatch regarding performance and binary size in Rust?', N'Senior', N'Static dispatch uses generics and monomorphization, which generates specialized code for every type, resulting in faster execution but potentially larger binaries due to code bloat. Dynamic dispatch uses trait objects with vtables, which incurs a runtime pointer indirection cost but keeps binary sizes smaller by sharing the same implementation across different types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
