INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c97fe9fb-daeb-4c01-8743-012baf57c230', N'075b8862-431c-4678-9767-f55359758a4a', N'Discuss the performance implications of ''shallowRef'' and ''shallowReactive'' in large-scale applications.', N'Senior', N'Shallow variants only track reactivity at the root level of the object, avoiding the performance overhead of deep recursive dependency tracking. They are highly effective when managing large, immutable data structures or third-party datasets where granular change detection is unnecessary, significantly reducing memory usage and initialization time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aac3d13f-8ad9-460d-9230-012c16f3bfc4', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why might you choose Rocket over other Rust web frameworks like Actix-web?', N'Middle', N'Rocket is often chosen for its focus on developer experience, ergonomic API design, and its philosophy of ''type-safe first.'' While frameworks like Actix-web may offer raw performance advantages, Rocket provides a more batteries-included approach that simplifies common web development tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f49af63-0812-4f5a-b4f7-012cd0ab9e0a', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Explain how Qwik handles dependency injection within its serialized environment.', N'Senior', N'Qwik uses a registry-based approach to dependency injection that allows services to be instantiated and serialized alongside the component state. This ensures that when a component resumes, it has access to the same service instances it had on the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
