INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd55800b0-37b0-4a5d-8ef3-013043523f08', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the concept of ''Dirty Reads'' and why they are generally avoided.', N'Middle', N'A dirty read occurs when a transaction reads uncommitted data written by another concurrent transaction that may later roll back. This is avoided because it can lead to data inconsistencies and incorrect application logic based on data that technically never officially existed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7433f393-b0c6-4784-8125-01315206e41e', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro ensure that CSS bundles do not grow linearly with the number of components?', N'Senior', N'Astro performs tree-shaking and component-level CSS injection, meaning it only includes styles for the components actually rendered on the current page. By scoping styles and removing unused rules at build time, it prevents the delivery of bloated, page-wide stylesheets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'486df277-7c28-423e-a61f-0132551a9d7c', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the advantage of Tailwind''s ''spacing'' system?', N'Junior', N'Tailwind uses a standardized spacing scale for margins, padding, and gaps, which helps maintain visual consistency across your application. By using these predefined values, you prevent ''magic number'' spacing issues that often occur when using arbitrary pixel values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe61f09d-7d14-41de-8d6e-01360a594240', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of redirecting in Flask?', N'Intern', N'Redirecting sends a response to the user''s browser telling it to navigate to a different URL. This is commonly used after processing a form submission to prevent duplicate submissions or to send the user to a new page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55d91d78-f4f8-4e91-90e0-013a22e2ccac', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the risks of using ''update_all'' or ''delete_all'' in Rails?', N'Middle', N'These methods execute SQL commands directly on the database without instantiating model objects, which means they bypass ActiveRecord validations, callbacks, and any logic defined in the model. They are extremely fast but can lead to inconsistent data if the application logic expects those callbacks or validations to trigger.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'424935b2-e23d-49b6-a037-013b141027c3', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a user authentication system, why should you use tokens instead of sending credentials with every request?', N'Fresher', N'Sending credentials with every request increases the risk of them being intercepted. Using a token-based system allows the user to log in once, receive a signed token, and use that token for subsequent requests, which is more secure and efficient for stateless communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'555301ea-b031-4212-9379-013e1b00eb39', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the role of an Identity Provider (IdP) in a modern architecture?', N'Middle', N'An IdP is a service that manages user identities and provides authentication services to other applications through protocols like OpenID Connect or SAML. It centralizes user management, enabling Single Sign-On (SSO) and consistent security policy enforcement across multiple services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e601777-925a-4d65-9c0d-014335368c84', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between error handling that terminates the process versus one that attempts recovery?', N'Fresher', N'If the error puts the system in an inconsistent or dangerous state, immediate termination is the safest path to prevent data corruption. If the error is transient and recoverable, retry logic or graceful degradation provides a better user experience by keeping the service running.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37c29327-36a6-46cd-902c-01433858d319', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Can you use SolidJS without a build step?', N'Middle', N'While SolidJS is typically used with a compiler to optimize reactivity, it can be used via a runtime-only approach. However, the compiler is highly recommended as it performs static analysis to generate the most efficient DOM update code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19bbbd48-df4a-4792-bf5f-0147d8915861', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How would you decompose a monolithic application into microservices?', N'Senior', N'Decomposing a monolithic application into microservices involves breaking down a larger piece of software into smaller, interconnected services. This process allows for greater development agility, flexibility, and often better scalability. Key Considerations 1. Domain-Driven Design (DDD): Microservices should be independently deployable and manageable pieces of the application, typically built around distinct business areas or domains. 2. Database Strategy: Each microservice should have its own data storage, but for ease of data access and management, it''s beneficial for microservices to share a database when practical. 3. Communication: The microservices should interact with each other in a well-coordinated manner.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd078e238-a55e-401a-b511-0149575bbda5', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does Python’s Global Interpreter Lock (GIL) impact multi-threaded performance, and why can it be a bottleneck in CPU-bound tasks?', N'Senior', N'The GIL ensures that only one thread executes Python bytecode at a time, preventing race conditions in memory management. For CPU-bound tasks, this prevents true parallelism across multiple cores, effectively serializing execution regardless of the number of threads. To bypass this, developers typically use the multiprocessing module to spawn separate processes with their own memory space and GIL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef4636be-5062-4c3e-9062-014a8aac1cfd', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Explain the performance benefits of Preact''s direct DOM mutation approach compared to traditional frameworks.', N'Senior', N'Preact minimizes the abstraction layer between the virtual DOM and the browser''s DOM by mapping VNodes directly to elements without excessive wrapping. This reduces the number of intermediate objects created during the rendering cycle, leading to faster paint times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24518d00-da6f-4745-9746-014bfc3f4e8b', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Explain the role of the ''locals'' object in SvelteKit.', N'Senior', N'The ''locals'' object is a container used to store request-specific data, such as user session information or database connections, which are populated during the ''handle'' hook. It is passed down to all subsequent server-side functions, providing a secure and clean way to propagate context without relying on global variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc4732ab-d46e-44f5-bac1-0150057a03ff', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the advantage of using ''Bloom Filters'' in large-scale storage systems?', N'Senior', N'A Bloom filter is a space-efficient probabilistic data structure used to test whether an element is part of a set, potentially returning false positives but never false negatives. It is used to prevent expensive disk lookups for data that does not exist in the cache or database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95109394-a82b-4ba3-bf3a-01506f8604bf', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is Babel and how does transpilation work?', N'Intern', N'Babel is a JavaScript transpiler (source-to-source compiler) that converts modern JavaScript (ES6+) into a backwards-compatible version for older browsers or environments that don''t support the latest syntax. How it works: 1. Parse — Source code is parsed into an AST (Abstract Syntax Tree). 2. Transform — Plugins traverse and modify the AST (e.g. convert arrow functions to regular functions). 3. Generate — The modified AST is printed back to JavaScript source code. Installation: babel.config.json: Example transformation: Polyfills vs. transpilation: * Transpilation handles *syntax* (arrow functions, destructuring, classes). * Polyfills (core-js, regenerator-runtime) handle missing *runtime APIs* (Promise, Array.from, generators).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c4e7aa1-1413-429a-ae66-0153458b41b8', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What does the x-data attribute do?', N'Fresher', N'The x-data attribute is used to declare a new Alpine component and define its initial data state. It acts as the scope for all other Alpine directives within that HTML element, allowing you to manage local variables and functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3955fe9b-d9cf-495b-9fef-01562a0536a7', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'When should you use ''save'' versus ''save(validate: false)''?', N'Middle', N'The ''save'' method runs all defined validations on the model and returns false if they fail. Using ''save(validate: false)'' skips these checks, which is useful for data migrations or emergency fixes but carries the risk of inserting invalid or inconsistent data into the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b9f6876-941d-4161-83ce-01565bd0a9f3', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How are errors handled in Fiber?', N'Fresher', N'Fiber provides a global error handler that catches errors returned by route handlers. Developers can define custom error handling logic to return standardized responses to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ac390b5-c6aa-466b-a420-0156abedbca0', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI leverage the Python type system to optimize request validation and serialization?', N'Senior', N'FastAPI uses Pydantic models to define schemas, which utilize Python type hints to perform runtime data validation and transformation. This approach allows the framework to automatically generate JSON schemas and enforce constraints during request parsing, significantly reducing boilerplate code while ensuring type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b59cff23-5b0e-4e21-b5db-015b3e03a1f8', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you decide between using a relational database and a NoSQL database?', N'Fresher', N'A relational database is ideal for structured data with complex relationships where consistency is critical. A NoSQL database is often better for unstructured or rapidly changing data that requires high flexibility and horizontal scaling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dda5ee7-0635-4de3-8fef-015cab2a48de', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Explain the significance of the Anti-Forgery Token and how it prevents CSRF attacks in ASP.NET Core.', N'Senior', N'The Anti-Forgery token adds a unique, cryptographically secure token to state-changing requests, which the server validates against a cookie. This prevents CSRF attacks because the attacker cannot read the cookie to obtain the token, ensuring that only requests originating from the legitimate application are processed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27a307f0-3952-43d0-b306-015d3f9d0826', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are the core building blocks of a Lit component?', N'Junior', N'A Lit component is essentially a class that extends the LitElement base class. It consists of a template defined by the html tag function, reactive properties, and lifecycle callbacks to manage the component''s state and behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b0ba04b-e8db-412c-bebe-015d93e1329c', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What happens to reflection-heavy libraries when compiling to a native image in Quarkus?', N'Senior', N'Native compilation is ''closed-world,'' meaning it cannot resolve reflection calls that aren''t known at build time. Quarkus provides a configuration system to explicitly register classes and methods for reflection, allowing the native image to include the necessary metadata without maintaining the overhead of full reflection capabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e34efa2a-8613-497b-94d2-0164f432b333', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Describe the difference between an lvalue and an rvalue in C.', N'Senior', N'An lvalue refers to an object that occupies a identifiable location in memory, while an rvalue is a temporary value that does not persist beyond the expression that evaluates it. Understanding this distinction is critical for understanding memory access, assignment, and the lifetime of variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f37fe812-659b-48a0-86dc-01678ff629c2', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why is ''Ember Object'' being phased out in favor of native JavaScript classes?', N'Middle', N'Native JavaScript classes are a standard language feature that offers better performance, improved tooling support, and easier debugging compared to the custom Ember Object system. Moving to native classes aligns Ember with modern web standards and reduces the framework-specific learning curve.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7742b9a6-4791-4703-a61d-016a8f11e1a3', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are the performance implications of using dynamic types versus static types?', N'Senior', N'Static types allow the compiler to perform type inference and generate optimized machine code with direct memory access. Dynamic types, conversely, force the runtime to perform lookups in method tables and check types at runtime, which incurs a significant overhead and prevents many compiler-level optimizations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d4d2a2f-c2b7-492e-885e-0174e1587ab8', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the ''partial'' keyword?', N'Intern', N'The partial keyword allows the definition of a class, struct, or method to be split across multiple files. This is useful for separating auto-generated code from manual code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc57ee8a-9af5-43da-9ece-0178ed6666dc', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Describe the benefit of Litestar''s ''Plugin'' system for backend architecture.', N'Senior', N'The plugin system allows for the seamless integration of third-party libraries like SQLAlchemy or Tortoise ORM into the application lifecycle. This standardizes how external resources are initialized and shut down, reducing boilerplate code and ensuring consistent configuration across different modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49057f83-c500-49f6-b5fc-017907d4f306', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does scope hoisting improve application performance?', N'Senior', N'Scope hoisting, also known as module concatenation, merges modules into a single closure rather than wrapping each in an individual function. This reduces the overhead of module wrappers and allows the JavaScript engine to perform better inline optimizations, resulting in smaller, faster-executing bundles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad723f74-eee6-4e72-86e7-0179180124c9', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does database indexing impact write scalability?', N'Middle', N'While indexing significantly improves read performance, every index requires an update during a write operation. Excessive indexing can slow down write throughput, making it a critical trade-off to manage when optimizing a write-heavy database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a77b234-60ef-483f-a4ab-0179234a61d0', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is ''reverting a deployment'' sometimes better than ''patching in production''?', N'Junior', N'Reverting immediately restores the application to a known stable state, minimizing downtime for users. Patching directly in production is risky because it often involves rushing a fix without full testing, which can lead to new, more severe bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'116bdf54-a5e6-421e-9a2e-017baf93e58d', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the role of the ''Sync'' and ''Send'' traits in sharing state across Rocket handlers?', N'Senior', N'These marker traits define whether a type can be safely shared or transferred between threads. Since Rocket operates in a multi-threaded asynchronous environment, any state managed by the framework must implement these traits to ensure thread safety and prevent data races.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c7f7df7-e6b7-4d44-82ee-01827643e172', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the architectural considerations for ''Error Boundaries'' and global error handling?', N'Senior', N'Global error handling is necessary for logging and reporting, but it cannot always recover state after a catastrophic failure in an asynchronous flow. Architects should design systems with graceful degradation, ensuring that independent modules can fail without crashing the entire execution context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
