INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eba21530-db25-409d-8ea1-0182c9c673c8', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis perform compared to a traditional relational database?', N'Junior', N'Redis is significantly faster for simple data access patterns because it operates entirely in RAM and lacks the overhead of SQL parsing and disk I/O. However, relational databases are better suited for complex queries, data integrity, and large-scale persistent storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7246e7e-c98e-4213-81e4-01842492ccb5', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack''s dependency graph construction differ from a simple file concatenation approach?', N'Senior', N'Webpack parses source files to identify import/require statements, creating a directed acyclic graph of dependencies. This allows it to perform tree shaking, dead code elimination, and granular code splitting, which is impossible with simple concatenation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ede513c4-134c-409f-9985-0186bf945c6c', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the impact of using Preact on SEO for server-side rendered applications?', N'Middle', N'Preact''s small size and fast rendering capabilities improve the performance metrics that search engines use for ranking, such as Core Web Vitals. Since Preact supports server-side rendering, it delivers fully rendered HTML to crawlers efficiently, ensuring good SEO performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48fab811-91ce-4814-977b-0187f3407f04', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Error Handling work in Swift?', N'Fresher', N'Swift uses the throwing, catching, and propagating of errors using the ''do-try-catch'' pattern. When a function encounters an issue, it throws an error that the caller must handle to ensure the program can recover gracefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'838ed10d-de03-477c-bbd5-018a60e4aa06', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of Read Repair in Cassandra?', N'Middle', N'Read Repair is a consistency mechanism that triggers during a read operation if the coordinator detects that different replicas have conflicting data. It updates out-of-date replicas to match the most recent version, helping maintain data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0eac7e5-9dc7-4668-9e9b-018d6b6254aa', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Why are top-level functions and variables discouraged in large Dart projects?', N'Middle', N'Over-reliance on top-level members can lead to namespace pollution and hidden dependencies, making code harder to test and maintain. Encapsulating logic within classes or libraries promotes better modularity, easier dependency injection, and clearer ownership of state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36261026-725a-4e9d-8893-018d780f9ee5', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is ''Backpressure'' in the context of asynchronous stream processing?', N'Senior', N'Backpressure is a feedback mechanism where a consumer signals to the producer that it is being overwhelmed by the rate of incoming data. This allows the producer to slow down or buffer data, preventing system crashes caused by resource exhaustion in the downstream components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
