INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f4e6257-c44a-4030-acb6-01a217e51219', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'When would you choose to use the @apply directive in Tailwind, and what are the potential downsides?', N'Middle', N'The @apply directive is useful for extracting common utility patterns into custom CSS classes to keep HTML clean or to integrate with legacy components. The downside is that it can lead to ''CSS bloat'' if overused, as it forces the browser to interpret more complex rules, and it can negate the benefits of Tailwind''s utility-first approach by making it harder to track which utilities are being applied to a specific element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
