INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c55a9ea-c36e-41cd-ad8d-01a786c3e618', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber manage request timeouts?', N'Fresher', N'Fiber allows developers to configure timeouts on the server level to prevent slow requests from hanging resources indefinitely. This ensures the server remains responsive even under heavy load or malicious traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d80a6fe-91c6-4d37-9341-01a9640aac29', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How do access control levels like ''fileprivate'' and ''private'' differ?', N'Middle', N'Private limits access to the enclosing declaration, while fileprivate limits access to the entire source file. These levels help encapsulate implementation details, reducing the API surface area and preventing external modules or files from relying on internal logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd113b79b-daa2-499e-b035-01add05b181a', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How do circuit breakers improve the reliability of a distributed system?', N'Senior', N'Circuit breakers prevent a system from repeatedly trying to execute an operation that is likely to fail, such as a request to a down service. By failing fast, they allow the upstream service to remain responsive and provide the failing service time to recover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef545810-cedf-41cb-b61d-01ae3ee514f5', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''unknown'' type and how does it differ from ''any''?', N'Intern', N'The ''unknown'' type is the type-safe counterpart to ''any''. While both can hold any value, you must perform type checking or narrowing before you can perform operations on an ''unknown'' variable, whereas ''any'' allows any operation without checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb91add6-49c9-4977-9b87-01aeae587b80', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of ''use strict''?', N'Junior', N'''use strict'' is a directive that enables a stricter mode of parsing and error handling in JavaScript. It prevents the use of undeclared variables, throws errors for silent failures, and disables some features that are considered error-prone.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67b4eb21-5be7-4842-bf5a-01aebb573893', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is a Phoenix Generator?', N'Fresher', N'Generators are built-in tools that automatically create boilerplate code for common tasks like creating models, controllers, and views. They help scaffold the initial structure of a feature to save development time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e1673d1-8ddb-4ec4-b649-01b0e3387edb', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is lambda? What are Lambda Functions ?', N'Intern', N'A function which doesn''t contain any name is known as a anonymous function lambda function, Lambda function we can assign to the variable & we can call the lambda function through the variable. Syntax: Lambda arguments:expression It is a single expression anonymous function often used as inline function. A lambda form in python does not have statements as it is used to make new function object and then return them at runtime. The lambda operator is used to create anonymous functions. It is mostly used in cases where one wishes to pass functions as parameters. or assign them to variable names. When we want a function with a single expression, we can define it anonymously. A lambda expression may take input and returns a value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60152785-09b8-4734-b659-01b197b1d718', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is Next.js and why is it used?', N'Intern', N'Next.js is a React framework that enables features like server-side rendering and static site generation. It is used to build fast, user-friendly web applications by providing a structured development environment and built-in optimizations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6466b386-32d7-40ec-8297-01b7e8053734', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does the Swift compiler utilize ''Whole Module Optimization'' (WMO)?', N'Senior', N'WMO allows the compiler to analyze the entire module at once, rather than compiling files individually. This enables cross-file inlining, function specialization, and the removal of unused code across the entire module boundary. This results in significantly faster and more optimized binaries, though it increases total compilation time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b78c1c16-f110-498f-a513-01b808873e07', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the primary goal of the Rust programming language?', N'Intern', N'The primary goal of Rust is to provide memory safety and high performance without the need for a garbage collector. It achieves this by enforcing strict rules at compile time that prevent common bugs like null pointer dereferences and data races.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3d3d247-0d29-4780-b1cd-01b834206e11', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro maintain global state across different framework components (e.g., React and Vue)?', N'Senior', N'Astro does not provide a built-in cross-framework state manager. For complex state requirements, developers must use external primitives like Nano Stores, which are framework-agnostic, or standard browser APIs like Custom Events or localStorage to synchronize data between disparate component islands.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'067491e0-3f99-4e8c-98b7-01b98d2101ae', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Does Actix-web support HTTP/2?', N'Intern', N'Yes, Actix-web has built-in support for HTTP/2. It allows for multiplexing multiple requests over a single connection, which improves performance and latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1e09eff-7b5e-4492-91bf-01bb8644cff1', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain the mechanics and trade-offs of the ''Module#const_missing'' hook.', N'Senior', N'Const_missing is invoked when a constant lookup fails, allowing for dynamic loading of classes or modules. While it enables lazy loading patterns, it can complicate dependency tracking and lead to unexpected behavior if multiple threads attempt to autoload the same constant simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c936529-1b74-4930-8b3e-01bbb38ab96e', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Discuss the trade-offs of using ''Symbols'' versus ''Strings'' as keys in hash maps.', N'Senior', N'Symbols are immutable and globally unique within the VM, meaning they are compared by memory address rather than character sequence, making them faster for lookups. However, symbols are never garbage collected in older Ruby versions, which can lead to memory exhaustion if keys are generated dynamically from user input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb3b020c-8b0f-415f-b3cb-01bbe4b93ea3', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to bind methods or event handlers in JSX callbacks?', N'Fresher', N'There are 3 possible ways to achieve this in class components: 1. Binding in Constructor: In JavaScript classes, the methods are not bound by default. The same rule applies for React event handlers defined as class methods. Normally we bind them in constructor. 2. Public class fields syntax: If you don''t like to use bind approach then _public class fields syntax_ can be used to correctly bind callbacks. The Create React App enables this syntax by default. 3. Arrow functions in callbacks: It is possible to use _arrow functions_ directly in the callbacks. Note: If the callback is passed as prop to child components, those components might do an extra re-rendering. In those cases, it is preferred to go with .bind() or _public class fields syntax_ approach considering performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
