INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46901fca-1d42-4e3c-96d7-01bda32232e0', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using a monolithic repo versus a multi-repo strategy for microservices?', N'Middle', N'A monorepo simplifies dependency management and cross-service refactoring but can lead to long build times and complex CI tooling. Multi-repos provide team autonomy and faster CI cycles, but they make it difficult to manage shared libraries and track cross-service breaking changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cb1d2f1-0987-4c26-a9d8-01bf5425aa79', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does database sharding affect data consistency and querying?', N'Middle', N'Sharding distributes data across multiple servers, which improves horizontal scalability and performance. However, it complicates cross-shard queries and makes maintaining global transactional consistency much more difficult compared to a single-instance database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
