INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'388fafa2-7f4c-489e-8c92-01cc5b6d62ef', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the role of a dead-letter queue in an event-driven architecture?', N'Middle', N'A dead-letter queue captures messages that could not be processed successfully after several retries, preventing them from blocking the main processing stream. It allows developers to inspect failed events and resolve the underlying issues without losing data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b85d104e-446e-4e85-8056-01cd55bb68c5', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of the ''Repository Pattern'' in Laravel, and is it always necessary?', N'Senior', N'The Repository Pattern abstracts the data layer, providing a collection-like interface for accessing domain objects and decoupling the business logic from the ORM. It is not always necessary for small applications, but it becomes valuable in large-scale systems where you need to support multiple data sources or simplify complex testing scenarios by mocking the repository.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a61f99ac-244d-4a31-97f2-01d48ac7009c', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind CSS handle pseudo-classes like hover or focus?', N'Fresher', N'Tailwind handles pseudo-classes by using modifiers prefixed to the utility class. By adding a prefix like hover: or focus: before a class, the style only applies when that specific state is triggered on the element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b81126bb-0083-452a-9915-01d61499d90c', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What strategy should be used to test Axum handlers in isolation?', N'Middle', N'To test handlers in isolation, you should invoke them directly as functions by manually constructing the expected input types. This bypasses the full HTTP server stack, allowing for rapid execution of unit tests without network overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
