INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55cfc2a8-691b-43ba-9258-01d78000f434', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the advantage of Remix''s ''streaming'' capabilities?', N'Middle', N'Streaming allows the server to send the HTML document in chunks as data becomes available, rather than waiting for the slowest data request to finish. This improves the ''Time to First Byte'' and perceived performance, as users can start seeing the page content while remaining data loads in the background.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9815427-8c7e-4e56-8173-01d81143b8fe', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does the Python import system manage module caching and reloads?', N'Senior', N'Python maintains a global dictionary called sys.modules that caches imported modules to ensure each is loaded only once per process. While this improves performance, it makes hot-reloading code complex, as the interpreter must explicitly invalidate cache entries and re-execute module-level code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9d51947-6c11-4a45-a053-01d9c7c48f4c', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of Enums in TypeScript?', N'Junior', N'Enums allow developers to define a set of named constants that make code more readable and easier to maintain. They are particularly useful for representing a group of related values, such as days of the week or status codes, which have a fixed set of possibilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78cf2337-5da2-4783-a204-01daa364ed3d', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are Type Parameters in Scala?', N'Intern', N'Type parameters allow you to create generic classes or methods that can work with any data type. They act as placeholders for the actual types that will be provided when the class or method is used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea1c8e50-afa8-4455-a7c5-01dda821419e', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does C handle structure padding and alignment?', N'Senior', N'C compilers add padding bytes between structure members to satisfy hardware-specific alignment requirements, ensuring that data types are stored at memory addresses that maximize performance. Because padding is implementation-defined, it can lead to binary incompatibility if structures are serialized directly to disk or transmitted over a network.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9ec4b31-6477-4e66-bbd6-01de0a99f08e', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is a scaffold in Rails?', N'Intern', N'A scaffold is a quick way to generate a set of files that provide the basic CRUD functionality for a specific model. It is intended to be a starting point for developers to see how Rails works, though it is usually customized later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f14ffc0a-8fc6-4794-afeb-01de3376f245', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between Middleware and Filters in ASP.NET Core?', N'Fresher', N'Middleware is a component that is executed in every HTTP request and response, forming a pipeline to handle cross-cutting concerns like logging or authentication. Filters, on the other hand, allow you to run code before or after specific stages in the action execution pipeline, such as before a controller action runs or after an exception is thrown.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a9ab20b-a269-42eb-976a-01df36536aaf', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the function of the @Get, @Post, and @Put annotations?', N'Junior', N'These are method-level annotations used in Controllers to map specific HTTP verbs to handler methods. They dictate which HTTP method must be used by the client to trigger that specific piece of server-side code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ff28191-5ebd-422e-bbe5-01dfdd4a8be8', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the purpose of a shard key, and why is its selection critical?', N'Middle', N'A shard key determines how documents are distributed across shards. A poor choice can lead to ''jumbo chunks'' or uneven data distribution, causing hotspots where one shard handles significantly more traffic than others, negating the benefits of scaling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a23e92cb-25e6-4940-9869-01e2f4ddc948', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain the security benefit of ''Data Masking'' at the application tier versus the database tier.', N'Senior', N'Application-tier masking provides granular control based on user context and authorization, protecting data before it reaches the UI. Database-tier masking provides a consistent, centralized enforcement that covers all access methods, ensuring that even privileged database administrators cannot view sensitive information in plaintext.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50bea093-cb93-4ee3-b3b6-01e4dd917184', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Why is testing in production sometimes necessary?', N'Middle', N'Testing in production, such as canary deployments or feature flags, allows for the validation of new code in a real-world environment where it is impossible to perfectly simulate all production traffic patterns. It enables rapid feedback and safer rollouts by exposing changes to a small subset of users first.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
