INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b0b8a19-a59c-4d54-99b2-01f85c4850bc', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What are the trade-offs of using ''nested'' objects compared to ''flattened'' objects in Elasticsearch mappings?', N'Middle', N'Nested objects allow arrays of objects to be indexed as separate hidden documents, enabling independent querying of sub-fields while maintaining the relationship between them. However, this increases index size and complexity, whereas flattened or object types merge data into a single document structure, which is more performant but loses the ability to query specific object relationships accurately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
