INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b898e27e-f7ae-48e0-ac93-0208b78c33da', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Mention what is the difference between Django, Pyramid, and Flask?', N'Fresher', N'Flask is a "microframework" primarily build for a small application with simpler requirements. In flask, you have to use external libraries. Flask is ready to use. Pyramid are build for larger applications. It provides flexibility and lets the developer use the right tools for their project. The developer can choose the database, URL structure, templating style and more. Pyramid is heavy configurable. Like Pyramid, Django can also used for larger applications. It includes an ORM. - You are having multiple Memcache servers running Python, in which one of the memcacher server fails, and it has your data, will it ever try to get key data from that one failed server?', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ba2f317-ed8a-46aa-8257-020e97d2d8dc', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the primary purpose of the C preprocessor?', N'Intern', N'The preprocessor is a text substitution tool that runs before the actual compilation begins. It handles directives like file inclusion and macro definitions to prepare the source code for the compiler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'003b60eb-3d20-4550-891d-020fafeaedeb', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a foreign key constraint?', N'Intern', N'A foreign key constraint ensures referential integrity by preventing actions that would destroy links between tables. It ensures that a value in the foreign key column must exist in the referenced primary key column.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1a4897b-8acb-4cd5-adec-021026090262', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of the ''async'' and ''await'' keywords in FastAPI?', N'Fresher', N'These keywords are used to perform asynchronous programming, allowing the server to handle multiple requests concurrently without blocking the execution thread. This is particularly useful for I/O-bound operations like database queries or calling external APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0705c479-8523-4591-9f28-0211c7bfe2e5', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Does the browser understand Sass files directly?', N'Junior', N'No, browsers only understand standard CSS files. Sass files must be compiled or transpiled into valid CSS before they can be correctly interpreted and applied by a web browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b78730b2-5521-450d-a34f-02178a6295a2', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why is the virtual DOM not used in Svelte?', N'Junior', N'The virtual DOM adds overhead because it requires comparing the current state to the previous state at runtime. Svelte avoids this by knowing exactly which parts of the DOM need to change during the build process, generating direct DOM manipulation code instead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6c7b931-6454-4e5e-8dad-021b627a0eea', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Explain one-way data flow of React and its benefits', N'Fresher', N'In React, one-way data flow means that data moves in a single direction: from parent components down to child components via props. Children cannot mutate the props they receive; to change parent state, a child invokes a callback the parent passed in. This contrasts with two-way binding (e.g. Angular or Vue''s v-model), where view and model stay in sync automatically. The main benefits are predictable state changes, easier debugging, and patterns like controlled components, immutable updates, and time-travel debugging that fall out naturally from the constraint. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f28fedd6-37ec-4784-97ab-021b699bce15', N'a2838158-7305-480a-b22b-4dc35776b400', N'Explain the trade-offs between linearizability and serializability in distributed databases.', N'Senior', N'Linearizability is a safety guarantee for individual operations, ensuring that once a write completes, all subsequent reads see that value. Serializability is an isolation property for transactions, requiring that the outcome of concurrent transactions is equivalent to some sequential execution order. Linearizability is about real-time constraints, while serializability is about the consistency of multi-step operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78e0ec47-1637-49af-b10f-021dc2467632', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the role of a Service Mesh in managing traffic?', N'Middle', N'A service mesh, like Istio or Linkerd, provides a dedicated infrastructure layer for managing service-to-service communication. It handles traffic routing, load balancing, retries, and security (mTLS) transparently, removing this complexity from the application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cdf2a98-c0f9-4be1-a026-021e69adcd9f', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do you mitigate N+1 query issues in Rails when dealing with deeply nested associations?', N'Senior', N'Use the includes or preload methods to eager load associations. For complex cases involving nested depth, use the nested hash syntax or join queries to fetch associated records in a single database round trip.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
