INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f328470-ae07-4bfd-ad07-0236fcd8929b', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of ''Read Repair'' in Cassandra, and how does it contribute to consistency?', N'Middle', N'Read Repair is an internal process where the coordinator node compares data versions across replicas during a read request. If it detects inconsistencies or stale data, it updates the out-of-date replicas to match the most recent version, helping to maintain data integrity across the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
