INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10294871-7045-407c-b2f3-0241c57083b2', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is a Symfony Environment?', N'Intern', N'An environment represents the state of the application, such as ''dev'', ''prod'', or ''test''. Each environment allows for different configurations, such as enabling debugging tools in development or optimizing performance in production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ee32ef6-c197-42a8-babe-0241f33ae869', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the trade-offs of using off-heap memory via ByteBuffer or Unsafe in high-throughput Java applications?', N'Senior', N'Using off-heap memory bypasses the Garbage Collector, significantly reducing GC pauses and improving latency for large data caches. However, it shifts the burden of memory management to the developer, introduces risks of memory leaks, and complicates debugging as these regions are not visible to standard profiling tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2823ac3f-c10f-4674-89ae-0242a684ddb9', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are lifecycle hooks in Nuxt?', N'Fresher', N'Lifecycle hooks are specific points in the application''s execution process where you can run custom logic. In Nuxt, these allow you to perform tasks like fetching data or setting up configurations at specific stages, such as when the server starts or when a component is mounted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50bb2d38-4a3a-4f4e-ae74-024523da08e8', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a transaction in MySQL?', N'Intern', N'A transaction is a sequence of one or more operations executed as a single logical unit of work. Transactions ensure that either all operations are completed successfully or none of them are, maintaining database consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b0e283e-293f-4042-bc09-0248b4907239', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is a rest parameter route in SvelteKit?', N'Junior', N'A rest parameter route uses a special syntax, like [...rest], to match any number of URL segments. This is useful for building catch-all routes or complex directory structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b79cfa97-d8b8-4e87-ab96-0249569e2e9b', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'When would you choose gRPC over REST for service-to-service communication?', N'Senior', N'Choose gRPC for high-performance, low-latency internal communication where strict schema definition and binary serialization are beneficial. REST is generally preferred for public-facing APIs due to its broad ecosystem support, ease of debugging, and universal compatibility with web browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e0204b6-79fa-4283-917a-02497ab7a618', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the purpose of a health check endpoint in a load-balanced environment?', N'Middle', N'A health check endpoint allows a load balancer to verify if an application instance is capable of processing requests. If the instance fails the health check, the load balancer stops routing traffic to it, ensuring that users are only directed to healthy and responsive servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a134aa8-3a52-4e3a-b79d-02498c08f923', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is an Exception Filter?', N'Fresher', N'An Exception Filter is a type of filter that catches unhandled exceptions that occur during the execution of an action or controller. It is used to implement global or controller-level error handling policies, such as logging the error and returning a generic error response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d467caa-9ecd-441e-b041-024d6c4c4b50', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does the libuv thread pool handle asynchronous I/O, and what are its limitations?', N'Senior', N'Libuv manages a default pool of four threads for blocking operations like file system I/O, DNS lookups, and crypto functions. Because this pool is shared across the entire Node.js process, a high volume of blocking operations can starve the pool, delaying other tasks. Tuning the UV_THREADPOOL_SIZE environment variable is necessary for I/O-heavy applications to avoid thread starvation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38ce34bd-2e97-4986-a892-024ed9469c2f', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is header manipulation in Fiber potentially more performant than in standard Go frameworks?', N'Senior', N'Fiber accesses headers through a direct lookup in a reusable header map rather than parsing the entire request object. This avoids the overhead of allocating new maps for every request, which is a common source of latency in high-traffic APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9b5d442-04fb-471a-931b-024ed96b1539', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does C handle memory alignment, and why is it critical for performance on RISC architectures?', N'Senior', N'C uses alignment requirements to ensure data structures map optimally to hardware cache lines and word boundaries. On RISC architectures, unaligned access often triggers hardware exceptions or requires multiple bus cycles to fetch data, leading to significant performance penalties compared to naturally aligned accesses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a72b0f01-3206-480f-a61f-0250816fc50a', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Can you explain what ''extension methods'' are in Dart?', N'Fresher', N'Extension methods allow you to add new functionality to existing libraries or types without modifying their source code. They provide a way to add utility methods to types you do not own.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6d14366-838c-40b9-a080-02516f48cacb', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it important to validate user input on both the client side and the server side?', N'Fresher', N'Client-side validation improves user experience by providing immediate feedback, while server-side validation is mandatory for security. Relying only on client-side checks is dangerous because malicious users can bypass them to inject harmful data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'234f9d21-79f2-4993-92ea-02582a5e2305', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the role of ''phantom types'' in ensuring domain-level correctness.', N'Senior', N'Phantom types are type parameters that have no value representation at runtime but act as compile-time tags. They are used to enforce state-machine logic or domain constraints, such as ensuring a method only accepts a ''validated'' user object, thereby catching logic errors during the compilation phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa0ea91e-ddfb-453d-8176-0258b3db5448', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When choosing a programming language for a new project, what is the trade-off between performance and developer productivity?', N'Junior', N'Lower-level languages offer fine-grained control and high performance, but require more development time and manual memory management. Higher-level languages prioritize developer productivity and ease of maintenance, but may have higher runtime overhead or less efficient memory usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
