INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf04f15a-8864-4afa-ad01-02635e9f2adf', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What happens when a node leaves the cluster?', N'Intern', N'If a node leaves the cluster, the master node detects the failure and re-allocates any missing primary shards from their replicas. The cluster status may briefly turn yellow or red until the data is rebalanced.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd75c80c-782e-44dc-b6c3-02643eb63ee7', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Describe the two-phase commit (2PC) protocol and its primary architectural drawback.', N'Senior', N'The two-phase commit protocol uses a coordinator to ensure all participating nodes either commit or abort a distributed transaction. Its primary drawback is that it is a blocking protocol; if the coordinator fails during the commit phase, participants remain locked, holding resources indefinitely until the coordinator recovers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5fcd006-4692-4e51-b040-026598816fb6', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How do you handle ''Hot Keys'' in a large-scale Redis deployment?', N'Senior', N'Hot keys occur when a single key receives a disproportionate amount of traffic, potentially overwhelming a specific shard. Strategies to address this include implementing local caching, spreading the load via read-only replicas, or redesigning the key schema to distribute the data more evenly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d2b8da8-ed08-4267-8a9a-0266a64d3384', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What does it mean for Preact to be a ''virtual DOM'' library?', N'Fresher', N'Like React, Preact uses a virtual DOM to optimize UI updates. It maintains a lightweight copy of the real DOM in memory and only updates the specific parts of the real DOM that have changed, which improves rendering performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
