INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ce4388c-7f79-4da4-a2f9-027739c422b0', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What are the trade-offs of using ''SyncArbiter'' in an Actix application?', N'Senior', N'SyncArbiter allows executing blocking operations by offloading them to a pool of dedicated threads. While this prevents blocking the main event loop, it introduces risks of thread starvation and necessitates careful management of resource contention and pool sizing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d50e6cf-0544-46f0-b505-0277c2be6a5a', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are the advantages of using a PSR-compliant autoloader?', N'Middle', N'A PSR-compliant autoloader eliminates the need for manual file inclusion, improving performance and developer efficiency. It maps class names to file paths based on a standardized convention, which allows frameworks to work seamlessly together. This prevents namespace collisions and ensures code structure is predictable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40644681-6d84-4ce6-95c8-0277dbe934a3', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the difference between Imperative and Reactive programming in Quarkus?', N'Fresher', N'Imperative programming uses a traditional thread-per-request model, which is easier to write but can be blocking. Reactive programming in Quarkus uses non-blocking I/O, allowing a small number of threads to handle a large volume of concurrent requests, which improves resource efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7576436f-e2ea-4b3d-a062-027b4f9c6591', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django’s database transaction management handle atomicity in a request-response cycle?', N'Senior', N'Django uses the ATOMIC_REQUESTS setting to wrap every view function in a database transaction. If the view finishes successfully, the transaction is committed; otherwise, it is rolled back, ensuring data consistency even if an exception occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1dc36632-ade0-4db4-9ca8-027ce4f040af', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What does ''auto-imports'' mean in Nuxt?', N'Intern', N'Auto-imports is a feature where Nuxt automatically detects the use of Vue functions, components, and utilities, importing them for you behind the scenes. This reduces the need for boilerplate code and keeps your files cleaner by removing manual import statements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fc50ba7-0a02-4d70-b2b4-027d0ee41f3f', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the primary benefit of Remix''s approach to ''progressive enhancement''?', N'Middle', N'Progressive enhancement ensures that the core functionality of the application works even in restricted environments, such as browsers with JavaScript disabled or slow network conditions. It allows developers to build robust applications that improve as network and browser capabilities allow, rather than relying solely on JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cca4546-3d95-47b9-85ea-027d22fc008d', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How do you implement error handling across the Actix-web middleware chain?', N'Senior', N'Error handling is implemented by mapping custom error types to HTTP responses within the middleware or by utilizing a centralized error handler that implements the ''ResponseError'' trait. This allows consistent translation of internal application failures into meaningful client-facing status codes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'849ffe14-147e-4013-aa76-027d53787885', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the advantages and disadvantages of using templates?', N'Middle', N'Templates provide powerful generic programming capabilities and allow for type-safe, performant code that avoids the overhead of virtual functions. The main disadvantages are significantly increased compilation times and the potential for ''code bloat'' due to the generation of multiple specialized versions of the same template.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e197ddb1-89ea-469f-bfce-027ef7b92f6f', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is vertical scaling?', N'Fresher', N'Vertical scaling, or scaling up, involves increasing the capacity of a single server by adding more CPU, RAM, or storage. This is the traditional approach used by most relational databases, which often have physical limits to how much they can be upgraded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'561cf169-133d-48c1-b9dc-02809f6be846', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is the use of ''goto'' generally discouraged, even if allowed in C?', N'Middle', N'The ''goto'' statement creates non-linear control flow that is difficult to trace, often leading to ''spaghetti code'' that is hard to maintain and test. Modern structured programming constructs like loops and functions achieve the same results with clearer readability and predictable scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
