INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd360433-7b7d-487c-9389-028fe947a732', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of Django''s ''select_related'' and ''prefetch_related'', and how do they differ?', N'Senior', N'select_related performs a SQL join to retrieve related objects in a single query, which is limited to single-valued relationships like ForeignKey. prefetch_related performs a separate lookup for each relationship and joins them in Python, which is necessary for many-to-many or reverse foreign key relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4992f86e-a549-4b7d-a644-02901249c296', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the role of the ''Buffer'' class in Node.js, and how does it differ from ''Uint8Array''?', N'Senior', N'Buffers are used to handle binary data outside the V8 heap, allowing Node.js to perform efficient I/O operations. While Buffers are a subclass of Uint8Array, they provide additional utility methods for encoding and decoding strings. Using Buffers is essential for high-performance network and file system operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
