INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5059e54d-e5aa-4315-9698-02912b06127c', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the risks of over-normalizing a database?', N'Middle', N'Over-normalizing can lead to excessive table fragmentation, requiring complex and numerous joins to reconstruct data for read queries. This can significantly degrade performance and increase query latency, making it harder to retrieve data efficiently compared to a slightly more denormalized model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a68f07f6-33c0-4ee2-b0a4-02922ae38a49', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Discuss how tokens are used for authorization in an API. What is the difference between authentication and authorization, and how are these processes implemented with tokens?', N'Fresher', N'Tokens, such as JWTs (JSON Web Tokens), are used for authorization in APIs to ensure that a user has permission to access certain resources or perform certain actions. Authentication is the process of verifying the identity of a user. When a user logs in with their credentials, the server verifies these credentials and if they are valid, the server generates a token. This token often contains information about the user and is sent back to the client. Authorization on the other hand, is the process of verifying what a user has access to. Once a user is authenticated and their token is sent with each request, the server can verify the token and check if the user has the necessary permissions to perform the requested action. Here''s a basic process: 1.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cc18b16-3846-4e34-9667-02931916d315', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the significance of the ''this'' parameter in function signatures?', N'Senior', N'The ''this'' parameter is a virtual parameter that defines the expected context of a function invocation. It allows developers to enforce the correct usage of object methods in callbacks, preventing errors where the ''this'' context is lost or incorrectly bound.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'653a9736-2cf5-4035-ba2a-0293771c1c01', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does vertical scaling differ from horizontal scaling?', N'Junior', N'Vertical scaling involves adding more power, such as CPU or RAM, to an existing database server. Horizontal scaling involves adding more database nodes to distribute the load across multiple machines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bccbc5c-90c8-4126-a8f4-0296900eba47', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the differences between useEffect and useLayoutEffect hooks?', N'Intern', N'useEffect and useLayoutEffect are both React hooks that can be used to synchronize a component with an external system, such as a browser API or a third-party library. However, there are some key differences between the two: - Timing: useEffect runs after the browser has finished painting, while useLayoutEffect runs synchronously before the browser paints. This means that useLayoutEffect can be used to measure and update layout in a way that feels more synchronous to the user. - Browser Paint: useEffect allows browser to paint the changes before running the effect, hence it may cause some visual flicker. useLayoutEffect synchronously runs the effect before browser paints and hence it will avoid visual flicker.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'722689ee-eb98-4fad-89f8-029af1d42676', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What are the architectural benefits of using Astro’s ''Middleware'' for authentication and request transformation?', N'Senior', N'Middleware in Astro allows for centralized request processing before a page is rendered. This is ideal for injecting user data into the request context or performing global redirects, ensuring consistent security and routing logic across both static and server-rendered routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f5ff254-0067-4f5d-a95c-029b4349e844', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'When is it appropriate to use Express as a ''BFF'' (Backend for Frontend) layer?', N'Senior', N'Express is ideal for a BFF layer when you need to aggregate data from multiple microservices and transform it into a format optimized for a specific frontend client. It provides a lightweight, flexible way to manage view-specific logic without bloating the core backend services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddb6eede-f2f4-4f09-a6fc-029b52ed4ba2', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does cache partitioning (sharding) improve system scalability?', N'Middle', N'Partitioning distributes cache data across multiple nodes based on a key hash, preventing any single cache instance from becoming a bottleneck. This allows the system to scale horizontally by adding more nodes to handle increased memory capacity and throughput demands.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'238a8bb1-bc46-4070-9efb-029bcab71fb1', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is the use of ''alloca'' generally discouraged in embedded or large-scale systems?', N'Senior', N'Alloca allocates memory on the stack, which is non-portable and can lead to stack overflow crashes that are difficult to debug. Because stack space is typically limited and fixed, dynamic stack allocation creates unpredictable runtime behavior compared to heap-based allocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e845a3ee-7393-45ba-8fbd-029d4e2ee61b', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are Ruby iterators and how do they work?', N'Intern', N'When it comes to Ruby, iterators allow for easy, streamlined data manipulation. Whether you''re working with arrays, ranges, or other data structures, iterators help you efficiently apply operations to each element without needing to manage loop counters. Most Common Ruby Iterators - Each: The most basic iterator, it goes through each element. - Each with index: Similar to each, but it also gives the index of the current element. Code Example: Each & Each with Index Here is the Ruby code: Common Usage - Each Char: Often used with strings, this iterator loops through each character. - Each Line: Handy for reading files, it processes lines one at a time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37881771-1aff-4ebf-8ac1-029d99464c9e', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the difference between ''source()'' and ''library()'' when loading code?', N'Middle', N'The source function executes a script file directly in the current environment, whereas library attaches a pre-compiled, namespaced package to the search path. Library is the standard way to distribute and manage dependencies, while source is typically used for local development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df7c8e0c-4d16-4473-9c79-029e7e47c0e6', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why does the JavaScript runtime prefer ''monomorphic'' over ''polymorphic'' code paths?', N'Senior', N'Monomorphic code paths interact with a single hidden class, allowing the engine to generate highly efficient machine code. Polymorphic paths must check against multiple hidden classes, forcing the engine to use slower, generalized lookup mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1ddef60-81e7-4dea-a607-02a1c4deee37', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What are the risks of over-engineering a solution?', N'Fresher', N'Over-engineering adds unnecessary complexity, making the system harder to understand, maintain, and extend. It also wastes valuable development time on features or abstractions that may never be needed by the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3659107-39e9-4a2e-a41d-02a258147085', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of the @RequestBody annotation?', N'Junior', N'The @RequestBody annotation is used in controller methods to indicate that the method parameter should be bound to the body of the incoming HTTP request. It automatically triggers the conversion of the request body, usually JSON, into a Java object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ecdbf8d-2eb4-42d2-9493-02a5f11532b5', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the primary difference between BASE and ACID properties in database systems?', N'Middle', N'ACID focuses on immediate consistency and reliability, making it suitable for transactional integrity. BASE prioritizes availability and partition tolerance, accepting eventual consistency, which is more common in distributed NoSQL systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f27b048-fa03-4e91-bf9c-02a7f56a130e', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between app.Use and app.Run?', N'Fresher', N'app.Use adds a middleware component to the request pipeline and potentially calls the next component. app.Run is used to add a terminal middleware that does not call the next component, effectively ending the request pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f0ebd7f-0856-44c8-bd47-02aa01a8c81f', N'954a0331-deff-4399-b588-96f39fec001d', N'How to transfer components to custom elements?', N'Fresher', N'Transforming components to custom elements involves two major steps, 1. Build custom element class: Angular provides the createCustomElement() function for converting an Angular component (along with its dependencies) to a custom element. The conversion process implements NgElementConstructor interface, and creates a constructor class which is used to produce a self-bootstrapping instance of Angular component. 2. Register element class with browser: It uses customElements.define() JS function, to register the configured constructor and its associated custom-element tag with the browser''s CustomElementRegistry. When the browser encounters the tag for the registered element, it uses the constructor to create a custom-element instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'537f3e00-75fe-45a2-8a54-02af17d9220c', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the difference between an Astro component and a framework component like React?', N'Intern', N'Astro components are stripped of JavaScript after the build, while framework components maintain their JavaScript runtime in the browser. Astro components are meant for static structure, while framework components are meant for complex interactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f512361c-5720-4d46-8aa2-02af39bd5922', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does ''Bulkheading'' increase the resilience of a distributed system?', N'Senior', N'Bulkheading isolates resources—such as thread pools or memory—for different services or request types so that a failure in one area does not consume all resources for the entire system. This prevents cascading failures by ensuring that critical operations remain functional even under heavy load or partial outages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0629f7ef-8237-4ba7-becc-02afec8098e2', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the difference between vulnerability scanning and penetration testing?', N'Middle', N'Vulnerability scanning is an automated, high-level process to identify known security weaknesses in a system. Penetration testing is a manual, in-depth exercise where professionals simulate real-world attacks to exploit vulnerabilities and evaluate the system''s defenses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f787cc4d-a2c0-4a06-adf4-02b06de1251c', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the difference between synchronous and asynchronous code execution in Express middleware?', N'Junior', N'Synchronous code blocks the event loop, preventing the server from handling other requests until the operation finishes. Asynchronous code allows the server to continue handling other requests while waiting for tasks like database queries or file I/O to complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e313d65-ed25-4672-bfb5-02b1f1d7e0c1', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the purpose of the Java Development Kit (JDK)?', N'Intern', N'The JDK is a software development environment used for developing Java applications. It includes the Java Runtime Environment, the compiler, and other tools like debuggers and documentation generators.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fac937f-7498-4b87-a7b7-02b337a8a6b3', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do you access the value of a store in a Svelte component?', N'Fresher', N'You can access the value of a store by prefixing the store name with a dollar sign. This automatically subscribes the component to the store and unsubscribes when the component is destroyed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a767f633-e6fa-4da3-a8de-02b49efc05a9', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain CSS Block Formatting Context?', N'Fresher', N'Floats, absolutely positioned elements, block containers (such as inline-blocks, table-cells, and table-captions) that are not block boxes, and block boxes with ''overflow'' other than ''visible'' (except when that value has been propagated to the viewport) establish new block formatting contexts for their contents. In a block formatting context, each box''s left outer edge touches the left edge of the containing block (for right-to-left formatting, right edges touch) A BFC is an HTML box that satisfies at least one of the following conditions: * The value of float is not none. * The value of position is neither static nor relative. * The value of display is table-cell, table-caption, inline-block, flex, or inline-flex. * The value of overflow is not visible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4e94b32-c8a7-42f1-9524-02b5db9c58c2', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do Svelte''s ''slots'' differ from React''s ''children'' pattern in terms of rendering efficiency?', N'Senior', N'Svelte slots are compiled into efficient render functions that pass DOM nodes directly into the child component. Because there is no intermediary abstraction layer, the browser renders the slotted content with minimal overhead compared to the virtual DOM wrapping and reconciliation required by React.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a6fc80f-0025-4c12-ae8d-02b8b01be5f3', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does the complexity of jQuery''s internal state tracking complicate the debugging of asynchronous events?', N'Senior', N'jQuery often hides internal state changes behind abstractions, making it difficult to trace the lifecycle of a DOM element through an event chain. In contrast, modern frameworks provide development tools that allow for explicit monitoring of state changes and component lifecycle hooks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3370f7e6-c5df-481d-8fe2-02b9ea415c80', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of the ''resolve'' configuration?', N'Intern', N'The resolve configuration tells Webpack how to find modules when they are imported. It allows developers to define file extensions to omit or create aliases for easier path imports, making the code cleaner and easier to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'955e5151-4142-4595-9d62-02bbf4d687e3', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When debugging, how do you distinguish between a symptom and the root cause?', N'Junior', N'I look for the underlying logic that leads to the observed error rather than just fixing the surface-level display or error message. I trace the data flow and system state to see where the divergence from expected behavior begins. Addressing the root cause prevents the issue from appearing again in a slightly different form.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3497dcf7-3a30-4c59-b83d-02bd6365fc18', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does the CAP theorem influence the design of a globally distributed metadata store?', N'Senior', N'The CAP theorem forces a choice between consistency and availability during network partitions. In a global store, designers often prioritize availability and partition tolerance (AP), accepting eventual consistency, or use quorum-based consensus algorithms like Paxos or Raft to achieve CP at the cost of higher latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00f546c2-ba5b-4a9e-bf97-02c5186e0f76', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the impact of using database transactions on long-running processes?', N'Senior', N'Holding transactions open for too long in long-running processes can lead to database connection exhaustion and lock contention. It is best practice to keep transactions as short as possible and avoid performing external API calls or heavy computation inside a transaction block to maintain system availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cedcb69-1356-4e29-a3b7-02c6002c597c', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro''s zero-runtime approach impact SEO?', N'Middle', N'Because Astro strips away component logic and delivers pure, semantic HTML to the browser, search engine crawlers can index the page content instantly. This eliminates the need for complex hydration processes that can sometimes cause delays or errors in search engine indexing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fceeff47-a1ae-42a0-a52c-02c84500c89e', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the relationship between TypeScript and JavaScript?', N'Intern', N'TypeScript is a syntactic superset of JavaScript, meaning all valid JavaScript code is also valid TypeScript code. TypeScript code must be compiled or transpiled into standard JavaScript before it can be executed by a browser or runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39fdeb33-d351-4176-b2f1-02ca96be49a9', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the primary purpose of the Django MVT architecture?', N'Fresher', N'MVT stands for Model, View, and Template. It separates the data structure in the Model, the business logic and request handling in the View, and the user interface presentation in the Template to ensure a clean separation of concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6cb89d2-1cef-483c-a8c7-02cf1c84cc47', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a mobile application, how do you decide whether to store data locally on the device or on a remote server?', N'Fresher', N'Local storage is ideal for data that needs to be accessed offline or to reduce latency for frequently used settings. Remote server storage is necessary when data needs to be synchronized across multiple devices or when the data volume exceeds the device''s storage capacity. The choice depends on the specific requirements for data persistence, connectivity, and cross-device availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c721fd54-465c-40fe-8c01-02d1207ce3a3', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are the architectural trade-offs of using the Sass @use rule compared to the legacy @import?', N'Senior', N'@use provides namespacing and private members, preventing global scope pollution and making dependencies explicit. Unlike @import, which concatenates files into a single global scope, @use ensures each module is loaded only once, significantly improving build performance and maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa4c54b2-d0f1-4810-9eb7-02d19f3fe360', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the difference between vertical and horizontal scaling, and when should each be used?', N'Middle', N'Vertical scaling involves increasing the resources of a single server, such as adding more CPU or RAM, which is limited by the hardware ceiling of that machine. Horizontal scaling involves adding more servers to the pool, which is generally preferred for distributed systems as it provides better fault tolerance and nearly limitless scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'847d248f-c0c4-45ed-be1e-02d1cec0e5e8', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum''s extractor system differ from middleware, and when should you use each?', N'Middle', N'Extractors are intended for retrieving specific data from a request, such as parsing JSON bodies or path parameters, and are tightly coupled to individual handler logic. Middleware, by contrast, operates on the entire request-response lifecycle, making it ideal for cross-cutting concerns like authentication, logging, or request tracing that apply to multiple routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6aa41080-fdd9-4042-b191-02d2b34bc8be', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a primary use case for a Key-Value database?', N'Fresher', N'Key-Value databases are commonly used for session management, caching, and shopping carts in web applications. They are extremely fast because they use simple lookups by a unique identifier.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bd4b2d5-497c-4720-badc-02d7e55636ab', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the primary difference between a process-based and a fiber-based concurrency model?', N'Middle', N'Processes are managed by the operating system kernel and have high overhead due to context switching and memory isolation. Fibers are user-mode threads managed by the application runtime, allowing for lightweight, cooperative multitasking with significantly lower overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f71e19c1-1d7b-49fe-b401-02d9a4d8c391', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the primary difference between SQL and NoSQL databases regarding schema?', N'Intern', N'SQL databases require a predefined schema where data must be structured into rows and columns. NoSQL databases are schema-less or have flexible schemas, allowing data to be stored without a strictly defined structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1fb9217-c8fd-46db-b5e2-02da50784853', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are indexes in PostgreSQL and why are they used?', N'Intern', N'Indexes are special lookup tables that the database search engine uses to speed up data retrieval. They allow the database to find rows without scanning every single row in a table, significantly improving query performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6827bff8-dfac-4746-ae41-02ddbde99431', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is a Django view?', N'Intern', N'A view is a Python function or class that takes a web request and returns a web response. It acts as the intermediary between the URL configuration, the model data, and the template, determining what content the user sees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79f1c319-db3e-49ea-b010-02de45bd8812', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between Shallow and Deep copy', N'Fresher', N'There are two ways to copy an object, Shallow Copy: Shallow copy is a bitwise copy of an object. A new object is created that has an exact copy of the values in the original object. If any of the fields of the object are references to other objects, just the reference addresses are copied i.e., only the memory address is copied. Example to create a duplicate if we change some property value in the duplicate one like this: The above statement will also change the name of empDetails, since we have a shallow copy. That means we''re losing the original data as well. Deep copy: A deep copy copies all fields, and makes copies of dynamically allocated memory pointed to by the fields. A deep copy occurs when an object is copied along with the objects to which it refers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0a37d8d-2740-4459-a2d8-02e2458bf799', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the primary architectural difference between Redis and traditional relational databases?', N'Middle', N'Redis is an in-memory, key-value data store that prioritizes extremely low latency and high throughput by keeping all data in RAM. Relational databases typically store data on disk and utilize complex indexing and schema constraints, which makes them better for ACID compliance and complex queries but slower for simple read-heavy operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'caff0aa1-4a90-4cde-b367-02e33762ddeb', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar ensure testability of its dependency injection system?', N'Middle', N'Litestar allows you to override any dependency at the application level during the test setup process. This enables developers to swap real database connections or external API clients with mocks or test-specific instances without modifying the production code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ea07931-1a48-427a-92ff-02e381a12ba8', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'When reviewing a colleague''s work, what should you focus on?', N'Junior', N'I focus on readability, consistency with team coding standards, and potential logical bugs or edge cases that might have been missed. My goal is to provide constructive feedback that improves the quality of the work while maintaining a positive team relationship.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05ecfa67-ec4d-434a-9985-02e5676802d6', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the Event Loop in Node.js and why is it important?', N'Intern', N'The Event Loop is a mechanism that allows Node.js to perform non-blocking I/O operations despite JavaScript being single-threaded. It continuously monitors the call stack and the task queue, executing callbacks only when the stack is empty. This architecture enables the server to handle many concurrent connections efficiently without waiting for each operation to finish.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23c5e6dd-d505-4756-bb5f-02e591d65596', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Are React Hooks available in Preact?', N'Junior', N'Yes, Preact includes a robust implementation of standard React hooks. Developers can use common hooks like useState, useEffect, and useRef to manage state and side effects in functional components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
