INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbbb8022-ccff-4835-a7ac-02e71071cf94', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit ensure performance efficiency?', N'Fresher', N'Lit uses a highly optimized virtual DOM-like approach that updates only the specific parts of the DOM that changed. By minimizing direct DOM manipulations, it reduces the workload on the browser''s layout and paint engines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2e8dd58-710f-4a5d-9801-02e791faa4b1', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the advantages and drawbacks of implementing a custom observer pattern compared to using built-in browser events?', N'Senior', N'Custom observer patterns allow for granular, domain-specific communication between decoupled modules without relying on the DOM tree. However, they require manual lifecycle management to prevent memory leaks, whereas built-in events are handled by the browser and integrated into the standard event propagation flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'beca5653-0d50-4ec8-bcd7-02e8bffb9dc0', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does method dispatch work in Swift, and how does the ''final'' keyword affect it?', N'Middle', N'Swift uses both static dispatch for direct method calls and dynamic dispatch for polymorphic behavior via vtables. The final keyword enforces static dispatch, which allows the compiler to perform optimizations like inlining and reduces the overhead of dynamic lookup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
