INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97026a0c-f9d5-4c29-9cd7-02f2f5b79269', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the primary role of the Axum framework in the Rust ecosystem?', N'Intern', N'Axum is a web application framework designed for building scalable and reliable backend services. It is built on top of the Tokio runtime and the Tower library, providing a high-level API to handle HTTP requests and responses while leveraging Rust''s safety and performance guarantees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23cc2e90-f58c-49fe-8517-02f76d35ba83', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What are the benefits of using Spring Data JPA compared to using raw JDBC?', N'Middle', N'Spring Data JPA abstracts away the boilerplate code required for database interactions, such as opening connections and writing repetitive SQL queries. It provides a powerful repository abstraction that generates queries automatically based on method names and simplifies entity management through object-relational mapping.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e302859-4657-4a7c-b170-02f9d415bcfc', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch handle document updates since segments are immutable?', N'Middle', N'Elasticsearch marks the old document as deleted in a bitset and writes a new version of the document to a new segment. During the merge process, the system physically removes the documents marked as deleted to reclaim space.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f431ab4b-937e-4047-a42f-02fbf8cf5cb4', N'075b8862-431c-4678-9767-f55359758a4a', N'What are recursive components?', N'Intern', N'The Components that can recursively invoke themselves in their own template are known as recursive components. Recursive components are useful for displaying comments on a blog, nested menus, or basically anything where the parent and child are the same, eventhough with different content. Note: Remember that recursive component can lead infinite loops with max stack size exceeded error, so make sure recursive invocation is conditional(for example, v-if directive).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a7d413f-95c2-4165-bfa0-02fce8ee8646', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is shallow copy and deep copy in javascript?', N'Intern', N'1. Shallow Copy: Shallow copy is a bit-wise copy of an object. A new object is created that has an exact copy of the values in the original object. If any of the fields of the object are references to other objects, just the reference addresses are copied i.e., only the memory address is copied. A Shallow copy of the object can be done using object.assign() Example: 2. Deep Copy: A deep copy copies all fields, and makes copies of dynamically allocated memory pointed to by the fields. A deep copy occurs when an object is copied along with the objects to which it refers. A Deep copy of the object can be done using JSON.parse(JSON.stringify(object)) Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'535a0324-3531-4ed6-bc05-0300ced03bc3', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the architectural benefits of using abstract base classes (ABCs)?', N'Senior', N'ABCs enforce a common interface for a group of subclasses, ensuring they implement required methods before instantiation. This promotes rigorous design patterns and allows for type checking via the ''isinstance'' mechanism, improving code reliability in complex systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f88af1ae-dd80-4d87-b750-03036ad81d72', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the ''root'' of a Preact application?', N'Intern', N'The root is the main DOM element where the entire Preact component tree is mounted. Usually, this is an empty ''div'' element in the HTML file that serves as the container for the rendered application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aac18e47-c14d-4d74-ad9a-03064ed8af9a', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the role of the ''Listen'' method in Fiber?', N'Junior', N'The Listen method starts the HTTP server on a specified network address and port. It blocks the main thread, continuously listening for incoming connections and dispatching them to the configured route handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd313ebb9-d864-40c8-a40b-03096b86ca1a', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Explain the concept of ''Rate Limiting'' in ASP.NET Core and why it is a critical defensive architectural pattern.', N'Senior', N'Rate limiting restricts the number of requests a client can make within a time frame, protecting backend services from exhaustion due to spikes or malicious activity. It is a fundamental pattern for maintaining system stability and preventing resource-based denial-of-service attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ce7f4f4-6f1c-41d0-8eb8-030ed4aa7b74', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do mapped types facilitate the creation of immutable utility types?', N'Senior', N'Mapped types allow developers to iterate over the keys of an existing type to transform them, such as applying readonly or optional modifiers. This provides a scalable way to derive variations of models without manually duplicating type definitions as the data structure evolves.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f13984e1-99f2-4e5c-bc41-030edffaf0c4', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the browser support of VueJS?', N'Intern', N'It supports all ECMAScript5 complaint browsers as mentioned in this url. VueJS doesn''t support IE8 browser and below, because it uses ECMAScript 5 features that are un-shimmable(require support from the underlying JS engine) in IE8.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0ba9bc9-d0f4-40f3-b2a1-030f2a82e190', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the purpose of the ''nextTick'' function?', N'Junior', N'The nextTick function schedules a callback to be executed after the next DOM update cycle. It is used when you need to wait for Vue to finish applying data changes and updating the DOM before interacting with elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9da1f752-060b-4eb1-93b3-03105e7c34b0', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What architectural benefit does Chi''s routing tree provide for highly complex APIs?', N'Senior', N'Chi uses a radix tree-based routing structure, which offers O(k) lookup performance where k is the length of the path. This structure scales significantly better than simple linear list iteration when dealing with hundreds of endpoints and deeply nested path parameters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2de839e-7c97-4f40-a83d-031063f56149', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why should you avoid using SELECT * in production?', N'Junior', N'Using SELECT * retrieves all columns from a table, which increases network traffic and memory usage if the table has many or large columns. It also prevents the database from utilizing covering indexes, which could otherwise satisfy the query without reading the actual table rows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbe0b8c9-c4ac-4430-ab1e-0311a62eecdc', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does the ''any'' type represent in TypeScript?', N'Intern', N'The ''any'' type tells the compiler to opt out of type checking for a specific variable. It essentially treats the variable as if it were dynamic JavaScript, which can be useful for migration but sacrifices type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e178574e-66c3-4e8a-90b8-031400422df8', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the difference between the ''preact'' package and the ''preact/compat'' package?', N'Middle', N'The ''preact'' package is the core library containing the essential virtual DOM and component logic, while ''preact/compat'' is an alias layer that provides full API parity with React. Use the core package for minimal projects and the compat layer when integrating existing React-reliant libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7066493-bb75-460f-81b2-031a7674eb58', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Why is that none of my threads are not running? How can I make it work?', N'Fresher', N'As soon as the main thread exits, all threads are killed. Your main thread is running too quickly, giving the threads no time to do any work. A simple fix is to add a sleep to the end of the program that''s long enough for all the threads to finish:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b23c36bc-ef73-4a05-a755-031bcaf22272', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you approach the migration of a large, stateful service from on-premise to a cloud-native Kubernetes environment?', N'Senior', N'I would first containerize the application and use persistent volume claims to handle state, while decoupling the data layer into a managed cloud database service. I would then perform a phased migration using a traffic-splitting strategy to ensure zero downtime during the cutover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb7efb8d-c609-4fd1-8692-031bd4aec64a', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the advantages of a schema-less design in NoSQL?', N'Junior', N'A schema-less design allows developers to store data without needing to perform time-consuming schema migrations or updates. It provides high flexibility, enabling the application to evolve quickly as business requirements change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fbe1363-3ccd-46f8-b1e4-031bee3358c0', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What happens if you use an invalid selector in jQuery?', N'Fresher', N'If you use an invalid or non-existent selector, jQuery will return an empty jQuery object. This means no operations will be performed, but the code will not crash or throw an error, allowing for safer execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92254c35-5d84-4be0-841c-031e6b75a14d', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the difference between dynamic and static routes?', N'Fresher', N'Static routes are predefined paths that do not change, while dynamic routes use bracket syntax in file names to handle variable data. Dynamic routes allow you to create pages for items like specific user profiles or blog posts based on an ID.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'619bfc5a-6450-4e71-9e62-031f1e27a220', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is meant by Atomicity in transactions?', N'Fresher', N'Atomicity ensures that all operations within a transaction are treated as a single ''all or nothing'' unit. If any part of the transaction fails, the entire transaction is aborted and the database remains unchanged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b881552-0d3a-45c0-8368-0321951c0167', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the role of the server directory in Nuxt?', N'Intern', N'The server directory is used to define custom server-side API endpoints or server middleware. It allows you to build a full-stack application by creating backend logic that runs on the server alongside your frontend code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52c4c979-0728-4ec8-b886-03244825e9d3', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the benefit of Axum''s ''ServiceBuilder'' pattern?', N'Senior', N'The ServiceBuilder pattern provides a fluent, ergonomic API for composing complex middleware stacks. It allows developers to order their middleware layers clearly, ensuring that authentication, logging, and rate limiting are executed in the correct sequence before the request reaches the business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07cf12d5-4c0f-4ea4-9baa-03281016da8a', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why might a team choose Tailwind over CSS modules?', N'Junior', N'Tailwind provides a faster workflow by keeping styling logic inside the markup, reducing the context switching between files. CSS modules require creating and naming separate files for every component, which can lead to ''divitis'' and naming fatigue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'920d0007-57fd-4913-81a1-03281bd180aa', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you were asked to estimate how many coffee cups are used in your office building in a single day, what approach would you take to arrive at a reasonable number?', N'Intern', N'I would use a Fermi estimation approach by breaking the problem down into smaller, manageable variables. I would estimate the number of employees, the average number of cups each person drinks per day, and account for external visitors or meetings to reach a logical total.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3b09d32-65e2-4fae-8ebc-032a0e02eb30', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Describe the function of a ''read replica'' and the architectural challenges of using them for scaling.', N'Senior', N'Read replicas offload read-only traffic from the primary instance to improve overall throughput. The primary challenge is replication lag, where the replica might serve stale data, requiring the application to be designed to handle potential inconsistencies during read-after-write scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb509231-28b5-4eac-bcb9-032b570af865', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the role of the ''base'' layer in Tailwind CSS?', N'Senior', N'The base layer is used for global resets and element-level styles, such as normalizing browser defaults or setting global font properties. It ensures a consistent starting point for all projects, preventing browser-specific rendering inconsistencies before utility classes are applied.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f106ce3-8b86-44ed-8c07-032be6a909f3', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel''s internal logging system handle error tracking?', N'Middle', N'Laravel uses the Monolog library to provide a variety of powerful log handlers. It can route logs to files, system logs, or external services like Sentry or Slack, making it easier to monitor application health and debug production issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f5c79fc-59f6-4609-9448-032c11c02011', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik differentiate its reactive system from standard observable-based frameworks?', N'Senior', N'Qwik''s reactivity is integrated with the serialization system, allowing the framework to track dependencies across server and client boundaries. This allows the application to resume its reactive state without needing to re-establish the dependency graph from scratch upon initial load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
