INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d534492-e923-4722-a2c3-032dab5c72e6', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are the performance trade-offs of the AdonisJS template engine (Edge) compared to client-side rendering?', N'Senior', N'Edge provides server-side rendering which improves initial load times and SEO, but it consumes CPU cycles on the server for every render. Client-side rendering offloads the processing to the user''s browser, improving server scalability but potentially increasing the time to interactivity and affecting SEO.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e36b10f-9cf3-4f0b-9abd-033029e8f8b2', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of the break statement in PHP loops?', N'Fresher', N'The break statement is used to immediately terminate the execution of a loop, such as for, while, or foreach. It forces the program to jump to the next statement immediately following the loop block.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
