INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'671ec654-638d-4575-b7b4-0334909e3295', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a stored procedure?', N'Intern', N'A stored procedure is a prepared collection of SQL statements that are saved in the database. They can be reused, accepted as parameters, and executed as a single unit to improve performance and security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7946445f-a5b7-46fe-a876-03363088f4da', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Explain the performance overhead of using jQuery''s selector engine when targeting ID-based selectors.', N'Senior', N'Even when selecting by ID, jQuery still parses the selector string and performs a search within the document tree, whereas native getElementById jumps directly to the node. This overhead is negligible for small sites but adds up significantly in applications with complex, deep DOM structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e51f489-5588-433d-a731-033632d6ea2b', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When designing an API, what are the most important considerations for long-term maintainability?', N'Middle', N'I prioritize clear documentation, consistent naming conventions, and robust versioning strategies such as URI versioning. I also ensure the API is predictable and follows standard HTTP semantics so that consumers can rely on stable, well-defined behaviors over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22cd7ea1-ff04-4639-b0d7-0336624a9ca0', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does ''prefetching'' differ from ''prerendering'' in terms of browser resource management?', N'Senior', N'Prefetching downloads a resource in the background during idle time for future use, resulting in a minimal impact on the current page''s performance. Prerendering, however, involves loading the entire page in a hidden background tab, which is significantly more resource-heavy and should be reserved for high-probability navigation targets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44c81323-4604-46d8-839e-0337a32f14f9', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How do channels facilitate memory synchronization between goroutines?', N'Senior', N'Channels act as a synchronization barrier, ensuring that data sent into the channel is visible to the receiver once the receive operation completes. This happens because the channel implementation internally uses memory barriers to enforce happens-before relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
