INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5959b57c-35bf-4e58-bc55-034af56ad0e0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the ''Temporal Dead Zone'' (TDZ) influence the correctness of variable initialization in complex scopes?', N'Senior', N'The TDZ prevents accessing variables declared with let or const before their definition, enforcing a stricter initialization sequence compared to var hoisting. This architectural choice forces cleaner code structures and prevents silent failures caused by accessing partially initialized or undefined variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24d028bd-affb-4f5b-a458-034b9eaf1fea', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is normalization in SQL?', N'Fresher', N'Normalization is the process of organizing data in a database to reduce redundancy and improve data integrity. It involves dividing large tables into smaller, related tables and defining relationships between them to ensure data is stored logically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0581456b-f5fa-4d4d-b14f-034e3d2e01da', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are the three service lifetimes in ASP.NET Core Dependency Injection?', N'Intern', N'The three lifetimes are Transient, Scoped, and Singleton. Transient services are created every time they are requested, Scoped services are created once per client request, and Singleton services are created the first time they are requested and then reused throughout the application''s lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01036765-ae98-4359-adaa-0352071888ad', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember ensure data consistency across multiple components?', N'Middle', N'Ember achieves data consistency by utilizing a single source of truth within services or the Ember Data store. By following the ''data down, actions up'' pattern, components receive data via arguments and notify parent components of changes via actions, preventing state fragmentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01d8ea6e-b0d3-46b9-9dd5-0352913ea216', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What happens if you create an index on a column with low cardinality?', N'Junior', N'Low cardinality means the column contains very few unique values, such as a gender or boolean flag. Creating an index here is often inefficient because the database optimizer will likely ignore the index and perform a full table scan, as the index does not help narrow down the search enough.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30d7fc04-924b-4656-b798-03533fd12dd6', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the primary architectural goal of the Chi project?', N'Senior', N'The primary goal is to provide a composable, standard-library-compatible router that avoids ''magic'' and framework-specific abstractions. By focusing on idiomatic Go, it allows developers to build high-performance APIs while maintaining full control over the underlying HTTP stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c510f75-8fb3-4a45-ae15-0357784b3753', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Does Hono support standard HTTP methods?', N'Intern', N'Yes, Hono natively supports all standard HTTP methods, including GET, POST, PUT, DELETE, PATCH, and OPTIONS. This allows it to fully implement RESTful API architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0d8caab-1f07-40b6-a1a2-0358b19c9672', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does the ASP.NET Core request/response compression middleware impact server performance?', N'Senior', N'Compression reduces the payload size sent over the network, improving latency for clients on slow connections. However, it increases CPU usage on the server due to the overhead of compressing data on the fly, so it should be used judiciously based on payload size and traffic patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e01bb005-dfb4-4805-821f-035a50da3225', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are higher-order functions in Scala?', N'Intern', N'Higher-order functions are functions that can accept other functions as parameters or return a function as a result. This concept is a core pillar of functional programming and allows for highly reusable and abstract code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7a09f2d-079a-4540-99b2-035c4ac3fd90', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What does !important mean in CSS?', N'Intern', N'It overrides the cascade and gives the style rule the highest precedence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'228cd429-1827-4617-8d5b-03628d832dcf', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the role of ''State'' in an Axum application?', N'Intern', N'State is used to share data across different parts of an Axum application, such as database connection pools or configuration settings. It allows handlers to access common resources without needing to pass them manually through every function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd6667cc-9f9a-4da2-8b9d-0362d2bbc2d7', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How do Merkle Trees assist in the Anti-Entropy Repair process?', N'Senior', N'Merkle Trees are hash-based trees used to efficiently compare data across replicas with minimal network traffic. By exchanging tree hashes, nodes can quickly identify specific ranges of data that differ, isolating only the necessary segments for synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3170d8a1-a93d-4c62-aa0f-0363caf3ed06', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind CSS differ from traditional CSS-in-JS libraries in terms of bundle size and performance?', N'Middle', N'Tailwind generates a static CSS file based on the classes used in your source code, resulting in a consistent and small bundle size that does not grow with the number of components. In contrast, CSS-in-JS libraries often rely on a runtime engine to inject styles, which can introduce performance overhead during component rendering and increase the JavaScript bundle size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd399ed0e-76d6-49d5-ac61-0363ed7a5756', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the ''this'' keyword behave differently in arrow functions compared to standard functions?', N'Middle', N'Standard functions have a dynamic ''this'' context determined by how they are invoked. Arrow functions inherit ''this'' lexically from the surrounding scope where they are defined, making them immune to changes in invocation context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47649239-b131-48bd-b756-0364b3483511', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why is it important to understand the difference between ''include'', ''require'', and their ''_once'' variants?', N'Middle', N'The primary difference lies in error handling and file loading behavior. ''Require'' halts execution if a file is missing, while ''include'' only issues a warning; the ''_once'' variants ensure a file is loaded only once per request, preventing redeclaration errors and reducing redundant file system lookups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f0ba476-4e38-49f8-9947-0365ff933dd3', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between vertical and horizontal sharding?', N'Middle', N'Vertical sharding involves splitting a database by placing different tables or columns onto separate physical servers to reduce load. Horizontal sharding, or partitioning, involves splitting rows of a single table across multiple servers, which helps manage extremely large datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78f8663b-72c7-41ba-9da4-03695006cae3', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Describe the difference between internal and external iteration in the context of the Streams API.', N'Senior', N'External iteration, like traditional for-loops, requires the developer to manage the control flow and state. Internal iteration, used by Streams, delegates the control flow to the library, which allows for better optimization, such as automatic parallelization and lazy evaluation, while simplifying the readability of complex data transformations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab4f3492-a8c1-48b0-b214-036ab8ebac80', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a receiver in a Go method?', N'Junior', N'A receiver is a special parameter defined between the function name and the ''func'' keyword that associates the method with a specific type. It acts similarly to ''this'' or ''self'' in other languages, allowing the method to access the fields of the struct.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'664674a5-5cb7-476d-b600-036b3bafa212', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the scope of variables in R functions?', N'Junior', N'Variables defined inside a function have local scope and are only accessible within that function. If a function tries to access a variable name not defined locally, it will look for it in the global environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25c6dc0c-c256-47f1-823c-036daae33b18', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Is Hono compatible with Node.js?', N'Fresher', N'Yes, while Hono is optimized for edge runtimes, it includes an adapter for Node.js. This allows developers to run Hono applications in traditional server environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a44d99f7-7651-4ef3-9261-036fa885400f', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Can you define multiple middleware for a single route?', N'Fresher', N'Yes, you can pass multiple middleware functions as arguments to a route method. Express will execute them in the order they are provided, provided that each middleware calls the next function to pass control to the next one in the chain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2023bc8c-7ffc-4036-a384-037061410ed7', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between @Configuration and @Component?', N'Middle', N'Both mark classes for component scanning, but @Configuration classes can contain @Bean methods that define how to instantiate complex beans. It essentially tells Spring that the class is a source of bean definitions and allows for more advanced configuration logic than simple component scanning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6dad278c-125f-495e-955e-0370e4c02af7', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What are the trade-offs between using a ''Push'' vs ''Pull'' model for configuration management?', N'Senior', N'A push model allows centralized control and immediate updates but requires complex infrastructure to reach all instances. A pull model is more resilient and scales better because instances manage their own updates, but it may introduce a delay between a configuration change and its application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f15d9029-322e-4c0c-8eb9-037341bb4fa6', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What are the common side effects that middleware addresses?', N'Junior', N'Middleware addresses side effects that shouldn''t happen inside a reducer, such as logging, routing, or making asynchronous API requests. By handling these outside the reducer, you keep your state logic clean and predictable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebb5d5eb-2386-4e78-b694-037376f16a0f', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How do components access data from the Redux store?', N'Junior', N'Components access data using the useSelector hook in modern React-Redux. This hook allows components to subscribe to specific parts of the store state and automatically re-render whenever the selected data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df102c3e-1fe5-4364-b957-0376363184a6', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the ''Module Graph'' in Vite and why is it important?', N'Senior', N'The module graph is an internal representation of the dependency tree that Vite uses to track relationships between files. It is crucial for HMR, as it allows Vite to calculate exactly which modules need to be reloaded when a specific file is modified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee094e04-127a-41fa-b061-037904da3b44', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Why is duck typing important in Python?', N'Middle', N'Duck typing focuses on an object''s behavior—what methods it has and what operations it supports—rather than its specific class hierarchy. This approach promotes polymorphism and loose coupling, as functions can accept any object that implements the required interface. It allows for more flexible code that is easier to extend without modifying existing logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e86b7136-94c9-47ed-9ebf-0379b831881d', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut''s ''Validation'' module work with Bean Validation (JSR 380)?', N'Senior', N'Micronaut validates input data by applying constraints defined on method parameters or request bodies before the logic is executed. By leveraging AOT to generate validation logic, it ensures that invalid requests are rejected early with minimal performance impact, improving the robustness of the API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84a246ec-cf82-497e-ba49-037c079dc4fa', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind simplify the maintenance of a design system?', N'Middle', N'Tailwind centralizes design decisions like colors, typography, and spacing into a single configuration file. This creates a ''single source of truth'' that ensures every developer is using the same design tokens, preventing the drift that often occurs when teams define styles independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17610757-e9bd-4cec-8e1b-037f583f8628', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do you pass data between components in React?', N'Fresher', N'Data Propagation in React (2026) Data propagation in React (v19+) adheres to the core principle of unidirectional data flow. While the fundamentals of Props and Callbacks remain, modern React emphasizes Server Components, Context API, and Signals (or state management libraries) to mitigate "prop drilling." Mechanism 1: Unidirectional Props Props facilitate parent-to-child communication. In React 19, props are now treated as standard stable arguments to component functions, eliminating the need for React.FC wrapper types, which are now largely considered boilerplate. Mechanism 2: Callback Functions Data moves up the tree when children invoke functions passed down as props. These functions typically trigger dispatch actions or state setters (e.g., useState, useActionState).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f60ce99e-fc2b-47e3-89b3-038303bbb01a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the reason to choose the name let as a keyword', N'Intern', N'The keyword let was chosen because it originates from mathematical notation, where "let" is used to introduce new variables (for example, "let x = 5"). This term was adopted by several early programming languages such as Scheme and BASIC, establishing a tradition in computer science. JavaScript follows this convention by using let to declare variables with block scope, providing a modern alternative to var. The choice helps make the language more familiar to programmers coming from other languages and aligns with the mathematical practice of variable assignment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'445065cf-8161-4b70-b55b-0384ddd3cb60', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of the ''any'' type, and why is it generally discouraged?', N'Junior', N'The ''any'' type explicitly tells the compiler to opt out of type checking for a specific variable, effectively treating it as if it were written in plain JavaScript. It is discouraged because it defeats the primary purpose of using TypeScript by allowing type errors to go unnoticed until runtime, which can lead to unpredictable bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92103da4-93f4-47f8-b531-038522a4ae1b', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the role of the Context object in Gin?', N'Fresher', N'The Context is the most important part of Gin, as it carries the request and response data throughout the lifecycle of an HTTP request. It provides helper methods to read parameters, set headers, and send responses back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3ca7827-3fbd-4720-8be1-0389f5d3f8b8', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Describe the utility of ''Constructor Parameters'' and ''InstanceType'' for factory pattern implementations.', N'Senior', N'These utilities allow for the extraction of constructor signatures and class instances from class definitions. They are invaluable for building factory functions or dependency injection containers where the logic needs to instantiate objects without knowing their concrete implementation details.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a044d146-0453-46c4-ad0c-038a2b8e8afc', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is a favicon and how do you include it?', N'Junior', N'A favicon is a small icon displayed in the browser tab for a website. It is included in the head section of the HTML document using a link tag with the rel attribute set to icon.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3f34c15-8710-4a63-9125-038bc13cc232', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is type inference in TypeScript?', N'Intern', N'Type inference is the compiler''s ability to automatically determine the type of a variable when an explicit type annotation is not provided. It bases this determination on the value assigned to the variable during its initialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b55101db-e940-4a0b-b053-038d06961e23', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If a user reports a bug that you cannot reproduce, what is your next step?', N'Intern', N'I would gather more information from the user, such as their environment, the steps they took, and any error messages they received. Then, I would attempt to isolate the issue by systematically varying input conditions until the behavior can be consistently triggered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5801a620-3e41-46dc-b708-038fdc08cdbd', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the ''Coordinator Node'' and its responsibility during a write request?', N'Senior', N'The coordinator node is any node in the cluster that receives a request from a client. Its responsibility is to identify the responsible nodes for the data partition, route the write requests to the appropriate replicas, and wait for the required number of acknowledgments based on the requested consistency level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'979eb3e8-4f3e-4318-a957-0391691c2f6a', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the role of a ''Write-Ahead Log'' (WAL) in distributed storage engines?', N'Senior', N'A WAL ensures durability by recording all changes to the data in a persistent append-only file before they are applied to the main data structures. This allows the system to recover the state in the event of a crash by replaying the log.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31d3c4ca-c75b-446f-9345-039191757956', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the role of an API Gateway in a microservices architecture?', N'Senior', N'An API Gateway acts as a single entry point for all client requests, abstracting the underlying microservice topology. It handles cross-cutting concerns such as authentication, rate limiting, request routing, and protocol translation, simplifying the client-side implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b83d9e74-734a-4588-80b2-0392649fb489', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the concept of ''Eventual Consistency'' and its practical trade-offs.', N'Senior', N'Eventual consistency guarantees that if no new updates are made to a data item, eventually all accesses will return the last updated value. This trade-off improves write availability and latency but introduces the complexity of handling read conflicts or stale data in the application layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b30a0c13-e176-47d2-baeb-039322873d5a', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind CSS interact with browser caching strategies in a production environment?', N'Senior', N'Since Tailwind generates a single, static CSS file that is highly optimized, it benefits from efficient browser caching. Because the file only contains the styles actually used in the project, it remains small and rarely changes, allowing for long-term cache validity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'435ad988-f48c-4718-a405-0397a7a33cee', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide when to implement a feature flag instead of a long-lived feature branch?', N'Junior', N'Feature flags are better for continuous integration, allowing you to merge code into the main branch early while hiding incomplete features from users. Long-lived feature branches should be avoided because they lead to difficult merge conflicts and delay the integration of code into the main codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20885ce3-95ce-47bb-8331-0397b6b66aed', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of source maps?', N'Intern', N'Source maps are files that map the minified or bundled code back to the original source code. They are essential for debugging because they allow developers to see the original file names and line numbers in browser developer tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
