INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4dbe737-aafc-4274-9d47-0399d90f50b8', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How would you architect a system to prevent cascading failures in a microservices environment?', N'Senior', N'I implement bulkhead patterns to isolate resource pools and use circuit breakers to fail fast when downstream dependencies are unhealthy. Furthermore, I ensure all inter-service communication includes strict timeouts and retries with exponential backoff and jitter to prevent thundering herd problems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0584ba50-5313-4f05-881f-039be2eaeb2b', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why is the lack of native Type/Interface validation in Express a risk for large-scale backend systems?', N'Senior', N'Express treats incoming requests as untrusted data without built-in schema validation, necessitating third-party libraries for validation. Without a strict contract, type errors or malformed payloads can propagate deep into the business logic, leading to runtime exceptions that are harder to diagnose.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18ba4313-d6b5-4fc8-9a7b-039f0e7b502d', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the purpose of semantic HTML, and why is it considered a best practice?', N'Intern', N'Semantic HTML uses tags that clearly describe their meaning and purpose in a document, such as header, footer, or article. This approach is a best practice because it improves accessibility for screen readers and helps search engines better understand the structure and content of your web page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
