INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a20850f-a99f-4e9e-b10e-03a1e0bb6e21', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between ''interface'' extension and intersection types?', N'Junior', N'Interfaces use the ''extends'' keyword to inherit from other interfaces, which is usually more efficient for the compiler and provides better error messages. Intersection types use the ''&'' operator to combine multiple types, which is more flexible but can sometimes result in complex error output for incompatible properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0dbaa229-72bc-403e-a614-03a322e9ecbe', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is type inference?', N'Junior', N'Type inference allows the Swift compiler to automatically deduce the type of an expression by examining the value provided during initialization. This reduces the need for explicit type declarations while maintaining strong type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd53b8373-e0e3-4fa1-8f76-03a48ed63a05', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the difference between Strongly Consistent and Eventually Consistent reads?', N'Intern', N'Strongly consistent reads return the latest version of the data, including all successful write operations. Eventually consistent reads might return data that is slightly stale because it takes time for the updates to propagate across all storage locations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edac693a-2833-43ff-aeac-03a4a0d68eda', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What does the ''const'' keyword do?', N'Intern', N'The ''const'' keyword is used to define variables or functions that cannot be modified after initialization. It ensures data integrity by preventing accidental changes to variables that are intended to remain constant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b175a3d-a613-4068-9bf8-03a83cbe62dd', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the architectural difference between Python''s list and tuple objects regarding memory allocation and mutability.', N'Senior', N'Lists are implemented as dynamic arrays with over-allocation to provide amortized O(1) append operations, whereas tuples are fixed-size arrays. Because tuples are immutable, Python can optimize their memory footprint and cache them more effectively, leading to better performance in read-only scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ca0a9fd-8681-4e4a-911e-03a8ed829955', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the role of the Controller in a Rails application?', N'Intern', N'The Controller acts as an intermediary between the Model and the View. It receives incoming requests from the user, retrieves data from the Model, and determines which View should be rendered to display the response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6a954fd-cfcb-4679-b102-03ac32020f3e', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a graph database?', N'Intern', N'A graph database is a type of NoSQL database that uses graph structures with nodes, edges, and properties to represent and store data. It is particularly effective for analyzing complex relationships between data points.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8acf675-7b41-490a-b3a7-03ad6b13b1bf', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the ''Bind'' feature in Echo?', N'Fresher', N'The Bind feature is a convenient way to automatically map request data from JSON, XML, or form-data into a Go struct. It significantly reduces the amount of boilerplate code needed to extract and parse client input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c0d78ed-5fc1-447a-b726-03aedbc0151c', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the role of query cost estimation in a database optimizer?', N'Senior', N'The optimizer uses statistics, such as cardinality and data distribution, to generate multiple execution plans and select the one with the lowest estimated I/O and CPU cost. Incorrect statistics can lead to poor execution plans, such as choosing a full table scan over an index seek.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96dbaa15-4971-4f2c-ac68-03af6f3892e1', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the benefit of ''lazy'' component loading in the context of SolidJS''s architecture?', N'Senior', N'Lazy loading enables code splitting, allowing the application to load only the necessary reactive code for the current view. Since SolidJS components are simple functions, lazy loading integrates seamlessly with dynamic imports and does not require complex wrapper components to handle the asynchronous boundary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'744396d1-b045-49d7-8856-03af88b5c312', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between document load and DOMContentLoaded events?', N'Fresher', N'The DOMContentLoaded event is fired when the initial HTML document has been completely loaded and parsed, without waiting for assets(stylesheets, images, and subframes) to finish loading. Whereas The load event is fired when the whole page has loaded, including all dependent resources(stylesheets, images).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'008832a7-7706-4121-a9b7-03b2e166a75e', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the Query extractor?', N'Intern', N'The Query extractor is used to parse and deserialize query string parameters from an HTTP request URL into a Rust struct. This makes it easy to access filter or search parameters sent by the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
