INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea75f875-4dba-4563-b899-03b7419e4200', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the significance of Gin''s ''Mode'' setting?', N'Middle', N'The mode setting, which can be debug, release, or test, determines the framework''s internal behavior. In debug mode, Gin provides verbose logs and stack traces, whereas release mode minimizes logging and optimizes performance for production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23603e10-d868-4485-98b7-03b795a1c28c', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Explain the mechanism of Micronaut''s declarative HTTP client and its advantages over manual rest templates.', N'Senior', N'The declarative client uses interfaces annotated with HTTP metadata, which Micronaut implements at compile time using Netty. This approach provides a cleaner, type-safe API, reduces boilerplate code, and improves performance by avoiding runtime proxy overhead and reflection-based request building.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9698d00d-c998-482d-a624-03b884c52803', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Why is idempotency critical in distributed systems?', N'Middle', N'In distributed systems, network failures often necessitate retrying requests. Idempotency ensures that performing the same operation multiple times results in the same state as the first request, preventing data corruption or duplicate side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'468f21c4-2810-4ba9-8a54-03b8de0f4518', N'954a0331-deff-4399-b588-96f39fec001d', N'What architectural patterns help in managing state in a large-scale Angular application without using external libraries?', N'Senior', N'One can use a service-based pattern with BehaviorSubjects and private state variables, exposing only read-only observables to components. This enforces a unidirectional data flow, ensuring that state changes are predictable and centralized within services while keeping the UI layer thin and reactive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
