INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62f32f25-16ab-46f2-8a68-03de9d387063', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Describe the behavior of generators and why they are memory-efficient.', N'Middle', N'Generators are functions that return an iterator, yielding values one at a time using the yield keyword instead of storing the entire sequence in memory. This lazy evaluation allows for processing massive datasets that would otherwise exceed RAM capacity. They maintain state between iterations, providing a clean abstraction for complex data streams.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2207640-f486-42eb-9fd7-03e01942e592', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of ''requestUpdate'' and when should a developer manually call it?', N'Middle', N'requestUpdate forces a component to re-render even if reactive properties haven''t changed. This is typically used when a component depends on internal state that isn''t tracked by the reactive property system, such as external data sources or complex non-reactive objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7219d700-ced2-415b-96cd-03e169c33ced', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between a constructor and a destructor?', N'Junior', N'A constructor is a special method called automatically when an object is created to initialize properties. A destructor is called when an object is destroyed or the script ends, allowing for cleanup tasks like closing database connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93766af2-4a99-4981-a722-03e232cd05b9', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What are the limitations of load balancing at the OSI Layer 4 versus Layer 7?', N'Senior', N'Layer 4 load balancing is faster as it routes based on simple IP and port info, but it lacks visibility into request content. Layer 7 load balancing allows for intelligent routing based on URLs, headers, or cookies, but consumes more CPU and adds latency due to deeper packet inspection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c27e697-80f9-4106-9037-03e2797c3114', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How do Tailwind CSS plugins extend the framework''s capability beyond its default utility set?', N'Senior', N'Plugins allow developers to inject custom utilities, components, or variants into the build process programmatically. This is essential for building project-specific design patterns that need to be reused across the entire utility ecosystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'983fdb96-aa66-4b33-b56b-03e3e8e684dc', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the difference between an ''Abort'' and a ''Rollback'' in the context of transaction management?', N'Senior', N'An abort is the decision to terminate a transaction, usually due to a conflict, constraint violation, or error. Rollback is the actual process of reversing the changes made by that transaction to return the database to the state it was in before the transaction began.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14b4210c-2e0d-4a86-a522-03e462746a1d', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What happens to the data in Redis if the server reboots?', N'Junior', N'If persistence is not configured, all data in memory will be lost upon a reboot. However, if RDB or AOF persistence is enabled, Redis will reload the data from the disk files back into memory when the service restarts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'485f8224-1d81-41b0-888a-03e6028a71ce', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the difference between Pseudo-classes and pseudo-elements?', N'Fresher', N'A pseudo-class is a selector that assists in the selection of something that cannot be expressed by a simple selector, for example :hover. A pseudo-element however allows us to create items that do not normally exist in the document tree, for example ::after. Pseudo-classes: Pseudo-classes select regular elements but under certain conditions, like when their position relative to siblings or when they''re under a particular state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50d85fce-9334-4791-9b8e-03e7114f5b7d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the capacity needed for a cache layer to effectively reduce database load?', N'Senior', N'I analyze cache hit ratio patterns and the frequency of read-heavy operations. By simulating the workload, I estimate the reduction in database queries and the required cache memory footprint to achieve a specific performance improvement goal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68eccafd-a3f3-47e3-87d1-03ea3dd2ecb4', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does ''perfect forwarding'' work and why is it essential for generic programming?', N'Senior', N'Perfect forwarding uses forwarding references and std::forward to preserve the value category and const-qualification of arguments as they are passed through wrapper functions. This is essential for building generic factories or wrappers that need to construct objects or call methods exactly as they would have been called if the wrapper were not present.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1e20973-8a6c-406f-9a16-03ea567110c6', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are response models in FastAPI?', N'Intern', N'Response models are used to define the structure of the data that the server sends back to the client. They ensure that sensitive fields are excluded from the output and that the data adheres to a specific format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5faf359-0ce2-4c76-be84-03eae342daf6', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What does it mean for a Lit component to be ''reactive''?', N'Fresher', N'Reactivity means the component automatically updates its view whenever its internal state or public properties change. This removes the need for manual DOM manipulation to sync the UI with the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'864784bc-6546-4aff-81bc-03ec82fe61d6', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why is the Clone trait important for the application State in Axum?', N'Junior', N'Axum routes are often shared across threads to handle concurrent requests. Because the state is passed to multiple handlers, the state type must be cloneable so that each thread can hold its own reference to the shared resources, such as a database pool.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdff0d08-481f-4449-bd5e-03f03adedf67', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the difference between synchronous and asynchronous operations?', N'Intern', N'In synchronous operations, tasks are performed one after another, and the system waits for one to finish before starting the next. Asynchronous operations allow a task to start and run in the background while the system continues to process other tasks, which is essential for maintaining responsiveness in web applications. Asynchrony prevents the entire application from freezing while waiting for a slow task like a database call.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61eae3b6-8845-41ab-9111-03f563f22d47', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum ensure type safety?', N'Fresher', N'Axum leverages Rust''s strict type system to ensure that request data is correctly parsed and that responses match expected structures. By using traits and generics, it catches type mismatches at compile time rather than runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eaa2a61c-8675-4604-a1a0-03f58fbacb99', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is a parameter in a Dart function?', N'Intern', N'A parameter is a variable that is defined in a function''s signature to accept input values when the function is called. Dart supports both positional parameters, which are identified by order, and named parameters, which are identified by their names.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21f4b742-c11a-4ef5-bea4-03fbeefa50e3', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you weigh the trade-offs between security hardening and system usability?', N'Senior', N'Excessive security controls, such as frequent MFA or strict password policies, can lead to shadow IT and user friction. The goal is to implement ''frictionless security'' where strong controls are integrated into the workflow, prioritizing the protection of high-value assets while keeping low-risk operations as accessible as possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5a229d4-0f94-425f-9115-03fd50f991e7', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does Sass handle color functions?', N'Junior', N'Sass includes built-in functions that allow you to programmatically modify colors, such as lightening, darkening, or adjusting the saturation. These functions make it easier to create color themes and variations without manually choosing new hex codes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37c688f0-6ebc-4838-9d7a-03ffaf413ffc', N'4c000000-0000-0000-0000-000000000005', N'What is the trade-off of using a centralized configuration store in microservices?', N'Senior', N'Centralized configuration simplifies management and enables dynamic updates across a fleet without redeployments. However, it introduces a single point of failure and requires robust caching or local fallbacks to ensure services can operate if the configuration store becomes unreachable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cc74312-cda4-45da-aa3d-040131f4a869', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Explain the concept of ''Content Projection'' using the `@content` directive.', N'Senior', N'The `@content` directive allows a mixin to accept a block of styles as an argument, which is then injected into the mixin''s body at the specified location. This enables the creation of powerful wrapper mixins, such as those that handle media queries or browser-specific hacks, by allowing the user to pass custom styles dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b49e17d4-ed95-4c9d-946d-04018e335fd9', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of Data Annotations?', N'Intern', N'Data annotations are attributes used to define validation rules or metadata for model properties. They allow developers to easily enforce constraints like required fields, string lengths, or email formats directly on the data model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82e89afb-b792-415d-b233-04025a76a2bf', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'You are tasked with designing a globally distributed system that requires strict consistency for financial transactions while maintaining high availability. How do you approach the trade-offs between the CAP theorem and the performance implications of synchronous replication across wide-area networks?', N'Senior', N'I would approach this by first acknowledging that strict consistency and high availability under network partitions are mutually exclusive, leading me to prioritize consistency and partition tolerance (CP) for financial integrity. To mitigate the latency costs of synchronous replication, I would utilize a consensus algorithm like Paxos or Raft with geographically optimized leader placement and suggest implementing asynchronous read-replicas for non-transactional queries to reduce the load on the primary consistency group. The design would focus on minimizing the number of network round-trips required for a quorum commit by colocating consensus nodes within low-latency proximity or using hardware-accelerated reliable multicast where applicable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c17a09df-4078-40ed-8a42-040319df222d', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What role does the ''Sidecar'' pattern play in a service mesh?', N'Middle', N'The sidecar pattern involves deploying a helper container alongside the main application service to handle peripheral tasks like logging, monitoring, traffic management, or security. This keeps the application code clean by offloading infrastructure-related concerns to the sidecar.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'623e0e33-a5a7-410f-b500-04048364ec35', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'In a NestJS microservice, what are the architectural implications of using ''ClientProxy'' versus standard HTTP communication?', N'Senior', N'ClientProxy abstracts the transport protocol, allowing for seamless switching between TCP, Redis, or NATS without changing the service logic. HTTP communication is simpler to implement and debug but tightly couples the services to the RESTful interface, whereas the proxy pattern facilitates asynchronous, decoupled event-driven communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86a2c3f0-1065-4b1f-a640-04061153f425', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of a destructor in a class?', N'Intern', N'A destructor is a special member function that is called automatically when an object goes out of scope or is explicitly deleted. Its primary purpose is to perform cleanup tasks, such as releasing memory or closing file handles. It ensures that resources acquired by the object are properly freed to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6778e72-6f0e-40b7-a859-0407142a3041', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How do you handle path parameters in Axum and why is it efficient?', N'Middle', N'Path parameters are handled via the ''Path'' extractor, which maps URL segments directly to struct fields. This is efficient because it performs the parsing and type conversion during the request routing phase, minimizing manual extraction logic within the business layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c53c57d0-af5c-4f65-8c47-0415b378274f', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum manage concurrency?', N'Intern', N'Axum leverages the Tokio runtime, which provides asynchronous I/O and task scheduling. Because Axum handlers are async, they can process many concurrent requests efficiently without blocking the thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f504caa4-675e-4af8-96c8-041a32df7851', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How do you create a nested list in HTML?', N'Fresher', N'A nested list is created by placing a or element inside an element of a parent list. Example — nested unordered list: Example — mixed ordered and unordered: Important rules: - The nested list must be placed inside an element, not directly inside / - Browsers apply different default markers at each nesting level (disc → circle → square for ) > Avoid deep nesting (more than 3 levels) for readability. Consider restructuring content or using headings instead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f9649b6-4af7-46cd-a20c-041a4f1af006', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Can you describe the main difference between a .forEach loop and a .map() loop and why you would pick one versus the other?', N'Fresher', N'To understand the differences between the two, Let us look at what each function does. 1. Array.forEach(): * Iterates through the elements in an array. * Executes a callback for each element. * Does not return a value. 2. Array.map(): * Iterates through the elements in an array. * "Maps" each element to a new element by calling the function on each element, creating a new array as a result. The main difference between .forEach and .map() is that .map() returns a new array. If you need the result, but do not wish to mutate the original array, .map() is the clear choice. If you simply need to iterate over an array, forEach is a fine choice. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb8ebedf-c12d-4229-983f-041c6bf24953', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the purpose of ''noinline'' in the context of higher-order functions?', N'Senior', N'The ''noinline'' modifier is used within an ''inline'' function to prevent specific functional parameters from being inlined, which is necessary if those parameters need to be stored as objects or passed to other functions. This provides a balance between the performance gains of inlining the function''s body and the architectural need to treat functional parameters as first-class objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'212f6e12-bd13-4b58-bf5f-041e08f66bcc', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala''s ''PartialFunction'' differ from a standard function?', N'Middle', N'A PartialFunction is only defined for a subset of possible input values and provides a method to check if an input is supported before application. This is particularly useful for pattern matching and building robust command processors where only specific inputs are valid.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dab4e55e-bfaf-490a-815f-0421fac437ad', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does module caching work in Node.js?', N'Fresher', N'When require() loads a module for the first time, Node.js executes the module file and caches the exported object in require.cache. Every subsequent require() call for the same file path returns the cached exports directly, without re-executing the file. This means: - Module-level code (e.g., a database connection) runs only once. - Mutating an exported object in one module is visible to all other modules that required it. Example — cache in action: Inspecting the cache: When is caching NOT used? - require() with different resolved paths (e.g., case sensitivity on Linux, symlinks) creates separate cache entries. - ES Modules (import) also cache, but their cache is separate from the CommonJS cache.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b54b773-8565-4959-8f2a-042343ce6400', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the primary trade-off when using GraalVM native images in a Quarkus application?', N'Senior', N'Native images significantly reduce memory footprint and startup time, but they require longer build times and lack support for some dynamic language features like heavy reflection or dynamic proxy generation. Additionally, some Java libraries may require custom configuration to function correctly in a static analysis environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9173897b-0f2a-439c-95b6-0423b3b83e3b', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the JVM handle off-heap memory and why is it used in high-performance applications?', N'Senior', N'Off-heap memory is allocated outside the garbage-collected heap using direct ByteBuffers or Unsafe APIs, effectively bypassing GC scanning and limiting pause times. It is commonly used for large caches or high-throughput networking to reduce the memory management burden on the JVM and prevent heap fragmentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc43b9db-df36-46da-8fa3-042576773d90', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the difference between synchronous and asynchronous handlers in Rocket?', N'Intern', N'Synchronous handlers block the thread while waiting for a task, while asynchronous handlers allow the thread to perform other tasks while waiting for I/O. Rocket supports both, but asynchronous handlers are preferred for high-concurrency applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a642ae0a-2d20-45e1-867b-0426e44d0bcd', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Can Micronaut applications be run as serverless functions?', N'Fresher', N'Yes, Micronaut is highly optimized for serverless environments like AWS Lambda. Its fast startup time and low memory usage help mitigate ''cold start'' issues common in serverless computing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7efb869d-fb70-4037-9dd1-04273d3de408', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the purpose of symbols in Ruby?', N'Intern', N'Symbols are lightweight, immutable identifiers often used as labels or keys in hashes. Because they are immutable and have a unique object ID, they are more memory-efficient than strings when used repeatedly for the same purpose.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'859436a4-89e4-4052-a375-0427ffa74f87', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What criteria do you use to choose between synchronous REST APIs and asynchronous message queues?', N'Senior', N'I choose synchronous APIs for requests requiring immediate feedback or strict transaction boundaries. I opt for asynchronous message queues to improve decoupling, handle traffic spikes through buffering, and enable long-running background tasks without blocking the request-response cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'813d90b5-dc94-4b7a-b492-0428d2868690', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is Twig in a Symfony project?', N'Intern', N'Twig is the default template engine used by Symfony to render HTML content. It provides a secure and concise syntax for generating dynamic views while separating presentation logic from business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c540f843-39b8-4cf3-a5d1-042b30105ef2', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum''s ''Extractor'' pattern differ from traditional middleware-based parameter parsing?', N'Senior', N'Axum extractors leverage Rust''s type system to resolve dependencies from the request state at runtime. Unlike middleware that modifies the request context, extractors are declarative and type-safe, allowing the framework to fail early if requirements are not met.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13f1d5ae-ce43-4a1f-a44b-042d77eaadf1', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the difference between group routing and individual routing in Echo?', N'Junior', N'Individual routing defines endpoints separately, while group routing allows you to bundle related routes under a common path prefix or apply specific middleware to a subset of routes. Grouping is best practice for organizing versioned APIs or securing specific sections of an application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43b440b2-46cf-4377-860f-042dfcab59e0', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you evaluate whether to adopt a microservices architecture versus a modular monolith for a new product?', N'Senior', N'Evaluate based on team size, deployment velocity requirements, and domain complexity. Microservices provide isolation and independent scaling but introduce significant operational overhead, whereas modular monoliths offer simpler debugging and consistency at the cost of potential tight coupling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'920f4ae6-b20e-4590-bbfd-04392433e652', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Explain the role of the Alpine.js lifecycle hooks in managing side effects within a component.', N'Senior', N'Lifecycle hooks like init and destroy allow developers to manage the setup and teardown of non-Alpine side effects, such as event listeners, external library initializations, or timers. By tying these to the Alpine scope, you ensure that state clean-up prevents memory leaks when components are dynamically added or removed from the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83c6a26e-1a3e-4a20-8325-04397d81229e', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If you are assigned a task where you do not know how to proceed, what steps would you take to address the knowledge gap without immediately asking for a solution?', N'Intern', N'First, I would conduct a thorough search of internal documentation and reliable external resources to understand the core concepts. Next, I would attempt to break the problem down into smaller, manageable components to identify exactly where my understanding stops. Finally, I would formulate a specific, well-researched question to ask a mentor, demonstrating that I have already put effort into solving it independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99770fb4-b71e-4665-8ffc-0439b22233c9', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is an interface in Java?', N'Intern', N'An interface is a reference type that contains only abstract methods and constant variables. It serves as a contract that defines what a class must do, without specifying how it should do it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f5e2034-318d-4d69-9f29-043bec31474e', N'075b8862-431c-4678-9767-f55359758a4a', N'What is a Teleport component in Vue 3?', N'Middle', N'Teleport allows you to render a component''s template at a different location in the DOM tree, such as the body or a modal container, while still keeping the component within the logical Vue component hierarchy. This is crucial for accessibility and managing stacking contexts like modals or notifications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a203a73-e696-448f-a95d-043e7abebf90', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s memory layout for structs differ from classes in terms of cache locality?', N'Senior', N'Structs are stored as contiguous blocks of memory, which promotes better spatial cache locality compared to classes, which are heap-allocated and require pointer indirection. Because classes are reference types, accessing their data often involves a pointer dereference that can lead to cache misses. Structs, being value types, are often stored directly within the container, reducing memory fragmentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd074dec1-c4ec-4d6d-9600-04403261333f', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you distinguish between an application-level bug and an infrastructure-level network partitioning issue?', N'Senior', N'I would analyze the error patterns: application bugs typically exhibit specific stack traces or inconsistent business logic state, whereas network issues manifest as time-outs, connection resets, or correlated failures across multiple unrelated services sharing the same network segment. Reviewing VPC flow logs or infrastructure heartbeats usually confirms if the underlying transport layer is the source of the failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6941487b-b7f5-4b10-a765-0441a4482679', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are Dynamic Modules in NestJS?', N'Intern', N'Dynamic modules are modules that can be configured at runtime. They allow you to pass configuration options to a module when it is imported, making the module more flexible and reusable across different parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'917fcfc5-e9bc-49cb-ad7d-044684b808b7', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Does Remix require a separate API server?', N'Junior', N'No, Remix is a full-stack framework that combines the frontend and backend. You can write your data fetching and mutation logic directly inside your route files, eliminating the need to maintain a separate API server for most tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8997d606-99d5-4510-bdce-04493573e1f1', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you ensure system reliability during a major architectural migration without impacting active users?', N'Senior', N'I utilize a dark launch or traffic shifting strategy, such as canary releases, to route a small percentage of traffic to the new architecture. I implement dual-writes or shadow-reads to validate data consistency in production before fully switching over, while maintaining a feature flag for an instant rollback.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6107af8-6606-476a-bf1d-044bf83978e0', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Explain the trade-off of server-side rendering in Remix regarding server load.', N'Middle', N'While server-side rendering in Remix provides excellent performance and SEO, it increases the workload on your server compared to a static site or a pure SPA. Developers must be mindful of database connection limits and caching strategies to ensure the server remains performant under high traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adc2447b-f784-4862-ba18-044fb183ccfd', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the purpose of the ''root.js'' file in a Remix project?', N'Intern', N'The root file acts as the primary layout component for the entire application. It contains the document structure, including the HTML, head, and body tags, which are shared across all pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
