INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd776d6f3-dd3a-479b-931f-0450e365c2f9', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why would you choose to use an asynchronous approach for a long-running task like sending emails?', N'Fresher', N'Performing a long-running task synchronously would block the user''s request and make the application appear frozen. By offloading it to an asynchronous process, the application can acknowledge the user''s action immediately while the background task completes independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'001f2868-bd7f-4a8c-bfbb-04557cb5c138', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What role does the ''Service'' trait play in the Axum ecosystem?', N'Fresher', N'The Service trait is a fundamental abstraction from the Tower library that represents an asynchronous function taking a request and returning a response. Axum builds its entire handler system on top of this trait to ensure consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
