INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bf3bbbb-95fe-4c7d-8062-0457e103689b', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the role of ''Context Propagation'' in observability?', N'Senior', N'Context propagation ensures that metadata, such as request IDs or user sessions, is passed through every layer of the system, including asynchronous queues and third-party APIs. Without consistent context, it is impossible to correlate events across the system, making root cause analysis of distributed failures impossible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba3215d8-8934-4f18-9dd2-045c7fb11059', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle global state?', N'Middle', N'Qwik handles global state through specialized stores that are serialized along with the component tree. These stores remain reactive across the server-client boundary, ensuring state consistency without manual re-hydration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b06ed0d2-1082-43e8-ada0-045cdb57ab82', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind CSS approach responsive design?', N'Junior', N'Tailwind uses a mobile-first responsive design strategy, meaning utility classes apply to all screen sizes by default. To target specific breakpoints, you add a prefix like ''md:'' or ''lg:'' to a utility class, ensuring that the style only takes effect when the viewport meets that minimum width requirement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6e9a9c3-0e7d-4a52-a248-045e02832eb4', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle error handling in routes?', N'Fresher', N'Remix provides an ErrorBoundary component that can be exported from any route. If an error occurs during rendering or data fetching for that route, the framework catches it and displays the component instead of crashing the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'624d4c10-f960-48cc-ba3b-0460645b4ac4', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the role of ''Adapters'' and ''Serializers'' in Ember Data, and how do they separate concerns?', N'Senior', N'Adapters define the communication strategy, such as REST or JSON:API, determining how requests are structured and sent to the backend. Serializers handle the transformation of data between the backend format and the internal representation required by the store, allowing the application logic to remain agnostic of the API''s specific schema.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0526efe5-634a-4296-b91e-046094e0c433', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does the ''Global Read Lock'' affect performance in older MongoDB versions versus WiredTiger?', N'Senior', N'In older engines like MMAPv1, a global lock blocked all operations across the entire server, creating severe bottlenecks during heavy write loads. WiredTiger eliminated the global lock in favor of fine-grained document-level locking and optimistic concurrency control, allowing for vastly superior performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
