INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'433f5214-922d-43ac-99ac-0461fc990da0', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How does a reverse proxy improve security?', N'Middle', N'A reverse proxy sits in front of backend servers and hides their internal IP addresses, providing an extra layer of abstraction. It can also perform SSL termination, filter malicious traffic, and act as a central point for implementing security policies like rate limiting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
