INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08fecf3a-1770-4043-a896-047083b2cd82', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is testing considered a part of the design process rather than just the final step?', N'Intern', N'Designing with testability in mind ensures that components are modular and have clear boundaries, which makes writing automated tests easier. If you consider testing during the design phase, you identify potential integration issues before any code is written.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
