INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd89c5ec-3ceb-4670-9207-04717214778b', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What are the performance impacts of using too many Vite plugins, and how can they be audited?', N'Senior', N'Each plugin adds overhead to the transformation pipeline, potentially increasing development latency or build times. Developers can use the vite-plugin-inspect tool to visualize the impact of each plugin on the module transformation lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7207401-50f6-4066-8868-0471871a6f96', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of a Bloom filter in database indexing?', N'Senior', N'A Bloom filter is a probabilistic data structure used to determine if an element is definitely not in a set or possibly in a set. Databases use them to avoid unnecessary disk I/O by checking the filter before performing a full index lookup, significantly speeding up queries for non-existent keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c42894f7-ad47-437c-b513-04762fca9e89', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the primary difference between SQL and NoSQL databases?', N'Intern', N'SQL databases are table-based and follow a strict, predefined schema, making them best for complex queries. NoSQL databases are document, key-value, or graph-based and offer a flexible schema, making them ideal for rapid growth and varied data types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53dca039-4f6f-411c-b84c-04764635eff7', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are Lit''s benefits for performance?', N'Fresher', N'Lit is lightweight and has a small bundle size because it relies on native browser features. Its efficient rendering system avoids unnecessary DOM updates, which results in faster UI rendering and lower memory usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33827427-da55-47be-a804-0476e92d92e6', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the difference between ''base'' R graphics and ''grid'' based systems?', N'Middle', N'Base graphics are immediate-mode systems where elements are drawn directly to the device and cannot be easily modified later. Grid-based systems, such as ggplot2, use a persistent graphical object model, allowing for more complex layering and systematic manipulation of plot elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e71f49cf-c2a2-455d-859b-047d94003d6b', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why would you choose to use an existing framework instead of building a custom solution from scratch?', N'Fresher', N'Frameworks provide pre-built, tested solutions for common problems like security, routing, and database management, which significantly speeds up development. Building from scratch is only advisable if the requirements are highly specialized and cannot be met by existing tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0aa80409-70c1-4ee2-94aa-0480372ad87a', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Why is it important to implement error handlers for global exceptions in a Flask application?', N'Senior', N'Global error handlers prevent the leakage of internal stack traces, which are a major security vulnerability, and ensure that all errors return a consistent, machine-readable API response. This abstraction is critical for client-side error handling and system monitoring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36659ba0-47e3-4d32-b3d0-048080a8f13d', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What are the performance implications of using complex data structures inside actor messages?', N'Senior', N'Sending large or complex data structures involves cloning or moving memory across actor boundaries, which can become a significant CPU bottleneck. Designers should prefer sending references, small identifiers, or using shared memory structures like Arc to minimize the cost of inter-actor communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f62bd454-df1b-465c-8242-04812998b023', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the difference between an API route (+server.js) and a page load function?', N'Middle', N'Page load functions are intended to provide data to components for rendering within the UI. API routes, however, serve as standard HTTP endpoints that return raw data like JSON, which is useful for building public APIs or handling webhook requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1be96bdf-de15-46a5-9954-0481c2011746', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the impact of middleware nesting in Fiber?', N'Middle', N'Excessive nesting or poorly optimized middleware can add latency to every request. Since each middleware is a function call in the execution chain, keeping the middleware stack lean is essential for maintaining high performance in latency-sensitive applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6ead4b4-6835-417f-90dc-0484398d0689', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the purpose of the Redux DevTools extension?', N'Junior', N'The DevTools extension is a browser tool that allows developers to inspect the state, view dispatched actions, and even time-travel to previous states. It is an essential tool for debugging complex state logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e6dcaae-0591-45a3-b75d-0486b0c705a7', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the purpose of ''hinted handoff'' in NoSQL replication?', N'Middle', N'Hinted handoff is a recovery mechanism where, if a node is temporarily unavailable during a write, another node stores the update and a ''hint'' to deliver it to the intended node once it returns online. This helps maintain consistency across the cluster during intermittent node failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6850e62c-dc14-4aa3-b6a5-04877629eb4b', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the core architectural difference between Astro and traditional Single Page Applications (SPAs)?', N'Middle', N'Astro follows the Islands Architecture, which emphasizes shipping zero JavaScript to the browser by default. Unlike SPAs that hydrate the entire page, Astro only hydrates specific interactive components, significantly improving initial load performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd4f78ac-6496-4012-b199-0487d537cbc4', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the trade-offs of using ''any'' versus ''unknown'' in a large-scale system?', N'Senior', N'Using ''any'' completely disables type checking for that value, creating a blind spot that can lead to runtime exceptions. Conversely, ''unknown'' acts as a type-safe counterpart that forces the developer to perform type narrowing or assertion before interacting with the value, preserving system integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccecca2d-2bda-418f-8080-048b2af4e6fb', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What are the main challenges when migrating an existing app to Qwik?', N'Middle', N'The main challenge is adapting to the rules of resumability, particularly the requirement that state and closures must be serializable. Developers must rethink how they manage component lifecycles and avoid patterns that rely on global, non-serializable variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c68b4b6-3768-440a-87db-048fac1ae0cb', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between Structural and Nominal typing, and which one does TypeScript use?', N'Middle', N'Nominal typing determines compatibility based on explicit declarations or names, while structural typing determines compatibility based on the shape or members of a type. TypeScript uses structural typing, meaning if two types have the same members, they are considered compatible regardless of their declaration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb866486-ddec-4cee-adab-04914ad53f58', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does ''Graceful Degradation'' differ from ''Fail-Fast'' and when should each be used?', N'Senior', N'Graceful degradation provides a reduced-functionality experience to the user to keep the system alive, whereas fail-fast immediately terminates an operation to prevent the spread of errors. Graceful degradation is preferred for user-facing features, while fail-fast is essential for internal services where error propagation causes severe instability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18748cf9-c19b-4f3e-bb7a-04929976eb68', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript handle optional parameters in functions?', N'Junior', N'Optional parameters are denoted by adding a question mark after the parameter name. This tells the compiler that the argument is not required and may be ''undefined'' if omitted during the function call.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f44f308-da39-4cff-a8d5-049561792b78', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Describe the difference between ''shallow'' and ''deep'' copying in jQuery''s ''extend'' method.', N'Middle', N'A shallow copy only copies the top-level properties of an object, while a deep copy recursively copies nested objects. Using deep copies is crucial when merging configuration objects to avoid unexpected side effects where nested properties are shared by reference between the original and the new object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fe7940f-d041-4416-afbc-04993e6b3fcf', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is LocalDateTime?', N'Intern', N'LocalDateTimecombines together LocaleDateand LocalTimecontains the date and time in the calendar system ISO-8601 without reference to the time zone. Time is stored accurate to the nanosecond. It contains many convenient methods such as plusMinutes, plusHours, isAfter, toSecondOfDay, etc.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'679993ba-d5a7-4f8b-979c-049ab9c89b26', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are the trade-offs of using Lit''s ''lit-html'' templating engine compared to a Virtual DOM approach?', N'Senior', N'lit-html uses tagged template literals to create efficient, static-optimized templates that only update the parts of the DOM that actually changed. Unlike Virtual DOM, which requires diffing a large object tree in memory, lit-html maintains direct references to dynamic parts, reducing memory overhead and CPU cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76a3a956-861b-45f9-8d8d-049e6ae9d274', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why is Express considered ''unopinionated'', and how does this affect team scalability in large organizations?', N'Senior', N'Being unopinionated means Express provides no guidance on project structure, data access patterns, or configuration management. In large organizations, this lack of standard leads to ''architectural drift'' where different teams build the same functionality in incompatible ways, increasing onboarding time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5e76919-ed42-4ea3-91b3-049ec2116678', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a foreign key and what is its purpose?', N'Junior', N'A foreign key is a field in one table that links to the primary key of another table. Its purpose is to maintain referential integrity between the two tables, ensuring that relationships between data remain consistent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7179f8f7-a095-4456-81c0-049ee2b233e6', N'a2838158-7305-480a-b22b-4dc35776b400', N'Explain the architectural implications of implementing a Saga pattern versus Two-Phase Commit (2PC) for maintaining distributed transaction integrity.', N'Senior', N'Two-Phase Commit is a synchronous, blocking protocol that ensures ACID compliance but suffers from performance bottlenecks and availability risks if the coordinator fails. In contrast, the Saga pattern manages distributed transactions as a sequence of local transactions using compensating actions to maintain eventual consistency. Sagas improve scalability and fault tolerance by avoiding long-lived locks, but they introduce complexity in handling partial failures and lack isolation by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40e041d4-0a05-4c74-b6cd-049f1abf2b12', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are PHP sessions used for?', N'Intern', N'Sessions are used to store information about a user across multiple pages of a website. They allow the server to recognize a user as they navigate through different parts of an application by creating a unique session ID.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38d96811-eb24-4b60-a404-04a2876a3fe4', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does ASP.NET Core implement asynchronous programming throughout the pipeline, and why is this critical for scalability?', N'Senior', N'The framework is designed to be fully non-blocking, using asynchronous I/O for database operations, file access, and HTTP requests. This prevents thread starvation by allowing the thread pool to handle other incoming requests while waiting for I/O operations, significantly increasing the concurrent request capacity of the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efc1aeda-db5e-4821-97f6-04a2c1fd9aa3', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Explain how you differentiate between an infrastructure-level issue and an application-level bug during a production incident.', N'Senior', N'I examine the correlation between the incident and any recent CI/CD deployments or infrastructure configuration changes. If the issue affects multiple services simultaneously, I focus on shared infrastructure components like service meshes, databases, or network gateways; if only one service is affected, I focus on recent code commits, dependency changes, or service-specific configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29f916b8-2bbc-4cc8-9d5d-04a9bc657ff2', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Explain the role of the C preprocessor in the context of separate compilation and link-time optimization.', N'Senior', N'The preprocessor operates before the translation phase, performing textual substitution and macro expansion that can obscure source intent from the static analyzer. While it enables conditional compilation for portability, it creates a disconnect between the source and the binary, making it harder for link-time optimization to perform cross-module analysis. Senior developers often prefer inline functions or constant definitions to maintain better symbol visibility and debugging information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8482fa6-6823-45ef-b885-04a9c532a2c2', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of the ''type'' field in older versions of Elasticsearch?', N'Intern', N'In older versions, types were used to group documents within an index, similar to tables. However, types have been deprecated in newer versions in favor of creating separate indices to avoid mapping conflicts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52aed210-fa51-455a-ae30-04a9cc9cd222', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Why is dependency injection considered beneficial for testing?', N'Fresher', N'Dependency injection makes testing easier because you can swap out real components for mocks or stubs during a test run. This allows you to isolate the logic of the handler from external systems like databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68dd41df-1256-4396-b0e4-04aa14029f1a', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the benefit of using ''when'' over ''if-else'' chains?', N'Junior', N'The ''when'' expression is a more readable and powerful version of a switch statement. It allows for complex branching logic, can be used as an expression to return values, and ensures exhaustive checking when working with sealed classes or enums.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b141f005-8a89-4161-b219-04ad1402f657', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is a ''Responder'' in Rocket?', N'Intern', N'A responder is a trait that defines how a type can be converted into an HTTP response. Anything that implements the Responder trait can be returned from a Rocket handler function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ee71907-b64f-4d05-973f-04b151064f3b', N'954a0331-deff-4399-b588-96f39fec001d', N'What is Angular Ivy?', N'Intern', N'Angular Ivy is a new rendering engine for Angular. You can choose to opt in a preview version of Ivy from Angular version 8. 1. You can enable ivy in a new project by using the --enable-ivy flag with the ng new command 2. You can add it to an existing project by adding enableIvy option in the angularCompilerOptions in your project''s tsconfig.app.json.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33bf915b-8cc2-4791-9369-04b16021077c', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the purpose of middleware in Redux, and how does it implement the decorator pattern?', N'Senior', N'Middleware provides a third-party extension point between dispatching an action and the moment it reaches the reducer. It uses the decorator pattern to wrap the dispatch method, allowing developers to inject custom logic like logging, crash reporting, or asynchronous task handling without modifying the core library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'375986c9-cc01-4fba-bc40-04b2eded7cf5', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the difference between Procs and Lambdas regarding argument handling?', N'Middle', N'Lambdas are stricter and behave more like methods, raising an error if the incorrect number of arguments is passed. Procs are more lenient, treating missing arguments as nil and ignoring extra arguments. Additionally, a return statement inside a lambda exits the lambda scope, while a return inside a proc exits the surrounding method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'078cc434-97be-49c2-8b81-04b35c397842', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the difference between HotSpot and GraalVM in Quarkus?', N'Fresher', N'HotSpot is the traditional Java Virtual Machine that runs bytecode, while GraalVM is a high-performance JDK that can compile Java code into native executables. Quarkus supports both, but GraalVM is used to achieve native compilation for maximum performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7dfbc584-f97b-40c7-8792-04b4c0e1001c', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How do you handle query parameters in Axum?', N'Intern', N'Axum provides a Query extractor that automatically parses URL query strings into a struct. This allows developers to work with typed data rather than raw strings when handling filters or search parameters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba151775-68cd-4389-be3c-04b5febaa5f4', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix approach the problem of ''layout shifting'' during navigation?', N'Senior', N'Remix manages layout persistence by keeping stable segments of the route tree in place during transitions. By only replacing the segments of the UI that change, it minimizes DOM churn and provides a stable, flicker-free navigation experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b9a1fee-9781-473c-bf73-04bf87e1ce77', N'954a0331-deff-4399-b588-96f39fec001d', N'What is content projection?', N'Intern', N'Content projection is a pattern in which you insert, or project, the content you want to use inside another component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be77942d-6a94-4461-b2d6-04c09bf92633', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the trade-offs between using a monolithic Rails architecture versus a microservices approach for a high-concurrency application.', N'Senior', N'A monolith simplifies data consistency and operational complexity but can become a bottleneck during vertical scaling. Microservices offer independent scalability and deployment flexibility, yet they introduce significant overhead in network latency, distributed transaction management, and service discovery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9412bb9e-5518-42a8-a2c6-04c3be9ad844', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Can Webpack optimize images?', N'Fresher', N'Yes, through specific loaders or plugins, Webpack can compress and optimize images during the build. This ensures that image assets are as small as possible before being deployed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b9535c1-ca3e-492c-afae-04c9f1c3828d', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the ''doc_values'' mechanism improve performance?', N'Middle', N'Doc values are an on-disk, columnar data structure that makes sorting and aggregations highly efficient. By storing data in a columnar format, Elasticsearch can read only the specific fields needed for a calculation instead of loading entire documents.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dc9e36f-5985-48ed-bee0-04caa61920df', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Compare Alpine.js to Web Components in terms of encapsulation.', N'Senior', N'Web Components provide true Shadow DOM encapsulation, whereas Alpine.js works within the light DOM. While Web Components offer better isolation, Alpine provides a much simpler developer experience for building interactive UI features without the boilerplate of custom element definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a76ae758-860b-40cf-89df-04cb567ca14d', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is CORS in the context of backend development?', N'Intern', N'CORS stands for Cross-Origin Resource Sharing. It is a security feature implemented by browsers that allows or restricts web applications on one domain to access resources located on a different domain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dc7879c-972e-4e77-98f4-04cd014eb709', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind ensure consistency in design tokens across a large team?', N'Middle', N'Consistency is enforced by defining a strict theme in the configuration file, such as a specific color palette or spacing scale. By limiting developers to these predefined tokens, Tailwind prevents the accumulation of arbitrary design values and ensures a cohesive visual language.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d3272b0-8bc6-49f3-ab98-04cf1c8b7a82', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the scope resolution operator?', N'Fresher', N'The scope resolution operator (::) is used to clarify the scope of a variable or function. It is commonly used to define a class member function outside the class body or to access a global variable that is shadowed by a local one.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb12f6fe-ac76-4645-a66d-04d06cef559d', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the role of the useSelector hook?', N'Fresher', N'The useSelector hook is used to extract data from the Redux store state. It allows components to subscribe to specific parts of the state and automatically re-render whenever that specific data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2717112f-8bc8-4ea7-8df5-04d3139a63d2', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does a load balancer improve system scalability?', N'Middle', N'A load balancer distributes incoming network traffic across multiple backend servers to ensure no single server bears too much demand. This prevents bottlenecks, increases fault tolerance, and allows the system to handle a higher volume of concurrent users by spreading the workload effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3462fbc-dd08-4ce1-923c-04d3de978e89', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Explain the architectural advantages of Hono''s ''Web Standards'' approach when deploying to edge runtimes.', N'Senior', N'By relying exclusively on the Fetch API, Request, and Response interfaces, Hono avoids dependencies on Node.js-specific APIs. This makes it inherently portable across heterogeneous environments like Cloudflare Workers, Vercel Edge, and Bun, ensuring consistent behavior without polyfills.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'825ccfad-e468-4fd1-9448-04d48f659944', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the purpose of ''sealed classes'' and how do they improve code safety?', N'Middle', N'Sealed classes represent restricted class hierarchies, allowing developers to define a fixed set of subclasses. They improve safety by enabling the compiler to perform exhaustive checks in ''when'' expressions, ensuring that all possible subtypes are handled without needing an ''else'' branch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ea1cb6f-90ed-46a0-83ad-04d71fabd002', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the role of a Candidate Key?', N'Fresher', N'A candidate key is any column or combination of columns that can uniquely identify a record in a table. From the set of candidate keys, one is chosen to be the primary key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3303894-a990-43a0-b475-04d734de7615', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What does it mean that Swift is a type-safe language?', N'Intern', N'Type safety means the language helps you be clear about the types of values your code can work with. If part of your code requires a string, the compiler prevents you from passing an integer by mistake, which catches errors early in the development process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'015da17c-9474-49c0-b046-04d7a81d6eb8', N'a2838158-7305-480a-b22b-4dc35776b400', N'Explain the ''LSM-Tree'' data structure and its impact on write performance.', N'Senior', N'Log-Structured Merge-Trees optimize write performance by buffering updates in memory and periodically flushing them to disk as sorted files. This transforms random writes into sequential writes, which are significantly faster on both HDDs and SSDs, making them ideal for high-write-volume storage engines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21b9677a-84d3-4dae-b73a-04dab3932170', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is a “smart cast” in Kotlin?', N'Intern', N'In Kotlin, a smart cast refers to the compiler''s ability to automatically cast a variable under certain conditions. This feature significantly reduces code verbosity and casting overhead, ensuring code safety. How It Works The smart cast is automatically applied after the compiler identifies a segment of code where a certain type check has been completed. For example, consider the following code snippet: Code Analysis - Within the if and else if blocks, smart casts are triggered. After these checks, the compiler automatically adjusts the type of obj for that code block. - This mechanism eliminates the need for developers to manually cast obj within each conditional branch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0667133e-9766-4d10-9245-04ddc5f567e3', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why are null values sometimes problematic in database design?', N'Junior', N'Null values can complicate queries because they represent the absence of data, which often requires special handling in logical operations. They can also make indexing less efficient and potentially lead to unexpected results in aggregate functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a489538-8df8-4ca9-a391-04de078a9911', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is a Migration in Ruby on Rails?', N'Intern', N'A migration is a feature that allows you to evolve your database schema over time in a consistent and version-controlled way. Instead of writing raw SQL, you use Ruby code to define changes such as creating tables, adding columns, or updating existing data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf15dc4a-5ca0-4c25-93de-04deb176bf18', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the purpose of the & character in Sass nesting?', N'Junior', N'The ampersand represents the parent selector in a nested rule. It is commonly used for pseudo-classes like hover or for creating BEM-style modifiers without repeating the parent''s full class name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa8e6458-c386-48d2-b3e5-04ded104fe6e', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does a load balancer assist in database scaling?', N'Middle', N'A load balancer sits in front of a cluster of database replicas and distributes incoming read requests across them. This ensures that no single replica becomes overloaded and provides a seamless way to add or remove capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a419dbb-3bab-40eb-beaf-04e1920dfc8f', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the difference between synchronous and asynchronous logging?', N'Middle', N'Synchronous logging waits for the write operation to finish before the application continues, which can introduce latency. Asynchronous logging offloads the write operation to a separate thread or process, ensuring the application remains responsive but risking log loss if the system crashes abruptly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'310a88d6-04d1-43cf-b723-04e2e1e76872', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What are the performance impacts of enabling ''All'' fields or deep-nesting objects?', N'Senior', N'Deeply nested objects require creating a hidden document for every nested object, significantly increasing the index size and query complexity. Similarly, indexing unnecessary fields into an ''all'' structure bloats the index and degrades performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33395988-9e76-4549-a1e1-04e8020f9874', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle browser history or URL state?', N'Middle', N'Alpine.js does not have built-in routing, but it can easily integrate with the browser''s History API or third-party routers. Developers typically use x-init to listen for popstate events or update the URL manually when component state changes to keep the UI in sync with the address bar.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae9cdfa0-6d0b-4c1b-b812-04e946e78ba1', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are Ruby blocks, and how do they differ from procs?', N'Middle', N'Blocks are anonymous chunks of code passed to methods that are not first-class objects and cannot be stored in variables. Procs are objects that encapsulate a block of code, allowing them to be assigned to variables, passed as arguments, and invoked multiple times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3596deb-25ff-4e90-a299-04ee129829e3', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the purpose of the ''NoRoute'' handler in Gin?', N'Senior', N'The NoRoute handler allows for custom 404 response logic, providing a centralized place to handle requests that do not match any defined path. This is useful for returning consistent API error structures instead of the default plain-text 404 response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05217762-5828-47fa-acad-04efb568c1e1', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why does Remix prioritize web standards like the Fetch API and Request/Response objects?', N'Middle', N'By adhering to web standards, Remix ensures that the framework remains interoperable and portable across different environments like Node.js, Cloudflare Workers, or Deno. It allows developers to use familiar native browser APIs instead of proprietary framework-specific abstractions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d411f3c-2d52-434c-baa0-04efba06fe37', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does the Quarkus ''Uber-JAR'' differ from a standard Maven/Gradle fat JAR?', N'Senior', N'A Quarkus Uber-JAR is optimized for speed by separating application code from framework libraries. This structure allows the framework to cache libraries across container layers, leading to faster deployment times and more efficient storage of container images.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'549cfc9f-e850-40c7-ae84-04f0a1517419', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a key-value store database?', N'Intern', N'A key-value store is the simplest type of NoSQL database where every data item is stored as a unique key associated with a specific value. It is highly efficient for simple lookups and caching scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b4fb85b-94e1-4a51-a31d-04f7c5b831ab', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What happens when R encounters missing data represented by NA?', N'Junior', N'Most mathematical operations involving NA will result in NA because the value is unknown. To perform calculations like sums or means on data containing missing values, one must typically use specific arguments like na.rm equal to true to ignore them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f6bd549-6cc3-4a94-a894-04f8f4475b2d', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the difference between path parameters and query parameters?', N'Intern', N'Path parameters are part of the URL path itself and are typically used to identify a resource. Query parameters are appended to the URL after a question mark and are generally used for filtering, sorting, or pagination.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8b3515a-298a-48d5-93c2-04fa08eada90', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are iterators and generators in JavaScript and what are they used for?', N'Intern', N'In JavaScript, iterators and generators are powerful tools for managing sequences of data and controlling the flow of execution in a more flexible way. Iterators are objects that define a sequence and potentially a return value upon its termination. They adhere to a specific interface: - An iterator object must implement a next() method. - The next() method returns an object with two properties: - value: The next value in the sequence. - done: A boolean that is true if the iterator has finished its sequence, otherwise false. Here''s an example of an object implementing the iterator interface. Generators are special functions that can pause execution and resume at a later point. They use the function* syntax and the yield keyword to control the flow of execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66932bca-6a86-4693-9394-04fb2c78aeb5', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When considering feature flags, what is the trade-off between deployment flexibility and code complexity?', N'Junior', N'Feature flags allow you to decouple code deployment from feature release, enabling safer rollouts and A/B testing. However, they add conditional logic to the codebase, which increases testing surface area and makes the code harder to read if not cleaned up promptly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8a7682c-5106-4833-92d6-04fc72732fe6', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing an API, why is versioning considered a best practice?', N'Junior', N'Versioning allows you to introduce changes or new features without breaking existing clients that rely on older versions of the API. It ensures backward compatibility and gives users time to migrate to newer endpoints at their own pace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fc3176d-58a2-4f89-9ef3-04fe51963163', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why does Ember emphasize ''Convention over Configuration'', and how does this affect scalability?', N'Senior', N'Convention over Configuration reduces the decision fatigue of setting up project structures and boilerplate, which allows large teams to move between different Ember projects with minimal onboarding. It also ensures that the framework''s tooling can reliably predict application structure, leading to better automated testing and build optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f66f9b66-da8f-4dd2-9bda-04fe9dd6b320', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Is jQuery still relevant in modern frontend development?', N'Fresher', N'While modern frameworks like React and Vue have replaced jQuery for complex applications, it remains relevant for smaller projects or legacy codebases. It is still a highly efficient tool for simple DOM manipulation and quick prototyping.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1ee456a-4373-4c3d-946f-04ff25ac581a', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are the architectural implications of Rust''s choice of ''zero-cost abstractions''?', N'Senior', N'Zero-cost abstractions mean that high-level features like iterators or closures are compiled down to machine code as efficient as hand-written equivalents. This allows developers to use expressive programming paradigms without incurring runtime penalties, though it shifts the complexity burden to the compiler''s optimization phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f692ad2-219f-4bfe-93a8-050231ae4f5b', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Why would you choose to use gRPC over REST for service-to-service communication in ASP.NET Core?', N'Senior', N'gRPC offers significantly higher performance by using Protocol Buffers for binary serialization and HTTP/2 for multiplexing. It also provides strictly typed contracts via .proto files, which reduces runtime errors and simplifies integration in complex internal microservices architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67a561a9-59d5-40ac-bff4-0502e5ffa1a1', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the architectural significance of using Starlette as the underlying foundation for FastAPI?', N'Senior', N'Starlette provides a lightweight, high-performance ASGI toolkit that handles the low-level asynchronous request-response cycle. By building on top of Starlette, FastAPI inherits robust asynchronous capabilities, WebSockets support, and middleware management, allowing it to focus strictly on developer experience and high-level routing features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fe1a406-2659-4595-b4ae-0504922e0d6b', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the role of MethodHandles compared to Reflection in terms of JVM optimization.', N'Senior', N'Reflection bypasses many static analysis checks and is inherently slower because it requires dynamic access checks on every invocation. MethodHandles provide a more type-safe, performant mechanism that allows the JVM to apply standard inlining and optimization techniques, as they are essentially treated as constant values by the JIT compiler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dea07987-dcab-4f3e-9d94-050594d864ab', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS ensure that large lists remain performant?', N'Middle', N'SolidJS uses a specialized ''For'' component that maps data to elements and tracks changes at the item level. This ensures that only the specific elements that were added, removed, or moved are updated, rather than re-rendering the entire list.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30628ee4-1fb6-472f-aa7c-0505f0f7a19b', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is optional binding?', N'Intern', N'Optional binding is the process of checking if an optional contains a value and, if so, making that value available as a temporary constant or variable. It is commonly implemented using ''if let'' or ''guard let'' syntax to safely unwrap the optional.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a654bc5c-684b-4753-aca9-0508c0581944', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux handle state hydration in Server-Side Rendering (SSR)?', N'Senior', N'During SSR, the state is serialized on the server and injected into the HTML as a global variable. On the client side, the application initializes the Redux store using this serialized state as the ''preloadedState'', ensuring that the client-side store starts in the exact same state as the server-rendered version.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e80f31a-984a-4033-b7d4-050aa3e75a35', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Describe the risk of using ''type assertions'' as a substitute for proper type narrowing.', N'Senior', N'Type assertions essentially override the compiler''s safety checks, effectively telling it to ignore potential inconsistencies. In large systems, over-reliance on assertions leads to ''lying'' to the compiler, which masks underlying architectural flaws and creates brittle code that is prone to runtime exceptions when data shapes deviate from expectations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4336c4a1-f508-434f-b2de-050ce72663ff', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is Dependency Injection in the context of Symfony?', N'Intern', N'Dependency Injection is a design pattern where an object receives its dependencies from an external source rather than creating them itself. In Symfony, the service container automatically injects these required dependencies into classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef64e519-5d8c-4759-997f-050da328e8ce', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Does Preact''s approach to ''hooks'' differ significantly from React''s internal implementation?', N'Senior', N'Preact''s hooks implementation is designed to be functionally identical to React''s but stripped of the complex internal state management logic required for features like concurrent mode. This makes Preact hooks faster and smaller, but they may behave differently in highly specific edge cases involving state synchronization or asynchronous updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6b0093d-d1fd-4499-92bb-050f95467dc1', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are nullable types and how are they denoted?', N'Junior', N'A nullable type is a type that can explicitly hold the value null. They are denoted by appending a question mark to the type name, such as String?, indicating that the compiler should enforce null checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
