INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee7d7c86-7def-4497-82cb-0510e5dc98b6', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Why would you use a Repository pattern in a Laravel application?', N'Middle', N'The Repository pattern acts as an abstraction layer between the application logic and the data source. It is useful if you need to switch database drivers, cache data consistently, or simplify complex queries to improve testability and maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a856820d-b89c-4de5-b44a-051276d4ed62', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle query parameter list types?', N'Junior', N'FastAPI can automatically parse query parameters that appear multiple times in a URL into a list. By defining a parameter with a List type hint, the framework collects all values associated with that key into a single Python list.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61c655cc-4227-4245-ad78-05147d41c65d', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Why is it dangerous to perform heavy CPU-bound tasks directly in an ''async def'' route handler?', N'Senior', N'An ''async def'' handler runs on the main event loop; a CPU-intensive task will block this loop, preventing the server from processing other incoming requests or performing I/O operations. This leads to increased latency and potential timeouts across the entire application under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13e42714-0bd7-430f-a501-05149fb95e70', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the concept of Dependency Injection in Spring Boot.', N'Intern', N'Dependency Injection is a design pattern where an object receives other objects that it depends on rather than creating them itself. In Spring Boot, the framework manages the creation and lifecycle of these dependencies, injecting them automatically into classes where they are needed to promote loose coupling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6df8c964-fc88-4360-afe8-05162cb4c968', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the ''poster'' attribute on a video element impact perceived performance?', N'Senior', N'The poster attribute allows the browser to display a static image before the video metadata is loaded, preventing a blank box during the initialization phase. This improves perceived performance and allows the browser to prioritize the image over the potentially heavy video file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffecacfd-7310-41ec-b3a8-0516827eac49', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Do NoSQL databases support joins?', N'Fresher', N'Most NoSQL databases do not support joins in the same way SQL databases do. Because data is often denormalized or embedded, the need for joins is reduced, and any required linking is usually handled at the application level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
