INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f571ecca-e6e2-4b22-a4c7-051c82576ab4', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Discuss the scalability limitations of the Global Run Queue in the Go scheduler.', N'Senior', N'The global run queue requires a mutex lock for every operation, creating contention as the number of CPU cores increases. To mitigate this, Go uses local run queues for each processor (P), only falling back to the global queue when local queues are empty.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
