INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7484089-66af-4e68-9a68-0527e617b60e', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the function of the ''start'' directory in an AdonisJS project?', N'Junior', N'The start directory contains files that are executed when the application boots up. It is primarily used to register routes, handle global event listeners, and perform initial configuration tasks required by the framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2813dab6-694a-43b6-bbe3-052acec83cfb', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'In a distributed system, why might you choose Quarkus over a traditional Java framework for serverless functions?', N'Senior', N'The ''cold start'' latency of traditional Java frameworks makes them unsuitable for serverless environments. Quarkus native images provide near-instant startup times, allowing Java applications to be competitive with languages like Go or Node.js in ephemeral compute environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51afb795-f64f-4376-9839-052f660bd1db', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is Qwik considered ''progressive''?', N'Junior', N'Qwik is progressive because it only loads the JavaScript for the specific features the user touches. It starts as a simple static HTML page and progressively becomes a fully interactive application as the user explores it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71f48d76-6564-4b7f-8225-0530315baf87', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What are Server Actions, and why are they considered a secure way to handle mutations?', N'Middle', N'Server Actions are asynchronous functions that execute on the server, allowing you to perform data mutations without manually creating separate API routes. They are secure because they integrate with Next.js built-in CSRF protection and allow you to enforce server-side validation and authorization before performing any action.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cadf0e7e-8481-4db6-8d87-0532413042fa', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s ''metadata'' (annotations) system function?', N'Middle', N'Metadata in Dart provides a way to attach additional information to code elements like classes, methods, or parameters using the ''@'' syntax. This information can be read at runtime via reflection or at compile-time by code generators to influence application behavior or perform static analysis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6994ee7-1931-4193-a5bd-0532e6140b70', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of ''g'' in Flask?', N'Intern', N'The ''g'' object is a special namespace that acts as a storage for data that needs to be accessed by multiple functions during a single request. It is useful for sharing data, such as a database connection, throughout the request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03769678-2cd7-46f3-b4f5-0535f6d3cfd1', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Your team is deciding whether to buy a third-party service or build a custom internal tool for a specific feature. What factors influence this trade-off?', N'Junior', N'I would weigh the development time and maintenance overhead of building against the cost and loss of control associated with a third-party service. Building is preferred if the feature is a core competitive advantage that requires deep integration, while buying is usually better for non-core features where speed-to-market and reduced operational burden are higher priorities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc1291aa-0702-4543-b0a2-053699dfaf77', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are Procs and Lambdas in Ruby?', N'Junior', N'Both are objects that wrap a block of code to be stored or passed around. The main difference is that Lambdas check the number of arguments passed to them and return control to the calling method, whereas Procs do not enforce argument count and return from the surrounding scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63f94164-66b2-48be-8bc6-0536b2d1888a', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of custom id?', N'Intern', N'When you change the translatable text, the Angular extractor tool generates a new id for that translation unit. Because of this behavior, you must then update the translation file with the new id every time. For example, the translation file messages.de.xlf.html has generated trans-unit for some text message as below You can avoid this manual update of id attribute by specifying a custom id in the i18n attribute by using the prefix @@.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc7f2200-dde3-4a7e-8932-0536bbfb773c', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the role of the ''Template Literal Types'' in generating dynamic string types.', N'Senior', N'Template literal types allow for the creation of new types by concatenating string literals or union types. This is particularly useful for modeling APIs that rely on specific string patterns, such as CSS property names or event emitter strings, ensuring type safety for dynamic key access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c205c8aa-3ad3-47d1-87b4-0536cd7efd65', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the primary advantage of Chi''s ''composability''?', N'Junior', N'Composability means you can break down your application into small, independent sub-routers and middleware stacks. This makes the codebase modular, easier to test, and simpler to maintain as the application grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03f3e5ab-1cfc-4654-817f-0537a012653f', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Why is the order of columns in a composite index critical for query performance?', N'Senior', N'B-tree indexes are sorted by the leading column first, then subsequent columns. If a query filters on a non-leading column without the leading column, the index cannot be traversed efficiently, often resulting in a full index or table scan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b607f468-49ce-4451-9d05-0537c3688045', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are the primary considerations when migrating an Ember application to ''Octane'' or newer editions?', N'Senior', N'The primary focus is shifting from class-based, property-heavy models to functional, tracked-based reactivity and native JavaScript classes. This involves refactoring legacy decorators and observers to use the native class syntax and the ''tracked'' paradigm, which improves overall performance and interop with standard JavaScript tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1944f72-0566-443d-90a6-0538fa6ae06f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a ''Type Assertion'' and when is it considered unsafe?', N'Middle', N'A type assertion (using ''as'' or angle brackets) tells the compiler to treat a value as a specific type, effectively bypassing the compiler''s inference. It is considered unsafe when the assertion does not match the actual runtime structure of the data. It should be used sparingly, primarily when you have more information about a value''s type than the compiler does.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff3baef5-a1f0-4fae-a886-0539317561ae', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the advantage of using ''Database Transactions''?', N'Middle', N'Database transactions ensure that a series of database operations either succeed entirely or fail entirely, maintaining data integrity. If one operation within the transaction fails, the entire set of changes is rolled back, preventing partial or inconsistent data states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4406cd77-e435-4def-8526-0539e37b570b', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does the ''N+1 Query Problem'' manifest in database design and how can it be mitigated?', N'Senior', N'The N+1 problem occurs when an application executes one query to fetch parent records and then individual queries for each child record, causing excessive network round-trips. It is mitigated through eager loading, join queries, or data loaders that batch requests into a single efficient operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1b1fe61-2f33-43c9-ab8f-053b18a1be55', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between the operators == and ===?', N'Junior', N'The == operator checks for equality of values after performing type juggling if necessary. The === operator, known as the identity or strict comparison operator, checks that both the values and the data types are identical without performing type conversion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1c2fba0-fd2c-4ff0-a912-053bd5496f44', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the concept of Auto-configuration in Spring Boot.', N'Fresher', N'Auto-configuration is a feature that automatically configures your Spring application based on the dependencies present in the classpath. It intelligently detects libraries like H2 or Hibernate and sets up the necessary beans without requiring the developer to write manual configuration code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c16d1c83-e64a-437e-a150-053e45aa935f', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When should you use a queue in your system design?', N'Fresher', N'A queue is useful when you need to decouple processes, such as when one service generates more work than another can handle immediately. It acts as a buffer to ensure that the system remains responsive even during traffic spikes, as tasks can be processed at a steady rate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bc07652-87b4-40ce-89b8-053e4d21aaeb', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How would you create a PHP variable and how are they scoped (global, local, static)?', N'Fresher', N'PHP variables have diverse scopes, from being accessible globally by all scripts to being confined to defined functions or methods. They can be local, global, and static. Local Scope Variables defined within a function are locally scoped and inaccessible outside its body. Example: Local Scope Here is the PHP code: Global Scope Global variables can be accessed across the entire PHP script, including from within functions. Example: Global Scope Here is the PHP code: Function / Method Scope Variables declared within a function or method are limited in scope to that block. Example: Function Scope Here is the PHP code: Static Scope Static variables retain their values between function calls. They are still function-scoped.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9180906-ac5d-4d7d-af69-053ef210d97b', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why is it beneficial to involve more experienced team members in the estimation process?', N'Junior', N'Senior members often have a better grasp of the broader system architecture and can identify risks that a junior might overlook. Their experience helps provide a sanity check, ensuring the estimate is grounded in reality rather than just theory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5eab0545-4d46-47e7-bdf0-05441c9ce655', N'a2838158-7305-480a-b22b-4dc35776b400', N'What are the limitations of using a centralized load balancer in a global system?', N'Senior', N'A centralized load balancer creates a single point of failure and a potential performance bottleneck. It also increases latency for geographically distributed users, which is why global systems typically use DNS-based load balancing or Anycast to route traffic to the nearest regional instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd17c2fb7-db3f-4f0e-8bf8-054818a6198c', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the primary difference between Svelte and traditional frameworks like React or Vue?', N'Intern', N'Svelte is a compiler rather than a framework that runs in the browser. While others use a virtual DOM to compare changes, Svelte converts your code into highly optimized, vanilla JavaScript during the build step, which updates the DOM directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7454ae07-6a4e-4ece-90ef-05487581d4a7', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the benefit of Chi’s ''Context'' middleware?', N'Middle', N'The Context middleware ensures that the request context is properly initialized with routing information. This is essential for features like URL parameter parsing to function correctly across the entire request stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f46fa6a8-2ad9-4eb6-a725-0549c428ba8b', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is an index in Elasticsearch?', N'Intern', N'An index is a logical namespace that groups related documents together. It functions similarly to a table in a relational database, providing a category for the documents stored within it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d98f990-5c44-4e14-92e5-0549c9ba43c2', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is throttling and debouncing in javascript?', N'Intern', N'Debouncing and throttling techniques are used to limit the number of times a function can execute. These are two widely-used techniques to improve the performance of code that gets executed repeatedly within a period of time. Throttling enforces a maximum number of times a function can be called over time. As in "execute this function at most once every 100 milliseconds." Example: Debouncing enforces that a function not be called again until a certain amount of time has passed without it being called.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f66287b0-70c4-4d30-aeb5-054d6abebf48', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How can you handle user events like clicks in Svelte?', N'Junior', N'You handle events using the ''on:'' directive followed by the event name, such as ''on:click''. You then assign a function to be executed when that event is triggered on the element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd71a3d54-273a-418b-b211-054f2359a87b', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does the ''Cache'' component in Symfony support cache invalidation, and what strategies exist for tag-based invalidation?', N'Senior', N'The Cache component supports tagged items, allowing groups of related cache entries to be invalidated simultaneously by a single tag identifier. This provides a robust strategy for maintaining data consistency, especially in scenarios where a change in a core entity necessitates clearing multiple related views.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7aa5abd0-e79b-412c-a90c-0553a284a1d0', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the difference between a ''liveness'' probe and a ''readiness'' probe?', N'Junior', N'A liveness probe checks if the application is running and should be restarted if it fails. A readiness probe checks if the application is prepared to handle requests, preventing traffic from being routed to an instance that is still initializing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3dbf441-0f7e-4748-9bcf-0553b108ca63', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Are there pre-built component libraries for Tailwind CSS?', N'Intern', N'Yes, there are several libraries, such as Tailwind UI, that offer professionally designed, accessible components. These are built using Tailwind classes and can be copied and pasted directly into your projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1654c6fb-9daa-4f54-92d7-0553b69a5805', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you share data between a parent and a child component?', N'Junior', N'You use the @Input decorator in the child component to receive data from the parent. The parent binds to this input property in its template to pass the required information down.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28a406bf-a6c3-4b93-81cd-0557b66ad2cf', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are Associated Values?', N'Intern', N'Associated values are Swift''s feature that permits each enum case to hold specific data. This ability makes enums more flexible and versatile. Unlike basic enums, which store the same type of data for all their cases, enums with associated values can store different types of data for each case. When to Use Associated Values Use associated values when an enum case can represent distinct states or data structures. This mechanism is a powerful way to model payload data. For instance: - In an online clothing store app, the ShoppingCart can be empty, or it can contain one or more items. - In a game, a Player can be in a particular state, like fighting or healing, and each state may include additional data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a1000e1-509c-4918-91ee-055950ae441b', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When estimating a task, why should you consult with team members who have more experience?', N'Junior', N'More experienced team members can identify potential edge cases, dependencies, or architectural pitfalls that I might overlook. Their input provides a more realistic perspective on complexity and helps prevent common project delays.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd70d2ad-2e0e-4b5f-a2e9-055aff25dab1', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite''s ''Optimization'' mode work for dependencies?', N'Senior', N'Vite automatically detects new dependencies in the project and performs an optimization pass, which is a cache-based re-bundling process. This ensures that the dev server stays performant even as new packages are added, by keeping a local cache of processed, ready-to-import modules in the node_modules folder.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eda44453-4d25-40cc-afb5-055b08d338c3', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the importance of ''Dependency Injection'' in testing Rails applications.', N'Middle', N'Dependency injection allows you to pass mock objects or alternative implementations into a class during testing, rather than relying on hard-coded dependencies. This isolates the component under test and prevents side effects, such as making real API calls or database writes during unit tests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9897d94f-3861-479c-bf2a-055c5a74bc01', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the significance of implicit interface implementation in Go?', N'Fresher', N'In Go, types do not need to explicitly declare that they implement an interface. As long as a type defines all the methods required by an interface, it is considered to implement that interface automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9826473-2ff2-4dd7-8465-055f29714d85', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of the constructor method?', N'Junior', N'The constructor is a special method that is automatically called when an object is instantiated from a class. It is primarily used to initialize object properties or perform setup tasks necessary for the object to function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'455c1770-1426-474f-a094-05608bae9141', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Is it possible to use Echo with other Go frameworks or libraries?', N'Middle', N'Yes, because Echo is built on standard library interfaces, it is highly interoperable. You can easily integrate other Go libraries for database ORMs, caching, or messaging systems without conflict.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf528fbd-d634-48ae-a1af-0560d9bec57c', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is Svelte?', N'Intern', N'Svelte is a component-based frontend framework that shifts the work of building an application from the browser to a compile step. Unlike traditional frameworks that use a virtual DOM, Svelte compiles your code into highly efficient, imperative vanilla JavaScript that surgically updates the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c9c6cff-2402-40a0-a86f-05611ae89950', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the purpose of a ''canary deployment''?', N'Middle', N'A canary deployment releases a new version of a service to a small subset of users before a full rollout. This allows developers to observe the performance and error rates of the new version in a production environment with minimal risk.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'597bab09-d541-488d-b7ba-05620498a875', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do ''Canary Deployments'' support reliability?', N'Middle', N'Canary deployments involve rolling out a new version of software to a small, isolated subset of users before a full release. If the monitoring metrics show an increase in error rates or latency, the deployment can be rolled back quickly, minimizing the impact on the user base.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22060d97-5bef-491d-8f9e-0563001e8c22', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the primary difference between React and Preact, and why would you choose the latter?', N'Junior', N'Preact is a lightweight alternative to React that maintains a similar API while being significantly smaller in bundle size. You would choose Preact when performance and minimizing the initial download size are critical, such as in mobile-first applications or projects with tight resource constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7c78c86-272b-47e0-b30a-056535813311', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are the implications of using ''platform types'' when consuming Java libraries in Kotlin?', N'Senior', N'Platform types are types with unknown nullability that the Kotlin compiler treats with relaxed safety rules, effectively opting out of null safety for those specific references. This is a pragmatic necessity for interoperability, but it introduces the risk of runtime null pointer exceptions, requiring developers to manually assert nullability through explicit checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
