INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15622ab1-3be1-4639-b35e-05684e3e6560', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the risk of using Tailwind''s default configuration in a strictly branded design system?', N'Middle', N'Using the default configuration risks a ''generic Tailwind look'' because the framework''s default spacing and color scales are very recognizable. To avoid this, developers should customize the theme config to match the specific design tokens provided by the brand''s style guide.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c92da175-5c11-4af4-9a60-0569594a8d42', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What approach would you take to ensure high availability for a stateful application in a Kubernetes cluster?', N'Senior', N'I would utilize Persistent Volumes with cross-zone replication provided by the cloud provider and ensure the application uses a distributed consensus algorithm like Raft or Paxos for state management. I would also configure Pod Disruption Budgets and anti-affinity rules to ensure replicas are spread across different nodes and availability zones.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a43d0e5-b5c4-4bae-96cb-0569f02190fa', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Describe the security implications of AdonisJS''s default body parser compared to manual request handling.', N'Senior', N'The default body parser includes built-in protection against common vulnerabilities like mass assignment and malicious payload injection through strict schema validation. Manual handling increases the surface area for bugs, as developers must manually sanitize and validate every input field, which is prone to human error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8604c1b8-2282-468c-a4a2-057026ff9f27', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the purpose of Flask Blueprints and why they are essential for mid-sized applications.', N'Middle', N'Blueprints provide a way to organize an application into distinct components or modules. They allow developers to register routes, error handlers, and static files separately, which prevents the main application file from becoming unmanageable. This improves maintainability and enables better team collaboration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb9b6bc3-3c5f-4a82-9471-057250085283', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are Accessors, mutators, @property?', N'Intern', N'Accessors and mutators are often called getters and setters in languages like "Java". For example, if x is a property of a user-defined class, then the class would have methods called setX() and getX(). Python has an @property ''decorator'' that allows you to ad getters and setters in order to access the attribute of the class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a21fdb75-c5e2-4cc7-bd94-0575c8debbd0', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How do you handle data modeling in DynamoDB compared to SQL?', N'Middle', N'In SQL, you normalize data across multiple tables to avoid redundancy. In DynamoDB, you typically use denormalization, storing related data in a single item or using composite keys to retrieve complex relationships in a single request, as joins are not supported.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45903406-c87b-42b3-b8a5-0576b8b88dc3', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the features of Redux DevTools?', N'Intern', N'Some of the main features of Redux DevTools are below, 1. Lets you inspect every state and action payload. 2. Lets you go back in time by _cancelling_ actions. 3. If you change the reducer code, each _staged_ action will be re-evaluated. 4. If the reducers throw, you will see during which action this happened, and what the error was. 5. With persistState() store enhancer, you can persist debug sessions across page reloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a35edc9-3142-413a-83ff-0576f7b87e4c', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a document in Elasticsearch?', N'Intern', N'A document is the basic unit of information that can be indexed. It is represented in JSON format and contains the specific fields and values that define the data record.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2073631-0523-45c2-bf1c-0578e706687a', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the primary benefit of Fastify''s encapsulated architecture via plugins?', N'Middle', N'Encapsulation allows developers to create isolated contexts where plugins, hooks, and decorators are scoped to specific routes or sub-applications. This prevents global state pollution and makes the application architecture more modular and easier to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc3ae142-d158-440f-81d0-057c70d15e17', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why would you choose an event-driven architecture over a request-response pattern?', N'Middle', N'Event-driven architecture is superior for decoupling services and handling high-volume, asynchronous workflows. It allows the system to remain reactive and scalable under load. I avoid it when the complexity of managing message brokers and distributed state outweighs the benefits of simplicity in a request-response model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13f804fe-a4a4-46c4-bc31-05846b9fe684', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What are the scalability concerns when moving from a monolithic Next.js app to a micro-frontend architecture?', N'Senior', N'Micro-frontends introduce challenges regarding shared dependencies, consistent UI design systems, and routing conflicts. While they allow teams to work independently, they often lead to increased bundle sizes and complex orchestration requirements compared to a unified Next.js repository.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
