INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e29dc9ee-f500-498d-a5bc-05894c94730a', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What does ''thread-safe'' mean regarding Actix-web state?', N'Intern', N'Thread-safe means that the application state can be accessed or modified by multiple threads simultaneously without causing data corruption or crashes. In Rust, this is typically enforced by the Send and Sync traits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
