INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24f8af07-5128-4ee1-9b1b-058f3b38cf1e', N'954a0331-deff-4399-b588-96f39fec001d', N'Describe the architectural difference between Angular''s Ivy renderer and the older View Engine.', N'Senior', N'Ivy is a locality-based rendering engine that compiles components independently, which significantly reduces bundle sizes via tree-shaking. Unlike the View Engine, which relied on complex metadata, Ivy generates instructions that are easily interpreted by the runtime, enabling features like lazy-loading components and better debugging capabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea369861-e07e-447f-b629-05910f6e56be', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you debug an issue where a microservice starts up correctly but fails to register with the service discovery mechanism?', N'Senior', N'I would verify the network connectivity between the service and the registry, ensuring that the necessary ports are open and that the service has the correct permissions to write to the registry. I would also check the startup sequence to ensure that the registration logic is not being skipped due to a dependency on another service that has not yet reached a ready state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36ff1e6b-8749-4fc5-ada4-05924caac210', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the purpose of the ''chi.NewRouter'' function?', N'Junior', N'The NewRouter function initializes a new instance of a Chi router. This object serves as the entry point for defining your API routes, middleware, and sub-routers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'febf0edc-66fc-461e-8e35-0594a199c6a7', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js interact with server-side rendered HTML?', N'Middle', N'Alpine.js is designed to layer on top of server-side rendered HTML seamlessly. Because it doesn''t require a build step to render the initial view, it preserves SEO and accessibility while adding interactivity to the static content generated by back-end frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec56443d-eca7-4c41-8f27-05957f587ba4', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is Fiber popular for high-performance applications?', N'Intern', N'Fiber is popular because it combines the simplicity of modern web frameworks with the raw performance of Go and the efficiency of the Fasthttp engine. This makes it ideal for applications requiring high concurrency and low latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8279a36-c1ef-46bc-b99a-059a6cdffe79', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How do you handle database transactions in Laravel to ensure data integrity?', N'Middle', N'Laravel provides the DB::transaction method which wraps a set of operations; if any operation fails, the entire transaction is automatically rolled back. This ensures that your database remains in a consistent state even if an error occurs during execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
