INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e46aeeda-0ec3-4ea3-9756-05a1b48d10b7', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the difference between an event listener and an event delegation in SolidJS?', N'Junior', N'SolidJS uses event delegation by default for most events to optimize performance by attaching a single listener to the root. While you can attach specific listeners, delegation is more memory-efficient and helps reduce the overhead of managing many individual event handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3eec9079-71d0-4399-9213-05a2f0a65e28', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Why would you choose an ''at-least-once'' delivery guarantee over ''exactly-once'' in a high-throughput system?', N'Middle', N'At-least-once delivery is significantly easier to scale and offers higher performance because it avoids the complex distributed transaction overhead required for exactly-once semantics. Systems using at-least-once must handle duplicate processing by implementing idempotent consumer logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc2f1cb6-9b59-4f16-87eb-05a636494542', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why does Lit use ''static styles'' rather than standard CSS-in-JS solutions?', N'Senior', N'Static styles are parsed once per component class and adopted by all instances of that component, which is significantly more memory-efficient than creating individual style tags for every instance. This approach leverages the browser''s native CSSStyleSheet capability, providing optimal performance and cacheability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
