INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0e696e3-99ad-4e2e-b5ac-05a7e1c679e9', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What does ''Resumability'' mean in the context of Qwik?', N'Intern', N'Resumability is the ability of an application to pause execution on the server and resume it on the client without re-executing the entire application logic. This allows the page to be interactive immediately after loading without needing to hydrate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
