INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9309c793-88ff-4ec1-a6c4-05b203d92a57', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does the ''hooks.server.js'' file interact with the application''s lifecycle?', N'Senior', N'This file acts as the global interceptor for incoming HTTP requests. It provides hooks to manipulate the request event, modify the response headers, or inject data into the ''locals'' object, effectively acting as the central coordination layer for cross-cutting concerns like logging and session management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8b725a9-87e3-49e0-9680-05b43117ff55', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a database backup?', N'Intern', N'A backup is a copy of the database data and structure used to restore the system in case of corruption or data loss. In PostgreSQL, backups can be performed as logical dumps or physical file-level copies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b5386d1-0a0f-4951-a351-05b6b9aded50', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you commit with payload?', N'Fresher', N'You can also pass payload for the mutation as an additional argument to store.commit. For example, the counter mutation with payload object would be as below, And then you can trigger increment commit Note: You can also pass primitives as payload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff45c1f2-af4d-4441-bd77-05b874ceb8da', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Why does Dart utilize a generational garbage collection strategy?', N'Middle', N'Generational garbage collection assumes that most objects have a short lifespan. By dividing memory into generations, Dart can quickly collect young objects and only periodically scan older, long-lived objects, significantly reducing the performance overhead of memory management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2fa85c5-5814-4269-ac91-05bb02a88db1', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the role of the ''app.vue'' file?', N'Intern', N'The app.vue file is the main entry point for a Nuxt application. It serves as the root component where you can define global layouts, styles, or logic that apply to every page in the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40248100-acef-4972-850d-05bb0b52a305', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the ''splitProps'' utility?', N'Fresher', N'SplitProps is a helper function used to destructure props while maintaining their reactivity. It is useful when you need to separate props into different groups, such as separating UI props from data props.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5521a451-ac3e-4471-b783-05bbe6f56dfb', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Can Micronaut applications run on GraalVM?', N'Intern', N'Yes, Micronaut is specifically designed to work with GraalVM Native Image. Because Micronaut does not use reflection, it can be compiled into a native executable that starts almost instantly and uses very little memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fddc0a83-8bd8-4157-968c-05bf656bbb48', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the advantage of using ''Fiber'' over a full-featured framework like ''Gin''?', N'Junior', N'Fiber is often chosen for its extreme performance due to the underlying Fasthttp engine and its familiar, Express-like API. While Gin is also performant and widely used, Fiber is specifically optimized for developers who need the absolute lowest latency and memory overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eed90e3b-129e-45da-aa1a-05bf9ebfedc0', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the concept of ''Type Erasure'' in Swift and why it is occasionally necessary.', N'Senior', N'Type erasure is a pattern used to hide the specific type information of a generic protocol, allowing it to be used in collections or as return types. It is necessary because Swift''s type system does not allow protocols with associated types to be used as concrete types directly, as the compiler cannot resolve the specific types at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ee34f4f-4965-4452-a901-05c21cfc1fff', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What are the implications of Axum''s ''Router'' being immutable after construction?', N'Senior', N'Axum routers are built as a static tree structure that cannot be modified at runtime. This immutability ensures thread safety and predictable routing behavior, which is critical for high-concurrency environments where shared mutable state in a router would be a significant point of failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28725a16-8157-4dbe-8488-05c2f2d125ef', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does indexing impact database performance?', N'Junior', N'Indexing significantly improves read speed by allowing the database to locate data quickly. However, it can slightly slow down write operations because the index must be updated every time data is inserted, updated, or deleted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'595c4eb9-bb06-493a-9af9-05c4827350a3', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of the ''requestUpdate'' method?', N'Junior', N'requestUpdate is a method used to manually trigger an update for a component. While rarely needed because property changes trigger updates automatically, it is useful when a component needs to re-render based on external data or state that is not managed by a reactive property.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8972af6-cefd-4c79-9350-05c5f866c0c9', N'954a0331-deff-4399-b588-96f39fec001d', N'Discuss the trade-offs between ''providedIn: root'' and declaring services in an NgModule''s providers array.', N'Senior', N'Using ''providedIn: root'' enables tree-shaking, as the service is only included if injected somewhere in the app, and it ensures a singleton instance. Declaring providers in an NgModule forces the service to be part of the bundle even if unused and creates separate instances if the module is imported in multiple lazy-loaded chunks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'045ccf8b-b8b4-4209-a616-05c6b519c48d', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB handle write capacity limits when using Auto Scaling?', N'Middle', N'DynamoDB Auto Scaling monitors actual utilization against provisioned throughput and adjusts capacity up or down based on predefined policies. When traffic spikes occur, the service provisions additional capacity to handle the load, though there is a slight delay before the new capacity is fully active.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93d8b87d-60af-42f9-9f33-05cd50408514', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the role of an Entity in Doctrine ORM?', N'Junior', N'An Entity is a simple PHP object that represents a row in a database table. Doctrine maps the properties of these objects to the database columns, allowing developers to interact with data using object-oriented principles instead of raw SQL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f73855f-a34b-4c90-9bf3-05d2c6cc1b93', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you differentiate between an assumption and a fact in a project requirement?', N'Intern', N'A fact is a verifiable piece of information supported by data or explicit documentation, while an assumption is a belief I am holding to move forward in the absence of data. I would document my assumptions clearly so they can be validated or corrected as more information becomes available.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1665cef-9b26-44e4-bab3-05d2c7824ac4', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What are the trade-offs of using an Actor-based architecture versus a pure Functional/Handler-based one in Actix?', N'Middle', N'The Actor model is excellent for managing complex stateful entities and long-lived connections, but it introduces overhead due to message passing and mailbox management. A pure functional approach is simpler and faster for stateless REST APIs, making the choice dependent on whether your application requires complex internal state coordination.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcea5dfc-1400-4dd5-aa82-05d40112a01e', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact manage component state updates in terms of object identity?', N'Senior', N'Preact aims for structural equality and minimizes object creation during renders, which helps in preventing unnecessary re-renders of child components. By being less aggressive with object freezing or deep immutability checks, it maintains speed, though developers must manage state immutability manually to ensure reliable component updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'843e874a-69b7-4930-84d1-05d68f6ec9db', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How do ''Opaque Types'' (some Protocol) differ from ''Existential Types'' (any Protocol)?', N'Senior', N'Opaque types hide the underlying concrete type from the caller while allowing the function to maintain the specific type identity internally for performance. Existential types allow the storage of different concrete types that conform to the protocol, at the cost of losing specific type information and incurring dynamic dispatch. Opaque types preserve type identity, enabling the compiler to optimize calls statically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17d03293-8d1a-4186-886d-05d9f8055153', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How do blocks, Procs, and lambdas relate to closures?', N'Middle', N'All three are closures, meaning they capture the local variable scope in which they were defined. This allows them to access and modify variables even after the original scope has exited, provided those variables are still in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0c964e6-baf1-4d33-8062-05dd36b264ff', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle static asset imports like images or JSON files?', N'Senior', N'Vite treats static assets as modules, allowing them to be imported directly into JavaScript code. It automatically handles URL resolution, caching via content hashes, and can even inline small assets as base64 strings if configured to do so.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf5b49fa-5d9b-42eb-8591-05dec765c6e0', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the function of the preprocessor in C?', N'Intern', N'The preprocessor is the first step of the compilation process that handles directives starting with a hash symbol. It performs tasks like including header files and replacing macro definitions before the actual compilation begins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8cf39c2-4a2c-4afb-8cfb-05df62a20d48', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix handle shared state between different request handlers?', N'Fresher', N'Actix uses application data, often wrapped in an atomic reference counter, to share state across different threads. This allows multiple handlers to safely access and modify shared resources like database pools or configuration settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59ce9a43-4641-4fd2-ab83-05df8ed0da20', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Does Svelte require a runtime library?', N'Intern', N'Svelte requires a very small runtime library that is included in the final bundle to handle component mounting and updates. However, because most of the heavy lifting is done at compile time, the runtime overhead is significantly lower than that of other frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1cc5d0d-bcab-4580-b1d6-05e12fe3d96b', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Can Tailwind CSS be used alongside existing CSS frameworks like Bootstrap?', N'Middle', N'Yes, they can coexist, but it requires careful configuration of the Tailwind prefix to avoid naming collisions. While possible, it is generally discouraged due to the increased bundle size and the confusion caused by having two competing ways to style the same elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c3f679b-0d90-4f02-89eb-05e27cb26a5f', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are the trade-offs of using ''state'' versus standard ''property'' in Lit?', N'Middle', N'Properties are intended for public API surface area, meaning they can be set from the outside via attributes. State is intended for internal data that should trigger updates but should not be exposed or reflected to the outside world, providing better encapsulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'023f5e6e-a6c5-428c-8e29-05e6035b672e', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between ''unowned'' and ''weak'' references, and when should each be used?', N'Senior', N'Weak references are optional and automatically set to nil when the object is deallocated, making them safer for objects with a longer lifespan than the referrer. Unowned references are non-optional and assume the object will always be available during the reference''s lifetime, which is more performant but risks a runtime crash if accessed after deallocation. Unowned is preferred when the relationship is strictly coupled and the referrer is guaranteed to be destroyed before the object it references.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7820996e-82ca-467e-a37f-05e7c134d0d6', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a relationship in database design?', N'Fresher', N'A relationship describes how different entities in a database are associated with each other. Common types include one-to-one, one-to-many, and many-to-many relationships, which define how data in one table links to data in another.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'300d4378-ad8d-45d6-aa73-05eda5c6cafa', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the supported System Modifier Keys?', N'Intern', N'Vue supports below modifiers to trigger mouse or keyboard event listeners when the corresponding key is pressed, 1. .ctrl 2. .alt 3. .shift 4. .meta Lets take an example of control modifier with click event,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe20d055-5217-4f25-91b7-05f435914810', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the difference between Reflow and Repaint, and how can you minimize their impact on application performance?', N'Senior', N'Reflow involves re-calculating the geometry and position of elements, which triggers a cascading effect through the render tree, while Repaint only updates visual properties like color or background. To minimize performance hits, developers should batch DOM mutations, use transform properties for animations to trigger GPU acceleration, and avoid layout-triggering properties like top or left.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'717a5dc0-fafb-477c-ad8a-05f9e6699fdc', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Why is it recommended to design APIs based on ''Resources'' rather than ''Actions''?', N'Senior', N'Resource-based design aligns with HTTP methods, allowing for standard cache control, improved discoverability, and cleaner URI structures. Action-based design often leads to RPC-style endpoints which lose the benefits of standard HTTP caching mechanisms and become harder to maintain as the domain model grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b473ac36-7d57-47f5-a6a5-05fa36419bcb', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why might a team choose Tailwind CSS over a component library like Material UI?', N'Middle', N'Tailwind provides total design freedom by offering low-level utility classes, whereas component libraries provide pre-styled, opinionated components. Teams choose Tailwind when they need a highly custom visual design that does not look like a standard library and want to avoid the ''overriding styles'' struggle common with rigid frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39ddfc6e-e64c-4202-a138-05fa781d01a4', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the purpose of the ''fetch'' event in Hono?', N'Intern', N'The fetch event is the entry point for requests in edge environments like Cloudflare Workers. Hono maps this event to its internal router to process incoming traffic according to the defined application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe996226-a04a-490f-9a26-05fbd61c1183', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How do stored procedures affect database design and maintainability?', N'Middle', N'Stored procedures encapsulate business logic within the database, which can reduce network traffic and ensure consistency across multiple applications. However, they can lead to vendor lock-in, make version control more difficult, and consume valuable database CPU resources that might be better used for query execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e0c46ac-87bf-4fb1-ab58-05fbe6b8a294', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why are ''extractors'' considered a powerful feature in Actix-web?', N'Middle', N'Extractors decouple request parsing from handler logic by automatically converting HTTP request components into typed Rust objects. This enforces type safety and reduces boilerplate code for tasks like JSON deserialization, query parameter parsing, and path variable extraction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1eac133-ee18-41d1-8416-05fd27e471bd', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of the ''resolve'' guard in Angular routing?', N'Middle', N'The resolve guard allows you to fetch data before a component is activated. This ensures that the component has all the necessary information ready when it initializes, preventing empty states or flicker during data fetching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'972629dd-f599-46d7-93e8-060007fad4bd', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does type hinting and return type declaration improve application reliability?', N'Middle', N'Type hinting enforces the expected data types for function arguments and return values at runtime, catching bugs early. This makes code self-documenting and significantly reduces the number of ''undefined index'' or ''call to member function on null'' errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df179136-e323-49b1-9934-060106ecbbc2', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide when to refactor a system versus rewriting it entirely?', N'Senior', N'Refactor when the architecture is sound but specific components are inefficient or brittle. Consider a rewrite only when the core architecture fails to meet modern business requirements or when the cost of maintaining the legacy system exceeds the cost of a greenfield implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cf1b3e8-0fe6-4371-8924-0601782f8f70', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the difference between static and sticky positioning?', N'Junior', N'Static is the default positioning where elements follow the normal document flow. Sticky positioning acts as a hybrid, where an element behaves like relative positioning until it reaches a specific scroll threshold, at which point it becomes fixed in place.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbe2b2b8-b658-4209-b8df-0601d5de624a', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you keep your technical knowledge up to date?', N'Intern', N'I regularly follow industry blogs, official documentation, and reputable technical forums to stay informed about new practices and tools. I also participate in team discussions and attend internal training sessions when possible. Consistent, small amounts of learning help me remain effective in a changing technical environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b817347a-b764-41ae-93c2-0602160483e7', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does a distributed queue maintain high availability?', N'Middle', N'High availability is achieved through replication, where messages are copied across multiple broker nodes. If one node fails, another can take over the lead role to ensure that producers and consumers can continue accessing the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bce85fd4-c18a-4b67-bcb0-06037fbd7053', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is Django ORM and why is it useful?', N'Intern', N'Django ORM stands for Object-Relational Mapper, which allows developers to interact with database data using Python objects instead of writing raw SQL queries. It abstracts the database operations, making the code more readable and portable across different database systems like PostgreSQL or SQLite.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf4a72bb-a629-4f1f-925c-06046edc57ab', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle large-scale data fetching on the server?', N'Senior', N'Qwik utilizes server-side ''loaders'' that are executed during the server-side rendering phase. These loaders are serialized into the HTML, ensuring that the client does not need to re-fetch the same data once the page becomes active.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2180f91-57e3-4217-a12b-0606e85cb3e6', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the nullish coalescing (??) and optional chaining (?.) operators, and how do they relate to control flow?', N'Intern', N'Both operators introduced in ES2020 reduce verbose defensive if checks for null/undefined values: - Nullish coalescing (??): Returns the right-hand operand when the left is null or undefined (not other falsy values like 0 or ""). - Optional chaining (?.): Short-circuits and returns undefined instead of throwing a TypeError when accessing a property on null or undefined. Example: Real-World Use Case: When consuming third-party REST APIs or GraphQL responses, deeply nested fields may be absent depending on the query. Optional chaining eliminates dozens of guard clauses like if (response && response.data && response.data.user).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c6deaa6-c4bf-4457-bf5c-0607b7c20e3b', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the primary data model used in MongoDB?', N'Junior', N'MongoDB uses a document-oriented data model. Data is stored in collections as flexible JSON-like documents, which allows for fields to vary between documents within the same collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd58bec2c-d344-44bb-91c6-06097b12cc35', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the difference between horizontal and vertical partitioning?', N'Middle', N'Horizontal partitioning, or sharding, stores rows of a table across different nodes. Vertical partitioning involves storing different columns of a table in different locations, often used when some columns are accessed much more frequently than others.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b466d59f-d6bf-462a-9440-060b2f7b3228', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the purpose of the Redis ''List'' data type?', N'Fresher', N'A Redis List is a collection of strings sorted by insertion order. It is commonly used to implement queues or stacks within an application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd69a981d-a628-4e80-b776-06100421dc87', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the concept of smart casts in Kotlin.', N'Fresher', N'Smart casts are a compiler feature that automatically casts an object to a specific type after a type check. If you check if a variable is of a certain type using the ''is'' operator, the compiler allows you to use it as that type without an explicit cast.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eeedd427-8d53-411c-a52e-0611811d672b', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the purpose of the ''CoroutineDispatcher'' abstraction?', N'Senior', N'The CoroutineDispatcher defines which thread or thread pool a coroutine uses for its execution. By decoupling the coroutine logic from the specific thread, it allows for easy testing with test dispatchers and enables switching execution contexts mid-coroutine without complex callback-based code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3656f025-49ba-4276-a97e-0612a511c0a2', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'In the context of Preact, what is the role of the ''preact/compat'' package and when should it be used?', N'Middle', N'The preact/compat package acts as a compatibility layer that mimics React''s API, allowing developers to use React-based libraries and components within a Preact project. It should be used when an application requires specific third-party dependencies that depend on React-specific behaviors, though it increases the final bundle size compared to using pure Preact.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'726c6fc3-3c55-4d6c-8bea-06138f04102b', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the purpose of a hidden node in a MongoDB replica set?', N'Senior', N'A hidden node is a member of the replica set that does not participate in elections and is not visible to the client applications for read operations. It is typically used for dedicated tasks like running analytical backups or generating reports without impacting the performance of the production primary and secondary nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1acd5f3-9474-4ca3-a950-0613e51c0c9e', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If a feature you implemented is not working as expected, how do you investigate?', N'Fresher', N'I would backtrack to the last point where the system was known to be working correctly. I would verify my assumptions about the input data and check if the expected output matches the actual output at each step of the logic. By systematically verifying each part of the process, I can isolate exactly where the behavior diverges from the requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b713969a-847b-4736-b9a8-06147e0227c6', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the ''createResource'' primitive?', N'Fresher', N'The createResource primitive is used for handling asynchronous data loading, such as fetching data from an API. It manages the loading state, error state, and the resulting data in a reactive way.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'411ff263-d54e-4ad1-829d-06150181b1b8', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the purpose of denormalization in NoSQL?', N'Junior', N'Denormalization involves storing related data together in one place, even if it causes data duplication. This is done to optimize read performance and reduce the need for expensive join operations that are not natively supported in many NoSQL systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65c4b49d-160b-46b6-b09b-0619b0818a90', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does the ''readConcern'' setting affect query consistency?', N'Middle', N'The readConcern setting determines the isolation level of read operations. For example, ''majority'' ensures that the data read has been acknowledged by a majority of replica set members, protecting against reading data that might be rolled back if the primary fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c534cfcb-901f-45d4-aa8a-0619f8d7e4a5', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the role of Write-Ahead Logging (WAL) in database recovery?', N'Senior', N'WAL ensures durability by appending all modifications to a sequential log on disk before applying them to the actual data pages. In the event of a system crash, the database can replay the log to restore the state to the last committed transaction, ensuring data integrity without needing to flush every page to disk immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1208baf0-5e2e-4263-b61c-061aa7919399', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the architectural implications of choosing a Multi-Master versus a Single-Master replication setup?', N'Senior', N'Single-Master simplifies conflict resolution and ensures strict ordering, but it creates a single point of failure and a bottleneck for write operations. Multi-Master increases availability and write throughput, but introduces significant complexity in managing write conflicts, data divergence, and synchronization overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22e76a64-c600-462e-bde9-061f3547bcd9', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the benefits of using an event emitter in your application architecture?', N'Middle', N'Event emitters allow for a decoupled, reactive architecture where modules can communicate without direct dependencies. This pattern makes the system more modular and easier to extend, as components can simply listen for events without needing to know the implementation details of the emitters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7972d19a-deaf-4b97-a9f6-0620a16396c0', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the difference between SQL and NoSQL databases regarding schema design?', N'Junior', N'SQL databases require a predefined, rigid schema where all data must fit into tables with specific columns and types. NoSQL databases offer a flexible schema, allowing data to be stored in formats like JSON documents without needing a fixed structure beforehand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'005c9555-3662-4c80-ad66-0621bb79e886', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a Hinted Handoff?', N'Intern', N'Hinted handoff is a mechanism that helps maintain consistency when a node is temporarily unavailable during a write. The coordinator node stores a ''hint'' and sends the data to the failed node once it comes back online.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1094aa1f-c4a8-481a-8227-062350a331e9', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is a request guard ''FromRequest'' trait?', N'Intern', N'The FromRequest trait is what allows a type to be used as a request guard. By implementing this trait, you define the logic that determines if a request is valid enough to proceed to the handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da4bdcc2-a101-4e0f-bf5d-0626977588a5', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the purpose of the Meta function?', N'Junior', N'The Meta function allows you to define meta tags for a specific route, such as the page title, description, and Open Graph tags. These are rendered into the document head, which is crucial for social media sharing and search engine visibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cf52189-9e57-4b44-9163-062970d56047', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle request timeouts?', N'Junior', N'Fiber can be configured with a ReadTimeout and WriteTimeout to ensure that connections do not stay open indefinitely. This helps prevent resource exhaustion from slow clients.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71b09cb3-b1b7-4a5a-84a3-0629bd6873c2', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the potential issues caused by hoisting?', N'Intern', N'Hoisting can lead to unexpected behavior in JavaScript because variable and function declarations are moved to the top of their containing scope during the compilation phase. This can result in undefined values for variables if they are used before their declaration and can cause confusion with function declarations and expressions. For example: ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3b11bbd-a69d-4d1c-9d46-062e91a86fed', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle a situation where you realize your initial approach to a problem is wrong?', N'Intern', N'I would pause the work, document why the initial approach failed, and pivot to an alternative method. It is better to acknowledge a dead end early than to continue investing time in a solution that will not work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb8d83f9-8f2a-4f54-a57a-062ebf0d756f', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the difference between synchronous and asynchronous code in Express?', N'Intern', N'Synchronous code executes line by line, blocking the event loop until it finishes. Asynchronous code allows the server to continue handling other requests while waiting for long-running tasks, such as database queries, to complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c885955-2ddb-4884-974b-0632528aa2c2', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How do ''Extension Methods'' work at the compiler level, and what are their limitations?', N'Senior', N'Extension methods are syntactic sugar that the compiler transforms into static method calls. They cannot access the private or protected members of the extended type, and they cannot override existing instance methods. They are resolved at compile-time, meaning they do not support dynamic dispatch based on the actual runtime type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6a0ef4c-2bd0-49a7-93c3-0632ac14315b', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How should one implement graceful shutdown in a Fiber application to ensure data integrity?', N'Senior', N'Graceful shutdown involves catching OS signals like SIGTERM and calling the application''s shutdown method, which stops accepting new connections while allowing active requests to finish within a specified timeout. This prevents abrupt termination of database transactions or ongoing processing tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'170f7e25-c644-46f2-b873-0634cde2828a', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the role of the ''root'' file in a Remix project?', N'Intern', N'The root file acts as the main layout component for the entire application. It contains the base HTML structure, such as the head and body tags, which are shared across all pages in the project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5ac330d-9ef1-4188-88ea-0635676ee00b', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the benefit of using ''Router'' objects in large Litestar applications?', N'Middle', N'Routers act as sub-applications that can be used to group related routes into distinct logical units. This allows for hierarchical API design, where different teams or modules can manage their own routes, dependencies, and middleware independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca7e81ed-08ed-43b3-aeed-0635a81540b2', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS leverage RxJS internally, and what are the architectural trade-offs of using Observables over Promises in a NestJS controller?', N'Senior', N'NestJS uses RxJS for its deep integration with interceptors and its ability to handle streams of data natively. While Observables provide superior handling for complex asynchronous sequences and backpressure, they introduce a steeper learning curve and potential memory leaks if subscriptions are not handled properly compared to the simpler, standard Promise-based async/await pattern.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c202a81b-8d2b-4b14-9679-063806f770d6', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Describe how you would design a system to process large volumes of streaming data with low latency.', N'Senior', N'I would use a distributed message streaming platform like Apache Kafka to decouple producers and consumers. I would then implement a stream processing framework that allows for parallel data partitioning, ensuring that consumer groups can scale horizontally to handle backpressure and maintain low processing latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3921f634-90fe-4f01-94d7-063a3e1a8f76', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go handle errors?', N'Intern', N'Go treats errors as values that are returned as the final return value of a function. It encourages explicit error checking, where the caller is responsible for checking if the returned error is non-nil before proceeding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6daa3dc-3842-4da6-8622-063c7cc87c3c', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Can Preact be used in a Micro-frontend architecture more effectively than React?', N'Senior', N'Preact is highly effective for micro-frontends because its small size minimizes the ''download penalty'' when multiple, independent micro-apps are loaded on a single page. Unlike React, which can lead to significant cumulative bundle sizes, Preact ensures that the performance impact of adding new micro-frontends remains negligible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e68fef6-92b6-4853-bc34-063d5d3394d7', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Describe the trade-offs of using Nuxt''s ''Route Rules'' for caching and rendering strategies.', N'Senior', N'Route rules allow granular control over rendering (SSR, CSR, SSG) and caching strategies at the edge level. The trade-off is increased complexity in infrastructure configuration, but it provides significant performance gains by offloading compute-heavy tasks to the CDN.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'236408ec-8bfd-4d92-85a4-063e1ca47525', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the primary key in DynamoDB and what are its two types?', N'Junior', N'The primary key uniquely identifies an item in a table. The two types are a Partition Key, which determines the physical location of the data, and a Composite Primary Key, which consists of both a Partition Key and a Sort Key for more granular data organization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62a666b5-f924-42de-9be3-063eac720d47', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify''s hook system differ from Express middleware?', N'Senior', N'Fastify hooks are lifecycle-bound, meaning they trigger at specific stages like request, pre-handler, or on-send, rather than being a linear chain of middleware. This structure provides more granular control over the request lifecycle and allows for better optimization of the execution path, as hooks are executed only when necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ce48215-1d49-45af-815c-063f6bed7ae2', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How do you handle redirects in a Next.js application?', N'Middle', N'Redirects can be managed at the configuration level in ''next.config.js'' for permanent URL restructuring or programmatically using the redirect function within server-side code. This ensures a seamless transition for users and maintains SEO integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22b5283c-3758-4481-a6ad-0642899015e9', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the difference between a class and an object in Ruby?', N'Intern', N'A class is a blueprint or template that defines the structure and behavior of objects. An object is a specific instance created from that class, representing a concrete entity in the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56051a8c-e735-4e9d-8c63-0642e0b5b7d2', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What architectural challenges arise when integrating Kotlin''s ''Internal'' visibility modifier with multi-module projects?', N'Senior', N'The ''internal'' modifier restricts visibility to the same module, which is effective for encapsulation but creates strict boundaries that can complicate testing or cross-module utility sharing. Developers must often expose internal APIs via ''@InternalAPI'' annotations or ''friend'' modules to bridge these gaps without breaking the intended encapsulation boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'222a4568-c1f4-47d9-b7e1-0643ac09a688', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the purpose of the __call__ method?', N'Middle', N'The __call__ method allows an instance of a class to be invoked as if it were a function. This is useful for creating objects that maintain state between calls, such as function objects or complex decorators. It enables a more functional style of programming while leveraging the features of an object-oriented design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1904512-0066-46cf-84eb-06446046ac4d', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is a ''Handler'' in Rocket?', N'Intern', N'A handler is a function that processes an incoming web request. It receives input from the request, performs logic, and returns a value that is converted into an HTTP response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5b824b2-5fe7-49a6-848d-0644f733ec5b', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What architectural patterns facilitate API evolution without forcing clients to upgrade immediately?', N'Senior', N'Adopting a strict ''expand and contract'' pattern allows the API to support multiple response formats simultaneously. By adding new fields while keeping old ones and only removing them after monitoring usage metrics, you provide a safe migration path for consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e84797b-9af1-473c-85e2-064a50f409cc', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'When should you use a Job instead of an Event?', N'Middle', N'You should use a Job when you need to perform a background task that can be queued and processed asynchronously to improve performance. Use an Event when you want to broadcast that something happened, allowing multiple listeners to react independently to that specific occurrence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12ba814d-4fb9-4dc8-9b6b-064a9d0c466a', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you handle configuration management in Flask across different environments?', N'Middle', N'Configuration should be managed using a base class for common settings and subclasses for specific environments like production or testing. You can load these settings using app.config.from_object or environment variables. This approach keeps sensitive information like database credentials out of the source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba063623-898e-4f70-949e-064aecf6de14', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the architectural implications of ''Circular Dependencies'' in Spring and how they are resolved.', N'Senior', N'Circular dependencies occur when two or more beans depend on each other, preventing the container from fully initializing them. While Spring can resolve simple setter-based circularities via early reference injection, they are generally considered a code smell that indicates poor architectural boundaries and should be resolved by refactoring into shared services or event-driven communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a39bd41e-e854-4d05-9132-064bdb0cfe47', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Explain the concept of ''False Sharing'' in multi-threaded programming.', N'Senior', N'False sharing occurs when multiple threads modify independent variables that reside on the same CPU cache line. This causes the cache coherence protocol to force the cache line to be reloaded across cores, creating significant contention and performance degradation even though there is no logical dependency between the variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ad5c567-5b27-427f-b6b4-064d40e95221', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How do you handle global CSS in Nuxt?', N'Fresher', N'Global CSS is handled by adding your style files to the css array within the nuxt.config.ts file. This ensures that these styles are included in the final build and applied across the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aeea93c8-f748-41ec-be19-064e87181575', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the primary architectural model of Cassandra?', N'Intern', N'Cassandra uses a peer-to-peer architectural model where all nodes in the cluster are equal. This design ensures that there is no master node, which prevents single points of failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdefeb87-2a57-4399-a7a9-064eb1b4041d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you evaluate the trade-offs between high availability and consistency when designing a distributed database?', N'Senior', N'I reference the CAP theorem to determine if the system prioritizes partition tolerance. I evaluate the business impact of stale data versus downtime; for financial systems, I would favor strong consistency, whereas for social feeds, I would prioritize availability and eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51c84f4e-94aa-4892-83f3-064fa0d4d824', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What happens if you dispatch an action that does not match any type defined in your reducer?', N'Fresher', N'If an action does not match any case in the reducer, the reducer should return the current state unchanged. This ensures that the application state remains stable when irrelevant actions are dispatched.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e726c26f-1181-4db3-b17e-064fc7cf9660', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the benefit of the ''sass-loader'' in a Webpack environment?', N'Middle', N'The sass-loader allows Webpack to process Sass files during the build process, converting them into valid CSS. It enables features like hot module replacement for styles and seamless integration with other CSS-related loaders like PostCSS for autoprefixing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b847103-7b17-4321-bf31-06524743cec7', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the primary difference between the ''any'' type and the ''unknown'' type in TypeScript?', N'Junior', N'The ''any'' type disables type checking entirely, allowing any operation on the variable. In contrast, ''unknown'' is a type-safe alternative that requires you to perform type narrowing or checks before executing operations on the value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ae40265-79e8-453a-a42b-065548f000aa', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is an object in Dart?', N'Intern', N'In Dart, almost everything is an object, including numbers, functions, and null. All objects inherit from the root Object class, which provides basic functionality like equality checking and string representation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca7177b2-a9d3-41b3-829c-06564d372d0c', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain how you can access sessions in Flask?', N'Fresher', N'A session basically allows you to remember information from one request to another. In a flask, it uses a signed cookie so the user can look at the session contents and modify. The user can modify the session if only it has the secret key Flask.secret_key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
