INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24fa9d99-1884-42d9-8aa5-065cb4b78234', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''never'' type in TypeScript?', N'Fresher', N'The ''never'' type represents values that will never occur, such as a function that always throws an error or an infinite loop. It is useful for exhaustive checking in switch statements to ensure all possible cases are handled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66ec648a-4e44-43d9-a08a-0661449f097e', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript’s structural typing system affect binary size and runtime performance?', N'Senior', N'TypeScript’s structural typing is a compile-time construct that is completely erased during transpilation. Because the type information does not exist at runtime, there is no impact on binary size or execution speed, as the JavaScript engine only sees the underlying logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5625ef80-f921-4bfb-a298-06629e5710e0', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using a managed service or self-hosting infrastructure?', N'Junior', N'I choose managed services to reduce the operational burden of maintenance, backups, and security patching, which is ideal for small teams or non-differentiating infrastructure. I consider self-hosting only when there are strict compliance requirements, specific configuration needs, or significant cost savings at scale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e949cf5-74c2-4680-886d-06660ebb38a7', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the impact of replication lag on user experience?', N'Middle', N'Replication lag can cause users to see stale data, such as a post they just created not appearing immediately on a refresh. To mitigate this, developers may use read-your-writes consistency or route critical reads to the primary instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
