INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'144490b8-a82f-4e6d-bcc1-0666e3b2bbc1', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is an embedded server in Spring Boot?', N'Intern', N'An embedded server is a web server, such as Tomcat, Jetty, or Undertow, that is included directly within the application''s executable JAR file. This allows the application to run as a standalone process without needing to install or configure an external application server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8e7e112-89f1-450a-ab59-0669da039eb4', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the ''cone of uncertainty'' and how does it relate to your estimation process?', N'Junior', N'The cone of uncertainty is a concept where estimates are highly inaccurate at the start of a project and become more precise as more information is gathered. I use this to explain to stakeholders that early-stage estimates are broad guidelines and should be refined as development progresses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'896fda49-7c6a-48f8-92e2-066db1fcc4d8', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the role of the ''next'' function in Express middleware?', N'Junior', N'The next function is a callback that tells Express to pass control to the subsequent middleware function in the stack. If it is not called and the response is not sent, the request will hang indefinitely, causing the client to time out.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37ca7ac5-d43f-4cb4-9143-066df1f50ea4', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Describe the ''Bulkhead'' pattern in the context of API reliability.', N'Senior', N'The bulkhead pattern isolates resources like thread pools or connection limits for different parts of an API, preventing a failure in one area from consuming all system resources. This containment ensures that a high-load or failing service does not bring down the entire API infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33292c94-4fae-4930-813a-066f4334ed5e', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB ensure ACID transactions across multiple items?', N'Senior', N'DynamoDB uses a two-phase commit protocol to manage transactions across multiple items or tables. This provides atomicity, consistency, isolation, and durability, but comes with a performance cost in terms of doubled throughput consumption and increased latency compared to standard requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a85975b2-0f24-4d0e-9ec3-066fe0551350', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript handle ''discriminated unions'' for state management?', N'Senior', N'Discriminated unions use a common literal property across all members of a union to help the compiler narrow the type effectively. This allows for exhaustive checking in switch statements, ensuring that all possible states of a component or action are handled safely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
