INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df2b72ff-0976-417c-bab5-06707cdfb684', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle event listeners compared to standard DOM events?', N'Junior', N'Preact uses a synthetic event system that normalizes events across different browsers. It attaches a single event listener to the root of the document to manage events efficiently via event delegation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1ed6e88-d33d-443f-8b76-06710cf9a2c4', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Why is it important to use Interfaces for services?', N'Middle', N'Using interfaces promotes the dependency inversion principle, allowing you to swap implementations without changing the code that consumes the service. This makes the system more modular and significantly easier to mock during unit testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8f0aa68-e23f-4536-9e3b-0671bb9aaa44', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the core philosophy of the Ruby programming language?', N'Fresher', N'Ruby was designed with a focus on developer happiness and productivity. It emphasizes the principle of least astonishment, meaning the language should behave in a way that minimizes confusion for experienced users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2af7485c-6018-4252-92df-0671cda216d5', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'Why is it important to define the ''expected output'' before starting an engineering task?', N'Intern', N'Defining the expected output provides a clear goal and a metric for success. Without a defined target, it is easy to lose focus or over-engineer a solution that does not actually satisfy the original requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f5de65a-3628-4646-96f5-0671e936c302', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Why is the distinction between ''lists'' and ''vectors'' fundamental to R''s memory model?', N'Senior', N'Vectors are atomic, contiguous memory blocks that provide high performance for numeric operations, while lists are collections of pointers to other objects. Lists are more flexible for complex data structures but have higher memory overhead and slower access times due to pointer dereferencing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f43449ed-30f0-4630-b1b0-0672eb9ec3ed', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is meant by data consistency?', N'Fresher', N'Data consistency ensures that any data written to the database must be valid according to all defined rules, constraints, and triggers. It guarantees that the database remains in a correct state before and after any transaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'919aa8d7-c679-49b2-a093-0673d58203aa', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How can you prevent a Node.js application from crashing due to an unhandled exception?', N'Middle', N'You should implement global ''uncaughtException'' and ''unhandledRejection'' handlers, although these should primarily be used for logging and graceful shutdown. Proper error handling should be done at the local level using try-catch blocks and promise error handlers to ensure the application remains stable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f7c5c62-a462-41cb-b38f-067569aa6133', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the difference between ''def'' and ''async def'' in FastAPI path operations?', N'Junior', N'Using ''def'' runs the function in an external thread pool so it does not block the main event loop, while ''async def'' runs the function directly on the event loop. ''Async def'' is preferred for I/O-bound operations to maximize performance, while ''def'' is useful for CPU-bound tasks or legacy synchronous libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47eee729-0e55-4913-ae8e-0676cda0cf77', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the primary difference between a checked and an unchecked exception in Java?', N'Middle', N'Checked exceptions are verified at compile-time, forcing the developer to either catch or declare them in the method signature. Unchecked exceptions, which extend RuntimeException, do not require explicit handling and typically represent programming errors or unrecoverable conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ca26328-c13c-4b11-9f98-0676f35f664f', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is an argument in an R function?', N'Intern', N'An argument is a value or input passed to a function that tells it how to behave or what data to process. Functions may have mandatory arguments that must be provided and optional arguments with default values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6413af1f-2df9-4ada-bd50-067837c16357', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What factors influence the decision to render a page on the server versus the client in Next.js?', N'Senior', N'Server rendering is preferred for SEO, initial load performance, and accessing sensitive data securely. Client rendering is reserved for highly interactive components that require frequent state updates, browser-specific APIs, or event listeners that cannot be executed on the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e381bdb3-56cd-4c50-894b-067aa5f5822c', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the advantage of Astro''s ''zero-bundle-size'' approach?', N'Fresher', N'By eliminating unused JavaScript, the browser does not need to download, parse, and execute massive bundles. This leads to faster Time to Interactive and better performance scores on mobile devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
