INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3da86669-daae-4ed1-adc4-0680307edced', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Explain the significance of Alpine.js''s ''magic properties'' and how they interact with the underlying Proxy objects.', N'Senior', N'Magic properties like $store or $refs provide a consistent API to access the internal state and DOM elements without polluting the global scope. They serve as abstraction layers that safely interact with the reactive Proxy objects, ensuring that developers can trigger reactivity or DOM access without manually interacting with the engine''s internal implementation details.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2362a80-6afc-492b-91c4-068313d5908b', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the role of ''Controllers'' in Litestar?', N'Fresher', N'Controllers are classes used to group related route handlers together. They help organize the codebase by allowing developers to define common configuration or base paths for a set of related endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d0eb620-7f7e-474e-8658-068626020af3', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the architectural significance of the Ember Data adapter and serializer pattern?', N'Senior', N'This pattern decouples the application''s internal data model from the external API''s payload structure. Adapters handle the transport layer and URL construction, while serializers normalize diverse backend formats into a unified JSON:API structure, ensuring the application layer remains agnostic to backend schema changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9912a61-955c-4261-ae37-0687f6f61f3a', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the difference between Asynchronous and Non-blocking?', N'Fresher', N'1. Asynchronous: The architecture of asynchronous explains that the message sent will not give the reply on immediate basis just like we send the mail but do not get the reply on an immediate basis. It does not have any dependency or order. Hence improving the system efficiency and performance. The server stores the information and when the action is done it will be notified. 2. Non-Blocking: Nonblocking immediately responses with whatever data available. Moreover, it does not block any execution and keeps on running as per the requests. If an answer could not be retrieved then in those cases API returns immediately with an error. Nonblocking is mostly used with I/O(input/output). Node.js is itself based on nonblocking I/O model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4b0ad1c-3e70-4ffb-b7ee-0688df764d44', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you approach a problem if you have very little historical data to guide your estimate?', N'Intern', N'I would rely on first-principles reasoning to break the problem down into fundamental, verifiable truths. I would look for industry benchmarks, consult with subject matter experts, or perform a small-scale pilot to gather initial data. This helps build a logical foundation for the estimate despite the lack of direct history.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1d35446-4e43-46f1-8ea5-06898f7cdc1c', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut''s modular design contribute to reduced memory consumption in serverless environments?', N'Senior', N'Micronaut''s modularity ensures that only the necessary dependencies are packaged and loaded, resulting in a minimal JAR size. Combined with its AOT-compiled bean initialization, this leads to extremely fast cold start times and lower memory usage, which are critical for cost-effective serverless execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ddfa41d-1e52-4a6c-8b6b-068bf458169e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are Symbols used for in JavaScript?', N'Intern', N'Symbols in JavaScript are a new primitive data type introduced in ES6 (ECMAScript 2015). They are unique and immutable identifiers that are primarily used for object property keys to avoid name collisions. These values can be created using the Symbol(...) function, and each Symbol value is guaranteed to be unique, even if they have the same key/description. Symbol properties are not enumerable in for...in loops or Object.keys(), making them suitable for creating private/internal object state. Note: The Symbol() function must be called without the new keyword. It is not exactly a constructor because it can only be called as a function instead of with new Symbol(). ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7041d07d-33e8-47f6-a007-068e6d5e077e', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Explain the concept of a ''thunk''.', N'Middle', N'A thunk is a function returned by an action creator that can perform side effects and delay the dispatch of an action. It provides a way to execute logic before or after an asynchronous operation completes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60d8438e-129d-420a-a7ea-0691a299716f', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Compare Django''s template engine performance with decoupling the frontend as a SPA.', N'Senior', N'The Django template engine renders HTML server-side, which is efficient for SEO but tightly couples the backend to the UI. Moving to a SPA architecture shifts rendering to the client, improving interactivity and separation of concerns, but introduces challenges with API versioning, state management, and initial load performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'474d42c4-52ad-4be7-862b-069303326f62', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Discuss the performance impact of Tailwind''s ''apply'' directive in large-scale applications.', N'Senior', N'The ''apply'' directive essentially reintroduces the maintenance overhead of traditional CSS classes. Overusing it can lead to larger CSS bundles and complicates debugging, as it obscures the direct mapping between the HTML class list and the final rendered styles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'218c4242-2f3e-459a-b75e-0696c9694fa3', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'When migrating a monolithic database to a microservices architecture, how do you handle data consistency across service boundaries?', N'Senior', N'I would move away from distributed transactions and adopt the Saga pattern or event-driven architecture using an outbox pattern for reliable messaging. This ensures eventual consistency by coordinating local transactions across services via asynchronous events, while maintaining idempotency to handle potential retries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'070d0880-d8a5-4cb2-b4ba-06971734bc72', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are the trade-offs of using ''View Components'' versus ''Partial Views'' in ASP.NET Core?', N'Senior', N'Partial Views are simple and share the parent''s model, making them easy to implement for UI reuse. View Components are more robust, featuring their own logic and dependency injection capabilities, which makes them better for complex UI widgets that need to retrieve their own data independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'269b91db-d281-4d89-8d7c-0697bbbf482e', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does C manage function call overhead and stack frame layout?', N'Senior', N'The C standard does not mandate a specific stack layout, but most implementations use the calling convention defined by the Application Binary Interface (ABI). This involves pushing arguments onto the stack or into registers, saving the return address and frame pointer, and allocating local variables within a stack frame.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
