INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2360b537-8621-489f-9c9c-06dd4ac62de9', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'A microservice is failing intermittently during high traffic spikes. How do you identify the root cause?', N'Middle', N'I would start by examining distributed tracing logs to identify which specific component is timing out or throwing errors. I would check resource utilization metrics like CPU, memory, and thread pool saturation to determine if the issue is due to resource contention or an upstream dependency failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce1f1da6-944e-45e2-a5d3-06de0ab7930a', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does the mixin system in Dart differ from traditional class inheritance?', N'Middle', N'Mixins allow developers to reuse class code across multiple class hierarchies without the limitations of single inheritance. Unlike standard inheritance, mixins act as ''pluggable'' behavior, enabling a class to incorporate methods and properties from multiple sources while avoiding the complexity of diamond-shaped inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'211e95f0-3519-4803-97df-06dec6201ab3', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the role of rate limiting in maintaining system scalability?', N'Middle', N'Rate limiting restricts the number of requests a user or service can make within a specific timeframe. It protects the system from being overwhelmed by spikes in traffic, malicious actors, or misconfigured clients, ensuring fair resource distribution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10b58bb5-2ca9-44d9-a4d2-06dfbc3a99e9', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Why should you avoid using ''attach()'' in R scripts?', N'Middle', N'The attach function adds a data frame to the search path, which can lead to ambiguity and name masking, making it difficult to track where a variable originated. It is considered poor practice because it creates dependencies on the order of operations and makes debugging significantly harder.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c71a102-308c-44cb-b128-06e0b5644d2b', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Why is idempotency critical in distributed API design and how do you implement it?', N'Senior', N'Idempotency ensures that multiple identical requests have the same effect as a single request, which is vital for handling network retries in distributed environments. It is typically implemented by having the client provide a unique idempotency key in the request header, which the server uses to track and prevent duplicate processing of state-changing operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'968f311c-9636-4e0c-b483-06e2c93a84cc', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a schema in a database?', N'Intern', N'A schema is the formal structure or blueprint that defines how data is organized in a database. It describes the tables, fields, data types, and the relationships between them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63b1ef45-94c1-4e2e-a959-06e3dd6d739d', N'075b8862-431c-4678-9767-f55359758a4a', N'What are composition functions?', N'Intern', N'Composition API is a set of additive, function-based APIs that allow flexible composition of component logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb7e9579-2411-458a-9821-06e3ecb2e17d', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does the ''Registry'' module in Phoenix improve the scalability of process discovery?', N'Senior', N'The Registry provides a distributed, partitionable key-value store for process names, allowing efficient lookup of processes across a cluster. It solves the scalability bottleneck of the global process registry by allowing developers to partition the registry into multiple tables, reducing contention in high-traffic applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2af4b57-20bc-46f1-a731-06e55c0c1a95', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of the Micronaut CLI?', N'Fresher', N'The Micronaut Command Line Interface (CLI) is a tool used to generate project skeletons, create beans, controllers, and services, and run the application. It helps developers quickly scaffold new microservices without manual configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f596ddfc-ef42-471d-8e8d-06e65029fce8', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is Quarkus?', N'Intern', N'Quarkus is a Kubernetes-native Java framework tailored for GraalVM and HotSpot. It is designed to optimize Java for serverless, cloud, and containerized environments by reducing memory usage and startup time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'becf5e8b-dddb-4764-8e82-06e91fd64194', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What considerations do you make when choosing between a managed cloud service and a self-hosted solution?', N'Middle', N'I weigh the total cost of ownership, including engineering time for maintenance and patching versus the subscription cost. Managed services are generally preferred to offload operational overhead, unless there are strict data sovereignty requirements or specific performance tuning that managed services cannot provide.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bda3433-a40a-4a68-ba03-06eaacf179d4', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are default parameters', N'Intern', N'In ES5, we need to depend on logical OR operators to handle default values of function parameters. Whereas in ES6, Default function parameters feature allows parameters to be initialized with default values if no value or undefined is passed. Let''s compare the behavior with an examples, The default parameters makes the initialization more simpler,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05f6df6e-710f-4209-944a-06eb084bc83a', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R''s handling of missing data (NA) impact memory layout and performance?', N'Senior', N'R treats NA as a special value within standard vectors, which requires internal bit-masking or sentinel values to handle missingness. This integration simplifies data analysis but prevents the use of primitive machine types for some operations, potentially slowing down arithmetic performance in heavy computation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae63c7a2-ee03-4eb5-a83a-06eb80dc7057', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why might a system work perfectly in development but fail in production?', N'Fresher', N'The production environment often has different hardware, network configurations, security permissions, or data volumes compared to the development environment. Discrepancies in these external factors are common causes for bugs that only appear after deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9009e611-40a7-4a94-a3b6-06ec8c27ea19', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What does it mean for a function to be ''inline''?', N'Junior', N'An inline function suggests to the compiler that it should replace the function call with the actual code of the function body. This can reduce the overhead of function calls for small, frequently used functions, though it may increase the size of the final binary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8f35cf9-eab9-4990-93ae-06f2df564b68', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does a document-oriented database store data?', N'Intern', N'Document-oriented databases store data in self-describing documents, usually in formats like JSON, BSON, or XML. Each document contains pairs of fields and values, allowing for nested data structures and flexible schemas that can evolve without altering the entire database structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1010a96e-1f96-45fe-87f9-06f4134b5199', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember CLI''s ''Addon'' ecosystem facilitate code reuse and maintainability at scale?', N'Senior', N'Addons allow developers to package reusable functionality, including templates, styles, and logic, into modular libraries. This promotes standard practices across disparate projects and enables teams to share complex integrations, reducing technical debt through centralized maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fc6b4f8-6e0f-4ca3-aae8-06f4de4e88f3', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the role of the Write-Ahead Log (WAL) in both crash recovery and replication.', N'Senior', N'The WAL ensures durability by recording all changes to data files before they are committed. During crash recovery, PostgreSQL replays the WAL to restore consistency, while in replication, the WAL stream is shipped or streamed to standby servers to maintain data synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2b07c23-14be-49f2-b1e7-06f6b1f5cea2', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is Alpine.js''s relationship with the DOM?', N'Intern', N'Alpine.js is a DOM-based framework, meaning it treats the HTML as the primary source of truth. It observes the DOM and attaches listeners and reactive proxies to elements to keep them synchronized with the underlying data state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bc4c5b6-899f-4e0a-81b2-06f73e66cdb5', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Explain the difference between a Route module and a Layout route in Remix.', N'Junior', N'A Route module represents a specific URL path, while a Layout route is a parent route that wraps nested child routes. Layouts are used to share persistent UI elements like navigation bars or footers across multiple pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99cb29df-0a58-4cd7-bc8a-06f76a50854c', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the difference between RDB and AOF in Redis?', N'Intern', N'RDB creates point-in-time snapshots of your dataset at specified intervals, which is efficient for backups. AOF logs every write operation received by the server, which provides better durability by reconstructing the dataset on startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79dbabb7-9676-4596-9d84-06f8c7abd558', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the purpose of the Identity Map pattern and whether Rails uses it.', N'Middle', N'An Identity Map ensures that each database row is represented by only one object instance in memory during a single request. Rails does not implement a global Identity Map by default because it can lead to memory bloat and stale data issues, instead relying on standard ActiveRecord instantiation per query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4823f1fd-5486-42f7-a0e0-06fb394d5d39', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi performance compare to other Go routers?', N'Intern', N'Chi is highly performant and is designed to have very low overhead. While there are faster routers that use highly optimized radix trees, Chi strikes a balance between speed and ease of use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25948eb2-7206-4c77-b8b7-06fd8bb5b27a', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R manage memory compared to lower-level languages like C++?', N'Middle', N'R manages memory automatically through a garbage collector that tracks objects and frees memory when it is no longer referenced. While this simplifies development, it offers less fine-grained control over memory allocation and release compared to manual management in C++.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2846e4cc-762f-448c-b7a7-0700888b4ce0', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach a situation where an error message is vague or non-descriptive?', N'Fresher', N'When an error is vague, you should look at system-level logs, monitor network traffic, or check the state of variables just before the failure occurs. Gathering auxiliary data helps fill in the gaps left by a generic error message.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'573e46b4-b5ca-462d-a252-07009e725aef', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach choosing between a SQL and a NoSQL database for a high-traffic service?', N'Senior', N'Analyze the data structure and access patterns; SQL is preferred for complex relational queries and ACID compliance, while NoSQL is better suited for horizontal scaling, schema flexibility, and high-velocity ingestion of unstructured data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f09f7efa-0a7f-4177-bb12-0700e5733b73', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What does it mean for a framework to be ''content-driven''?', N'Intern', N'A content-driven framework is optimized for websites where the primary goal is displaying text, images, and other media to users. Astro is built this way to ensure that blogs, documentation, and marketing sites are exceptionally fast.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ed55803-e0b1-4feb-865f-07036e70372c', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the difference between a database and a database management system?', N'Intern', N'A database is the organized collection of structured information or data. A database management system is the software application that allows users to interact with the database to create, read, update, and delete data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ac3fe8e-b44b-4ad1-8ae7-07038d8b520c', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between Entity Framework Core and Dapper?', N'Junior', N'Entity Framework Core is an Object-Relational Mapper that provides a high-level abstraction for database operations, handling SQL generation automatically. Dapper is a micro-ORM that is much thinner and requires the developer to write raw SQL, offering better performance at the cost of more manual effort.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bec3501-4fdf-4031-b14d-07042e0d1f05', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between code reusability and specificity?', N'Fresher', N'Highly reusable code is flexible and reduces redundancy, but it often becomes bloated with parameters to handle various cases. Specific code is simple and optimized for one task, but it leads to duplication if similar tasks arise later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df069c92-02d2-4fc2-b5fe-070606dc43d9', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the purpose of the ''line-height'' property?', N'Junior', N'The line-height property controls the amount of space between lines of text. It is crucial for improving readability and is often set as a unitless multiplier for better flexibility when font sizes change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4aa3d8a-813e-4832-83cd-0706140ea5f2', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a Generic constraint and why is it used?', N'Middle', N'Generic constraints restrict the types that can be used as arguments for a generic parameter by requiring them to satisfy a specific interface or condition. This ensures that the generic function or class can safely access the required properties of the type being passed in.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5870b109-e6ef-46d9-abca-070b2b2a3473', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the main benefit of using a Content Delivery Network (CDN)?', N'Fresher', N'A CDN stores copies of static website assets on servers located around the world, closer to the users. This significantly reduces latency and improves load times because the data has to travel a shorter physical distance to reach the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5cc7a0c-62c8-48eb-864b-070b49d9b577', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is Spring Boot Starter and why is it useful?', N'Junior', N'A Spring Boot Starter is a set of convenient dependency descriptors that you can include in your application. They are useful because they group together all the necessary dependencies for a specific feature, like web development or database access, reducing the need to manually manage version compatibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a9c1341-0684-4286-a95d-070b62e45881', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does the createEffect primitive work?', N'Junior', N'The createEffect function runs a side effect whenever any of its tracked dependencies change. It is primarily used for tasks like manual DOM manipulation, logging, or interacting with external APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66daa02b-d797-4207-9250-070c7d7235c4', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are default props?', N'Intern', N'The _defaultProps_ can be defined as a property on the component to set the default values for the props. These default props are used when props not supplied(i.e., undefined props), but not for null or 0 as props. That means, If you provide null value then it remains null value. It''s the same behavior with 0 as well. For example, let us create color default prop for the button component, If props.color is not provided then it will set the default value to ''red''. i.e, Whenever you try to access the color prop it uses the default value', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4a26ee6-1d73-41ff-86ff-070e160503d3', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS maintain reactivity in a list rendering?', N'Middle', N'SolidJS uses a specialized ''For'' component that maps data to DOM elements and tracks changes at the item level. Instead of re-rendering the whole list, it uses efficient DOM diffing to add, move, or remove only the specific elements that changed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd9c2b6f-43f4-4a1f-b014-070e304429c3', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of ''app.set()'' in Express?', N'Junior', N'The app.set() method is used to assign a setting name to a value. This is commonly used to configure application settings like the template engine, the views directory, or environment-specific variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
