INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1b63dd7-8337-4484-8303-0713c427ec32', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a primary key and why is it important in a relational database?', N'Fresher', N'A primary key is a column or a set of columns that uniquely identifies each row in a table. It is essential because it ensures that no two records are identical and provides a reliable way to reference specific data across different tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
