INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e2f1979-6018-4fa1-95ca-0723a5490be4', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is SQL injection?', N'Junior', N'SQL injection is a security vulnerability where an attacker manipulates a database query by inserting malicious input. This can be prevented by using prepared statements and parameterized queries, which treat user input as data rather than executable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f657a54-9736-4a92-b5e4-072758c3c864', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind support multi-platform development (Web and Native)?', N'Middle', N'Tailwind is primarily for the web, but tools like NativeWind allow developers to use Tailwind syntax in React Native. This bridges the gap by mapping Tailwind classes to the underlying native styling engine, allowing for a shared styling language across web and mobile platforms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24ffc213-b61e-414f-9367-0727d276bf8d', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why are backups and data recovery plans essential for engineering teams?', N'Intern', N'Data loss can result from hardware failure, human error, or malicious attacks. A robust backup plan ensures business continuity, allowing a team to restore the system to a previous state and minimize downtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3aabe0a2-b369-4f7a-a5f7-072e1f1353df', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why is it important to use semantic HTML for SEO and screen reader interoperability?', N'Senior', N'Semantic elements provide machine-readable context, allowing search engine crawlers to accurately interpret page structure and content hierarchy. For screen readers, these elements provide built-in roles and states, reducing the need for extensive ARIA attributes and creating a more robust, accessible foundation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8db68cdb-4826-406f-823f-072f534d150b', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are the limitations of R''s single-threaded execution model?', N'Middle', N'R''s core execution is single-threaded, meaning it cannot natively utilize multiple CPU cores for a single process without external parallelization libraries. While this simplifies memory safety, it creates a bottleneck for compute-intensive tasks on modern multi-core hardware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ec49777-e4fb-41f5-9c8a-07319ea56f04', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the mechanics of Dart''s event loop and how it handles concurrency.', N'Senior', N'Dart operates on a single-threaded execution model using an event loop that manages two queues: the microtask queue and the event queue. Microtasks are processed immediately after the current task finishes, while the event queue handles asynchronous I/O, timers, and user interaction events, ensuring non-blocking execution without true multi-threading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd1fbc04-edd1-4994-9284-073287d51224', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How do Alpine.js modifiers change the behavior of directives?', N'Middle', N'Modifiers act as configuration flags that extend the functionality of directives, such as .debounce for event listeners or .outside for click-away detection. They allow for complex behavior to be added declaratively without writing additional JavaScript logic for common tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d993678-e999-446d-bb95-07338d4a579f', N'954a0331-deff-4399-b588-96f39fec001d', N'What is a bootstrapping module?', N'Intern', N'In Angular, the bootstrapping module is the root module of your application, typically named AppModule. It''s the starting point that Angular uses to launch your application. It''s configured using the @NgModule decorator and must include a bootstrap array within its metadata. This array lists the components that Angular should bootstrap when the module is bootstrapped. For the root module, this array usually contains just one component, the root component (e.g., AppComponent), which is the first component rendered in the browser''s DOM. The actual bootstrapping process is initiated in the application''s entry file, usually main.ts, by calling platformBrowserDynamic().bootstrapModule(AppModule).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3306de2-2741-4aaf-9130-0734e16f3d3e', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why might you choose serverless functions over dedicated virtual machines or containers?', N'Middle', N'Serverless functions offer extreme scalability and a pay-per-execution model with zero idle cost, which is perfect for bursty workloads. Dedicated containers provide more control over the environment, predictable costs for consistent loads, and avoid the ''cold start'' latency issues inherent in many serverless platforms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce3e6d14-e865-41cd-b8ec-0735cac3b897', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Discuss the scalability of Preact in large-scale enterprise applications versus React.', N'Senior', N'Preact is highly scalable in terms of bundle size and initial load time, making it excellent for performance-critical applications. However, in extremely complex state-heavy apps, React''s concurrent features and mature ecosystem of developer tools provide better long-term maintainability and easier debugging of complex rendering cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66dda52c-7fec-401b-9884-07365b96e180', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle static files?', N'Junior', N'Axum integrates with the tower-http crate, which provides services for serving static files from a directory. You can mount these services to your router to handle file requests alongside your API endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad1b9802-2e2d-4d5e-8565-07372e375223', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is a generic type in Rust?', N'Intern', N'Generics allow you to write code that can work with many different types rather than one specific type. This reduces code duplication by allowing you to define functions or structs that are flexible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3e02c0d-d36e-49e5-a473-07378fd3fdd2', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is ''Semantic Logging'' and why is it important for observability?', N'Senior', N'Semantic or structured logging outputs logs in a machine-readable format like JSON. This enables efficient querying, filtering, and aggregation of log data, which is essential for modern observability platforms to perform automated root cause analysis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bba56253-6edf-4bc3-9fc3-073816b09235', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you handle HTTP methods like GET and POST in Flask?', N'Fresher', N'You can specify allowed HTTP methods in the methods argument of the route decorator. Inside the view function, you can then check the request.method property to execute different logic based on whether the request is a GET for data retrieval or a POST for data submission.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd62be1ed-6430-40c3-8e80-073a193279e1', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the difference between a Model and a Controller in AdonisJS?', N'Intern', N'A Model represents a table in the database and handles data retrieval and manipulation. A Controller handles the incoming HTTP requests, communicates with the model to get the data, and returns the response to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a18ca849-c24e-4043-a1b7-073b84bb0f0b', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut optimize the loading of configuration properties from multiple sources?', N'Senior', N'Micronaut uses a prioritized configuration hierarchy that merges properties from environment variables, system properties, and various configuration files. By evaluating this hierarchy during the bootstrap phase, it ensures that the most specific configuration takes precedence while maintaining an efficient, centralized lookup mechanism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb4e1ab0-2284-4234-96e9-073dcb2dfc00', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo support data rendering?', N'Fresher', N'Echo supports rendering various response formats including JSON, XML, HTML, and plain text. The context object provides specific methods to automatically set the correct content-type header and serialize the data appropriately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b463b89-d52a-4dd2-94ec-073e012bdec5', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why should you avoid direct DOM manipulation in React?', N'Middle', N'React uses a virtual DOM to optimize updates and ensure consistency between the UI and application state. Manipulating the real DOM directly bypasses React''s reconciliation process, which can lead to bugs, inconsistent state, and performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'129ba511-da76-41d0-8fcc-073fb1b054f7', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is a ''split-brain'' scenario in database clusters?', N'Middle', N'A split-brain scenario occurs when a network failure causes a cluster to divide into two or more independent parts that cannot communicate. If both parts continue to accept writes, it leads to data inconsistency that is difficult to reconcile.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b0d2a69-2238-49ef-b9f4-07459f12b6dd', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Why is MongoDB often referred to as a document-oriented database?', N'Junior', N'It is called document-oriented because it stores data in units called documents rather than rows and tables. These documents are self-describing and can contain nested data structures like arrays and sub-documents.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52108bfd-75be-4f6b-9951-07472d93880d', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What makes Qwik particularly effective for e-commerce sites?', N'Junior', N'Qwik is ideal for e-commerce because it ensures the product page becomes interactive almost instantly, even on slow mobile networks. This reduces bounce rates and improves SEO rankings, as performance metrics are critical for modern search engine algorithms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce72d20e-9fa1-4fec-bdcc-07475bb393f4', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the primary goal of conducting a trade-off analysis in an engineering project?', N'Intern', N'The goal is to evaluate competing alternatives to find the optimal solution that best balances performance, cost, and time constraints. It ensures that developers make informed decisions rather than relying on intuition alone.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb090f37-27b6-4b89-9ac3-074888f7a497', N'954a0331-deff-4399-b588-96f39fec001d', N'How to use polyfills in Angular application?', N'Fresher', N'The Angular CLI provides support for polyfills officially. When you create a new project with the ng new command, a src/polyfills.ts configuration file is created as part of your project folder. This file includes the mandatory and many of the optional polyfills as JavaScript import statements. Let''s categorize the polyfills, 1. Mandatory polyfills: These are installed automatically when you create your project with ng new command and the respective import statements enabled in ''src/polyfills.ts'' file. 2. Optional polyfills: You need to install its npm package and then create import statement in ''src/polyfills.ts'' file. For example, first you need to install below npm package for adding web animations (optional) polyfill. and create import statement in polyfill file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
