INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92e50e96-1a64-47eb-be50-074befae675e', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the concept of boxing and unboxing.', N'Fresher', N'Boxing is the process of converting a value type to the object type, which moves it to the heap. Unboxing is the explicit extraction of the value type from the object back to the stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
