INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90a79182-da96-4620-ac29-075a2c825b32', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does the @import rule function in Sass?', N'Fresher', N'The @import rule allows you to include content from other Sass files into the current file. This helps in modularizing your codebase by splitting large CSS files into smaller, more manageable partials that are combined during the compilation process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4214d3ba-3c10-4cfe-8480-075c12fb4e12', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the difference between a global middleware and a named middleware?', N'Junior', N'Global middleware execute on every single request made to the application. Named middleware are assigned to specific routes or route groups, allowing for more granular control over where certain logic is applied.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
