INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd86e2c0c-d7fd-44a4-b470-075d9ef4eb96', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why is it important to use virtual destructors in inheritance?', N'Fresher', N'Using a virtual destructor ensures that when a derived class object is deleted through a base class pointer, the derived class''s destructor is called first. This prevents memory leaks and ensures proper cleanup of derived class resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36ffeafc-2a2f-47a5-91f7-0762a90291cb', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is a constructor in Java?', N'Junior', N'A constructor is a special block of code used to initialize an object when it is created. It has the same name as the class and does not have a return type, ensuring that the object is in a valid state upon instantiation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbf21a02-5d7a-4544-9d33-0763d359c850', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When designing a system for massive scale, how do you decide between vertical and horizontal scaling?', N'Senior', N'Vertical scaling is prioritized when simplicity and lower latency are required and the workload fits within a single machine''s capacity. Horizontal scaling is the default for high-availability systems that require elastic growth, fault tolerance, and the ability to handle unpredictable traffic spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2efb37c-8c10-4d72-9748-0766d1b3b626', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle backpressure when streaming large responses, and how can it be managed?', N'Senior', N'Express does not provide native backpressure management for streams; it relies on the underlying Node.js stream implementation. To handle this, you must manually check the drain event on the response object or use pipeline functions to pipe readable streams into the response to ensure the buffer does not overflow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58a2b0f6-808d-465b-921b-0769312bb114', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of a database index?', N'Intern', N'An index is a data structure that improves the speed of data retrieval operations on a database table. By creating an index on a specific column, the database can find rows much faster without having to scan the entire table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
