INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f078224-f39a-4bcc-9a6d-0793b10547e5', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby handle global state and concurrency safety?', N'Middle', N'Ruby''s Global Interpreter Lock (GIL) ensures that only one thread can execute Ruby bytecode at a time, preventing race conditions in internal data structures. While this protects the interpreter, it means that CPU-bound tasks cannot achieve true parallelism across multiple cores without using separate processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bbe9163-6f17-4603-a81c-0793be68a8f4', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does C handle type casting between different pointer types?', N'Middle', N'C allows explicit type casting between different pointer types, but it is the programmer''s responsibility to ensure the memory being pointed to is compatible with the target type. Casting pointers can lead to serious bugs if it violates strict aliasing rules or results in improper memory alignment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cbf5e6c-457a-4bcf-8b40-0796281f6982', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Explain the concept of ''Payload'' in Nuxt 3.', N'Middle', N'Payload is the data fetched by your app that is serialized and sent from the server to the client. By caching this payload, Nuxt avoids redundant API requests during client-side navigation, which makes subsequent page transitions nearly instantaneous.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd23b63ef-1d6a-4fe4-adf4-0799a2832767', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Compare the impact of synchronous vs asynchronous replication on message durability and performance.', N'Senior', N'Synchronous replication ensures high durability by waiting for multiple replicas to acknowledge the write, but increases latency and reduces availability if a follower lags. Asynchronous replication provides lower latency and higher throughput but risks data loss if the leader fails before replicating the message.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9528c57a-c9cf-4fbb-a954-0799a54e1479', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why are Redux state functions called reducers?', N'Fresher', N'Reducers always return the accumulation of the state (based on all previous and current actions). Therefore, they act as a reducer of state. Each time a Redux reducer is called, the state and action are passed as parameters. This state is then reduced (or accumulated) based on the action, and then the next state is returned. You could _reduce_ a collection of actions and an initial state (of the store) on which to perform these actions to get the resulting final state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bea425c6-7f08-46f6-bc21-0799fd728343', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does the Rails connection pool work and why should you monitor it?', N'Middle', N'The connection pool maintains a set of open database connections that are shared among threads in a multi-threaded application. If the pool is too small, threads will block waiting for an available connection, increasing latency; if it is too large, it can overwhelm the database server with too many concurrent connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'140b39af-80dd-443c-92c4-079c44b9f12a', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Explain the trade-off between memory usage and processing speed.', N'Fresher', N'Caching data in memory allows for significantly faster retrieval times but consumes limited RAM resources. Conversely, reading from disk saves memory but increases latency due to slower I/O operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3b0ae2d-ab1e-4dd0-ba49-079c7af97058', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What does ''reactive'' mean in Svelte?', N'Intern', N'Reactivity means that when the state of a variable changes, the user interface automatically updates to reflect that change. Svelte achieves this by tracking variable assignments and updating only the parts of the DOM that are affected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68234da4-7643-4f60-8229-079dff8abb07', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What factors influence the decision to use a third-party service instead of building a feature in-house?', N'Junior', N'You should consider the core competency of your business, the maintenance effort, and the time-to-market. If the feature is not a strategic differentiator and a reliable third-party service exists, buying or subscribing is usually more cost-effective than building and maintaining it yourself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f251730c-1fdc-46e8-aa28-07a32a2dd251', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Does Axum support middleware, and how is it implemented?', N'Intern', N'Yes, Axum supports middleware through the Tower library. Middleware in Axum allows developers to intercept requests and responses to perform tasks like logging, authentication, or modifying headers before the request reaches the handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64fc48b6-f491-4472-a271-07a40ba71d54', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How do Kotlin''s ''Flow'' streams differ from ''Reactive Streams'' (e.g., RxJava) in terms of concurrency model?', N'Senior', N'Kotlin Flows are built on top of coroutines and are inherently sequential by default, relying on explicit operators for concurrency control, whereas RxJava is designed around a more complex, operator-heavy concurrent push model. Flows provide a more idiomatic and readable way to handle asynchronous streams while maintaining full integration with the structured concurrency of coroutines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23f6e6ad-8548-434c-b7a9-07a84dd4804f', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What are jQuery effects, and give an example?', N'Fresher', N'jQuery effects are built-in methods used to create visual animations on web pages. Examples include .hide(), .show(), .fadeIn(), and .slideToggle(), which change the visibility or appearance of elements over a specified duration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fff286f-05b3-4cdb-80c4-07aba5ba44d5', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain the concept of ''Zero Trust'' architecture and its impact on internal network design.', N'Senior', N'Zero Trust assumes that the internal network is no more trustworthy than the public internet, requiring strict identity verification for every request regardless of origin. This shifts the architectural focus from perimeter-based security to per-service authentication, fine-grained micro-segmentation, and continuous authorization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96a8d8d1-99a1-4009-8652-07ad856298fc', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Describe the purpose and function of Ruby''s method missing hook.', N'Middle', N'Method missing is a hook that is triggered when an object receives a message it does not have a defined method for. It is commonly used for metaprogramming to handle dynamic method calls gracefully, though it should be used cautiously as it can hide bugs if not paired with responding to respond_to_missing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'237a1c31-a77f-4edb-9b89-07b17a9318b3', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How should you approach rate limiting in a Fastify application for better performance?', N'Middle', N'It is best to use a dedicated plugin like fastify-rate-limit that integrates directly into the request lifecycle. By handling rate limiting before costly logic execution, you protect your server resources from being exhausted by malicious or excessive traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6100922-e3ec-408f-9297-07b2e0fa5c16', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Why is observability crucial in a highly scalable architecture?', N'Middle', N'In large-scale systems, identifying the source of performance issues or bottlenecks is difficult due to the complexity and distribution of components. Robust logging, metrics, and distributed tracing provide the visibility needed to debug issues and optimize resource allocation effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
