INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff5609bf-abf4-4e66-8fc8-07bc348b4acf', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are the security implications of using ''form actions'' in SvelteKit, and how are they handled?', N'Senior', N'Form actions centralize server-side mutation logic, providing a built-in mechanism to prevent CSRF via strict request method checking and implicit origin validation. By handling mutations on the server, they keep sensitive business logic out of the client bundle, reducing the attack surface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
