INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e463a6d-c843-496e-87d1-07cd880c4577', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What happens if you don''t return a value in a Fastify handler?', N'Junior', N'If you don''t explicitly send a response or return a value, the request may hang. You must either use the reply object to send a response or return a value (like an object or string) which Fastify will automatically send to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99a16797-4f57-41ee-a1a3-07ced997d480', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the ''Shape'' or ''Hidden Class'' transition system handle objects that change their property structure over time?', N'Senior', N'When an object structure changes, the engine creates a new hidden class and updates the object''s reference to point to it. If an object undergoes too many structural changes, the engine may mark it as ''dictionary mode,'' sacrificing speed for flexibility by using a hash table instead of optimized offset-based access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ce59a30-558a-4f2d-b536-07d1761f2fb7', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is an HTTP Kernel in Symfony?', N'Intern', N'The Kernel is the heart of the Symfony framework that handles the main execution flow. It receives a Request object, runs it through the middleware and routing systems, and returns a Response object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41f01308-44e7-4e28-946c-07d3930ede9d', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a virtual destructor?', N'Junior', N'A virtual destructor is used in base classes to ensure that the correct destructor is called when an object is deleted through a base class pointer. This prevents memory leaks by ensuring resources in derived classes are properly cleaned up.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ed978e3-c4fb-4254-8951-07d87d5ec66a', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Explain the role of ''doctype'' in modern browser rendering modes.', N'Senior', N'The doctype informs the browser to render the page in ''standards mode'' rather than ''quirks mode''. Quirks mode replicates legacy browser behavior which can cause inconsistent layout rendering, so the doctype is essential for ensuring predictable cross-browser CSS and HTML interpretation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0462d0bc-dd05-4b34-b46a-07d96147f3d6', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Explain the importance of ''Build-time Boot'' in Quarkus for serverless scaling.', N'Senior', N'Serverless platforms like AWS Lambda scale by spinning up instances on demand, where cold-start latency is a major cost factor. Build-time boot ensures the framework is pre-configured and ready to serve requests immediately, allowing Java-based applications to compete with faster-starting languages like Go or Node.js.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b59d66b3-c7ac-4c62-a4e8-07de1073c941', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit manage environment variables?', N'Fresher', N'SvelteKit provides a secure way to manage environment variables through specific modules that differentiate between public and private variables. This prevents sensitive server-side configuration from leaking into the client-side code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
