INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3da8291f-a0d4-47a0-bfae-07de1259c392', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between ''let'' and ''var'' inside a closure?', N'Fresher', N'Variables captured by closures are captured by reference, meaning the closure can modify the original variable. Using ''let'' or ''var'' inside a closure''s capture list allows you to define how the variable is captured, such as capturing by value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0ccc7db-0663-494b-ac52-07dee2dc0121', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why does Vite recommend Rollup for production builds instead of using esbuild for the final output?', N'Senior', N'While esbuild is extremely fast, Rollup provides superior tree-shaking, more flexible chunking strategies, and better support for legacy browser compatibility. Rollup’s robust plugin ecosystem is essential for creating highly optimized production bundles that require complex transformation pipelines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ebb1166-9d08-4176-891c-07e0d98b7bc4', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What happens if you forget to call ''next()'' in a middleware function?', N'Junior', N'If you do not call ''next()'' or send a response to the client, the request will hang indefinitely. This causes the client to wait until the request times out, effectively blocking that specific request cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'392c89bc-e3f6-477f-ae41-07e40b262a8b', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What role does the ''links'' export play in a route?', N'Middle', N'The links export allows a component to specify its own external resources, such as stylesheets or prefetch hints. This enables modular asset management where each route explicitly declares its dependencies, which the framework then optimizes for the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32a1ef57-c985-43b4-830b-07e6d5c0a456', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Explain how Rust handles panic unwinding and its impact on system stability.', N'Senior', N'Panic unwinding traverses the stack to run destructors for objects in scope, ensuring resource cleanup before the thread terminates. In embedded environments or performance-critical code, developers often choose abort mode to avoid the binary size and complexity overhead of unwinding logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'196e08b6-4f7f-494a-92bc-07e7a8a16d58', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What are the risks of mixing jQuery with a reactive framework in the same project?', N'Middle', N'Mixing them leads to ''state synchronization'' issues where jQuery modifies the DOM outside of the framework''s knowledge. This causes the framework to lose track of the DOM state, resulting in bugs where the UI and the underlying data model fall out of sync.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
