INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e5bb856-6cd5-44fb-a8bf-07eed8622e8c', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach debugging a cascading failure where one service''s latency causes a system-wide collapse?', N'Senior', N'I would immediately implement circuit breakers and request shedding to isolate the faulty service and prevent it from consuming resources across the cluster. Once stability is restored, I would perform a post-mortem to identify why the upstream services failed to handle the increased wait times, specifically looking for thread pool saturation and lack of adequate timeouts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2eb42441-c961-45e9-bd79-07f22d697aed', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the difference between mutable and immutable objects?', N'Fresher', N'A mutable object is an object whose state can be modified after it is created. An immutable object is an object whose state cannot be modified after it is created. In JavaScript numbers, strings, null, undefined and Booleans are primitive types which are immutable. Objects, arrays, functions, classes, maps, and sets are mutable. Example 01: Immutable (Primitives) Example 02: Mutable (Objects and arrays)', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
