INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd89d8a99-6949-48a7-a07c-07f9ecec61d0', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the role of the Micronaut ''Configuration Properties'' system in a cloud-native environment?', N'Senior', N'The configuration system allows for type-safe binding of external properties into POJOs at compile-time. It supports hierarchical configuration sources, including environment variables and distributed configuration servers, enabling seamless integration with platforms like Kubernetes or HashiCorp Consul.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3329321d-e0e6-4b71-83c0-07fadffbc610', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you approach a trade-off involving security and user convenience?', N'Intern', N'Security and convenience are often inversely related, such as with multi-factor authentication. My approach is to evaluate the risk profile of the data; the more sensitive the information, the more security should be prioritized over ease of access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7694911c-adaf-48e5-be02-07fb988b7bee', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are utility types?', N'Intern', N'Utility types are built-in global types provided by TypeScript to help with common type transformations. Examples include Partial, Readonly, and Pick, which allow you to create new types based on existing ones.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af19c836-9a29-43df-a9a9-07fe4a643e7e', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why should you avoid performing expensive operations inside the ''render'' method?', N'Middle', N'The render method is called whenever the component updates, which can happen frequently during user interaction or data streaming. Performing heavy calculations here can block the main thread and lead to UI jank or unresponsive interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34fc1586-7810-4bf3-89df-08007760d1b4', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is a singleton in Kotlin?', N'Intern', N'A singleton is a design pattern that ensures a class has only one instance and provides a global point of access to it. In Kotlin, this is easily achieved by using the ''object'' keyword.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8d40ca4-3532-40e0-9ed8-08009ac289aa', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the purpose of the ''primary shard'' in a sharded cluster?', N'Senior', N'The primary shard is the specific shard where all un-sharded collections are stored by default. It also acts as the transaction coordinator for distributed transactions, making its health and performance critical for the stability of operations involving multiple shards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'775c7835-40a3-4bf2-a28c-080115ebb956', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux handle the flow of data and actions?', N'Fresher', N'In Redux, the unidirectional data flow concept ensures data consistency by using one-way channels for state and actions. Let''s look at a more detailed overview: Key Elements - Actions: These are objects with a type attribute, describing what needs to change in the application. Actions are dispatched from components and received by reducers. - Reducers: These are pure functions that specify how the application''s state should transform in response to actions. - Store: It''s a single source of truth. It holds the application''s state tree and is responsible for: - State modification through reducers. - State dispatch as actions are sent. One-Way Data Flow 1. Action Dispatch: Components dispatch actions (through store.dispatch(action)). 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0780bcc0-b6d3-47c9-9f17-08060d454122', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'If performance is a requirement, how do you handle the trade-off with security?', N'Fresher', N'I would evaluate if the security measure can be optimized or moved to a non-blocking process. If there is a direct conflict, I would document the risk and ensure the security standard is met first, as performance is often easier to optimize later than security vulnerabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3adf8ac-9ede-4301-93c6-0806b6a1a95f', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is a distributed transaction and why is it difficult to implement?', N'Middle', N'A distributed transaction involves updating multiple independent data sources that must succeed or fail as a single atomic unit. It is difficult because it requires complex consensus protocols like two-phase commit, which can significantly hurt performance and availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74143dfe-8d5e-4491-b23d-080719ac34fd', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How do Kotlin''s ''contract'' APIs affect the compiler''s static analysis capabilities?', N'Senior', N'Contracts allow developers to provide the compiler with explicit information about function behavior, such as whether a lambda is called exactly once or if a function''s return value implies a specific nullability state. This enables smarter smart-casting and more accurate flow analysis that the compiler would otherwise be unable to infer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cba0e4db-95d3-4de5-b38b-080826bc5a2b', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a document in a NoSQL context?', N'Fresher', N'A document is a self-describing unit of data, typically stored as JSON, BSON, or XML. It encapsulates all the information related to a specific entity, including nested data, within one object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4d9f6c4-7b03-4bc7-8c06-0808413bee79', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is nil coalescing?', N'Junior', N'The nil coalescing operator provides a default value to use if an optional contains nil. It essentially unwraps the optional if it has a value, or returns the provided default value instead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c236b00-815e-42a2-954d-080895e70e18', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Why is ''High Cardinality'' a challenge for observability platforms?', N'Senior', N'High cardinality refers to data fields with a very large number of unique values, such as user IDs or request IDs. These fields cause an exponential increase in index size and storage costs in time-series databases, often leading to performance degradation in query engines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f68b410a-deb6-4709-a50a-08098cd9eb22', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the advantages of using the Composition API over the Options API?', N'Middle', N'The Composition API provides better code organization by grouping related logic together, improved type inference for TypeScript, and easier reuse of logic via composables. It avoids the fragmentation of data, methods, and lifecycle hooks often found in large Options API components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e9a24a8-1e0e-4457-9db3-080ac71dc183', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is a class variable and how is it denoted?', N'Junior', N'A class variable is shared among all instances of a class and the class itself. It is denoted by a double ''@@'' prefix and is used to store data that should be common to every instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aae24aa4-4936-4f1c-9cf2-080d4a5e6eee', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How do you handle ''thundering herd'' problems during consumer rebalancing?', N'Senior', N'To mitigate this, implement cooperative sticky rebalancing, which prevents all consumers from stopping simultaneously and minimizes the number of partition movements. Additionally, staggering the startup of new consumer instances and using exponential backoff for connection retries helps smooth out spikes in broker load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2eab61d-6919-4598-8211-080dfebc7aca', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the difference between TTL indexes and regular indexes?', N'Middle', N'A TTL (Time-To-Live) index is a special index type used to automatically remove documents from a collection after a certain amount of time or at a specific clock time. Regular indexes are used strictly for query optimization and do not have any built-in data expiration functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd45e366c-9ee6-4c87-ae92-080e72cedf21', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'When should you use ''def'' versus ''async def'' for a path operation?', N'Middle', N'Use ''async def'' when your function performs non-blocking I/O operations, such as database queries or external API calls, to keep the event loop responsive. Use ''def'' for CPU-bound tasks, as FastAPI will run these in an external thread pool to prevent blocking the main event loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d89e086-28fd-4d2a-b0c4-08112cf7d250', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Does Webpack work without a configuration file?', N'Fresher', N'Yes, Webpack can run without a configuration file using default settings. However, for most real-world projects, a configuration file is necessary to customize loaders, plugins, and output paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'638222e8-6827-4bb9-9436-0817e53ccf00', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix manage connection pooling for databases?', N'Middle', N'Actix applications typically integrate with connection pooling libraries like Diesel or SQLx. The pool is initialized at startup and injected into the application state via web::Data, allowing every request handler to retrieve a connection from the pool without the overhead of creating a new database connection per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'934a117f-83c7-4ed8-8135-0819fe4644da', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is an ORM and what does it do in Rails?', N'Intern', N'ORM stands for Object-Relational Mapping. In Rails, this is handled by Active Record, which allows developers to interact with database tables as if they were standard Ruby objects, eliminating the need to write raw SQL queries for common tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbccefb5-fe28-4524-b4c0-082172b66222', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the primary architectural design choice behind the G-P-M scheduler in Go?', N'Senior', N'The G-P-M model separates the logical goroutine (G) from the OS thread (M) via a processor context (P). This design allows the runtime to multiplex many goroutines onto a small number of OS threads, minimizing context switching overhead and enabling efficient load balancing across multiple CPU cores.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63431825-b6f5-4f29-bc6f-08227934618f', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How do you handle error responses in Litestar?', N'Fresher', N'Litestar includes a structured exception handling system. You can define custom exception handlers that catch specific errors and return standardized JSON responses to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'974124bc-b468-4cac-b0c8-0823249f7c94', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you verify the model changes in forms?', N'Fresher', N'You can add a getter property(let''s say, diagnostic) inside component to return a JSON representation of the model during the development. This is useful to verify whether the values are really flowing from the input box to the model and vice versa or not. and add diagnostic binding near the top of the form', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7463618-8eef-4f63-932e-0824adc07019', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why is it necessary to use a distributed PubSub adapter when scaling Phoenix beyond a single node?', N'Senior', N'Because standard PubSub operates only within the memory of a single Erlang node, it cannot notify clients connected to other servers in a cluster. A distributed adapter broadcasts messages across the entire cluster, ensuring real-time features remain functional regardless of which node the user is connected to.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cad7c4d0-4124-4453-b50f-0828637b16a6', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a ''Partial Index'' and when is it useful?', N'Middle', N'A partial index is an index built over a subset of a table, defined by a conditional expression. It is useful for reducing index size and maintenance overhead when you frequently query only a specific portion of your data, such as records where a status column equals ''active''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8470b64-aa30-4a7c-a760-0828d412a29c', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Why is it important to use Form Requests in Laravel, and how do they decouple validation from controllers?', N'Senior', N'Form Requests move validation logic into dedicated classes, keeping controllers focused on handling requests and returning responses. This separation of concerns adheres to the Single Responsibility Principle, makes validation rules reusable across different endpoints, and ensures that controllers only receive validated, sanitized data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
