INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e832b5e-aebf-4cc9-8e24-0849f6d064bf', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is ''use strict''; (strict mode) in JavaScript for?', N'Intern', N'''use strict'' is a statement used to enable strict mode to entire scripts or individual functions. Strict mode is a way to opt into a restricted variant of JavaScript. Advantages - Makes it impossible to accidentally create global variables. - Makes assignments which would otherwise silently fail to throw an exception. - Makes attempts to delete undeletable properties throw an exception (where before the attempt would simply have no effect). - Requires that function parameter names be unique. - this is undefined in the global context. - It catches some common coding bloopers, throwing exceptions. - It disables features that are confusing or poorly thought out. Disadvantages - Many missing features that some developers might be used to.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
