INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ec5e292-6999-42cb-9489-08512700aa9e', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does Sass handle variable scope compared to standard JavaScript closures?', N'Senior', N'Sass variables have a lexical scope; a variable defined within a block is only available within that block and its children. Unlike JavaScript closures, Sass does not have the concept of private scopes or higher-order functions in the same way, making it strictly tied to the static compilation tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
