INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6990c78-e549-4782-a80d-085dc7e7c3cd', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How do C++ ''inline'' functions affect the compilation and linkage process?', N'Senior', N'The inline keyword suggests to the compiler that it should substitute the function body at the call site, potentially reducing call overhead. It also allows the function to be defined in multiple translation units without violating the One Definition Rule, provided that the definitions are identical, which facilitates header-only library design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
