INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdc90313-48f0-4fd7-a0e9-086c1623e0fe', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Why is the MVC pattern important in Symfony?', N'Fresher', N'The MVC pattern separates the application into Model, View, and Controller layers to improve code organization. This separation ensures that business logic, user interface, and request handling remain independent, making the application easier to test and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
