INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3bc7e73-2f51-4e1a-b26c-0870f3b1616f', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo facilitate testing of API handlers?', N'Junior', N'Echo makes testing easy because handlers accept a context object that can be mocked using the standard library''s httptest package. This allows you to simulate requests and verify responses without needing to run a live server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4b559ad-8912-4ec5-b628-0872960cc8ab', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does the ''next'' function in Express work under the hood regarding the call stack?', N'Senior', N'The ''next'' function acts as a pointer to the next middleware in the internal array of handlers. When called, it invokes the next function in the chain, effectively managing the execution flow without blowing the call stack, as each middleware is invoked as a separate asynchronous event loop cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
