INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a061e92-4211-471f-8918-087c65ebc449', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'When would you choose a microservices architecture over a monolithic one?', N'Middle', N'You should choose microservices when your application becomes too complex for a single team to manage, requiring independent deployment cycles and specialized technology stacks. Microservices allow for better fault isolation and scalability, though they introduce significant operational overhead regarding service discovery and distributed tracing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'708b7b0e-7e9a-471a-a486-087cbd2ad086', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is MongoDB?', N'Intern', N'MongoDB is a document-oriented NoSQL database used for high volume data storage. Instead of using tables and rows as in the traditional relational databases, MongoDB makes use of collections and documents. Documents consist of key-value pairs which are the basic unit of data in MongoDB. Collections contain sets of documents and function which is the equivalent of relational database tables. Key Features: * Document Oriented and NoSQL database. * Supports Aggregation * Uses BSON format * Sharding (Helps in Horizontal Scalability) * Supports Ad Hoc Queries * Schema Less * Capped Collection * Indexing (Any field in MongoDB can be indexed) * MongoDB Replica Set (Provides high availability) * Supports Multiple Storage Engines Key Components: 1.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b4fdd68-2d6f-4937-8ff4-0886c6d0fda7', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does ''Symbol'' provide a unique identifier that cannot be accidentally overwritten?', N'Senior', N'Symbols are primitive values that are guaranteed to be unique and immutable. They are often used for private object properties or unique keys in maps, ensuring that different parts of a system cannot collide when interacting with the same object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9b554fc-447e-4f2e-b950-08875c82ed37', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'In a scenario where two users update the same record simultaneously, what happens?', N'Fresher', N'This is a concurrency issue that can lead to data loss if not managed. A typical approach is to use locks, where the first user to access the record prevents others from editing it until they are finished. Alternatively, the system can use version numbers to detect if the data changed since it was last read and reject the later update.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
