INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0eee102-d289-458a-bb1c-08934ebd675d', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does Project Loom’s virtual threads architecture differ from traditional OS-level threading?', N'Senior', N'Virtual threads are lightweight, user-mode objects managed by the JVM rather than the OS kernel, allowing for millions of concurrent threads. When a virtual thread performs a blocking I/O operation, the JVM unmounts it from the carrier thread, enabling the carrier to perform other work instead of remaining idle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3aad3816-c0f0-4114-9c3b-0893d69708a3', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why is dependency injection often preferred in unit testing C++ code?', N'Middle', N'Dependency injection allows for the substitution of real objects with mock or stub implementations during testing. This decouples the class under test from its dependencies, making it easier to isolate functionality and test edge cases without needing a complete environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef320aaf-d5f8-4f00-a349-0894247a2a0b', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of the ''Pipeline'' pattern in Laravel?', N'Senior', N'The Pipeline pattern allows for the sequential processing of an object through a series of ''pipes'' or filters, modifying it at each stage. It is the architectural foundation of Laravel''s middleware system, enabling a clean and extensible way to perform request filtering and response transformation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
