INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d34b965-5ada-412e-b30c-08a2faef50de', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Are Preact components case-sensitive?', N'Intern', N'Yes, Preact components must start with an uppercase letter to distinguish them from standard HTML tags. If a component name starts with a lowercase letter, Preact treats it as a standard built-in HTML element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55fdbfce-a91b-43d9-9b97-08a546bcdc61', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why is Chi''s reliance on the standard library considered a long-term architectural advantage?', N'Senior', N'Relying on the standard library ensures that the code remains maintainable and compatible with future versions of Go. It avoids the ''framework lock-in'' effect, where an application becomes tied to the proprietary abstractions of a third-party framework that may eventually become unmaintained.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67834cda-79bf-446e-a872-08a755848376', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the Program.cs file?', N'Intern', N'Program.cs is the main entry point of an ASP.NET Core application. It is responsible for configuring the host, setting up the web server, and starting the application lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'166338f9-0e40-420d-8f17-08afb9804fbe', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does query offloading to a cache layer impact database scalability?', N'Senior', N'Offloading frequent read queries to an in-memory cache like Redis or Memcached significantly reduces the load on the primary database, allowing it to focus on write-intensive tasks. This creates a tiered architecture that improves latency and throughput but requires careful cache invalidation strategies to ensure data freshness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89888e3a-c06c-422d-ab83-08b029af627d', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the architectural implications of the Java Virtual Machine''s Just-In-Time (JIT) compilation on long-running application performance?', N'Senior', N'JIT compilation improves performance by converting bytecode to machine code at runtime, allowing the JVM to perform profile-guided optimizations such as method inlining and speculative devirtualization. While this adds initial startup latency and memory overhead, it enables the runtime to adapt to actual usage patterns, often resulting in execution speeds exceeding statically compiled languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66e4e428-51e8-4c7f-84fe-08b7c2dcfdca', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle concurrent requests, and what are the limitations?', N'Middle', N'Gin handles concurrent requests by spawning a new goroutine for every incoming HTTP request via the net/http server. While this is highly efficient, developers must be careful to avoid race conditions when accessing shared state or non-thread-safe global variables within handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5580d245-19b3-4046-8a8e-08b98bcde6ab', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do you handle cookie management in Gin?', N'Middle', N'Gin provides convenient helper methods on the Context object to set and retrieve cookies. It abstracts the process of creating http.Cookie objects, allowing developers to define cookie attributes like expiration, path, and security flags directly in the handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d5a2d6e-a0c4-49eb-a0ad-08bb6e16f956', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of the ''clean-webpack-plugin'' or the ''clean'' property?', N'Intern', N'These tools are used to clear or remove the output directory before a new build starts. This ensures that old, unused files from previous builds are deleted, keeping the output folder clean.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02507371-b217-40f3-8719-08bbb4af1e49', N'954a0331-deff-4399-b588-96f39fec001d', N'How does an Angular application work?', N'Fresher', N'An Angular application starts execution from the main.ts file, which bootstraps the root module, typically AppModule. This module declares and imports other modules and components needed for the application. The root module then bootstraps the root component, usually AppComponent. Components are the building blocks of an Angular application, consisting of a TypeScript class for logic, an HTML template for the view, and CSS styles. Angular uses data binding to synchronize data between the component class and its template. Angular''s compiler processes the application code (TypeScript, HTML, CSS) during the build process, often using Ahead-of-Time (AOT) compilation to produce optimized JavaScript bundles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9077da2-1804-461f-97b1-08bc4b678fc0', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the purpose of declaration merging in TypeScript.', N'Middle', N'Declaration merging allows the compiler to combine two or more separate declarations with the same name into a single definition. This is commonly used to extend existing types or libraries by adding new properties or methods to an interface without modifying the original source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0fe50ca-259d-436c-b2b5-08bd57c1033b', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the use "with" statement in python?', N'Fresher', N'- In python generally "with" statement is used to open a file, process the data present in the file, and also to close the file without calling a close() method. "with" statement makes the exception handling simpler by providing cleanup activities. General form of with: processing statements Note: no need to close the file by calling close() upon file-var.close()', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cbc4551-f8cd-41e6-9a2a-08bef63b4da3', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are the trade-offs of using ''lazy'' stored properties?', N'Middle', N'Lazy properties are not initialized until they are first accessed, which can improve initial performance and memory usage. However, they are not thread-safe and cannot be constants, which can introduce side effects if not managed carefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b2868e4-f60d-4675-b297-08c09e50a7c5', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What are the security implications of exposing detailed error messages in an API?', N'Middle', N'Detailed error messages can leak internal system architecture, database schema details, or stack traces to malicious actors. It is best practice to return generic error messages to the client while logging the detailed technical information internally for debugging purposes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5d48a23-4709-405b-bc33-08c20b5a8342', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between a constructor and a factory constructor in Dart?', N'Intern', N'A standard constructor creates a new instance of a class directly. A factory constructor does not always create a new instance; it can return an existing instance, a cached instance, or a subclass, providing more flexibility in object creation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbb851c8-dcfd-4a9e-bd97-08c37b288af8', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the primary purpose of Rust''s ownership system?', N'Intern', N'The ownership system is designed to manage memory safety without needing a garbage collector. It enforces rules at compile time that ensure memory is cleaned up exactly when it is no longer needed, preventing common bugs like dangling pointers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
