INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'899e7d18-3121-4b75-987c-08d040b195c8', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you balance the trade-off between consistency and availability in a distributed system?', N'Middle', N'I consult the CAP theorem to determine the requirements of the specific business case. For financial systems, I prioritize consistency, even if it means temporary unavailability. For social media feeds or content delivery, I prioritize availability and partition tolerance, accepting eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d57223d-e5b8-4ef6-ac88-08d0eb5819c4', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the impact of using ''final'' on a class or method?', N'Middle', N'Using the final keyword prevents a class from being subclassed or a method from being overridden. This allows the compiler to use static dispatch, improving performance by avoiding the overhead of looking up method implementations in a virtual table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
