INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bde60164-c2f5-4dd7-8f93-08d4a6908508', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the primary key in MongoDB?', N'Intern', N'The primary key in MongoDB is the _id field, which must be unique for every document in a collection. If a user does not provide one, MongoDB automatically generates a unique ObjectId for the document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c72ce9a6-b623-4f52-a92b-08d504567d56', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is throttling?', N'Intern', N'Throttling is a programming technique used to control the rate at which a function is executed. When an event is triggered continuously—such as during window resizing, scrolling, or mouse movement—throttling ensures that the associated event handler is not called more often than a specified interval. This helps improve performance by reducing the number of expensive function calls and preventing performance bottlenecks. Common use cases: * Window resize events * Scroll events * Mouse movement or drag events * API rate limiting How does throttling work? Throttling will execute the function at most once every specified time interval, ignoring additional calls until the interval has passed. Example: Throttle Implementation and Usage JavaScript', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7640c320-60d1-4fce-93e1-08d546d695d7', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the risks of long-running transactions?', N'Middle', N'Long-running transactions hold locks for extended periods, potentially causing contention and blocking other users. They also prevent the transaction log from being truncated, which can lead to disk space exhaustion and potential database unavailability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3847b09f-2654-4d83-aef1-08d5e509323a', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why would a DBA choose ''Unlogged'' tables for certain workloads?', N'Senior', N'Unlogged tables bypass the WAL, significantly speeding up write operations because the data does not need to be written to the log. However, they are not crash-safe and are truncated automatically after a crash, making them suitable only for non-critical, ephemeral data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7456574-05d7-42c5-bd51-08da412828cf', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is inline caching?', N'Fresher', N'Inline caching is an optimization technique based on the observation that repeated calls to same function tends to occur on same type of objects. The V8 compiler stores a cache of the type of objects that were passed as a parameter in recent method calls. Upon next time when same function is called, compiler can directly search for the type in cache. Let''s consider an example where the compiler stores the shape type in cache for repeated calls in the loop. After few successful calls of the same area method to its same hidden class, V8 engine omits the hidden class lookup and simply adds the offset of the property to the object pointer itself. As a result, it increases the execution speed. There are mainly 3 types of inline caching possible: 1.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30babcc7-3219-466f-8cea-08db2f1efc81', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Describe the Ruby garbage collection algorithm and its evolution toward generational GC.', N'Senior', N'Ruby uses a mark-and-sweep garbage collector, which has evolved to include generational capabilities. By segregating objects into young and old generations, the collector optimizes performance by focusing collection efforts on shorter-lived objects, thereby reducing the duration of stop-the-world pauses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eec3401e-63b3-46c6-b7d3-08dd8134d38a', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is it important to keep message types in Actix small and serializable?', N'Middle', N'Messages are passed between threads, and depending on the implementation, they might need to be copied or moved. Keeping messages small reduces memory overhead and serialization time, which directly improves the overall system throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1080a31-c17f-4a1f-b09c-08def6ba55b7', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the purpose of a collection in MongoDB?', N'Junior', N'A collection is a grouping of MongoDB documents that share a similar purpose or structure. It is the functional equivalent of a table in a relational database, serving as a container for related data entries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'603014fb-15b2-4a12-9df7-08e211c2fd37', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between documentation and code self-documentation?', N'Junior', N'Writing clear, self-documenting code reduces the cognitive load for developers reading the code and minimizes the risk of documentation becoming stale. However, external documentation is still necessary for explaining high-level architectural decisions, business logic, and setup procedures that code alone cannot convey.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abfda37d-54da-48bb-9739-08e29f4bbb3a', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How does the ''Sidecar'' pattern improve the maintainability of microservices architecture?', N'Senior', N'The sidecar pattern offloads cross-cutting concerns like logging, monitoring, and security proxying to a separate container colocated with the service. This allows developers to focus on core business logic while maintaining consistent infrastructure policies across different technology stacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'101a6a65-eeaf-45e9-b2b6-08edd18ec26a', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What role does the ''dart:mirrors'' library play in reflection, and why is it restricted in certain environments?', N'Senior', N'The mirrors library provides full runtime reflection capabilities, allowing code to inspect and modify its own structure. It is restricted in AOT-compiled environments because it requires the entire program structure to be kept in the binary, which prevents tree-shaking and significantly increases binary size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f5bb068-9e73-424c-95f8-08eefd43e939', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is Isolation in the context of ACID?', N'Intern', N'Isolation ensures that concurrent transactions do not interfere with each other. It makes it appear as though transactions are executing sequentially, even when they are running at the same time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc9cd305-ce44-4a67-8e8d-08f2194498e2', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the significance of the ''Opaque Types'' (some keyword) in Swift''s type system.', N'Senior', N'Opaque types allow a function to hide the underlying concrete type of a return value while still guaranteeing it conforms to a specific protocol. This provides an abstraction layer that allows the internal implementation to change without affecting the public API contract, while still allowing the compiler to perform optimizations based on the specific hidden type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5db354d7-e833-45fd-94a5-08f3048e583f', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix manage CSS loading?', N'Middle', N'Remix allows you to export a links function from each route to define specific stylesheets that should be loaded. The framework then intelligently manages these assets, ensuring that CSS is only loaded when the user visits the route, improving initial page load performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13eac99e-fdc0-4315-835c-08f4dcbaccfe', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the advantage of using Read Replicas?', N'Middle', N'Read Replicas allow you to offload read-intensive traffic from the primary database instance. This increases system scalability and availability, as the primary instance can focus on handling write operations while replicas serve the read requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2135367a-470b-459a-83a7-08f61334a3fd', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the benefit of Micronaut''s startup time compared to other frameworks?', N'Junior', N'Because Micronaut resolves dependencies and performs proxy generation at compile time, the application does not need to scan the classpath or perform reflection at startup. This results in significantly faster startup times, which is beneficial for serverless environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82775b3c-11ed-4458-8bc7-08f63f749fac', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What does ''server-side scripting'' mean?', N'Fresher', N'It means the script is executed on the web server rather than the user''s browser. The server processes the PHP code and generates the final output, which is then sent to the client as plain HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e42053a2-e009-4205-974d-08fc05d40f65', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a pure function, and why does it matter for predictable software?', N'Intern', N'A pure function has two properties: 1. Deterministic — given the same inputs, it always returns the same output. 2. No side effects — it does not modify external state, mutate arguments, perform I/O, or depend on anything outside its arguments (no global variables, no Date.now(), no Math.random()). Pure functions are the foundation of functional programming. They are: - Trivially testable — no mocks, no setup, no teardown needed. - Safely cacheable — results can be memoised (same input → same output). - Safely parallelisable — no shared state mutations. - Composable — output of one is safely passed as input to another. Example 01: Example 02: Real-World Use Case: Redux reducers are required to be pure functions — (state, action) => newState.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'266167e4-ed8b-4b60-923b-08fc0e9f36ce', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum''s ''Router'' handle overlapping path patterns?', N'Middle', N'Axum''s router performs path matching based on the order of registration and specificity of the routes. If multiple patterns match, the router typically routes to the first matching route, which requires careful structuring of route definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9e51109-ce3e-47ee-a3b1-090d48c3c590', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket''s dependency injection system differ from container-based DI in other languages?', N'Senior', N'Rocket''s DI is type-based and checked at compile-time, meaning it relies on the Rust compiler to verify that required dependencies exist. This avoids the runtime resolution errors common in dynamic DI frameworks, providing a more reliable and performant alternative.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50eb89c9-6787-43bf-bc08-090f5c8983cf', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the architectural purpose of `functools.wraps` when creating decorators?', N'Senior', N'When creating decorators, the wrapper function replaces the original, which can obscure metadata like the function name and docstring. `functools.wraps` copies these attributes from the original function to the wrapper, ensuring that introspection tools and documentation generators remain accurate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'315a8597-7dd3-4244-b5ac-0910141b01de', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Why is the use of `__call__` considered an implementation of the Command pattern?', N'Senior', N'Defining the `__call__` method allows an object instance to be invoked as a function, effectively encapsulating a request as an object. This enables complex stateful operations to be passed around and treated as callable units, decoupling the invoker from the execution logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bc7823d-db65-49b4-a3c6-09102e2b2f92', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix Channels handle scalability compared to traditional REST APIs?', N'Middle', N'Phoenix Channels use persistent WebSocket connections rather than HTTP request-response cycles, reducing the overhead of repeated headers and handshakes. Because of the lightweight nature of Erlang processes, a single server can maintain hundreds of thousands of concurrent connections, making it highly efficient for real-time applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
