INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'378c71c5-6af1-4013-aaeb-09186e4c62d1', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are Svelte ''derived'' stores and why are they useful?', N'Middle', N'Derived stores allow you to create new state based on the values of one or more existing stores. They automatically update whenever the source stores change, which helps in keeping data logic centralized and preventing redundant state calculations within components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
