INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a79d5cf-f218-4259-bc73-0919d0699a5b', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What does the ''static'' keyword do in C?', N'Fresher', N'When applied to a local variable, ''static'' makes it persist for the entire duration of the program rather than being destroyed when the function exits. When applied to global variables or functions, it limits their scope to the current file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cebe21df-e287-43b2-93a6-091ddf4cbdb2', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between the ''src'' and ''href'' attributes?', N'Junior', N'The src attribute is used to embed a resource, such as an image or script, directly into the page. The href attribute defines the relationship between the current document and a linked resource, such as a CSS file or another webpage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4be51be4-89eb-4247-925c-091e9d98c556', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach the selection of a programming language for a new microservice?', N'Senior', N'I balance the team''s existing expertise with the specific performance, ecosystem, and tooling requirements of the service. I prioritize languages that offer strong support for the target deployment environment, such as Go for high-performance cloud-native infrastructure or Java/Kotlin for complex enterprise business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adf871d8-3e55-40b4-8eac-0921af40e8de', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What does the ''overflow'' property do?', N'Junior', N'The overflow property controls what happens when content is too large to fit inside its container. Common values include hidden, which clips the content, scroll, which adds scrollbars, and visible, which lets the content spill out.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1b983d4-45cf-4b31-9bd0-09231eec2e10', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between vertical and horizontal scaling for a service experiencing high load?', N'Middle', N'Vertical scaling is a quick, cost-effective solution when a single machine can handle the increased load. Horizontal scaling is the long-term architectural choice for high availability and fault tolerance, though it requires handling data partitioning and distributed state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd43b0fc6-5214-4e75-901a-09238d87ed9e', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How does ''Backpressure'' play a role in inter-service communication?', N'Senior', N'Backpressure is a mechanism where a consumer signals to the producer that it is overloaded and cannot process more requests. This prevents system saturation and cascading failures by allowing the producer to buffer, drop, or delay requests until the consumer recovers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'031f10b1-42f1-4c63-981b-092887fb553c', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What does it mean for PHP to be a server-side language?', N'Intern', N'Being server-side means that the PHP code is executed on the web server rather than in the user''s web browser. The server processes the script and generates plain HTML output, which is then sent to the client to be displayed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b78372b-e9ef-4a76-8cd8-09299a3fe46d', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI leverage Python type hints to improve application performance and developer experience?', N'Middle', N'FastAPI uses type hints to perform automatic data validation and serialization via Pydantic. By inspecting these types at runtime, it generates OpenApi documentation automatically and prevents invalid data from reaching your business logic, reducing boilerplate code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
