INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9310ab36-43eb-4b7c-8e9d-092d2ce01f81', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is a cache hit ratio and why is it a critical performance metric?', N'Middle', N'The cache hit ratio is the percentage of total requests served by the cache versus those that fall through to the database. A high ratio indicates efficient resource utilization, while a low ratio suggests poor key design, inadequate cache size, or an overly volatile dataset.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
