INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84d38c80-c8b8-4a4a-b222-0936c329091c', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What does it mean for a system to be ''highly available''?', N'Intern', N'High availability means that a system is designed to remain operational and accessible for a high percentage of time, even if individual components fail. This is typically achieved through redundancy, where backup components take over if the primary ones go down. It ensures that users experience minimal or no disruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5789115c-0c96-41a2-9a20-0937dbd6c985', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the difference between a constant and a variable in Rust?', N'Fresher', N'Variables are immutable by default and can be made mutable, while constants are always immutable and are evaluated at compile time. Constants can be declared in any scope, including the global scope, whereas variables are bound to a specific scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
