INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'570bcebf-7a41-43b1-aa3b-093c40657a09', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Explain the performance implications of the work-stealing algorithm implemented in the Go scheduler.', N'Senior', N'The work-stealing algorithm allows idle processor threads to pull tasks from the local queues of busier threads. This balances the workload across available CPU cores dynamically, preventing thread starvation and ensuring high throughput in systems with heterogeneous task durations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20a638ee-46d7-462a-961d-093e06888663', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How do Scala''s ''Sealed Traits'' enhance pattern matching exhaustiveness?', N'Senior', N'Sealed traits restrict the hierarchy of a class to be defined within the same file, allowing the compiler to know every possible subclass. When performing pattern matching, the compiler can verify that all cases are covered, issuing a warning if a branch is missing. This significantly improves code safety by preventing runtime exceptions that occur when an unexpected type is passed to a match expression.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
