INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97a6a8db-4ee7-4796-820f-09496661a36d', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If a system is failing but you cannot reproduce the error, how should you approach the problem?', N'Intern', N'You should gather as much data as possible from logs, system metrics, and user reports to identify patterns. Focus on the environment, timing, and user inputs to determine if the failure is intermittent or triggered by specific external conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44612d41-0ca3-497b-91fe-094e26e31207', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt handle environmental variables, and why is the distinction between server and client exposure important?', N'Middle', N'Nuxt uses a runtime configuration system to manage environmental variables. Variables defined in the public section are exposed to the client, while those in private are kept server-side to prevent sensitive credentials, such as API keys, from being leaked to the browser bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62447f8e-00a5-4d8d-ad40-094e32c7c88c', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of ''flask run''?', N'Fresher', N'The ''flask run'' command is a built-in development server that allows you to run your application locally. It is intended for development and testing purposes only, not for serving traffic in a live production environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'107a799c-cd82-4471-8718-094eb72ebe91', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the advantage of using the .on() method for event delegation?', N'Junior', N'The .on() method allows you to attach an event listener to a parent element that will trigger for all current and future child elements that match a selector. This is highly efficient because it reduces the number of event listeners attached to the document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2697c6a-73ab-4cb3-b6c8-094ef4cdfa62', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the dependency graph in Webpack?', N'Intern', N'A dependency graph is a visual or logical representation of how modules in an application relate to one another. Webpack builds this by recursively traversing every import or require statement starting from the entry point.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4acf182-8546-4dce-88ef-094fd9a8959f', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it useful to check the health status of external dependencies when your service is failing?', N'Junior', N'Modern applications rely on third-party APIs and databases that may experience downtime or outages independently of your code. Confirming the health of these external services helps you quickly rule out issues that are outside of your direct control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c66c6ceb-0cb2-4895-a87e-0950c3f1e125', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the trade-offs of using Laravel''s broadcast system for real-time features.', N'Senior', N'Laravel''s broadcasting system simplifies real-time communication but introduces a dependency on external services like Pusher or self-hosted WebSockets like Soketi. While it scales well, it adds complexity to the infrastructure and requires careful management of connection state and authentication security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4457cfbd-234c-4469-a473-09571a7b95c0', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is LINQ in C#?', N'Junior', N'LINQ stands for Language Integrated Query, which provides a consistent syntax for querying collections, databases, and XML. It allows developers to perform filtering, sorting, and grouping operations directly within C# code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52479fba-9ae0-4f79-9bb2-0967defcea09', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro improve SEO?', N'Fresher', N'Astro improves SEO by generating full HTML content on the server or at build time, which is easily indexable by search engine crawlers. Unlike heavy client-side frameworks, it ensures content is available immediately upon page load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c8ba0f5-a658-4b54-aace-0969904499f4', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the role of the ''schema'' property in a route definition?', N'Junior', N'The schema property is used to define the structure of incoming request data and outgoing response data. Fastify uses this to validate inputs automatically and to serialize outputs, which significantly improves performance and security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ada1648c-e4cb-46d0-bc41-096b2a26e725', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Why is it important to implement distributed tracing in a microservices architecture?', N'Middle', N'In a distributed system, a single user request often traverses multiple services. Distributed tracing allows you to visualize the entire lifecycle of a request, making it easier to identify which specific service or network hop is causing latency or failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e33af80-637b-4b7b-85d8-096edfca3f74', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between a class variable and an instance variable?', N'Junior', N'A class variable is shared by all instances of a class and is defined inside the class but outside any methods. An instance variable is unique to each object and is defined within methods using the self keyword. Changes to an instance variable do not affect other instances, whereas changes to a class variable affect all instances of that class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'710dab78-7f0b-433a-b260-096f31078dec', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the role of the ACID properties in PostgreSQL?', N'Fresher', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably, maintaining data integrity even in the event of system errors or power failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9489feba-8e73-4dfd-9288-0973d5cccdb9', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the ''N+1'' query problem and how to mitigate it in MySQL.', N'Middle', N'The N+1 problem occurs when an application executes one query to fetch parent records and then executes N additional queries to fetch related child records. This can be mitigated by using JOINs to retrieve the data in a single query or by using eager loading techniques to fetch all necessary data upfront.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
