INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae57eebf-e427-425e-a343-0978b1d56ed2', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does the ''Suspense'' component function in SolidJS?', N'Senior', N'Suspense tracks async resources accessed within its children and automatically switches to a fallback UI until those resources resolve. It is a declarative way to handle loading states that bubbles up through the component tree, keeping UI logic clean.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32dfc409-73c0-4bfd-b44e-097988270a06', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono''s router implementation differ from traditional Express-style middleware chains in terms of performance and memory allocation?', N'Senior', N'Hono utilizes a trie-based routing algorithm, which provides O(1) or O(log n) lookup times regardless of the number of registered routes. This is significantly more efficient than the linear iteration used in older frameworks, resulting in reduced memory overhead and faster request matching, especially in high-throughput edge environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0cc35fe-3f99-4996-9a35-097eb7505fa6', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What are Named Routes?', N'Fresher', N'Named routes allow you to assign a unique name to a specific route, making it easier to generate URLs or redirects. If the URL structure changes in the future, you only need to update the route definition, and the references throughout the app remain valid.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e450ed58-f1e8-4a27-84eb-09803dc4c733', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does ''Write Concern: Journaled'' provide stronger durability guarantees than ''Write Concern: W:1''?', N'Senior', N'W:1 ensures the data is written to the primary''s memory, but the write is not guaranteed to survive a crash. Journaled write concern forces the write to be flushed to the on-disk journal, ensuring that the operation survives a server power failure or crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4f0af3b-b95c-4302-80a0-098091eec3ab', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How do you handle ''Hot Keys'' that cause uneven load distribution in a distributed cache?', N'Senior', N'Hot keys can be managed by replicating the hot key across multiple cache partitions or using local node-level caches to handle the surge in traffic. Additionally, identifying and caching the derived results of common queries can prevent individual keys from becoming singular points of contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c8eee4b-a6a1-42f3-8897-0980ba8f0f59', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you approach the decision to build a custom internal tool versus purchasing a third-party SaaS solution?', N'Middle', N'Building internally allows for perfect customization and deep integration with your current stack but incurs high development and maintenance costs. Purchasing a SaaS solution reduces time-to-market and operational overhead but may introduce vendor lock-in and limited flexibility in meeting specific edge-case requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
