INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'000eba61-84ea-4ca0-8c71-0981483ab4b8', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the difference between the window.onload event and the jQuery ready event?', N'Fresher', N'The window.onload event waits for the entire page, including images and external resources, to finish loading before executing. In contrast, the jQuery ready event triggers as soon as the Document Object Model is fully loaded, allowing scripts to run faster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
