INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a3f9ae5-99e0-4c49-a50f-0988ee1460ad', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the benefit of Hono being ''Edge-ready''?', N'Intern', N'Being Edge-ready means Hono is optimized to run on distributed networks of servers located close to the end user. This minimizes latency and improves performance for global applications compared to traditional monolithic servers located in a single region.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0078597-f767-4968-a6d5-098a160ba87c', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do you balance Sass''s power with the need for clean, readable compiled CSS?', N'Senior', N'Balance is achieved by adhering to architectural patterns like BEM, keeping nesting shallow, and using mixins and extends judiciously to avoid selector bloat. Regularly inspecting the compiled CSS output during development helps identify and prune unnecessary complexity, ensuring the final stylesheet remains performant and maintainable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfbef6ad-9266-4969-91fd-098bef7a1e47', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind handle responsive design compared to traditional media queries?', N'Middle', N'Tailwind uses a mobile-first approach where utility classes are prefixed with responsive modifiers like ''md:'' or ''lg:''. This keeps media query logic directly within the markup, making it easier to see how a component adapts to different viewports without constantly switching between HTML and separate CSS files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e34e6337-d3e3-4d56-9c83-09920ce0e20e', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a bulk API?', N'Intern', N'The bulk API allows you to perform multiple index, update, or delete operations in a single API call. This significantly improves performance by reducing the network overhead of multiple individual requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbfa6e2c-0a02-41c3-aa1a-0992e67a782e', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the purpose of serialization in Qwik?', N'Fresher', N'Serialization is used to convert the complex application state and component information into a text format that can be embedded directly in the HTML. This is critical for resumability, as it allows the client to reconstruct the state without re-running server logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed6cdf7f-bc50-4619-a360-0995551ce221', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are ''opaque types'' and how do they benefit API design?', N'Middle', N'Opaque types use the ''some'' keyword to hide the underlying concrete type while ensuring the return value conforms to a specific protocol. This allows library authors to change internal implementation details without breaking the public interface or exposing complex generic signatures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e41613d5-1e2c-4d57-b9db-099828863783', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony''s ''ParamConverter'' simplify controller logic, and what are its drawbacks?', N'Senior', N'ParamConverters automatically inject objects into controller methods by mapping request attributes to database entities. While this reduces boilerplate code significantly, it can lead to hidden database queries that are difficult to debug or optimize, potentially impacting performance in high-concurrency environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a783b18-f02f-4fd9-9eb5-099f4c3a432d', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the ''Dependency Injection'' pattern and why is it used?', N'Middle', N'Dependency Injection is a design pattern where an object''s dependencies are provided to it from an external source rather than the object creating them internally. It promotes loose coupling, enhances testability by allowing for easy mocking of dependencies, and makes the codebase more maintainable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e613f31-6163-4730-9044-09a02d9c3499', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the primary challenge of maintaining global consistency in a multi-region database setup?', N'Senior', N'The CAP theorem dictates that during network partitions, a system must choose between consistency and availability. In multi-region setups, achieving strong consistency requires cross-region consensus protocols like Paxos or Raft, which significantly increase write latency due to the speed-of-light constraints on communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0cf5ce1-d3f3-4daf-8faf-09a29e1fc0a5', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the concept of Bivariance in TypeScript function parameters.', N'Middle', N'Bivariance allows function parameters to be treated as both covariant and contravariant. While this provides flexibility in common scenarios like callback methods, it can potentially lead to type safety issues, which is why strict function types usually disable this behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acc2c9fb-bcd9-4d96-b7cd-09a4f4d29086', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the benefits of using a connection pooler like PgBouncer?', N'Middle', N'PostgreSQL creates a new process for every connection, which is resource-intensive. PgBouncer sits between the application and the database, maintaining a pool of persistent connections that are reused, significantly reducing memory consumption and improving connection establishment speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6eb44357-0dda-46a2-a7c3-09a5bd29be19', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Why is the separation of ''Handler'' logic and ''Middleware'' logic critical in Hono?', N'Senior', N'Separating concerns ensures that middleware is strictly used for cross-cutting concerns like authentication or logging, while handlers remain pure business logic. This separation allows for easier unit testing of handlers without needing to mock complex middleware state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9854ab1d-19b6-445b-8dd0-09a79feda9a4', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your approach to managing state in a distributed system?', N'Middle', N'I prefer stateless services whenever possible to simplify horizontal scaling and recovery. If state must be maintained, I offload it to a shared, high-availability data store like Redis or a database. This ensures that any instance can handle incoming requests without needing to know the history of previous interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de1ea477-4231-4f08-ab2b-09ae862fa2dc', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is a ''dead letter queue'' and why is it used in message-driven systems?', N'Middle', N'A dead letter queue is a storage area for messages that cannot be processed successfully after multiple attempts. It allows developers to isolate problematic messages for debugging without blocking the main processing pipeline or losing the data permanently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bed644e-8bb9-492e-9150-09af659f0739', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are the security implications of using FastAPI''s default dependency injection without proper validation?', N'Middle', N'If dependencies are not properly validated, an attacker might inject malicious data into protected route logic. It is essential to treat all injected parameters, especially those derived from headers or cookies, as untrusted input and validate them using Pydantic models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04ce8ece-21fc-46f6-9c63-09b128087a2d', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik''s ''resumability'' differ from standard ''hydration''?', N'Middle', N'Hydration requires downloading and executing all JavaScript to reconstruct the component state and attach listeners. Resumability allows the application to pause execution on the server and resume it on the client exactly where it left off, using serialized metadata.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6a8a198-3388-42db-aa05-09b1ac71ec7d', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are the benefits of using a preprocessor like Sass over plain CSS?', N'Intern', N'Sass provides advanced features like variables, nesting, and modularity that plain CSS lacks. These features improve code maintainability, reduce repetition, and make large-scale styling projects much easier to manage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15abeb5b-7d37-4b8b-9f42-09b2b5e9601e', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the primary trade-off when using SolidJS?', N'Middle', N'The primary trade-off is the strict requirement to avoid common pitfalls like destructuring props or forgetting to access signals as functions. Developers must follow these reactive rules strictly to ensure the dependency graph remains intact and the application behaves as expected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15055141-c87c-49f7-806d-09b2e55b8643', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'In a distributed system, how does Axum''s design assist with observability and distributed tracing?', N'Senior', N'Axum''s middleware-based architecture allows for the seamless integration of tracing headers at the entry point of the request. By using the ''tracing'' crate, developers can automatically propagate span IDs through the asynchronous call stack, providing deep visibility into request flow across service boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b376f12-1a3e-4859-b608-09b63b0d5604', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the difference between ''Auth::attempt'' and ''Auth::login''?', N'Middle', N'Auth::attempt is used for authenticating a user by verifying credentials against a database record. Auth::login is used to manually log in a specific user instance without verifying credentials, which is often useful for social authentication or after user registration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f12822da-23cf-4584-939f-09b6afdebfe9', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a primary key constraint?', N'Intern', N'A primary key constraint is a rule applied to a column to ensure that every value is unique and not null. This enforces the integrity of the record identification within the table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f35009d-1f03-483c-9a76-09b8ec128db2', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Explain the trade-offs of using Hono’s RPC (Remote Procedure Call) mode versus standard REST.', N'Senior', N'Hono''s RPC mode allows for shared type definitions, enabling the client to have full visibility into the server''s contract without manual API documentation synchronization. While this increases coupling, it significantly improves developer productivity and prevents breaking changes, which is a major advantage for internal service-to-service communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa06c7f6-95e2-4c6c-a3ef-09bd4613195d', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is BSON and why does MongoDB use it?', N'Intern', N'BSON stands for Binary JSON and is the storage format used by MongoDB. It extends the JSON model to provide additional data types, such as dates and binary data, and is designed to be efficient for both scanning and parsing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aef422ba-100f-4282-9bae-09bdf1bc3990', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the difference between ''server-only'' and ''client-only'' components?', N'Junior', N'Server-only components are rendered exclusively on the server and are not sent to the browser, which is useful for sensitive logic or secret keys. Client-only components are rendered only in the browser, which is necessary for features that depend on browser-specific APIs like the window object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3906c855-b591-4401-b4e9-09c129951e71', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the primary trade-off of stateless API design?', N'Middle', N'Stateless design allows for easier horizontal scaling because any server instance can handle any request. The trade-off is that the client must provide all necessary context, like session tokens, with every single request, which can slightly increase payload size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8ab799f-a633-4cc3-8ba6-09c1bad9f477', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the benefit of Svelte''s scoped CSS?', N'Intern', N'Scoped CSS ensures that styles defined in one component do not clash with styles in another. This allows developers to name classes freely without worrying about unintended side effects in other parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3462c749-bbcc-462a-8fcd-09c1e604a7c3', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do you define an optional property in an interface?', N'Junior', N'You define an optional property by adding a question mark after the property name. This tells the compiler that the property may be omitted when creating an object that adheres to that interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7d751b7-bd60-4bf0-b9fb-09c1ecbb70d4', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Describe the architecture and limitations of PostgreSQL''s synchronous replication.', N'Senior', N'Synchronous replication ensures that a transaction is not committed until the WAL data has been received by at least one standby server. While it guarantees zero data loss, it introduces a performance penalty on the primary due to network latency and risks availability if the standby becomes unresponsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80327bbc-903d-44ff-9d98-09c7d14c6726', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What are ''Aliases'' in Vite configuration?', N'Junior', N'Aliases allow you to define shortcuts for import paths, such as mapping ''@'' to the ''src'' directory. This prevents the need for messy relative import paths like ''../../components/button''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4497dd69-90ee-4b04-8fc1-09c948c567b3', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the primary difference between long-term caching via content hashes versus module IDs?', N'Senior', N'Content hashes are derived from the file contents, ensuring that the filename changes only when the code changes, which is critical for invalidating browser caches. Module IDs are internal identifiers that can change if the dependency order changes, potentially causing unnecessary cache invalidations if not stabilized using plugins like HashedModuleIdsPlugin.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'daa4a8b5-9be5-4d5a-946c-09c9e67187a9', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the main advantage of Ruby''s dynamic nature?', N'Fresher', N'The dynamic nature of Ruby allows for metaprogramming, where programs can write or modify themselves at runtime. This leads to highly flexible code and the ability to create powerful domain-specific languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26d81d89-ef2d-45ea-93a6-09cb2396e30d', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How do you navigate between pages in Next.js without a full page refresh?', N'Junior', N'You use the Link component provided by Next.js instead of a standard anchor tag. The Link component prefetches the destination page in the background, allowing for seamless client-side transitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71732903-40ab-4264-9e9d-09cbf4ed769c', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is meant by the ''M:N'' scheduling model?', N'Intern', N'The M:N model refers to mapping M user-level fibers onto N kernel-level threads. This allows the application to utilize multiple CPU cores while maintaining the efficiency of lightweight fiber scheduling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bcee7bd-2b0f-4062-8b94-09cd9d3708e7', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the role of the ''Response'' object?', N'Junior', N'The Response object is used to send data back to the client. It provides methods to set status codes, headers, and the body of the response, such as JSON or HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cccae02e-9ca2-4248-84ff-09d0601aed42', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Explain the role of ''Layer'' directives in Tailwind CSS and why they are important for managing specificity.', N'Senior', N'Layer directives organize CSS into base, components, and utilities, which helps manage the order of the cascade. By placing utility classes in the ''utilities'' layer, Tailwind ensures they have lower priority than base styles or custom component overrides, preventing accidental style overrides during layout development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27380b47-79c8-487c-908b-09d0fae4f081', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Does Preact support portals?', N'Fresher', N'Yes, Preact supports Portals, which allow you to render a component''s children into a different part of the DOM tree outside of the parent component''s hierarchy. This is useful for modals, tooltips, and overlays.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'608eac63-f7f8-488a-b7ec-09d75da0a13b', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How do Guards work in NestJS?', N'Junior', N'Guards are classes used to determine whether a request should be handled by a route handler based on certain conditions like permissions or roles. They execute before the interceptors and pipes, making them ideal for authentication and authorization logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32d8be6e-b4e4-48fd-ab3a-09d8be2d3d69', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle lists or collections?', N'Fresher', N'Lit handles lists using the ''repeat'' directive, which efficiently renders an array of items. It uses unique keys to track items, allowing it to move, add, or remove elements in the DOM without re-rendering the entire list.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a703691-ad38-4c31-bc7d-09d9a1058584', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the primary constraint when using Hono with heavy computational tasks?', N'Middle', N'Hono is designed for I/O-bound tasks in fast, event-driven environments. Since edge environments often have CPU time limits, performing heavy computation inside Hono routes can lead to timeouts or performance degradation, suggesting such tasks should be offloaded to background workers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56210b8c-51f8-4863-92e2-09db6db4d42c', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the difference between a Rocket ''Fairing'' and a standard middleware?', N'Middle', N'Fairings are Rocket''s implementation of lifecycle hooks that allow you to attach code to specific stages of the application lifecycle, such as startup, request receipt, or response generation. Unlike middleware in other frameworks, Fairings are deeply integrated into Rocket''s architecture, providing a type-safe way to influence the request-response lifecycle globally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06368412-2af2-4610-87be-09dc435331e8', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the purpose of ''Chaos Engineering'' in a production environment?', N'Middle', N'Chaos engineering involves intentionally injecting faults, such as killing instances or simulating network latency, to test how the system responds under pressure. It helps discover hidden weaknesses and validates that automated recovery mechanisms are functioning as expected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'695ca180-71ee-4a7a-b511-09dcc3e9cc8a', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt handle SEO compared to a standard Single Page Application (SPA)?', N'Fresher', N'Standard SPAs render content on the client side, which can sometimes be difficult for search engine bots to index. Nuxt uses SSR to deliver fully rendered HTML, making it much easier for search engines to crawl and index content effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8bd3d7a-de48-42a7-a28b-09dd895a3f14', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the function of the Cluster State, and which node typically holds the master role?', N'Senior', N'The Cluster State is a global metadata structure containing information about indices, shards, and node health, managed by the elected master node. The master node is responsible for lightweight cluster-wide changes, such as creating or deleting an index, and tracking which nodes are part of the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54b87114-fe1e-4413-804b-09e115b5b695', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What architectural considerations are necessary when migrating a complex React application to Preact?', N'Senior', N'The primary consideration is identifying usage of React-specific internal APIs or lifecycle methods that may not be supported by Preact. One must also evaluate the dependency graph for heavy React-native libraries and ensure that the build system is correctly aliasing the packages via the compat layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a50235b-f105-48d7-b54c-09e308d028d8', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach capacity planning for a system with seasonal traffic spikes?', N'Senior', N'I analyze historical traffic patterns to identify peak periods and simulate load to determine the system''s breaking point. I then implement auto-scaling policies based on resource utilization metrics to ensure the infrastructure can dynamically expand to meet demand while remaining cost-effective during quiet periods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7c82048-56bb-4f28-b2f7-09e7268478d4', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the purpose of Rocket''s configuration system?', N'Intern', N'Rocket''s configuration system allows developers to manage environment-specific settings like server addresses, port numbers, and database connection strings. These settings can be defined in a configuration file or via environment variables, ensuring the app behaves correctly across development, testing, and production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'859d3110-b704-495c-8e15-09e9211731c3', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Describe the trade-offs between using Worker Threads versus clustering in Node.js.', N'Senior', N'Clustering spawns multiple processes, each with its own event loop and memory space, providing fault isolation and better utilization of multi-core systems. Worker Threads share memory and are more lightweight, making them ideal for CPU-intensive tasks within a single process. Clustering is generally preferred for horizontal scaling and high availability, while Workers are better for computational parallelization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c42a503-01ea-44a7-b827-09ed704f6236', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the Roslyn compiler leverage the ''partial'' keyword for incremental builds?', N'Senior', N'Partial classes and methods allow large source files to be split, enabling the compiler to track changes more granularly. This architecture supports faster incremental builds by only recompiling the segments of the code that have actually changed rather than the entire type definition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5d922ee-d989-4437-b94c-09efe8f744b1', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What role do plugins play in the Tailwind CSS ecosystem?', N'Middle', N'Plugins allow developers to extend Tailwind''s functionality by adding new utilities, components, or variants. They are used to share custom CSS logic across projects or to integrate third-party libraries without manually modifying the core configuration file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33dbc35f-844a-460d-a3de-09f0ed1b7121', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle a situation where you disagree with a manager''s approach to a problem?', N'Intern', N'I would respectfully ask for clarification on the logic behind their approach to understand their perspective. If I still have concerns, I would share my observations backed by data or reasoning, while remaining ready to follow the final direction once the discussion is complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90a8f8e3-70ca-4db1-a9df-09f126341f0a', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Why is horizontal scaling of a message broker more complex than scaling a stateless web server?', N'Senior', N'Brokers must maintain state about message offsets, partition ownership, and consumer groups, which requires complex coordination between nodes. Scaling a stateless server only involves adding instances behind a load balancer, whereas scaling a broker requires data rebalancing and maintaining consensus across the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8436dc9c-9e0c-41be-b2ef-09f25f520958', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the purpose of the server directory?', N'Intern', N'The server directory is used for writing server-side API routes and middleware. It allows you to build a full-stack application by including your backend logic directly within the Nuxt project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'756f9d53-2743-4afb-9fb9-09f380f73154', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the purpose of the Quarkus ''Hot Reload'' feature?', N'Intern', N'Hot Reload allows developers to see their code changes instantly in the running application without needing to manually stop and restart the process. This significantly speeds up the development feedback loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b38e2756-6274-4903-9694-09f45852d446', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are the advantages of using ''delegation'' in Kotlin?', N'Middle', N'Delegation allows a class to implement an interface by delegating its implementation to a specific object instance. This reduces boilerplate compared to manual implementation and facilitates easier composition by allowing classes to inherit behavior from multiple sources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf3acecb-8bc3-425f-9594-09f4d27f12ea', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the ''nuxt.config'' file used for?', N'Fresher', N'The nuxt.config file is the central configuration hub for your entire Nuxt project. It allows you to define global settings, register modules, set up environment variables, and configure build-time behavior for the framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbd1ec79-4b88-4c16-8f1f-09f5cffa9637', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the difference between ChangeDetectionStrategy.Default and OnPush?', N'Middle', N'The Default strategy checks every component in the tree whenever any event occurs in the application. OnPush restricts the change detection to only run when an input reference changes, an event originates from the component, or an observable emits, which significantly improves performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'432dc7aa-d1fe-4006-b02b-09f601b0be26', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the trade-off between ''Write-Ahead Logs'' (WAL) and memory-mapped files for data persistence.', N'Senior', N'WAL provides high durability by ensuring every operation is logged to disk before applying it to the memory state, protecting against crashes. Memory-mapped files offer faster access by mapping disk segments directly into memory, but they rely on the OS to flush data, increasing the risk of data loss during a power failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eaead35a-8af0-4dc5-94db-09f786b41603', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a foreign key constraint violation?', N'Junior', N'This occurs when an attempt is made to insert or update data that references a non-existent primary key in another table. It also occurs if an attempt is made to delete a row that is still being referenced by foreign keys elsewhere, maintaining referential integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1379a06b-4c5b-464b-b8bc-09f789b92bc8', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you handle large file uploads in Flask efficiently?', N'Middle', N'For large files, you should avoid reading the entire file into memory to prevent process crashes. Flask allows you to stream the request data or use the ''save'' method on file objects to write chunks directly to disk. In high-traffic scenarios, it is often better to offload file handling to a dedicated storage service or a reverse proxy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20d41303-3ed2-42aa-bd7e-09f87ddebd13', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Can FastAPI applications be containerized easily, and what is the best practice?', N'Middle', N'Yes, FastAPI is highly container-friendly due to its simple dependencies and small footprint. The best practice is to use an official Python slim image, install requirements, and run the application using a production-ready ASGI server like Uvicorn within the container.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b1aa756-e319-4e56-a72d-09f88a39ab53', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What are ''Astro Actions'' and when should you use them?', N'Middle', N'Astro Actions are a type-safe way to handle form submissions and server-side mutations. They provide built-in validation and error handling, making it easier to manage data flow between the client and server without writing boilerplate fetch logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12ef54ad-7b73-4235-b524-0a0033eeb1f1', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web handle multiple concurrent requests?', N'Intern', N'Actix-web creates a number of worker threads proportional to the number of logical CPU cores. Each worker runs its own event loop to manage multiple connections simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcba1eba-f4d8-41b4-bfbc-0a0243312ff2', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is meant by ''Zero JavaScript by default'' in Astro?', N'Junior', N'This means that any component you write in Astro is stripped of its JavaScript before it reaches the browser, unless you explicitly tell it otherwise. This drastically reduces the amount of code the browser needs to parse and execute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9771b186-ab24-49b0-beb5-0a0318b7271e', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does the database ''Isolation Level'' influence the query execution plan?', N'Senior', N'While isolation levels primarily affect concurrency control, they can indirectly influence execution plans by changing the visibility of data. For example, some engines might disable certain optimizations or force specific index scans to ensure that a serializable snapshot remains consistent throughout the duration of a complex query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53456b82-6c2f-483b-910e-0a03a13d6e34', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What are the risks of exposing database-level models directly through an API?', N'Senior', N'Exposing internal models creates tight coupling, making it difficult to refactor the database schema without breaking clients. It also risks leaking sensitive internal fields or implementation details, and prevents the ability to transform data into a format optimized for the API''s specific use case.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f41414e4-8a6c-440b-b531-0a03d3175e93', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the difference between ''client:load'' and ''client:idle''?', N'Fresher', N'The ''client:load'' directive hydrates a component immediately on page load, while ''client:idle'' waits until the browser has finished its initial tasks. Using ''client:idle'' can improve performance for lower-priority interactive elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d7606dc-0671-4cc4-a714-0a059d6edf27', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are the architectural risks of using ''GlobalScope'' in a complex application?', N'Senior', N'GlobalScope creates coroutines that are not bound to any specific lifecycle, leading to potential memory leaks and orphaned tasks. It prevents structured concurrency, making it difficult to cancel or track background work, which can lead to unpredictable application state during configuration changes or shutdowns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
