INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc8b832d-7557-4b58-9c8c-0a0dd8b34d24', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is meant by the ''CAP Theorem''?', N'Middle', N'The CAP Theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. In the presence of a network partition, a system designer must choose to favor either consistency or availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
