INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef2ea37a-f7c6-4ad0-b8ba-0a2a7d2ebb48', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle asynchronous errors differently than older Node.js frameworks?', N'Middle', N'Fastify integrates natively with promises and async/await, automatically catching rejected promises and passing them to the global error handler. This eliminates the need for manual try-catch blocks in every route handler and prevents unhandled promise rejections from crashing the process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17631d63-7dc7-49b2-9df1-0a2a9641f388', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of a Model in Ember.js?', N'Junior', N'The Model represents the data layer of your application. Its role is to fetch, store, and manage the state of your data, typically by interacting with an API through Ember Data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ed14bb7-d2e8-4fde-825d-0a306d848ccc', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Describe the difference between High Availability and Disaster Recovery.', N'Senior', N'High Availability focuses on maintaining uptime during normal operating conditions by eliminating single points of failure through redundancy and failover. Disaster Recovery focuses on restoring service after a catastrophic, site-wide event, prioritizing data integrity and recovery time objectives over continuous operational availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2154d7a4-23e3-4bd0-a309-0a328e18c3e3', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the architectural implications of using ''shallowRef'' in a performance-critical Vue application?', N'Senior', N'ShallowRef avoids the recursive reactivity overhead by only tracking the change of the top-level value. This is highly effective when managing large, immutable data structures or third-party objects where deep reactivity is unnecessary, significantly reducing the initialization time and memory footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e749e38-7379-44ec-9ce8-0a3325348557', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How do Phoenix Channels differ from standard HTTP requests?', N'Junior', N'Channels provide a mechanism for soft real-time communication using WebSockets. Unlike standard HTTP, which is request-response based, channels allow for persistent, bi-directional communication between the server and the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f49546f-656e-4452-adc5-0a341c6d4b96', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of the Model layer in Django?', N'Fresher', N'The Model layer acts as the definitive source of truth about your data. It contains the essential fields and behaviors of the data you are storing and maps directly to a database table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af70d713-9d24-496e-ba9f-0a3784b5b2e1', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it important to consider error handling when designing a new feature, rather than adding it at the end?', N'Intern', N'Designing for error handling from the start ensures that the system is resilient and provides meaningful feedback to the user when things go wrong. If added at the end, error handling often becomes an afterthought, leading to poor user experience and difficult debugging. Considering failure modes early allows for better architecture, such as defining clear boundaries and fallback states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04a783a5-95f6-4ea2-86d6-0a39af38e04b', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is Node.js and why is it used?', N'Intern', N'Node.js is an open-source, cross-platform JavaScript runtime environment that executes code outside of a web browser. It is built on V8, the same JavaScript engine within Chrome, and optimized for high performance. This environment, coupled with an event-driven, non-blocking I/O framework, is tailored for server-side web development and more. Key Features - Asynchronous & Non-Blocking: Ideal for handling a myriad of concurrent connections with efficiency. - V8 Engine: Powered by Google''s V8, Node.js boasts top-tier JavaScript execution. - Libuv Library: Ensures consistent performance across platforms and assists in managing I/O operations. - NPM: A vast package ecosystem simplifies module management and deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c0f9a02-8d0a-4d28-8e31-0a3b67e08336', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the impact of zero-allocation routing on high-traffic API performance?', N'Senior', N'Zero-allocation routing avoids creating new objects or strings for every incoming path segment. By utilizing pointers to the original request buffer and pre-compiled routing trees, the framework significantly reduces GC pressure, allowing for higher request-per-second capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30ed501e-af24-4f74-bef1-0a3c4c92bc82', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis ensure data consistency in a cluster?', N'Junior', N'Redis Cluster uses an asynchronous replication model to send data from the primary node to its replicas. Because replication is asynchronous, there is a small window where a write might be lost if a failover happens before the data is synchronized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57170139-85a1-4555-a928-0a3c992fc8c6', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a Tombstone in Cassandra and why is it used?', N'Middle', N'A tombstone is a marker used to represent a deleted record in Cassandra''s immutable storage structure. Since data files are immutable, Cassandra cannot delete data in place, so it marks it for later removal during the compaction process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05c7d7ca-c70c-4d46-b6f9-0a3d8b08915f', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does HTTPS protect data in transit?', N'Middle', N'HTTPS uses TLS encryption to establish a secure, encrypted channel between the client and the server. This prevents man-in-the-middle attacks by ensuring that intercepted traffic cannot be read or tampered with by unauthorized parties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
