INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b4aa886-0466-468b-b944-0a5332cb6e69', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust''s ''Zero-Cost Abstractions'' philosophy manifest in its standard library?', N'Senior', N'Zero-cost abstractions ensure that higher-level language features, such as iterators or closures, compile down to machine code that is as efficient as hand-written, low-level code. By using monomorphization and aggressive inlining, Rust allows developers to write expressive, high-level code without incurring runtime overheads typically associated with abstraction layers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
