INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e526e0f6-1fac-4c84-803e-0a57e357fdec', N'954a0331-deff-4399-b588-96f39fec001d', N'How does Angular''s Dependency Injection system handle hierarchical injectors, and what are the implications for memory management?', N'Senior', N'Angular utilizes a tree of injectors mirroring the component tree, allowing for scoped providers that can be destroyed alongside their component. This prevents memory leaks by ensuring services tied to specific components are garbage collected when the component is destroyed, while also allowing for clean singleton patterns at the root level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6dc4071-ee53-4913-8cbe-0a584d8d242f', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the effect of using ''force()'' in a function with lazy evaluation?', N'Middle', N'The ''force()'' function explicitly triggers the evaluation of a promise, compelling R to evaluate an argument immediately. This is necessary when an argument needs to be captured in its current state before subsequent operations modify the environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ceea87c-2d45-415b-b359-0a585e884688', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you install vuex?', N'Fresher', N'You can install vuex using npm or yarn as below, In a module system, you must explicitly install Vuex via Vue.use() (OR) You can also install it using CDN links such as unpkg.cpm which provides NPM-based CDN links. Just include vuex after Vue and it will install itself automatically. Note: You can use a specific version/tag via URLs like https://unpkg.com/vuex@2.0.0. If you don''t mention any version then it will point to latest version.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'021eb251-690d-4ae8-9f4a-0a5af66be3d9', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do you secure a Gin application against common web vulnerabilities?', N'Middle', N'Securing a Gin app involves using middleware for tasks like rate limiting, setting security headers, and implementing CSRF protection. Additionally, you must always validate all input data and use parameterized queries to prevent injection attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88312865-53b6-41e1-94a4-0a5b5c0b72d6', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Does Astro use a virtual DOM?', N'Intern', N'Astro itself does not use a virtual DOM. It renders components to raw HTML on the server, which is then sent to the browser, making it much lighter than frameworks that rely on virtual DOM reconciliation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b42189f-293b-4e10-850e-0a5c33868b34', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is an enumeration in Swift?', N'Intern', N'An enumeration defines a common type for a group of related values and enables you to work with those values in a type-safe way within your code. Each case in an enumeration can also have associated values of different types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29860852-47a1-4143-a548-0a60526cda63', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does a document differ from a row in a relational database?', N'Fresher', N'A document in Elasticsearch is a JSON object that stores data in a flexible, schema-less format, whereas a row in a relational database must strictly adhere to a predefined table schema. Documents allow for nested structures and varying fields, making them more versatile for semi-structured data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ca0487d-7a11-41e5-ac00-0a621d19f06a', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What does ACID stand for in the context of databases?', N'Intern', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably, maintaining data validity even in the event of errors or system failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ad311db-d183-48f7-8fa9-0a656a6a2115', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik''s build process differ from a standard Vite-based React build?', N'Middle', N'While both use Vite, Qwik''s build process includes a specialized step where the Optimizer analyzes component code to extract logic into separate modules. This produces a granular output of small JavaScript chunks, whereas a standard React build typically bundles code into larger files that are executed as a single unit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1cc64e09-80d7-4e7e-a03b-0a689abaccc0', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the primary difference between a key-value store like Redis and a relational database management system?', N'Fresher', N'A key-value store like Redis uses a simple schema-less approach where data is accessed via a unique key, making it highly efficient for simple data retrieval. In contrast, a relational database uses structured tables with predefined schemas and relationships, which is better suited for complex queries and maintaining data consistency through ACID properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6246e5b1-a888-435d-b2c0-0a6cf4db7d83', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the purpose of hydration in a SvelteKit application?', N'Middle', N'Hydration is the process where the client-side JavaScript takes over the static HTML delivered by the server. Svelte ensures this process is efficient by attaching event listeners and reactive logic to the existing DOM nodes without needing to re-render the entire page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f7eab48-19d7-45ca-9c28-0a70283ce0a3', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the role of the Garbage Collector (GC)?', N'Fresher', N'The Garbage Collector is an automatic memory management system that reclaims memory occupied by objects that are no longer being used by the application. It helps prevent memory leaks by identifying unreachable objects and freeing their space.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88f07014-d633-40b0-9e77-0a7105997cc7', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Does Vite use Webpack for building applications?', N'Fresher', N'No, Vite does not use Webpack. It uses Rollup for production builds to ensure highly optimized and tree-shaken static assets, while using native ESM for the development phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04d49f41-306d-47cb-8702-0a7a4d787ff4', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the function of the ''$$props'' object in Svelte components?', N'Middle', N'The $$props object contains all properties passed to a component, including those not explicitly declared. It is typically used for creating highly reusable components that need to pass through unknown attributes to underlying DOM elements, though it should be used carefully to maintain component predictability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
