INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18e74b36-bbd1-4600-acd4-0a7d0662319f', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you implement distributed logging to debug issues across services?', N'Middle', N'Distributed logging requires injecting a unique ''Correlation ID'' into the header of every request as it enters the system. This ID is passed along to every subsequent service call, allowing developers to aggregate logs from all services in a centralized system and filter them by that ID.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd52060c-3d67-4f0f-b41e-0a82271d4e4c', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle state management compared to traditional frameworks?', N'Middle', N'Lit is essentially a library for building components rather than a full-blown framework, so it relies on local reactive properties for state. For complex application-wide state, developers typically use external libraries or state management patterns like Context, which Lit provides as an official utility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13fa5538-eba6-438d-84a5-0a822a1053d5', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What does ''serialization'' mean in a web framework?', N'Fresher', N'Serialization is the process of converting complex Python objects, such as database models or dictionaries, into a format like JSON that can be sent over the network. Deserialization is the reverse process of turning incoming JSON back into Python objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
