INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6186adc6-d82c-40a2-a43e-0a89c8bd875f', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is Hot Module Replacement (HMR) in the context of Vite?', N'Fresher', N'HMR is a feature that allows the browser to update modules in real-time without requiring a full page refresh. When you save a file, Vite replaces only the modified module, preserving the current state of the application and significantly speeding up the feedback loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fcacd0c-6827-40b9-87ba-0a8b241e3db5', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are environment variables in Nuxt?', N'Intern', N'Environment variables are key-value pairs used to store configuration data that might change between development, staging, and production environments. Nuxt allows you to access these variables safely to manage settings like API base URLs without hardcoding them into your source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a2dc513-73a2-414c-84c9-0a8ef06a4e81', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala''s type system handle the conflict between object-oriented inheritance and functional composition?', N'Senior', N'Scala utilizes traits to facilitate mixin composition, allowing for a form of multiple inheritance that avoids the diamond problem through linearization. This enables developers to compose behavior horizontally rather than relying solely on deep class hierarchies, aligning the language with functional paradigms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfa210ef-0de4-4145-9c29-0a90990bb5dd', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How do NoSQL databases differ from SQL databases in terms of structure?', N'Fresher', N'SQL databases are relational and use predefined schemas with fixed rows and columns. NoSQL databases are non-relational and typically use flexible models like documents, key-values, or graphs, allowing for dynamic schemas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5094ed1-fb74-4d91-b05c-0a916dd6d4c1', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How are objects stored in R?', N'Intern', N'Objects in R are stored in the computer''s memory, specifically in the RAM, during the active R session. When the session is closed, the workspace can be saved to a file for later use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2df2c9d2-6af2-4ba8-9a06-0a91ef4936fc', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the role of the ''Transaction Log'' in database recovery?', N'Senior', N'The transaction log captures all operations that modify data before they are permanently committed to the data files. In a failure scenario, the system uses the log to roll back incomplete transactions and roll forward committed ones, ensuring the database returns to a consistent, valid state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a27f1ba3-cf5a-442c-b90e-0a92a9bc6ac7', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What does the ''App.Hooks'' feature provide in Fiber?', N'Middle', N'Hooks allow developers to execute custom logic at specific stages of the application lifecycle, such as after the server has started or before it shuts down. This is useful for initializing resources like database connections or cleaning up connections before the process terminates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'098e6480-56f6-48da-a888-0a92b31b37a6', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why is it important to keep the Redux store state flat?', N'Senior', N'A flat state structure avoids the complexity of deeply nested updates, which are error-prone and computationally expensive to perform immutably. It simplifies data retrieval and updates, making it easier to maintain relationships between entities and preventing accidental data loss during partial state updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4540ff91-3921-4c0f-b626-0a93fc0199e0', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Can you perform joins in DynamoDB?', N'Intern', N'No, DynamoDB does not support joins like traditional relational databases. Because it is a NoSQL database, you are encouraged to denormalize your data or use secondary indexes to access related information efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc0ae6d5-1e35-4576-9584-0a94ad2efdd8', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How can you serve static files in Express?', N'Junior', N'Static files such as images, CSS, or JavaScript files are served using the built-in express.static middleware function. You provide the name of the directory containing the static assets to this function to make them accessible via the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebe1f77d-d37a-41a8-a32f-0a94f2a31996', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue handle prop validation and why is it beneficial for team scalability?', N'Senior', N'Vue''s prop validation allows developers to define types, requirements, and custom validators for component inputs. This creates a contract between parent and child components, catching bugs early in development and serving as self-documenting code for larger teams.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c302297b-5526-4272-8257-0a95158e675d', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What are the common use cases for Chi?', N'Intern', N'Chi is commonly used for building RESTful APIs, microservices, and web backends. Its focus on performance and simplicity makes it an excellent choice for services that require low latency and clean code architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e44eaf1-06c3-4a87-82fe-0a95f2e4c127', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Why might you choose Alpine.js over a library like jQuery for a modern project?', N'Middle', N'Alpine.js provides a declarative, reactive approach that automatically keeps the DOM in sync with state, whereas jQuery requires imperative manual manipulation of the DOM. Alpine reduces the amount of boilerplate code needed to handle state updates and simplifies complex UI interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fda1799-8240-4dc1-9255-0a969d679b42', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Describe the impact of index fragmentation on performance and how it is mitigated.', N'Senior', N'Fragmentation occurs when logical order of pages does not match physical order or when pages have significant free space due to deletions and updates. This leads to inefficient sequential I/O and increased buffer pool pressure, which is mitigated through index reorganization or full rebuilds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b6c86ff-c99c-4de9-9146-0a96cc9f7ce2', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What are the trade-offs of using Micronaut compared to Spring Boot?', N'Middle', N'Micronaut offers faster startup and lower memory usage due to AOT compilation, whereas Spring Boot provides a broader ecosystem and more mature runtime-based features. Micronaut is generally preferred for microservices and serverless environments, while Spring Boot is often chosen for monolithic applications requiring deep legacy integration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b53d6217-441a-4eb4-b5db-0a98938e3891', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When designing a system that requires high consistency, how do you manage the trade-off between latency and data integrity?', N'Middle', N'I would evaluate the business requirement to determine if eventual consistency is acceptable for the specific use case. If strong consistency is mandatory, I prioritize integrity over latency by implementing synchronous replication or consensus algorithms, acknowledging the trade-off in response time. If low latency is critical, I would propose an asynchronous model with conflict resolution strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9b32510-0e14-43e6-9969-0a9b1fac99fb', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the main advantage of Qwik for SEO?', N'Fresher', N'Qwik provides excellent SEO because it sends fully rendered HTML from the server to the browser immediately. Search engine crawlers can read the content without waiting for JavaScript to execute or hydrate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3accbc7c-096c-437a-9f0a-0a9c17093f2e', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Why is Echo considered ''minimalist''?', N'Intern', N'Echo is considered minimalist because it focuses on providing only the core features needed for a web framework, such as routing and context management. It does not force specific patterns or database libraries on the developer, allowing them to choose their own architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0ff75eb-73d1-4d92-b9a5-0a9f1ad05d23', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Explain the difference between transient, scoped, and singleton service lifetimes and how they impact memory consumption and state management.', N'Senior', N'Transient services are created every time they are requested, scoped services are created once per client request, and singletons are created the first time they are requested. Using inappropriate lifetimes can lead to memory leaks or concurrency issues, particularly when injecting scoped services into singletons, which causes a captive dependency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e217654-6e2a-4907-8e8b-0a9f343d6609', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the benefit of using Fasthttp as the underlying engine for Fiber?', N'Intern', N'Fasthttp is designed for high-concurrency environments and significantly reduces memory allocation compared to the default Go HTTP server. This leads to lower latency and higher throughput, making it ideal for performance-sensitive applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff427dd7-cee7-41f9-a8df-0aa284916529', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle component re-rendering?', N'Junior', N'Preact re-renders a component when its state or props change. It compares the new Virtual DOM tree with the previous one and applies only the necessary changes to the real DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3b47704-234c-4d54-b9a8-0aa48d4f0b0d', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the concept of ''Bundle'' in Symfony and why modern applications prefer a more modular approach.', N'Middle', N'Bundles were originally intended as reusable units of functionality, but modern Symfony development encourages keeping logic in the ''src'' directory. This modular approach reduces the overhead of maintaining multiple bundles and makes the application structure easier to navigate for smaller to mid-sized projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d837816-f93a-4136-8055-0aa54725c9be', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Describe the mechanism behind Litestar''s ''Guard'' system and its role in authorization.', N'Senior', N'Guards are composable functions that run before a route handler, allowing for centralized, declarative authorization logic. By attaching guards to routers or individual handlers, developers can implement complex access control policies that remain decoupled from the business logic within the handler itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'053707e0-1242-445d-b833-0aa58aae560d', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the difference between interface and type alias in TypeScript and when to favor one over the other.', N'Senior', N'Interfaces are primarily intended for defining object shapes and support declaration merging, making them ideal for public APIs or library definitions. Type aliases are more flexible, supporting unions, intersections, and primitive mappings, which are better suited for complex type transformations or utility types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a3a5bb4-cdd1-48fe-8757-0aa6693a67f1', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What happens if you access a signal outside of a reactive scope?', N'Junior', N'If you access a signal outside of a component template, effect, or memo, the framework will not track it. The value will be read, but any future updates to that signal will not trigger any UI changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
