INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e98cf92-3867-4b90-88f3-0aa8646a11ea', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is ''Build Time Boot'' in Quarkus?', N'Intern', N'Build Time Boot is a process where the framework performs heavy lifting, such as scanning classes and resolving dependencies, during the compilation phase. This allows the application to start much faster because these tasks are already completed before the application launches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15dde512-544e-4d60-b02d-0aa8deff873d', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Describe the difference between ''competing consumers'' and ''partitioned consumers''.', N'Senior', N'Competing consumers take messages from a common queue where any consumer can pick up any message, making ordering non-deterministic. Partitioned consumers assign specific partitions to specific consumers, ensuring that all messages with a particular key are always processed by the same instance, thus preserving strict order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1c861e7-8458-48c4-ab69-0aa8fd3e2d23', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the difference between ''Handler'' and ''Actor'' in Actix-web?', N'Middle', N'In Actix-web, a handler is a function or struct that processes an HTTP request and returns a response. An actor is a long-lived entity with internal state that processes messages, which may be triggered by a handler but exists independently of the request-response cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cc7aa26-ecd1-4de6-b7ff-0aaaa3c18a77', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Explain the concept of Alpine.js ''deferred loading'' and its impact on SEO.', N'Senior', N'Alpine.js is inherently SEO-friendly because the HTML is rendered on the server and Alpine hydrates it on the client. Since it doesn''t require the browser to execute a full application bundle to display initial content, search engine crawlers can index the static content easily before Alpine initializes its reactive features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95ad5558-de04-4f48-9287-0aaaafb6bbb1', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What does ''chi.URLParam'' return if the parameter is missing?', N'Fresher', N'If the requested URL parameter does not exist in the current request context, ''chi.URLParam'' will return an empty string. It is a safe way to attempt to retrieve path variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d4bdee1-5dac-4523-958b-0aab328f4d5d', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why might you choose a relational database (SQL) over a non-relational database (NoSQL) for an e-commerce inventory system?', N'Fresher', N'A relational database is preferred when data is highly structured and requires complex relationships between entities like products, orders, and customers. SQL databases enforce strict schemas and ACID properties, which ensure data integrity and reliable transactions during purchases. This is essential for maintaining accurate inventory levels and order history.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acf454b6-ec4a-4dd3-9539-0aac6039623a', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the WHERE clause used for?', N'Intern', N'The WHERE clause is used to filter records in a query. It ensures that only rows meeting a specific condition are returned by the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
