INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c31a715b-afe1-4fbc-82b3-0ab1ca6aa6e6', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do TypeScript''s variance rules (covariance, contravariance, invariance) affect the design of complex API wrappers?', N'Senior', N'Understanding variance is critical for ensuring type safety in function parameters and return values, especially when dealing with complex generic hierarchies. Misunderstanding these rules—particularly contravariance in function arguments—can lead to subtle runtime errors, necessitating the use of ''readonly'' modifiers or explicit type constraints to enforce sound architectural boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b6c3b36-eed8-44c0-bded-0ab2007ada37', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How do ''Parallel Routes'' differ from ''Intercepting Routes'' in the App Router?', N'Middle', N'Parallel routes allow you to render multiple pages in the same layout simultaneously, such as a dashboard with a sidebar and a main content area. Intercepting routes allow you to load a route from another part of the application within the current page, usually to create modal-like experiences.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86e9cfa2-f492-47b4-ae2c-0ab23cb82257', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why might you choose a synchronous API design over an asynchronous one?', N'Junior', N'Synchronous design is straightforward to implement and debug because the flow is linear and predictable. Asynchronous design is better for long-running tasks to prevent blocking the user, but it introduces complexity in handling state, error propagation, and eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72e13c78-6689-4ac9-96fb-0ab498f44f79', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the advantages of using a NoSQL database like MongoDB?', N'Fresher', N'NoSQL databases offer flexibility in data modeling, allowing developers to store varying structures in the same collection. They are generally easier to manage for rapidly changing applications and handle hierarchical data naturally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b63a979-995f-4a15-a008-0ab63d916cbf', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle request panics?', N'Fresher', N'Chi provides a built-in middleware called ''Recoverer'' that catches any panics occurring during request processing. This prevents the entire server from crashing and allows you to return a 500 Internal Server Error instead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34f20ea1-00be-463c-9868-0ab9638ffaff', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why is Rocket''s compile-time URI generation considered a scalability and maintenance advantage?', N'Senior', N'By generating URIs from internal route definitions at compile-time, Rocket prevents broken links caused by refactoring. This architecture ensures that any change in API structure is caught during the build process, reducing the risk of runtime 404 errors in production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d057d30-5141-433a-9a89-0aba54920681', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a major trade-off when using a document database?', N'Intern', N'The primary trade-off is that document databases generally do not support complex joins between documents as efficiently as SQL databases do with tables. This requires developers to design data models that minimize the need for joins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'632819c5-c4b5-432d-b9f0-0abbfea4b173', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why is Remix considered ''Server-First'' rather than ''Client-First''?', N'Senior', N'Remix prioritizes server-side data processing and HTML generation to ensure content is immediately available. Client-side interactivity is treated as an enhancement to the base server-rendered experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
