INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6426ff7-cf0b-4ac8-b1cb-0ac12b932d5e', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are the trade-offs of storing application state in a GenServer versus a database?', N'Middle', N'Storing state in a GenServer provides extremely fast, low-latency access since it resides in memory, but it is volatile and lost if the process crashes. A database provides persistence and durability, but introduces disk I/O overhead and latency for every read or write operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
