INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03712a1e-6345-41f1-8d6b-0ac72c84d1e5', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the difference between ''Flow'' and ''StateFlow'' in Kotlin coroutines?', N'Middle', N'Flow is a cold stream that starts emitting values only when collected and can be recreated for each collector. StateFlow is a hot, state-holding stream that always keeps the latest value and emits it to new collectors immediately upon subscription.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd879e462-9d3e-4db1-977b-0ac97d6feb66', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the Commit Log used for?', N'Junior', N'The commit log is an append-only log on disk that records all mutations made to the database. It ensures data durability in case of a system crash before the data in the memtable is flushed to an SSTable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
