INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4f98ba1-245e-475d-8839-0acd4f4f8fcc', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you know when a task is ''done''?', N'Intern', N'A task is done when it meets all the established requirements, has passed all necessary tests, and has been reviewed according to team standards. It should also be documented and verified to function correctly in the target environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04eca62d-e8ab-4ba5-8dcf-0ace23e1a5ad', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the difference between ''sync'' and ''async'' queue drivers and when you would use each in a production environment.', N'Senior', N'The ''sync'' driver processes jobs immediately within the request cycle, making it suitable for debugging or local development but unsuitable for production as it blocks the web server. The ''async'' drivers (e.g., Redis, SQS) move jobs to a persistent queue for background processing, which is essential for maintaining responsiveness in high-traffic applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
