INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2340deb8-f307-4e81-b3fd-0ad3d2eed861', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the difference between a global middleware and a route-specific middleware in Hono?', N'Junior', N'Global middleware runs for every single request that enters the application, whereas route-specific middleware is only executed when a request matches a specific path or group of paths. This allows for granular control over security and logging requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35c5c2f6-7a1d-4ec6-8f24-0ad44ae23a7c', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the impact of using ''SELECT *'' in production queries.', N'Middle', N'Using ''SELECT *'' retrieves all columns, which increases network traffic and memory usage on the application server. It also prevents the use of covering indexes, forcing the database to perform extra lookups to retrieve data that may not be needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
