INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b0e9bda-ad98-4bf0-851e-0ad6cf74aab8', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Describe the role of TTL (Time to Live) in DynamoDB.', N'Middle', N'TTL allows you to define an expiration timestamp for items, after which DynamoDB automatically deletes them without consuming provisioned throughput. It is an efficient way to manage data lifecycle and reduce storage costs for transient data like sessions or temporary logs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cba88470-bf43-4878-b26b-0ada083c2dc0', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the purpose of the @Transactional annotation in Quarkus?', N'Junior', N'The @Transactional annotation is used to declare that a method should run within a database transaction context. If the method completes successfully, the changes are committed; if an exception occurs, the transaction is automatically rolled back.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'369df41b-7b6b-49ef-813b-0add31aec610', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is nodejs', N'Intern', N'Node.js is a server-side platform built on Chrome''s JavaScript runtime for easily building fast and scalable network applications. It is an event-based, non-blocking, asynchronous I/O runtime that uses Google''s V8 JavaScript engine and libuv library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0910cce-b797-4e30-81b6-0ae1d9716267', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a column-family database?', N'Intern', N'A column-family database is a type of NoSQL system that stores data in columns rather than rows. This design is highly efficient for analytical queries that process large amounts of data across specific subsets of attributes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'add1a3d9-0845-4ddd-9af7-0ae2fa4c12a3', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Why would you use Symfony''s EventDispatcher component?', N'Middle', N'The EventDispatcher allows for decoupling different parts of an application by enabling components to communicate without direct dependencies. You can trigger an event when a specific action occurs, and any number of registered listeners or subscribers can react to that event independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b2c8343-a6d2-4708-9e73-0ae668e723e0', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Describe the benefits and risks of using a pre-fork model in a Fiber application.', N'Senior', N'Pre-forking allows multiple child processes to listen on the same port, effectively utilizing multi-core systems by bypassing the GOMAXPROCS limitation on single-process network listeners. The risk lies in increased memory consumption and the complexity of managing shared states, which must be handled via external stores like Redis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
