INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1a6430f-26e0-4d77-a70f-0af0ca88cd31', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the concept of a ''Dirty Read'' in a database transaction.', N'Middle', N'A dirty read occurs when a transaction reads data that has been modified by another concurrent transaction but not yet committed. If the original transaction rolls back, the reading transaction is left with data that effectively never existed in the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
