INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04b7440b-c9fb-437c-a282-0b0d083718c5', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the primary purpose of the Redux store in an application?', N'Middle', N'The Redux store serves as the single source of truth for the application state. It centralizes the state, making it predictable and easier to debug, as all state changes occur through a controlled flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17c1d893-43ac-4bc8-8ae0-0b0d4e176fce', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the MySQL binary log (binlog) contribute to replication and disaster recovery?', N'Senior', N'The binlog records all changes to the database structure and content, serving as the source of truth for replicas and point-in-time recovery. It allows for asynchronous or semi-synchronous replication, ensuring that standby servers can reconstruct the state of the primary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a990245-20ad-4b70-8eb3-0b0f5e12a5e2', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik achieve ''Instant'' loading without compromising interactivity?', N'Senior', N'By serializing the application state into the HTML, Qwik bypasses the need for the browser to run a massive startup bundle. The app becomes interactive as soon as the HTML is parsed, and subsequent code is only loaded on-demand, creating the illusion of an instant, fully loaded application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21a44c8f-1e4a-4852-b5b1-0b0fe0454ac9', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why might you prefer a ''struct'' over a ''class''?', N'Middle', N'Structs provide safer, thread-local state management because they are copied rather than shared. They avoid memory management overhead associated with ARC for reference types and are generally faster due to stack allocation. They are the preferred default in Swift for modeling data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0ba4336-90e8-46e1-a07b-0b0fe3b7ee0f', N'075b8862-431c-4678-9767-f55359758a4a', N'Why is it important to keep components small and focused?', N'Middle', N'Small, focused components improve maintainability, make testing easier, and allow for better reusability across the application. They also help minimize re-renders, as changes in one part of the component tree won''t necessarily trigger updates in unrelated parts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc8f1b6c-799b-4953-8265-0b1081a68836', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a schema in a database?', N'Fresher', N'A schema is the formal structure or blueprint of a database. It defines the tables, the fields in each table, the relationships between them, and the constraints applied to the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c1fe3b1-4e76-429f-8d3e-0b1103fe7e28', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does event-driven architecture support system scalability?', N'Middle', N'Event-driven architecture allows components to react to events asynchronously, making the system highly modular and reactive. It allows for better resource utilization because services only process events when they occur, rather than polling for updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1a18719-3e63-481f-b8b3-0b187e89e4f0', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does the ''Read Replica'' pattern improve database performance?', N'Middle', N'Read replicas offload read-heavy traffic from the primary database instance to secondary instances. This improves overall system throughput and availability, though it introduces the challenge of potential replication lag where reads might not reflect the most recent writes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'357cf0bf-ca2b-4bf4-bde3-0b1db1ae4041', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What does ''technical debt'' mean to you?', N'Fresher', N'Technical debt represents the cost of choosing an easy or quick solution now instead of a better, more sustainable one that would take longer to implement. While it can help meet immediate deadlines, it makes future development harder and slower because the ''quick fix'' code is often messy. It must be managed by eventually refactoring the code to pay down the debt.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ec309d6-5ff2-46c3-bae0-0b1e822a254f', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of Middleware in FastAPI?', N'Fresher', N'Middleware is a function that works with every request before it is processed by a specific path operation, and with every response before it is returned. It is useful for tasks like logging, authentication, or modifying headers globally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef64643a-3842-4279-bbe2-0b204b52e87b', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between a Migration and a database schema change?', N'Junior', N'A migration is a way to version control your database schema changes using Entity Framework Core code. Instead of manually running SQL scripts, migrations allow you to apply and track changes to the database structure through code files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5939b47b-8cb7-4c51-a659-0b2867190ad4', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are ''aria-labels'' and when should you use them?', N'Middle', N'ARIA labels provide accessible names to elements that do not have visible text or where the visible text is insufficient. You should use them for icons, buttons, or interactive elements that rely solely on visual cues. They should not be used as a replacement for standard semantic HTML tags.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee5a1e93-8e12-4847-8505-0b2b2c071588', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the significance of the ''Ember Inspector'' in the development workflow?', N'Senior', N'The Inspector provides a deep, framework-aware view of the running application, including the current route state, service values, and component hierarchies. It is essential for debugging because it exposes the internal state managed by the framework, which is often abstracted away from the standard browser debugger.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ad4fe99-9abe-4315-adf4-0b2d959b78ed', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Why is ''Security by Design'' superior to ''Penetration Testing'' as a primary strategy?', N'Senior', N'Security by design embeds security into the architecture and requirements phase, preventing vulnerabilities before they are built. Penetration testing is a reactive measure that identifies defects after they exist; relying solely on it is insufficient as it often misses deep architectural flaws and logic errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27d09eb0-815c-40e0-b758-0b3044b3a5e3', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When considering scalability, what is the trade-off regarding infrastructure cost?', N'Intern', N'Building a system to scale horizontally supports millions of users but significantly increases cloud infrastructure costs and operational complexity. For a small internal tool, a simpler, monolithic architecture is often more cost-effective.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca7c542a-346c-48c9-bd5e-0b318f42c660', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the difference between a stored procedure and a function?', N'Junior', N'A stored procedure is a set of SQL statements that can perform various actions, including modifying data, and does not necessarily return a value. A function must return a single value or table and is typically designed to perform calculations or data transformations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e004e910-0882-44cf-981f-0b32e271e968', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the benefit of using ''declarative'' rendering over ''imperative'' DOM manipulation for complex UI?', N'Senior', N'Declarative rendering ensures that the UI is always a predictable reflection of the current state, eliminating the need to manually sync DOM elements when data changes. This reduces the surface area for bugs related to out-of-sync UI states and simplifies the mental model required for complex interface logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
