INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c93713c-0d19-4b4e-a120-0b3a1d357d02', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the trade-offs of using Redis Cluster versus a single Redis instance?', N'Middle', N'Redis Cluster provides horizontal scaling by partitioning data across multiple nodes, increasing memory capacity and throughput. However, it introduces complexity in client-side routing, multi-key operations across shards, and potential latency overhead due to network communication between nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
