INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'686b6d46-8fe0-4b9d-af02-0b41b7c3173d', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is React lazy function?', N'Intern', N'The React.lazy function lets you render a dynamic import as a regular component. It will automatically load the bundle containing the OtherComponent when the component gets rendered. This must return a Promise which resolves to a module with a default export containing a React component. Note: React.lazy and Suspense is not yet available for server-side rendering. If you want to do code-splitting in a server rendered app, we still recommend React Loadable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1484281-f765-4a83-8163-0b44bce9c11c', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you define ''done'' when completing a task?', N'Junior', N'A task is done when it meets all the acceptance criteria, passes all automated tests, and has been verified against the initial requirements. It also includes ensuring the work is documented and that any necessary cleanup or refactoring is completed. Finally, the task must be validated through peer review or QA processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79b443f0-7f58-4067-aede-0b44cef31ef5', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What criteria do you use to choose a serialization format like JSON, Protobuf, or Avro for inter-service communication?', N'Middle', N'I choose JSON for human-readability and ease of debugging in public APIs. I select Protobuf or Avro for internal service-to-service communication when performance, reduced payload size, and strict schema evolution are critical requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2efd211f-a686-401c-9650-0b454d0eafb2', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What architectural patterns help in managing shared state across multiple Flask worker processes?', N'Senior', N'Because workers do not share memory, shared state must be managed via external data stores like Redis or Memcached. These stores act as a centralized, high-performance cache or state manager, enabling features like distributed rate limiting, session sharing, and cross-process data synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49f08671-e6f5-4dee-b751-0b457e2f4c0f', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the various Modules in NestJS?', N'Fresher', N'A module is a class annotated with a @Module() decorator. The@Module() decorator provides metadata that Nest makes use of to organize the application structure. modules are a fundamental aspect of the framework''s architecture. They help organize the application into logical and manageable sections. There are three main types of modules in NestJS: 1. Feature Modules: These are the most common type of modules and are used to group related features together. They keep the code organized and establish clear boundaries. This helps us manage complexity and develop with SOLID principles, especially as the size of the application and/or team grow. For example: The CatsController and CatsService belong to the same application domain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'992ccbf0-9b4b-4449-9743-0b46159dacea', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of the ''INSTALLED_APPS'' setting?', N'Intern', N'The INSTALLED_APPS setting tells Django which applications are active in the project. This is necessary for Django to recognize the models, templates, and management commands provided by those apps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ede3115-2f8c-450a-90a6-0b49f7539225', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Can you use Hono with external libraries?', N'Intern', N'Yes, because Hono is standard JavaScript, you can use any library that is compatible with your chosen runtime. However, it is recommended to use libraries that are also compatible with edge environments to avoid runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55c7ca60-5cc2-441b-baa7-0b4bff5419d6', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle a situation where a critical service dependency has a lower SLA than your own service?', N'Senior', N'I would architect the system to be resilient to the dependency''s failure by implementing circuit breakers and fallback mechanisms. This ensures that a failure in the lower-SLA service does not cause a cascading failure throughout my own architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54c330cf-fa2c-484c-9b8a-0b50a8e292c9', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the difference between a process and a thread in Node.js?', N'Junior', N'A process is an instance of a program with its own memory space, while a thread is a unit of execution within that process. Node.js typically runs one main thread per process but can spawn multiple threads for specific tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'261dbc28-5b26-47e1-99c9-0b51093bfdeb', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How do you manage environment variables in Next.js, and how does the framework handle secrets versus public variables?', N'Senior', N'Variables prefixed with ''NEXT_PUBLIC_'' are bundled into the client-side code, while others remain server-only. It is critical to never include sensitive secrets like database credentials in variables with the ''NEXT_PUBLIC_'' prefix, as they will be exposed in the browser''s source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0951a7fb-b9fb-46f7-8c73-0b519b7a44ce', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is meant by ''Declarative Templates'' in Lit?', N'Fresher', N'Declarative templates allow you to define the structure of your UI using a simple, readable syntax directly in your code. Lit uses tagged template literals to define these templates, which are then processed to update the DOM efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f086126-b33e-4e0a-91d0-0b5368074925', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the purpose of database partitioning and how does it differ from sharding?', N'Middle', N'Partitioning splits a single logical table into smaller, more manageable physical pieces on the same server to improve query performance. Sharding involves distributing data across multiple physical servers to achieve horizontal scale and distribute the load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d2bc19f-62a5-46d6-b495-0b537cafaf61', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the role of the ''app.run()'' method?', N'Fresher', N'The ''app.run()'' method starts the built-in development server provided by Flask. It listens for incoming requests and routes them to the appropriate functions defined in the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74fd0d4a-7535-4ae7-a507-0b53aba1d7f7', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What architectural benefits does Gin provide for testing microservices?', N'Senior', N'Gin allows for the creation of an Engine instance that can be tested using the net/http/httptest package without binding to a network port. This enables fast, isolated unit and integration tests that verify routing, middleware, and handler logic in a controlled environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'155de647-7118-422e-89ba-0b5447e99434', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle form data?', N'Intern', N'Echo can process form data sent via POST requests by binding it to a struct or accessing it directly through the context. It supports both standard form-encoded data and multipart form data for file uploads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1630b6c-3227-47a8-b5bf-0b55ff238890', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are the benefits of ''Path-Dependent Types'' in Scala''s type system?', N'Senior', N'Path-dependent types tie a type to a specific instance of an object rather than just its class, allowing for deep type-level constraints that reflect the object''s structure. This is particularly useful in complex DSL design and internal API modeling to ensure that objects from different instances cannot be accidentally mixed. It provides a high level of compile-time safety by preventing illegal operations between entities that are logically separated at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23d015b4-7f6b-4bac-a581-0b57925fb129', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why is Elasticsearch considered ''near real-time''?', N'Intern', N'It is called near real-time because there is a slight delay between the time a document is indexed and the time it becomes searchable. This delay is caused by the refresh interval required to update the inverted index.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecfacb6e-d144-4efd-a998-0b5c47509a0a', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are React Portals used for?', N'Intern', N'React Portals are used to render children into a DOM node that exists outside the hierarchy of the parent component. This is useful for scenarios like modals, tooltips, and dropdowns where you need to break out of the parent component''s overflow or z-index constraints. You create a portal with createPortal(child, container) from react-dom. Even though the rendered DOM lives elsewhere, the portal still belongs to the React tree, so events bubble up to the React parent and context still flows through normally. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1271fe99-be2c-4d0b-bce6-0b5c4d41a5ca', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How do you ensure thread safety when using a Singleton service in ASP.NET Core?', N'Middle', N'Since singleton services are shared across all requests, you must ensure that any state or shared resources are accessed in a thread-safe manner. This is typically done by using synchronization primitives like locks, concurrent collections, or by ensuring the service is entirely stateless.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11ed5807-0a76-40e4-bd24-0b5d5a8b6665', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the role of the Cargo tool?', N'Fresher', N'Cargo is Rust''s build system and package manager. It handles tasks like downloading dependencies, compiling code, running tests, and generating documentation for Rust projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3a6aca9-3d14-43df-bded-0b5eef0fa754', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the primary purpose of the ''path operation decorator'' in FastAPI?', N'Fresher', N'A path operation decorator tells FastAPI that the function immediately below it corresponds to a specific URL path and HTTP method. It allows the framework to map incoming web requests to the correct Python function to handle the logic. By using these decorators, developers can easily define routes like GET or POST for different endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c97d8e0-2d9e-4ecb-90c5-0b5fbf07a8f0', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do you navigate between pages in an Ember app?', N'Junior', N'You use the ''link-to'' component, which generates the correct URL for a route. Using this instead of a standard anchor tag allows Ember to transition between routes without performing a full page reload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0922afaf-fed1-4e13-8552-0b62892c7b18', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the benefit of SvelteKit''s zero-config approach?', N'Fresher', N'The zero-config approach means that common tasks like routing, building, and bundling work out of the box without needing complex setup files. This allows developers to focus on writing application code rather than configuring build tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46f7b36a-4817-4afb-8486-0b62d999e152', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the purpose of the .each() method?', N'Fresher', N'.each() is a looping construct used to iterate over a collection of jQuery objects. It allows you to execute a function for every element in the selection, which is useful for batch operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21c37659-51a7-4fb6-bcfd-0b64d50de952', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why is database sharding used, and what is a potential downside?', N'Middle', N'Sharding is the process of splitting a large dataset into smaller, more manageable chunks across multiple database instances to improve read and write performance. The main downside is the increased complexity in application logic, specifically regarding cross-shard joins and maintaining data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'077af7a3-45cf-413f-bb65-0b65fd0b354f', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are the trade-offs of using Ember''s ''Octane'' architecture versus the older ''Classic'' component model?', N'Senior', N'Octane emphasizes a flatter, function-based component model using Glimmer components and native decorators, which improves performance and reduces the complexity of the component lifecycle. Classic components rely heavily on inheritance and complex lifecycle hooks, which can lead to brittle and harder-to-maintain codebases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2a0f3a3-c96a-41e6-83c0-0b67464ef186', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If a deployment causes a major production outage, what is your immediate course of action?', N'Middle', N'I prioritize restoring service by immediately rolling back to the last known stable state. Once the system is stable, I conduct a blameless post-mortem to analyze the root cause and update the deployment pipeline to prevent similar issues in the future.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe571184-f791-4ba3-9c18-0b69654a9236', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar optimize performance during the request-response lifecycle compared to other ASGI frameworks?', N'Senior', N'Litestar optimizes performance by performing heavy introspection during the application startup phase rather than at runtime. By caching the parsed signature and metadata of handlers, it minimizes the overhead per request, leading to more efficient execution within the ASGI loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41167d6c-8bf8-4960-8202-0b69c0f48dd9', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between a coroutine and a standard generator?', N'Senior', N'While both use yield-based mechanisms, coroutines are designed for asynchronous I/O and data consumption via the ''send'' method. Coroutines represent a stateful task that can pause and resume, forming the core infrastructure for Python''s event-loop-based concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f40697e-6dd3-46a3-8674-0b6a39ec5ef9', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why is choosing a database schema a significant architectural trade-off?', N'Fresher', N'A rigid, well-defined schema ensures data integrity and high performance for specific queries. A flexible, schemaless approach allows for faster changes and diverse data types but places the burden of structure and validation on the application layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2502d28d-e9ca-45d6-b6d0-0b6dc61d33fb', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the PostgreSQL transaction log?', N'Intern', N'The transaction log, known as Write-Ahead Logging (WAL), records all changes made to the database before they are applied to the main data files. This ensures data integrity and allows for recovery in the event of a system crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bdcad55-67b3-449a-a088-0b6e845f04cc', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you handle API versioning in a distributed system to ensure backward compatibility without breaking existing clients?', N'Senior', N'Versioning should be handled through URI path prefixing, custom headers, or media type versioning in the Accept header. URI versioning is the most explicit and cache-friendly, while header-based versioning allows for cleaner resource URIs. Always maintain at least two versions concurrently and implement a formal deprecation policy with clear communication to consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9832bd8e-d9d5-4d9a-b31d-0b719d67156f', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain the role of an Angular Module (NgModule) versus Standalone Components.', N'Middle', N'NgModules act as a grouping mechanism to organize related components, directives, and pipes into a cohesive unit with a defined scope. Standalone components simplify the mental model by allowing components to manage their own dependencies directly, reducing the need for boilerplate module files in smaller or modern applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edf1bda5-a8d4-49c6-a18b-0b71acc927d5', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the strategic value of Alpine.js in a ''Micro-Frontend'' architecture?', N'Senior', N'In micro-frontends, Alpine.js serves as an excellent ''glue'' for independent UI fragments that need interactivity without the overhead of a heavy framework. It allows teams to ship small, self-contained interactive units that don''t share dependencies, preventing version conflicts between different micro-frontend applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1868455f-013c-4fde-99e6-0b725cde0bd0', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle a scenario where your initial estimate for a task is significantly lower than the actual time taken?', N'Middle', N'I would conduct a post-mortem analysis to identify the root cause, such as unforeseen technical complexity or missed dependencies. Communicating this discrepancy early to stakeholders and adjusting future estimates based on these learnings is essential for maintaining transparency and improving prediction accuracy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36e9c409-9c4b-4285-8f7a-0b73a3cf2aa6', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the IOptions pattern, and why is it preferred over direct configuration injection?', N'Senior', N'The IOptions pattern provides a strongly-typed, centralized way to access configuration settings, supporting features like automatic validation and change tracking. It decouples the application logic from the configuration source, such as JSON files or environment variables, allowing for easier testing and configuration updates without application restarts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5571c10a-f559-44ac-b679-0b76dd49a605', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How do you manage environment variables in a NestJS application?', N'Middle', N'The standard approach is using the @nestjs/config module, which leverages the dotenv package. It maps environment variables to a configuration object that can be injected into services, ensuring centralized and type-safe access to settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48917210-95c6-4dd5-95a3-0b786e9f4bd3', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Explain the architectural impact of choosing between synchronous and asynchronous replication in a multi-region database setup.', N'Senior', N'Synchronous replication guarantees strong consistency and zero data loss but introduces high write latency because the primary must wait for replicas to acknowledge the commit. Asynchronous replication provides high availability and low latency, but it introduces the risk of data loss during a failover and forces the application to handle potential read-your-writes inconsistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5768ec01-a3e6-4406-99b8-0b79574c54ac', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'When would you prefer gRPC over REST for service-to-service communication?', N'Middle', N'gRPC is preferred when you need low-latency, high-performance communication with small payload sizes due to its use of Protocol Buffers and HTTP/2. It is ideal for internal service communication where strong typing and bidirectional streaming are beneficial.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78bb74be-1759-4c31-bfa1-0b7bd7b7f667', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the architectural trade-offs when choosing Fiber over a more standard-compliant framework like Gin?', N'Senior', N'Fiber offers superior raw performance and reduced latency, but at the cost of breaking compatibility with the vast ecosystem of net/http-compatible middlewares. Gin, built on the standard library, provides better long-term maintainability and easier integration with existing tools and libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b64bf58e-7703-41c4-aa49-0b7cdb8285fa', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If you are stuck on a task for several hours, what is your strategy for getting unblocked?', N'Intern', N'First, I step away from the task to gain a fresh perspective. Then, I verify my assumptions against the initial requirements to ensure I haven''t overlooked a fundamental detail. If still stuck, I document my progress and ask a teammate for guidance, ensuring I can clearly explain what I have already tried.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97317d12-d614-4f86-9038-0b7ffa407df2', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind facilitate the implementation of dark mode?', N'Middle', N'Tailwind provides a ''dark'' variant modifier that allows you to specify different styles that only apply when a dark mode selector is present in the document. This is usually toggled via a class on the root element, making theme switching simple and performant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3ba188f-1a57-4924-9514-0b8255f1798a', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the main advantage of Webpack 5''s ''Module Federation''?', N'Middle', N'Module Federation allows multiple independent builds to share code at runtime. It enables micro-frontend architectures by allowing different applications to dynamically load modules from each other, reducing the need to redeploy the entire application when one part changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4544cdff-4583-4f65-83b2-0b834191af1f', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How is React different from Angular or Vue?', N'Fresher', N'Architectural Paradigm * React (19): A library for building user interfaces using a Causal Decoder-only conceptual model for rendering. It emphasizes functional programming paradigms via Hooks and the React Compiler (automatic memoization). * Angular (v19+): A platform utilizing a Signals-based reactivity system (replacing legacy Zone.js change detection). It mandates a strict Dependency Injection architecture. * Vue.js (3.x/4): A progressive framework utilizing a Proxy-based reactivity system. It bridges the gap between React’s composability and Angular’s template-first DX. Learning Curve * React: Steepened in 2026 due to the required mastery of Server Components (RSC), Suspense, and the transition to native asynchronous patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10e41ccf-9d4c-4da7-a089-0b83d76bb038', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How do Intercepting Routes improve the user experience in modern web applications?', N'Senior', N'Intercepting Routes allow a route to be rendered within the context of the current page rather than performing a full navigation. This is commonly used for displaying modals or slide-overs on top of existing content, maintaining the application state while providing a seamless transition for the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96cd5eb5-1d23-4525-84d8-0b88405d602a', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does React''s reconciliation process work?', N'Middle', N'React compares the current virtual DOM tree with a newly generated one using a diffing algorithm. It identifies changed nodes and updates only those specific parts of the real DOM, significantly improving rendering performance compared to re-rendering the entire page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2cb2795-bc79-402d-8beb-0b894f47279f', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Does Nuxt require a Node.js server?', N'Fresher', N'If you are using Server-Side Rendering, a Node.js server is required to execute the JavaScript code that generates the HTML. However, if you use Static Site Generation, the output is just standard HTML, CSS, and JS, which can be hosted on any static file server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'661d3554-5b20-4a9e-a084-0b8ac58501f9', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is sharding in a NoSQL environment?', N'Junior', N'Sharding is the process of splitting a large dataset into smaller, more manageable chunks called shards and distributing them across multiple servers. This ensures that no single server bears the entire load of the database, improving performance and availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf8dd0f5-f27e-42b6-8004-0b8f76b11918', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Explain the role of the C stack frame during a function call.', N'Middle', N'A stack frame is a block of memory allocated on the call stack for each function call to store local variables, function parameters, and return addresses. It provides a structured way to manage function nesting and ensures that local context is preserved and restored correctly as the program execution flows through different functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f4dcf39-fe2b-48cf-a42e-0b90c4263c09', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Eloquent''s ''Lazy Loading'' work and what are its performance risks?', N'Middle', N'Lazy loading retrieves related data only when you access the relationship property on a model instance. The risk is that if you do this inside a loop, it triggers a new database query for every iteration, resulting in the N+1 performance bottleneck.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccfb27c3-91a8-472e-9763-0b920a3e3d0b', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the difference between development and production builds?', N'Junior', N'Development builds are optimized for rapid iteration and include helpful errors and warnings. Production builds are optimized for performance, including code minification, asset compression, and removal of development-only code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d37c9ce-dc0b-4374-b649-0b948a999a91', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is the use of jQuery''s $.ajax considered less scalable than modern Fetch API or Axios implementations?', N'Senior', N'jQuery''s AJAX implementation is heavily coupled with the DOM and event-based callbacks, which can lead to ''callback hell'' without heavy abstraction. Modern alternatives are built on Promises or Async/Await, which offer cleaner flow control, better error handling, and separation of concerns from the UI layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68c77080-06f4-4421-a64e-0b99b7ea3342', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Why is the AdonisJS ''Exception Handler'' critical for distributed systems?', N'Senior', N'The global exception handler normalizes error responses, ensuring that the API returns consistent JSON structures even during crashes. In distributed systems, this is vital for monitoring tools and upstream services to correctly interpret failure states, preventing the leakage of sensitive stack trace information to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'275fb740-5330-4f0e-bde6-0b9b04c81140', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What are the architectural implications of using ''SyncActors'' in a high-load Actix application?', N'Senior', N'SyncActors run in a separate pool of threads and are designed for CPU-bound tasks or blocking I/O. While they allow for parallel processing of blocking tasks, they introduce overhead due to thread context switching and synchronization, and should be used sparingly compared to standard asynchronous actors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'736b6cb4-7dbd-4cff-a330-0ba231f1d9e7', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the role of the lang attribute in the html tag?', N'Junior', N'The lang attribute defines the language of the document''s content. This information is used by browsers and assistive technologies to correctly pronounce text and apply appropriate language-specific features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f305256-d772-4108-babb-0ba286f766f5', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Explain the trade-offs of using PUT versus PATCH for updating resources.', N'Middle', N'PUT is idempotent and typically replaces the entire resource, requiring the client to send the full state. PATCH is used for partial updates, which is more bandwidth-efficient but requires careful handling to ensure it remains idempotent or predictable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3df41ac0-bb09-4373-b00c-0ba540b7aa27', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you mitigate the risk of a ''split-brain'' scenario in a distributed cluster with a leader-follower configuration?', N'Senior', N'I would implement a consensus algorithm like Raft or Paxos to manage leader election and ensure that only a single partition can reach a quorum. Using an odd number of nodes and a witness or arbiter node helps maintain a majority, preventing conflicting masters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6fad82a-8594-44da-8a9c-0ba874664d54', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you approach debugging a bug that you cannot reproduce on your local machine?', N'Fresher', N'I would gather logs from the environment where the bug is occurring to understand the specific sequence of events leading to the error. I would also ask for detailed steps to reproduce the issue, including the browser version, operating system, and any specific inputs used by the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92c96b2d-0fe5-4173-9ec2-0ba8b9721ff7', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is an ORM and how does Rails use it?', N'Fresher', N'An Object-Relational Mapper is a technique that lets you query and manipulate data from a database using an object-oriented paradigm. Rails uses ActiveRecord as its ORM, which allows developers to interact with database records as if they were simple Ruby objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21c1a8f0-048a-4553-ba45-0baa474a0c7f', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does Node.js handle errors in asynchronous code?', N'Junior', N'Asynchronous errors are typically handled using try-catch blocks with async-await, or by passing error objects to callback functions. In Promises, errors are caught using the .catch() method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
