INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b71007f-1200-4200-b4e2-0bafc8a609a1', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you balance system performance with security requirements?', N'Intern', N'Security measures like encryption and authentication can introduce latency. The design approach is to identify critical paths where performance is paramount and apply security controls in a way that minimizes impact, often by offloading security checks to specialized infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7cff52a-b973-4bbc-ae5e-0bb40239fa8b', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the Spring Bean lifecycle scope.', N'Middle', N'The default scope is singleton, meaning one bean instance per application context. Other scopes include prototype, which creates a new instance every time the bean is requested, and request or session scopes which are used in web-aware contexts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e364896b-512e-4773-babe-0bb49e78f2e3', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Why is connection pooling important for database scalability?', N'Middle', N'Opening and closing database connections is a resource-intensive operation that can become a bottleneck under high load. Connection pooling maintains a pool of active, open connections that can be reused, significantly reducing overhead and improving response times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23674c26-fd14-4c54-95bd-0bb67cc890fa', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the primary benefit of the ''Suspense'' feature in Nuxt components?', N'Middle', N'Suspense allows components to display a fallback state, such as a loading spinner, while their asynchronous dependencies are being resolved. This improves perceived performance and simplifies the management of loading states without needing complex conditional rendering logic in every component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4a4540b-bc4d-4332-bc47-0bb68f8973de', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does the use of the useFetcher hook change the user experience?', N'Middle', N'The useFetcher hook allows interactions with the server—such as submitting forms or loading data—without triggering a full page navigation. It is essential for building background tasks or dynamic UI elements like search bars and live updates while maintaining the framework''s data revalidation logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1dedf29a-5361-4ed7-ab13-0bb7d5d9061e', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Explain why ''Database Isolation Levels'' are a trade-off between concurrency and correctness.', N'Senior', N'Lower isolation levels like Read Committed allow higher concurrency by reducing lock contention but risk anomalies like non-repeatable reads. Higher levels like Serializable ensure absolute data consistency by preventing all anomalies, but they significantly limit throughput by imposing stricter locking or optimistic concurrency controls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55643a83-2828-4950-bbc5-0bb9ffb19ec9', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When choosing an authentication mechanism, what is the trade-off between session-based and token-based (JWT) auth?', N'Middle', N'Session-based authentication is stateful and easier to revoke, but it makes horizontal scaling harder as sessions need to be shared across servers. Token-based authentication is stateless and scales easily across domains, but revoking access before token expiration is complex and requires additional infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98d020b8-7854-441c-b37f-0bbb68c29747', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are the trade-offs of using Ember’s Service layer versus traditional dependency injection patterns?', N'Senior', N'Ember services provide a singleton-based registry that simplifies state sharing across the application. While they promote loose coupling through dependency injection, excessive reliance can lead to hidden state dependencies, making components harder to unit test without thorough mocking of the service container.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0a18b67-76f2-4887-8137-0bbd181ff753', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the ''connectedCallback'' method?', N'Intern', N'The connectedCallback is a native web component lifecycle method that runs when the element is added to the document. It is often used for initial setup tasks like adding global event listeners.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9b9b764-0f39-42ea-ab28-0bbe79d7bbc2', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does the acronym ACID stand for?', N'Intern', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These are the four fundamental properties that ensure database transactions are processed reliably.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95c3ba15-f028-458b-8dc3-0bbea41df80d', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the purpose and behavior of Python''s Method Resolution Order (MRO).', N'Middle', N'MRO defines the order in which base classes are searched when executing a method in a class hierarchy, specifically using the C3 Linearization algorithm. It ensures that methods are found in a predictable, monotonic sequence that respects both local precedence and global inheritance order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cabdf442-109c-4bff-91e1-0bc2bb1a864a', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the benefit of using the Lit Context API?', N'Middle', N'The Context API provides a way to pass data down the component tree without manually passing properties through every intermediate component. It simplifies state sharing for common dependencies like themes, authentication status, or configuration settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'515c8c01-7849-4df9-863c-0bc3bdaa3708', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When choosing between performance and memory usage, how should you approach the decision?', N'Intern', N'You should first identify the project''s primary constraints and requirements. If the application runs on hardware with limited resources, memory optimization is prioritized; if the user experience depends on speed, performance becomes the focus.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1e8218b-1cb2-4bd2-8a16-0bc602b46fc4', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the difference between pessimistic and optimistic locking?', N'Middle', N'Pessimistic locking prevents conflicts by locking resources as soon as they are accessed until the transaction completes. Optimistic locking assumes conflicts are rare and only checks for data changes at the time of commit, making it more efficient for high-concurrency systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d23dadf-0c61-45b3-876a-0bc692f2a376', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How can you optimize an Express application for production performance?', N'Middle', N'Optimization involves using a reverse proxy like Nginx, setting the NODE_ENV to production to enable caching and performance optimizations, and using clustering to utilize multi-core processors. Additionally, offloading static asset serving to a CDN or a dedicated web server reduces the load on the Node.js event loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f98cba2-bfef-4ca6-af05-0bc71f764cd1', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When choosing an orchestration platform, what is the trade-off between managed services and self-hosted solutions?', N'Senior', N'Managed services trade off vendor lock-in and higher direct costs for reduced operational toil and faster time-to-market. Self-hosted solutions provide total control and potential cost savings at scale, but they require a dedicated team to manage patches, upgrades, and availability. I choose managed services unless the scale is large enough that the operational overhead is eclipsed by the cost of the managed service premium.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28c98399-ece8-43d8-9570-0bc7eb42c1bd', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Explain the performance benefits of Gin’s Radix tree routing compared to standard library approaches.', N'Senior', N'Gin utilizes a Radix tree (prefix tree) to store routes, which minimizes memory usage and allows for O(k) lookup time where k is the length of the path. This is significantly more efficient than iterating through a slice of routes or using complex regex, especially as the number of defined endpoints scales.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13d35cef-0e60-478e-80b9-0bcdf632e029', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the MVT architectural pattern in Django?', N'Intern', N'MVT stands for Model, View, and Template. The Model handles the data and database structure, the View acts as the logic layer that processes user requests, and the Template handles the presentation layer by defining how the data is displayed to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebbe05c6-6f18-40bd-9da8-0bd1396ad1a2', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why is it important to avoid destructuring props in SolidJS?', N'Middle', N'Props are reactive proxies. Destructuring them copies the value at that moment, effectively stripping away the reactivity. To maintain reactive updates, you must access properties directly from the props object or use the splitProps utility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'069ef102-b38d-4015-933e-0bd1d7f71e02', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does log-structured merge-tree (LSM-tree) storage architecture optimize write throughput?', N'Senior', N'LSM-trees optimize writes by buffering incoming data in memory and flushing it to disk as sorted, immutable segments, transforming random writes into sequential I/O. While this boosts write performance, it increases read complexity because the system must merge data from multiple segments during a query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31944205-34ac-4906-a345-0bd2502489b6', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is an embedded document?', N'Intern', N'An embedded document is a document that is stored inside another document as a field value. This allows for denormalized data modeling, where related information is kept together to improve read performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25958b8f-9fc7-499c-b178-0bd56f9a93b2', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is a root reducer?', N'Fresher', N'A root reducer is a function that combines multiple smaller, specialized reducers into one single function. This allows you to split your state management logic into smaller, more manageable pieces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66808c27-5db8-4e30-ad12-0bd5897b0f76', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle conflicting technical requirements from different stakeholders?', N'Intern', N'I document the conflicting requirements and bring them to my supervisor or the project lead for resolution. I provide a clear summary of how each requirement affects the project''s goals, which helps stakeholders reach a consensus. This prevents me from making arbitrary decisions that might negatively impact the project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'262359ef-b472-49f3-a385-0bd77017f583', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Can you use standard library http.HandlerFunc with Chi?', N'Fresher', N'Yes, Chi is fully compatible with standard http.HandlerFunc. Any existing handler written for the standard library can be used directly as a route handler in Chi.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cebcce16-0215-4f18-89b5-0bd9678316f7', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle code splitting?', N'Fresher', N'Vite supports code splitting natively by using dynamic imports. When you use dynamic imports in your code, Vite will automatically split that module into a separate chunk that is loaded on demand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb715d38-be24-4ce3-823b-0bda39e03d02', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of the ''externals'' configuration?', N'Junior', N'The externals property allows you to exclude dependencies from the bundle. This is useful when you want to load a large library, like React or jQuery, from a CDN instead of including it directly in your own bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'271c4348-3d44-44c8-9916-0bde3d170138', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the Consistency property?', N'Junior', N'Consistency ensures that a transaction takes the database from one valid state to another valid state. It must follow all defined rules, constraints, cascades, and triggers set on the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36a03bed-b31c-46d0-ac26-0bde883f2596', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle high-concurrency requests compared to a framework with a traditional thread-per-request model?', N'Senior', N'Hono runs in non-blocking event loops, which are significantly more efficient than thread-per-request models for I/O-bound workloads. By avoiding the memory overhead of multiple threads, Hono can handle a much higher volume of concurrent connections on smaller, cheaper instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f33b7c2-24f0-4e5c-98e6-0bdfb01ee977', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are partials in Sass?', N'Intern', N'Partials are Sass files that start with an underscore in their filename, such as _variables.scss. They are designed to be imported into other files rather than compiled into standalone CSS files directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7d7e5e9-7bff-40c8-b445-0be13ab82c35', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Is Tailwind CSS accessible by default?', N'Fresher', N'Tailwind provides the tools to build accessible interfaces, but it is not inherently accessible by itself. You must still use semantic HTML and appropriate ARIA attributes, but Tailwind makes it easier to implement accessible states like focus rings and hover effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1281a8e1-ec93-4a9e-b7c7-0be15b349fa8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is rendering in JavaScript?', N'Intern', N'JavaScript-powered content needs to be rendered before it can output meaningful code and be displayed for the client. These are the different steps involved in the JavaScript rendering process: 1. JavaScript: Typically JavaScript is used to handle work that will result in visual changes. 2. Style calculations: This is the process of figuring out which CSS rules apply to which elements. They are applied and the final styles for each element are calculated. 3. Layout: Once the browser knows which rules apply to an element it can begin to calculate how much space it takes up and where it is on screen. 4. Paint: Painting is the process of filling in pixels. It involves drawing out text, colors, images, borders, and shadows, essentially every visual part of the elements. 5.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a7b2a81-7dec-47df-b6ee-0be1cc2ecfe1', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between static and dynamic typing in PHP?', N'Fresher', N'PHP uses dynamic typing, meaning variable types are determined at runtime based on the assigned value. This differs from static typing, where variables must be declared with a specific data type that cannot change during the program''s execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbea3f94-c57d-4da8-b8ff-0be1e0204f78', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Does Preact implement a ''Fiber'' architecture?', N'Middle', N'No, Preact does not use a Fiber architecture. Fiber was introduced in React to enable asynchronous rendering and time-slicing, which were not goals for Preact''s design, which prioritizes small size and synchronous, predictable updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f08cb3e-b169-4e88-a1e3-0be364d6dda2', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Describe the concept of cache warming and its role in high-traffic systems.', N'Senior', N'Cache warming involves proactively populating a cache with frequently accessed data before the system goes live or after a restart. This prevents a cold-start scenario where the database experiences a sudden, massive performance degradation due to a high volume of cache misses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59be2234-86da-4e6a-8888-0be3c977c3e1', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'In the context of Dart''s compiler, what is the purpose of ''dart2wasm''?', N'Senior', N'Dart2wasm is a compiler backend that translates Dart code directly into WebAssembly modules. This provides near-native performance for web applications compared to the traditional JavaScript transpilation, enabling more efficient execution of compute-intensive tasks in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'590e5d21-3579-4f0b-b839-0be44e4978c4', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach a situation where requirements are ambiguous or missing key details?', N'Junior', N'I stop work to prevent wasting time on incorrect assumptions and reach out to the stakeholder or product owner for clarification. I document the answers I receive to ensure everyone is aligned on the expected outcome before proceeding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb312d9f-3aca-4d16-870c-0be65cc11bab', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the specific challenges of implementing distributed transactions (Two-Phase Commit)?', N'Senior', N'Two-Phase Commit ensures atomic operations across distributed nodes, but it is notoriously slow because it requires all participating nodes to be available and responsive. It introduces a blocking problem where a failure in the coordinator or a single participant can leave resources locked indefinitely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ff74ffa-98ac-4ad1-b9b3-0be806a09c63', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are Symfony Form types?', N'Intern', N'Form types are classes used to define the structure, constraints, and data mapping for HTML forms. They automate the process of rendering the form, validating the input, and converting the data into objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11eed10c-8582-420d-acab-0be884fadd80', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB handle data types compared to relational databases?', N'Junior', N'MongoDB supports a wide variety of data types including strings, integers, booleans, arrays, and nested objects directly within the document. Unlike relational databases that require strict column data types, MongoDB documents can hold diverse data types within the same field across different records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17a721f9-da3e-4762-ae71-0be8c2629de2', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Is there any legitimate use case for jQuery in an enterprise environment today?', N'Senior', N'jQuery may be justified only in legacy maintenance scenarios where the cost of migration outweighs the benefits of modernizing. For new greenfield projects, there is no architectural justification for using jQuery, as modern browser APIs and frameworks provide better performance, security, and developer ergonomics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e43da79-928f-4828-adb7-0bea6437f95f', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is a Result Type in a controller action?', N'Intern', N'A Result Type is the return value of an action method that represents the HTTP response sent back to the client. Examples include Ok, which returns a 200 status code, and NotFound, which returns a 404 status code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a63639e-fc79-4a98-a9db-0bebb0a09dd0', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the trade-offs of using PHP''s standard session handling versus custom storage drivers in a distributed system.', N'Senior', N'Standard file-based sessions cause I/O bottlenecks and complicate load balancing because sessions are tied to specific server nodes. Moving to custom drivers like Redis or Memcached enables centralized session storage, allowing for seamless horizontal scaling where any web server can access any user''s session.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bd72003-4904-47d3-98cb-0bf74defe01f', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the role of the ''createMemo'' function?', N'Intern', N'The createMemo function is used to cache the result of an expensive calculation based on signals. It only recomputes the value when its dependencies change, preventing unnecessary recalculations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'795c2956-ded8-45c7-b8d9-0bf91e816855', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why is it important to keep Axum handlers asynchronous?', N'Middle', N'If a handler performs blocking I/O operations, it will stall the underlying Tokio thread, preventing other concurrent tasks from progressing. Asynchronous handlers ensure the event loop remains responsive by yielding control whenever waiting for I/O completion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5d514ec-7d95-42d1-8354-0bf95db07b49', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is eval', N'Intern', N'The eval() function evaluates JavaScript code represented as a string. The string can be a JavaScript expression, variable, statement, or sequence of statements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ed9ffc1-d0f4-424b-a986-0bf9a04a0369', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the trade-offs of using exceptions versus error codes in high-performance C++.', N'Senior', N'Exceptions provide a cleaner separation of error handling logic and do not impose performance costs in the non-throwing path, but they can cause code bloat and unpredictable latency when an exception is thrown. Error codes are predictable and transparent but often lead to cluttered code and can be ignored, potentially masking critical failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'821d7ab7-e6f2-455d-a203-0bfb1e6420d1', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'You are asked to estimate the time required to migrate a legacy database to a new cloud-based infrastructure. How do you approach this estimation process to ensure it is realistic and accounts for hidden complexities?', N'Middle', N'I would start by breaking the migration into discrete phases such as schema mapping, data validation, and network transfer, rather than estimating the project as a single block. I would then incorporate a buffer for ''unknown unknowns'' by applying a risk multiplier based on the technical debt identified in the legacy system. Finally, I would validate these estimates against historical data from similar past projects and conduct a short proof-of-concept to identify any hidden bottlenecks before finalizing the timeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc54c06c-013d-4318-898d-0bfc27a5c82a', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle service discovery in a distributed system?', N'Senior', N'Micronaut provides an abstraction for service discovery that integrates with providers like Consul, Eureka, or Kubernetes DNS. It enables automatic registration and discovery of service instances, allowing for dynamic load balancing and communication between microservices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b61ec05-7c06-4ca6-89f8-0bfced1f0c81', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If an experiment yields unexpected results, what is your first step?', N'Intern', N'I would first verify the integrity of the data and the experimental setup to ensure there was no human error or equipment malfunction. Once I confirm the results are accurate, I would analyze the data to see if it reveals a new trend or if my initial hypothesis was incorrect.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'549a89a7-b81e-483a-8fcf-0c00fbe1e51f', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the primary difference between @Component, @Service, and @Repository in Spring?', N'Middle', N'These annotations are specialized versions of @Component used for semantic clarity and architectural layering. @Repository is specifically used for DAOs and enables automatic exception translation, while @Service denotes business logic, and @Component is a generic stereotype for any managed bean.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e125750-6779-493a-bf21-0c04068dc76f', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What are Query Parameters in Echo?', N'Intern', N'Query parameters are key-value pairs appended to the URL after a question mark. They are used for filtering, sorting, or providing additional configuration for a request and can be accessed via the context object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'274b7ea0-3f98-4700-8d8f-0c04794ecb58', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why is ''Supervision'' critical for the stability of a Phoenix application, and how does it relate to the ''Let it Crash'' philosophy?', N'Senior', N'Supervisors provide fault tolerance by monitoring child processes and restarting them if they fail, adhering to the ''Let it Crash'' philosophy where transient errors are contained rather than handled by complex defensive code. This allows the application to recover to a known good state automatically, ensuring high availability even when unexpected exceptions occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e003a09-1020-474b-a619-0c0494a50fe7', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber''s design influence the choice of dependency injection patterns?', N'Senior', N'Because Fiber relies on a specific context interface, developers often create wrapper structs or use functional options to inject dependencies. This ensures that the dependencies are available within the handler scope without violating the constraints imposed by the framework''s internal object pooling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcbe143f-392e-47d6-912e-0c04ac27b97f', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why does Rust use ''Result'' and ''Option'' types instead of exceptions?', N'Middle', N'These types force the developer to explicitly handle success and failure cases at compile time, eliminating the possibility of unhandled exceptions. This makes the control flow more visible and predictable throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e153998-b0fd-4b34-8298-0c0847b7b99b', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind''s mobile-first responsive design strategy work in practice?', N'Middle', N'Tailwind uses a mobile-first approach where base utility classes apply to all screen sizes, and responsive variants are applied using prefix modifiers. This ensures that the layout is designed for smaller devices by default, and styles are incrementally added as the viewport width increases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'136afd73-9128-4d6f-a438-0c0b2f1bc778', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the ''x-cloak'' directive?', N'Intern', N'The ''x-cloak'' directive is used to prevent the ''flash of unstyled content'' that might occur before Alpine initializes. It is usually combined with CSS to hide the element until Alpine is ready and removes the attribute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c9cd6f8-538e-4051-99b6-0c0d862ef0a7', N'a2838158-7305-480a-b22b-4dc35776b400', N'What are the architectural risks of ''Cascading Failures'' in microservices?', N'Senior', N'Cascading failures occur when a single service failure causes upstream services to exhaust their resources while waiting for timeouts, leading to a total system collapse. Mitigation strategies include circuit breakers to fail fast, bulkhead patterns to isolate resource pools, and aggressive request timeouts. Proper observability and automated scaling are also critical to preventing these failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ed35860-797a-47a8-b602-0c0e968bbd8e', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the difference between a Hash and an Array?', N'Junior', N'An Array is an ordered list of elements accessed by numerical indices starting at zero. A Hash is a collection of key-value pairs where elements are accessed by a specific key rather than a numerical position.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbd1596d-41f6-4987-956f-0c0ec00b0abc', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the role of the PHP autoloader?', N'Junior', N'An autoloader eliminates the need to manually write multiple include or require statements for classes. It automatically loads the required class file the moment a class is instantiated in the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8108cdc-c893-471a-8d77-0c11f6d4feda', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why does Actix-web use an asynchronous runtime like Tokio?', N'Junior', N'Actix-web is built on top of asynchronous Rust to ensure high performance and non-blocking I/O. The Tokio runtime provides the underlying infrastructure to schedule and execute these concurrent tasks efficiently, allowing the server to handle many connections simultaneously without blocking threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca653a08-f96a-492d-871a-0c15d70e9385', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is a volatile variable?', N'Intern', N'The ''volatile'' keyword tells the compiler that a variable''s value can change at any time due to factors outside the program''s control, such as hardware or another thread. This prevents the compiler from performing optimizations that might assume the variable remains constant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
