INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c5bee59-20dd-403b-ba48-0c187adcab53', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How do you handle timeouts in a Chi-based application?', N'Middle', N'You can use the built-in ''Timeout'' middleware, which wraps the request context with a timeout. This ensures that long-running requests are canceled after a specified duration, preventing resource exhaustion and improving overall server responsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8bff185-ff7c-4ce3-8f8d-0c1d1b387796', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the primary architectural advantage of using APIRouter in FastAPI?', N'Senior', N'APIRouter allows for the modularization of routes into multiple files, enabling better organization for large-scale applications. It permits developers to group related functionality, apply shared dependencies or tags to a subset of routes, and keep the main application file clean and maintainable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8e98dae-3b3d-4e4e-a29e-0c28aeef631e', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Explain the concept of zero-allocation in the context of Fiber''s request parsing.', N'Senior', N'Zero-allocation refers to the practice of parsing incoming byte streams directly into reusable buffers without creating new string or object instances on the heap. By reusing these buffers, the framework avoids triggering the garbage collector, which is the primary bottleneck in high-throughput Go network services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9169af1-fef7-444a-ad13-0c296d6837fe', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is Jinja2 in the context of Flask?', N'Intern', N'Jinja2 is the default template engine used by Flask. It allows developers to generate HTML dynamically by injecting Python variables and logic into HTML files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d7ef238-27d1-4090-a452-0c2cf1cf293a', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin''s inline function mechanism impact binary size and performance when used indiscriminately?', N'Senior', N'Inline functions replace the function call with the actual function body at the call site, which reduces stack overhead and allows for lambda object allocation avoidance. However, indiscriminate use leads to significant bytecode bloat, potentially hitting the 64KB method limit in DEX files and increasing instruction cache pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a50fd2b-5ce0-4140-ac8e-0c33c4b88b21', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does the Spring MVC ''DispatcherServlet'' process a request?', N'Middle', N'The DispatcherServlet acts as the Front Controller, receiving all incoming HTTP requests and delegating them to the appropriate handler mapping. It then invokes the corresponding controller method, handles data binding and validation, and finally manages the view resolution or response body serialization before returning the result to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'939328ab-4237-49b5-bd37-0c366a6147fd', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why is ''Immutability'' a cornerstone of Phoenix performance, and how does it simplify concurrency?', N'Senior', N'Immutability eliminates the need for locks and mutexes, as data cannot be modified once created. This removes the risk of race conditions and enables the VM to share data between processes safely without complex synchronization, leading to highly predictable and scalable concurrent performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec2d671a-233a-4008-bebe-0c36d6f5a539', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is a ''chunk'' in Webpack?', N'Intern', N'A chunk is a piece of code that is generated as a result of splitting the application into smaller parts. These chunks are the files that are actually sent to the browser during execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b1bb50d-9dbd-4812-91e2-0c378fc03acc', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is Svelte and how does it differ from traditional frameworks like React?', N'Intern', N'Svelte is a frontend framework that acts as a compiler rather than a runtime library. Unlike frameworks that do the bulk of their work in the browser, Svelte converts your code into highly optimized vanilla JavaScript during the build step.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92270b1b-db78-4d77-b2e9-0c397b90942f', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you balance the trade-off between automated testing coverage and development speed?', N'Middle', N'High test coverage increases confidence and reduces regression bugs, but it can slow down initial feature development and maintenance of the test suite. The approach should focus on testing critical business paths and complex logic, while accepting lower coverage in non-critical, frequently changing UI components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72ed13af-d7b9-4b65-b36f-0c3d55111c00', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How do FastAPI''s Sub-applications improve the modularity of a backend system?', N'Senior', N'Sub-applications allow you to mount independent FastAPI apps under a single root application, each with its own routes, middleware, and configuration. This is highly effective for building modular monoliths or integrating distinct services within a single deployment process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baa839ee-b12c-4549-bbd3-0c3ebddc8b34', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What are reducers in Redux?', N'Intern', N'Reducers are pure functions that take the current state and an action as arguments and return a new state. They specify how the application state changes in response to actions sent to the store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0d5d0d8-56ca-4795-b56d-0c405fc75ca2', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the role of the Ember Data store in an application?', N'Middle', N'The Ember Data store acts as a central repository for all models in an application. It manages the lifecycle of records, handles caching to prevent redundant network requests, and provides a unified interface for fetching and persisting data from various backends.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2af73698-c8ab-4253-b833-0c40d788055d', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the primary purpose of the C++ ''Type Erasure'' pattern?', N'Senior', N'Type erasure allows different types with a common interface to be stored in a uniform container without requiring a common base class. It achieves this by wrapping the specific type in a generic object that uses either virtual functions or function pointers to delegate operations back to the original type, decoupling the container from the specific implementation details.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65f95ad3-8b6e-4c8b-acd0-0c437f3eab10', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Discuss the performance implications of prop drilling and the architectural patterns used to solve it.', N'Senior', N'Prop drilling increases coupling and makes components harder to refactor, as intermediate components must handle data they don''t use. Architectures such as component composition, the provider pattern, or state lifting to a shared ancestor are used to encapsulate data flow and reduce the burden on the component tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38def435-589a-48fe-aa2e-0c4891c1f1e7', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle API documentation?', N'Intern', N'FastAPI automatically generates interactive API documentation using Swagger UI and ReDoc. This documentation is available at the /docs and /redoc paths of the running application without requiring any extra configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'095a4240-adf3-4493-a30d-0c48fabb147f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you create copy to clipboard button', N'Fresher', N'You need to select the content(using .select() method) of the input element and execute the copy command with execCommand (i.e, execCommand(''copy'')). You can also execute other system commands like cut and paste.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c57b720a-b5d9-4c89-8f48-0c514fcba4cf', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the ''initial state'' in a reducer?', N'Fresher', N'The initial state is the default value of the state provided to the reducer when the application first loads. It ensures that the store has valid data before any actions are dispatched.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc07c6f6-31ee-448f-b4f7-0c5549a8a763', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are asked to prioritize two features that seem equally important, how do you decide which one to tackle first?', N'Junior', N'I would look at the business value, potential dependencies, and the risk associated with each feature. I would then discuss the trade-offs with the product manager to understand which feature provides the most immediate benefit to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'311223eb-a5fc-4df0-82e8-0c560d909b0c', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Does Axum provide built-in support for WebSockets?', N'Intern', N'Yes, Axum includes first-class support for WebSockets through the axum::extract::ws module. This allows developers to handle persistent, full-duplex communication channels between the client and the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15ccf8f6-142c-43a5-b265-0c56e3df6347', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Does Chi have a built-in JSON validator?', N'Intern', N'No, Chi does not include a built-in JSON validator. It intentionally remains a focused routing library, leaving data validation and serialization to the standard library''s encoding/json package or other dedicated third-party packages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2b29554-4e7f-46fa-9f72-0c56fded2974', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What are the scalability limitations of Alpine.js when managing complex, high-frequency state updates across multiple components?', N'Senior', N'Alpine.js lacks a centralized state management architecture by design, making global state propagation across deeply nested or distant components difficult. When state updates occur with high frequency, the lack of a virtual DOM means every change triggers direct, granular DOM updates which can lead to layout thrashing. It is best suited for localized interactivity rather than complex, data-intensive state synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f55d0b8e-aec9-4503-8525-0c57177ef108', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the primary benefit of moving from a monolithic database to a polyglot persistence architecture?', N'Senior', N'Polyglot persistence allows developers to use the best database technology for specific data types, such as graph databases for relationships or document stores for unstructured data. This optimizes performance and development speed for varied workloads, though it increases operational overhead by requiring expertise in multiple data systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b30cbc09-71f8-4aa4-a299-0c57ede916e8', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why is Preact''s virtual DOM implementation considered ''shallow'' in comparison to React''s?', N'Senior', N'Preact''s VDOM structure is intentionally flatter to reduce pointer chasing and memory fragmentation during the diffing phase. By keeping the object representation of nodes as simple as possible, it facilitates faster property access during reconciliation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3e39381-8d31-4dc0-9bdd-0c5b3c604546', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between VACUUM and VACUUM FULL in PostgreSQL?', N'Middle', N'VACUUM reclaims storage occupied by dead tuples and marks them as available for future reuse without locking the table. VACUUM FULL physically compacts the table by writing a new version of it, which requires an exclusive lock and releases disk space back to the operating system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1cb8a3b0-b4ac-43d6-9555-0c5b83bb1055', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How are environment variables typically accessed in an Axum app?', N'Intern', N'Environment variables are typically read during application startup and stored in a configuration struct. This struct is then passed into the application state so that handlers can access the configuration values as needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9dd4c4c1-a731-43f9-a973-0c5ca3fd1426', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do database locks help transactions?', N'Fresher', N'Locks are mechanisms that prevent multiple transactions from modifying the same data simultaneously. By acquiring a lock, a transaction ensures that no other process can change the data until the lock is released, maintaining isolation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0afeede2-5cf3-4de7-babe-0c5d61e7118c', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you balance the need for comprehensive test coverage with the pressure to release features quickly?', N'Junior', N'I focus on a testing pyramid approach, prioritizing automated unit and integration tests for critical business logic. I accept less coverage for non-critical UI components to maintain velocity without compromising system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ab26e0e-ccb5-415e-8c44-0c610d144961', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is an Implicit Parameter in Scala and why should it be used cautiously?', N'Middle', N'Implicit parameters allow the compiler to fill in method arguments automatically from the current scope. They should be used cautiously because they can make code difficult to read and maintain by obscuring where dependencies are coming from, potentially leading to unpredictable behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0cd7f7a-9ebe-4cc0-b4a9-0c672912d891', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you decide whether to spend more time refining a solution versus delivering a ''good enough'' version quickly?', N'Junior', N'I evaluate the trade-off between the business impact of the deadline and the long-term technical debt incurred by rushing. If the task is a core system component, I prioritize robustness and testability. If it is an experimental feature or a prototype, I focus on meeting the immediate requirements and document the areas that need future refactoring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eebda160-c081-4fb3-9642-0c67df7fb2b8', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are the trade-offs of using ''Any'' versus ''AnyObject''?', N'Middle', N'Any can represent an instance of any type, including functions and value types, whereas AnyObject is restricted to class instances only. Using Any is more flexible but requires explicit casting, which can lead to runtime errors if misused. AnyObject provides better type safety for scenarios specifically involving reference-type behaviors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'260dd045-0b91-407e-a338-0c695e0835e6', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Define the Isolation property in ACID.', N'Junior', N'Isolation ensures that concurrent transactions do not interfere with each other. It makes it appear as if each transaction is executing in complete seclusion, preventing intermediate states of one transaction from being visible to others.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8b8bda5-6d36-4fb7-a354-0c6baa94bcac', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra''s peer-to-peer architecture differ from a master-slave model?', N'Middle', N'Cassandra uses a decentralized peer-to-peer architecture where every node is identical and can handle any read or write request. This eliminates single points of failure and prevents bottlenecks associated with a primary master node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'923a711f-d6dd-4f63-b222-0c6d36dcc562', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is Middleware in ASP.NET Core and what is its primary purpose?', N'Intern', N'Middleware consists of software components that are assembled into an application pipeline to handle requests and responses. Each component decides whether to pass the request to the next component in the pipeline and can perform actions both before and after the next component is invoked. Its primary purpose is to process HTTP requests and responses by executing logic like authentication, routing, or error handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15b96471-5a92-4c60-9a50-0c6d9825122b', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is type narrowing in TypeScript?', N'Junior', N'Type narrowing is the process of refining a variable''s type within a specific block of code. This is typically achieved through control flow statements like if-checks using ''typeof'', ''instanceof'', or custom type guards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'322c50ea-fa8a-40e0-b95c-0c6f613fc1db', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Describe the mechanism behind Laravel''s Queue worker scalability and how to prevent race conditions in job processing.', N'Senior', N'Queue workers operate independently, scaling horizontally by adding more processes. To prevent race conditions, you must implement atomic locks using the cache driver or rely on database-level constraints and pessimistic locking within the job''s execution logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7394e68-dc79-4c4f-a7f4-0c72493d9e05', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Why are mutable default arguments considered a common anti-pattern in Python?', N'Middle', N'Default arguments are evaluated only once at the time of function definition, not every time the function is called. If a mutable object like a list or dictionary is used as a default, changes made to that object during one function call persist across subsequent calls, leading to unexpected behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e304447-ec96-4c39-a892-0c737aa95a27', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js manage memory in long-lived single-page applications?', N'Senior', N'Alpine automatically cleans up event listeners and reactive bindings when an element is removed from the DOM. However, developers must be cautious when attaching listeners to global objects or external stores, as these references may persist if not explicitly cleaned up via custom lifecycle management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
