INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8ca4477-51ca-4362-b4a8-0c75066fc00d', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'When should you prefer Redux Toolkit over vanilla Redux?', N'Middle', N'Redux Toolkit is the recommended approach for modern Redux development as it reduces boilerplate significantly. It includes built-in utilities for store setup, immutable state updates, and asynchronous logic, leading to cleaner and more maintainable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75075ea0-50c8-4790-9edd-0c7513fee580', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between the article and section tags?', N'Junior', N'An article tag is intended for self-contained, independent content that could be syndicated, such as a blog post or news story. A section is meant for grouping related content that is part of a larger whole, like different chapters or categories on a page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04d20490-fa83-4238-8814-0c7755e2bbce', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Explain the concept of reactivity in Alpine.js.', N'Junior', N'Reactivity in Alpine.js means that when the data defined in x-data changes, the UI automatically updates to reflect those changes. Alpine tracks these data dependencies and ensures that whenever a bound property is modified, any connected DOM elements are re-rendered or updated accordingly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00511d6f-afc8-4cb4-a8ed-0c78a587a7da', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are the common ways to handle errors in Hono?', N'Junior', N'Hono provides a dedicated error handling middleware that catches exceptions thrown during the request lifecycle. Developers can define a global error handler to return standardized JSON responses instead of crashing or leaking stack traces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d945dfb-dc53-41c9-bddf-0c79515f7984', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle cache busting for static assets?', N'Middle', N'Vite automatically appends a content-based hash to the filenames of bundled assets and chunks in production. When the content of a file changes, the hash changes, forcing the browser to download the new version rather than using the cached one.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'598a334d-0ba3-42c3-871d-0c7b544a5f9d', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the architectural impact of using jQuery-based plugins on the browser''s main thread?', N'Senior', N'Many jQuery plugins perform DOM-intensive operations that block the main thread, resulting in unresponsive interfaces. Modern architecture encourages offloading heavy computations to Web Workers, which is natively supported by modern frameworks but difficult to implement with jQuery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
