INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2adafc06-54be-41d4-af35-0c7f70b46f41', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the global object in Node.js?', N'Intern', N'In Node.js, the global object is ''global''. It is similar to the ''window'' object in browsers and contains variables and functions that are available anywhere in the application scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0afc914b-278c-46b8-b569-0c7fb5971f4b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are global variables?', N'Intern', N'Global variables are declared outside of a function or declared with a window object for accessibility throughout the program (unless shadowed by locals). If you declare a variable without using var, even if it''s inside a function, it will still be seen as global. The var statement declares a function-scoped or globally-scoped variable, optionally initializing it to a value. Example: Example: Declaring global variable within function Using Undeclared Variables: * In strict mode, if you attempt to use an undeclared variable, you''ll get a reference error when you run your code. * Outside of strict mode, however, if you assign a value to a name that has not been declared with let, const, or var, you''ll end up creating a new global variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
