INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e118e76-9ec0-4cc4-bcb8-0c80a8df69a4', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the benefit of using Redis transactions?', N'Junior', N'Redis transactions allow a group of commands to be executed in a single, isolated step. This ensures that either all commands in the sequence are executed or none are, providing a basic level of consistency for operations that require multiple steps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f847123-d04a-4c71-9958-0c8197311ff3', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is ''Database Sharding'' and how does it relate to the concept of ''Shared-Nothing'' architecture?', N'Senior', N'Sharding is the process of splitting a large dataset into smaller, independent chunks across different physical machines. It is the implementation of a ''Shared-Nothing'' architecture, where each node is self-sufficient and does not share memory or storage, allowing for linear scalability without contention at the storage layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
