INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef52114a-7ac3-4b12-9537-0c99e9bf5411', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is encapsulation?', N'Intern', N'Encapsulation is the practice of bundling data and the methods that operate on that data into a single unit or class. It also involves restricting direct access to some of an object''s components, usually through access modifiers like private, to protect the internal state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1793c31f-3b6d-4e2b-8555-0c9c2a95fbef', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch ensure data durability during node failures?', N'Middle', N'Data durability is ensured through replica shards and the translog. If a primary shard fails, a replica is promoted to primary, and the translog ensures that indexed data not yet flushed to the disk segment is not lost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
