INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bd38391-a359-4a55-ad13-0ca9dd0fcc78', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the Java Virtual Machine handle OutOfMemoryError?', N'Middle', N'OutOfMemoryError occurs when the JVM cannot allocate more objects because the heap is exhausted and the garbage collector cannot free up enough space. This usually happens due to memory leaks or incorrect heap size configuration. The JVM typically throws this error to signal that the application has exceeded its memory limits and requires intervention, such as heap tuning or code optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc291896-1dca-4012-af8f-0cab810e9d0a', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle code splitting?', N'Fresher', N'SvelteKit automatically performs code splitting by creating separate JavaScript bundles for each route. This ensures that users only download the code necessary for the current page, resulting in faster load times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
