INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f0904ac-c30d-44ce-83b1-0cad1e7efec6', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the impact of ''Type Instantiation'' limits on deep recursive types?', N'Senior', N'TypeScript imposes limits on the complexity of type instantiation to prevent infinite recursion and excessive memory consumption during compilation. Exceeding these limits forces developers to refactor types into flatter, more explicit structures, which can improve compilation performance and type readability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
