INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5a5c5ad-cfa5-4a77-97fc-0cc31c6cc8a4', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of the Redo Log in MySQL?', N'Middle', N'The Redo Log is a disk-based data structure used during crash recovery to ensure durability. It records changes made to the data pages so that if the system crashes before the changes are written to the main data files, they can be replayed to restore consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
