INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5ab05f3-688f-4bf5-98b6-0cc8f69529d0', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How do you prevent ''Phantom Reads'' in MySQL?', N'Middle', N'Phantom reads, where new rows appear in a range scan during a transaction, are prevented by the default ''Repeatable Read'' isolation level in InnoDB. It uses ''Next-Key Locking'' to lock the index records and the gaps between them, preventing other transactions from inserting new rows within the range.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97948b29-6509-45b4-9557-0cd03b6064ad', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the architectural impact of a ''fan-out'' pattern in a publish-subscribe system?', N'Senior', N'Fan-out allows a single message to be broadcast to multiple subscribers, increasing system flexibility but potentially amplifying load significantly on the message broker. To maintain performance, the broker must efficiently handle subscription management and resource isolation to ensure one slow subscriber does not degrade delivery performance for others.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
