INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59dc0294-b9b5-4561-a8c7-0cdc1bacd042', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why do many NoSQL databases utilize Log-Structured Merge (LSM) trees instead of B-trees?', N'Senior', N'B-trees involve random I/O for updates, which performs poorly on spinning disks and even some SSDs. LSM trees transform random writes into sequential writes by buffering updates in memory and flushing them to immutable sorted files, significantly increasing write throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcf05356-d875-422d-b259-0cde10b77bb3', N'4c000000-0000-0000-0000-000000000005', N'How does ''Eventual Consistency'' impact the design of the user interface?', N'Senior', N'UI design must account for latency between action and state reflection, often by using optimistic UI updates or displaying ''processing'' states to the user. Developers must ensure that the application handles out-of-order events or stale data gracefully to avoid confusing the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0136eaeb-2af2-4a09-ba09-0cdfddb4e035', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why does Svelte handle state updates via simple variable assignment rather than immutable state setters?', N'Middle', N'Svelte uses the assignment operator as a trigger to schedule DOM updates, which simplifies the developer experience by avoiding complex immutable patterns. Because the compiler knows which variables are reactive, it can surgically inject update logic directly into the code where assignments occur, ensuring optimal performance without the overhead of state management libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2dae780-179e-463b-a50d-0ce00e2cc12a', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the purpose of the ''Replica Priority'' setting in Redis Sentinel?', N'Senior', N'The replica priority determines which replica is preferred for promotion during a failover if multiple candidates are available. A lower numerical value signifies higher priority, allowing administrators to designate specific, more powerful, or better-located replicas to take over as master.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc92aa4b-293a-47d9-b954-0ce448c327a0', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express facilitate the implementation of a microservices pattern?', N'Senior', N'Express is lightweight and unopinionated, making it easy to create small, single-purpose services that communicate via REST or gRPC. Its minimal footprint allows for fast boot times and low resource usage, which are ideal for deployment in containerized environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57ffa2ee-270f-4236-8a45-0ce482efe8d0', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is a Sass compiler?', N'Junior', N'A compiler is a tool or build-step process that translates Sass code into standard CSS. Popular examples include Dart Sass, which is the primary implementation used in modern web development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c1719c3-e232-4f3f-a797-0ce819ef93dc', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How to gracefully shutdown Node.js Server?', N'Fresher', N'The graceful shutdown of our application indicates when all of the resources it used and all of the traffic and/or data processing what it handled are closed and released properly. It means that no database connection remains open and no ongoing request fails because we stop our application. Possible scenarios for a graceful web server shutdown: * Handle process kill signal * Stop new requests from client * Close all data process * Exit from process Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0652804e-6e2b-475e-bf4e-0ce8c4b3aa2b', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the reason not to update the state directly?', N'Intern', N'We want to explicitly track application state in order to implement tools that can log every mutation, take state snapshots, or even perform time travel debugging. So we need to commit a mutation instead of changing store''s state directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'885e239d-7d85-4a70-ba36-0ced1e738a27', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How do Ruby''s ''method_missing'' and ''respond_to_missing?'' interact with metaprogramming performance?', N'Senior', N'Method_missing allows dynamic handling of undefined method calls, but it is computationally expensive because it triggers a full search of the ancestor chain. Implementing respond_to_missing? is essential for maintaining consistency with Ruby''s reflection APIs and improving performance by allowing the runtime to verify method existence without invoking the full dispatch mechanism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0a7a1c9-761f-4565-a5d7-0cedf0e21ffa', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Do I need to rewrite all my class components with hooks?', N'Middle', N'No. But you can try Hooks in a few components(or new components) without rewriting any existing code. Because there are no plans to remove classes in ReactJS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'330d8902-72a7-4672-a9ed-0cef18035f8b', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is a group in Fiber routing?', N'Intern', N'A group is a feature that allows developers to prefix a set of related routes with a common path. This is useful for organizational purposes, such as grouping all API v1 endpoints under a single ''/api/v1'' prefix.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'024d8384-33b8-4a8d-b6a6-0cef7b801b43', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the role of the TypeScript compiler (tsc)?', N'Intern', N'The TypeScript compiler is responsible for checking the code for type errors and transpiling the TypeScript source code into standard JavaScript. It also generates declaration files and manages configuration settings defined in the project configuration file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e9efa70-73a6-4719-bf2a-0cf05f4c4aa4', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is it often discouraged to use Tailwind with very generic class names in large teams?', N'Middle', N'Using generic or deeply nested utility combinations without component abstraction leads to high cognitive load and difficulties in refactoring. When the same complex set of utilities is repeated across many files, changing a design requirement becomes a labor-intensive task that is prone to human error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'feb1f020-a9cb-4d81-96bb-0cf07eccd0a0', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is meant by ''Auto-imports'' in Nuxt?', N'Fresher', N'Auto-imports is a feature where Nuxt automatically detects the functions, components, and composables you use in your code and imports them for you. This reduces the need for manual import statements at the top of your files, making the development process faster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4c48f6b-ee40-4782-bac0-0cf5a61ff7a6', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a system where logs show a request was received but never processed?', N'Senior', N'I would investigate the message buffer, request queue, or potential thread starvation that might be preventing the application from picking up the request. I would also check for potential silent failures in middleware or interceptors that might be consuming the request before it reaches the main application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
