INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7b29b1d-7f0b-49fe-afcb-0d07bef3137e', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the benefit of DynamoDB Accelerator (DAX)?', N'Middle', N'DAX is a managed, write-through, in-memory cache for DynamoDB that provides microsecond response times for read-heavy workloads. It reduces the load on the underlying table and simplifies the application architecture by handling cache invalidation automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8af6309-43a6-4f4d-a16b-0d08561bba8c', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What are Guard functions in Litestar and when should they be used?', N'Middle', N'Guards are functions that run before a route handler to check for specific conditions, such as user authentication or authorization. If the guard raises an exception, the handler is not executed, providing a clean way to implement security layers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'873828a4-a175-45a7-8349-0d0fe5e2e5b8', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are the trade-offs of using synchronous database drivers in a FastAPI application?', N'Middle', N'Using synchronous database drivers in an ''async def'' endpoint will block the event loop, effectively negating the benefits of asynchronous concurrency. While FastAPI can run them in a thread pool, it adds overhead and makes the application less scalable compared to using native asynchronous drivers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd35864a5-2330-4e90-bc4e-0d1117046efc', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the function of the ''App'' object in Litestar?', N'Junior', N'The App object is the central point of your application configuration. It is where you register your routers, middleware, plugins, and global settings that define the behavior of the entire web service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee3ee047-0cbb-497c-9066-0d11a80b1865', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin’s routing performance compare to the standard library net/http router in terms of algorithmic complexity?', N'Senior', N'Gin utilizes a Radix tree (prefix tree) for routing, which provides O(k) lookup time where k is the length of the path. The standard library router typically uses a map-based approach or linear searching, making Gin significantly more performant as the number of registered routes grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04efbca1-2cbb-4ade-b365-0d11cce6e88e', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle concurrent requests, and what are the limitations regarding shared state?', N'Senior', N'Gin runs each incoming request in its own goroutine, naturally leveraging Go''s concurrency model. However, handlers must be thread-safe; shared state within handlers or controllers must be protected by mutexes or atomic operations to prevent data races.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2798cf5-5e2b-4fc9-8e11-0d1249fb218a', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is Compaction in Cassandra?', N'Intern', N'Compaction is the background process that merges multiple SSTables into fewer, larger ones. This process cleans up obsolete data, such as deleted records or older versions of updated data, and optimizes read performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f512182-2117-4e0a-a68b-0d1275a0cfcc', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'When should you use ''useAsyncData'' versus ''useFetch'' in a Nuxt application?', N'Middle', N'useFetch is a wrapper around useAsyncData that provides a more convenient syntax for standard data fetching. Use useAsyncData when you need more granular control, such as manual transformation of the response or custom caching logic, while useFetch is preferred for most simple API requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32ef7f58-c79a-4bc9-9536-0d12dd36c8df', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the benefits of new JSX transform?', N'Intern', N'There are three major benefits of new JSX transform, 1. It is possible to use JSX without importing React packages 2. The compiled output might improve the bundle size in a small amount 3. The future improvements provides the flexibility to reduce the number of concepts to learn React.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abd344ec-f0ec-461e-94e8-0d13b709f87a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you handle a situation where you are behind on a deadline?', N'Fresher', N'I would communicate the status of my work to my manager as early as possible so that expectations can be adjusted. I would also discuss which parts of the task can be prioritized to ensure that the most important features are delivered on time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63a388a1-363b-4293-8eed-0d18219f12bb', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the trade-off of using ''willUpdate'' versus ''updated'' lifecycle hooks?', N'Middle', N'The willUpdate hook runs before the DOM is updated and allows for side effects based on property changes, while updated runs after the render is complete. Using willUpdate is safer for calculating derived state, whereas updated is the appropriate place for DOM measurements or manual interaction with the rendered elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efb9705d-b78f-4cca-aa3a-0d1840bbc23c', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the ''Request Stack'' in Symfony?', N'Middle', N'The Request Stack is a service that provides access to the current request object and, in some cases, previous requests in the stack. It is essential for services that need to interact with the current HTTP request, such as for localization or URL generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8a8f2fb-fa65-47fe-84e7-0d186652af09', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo facilitate testing of API endpoints?', N'Middle', N'Echo''s design makes unit testing easy because handlers accept a context object that can be mocked or initialized with a fake request and response recorder. This allows testing the logic of each handler in isolation without starting a real network server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aedc29b9-8ad5-4da0-b2c5-0d19dbbe702b', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What are the common security challenges in a microservices environment?', N'Middle', N'The primary challenge is securing the ''east-west'' traffic between services, not just the ''north-south'' traffic at the perimeter. This is often solved using mTLS for transport security and implementing centralized identity propagation, such as JWTs, to verify user identity across service boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b921f02-9cb8-4a49-8ba6-0d1a76a663c3', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is Lucid ORM, and why is it used?', N'Junior', N'Lucid is the built-in ORM for AdonisJS that provides an abstraction layer over the database. It allows developers to interact with database records using object-oriented syntax instead of raw SQL queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb7ddf2f-8c28-4195-9c2b-0d1f01f54a3d', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a hot standby and a warm standby?', N'Middle', N'A warm standby is a standby server that is kept in a state where it can be promoted to a primary, but it cannot process read-only queries. A hot standby can process read-only queries while simultaneously receiving data from the primary, making better use of hardware resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13240f4e-3870-4f9f-a84d-0d2062d5d0c2', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Explain why C''s type system is considered ''weak'' compared to higher-level languages.', N'Senior', N'C allows for implicit type conversions and pointer casting that bypass the intended type safety, essentially treating memory as a raw sequence of bytes. While this provides the flexibility required for low-level systems tasks and hardware manipulation, it lacks the compile-time guarantees that prevent logic errors. This requires developers to use static analysis and defensive programming practices to enforce the type invariants that the language itself does not guarantee.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cce0a478-bc3c-4c4b-8041-0d206e5689c4', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the Elvis operator?', N'Intern', N'The Elvis operator is a shorthand syntax used to provide a default value when a nullable reference might be null. It evaluates an expression and returns its value if not null, otherwise returning the provided default value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75cff191-30a2-474e-8c3f-0d22210089d3', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you decide between fixing a bug immediately and continuing with planned feature work?', N'Junior', N'I would weigh the severity of the bug against the business priority of the feature. If the bug is a blocker or impacts user data, it takes precedence; otherwise, I would consult with my team lead to manage the sprint backlog appropriately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c97276a-027c-4f72-a16c-0d2249347444', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the purpose of the ''generateMetadata'' function in the App Router?', N'Senior', N'The ''generateMetadata'' function allows for dynamic SEO configuration based on route parameters or data fetched on the server. It centralizes metadata management, ensuring that search engines receive accurate, dynamically generated information for every page without requiring client-side updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd142e53e-f4de-43fa-ab7f-0d292c162da7', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why is Axum''s strictly typed request handling superior to dynamic alternatives in large codebases?', N'Senior', N'Strict typing at the extractor level forces developers to define and validate the contract between the transport layer and the business logic at compile time. This drastically reduces runtime errors related to missing fields or type mismatches, which are common in dynamically typed frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
