INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d4410e3-60e9-47ed-9831-0d36579e92b6', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the purpose of the Remix compiler?', N'Intern', N'The Remix compiler manages the build process by bundling your code and transforming it for production. It optimizes the assets to ensure that the application is fast, efficient, and compatible with various browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f718457-e976-4bc0-ad75-0d371231f9df', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Why is it important to design APIs with ''least privilege'' in mind?', N'Middle', N'Least privilege ensures that an API key or token has only the permissions necessary for its intended task. This minimizes the blast radius if an API key is compromised, as the attacker cannot perform unauthorized operations outside the specified scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'770c636f-14f1-4114-9bb0-0d39f2aecebe', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the purpose of the key prop in React?', N'Intern', N'The key prop tells React how to identify each child in a list across renders so it can match the right component instance to the right data, preserve its state, and reorder DOM nodes correctly. A key only needs to be unique among siblings, not globally. Changing a component''s key is also the idiomatic way to reset its state — React unmounts the old instance and mounts a fresh one. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcd6ebfa-ab09-4007-a762-0d3aeddd6649', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI''s dependency injection compare to standard patterns in other languages like Java''s Spring or C#''s .NET DI?', N'Senior', N'FastAPI''s DI is request-scoped and specifically designed for the web request/response lifecycle rather than being a full-fledged service container. It is more lightweight and dynamic compared to the heavy compile-time or reflection-based containers found in Spring, making it easier to integrate into Python''s dynamic environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99ed5aee-297c-490c-9406-0d3cb8398565', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the inverted index used for in Elasticsearch?', N'Fresher', N'The inverted index is the core data structure that allows for fast full-text searches. It maps every unique word to the list of documents that contain that word, enabling the engine to quickly find relevant documents.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8e77a2c-e810-4b3b-b39f-0d3d03e263f6', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the difference between the ''dev'' and ''prod'' environments?', N'Junior', N'The ''dev'' environment is optimized for debugging, providing detailed error pages and profiler tools, while the ''prod'' environment is optimized for performance and security. In ''prod'', debugging features are disabled, and configuration is cached to ensure faster execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'becdb3bd-ffa5-418e-84ca-0d3fea8eb1e9', N'4c000000-0000-0000-0000-000000000005', N'Explain the concept of eventual consistency and when it is an acceptable trade-off.', N'Middle', N'Eventual consistency means that while all replicas of data will eventually converge to the same value, they may temporarily return different data during updates. This is an acceptable trade-off in systems where high availability and low latency are prioritized over immediate data accuracy, such as in social media feeds or product recommendations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b58596fd-0818-4ff2-a63e-0d41e0e8f438', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut support testing?', N'Intern', N'Micronaut provides robust support for testing through a dedicated testing framework that allows for easy integration tests. It can start the application context within a test environment, enabling developers to verify dependency injection and bean behavior without deploying the full application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c490e053-aa46-4b58-8f23-0d4216fb4114', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Does Fiber have built-in support for request validation?', N'Fresher', N'While Fiber does not have a strict built-in validation engine, it integrates easily with existing Go validation libraries. Developers typically use these libraries within their handlers to verify request bodies against specific rules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66cdf1ad-941f-48ee-bbd0-0d4391629d1b', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle form validation?', N'Intern', N'AdonisJS includes a validator package that allows developers to define schemas for incoming request data. It automatically checks if the input meets the required rules and returns an error response if the validation fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'702d3540-8f17-4fc7-af3c-0d43d937fffc', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How do you test a Litestar application without starting a network server?', N'Middle', N'Litestar provides a ''TestClient'' that interacts directly with the ASGI application instance. This allows for fast, isolated integration tests that simulate the entire request-response lifecycle without the overhead of network sockets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6724d0f7-4ef9-499c-babd-0d4510c04580', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the primary goal of Qwik?', N'Fresher', N'The primary goal of Qwik is to provide instant loading web applications regardless of their size or complexity. It achieves this by focusing on delivering minimal JavaScript to the browser and delaying execution until user interaction occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
