INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c168cc15-6794-42ad-8a4f-0d49db579e45', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of @RequestMapping?', N'Intern', N'@RequestMapping is used to map web requests to specific controller methods. It can be used at the class level to define a base path and at the method level to refine the mapping based on URL patterns and HTTP methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf692ec3-ea0b-4e91-8471-0d4a7d7ef833', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the role of the Safepoint mechanism in JVM garbage collection and thread coordination?', N'Senior', N'A safepoint is a specific point in code execution where thread state is consistent, allowing the JVM to safely pause threads for garbage collection or stack scanning. All threads must reach a safepoint before the VM can perform non-atomic operations, ensuring memory integrity and preventing race conditions during heap snapshots.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4349e465-87fc-4089-bed9-0d4cad351051', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does the ''hidden'' node type work in a replica set?', N'Senior', N'A hidden node is a member of a replica set that maintains a copy of the data but is invisible to the application for read distribution. These nodes are typically used for dedicated tasks like analytics, reporting, or off-site backups to prevent impacting the performance of primary and secondary nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8958a374-ce16-45b4-aebf-0d4ee587cbaf', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle navigation?', N'Intern', N'Remix uses its own Link component to handle navigation. Unlike a standard anchor tag that triggers a full page refresh, the Link component allows the framework to preload data and perform faster transitions between routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b959af2-112a-4eb7-9c3c-0d50241be88f', N'4c000000-0000-0000-0000-000000000005', N'What is the role of an API Gateway in a microservices system?', N'Middle', N'An API Gateway acts as a single entry point for all client requests, handling tasks like authentication, SSL termination, rate limiting, and request routing. It simplifies the client-side interaction by abstracting the internal complexity of the microservices architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5550e916-96cb-4998-b288-0d517b1c68c4', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the Write-Ahead Log (WAL) and how does it relate to the checkpoint process?', N'Senior', N'The WAL ensures durability by recording changes before they are applied to data files, allowing recovery after crashes. Checkpoints periodically flush dirty pages from shared buffers to disk, allowing the system to truncate the WAL and reduce recovery time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d510ce9-11e2-4d45-be67-0d5740e05555', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What are the advantages of using a cache as a message broker?', N'Middle', N'Some cache systems support pub/sub capabilities, allowing them to act as lightweight brokers for real-time notifications or task queues. This can simplify architecture by reusing existing infrastructure, though it may lack the persistence guarantees of dedicated message queuing systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9597453-e583-4983-8dea-0d57741407e5', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the difference between a client-side error and a server-side error, and how do you identify them?', N'Fresher', N'Client-side errors, often indicated by 4xx status codes, occur when the request itself is invalid or unauthorized. Server-side errors, indicated by 5xx codes, mean the server encountered an unexpected condition while trying to fulfill a valid request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40686629-8b40-46cb-b54d-0d585c03a3fb', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the difference between Snapshot Isolation and Serializability?', N'Middle', N'Snapshot isolation allows a transaction to operate on a consistent version of the database from the moment the transaction started. While it prevents many anomalies, it is generally weaker than serializability because it does not prevent write skew, where two transactions modify different rows that violate a shared constraint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
