INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e05eeb30-ef13-43d8-b302-0d5a814d4262', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are Database Migrations?', N'Intern', N'Migrations are a version control system for your database schema. They allow you to define the structure of your tables in code, making it easy to share and apply schema changes across different development environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
