INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b14f05c-d52a-4380-ab5f-0d5e988e47fc', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is a session in Rails?', N'Intern', N'A session is a mechanism for storing user-specific data across multiple HTTP requests. Because HTTP is stateless, sessions allow the application to remember information like user authentication status or shopping cart contents as the user navigates the site.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'509f81ad-8425-4982-8bb4-0d624f1e5331', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Describe the implementation of a circuit breaker pattern and why it is essential for system reliability.', N'Senior', N'A circuit breaker prevents a system from repeatedly trying to execute an operation that is likely to fail, thereby avoiding resource exhaustion and cascading failures. It allows a failing downstream service time to recover while providing a graceful fallback or error response to the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a78b66c-b1ad-4ede-9fa6-0d6298c3e800', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why is it important to use middleware in a backend service?', N'Intern', N'Middleware allows you to decouple cross-cutting concerns from your business logic. By moving tasks like logging or authentication into middleware, your primary handlers remain focused on their core responsibilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a68345f-234d-4595-ab56-0d62c37120c4', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is server-side rendering (SSR) in Qwik?', N'Intern', N'SSR in Qwik involves rendering the initial HTML on the server and sending it to the browser. Unlike traditional SSR, Qwik attaches the necessary metadata to resume execution on the client without needing to re-hydrate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5ad74a2-d3c5-4279-8fed-0d6548b4e6f6', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the primary trade-off of using a highly modular Axum architecture?', N'Middle', N'The primary trade-off is increased complexity in tracing the request flow through multiple layers of middleware and nested routers. While it improves testability and code reuse, it can make debugging specific request failures more difficult.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60cf4ed0-af73-47a6-804c-0d65a4935924', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is a Redux store?', N'Intern', N'A store is a single object that holds the entire state tree of your application. It is the central hub where the application data lives and from which components can subscribe to updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f41b942-6b57-432d-9208-0d6aeb2fe0fa', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite manage environment variables, and why is the VITE_ prefix required?', N'Senior', N'The VITE_ prefix prevents accidental leakage of sensitive server-side environment variables into the client-side bundle. Vite explicitly exposes only variables with this prefix via import.meta.env to ensure security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1448952-940f-44fd-b908-0d6dd00c7c3b', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What architectural patterns help mitigate the ''n+1 query problem'' when using an ORM within Flask views?', N'Senior', N'To mitigate this, you should use eager loading techniques provided by the ORM, such as joined or subquery loading, to fetch related data in a single query rather than inside a loop. Alternatively, implementing a Data Access Layer or Repository pattern can centralize query logic, making it easier to optimize data fetching strategies across the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e80c8821-0d81-470e-aa5d-0d6eb87c829e', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach troubleshooting an issue where a service is intermittently failing due to ''too many open files''?', N'Senior', N'I would audit the service''s resource descriptors to identify potential leaks in file handles, sockets, or database connections. I would also verify that the OS-level file descriptor limits are correctly tuned for the application''s concurrency model and that all resources are properly closed in finally blocks or using context managers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b32d124-6799-4fe5-a46a-0d6feb6174e9', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the z-index property used for?', N'Intern', N'The z-index property specifies the stack order of elements that overlap each other. An element with a higher z-index value is placed in front of an element with a lower value, provided the elements are positioned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0349130-7064-4e32-b7f0-0d710d6e4db8', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are lambda expressions, list comprehensions and generator expressions?', N'Intern', N'Lambda expressions are a shorthand technique for creating single line, anonymous functions. Their simple, inline nature often – though not always – leads to more readable and concise code than the alternative of formal function declarations. On the other hand, their terse inline nature, by definition, very much limits what they are capable of doing and their applicability. Being anonymous and inline, the only way to use the same lambda function in multiple locations in your code is to specify it redundantly. List comprehensions provide a concise syntax for creating lists. List comprehensions are commonly used to make lists where each element is the result of some operation(s) applied to each member of another sequence or iterable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd109020-f537-46e4-adbe-0d73167f3337', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How do value types and reference types differ in Swift regarding memory management and thread safety?', N'Middle', N'Value types like structs are copied when assigned or passed, which inherently avoids data races because each thread holds its own unique instance. Reference types like classes share the same memory location, requiring synchronization mechanisms like locks or serial queues to prevent race conditions. Structs are managed on the stack, while classes are allocated on the heap, making structs generally more performant due to reduced reference counting overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59017626-f8dc-4e60-a97d-0d779dacaf2d', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a column-family store and when is it typically used?', N'Junior', N'A column-family store organizes data into rows that can have a varying number of columns, making it efficient for large-scale data analysis and time-series data. It is typically used when you need to store and process massive datasets across distributed clusters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7363edc3-8df9-4b6e-9f1b-0d78416cfa09', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the purpose of a Merkle tree in distributed databases like DynamoDB or Cassandra?', N'Senior', N'Merkle trees are used for efficient data synchronization and anti-entropy processes between nodes. By comparing the hashes of data ranges at the leaf nodes, the system can quickly identify precisely which data segments differ without transferring the entire dataset, drastically reducing network overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6afa3e9-25cd-4615-9a52-0d784fc40f88', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How do Go''s generics impact binary size and performance?', N'Senior', N'Go implements generics using ''dictionaries'' or monomorphization, which can lead to binary bloat if the compiler generates specialized code for many different types. While this provides type safety and performance parity with concrete types, it increases build times and memory footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90ed4a81-c27a-4ed6-a2fd-0d80a1f4bff0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a storage event and its event handler', N'Intern', N'The StorageEvent is an event that fires when a storage area has been changed in the context of another document. Whereas onstorage property is an EventHandler for processing storage events. The syntax would be as below Let''s take the example usage of onstorage event handler which logs the storage key and it''s values', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d0e2ad3-ffd0-40b2-9630-0d81539f31a3', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What role does ''TTL Jitter'' play in preventing synchronized cache expiration?', N'Senior', N'Adding random jitter to TTL values prevents a large number of cache keys from expiring at the exact same moment. This spreads the recomputation load over time, preventing sudden spikes in database traffic and potential cascading failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9bf4e6d-9fda-464c-acb8-0d81a7c7f976', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does Dependency Injection work in NestJS?', N'Intern', N'Dependency Injection is a design pattern where a class requests dependencies from an external source rather than creating them itself. NestJS uses an internal IoC container to manage these dependencies, automatically instantiating and providing them to the classes that need them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95494fde-7e49-42d5-a0a3-0d829d633039', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What does type inference mean in Swift?', N'Fresher', N'Type inference is a feature where the compiler automatically determines the data type of a variable or constant based on the value assigned to it during initialization. This allows developers to omit explicit type declarations, making the code more concise while maintaining type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'427f02b6-2513-4018-9cab-0d83e877b6b2', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between an application.properties file and an application.yml file?', N'Middle', N'Both serve the same purpose of externalizing configuration, but YAML files support hierarchical structures and are generally considered more readable for complex configurations. Properties files are flatter, use dot notation, and are often preferred for simpler setups or when environment variable overriding is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ddf191b-03d5-4053-9898-0d851be0867a', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript''s ''lib'' setting influence the environment?', N'Middle', N'The ''lib'' setting defines the built-in JavaScript APIs and DOM interfaces available to the compiler. It allows you to target specific environments, such as browser-only APIs or newer ECMAScript versions, regardless of the target JavaScript output version.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b80934ee-af39-458f-a67d-0d874b00993f', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are Interceptors and what can they do?', N'Junior', N'Interceptors are powerful tools that can bind extra logic before or after method execution. They can transform the result returned from a function, transform the exception thrown, extend basic function behavior, or even override a function depending on specific conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47d8fdc4-c44b-48ae-b04d-0d87c3af26c0', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the benefit of keeping a development environment separate from the production environment?', N'Fresher', N'Separation ensures that changes or bugs introduced during development do not affect the live application used by customers. It provides a safe sandbox for testing new features and configurations before they are deployed to the real world.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16e62424-d49f-46c8-b061-0d892a8e5580', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Explain the difference between idempotent and safe HTTP methods.', N'Middle', N'A safe method, like GET or HEAD, does not modify server state and can be called repeatedly without side effects. An idempotent method, such as PUT or DELETE, ensures that performing the same request multiple times results in the same server state as a single request, even if the response status differs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efed9dd4-e1c5-4e1c-b4a9-0d8a561704e9', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does ''Virtual Nodes'' (vnodes) in consistent hashing improve the balance of a distributed cache?', N'Senior', N'Vnodes map a single physical cache node to multiple points on the hash ring, preventing ''hot spots'' caused by non-uniform key distribution. This allows for better load distribution, especially when nodes have heterogeneous hardware capacities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9780e8aa-e2d5-4920-9e58-0d8b83f28220', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the architectural benefits of using the Messenger''s ''Bus'' concept.', N'Senior', N'The Bus pattern decouples the message producer from the handler, allowing for multiple buses that can route messages differently, such as one for synchronous commands and another for asynchronous events. This separation of concerns simplifies system flow control and makes the application easier to refactor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34f8f6e1-7266-4d9f-8e5d-0d8f29e54f51', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is a Template Result in Lit?', N'Intern', N'A Template Result is an object returned by the render method that contains the information needed to render a template. Lit uses this object to efficiently update the DOM without re-rendering the entire structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c256159e-d4b7-4d53-a0df-0d91ed9842be', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are the benefits of using LiveView ''mount'' parameters for security?', N'Middle', N'The mount function allows you to authorize the connection before the LiveView process fully initializes. By validating session data or parameters here, you can prevent unauthorized users from accessing the socket or performing actions within the view.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f744e70a-23cd-4962-b105-0d925e4a174f', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are the performance implications of using Tailwind CSS in terms of browser rendering?', N'Middle', N'Tailwind generates highly optimized, flat CSS, which is generally very efficient for the browser to parse and apply. However, since the markup becomes more verbose, the HTML file size increases slightly, though this is usually offset by the reduction in the total CSS file size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'942716f1-c227-48bf-81cc-0d96c8645a26', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a Flask context processor?', N'Intern', N'A context processor is a function that runs before a template is rendered. Its purpose is to inject variables into the template context so that they are automatically available to all templates without having to pass them explicitly in every route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bb40209-5722-4600-9d83-0d97273f3370', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle data validation and serialization?', N'Junior', N'FastAPI uses Pydantic models to define the structure of request and response data. When a request arrives, Pydantic automatically validates the incoming JSON against the defined model and raises an error if the data types or required fields do not match.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c44730e0-e690-4d1c-82a1-0d9963257ad8', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik ensure security during the serialization process?', N'Senior', N'Qwik sanitizes serialized data to prevent XSS attacks that could occur if the HTML were tampered with before reaching the client. By validating the state during the restoration process, it ensures that only expected data structures are used to resume the app.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd508821-6019-4917-95dc-0d9a35d35303', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between @Autowired and @Inject?', N'Fresher', N'@Autowired is a Spring-specific annotation for dependency injection. @Inject is part of the Java Dependency Injection standard (JSR-330), which is more generic and can be used in other frameworks, though they function similarly in practice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'469cacb0-7262-4494-b103-0d9b1883ec0e', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How can you implement fine-grained rate limiting in a FastAPI application?', N'Senior', N'Fine-grained rate limiting is best implemented via middleware or dependencies that interface with a fast, distributed store like Redis. By checking the request count against an identifier like a user ID or IP address, you can enforce limits before the request reaches the business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad7b5e33-7083-4335-aed0-0d9bb27f05a8', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between shallow and deep copying of objects in PHP?', N'Middle', N'A shallow copy creates a new object and copies the properties, but nested objects still point to the same references as the original. A deep copy must be manually implemented to recursively duplicate nested objects, ensuring that modifications to one object do not unexpectedly affect the other.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af473f2d-0bd8-42c4-ab4c-0d9d1931ebc3', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle a situation where you accidentally pushed sensitive information, like an API key, to a public repository?', N'Junior', N'I would immediately revoke the key, rotate it to a new value, and remove the sensitive file from the repository history using version control tools. I would then inform my team lead about the incident so we can ensure no unauthorized access occurred.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f7bc02b-a34f-4287-b3b3-0d9ee758e522', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How can you loop over an array in Alpine.js?', N'Junior', N'You use the x-for directive on an element to repeat it for every item in an array. It is typically used in conjunction with a template tag to ensure the structure remains valid HTML while generating a list of elements based on your data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bc14b8c-a4d5-4cc0-b363-0da09af67170', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the difference between Astro''s static build and SSR mode?', N'Middle', N'Static build generates all HTML files at compile time, resulting in ultra-fast, deployable assets. SSR mode generates HTML dynamically on every request, which is necessary for pages requiring real-time data or user-specific information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'587d9164-fd58-42f4-8972-0da0b0e1b188', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the difference between CHAR and VARCHAR data types?', N'Intern', N'CHAR is a fixed-length data type that always reserves the specified amount of storage space regardless of the actual data size. VARCHAR is a variable-length data type that only uses the storage space required for the actual data entered. VARCHAR is generally more efficient for columns with varying string lengths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'307803e8-df9e-4601-ac14-0da3ffdd5df8', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What does the @Singleton annotation mean in Micronaut?', N'Intern', N'The @Singleton annotation indicates that only one instance of the annotated class will be created and shared across the entire application. This is the default scope for beans in Micronaut if no other scope is specified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
