INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1c0d824-3370-4ec6-ab2f-0da8fe440c49', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What happens if you update a signal outside of a component scope?', N'Intern', N'Since signals are independent of the component lifecycle in SolidJS, they will still trigger updates wherever they are being used. This makes signals very flexible for managing global state without needing complex context providers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd61b1d79-bb26-4ddc-b902-0dac615c4a21', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Discuss the risks of using Flask''s built-in development server in a production environment.', N'Senior', N'The built-in server is designed solely for development debugging and lacks the necessary robustness for production, such as multi-process management, request queuing, and protection against certain types of denial-of-service attacks. It is single-threaded and lacks the security hardening found in production-grade WSGI servers like Gunicorn or uWSGI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5408554c-9b17-4908-a143-0dae59f7a6f8', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the purpose of the ''Signature Model'' in Litestar''s internal design?', N'Senior', N'The Signature Model is used to parse and validate function signatures at runtime, which powers the framework''s automatic dependency injection and OpenAPI schema generation. This core component enables the framework to ''introspect'' handler requirements and resolve them dynamically, forming the backbone of its developer-friendly API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8aafb40f-ea4b-4b3e-abe4-0db4c023d253', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you explain a complex technical problem to a non-technical stakeholder?', N'Intern', N'I would use analogies to relate the problem to real-world concepts they are familiar with, while avoiding technical jargon. I would focus on the impact of the problem and the proposed solution, rather than the intricate internal mechanics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60030db7-0b68-4175-b208-0db4e905ffe6', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle JSON data?', N'Intern', N'Axum provides a built-in Json extractor that automatically deserializes incoming request bodies into Rust structs using the Serde library. Similarly, returning a Json type from a handler will automatically serialize the data into a JSON response with the correct content-type header.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23539173-fc3b-4101-a9d0-0dba0f97ea05', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why do you choose JSON as a data exchange format for most modern web applications?', N'Fresher', N'JSON is a lightweight, text-based format that is easy for humans to read and for machines to parse. It is language-agnostic and natively supported by almost all modern web browsers and backend technologies. This versatility makes it the standard choice for communication between frontend clients and backend APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67d32437-4342-4c5d-b753-0dbe199defe4', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle incoming HTTP requests?', N'Intern', N'Rocket uses routing to map incoming HTTP requests to specific handler functions. When a request arrives, the framework matches the URL path and HTTP method against defined routes and executes the associated function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'950af28a-a39f-4305-a69a-0dbecaa2ff1e', N'a2838158-7305-480a-b22b-4dc35776b400', N'When would you prefer a CRDT (Conflict-free Replicated Data Type) over a consensus-based approach for data replication?', N'Senior', N'CRDTs are preferred when high availability and low-latency local updates are critical, as they allow concurrent modifications that mathematically guarantee convergence without requiring global consensus. Consensus algorithms are better suited for scenarios where strict linearizability and strong consistency are non-negotiable requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee9b9f55-1435-4979-aa1f-0dc238214753', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the benefit of type hinting in FastAPI?', N'Junior', N'Type hinting allows FastAPI to perform automatic data validation, serialization, and documentation generation. It also helps developers by providing better IDE support, such as autocompletion and early error detection during development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a3ff6c3-1af7-4c1e-924b-0dcb5cbf9d96', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What are the trade-offs of using Remix’s ''meta'' function for SEO compared to client-side meta tag management?', N'Senior', N'Remix''s meta function executes on the server, ensuring that search engines and social media scrapers receive fully rendered metadata on the initial request. Client-side management often fails to provide this data to bots that do not execute JavaScript, making Remix superior for SEO-critical pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'002fba59-aede-4e00-99bb-0dcb64f6c680', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'In a distributed system, what is the trade-off between strong consistency and high availability during a network partition?', N'Middle', N'According to the CAP theorem, you must choose either consistency or availability during a partition. Choosing consistency ensures all nodes return the same data but risks returning an error if the system cannot guarantee accuracy, while choosing availability ensures the system remains operational but risks serving stale data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89e242a0-5037-427f-b939-0dcdc0eb239a', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the JVM handle hardware-specific optimizations without sacrificing portability?', N'Senior', N'The JVM achieves this through the JIT compiler, which generates machine code tailored to the specific processor architecture (e.g., AVX-512 instructions) during runtime. By abstracting the execution through bytecode, the JVM maintains write-once-run-anywhere compatibility while still leveraging hardware-level advancements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
