INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6cfbf15-64d9-43b7-aca3-0de3952f600e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is module scope in JavaScript?', N'Intern', N'Module scope is a feature introduced with ES6 (ES2015) modules that creates a scope specific to a module file, isolating variables and functions declared within it from the global scope and other modules. Variables and functions declared in a module are private by default and can only be accessed by other modules if they are explicitly exported. Key characteristics of module scope: 1. Variables declared in a module are scoped to that module only. 2. Each module has its own top-level scope 3. Variables and functions need to be explicitly exported to be used in other modules 4. The global scope cannot access module variables unless they are explicitly exported and imported 5.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
