INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2e370d3-219d-4663-990e-0df0d2187f05', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to structure Redux top level directories?', N'Fresher', N'Most of the applications has several top-level directories as below: 1. Components: Used for _dumb_ components unaware of Redux. 2. Containers: Used for _smart_ components connected to Redux. 3. Actions: Used for all action creators, where file names correspond to part of the app. 4. Reducers: Used for all reducers, where files name correspond to state key. 5. Store: Used for store initialization. This structure works well for small and medium size apps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
