INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ab2ce6a-cc18-47c3-85ad-0dfb664f06dc', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin improve upon Java for Android development?', N'Fresher', N'Kotlin, a statically-typed language, provides several benefits over Java in the context of Android development. Improved Developer Experience - Intuitive Syntax: Kotlin reduces boilerplate code, leading to more elegant, succinct, and readable codebases. - Extension Functions: This language feature allows developers to extend specific types with new functionalities. Enhanced Productivity - Null Safety: The type system in Kotlin differentiates between nullable and non-nullable references, effectively reducing NullPointerException occurrences. - Smart Casting: The language''s type inference allows automatic casting of types wherever possible, thereby eliminating the need for explicit casting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
