INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e48a995-31ee-4520-9e52-0e22c4e3a1ca', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does React handle event delegation internally?', N'Senior', N'React implements a synthetic event system that uses event delegation by attaching a single event listener to the root container rather than individual DOM nodes. This reduces memory footprint and ensures cross-browser consistency by normalizing event objects across different environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2aa565e-4819-4aac-bb81-0e2343677cdc', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you handle a request for a new feature that you believe will negatively impact performance?', N'Junior', N'Communicate your concerns clearly to the stakeholder by explaining the potential performance trade-offs. Suggest alternative approaches or optimizations that could achieve the desired goal without sacrificing system stability or speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e260097-01ac-462e-96d3-0e23cdce1918', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the benefit of using an API Gateway for scaling?', N'Middle', N'An API Gateway centralizes common tasks like authentication, rate limiting, and request routing. By offloading these responsibilities from individual microservices, it allows them to focus on business logic and scale more effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b00ebcd-80cc-4584-8975-0e25c7604a2f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the Dart Virtual Machine (Dart VM)?', N'Intern', N'The Dart VM is the runtime environment that executes Dart code. It provides Just-In-Time (JIT) compilation during development for fast iteration and Ahead-Of-Time (AOT) compilation for production to ensure high performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23f909ff-05fc-4fca-954f-0e25dcd60435', N'4c000000-0000-0000-0000-000000000005', N'What is the role of a message queue in system design?', N'Middle', N'A message queue enables asynchronous communication between services, decoupling the sender from the receiver. It helps in smoothing out traffic spikes and ensures that tasks are processed reliably even if the consumer is temporarily down.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11219b33-f07f-4594-bd5d-0e280992d105', N'075b8862-431c-4678-9767-f55359758a4a', N'What is Dev Tools and its purpose?', N'Intern', N'DevTools is a browser extension allowing you to inspect and debug your Vue applications in a more user-friendly interface. You can find the below extensions for different browsers or environments, 1. Chrome Extension 2. Firefox Addon 3. Standalone Electron app (works with any environment) The DevTools plugins can be used as shown in the below snapshot, Note: 1. If the page uses a production/minified build of Vue.js, devtools inspection is disabled by default so the Vue pane won''t show up. 2. To make it work for pages opened via file:// protocol, you need to check "Allow access to file URLs" for this extension in Chrome''s extension management panel.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d8577ef-e1b4-40dd-b66a-0e2ab2baa878', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the browser handle the cascade and specificity conflicts when applying styles from multiple sources?', N'Senior', N'The browser resolves conflicts by calculating specificity weights, origin of the style, and the order of appearance. When specificity is equal, the last rule defined in the source order takes precedence, ensuring a deterministic outcome even when styles are injected or modified dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19af171a-6cd5-4ef4-9990-0e2b80a59e0b', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Explain the concept of nesting in Sass.', N'Fresher', N'Nesting allows you to write CSS selectors in a way that mirrors the hierarchy of your HTML document. This makes the code easier to read and reduces the need to repeat parent selectors when styling child elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e267589d-c142-456c-b228-0e2cc100bcf6', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle feedback that suggests your solution is not optimal?', N'Fresher', N'I view feedback as an opportunity to learn and improve my skills rather than a critique of my ability. I ask for specific details on why the solution was not optimal so I can apply that knowledge to future tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d0566d8-cf51-415a-9a42-0e315b76436a', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between strong, weak, and unowned references in memory management?', N'Junior', N'A strong reference increases the reference count of an object, keeping it in memory. A weak reference does not increase the reference count and automatically becomes nil when the object is deallocated, while an unowned reference assumes the object will always exist and does not become nil.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b52c60a-c4be-48fd-be00-0e31994424df', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are the performance implications of boxing and unboxing value types?', N'Senior', N'Boxing requires a heap allocation and a metadata-rich object wrapper, which increases pressure on the garbage collector. Excessive boxing leads to higher memory fragmentation and cache misses, significantly degrading performance in tight loops or high-frequency data processing pipelines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16329d9f-dcb1-4e12-96a3-0e37330ae65b', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is cache eviction in Redis?', N'Intern', N'Cache eviction is the process of removing old or less important data from memory when the allocated space is full. Redis uses various policies, such as Least Recently Used, to decide which data to delete to make room for new entries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5067146e-a70a-49af-9916-0e39e1448e3d', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does an actor communicate its result back to the sender?', N'Junior', N'An actor communicates results back using a Request-Response pattern with a Responder. When a message is sent, the sender receives a future that resolves to the result once the actor processes the message.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92cf1e63-7774-45af-a34f-0e3c7ea15621', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the difference between Redis and a relational database like MySQL?', N'Fresher', N'MySQL stores data on disk and uses SQL for complex joins and relationships. Redis stores data in RAM, focuses on simplicity and speed, and does not support complex table joins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed93c1b1-0728-408b-ad3e-0e403ab515b0', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the trade-off between testing coverage and release speed?', N'Intern', N'Higher test coverage reduces the risk of production bugs and maintenance costs but slows down the deployment pipeline. Engineers must determine the acceptable risk level based on the application''s criticality to decide the appropriate depth of testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50625e2d-9da5-4d8c-ae38-0e40ae45bf39', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R''s dynamic typing influence the design of high-performance packages?', N'Senior', N'Dynamic typing allows for extreme flexibility in data structures but forces the R interpreter to perform type checking at runtime, which is a major performance bottleneck. Developers of high-performance packages often mitigate this by offloading the heavy computational tasks to statically typed languages, ensuring that the bulk of processing occurs outside the reach of the dynamic type checker.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bc08f94-ad23-44c5-af32-0e425e767072', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the role of ''application.properties'' or ''application.yml''.', N'Middle', N'These files serve as the external configuration source for Spring Boot applications. They allow developers to override default configuration properties, define custom application-specific settings, and manage environment-specific variables without re-compiling the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'838f1e27-7b89-45fb-88c1-0e43743e9416', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What does it mean for a Svelte component to be ''compiled''?', N'Junior', N'Compiling means that Svelte analyzes your component files and generates a standalone JavaScript file that performs the required DOM updates. This results in smaller bundle sizes and faster performance since no framework runtime is shipped to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6d4ad70-7c8b-4161-a99a-0e441fff643b', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What happens if you use the jQuery library alongside another library that also uses the $ sign?', N'Fresher', N'If there is a conflict, you can use jQuery.noConflict() to release control of the dollar sign variable. This allows you to use a different alias for jQuery or return the dollar sign to the other library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'198dd397-f128-4fb2-b038-0e4534029b18', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What are the benefits of using the Redux DevTools extension?', N'Middle', N'Redux DevTools provides a visual interface to inspect every action dispatched and the resulting state changes. It allows developers to time-travel, replay actions, and persist state, which significantly simplifies debugging complex state logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69f38fcb-fb9f-441e-87f9-0e4543dcc7ac', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of a token in Cassandra?', N'Intern', N'A token is a numeric value assigned to a node that defines its range of responsibility in the data ring. It helps the partitioner determine which data belongs to which node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd377cf2f-23fe-42ca-afff-0e4591ebff34', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is Qwik often described as a ''Performance-first'' framework?', N'Intern', N'Qwik is called performance-first because every design decision is aimed at reducing load time and main-thread work. It prioritizes the end-user experience by ensuring the application feels instant, even on low-end hardware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af7fdba0-37fb-4f3e-8533-0e48ac7681c3', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Explain the concept of ''normalization'' in Redux state management and why it is critical for performance in large-scale applications.', N'Senior', N'Normalization involves structuring state as a flat database-like schema where entities are stored by ID rather than nesting objects. This prevents data duplication, ensures that updates to a single entity are reflected across the entire UI without deep traversal, and significantly improves selector performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8dd9b197-7d84-4f55-b2f2-0e4a230f0c52', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the Fastify Logger and why is it important?', N'Fresher', N'Fastify includes a built-in logger based on the Pino library, which is known for being extremely fast and low-overhead. It is important because it provides structured logging out of the box, which is essential for monitoring server activity and debugging issues in a production environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
