INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5420605-d141-4a65-9b2f-0e526686230b', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask handle routing?', N'Fresher', N'Flask uses decorators to map specific URLs to Python functions. When a user visits a URL, the framework executes the function associated with that route to generate the response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91c936e3-59d6-422b-a45d-0e5470a49bf8', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does ''Optimistic Locking'' use version columns?', N'Middle', N'Each row has a version column that increments with every update. Before committing, the transaction checks if the version it read is the same as the current version in the database; if it has changed, the transaction aborts, signaling that the data was modified by someone else.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94d27607-fae6-4be1-b555-0e55a8f4d714', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What are the challenges of implementing generics in Go, and how did the chosen implementation impact compilation?', N'Senior', N'Go implemented generics using a hybrid approach of dictionaries and monomorphization to balance binary size with execution speed. While this allows for type safety and code reuse, it increases compile times because the compiler must generate specialized code versions for different type instantiations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'718a5784-4692-43bc-b87e-0e5780ec61c8', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why is ''single source of truth'' important in Redux?', N'Junior', N'Having a single source of truth means the entire application state is stored in one object tree. This makes it much easier to debug, persist state for features like undo/redo, and ensure that different parts of the UI are always synchronized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99f57349-9659-4de7-b37e-0e59641938b4', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Why is it dangerous to ignore OutOfMemoryErrors in long-running Java services?', N'Senior', N'An OOM exception usually indicates a fundamental state of heap exhaustion or native memory corruption that renders the JVM''s internal state unreliable. Continued execution can lead to inconsistent application behavior, silent data corruption, or a cascading failure that prevents the system from performing an orderly shutdown or diagnostic dump.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5aa3562-7289-47ba-a796-0e5b8dc5796d', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the concept of type narrowing in TypeScript.', N'Middle', N'Type narrowing is the process of refining a broader type to a more specific type within a conditional block using type guards. This allows the compiler to safely treat a variable as a specific subtype based on runtime checks like typeof, instanceof, or custom type predicates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a8f68d7-18dd-40f6-b3fe-0e5f56f524b0', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why is the lack of ''Concurrent Mode'' in Preact considered a design choice rather than a limitation?', N'Senior', N'The exclusion of concurrent mode is a deliberate choice to maintain a tiny bundle size and high performance for standard use cases. By focusing on synchronous, reliable updates, Preact maintains predictable behavior that is easier to reason about, which is often preferred for performance-critical, non-complex UI architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
