INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2ebc0aa-7f4b-4cb4-9ec2-0e617b65169e', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are the main features of Scala that make it amenable for data science and machine learning tasks?', N'Senior', N'Scala has gained popularity in the data science and machine learning communities due to its unique blend of functional and object-oriented paradigms and its compatibility with Java. Here are the key features and tools that make Scala a strong choice for these domains: Key Features Immutability Many machine learning algorithms benefit from immutability, simplifying multi-threading and promoting safer, functional-style programming. Concurrency The combination of immutability and actors from tools such as Akka makes concurrent programming more approachable. Type System Scala''s strong type system aids in catching errors early in the development cycle. Its support for type inference reduces verbosity, improving code readability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e44860c-33ba-490b-aff4-0e637d1f6a1f', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the difference between RDB and AOF persistence?', N'Intern', N'RDB persistence captures the state of the data at specific intervals, creating a compact file. AOF persistence logs every single write operation performed by the server, offering better data safety but resulting in larger files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0a094b7-775d-442d-96f8-0e668cb91f9d', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What happens to data in Redis if the server restarts?', N'Fresher', N'By default, data stored in Redis is volatile because it resides in RAM. If the server restarts without persistence configured, all data will be lost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
