INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60e2116a-7872-4629-b01a-0e7d3e68d196', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When would you prefer optimistic locking over pessimistic locking for concurrent data access?', N'Middle', N'Optimistic locking is ideal for systems with low contention where conflicts are rare, as it maximizes throughput by not holding locks during data processing. Pessimistic locking is better for high-contention scenarios where the cost of rolling back a transaction is higher than the performance penalty of blocking other operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9615edc1-8d37-4ba4-bce1-0e7eff5f86bf', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When estimating the time required for a task, why do people often underestimate the duration?', N'Intern', N'This is often due to the ''planning fallacy,'' where individuals focus on the ideal scenario rather than accounting for potential interruptions, technical difficulties, or unforeseen complexities. People tend to be overly optimistic about their own productivity and often overlook the time required for administrative or communication overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
