INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26936ed5-3433-47e8-8fe8-0e8119649ea3', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Can you describe about componentDidCatch lifecycle method signature?', N'Middle', N'The componentDidCatch lifecycle method is invoked after an error has been thrown by a descendant component. The method receives two parameters, 1. error: - The error object which was thrown 2. info: - An object with a componentStack key contains the information about which component threw the error. The method structure would be as follows', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76aed053-7cc7-4a1b-9e1e-0e85be2b13bf', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a reference in C++?', N'Intern', N'A reference is an alias for an existing variable. Once a reference is initialized to a variable, it cannot be changed to refer to another variable and must be initialized upon declaration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8aca252-ba4b-4f5a-8ccc-0e8a6e15ea8f', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the ''virtual'' keyword differ from the ''abstract'' keyword in C# inheritance?', N'Middle', N'A virtual method provides a default implementation that derived classes can choose to override. An abstract method has no implementation in the base class and forces derived classes to provide their own specific implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c612bfa-ae18-4883-84dc-0e8b9ac27a39', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember handle ''Auto-tracking'' with nested objects and arrays?', N'Senior', N'Ember''s auto-tracking system is proxy-based, meaning it can detect changes to properties within nested objects or changes to array contents. However, deep mutations sometimes require specific patterns to ensure the tracking system registers the change, which is a key consideration when designing complex data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3ec5a3c-cfe0-4251-9434-0e8c39b38636', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the architectural purpose of an ''Idempotency Key'' in the context of API retries?', N'Senior', N'Idempotency keys ensure that multiple identical requests from a client do not cause duplicate side effects on the server during network failures. By capturing the key and the corresponding response, the server ensures that retries result in the same outcome as the first successful attempt without re-executing the business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a5be72f-7432-40a5-951d-0e8da6c48989', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Why is it important to use a secret key in Flask?', N'Intern', N'A secret key is used to cryptographically sign session cookies and other security-related tokens. Without a strong secret key, it would be easy for a malicious user to tamper with session data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd31ebd6a-71f2-4899-afdf-0e8eb20c4310', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you design a system to ensure data integrity during a partial network partition?', N'Senior', N'I would apply the CAP theorem, prioritizing consistency over availability if the data requires strict correctness, or availability over consistency if the user experience can tolerate stale data. I would use quorum-based writes to ensure that only a majority of nodes must agree, maintaining a level of consistency even if some nodes are unreachable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
