INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8442fe2e-6630-4a70-b37a-0e964821c6ec', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are asynchronous thunks', N'Intern', N'The asynchronous thunks are useful to make network requests. Let''s see an example of network requests, The getData function won''t be called immediately but it will be invoked only when the data is available from API endpoint. The setTimeout function is also used to make our code asynchronous. The best real time example is redux state management library which uses the asynchronous thunks to delay the actions to dispatch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3436d47c-8eaf-4a3d-b1b7-0e9bd3741b81', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does Vector Clocks address the challenge of causal ordering in distributed systems?', N'Senior', N'Vector clocks allow a system to detect conflicts and determine causal relationships between events without relying on synchronized physical clocks. Each node maintains a counter, and by comparing vectors, the system can identify if one update happened before, after, or concurrently with another.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b963f88-682d-4cf9-ab8e-0e9d1b7648d8', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the asset pipeline in Rails?', N'Intern', N'The asset pipeline is a framework that manages and optimizes JavaScript, CSS, and image files. It handles tasks like minification, concatenation, and fingerprinting, which helps improve the performance of the application for the end-user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b8445f4-6d91-4c56-b280-0e9daf6e70e4', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Explain the impact of having too many shards in an Elasticsearch cluster.', N'Senior', N'Each shard consumes heap memory and file descriptors on the host node, and the master node must track the state of every shard. An excessive number of small shards leads to metadata overhead, increased memory pressure on the master, and inefficient query execution due to the overhead of managing many individual search requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6967f7d3-fa4d-4272-9588-0e9dbf5527d9', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the difference between a collection in MongoDB and a table in a relational database?', N'Junior', N'A collection is a grouping of MongoDB documents, which are similar to rows in a relational table but do not require a fixed schema. While tables enforce a strict structure with predefined columns for every row, collections allow documents to have different fields and data types, providing flexibility for storing unstructured or evolving data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fc42402-4b36-45db-81a1-0e9ef118afb5', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What are the challenges of performing ''joins'' in a sharded database environment?', N'Senior', N'Joins across shards are expensive because they require the application layer or a proxy to fetch data from multiple nodes and perform the merge in memory. This is typically avoided by denormalizing data into a single shard or using a global secondary index to maintain co-location of related records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2862176b-17a0-453f-b513-0ea00de8b134', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What are the limitations of Alpine.js regarding server-side rendering (SSR) hydration?', N'Senior', N'Unlike frameworks like React, which perform complex hydration to preserve server-rendered state, Alpine.js simply attaches itself to the existing DOM. This makes it incredibly fast but requires careful planning to ensure the state defined in Alpine matches the state rendered by the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35e0e5eb-27ec-4825-9b6e-0ea073813fc6', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a primary key and a unique constraint?', N'Intern', N'Both ensure uniqueness, but a primary key cannot contain NULL values and each table can have only one. A unique constraint can allow NULL values and a table can have multiple unique constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
