INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8f4ee5f-f945-4f11-9841-0ea4d22eb091', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut''s ahead-of-time (AOT) compilation strategy differ from traditional runtime reflection-based frameworks?', N'Senior', N'Micronaut moves dependency injection and proxy generation to the compile phase using annotation processors. This eliminates the need for runtime reflection, significantly reducing startup time and memory footprint compared to frameworks that scan and configure components at initialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
