INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24b0d7d3-af9d-440a-920b-0eb268a0a695', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Can you use FastAPI for both synchronous and asynchronous databases?', N'Junior', N'Yes, but you must be careful. If you use a synchronous database driver, you should define your path operations with ''def'' rather than ''async def'' so they run in a separate thread and do not block the event loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0eeaf51-7acd-41d2-90af-0eb29047e4e1', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the significance of the restrict qualifier in C?', N'Middle', N'The restrict qualifier is a promise to the compiler that a pointer is the only way to access the object it points to within its scope. This information allows the compiler to perform more aggressive optimizations, such as better register allocation and instruction scheduling, because it does not need to worry about memory aliasing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'678de749-f49b-4da2-9bc7-0eb35b053048', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is shadowing in Rust and give an example of how it''s used?', N'Intern', N'Shadowing, unique to Rust, allows you to redefine variables. This can be useful to update mutability characteristics and change the variable''s type. Key Features - Mutable Reassignment: Shadowed variables can assign a new value even if the original was mut. - Flexibility with Types: You can change a variable''s type through shadowing. Code Example: Rust''s "Shadowing" Here is the Rust code: Shadowing vs. Mutability Types of Variables - Immutable: Unmodifiable after the first assignment. - Mutable: Indicated by the mut keyword and allows reassignments. Their type and mutability status cannot be changed. Variables defined through shadowing appear as though they''re being reassigned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f70a647-9579-44bc-a21f-0eb490462db3', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Describe the mechanics of the Go garbage collector and its impact on application latency.', N'Senior', N'Go uses a non-generational, concurrent mark-and-sweep garbage collector designed for low latency. It uses a tri-color marking algorithm that runs concurrently with the application, minimizing stop-the-world pauses by utilizing write barriers. While this significantly reduces latency, it can increase CPU overhead as the collector must compete with the application for processing cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63641bcb-530d-4fe3-ac2c-0eb49a9b08cc', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why does Axum utilize procedural macros for route definition?', N'Senior', N'Procedural macros allow Axum to perform complex compile-time checks on handler arguments, ensuring they implement the required traits. This reduces the runtime overhead of reflection or dynamic dispatch, resulting in faster request routing and better performance compared to frameworks that rely heavily on runtime introspection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bc22b8b-5220-451b-b9d6-0eb6a78f0796', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do you access route parameters in SvelteKit?', N'Fresher', N'Route parameters are accessed via the ''params'' object provided in the load function. These parameters correspond to folders named with square brackets, such as [id] in the route path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64d97a99-6258-4767-8892-0ebb30a2fefa', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are Rails environments?', N'Intern', N'Rails environments, such as development, test, and production, allow you to configure the application behavior based on the context in which it is running. Each environment has its own settings, such as database connections and logging levels, to suit different stages of the development lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1375c7dc-9c2a-4c9a-a5d3-0ebc4af15990', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the purpose of the Dependency Inversion Principle (DIP) in NestJS?', N'Fresher', N'The Dependency Inversion Principle (DIP) is one of the five principles of SOLID, an acronym. The principle states that: > In the context of NestJS, or any other framework that supports dependency injection, the purpose of DIP is to reduce the coupling between modules, making the system more flexible, easier to test, and easier to maintain. By depending on abstractions, not on concrete implementations, you can easily swap out modules without changing the high-level code. For example, you might have a service that depends on a repository. If you code to an interface, you can easily change the repository (e.g., from an in-memory repository to a database repository) without changing the service code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6235a525-88f7-43a2-b4fe-0ebd1f6acfef', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar manage the lifecycle of database connections?', N'Middle', N'Litestar uses startup and shutdown events to manage connection pools, ensuring they are initialized when the server starts and gracefully closed when it stops. This prevents connection leaks and ensures that the application is fully prepared before accepting traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92cb463f-1cd4-4b87-8c67-0ec1339134e3', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the primary architectural advantage of using Fastify for a backend application?', N'Intern', N'Fastify is designed from the ground up to be highly performant and low-overhead, focusing on minimizing the processing time of each request. It achieves this by using a highly optimized internal routing system and a plugin-based architecture that ensures the framework remains lightweight and fast. This makes it an ideal choice for building scalable network applications that need to handle a high volume of requests efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8619ddf6-a499-4aa8-bd77-0ec231f870f0', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you design a database indexing strategy to support complex query patterns without sacrificing write performance?', N'Senior', N'I would start by analyzing query execution plans to identify bottlenecks and apply selective indexing on frequently filtered or joined columns. I would avoid over-indexing, as it increases write overhead and storage costs, and consider covered queries to minimize disk I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cdf4038-dfdf-4834-b8d6-0ec2412a631a', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does the ''KeyPath'' implementation in Swift provide type safety compared to string-based selectors?', N'Senior', N'KeyPaths are statically typed structures that provide a path to a property, allowing the compiler to verify existence and type compatibility at compile-time. Unlike string-based selectors, which are evaluated at runtime and prone to breakage, KeyPaths ensure that property access is verified before the application executes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b0d1c16-fcd8-4520-abc6-0ec290e75f83', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the architectural implications of choosing a Document store versus a Wide-Column store for time-series data?', N'Senior', N'Document stores offer flexibility for varied schemas but can suffer from write amplification due to indexing overhead on every field. Wide-column stores like Cassandra are optimized for high-velocity ingestion and efficient disk I/O through Log-Structured Merge-trees, making them superior for time-series where data is rarely updated and mostly appended.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76d02f77-9ddc-4368-8d2d-0ec5ab51e716', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you decide between building a feature from scratch and using an existing third-party library?', N'Junior', N'I weigh the maintenance burden and security risks of a third-party library against the time and effort required to build and maintain a custom solution. If the feature is not a core competency of the business, using a well-supported library is usually the better choice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28e74e24-90eb-449a-aa39-0ec68c6a47ec', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of type hinting in PHP?', N'Junior', N'Type hinting allows you to specify the expected data type for function parameters and return values. This helps catch bugs early by ensuring that the data passed to or returned from a function matches the required format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'643ea5e5-01eb-461c-9146-0ec83da890c8', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Explain the concept of ''Analyzers'' in Elasticsearch.', N'Middle', N'An analyzer is a combination of character filters, a tokenizer, and token filters that process text into searchable tokens. It defines how the input text is normalized, case-folded, stemmed, or filtered, directly impacting the precision and recall of full-text search results.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba3925de-c06e-4d63-be55-0ec8b098a2df', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the ''Manager'' in a Django model?', N'Junior', N'A Manager is the interface through which database query operations are provided to Django models. By default, every model has a manager called ''objects'' that provides methods like filter, get, and create.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3402110a-10b6-4cea-8d11-0ec959ef0f87', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is denormalization and when is it used?', N'Junior', N'Denormalization is the deliberate introduction of redundancy into a database design to improve read performance. It is used in scenarios where complex joins are too slow and the application prioritizes fast data retrieval over write speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08e7e45a-6d58-4a0b-959a-0ecadc7b1549', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the difference between a project and an app in Django?', N'Intern', N'A project is the overall collection of configuration and settings for a website, while an app is a specific module or feature within that project. An app is designed to be reusable and handle a specific set of functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1c3d50b-550a-4698-af1a-0ecc7cada57b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between == and === operators?', N'Fresher', N'JavaScript provides both strict (===, !==) and type-converting (==, !=) equality comparison. The strict operators takes type of variable in consideration, while non-strict operators make type correction/conversion based upon values of variables. The strict operators follow the below conditions for different types, 1. Two strings are strictly equal when they have the same sequence of characters, same length, and same characters in corresponding positions. 2. Two numbers are strictly equal when they are numerically equal. i.e, Having the same number value. There are two special cases in this, 1. NaN is not equal to anything, including NaN. 2. Positive and negative zeros are equal to one another. 3. Two Boolean operands are strictly equal if both are true or both are false. 4.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec8eb430-0635-41b7-8140-0ece956a5566', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain the concept of ''eventual consistency'' in the context of MongoDB read preferences.', N'Middle', N'Eventual consistency occurs when reading from secondary nodes in a replica set, as data replication from the primary is asynchronous. There is a small time window where a read might return stale data before the secondary catches up with the primary''s state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c919d006-a37e-412e-9b98-0ecf19d75b35', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why does Rust require the Send and Sync traits?', N'Middle', N'Send and Sync are marker traits that inform the compiler about thread safety. Send indicates that ownership of a type can be transferred to another thread, while Sync indicates that it is safe for multiple threads to access a reference to the type, preventing data races at compile-time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9af59e1a-418c-4520-aaa3-0ecfa16a75fa', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the purpose of the ''Responder'' trait?', N'Middle', N'The Responder trait allows any type to be converted into an HTTP response. It provides a flexible way to define how custom data structures should be serialized, which status codes they should return, and what headers should be set, making response handling highly modular.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e8efbb2-fdd3-4b08-8a26-0ed045838cfa', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the benefit of using a multi-level cache architecture?', N'Middle', N'A multi-level architecture, such as L1 (local memory) and L2 (distributed cache), provides a balance between extreme performance for the most critical data and shared access for the broader dataset. It reduces the network burden on the distributed cache while providing a fallback if local memory is exhausted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e092cde5-239c-4125-aca4-0ed47673a8b8', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When faced with a performance issue, how do you identify the bottleneck?', N'Junior', N'I would use monitoring and profiling tools to measure the execution time of different parts of the application. By analyzing the data, I can identify which specific function, query, or service is consuming the most resources and focus my optimization efforts there.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bf0dd4e-c853-4c5e-9887-0ed4f5577037', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between formal and actual arguments?', N'Fresher', N'Formal arguments are the parameters declared in the function definition, acting as placeholders for the data to be received. Actual arguments are the values or variables passed into the function when it is called.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'406481e8-4a76-4115-b01f-0ed72fe1c3f3', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s ''Property Wrappers'' feature facilitate clean architecture?', N'Senior', N'Property wrappers allow developers to encapsulate repetitive logic, such as thread synchronization, dependency injection, or data validation, into reusable components. This keeps the core business logic in classes and structs clean and focused, separating cross-cutting concerns from domain requirements. By abstracting this logic, it reduces boilerplate and enforces consistent behavior across properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eeb5f108-2c4d-4550-a45c-0ed79db7ac84', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is reflection in C#?', N'Fresher', N'Reflection is a mechanism that allows a program to inspect its own metadata, types, and members at runtime. It is often used to dynamically load assemblies or instantiate objects without knowing their types at compile-time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'272dd141-2685-4a53-b852-0edf9ecc076d', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does Durability guarantee in a transaction?', N'Fresher', N'Durability guarantees that once a transaction has been committed, it will remain saved even in the event of a system failure like a power loss or crash. The changes are permanently recorded in non-volatile memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed80ca0b-5ab4-4551-8061-0ee73e2e5874', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the mechanics of Python''s method resolution order (MRO) in the context of multiple inheritance.', N'Senior', N'Python uses the C3 Linearization algorithm to determine the order in which base classes are searched for methods. This algorithm ensures monotonicity and local precedence, preventing ambiguity by enforcing that subclasses always appear before their base classes in the lookup hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7df8a78b-5c9e-475b-80e3-0eebc1e4c6f0', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the difference between a local and a distributed transaction?', N'Intern', N'A local transaction involves only one database system. A distributed transaction involves two or more distinct database systems and requires complex coordination to ensure that all participating databases commit or roll back together.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'970db8c7-38a9-4cba-b4ad-0eec6e6d89cd', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How would you handle a situation where a service is consuming too much memory due to a memory leak that is difficult to reproduce?', N'Senior', N'I would capture heap dumps from the affected instances in production to perform offline analysis of object retention. Simultaneously, I would implement aggressive automated restart policies for affected pods to maintain availability while the team investigates the root cause.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6db2858-6b27-4bb9-a6aa-0eec94cdc7a6', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How to improve the page load?', N'Fresher', N'Here are the key techniques to improve page load performance: Reduce HTTP Requests - Combine JS files into one, CSS files into one - Use CSS sprites to merge multiple images into a single file - Remove duplicate scripts Assets & Delivery - Use a CDN — serves content from servers geographically closer to users - Gzip compression — reduces HTTP response size by ~70% - Minify JavaScript and CSS - Make JS and CSS external so browsers can cache them Script & Style Placement - Put stylesheets in — enables progressive rendering - Put tags at the bottom of , or use async/defer Caching - Set Expires / Cache-Control headers on static assets - Use localStorage to cache data client-side - Configure ETags - Use cache busting (script.js?v=2) when assets change Images - Compress and optimize images - Don...', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01d83f80-fb70-42ab-be7f-0eed167a493f', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the benefit of context-aware logging in Fastify?', N'Middle', N'Fastify attaches a unique request ID to the logger instance for every request. This allows developers to trace logs associated with a specific user interaction across multiple asynchronous operations, which is essential for debugging in distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8497ec3-e775-4c2e-a1c4-0eed7a25fc2a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What steps do you take when you encounter a problem you cannot solve on your own?', N'Junior', N'First, document what you have already tried and the specific errors you encountered. Then, perform a targeted search in internal documentation or reliable external resources, and if still stuck, ask a senior teammate for guidance, providing them with your summary of the issue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'411ba5dd-31d3-4207-9b7c-0eeebea39501', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the concept of ''monkey patching'' and its impact on large-scale system stability.', N'Senior', N'Monkey patching involves modifying the behavior of modules or classes at runtime by overwriting their attributes. While powerful for testing or hot-fixing, it obscures the program''s control flow and creates hidden dependencies that make debugging and maintenance significantly more difficult.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'287b3804-2704-4ffe-8687-0ef34359be41', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When designing an API, how do you decide between REST and gRPC?', N'Senior', N'I choose REST for public-facing APIs where discoverability, caching, and ecosystem interoperability are prioritized. I opt for gRPC in internal service-to-service communication where low-latency, strongly typed contracts, and efficient binary serialization are required for high-throughput performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba0a5622-7f3a-49a8-8a31-0ef4c9c65a8a', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Security''s DelegatingFilterProxy integrate with the standard Servlet Filter chain?', N'Senior', N'DelegatingFilterProxy acts as a bridge between the Servlet container and the Spring ApplicationContext. It intercepts incoming requests and delegates the filtering logic to a bean managed by Spring, allowing security rules to leverage the full power of Spring''s dependency injection and bean lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c829842a-d0ff-4cd5-9efd-0ef57db7991c', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django''s cache framework handle cache stampedes?', N'Senior', N'Django''s default caching does not inherently prevent stampedes, where multiple concurrent requests attempt to regenerate an expired cache key simultaneously. To handle this, developers must implement locking mechanisms, such as distributed locks using Redis, or use probabilistic early recomputation to refresh data before it expires.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2725c4c8-73ea-49ee-aa61-0ef5f2b308d9', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What are the benefits of Fastify''s automatic response serialization?', N'Fresher', N'Fastify can automatically serialize response objects into JSON based on a provided schema. This is much faster than standard JSON stringification because it uses a pre-compiled function that handles data structures efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c3c445f-b097-4083-af7c-0ef6ee78775c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you prevent promises swallowing errors', N'Fresher', N'While using asynchronous code, JavaScript’s ES6 promises can make your life a lot easier without having callback pyramids and error handling on every second line. But Promises have some pitfalls and the biggest one is swallowing errors by default. Let''s say you expect to print an error to the console for all the below cases, But there are many modern JavaScript environments that won''t print any errors. You can fix this problem in different ways, 1. Add catch block at the end of each chain: You can add catch block to the end of each of your promise chains But it is quite difficult to type for each promise chain and verbose too. 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2aefedb9-e627-43e3-94ff-0ef70440ae6c', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What does the ''out'' keyword do in method parameters?', N'Intern', N'The out keyword is used to pass arguments to a method by reference, requiring the method to assign a value to the parameter before it returns. It is commonly used when a method needs to return multiple values to the caller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bbb65be-9747-45c8-97f4-0ef8bef192bc', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Explain the architectural implications of Preact''s approach to event delegation compared to modern React.', N'Senior', N'Preact attaches event listeners directly to the document object to manage bubbling, which minimizes the number of listeners and memory usage. While effective for performance, this can cause conflicts in complex applications where global event handlers might interfere with third-party libraries or shadow DOM implementations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4998c55f-43e1-4d67-a65d-0efaad4056f9', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide the granularity of your logging strategy?', N'Middle', N'I log enough detail to trace requests across services and identify root causes during production outages, while avoiding PII and excessive volume that increases storage costs. I use structured logging to ensure that logs are machine-readable and easily searchable in aggregation tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e71b252-15b1-4f3a-9356-0efc94790cca', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the difference between a ''trait'' and an abstract class?', N'Intern', N'A trait is similar to an interface but can contain both method declarations and implementation code. Unlike abstract classes, a single class in Scala can extend multiple traits, which allows for a form of multiple inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f565cb4-3fa6-4df1-a383-0eff42d01a1f', N'954a0331-deff-4399-b588-96f39fec001d', N'What is Angular and what are its key features?', N'Intern', N'Angular is a robust, structural, TypeScript-based open-source front-end web application platform. It is especially well-suited for creating Single Page Applications (SPAs) and maintains a rich ecosystem of libraries, extensions, and tools. Core Features - Modularity: Through NG Modules, different parts of an Angular application can be structured and managed as distinct and cohesive units. - Component-based Architecture: Angular is built around components, fostering a modular, reusable, and testable design. - Directives: These markers on a DOM element instruct Angular to attach a particular kind of behavior to that element or even transform the element and its children.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55049c93-03d2-4e52-870d-0effb8ddb140', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the difference between an ''onResponse'' and ''onSend'' hook?', N'Fresher', N'The onSend hook runs when a payload is about to be sent to the client, allowing for response manipulation. The onResponse hook runs after the response has been sent to the client and is typically used for logging or cleanup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e68e095-5f9c-4618-b7dd-0f05e65cbebf', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle multi-part form data differently from standard JSON?', N'Senior', N'Rocket treats multi-part data through specific guards that handle file uploads and stream processing. Unlike JSON, which is typically buffered and parsed entirely, multi-part guards can handle large streams of data efficiently, preventing memory exhaustion when dealing with large file uploads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'915e6510-2014-4aa4-ba2b-0f0767557004', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are Svelte transitions and animations?', N'Junior', N'Transitions and animations are built-in features that allow you to easily add visual effects when elements are added to, removed from, or updated in the DOM. They are implemented using standard Svelte directives, which handle the underlying timing and CSS transitions automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90ad961d-4bf3-4bd2-a0e6-0f07ad727d95', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How do you handle authentication in an Astro SSR application to ensure it is secure?', N'Senior', N'Authentication is managed via server-side middleware that checks cookies or headers before the page is rendered. Because the verification occurs on the server, it prevents unauthorized access to the initial HTML, ensuring that sensitive data is only returned to the client if the session is authenticated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5078700f-3ce3-463e-bb1f-0f07e95cb413', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the role of the Database Access Layer in a service-oriented architecture?', N'Senior', N'The layer serves to decouple the business logic from the underlying storage technology and query dialects. It allows for database optimization, such as introducing read replicas or switching engines, without requiring changes to the application logic, provided the schema contracts remain stable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12a3cb97-d10c-446d-9fa5-0f0b80f43817', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the primary architectural benefit of separating the Rails API from the frontend application?', N'Senior', N'Separation of concerns allows the backend to be scaled and deployed independently as a stateless API service. This enables the team to utilize different deployment pipelines, independent technology stacks for the frontend, and improved cacheability via CDNs for the client-side assets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfbfb55a-f12d-4804-b951-0f0c71c39c8b', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel''s Eloquent ORM handle the N+1 query problem?', N'Middle', N'The N+1 problem occurs when an application executes one query to fetch parent records and then individual queries for each child record. Laravel solves this using ''eager loading'' via the with method, which fetches all related data in a single additional query using an IN statement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eef4f83b-0cfc-405f-a770-0f0cdf1e6f61', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the ''sealed'' keyword?', N'Intern', N'The ''sealed'' keyword is used to prevent other classes from inheriting from a specific class or to prevent a method from being overridden. It is often used for security or to ensure the behavior of a specific class remains unchanged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9b5869c-658d-4a20-8e3f-0f0dc0bc584c', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is a fiber stack, and why is it important?', N'Intern', N'A fiber stack is the memory area allocated to store the local variables and execution state of a specific fiber. Because fibers are lightweight, these stacks are often much smaller than the default OS thread stack size, allowing for high memory efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1e4a0c4-32d0-42f2-a62c-0f1090619405', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why is it important to break a large project into smaller sub-tasks?', N'Intern', N'Smaller tasks are easier to estimate, track, and manage, which reduces the likelihood of overlooking hidden complexities. This approach provides clearer milestones, allowing for more frequent progress updates and earlier detection of potential delays.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ce09091-056b-47c8-b52d-0f116f3ce22e', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do generics help improve code reusability?', N'Junior', N'Generics allow you to create components or functions that work with a variety of types rather than a single one. By using a placeholder for the type, you can maintain strong type safety while ensuring the logic remains flexible enough to handle different data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fb53c51-c734-4739-a8d1-0f11f64bbabf', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the role of the Tokio runtime in an Actix-web application?', N'Junior', N'Tokio provides the underlying asynchronous runtime that Actix-web runs on. It manages the task scheduling, I/O polling, and timer functionality, which are necessary for handling network traffic in a non-blocking manner.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35f9f675-fe75-40d7-bf5e-0f1240999ea3', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the benefit of Qwik''s ''Progressive Hydration'' versus full hydration?', N'Middle', N'Qwik does not actually use progressive hydration; it uses resumability. Progressive hydration still hydrates components over time, which consumes main-thread resources, whereas Qwik''s resumability avoids the execution of framework logic entirely until the specific interaction occurs, resulting in much less main-thread activity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8ab5b21-3a5e-4b49-9a55-0f1240b3c57f', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the role of the Go scheduler and its M:N scheduling model.', N'Middle', N'The M:N model maps M goroutines onto N OS threads. The Go scheduler efficiently distributes goroutines across available processors, ensuring that when one goroutine blocks on I/O, others can continue running on the same thread, maximizing CPU utilization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad07ad62-cecf-4045-9342-0f17c0e87c6e', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel handle session management?', N'Fresher', N'Laravel provides a unified API for various session drivers, such as file, database, or redis. It allows the application to store information about a user across multiple requests, making it easy to handle things like user logins and shopping carts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
