INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7604d6fa-2186-49e2-8c6d-0f1e7c8c34b5', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the primary trade-off of using a shared-nothing architecture?', N'Middle', N'The shared-nothing architecture minimizes contention by ensuring each node operates independently with its own resources. While this significantly improves horizontal scalability, it introduces complexity in data consistency and synchronization across nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
