INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'028916a7-ff7e-4327-9c49-0f211de41e31', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the architectural trade-offs of using Django’s ORM versus raw SQL for complex analytical queries.', N'Senior', N'The ORM provides abstraction, security, and developer productivity, but can generate inefficient queries for highly complex joins or window functions. Raw SQL offers maximum performance and control over execution plans but sacrifices portability and increases the risk of injection vulnerabilities if not handled with parameterized queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
