INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18b66bce-3e3d-4b03-99b2-0f2a184a6121', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between ''lazy'' and ''eager'' loading in ActiveRecord and how do you influence the choice?', N'Senior', N'Lazy loading fetches associated records only when accessed, which is the default but causes N+1 queries. Eager loading fetches associations upfront using includes, preload, or eager_load to optimize performance by reducing the total number of database queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
