INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd528a10d-a223-4ee5-8861-0f2be5e12b05', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'When should you use an Alpine plugin instead of writing custom logic in the component?', N'Middle', N'Plugins are best for reusable functionality that needs to be accessed across multiple components or projects. If the logic is specific to one component''s unique behavior, it is better to keep it encapsulated within that component to avoid unnecessary global overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
