INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e147cf8-9f96-4fa0-bf1f-0f2fe6d76a6f', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why is it generally discouraged to use the built-in ''express.static'' middleware for high-traffic applications?', N'Middle', N'While convenient, the built-in static middleware is less efficient at handling large volumes of concurrent requests and lacks advanced features like automatic compression or fine-tuned cache-control headers. Offloading static file delivery to Nginx or a CDN is more performant as it avoids blocking the Node.js event loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7518390-d609-401a-8821-0f338fafa5a3', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the concept of Structural Typing in TypeScript.', N'Junior', N'TypeScript uses a structural type system, meaning compatibility is determined by the members of the type rather than explicit declarations. If two objects have the same structure or if one is a subset of the other, they are considered compatible regardless of their names.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2ba2217-af8a-4529-a314-0f33df3af5e7', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are higher ordered functions?', N'Intern', N'You have two choices: you can use nested scopes or you can use callable objects. For example, suppose you wanted to define linear(a,b) which returns a function f(x) that computes the value a*x+b. Using nested scopes: Or using a callable object: In both cases: taxes = linear(0.3,2) gives a callable object where taxes(10e6) == 0.3 * 10e6 + 2. The callable object approach has the disadvantage that it is a bit slower and results in slightly longer code. However, note that a collection of callables can share their signature via inheritance: Object can encapsulate state for several methods: Here inc(), dec() and reset() act like functions which share the same counting variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11b2d2df-f7df-44f7-a253-0f345b3fb2b5', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle error boundaries?', N'Middle', N'Remix provides route-level error boundaries that catch errors during rendering or data fetching. This prevents the entire application from crashing and allows you to display a specific error UI for a sub-section of the page while keeping the rest of the application functional.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c26f575-826a-43f8-bdc4-0f346266e5d1', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is a reducer in Redux and what role does it play?', N'Intern', N'A reducer in Redux is a pure function responsible for managing specific parts of your application state. It captures state changes and computes the new state based on those changes. Key Characteristics - Predictability: Given the same input, a reducer will always produce the same output, making state management more predictable. - Immutability: Reducers handle state immutably, ensuring that every state transition results in a new state object. This helps to avoid side effects and enhances the efficiency of UI and state management libraries like React and their change detection algorithms. - Single Responsibility: Each reducer is geared towards managing a particular slice of application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86930f47-1bdc-40ff-ac0f-0f3acbbd467e', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you approach a situation where a team member disagrees with your technical approach?', N'Fresher', N'I would ask them to explain their reasoning and compare both approaches based on criteria like simplicity, maintainability, and efficiency. If we cannot reach a consensus, I would present both options to a senior lead to make an informed decision.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d885695-6874-4aaf-9c3a-0f3ec2a0a7ee', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the purpose of the ''Layer'' concept in Axum?', N'Junior', N'Layers are the mechanism used to apply middleware to a router or a specific route. They allow you to wrap the request-response lifecycle with additional functionality like timeouts or authentication checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
