INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52ead0b8-fdeb-4ea0-90fe-0f4056cc72df', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What makes FastAPI ''fast'' compared to other Python frameworks?', N'Fresher', N'FastAPI is built on Starlette for web parts and Pydantic for data parts, making it one of the fastest Python frameworks available. Its speed is largely due to its native support for asynchronous programming using async and await, which allows it to handle many concurrent connections efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7db6a054-d538-4f18-b4dc-0f427ad7469c', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Why are case classes preferred over regular classes for data modeling in Scala?', N'Middle', N'Case classes automatically generate boilerplate code such as accessors, equality methods, hash codes, and a companion object with factory methods. They also support pattern matching out of the box, making them ideal for immutable data structures and functional programming patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e9453f0-f244-4ce0-8336-0f44bf555c5e', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach learning a new technology quickly for a project?', N'Fresher', N'I would start by understanding the fundamental concepts and the ''why'' behind the technology, then look for a ''hello world'' style tutorial to get hands-on experience. I would focus on core features first and consult documentation as I encounter specific requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3deba95c-f1db-4df1-91d3-0f4609b920fc', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is an index in a NoSQL database?', N'Intern', N'An index is a special data structure that improves the speed of data retrieval operations on a database table or collection. Without an index, the database would have to scan every single document to find a match, which is inefficient for large datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
