INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5712eed9-2a02-4385-a269-0f50b2fc9111', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the role of the ''pubspec.yaml'' file in a Dart project?', N'Junior', N'The pubspec.yaml file is the project configuration file that manages dependencies, assets, and metadata. It tells the package manager which external libraries are needed for the project and specifies the version constraints for those packages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'698b0633-9b18-4bc0-bee6-0f5102da74e0', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket''s type-safe request routing affect application security compared to runtime-based routers?', N'Senior', N'Rocket''s routing uses procedural macros to validate request parameters at compile-time, ensuring that types match before the handler is ever invoked. This eliminates entire classes of runtime injection and parsing vulnerabilities by enforcing strict schema adherence during the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'406d6755-8ad2-492f-bb99-0f51e6da1869', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is meant by ''Islands Architecture'' in Astro?', N'Fresher', N'Islands architecture refers to the strategy of rendering static HTML on the server and injecting interactive components only where needed. These individual interactive parts are known as islands, which operate independently within the static page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc5cda76-be9c-4cd6-9bba-0f5451711f9f', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle URL parameter extraction, and why is this useful for RESTful API design?', N'Middle', N'Chi uses a pattern matching system that allows developers to define dynamic segments in route paths. This is essential for RESTful design because it enables clean, resource-oriented URI structures where parameters like unique identifiers are directly accessible via the request context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a8cdd43-d796-4609-bc44-0f54cb6be9d2', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between a static method and a class method?', N'Middle', N'A class method receives the class itself as the first argument, allowing it to modify class-level state or act as an alternative constructor. A static method does not receive any implicit first argument, functioning as a regular function that is simply scoped to the class namespace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20dcc071-67c0-4eb6-b191-0f5ceadd984a', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a race condition that only occurs in production under high load?', N'Middle', N'I would look for shared mutable state in the code that is accessed concurrently without proper synchronization. Since it is hard to reproduce, I would increase logging for critical sections or use observability tools to track state changes in real-time. Then, I would design a synthetic load test that simulates the high concurrency to confirm the hypothesis before applying thread safety measures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af86154b-7290-4ad5-b05d-0f63ba0dc8d8', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Why is it important to use connection pooling in Rails, and what happens when the pool size is misconfigured?', N'Senior', N'Connection pooling allows the application to reuse database connections, significantly reducing the overhead of establishing new TCP handshakes for every request. If the pool is too small, requests will time out waiting for an available connection; if too large, the database may hit its maximum connection limit and start rejecting queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7404b75-1366-4397-b7fe-0f676e72e718', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is lazy evaluation in R?', N'Junior', N'Lazy evaluation means that function arguments are only evaluated at the moment they are actually used inside the function. If an argument is never used during the function call, it is never evaluated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aba04f26-0949-499e-a931-0f69b3290b47', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is a ''Router'' in Chi?', N'Fresher', N'A Router in Chi is an interface that defines the methods used to register routes and middleware. Because the Mux struct implements this interface, it can be passed around as a standard handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a43f070e-f15a-4c88-ba2a-0f6a32b82b40', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Why is it important to use ''async'' database drivers with FastAPI?', N'Senior', N'If a blocking synchronous database driver is used inside an ''async def'' route, it blocks the entire event loop, preventing the server from handling any other concurrent requests. Using async drivers ensures the event loop remains free to process other I/O tasks while waiting for the database response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2f37702-c0d6-4e0c-bfe5-0f6a5a486551', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the difference between filtering and querying?', N'Junior', N'Querying calculates a relevance score to rank results, whereas filtering only checks for a binary yes/no match. Filters are generally faster and can be cached, making them ideal for narrowing down search results without affecting the ranking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1aa1b62d-828c-41d3-a0ff-0f6bfa7890a1', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When debugging high CPU usage, what do you look for first?', N'Middle', N'I first determine if the high CPU is caused by a spike in request volume or by inefficient code execution, such as infinite loops or intensive data processing. I use thread dumps to see if specific threads are stuck in hot loops or blocked on CPU-bound tasks. If the CPU is not linked to traffic, I investigate background tasks, cron jobs, or potential resource leaks in the application runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6dde522a-49b6-4bcd-a865-0f6e5cdf9eb6', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Where does PHP code execute?', N'Intern', N'PHP code executes on the server side. The server processes the script and sends only the resulting HTML output to the client''s browser, meaning the original source code is never visible to the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffc16b75-a13e-4337-a183-0f6f98fdd9b8', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How do you manage packages in a Node.js project?', N'Fresher', N'Node.js utilizes npm (Node Package Manager) or yarn for package management. npm vs. Yarn Both tools create a node_modules folder, but they have subtle differences: - Yarn''s yarn.lock provides deterministic package versions, while npm uses package-lock.json. - npm uses npm install while Yarn uses yarn add to install a package. Yarn also has advanced features like parallel package installations and a lockfile ensuring consistent installations across machines. Core npm Commands - npm init: Initializes a new project and creates a package.json file. - npm install [package] (-D): Installs a package and updates the package.json file. The -D flag indicates a devDependency. - npm update [package]: Updates installed packages to their latest versions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91f238de-524f-4478-9a22-0f721fa51008', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is "key" prop and what is the benefit of using it in arrays of elements?', N'Intern', N'A key is a special attribute you should include when mapping over arrays to render data. _Key_ prop helps React identify which items have changed, are added, or are removed. Keys should be unique among its siblings. Most often we use ID from our data as _key_: When you don''t have stable IDs for rendered items, you may use the item _index_ as a _key_ as a last resort: Benefits of key: * Enables React to efficiently update and re-render components. * Prevents unnecessary re-renders by reusing components when possible. * Helps maintain internal state of list items correctly. Note: 1. Using _indexes_ for _keys_ is not recommended if the order of items may change. This can negatively impact performance and may cause issues with component state. 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0eceedf-c811-40dc-adf5-0f726b0f7cac', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What are the risks of using a poorly designed partition key?', N'Senior', N'A poor partition key, such as one with low cardinality, can lead to uneven data distribution, resulting in partition hotspots where a single node handles disproportionate traffic. This creates performance bottlenecks and potentially causes heap pressure or node crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6177f11f-233f-422d-a3a7-0f74f62551f1', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What does ''type erasure'' achieve in C++ and how is it implemented?', N'Senior', N'Type erasure hides the concrete type of an object while providing a common interface, allowing containers or functions to hold heterogeneous types without templates. It is typically implemented by wrapping an object in a class that holds a pointer to a base interface or a function pointer, achieving polymorphism without requiring a common inheritance hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e062aedd-c879-4bcc-bb7c-0f75d54928b3', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the advantage of using stateless services in a scalable architecture?', N'Middle', N'Stateless services do not store client session data locally, allowing any instance of the service to handle any request. This makes it trivial to scale horizontally by simply adding or removing instances behind a load balancer without worrying about session persistence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdcef5c0-60b5-4cb2-87df-0f774e3b2dc9', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide when to upgrade a major dependency or framework in a large project?', N'Middle', N'I evaluate the upgrade based on security vulnerabilities, performance improvements, and the effort required to manage breaking changes. I would perform a cost-benefit analysis and run the upgrade in a canary deployment to ensure that it does not introduce regressions or compatibility issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'856cfdb5-eba0-4b12-b7f0-0f792ecb31db', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What happens if multiple middleware are used in Chi?', N'Junior', N'When multiple middleware are used, they are executed in the order they were added to the router. This creates a chain where each middleware can perform logic before calling the next handler in the sequence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8fb239d-b297-4c83-92e3-0f7933e8a1a6', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What does ''Strict Typing'' refer to in the context of AdonisJS?', N'Intern', N'AdonisJS is built with TypeScript, which adds static type definitions to the code. This ensures that variable types and function arguments are checked at development time, which helps prevent bugs and improves code reliability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae566e44-1496-468b-b414-0f7996c0608e', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are the architectural implications of using Scala''s Actors (Akka) for distributed state management?', N'Senior', N'Actors provide a location-transparent, asynchronous model that inherently avoids shared mutable state, facilitating horizontal scalability. However, they introduce complexity regarding failure recovery, message serialization, and potential mailbox overflows, requiring careful design of supervision hierarchies to maintain system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61a5ae62-ba5b-479f-89f4-0f7b13241dc5', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the impact of primary key selection on performance?', N'Middle', N'Selecting an inappropriate primary key, such as a long string or a non-sequential value, can lead to index fragmentation and slower performance. Using an auto-incrementing integer or a compact GUID is generally preferred to keep index tree structures efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfab724e-30d2-494e-b408-0f7dc1b084dd', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a snapshot in Elasticsearch?', N'Junior', N'A snapshot is a backup of an entire cluster or specific indices, stored in a remote repository. It is a critical feature for disaster recovery and migrating data between different environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'945549c0-f779-41ad-9b4c-0f7e7af1c71e', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Can Qwik components be heavy and complex without hurting performance?', N'Middle', N'Yes, because of Qwik''s granular code splitting, the internal complexity of a component does not affect initial page load. Only the parts of the component that are interacted with are ever loaded into the browser memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e379e6d3-075f-4d39-838e-0f82397a915d', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is a ''session'' in a web application?', N'Intern', N'A session is a way to store data across multiple requests for a specific user. It is commonly used to keep a user logged in or to maintain temporary state, such as items in a shopping cart.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fcee831-b4d0-4f40-bc70-0f83d1943b65', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you verify the integrity of a system after a major deployment?', N'Middle', N'I use automated smoke tests to verify critical paths immediately after deployment. Additionally, I monitor error rates and latency metrics closely using canary releases, where the new version is exposed to a small subset of traffic before a full rollout.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'831bf9c2-425d-47c6-9f44-0f842c94825e', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is middleware in Fiber?', N'Intern', N'Middleware are functions that run during the request-response cycle before the final route handler. They can perform tasks like logging, authentication, or modifying headers, and they must call the next function to pass control to the subsequent handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c21f1e60-60f3-44b2-97d8-0f843c4defed', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the benefit of a schema-less design in NoSQL?', N'Junior', N'A schema-less design allows developers to store data without adhering to a rigid structure, providing the flexibility to add new fields as application requirements evolve. This is particularly useful for rapidly changing data models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49049ee4-c0d7-4f29-9d10-0f85966e1e91', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do you manage global state in a SvelteKit application without using external stores?', N'Middle', N'Global state can be managed using Svelte''s built-in writable stores defined in external files. Because these stores persist for the duration of the page lifecycle, they provide a reactive way to share data across different components and routes without needing complex context providers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'031a7065-040d-45e6-914b-0f85cb854fa8', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why might a query perform differently on a replica compared to the primary, despite having identical data and indexes?', N'Senior', N'Differences can arise from variations in statistics, session-level parameters, or the presence of conflicting vacuum processes. Additionally, if the replica is not perfectly synchronized or has different hardware configurations, query performance and plan selection may diverge.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6843872a-ca75-42ae-b029-0f8882d89a4a', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix prevent CSRF attacks?', N'Middle', N'Phoenix includes a built-in plug that verifies a CSRF token submitted with state-changing requests. This ensures that the request originated from the legitimate application and not a malicious third-party site.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fb0ba92-d86b-4a4f-9cb5-0f89ad79f58c', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How do you handle distributed transactions in a Spring Boot microservices environment where JTA is not viable?', N'Senior', N'In microservices, distributed transactions are typically managed using the Saga pattern, involving a sequence of local transactions coordinated via events or messages. This approach favors eventual consistency over the strong consistency provided by traditional JTA/XA transactions, which are generally avoided due to performance and scalability constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce40afb9-f9fa-49a0-a3e2-0f8a329a4a37', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the difference between ''let'', ''run'', ''apply'', and ''also''?', N'Junior', N'These are scope functions that execute a block of code within the context of an object. The main differences lie in whether they refer to the object as ''this'' or ''it'', and whether they return the original object or the result of the block.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6502cd31-15e1-495b-a02e-0f8d07a74752', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi''s routing logic handle trailing slashes and redirection?', N'Senior', N'Chi provides built-in configuration options to handle trailing slash redirects automatically, which is crucial for SEO and API consistency. This behavior can be toggled per router, giving developers control over whether to treat paths with and without slashes as distinct or identical resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fb89132-7880-4a30-9733-0f901659138c', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why are deadlocks common in lock-based concurrency control and how are they mitigated?', N'Senior', N'Deadlocks occur when two or more transactions hold locks that the others need, creating a circular dependency. Databases typically mitigate this by implementing a deadlock detection algorithm that kills one of the transactions or by using lock timeouts to force a release.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f020307c-d825-4431-9ac1-0f90a3a5863d', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift handle error handling?', N'Junior', N'Swift uses a ''do-catch'' pattern to handle errors that can be thrown by functions or methods. The function must be marked with ''throws'', and the caller must use ''try'' to invoke it and handle potential errors in a ''catch'' block.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'568942da-9528-40cc-80c3-0f945eb76b0e', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the performance implications of complex type transformations?', N'Middle', N'Extremely complex nested conditional or recursive types can increase the time it takes for the TypeScript compiler to perform type checking. Large-scale projects with heavy reliance on deep type manipulation may experience slower IDE responsiveness and longer build times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c84bf39-76aa-4e1c-8fa1-0f9518aaf6ce', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the architectural benefits of using Redis Client-side caching (Tracking)?', N'Senior', N'Client-side caching allows applications to store data in local memory, significantly reducing latency and server load. Redis tracks the keys requested by clients and sends invalidation messages when the data is modified, ensuring cache consistency without constant polling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cecb8cb6-7d7a-425d-8c92-0f9694257d1c', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Why might you choose a custom Exception Filter over the built-in global exception handler?', N'Senior', N'Custom exception filters allow for standardized, domain-specific error formatting and logging across the entire application. They are essential for ensuring that client-facing error responses remain consistent, even when dealing with varied third-party library errors or complex domain-specific exceptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'815b5f84-e5a0-4dc1-b1bf-0f972636f55f', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How do Middleware functions work in Next.js, and what are common use cases for them?', N'Middle', N'Middleware allows you to run code before a request is completed, enabling you to modify the response or rewrite the URL based on incoming request data. Common use cases include authentication checks, geo-based content targeting, and A/B testing implementations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83bb0b82-1021-46de-9d14-0f980b8994d7', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does React''s ''Suspense'' improve the UX of data-heavy applications?', N'Senior', N'Suspense allows components to defer rendering until their data or dependencies are ready, providing a declarative way to manage loading states. It enables streaming server-side rendering, where the server sends the shell of the page first and streams content as it becomes available, reducing Time To First Byte.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab9c88ae-5df9-4b0d-b7f9-0f9aa7e4e88c', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the difference between vertical and horizontal scaling in a database context?', N'Middle', N'Vertical scaling involves increasing the capacity of a single server, such as adding more CPU or RAM, while horizontal scaling involves adding more servers to a distributed system. Horizontal scaling is often preferred in modern cloud architectures for high availability and fault tolerance, though it introduces complexity in data consistency and partitioning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'499893b0-1834-4f1e-a7e0-0f9af90d14e4', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Describe the difference between ''Job'' queues and ''Active Job'' in Rails.', N'Middle', N'Active Job is an abstraction layer that provides a unified interface for various queuing backends like Sidekiq, Resque, or Delayed Job. It allows developers to write background tasks once and switch the underlying infrastructure provider without changing the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ee7d3fe-642c-4992-8cca-0f9c161d2dc7', N'a2838158-7305-480a-b22b-4dc35776b400', N'Describe the ''Circuit Breaker'' pattern and its operational benefits.', N'Senior', N'The circuit breaker detects failures in a remote service and stops sending requests to it once a threshold is reached, allowing the failing system time to recover. It improves system stability by failing fast instead of hanging threads, preventing resource exhaustion in the calling service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b33ee347-4210-477f-b887-0f9c41906de4', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle routing compared to other frameworks?', N'Junior', N'Fiber uses an optimized trie-based routing algorithm. This allows it to match incoming request paths to defined handlers extremely quickly, regardless of how many routes are registered in the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ff889f6-ee39-4055-9801-0f9d2cb10c1e', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What are the security implications of Echo''s default CORS middleware configuration?', N'Senior', N'The default configuration might be overly permissive for production. A senior architect must ensure that the CORS middleware is configured with strict origin whitelisting and proper credential handling to prevent cross-site request forgery and unauthorized data access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33257741-9dc6-4ccd-a97a-0f9e9e063241', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Why is garbage collection in R considered ''stop-the-world'' and how does it affect real-time applications?', N'Senior', N'R’s garbage collector uses a generational approach that periodically pauses execution to reclaim memory from unreachable objects. This latency-inducing behavior makes R unsuitable for hard real-time systems where consistent execution timing is required, as the frequency and duration of these pauses depend on the rate of memory allocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7584eea-1a25-4976-867f-0fa018cdb3cc', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is it important to use the correct format specifiers in printf?', N'Junior', N'Using the correct format specifier is critical because it tells the function how to interpret the underlying binary data in memory. If you use the wrong specifier, the function may attempt to read the wrong number of bytes or interpret the bits incorrectly. This leads to garbage output or, in some cases, program instability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30a38c9d-f095-49ff-8995-0fa57574bc35', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle CSS scoping?', N'Junior', N'Svelte automatically scopes CSS styles to the component where they are defined. It achieves this by generating unique class names for elements during the build process to ensure styles do not leak into other parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a13072f6-23ee-4fd6-ba70-0fa7ca8b1800', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle path parameters versus query parameters?', N'Junior', N'Path parameters are defined directly in the URL path string and are marked as required, while query parameters are appended after a question mark in the URL and are treated as optional unless a default value is omitted. FastAPI automatically detects these based on whether the parameter is included in the route path string.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c508df5-3a7d-4b7b-9301-0fa87f406911', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP''s dynamic typing system affect engine performance and memory overhead?', N'Senior', N'Every variable in PHP is stored in a complex structure called a ZVAL, which includes type information and reference counters. This dynamic flexibility requires higher memory overhead per variable compared to statically typed languages, where the compiler can optimize memory layout based on fixed types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
