INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'828b38b2-379d-4458-8158-0fb23c492ab8', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the primary advantage of Micronaut''s ''Introduction Advice'' mechanism?', N'Middle', N'Introduction Advice allows developers to define interfaces that the framework implements automatically at compile time. This is useful for features like declarative HTTP clients or data repositories, where the framework provides the implementation logic based on annotations without requiring runtime proxies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
