INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ffb9a54-81af-412b-b810-0fb333192123', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the architectural purpose of NestJS Guards, and how do they differ from Middleware?', N'Senior', N'Guards are designed specifically for authentication and authorization, having access to the execution context to make security decisions. Unlike middleware, which is unaware of the handler being executed, guards have full access to the target class and method metadata, allowing for granular, decorator-based access control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e160197b-01a7-4ecd-8e2b-0fb91e492b8d', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the role of the ''Catchers'' mechanism in Rocket?', N'Middle', N'Catchers are used to define custom error handling logic for specific HTTP status codes. They allow developers to provide consistent, meaningful error responses to clients when a request fails, such as returning a formatted JSON object instead of a default error page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d2d5f3c-1849-4d78-8d86-0fbda9c699a7', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the role of an ''Actor'' in the context of Actix?', N'Fresher', N'An actor is an entity that encapsulates state and logic, communicating exclusively via message passing. While Actix-web is now mostly focused on HTTP, the underlying Actor system can still be used for complex background tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ab79d18-1e0c-46c7-8c69-0fbeb1a20f9e', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Explain the concept of ''Optimistic Concurrency Control''.', N'Middle', N'Optimistic concurrency control assumes that multiple transactions can complete without interfering with each other. Instead of locking data, the system checks for conflicts only at the time of commit, rolling back the transaction if the data was modified by another process in the meantime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bba8679-5d14-4abf-a59b-0fc0651ac6ea', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik compare to static site generators regarding content delivery?', N'Middle', N'Qwik performs similarly to static site generators in terms of initial load speed but adds dynamic functionality without the need for a heavy runtime. While static generators deliver static HTML, Qwik delivers ''active'' HTML that can resume its full application capabilities the moment the user interacts with it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86f27d66-f65c-4258-8248-0fc23b725217', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does React''s fiber architecture improve rendering performance compared to the legacy stack reconciler?', N'Senior', N'The Fiber architecture enables incremental rendering by breaking the work into small units that can be paused, aborted, or prioritized. This prevents the main thread from being blocked during long reconciliation processes, significantly improving responsiveness in high-frequency update scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'837bee22-5217-4cc8-90c3-0fc34cd9b1ee', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the architectural impact of moving from a perimeter-based security model to a Zero Trust model?', N'Senior', N'Transitioning to Zero Trust requires shifting security focus from network location to identity and device posture, necessitating pervasive authentication and authorization at every service interaction. This architectural shift requires significant investment in identity providers, continuous monitoring, and micro-segmentation to ensure no traffic is implicitly trusted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6885e33-5790-4ac1-a6f6-0fc82638ff34', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS handle Dependency Injection?', N'Junior', N'NestJS uses an internal IoC container that manages the instantiation and lifecycle of classes decorated as injectable. When a class is declared as a provider, the framework automatically resolves its dependencies and injects them into the constructor, promoting loose coupling and easier testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92ec1fa5-6d1d-46b7-9e1e-0fc98341a902', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How can you implement circuit breakers in Micronaut?', N'Middle', N'Micronaut provides a built-in @CircuitBreaker annotation that can be applied to methods. It monitors for failures and automatically trips the circuit to prevent cascading failures in a microservice architecture, with configurable fallback methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ca06857-00b5-4631-b698-0fcdbb668f17', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind CSS help in maintaining consistency across a large project?', N'Fresher', N'Tailwind enforces consistency by restricting the available design options to your defined theme values, such as specific color palettes or spacing scales. By using the same utility classes throughout the application, you ensure that elements like margins, padding, and font sizes remain uniform.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5484efec-9e25-4da0-8797-0fcef6960ca9', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django’s ORM handle database connection pooling, and why is it often insufficient for high-concurrency applications?', N'Senior', N'Django opens and closes a connection for each request by default, which introduces significant latency under high load. For high-concurrency systems, you must use external tools like PgBouncer to manage persistent connection pools, as Django lacks built-in support for persistent connection pooling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a661964-9b9a-4213-8ab9-0fd0e8a26788', N'4c000000-0000-0000-0000-000000000005', N'Describe the difference between optimistic and pessimistic locking in high-concurrency systems.', N'Senior', N'Pessimistic locking prevents conflicts by locking resources for the duration of a transaction, which ensures safety but drastically reduces throughput in high-contention scenarios. Optimistic locking assumes conflicts are rare and uses version checks at commit time, which scales better but requires robust application-level retry logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43f952d4-5b10-4053-8048-0fd15f276c36', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Can Echo handle multiple HTTP methods for the same route?', N'Junior', N'Yes, you can register the same route path for different HTTP methods like GET, POST, or PUT. Echo routes requests based on both the URL path and the HTTP verb used by the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c0d532a-b1b9-4231-85b3-0fd3cd84202f', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle memory fragmentation?', N'Middle', N'Redis uses a custom memory allocator (like jemalloc) to manage memory efficiently. When fragmentation becomes too high, the ''activedefrag'' feature can be enabled to move data in memory and reclaim space, though this process can introduce some CPU overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7eba96a3-4e6b-4683-b41b-0fd8000e60cf', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono’s design accommodate the ''Isomorphic'' development pattern?', N'Senior', N'Because Hono targets Web Standards, the same code often runs on both the client (for data fetching or mock testing) and the server. This isomorphism allows developers to share validation schemas, API contracts, and business logic between the backend and frontend, significantly reducing code duplication and synchronization errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5c63d48-0d3b-4430-8ccd-0fd9a0dfe959', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot handle application properties?', N'Fresher', N'Spring Boot uses an application.properties or application.yml file located in the classpath to manage configuration settings. These files allow developers to externalize environment-specific settings like database credentials, server ports, or custom application variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de51e158-3753-416b-9d64-0fdaaef0cf1d', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the impact of Tailwind''s ''arbitrary values'' on design system governance?', N'Senior', N'Arbitrary values allow developers to deviate from the theme configuration, which can lead to ''magic numbers'' that break design system consistency. Governance requires strict code reviews or linting rules to ensure developers stick to the defined design tokens.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d208ea7-e26d-4204-8223-0fdd1eb81823', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How do ''Consistent Hashing'' algorithms improve system stability when adding or removing nodes from a cache cluster?', N'Senior', N'Consistent hashing maps both data keys and nodes onto a circular hash space, ensuring that only a small fraction of keys need to be remapped when a node is added or removed. This minimizes cache misses and prevents a sudden spike in requests to the underlying database compared to traditional modulo-based hashing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f064ad41-3f24-4dc6-b6ca-0fde95979382', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What does the ''volatile'' keyword signify in C?', N'Intern', N'The volatile keyword tells the compiler that a variable''s value may change at any time without any action being taken by the code the compiler is currently processing. This prevents the compiler from optimizing away reads or writes to that variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
