INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7eb07d3b-7b29-49e5-a8d6-0fe2a5e793eb', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''any'' type in TypeScript and why should it be used sparingly?', N'Fresher', N'The ''any'' type tells the compiler to ignore type checking for a variable, effectively turning off TypeScript''s safety features. It should be avoided because it negates the benefits of using TypeScript, making the code prone to runtime errors that static typing would otherwise prevent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'222e54bb-2e01-4614-8ec6-0fe9741370c3', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is a ''timeout'' error and what does it suggest about a system?', N'Fresher', N'A timeout error means a requested operation took longer than the system was willing to wait. It suggests that the target resource is either overloaded, unresponsive, or experiencing a bottleneck that prevents it from processing the request in time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5dd14e1c-36c7-413c-8ba7-0fea1263bf66', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the risk of CSRF attacks in Django and how the framework prevents them.', N'Senior', N'CSRF allows attackers to execute unauthorized actions on behalf of authenticated users by exploiting their browser''s session cookies. Django prevents this by injecting a secret, unique token into forms and verifying it on every POST, PUT, or DELETE request to ensure the request originated from the application itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
