INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4477cf4-f2cc-43da-b875-0fea3e17020c', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony''s ''HttpFoundation'' component handle file uploads, and what security considerations must be addressed at the architecture level?', N'Senior', N'HttpFoundation abstracts the raw PHP superglobals, providing a cleaner interface for accessing file metadata. From an architectural perspective, files must be stored outside the web root, validated for MIME types, and renamed before storage to prevent execution of malicious code and directory traversal attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
