INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ee84efb-3267-46b4-a7bf-0ffbda3dd6a6', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB ensure data durability in the event of a system crash?', N'Middle', N'MongoDB uses a write-ahead log (journaling) to record operations before they are applied to the data files. If a crash occurs, the system replays the journal during startup to recover the database to a consistent state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
