INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a0a5d60-3562-4110-af12-101890a6cbbd', N'4c000000-0000-0000-0000-000000000005', N'How would you handle the ''thundering herd'' problem when a high-traffic cache key expires in a distributed system?', N'Senior', N'The thundering herd problem occurs when multiple concurrent requests attempt to recompute the same expired cache key simultaneously, overwhelming the backend database. To mitigate this, implement a probabilistic early expiration strategy (XFetch) or use a distributed locking mechanism, such as Redis-based mutexes, to ensure only one process triggers the cache refresh while others continue to serve the stale data or wait.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
