INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e5a1e47-62be-4f4e-91df-1028e3b8ca7a', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of middleware in Express?', N'Fresher', N'Middleware functions are functions that have access to the request object, the response object, and the next middleware function in the application’s request-response cycle. They are used to execute code, make changes to the request/response objects, end the cycle, or call the next function in the stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'298c70d4-a801-43c2-83cd-102a8a4641bf', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What are the trade-offs of using Gin''s Context object compared to passing standard ''context.Context'' explicitly?', N'Senior', N'Gin''s Context is a custom wrapper that aggregates request and response data, which simplifies handler signatures. However, it can lead to tight coupling with the framework, making unit testing harder compared to injecting standard context.Context patterns which are idiomatic in Go for cancellation signals and request-scoped values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
