INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5eb78de7-6d05-4c06-91ad-103899e2ec0e', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does an array differ from a linked list in terms of memory?', N'Junior', N'Arrays are stored in contiguous memory blocks, allowing for fast access to any element by index. Linked lists consist of nodes scattered in memory, where each node points to the next, making insertion and deletion more flexible but access slower.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83f7810a-f6a6-479b-b588-103c70b3fef6', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the role of the x-cloak directive?', N'Fresher', N'The x-cloak directive is used to hide elements until Alpine.js has finished initializing the page. It prevents the ''flash of unstyled content'' where users might see raw template code before the framework processes the directives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22167ed6-95e4-43e8-9b17-103ce063a363', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you define property on Object constructor?', N'Fresher', N'The Object.defineProperty() static method is used to define a new property directly on an object, or modifies an existing property on an object, and returns the object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee4dba64-68c8-447b-a616-103d478e6904', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Explain the concept of ''chaining'' in jQuery and its impact on performance and code readability.', N'Middle', N'Chaining allows multiple methods to be called on the same set of elements in a single statement by returning the jQuery object. While it improves code conciseness, excessive chaining can make debugging difficult and may lead to redundant DOM lookups if not managed correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91a93e23-c7d2-4302-b09e-103dfaab0b30', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Compare the performance overhead of using JSON-based middleware in Express versus binary serialization formats.', N'Senior', N'JSON parsing is CPU-intensive and synchronous, which can block the event loop for large payloads. Using binary formats like Protocol Buffers reduces the parsing overhead and payload size, leading to lower latency and better throughput in high-load systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0fccada-dfcf-43d7-aa0b-103e99d8ccfb', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the role of the DynamoDB Streams feature?', N'Middle', N'DynamoDB Streams captures a time-ordered sequence of item-level modifications, such as insertions, updates, and deletes. It is commonly used for cross-region replication, triggering serverless functions, or maintaining materialized views in other data stores.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8da0dfc-6721-435f-bb5f-103eb8f7d07c', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot perform auto-configuration?', N'Junior', N'Spring Boot scans the classpath for specific library files and automatically configures beans based on the presence of those libraries. If you add a library like H2 or Hibernate, Spring Boot detects it and sets up the necessary data source and entity manager beans automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52793b70-6704-47c4-8eac-1040465315c7', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the useId hook in React and when should it be used?', N'Fresher', N'useId (added in React 18) generates a stable, unique string ID per component instance, per React root. Its main reason for existing is to produce IDs that match between the server-rendered HTML and the client hydration — a plain incrementing counter would produce mismatches. Within a single root the IDs are unique, but two separate roots on the same page can collide unless you set identifierPrefix on createRoot / hydrateRoot. Use it for things like linking to , never as a list key. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2518582-137a-4e35-843b-1041e2d93818', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Describe how to implement versioned APIs using Chi''s routing capabilities.', N'Senior', N'Versioned APIs are best handled by nesting routers under version-specific prefixes like /v1 and /v2. This allows for distinct middleware chains and handler sets for each version, ensuring that breaking changes in one version do not impact others while sharing the same underlying server instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6a72ee2-7b9b-4562-9ab9-1042111b3948', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the role of the ''reply'' object in a route handler?', N'Junior', N'The reply object is a wrapper around the standard Node.js server response that provides convenient methods for sending data. It allows you to set status codes, headers, and send payloads in various formats like JSON or buffers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce38ec51-e876-4524-9824-1043f4e4f3ce', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the primary architectural difference between Vite''s development mode and production build?', N'Senior', N'Vite uses unbundled ESM during development for speed, but relies on Rollup for production builds. Rollup is used because it provides superior tree-shaking, code-splitting, and asset optimization, which are critical for performance in a production environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56f26855-ba0e-4210-874c-1044406be19b', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How do you configure Rocket settings?', N'Fresher', N'Rocket settings can be configured using a configuration file, environment variables, or programmatically in the code. This allows for flexible deployment across different environments like development, staging, or production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae5a2fef-846e-47ec-8526-1045bbeec597', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the size of an enum type differ across platforms?', N'Middle', N'The C standard allows the compiler to choose the underlying integer type for an enum based on the range of values it contains. Consequently, the size of an enum can vary between different compilers or architectures, which can lead to portability issues when interfacing with hardware or binary file formats.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d846f38-4a1f-46e8-b563-1048b9ec9c93', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Why is the use of middleware considered a ''chain''?', N'Intern', N'Middleware is called a chain because requests pass through each defined middleware function sequentially before reaching the final handler. Each piece of middleware can choose to stop the chain or pass the request to the next function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51d7478b-b992-4a11-9f17-1049425686e3', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What are the advantages of using the Actor model for complex state management?', N'Middle', N'The Actor model encapsulates state within a single actor, ensuring that all modifications occur sequentially. This eliminates the need for complex mutex-based locking mechanisms, reducing the risk of deadlocks and making the state logic easier to reason about.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35310b87-0c89-436d-9bbd-104a039108ea', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web optimize the serialization and deserialization process?', N'Senior', N'Actix-web integrates with high-performance serialization libraries like Serde, which utilizes procedural macros to generate code that serializes and deserializes data at compile-time. This eliminates the need for runtime reflection, significantly speeding up the handling of JSON payloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e993c6b9-ce36-46c5-9185-104ad7b413da', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How do you handle ''poison pills'' in a message queue?', N'Middle', N'A poison pill is a message that causes a consumer to crash or fail repeatedly. It should be detected through retry limits and moved to a Dead Letter Queue to prevent it from continuously blocking the consumer or the partition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e63d3ac3-d9f6-41af-b191-104f5126bcfd', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle multipart form data compared to standard JSON payloads?', N'Middle', N'Gin provides specific binding methods for multipart forms, which include logic for handling file uploads and stream processing. Unlike JSON, which is typically parsed entirely into a struct, multipart handling often requires interaction with the request body as a stream to avoid high memory consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13c22374-c737-400e-948d-10504380e3b5', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is Routing in Symfony?', N'Fresher', N'Routing is the process of mapping a specific URL pattern to a controller action in your application. It allows you to define clean, readable URLs and ensures that incoming requests are correctly directed to the appropriate logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'665c084b-2d1e-4712-a65a-10529ed156c0', N'954a0331-deff-4399-b588-96f39fec001d', N'What are Content Projection and its primary use case?', N'Middle', N'Content projection allows you to insert external HTML content into a component''s template from a parent component. It is primarily used to build reusable wrapper components, such as modals, cards, or layout containers that require dynamic interior content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54bd8eef-fd9f-4943-84b8-105620be5da0', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does partitioning (sharding) impact the complexity of performing joins in NoSQL?', N'Senior', N'Partitioning prevents cross-shard joins because data is physically separated across different nodes. To perform joins, applications must either perform multiple queries and merge results in the application layer, or denormalize the data schema beforehand to store related information in a single document or partition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b63dda00-fd62-4a13-8287-105af02bdfb3', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is technical debt and how should it be managed?', N'Junior', N'Technical debt is the implied cost of additional rework caused by choosing an easy, quick solution instead of a better approach. It should be managed by regularly scheduling time to address it and ensuring it is tracked in the project backlog.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b3ddd7b-f8d0-4c08-9471-105f6710752a', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you force update?', N'Fresher', N'It is extremely rare situation of having to manually force an update despite the fact that no reactive data has changed. i.e, To force the Vue instance to re-render manually. You can do it force update using vm.$forceUpdate() API method. Note: It does not affect all child components but only the instance itself and child components with inserted slot content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1bfbc82-5edd-47fd-b6ce-10620c9952fe', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the difference between logical and physical sharding?', N'Middle', N'Logical sharding involves organizing data into different groups within the same database instance, often using schemas. Physical sharding involves distributing those groups across entirely separate server instances, providing true horizontal scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e7b6e3c-8b40-4317-a77c-106855851d21', N'954a0331-deff-4399-b588-96f39fec001d', N'What are Angular Guards, and when should you use them?', N'Middle', N'Guards are interfaces that allow you to control access to routes based on conditions, such as authentication or user roles. They are triggered before a route is activated or deactivated, helping to protect sensitive data and manage navigation flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc1ef7b2-1039-4cbf-bb67-1068669ea3ea', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the purpose of vuejs once directive?', N'Intern', N'If you want to render a lot of static content then you need to make sure it only evaluated once and then cached thereafter. In this case, you can use v-once directive by wrapping at the root level. The example usage of v-once directive would be as below, Note: It is recommended not to overuse unless there is slow rendering due to lot of static content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0330bd62-adb7-4b5f-9536-10687af63ae5', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the importance of the ''Astro.slots'' API?', N'Middle', N'The slots API allows for flexible component composition by enabling parents to inject content into specific placeholders in child components. This is the primary way to create layout components that can wrap different types of content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
