INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8699da3b-5be5-4e9b-9b90-1069f75935d1', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the difference between @import and @use in Sass?', N'Intern', N'While @import was the traditional way to include files, @use is the modern recommended approach. @use namespacing prevents naming collisions between files and loads modules only once, which improves performance and maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d1654b5-0547-40d7-af15-106e4ebd7f98', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you manage your time when working on multiple tasks simultaneously?', N'Junior', N'I prioritize tasks based on deadlines and dependencies, using a task tracking tool to stay organized. I try to focus on one task at a time to maintain context, communicating clearly if any shifting priorities affect my deadlines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61121c02-0525-4608-99f9-106f143a678b', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the benefits of using a centralized state management library like Pinia?', N'Middle', N'Pinia provides a structured, predictable way to manage shared state across large applications, making it easier to debug and track state changes. It separates the business logic from the UI components and ensures that state remains consistent across different parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8a2106d-8d70-4cb3-96e6-107632790695', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the primary advantage of extension functions in Kotlin?', N'Middle', N'Extension functions allow adding functionality to existing classes without needing to inherit from them or modify their source code. This promotes cleaner API design by providing a way to organize helper methods directly within the namespace of the target type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1831272e-a27a-4a50-869d-1076dbe422c7', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is ''noImplicitAny'' important for a codebase?', N'Middle', N'The ''noImplicitAny'' flag forces the developer to explicitly define types for variables where the compiler cannot infer a specific type. This prevents the compiler from defaulting to ''any'', which would otherwise silently disable type checking for those variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7f51270-a721-4631-94ec-1076dfc72f23', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is Dependency Injection (DI)?', N'Fresher', N'Dependency Injection is a technique where an object receives its dependencies from an external source rather than creating them itself. In Spring, the container injects the required objects into the classes that need them, promoting loose coupling and easier testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8f7768b-6b37-419c-9a64-107bcae9374a', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the impact of using ''UUIDs'' as primary keys compared to sequential integers?', N'Middle', N'Sequential integers are compact and index-friendly because they insert data at the end of the B-tree. UUIDs are larger and randomized, which can cause fragmentation in index pages, leading to increased I/O overhead as the database performs frequent page splits to insert data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0356a63b-d13a-4122-b9aa-107d8f6b95d2', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the benefit of MVCC (Multi-Version Concurrency Control) compared to strict locking?', N'Middle', N'MVCC allows multiple versions of data to exist simultaneously, enabling readers to access a consistent snapshot without blocking writers. This significantly increases concurrency and performance in read-heavy applications compared to traditional locking mechanisms that force readers to wait for writers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1643702-9597-4537-8404-107f57b4a9a8', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you prioritize which bugs to fix first?', N'Fresher', N'I prioritize bugs based on their impact and urgency, focusing on those that prevent core functionality or affect the largest number of users. Critical system crashes take precedence over minor cosmetic issues or edge cases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
