INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b17b7ff1-dea6-459b-a141-109d76f73081', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Does Quarkus support standard Java enterprise specifications?', N'Fresher', N'Yes, Quarkus is built on top of well-known Jakarta EE and MicroProfile specifications. This allows developers to use familiar APIs like Jakarta REST, Jakarta JSON-B, and MicroProfile Config while benefiting from the performance optimizations of the Quarkus framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'557f14c2-d1a4-4d10-b2f6-109fb6733f69', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the ''soft_deletes'' feature impact index recovery performance?', N'Senior', N'Soft deletes track changes in the Lucene index, allowing replicas to perform peer recovery by fetching only the missing operations rather than copying entire segments. This significantly reduces network bandwidth usage and recovery time, especially in clusters with frequent updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'234ed1d4-26a6-4eb5-8124-109fd36b71b2', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the @Service annotation used for?', N'Intern', N'@Service is a specialization of the @Component annotation used to indicate that a class holds business logic. It helps with code organization and allows the component scanning mechanism to detect and register the class as a bean.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e35066d-6fc5-4af6-960d-10a5e908c71c', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is an ''Arbiter'' in the context of Actix?', N'Junior', N'An Arbiter is an event loop that runs in its own thread. It is responsible for executing the logic of actors and managing the execution context, allowing different actors to run in parallel on different threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8341f44c-3f8c-48fa-91c2-10a76f675128', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What does the Lucid ORM do in AdonisJS?', N'Intern', N'Lucid is the built-in Object-Relational Mapper for AdonisJS. It provides an abstraction layer that allows developers to interact with database records using JavaScript objects rather than writing raw SQL queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a72ebe8-8c40-4aac-bae9-10a871b8de70', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Why is Quarkus considered ''Cloud Native''?', N'Middle', N'It is designed to minimize resource consumption and maximize startup speed, which are critical requirements for serverless and containerized environments. By optimizing for low memory footprints and fast scaling, it aligns perfectly with the operational models of Kubernetes and cloud-based platforms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e704daf-5860-4a37-ba87-10b05377ba34', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you approach a problem you have never encountered before?', N'Intern', N'I start by breaking the problem down into smaller, manageable components to isolate the core issue. I consult official documentation, existing internal knowledge bases, and team resources to understand the underlying theory before attempting a solution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad779da2-dae2-4601-82cc-10b1703c143f', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain the difference between ''self'' in a class definition versus inside a block or lambda.', N'Senior', N'In a class definition, self refers to the class object being defined, allowing for the definition of class methods. Inside a lambda, self is lexically scoped and remains bound to the object where the lambda was created, whereas blocks are closures that capture the surrounding scope''s self, making them dynamic based on the execution context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d0421f7-b68a-463c-bc76-10b1884e63d7', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of the SQL GROUP BY clause?', N'Fresher', N'The GROUP BY clause is used in conjunction with aggregate functions like COUNT, MAX, or SUM to group result rows that have the same values into summary rows. It is essential for generating reports and statistical data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9abd8a3-97e6-417c-b7e5-10b1ba5d4d80', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the purpose of a ''dead-letter queue'' in an asynchronous message processing system?', N'Senior', N'A dead-letter queue stores messages that cannot be processed successfully after a defined number of retries, preventing them from blocking the main processing pipeline. It allows developers to isolate, inspect, and debug problematic messages without stopping the entire system flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6266e58d-5e26-46e3-a5fb-10b24a27a907', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the benefit of Rocket''s ''Fairings''?', N'Junior', N'Fairings are a form of middleware that allow you to hook into the lifecycle of the application. They can be used for tasks like logging, modifying requests or responses, or performing initialization logic during server startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd159b331-6625-428e-bb85-10b2eeb4ece5', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why React uses className over class attribute?', N'Fresher', N'React uses className instead of class because of a JavaScript naming conflict with the class keyword. 1. class is a reserved keyword in JavaScript In JavaScript, class is used to define ES6 classes: If you try to use class as a variable or property name, it will throw a syntax error. Since JSX is just JavaScript with XML-like syntax, using class directly in JSX would break the parser. 2. JSX Is JavaScript When you write JSX like this: It will be compiled to: But class is invalid in this object literal context (since it clashes with the JS keyword), hence React instead uses className. which compiles to: React then translates className to class in the final HTML DOM. 3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63af4e50-bd82-45a9-805a-10b51d78fc6e', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you decide whether to use a relational database or a NoSQL database?', N'Fresher', N'I choose a relational database when the data is highly structured and requires complex relationships or strict consistency. I choose NoSQL when the data is unstructured, requires high flexibility, or needs to handle massive amounts of rapidly changing data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d7a5ce1-d099-4760-9f10-10b745b5df9d', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the role of the ''Ace'' CLI in the development lifecycle of a large-scale AdonisJS project?', N'Senior', N'Ace acts as the command center for scaffolding, migrations, and custom task automation. In large teams, it standardizes developer workflows and ensures consistency in environment configuration, deployment scripts, and database schema management across different development environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1975c19-de00-4135-a1b4-10b7f566dfb2', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is middleware in Actix?', N'Intern', N'Middleware are components that sit between the incoming request and the final handler. They can perform tasks like logging, authentication, or modifying requests and responses before they reach the main logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e59b4140-627d-4460-9b34-10bc5722e9cf', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does error handling work in Express?', N'Intern', N'Error handling is performed by defining middleware functions with four arguments: err, req, res, and next. These functions must be defined after all other app.use() and route calls to catch errors passed from previous middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44728333-276f-47b7-bde2-10bfcbf4bb84', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the difference between ''async def'' and ''def'' in FastAPI?', N'Intern', N'Using ''async def'' allows the function to be executed asynchronously, which is better for I/O-bound tasks. Using ''def'' executes the function synchronously, which is suitable for standard CPU-bound operations that do not need to wait on external resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d54d970-023b-4099-8925-10c075920d24', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing a system, how do you decide between a microservices architecture and a modular monolith?', N'Senior', N'I consider the team size, deployment frequency, and the need for independent scaling. A modular monolith is preferred for early-stage products to minimize operational complexity, while microservices are chosen when organizational scale demands independent service lifecycles and fault isolation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3affe98b-15d7-4480-a406-10c1a07b5107', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP''s type hinting and strict typing affect application reliability?', N'Middle', N'Type hinting allows developers to define expected data types for function arguments and return values, leading to better self-documenting code and earlier error detection. Strict typing ensures that PHP throws a TypeError when a mismatch occurs, preventing silent type coercion bugs that are common in loosely typed languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f9730f7-cd3d-493c-9109-10c1f774f5e9', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the role of an SQL Alias?', N'Junior', N'An alias is a temporary name given to a table or a column in a query result. It is used to make column headers more readable or to simplify queries that involve multiple tables with overlapping column names.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d683570-5ba0-485a-834d-10c69f1f146c', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind CSS handle the CSS bundle size issue compared to standard CSS frameworks like Bootstrap?', N'Middle', N'Tailwind uses a post-processing engine that scans your source files to identify used utility classes and generates a minimal CSS file containing only those specific styles. In contrast, traditional frameworks often include the entire library''s CSS regardless of usage, leading to larger file sizes unless significant manual tree-shaking is performed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f51721e6-5584-4a1a-be79-10c94881db8c', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What are middleware in Chi and what are they used for?', N'Junior', N'Middleware in Chi are functions that wrap an http.Handler to perform operations before or after the request is processed. They are commonly used for logging, request ID generation, recovery from panics, and authentication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0bb6202-45f0-4025-8a17-10cf6da494dd', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Explain the trade-offs of using Remix''s ''useFetcher'' hook versus standard navigation.', N'Middle', N'The ''useFetcher'' hook is designed for scenarios where you need to interact with loaders or actions without triggering a full page navigation, such as submitting a form in a modal or updating a specific UI component. While standard navigation is better for changing the entire page context and updating browser history, ''useFetcher'' provides granular control over background data synchronization. Overusing it can complicate state management, so it should be reserved for non-navigational side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
