INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56631708-4650-4ebb-b2ae-10d7af89fc2f', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the purpose of the ''$'' syntax prefix in Svelte stores?', N'Middle', N'The ''$'' prefix is a special syntax that tells Svelte to automatically subscribe to a store and keep the variable in sync with the store''s value. It simplifies the developer experience by removing the need for manual subscription and unsubscription logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7b08d41-d9d9-4dca-83b1-10e33d416e08', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is meant by ''lazy evaluation'' in R?', N'Intern', N'Lazy evaluation means that function arguments are not evaluated until they are actually used inside the function body. If an argument is never referenced within the function, it will never be computed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5a514af-1ef0-4c5b-84a8-10e47953cb41', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the working directory in R?', N'Intern', N'The working directory is the specific folder on your computer that R uses by default to read and write files. You can check or change this path to ensure R accesses the correct data files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ad49f77-4c8d-4716-b67c-10e47e882cf3', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web handle HTTP requests?', N'Fresher', N'Actix-web uses a routing system to match incoming HTTP requests to specific handler functions. When a request matches a route, the framework invokes the corresponding function to process the request and return an HTTP response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6e18ac1-9bde-4e7e-b157-10e4cc79f30a', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the ''Two-Phase Locking'' (2PL) protocol?', N'Middle', N'2PL ensures serializability by requiring that a transaction must acquire all necessary locks before releasing any. It consists of a growing phase where locks are acquired and a shrinking phase where locks are released, ensuring no new locks can be acquired once the shrinking phase begins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0def445-20ca-4ae7-af92-10e8e99509e2', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Can Astro be used for dynamic websites?', N'Fresher', N'Yes, through its SSR capabilities, Astro can fetch data from external APIs or databases at request time. This allows it to support personalized content and dynamic routes while maintaining performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e3633fb-b757-4307-8518-10e9e86164e9', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Explain the role of ''Cache-Control'' headers in HTTP caching and their impact on CDN behavior.', N'Senior', N'Cache-Control headers provide declarative instructions to intermediaries like CDNs regarding how long and under what conditions a resource can be cached. Proper configuration allows developers to optimize bandwidth and offload traffic from origin servers effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4eb0f6d2-2a90-439d-b6a9-10ea7aac9afd', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the ''public'' directory in a Vite project?', N'Intern', N'The public directory is used for static assets that should be served as-is without being processed by Vite. Files placed here are copied to the root of the build output and can be accessed directly via the root URL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'907ec3a6-53a6-4208-93db-10eb9eb6f40a', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When architecting for disaster recovery, how do you balance RPO and RTO against infrastructure costs?', N'Senior', N'I categorize services by criticality to apply different tiers of recovery strategies. Low RPO/RTO requirements necessitate active-active multi-region deployments, which are expensive, whereas non-critical services can survive with cold standbys or backup restores. The trade-off is framed as an insurance premium where the cost is justified only by the potential revenue loss during downtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'227a9551-8091-4600-91c7-10ee0944f0e4', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a Composite Primary Key in DynamoDB?', N'Fresher', N'A composite primary key consists of two parts: a partition key and a sort key. This combination allows for more complex data retrieval patterns compared to using a single partition key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c21c3b38-f3fe-4db4-9144-10f2557c8835', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How would you debug a persistent ''database connection pool exhausted'' error despite the application having an appropriate number of connections configured?', N'Senior', N'I would examine the application''s connection management code to ensure that connections are always returned to the pool in a ''finally'' block, even in the event of an exception. I would also monitor the database side to see if there are ''zombie'' connections or long-running queries that are holding onto connections for far longer than the application expects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce02ee41-5eba-4c26-859b-10f391adca76', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the impact of choosing a synchronous communication protocol like gRPC over HTTP/REST?', N'Middle', N'gRPC uses binary serialization and HTTP/2, which provides significantly lower latency and higher throughput compared to JSON over HTTP/1.1. However, it requires more effort for integration with browsers and is less human-readable than REST for debugging purposes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'372c7ace-5f2b-4871-9078-10f422313b2a', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix handle backpressure in its actor system?', N'Senior', N'Backpressure is managed primarily through mailbox limits and the asynchronous nature of message delivery. When a recipient is busy, the sender can asynchronously wait or apply strategies like load shedding to ensure the system remains stable under heavy traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8ed07bf-72cd-41c7-94cf-10f87fc77b6f', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your process for testing a solution you just developed?', N'Fresher', N'I first perform a manual walkthrough of the logic to check for edge cases. I then test the solution against the initial requirements to ensure it meets the objective and does not negatively impact existing functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d89ec58-1249-44ad-a8b1-10f8b664533b', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are ''externals'' in Webpack?', N'Junior', N'Externals allow you to prevent certain libraries from being bundled into your application. This is useful when you want to load a library like jQuery or React via a CDN instead of including it in your local bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97d54f09-af2d-4d60-9ab8-10f8f6d129b4', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How can you implement secure audit logging in a distributed system?', N'Senior', N'Logs must be streamed in real-time to an immutable, centralized, and append-only storage system located outside the production environment. Logs should be cryptographically signed or hashed to detect tampering and must exclude sensitive PII through automated masking at the edge.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8529498-4cc7-453a-8fa8-10fbe6237f85', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How do ''eval'' and ''instance_eval'' differ in their scope and security profile?', N'Senior', N'Eval executes string-based code within the current scope, while instance_eval changes the context to the target object, allowing access to its private state. Both are dangerous if used with unsanitized user input, as they can lead to remote code execution and arbitrary state modification.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07ab43ed-5a48-4d0f-b7bf-10fc4c1e2fc3', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Explain the architectural difference between a multiplexed event loop and Go''s M:N scheduler.', N'Senior', N'A traditional event loop (like Node.js) runs on a single thread and offloads I/O to the kernel, whereas Go''s M:N scheduler maps M goroutines onto N OS threads. Go''s approach allows for true parallel execution on multi-core systems without needing to manually manage multiple event loop processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddd4e657-de63-4f8e-9fd4-10fcfd027192', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is NextJS and major features of it?', N'Intern', N'Next.js is a popular and lightweight framework for static and server‑rendered applications built with React. It also provides styling and routing solutions. Below are the major features provided by NextJS, 1. Server-rendered by default 2. Automatic code splitting for faster page loads 3. Simple client-side routing (page based) 4. Webpack-based dev environment which supports (HMR) 5. Able to implement with Express or any other Node.js HTTP server 6. Customizable with your own Babel and Webpack configurations', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
