INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52029564-5d37-48f3-82a3-1104beb02162', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain the role of ''Decorators'' in AdonisJS models.', N'Senior', N'Decorators provide a clean, declarative way to define model relationships, column types, and hooks without cluttering the business logic. They leverage metadata reflection to allow the ORM to understand the schema structure at runtime, enabling features like automatic serialization and relational data fetching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfa9e80b-8c3b-4b1c-a2b9-1107e95492e6', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Can you use Remix with a database directly?', N'Fresher', N'Yes, because Remix runs on the server, you can import database clients directly into your loaders and actions. This allows for simple, secure data access without needing a separate backend server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
