INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eccdaa0a-b092-4db1-9070-110ae8b753af', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the impact of using Ecto''s ''Multi'' on database transaction integrity in Phoenix?', N'Senior', N'Ecto.Multi allows developers to group multiple database operations into a single atomic transaction while maintaining a clear, declarative pipeline. It effectively handles complex workflows where multiple records must be updated or created, ensuring that if any step fails, the entire set of operations is rolled back to maintain consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69fe02a6-d349-4c0d-b38f-110ba43f82c6', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is inheritance in Swift?', N'Intern', N'Inheritance allows a class to acquire the properties and methods of another class, known as the superclass. The class that inherits is called a subclass, and it can override the superclass''s functionality or add its own.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2575b82-2d61-4f0b-8c5b-110c05a54d31', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Why is it important to use Gin''s ''Group'' functionality?', N'Middle', N'Groups allow for logical categorization of routes, which simplifies the application of shared middleware and URL path prefixes. This improves code organization and allows for easier versioning of API endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4809141c-ffa2-4907-9eff-110cdbfa0942', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How do you optimize a Node.js application for high throughput in a cloud environment?', N'Senior', N'Optimization involves reducing event loop lag, using non-blocking I/O, leveraging keep-alive for HTTP connections, and vertical scaling via more cores or horizontal scaling via containers. Monitoring resource metrics and using tools like Prometheus/Grafana is necessary to identify bottlenecks in the request-response cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2485e167-a33a-4407-b89e-1111ac46b6fd', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How can you implement rate limiting in a Litestar application?', N'Middle', N'Rate limiting can be implemented by creating a custom middleware or a guard that tracks request frequency using a shared store like Redis. By checking the client''s IP or authentication token against the store, you can reject excessive requests before they reach the controller logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'501e16fa-becf-41ee-847b-111227ac6940', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the purpose of the Redis replication backlog, and how does it facilitate partial resynchronization?', N'Senior', N'The replication backlog is a fixed-size buffer that stores recent writes sent to replicas. If a replica temporarily disconnects, it can request a partial resynchronization by sending its last offset; if the offset is within the backlog range, the master sends only the missing data instead of a full state dump.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b5d52d2-049c-4d49-a48a-1115901f010c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach a design problem when you have conflicting requirements?', N'Intern', N'You should list the trade-offs of each approach and align them with the business priorities. If requirements conflict, you must communicate with stakeholders to understand which goal is more important to solve first.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b49c613-d934-4a96-b26e-11173279521d', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the significance of the --max-old-space-size flag in production environments?', N'Senior', N'This flag sets the memory limit for the V8 heap. If not tuned correctly, Node.js may crash with an out-of-memory error before the container orchestrator can restart it, or it may use excessive memory and trigger OOM killer policies. It should be configured based on the specific memory constraints of the deployment environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'359f6463-163d-438e-a213-111b6f6a4f13', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby handle access control for methods?', N'Intern', N'Ruby uses three levels of access control: public, protected, and private. Public methods can be called by anyone, protected methods can be called by instances of the same class or subclasses, and private methods can only be called from within the class itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c7a807a-b372-4b5d-bcd3-111de14044fc', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why would you choose to use a custom ''Extractor'' instead of just using the default ones?', N'Middle', N'Custom extractors are useful for encapsulating repeated logic, such as validating a JWT token or checking user permissions. They keep handlers clean by moving authorization and validation logic into a reusable, declarative format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6985027-bc1d-4924-b894-111ed5aca2ae', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does the ''when'' expression work?', N'Junior', N'The ''when'' expression is a more powerful and flexible replacement for the traditional switch statement. It can evaluate various conditions, ranges, or types and return a value, acting as an expression rather than just a control flow statement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aeeefacc-a44e-4b48-aaff-111ee03cba47', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the consequence of not terminating the request-response cycle in an Express route?', N'Middle', N'If you fail to send a response or call the next function, the request remains pending indefinitely. This leads to memory leaks and eventually causes the server to stop accepting new requests because the event loop becomes clogged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75d67782-6183-4a8e-94c0-111fe5ae4e0a', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the primary architectural pattern used by Django?', N'Intern', N'Django follows the Model-View-Template (MVT) architectural pattern. This pattern separates the data management (Model), the user interface presentation (Template), and the business logic that mediates between them (View).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95e1c2bb-6f88-477f-a02e-1121228b3ed9', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle streaming responses?', N'Senior', N'Rocket supports streaming responses by allowing handlers to return a ''Stream'' of data, which is then sent to the client as it becomes available. This is crucial for large downloads or real-time event streams, as it keeps memory usage low by not loading the entire response into the server''s RAM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34ae4196-18c1-43ed-a49b-1121a4eab577', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason about the trade-off between building a custom solution versus using an off-the-shelf tool when estimating delivery time?', N'Middle', N'I evaluate the long-term maintenance, integration effort, and feature flexibility of both options. While an off-the-shelf tool might be faster to implement initially, I estimate the time to integrate it versus building a custom, lightweight solution that fits our specific use case perfectly, considering total cost of ownership.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dabd755a-6f09-4d48-8f35-1123491391ae', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle static file serving, and why would you avoid using this in production?', N'Senior', N'Echo''s static file serving is convenient for local development or small internal tools, but it is not optimized for high-performance delivery compared to Nginx or a CDN. Using a dedicated web server or object storage for static assets offloads traffic from the application layer, improving overall system scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c58395b-d14c-46ed-a795-1124cffb2fb7', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What does ''hot module replacement'' mean?', N'Intern', N'Hot Module Replacement, or HMR, is a feature that allows modules to be updated in a running application without a full page refresh. This preserves the application state and significantly speeds up the development process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'270be560-92ac-4db4-b8e2-112995a4d6dd', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is a callback function in Express?', N'Fresher', N'A callback function is a function passed to a route or middleware that executes when the specific request is received. It typically accepts the request, response, and next objects to process the logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecc6fa3a-822e-47bd-b0c3-1130f07b0086', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How do you decide between a document-oriented database and a key-value store?', N'Middle', N'A key-value store is best for simple, high-speed lookups where the application handles data logic, offering maximum performance and simplicity. A document store is better when the database needs to understand the structure of the data, allowing for secondary indexing, querying, and filtering based on fields within the document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72a8d7d3-4d07-4de0-a01d-113114652cc7', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is a context manager and why is it used?', N'Junior', N'A context manager is a feature that allows you to allocate and release resources precisely when you want to. It is most commonly used with the ''with'' statement, which ensures that resources like file handles or database connections are automatically closed after the block of code finishes. This prevents memory leaks and ensures resource safety even if errors occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bae8cbc-7e08-4ae7-ab43-11315932f7de', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do you handle multi-tenancy in a Rails application?', N'Middle', N'Multi-tenancy can be handled by scoping queries using a tenant identifier, using separate database schemas, or using entirely separate databases. The approach chosen depends on the level of data isolation required and the complexity of managing shared resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd25eaaf8-0d6c-497f-bcef-11365fd9e74b', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a ''vector clock'' used for in NoSQL?', N'Middle', N'Vector clocks are used to track the causal history of updates to a data item in a distributed system. They help the database identify conflicts between concurrent updates, allowing the system to resolve or report those conflicts during read operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4a4e846-cabe-4ca1-ab6c-1136d0f1b489', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the common risks of not using parameterized queries?', N'Junior', N'The primary risk is SQL injection, where malicious users insert their own SQL code into input fields to manipulate the database. Parameterized queries treat user input as data only, preventing the execution of unintended commands.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'781eced5-92a1-483a-98cd-1138edde0b5d', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is a Case Class and why is it commonly used?', N'Junior', N'A case class is a specialized class that automatically generates useful methods like equals, hashCode, and toString. They are primarily used for immutable data modeling and are highly effective when used with pattern matching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85060bd2-00dd-409e-95dc-113c372cffcb', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does C# implement interface method dispatch differently than class method dispatch?', N'Senior', N'Class methods use vtable-based dispatch, while interface method calls require an interface method table lookup, which is slightly more expensive. Modern .NET runtimes employ devirtualization and interface caching to minimize this overhead, but interface calls remain inherently less direct than class-based virtual calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf27c26c-6669-428a-8c0d-113c4f0e7f0f', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the primary purpose of a database schema?', N'Intern', N'A database schema acts as the blueprint or logical structure that defines how data is organized and how the relations among them are associated. It ensures that data is stored in a predictable format, which helps maintain integrity and security across the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ad05a79-d6e5-4637-ba3a-113cbc6fd411', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the benefit of using the next/navigation hooks?', N'Junior', N'Hooks like useRouter or usePathname allow you to programmatically interact with the router and get information about the current URL. These hooks are optimized for use within the App Router architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a82c1a3f-4049-47ae-9936-113e1658f0c7', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS handle request-scoped providers, and why should they be used sparingly in high-throughput systems?', N'Senior', N'Request-scoped providers are instantiated per incoming request, which triggers a significant overhead as the DI container must resolve the dependency graph for every single call. In high-throughput systems, this can lead to increased latency and excessive garbage collection pressure, making singleton-scoped providers the preferred architectural choice for performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'534737bf-b1f3-48d1-abdb-113ed2409a18', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of the ''volatile'' keyword?', N'Intern', N'The volatile keyword tells the compiler that the value of a variable can change at any time due to external factors outside the program''s control, such as hardware or another thread. It prevents the compiler from performing optimizations that assume the variable''s value remains constant between accesses. This is crucial for hardware-level programming and multi-threaded applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2095ffd8-e16d-43f4-8138-113f350404a5', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Explain the trade-offs of using Cache-Aside versus Read-Through patterns.', N'Senior', N'Cache-aside places the responsibility on the application code to manage cache hits and misses, offering flexibility but increasing code complexity. Read-through abstracts the caching logic into the data access layer, simplifying the application code but tightly coupling the application to the specific caching provider.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e1021f9-982b-4ad0-9ecf-114493340bce', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why do we use array destructuring (square brackets notation) in useState?', N'Fresher', N'When we declare a state variable with useState, it returns a pair — an array with two items. The first item is the current value, and the second is a function that updates the value. Using [0] and [1] to access them is a bit confusing because they have a specific meaning. This is why we use array destructuring instead. For example, the array index access would look as follows: Whereas with array destructuring the variables can be accessed as follows:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'603c8b4f-ad17-4f65-a6ac-11451b976c94', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is Express.js?', N'Intern', N'Express.js is a minimal and flexible web application framework for Node.js. It provides a robust set of features for web and mobile applications, simplifying the process of handling HTTP requests and routing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2b11a57-9587-49eb-b6d7-11464fda4939', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the significance of the module graph in Vite, and how is it used during HMR?', N'Senior', N'The module graph is an internal map that tracks the dependency chain between files. During HMR, Vite traverses this graph to determine exactly which modules need to be invalidated and updated, ensuring that only affected parts of the application are re-evaluated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28e6167b-f3e9-4724-a158-11467e808ec7', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember''s build pipeline (Ember CLI) optimize assets for production?', N'Senior', N'Ember CLI utilizes Broccoli to create a dependency graph that performs tree-shaking, minification, and fingerprinting of assets. This ensures that only the necessary code is included in the production build and that cache-busting strategies are applied effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f784b70-9077-4cff-976a-114aeb269784', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix''s dependency on the server environment influence infrastructure design?', N'Senior', N'Remix requires a server runtime to process loaders and actions, meaning it cannot be deployed as a static site. This necessitates an infrastructure capable of handling server-side execution, such as Node.js, Cloudflare Workers, or Deno.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15d7cf05-a001-4c48-b54a-114d3a2a0543', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What are some of the challenges you might face when designing a microservices architecture?', N'Senior', N'When designing a microservices architecture, you are likely to encounter the following challenges: Data Management - Database Per Microservice: Ensuring that each microservice has its own database can be logistically complex. Data relationships and consistency might be hard to maintain. - Eventual Consistency: Different microservices could be using data that might not be instantly synchronized. Dealing with eventual consistency can raise complications in some scenarios. Service Communication - Service Synchronization: Maintaining a synchronous communication between numerous services can result in a more tightly coupled and less scalable architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05c02c6e-fb97-4973-9373-114e0d451b1a', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does the ''final'' keyword affect class design in C++?', N'Middle', N'The final keyword can be used to prevent a class from being inherited or a virtual function from being overridden. It is a useful tool for performance optimization and architectural enforcement, signaling that the design is complete and should not be extended further.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'144d1948-36db-4adf-a3ad-114f77ab663b', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a Redis snapshotting?', N'Intern', N'Snapshotting is a persistence method that saves the entire dataset to a disk file at specified intervals. It creates a point-in-time copy of the database state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6193810f-b079-413e-9826-114fb64881d9', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the trade-offs between using type aliases and interfaces for defining object shapes.', N'Senior', N'Interfaces are extendable via declaration merging, which is useful for library authors, while type aliases support unions and intersections that interfaces cannot represent. Interfaces generally offer better compiler performance and more descriptive error messages in complex type hierarchies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a00e8c4e-1bac-42ea-819b-11545a68cc46', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB handle horizontal scaling?', N'Junior', N'MongoDB handles horizontal scaling through a process called sharding. This involves distributing data across multiple physical machines or clusters to manage large datasets and high throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bef4e7d9-8870-49f5-846d-115650144231', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the interaction between the Java metaspace and native memory management.', N'Senior', N'Metaspace stores class metadata in native memory rather than the garbage-collected heap, allowing it to grow automatically based on the available host memory. While this prevents heap fragmentation, it necessitates strict monitoring of native memory pressure to avoid unexpected OS-level OOM kills.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01a029eb-f6bb-4b0d-8eda-11589efce38b', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a ''hot spot'' in database sharding, and how can it be avoided?', N'Middle', N'A hot spot occurs when a specific shard receives a disproportionately high amount of traffic compared to others. It is avoided by choosing a shard key with high cardinality and even distribution, preventing specific nodes from becoming bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd20b3870-60ba-4835-b199-115ab3039fd7', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What does ''type-safe'' mean regarding Rocket''s request handling?', N'Intern', N'Type-safety means that Rocket automatically validates incoming request data against the types defined in your functions. If a request does not match the expected data types, Rocket rejects the request before it reaches your logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c88933d-ba11-4556-b98b-115c4f000473', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is it important to avoid synchronous methods in the Node.js event loop?', N'Senior', N'Synchronous methods block the entire process, meaning no other events can be processed until the method returns. In a web server, this means all other concurrent requests are paused, causing a massive increase in response latency. Every blocking call effectively serializes the application, destroying the benefits of the non-blocking I/O model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'655770c4-b40d-43b6-8915-115f9cc4bcb0', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Describe the impact of PHP''s request-lifecycle on database connection pooling.', N'Senior', N'Because PHP lacks a persistent process-wide state, native database connection pooling is not possible within the language runtime itself. Connection pooling must be handled by external middleware like ProxySQL or PgBouncer, as each PHP process terminates its connection handle upon request completion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c76060a4-8d36-43fe-958f-1161123974ee', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using a global CSS file and CSS modules for styling a frontend application?', N'Fresher', N'Global CSS files are easier to set up for small projects, but they can lead to naming conflicts as the application grows. CSS modules provide scoped styles by default, preventing style leakage and making it easier to maintain components in large projects. You choose CSS modules when you need a more scalable and predictable styling architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56a1afea-2e2d-4f07-83cf-1165b8d65073', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When should you ask a team member for help with a bug?', N'Junior', N'I should ask for help after I have exhausted my own troubleshooting steps and spent a reasonable amount of time investigating, usually after hitting a ''blocker'' state. It is important to present what I have already tried so the team member can build upon my progress rather than repeating the same steps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a05ec68-6bcd-425b-8294-1167edd8a87a', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt handle route-based code splitting?', N'Middle', N'Nuxt uses file-system-based routing to automatically generate chunks for each page. When a user navigates to a route, Nuxt only loads the JavaScript and CSS associated with that specific page, significantly reducing the initial bundle size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20e94647-9158-4bf4-ad12-11686d37ac20', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the benefit of server-side rendering in Remix?', N'Intern', N'Server-side rendering allows the server to generate the HTML for a page before sending it to the browser. This improves performance for the initial page load and ensures that search engines can easily crawl and index the content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59a44929-e878-4253-8554-1169b9297b3e', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of Swift''s ''Value Witness Table'' and how does it relate to generics?', N'Senior', N'The Value Witness Table is an internal structure that defines how the runtime handles the lifecycle of a type, such as allocating, copying, and destroying values. When using generics, the compiler cannot know the size or alignment of the type at compile time, so it uses the table to perform these operations polymorphically. This allows generic functions to operate on any type without knowing its memory layout beforehand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54a43fd6-4f55-4ed8-9c27-116a51fc28d3', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift handle error propagation versus traditional exception handling?', N'Senior', N'Swift uses a typed error propagation model where functions must explicitly declare that they can throw errors, and callers must acknowledge this with a try keyword. Unlike traditional exceptions, Swift''s errors do not use stack unwinding, which is computationally expensive and makes the control flow hard to follow. This approach ensures that error handling is explicit and predictable throughout the call stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fe17fc8-b8de-4ee6-ba12-116a8f0a4425', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How do for-comprehensions work in Scala?', N'Senior', N'In Scala, a for-comprehension is a high-level language construct that enables seamless iterations across collections, abstracts, or data types that define a specific behavior. You can think of it as a more readable and intuitive syntactic sugar that simplifies working with map, flatMap, and filter operations. Key Components - Generators: These specify the data sources you want to iterate over. - Filters: Optional, they help you select specific elements meeting certain criteria. - Variables: These are declared within the for-comprehension and preserve values throughout the loop. - Statements: Enclosed within curly braces, they define actions to be carried out for each iteration. Example: List of Squares Here is the corresponding Scala code: Syntax Breakdown - Generator: n', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f3c52e8-f82c-4802-80e7-116cdcb0545c', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Interfaces in TypeScript and how do they work?', N'Intern', N'In TypeScript, an interface defines the structure and types of its members. It acts as a contract for the required properties and methods, ensuring that implementing classes or objects match this structure. Key Features of Interfaces - Type Consistency: Objects that adhere to an interface''s structure are considered compatible with it. - Optional and Readonly Members: Interfaces allow for optional attributes and readonly members with the ? and readonly keywords respectively. - Call Signatures: Interfaces can define method types, specifying function parameter and return types. - Index Signatures: Useful for specifying that an object can have any number of properties, all of a certain type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88300ed2-fa1c-4d64-a035-116d336b7bd1', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony handle environment variables, and why is this practice preferred?', N'Middle', N'Symfony uses the Dotenv component to load environment variables from files, which helps keep configuration separate from the codebase. This practice is preferred because it allows the application to be deployed across different environments without modifying the source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11ad23b9-00dd-4b04-abac-116ea531a1f9', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do you dispatch custom events from a child component to a parent?', N'Junior', N'You use the createEventDispatcher function to create a dispatcher. You then call the dispatcher with the event name and optional data, allowing the parent to listen for the event using the on: directive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00a29b45-4b4c-4161-ae7d-116eb8733f00', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it useful to consult team documentation or wikis when encountering a bug?', N'Junior', N'Many bugs are recurring or involve known limitations of the system that have already been documented by other team members. Checking documentation can save significant time by preventing me from re-discovering the same issues or attempting solutions that were already proven unsuccessful.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8ad0207-4c74-41c6-b476-11767c50ad28', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why is it important to use ''onDestroy'' in Svelte components?', N'Middle', N'The onDestroy lifecycle hook is crucial for cleaning up side effects such as intervals, event listeners, or store subscriptions. Failing to do so can result in memory leaks, which negatively impact application performance over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bda40bd-4a7f-4ce2-acc5-117756e075b2', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Describe the security implications of session management in Phoenix.', N'Senior', N'Phoenix uses signed and optionally encrypted cookies to store session data, ensuring integrity and confidentiality. By using plug-based session management, developers can easily rotate secrets and set strict security flags, protecting against session tampering and cross-site scripting attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efb59b13-54b6-4ba5-9d6b-1177b3160e24', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the benefit of immutable state updates?', N'Intern', N'Immutable state updates allow for efficient change detection and predictable debugging. By creating a new state object rather than modifying the old one, you ensure that components can easily determine if they need to re-render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acdf2f7d-f8c9-42ed-977f-117dcc7133ad', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle DOM updates compared to traditional manual DOM manipulation?', N'Middle', N'Alpine.js abstracts manual DOM manipulation into declarative directives, ensuring that the DOM stays in sync with the state automatically. This prevents common bugs associated with manual updates, such as synchronization errors and memory leaks from forgotten event listeners.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
