INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42a2de0a-7620-4316-ae01-1181895fa8a9', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between Query Strings and Route Data?', N'Fresher', N'Route data is part of the URL path itself, used to identify specific resources, while query strings are key-value pairs appended to the URL after a question mark, typically used for filtering or sorting results.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c27f18b8-de7d-4bda-98aa-118340768743', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does the Serializable isolation level differ from others in terms of performance?', N'Middle', N'Serializable is the highest isolation level and provides the strictest guarantees by ensuring transactions execute as if they were running one after another. Because it requires significant locking or dependency tracking, it often results in reduced concurrency and higher chances of transaction aborts due to serialization failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f30ffa8-7486-4f0a-97f4-11844aadde74', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How do you stop the default behavior of an event in jQuery?', N'Junior', N'You can prevent the default behavior, such as a link following a URL or a form submitting, by calling the .preventDefault() method on the event object passed to the handler function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
