INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a834ff5-20b0-4707-9fd8-119e29f8bc5f', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the difference between ''Eventual Consistency'' and ''Strong Consistency''?', N'Senior', N'Strong consistency guarantees that all reads return the latest write, effectively behaving like a single-node system. Eventual consistency allows temporary divergence between replicas, ensuring that if no new updates are made, all replicas will eventually return the same data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b328c93a-ec2d-40a2-9a74-11a0d2fabdfc', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the C abstract machine handle the sequence point concept in relation to optimization?', N'Senior', N'Sequence points define the boundaries at which all side effects of previous evaluations must be complete and subsequent evaluations must not have begun. Compilers use these points to determine the limits of instruction reordering for optimization without violating the observable behavior mandated by the standard.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea4dad27-8a84-4a30-9e68-11a0df6c02a1', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the importance of the ''SECRET_KEY'' in a Flask application?', N'Junior', N'The secret key is used to cryptographically sign session cookies and other security-related tokens. It prevents users from tampering with their session data, making it a critical component for application security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ee19f24-5265-4f6d-b580-11a202deba02', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring''s dependency injection container handle circular dependencies?', N'Senior', N'Spring attempts to resolve circular dependencies between singleton beans by using setter injection or @Lazy proxies, which defer the resolution until the bean is actually accessed. However, constructor-based circular dependencies result in a BeanCurrentlyInCreationException because the container cannot resolve the required instances during the initialization phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa4c4971-48e3-459f-ad2e-11a211d5a9bf', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the role of Hibernate ORM in Quarkus?', N'Fresher', N'Hibernate ORM is used in Quarkus to handle object-relational mapping, allowing developers to interact with databases using Java objects. Quarkus provides a specialized extension for Hibernate that makes it efficient and compatible with native compilation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55e66d75-95ff-4d18-8a20-11a36cd531be', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Discuss the implications of C''s lack of a garbage collector on system reliability.', N'Senior', N'The lack of garbage collection places the responsibility for memory management entirely on the programmer, which allows for precise control over resource lifecycles and predictable performance. However, this significantly increases the risk of memory leaks, dangling pointers, and double-free errors, which are common sources of system instability. Successful C development requires rigorous ownership models and the use of tools like static analyzers or sanitizers to manage these risks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffb3edaa-64f7-412e-be44-11a4496130e9', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the ''extern'' keyword function?', N'Middle', N'The ''extern'' keyword declares a variable or function without defining it, indicating that the definition exists in another translation unit. It allows the current file to access globally scoped identifiers defined elsewhere in the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48b41937-ea08-46b6-9664-11a58a5c35aa', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between @Transactional(readOnly=true) and regular transactions?', N'Middle', N'Setting readOnly to true provides a hint to the underlying database and JPA provider to optimize performance by skipping dirty checking. It is useful for read-only operations to reduce the load on the persistence context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6071a59b-1de2-4f1e-9b84-11a6c342867d', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of the ''Form'' parameter in FastAPI?', N'Fresher', N'The ''Form'' parameter is used when you need to receive data sent as form fields rather than as a JSON body. It is commonly used for HTML form submissions where the content type is application/x-www-form-urlencoded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'090b5922-06ad-4ff9-a794-11ab4983a9c0', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why is it important to use prepared statements for database interactions in PHP?', N'Middle', N'Prepared statements separate the SQL query logic from the user-provided data, ensuring that the database treats inputs as values rather than executable code. This is the most effective defense against SQL injection attacks, as it prevents malicious users from altering the structure of the database query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93a3084b-ee7f-4149-969c-11abbce0af60', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why might you choose to use aliases in Elasticsearch?', N'Middle', N'Aliases provide a layer of abstraction that allows you to change the underlying index without updating your application code. They are useful for zero-downtime index migrations and for grouping multiple indices under a single name for queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c86c1aea-ff94-44d8-a94a-11ac35ec0a32', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the role of the ''init'' function and its impact on package initialization?', N'Senior', N'The ''init'' function is a special function that runs automatically during package initialization, allowing for the setup of global variables and registration of dependencies. Because it runs before the ''main'' function, it provides a deterministic way to configure state. However, excessive use of ''init'' can make the order of execution hard to track and lead to hidden side effects, so it is recommended to keep them minimal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0de38dab-4444-4428-8ee4-11ad688ce39f', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you handle long-running tasks in Flask to avoid blocking the request-response cycle?', N'Middle', N'Long-running tasks should be offloaded to a background task queue like Celery or RQ. The Flask application triggers the task and immediately returns a response to the client, while a separate worker process executes the logic asynchronously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be905f6d-72e5-45df-8568-11af377b165c', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the function of the ''layout.js'' file in the App Router, and how does it affect component re-rendering?', N'Middle', N'A layout file defines a persistent UI structure shared across multiple pages, such as headers or sidebars. Because layouts are preserved during navigation, they do not re-render when the user moves between pages that share the same layout, improving performance and state persistence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6d6dc9f-cc66-40fb-959c-11b1b1a337db', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is it important to understand that Fiber uses Fasthttp under the hood?', N'Junior', N'Because Fasthttp uses a request pooling mechanism to reduce garbage collection pressure, users must be careful not to store references to request objects after the handler returns. Accessing request data outside the handler''s scope can lead to data corruption or unexpected behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4dbe8580-5f9d-4512-b3be-11b2c92f92e3', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Explain the architectural difference between ''Component'' and ''Helper'' in Ember.', N'Senior', N'Components are stateful, lifecycle-aware units that manage DOM structure and user interaction. Helpers are stateless, functional utilities meant for simple data transformation or logical checks within templates, providing a cleaner separation between view logic and presentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2499a9e-e669-428a-b8da-11b82618b85b', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the impact of heavy disk I/O on the Elasticsearch garbage collector?', N'Senior', N'Heavy disk I/O can block threads and cause latency in the indexing pipeline, leading to increased memory usage as pending tasks queue up. This pressure on the JVM heap can trigger frequent or long ''stop-the-world'' garbage collection cycles, which further degrades performance and can lead to nodes being marked as unresponsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33e6639b-ae78-4807-a3c1-11b88efa2213', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain browser console logs features?', N'Fresher', N'The Console method log() outputs a message to the web console. The message may be a single string or it may be any one or more JavaScript objects. 1. console.table() Output 2. console.log() 3. console.warn() 4. console.error()', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e008aa7-a423-43cc-aeff-11bb34e01fe5', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'In the context of Hono, what are the primary trade-offs when choosing between the ''hono/tiny'' build and the full-featured framework?', N'Senior', N'The ''hono/tiny'' build minimizes the cold-start footprint by excluding auxiliary features like advanced middleware and complex routing, making it ideal for extremely latency-sensitive edge functions. The trade-off is the loss of developer productivity tools and built-in abstractions, which forces the developer to implement common patterns, such as complex parameter validation or sophisticated error handling, from scratch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1c331ff-f64e-48f0-96c7-11bd954bb44f', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle CORS?', N'Intern', N'CORS (Cross-Origin Resource Sharing) is a security feature that restricts web pages from making requests to a different domain. Echo provides a middleware to configure these policies, allowing the server to permit or deny cross-origin requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd727aed9-52c8-4542-93e3-11be45c6fff5', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the Dev UI in Quarkus?', N'Fresher', N'The Dev UI is a built-in web interface available in development mode that allows you to inspect your running application. It provides information about loaded extensions, configuration properties, and various diagnostic tools to help you monitor and debug your application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8509205-1de1-4910-aa6b-11c08dc4dcb7', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the purpose of the ''content-visibility'' property?', N'Senior', N'The content-visibility property allows the browser to skip rendering work for off-screen elements. By setting it to ''auto'', the browser avoids painting and layout for hidden content, which significantly improves initial load times and responsiveness for long, content-heavy pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b6197f1-3b15-4e35-a5fc-11c446f29e72', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are Procs and Lambdas and how do they differ?', N'Middle', N'Both are objects that wrap blocks of code, but they differ in how they handle arguments and the ''return'' keyword. Lambdas enforce strict argument counting and return control to the calling method, while Procs are more lenient with arguments and cause a return from the surrounding scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5064ecc7-d989-41c6-838e-11c46e1f1164', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle scoped CSS?', N'Intern', N'Svelte automatically adds a unique class name to elements within a component during the build process. It then applies the styles specifically to those classes, ensuring that CSS in one component does not leak into another.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d20c649-a5a0-43fa-9b46-11c49531d570', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How do Redis ''Modules'' extend the database''s functionality beyond core primitives?', N'Senior', N'Modules allow developers to load compiled libraries into the Redis process, enabling custom data types and specialized commands, such as RedisJSON or RediSearch. This effectively turns Redis into a multi-model database while retaining its core performance characteristics and memory management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd72a9fa1-22b5-4094-a8de-11cc3cced9dd', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is a Buffer in Node.js?', N'Intern', N'A Buffer is a built-in class used to handle raw binary data. Since JavaScript strings are typically UTF-8, Buffers are necessary to manipulate streams of data from files, network sockets, or other sources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a11739b-b39f-4135-b892-11cf1700e48e', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s approach to request bodies affect memory usage for large file uploads?', N'Senior', N'Echo reads request bodies into memory by default, which can lead to OOM errors with large uploads. You must configure the body limit or use streaming approaches to process large payloads directly from the request stream without fully buffering into memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd2d5f0a-25c5-4844-816f-11cf752febca', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the role of the build tool (Gradle/Maven) in Micronaut?', N'Intern', N'The build tool is responsible for orchestrating the compilation process, which includes triggering Micronaut''s annotation processors. These processors are essential because they generate the metadata and supporting classes required for dependency injection to function correctly at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c710573f-7f0c-4495-914a-11d0be239853', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the significance of Gin''s engine configuration for custom logger and recovery writers?', N'Senior', N'Gin allows overriding the default output writers for logging and recovery, which is critical for log aggregation in containerized environments. Redirecting these streams to standard output or a structured logging library ensures that logs are correctly parsed by collectors like Fluentd or ELK.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd29ebfb8-c563-4ffc-bcda-11d10c0d22b5', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the significance of Go''s ''zero value'' philosophy.', N'Middle', N'In Go, every type has a well-defined zero value, ensuring that variables are always in a valid state upon initialization. This eliminates many classes of bugs related to uninitialized memory and simplifies the logic required to instantiate complex data types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45702dd7-7161-45bc-86ff-11d27f487da3', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Explain the concept of ''Request-Scoped'' data in Express.', N'Middle', N'Request-scoped data refers to information attached to the ''req'' object as it travels through the middleware chain, such as authenticated user details or transaction IDs. This allows different middleware functions to share context about a specific request without needing to use global variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11abf795-5af9-4305-af5d-11d6282705f4', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What are the advantages of using a CDN (Content Delivery Network) over a standard server-side cache?', N'Middle', N'A CDN caches static assets at edge locations geographically closer to the user, significantly reducing network latency and offloading traffic from the origin server. A standard server-side cache typically optimizes data retrieval from the database, which is closer to the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'868e2fc3-b9c6-4684-91c2-11d9f39092d2', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What are cookies in the context of Rocket?', N'Fresher', N'Cookies are small pieces of data stored on the client side. Rocket provides a way to easily read and write these cookies, allowing developers to maintain session information or persistent user preferences.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0eb91bd-adc6-47b8-a1c3-11da0aaead2c', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are props in React?', N'Intern', N'_Props_ are inputs to components. They are single values or objects containing a set of values that are passed to components on creation similar to HTML-tag attributes. Here, the data is passed down from a parent component to a child component. The primary purpose of props in React is to provide following component functionality: 1. Pass custom data to your component. 2. Trigger state changes. 3. Use via this.props.reactProp inside component''s render() method. For example, let us create an element with reactProp property: This reactProp (or whatever you came up with) attribute name then becomes a property attached to React''s native props object which originally already exists on all components created using React library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'833ea2a6-32b8-4367-899a-11dc2cb22bd1', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the benefit of a serverless database like DynamoDB?', N'Fresher', N'A serverless database eliminates the need for managing underlying infrastructure, such as hardware provisioning or software patching. The provider handles all administrative tasks, allowing developers to focus solely on application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ad2298f-cdf6-4f50-987c-11ddf3c5cacc', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s approach to request binding handle security vulnerabilities like mass assignment?', N'Senior', N'Echo''s binding mechanism maps request fields directly to struct fields. To prevent mass assignment, developers must use Data Transfer Objects (DTOs) with specific tags rather than binding directly to database models, ensuring only intended fields are updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18551e32-22df-4eed-ab13-11e030bcb31d', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why is client-side navigation faster than standard page transitions?', N'Junior', N'Client-side navigation only fetches the necessary data and the layout changes required for the new route rather than downloading the entire HTML document. This keeps the application state persistent and avoids the overhead of a full browser reload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb0b5237-a6c5-4f74-9ff8-11e2b457add6', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How can you implement caching strategies for API routes in Nuxt/Nitro?', N'Middle', N'Nitro supports route rules that allow you to define caching headers or internal caching policies for specific API endpoints. This reduces database load and response times by serving cached results for identical requests for a specified duration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e9fad2f-69fc-46c4-bc14-11e3d9a2018d', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Discuss the trade-offs of using CSS Grid versus Flexbox for high-level page layout.', N'Senior', N'CSS Grid is inherently two-dimensional, making it superior for overarching page structure where rows and columns must align independently, whereas Flexbox is one-dimensional and ideal for aligning content within components. Using Grid for global layout allows for more robust responsive strategies with less code, while Flexbox remains the standard for interior alignment and distribution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33303a05-603d-4775-92e9-11e5625c0965', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are the implications of enabling ''Server Mode'' Garbage Collection?', N'Senior', N'Server GC provides multiple heaps and dedicated background threads for garbage collection, which significantly increases throughput for high-load, multi-core systems. While it improves performance under heavy pressure, it also increases total memory usage compared to Workstation GC, making it less suitable for small or memory-constrained applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e004ed7-6d81-41d9-916b-11e64d743192', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What are the security trade-offs of storing sensitive configuration data, such as API keys, in environment variables versus a dedicated secrets manager?', N'Middle', N'Environment variables are often logged, exposed in process dumps, or accidentally committed to version control, making them less secure. A dedicated secrets manager provides centralized auditing, encryption at rest, and the ability to rotate credentials automatically, which is significantly safer for production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bc6caff-8600-4ef6-aba4-11e6d95ec20c', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the mechanics of PHP''s garbage collection cycle for circular references.', N'Senior', N'When the reference count of a ZVAL reaches zero but is still part of a circular reference, the garbage collector triggers a cycle-finding algorithm to identify and clean up the unreachable memory. This prevents memory leaks in complex object graphs, though it introduces a small, periodic CPU cost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a25381a-2a15-4f1d-986d-11e76dced3a4', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the difference between CSS variables and preprocessor(SASS, LESS, Stylus) variables?', N'Fresher', N'SASS variables are replaced with their values as the preprocessor produces its CSS output long before the browser interprets the code, while CSS custom properties are evaluated by the browser at runtime. Example: Preprocessor Variable The above code would do nothing in a browser. The browser wouldn''t understand the declarations and toss them out. Preprocessors need to compile into CSS to be used. This code would compile to: This is now valid CSS. The variable was part of the preprocessor language, not CSS itself. Once the code compiles, the variables are gone. Example: CSS Custom Property The native CSS has started supporting CSS variables, or "CSS Custom Properties". It allows you to work with variables directly in CSS. There is no compiling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'388172ba-d466-4c5e-8d37-11e9c5d78ab6', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a pure function', N'Intern', N'A pure function is a function whose output depends only on its input arguments and produces no side effects. This means that given the same inputs, a pure function will always return the same output, and it does not modify any external state or data. Let''s take an example to see the difference between pure and impure functions, Example: Pure vs. Impure Functions - impureAddNumber changes the external variable numberArray and returns the new length of the array, making it impure. - pureAddNumber creates a new array with the added number and does not modify the original array, making it pure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74b92ed4-3444-4cb4-8525-11ea5ecf50c2', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you manage secrets and sensitive configuration in a cloud-native environment?', N'Senior', N'I would use a dedicated secret management service like HashiCorp Vault or cloud-provider-specific solutions such as AWS Secrets Manager. These tools provide dynamic secret rotation, audit logging, and least-privilege access, ensuring secrets are injected at runtime rather than stored in version control or environment variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04288d20-bfd7-4208-a3c5-11ecea650b02', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the fastest way to swap the values bound to two variables?', N'Intern', N'In Python, the fastest way to swap the values bound to two variables is to use tuple unpacking, like this: In this code, the values of a and b are swapped by creating a tuple of the values in reverse order ((b, a)) and unpacking them into the variables a and b. The assignment is performed simultaneously, which makes this method faster than using a temporary variable, which requires an additional assignment. For example: In this example, the values of a and b are swapped using tuple unpacking, and the final output shows that the values have indeed been swapped.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'897b61c4-6664-48b9-b46d-11f31238d47b', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you handle redirects in Flask?', N'Fresher', N'Redirects are handled using the ''redirect'' function, which returns an HTTP response telling the browser to navigate to a different URL. It is often used in combination with the ''url_for'' function to ensure the correct route is generated dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23c8308a-48ad-42c0-9a11-11f5fb70b254', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the difference between the ''id'' and ''class'' selector in jQuery?', N'Fresher', N'The ID selector targets a single unique element with a specific ID attribute, whereas the class selector targets all elements that share a common class name. Using the ID selector is generally faster and more precise for single elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'766179d0-74a7-4773-b523-11f97b4d3a3c', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is an empty element in HTML?', N'Junior', N'An empty element is an element that does not have any content or a closing tag. Examples include img, br, and hr, which are self-closing and perform specific functions without wrapping text or other elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'843280f7-0372-4a4c-9203-11fa726100b9', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is an event listener in Lit?', N'Intern', N'An event listener in Lit allows a component to react to user interactions like clicks or input changes. You can attach these listeners directly within the template syntax.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa97403e-6921-4555-b709-11fac9eac102', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the trade-offs of using decorators?', N'Middle', N'Decorators provide a clean, reusable way to modify or extend the behavior of functions and classes without changing their source code. However, excessive use can make the stack traces more difficult to read and complicate debugging. They also hide the original function''s metadata unless the functools wrapper decorator is used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fb4115f-2a1c-4d38-adde-11fcd2404dae', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the advantage of using AdonisJS ''Mail'' providers?', N'Middle', N'The Mail provider abstracts the underlying transport layer, allowing you to switch between services like SMTP, Amazon SES, or Mailgun without changing your business logic. It also supports queuing, which is essential for maintaining application responsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffe62e90-00a7-47ea-a72e-11fe0ab32f81', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify''s routing tree handle path parameters compared to regex-based routers?', N'Senior', N'Fastify''s radix tree routing avoids the overhead of testing every route against a regular expression. It traverses the tree based on path segments, offering O(n) performance where n is the number of path segments, regardless of the total number of routes defined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70d67766-2076-41c7-a2e2-12047a72c29f', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the benefit of Alpine''s ''magic properties'' like $refs?', N'Middle', N'Magic properties provide a standard way to access common DOM elements or framework utilities without writing extra code. $refs, for example, allows you to directly reference DOM elements in your logic, making it easier to perform manual operations like focusing an input or measuring an element''s dimensions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a43ce4d8-6086-4e98-9d07-12051067680b', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How do ''Policies'' differ from ''Middleware'' in AdonisJS for authorization?', N'Middle', N'Middleware acts as a gatekeeper for entire routes or route groups, while Policies are dedicated classes that handle specific authorization logic for individual resources. Policies allow for more granular control, such as checking if a specific user is permitted to edit a specific record based on ownership.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc4e6f08-f185-45bc-a184-1206839f4ba3', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are path parameters in FastAPI?', N'Intern', N'Path parameters are dynamic values embedded directly into the URL path. They are used to identify specific resources, such as a user ID, and are captured by the framework for use in the function logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd972abd-e7ad-4810-8299-12071766c52e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you detect primitive or non primitive value type', N'Fresher', N'In JavaScript, primitive types include boolean, string, number, BigInt, null, Symbol and undefined. Whereas non-primitive types include the Objects. But you can easily identify them with the below function, If the value is a primitive data type, the Object constructor creates a new wrapper object for the value. But If the value is a non-primitive data type (an object), the Object constructor will give the same object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5dc2cecd-6e02-4b81-a33e-1208a0648f19', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the differences between XMLHttpRequest and fetch() in JavaScript and browsers?', N'Intern', N'XMLHttpRequest (XHR) and fetch() API are both used for asynchronous HTTP requests in JavaScript (AJAX). fetch() offers a cleaner syntax, promise-based approach, and more modern feature set compared to XHR. However, there are some differences: - XMLHttpRequest uses event callbacks, while fetch() utilizes promise chaining. - fetch() provides more flexibility in headers and request bodies. - fetch() supports cleaner error handling with catch(). - Handling caching with XMLHttpRequest is difficult, but caching is supported by fetch() by default via the cache value of the second parameter to fetch() or Request(). - fetch() requires an AbortController for cancelation, while XMLHttpRequest provides an abort() method. - XMLHttpRequest has good support for progress tracking, which fetch() lacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31d5a425-f129-4f9a-abd9-120a38d1b96a', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi compare to the standard ''net/http'' ServeMux?', N'Junior', N'While the standard ServeMux is basic and lacks advanced features like path parameters or grouping, Chi offers a more feature-rich API. Chi provides better support for complex routing patterns, middleware chaining, and clearer path parameter handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5534ea1c-fb8b-44e9-b524-12117e50c258', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Explain the difference between app.use() and app.METHOD() in Express.', N'Middle', N'app.use() is used to mount middleware functions that execute for any HTTP method or specific path prefixes, making it ideal for global cross-cutting concerns. app.METHOD() targets specific HTTP verbs like GET or POST, ensuring the handler only executes when the request matches both the URL path and the specific HTTP method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c65623d8-0220-4b5a-90ea-12125f45a91b', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the primary purpose of a module bundler like Webpack in a frontend project?', N'Junior', N'Webpack takes various assets like JavaScript files, CSS, and images, and bundles them into a single file or a small set of files optimized for the browser. It helps manage complex dependency graphs between files and allows developers to use modern features like modules, which browsers might not natively support in all environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'211cd87a-6451-44d9-bde3-1212a01f7bd9', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are the trade-offs of using Scala''s ''Future'' API?', N'Middle', N'Futures allow for non-blocking asynchronous operations, improving responsiveness. However, they can be difficult to debug due to stack traces that span multiple threads, and they require careful management to avoid resource exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41bdd481-4ab2-4a16-8891-1214fce46f00', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How can you highlight text in HTML?', N'Fresher', N'The HTML element represents text which is marked or highlighted for reference or notation purposes, due to the marked passage''s relevance or importance in the enclosing context. Example: Note: By default, browsers render with a yellow background.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
