INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4840c48-17e8-4664-b19c-1231291d85e2', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does memory alignment impact CPU performance and memory access?', N'Senior', N'Processors are optimized to fetch data from memory at addresses that are multiples of the data size, such as 4 or 8 bytes. Misaligned accesses can cause the CPU to perform multiple memory cycles or trigger hardware exceptions, necessitating padding within structures to ensure optimal performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
