INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce72f266-ed5d-4709-8944-123941d000ff', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the benefit of Qwik''s architecture for mobile users?', N'Intern', N'Mobile users benefit significantly from Qwik because it reduces the amount of data that needs to be downloaded and processed. This leads to faster Time to Interactive (TTI) scores, which is crucial for users on slower network connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73c2b1c1-560f-4ffa-94eb-1239ffca7606', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Explain the difference between Redis RDB and AOF persistence mechanisms.', N'Middle', N'RDB performs point-in-time snapshots of the dataset at specified intervals, making it efficient for backups and fast restarts. AOF logs every write operation received by the server, providing better durability and data integrity at the cost of larger file sizes and potentially slower recovery times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'864dfc9c-3941-4d8a-8316-123cb5eb6ee3', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle event delegation, and why is this efficient for large lists?', N'Senior', N'Alpine.js utilizes event delegation at the root level to capture events bubbling up from child elements. This approach is highly efficient because it avoids attaching individual event listeners to every single DOM node in a list, significantly reducing memory consumption and improving browser performance during user interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cd0c366-8a86-428d-9030-123f0191302c', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the String Pool optimization work in Java?', N'Middle', N'The String Pool is a special memory area in the heap where Java stores unique string literals to save memory. When a string is created using a literal, the JVM checks the pool first; if an identical string exists, it returns a reference to the existing instance instead of creating a new one. This significantly reduces memory usage when applications use many repeated string values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cf45d31-b793-49c3-b15b-123fbb6bf72f', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach refactoring a legacy system without breaking existing functionality?', N'Middle', N'I prioritize writing comprehensive integration and unit tests for the critical paths before making any changes. I then proceed with incremental, small-scope refactorings using the Strangler Fig pattern to replace segments of the system while maintaining a working version throughout the process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e80a9b51-6944-4642-a48b-124067e85858', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is an Iterator', N'Intern', N'An iterator is an object which defines a sequence and a return value upon its termination. It implements the Iterator protocol with a next() method which returns an object with two properties: value (the next value in the sequence) and done (which is true if the last value in the sequence has been consumed).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4164983-ca56-4667-9212-124263dc03dd', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Are Qwik applications considered Single Page Applications (SPAs)?', N'Fresher', N'Yes, Qwik can function as an SPA, but it handles navigation and resource loading differently than traditional SPAs. It provides a seamless transition between pages while maintaining the high performance of a multi-page application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd31ace5d-1153-42d4-9840-1242716c948f', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is ''Streaming'' in the context of Next.js?', N'Junior', N'Streaming is a technique that allows you to send UI components to the client in chunks rather than waiting for the entire page to render on the server. This improves performance by allowing users to see and interact with parts of the page before the full content has finished loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64af7643-917d-4d79-b017-124502cae383', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How do you handle relationships in MongoDB?', N'Intern', N'Relationships are handled either through embedding, where related data is stored inside a single document, or referencing, where a document stores the ID of another related document. Embedding is preferred for one-to-few relationships, while referencing is used for one-to-many or many-to-many relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9074ef0b-f795-45bc-a554-124514c133ce', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why do many NoSQL databases prefer ''Eventual Consistency'' over ''Strong Consistency'' for global deployments?', N'Senior', N'Global deployments face significant speed-of-light latency issues when attempting to synchronize data across geographically distributed data centers. Eventual consistency allows local data centers to process transactions instantly without waiting for cross-continent round trips, providing a better user experience at the expense of temporary global state inconsistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18a1d139-f12e-48d8-8633-12478674d200', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are the trade-offs of using ''Server-Side Rendering'' (SSR) versus ''Static Site Generation'' (SSG) in SvelteKit?', N'Middle', N'SSR generates pages on-demand per request, which is ideal for dynamic, user-specific data but increases server load. SSG generates pages at build time, offering superior performance and scalability but requiring a full rebuild to update data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c84f5ab4-da90-4352-86f4-124bcd2ed87c', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is ''Russian Doll Caching'' in Rails and why is it effective?', N'Middle', N'Russian Doll Caching is a technique of nesting cached fragments within other cached fragments. It is effective because invalidating an outer cache fragment automatically refreshes the inner ones, ensuring that the view layer is updated efficiently without regenerating the entire page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55fc577a-021a-4f0e-8aed-124d830b994c', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the primary benefit of avoiding custom CSS class names?', N'Intern', N'Avoiding custom class names removes the overhead of naming components and deciding where to keep styles. It prevents the problem of naming collisions and reduces the time spent managing and maintaining large CSS files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85f9de5f-8be9-484b-947c-12504310032d', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle reactivity compared to vanilla Web Components?', N'Junior', N'Vanilla Web Components require manual updates to the DOM when data changes. Lit automates this process by using reactive properties that trigger an automatic update cycle whenever their values are modified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21a7f674-f679-45f7-8888-1250f08da85d', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the benefit of using PubSub in a Phoenix application?', N'Middle', N'PubSub allows for decoupled communication between different parts of the application or even different nodes in a cluster. By publishing messages to a topic, you can trigger side effects across the entire system without the sender needing to know about the subscribers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b61c2c4d-24ad-48aa-9327-1251910ace36', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are the trade-offs of using ''attributeChangedCallback'' versus reactive properties in Lit?', N'Middle', N'Reactive properties are more ergonomic and integrated with Lit''s change detection system, making them the standard choice for data flow. Using ''attributeChangedCallback'' directly is lower-level and usually unnecessary, as Lit automatically maps observed attributes to properties, simplifying the synchronization between HTML attributes and JavaScript state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd673411f-e6f3-4777-8a99-125305c85f60', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Describe the trade-off of using Shadow DOM in Lit components.', N'Middle', N'Shadow DOM provides strong style encapsulation, preventing global CSS from bleeding into the component and vice versa. However, it can make global theming more difficult and may require the use of CSS parts or custom properties to allow external styling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8e9c51c-aa3e-4e6d-85b5-1253bbb7e867', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does ''strict mode'' do in TypeScript configuration?', N'Junior', N'Strict mode enables a wide range of type-checking behaviors that provide stronger guarantees about program correctness. It includes features like ''noImplicitAny'' and ''strictNullChecks'', which help prevent common bugs related to missing or unexpected values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a52b542-a369-43af-9bd5-1254c1a75bf2', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using a relational database and a NoSQL database?', N'Fresher', N'Relational databases prioritize data integrity and complex querying, while NoSQL databases prioritize high write-throughput and flexibility with unstructured data. The choice depends on whether your application requires strict consistency or rapid, scalable data ingestion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f52b462-7d55-44a1-9197-12559d882b24', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are Ecto Changesets and why are they used?', N'Junior', N'Changesets are used to filter, cast, and validate data before it is sent to the database. They provide a safe way to handle form inputs and ensure that only valid data is persisted, preventing common errors or invalid states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
