INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86a1af31-7475-4239-bb47-126144ebf70d', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the role of the ''Action Creator'' and why is it considered a best practice to keep them as pure functions?', N'Senior', N'Action creators act as factories for action objects, abstracting the structure of the action from the component. Keeping them pure ensures that they are easily testable and predictable, preventing accidental logic errors from being injected into the dispatch process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
