INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d2db19b-8dff-4645-a383-126797583d5c', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the purpose of the ''using'' statement in C#.', N'Middle', N'The using statement provides a convenient syntax for ensuring that IDisposable objects are properly disposed of once they are no longer needed. It automatically calls the Dispose method on the object, which is crucial for releasing unmanaged resources like file handles or database connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e4cf89b-1e10-4767-b479-1269b72631fe', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony Security handle authentication versus authorization, and why are these separate?', N'Senior', N'Authentication identifies who the user is through mechanisms like JWT or session cookies, while authorization determines what the user can do based on roles or attributes. Separating them allows for flexible security policies where authentication methods can be swapped or added without changing authorization logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
