INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78bb79b1-9496-446e-83d7-126caded10b2', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does strict serializability differ from serializability?', N'Senior', N'Serializability guarantees the outcome of concurrent transactions is equivalent to some serial execution, but it does not mandate the order relative to real-time. Strict serializability adds the requirement that the order must also respect the real-time order of transaction completion, effectively combining serializability with linearizability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
