INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'853fa94c-ad87-4066-9263-12781441aab3', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is scalability in the context of databases?', N'Intern', N'Scalability refers to the ability of a database system to handle an increasing amount of work or data load. It can be achieved through vertical scaling, which adds more resources to an existing server, or horizontal scaling, which adds more servers to the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fbf8077-41d4-464a-8c5c-127ab87951b4', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the primary performance trade-offs when using Fiber compared to standard net/http?', N'Senior', N'Fiber is built on Fasthttp, which achieves higher performance by minimizing memory allocations and reusing objects via sync.Pool. However, this creates trade-offs regarding compatibility with the standard library''s context-based interfaces and potential misuse of request objects outside the handler scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9bff88a-c889-4535-8d6e-127b1231971f', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite support TypeScript?', N'Junior', N'Vite provides built-in support for TypeScript by using esbuild to transpile TS files into JavaScript. However, it only performs transpilation and does not conduct type checking, which is typically handled by the IDE or a separate build script.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0a52b31-193a-4387-938e-127bf674dfb6', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the purpose of jQuery chaining?', N'Intern', N'Chaining allows multiple jQuery methods to be called on the same set of elements in a single statement. This makes the code more concise and readable by reducing the need to repeatedly select the same elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80bf3514-025b-43d5-94ee-128245fd17af', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R handle missing data?', N'Intern', N'R uses the special value NA, which stands for Not Available, to represent missing values in data. Most statistical functions in R provide options to ignore these values during calculations to prevent errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6744b447-c2c8-481c-bde8-128273b625c8', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When designing a system, how do you estimate the trade-off between consistency and availability (CAP theorem) in terms of user experience?', N'Senior', N'I map the business requirements to the cost of inconsistency for specific user actions, quantifying the impact of stale data versus the impact of an unavailable service. This reasoning allows me to choose the appropriate consistency model, such as eventual consistency for non-critical reads, to ensure the system remains available and performant under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41c1e8e2-53df-4dfd-893e-12861d8ab43e', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is a nested type in Swift?', N'Fresher', N'Swift allows you to define types, such as enums, classes, or structs, inside the definitions of other types. This is used to organize code and encapsulate helper types within the context they are used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d7005ef-74e2-43ff-860c-128a39e537e1', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is static analysis critical to the Qwik framework''s build process?', N'Senior', N'Qwik uses static analysis to identify functions that need to be extracted into separate, lazy-loadable modules. By automatically wrapping code into QRLs, the build process ensures that the developer can write natural-looking code while the framework handles the complex splitting required for resumability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a5dd547-4df8-481f-b123-128b9d7baffc', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the Model-View-Controller (MVC) pattern?', N'Fresher', N'MVC is an architectural pattern that separates an application into three main components. The Model manages data and business logic, the View handles the user interface, and the Controller acts as an intermediary that processes requests and coordinates between the Model and the View.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30afad31-91d5-4be7-aef6-128e2bb23bd1', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Describe the impact of Preact''s small API surface area on library maintenance and long-term scalability.', N'Senior', N'A smaller API surface area results in less internal complexity, making the library easier to audit, secure, and maintain over the long term. This reduces the risk of regression bugs and allows for a more stable foundation, which is crucial for enterprise applications that need to support multiple versions over several years.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cac64c3e-17a5-4f80-bf85-128ec7b6438b', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What happens if an index does not fit into RAM?', N'Middle', N'If the indexes does not fit into RAM, MongoDB reads data from disk which is relatively very much slower than reading from RAM. Indexes do not have to fit entirely into RAM in all cases. If the value of the indexed field increments with every insert, and most queries select recently added documents; then MongoDB only needs to keep the parts of the index that hold the most recent or "right-most" values in RAM. This allows for efficient index use for read and write operations and minimize the amount of RAM required to support the index. Example: To check the size of indexes', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddaa8be5-7da6-45a8-80f7-1293fb4d479d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using an Agile development process versus a Waterfall approach?', N'Junior', N'Agile allows for frequent iterations and pivots based on feedback, which is ideal for changing requirements. Waterfall offers a predictable timeline and clear documentation from the start but is rigid and difficult to adjust if initial assumptions turn out to be incorrect.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2b0c7ab-5026-45ad-9dc1-12985c1aaa27', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why is it important to use the Remix Link component instead of an anchor tag?', N'Junior', N'The Link component provides prefetching capabilities and smoother client-side navigation. It allows Remix to intelligently load the data for the next page before the user even clicks, resulting in a faster perceived experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
