INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fef5d3f1-aa2c-42a2-b165-1299d5b18501', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the primary architectural differences between ''Column-Family'' and ''Key-Value'' stores?', N'Senior', N'Key-value stores are designed for simple retrieval based on a unique identifier, providing high performance but limited query capabilities. Column-family stores are optimized for large-scale analytical or wide-row workloads, allowing for efficient aggregation of specific columns across sparse datasets and providing more complex indexing options.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
