INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6735d6b9-fd3e-4c7c-b13b-12a3e2bafacb', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the purpose of the Write-Ahead Log (WAL) in database systems?', N'Middle', N'WAL ensures data integrity by recording all changes to a durable log file before applying them to the actual data files. This allows the database to recover to a consistent state in the event of a crash or power failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5e56c3e-38ba-407f-ab11-12a4af58b895', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'When designing a large-scale API, why might you choose to implement a custom middleware over using Echo''s built-in recovery middleware?', N'Senior', N'While built-in recovery is convenient for general stability, custom recovery middleware allows for structured logging, integration with distributed tracing systems, and granular error reporting tailored to specific business requirements. It enables the decoupling of infrastructure-level panic handling from domain-specific error management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ccb0dd6-015f-4260-942d-12a81c5da6c1', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'When should you avoid embedding data in a document?', N'Junior', N'You should avoid embedding when the embedded document grows indefinitely, as MongoDB has a document size limit of 16 megabytes. Additionally, if the data is updated very frequently or accessed independently of the parent document, referencing is usually a better choice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7eb6f81c-3179-407a-b983-12abcf9a6d75', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Describe the role of environments in R''s scoping rules.', N'Middle', N'Environments are data structures that map names to values and are central to R''s lexical scoping. They form a parent-child hierarchy, where a function''s scope is determined by where it was defined, not where it was called, allowing functions to access variables from their enclosing environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f62f91d2-2426-4564-8fc5-12ac01d1029d', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Explain the concept of ''optimistic updates'' within the Redux flow.', N'Senior', N'Optimistic updates involve updating the UI immediately before the server response confirms the action, assuming the request will succeed. If the request fails, the application must be able to roll back the state to the previous snapshot, which Redux facilitates through its immutable state history.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd291383a-f705-41b7-848a-12ac4edd993e', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is a Phoenix Plug?', N'Intern', N'A Plug is a specification for composable modules that sit between the web server and the application. They are used to perform tasks like logging, authentication, or request transformation as a request flows through the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0efd6bf-0607-4c9d-b65f-12adb9861618', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI validate headers or cookies?', N'Fresher', N'FastAPI allows you to define parameters for headers and cookies using the ''Header'' and ''Cookie'' classes. Similar to other parameters, these are automatically validated and parsed based on the provided type hints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb7a34ed-9517-4f68-af9d-12b0f088b7d9', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of the ''WeakMap'' and ''WeakSet'' data structures?', N'Senior', N'WeakMap and WeakSet hold weak references to their keys, meaning they do not prevent the garbage collector from reclaiming those objects if no other references exist. They are ideal for associating metadata with DOM nodes or private data with objects without causing memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a034d8b1-0959-45d5-9c8d-12b255c10f4b', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If you are unsure about a requirement, what is the best way to clarify it?', N'Junior', N'I would reach out to the stakeholders or the product owner to ask specific questions about the expected behavior. It is better to ask for clarification early in the process than to spend time building the wrong thing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fbcf69d-017c-4309-8347-12b26acef48b', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the purpose of the ''Links'' function in a Remix route?', N'Intern', N'The links function allows you to define CSS stylesheets or pre-fetch links that are specific to a particular route. Remix automatically adds these to the document head when the user navigates to that route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8bbc70f-1376-4019-8446-12b278cd6b12', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit optimize the rendering of lists compared to frameworks like React?', N'Middle', N'Lit uses a directive called ''repeat'' that uses unique keys to track list items during updates. This allows Lit to move, add, or remove existing DOM nodes instead of re-rendering the entire list when data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8654686d-c7a6-49a7-b692-12b738f6187a', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the purpose of the ''manifest'' file generated by Vite during the production build?', N'Middle', N'The manifest file provides a mapping between non-hashed source filenames and their hashed production counterparts. This is essential for server-side rendering or backend integration, allowing the server to dynamically inject the correct file paths into the HTML templates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'428af6b1-dbe1-4cf3-b02d-12b780d1bfff', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What strategy do you use to debug a system that behaves correctly under low load but fails under heavy load?', N'Middle', N'I would look for bottlenecks related to concurrency, such as thread pool starvation, database connection limits, or lock contention that only manifest when many processes compete for resources. Using performance testing tools, I would simulate the high load in a staging environment to observe these thresholds and tune the system configuration accordingly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c15949e1-1dad-4485-90fd-12b7ceb7055a', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Describe the memory overhead associated with Python''s small object allocator (pymalloc).', N'Senior', N'Pymalloc optimizes allocations for small objects by requesting large memory blocks from the OS and subdividing them into pools and arenas. While this reduces fragmentation and system call overhead, it creates a risk where memory is held by the allocator even after objects are freed, potentially leading to higher resident set sizes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'532f2afa-e003-4ce7-9371-12b80c2ef869', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the benefit of using Astro''s built-in image component?', N'Junior', N'The image component automatically optimizes images by resizing, cropping, and converting them to modern formats like WebP or AVIF. This helps improve page speed and core web vitals by ensuring images are served in the most efficient way.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa1193de-812f-4538-8d5b-12b9193b821d', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the mechanism behind ''streaming'' in SvelteKit and how does it relate to ''load'' functions?', N'Senior', N'Streaming allows the server to send the initial page shell immediately while ''streaming'' subsequent chunks of data as they become available. This significantly improves perceived performance by allowing the UI to render partially before all slow data requests have completed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f3da8d6-c589-403e-bbf3-12bcf68ee6c6', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember handle nested routes?', N'Fresher', N'Ember allows you to define a hierarchy of routes, where a child route is visually rendered inside a parent route''s template. This allows for complex UI layouts where certain parts of the page change while others remain static.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ef3f8b3-5b50-4d6b-80b5-12bde39e005d', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What are the common strategies for handling API retries on the client side?', N'Middle', N'Clients should implement exponential backoff with jitter to avoid overwhelming the server during retry storms. This prevents a synchronized surge of requests that could lead to a cascading failure of the backend services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'643c7b42-c8f4-4b14-aa0e-12c015d875f7', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the purpose of the ''Balancer'' in a sharded cluster and how does it affect system performance?', N'Senior', N'The balancer is a background process that monitors the distribution of chunks across shards and migrates them to maintain an even balance. While it ensures cluster scalability, migration activities consume CPU and network bandwidth, which can temporarily impact production query performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8108e0dd-a1a1-4d50-af93-12c0e6a7c18c', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the time required for a complex refactoring project when technical debt is poorly documented?', N'Senior', N'I would perform a time-boxed discovery phase to map high-risk modules and create a dependency graph. I then apply a confidence factor to the estimated effort, breaking tasks into granular sub-tasks and using a range-based estimation method to account for unforeseen discovery during the refactoring process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfcb1553-97f5-4a56-9de6-12c1c3d9c7e5', N'954a0331-deff-4399-b588-96f39fec001d', N'When should you use ''providedIn: root'' versus adding a service to a module''s providers array?', N'Middle', N'Using ''providedIn: root'' enables tree-shaking, allowing the service to be excluded from the final bundle if it is not used. Adding a service to a module''s providers array forces the service to be part of that specific module''s scope and prevents it from being tree-shaken.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17c730ed-9ac5-467d-a49f-12c57b3b3466', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your approach to rate limiting in a distributed system to prevent cascading failures?', N'Senior', N'I implement multi-layered rate limiting, starting with edge-based ingress controls to protect the system perimeter. I then use service-level tokens or leaky buckets to ensure fair resource allocation and backpressure mechanisms to prevent slow consumers from saturating the event bus or internal network.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51101a00-da25-4cf1-929d-12ca0a8c4a2d', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the primary architectural benefit of Fastify''s plugin system compared to Express''s middleware-based approach?', N'Middle', N'Fastify uses an encapsulated plugin system based on a directed acyclic graph, which allows for better isolation of settings, hooks, and decorators. Unlike the linear middleware chain in Express, Fastify''s architecture prevents cross-pollution of configurations between different parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'000c4cce-5ee1-4267-a693-12cfcce5433d', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the purpose of a ''minimal reproducible example'' when reporting a bug?', N'Intern', N'A minimal reproducible example strips away unrelated logic and data to demonstrate the bug in the simplest possible form. This helps developers focus on the core issue and confirms that the bug is rooted in the system logic rather than external factors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a10b7f2c-a4c8-411d-82c6-12cffc91841a', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How do you define layouts in Nuxt?', N'Junior', N'Layouts are defined in the layouts directory and allow you to create shared structures like headers and footers. You can apply a layout to a specific page by setting the layout property in the page''s metadata or using the NuxtLayout component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a78a63d-bb78-42cf-8b63-12d94c78ac93', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is a Micronaut Client?', N'Intern', N'A Micronaut Client is a declarative interface used to perform HTTP requests to external services. By annotating an interface with @Client, the framework automatically implements the logic to invoke the remote API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'151ac905-093b-4b61-bb1b-12ddb67577db', N'075b8862-431c-4678-9767-f55359758a4a', N'How do ''Fragment'' components affect the DOM tree structure in Vue 3?', N'Senior', N'Fragments allow components to have multiple root nodes, eliminating the need for unnecessary wrapper divs that were required in Vue 2. This results in a cleaner, more semantic DOM structure and reduces the CSS complexity associated with managing deep, redundant element nesting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3f21e98-39c5-48d2-9bb4-12de2071d719', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a unique constraint?', N'Intern', N'A unique constraint ensures that all values in a specific column are different from one another. Unlike a primary key, a unique constraint may allow null values depending on the database system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06266427-f55c-4b22-890a-12de36567f27', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is a closure in Rust?', N'Intern', N'A closure is an anonymous function that can capture variables from the scope in which it is defined. They are often used for short-lived tasks like passing logic to iterators or asynchronous callbacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2183f05a-7e90-4f01-8ae5-12de7c9b9162', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why does Rocket require handlers to be async functions?', N'Middle', N'Async handlers allow the server to yield control when performing I/O tasks, such as database queries or file reads. This non-blocking behavior is essential for high-performance backends, as it enables a single server process to maintain thousands of concurrent connections without blocking threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'996abaa2-1cc4-44d0-a58d-12df1aebd24c', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the significance of the Litestar ''App'' object?', N'Fresher', N'The App object is the central registry of a Litestar application. It holds configuration, route definitions, middleware, and dependency providers, acting as the main entry point for the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8cfffcc-cdb4-49ac-a568-12e08862b136', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the ''init'' function?', N'Intern', N'The ''init'' function is a special function that runs automatically when a package is initialized. It is typically used for setup tasks like variable initialization or registering components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c001db4-f708-4e75-a7d7-12e3ae6b1e32', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt''s middleware system differ from Vue Router''s navigation guards?', N'Senior', N'Nuxt middleware is integrated into the framework''s lifecycle and can be executed on both the server and the client, making it suitable for tasks like server-side redirects or auth checks. Vue Router navigation guards are strictly client-side, making them insufficient for scenarios requiring server-side authentication validation before the page is rendered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a16b6c49-cad6-40eb-9fa9-12e3c5d706cd', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the trade-offs of using sync.Pool for object reuse in high-concurrency web servers?', N'Senior', N'Using sync.Pool reduces GC overhead by recycling objects, but it introduces complexity in object cleanup. If objects are not properly reset before being returned to the pool, sensitive data or state from a previous request can leak into a new one.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c507a15-1b69-45c1-a4f5-12e5253b396b', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Why is it recommended to use ''AsNoTracking'' in Entity Framework Core for read-only queries?', N'Middle', N'Using AsNoTracking disables the overhead of change tracking for the entities returned by a query. This reduces memory usage and improves performance significantly because the context does not need to snapshot the objects or monitor them for updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6122de99-5f96-451e-92df-12e5b395d1b1', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it important to use environment variables for sensitive configuration like API keys rather than hardcoding them?', N'Junior', N'Hardcoding secrets exposes them in version control systems, posing a severe security risk. Environment variables allow configuration to be managed outside the source code and injected at runtime, enabling different settings for development, testing, and production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17f73580-acd5-44fe-ba0b-12e759865d28', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the difference between a GET and POST request?', N'Intern', N'A GET request is primarily used to retrieve data from a server without modifying it. A POST request is used to send data to the server to create or update a resource.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d6f1f86-0cf4-4e44-be16-12e9cae9b31d', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain the role of the Dependency Injection (DI) hierarchy and how tree-shakable providers affect bundle size.', N'Senior', N'Angular uses a hierarchical DI system where providers can be scoped to modules or components. By using the providedIn property in the Injectable decorator, services become tree-shakable, meaning they are only included in the final bundle if they are actually injected into a component or service, thus optimizing the build size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1267f519-c45e-4cdd-ba44-12eb500228d6', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix handle errors in the request pipeline?', N'Fresher', N'Phoenix uses custom error views to render user-friendly pages when errors occur, such as a 404 Not Found or a 500 Internal Server Error. These are defined in the application''s error view module.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8207a59-72b2-41ca-8e8c-12ee3cfe926b', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of Spring Boot starters?', N'Intern', N'Starters are a set of convenient dependency descriptors that you can include in your application. They handle all the required dependencies for a specific technology, ensuring compatibility and reducing the complexity of managing library versions manually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'876255a4-f848-4a65-989b-12ef3a5816cc', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Explain the role of the Ember Run Loop in managing application-level performance.', N'Senior', N'The Run Loop batches internal tasks like rendering, binding updates, and promise resolutions into discrete phases. By deferring execution and processing changes in queues, it prevents layout thrashing and redundant computations, ensuring that the browser only performs expensive DOM operations once per frame.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e4b52ab-9bbd-422b-9182-12f05f13ad6b', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between building a custom internal tool and buying a third-party SaaS solution?', N'Middle', N'Building a custom tool allows for perfect alignment with specific business workflows and competitive advantages, but consumes significant engineering resources. Buying a SaaS solution saves time and maintenance effort but often introduces vendor lock-in and may lack the specific custom features required for unique business processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ace0cfc1-dbde-4708-826a-12f111829f1f', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the primary purpose of Webpack in a frontend project?', N'Intern', N'Webpack is a static module bundler for modern JavaScript applications. It takes various assets like JavaScript, CSS, and images, processes them, and bundles them into a single file or a few files that the browser can efficiently load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cf805be-2348-4fe0-aef1-12f5246d06d0', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit achieve ''progressive enhancement'' in its form handling?', N'Senior', N'SvelteKit''s use of the ''use:enhance'' action allows forms to function without JavaScript by using standard browser behavior, then ''upgrades'' them to AJAX-based submissions when JavaScript is available. This ensures the application remains functional for users with restricted network conditions or disabled scripting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b01e3d97-085f-4c5a-8c28-12f6b94d2e5a', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the purpose of the ''Object Header'' in the JVM and how does it affect memory layout?', N'Senior', N'The object header contains metadata such as the mark word, which stores GC status and locking information, and the class pointer, which identifies the object''s type. This header adds a fixed memory overhead to every object, which can significantly impact memory footprint when dealing with large collections of small objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77721b79-4f1e-4901-920e-12f7428ecfde', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What does it mean to perform a ''root cause analysis''?', N'Fresher', N'Root cause analysis is the process of digging past the symptoms of a problem to find the underlying source of the error. It prevents the bug from recurring by addressing why the flaw exists rather than just patching the immediate failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
