INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e8b1546-488a-4377-bfad-12fa6bc8d5bc', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'When is it appropriate to use local component state versus global Redux state?', N'Senior', N'Local state is appropriate for transient UI data, such as input field values or toggle states, that do not need to be shared across the application. Redux state should be reserved for data that is needed by multiple components, requires complex transformations, or must be persisted across navigation sessions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
