INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'256e384e-134e-4c0e-90f3-130249839639', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is a ''sanity check'' when troubleshooting?', N'Fresher', N'A sanity check involves verifying basic assumptions first, such as ensuring the power is on, the internet connection is active, or the correct configuration file is being read. It prevents wasting time on complex deep-dives when the cause is actually something trivial.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
