INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eeb60d95-4287-4e67-8289-13048afd1d8c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you compare two date objects?', N'Fresher', N'Two dates can be compared by converting them into numeric values using date.getTime() method to correspond to their time. Also, the relational operators , >= can be used to compare JavaScript dates. However, the equality operators ==, !=, ===, !== cannot be used to compare (the value of) dates because: * Two distinct objects are never equal for either strict or abstract comparisons. * An expression comparing Objects is only true if the operands reference the same Object. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a944fe6-f848-4cd9-bcb8-130c624648b2', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are the primary architectural benefits of separating Express route definitions from the business logic layer?', N'Senior', N'Separation of concerns ensures that the routing layer only handles HTTP-specific tasks like parsing parameters and sending responses. This makes the business logic easier to unit test in isolation and allows the same logic to be reused across different interfaces like CLI tools or message consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'190df8ed-f4cb-4b5f-b85d-130d92b58725', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the ''sizeof'' operator?', N'Fresher', N'The sizeof operator is a compile-time operator used to determine the size of a data type or a variable in bytes. It is commonly used to ensure portability when allocating memory or performing pointer arithmetic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac3c0566-c609-46fb-b2d5-130ecabfd6ab', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of the Request Body in FastAPI?', N'Fresher', N'The request body is used to send complex data to the server, typically in JSON format. FastAPI uses Pydantic models to define the expected structure of this body, ensuring incoming data is parsed and validated correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'738ae92d-5a49-41c4-a871-13100779555e', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'When should you use the Repository pattern in a Laravel project?', N'Senior', N'The Repository pattern is beneficial when your application needs to abstract complex data access logic, support multiple data sources, or facilitate easier mocking for testing. However, since Eloquent is already an active-record implementation, overusing repositories can lead to unnecessary boilerplate code that hinders rapid development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3c6b43e-8701-4d21-a960-131115c5c1ae', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does ASP.NET Core manage thread pool exhaustion, and what role do ''async all the way'' practices play?', N'Senior', N'Thread pool exhaustion occurs when all threads are blocked waiting for synchronous I/O, preventing the server from handling new requests. ''Async all the way'' ensures that threads are returned to the pool while waiting for I/O operations to complete, drastically increasing the server''s scalability and responsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16b27b41-05b9-4002-bcc6-1312faa2fcf7', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is an ''Isolate'' in Dart?', N'Intern', N'An Isolate is a unit of independent memory and a single thread of execution in Dart. Unlike threads in other languages, isolates do not share memory and communicate exclusively by passing messages, which prevents race conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8b400f7-8d55-40a9-871f-1315496fbc1d', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is a Context object in Gin?', N'Intern', N'The Context object is the most important part of Gin, as it carries variables, manages the flow of a request, and validates JSON. It allows developers to handle HTTP requests and responses by providing helper methods to read input data and send status codes or payloads back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
