INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c45c071-1c84-47f2-aee0-1338dcdabc76', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When faced with an incident where metrics show a sudden drop in success rate but no logs indicate failure, what is your first step?', N'Senior', N'I would analyze the infrastructure ingress and egress traffic to check for silent packet loss, load balancer misconfigurations, or service discovery issues. I would also investigate sidecar proxies or service mesh metrics to determine if requests are being terminated before reaching the application layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7ede0a7-10fc-4fc3-8d5b-13392a6bf5dc', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB achieve horizontal scaling?', N'Junior', N'DynamoDB horizontally scales by automatically partitioning data across multiple servers. As your data grows, DynamoDB splits partitions and distributes them across more physical hardware to maintain performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4f75fda-6b5d-45ff-8ce0-133b3a750be5', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of Migrations in AdonisJS?', N'Intern', N'Migrations are a version control system for your database schema. They allow you to define, modify, and share database table structures using code rather than manual SQL commands.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8720ff4e-fd7a-408e-8acb-133b4a17af91', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why is Next.js good for SEO?', N'Intern', N'Next.js improves SEO because it renders the page content on the server, providing search engine crawlers with a fully populated HTML document. This makes it easier for bots to index the content compared to pages that rely entirely on client-side rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'498b73d1-8b40-411a-8e61-133d4ed1c357', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the difference between an ID and a class selector?', N'Intern', N'A class selector is used to style multiple elements by applying the same style to all items that share that class name. An ID selector is unique and intended to style only one specific element per page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4f3a7b3-4e42-4741-a5fa-13443ad71b2d', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik ensure type safety in a serialized, lazy-loaded environment?', N'Senior', N'Qwik leverages TypeScript throughout the build pipeline to ensure that serialized data maintains its type integrity. Because the framework knows the structure of the data at build time, it can enforce type constraints even when the execution is split across multiple asynchronous chunks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e4643f3-b638-44e2-ae3f-13487ad05e1b', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How do you share state across different handlers in Axum?', N'Junior', N'You can share state by creating a struct to hold your application data and injecting it into the router using the ''with_state'' method. Handlers can then access this shared state by using the ''State'' extractor as a function argument.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a097496-aec1-4d95-b224-1348d9f13c4f', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the CAP theorem and how does it influence database design?', N'Middle', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. Designers must choose which trade-off aligns with their business needs, often prioritizing availability in large-scale distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31112e35-5a98-4a7c-bf58-134d8391500d', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the CSS Box Model?', N'Intern', N'The box model is a fundamental concept where every element is represented as a rectangular box. It consists of four layers: the content area, padding, border, and margin, which determine how space is managed around and inside elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b185bd8-849d-4d5b-bb95-134dd1336e16', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the role of the ''Stream'' trait in Actix?', N'Junior', N'The Stream trait is used when an actor needs to handle a sequence of messages over time. It allows the actor to process data as it arrives, such as reading from a socket or a file stream.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4db54cd5-879e-47fc-8800-1350b69a2f5f', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the ''container'' class in Tailwind CSS?', N'Fresher', N'The container class is a utility that sets an element''s max-width to match the current breakpoint. It is commonly used to center your content horizontally and provide consistent padding on different screen sizes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'656e2164-4535-4256-8a9a-1352b23fe96a', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain the concept of ''Eventual Consistency'' in the context of the CAP theorem.', N'Senior', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. In a partitioned system, choosing availability leads to eventual consistency, where the system ensures that all updates will eventually propagate to all nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3447897c-3f30-42ca-91bd-1357785f7654', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the role of the @RestController annotation in a Spring Boot application?', N'Junior', N'@RestController is a convenience annotation that combines @Controller and @ResponseBody. It tells Spring that the class will handle web requests and that the return value of each method should be written directly to the HTTP response body as JSON or XML instead of being interpreted as a view name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8db96ab2-a925-4d16-a492-135811328701', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of the ''Mapping'' in Elasticsearch and why should dynamic mapping be avoided in production?', N'Senior', N'Mapping defines the data type for each field, which dictates how data is indexed and searched. Dynamic mapping can lead to inefficient field types, such as mapping a large text field as a keyword, which consumes excessive memory and storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21e22440-5528-4438-b08d-135bd6f7d8ba', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you evaluate if a problem has been successfully solved?', N'Fresher', N'I evaluate success by checking if the original requirements are met and if the solution functions correctly without introducing new issues. I also verify that the solution is maintainable and meets the established quality standards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eac7642f-12fc-4a16-bc84-135e57ceda61', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the difference between a ModelForm and a Form?', N'Fresher', N'A Form is a generic class used to validate input and generate HTML forms, while a ModelForm is a subclass that automatically creates a form based on the fields of a specific database model. ModelForms simplify the process of saving data directly to the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e68d24b2-3de3-49ed-860b-13646c7377e5', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Describe the role of ''Witness Tables'' in Swift''s protocol implementation.', N'Senior', N'Witness tables are similar to vtables but specifically map protocol requirements to concrete implementation methods for a given type. They allow the Swift runtime to find and execute the correct function for a specific protocol call, enabling dynamic dispatch across different conforming types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64868c86-a68a-4830-9e91-13664009ff23', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a performance bottleneck when the application CPU usage is low but latency is high?', N'Middle', N'I would investigate potential I/O bottlenecks, such as slow database queries, external API dependencies, or thread contention. I would use profiling tools to examine wait states for individual threads to determine if they are blocked by network calls or lock contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1175e9d0-f208-4912-bb46-1368cd22eba1', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is a covered query in MongoDB?', N'Intern', N'The MongoDB covered query is one which uses an index and does not have to examine any documents. An index will cover a query if it satisfies the following conditions: * All fields in a query are part of an index. * All fields returned in the results are of the same index. * No fields in the query are equal to null Since all the fields present in the query are part of an index, MongoDB matches the query conditions and returns the result using the same index without actually looking inside the documents. Example: A collection inventory has the following index on the type and item fields: This index will cover the following operation which queries on the type and item fields and returns only the item field:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc8f5719-8823-4d1a-bbb3-136bcf59f336', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How do jQuery''s chainable APIs influence the readability and maintainability of large-scale codebases?', N'Senior', N'While chaining provides a concise syntax for common operations, it encourages long, dense lines of code that are difficult to debug or step through with a debugger. In large projects, this leads to ''callback hell'' and makes it harder to isolate logic for refactoring or modularization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3d77226-5ffb-4add-bce7-137241248db9', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the benefit of using jQuery''s method chaining?', N'Intern', N'Method chaining allows multiple jQuery methods to be called on the same set of elements in a single line of code. This reduces the need to re-select the same element multiple times, leading to cleaner and more efficient code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf0a4678-7808-4905-9728-13748a21e0b4', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby handle truthiness?', N'Junior', N'In Ruby, every object is considered ''truthy'' except for the values ''false'' and ''nil''. Everything else, including empty strings, empty arrays, and the number zero, evaluates to true in a conditional expression.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93f091f4-9723-4c39-bc80-1374d3590351', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot handle database connection pooling, and when would you choose HikariCP over alternatives?', N'Senior', N'Spring Boot uses HikariCP as the default pool because it is highly optimized for performance and minimal latency. You should prefer it over alternatives because it employs advanced techniques like concurrent collections and thread-local caching to reduce lock contention in high-concurrency environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecabb2e2-09cf-45b7-940a-1376e6e5577b', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are the trade-offs of using Express''s ''res.sendFile'' versus serving static assets through a reverse proxy like Nginx?', N'Senior', N'Using res.sendFile incurs an overhead on the Node.js process by consuming memory and CPU cycles for file I/O and stream management. Serving files through Nginx is significantly more efficient as it bypasses the Node.js application layer and leverages optimized kernel-level sendfile system calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48b78ebd-8cd0-434f-ac09-137c577d9bde', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you prioritize which technical debt to pay down first?', N'Junior', N'I prioritize technical debt based on its impact on system stability, developer productivity, and the likelihood of future development in that area. Debt that blocks new features or causes frequent production incidents should be addressed before minor refactoring tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
