INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a73b1ad2-2818-447b-8158-1380124361f5', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why is Preact often chosen for performance-sensitive mobile web applications?', N'Middle', N'Preact''s tiny bundle size results in faster download and parsing times, which are critical for mobile performance. Its efficient reconciliation process also consumes less CPU and memory, leading to smoother interactions on lower-end devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdbd9894-d8ae-4535-b1d5-13834c883af7', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is a segmentation fault?', N'Intern', N'A segmentation fault is an error that occurs when a program attempts to access a memory location that it does not have permission to access. It is often caused by dereferencing null pointers or accessing memory outside the bounds of an array.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee54c6cd-4553-45c4-84b7-1383d4f656d1', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'When is it appropriate to use a capped collection?', N'Senior', N'Capped collections are fixed-size collections that automatically overwrite the oldest documents when they reach their size limit. They are ideal for high-throughput logging, caching, or buffering scenarios where you need to maintain a recent history of events without manually managing document deletion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b13df33-0f9e-4e8e-a545-1384ebc78f04', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the role of the database administrator?', N'Fresher', N'A database administrator is responsible for the performance, integrity, and security of the database. Their tasks include managing user access, performing backups, and ensuring the database remains available to users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b505265-c0d1-42d9-8332-1385db67cf51', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why is it often harder to estimate maintenance tasks than new feature development?', N'Middle', N'Maintenance tasks often involve navigating undocumented legacy logic and resolving hidden side effects. Because the root cause of an issue or the ripple effect of a change is not always clear upfront, these tasks carry higher ambiguity and require more exploratory time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edfec125-4f9b-487d-8222-138661b91e4e', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the purpose of a cache, and what is the risk of using it?', N'Fresher', N'A cache stores frequently accessed data in a fast-access layer to improve performance. The main risk is that the cached data may become ''stale'' or outdated if the source information changes and the cache is not properly invalidated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92f3b283-a388-4e67-80b1-1386a21b4633', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit compare to frameworks like React?', N'Junior', N'Lit is a library for building web components using native browser standards, whereas React is a framework that uses its own virtual DOM implementation. Lit components are interoperable with any other framework or even vanilla JavaScript because they are standard web elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
