INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'322cd7a2-9397-4c9d-974d-1387c60870fd', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Does Axum perform synchronous or asynchronous request handling?', N'Fresher', N'Axum performs asynchronous request handling. Because it is built on Tokio, it leverages Rust''s async/await syntax to handle multiple concurrent connections efficiently without blocking threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b857d431-24f3-4213-a607-13883f679b3e', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does bulkheading improve the fault tolerance of a system?', N'Middle', N'Bulkheading involves isolating resources, such as thread pools or memory, for different parts of a system. If one component fails or experiences high latency, the bulkhead prevents the failure from cascading to other areas, ensuring the entire system doesn''t collapse.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44f437b4-1752-4479-a0df-138acff8fcdf', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a data type in a database?', N'Intern', N'A data type is an attribute that specifies the kind of data a column can hold, such as integer, character, date, or boolean. It helps the database enforce data integrity and allocate storage space efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83b8c327-0a53-44d4-82ac-138b64f3608f', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is ''consumer lag'' and why is it a primary operational metric?', N'Senior', N'Consumer lag represents the offset difference between the latest produced message and the last processed message. It is the primary indicator of system health; high lag suggests the consumer cannot keep up with the producer, which could lead to stale data or prolonged processing delays.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'065e181b-9543-41d3-a077-138d23d52357', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why is the Two-Phase Commit (2PC) protocol often avoided in high-scale NoSQL systems?', N'Middle', N'2PC is a blocking protocol, meaning nodes must wait for others to acknowledge, which can significantly decrease availability and performance under network partitions. NoSQL systems often prioritize the CAP theorem''s availability or partition tolerance, opting for eventual consistency instead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'538b8aaf-d706-4279-9aac-138fbd949381', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What are the performance implications of Qwik''s ''lazy loading'' strategy?', N'Middle', N'Because Qwik breaks the application into tiny, granular chunks, it achieves a very small initial bundle size. This results in an almost instantaneous Time to Interactive, as the browser only downloads the code required for the current visible state and immediate user interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23188787-5030-4c38-bd87-1392e8c968b2', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the purpose of the ''cluster'' module?', N'Junior', N'The cluster module allows you to create child processes that share the same server port to take advantage of multi-core systems. This improves performance and reliability by distributing the load across multiple CPU cores.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fbde7e1-7186-48b8-981a-1393dd964001', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is a vector in R and why is it important?', N'Fresher', N'A vector is the most basic data structure in R, which stores a sequence of elements of the same data type. It is essential because almost all data operations in R are vectorized, meaning calculations are performed on the entire vector at once rather than using loops.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'530cb517-06cb-4fb9-a899-1395ddf44903', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does Python''s memory management handle garbage collection?', N'Middle', N'Python primarily uses reference counting, where objects are immediately deallocated when their reference count drops to zero. It also employs a cyclic garbage collector to detect and clean up reference cycles that simple counting cannot resolve. This combined approach balances real-time cleanup with the need to handle complex, self-referential object graphs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
