INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a43a753-a5fc-4152-aae6-139731459649', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain the difference between a Controller and a Service in an AdonisJS application.', N'Middle', N'Controllers are responsible for handling HTTP requests and returning responses, acting as the entry point. Services contain the core business logic, enabling reuse of complex operations across different controllers and keeping the codebase maintainable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7b85dcb-ff11-41c9-94ca-13978a4d9d6e', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the limitations of secondary indexes in distributed NoSQL databases?', N'Senior', N'Secondary indexes often require global coordination or scatter-gather queries across all nodes, which can introduce significant latency and reduce availability. Unlike primary keys, secondary indexes may not be atomic with the underlying data, leading to temporary index inconsistencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
