INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5280ce7e-d77f-47ac-a233-139d5157e213', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'When would you prefer Chi over a more feature-heavy framework like Gin?', N'Middle', N'You would prefer Chi when you want to minimize dependencies and maintain full control over your tech stack. If your team prefers using standard library interfaces and wants to avoid the overhead of a framework that dictates how to handle things like logging or binding, Chi is the superior choice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'514c9f9e-6380-4132-a649-13a130850a36', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle dependency injection compared to traditional framework approaches?', N'Middle', N'Litestar uses a type-hint-driven dependency injection system that allows for both request-scoped and application-scoped providers. By leveraging the type system, it automatically resolves dependencies during the handler execution phase, which promotes cleaner separation of concerns and facilitates easier unit testing by allowing mock dependencies to be injected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
