INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fb265a7-6896-4692-b3e9-13a7dd65abe4', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the impact of boxing and unboxing on the execution pipeline, and how does Generics mitigate this?', N'Senior', N'Boxing forces a value type onto the heap, requiring an allocation and subsequent garbage collection pressure. Generics allow the runtime to create specialized code at JIT time for value types, eliminating boxing and providing type-safe performance by avoiding object-based indirection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
