INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c230e417-891e-4a56-ad77-13aceaa5e7a3', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the difference between a Controller and a Service in Symfony.', N'Middle', N'A Controller is responsible for handling incoming HTTP requests, interacting with the model layer, and returning an HTTP response. A Service is a specialized class designed to perform specific business logic or reusable tasks, keeping the controller thin and focused solely on flow control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd9e8e48-903e-4cc4-8bcb-13ad3a0c2dc9', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between a database migration and a schema file in Rails?', N'Junior', N'A migration is a Ruby class used to define specific changes to the database structure over time, such as creating tables or adding columns. The schema file is a snapshot that reflects the current state of the database structure after all migrations have been applied. While migrations are used to modify the database, the schema file serves as the authoritative reference for the current database layout.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
