INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a8b3537-9b75-4f20-b930-13c31bb0f090', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the risk of ''shotgun debugging'' where you change multiple things at once?', N'Junior', N'Changing multiple things at once makes it impossible to know which change actually fixed the issue, or if the fix was just a coincidence. It often introduces new side effects and leaves the codebase in an uncertain state, making it harder to maintain in the long run.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed4d477d-426a-4f1d-b0de-13c3b2ce4d1c', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the concept of Duck Typing in Python.', N'Middle', N'Duck typing is a programming concept where the type of an object is less important than the methods it implements. If an object behaves like a specific type, such as having a read method, Python treats it as that type regardless of its actual class inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18192f6f-9105-44a2-95e4-13c9e66d5851', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go handle cgo overhead and why is it a concern?', N'Senior', N'Cgo requires a context switch between the Go runtime and the C execution environment, which involves saving the current Go stack and transitioning to a system stack. This transition is expensive compared to native Go function calls and prevents the Go scheduler from preempting the C code. Frequent calls to C functions can lead to significant performance bottlenecks, especially in tight loops or high-concurrency systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c574e06-d376-4193-9c3d-13ca23ca8c96', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix mitigate the risk of ''prop drilling''?', N'Senior', N'Because data is fetched at the route level and accessed via the ''useLoaderData'' hook, any component within that route tree can consume the data directly. This removes the need to pass props through intermediate components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
