INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f66969e6-73a5-4204-bf2d-13cf0d4865a9', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between reflow and repaint', N'Fresher', N'A _repaint_ occurs when changes are made which affect the visibility of an element, but not its layout. Examples of this include outline, visibility, or background color. A _reflow_ involves changes that affect the layout of a portion of the page (or the whole page). Resizing the browser window, changing the font, content changing (such as user typing text), using JavaScript methods involving computed styles, adding or removing elements from the DOM, and changing an element''s classes are a few of the things that can trigger reflow. Reflow of an element causes the subsequent reflow of all child and ancestor elements as well as any elements following it in the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31400ccf-6cb3-4608-b7ad-13cf6f6de862', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does ''concurrency'' mean in database transactions?', N'Fresher', N'Concurrency refers to the ability of a database system to handle multiple transactions simultaneously. Managing concurrency is essential to ensure that simultaneous access does not lead to conflicting data updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'918f17c1-7198-4ea6-9122-13cfa01a566d', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is horizontal scaling, and how does MongoDB achieve it?', N'Intern', N'Horizontal scaling involves adding more servers to a database system to handle increased loads. MongoDB achieves this through a process called sharding, which distributes data across multiple machines, allowing the database to grow beyond the storage or performance limits of a single server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
