INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f15af857-bd1c-42d9-baa5-13d197b19ebc', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing an API, what are the trade-offs between REST and GraphQL?', N'Middle', N'REST is generally simpler to implement and leverages standard HTTP caching mechanisms, making it ideal for straightforward resource-based interactions. GraphQL offers superior flexibility by allowing clients to request exactly the data they need, which reduces over-fetching, but it increases server-side complexity regarding query optimization and security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'206e55fc-b362-4bb5-be90-13d568c57b7b', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Explain the role of the Qwik Loader in the framework''s architecture.', N'Senior', N'The Qwik Loader is a tiny, inline script that intercepts browser events before the application is fully loaded. It maps these events to the corresponding serialized metadata in the HTML and fetches the specific chunks required to execute the logic, facilitating the resumability mechanism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f36ef54-8526-49e8-b5e7-13d5fea9895f', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Is Go case-sensitive?', N'Intern', N'Yes, Go is case-sensitive, meaning that identifiers like ''variable'', ''Variable'', and ''VARIABLE'' are treated as distinct names. Additionally, capitalization in Go determines the visibility of identifiers, where uppercase names are exported to other packages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fe94291-5496-405d-ab3b-13dd333fa93d', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does event-driven architecture influence the schema evolution of messages?', N'Senior', N'In event-driven systems, schema changes must be backward and forward compatible, often requiring the use of centralized schema registries to enforce versioning rules. If a producer breaks the contract, it can cause silent failures across many downstream consumers, making strict schema management a mandatory architectural requirement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac68ea0f-3409-4b4e-a986-13df60ac381a', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How do HTML custom elements interact with the browser''s declarative parsing flow?', N'Senior', N'Custom elements are defined via JavaScript and registered with the browser; once registered, the browser upgrades any matching tags found in the HTML parser. The lifecycle callbacks allow developers to hook into this process to synchronize state, manage shadow roots, and handle attribute changes efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4494f847-52d4-4568-97a4-13e0f5031dd9', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the zero value in Go?', N'Intern', N'When a variable is declared without an explicit initial value, Go assigns it a ''zero value'' based on its type. For example, integers become zero, booleans become false, and strings become empty strings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8baeebcf-e944-46fb-ab81-13e23b73d2be', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the primary benefit of Fiber''s ''CORS'' middleware?', N'Middle', N'The CORS middleware automates the handling of Cross-Origin Resource Sharing headers, which are required for browser-based clients to interact with APIs hosted on different domains. It simplifies security configuration by providing an easy interface to define allowed origins, methods, and headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5c10bd5-1376-4040-a380-13e449a9c283', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is meant by ''Eventual Consistency''?', N'Fresher', N'Eventual consistency is a model where data updates are not immediately reflected across all nodes in a distributed system. The system guarantees that, given enough time without new updates, all copies of the data will eventually match.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f187acc2-633e-47ee-aec6-13e50f0c7095', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the difference between .addClass() and .toggleClass()?', N'Intern', N'The .addClass() method adds a specific CSS class to the selected elements. The .toggleClass() method checks if the class exists; if it does, it removes it, and if it does not, it adds it, which is ideal for interactive UI states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7265fd8d-f094-4d2c-bcee-13e5b3bd5ab0', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What happens to the ''load'' function when navigating from a client-side route?', N'Middle', N'When navigating between routes on the client, SvelteKit executes the load function in the browser to fetch only the necessary data. This avoids a full document refresh and allows the application to stay responsive while updating the page view seamlessly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1593b3e1-111d-46ec-8ab9-13e6b9a0e8c7', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between TRUNCATE and DELETE?', N'Fresher', N'DELETE is a DML command that removes rows one by one and logs each deletion, making it slower and allowing for conditional removal. TRUNCATE is a DDL command that removes all rows from a table at once, is faster, and cannot be used with a WHERE clause.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb4acee4-2f5b-4432-8432-13e95fb9862a', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js handle SEO differently from a standard Client-Side Rendered (CSR) React application?', N'Middle', N'Next.js renders the full HTML on the server before sending it to the client, ensuring that search engine crawlers can index the content immediately. Standard CSR applications often rely on JavaScript execution for rendering, which can lead to incomplete indexing or slower discovery by search bots.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'193e3faa-7103-445b-9131-13ea60dce40b', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What does it mean for Redis to be an in-memory database?', N'Intern', N'Being in-memory means that all data is kept in the server''s main memory (RAM) while the system is running. This allows for sub-millisecond latency compared to traditional disk-based databases that require slower I/O operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89e76c16-fd1f-4212-bdde-13f0f22bf237', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you ensure data consistency in a distributed system following a microservices architecture?', N'Middle', N'I would favor eventual consistency over strong consistency when possible, using an event-driven architecture with message queues to propagate state changes. For cases requiring atomic operations across services, I would employ the Saga pattern to manage distributed transactions via compensating actions if a step in the process fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
