INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34a83168-c387-44f1-95d9-13f91c450319', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When choosing a storage solution, what factors drive the trade-off between SQL and NoSQL databases?', N'Senior', N'SQL databases prioritize ACID compliance and complex relational queries, making them ideal for structured data where consistency is non-negotiable. NoSQL databases prioritize horizontal scalability and flexible schema design, which are essential for high-velocity, unstructured data or rapidly evolving application requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
