INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c23ce1f1-5ae0-4443-acd0-14159f8d1c92', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the advantage of serializing state in Qwik?', N'Intern', N'Serializing state allows the client to pick up exactly where the server left off. It means the browser does not need to re-execute data fetching or initialization logic, saving time and resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4acd780f-221e-4e4e-9a7f-14160543b56d', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the purpose of the ''Abort'' method in Gin?', N'Intern', N'The Abort method is used to stop the execution of the middleware chain. It is typically called when an error occurs, such as a failed authentication check, to prevent the main handler from executing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55dc9b38-9911-4d83-b485-141d1ec3803d', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the benefit of using Redis as a cache for a web application?', N'Junior', N'By storing frequently accessed data in memory, Redis reduces the load on the primary backend database and significantly improves application response times. This allows the system to serve repetitive requests almost instantly without needing to perform expensive disk-based queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7014843-178d-4665-bfc7-141e2a69f809', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is it discouraged to keep large objects in actor state?', N'Senior', N'Actors are designed to be lightweight; storing large objects increases the memory usage of each actor instance, which limits the total number of actors the system can spawn. Furthermore, large state can increase the time required for actor migration or serialization if clustering is involved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e853211-4526-4c67-b008-14219e6fd805', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is unittest in Python? What\''s your approach to unit testing in Python?', N'Fresher', N'A unit testing framework in Python is known as unittest. It supports sharing of setups, automation testing, shutdown code for tests, aggregation of tests into collections etc. The most fundamental answer to this question centers around Python''s unittest testing framework. Basically, if a candidate doesn''t mention unittest when answering this question, that should be a huge red flag. unittest supports test automation, sharing of setup and shutdown code for tests, aggregation of tests into collections, and independence of the tests from the reporting framework. The unittest module provides classes that make it easy to support these qualities for a set of tests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'079e0a38-85b8-4c04-9529-1424b2c195ea', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the purpose of the ''Reflector'' class in NestJS?', N'Middle', N'The Reflector class is used to read metadata attached to classes or methods via custom decorators. It is essential for building logic that depends on configuration provided at the route level, such as checking for specific user roles required to access a protected resource.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44891b24-4614-406c-a0f8-14295d656a27', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask''s error handling mechanism allow for centralized API error responses?', N'Senior', N'Flask allows you to register global error handlers for specific exception types, enabling a uniform JSON response structure across the entire application. This prevents the leaking of stack traces and ensures that clients receive consistent error codes and messages, regardless of where the failure occurred in the stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2e3caaa-2609-416d-b5a4-142b7af05d96', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Can Fastify''s performance be degraded by large schema definitions?', N'Senior', N'Yes, extremely large or complex schemas can increase startup time due to the compilation process. However, once compiled, the runtime cost remains low; the trade-off is a slight increase in boot time for massive API surfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c30f20bd-cdb9-4758-8a68-142ed8d4ff8f', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js differentiate between Static Site Generation (SSG) and Server-Side Rendering (SSR) in terms of data fetching and scalability?', N'Senior', N'SSG generates HTML at build time, allowing for massive scalability via CDN caching, whereas SSR generates HTML per request on the server. SSG is ideal for content that changes infrequently, while SSR is necessary for personalized or highly dynamic data that requires fresh state on every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f895e85-d1db-4abc-9dd6-142fac294f36', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the context API in Preact?', N'Intern', N'The context API provides a way to share values like themes or user authentication status between components without having to explicitly pass props through every level of the component tree. It is designed for global data that needs to be accessed by many components at different depths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad895d45-a546-4fc0-91ed-1432759bb256', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the difference between v-show and v-if directives?', N'Fresher', N'Below are some of the main differences between v-show and v-if directives, 1. v-if only renders the element to the DOM if the expression passes whereas v-show renders all elements to the DOM and then uses the CSS display property to show/hide elements based on expression. 2. v-if supports v-else and v-else-if directives whereas v-show doesn''t support else directives. 3. v-if has higher toggle costs while v-show has higher initial render costs. i.e, v-show has a performance advantage if the elements are switched on and off frequently, while the v-if has the advantage when it comes to initial render time. 4. v-if supports tab but v-show doesn''t support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8315208-25f2-4775-9845-1432926a7b38', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are the advantages of using a Microservice architecture with NestJS?', N'Middle', N'Using microservices allows for independent scaling of services, improved fault isolation, and the ability to use different transport layers like Redis, RabbitMQ, or gRPC. It facilitates development by teams working on separate business domains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74c7d119-8ebe-48fe-885a-1433174cc9d4', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the concept of Facades in Laravel and their trade-offs.', N'Middle', N'Facades provide a static-like interface to classes available in the service container. While they make code cleaner and easier to read, they can lead to hidden dependencies and make testing more difficult if not properly mocked or injected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9c6c22c-a1b5-48bc-9644-14342ab4335d', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the impact of long-running O(N) commands in a single-threaded Redis environment?', N'Senior', N'Since Redis processes commands sequentially, a long-running O(N) command blocks the entire event loop, preventing all other incoming requests from being processed. This can lead to significant latency spikes and timeouts across the entire application if the dataset being accessed is large.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00c5cfd6-5378-439a-84ff-143457259246', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What happens if an Axum extractor fails to retrieve the requested data?', N'Junior', N'If an extractor fails, such as when a JSON body is malformed or a parameter is missing, Axum will automatically return an error response to the client. This prevents the handler function from being executed with invalid input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef9ceadd-29d4-4d0f-99ac-1435b5752fed', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How do you define path parameters in Fastify routes?', N'Fresher', N'Path parameters are defined using a colon prefix in the URL string, such as ''/users/:id''. Fastify automatically extracts these values and makes them available in the request object under the params property.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdf1aa18-9ea6-4e85-a777-143769b8730b', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the ForkJoinPool framework optimize task execution compared to a standard fixed-size ThreadPoolExecutor?', N'Senior', N'The ForkJoinPool uses work-stealing algorithms where idle threads ''steal'' tasks from the queues of busy threads, ensuring better load balancing. This is highly effective for recursive, divide-and-conquer tasks, whereas a standard ThreadPoolExecutor is better suited for independent, long-running tasks where task stealing overhead might outweigh the benefits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15d8f50f-9f7c-470f-a0dd-14378536a6b6', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the ''BEM'' methodology and why is it used?', N'Middle', N'BEM stands for Block, Element, Modifier, a naming convention designed to make CSS code modular, reusable, and easy to understand. It prevents specificity wars by ensuring each class name is unique and describes its function within the component structure. This significantly improves maintainability in large teams where styles are frequently modified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32d76ef9-7090-420e-a414-1438e0b9bb1d', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Why is it generally recommended to keep Rails controllers thin, and how does this affect system testability?', N'Middle', N'Thin controllers follow the principle of single responsibility, ensuring that they only handle HTTP request routing and parameter parsing while delegating business logic to models or service objects. This improves testability because business rules can be unit-tested in isolation without needing to mock complex request or session objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2982305e-b5b6-4605-a444-1439630ececf', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is a clearfix in CSS?', N'Intern', N'A clearfix is a way for an element to clear its child elements automatically without any additional markup. The clearfix property is generally used in float layouts where elements are floated to be stacked horizontally. The clearfix property allows a container to wrap its floated children. Without a clearfix, a container will not wrap around its floated children and will collapse, just as if its floated children had been positioned absolutely. Syntax: Example: Live Demo: CSS Clearfix', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ea29aa1-bf6c-48a9-aede-143bf51c098b', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is your favorite React stack?', N'Intern', N'Even though the tech stack varies from developer to developer, the most popular stack is used in react boilerplate project code. It mainly uses Redux and redux-saga for state management and asynchronous side-effects, react-router for routing purpose, styled-components for styling react components, axios for invoking REST api, and other supported stack such as webpack, reselect, ESNext, Babel. You can clone the project https://github.com/react-boilerplate/react-boilerplate and start working on any new react project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09067851-973a-4c7d-bc76-143ecd75675f', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is a Model in the AdonisJS MVC pattern?', N'Intern', N'A Model represents a single table in your database. It defines the structure of the data and provides methods to perform operations like fetching, creating, updating, or deleting records in that specific table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'557008af-3d68-492e-8adc-14427f7b6f4b', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is an application factory pattern in Flask?', N'Junior', N'The application factory pattern involves creating a function that configures and returns an instance of the Flask app. This approach is preferred for larger applications as it makes testing easier and allows for multiple configurations, such as separate settings for testing and production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd02f6380-5b2c-4e41-ab03-1443910b96a4', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is ''Middleware'' in the Axum framework?', N'Fresher', N'Middleware consists of components that wrap handlers to perform tasks before or after the request reaches the business logic. Common uses include logging, authentication, or modifying headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'faf2bccf-76df-4263-8f68-1447ae672584', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is a sealed class and when is it preferred?', N'Junior', N'A sealed class represents a restricted class hierarchy where all subclasses must be defined in the same package. It is preferred when you have a set of types that you want to check exhaustively using a when expression. This ensures that you handle every possible subclass, making your code more robust.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'420fccc2-5ae2-412e-8713-144d1ebc1d94', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between a stack-allocated variable and a heap-allocated variable in C?', N'Junior', N'Stack-allocated variables are managed automatically by the compiler and have a scope limited to the function they are declared in, meaning they are cleared once the function returns. Heap-allocated variables are managed manually by the programmer using functions like malloc and free, allowing them to persist beyond the function''s scope until explicitly deallocated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3277dcc9-9a3c-4666-a489-144d58e2c4ca', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How would you implement custom error handling for the entire application?', N'Middle', N'You can use the ''@app.errorhandler'' decorator to register functions that catch specific HTTP status codes or exceptions. By defining these centrally, you ensure consistent error responses across the entire API or web interface, improving maintainability and the user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'180a9b55-53c3-48ce-ba2a-1451f18f18be', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the impact of long-lived transactions on scalability?', N'Middle', N'Long-lived transactions hold locks on database rows for extended periods, blocking other transactions and reducing concurrency. In a scalable system, keeping transactions short and granular is essential to avoid resource contention and maintain high throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96a9d371-a6dc-4513-8fe5-14576487c7a9', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the role of the destructor in a C++ class?', N'Junior', N'A destructor is a special member function that is called automatically when an object goes out of scope or is explicitly deleted. Its primary purpose is to clean up resources, such as closing files or freeing heap memory, that were acquired during the object''s lifetime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2938c39-5045-4dfd-8b52-14588979c6aa', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a ''text'' field type?', N'Fresher', N'The text field type is used for full-text content. Data stored in these fields is analyzed, meaning it is broken down into individual terms or tokens to allow for efficient searching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b2a61ed-0c1f-4289-b24f-145b06c66054', N'a2838158-7305-480a-b22b-4dc35776b400', N'How do distributed caches like Redis improve system performance?', N'Middle', N'Distributed caches store frequently accessed data in memory across multiple nodes, reducing the load on primary databases. By serving data from memory, the system achieves significantly lower latency and higher throughput compared to disk-based database queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd76b33d2-ac33-4c56-8745-145ff0c33f6d', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the ''loading=lazy'' attribute affect page performance?', N'Middle', N'The ''loading=lazy'' attribute tells the browser to defer loading of off-screen images until the user scrolls near them. This reduces the initial page load size and bandwidth consumption, leading to faster initial rendering. It is a critical performance optimization for pages with many images located below the fold.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e045f2a4-6100-48ea-a0be-14614f74e69c', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Compare ''Push'' vs ''Pull'' models for real-time data streaming architectures.', N'Senior', N'The push model provides lower latency as data is sent immediately upon arrival, but can overwhelm slow consumers. The pull model allows consumers to process data at their own pace, which improves stability but introduces latency and requires more complex polling logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50781b9e-ac95-4307-bc49-1462281c5054', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does the ''tsconfig.json'' project reference feature improve build performance in monorepo architectures?', N'Senior', N'Project references allow the compiler to treat a monorepo as a graph of independent sub-projects, enabling incremental builds and shared output caching. This prevents the compiler from re-analyzing the entire workspace, drastically reducing build times for large-scale applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
