INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d8a20f9-1974-460d-b58c-1466bb22b1cb', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is a functional component in Preact?', N'Intern', N'A functional component is a simple JavaScript function that accepts props as an argument and returns the UI structure to be rendered. They are the standard way to define components in modern Preact development because they are concise and easy to test.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'236d28ab-1b5a-4ac7-8757-1468150c8716', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the difference between .scss and .sass file extensions?', N'Intern', N'The .scss syntax is an extension of standard CSS and uses curly braces and semicolons, making it easier for developers familiar with CSS to learn. The .sass syntax is the older, indented syntax that does not use braces or semicolons, relying instead on indentation to define blocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
