INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b5bc840-e404-48bf-a0e3-146d1f31bff3', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle memory fragmentation, and what strategies can mitigate it?', N'Senior', N'Redis uses a custom memory allocator, usually jemalloc, which can lead to fragmentation over time due to frequent object creation and deletion. Mitigating this involves tuning the active defragmentation settings in the configuration or periodically restarting instances to reclaim memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15bcbda0-8a9a-4ea2-8abc-14712c32a6d0', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the ''rel=preload'' hint affect the browser''s critical rendering path?', N'Senior', N'Preload informs the browser to fetch high-priority resources earlier than the parser would naturally discover them, improving time-to-first-byte for critical assets. Misusing it by preloading non-essential resources can lead to bandwidth contention and delay the loading of more important elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
