INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ef8ad76-c930-4cfa-9a00-1487403b3572', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Why Use Migrations?', N'Fresher', N'- Version Control: Migrations are text-based, making them ideal for version control systems like Git. - Data Integrity: They help ensure that data remains consistent as the schema evolves. - Collaboration: Simplifies team collaboration and deployment processes. - Adaptability: Migrations can be tailored for different databases, such as PostgreSQL or MySQL. Basic Migration Commands 1. Initial Migration: Generate the initial database schema from models. 2. Apply Migrations: Execute the pending migrations on the database. 3. Migrations Plan: Check the status of migrations. Advanced developers may often require more intricate migration commands and functionalities. Fortuitously, Django offers a versatile array of options to accommodate those needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
