INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2207880a-7db3-44bb-9b16-14946956d663', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'When building a highly interactive dashboard, why might Astro be a better choice than a pure SPA framework?', N'Senior', N'Astro allows you to keep the static, SEO-heavy parts of the dashboard as plain HTML while limiting the heavy interactivity to isolated islands. This results in a smaller initial download and faster startup time for the core application compared to loading a monolithic JS bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f65ec472-d8e8-4020-bcf6-1495212fe93a', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you decide when to stop optimizing a piece of code and move on to the next task?', N'Junior', N'I stop optimizing once the code meets the defined performance requirements and passes all tests. Further optimization should only occur if there is a demonstrated bottleneck or if the code is clearly inefficient enough to impact user experience or system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9230303c-0a89-4332-9c5b-149a7293f65f', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the MVC architectural pattern used in Laravel?', N'Intern', N'MVC stands for Model, View, and Controller. The Model handles the data and business logic, the View manages the user interface and presentation, and the Controller acts as an intermediary that processes user input and updates the Model or View accordingly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87da1d89-644a-458b-ad0f-149bb1bf161c', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s event loop architecture differ from traditional multi-threaded programming models?', N'Middle', N'Dart uses an event-loop based single-threaded model, which simplifies concurrency by avoiding race conditions and locks associated with shared memory. It executes code asynchronously using microtasks and event queues, allowing non-blocking I/O operations without requiring explicit thread synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d55ae6a-efcd-4878-919d-149cacd4817f', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle request scope concurrency without relying on ThreadLocals?', N'Senior', N'Micronaut utilizes a request-context propagation model that captures the state and passes it through non-blocking execution flows. By avoiding ThreadLocals, it ensures that context remains consistent across asynchronous calls and reactive streams without risking memory leaks or cross-thread data contamination.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02d130a9-5969-4faf-a83d-149db8e6d20c', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux handle multiple middleware?', N'Middle', N'Redux processes middleware in a pipeline sequence, often referred to as a chain. When an action is dispatched, it passes through each middleware in the order they were defined before finally reaching the reducer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45ca2516-ddd7-4949-a461-149e043244dd', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What are the trade-offs of using reflection-free frameworks like Micronaut?', N'Middle', N'The primary trade-off is that developers lose some flexibility regarding runtime code generation and highly dynamic bean configuration. However, this is usually offset by significant gains in startup speed, reduced memory usage, and improved maintainability through compile-time error checking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'847b52e7-4218-46dc-8c62-149e9a5f44af', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is an HTTP status code, and how do you set one in Express?', N'Fresher', N'An HTTP status code indicates the success or failure of a client''s request. In Express, you set this using the res.status() method, followed by an optional response method like .send() or .json().', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8aaf9be-7651-4e54-8b04-149f858e7e59', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte differ from frameworks like React or Vue?', N'Intern', N'React and Vue use a virtual DOM to compare state changes and update the UI, which happens at runtime. Svelte operates as a compiler that converts your components into pure JavaScript during the build process, eliminating the need for a virtual DOM entirely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'929c74f1-f083-4ad0-876c-149fa645cd2a', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the role of the Controller in the MVC pattern?', N'Intern', N'The Controller acts as an intermediary between the Model and the View. It receives incoming web requests, processes them, interacts with the model to fetch or save data, and then decides which view to render for the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bcb6cf9-a61b-4f7f-bdf9-14a0c9ffbbaa', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why is it important to keep table statistics up to date?', N'Middle', N'The query planner relies on table statistics to choose efficient execution plans. If statistics are outdated, the planner may make poor decisions, such as choosing a slow join method or a full table scan when an index scan would have been more efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e62e4ca9-eda0-4380-9635-14a15d25dcec', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the trade-off between using buffered and unbuffered channels?', N'Middle', N'Unbuffered channels provide synchronous communication, ensuring both sender and receiver are ready at the same time, which acts as a synchronization barrier. Buffered channels decouple the sender and receiver by allowing a specific number of items to be queued, which can improve throughput at the cost of potential memory usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'339e05c8-63bc-4c26-b7ff-14a2a8b3aadb', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB handle scaling?', N'Intern', N'DynamoDB automatically scales the storage and throughput capacity based on the configured settings or by using auto-scaling. It distributes data across multiple servers to handle high traffic loads seamlessly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbfb6d39-c46b-4bdc-bfec-14a2f46180c5', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you design an observability strategy for a system that spans hundreds of microservices?', N'Senior', N'I would implement a standardized telemetry approach using distributed tracing to map request flows across service boundaries, paired with centralized logging and metric aggregation. This ensures a unified view of system health, allowing for correlation between high-level service latency and specific infrastructure bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c892ee6-cbac-4dcb-b15e-14a42cb06e67', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Why is ''View Transitions'' in Astro considered a performance optimization?', N'Middle', N'View Transitions allow for seamless navigation between pages without a full browser reload. This creates a smoother user experience similar to an SPA while maintaining the benefits of a multi-page application architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f8f33ec-6012-4fd2-9dd8-14a5f3ead277', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Describe the impact of the ''hidden'' attribute on the document''s structure versus CSS display properties.', N'Senior', N'The hidden attribute is semantically equivalent to ''display: none'', removing the element from the accessibility tree and the rendered output. Unlike CSS, it is a declarative HTML state that persists regardless of stylesheet loading, ensuring consistency across different rendering phases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1df39a8a-2df1-4a69-8cea-14a69c5b8cee', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the shorthand syntax for x-bind?', N'Fresher', N'The shorthand for x-bind is a colon. For example, instead of writing x-bind:class, you can simply write :class to dynamically bind CSS classes to an element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44375632-aa2e-416f-a846-14a70fad5058', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is a View in the MVC pattern?', N'Intern', N'The View is responsible for the user interface and presentation layer of the application. It receives data from the controller and formats it into HTML or other formats for the user to see.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5b24bfc-50a2-4855-89da-14a7b4cc7f5b', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the primary benefit of Qwik''s approach to hydration?', N'Fresher', N'The primary benefit is near-instant page load times. By avoiding hydration, Qwik prevents the main thread from being blocked by massive JavaScript execution during the initial page load, resulting in a much faster Time to Interactive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
