INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00f97184-0d8f-482c-bde0-14a88045be90', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the ''layout'' file in Rails?', N'Fresher', N'A layout file provides a common template wrapper for all views in the application, such as the site-wide header and footer. It ensures a consistent look and feel across different pages by defining the shared HTML structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08c50915-812a-42a5-b4e9-14a967685db7', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do you design and maintain a CSS design system for a team?', N'Fresher', N'A design system is more than a component library — it is the single source of truth for visual language, shared between design and engineering. Core layers of a CSS design system: Token structure (CSS custom properties): Lead responsibilities for a design system: * Partner with designers — tokens must map 1:1 with Figma variables. Use a single source (Figma Tokens, Style Dictionary) that exports to both design and CSS formats. * Enforce token usage — Stylelint rules should ban raw color values and magic spacing numbers, forcing developers to use tokens. * Version the design system — treat it like a package; use semantic versioning and a changelog so consuming teams can upgrade safely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67d23455-bfce-49b6-a36b-14a979c54618', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the performance trade-off when using the ''client:load'' directive compared to ''client:idle'' in Astro?', N'Senior', N'The ''client:load'' directive hydrates the component immediately upon page load, which can block the main thread and delay interactivity. ''Client:idle'' waits for the browser to reach an idle state before hydrating, prioritizing the initial page render and improving metrics like Time to Interactive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20689428-6bb6-44b0-b566-14b132d7949b', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing a logging system, how do you balance the granularity of logs with performance and storage costs?', N'Middle', N'Highly granular logs are invaluable for debugging complex issues but consume massive amounts of storage and can impact system performance. The strategy should be to balance verbosity based on the environment, using high-detail logs in development and structured, essential logs in production to optimize costs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
