INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82929e0c-8db9-434a-9dd3-14b5e971087c', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the ''viewport'' meta tag influence the mobile-first rendering pipeline?', N'Senior', N'The viewport meta tag communicates to the browser that the page is optimized for mobile, preventing the browser from applying default scaling that would shrink the layout to desktop dimensions. Without this, the browser might incorrectly calculate layout widths, leading to poor usability and negative impacts on Core Web Vitals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10550764-7d89-4bed-a152-14bb160149b9', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'When is it appropriate to use a content delivery network (CDN) versus an application-level cache?', N'Middle', N'A CDN is used to cache static assets geographically closer to users to reduce latency and bandwidth costs. An application-level cache is used to store dynamic data or computed results closer to the application logic to reduce database load and improve processing speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa8cba49-c156-4cc7-bec3-14bb39eae0f3', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the difference between the ''get'' and ''post'' methods in jQuery AJAX?', N'Junior', N'The GET method is used to retrieve data from a server, where parameters are appended to the URL. The POST method is used to send data to the server, typically for creating or updating resources, and hides the data within the request body.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59f91e3b-5f3b-4123-bffd-14bbd836e475', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the benefit of Axum''s type-safe routing?', N'Intern', N'Type-safe routing ensures that if a handler expects specific data, the framework verifies the request contents at runtime before the handler is invoked. This reduces errors by automatically rejecting malformed requests that do not match the expected structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29ef3405-4593-43ea-b167-14bd07836e53', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a browser engine?', N'Intern', N'The browser engine is to take the HTML, CSS and other code of a web page - the text you can see in the page source or open in a text editor, setting out layouts, page content, and styling - and convert it into what you actually see on screen. The browser engine, rendering engine, and JavaScript engine are all essentially working together to get raw web code into a viewable and usable-form inside your browser. Browser Engines: 1. Gecko: It''s a Mozilla''s browser engine. It is used in the Firefox web browser, the Thunderbird email client, and the SeaMonkey internet suite. Goanna also is a fork of Gecko used in the Pale Moon browser. 2. WebKit: This engine created by Apple for its Safari browser, by forking the KHTML engine of the KDE project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18e3c592-0281-47e3-baab-14c304d936b9', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the main benefit of using Redux DevTools?', N'Intern', N'Redux DevTools allows developers to inspect the state at any point in time and see the history of dispatched actions. It also enables time-travel debugging, which lets you step back and forth through state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8e360fc-caf1-4088-8207-14c49aaf54df', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are Data Annotations?', N'Intern', N'Data Annotations are attributes that can be applied to model properties to define validation rules or metadata. They provide a simple way to enforce requirements like mandatory fields, string length, or data formats directly within the model class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dab4b965-041c-403e-9606-14c4f8c0d0af', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is LiveView?', N'Intern', N'LiveView is a feature in Phoenix that allows developers to build interactive, real-time user interfaces using only Elixir. It maintains a stateful connection between the client and server to update the DOM automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'612197a2-c0ff-4f82-8bc1-14c71afb09e3', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What are the advantages of using Astro for documentation or blog sites?', N'Middle', N'Astro''s built-in support for Markdown and MDX, combined with its static output, makes it ideal for content-heavy sites. It minimizes overhead, ensures high lighthouse scores, and simplifies the workflow for maintaining large collections of text-based content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de747a70-f09f-4565-b041-14c91a81bf66', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'When would you prefer a Multi-Master replication strategy over a Primary-Replica model?', N'Senior', N'Multi-master is useful for globally distributed systems where writes must be served locally to reduce latency. However, it introduces significant complexity regarding write conflict resolution and often requires sacrificing strict consistency to prevent deadlocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04583f8d-887b-4c98-af17-14c9e3f9a057', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the role of ''HTTPException'' in FastAPI?', N'Junior', N'HTTPException is a built-in class used to raise controlled errors that FastAPI converts into HTTP responses. By raising this exception with a status code and detail message, you can easily signal to the client why a request failed while keeping the code clean.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95b78292-79c6-4851-8244-14ca950f052a', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does the Symfony EventDispatcher component work?', N'Fresher', N'The EventDispatcher allows different parts of an application to communicate by dispatching and listening to events. It enables developers to hook into the application''s lifecycle, such as performing actions before or after a controller is executed, without modifying the core logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b68625be-d1ce-479c-9e95-14cde08b200c', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is meant by ''Convention over Configuration'' in Rails?', N'Fresher', N'Convention over Configuration means that Rails makes sensible assumptions about how things should be named and structured, so developers do not have to write manual configuration files. By following these naming conventions, the framework automatically understands how different parts of the application, such as models and controllers, relate to each other.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e2db1cc-36a1-413a-a800-14cfbf39a7cc', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of the Django ''AppConfig'' class?', N'Middle', N'The AppConfig class allows you to configure specific settings for an app, such as its name, verbose name, or custom startup logic. It is the designated place to register signals or perform initialization tasks when the Django application starts up.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c631505c-f638-42da-a888-14d0fa3a89ef', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does the ''Lock'' component manage concurrency in a distributed system, and why is this necessary for database integrity?', N'Senior', N'The Lock component uses external stores like Redis or databases to manage mutual exclusion across multiple application instances. It prevents race conditions during critical operations, such as processing payments or updating inventory, where concurrent access could lead to inconsistent data states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
