INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ea68e21-b8db-4565-a7a0-14d64f30e2ac', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a readonly property?', N'Junior', N'A readonly property is a member of an object or class that can only be assigned during initialization. Once set, it cannot be modified, which helps enforce immutability for certain parts of your application data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fd53f55-67b4-4901-b6ff-14d7d725d0af', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why is it important to consider the access pattern before designing the DynamoDB schema?', N'Senior', N'DynamoDB is a non-relational database optimized for specific query paths defined by the schema. Unlike SQL, where you can add indexes to support new queries later, changing access patterns in DynamoDB often requires a complete table redesign or data migration. Designing for access patterns up-front is mandatory for sustained performance and cost-effectiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
