INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8a6f451-83c2-4e7e-b9a1-14e3b81a89f9', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of the @Singleton annotation in Micronaut?', N'Fresher', N'The @Singleton annotation indicates that only one instance of the annotated class should exist within the application context. The framework creates this instance the first time it is requested and reuses it for all subsequent injection points.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad5fa68d-734c-4dd8-81d5-14e45f741381', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does the ''Cell'' type differ from ''RefCell'' in terms of safety and use-cases?', N'Senior', N'''Cell'' provides interior mutability for types that implement the ''Copy'' trait by using direct replacement, which avoids the overhead of runtime borrow checking. ''RefCell'' is required for types that do not implement ''Copy'' or require dynamic borrow verification at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6ab3f15-99d8-4359-bdd8-14e66d88a3d1', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are the security implications of using Lucid''s automatic query sanitization?', N'Middle', N'Lucid uses parameterized queries by default, which effectively eliminates the risk of SQL injection. This removes the need for manual escaping and provides a secure-by-default interface for database interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
