INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e216d122-7bd4-4f56-9706-14ec06afd55a', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar utilize Pydantic or Msgspec for data handling?', N'Middle', N'Litestar leverages these libraries to perform automatic validation and serialization of request and response bodies based on type annotations. This ensures type safety and reduces the need for manual data transformation logic within route handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8355b8c6-3e32-4b80-8c71-14ecad893194', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the primary architectural purpose of a ''Dead Letter Queue'' (DLQ)?', N'Senior', N'A DLQ acts as a repository for messages that cannot be processed successfully after multiple retries. It allows developers to isolate problematic messages for analysis and manual intervention without blocking the main message processing pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbcd2b20-41b9-4bac-9293-14ed50fe9462', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Does Alpine.js require a build step?', N'Intern', N'No, Alpine.js does not require a build step. You can include it via a simple script tag in your HTML file and start using it immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'895e7423-e9a3-4646-9c3c-14f42005ae6a', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does ''Module Resolution'' strategy affect the interoperability between CommonJS and ESM in TypeScript?', N'Senior', N'The module resolution setting determines how the compiler locates type definitions and modules on disk. Mismatches between these settings and the actual runtime environment can lead to ''module not found'' errors or runtime crashes due to the way different systems handle default imports and exports.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37606043-4af5-4b87-b867-14f534e9713e', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Discuss the memory model implications of Kotlin Coroutines regarding context switching and stack management.', N'Senior', N'Kotlin coroutines are cooperative and stackless, meaning they do not map 1:1 to OS threads and do not require separate thread stacks for suspension points. Instead, they use a state machine generated by the compiler to capture local variables, significantly reducing memory footprint and context switching overhead compared to preemptive threading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'690298cb-4c9c-4b7e-a838-14f9d5ccdbb3', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the basic types available in TypeScript?', N'Intern', N'TypeScript provides an assortment of basic types for different kinds of data, such as numbers, strings, boolean values, arrays, tuples and more. Common Basic Types in TypeScript - Boolean: Represents true/false values. - Number: Applies to both integer and floating-point numbers. - String: Refers to textual data. - Array: Offers a flexible way to work with structured data. - Tuple: Enables the definition of arrays with a fixed number of elements, each potentially of a different data type. - Enum: Provides a set of named constants such as days or colors. - Any: Offers a dynamic type, which can be used to bypass type-checking. It''s typically best to be avoided, as it defeats the purpose of using TypeScript, which is primarily focused on static typing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4367701-012d-4aab-a2ad-14faf4ddb42a', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit ensure type safety across the server-client boundary?', N'Middle', N'SvelteKit automatically generates TypeScript types for your load functions, form actions, and page data based on your file structure. This provides end-to-end type safety, ensuring that the data returned from the server matches the schema expected by your components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71d69fb4-dc84-4db5-a687-14fbbd78606a', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS''s Validator service improve system reliability compared to custom validation logic?', N'Senior', N'The Validator service enforces strict schema definitions, ensuring that incoming data meets expected types and constraints before it reaches the business logic layer. Centralizing validation prevents ''data corruption'' bugs and ensures that downstream services can trust the integrity of the data being passed to them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'724653a9-2ed8-4fb4-b84e-14fccdb69def', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How do GiST and GIN indexes differ in their use case and performance characteristics?', N'Senior', N'GiST indexes are balanced trees suitable for geometric data and custom types, offering good performance for both updates and lookups. GIN indexes are inverted indexes optimized for multi-valued data like arrays or full-text search, providing faster search performance but slower updates due to the cost of index entry maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'752bf53c-f0f4-466c-b0b8-14feaa08402d', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the advantage of using asynchronous message queues in a high-scale system?', N'Senior', N'Asynchronous messaging decouples the producer from the consumer, allowing the system to handle bursts of traffic by buffering requests. It improves system resilience by ensuring that a failure in a downstream service does not immediately cascade to the upstream caller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a3ea011-a656-4635-8f40-14ff203552cd', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the challenges of maintaining state consistency in an event-driven architecture?', N'Senior', N'Event-driven systems often rely on eventual consistency, which introduces challenges in handling distributed transactions and read-after-write conflicts. Implementing patterns like Saga or using transactional outbox ensures atomicity, but they increase architectural complexity and require robust handling of duplicate events and out-of-order processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e7149e6-a705-4888-b305-1501ea4610ee', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the difference between a Route and a Controller?', N'Intern', N'A Route defines the endpoint URL and the HTTP method, while a Controller contains the actual code that executes when that endpoint is hit. The route points to the controller method to handle the logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e80abda-2c57-401d-95e0-1502e60cc889', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How do you achieve graceful shutdown in an ASP.NET Core application, and why is it important for consistency?', N'Senior', N'Graceful shutdown involves signaling the application to stop accepting new requests while finishing pending tasks before the process terminates. This is crucial for maintaining data consistency, ensuring database transactions complete, and preventing abrupt termination errors in distributed environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
