INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1e8dd07-7e0c-4d28-88a5-15197b1ab44f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does setTimeout(fn, 0) actually behave, and what are its timer accuracy limitations?', N'Fresher', N'setTimeout(fn, 0) does not execute fn immediately or even after exactly 0 milliseconds. It schedules fn as a macrotask — it will not run until: 1. The current call stack is empty. 2. The entire microtask queue is drained. 3. The event loop picks the next macrotask. Additionally, browsers enforce a minimum timer delay of 4ms after 5 nested setTimeout calls (the "clamping" rule, per the HTML spec). In background tabs, browsers further throttle timers to 1000ms (1 second) to save CPU. Node.js has a minimum delay of 1ms but also subject to the event loop''s libuv timer phase overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
