INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f3944f1-1c73-45d7-8df6-151b58647141', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the impact of using Django''s ''lazy'' loading for related models, and how does it affect memory usage?', N'Senior', N'Lazy loading defers database queries until the moment the data is actually accessed, which saves resources if the data is not needed. However, it can inadvertently trigger many small queries if objects are accessed in a loop, potentially exhausting memory or causing database connection saturation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fac952e7-4c84-47a1-8fcb-151c23752a6f', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What role does caching play in achieving high scalability?', N'Middle', N'Caching stores frequently accessed data in high-speed memory to reduce the load on primary databases and downstream services. By serving data from the cache, the system significantly lowers latency and allows the backend to handle a much higher volume of requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2aed83ee-6435-4771-80c3-151e8bfaab42', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember''s router handle nested states?', N'Middle', N'The Ember router treats URLs as a hierarchy, where each route can have child routes that inherit the parent''s model context. This hierarchical structure allows the UI to update partially, keeping parent components rendered while changing only the content within the nested outlets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
