INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b2c5eb2-fdc5-4d84-9c9d-152eb351ff2a', N'075b8862-431c-4678-9767-f55359758a4a', N'Can you explain the Vue.js lifecycle hooks?', N'Middle', N'Vue.js organizes lifecycle events into distinct stages, each linked to a specific lifecycle hook. These hooks enable developers to execute custom logic at crucial points during a component''s life cycle. Vue.js Lifecycle Stages 1. Initialization: The component is being set up. 2. Mounting: The component is being added to the DOM. 3. Update: Data in the component undergoes changes. 4. Destruction: The component is being removed from the DOM. Lifecycle Hooks 1. beforeCreate: Occurs at the earliest step in initialization, before data observations and initializations are in place. 2. created: After the component''s data and events are set up, this hook permits you to work with the component synchronously. 3. beforeMount: Just before the component is added to the DOM, execute logic. 4.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
