INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a4cc0ae-f20d-4ccc-a74c-154a59e90991', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust''s ownership model eliminate the need for a garbage collector while ensuring memory safety?', N'Senior', N'Rust enforces strict ownership rules at compile time through the borrow checker, which tracks the lifetime of every variable. By tying memory deallocation to the scope of the owner, the compiler automatically inserts drop calls, ensuring memory is freed predictably without runtime overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c406cfa6-2b38-4405-89b6-154d9cb5acd5', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the benefit of using the chi.Mux object?', N'Intern', N'The chi.Mux object is the central router instance. It acts as the container for all your routes, middleware, and configuration, making it the entry point for your HTTP server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5ae5cb1-70c0-4e5e-bfae-154e31d4d7cd', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the benefit of using Fastify''s ''reply.hijack()'' in a high-concurrency environment?', N'Senior', N'Hijacking allows a developer to take full control of the raw Node.js stream, bypassing Fastify''s standard response serialization and lifecycle. This is useful for proxying or streaming large datasets where the overhead of JSON serialization would be detrimental to memory usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc0c1a3b-ab1d-4f14-9160-154f067494cc', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Can you define multiple middleware for a single route in Gin?', N'Junior', N'Yes, Gin allows you to pass multiple middleware functions as arguments when defining a route or a group. These functions will be executed in the order they are provided.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6139fb9d-8189-48a4-a501-1551647cf25d', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What role does the Partition Key play in the physical distribution of data?', N'Senior', N'The partition key is hashed to determine which physical partition stores the data. A poor choice of partition key results in data skew, where one partition grows larger or receives more traffic than others. Proper distribution is critical to ensuring the service can scale horizontally across the underlying infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5134138-36b7-49fb-a45f-155166a2f2a3', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'Why is it important to define requirements before starting a task?', N'Fresher', N'Defining requirements ensures that the final result aligns with the actual needs of the user or system. It prevents wasted effort on features that are not necessary and helps in planning the steps required for completion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f72bdeac-b67a-4568-b040-1554e1457d19', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Does Tailwind CSS include pre-designed components?', N'Fresher', N'Tailwind CSS does not include pre-designed components like cards or modals by default, as it focuses on providing the building blocks for your own custom designs. However, the Tailwind team offers a separate product called Tailwind UI, which provides professionally designed, copy-pasteable component examples.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'387cfe00-d512-46d1-874f-1555863095de', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Explain the architectural trade-offs of Preact''s lack of a Fiber-like reconciliation engine.', N'Senior', N'Preact uses a synchronous, recursive diffing algorithm which is faster for small-to-medium component trees but can block the main thread during large updates. Unlike React''s Fiber, which supports time-slicing and interruptible rendering, Preact prioritizes initial load speed and bundle size over long-task concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3d6f6c6-bd56-4bb9-a6c2-1558cdc3717a', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the ''updated'' lifecycle method?', N'Intern', N'The updated method is called after the component''s DOM has been updated and rendered. It is the perfect place to perform actions that require access to the rendered DOM elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8538e9cc-6332-43f9-adaf-1558e3ee076a', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is ''DRY'' in the context of programming?', N'Junior', N'DRY stands for ''Don''t Repeat Yourself,'' a principle aimed at reducing repetition of software patterns. In Rails, this is achieved by using features like helpers, partials, and model concerns to keep code modular and maintainable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4aa73e34-59bf-45e1-a2bc-1559c76508bd', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you decide between building a new solution or using an existing library?', N'Intern', N'I weigh the complexity of the requirement against the time and cost of maintaining a custom solution. If an existing library is well-supported, secure, and solves the problem efficiently, it is usually better to use it than to reinvent the wheel.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74739219-8b45-453c-83b9-155ba0af3b94', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the role of ''lifespan'' in Litestar?', N'Fresher', N'The lifespan defines the startup and shutdown logic of the application. It is used to initialize resources like database connections or cache clients when the server starts and clean them up gracefully when the server stops.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd99e5500-83cd-431c-9e9c-155bacdc784b', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the memory management differences between PHP 7 and PHP 8''s internal object structures.', N'Senior', N'PHP 7 introduced a significant refactoring of internal structures, moving toward a more compact representation of values and ZVALs to reduce memory fragmentation. PHP 8 further optimized these internal structures by introducing improvements like tagged pointers and more efficient heap allocation strategies, which collectively lower the overhead for object instantiation and function calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5205ea37-9aee-418f-ba30-155d8e947c2e', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What happens if you try to mutate a prop directly inside a child component?', N'Junior', N'Directly mutating a prop is discouraged because props are intended to be read-only from the perspective of the child. If you need to change a prop value, you should use events to notify the parent to update the data instead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1de56dd-2323-4a65-9db4-155e0dc0cc6e', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Why is ''Clock Skew'' a significant concern for observability and distributed systems?', N'Senior', N'Clock skew can cause events to appear out of chronological order in logs and traces, making incident reconstruction extremely difficult. It can also cause issues with distributed locking mechanisms and TTL-based cache entries, requiring protocols like NTP or PTP for synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a44e6e6-f22f-45a9-9250-155e8a9df88e', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why might a team choose a simple solution over a technically superior but complex one?', N'Fresher', N'Simplicity reduces the mental overhead for the team, lowers the risk of hidden bugs, and makes the system easier to onboard new members. A technically superior but complex solution might be overkill for the current problem and introduce unnecessary technical debt.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
