INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3771f44-5d38-42f9-be76-1566baa06ba2', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'When should you use Webhooks instead of polling?', N'Middle', N'Webhooks should be used when you need near real-time updates and want to avoid the overhead of constant client-side polling. Polling wastes resources and introduces latency, whereas Webhooks push data to the client only when an event occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'743bd3e2-7ac3-4c29-ab46-1566da07cf09', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Why are mutable default arguments considered a dangerous practice in Python?', N'Middle', N'Mutable default arguments are evaluated only once at the time the function is defined, rather than every time the function is called. This causes the same object to be shared across all calls to the function, leading to persistent state changes that often cause unexpected bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'080fb17e-97bf-430f-bc8c-156a2b9b0d7e', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are Sass operators, and how are they used?', N'Middle', N'Sass operators allow for mathematical operations like addition, subtraction, multiplication, and division directly within your stylesheets. They are particularly useful for fluid layouts, calculating relative units, and generating color variations dynamically based on a base value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f148feb-926d-4886-a11e-156aa8de2447', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How do you evaluate if Tailwind is the right choice for a high-performance, design-system-heavy enterprise application?', N'Senior', N'Evaluation should focus on the team''s ability to manage a shared configuration, the need for rapid UI development, and the performance benefits of JIT-generated CSS. If the application requires a highly unique, non-standard visual language that changes constantly, the maintenance cost of the Tailwind configuration might outweigh the utility benefits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56e2e2fb-9047-4820-b684-156bf9346f0f', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle query parameters?', N'Fresher', N'Fiber provides methods on the Context object to retrieve query string parameters from the URL. These can be fetched individually by key or parsed into a map for easier access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dd55b89-45f7-445c-9833-156dcbd186e8', N'4c000000-0000-0000-0000-000000000005', N'What is the difference between optimistic and pessimistic locking?', N'Middle', N'Pessimistic locking prevents others from accessing a record while it is being updated, which avoids conflicts but can lead to deadlocks. Optimistic locking allows multiple users to read and update, checking for conflicts at the time of commit, which is generally better for high-read systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'692ecf8b-fb1d-444c-ae93-15720ea180a2', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach troubleshooting a third-party API integration that is returning inconsistent errors?', N'Middle', N'I would implement robust request and response logging to capture the exact payload and headers sent to the provider to see if the errors correlate with specific inputs. I would then verify if the provider has documented rate limits, downtime, or known issues, and implement a circuit breaker pattern to prevent the issues from cascading into our own system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b965b2e5-3d41-4181-b3ee-1572fdfda152', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of the render method in Lit?', N'Intern', N'The render method is where you define the component''s template. It returns a template result that Lit uses to update the component''s shadow DOM whenever its state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c864ec96-501e-4270-b9ad-1573d54340bf', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why is concurrency control necessary?', N'Fresher', N'Concurrency control is needed to manage multiple users accessing or modifying the database simultaneously. It prevents data corruption and conflicts by ensuring that transactions do not violate integrity rules when running in parallel.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f97cb6e9-c61b-43fd-a63c-157413dd5f61', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js handle data fetching caching?', N'Junior', N'Next.js builds upon the native fetch API to provide a powerful caching mechanism. It automatically caches data requests during the build or request process, allowing you to configure revalidation times to keep your content up to date.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26a8e3a2-1d17-481f-9e9d-1577927be6eb', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle clock drift in a distributed system, and why does it matter?', N'Senior', N'Redis relies on local system time for key expiration and RDB timestamps, so severe clock drift can cause keys to expire prematurely or break replication synchronization. In distributed environments, it is critical to use NTP to keep clocks synchronized to prevent these inconsistencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f6d0ce0-fe1d-4117-b5db-1577eafc65c8', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the trade-offs between the G1 Garbage Collector and the ZGC in terms of latency and throughput.', N'Senior', N'G1 is designed for high throughput with predictable pause times by partitioning the heap into regions, making it suitable for large heaps. ZGC focuses on ultra-low latency by performing almost all work concurrently with application threads, though this often results in a higher CPU overhead and slightly lower peak throughput compared to G1.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5034950d-ba16-41b5-bbb7-157853a20041', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the ''Qwik Loader'' and what is its primary function?', N'Middle', N'The Qwik Loader is a tiny piece of JavaScript, usually inlined in the HTML, that acts as the entry point for interactions. Its job is to listen for browser events, find the relevant chunk of code associated with that event, and download and execute that chunk immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0228c883-83d5-47b8-8f1f-1579c84430a9', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut support reactive programming models natively?', N'Senior', N'Micronaut is built on a reactive foundation, providing first-class support for Project Reactor, RxJava, and Kotlin Coroutines. Its non-blocking HTTP client and server are designed to handle streams of data asynchronously, preventing thread blocking and improving system throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a867c540-af01-4d74-a958-157b3a00f6f7', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the ''calc()'' function improve CSS maintainability?', N'Middle', N'The ''calc()'' function allows for performing mathematical operations directly within CSS, making it possible to mix different units like percentages and pixels. This reduces the need for hardcoded values and allows for more flexible layouts that adapt to varying screen sizes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5b11663-2013-4584-affe-157c4a72fb10', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the benefit of Astro''s file-based routing?', N'Intern', N'Astro uses a file-based routing system where the file structure inside the pages directory determines the URL path of the website. This makes it very intuitive to organize pages and understand the site architecture just by looking at the folder structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49c0f283-29e0-4beb-aecb-157e81d608d0', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix manage state compared to client-side frameworks like Next.js?', N'Middle', N'Remix encourages keeping state on the server and synchronizing it through loaders and actions. This reduces the need for complex global client-side state management, as the server acts as the single source of truth for the application''s data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'020e121d-d920-455b-8476-157ea2931d7c', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you estimate the number of piano tuners in a major city?', N'Intern', N'I would estimate the total number of households, the percentage of households that own a piano, and how often a piano requires tuning. By calculating the total number of tunings per year and dividing by the number of tunings one person can perform annually, I can derive a reasonable estimate for the number of tuners required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6bda4fc-0749-446a-b1cf-158091d7c995', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain CSS position Property?', N'Fresher', N'* absolute, place an element exactly where you want to place it. absolute position is actually set relative to the element''s parent. if no parent available then relatively place to the page itself (it will default all the way back up to the element). * relative, means "relative to itself". Setting position: relative; on an element and no other positioning attributes, it will no effect on it''s positioning. It allows the use of z-index on the element and it limits the scope of absolutely positioned child elements. Any child element will be absolutely positioned within that block. * fixed, element is positioned relative to viewport or the browser window itself. viewport doesn''t changed if you scroll and hence fixed element will stay right in the same position.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0c970e7-d2d5-4d07-88a3-15839cb473e7', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does tail call optimization (TCO) work in Scala, and what are its limitations?', N'Middle', N'TCO allows the compiler to reuse the current stack frame for recursive function calls, preventing stack overflow errors. The limitation is that it only applies to direct tail recursion where the final action of the function is the recursive call, and it cannot be used with methods that are overridable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8239c75-1c22-439b-8702-15843bd270f0', N'4c000000-0000-0000-0000-000000000005', N'What is a service discovery mechanism?', N'Middle', N'Service discovery allows services in a dynamic environment to automatically find and communicate with each other without hardcoding IP addresses. It typically involves a registry where services announce their presence and health status.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd55a187-5489-4399-b57b-15862a66634c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is documentation a critical design decision?', N'Fresher', N'Documentation serves as a roadmap for future developers and helps maintainers understand the ''why'' behind specific design choices. It reduces knowledge silos and ensures that the system can be supported long-term by different team members.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd09c40d5-f45c-49da-8096-158c4d4a8e54', N'954a0331-deff-4399-b588-96f39fec001d', N'What is metadata rewriting?', N'Intern', N'Metadata rewriting is the process in which the compiler converts the expression initializing the fields such as useClass, useValue, useFactory, and data into an exported variable, which replaces the expression. Remember that the compiler does this rewriting during the emit of the .js file but not in definition files( .d.ts file).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'495fa4d3-5149-48d4-97b2-15909e4f0895', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How do you implement rate limiting in a Hono application?', N'Middle', N'Rate limiting is implemented by creating a middleware that checks the client''s IP or identification token against a shared store, such as a KV store or Redis. If the threshold is exceeded, the middleware returns a status code of 429, preventing the request from reaching the route handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e21b3838-cce4-4e43-a40c-15916d04047d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is callback() function in javascript?', N'Intern', N'A callback function is a function passed into another function as an argument, which is then invoked inside the outer function to complete some kind of routine or action. Example: Key points: * Callbacks can be named or anonymous functions * They enable asynchronous and non-blocking code * Overusing nested callbacks leads to "callback hell" — solved by Promises or async/await *Note: callbacks are often used to continue code execution after an asynchronous operation has completed — these are called asynchronous callbacks.*. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ea78e99-a95b-47f3-95fe-1591f254c336', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Can Fiber handle static files?', N'Intern', N'Yes, Fiber provides built-in middleware to serve static files like images, CSS, or JavaScript files. This allows the backend to act as a file server in addition to processing API requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b168f64-b7dc-48bd-98ac-159210e2170a', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of the ''Stack'' and the ''Heap'' in Rust?', N'Fresher', N'The stack stores data with a known, fixed size that is added and removed in a Last-In-First-Out order, while the heap stores data of unknown or dynamic size. Rust uses ownership rules to decide when to allocate data on the heap and when to clean it up automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5d2d195-4b31-4526-94e2-159277862288', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Describe the ''Write-Ahead Log'' (WAL) and its role in durability.', N'Senior', N'The WAL ensures durability by recording all changes to a durable log file before they are applied to the actual data structures. In the event of a crash, the system replays the log to recover the state and ensure no committed data is lost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
