INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d180f36-43ce-492b-a2c2-15965ec1f73f', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are the trade-offs of using SvelteKit''s ''ssr: false'' configuration?', N'Middle', N'Setting SSR to false turns the application into a Single Page Application (SPA), which simplifies server logic and hosting requirements. However, this sacrifices SEO performance and the initial ''time to content'' speed, as the browser must download and execute the entire JavaScript bundle before rendering any content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
