INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'496d2996-7db0-420b-b43f-1598ec59b346', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the default port Gin runs on?', N'Fresher', N'By default, Gin runs on port 8080. However, this can be easily changed by passing a different address string to the Run method when starting the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28e87803-7e66-4c74-adf2-159a47bdf301', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt''s route middleware architecture differ from traditional Vue Router navigation guards?', N'Senior', N'Nuxt middleware provides a structured, tiered approach (global, named, and inline) that integrates seamlessly with the server-side data-fetching lifecycle. Unlike standard Vue Router guards, Nuxt middleware can execute on the server during the initial request, allowing for server-side redirects or authentication checks before the page is ever sent to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c896a00-a917-4e50-82d3-159aeae87b3f', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the architectural difference between a Phoenix ''Controller'' and a ''LiveView'' in terms of request lifecycle.', N'Senior', N'Controllers follow the standard request-response lifecycle where each request is stateless and terminates after the response is sent. Conversely, LiveView maintains a persistent process throughout the lifecycle of the view, allowing the server to maintain state and push updates to the client for the duration of the page session.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e497e36-1e08-4622-b824-159be2e71bf6', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind approach browser compatibility?', N'Fresher', N'Tailwind generates standard CSS that is compatible with all modern browsers. Because it relies on standard CSS features, it does not introduce browser-specific quirks beyond what standard CSS already handles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3358d648-fa18-4393-bc68-15a37a7905cc', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you react when you realize you will miss an estimated deadline?', N'Fresher', N'I would communicate the delay as early as possible with the reasons for the change and a plan to mitigate the impact. It is crucial to be transparent about the status, explain what has been accomplished, and provide a revised, realistic timeline for completion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e63950b-16c3-4d52-809d-15a7cac894b5', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the best practice for error handling in a RESTful Flask API to ensure consistent client responses?', N'Senior', N'Implement a centralized error handler using the app.errorhandler decorator or a custom error handler function registered on the blueprint level. This ensures that all exceptions return a standardized JSON structure with appropriate HTTP status codes, preventing the exposure of stack traces to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b83a4048-88df-4d9c-adbe-15a8450cfb19', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach a task where the requirements are intentionally vague?', N'Intern', N'I would ask clarifying questions to understand the goals and the desired outcome. I would then create a draft proposal or a simple mockup of my understanding and share it with the stakeholder to confirm that I am moving in the right direction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fa151a2-c4ea-40f4-a4a9-15a8722cee3b', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How does verifying your assumptions help in debugging?', N'Intern', N'Engineers often make incorrect assumptions about how a component works or how data flows through a system. Explicitly testing your assumptions through logs or observation often reveals that the problem is not where you initially thought it was.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'570e2127-b433-4197-8643-15a8ade57efa', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What determines the optimal shard size in an Elasticsearch cluster?', N'Senior', N'Optimal shard size typically ranges between 10GB and 50GB depending on the use case, balancing the number of shards against index maintenance overhead. Smaller shards lead to more overhead for the master node, while excessively large shards make rebalancing and recovery operations slow and resource-intensive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10c3f6d9-80a3-40ab-b8b5-15acab509cc5', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How can you handle different HTTP methods in a single route?', N'Junior', N'You handle different methods by passing a ''methods'' argument to the @app.route decorator. Inside the function, you can check ''request.method'' to execute specific logic depending on whether the request is a GET, POST, or another verb.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'035977b8-b5fd-4b87-8f51-15ae62e05536', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing an API, why should you use standard HTTP status codes instead of returning custom codes inside the response body?', N'Junior', N'Standard HTTP status codes are recognized by browsers, proxies, and load balancers, allowing them to handle errors appropriately. Using custom codes inside the body forces clients to parse the payload just to understand if the request succeeded, which is inefficient and non-standard.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ef470c5-2e4f-4112-ab3c-15af0ef383e1', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does GPU acceleration work in the context of CSS animations?', N'Middle', N'GPU acceleration is triggered by animating specific properties like ''transform'' and ''opacity'' that do not require layout or paint recalculations. By moving these operations to the GPU, the browser can handle animations more smoothly, offloading the work from the main thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e7334f5-aa40-43d6-afbd-15b0c065ccfa', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does the ''Bulkhead'' pattern prevent resource exhaustion in a microservices environment?', N'Senior', N'The bulkhead pattern isolates resources, such as thread pools or connection pools, for different parts of a system so that a failure in one service component does not consume resources required by others. This compartmentalization ensures that the failure of a non-critical service does not take down the entire system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'421dfa5a-385a-464f-aa08-15b40e963269', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you evaluate if a design is ''good''?', N'Intern', N'A good design is typically simple, maintainable, scalable, and meets the stated business requirements. It should be easy to understand for other engineers and flexible enough to accommodate future changes without requiring a complete rewrite.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b3ebb2e-3d8b-408b-a24e-15b741396ebf', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Explain the role of the ''Search Thread Pool'' and how to identify if it is saturated.', N'Senior', N'The search thread pool executes search requests across shards. Saturated pools result in rejected tasks, which are visible in node statistics, indicating that the cluster lacks the CPU capacity to handle the current query volume.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86167abb-431f-414a-b023-15b75242b192', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is technical debt, and why is it sometimes an acceptable design choice?', N'Intern', N'Technical debt occurs when a team chooses a quick, sub-optimal solution to meet a tight deadline instead of a cleaner, long-term design. It is acceptable if it allows for rapid market entry, provided the team plans to refactor the code later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5704753e-3d6f-4a78-82da-15b87f64b5f1', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the impact of Lit''s ''dirty-checking'' mechanism on property updates?', N'Senior', N'Lit uses strict equality checking to determine if a property has changed before triggering an update. This prevents unnecessary re-renders when a property is set to the same value, acting as a critical performance optimization for complex UI trees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'699d01d9-3ef3-4535-a5ef-15b8e1339a8b', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a composite primary key?', N'Junior', N'A composite primary key is a primary key that consists of two or more columns. It is used when a single column is not sufficient to uniquely identify a record, but the combination of multiple columns can.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd10705c-268c-4fd6-bff5-15bb01b78cb4', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the ''Request Scope'' in NestJS?', N'Intern', N'Request scope refers to the lifetime of a provider where a new instance is created for every incoming request. This is useful for services that need access to request-specific data like user headers or session info.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'232ffdd8-1954-4db7-b72c-15bd9b438ed1', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does the ''TracePoint'' API affect application performance in production environments?', N'Senior', N'TracePoint hooks into the Ruby interpreter to monitor events like method calls and class definitions, which introduces significant latency as it intercepts and evaluates code execution flow. Enabling it in production can cause severe performance degradation, as it disables many of the VM''s internal optimizations and method cache shortcuts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06bff418-c1e9-48c8-baae-15bebc5f975f', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the benefit of using an ER diagram?', N'Intern', N'An Entity-Relationship (ER) diagram is a visual representation of the entities, attributes, and relationships within a database system. It helps designers and developers understand the structure of the data before implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3db4bb2c-97b0-4027-94d5-15bfea401664', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between MVC and Web API?', N'Intern', N'MVC is primarily designed for building web applications that render HTML views to the browser. Web API is designed for building services that return data, typically in JSON or XML format, to be consumed by client applications like mobile apps or SPA frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f83b78b3-827d-4209-9f96-15c0596b0354', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Why is Micronaut considered cloud-native?', N'Intern', N'Micronaut is cloud-native because it is specifically designed to run efficiently in containerized environments like Kubernetes and serverless platforms like AWS Lambda. Its fast startup and low memory footprint make it ideal for scaling in the cloud.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66dcbafe-9f34-49a1-9180-15c0935a015b', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do you handle responsive design in Sass?', N'Junior', N'You can use mixins to define media queries, which allows you to keep the responsive logic grouped with the element it affects. This makes your responsive code much easier to manage compared to keeping all media queries at the bottom of a large CSS file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02a820a9-e1f7-4bdb-86c1-15c096281a08', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the difference between an API Gateway and an Ingress Controller?', N'Senior', N'An Ingress Controller primarily manages cluster-level traffic routing and external access to Kubernetes services at the L7 level. An API Gateway is a more feature-rich solution that includes cross-cutting concerns like authentication, transformation, and rate limiting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c957763-3623-4c3d-9df5-15c217b7506f', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Does Go have a pointer system like C?', N'Fresher', N'Yes, Go has pointers, but they are safer than those in C. Go supports pointer arithmetic only through the unsafe package, and it does not allow arbitrary memory access, which helps prevent common bugs like buffer overflows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'915cc08e-0ecf-438f-bed6-15c31227d4d2', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Explain the difference between a Component and a Controller in modern Ember.', N'Middle', N'Components are responsible for the UI, encapsulation, and local state, while Controllers act as a bridge between the route model and the template. In modern Ember, Controllers are primarily used to manage query parameters and actions that persist across transitions within the same route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0613817-c2df-40d9-847f-15c39f13ffc8', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are ''Borrowing'' and ''References'' in Rust?', N'Fresher', N'Borrowing allows you to access a value without taking ownership of it, using references denoted by an ampersand. This enables multiple parts of code to read data without needing to duplicate it, while still adhering to strict safety rules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6378a7c-b6d2-43f9-bb5c-15c496d67ebf', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does the ''promise'' object represent a deferred computation in R?', N'Senior', N'A promise is an internal object consisting of an expression, an environment, and a value that is initially empty. It is the mechanism that implements lazy evaluation, storing the context of the call until the value is requested, which allows for complex control flow without immediate execution overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'283f3d83-d8d6-4d73-8d30-15c721b9ac4d', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a database engine in MySQL?', N'Intern', N'A database engine, or storage engine, is a software module that the database uses to perform CRUD operations on data. MySQL supports different engines, such as InnoDB, which provides transaction support and row-level locking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2a9d276-1a36-44bb-a98c-15c935b69260', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the main trade-off of using Sass in a large-scale project?', N'Middle', N'While Sass improves development speed and code organization, it requires a build step that can increase complexity in the CI/CD pipeline. Additionally, if the project relies too heavily on features like deep nesting or complex mixins, it can result in a bloated, hard-to-debug CSS bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'662ab712-161d-41a0-8095-15c9b2a2bc4c', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the trade-offs of using polymorphic associations in Rails?', N'Middle', N'Polymorphic associations allow a model to belong to more than one other model on a single association, providing great flexibility for shared features like comments or images. However, they prevent the use of database-level foreign key constraints, which can lead to data integrity risks if not managed carefully at the application level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a753cea-618e-4234-8cd4-15cc3ce2075e', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS achieve ''fine-grained'' updates compared to frameworks like Vue?', N'Middle', N'While Vue uses a reactive system, it often relies on a Virtual DOM for sub-component updates. SolidJS bypasses the Virtual DOM entirely, mapping reactive signals directly to specific DOM elements, which ensures that only the affected text nodes or attributes are mutated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd28d78bd-4b72-4883-8080-15ccb217a3c3', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the impact of the ''suspend'' modifier on the function signature at the JVM level?', N'Senior', N'At the JVM level, the compiler transforms a suspend function by adding an additional ''Continuation'' parameter to the method signature. This parameter acts as a callback mechanism to handle the resumption of the coroutine, which alters the function''s binary signature and necessitates specific handling by interoperating Java code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6af7411-7fb1-4d01-896e-15ce5b28365e', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the common data types supported by MongoDB?', N'Fresher', N'Common types include String, Integer, Boolean, Double, Min/Max key, Array, Timestamp, and ObjectId. These types are specified by the BSON specification used by the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28ee7da2-560b-4081-b0ad-15d101093d2b', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Describe the function of the C linker.', N'Middle', N'The linker is responsible for combining multiple object files generated by the compiler into a single executable or library. It resolves external references by matching function calls and variable uses to their corresponding definitions in other object files or libraries, ensuring the final program has all necessary dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f15c658-fcbd-4a9d-8879-15d1f3da1890', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is reconciliation in React?', N'Intern', N'Reconciliation in React is the process through which React updates the DOM to match the virtual DOM. When a component''s state or props change, React creates a new virtual DOM tree and compares it with the previous one. This comparison process is called "diffing." React then updates only the parts of the actual DOM that have changed, making the updates efficient and fast. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3dea9029-c13c-4139-96b3-15d26026f4ab', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain the role of the ''config'' directory.', N'Junior', N'The config directory holds configuration files for various parts of the framework, such as database connections, authentication, and session settings. It provides a centralized place to manage application-wide settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
