INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'954780d8-ff73-4b56-9ea3-15d64e4d34c0', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a Dirty Read in database transactions?', N'Fresher', N'A dirty read occurs when a transaction reads data that has been modified by another concurrent transaction but not yet committed. If the first transaction rolls back, the second transaction is left with invalid data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
