INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57ef4618-6a7f-4095-b828-15da56de0b93', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the impact of ''tailrec'' on JVM bytecode?', N'Senior', N'The ''tailrec'' modifier instructs the compiler to perform tail-call optimization, replacing recursive function calls with a simple iterative loop in the generated bytecode. This prevents StackOverflowErrors for deep recursion while maintaining the readability of a recursive algorithm.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25bc286b-f72c-4887-bd8b-15dc704184fe', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'When would you prefer Hono over a batteries-included framework like NestJS?', N'Middle', N'You would choose Hono when performance, low cold-start latency, and deployment flexibility are the primary requirements, such as in edge computing. NestJS is better suited for large-scale enterprise applications that require a rigid structure, dependency injection, and a broad set of pre-built integrations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b22e050-acfd-4c50-b366-15dd23bf18f8', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What are the implications of Echo’s ''Bind'' functionality on memory allocation and performance during high-throughput JSON processing?', N'Senior', N'Echo''s Bind method uses reflection to map request bodies to structs, which introduces CPU overhead during serialization. For extremely high-throughput systems, bypassing reflection in favor of manually written decoders or using code-generated binding can significantly reduce memory allocation and GC pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
