INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7115393a-ee4c-424d-ae63-15e8248f0b73', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the primary trade-off when using Alpine.js for complex, data-heavy state management compared to a framework like React?', N'Middle', N'While Alpine.js is excellent for local UI state, it lacks a robust, centralized state management ecosystem or complex lifecycle hooks required for highly dynamic, data-intensive applications. As application complexity grows, the lack of strict structure and the reliance on inline logic can lead to maintainability challenges compared to the component-based architecture of React.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
