INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf15b6ad-4ec5-4743-bcc3-15f9b0702f3a', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How would you approach troubleshooting a system that intermittently fails and cannot be easily reproduced?', N'Intern', N'To troubleshoot intermittent issues, focus on gathering data through increased logging or monitoring to identify patterns in when the failure occurs. Look for correlations with system load, time of day, or specific user inputs that might trigger the instability. By establishing a baseline of normal behavior, you can better identify the environmental factors that contribute to the non-deterministic error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0dfec336-7dc6-4abb-9387-15fadad4ff15', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is a tuple?', N'Junior', N'A tuple is a collection of values of different types grouped together into a single compound type. They have a fixed length and are useful for returning multiple values from a function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9677a468-82eb-4665-b0ad-16020701b5a4', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the benefit of breaking a large problem into smaller tasks?', N'Junior', N'Breaking down problems makes them easier to understand, estimate, and track. It allows for better progress visualization and helps identify potential blockers early, reducing the risk of being overwhelmed by a single large task.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea38e97f-1d62-4021-92ef-160a17d23a0d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs of centralized logging versus distributed logging in a microservices architecture?', N'Middle', N'Centralized logging provides a single pane of glass for monitoring and troubleshooting, which is essential for distributed systems. The trade-off is the significant cost and complexity of the logging pipeline, which must be scaled to handle the aggregate throughput of all services, potentially becoming a performance bottleneck itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ea36f7a-8aaa-4fca-be59-160a81259a2f', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the difference between GSI and LSI?', N'Fresher', N'A GSI can have a different partition key than the base table and can be created or deleted at any time. An LSI must share the partition key with the base table and can only be defined when the table is created.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b0e04a5-b071-4c36-8643-160b1fa993a2', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the function of the NestJS Execution Context, and how does it assist in writing polymorphic guards and interceptors?', N'Senior', N'The Execution Context provides a unified abstraction over different transport layers, such as HTTP, WebSockets, or RPC. It allows guards and interceptors to access the underlying request object or arguments in a type-safe manner, enabling the creation of reusable logic that functions identically regardless of whether the request originated from a REST endpoint or a message queue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ac49f69-56b4-43b9-813e-160d71288ad1', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is an interceptor in the context of NestJS?', N'Intern', N'An interceptor is a class annotated with the @Injectable() decorator and implements the NestInterceptor interface. An Interceptor is function that can be used to intercept incoming requests to a NestJS application and perform some sort of manipulation before the request is handled by the route handler. This can be useful for things like logging, authentication and so on. An Interceptor has a set of useful capabilities which are inspired by the Aspect Oriented Programming (AOP) technique. Aspect Oriented Programming is a programming paradigm that aims to increase modularity by allowing the separation of cross-cutting concern. Interceptors make it possible to: Binding extra logic before / after method execution: An Interceptor can execute logic before and after a method is executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6368445-f181-4d6d-9eb7-1610d160f98c', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the purpose of a CDN in a distributed system?', N'Middle', N'A Content Delivery Network (CDN) caches static content like images and scripts on edge servers located geographically closer to the end user. This reduces latency and offloads traffic from the origin server, improving the overall user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97b1118e-5882-4391-a2cf-161268ec7e29', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you debug an issue where a background job is failing silently without throwing clear errors?', N'Middle', N'I would review the job queue configuration and ensure that stdout and stderr for the background process are being captured correctly. I would also add logging at every major milestone of the job process to pinpoint exactly where it terminates before completion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73bc026b-1cdb-4fca-bb2e-1612701a4716', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the role of the Symfony Validator component?', N'Intern', N'The Validator component provides a set of constraints to check the validity of data before it is processed or saved. It is commonly used to ensure that user input meets specific criteria such as email format, string length, or required fields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
