INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56823f42-3807-4d88-a5c5-161ce6ca1c1a', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is a Reducer and what is its role?', N'Fresher', N'A reducer is a pure function that takes the current state and an action as arguments and returns a new state object. It determines how the application state changes in response to the actions sent to the store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e038895-0f58-498d-b03f-161e9115289a', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Can you explain what is meant by "TypeScript is a superset of JavaScript"?', N'Junior', N'TypeScript is often described as a "superset of JavaScript" because every valid JavaScript code is also a valid TypeScript code. TypeScript is designed in a way that it fully embraces existing JavaScript syntax and functionality. This ensures a smooth transition for developers wishing to adopt or migrate to TypeScript. Key TypeScript Features On Top of JavaScript - Type Definitions: TypeScript introduces static typing through type annotations. These are optional, enabling gradual adoption for existing codebases that might not need them. - Newer JavaScript Features: TypeScript extends JavaScript syntax, providing support for the latest ECMAScript standards more effectively through its compiler, even when the underlying JavaScript engine might not support them yet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47281c4d-daaf-41cc-a26b-16211e6b66d8', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the role of ''Factories'' in Micronaut?', N'Middle', N'Factories are classes annotated with @Factory that provide a mechanism for creating beans that are not managed by component scanning. They are useful for exposing third-party libraries or complex object configurations as injectable beans.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd39d5803-f0fc-4d28-afbc-16260dc5b7f3', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does the Twig template engine differ from standard PHP templates?', N'Junior', N'Twig is a secure, flexible template engine that uses a more concise syntax than standard PHP. It provides features like automatic output escaping to prevent XSS attacks, template inheritance, and filters that simplify data manipulation in the view layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec41e261-61cc-45f2-beef-162764f573d1', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Describe the lifecycle of an Ember Route.', N'Middle', N'The route lifecycle begins with the model hook, where data is fetched, followed by setupController to prepare the state, and finally the rendering phase. It provides hooks to manage transitions, handle error states, and ensure dependencies are resolved before a route fully activates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc95330d-3802-4208-ba82-1628e83f4dca', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel implement the MVC architectural pattern?', N'Fresher', N'Laravel follows the Model-View-Controller pattern by separating the application logic into three distinct layers. Models handle data and database interactions, Views manage the user interface presentation, and Controllers act as the intermediary that processes incoming requests and returns appropriate responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26d97913-09ad-4d70-ad2e-1628f975eb28', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What architectural role does the ''Controller'' play in modern Ember apps where components are becoming the primary UI unit?', N'Senior', N'In modern Ember, controllers are increasingly relegated to being thin bridges between the route''s model and the template. They are primarily used for storing UI state that needs to persist during a route transition, such as query parameters, rather than holding heavy business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f6df204-f7ff-4d8e-8e89-162c2f9dd267', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the primary purpose of Nuxt.js in frontend development?', N'Intern', N'Nuxt.js is a framework built on top of Vue.js that simplifies the development of web applications by providing features like server-side rendering, static site generation, and automatic routing. It helps developers create performant applications with a structured architecture out of the box.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57489113-cde4-4206-a858-162d7d03ffb7', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the role of the ''VNode'' (Virtual Node) architecture in scaling a cluster?', N'Senior', N'VNodes allow a single physical node to hold multiple small partition ranges across the hash ring. This facilitates faster rebalancing when adding or removing nodes, as the workload is distributed across many smaller segments rather than a few massive ones, leading to more uniform cluster utilization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ae3c0df-85c3-49a2-9201-16306aff677e', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the effort required to implement a new security compliance requirement across distributed services?', N'Senior', N'I audit the current state of security controls against the new requirements to identify the delta. I estimate the time needed for implementation per service type, accounting for testing, auditing, and potential performance impacts caused by additional encryption or validation overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34a1343c-6b54-476a-929f-1630745e2b55', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What are microservices and how do they impact scalability?', N'Middle', N'Microservices break a large application into smaller, independent services that communicate over a network. This allows teams to scale specific parts of the application independently based on their individual resource demands rather than scaling the entire monolith.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'376ac5cb-85c2-4031-8292-16348acfb2f7', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How do ''Generics'' in Rust compare to template metaprogramming in C++?', N'Senior', N'Both use monomorphization to generate specialized code, but Rust generics are constrained by trait bounds that ensure type safety before the code is even instantiated. This provides a more predictable and readable error-reporting mechanism compared to the often cryptic compiler errors associated with C++ template expansion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'617af694-83c5-4ca5-bc5d-163845f08749', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the function of an ARIES-based recovery algorithm?', N'Senior', N'ARIES (Algorithm for Recovery and Isolation Exploiting Semantics) uses a three-pass approach—analysis, redo, and undo—to restore the database to a consistent state after a crash. It identifies the state of the system at the time of failure, replays all changes in the log, and rolls back any transactions that were in progress but not committed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb6fc0c8-8de5-4986-b954-163b5ba7b87d', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the purpose of x-transition?', N'Junior', N'The x-transition directive provides an easy way to apply CSS transitions to elements when they are shown or hidden. It automatically adds and removes specific classes during the enter and leave phases of an element''s lifecycle, allowing for smooth animations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62ed27a7-b7eb-42cf-b59a-163effed6d1e', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the difference between authentication and authorization, and why is this distinction important in microservices?', N'Middle', N'Authentication verifies the identity of a user, while authorization determines what resources that identity can access. In microservices, separating these concerns allows for centralized authentication via an identity provider while delegating granular authorization to individual services or a policy engine, reducing the risk of unauthorized access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f51839c8-c033-449d-b931-1641e27ce95b', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the function of a view in PostgreSQL?', N'Fresher', N'A view is a virtual table based on the result set of an SQL query. It does not store physical data itself but provides a simplified or restricted representation of the underlying tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c906e7e-3d4f-4cd1-91d3-1643f0b7a29f', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Can SvelteKit be used to build a static website?', N'Intern', N'Yes, by using the static adapter, SvelteKit can pre-render your entire application into static HTML, CSS, and JavaScript files. This allows the site to be hosted on simple file servers or CDNs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e5684f8-25b6-45de-947f-1643f41f43c6', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Describe the relationship between Actix-web and the Tokio runtime.', N'Senior', N'Actix-web runs on top of the Tokio runtime, which provides the underlying asynchronous I/O primitives and timer services. Actix-web specifically leverages Tokio''s multi-threaded executor to manage its own pool of worker threads efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c662f8bd-28ce-41ed-adf6-16485c3a1465', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is a View Model?', N'Intern', N'A View Model is a class designed specifically to hold the data required by a specific view. It separates the data used for display purposes from the domain entities, ensuring that the view only receives the data it needs to render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a84d7987-995a-4789-8f31-1649871c3763', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Are there limitations to how much code can be lazy-loaded in Qwik?', N'Junior', N'While Qwik is very aggressive with lazy-loading, developers must ensure that code intended for lazy-loading is properly marked with the dollar sign syntax. If code is not properly decoupled, it may be bundled with the main entry point, reducing performance benefits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f07477db-4402-4270-954a-164a086404fb', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of the Show component in SolidJS?', N'Fresher', N'The Show component is a control flow utility used for conditional rendering. It efficiently adds or removes elements from the DOM based on a boolean condition provided via its props.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c44d6c6b-7d00-44ea-9804-164c64a90454', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does the Symfony Cache component improve application performance, and what are the trade-offs of using different cache adapters?', N'Middle', N'The Cache component reduces the need for expensive operations, such as database queries or complex calculations, by storing results in memory or filesystem adapters. While in-memory adapters like Redis or Memcached provide the fastest retrieval, they are volatile and memory-constrained, whereas filesystem adapters are more persistent but significantly slower due to disk I/O latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'418fdaf2-83eb-4fe9-8610-164d460b236c', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the benefits of using off-heap memory in Java applications, and what are the risks?', N'Senior', N'Off-heap memory reduces the impact of long GC pauses by keeping large data structures outside the scope of the garbage collector. However, it requires manual memory management, which increases the risk of memory leaks and makes the application more vulnerable to native memory corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'544ef8ee-1135-4d81-ac0c-164d91c4868c', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a join in MySQL?', N'Intern', N'A join is a method used to combine rows from two or more tables based on a related column between them. It allows you to query data spread across different tables as if it were a single set.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbafd323-f04e-4a18-9e19-1650c7096121', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What does it mean for a framework like Hono to be ''runtime-agnostic''?', N'Intern', N'Being runtime-agnostic means that the framework is not tied to a specific JavaScript engine like Node.js. It can execute on any environment that supports standard Web APIs, allowing the same codebase to run on Cloudflare Workers, Fastly Compute, or standard servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
