INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'009a7b7e-bf90-4199-a7c8-165b63a1ee24', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the primary trade-off when choosing between synchronous and asynchronous communication between services?', N'Junior', N'Synchronous communication is easier to implement and provides immediate feedback, but it creates tight coupling and can lead to cascading failures if one service is slow. Asynchronous communication decouples services and improves system resilience, but it introduces complexity in handling eventual consistency and error tracking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e090921-a2a4-475c-bfdf-165dc131f1f2', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Explain how jQuery''s internal cache system works.', N'Middle', N'jQuery uses an internal object map, often referred to as the data cache, to store metadata and event handlers associated with DOM elements. This avoids attaching data directly to the DOM nodes, which helps prevent memory leaks in older browsers and allows for easier cleanup of event listeners.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10eda0af-ca0c-4e3e-8c16-1662d833f96b', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the mechanism of Django''s database connection pooling and how to scale it.', N'Senior', N'Django opens a new connection for every request and closes it afterward by default, which can lead to connection exhaustion under high load. Scaling this requires external connection poolers like PgBouncer, which sits between the application and the database to maintain a pool of warm connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c64e1916-3a8f-40a5-8c7d-166526a16bd0', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the trade-offs of using Synchronous versus Asynchronous replication in a high-availability architecture?', N'Senior', N'Synchronous replication ensures zero data loss by requiring the primary to wait for standby confirmation, which increases latency and impacts write availability if the standby fails. Asynchronous replication provides higher performance by not waiting for the standby, but introduces a window of potential data loss during a primary failover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
