INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8edb9ff0-4047-407f-bb0b-1669bd207c51', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why does the microtask queue have priority over the macrotask queue in the event loop execution model?', N'Senior', N'The microtask queue processes promises and other immediate continuations to ensure that state updates and asynchronous operations finish before the next rendering or I/O cycle. Prioritizing microtasks prevents race conditions between the application state and the browser''s UI layout tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
