INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1603d073-9944-4452-abc0-16704ba5806a', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using synchronous and asynchronous communication in microservices?', N'Junior', N'Synchronous communication is easier to reason about and provides immediate feedback, but it creates tight coupling and risks cascading failures. Asynchronous communication decouples services and improves resilience, but makes the system harder to debug and introduces eventual consistency challenges.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4040664b-c5e6-44d9-bd5c-16719a37fd14', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the C preprocessor handle macro expansion compared to function calls, and what are the architectural trade-offs?', N'Senior', N'Macros perform textual substitution before compilation, potentially leading to code bloat and issues with operator precedence, but they avoid the overhead of function call stacks. Functions provide type safety and binary modularity at the cost of the stack frame setup and potential branching penalties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30820345-8c33-4f2f-97af-1674ab04a9da', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is data modeling in Cassandra ''query-first''?', N'Junior', N'In Cassandra, you design your tables based on the specific queries you need to run, rather than normalizing data as you would in a relational database. This allows for optimized read paths since joins are not supported, ensuring that complex data retrieval is performant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82e143be-1451-42a8-a76a-1679d2db46e2', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a cluster index and a non-cluster index?', N'Junior', N'A clustered index determines the physical order of data in the table, meaning the table can have only one. A non-clustered index creates a separate structure that points to the data rows, allowing multiple non-clustered indexes per table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f69ec49-c22f-4910-bad9-167ed529377d', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'In a high-concurrency environment, how does Fiber''s request context management differ from standard Go practices?', N'Senior', N'Fiber''s context objects are pooled and reused to prevent frequent heap allocations. Because these objects are recycled immediately after the request handler finishes, any reference to the context outside of the handler scope will result in race conditions or memory corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
