INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71d908f6-ec19-46f1-8bf6-1686660024b7', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the scope of a variable?', N'Intern', N'The scope of a variable refers to the part of the program where the variable is accessible. Variables can have global scope, accessible throughout the program, or local scope, accessible only within the block or function where they are defined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34a2649e-8cf7-4a84-ab39-1686c3302eca', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Explain the concept of ''Eventual Consistency'' in the context of Redis replication.', N'Senior', N'Redis replication is asynchronous, meaning the master returns a success to the client before the write is propagated to replicas. This creates a window of time where replicas might serve stale data, necessitating architectural considerations if strict read-after-write consistency is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
