INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5e6e64a-3eb2-4285-917a-168ca3f6869f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript handle ''readonly'' properties?', N'Middle', N'The ''readonly'' modifier prevents a property from being reassigned after its initial declaration. It provides compile-time safety to ensure data immutability within your application. Note that it is a shallow check, so nested objects may still be mutable unless explicitly marked as read-only as well.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
