INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'833d055d-e42f-4754-b006-169bd0c74390', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What are the trade-offs of using asynchronous processing for scalability?', N'Middle', N'Asynchronous processing allows a system to offload time-consuming tasks to background workers, improving response times for the end user. The trade-off is increased system complexity, as you must handle message queues, eventual consistency, and potential failures in background jobs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
