INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd96c6b28-0d66-48ec-a474-169e23701d16', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does the ''Atomicity'' property ensure that partial updates do not happen?', N'Middle', N'Atomicity treats a transaction as a single ''all-or-nothing'' unit of work. If any part of the transaction fails, the entire set of operations is aborted, and the database state remains as if the transaction never started.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'291f1771-7a03-42a6-a138-169e38af8c38', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of ''Generics'' and why are they important for reusable components?', N'Middle', N'Generics allow you to create components or functions that work with a variety of types rather than a single one, while still maintaining full type safety. They enable the creation of reusable logic where the input and output types are linked, preventing the need to rely on the ''any'' type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
