INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7daf149-f4cf-4fe3-b760-16a4d508ae9d', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Describe how Ruby handles memory management and the specific challenges posed by its generational garbage collector.', N'Senior', N'Ruby uses a generational, incremental mark-and-sweep garbage collector designed to reduce pause times by focusing collection on ''young'' objects. The challenge lies in managing long-lived objects that survive multiple cycles, which can lead to heap fragmentation and require periodic major collections that stop the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4917edf7-7f5e-470b-a1d0-16a92145a03e', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt 3''s ''Island'' architecture work?', N'Senior', N'Nuxt Islands allow developers to isolate complex or interactive components into separate server-rendered units that operate independently of the main page bundle. This reduces total client-side JavaScript execution by only hydrating the ''islands'' that require interactivity, rather than the entire page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ae85b36-043b-4815-ba1f-16a9c9caac25', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you decide between a monolithic and a microservices architecture for a new project?', N'Middle', N'I look at the team size, the complexity of the domain, and the need for independent deployment cycles. A monolith is often better for early-stage products to maintain velocity and simplicity, while microservices should be considered when team size scales or when specific parts of the system require different scaling or technology stacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7964aadd-9544-440d-a74b-16ac25edfb0f', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a Flask session and how is it used?', N'Fresher', N'A session in Flask allows you to store information specific to a user across multiple requests. It uses a signed cookie to keep the data secure on the client side, enabling features like user login states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6ac2083-902a-43ca-bf2d-16b02b69c547', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the limitations of Redis Transactions compared to RDBMS transactions?', N'Middle', N'Redis transactions allow for grouping commands, but they lack rollback capabilities; if a command fails during execution, the preceding commands are not reverted. Additionally, Redis transactions do not support strict isolation levels like serializable or repeatable read found in relational databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db9d790c-af97-4b92-aef0-16b0888dd27b', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When a project has a tight deadline, how do you decide what to cut?', N'Junior', N'I collaborate with the product owner to identify which features are essential for the MVP and which can be deferred to a later release. I prioritize core functionality that delivers the most value while ensuring the remaining features are built with high quality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d1e9d4a-b4cf-4c6c-a5f7-16b14fa0ff72', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the Elasticsearch heap size influence garbage collection and system stability?', N'Senior', N'The heap stores in-memory structures like field caches and query results; if it is too small, the system suffers from frequent, long garbage collection pauses. However, if the heap exceeds 32GB, the JVM loses compressed object pointers, leading to inefficient memory usage and potential performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7c98c7e-434e-4da9-81ca-16b239940905', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the concept of a ''circuit breaker'' state transition?', N'Middle', N'A circuit breaker transitions between Closed (request flows normally), Open (request fails immediately to save resources), and Half-Open (a few test requests are allowed through to see if the service has recovered). This lifecycle automates the process of handling and recovering from service failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f99f7815-36c5-45cd-8d35-16b5000991e5', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are the benefits of using ''enums'' in Dart over constant integers or strings?', N'Middle', N'Enums provide type safety and represent a fixed set of named constants, preventing invalid values from being passed to functions. They also support member methods and properties, making them more powerful than simple constants and improving the overall maintainability of domain logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcb10aed-b844-4001-b237-16b77a1fc5fd', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between the b and strong tags?', N'Intern', N'Both tags make text bold, but they have different meanings. The strong tag indicates that the text has strong importance or urgency, while the b tag is purely for styling and does not imply any extra importance to screen readers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b4756fe-6f54-4fcc-a1bd-16b7b52545a8', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach securing an internal service-to-service communication?', N'Middle', N'Implement mutual TLS (mTLS) to ensure that only authenticated services can communicate, while also enforcing network policies to restrict traffic flow. This creates a zero-trust environment where the network location of a service is not sufficient for authorization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'575c6dad-5201-4362-860a-16bb8897430f', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why might a query not use an index even if one exists on the columns in the WHERE clause?', N'Middle', N'The optimizer might ignore an index if it determines that the cost of reading the index plus the random disk access to fetch rows is higher than a sequential scan. This often happens if the query selects a large percentage of the table''s rows, making the index lookup less efficient than a full scan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06b6cedb-183e-466d-8fdd-16bf311c2196', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why might a developer choose a lower isolation level?', N'Junior', N'A developer might choose a lower isolation level to increase system performance and concurrency. High isolation levels require more locking, which can slow down the database and increase the risk of deadlocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27f2a997-2f33-4d97-9455-16bfe12e5a98', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is access control in Swift?', N'Intern', N'Access control restricts access to parts of your code from code in other source files or modules. It allows you to hide implementation details and specify interfaces that other parts of your code can interact with, such as public, internal, or private.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de016cce-03f4-4ae5-9b79-16c02da89185', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Explain the significance of the Lit update lifecycle and how it optimizes performance.', N'Middle', N'The Lit lifecycle is asynchronous and batched, meaning multiple property changes result in only one render pass. This prevents unnecessary DOM operations and improves performance by ensuring the component only updates after all pending changes are processed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb808e0b-9e5b-4917-a86d-16c134284f1c', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you achieve conditional group of elements?', N'Fresher', N'You can achieve conditional group of elements(toggle multiple elements at a time) by applying v-if directive on element which works as invisible wrapper(no rendering) for group of elements. For example, you can conditionally group user details based on valid user condition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b3a56a6-0b0b-4d50-b111-16c3822d3c40', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket''s type-safe request routing differ from traditional frameworks using dynamic dispatch?', N'Senior', N'Rocket utilizes procedural macros to generate specialized routing logic at compile-time. This eliminates the runtime overhead associated with reflecting on function signatures or matching strings against regex patterns, resulting in faster request dispatch and earlier error detection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b679b71-8050-4379-bcc0-16c3aa3e7b30', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does ''Method#unbind'' and ''UnboundMethod'' allow for advanced object manipulation?', N'Senior', N'Unbinding a method removes it from its original class context, creating an ''UnboundMethod'' object that can be stored and later bound to a different object. This allows developers to move behavior between unrelated objects at runtime, providing a flexible way to share logic without complex inheritance structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
