INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c58b8e25-357d-4460-88ff-16c83ee0392d', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the concept of ''Type Narrowing'' and how it improves type safety.', N'Middle', N'Type narrowing occurs when TypeScript deduces a more specific type for a variable within a certain block of code, often using control flow statements like if-checks or type guards. This allows developers to safely access properties or methods that only exist on that specific type, preventing runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'823dbdac-b0e7-497e-b001-16c870196296', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the architectural difference between Flask''s ''before_request'' hooks and ''before_first_request'' hooks?', N'Senior', N'The ''before_request'' hook runs for every incoming request, making it suitable for authentication or logging, while ''before_first_request'' executes only once when the application starts. ''before_first_request'' is typically used for one-time initialization, such as establishing database connections or warming up caches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b18424f-6320-4fa2-ad43-16c9f3a55039', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the ''Shadow DOM'' and how does it relate to HTML?', N'Middle', N'The Shadow DOM allows for the encapsulation of a subtree of DOM elements, shielding them from the global document styles and scripts. It is a key component of Web Components, enabling developers to create reusable, self-contained widgets. It ensures that styles inside the shadow root do not leak out and vice versa.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
