INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aedfda3c-1e5b-4c7d-ad5f-16cb99cdfbe0', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the role of the ''Identity Map'' pattern and why it is not the default in Rails.', N'Senior', N'An Identity Map ensures that multiple requests for the same database record return the exact same object in memory. Rails avoids this by default because it introduces complex memory management issues and potential stale-data bugs that are difficult to debug in a concurrent environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
