INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8f53d04-728c-4dc3-92d1-16d9231ec165', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle HTTP requests?', N'Intern', N'Micronaut uses a non-blocking, event-loop-based HTTP server, typically Netty, to handle requests. It maps incoming URLs to controller methods using annotations, allowing for efficient request processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ba65475-334f-4b41-9dce-16d9e8ec8062', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is fault tolerance in Quarkus?', N'Fresher', N'Fault tolerance is a set of features that help applications handle failures gracefully. Quarkus uses the MicroProfile Fault Tolerance specification to provide tools like retries, timeouts, and circuit breakers to manage service dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76857756-5ccd-4b23-93ac-16deb0a71e37', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the major features of VueJS?', N'Intern', N'Below are the some of major features available with VueJS 1. Virtual DOM: It uses virtual DOM similar to other existing frameworks such as ReactJS, Ember etc. Virtual DOM is a light-weight in-memory tree representation of the original HTML DOM and updated without affecting the original DOM. 2. Components: Used to create reusable custom elements in VueJS applications. 3. Templates: VueJS provides HTML based templates that bind the DOM with the Vue instance data 4. Routing: Navigation between pages is achieved through vue-router 5. Light weight: VueJS is light weight library compared to other frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89f3f86a-2a38-4064-96a3-16e1e7cd554d', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Explain why Cassandra is considered an AP system in the CAP theorem context.', N'Senior', N'Cassandra prioritizes availability and partition tolerance by allowing writes to continue even when some nodes are unreachable. By using tunable consistency, it permits developers to choose between consistency and availability on a per-request basis, rather than forcing a global trade-off.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0620c645-7d2d-4dea-958a-16e55cee7584', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why does Go use a garbage collector instead of manual memory management?', N'Middle', N'Go prioritizes developer productivity and memory safety by automating heap management. This approach eliminates common vulnerabilities like use-after-free or double-free errors while maintaining acceptable performance through a highly optimized, concurrent mark-and-sweep collector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac4da1cd-b523-40fc-98dc-16e6d3dac2f4', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is a ''typealias''?', N'Junior', N'A typealias provides an alternative name for an existing type. It is useful for shortening long or complex type names, such as function types or generic collections, to improve code readability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'223810d4-9bee-42c9-81d7-16e701ea95b2', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the ''useMemo'' hook used for?', N'Intern', N'The ''useMemo'' hook is used to cache the result of an expensive calculation so that it does not need to be recomputed on every render. By only re-running the calculation when specific dependencies change, it helps optimize the performance of components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c8f7c59-e6ee-479d-8f9d-16ea8f1eb025', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using a relational database versus a NoSQL database for a new feature?', N'Junior', N'I evaluate the structure of the data and the necessity of complex relationships. If the data is highly structured and requires strict consistency or complex joins, I choose a relational database. If the data is unstructured, requires rapid scaling, or has a flexible schema, I opt for a NoSQL solution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b5efa49-a412-4325-9f05-16ec53c53322', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are some common performance bottlenecks in JavaScript applications?', N'Intern', N'Common performance bottlenecks in JavaScript applications include inefficient DOM manipulation, excessive use of global variables, blocking the main thread with heavy computations, memory leaks, and improper use of asynchronous operations. To mitigate these issues, you can use techniques like debouncing and throttling, optimizing DOM updates, and leveraging web workers for heavy computations. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the concept of debouncing and throttling Debouncing and throttling are techniques used to control the rate at which a function is executed. Debouncing ensures that a function is only called after a specified delay has passed since the last time it was invoked. Throttling ensures that a function is called at most once in a specified time interval.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fb9d999-fad5-419c-996b-16eefa632393', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the primary concern when using global state or non-thread-safe variables within a Fiber handler?', N'Middle', N'Because Fiber reuses request contexts and potentially handles multiple requests concurrently within a worker pool, any shared state must be protected by synchronization primitives like Mutexes. Failing to do so will lead to race conditions as concurrent requests attempt to mutate the same memory address simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40f30cad-1361-4218-a8e5-16ef5bd2da4f', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does the ''Either'' type differ from ''Option''?', N'Middle', N'Either is used for error handling where you need to provide information about why a process failed. Unlike Option, which only indicates presence or absence, Either carries two possible types, usually representing a successful result or an error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7f18caf-3549-4902-935d-16f049a277a1', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the jQuery .each() method used for?', N'Fresher', N'The .each() method is used to iterate over a collection of jQuery elements or an array of data. It allows you to execute a function for each item in the selection, which is useful for performing repetitive tasks on multiple elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19ab05b4-cba1-443f-b2d2-16f39fed8463', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How can you test Quarkus applications effectively?', N'Middle', N'Quarkus provides specialized test runners that can start the application, including containerized dependencies like databases via Testcontainers, directly during the test lifecycle. This ensures that integration tests accurately reflect the production environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c8e5728-57a8-46c6-90d6-16f71b60e2ce', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the purpose of Write-Ahead Logging (WAL) in PostgreSQL.', N'Middle', N'WAL ensures data integrity by recording all changes to the database in a log file before applying them to the actual data files. This allows the database to recover from crashes by replaying the log, ensuring that transactions are durable even if a system failure occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4797ca32-de89-48b0-8466-16f883c09c2c', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Does Dart support multi-threading in the traditional sense?', N'Intern', N'Dart does not use traditional shared-memory multi-threading, which avoids common issues like race conditions. Instead, it uses an event loop and isolates, which are independent workers that communicate by passing messages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ceabc04-fcf2-4a60-a6ae-16fc4ea8679e', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Describe your strategy for estimating the infrastructure costs of a system that needs to scale from zero to millions of users.', N'Senior', N'I employ a bottom-up modeling approach based on expected throughput, storage growth, and architectural overhead. I then benchmark against similar systems and build in significant buffers for cloud resource overhead, while planning for horizontal scalability to avoid over-provisioning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
