INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b8dfabc-e34f-4bdd-9ed2-1703cd276e31', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the role and trade-offs of the NestJS execution context in a microservices architecture.', N'Senior', N'The execution context provides metadata about the incoming request, allowing guards, interceptors, and filters to behave differently based on the transport layer. A trade-off is the added abstraction layer, which can make debugging complex request lifecycles more difficult compared to native transport-specific implementations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
