INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'433465da-e881-4139-b6a2-170bf9783643', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How can you trigger an action after a component initializes?', N'Fresher', N'You can use the x-init directive to run code as soon as an Alpine component is initialized. This is commonly used for fetching initial data, setting up event listeners, or performing any setup logic required by the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0f2ecc5-8126-400d-bec4-170d436573fc', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between the ''equals'' method and the ''=='' operator in Java?', N'Junior', N'The ''=='' operator compares the memory addresses of two objects to check if they refer to the exact same instance. The ''equals'' method is intended to be overridden to compare the actual content or logical values of two objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29d3ee05-e92f-4571-abe2-170dfd3f0455', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of a ''layout'' in Rails?', N'Intern', N'A layout is a template that defines the common wrapper for your application views, such as the HTML header, footer, and navigation. By using layouts, you ensure a consistent look and feel across all pages without having to duplicate that boilerplate HTML in every view file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c22e3f7-7e34-436b-a229-170ecc276e2c', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Explain the role of the ''QRL'' in Qwik.', N'Middle', N'A QRL (Qwik Resource Locator) is a specific URL-like string that points to a chunk of code. It allows the framework to lazily load and execute functions or components only when triggered by user interaction or other asynchronous events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bab75514-bbd6-404b-9993-170fa88a6eee', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the purpose of the NestJS ''Dynamic Module'' pattern?', N'Middle', N'Dynamic modules allow you to create customizable modules that can be configured at runtime. This is useful for importing external libraries or services that require specific credentials or settings upon application startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72501172-f99d-4ffd-8d59-17101bfb142a', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain the difference between ''Structural Directives'' and ''Attribute Directives'' at the architectural level.', N'Senior', N'Structural directives, like *ngIf or *ngFor, alter the DOM layout by adding or removing elements, which changes the component tree structure. Attribute directives, like ngClass, only change the appearance or behavior of an existing element without altering the DOM structure, making them more performant for simple UI manipulations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da8c63bd-88ef-4087-8c07-17134d0b93e2', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the benefit of using Chi over the standard library''s ServeMux?', N'Junior', N'Chi provides more advanced features like route parameters, sub-routing, better middleware support, and method-based routing. The standard ServeMux is limited in its ability to handle dynamic path segments and complex routing hierarchies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'394adc0a-066b-4f4f-97bc-1713858d261c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What does it mean for JavaScript to be a dynamically typed language?', N'Junior', N'Being dynamically typed means that variable types are checked at runtime rather than at compile time. You do not need to explicitly declare the data type of a variable, and a single variable can hold different types of data throughout its lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e38b3549-efc0-4456-8ffc-17170cc346b9', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Why is ''Eventual Consistency'' often accepted in microservices, and how is it managed?', N'Middle', N'Strong consistency often requires blocking operations that conflict with the high availability and scalability goals of microservices. Eventual consistency is managed by using events to propagate state changes between services and implementing mechanisms like idempotent consumers to handle duplicate messages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fd58034-8bb2-49eb-9067-171804d20e07', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How do you optimize performance in a Spring Data JPA application?', N'Middle', N'Performance can be optimized by using join fetches to avoid N+1 query problems, selecting only required fields using projections, and carefully managing transaction boundaries. Additionally, using read-only transactions can help the underlying persistence provider optimize resource usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8537a3c-1eb0-4100-a296-1718d241cf03', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the significance of the ''Response Caching'' middleware?', N'Middle', N'Response caching middleware allows the server to store and serve cached HTTP responses based on request headers. This reduces the processing load on the server and improves response times for frequently accessed data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a19f447-12c5-4dc4-a30a-171b705d8770', N'4c000000-0000-0000-0000-000000000005', N'What is eventual consistency and when is it acceptable?', N'Middle', N'Eventual consistency means that while all updates will propagate to all nodes eventually, there is a window where different users might see different data. It is acceptable in systems like social media feeds or analytics dashboards where high availability and low latency are prioritized over immediate data accuracy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'440f260d-b83e-4d5e-a5ad-171b9beb5cc7', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Does Express automatically parse incoming JSON data?', N'Intern', N'Yes, modern versions of Express include built-in middleware such as express.json to automatically parse incoming requests with JSON payloads. You must explicitly use this middleware in your application for it to take effect.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6315296d-3362-4ead-b315-171dc5c9644c', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Why is Hono suitable for microservices?', N'Junior', N'Because Hono is extremely lightweight and has a fast startup time, it is ideal for microservices that need to be deployed and scaled independently. Its minimal footprint ensures low resource usage in containerized or serverless environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8c35491-2483-43af-9175-17229a0d3fee', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'When is a Hash Index preferred?', N'Middle', N'Hash indexes are specifically designed for equality comparisons on large values where a B-tree might become too deep. However, they are not WAL-logged in older versions and generally have more limited functionality compared to B-trees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e69eb1c2-5515-4309-9991-17235d5d9790', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin handle null safety and what is the Elvis operator?', N'Fresher', N'In Kotlin, null safety is a core feature designed to address the issues around null references. It aims to reduce NullPointerException errors that are commonly encountered in other languages, particularly Java. The Elvis Operator provides a concise means for handling null values within expressions. Null Safety Kotlin employs a set of rules to manage nullability in objects: Nullable Types - A type is marked as nullable if it can accept null values. This is indicated by appending ? to the type name. - If the name variable was not marked as nullable (e.g., val name: String = null), and you attempted to assign null, the Kotlin compiler wouldn''t allow it. Safe Calls - To invoke a method or access a property on a nullable object, use the safe call operator ?..', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49946fc2-5bb8-4125-b554-1723a6fa545c', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Discuss the trade-offs of using ''Typed Messages'' in Actix for system extensibility.', N'Senior', N'Typed messages provide compile-time safety, ensuring that handlers only receive data they are equipped to process, which reduces runtime errors. However, this strictness can make it difficult to implement generic handlers or dynamic systems that need to process polymorphic message types without extensive enum nesting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2408541d-a114-44f7-9501-17245dc847f0', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How do different transaction isolation levels affect concurrency and consistency?', N'Middle', N'Isolation levels define how transaction integrity is visible to other users and systems. Higher levels like Serializable provide maximum consistency by preventing dirty reads, non-repeatable reads, and phantoms, but they decrease performance by increasing lock contention, whereas lower levels like Read Committed offer higher concurrency at the cost of potential consistency anomalies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
