INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4af2668b-0195-4a01-a302-172646d69065', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the purpose of a ''divide and conquer'' strategy in troubleshooting?', N'Intern', N'Divide and conquer involves splitting a complex system or process into smaller segments to test each one individually. This narrows down the location of the fault, allowing you to focus your investigation on the specific component that is failing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9300e797-5440-4ef3-b515-1729250fb737', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a ''Hot Standby'' and a ''Physical Standby''?', N'Middle', N'A physical standby is a replica that maintains a block-level copy of the database. A Hot Standby is a specific configuration of a physical standby that allows read-only queries to be executed against the replica while it is still receiving data updates from the primary, enabling horizontal read scaling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
