INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'346a940c-eb60-459e-b1ab-172bafa446af', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the benefit of using an API Gateway in a distributed architecture?', N'Middle', N'An API Gateway serves as a single entry point that handles cross-cutting concerns like authentication, rate limiting, and request routing. It abstracts the underlying service complexity from the client and provides a centralized place for monitoring and security policies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f202036-a9d6-45a6-a269-17305aa9a0aa', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are the trade-offs of using ''dynamic'' in Dart?', N'Middle', N'Using dynamic disables static type checking, which can lead to runtime errors that the compiler would otherwise catch. While it offers flexibility for interop or complex data structures, it degrades performance and breaks the safety guarantees of the type system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62d1157d-b0f2-400e-8d36-173440928344', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How do you handle database connection pooling in Laravel?', N'Senior', N'Laravel manages database connections natively through PDO, but it does not have built-in connection pooling. For high-scale applications, you should implement an external proxy like PgBouncer or ProxySQL to manage and pool connections between the application and the database server efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a54afffb-03ce-44fa-b2f0-17350e5fb48d', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does ''Strict Serializable'' isolation differ from standard serializability?', N'Senior', N'Strict Serializability combines serializability with linearizability, meaning transactions not only appear to execute in a serial order but that this order is consistent with the real-time order of the operations. It is the strongest possible consistency model for distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
