INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d39e688-5112-410a-aad9-17367c2d3ef1', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Why is the order of middleware important in Echo?', N'Junior', N'Middleware in Echo executes in the order it is added to the router. Because each middleware can modify the request or terminate the chain, placing them in the correct sequence ensures that tasks like authentication happen before logging or processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3c8c2a3-1b98-42a8-9b05-1736be258815', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the CSS ''content-visibility'' property and why is it used?', N'Middle', N'The ''content-visibility'' property allows the browser to skip the rendering work, including layout and painting, for off-screen elements. This significantly improves initial load times and responsiveness for long pages by only processing content that is currently in the viewport.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9c3d7ce-6d53-4b2f-8438-173a9eef6c78', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin''s Context object improve request handling compared to the standard library''s http.ResponseWriter and *http.Request?', N'Middle', N'The Context object aggregates request and response data, providing helper methods for binding parameters, rendering templates, and serializing JSON. It also manages the middleware chain state, allowing data to be passed between handlers through a thread-safe map.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd13dfb6d-df6a-449b-b49e-173dad3c9a6a', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What does it mean for R to be a vectorized language?', N'Junior', N'Vectorization means that R operations are applied to entire vectors or arrays simultaneously rather than requiring explicit loops. This improves performance and results in more concise, readable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d272f23-8da9-4a8a-9029-173fa088357f', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the purpose of the ''runtime.Gosched()'' function?', N'Senior', N'Gosched yields the processor, allowing other goroutines to run while the current goroutine remains in the runnable state. It is rarely needed in production code but can be used in tight loops to prevent a single goroutine from monopolizing a CPU core.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33b4cf95-3d8a-479c-89be-17411a07e00a', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you account for ''unknown unknowns'' when providing project estimates?', N'Middle', N'I apply a contingency buffer to the total estimate based on the historical complexity of similar projects. I also maintain a risk register to track potential blockers, ensuring that if an unknown issue arises, there is already an established process to re-evaluate the timeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad48cea5-74ba-49d9-84d7-17437b57b2a7', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact''s virtual DOM implementation differ from React''s in terms of memory footprint and performance?', N'Senior', N'Preact prioritizes a minimal footprint by using a lightweight VDOM that avoids complex features like SyntheticEvents and extensive object pooling. By keeping the core library size under 3KB, it reduces parse time and memory overhead, making it highly efficient for constrained environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ca96c7a-f334-41d5-880f-1744d2062543', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the difference between an ''on:mount'' lifecycle function and standard script execution?', N'Junior', N'The ''on:mount'' function runs after the component has been rendered and inserted into the DOM for the first time. Standard script code runs as soon as the component is initialized, before the DOM elements are available.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'370238f0-66ad-4cfd-82b6-1744fdfa9adf', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How do you manage cross-origin resource sharing (CORS) policies in a distributed Express environment?', N'Senior', N'CORS should be handled by a centralized middleware that validates the Origin header against a whitelist. In distributed environments, it is often better to configure CORS at the API Gateway level to ensure consistent policy enforcement across all microservices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8a3c30a-35bd-4258-b58c-1745f01f0a1d', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What are Astro ''Content Collections'' and why are they useful?', N'Middle', N'Content Collections provide a structured way to organize and validate local content like Markdown or MDX files using TypeScript schemas. They improve developer experience by providing type safety and better performance during the build process through optimized content querying.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4328c5cf-66d4-4da7-b92c-1749e55d18e4', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the purpose of the ''static'' keyword in Java?', N'Fresher', N'The static keyword indicates that a member variable or method belongs to the class itself rather than to any specific instance of the class. This means a static member is shared by all objects of the class and can be accessed without creating an object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ea94193-6d1d-41a8-b837-174c528bebfc', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Describe the difference between eager and lazy evaluation in the context of C++ expression templates.', N'Senior', N'Eager evaluation performs operations immediately as they appear, whereas expression templates enable lazy evaluation by representing expressions as tree structures of types until the final result is assigned. This allows the compiler to optimize the entire expression tree, such as minimizing intermediate allocations or fusing loops in numerical libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6675f0b2-248d-4d59-a390-174f18374a30', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the significance of the ''Vector Clock'' in resolving partial ordering of events.', N'Senior', N'Vector clocks track the logical history of an object across different replicas by maintaining a counter for each node. This allows the system to determine if one update causally precedes another, or if they are concurrent and require conflict resolution logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18c57e6f-16c3-47d4-a2df-174f9bc2e5c1', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How do you add a new plugin to a Vite project?', N'Junior', N'You typically install the plugin via a package manager and then import it into the plugins array within the vite.config.js file. Most plugins are simply functions that return an object with specific hooks that Vite executes during the build lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'635e1d49-77b1-4324-8ffb-17514daa1c91', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of the @Primary and @Qualifier annotations in dependency injection?', N'Senior', N'@Primary designates a bean as the default choice when multiple beans of the same type exist. @Qualifier provides a more granular approach, allowing you to explicitly name which specific bean should be injected, which is essential when dealing with multiple implementations of a single interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d3c00f9-27ff-43a3-8f32-1753c423b52d', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why is it recommended to place style sheets in the ''head'' and scripts at the end of the ''body''?', N'Middle', N'Placing styles in the head allows the browser to render the page immediately without waiting for layout calculations to be blocked by late-arriving CSS. Placing scripts at the end of the body ensures that the DOM is fully parsed and available before the script attempts to interact with it, preventing null reference errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef60c559-8789-4c07-a570-1756343606fb', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the benefit of Fastify''s encapsulated context?', N'Junior', N'Encapsulation allows you to create isolated parts of your application where plugins and decorations are restricted to specific route trees. This prevents side effects between different modules and makes large applications easier to maintain and test.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57f3c73c-1f6f-465a-8e63-1756a3c6eb77', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the purpose of implementing a circuit breaker pattern?', N'Middle', N'The circuit breaker pattern prevents a service from repeatedly trying to execute an operation that is likely to fail, such as a request to a down downstream service. By failing fast, it allows the calling system to maintain stability and provides the failing service time to recover without being overwhelmed by requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7240d0a8-9fd2-4b5e-8a7a-1759510115c0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does await and async works in es6?', N'Fresher', N'The async and await keywords enable asynchronous, promise-based behavior to be written in a cleaner style, avoiding the need to explicitly configure promise chains. Async keyword is used along with the function declaration which specifies that this function is now able to accept all types of asynchronous events on itself. Await basically waits for the results which are particularly to be fetched from the source from which that async function is about to fetch the data. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5781651-3c39-42af-ae5c-17598f702c5c', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why is ''Linearizability'' considered a stronger guarantee than ''Serializability''?', N'Senior', N'Serializability is a property of transactions, ensuring the outcome of multiple concurrent transactions is equivalent to some serial order. Linearizability is a property of individual operations on a single object, ensuring that once a write completes, all subsequent reads see that value, effectively providing a total order of operations in real-time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5f4f54a-2318-4797-9865-175e94ba6abc', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the benefit of Rocket''s ''zero-cost abstractions''?', N'Fresher', N'Rocket aims to provide high-level features and convenience without imposing a runtime performance penalty. By utilizing Rust''s compile-time features, the framework ensures that abstractions do not add overhead to the final executable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f87c65d6-f508-4f51-a002-175eb16f2c97', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How do you handle configuration validation in NestJS?', N'Middle', N'You can use the ''joi'' or ''class-validator'' libraries within the ConfigModule to validate environment variables during the bootstrap process. This ensures that if critical configuration is missing or malformed, the application will fail to start rather than crashing later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f34befe6-44f0-432f-8680-1761dd5c0e3d', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the value of a ''fail-fast'' approach?', N'Intern', N'The fail-fast approach encourages identifying and exposing errors as soon as they occur rather than letting them propagate through the system. By crashing or surfacing an error immediately, it prevents the system from entering an invalid state, making debugging much easier. It allows developers to address defects while the context is still fresh.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de4c2907-62e4-4f4b-af87-1764b0ef70f9', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How do you handle JSON data in Litestar?', N'Fresher', N'Litestar automatically handles JSON serialization and deserialization. When a request has a JSON body, the framework parses it into a Python object, and when returning a dictionary or model, it converts it back to a JSON response automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c5a5382-6da7-4d9d-a8ae-1764eaa342c7', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the role of the IoC container in AdonisJS?', N'Intern', N'The Inversion of Control container manages the lifecycle of classes and dependencies within the application. It allows for decoupling components, making it easier to swap implementations and manage complex class instantiations automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'855f9793-4b4f-446f-a424-176617a1ed84', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of static files in Express?', N'Intern', N'Static files are assets like images, CSS files, and JavaScript files that do not change based on user input. Express provides a built-in middleware called express.static to serve these files directly to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48a4346d-5ef3-4044-9793-1768382b0103', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the difference between a Compiler Pass and a regular service configuration.', N'Middle', N'Compiler Passes are used to manipulate the service container definition during the compilation phase, before the container is frozen. While regular configuration defines static services, compiler passes allow for dynamic modification, such as automatically registering tagged services or optimizing the container structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdd6a3bb-383a-424b-8960-176ab2c18125', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is an ''App'' in Actix?', N'Intern', N'An App is the entry point for an Actix web application. It acts as a container for routing, middleware, and shared application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2516bb97-5db4-46de-865b-176c25ae0bc0', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are declaration files (.d.ts)?', N'Intern', N'Declaration files contain type information for JavaScript code that does not have built-in TypeScript support. They allow TypeScript to understand the types used in third-party libraries without needing to see the underlying implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63febebb-7ccf-478f-bbc4-176cdb68871f', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact treat the ''key'' prop during reconciliation?', N'Senior', N'The ''key'' prop is used to identify individual VNodes in a list, allowing Preact''s diffing algorithm to perform efficient reordering and insertion instead of full list re-renders. Properly using unique keys prevents unnecessary unmounting and remounting of components, which is critical for maintaining component state during list mutations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9998fdb3-052c-4628-a870-176e4063f5dd', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What role does monitoring play in cache management?', N'Middle', N'Monitoring cache metrics such as hit ratio, eviction rate, and memory usage is essential for identifying bottlenecks. A low hit ratio suggests that the cache is either too small, the keys are poorly chosen, or the data is changing too rapidly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3dfe5260-1d04-42ec-8102-176f1fc5fefb', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you access JSON data sent to a Flask route?', N'Junior', N'If a client sends data with the ''application/json'' content type, you can access it using the request.get_json() method. This method parses the incoming JSON body into a Python dictionary that you can easily manipulate in your code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'830458f7-063e-4205-a93f-1771118a1a38', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the role of the ''Logger'' interface in Echo?', N'Intern', N'The Logger interface allows developers to integrate custom logging solutions with the Echo framework. By implementing this interface, you can control how the framework outputs its internal logs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5584248d-d3a1-421f-af64-17720812293d', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Explain the difference between ''Fairings'' and Middleware.', N'Middle', N'Fairings are Rocket’s mechanism for hooking into the application lifecycle, such as request arrival or response completion. They are similar to middleware but are more integrated into the Rocket lifecycle, allowing for global modification of requests and responses or configuration checks during startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce23e8c9-f821-4e9e-b6ff-177358dd0e4b', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Discuss the relationship between ''Object'' singletons in Scala and the JVM''s classloader hierarchy.', N'Senior', N'Scala objects are implemented as static instances within a class, and their initialization is handled by the JVM''s class loading mechanism, ensuring thread-safe lazy initialization. The architectural risk arises if the classloader hierarchy is complex, as static instances are tied to specific classloaders. This can cause issues in environments like OSGi or application servers where multiple classloaders exist.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6454ad66-e61c-4c74-89e6-17758a51d500', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the primary purpose of Spring Boot''s ''Auto-configuration'' feature?', N'Intern', N'Auto-configuration automatically configures your Spring application based on the dependencies present on your project''s classpath. It eliminates the need for manual setup by intelligently guessing the necessary beans and configurations required for common frameworks. This significantly reduces boilerplate code and speeds up the initial development process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec36fe81-80f2-4f84-8154-17776f6e4ee2', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the hook functions provided by directives?', N'Intern', N'A directive object can provide several hook functions, 1. bind: This occurs once the directive is attached to the element. 2. inserted: This hook occurs once the element is inserted into the parent DOM. 3. update: This hook is called when the element updates, but children haven''t been updated yet. 4. componentUpdated: This hook is called once the component and the children have been updated. 5. unbind: This hook is called only once when the directive is removed. Note: There are several arguments that can be passed to the above hooks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37363ae6-51cf-476d-b262-1779ad914007', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django''s ORM handle database transactions and when might you need to explicitly manage them?', N'Middle', N'Django wraps every view function in a transaction by default if the ATOMIC_REQUESTS setting is enabled. You should explicitly manage transactions using the atomic decorator or context manager when performing multiple related database operations that must either all succeed or all fail to maintain data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a16687b-294b-4613-b9d3-177b3ab1e72b', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach the trade-off between latency and data integrity in a distributed transaction?', N'Senior', N'I prefer the Saga pattern or outbox pattern over distributed locks or two-phase commits to ensure eventual consistency without blocking resources. By favoring asynchronous communication and compensating transactions, I maintain system throughput while acknowledging that the system state might be temporarily inconsistent during the process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8f8c9ef-fd4e-41e0-a4e5-17830b6178de', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Why is SvelteKit considered ''framework agnostic'' regarding data fetching?', N'Middle', N'SvelteKit does not dictate a specific data fetching library; it works with native fetch, Axios, or any other library. Because the load functions are just standard functions, you can integrate any data layer or ORM that is compatible with the Node.js or edge runtime environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56654f2a-a790-4d02-9d47-178400e59ee9', N'075b8862-431c-4678-9767-f55359758a4a', N'Discuss the trade-offs of using TypeScript with Vue 3''s Composition API.', N'Senior', N'TypeScript provides static type checking, better IDE autocompletion, and clearer interface contracts, which are essential for maintainability in large teams. The trade-off is increased setup complexity and the need for sophisticated type definitions for complex composables, but the long-term benefits in preventing runtime errors usually outweigh these costs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
