INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0936b951-9aa4-4fc4-86e4-178ce80f43af', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the Java ClassLoader hierarchy support modularity and isolation in complex enterprise applications?', N'Senior', N'The delegation-based ClassLoader hierarchy ensures that classes are loaded by parent loaders first, preventing conflicts between core platform libraries and user-defined code. This architecture allows for dynamic class loading and isolation, enabling multiple versions of the same library to coexist within the same JVM process by using separate child ClassLoaders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9130d377-160a-457d-9528-178f1ac5309d', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you ensure data privacy and compliance in a distributed system?', N'Senior', N'I implement data classification at the schema level and enforce encryption at rest and in transit. I also ensure that PII is centralized or strictly controlled through access tokens, providing audit logs that prove compliance with regulations like GDPR or SOC2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
