INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86b1fc13-802e-4beb-b3d3-17904b9cb9b7', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is C considered a middle-level language?', N'Junior', N'C is considered middle-level because it combines the low-level features of assembly language, such as direct memory access via pointers, with the high-level features of structured programming languages. This makes it suitable for both system-level programming and application development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7df7e87-c729-49fd-b887-17924d9178b8', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is type assertion in TypeScript?', N'Fresher', N'Type assertion is a way to tell the compiler to treat a value as a specific type, overriding the compiler''s inferred type. It is essentially a way for the developer to say they know more about the value''s type than the compiler does.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
