INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7db33c87-0532-480c-b83d-1795aa2eb8cd', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the browser determine the ''origin'' of a document for CORS purposes?', N'Senior', N'The browser defines the origin based on the scheme, host, and port of the URL. HTML elements that fetch cross-origin resources, such as scripts or images, are subject to CORS policies; properly setting attributes like ''crossorigin'' on elements is necessary to allow the browser to share responses across these boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'209295f7-80d7-40c0-94cc-1795f55e507d', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'When designing for disaster recovery, how do you determine your RTO and RPO?', N'Middle', N'RTO and RPO are determined by business requirements regarding the cost of downtime versus the cost of maintaining redundant infrastructure. I work with stakeholders to define the maximum tolerable duration of an outage and the maximum acceptable amount of data loss, then design infrastructure, backups, and failover procedures to meet those specific targets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad195822-c583-474e-b071-179768f666e8', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the purpose of a load balancer?', N'Fresher', N'A load balancer distributes incoming network traffic across multiple servers to ensure that no single server becomes overwhelmed. By spreading the load, it improves the responsiveness and reliability of the application. If one server fails, the load balancer can direct traffic to the remaining healthy servers, preventing downtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f400373-f59f-4491-9195-1799302d2732', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is a Capped Collection and what are its common use cases?', N'Middle', N'A capped collection is a fixed-size collection that automatically overwrites its oldest documents once the allocated space is full. It is ideal for scenarios like logging, caching, or storing high-frequency time-series data where older data is no longer needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59ba4e18-efbd-4eee-a0f3-17997aec4d90', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono differ from Express.js in terms of architecture?', N'Fresher', N'Hono is built on modern Web Standards like the Fetch API, making it lightweight and portable across runtimes. In contrast, Express.js was built specifically for Node.js using an older architecture that relies heavily on Node-specific APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5378d716-3bc4-4d7f-9bc3-179d358be39a', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of the ''Send'' and ''Sync'' traits?', N'Middle', N'These are marker traits used to communicate thread safety properties to the compiler. ''Send'' indicates that a type can be safely transferred between threads, while ''Sync'' indicates that a type can be accessed from multiple threads simultaneously through immutable references.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'612c030d-2949-4c94-83f9-179f35605eb5', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the role of the ''request'' object in Flask?', N'Fresher', N'The request object is a global object provided by Flask that contains all the data sent by the client in an HTTP request. It allows developers to access form data, URL parameters, headers, and files submitted by the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c3f5bf5-8ea3-4439-9532-179fba1b3d2e', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do you handle events in Lit?', N'Intern', N'You handle events in Lit by adding standard event listeners directly in the template using the @event syntax. This maps the event to a method defined in your component class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cee669e0-3d0d-446b-a398-17a1ec609ce4', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the benefit of keeping a detailed change log for production environments?', N'Middle', N'A detailed change log allows for rapid correlation between system behavior changes and recent deployments. When a bug appears, knowing exactly what code, configuration, or environment variables changed recently helps to narrow the search space for the root cause significantly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a394bcd-d893-473c-b1a7-17a416cc9df9', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are asked to estimate how many windows are in your city, how would you approach the problem?', N'Intern', N'I would start by estimating the population of the city and the average number of people per household to determine the total number of residential units. Then, I would estimate the average number of windows per unit, account for commercial and office buildings separately, and multiply these figures to reach a reasonable order-of-magnitude estimate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e844050d-82fb-404f-b97b-17a4b60f543c', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the primary advantage of Vite''s speed?', N'Fresher', N'The primary advantage is the significantly faster feedback loop during development. Developers spend less time waiting for the server to start or for changes to reflect in the browser, which increases productivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f05935c-ba38-4a50-8fee-17a6c8816f81', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is Minification', N'Intern', N'Minification is the process of removing all unnecessary characters(empty spaces are removed) and variables will be renamed without changing it''s functionality. It is also a type of obfuscation .', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32f6e370-b540-4a52-97bc-17a79385a7d1', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the difference between Path and Query parameters in terms of code implementation?', N'Fresher', N'Path parameters are defined within the URL string of the decorator, while query parameters are any extra function arguments that are not declared as path parameters and are not using a special class like ''Body'' or ''Form''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b849470-a940-4d9c-9f44-17a79cad49bb', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Why does Kotlin distinguish between ''List'' and ''MutableList'' at the interface level?', N'Senior', N'This distinction enforces the principle of immutability in the type system, allowing developers to communicate the intent that a list should not be modified by the receiver. By preventing unauthorized mutation, this design improves code safety and makes it easier to reason about state changes in complex, multi-threaded applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'171e32aa-7cc9-46d8-93b7-17a9bc303e4e', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the concept of an Index-Only Scan.', N'Middle', N'An index-only scan occurs when the database retrieves all the required columns for a query directly from the index tree. This avoids the extra cost of fetching the corresponding heap page, provided the visibility map confirms the rows are visible to the current transaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bdb630d-c36e-48e9-88d9-17ace1baf135', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why is the ''public'' directory special in Vite?', N'Intern', N'Files placed in the public directory are served at the root path and are not processed by Vite. They are copied to the build output directory as-is, which is useful for static files like favicons or robots.txt.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46a9ecb3-34c1-46c7-bb2e-17ad83050772', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are the trade-offs of using Shadow DOM encapsulation versus global CSS in a large-scale design system?', N'Senior', N'Shadow DOM provides true style isolation, preventing global style leakage and ensuring component portability. However, it complicates global theme management and requires CSS variables or constructible stylesheets for effective cross-component token injection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b23c435-9794-4b66-a16e-17ae68b20365', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the theoretical difference between ''Task'' and ''TaskGroup'' in Swift concurrency?', N'Senior', N'A Task is a single unit of asynchronous work, whereas a TaskGroup is a structured concurrency mechanism used to manage and wait for multiple child tasks simultaneously. TaskGroups provide a way to aggregate results from parallel operations while ensuring that all child tasks are completed or cancelled before the group finishes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8bc57df-0563-4d21-bd57-17af6cb4caf4', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin manage JSON serialization performance?', N'Middle', N'Gin uses the standard encoding/json library by default but allows for easy integration with high-performance JSON libraries like jsoniter. It optimizes serialization by providing helper methods that set the appropriate content-type headers automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92371956-74af-4ae6-bba1-17b0309762a5', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of the Portal component?', N'Junior', N'The Portal component allows you to render a part of your UI into a different DOM element, usually outside the main application root. It is commonly used for modals, tooltips, or popups that need to escape the styling constraints of their parent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2b24c4d-62df-4f65-9b45-17b5f161e3a7', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript handle type erasure during the build process, and what are the implications for reflection?', N'Senior', N'TypeScript performs type erasure by removing all annotations, interfaces, and type aliases, leaving only the generated JavaScript. This means that metadata-based reflection is unavailable at runtime unless experimental decorators and the ''emitDecoratorMetadata'' flag are used, which introduces its own performance overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc72a496-8ac0-441c-8989-17b9c6e8be88', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt''s auto-import feature affect build performance and bundle size?', N'Senior', N'Auto-imports improve developer experience but can increase build times due to the overhead of scanning components and composables. While it doesn''t negatively impact the final bundle size since Nuxt performs tree-shaking, it can lead to namespace collisions if not managed with explicit prefixes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cec49adc-61b8-4595-bb3c-17ba384a1e22', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'Explain your process for identifying a performance bottleneck in a distributed system where multiple services communicate asynchronously.', N'Senior', N'I utilize distributed tracing to visualize the request flow and latency distribution across service boundaries. By comparing metrics like queue depth, CPU utilization, and I/O wait times, I isolate which service is the primary contributor to the latency or where backpressure is manifesting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dea4bbb0-1538-4097-83e8-17babcc092b5', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How can you customize the Vite production build output directory?', N'Middle', N'The build output directory can be configured via the build.outDir setting in the Vite configuration file. This allows developers to point the build artifact to a specific folder required by their deployment pipeline or server structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f47221a5-3a3a-45d8-805d-17bc51631a3d', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What does it mean for a Phoenix application to be stateful in a Channel context?', N'Junior', N'Unlike traditional HTTP requests which are stateless, a Channel connection maintains an open process on the server for the duration of the WebSocket connection. This allows the server to keep track of user-specific state during the session.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'800be052-042e-4ed9-9077-17bddfbf221b', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono manage CORS, and why is this often a point of failure in serverless deployments?', N'Middle', N'Hono provides a built-in CORS middleware that simplifies the configuration of headers for cross-origin requests. It can be a point of failure if the middleware is not placed early enough in the execution chain, causing the browser to reject pre-flight requests before the application logic runs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eafeccb6-4285-4294-b427-17c0443cd59e', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the role of the Erlang VM (BEAM) in Phoenix?', N'Intern', N'The BEAM is the virtual machine that executes Elixir code. It provides the foundation for Phoenix''s performance by managing lightweight processes, enabling massive concurrency and superior error isolation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9d1e0ce-1676-4990-8cbd-17c1c83343df', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the role of a Partitioner in Cassandra and how does it affect cluster distribution?', N'Senior', N'A Partitioner determines how the partition key is hashed to distribute data across the cluster''s token ring. Using the Murmur3Partitioner ensures uniform data distribution, which prevents hotspots but makes range queries across the entire cluster inefficient compared to ordered partitioning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4da06bef-dc35-483a-86b2-17c5dab57f02', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between final and const in the Dart programming language?', N'Fresher', N'The final keyword is used for variables that are set once at runtime and cannot be reassigned thereafter. In contrast, the const keyword is used for compile-time constants, meaning their value must be known before the program starts running. While final variables can be assigned based on a calculation or function result, const variables must be assigned a fixed, literal value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5819f8e4-1b3d-4ba3-a27c-17c5e7391f2b', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is Fastify''s built-in logger?', N'Fresher', N'Fastify uses the Pino logger by default, which is known for being extremely fast and low-overhead. It automatically logs incoming requests and outgoing responses, providing essential visibility into server operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44557097-61a1-46fd-a46f-17c7730a1fbb', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does the ''nominal'' typing simulation using ''branded types'' work and why would a senior architect choose it?', N'Senior', N'Branded types use intersection types with unique literal properties to force nominal behavior on structurally compatible types. This is used in architecture to prevent domain-level confusion, such as accidentally passing a User ID string where an Order ID string is expected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12ff7041-e354-4e85-b1f3-17c885f295ed', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What does ''thread-safe'' mean in the context of Actix-web state?', N'Fresher', N'Thread-safe means that multiple threads can access or modify the state without causing data corruption or crashes. Actix-web requires shared state to implement specific traits, like Send and Sync, to guarantee safe concurrent access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9ab9fa6-9846-48aa-b462-17c91fe99bd9', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are Custom Decorators in NestJS and why are they useful?', N'Middle', N'Custom decorators allow you to create reusable metadata annotations for classes, methods, or parameters. They are highly useful for extracting request-specific data like user objects or headers directly into route handler arguments, keeping controllers clean.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3632ae77-92ef-43ac-aa01-17c9d33f717c', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Explain the difference between ''Message'' and ''Handler'' traits in Actix.', N'Senior', N'The Message trait defines the structure and expected response type of a communication unit, while the Handler trait defines the actual business logic executed when an actor receives that specific message. This separation allows for decoupling the intent of a request from the implementation of its processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7fd4247-e82c-4410-91d3-17d218d7e126', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is an instance variable in Ruby?', N'Intern', N'An instance variable is a variable that belongs to a specific instance of a class. It is used to store the state of an object and is identified by the @ symbol at the beginning of its name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d707955-927d-49bd-a73d-17d3be9c8b15', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Does MongoDB use a schema?', N'Fresher', N'MongoDB is schema-less by default, meaning documents in the same collection do not need to have the same set of fields. This provides flexibility as the data structure evolves over time without requiring expensive migration processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'214c1303-7aee-4642-9058-17d407163853', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra achieve high write performance?', N'Junior', N'Cassandra achieves high write performance by using an append-only log structure. Incoming writes are first recorded in a commit log and then written to an in-memory structure called a Memtable, which minimizes disk I/O operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
