INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a552ecf7-2b91-4d8c-9e7c-17e1ce0a8c21', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are the architectural trade-offs of using ''iframe'' for content embedding?', N'Senior', N'Iframes provide complete security and style sandboxing, useful for third-party widgets, but they come with significant performance costs due to separate document context, resource loading, and memory consumption. Furthermore, coordinating communication between an iframe and its parent requires the ''postMessage'' API, which adds complexity to state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83b400f1-9bf3-4443-a600-17e291feec7b', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are Phoenix Contexts and why are they used?', N'Junior', N'Contexts are dedicated modules that expose functions for specific areas of your application''s business domain, such as Accounts or Catalog. They are used to decouple the web layer from the data layer, making the codebase more organized and easier to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fee8556-fecc-4d35-bbc5-17e37d27980a', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the purpose of a Content Security Policy (CSP) in web application architecture?', N'Middle', N'CSP is an HTTP header that allows site administrators to restrict the resources, such as JavaScript, CSS, or images, that the browser is allowed to load for a given page. It is a critical defense mechanism against Cross-Site Scripting (XSS) attacks by preventing the execution of unauthorized or malicious scripts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
