INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'565fbe66-8806-4da0-907c-17e718930a43', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the relationship between transactions and data integrity?', N'Fresher', N'Transactions are the primary tool for maintaining data integrity. By enforcing ACID properties, they ensure that the database never ends up in a corrupted or invalid state, even when multiple users are active.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df7c4614-eac9-4b5e-9d53-17e87651310c', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If a service is experiencing high latency, how do you determine if the issue is the application, the database, or the network?', N'Middle', N'I would start by examining the request duration metrics to see where the time is spent: in the application logic, during database queries, or in external API calls. I would check database execution plans and lock contention metrics to rule out slow queries. Finally, I would inspect network observability data, such as TCP retransmissions or load balancer latencies, to identify infrastructure bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e7fd912-4cbf-46c1-8f09-17e89ef181db', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the trade-offs of using wide primary keys in InnoDB?', N'Middle', N'Using wide primary keys negatively impacts performance because every secondary index in the table stores a copy of the primary key. This significantly increases the storage size of all secondary indexes, leading to more memory usage and more frequent disk I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
