INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b23a833-85ce-43a3-98da-17ed2c141a56', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you maintain consistency when working on a large team with different coding styles?', N'Junior', N'Adhere strictly to the team''s established style guide and shared coding conventions. Using automated linting tools and participating in thorough peer code reviews helps ensure that everyone''s work remains uniform and maintainable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e20c1073-4734-46d9-ae49-17efc6388a14', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the benefit of using an absolute path for the output directory?', N'Intern', N'Using an absolute path ensures that Webpack always knows exactly where to place the generated files regardless of the working directory. It prevents ambiguity and errors that can occur when the build process is run from different locations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e481a7d-7205-4525-bcd3-17f19dd048c4', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the difference between Server-Side Rendering (SSR) and Client-Side Rendering (CSR)?', N'Intern', N'In SSR, the server generates the full HTML content for a page and sends it to the browser, which improves initial load speed and SEO. In CSR, the browser receives a minimal HTML file and uses JavaScript to fetch data and build the page content dynamically after the initial load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e04b77ba-fd8f-40f4-8973-17f46a983b02', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django protect against Cross-Site Request Forgery (CSRF) attacks?', N'Middle', N'Django includes a middleware that checks for a CSRF token in POST requests. The server generates a unique, secret token for the user''s session, which must be submitted with any state-changing request, ensuring that the request originated from a trusted source rather than a malicious third-party site.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee146b15-c0af-4321-90d8-17f4fa658c72', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is ''createResource'' used for?', N'Intern', N'The createResource primitive is designed to handle asynchronous data fetching. It manages the loading state, error states, and the resulting data from a promise, making it easy to integrate API calls into the UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25d08b61-2fe1-4de1-a769-17fa29d80266', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Explain the potential risks of using the preprocessor macro system in C.', N'Middle', N'Macros are simple text substitutions that lack type checking and scope awareness, which can lead to hard-to-debug errors. They also risk unintended side effects if arguments are evaluated multiple times, and they do not follow the standard debugger visibility rules, making them difficult to trace during execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e8e9b53-6f17-4e60-8451-17fd1cd73eee', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Does Alpine.js support transitions?', N'Fresher', N'Yes, Alpine.js provides the x-transition directive, which makes it easy to add CSS transitions when elements are shown or hidden. It handles the adding and removing of CSS classes automatically during the transition lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bb64aa5-ec97-4561-8c6a-17fec7f0d4a0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does hoisting affect the execution order of multiple var declarations and function declarations with the same name?', N'Fresher', N'When multiple var declarations or function declarations share the same identifier in the same scope, the engine applies specific precedence rules during the compilation phase: 1. var declarations are merged into one — only one undefined slot is allocated; whichever assignment executes last wins at runtime. 2. Function declarations override var declarations of the same name during hoisting — the function body wins over var''s undefined. 3. Multiple function declarations with the same name: the last one in source order wins (it overwrites the earlier one during hoisting). Example: Why this matters architecturally: In large legacy codebases (pre-modules), concatenating multiple script files together frequently caused silent name collisions of this kind.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4efba2d9-305e-41f2-93d8-18002983152f', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is a Profile in Spring Boot?', N'Intern', N'Profiles provide a way to segregate parts of your application configuration and make it available only in certain environments. You can define separate configurations for development, testing, and production, and activate the desired profile at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e315250-9449-4dac-ae29-1804bd3f02b1', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If an application crashes during a peak traffic event, what steps would you take to identify the cause?', N'Fresher', N'I would first check the system logs to see if there are any error messages or stack traces indicating what went wrong. I would then look at resource utilization metrics, such as CPU and memory usage, to determine if the server ran out of resources or if a specific process caused the crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b067c460-6612-4985-b6c2-180539d1b527', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does the ''CAP theorem'' influence the choice of a database for a global multi-region application?', N'Senior', N'The CAP theorem forces a trade-off between consistency and availability during a network partition. For global applications, choosing AP often leads to eventual consistency via conflict resolution, while CP systems prioritize data correctness at the expense of downtime during cross-region latency spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7644b1d-43d7-4826-98f3-18056775058a', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the purpose of the ''web::Data'' extractor?', N'Fresher', N'The web::Data extractor is used to share application state across different request handlers. It allows developers to inject thread-safe resources, such as database connection pools or configuration settings, directly into the handler function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72f4fde5-1381-4bb4-a71c-180793da36ea', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the ''disconnectedCallback'' method?', N'Fresher', N'The disconnectedCallback is called when the component is removed from the DOM. It is primarily used for cleanup tasks, such as removing event listeners or clearing timers to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec2c1b6f-6a8a-4259-8d9e-1809687074ae', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why is Svelte often considered more ''server-side rendering'' (SSR) friendly than some other frameworks?', N'Middle', N'Svelte can compile components into pure HTML and CSS string templates, which makes the initial render extremely fast and lightweight. This reduces the time-to-first-byte and overall hydration cost compared to frameworks that require sending a large runtime bundle to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76a58864-555a-430a-9cce-1809879a9e65', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do you test asynchronous code in Ember?', N'Middle', N'Ember testing tools provide built-in wait helpers that automatically detect pending network requests and run-loop tasks. This ensures that tests wait for the application to reach a stable state before making assertions, preventing flaky tests caused by timing issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f820c13e-9d09-4aaa-975f-1809ab07de3e', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Are Alpine.js directives case-sensitive?', N'Junior', N'Alpine.js directives are generally written in lowercase, such as x-data or x-show. While HTML is case-insensitive, it is standard practice and recommended to keep all Alpine directives in lowercase for consistency and compatibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
