INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4dcf34cc-9569-4455-9b01-180ced7d2fb6', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is ''Hydration'' in a Nuxt application?', N'Fresher', N'Hydration is the process where the client-side JavaScript takes over the static HTML rendered by the server. It attaches event listeners and makes the page interactive, turning the static content into a fully functional Vue application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa7099a3-356b-4ea7-9485-180ef8a62477', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is middleware in the context of a Fiber application?', N'Junior', N'Middleware are functions that execute before or after the main route handler, allowing developers to inject logic such as logging, authentication, or request modification. They are executed in a chain, and each middleware must call the next function to pass control to the subsequent stage of the request pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1827199-7a1c-4350-8161-180f8fc15d49', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the function of the Write-Ahead Log (WAL) and how does it relate to the checkpoint process?', N'Senior', N'The WAL ensures durability by recording all changes before they are applied to the data files, allowing recovery after a crash. Checkpoints periodically flush the modified data from memory to disk, defining a point in time from which recovery can start and truncating the log.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be68629c-bab5-45a5-b741-1814755a1253', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the significance of the L1/L2 cache locality in high-performance backend development?', N'Senior', N'Cache locality refers to the practice of organizing data in memory such that the CPU can access it from the L1 or L2 cache rather than fetching from main memory. Since cache hits are orders of magnitude faster than RAM access, designing data structures that favor sequential access or compact representation significantly improves execution speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'973698a5-c28b-42ce-b24e-18149d1f1d52', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is a ''Native Executable'' in the Quarkus ecosystem?', N'Intern', N'A native executable is a binary file produced by compiling Java code using GraalVM. Because it includes the application code and the necessary runtime components, it can run on a host machine without requiring a standard Java Virtual Machine to be installed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5c6f431-50c1-453d-99a2-18187a6da55c', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the role of the ''Doublewrite Buffer'' in relation to the ''Redo Log''.', N'Senior', N'The redo log is used to replay transactions after a crash, but it assumes the page data itself is not corrupted. The doublewrite buffer ensures that a full, valid page is written to disk before the redo log is applied, preventing crashes from being unrecoverable due to torn pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9c13543-93db-4abf-81f7-181add753a63', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of a Service in Ember?', N'Intern', N'Services are long-lived, singleton objects used to share state or functionality across different parts of an application. Because they persist for the entire duration of the application''s lifecycle, they are ideal for tasks like managing user authentication, handling browser notifications, or storing global application settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a199b980-0f6e-4374-ae01-181b84bf35b8', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How can you trigger an action when an element initializes in Alpine.js?', N'Intern', N'You can use the ''x-init'' directive to run a JavaScript expression immediately after an element is initialized by Alpine. This is commonly used for fetching data or setting up initial state values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4be4a888-4f82-412b-86b9-181bc6f1c96c', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is it considered a best practice to keep DOM manipulation outside of jQuery''s ''each'' loop?', N'Middle', N'Performing DOM operations inside a loop forces the browser to recalculate the layout repeatedly, which causes significant performance degradation. It is better to build a string or document fragment and append it to the DOM once outside the loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fce6aa21-365c-4320-be1e-181c0a12e1cd', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing an API, how do you balance backward compatibility with the need to introduce breaking changes?', N'Middle', N'You can mitigate breaking changes by versioning the API or introducing new endpoints while maintaining the old ones for a deprecation period. The trade-off is the increased maintenance burden of supporting multiple versions versus the risk of breaking existing client integrations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af022c2e-4ea4-4015-929a-181cda5ff0cb', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the four properties of ACID compliance?', N'Fresher', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably, maintaining data integrity even in the event of errors or system failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'008e821d-35fb-4119-8b38-181eefbd80e5', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the purpose of the ''Arbiter'' in Actix?', N'Middle', N'An Arbiter provides an execution context for actors. It essentially acts as a thread that runs the actor system''s event loop, allowing you to control which threads specific actors are executed on for better resource isolation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbd6f44c-206a-4358-b3cd-1820a140c51d', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Can you use other databases with Remix?', N'Fresher', N'Yes, Remix is database-agnostic. Since the loader and action functions run on the server, you can use any database or API service you choose to fetch or mutate your data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d37fa1c-c143-442f-a449-1821692570ae', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of the ''Model'' hook in Ember''s route lifecycle, and how does it handle asynchronous data fetching?', N'Senior', N'The model hook is responsible for fetching data required for a route to render, and it is natively integrated with Ember''s router transition system. It supports asynchronous operations by pausing the transition until the returned promise resolves, ensuring that the application doesn''t enter a state with incomplete or missing data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf6b3ab0-de0f-4330-8c30-1822c29adc77', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the function of the useLoaderData hook?', N'Junior', N'The useLoaderData hook allows your React components to access the data returned by the loader function. It makes the server-fetched data available for rendering within the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6010f030-a354-4ec8-b06f-1823fb247444', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the role of an ASGI server like Uvicorn?', N'Intern', N'An ASGI server like Uvicorn is required to run the FastAPI application. It acts as the bridge between the internet and the Python code, listening for incoming network requests and passing them to the framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47157666-1143-4b72-8262-18282584f34c', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of the ''this'' pointer?', N'Intern', N'The ''this'' pointer is an implicit parameter available in every non-static member function of a class. It points to the specific object instance that is currently calling the function. It is often used to distinguish between member variables and parameters with the same name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2873f620-4b6b-47a5-a67c-1828a10770df', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you handle service discovery in a dynamic containerized environment?', N'Senior', N'Leverage native service discovery mechanisms provided by container orchestrators or service meshes. These tools automatically register and deregister service instances, ensuring that load balancers and clients always route traffic to healthy endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acc0749f-4fa9-4423-933d-182b60f087c9', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the ''dynamic'' type in Dart?', N'Intern', N'The dynamic type tells the compiler to disable static type checking for a specific variable. This allows the variable to hold any type of value, but it removes the safety benefits of the type system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffc8e317-2900-4f5f-8633-182e36055b95', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'You have a high-traffic service experiencing cascading failures due to a downstream dependency. What architectural patterns would you apply to improve resilience?', N'Senior', N'I would implement the Circuit Breaker pattern to prevent requests from hitting a failing service, combined with bulkhead isolation to contain the failure. Additionally, introducing exponential backoff and jitter for retries ensures the downstream service has space to recover without being overwhelmed by a thundering herd.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8e46198-aeac-4572-9024-182e5285bd90', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the significance of the Spring ApplicationContext and why it is considered a heavyweight object.', N'Senior', N'The ApplicationContext is the central interface for the Spring IoC container, responsible for instantiating, configuring, and assembling beans. It is heavyweight because it performs reflection, scans the classpath, manages dependency graphs, and holds all managed bean instances in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a56b64f1-3b4d-4ad0-8ad8-182f00755208', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the benefit of using Reactive programming in Quarkus?', N'Junior', N'Reactive programming allows Quarkus to handle high concurrency with a small number of threads. It is non-blocking, meaning that while the application waits for I/O operations like database queries or network calls, the thread is freed up to handle other incoming requests, improving overall throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb39dca4-fe0d-4f11-9a58-1830c58572ae', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Explain the role of database vacuuming or compaction in long-term scaling.', N'Senior', N'Periodic vacuuming or compaction reclaims space from deleted or updated rows and prevents fragmentation, ensuring the database engine remains efficient. Neglecting this maintenance leads to ''bloat,'' where storage growth outpaces actual data content, degrading performance and increasing backup durations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e558d0f-b883-41b3-b918-1831734ad677', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What are the trade-offs of using a serverless architecture compared to traditional containerized services?', N'Senior', N'Serverless offers massive operational savings and inherent auto-scaling, but it can introduce cold-start latency and potential lock-in to cloud-provider-specific APIs. Containerized services provide greater control over the runtime environment and portability across clouds but require significantly more management overhead for orchestration and scaling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd15b1ec2-2362-48a8-b94b-1831fca5ccc9', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using an API Gateway versus direct service communication?', N'Middle', N'I use an API Gateway when I need a centralized point for cross-cutting concerns like authentication, rate limiting, and request logging. I consider direct communication only for small internal systems where the added overhead and complexity of a gateway are not justified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afacd6a6-fb11-4b0f-81e8-18326c302d7f', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'In what scenarios would you choose Preact over React for a high-performance frontend architecture?', N'Senior', N'Preact is the superior choice when the primary constraints are initial load time, memory usage on low-end devices, or when building small-to-medium sized components embedded in larger legacy pages. Its minimal footprint makes it ideal for performance-budgets where every kilobyte of JavaScript impacts conversion rates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2c82886-37ff-4c0d-95b4-183457a86c09', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does multi-version concurrency control (MVCC) function in a distributed NoSQL environment?', N'Senior', N'MVCC allows multiple versions of a record to coexist, enabling readers to access a consistent snapshot of the data without blocking writers. In NoSQL systems, this often facilitates lock-free reads and simplifies conflict resolution in multi-master replication scenarios by allowing the system to track version history.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'caf115a3-939c-4e4c-adc8-18378f716f38', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the difference between HotSpot and native mode?', N'Intern', N'HotSpot mode runs on a standard Java Virtual Machine, allowing for dynamic class loading and better peak performance over time. Native mode uses Ahead-of-Time compilation to produce a standalone binary with rapid startup and low memory usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f63c861-1e22-451e-b233-18394ca24971', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is tweening in css?', N'Intern', N'The pose-to-pose option is to create a few keyframes throughout the sequence, and then fill in the gaps later. Filling in these gaps is known as tweening. It is the process of generating intermediate frames between two images. It gives the impression that the first image has smoothly evolved into the second one. In CSS3, Transforms (matrix, translate, rotate, scale etc.) module can be used to achieve tweening. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
