INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4103366c-7830-4f1f-96de-183f5f382a45', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB ensure ''Data Integrity'' during an unexpected power failure?', N'Senior', N'MongoDB uses a write-ahead log (journal) that records operations before they are applied to the data files. Upon restart, the system replays the journal to reconstruct the state of the database, ensuring that any committed writes are recovered even if they were not yet flushed to the main data files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7854d7ce-8db8-4c1a-9cf9-183fa5192578', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are the limitations of FastAPI''s automatic validation when dealing with complex, nested data structures?', N'Senior', N'While Pydantic handles complex nested models well, deeply recursive structures can lead to performance overhead and complex error messages. For extreme cases, manual validation or schema optimization might be required to ensure the system remains performant and debuggable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8672ce4-e3c5-4ac3-94bf-184155bd4ec2', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the benefit of using ''Result'' as a return type in Axum handlers?', N'Middle', N'Returning a Result allows you to propagate errors from your business logic to a centralized error handling mechanism. If the error type implements ''IntoResponse'', Axum can automatically convert it into an appropriate HTTP error code and message.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8a87df6-b7f7-4579-b31b-1841a90d98f9', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Explain the difference between LRU and LFU eviction policies.', N'Middle', N'LRU evicts keys based on the time since they were last accessed, assuming recently used data is likely to be needed again. LFU evicts keys based on the frequency of access, which is often more effective when certain keys are accessed infrequently but are still considered ''important'' for the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da6b5299-ea4b-48c8-81fa-184253f14ad5', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the trade-off between performance and maintainability?', N'Intern', N'Highly optimized, high-performance code can sometimes be complex and difficult to read, which increases the time required for future maintenance. A balance must be struck where the system is fast enough to meet requirements while remaining readable and easy to update.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
