INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'173596f2-c029-4b6c-90d8-18459a639870', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between a compiler and an interpreter?', N'Intern', N'A compiler translates the entire source code into machine code before execution, creating an executable file. An interpreter translates and executes the source code line-by-line during runtime, which is generally slower.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
