INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e06a4be-9328-4fd8-aa27-184be225b540', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between get and defineProperty?', N'Fresher', N'Both has similar results until unless you use classes. If you use get the property will be defined on the prototype of the object whereas using Object.defineProperty() the property will be defined on the instance it is applied to.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a4a5bfa-0efc-4100-be3c-184e8d533b73', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the trade-off between strong consistency and high availability in a distributed system?', N'Senior', N'I evaluate this through the lens of the CAP theorem, assessing whether the business requirements prioritize data accuracy over uptime during network partitions. If the system supports critical financial transactions, I lean towards strong consistency via consensus algorithms, whereas for high-traffic read-heavy services, I prioritize availability and eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd45254e8-9089-48e7-bd43-184ea048f18e', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain the meaning of each of these CSS units for expressing length?', N'Fresher', N'* centimeters * elements (i.e., relative to the font-size of the element; e.g., 2 em means 2 times the current font size) * inches * millimeters * picas (1 pc = 12 pt = 1/6th of an inch) * points (1 pt = 1/72nd of an inch) * pixels (1 px = 1/96th of an inch)', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
