INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9dfbabe4-1ee3-4b81-b1f0-18557e16c406', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does horizontal scaling affect transactional integrity?', N'Middle', N'Maintaining ACID compliance across multiple shards is difficult because traditional two-phase commit protocols can introduce significant latency. Often, distributed systems settle for ''eventual consistency'' to maintain high availability and performance across the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
