INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3059ab9-ff59-4d17-870a-186e5f74cce6', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the primary goal of database sharding?', N'Middle', N'Sharding is the process of splitting a large database into smaller, more manageable pieces called shards across multiple servers. Its goal is to improve read and write performance by distributing the data load and overcoming the limitations of single-node storage and throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4624722-1b53-4951-81ed-186fdffe3919', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro handle state management across multiple disjointed islands?', N'Senior', N'Since islands are isolated and do not share a single runtime, state cannot be shared via standard framework context providers. Developers must use browser-native primitives like Custom Events, the Storage API, or external state managers that utilize the global scope to synchronize data between islands.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db19e8f4-55fd-454d-ad20-18734f329cb6', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'In the context of database replication, what is the difference between synchronous and asynchronous replication?', N'Senior', N'Synchronous replication ensures that a transaction is committed on both the primary and replica before acknowledging success, guaranteeing zero data loss but increasing write latency. Asynchronous replication acknowledges the write immediately upon local commit, offering lower latency but risking data loss if the primary fails before the replica updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
