INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'403794d3-1546-47de-8ab6-1874ffde6a4e', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the primary purpose of a Primary Key?', N'Intern', N'A primary key is a specific column or set of columns in a table that uniquely identifies each row. It ensures that no two rows have the same identifier, which is essential for maintaining data integrity and linking tables together.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef908891-c6f3-409c-b321-187519c4577b', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle a situation where you have conflicting feedback from two different team members?', N'Intern', N'I would schedule a brief meeting with both individuals present to discuss the feedback. By facilitating a conversation where both perspectives are heard, I can help the team reach a consensus or ask for a final decision from a lead to resolve the conflict.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cde43ff-bc4c-4fe8-8d88-18754f93ae47', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why do many NoSQL databases choose Eventual Consistency over ACID transactions?', N'Middle', N'NoSQL databases often prioritize high availability and partition tolerance, as dictated by the CAP theorem. By relaxing the requirement for immediate global consistency, these systems can offer lower latency and higher write throughput, which is essential for distributed architectures where waiting for a consensus across nodes would create unacceptable performance bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'647875d2-216a-4487-b0d0-1876f2cb6c6d', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is a ''Transpilation'' step in Vite?', N'Intern', N'Transpilation is the process of converting modern JavaScript or TypeScript syntax into a version compatible with older browsers. Vite handles this automatically, ensuring your modern code works in the environments you specify.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2179ebcd-0a88-498a-80c5-18775f1481de', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are the drawbacks of relying heavily on Sass features that do not exist in native CSS?', N'Senior', N'Over-reliance on Sass-specific features can lead to vendor lock-in and a bloated build pipeline. As native CSS evolves to include features like nesting, variables, and color functions, these Sass abstractions may become redundant or even negatively impact performance if they are not transpiled efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e27bf1f3-a861-4cfa-9afa-187a49faed0b', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is meant by a ''Read-Only'' transaction?', N'Junior', N'A read-only transaction is a transaction that only retrieves data from the database without performing any modifications. These are often optimized by the database engine since they do not require write locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41c86883-858a-44b9-9543-187b14892405', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Why is Dart''s ''async/await'' implementation considered ''non-blocking''?', N'Senior', N'When an ''await'' expression is encountered, the execution of the current function is suspended and the function returns a Future, allowing the event loop to pick up other pending tasks. This ensures the main execution thread remains responsive to user input and other events while waiting for I/O or timer completion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aedaf80a-6d9b-4db6-b04b-187c0655d568', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is an Interface in C#?', N'Intern', N'An interface is a contract that defines a set of methods and properties that a class must implement. It allows for multiple inheritance of behavior, enabling different classes to share common functionality without sharing a specific implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74bea9cc-c040-437c-a97f-187eb7583338', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the difference between Dart Sass and LibSass in a modern enterprise context?', N'Senior', N'Dart Sass is the current primary implementation and the only version that receives new features and support. LibSass is deprecated and does not support many of the modern Sass features like the module system, making Dart Sass the only viable choice for modern projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81abbf5b-75b1-40c0-a483-187f3b5ff980', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does C address the issue of floating-point precision differences across hardware?', N'Senior', N'C provides the float.h header to define implementation-specific limits, but the language allows excess precision for intermediate calculations. This means that code can produce different results on different hardware platforms, necessitating the use of specific compiler flags to enforce strict IEEE-754 compliance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55533a01-9cc0-4cc9-be9d-187f9d5ee8ea', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the role of the ''npm'' utility in a backend environment?', N'Intern', N'NPM stands for Node Package Manager and serves two main purposes. It is an online registry for sharing open-source JavaScript packages, and it is a command-line tool that allows developers to install, manage, and remove those packages within their local projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2cf0cd0-7c56-4e4b-8697-1881355880bc', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the trade-off of using Hono''s middleware architecture compared to the standard Express middleware pattern?', N'Middle', N'Hono uses a ''next'' function-based middleware approach similar to Express, but it is designed to be lightweight and strictly typed. While this provides excellent developer experience and type safety, the trade-off is that developers must be more mindful of memory usage and execution order, as Hono''s lightweight design lacks the extensive ecosystem of pre-built, heavy-duty plugins found in more mature, older frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5809ec5f-dbc1-43fa-a766-18814b0bb806', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the purpose of the async and await keywords?', N'Intern', N'These keywords provide a way to write asynchronous code that looks and behaves like synchronous code. They make it easier to read and maintain logic that depends on background tasks finishing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad39ec7c-63a9-4370-823f-188396419e3c', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the difference between an API and an RPC?', N'Middle', N'An API generally refers to a set of rules for interacting with a system, often using RESTful patterns, while RPC (Remote Procedure Call) is a protocol that allows a program to execute a function on a remote server as if it were local. RPC is often more performant due to binary serialization, whereas REST is more interoperable and standard for web services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58264f22-ff33-4cda-a975-1884cd01f335', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is a borrow checker?', N'Intern', N'The borrow checker is a part of the Rust compiler that ensures all references to data remain valid. It validates that data is not modified or destroyed while other parts of the code are still using it, preventing data races.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd924e038-141d-4d8e-a183-1885655befaa', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the pros and cons of using Rails Engines for modularity?', N'Middle', N'Rails Engines allow developers to package functionality into isolated components with their own routes, models, and controllers, promoting code reuse across multiple applications. The downside is increased complexity in managing dependencies, configuration, and potential naming collisions between the engine and the host application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d21af91-21eb-4d84-ad0e-1885cac2a756', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the role of an autoloader?', N'Junior', N'An autoloader automatically loads class files when they are needed, removing the need for manual ''include'' or ''require'' statements for every class. Most modern PHP projects use the Composer autoloader to handle this dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2be01f62-afab-44ed-bd95-1887616eca48', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Could you explain what a goroutine is?', N'Junior', N'Goroutines are lightweight threads or, more accurately, cooperative concurrent functions in Golang that manage their execution. They allow for independent code segments to execute concurrently. Key Characteristics - Efficiency: Goroutines are more memory and processing efficient than traditional threads because they''re multiplexed over a small number of OS threads. - Go Select-Weile: Concurrency and communication between Goroutines are elemental in Go, often achieved through channel communication and the select statement. Setup and Control Goroutines are created using the go keyword, which precedes a function call. The process involves the Go runtime, making Goroutines distinct from typical functions. - Simplicity: The process of creating and controlling Goroutines is streamlined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fb0f8f1-e9c1-405e-82c3-1887f2903303', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What are ''DTOs'' (Data Transfer Objects) used for in Litestar?', N'Junior', N'DTOs are used to define the contract for data moving in and out of your API. They help separate your internal database models from the structure exposed to the client, allowing you to hide sensitive fields or reformat data for the frontend.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c5b05a1-d041-44e3-aea3-1888f4bd91db', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Why would you choose to use ''Try'' instead of standard try-catch blocks?', N'Middle', N'The Try type treats exceptions as data, allowing them to be passed around, transformed, and composed using functional combinators. This avoids the disruptive control flow of traditional exception handling and integrates well into functional pipelines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f71f379-7f2d-44fc-be45-188bacd8fc75', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the role of ''Dispatchers'' in coroutines?', N'Middle', N'Dispatchers determine which thread or thread pool a coroutine executes on. They ensure that tasks like UI updates, I/O operations, or heavy computations are assigned to the appropriate thread, preventing blocking and improving performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19577651-f2e3-42c8-af73-188c5d221a73', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do optional properties work in TypeScript interfaces?', N'Fresher', N'Optional properties are denoted by adding a question mark after the property name in an interface or type definition. This signals to the compiler that the property may or may not be present in an object, preventing errors when accessing it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f6a24df-a082-4a92-a36b-188ccea60821', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the architectural trade-offs of using a Search engine (like Elasticsearch) alongside a primary database?', N'Senior', N'Using a search engine enables complex full-text and faceted search capabilities that relational databases struggle to perform. However, it introduces the challenge of data synchronization, requiring an ETL or change-data-capture (CDC) pipeline that can lead to a lag between the primary store and the search index.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd768edec-af21-49e2-a105-188daf71f1f4', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of ''DEBUG = True''?', N'Intern', N'Setting debug to True displays detailed error pages with stack traces when an error occurs. It should only be used during development because it can expose sensitive configuration information to users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ccf9e52-306b-4e12-be37-188ef9a15045', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How can you implement rate limiting in a FastAPI application, and where should this be positioned in the architecture?', N'Senior', N'Rate limiting is best implemented as middleware or via a shared store like Redis for distributed consistency. Placing it at the middleware layer ensures that requests are dropped before reaching the application logic, protecting the server''s CPU and memory resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26a81996-4300-442e-8f65-18912962ebb8', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of the Ember ''Outlet''?', N'Middle', N'An outlet is a placeholder in a parent template that dictates where a child route''s template should be rendered. It allows the application to compose complex layouts by nesting templates dynamically based on the current URL state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7710081f-7848-452d-9339-1892ad98b145', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does the ''DefinePlugin'' operate, and why is it essential for environment-specific builds?', N'Senior', N'DefinePlugin performs a direct text replacement of variables within the code during the compilation phase. It is essential for injecting environment-specific constants, like API endpoints or feature flags, allowing Webpack to prune unreachable code branches via dead code elimination.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8490b256-b70e-4c11-bc3a-1895d150a8c6', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the difference between magic properties and standard component properties?', N'Middle', N'Magic properties, prefixed with a dollar sign, are globally available utilities provided by Alpine for common tasks like event dispatching, element selection, or accessing the current state. Standard component properties are the specific data and methods defined by the developer within the x-data object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'548c2c4b-0f43-4104-bc25-189605306628', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are ''custom elements'' in the context of Web Components?', N'Middle', N'Custom elements allow developers to define their own HTML tags and associate them with custom behavior. By extending the browser''s native capabilities, they promote the creation of modular, reusable, and encapsulated UI components that function across different frameworks. They rely on standardized browser APIs to register and manage these tags within the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be09fc06-1e2c-455a-8228-18970fc0ed19', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How do Webpack ''Resolvers'' work, and how can they be optimized to reduce build time?', N'Senior', N'Resolvers map file paths to absolute paths by applying extensions and alias logic. Build time is reduced by minimizing the number of directories searched and using absolute paths for aliases to prevent the resolver from performing costly file system crawls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ecf1786-c7da-4ace-8f88-189775023da2', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is an AdonisJS Factory?', N'Intern', N'Factories are used to generate fake data for models, which is particularly useful for seeding databases or writing automated tests. They allow you to create test data quickly without manually inserting records into the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4272a85e-1c67-4003-a39c-189afb55391d', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Compare the performance overhead of std::function against a raw function pointer or template-based functor.', N'Senior', N'std::function introduces type erasure, which usually involves heap allocation and virtual function calls to invoke the underlying callable, causing performance overhead. In contrast, template-based functors allow the compiler to inline the call, and raw function pointers provide a direct, low-overhead jump, making templates superior for performance-critical hot paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79ac9739-a5e6-4ef7-a0fd-189c22a71a23', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why is the order of middleware important in Express?', N'Intern', N'Express executes middleware functions in the order they are defined. If a piece of middleware sends a response or ends the request cycle, subsequent middleware functions will not be executed for that request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb4d8859-91b4-408e-8b52-18a3bae74683', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Describe the impact of Laravel''s middleware stack on request lifecycle performance and how you would optimize it for high-traffic applications.', N'Senior', N'Each middleware adds a layer of execution overhead to every incoming request. To optimize, global middleware should be strictly limited, and route-specific middleware should be used to ensure unnecessary logic is bypassed, potentially leveraging caching layers or lightweight micro-services for static request handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0c3a4c1-89bd-41be-b0f7-18a9b6f3d1b1', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle a request for a ''quick fix'' that you know will cause long-term issues?', N'Junior', N'I explain the trade-offs to the stakeholder, highlighting the potential for future bugs or maintenance overhead. I propose a balanced solution that addresses the immediate need while minimizing long-term damage, or I suggest documenting the shortcut as a task to be refactored later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41d5b0af-d2f5-4c9c-8cea-18a9e158e20c', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How would you design a scalable background task system for a Django application?', N'Senior', N'For scalable tasks, offload processing to a dedicated worker system like Celery or Dramatiq using a message broker like RabbitMQ or Redis. This decouples long-running logic from the request-response cycle, allowing the application to respond quickly while tasks are processed asynchronously by separate worker nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad4584bd-5c60-4b03-9c7a-18aa49078c43', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the difference between a write and a read operation in Cassandra?', N'Fresher', N'A write operation is always successful and fast because it is appended to the commit log and memtable. A read operation might be slower if the system has to scan multiple SSTables or perform read repairs to ensure consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b56256f-b1e8-493d-b00d-18ac11453eca', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between static and dynamic dispatch in Swift?', N'Middle', N'Static dispatch happens at compile time, allowing the compiler to inline code and perform optimizations, making it very fast. Dynamic dispatch is resolved at runtime via a vtable or witness table, providing the flexibility needed for polymorphism but incurring a small performance cost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1ee8d50-29d5-4f6d-9cc4-18ad090229ed', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the concept of ''zero values'' in Go and why they are important.', N'Middle', N'Every variable in Go is automatically initialized to its zero value upon declaration, ensuring that the language is safe and predictable. This eliminates the risk of using uninitialized memory and simplifies code by removing the need for explicit initialization logic in many cases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'993ad686-9204-4f74-946e-18ae35cc06a7', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the architectural significance of the Ruby VM (YARV) using an instruction-based stack machine rather than a register-based model?', N'Senior', N'A stack-based VM simplifies the compilation process and keeps the instruction set small and platform-independent. While it may require more operations per task than a register-based model, it aligns well with Ruby''s dynamic nature and the need for frequent object allocation and method dispatching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbf2bfaa-6ab0-4e62-b02f-18afdd042d7d', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is it important to use ''Helmet'' or similar middleware in an Express application?', N'Middle', N'Helmet helps secure Express apps by setting various HTTP response headers, such as Content-Security-Policy and X-Frame-Options. These headers protect the application from common web vulnerabilities like cross-site scripting (XSS), clickjacking, and other code injection attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e49942ad-6332-40e0-8e3b-18b3e577703a', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the primary purpose of the Lit library in web development?', N'Fresher', N'Lit is a lightweight library used for building fast, lightweight web components. It provides a base class that simplifies the process of managing reactive properties, handling component updates, and rendering HTML templates using native browser APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'858ea0b8-8298-4d1e-b0f3-18b48727e709', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is meant by ''capacity modes'' in DynamoDB?', N'Intern', N'Capacity modes determine how you are billed and how your tables handle request volume. The ''On-Demand'' mode automatically scales to accommodate traffic spikes, while the ''Provisioned'' mode allows you to specify the exact amount of read and write capacity units you expect to need.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
