INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b54467e-8a0c-400c-9207-18b55fdd9562', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between ''delete'' and ''delete[]''?', N'Fresher', N'The ''delete'' operator is used to deallocate memory for a single object, while ''delete[]'' is used to deallocate an array of objects. Using the wrong one can lead to undefined behavior and memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcc6f07c-77b1-402b-aa92-18ba57067572', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind CSS achieve small bundle sizes despite having thousands of available utility classes?', N'Middle', N'Tailwind utilizes PurgeCSS or its internal JIT engine to scan project files for class names and includes only the CSS that is actually used in the final production build. This tree-shaking process ensures that the CSS bundle size remains constant regardless of the size of the project or the number of utility classes available in the configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b54b5023-770a-49f1-84b9-18bb3121e6d0', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Discuss the ''satisfies'' operator and why it is superior to type casting for configuration objects.', N'Senior', N'The ''satisfies'' operator validates that an expression matches a type without losing the specific literal types of the properties. Unlike explicit casting, it provides type safety while ensuring that the inferred type remains as specific as possible, which is ideal for configuration objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
