INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a2ffd94-da41-4a22-bb53-18be6513af65', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut support multi-tenancy in backend applications?', N'Middle', N'Micronaut provides built-in support for multi-tenancy through a tenant resolver interface. It can resolve the current tenant based on headers, subdomains, or custom logic, allowing for seamless isolation of data and configuration across different requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
