INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cd169ad-96f4-43a4-956a-18c5ff7556ac', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Why is it recommended to use the ''goto'' function instead of standard anchor tags for internal navigation?', N'Middle', N'The ''goto'' function allows for programmatic navigation that integrates with SvelteKit''s router, enabling features like smooth transitions and data prefetching. While anchor tags are fine, ''goto'' provides more control over the navigation process within your application''s logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af6d5c9a-94d3-46be-b012-18c7e409224a', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are the risks of overusing implicit conversions in a large Scala codebase?', N'Senior', N'Overusing implicit conversions can create code that is highly opaque and difficult to reason about, as the compiler silently modifies types. This obscures the actual data flow, leading to increased cognitive load for developers and potential runtime errors that are obscured by the compiler''s automatic transformations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7cd443e-ddec-4518-87d0-18c8c98527ab', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the role of the ''trust proxy'' setting in Express, and why is it critical for cloud-native deployments?', N'Senior', N'The ''trust proxy'' setting tells Express to trust headers like X-Forwarded-For set by reverse proxies or load balancers. Without it, Express may incorrectly identify the client''s IP as the load balancer''s IP, breaking rate limiting, logging, and security policies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad848f67-a6e4-4053-900e-18c969eb7c39', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you design a system to support zero-downtime deployments?', N'Senior', N'I utilize blue-green or canary deployment strategies orchestrated by a load balancer or service mesh. By routing traffic incrementally to the new version and performing automated health checks, I can safely roll back if errors spike, ensuring the user experience is never interrupted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'013d8943-ef43-429c-9dc7-18d025b05a00', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the primary benefit of keeping the Redux state flat?', N'Junior', N'Keeping the state flat reduces complexity when updating nested data. It makes it easier to write immutable updates without needing deep copies, which in turn improves performance and makes the code more readable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61c79338-7114-4fd5-b0b2-18d0bd61af85', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar utilize dependency injection compared to other Python frameworks?', N'Middle', N'Litestar uses a type-hint-driven dependency injection system that resolves dependencies at runtime based on signatures. It allows for modular, reusable providers that can be scoped to routes, controllers, or applications, promoting cleaner separation of concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1726264-1b8f-457f-8dec-18d336d2dae2', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is a Controller in NestJS?', N'Intern', N'Controllers are responsible for handling incoming requests and returning responses to the client. They use routing mechanisms to control which controller receives which requests, effectively acting as the interface between the client and the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e972683-0309-4262-b561-18d44d65936b', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do you organize a Sass project for maximum maintainability?', N'Middle', N'The 7-1 pattern is a standard architecture where styles are split into seven folders representing different concerns like base, components, layouts, and abstracts. This ensures that developers can quickly locate relevant files and keeps the codebase modular and scalable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c7773df-cbc4-44e7-a442-18d4e6609ef9', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach estimating the time required for a task you have never performed before?', N'Fresher', N'I would research the task to understand its basic components, look for similar tasks I have completed, and consult with someone experienced in that area. I would then add a larger buffer for ''unknown unknowns'' until I gain more clarity on the actual effort required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5bdfd34-0017-4fb0-a88f-18d61bf1c90d', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does the Redux ''single source of truth'' principle benefit application architecture?', N'Middle', N'Maintaining the entire state of the application in a single store makes it easier to debug and inspect the state at any given point in time. It also enables powerful features like server-side rendering and time-travel debugging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45733bc6-5a01-40e0-84a2-18d94c589b29', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are the trade-offs of using Django''s built-in authentication system for large-scale enterprise applications?', N'Senior', N'The built-in system is convenient and secure for standard use cases but can be rigid when integrating with complex external identity providers or fine-grained RBAC/ABAC requirements. Enterprises often find themselves overriding the User model or replacing the authentication backend entirely to meet specific compliance or scaling needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37e1ed2b-ba32-4b40-ad81-18db376f5f49', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do you handle global styles in a Shadow DOM-encapsulated component?', N'Middle', N'You can inject global styles using the ''adoptedStyleSheets'' API or by importing CSS modules inside the component''s style property. This allows shared themes to be applied consistently across encapsulated components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ae6a969-3b9b-4938-8a9c-18ddb8de24d5', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are Rust references and how do they work?', N'Fresher', N'References allow you to access data without taking ownership of it, a process known as borrowing. Rust enforces strict rules where you can have either one mutable reference or any number of immutable references to a piece of data at any given time, which prevents data races.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ce7f52d-b02c-4670-85da-18dde17a1c49', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does the ''void'' return type signify?', N'Junior', N'The ''void'' type indicates that a function does not return any value. It is commonly used for functions that perform side effects, such as logging to the console or updating the DOM, without needing to pass data back to the caller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
