INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1eef10c-5c5c-4e5c-8682-18e94a69874f', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the trade-offs of using templates in C++?', N'Middle', N'Templates allow for generic programming and compile-time type safety, resulting in highly efficient code tailored to specific types. The trade-offs include significantly longer compilation times and larger binary sizes due to the compiler generating code for every instantiated type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53f7f474-1203-4c09-8984-18e99efa17ef', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is line-height and how does it affect text?', N'Intern', N'line-height controls the height of a line box, which affects the vertical spacing between lines of text. It can be set as a unitless number, percentage, length, or keyword. Recommended values: 1.4–1.6 for body text for readability. Unitless values are preferred because child elements inherit the multiplier, not the computed value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76402cfc-cbd7-498d-b3ed-18ea46fc4565', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the difference between variable shadowing and scoping in Sass modules?', N'Middle', N'In Sass modules, variables are scoped to the file where they are defined. Variable shadowing occurs when a local variable shares the same name as a module-level variable, which can lead to confusion; using explicit namespaces with @use prevents this by requiring a prefix.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12bd9ebc-1e50-484a-aab1-18ede28658d0', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the primary architectural difference between stateless and stateful authentication?', N'Middle', N'Stateless authentication uses tokens like JWTs that contain all necessary user information, allowing the server to verify requests without querying a database. Stateful authentication relies on server-side sessions stored in memory or a database, requiring a lookup for every request to validate the session ID.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80b75619-cdb0-4fbe-b670-18efac7c07b5', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does the ''Either'' type improve error handling?', N'Middle', N'Either is a type that can hold one of two values, typically used to represent a successful result or an error message. By convention, ''Left'' is used for the error and ''Right'' for the success, allowing the caller to chain operations while explicitly acknowledging potential failure paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'598ca4db-ff17-4e05-939a-18f00e794f83', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Explain the concept of ''tick'' in the context of Svelte''s update cycle.', N'Senior', N'Svelte updates the DOM asynchronously, batching changes to improve performance. The tick function returns a promise that resolves after any pending state changes have been applied to the DOM, allowing developers to perform actions that depend on the updated UI state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acdf744f-3b56-4513-b87c-18f084862158', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono simplify the implementation of ''Zero-Trust'' networking in microservices?', N'Senior', N'Hono provides middleware hooks that can easily validate JWTs, mTLS, or custom headers at the entry point of every route. By applying these policies as part of the middleware stack, developers ensure that authorization is enforced consistently across the entire service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'765c864e-8125-484d-9bab-18f092f83315', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the difference between a Component and a Helper in Ember?', N'Middle', N'Components are used for reusable UI elements that have their own state and lifecycle hooks. Helpers are lightweight, functional utilities designed to transform data or perform simple logic directly within a template without managing complex internal state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd6be704-0a10-4e9d-8604-18f64458a831', N'4c000000-0000-0000-0000-000000000005', N'Explain the architectural implications of choosing between a Leader-Follower and Multi-Leader replication model.', N'Senior', N'Leader-Follower simplifies consistency but creates a single point of write contention and potential bottleneck. Multi-leader replication increases write availability and proximity to users but introduces significant conflict resolution challenges and risks of write divergence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e84d887b-6bdd-45ec-82e8-18f6c8854d5b', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Discuss the ''client:visible'' directive and its impact on the Critical Rendering Path.', N'Senior', N'The ''client:visible'' directive uses the Intersection Observer API to delay component hydration until the element enters the viewport. This keeps the initial bundle size minimal and defers non-critical JavaScript execution, significantly improving the Largest Contentful Paint metric.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd58edf2-3c4e-4142-9ba7-18f6c8bd9f1c', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the ''Repository Pattern'' in the context of Laravel and why it is sometimes considered an anti-pattern by the community.', N'Senior', N'The Repository Pattern aims to abstract data access, but because Eloquent is already a sophisticated implementation of the Active Record pattern, adding a repository layer often creates redundant code and loses the expressive power of the ORM. It is often seen as unnecessary boilerplate unless the project requires switching persistence layers entirely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'055bd08e-89e4-4e20-b590-18f91670f1b3', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle props, and why can you not destructure them directly?', N'Middle', N'SolidJS props are reactive objects that use getters to track access. If you destructure them in the function arguments, you lose that reactivity, causing the component to stop responding to parent updates; you must use the ''splitProps'' or ''mergeProps'' utilities instead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70cfe75c-f9d8-4b1f-baec-18f95bdf3b75', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'When should you use Django’s cache framework instead of database-level caching?', N'Middle', N'You should use the cache framework when you need to store results of expensive calculations or frequently accessed data that rarely changes. It is superior to database-level caching because it reduces the load on the database engine entirely by retrieving data from faster, in-memory stores like Redis or Memcached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df325cd7-8d75-4486-9b66-18faa2c545b3', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are ACID properties?', N'Intern', N'ACID stands for Atomicity, Consistency, Isolation, and Durability, which are the fundamental principles of database transactions. These properties ensure that database operations are reliable and maintain data integrity even in the event of errors or system failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be4b59fe-1ef5-4d8a-91c0-18fcf8833956', N'4c000000-0000-0000-0000-000000000005', N'Why would you implement a CDN in your system architecture?', N'Middle', N'A CDN reduces latency by caching static assets at edge locations closer to the user. This decreases the load on your origin servers and improves performance by minimizing the physical distance data must travel.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bb6e583-d4cc-4b37-a345-18fd5d390bb7', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does ''npm install'' manage package versions?', N'Junior', N'Npm uses the package-lock.json file to ensure consistent installations by recording the exact version and dependency tree used. It follows semantic versioning rules, where specific symbols determine if minor or patch updates are allowed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33a32013-b00a-422e-8bb7-19023f465c79', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Can Gin handle different HTTP methods for the same path?', N'Intern', N'Yes, Gin allows you to define different handler functions for the same URL path based on the HTTP method used, such as GET, POST, PUT, or DELETE. This is a fundamental aspect of RESTful API design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'394fc507-680f-41f8-87e1-1908fb2287b5', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit''s ''page data'' system optimize bandwidth and performance?', N'Senior', N'SvelteKit serializes the ''load'' function data into the initial HTML, preventing the need for the browser to make a second network request for data after the page loads. This ''hydration'' process ensures that the client-side application is immediately interactive with the correct data state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac2659a7-f8c4-43e6-9c39-190be6afb823', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala''s ''Future'' abstraction manage context propagation in highly concurrent systems?', N'Senior', N'Scala Futures utilize ExecutionContexts to manage thread pools and scheduling, effectively decoupling task definition from execution logic. Context propagation, such as thread locals, is difficult because Futures are inherently asynchronous and may execute on different threads. Developers must often explicitly pass tracing or security context through the Future chain or use specialized libraries to maintain consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e941c8eb-464e-4ae3-b11a-190cbbde68ff', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What does ''document-oriented'' mean?', N'Intern', N'Document-oriented means that the database stores information in documents rather than rows and columns. This approach allows related data to be nested within a single document, reducing the need for complex joins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f07479b-672c-4b7f-9f73-190d9a44922d', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'When should you avoid using schema-based validation in Fastify?', N'Middle', N'Schema validation should be avoided only when the request body is extremely dynamic, unpredictable, or too large to be efficiently parsed. In such rare edge cases, standard Node.js stream handling or custom middleware might be preferred to avoid the performance cost of schema compilation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60f888dd-2a64-4bf8-b833-190db16dabbe', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the COMMIT and ROLLBACK commands?', N'Fresher', N'COMMIT is used to permanently save the changes made during the current transaction to the database. ROLLBACK is used to undo changes made during the current transaction, returning the database to its state before the transaction began.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a249a82-bde0-455f-b325-190fea6a0293', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the difference between Unit, Integration, and Acceptance tests in Ember?', N'Middle', N'Unit tests focus on individual functions or classes in isolation. Integration tests focus on how a component interacts with the template and parent context. Acceptance tests simulate full user workflows by navigating through the application and interacting with the UI as a user would.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6ba6ad2-35f2-49b8-b24c-1916a0eedc3f', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the impact of Tailwind''s ''plugin'' system on project scalability?', N'Senior', N'Plugins allow for the encapsulation of reusable component logic and custom utilities. This promotes modularity, as complex or repetitive design patterns can be packaged as a plugin and shared across multiple projects, ensuring consistent implementation of custom logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'717d5d6a-ab78-4bca-a917-1916b277490b', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the primary purpose of a bundler in frontend development?', N'Intern', N'The primary purpose is to combine multiple files into a single bundle to reduce the number of HTTP requests a browser must make. It also allows developers to use modern JavaScript features and modular code structures that are not natively supported by all browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9db18b81-8651-47c8-a362-1916e6be4ea0', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the significance of the 3rd Normal Form (3NF)?', N'Middle', N'3NF requires that a table is in 2NF and that all non-key attributes are functionally dependent only on the primary key. This eliminates transitive dependencies, ensuring that each piece of data is stored in exactly one place and reducing update anomalies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'180b7fa5-6e4b-4729-8c46-19175a76f110', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are lifecycle methods in Preact?', N'Intern', N'Lifecycle methods are specific hooks or methods that trigger at different stages of a component''s life, such as when it is added to the DOM or updated. They allow you to perform actions like fetching data or cleaning up resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd405f368-dd11-4b05-93ed-1919a9304126', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is meant by ''Resumability'' in the context of Qwik?', N'Fresher', N'Resumability is the ability of an application to pause its execution on the server and resume exactly where it left off on the client. It eliminates the need for ''hydration'' because the framework serializes the state and event listeners into the HTML, allowing the browser to pick up the execution without re-running the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'132618d9-787d-4907-971b-1919a9cb0ba8', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s ARC manage memory for closures, and what are the implications of capture lists?', N'Senior', N'ARC manages closures by tracking the reference count of captured variables, which can lead to strong reference cycles if an object captures self strongly. Capture lists allow developers to explicitly define the memory management semantics, such as weak or unowned, to break these cycles and prevent memory leaks. This is essential for preventing retain cycles in non-trivial object graphs where closures are stored as properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ded531dc-f656-4945-882a-1919c920c796', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What approach do you take when a project is behind schedule and critical features are still incomplete?', N'Middle', N'I perform a triage of the remaining work to identify the absolute minimum functionality required for a launch. I discuss with stakeholders the possibility of a phased release, focusing on delivering the most valuable components first and pushing lower-priority items to a follow-up release.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54e648a4-0504-43a6-8b6d-1919e1209079', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are the trade-offs of using ''final'' versus ''sealed'' modifiers in Scala class hierarchies?', N'Senior', N'A ''final'' modifier prevents inheritance entirely, which can be useful for performance optimization and API constraints. A ''sealed'' modifier restricts inheritance to the same source file, enabling the compiler to check for exhaustive pattern matching, which provides stronger architectural safety for domain modeling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8e01bfe-ea41-422e-a6a3-191ad53de60c', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are Symfony Annotations or Attributes?', N'Intern', N'Attributes are metadata added directly above classes, methods, or properties to configure behavior. They are commonly used in Symfony to define routes, security permissions, or database mappings directly in the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27ea5b24-7fbd-4e64-90fd-191bcee80371', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind handle responsive design compared to media queries in standard CSS?', N'Middle', N'Tailwind uses a mobile-first approach where responsive modifiers are prefixed to utility classes. This allows developers to define different styling behavior at specific breakpoints directly within the markup, rather than writing standalone media query blocks in separate CSS files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e3bd8ea-13f2-4a3b-b922-191d6eb13194', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Explain the role of Alpine.js plugins and their architectural benefits.', N'Senior', N'Plugins allow developers to extend the core functionality of Alpine without bloating the base bundle for users who do not need those features. This modular architecture follows the ''pay-for-what-you-use'' principle, keeping the core library small while enabling complex features like persist or focus-trap.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36e6b466-49a0-4d63-8629-192083fd68f1', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are the architectural trade-offs of using ''Zone'' in Dart?', N'Senior', N'Zones provide a way to create an execution environment with its own error handling and asynchronous hooks, essentially acting as a dynamic scope. While they are powerful for tracking asynchronous context or logging, they can introduce non-obvious control flow dependencies and overhead if overused in performance-critical paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b98f46c8-9284-43c7-9938-1921ee5adbec', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the purpose of groups in Echo?', N'Intern', N'Groups allow developers to organize routes that share common characteristics, such as a URL prefix or a specific set of middleware. This makes the code cleaner and easier to manage when building large applications with many endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2265806a-834c-43b0-a857-1922214913e9', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the purpose of the ''WAIT'' command in Redis replication?', N'Middle', N'The WAIT command allows a client to block until a specified number of replicas have acknowledged receiving the write operation. This provides a way to implement synchronous replication for critical data, ensuring the master and replicas are in sync before proceeding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7ac8d63-0d82-4499-8f21-19233f2f59a6', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do computed properties differ from native getters in modern Ember?', N'Middle', N'Computed properties are tracked properties that automatically recompute when their dependent keys change, whereas native getters are standard JavaScript getters that don''t inherently track dependency changes. While modern Ember prefers native getters with tracked decorators, computed properties were historically essential for observable data reactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'faa59d6b-cb0d-4aea-b715-19252630aa83', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a database index and why is it used?', N'Junior', N'An index is a data structure that improves the speed of data retrieval operations on a table. It works similarly to an index in a book, allowing the database to find rows without scanning the entire table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a0d2b22-4671-43ff-aaee-1925dd1deb3b', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Discuss the scalability of Svelte in micro-frontend architectures.', N'Senior', N'Svelte is highly effective for micro-frontends because it produces autonomous, framework-agnostic custom elements or standard components with zero runtime dependency. This allows multiple micro-apps to coexist without worrying about version mismatches of the framework library, as the framework code is encapsulated within each build.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91b565ce-8bcd-46b5-aa48-19260f2f6140', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the performance implications of database indexes on write operations?', N'Middle', N'While indexes significantly speed up read operations, they impose a performance penalty on write operations. Every time data is inserted, updated, or deleted, the database engine must also update all associated index structures, which increases I/O overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41b35b0f-9795-4d36-853c-19268b7ad1c9', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What are the trade-offs of the ''one-time execution'' model of components?', N'Senior', N'The primary benefit is massive performance gains due to avoided re-renders. The trade-off is that developers must be careful not to place logic that needs to run on every update inside the component body, but rather inside signals or effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3aac731e-2411-4258-85a5-192795c74a4f', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin''s middleware execution chain work?', N'Middle', N'Gin uses a chain-of-responsibility pattern where each middleware calls the next handler using a context method. This allows middleware to execute logic both before and after the main request handler finishes its execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84390143-48d5-4d27-ac94-19279b012752', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain how to delete a file in Python?', N'Fresher', N'By using a command os.remove (filename) or os.unlink(filename)', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8a6f007-0ca8-4e0c-aaa4-1928626ebe12', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'In what scenario would you choose standard CSS or SASS over Tailwind CSS?', N'Middle', N'You might choose standard CSS or SASS when the project requires a highly custom design system that does not map well to Tailwind''s default configuration, or when the team prefers to keep logic and styling completely separated for architectural reasons. It is also beneficial if the project has extreme constraints on build-time overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'723396bc-e4fc-491e-b612-192c216cc352', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does ''Lit''s'' template system prevent XSS vulnerabilities?', N'Middle', N'Lit automatically escapes dynamic content rendered within templates, ensuring that potentially malicious strings are treated as text rather than executable markup. This provides a baseline level of security against injection attacks by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd75559ed-fb1d-465f-b461-192c39c45470', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the purpose of the ''NoRoute'' handler in some frameworks, and how does Echo handle this?', N'Junior', N'While some frameworks have a specific ''NoRoute'' handler, Echo handles unmatched routes through a central HTTP error handler. You can define a custom global error handler to manage all non-existent routes consistently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb3ff8f3-e287-48e6-a36b-193056333bc6', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What are the limitations of SolidJS''s reactive system?', N'Middle', N'The primary limitation is the strict requirement to maintain reactive proxies. Developers cannot easily convert reactive data to plain objects or pass them into standard JavaScript functions without losing the reactivity, requiring the use of specific framework primitives throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f02a8f6-22a5-4850-90b7-1931f9a0e318', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does the write-ahead logging (WAL) mechanism ensure ACID compliance during a system crash?', N'Senior', N'WAL ensures durability by requiring that all modifications to data pages are recorded in a persistent log before the actual data files are updated. In the event of a crash, the system can replay these logs to reconstruct the state of the database, ensuring that committed transactions are preserved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3394e3d3-6b03-4b05-933e-193557d919c5', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Can you define the term ''document-oriented'' in the context of MongoDB?', N'Fresher', N'Being document-oriented means that the database is designed to store, retrieve, and manage document-based information. This approach aligns well with object-oriented programming, allowing developers to map application objects directly to database documents.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'844d11db-07e5-4b7c-a1a6-1937acc98e6b', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do layouts work in a nested directory structure?', N'Fresher', N'Layouts are inherited, meaning a layout.svelte file in a parent directory will wrap all child routes. If a child directory also has a layout, it will nest inside the parent layout, allowing for complex UI hierarchies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e25d527-0294-4e4f-88cd-193b44170b19', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why is NoSQL often used for Big Data?', N'Fresher', N'NoSQL databases are designed to handle unstructured or semi-structured data at high speeds. They provide more flexibility than SQL databases because they do not require a rigid, predefined schema.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74ff4d1e-3700-476e-a67f-19440ba5322b', N'4c000000-0000-0000-0000-000000000005', N'What are the architectural challenges of achieving strong consistency in a multi-region deployment?', N'Senior', N'Strong consistency requires synchronous coordination across geographic distances, which introduces high latency due to the speed of light constraints. To mitigate this, architects often use geo-local replicas for reads and restrict write operations to a specific ''home'' region.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a50550d-a8ca-4f5e-b1ad-19467ec9542d', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the architectural difference between PHP''s traditional CGI execution model and the PHP-FPM model.', N'Senior', N'Traditional CGI spawns a new process for every request, which is extremely resource-intensive. PHP-FPM maintains a pool of persistent worker processes that remain alive between requests, significantly reducing latency and overhead by avoiding frequent process creation and destruction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46017773-7076-48a7-bec8-1951f7991ecd', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle middleware?', N'Fresher', N'Hono uses a middleware pattern similar to other popular frameworks like Express. Middleware functions are executed in a sequence to process requests before they reach the final handler, allowing for tasks like logging, authentication, or error handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89865526-ebb3-4635-95fa-1953979b3f27', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How does ''Service Discovery'' work in dynamic cloud environments?', N'Senior', N'Service discovery uses a registry where services register their network location upon startup and query the registry to find the locations of other services. This abstracts away the need for hardcoded IP addresses, enabling seamless scaling and recovery in environments where infrastructure is ephemeral.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bd01a98-ea24-4a84-bc3c-1954bd504488', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'When building an Echo-based API, how should you structure your application to facilitate unit and integration testing?', N'Senior', N'Decouple your business logic from the Echo handler functions by moving logic into services or domain objects. This allows you to test the core logic using standard Go testing tools without needing to mock the Echo context or trigger the full HTTP stack for every test case.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6e33a4c-aac8-402b-85fb-19574ec7f3df', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of an Angular Interceptor?', N'Middle', N'Interceptors allow you to intercept, inspect, and modify HTTP requests and responses globally. They are commonly used for adding authentication tokens, logging, or handling global error messages across all outgoing and incoming API traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f376bcc6-cbdc-4bcf-b44a-19576c0523f5', N'4c000000-0000-0000-0000-000000000005', N'What is the CAP theorem and why does it matter?', N'Middle', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. In practice, since network partitions are inevitable, architects must choose between prioritizing consistency or availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'634c96cf-fa96-48af-aa07-1959237529fe', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the Write-Ahead Log (WAL) and how does it contribute to crash recovery?', N'Senior', N'The WAL records all changes to the database state before they are applied to the actual data files, ensuring atomicity and durability. During crash recovery, PostgreSQL replays these logs to restore the database to the last consistent state, ensuring transactions that were committed are preserved even if they were not yet written to the main data pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2035e35c-d49b-44c3-b877-195a8447d739', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What does ''lazy'' loading mean in SolidJS?', N'Fresher', N'Lazy loading is a technique used to defer the loading of components until they are actually needed. This helps reduce the initial bundle size of an application by splitting it into smaller chunks that are fetched on demand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfb4980e-2077-4ce1-91ce-195be64ee5a4', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a circuit breaker in Elasticsearch and why does it exist?', N'Middle', N'A circuit breaker is a safeguard that monitors memory usage and prevents operations that would cause an out-of-memory error. It stops memory-intensive queries before they can crash the entire node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81e91837-bc48-434a-9747-195d8bc16427', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a ''readonly array'' and why is it preferred over a mutable array in some cases?', N'Middle', N'A ''readonly array'' is a type that prevents modification of its elements, such as pushing or popping items. It is preferred in functional programming patterns to ensure data integrity and prevent side effects, as it guarantees the array''s content remains consistent throughout the function''s execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8917eb3c-423e-4736-9695-195e41ec2206', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a ''conflict resolution'' strategy in distributed databases?', N'Middle', N'Conflict resolution determines how the system handles simultaneous writes to the same data on different nodes. Common strategies include ''last write wins'' based on timestamps or using vector clocks to detect causal relationships between updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'765cfa3c-84c6-49c9-ac59-195f70c36279', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is a database migration in Django and why is it important?', N'Intern', N'Database migrations in Django are changes to the database schema, ensuring it stays in sync with the evolving data models. Each migration is represented as a Python file, making alterations via the django.db.migrations module. Key Components - Migration Files: These are generated sequentially and outline the changes to be applied to the database. - Migrations Modules: A collection of related migration files. - Migration Plan: A record of applied and unapplied migrations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bfc2281-40a9-4112-84db-19615601d5cd', N'075b8862-431c-4678-9767-f55359758a4a', N'What is a ''prop drilling'' problem?', N'Junior', N'Prop drilling occurs when you have to pass data through multiple layers of intermediate components that don''t need the data themselves, just to reach a deeply nested child. This is typically solved by using a state management library like Pinia or Vue''s provide/inject mechanism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7626c98c-4972-4111-ac24-19636535d35a', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'When would it be appropriate to use a ''slim'' version of jQuery?', N'Middle', N'The slim version of jQuery excludes modules like AJAX and effects, resulting in a smaller file size for the production bundle. It is appropriate when you only need jQuery for its DOM manipulation and event handling capabilities and do not require the heavier, less-used features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29c639f9-5c1f-4c61-8d0d-1964124e05d2', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum differ from Actix-web in its architectural philosophy?', N'Senior', N'Axum is designed to be highly modular and built directly on top of the Tower ecosystem, focusing on composability and leveraging standard Rust traits. Actix-web is a more monolithic framework with its own custom actor-inspired design and internal abstractions, which can make it faster in specific benchmarks but less interoperable with standard Tower services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ece1993-4dd8-4bcd-86a4-19647cbb36a5', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How do Remix ''Actions'' support atomic operations?', N'Senior', N'Remix actions allow for atomic transactions because the entire data mutation occurs on the server. If an action fails, the server can return a specific error response, and because the action is decoupled from the UI, the application can revert to a safe state without risk of partial data updates on the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0372389-ce5c-41aa-b98c-1966d92d8a97', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Can Hono handle multiple middleware layers?', N'Fresher', N'Yes, Hono supports chaining multiple middlewares. They are executed in the order they are defined, allowing for modular and reusable logic such as authentication, validation, and logging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66138885-99e2-4c04-babb-196b19ec339f', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is a Curried Function?', N'Intern', N'Currying is the process of transforming a function that takes multiple arguments into a sequence of functions that each take a single argument. This technique allows for better function composition and partial application of arguments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5457150-7d7b-4cb4-8eef-196b25686d58', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does the ''Replication Factor'' affect cluster design?', N'Middle', N'The replication factor determines how many nodes hold a copy of the same piece of data. A higher factor increases fault tolerance and read availability but also increases storage requirements and write overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e2f06db-64bf-4b3c-9783-196cc5d5012c', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the difference between Orchestration and Choreography in microservices coordination?', N'Senior', N'Orchestration uses a centralized controller to manage the flow of business processes, offering better visibility and control. Choreography relies on decentralized event-driven interaction where services react to events, which is more scalable and decoupled but harder to monitor and debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c399c38-4281-425b-bfff-196dca0cb433', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What are the benefits of using a staging environment that mirrors production?', N'Intern', N'A staging environment allows you to test new features or configuration changes in a setting that replicates the production infrastructure. This helps identify issues related to system integration, performance, or environmental differences before users are impacted. It provides a safety net that significantly reduces the risk of introducing bugs into the live system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e205ae51-a335-44fe-9902-196e0d454cb1', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is Middleware in Next.js?', N'Intern', N'Middleware allows you to run code before a request is completed. It is commonly used for tasks like authentication, redirects, or rewriting URLs based on user information or cookies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c398db4-723c-45a8-bc60-196ecf5a2cce', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'When should you use a pointer receiver versus a value receiver for methods?', N'Middle', N'Use a pointer receiver when the method needs to modify the underlying data or when the struct is large and you want to avoid copying. Use a value receiver when the struct is small or when you want to ensure the original data remains immutable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57007369-b716-4a5b-8cb3-197033494b6d', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the purpose of DTOs (Data Transfer Objects) in NestJS.', N'Fresher', N'DTOs are used to define the structure of data exchanged between different layers of an application. They define the shape of data for a specific operation, such as creating, updating, or returning data. DTOs serve several purposes which include: Validation: With the class-validator package, you can add validation rules to the fields in your DTOs. NestJS can automatically validate incoming requests against these rules and return an error if the request is invalid. Documentation: DTOs provide a clear model of what the data should look like. This can be helpful for other developers, and for tools like Swagger to automatically generate API documentation. Type Safety: DTOs provide type safety in TypeScript, which can help catch errors at compile time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c35b9294-015a-4bd9-9334-1970a0228fcf', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are primitive functions in R?', N'Intern', N'Primitive functions are low-level functions that are written in C or Fortran and are built directly into the R language. They are typically faster than user-defined functions because they bypass the overhead of the R interpreter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f9d044a-342c-4ac5-ae44-1970c12a0211', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Compare the accessibility implications of utility-first CSS versus standard CSS classes.', N'Senior', N'Both methods require developers to be mindful of accessibility. Utility classes do not inherently improve or degrade accessibility, but they make it easier to miss semantic HTML structure if developers focus solely on visual styling; therefore, strict adherence to ARIA standards remains mandatory regardless of styling methodology.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff94efbb-4a11-45a8-9f78-1970d5e34236', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Does Redis support complex data types?', N'Fresher', N'Yes, unlike simple key-value stores, Redis supports advanced data structures. These include strings, hashes, lists, sets, sorted sets, and bitmaps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b3d512e-e96f-4232-8e47-19719c127b12', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut''s introduction of Compile-Time Proxy generation improve performance?', N'Senior', N'By generating proxies at compile time, Micronaut avoids the performance overhead of dynamic bytecode generation or reflection at runtime. This results in faster startup and lower CPU utilization during the initialization phase when establishing aspect-oriented programming features like interceptors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ede4125-ea0c-49eb-8df5-1971f786ee22', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Why is it important to rotate encryption keys periodically?', N'Middle', N'Key rotation limits the amount of data compromised if a specific key is stolen or cracked. It reduces the window of opportunity for an attacker to decrypt historic traffic and ensures that systems remain compliant with security standards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f13c2c6e-b390-4d28-b8aa-1972156e43c5', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you decide if a bug is high priority?', N'Fresher', N'I evaluate priority based on the impact on the user and the system''s stability. A bug that causes data loss, security vulnerabilities, or prevents core functionality is treated as high priority.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c965a63d-5302-41f1-9fa6-197321c79379', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why shouldn''t you modify the state directly in Redux?', N'Fresher', N'Directly modifying the state violates the principle of immutability, which makes it difficult to track state changes and debug the application. Redux relies on detecting state references to determine when to trigger UI updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'182b481b-5e45-4741-98c7-197548386a92', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do Ember''s ''tracked'' properties differ from React''s state management?', N'Senior', N'Ember’s tracked system uses an autotracking mechanism based on a dependency graph created at runtime. Unlike React''s explicit dependency arrays, Ember automatically detects which properties are consumed during rendering, allowing for precise, fine-grained reactivity without manual memoization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9f550d1-9726-46dd-80bc-1980b5dd0d19', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember''s Glimmer VM improve rendering performance compared to traditional template rendering?', N'Middle', N'The Glimmer VM compiles templates into a low-level bytecode that is executed by a highly optimized virtual machine. This approach reduces the overhead of re-rendering by using a fast diffing algorithm that updates only the specific parts of the DOM that have changed, rather than re-rendering entire component trees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53f278c4-e46d-42ce-954b-19826c483f9b', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the primary goal of Rust''s ownership system?', N'Intern', N'The ownership system is designed to ensure memory safety without needing a garbage collector. It manages memory through a set of rules that the compiler checks at compile time to prevent memory-related bugs like dangling pointers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f570882f-4d71-45b2-95fb-198349f7a296', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is it important to consider the ''moduleResolution'' strategy when integrating with legacy build tools?', N'Senior', N'The resolution strategy dictates how the compiler locates modules, and misconfigurations can lead to broken imports or missing declarations. In complex environments, selecting between Node16/NodeNext or Classic is critical for ensuring compatibility with the specific packaging and resolution logic of the underlying build system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62dae5a1-bd2e-4e57-9f87-19846f781853', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the size of an array relate to a pointer in C?', N'Middle', N'While an array name often decays into a pointer to its first element, they are distinct entities. An array has a fixed size known to the compiler, whereas a pointer is a variable that stores a memory address and does not inherently know the size of the memory block it points to.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d197e64-22a4-430e-a5c4-1984ecfaee99', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How are props passed in Preact?', N'Junior', N'Props are passed to components as a read-only object argument. In functional components, this object is the first parameter; in class components, it is accessed via the ''this.props'' property.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07f933a3-e834-4783-95e4-198b8f99a4a9', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How do you implement a custom error handler in Echo to replace the default one?', N'Middle', N'You can replace the default error handler by assigning a custom function to the ''HTTPErrorHandler'' field in the Echo instance. This allows you to centralize error logging, standardise response formats, and mask internal error details from the end-user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e65d7c21-1f78-46dd-89b0-198d56ee888b', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP handle session management?', N'Fresher', N'PHP uses sessions to store information across multiple pages for a single user. When a session starts, PHP assigns a unique session ID, typically stored in a cookie, which allows the server to retrieve the user''s data associated with that ID on subsequent requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db8bf859-d922-40cd-98fa-198d57e9277a', N'954a0331-deff-4399-b588-96f39fec001d', N'Why should you use ''trackBy'' with ngFor?', N'Middle', N'The trackBy function helps Angular identify which items in a list have changed, been added, or removed by using a unique identifier. Without it, Angular re-renders the entire list whenever the array reference changes, which is inefficient for large datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7c0e256-6a3f-4b58-adca-198d5ce6750b', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the risk of guessing a solution without fully understanding the problem?', N'Intern', N'Guessing can lead to ''trial and error'' fixes that do not address the root cause, potentially creating new bugs elsewhere. It is always better to spend time understanding the mechanism of the failure before attempting a fix to ensure long-term system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fbd5f8f-fa51-4159-9246-19914efc15ef', N'075b8862-431c-4678-9767-f55359758a4a', N'What are non prop attributes?', N'Intern', N'A non-prop attribute is an attribute that is passed to a component, but does not have a corresponding prop defined. For example, If you are using a 3rd-party custom-input component that requires a data-tooltip attribute on the input then you can add this attribute to component instance, If you try to pass the props from parent component the child props with the same names will be overridden. But props like class and style are exception to this, these values will be merged in the child component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01e80659-5c0f-432c-b957-1993b9195fbe', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What does ''subscribe'' mean in Redux?', N'Intern', N'Subscribing allows a function to be called whenever the state in the store changes. It is a fundamental mechanism that allows parts of the application to react to state updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
