INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb7013ea-319c-48c8-84c8-19a46b2695cd', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus handle configuration injection compared to standard property files?', N'Senior', N'Quarkus uses a unified configuration system that aggregates properties from various sources, including environment variables, system properties, and profiles. It supports type-safe configuration injection, where properties are mapped directly to POJOs at build time, ensuring that invalid configurations are caught before the application starts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
