INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57f559e0-d850-4df4-94e1-19ab8732cd32', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What happens if a signal is accessed outside of a reactive scope?', N'Senior', N'If a signal is read outside of a tracking context like a component body or an effect, it simply returns its current value. However, it will not trigger any re-renders or updates, as there is no subscriber to receive the notification.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
