INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'430fb289-b210-47c6-b5ea-19bbc14d6e2f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s Isolate model differ from traditional multithreading, and why is this design choice significant for UI performance?', N'Middle', N'Dart uses a shared-nothing memory model where each Isolate has its own private heap, preventing data races and eliminating the need for complex locks or mutexes. This design ensures that UI rendering is never blocked by heavy computations, as expensive tasks are offloaded to separate Isolates that communicate only through asynchronous message passing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46bf95b1-b649-4b0f-b047-19bc5fe44b7d', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of the ''Preload'' feature in Lucid ORM?', N'Senior', N'Preload allows for eager loading of related database models, solving the ''N+1'' query problem by fetching relational data in minimal round trips. This is crucial for performance, as it prevents the ORM from executing a separate database query for every single item in a collection, significantly reducing latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bca5151c-5983-4a14-9f5d-19bca91951e2', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the primary benefit of using Spring Boot over standard Spring?', N'Junior', N'Spring Boot significantly reduces the boilerplate configuration and setup time required for a traditional Spring application. It provides sensible defaults, auto-configuration, and embedded servers, allowing developers to focus on writing business logic rather than infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63917423-9fb7-4f21-be7f-19bde6168738', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are environment variables in the context of Flask?', N'Intern', N'Environment variables are used to pass configuration settings to the application from the operating system. This is a secure practice to keep sensitive data like API keys or database passwords out of the source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae9692c3-1811-4b57-92da-19be2eb80c71', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What are the advantages of using ''gRPC'' over REST for inter-service communication?', N'Senior', N'gRPC uses Protocol Buffers for efficient binary serialization and leverages HTTP/2 for multiplexing and streaming, resulting in significantly lower latency and bandwidth usage. REST is easier to debug and more widely supported by generic web infrastructure, but it is typically less performant and lacks built-in strong typing for service contracts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4366ea49-4488-4373-b429-19c028a9fc51', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What does it mean for R to be case-sensitive?', N'Intern', N'Being case-sensitive means that R distinguishes between uppercase and lowercase letters when identifying objects. For example, a variable named ''Data'' is treated as entirely different from a variable named ''data''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2e6a8a2-1fa9-4d78-8a94-19c04550fd91', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why should you prefer the ''picture'' element over a standard ''img'' tag for art direction?', N'Middle', N'The ''picture'' element allows you to provide different image files based on media queries, which is known as art direction. While ''srcset'' is ideal for resolution switching, ''picture'' is better when you need to change the image''s crop or aspect ratio based on the screen size. This gives developers precise control over how visual assets are presented across various devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b751411c-8647-4652-be74-19c43171a4ae', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is an iterator in Python?', N'Junior', N'An iterator is an object that contains a countable number of values and can be traversed through. It implements the iterator protocol, which consists of the methods that allow the retrieval of the next item in a sequence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee1883c6-78c5-47a7-b4e3-19c4c9f5fa46', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is a reference type?', N'Intern', N'A reference type is a type where multiple variables or constants point to the same underlying instance in memory. Changes made to one reference will be reflected in all other variables pointing to that same instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c64e53b2-0c3c-4585-8a5b-19c576d1049e', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin''s ''Companion Object'' differ from Java''s static members?', N'Senior', N'Companion objects are actual singleton instances of a nested class rather than static members of the containing class. This allows them to implement interfaces, participate in polymorphism, and hold state, providing a more flexible and object-oriented approach to static-like functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'308570a3-cda7-43f6-bba2-19c75b2101f4', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Can NoSQL databases handle relational data?', N'Junior', N'While NoSQL is not built for relationships, it can handle them by embedding related data within documents or using application-level logic to link records. However, it is not as efficient as SQL databases at managing complex, highly interconnected relational datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc154ee9-4711-4a01-89cb-19c760fcd458', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the main security risk of not updating software dependencies?', N'Fresher', N'Outdated dependencies often contain known security vulnerabilities that are documented publicly. Hackers can exploit these weaknesses to compromise the application if the patches provided by library maintainers are not applied. Regularly updating dependencies is a standard practice to keep the application protected against known threats.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77c7242d-338d-4967-a9bb-19c813b20c4b', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind influence the ''separation of concerns'' debate in frontend architecture?', N'Senior', N'Tailwind shifts the concern of styling from the CSS file to the HTML template, arguing that styling and structure are inherently coupled. This moves the concern from ''how to style a specific element'' to ''how to compose an interface from existing design tokens''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19b8eeab-feb0-4658-8c35-19c83a9f99b3', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the benefit of keeping a task simple rather than adding extra features?', N'Fresher', N'Simple solutions are easier to maintain, less prone to errors, and faster to deliver. Extra features often introduce unnecessary complexity that can make the system harder to support over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'304878e8-6693-4ac8-9f48-19c8ff339f9a', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the purpose of the payload property in an action?', N'Junior', N'The payload is a conventional property used to carry the data necessary for an action to be processed. While the action type identifies the event, the payload provides the specific information required to update the state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f09975b8-ac27-4578-9833-19c9330cf40c', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the difference between a Compiler Pass and a regular service definition.', N'Middle', N'A regular service definition registers a class in the container, while a Compiler Pass allows you to manipulate the container before it is compiled. This is useful for tasks like automatically registering services tagged with a specific interface or optimizing service definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63de39b2-8af6-4b15-b76f-19c99175d61a', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the architectural implications of moving from a monolithic database to a distributed SQL cluster?', N'Senior', N'Moving to distributed SQL introduces challenges related to the CAP theorem, specifically handling network partitions and maintaining consistency across nodes. It requires distributed consensus algorithms like Raft or Paxos to ensure atomicity and synchronous replication, which introduces latency compared to local disk writes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca18d755-0532-4904-9b45-19ca6ca5cdb3', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the difference between a Guard and an Interceptor?', N'Junior', N'Guards are used to determine whether a request should be handled by the route handler, typically for authentication or authorization. Interceptors, on the other hand, can transform the result returned from a function or the exception thrown, and can also extend basic method behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
