INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2144b91b-153b-49a5-a945-19cdccbd2ccc', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Discuss the implications of the ''extern'' keyword in large-scale C development.', N'Senior', N'The ''extern'' keyword declares that an identifier exists elsewhere, preventing duplicate symbol errors during linking. Excessive use of ''extern'' for global variables creates tight coupling between modules, making the dependency graph difficult to manage and increasing the risk of race conditions in multi-threaded environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f6e11bc-ac23-420a-a7be-19cde4866cb6', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the difference between observability and monitoring?', N'Middle', N'Monitoring focuses on tracking predefined metrics to tell you when something is wrong based on known failure modes. Observability is a property of a system that allows you to understand its internal state by examining its external outputs, enabling you to debug issues you haven''t anticipated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef927c84-9368-43cf-bda9-19cebbf549b9', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery''s lack of a reactive data binding layer affect the complexity of UI state synchronization?', N'Senior', N'Without a reactive layer, developers must manually synchronize the UI whenever the underlying data changes, often leading to race conditions and inconsistencies. This manual synchronization effort scales linearly with the number of UI elements, whereas reactive frameworks handle these updates automatically via observable patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d2c4be9-9a6c-4325-908b-19cf2037301a', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle lifecycle events?', N'Fresher', N'Svelte provides lifecycle functions like onMount, beforeUpdate, afterUpdate, and onDestroy. These functions allow you to execute logic at specific points in a component''s lifecycle, such as when it is first added to the DOM or when it is about to be removed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bf678de-30ca-4e9b-bee0-19cfdf819fec', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you troubleshoot a performance bottleneck in a multi-tier application?', N'Middle', N'I would start by reviewing distributed traces to identify the specific service or database query responsible for the latency. Once the bottleneck is isolated, I would analyze resource utilization metrics and execution plans to determine if the issue stems from inefficient code, missing database indexes, or external network contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dada975e-350b-4a98-b3bc-19cff755c7ce', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the primary role of Express in a backend application?', N'Intern', N'Express is a minimalist web framework for Node.js that simplifies the process of building web applications and APIs. It provides a robust set of features for routing, handling HTTP requests and responses, and managing middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5d59336-e716-470f-bbaf-19d0e5429117', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the ways to trigger change detection in Angular?', N'Intern', N'You can inject either ApplicationRef or NgZone, or ChangeDetectorRef into your component and apply below specific methods to trigger change detection in Angular. i.e, There are 3 possible ways, 1. ApplicationRef.tick(): Invoke this method to explicitly process change detection and its side-effects. It check the full component tree. 2. NgZone.run(callback): It evaluate the callback function inside the Angular zone. 3. ChangeDetectorRef.detectChanges(): It detects only the components and it''s children.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e365097-268f-439c-b0a0-19d18057e6df', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is ''Hot Reload'' in the context of Dart and Flutter?', N'Intern', N'Hot reload is a development feature that allows developers to inject updated source code into a running application without losing the app''s state. It relies on the JIT compiler to quickly update the logic and UI while the app remains running.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fa9eef6-cb61-4b9c-95fa-19d734e1279a', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Why is the separation of build-time and run-time data fetching critical in Astro?', N'Senior', N'Distinguishing between build-time fetching (for static generation) and run-time fetching (for SSR) allows developers to optimize data usage and costs. Build-time fetching reduces database load and latency, while run-time fetching ensures that users receive real-time information when necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af16df53-3b7a-4257-942d-19d756712184', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the function of the @SpringBootApplication annotation?', N'Intern', N'This annotation is a convenience that adds @Configuration, @EnableAutoConfiguration, and @ComponentScan. It tells Spring Boot to begin scanning for components and automatically configure beans based on the classpath.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06571034-bde9-4539-b28b-19d87cb1e8e4', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the purpose of the ''Quarkus Test Framework''?', N'Middle', N'The test framework allows developers to write unit and integration tests that run in the same context as the application, including support for test containers. It enables testing of native executables and simulated environments, ensuring that the application behaves correctly before deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2a69b00-7d4f-45e1-97ab-19d99df6a8ff', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between a class and a structure in C++?', N'Fresher', N'The primary difference is the default access specifier; class members are private by default, while structure members are public by default. Both can contain data members and member functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6b880e0-7999-4baa-950b-19e2accc4a69', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Utility Types like Pick, Omit, and Record used for?', N'Middle', N'Utility types are built-in helpers that allow you to transform existing types into new ones without manually defining them. ''Pick'' creates a type with a subset of properties, ''Omit'' removes specific properties, and ''Record'' constructs an object type with specific key and value types. They are essential for keeping code DRY and maintainable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d727eed-b59a-4012-808f-19e332ed8cbd', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the significance of the ''Owner'' concept in SolidJS?', N'Senior', N'The Owner is an internal object that keeps track of the reactive hierarchy, including signals, effects, and sub-components. It provides the context necessary for lifecycle management and disposal, ensuring that reactive resources are correctly cleaned up when a parent component is destroyed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75e6d939-f3c4-48d7-8751-19e49ffeb12c', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is dependency pre-bundling?', N'Fresher', N'Dependency pre-bundling is a process where Vite converts CommonJS or UMD dependencies into native ESM format. This improves page load speed and ensures compatibility with the browser''s module system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70f26b27-4ddf-4dfb-ac12-19e5d39be509', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does reified type parameterization solve the ''type erasure'' problem?', N'Middle', N'Type erasure removes generic type information at runtime, making it impossible to check types like ''if (x is T)''. By using reified types in inline functions, the compiler generates bytecode that retains the actual type information at the call site, allowing for runtime type checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'911e6d5b-8a5c-4822-99d4-19e79df802f6', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the ''picture'' element differ from the ''img'' element with ''srcset''?', N'Middle', N'The ''srcset'' attribute provides a list of images for the browser to choose based on its current viewport width or pixel density. The ''picture'' element provides more granular control, allowing developers to define different image formats or art-directed crops for specific media queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'831b9a61-cbaf-47a3-84ca-19e862c960d3', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you check if a key exists in an object', N'Fresher', N'You can check whether a key exists in an object or not using three approaches, 1. Using in operator: You can use the in operator whether a key exists in an object or not and If you want to check if a key doesn''t exist, remember to use parenthesis, 2. Using hasOwnProperty method: You can use hasOwnProperty to particularly test for properties of the object instance (and not inherited properties) 3. Using undefined comparison: If you access a non-existing property from an object, the result is undefined. Let’s compare the properties against undefined to determine the existence of the property.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b2ef6bf-016e-40bb-9d2a-19e8cefe5840', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why is Rust considered a systems programming language despite its high-level features?', N'Middle', N'Rust provides low-level control over memory layout and hardware resources, comparable to C or C++. Its zero-cost abstractions and lack of a runtime garbage collector allow for deterministic performance, which is a requirement for operating systems, drivers, and embedded applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6c8a775-3ee0-40fa-8feb-19ea18cc8baa', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What does the ''virtual'' keyword do?', N'Intern', N'The virtual keyword allows a method or property in a base class to be overridden in a derived class. It is the foundation for achieving polymorphism, enabling the runtime to execute the specific implementation based on the actual object type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
