INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d40e63b-ab1c-43be-ab25-19ed59f9a24f', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why does Preact not use Synthetic Events by default?', N'Middle', N'Preact uses standard browser-native DOM events instead of a synthetic event system to reduce bundle size and overhead. By attaching event listeners directly to the DOM, it avoids the memory consumption and complexity associated with maintaining a cross-browser event normalization layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
