INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a7f0eb2-0944-411f-afd9-19f1b0b336bc', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your approach to handling data migration between two different storage engines?', N'Middle', N'I implement a dual-write strategy where the application writes to both the old and new systems while performing a background migration of existing data. Once the new system is synchronized and verified, I switch the read source and eventually decommission the old storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
