INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'786f4a87-4834-4f19-beab-19fb00a1c38d', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does Rails handle database transactions, and why should they be used?', N'Middle', N'Rails transactions ensure that a group of database operations are executed as an atomic unit, meaning they either all succeed or all roll back if an exception occurs. They are crucial for maintaining data integrity when multiple related records must be updated simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'738024de-795f-4bc5-9ff1-19fbe198e335', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why is Phoenix considered highly concurrent?', N'Fresher', N'Phoenix runs on the Erlang VM, which uses lightweight processes that can be created and destroyed very quickly. This architecture allows the server to manage thousands of concurrent users with minimal resource overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
