INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80deb4f2-6821-4736-9884-19ff187d8bda', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between a synchronous and asynchronous controller action?', N'Fresher', N'A synchronous action blocks the execution thread until the task is complete, which can limit scalability under load. An asynchronous action uses the async and await keywords to release the thread while waiting for I/O operations, allowing the server to handle more concurrent requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c8a1efa-4bf6-4e07-9e35-1a0138330a8e', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why is caching often considered a ''double-edged sword'' for debugging?', N'Senior', N'Caching introduces hidden state that is not immediately visible in the source of truth, making it difficult to reproduce bugs or verify data integrity. It can mask underlying database performance issues, only for those issues to surface during high-load scenarios when the cache is bypassed or flushed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'deddd436-87d9-4f89-9b70-1a031a0822f8', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the benefit of using an index signature?', N'Junior', N'An index signature allows you to define the type of keys and values for an object when you do not know the exact property names in advance. This is useful for dynamic objects where you want to enforce a specific type for all keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b170950d-2b5c-4804-9d0b-1a056d9d946f', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Compare ''Synchronous'' vs ''Asynchronous'' replication regarding data durability.', N'Senior', N'Synchronous replication ensures that a write is acknowledged only after it is confirmed on the secondary node, providing zero data loss and strong consistency. Asynchronous replication acknowledges the write immediately after the primary commits, offering superior performance but risking data loss if the primary fails before the update propagates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17d17e68-608a-41c9-920c-1a06254e7896', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the significance of the ''late'' modifier?', N'Middle', N'The late modifier allows for lazy initialization of variables that are non-nullable but cannot be assigned at the time of object construction. It signals to the compiler that the developer takes responsibility for ensuring the value is assigned before it is read, preventing null-related runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9200adc-e439-4899-a486-1a0a4155ca0c', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of the async pipe in Angular templates?', N'Intern', N'The async pipe in Angular templates is used to automatically subscribe to an Observable or Promise and unwrap the value they emit. When a new value is emitted, the pipe triggers change detection to update the view. Its main purposes are: - Simplifying template code by removing the need for manual subscription and variable updates in the component class - Preventing memory leaks by automatically unsubscribing from the Observable when the component is destroyed - Handling the asynchronous nature of data streams gracefully in the template You use it directly in the template like this: where `data > Try out Angular coding questions on GreatFrontEnd. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2c75d26-1ec8-430e-958b-1a0c1b0edab8', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the purpose of v-for directive?', N'Intern', N'The built-in v-for directive allows us to loop through items in an array or object. You can iterate on each element in the array or object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed3fe460-adb6-46a8-972e-1a0d451589fd', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the purpose of the public folder in Astro?', N'Fresher', N'The public folder is used for static assets that do not need to be processed by Astro. Files placed here, such as favicons or robots.txt, are copied directly to the output build directory as-is.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a34891f8-494d-45c8-869f-1a0e48f54847', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi interact with Go''s ''context'' package?', N'Middle', N'Chi uses the context package to carry request-scoped information throughout the handler chain. By populating the context with route parameters and other data, Chi ensures that all middleware and handlers have a consistent way to access the request metadata.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
