INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abd9a47a-a0fc-4c4f-99d2-1a0ec9e0a3be', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is an API Controller?', N'Intern', N'An API Controller is a class that inherits from the ControllerBase class and contains action methods to handle HTTP requests. It is used to define the endpoints of a RESTful web service and return data, typically in JSON format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20e69e53-1568-43c1-a853-1a14755adbe8', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a physical replication and a logical replication in PostgreSQL?', N'Middle', N'Physical replication copies the entire database cluster at the byte level, which is ideal for high availability and disaster recovery. Logical replication allows for the replication of specific tables or databases, enabling more flexible data distribution and cross-version migrations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
