INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6dc9245-11ef-4d47-b7c9-1a1b6b6f5195', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Explain the concept of ''Progressive Enhancement'' as applied in Remix.', N'Senior', N'Progressive enhancement in Remix means the app is functional with only basic HTML and browser form capabilities, and it ''enhances'' to a high-performance SPA as soon as the JS bundle downloads. This ensures the app is resilient to network failures, slow devices, and JavaScript execution errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7546a86-a605-437b-8182-1a1c355c95e7', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Why is the AdonisJS ''Model-View-Controller'' pattern considered an opinionated structure, and what are the benefits for large teams?', N'Senior', N'It provides a clear separation of concerns that ensures consistency regardless of the developer assigned to a feature. For large teams, this standardization reduces onboarding time and prevents the ''spaghetti code'' that often results from frameworks that offer too much architectural freedom.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a0e8a85-83d8-4ddb-907e-1a1f3b76de09', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why is Svelte often preferred for memory-constrained environments like embedded devices or low-end mobile?', N'Senior', N'By eliminating the virtual DOM and minimizing the runtime, Svelte reduces the garbage collection pressure and binary size. This allows the browser to spend fewer CPU cycles on overhead and more on rendering, which is critical for devices with limited memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
