INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fcd9e14-41c9-4b96-b92a-1a29fce31ad4', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle event listeners compared to traditional frameworks?', N'Middle', N'Qwik uses a global event delegation system where a single listener is attached to the document root. This listener intercepts user interactions, identifies the associated serialized code chunk, and lazily downloads and executes it on demand, rather than attaching individual listeners to every DOM element during initialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
