INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36407e0d-9d77-4e45-a287-1a30f7f844c9', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle DOM updates?', N'Fresher', N'Lit uses a technique called efficient DOM updates by rendering only the parts of the template that have changed. It uses a virtual DOM-like approach to track changes and minimizes direct interaction with the browser''s DOM for better performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'478e9f16-4732-4b1a-b117-1a3170b24f77', N'4c000000-0000-0000-0000-000000000005', N'When would you prefer a Log-Structured Merge-tree (LSM) over a B-Tree for a storage engine?', N'Senior', N'LSM trees are preferred for write-heavy workloads because they perform sequential writes to disk, avoiding the random I/O overhead typical of B-Trees. However, B-Trees are generally superior for read-heavy workloads where point lookups must be performed with minimal latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b09c6bb2-89c2-4664-81c1-1a32172c0c39', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'In a distributed system, why should you avoid using Express''s built-in memory store for sessions?', N'Senior', N'The default memory store is not persistent and is limited to a single process, making it incompatible with horizontal scaling. Using an external, shared store like Redis ensures that session data persists across server restarts and is accessible to all instances in a clustered environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
