INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'684cd4ca-fe7a-4145-8fa7-1a342d7b4a0e', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a view in a database?', N'Intern', N'A view is a virtual table based on the result set of an SQL statement. It does not store data itself but displays data from underlying tables, allowing users to simplify complex queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15a3f7a1-bf73-40c8-a149-1a3494ad9b97', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the benefit of Hono''s ''Standard Web APIs'' approach?', N'Intern', N'By adhering to standard Web APIs, Hono ensures that developers use familiar interfaces like Request, Response, and Headers objects. This reduces the learning curve and makes the code more portable across different environments that support these standards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8a66960-7109-4f64-a09c-1a3653e4bf64', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How do you handle security in Micronaut microservices?', N'Middle', N'Micronaut Security provides a robust framework that supports various authentication mechanisms like JWT, OAuth 2.0, and LDAP. It offers declarative security annotations to enforce authorization rules consistently across service endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
