INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4f11143-3ce5-4ae8-b3a7-1a3ebd3c2ec5', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the primary role of the Rocket framework in a Rust-based backend application?', N'Fresher', N'Rocket is a web framework designed to help developers build secure and performant web applications using the Rust programming language. It focuses on type safety and developer productivity by providing a highly structured way to handle HTTP requests, routing, and response generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10496e42-3c42-42e0-9323-1a3f470b31d2', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do you set default value for uncontrolled component?', N'Fresher', N'In React, the value attribute on form elements will override the value in the DOM. With an uncontrolled component, you might want React to specify the initial value, but leave subsequent updates uncontrolled. To handle this case, you can specify a defaultValue attribute instead of value. The same applies for select and textArea inputs. But you need to use defaultChecked for checkbox and radio inputs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b949d345-a431-4e71-bd82-1a4087b498c8', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP handle session data, and what are the limitations in distributed systems?', N'Middle', N'By default, PHP stores session data in local temporary files, which causes issues in distributed environments where a user might be routed to different servers. To solve this, session handlers must be configured to use a centralized storage mechanism like Redis or a database to ensure state consistency across all nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'906efea6-589c-42d0-a74d-1a410589d7fb', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When implementing security, what is the trade-off between user friction and protection?', N'Middle', N'Adding security layers like multi-factor authentication or strict password policies enhances protection against breaches but increases user friction, which can lead to lower adoption or user drop-off. The strategy must be risk-based, applying stricter controls only to sensitive actions while minimizing friction for low-risk user activities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b513f54-7e0e-4ac8-b62d-1a45f4c726a5', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If an application stops working after a recent update, what is the first step you should take to identify the source of the issue?', N'Intern', N'The first step is to isolate the change by comparing the application''s current behavior against its known state before the update. You should review the recent changes or logs to determine if the error is caused by new code, a configuration mismatch, or an external dependency failure. This process of elimination helps narrow down whether the issue lies within the software logic or the environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f37bb02-7e75-4c74-8150-1a4723fa3223', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Why is it often better to use ''join()'' instead of ''+'' to concatenate many strings?', N'Middle', N'Strings are immutable, so using ''+'' creates a new string object in memory for every concatenation operation, leading to quadratic time complexity. The ''join()'' method calculates the total memory required upfront and allocates it once, making it significantly more efficient for building strings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3772b609-1e8f-40ec-8d56-1a47b137eb68', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the difference between a struct and a class.', N'Junior', N'In C++, the only functional difference is the default access level for members. In a struct, members are public by default, whereas in a class, they are private by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'273b39a3-b0ca-4335-9e9b-1a48dc2e5035', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Explain the architectural trade-off of Svelte''s decision to treat DOM updates as a compilation task.', N'Senior', N'The main trade-off is the increased reliance on the build process and the loss of runtime flexibility compared to virtual DOM frameworks. While this leads to significantly higher performance and smaller bundles, it limits the ability to perform dynamic, runtime-only component generation or highly fluid schema-based UI construction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da08896d-3920-4875-a28e-1a4a22da8b39', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you handle form submissions in Angular?', N'Fresher', N'In Angular, creating, validating, and submitting forms can happen either using Template-Driven Forms or Reactive Forms. Template-Driven Forms Template-Driven Forms are easier to set up but offer limited functionality compared to Reactive Forms. Steps to Use Template-Driven Forms 1. Import the FormsModule: In the app module, you need to import FormsModule. 2. Add a form tag: Within your component''s markup, place a tag that binds to NgForm. 3. Bind to Form Controls: Use directives like ngModel to handle data bindings and validation. 4. Customize Validation: Make use of built-in directives like required, or customize them like NgModel with ngControl. 5. Work with Submission: Define a method for the ngSubmit event of the form.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d48d1eb-a63f-414c-8c63-1a4af5c45516', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What does the target attribute do in a link?', N'Intern', N'The target attribute specifies where the linked document should open when the user clicks the link. For example, setting the target to an underscore followed by blank will cause the link to open in a new browser tab or window.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1d0f602-7fbd-4019-b065-1a4e5a1dfc3e', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is a ''binding'' in Ruby?', N'Middle', N'A binding is an object that encapsulates the execution context of a specific location in the code, including local variables, methods, and the value of ''self''. It can be passed around and used to evaluate code in that saved context later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e85656f4-8943-4ff2-a0a3-1a4eb918a19c', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are the benefits of using Svelte''s ''reactive declarations'' over standard functions?', N'Middle', N'Reactive declarations automatically re-run whenever their dependencies change, ensuring that variables stay in sync without manual updates. This declarative approach reduces the risk of state inconsistency and simplifies complex logic that depends on multiple data sources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9afb80f5-7cb2-4ffe-922f-1a4f33117d0d', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the role of the ClassLoader?', N'Intern', N'The ClassLoader is a crucial component in Java''s runtime environment, responsible for loading class files into memory. Key Functions 1. Loading Classes: Finds and reads the binary representation of a class or interface. 2. Linking Classes: - Verification: Ensures the loaded class adheres to Java language and JVM specifications. - Preparation: Allocates memory for class variables and initializes them with default values. - Resolution: Replaces symbolic references with direct references to other classes. 3. Initializing Classes: Executes the static initializers and initializes static fields of the class. Types of ClassLoaders 1. Bootstrap ClassLoader: - Written in native code (C++) - Loads core Java API classes from rt.jar or modules in Java 9+ 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f56beee-6cfa-416f-9f3b-1a50edddbc50', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why should you avoid using ''table'' elements for layout purposes?', N'Middle', N'Tables are designed for tabular data, and using them for layout breaks the semantic meaning of the document. This causes significant accessibility issues for screen readers, as the logical flow of the page becomes confused. Furthermore, table-based layouts are difficult to make responsive and increase the complexity of the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd269466-0799-4f6c-b700-1a5134243379', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Define the concept of ''Isolation'' in the context of ACID transactions.', N'Middle', N'Isolation ensures that the intermediate state of a transaction is invisible to other concurrent transactions. It creates the illusion that each transaction is executing sequentially, preventing interference and maintaining data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6f6fe27-7f3b-4d18-ac9e-1a53bda6c39c', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Explain the architectural trade-offs of Preact''s ''diffing'' algorithm compared to React''s reconciliation process.', N'Senior', N'Preact utilizes a more compact diffing algorithm that avoids unnecessary property tracking and reconciliation overhead found in React. While this sacrifices some of the advanced scheduling and concurrent features of React, it achieves faster update cycles and lower runtime memory consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'974a9080-cf96-4daf-8dfa-1a5442106198', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When implementing a search feature, what is the trade-off between using database ''LIKE'' queries versus a dedicated search engine?', N'Junior', N'Database ''LIKE'' queries are simple to implement and require no extra infrastructure for basic needs. A dedicated search engine like Elasticsearch offers advanced features like fuzzy matching, relevance ranking, and massive scalability, but it adds significant operational overhead and synchronization complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'187e8d08-eed7-4e57-b073-1a5627c0278a', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Can a transaction span across multiple tables?', N'Intern', N'Yes, a transaction can involve operations across multiple tables within the same database. The database ensures that all changes across those tables are treated as a single atomic unit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d1245d7-e03a-4f82-8590-1a56aa42ee3a', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of the ''Depends'' object in FastAPI?', N'Middle', N'The ''Depends'' object is the core component of the dependency injection system, marking a parameter as a dependency that needs to be resolved by the framework. It allows the framework to execute setup and teardown logic, such as opening and closing database connections, reliably for every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2011701-9c00-416a-9156-1a571afbcf45', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Is Echo thread-safe?', N'Intern', N'Yes, Echo is designed to handle multiple concurrent requests by leveraging Go''s built-in goroutines. Each request is processed within its own context, ensuring that operations remain thread-safe.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12a5f60d-4547-474c-bce8-1a5accb846d9', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the IConfiguration interface?', N'Intern', N'IConfiguration is a built-in interface used to access the application''s configuration settings. It provides a unified way to read data from various sources like JSON files, environment variables, or command-line arguments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63afb50f-3866-4206-9596-1a5fd74e8142', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Why might a large message size cause architectural bottlenecks in a messaging system?', N'Senior', N'Large messages consume excessive memory in both the broker and the consumer, increase network congestion, and can exceed the configured maximum message size of the broker. A common pattern to avoid this is the ''Claim Check'' pattern, where the message payload is stored in external object storage and only a reference is sent via the broker.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77c43b2f-0bdc-4939-9812-1a628bbfbae3', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Why is it recommended to use constructor injection with final fields?', N'Middle', N'Using final fields with constructor injection ensures that the dependency cannot be changed after the bean is initialized, which promotes thread safety. It also guarantees that the object cannot be instantiated in an inconsistent state, as all required dependencies must be provided during construction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'854e5b6e-92fb-4b53-be53-1a6da8b5208d', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is a ''Router'' in Litestar?', N'Fresher', N'A Router is a way to group and organize route handlers into logical modules or sub-sections. Routers can be mounted onto the main application or other routers, allowing for modular application design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abc721fc-344a-40fc-853d-1a6ea421b7f6', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the impact of using reflection in PHP?', N'Middle', N'Reflection allows for the inspection and manipulation of classes, methods, and properties at runtime, which is powerful for building frameworks and dependency injection containers. However, it carries a significant performance cost and can make code harder to analyze statically. It should be used judiciously, primarily in infrastructure code rather than business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abb41164-e4a3-4ec1-8c16-1a6f6c549d3c', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach debugging a cascading failure where one service''s latency causes a total system outage?', N'Senior', N'I prioritize stabilizing the system by implementing circuit breakers or load shedding to stop the propagation of failures. Once the system is stable, I perform a post-mortem analysis of the dependency graph to identify lack of timeouts or insufficient backpressure mechanisms that allowed the initial fault to overwhelm downstream services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20e0df42-e699-41aa-afe5-1a70a038ce97', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'When should you implement database sharding?', N'Senior', N'Database sharding is necessary when a single database instance cannot handle the required read/write throughput or data volume. It is a complex architectural decision that should be deferred until optimization of indexes and vertical scaling are no longer sufficient due to its impact on query complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd07aac2-88ac-438d-ac07-1a73c8f035fe', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the behavior of uncaught errors in react 16?', N'Intern', N'In React 16, errors that were not caught by any error boundary will result in unmounting of the whole React component tree. The reason behind this decision is that it is worse to leave corrupted UI in place than to completely remove it. For example, it is worse for a payments app to display a wrong amount than to render nothing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edfbcccd-6cff-4283-a62d-1a795ad3d2c1', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is NaN property', N'Intern', N'The NaN property is a global property that represents "Not-a-Number" value. i.e, It indicates that a value is not a legal number. It is very rare to use NaN in a program but it can be used as return value for few cases', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05e6ee79-a54e-4778-a4e2-1a79abb32aa8', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the trade-offs of using ''CSS-in-JS'' libraries compared to standard CSS modules?', N'Senior', N'CSS-in-JS allows for dynamic styling based on component props and colocates styles with logic, but it incurs a runtime cost for style injection and parsing. CSS modules offer better performance and browser caching, as they compile to static files, but require more boilerplate to handle dynamic style changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'701b80aa-e979-42d6-9981-1a7b93186721', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the advantage of using Fiber''s built-in error handling?', N'Junior', N'Fiber allows you to define custom error handlers that catch errors thrown during the request lifecycle. This ensures that the client receives a consistent error response format instead of the connection simply closing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2456b78a-f0a0-458d-a0f0-1a7bcf9b4953', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle trailing slashes in URLs?', N'Fresher', N'Chi provides configuration options to handle trailing slashes consistently. By default, it can be configured to redirect or ignore trailing slashes to ensure that different URL formats resolve to the same handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f286550-e058-4cce-b42f-1a7d7ebbb199', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does await and async works in es6?', N'Fresher', N'The async and await keywords enable asynchronous, promise-based behavior to be written in a cleaner style, avoiding the need to explicitly configure promise chains. Async keyword is used along with the function declaration which specifies that this function is now able to accept all types of asynchronous events on itself. Await basically waits for the results which are particularly to be fetched from the source from which that async function is about to fetch the data. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd63e9ed0-6837-4f0a-b5f9-1a883982dd56', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is declaration merging?', N'Fresher', N'Declaration merging is a feature where the compiler automatically combines multiple declarations with the same name into a single definition. This is most commonly seen when extending interfaces or merging namespaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'457b293a-81aa-43ca-bd60-1a8a170bd6db', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the purpose of the Quarkus Extension model?', N'Senior', N'The extension model provides a mechanism for frameworks and libraries to integrate with Quarkus at build time. Extensions define how a library should be initialized, how to optimize its metadata, and which classes should be included in the native image, enabling seamless interoperability with the Quarkus ecosystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc52362b-180b-4857-98db-1a8a46ee5372', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is denormalization in NoSQL?', N'Intern', N'Denormalization is the practice of combining data from multiple entities into a single record. This reduces the need for complex lookups or joins, allowing the database to retrieve all required information in one read operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15f8bb65-9590-4ff2-83c3-1a8a88b67dc6', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the importance of modularity in system design?', N'Intern', N'Modularity involves breaking a system into smaller, independent components that can be developed and maintained separately. This makes the system easier to understand, test, and update without affecting the entire architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
