INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf6ff596-3fa5-4315-8d33-1a8d3896987a', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When debugging a performance bottleneck, why might you use profiling tools instead of just adding more logs?', N'Middle', N'Profiling tools provide a high-resolution view of CPU, memory, and I/O usage over time without the overhead of excessive logging. Logs can inadvertently slow down the system further due to I/O blocking, whereas profilers collect statistical data that highlights hot paths and inefficient algorithms. Profiling allows for a data-driven approach to optimization rather than guessing based on log timestamps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7daafbd7-1397-4c00-80e1-1a8f7fe161c0', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Is Fiber suitable for building RESTful APIs?', N'Fresher', N'Yes, Fiber is highly suitable for RESTful APIs. It provides easy methods for mapping HTTP verbs like GET, POST, PUT, and DELETE to specific functions, making it straightforward to implement CRUD operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f4bf072-12d6-42ad-b725-1a907e01e76c', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Describe the benefits of using ''Form'' guards in Rocket.', N'Middle', N'Form guards provide automatic validation and deserialization for URL-encoded or multipart form data. They ensure that incoming form fields match the expected structure defined in a Rust struct, reducing the boilerplate code needed for input validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d61103c-2def-4639-8d89-1a93292b20da', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are ''opaque types'' and how do they differ from protocols?', N'Middle', N'Opaque types, denoted by ''some'', allow a function to hide the underlying concrete type while ensuring it conforms to a specific protocol. Unlike returning a protocol type directly, opaque types preserve the identity of the underlying type, which is important for performance and type-system constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1df9d53d-23e5-4c93-bc84-1a941fc89ed6', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does the ''Binding'' class facilitate the creation of Domain Specific Languages (DSLs) in Ruby?', N'Senior', N'A Binding object captures the entire state of the execution context, including local variables and self, at a specific point in time. This allows a DSL to execute code within a custom scope, providing access to the context-specific data without needing to pass arguments explicitly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31ec9411-53f4-44b7-8cf0-1a95499f7e6d', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the advantage of using ''Telemetry'' in Phoenix?', N'Middle', N'Telemetry provides a unified way to instrument your code and emit events without coupling your business logic to specific monitoring tools. It allows you to collect metrics on request duration, database query performance, and other system health indicators for better observability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b045bf35-b4a0-4004-b5de-1a9b760f5123', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the performance advantage of Gin?', N'Fresher', N'Gin is built on top of a highly optimized custom HTTP router based on Radix trees. This design minimizes memory allocation and lookup time, making it significantly faster than standard library routers for complex applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'038733dc-56d5-4ef6-988f-1a9e00543adc', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the purpose of the ''ready'' event in Fastify?', N'Fresher', N'The ''ready'' event is emitted once all plugins have been loaded and the server is fully initialized. It is useful for performing final setup tasks that must only run after the entire application configuration is complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c9fbd72-3129-4149-827e-1a9f2da169d5', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the ''N+1'' query problem in ORMs?', N'Middle', N'The N+1 problem occurs when an application executes one query to fetch parent records and then executes N additional queries to fetch related child records. This leads to severe performance degradation and can be solved by using eager loading or joining tables in the initial query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ad78ffe-0a1c-4b86-9342-1a9fafb40fad', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the difference between ''extend'' and ''include''?', N'Fresher', N'The include keyword adds module methods to a class as instance methods, making them available to objects of that class. The extend keyword adds module methods to a class as class methods, making them available on the class itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc198b23-fc61-4629-81d8-1aa08d0c0a20', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the performance implication of using ''try-catch'' blocks inside performance-critical loops?', N'Senior', N'Historically, try-catch blocks prevented engines from applying certain optimizations like inlining. While modern engines have mitigated this, placing them in tight loops can still disrupt the flow of the optimizer and add unnecessary overhead to the execution pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03dc27e4-c58c-436d-936a-1aa0feef4a4f', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How do you handle asynchronous operations in Micronaut?', N'Middle', N'Micronaut is built on a reactive foundation, supporting Java''s CompletableFuture and Project Reactor''s Flux and Mono types. This allows for non-blocking I/O operations throughout the request processing pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a2d2cf1-7fb0-4476-a361-1aa1efa966d5', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do ''layout files'' differ from ''page files'' in SvelteKit?', N'Middle', N'Layout files are used to define common UI elements like headers, footers, or sidebars that persist across multiple pages within a route segment. Page files contain the unique content for a specific route, which is then injected into the layout''s slot.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44fe1499-24ad-4e33-979a-1aa3d7c4945f', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the performance cost of using ''decorator'' metadata in Lit?', N'Senior', N'Decorators introduce a small amount of overhead during class definition and property initialization. While negligible in most applications, in extremely large systems with thousands of components, the cumulative cost of property metadata can impact startup time, although this is usually outweighed by the developer productivity gains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'579647c8-cc8a-47e2-8bd0-1aa3f4534758', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle event listeners?', N'Fresher', N'Svelte handles event listeners using a simple directive syntax attached directly to HTML elements. This allows you to specify a function to be executed when a specific DOM event, such as a click or input change, is triggered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e791ce60-bb02-490a-9bd2-1aa462cd8a48', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What considerations are necessary when migrating a project from Express to Hono regarding middleware behavior?', N'Senior', N'The primary consideration is the shift from a mutable request/response object pattern to a functional, context-based approach. Middleware that relies on Express-specific internal state or synchronous blocking code must be refactored to be asynchronous and context-aware, which generally results in more resilient and predictable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66bc2997-54ad-4b7d-978f-1aa48874f646', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the concept of a ''stop-the-world'' event in the Go garbage collector.', N'Senior', N'A stop-the-world event is a brief moment where the runtime halts all goroutines to perform critical tasks like stack scanning or finalizing the collection cycle. Modern Go versions have optimized these pauses to be sub-millisecond, effectively making them imperceptible in most applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f71facd6-bfa5-4e23-abdf-1aa4dd7c12eb', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why does Fastify prioritize the use of JSON Schema for request and response validation?', N'Middle', N'Fastify uses JSON Schema to compile validation logic into highly optimized functions using JIT compilation. This significantly improves performance compared to runtime validation libraries that interpret rules dynamically for every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4d43778-dce7-4d01-ba6b-1aa900be0444', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Are NoSQL databases ACID compliant?', N'Intern', N'While traditional relational databases strictly adhere to ACID (Atomicity, Consistency, Isolation, Durability) properties, many NoSQL databases prioritize the BASE (Basically Available, Soft state, Eventual consistency) model. However, some modern NoSQL databases have introduced ACID support for specific use cases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2245767d-3f0f-48ec-82dc-1aa9c7586082', N'4c000000-0000-0000-0000-000000000005', N'How does the ''CAP theorem'' influence the choice of a database for a global messaging system?', N'Senior', N'In a global system, network partitions are inevitable, forcing a choice between consistency and availability. For messaging, we typically favor availability and partition tolerance (AP), accepting eventual consistency to ensure that users can always send and receive messages even during regional outages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bcf1cdc-edc6-4b8a-97da-1aaa65f99b90', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Compare the performance impacts of standard Client-Side Navigation vs. Server-side page transitions.', N'Senior', N'Client-side navigation via the Link component fetches only the necessary segment data, updating the DOM without a full page reload. This provides a SPA-like experience with significantly lower latency than a traditional browser-based full page navigation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f39c5815-826e-4bbf-8884-1ab515ef656b', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between pass-by-value and pass-by-reference?', N'Intern', N'Pass-by-value copies the value of an argument into a function, so changes made inside the function do not affect the original variable. Pass-by-reference passes the memory address of the argument, allowing the function to modify the original variable directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
