INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbdbd63f-9767-4e7f-8647-1abe4632ec0a', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the role of the virtual table (vtable) in C++.', N'Middle', N'The vtable is a static array of function pointers used by the compiler to support dynamic dispatch. Every class with virtual functions has a vtable, and each object contains a hidden pointer to the vtable of its class to look up the correct function at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
