INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4ac5b7a-6b58-4a7f-98c7-1ae791ba0aba', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Describe the function of the Bloom filter in Cassandra''s read path.', N'Senior', N'A Bloom filter is a probabilistic data structure stored in memory that allows Cassandra to determine if a specific partition key exists in an SSTable before performing disk I/O. This significantly reduces disk seek overhead by preventing unnecessary reads of files that do not contain the requested data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21b7aa80-aedf-4319-8a81-1ae7e2119975', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the concept of ''Context-Local'' proxies in Flask and how they enable thread-safety.', N'Senior', N'Context-local proxies act as intermediaries that point to the current request or application context, which are managed as thread-local or greenlet-local storage. This allows developers to use global-looking objects like ''request'' or ''current_app'' that automatically resolve to the correct data for the specific thread handling the current request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
