INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d592c91-0f6b-4e6b-9601-1af4bca0eeed', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle a situation where you are asked to provide an estimate for a task you have never performed before?', N'Fresher', N'I would break the task down into smaller, manageable sub-tasks that I am familiar with and estimate each individually. I would also consult documentation or internal resources to understand the complexity and add a buffer for unforeseen challenges. It is better to communicate the uncertainty and the basis of the estimate clearly than to guess a random number.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
