INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'858ec202-ef63-47e0-9220-1b01fd4da126', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How do you calculate the optimal cache size given memory and latency constraints?', N'Senior', N'The optimal size is a balance between the cost of memory and the desired hit rate, typically determined by analyzing the working set size of the application. You must also consider the performance penalty of frequent garbage collection or eviction cycles if the cache size is set too aggressively for the available hardware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
