INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33c4b5ba-723e-44af-914e-1b0b51fa8ef0', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the role of the ''typedef'' keyword beyond simple alias creation?', N'Senior', N'Beyond naming, typedef is used to abstract platform-dependent types into platform-agnostic ones, which is vital for writing portable code. It does not create new types, but rather provides a layer of indirection that simplifies maintenance and ensures consistency across different data models like ILP32 or LP64.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e59d5dab-637c-4b0e-8b17-1b0c35e01fee', N'4c000000-0000-0000-0000-000000000005', N'How do you achieve high availability in a database layer?', N'Middle', N'High availability in databases is achieved through replication, where data is copied to secondary nodes to provide failover capabilities. If the primary node fails, a replica can be promoted to take over, ensuring minimal downtime and data loss.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62267436-8c23-46fc-84c7-1b0d340780f8', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of the ''static'' keyword when applied to a global variable?', N'Intern', N'The static keyword limits the scope of a global variable to the specific file in which it is defined. This prevents other source files from accessing or modifying the variable, ensuring internal linkage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b965cb1c-2a73-4be5-8b06-1b0d4be19ec0', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does Durability guarantee after a transaction commits?', N'Junior', N'Durability guarantees that once a transaction has been committed, the changes are permanent and will survive even in the event of a system crash or power failure. The database ensures the data is stored in non-volatile memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9d81f7b-3883-4504-9a3d-1b0d8aa1ef5c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of the break and continue statements?', N'Intern', N'The break statement is used to exit a loop or switch statement prematurely, while the continue statement skips the current iteration of a loop and proceeds to the next iteration. For example, in a for loop, break will stop the loop entirely, and continue will skip to the next iteration. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f41064a9-86ec-4895-8943-1b0d91a1c0a4', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How do you achieve multi-region availability in DynamoDB?', N'Middle', N'Global Tables provide a managed multi-region, multi-active database solution. It automatically replicates data across multiple AWS regions, allowing you to build applications that are resilient to regional failures and provide low latency to geographically distributed users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83258e99-f434-4a2e-9ae7-1b0e05f7c2fb', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel''s Task Scheduling work and what is required to make it functional?', N'Middle', N'Laravel''s Task Scheduler allows you to define scheduled tasks within the application itself using a fluent syntax. To function, it requires a single Cron entry on the server that calls the schedule:run command every minute, which then evaluates the scheduled tasks based on the defined logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0777277-99e9-43d8-b109-1b0eaa8676bf', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why might you prefer an asynchronous design over a synchronous one for a task?', N'Fresher', N'Asynchronous design is chosen to prevent blocking the main thread, especially when performing I/O operations like network requests. This keeps the application responsive for the user while the background task completes independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7646c039-5ffa-429b-893f-1b0f6bd8910d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the potential impact of a breaking API change on downstream consumers?', N'Senior', N'I analyze the dependency graph and usage telemetry to identify affected consumers. I estimate the effort for providing backward compatibility, deprecation cycles, and coordinated communication, ensuring the transition strategy minimizes disruption to the ecosystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a1e7a6e-b398-4401-876d-1b0fd4562c17', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is modules in ES6?', N'Intern', N'Making objects, functions, classes or variables available to the outside world is as simple as exporting them, and then importing them where needed in other files. Benefits * Code can be split into smaller files of self-contained functionality. * The same modules can be shared across any number of applications. * Ideally, modules need never be examined by another developer, because they’ve has been proven to work. * Code referencing a module understands it''s a dependency. If the module file is changed or moved, the problem is immediately obvious. * Module code (usually) helps eradicate naming conflicts. Function x() in module1 cannot clash with function x() in module2. Options such as namespacing are employed so calls become module1.x() and module2.x().', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b6e932a-cf6b-4177-9a93-1b1297ad2a58', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the primary risk when using an optimistic concurrency control strategy in a database?', N'Middle', N'Optimistic concurrency assumes conflicts are rare and only checks for them during the commit phase, which can lead to high transaction retry rates under heavy contention. It is efficient for read-heavy workloads but performs poorly when multiple users frequently update the same records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79f195d5-c79c-4e07-82c4-1b1298f4c482', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of the Option enum?', N'Intern', N'The Option enum is used to represent a value that might be absent. It forces the programmer to explicitly handle the case where a value does not exist, helping to avoid null pointer exceptions common in other languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd55bfd33-98d7-4859-93dc-1b136a177b9d', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is template inheritance?', N'Intern', N'Template inheritance is a powerful feature that allows you to build a base skeleton template that contains all the common elements of your site. Child templates can then inherit from this base and override specific blocks of content, reducing code duplication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02ce649b-aacb-4119-9b08-1b14b1d7d8dc', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does denormalization differ in NoSQL compared to traditional relational database design?', N'Middle', N'In relational databases, normalization is preferred to reduce data redundancy and ensure integrity. In NoSQL, denormalization is a standard practice where related data is embedded within a single record to eliminate the need for costly joins, thereby improving read performance at the expense of increased storage and potential update complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65d97c54-1c41-42ad-a26e-1b16100db5a8', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the purpose of ''q-loader.js'' in the browser?', N'Middle', N'The q-loader is a tiny runtime script that acts as the entry point for Qwik. It intercepts user events, resolves the required symbols, and lazy-loads the corresponding code chunks to fulfill the interaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51bfde26-4684-41ab-94eb-1b16b2a5ca7f', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why does Ember use a convention-over-configuration approach?', N'Middle', N'Convention-over-configuration reduces the cognitive load on developers by providing a standard structure and naming system that the framework expects. This eliminates the need for boilerplate configuration files and allows new developers to understand the project structure immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a61d790e-fadd-4ff8-9fc9-1b198f6e3e3d', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How can Django''s ORM be extended to support non-relational data types like JSONB?', N'Senior', N'Django natively supports JSONField for PostgreSQL, which maps to JSONB, allowing for efficient querying and indexing of nested data. For other engines, custom model fields or third-party wrappers can be used, though they often lack the depth of optimization provided by the native PostgreSQL implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b74e5559-379b-4683-a9bf-1b1a1074ec3b', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB handle partition hot-key issues, and what architectural trade-offs are involved in mitigating them?', N'Senior', N'Hot-key issues occur when a specific partition key receives disproportionate traffic, exceeding the allocated throughput. Mitigation involves using partition key salting to distribute load or redesigning the schema to avoid high-cardinality imbalances. The trade-off is increased complexity in query patterns and the need for scatter-gather operations on the client side.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8252db3e-728e-4446-9d3a-1b1d9b7b8cca', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik prevent the ''waterfall'' problem in data fetching?', N'Senior', N'Qwik City provides loaders that allow data to be fetched in parallel with the HTML streaming. By pre-fetching data on the server and serializing it into the initial response, Qwik eliminates the need for the client to initiate further requests for core page data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8775397-1f94-44d6-9152-1b1ea269c9aa', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is Encapsulation and why is it important?', N'Junior', N'Encapsulation is the practice of bundling data and methods that operate on that data within a single unit or class. By making data private and providing public getter and setter methods, it protects the internal state of an object from unauthorized access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd272ab6-4119-4453-b937-1b1f89a421c6', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the importance of ''namespacing'' in R packages?', N'Middle', N'Namespacing prevents function name collisions by explicitly defining which functions are exported and which are kept internal to the package. It also ensures that the package''s code always finds the correct dependencies, even if other packages are loaded in the global workspace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa80ba6b-5c78-488e-a826-1b20322602c8', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain the difference between ''Named'' and ''Global'' middleware in AdonisJS.', N'Middle', N'Global middleware runs on every single incoming HTTP request, making it suitable for security headers or logging. Named middleware is explicitly assigned to specific routes or route groups, allowing for granular control over authentication or authorization requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6fcab01-3a20-4a84-8dbc-1b21b6bc9dd1', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web perform request validation?', N'Junior', N'Request validation is typically handled by using extractors combined with deserialization. By defining a struct that implements the Deserialize trait, you can automatically validate that incoming JSON or form data matches your expected schema.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60e53610-25af-4082-8f9f-1b221d2b2e52', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why is ''Cache Eviction'' complexity important for high-throughput systems?', N'Senior', N'In high-throughput systems, the CPU overhead required to maintain eviction metadata can become a performance bottleneck. Simpler algorithms like FIFO or random eviction are sometimes preferred over complex LRU implementations to minimize the lock contention and computational cost per access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17f42d1e-cb37-4591-a821-1b24e1d23322', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of a session in PHP?', N'Intern', N'A session is a way to store information to be used across multiple pages for a single user. Because the HTTP protocol is stateless, sessions allow the server to recognize the user and maintain their state, such as login status.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b21051f-fa9c-4247-8095-1b2b49fa6811', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How do ''type lambdas'' facilitate advanced functional programming patterns in Scala?', N'Senior', N'Type lambdas allow the creation of anonymous type functions, which are essential for defining complex abstractions that require higher-kinded types. They are a powerful tool for library authors to create generic abstractions that work across varied types, even though the syntax can be intimidating for less experienced developers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3bb18f2-1c6a-495f-a824-1b2baeac32db', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you design a system to be idempotent when processing messages from a queue?', N'Middle', N'I would assign a unique identifier to each message and store a record of processed IDs in a fast-access database. Before performing any state-changing operation, the service checks if the ID has already been processed and skips the action if it has, ensuring that duplicate messages do not cause duplicate side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b57259c-d045-4cc5-bf9a-1b2c3a4492a1', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why is the use of ''Phoenix.LiveView'' considered a paradigm shift for state management in web applications?', N'Senior', N'LiveView shifts state management from the client-side JavaScript layer to the server-side process, keeping the view in sync via a persistent WebSocket connection. This reduces complexity by eliminating the need for client-side API orchestration and data synchronization logic while keeping the UI responsive through diff-based patching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8617d189-4700-4b5f-9992-1b2c479c621a', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How do you handle race conditions in Redux when multiple asynchronous actions are dispatched for the same resource?', N'Senior', N'Race conditions are managed by implementing logic that ignores stale responses, typically by using a unique identifier or a timestamp to validate that the result matches the most recent request. Advanced middleware like Redux-Saga provides specific effects like ''takeLatest'' to automatically cancel previous pending tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc100922-f26c-4a50-a8d7-1b2ff0dff888', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the differences between the freeze and seal methods', N'Intern', N'If an object is frozen using the Object.freeze() method then its properties become immutable and no changes can be made in them whereas if an object is sealed using the Object.seal() method then the changes can be made in the existing properties of the object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9d0cb32-3cff-485a-89a4-1b3398532277', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Is it possible to use React DevTools with Preact, and what is required?', N'Middle', N'Yes, Preact supports React DevTools via a specific bridge package. This requires adding a alias or a specific import to map Preact internals to the format the DevTools extension expects, allowing developers to debug component trees and state effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9b0dde1-88a5-46bb-85da-1b3878a5aa6c', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs between implementing authentication via session cookies versus JSON Web Tokens (JWT)?', N'Middle', N'Session cookies are stateful and managed by the browser, making them easier to revoke, but they are vulnerable to CSRF attacks and complicate scaling across distributed servers. JWTs are stateless and easy to scale across services, but they are difficult to revoke before expiration and require careful management of sensitive payloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2067d48f-7014-42a2-b9c4-1b3881aa124b', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the architectural impact of Litestar''s lack of a global app instance?', N'Senior', N'By avoiding a global app instance, Litestar promotes the factory pattern, which is crucial for testing and containerization. It allows for multiple isolated instances of the application to exist within a single process, facilitating easier integration testing and complex deployment scenarios like blue-green or canary deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94975f20-b1e8-42a9-a3a5-1b38a0b1e1f2', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Describe the impact of the single-threaded event loop on long-running commands.', N'Senior', N'Since Redis executes commands sequentially in a single thread, long-running operations like KEYS * or large SINTER operations block the entire server. This stalls all subsequent requests, making it critical to avoid O(N) complexity commands in production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00869efa-0d24-478d-9543-1b3a807109f1', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are server-only files in SvelteKit?', N'Intern', N'Server-only files, denoted by the .server.js or .server.ts extension, are modules that contain logic meant to run exclusively on the server. SvelteKit ensures that the code inside these files is never sent to the client, which is useful for keeping API keys and database logic secure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ae7de9d-1a19-4bd4-a215-1b3af9239144', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What are the trade-offs of using a NoSQL document store versus a relational database for a rapidly scaling application?', N'Senior', N'Document stores offer flexible schemas and horizontal scalability out of the box, making them ideal for unstructured data and rapid feature iteration. Relational databases provide strong consistency, complex query support, and transactional integrity, but are harder to scale horizontally without specialized sharding middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1fb6b4a-8263-4d9f-9e6e-1b3c360392a4', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'When should you prefer an optimistic locking strategy?', N'Middle', N'Optimistic locking is best for workloads where data contention is low and the cost of retrying a transaction is minimal. It provides higher performance than pessimistic locking by avoiding the overhead of managing locks and the risk of deadlocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed79f38d-1bcb-4c6f-bead-1b3d003347b1', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are variables in Sass and what are their benefits?', N'Fresher', N'Variables in Sass allow you to store information like colors, font stacks, or sizes and reuse them throughout your stylesheet. This is beneficial because if you need to change a value, you only need to update it in one place, ensuring consistency across the entire project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e500ffd2-4729-4e6f-a623-1b3ea99b8ed7', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does a database know when to roll back a transaction?', N'Fresher', N'A database monitors the transaction log for errors, constraint violations, or explicit rollback commands. If a failure occurs before a commit is finalized, the recovery process uses the log to undo partial changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5f9e60d-003b-4a6c-871c-1b3eaedb89ca', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of ''Prepared Statements'' regarding the query planner?', N'Senior', N'Prepared statements allow the database to parse, analyze, and plan a query once, reusing that plan for subsequent executions with different parameters. This reduces overhead for frequently executed queries, though it can lead to suboptimal plans if the data distribution varies significantly across parameters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
