INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f30748d-986f-41ef-8822-1b4a35de2605', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain the role of the AdonisJS Service Provider in the context of Dependency Injection and why it is a preferred pattern for managing application state.', N'Middle', N'Service Providers are the central place to boot, configure, and register services into the IoC container. This pattern decouples service instantiation from the business logic, allowing for easier mocking during unit testing and ensuring that dependencies are resolved dynamically at runtime rather than being hard-coded throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77f22be4-04c1-4922-a701-1b4f542ece3d', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is a scope function?', N'Intern', N'Scope functions are standard library functions like ''let'', ''run'', ''also'', ''apply'', and ''with'' that execute a block of code within the context of an object. They make code more readable by grouping operations on a specific object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3966201a-a94d-4f74-89fb-1b5244a39961', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the difference between a Filter and an Interceptor in Micronaut?', N'Fresher', N'A Filter is primarily used to intercept and modify incoming HTTP requests and responses globally. An Interceptor is used to add cross-cutting logic, such as logging or security, to specific method calls using AOP.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
