INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ffcf4b9-b599-4352-a74c-1b5691c160df', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the primary difference between variance annotations in Scala and Java''s wildcard-based generics?', N'Senior', N'Scala uses declaration-site variance, where the variance is defined within the class or trait definition, making the relationship between types explicit and reusable. Java uses use-site variance with wildcards, which provides more flexibility for individual method calls but increases the verbosity and cognitive load of type signatures. Scala''s approach provides tighter type safety and cleaner APIs for library consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'587eabc9-4f3c-4ae4-997b-1b5697cfd69e', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the benefit of Svelte''s ''props'' being exported versus React''s pass-through props?', N'Middle', N'Exporting props makes the component interface explicit and clear, which helps with tooling and documentation. It allows for a more direct data flow and avoids the prop-drilling issues often associated with complex component hierarchies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3c6a5a1-2b39-4e78-af6b-1b583d8a8544', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How do you ensure data integrity during a network partition in a distributed queue cluster?', N'Senior', N'Integrity is managed via consensus algorithms like Raft or Paxos, which require a quorum of nodes to acknowledge a write before it is committed. During a partition, the minority side will stop accepting writes to prevent split-brain scenarios, prioritizing consistency over availability in alignment with the CAP theorem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10bb1d14-c861-4f6f-83fe-1b58bfb02216', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the primary difference between a relational database and a NoSQL database in terms of data structure?', N'Junior', N'Relational databases use a structured schema with predefined tables, rows, and columns, making them ideal for data with strict relationships. In contrast, NoSQL databases are schema-less or flexible, allowing for the storage of unstructured or semi-structured data like documents, key-value pairs, or graphs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0485c97a-3dca-4ba7-9bd1-1b5b0cac938f', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What does the ''Responder'' trait do in Actix?', N'Fresher', N'The Responder trait is used to convert a return value from a handler function into an HTTP response. Any type that implements this trait can be returned from a handler, allowing developers to return strings, JSON, or custom objects directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd392421f-bdf8-4364-b6ee-1b5c5a84f896', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain classes in TypeScript. How are they different from ES6 classes?', N'Fresher', N'While TypeScript and ES6 classes share many similarities, TypeScript''s classes offer additional features and strong typing to make your code more robust. Key Shared Class Features - Inheritance: Subclasses (children) can extend parent classes, inheriting their methods and properties. - Polymorphism: Derived classes can define methods with the same name as their parent. - Encapsulation: Data hiding is supported through access modifiers, such as public, private, and protected. - Constructor: Instantiation starts with a constructor method, if defined. Unique TypeScript Class Features Field Declaration In TypeScript, you can specify fields directly in the class without initializing them. Automatic initialization to undefined occurs during object creation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b75f78fb-eb43-4bb4-99ab-1b5daff65ac2', N'954a0331-deff-4399-b588-96f39fec001d', N'What is an ngModule?', N'Intern', N'An NgModule is a class decorated with @NgModule that defines a module in Angular. It acts as a container for a cohesive block of functionality, grouping related components, directives, pipes, and services. Its primary purposes are to: - Organize application code into logical units - Configure the Angular compiler to process components and templates - Configure the injector to make services available for dependency injection - Control the visibility of components, directives, and pipes to other modules Key properties within the @NgModule decorator include: - declarations: Lists components, directives, and pipes that belong to this module - imports: Lists other NgModules whose exported classes are needed by components in this module - providers: Lists services that the injector should create...', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80b4b304-2002-478e-af36-1b62a6ea31ae', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a document update in Elasticsearch?', N'Fresher', N'In Elasticsearch, documents are immutable, meaning they cannot be modified in place. An update actually involves retrieving the existing document, making changes, and re-indexing it as a new version while marking the old version for deletion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8156121f-1d45-4dd2-bcb8-1b64149a3350', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the role of the Fastify ''instance''?', N'Junior', N'The Fastify instance is the core object of your application that provides the API for registering routes, plugins, hooks, and configuration. It acts as the central hub for managing the server lifecycle and state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b97d1c70-db88-49ef-9c4f-1b66fa36822d', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are cookies and how does Express handle them?', N'Junior', N'Cookies are small pieces of data stored on the client side by the browser. Express handles cookies using the ''cookie-parser'' middleware, which populates the req.cookies object with data sent by the client, and the res.cookie method to send cookies back.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52fc3ac0-fa5c-44dd-85e2-1b678714cdd5', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the CSS box model differ between ''content-box'' and ''border-box''?', N'Middle', N'In ''content-box'', the width and height properties only include the content area, meaning borders and padding are added on top. In ''border-box'', the width and height include the content, padding, and borders, which makes calculating total element dimensions much more intuitive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d2cb5e3-23e8-4c56-980a-1b68cba8bc3a', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'In a large-scale enterprise application, how does Tailwind CSS affect the browser''s CSSOM performance?', N'Senior', N'Because Tailwind encourages the reuse of atomic classes, the browser CSSOM tree remains shallow and predictable. While the total number of classes in the HTML is high, the actual number of unique CSS rules is strictly limited to those used, which prevents the CSSOM from growing unbounded as features are added.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf0d5079-75f2-4292-8c4c-1b6b143f31a1', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of an Alias in Elasticsearch?', N'Intern', N'An alias is a virtual name that points to one or more indices. It allows you to perform operations on a group of indices as if they were a single index, and makes it easy to switch indices without updating application configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56b095a1-c9b6-4a7a-becb-1b6c9e9480d3', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is operator overloading?', N'Fresher', N'Operator overloading allows programmers to redefine the way standard operators, such as plus or minus, work with user-defined types like classes. This makes custom objects easier to use and allows them to behave in a more intuitive, natural way.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81f9b13a-7299-4095-9ff8-1b7019c672ba', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are the trade-offs of using SvelteKit''s ''adapter-auto'' versus a platform-specific adapter like ''adapter-node''?', N'Senior', N'adapter-auto attempts to detect the environment and configure deployment automatically, which is convenient but can hide necessary platform-specific optimizations. adapter-node provides full control over the runtime environment, making it better for custom containerized deployments where you need fine-grained control over headers, caching, and server-side resource limits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5dc2ef30-b736-48c2-9cb2-1b74e0d3d5af', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a situation where the application is consuming excessive disk space?', N'Middle', N'I would use system utilities to identify which directories or files are growing rapidly, such as log files, temporary files, or database snapshots. If logs are the culprit, I would implement log rotation or adjust the logging levels to reduce verbosity. If it is data-related, I would investigate the archival process or cleanup scripts that might be failing to run.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa1aa702-ffc3-4140-8f26-1b750fcc02ce', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you decide whether to offload a task to a background worker?', N'Middle', N'I offload tasks that are not required for the immediate request-response cycle, such as sending emails, generating reports, or performing heavy data processing. This improves user-perceived latency and allows the system to manage resource allocation more effectively during peak times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'992a0d4a-4630-4987-bf36-1b77da8a4216', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why does Swift prefer value types over reference types for architectural modeling?', N'Senior', N'Value types enforce thread safety by default because they are copied upon assignment, preventing hidden state mutation across different parts of an application. This eliminates the need for complex locking mechanisms or synchronization primitives required by reference types. By reducing shared mutable state, value types make codebases more predictable and easier to debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc9f8849-90f2-43eb-84a7-1b7d488190de', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your reasoning when selecting between a batch processing job and real-time stream processing?', N'Middle', N'I choose batch processing for high-volume, non-time-sensitive data where throughput is the priority. I choose stream processing for scenarios requiring immediate insights or event-driven actions where data needs to be processed as it arrives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4668b246-5f45-4285-b662-1b7e52ce96c7', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the strategy for error handling in Hono to ensure consistent API responses?', N'Middle', N'Hono provides a global error handler middleware that catches unhandled exceptions during the request lifecycle. This allows developers to return standardized error structures, ensuring that the client always receives a predictable JSON response even when internal errors occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57d269c8-bef5-4de4-8190-1b7e691c0149', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the concatenation?', N'Intern', N'This is very basic Python Interview Question, try not to make any mistake in this. Concatenation is joining two sequences. We use the + operator for this. ''32''+''32'' ''3232'' [1,2,3]+[4,5,6] [1, 2, 3, 4, 5, 6] (2,3)+(4) Traceback (most recent call last): File " ", line 1, in (2,3)+(4) TypeError: can only concatenate tuple (not "int") to tuple Here, 4 is considered an int. Let''s do this again. (2,3)+(4,) (obj,) is way to declare single empty (2, 3, 4)', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfae08fc-c2b3-4ca3-8b38-1b7ee7357fef', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Are Svelte components compiled into standard JavaScript?', N'Junior', N'Yes, Svelte compiles components into efficient, standard JavaScript classes or functions. The resulting code manipulates the DOM directly, making it highly performant and easy for browsers to execute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'389840bc-c36f-42cd-a6ee-1b7ff14cd26f', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain the architectural implications of the CAP theorem in system design.', N'Senior', N'The CAP theorem states that in the presence of a network partition, a system must choose between consistency and availability. Architects must evaluate business requirements to determine which property is more critical, often opting for ''AP'' in high-scale web systems and ''CP'' in financial or transactional systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bfd225f-331e-4ae5-a78e-1b87749c0b7a', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the risk of applying a quick fix without understanding the root cause?', N'Fresher', N'Applying a quick fix without understanding the root cause often leads to ''band-aid'' solutions that may cause more complex issues later. It also leaves the underlying flaw in the system, which will likely manifest as a different error in the future.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8d6cfa2-2bca-4720-828a-1b87f981b17d', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Why would you choose MongoDB over a relational database for a highly evolving schema?', N'Senior', N'MongoDB’s flexible schema allows for polymorphic data structures without requiring expensive ''ALTER TABLE'' operations. This is advantageous for agile development where data models change frequently, as it avoids the downtime and complexity associated with schema migrations in rigid SQL systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3f68ca0-fe0f-476d-b038-1b887a8ad0cc', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do async generators and for await...of enable streaming data processing?', N'Fresher', N'An async generator (async function*) is a function that produces values asynchronously via yield. Each yield pauses execution until the consumer calls .next(), which returns Promise . for await...of is the idiomatic consumer — it automatically awaits each .next() call, making streaming processing look synchronous. This pattern enables lazy, backpressure-aware pipelines: data is produced and consumed one chunk at a time rather than loading an entire dataset into memory. Example: Real-World Use Case: Node.js 18+ natively supports async iteration over fetch response bodies: for await (const chunk of response.body). AWS S3 SDK v3 returns async iterables for ListObjectsV2Command pagination.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78acf718-3d07-4751-8fdd-1b8ad5d5bbea', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How does team size and communication overhead affect your estimation of project delivery?', N'Junior', N'Larger teams require more time for synchronization, meetings, and consensus-building, which reduces individual productivity. I adjust my estimates by accounting for the added time spent on communication and the potential for blockers when many people are working on the same codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62e85464-e95e-417c-8e85-1b8b6014b7fd', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is a ''Route'' in Actix?', N'Intern', N'A route is a configuration that maps a specific HTTP request method and path to a handler function. It tells the framework how to process incoming requests based on the URL structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c412057a-cbee-4233-be01-1b8dc600e44e', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What does the DROP command do?', N'Fresher', N'The DROP command is a DDL operation used to permanently remove an entire database object, such as a table, index, or database. Once executed, all data and the structure of the object are deleted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0834574-411b-4b45-842f-1b8f5dcff078', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between ''map'' and ''compactMap''?', N'Junior', N'The ''map'' function transforms each element of a collection into a new value. ''compactMap'' performs the same transformation but also removes any nil results, returning a collection of non-optional values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05e527c3-f8f1-479b-b05d-1b8f81da79d9', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is normalization in database design?', N'Fresher', N'Normalization is the process of organizing data in a database to reduce redundancy and improve data integrity. It involves dividing large tables into smaller, related tables and defining relationships between them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff6f8813-39a0-4e20-925a-1b915158e2b7', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why is it important to use a consistent naming convention for classes?', N'Junior', N'Using a consistent naming convention makes your codebase easier to read, maintain, and scale. It helps other developers understand the purpose of a class simply by looking at its name, reducing confusion and development time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'792c5c04-3320-436d-bcf0-1b91517e45bd', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain the architectural implications of implementing HSTS and Content Security Policy (CSP) headers.', N'Senior', N'HSTS forces browsers to interact with your site exclusively over HTTPS, mitigating SSL stripping attacks but requiring careful management of subdomain certificates. CSP provides a defense-in-depth mechanism against XSS by restricting the sources from which scripts can be loaded, though it requires rigorous testing to ensure it does not break legitimate dynamic content loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
