INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38854566-41da-4d69-9838-1b92b4521bdc', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a shard in the context of Elasticsearch?', N'Junior', N'A shard is a smaller, self-contained portion of a larger index that allows the data to be distributed across multiple nodes. This partitioning enables the database to scale horizontally and process large datasets in parallel.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38f6d8b6-26de-4632-91b8-1b93e9e803e3', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the role of the ''Serializer'' component in a headless architecture?', N'Middle', N'The Serializer component transforms complex objects into formats like JSON or XML and vice versa. It is essential in headless architectures for ensuring consistent data exchange between the backend and frontend, handling normalization and denormalization automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
