INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'563679ff-104f-4114-81aa-1b95c76d4fd6', N'4c000000-0000-0000-0000-000000000005', N'What is the purpose of an API Gateway?', N'Middle', N'An API Gateway acts as a single entry point for all client requests, handling tasks like authentication, rate limiting, and request routing. It simplifies client interactions by abstracting the complexity of the underlying microservices architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ac7df39-ef44-408f-a9ca-1b95eb90b850', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the trade-off between using Chi''s context-based routing versus standard library path pattern matching?', N'Senior', N'Chi provides a more expressive and performant routing tree that supports URL parameters and wildcard matching, which the standard library lacked for years. While the standard library has improved, Chi''s implementation remains highly optimized for complex RESTful structures, sacrificing a tiny bit of dependency-free purity for significantly better developer ergonomics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c227adf7-3aa3-451d-9b28-1b9672360149', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why is the order of middleware registration crucial when implementing security headers like Helmet?', N'Senior', N'Security middleware must be registered at the very top of the stack to ensure that all responses, including those generated by error handlers or static file serving, are correctly decorated with headers. If registered late, some responses might be sent without the necessary protection, leaving the client vulnerable to injection attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f77093a-56a6-428e-aaa5-1b9a0b9d80db', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are the common ways to style components in Preact?', N'Fresher', N'You can style Preact components using standard CSS classes, CSS-in-JS libraries, or inline styles. Since Preact supports standard HTML attributes, the ''class'' attribute is used instead of ''className'', though ''className'' is also supported via compatibility aliases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
