INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94f0d5c2-9b2b-43f7-a822-1b9d4e80e02f', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the difference between a Module and a Provider?', N'Junior', N'A module acts as a container or organizational unit that collects related parts of the app. A provider is the specific service or class that contains the actual logic being used by other parts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0eb2bb1-85c0-4fcb-82f6-1b9f0aef28af', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the design goals of service workers?', N'Intern', N'Below are the list of design goals of Angular''s service workers, 1. It caches an application just like installing a native application 2. A running application continues to run with the same version of all files without any incompatible files 3. When you refresh the application, it loads the latest fully cached version 4. When changes are published then it immediately updates in the background 5. Service workers saves the bandwidth by downloading the resources only when they changed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
