INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de12da0b-7bce-4f6f-b3a9-1ba398b1768f', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do ''rest parameters'' work in SvelteKit routing?', N'Middle', N'Rest parameters allow a route to capture an arbitrary number of path segments, which is useful for building dynamic routing systems like wikis or file explorers. The captured segments are provided as an array in the page parameters, allowing for flexible URL handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd5359a1-be8b-4d90-9fc2-1ba5452ad65d', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the primary difference between Symfony''s ''KernelEvents::REQUEST'' and ''KernelEvents::CONTROLLER'' events?', N'Senior', N'The REQUEST event is triggered early in the lifecycle before the controller is identified, making it ideal for global request transformations. The CONTROLLER event is triggered after the controller has been resolved but before execution, allowing for last-minute modifications to the controller instance or arguments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
