INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1c78370-7bbc-4e55-a2f7-1bad2a327807', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript handle type inference for recursive types, and what are the limitations?', N'Senior', N'TypeScript uses a deferred resolution strategy for recursive types to prevent infinite loops during type checking. However, the compiler has a fixed recursion depth limit, and attempting to express overly complex self-referential types can lead to ''Type instantiation is excessively deep'' errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da97bfd5-733a-48b1-aa0a-1baec04a88c3', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle styling within components?', N'Fresher', N'Lit allows you to define styles using tagged template literals, which are then scoped to the component''s shadow DOM. This ensures that styles are encapsulated and do not interfere with the rest of the application''s global styles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96694d45-f35a-4070-ba02-1baf18e1b213', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Explain the role of the BeanContext in Micronaut and how it manages application state.', N'Senior', N'The BeanContext is the core container that manages the lifecycle of beans, handling instantiation, dependency injection, and destruction. It maintains a registry of definitions and singleton instances, ensuring thread-safe access and efficient resource management throughout the application lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21f618f6-eee1-4db6-ade1-1bb1716df5e3', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How can Hono be tested without spinning up a live server?', N'Middle', N'Hono allows for direct invocation of route handlers by passing a mock Request object to the application instance. This enables fast unit testing of business logic without the overhead of network I/O or full server initialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f6c357c-1b04-41f5-af42-1bb67ee16448', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the impact of using ''cookies'' for server-side state in SvelteKit?', N'Senior', N'Using cookies allows for persistent state identification across requests, which is crucial for server-side auth checks. However, they must be managed with care regarding security flags like ''HttpOnly'' and ''Secure'' to prevent XSS and interception, and they add overhead to every request header.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc4f7e7f-99a9-436a-a125-1bb7f4978ebb', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How do you manage database migrations in Quarkus?', N'Junior', N'Quarkus supports tools like Flyway or Liquibase through dedicated extensions. These tools allow developers to version control their database schema changes and automatically apply them during application startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2185b05-0afb-460e-b92f-1bbbcb422200', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is meant by the term ''Atomic'' in ACID properties?', N'Intern', N'Atomicity ensures that a series of database operations are treated as a single ''unit of work.'' Either all the operations succeed, or none of them are applied, which prevents partial updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c454ac1e-473e-42af-ae61-1bbe32ed640c', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Explain how ''hasChanged'' in a reactive property declaration can be used for performance optimization.', N'Senior', N'The ''hasChanged'' function allows you to define custom logic for determining if a property update should trigger a re-render. By default, Lit uses strict equality, but custom logic allows you to optimize by ignoring shallow changes in complex objects or arrays, preventing unnecessary update cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'376965c9-3ef2-4da7-a560-1bc08a47fafa', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle CORS and why is it managed at the middleware level?', N'Middle', N'CORS is managed as middleware because it requires intercepting every request to add appropriate security headers before the business logic executes. Handling this at the middleware level ensures that even pre-flight requests are correctly addressed without reaching the core application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5290eb4-30ef-4b1c-8bb5-1bc305488fe5', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What happens if a handler in Echo returns an error?', N'Fresher', N'If a handler returns an error, Echo''s default HTTP error handler catches it and sends a corresponding error response to the client. This prevents the application from crashing and ensures that the client receives a structured error message.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc946216-cb57-4f65-9267-1bc3841892bc', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Why is Hono particularly well-suited for Cloudflare Workers?', N'Middle', N'Hono is designed to work natively with the Fetch API, which is the primary interface for Cloudflare Workers. It avoids dependencies on Node.js built-in modules, ensuring it fits perfectly within the restricted V8 isolate environment without requiring polyfills.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c7d2e16-de9c-433c-adfe-1bc6548acf97', N'075b8862-431c-4678-9767-f55359758a4a', N'What are computed properties and when should you use them?', N'Junior', N'Computed properties are used to define logic that depends on other reactive data sources. They are cached based on their dependencies and only re-evaluate when one of those dependencies changes. You should use them to simplify complex expressions in your templates and to perform data transformations efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90234720-f301-421b-bb4f-1bc6ca34159a', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the primary benefit of using Echo''s Context object instead of the standard http.ResponseWriter and *http.Request?', N'Middle', N'The Echo Context interface provides a unified, simplified way to access request data, bind parameters, and handle responses. It abstracts away the underlying HTTP implementation, offering helper methods for JSON serialization, status code setting, and cookie management that reduce boilerplate code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd045a127-e627-4caf-9be5-1bc77decbd9a', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro''s partial hydration model reduce the risk of layout shift (CLS)?', N'Senior', N'By server-rendering the initial HTML state of all components, Astro ensures that the page layout is established before any client-side JavaScript is downloaded. This eliminates the ''flicker'' or layout shifts often caused by client-side frameworks that render empty placeholders before fetching data and hydrating the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2eac15c-bf6b-4d88-9720-1bc9e12b86bf', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the role of the dispatch method?', N'Fresher', N'The dispatch method is the only way to trigger a state change in Redux. You call store.dispatch with an action object, which then triggers the reducer to calculate the new state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
