INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49a21eac-f55a-41ad-bcd9-1bcc77c9c6ae', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of ''AssemblyLoadContext'' in modern .NET?', N'Senior', N'AssemblyLoadContext provides a mechanism for loading, isolating, and unloading assemblies within a process. It replaces the legacy AppDomain model, offering more control over how dependencies are resolved and enabling scenarios like dynamic plugin loading. It is essential for building modular architectures that require runtime extensibility without process restarts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
