INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c7dd56c-46dd-46e8-82be-1bd59d8724f9', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Explain the architectural trade-offs of using @extend versus @mixin in a large-scale project.', N'Senior', N'Using @extend can lead to unexpected selector chaining and bloated CSS files if not managed carefully, as it modifies the inheritance tree. @mixin is generally safer and more predictable for modular architecture, though it can increase the total file size due to duplicated declarations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
