INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1f2ed3e-bc3a-48ee-8642-1be16aacda93', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the risk of ''Type Widening'' and how ''as const'' can mitigate it.', N'Senior', N'Type widening occurs when the compiler automatically treats a literal value as a more general type, such as ''string'' instead of ''hello''. Using ''as const'' forces the compiler to treat values as literal types, which is essential for maintaining strictness in configuration constants.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
