INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'375c4a80-bb09-43b5-8a3f-1be78d3e38fe', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does the ''Result'' type in Kotlin compare to traditional exception handling for error propagation?', N'Senior', N'The Result type forces developers to explicitly handle error states as data, which improves the visibility of potential failures compared to hidden, unchecked exceptions. While it provides cleaner control flow in functional chains, it can be abused by overusing it for expected business logic errors instead of exceptional, unrecoverable system failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc953f0c-7b82-40e1-b27a-1be8cf9100ce', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do you achieve ''nominal typing'' in a structural system like TypeScript?', N'Middle', N'You can simulate nominal typing by using ''branded'' or ''tagged'' types, which involve adding a unique, often empty, property to an interface. This forces the type system to treat objects as distinct even if they share the same underlying structure, preventing accidental mixing of different data types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c369d5a9-3e05-40eb-9c78-1beb42a8e22d', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What architectural challenges arise when implementing Server-Side Rendering (SSR) in Svelte compared to client-only apps?', N'Senior', N'SSR in Svelte requires the compiler to generate string-based output for static HTML while maintaining state hydration markers. The primary challenge is ensuring that the client-side bundle correctly maps to the server-rendered DOM nodes, which requires careful management of hydration scripts and initial state serialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
