INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfb3fee5-b94c-40bf-ab88-1c01072f6d0f', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the significance of ''Self-Types'' in Scala''s module system?', N'Senior', N'Self-types allow a trait to declare that it can only be mixed into another type, effectively asserting a dependency on that type''s members. This enables a form of structural subtyping that is more flexible than traditional inheritance. It is a key tool for decomposing complex systems into smaller, manageable units while enforcing architectural constraints at compile time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8761d2f3-cfa3-443a-b2cd-1c016fb0f8a6', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux support SSR (Server-Side Rendering)?', N'Senior', N'Redux supports SSR by allowing the server to initialize the store with a state object, render the initial HTML, and serialize that state into the response. The client-side application then reads this serialized state to ''hydrate'' the store, ensuring that the client and server start with an identical data structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b192e900-4c5c-4784-8023-1c020f1e7fd5', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Why is the ''volatile'' keyword insufficient for compound operations like incrementing a counter?', N'Senior', N'While volatile guarantees visibility and prohibits instruction reordering, it does not provide atomicity for read-modify-write sequences. An increment involves multiple steps; between the read and the write, another thread could modify the value, leading to lost updates, which necessitates atomic variables or locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
