INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'948a0d9f-2805-4b62-9959-1c14e173938b', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut''s ahead-of-time (AOT) compilation approach differ from Spring Boot''s runtime reflection strategy?', N'Senior', N'Micronaut performs dependency injection, proxy creation, and configuration binding at compile-time using annotation processors. In contrast, Spring Boot typically relies on runtime reflection and classpath scanning to build the application context, which increases startup time and memory footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9bf59b2-1c44-40fd-8a5f-1c16b8323cbc', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between Inner Join and Outer Join?', N'Fresher', N'An Inner Join returns only the rows where there is a match in both tables. An Outer Join returns matched rows as well as rows from one or both tables that do not have a match, filling missing sides with nulls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79fb387b-ccd4-424f-81d1-1c1c75c42393', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why does Rust lack inheritance in favor of composition and traits?', N'Senior', N'Inheritance often creates fragile base class problems and complex object hierarchies that are difficult to reason about in concurrent contexts. Traits facilitate polymorphism through behavior sharing rather than state inheritance, which aligns with Rust’s emphasis on explicit data layout and memory safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54d093c9-2075-4c33-80f2-1c1c9050a34b', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What does it mean for Axum to be ''type-safe'' in the context of routing?', N'Middle', N'Axum leverages Rust’s type system to ensure that extractors match the input requirements of a handler at compile time. This reduces runtime errors by catching mismatches, such as missing path parameters or invalid body formats, during the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1e11b44-717d-49bb-bda8-1c1cc3691f80', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How do memory fences and acquire-release semantics influence thread synchronization?', N'Senior', N'Acquire-release semantics define a synchronization point where memory operations performed before a release must be visible to a thread performing an acquire on the same atomic object. This creates a happens-before relationship without requiring a full sequential consistency barrier, offering a performance advantage on architectures with relaxed memory models like ARM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68465dc2-15fe-403f-b394-1c1d0b1846dd', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does sharding contribute to the scalability of a NoSQL database?', N'Middle', N'Sharding is the process of splitting a large dataset into smaller, manageable chunks called shards and distributing them across multiple servers. This horizontal scaling allows the database to handle increased load and storage requirements by adding more nodes rather than upgrading existing hardware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d6cf342-3068-4212-871f-1c1d5e036c19', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is a ''Future'' in the context of Actix?', N'Junior', N'A Future is a value that represents a computation that might not have finished yet. In Actix, many operations return futures, allowing the system to perform non-blocking I/O operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aec85a2a-fbd0-4ec5-9405-1c23f225b77a', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the primary trade-off described by the CAP theorem in distributed systems?', N'Middle', N'The CAP theorem states that a distributed system can only simultaneously provide two of three guarantees: Consistency, Availability, and Partition Tolerance. In the presence of a network partition, a system must choose between cancelling the operation to maintain consistency or proceeding with the operation to maintain availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a32fe398-4acf-4785-a6a5-1c2679f5585e', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the difference between new() and make()?', N'Fresher', N'The new function allocates memory for a type and returns a pointer to its zero value. The make function is used specifically to initialize slices, maps, and channels with their internal data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8dcd941f-c055-4dba-8599-1c2cefa39159', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does dynamic memory allocation work in C?', N'Fresher', N'Dynamic memory allocation allows a program to request memory from the heap during runtime using functions like malloc or calloc. The programmer is responsible for releasing this memory using the free function to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccdf88ee-e348-43f9-bc1b-1c2cf1d42574', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the trade-off of using a master-slave replication architecture?', N'Middle', N'Master-slave architecture simplifies write consistency by centralizing all writes to one node, but it creates a single point of failure and potential bottlenecks. While it scales reads easily by adding slaves, the master node can become overwhelmed, and failover processes can be complex.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70f85f9d-2ae6-4185-92d5-1c2f27b616d2', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between ''++i'' and ''i++''?', N'Fresher', N'The prefix increment (++i) increments the variable first and then returns the new value. The postfix increment (i++) returns the current value first and then increments the variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
