INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c3092c4-7c23-4e79-ac74-1c3a7971d283', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to prevent a function from being called multiple times?', N'Fresher', N'If you use an event handler such as onClick or onScroll and want to prevent the callback from being fired too quickly, then you can limit the rate at which callback is executed. This can be achieved in the below possible ways, 1. Throttling: Changes based on a time based frequency. For example, it can be used using \_.throttle lodash function 2. Debouncing: Publish changes after a period of inactivity. For example, it can be used using \_.debounce lodash function 3. RequestAnimationFrame throttling: Changes based on requestAnimationFrame. For example, it can be used using raf-schd lodash function', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
