INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'890ec0bd-1440-4b08-855e-1c3d97c8bbb3', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is eventual consistency and why is it used in large-scale systems?', N'Middle', N'Eventual consistency allows replicas to be temporarily out of sync, guaranteeing that they will eventually converge to the same state. It is used to achieve higher availability and lower latency by avoiding the performance penalty of synchronous distributed locking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
