INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3067d749-ea7a-4a9e-9f71-1c4166f99520', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How do you mitigate the ''N+1'' query problem in DynamoDB?', N'Senior', N'The N+1 problem is mitigated by using BatchGetItem to retrieve multiple items in a single request rather than making individual calls for each item. Alternatively, denormalizing data to store relationships within a single item can eliminate the need for secondary lookups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
