INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f648d8f3-36a6-40d5-af06-1c42b6c2d3a1', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket''s focus on ''Type-Driven Development'' influence long-term system maintainability?', N'Senior', N'By encoding business rules and protocol requirements directly into the types, the compiler acts as a primary validator. This significantly reduces the need for runtime sanity checks and documentation, as the API contract is effectively self-documenting and enforced by the build system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'263c5a13-ce86-4cdc-bddf-1c430bf56db0', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What are lifecycle hooks in Litestar?', N'Fresher', N'Lifecycle hooks are functions that run during specific stages of the application''s life, such as startup or shutdown. They are commonly used for initializing database connections or cleaning up resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11b20f19-5db8-4474-8dc6-1c466f062146', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do you handle side effects in Svelte components?', N'Middle', N'Side effects are typically handled using reactive declarations or lifecycle hooks like ''onMount''. Reactive declarations ensure that side effects run whenever specific dependencies update, while ''onMount'' ensures code runs only after the component is rendered to the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'916ba828-eb31-4fb7-9a1d-1c47062936cf', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Is Alpine.js reactive?', N'Fresher', N'Yes, Alpine.js is reactive. It tracks the dependencies of your data and automatically re-renders the parts of the DOM that rely on that data whenever it changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47f0ee60-619f-4ab0-9fed-1c48ff4c0e4e', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What does the term ''opinionated'' mean in the context of AdonisJS?', N'Fresher', N'Being opinionated means that the framework provides a specific, recommended way to structure your application and handle common tasks. This reduces decision fatigue for developers by offering built-in solutions for routing, authentication, and validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1935e866-8252-47a1-9d18-1c49880ac75b', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does the ''Reselect'' library optimize performance in Redux-heavy applications?', N'Senior', N'Reselect creates memoized selectors that only recompute their result when their input selectors return different references. This prevents expensive derived data calculations from running on every store update, ensuring that components only re-render when the actual computed data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9673827-68f0-413e-8808-1c4991c25614', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What are the advantages of using Event-Driven Architecture?', N'Middle', N'Event-Driven Architecture allows services to react to changes in state by emitting and consuming events, promoting loose coupling and high scalability. It is particularly effective for complex business processes where components do not need to know about each other''s existence to function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6479080f-4ee9-45b2-bc24-1c4af70cf97e', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the circuit breaker pattern and why is it important for distributed systems?', N'Middle', N'A circuit breaker prevents an application from repeatedly trying to execute an operation that is likely to fail. By failing fast, it prevents cascading failures across a distributed system and allows the failing service time to recover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'803cf30c-9add-42d5-8b55-1c4b732e2b7c', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How does a ''Hexagonal Architecture'' (Ports and Adapters) improve system maintainability?', N'Senior', N'Hexagonal architecture isolates the core business logic from external dependencies like databases, APIs, or UI frameworks using ports and adapters. This makes the system more testable and allows for swapping external technologies without modifying the core domain logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bb4f0cd-0ee8-4be2-bb17-1c4df9332771', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'When would you prefer a message queue over synchronous REST API calls for inter-service communication?', N'Senior', N'Message queues are preferred for decoupling services, handling traffic spikes through backpressure, and ensuring reliable asynchronous processing. They allow producers to offload tasks without waiting for immediate consumer responses, improving overall system responsiveness and fault tolerance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b43c6d16-d973-47c0-bc06-1c52c375d49e', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the difference between a functional bug and a performance issue, and how does your troubleshooting approach differ?', N'Junior', N'A functional bug means the system is doing the wrong thing, requiring a logic check to find where the process deviates from requirements. A performance issue means the system is doing the right thing too slowly, requiring tools like profiling or monitoring to identify bottlenecks like inefficient queries or resource exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1db6eeac-5a90-4db8-89dd-1c52e25b3a23', N'4c000000-0000-0000-0000-000000000005', N'Describe the concept of ''write amplification'' in the context of SSDs and database storage engines.', N'Senior', N'Write amplification occurs when the actual amount of data written to the physical storage media is a multiple of the data intended to be written by the application. This is caused by background processes like garbage collection, compaction, and page-level updates, impacting both performance and device lifespan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5b9b808-7278-4e24-82c0-1c538eb46d70', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If you find a bug in a legacy system, what is the safest way to fix it?', N'Junior', N'The safest way is to first create a test case that reproduces the bug to confirm the failure. Then, I would implement the fix in a staging environment, verify that it passes the new test case without breaking existing functionality, and perform regression testing on related features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79ebafc9-ce9b-4883-bf97-1c540d183984', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of the ''readonly'' modifier?', N'Intern', N'The ''readonly'' modifier is used to make properties in an interface or object immutable. Once a value is assigned to a readonly property, it cannot be changed or reassigned, which helps in preventing accidental state mutations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'139bcdc8-72e7-452c-bd21-1c552111c282', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the purpose of the @Inject annotation?', N'Junior', N'The @Inject annotation is used to tell the CDI container to provide an instance of a specific bean to the class where it is requested. It handles the wiring of dependencies automatically, so the developer does not need to manually instantiate objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
