INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e396aec-23c4-4a61-8d55-1c57a4ca7cf7', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How do you define a companion object and what is it used for?', N'Junior', N'A companion object is an object defined inside a class that is marked with the ''companion'' keyword. It allows you to define members that are tied to the class itself rather than to individual instances, similar to static members in other languages. It is commonly used for factory methods or constants related to that class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59fc41e5-fc48-4874-b4f5-1c583b36da02', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the purpose of the +page.svelte file?', N'Intern', N'The +page.svelte file is a standard component used to define the UI for a specific route in your application. It acts as the entry point for the content that a user sees when they navigate to that particular URL path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef9e92e4-c9ba-45e4-995e-1c5bd428c27f', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web''s type-safe routing contribute to performance and safety?', N'Senior', N'Actix-web uses macro-based routing that resolves paths at compile-time rather than runtime. This ensures that route definitions are checked for correctness before the binary is ever executed and avoids the performance cost of dynamic regex-based path matching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90d8418f-8cee-4ff6-8093-1c5c9bb1d62f', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket''s modularity support larger application architectures?', N'Middle', N'Rocket uses ''mount points'' to organize routes into different groups or modules, which can then be combined into a single application. This allows developers to split the codebase into logical domains, making it easier to maintain and scale as the application grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fd2a16a-9cc6-49e0-b0fc-1c5ec481d8c8', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Describe the purpose of write-ahead logging (WAL) in database durability.', N'Senior', N'WAL ensures durability by recording all changes to a persistent log file before they are applied to the actual data files. If the system crashes, the database can reconstruct its state by replaying the log, ensuring that committed transactions are not lost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8054c702-acea-4af3-a273-1c601700c08b', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why is ''Time-Series Data'' often handled by specialized databases?', N'Senior', N'Time-series data is characterized by massive ingestion rates and temporal-based queries, which traditional databases struggle to optimize. Specialized time-series engines use features like downsampling, TTL-based data aging, and specialized compression to handle the high-velocity data efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6862a6d0-c7cc-42cd-8055-1c642a2c6e8a', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the virtual DOM and why does Svelte not use it?', N'Intern', N'The virtual DOM is a programming concept where a representation of the UI is kept in memory and synced with the real DOM. Svelte does not use it because it adds overhead and complexity; instead, Svelte updates the DOM directly through its compiler, resulting in better performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fd5b3e2-6e5f-4191-94da-1c667eb266f5', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'In what scenarios would you choose a ''Controller'' over a ''Component'' in Ember?', N'Senior', N'Controllers are primarily used to manage state that persists across route transitions, such as query parameters or filters. Components are intended for UI representation and local interaction, meaning controllers are strictly for route-level concerns rather than visual component logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4633eb9f-a5c3-4843-a02c-1c69f1802b71', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is an HTML preprocessor? Have you used different HTML templating languages before?', N'Intern', N'An HTML preprocessor is a tool that lets you write HTML in an extended syntax with features like variables, loops, conditionals, and mixins — then compiles it down to standard HTML that browsers can read. Why Use One? - Avoid repetition — define layouts/partials once, reuse everywhere - Dynamic content — inject server-side data (from DB, API, etc.) into templates - Cleaner syntax — less boilerplate than raw HTML - Inheritance — extend base layouts with child templates Popular HTML Templating Languages * Pug (formerly Jade) * Haml * ERB (Embedded Ruby) * Handlebars * Jinja2 * Liquid The key distinction from plain HTML is server-side rendering of dynamic data — the preprocessor fills in variables, loops through data, and outputs fully-formed HTML before it ever reaches the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24aaee78-5921-4504-90b1-1c6ad6f9c62c', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the primary role of the Flask framework in backend development?', N'Intern', N'Flask is a lightweight WSGI web application framework designed to make getting started quick and easy. Its primary role is to provide the necessary tools and libraries to handle incoming HTTP requests and return appropriate responses, effectively acting as the bridge between a client and a database or server-side logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9cc329fc-3ab9-441f-9a79-1c7385bcb1ed', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What role does ''eventual consistency'' play in high-performance caching?', N'Senior', N'Eventual consistency accepts that the cache may be out of sync with the database for a short duration, allowing the system to scale by avoiding expensive synchronization locks. It is appropriate for systems where the business logic can tolerate minor delays in data propagation, such as social feeds or news updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'027aaaca-14fb-4abc-afb4-1c7896aca6c4', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is a ''Circuit Breaker'' in the context of a messaging-based microservice architecture?', N'Senior', N'A circuit breaker prevents a failing downstream service from being overwhelmed by retries or cascading failures by temporarily halting message dispatching to that destination. Once the downstream service recovers, the breaker allows traffic to resume, protecting the stability of the entire message pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8d73f73-cef4-4f3a-9938-1c79e76ffce5', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are extensions in Dart?', N'Fresher', N'Extensions allow you to add new functionality to existing classes without modifying the original class source code. They are particularly useful for adding utility methods to types that you do not own, such as classes from third-party libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
