INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f85c07e5-11a4-404a-ba12-1c7c72531a99', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How do you handle message persistence in a distributed queue?', N'Middle', N'Message persistence involves writing incoming messages to non-volatile storage, such as a disk, before acknowledging the producer. This ensures that the messages survive broker restarts or system crashes, though it introduces a latency penalty.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'987233b3-c4ed-483a-aefb-1c7ce82c0cb7', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the advantage of Tailwind''s ''mobile-first'' approach?', N'Fresher', N'The mobile-first approach simplifies CSS by requiring fewer media queries. By setting the base styles for mobile and adding responsive modifiers only when the design needs to change for larger screens, the resulting CSS is cleaner and easier to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af4d03e8-3852-421d-9dcf-1c7d0076ca62', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a physical and logical backup?', N'Middle', N'A physical backup copies the raw data files directly, which allows for fast restoration of the entire database cluster. A logical backup, such as a SQL dump, records the data in a portable format, allowing for cross-version migration and granular restores.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
