INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b77f0c4b-b6f9-4448-8d43-1c84c485047f', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the difference between an API ''resource'' and an ''action''?', N'Middle', N'Resources represent nouns or objects like users or orders, while actions represent verbs or operations. RESTful design favors resources in URLs, while actions are often handled by specific HTTP methods or state transitions on a resource.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6043191b-2ab5-41ef-abe1-1c8565aca67d', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the MySQL buffer pool interact with the operating system''s page cache?', N'Senior', N'MySQL''s buffer pool is a user-space memory area that manages its own caching and page lifecycle, effectively bypassing or duplicating the OS page cache. While the OS may cache the data files, the buffer pool provides more granular control over page eviction based on InnoDB-specific access patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16b005bb-c036-4ff2-b9de-1c8ac3e5a5f7', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why does Swift forbid the use of pointers in standard code while providing them for interop?', N'Senior', N'Swift prioritizes memory safety and predictable ownership, which are undermined by manual pointer arithmetic. By restricting pointer usage to Unsafe types and ''withUnsafePointer'' patterns, the language enforces a clear boundary between safe, idiomatic code and the necessary risks of C interop. This design forces developers to explicitly acknowledge and handle the hazards when stepping outside the safety guarantees of the language.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
