INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d87f4e9-ab00-42fc-ad80-1c8ee371c65a', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between client-side and server-side rendering in a web application?', N'Senior', N'Server-side rendering is better for SEO and initial load times, but it increases server load and complicates the architecture. Client-side rendering provides a smoother, app-like experience and offloads processing to the user, but it can suffer from poor performance on low-end devices and SEO challenges. I choose based on the user''s need for interactivity versus the business need for reach and discoverability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8b64694-0555-48b6-9d8a-1c907b358a9a', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When a service is crashing with an ''Out of Memory'' error but heap usage appears normal, where do you look?', N'Senior', N'I would investigate native memory usage, such as thread stacks, direct buffers, or external library memory allocations that exist outside the managed heap. I would also check for OS-level resource limits like cgroup constraints that might be killing the process despite low JVM/runtime heap usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
