INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db8fe94c-2a4e-4fa2-b44f-1cbe0cc83383', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the primary difference between SolidJS signals and React state?', N'Senior', N'Signals are independent observables that do not trigger component re-renders when updated. React state is tied to component lifecycle, forcing a full function re-execution upon change, whereas SolidJS tracks individual reactive atoms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cdb44f2-4e4e-4f35-b4ab-1cbf6e720345', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'An application is running slowly only for one specific user. How would you start investigating this?', N'Junior', N'I would first compare that user''s environment, such as browser, device, or network location, against users who are not experiencing the issue. Then, I would check server-side logs specifically filtered by that user''s ID to see if their specific actions are triggering unique errors or resource-intensive database queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70960f56-4659-4256-847c-1cc20d5ffd9c', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why is the use of ''document.write'' considered an anti-pattern in modern web development?', N'Senior', N'Document.write is synchronous and blocks the HTML parser, which can cause significant delays in page rendering and interactivity. Modern browsers may block these requests entirely for scripts on slow connections, leading to unpredictable behavior and poor performance metrics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13e5e33b-dd28-4da7-8875-1cc2e9607b5a', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What does the .each() method do?', N'Intern', N'The .each() method is a loop function that iterates over a collection of jQuery objects. It allows you to perform an action on every element found by a selector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57fe892b-72bc-4003-bb4c-1ccc0032a89e', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you balance the trade-off between observability (logs/metrics/traces) and system performance?', N'Senior', N'I implement robust observability to reduce MTTR, but I am mindful of the ''observer effect.'' I use sampling for high-volume traces and offload logging to asynchronous agents to ensure that telemetry collection does not introduce meaningful latency or resource contention in the critical path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4ede3e9-0fc1-4a8d-bd09-1cccad4aae88', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does denormalization benefit NoSQL performance?', N'Junior', N'Denormalization allows related data to be stored together in a single place. This reduces the number of read requests and eliminates the need for joins, which significantly speeds up data retrieval in high-traffic applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d9cb18b-a60b-4066-ae57-1ccd75748c30', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the C translation phase deal with translation unit dependencies?', N'Senior', N'C handles dependencies through the preprocessor''s include mechanism, which copies the contents of header files into the translation unit. This simple approach lacks the sophisticated module systems found in newer languages, leading to problems like circular dependencies and redundant work. Developers must manage these dependencies manually using include guards or proper architectural design to keep the build process efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f634f397-64db-41b9-9313-1ccd85fc54b3', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro''s ''View Transitions'' API differ from standard browser navigation?', N'Senior', N'Astro''s View Transitions API intercepts page navigations to perform DOM snapshots and CSS animations between views, simulating a single-page application experience. It maintains scroll position and persistence across page loads without the overhead of a full JavaScript-heavy SPA router.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'157dbf9f-cd94-40d3-969e-1cd05eed5a97', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why is it important to disable dynamic mapping for production environments?', N'Senior', N'Dynamic mapping allows the engine to infer field types on the fly, which can lead to incorrect data typing, such as mapping a numeric field as text and preventing range queries. Explicitly defining mappings ensures data integrity, saves cluster state memory, and prevents the aforementioned mapping explosion issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fcbf9de-3d6b-44b2-83f9-1cd30d7d26bf', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Can Webpack process images?', N'Fresher', N'Yes, Webpack can process images using asset modules or loaders like file-loader. It can copy the image to the output directory and provide the correct path to use in your application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4c638df-9b94-4b86-8a0e-1cd3e4a210f8', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are the performance and accessibility trade-offs when choosing between semantic and non-semantic HTML elements?', N'Middle', N'Semantic elements provide built-in meaning to the browser and assistive technologies, which significantly improves accessibility and SEO without extra effort. While non-semantic elements like divs are flexible, they require additional ARIA roles and labels to convey the same information. Prioritizing semantic HTML reduces the reliance on complex accessibility attributes and helps browsers optimize rendering and navigation paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'037f0728-c84f-46f1-91b5-1cd60a997528', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Is it easy to migrate from React to Preact?', N'Fresher', N'Yes, because Preact mimics the React API, migration is often straightforward. By using the compatibility layer, many existing React projects can be switched to Preact with minimal or no code changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a278dc7-9cb2-4703-a15c-1cd626a65f9d', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why might a system fail only under ''heavy load''?', N'Fresher', N'Heavy load can trigger concurrency issues, resource exhaustion, or race conditions that do not appear during normal operation. These problems occur because multiple processes are competing for the same limited resources simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'333eca39-c9a4-4709-9031-1cd67291834e', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the impact of Remix on ''Time to First Byte'' (TTFB)?', N'Senior', N'Because Remix waits for loaders to resolve before sending the initial HTML, the TTFB can be higher than a static site. However, this is a conscious architectural trade-off that ensures the user receives a fully populated page, avoiding the need for client-side loading spinners or layout shifts common in CSR architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c200ab3-488c-443e-9bc7-1cd8da41e8ac', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does the choice of database index type (e.g., B-tree vs. GIN) impact performance in Rails applications?', N'Senior', N'B-tree indexes are the standard for most columns, providing efficient sorting and range searching. GIN indexes are specialized for complex data types like JSONB or full-text search, offering faster lookup speeds for unstructured data at the cost of slower write performance and larger storage requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d5531bb-5962-480d-8fe2-1cd9227dd9df', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why is Preact''s error boundary implementation considered efficient?', N'Middle', N'Preact''s error boundaries are lightweight wrappers that catch errors in the component tree during the render phase. Because the core library is small, the overhead of wrapping large portions of the application in error boundaries is negligible compared to more bloated frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad4dc19a-8e8e-4a21-9454-1cda1b1a5a87', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does ''Distributed Consensus'' impact system reliability?', N'Senior', N'Distributed consensus protocols like Raft or Paxos ensure that all nodes in a cluster agree on a specific state, which is critical for consistent data storage and leader election. While this increases reliability by preventing data corruption during partitions, it introduces latency overhead due to the required network round-trips for voting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2928b052-3947-4c4c-b33f-1cdaa8234809', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus approach reactive programming compared to traditional imperative models?', N'Senior', N'Quarkus is built on a non-blocking, event-loop-based architecture using Vert.x, which allows it to handle high concurrency with a very small number of threads. It provides a unified reactive model where imperative and reactive code can coexist, optimizing resource utilization by preventing thread blocking during I/O operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5499838-e817-46a9-a932-1cdc98390784', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the PostgreSQL ''vacuum'' process?', N'Intern', N'The vacuum process reclaims storage occupied by dead tuples, which are rows that have been updated or deleted. This helps maintain database performance and prevents table bloat.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0694fcb1-9f9c-4040-a393-1cdfb999f89c', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the significance of the ''GOMAXPROCS'' setting in high-concurrency applications?', N'Senior', N'GOMAXPROCS defines the maximum number of OS threads that can execute user-level Go code simultaneously. Setting this too low limits CPU utilization, while setting it too high can lead to excessive context switching and cache thrashing depending on the nature of the workload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02ef9d09-ce90-4e34-b76f-1ce1305a7981', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using a single large database instance versus multiple sharded instances?', N'Junior', N'A single instance is simple to manage and guarantees strong consistency. Sharding allows the database to scale horizontally to handle massive traffic, but it significantly increases the complexity of application logic, data distribution, and cross-shard queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1aaa9e9-c4a1-45e5-b543-1ce35861d0b1', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of migrations in Symfony?', N'Junior', N'Migrations provide a way to version control database schema changes over time. They allow developers to programmatically define modifications to the database structure, such as adding tables or columns, which can be consistently applied across different environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'863f4365-e1ea-4098-b316-1ce8b2319631', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the difference between a table scan and a query in DynamoDB?', N'Middle', N'A query is restricted to a specific partition key and is highly efficient, while a scan iterates through the entire table. Queries are the standard for retrieving specific data, whereas scans are typically used only for bulk exports or administrative tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd58f63fb-7c3e-4c90-bf68-1cf02fd959b6', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are ''directives'' in Tailwind CSS?', N'Intern', N'Directives are special commands used in your CSS files, such as @tailwind, @apply, or @layer. They tell the Tailwind build engine where to inject the base, components, and utility styles into your stylesheet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2090685-b842-48ad-b63c-1cf214cac523', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain how R handles closures and their impact on memory retention.', N'Senior', N'R closures capture the environment in which they were created, retaining all variables within that scope even after the outer function finishes execution. This can cause significant memory pressure if large data structures are unintentionally held in the closure''s scope, preventing the garbage collector from reclaiming that space.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63f3adc4-c250-4d37-a35d-1cf281d8e78f', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you provide configuration inheritance?', N'Fresher', N'Angular Compiler supports configuration inheritance through extends in the tsconfig.json on angularCompilerOptions. i.e, The configuration from the base file(for example, tsconfig.base.json) are loaded first, then overridden by those in the inheriting config file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f52345d8-d5f3-4098-aaba-1cf3511d1e73', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Describe the difference between vertical and horizontal partitioning (sharding).', N'Middle', N'Vertical partitioning splits a table by columns, often moving frequently accessed columns to one table and rarely used or large columns to another. Horizontal partitioning, or sharding, splits rows across different database instances to distribute the storage and query load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acc55feb-c25d-4f34-bde2-1cf5b784b22c', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the primary purpose of the dollar sign ($) in jQuery?', N'Intern', N'The dollar sign is an alias for the jQuery function. It acts as a shortcut to select elements in the DOM and provides access to the library''s vast collection of methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c8de307-6645-47a0-b7f0-1cf5bb1bcadc', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the difference between a collection and a document in MongoDB?', N'Fresher', N'A document is the basic unit of data in MongoDB, similar to a row in a relational database, containing data in key-value pairs. A collection is a grouping of these documents, equivalent to a table in a relational database system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72aa0ba3-b994-41dc-9b32-1cf60c912d27', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP handle dynamic typing?', N'Junior', N'PHP is a dynamically typed language, meaning the type of a variable is determined at runtime based on the value it holds. You do not need to declare variable types explicitly, and a variable can change its type throughout the execution of a script.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10244695-76d4-4d38-b4f1-1cf74fddbaba', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R handle variable scoping?', N'Junior', N'R uses lexical scoping, which means the scope of a variable is determined by its physical location within the source code. When looking for a variable, R searches the current environment first and then moves up through the enclosing environments until it finds a match.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd974b12e-e725-49b2-b48b-1cf7db1a9ceb', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Describe the concept of a ''Dead Letter Queue'' and its role in reliability.', N'Senior', N'A dead letter queue is a destination for messages that cannot be processed successfully after a certain number of retries. It prevents system stalls by moving problematic messages aside for manual inspection or later reprocessing, ensuring the main pipeline continues to operate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ddd4e33-258b-47f3-b71e-1cf9e35b965c', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why is Express considered ''unopinionated''?', N'Fresher', N'Express is unopinionated because it does not enforce a specific structure, database, or toolset for your application. It leaves the decision-making process regarding project architecture and libraries entirely to the developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4cccc4e-31b1-47cd-b6ff-1d00d872dbb0', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How do indexes affect the performance of range scans?', N'Middle', N'Indexes are stored in a sorted B+ tree structure, which is highly efficient for range scans compared to a full table scan. The database can quickly find the starting point of the range and traverse the leaf nodes linearly until the end of the range is reached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53c73c38-945b-47b8-88db-1d00f0ff7de7', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the impact of ''noisy neighbor'' syndrome on system reliability in multi-tenant environments?', N'Senior', N'In multi-tenant systems, one tenant may consume disproportionate resources, causing latency for others. Mitigate this by implementing strict resource quotas, container orchestration limits, and enforcing fair-share scheduling algorithms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
