INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'476e82ca-7c37-4854-9303-1d1534487c23', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach estimating the ''unknown unknowns'' in a large-scale migration project?', N'Senior', N'I would implement a buffer based on historical velocity trends and prioritize high-risk architectural spikes early in the project timeline to uncover hidden technical hurdles. Continuous monitoring and frequent re-estimation after each phase allow for the absorption of volatility while keeping the overall project roadmap transparent and adaptable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
