INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34f0df6a-dd88-4273-a796-1d1d37db3a33', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the role of the urls.py file in a Django project?', N'Intern', N'In Django, the urls.py file plays a key role in routing and mapping URLs to views. Each app typically has its own urls.py for modular URL handling. Global URLs vs. App URLs - Global (project.urls): The project''s main urls.py generally includes paths to various apps. - Local (app.urls): Each app''s urls.py handles its specific URL mappings. URL Patterns Every urls.py file uses URL patterns, defined with path() or re_path(). - path(): For simple text-based URLs. - re_path(): For complex URLs using regular expressions. Passing URLs to Views The path() function''s view argument typically points to the corresponding view function. You can also send additional data, like query parameters or URL segments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
