INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8024ea1-6692-4ad7-88ea-1d28a30902a2', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Describe the challenges of implementing real-time features in a language designed for short-lived requests.', N'Senior', N'The primary challenge is the lack of a shared, persistent memory state between requests, which forces real-time applications to rely on external message brokers like Redis or RabbitMQ. Furthermore, the synchronous nature of standard PHP execution requires specialized event-driven runtimes to maintain long-lived connections without exhausting server process limits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'567849cb-defc-4681-826d-1d2abf08c8e5', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What does the UNIQUE constraint do?', N'Intern', N'The UNIQUE constraint ensures that all values in a column or a group of columns are different from one another. It prevents duplicate entries in the specified fields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd98e6639-08f7-4e1d-8e6a-1d340ed530d1', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why would you use a database view?', N'Junior', N'A view is a virtual table that presents a subset of data from one or more tables. It is used to simplify complex queries for users, provide a layer of security by hiding sensitive columns, or present data in a more readable format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35f9553c-476c-4d3a-87b5-1d34b9763f01', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does the ''working set'' size impact MongoDB server selection?', N'Middle', N'The working set is the portion of your data and indexes that is accessed most frequently. Ideally, the entire working set should fit into RAM; if it does not, the database will rely on disk I/O, leading to significant performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fad0cd11-508c-4a77-9bb1-1d34e20d68ab', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the purpose of Isolation in a database?', N'Intern', N'Isolation ensures that concurrent transactions do not interfere with each other. It makes it appear as if each transaction is executing in total isolation, preventing intermediate states of one transaction from being visible to others.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'037ed623-ded2-4669-9b0b-1d3560d2557d', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the role of the Write-Ahead Log (WAL) during a point-in-time recovery?', N'Middle', N'Point-in-time recovery uses a base backup and a sequence of archived WAL files to restore the database to a specific moment. By replaying the logs up to a desired timestamp, the database can reconstruct its state accurately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5976a6fe-4810-4e67-af66-1d3577333afa', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt handle caching strategies at the server level?', N'Senior', N'Nuxt leverages Nitro''s built-in cache storage, allowing developers to define custom caching logic for API responses or rendered pages using route rules. This significantly reduces database and API load by serving cached responses for recurring requests based on time-to-live or specific cache keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'359ad51a-98f1-4bd8-96bf-1d370f662a92', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a ''Write Skew'' anomaly?', N'Middle', N'Write skew is a phenomenon where two transactions read overlapping data sets but modify disjoint sets of data, resulting in a state that violates application-level business constraints. It typically occurs in snapshot isolation levels that do not employ predicate locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
