INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44a05c99-4b4a-445b-9672-1d3773d8d14d', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify''s routing system improve upon traditional regex-based routers?', N'Middle', N'Fastify uses a Radix Tree based router, which is significantly more efficient than iterating through an array of regular expressions for every request. This constant-time or logarithmic-time lookup ensures that routing performance remains stable as the number of defined endpoints grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
