INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5a9dadb-d4bd-4ecf-bd5f-1d3fca6be437', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is Cassandra called ''schema-optional''?', N'Fresher', N'Cassandra is described as schema-optional because it does not require a rigid structure for data at the time of creation. While you define a table structure, columns can be added or removed dynamically, and rows do not need to share the same columns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
