INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'240626d2-16b3-4846-acf4-1d502e99a638', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the purpose of the ''NoRoute'' handler in Echo?', N'Junior', N'The ''NoRoute'' or 404 handler is triggered when a client requests a URL path that does not match any registered routes. Echo allows you to define a custom handler for these cases to return a user-friendly JSON response instead of a plain text error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c15ec626-b3dc-49af-9c55-1d53981f241f', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo optimize routing lookups, and what are the implications for API performance?', N'Senior', N'Echo utilizes a radix tree (or prefix tree) for route matching, which provides O(k) lookup performance, where k is the length of the path. This is significantly faster than linear regex-based routing, ensuring that even systems with hundreds of endpoints maintain low latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fac1a288-37cc-44b7-9003-1d55322125ba', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain the interaction between Ruby''s ''Load Path'' ($LOAD_PATH) and constant lookup.', N'Senior', N'The load path determines where Ruby searches for files when ''require'' is called. Once loaded, constants are resolved based on the lexical nesting of the code, which is independent of the load path; understanding this separation is critical for avoiding namespace collisions and ''uninitialized constant'' errors in large codebases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1f0c93b-4d10-4999-8355-1d57691712b9', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi facilitate testing?', N'Fresher', N'Since Chi handlers are standard Go http.Handler functions, they can be tested easily using the standard library''s net/http/httptest package. This allows you to simulate requests and inspect responses without needing a running server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23712bd0-afa5-41f7-a15a-1d57efd59ba8', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s Copy-on-Write (COW) mechanism function internally for collection types?', N'Senior', N'Swift uses a reference-counting mechanism where the actual data buffer is shared between instances until a mutation is attempted. When a mutation occurs, the system checks the reference count; if it is greater than one, a unique copy of the buffer is created to ensure value semantics are preserved, optimizing memory usage and performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7404a7a3-336c-452f-acf6-1d59421648ac', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle JSON data?', N'Intern', N'Hono provides built-in methods to easily parse incoming JSON request bodies and serialize objects into JSON responses. This streamlines the process of communicating with APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8dbd9eab-2a81-4963-876f-1d5a05afab1e', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What are Axum extractors and why are they used?', N'Junior', N'Extractors are a mechanism in Axum to pull data out of an incoming HTTP request. They allow handlers to automatically parse parameters, headers, or JSON bodies into typed Rust structures, reducing boilerplate code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbbc0661-9066-45d3-89e5-1d605ad25c09', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is meant by type erasure in TypeScript?', N'Middle', N'Type erasure is the process where all TypeScript-specific syntax, such as interfaces and type annotations, is removed during the transpilation process. Because the generated output is plain JavaScript, these types do not exist at runtime and cannot be used for runtime checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e04744fa-91fe-4160-806a-1d6120f45b63', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the ''object'' keyword used for?', N'Junior', N'The ''object'' keyword is used to create a singleton instance of a class immediately upon definition. It is the standard way to implement the singleton pattern in Kotlin, ensuring only one instance of the object exists throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1fe4e32-c297-4c21-9fa4-1d6136bdd93c', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What are the advantages of Chi''s ''Chain'' utility for middleware management?', N'Senior', N'The Chain utility allows for the construction of a middleware pipeline that can be reused across multiple route groups. This reduces code duplication and ensures that the order of execution for logging, authentication, and validation is consistent across the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
