INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abe89ab2-09f1-4821-ba4f-1d63580b61f1', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are the trade-offs of using Kotlin''s ''Result'' type for error handling versus traditional exceptions?', N'Senior', N'Using the ''Result'' type forces callers to acknowledge and handle failure states explicitly, leading to more robust and predictable code paths compared to hidden exceptions. However, this approach can lead to deeper nesting and complex return types, potentially complicating the API surface if not managed with appropriate monadic abstractions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30a43178-d02b-4a67-9b88-1d652bd59bb1', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain ''Declaration Merging'' and the potential risks it introduces to an application.', N'Senior', N'Declaration merging allows multiple declarations with the same name to combine into a single definition, commonly used to extend global interfaces. While powerful, it can lead to confusion if multiple libraries modify the same interface, making it harder to track where a specific property definition originated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
