INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfcf4e26-95e5-4a0d-9223-1d66b723ae9e', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How do traits differ from abstract classes in PHP?', N'Middle', N'Traits are designed to reuse code across unrelated classes without the constraints of single inheritance. Unlike abstract classes, traits cannot be instantiated on their own and do not create a strict class hierarchy. They allow horizontal composition of behaviors, whereas abstract classes define a vertical template for child classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'386648a6-43da-4481-96a3-1d6a8150f8af', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Discuss the trade-offs of using ''Isolate.spawn'' versus sharing memory via low-level primitives.', N'Senior', N'Dart isolates are designed for strict memory isolation; there is no shared mutable memory, which forces developers to use message passing (typically via SendPort/ReceivePort). While this adds serialization overhead for large data structures, it guarantees memory safety and prevents data contention, which is a deliberate trade-off for scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'888f90b5-c0ac-461a-bb80-1d6e1912dd46', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is a Phoenix View and how does it relate to Templates?', N'Junior', N'The view module is responsible for preparing data for the template, acting as a data transformation layer. Templates contain the actual HTML structure, while the view provides functions to format and display that data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
