INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a76729c-319f-427d-abfe-1d733ef75d99', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does the Cassandra ''SSTable'' architecture impact write performance compared to traditional B-Tree databases?', N'Senior', N'Cassandra utilizes a Log-Structured Merge-tree architecture, which converts random writes into sequential disk I/O by appending updates to a memory buffer and flushing them to immutable SSTables. This eliminates the need for in-place updates and random seeks, resulting in significantly higher write throughput than B-Tree based systems that require frequent page rebalancing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a711af95-e2a7-46f1-9ec3-1d749ef02824', N'075b8862-431c-4678-9767-f55359758a4a', N'Why is it important to clean up side effects in a component?', N'Middle', N'Failing to clean up side effects like timers, event listeners, or network requests can lead to memory leaks and unexpected behavior. Always using lifecycle hooks or watchers to remove these references ensures the application remains stable and efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1256191-3481-4d26-a9d9-1d75107188c9', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala''s implicit resolution mechanism differ from C++ templates?', N'Senior', N'Scala''s implicit resolution is a search mechanism performed by the compiler based on scope and type, effectively acting as a form of ad-hoc polymorphism known as type classes. C++ templates use a compile-time instantiation model that generates specialized code for every type combination, leading to binary bloat. Scala''s approach favors modularity and separation of concerns while maintaining type safety through compile-time evidence passing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0913833-b169-4899-a9d1-1d78804abaf8', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is security considered a continuous process rather than a one-time task?', N'Intern', N'New vulnerabilities are discovered constantly, and systems change over time, meaning security must be regularly updated and monitored. Treating it as a continuous process ensures that defenses evolve to counter emerging threats.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18b3d998-c48d-4ef1-b1f7-1d7d1813ba95', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of the microtask queue in the event loop?', N'Middle', N'The microtask queue processes tasks with higher priority than the macrotask queue, such as promise resolutions and mutation observers. The event loop ensures all pending microtasks are cleared before moving on to the next macrotask, ensuring immediate follow-up actions are handled quickly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09b177dd-5d16-4d96-b436-1d7d6228930e', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP handle error reporting?', N'Fresher', N'In PHP, Error Handling can be configured using either .ini settings, programmatic functions, or a combination of both, offering developers great flexibility. Configuration Modes - Local (File-Specific): Adjusts settings for a specific PHP file using ini_set(). - Global: Modifies global PHP settings via php.ini or ini_set(). Enabling Error Reporting 1. Using Functions: error_reporting(E_ALL) enables all types of errors. To target specific error types, bitwise operators come in handy. 2. Using php.ini: Directly edit the php.ini file. Setting error_reporting to E_ALL enables comprehensive reporting. 3. Using ini_set(): For finer control, use ini_set(''error_reporting'', E_ALL) when you need to adjust settings on a per-file basis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da27faeb-b0f5-4341-b7c9-1d7dd17607bd', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are Hono ''Presets''?', N'Intern', N'Presets are pre-configured bundles of middleware and settings in Hono. They are designed to provide common functionality, such as security headers or logging, with minimal setup for the developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce1ef8cb-2be5-4f5c-9d2e-1d7e92c4d444', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How do you execute a PHP script from the command line?', N'Fresher', N'Executing a PHP script from the command line involves using the php CLI tool. Using the php Command To run a PHP script, use the following command: Arguments - Input: The -f option allows you to provide a file. - Output: Use -i to see the configuration, and -r to run a snippet without a script. - When Installed: --run is an alternative for Unix systems without a shebang line. - PHP Version: Use -v to check the installed PHP version. Examples - Running a File: - Displaying PHP Info: - Running a Single Command: Setting Up Environment Variables You can configure PHP-specific environment variables, allowing for script customization or convenience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
