INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47c4b488-8767-40d0-8076-1d82a44d4391', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle dependency injection, and why is it considered more efficient than frameworks like Spring?', N'Junior', N'Micronaut uses a pre-computed dependency injection system generated during the compilation phase, which eliminates the need for runtime reflection. In contrast, many traditional frameworks rely on runtime reflection to inspect classes and inject dependencies, which leads to higher memory overhead and slower startup speeds as the application grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbc20820-a04c-4cb6-b21f-1d8434c4b461', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the ''disconnectedCallback'' method used for?', N'Intern', N'This method runs when an element is removed from the DOM. It is primarily used for cleanup tasks, such as removing event listeners or canceling timers to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b33d979-e47a-4f34-8449-1d84e3236321', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle error management?', N'Intern', N'Hono allows developers to define custom error handling middleware to catch and process exceptions globally. This ensures that the server can return structured error responses instead of crashing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fdf0a80-056a-40c0-9a3a-1d85cea78b3c', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the benefit of using an H2 database during development?', N'Junior', N'H2 is an in-memory database that is very fast and requires no complex installation or configuration. It is perfect for integration testing and rapid development because it resets its state every time the application restarts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9329274a-722c-4208-8ef9-1d8785e65435', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is meant by the term ''Edge computing'' in relation to Hono?', N'Fresher', N'Edge computing refers to running code on servers geographically closer to the user to reduce latency. Hono is specifically engineered to be lightweight enough to start instantly in these distributed edge environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77f2dcbb-60f0-41e9-b270-1d8a72b0b18c', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the role of Rollup in a Vite project?', N'Intern', N'While Vite uses esbuild for development, it uses Rollup to bundle the application for production. Rollup is a highly efficient module bundler that performs optimizations like tree-shaking and minification to produce a small, performant build for the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a42202e-6e2f-4c7b-81df-1d8ce016b25d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you handle a scenario where two requirements directly conflict with one another?', N'Intern', N'I would first identify the project''s core objectives to see which requirement carries more weight or business value. Then, I would discuss the conflict with stakeholders to negotiate a compromise that minimizes negative impact on the overall system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3b01134-5477-4011-8dd1-1d912f6eef5e', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What criteria do you use to determine if a service should be broken down further into smaller microservices?', N'Senior', N'I evaluate the service based on its bounded context, team ownership, and deployment frequency. If a service has grown too large to manage effectively, has mixed responsibilities, or becomes a bottleneck for team velocity, it is a prime candidate for decomposition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4310f904-1413-40b1-9a36-1d91fbbe7280', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Does Tailwind CSS support Dark Mode, and if so, how?', N'Junior', N'Yes, Tailwind supports dark mode using a dark: variant modifier. You can configure it to toggle based on a class on the root element or by following the user''s system-level OS preferences.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e157ea2-a1da-49ad-a5ba-1d929f0cc85c', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does the Symfony Service Container implement Dependency Injection, and what is the benefit of using autowiring versus manual configuration?', N'Senior', N'The Service Container manages object lifecycle and dependencies by injecting them via constructors or setters. Autowiring uses reflection to automatically resolve dependencies based on type-hints, reducing maintenance overhead, while manual configuration provides explicit control for complex scenarios or interface implementations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f5aec79-b58c-47de-af8c-1d9550876f85', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is middleware in Chi?', N'Intern', N'Middleware in Chi is a function that sits between an incoming HTTP request and the final handler. It can inspect, modify, or terminate the request before it reaches the handler, or perform actions after the handler has finished.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2aff10d4-a8ed-4196-9f19-1d987f4e561f', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL decide between a sequential scan and an index scan?', N'Middle', N'The optimizer estimates the cost of both approaches based on table statistics. If a query is expected to return a large percentage of the table, a sequential scan is usually chosen because it reads data in large, efficient sequential blocks; an index scan is preferred when the expected output is a small fraction of the total data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b69aedb7-6def-41a2-830f-1d988fc21d38', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do Svelte stores manage memory and subscription lifecycles?', N'Senior', N'Svelte stores use an observer pattern where components can subscribe to state changes. The framework provides an auto-subscription syntax that automatically handles unsubscription when a component is destroyed, preventing memory leaks that often occur with manual subscription management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcd2f5c9-9649-4535-bdab-1d99007d0444', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is Force Unwrapping?', N'Fresher', N'Force unwrapping is the act of accessing the value inside an optional using an exclamation mark. It is dangerous because if the optional is nil, the program will crash immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7050bd4a-e868-40c0-aa39-1d9df9a7ae87', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Why is it important to monitor the ''page fault'' rate in MongoDB?', N'Middle', N'High page fault rates indicate that the working set of data does not fit in RAM, forcing the engine to frequently fetch data from disk. This creates a significant performance bottleneck and suggests that the instance may require more memory or better index optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92308fe2-2930-460b-a3b1-1da03e10b218', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Why is it important to design APIs to be stateless?', N'Middle', N'Stateless APIs do not store client context on the server between requests, which allows any server instance to handle any request. This makes the system easily scalable, as traffic can be distributed across a pool of servers without needing to synchronize session state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6fcdede-59e7-4a3f-a5a1-1da197779937', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the difference between a trait and an abstract class?', N'Middle', N'A trait defines behavior that a type can implement, focusing on what a type can do rather than what it is. Unlike abstract classes, traits do not support data fields or single-inheritance hierarchies, which prevents complex state-sharing issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
