INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02742e7e-63b2-4424-8b53-1da4b1c729c4', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain the concept of ''Defense in Depth'' in the context of a web application.', N'Middle', N'Defense in depth is an architectural strategy that uses multiple layers of security controls to protect data. If one security mechanism fails, others are in place to prevent an exploit, such as combining input validation, TLS encryption, firewalls, and least-privilege access controls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14c27f91-1c78-463d-b038-1da942efa81d', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the purpose of the ''chi.NotFound'' handler?', N'Junior', N'The NotFound handler is a custom function that Chi invokes when no defined route matches the incoming request path. You can override the default behavior to return a custom JSON error or a branded 404 page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
