INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f67a9d3b-d360-4acb-9232-1daa0e04b133', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you ensure your design is scalable before writing any code?', N'Fresher', N'I ensure scalability by keeping components independent and avoiding single points of failure. Designing with a ''stateless'' approach where possible allows the system to handle increased loads by adding more instances of the service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd56ace9-7c4d-4c2b-8ff3-1daafcfb7f81', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your approach to handling cascading failures in a microservices environment?', N'Senior', N'I implement patterns like circuit breakers, bulkhead isolation, and rate limiting to contain faults. By decoupling services through asynchronous messaging or graceful degradation strategies, I ensure that one failing component does not exhaust the resources or connection pools of upstream callers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e8300cf-6f0d-47f3-82ee-1dab7be6d86a', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'In what way does Chi’s middleware support the decorator pattern for cross-cutting concerns?', N'Senior', N'Chi’s middleware acts as a decorator for the standard http.Handler, allowing for the transparent wrapping of request processing. This enables senior engineers to implement cross-cutting concerns like logging, telemetry, and recovery in a declarative manner without polluting business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
