INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59edce0e-0631-4487-8906-1dad1b33b07e', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What Are The Types of Objects Support in Python Language?', N'Intern', N'Python supports are two types are of objects. They are: Immutable built-in types: Strings Tuples Numbers Mutable built-in types: List Sets Dictionaries - Immutable Objects The objects which doesn''t allow to modify the contents of those objects are known as ''Immutable Objects'' Before creating immutable objects with some content python interpreter verifies is already any object is available. In memory location with same content or not. If already object is not available then python interpreter creates new objects with that content and store that object address two reference variable. If already object is present in memory location with the same content creating new objects already existing object address will be given to the reference variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d7c0166-d5cb-49c4-9ac0-1dae518f72d0', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between SQL and MySQL?', N'Intern', N'SQL is the standard language used to communicate with and manage relational databases. MySQL is a specific software product, or RDBMS, that implements the SQL language to store and retrieve data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de9036c9-74b8-4287-8286-1db0f23a89f5', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'You need to choose between a relational database and a NoSQL database for a new application. How would you approach this decision?', N'Junior', N'I would evaluate the data structure and consistency requirements of the application. If the data is highly structured and requires complex transactions with strict consistency, a relational database is safer. If the data is unstructured, requires high write throughput, or needs to scale horizontally across many servers, I would consider a NoSQL database while acknowledging the trade-off of weaker consistency guarantees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baba99f8-e602-4ff9-9d77-1db258452287', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is Flask-Migrate used for?', N'Junior', N'Flask-Migrate is an extension that handles SQLAlchemy database migrations. It tracks changes to the database schema over time and allows developers to apply or roll back those changes systematically as the application evolves.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2df05177-c5bb-44c2-9361-1db2f70e151f', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of the Routing component?', N'Junior', N'The Routing component maps incoming HTTP request URLs to specific Controller actions. It parses the URL based on defined patterns and determines which method should be executed to handle the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b593289d-9730-442d-9ea7-1db63eb4f895', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach debugging a distributed deadlock in a system using a message queue?', N'Senior', N'I would visualize the message flow to identify cycles where services are waiting for each other to process specific event types. I would then inspect the consumer group offsets and dead-letter queues to determine if stuck messages are blocking the pipeline, indicating a need for better timeout management or consumer concurrency adjustments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c1fcc56-503a-4cd6-b140-1db8300bc9d0', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a situation where an error occurs sporadically?', N'Intern', N'For sporadic errors, you should increase logging granularity and monitor the system closely to capture the state during a failure. Look for correlations with system load, time of day, or specific user actions to identify the trigger.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57d32ccd-13fc-41c0-a04e-1db9020c9965', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What role does the Write-Ahead Log (WAL) play in ensuring the Durability property of ACID?', N'Senior', N'WAL ensures that all modifications are appended to a persistent log on non-volatile storage before they are applied to the actual data files. In the event of a system crash, the database can replay the log to reconstruct the state of committed transactions, ensuring that no data is lost even if the main data pages were not yet flushed to disk.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f246c6b0-16db-48c8-853c-1dbcebb9363a', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What are the trade-offs of using a ''Global Load Balancer'' vs. a ''Regional Load Balancer''?', N'Senior', N'A global load balancer routes traffic to the nearest geographic region to minimize latency, but it requires sophisticated health checks and cross-region state awareness. Regional load balancers are simpler to manage but force users to traverse longer network paths if the origin is distant from their region.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83615fc1-b633-424e-a6ce-1dbeada5e9ac', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the role of the ''import'' mechanism and the sys.modules cache in Python''s module resolution.', N'Senior', N'When a module is imported, Python first checks sys.modules to see if it has already been loaded, providing an O(1) lookup. If not found, it searches through sys.path to locate the file, compiles it to bytecode if necessary, and executes it. Understanding this process is key to debugging circular dependencies and managing complex dependency trees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e27e51fa-41ee-46ef-8cb5-1dbfe424a1b9', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is tree-shaking in the context of a Vite build?', N'Intern', N'Tree-shaking is a process where the bundler removes unused code from your final production build. By analyzing the dependency graph, Vite identifies and excludes modules that are imported but never actually utilized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'631e3d9d-28b0-42f0-801e-1dc08e01bf49', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript''s ''lib'' configuration affect project development?', N'Middle', N'The ''lib'' option specifies which built-in type definitions for the JavaScript environment are included in the compilation. This allows developers to target specific environments, such as modern browsers or Node.js, ensuring that the compiler recognizes the global APIs available in those target environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b87ad345-abdc-4af5-ba85-1dc18f918cfa', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a primary shard?', N'Fresher', N'A primary shard is the main shard where data is first indexed. Every document is assigned to a specific primary shard, which is then responsible for indexing the document across all its replicas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d647dbe-4c4e-47db-a4cb-1dc26df32d5d', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between shallow copy and deep copy in the context of C# object cloning?', N'Senior', N'A shallow copy duplicates the object''s reference fields, meaning both copies point to the same underlying objects. A deep copy recursively duplicates all referenced objects, ensuring total independence between the source and the target.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6bc0321-587c-4791-b30f-1dc37fdc1d31', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do SvelteKit''s ''page options'' like ''ssr'', ''csr'', and ''prerender'' provide control over rendering strategies?', N'Senior', N'These options allow developers to toggle rendering behavior on a per-route basis, enabling a fine-tuned balance between performance and dynamic requirements. For example, disabling CSR for marketing pages boosts performance, while keeping it enabled for dashboards allows for interactive, state-heavy interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b47ad136-5e2e-4e7e-a476-1dc4163409f8', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What are the risks of ''distributed monoliths'' in terms of observability?', N'Senior', N'Distributed monoliths couple services tightly, making it impossible to scale or deploy them independently. Observability becomes difficult because a change in one service can cause unpredictable side effects in others, masking the true root cause of failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
