INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bbbbb55-b168-41dc-9523-1dcb9fa03962', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between a DDL and a DML?', N'Intern', N'DDL stands for Data Definition Language and is used to define or change the structure of database objects like tables. DML stands for Data Manipulation Language and is used to manage and modify the actual data stored within those tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
