INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd4e55b7-d41b-44d9-a1a8-1dd613b18b28', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What does ''serialization'' mean in Fastify?', N'Intern', N'Serialization is the process of converting JavaScript objects into a string format, such as JSON, to be sent in the HTTP response. Fastify uses high-performance libraries to serialize data, which significantly improves throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b19b9e40-feda-46c5-93a3-1dd863ed3bfa', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is ''Data Skew'' and why is it problematic in map-reduce or distributed query execution?', N'Senior', N'Data skew occurs when one node processes significantly more data than others, becoming a bottleneck that prevents parallel efficiency. It forces the entire job to wait for the overloaded node, negating the scalability benefits of a distributed architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
