INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbfc889d-908a-4ecc-8cb9-1ddfba1a2ee7', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How do Go''s map internals handle concurrency?', N'Senior', N'Go maps are not thread-safe by design; concurrent read and write access will cause a fatal runtime panic. Developers must protect maps with a sync.Mutex or sync.RWMutex to ensure consistency when shared across multiple goroutines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
