INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c4d2476-dddc-4a23-a7ec-1de6c2e2e19f', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What are the limitations of Qwik in high-frequency update scenarios?', N'Senior', N'While Qwik is efficient for typical web interactions, high-frequency updates—like real-time canvas rendering or complex animations—may face overhead due to the constant lookups and serialization required for every state change. Developers in these scenarios may need to bypass the framework''s reactive system for specific hot paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3063708-e495-4caf-8547-1de6db5dc365', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle form data?', N'Intern', N'Gin provides methods to parse and retrieve data sent in HTTP POST requests as form-encoded data. This is typically used for submitting HTML forms or simple key-value payloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc9aaeff-2d21-4ec9-ad22-1de70a031c0c', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix handle long-running processes without blocking the request-response cycle?', N'Middle', N'Phoenix offloads long-running tasks to separate processes or background workers. By decoupling heavy computation from the request process, the web server remains responsive to new incoming traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
