INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8aa005f0-8755-43ab-a8c2-1deb44ac56c6', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of a Filter in ASP.NET Core MVC/API?', N'Middle', N'Filters allow you to run code before or after specific stages in the request processing pipeline, such as before an action executes or after an exception occurs. They are useful for cross-cutting concerns like authorization, model validation, and exception handling without cluttering action methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
