INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3656fd63-fa23-413d-aa60-1ded46bf0da8', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a channel and why is it used?', N'Junior', N'A channel is a communication pipe that allows goroutines to send and receive values. It is the primary mechanism for synchronizing execution and passing data safely between concurrent processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2de846d-6611-4f7d-99cf-1df57e38d967', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the difference between Optimistic and Pessimistic concurrency control and when to prefer each.', N'Senior', N'Pessimistic concurrency uses locks to prevent conflicts before they happen, making it suitable for high-contention environments where rollbacks are costly. Optimistic concurrency assumes conflicts are rare, using versioning or timestamps to validate data only at commit time, which improves throughput in read-heavy systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fa2009f-ba62-4f2a-8c7d-1df6ccaecb7d', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the benefit of render functions over templates?', N'Intern', N'In VueJS, the templates are very powerful and recommended to build HTML as part of your application. However, some of the special cases like dynamic component creation based on input or slot value can be achieved through render functions. Also, these functions gives the full programmatic power of javascript eco system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
