INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'966be0e0-97d1-4e24-adc7-1e015e7dc174', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Explain the trade-offs between ''universal rendering'' (SSR + Hydration) and ''Client-Side Rendering'' (CSR) in a complex enterprise application.', N'Senior', N'Universal rendering provides superior initial load performance and SEO by delivering pre-rendered HTML, but it introduces complexity regarding hydration mismatches and increased server resource consumption. CSR simplifies the infrastructure but often suffers from poor Core Web Vitals, specifically Largest Contentful Paint and Cumulative Layout Shift, if not managed with sophisticated code splitting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
