INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e1e7b8e-3aae-4b12-971f-1e1c6bd22eef', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are the advantages of using Hono’s built-in validator over external libraries like Zod or Joi?', N'Middle', N'Hono’s validator is lightweight and designed to work natively with the Hono Context object, enabling seamless integration with type inference. While external libraries offer more complex schema features, Hono’s validator is optimized for minimal bundle size and runtime performance at the edge.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ad78ab2-1360-4675-98e6-1e1e89bd1c5d', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Why is observability critical in a microservices architecture?', N'Middle', N'Observability through distributed tracing, logging, and metrics is essential because requests traverse multiple network boundaries. Without these tools, identifying the root cause of a failure or performance bottleneck in a distributed system is nearly impossible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c172c36-d667-40f2-a2a9-1e1f6d01ee5e', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are some alternative implementations to CPython? When and why might you use them?', N'Intern', N'One of the more prominent alternative implementations is Jython, a Python implementation written in Java that utilizes the Java Virtual Machine (JVM). While CPython produces bytecode to run on the CPython VM, Jython produces Java bytecode to run on the JVM. Another is IronPython, written in Cand targeting the .NET stack. IronPython runs on Microsoft''s Common Language Runtime (CLR). As also pointed out in Why Are There So Many Pythons?, it is entirely possible to survive without ever touching a non-CPython implementation of Python, but there are advantages to be had from switching, most of which are dependent on your technology stack. Another noteworthy alternative implementation is PyPy whose key features include: - Speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae421ba1-da20-4e51-bf2e-1e205b9c8832', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the primary difference between Svelte and traditional frameworks like React regarding how they handle the DOM?', N'Junior', N'Svelte is a compiler that converts your code into highly optimized vanilla JavaScript during the build process, rather than using a virtual DOM. This means the browser does not need to perform complex diffing at runtime, resulting in faster updates and smaller bundle sizes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7eb1870-4753-4c8a-9ce0-1e20a964d7ce', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the trade-offs of using ''namespace'' versus ES modules in modern TypeScript?', N'Senior', N'Namespaces are a legacy feature for grouping code under a single global object, whereas ES modules are the standard for managing dependencies and scoping. Modern TypeScript development should prioritize ES modules for better tree-shaking, maintainability, and compatibility with bundlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79ba74ab-65fd-4cc8-90be-1e2163eeffaf', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the significance of the ''$'' operator in R?', N'Intern', N'The $ operator is used to extract or replace a specific element from a list or a column from a data frame by its name. It provides a convenient way to access data components without needing to know their numeric index.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eaaceb8b-8b53-46a3-bb63-1e24369528b7', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What does it mean for a function to be ''pure'' in R?', N'Middle', N'A pure function is one that always returns the same output for the same input and has no side effects, such as modifying global variables or printing to the console. Pure functions are easier to reason about, test, and parallelize, making them highly desirable in robust software design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e652b0a-21f0-44b8-81a4-1e29b346b506', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Can Hono be used with TypeScript?', N'Junior', N'Yes, Hono is built with TypeScript in mind and offers excellent type support for request inputs, path parameters, and environment variables. This enhances developer productivity by providing autocompletion and catching type-related errors during development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fb11cab-da8b-4c09-a4b2-1e2a85aab794', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Describe the function of the C preprocessor in the context of the translation unit.', N'Senior', N'The preprocessor performs lexical analysis on source files to handle macro substitution, file inclusion, and conditional compilation before the actual compilation phase. It transforms the source into a single translation unit, which is the basic unit of compilation that the compiler frontend processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69bf2648-8da6-4b82-aa83-1e2b46403576', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix''s actor model reconcile the constraints of Rust''s ownership system with the need for shared state across asynchronous tasks?', N'Senior', N'Actix utilizes a combination of message passing and internal reference counting to manage state safely. Each actor owns its private state, ensuring that mutations only occur within a single-threaded execution context per actor, which eliminates the need for complex locks while maintaining memory safety guarantees required by the borrow checker.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4af0040-45fe-4d14-bc2d-1e2ba3d0bc5d', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of the ''Edge'' template engine?', N'Fresher', N'Edge is the default template engine for AdonisJS used to render server-side HTML. It allows developers to inject dynamic data into HTML templates and provides features like partials, components, and logic structures like loops and conditionals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff0c78b3-0509-45d7-92cc-1e2d53ae653b', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Why is it important to use ''functions'' for unit conversion in Sass?', N'Senior', N'Hardcoding unit conversions, such as pixels to rems, can lead to maintenance challenges if the base font size changes. Using a dedicated Sass function ensures that all conversions are calculated consistently from a single source of truth, making the codebase easier to update and less prone to arithmetic errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c2e4605-49c6-451c-b1ed-1e2d9502634d', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the function of the ''IActionResult'' return type?', N'Fresher', N'IActionResult is an interface that allows an action method to return various types of HTTP responses, such as a status code, a file, a redirect, or serialized JSON data. It provides flexibility by allowing the method to return different responses based on the outcome of the logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c1fa330-fab5-4c8f-91df-1e2f918c21d2', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the purpose of the ''ShouldBind'' method family?', N'Junior', N'The ShouldBind family of methods allows for flexible data parsing from various sources like JSON, XML, or form-data based on the request''s Content-Type. Unlike the standard Bind method, these return an error instead of aborting the request, allowing you to handle validation failures manually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d28689f-4875-4545-a4b3-1e31b11c86f0', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is Nuxt and why is it used?', N'Fresher', N'Nuxt is an open-source framework built on top of Vue.js designed to make web development intuitive and powerful. It is used to simplify the creation of universal or single-page applications by providing built-in features like server-side rendering, static site generation, and automatic routing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9c1fcf8-3ca6-41e0-835a-1e33b087f109', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the purpose of jitter in retry policies?', N'Middle', N'Jitter adds a random delay to retry attempts to prevent the ''thundering herd'' problem. If multiple instances fail at once, jitter ensures they do not all retry at the exact same moment, which would overwhelm the recovering service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb3bb6ec-2688-4059-a386-1e34e8662d9d', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Why is it generally better to use transform and opacity for animations instead of top, left, or width?', N'Middle', N'Transform and opacity properties are handled by the browser''s compositor thread, which can animate elements using the GPU without triggering layout or paint cycles. Animating properties like top or width forces the browser to perform reflow and repaint on the main thread for every frame. Using compositor-only properties ensures smooth 60fps performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41816623-515d-45eb-96a0-1e39770b4aa0', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is it important to keep utility classes in HTML instead of writing custom CSS?', N'Intern', N'Keeping styles in HTML makes the UI more maintainable by eliminating the need to toggle between files to understand how an element is styled. It also prevents the common problem of ''dead CSS,'' where removing HTML elements leaves behind unused styles in a separate file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85f9e725-8e55-48bc-b219-1e3ac84ffe75', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What are the trade-offs of using Cache-Aside versus Read-Through patterns in a high-concurrency microservices environment?', N'Senior', N'Cache-Aside gives the application full control over cache logic but requires duplicate boilerplate code across services and is susceptible to stale data if not handled correctly. Read-Through offloads the cache management to the provider, simplifying application code, but couples the application logic to the specific caching library or provider.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c1165a9-dad7-423c-bcc8-1e3b685a7670', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of a junction table in database design?', N'Junior', N'A junction table is used to implement a many-to-many relationship between two other tables. It contains foreign keys pointing to the primary keys of the two tables it links, effectively breaking the many-to-many relationship into two one-to-many relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb79be1f-53c2-410e-8770-1e3c191769f7', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you prepare for a code review?', N'Junior', N'I review my own code to ensure it meets the team''s standards and that all changes are intentional. I also prepare a brief summary of the changes to explain the ''why'' behind the logic, making it easier for the reviewer to understand my approach.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8cbf021-6e3a-498b-90da-1e3e8fecd1ee', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you decide between using a relational database versus a NoSQL database for a new microservice?', N'Middle', N'I evaluate the data consistency requirements and the schema structure. If the data has strict transactional needs and defined relationships, a relational database is preferred for ACID compliance, whereas NoSQL is better suited for rapidly evolving schemas, horizontal scalability, and high-velocity unstructured data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
