INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f545f771-13fe-4ea6-b7b9-1e44c7a97aa9', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a CommitLog?', N'Intern', N'The CommitLog is a crash-recovery mechanism that records every write operation to a file on disk. If a node fails, it uses the CommitLog to replay operations and recover data that was not yet flushed from the Memtable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a8ed077-2d86-41c0-82df-1e465d715fe5', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the ''dynamic'' keyword?', N'Middle', N'The dynamic keyword tells the compiler to bypass static type checking and resolve operations at runtime. While it provides flexibility for interoperability with dynamic languages or COM objects, it lacks compile-time safety and can introduce runtime errors that are harder to debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
