INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c175fc2d-2f08-4055-bc24-1e4bc36cc9b4', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the significance of the document ready event?', N'Intern', N'The document ready event ensures that your jQuery code only runs once the DOM hierarchy has been fully loaded. This prevents errors that occur when trying to interact with elements that do not yet exist in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e6adf90-f5fc-4b5f-b3a8-1e4c80bf2adb', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux know when to re-render a component?', N'Junior', N'When the state in the Redux store is updated via a new object reference, the useSelector hook detects the change. If the returned value from the selector changes, the component is triggered to re-render with the new data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72e902c0-5bd2-4efc-abfb-1e501f7f8656', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the ''Observer Effect'' in the context of observability?', N'Senior', N'The observer effect occurs when the act of monitoring or logging consumes significant system resources, effectively altering the system''s performance. Excessive instrumentation can introduce latency, potentially causing the very issues engineers are trying to diagnose.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98d45af6-8dce-4360-8dec-1e5081ea3e0f', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach the estimation of resources needed for a data-intensive background processing job?', N'Senior', N'I calculate the volume of data to be processed and the complexity of the transformation logic. By running a representative pilot on a scaled-down dataset, I extrapolate the compute and memory requirements while accounting for I/O wait times and parallelization efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'557cb856-eb8d-4440-9a9a-1e516f95037b', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between a constructor and a destructor?', N'Intern', N'A constructor is a special member function that is automatically called when an object is created to initialize it. A destructor is called automatically when an object goes out of scope to perform cleanup tasks like freeing allocated memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bd05ad9-7824-47ea-b86f-1e528d4d6d29', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What does ''unidirectional data flow'' mean in Redux?', N'Junior', N'Unidirectional data flow means that data in an application follows a strict, one-way path: an action is dispatched, the reducer processes it, the state is updated, and the UI re-renders. This cycle makes it easy to understand how data moves through the app.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
