INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4891b041-a053-47ab-ac82-1e704cb94655', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does the ''asyncio'' event loop handle concurrency, and what are the limitations compared to true multi-threading?', N'Senior', N'The asyncio event loop uses cooperative multitasking, where tasks yield control back to the loop at await points. Unlike multi-threading, which is preemptive and managed by the OS, asyncio is strictly single-threaded and relies on non-blocking I/O. It is highly efficient for I/O-bound applications but provides no benefit for CPU-bound tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
