INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1ade531-c9ef-4e91-9dad-1e859df02ee4', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How would you handle horizontal scaling of a Laravel application that relies heavily on local file storage and session state?', N'Senior', N'To scale horizontally, you must externalize state by moving session storage to a distributed store like Redis and file storage to an object-store service like S3. This ensures the application remains stateless, allowing any worker node to handle any request without reliance on local disk persistence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d64201f-09f3-4be6-92ac-1e88413509e2', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why is deadlocking a concern in high-concurrency transaction environments?', N'Middle', N'Deadlocks occur when two or more transactions hold locks on resources the other needs, resulting in a circular dependency that stops progress. Databases must implement deadlock detection algorithms to kill one of the transactions to allow others to continue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee449c56-9207-4853-a164-1e8af675f100', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the role of the ''load'' path ($LOAD_PATH) in Ruby''s architecture for library resolution?', N'Senior', N'The $LOAD_PATH is an ordered array of directories that the Ruby interpreter searches when requiring files. Architecturally, this provides a flexible way to manage dependencies and versioning, but it can lead to ''dependency hell'' if multiple versions of a library are present or if the load order is incorrectly configured.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66a19797-4d27-4137-b70f-1e8de9e55f21', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why is JavaScript''s single-threaded event loop a strategic choice for I/O bound applications?', N'Senior', N'The single-threaded model eliminates the need for complex locking mechanisms and race condition mitigation in user code. By delegating I/O operations to the underlying operating system and using non-blocking callbacks, the engine achieves high concurrency with low memory footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f210d5c1-c60d-4ec0-a140-1e8f6a38f53e', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Explain the trade-off in choosing between a monolithic and a modular design.', N'Fresher', N'A monolith is often easier to deploy and test initially, but it can become difficult to maintain as it grows. A modular design is easier to maintain and scale in parts, but it requires more effort to manage dependencies and communication between modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
