INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06629642-8e5b-416c-9bca-1e95f5afe03d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why is there a trade-off between software development speed and long-term maintainability?', N'Junior', N'Prioritizing speed often involves taking technical shortcuts or skipping documentation to meet immediate deadlines. While this delivers features quickly, it creates technical debt that makes future updates and bug fixes more difficult and time-consuming.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'445b881c-39d1-45c6-b294-1e9bc3c14db7', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a node in Elasticsearch?', N'Intern', N'A node is a single running instance of Elasticsearch that stores data and participates in the cluster''s indexing and search capabilities. Multiple nodes together form a cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2477cf2-f63c-4b52-b82f-1e9c87e569d5', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the significance of the Request object in Litestar?', N'Intern', N'The Request object represents the HTTP request sent by the client. It provides access to headers, query parameters, request bodies, and other metadata necessary for the server to process the client''s intent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'285800fc-8f3c-4f61-8009-1e9d1cac14cc', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar approach API documentation?', N'Junior', N'Litestar has built-in support for generating OpenAPI specifications automatically based on your route handlers and type annotations. It provides built-in UI components like Swagger UI or Redoc to visualize and test the API directly from the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce2e5a57-871c-48f5-9ddf-1e9e220538f8', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the architectural significance of the ''strictFunctionTypes'' flag in ensuring sound function variance?', N'Senior', N'This flag enforces correct contravariance for function parameters, preventing the common but unsound practice of assigning a function with a more specific parameter type to a variable expecting a broader one. It is essential for maintaining strict type integrity, though it may require refactoring legacy code that relied on the previous, less sound behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b0abe1c-fdb2-4b3b-8bc7-1e9fdfc7b5c7', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the benefit of using ''guard'' instead of ''if'' for early exits?', N'Middle', N'The guard statement improves readability by keeping the ''happy path'' of execution at the lowest level of indentation. It also requires an early exit, ensuring that necessary conditions are met before proceeding with the rest of the function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7936916-3a37-41b2-9db0-1ea29ae141df', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind manage file size in production?', N'Intern', N'Tailwind uses a tool called PurgeCSS that scans your HTML and template files for class names. It automatically removes any unused CSS from the final build, resulting in a very small production file size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89678096-45f8-462c-892f-1ea46af4de57', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between ''let'' and ''var'' inside a struct?', N'Intern', N'In a struct, ''let'' defines a constant property that cannot be changed after the struct is initialized. ''var'' defines a mutable property that can be changed, provided the instance of the struct itself is also declared as a variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'608019b2-2e62-4a0e-85e7-1ea5c57e9a1c', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte manage props and reactivity across component boundaries?', N'Senior', N'Svelte uses a prop-passing mechanism where data flows downward, and the compiler automatically updates child components when props change. This creates a predictable data flow while maintaining high performance because the compiler generates localized update code rather than a global re-render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4edb2b8-9e8c-4a68-9807-1ea9e3f3270f', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the JIT compiler handle deoptimization when speculative assumptions fail?', N'Senior', N'The JIT compiler makes assumptions based on profiling data, such as a branch always being taken or a class never being subclassed. If these assumptions are invalidated at runtime, the JVM performs ''deoptimization'' by discarding the optimized machine code and falling back to the interpreter to safely re-execute the method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c2cf7c8-4a48-4e70-9e82-1eab47ae0e83', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does the Durability property guarantee?', N'Junior', N'Durability guarantees that once a transaction has been committed, it will remain permanent even in the event of a system crash or power failure. This is typically achieved by logging changes to non-volatile storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7082ee40-7591-4206-90f2-1eb182482acc', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP''s opcode caching interact with deployment pipelines?', N'Senior', N'Opcode caches must be explicitly invalidated or cleared upon code deployment to prevent the engine from executing stale bytecode. Failing to handle this cache invalidation leads to inconsistency between the deployed source code and the executing machine instructions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'633313de-978b-45b5-a495-1eb310d14de8', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain the significance of ''ControlValueAccessor'' when building custom form components.', N'Senior', N'ControlValueAccessor acts as the bridge between the Angular Forms API and custom UI components, allowing them to participate in reactive or template-driven forms. It ensures that custom components behave like native form inputs, supporting features like validation, dirty/pristine states, and programmatic value updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54ac9311-be05-4398-b545-1eb9052713ca', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you determine if a feature should be implemented as a separate service or as part of an existing one?', N'Middle', N'I look at the team boundaries, the lifecycle of the feature, and whether it has distinct scaling requirements. If the feature changes frequently and independently, it is a candidate for a new service; if it is tightly coupled with existing domain logic, it should stay within the current service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9a7c88c-459f-4a88-9013-1ebaca355201', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are the advantages of using MediatR in an ASP.NET Core application?', N'Middle', N'MediatR implements the Mediator pattern to decouple request sending from request handling. It promotes the Single Responsibility Principle by separating logic into individual handlers, making the codebase easier to maintain, test, and extend.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
