INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f0b8316-5185-4c27-9e62-1ebd172bd5d1', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the principle of least privilege, and how can you implement it in a cloud-based infrastructure?', N'Middle', N'The principle of least privilege dictates that every module or user must be able to access only the information and resources necessary for its legitimate purpose. In cloud environments, this is implemented by using granular Identity and Access Management (IAM) roles rather than broad administrative permissions for service accounts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be3a58b7-680d-4c2e-b42e-1ebe29f81446', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the benefit of resumability for SEO?', N'Intern', N'Because Qwik renders fully functional HTML on the server, search engines can easily index the content without needing to execute complex JavaScript. This results in better performance and higher search rankings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e365b22d-d7d3-4182-8ef4-1ec14bbfbf4c', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the ''Soft state'' in the BASE model?', N'Intern', N'Soft state refers to the condition where the state of the system may change over time, even without new input. This occurs because of the eventual consistency model, where updates are propagating through the system nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df90e677-de3a-414b-b517-1ec308c421e1', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why is transaction isolation important?', N'Fresher', N'Isolation is important because it prevents data corruption and inconsistencies when multiple users or processes access the database simultaneously. It manages the trade-off between data accuracy and system performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
