INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ba3b971-8fd8-4c50-a523-1ec7a0b073c0', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain different types of compilation Angular provides and why is the need for it.', N'Fresher', N'Angular needs to compile your application''s code, which includes TypeScript and HTML templates, into efficient JavaScript that browsers can understand and execute. There are two main types of compilation: - Just-in-Time (JIT) compilation: This happens in the browser at runtime. The Angular compiler is included in the application bundle, and it compiles the application code just before it runs. This is typically used during development (ng serve) because it allows for faster rebuilds. - Ahead-of-Time (AOT) compilation: This happens during the build process, before the browser loads the application. The Angular compiler runs on your machine, converting your templates and components into highly optimized JavaScript. The browser then downloads and runs the pre-compiled code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd72eb95-d727-4247-b1fe-1ecaf6772e83', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why might a team intentionally choose a less readable code structure for better performance?', N'Fresher', N'This is a trade-off between maintainability and execution speed. If the application has strict latency requirements, developers may prioritize low-level optimizations, accepting that the code will be harder for future engineers to understand and modify.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'856efc0a-3ba5-44e9-bb9e-1ecc6dda1ed6', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the ''try-with-resources'' statement improve resource management?', N'Middle', N'The try-with-resources statement ensures that each resource, such as a file or socket, is automatically closed at the end of the block, regardless of whether an exception occurs. This eliminates the need for complex, error-prone finally blocks and prevents resource leaks. It requires that the resource implements the AutoCloseable interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e326c27-ac8b-4449-b1fc-1ecd1d4355e8', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'When is it appropriate to use an ''Astro'' endpoint?', N'Middle', N'Endpoints are used to handle API requests, such as generating RSS feeds, sitemaps, or handling form submissions in SSR mode. They allow you to define server-side logic that returns JSON, XML, or other non-HTML formats.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f41ab15-e042-4339-8a90-1ecd225e0b41', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the ''fastify-plugin'' utility?', N'Intern', N'The fastify-plugin utility is a helper that marks a plugin as ''shared.'' This prevents the plugin from creating a new encapsulation scope, allowing it to share decorators and hooks with the parent application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8358275e-55e9-4181-abe2-1ecf16813b61', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are namespaces and why are they considered less relevant in modern TypeScript?', N'Middle', N'Namespaces were originally designed to organize code into logical groupings and prevent global scope pollution. In modern TypeScript, ES modules are preferred as they align with standard JavaScript module systems and handle dependency management more effectively than the historical namespace approach.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e37156e4-89f1-4c8b-8b91-1ecf5300c173', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the ''meta'' function used for in Remix?', N'Middle', N'The meta function allows you to define dynamic metadata, such as page titles, descriptions, and Open Graph tags, on a per-route basis. This is critical for SEO and ensuring that shared links look professional on social media platforms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2080f15c-750f-4975-97b2-1ecf8beb0c70', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the purpose of the RubyGems package manager?', N'Intern', N'RubyGems is a utility that allows developers to easily download, install, and manage libraries and dependencies for their Ruby projects. It acts as a central repository for sharing code within the Ruby community.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f825a8e-866c-4b37-9fcd-1ed0e911a9b9', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What does it mean for R to be dynamically typed?', N'Intern', N'Dynamic typing means that the data type of a variable is determined at runtime rather than at compile time. You do not need to declare the type of a variable when creating it in R.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd5f53b9-b32f-4d69-8059-1ed164cbfd94', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing a configuration system, what is the trade-off between hard-coded values and external configuration files?', N'Fresher', N'Hard-coded values are simple and ensure the system behaves consistently, but they require a code change to update. External configuration files allow for dynamic updates without recompilation, but they introduce the risk of misconfiguration and require a mechanism to load and validate them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03de0a99-32e9-422f-b725-1ed1c9f8ac55', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is ''Lazy Loading'' in Qwik?', N'Intern', N'Lazy loading is a performance technique where pieces of code are downloaded only when they are actually needed. In Qwik, this is highly granular, ensuring that only the specific code for an interacted component is loaded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56957930-2694-4602-acac-1ed2d3e37fef', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What specific architectural patterns should be avoided when transitioning from a standard library app to Fiber?', N'Senior', N'Avoid using any middleware or libraries designed for the standard net/http package, as they will attempt to access standard Request and ResponseWriter types. Additionally, avoid storing state in request-scoped variables that are not explicitly managed by Fiber''s context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3666a9ba-aecb-4c31-b41e-1ed359f86e4e', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the function of the Rails middleware stack?', N'Middle', N'The middleware stack is a chain of components that process each HTTP request and response before they reach the controller. It handles cross-cutting concerns like session management, cookie parsing, header manipulation, and error handling, acting as a modular pipeline for request lifecycle management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'781d2ab4-72ae-4f7d-b6f9-1ed3e64dff99', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How to access cache data in Node.js?', N'Fresher', N'Caching is a technique used in web development to handle performance bottlenecks related to how data is managed, stored, and retrieved. A cache layer or server acts as a secondary storage layer, usually faster and highly performant to temporarily store a subset of data. It is expected that data stored in a cache does not change often. Cache can be stored using various techniques like in-memory cache, file cache or a separate cache database. Installation: Node-cache has following major functions: * .set(key, val, [ ttl ]): Used to set some value corresponding to a particular key in the cache. This same key must be used to retrieve this value. * .get(key): Used to get value set to specified key. It returns undefined, if the key is not already present.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0443cc4a-56bb-44b5-9792-1ed68a41ada5', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of a Declaration File (.d.ts)?', N'Middle', N'Declaration files contain only type information and are used to provide type definitions for JavaScript libraries that lack native TypeScript support. They enable TypeScript to provide autocompletion and type checking for external dependencies without modifying the original source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'561f99da-9bf8-4ed8-99fd-1ed6e7c872b1', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the <label> element improve HTML forms?', N'Fresher', N'The element provides a text description for a form control. It improves both accessibility and usability. Two ways to associate a label with an input: 1. Using for + id (explicit — recommended): 2. Wrapping the input (implicit): Benefits: 1. Accessibility — Screen readers announce the label text when the input receives focus. 2. Larger click target — Clicking the label text also focuses/activates the input, especially helpful for checkboxes and radio buttons on mobile. 3. WCAG compliance — Associating labels with inputs is a WCAG 2.1 Level A requirement. > Always use for every form control. Placeholder text is not a substitute — it disappears when the user starts typing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'243227d3-0123-42bd-af93-1ed78a64cdd0', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the advantage of using opaque pointers or handles for encapsulation?', N'Middle', N'Opaque pointers allow you to hide the internal structure of an object from the user of a library, exposing only a pointer type. This enables you to change the internal implementation of the data structure without breaking binary compatibility for existing code that uses the library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9154394b-f66c-4e6d-9949-1ed80ff5bde6', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the role of a dead-letter queue in a message-driven system?', N'Middle', N'A dead-letter queue is a storage area for messages that cannot be processed successfully after multiple attempts. It prevents these messages from blocking the main processing pipeline while allowing developers to inspect and debug them later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76521e60-414e-467c-bad1-1ed9bd338fec', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the function of the LIMIT clause in a SELECT statement?', N'Junior', N'The LIMIT clause is used to specify the maximum number of records to return from a query result set. It is commonly used in pagination to display a small subset of data at a time instead of retrieving thousands of records at once.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66f710d1-ebdb-43f1-bf08-1ee39565b0ef', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the ''Quarkus Testing'' model?', N'Middle', N'Quarkus provides a robust testing framework that supports both JVM-based tests and native executable tests. It allows developers to test components in an environment that closely mirrors production, including automatic startup of necessary infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7614152d-a5a0-4703-b1f1-1ee6015d6825', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle dependency injection compared to other Node.js frameworks?', N'Middle', N'AdonisJS uses a built-in IoC container that manages the lifecycle and resolution of dependencies automatically. This allows for cleaner architectural decoupling, as services can be resolved by their abstract keys rather than requiring manual instantiation or complex import chains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d9a56c8-52a3-4178-8f4f-1ee7b68376a8', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How should you approach error handling in a Hono application?', N'Middle', N'You should use the built-in error handling middleware to catch exceptions globally. By defining a custom error handler, you can normalize response formats and ensure sensitive stack traces are not exposed to the client in production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'236f345e-8503-468e-9820-1ee86258062f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is function composition and how do compose and pipe work?', N'Intern', N'Function composition is the mathematical concept of chaining functions such that the output of one becomes the input of the next: (f ∘ g)(x) = f(g(x)). In JavaScript this is implemented with two conventions: - compose(f, g, h) — applies right-to-left: f(g(h(x))) (mathematical convention) - pipe(f, g, h) — applies left-to-right: h(g(f(x))) (more readable for imperative programmers) Both require unary functions (single argument) for clean composition. Multi-argument functions must be curried first. Example: Real-World Use Case: Redux middleware (applyMiddleware) and compose utility implement pipeline composition — compose(logger, thunk, devTools)(createStore) stacks middlewares right-to-left.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'448ced0f-8f7c-4448-9486-1ee9512af9b0', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind facilitate team collaboration on front-end projects?', N'Middle', N'Tailwind reduces friction in code reviews because developers don''t have to navigate through multiple CSS files to understand how a component is styled. Since all styling is visible directly in the HTML, the intent of the author is clear and consistent across the entire team.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c423693b-2a86-40ff-9380-1eeb8baf1672', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Why is Alpine.js often described as a ''framework for modern static sites''?', N'Intern', N'It is described this way because it is intended to be dropped directly into existing HTML files via a script tag without requiring a complex build process like Webpack or Vite. This makes it ideal for developers who want to enhance static HTML pages with dynamic features rather than building a full Single Page Application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73979173-5ea9-4b33-a570-1eef4e9c97d8', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How do memoized selectors (e.g., reselect) mitigate performance issues in a React-Redux application?', N'Senior', N'Memoized selectors prevent unnecessary re-computations by caching the result of a transformation based on the input arguments. When the underlying state remains unchanged, the selector returns the cached reference, preventing downstream components from re-rendering due to object identity changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baaf610f-4926-41ef-aa7b-1ef4077ab5a4', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the primary benefit of constexpr functions over const variables?', N'Senior', N'Constexpr functions allow for the execution of logic during compilation, turning runtime calculations into compile-time constants. Unlike simple const variables, constexpr enables the creation of complex, type-safe, and highly optimized constant expressions that are evaluated before the program even runs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e75da89c-f0ec-46d3-9652-1ef52b702e70', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js differ from heavy frameworks like React or Vue in terms of architecture?', N'Middle', N'Alpine.js is a lightweight, declarative framework designed to be included directly in HTML via script tags without a build step. Unlike component-based frameworks that require a virtual DOM and complex state management, Alpine enhances existing HTML by adding behavior directly to the DOM nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8412bf1-56f6-498a-8030-1effe19b773c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the primary reason for using connection pooling in a database application?', N'Junior', N'Opening and closing database connections is an expensive operation that can significantly degrade performance under high load. Connection pooling maintains a set of reusable connections, allowing the application to quickly borrow and return them, which reduces latency and resource consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65f6d21f-64f5-4503-98e5-1f015077745c', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'You receive a bug report that only happens occasionally. How do you approach reproducing it?', N'Junior', N'I would first look for patterns in the bug reports, such as specific user environments, browser versions, or time of day. If no obvious pattern exists, I would focus on logging more detailed telemetry or state data to capture the application''s context at the moment the failure occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f84c4b01-c112-4a37-aeca-1f02f59b64cf', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the Symfony ''bin/console'' file?', N'Junior', N'This is an entry point script used to execute CLI commands within your Symfony application. It provides access to the framework''s internal tools for maintenance, development, and debugging from the terminal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eef5a625-9952-448f-9c95-1f0540f6f73c', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain how you can minimize the Memcached server outages in your Python Development?', N'Fresher', N'- When one instance fails, several of them goes down, this will put larger load on the database server when lost data is reloaded as client make a request. To avoid this, if your code has been written to minimize cache stampedes then it will leave a minimal impact - Another way is to bring up an instance of Memcached on a new machine using the lost machines IP address - Code is another option to minimize server outages as it gives you the liberty to change the Memcached server list with minimal work - Setting timeout value is another option that some Memcached clients implement for Memcached server outage. When your Memcached server goes down, the client will keep trying to send a request till the time-out limit is reached', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a285b3a-3eb9-43ae-af24-1f0683c5baa2', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the ''select_for_update'' method and what problem does it solve?', N'Middle', N'This method performs a row-level lock on database records, preventing other transactions from modifying or locking those rows until the current transaction completes. It is critical for preventing race conditions in scenarios like inventory management or account balance updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6c441ab-8f45-4c7a-a402-1f07d0c12875', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is write capacity unit (WCU)?', N'Intern', N'A WCU represents one unit of write throughput for your table. It allows you to perform one write per second for an item up to 1 KB in size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7f81eb8-d27d-44dc-a41d-1f0a231d4454', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is an error-first callback?', N'Intern', N'The error-first callback is a Node.js convention where the first argument of every callback is reserved for an error object, and subsequent arguments carry the success result. The Pattern * If the operation failed → err is an Error object, results are undefined * If the operation succeeded → err is null, results contain the data Why It Exists Async exceptions cannot be caught with try/catch because the callback fires after the call stack has moved on: Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24ca8ed0-70c9-4b38-b17a-1f0a313cf8d4', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack handle hot module replacement (HMR)?', N'Middle', N'HMR allows modules to be updated, added, or removed while an application is running without a full page reload. Webpack tracks changes to files and pushes the updated modules to the browser via WebSockets, where the runtime patches the application state in place.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'141e9296-bc27-4144-826c-1f0e12e296d6', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Can you use custom values in Tailwind if the default utilities are not enough?', N'Junior', N'Yes, Tailwind supports arbitrary values using square bracket notation, which allows you to apply specific values like exact pixel widths or colors not in your theme. This is useful for edge cases where the standard design system does not provide the exact styling needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
