INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34ed4bae-689b-4b40-9d35-1f11414354ab', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the benefit of explaining your thought process out loud during a problem-solving session?', N'Intern', N'Verbalizing your thoughts helps you identify logical gaps in your own reasoning and ensures that your supervisor understands your approach. It also allows others to intervene early if they spot a misunderstanding, saving time and preventing errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f38318cb-726b-4ecb-b74b-1f11911a6e48', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of using a circuit breaker pattern in a Rails application that consumes third-party APIs?', N'Senior', N'A circuit breaker prevents the application from repeatedly calling a failing external service, which saves local resources and prevents cascading failures. It allows the system to fail fast and recover gracefully, maintaining overall system stability during external service outages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
