INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9c28082-18ce-49bf-9230-1f16d2e3a976', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'In a database, what is the purpose of an index, and when should you avoid creating too many of them?', N'Fresher', N'An index helps the database find data faster, similar to an index in a book. However, you should avoid creating too many because every index consumes extra storage and slows down write operations, as the database must update the index whenever data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0659d356-015b-40a5-be1e-1f17a1f9e33a', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between SQL and NoSQL databases?', N'Intern', N'SQL databases are relational, use structured schemas, and are based on tables. NoSQL databases are non-relational, offer flexible schemas for unstructured data, and often use document, key-value, or graph models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4752a33e-e987-43ea-955b-1f183ba88825', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What does Elasticsearch mean by being ''distributed''?', N'Intern', N'Being distributed means that Elasticsearch can automatically manage how data is stored and distributed across multiple nodes. It handles the complexity of data replication and rebalancing, allowing the system to scale easily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f221eab-c312-4632-9b66-1f1bc00e121d', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why is it difficult to achieve strong consistency in distributed caching?', N'Senior', N'Strong consistency requires synchronous coordination between all cache replicas, which introduces significant latency and reduces throughput. This creates a fundamental trade-off described by the CAP theorem, where systems often choose eventual consistency to maintain high availability and low latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
