INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a259d39-fea2-407a-92ef-1f29ba2c6e89', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How do NestJS Global Pipes differ from Controller-scoped pipes in terms of their execution pipeline?', N'Senior', N'Global pipes are applied to every incoming request at the application level, providing a uniform way to handle validation or transformation. Controller-scoped pipes only apply to routes within that controller, allowing for more granular control when specific endpoints require different validation logic or schema enforcement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04269e91-cae2-4a7f-88ce-1f2e3d2eaf89', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the advantage of using a functional language like Elixir in Phoenix?', N'Fresher', N'Functional programming emphasizes immutability and pure functions, which makes code easier to test and reason about. Because Elixir avoids shared state, it significantly reduces bugs related to concurrent access in high-traffic web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
