INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68e5d1bd-76b0-4ddb-898e-1f34743ab934', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the purpose of the head section in an HTML document?', N'Intern', N'The head section contains metadata about the document, which is information that is not displayed directly on the webpage. This includes the page title, links to CSS stylesheets, character set definitions, and viewport settings for responsive design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efcae8a2-9dc1-4b8c-8fc9-1f3546f3dead', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are the advantages of using Symfony Messenger for asynchronous background processing compared to synchronous execution?', N'Senior', N'Messenger decouples time-consuming tasks from the web request-response cycle, significantly improving user-perceived performance and system resilience. It allows for horizontal scalability by offloading tasks to separate workers and provides built-in mechanisms for retries, failure handling, and bus-based routing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94952a59-aa68-474d-a553-1f368d25ccfe', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the benefit of using Echo''s ''Context'' object to share data between middlewares and handlers?', N'Middle', N'The ''Set'' and ''Get'' methods on the context allow you to pass request-scoped data, such as authenticated user IDs or tracing spans, through the middleware chain. This avoids the need for global variables and keeps the data isolated to a single request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60463b0c-2485-4f60-9bf0-1f380ab58786', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the trade-offs between using a generational garbage collector versus a reference counting approach in JavaScript engines.', N'Senior', N'Generational GC exploits the weak generational hypothesis by segregating objects into young and old generations, which improves throughput. Reference counting handles memory reclamation immediately but struggles with cyclic references and introduces significant overhead on every pointer assignment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'722be6d8-0eab-4b42-981a-1f391b7a9f74', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is an API endpoint in ASP.NET Core?', N'Intern', N'An endpoint is a specific URL path that an application listens for, associated with a particular HTTP method like GET or POST. It represents a single functional unit of an API that can be called by a client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
