INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd30af610-817a-44da-bfc1-1f3ccb2d08b6', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is a ''case class'' in Scala and why is it used?', N'Intern', N'A case class is a special type of class that is optimized for pattern matching and data modeling. It automatically provides implementations for equality, hashing, and string representation, making it ideal for immutable data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4812ddcd-3119-48a0-adce-1f3d1e3ad520', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the ''Redo Log'' ensure durability in InnoDB?', N'Middle', N'The Redo Log records all changes made to the data pages, which are written sequentially to disk. In the event of a crash, MySQL uses these logs to replay operations and restore the database to its last consistent state, fulfilling the durability requirement of ACID.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
