INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74b11078-d65a-41b4-a392-1f432e214625', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is static interface method?', N'Intern', N'Static interface methods are similar to default methods, except that there is no way to override them in classes that implement the interface. * Static methods in the interface are part of the interface without the ability to use them for objects of the implementation class * Class methods java.lang.Objectcannot be overridden as static * Static methods in the interface are used to provide helper methods, for example, checking for null, sorting collections, etc.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30e9bd53-3346-4521-baf8-1f443b694f2d', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the significance of the ''Q-ID'' in Qwik?', N'Intern', N'The Q-ID is a unique identifier attached to DOM elements that helps Qwik map them to their corresponding JavaScript chunks. It allows the framework to know exactly which piece of code to load when a specific user interaction occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3bbaf24-9b05-4e5c-9e4d-1f44b4ffd1cf', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'When should you use a GIN index instead of a B-tree index?', N'Middle', N'GIN (Generalized Inverted Index) is designed for cases where a single column contains multiple values, such as arrays, JSONB, or full-text search documents. B-tree indexes are suitable for scalar data types where you need to search for exact matches or ranges, whereas GIN is optimized for searching keys contained within composite structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
