INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5841075e-22aa-41e4-bd73-1f519ec218df', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the concept of ''dispatch'' in Swift and the difference between static and dynamic dispatch.', N'Middle', N'Dispatch determines which implementation of a function to call at runtime. Static dispatch occurs at compile time, which is faster and allows for compiler optimizations like inlining, while dynamic dispatch uses a table lookup at runtime to support polymorphism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
