INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e7835aa-a00a-48f9-877f-1f58553bfa05', N'075b8862-431c-4678-9767-f55359758a4a', N'Explain why Vue''s computed properties are cached and when this behavior might be undesirable.', N'Senior', N'Computed properties are cached based on their reactive dependencies, ensuring the calculation only re-runs when those dependencies change. This behavior is undesirable when the computed property depends on non-reactive data or external global state that changes outside of Vue''s reactivity system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66209f10-6119-464b-9aeb-1f5971fb97d8', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the primary purpose of Astro?', N'Intern', N'Astro is a web framework designed for building content-focused websites. It prioritizes performance by shipping minimal JavaScript to the browser by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bacdb2c-0a00-4aa1-9ee3-1f5bb07afc7b', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the concept of Database Migrations and their importance in team environments.', N'Middle', N'Migrations act as version control for your database schema, allowing developers to define table structures in code. This ensures that every developer on a team can synchronize their local database state simply by running a command, avoiding manual schema changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2eabb858-b62d-45bd-9057-1f664d9a0677', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle concurrent requests that rely on shared but mutable state?', N'Senior', N'Litestar relies on the developer to manage shared state thread-safely, as it does not enforce immutability at the framework level. Architects must use appropriate synchronization primitives or rely on immutable data structures to prevent race conditions in asynchronous code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7eb830ea-628c-49b6-9c80-1f719576a1d4', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you document your problem-solving process for others to follow?', N'Fresher', N'I maintain clear notes on the problem, the steps I took to reproduce it, and the final solution I implemented. This documentation helps teammates understand my logic and serves as a reference if similar issues arise later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef7e4f14-ab70-4d9e-9a00-1f71f77777ad', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the ''dual write'' problem in microservices, and how does the Transactional Outbox pattern solve it?', N'Senior', N'The dual write problem occurs when a service attempts to update a database and send a message to a broker separately, risking inconsistency if one fails. The Transactional Outbox pattern solves this by saving the message into an ''outbox'' table within the same local database transaction, then using a separate process to relay those messages to the broker.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03440eb3-b207-4b37-ba67-1f738cecd22f', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What happens to dynamic features like JMX or dynamic proxies in Native Image?', N'Senior', N'These features are inherently restricted because Native Image requires a closed-world assumption where all code is known at compile time. While some dynamic proxying is supported if pre-configured, features relying on arbitrary class loading or bytecode manipulation at runtime will fail unless explicitly bypassed or configured via reachability metadata.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3becb82f-7540-495a-8346-1f7395b0ef06', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you approach the trade-off between centralized and decentralized logging?', N'Senior', N'Centralized logging provides a single pane of glass for troubleshooting and security auditing, which is essential for compliance. Decentralized logging allows for local exploration and reduced network traffic, but makes aggregate analysis across the system significantly more difficult.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd09226e9-247f-49f9-8f3f-1f73cedba61a', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the role of the Flask application context and how does it differ from the request context?', N'Middle', N'The request context manages data specific to a single HTTP request, such as headers and arguments. The application context tracks application-level data like configuration and database connections. Both are pushed to the stack during request handling to allow global access without passing objects manually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3123a97-270f-4b26-9f44-1f7596b1a991', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala''s ''Option'' type handle null values?', N'Junior', N'The Option type is a container that represents the presence or absence of a value, using ''Some'' if a value exists or ''None'' if it is missing. This forces developers to handle the absence of data explicitly, preventing null pointer exceptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5884fe3-639d-40ef-9690-1f75c0876e25', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Discuss the performance implications of Ruby''s ''method_missing'' and ''define_method'' metaprogramming techniques.', N'Senior', N'Method_missing is costly because it forces a full traversal of the ancestor chain before falling back, while define_method adds overhead during the initialization of the class. Both techniques bypass static analysis and can make performance profiling difficult, often resulting in slower execution compared to explicitly defined methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24574920-489a-4b69-b048-1f762c778f46', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the role of a Controller in AdonisJS?', N'Intern', N'A controller acts as the intermediary between the incoming HTTP request and the application logic. It processes the request, interacts with models to fetch or save data, and determines the appropriate response to send back.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cedd05f2-6109-4b49-89dd-1f784032e0e1', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does Node.js handle error propagation in asynchronous operations compared to traditional synchronous code?', N'Senior', N'In asynchronous operations, errors cannot be caught with standard try-catch blocks across callbacks or promises without explicit handling. Developers must use error-first callbacks, promise rejection handlers, or async/await with try-catch blocks to ensure errors are captured. Failing to handle errors properly in asynchronous flows leads to unhandled promise rejections, which can crash the process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84c9c654-0040-4e31-a81b-1f7ed369f4e2', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Describe the security implications of using Laravel''s mass assignment protection and why it is critical for production APIs.', N'Senior', N'Mass assignment protection prevents users from injecting unauthorized data into database columns by restricting which fields can be updated via array inputs. Failure to configure this correctly can lead to privilege escalation, such as a user updating their own ''is_admin'' status during a profile update request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee0436a8-59fd-4729-b6e5-1f818c64c577', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the role of the ''x-data'' directive in defining the scope of a component?', N'Senior', N'The x-data directive initializes a reactive object that defines the state and scope for that specific DOM subtree. It creates a new instance of the Alpine reactive engine for that scope, ensuring that data is encapsulated and that changes to the state only trigger re-renders within that specific hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea69f281-25f9-41db-9e50-1f8701255db9', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the concept of ACID properties in databases?', N'Intern', N'ACID stands for Atomicity, Consistency, Isolation, and Durability, which are a set of properties that guarantee reliable transaction processing. These properties ensure that a database remains in a valid state even in the event of errors, crashes, or power failures. They are fundamental to maintaining data integrity in relational systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c05648c7-3130-4cff-9df4-1f8796194d21', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the risks of using the ''find_in_batches'' method on extremely large datasets?', N'Senior', N'While it prevents loading the entire dataset into memory, it relies on primary key ordering which can be slow on non-indexed columns. Additionally, if data is modified while the batch process is running, the process might skip records or process the same record twice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
