INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3925ff04-c6dd-4bc4-a9dd-1f904b261d93', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are ''group'' and ''peer'' modifiers in Tailwind?', N'Fresher', N'These are state modifiers that allow you to style an element based on the state of its parent or sibling. ''Group'' is used to apply styles based on the parent''s hover state, while ''peer'' is used to style an element based on the state of a preceding sibling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1cb24f49-c6ab-4f69-9bfa-1f905776a7a4', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is it important to use ''const'' qualifiers for pointers?', N'Middle', N'Using ''const'' improves code safety by preventing accidental modification of data that should remain read-only. It also allows the compiler to perform better optimizations by guaranteeing that the pointed-to values will not change unexpectedly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa86ddb6-3580-4495-a9f4-1f907e16e55c', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the difference between a functional requirement and a non-functional requirement?', N'Intern', N'Functional requirements define what the system must do, such as specific features or user actions. Non-functional requirements define how the system should perform, such as scalability, security, and speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'664b65f1-917a-416a-8bd2-1f998606d302', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the difference between synchronous and asynchronous operations in AdonisJS?', N'Fresher', N'Since AdonisJS is built on Node.js, most I/O operations like database queries or file reading are asynchronous. Asynchronous operations prevent the server from blocking while waiting for a task to complete, allowing it to handle other incoming requests simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02a2ae3b-e342-412f-a686-1f9a27481aac', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you work with preprocessors using vue loader?', N'Fresher', N'Vue-loader will automatically infer the proper loaders to use based on the lang attribute of a language block and the rules defined in webpack config. You can use pre-processors such as SASS,LESS, Stylus and PostCSS using vuejs loader.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb979652-20b2-4f40-a737-1f9d7f9b7f60', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the difference between an Extractor and a Handler in Axum?', N'Intern', N'An Extractor is used to parse and validate components of an incoming request, while a Handler is the function that actually processes those components to produce a result. Extractors provide the input to the handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0043a6b5-d966-40e6-a9cc-1f9ee405c66c', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte manage styles in components?', N'Junior', N'Svelte scopes CSS styles to the component by default. During the build process, it adds unique classes to elements so that styles defined within a component do not leak out and affect other parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bca6a57-a0eb-4bfc-9155-1fa1b5e89662', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does the ''context'' pattern in Lit differ from the Context API in React?', N'Senior', N'Lit''s context implementation usually relies on DOM event bubbling or specialized context providers to propagate data down the tree without prop drilling. Unlike React''s Context, it is designed to work across boundaries of shadow roots, making it more robust for distributed design systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8eee0f3-9b40-40da-b494-1fa2d1a5bf90', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why does the order of link tags for CSS matter in an HTML document?', N'Senior', N'CSS follows a cascading priority model where styles defined later in the document or in later-loaded files take precedence. Incorrect ordering can lead to unpredictable style overrides, making CSS maintenance difficult and potentially causing layout shifts as the browser processes multiple stylesheets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74bec98f-5f8c-4dda-96d6-1fa38e3a6697', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are the architectural benefits of using the Shadow DOM in Lit components for large-scale applications?', N'Senior', N'Shadow DOM provides strong encapsulation by isolating styles and the DOM structure from the global document context. This prevents style leakage and CSS collisions, allowing large teams to work on independent components without worrying about side effects on the rest of the application''s global layout or styling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'230abc18-525e-4f61-b9de-1faa3bc52c72', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the trade-offs of using PHP''s weak references compared to strong references.', N'Senior', N'Weak references allow an object to be referenced without preventing its destruction by the garbage collector. This is useful for building object caches or mapping structures that should not prevent memory reclamation if the object is no longer used elsewhere in the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
