INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6e1501c-c9f6-4201-be14-1faf3c17354c', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the role of the ''options'' object in Preact for framework extensibility?', N'Senior', N'The ''options'' object allows developers to hook into Preact''s internal lifecycle, such as intercepting VNode creation or component rendering. This is the primary mechanism for building DevTools, performance monitoring utilities, or custom state management libraries that need to observe or modify the rendering lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
