INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18450bb6-465e-45d0-8e95-1fccdaff9d9a', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does the C++ volatile keyword differ from its Java or C# counterparts?', N'Senior', N'In C++, volatile is intended for memory-mapped I/O and signal handlers, informing the compiler that an object''s value can change outside the program''s control, thus preventing optimization of reads and writes. Unlike Java or C#, C++ volatile does not provide any atomicity, thread synchronization, or memory barrier guarantees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ea48360-d0dd-4121-b430-1fccfcdb7642', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you verify if a system failure is due to a network issue?', N'Fresher', N'I would check connectivity between services using standard diagnostic tools like ping or traceroute. If services are unreachable or timing out, the problem is likely related to the network infrastructure rather than the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49af7a03-9a33-424e-81fc-1fce445dd6ad', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the architectural considerations when migrating a large React app from client-side rendering to SSR?', N'Senior', N'The primary considerations include handling global browser objects like window/document that are unavailable on the server, ensuring data serialization for state transfer, and optimizing the initial bundle size. It also requires a robust strategy for managing authentication and environment-specific configurations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'417de42d-9600-489e-8017-1fd3ae995a39', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you display data in a tabular format using console object', N'Fresher', N'The console.table() is used to display data in the console in a tabular format to visualize complex arrays or objects. The data visualized in a table format, !Screenshot Not: Remember that console.table() is not supported in IE.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'183b730f-3c63-4af4-bf80-1fd761f7b28a', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a ''TTL'' in Redis and why is it useful?', N'Junior', N'TTL stands for Time-To-Live, which is a setting that determines how long a key should exist in the database before it is automatically deleted. This is very useful for caching scenarios where data only needs to be temporarily stored.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'191bb3b4-9d13-4989-b421-1fd91b1ea693', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the CAP theorem and why does it matter for system design?', N'Middle', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. In large-scale systems, partition tolerance is mandatory, forcing architects to choose between consistency and availability during network failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9330bc2f-1a00-4204-b07d-1fdd0f79df07', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of the ''Introspected'' annotation in Micronaut?', N'Middle', N'The @Introspected annotation tells the compiler to generate a BeanIntrospection for a class. This allows Micronaut to access properties and create instances of the class without using reflection, which is essential for performance, especially when using GraalVM native images.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'453ca8f2-c8ec-4ede-959d-1fdd1ae2e666', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Describe the trade-offs of using Redis Pub/Sub in a distributed architecture.', N'Senior', N'Redis Pub/Sub is high-performance and lightweight, but it is ''fire-and-forget'' with no built-in message persistence or delivery guarantees. If a subscriber disconnects, it misses all messages published during the downtime, making it unsuitable for mission-critical tasks requiring guaranteed delivery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d24f306-cec5-46e5-9519-1fe1fdd4e0da', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why is server-side rendering (SSR) more complex with Web Components compared to traditional frameworks?', N'Middle', N'Standard Web Components rely on the browser''s custom element registry, which is not natively available in Node.js environments. Lit SSR requires specific libraries to serialize the component tree and hydrate it on the client, bridging the gap between static HTML and dynamic interactive elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd944fd0f-31d3-4a83-95ac-1fe858e3e731', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Does Webpack support CSS natively?', N'Intern', N'No, Webpack only understands JavaScript and JSON files by default. To process CSS, you must use loaders like ''css-loader'' to interpret the file and ''style-loader'' to inject the styles into the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65e7eb29-e7cf-4af3-9f1f-1fe8c02d2e4a', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the purpose of the ''chi.URLParam'' function?', N'Middle', N'This function is used to retrieve dynamic path parameters defined in the route pattern, such as user IDs or resource names. It extracts these values from the request context where Chi stores them during the routing process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd36e9a39-23b7-4c8e-9b80-1fe94e149a84', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the role of the ''helmet'' middleware?', N'Junior', N'Helmet is a popular middleware that helps secure your Express app by setting various HTTP response headers. It protects the application from common web vulnerabilities like cross-site scripting and clickjacking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8549bfca-5cbe-4baf-bf2a-1fec3c79d398', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How does the ''Bulkhead'' pattern protect a system?', N'Middle', N'The bulkhead pattern isolates elements of an application into pools so that if one fails, the others continue to function. By limiting the resources (like thread pools or connection pools) dedicated to a specific service, you prevent one overwhelmed service from exhausting the entire system''s capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06140c7a-2393-470f-9ea1-1fec537d81b3', N'954a0331-deff-4399-b588-96f39fec001d', N'How does Angular''s Change Detection strategy (Default vs OnPush) impact application performance in large-scale applications?', N'Senior', N'The Default strategy checks every component for changes whenever any event occurs, which scales poorly as the component tree grows. OnPush optimizes performance by only triggering change detection when an input reference changes or an event originates from within the component, significantly reducing CPU overhead in complex UIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8998f99d-1f30-4c5e-9802-1fed10cfa807', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Describe the impact of ''project references'' on managing large-scale monorepo architectures.', N'Senior', N'Project references allow a large TypeScript workspace to be split into smaller, independently compilable sub-projects. This improves build performance through incremental compilation and allows for strict boundary enforcement between different parts of the application architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aff45fca-95d5-4d5c-a72e-1feee88c2d4f', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of Database Normalization to the Third Normal Form (3NF)?', N'Middle', N'3NF ensures that every non-key attribute is dependent only on the primary key, eliminating transitive dependencies. This structure prevents update, insertion, and deletion anomalies, ensuring that a change to a single piece of data only needs to be performed in one location.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'962812a5-78e8-42d3-ba1b-1ff18fe14db8', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte optimize the rendering of large lists?', N'Senior', N'Svelte uses keyed each blocks to track elements in a list, ensuring that only the changed, added, or removed items are touched in the DOM. This minimizes expensive DOM operations and maintains the state of keyed components during list reordering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c15c6efb-2db7-41a5-801d-1ff19300ba08', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What are the trade-offs of using persistent storage for queues versus in-memory queues?', N'Senior', N'Persistent storage ensures durability across broker restarts but introduces disk I/O bottlenecks. In-memory queues offer ultra-low latency and high throughput but risk losing all unacknowledged messages during a crash or power failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'467a2fec-65fa-4daf-a54c-1ff377d3b96e', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Does Remix work well with client-side only libraries?', N'Middle', N'Yes, but they must be carefully integrated to handle the server-side environment. Since code runs on the server first, you often need to wrap client-side logic in checks or use lifecycle hooks like useEffect to ensure libraries requiring the window object do not execute during SSR.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9fc86ef-22d7-4c46-a8c0-1ff3f5314ea2', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is middleware in the Fiber framework?', N'Intern', N'Middleware are functions that execute during the lifecycle of an HTTP request before the final route handler. They can perform tasks like logging, authentication, or modifying the request and response objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72f55ac3-63f2-44fe-a01a-1ffeb599fa91', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the ''Backpressure'' mechanism and why is it important in stream processing?', N'Senior', N'Backpressure occurs when a consumer cannot keep up with the rate of incoming events from a producer. By signaling the producer to slow down or buffering the overflow, the system prevents memory exhaustion and cascading crashes in downstream components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a5494ba-b1f8-4a9f-a02e-1fff62643757', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is database denormalization?', N'Intern', N'Denormalization is the process of intentionally adding redundant data to a database to speed up read operations. By reducing the number of joins required, the database can retrieve information faster at the cost of increased storage space.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'610154b2-dd62-4e23-9f5c-1fff6d453da2', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the purpose of the ''error boundary'' in Remix, and how does it improve user experience?', N'Middle', N'Error boundaries are special components that catch errors occurring during the server-side rendering or data loading phase of a route. They allow the developer to display a specific UI for the failed segment, preventing the entire application from crashing and providing a graceful degradation of the interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0701600e-d590-44de-995b-2007c67caeff', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is meant by the scope of a variable?', N'Intern', N'The scope of a variable refers to the specific region of the program where that variable is visible and can be accessed. A variable defined inside a block is not visible outside that block.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68d0dcf6-f028-4665-85c9-200878d83e90', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the trade-offs of using Flask-SQLAlchemy versus raw SQL queries.', N'Middle', N'Flask-SQLAlchemy provides an abstraction layer that simplifies database interactions and improves code readability through an ORM. While raw SQL offers potentially better performance for complex queries and more control, it is harder to maintain and prone to security risks like injection. ORMs are generally preferred for standard CRUD operations in mid-sized projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d6ecee4-66a9-4a7d-8101-200dda95cb88', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What are the performance implications of using complex CSS selectors?', N'Middle', N'Browsers match CSS selectors from right to left, so overly specific or deeply nested selectors require more computational effort during the style calculation phase. Keeping selectors flat and simple improves browser performance, especially in large applications with many DOM nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ea69e27-71f7-45b9-89f2-200e4be24a70', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of queueMicrotask', N'Intern', N'The queueMicrotask function is used to schedule a microtask, which is a function that will be executed asynchronously in the microtask queue. The purpose of queueMicrotask is to ensure that a function is executed after the current task has finished, but before the browser performs any rendering or handles user events. Example: By using queueMicrotask, you can ensure that certain tasks or callbacks are executed at the earliest opportunity during the JavaScript event loop, making it useful for performing work that needs to be done asynchronously but with higher priority than regular setTimeout or setInterval callbacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7dcce1a2-7dbd-47c1-bb9b-200ef5b750dc', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the Show component used for in SolidJS?', N'Junior', N'The Show component is a control flow utility used for conditional rendering. It efficiently switches between displaying its children or a fallback based on a reactive boolean condition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8888f87b-9ff6-4b69-95a3-2010e13c8b02', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Discuss the trade-offs of using PHP''s reflection API in production code.', N'Senior', N'Reflection allows for deep inspection of classes and methods at runtime, which is essential for dependency injection containers and ORMs. However, it is computationally expensive and can significantly increase request latency if used excessively within loops or hot paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e718ddc-60f6-43d6-88bc-20125e91184a', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does Python''s function argument unpacking and keyword-only arguments influence API design?', N'Senior', N'Argument unpacking (*args and **kwargs) allows for highly flexible function signatures and effective wrapper functions. Keyword-only arguments force clarity in API usage by requiring explicit naming of parameters, which reduces ambiguity in functions with many optional parameters. Combining these features allows for the creation of extensible and maintainable interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14c219b6-10aa-4d03-ad32-2014649ce9e5', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why is compaction important in log-structured merge-tree (LSM) storage?', N'Middle', N'Compaction is the process of merging and cleaning up data files to remove obsolete entries and reclaim space. Without it, the storage footprint would grow indefinitely due to redundant updates and deletions, and read performance would degrade significantly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'723fcb9d-00de-4e25-857e-2016f6f0c8da', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What does the term ''BASE'' stand for in the context of NoSQL databases?', N'Junior', N'BASE stands for Basically Available, Soft state, and Eventual consistency. It represents a consistency model that prioritizes high availability and performance over the strict immediate consistency found in traditional ACID transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e35ffc14-de6c-4981-8440-201877da1bf6', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of ''res.redirect()''?', N'Junior', N'The res.redirect() method sends a response to the client telling it to navigate to a different URL. It typically sends an HTTP 302 status code by default, but can be configured to send other redirect status codes as well.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f99b909-e7b2-44d3-b7a2-2019467102ea', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Explain the importance of struct tags in Gin''s binding process.', N'Middle', N'Struct tags map incoming request parameters like JSON keys or URL query strings to struct fields. They also define validation constraints, allowing Gin to enforce data integrity automatically before the data reaches the business logic layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd98f70e-d8c4-465a-adf1-201aae751c8b', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you weigh the costs of maintaining a multi-region deployment against a single-region deployment?', N'Senior', N'Multi-region deployments provide disaster recovery and lower latency for global users but introduce significant complexity in data synchronization and conflict resolution. I assess if the cost of downtime and latency exceeds the operational cost and engineering effort of managing multi-region traffic routing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
