INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8724863a-8ba9-4c3b-8a8d-201fdbd4df8e', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is Tailwind CSS often considered easier to maintain than traditional CSS?', N'Intern', N'Tailwind reduces the need to constantly switch between HTML and CSS files, which prevents the build-up of unused or redundant CSS rules. Because styles are applied locally at the element level, developers do not have to worry about accidentally breaking global styles elsewhere in the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd08c6a90-8042-4b66-b33c-202096ba9e8d', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the ''ready'' state in Fastify?', N'Intern', N'The ready state refers to the point in the application lifecycle where all plugins have been registered and the server is prepared to start listening for requests. You can use the ''ready'' callback to execute logic that must occur only after the entire application configuration is complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd780dafc-73db-47d2-a221-20239b1d57ad', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are lambda functions in Python?', N'Junior', N'Lambda functions are small, anonymous functions that can contain only a single expression. They are defined without a name and are often used for short-term tasks, such as being passed as arguments to higher-order functions like map or filter. While convenient for simple operations, they are not suitable for complex logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bdec1f8-949c-42c4-90de-202425899b0e', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the JSON format in Web APIs?', N'Intern', N'JSON is a lightweight, text-based data interchange format that is easy for humans to read and machines to parse. It is the standard format used by ASP.NET Core Web APIs to exchange data between the server and the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30649692-fba8-445c-a915-20256a85c7cf', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do middleware functions work in Gin?', N'Junior', N'Middleware in Gin are functions that execute before or after the main request handler. They are chained together using the context object, allowing you to perform tasks like authentication, logging, or error recovery across multiple routes without duplicating code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d3ff9d5-3154-4006-b127-202582f79c54', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are loadable components?', N'Intern', N'With the release of React 18, React.lazy and Suspense are now available for server-side rendering. However, prior to React 18, it was recommended to use Loadable Components for code-splitting in a server-side rendered app because React.lazy and Suspense were not available for server-side rendering. Loadable Components lets you render a dynamic import as a regular component. For example, you can use Loadable Components to load the OtherComponent in a separate bundle like this: Now OtherComponent will be loaded in a separated bundle Loadable Components provides additional benefits beyond just code-splitting, such as automatic code reloading, error handling, and preloading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cee690a0-5430-4b7d-9f61-20267bd54ce1', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Compare the performance and memory trade-offs of using Proc objects versus simple blocks.', N'Senior', N'Blocks are a language construct that are highly optimized and do not require object allocation until explicitly converted into a Proc object. Converting a block to a Proc creates a new object in the heap, which incurs memory overhead and can trigger more frequent garbage collection if performed inside tight loops.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f08e035b-ed14-4054-a554-2028d5b94f20', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'When should you use the @at-root rule?', N'Middle', N'The @at-root rule allows you to break out of nested blocks and place a style rule at the root level of the CSS file. This is useful for creating global class names that need to be defined within a nested structure for logical grouping, such as handling modal overlays or global resets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eca369f0-74ae-40a0-b42b-202cc526584a', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the benefit of using Echo''s ''Validator'' interface?', N'Intern', N'The Validator interface allows you to define custom logic for validating the data bound from requests. This ensures that only data meeting your application''s requirements is processed by your business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bac84b7-a4df-486e-b286-20300b328b50', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle request routing compared to traditional heavy frameworks?', N'Intern', N'Hono uses a high-performance router designed for efficiency, focusing on rapid path matching even in serverless environments where startup time is critical. Unlike traditional frameworks that may rely on heavy middleware stacks or complex object-oriented patterns, Hono utilizes a minimalist design that prioritizes speed and low memory overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8807291-7884-48cd-9bd9-2034b6190f2a', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Does NoSQL use SQL query language?', N'Intern', N'Generally, NoSQL databases do not use standard SQL. They often use proprietary APIs, object-based query languages, or specific command-line interfaces to interact with the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'188c1762-fe8e-42e5-a699-20394bd4d090', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite''s plugin execution order work?', N'Middle', N'Vite plugins have an ''enforce'' property that dictates whether they run ''pre'' (before core Vite plugins), ''post'' (after core plugins), or default. This is critical for ensuring that transformations happen in the correct sequence, such as processing a custom file type before the bundler attempts to read it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5becfe1-2107-4ecd-aea5-203a1abae1a1', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why should you document your design decisions?', N'Intern', N'Documentation provides context for future developers about why specific trade-offs were made, preventing the team from repeating past mistakes. It serves as a historical record that helps maintain architectural integrity as the team grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6187b853-a6d7-4e0e-8424-203bb437fe87', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you stay organized when working on a large project with many files?', N'Junior', N'I follow established project structures and naming conventions to keep files organized and predictable. I also use IDE tools and clear commit messages to keep track of changes and navigate through the codebase efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8006750-d1c2-448f-b1dd-203d0c00f9e1', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the role of a ''Circuit Breaker'' pattern in a microservices environment?', N'Senior', N'A circuit breaker prevents a service from repeatedly calling a failing downstream dependency, which would otherwise waste resources and propagate latency. It transitions through closed, open, and half-open states to allow the failing service time to recover before resuming normal traffic flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2ebf5e1-2304-499e-b807-203ed1f25f39', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the primary trade-off of using a fiber-based architecture?', N'Intern', N'The primary trade-off is the increased complexity of the runtime and the requirement for non-blocking I/O throughout the entire application stack. If any library or function performs a blocking operation that doesn''t yield, it can negate the performance benefits of the entire system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fa9885a-7179-46c2-b48e-2040a60f3d14', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why does Remix discourage the use of global client-side state management libraries like Redux?', N'Senior', N'Remix treats the URL and the server-side data loaders as the single source of truth for the application state. By managing state through server-side mutations and revalidations, developers can avoid the complexity of synchronizing global stores with server data, which is often a source of bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee679216-cf8d-414f-b12a-204520fc453c', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the C compiler handle variable-length arrays (VLAs) internally?', N'Senior', N'VLAs require the stack pointer to be adjusted at runtime to allocate space based on variable sizes, which can be expensive and risky. Because the size is not known at compile time, the compiler must generate additional instructions to manage the stack frame dynamically, leading to potential security vulnerabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73bba293-aa63-4c01-8071-204613caa62f', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt ensure type safety across the full stack?', N'Senior', N'Nuxt leverages TypeScript by auto-generating types for routes, server API endpoints, and configuration files. This creates a unified development experience where changes in backend API signatures are immediately reflected and type-checked in the frontend codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'931b5cc9-74f5-4157-b2c9-2048c6ebd169', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the fundamental difference between pessimistic and optimistic concurrency control, and when would you choose one over the other?', N'Senior', N'Pessimistic concurrency control locks resources during a transaction to prevent conflicts, which is ideal for high-contention environments where conflicts are frequent. Optimistic concurrency control assumes conflicts are rare and only checks for them at commit time, which improves throughput in read-heavy or low-contention systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72d5b5ab-a4ee-4137-98c9-204c244c5d04', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the ''mix'' tool in Elixir and Phoenix?', N'Fresher', N'Mix is the build tool that ships with Elixir. It is used to manage dependencies, run tests, compile code, and execute tasks like starting the Phoenix server or running database migrations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1f4983e-2bb4-4d01-b409-204cc04b555d', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Describe the trade-offs of using ''Synchronous'' versus ''Asynchronous'' logging.', N'Senior', N'Synchronous logging ensures logs are persisted immediately but can introduce latency into the application''s request path. Asynchronous logging improves performance by buffering log events, but carries a risk of losing logs if the application crashes before the buffer is flushed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0b1d467-f846-424d-aa4c-204feec8f8ad', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is pessimistic concurrency control?', N'Intern', N'Pessimistic control assumes conflicts are likely and locks data as soon as a transaction starts accessing it. This prevents other transactions from modifying the data until the first transaction is finished.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dbbef19-ad81-4a0d-aa09-2051dd546643', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why is it often recommended to disable autovacuum for specific high-volume bulk-load tables?', N'Senior', N'Autovacuum can struggle to keep up with massive churn, leading to performance contention or excessive resource usage. It is often better to disable it and run manual, targeted maintenance after the bulk operation completes to ensure optimal performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd44cc94d-0e4f-499e-8224-20525513dff4', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does the Python method resolution order (MRO) handle multiple inheritance, and what algorithm does it use?', N'Senior', N'Python uses the C3 Linearization algorithm to determine the order in which base classes are searched for methods. This algorithm ensures monotonicity and local precedence order, preventing the ambiguities found in depth-first search approaches used by older languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26785912-a719-4025-974b-20537912ba2b', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo interact with standard HTTP libraries?', N'Middle', N'Echo is fully compatible with the standard net/http interface, allowing developers to integrate standard library handlers seamlessly. This allows for a smooth transition from existing projects and provides access to the vast ecosystem of standard-compliant middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'521ae18f-3358-4675-b694-2053f7681ca7', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle accessibility compared to other frameworks?', N'Middle', N'Svelte includes built-in accessibility warnings during the build process, alerting developers to potential issues like missing alt tags or improper ARIA usage. This proactive approach helps enforce best practices during development rather than relying on runtime auditing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'244fc728-a411-4fb5-8ed7-205506ccc58e', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why is Axum considered type-safe?', N'Fresher', N'Axum leverages Rust''s strict static type system to ensure that request data matches the expected structure at compile time. This prevents many common runtime errors related to missing fields or incorrect data types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aac0ffa8-88eb-4f27-b7dc-20565301d982', N'4c000000-0000-0000-0000-000000000005', N'What is the difference between a forward proxy and a reverse proxy?', N'Middle', N'A forward proxy sits in front of clients to manage outgoing requests, often used for content filtering or anonymity. A reverse proxy sits in front of servers to handle incoming requests, often used for load balancing, SSL termination, and caching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f544d182-1231-47f6-8345-2056e655bee9', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a scenario where a deployment works in staging but fails in production due to environmental differences?', N'Senior', N'I would perform a rigorous configuration drift analysis to compare environment variables, security group settings, and resource limits between the two environments. I would also check for differences in the underlying runtime version, library dependencies, or back-end data scale that might trigger edge cases not present in the smaller staging environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1698f848-7769-40f9-9bfb-20574ea42d09', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the difference between ''sync'' and ''async'' tests in ExUnit.', N'Middle', N'Sync tests run sequentially, which is necessary if they modify global state or the database in a way that interferes with other tests. Async tests run in parallel, significantly speeding up the test suite, provided they are written to be isolated and do not share mutable state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25bd3904-84b6-4fc9-8193-2059d33f7bbf', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix handle concurrency compared to traditional frameworks?', N'Junior', N'Phoenix uses the Erlang VM''s lightweight processes, which are cheap to create and manage. Unlike thread-based frameworks that require complex locking, Phoenix handles thousands of concurrent connections independently without blocking the entire system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8814fd77-38df-4665-862c-205c726a2434', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the role of the Dart Virtual Machine (VM) in the development process?', N'Intern', N'The Dart VM provides an environment that enables just-in-time compilation, which allows for fast development cycles through features like hot reload. It executes Dart code during development to provide immediate feedback, while also supporting the ahead-of-time compilation process used for final production builds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4de0a526-bf35-4e15-8b9f-205cedd76063', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are Validations in ActiveRecord?', N'Fresher', N'Validations are used to ensure that only valid data is saved into your database. They allow you to define rules, such as requiring a field to be present or ensuring an email address is formatted correctly, before data is persisted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
