INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab343e1f-c034-4a07-9719-205d1634bce0', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a ''rollback'' in database transactions?', N'Intern', N'A rollback is an operation that restores the database to its previous state before the transaction began. It is typically triggered when an error occurs or when the user decides to cancel the pending changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'199bfa67-5126-4895-91f4-205d8656a145', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of using object is method', N'Intern', N'Some of the applications of Object''s is method are follows, 1. It is used for comparison of two strings. 2. It is used for comparison of two numbers. 3. It is used for comparing the polarity of two numbers. 4. It is used for comparison of two objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fb9ff9e-48b3-40cf-89d2-205e1f49a32e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a service worker?', N'Intern', N'A Service worker is basically a JavaScript file that runs in background, separate from a web page and provide features that don''t need a web page or user interaction. Some of the major features of service workers are * Offline first web application development * Periodic background syncs, push notifications * Intercept and handle network requests * Programmatically managing a cache of responses Lifecycle of a Service Worker It consists of the following phases: * Download * Installation * Activation Registering a Service Worker To register a service worker we first check if the browser supports it and then register it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'534e81f6-0dff-4e82-8fe6-206094afb23d', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the role of ''Guards'' in an Angular application, and why should they be used for authorization rather than just UI state?', N'Senior', N'Guards provide a declarative way to control navigation based on conditions, such as user roles or authentication status, preventing unauthorized users from even loading a component. Relying on them for authorization is a security best practice because it prevents the client-side code for a restricted feature from ever being executed or displayed, which is more robust than hiding UI elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d0998f7-521a-43ce-ba32-2060be11db06', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are smart pointers?', N'Junior', N'Smart pointers are data structures that act like pointers but have additional metadata and capabilities. Examples like Box, Rc, and Arc manage memory automatically and provide features like heap allocation or reference counting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c5c9058-9c1a-46ae-a77d-2060f85477bc', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is a circuit breaker pattern and why is it useful?', N'Middle', N'The circuit breaker pattern prevents an application from repeatedly trying to execute an operation that is likely to fail, such as calling an unresponsive service. It helps maintain system stability by failing fast and providing a fallback mechanism until the downstream service recovers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2684691-3b7b-47d8-897f-206216af941b', N'075b8862-431c-4678-9767-f55359758a4a', N'What are navigation guards in vue router?', N'Intern', N'The navigation guards of vue-router are used to protect navigations either by redirecting it or canceling it. Below are the 3 different ways to hook into router navigations 1. Global: 2. Per-route: 3. In-component:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f543ed5d-a404-45db-b8f9-20623458847e', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If you are stuck on a problem for several hours, what steps do you take?', N'Junior', N'After a reasonable amount of time, I step away to clear my head to gain a fresh perspective. If I am still stuck, I review the documentation and logs again to ensure I haven''t missed any fundamental details. Finally, I reach out to a team member for a quick pair-programming session or to talk through my logic to spot errors I might have overlooked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd671a246-05df-4f09-ace2-206364a763ac', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Why is it important to design APIs with ''Developer Experience'' (DX) in mind?', N'Middle', N'Good DX, characterized by clear documentation, intuitive endpoint naming, and consistent error handling, accelerates adoption and reduces integration errors. It lowers the barrier to entry for third-party developers, leading to higher usage and better maintenance of the API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd3d6f4b-08ce-4b14-870f-206a1aeae70f', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do I access a module written in Python from C?', N'Fresher', N'You can get a pointer to the module object as follows: module = PyImport_ImportModule(""); If the module hasn''t been imported yet (i.e. it is not yet present in sys.modules), this initializes the module; otherwise it simply returns the value of sys.modules[""]. Note that it doesn''t enter the module into any namespace -- it only ensures it has been initialized and is stored in sys.modules. You can then access the module''s attributes (i.e. any name defined in the module) as follows: attr = PyObject_GetAttrString(module, ""); Calling PyObject_SetAttrString() to assign to variables in the module also works.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9363d280-7d4d-4fb8-86b5-207138880bc6', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between a Flask ''Blueprint'' and a standard Python module?', N'Middle', N'A Blueprint is a Flask-specific object that allows you to organize your application into distinct components with their own routes, templates, and static files. Unlike a simple module, a Blueprint registers its contents with the application instance, enabling a modular architecture that is easier to maintain and scale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f447e764-c589-4033-88d5-20726789e701', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does Sass nesting work and what is a best practice regarding it?', N'Junior', N'Nesting allows you to write CSS selectors in a way that follows the visual hierarchy of your HTML. A best practice is to avoid nesting too deeply, as it can lead to overly specific CSS selectors that are hard to override and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e2132f2-0468-4ede-a466-207269837ef0', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the relationship between Axum and Tower?', N'Intern', N'Axum is built on the Tower library, which defines the ''Service'' trait as a fundamental abstraction for processing requests. By using Tower, Axum allows developers to use various middleware and utilities that are compatible with the broader Rust web ecosystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83e6b55c-bd40-457b-a70d-2073ff12e95a', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the role of signals in SolidJS?', N'Junior', N'Signals are the fundamental building blocks of state in SolidJS. They hold a value and provide a getter and setter, allowing the framework to track dependencies and update only the parts of the DOM that specifically reference that signal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
