INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5aec32b-0a5d-49a7-9410-20761231c971', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony handle different environments like dev, test, and prod?', N'Middle', N'Symfony uses environment-specific configuration files to adjust settings like debug mode, logging levels, and cache settings. The framework automatically loads the correct configuration based on the APP_ENV environment variable, ensuring that the application behavior is optimized for the specific context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
