INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d31fc3a-b77f-4547-afe1-207ebc0215a6', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is a ''Guard'' in Litestar, and when is it typically used?', N'Junior', N'A Guard is a callable that checks if a request should be processed based on specific conditions, such as authentication status or user roles. Guards act as an early filter, allowing you to reject unauthorized requests before they reach your main logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42cdb848-a30c-4be2-99be-207f7a679c61', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does the ''Pin'' type ensure memory safety for self-referential structures?', N'Senior', N'Certain structures, such as asynchronous futures, might contain internal pointers that reference their own fields. ''Pin'' ensures that these structures are not moved in memory after they have been created, which prevents those internal pointers from becoming invalid.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63fe5cae-f815-4ea4-bd19-2080d4bc67a2', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why is the use of ''eval'' generally considered an architectural anti-pattern in high-scale PHP applications?', N'Senior', N'The ''eval'' function bypasses the opcode cache, as it requires the engine to parse and compile string-based code at runtime. It also introduces critical security vulnerabilities related to code injection and makes static analysis of the codebase impossible for modern CI/CD tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
