INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd332ba56-7b6a-4f33-8493-2087283ff8c2', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you handle API versioning, and what are the pros and cons of each approach?', N'Middle', N'Versioning can be handled via URI paths, custom headers, or media type negotiation. URI versioning is the most visible and easiest to cache, while header or content-negotiation versioning keeps URLs clean but can complicate infrastructure like load balancers and proxies that do not inspect custom headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
