INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39776005-3294-46f9-8d27-208e0fec7e97', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a ''Deadlock'' in a database environment?', N'Middle', N'A deadlock occurs when two or more transactions are waiting for locks held by each other, creating a circular dependency. The database management system must detect these cycles and abort one of the transactions to allow the others to proceed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
