INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b36c0a10-5101-4a24-ac24-209985e3ad61', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the concept of ''Bloat'' in PostgreSQL tables.', N'Middle', N'Bloat occurs when updates or deletions leave behind dead tuples that have not been cleaned up by the autovacuum process. This increases the table size on disk, forcing the database to scan more pages during queries and leading to decreased performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08ec5f23-c04a-4f1b-bf0c-209df8f45579', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack handle different JavaScript versions?', N'Middle', N'Webpack does not natively transpile modern JavaScript; it relies on loaders like babel-loader to process code. These loaders interface with tools like Babel, which convert newer ECMAScript syntax into older, browser-compatible versions based on your specific browser support requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fffa57dc-c099-44a5-b47b-20a13d6c8e8f', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is ''Request Buffering'' and why might you disable it?', N'Middle', N'Request buffering stores the entire request body in memory or disk before processing. You might disable it for large file uploads or streaming scenarios to reduce memory consumption and latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8c2f1d9-dbb6-4e86-af18-20a2a0ea4244', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the primary trade-off when using Alpine.js for large-scale enterprise applications?', N'Middle', N'The main trade-off is the lack of strict structure and modularity found in larger frameworks, which can lead to maintainability challenges as the codebase grows. While it excels at small to medium interactivity, large applications may suffer from logic fragmentation due to the lack of enforced component boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2847f5ed-a937-4b69-8031-20a54e6823e2', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the purpose of the normalization process in SQL?', N'Junior', N'Normalization is the process of organizing data in a database to reduce redundancy and improve data integrity. It involves dividing large tables into smaller, related tables and defining relationships between them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'808a7f9a-6dfc-4ba9-b567-20a6b6e6af04', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What role does intuition play in professional estimation?', N'Intern', N'Intuition is a useful starting point based on past experience, but it should never be the final answer. It is best used to generate a hypothesis that is then rigorously tested and validated through data, logical decomposition, and systematic analysis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7001b1f8-6c54-4078-81ac-20a6d624b6c2', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Is chi a full-featured web framework like Django or Rails?', N'Junior', N'No, chi is a lightweight router, not a full-featured framework. It focuses specifically on routing and middleware, leaving other concerns like database ORMs, template rendering, and session management to other packages or the standard library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88e249c9-85e7-4dee-8587-20a71f22e123', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the ''important'' modifier in Tailwind?', N'Intern', N'The important modifier adds an exclamation mark to a class to force it to have higher CSS specificity. It is used to ensure a specific utility style overrides any conflicting styles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ee77b5a-514d-4083-b340-20a972731559', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you confirm that you have truly solved a problem?', N'Intern', N'I test the solution against the initial requirements and edge cases to ensure it behaves as expected under different conditions. If the outcome consistently matches the success criteria, the problem is solved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf8caf53-3ba2-4375-bfc2-20aade2a0f68', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If a system stops working after a recent update, what is your troubleshooting approach?', N'Intern', N'The most logical approach is to identify the specific changes made in the latest update. By comparing the system''s state before and after the update, you can isolate the introduced variables that likely caused the regression.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20c5f383-2101-4e1d-b575-20ab12c117f2', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What steps do you take when you encounter a bug you cannot solve after an hour?', N'Fresher', N'I step back to re-evaluate my assumptions and check if I missed any documentation or error logs. If still stuck, I prepare a summary of what I have tried so far and ask a senior team member for a quick review to gain a fresh perspective.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ccf6869-4359-4800-83d4-20af20855c69', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the purpose of a log file in a production environment?', N'Intern', N'Log files serve as a chronological record of system events, errors, and warnings that occur during application runtime. They provide visibility into what the system was doing at the exact moment a failure occurred, which is crucial for post-mortem analysis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e39bf100-788d-45ff-bcee-20b00247a539', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are some pitfalls about using context in React?', N'Intern', N'Context in React is convenient but easy to misuse. The biggest pitfalls are passing a fresh object/array as the provider value on every render (which forces every consumer to re-render), assuming React.memo will stop context-driven re-renders (it won''t), and reaching for context as a general-purpose state manager. For frequently-changing or independent slices of state, split context into multiple providers, memoize the value, or use a dedicated state library like Redux, Zustand, or Jotai. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'939b413a-9ec0-4ef6-95b6-20b20fbc0bf9', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the purpose of the DynamoDB Streams feature in an event-driven architecture?', N'Senior', N'DynamoDB Streams captures a time-ordered sequence of item-level modifications, allowing downstream services to react to changes. It is commonly used for cross-region replication, real-time analytics, or triggering serverless functions for asynchronous processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0af087c-e8fd-4afb-93a4-20b34e47ec8a', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Are Fiber handlers thread-safe?', N'Fresher', N'Fiber handles each request in a separate goroutine, which is the Go standard for concurrency. Developers must ensure that any shared state accessed by handlers is protected by synchronization primitives like mutexes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e735434f-20c5-4128-b978-20b4fbe2b680', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the ''c.Abort()'' method used for?', N'Junior', N'c.Abort() is used to stop the execution of the middleware chain for the current request. It is typically called when a validation or authentication check fails, preventing the main handler from being reached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bf84244-e9cc-499a-92ba-20b69db41d91', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the difference between a relational database and a non-relational database?', N'Intern', N'A relational database stores data in structured tables with predefined relationships, which is ideal for complex queries and maintaining data consistency. A non-relational database is more flexible, storing data in formats like documents or key-value pairs, which is better for handling unstructured data or rapid scaling. The choice depends on whether your data needs a strict schema or requires high speed for dynamic data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17304f50-227c-4a90-9748-20b733d50297', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are Tracked Properties?', N'Fresher', N'Tracked properties are a mechanism in modern Ember used to signal the framework that a specific piece of data has changed. When a tracked property is modified, Ember automatically re-renders the parts of the UI that depend on that value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe484725-8a59-4025-a297-20b9aa4a3dc9', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS utilize the IoC container to manage dependency injection compared to traditional framework patterns?', N'Senior', N'AdonisJS uses a centralized IoC container that handles automatic dependency resolution through reflection or provider registration. Unlike standard frameworks that might rely on service locators, Adonis ensures that dependencies are resolved lazily, promoting modularity and decoupling components while maintaining a strict lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4728ebfa-b990-41b8-b3bd-20bb3a9cfe91', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between self:: and $this->?', N'Junior', N'$this refers to the current instance of an object and is used to access instance properties or methods. self refers to the current class itself and is used to access static properties or methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c96cf9ca-3401-4ed7-a414-20bc25d5c30c', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is FastAPI and what is its primary purpose?', N'Fresher', N'FastAPI is a modern, high-performance web framework for building APIs with Python based on standard Python type hints. Its primary purpose is to allow developers to build robust, production-ready web services quickly while ensuring excellent performance comparable to Node.js and Go.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
