INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b7bf293-bee4-4bfb-9b82-20c15508eff2', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between Flask and Django?', N'Fresher', N'Flask is a micro-framework that offers flexibility and minimal features, requiring developers to choose their own libraries for tasks like database management. Django is a full-stack framework that comes with ''batteries included,'' providing built-in tools for authentication, database ORM, and admin interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab9429d0-6df1-4a57-a8f2-20c1dc42917c', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How would you approach a bug that only happens intermittently?', N'Junior', N'I would look for patterns in the timing, user behavior, or environmental factors that correlate with the failures. I would also increase logging verbosity during the suspected timeframe to capture more granular data about the application state when the intermittent error occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
