INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f342877-9c1f-46b2-9d4e-20c36c2c466b', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are ''Refs'' used for in Preact?', N'Junior', N'Refs allow you to access DOM nodes directly or store mutable values that persist across renders without triggering a re-render. They are typically used for managing focus, text selection, or integrating with non-Preact libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bae13ce8-8a26-4939-8794-20cfe5c555a8', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How does user feedback play a role in the debugging process?', N'Intern', N'User feedback often provides the initial trigger for an investigation, including specific behaviors or error messages that developers might have missed. It helps bridge the gap between the intended design and the actual user experience in real-world scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6082f806-5622-4df0-896c-20cfedf90e42', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How to get query string values in javascript?', N'Fresher', N'The URLSearchParams() provides an interface to work with query string parameters. The has() method of the URLSearchParams() determines if a parameter with a specified name exists. Example: URLSearchParams() The URLSearchParams() methods: * keys() returns an iterator that iterates over the parameter keys. * values() returns an iterator that iterates over the parameter values. * entries() returns an iterator that iterates over the (key, value) pairs of the parameters. Example: keys() Example: values() Example: entries() &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7927bf3f-69a6-4c21-990b-20d24566175d', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the importance of checking error logs for timestamp accuracy?', N'Intern', N'Synchronized timestamps allow you to correlate events across different services or servers. If logs are not synced, it becomes nearly impossible to determine the order of operations and establish a clear cause-and-effect timeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a743f23f-5b85-42a6-a872-20d3d616f70a', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the trade-off of ''Eventual Consistency'' in microservices?', N'Senior', N'Eventual consistency sacrifices immediate data accuracy for higher availability and partition tolerance. It requires the business and UI to be designed to handle potentially stale data or temporary inconsistencies while updates propagate through the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'185e0f5f-171c-4ef7-9894-20d68c0c507d', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What does ''Hot Reloading'' mean in the context of Phoenix development?', N'Junior', N'Hot reloading, specifically via the Phoenix LiveReload feature, automatically refreshes the browser whenever code changes are saved. This significantly speeds up the development process by allowing developers to see updates instantly without manually restarting the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c98cce58-d8de-4c77-a2e8-20d8ccf4a392', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What does the ''conn'' variable represent in Phoenix controllers?', N'Intern', N'The ''conn'' is a struct that represents the connection between the client and the server. It contains all information about the request and is used to build the response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e008f14-4fcb-47ee-bad8-20d928a6c6b3', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is variable shadowing in javascript?', N'Intern', N'Variable shadowing occurs when a variable declared within a certain scope (decision block, method, or inner class) has the same name as a variable declared in an outer scope. This outer variable is said to be shadowed. If there is a variable in the global scope, and you''d like to create a variable with the same name in a function. The variable in the inner scope will temporarily shadow the variable in the outer scope. Example: Block-level shadowing (let/const): var does NOT shadow at block level (only at function level): Nested function shadowing: Note: - Shadowing does not modify the outer variable - let/const shadow at block level; var only at function level - Can cause bugs when unintentional — use distinct variable names to avoid confusion', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f69567f0-e873-4d44-8a4c-20dd35db4316', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the impact of sequence points on the evaluation of expressions with side effects?', N'Senior', N'Sequence points define the boundary at which all side effects of previous evaluations are guaranteed to be complete. Between sequence points, the order of evaluation is largely unspecified, meaning expressions with multiple side effects on the same variable can lead to undefined behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2497140e-28a3-4a68-b2f2-20ddf314a349', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the difference between a clustered and non-clustered index?', N'Middle', N'A clustered index determines the physical order of data in the table, meaning a table can have only one. A non-clustered index is a separate structure that stores pointers to the actual data rows, allowing for multiple such indexes per table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31ac84c1-874d-454f-ac90-20df002c29e2', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a pointer in C++?', N'Intern', N'A pointer is a variable that stores the memory address of another variable rather than a direct value. Pointers allow for dynamic memory management and efficient passing of large data structures between different parts of a program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e716042b-b074-4e1a-9470-20df7c1615f1', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What are the limitations of jQuery''s deferred object compared to native JavaScript Promises?', N'Middle', N'jQuery''s Deferred object does not fully adhere to the Promises/A+ specification, which can lead to inconsistencies when interoperating with modern async/await patterns. Native Promises are faster, standard-compliant, and provide better error handling capabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f442f92-5f17-4d1c-89fc-20e353544424', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are the trade-offs of using ''inline'' functions in a large-scale Kotlin project?', N'Senior', N'Inlining functions reduces the overhead of functional calls and lambda object allocations, which is beneficial for performance and higher-order function ergonomics. However, excessive inlining can lead to significant code bloat in the generated bytecode and can complicate debugging, as the call stack becomes flattened and less representative of the source code structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1d19d3c-2147-42f2-a850-20e56215b437', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How do you handle distributed transactions across multiple microservices in Spring Boot?', N'Senior', N'Since standard JTA is not viable in microservices, you should use patterns like the Saga pattern or the Transactional Outbox pattern. These ensure eventual consistency by using compensating transactions or messaging to coordinate state changes across services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc73b535-d936-4ab5-884f-20e60c48074e', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between @Autowired and constructor injection?', N'Junior', N'@Autowired is used for field injection, while constructor injection uses the class constructor to provide dependencies. Constructor injection is generally preferred because it allows for immutable fields, better testability, and ensures the bean is fully initialized before use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
