INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d0ad170-4e33-426d-807f-20e9c77f382f', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'In a distributed environment, why might you need to override Django’s default file storage backend?', N'Senior', N'The default filesystem storage is tied to the local disk, which is inaccessible if the application runs across multiple containers or servers. Overriding this with a cloud-native storage backend like S3 ensures that all application instances have consistent access to the same file assets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
