INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36399884-b5ab-417b-9322-20ee26e6dc5d', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What are Named Routes and why are they useful?', N'Junior', N'Named routes allow you to assign a specific name to a route, which you can use to generate URLs or redirects throughout your application. This is beneficial because if the URL structure of your application changes, you only need to update the route definition, not every hardcoded link in your views or controllers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a2b4ec4-c517-48d6-bdd4-20ee9b4e46fa', N'075b8862-431c-4678-9767-f55359758a4a', N'How do ''Fragment'' components improve the DOM structure in Vue?', N'Senior', N'Fragments allow components to have multiple root nodes, eliminating the need for unnecessary wrapper elements that were required in Vue 2. This results in cleaner HTML output and reduces the overhead on the browser''s CSS layout engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8218e24e-e2e6-4e15-a00d-20f03967c3c2', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the difference between req.params and req.query?', N'Fresher', N'The req.params are a part of a path in URL and they''re also known as URL variables. for example, if you have the route /books/:id, then the id property will be available as req.params.id. req.params default value is an empty object {}. A req.query is a part of a URL that assigns values to specified parameters. A query string commonly includes fields added to a base URL by a Web browser or other client application, for example as part of an HTML form. A query is the last part of URL Example 01: req.params Example 02: req.query', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd5c709e-a07e-47ed-9c71-20f0afd356f6', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is scalability in database design?', N'Intern', N'Scalability refers to the ability of a database system to handle an increasing amount of work or data. Vertical scaling involves adding more power to an existing server, while horizontal scaling involves adding more servers to distribute the load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'150e6493-c34b-4348-897d-20f1482ccaa3', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the refresh interval impact system performance and near-real-time search capabilities?', N'Senior', N'The refresh interval determines how frequently the in-memory buffer is written to a new segment, making documents searchable. Shorter intervals improve near-real-time search availability but increase system overhead due to frequent segment creation and merging; longer intervals improve indexing throughput at the cost of search latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1519dddb-9965-4bdf-8c52-20f79384f1ee', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How do you define a sub-router in Chi?', N'Intern', N'A sub-router is defined by creating a new router instance and mounting it to a path on the main router. This is useful for modularizing code by domain or resource type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86e4d48e-3784-4c16-aad7-20f93b29ade7', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What are Vite plugins and why might you use them?', N'Junior', N'Vite plugins are extensions that allow you to customize the build process, such as adding support for specific file types or integrating with other tools. They use a hook-based system to tap into Vite''s internal processes during development or production builds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'037291f6-6d9a-43f7-ad88-20f9f4480d10', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Why is it difficult to achieve strict global ordering in a highly available distributed system?', N'Senior', N'Achieving global order requires a total ordering protocol, which introduces significant latency due to required synchronization across all nodes. In distributed systems, this creates a performance bottleneck that contradicts the core requirements of high availability and horizontal scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc4767e4-2cfc-467a-94db-2104156cf474', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between client-side and server-side languages?', N'Intern', N'Client-side languages run in the user''s web browser, while server-side languages run on the web server. PHP is server-side, meaning it prepares the page before it reaches the browser, whereas languages like JavaScript can manipulate the page after it has loaded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ab21c89-2488-4140-8ddb-2105cef38d3c', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do you debug React applications?', N'Fresher', N'To debug React applications, use the React Developer Tools browser extension to inspect the component tree, props/state, and rendering with the Profiler. Enable Strict Mode during development to surface unsafe patterns, and rely on React 19.1 owner stacks for clearer component-aware stack traces. Use error boundaries (or the react-error-boundary package) to catch render-time errors, and reach for console.log, breakpoints, and the React DevTools "log" button for deeper inspection. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34c41f5d-fc27-4e03-b862-21093d8fa03f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of the new keyword?', N'Intern', N'The new keyword in JavaScript is used to create an instance of a user-defined object type or one of the built-in object types that has a constructor function. When you use new, it does four things: it creates a new object, sets the prototype, binds this to the new object, and returns the new object. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0920f22e-af3b-4875-85e5-2109aba1df32', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'When should the Singleton pattern be applied and what are its drawbacks?', N'Middle', N'While the Singleton pattern offers benefits such as a single point of access and delayed instantiation, its drawbacks and potential misapplications are worth considering. Key Considerations Scope of Singleton Behavior The Singleton pattern isn''t always the most suitable for enabling unique global access. Classes managed by dependency injection (DI) frameworks, for instance, often provide more adaptable and testable mechanisms for context-driven singletons. Drawbacks of the Singleton Pattern 1. Hidden Dependencies: The use of singletons can introduce implicit and potentially unexpected dependencies. This can make the codebase more challenging to understand and debug. 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da2c8235-2e17-49fd-b6eb-210d831df21b', N'954a0331-deff-4399-b588-96f39fec001d', N'What is angular animation?', N'Intern', N'Angular''s animation system is built on CSS functionality in order to animate any property that the browser considers animatable. These properties includes positions, sizes, transforms, colors, borders etc. The Angular modules for animations are @angular/animations and @angular/platform-browser and these dependencies are automatically added to your project when you create a project using Angular CLI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b54ed589-d5d3-4753-9a95-2110af0fca18', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember’s Service-based architecture support modularity and state persistence across different routes?', N'Senior', N'Services in Ember are long-lived, singleton objects that persist for the duration of the application''s lifecycle, independent of the route hierarchy. This makes them ideal for managing global state, such as authentication sessions, user preferences, or WebSocket connections, providing a centralized point of access that decouples state from the UI component tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba498fd8-eef4-4006-9680-2113325a18e6', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are the architectural considerations when implementing rate limiting in Hono on the edge?', N'Senior', N'Because the edge is distributed, rate limiting must be handled via a global cache or database like Redis or Cloudflare KV. Relying on local memory for rate limiting is ineffective, so Hono middleware must be integrated with an external, low-latency distributed store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b71b107d-237e-4138-9c42-211672b19362', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between Use and Run in the middleware pipeline?', N'Intern', N'The Use method adds middleware that can call the next component in the pipeline, allowing for further request processing. The Run method adds a terminal middleware that does not call the next component, effectively ending the pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a264a0ca-f5a0-48bb-8cf4-211741bb12ca', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Discuss the performance trade-offs of using asynchronous I/O versus synchronous I/O in an ASP.NET Core web server.', N'Senior', N'Asynchronous I/O releases the thread back to the thread pool while waiting for external resources, significantly increasing scalability under heavy load. Synchronous I/O blocks threads, leading to thread pool starvation, which severely limits the server''s throughput and response time during high traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e11e16e-a5eb-4560-bc86-2118ee801364', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of the Laravel Service Container?', N'Intern', N'The Service Container is a powerful tool for managing class dependencies and performing dependency injection. It acts as a central registry where you can bind classes or interfaces and resolve them whenever they are needed throughout your application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
