INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'248dc703-113b-4490-b2d5-211ac66ae5ed', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the architectural significance of the ''Error Budget'' in Site Reliability Engineering?', N'Senior', N'The error budget represents the maximum amount of downtime or failure a service can tolerate within a period while still meeting its Service Level Objective. It serves as a quantitative mechanism to balance the velocity of feature releases against the need for system stability, effectively governing the release process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
