INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1132692f-e206-4286-8999-21222da18254', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the primary trade-off between using channels and using mutexes in Go?', N'Middle', N'Channels are designed for orchestrating control flow and passing ownership of data between goroutines, promoting a design based on communicating sequential processes. Mutexes are better suited for protecting shared memory state in high-contention scenarios where fine-grained locking is required to maximize performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66aa20f2-2f38-46f0-8126-21228240307c', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit manage state across page navigations?', N'Middle', N'SvelteKit uses the ''page'' store to provide reactive access to current routing information like parameters, URL data, and form state. For global application state, standard Svelte stores are typically used, as they persist across client-side navigations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd914190-aef7-4345-a485-212526bfa0cf', N'4c000000-0000-0000-0000-000000000005', N'When is it appropriate to use a cache-aside versus write-through caching strategy?', N'Senior', N'Cache-aside is more flexible and resilient, as the application controls the cache logic, but it risks stale data if not handled with expiration policies. Write-through ensures the cache and database remain perfectly synchronized at the cost of higher write latency, making it better for read-heavy workloads where data consistency is paramount.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92463624-4a1b-4c38-b23a-212bb4d7487c', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the difference between an interpreter and a compiler in the context of Ruby?', N'Intern', N'Ruby is primarily an interpreted language, meaning the source code is read and executed line-by-line by the Ruby interpreter at runtime rather than being converted into machine code beforehand. This allows for dynamic behavior and faster development cycles, though it may result in slower execution speeds compared to compiled languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b64fa60-d5e8-4c81-ab26-212c0b7af680', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the role of a Circuit Breaker in a microservices environment?', N'Middle', N'A circuit breaker prevents a system from repeatedly trying to execute an operation that is likely to fail, such as a request to a down service. It allows the system to fail fast and return a fallback response, preventing cascading failures and providing time for the downstream service to recover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b37c1a91-d051-40d8-85d7-213125a1e19e', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of a backup in a database system?', N'Intern', N'A backup is a copy of the database data used to restore the system in case of data loss, corruption, or hardware failure. It is a critical component of disaster recovery and data protection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c99de1af-a5f3-46cd-a384-2135f8230836', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin optimize memory usage for large numbers of requests?', N'Middle', N'Gin utilizes a sync.Pool to reuse context objects across requests, which reduces the overhead of garbage collection. By recycling these objects, the framework minimizes memory allocations under high concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63daf7ca-0816-43b9-b023-2138addd95de', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is it often better to favor ''Interfaces'' over ''Classes'' for defining API contracts?', N'Middle', N'Interfaces are purely for type checking and disappear after compilation, resulting in no runtime overhead. Classes define both the structure and runtime behavior, which can be unnecessary if you only need to define a data contract for communication between components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b68a4e9-1748-4a8e-a59a-213ca45bb794', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How to detect system dark mode in javascript?', N'Fresher', N'The combination of Window.matchMedia() utility method along with media query is used to check if the user has selected a dark color scheme in their operating system settings or not. The CSS media query prefers-color-scheme needs to be passed to identify system color theme. The following javascript code describes the usage, You can also watch changes to system color scheme using addEventListener, Note: The matchMedia method returns MediaQueryList object stores information from a media query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'394a0710-ee45-48fe-bf53-213cd1f18df7', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'In what scenarios would you choose a ''Prototype'' scope over a ''Singleton'' scope in Micronaut?', N'Senior', N'The Prototype scope should be used when a bean must maintain state that is unique to each injection point or when the bean is not thread-safe. While it provides isolation, it should be used sparingly as it increases object instantiation overhead and memory usage compared to the Singleton scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37193f52-02c7-4346-8d34-213ec3b8c40c', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What are ''Hydration Directives'' in Astro?', N'Junior', N'Hydration directives are special attributes applied to components that tell Astro when to load and execute the component''s JavaScript. By default, Astro components are static, so these directives are necessary to make them interactive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4fd1e7d-d4d0-439d-9096-213effd2ae70', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is meant by a zero-cost abstraction?', N'Intern', N'A zero-cost abstraction means that using high-level features does not result in worse performance than writing low-level code manually. The Rust compiler optimizes these abstractions so that they run as efficiently as if you had written the underlying machine code yourself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37edccd6-92a2-4a51-9cae-2141931b6e83', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between pass-by-value and pass-by-reference in PHP?', N'Middle', N'Pass-by-value creates a copy of the variable, meaning changes inside the function do not affect the original. Pass-by-reference passes a pointer to the original memory address, allowing the function to modify the actual variable. Using references can be more memory-efficient for large objects but can lead to side effects that make code harder to debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2edfe2dc-64ee-416a-bb1b-214523be93f2', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the ''Option'' type in Rust?', N'Intern', N'The Option type is an enum used to represent the presence or absence of a value. It is used instead of null pointers to explicitly handle cases where data might be missing, forcing the developer to account for that possibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'928dab69-baa0-4b93-82db-21465db7a8ec', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the benefits of using TypeScript with ReactJS?', N'Intern', N'Below are some of the benefits of using TypeScript with ReactJS, 1. It is possible to use latest JavaScript features 2. Use of interfaces for complex type definitions 3. IDEs such as VS Code was made for TypeScript 4. Avoid bugs with the ease of readability and Validation', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39024ece-d1fb-47b0-98ea-214899275106', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How are database relations handled in Lucid?', N'Fresher', N'Lucid uses relationship methods inside models to define how tables interact with each other. It supports standard types like One-to-One, One-to-Many, and Many-to-Many, allowing for easy data retrieval through linked models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'656b0e94-71bb-491b-87d3-214fc41b04c7', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What does Sass nesting do to your CSS?', N'Junior', N'Nesting allows you to write CSS selectors in a way that follows the visual hierarchy of your HTML. While it makes code look cleaner, you should avoid deep nesting to prevent overly specific selectors that are hard to override.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e6a3aba-7b6f-4095-9bc1-2152e333b05c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it important to use environment variables instead of hardcoding API keys or database passwords?', N'Fresher', N'Hardcoding sensitive information makes it vulnerable to being exposed if the source code is ever shared or uploaded to a repository. Using environment variables keeps sensitive credentials separate from the application logic, allowing for better security and easier configuration across different environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c5b12d4-3193-4117-8e0e-215361082a3c', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Discuss the advantages of using AdonisJS''s provider-based architecture for plugin development.', N'Senior', N'Provider-based architecture allows third-party plugins to hook into the application boot process, register services, and inject dependencies seamlessly. This modular approach ensures that plugins do not interfere with core framework logic and can be easily toggled, updated, or removed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d1c94cb-0b1f-4633-8f5a-21581f53783f', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of Django Middleware?', N'Intern', N'Middleware is a framework of hooks that process requests and responses globally. It sits between the server and the view, allowing you to perform actions like authentication, session management, or logging on every incoming request before it reaches the view.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c15466b-2fdf-4784-8b1a-2158a4b5777f', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Describe how to handle bulk operations in a RESTful API.', N'Senior', N'Bulk operations can be handled by providing an endpoint that accepts an array of resources or by creating a batch job resource. For large sets, it is better to treat the bulk request as a job that runs asynchronously, providing a reference to track completion status to avoid blocking the HTTP request-response cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e206ac97-9ee6-4709-b387-215ac7ed8a7f', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How do you handle file uploads efficiently in Fiber?', N'Middle', N'Fiber provides methods to access multipart form data, which can be used to stream file uploads directly to storage or process them in memory. For large files, it is recommended to stream the input directly to avoid loading the entire file into RAM, which could crash the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba09b879-1407-4f8e-9500-215b5c5edf4e', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the purpose of the ''build'' command in Vite?', N'Junior', N'The build command prepares the application for production by bundling, minifying, and optimizing the code. It uses Rollup under the hood to ensure the final output is highly optimized and compatible with modern browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c0198d6-a934-417e-961e-215b8cbb5e7d', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How to improve Node.js performance?', N'Fresher', N'1. Asynchronous Functions: Using asynchronous functions in an application that heavily uses I/O operations will improve it. This is because the CPU will be able to handle multiple requests simultaneously due to non-blocking I/O, while one of these requests is making an Input/Output operation. Example: 2. Query Optimization: Basic tips to improve your database performance/optimization overview * Indexing - Indexing is an approach to optimize the performance of a database by minimizing the number of disk accesses required when a query is processed. * Avoid SELECT - Use the SELECT statement to query only the data you need and avoid extra fetching loads to your database. * Use LIMIT - LIMIT will return only the specified number of records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
