INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e7ea3c4-19c3-4ed3-8281-216582c59d72', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Can an actor send a message to itself?', N'Junior', N'Yes, an actor can send messages to its own address. This is a standard way to schedule internal tasks or defer operations to be processed later in the actor''s event loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
