INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2035080-fab6-456b-a074-2171a24fbb89', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Explain the concept of ''stackful'' versus ''stackless'' fibers.', N'Middle', N'Stackful fibers maintain their own execution stack, allowing them to be suspended from anywhere, including deep inside function calls. Stackless fibers, often implemented as state machines, only allow suspension at the top level, which is generally more memory-efficient but more restrictive to write.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c1c939f-826a-481f-85c1-2175fe11bd32', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the benefit of non-blocking I/O?', N'Intern', N'Non-blocking I/O allows a single thread to handle multiple concurrent connections without waiting for each one to finish. This makes Node.js highly efficient for I/O-intensive applications like chat apps or real-time streaming.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
