INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd16241be-b184-4f53-9e3e-217c1e8cdaf5', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between ''find'' and ''find_by'' in Active Record?', N'Junior', N'The ''find'' method searches by primary key (ID) and raises an error if the record is not found. The ''find_by'' method allows you to search by any attribute and returns ''nil'' if no matching record is found.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5675a3fc-d778-41a6-a49c-217c3f7ed0c0', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are associations in Active Record?', N'Intern', N'Associations are declarations that define the relationship between two models, such as belongs_to, has_many, or has_one. They allow Rails to easily fetch related data and manage dependencies between different database tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c95d24b-891d-42b9-a996-217e5cea83ac', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do async generators and for await...of enable streaming data processing?', N'Fresher', N'An async generator (async function*) is a function that produces values asynchronously via yield. Each yield pauses execution until the consumer calls .next(), which returns Promise . for await...of is the idiomatic consumer — it automatically awaits each .next() call, making streaming processing look synchronous. This pattern enables lazy, backpressure-aware pipelines: data is produced and consumed one chunk at a time rather than loading an entire dataset into memory. Example: Real-World Use Case: Node.js 18+ natively supports async iteration over fetch response bodies: for await (const chunk of response.body). AWS S3 SDK v3 returns async iterables for ListObjectsV2Command pagination.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b04c4f6-f099-470a-ac4c-217f07019735', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the benefit of using Gin''s Bind method?', N'Intern', N'The Bind method simplifies the process of decoding request data into a Go struct. It automatically handles validation and error reporting based on tags defined in the struct fields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'112674a9-407c-4aea-94bc-217f3aab96a1', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you manage your time when you have multiple tasks due at once?', N'Fresher', N'I prioritize tasks based on their urgency and impact on the overall project. I then break each task into smaller pieces and focus on completing them one by one to avoid losing focus due to multitasking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19cc8c79-a511-4044-bd11-217fb88a9f4d', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the role of the ''initialize'' method?', N'Junior', N'The initialize method is a special constructor method that runs automatically when a new instance of a class is created. It is typically used to set up initial state or assign values to instance variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7f88cfe-07eb-44cf-8df5-21816ca908bb', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Can Redis handle multiple clients simultaneously?', N'Fresher', N'Yes, Redis is designed to be highly concurrent. It uses a single-threaded event loop to handle multiple client connections efficiently without the need for complex locking mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd28278e-4ef4-44df-965b-2183357faa14', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro''s ''Islands Architecture'' improve performance?', N'Middle', N'By isolating interactive UI components into ''islands,'' Astro allows the rest of the page to remain static HTML. This reduces the amount of JavaScript the browser needs to download, parse, and execute, leading to faster Time to Interactive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77f8d44a-d119-490d-97fc-218347c52e4d', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of a partitioner in Cassandra?', N'Middle', N'A partitioner is a strategy that determines how data is distributed across the nodes in the cluster. It converts the partition key into a token, which dictates the node responsible for that data based on the cluster''s token ring structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48cc71af-816a-4486-8e89-218368cf929b', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the risk of having too many partitions in a distributed message log?', N'Senior', N'Each partition consumes system resources like file handles and memory on the broker. Excessive partitioning can lead to increased metadata overhead, longer recovery times after failure, and reduced efficiency in batching data transfers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c16edec9-bcd4-4465-af83-218477e3a60b', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Describe the difference between bounded staleness and eventual consistency in MongoDB read preferences.', N'Senior', N'Eventual consistency allows reads from secondaries that may lag behind the primary without a time limit. Bounded staleness, often achieved through ''maxStalenessSeconds'', limits the acceptable lag of a secondary, ensuring the data returned is not older than a specific threshold.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d000e4e-833f-4b9f-a011-218bde647b28', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Explain the role of the ''onDestroy'' lifecycle hook.', N'Junior', N'The ''onDestroy'' hook is used to perform cleanup tasks when a component is removed from the DOM. This is essential for preventing memory leaks, such as clearing intervals, timeouts, or removing event listeners.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e85e78e-4134-43b1-a65e-218bdfa514c6', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind CSS approach component reusability?', N'Middle', N'Tailwind encourages component reusability by leveraging the underlying framework''s component model, such as React, Vue, or Svelte components. Instead of creating CSS classes for buttons, you create a reusable UI component that encapsulates the necessary utility classes, keeping styling logic local to the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5062ef6-a28a-42c6-a0f4-218cc71b7564', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When an application crashes with an ''Out of Memory'' error, what is the first thing you look for?', N'Middle', N'I would check the system logs for the exact stack trace and memory usage patterns leading up to the crash, such as sudden spikes versus gradual growth. I would also investigate recent deployments or configuration changes to see if memory limits were adjusted or if new code introduced a high-memory operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59be5a14-d6fb-488a-8bc2-218ea12bcbb7', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is a +layout.server.ts file?', N'Intern', N'This file is used to fetch data that is required for a layout and all its child pages. The loaded data is available to both the layout component and any nested pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9afa8bb-4f7e-4028-97d5-218f023116b7', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How are assets like images managed in Qwik?', N'Junior', N'Qwik provides built-in components and utilities to optimize image loading, such as lazy loading. These utilities help ensure that assets do not block the initial page render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'567f7c3f-d21a-4c90-83f0-21956b4aeb6c', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Explain the role of the Partition Key and Sort Key in DynamoDB''s physical storage layout.', N'Senior', N'The Partition Key determines the physical partition where the item resides, while the Sort Key allows for range queries within that partition. Together, they form a composite primary key that uniquely identifies items and enables efficient data organization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0643240b-2b52-42d0-b7b9-2198fa386fed', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the main limitation of storing all data in RAM?', N'Fresher', N'The main limitation is the cost and capacity of RAM compared to disk storage. It is much more expensive to store large amounts of data in memory than on a hard drive or SSD.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'072840fb-ae34-4f4f-ac69-219affa19c5a', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the difference between ''make'' and ''new'' in Go.', N'Junior', N'The ''new'' function allocates memory for a type and returns a pointer to its zero value. In contrast, ''make'' is used exclusively for initializing slices, maps, and channels, returning the initialized object itself rather than a pointer, as these types require internal data structure setup before use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'198cabce-01d4-4268-a662-219c46c84d88', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What does it mean to ''isolate the environment'' when troubleshooting?', N'Intern', N'Isolating the environment means removing or disabling external connections, services, or configurations that are not strictly necessary for the process you are testing. This helps ensure that the behavior you are seeing is caused by the component in question and not by an external dependency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9e04bd3-6c67-4128-8a19-219cfafcc979', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle route parameters, and what is the benefit?', N'Middle', N'Gin extracts route parameters directly from the URL path during the radix tree traversal process. This is highly efficient because the parameters are identified while the route is being matched, rather than needing a secondary regex pass over the URL string.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4a7e1b1-d0bf-4a9c-ad39-219d35e99e21', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the browser rendering pipeline, and what triggers a reflow vs. a repaint?', N'Intern', N'The browser rendering pipeline is the sequential process a browser engine follows to convert HTML, CSS, and JavaScript source code into actual pixels on a physical screen The Rendering Pipeline Steps Reflow (Layout): Recalculation of element geometry. Triggered by any change that affects the size or position of elements. It is expensive because it may cascade — changing one element''s size can force recalculation of its entire subtree and ancestors. Repaint: Redrawing pixels where geometry has not changed but visual appearance has (colour, opacity, visibility). Less expensive than reflow but still non-trivial. Compositing only: The cheapest operation — moving or animating a composited layer (using transform or opacity) without triggering layout or paint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da61536a-ca3d-4a44-8747-21a32a888af5', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What architectural challenges arise when integrating R with low-latency systems?', N'Senior', N'The primary challenge is the latency induced by garbage collection and the copy-on-modify behavior, which can cause non-deterministic pauses. Integrating R into low-latency pipelines typically requires moving the heavy lifting into compiled C++ code and keeping R as an interface layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2aa7b24-5838-44d6-b880-21a529d08f1c', N'075b8862-431c-4678-9767-f55359758a4a', N'Can I use strict mode in production environment?', N'Senior', N'No, it is not recommended to use strict mode in production environment. Strict mode runs a synchronous deep watcher on the state tree for detecting inappropriate mutations and it can be quite expensive when you perform large amount of mutations. i.e, It can impact performance if you enable in production mode. Hence, it should be handled through build tools,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05f7f9f6-9ebb-4633-b49e-21a71e2ea70f', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you choose between using an ORM and writing raw SQL queries?', N'Middle', N'An ORM increases developer productivity and helps maintain consistent data models, but it can obscure query performance and generate inefficient SQL. Writing raw SQL allows for fine-tuned performance optimization and full control over database-specific features, but it is harder to maintain and less portable across different database engines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1152efa9-af20-4230-b5bd-21a86e59aa87', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle a situation where you are given a task with no clear deadline?', N'Intern', N'I would first ask my manager about the priority of the task relative to my other responsibilities. If it is not immediately clear, I would propose a reasonable timeline for completion and ask for confirmation to ensure my expectations align with the team''s needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6755d612-5475-4123-b8f1-21aafbcbe3d9', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you estimate the number of tennis balls that can fit into a Boeing 747?', N'Fresher', N'I would approach this by estimating the volume of the aircraft interior and the volume of a single tennis ball. I would account for the packing efficiency, acknowledging that balls cannot fill every corner perfectly due to their spherical shape, and then divide the total usable volume by the volume of one ball.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69155f45-7373-4472-919e-21ab43f1f4ce', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How can you implement ordering guarantees in a distributed messaging system?', N'Middle', N'Ordering is typically guaranteed only within a single partition or shard by ensuring all messages with the same correlation key are sent to the same partition. This forces sequential processing for those specific messages, though it limits the ability to scale processing horizontally for that key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff347ad2-d91d-4471-ad53-21af7606ca51', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of the Controller in Ember?', N'Intern', N'The Controller holds the state of the application''s view, such as form inputs or UI-specific flags. While modern Ember relies more on components, controllers are still used to manage state that persists across different transitions within a route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd11e8786-0e8a-440b-8b55-21b3b8e4adf6', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Does Next.js support CSS modules?', N'Intern', N'Yes, Next.js has built-in support for CSS modules. This allows you to write scoped CSS for individual components, which prevents class name collisions and helps keep your styles organized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9be40d7a-fb54-4184-85dd-21b5b9af1a92', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do ''Symbols'' contribute to private property implementation?', N'Senior', N'Symbols provide unique, non-enumerable keys that cannot be guessed or accessed through standard iteration methods like Object.keys. This makes them useful for defining internal or ''hidden'' properties on objects that shouldn''t be exposed during public usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53445bc3-f9a7-4cc5-8d78-21ba1c1de981', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro handle environment variables on the server versus the client?', N'Senior', N'Astro strictly separates environment variables: those prefixed with PUBLIC_ are exposed to the client, while others are kept server-side only. This prevents sensitive data like API keys from leaking into the browser bundle during the build or runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7537a8c-8d76-4f23-a714-21ba42775b71', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the ''System'' in the context of Actix actors?', N'Middle', N'The System is the central registry and manager for the actor runtime. It provides the event loop, handles the lifecycle of actors, and manages signal processing, acting as the foundation for the entire actor system to execute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'898d8a2d-a607-4db6-a1ea-21bc2af261f5', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is pattern matching in Rust?', N'Intern', N'Pattern matching is a control flow construct that compares a value against a series of patterns and executes code based on the first one that matches. It is highly expressive and ensures that all possible cases for a data structure are handled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26dedfc1-df20-4d50-9345-21bd42fed047', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the ''client:visible'' directive used for?', N'Fresher', N'The ''client:visible'' directive delays the hydration of a component until it enters the user''s viewport. This is an efficient way to load heavy interactive components only when they are actually needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a371224d-a36b-466a-83de-21be2bdb22d7', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is Hot Reload in Quarkus and how does it assist developers?', N'Fresher', N'Hot Reload is a developer productivity feature that allows you to modify your code and see the changes immediately without restarting the application. When you save a file, Quarkus automatically recompiles the necessary parts and updates the running application in the background.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9037f74a-9ddb-4c9e-8af0-21be63d1183f', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Why might you prefer a list comprehension over a standard loop?', N'Middle', N'List comprehensions are generally faster because they are executed at C-speed within the interpreter and are more concise. However, if the logic is complex or requires multiple steps, a traditional loop is often preferred for readability and maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aeea32c8-d10a-443b-af64-21be82a24ee6', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is PostgreSQL''s MVCC?', N'Intern', N'MVCC stands for Multi-Version Concurrency Control. It allows multiple users to access the database simultaneously without blocking each other by keeping multiple versions of data rows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a8dcf85-1d01-478a-8f84-21c36ebf72e8', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the danger of leaking internal stack traces in an Express production environment?', N'Senior', N'Exposing stack traces provides attackers with internal file paths, module versions, and code structure information, significantly lowering the difficulty of crafting an exploit. Always use generic error responses in production and log detailed traces only to a secure, private logging service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb5b03ff-7809-460e-8be0-21c79a7ddf57', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Compare the impact of Astro''s zero-JS-by-default philosophy on Core Web Vitals versus a Next.js approach.', N'Senior', N'Astro''s zero-JS-by-default approach results in significantly smaller bundle sizes for static sites, directly improving Largest Contentful Paint and Total Blocking Time. Next.js, while highly optimized, generally ships more runtime framework code to support its hydration model, which can lead to higher baseline JavaScript costs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74ef802e-c718-4ff7-b02a-21c947f3b137', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Compare LRU and LFU eviction policies in the context of a high-concurrency microservices architecture.', N'Senior', N'LRU (Least Recently Used) is generally efficient for workloads with temporal locality but can be prone to cache pollution by one-time scans. LFU (Least Frequently Used) tracks access frequency, making it better for workloads with stable popularity, but it requires more metadata and struggles to adapt if access patterns shift rapidly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c444c0d9-bb02-47f2-bbfb-21caff98c060', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How to create a simple server in Node.js that returns Hello World?', N'Fresher', N'Step 01: Create a project directory Step 02: Initialize project and link it to npm This creates a package.json file in your myapp folder. The file contains references for all npm packages you have downloaded to your project. The command will prompt you to enter a number of things. You can enter your way through all of them EXCEPT this one: Rename this to: Step 03: Install Express in the myapp directory Step 04: app.js Step 05: Run the app &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea781a8c-ba5e-4f8f-8599-21cca1297538', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What steps do you take to ensure the security of a CI/CD pipeline?', N'Senior', N'I implement automated security scanning for dependencies and code, enforce strict access controls for the pipeline, and ensure that all build artifacts are signed and verified. I treat the pipeline itself as infrastructure-as-code, subjecting it to the same auditing and review processes as product code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f54d767a-ce95-43c1-a380-21cd3b551482', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Explain the benefit of ''Layouts'' in the App Router compared to the nested layout patterns in the Pages Router.', N'Senior', N'Layouts allow components to persist across route transitions, preventing unnecessary re-renders of the UI shell. This architecture enables state preservation and smoother transitions, whereas the Pages Router often required duplicating layout logic or using complex _app.js wrappers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7dd79e85-7f5e-4080-ae7e-21cda42f1524', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the advantage of Remix being built on top of Web Fetch API?', N'Middle', N'By using the standard Web Fetch API, Remix code becomes highly portable and compatible with various runtime environments like Cloudflare Workers, Node.js, or Deno. This standard-based approach ensures that developers are working with web platform primitives rather than framework-specific abstractions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9bc439e-88b6-4e66-8bcc-21cdaf8bec12', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are components in Preact?', N'Intern', N'Components are the building blocks of a Preact application, representing reusable, independent pieces of the user interface. They can be defined as either functions or classes and accept data inputs to manage and display information dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ec7f410-2206-4626-bcc1-21ce415ca9ce', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue handle form input validation?', N'Junior', N'Vue does not have built-in complex validation, but it handles form input via v-model for binding. Developers typically use external libraries like Vuelidate or VeeValidate to manage validation rules, error messages, and form state cleanly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8398abef-5a16-4dd6-8840-21ce802ab288', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the ''yield return'' keyword affect the execution flow of a method?', N'Middle', N'The ''yield return'' keyword enables the creation of an iterator that returns elements one by one, maintaining the state of the method between calls. It allows for lazy evaluation, meaning the collection is generated only as the consumer iterates over it rather than creating the entire set in memory upfront.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5270eb80-f8c5-4a98-9944-21d03560eae6', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle bean scopes compared to traditional frameworks?', N'Middle', N'Micronaut supports standard scopes like Singleton, Request, and Prototype, but manages them through compile-time generated factories. This approach ensures that scope resolution is performant and avoids the overhead associated with runtime proxies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9cefc542-074b-4d14-8d2e-21d054d89f2a', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you approach the trade-off between adding new features and technical debt reduction?', N'Middle', N'This is a balance between short-term business velocity and long-term maintainability. I advocate for a prioritized approach where technical debt is addressed systematically alongside feature development, ensuring that critical debt is paid down before it creates significant blockers for future work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'327dd9a1-c59d-40d1-9547-21d3d07e367a', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is an object in object-oriented programming?', N'Intern', N'An object is a specific instance of a class that contains both data and the methods to manipulate that data. It represents a real-world entity or concept within the program''s logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cc04161-e8b3-449a-ada2-21d4abb33901', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'When faced with a complex problem you''ve never encountered before, how do you start solving it?', N'Intern', N'I start by breaking the problem down into smaller, manageable parts to understand the core requirements. I then research similar problems, consult documentation or team resources, and create a logical plan before attempting a solution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28b89a29-8ee1-4266-928a-21d655a42c41', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the main security risk of hardcoding API keys in source code?', N'Middle', N'Hardcoded keys are often committed to version control systems, making them visible to anyone with repository access. If the repository is leaked or compromised, the credentials can be exploited to gain unauthorized access to external services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc707c07-65d6-4dc8-9624-21db1c9de7cd', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is a ''sideEffect'' in the context of Webpack optimization?', N'Middle', N'Side effects refer to code that executes a task beyond simply exporting a value, such as modifying the global scope or polyfilling. Marking files as side-effect-free in the package configuration allows Webpack to safely remove those modules during tree shaking even if they aren''t directly imported.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd6d0744-6e5b-4c18-9510-21e054a59d7d', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Describe the concept of ''Secret Rotation'' and why it is critical for long-lived systems.', N'Senior', N'Secret rotation involves automatically changing credentials at predefined intervals to minimize the window of opportunity for an attacker using a leaked credential. It is essential because it limits the lifespan of a stolen key and forces the application to verify its identity management processes regularly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5aaf2d22-ca44-46b1-af5a-21e06c19e222', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What does the x-bind directive do?', N'Intern', N'The x-bind directive allows you to dynamically set attributes on an element based on the component''s state. It is commonly used for binding CSS classes, styles, or standard HTML attributes like disabled or href.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78da3464-34b3-45c5-bfba-21e12c3a3b8f', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the role of the id field in MongoDB documents?', N'Intern', N'The _id Field in MongoDB serves as a primary key and provides several key functionalities: - Uniqueness Guarantee: Each document must have a unique _id, which ensures data integrity. - Automatic Indexing: Automated indexing based on _id enhances query efficiency. - Inherent Timestamp: The _id can have an embedded timestamp, useful for time-based operations. For instance, with an ObjectId, the first 8 characters represent a 4 byte timestamp: $\text{timestamp} = \text{substr}(\text{ObjectId}, 0, 8)$ - Concurrency Control: If multiple write operations with the same _id occur simultaneously, MongoDB uses a technique called last-write wins to manage the conflict: The document with the most recent _id value, or timestamp if using an ObjectId, supersedes the others.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'334dbf33-a33c-4528-89f4-21e2bfde41d6', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the ''selector'' pattern and why is it used?', N'Middle', N'Selectors are functions used to extract specific slices of state from the store. They promote code reusability and performance optimization through memoization, ensuring that components only re-render when the specific data they depend on actually changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7488304f-0e4e-44d5-a746-21e32bee6b9a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is your strategy for maintaining system availability during a database migration involving a schema change?', N'Senior', N'I would use a multi-phase approach: first, introduce the new schema alongside the old one while dual-writing from the application level. Once data parity is verified, I would perform a background migration of historical data before finally switching the read path to the new schema and decommissioning the old one.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b19d9b51-9fa8-46a7-98a1-21e358bae59c', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs of using a document-based NoSQL store versus a traditional table-based relational database for a rapidly changing schema?', N'Middle', N'A document-based store allows for schema flexibility, making it easy to iterate on features without migrations. A relational database provides strict data integrity and powerful querying capabilities, but schema changes can be slow and painful as the application evolves.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
