INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ba788e3-fd68-4237-a5d7-21e618e13917', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How to use promise in Node.js?', N'Fresher', N'A promise is an object that represents the return value or the thrown exception that the function may eventually provide. A promise can also be used as a proxy for a remote object to overcome latency. Promise is relatively an easy implementation for asynchronous operation. The promise object returned from the function represents an operation which is not completed yet, but it guarantees to the caller of the operation that the operation will be completed in future. Promise has the following states: * Pending - asynchronous operation is not yet completed. * Fulfilled - asynchronous operation is completed successfully. * Rejected - asynchronous operation is terminated with an error. * Settled - asynchronous operation is either fulfilled or rejected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4eed7132-9721-47f4-98bb-21ea854a572b', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between ''nominal'' subtyping and TypeScript''s ''duck typing'' in object composition?', N'Senior', N'Nominal subtyping requires an explicit ''extends'' relationship, while TypeScript''s duck typing checks if an object satisfies the required members. Duck typing allows for more flexible composition, but it can occasionally lead to unexpected type matches if two unrelated types happen to share an identical structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5923e6b1-4b0f-4874-ada4-21ead65c2a38', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using a library versus building a custom solution for a specific feature?', N'Junior', N'Using a library saves development time and provides tested functionality, but it introduces an external dependency and potential bloat. Building a custom solution gives you full control and a smaller footprint but requires more time for development, testing, and long-term maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'268084a9-836b-4c2d-96cf-21ed176b67c4', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit ensure that CSS performance remains high with Shadow DOM?', N'Middle', N'Lit uses Constructable Stylesheets, which allow styles to be parsed once and shared across multiple instances of the same component. This significantly reduces the memory footprint and improves the performance of large applications with many repeated components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e28b3cc7-05c4-40ff-8165-21eeec6a0d4e', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does Rails perform database migrations, and why should you never edit a past migration file?', N'Middle', N'Rails migrations provide a structured way to evolve the database schema over time using Ruby code. You should not edit past migration files because they are already recorded in the schema_migrations table; changing them would cause discrepancies between developer environments and production, as the migration would not re-run.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd45bc322-3985-4489-9ef2-21efdfc4d3d6', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why is it important to design for failure in distributed databases?', N'Middle', N'In a distributed system, components will inevitably fail due to network issues or hardware problems. Designing for failure, such as implementing automated failover and replication, ensures that the system remains operational and protects data integrity despite individual component outages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b922f61-40d1-48e6-a329-21f014a277e8', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the difference between optimistic and pessimistic locking in JPA.', N'Middle', N'Optimistic locking assumes conflicts are rare and uses a version field to detect concurrent modifications, throwing an exception if a collision occurs. Pessimistic locking locks the database row explicitly, preventing other transactions from modifying it until the current transaction is finished.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
