INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97185269-c000-4283-9cb1-22074901b8df', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the role of ''Adapters'' in the Astro build process, and why are they necessary?', N'Senior', N'Adapters transform Astro''s build output to meet the requirements of specific deployment platforms like Vercel, Netlify, or Node.js. They handle environment-specific concerns like serverless function signatures, request/response handling, and edge middleware, abstracting away platform-specific complexities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d51b9bc-c444-4f4d-a0ca-220795b4c445', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the architectural implications of the C++ Object Model regarding memory layout and ABI stability?', N'Senior', N'The C++ Object Model dictates that objects have a defined memory layout, including vtable pointers for polymorphic classes and alignment requirements. ABI stability is difficult because layout changes, such as adding virtual functions or changing member order, break binary compatibility with previously compiled modules, necessitating a full recompilation of dependent code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71f84052-fafb-4a4e-8c63-2207b90242e2', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of Routing in Symfony?', N'Intern', N'Routing is the process of mapping a specific URL path to a controller method that handles the request. It defines the entry point for incoming traffic and ensures that the correct logic is executed based on the requested address.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b971b6fb-7567-4a20-9941-2207e66fdd05', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is an Effect in SolidJS?', N'Intern', N'An effect is a function that runs in response to changes in signals. It is primarily used for side effects, such as manually manipulating the DOM or performing network requests when specific state values change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82676c1a-7930-4ba9-be47-2209a7bb1074', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle CSS modules?', N'Intern', N'Vite supports CSS modules out of the box for any file ending in ''.module.css''. It automatically scopes CSS classes locally to prevent naming conflicts, allowing developers to import classes as objects in their JavaScript files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8004023-84fa-409a-bbcb-220ca4b324e1', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the ''next'' function in Hono middleware?', N'Intern', N'The ''next'' function is a callback that tells Hono to move on to the next middleware or the final route handler in the execution chain. If this function is not called, the request processing stops, and the chain is interrupted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba1e4a4c-1b24-4be2-a3d4-220ef59bb8f2', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What approach should be taken to handle custom error types in Gin?', N'Middle', N'Developers should implement a custom error handling middleware that checks for specific error types attached to the context. This allows for centralized mapping of domain-specific errors to appropriate HTTP status codes and response bodies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e245f7b3-6e6d-465c-a575-220fafbc0073', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi facilitate testing of API endpoints?', N'Senior', N'Because Chi uses the standard net/http.Handler interface, you can test your routes by using the httptest package to perform requests directly against your router instance. This allows for full integration testing of your API without needing to start a physical network server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc4ce5e5-995c-4be2-a589-2211b361a618', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How are constants declared and what is their scope in Ruby?', N'Fresher', N'In Ruby, you declare a constant by using all uppercase letters. Constants are subject to lexical scoping. While reassignment is technically possible (spawning a warning), it should be avoided as a practice. Constant Declaration You can declare a Ruby constant using Object::CONSTANT notation or by assigning a value directly to an identifier. Code Example: Constant Declaration Constant Scope Constants have a global scope, but their visibility can be restricted within classes and modules. Global VS. Local Scope - Global Scope: Constants are accessible throughout the entire application. - Local Scope: Constants are defined within a module or a class. Best Practices - Avoid re-assigning constants.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2b3468b-6d95-4674-a4a3-2212f75e6f5a', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a memory leak and how can it be prevented?', N'Intern', N'A memory leak occurs when a program allocates memory but fails to release it when it''s no longer needed. This leads to a gradual reduction in available memory, potentially causing performance issues or program crashes. Common Causes of Memory Leaks - Missing Deallocation: Failing to delete for every new or free for every malloc. - Complex Data Structures: Forgetting to deallocate memory in structures like linked lists or trees. - Circular References: In garbage-collected languages, circular references between objects can prevent memory reclamation. Techniques to Prevent Memory Leaks Manual Memory Management - RAII (Resource Acquisition Is Initialization): Allocate resources in the constructor and release them in the destructor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37e4da93-cae1-4f53-ace3-22143838663b', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why is immutability important in Phoenix applications?', N'Junior', N'Immutability ensures that data cannot be changed after it is created, which eliminates many classes of bugs related to shared state. This makes concurrent code safer, as multiple processes can read the same data without fear of it being modified unexpectedly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdd2a4ac-2c32-4d9b-af1f-2218569e7901', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you choose between vertical and horizontal scaling for a service?', N'Middle', N'I choose vertical scaling if the bottleneck is due to single-threaded performance or memory limits on a single node and the cost is justified. I opt for horizontal scaling if the workload is stateless and can be distributed across multiple smaller instances to improve fault tolerance and handle unpredictable traffic growth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'373a9625-e747-4773-a88e-221966ae6165', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the primary difference between Micronaut and Spring Boot regarding dependency injection?', N'Fresher', N'Micronaut performs dependency injection at compile-time, whereas Spring Boot typically performs it at runtime using reflection. This compile-time approach allows Micronaut to start faster and consume less memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'648902fb-8605-4e90-9af2-22247de8f747', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is ''Speculative Retry'' and when is it useful?', N'Senior', N'Speculative Retry is a configuration that triggers an additional read request to another replica if the original request does not complete within a specified latency threshold. It is useful for masking transient node performance issues, though it can increase total system load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a87305f-8e9a-402d-83c6-22259c2b4a23', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does Node.js handle backpressure in streams, and why is it critical for system stability?', N'Senior', N'Backpressure occurs when a readable stream produces data faster than a writable stream can consume it. Node.js handles this by signaling the readable stream to pause and resume once the internal buffer of the writable stream is drained. Ignoring backpressure leads to excessive memory usage and potential process crashes due to heap exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69c9448d-4a80-49cb-a54c-2227185815c5', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why might you use a ''Write-Around'' caching strategy for write-heavy applications?', N'Senior', N'Write-Around bypasses the cache for write operations to prevent the cache from being flooded with data that may not be read immediately. This preserves cache memory for high-value read-heavy data and reduces the overhead of cache management for ephemeral or infrequent writes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8324b53-4fc1-4a2a-9382-222787623d54', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are the common benefits of using a preprocessor like Sass in a team environment?', N'Intern', N'Sass improves collaboration by encouraging a modular project structure and providing a consistent way to manage design tokens. It makes large-scale projects easier to navigate and ensures that design changes can be applied globally with minimal effort.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e05b78ca-cf69-4994-91f4-2229426c23b9', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django’s ContentType framework work and what are the performance concerns?', N'Senior', N'The ContentType framework tracks all installed models in a database table, allowing for generic relationships. While flexible, it can lead to performance degradation because it often requires additional JOINs or extra queries to resolve the underlying model, making it unsuitable for high-frequency lookup tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
