INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbfec497-26dc-4821-ad1a-223079572218', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does the ''Normalized State'' pattern improve scalability in large-scale Redux applications?', N'Senior', N'Normalization involves structuring the state like a database, where entities are stored by ID in a flat object rather than nested arrays. This approach prevents data duplication, simplifies updates to specific entities, and allows for O(1) lookup performance, which significantly improves the efficiency of complex state updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
