INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84c888c9-f003-44b5-ab72-2238bdfbbe22', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain the architectural implications of choosing between eventual consistency and strong consistency in a global distributed system.', N'Senior', N'Strong consistency guarantees that all nodes see the same data at the same time, which often requires synchronous coordination and leads to higher latency. Eventual consistency prioritizes availability and performance by allowing temporary state divergence, shifting the burden of conflict resolution or business logic reconciliation to the application layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca3be981-e8dc-458d-9a20-2238d1726e72', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'When should you use ''ets'' versus a ''GenServer'' for caching?', N'Middle', N'ETS is an in-memory table storage that provides high-speed, concurrent read/write access and is ideal for large, shared datasets. Use a GenServer if you need to encapsulate logic around the data, perform validation, or ensure that access is serialized for state consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
