INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'771815b6-762e-4785-b580-224e52434fe3', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is an entity?', N'Intern', N'An entity is a real-world object, concept, or person about which a database stores information. In a relational database, an entity is typically represented as a distinct table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88aaaf6f-eea0-46b0-bfe6-224fcaaacb87', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Define the concept of eventual consistency.', N'Middle', N'Eventual consistency is a consistency model where, if no new updates are made to an object, eventually all accesses will return the last updated value. It is often used in high-availability systems where immediate consistency across all nodes is too costly in terms of performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
