INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9809f800-8726-435c-8cd7-22551e623610', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Discuss the performance implications of ''Component Composition'' versus ''Inheritance'' in Ember.', N'Senior', N'Component composition encourages the creation of small, focused components that communicate via arguments, which is generally more performant and easier to maintain. Inheritance can lead to fragile base classes and tightly coupled hierarchies that are difficult to refactor, making composition the preferred architectural approach for scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ced5ea0c-a57f-420d-ad1f-22581351bee6', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the mechanics of Dart''s event loop and how it differentiates between microtasks and events.', N'Senior', N'Dart uses a single-threaded event loop that processes events from two queues: the event queue and the microtask queue. The microtask queue is checked after every event loop iteration and is prioritized over the event queue, allowing for rapid, scheduled completion of tasks before handling external I/O or timers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8032f75a-8b50-40ce-bd4d-225d048a4d13', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the primary difference between Webpack loaders and plugins?', N'Middle', N'Loaders are used to transform certain types of modules into valid modules that Webpack can process, such as converting TypeScript to JavaScript or CSS to strings. Plugins are more powerful and can perform a wider range of tasks, such as bundle optimization, asset management, and environment variable injection, by hooking into the entire compilation lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd0e633a-221f-4ec3-8215-225de8c8bfa0', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember handle dependency injection?', N'Middle', N'Ember uses a central container to manage the instantiation and lifecycle of objects like services and helpers. When you inject a service into a component, the container resolves that dependency, ensuring you have a consistent instance across your application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
