INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eee083d2-0ab1-4cc0-8ff9-227300fba005', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is Hot Module Replacement (HMR) and how does it benefit the developer?', N'Intern', N'Hot Module Replacement is a feature that updates specific modules in the browser as soon as the source code is changed without requiring a full page reload. This preserves the current application state and provides near-instant feedback while developing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43e635b3-8b6d-4bf1-a1fc-2277a4992574', N'a2838158-7305-480a-b22b-4dc35776b400', N'Compare ''Sharding'' and ''Replication'' as strategies for scaling a database.', N'Senior', N'Sharding distributes data across multiple nodes to increase storage capacity and write throughput by partitioning the dataset. Replication creates copies of data across multiple nodes to increase read availability, fault tolerance, and geographic proximity to users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1a2d8d3-9af2-4c5e-b14b-227895fafc44', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a closure memory leak and how do you prevent it?', N'Fresher', N'A closure memory leak occurs when a closure unintentionally keeps a large object (such as a DOM node, a large dataset, or a complete HTTP response) in memory by holding a reference in its closed-over scope long after the object is needed. The V8 garbage collector cannot reclaim the memory because the closure is still reachable. Common patterns that cause leaks: 1. Event listeners not removed — the listener closes over component state, keeping the entire component tree alive. 2. Timers not cleared — setInterval callbacks closing over large objects run indefinitely. 3. Detached DOM nodes — a closure holds a reference to a DOM node that has been removed from the document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af9b62fa-d412-4217-bee5-227ad1216979', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the difference between warning, message, and stop in R?', N'Middle', N'Stop terminates execution and throws an error, requiring the user to intervene. Warning indicates a potential issue but allows the code to continue running, while message is used for providing informational feedback to the user without interrupting execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02661387-6f20-430e-8ead-227bc0b61c60', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does the Svelte compiler maintain performance when dealing with large lists?', N'Senior', N'Svelte uses efficient keyed-each blocks that track elements in a list. When the list changes, the compiler generates instructions to move or update only the specific DOM nodes affected, rather than re-rendering the entire list.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6d6ecb5-732a-47b9-b279-227c655e2281', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the standard template library (STL)?', N'Intern', N'The Standard Template Library is a collection of C++ template classes that provide common data structures and algorithms. It includes containers like vectors, lists, and maps, as well as algorithms for sorting and searching. Using the STL helps developers write efficient and standardized code without reinventing common tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a0bc5ea-e6d7-4071-8784-227e8a011433', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does the Phoenix View layer differ from templates in other frameworks?', N'Middle', N'Phoenix Views are actual modules that act as a presentation layer, separating data formatting logic from the template rendering. This allows developers to define functions to prepare data for display, keeping templates clean and focused solely on HTML structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1d388f8-24ec-4a4d-abc2-2282800e8fde', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of the ''renderOptions'' property in a Lit component?', N'Middle', N'Render options allow you to customize how the template is rendered, such as specifying a host for the shadow root or using a different render root entirely. This is useful for advanced scenarios like rendering into a light DOM instead of shadow DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fff6e316-1496-4324-8795-22846c7a0a22', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does C++ achieve RAII and why is it preferred over manual memory management?', N'Middle', N'RAII binds the lifecycle of a resource, like memory or file handles, to the lifetime of an object. By using constructors to acquire resources and destructors to release them, C++ ensures deterministic cleanup even when exceptions occur, significantly reducing memory leaks and dangling pointers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b52be94e-32f9-4a36-a27d-2286ef294007', N'954a0331-deff-4399-b588-96f39fec001d', N'How does ''Ahead-of-Time'' (AOT) compilation differ from ''Just-in-Time'' (JIT)?', N'Middle', N'AOT compiles the application during the build process, leading to smaller bundles and faster rendering since the browser does not need to compile code on the fly. JIT compiles the application in the browser at runtime, which is faster for development cycles but slower for production performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'044c10b2-7be6-44aa-9944-2287b3df77bf', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does logical decoding facilitate change data capture (CDC) in PostgreSQL?', N'Senior', N'Logical decoding allows the extraction of changes from the WAL in a format that can be consumed by external systems. By using replication slots, it ensures that the database keeps the necessary WAL segments until the downstream consumer has acknowledged the data, ensuring reliable integration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87b5dc22-6a64-4f8c-aeb4-2288bacb2727', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask manage configuration settings?', N'Junior', N'Flask applications can store settings in a configuration object, which can be loaded from a dictionary, a file, or environment variables. This allows developers to easily switch between different settings for development, testing, and production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41f9a8d9-10ee-435e-986a-2288fba1b682', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is an Astro Layout component?', N'Intern', N'A layout component is a reusable Astro component used to wrap page content with common elements like headers, footers, and metadata tags. It helps maintain a consistent design throughout the website.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91667c26-317a-4a5c-b57c-2289ccbdb87d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the drawback of declaring methods directly in JavaScript objects?', N'Intern', N'One of the drawback of declaring methods directly in JavaScript objects is that they are very memory inefficient. When you do that, a new copy of the method is created for each instance of an object. Example: Here, each instance variable emp1, emp2 has own copy of formatSalary method. However the formatSalary2 will only be added once to an object Employee.prototype. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'840224e2-6a94-4a33-a1e1-228d196ff8e2', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the trade-offs of the Read Committed isolation level.', N'Middle', N'Read Committed prevents dirty reads by ensuring a transaction only sees data that has been fully committed. However, it does not prevent non-repeatable reads, meaning data can change if another transaction commits changes between two reads within the same transaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b4dfe18-e673-4da7-b883-228d8233db00', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What are the implications of using jQuery''s .html() method compared to .text() for security?', N'Middle', N'The .html() method parses the input string as HTML, which can lead to Cross-Site Scripting (XSS) vulnerabilities if the content is not sanitized. The .text() method treats the input as plain text, effectively preventing the execution of malicious scripts injected via data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2723b7b9-93b8-4500-ac65-228daed338cb', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why would you choose to use a ''LiveView'' over a traditional SPA architecture?', N'Middle', N'LiveView allows you to write complex, real-time UI logic on the server, keeping the state on the server and reducing the amount of JavaScript the client needs to manage. This simplifies development by avoiding the need for a complex JSON API and client-side state synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1efdbbec-715e-477b-8022-228de7a926c9', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit''s file-based routing impact the scalability of large-scale frontend projects?', N'Senior', N'File-based routing enforces a strict organizational structure that makes codebases predictable and easier to navigate as the team grows. It maps the URL structure directly to the filesystem, which simplifies deep-linking and reduces the cognitive load required to manage complex application paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c666204-de00-4c1d-94d1-228f564dce2a', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is the use of jQuery''s event delegation considered a double-edged sword?', N'Senior', N'While event delegation is an efficient way to handle dynamic elements, relying on it globally can make the event flow harder to trace and debug. Modern frameworks encapsulate event handling within components, providing clearer boundaries and easier scoping for event interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef4722f3-35fe-487e-a503-229051128ad2', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is React hydration?', N'Intern', N'React hydration is used to add client-side JavaScript interactivity to pre-rendered static HTML generated by the server. It is used only for server-side rendering(SSR) to enhance the initial rendering time and make it SEO friendly application. This hydration acts as a bridge to reduce the gap between server side and client-side rendering. After the page loaded with generated static HTML, React will add application state and interactivity by attaching all event handlers for the respective elements. Let''s demonstrate this with an example. Consider that React DOM API(using renderToString) generated HTML for component which contains element to increment the counter. The above code generates the below HTML with a header text and button component without any interactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29a2ac91-f9f5-4a05-a99e-2291a9b91911', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How can you handle errors in NestJS?', N'Fresher', N'NestJS handles errors using exceptions such as throw new HttpException() syntax. When an exception is thrown, NestJS will automatically send an appropriate HTTP response with a status code and message. In the above example, an HttpException is thrown with a message of ''Resource not found'' and a status code of 404 (Not Found). For more complex error handling, you can create custom exceptions by extending the HttpException class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43d9fdcf-24ff-4b63-99b6-229356e78d2b', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Discuss the trade-offs of using short-lived tokens versus long-lived tokens in an OAuth2 flow.', N'Senior', N'Short-lived access tokens reduce the window of opportunity for an attacker if a token is intercepted, improving security. However, they require frequent refreshing, which increases the load on the authorization server and adds complexity to the client-side token management logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b71fae21-03b6-4ccc-9202-22939695d970', N'075b8862-431c-4678-9767-f55359758a4a', N'What are single file components?', N'Intern', N'Single File Components are an easy concept to understand. Earlier you might heard about all three parts(HTML, JavaScript and CSS) of your application kept in different components. But Single File Components encapsulate the structure, styling and behaviour into one file. In the beginning, it seems strange to have all three parts in one file, but it actually makes a lot more sense. Let''s take an example of Singile File Components', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9206aad-6657-45cd-960f-22959478843b', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the benefits of using Sparse Indexes in DynamoDB?', N'Senior', N'Sparse indexes only contain entries for items that have the indexed attribute present. This reduces the storage size and improves query efficiency for datasets where only a subset of items matches specific metadata criteria.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbe4a08e-bb19-4525-b1aa-2295b9e47341', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How are cross-cutting concerns addressed in software architecture?', N'Senior', N'Cross-cutting concerns in software development represent aspects that span multiple modules and layers, such as logging, security, and caching. Tackling these concerns with a straightforward and coherent approach often simplifies both development and maintenance. Addressing Cross-Cutting Concerns 1. Separation of Concerns (SoC): A design principle that suggests partitioning a program into distinct sections, such as presentation or data storage. Implementing SoC often involves strategies like modularization and layering. 2. Design Patterns: They are recurring, reliable solutions to typical design problems that help direct the structure and flow of programs. Patterns like Singleton, Factory, and Observer all take on cross-cutting concerns. 3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9629e7e-e88f-470d-82c3-2297d6edc8bb', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How do you perform redirects in Hono?', N'Junior', N'Hono provides a redirect method on the context object. This simplifies the process of sending a 302 status code along with the target URL to the client, effectively managing navigation or resource location changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62f02daa-8e50-4bab-92a6-229ba58125b6', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the benefit of using Echo''s ''Group'' middleware over global middleware?', N'Middle', N'Group middleware allows for granular security, such as only applying authentication to routes under /api/v1/user. This prevents unnecessary overhead and potential security vulnerabilities from applying middleware to public endpoints like health checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
