INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb8c8b7e-7710-4ffe-b20c-229f160e34ae', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the primary difference between ''SizeTieredCompactionStrategy'' and ''TimeWindowCompactionStrategy''?', N'Senior', N'SizeTieredCompactionStrategy groups SSTables of similar sizes to reduce write amplification, making it ideal for general workloads. TimeWindowCompactionStrategy organizes data into time-based buckets, which is highly efficient for time-series data as it allows for efficient data expiration and removal of entire files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
