INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdef330d-a652-4a1a-911c-22a0e1c22fcf', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What does ''lazy'' loading do in SolidJS?', N'Junior', N'Lazy loading allows you to split your application code into smaller chunks by dynamically importing components only when they are needed. This improves initial load performance by reducing the size of the main JavaScript bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4a99e02-1e63-4ed5-b759-22a1fe2dfd9c', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are the risks of using global variables in a large Sass project?', N'Senior', N'Global variables can lead to naming collisions and unpredictable behavior when multiple modules attempt to modify or rely on the same value. Using the module system''s namespacing mitigates these risks by requiring explicit access to variables from their respective files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6f90b4d-ee4e-44e0-a69d-22a489732175', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your approach when you discover that a design decision you made earlier is no longer suitable for the current requirements?', N'Intern', N'I would first perform a root cause analysis to understand why the original decision is no longer effective and document the limitations. Then, I would communicate the situation to my team or supervisor, explaining the impact of the change and proposing a plan to migrate to a better approach. It is better to acknowledge the need for change early rather than forcing a suboptimal design to work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0d25e38-1316-4816-a29d-22a5130b63dd', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you generate random integers', N'Fresher', N'You can use Math.random() with Math.floor() to return random integers. For example, if you want generate random integers between 1 to 10, the multiplication factor should be 10, Note: Math.random() returns a random number between 0 (inclusive), and 1 (exclusive)', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1eb8f31f-dd7e-4d7d-b5a8-22a56a2a13bf', N'a2838158-7305-480a-b22b-4dc35776b400', N'What are the architectural implications of choosing a push-based versus a pull-based monitoring system?', N'Senior', N'Push-based systems allow services to report metrics immediately, which is useful for ephemeral jobs but can overwhelm the central collector during traffic spikes. Pull-based systems allow the collector to control the load and implement backpressure, but they require the infrastructure to be discoverable by the monitoring agent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cebaad1-324e-4769-8121-22a57a51f2e9', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is dynamic typing in Python?', N'Intern', N'Dynamic typing means that the type of a variable is determined at runtime rather than when the code is written. You do not need to explicitly declare the data type of a variable, as the interpreter tracks it automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a00212a7-e241-44a7-b3e8-22a827d4dfa3', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What does Svelte''s ''hydration'' process entail?', N'Middle', N'Hydration is the process where Svelte attaches event listeners and reactivity to existing server-rendered HTML. It ensures that the page becomes interactive without requiring the browser to re-render the entire DOM structure from scratch, balancing speed and interactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db828a93-c3a9-4659-b1f5-22a8b1294f79', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why should you use standard protocols like REST or gRPC instead of inventing a custom communication format?', N'Junior', N'Standard protocols have extensive community support, well-documented tooling, and broad compatibility with other systems. Using custom formats increases the learning curve for new team members and complicates integration with third-party libraries and monitoring tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7510b24-8344-4820-b534-22abc2cdb706', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of Flask''s ''teardown_appcontext'', and how does it differ from ''teardown_request''?', N'Senior', N'The ''teardown_appcontext'' runs when the application context is popped, regardless of whether a request was successfully handled or failed. It is the safest place for resource cleanup, such as closing database connections, to ensure they happen even in the event of an unhandled exception.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
