INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27ab1ed8-8e93-40f4-8279-22b403ab4c48', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik achieve SEO benefits?', N'Intern', N'Qwik provides full HTML content to search engines during the initial request because it uses server-side rendering. Since the content is fully rendered and does not depend on client-side JavaScript execution to appear, search engine crawlers can easily index the pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
