INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e08e2ea3-5476-479a-b4f7-22b974e9a85c', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How do goroutines differ from lightweight threads in other languages?', N'Senior', N'Goroutines are multiplexed onto a small, managed pool of OS threads and have a much smaller initial stack size compared to standard OS threads. The Go runtime manages the lifecycle of goroutines, including stack growth and scheduling, with far less overhead than the OS kernel. This allows for the creation of millions of concurrent goroutines, which would be impossible with traditional thread-based concurrency models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
