INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'499a07ea-4529-4280-85af-22c24a897218', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Can Chi be used effectively for high-performance gRPC-gateway implementations?', N'Senior', N'Yes, Chi is often used alongside gRPC-gateway to serve RESTful endpoints that map to gRPC services. Its lightweight routing is ideal for the reverse proxy pattern, as it adds minimal latency when translating HTTP/JSON requests into gRPC calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f08e6f6e-2355-40bb-bdb1-22c2c7145fac', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When considering software security, what is the typical trade-off with user convenience?', N'Fresher', N'Enhanced security features, such as multi-factor authentication or complex password policies, often create friction for the user. The trade-off is balancing the level of protection needed against the impact on the user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
