INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9b373ae-e0b5-40d8-b7e7-22ce2f5bf62b', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the role of the HttpServer struct?', N'Intern', N'The HttpServer struct is responsible for binding the application to a network address and port. It manages the lifecycle of the server and distributes incoming requests to the configured worker threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f7faf19-039a-4cee-8344-22cfcd29ba8b', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What happens to the JavaScript of an Astro component if it is rendered with no hydration directive?', N'Middle', N'If no hydration directive is used, the component''s JavaScript is stripped away entirely during the build process. Only the HTML and CSS generated by that component are sent to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f04be82-7a36-4597-8f5f-22d0ea923bb9', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does the Two-Phase Commit (2PC) protocol handle node failures during the commit phase?', N'Senior', N'If a participant fails after voting but before receiving the final commit command, it remains in a blocked state until the coordinator recovers or the transaction times out. The coordinator persists the decision in a write-ahead log, allowing it to re-send the decision to participants upon recovery to ensure all nodes reach the same state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d4a12d7-525a-47e4-b219-22d1a1886c54', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the role of the ''write barrier'' in Go’s garbage collector?', N'Senior', N'The write barrier is a mechanism that intercepts pointer updates during the concurrent marking phase to ensure the GC maintains a consistent view of the heap. It prevents the GC from missing objects that are moved or referenced by the application while marking is in progress.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a295486-778c-4585-a0db-22d4bd256f8b', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How are security headers managed in Litestar?', N'Junior', N'Security headers can be managed through custom middleware or built-in security plugins. These tools help protect the application by setting headers like Content-Security-Policy or CORS policies automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'930aacc9-d78a-4d63-97b2-22d851d2ab73', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How do you implement a Zero Trust Architecture in a distributed microservices environment?', N'Senior', N'Zero Trust relies on the principle of never trusting, always verifying, regardless of network location. This is achieved through mutual TLS (mTLS) for service-to-service authentication, fine-grained identity-based access control using JWTs or SPIFFE, and continuous monitoring of request context rather than relying on perimeter security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e471f5f-1507-4092-9dc2-22dbccd536c8', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the primary role of PostgreSQL in a database architecture?', N'Intern', N'PostgreSQL is an object-relational database management system that serves as a central repository for storing, retrieving, and managing structured data. It ensures data integrity and consistency by adhering to ACID properties, making it a reliable choice for applications requiring complex queries and robust transaction support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d3c45b3-a997-4c24-83d5-22dc44c78a23', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does dependency injection (DI) in ASP.NET Core differ from traditional service location?', N'Middle', N'In DI, dependencies are explicitly declared through constructors, making components easier to test and loose-coupled. Service location involves an object retrieving its own dependencies from a container, which obscures dependencies and makes unit testing significantly harder.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03c92943-46e2-4fad-bf1d-22df827bd868', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Describe your process for debugging a complex race condition in a distributed system that only manifests under high concurrency.', N'Senior', N'I would attempt to reproduce the scenario in a staging environment using traffic shadowing or replay tools to simulate the exact concurrency patterns. If reproduction is impossible, I would perform a formal verification of the distributed locking logic or state synchronization mechanism to ensure that atomicity is maintained across all nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5046e604-e53b-4b6c-8ec6-22e03a6910a3', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the purpose of the ''Controller'' class in Litestar?', N'Junior', N'Controllers are a way to organize related route handlers into a single class. They allow you to group endpoints under a common URL path prefix and apply shared middleware or security settings to all routes within that group.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e49f7e6e-0158-4968-957d-22e2dc4cea16', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Why is it often better to use relative units like ''rem'' or ''em'' instead of ''px''?', N'Middle', N'Using relative units like ''rem'' makes websites more accessible and responsive, as they scale according to the user''s browser font settings. Pixels are absolute units that do not adjust to user preferences, which can lead to poor readability for users who have customized their browser''s default font size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'180b2b04-545b-4c2e-8813-22e63e5a154c', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What does the DISTINCT keyword do?', N'Fresher', N'The DISTINCT keyword is used in a SELECT statement to return only unique values from a column. It removes all duplicate records from the result set.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64d15c78-4703-47b5-8be4-22e6862ae058', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Why is data denormalization often used in high-scale database design?', N'Middle', N'Denormalization involves adding redundant data or grouping data to avoid complex joins across large tables. This reduces the computational cost of read operations, significantly improving performance at the expense of increased storage requirements and data integrity management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'264a15e5-3a38-42a0-976c-22e764c64ed4', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Can Vite be used without a framework?', N'Intern', N'Yes, Vite is framework-agnostic. While it is commonly used with React, Vue, or Svelte, it can also be used for vanilla JavaScript or TypeScript projects without any underlying framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
