INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34512e82-b48f-48f1-a841-22f4ddcb2465', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the difference between Laravel Queues and standard synchronous execution, and when should you use them?', N'Middle', N'Synchronous execution blocks the application flow until a task completes, while queues offload time-consuming tasks to a background process. Queues should be used for operations like sending emails, processing images, or third-party API calls to keep the user interface responsive and improve overall system throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67dd0c4a-bb13-44d6-a203-22f503752a4a', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the advantage of using ''keep-alive''?', N'Middle', N'Keep-alive caches component instances when they are toggled out of the DOM. This preserves the state of the component, such as form inputs or scroll positions, and prevents the expensive overhead of re-mounting the component when it is navigated back to.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86ff840f-875a-4f01-9f99-22f60c6311dc', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the advantage of using standard Web APIs in Hono?', N'Fresher', N'Using standard Web APIs ensures that the code is future-proof and compatible with any modern JavaScript environment. It reduces dependency on non-standard libraries and makes the framework easier to learn for those familiar with frontend web development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ca2dde1-117f-45ce-a6e6-22ff8e114a8b', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the ''batch'' utility used for in SolidJS?', N'Middle', N'The batch utility allows multiple signal updates to be processed in a single reactive cycle. This prevents unnecessary intermediate renders when multiple related state changes occur simultaneously, improving performance by ensuring effects only run once after all updates are applied.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38b1532c-864a-44ff-ad92-230079ec6348', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the architectural implications of using biased locking in older JVM versions versus the modern approach of deprecating it?', N'Senior', N'Biased locking was designed to optimize uncontended synchronization by assuming a lock is held by the same thread repeatedly. However, it introduced significant complexity in the JVM and overhead during safepoint synchronization, leading to its deprecation in favor of more efficient, streamlined locking mechanisms that perform better in modern multi-core environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d545537-51d9-4e90-a9ad-23024abfb001', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the purpose of Rocket''s ''Config'' system and how is it integrated?', N'Senior', N'Rocket''s configuration system allows for environment-specific settings defined via TOML files, environment variables, or programmatic structs. It integrates seamlessly into the application lifecycle, ensuring that production, staging, and development environments remain isolated through type-safe configuration access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea0df097-ac89-419a-998e-2302512ef847', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does Rails handle multi-threading, and what are the implications for shared state?', N'Senior', N'Rails is thread-safe, but shared state in global variables or class instance variables is not thread-safe and will cause race conditions. You must use thread-local variables or immutable patterns to ensure data integrity when running in multi-threaded environments like Puma.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9afeaeef-77f0-4a9d-a1ed-23029321e93c', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of the include statement in PHP?', N'Intern', N'The include statement is used to insert the content of one PHP file into another before it is executed. It is primarily used for code reuse, such as including header, footer, or configuration files across multiple pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5c8feba-ed3b-40ed-9476-2303176c93f3', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js handle route prefetching and its impact on user experience?', N'Senior', N'Next.js automatically prefetches linked routes in the background when they enter the viewport. This makes navigation feel instantaneous because the necessary JavaScript and data are already cached in the browser by the time the user clicks the link.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89ef7fe0-bd47-44c6-ad40-230358cf9497', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What happens if you perform a read operation without specifying the partition key?', N'Fresher', N'If you do not specify a partition key in your query, you must perform a Scan operation. This reads the entire table, which is inefficient and consumes significant read capacity units.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1e17039-8f12-4938-87ba-2303e136a081', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it important to maintain a separation of concerns in your software architecture?', N'Intern', N'Separation of concerns ensures that each part of the system has a single, well-defined responsibility. This makes the system easier to understand, test, and refactor because changes in one area are less likely to have unintended side effects in others.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48ad5970-7a14-49fd-b118-2304af771c7e', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How do you handle dark mode in Tailwind?', N'Intern', N'Tailwind includes a ''dark'' variant that allows you to style elements specifically for dark mode. By adding the ''dark:'' prefix, you can define colors and styles that only trigger when the user''s system preferences or a specific class is set to dark.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'192f774c-2d47-4ee9-ae05-2306e55be66b', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between ArrayList and LinkedList?', N'Junior', N'ArrayList is backed by an array and is generally faster for accessing elements by index. LinkedList is a doubly-linked list, which is more efficient for frequent additions and removals from the beginning or middle of the list.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4678a658-364f-4268-9b01-2307f88746c0', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why might a Senior Engineer prefer Tailwind CSS over a component library like Material UI or Ant Design for a custom product?', N'Senior', N'Tailwind provides unstyled primitives, allowing for total visual control and easier brand differentiation compared to opinionated component libraries. It avoids the ''library bloat'' and the difficulty of overriding complex internal styles inherent in pre-built UI kits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75830151-01b7-48c6-bef5-230dcf53d622', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a Dirty Read?', N'Intern', N'A dirty read occurs when a transaction reads data that has been modified by another uncommitted transaction. If the first transaction rolls back, the second transaction is left with data that technically never existed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b4e4eba-2beb-4fa0-a751-2310bf93c8eb', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the difference between ''any'' and ''some'' when using protocols.', N'Middle', N'The ''some'' keyword indicates an opaque type where the underlying type is hidden but fixed, allowing the compiler to know the specific type. ''Any'' is an existential type that erases the underlying type, allowing a variable to hold any type that conforms to the protocol but requiring dynamic dispatch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'136b764c-0e7c-462a-b0cd-2314e3d1fda5', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik optimize cache hit rates for JavaScript chunks?', N'Senior', N'By splitting the application into many small, granular chunks, Qwik improves cache efficiency. Since each chunk is highly specific to a component or interaction, updates to one part of the application do not invalidate the entire bundle, allowing browsers to reuse cached code across navigations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5a3dff2-df9a-4539-86ac-231ac3925a3d', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why is it generally discouraged to use a low-cardinality partition key?', N'Middle', N'A low-cardinality partition key results in data being concentrated in a small number of partitions, leading to uneven distribution. This creates hotspots, prevents effective horizontal scaling, and limits the total throughput capacity of the table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1adc7370-8667-45ad-90e2-231ca1e865f8', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of the ''Depends'' function?', N'Intern', N'The ''Depends'' function is used to declare a dependency in a function signature. It tells FastAPI to resolve the dependency logic before executing the main function and to inject the result as an argument.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bb61fca-928b-434c-a919-231e712b4ae3', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What happens to unused CSS in a production build of Tailwind?', N'Intern', N'Tailwind automatically scans your project files for utility classes and removes any CSS that isn''t being used. This process ensures that your final CSS bundle remains as small as possible regardless of how many classes exist in the framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4749d819-a78d-4c02-a25d-231e7e933480', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'When should you choose database sharding over read replication?', N'Middle', N'Read replication is used to scale read-heavy workloads by distributing queries across multiple secondary nodes. Sharding is required when the write volume or the total data size exceeds the capacity of a single primary node, as it partitions the data across multiple physical databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54847436-47a6-4a7c-b795-232123ff723e', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the function of the NestJS Logger?', N'Junior', N'The built-in Logger service provides a consistent way to log information across the application. It supports different log levels like debug, error, and verbose, and can be customized to send logs to external monitoring systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c53ad45e-364f-4cc1-ae51-2323a006518a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What strategy would you use to perform a zero-downtime deployment for a critical service?', N'Senior', N'I would employ a Blue-Green or Canary deployment strategy, where the new version is deployed alongside the old one. Traffic is gradually shifted to the new environment while monitoring error rates, allowing for an immediate rollback if performance metrics deviate from established thresholds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abec9c02-c6ff-4e66-a309-2323cb0ec6d3', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What are the ACID properties?', N'Fresher', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably and maintain data integrity even in the event of errors or system failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'558e86e1-21b9-4577-aaf5-2325d7b65cc2', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What are ES modules and why does Vite rely on them?', N'Intern', N'ES modules are the official standard format for packaging JavaScript code for reuse. Vite uses them to load files directly in the browser during development, allowing the browser to handle module resolution rather than bundling everything upfront.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae0cb3dd-76dd-4447-87de-232e3869fa4f', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of ''Flask-SQLAlchemy''?', N'Fresher', N'Flask-SQLAlchemy is an extension that adds support for SQLAlchemy to Flask. It simplifies database interactions by providing an object-relational mapper, allowing you to use Python classes to represent database tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02575042-e53b-4977-9c0e-232e4ddab5a9', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Explain the concept of ''Resumability'' in Qwik and how it fundamentally differentiates the framework from traditional Hydration-based approaches.', N'Senior', N'Resumability is the ability of an application to pause execution on the server and resume it on the client without re-executing the entire component tree or downloading the initial bundle. Unlike traditional hydration, which requires the browser to download and execute JavaScript to attach event listeners and reconstruct the virtual DOM, Qwik serializes the application state and event metadata into HTML. This allows the client to immediately interact with the page, as event listeners are lazily loaded only when a user interacts with a specific element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1978ee21-7ced-4348-b76d-2331bda30581', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js''s reactivity system handle deep objects and array mutations?', N'Senior', N'Alpine.js uses a deep reactive approach, meaning it recursively wraps objects and arrays with proxies to track changes. While this provides an intuitive developer experience, deeply nested structures can incur a performance penalty on every mutation, necessitating a flatter state structure for high-frequency updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77cf2edf-befb-4449-83f7-2332e151e80e', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing storage, how do you evaluate the trade-offs between data compression and CPU usage?', N'Senior', N'Compression is a tactical choice to reduce I/O and storage costs, which is highly beneficial for cold data or bandwidth-constrained systems. I avoid aggressive compression on hot, CPU-bound application paths where the latency penalty of decompressing data on the fly would negatively impact end-user response times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ddf2dc2-de90-4610-824d-2333a2371d36', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What does it mean if a system is ''stateless''?', N'Fresher', N'A stateless system does not retain information about previous interactions between the client and the server. Every request from the client must contain all the information necessary for the server to understand and process it. This makes the system easier to manage because the server does not need to synchronize session data across different requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ca6d0fe-ec09-49a7-a2de-2335b10da713', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is suspense component?', N'Intern', N'React Suspense is a built-in feature that lets you defer rendering part of your component tree until some condition(asynchronous operation) is met—usually, data or code has finished loading. While waiting, Suspense lets you display a fallback UI like a spinner or placeholder. 1. Lazy loading components uses suspense feature, If the module containing the dynamic import is not yet loaded by the time parent component renders, you must show some fallback content while you’re waiting for it to load using a loading indicator. This can be done using Suspense component. The above component shows fallback UI instead real component until OtherComponent is fully loaded. 2. As an another example, suspend until async data(data fetching) is ready', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'904e051a-b4c7-4112-adf6-2336c7e6456a', N'4c000000-0000-0000-0000-000000000005', N'Why is it important to implement rate limiting in an API?', N'Middle', N'Rate limiting protects your services from being overwhelmed by too many requests, whether from accidental misconfigurations or malicious DDoS attacks. It ensures fair usage and maintains system stability for all users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'279f661d-7461-4a64-a1da-2337f8e06d94', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the difference between FastAPI and Flask?', N'Intern', N'FastAPI is built from the ground up to support asynchronous programming and uses Python type hints for validation. Flask is a more traditional, synchronous framework that generally requires external extensions to achieve similar features like automatic validation and documentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e86ee745-4ca7-4f58-a924-233b57245568', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle props?', N'Fresher', N'Props are read-only properties passed from a parent component to a child component. They allow data to be passed down the component tree to configure how a component should appear or behave.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'faa2f86a-376c-4daa-8360-233e1f889db4', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Explain the concept of eventual consistency in DynamoDB.', N'Middle', N'Eventual consistency means that a read operation might not immediately reflect the results of a recently completed write operation. While it provides higher read throughput, data is typically consistent across all replicas within a second, which is a trade-off for lower latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49a4c92b-7e59-4f71-8538-2340ea5093c6', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the ''Responder'' trait in Actix-web?', N'Fresher', N'The Responder trait is used to convert an object into an HTTP response that can be sent back to the client. Any type that implements this trait can be returned from a handler function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a1102ca-8121-439f-9d84-23412acc30c7', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s sound null safety interact with the underlying JavaScript engine when compiled to web?', N'Senior', N'When compiled to JS, Dart''s sound null safety is enforced via type assertions and structural checks during the development process. However, the generated JS code must still be cautious of the lack of inherent null safety in the host environment, often requiring additional runtime safeguards to ensure the Dart type system invariants are maintained.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'865d9b8d-3c53-492f-a5dc-2341505862a9', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How do you handle shared state across multiple requests in FastAPI?', N'Senior', N'Shared state can be stored in the ''app.state'' object or via global singletons. For distributed systems, however, state should be managed in an external, shared persistence layer like Redis to ensure consistency across multiple instances of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ad0781c-d603-4991-ae43-23437882398e', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the ''App'' instance in Fiber?', N'Junior', N'The App instance is the central object that initializes the server, registers routes, and manages global middleware. It acts as the primary configuration point for the entire application, including settings like server timeouts and custom error handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc80818e-f6bf-4495-b82e-23487bbbceb3', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the reasoning behind choosing a public cloud provider versus hosting on-premises?', N'Junior', N'Cloud providers offer scalability, reduced maintenance overhead, and a pay-as-you-go model that is ideal for most startups. On-premises hosting is usually reserved for organizations with strict regulatory, security, or data sovereignty requirements that mandate physical control over the hardware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff9c4223-3d37-420a-a59f-2349e527098a', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your approach to choosing between a relational and document-oriented database?', N'Senior', N'I choose a relational database when complex relationships, transactional integrity, and data normalization are critical to the business logic. I opt for document-oriented databases when the schema is highly dynamic, the data is hierarchical, or the access pattern is primarily key-value based, allowing for easier horizontal partitioning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80415f50-43d9-433e-96d3-234ba2980cd6', N'4c000000-0000-0000-0000-000000000005', N'When is it appropriate to use a Bloom filter?', N'Middle', N'A Bloom filter is a space-efficient probabilistic data structure used to test whether an element is a member of a set. It is ideal for scenarios where you want to avoid expensive disk lookups for items that definitely do not exist, though it may return false positives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'471792e7-ede7-4308-bb6d-234ce8f52008', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What does it mean for a Micronaut application to be cloud-native?', N'Junior', N'Being cloud-native means the framework is designed to work efficiently in containerized environments like Kubernetes. Features like low memory footprint, fast startup, and built-in support for service discovery make it ideal for cloud deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c440aa99-2ed3-4472-9212-234d3eb3916d', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R handle non-standard evaluation (NSE) and what are the risks for package developers?', N'Senior', N'NSE allows functions to capture unevaluated expressions, enabling user-friendly interfaces like those in data manipulation libraries. For developers, this creates significant risk as it breaks standard functional expectations, requiring careful use of quasiquotation to manage scope and prevent symbol leaking or unexpected evaluation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93b77596-42a8-44e1-83a1-234d4b94550f', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why is the use of ''Tracked'' properties important in modern Ember?', N'Middle', N'Tracked properties are the foundation of Ember''s reactivity system. By decorating properties as tracked, the framework automatically detects when they change and schedules a re-render of only the parts of the DOM that depend on those specific values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3320737-71af-4d6e-8009-234e7df5471e', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the difference between Universal Rendering and Client-Side Rendering in Nuxt?', N'Intern', N'Universal rendering provides both server-side rendering for the initial request and client-side hydration for subsequent interactions. Client-side rendering delivers a minimal HTML shell and relies on JavaScript to fetch and render content in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf7fcdf7-3763-4335-aed4-2350c7b3a539', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Discuss the performance implications of string conversion in Go.', N'Senior', N'Strings in Go are immutable, meaning that conversions between types like ''string'' and ''[]byte'' often require a full memory allocation and copy. While the compiler performs optimizations for common cases like range loops or specific map lookups, developers must be aware of the allocation cost in high-throughput paths. Avoiding unnecessary conversions by utilizing byte slices directly can significantly reduce pressure on the garbage collector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8f478a1-bab2-4ee2-a3b2-23523eb0b581', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'In a NestJS microservices architecture, how do you handle partial failures in inter-service communication?', N'Senior', N'Implement patterns such as retries, circuit breakers, and dead-letter queues to handle service unavailability. NestJS''s modular nature allows for injecting these fault-tolerance patterns at the service level, ensuring that one failing downstream dependency does not crash the entire request chain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80de2169-2900-49bb-bb41-2354d4a2eb13', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If two team members disagree on how to implement a feature, what is the best way to move forward?', N'Intern', N'I would encourage both parties to clearly explain the pros and cons of their respective approaches based on technical requirements and constraints. If a consensus cannot be reached, we should look for objective evidence or consult a senior team member to evaluate which solution better aligns with the project goals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cce82a4f-ed50-4bc8-8c90-235539a460c9', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the primary purpose of middleware in Hono?', N'Intern', N'Middleware in Hono acts as a layer that sits between the incoming request and the final route handler. It is used to perform common tasks such as logging, authentication, error handling, or modifying request and response objects globally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12fafdb2-8f16-47d9-9389-235572d9a47e', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the difference between causal consistency and eventual consistency in MongoDB?', N'Senior', N'Causal consistency ensures that operations that are causally related appear in the correct order to the client, even across different nodes. Eventual consistency only guarantees that all nodes will eventually reflect the same data without ordering guarantees across distributed operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c49b4b9-6917-4f29-8022-2356adb6cd06', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between shallow and deep copying of an object?', N'Middle', N'A shallow copy creates a new object instance but shares references to mutable objects contained within the original. A deep copy recursively duplicates every object found within the original, ensuring that the new instance is completely independent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed9c3be4-21ec-4218-bfa9-2357a5f417c5', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'In what way does Preact manage prop-types and validation differently to improve performance?', N'Senior', N'Preact treats prop validation as an entirely separate, optional layer rather than an integral part of the reconciliation core. This avoids the runtime overhead of checking property types during every render cycle, which is a significant performance gain in production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'032ecee1-581a-4438-92a4-2359a8866968', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does the Two-Phase Commit (2PC) protocol affect system availability?', N'Senior', N'2PC is a blocking protocol; if the coordinator fails after a participant has prepared a transaction but before it receives the commit/abort instruction, the participant remains locked. This resource contention can lead to cascading failures and significantly reduced availability during coordinator outages. Consequently, modern systems often favor Sagas or compensating transactions for long-lived processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fec7286b-081a-444f-9c74-235aa24b2a8a', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the security implications of Flask''s default cookie-based session implementation.', N'Senior', N'Since default sessions are stored on the client side, they are susceptible to tampering if the secret key is compromised, even if the session is cryptographically signed. Storing sensitive information in these sessions is dangerous, so they should be limited to non-sensitive data or replaced with server-side storage for high-security applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3297798b-0316-43da-b957-235b7d0b5381', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the role of the Python interpreter in executing code.', N'Middle', N'The Python interpreter reads source code, compiles it into bytecode, and then executes that bytecode on a virtual machine. This multi-stage process provides platform independence, as the same bytecode can run on any system with a compatible virtual machine. The interpreter also handles memory management and dynamic type checking during execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b23535e-2efc-4185-9702-235bc358c2e8', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you troubleshoot a performance issue in a microservices environment where the request spans many services?', N'Senior', N'I would use distributed tracing tools like Jaeger or Honeycomb to visualize the entire lifecycle of a request across service boundaries. By analyzing trace spans, I can pinpoint which specific service or network hop is introducing the latency or error, allowing for targeted remediation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4178122-c333-4d31-902f-235cfe4af950', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it important to document the steps taken during debugging?', N'Fresher', N'Documentation helps track what has already been tried, preventing redundant work. It also provides a knowledge base for future issues and aids in the final post-mortem analysis of the incident.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11d8093f-247b-46dd-8e7c-235d424a63cd', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the difference between Astro''s default behavior and client-side hydration directives?', N'Middle', N'By default, Astro renders components as static HTML with zero JavaScript. Hydration directives like client:load or client:visible tell Astro to bundle the necessary JavaScript for specific components to make them interactive in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2052e99-7a9d-4929-ac2b-235e73dc84d2', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Why is ''Idempotency'' critical in distributed event-driven systems?', N'Senior', N'Distributed systems often suffer from ''at-least-once'' delivery, where messages can be retried or duplicated due to network failures. Idempotent design ensures that processing the same message multiple times has the same effect as processing it once, preventing data corruption or inconsistent states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36374057-7647-4eb4-a399-236271ea20c6', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How do you handle dependency injection in Fiber?', N'Middle', N'Dependency injection in Fiber is usually handled by initializing dependencies outside the handler functions and passing them via closures or struct methods. Since Fiber handlers are typically closures, you can capture injected services or database connections from the outer scope to be used at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9309634e-ad3e-4eb0-b895-23651c3b1809', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the purpose of a technical design document?', N'Intern', N'A design document outlines the architecture, logic, and reasoning behind a proposed solution before implementation begins. It serves as a blueprint for the team to review, ensuring that the approach aligns with project goals and technical constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5153b35-7181-46b4-baca-23660b6aa2ae', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What architectural benefit does the ''Single-Table Design'' pattern offer?', N'Senior', N'Single-table design allows developers to model complex, relational-style data structures into a single DynamoDB table by using overloaded keys and indexes. This reduces the need for cross-table joins, simplifies data retrieval into single requests, and improves overall system performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55606127-2706-42a1-bf52-2366f055d321', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a cluster state?', N'Intern', N'The cluster state is a collection of information about the cluster, including node metadata, index settings, and shard allocation. It is maintained by the master node and synchronized across all nodes in the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'deaf9921-5b87-470c-9d46-23672e06aae1', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between synchronous and asynchronous processing for a task?', N'Fresher', N'Synchronous processing is simpler to implement and debug but can block the main execution thread, leading to a poor user experience. Asynchronous processing improves responsiveness and concurrency but increases complexity in error handling and state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b82ed1ec-d6f9-47fb-bd0f-236c04a1d087', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does the @warn directive differ from @error?', N'Middle', N'The @warn directive prints a message to the console during compilation without stopping the build process, which is useful for suggesting best practices. The @error directive stops the compilation entirely, which is intended for catching critical configuration failures or invalid inputs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8ca3a76-93bc-49c0-a5e6-236d2911230d', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are Rails migrations and why are they important?', N'Junior', N'Migrations are a feature that allows you to evolve your database schema over time in a consistent and version-controlled way. Instead of writing raw SQL, you use Ruby to define changes to tables, which makes it easy to share schema updates across different development environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f16cf2d-fa17-48e7-9692-23705401c9e3', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is a derived signal?', N'Intern', N'A derived signal is a value that is calculated based on one or more existing signals. Whenever the base signals change, the derived signal automatically updates its value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a6405d7-be03-447b-9194-2373d7d32254', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the impact of using ''ajv'' for request validation in Fastify?', N'Senior', N'Ajv provides extremely fast JSON schema validation by compiling schemas into optimized JavaScript functions. By validating incoming requests at the edge of the application, Fastify prevents malformed or malicious data from reaching the core business logic, ensuring input integrity with minimal performance overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd604af7-dd65-41dd-8392-2373ef061c05', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Discuss the performance implications of deep DOM nesting in modern browser engines.', N'Senior', N'Deeply nested DOM trees increase the complexity of the style recalculation and layout phases, as the browser must traverse further up and down the tree for every change. This can significantly increase the time spent in the rendering pipeline, potentially leading to frame drops during complex animations or dynamic updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'346c31a6-5c29-4b06-ac6e-23763d4aeadc', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro handle CSS styling?', N'Intern', N'Astro allows you to write CSS in standard style tags. It also supports scoped styles, which automatically ensure that CSS written for one component does not accidentally affect other parts of the site.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82939438-7599-40cd-bd2f-237646f07616', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Explain the role of the @Introspected annotation.', N'Junior', N'The @Introspected annotation tells Micronaut to generate bean introspection metadata at compile-time. This allows the framework to access bean properties and methods without using slow runtime reflection, which is crucial for performance and compatibility with GraalVM native images.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6416d3d3-59c6-42ba-ba4a-2378221a4395', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you defend against supply chain attacks in a JavaScript ecosystem?', N'Fresher', N'Supply chain attacks target dependencies, build tools, and CDN resources rather than your application code directly. Defending against supply chain attacks in JavaScript requires securing three distinct vectors: * third-party packages (npm), * build-time infrastructure (CI/CD), and * runtime execution (the browser). 1. Lock Down the Registry & Dependencies (Package Time) The primary entry point for malicious code is the npm registry through typosquatting, account takeovers, or compromised dependencies * Enforce Dependency Pinning: Never use loose version ranges (^ or ~). Pin your versions exactly and commit your package-lock.json, pnpm-lock.yaml, or yarn.lock to ensure identical builds across environments. * Run Manifest Validation: Use tools like lockfile-lint in your pre-commit hooks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2627a9e-8c29-4bfa-b74e-23783c5457ad', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How can you optimize binary size and startup time for Axum-based microservices?', N'Senior', N'To optimize for deployment, developers can use link-time optimization (LTO) during compilation, strip debug symbols, and use a minimal base image like Distroless. Additionally, reducing dependencies and using feature flags to disable unused framework components can further shrink the binary footprint and improve cold-start performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c733253a-4eda-4b66-806f-2379546b93f3', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Describe the ''Thundering Herd'' problem in the context of database scaling.', N'Senior', N'The Thundering Herd occurs when a frequently accessed cache key expires, causing multiple concurrent application requests to hit the database simultaneously to regenerate the value. It can be mitigated by implementing mutex locks, probabilistic cache refresh, or background recomputation to protect the database from sudden spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2302f9a8-c274-4be8-8ac3-23795b61f97b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of the ''Write Barrier'' in concurrent garbage collection?', N'Senior', N'A write barrier is a mechanism used to maintain consistency during concurrent GC by intercepting pointer updates. It ensures that the collector remains aware of any modifications made to the object graph while the background marking phase is running.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7768e987-541c-4b97-8533-237a1a03f59f', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the purpose of the Consistency property?', N'Intern', N'Consistency ensures that a transaction takes the database from one valid state to another valid state. It maintains all predefined rules, such as constraints, cascades, and triggers, so no data is corrupted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94013e06-727f-4dc1-a933-237a990bc25b', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How does caching improve application performance?', N'Middle', N'Caching stores frequently accessed data in high-speed memory, allowing the system to serve requests much faster than by querying a primary database. It reduces the computational load on backend services and minimizes latency for end-users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83facb6c-622f-4024-bca1-237b422e9ae9', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis ensure atomicity?', N'Fresher', N'Because Redis is single-threaded, each command is executed atomically. This ensures that no other client can interrupt a command while it is being processed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
