INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'850fc5ff-93aa-4096-a772-237cb9060f17', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why is choosing a good Partition Key important?', N'Intern', N'Choosing a good partition key is crucial for distributing data evenly across partitions. A poor key can result in ''hot partitions,'' where one partition receives significantly more traffic than others, leading to performance bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
