INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'113226ee-db91-4afe-b350-2380dfb4fd06', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Can a function return multiple values in Go?', N'Intern', N'Yes, Go functions can return multiple values simultaneously. This is commonly used to return a primary result along with an error value to indicate success or failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ebbccf9-bf1a-4b52-9981-23811e7cbfcb', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between documentation and development speed?', N'Fresher', N'Writing thorough documentation slows down the immediate development cycle but drastically reduces time spent in knowledge transfer and debugging later. A lack of documentation leads to faster initial delivery but creates significant ''technical debt'' for future maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08ae33f4-af79-419d-b08f-238546155182', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of ''Portal'' in SolidJS?', N'Senior', N'Portals allow rendering a component''s children into a different part of the DOM tree, such as a modal or tooltip outside the main application container. This is essential for handling CSS stacking contexts while maintaining the component''s logical placement in the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63efc4be-a4e2-4643-955b-23868fe1d838', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Can you define custom route patterns in Chi?', N'Junior', N'Yes, Chi supports custom patterns, including wildcards and regex-like behavior within the route definition. This allows for complex routing requirements while keeping the code organized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db0d2db5-167f-43da-9285-23871039a7cd', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Is Dart a garbage-collected language?', N'Intern', N'Yes, Dart uses a generational garbage collector to manage memory. This system efficiently reclaims memory by focusing on short-lived objects, which is common in UI-heavy applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfa875aa-d7b4-4946-b27e-23885a8ac98e', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why might you choose a monolithic architecture over microservices for a new project?', N'Junior', N'For a small team or a project in the early stages, a monolith is often easier to deploy, test, and manage due to lower operational complexity. I would choose a monolith to allow for faster iteration and to avoid the overhead of distributed systems until the application actually outgrows the initial architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35462ef1-7c28-4ff0-a7e1-2388ddcf53b2', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between an Access Exclusive lock and a Row Exclusive lock in terms of database concurrency?', N'Senior', N'A Row Exclusive lock is acquired for standard data modifications like updates or deletes, allowing other concurrent transactions to read and write to the table. An Access Exclusive lock is the most restrictive, preventing any concurrent access to the table, and is typically required for structural changes like ALTER TABLE or DROP TABLE.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5741d7b-6e29-4413-82e6-238957a5f2f9', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the benefit of Micronaut’s ''Client'' annotation for HTTP communication?', N'Middle', N'The @Client annotation allows for the declarative definition of HTTP clients, where the implementation is generated at compile-time. This ensures type safety for API calls and provides built-in support for retries, load balancing, and timeouts without manual boilerplate code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88625236-4563-4a3a-b42d-238d8901b844', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle a situation where a third-party API is unstable?', N'Middle', N'I would wrap the third-party client with a retry policy using exponential backoff to handle transient errors. Additionally, I would implement a bulkhead pattern to isolate these calls and ensure that failure in the third-party service does not consume all resources in my application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb1fa56e-d724-448a-8de4-238e97093556', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle progressive enhancement when JavaScript fails to load?', N'Senior', N'Remix is built on standard Web Fetch and Form APIs, meaning forms and links function natively via the browser even without client-side hydration. By utilizing standard HTML form submissions, the application remains fully functional in degraded network conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c055d7a7-91d8-4d1e-a785-238eec1d28d2', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart handle hot-reload, and what are the requirements for a library to support it?', N'Senior', N'Hot-reload works by injecting new source code into the running VM while preserving the current state of the heap, including object instances. For this to function, the state must be compatible with the new code changes; major structural changes to classes often require a full restart to ensure the heap remains consistent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfc3ed96-f9de-409d-8cb7-238fae963d83', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How do you install a new Vite project?', N'Intern', N'A new Vite project is typically initialized using a command-line interface tool, such as ''npm create vite@latest''. This command prompts the user to select a framework and language template to generate the necessary files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'944a50ad-1b6a-45b3-91a6-23905bb8b797', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a rune in Go?', N'Fresher', N'A rune is an alias for int32 and is used to represent a single Unicode code point. It is used when you need to process strings as a sequence of characters rather than as a sequence of raw bytes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62b2981c-e00f-48e3-878b-2392821add61', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain the role of ''Hooks'' in the Lucid ORM lifecycle and their architectural dangers.', N'Senior', N'Hooks allow for executing logic before or after database lifecycle events, providing a way to handle side effects like cache invalidation or audit logging. However, excessive use of hooks can lead to hidden dependencies and complex, hard-to-debug side effects that violate the principle of single responsibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20991fdc-f0e3-4324-804e-2393ec66565d', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Explain the concept of reactivity in Svelte.', N'Fresher', N'Reactivity in Svelte is triggered by simple variable assignments. When a variable is updated in a component, Svelte automatically detects the change and updates the corresponding part of the DOM, eliminating the need for complex state management hooks or virtual DOM diffing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3a035f5-0170-4326-9b8d-2395a15c855c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What does it mean to design for ''extensibility'' in a software system?', N'Intern', N'Designing for extensibility means building the system so that new features can be added with minimal impact on existing code. This is achieved by adhering to principles like modularity and loose coupling, ensuring that the system can evolve without requiring a total redesign.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5437c507-f95e-404f-8e6d-23962de540e8', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Discuss the architectural advantage of using ''View'' modules to prepare data for templates.', N'Senior', N'View modules act as a transformation layer that cleans and formats raw data from the database before it reaches the template. This separation of concerns ensures that templates remain logic-free and that data formatting is testable and reusable across multiple endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b5ab739-feb7-4304-a5c2-239aa738d467', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why might you prefer to use a PSR-3 compliant logging library over custom file-writing code?', N'Middle', N'PSR-3 provides a standard interface for loggers, allowing you to swap logging implementations without changing your application code. This flexibility enables developers to switch from local file logging to cloud-based monitoring services seamlessly while maintaining consistent logging behavior across the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f457cd76-5210-4993-a431-239d494b7d95', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the risk of using ''attach()'' in R?', N'Middle', N'The attach function adds a data frame or list to the search path, which can lead to ambiguity and shadowing of existing variables. It is generally discouraged because it makes it unclear where a variable is being retrieved from, making the code harder to debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f19a2cf-403d-412e-b3c4-239ece903276', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI support database integration?', N'Junior', N'FastAPI is database-agnostic, meaning it doesn''t force a specific database or ORM. Developers typically use SQLAlchemy or Tortoise ORM along with the dependency injection system to provide a database session to each request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d18666e-4f9d-47e8-9da5-23a2493779c9', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Describe the internal mechanism and impact of Global Secondary Indexes (GSIs).', N'Senior', N'A GSI is an asynchronous index that maintains its own partition and sort key space, separate from the base table. Updates to the base table are propagated to the GSI via an internal stream, which introduces a slight replication lag and consumes independent throughput capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68e04703-9fc8-48f9-8f87-23a27d251607', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the implications of using ''Object.assign'' versus the spread operator for object merging?', N'Senior', N'Both perform shallow copies, but the spread operator is generally more concise and readable within expressions. ''Object.assign'' modifies the target object if provided, which can lead to unexpected side effects if not used carefully, whereas the spread operator creates a brand new object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac35b556-e6e4-4c42-ac9e-23a4f982c5d9', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle form submissions compared to traditional React state-based forms?', N'Middle', N'Remix leverages standard HTML form behavior, allowing forms to work even if JavaScript fails to load. It uses the action function to handle mutations server-side, which automatically triggers a revalidation of all active loaders to keep the UI in sync.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f8f26b9-b38c-4e23-8c46-23a6b4138049', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Explain the mechanics of the refresh interval and its impact on near real-time search capabilities.', N'Senior', N'The refresh interval defines how often the in-memory buffer is flushed to a new Lucene segment, making documents searchable. Shorter intervals improve search latency but increase I/O overhead, while longer intervals improve indexing performance at the cost of visibility delay.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'009d4674-fd2a-43a8-83ec-23a8b2fed2c5', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi implement route grouping?', N'Middle', N'Route grouping is implemented through the ''Group'' method, which creates a new router instance that inherits the configuration of the parent. This allows for clean separation of concerns and middleware application without cluttering the main router definition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5a510c6-879a-4adc-862a-23a94ca5bb8e', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the role of NestJS ''Lifecycle Events'' (onModuleInit, onApplicationBootstrap) in complex deployments.', N'Senior', N'These events allow developers to execute specific logic at different phases of the application startup, such as warming up database connections or establishing socket connections. Proper use ensures that the application is fully prepared to handle traffic before it begins accepting requests, preventing race conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b999b87-8d3f-4e81-854c-23a950533972', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How do you configure application properties in Quarkus?', N'Junior', N'Quarkus uses an application.properties file located in the resource folder to store configuration settings. It also supports environment variables and system properties, which follow a specific hierarchy to allow for easy overrides in different deployment environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3affdc9-1d5e-4982-ae9a-23aa8bbcf3cf', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you explain the concept of ''latency'' to a non-technical stakeholder?', N'Intern', N'Latency is the time delay between sending a request and receiving a response. Think of it like the time it takes for a message to travel from one person to another; lower latency means a faster, more responsive experience for the user. High latency can make an application feel sluggish or unresponsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'631a7427-f288-4c09-b9f8-23aad3389a04', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What are the advantages and disadvantages of using a microservices architecture versus a monolith?', N'Middle', N'Microservices offer better scalability, independent deployments, and technology flexibility, but introduce significant operational overhead and complexity in network communication and data consistency. A monolith is easier to develop, test, and deploy initially but becomes difficult to scale and maintain as the team and codebase grow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd6c51e6-4854-4270-acad-23aba4f2337e', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How do you pass data from the frontmatter to the HTML template in an Astro file?', N'Intern', N'You can use curly braces to embed JavaScript variables defined in the frontmatter directly into the HTML markup. This is similar to the syntax used in other template engines or frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c909518-947b-4d3e-afc4-23ad33736da2', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between a default parameter and an optional parameter?', N'Junior', N'A default parameter provides a fallback value if the caller does not supply an argument for that parameter. An optional parameter allows the caller to pass nil as an argument, which must be handled explicitly within the function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baaf4cb6-82e7-4734-8f44-23b03c1a50f6', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are constant variables in PHP?', N'Fresher', N'Constants are identifiers for simple values that cannot be changed during the execution of the script. Once defined using the define function, they remain constant for the entire duration of the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d74484c-71df-4d1f-8924-23b171dcc595', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the purpose of lazy loading in Qwik?', N'Intern', N'Lazy loading in Qwik ensures that only the code required for the current user interaction is downloaded. This significantly reduces the initial bundle size and improves the time-to-interactive metric.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f848576-7b11-42a6-acb4-23b1d340fcfe', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is a parameter route in SvelteKit?', N'Junior', N'A parameter route is a dynamic path defined by square brackets in a directory name, such as [id]. It allows the application to capture variable parts of the URL and use them to fetch specific content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77e1c278-9e23-42ee-9742-23b5c2747c2c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide whether to build a custom internal tool or purchase an off-the-shelf solution?', N'Middle', N'I buy if the solution is non-core to the business and a reliable vendor exists. I build only if the requirement is a unique competitive advantage or if existing tools fail to integrate with our core infrastructure, making the maintenance of a custom solution more cost-effective than the operational pain of a poor integration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ad0c299-5dba-46f0-8075-23b62d8e2d63', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle accessibility (a11y) at the compiler level?', N'Senior', N'Svelte includes a built-in static analysis tool that warns developers about potential accessibility violations, such as missing alt text or incorrect ARIA roles, during the build process. This enforces accessibility standards as a first-class citizen of the development lifecycle rather than an afterthought.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c47eba3e-2177-44ed-b335-23bb9eec0c2e', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of the ''mut'' keyword?', N'Intern', N'The ''mut'' keyword is used to explicitly opt into mutability for a variable or reference. By requiring this keyword, Rust makes it clear to the reader and the compiler that a value is intended to be modified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1801aeb1-ea08-4f02-9db7-23be2091344e', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is error handling a critical part of system design?', N'Intern', N'Robust error handling prevents a system from crashing due to unexpected inputs or failures. It ensures that the system provides helpful feedback to users and logs sufficient information for developers to diagnose and fix the root cause.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c0db235-6ff1-4efc-8a89-23be8acd5cdd', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel handle Environment Configuration?', N'Fresher', N'Laravel uses a .env file located at the root of the project to store sensitive configuration variables like database credentials and API keys. This keeps environment-specific settings separate from the application code, enhancing security and portability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba331614-4da0-425b-a0ca-23c064cf69a9', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is ''nodemon'' in the Express development workflow?', N'Fresher', N'Nodemon is a utility that monitors for any changes in your source files and automatically restarts the server. This eliminates the need to manually stop and start the server every time a code change is made.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'710f3262-b8d0-4a24-b50f-23c1cc823423', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Explain the concept of ''At-most-once'' delivery.', N'Middle', N'At-most-once delivery means a message is either delivered once or not at all, with no retries. This is suitable for scenarios where losing a few messages is acceptable, such as high-frequency sensor readings, and low latency is the highest priority.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff6339dd-e45d-4a49-a998-23c6471da229', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix achieve progressive enhancement?', N'Intern', N'Remix supports progressive enhancement by ensuring that core features, like form submissions, work with basic HTML before JavaScript is even loaded. Once the JavaScript bundle arrives, Remix enhances the experience with smoother client-side navigation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1436fd42-b45c-4485-9543-23c6c962e6e5', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS middleware handle request lifecycle management differently than Express-based frameworks?', N'Senior', N'AdonisJS uses a strictly typed, onion-like middleware pattern that is deeply integrated with the framework''s execution pipeline. Unlike Express, which relies on manual callback invocation, AdonisJS manages the ''next'' function invocation internally, reducing the risk of orphaned requests and ensuring consistent error handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9823e53a-b37b-4a78-978a-23c79b9c1043', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What are the performance implications of using complex selector matching?', N'Senior', N'Browsers match CSS selectors from right to left, meaning the rightmost part is the key selector. Highly specific or deep selectors force the browser to traverse more of the DOM tree during style recalculation, increasing the computational cost compared to simple class-based selectors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'983afbd7-fde9-4a12-b25a-23c7b1954d0e', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Describe the ''Circuit Breaker'' state machine.', N'Senior', N'A circuit breaker transitions between Closed, Open, and Half-Open states. It stays closed during normal operation, opens when error thresholds are exceeded to block traffic, and enters half-open to test if the service has recovered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'010e4ac3-e196-483f-8168-23c9442b6514', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is a Blade Template Engine?', N'Intern', N'Blade is the templating engine provided with Laravel. It allows you to write plain PHP code in your views while providing convenient shortcuts for common tasks, such as printing data or using control structures like loops and conditionals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'072778db-0d02-465c-aef1-23c99a7ee865', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why do I need to use the freeze method', N'Fresher', N'In the Object-oriented paradigm, an existing API contains certain elements that are not intended to be extended, modified, or re-used outside of their current context. Hence it works as the final keyword which is used in various languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ff7582a-fed5-4e75-9216-23ca84af0ec0', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How do you implement graceful shutdown in a Node.js application?', N'Senior', N'Graceful shutdown involves catching termination signals, stopping the server from accepting new connections, finishing existing requests, and closing database connections. It is critical to ensure that no data is lost or corrupted during the transition. Using a timeout to force-exit if the shutdown takes too long is standard practice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed794555-7daf-4b66-9f32-23ca8546544f', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason about the technical debt versus feature velocity trade-off?', N'Senior', N'I quantify the impact of technical debt on current development speed and system stability. If the debt prevents new feature delivery or increases operational risk, I advocate for allocating a fixed percentage of each sprint to refactoring, treating it as an investment in sustainable velocity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9669241-2431-4736-b46f-23cbc89111e0', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the role of the VACUUM process and why it is critical for PostgreSQL maintenance.', N'Middle', N'VACUUM reclaims storage occupied by dead tuples created during updates or deletes, making that space available for reuse. Without regular vacuuming, the database will experience table bloat, leading to larger table scans and degraded query performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4d27e93-d08c-4507-a9cb-23ce3b9d8dff', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the ''DOM node leak'' problem in jQuery?', N'Middle', N'If you remove elements from the DOM using native methods instead of jQuery''s built-in removal methods, jQuery''s internal event listeners and data cache attached to those nodes may not be garbage collected. This leads to memory leaks, as the browser continues to hold references to the ''removed'' elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4efea743-7a1b-4964-a0f5-23d0cb9cdee2', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How does technical debt influence trade-off analysis?', N'Intern', N'Technical debt represents a trade-off where short-term speed is prioritized over long-term code quality. It is acceptable if it is intentional and managed, but it requires future effort to pay down the debt to ensure system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ae3eab1-0f12-47c3-9807-23d10aa483e2', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What are the architectural risks of overusing client-side directives in an Astro application?', N'Senior', N'Excessive use of hydration directives can re-introduce the performance bottlenecks of heavy SPAs, such as increased Total Blocking Time and larger JavaScript bundles. It undermines the ''zero-JS'' philosophy, leading to slower load times on low-end mobile devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adef843b-c67e-455e-ae27-23d3122d0532', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'When would you choose to use a custom ''HTTP'' server instance with Fastify instead of the default?', N'Senior', N'You might use a custom server instance when you need to integrate with specific legacy infrastructure or require advanced configuration, such as custom TLS/SSL settings or specialized socket handling. Fastify''s flexibility allows it to wrap any standard Node.js HTTP server implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07569244-aefb-4fbc-b8ab-23d622e8bc26', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between a shallow copy and a deep copy?', N'Intern', N'A shallow copy duplicates the values of the member variables, which can lead to multiple objects pointing to the same dynamic memory. A deep copy creates a new instance of the dynamic memory for the new object, ensuring that the original and the copy are independent. Deep copies are essential when a class manages resources like heap memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67c4d5fc-4e30-491e-9d59-23d6a32612b6', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are SvelteKit routes?', N'Intern', N'Routes in SvelteKit are defined by the directory structure within the src/routes folder. Each folder represents a URL path, and specific files like page.svelte files define the user interface for that path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77e4d713-5296-4f09-86ad-23d87983b92d', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the difference between ''container'' and standard layout classes?', N'Junior', N'The ''container'' class is a utility that sets the max-width of an element to match the current breakpoint. It is used to center content on the page, whereas standard layout utilities like flex or grid control the positioning and alignment of items within a container.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1f8d24e-0e89-475e-a116-23da6036a0c3', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the main drawback of denormalization in NoSQL?', N'Junior', N'The main drawback is data redundancy and the risk of data inconsistency. Because data is duplicated, updating a single piece of information may require updating multiple records, which increases complexity and the potential for data anomalies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06c071be-40a4-4833-916b-23db336c9802', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the benefit of using Echo''s ''Logger'' middleware compared to raw logging in every handler?', N'Senior', N'The Logger middleware provides a centralized way to capture request metadata like duration, status codes, and IP addresses, ensuring consistent observability across the platform. This avoids code duplication and ensures that every request is logged, even if the application logic fails prematurely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e79bab6-07cb-41d2-9afa-23dce64c9e12', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If you find that a requirement is technically impossible to implement within the project constraints, what do you do?', N'Junior', N'I would document the technical limitations and present them to my team lead along with potential alternatives or workarounds. Providing options demonstrates that I have thought through the problem and am looking for a constructive path forward.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2c10b8c-7215-49e8-b863-23e2d2366620', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What does Fastify''s ''encapsulation'' mean for variable scope?', N'Fresher', N'Encapsulation means that any modifications to the Fastify instance, such as adding decorators or plugins, made inside a plugin are local to that plugin and its children. This prevents conflicts when different parts of an application define the same decorator name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3932645d-636a-4403-9735-23e3ab0e3146', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between a Partial View and a View Component?', N'Fresher', N'A Partial View is a simple way to render a piece of HTML and is best for static content. A View Component is more complex, has its own C# logic class, and is better suited for dynamic data-driven content that needs to be reused across the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81e1e375-2986-4593-8e2b-23e42c9a6ed4', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact''s virtual DOM differ in memory usage?', N'Middle', N'Preact''s virtual DOM nodes are simpler objects with fewer properties, resulting in a significantly lower memory footprint during the diffing process. This efficiency allows Preact to perform faster initial renders and updates on resource-constrained devices compared to the more feature-rich React virtual DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d3b13af-0af2-45e1-8c73-23e83d377588', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between centralized and decentralized system control?', N'Intern', N'Centralized control is usually easier to manage and secure, but it can become a single point of failure and a bottleneck. Decentralized control increases resilience and scalability but introduces significant challenges in data consistency and system coordination.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
