INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fb643e9-b78c-4c9f-ac08-23f9172f3ee7', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Is Alpine.js suitable for large-scale applications?', N'Fresher', N'Alpine.js is primarily intended for smaller projects, interactive UI components, or enhancing static sites. While it can be used in larger applications, it lacks the architectural structure, state management, and routing capabilities typically required for complex, enterprise-level web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1a5473e-95e3-414b-9351-23fbf1da5507', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How can query optimization help avoid database scaling issues?', N'Middle', N'Effective query optimization reduces the load on the database engine by ensuring queries use indexes, avoiding unnecessary joins, and minimizing the amount of data transferred. Often, well-optimized queries can postpone the need for expensive horizontal scaling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2626e12-a6e2-41d3-ac4b-23fcbcf8abbb', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the architectural utility of R''s ''promises'' in lazy evaluation.', N'Senior', N'Promises act as placeholders that store the expression, the environment where it was defined, and a cached value once evaluated. This architecture allows R to defer expensive computations until the last possible moment, optimizing execution flow in complex workflows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
