INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26be16e4-a2ee-41ee-aba3-2400480deba4', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is FastAPI and what is its primary advantage?', N'Fresher', N'FastAPI is a modern, high-performance web framework for building APIs with Python based on standard type hints. Its primary advantage is its speed, which is comparable to NodeJS and Go, thanks to its foundation on Starlette and Pydantic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82c0157a-9235-4940-a4e9-24005eb3b543', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle concurrency compared to traditional synchronous frameworks like Flask?', N'Middle', N'FastAPI is built on Starlette and uses an asynchronous event loop, allowing it to handle many concurrent connections without the overhead of threads per request. Traditional synchronous frameworks typically require a multi-process or multi-threaded worker model to achieve similar concurrency, which consumes more memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd537347-cf4b-4a36-bb63-2401b26a631d', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Explain the significance of the Alpine.js reactivity system compared to proxy-based systems.', N'Senior', N'Alpine.js uses a custom reactivity engine that tracks dependencies through variable access within expressions. It provides a lightweight alternative to the deep proxy observation found in Vue 3, prioritizing small bundle size and seamless integration into server-side rendered templates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f36be799-9d94-4de1-8967-2403e8e41b7f', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What role do ''finalizers'' play in Go, and why are they generally discouraged?', N'Senior', N'Finalizers allow for the execution of code when an object is garbage collected, but they provide no guarantees regarding exactly when they will run. They are discouraged because they can delay memory reclamation, increase garbage collector complexity, and make the lifetime of objects unpredictable, often leading to subtle race conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a1070ac-67c3-4b2d-9520-2403f5a29e78', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What does the Echo ''Start'' method do?', N'Intern', N'The Start method initializes the HTTP server and begins listening for incoming requests on a specified address. It blocks the execution until the server is shut down or an error occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eec5c818-4d70-44d5-b1cc-240446eff818', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Describe how MongoDB handles ''Stale Reads'' in a distributed environment.', N'Senior', N'Stale reads occur when a client reads from a secondary that has not yet caught up with the primary''s state. To mitigate this, MongoDB offers ''causal consistency'' via sessions, which forces the client to read data that is at least as recent as its previous writes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7d55c86-e84a-4431-998c-2407ae8b1401', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of the const qualifier, and does it guarantee true immutability?', N'Middle', N'The const qualifier indicates that a variable should be treated as read-only by the compiler, providing a layer of safety against accidental modification. However, it does not guarantee absolute immutability because the value can often be changed by casting away the const qualifier or by modifying the underlying memory address directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7a6dfa9-8855-40da-975c-240c16312f29', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus handle dependency injection compared to traditional frameworks?', N'Intern', N'Unlike traditional frameworks that perform dependency injection at runtime, Quarkus performs as much wiring as possible at build time. This reduces the CPU and memory overhead during application startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf99813a-2dcf-440d-acd3-240d4bbf7510', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Can you use Tailwind CSS with standard HTML files?', N'Fresher', N'Yes, you can use Tailwind CSS with plain HTML files by including the compiled CSS file in your head tag. You can also use the Tailwind CLI to watch your HTML files and generate the necessary CSS automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2058559-ccd1-4528-b1c2-240e634facd8', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is a cookie in Express?', N'Intern', N'A cookie is a small piece of data sent from the server and stored on the user''s browser. In Express, cookies are typically managed using the cookie-parser middleware to read and set cookie headers in the HTTP request and response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e2f585f-4c62-4858-9456-2410d27643bb', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of the Cargo tool?', N'Junior', N'Cargo is Rust''s build system and package manager. It handles tasks such as downloading dependencies, compiling your packages, and running tests, simplifying the development workflow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61ae30af-bc7c-44d3-a969-2412243f02d3', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is meant by the ''N+1 query problem'' in the context of database design?', N'Middle', N'The N+1 problem occurs when an application makes one query to fetch a list of items and then makes an additional query for each item to fetch related data. It is a design anti-pattern that can be solved by using eager loading, joins, or batch fetching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b316890-c911-4ffa-9dd0-2412f2897cd1', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you diagnose a situation where an application is experiencing high thread contention?', N'Senior', N'I would take multiple thread dumps to identify which threads are waiting for the same locks or resources and analyze the call stacks to determine the origin of the contention. I would then evaluate if the locking granularity can be reduced, if lock-free data structures can be used, or if the number of worker threads needs to be adjusted based on the hardware capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8dbed376-90fd-4edd-9326-24148769a4b6', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is a primary constructor in Kotlin?', N'Intern', N'A primary constructor is part of the class header and is declared immediately after the class name. It provides a concise way to initialize properties of a class directly when it is instantiated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72b773e2-bbba-4943-aff9-24158efe99db', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the ''disconnectedCallback'' used for?', N'Junior', N'This lifecycle method is called when a component is removed from the document. It is typically used for cleanup tasks, such as removing event listeners or clearing timers, to prevent memory leaks in the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b2017a7-af6f-4e17-85fc-24159c8470bf', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How does the Database-per-Service pattern affect reporting and analytics requirements?', N'Senior', N'Since data is siloed, traditional join queries across services are impossible. You must implement an event-driven data pipeline to sync data into a dedicated read-only analytical store or data warehouse, often using Change Data Capture to maintain eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f31e58a-5fe9-4d1a-9927-2415a007e707', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the ''autovacuum'' daemon, and why is disabling it generally discouraged?', N'Senior', N'Autovacuum automates the cleanup of dead tuples and updates statistics for the planner. Disabling it leads to severe table bloat, performance degradation, and potential transaction ID wraparound, which can halt database operations if not managed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
