INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11e06915-4386-4c08-85fb-241a291f0ba2', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between the String class and the StringBuilder class?', N'Junior', N'String objects are immutable, meaning any change to the string creates a new object in memory. StringBuilder is mutable, allowing for efficient modifications to a sequence of characters without creating unnecessary intermediate objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
