INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69d83174-ba0a-489b-8d44-241dcf5279f2', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does the Kotlin compiler handle ''companion objects'' in terms of bytecode generation?', N'Senior', N'The compiler creates a static nested class for the companion object and adds a static field to the enclosing class to hold the instance. This ensures that the companion object behaves like a singleton, providing a clean way to host static-like members while still allowing the companion to implement interfaces or inherit from classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24ffb0f2-71cc-483a-868f-241e2149fe5e', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How would you handle a production issue where you suspect a bad configuration change, but multiple deployments occurred recently?', N'Senior', N'I would use an audit log of all configuration changes and deployment timestamps to correlate the onset of the issue with the specific change event. I would then perform a ''binary search'' approach, reverting the most recent changes or comparing the current state against a known-good configuration snapshot until the problematic setting is isolated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
