INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37eea286-c654-4f5e-877f-24258d576d8e', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Describe the role of the ''Code Cache'' in the JVM and what happens when it becomes full.', N'Senior', N'The code cache is a dedicated memory region that stores the native machine code generated by the JIT compiler. If the code cache becomes full, the JVM stops compiling new methods, forcing the application to run in interpreted mode and leading to a significant performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ec17756-bdb1-496d-a136-24267ec621a9', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you ensure zero-downtime deployments for a stateful service?', N'Middle', N'I would use a blue-green or canary deployment strategy combined with an abstraction layer for data migration. Ensuring backward compatibility of the database schema is critical so that both the old and new versions of the application can operate concurrently during the transition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'697a9225-a730-4699-a07a-24283fc94876', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What approach do you take when debugging a race condition that occurs only under high load?', N'Middle', N'Since race conditions are timing-dependent, I would use load testing to simulate high-concurrency scenarios in a controlled environment. I would focus on auditing shared state access patterns and looking for improper synchronization mechanisms that might fail under heavy contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
