INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0bc4af1-c647-4dfb-9c75-2438770adc93', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the role of the @Singleton annotation?', N'Junior', N'The @Singleton annotation defines a bean that is created only once within the application context. Every time the bean is injected elsewhere, the same instance is reused, which is efficient for stateless services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
