INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95c0de8d-dbd8-4be5-a36c-243afa835743', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the benefit of Preact''s ''options'' object for advanced architectural customization?', N'Senior', N'The ''options'' object provides a hook-like API for intercepting internal framework operations such as VNode creation or component rendering. This allows developers to build global performance monitoring, logging, or custom rendering middleware without modifying the core framework code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78be360b-ccf6-4aef-be40-243e04d557e4', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the functional interfaces UnaryOperator<T>, DoubleUnaryOperator, IntUnaryOperatorand LongUnaryOperator?', N'Intern', N'UnaryOperator (unary operator) takes an object of type as a parameter T, performs operations on them and returns the result of operations in the form of an object of type T: * DoubleUnaryOperator- unary operator receiving input Double; * IntUnaryOperator- unary operator receiving input Integer; * LongUnaryOperator- unary operator receiving input Long.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f41f2d64-93ae-4244-9a61-243f2b8215c1', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is normalization in the context of MySQL?', N'Junior', N'Normalization is the process of organizing data in a database to reduce redundancy and improve data integrity. It involves dividing large tables into smaller, related tables and defining relationships between them to ensure that each piece of data is stored in only one place.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e32488f-edba-442d-a000-243f52237048', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django handle database migrations, and how do you mitigate risks during a zero-downtime deployment?', N'Senior', N'Django uses a state-tracking system to generate migration files that reconcile the model state with the database schema. To achieve zero-downtime, migrations must be backward-compatible, often requiring a multi-step process where schema changes and code deployments are decoupled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
