INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58643ea4-d09f-486f-90d9-24469e293233', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are the trade-offs of using ''method_missing'' in Ruby?', N'Middle', N'Method_missing allows for dynamic, flexible APIs and metaprogramming, enabling objects to respond to methods they do not explicitly define. However, it can make debugging difficult, obscure the API contract, and incur a performance penalty since it requires a full lookup cycle through the entire inheritance chain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'261270de-25d7-487c-8692-2446a24e1a68', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the impact of the ''defer'' and ''async'' attributes on the critical rendering path?', N'Senior', N'Both attributes allow scripts to download in parallel with HTML parsing, but ''async'' executes immediately upon download, potentially blocking the parser. ''Defer'' maintains the execution order and waits until the document is fully parsed, making it the superior choice for non-critical scripts that depend on the DOM structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2114a001-2e4f-4b50-a5e7-244865cf812d', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do you mitigate cascading failures in a distributed system?', N'Senior', N'Implement circuit breakers to fail fast when a dependency is unhealthy, preventing resource exhaustion. Additionally, use bulkheading to isolate failure domains and rate limiting to protect downstream services from traffic spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f461c2ea-ef84-4ff2-9340-244ac05d62d8', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a shared lock?', N'Fresher', N'A shared lock is requested when a transaction needs to read data. Multiple transactions can hold a shared lock on the same resource simultaneously, but they cannot modify it while the lock is held.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17aa0e4f-8930-43ec-a85b-244f8442f88d', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How can you implement authentication in a Next.js application?', N'Middle', N'Authentication is typically handled using middleware to protect routes by verifying user sessions before a request reaches the page. You can also manage authentication state via server-side sessions or cookies, which are then accessible within Server Components to verify permissions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29b57289-9e24-453f-84af-2450155b3db4', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle component lifecycle methods differently than React?', N'Senior', N'Qwik does not use traditional lifecycle hooks like ''useEffect'' in the same way, as they rely on the component being mounted and hydrated. Instead, Qwik uses reactive primitives that are designed to be triggered by state changes regardless of whether the component is currently ''mounted'' in the traditional sense.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1dd23e6a-f5ff-493f-9a37-24524ddc7569', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why might you choose a NoSQL database like DynamoDB over a Relational database?', N'Middle', N'DynamoDB provides predictable performance at any scale and eliminates the operational overhead of managing database servers. It is preferred when application requirements involve massive horizontal scaling, flexible schema design, and low-latency access to simple data models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7d92f87-3011-470b-866f-2453399b8084', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are asked to estimate how long a new feature will take to build, what is your process for breaking down the request?', N'Junior', N'I would start by breaking the feature into smaller, manageable functional components or user tasks. Then, I would identify potential dependencies or technical unknowns that might require research. Finally, I would provide an estimate range to account for unforeseen complexities and verify the requirements with stakeholders to ensure alignment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd48b1d13-16f2-4277-ae8d-24534bd19747', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Explain the trade-offs of using ''lit-html'' expressions versus manual DOM manipulation in a high-frequency update scenario.', N'Senior', N'Lit-html uses tagged template literals to create efficient, compiled update functions that only modify the parts of the DOM that have changed. Manual DOM manipulation, while potentially faster for single operations, is significantly more error-prone and complex to maintain, losing the declarative synchronization that keeps the UI consistent with the state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5a1a47d-b5d5-48f3-97bc-245951712e58', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the advantage of using SvelteKit over a standard Svelte app?', N'Intern', N'SvelteKit provides built-in routing, server-side rendering, and data fetching utilities that you would otherwise have to build yourself. It creates a standardized project structure that simplifies development and deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44a8b955-960d-4718-a6de-245abb7ac9ed', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach debugging an issue where the system behaves differently across different browser versions?', N'Middle', N'I would use browser-specific developer tools to inspect the console logs, network requests, and DOM state to pinpoint the incompatibility. I would also verify if the issue is related to CSS, JavaScript features, or API responses that differ based on headers. Once identified, I would implement polyfills or provide graceful degradation to ensure a consistent experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
