INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b543ca6-0818-43c5-a6ab-24605767965e', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the C# compiler implement ''async/await'' under the hood using state machines?', N'Senior', N'The compiler transforms an async method into a generated struct or class that implements a state machine. This state machine tracks the execution point and local variables, allowing the method to suspend execution and resume later without blocking the calling thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03ec7ca1-09c9-428f-9bea-2461b9c6c223', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does the ''Connect'' HOC differ from ''useSelector'' in terms of performance and lifecycle?', N'Senior', N'The ''Connect'' HOC uses context to inject state, which can trigger re-renders based on prop changes, while ''useSelector'' uses a subscription model that allows for more granular control over re-renders. ''useSelector'' is generally preferred in modern React for its ability to prevent unnecessary component updates and better integration with functional components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
