INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0708945b-50b9-4e9f-8947-246934d96f1c', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the primary trade-off when using Read-Your-Writes consistency?', N'Senior', N'Read-Your-Writes consistency ensures a user always sees the updates they just made, which improves user experience. The trade-off is increased architectural complexity, often requiring routing requests to the specific replica that received the write or utilizing version tokens to ensure the read replica is up-to-date.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'271fd2de-2d3e-4071-84a5-2469c57dd316', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What happens if a property is not declared as a reactive property?', N'Fresher', N'If a field is not declared with the @property decorator, changes to that field will not trigger an automatic update of the component. The component will only re-render if a reactive property is also changed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3751427-cccd-42fb-b8b5-246a8fb3aabb', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Does Go have a garbage collector?', N'Intern', N'Yes, Go has an automatic garbage collector. It manages memory allocation and deallocation, freeing developers from manual memory management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b54d6ca1-5616-4841-bc4a-246dbbef2f0b', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'In what scenario, if any, is it still theoretically sound to use jQuery in a new project?', N'Senior', N'It may be theoretically sound only in extremely constrained environments, such as a legacy server-side template system where minimal, read-only interactivity is required. However, even in these cases, native Vanilla JS is almost always a superior alternative due to its performance, lack of dependencies, and long-term maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0126d5f-634f-49e0-ae95-246e74cd2d16', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why might you choose to implement a custom middleware layer in Next.js versus handling authentication in individual pages?', N'Senior', N'Middleware allows for centralized logic execution, such as authentication checks or header manipulation, before a request reaches the route handler. By running at the edge, it prevents unauthorized requests from reaching the application logic, thereby improving security and reducing unnecessary compute costs for protected routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6038724d-b1b3-4d2d-acf4-24705ae71b23', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why is it important to define mappings explicitly?', N'Junior', N'Defining mappings explicitly prevents Elasticsearch from guessing field types, which can lead to inefficient storage or incorrect search results. It gives developers full control over how data is processed and indexed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbbb6a39-d9f2-4eef-a879-2475826e6c74', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the primary role of the ReactiveElement base class in Lit?', N'Middle', N'ReactiveElement is the foundation of Lit that handles property change detection and triggers the update lifecycle. It leverages the browser''s native Custom Elements API to manage attribute reflection and property synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e67176fe-8509-4cf2-beae-247744227c53', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the role of ''extern template'' in reducing compilation overhead?', N'Senior', N'The ''extern template'' keyword tells the compiler that a specific template instantiation is defined in another translation unit. This prevents the compiler from generating the same template code repeatedly across multiple files, reducing compilation time and decreasing the binary size by centralizing the instantiation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'029aef6c-0cfd-43f0-9cce-2477f3d5dd40', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Explain the trade-offs between using high-cardinality logs versus structured metrics for troubleshooting production issues.', N'Middle', N'Logs provide granular detail about individual request lifecycles, which is essential for understanding the sequence of events leading to a failure. Metrics, however, are more efficient for identifying trends and anomalies across large datasets, allowing for faster alerting and visualization of system health.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd0306cd-fbbf-49d4-8985-247a0e4c5d09', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between client-side rendering and server-side rendering?', N'Junior', N'I choose server-side rendering when SEO is critical or when the initial page load time is a priority for user experience. Client-side rendering is often preferred for highly interactive, complex applications where the user experience is better managed by a rich client-side framework after the initial load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8225891f-42b0-4320-a7aa-247e8924e312', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s Copy-on-Write (COW) mechanism function at the architectural level for collection types?', N'Senior', N'COW is implemented by checking the reference count of the underlying heap-allocated buffer. When a mutation occurs, if the reference count is greater than one, the collection performs a deep copy of the buffer before modifying it, ensuring value semantics and thread safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06a1d3d5-4c88-465a-bcb6-2480029c2e69', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How do you handle authentication in Axum?', N'Fresher', N'Authentication is usually handled by creating a custom middleware or an extractor that checks for the presence and validity of tokens in request headers. If the authentication fails, the middleware returns an unauthorized response before reaching the handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd2d51c1-b9e6-4e4f-9486-2480584d32cf', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a system, how do you handle configuration management across environments?', N'Middle', N'I keep configuration separate from the application code using environment variables or a centralized configuration service. This ensures that the same binary can be deployed to staging and production without changes while maintaining secret management best practices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20e328c6-b0da-4991-8cf6-24811ee40579', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Explain how Vite supports different build targets and why this matters for legacy browser support.', N'Senior', N'Vite allows configuring the target browser range, which determines how modern the emitted JavaScript needs to be. For older browsers, Vite uses the @vitejs/plugin-legacy to automatically generate polyfills and alternative chunks to ensure compatibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'847ee925-cc3d-43b7-9ceb-24826267b45d', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Define the ''Dirty Write'' anomaly.', N'Middle', N'A dirty write occurs when a transaction overwrites data that was modified by another uncommitted transaction. This is considered a severe violation of isolation and is prevented by almost all database systems to maintain data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c083334d-b1e9-42fd-857c-24861f4b9a9d', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the role of the ''lock'' statement?', N'Middle', N'The lock statement ensures that a block of code is executed by only one thread at a time, preventing race conditions on shared data. It works by obtaining a mutual exclusion lock on a specific object reference for the duration of the block.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30e46f10-aa45-4080-93bf-2486fdaa3cc3', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the primary purpose of using TypeScript?', N'Intern', N'The primary purpose of TypeScript is to catch common programming errors during development rather than at runtime. By enforcing type checking, it helps developers write more predictable, maintainable, and self-documenting code, especially in large applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'803db67e-754d-49ad-be94-24875023068b', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are the advantages of using Ember Data compared to manual fetch implementations?', N'Middle', N'Ember Data provides a robust abstraction layer for data fetching, caching, and normalizing API responses. It manages relationships between models automatically, provides a unified interface for CRUD operations, and reduces boilerplate code required for handling network state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc661f62-b427-4884-be5e-2487a12229ed', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the primary benefit of the ''State'' object in Litestar?', N'Middle', N'The state object provides a thread-safe container for application-wide data that needs to be accessed by various parts of the framework. It acts as a central registry for shared resources like database pools or configuration settings, ensuring they are accessible across all route handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'218eddfc-7720-49ca-8632-24887522a0fc', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are template literals in es6?', N'Intern', N'Template literals help make it simple to do string interpolation, or to include variables in a string. Template literals, however, preserve whatever spacing you add to them. For example, to create that same multi-line output that we created above, you can simply do: Another use case of template literals would be to use as a substitute for templating libraries for simple variable interpolations:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffbd3317-e88f-416e-8c65-248af7343661', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi impact the testing of HTTP handlers?', N'Middle', N'Because Chi adheres strictly to the standard http.Handler interface, handlers can be tested using the standard net/http/httptest package without needing a running server or Chi-specific test harnesses. This promotes decoupled testing where the logic is isolated from the routing layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abefc66a-3aad-433e-b95b-248bcb0264d5', N'4c000000-0000-0000-0000-000000000005', N'When would you prefer a NoSQL document store over a Relational database for a new system?', N'Senior', N'Choose a document store when your data model is hierarchical, polymorphic, or frequently changes, as it avoids complex migrations associated with rigid schemas. Use a Relational database when strong transactional integrity, complex joins, and mature data normalization are essential for the business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c4e5dbc-4d10-4719-9464-248e804e8e7e', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What does the term ''schema-less'' mean in NoSQL?', N'Intern', N'Schema-less means that a database does not require a predefined structure for the data before it is inserted. This allows for flexibility where different documents or records in the same collection can have different fields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baf95819-e200-4c2b-afd0-248eb17d3288', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How do NoSQL databases handle schemas?', N'Fresher', N'NoSQL databases typically use a dynamic schema, meaning they do not require a predefined structure before inserting data. This allows developers to add new fields or change data formats on the fly without performing complex database migrations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddd6685f-5989-4dfa-bc60-248efbc7855e', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Describe the impact of the ''autocomplete'' attribute on form accessibility and security.', N'Senior', N'The autocomplete attribute allows browser managers to fill in user data automatically, which increases accessibility by reducing typing requirements. From a security perspective, it also enables better password management by allowing browsers to correctly identify sensitive fields for credential storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02f4200f-8e5f-4194-bd5e-249273428333', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is horizontal scaling, often called scaling out, in NoSQL?', N'Junior', N'Horizontal scaling involves adding more servers or nodes to a database cluster to handle increased traffic or data volume. This contrasts with vertical scaling, which requires upgrading a single server with more CPU or RAM, and is a core advantage of many NoSQL architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31f15e21-c88e-4e59-b27e-2492abc03287', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is Hono''s approach to request validation?', N'Fresher', N'Hono provides validation middlewares that check incoming request data against defined schemas. This ensures that the data received from the client is in the expected format before it reaches the main business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ef7e355-4c59-4e2a-b4ed-24930917b211', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is an Ember Serializer and why is it necessary?', N'Middle', N'Serializers handle the transformation of data between the format expected by the API and the format used by the Ember Data store. They are essential for mapping JSON payloads, normalizing attribute names, and handling side-loaded records or complex relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06f0abcc-b443-4ae9-873b-24937a160ead', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the purpose of the bind directive?', N'Intern', N'The bind directive creates two-way data binding between a component''s state and an HTML form element. This ensures that when the user changes an input value, the underlying data variable is automatically updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c76c61f-cadf-44e5-9d37-249520d2f53d', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of a constructor in a class?', N'Fresher', N'A constructor is a special member function that is automatically called when an object of a class is created. Its primary purpose is to initialize the object''s data members and allocate any necessary resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12acde20-6724-4d9d-bc04-24954f16a919', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the purpose of the ''crossinline'' modifier?', N'Middle', N'Crossinline is used in inline functions to prevent a lambda passed as a parameter from performing a non-local return. This is necessary when the lambda is executed in a different execution context, such as a different thread or an asynchronous callback.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93f84be6-e511-4a23-a60f-2497c60d1ce5', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why is ''FromRequestParts'' preferred over manual request parsing in complex handlers?', N'Senior', N'FromRequestParts provides a standardized, composable interface for inspecting request metadata without consuming the entire request body. This is crucial for performance-sensitive applications where you might need to validate authentication headers or trace IDs before deciding whether to read the potentially large request body.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b78d7c8c-9600-4d6a-984f-249e1a7939e2', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What happens when you call a getter function from a Signal inside a component''s JSX?', N'Junior', N'When a Signal getter is accessed within the JSX, SolidJS automatically tracks it as a dependency for that specific part of the template. When the Signal''s value changes, SolidJS knows exactly which DOM element to update.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd43d778a-0993-4fb0-ba2b-24a1b42abf70', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What are Gin route parameters?', N'Junior', N'Route parameters are dynamic values embedded within the URL path, often used for identifying specific resources like a user ID or order ID. In Gin, these are defined with a colon and can be accessed via the context using the Param method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1efd754f-4c2c-4085-a07a-24a1d4b6e42b', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between stack and heap memory?', N'Intern', N'Stack memory is used for static memory allocation and is managed automatically by the system, while heap memory is used for dynamic allocation and must be managed manually by the programmer. Stack memory is generally faster but more limited in size compared to the heap.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88f2d749-a5d1-4ec5-9e27-24a23a4b0ecc', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What are channels used for in Go?', N'Fresher', N'Channels are the pipes that connect concurrent goroutines. They allow goroutines to communicate with each other and synchronize their execution by passing data securely without explicit locking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90feb716-9f1b-4e8b-93ef-24a2d08649a9', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit''s ''prefetching'' mechanism improve perceived performance and what are the potential downsides?', N'Senior', N'Prefetching fetches data and code for subsequent routes before the user clicks, making navigation feel instantaneous. The downside is increased network traffic and server load, which must be managed by carefully configuring prefetch triggers to avoid wasting resources on unnecessary requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aad696cb-feb2-4515-960e-24a2dec89a5d', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the primary architectural benefit of using Spring Cloud Gateway over a standard Spring MVC filter chain for cross-cutting concerns?', N'Senior', N'Spring Cloud Gateway is built on Project Reactor and Netty, making it non-blocking and highly scalable compared to the servlet-based filter chain. It provides a centralized infrastructure for routing, rate limiting, and security, effectively decoupling these concerns from the individual microservices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
