INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d891c39-473c-4072-a18e-24a9e9d20162', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What are the architectural implications of using counter columns in Cassandra?', N'Senior', N'Counters in Cassandra are not idempotent and rely on read-before-write operations internally, which can lead to inaccuracies during concurrent updates or partial failures. They require careful design because they cannot be easily corrected or replayed without risking data inconsistencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
