INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15bf962e-eafd-4ef6-805f-24be03ef2b78', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the impact of excessive indexing on a table?', N'Middle', N'Every index adds overhead to data modification operations, as the database must update every associated index whenever a row is inserted, updated, or deleted. Excessive indexing can lead to slower write performance and increased storage requirements without providing proportional benefits for read performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0572662e-76c7-4d9d-a258-24c1e79aaaf1', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How are errors handled in Ruby?', N'Fresher', N'Ruby''s exception hierarchy enables developers to manage different kinds of errors. The two main exception types cater to a multitude of issues: - StandardError: For generic problems that occur during code execution. - SystemCallError: Specifically deals with errors originating from system calls. Ways to _Handle Exceptions_ in Ruby Top-Level Exception Handling Ruby leverages the at_exit method for centralized error handling. This approach is mainly useful for logging errors before program exit or for cleaning up resources. Single Statement Unwind Utilize inline rescue, marked by the begin and end block. If an exception arises during the evaluation of the enclosed expression, it''s caught.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04c8a080-2438-4db2-b9bf-24c30aadc34d', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s ''Defer'' statement differ from ''Finally'' blocks in other languages?', N'Senior', N'The defer statement registers a block of code to be executed when the current scope is exited, regardless of how the exit occurred. Unlike a catch-all finally block, defer is scoped to the current lexical block and is often used for resource cleanup, executing in reverse order of declaration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cb58755-f60c-4e2c-a0e0-24c3da01d223', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How can you optimize the performance of a Nuxt application?', N'Middle', N'Performance can be optimized through techniques like image optimization, using the Nuxt Link component for prefetching, minimizing the use of heavy client-side plugins, and leveraging server-side caching. Additionally, splitting code and using effective lazy loading for components can significantly reduce the initial JavaScript bundle size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f3c5567-c591-4882-9713-24cc5117af3c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you handle long-term data evolution without breaking existing clients?', N'Senior', N'I enforce strict schema versioning and backward compatibility practices, such as never removing fields and using optional fields for new data. By employing API versioning strategies, I allow clients to migrate to newer interfaces at their own pace without forcing a breaking change on the entire ecosystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bc0149d-329a-486d-807a-24ce2d561ee2', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Discuss the handling of 404 and 405 status codes in Chi.', N'Senior', N'Chi provides built-in mechanisms to define custom handlers for ''Not Found'' and ''Method Not Allowed'' scenarios. This is vital for maintaining a consistent API contract and providing helpful error messages to clients when they attempt to access non-existent resources or use incorrect HTTP verbs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd75df71a-42b5-4663-9719-24cf1eb72796', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is your reasoning process when determining whether to build a custom solution versus buying a third-party service, considering estimation accuracy?', N'Senior', N'I compare the predictability of the vendor''s integration timeline against the high risk of estimation error in building complex in-house systems. I prioritize the long-term maintenance and opportunity costs, choosing to build only when the custom solution provides a unique, sustained competitive advantage that outweighs the risk of internal delivery delays.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6df12b3-bf02-46d0-bba0-24d158738d38', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What are the trade-offs of using Fastify''s ''avvio'' based plugin system?', N'Middle', N'Avvio provides an asynchronous boot process that ensures all plugins are loaded before the server starts accepting requests. While this ensures stability and dependency management, it can increase the initial startup time of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5adde8e8-ca9d-4c25-ab4b-24d4761fa255', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the different ways to make an API call in JavaScript?', N'Intern', N'In JavaScript, you can make API calls using several methods. The most common ones are XMLHttpRequest, fetch, and third-party libraries like Axios. XMLHttpRequest is the traditional way but is more verbose. fetch is modern and returns promises, making it easier to work with. Axios is a popular third-party library that simplifies API calls and provides additional features. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain AJAX in as much detail as possible AJAX (Asynchronous JavaScript and XML) facilitates asynchronous communication between the client and server, enabling dynamic updates to web pages without reloading. It uses techniques like XMLHttpRequest or the fetch() API to send and receive data in the background.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bec0da3-aa1c-4028-b3a5-24d57600cec5', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of the ''spring.factories'' file in the context of Spring Boot''s modularity?', N'Senior', N'The spring.factories file is a legacy mechanism used by Spring Boot to enable the auto-discovery of configuration classes, listeners, and initializers from external jars. It allows libraries to register components with the Spring context without manual configuration, facilitating a plug-and-play architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd3a7728-a64b-469b-91b2-24d6143d3690', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do SvelteKit''s ''page options'' like ''ssr'', ''csr'', and ''prerender'' allow for fine-grained performance tuning?', N'Senior', N'These options allow developers to toggle rendering strategies on a per-route basis, enabling hybrid applications that mix static content, server-rendered dynamic data, and client-only dashboards. This architectural flexibility is essential for optimizing Time to First Byte and resource caching based on specific route requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce18177a-a021-429c-9f14-24d67989d8a1', N'954a0331-deff-4399-b588-96f39fec001d', N'What are different types of compilation in Angular?', N'Intern', N'Angular offers two ways to compile your application, 1. Just-in-Time (JIT) 2. Ahead-of-Time (AOT)', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e9b9f53-0210-4743-952e-24d6e1fc1c89', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the primary difference between Preact and React in terms of library size?', N'Fresher', N'The main difference is the bundle size. Preact is extremely small, typically around 3KB, whereas React is significantly larger because it includes more features and legacy support. This makes Preact ideal for performance-sensitive applications where load time is critical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34e81a72-9079-4559-912f-24d8d06140e9', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle routing conflicts when multiple routes match the same path?', N'Senior', N'Chi follows a ''first-match-wins'' strategy based on the order of registration in the routing tree. When defining routes, more specific paths must be defined before catch-all or wildcard parameters to prevent the router from prematurely matching broader route patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56f85088-a088-4b7e-afd9-24e08137c389', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How do you handle rate limiting in a Chi-based architecture?', N'Senior', N'Rate limiting is typically implemented as a middleware that interacts with a distributed store like Redis to track request frequency. By placing this at the router entry point, you can protect downstream services from traffic spikes and ensure fair resource allocation across different API clients.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd13d4e1f-ffe0-4731-80c4-24e260ba91c3', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the primary trade-off when deciding between ''def'' and ''async def'' for route handlers in FastAPI?', N'Senior', N'Using ''async def'' allows the event loop to switch tasks during I/O operations, but it incurs a slight overhead. Using standard ''def'' executes the function in an external thread pool; therefore, ''async def'' is optimal for I/O-bound tasks, while ''def'' is preferred for CPU-bound tasks to avoid blocking the event loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91a481cb-81cc-4e16-9a3f-24e4df6c5c8c', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle a situation where you realize you will miss a deadline?', N'Fresher', N'I would communicate the delay to my manager as soon as I identify the risk, providing a clear explanation and a revised estimate. Being proactive allows the team to adjust expectations or provide additional support before the deadline actually passes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c57b36c-645d-4c7d-a770-24e662871797', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express facilitate testing of routes?', N'Middle', N'Express allows you to export the application object without starting the server, enabling integration testing using tools like Supertest. This allows you to simulate HTTP requests and verify responses without needing to open a network port.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7de24b6-c46e-4576-8dc9-24e9a791e55a', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Can you use standard JSX with Preact?', N'Junior', N'Yes, Preact is fully compatible with JSX. You just need to configure your build tool, such as Babel or Vite, to use the appropriate pragma to point to the Preact ''h'' function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c1b55a6-c4df-4dd6-9562-24e9ef63d0d0', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does C++ achieve ABI stability and why is it difficult to maintain?', N'Senior', N'ABI stability requires keeping the binary layout of classes and function calling conventions consistent across versions, often forcing restrictions on data structure changes. Maintaining this is difficult because adding virtual functions, changing member visibility, or modifying memory layout can break binary compatibility, requiring careful design and often resulting in code bloat to support legacy layouts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35688a8a-2074-4c77-a9c4-24edcd948fc1', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is ''Database Denormalization'' and how does it help with read scalability?', N'Senior', N'Denormalization involves adding redundant data to tables to reduce the need for complex joins during read operations. While it increases storage usage and complicates data integrity, it dramatically improves query performance in read-heavy, large-scale systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd549cea-99d2-475c-8e37-24ef7a7749ed', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of the ''cache-loader''?', N'Middle', N'The cache-loader caches the result of expensive transformations from loaders into disk. By reusing these cached results on subsequent builds, it drastically reduces the time required for incremental compilations, improving developer productivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddb81c1e-a7f5-4c0b-a133-24f172e25351', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber manage request timeouts at the architectural level?', N'Senior', N'Fiber leverages the underlying Fasthttp timeout mechanisms to prune idle or slow connections at the socket level. This prevents resource exhaustion by ensuring that unresponsive clients are disconnected before they can consume too many server-side resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e8edb15-f433-4ead-9a3f-24f23665eedd', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the role of the ''break'' and ''continue'' statements?', N'Fresher', N'The break statement terminates the execution of the nearest enclosing loop or switch statement. The continue statement skips the remainder of the current iteration of a loop and proceeds to the next iteration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6414c76-7cce-49c6-9566-24f4259a0bc3', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it beneficial to explain a problem to a colleague, even if they do not provide a solution?', N'Intern', N'This is known as rubber ducking, where the process of articulating the problem in simple terms forces you to examine your own assumptions. Often, the act of organizing your thoughts to explain the situation leads you to notice a detail or logic error you previously overlooked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39406c78-7cb8-423c-90d2-24f9a561e766', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the difference between consistent hashing and simple modulo hashing in a sharded cache?', N'Middle', N'Simple modulo hashing causes massive data remapping whenever the number of nodes changes, leading to widespread cache misses. Consistent hashing ensures that only a small fraction of keys need to be moved when nodes are added or removed, improving stability in dynamic environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de0e5950-1ccc-4387-8de2-24f9e92dc614', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why does Lit use the shadow DOM by default?', N'Junior', N'Shadow DOM provides encapsulation for your component''s styles and markup. It ensures that styles defined inside the component do not leak out to affect the rest of the page, and external global styles do not accidentally break the component''s internal layout.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0dff43c3-d7e4-43f2-9fb5-24fa3754dbb3', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does the ''reactive graph'' in SolidJS handle circular dependencies?', N'Senior', N'SolidJS''s reactive graph is generally a directed acyclic graph. If a circular dependency is created, it could cause infinite loops, but the framework includes safeguards and runtime checks to prevent these issues, and it relies on the developer to structure the state flow correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3435b1b8-24f1-432a-929a-24fd9148c9d3', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix handle concurrency?', N'Intern', N'Phoenix handles concurrency through the lightweight process model of the Erlang VM. Each request is handled by its own process, allowing thousands of users to interact with the application simultaneously without blocking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d11b2fa-6c82-46b7-b573-24ff099ca5f6', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket use type-safe routing?', N'Junior', N'Rocket uses the function signatures of your route handlers to determine expected parameters. If a request does not match the types defined in the handler arguments, Rocket automatically returns a 404 error before the handler code even runs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd21c20c8-a1be-438d-8a4a-2500151f7479', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is a variable''s ''scope'' in Rust?', N'Fresher', N'A variable''s scope is the range within a program for which the item is valid. Once the variable goes out of this scope, Rust automatically cleans up the memory associated with it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0732cffc-fab5-4776-ae1b-25003990d5df', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using a CDN versus serving assets directly from your server?', N'Junior', N'A CDN caches content closer to the user, significantly reducing latency and server bandwidth costs. Serving assets directly is simpler to set up and avoids the need to manage cache invalidation, but it becomes a bottleneck as traffic grows and physical distance from the server increases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd8c47d3-77ac-4b35-9b9d-2504235dfcb8', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the trade-offs of using Unlogged tables in PostgreSQL?', N'Middle', N'Unlogged tables do not write data to the Write-Ahead Log (WAL), which significantly increases performance for bulk inserts or temporary data. The trade-off is that these tables are not crash-safe and will be truncated automatically after a server crash or unclean shutdown.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b681c1c5-37f9-4f62-980b-250471a5c417', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What are the trade-offs of using ''cgo'' for foreign function interfaces?', N'Senior', N'Cgo allows Go to call C code but introduces a significant performance penalty due to the transition between the Go stack and the C stack. It also complicates the build process, breaks cross-compilation simplicity, and requires the runtime to manage OS threads differently, which can impact scheduling efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfd30804-94d3-47c3-8b38-2504cb3af14d', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between a GET request and a POST request in Rails?', N'Intern', N'A GET request is used to retrieve data from the server and should not change the state of the database. A POST request is used to submit new data to be processed, typically resulting in the creation of a new record or a change in the application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d87a6a9-c9b7-4a96-a694-2506ad0d7e6e', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is a DTO and why is it used?', N'Intern', N'A DTO (Data Transfer Object) is an object that defines how the data will be sent over the network. It is typically a simple class or interface used to validate and structure the data coming into the application from a client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55fc8136-232e-4a01-bfad-25075882bc16', N'954a0331-deff-4399-b588-96f39fec001d', N'How does the Angular change detection strategy OnPush differ from the default strategy, and what are the performance implications?', N'Senior', N'The Default strategy checks every component whenever any event, timer, or XHR occurs, which can be inefficient in large trees. OnPush restricts change detection to only run when an input reference changes, an event originates from the component, or an Observable marked with the async pipe emits, significantly reducing CPU overhead in complex applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8006cd5-3104-473d-a755-250870c820d8', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the difference between a synchronous and asynchronous hook in Fastify?', N'Intern', N'A synchronous hook executes immediately and blocks the event loop until it finishes. An asynchronous hook returns a promise, allowing the event loop to continue processing other tasks while waiting for the hook to resolve.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d755825-f871-4705-9b79-25095104697f', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle component state?', N'Intern', N'Preact components can manage internal state using hooks like ''useState'' or by using class component state properties. When this state changes, Preact automatically re-renders the component and updates the DOM to reflect the new data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59ee1a65-8138-4440-abe1-250f07c96cef', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does checked and unchecked context affect arithmetic operations?', N'Fresher', N'In C#, the enablers checked and unchecked ensure more predictable behavior when using specific arithmetic operations. By default, Cemploys overflow checking, but you can toggle to overflow wrapping using appropriate blocks. Context Control Keywords - checked: Forces operations to produce exceptions for overflow. - unchecked: Causes operations to wrap on overflow. When to Use Each Context - checked: Ideal when you require accurate numeric results to guarantee that potential overflows are detected and handled. - unchecked: Primarily used to enhance performance in scenarios where the logic or the expected input range ensures that overflows are less probable or inconsequential. CCode Example Here is the Ccode:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'254b9e32-7e40-4b28-a20c-25146407eed6', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack handle asset modules?', N'Fresher', N'Asset modules allow you to use assets like fonts or images without needing additional loaders. Webpack can either emit a separate file or inline the asset as a data URI depending on the configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25b9ebe7-7f4e-4551-b796-2514b337cfcc', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What should you do if your attempts to fix a bug are failing and you are running out of time?', N'Junior', N'I would take a step back, document my findings, and reach out to a senior team member for a fresh perspective. It is better to ask for help early than to spend too much time going down a wrong path, especially when the issue is time-sensitive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd46c9140-0294-4239-b24f-25160f363152', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Why is it considered a best practice to avoid using @extend across media queries?', N'Senior', N'Because @extend cannot move a selector from outside a media query to inside one, it often fails or produces invalid CSS if you try to extend a class defined globally within a media-specific block. This limitation forces developers to keep shared styles outside of responsive blocks, which can fragment the codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cbbd070-432c-47ae-8322-251a7bae3863', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Explain the concept of ''scope hoisting'' in Webpack.', N'Middle', N'Scope hoisting is an optimization where Webpack concatenates the scope of multiple modules into a single closure rather than wrapping each module in its own function. This reduces the amount of code overhead and helps the browser''s JavaScript engine execute the code more efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9582a8f2-0889-4cef-9c8e-251c68dc3a41', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it important to change only one variable at a time when troubleshooting a complex issue?', N'Intern', N'Changing one variable at a time allows you to clearly identify which specific modification resolved the issue or caused a new one. If multiple variables are changed simultaneously, it becomes impossible to determine the root cause, leading to confusion and potential regressions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'faff367a-b68c-4c5a-99e8-251d53dde861', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the Go garbage collector work in a general sense?', N'Junior', N'Go uses a non-generational, concurrent, tri-color mark-and-sweep garbage collector. It runs alongside the application to identify and reclaim memory that is no longer reachable by the program, minimizing pause times and keeping the application responsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee50d0f4-cc9d-4513-b8a3-251e66b49eae', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why is Redux often used with React?', N'Intern', N'Redux is often used with React because React''s component-based architecture can make passing data through many layers difficult. Redux solves this by providing a way to access state from any component without prop drilling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fe793d7-4af4-41a9-a662-2522f92d4e9e', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between error handling that is too generic versus too specific?', N'Junior', N'Generic error messages improve security by hiding implementation details, but they make it frustrating for developers to debug issues. Specific error messages help identify the root cause quickly, but they can leak sensitive system information to potential attackers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'492e50a4-121a-44d8-989a-2526b214a292', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the difference between a Partition Key and a Clustering Key?', N'Intern', N'The partition key determines which node the data is stored on, while the clustering key determines the sort order of data within that partition. Together, they form the primary key of the table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c00bc00d-6ab2-4982-ac07-252a33640965', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the primary benefit of Quarkus for cloud environments?', N'Fresher', N'The primary benefit is its rapid startup time and low memory footprint. This makes it highly efficient for serverless functions and containerized environments where scaling quickly and using fewer resources is critical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f6375a6-5421-4d42-a32f-252abf695fde', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the benefit of using Tailwind CSS over writing plain CSS?', N'Fresher', N'Tailwind eliminates the need to invent class names and manage separate CSS files for every component, which speeds up the development process. It also reduces the cognitive load of switching between HTML and CSS files and prevents accidental style overrides common in large stylesheets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a500589-34fb-4553-979c-252e0df4a9d0', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the ''Cache Stampede'' problem, and how can it be mitigated at the architectural level?', N'Senior', N'Cache Stampede occurs when a highly requested key expires, causing multiple concurrent requests to simultaneously fetch data from the backend database. It can be mitigated by using probabilistic early expiration, mutex locks to ensure only one process refreshes the cache, or background recomputation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddf13363-3fd7-4550-bf48-2531137da3b8', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What does it mean for a Svelte component to be SSR capable?', N'Intern', N'SSR stands for Server-Side Rendering, which means the Svelte component can be rendered into an HTML string on the server before being sent to the browser. This improves initial load performance and search engine optimization by providing content to the user more quickly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c66b3132-ca2f-4e11-b4b0-253321b93898', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the purpose of the ''IntoResponse'' trait?', N'Intern', N'The IntoResponse trait allows a type to be converted into an HTTP response. By implementing this trait, custom data structures can be returned directly from handlers, enabling clean and concise code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80d0a130-8a91-4f49-adb0-2533c7ca0526', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is meant by ''Build Time'' optimization in Quarkus?', N'Fresher', N'Build time optimization refers to the process where Quarkus performs tasks like dependency injection scanning and configuration parsing during the compilation phase. By doing this work early, the application avoids performing these heavy operations when it starts up.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45c1ed40-3f17-41b6-8977-25353890912b', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Zero-Copy architecture improve performance in network-heavy applications?', N'Senior', N'Zero-copy minimizes the need to copy data between user-space and kernel-space buffers by using system calls like sendfile or mmap. This reduces CPU cycles spent on memory copying and decreases the number of context switches between user and kernel modes, which is critical for serving large files or high-volume data streams.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3f2923b-b8f1-49bc-9187-25373af3ca25', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is Object.preventExtensions() for?', N'Intern', N'Object.preventExtensions() is a method in JavaScript that prevents new properties from being added to an object. However, it does not affect the deletion or modification of existing properties. This method is useful when you want to ensure that an object remains in a certain shape and no additional properties can be added to it. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01c8556e-7939-4d20-a469-25386f01feb6', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the concept of ''Snapshot Isolation'' in multi-version concurrency control (MVCC).', N'Middle', N'Snapshot isolation provides a transaction with a consistent view of the database as it existed at the start of the transaction. Instead of locking rows, the system keeps multiple versions of data, allowing readers to access older versions without blocking writers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'191d3466-acdc-4c3a-9299-253a71ac2326', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does the ''Saga'' pattern manage distributed transactions across microservices?', N'Senior', N'The Saga pattern coordinates a sequence of local transactions where each step updates a service and publishes an event to trigger the next. If a step fails, the saga executes a series of compensating transactions to undo the previous steps, maintaining eventual consistency without long-lived distributed locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f44b3b1c-393a-4208-a6d0-253a7388ef31', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is exception handling?', N'Fresher', N'Exception handling is a mechanism for dealing with runtime errors or unusual conditions in a program. It uses try, catch, and throw blocks to separate error-handling logic from the main application flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9f8430c-ac14-433b-abaa-253bc7257ac6', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the difference between ''Future'' and ''Stream'' in Dart''s asynchronous model.', N'Middle', N'A Future represents a single value or error that will be available at some point in the future. A Stream, conversely, is a sequence of asynchronous events, allowing a system to receive multiple values over time until the stream is closed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c6a2280-dbd7-48b7-a287-253be2c58301', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between ''public'', ''private'', ''protected'', and ''internal''?', N'Junior', N'These are access modifiers that control visibility. ''Public'' is accessible everywhere, ''private'' is restricted to the containing class, ''protected'' is accessible to the class and its derivatives, and ''internal'' limits access to the current assembly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2387d87-4fb9-45be-b8a9-254663a904e8', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Can you use standard Vue components in Nuxt?', N'Fresher', N'Yes, Nuxt is built on top of Vue.js, so you can use any standard Vue component within a Nuxt project. Nuxt simply adds extra features on top of these components to handle routing, imports, and data fetching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87dbf12f-c542-4f63-b255-254ae927ec13', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does the ''ACID'' property ensure reliability in database transactions?', N'Middle', N'ACID stands for Atomicity, Consistency, Isolation, and Durability, providing a framework to ensure that transactions are processed reliably. These properties guarantee that all operations succeed or fail as a unit, data remains consistent, transactions are isolated from each other, and once committed, changes persist permanently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9f76bf2-fa8d-4a48-94dd-254bb0e574fb', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is a JSON response?', N'Intern', N'A JSON response is a standard format for sending data over the web that is easy for humans to read and for machines to parse. FastAPI automatically converts return values from Python dictionaries or models into JSON format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd873b862-9ae8-4979-becb-254ca5c3c2a0', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of the ''static'' keyword when applied to a variable inside a function?', N'Fresher', N'When a local variable is declared as static, its lifetime extends throughout the entire duration of the program rather than being destroyed when the function exits. It is initialized only once and retains its value between multiple function calls. This is useful for maintaining state information within a function without using global variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f32d16bb-6e6b-4fbe-9961-254df05053ae', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why is the Two-Phase Commit protocol considered a blocking protocol?', N'Senior', N'2PC is blocking because if the coordinator fails after a participant has voted ''ready'' but before the final decision is broadcast, the participant remains locked. This prevents other transactions from accessing the data, potentially leading to system-wide stalls until the coordinator recovers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b200d04a-587f-4d82-8066-25518d4dca48', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the primary relationship between Fiber and Fasthttp?', N'Intern', N'Fiber uses Fasthttp as its underlying HTTP engine instead of the standard Go ''net/http'' library. This choice allows Fiber to achieve significantly faster throughput and lower memory allocation compared to standard library frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fbfae21-aadc-4cf1-9953-2551bc12f45d', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do I test a Python program or component?', N'Fresher', N'Python comes with two testing frameworks: The documentation test module finds examples in the documentation strings for a module and runs them, comparing the output with the expected output given in the documentation string. The unittest moduleis a fancier testing framework modeled on Java and Smalltalk testing frameworks. For testing, it helps to write the program so that it may be easily tested by using good modular design. Your program should have almost all functionality encapsulated in either functions or class methods. And this sometimes has the surprising and delightful effect of making the program run faster because local variable accesses are faster than global accesses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44a53008-0a1e-40b0-93b4-255281a1df13', N'075b8862-431c-4678-9767-f55359758a4a', N'Explain the concept of ''Dependency Injection'' in Vue and how it improves component decoupling.', N'Senior', N'Dependency injection via ''provide/inject'' allows a parent component to serve as a dependency provider for any descendant, regardless of depth. This eliminates the need for ''prop drilling'' and decouples components from their specific middle-layer parents, making the codebase more modular and easier to refactor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca22f3d4-4239-4042-90b6-2552cff0c8af', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you determine when it is appropriate to use asynchronous processing for a task?', N'Middle', N'I use asynchronous processing when a task is long-running and does not need to return an immediate result to the user, such as generating reports or sending emails. This decouples the client from the background operation, improving overall system responsiveness and fault tolerance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de55012b-56ac-42b2-a97f-2553acb5e29f', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between ''++i'' and ''i++''?', N'Intern', N'The pre-increment operator ++i increments the variable before using its value in an expression. The post-increment operator i++ uses the current value of the variable in the expression first, and then increments it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffd23d5f-67b3-4801-ba41-25540b96d66b', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the ''Strangler Fig'' pattern used for?', N'Middle', N'The Strangler Fig pattern is a strategy for migrating a monolithic system to microservices by incrementally replacing specific functionalities with new services. Over time, the new services ''strangle'' the monolith until it can be retired entirely, reducing migration risk.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ddfadce-65fd-4807-ac6e-255742b907d2', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Discuss the trade-offs of Svelte''s ''write-time'' reactivity versus ''run-time'' reactivity.', N'Senior', N'Write-time reactivity allows for highly optimized, granular updates but forces the framework to be opinionated about syntax. Run-time reactivity, while more flexible for dynamic object structures, requires a larger runtime footprint and additional processing overhead to track changes during execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5d36de7-176f-4964-aee7-25578a1ade1e', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does the implementation of a distributed lock manager affect system scalability?', N'Senior', N'Distributed locks introduce significant latency and potential bottlenecks because they require cross-node coordination and consensus. They should be avoided in favor of optimistic concurrency control or idempotent operations whenever possible to ensure high throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06f6f1a2-6cdc-4144-9188-2559e15621f8', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the benefit of Rocket’s ''Data'' guard for body parsing?', N'Senior', N'The ''Data'' guard acts as a limit-aware wrapper for incoming request bodies, preventing large-payload attacks by enforcing size limits at the framework level. It ensures that the application does not consume excessive system resources before the data is even validated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f7acdbf-4bb6-4997-9f34-255b642bfb94', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Explain the architectural implications of choosing between horizontal partitioning (sharding) and vertical partitioning.', N'Senior', N'Horizontal partitioning scales write throughput by distributing rows across multiple nodes, but introduces complexity in cross-shard joins and aggregation. Vertical partitioning improves performance for specific queries by isolating frequently accessed columns, but it does not inherently solve write bottleneck issues as easily as sharding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1a4a4fe-ebee-4ffd-93c3-255bf90929c6', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the difference between vertical and horizontal scaling?', N'Middle', N'Vertical scaling involves adding more power, such as CPU or RAM, to an existing server, whereas horizontal scaling involves adding more machines to the resource pool. Horizontal scaling is generally preferred for distributed systems as it avoids single points of failure and offers theoretically unlimited growth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
