INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa5afaf5-ace5-4a5f-b46a-2561a8d272fc', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What role does the ''actix-rt'' crate play?', N'Fresher', N'Actix-rt provides the asynchronous runtime for Actix applications. It is responsible for managing the event loop and executing asynchronous tasks efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79c84807-40ad-43f5-b53c-2561b1ed7bcd', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If a system is healthy under low traffic but fails under high traffic, how do you investigate?', N'Middle', N'I would investigate resource contention, such as thread pools, connection pools, or CPU scheduling, that only manifests when throughput increases. I would review load testing reports to see if the system performance degrades linearly or exponentially as load grows. This often points to non-scalable architectural components, like shared locks or synchronous blocking I/O, which become bottlenecks under pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9119ed3-fed5-425f-912e-2562b7268814', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the performance implications of using deep object cloning versus structured cloning or immutable data structures?', N'Senior', N'Deep cloning via recursive approaches is slow and can cause stack overflows, while structured cloning handles complex types but is asynchronous and blocking. Immutable data structures leverage structural sharing to keep memory usage low and allow for referential equality checks, which drastically improves performance in change detection mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b86fbb99-a0c0-4d7c-9b2b-2563937bc230', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the trade-offs of using Rails Engines for modularizing a large codebase?', N'Senior', N'Engines facilitate code reuse and separation of concerns by encapsulating functionality within isolated namespaces and mount points. However, they can complicate dependency management and testing, and excessive modularization can lead to a fragmented architecture that is difficult to navigate and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06db1812-5344-4cdc-9871-2563dae5286d', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What does ARC stand for and what does it do?', N'Intern', N'ARC stands for Automatic Reference Counting. It is a memory management mechanism that automatically tracks and manages your app''s memory usage by deallocating instances that are no longer needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75e2d130-26ff-40a7-8d83-256462e663cf', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What are the architectural benefits and drawbacks of using GraphQL versus REST in a microservices environment?', N'Senior', N'GraphQL allows clients to request exactly what they need, reducing over-fetching, but it complicates caching and makes fine-grained rate limiting or cost estimation difficult. REST provides predictable resource-based caching and simpler security models but often leads to over-fetching or N+1 query problems in complex object graphs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe196961-1e10-4afb-916a-2565777e978b', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does the ''any'' type do, and why should its use be minimized?', N'Junior', N'The ''any'' type disables type checking for a variable, effectively treating it like plain JavaScript. Its use should be minimized because it defeats the purpose of using TypeScript by allowing type-related bugs to bypass the compiler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad2c0fb7-9423-46ab-9cb0-256666f5f7a6', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Explain the trade-offs of using Astro''s ''Static Site Generation'' (SSG) versus ''Server-Side Rendering'' (SSR) modes.', N'Middle', N'SSG generates all pages at build time, resulting in maximum performance and effortless deployment to CDNs, but it requires a full rebuild to update content. SSR generates pages on-demand at request time, enabling dynamic content and personalization, but it requires a Node.js server and introduces latency for the initial response. Choosing between them depends on whether your content updates frequently and requires user-specific data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44b80dc3-e0bd-4f14-b591-2568e82bc920', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When planning a migration to a microservices architecture, how do you estimate the breaking point for your team''s capacity?', N'Senior', N'I estimate based on the team''s ability to manage the operational complexity, specifically focusing on the overhead of distributed tracing, CI/CD, and cross-service communication. If the cognitive load exceeds the team''s current capability, I prioritize simplifying the architecture over further decomposition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'770e812a-a8ed-45c2-9607-2569a5b39a7e', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Why is Astro considered a ''multi-page application'' framework rather than an SPA?', N'Senior', N'Astro focuses on traditional server-side routing where each URL corresponds to a distinct HTML document, which is inherently more robust for search engines and accessibility. While it can mimic SPA navigation via View Transitions, its architectural foundation remains document-centric rather than relying on a client-side router to manage page transitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'517ffcef-50af-4a45-9424-256a16110b15', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is a URL dispatcher in Django?', N'Intern', N'The URL dispatcher is a mechanism that matches requested URLs to specific views in your application. It uses a configuration file, typically named urls.py, to map URL patterns to the corresponding view functions or classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
