INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b1a51c5-8a62-436d-9e0e-256eb8ca254f', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When debugging, why is it useful to explain the problem to someone else?', N'Fresher', N'This is known as ''rubber ducking,'' where explaining a problem forces you to articulate your logic clearly. Often, the act of organizing your thoughts out loud helps you notice gaps in your reasoning or identify the solution you had previously overlooked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
