INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'356cfa3b-ffe7-4345-9930-2578029159b3', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Explain your approach to estimating the performance impact of a database schema migration.', N'Middle', N'I would perform a dry run on a production-like dataset in a staging environment to measure the duration of the migration and the impact on query performance. I would then use these metrics to estimate the required maintenance window and the potential for temporary latency spikes, ensuring we have a rollback plan in place.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5d75f27-5458-4911-a135-25787183a672', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of the ''ContentChild'' and ''ContentChildren'' decorators?', N'Middle', N'These decorators are used to query and access elements that are projected into a component via ng-content. ContentChild provides access to a single element, while ContentChildren provides an QueryList of multiple elements, allowing the parent component to interact with projected content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21986994-6b7a-4a68-9361-257889e7c7a6', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the primary role of a router like Chi?', N'Intern', N'The primary role of a router is to match incoming HTTP requests to specific handler functions based on the request URL path, method, and other parameters. It acts as a traffic controller for the application''s API endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66d82288-5f82-479f-b481-2579372edd84', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is your process for designing a system for high availability?', N'Middle', N'I design for redundancy at every layer, including multiple availability zones and load balancers to distribute traffic. I also incorporate health checks and automated failover mechanisms to ensure that the system remains operational if a single component fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'741df32d-a2a7-4359-919b-257a76eee409', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the Result type in Rust?', N'Intern', N'The Result type is an enum used for returning and propagating errors. It has two variants, Ok and Err, which represent success and failure respectively, requiring the caller to explicitly handle the possibility of an error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7dcf4555-e947-4e41-a634-257dfc9f25ae', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the difference between Parallel Routes and Intercepting Routes?', N'Middle', N'Parallel Routes allow you to render multiple pages simultaneously in the same layout, useful for complex dashboards. Intercepting Routes allow you to load a route from another part of the application within the current layout, commonly used for modals that show details without losing the background page context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5eeb9a36-7328-4366-bff0-257fcca5a728', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS enforce strict typing and configuration validation during the bootstrap process?', N'Senior', N'AdonisJS uses a centralized configuration system that validates environment variables and settings against defined schemas before the application starts. This ''fail-fast'' approach prevents runtime errors caused by missing or malformed environment data, ensuring the application state is valid from the start.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e47a0c25-5e92-44ef-b134-2581afda4ce4', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Explain the role of the ''WATCH'' command in Redis optimistic locking.', N'Middle', N'The WATCH command allows a client to monitor keys for changes before executing a transaction. If any watched key is modified by another client before the transaction is executed, the transaction will fail, preventing race conditions without needing complex pessimistic locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f0cf489-f34c-44ab-9def-2581b4f7b3c5', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does the Cluster module work to improve Node.js performance?', N'Middle', N'The cluster module allows you to create child processes that share the same server port. This enables a Node.js application to utilize multi-core CPU systems effectively by distributing the incoming load across multiple instances, bypassing the single-threaded limitations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35374158-13f7-4f14-b76e-2585b41002b4', N'4c000000-0000-0000-0000-000000000005', N'What is the advantage of using a microservices architecture over a monolithic one?', N'Middle', N'Microservices allow individual components to be developed, deployed, and scaled independently, providing better fault isolation and team agility. However, this introduces complexity in service orchestration, data consistency, and distributed tracing compared to a monolithic structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3dab7cce-81c8-46e3-88f0-25874a1186f1', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are *args and **kwargs used for?', N'Junior', N'These syntax elements allow a function to accept a variable number of arguments. ''*args'' collects extra positional arguments into a tuple, while ''**kwargs'' collects extra keyword arguments into a dictionary, providing flexibility in function signatures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bef61bc9-625e-49aa-8b33-258ab8c4e71d', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What happens if a read request is ''eventually consistent''?', N'Fresher', N'An eventually consistent read may reflect changes from recently completed write operations. This happens because data replication across the distributed storage partitions takes a small amount of time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a027a83c-9c50-4529-88d4-258c3a98c37a', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is jQuery considered less relevant in modern web development?', N'Junior', N'Modern browser APIs have significantly improved, allowing tasks that once required jQuery to be performed easily with native JavaScript. Frameworks like React, Vue, and Angular also provide more robust ways to handle DOM manipulation and state management, reducing the need for an external library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75cc1cdc-870d-4af0-baeb-258cc0c1255e', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do you handle asynchronous data loading in React applications?', N'Fresher', N'In a modern React app, don''t roll your own useEffect + fetch for data loading — the React docs explicitly recommend against it. Reach first for a dedicated data-fetching library: TanStack Query, SWR, or RTK Query for client-side fetching, or Server Components and route-level loaders (Next.js App Router, Remix/React Router) when you control the framework. In React 19, the new use() hook lets a component read a promise directly and suspend, which pairs naturally with for loading states and error boundaries for failures. A hand-written useEffect+fetch is a low-level fallback that needs an AbortController, a response.ok check, and careful state handling to avoid race conditions and stale updates. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd2e8beb-7355-46b2-a266-2595c344a640', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart handle memory management?', N'Intern', N'Dart uses an automatic garbage collection system to manage memory. It periodically identifies and deallocates objects that are no longer reachable, freeing developers from manual memory management tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5493ec74-d008-47e7-af45-2596e506f765', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of the null coalescing operator?', N'Intern', N'The null coalescing operator is a shorthand way to check if a variable exists and is not null. It returns the value of the variable if it exists, or a default value if the variable is null or undefined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
