INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aae79efb-6f98-4565-8ecb-259d30304902', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How do Tailwind''s media query handling mechanisms improve developer productivity?', N'Senior', N'Tailwind uses a mobile-first responsive design approach with shorthand prefixes, allowing developers to define responsive behavior directly on the element. This eliminates the need to switch between HTML and separate media query blocks in external CSS files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f02ac9c8-03a6-4f87-a38a-259db82961cd', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust''s module system handle visibility?', N'Middle', N'Rust uses the ''pub'' keyword to control the visibility of modules, functions, and structs. By default, everything is private to the current module, requiring explicit declarations to expose APIs, which encourages encapsulation and hides internal implementation details.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
