INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c193f71-733a-410a-925c-25b2711ca7e3', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is windowing technique?', N'Intern', N'Windowing is a technique that only renders a small subset of your rows at any given time, and can dramatically reduce the time it takes to re-render the components as well as the number of DOM nodes created. If your application renders long lists of data then this technique is recommended. Both react-window and react-virtualized are popular windowing libraries which provides several reusable components for displaying lists, grids, and tabular data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7b398b6-6e6e-40d2-93b9-25b399cf2a01', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How can you install NestJS and set up a new project on your machine?', N'Fresher', N'To install NestJS on your machine, you need to have Node.js and npm (Node Package Manager) installed. Once you have those, you can install the NestJS CLI (Command Line Interface) globally on your machine using the following command: This command installs the NestJS CLI globally, which allows you to use the nest command from anywhere on your machine. With the NestJS CLI, you can create new projects using and after creating a project you can generate NestJS modules, services, etc. running will several files that work together to handle CRUD (Create, Read, Update, Delete) operations for a particular entity, in this case, "users".', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'712883aa-789a-4c8d-aee1-25b6c4c13174', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a distributed deadlock, and why is it harder to detect than a local one?', N'Middle', N'A distributed deadlock occurs when transactions wait for resources across multiple nodes in a cluster. It is harder to detect because no single node has a complete view of the wait-for graph, requiring complex inter-node communication or timeouts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8b0d865-e5cf-4130-80fc-25b8abcf6d39', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is the use of ''malloc'' usually accompanied by a call to ''free''?', N'Junior', N'Malloc allocates memory on the heap, which the operating system does not automatically reclaim. If free is not called, the program will experience a memory leak, eventually exhausting available system memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f0be9e7-9def-47bb-8277-25b8e0062adb', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the difference between a sparse index and a secondary index in Cassandra?', N'Middle', N'Cassandra does not use traditional indexes in the same way as RDBMS. Secondary indexes are designed for low-cardinality columns and can create performance bottlenecks, whereas standard partition-based lookups are always preferred for scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2db88abb-ca95-4285-ae8c-25b9aeedbb03', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does the ASP.NET Core request pipeline differ from the traditional ASP.NET HTTP Module/Handler pattern?', N'Senior', N'ASP.NET Core uses a middleware-based pipeline where components are chained together in a specific order, allowing each to decide whether to pass the request to the next component or terminate it. This is more modular and performant than the legacy pipeline, as it operates entirely within the Kestrel web server context without relying on IIS-specific abstractions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f19a8ff4-4a14-434b-936e-25be95c74178', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the purpose of the Garbage Collector?', N'Junior', N'The Garbage Collector is a memory management process that automatically identifies and deletes objects that are no longer being referenced in the application. This helps prevent memory leaks and reduces the need for manual memory deallocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a9907fc-ed3a-4178-bc51-25c1d4ceeb35', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Is Actix-web thread-safe?', N'Fresher', N'Yes, Actix-web is inherently thread-safe because it is built on Rust. The compiler prevents data races at compile-time by enforcing strict ownership and borrowing rules for all shared state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ef9c81c-2192-4755-84db-25c1d7d93f8c', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the role of templates in Ember?', N'Junior', N'Templates are written in Handlebars syntax and define the visual structure of your application. They are declarative, meaning you describe what the UI should look like based on the data provided, and Ember updates the DOM automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'936a6024-9e79-4a4f-a43e-25c302042d01', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What happens if you call useState conditionally?', N'Junior', N'As per rules of React Hooks, hooks must be called unconditionally. For example, if you conditionally call it: React will throw a runtime error because it relies on the order of Hook calls, and conditional logic breaks that order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5bcbf82-10c8-4a15-bc59-25c5760c6686', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does connection pooling interact with caching layers?', N'Middle', N'Connection pooling reduces the overhead of establishing database connections when the cache needs to perform a backend fetch. By reusing existing connections, the system reduces latency during cache misses, resulting in a more stable and efficient data retrieval process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91f13a46-5b33-459e-a23a-25cb5d7d296a', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it important to change only one variable at a time when debugging?', N'Intern', N'Changing one variable at a time ensures that you can definitively identify the cause of the problem. If you change multiple things simultaneously, you cannot know which change resolved the issue or if you inadvertently introduced a new one.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4aeffce6-9768-4ca4-8c9e-25cbac86c4ef', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of the MySQL Change Buffer and when is it most effective?', N'Senior', N'The change buffer is a specialized data structure that caches changes to secondary index pages that are not currently in the buffer pool. It is most effective for workloads with high insert, update, or delete volumes on secondary indexes, as it avoids expensive random I/O by merging changes later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18bef275-76a7-4013-a078-25cfc1025900', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the significance of interior mutability in Rust, and how is it implemented?', N'Senior', N'Interior mutability is a design pattern that allows modifying data even when there are only immutable references to it, bypassing the usual borrowing rules. It is implemented via types like Cell or RefCell, which perform runtime checks to ensure that the strict aliasing rules are maintained, shifting enforcement from compile-time to execution-time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f000c44-b909-4205-8394-25d1bdaa0e2c', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus reduce memory consumption?', N'Fresher', N'Quarkus reduces memory by shifting framework initialization to build-time and removing unused classes or dependencies during the native compilation process. This results in a leaner application that only loads what is strictly necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cfaf205-1547-4456-bf54-25d35972fea8', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are properties in Kotlin?', N'Fresher', N'Properties in Kotlin are a combination of fields and accessor methods. When you declare a property, Kotlin automatically generates the getter and setter methods, which you can customize if needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02fbde6b-30e6-43f9-8651-25d71f563d08', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the precedence between pipe and ternary operators?', N'Intern', N'The pipe operator has a higher precedence than the ternary operator (?:). For example, the expression first ? second : third | fourth is parsed as first ? second : (third | fourth).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6ee901d-ab8d-4a64-8c25-25d8a4bd656b', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What does it mean for Nuxt to be ''opinionated''?', N'Fresher', N'Being opinionated means that Nuxt provides a specific set of conventions and folder structures that developers are encouraged to follow. This consistency makes it easier for team members to understand projects and ensures that best practices are applied automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'892b1953-35c0-44e2-b3a6-25d8a6cfa03f', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin''s delegation pattern differ from traditional class inheritance in terms of architectural flexibility?', N'Senior', N'Delegation promotes composition over inheritance, allowing an object to delegate responsibility to an internal instance rather than sharing a base class implementation. This avoids the fragility of deep inheritance hierarchies and enables runtime behavior changes, whereas inheritance creates rigid, compile-time coupling between parent and child classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce3118e6-417d-4896-862f-25d9352eb746', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the rationale behind Go''s lack of support for function overloading.', N'Senior', N'Go prioritizes simplicity and readability, aiming to minimize the cognitive load of understanding code. By disallowing overloading, the language ensures that a function name uniquely identifies a specific implementation, making the code easier to navigate and the compiler easier to implement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae39fb35-c203-4f2f-856a-25d9a974b933', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack''s dependency graph impact build times?', N'Middle', N'The size and complexity of the dependency graph directly influence the time it takes for Webpack to resolve, parse, and bundle the application. Larger projects with many deep dependencies require more memory and processing power, which can be mitigated using caching features like persistent caching in Webpack 5.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a08d79d2-f993-4cc6-8793-25e59f7bf20b', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the purpose of a sanity check after completing a complex estimation?', N'Intern', N'A sanity check involves stepping back to see if the final result makes logical sense in the real world. It helps catch significant calculation errors, misplaced decimal points, or invalid assumptions by comparing the result against known benchmarks or intuitive expectations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bdab80c-911f-4819-bbf4-25e8d2c558f3', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain the difference between include, prepend, and extend in Ruby''s mixin system.', N'Senior', N'Include inserts a module into the ancestor chain immediately after the class, prepend inserts it before the class, and extend adds the module methods as singleton methods to the object. These mechanisms manipulate the inheritance hierarchy to control method lookup priority and scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c20c83d-7a8d-40e1-86a7-25ea6fc3b775', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js manage memory in large applications with many components?', N'Middle', N'Alpine.js is designed to be lightweight, and because it works directly on existing DOM nodes, it does not maintain a massive shadow memory structure. However, developers should still be mindful of ''x-data'' scope nesting and avoid excessive global state to prevent memory leaks in long-running single-page applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6243dee3-ec61-441f-b4c9-25ec56147697', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the difference between ''import.meta.env.DEV'' and ''import.meta.env.PROD''?', N'Middle', N'These are boolean flags automatically set by Vite to indicate whether the application is running in development or production mode. They allow developers to conditionally execute code, such as logging or connecting to different API endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab161063-87ca-46dc-b52c-25ec91dad75b', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix ensure type safety across the client-server boundary?', N'Middle', N'Remix allows you to share TypeScript types between loaders, actions, and components by using utility types provided by the framework. By sharing these definitions, the client can be strictly typed against the data returned by the server, reducing runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'154da52a-68b3-41af-86f9-25edddb6b009', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of the Cluster in Cassandra?', N'Junior', N'A cluster is the outermost container for a Cassandra database, representing the collection of all nodes that work together to store and manage data. All nodes in a cluster share the same partitioner and snitch configuration to ensure consistent communication and data placement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5bd4786-158c-4538-a4c6-25ede3de4553', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If a critical microservice experiences a cascading failure, what is your systematic approach to containment and mitigation?', N'Senior', N'I immediately implement circuit breakers to stop the propagation of errors and apply rate limiting to shed excess load. Simultaneously, I analyze telemetry to identify the root cause—such as resource exhaustion or a deadlock—before initiating a controlled rollout of a fix or a rollback to a known stable state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3fc5917-59f3-4558-8ba3-25ee2d9d9620', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How do you handle sensitive configuration data in Symfony?', N'Middle', N'Sensitive data should be handled using environment variables managed by a .env file or system-level variables. Symfony''s configuration system can reference these variables, ensuring that secrets like API keys or database credentials are never hardcoded in the source code or committed to version control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24ad5002-f185-48c3-a610-25f2a3e56451', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of the ''secret_key'' in Flask?', N'Intern', N'The secret key is used to cryptographically sign session cookies and other security-related tokens. It is crucial for preventing users from tampering with their session data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac6a314d-673c-4c27-b409-25f662c02af8', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does the Validator component support complex business rule validation that spans multiple objects?', N'Senior', N'The Validator component supports Class-level constraints, which allow you to inject services into a validator class to check cross-object dependencies. This ensures that validation logic remains encapsulated and testable, rather than being forced into the persistence layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'800d5cc2-c1e8-4c55-b25e-25f71fab1712', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a distributed system, how do you decide between eventual consistency and strong consistency for a global user-facing application?', N'Senior', N'I evaluate the business impact of stale data against the latency requirements of the user experience. Strong consistency often requires synchronous cross-region coordination, which significantly increases tail latency, so I prefer eventual consistency for non-critical features while using strictly consistent paths only for operations like financial transactions where data integrity is non-negotiable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c99f649-3f43-4b57-9e7a-25f8385c3b99', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux handle state normalization?', N'Middle', N'Normalization involves structuring the state as a flat object where entities are stored by ID rather than deeply nested structures. This prevents data duplication and makes it easier to update individual items without complex tree traversals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac070d3f-8598-45ef-ae6c-25fa6e09f82d', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle middleware execution flow?', N'Middle', N'Chi processes middleware in a layered fashion using a chain-of-responsibility pattern. Each middleware wraps the next handler in the stack, allowing developers to execute logic before and after the final route handler is invoked, similar to onion architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a38686f0-27fa-42f8-8b29-25fda862af03', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are the implications of boxing and unboxing in C#?', N'Middle', N'Boxing is the process of converting a value type to an object reference, which requires allocating memory on the heap. Unboxing is the reverse operation that extracts the value type from the object, which involves type checking and copying. Frequent boxing and unboxing can degrade performance significantly due to increased memory pressure and garbage collection overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1530e562-c0b6-4138-af8a-25fddd4cee25', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is Durability in a database context?', N'Fresher', N'Durability guarantees that once a transaction has been committed, it will remain saved even in the event of a system failure, power outage, or crash. The changes are permanently recorded in non-volatile memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a04e973-f857-49f3-ab73-26007fa6e6b3', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is a preprocessor directive?', N'Fresher', N'A preprocessor directive is a command that starts with a hash symbol and is processed by the C preprocessor before the actual compilation begins. Common examples include file inclusion via include and constant definition via define.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fb24f8a-cf79-448b-ab2c-2600cd7934c3', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is your strategy for diagnosing a memory leak in a high-throughput production application that lacks detailed profiling instrumentation?', N'Senior', N'I would perform heap dumps at two different timestamps during the application''s lifecycle and compare the object retention graphs to identify which classes are growing monotonically. If dumps are not feasible, I would monitor OS-level RSS metrics alongside garbage collection frequency to infer if the heap is being exhausted or if off-heap memory is accumulating due to native resource leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2710933e-bb2a-4024-8923-2601dd550eb8', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB achieve high availability despite being a distributed system?', N'Senior', N'DynamoDB achieves high availability by replicating data across multiple Availability Zones within an AWS region by default. It uses a leader-based replication protocol for each partition to ensure that data is durably written to a majority of replicas before acknowledging the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3242fc3-be2e-4601-9d2b-260258e27a51', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the primary difference between a stack and heap allocation in Go?', N'Middle', N'Stack allocation is fast and managed automatically as functions return, while heap allocation requires the garbage collector to track object lifetimes. Go uses escape analysis to decide if a variable can stay on the stack or must be moved to the heap to prevent dangling references.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e352ec7-0fe3-4941-a8e2-26059f5d28b1', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the difference between the App Router and the Pages Router?', N'Intern', N'The Pages Router is the traditional routing system based on a pages folder, while the App Router is a newer architecture built on React Server Components. The App Router provides more advanced features like nested layouts, streaming, and improved data fetching capabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1094b68-9188-459e-9d99-260a731547d5', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What are ''Profiles'' in Quarkus and when would you use them?', N'Junior', N'Profiles allow developers to define different sets of configurations for different environments, such as dev, test, or prod. You can activate a specific profile to override properties, ensuring the application behaves correctly based on the current deployment context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4585013b-71d5-4a47-b4ba-260a7fcbd995', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the ''cost of quality'' when deciding between rapid prototyping and building a robust production-ready architecture?', N'Senior', N'I evaluate the business risk of failure versus the time-to-market advantage. I estimate the cost of future refactoring, technical debt interest, and potential downtime, comparing those to the immediate revenue gains of a faster release to determine the optimal investment level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f08f94fa-44cd-4936-9562-260ba8ffa41d', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of the dependency injection system in FastAPI?', N'Intern', N'Dependency injection allows you to declare shared logic, such as database connections or authentication, and have it automatically provided to your path operations. This promotes code reuse and makes testing easier by decoupling components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a3c488f-c68b-436a-838a-260c36b9fb32', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Why Use Implicit Parameters?', N'Fresher', N'1. Global Environment: They''re often used to propagate information through the codebase, reducing the need for manual parameter passing. For instance, you can set locale, database connections, or logging levels without passing them to every function. 2. Type Classes: They''re foundational to defining and utilizing type classes. Such as Ordering in collections like sort. 3. Fluent Interfaces: They can help in building more expressive DSLs and fluent interfaces by eliminating repetitive parameters. 4. Library Integration: They''re widely used in libraries like Akka, Play Framework, and Cats, which leverage implicits for improved flexibility and functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65aaed44-5963-48b6-9a4d-260cd236352a', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a Local Secondary Index (LSI)?', N'Intern', N'An LSI is an index that has the same partition key as the base table but a different sort key. It allows you to query items within the same partition using a different sort attribute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddeb6be0-3296-401b-afe4-260df55040f8', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do you handle user events in Ember components?', N'Junior', N'User events are handled by defining action methods within the component class. These actions are then triggered from the template using event modifiers or standard HTML event attributes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'291d51c0-d132-43ee-b1b6-260f13bf95b5', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do you prevent mutating array variables?', N'Fresher', N'The preexisting variables outside of the function scope including state, props and context leads to a mutation and they result in unpredictable bugs during the rendering stage. The below points should be taken care while working with arrays variables. 1. You need to take copy of the original array and perform array operations on it for the rendering purpose. This is called local mutation. 2. Avoid triggering mutation methods such as push, pop, sort and reverse methods on original array. It is safe to use filter, map and slice method because they create a new array.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1857972-368d-482b-bd63-261016e4a4c5', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a Phantom Read?', N'Intern', N'A phantom read occurs when a transaction executes a query twice and finds a different set of rows because another transaction inserted or deleted rows during that time. It is similar to a non-repeatable read but involves entire row sets rather than specific values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28787e37-d98d-49fa-b182-2611fc867884', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between @Controller and @RestController in Spring Boot?', N'Fresher', N'@Controller is used to define a web controller that typically returns a view name to be resolved by a view resolver. @RestController is a specialized version of the controller that adds the @ResponseBody annotation, which automatically serializes the return value directly into the HTTP response body, usually as JSON or XML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ef22f30-b51e-467f-9a55-26161e038970', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of the die() or exit() functions?', N'Junior', N'Both functions are used to terminate the execution of the current script immediately. They are frequently used to halt a program when a critical error occurs or when a required resource is unavailable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3218631a-6367-42b2-a118-261ac46f3a84', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When designing a data storage strategy for a system with massive write volumes, how do you choose between a relational database and a NoSQL alternative?', N'Senior', N'I evaluate the need for complex ACID transactions versus the requirement for high write throughput and horizontal scalability. If the data schema is highly structured and requires referential integrity, I optimize the relational model; otherwise, I favor a NoSQL approach to gain partition tolerance and linear scaling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76de6bcc-81d7-4cee-8833-261d7f0d2376', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the C memory model interact with modern CPU cache architectures?', N'Senior', N'C assumes a sequential consistency model in abstract, but modern hardware caches and store buffers often allow weak consistency. Developers must use atomic primitives and explicit memory fences to ensure that memory operations are visible across different CPU cores in the order the programmer expects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c82a926-788e-4984-ab35-261ee55a48bb', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason through the trade-offs of using a bleeding-edge technology for a project with a strict deadline?', N'Middle', N'I weigh the potential for increased development efficiency against the high risk of encountering undocumented bugs or lack of community support. If the deadline is strict, I would lean toward proven, stable technologies, as the time lost troubleshooting immature tools often negates any potential speed gains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17058c2d-fa79-4226-bf4f-261ff3b96372', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the concept of ''Dependency Injection'' and its benefits for testing.', N'Middle', N'Dependency injection is a design pattern where an object receives its dependencies from an external source rather than creating them internally. This decoupling makes it easier to inject mock objects during unit testing, allowing for isolated testing of components without needing actual database or API connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2a3a372-6f4e-4846-95a1-2625cf4215cb', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the concept of horizontal scaling in NoSQL databases.', N'Junior', N'Horizontal scaling, or scaling out, involves adding more servers to a database cluster to handle increased load. NoSQL databases are designed to distribute data across these multiple servers automatically, making them highly scalable compared to vertical scaling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4be1fd9d-cfb3-474b-bbe2-2628a62cbcd6', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the role of a data warehouse in a database architecture?', N'Middle', N'A data warehouse is optimized for analytical processing rather than transactional processing. It consolidates data from various sources and is structured to support complex reporting, historical analysis, and business intelligence, often using star or snowflake schemas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c8e359f-ec20-4a89-a8b0-262ccc45501e', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why might you choose a simpler database solution over a more powerful, complex one?', N'Intern', N'A simpler solution reduces the operational overhead, training requirements, and potential for misconfiguration. If the data requirements do not justify the advanced features, the simpler tool is more efficient for the team''s overall productivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52ed1b7b-3671-4366-a103-262ea214af4d', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Discuss the performance implications of jQuery''s animation engine versus CSS transitions.', N'Senior', N'jQuery animations run primarily on the main thread using JavaScript-based timers, which can lead to layout thrashing and dropped frames. Modern CSS transitions and animations are offloaded to the browser''s compositor thread, providing significantly smoother performance and better energy efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed5e0653-6ea3-4d7d-a3b3-26338b49104b', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between an ''interface'' and a ''type'' in TypeScript?', N'Intern', N'Both are used to define the structure of objects, but they have subtle differences. Interfaces are generally better for defining object shapes and can be merged through declaration merging, while types are more flexible and can represent unions, intersections, and primitive aliases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
