INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1638fea5-3a7a-40dc-ab71-2635c551d997', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Describe the purpose of ''sealed'' traits in an inheritance hierarchy.', N'Middle', N'Sealed traits restrict the inheritance of a hierarchy to the same source file, which allows the compiler to perform exhaustive pattern matching checks. If a developer misses a case in a match expression, the compiler will issue a warning, preventing potential runtime bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b28df93c-e63f-4411-866f-263a6889b416', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between checked and unchecked exceptions?', N'Intern', N'Checked exceptions are verified by the compiler at compile-time and must be handled or declared by the programmer. Unchecked exceptions occur at runtime and represent programming errors that do not require mandatory handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'714e2bd0-7d1a-4968-b5c8-263d4b106ceb', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does the ''lazy'' keyword affect memory usage and performance?', N'Middle', N'The lazy keyword defers the initialization of a property until it is first accessed. This can reduce the initial memory footprint and improve startup time for objects that might not always be needed, though it introduces a potential thread-safety risk as it is not atomic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cad9ab4f-1398-4ae7-a065-263f11d5a79b', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is Ruby''s approach to inheritance?', N'Junior', N'Ruby supports single inheritance, meaning a class can only inherit from one superclass. However, Ruby utilizes modules via mixins to provide multiple inheritance-like behavior by allowing classes to include the methods of other modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45f0af23-fcf3-4700-8e33-263f714cc61d', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the ''app state'' in SvelteKit?', N'Intern', N'App state refers to the data that is shared or managed across your application components. SvelteKit provides stores and context to help you manage this data effectively so that UI components stay in sync with the underlying information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ec37783-1115-41c5-ad90-26403d9c0df5', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does the size of Preact affect the Time to Interactive (TTI) metric?', N'Middle', N'Because Preact is significantly smaller than React, the main thread is blocked for less time during the initial JavaScript parsing and execution phase. This leads to a faster Time to Interactive, as the application becomes functional and responsive to user input sooner after the initial download.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'851e2525-ec53-423e-aef6-2642561ce9b2', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How do PHP generators impact memory consumption during large dataset processing?', N'Senior', N'Generators allow functions to yield values one at a time instead of building an entire array in memory, effectively turning an O(n) memory problem into O(1). This is critical for processing large files or database result sets that would otherwise exceed the PHP memory limit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0efc4d4c-484b-42a0-86e0-2645b04e072e', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Can you describe the Laravel request lifecycle?', N'Junior', N'Let''s dive deeper into the Laravel request lifecycle. Key Components - HTTP Middleware: Delivers a modular approach to filtering HTTP requests and responses. - Request: Transforms HTTP requests into an instance of Request. - Router: Matches the URI to an appropriate route. - Controller: Processes the incoming request. - Middleware Groups: Organize several middleware under a single, distinctive name. - Response: Turns controller return results into HTTP responses. - Global Middleware: Applies to all HTTP requests. Request Lifecycle Steps 1. Initial Request: - Following an HTTP request, \textbf{the public/index.php file is called}. This initializes the Laravel framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee3e2ec9-a2c2-4aa6-bfc6-2648f4009c97', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How are constants handled in Go?', N'Junior', N'Constants are values that are known at compile time and cannot change during execution. They can be numeric, character, string, or boolean, and they provide a way to define immutable values that are type-safe.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9738912e-9ff3-4656-96e7-264af057d6b1', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How do you check if a map key exists in Go?', N'Junior', N'You can check for a key''s existence by using a two-value assignment when accessing the map. The second value is a boolean that is true if the key exists and false otherwise.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90f9c494-a7cc-47c5-af10-264bb8914916', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js manage CSS/styling scalability?', N'Senior', N'Next.js supports CSS Modules and CSS-in-JS, which provide scoped styling to prevent global namespace collisions. By extracting CSS into separate files during the build process, it prevents render-blocking and ensures that styles are loaded efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2601640f-3571-40c1-bb68-26527551fc82', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between isNaN and Number.isNaN?', N'Fresher', N'1. isNaN: The global function isNaN converts the argument to a Number and returns true if the resulting value is NaN. 2. Number.isNaN: This method does not convert the argument. But it returns true when the type is a Number and value is NaN. Let''s see the difference with an example,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8af2d20-fda2-4a97-a6b9-265345d2ee44', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the purpose of component hydration in Astro?', N'Junior', N'Hydration is the process of making a static HTML element interactive by attaching JavaScript event listeners. In Astro, you must explicitly tell the framework which components need to be hydrated using specific client directives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9d7f1b3-7f8a-4e6b-beae-2655554fbfe1', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the significance of the CAP theorem for distributed databases?', N'Senior', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. Since network partitions are inevitable in distributed environments, architects must choose between prioritizing consistency during a failure or maintaining availability at the cost of stale data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3963d542-aec8-4b8d-a0e7-265aefa92d32', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is a Ruby mixin, and how is it used?', N'Fresher', N'A mixin is a way to include the functionality of a module into a class using the include or extend keywords. It allows developers to share methods between unrelated classes, effectively overcoming the limitations of single inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'759dabbb-f309-4082-9f74-265c0fc1db03', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between an input element and a textarea element?', N'Junior', N'An input element is typically used for short, single-line text entries or specialized fields like dates and checkboxes. A textarea is designed for multi-line text input, allowing users to type longer blocks of text.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'630d3fcb-13e6-4dcc-9d50-265fc98a51ab', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the role of the Phoenix Presence feature and why it is more scalable than a centralized database-polling approach.', N'Senior', N'Phoenix Presence uses a Conflict-free Replicated Data Type (CRDT) implementation to track process state across a distributed cluster. Instead of hitting a central database for every status update, nodes synchronize state changes via an efficient gossip protocol, ensuring eventual consistency while offloading database contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de5af6ef-3529-4ae0-92d0-2662f950d31b', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What factors influence your decision to choose a NoSQL database over a relational database for a new feature?', N'Middle', N'I evaluate the data schema requirements and the nature of the consistency model needed. I choose NoSQL if the data is unstructured, requires massive horizontal scaling, or demands high write availability, while I stick to relational databases for structured data that requires complex transactions and strict ACID compliance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'504408bc-efc3-4566-aada-2664735d1b7d', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What does horizontal scaling mean in Elasticsearch?', N'Intern', N'Horizontal scaling refers to the ability to increase capacity by adding more nodes to the cluster. This allows the system to handle more data and higher query volumes by distributing the workload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e18ef574-1e1a-4ab9-949f-266587456e29', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide when a piece of functionality should be moved to a client-side application versus the server?', N'Junior', N'Client-side logic is ideal for improving interactivity and reducing server load, but sensitive business logic, data validation, and authentication must always be performed on the server. Never trust data coming from the client, as it can be easily manipulated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03509380-1926-4fc8-aad5-26668745e0f7', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Can you define routes in separate files in Fastify?', N'Junior', N'Yes, you can define routes in separate files by exporting a function and registering that file as a plugin. This helps keep your codebase organized by separating route logic from the main application setup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa92e618-5e33-481b-8a64-266697f53a60', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does React Fiber works? Explain in detail.', N'Fresher', N'React Fiber is the core engine that enables advanced features like concurrent rendering, prioritization, and interruptibility in React. Here''s how it works: 1. Fiber Tree Structure Each component in your app is represented by a Fiber node in a tree structure. A Fiber node contains: * Component type * Props & state * Pointers to parent, child, and sibling nodes * Effect tags to track changes (e.g., update, placement) * This forms the Fiber Tree, a data structure React uses instead of the traditional call stack. 2. Two Phases of Rendering A. Render Phase (work-in-progress) * React builds a work-in-progress Fiber tree. * It walks through each component (begin phase), calculates what needs to change, and collects side effects (complete phase).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be8a2050-8994-414d-b02f-2667396e8b21', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono optimize request matching in a nested routing structure?', N'Senior', N'Hono supports hierarchical route mounting, which allows developers to split the routing tree across multiple files. The trie-based router remains efficient because it maps these sub-routers into the primary trie, maintaining fast lookup times while improving code maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13bd39a5-9278-4e13-9388-26689475db3e', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is an array in C?', N'Intern', N'An array is a data structure that stores a collection of elements of the same data type in contiguous memory locations. Each element is accessed using an index, which represents its position relative to the start of the array.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81a3123c-ec33-425b-9132-2668a2ff19e9', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Explain about HTML Layout Engines used by browsers?', N'Fresher', N'A layout engine (also called a rendering engine) is the core software component of a browser responsible for parsing HTML/CSS and rendering the visual output on screen. The three active engines today: Blink (Google, 2013 — forked from WebKit) - Used by: Chrome, Edge (since 2020), Opera, Brave, Samsung Internet, Vivaldi - Powers the majority of web traffic today - Developed by Google + contributors via the Chromium project WebKit (Apple, 2003 — forked from KHTML) - Used by: Safari on macOS/iOS, and all browsers on iOS (Apple mandates WebKit on iOS App Store) - The original engine Chrome was based on before Google forked it into Blink Gecko (Mozilla, 1998) - Used by: Firefox, Thunderbird, SeaMonkey, Waterfox - The only major independent engine not owned by a big tech company - Uses a separat...', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eda99da0-8358-44d2-99a3-26692ea0669e', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How do Ruby singleton classes work?', N'Middle', N'A singleton class is an anonymous, hidden class that exists for a specific object instance to hold methods unique to that object. It resides in the method lookup path immediately before the object''s actual class. This is the underlying mechanism that enables class-level methods and per-instance method definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44b9ad37-614d-47c7-adcd-266a383378c6', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why does Swift utilize Automatic Reference Counting (ARC), and what role do strong, weak, and unowned references play in it?', N'Middle', N'ARC is a compile-time memory management system that tracks and manages an object''s reference count, automatically deallocating memory when the count reaches zero. Strong references increase the reference count, while weak and unowned references do not, which is essential for breaking retain cycles. Weak references are optional and become nil when the object is deallocated, whereas unowned references are non-optional and assume the object will always exist during the reference''s lifetime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3348f3e-ec55-4a5e-b7c8-266b14eaf044', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is a ''brute-force'' approach to problem solving, and when is it a viable trade-off?', N'Intern', N'A brute-force approach prioritizes simplicity and immediate results over efficiency. It is a viable trade-off when the dataset is small or when the solution only needs to run once, as it saves development time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
