INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16ee2791-439b-431c-90fd-26766260b1f1', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are the trade-offs of using Hono in an edge-native architecture compared to a traditional Node.js server-side framework?', N'Senior', N'Edge-native frameworks like Hono prioritize minimal cold-start times and low memory footprints, which is critical for serverless functions. While you lose access to certain Node.js-specific native modules and local file system persistence, you gain significant latency improvements and global scalability by deploying logic closer to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
