INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'696313e1-5d84-46fe-82d6-2679d3650033', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a ''partition key'' in a distributed database?', N'Junior', N'A partition key is a specific field used by the database to determine which node or shard a particular piece of data should be stored on. Choosing a good partition key is vital to ensure that data is distributed evenly across the cluster and to avoid performance bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'442e0d88-bd4b-4266-b678-267b28a94658', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the significance of ''Variance'' (covariant, contravariant, invariant) in Scala''s type system?', N'Senior', N'Variance defines how complex types relate to their components, determining whether a generic container of a subtype can be treated as a container of a supertype. Covariance allows for safe subtyping in read-only scenarios, while contravariance is essential for consuming types such as function arguments. Understanding these rules is crucial for building robust, reusable APIs that avoid runtime type errors while maintaining flexibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
