INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1079435c-c168-4c74-a5e1-268f4db4e4d8', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the advantages of using surrogate keys over natural keys?', N'Middle', N'Surrogate keys are system-generated identifiers that have no business meaning, ensuring they never change even if the underlying data changes. Natural keys are based on real-world attributes, which can be problematic if those attributes need to be updated or if they are not truly unique over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5254e7e-5108-47c5-a3b5-26910067fdc9', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is ''Depends'' in FastAPI?', N'Intern', N'The ''Depends'' function is a core component of the dependency injection system. It is used to declare that a function parameter requires an external dependency to be resolved before the endpoint logic executes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fc591b5-135e-4ca9-bf33-2691971e043a', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind''s handling of pseudo-classes and media queries differ from standard CSS organization?', N'Senior', N'Tailwind uses a modifier syntax that keeps state-based styles and responsive breakpoints directly alongside the base utility. This colocates the logic with the element, making it easier to reason about the component''s state without jumping between multiple CSS files or media query blocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1107bf19-dfbb-49be-b253-269277fbfba8', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What are the security implications of exposing API routes in a Next.js application?', N'Senior', N'API routes are server-side code and should be treated as such, meaning they must include proper input validation and authentication checks. Developers must be careful not to leak internal server logic or database schemas through API responses, as these endpoints are publicly accessible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4e1dbb2-3971-4e0b-b2ae-2692f85e8d67', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Compare ''Push'' vs. ''Pull'' models for task distribution in a worker-based system.', N'Senior', N'The Push model allows for lower latency as tasks are immediately sent to available workers, but it risks overloading workers if not managed correctly. The Pull model allows workers to request tasks based on their current capacity, preventing overload and providing better load balancing, though it introduces a slight polling delay.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cac8d3a-6978-4130-9ee2-2694c8170472', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why is data modeling important in DynamoDB?', N'Fresher', N'Unlike relational databases where you can normalize data, DynamoDB requires you to model data based on your application''s access patterns. Proper modeling ensures that you can retrieve all required data in a single request, which is crucial for performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53c605f2-33f2-411b-9ac8-26977035b590', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the concept of AOP (Aspect Oriented Programming) in Spring.', N'Middle', N'AOP allows you to separate cross-cutting concerns, such as logging, security, or transaction management, from the main business logic. It works by intercepting method calls and injecting additional behavior without modifying the original code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f38eddf1-3c0b-47d2-9a18-26986e414f15', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the function of the meta viewport tag?', N'Junior', N'The meta viewport tag gives the browser instructions on how to control the page''s dimensions and scaling on mobile devices. Without it, mobile browsers might render the page at a desktop width and zoom out, leading to a poor user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d96c00f-44f1-4bf0-bbbe-269b6457bcca', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you handle idempotency in a POST request?', N'Middle', N'Idempotency is typically handled by providing a unique client-generated key, often called an Idempotency-Key, in the request header. The server stores this key to ensure that repeated requests with the same key do not create duplicate side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3652ccc-cbe1-4c15-af29-269d36c7fbd9', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why is it recommended to use JSON schemas for validation in Fastify?', N'Middle', N'Using JSON schemas allows Fastify to pre-compile validation logic into optimized code, significantly increasing throughput. It also automatically generates documentation and ensures that input data adheres to the expected contract before it reaches the route handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3549660a-9ce9-437b-929b-269dff624a0e', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How are headers accessed in Echo?', N'Fresher', N'You can access request headers using the request header map through the context object. Similarly, you can set response headers by using the response header map before sending the final response to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68b8699c-63f6-495b-8d72-269e8fd4e1f4', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery affect the critical rendering path in a performance-critical application?', N'Senior', N'Including the entire jQuery library adds significant script evaluation time and increases the initial bundle size, delaying the Time to Interactive. Furthermore, because jQuery often triggers multiple style calculations and layout reflows during DOM manipulation, it can block the main thread and degrade the user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1873cd28-ae4c-4ac6-91b6-26a774bc8303', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do Ember Modifiers work and why are they used?', N'Middle', N'Modifiers are used to attach behavior to DOM elements, such as third-party library initialization or custom event listeners, which cannot be expressed through templates alone. They provide a declarative way to manipulate the DOM during the lifecycle of an element without needing to touch the internal component state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d08bc2a-b5ab-4208-8459-26a791bff9b3', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do mapped types work?', N'Junior', N'Mapped types allow you to create new types based on the properties of an existing type. They are useful for transforming or filtering object properties programmatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69530957-6f73-4f74-8d71-26a7e2cbb4b1', N'075b8862-431c-4678-9767-f55359758a4a', N'Explain the concept of ''lazy loading'' routes in Vue Router.', N'Middle', N'Lazy loading splits the application code into smaller chunks that are only fetched when a specific route is visited. This significantly reduces the initial load time of the application by ensuring the user only downloads the code necessary for the current view.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a09b5a7-9a26-4736-98be-26aa840e2c87', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the guidelines to be followed for writing reducers?', N'Intern', N'There are two guidelines to be taken care while writing reducers in your code. 1. Reducers must be pure without mutating the state. That means, same input always returns the same output. These reducers run during rendering time similar to state updater functions. So these functions should not send any requests, schedule time outs and any other side effects. 2. Each action should describe a single user interaction even though there are multiple changes applied to data. For example, if you "reset" registration form which has many user input fields managed by a reducer, it is suggested to send one "reset" action instead of creating separate action for each fields. The proper ordering of actions should reflect the user interactions in the browser and it helps a lot for debugging purpose.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0d254cf-e0ca-4d54-aed7-26abdad61e81', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How can you handle file uploads in NestJS, and what is the role of the Multer library?', N'Fresher', N'NestJS offers convenient ways to handle file uploads, and one common approach is using the multer middleware. Additionally, the framework provides the @UploadedFile decorator, which simplifies the process of accessing and processing uploaded files in NestJS controllers. These tools collectively offer a flexible and efficient solution for managing file uploads in NestJS applications. By using the @UseInterceptors() decorator with FileInterceptor or FilesInterceptor, you can handle single or multiple file uploads in your application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f207754-e40d-4ca6-a8bf-26ace342c205', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is React?', N'Intern', N'React (aka React.js or ReactJS) is an open-source front-end JavaScript library for building user interfaces based on components. It''s used for handling the view layer in web and mobile applications, and allows developers to create reusable UI components and manage the state of those components efficiently. React was created by Jordan Walke, a software engineer at Facebook (now Meta). It was first deployed on Facebook''s News Feed in 2011 and on Instagram in 2012. The library was open-sourced in May 2013 and has since become one of the most popular JavaScript libraries for building modern user interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'beccd718-c352-4128-8e5a-26af83611b2a', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What are the limitations of Echo''s automatic recovery middleware?', N'Middle', N'The recovery middleware catches panics to prevent the server from crashing, but it should not be considered a substitute for robust error handling. It is a safety net that logs the stack trace and returns a 500 error, but developers must still manage expected runtime exceptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b36d7ca6-c61b-4676-a164-26af9c165462', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is an inverted index and why is it important?', N'Junior', N'An inverted index is a data structure that maps content, such as words or tokens, to the documents where they appear. It is the core mechanism that allows Elasticsearch to perform rapid full-text searches without scanning every document in the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb3d0a87-9ef0-4e6b-b411-26b0d325f98a', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When working on a complex project, how do you decide which sub-tasks to prioritize?', N'Intern', N'I would prioritize tasks based on their dependencies, as some tasks must be completed before others can start. I would also focus on high-risk or high-uncertainty tasks early to uncover potential blockers as soon as possible. This approach minimizes the chance of project failure due to late-stage discoveries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84de07e1-b51b-42f0-8896-26b263a43f4e', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s access control (internal, private, file-private, public) affect binary size and performance?', N'Middle', N'Stricter access control, such as private or file-private, provides the compiler with more information about where symbols are used. This enables ''whole-module optimization'' to perform more aggressive inlining and dead-code elimination, potentially reducing binary size and improving execution speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4a1d57a-b416-4b00-b983-26b34911e7c5', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack handle circular dependencies during the bundling process?', N'Senior', N'Webpack handles circular dependencies by creating an empty object export for the module before the actual code execution finishes. While this prevents infinite loops, it can lead to runtime errors where an imported value is undefined if it is accessed synchronously before the circular dependency has finished initializing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9a73c78-1e71-47e7-9fb0-26b46c939c88', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What happens if an extractor fails in Axum?', N'Intern', N'If an extractor fails, such as when mandatory JSON fields are missing or data types are incorrect, Axum automatically generates an error response. By default, it returns a 400 Bad Request status code to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82e5256b-fd96-4a87-8671-26b48092aff4', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How do ''named constructors'' improve code readability in Dart?', N'Middle', N'Named constructors allow a class to expose multiple ways to instantiate objects, clearly communicating the intent behind each approach. This avoids the confusion of multiple overloaded constructors with similar signatures, which is a common issue in languages like Java or C++.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4413d51-7dce-4ef6-8c82-26b7f8fd88bf', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is it important to keep Actix handlers non-blocking?', N'Junior', N'Since Actix runs on a limited number of worker threads, blocking a thread stops that worker from processing any other incoming requests. Keeping handlers non-blocking ensures the server remains responsive and can handle a high volume of concurrent traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0c7b9c9-3d2c-4b20-847e-26b8cd15dd6e', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Describe the difference between Global and Module-scoped Exception Filters in terms of architectural impact.', N'Senior', N'Global filters provide a unified error-handling strategy across the entire application, ensuring consistent API responses for all exceptions. Module-scoped filters allow for granular control, permitting domain-specific error handling that does not leak into other parts of the system, which is safer for complex multi-tenant or multi-domain architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca8a539c-1d48-4484-ad8e-26ba2a0125bc', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the trade-off between synchronous and asynchronous communication in microservices?', N'Middle', N'Synchronous communication is easier to implement and provides immediate feedback but creates tight coupling and potential latency bottlenecks. Asynchronous communication improves fault tolerance and scalability but increases complexity due to the need for eventual consistency and handling lost or out-of-order messages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bc17c6f-a6cf-43b8-82fe-26c08c9bf766', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of ''declaration maps'' in a library distribution strategy?', N'Senior', N'Declaration maps provide a link between the generated .d.ts files and the original source files. They are essential for IDEs to enable ''Go to Definition'' functionality, allowing users of a library to navigate to the source code even when consuming only the distributed type definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1783f62f-8bcb-46eb-930e-26c1072aeca4', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How are database seeds used in AdonisJS?', N'Junior', N'Seeds are scripts used to populate the database with initial or default data, such as admin accounts or lookup tables. They are essential for setting up a consistent development environment for new team members.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6da39c79-ed4a-42e8-9ffa-26c25b5aa10e', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the internal mechanism of interface values in Go.', N'Senior', N'An interface is represented as a two-word structure containing a pointer to the type information and a pointer to the actual data. This allows for dynamic dispatch while maintaining type safety, though it introduces a small performance overhead compared to direct method calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9ac7803-d5cb-4552-ab23-26c4ee3f17c5', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Why is it better to use external CSS files instead of inline styles?', N'Junior', N'External CSS files promote better code maintenance by keeping styles separate from HTML structure. They also improve performance because external files are cached by the browser, reducing load times across multiple pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9024aedb-bfd8-4112-9af3-26c77202e8b2', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Is Dart a compiled or interpreted language?', N'Intern', N'Dart can be both. It uses Just-In-Time (JIT) compilation during development for fast iteration and Ahead-Of-Time (AOT) compilation for production to produce native machine code for high performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e175221-b9c9-4054-8560-26c7ca3ef21f', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the benefit of using ''response_model'' in a FastAPI decorator?', N'Junior', N'The ''response_model'' parameter ensures that the data returned by your function is validated and filtered according to the provided Pydantic model. This prevents sensitive data from being accidentally returned and ensures the client receives the expected output format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df0459b4-b80e-45d5-bc2e-26c80bed0444', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How do covered queries improve performance in MongoDB?', N'Senior', N'A covered query occurs when all fields in the query are present in a single index. This allows the database to return the results directly from the index tree without having to load the full documents from the data files, significantly reducing disk I/O and CPU usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10b007d5-1aff-48f0-83b9-26c99f182bf4', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the function of the ''useStore'' hook in Qwik?', N'Junior', N'The useStore hook is used to create reactive state objects. When properties within this object change, Qwik automatically tracks these changes to update only the relevant parts of the UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b19091f-e046-4780-8893-26ca662fc7d1', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of the ''res.send()'' method?', N'Junior', N'The res.send() method sends the HTTP response to the client. It automatically sets the Content-Type header based on the data type provided and terminates the request-response cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5ca943b-03ed-4021-b08a-26cb0abea924', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the concept of ''branded types'' and why they are necessary for domain-driven design in TypeScript.', N'Senior', N'Branded types use intersection types to add a unique ''tag'' to primitives, distinguishing semantically different values (like UserID vs ProductID) that share the same base type. This prevents logic errors where a value of one type is accidentally passed where another is expected, which is a common hazard in large, complex systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d14bcab-5574-4858-ba1a-26cbba9dc6af', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Explain the concept of Progressive Enhancement.', N'Middle', N'Progressive enhancement is a strategy that focuses on building the core functionality of a web page first using standard HTML. Once the basic experience is guaranteed, additional features like CSS for layout or JavaScript for interactivity are added as layers. This ensures that users on older browsers or limited connections can still access the essential content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'196a49d1-69ce-4386-a151-26ccfdb62c51', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Describe the architectural purpose of the ExecutionContext in .NET asynchronous programming.', N'Senior', N'ExecutionContext captures and flows ambient environment data, such as security context, culture, and synchronization context, across asynchronous boundaries. This ensures that logically related operations maintain a consistent environment even when they execute on different threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4e40ba8-e023-4039-9370-26cd0e54beeb', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the impact of table scans on database scalability?', N'Middle', N'Table scans force the database to read every row in a table, which is highly inefficient as data grows. They consume significant I/O and CPU resources, making it impossible to maintain performance at scale without properly implemented indexes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33a81375-658b-45fe-8090-26ce6b6185d6', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of the ''Pipeline'' pattern in Laravel, and where is it most effectively applied?', N'Senior', N'The Pipeline pattern allows for the sequential processing of an object through a series of classes, commonly used in middleware and task processing. It provides a clean, extensible way to modify or validate data without deeply nested conditional logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a3b9257-2aac-45c5-af9f-26d0ce62c97c', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'You have a microservice that is experiencing intermittent latency spikes only during peak traffic. How would you investigate this?', N'Middle', N'I would start by reviewing distributed tracing spans to identify which specific downstream dependencies or internal operations are causing the bottleneck. Simultaneously, I would inspect metrics like garbage collection pauses, thread pool saturation, and connection pool availability to see if resource exhaustion is occurring under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'824a726a-957b-461b-9823-26d2ad5464d6', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik maintain performance in large-scale applications?', N'Senior', N'Qwik scales independently of the application size because the cost of hydration does not grow with the number of components. Since only the necessary code for a specific user interaction is downloaded, the initial footprint remains constant regardless of the total complexity of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66ec1f9d-5546-4173-b492-26d41969d17a', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the difference between ''Throughput'' and ''Latency'' regarding scalability?', N'Senior', N'Throughput is the amount of work or transactions a system can process per unit of time, while latency is the time it takes for a single request to complete. Scalability often focuses on maximizing throughput, but it must be balanced against latency requirements to ensure a good user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
