INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b34dc0a4-2ef9-4f82-9fcc-26d9c4ba5ad2', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does sampling strategy affect the utility of distributed tracing at scale?', N'Senior', N'Head-based sampling can miss rare, high-impact errors, while tail-based sampling allows you to keep traces based on specific criteria like latency or error status. A robust strategy balances storage costs and performance overhead by focusing on the most relevant traces for debugging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbfbc4f9-3109-4acf-b70d-26d9f6b7bf50', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS facilitate test-driven development through its built-in testing suite?', N'Senior', N'AdonisJS provides a comprehensive testing framework that supports both unit and functional testing, with built-in helpers for mocking the IoC container. This allows developers to test components in isolation while maintaining a high level of confidence in the integration of those components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30ca0bbb-9270-451a-bd27-26dc13570428', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the memory impact of large-scale object allocation in JavaScript?', N'Senior', N'Large-scale object allocation increases the frequency of minor and major GC cycles, which can lead to application pauses. Developers must balance object creation against memory pressure, often using object pooling or typed arrays to reduce the load on the garbage collector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
