INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'346864f1-5f70-4005-aedc-26df1cff8483', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the impact of excessive fragmentation in InnoDB tables?', N'Senior', N'Fragmentation occurs when deleted records leave gaps in data pages, leading to inefficient disk space usage and suboptimal I/O. This forces the engine to read more pages than necessary to retrieve the same amount of data, necessitating periodic table optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e17bc3c-1910-48dc-b0ef-26df561aa256', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the trade-offs of using ''Interceptors'' in HTTP service calls?', N'Senior', N'Interceptors provide a clean way to handle authentication headers, logging, or error transformation globally. However, they can also become a ''black box'' where debugging specific failed requests becomes difficult if the interceptor logic is too complex or opaque.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d80adc4-dd8d-4933-9a45-26e1b8146ca3', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is provisioned mode in DynamoDB?', N'Intern', N'Provisioned mode is a billing option where you specify the number of reads and writes per second that you expect your application to require. This is more cost-effective for steady-state or predictable traffic patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1931785-d034-43e5-ad68-26e51c63689b', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is JIT and how is it related to Node.js?', N'Intern', N'Node.js has depended on the V8 JavaScript engine to provide code execution in the language. The V8 is a JavaScript engine built at the google development center, in Germany. It is open source and written in C++. It is used for both client side (Google Chrome) and server side (node.js) JavaScript applications. A central piece of the V8 engine that allows it to execute JavaScript at high speed is the JIT (Just In Time) compiler. This is a dynamic compiler that can optimize code during runtime. When V8 was first built the JIT Compiler was dubbed FullCodegen. Then, the V8 team implemented Crankshaft, which included many performance optimizations that FullCodegen did not implement. The V8 was first designed to increase the performance of the JavaScript execution inside web browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd25bfd63-39d1-4a2d-ba3b-26e54e608567', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'In a web application, why is it safer to store passwords as hashes rather than plain text?', N'Fresher', N'Storing passwords as hashes ensures that even if the database is compromised, the actual passwords remain protected and unreadable. A one-way cryptographic hash makes it computationally infeasible for an attacker to revert the hash back to the original password.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0948b46-7b39-4917-8c5f-26e6ad9a7fc2', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How do you handle errors in Swift?', N'Junior', N'Swift uses a pattern involving throwing, catching, and propagating errors. You mark functions that can fail with the ''throws'' keyword, and use ''do-catch'' blocks to handle the potential errors thrown during execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92f4e9ce-20f8-4c17-aa4d-26e7475b10b8', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Discuss the impact of ''Backpressure'' in a stream processing system.', N'Senior', N'Backpressure is a feedback mechanism where a consumer signals to the producer that it is overloaded and cannot keep up with the current rate. It prevents the system from crashing due to buffer overflows and encourages graceful degradation under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfac1570-3cf3-47e8-a03f-26eeee3d9bbc', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the primary purpose of database normalization?', N'Intern', N'The primary purpose of normalization is to reduce data redundancy and improve data integrity. It organizes data into tables to ensure that each piece of information is stored in only one place, which prevents update anomalies and inconsistent data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c929b209-b36f-4255-95f8-26f0176da13c', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you design an API that handles bulk operations efficiently?', N'Senior', N'Bulk operations should be designed to be atomic or provide granular success/failure status for each item in the batch. For extremely large sets, shift from synchronous processing to an asynchronous ''job'' pattern where the API returns a 202 Accepted status and a location header to poll for final completion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2513cb13-3345-4abf-a6a9-26f7670cfca0', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Can you explain what is meant by "TypeScript is a superset of JavaScript"?', N'Junior', N'TypeScript is often described as a "superset of JavaScript" because every valid JavaScript code is also a valid TypeScript code. TypeScript is designed in a way that it fully embraces existing JavaScript syntax and functionality. This ensures a smooth transition for developers wishing to adopt or migrate to TypeScript. Key TypeScript Features On Top of JavaScript - Type Definitions: TypeScript introduces static typing through type annotations. These are optional, enabling gradual adoption for existing codebases that might not need them. - Newer JavaScript Features: TypeScript extends JavaScript syntax, providing support for the latest ECMAScript standards more effectively through its compiler, even when the underlying JavaScript engine might not support them yet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c6afc2b-a18c-4919-b56b-26f8aea5dfae', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a sharding strategy in NoSQL?', N'Intern', N'Sharding is the process of splitting a large dataset into smaller chunks, called shards, and distributing them across multiple servers. This ensures that no single server bears the entire load, improving performance and storage capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5a5ff8a-d6ce-4059-b231-26f8c0ac868a', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the difference between Gin and the standard net/http library?', N'Intern', N'While net/http is the standard library for building web servers in Go, Gin is a third-party framework built on top of it. Gin adds features like advanced routing, context management, and simplified request handling to make development faster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f0c987f-64b8-4730-ba5e-26fa2e15cc76', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does multi-version concurrency control (MVCC) improve performance in high-concurrency environments?', N'Senior', N'MVCC allows multiple versions of a record to exist simultaneously, enabling read operations to access a consistent snapshot without being blocked by concurrent write operations. This significantly reduces lock contention and prevents readers from blocking writers, leading to higher throughput in read-heavy and mixed-workload systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8cd0507-1c74-4fc6-ba51-26fa948b16c5', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of ''Pin'' in asynchronous Rust?', N'Middle', N'Pin is used to ensure that a value cannot be moved in memory, which is essential for self-referential structs used in async futures. If a future contained a reference to one of its own fields, moving that future would invalidate the pointer, so Pin guarantees the memory address remains stable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8fd242c-1f6e-4bf5-a84f-2700cf069d1d', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the difference between a Unique Index and a Primary Key constraint.', N'Middle', N'A primary key constraint enforces uniqueness and implicitly disallows null values while creating a unique index. A unique index strictly enforces that all values in the column or columns are distinct but allows null values depending on the specific implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33bd177a-52c8-4b8a-baed-2701037deee4', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you choose between optimistic and pessimistic locking for concurrent data access?', N'Senior', N'Optimistic locking is preferred when contention is low, as it avoids locking resources and keeps the system responsive. Pessimistic locking is chosen for high-contention environments where the cost of retries or data conflicts outweighs the performance penalty of holding locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26817762-ad48-4a58-9c25-27075e480b35', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does the assignment operator work in R?', N'Fresher', N'R primarily uses the arrow operator to assign values to variables. While the equal sign can also be used, the arrow operator is the standard convention in the R community to clearly distinguish assignment from function argument passing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc149e71-a8a2-4176-bac7-2707df1202d7', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is Cache Warming, and when should it be performed?', N'Middle', N'Cache warming is the practice of pre-populating a cache with frequently accessed data before the system goes live or after a cache reboot. It is typically performed during deployments or maintenance windows to prevent a sudden spike in database load and ensure high performance from the moment traffic resumes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99421018-7696-44de-a50d-270a4a5f182a', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the concept of WSGI and how Flask interacts with it.', N'Middle', N'WSGI is the standard interface between a Python web application and a web server. Flask implements the WSGI interface, meaning the server passes requests to the Flask application as a standard dictionary and expects a response in a specific format. This abstraction allows Flask to be deployed on any server that supports the WSGI standard.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75f41cbb-f604-46d4-af5a-270b560622d5', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of the ''void'' pointer in C?', N'Intern', N'A void pointer is a special type of pointer that can point to any data type, as it does not have a specific type associated with it. It serves as a generic pointer that must be typecast before the data it points to can be accessed or manipulated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93b57c26-784d-4fca-aeb1-270c81a1f0ab', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why might you use an Abstract Class instead of an Interface?', N'Middle', N'Abstract classes allow you to define both the structure of a class and provide implementation details for some methods. Interfaces, conversely, only define the contract and cannot contain any implementation logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebe71151-19a3-46d3-bc39-27111adda53a', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the concept of ''Context'' in Laravel''s logging and observability.', N'Senior', N'Logging context allows developers to attach metadata, such as request IDs or user IDs, to log entries. This is crucial in distributed systems for tracing a specific user''s journey through multiple services and components, making it significantly easier to debug production issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'938b960b-dd8d-4169-a383-27125f22d8dc', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is CRUD, and how is it implemented in Rails?', N'Intern', N'In Ruby on Rails, the CRUD actions (Create, Read, Update, Delete) profoundly simplify database interactions through a Model''s active record representation. Key Components - Model: Represents the data and its rules. - View: Presents data to the user. - Controller: Acts as an intermediary that processes user input and interacts with the model and view. Simplified Workflow 1. Create: POST an entity data to the server. 2. Read: Fetch all entities with GET or a specific one by ID. 3. Update: PUT the modified entity. 4. Delete: Remove an entity with a DELETE request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03fb6023-628a-4a7c-8c65-2712a5de6071', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between Vertical and Horizontal partitioning?', N'Middle', N'Vertical partitioning involves splitting a table into separate tables by columns, often to separate frequently accessed data from rarely accessed BLOBs. Horizontal partitioning, or sharding, involves splitting rows across different tables or servers to distribute the load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e7d2c28-7670-407e-b433-2717a6f405f2', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Describe the difference between ''early binding'' and ''late static binding'' in PHP.', N'Middle', N'Early binding resolves class references at compile time, which can lead to unexpected behavior when inheriting static methods. Late static binding uses the ''static'' keyword to defer resolution until runtime, allowing the code to reference the class that was actually called, which is essential for flexible class hierarchies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39161eb1-e599-4bb2-8aa7-271900d07364', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How do you handle graceful shutdowns in a Rocket application?', N'Middle', N'Rocket provides a built-in mechanism to handle shutdown signals, allowing the server to finish processing active requests before terminating. You can configure this via the Rocket configuration or by programmatically triggering a shutdown command during the application lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0a6efef-6f9e-4599-a602-271f71ed335d', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is a Webpack ''target'' and why is it important?', N'Middle', N'The target configuration specifies the environment for which your code is being built, such as ''web'', ''node'', or ''electron''. Setting the correct target ensures that Webpack includes the appropriate boilerplate and runtime code to support the specific features and APIs available in that environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d518516-5365-43d5-997d-27210342c65c', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why might you choose a micro-task queue over a macro-task for specific asynchronous operations?', N'Senior', N'Micro-tasks, such as Promise resolutions, have higher priority and will always run before the next phase of the event loop. This ensures that certain state updates are processed as quickly as possible, though it carries the risk of starving the event loop if the micro-task queue is flooded with recursive promises.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c426f6b7-3d52-4984-8a96-27220cdf60bf', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing for multi-region availability, how do you manage data synchronization?', N'Senior', N'I categorize data into globally replicated state and region-local state to minimize cross-region latency. For global data, I use active-active or active-passive replication strategies with conflict resolution logic, ensuring that the system remains operational even if an entire region experiences an outage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6339702-2542-4cdf-8824-2724171ec2ff', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask''s configuration management support environment-specific deployments?', N'Senior', N'Flask uses a configuration object that can be loaded from Python files, environment variables, or objects, allowing for clean separation between development, testing, and production settings. This enables externalizing sensitive data like secret keys and database URLs, which is a fundamental requirement for secure 12-factor application design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1688d7b-e339-4408-83c9-272611776328', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust''s ''Drop'' trait interact with the stack-based memory management model?', N'Senior', N'The ''Drop'' trait provides a hook for deterministic resource cleanup when an object goes out of scope. Because Rust relies on RAII, the compiler automatically inserts calls to the drop method, ensuring that memory and external resources are released predictably without needing a garbage collector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
