INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9650919b-8e03-4125-ae6a-2749b686db2b', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is a Pipe used for in NestJS?', N'Junior', N'Pipes are used for two main purposes: transformation and validation. They can transform input data to the desired format or validate the incoming data and throw an exception if the data is incorrect.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d7a389c-1cdd-4d3f-954f-2749c5b0ddce', N'4c000000-0000-0000-0000-000000000005', N'How do you ensure data integrity in a system using asynchronous messaging?', N'Senior', N'Implement the transactional outbox pattern to ensure that state changes and event publishing occur atomically. Additionally, design consumers to be idempotent by checking for duplicate processing, which is necessary because distributed systems cannot guarantee exactly-once delivery without significant performance costs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce435129-7e31-4754-94a9-2749e20195c9', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind CSS ensure that the generated CSS file remains small?', N'Fresher', N'Tailwind uses a process called tree-shaking that scans your project files for class names and only includes the CSS for the utilities that are actually being used. This ensures that the final stylesheet does not contain unused code, keeping the file size minimal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08b45cb6-e9ad-4c7e-8102-274a207a0447', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How can you implement versioning in NestJS APIs?', N'Fresher', N'Versioning allows you to have different versions of your controllers or individual routes running within the same application. There are 4 types of versioning that are supported: 1. URI Versioning: The version will be passed within the URI of the request (default). 2. Header Versioning: A custom request header will specify the version. 3. Media Type Versioning: The Accept header of the request will specify the version. 4. Custom Versioning: Any aspect of the request may be used to specify the version(s). A custom function is provided to extract said version(s). To enable Header Versioning for your application, do the following: Check this to see how the above types of versioning are implemented.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20f0d656-4872-4bb3-b35d-274a2e010a5b', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a read lock in a database?', N'Junior', N'A read lock allows multiple transactions to read a data object simultaneously but prevents any transaction from modifying the data. It ensures that the data being read does not change while the transaction is processing it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'076652d5-2836-40b4-ab09-274be249ff42', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why is Axum''s design often described as ''composable''?', N'Middle', N'Axum is composable because it relies on the ''Router'' and ''Service'' abstractions, allowing developers to build complex applications by combining smaller routers and middleware layers. This modularity makes it easy to refactor or extend features without impacting the entire application structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c1ed9cc-37ef-46bd-9440-274d004eab50', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is it generally discouraged to create unbounded goroutines in a high-traffic system?', N'Senior', N'Unbounded goroutine creation can lead to memory exhaustion and excessive GC pressure, as each goroutine consumes stack memory and runtime metadata. Implementing a worker pool pattern or using rate-limiting middleware is necessary to bound resource consumption and maintain system stability under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9f8ec3f-13e9-4399-818c-274f2a20dbee', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why is Preact considered ''modular''?', N'Fresher', N'Preact is modular because it provides a core library that handles the essentials, while other features like routing or state management are provided as separate, optional packages. This keeps the core bundle extremely small.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'030b8454-73cc-41d9-97f0-2752b93ab5cc', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Conditional Types and what problem do they solve?', N'Middle', N'Conditional types allow the selection of one of two possible types based on a boolean condition expressed as a type relationship. They solve the problem of creating flexible, reusable generic types that need to adapt their return type based on the inputs provided to them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b54e814-e796-40c2-bedb-2753161d6514', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How do you access component data inside a method?', N'Fresher', N'Since your methods are defined within the scope of your x-data object, you can access your data variables using the ''this'' keyword. This refers to the component instance, allowing you to read or update variables defined in x-data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c811105-bbb0-40e3-bc0a-27542ad6f076', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the pass statement in Python?', N'Intern', N'There may be times in our code when we haven''t decided what to do yet, but we must type something for it to be syntactically correct. In such a case, we use the pass statement. Similarly, the break statement breaks out of a loop. 0 1 2 Finally, the continue statement skips to the next iteration. 0 1 2 4 5 6', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a10b822e-eec9-41ad-ace5-275448a6c79e', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a primary key in a database?', N'Intern', N'Definition: Primary Key (PK) A Primary Key is a constraint that uniquely identifies each tuple (record) within a relation (table). It serves as the immutable anchor for Entity Integrity. Key Characteristics - Uniqueness: The database engine enforces a UNIQUE constraint, ensuring no two rows share the same key value. - Non-Nullity: The column must be NOT NULL. Absence of value is logically incompatible with identification. - Immutability: Once assigned, the PK value should not change. Updates to PKs trigger cascading updates across dependent indexes and foreign key relationships, incurring significant $O(n)$ overhead. Data Integrity & Structural Role - Entity Identity: Enforces that the row represents a single, distinct real-world object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07ca4ba9-1f3e-4763-833d-27565fac2870', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are Higher-Order Components (HOCs) in the context of Preact?', N'Junior', N'An HOC is a function that takes a component and returns a new component with additional functionality or props. It is a common pattern for reusing component logic across different parts of an application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a1966a1-5800-4bb2-adda-2758d7b52f80', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What does the Scala compiler target?', N'Intern', N'The Scala compiler targets the Java Virtual Machine. This allows Scala code to run on any platform that supports Java and enables seamless interoperability with existing Java libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f7ef618-4447-410c-b93f-2761b7b01209', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle large file uploads?', N'Middle', N'Fastify manages file uploads by integrating with busboy, allowing for efficient streaming of multipart/form-data. This prevents loading large files entirely into memory, which is critical for maintaining application stability and preventing heap overflows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c681ca1-89b1-414f-82e1-27626d27d5c1', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the implications of using decorators on performance?', N'Middle', N'Decorators wrap functions and add a layer of indirection, which introduces a minor overhead for each call. While usually negligible, this overhead can accumulate in performance-critical loops or high-frequency function calls, making it important to use them judiciously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'412be05a-4e1a-4893-a967-27631a60ec8d', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why is the order of middleware registration significant in Axum?', N'Senior', N'Middleware in Axum is applied in a nested fashion, meaning the first middleware registered is the outermost one. The order is critical because it dictates the sequence in which requests are intercepted and responses are processed, affecting behavior like request logging, authentication enforcement, and error handling order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddb175e4-1219-4e8f-b428-2765a23d5fcb', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of ''Ecto.Query.preload''?', N'Middle', N'Preloading is used to solve the N+1 query problem by fetching associated data in separate, optimized queries. It ensures that related records are loaded into the struct, reducing the total number of database roundtrips required to render a resource.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1f93db8-18da-49ff-ac99-2767f17d9bb0', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What happens to the application state when moving from server to client in Qwik?', N'Fresher', N'The application state is serialized into the HTML document as JSON data by the server. When the client-side application starts, it reads this serialized state, allowing it to pick up exactly where the server left off.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cf45a59-c8cf-4802-9786-27699a171575', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach estimating the effort required for infrastructure or DevOps tasks?', N'Middle', N'Infrastructure tasks often involve hidden complexities like configuration drift or environment constraints. I approach these by creating a checklist of required steps and adding a significant buffer for debugging and environment-specific issues that frequently arise during implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01745bc8-780d-4472-9033-276b3cb65098', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you diagnose an issue where a service is experiencing high latency only for a specific set of users?', N'Senior', N'I would analyze the request context to see if these users are hitting specific database partitions or cached data shards that are overloaded. I would also look for patterns such as large payload sizes or complex query parameters that only affect that user segment, potentially identifying a performance edge case in the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fd7fe70-a7c7-4b77-b667-276c199a1813', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the benefit of using the parent selector (&) in Sass?', N'Fresher', N'The parent selector (&) allows you to reference the parent element within a nested block. It is primarily used for pseudo-classes like hover or focus, or for creating BEM-style naming conventions efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bcab3eb-e8f3-4580-99c4-2772fc781e34', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is static site generation in the context of Astro?', N'Junior', N'Static Site Generation (SSG) is the process of building the entire website into static HTML files at build time. Astro excels at this, creating highly optimized files that are easy to deploy to any CDN or hosting provider.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'689dec61-693b-446d-b2d0-2775f0146bb9', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is a structure in C?', N'Intern', N'A structure is a user-defined data type that allows you to group related variables of different data types under a single name. This enables the creation of complex data objects that represent a single entity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'635039b3-7947-4154-b85d-277742d5fe36', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the role of the Microtask Queue in the JavaScript event loop and how does it prioritize execution?', N'Senior', N'The microtask queue processes tasks like Promise resolutions and MutationObserver callbacks immediately after the current synchronous execution stack clears. It takes priority over macrotasks, ensuring that asynchronous state updates are reflected before the engine yields to the next rendering phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b1d8add-4425-4e5e-b299-2779d3bab710', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How do ''tabindex'' attributes affect accessibility?', N'Middle', N'The tabindex attribute controls the keyboard focus order of elements on a page. A positive value changes the sequence, which is generally discouraged as it creates non-intuitive navigation, while 0 adds an element to the natural tab order. A value of -1 removes an element from the tab order but allows it to be focused programmatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd72f1df9-3b6f-4669-8831-277a700b34ed', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Does Redis support ACID compliance?', N'Fresher', N'Redis supports atomicity and consistency to a certain extent through transactions and its single-threaded nature. However, it does not provide full ACID compliance in the same way that traditional relational databases do.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf810ced-8efe-4470-86c4-277b5de152c7', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift ensure thread safety?', N'Middle', N'Swift achieves thread safety primarily through the use of value types, which prevent shared mutable state, and concurrency primitives like Actors. Actors provide a mechanism to protect shared state by ensuring that only one task can access their internal data at any given time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56eb3aa9-0f1d-4e97-9567-277cf4c36f2a', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are environment variables and why use them in Express?', N'Junior', N'Environment variables store configuration settings like database credentials or API keys outside of the source code. This improves security and allows the application to behave differently across development, testing, and production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcd0afe8-a868-47b3-a722-2781fcbf1546', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is meant by ''scoped'' in Alpine.js?', N'Intern', N'Scoping refers to the fact that directives and data defined within an element are only accessible to that element and its children. This prevents variable naming conflicts across different parts of the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55d67ad6-e57d-453d-9bf2-2785b98c39e6', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of an initializer in Swift?', N'Intern', N'An initializer is a special method used to prepare an instance of a class, struct, or enum for use. It sets initial values for all stored properties and performs any other setup required before the instance is ready to be used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'294539c1-126b-482a-bcf8-278686c94c56', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI leverage Python''s type hints for request validation and serialization?', N'Middle', N'FastAPI uses Pydantic models and Python type hints to automatically parse incoming request data into complex objects. It validates the data types against the schema and serializes the response back to JSON, providing built-in error handling for malformed requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf09a708-90d8-45b2-93ee-27877309f1e0', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi differ from a full-blown web framework?', N'Intern', N'Unlike a full framework that might include ORMs, template engines, and built-in validation, Chi is strictly a router. It provides only the essential infrastructure for routing and middleware, leaving the rest of the architectural decisions to the developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c72a0b6-95f5-4db3-a421-2787d1830f61', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are the architectural risks of using ''lateinit'' properties in multi-threaded environments?', N'Senior', N'Lateinit properties are not inherently thread-safe, and accessing them before initialization results in an UninitializedPropertyAccessException. In multi-threaded applications, there is a risk of a race condition where one thread attempts to read the property before another has finished initializing it, requiring external synchronization mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d24a13d-1e96-482f-9b1a-2788bf14ea3f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are named parameters in Dart and why are they useful?', N'Junior', N'Named parameters are optional parameters that are identified by their name rather than their position in the function call. They improve code readability and maintainability, especially when a function has many parameters or several optional ones.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00590a89-218f-46f0-a3dc-2789da459b4b', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the purpose of ''NuxtLink''?', N'Fresher', N'NuxtLink is a component used for navigation between pages within your application. It acts as a wrapper for the standard HTML anchor tag, providing optimized client-side navigation without triggering a full page reload, which keeps the user experience smooth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5add29f2-2a07-4861-a59b-278c367b8f0e', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the difference between React and ReactDOM?', N'Fresher', N'The react package contains React.createElement(), React.Component, React.Children, and other helpers related to elements and component classes. You can think of these as the isomorphic or universal helpers that you need to build components. The react-dom package contains ReactDOM.render(), and in react-dom/server we have _server-side rendering_ support with ReactDOMServer.renderToString() and ReactDOMServer.renderToStaticMarkup().', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffe99968-43a8-4109-9ad8-278d9c560eb4', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of a Voter in Symfony Security?', N'Middle', N'A Voter is a specialized security component used to implement custom authorization logic. It evaluates whether a user has permission to perform a specific action on a resource, keeping complex access control rules out of controllers and services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af49343d-c3e0-4d23-9055-27926365b349', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the option to choose between inline and external template file?', N'Intern', N'You can store your component''s template in one of two places. You can define it inline using the template property, or you can define the template in a separate HTML file and link to it in the component metadata using the @Component decorator''s templateUrl property. The choice between inline and separate HTML is a matter of taste, circumstances, and organization policy. But normally we use inline template for small portion of code and external template file for bigger views. By default, the Angular CLI generates components with a template file. But you can override that with the below command,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11048ff4-4033-4ade-a6f1-2794e15bf83f', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Explain the architectural difference between Astro components and standard React components.', N'Senior', N'Astro components are server-only files that render to static HTML at build time, whereas React components are typically designed to be hydrated into dynamic client-side elements. Astro components do not execute in the browser, making them lightweight and zero-cost in terms of runtime bundle size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd672cab6-d69b-48b9-9025-27951f9a2f6d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the security implications of using innerHTML versus modern DOM manipulation APIs in terms of Cross-Site Scripting (XSS)?', N'Senior', N'Using innerHTML allows for the injection of raw HTML strings, which can execute malicious scripts if input is not properly sanitized. Modern APIs like textContent or DOMParser ensure that content is treated as text or safely parsed, significantly reducing the attack surface for XSS vulnerabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9e82e53-bc38-47c0-87c6-2796d0feeadf', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'In the context of Rails, what is the ''N+1 query problem'' and why is it particularly dangerous in large-scale systems?', N'Senior', N'The N+1 problem occurs when an application executes one query to fetch a parent record and an additional query for each child association, causing an exponential increase in database load. In large systems, this latency compounds quickly, potentially exhausting database connection pools and causing cascading failures across the service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'720d3c1f-325f-44af-a207-2797070ea759', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the security risk of ''shadow IT'' and how can architecture prevent it?', N'Senior', N'Shadow IT occurs when teams deploy infrastructure or services outside of centralized governance, leading to unpatched systems and data leaks. Architecture can prevent this by providing self-service, compliant, and pre-approved cloud landing zones that make the path of least resistance the most secure path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
