INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fd33558-e961-4308-baf1-27a15e13bbf5', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why would you choose a Wide-Column store like Cassandra over a Relational database for time-series data?', N'Senior', N'Wide-column stores handle massive volumes of append-only data by leveraging partition keys to distribute writes across a cluster. They avoid the overhead of relational joins and locking mechanisms, providing predictable performance for high-velocity ingest that would overwhelm a traditional RDBMS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
