INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c253715b-70ea-47be-a373-27b43b04ce12', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the architectural considerations when choosing between a monolith and microservices in a Node.js ecosystem?', N'Senior', N'Monoliths offer simpler deployment and shared memory access but can become difficult to scale and maintain as the codebase grows. Microservices provide better team autonomy and independent scaling but introduce complexities in service discovery, distributed tracing, and network latency. The choice depends on team size, deployment frequency, and fault tolerance requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d1d1014-a51b-40d7-a63a-27b4e309f989', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Can Alpine.js be used alongside other frameworks like React or Vue?', N'Fresher', N'Yes, Alpine.js can coexist with other frameworks on the same page. However, it is generally recommended to use it as a standalone solution for adding small interactive features to static pages rather than as a replacement for full-blown application frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fae8f85e-d553-4e8d-90ec-27b51cfa5e76', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the purpose of the script tag in a Svelte file?', N'Intern', N'The script tag contains the JavaScript logic for the component. It is where you define variables, functions, and state that will be used to control the component''s behavior and data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e041a8a-167b-4240-942b-27b805da8cea', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is it generally discouraged to use jQuery alongside modern frameworks like React or Vue?', N'Middle', N'Modern frameworks rely on a virtual DOM and declarative state management to synchronize the UI. jQuery directly manipulates the real DOM imperatively, which creates a conflict with the framework''s internal rendering cycle and can lead to unpredictable state inconsistencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd34d5060-64e4-4519-8e27-27b8e4be7490', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why does SolidJS not use a Virtual DOM?', N'Intern', N'SolidJS avoids the Virtual DOM because it adds unnecessary overhead by comparing old and new trees. Instead, SolidJS compiles templates into real DOM nodes and sets up direct subscriptions to reactive updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'809831de-bf37-4ee9-9970-27b9bac76cf9', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of the ''before_request'' and ''teardown_request'' hooks in the Flask lifecycle?', N'Senior', N'These hooks allow you to execute code before the request is processed and after it has finished, respectively. ''before_request'' is typically used for authentication or setup, while ''teardown_request'' is essential for cleaning up resources like database connections, even if an unhandled exception occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7bd94d3-c144-443d-a8c2-27baad63a59e', N'075b8862-431c-4678-9767-f55359758a4a', N'What is object style commit?', N'Intern', N'You can also commit a mutation is by directly using an object that has a type property. Now the entire object will be passed as the payload to mutation handlers(i.e, without any changes to handler signature).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4112f6bf-34df-495f-93ce-27baba56de1b', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB handle data consistency?', N'Fresher', N'DynamoDB supports both eventually consistent and strongly consistent reads. Eventually consistent reads are faster but might return stale data, while strongly consistent reads return the most up-to-date data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b354d154-5871-4581-a737-27bdd10f96c4', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are loaders evaluated in what order?', N'Fresher', N'Loaders are evaluated from right to left, or bottom to top in the configuration array. This means the last loader in the list is the first one applied to the source file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebcac991-38af-4f27-b53d-27be5132f094', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How does isolating a component help in debugging?', N'Fresher', N'Isolating a component allows you to test it independently of external dependencies like databases or APIs. If the component works in isolation, you know the issue lies in the interaction between components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4bd0815-840a-42de-9c66-27be5f627c0a', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the purpose of the ''reply'' object in Fastify?', N'Intern', N'The reply object is a core component used to send responses back to the client. It provides methods to set headers, status codes, and the body of the response, offering a consistent interface for managing outbound communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87c9071f-62d7-43ed-8775-27beee3eae56', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does asynchronous processing help a system scale?', N'Middle', N'Asynchronous processing decouples long-running tasks from the main execution thread by using message queues. This prevents the system from blocking while waiting for a task to complete, allowing the application to remain responsive under heavy load while processing background tasks at its own pace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50ff41cd-f7e0-4fec-bca0-27c3cca0ccb2', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Explain the trade-offs of using Nuxt’s ''static'' target versus a Node.js server.', N'Middle', N'Static generation pre-renders pages at build time, offering extremely fast delivery via CDN and high security, but it requires a full site rebuild for content updates. A Node.js server allows for dynamic, real-time data and personalized content, though it requires persistent server maintenance and higher infrastructure costs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca29b94c-c080-4f22-9cb2-27c8720a4ca3', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the role of the ''Transaction Coordinator'' in distributed systems.', N'Senior', N'The coordinator manages the life cycle of a distributed transaction, including the voting and decision-making phases. It is responsible for orchestrating the participants, ensuring they all agree on the outcome, and logging the final result to guarantee durability in case of failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a2f2271-2f2d-4d2a-8fcc-27cc7a68eebc', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why do we need a development server like webpack-dev-server?', N'Intern', N'A development server provides features like live reloading and hot module replacement. It serves your application files from memory rather than the disk, which significantly speeds up the development process by avoiding constant file writing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84477a1a-7d3a-43f3-a6e7-27cdee851228', N'4c000000-0000-0000-0000-000000000005', N'When would you use a read replica?', N'Middle', N'You use read replicas when a system has a high read-to-write ratio. By directing all read queries to the replicas, you reduce the load on the primary database, which can then focus on handling write operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e0bb35e-12b7-4178-b5ed-27ceac3e3508', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is responsive web design?', N'Intern', N'Responsive web design is an approach that ensures web pages render well on a variety of devices and screen sizes. It uses fluid grids, flexible images, and media queries to adapt the layout based on the user''s viewport.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
