INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ad7edd9-bca9-4250-92b2-27d23f9e9d84', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Discuss the architectural trade-offs of using hardware security modules (HSMs) versus software-based key stores.', N'Senior', N'HSMs offer superior protection by keeping cryptographic keys in tamper-resistant physical hardware, which is essential for compliance and high-security requirements. Software-based stores are cheaper and more flexible for cloud-native deployment but are potentially more vulnerable to exploitation if the underlying host or memory is compromised.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afae69cf-c283-4986-aea6-27d374414b41', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the performance implications of using deep cloning versus shallow cloning for large object structures?', N'Middle', N'Shallow cloning is computationally inexpensive as it only copies top-level references. Deep cloning recursively traverses the entire object tree, which can lead to significant performance bottlenecks, high memory consumption, and potential stack overflow errors with circular references.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b65ee038-a22e-40d8-bbe2-27d3f3c78114', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What does ''autowiring'' mean in Symfony?', N'Junior', N'Autowiring is a feature of the Service Container that automatically detects the dependencies of a service based on its constructor type-hints. It eliminates the need to manually configure every service, significantly reducing the amount of boilerplate code required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e453c9a4-de61-4fa6-85f0-27d443d08f8f', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the advantages of using Stored Procedures?', N'Junior', N'Stored procedures improve performance by reducing network traffic between the application and database. They also enhance security by allowing access control and enable code reusability across different applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b179bd6-b116-41f0-b063-27d6aaf8cfd3', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Explain the difference between ''Started'' and ''Running'' states in an actor''s lifecycle.', N'Senior', N'The ''Started'' state represents the initial setup phase where resources are allocated, while the ''Running'' state indicates the actor is actively polling its mailbox for messages. Proper lifecycle management ensures that state initialization is completed before the actor begins processing concurrent requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e6e12ea-d381-42f8-91f6-27d8ab52eec8', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the @Introspected annotation?', N'Intern', N'The @Introspected annotation instructs Micronaut to generate bean introspection data at compile-time. This is often used for serialization and deserialization, allowing the framework to access bean properties without using reflection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3dd0fbc-7640-493c-b04d-27d9c14803c8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How can you implement secure authentication and authorization in JavaScript applications?', N'Fresher', N'To implement secure authentication and authorization in JavaScript applications, use HTTPS to encrypt data in transit, and store sensitive data like tokens securely using localStorage or sessionStorage. Implement token-based authentication using JWTs, and validate tokens on the server side. Use libraries like OAuth for third-party authentication and ensure proper role-based access control (RBAC) for authorization. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the same-origin policy with regards to JavaScript The same-origin policy is a security measure implemented in web browsers to prevent malicious scripts on one page from accessing data on another page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d306c3c-2889-489d-93a1-27e0bc112afc', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you account for non-functional requirements like security or performance in your feature estimates?', N'Middle', N'I treat non-functional requirements as core components of the feature rather than afterthoughts. I include specific tasks for testing and verification in the initial scope so that the time required to meet these standards is reflected in the overall delivery estimate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cae93429-d9c9-408d-9f07-27e1c071960e', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Why is it important to use ''typing'' extensively in Litestar applications?', N'Middle', N'Litestar heavily utilizes Python type hints for dependency injection, serialization, and OpenAPI documentation generation. Strong typing allows the framework to perform introspection to automatically configure routing and validation, reducing the need for explicit boilerplate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86b169d9-99ee-4744-b1cc-27e208ffc742', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the role of the Spring IoC Container?', N'Intern', N'The IoC container is responsible for creating, configuring, and managing the lifecycle of Spring beans. It reads configuration metadata to determine how to instantiate the objects and manages the dependencies between them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f1c8b36-9ce9-42dd-b0ae-27e2646eb28e', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the concept of ''Request'' and ''Response'' in Laravel.', N'Fresher', N'The Request object encapsulates all data sent by the user, such as form inputs or headers, while the Response object represents the data sent back to the user''s browser. Laravel simplifies this interaction by providing dedicated classes to access input data and define the content type of the outgoing response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d86ef6c-116e-4342-bb49-27e3257afba1', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does C++ template metaprogramming affect binary size and build scalability?', N'Senior', N'Template metaprogramming causes code bloat because the compiler generates a unique instantiation for every distinct set of template arguments used. While this maximizes runtime performance by eliminating runtime dispatch, it drastically increases build times and memory usage during compilation as the compiler handles complex recursive template expansions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99a8b171-c8f2-4df0-bcfa-27e45d23b4cb', N'4c000000-0000-0000-0000-000000000005', N'What is a circuit breaker pattern and when is it used?', N'Middle', N'The circuit breaker pattern detects service failures and prevents an application from repeatedly trying to execute an operation that is likely to fail. It prevents cascading failures by failing fast, allowing the failing service time to recover while maintaining system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e5fbfda-0834-445c-be47-27e4f69c580a', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite achieve CSS code-splitting?', N'Middle', N'Vite automatically detects CSS imports within components and splits them into separate files during the build process. These CSS chunks are then loaded dynamically only when the corresponding JavaScript components are imported, preventing unnecessary styles from being downloaded on initial page load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a9bd693-5559-4010-96c9-27e54a32fbee', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript handle type compatibility?', N'Intern', N'TypeScript uses structural typing, meaning it compares the structure of two types rather than their names. If one object has all the required members of another object, they are considered compatible, regardless of whether they share the same class or interface name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5512af33-b80a-4f44-8d73-27e666047f6c', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How do multi-column indexes differ from individual indexes on the same columns?', N'Senior', N'Multi-column indexes are optimized for queries that filter or sort by the specific prefix of columns defined in the index. While they take up more space, they are often more efficient than individual indexes because they allow the planner to satisfy complex filter conditions in a single index scan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea7b556b-2bb4-4291-ba68-27e6a99bae32', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the significance of the OpenAPI (Swagger) documentation in FastAPI?', N'Junior', N'FastAPI automatically generates an interactive API documentation page based on your path operations and type hints. This helps developers and frontend teams understand the available endpoints and their expected parameters without extra work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c22bb2be-9d82-4093-9dc3-27ea4bc11619', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does the ''preact-compat'' layer manage compatibility without bloating the core bundle?', N'Senior', N'The compat layer acts as an alias shim that maps React-specific APIs to Preact’s internal implementation. It allows developers to use the React ecosystem while keeping the core engine lightweight by only including necessary compatibility logic if explicitly imported.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a60b6924-987e-476e-9d3e-27ea91baf619', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the difference between ''Quorum'' and ''All'' consistency levels?', N'Junior', N'A Quorum requires a majority of replicas to acknowledge a request, balancing performance and consistency. ''All'' requires every single replica in the cluster to respond, providing the highest possible consistency but making the system highly vulnerable to failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f10d7e81-2473-4f12-853e-27ec934669a4', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the <time> element and why is it useful?', N'Intern', N'The element represents a specific date, time, or duration. The datetime attribute provides a machine-readable format while the element''s text content can be human-readable. Syntax: Why it matters: Search engines (Google''s Knowledge Graph, schema.org microdata) use the datetime attribute to accurately index events, articles, and schedules. Screen readers can interpret the date format correctly regardless of how it''s displayed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8763fa5b-cf28-44d8-91d3-27ede9eebd7b', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between a request argument and a form argument?', N'Junior', N'Request arguments are passed through the URL query string, while form arguments are sent in the body of a POST request. They are accessed via the ''args'' and ''form'' attributes of the request object respectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd7716fc-1330-4be8-8d44-27edeca1594a', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why does Preact exclude certain React features like ''Suspense'' or ''Error Boundaries'' from the core package?', N'Senior', N'Preact excludes these to maintain a tiny core, delegating specialized features to modular plugins that can be loaded only when required. This philosophy ensures that the baseline cost of using Preact remains constant regardless of whether the developer needs advanced error handling or asynchronous loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f873be7e-0672-4784-955d-27ee91caf391', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the purpose of ''API Composition'' in a microservices architecture?', N'Senior', N'API Composition is an architectural pattern where an aggregator service calls multiple microservices to build a unified response for a client. It simplifies client interaction but introduces a potential single point of failure and increases the complexity of error handling and latency management within the aggregator.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48d435b5-b04a-450a-b608-27ee9b9121ee', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is it often considered a best practice to extract components in frameworks like React when using Tailwind?', N'Middle', N'While Tailwind allows for rapid styling, repeating long strings of utility classes across multiple elements leads to poor maintainability and visual inconsistency. Extracting these into reusable components or using directives helps keep the markup clean and ensures that design changes can be applied globally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'272c9d15-e96f-4546-9b64-27eea2e583d2', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is ''index-only scan'', and how does the visibility map contribute to this optimization?', N'Senior', N'An index-only scan retrieves data directly from the index without accessing the heap. The visibility map identifies which pages contain only tuples visible to all active transactions, allowing the planner to bypass heap access if the index contains all required columns and the visibility status is confirmed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cd161de-72db-41c2-b80f-27f0339b53fe', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What does ''state is read-only'' mean in Redux?', N'Intern', N'This means that the state cannot be modified directly by the application code. The only way to change the state is by dispatching an action, which triggers the reducer to create a new state object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcb31c20-dd57-4ea6-abb3-27f21eb6479b', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a goroutine in Go and how does it differ from a thread?', N'Fresher', N'A goroutine is a lightweight thread managed by the Go runtime rather than the operating system. They require significantly less memory than traditional OS threads, allowing developers to run thousands or even millions of them concurrently within a single program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f10bcb8-7b72-47b5-849d-27f2ba7a8b43', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the purpose of the .attr() method?', N'Intern', N'The .attr() method is used to get or set the value of attributes on HTML elements, such as ''src'', ''href'', or ''title''. It allows you to dynamically modify element properties directly through the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'757624b5-0f66-4f46-aa99-27f65dde5e8c', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle a scenario where a third-party API dependency experiences frequent outages?', N'Senior', N'I would implement the circuit breaker pattern to stop calling the failing API and provide a fallback response, such as cached data or a default value. I would also implement a robust retry policy with exponential backoff and potentially queue the requests for later processing once the service stabilizes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77f444a5-e366-41a8-9444-27f86393426e', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the ''mode'' option in Vite?', N'Intern', N'The mode option allows developers to specify which environment settings to load, such as ''development'' or ''production''. Different modes can trigger different build behaviors and load specific environment variable files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91b2f7e5-9a6f-47e0-bbbc-27fc44acd4ac', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a foreign key, and why is it used?', N'Junior', N'A foreign key is a column or group of columns that provides a link between data in two tables. It acts as a cross-reference between tables by referencing the primary key of another table, ensuring referential integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd85e7ec6-8045-4a01-a09a-27fe7c3dba05', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you optimize a system that is experiencing high latency due to excessive database locks during write-heavy operations?', N'Senior', N'I would look to move write operations into a message queue to decouple the request-response cycle from the database persistence. Alternatively, I would implement optimistic locking or switch to a partition-based database schema to reduce contention on specific rows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b46c57a9-a54e-428e-ac28-2803eff90fbc', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do you handle navigation between pages in SvelteKit?', N'Intern', N'You use the standard anchor tag for navigation. SvelteKit intercepts these clicks to perform client-side transitions, which makes navigation feel faster by only updating the necessary parts of the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdd210f5-68cc-490a-8acf-28044e94993a', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does database connection pooling improve scalability?', N'Senior', N'Connection pooling reduces the overhead of creating and tearing down expensive database connections for every request. By reusing existing connections, the database can handle a much higher volume of concurrent application workers without exhausting memory or process limits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e335ee41-fd6e-4301-92d1-2804d8ed5f47', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the primary purpose of the jQuery library?', N'Intern', N'The primary purpose is to simplify client-side scripting by abstracting complex JavaScript tasks into shorter, more readable methods. It helps developers write less code to achieve common tasks like selecting elements and handling events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcb079c5-ce10-4d30-906a-28070858a7fb', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are Svelte lifecycle functions?', N'Intern', N'Lifecycle functions are special tools that allow you to run code at specific points in a component''s existence, such as when it is created, mounted to the DOM, or destroyed. These are useful for setting up timers, fetching data, or cleaning up resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5a17c15-b3d3-4b59-b693-2807bee9c93a', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the difference between ''Read Committed'' and ''Repeatable Read'' isolation levels regarding phantom reads?', N'Senior', N'Read Committed isolation prevents dirty reads but allows non-repeatable reads, meaning data can change between two reads in the same transaction. Repeatable Read prevents non-repeatable reads by keeping snapshots of records, but depending on the implementation, it may still allow phantom reads where new rows appear in a result set during the transaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33535fd0-d89e-4880-a5bd-280d593f560e', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why is Redis considered a single-threaded architecture, and what are its implications?', N'Middle', N'Redis uses a single-threaded event loop to process commands, which eliminates the overhead of context switching and lock contention associated with multi-threading. While this makes it extremely fast for in-memory operations, it means that long-running commands can block the entire server, potentially impacting latency for subsequent requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e72d23d8-026d-42c3-9cf3-280f0e92bf2d', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is sharding in a database context?', N'Junior', N'Sharding is the process of splitting a large dataset into smaller, more manageable chunks called shards and distributing them across multiple database servers. This technique helps improve performance and allows the database to handle larger amounts of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a5575cb-a690-45d3-ba4e-2817896ee2e6', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is a Laravel Controller?', N'Intern', N'A controller is a class that groups related request-handling logic into a single unit. It acts as an intermediary between the incoming HTTP request and the application''s business logic or database models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21953a38-dbcc-4180-b866-2817fa6e06a3', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the function of the @tailwind directive in a CSS file?', N'Junior', N'The @tailwind directive is used to inject Tailwind’s base, components, and utilities styles into your main CSS file. This tells the build tool where to insert the generated CSS for each specific section of the framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d40c9a9-ae80-4a9f-9d22-281cdcb98f68', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of the TypeScript compiler?', N'Intern', N'The TypeScript compiler, known as tsc, is responsible for transforming TypeScript code into JavaScript. It also performs static analysis to ensure that the code adheres to the defined type rules before the transformation occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5aa8387-afb2-4fe3-a7d2-2820c76b5cd7', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is ''strictNullChecks'' considered the most important setting for robust TypeScript applications?', N'Senior', N'Enabling ''strictNullChecks'' forces developers to handle ''null'' and ''undefined'' explicitly, which are the most frequent sources of runtime crashes in JavaScript. It shifts the burden of checking for missing values from runtime null-checks to compile-time guarantees, significantly increasing application stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'306cbafc-8044-43de-969b-2820e9283ad7', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Describe the challenges of testing a Nuxt application compared to a standard Vue application.', N'Senior', N'Testing Nuxt applications requires mocking the auto-import environment and the global Nitro context, which are not present in standard Vue unit tests. Integration tests often necessitate a full lifecycle environment or a mock server setup to accurately simulate the SSR and hydration process, which is more complex than testing isolated components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8805a24-46d1-4cd3-a8e7-2821091411f2', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit''s reactivity system differ from React''s state management approach?', N'Senior', N'Lit uses a fine-grained reactivity system based on property decorators that trigger localized updates to the DOM when values change. Unlike React''s top-down reconciliation process, Lit updates only the specific parts of the template bound to the changed property, minimizing unnecessary re-renders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdb4a086-9f2a-4851-a6b0-2824a6c884f1', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the difference between GET and POST in Elasticsearch?', N'Intern', N'GET is typically used to retrieve information or documents without changing the state of the system. POST is used to perform actions that result in data modification or complex queries that require a request body.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e62dfbc-6ac2-4075-85b7-2825674ed27b', N'954a0331-deff-4399-b588-96f39fec001d', N'Describe the impact of ''Barrel files'' (index.ts) on Angular build times and circular dependency risks.', N'Senior', N'Barrel files simplify imports by grouping exports, but they can significantly slow down builds by forcing the compiler to parse more files than necessary. Furthermore, they are a frequent source of circular dependencies, which can lead to runtime errors or uninitialized dependencies if not managed with careful import pathing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2db78e35-cd4e-4208-a5ab-28260a4ca7c7', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why might a senior engineer choose Rocket over a dynamic language framework for a high-traffic microservice?', N'Senior', N'The primary reasons are memory efficiency, type safety, and raw performance. Rocket''s compile-time optimizations and lack of a garbage collector provide predictable latency and lower infrastructure costs, which are significant advantages for high-scale, performance-critical services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30544a27-aecf-4118-b1ff-282646313de3', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why is it important to use prepared statements instead of directly concatenating user input into queries?', N'Middle', N'Prepared statements decouple the SQL command from the data parameters, ensuring that the database engine treats input strictly as data rather than executable code. This prevents SQL injection attacks, which are a primary security threat. It also allows the database to cache the query plan for better performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd237ca8b-aa95-4ca3-886a-282662ec43d6', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Describe the security implications of utilizing the ''target=_blank'' attribute in anchor tags.', N'Senior', N'Using ''target=_blank'' allows the newly opened page to potentially access the opening page''s window object via the ''window.opener'' property. This creates a security vulnerability where the new page could maliciously redirect the original tab, which can be mitigated by including ''rel=noopener'' or ''rel=noreferrer''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd00b81e3-6e0c-46eb-a849-282bb907b151', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between an inner join and a left join?', N'Intern', N'An inner join returns only the rows where there is a match in both tables. A left join returns all rows from the left table and the matched rows from the right table, or NULL if no match exists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0b821ee-ed5f-44c9-b18a-282c40009a8a', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the trade-offs of using Flask-Migrate versus manual database schema management.', N'Senior', N'Flask-Migrate, powered by Alembic, automates schema versioning and provides a systematic way to track and apply changes. While manual scripts provide more control, they are error-prone and difficult to synchronize across team members, whereas automated migrations are essential for reliable CI/CD pipelines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f923308-ea4e-43c2-9e7d-2830c6bcd9e0', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why is the ''Container'' pattern important for Ember''s internal orchestration?', N'Senior', N'The container acts as a central registry that manages the lifecycle and instantiation of all framework objects like services, controllers, and components. It ensures that dependencies are resolved correctly and that objects are shared or scoped appropriately throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
