INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b6f56a2-8aaa-49b5-9af5-28354f713073', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you approach the trade-off between data normalization and denormalization in high-read systems?', N'Senior', N'Normalization reduces redundancy and simplifies data integrity but often requires expensive joins in read-heavy applications. I denormalize data when read performance is the priority, accepting the cost of increased storage and the complexity of maintaining data consistency across replicas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
