INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c925e81-1aec-4897-8825-28407bad7163', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does a distributed cache differ from a local in-memory cache?', N'Middle', N'A local cache resides on the application server''s memory, offering extremely low latency but limited capacity and lack of data sharing across nodes. A distributed cache sits on a separate cluster, offering shared state and horizontal scalability at the cost of network latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64125ac0-8901-4445-949a-28427986d80c', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the advantage of using Remix over a traditional Client Side Rendered (CSR) app?', N'Junior', N'Remix provides better performance and reliability by handling data fetching on the server. This reduces the amount of JavaScript required on the client and ensures the app remains functional even on slow network connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad281dbb-f414-415f-b830-284515cbd412', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the advantage of using ''NuxtLink'' over a standard anchor tag?', N'Middle', N'NuxtLink provides client-side routing, which enables instant page transitions without a full browser refresh. It also pre-fetches the target page in the background when the link enters the viewport, significantly improving the perceived speed of navigation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d25cecf-a174-44e0-996e-28460c96188f', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What are the common causes of a ''Time Out'' error?', N'Junior', N'Time-outs usually occur when a service, database, or network request takes longer to respond than the configured threshold. This can be caused by heavy load, inefficient queries, or a complete failure of a downstream service that is not responding at all.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ac4ddf9-26c7-4cc4-b8d1-28463c3e510d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using an open-source tool versus a paid commercial product?', N'Fresher', N'Open-source tools are usually free and have community support but may require more internal effort for configuration and security patching. Commercial products often provide dedicated support and easier integration but come with licensing costs and vendor lock-in.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24638844-3b88-4550-b4a4-28499f09467f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do JavaScript generators handle asynchronous control flow?', N'Senior', N'Generators allow a function to pause execution and yield control back to the caller using the yield keyword. When combined with a runner, they can write asynchronous code that looks and behaves synchronously, providing a precursor to modern async/await syntax.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75812778-12e8-4877-af78-284c03f4187f', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Explain how Gin manages the lifecycle of a request.', N'Middle', N'A request enters the Gin engine, which resolves the route via the Radix tree, executes the global middleware, processes the route-specific middleware, and finally hits the handler. After the handler finishes, the response is written to the client, and control flows back through the middleware stack in reverse order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31ce7b02-fa0d-4a38-b4da-284cbe9bcde3', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar''s dependency injection system differ from standard framework dependency injection?', N'Senior', N'Litestar utilizes a type-hint-driven dependency injection system that operates at the request lifecycle level. Unlike global containers, its dependencies are scoped to the route handler and can be resolved asynchronously, allowing for complex object graph construction without manual service locator patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f56f9de-0065-4ed9-914f-2850b8d4102a', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is a ''Connection Pool'' in Rocket?', N'Intern', N'A connection pool is a cache of database connections kept open so that they can be reused for future requests. Rocket applications often use managed state to hold these pools for efficient database access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'175c7ea7-8941-4af6-a457-2852daf1102d', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Can you perform JOIN operations in DynamoDB?', N'Fresher', N'No, DynamoDB does not support JOIN operations. Because it is a non-relational database, data is typically denormalized, meaning you store related data together in a single item or handle relationships at the application level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bba03db8-aff3-4223-8101-2856a9e5fb77', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS optimize memory usage when processing large file uploads?', N'Senior', N'AdonisJS uses stream-based file handling, which processes chunks of data rather than loading the entire file into memory. This approach prevents heap memory exhaustion and application crashes when dealing with concurrent large file uploads, ensuring consistent performance under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a42981eb-573f-4e17-bb0d-2856e8005ecb', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How do generators impact memory usage when processing large datasets?', N'Middle', N'Generators allow you to iterate over large data sets without loading the entire collection into memory at once. By using the ''yield'' keyword, the generator produces one value at a time on demand, which is highly efficient for memory-constrained environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68c2bfe3-156f-4201-b3d9-2858664f9843', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does the ''nothing'' sentinel value in Lit templates influence rendering?', N'Middle', N'The ''nothing'' sentinel is used to explicitly tell Lit to render nothing at a specific location in a template, which is useful for conditional logic. It is more efficient than rendering an empty string or null, as it helps the template engine manage DOM nodes more effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f271229d-655a-47ce-b6c3-2858f245eeda', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are the limitations of R''s single-threaded nature?', N'Middle', N'R''s core execution is single-threaded, meaning it cannot natively utilize multiple processor cores for standard operations without external packages. While this simplifies thread safety, it necessitates specialized parallel computing strategies for computationally intensive tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'265ba775-d55b-4271-8456-2860d72b1463', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are template literals and how are they used?', N'Intern', N'Template literals are a feature in JavaScript that allow for easier string interpolation and multi-line strings. They are enclosed by backticks ( ) instead of single or double quotes. You can embed expressions within template literals using ${expression}` syntax. Example: ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the concept of tagged templates Tagged templates in JavaScript allow you to parse template literals with a function. The function receives the literal strings and the values as arguments, enabling custom processing of the template. For example: ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f7e3c86-d450-4feb-bf64-28619f102c1b', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why is abstraction considered a trade-off in design?', N'Fresher', N'Abstraction simplifies complex systems by hiding details, making code easier to understand and manage. However, excessive abstraction can make it difficult for new developers to understand how the system works under the hood.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b2c56a2-f450-4ce7-a480-28631da4cc21', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the ''Strangler Fig'' pattern in the context of migrating from a monolith?', N'Middle', N'The Strangler Fig pattern involves gradually replacing parts of a monolithic application with new microservices. Over time, the new services ''strangle'' the old functionality until the monolith is fully replaced, reducing the risk compared to a complete system rewrite.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5be23617-8c8a-41d0-8ac2-28668431881f', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What are the security implications of exposing internal service ports to the public internet?', N'Middle', N'Exposing internal ports increases the attack surface, allowing attackers to probe for vulnerabilities in backend services that were not designed to face the public. It is best practice to keep internal services on private networks and route traffic through a secure gateway.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e88f270-bd83-45ce-a62b-2866c1eb2c40', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why is it important to consider the trade-off between logging granularity and storage costs?', N'Middle', N'High granularity logs are invaluable for debugging and security auditing but result in massive storage costs and potential performance bottlenecks in logging pipelines. A balanced approach involves tiered logging, where verbose logs are stored for short periods and summarized, structured logs are kept for long-term analysis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
