INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adc32ef6-bd8e-483a-9b4e-286a12883e66', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you ensure your system remains observable during an incident?', N'Middle', N'I implement comprehensive logging, metrics, and distributed tracing from the start. During an incident, I rely on dashboards to visualize trends and use trace IDs to correlate logs across services, allowing for rapid identification of the root cause.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1c109ef-fbf8-4d4e-8056-286ca481858b', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is an HTTP verb in the context of Rocket routes?', N'Intern', N'An HTTP verb, such as GET, POST, PUT, or DELETE, defines the type of action a client wants to perform on a resource. Rocket routes specify which verb they respond to to ensure proper RESTful design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b85586dc-5b54-4678-92b0-286e7f17b569', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'When should you NOT use Redis?', N'Junior', N'You should avoid using Redis when your data set is too large to fit in memory or when you need complex relational queries like joins. It is also not ideal for data that requires strictly transactional ACID compliance for large-scale, disk-based storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7975c64a-38bf-4fc9-92ad-2871fa4b4841', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is your approach to debugging an issue where a background job queue is consistently backing up?', N'Senior', N'I would evaluate the throughput of the producers versus the consumers and check for individual jobs that might be failing or taking significantly longer than expected. I would also analyze worker health to ensure that nodes are not dying or failing to process tasks due to resource starvation or connectivity issues with the queue provider.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd326ccde-929d-4ea6-a3f1-287249f35c48', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the ''async'' attribute differ from ''defer'' in terms of execution timing and document readiness?', N'Senior', N'Async scripts execute as soon as they are downloaded, which can occur at any point during HTML parsing and may block the parser if the download completes quickly. Defer ensures scripts only execute after the document is fully parsed, making it the safer choice for scripts that rely on the DOM structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93569729-e749-4e84-886a-287396338490', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of the @ConfigurationProperties annotation?', N'Middle', N'This annotation is used to map external configuration properties, such as those from application.properties, into strongly-typed Java objects. It is superior to @Value because it supports hierarchical data structures, validation, and provides better IDE support for autocompletion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fb723ce-4d96-4ff4-825d-287642640119', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is a cascading failure?', N'Middle', N'A cascading failure occurs when a fault in one part of a system causes subsequent failures in other interconnected components. It often happens when one service slows down, causing callers to wait longer and eventually exhaust their own resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0de39369-59f3-4a94-bb24-28791e1a8610', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are design patterns and why are they useful?', N'Senior', N'Design patterns are reusable solutions to common problems in software design. They provide a template for how to solve a problem that can be used in many different situations. They are useful because they help developers avoid common pitfalls, improve code readability, and make it easier to maintain and scale applications. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the concept of the Singleton pattern The Singleton pattern ensures that a class has only one instance and provides a global point of access to that instance. This is useful when exactly one object is needed to coordinate actions across the system. In JavaScript, this can be implemented using closures or ES6 classes. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9104cd33-2f68-4e3e-99b4-287999c6f11e', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is an Immutable collection?', N'Intern', N'An immutable collection is a data structure that cannot be modified after it is created. Instead of changing the collection, operations return a new collection containing the updated data, which helps prevent side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46bfd657-4d05-4794-86e2-287a4f749339', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain the role of ''Ractor'' in Ruby''s evolution toward true parallel execution.', N'Senior', N'Ractors are designed to provide thread-safe parallelism by isolating objects within separate execution contexts that do not share state. This overcomes the limitations of the GVL by allowing multiple Ractors to run concurrently on different cores, provided they communicate via message passing rather than shared memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6fa8752-c3f2-42af-991d-287afdd7f799', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the options in a cookie', N'Intern', N'There are few below options available for a cookie, 1. By default, the cookie is deleted when the browser is closed but you can change this behavior by setting expiry date (in UTC time). 2. By default, the cookie belongs to a current page. But you can tell the browser what path the cookie belongs to using a path parameter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4452b5e6-1663-4f47-9bd1-287affb5a864', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the value of rubber ducking in debugging?', N'Fresher', N'Rubber ducking involves explaining the problem to an inanimate object or a colleague. The process of articulating the logic step-by-step often helps you identify gaps in your own reasoning or notice details you previously overlooked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae81b451-ff26-4f4e-8788-287cd1b74d90', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the difference between a bug and a system outage?', N'Junior', N'A bug is typically a functional flaw that prevents a specific feature from working as expected for some or all users. An outage is a complete or significant loss of service that usually requires an emergency response to restore availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05bab822-b335-47e5-8afb-28801717b15f', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing an API, why is it important to use consistent status codes like 404 or 500?', N'Fresher', N'Consistent status codes provide clear, standardized feedback to the client about the outcome of a request. This allows the frontend application to handle errors gracefully and display appropriate messages to the user. Without standardized codes, debugging becomes difficult, and the client cannot distinguish between different types of failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c2c27c2-0d0e-4e9a-ad4d-28804c0ce0fb', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'In what scenarios is Alpine.js''s ''x-data'' scope isolation preferred over global state management patterns?', N'Senior', N'Scoped isolation is preferred when components need to remain portable, self-contained, and decoupled from the rest of the application. By encapsulating logic within ''x-data'', you prevent naming collisions and avoid the overhead of complex state orchestration tools. This is ideal for modular features like modals, dropdowns, or independent widgets where global state would be an unnecessary architectural burden.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e244664-0f71-4064-a116-288096bc7e4f', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of the ''mode'' configuration option?', N'Intern', N'The mode option tells Webpack to use its built-in optimizations corresponding to the environment. Setting it to development or production enables specific features like minification or debug-friendly source maps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c224ccfe-0bb6-408c-bb8f-2880ae08ed97', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between ''type widening'' and ''type narrowing''?', N'Senior', N'Type widening occurs when the compiler infers a broader type from a variable, such as assuming a string literal is a generic string. Type narrowing is the process of moving from a broad type to a more specific one through logical assertions or guards, allowing for safer property access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df9223bf-beb0-4d27-b269-28818ad88f82', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Is jQuery still used in modern web development?', N'Intern', N'While modern frameworks like React or Vue have replaced jQuery for complex applications, it is still widely used for smaller projects, legacy codebases, and quick, simple DOM manipulations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2da99101-7e60-4c9f-aa32-28821db3f85f', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are the performance trade-offs of using Express middleware compared to handling logic directly in a route handler?', N'Middle', N'Middleware allows for modularity and code reuse, enabling cross-cutting concerns like logging or authentication to be applied consistently across routes. However, excessive middleware depth can introduce overhead due to function call stacks and object creation for each request. For high-throughput systems, it is essential to balance this abstraction against the latency added by executing multiple layers for every incoming request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a518189-da8a-4f05-ad49-2884e199c47c', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the role of the server in a Qwik application?', N'Intern', N'The server in Qwik is responsible for rendering the initial HTML and serializing the application state into that HTML. It sends a fully functional, static-looking page that is ready to ''resume'' execution as soon as the client needs it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ebd7e95-be87-4317-a7fc-2884e85c2f50', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'In a distributed system, how would you leverage Rocket''s ''Catchers'' for global error handling?', N'Senior', N'Catchers allow for centralized handling of specific HTTP error codes across the entire application. By defining standard JSON error responses in catchers, you ensure consistent API contract compliance, which is critical for downstream services to interpret failures correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57fa33f9-507b-463e-8532-2887fb370d40', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte achieve two-way data binding?', N'Fresher', N'Svelte provides a simple directive that links a component variable directly to an HTML form element. When the user modifies the input, the component variable updates automatically, and vice-versa, keeping the state and UI perfectly synchronized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'499f9511-75d8-44c9-8359-288a3792d0b1', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the WHERE clause versus the HAVING clause?', N'Fresher', N'The WHERE clause is used to filter individual rows before any grouping occurs. The HAVING clause is used to filter groups created by the GROUP BY clause, typically after aggregate calculations have been performed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b97b72a-f525-4bf1-aa29-288f19dedb0c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the significance of the ''Content Security Policy'' (CSP) for frontend architecture?', N'Senior', N'CSP provides a layer of security by defining which resources can be loaded and executed by the browser. It mitigates XSS attacks by restricting sources for scripts and preventing the execution of inline code, which requires developers to adopt stricter coding standards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64f9d8da-3cde-45dd-b76b-288ff457d4e0', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain the difference between optimistic and pessimistic locking.', N'Middle', N'Pessimistic locking prevents data conflicts by locking a record as soon as it is accessed, ensuring no one else can modify it until the lock is released. Optimistic locking assumes conflicts are rare and only checks for version changes at the time of commit, which improves performance in high-concurrency environments by avoiding long-held locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56c9f89f-e054-46e2-a395-28948ef1ff59', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using an array and a linked list for a collection of data?', N'Fresher', N'I would choose an array if I need fast, random access to elements by index, as it provides constant time complexity for lookups. I would choose a linked list if the application requires frequent insertions or deletions, as these operations are more efficient since they don''t require shifting elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c60d09f9-f105-4aaf-94bb-289841f4ea0a', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the function of the Ember Service layer and when should you use it?', N'Middle', N'Services are long-lived singletons that persist for the duration of the application. They are designed for sharing state, managing global data like authentication tokens, or providing common functionality across unrelated parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5725118e-24fb-4449-bcff-28997254f3a1', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Does Axum support type safety for routes?', N'Intern', N'Yes, Axum leverages Rust''s strong type system to ensure that extractors and return types are checked at compile time. This reduces runtime errors by ensuring that the data being passed to handlers matches the expected structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45469f58-4cf6-434d-88fc-289ad019c9f6', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How do you pass an array to a function?', N'Fresher', N'When an array is passed to a function, it is treated as a pointer to its first element. The function receives the memory address of the array, allowing it to access and modify the original data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6afb6690-4d2d-4d3e-9514-289b14454c57', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How do you handle string interpolation in Scala?', N'Junior', N'Scala uses ''s'' or ''f'' prefixes before a string literal to allow for variable substitution directly within the string. This makes building dynamic strings much more readable compared to standard concatenation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8bed7f7-d700-489c-82ae-289bb355315f', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the difference between before_action and around_action in Rails controllers.', N'Middle', N'A before_action runs a method before the controller action is executed, commonly used for authentication or setting up variables. An around_action wraps the execution of the controller action, allowing code to run both before and after the action, which is useful for benchmarking or transaction management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'709c4dc5-062a-4945-b722-289c8c826d74', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When building a distributed system, how do you estimate the trade-off between consistency and latency under high load?', N'Senior', N'I analyze the system''s requirements using the CAP theorem and PACELC framework to identify where eventual consistency is acceptable. I estimate latency budgets by benchmarking critical path operations and calculating the overhead of coordination protocols like Paxos or Raft versus asynchronous replication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a18010bb-738c-4b66-b724-28a20e057b98', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Why is it often considered a best practice to avoid ''async void'' in C#?', N'Senior', N'Async void methods cannot be awaited, which prevents the caller from tracking completion or catching exceptions. Unhandled exceptions in async void methods crash the process immediately, as they cannot be captured by the typical task-based exception propagation mechanism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eae3fbe7-5422-4e81-846b-28a34b4fd8d7', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How do you handle ''barrel files'' in Vite to avoid performance degradation?', N'Senior', N'Barrel files can cause Vite to process more modules than necessary, impacting HMR speed. To mitigate this, developers should ensure that barrel files do not unintentionally import large dependency trees or use tree-shaking-friendly import patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
