INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1808b3e-6700-4323-85b1-28a7e7b050a6', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How does Event Sourcing differ from traditional state-based persistence?', N'Middle', N'Instead of storing the current state of an object, Event Sourcing stores all changes as a sequence of immutable events. The current state is derived by replaying these events, which provides a perfect audit log and the ability to reconstruct state at any point in time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
