INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'104156bb-b04b-45c3-b6c4-28ad532133dc', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle request validation for large file uploads efficiently?', N'Senior', N'AdonisJS uses a streaming approach to handle file uploads, allowing the server to process chunks of data rather than loading the entire file into RAM. This is critical for preventing memory exhaustion during high-concurrency file transfers, as it keeps the memory footprint low regardless of the upload size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd8a7dc3-8fd6-40eb-b960-28afcab7b75f', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle data reactivity compared to standard vanilla JavaScript?', N'Junior', N'Alpine.js uses a proxy-based reactivity system that automatically tracks state changes within its defined scopes. When a piece of data bound to an element is updated, Alpine observes the change and immediately re-renders the specific parts of the DOM that depend on that data, whereas vanilla JavaScript would require manual DOM manipulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'090078f6-d73c-426c-8d72-28b05b322a02', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the significance of the dependency array in ''useEffect''?', N'Senior', N'The dependency array tells React when to re-run the effect based on changes to specified variables. Omitting it causes the effect to run on every render, while providing an empty array restricts it to mount/unmount, which is crucial for managing external side effects and performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d90c71c-fc5a-4d26-bec7-28b16ed527b5', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What are the trade-offs of putting logic directly in HTML attributes versus external JavaScript files?', N'Middle', N'Inlining logic provides immediate context and rapid development for simple interactions, but it can lead to maintenance challenges and poor readability as complexity grows. Moving logic to external Alpine plugins or files improves testability and separates concerns, though it requires more setup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45ba2a4f-56bd-4ddc-b469-28b1b75f8478', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is meant by ''pass-by-value'' versus ''pass-by-reference''?', N'Junior', N'Pass-by-value creates a copy of the argument, meaning changes inside the function do not affect the original variable. Pass-by-reference passes the memory address of the argument, allowing the function to modify the original object directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd91b026d-03f1-4266-a304-28b20f23dcec', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Explain the role of the ''inert'' attribute in complex UI component state management.', N'Senior', N'The inert attribute allows developers to mark DOM subtrees as non-interactive, effectively removing them from the tab order and preventing focus-based events. This is highly efficient for managing modal dialogs or off-screen navigation, as it eliminates the need for complex manual event listener cleanup or focus trapping.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41e347b3-aed1-4c42-8f17-28b324663352', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the role of the ''rocket::get'' macro in a Rocket application, and how does it relate to HTTP methods?', N'Junior', N'The ''rocket::get'' macro is a procedural attribute used to define a route handler that specifically responds to HTTP GET requests. By annotating a function with this macro, you tell the Rocket router that the function should only be invoked when a client performs a read operation at the specified path. It simplifies routing by mapping HTTP verbs directly to Rust functions, ensuring the application follows standard RESTful conventions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2ad0fde-0e43-4b02-9681-28b72bea9788', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery handle AJAX requests?', N'Junior', N'jQuery provides a simple and consistent interface for making asynchronous HTTP requests through the $.ajax() method. It abstracts the complex XMLHttpRequest object, allowing developers to easily send data to and receive data from a server without refreshing the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d03786e-e7a3-43be-b81a-28bbc129b8c0', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the performance implications of deep interface merging and declaration merging in large TypeScript projects.', N'Senior', N'Excessive declaration merging can lead to increased memory consumption and slower type-checking as the compiler must continually re-evaluate and aggregate global scopes. Architects should favor composition over merging to maintain predictable type resolution paths and avoid performance bottlenecks in the compiler''s symbol resolution phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
