INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b91676b-86a8-4e1a-a85e-28c4fc5bad7b', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Describe the difference between microtasks and events in the event loop.', N'Senior', N'Microtasks are intended for short, high-priority tasks that must be finished before the next event loop iteration, such as completing a Future. Events are meant for longer-running tasks or I/O, and the event loop only processes one event at a time, ensuring that microtasks act as a high-priority buffer to minimize latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
