INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f20c659-b21e-49c6-b22a-28e99a30676e', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What role does the ''fastify-static'' plugin play in a high-performance content delivery strategy?', N'Senior', N'It serves static assets with optimized buffer handling and cache headers, preventing the main application logic from being interrupted by file I/O. However, for extreme scale, this should still be offloaded to a dedicated CDN or Nginx reverse proxy to free up Node.js resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8226fef6-4618-4d15-a1a9-28ed2375712b', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Why is it important to use ''c.NoContent'' instead of writing a manual 204 response?', N'Middle', N'Using Echo''s helper method ensures that response headers are correctly set, the body is properly closed, and the response lifecycle is handled in line with framework expectations. It prevents common mistakes like accidentally sending a body with a 204 status or failing to set proper content lengths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a84b791d-9ec5-41b5-b26b-28f15cad025f', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are the architectural benefits of using a Dependency Injection (DI) container in PHP?', N'Middle', N'A DI container centralizes the management of object creation and dependencies, promoting loose coupling and easier unit testing. It allows developers to swap implementations of services without modifying the classes that consume them, making the application more modular and extensible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b924f08e-e2af-43ab-81e9-28f2eb982f78', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are environment variables and why are they used in Express?', N'Intern', N'Environment variables are key-value pairs stored outside the application code. They are used in Express to manage configuration settings like database credentials, API keys, or port numbers, keeping sensitive information out of the source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'447b5571-54f4-4f7e-9686-28f6147511c6', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express''s single-threaded event loop model handle I/O-bound vs CPU-bound tasks, and what is the consequence of blocking?', N'Senior', N'Express executes all code on a single thread, meaning CPU-intensive tasks will block the event loop and prevent it from processing new I/O events. This causes the entire application to hang, leading to increased response times for all concurrent users, whereas I/O-bound tasks are offloaded to the libuv thread pool.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a544c7a4-4c9b-41c4-af56-28f628221294', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the purpose of the Redis ''Client Output Buffer'' limit, and how can its misconfiguration cause issues?', N'Senior', N'The client output buffer limit manages the amount of memory consumed by queued responses for connected clients. If the limit is too low, Redis will disconnect clients that are slow to consume data; if too high, it can lead to OOM (Out of Memory) conditions during traffic spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03578aa2-da5c-444e-b665-28fadf0a4d7b', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the purpose of a primary key in DynamoDB?', N'Fresher', N'A primary key uniquely identifies each item in a table so that no two items can have the same key. It consists of either a partition key alone or a combination of a partition key and a sort key, which determines how data is organized and retrieved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
