INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd077cc96-a7b9-4614-bb29-290afe9d1031', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the common storage engines in MySQL?', N'Junior', N'InnoDB and MyISAM are the two most common engines. InnoDB is the default, supporting transactions, row-level locking, and foreign keys, while MyISAM is an older engine that does not support transactions and uses table-level locking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c396d7e0-5ac5-4fc3-aba6-290dd4480c8a', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is Concurrent Rendering?', N'Fresher', N'The Concurrent rendering makes React apps to be more responsive by rendering component trees without blocking the main UI thread. It allows React to interrupt a long-running render to handle a high-priority event. i.e, When you enabled concurrent Mode, React will keep an eye on other tasks that need to be done, and if there''s something with a higher priority it will pause what it is currently rendering and let the other task finish first. You can enable this in two ways,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c56ceaa5-452d-414e-bcd2-290e297b916f', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are the architectural risks of using ''Observers'' in modern Ember?', N'Senior', N'Observers can create unpredictable side effects because they execute in response to property changes without a clear order or scope. They are often difficult to test, can cause infinite loops, and frequently lead to inconsistent state, which is why they are strongly discouraged in favor of tracked properties or life-cycle modifiers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
