INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70241e10-b9ff-4d0c-a1da-2912528d2a5a', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the role of the mongos process in a sharded cluster?', N'Middle', N'The mongos process acts as a query router, sitting between the client application and the sharded cluster. It determines which shards contain the necessary data and routes the request to the appropriate nodes, masking the complexity of the sharded environment from the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
