INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f426578-9feb-4afc-9d0b-2919ccf773e8', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does MySQL''s Adaptive Hash Index (AHI) work, and when is it disadvantageous?', N'Senior', N'InnoDB automatically builds hash indexes on frequently accessed index pages to speed up lookups. It is disadvantageous in workloads with high concurrency or range scans, as the management overhead of the hash index can lead to lock contention and CPU bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b469d3e5-dfea-4989-9207-2919ce417c21', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket manage asynchronous execution compared to standard synchronous frameworks?', N'Senior', N'Rocket is built on top of the Tokio runtime, allowing handlers to be defined as asynchronous functions. This enables non-blocking I/O operations, which significantly improves concurrency and scalability for high-throughput applications by allowing the server to handle multiple requests on a limited set of threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a1d14ac-8503-4a5c-ab99-291a676333d5', N'4c000000-0000-0000-0000-000000000005', N'What is the advantage of using a load balancer?', N'Middle', N'Load balancers distribute incoming network traffic across multiple servers to ensure no single server becomes a bottleneck. They improve reliability by performing health checks and routing traffic away from failed instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b63d7db1-1424-49ce-b10e-291c131e2e01', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI manage the lifecycle of an application, and why is it important?', N'Middle', N'FastAPI provides lifespan events that allow developers to execute code before the server starts and after it shuts down. This is crucial for managing resource-intensive tasks like establishing database connection pools or cleaning up background connections upon graceful shutdown.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1291b1e7-a614-48f3-a3ba-291e86de68c2', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How do you perform dependency injection in Axum?', N'Middle', N'Dependency injection is primarily achieved through the ''State'' extractor. By wrapping your services or repositories in an Arc and passing them into the application state, they become accessible to any handler that requests them via the state extractor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c65600d9-121e-40d4-b5c7-291f3da616fc', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you determine the appropriate level of abstraction for a shared library used across microservices?', N'Senior', N'Keep abstractions thin to avoid tight coupling that forces all services to upgrade simultaneously. Prioritize library stability and favor sidecar patterns or standalone services if the functionality requires frequent updates or language independence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f224d0f1-fb3a-4a5f-8531-2920e7b1f115', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How does the trade-off between simplicity and flexibility manifest in software architecture?', N'Intern', N'Simple systems are easier to build, test, and maintain, but they may struggle to adapt to changing business requirements. Flexible, highly-configurable systems accommodate change well but are significantly harder to design and understand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06aeac7a-5400-4011-8acd-2922a9e0e5af', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Can you use standard React hooks in Next.js?', N'Intern', N'Yes, you can use standard React hooks like useState and useEffect in Next.js, but they must be used within Client Components. Server Components have limitations and cannot use hooks that rely on browser-specific APIs or state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b08bab03-10b1-4f57-922d-29230ed3f8ff', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How can you handle global exceptions in FastAPI?', N'Junior', N'You can use the ''@app.exception_handler'' decorator to define custom functions that catch specific exceptions globally. This allows you to standardize error responses across your entire application instead of handling errors individually in every route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63c027b9-123c-47ec-9b5e-29249cec8d0a', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of an ''upsert'' operation in database design?', N'Middle', N'An upsert is a combination of ''update'' and ''insert'' that attempts to update an existing record based on a unique key, and if the record does not exist, inserts a new one. It is commonly used to simplify data synchronization processes and prevent duplicate constraint violations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02739dc5-1767-4ed2-a5c0-2925aebaf4cd', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the significance of the ''useVisibleTask'' hook?', N'Middle', N'The ''useVisibleTask'' hook is used to run code immediately when a component becomes visible in the viewport. It is primarily used for tasks that require client-side access, such as setting up third-party libraries or observing elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'224af7fc-61c9-4b7b-a6db-29290e951a2c', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the benefit of using Data Transfer Objects (DTOs)?', N'Fresher', N'DTOs are used to transfer data between processes, effectively separating the database model from the structure exposed to the client. This prevents leaking internal database details and allows for the shaping of data specifically for the consumer''s needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
