INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f44c15e0-17de-4ad0-b04a-292b301b3380', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When faced with a technical problem where you have two conflicting theories about why a system is failing, how would you determine which one to investigate first?', N'Intern', N'I would evaluate both theories based on the likelihood of occurrence and the relative ease of testing each one. I would prioritize testing the theory that is easiest to verify or disprove, as this provides quick information that helps narrow down the scope of the problem without wasting excessive time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'019fd34b-0a4b-4d88-accc-292eb2b10eb9', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web achieve its ''zero-cost'' abstraction claim?', N'Middle', N'Actix-web uses Rust''s type system and procedural macros to generate code at compile time. This allows for features like type-safe routing and dependency injection without the runtime overhead typically associated with reflection or dynamic dispatch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65ab29f3-6afc-4be7-b6d0-29301ba6cb9e', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the purpose of the x-text directive?', N'Intern', N'The x-text directive is used to set the text content of an element to the result of a JavaScript expression. It is a safer alternative to innerHTML as it treats the content as plain text, preventing potential security issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'920dce73-28e5-4792-8961-293164e8a671', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Can you define custom status codes in Litestar?', N'Fresher', N'Yes, Litestar allows you to set custom HTTP status codes for any response. You can return a status code explicitly from a route handler to indicate the outcome of the operation, such as 201 for resource creation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3718fa9b-67a7-4ff7-9f38-2933cc786fa3', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle redirects on the server?', N'Middle', N'Redirects are handled by throwing a redirect object within a load function or form action, which SvelteKit intercepts to send the appropriate HTTP status code. This ensures that the browser handles the navigation correctly before the page even finishes rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bab22aa-a75c-4987-a9e2-293531c8bc91', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the role of ''external pointers'' in R''s memory management?', N'Senior', N'External pointers allow R to wrap C/C++ memory addresses, effectively moving the responsibility of memory allocation outside the R garbage collector. This is crucial for interfacing with high-performance C libraries, as it allows the external code to manage the object''s lifecycle without R attempting to track or free the underlying data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ad7fc3e-005c-49c5-9f97-2936eb7784dc', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between a shallow copy and a deep copy in the context of C structs?', N'Middle', N'A shallow copy duplicates the values of the struct members as they are, meaning pointer members in both structs will point to the same memory address. A deep copy involves allocating new memory for the contents pointed to by the pointers and copying the data itself, ensuring that modifications to one do not affect the other.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72470db4-a907-429b-9f38-2937cecf73d6', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the ''c.req'' object in Hono?', N'Intern', N'The c.req object is a wrapper around the incoming HTTP request. It provides easy access to URL parameters, query strings, headers, and the request body, abstracting away some of the complexity of the native Fetch API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f1d511d-6f3a-45e7-a10f-293941c5c78d', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut''s test framework leverage its AOT nature?', N'Senior', N'The test framework uses the same dependency injection and context management as the production runtime, ensuring that tests run against a realistic environment. By reusing the compile-time generated beans, it provides high confidence that the behavior in tests will match the behavior in production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58f2e702-52c3-4ab3-9d23-2939facaa66f', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How do you handle dependency injection in a Hono application?', N'Middle', N'Dependency injection is typically managed by attaching services to the Hono context or by using closure-based scoping. Since Hono is minimalist, it does not force a specific DI pattern, allowing developers to choose lightweight patterns that fit the small-scale nature of edge functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42b1acbb-5518-49ec-93f4-293b66f75d20', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How do C# ''ref structs'' differ from standard structs in memory management?', N'Senior', N'Ref structs are restricted to the stack to prevent them from being captured by closures or stored in heap-allocated fields. This constraint ensures memory safety for pointers or handles that point to stack-allocated memory, preventing dangling references.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17ec4327-779e-4968-8eb8-293d80d0e4dd', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the difference between a relational and non-relational database?', N'Intern', N'Relational databases store data in structured tables with predefined schemas and use SQL for querying. Non-relational, or NoSQL, databases use flexible formats like documents, key-value pairs, or graphs, allowing for more dynamic data storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23797782-4ca5-40ce-8988-29453a719f2d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a higher order function?', N'Intern', N'A Higher-Order function is a function that receives a function as an argument or returns the function as output. For example, Array.prototype.map(), Array.prototype.filter() , Array.prototype.forEach() and Array.prototype.reduce() are some of the Higher-Order functions in javascript. Example 01: .map() Example 02: .filter() Example 03: .forEach() Example 04: .reduce() &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b66dd25-2b70-4958-9132-29463cf08a1b', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the concept of database normalization.', N'Fresher', N'Normalization is the process of organizing data in a database to reduce redundancy and improve data integrity. It involves dividing large tables into smaller, related tables and defining relationships between them to ensure data is stored logically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcb5fd4e-a8f0-4fc7-9310-294836379c15', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What does the ''php artisan optimize'' command do and when is it used?', N'Middle', N'This command caches configuration, routes, and services into single files to improve application performance. It should be used primarily in production environments as part of the deployment process to reduce the overhead of reading individual files on every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f2b2fc5-40ac-4652-93ba-2948c10480a6', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What does ''move'' semantics mean in Rust?', N'Junior', N'Move semantics occur when ownership of a value is transferred from one variable to another. After a move, the original variable is no longer valid, which prevents double-free errors and ensures memory safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e31aff9-1c8c-4189-8e21-294c1243f3c1', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does the ''PhantomData'' marker assist in type-level design?', N'Senior', N'''PhantomData'' tells the compiler that a struct conceptually owns data of a certain type, even if it does not contain a field of that type. This is essential for managing drop semantics and lifetime variance in structs that interact with raw pointers or foreign memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ec8dac6-4bb7-4108-a44b-294d367a52a6', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'When should you use the ''nested'' data type?', N'Middle', N'The nested type should be used when you need to store arrays of objects and query them independently without losing the relationship between their fields. Standard object arrays in Elasticsearch are flattened, which causes cross-object matching issues that nesting solves.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd88ac0b0-10dc-4232-a33e-294da21be907', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the primary role of Express in a Node.js backend application?', N'Junior', N'Express is a minimal and flexible web application framework that provides a robust set of features for building web and mobile applications. It simplifies the process of handling HTTP requests, routing, and managing middleware, which are more complex when using only the native Node.js http module.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29158571-57b2-4a43-ac96-294e24613099', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why does Rocket emphasize compile-time checks?', N'Intern', N'By performing checks during compilation, Rocket catches errors before the code is ever executed. This reduces the likelihood of runtime bugs, such as type mismatches or missing routes, leading to more stable applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'917591f3-536f-4173-8c76-295373be7c30', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What are the advantages of using Vite''s glob import feature?', N'Middle', N'Glob imports allow developers to import multiple files at once using patterns. This is useful for dynamic scenarios like registering routes or loading components based on a directory structure, without manually maintaining large import lists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f556b70-039d-41cd-8414-295508ba4d98', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is a package in Java?', N'Intern', N'A package is a grouping of related classes and interfaces. It helps organize code into a hierarchical structure, which prevents naming conflicts and makes projects easier to manage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6388d3d8-56a5-4fdd-a2c9-29554ca1506b', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the GAC?', N'Junior', N'The Global Assembly Cache (GAC) is a machine-wide repository where shared assemblies can be stored. It allows multiple applications to use the same version of a library, reducing disk usage and avoiding dependency conflicts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad17b34d-5603-4e33-a713-2958a32b57d1', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the role of the ''view'' engine in AdonisJS?', N'Junior', N'The view engine is used to render server-side templates, converting data from the backend into HTML. While many modern AdonisJS apps use the framework as an API, the view engine remains a tool for building traditional server-rendered websites.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'203051c1-1a41-495b-a814-2959b66db15c', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is an API Controller and how does it differ from a standard MVC controller?', N'Fresher', N'An API controller is marked with the ApiController attribute, which enables features like automatic model validation and requirement for attribute routing. Unlike MVC controllers, it is optimized for returning data in formats like JSON rather than rendering HTML views.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2da8153-55b6-40ce-80fa-295cffe56eaf', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Explain the strategy for managing API pagination across large datasets.', N'Senior', N'Offset-based pagination is simple but suffers from performance degradation and consistency issues on large datasets. Cursor-based pagination is preferred for large-scale systems because it provides stable navigation and efficient query performance by using an opaque pointer to the last retrieved item.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c99a7c7-ea6a-43b0-8223-295e1c0b8542', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why is Vite''s use of ''native ESM'' considered a paradigm shift in frontend tooling?', N'Senior', N'By delegating the module resolution to the browser, Vite effectively moves the complexity of the module graph from the build tool to the browser''s native engine. This shift removes the need for expensive bundling during development, which was the primary bottleneck for productivity in earlier generations of JavaScript build tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b6ef949-b6f3-461c-884a-295e61a84d69', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using a monolithic deployment pipeline versus per-service pipelines?', N'Senior', N'A monolithic pipeline is easier to coordinate for integrated testing but becomes a bottleneck as team size increases. Per-service pipelines enable independent deployment cycles and faster iteration, requiring more mature infrastructure and automated testing to ensure cross-service compatibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a2055d7-4d72-4211-a3ce-295ee73f1c0c', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Why is FastAPI considered a ''developer productivity'' framework despite being highly performant?', N'Senior', N'FastAPI combines high performance with modern features like auto-generated documentation, type-hint based validation, and intuitive dependency injection. These features reduce the cognitive load on developers and decrease the time spent on repetitive tasks like writing boilerplate serialization and documentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
