INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bfe8f08-e131-4284-bab2-296dd5ac5e07', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Why is data locality important for performance in a distributed database?', N'Senior', N'Data locality minimizes network round-trip time by ensuring that data is processed close to where it is stored or cached. Reducing cross-region or cross-rack data movement significantly decreases latency and improves the overall responsiveness of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b2b0d25-9935-41c2-8106-2971b2654e4f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why is it often recommended to use functional programming patterns in JavaScript?', N'Middle', N'Functional programming patterns like immutability and pure functions make code easier to test, debug, and reason about by eliminating hidden side effects. These patterns align well with modern framework state management, where predictability and consistent state updates are critical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
