INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14891d28-0725-441d-9730-297509ecb2df', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is buffer overflow a significant security risk?', N'Junior', N'A buffer overflow occurs when data written to a buffer exceeds its allocated capacity, overwriting adjacent memory. This can be exploited by attackers to inject malicious code or overwrite return addresses to hijack program control. It is a common source of vulnerabilities that can be mitigated by careful boundary checking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'713f9fb3-76d6-4192-8c3c-297818ab7ac1', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a Covering Index and how does it improve query performance?', N'Middle', N'A covering index includes extra columns in the index structure beyond those used for searching. This allows the database to retrieve all required data directly from the index without having to perform a ''heap fetch'' to access the actual table rows, significantly reducing I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40ac1300-fcdf-45e6-abc5-2978d5e39ef1', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is a reference in Rust?', N'Intern', N'A reference is a way to access data without taking ownership of it. This process is known as borrowing, which allows multiple parts of code to read data without needing to create copies or transfer the owner.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
