INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33f001d9-5a68-4cdb-a588-297a52ecf808', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why is it important to minimize the size of ''unsafe'' blocks?', N'Middle', N'The larger an unsafe block is, the harder it becomes to audit for memory safety violations. Keeping these blocks small and well-documented allows developers to isolate potentially risky code and simplify the process of ensuring the overall safety of the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'655efe32-a84d-4578-a2c7-297af2620339', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the purpose of the ''onDestroy'' lifecycle hook?', N'Fresher', N'The onDestroy hook runs when a component is removed from the DOM. It is primarily used for cleanup tasks, such as clearing intervals, removing event listeners, or cancelling pending network requests to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'414280cc-ffbc-4c8f-b6ac-297cf400be46', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of AdonisJS Validators?', N'Intern', N'Validators are used to ensure that the data sent by a client meets specific criteria before it is processed by the application. They help prevent invalid or malicious data from reaching the database or business logic layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f5eed5a-968c-41e2-aa42-297f83f28ae9', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do you optimize a React application for performance?', N'Middle', N'Optimization strategies include code splitting, memoizing components and calculations, minimizing unnecessary re-renders, using lazy loading for assets, and implementing virtual lists for large datasets. Profiling with React DevTools is essential to identify and address specific bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab441a07-5e9c-4714-a0f7-297fdcb89a65', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Explain the performance implications of Fastify''s schema-based serialization and how it relates to the underlying JSON handling compared to standard JSON.stringify.', N'Senior', N'Fastify leverages the ''fast-json-stringify'' library, which generates optimized serialization functions based on provided JSON schemas. By pre-compiling these functions, Fastify avoids the overhead of runtime reflection and dynamic type checking, resulting in significantly faster serialization throughput compared to the generic and slower native JSON.stringify.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f4334ba-c595-4c79-875c-2981bc807c83', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the ''Doublewrite Buffer'' protect data integrity in InnoDB?', N'Middle', N'The doublewrite buffer is a storage area where InnoDB writes pages before writing them to the actual data files. If a system crashes during a page write, InnoDB can restore the page from the doublewrite buffer, ensuring that the data is not corrupted due to partial writes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af68c888-29c2-48cb-80ba-29829ddbca66', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the difference between S3 and S4 object systems in R?', N'Middle', N'S3 is a informal, class-based system that uses generic functions and method dispatch based on class attributes, making it flexible but prone to errors. S4 is a formal system requiring explicit class definitions and method signatures, offering stricter structure and multiple dispatch at the cost of increased complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ed31ca3-feb6-4e98-a3ff-2986b5c105d0', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Why is multi-master replication often discouraged for write-heavy workloads despite its apparent availability benefits?', N'Senior', N'Multi-master replication introduces significant conflict resolution complexity because concurrent writes to the same record in different nodes can lead to data divergence. Detecting and resolving these conflicts often requires complex application logic or costly consensus algorithms, which can negate performance gains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00a8b6ad-be96-4d7f-b3ab-2987dd57bfe2', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the ggplot2 library?', N'Intern', N'ggplot2 is a widely used R package for data visualization based on the grammar of graphics. It allows users to build complex, multi-layered plots by mapping data variables to visual aesthetics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab2b3a01-cccb-42a1-b92c-2989b8632cb0', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the difference between ''res.send'' and ''res.json''?', N'Intern', N'res.send can send different types of data, such as a buffer, a string, or an object, and sets headers accordingly. res.json specifically sends a JSON response and ensures the Content-Type header is set to application/json.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4fa5dc8-c9ab-4124-9065-298a7c42cc9c', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a database trigger?', N'Junior', N'A trigger is a set of SQL statements that automatically executes or fires when a specific event occurs, such as an INSERT, UPDATE, or DELETE on a table. It is often used for auditing changes or enforcing complex business rules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebad78ed-6cf1-417a-a4f3-298c3be17739', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How do ''Indexes'' in Cassandra differ from those in RDBMS, and what are the limitations of Secondary Indexes?', N'Senior', N'Secondary Indexes in Cassandra are local to each node and require a scatter-gather approach for queries, which is inefficient for large datasets. Unlike global RDBMS indexes, they can cause significant performance degradation when filtering on low-cardinality columns, leading architects to prefer denormalized tables instead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a65e18a4-3ac1-4de8-8f26-298c4d2e1b83', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What does it mean for a function to be first-class?', N'Junior', N'In Go, functions are first-class citizens, meaning they can be assigned to variables, passed as arguments to other functions, and returned as values from functions. This enables functional programming patterns like closures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'569f238a-8855-415f-a21e-298f0a4652b4', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala support functional programming?', N'Fresher', N'Scala supports functional programming by treating functions as first-class citizens, allowing them to be passed as arguments or returned as values. It also emphasizes immutability, pure functions, and higher-order functions to manage state changes effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bbe6034-43d8-4c31-82f9-298f0fcabeb5', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the role of the Master Node?', N'Intern', N'The Master Node is responsible for cluster-wide management tasks, such as creating or deleting indices and tracking which nodes are part of the cluster. It ensures the health and stability of the cluster by managing shard allocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9809a97d-095e-48f6-bf4d-298f4c28f31f', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle a sudden, massive surge in traffic for a service that is currently at its capacity limits?', N'Senior', N'I would prioritize core system functionality through load shedding, dropping non-critical traffic like analytics or background jobs. Simultaneously, I would trigger auto-scaling policies to provision more resources while ensuring that existing load balancers and database connection pools are not overwhelmed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0c79b12-09c7-4b22-afd0-298fb22e4b08', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'When is it appropriate to use a multi-master database setup?', N'Senior', N'Multi-master setups are ideal for globally distributed systems where users need low-latency read and write access to the same dataset from different geographic locations. However, they require sophisticated conflict detection and resolution logic, such as Last-Write-Wins or CRDTs, to manage concurrent updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4e86e50-38ef-4fb6-a11c-299240eb9ec5', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the purpose of the ''v-if'' directive compared to ''v-show'' in Vue?', N'Junior', N'The v-if directive performs conditional rendering by completely removing or inserting elements from the DOM based on a boolean value. In contrast, v-show keeps the element in the DOM but toggles its visibility using the CSS display property. v-if has higher toggle costs, while v-show has higher initial render costs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52471525-10ac-4fb6-9033-29941269c91c', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why is security important in PHP development?', N'Intern', N'Because PHP interacts directly with the server and databases, improper coding can lead to vulnerabilities like SQL injection or cross-site scripting. Developers must sanitize user input and validate data to ensure the application remains secure from unauthorized access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5f0ee0c-b56b-4b95-8791-2994dae15352', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB achieve horizontal scalability while maintaining predictable performance?', N'Senior', N'DynamoDB uses a partition-based architecture where data is distributed across multiple storage nodes based on a partition key. By hashing the partition key, the system ensures uniform data distribution, and as the table grows or traffic increases, DynamoDB automatically splits partitions to accommodate the load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af2f243e-40a9-4582-a323-29991ea1d30e', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the significance of the ''val'' keyword?', N'Intern', N'The val keyword is used to declare an immutable variable. Once a value is assigned to a val, it cannot be changed, which is a core concept in functional programming for maintaining state safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58fa6a20-dbe3-4f95-9fcd-29997ebc2ce0', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is meant by ''reactive scopes'' in SolidJS?', N'Intern', N'Reactive scopes define the context in which signals are tracked. When a component initializes, it creates a scope that tracks all signals used within it, ensuring updates are scoped correctly to that component''s lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'940d2da6-baaf-4dd9-8d04-299a6d9e257b', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the difference between dynamic and static rendering?', N'Junior', N'Static rendering means the HTML is generated at build time, while dynamic rendering generates the HTML at request time. Dynamic rendering is necessary when the page content depends on cookies, request headers, or frequently changing data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'897f7a22-247f-4b6c-aa5b-299a95bad3de', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are Ember Models?', N'Intern', N'Ember Models represent the data structures within an application. They define the shape of the data and are typically used in conjunction with Ember Data to communicate with a backend API, allowing the app to fetch, update, and manage persistent data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eaaf8f45-491e-4c9d-ada7-299c77d801c7', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the difference between ''effective'' and ''efficient'' in problem solving?', N'Intern', N'An effective solution accomplishes the goal and meets the requirements, while an efficient solution does so with the minimum amount of time and resources. Ideally, a solution should be both effective and efficient. However, efficacy is always the priority before optimizing for efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f569102-daaf-492f-a916-299fc3f17258', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the significance of the ''Micronaut Launch'' tool?', N'Middle', N'Micronaut Launch is an online service that enables developers to bootstrap projects with specific features and dependencies pre-configured. It simplifies the setup process and ensures that all selected components are compatible and correctly versioned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24f0ae48-0c55-4c9a-ada0-29a0535c87e2', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Why is it generally better to animate ''transform'' instead of ''top'' or ''left''?', N'Senior', N'Transform properties are handled by the compositor thread, meaning they can be animated without triggering a relayout or repaint of the page. Animating top or left forces the browser to recalculate the layout on every frame, which is significantly more expensive and often results in dropped frames.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19b5b920-9b81-4287-908b-29a1d90711df', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the ''dark mode'' feature in Tailwind CSS?', N'Fresher', N'Dark mode allows you to easily style your application for dark themes by using the dark: modifier. When enabled, Tailwind applies specific styles only when the user''s system preference is set to dark mode or when a specific class is added to a parent element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c343b4e8-a451-4f19-af2c-29a24f5a78b0', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Is jQuery still useful for internal tools or legacy system maintenance?', N'Middle', N'Yes, jQuery remains highly effective for rapid prototyping or maintaining older enterprise systems where rewriting the entire frontend is not feasible. Its vast plugin ecosystem and ease of integration make it a low-friction choice for projects that do not require complex state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e803b35c-51a5-4f2b-a7dd-29a2e9b8d40d', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is a server-side language?', N'Intern', N'A server-side language is a programming language that runs on the web server rather than the user''s browser. This allows the server to process data, access databases, and perform security checks before sending the final page to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8becb03-3482-41c2-9ee9-29a575508285', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How does the Saga pattern manage data consistency in microservices?', N'Middle', N'The Saga pattern manages distributed transactions by breaking them into a series of local transactions with corresponding compensating actions. If one step fails, the saga executes the compensating transactions to undo the changes made by previous steps, maintaining data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40506d14-c20e-4a36-8b69-29a7038de680', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does the Snitch determine network topology awareness?', N'Senior', N'A Snitch maps nodes to data centers and racks, allowing Cassandra to be topology-aware. This information is used to place replicas intelligently across different racks or regions, ensuring that the system can survive entire rack or data center failures without losing data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11207e07-2f3e-423f-9a08-29a83e9b40f9', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Why is consumer group rebalancing in distributed brokers potentially disruptive to system performance?', N'Senior', N'Rebalancing occurs when a consumer joins or leaves a group, forcing the broker to redistribute partition ownership across available consumers. During this period, processing for those partitions is usually paused, which can lead to latency spikes and potentially cause temporary duplicate processing if offsets were not committed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9cad2bf-8b9f-43bc-a28b-29aa892b2b36', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the primary role of a ''partition key'' in a NoSQL database?', N'Intern', N'A partition key is used to determine how data is distributed across a cluster of servers. It helps the database engine route read and write requests to the correct node where the specific data resides.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'082d5e4d-d31f-407e-a7a2-29ab9aca8e00', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the role of a partition key?', N'Intern', N'A partition key determines how data is distributed across different nodes in a cluster. It helps the database locate where a specific piece of information is stored, ensuring efficient data retrieval.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51e52109-0d38-418d-939b-29ac4f9df490', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How are types handled in Go?', N'Intern', N'Go is a statically typed language, meaning the type of every variable is known at compile time. However, it also features type inference, which allows the compiler to determine the type based on the assigned value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ac88c6e-b461-4392-9e45-29aeab218fc2', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is data validation in the context of Echo?', N'Fresher', N'Data validation ensures that the input received from a request meets specific criteria before being processed. While Echo provides binding, developers typically use third-party packages or internal logic within the handler to validate that the bound data is correct and safe.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca5b4828-0586-41d4-a0c0-29b1f555f988', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you ensure your work is maintainable for other developers?', N'Fresher', N'I write clear, descriptive labels for components and include comments that explain the ''why'' behind complex logic. I also follow standard conventions to make the system intuitive for anyone else working on it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58085a9c-6d6b-4b35-a3b4-29b2bfcf652b', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Discuss the maintenance burden of ''spaghetti code'' inherent in large-scale jQuery applications.', N'Senior', N'Large jQuery apps often lack a formal architectural pattern, leading to tight coupling between business logic and DOM manipulation. This makes unit testing extremely difficult, as most tests require a full browser environment to verify even the simplest state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adbc59f1-5c2a-450d-8905-29b856692403', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is database sharding and when should it be considered?', N'Middle', N'Sharding is the process of splitting a large dataset into smaller chunks, known as shards, and distributing them across multiple database servers. It should be considered when a single database instance can no longer handle the read/write throughput or storage capacity required by the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4cb3382-4110-4ab7-a594-29bb62773661', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the ''server'' directory in Nuxt?', N'Fresher', N'The server directory is used for creating backend API endpoints and server-side logic within your Nuxt application. It allows you to build full-stack features directly inside your Nuxt project without needing a separate backend server for simple tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8919613-ecbf-41cb-b6c4-29c050f5f0d8', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Describe the architectural benefits of using a Sidecar pattern.', N'Senior', N'The sidecar pattern offloads cross-cutting concerns like logging, monitoring, and security to a separate process running alongside the application. This decouples infrastructure logic from business code, allowing teams to update or maintain system-level functionality without redeploying the main application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3315993f-5326-4ee9-a16d-29c20db6d9bb', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the role of the ''public'' folder in an Astro project?', N'Intern', N'The public folder is used for static assets that do not need to be processed by Astro. Files placed here, such as images or fonts, are copied directly to the final build folder.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'356d9ab9-7b7b-4681-97a4-29c504351d66', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar manage response status codes?', N'Fresher', N'Litestar allows developers to specify the HTTP status code for a response either explicitly or by default based on the request method. For example, a successful creation request might default to a 201 status code, while a standard retrieval defaults to 200.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b3d2f5b-97c0-480b-8e2c-29c572df79c5', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Does Hono support multiple JavaScript runtimes?', N'Intern', N'Yes, Hono is platform-agnostic, meaning it is built to run consistently across different environments. This includes Node.js, Bun, Deno, and various serverless platforms like Cloudflare Workers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4d5ea83-a626-495b-a1a7-29c6597bb862', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the purpose of the Router type in Axum?', N'Fresher', N'The Router type is the central component that defines the application structure. It holds the mapping of paths to handlers and serves as the main entry point for requests arriving at the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9acb1c1-fde1-448e-b6aa-29c694c04a91', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why might a query optimizer choose a table scan instead of using an existing index?', N'Middle', N'The optimizer may choose a full table scan if it determines that fetching the majority of rows via the index would be slower than sequential disk access. This often happens on small tables or when the query selects a large percentage of the table''s total rows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b04abfd-5a41-438d-8e69-29cbd8e00568', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What does ''lazy-loading'' mean in Qwik?', N'Junior', N'Lazy-loading in Qwik refers to breaking the application into small, independent chunks of code. These chunks are only fetched from the server when a specific user interaction, like a click or hover, triggers them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f41298f-2f45-476a-bc78-29ccc3dacab9', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason about the trade-offs of using a cutting-edge technology versus a mature, established one?', N'Middle', N'I evaluate the technology based on the team''s familiarity, the availability of support and libraries, and the long-term support lifecycle. While newer tech may offer performance gains, established tech reduces risk and development time, which is usually preferable unless the new tech provides a distinct strategic advantage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5f0ec63-f063-4dca-82b9-29ce53d5bf7d', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What are the limitations of ''Gold Signal'' monitoring (Latency, Traffic, Errors, Saturation)?', N'Senior', N'While the Four Golden Signals provide a high-level view of system health, they often fail to capture business-level anomalies or complex logical bugs. They describe the symptom of the system behavior but rarely provide enough context for root cause analysis without deeper tracing and logging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd92ca7f7-24ea-4490-a952-29cf66322b5a', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the purpose of middleware in Litestar?', N'Intern', N'Middleware are components that sit between the server and the application, allowing you to intercept and process every incoming request or outgoing response. They are commonly used for tasks like logging, authentication, and CORS headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cec333f-cd13-4f9f-8ccb-29d11e47dfc6', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the significance of the ''Responder'' trait in Rocket?', N'Middle', N'The Responder trait defines how a type can be converted into a HTTP response. It allows developers to create custom types that encapsulate status codes, headers, and body content, simplifying the process of returning consistent API responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fea574f-a802-4f1c-8ddc-29d26b1869e3', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the trade-offs of using strongly consistent reads?', N'Middle', N'Strongly consistent reads ensure you always get the latest data but come at the cost of higher latency and lower availability during network partitions. They also consume double the read capacity units compared to eventually consistent reads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e62fa6a-6c72-499f-930c-29d386fbb02e', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is a BSON format in MongoDB?', N'Intern', N'BSON stands for Binary JSON. It is a binary-encoded serialization of JSON documents that MongoDB uses for storage and network transfer. It is designed to be lightweight, traversable, and efficient, while supporting more data types than standard JSON.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9179e27-2437-4d0e-af1b-29d45e6dbb2d', N'075b8862-431c-4678-9767-f55359758a4a', N'What happens if you modify a prop directly in a child component?', N'Middle', N'Vue enforces one-way data flow, so modifying a prop directly will trigger a console warning. The change will not propagate back to the parent and will be overwritten the next time the parent re-renders, leading to inconsistent state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c907fea-3051-4363-8bda-29d941f5280f', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the Go garbage collector?', N'Intern', N'The garbage collector is a component of the Go runtime that automatically manages memory by reclaiming space used by objects that are no longer accessible. This helps prevent memory leaks and reduces the burden of manual memory management for the developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
