INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef13dcc0-2d79-4d2d-a94b-29ffcf1b8566', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the significance of the Rust compiler, rustc?', N'Fresher', N'The compiler is central to Rust because it performs extensive static analysis to ensure memory safety and type correctness before a program ever runs. If the code violates ownership or borrowing rules, the compiler will refuse to build the program, catching errors early in the development cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f2701e9-9412-40a6-9d97-2a012a012c73', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are Progressive Web Applications (PWAs)?', N'Intern', N'Progressive Web Applications (PWAs) are web applications that use modern web capabilities to deliver an app-like experience to users. They are reliable, fast, and engaging. PWAs can work offline, send push notifications, and be installed on a user''s home screen. They leverage technologies like service workers, web app manifests, and HTTPS to provide these features. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec453e91-6304-4611-bd81-2a014242a072', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is an event table', N'Intern', N'Event Table is a data structure that stores and keeps track of all the events which will be executed asynchronously like after some time interval or after the resolution of some API requests. i.e Whenever you call a setTimeout function or invoke async operation, it is added to the Event Table. It doesn''t not execute functions on it’s own. The main purpose of the event table is to keep track of events and send them to the Event Queue as shown in the below diagram. !Screenshot', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fb32082-5a4a-4da7-bf3f-2a01d7d845fc', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the architectural implications of using the Rails identity map or request-store for data caching?', N'Senior', N'These patterns allow sharing data across the request lifecycle to avoid redundant database hits. However, they introduce risks like stale data if the underlying record is updated during the request and can increase memory usage if large collections are cached prematurely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9c6689f-1163-4ffc-ae56-2a054bc440a2', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is a Spring Bean?', N'Intern', N'A Spring Bean is an object that is instantiated, assembled, and managed by the Spring IoC container. Beans are defined by configuration metadata and are the fundamental building blocks of a Spring application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fec7f930-a9b7-4aa2-ba30-2a0741e86b85', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What does it mean that Go is a compiled language?', N'Intern', N'Go code is translated directly into machine code before execution, resulting in high-performance binaries. This contrasts with interpreted languages that require a runtime engine to read and execute the code line by line.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'855089fb-f749-4f15-83c0-2a095ec4aa3b', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra''s peer-to-peer architecture differ from a primary-replica model regarding availability?', N'Senior', N'Cassandra utilizes a decentralized, leaderless architecture where every node can perform read and write operations. This eliminates single points of failure and prevents bottlenecks common in primary-replica setups, ensuring high availability even if several nodes fail.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f2f402c-86ee-44f2-9250-2a0a978c6735', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the benefit of Micronaut''s ''Fast Startup'' time?', N'Fresher', N'Fast startup allows applications to scale rapidly in response to traffic spikes. It is particularly beneficial in cloud-native environments where instances need to boot quickly to handle incoming requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00c46053-604e-44f2-8faf-2a0b7a5eff8a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you redeclare variables in a switch block without an error', N'Fresher', N'When you try to redeclare variables using let or const in multiple case clauses of a switch statement, you will get a SyntaxError. This happens because, in JavaScript, all case clauses within a switch statement share the same block scope. For example: To avoid this error, you can create a new block scope within each case clause by wrapping the code in curly braces {}. This way, each let or const declaration is scoped only to that block, and redeclaration errors are avoided: That means, to safely redeclare variables in different cases of a switch statement, wrap each case’s code in its own block using curly braces. This ensures each variable declaration is scoped to its specific case block.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2cb9f34-2b8e-4bf7-b5d4-2a0ce2935da5', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle request validation?', N'Intern', N'AdonisJS uses a built-in validator service that allows you to define rules for incoming request data. It automatically checks the data against these rules and returns an error response if the validation fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e528f9a-a204-4dac-bf00-2a0d584e713b', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between ''if let'' and ''guard let''?', N'Intern', N'If let is used to conditionally bind an optional value to a local constant within an if block. Guard let is used to bind an optional value and requires an early exit if the binding fails, ensuring the variable remains available for the rest of the scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0b0b028-ad83-4b77-8dc6-2a0e9ab60c7c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you minimize the impact of ''noisy neighbor'' problems in a multi-tenant cloud environment?', N'Senior', N'I implement strict resource quotas and rate limiting at the API gateway layer to ensure fair sharing of compute and memory. By using container orchestration tools to define resource limits and isolation policies, I prevent a single tenant from starving the system of resources needed by others.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa80274e-283f-498f-b29b-2a0ee1a261fb', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Explain the trade-off between monolithic architecture and microservices for a small team.', N'Junior', N'A monolith is simpler to deploy, test, and reason about initially, making it ideal for small teams. Microservices offer better scalability and independent deployment for specific components but introduce significant operational overhead and complexity in service communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3cacabe-16c8-4310-8e97-2a13fef58566', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is an Active Record migration?', N'Junior', N'A migration is a feature of Active Record that allows you to evolve your database schema over time. It provides a way to describe changes to your database structure using Ruby code instead of raw SQL, making it easier to version control and share schema updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'562aa2d6-2bbc-46d5-b8ec-2a14e41880e2', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Why is Hono considered a ''zero-dependency'' framework?', N'Junior', N'Hono is written to be lightweight and does not rely on heavy external libraries for its core functionality. This minimizes the bundle size and reduces the risk of supply chain vulnerabilities, which is critical for edge-deployed applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e220162-e4d2-45a5-809b-2a153e56fde1', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Compare Fiber''s error handling mechanism to the standard library''s error return pattern.', N'Senior', N'Fiber encourages returning errors directly from handlers, which are then intercepted by a global error handler middleware. This centralizes logging and response formatting, whereas the standard library often requires manual error handling and response writing within every individual handler function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8d24b55-7759-4ced-b371-2a1ae5a2ff57', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is an inverted index in Elasticsearch?', N'Fresher', N'An inverted index is a data structure used to map content to its location in a document, similar to an index at the back of a book. It allows for extremely fast full-text searches by storing a list of unique words and the documents they appear in.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9504fb2d-b323-46e8-ab6d-2a1e49cfa70a', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle DOM updates efficiently?', N'Junior', N'SolidJS uses fine-grained reactivity to update specific parts of the DOM directly. Because it does not use a Virtual DOM, it avoids the overhead of comparing tree structures and only modifies the nodes that actually changed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd84ee885-a795-48db-bdf1-2a213c01f574', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is CRAN?', N'Intern', N'CRAN stands for the Comprehensive R Archive Network. It is a global network of servers that store identical, up-to-date versions of code and documentation for R, serving as the official repository for R packages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14481c22-f5dc-4292-9d52-2a2446f42cb6', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the performance implication of blocking the event loop in an Express app?', N'Middle', N'Since Node.js is single-threaded, performing heavy CPU-bound tasks inside an Express route will block the event loop, preventing the server from handling other incoming requests. This leads to latency and potential timeouts for all users until the task finishes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a64c55da-7ec4-49e9-9907-2a24b33240be', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is Subresource Integrity (SRI) and how is it used?', N'Intern', N'Subresource Integrity (SRI) is a security feature that allows browsers to verify that files loaded from third-party sources (CDNs) have not been tampered with. The browser computes a cryptographic hash of the downloaded file and compares it to the expected hash in the integrity attribute. If they don''t match, the resource is blocked. Syntax: Generating the hash: Or use srihash.org to generate hashes online. Why crossorigin="anonymous" is required: SRI requires the resource to be served with CORS headers. The crossorigin="anonymous" attribute tells the browser to make a CORS request without sending credentials.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5dd0c25-341c-40d0-b0c7-2a294e2c0b21', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is an action in Redux and what is its mandatory property?', N'Middle', N'An action is a plain JavaScript object that describes a change to be performed on the state. It is mandatory for an action to have a ''type'' property that indicates the intent of the action.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
