INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94ecbf52-0eed-4c71-952b-2a2a234c1d1a', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does ''tailrec'' optimization work in Kotlin?', N'Middle', N'The tailrec modifier allows the compiler to optimize recursive functions by transforming them into iterative loops under the hood. This prevents StackOverflowError by reusing the stack frame instead of creating new ones for each recursive call.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a943b14-c830-48d3-88b5-2a2c297cdc0f', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain the concept of ''Content Visibility'' and its impact on the Critical Rendering Path.', N'Senior', N'The content-visibility property allows the browser to skip the rendering work, including layout and painting, for elements that are off-screen. This drastically improves initial page load times and interactivity by deferring the processing of hidden content until it enters the viewport.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ac66c0b-a703-4f32-b3ba-2a2d5cab1aca', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do you ensure data integrity across multiple services in a Rails-based architecture?', N'Senior', N'Since standard database transactions do not span microservices, you must implement patterns like the Saga pattern or two-phase commits to ensure eventual consistency. These patterns coordinate compensating transactions to roll back changes if a later step in a distributed workflow fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2117362-636f-4531-bd9c-2a2eff5bf1b2', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the significance of the ''class'' of an object in R?', N'Fresher', N'The class of an object determines how R functions behave when applied to that object. For example, generic functions like ''print'' or ''summary'' will produce different outputs depending on whether the input is a data frame, a list, or a numeric vector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e836627a-f5ed-416a-95e6-2a2f7205a636', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When implementing observability, what is the trade-off between high-cardinality data and storage costs?', N'Senior', N'High-cardinality data provides granular visibility into specific failures but drastically increases storage and index costs in time-series databases. I balance this by implementing sampling strategies for high-volume logs and using high-cardinality data only for critical metrics. I prioritize the signal-to-noise ratio to ensure that operational insights remain cost-effective.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef0c2a2d-d71c-48fb-936a-2a331a65548d', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How do ''ContextReplacementPlugin'' or ''IgnorePlugin'' help with bundle size optimization?', N'Senior', N'These plugins allow developers to exclude unnecessary files or directories from being processed by the bundler, such as locale files in libraries like moment.js. This significantly reduces the size of third-party dependencies by stripping out unwanted features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8064a85-fa47-4fb2-a8a9-2a352fff9471', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL handle data integrity?', N'Fresher', N'PostgreSQL ensures data integrity through the use of constraints such as primary keys, foreign keys, unique constraints, and check constraints. These rules prevent invalid data from being inserted into the database and maintain relationships between tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
