INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dab84b0e-dfd7-45e8-88a5-2a3cc666cc7e', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the benefit of schema-based serialization in Fastify?', N'Intern', N'Schema-based serialization allows Fastify to compile the output transformation into a high-speed function. This significantly reduces the time required to convert objects into strings before sending them to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2fdca06-5ab7-4917-8eac-2a3ef43aeb3e', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How do Elasticsearch''s primary and replica shard allocation strategies influence write consistency and availability during a node failure?', N'Senior', N'Elasticsearch manages write consistency through the ''wait_for_active_shards'' setting, which ensures a quorum of replicas acknowledges the write before confirming success. During a node failure, the master node promotes a replica to primary status, maintaining availability, but the cluster enters a yellow state if the required replica count is not met. This architecture prioritizes durability and availability but requires careful balancing of replica counts to avoid excessive inter-node traffic and resource contention during recovery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6d7a81f-e1ca-422e-af92-2a3fe9093c4a', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are Django forms used for?', N'Junior', N'Django forms are used to handle user input, data validation, and HTML form rendering. They provide a secure way to clean incoming data and translate it into Python objects that can be saved to the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
