INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e02dbe1-e3e3-4646-a5d9-2a4457af350b', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs when choosing between a polling mechanism and a push-based mechanism (like WebSockets) for real-time updates?', N'Middle', N'Polling is easier to implement and works well with standard infrastructure, but it is inefficient and creates unnecessary server load. Push-based mechanisms are highly efficient for real-time data and provide lower latency, but they require persistent connections and more complex server-side state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e66fe3b3-6dd2-4127-af6c-2a45345fc5a0', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix''s approach to data loading differ from standard React Query-based patterns?', N'Senior', N'Remix utilizes route-based loaders that execute on the server before the component renders, effectively eliminating request waterfalls. Unlike client-side data fetching where the UI mounts before data is requested, Remix ensures the data is available at the moment of hydration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'077985e9-c63f-41f4-9b52-2a46c1a5eedf', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why does SolidJS avoid the use of ''hooks'' in the same way React does?', N'Senior', N'SolidJS components are functions that run only once, so the concept of hooks—which rely on execution order and re-renders—is unnecessary. Its reactive primitives are simply functions that interact with the global reactive graph, making them more predictable and less prone to ''rules of hooks'' violations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
