INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3064628-b52f-4a0f-b7bc-2a6cad017b0b', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a dangling pointer?', N'Intern', N'A dangling pointer is a pointer that references a memory location that has been deallocated or is no longer valid. This situation typically occurs when the memory to which the pointer was pointing has been freed or deleted, or when the object it was referencing has gone out of scope. Causes of Dangling Pointers 1. Premature Deallocation: Memory is freed or deleted while pointers to it still exist. 2. Returning Local References: Returning a reference or pointer to a local variable that goes out of scope. 3. Use-After-Free: Accessing memory through a pointer after it has been deallocated. Avoiding Dangling Pointers 1. Smart Pointers: Utilize std::unique_ptr, std::shared_ptr, or std::weak_ptr from the C++11 standard library to manage memory automatically. 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
