INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74f87dd8-440a-460e-988f-2a6f19a74e01', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro manage the trade-offs between static site generation (SSG) and server-side rendering (SSR) at the route level?', N'Senior', N'Astro allows developers to define the output mode on a per-page or per-directory basis. This hybrid approach enables pre-rendering high-traffic marketing pages for speed while using SSR for dynamic user-specific pages, effectively balancing performance and data freshness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfc78f20-0de8-424f-9807-2a702a857c33', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro facilitate data fetching?', N'Fresher', N'In Astro, data fetching happens in the frontmatter of the component. Since this code runs on the server during the build process, you can safely fetch data from APIs or databases without exposing credentials to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'499ec6d6-9c79-4837-8daf-2a72c95a0552', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the Ember Run Loop?', N'Fresher', N'The Run Loop is a mechanism that manages the execution of tasks in an Ember application. It batches updates and operations together to optimize performance and ensure that data changes are processed efficiently in the correct order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b518d7aa-b983-41aa-9a49-2a7409e1f49b', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How do you choose between an LRU and a FIFO (First-In, First-Out) eviction policy?', N'Middle', N'LRU is generally superior for most applications because it retains data that is actively being used. FIFO is simpler but treats all items equally regardless of usage, which often leads to evicting frequently accessed items simply because they were added to the cache first.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bd05983-76db-4591-8e32-2a7423412bca', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What design patterns are commonly used in microservices architectures?', N'Senior', N'Several design patterns lend themselves well to microservices architectures, offering best practices in their design and implementation. Common Design Patterns - API Gateway: A single entry point for clients, responsible for routing requests to the appropriate microservice. - Circuit Breaker: A fault-tolerance pattern that automatically switches from a failing service to a fallback to prevent service cascading failures. - Service Registry: Microservices register their network location, making it possible to discover and interact with them dynamically. This is essential in a dynamic environment where services frequently start and stop or migrate to new hosts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59f17253-cfc0-4dd3-aaeb-2a75c06a7627', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit''s streaming data feature work?', N'Middle', N'Streaming data allows you to return a promise from a load function, which SvelteKit then resolves on the server and streams to the client as it becomes available. This improves the ''Time to First Byte'' and allows the user to see parts of the page before slow data-fetching tasks are finished.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a47ae0c-90c6-4ba5-9612-2a7643238e3c', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of the ''Job'' class in Laravel?', N'Middle', N'A Job class encapsulates a single unit of work that needs to be performed, typically asynchronously. It provides a structured way to define the task logic, configure retries, and manage timeouts, making background processing robust and maintainable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7395c218-f48e-49aa-a849-2a776eaee8a8', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the Preact CLI?', N'Fresher', N'The Preact CLI is a command-line tool that helps developers set up, develop, and build Preact applications. It provides a standard project structure, a development server with hot-module replacement, and optimized build configurations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7095d183-07cf-48da-a63d-2a7809eb1934', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of the ''Data Type'' in a table column definition?', N'Junior', N'The data type defines the kind of information a column can hold, such as integers, dates, or strings. This enforces data validation at the database level and ensures efficient storage and processing of the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef762953-9304-455d-b791-2a78a6fbd029', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch ensure data durability during node restarts?', N'Senior', N'Durability is ensured by the combination of the translog for uncommitted operations and the periodic Lucene commits to persistent storage. Upon restart, the node replays the translog to recover any operations that were in memory but not yet committed to the segment files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ca043a9-f609-44d3-b725-2a79ba81a038', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web ensure type safety?', N'Junior', N'Actix-web leverages Rust''s strong static type system to enforce strict contracts between requests and handlers. If an extractor expects a specific JSON structure, the framework will automatically validate the input and return a bad request error if the types do not match.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c78c3bc9-e093-4d44-ab91-2a7a07c3d54b', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Why does Scala encourage the use of immutable collections?', N'Junior', N'Immutable collections prevent side effects by ensuring that data cannot be modified after creation. This makes code safer, easier to reason about, and inherently thread-safe in concurrent environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd68ee2ef-0fb4-479e-9291-2a7bc1659e37', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does JavaScript implement ''Tail Call Optimization'' and why is it rarely supported?', N'Senior', N'TCO allows a function call in a tail position to reuse the current stack frame instead of creating a new one, preventing stack overflows. It is rarely implemented because it complicates debugging and stack trace generation, which are critical in the dynamic JavaScript ecosystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e161aad-c2c0-4f0d-bc03-2a7d3c9b8ab6', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Explain the concept of ''Error Boundaries'' and why they cannot catch all types of errors.', N'Senior', N'Error Boundaries catch JavaScript errors in their child component tree during lifecycle methods and rendering, allowing for a graceful fallback UI. They do not catch errors in event handlers, asynchronous code, or server-side rendering, as these errors occur outside the React component reconciliation cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
