INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1958daad-f0f2-4133-8fa0-2a848ecb353e', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What are the trade-offs of caching at the ''Edge'' versus the ''Origin''?', N'Senior', N'Edge caching provides the lowest latency for end-users by serving content from geographically close locations, but it makes invalidating that content difficult and slow. Origin caching is easier to manage and update but increases latency for users and puts more load on the backend infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
