INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89b7fb84-b385-44e4-ac13-2a8cf7907f95', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you create a service in Angular and why would you use one?', N'Fresher', N'Services are instrumental in Angular for finer architectural design and sharing common functionality across components. Angular automatically injects a service when a component or another service needs it. This mechanism fosters the "Don''t Repeat Yourself" (DRY) principle, leading to more modular, maintainable, and testable code. Service Creation You can create a service in Angular using either of these methods: 1. CLI: Use the Angular CLI to generate a service. 2. Manual: Create a .ts file for the service and define the class. Using the Service 1. Service Registration: - Module: Link the service to a specific module by adding it to the providers array in @NgModule. - Dependency Injection Tree: Use a tree level below the root or at a component level. 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e41b510-f7c7-41b5-b5fb-2a8d9880e9e3', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the ''N+1'' query problem and how does it relate to database design?', N'Middle', N'The N+1 problem occurs when an application executes one query to fetch a list of items and then executes an additional query for each item to fetch related data. This results in poor performance due to excessive round-trips to the database, which is best solved using JOINs or eager loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74d0c6b6-93b4-49f0-9cdc-2a8fab0e7ed4', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a database transaction in MySQL?', N'Intern', N'A transaction is a sequence of one or more SQL operations treated as a single unit of work. It follows ACID properties to ensure that either all operations within the transaction succeed or none of them do, maintaining data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
