INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff1982ce-b11c-4dec-b63c-2a9421cf7538', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of Django’s signal framework and when should you avoid using it?', N'Senior', N'Signals decouple parts of the application by allowing senders to notify receivers of events. They should be avoided when they lead to hidden side effects that make the control flow difficult to trace, or when they execute slow logic synchronously, which can block the main request thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40e11c40-4894-4ef5-a092-2a97046f7bbb', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Discuss the performance trade-offs of using ''eval'' or ''new Function'' in a modern JS environment.', N'Senior', N'These functions bypass static analysis, preventing the JIT compiler from performing optimizations like scope flattening or type inference. Furthermore, they introduce significant security risks regarding code injection and force the engine to stay in a slower execution mode due to the potential for dynamic local variable modification.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0485a60c-b759-4f44-b2a0-2a98a86ee8c8', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the Go garbage collector (GC) approach latency versus throughput?', N'Middle', N'The Go GC is designed as a concurrent mark-and-sweep collector that prioritizes low latency. It works alongside the application to minimize ''stop-the-world'' pauses, making it highly suitable for real-time services where consistent response times are more critical than raw throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eafa2fde-4c03-482b-aa86-2a98c9f9190c', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How assert works in Node.js?', N'Fresher', N'The assert module provides a way of testing expressions. If the expression evaluates to 0, or false, an assertion failure is being caused, and the program is terminated. This module was built to be used internally by Node.js.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a49ed138-ba67-4a36-a742-2a9b6efcae4d', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of the Endpoint in Phoenix?', N'Intern', N'The Endpoint is the first layer of the Phoenix request pipeline. It is responsible for starting the server, handling basic configuration, and passing the request to the router.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36323c3a-ba65-4fcf-888c-2a9d2b308a0b', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of the Option enum in Rust?', N'Intern', N'The Option enum is used to represent the concept of a value being either present or absent. It forces the programmer to explicitly handle the case where a value might be missing, which helps prevent null pointer errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd92bc745-c797-4296-b397-2a9dbb097819', N'4c000000-0000-0000-0000-000000000005', N'What are the benefits and drawbacks of using a Microservices architecture compared to a Monolithic architecture?', N'Middle', N'Microservices enable independent deployment, scaling, and technology choices for different service components, but they introduce significant operational complexity and challenges in data consistency and inter-service communication. Monoliths are simpler to develop, test, and deploy initially but can become difficult to maintain and scale as the application grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10f1320c-a7f9-4e54-873a-2a9df65492c9', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI''s dependency injection system facilitate architectural decoupling and testability?', N'Senior', N'The dependency injection system allows developers to declare dependencies as function parameters, which are resolved and injected by the framework at runtime. This decouples business logic from external concerns like database connections or authentication, enabling easy substitution of mocks or stubs during unit testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'765cd4e6-bd1d-4fb5-9bd9-2a9e265b662f', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Explain the difference between ''Box'', ''Rc'', and ''Arc'' in terms of memory management and concurrency.', N'Senior', N'Box provides unique ownership on the heap, Rc provides shared ownership for single-threaded contexts using reference counting, and Arc provides thread-safe shared ownership using atomic reference counting. The choice between them depends on whether the data needs to be moved, shared across scopes, or shared across thread boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7abd6dfb-2eaf-42d5-bce4-2a9e391927ab', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the difference between physical and logical replication in database clusters?', N'Senior', N'Physical replication copies the exact binary changes from the data files, which is faster but requires identical hardware and software versions. Logical replication streams individual data changes, allowing for more flexibility, such as replicating between different database versions or filtering specific tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f634c8d0-561d-4e07-b9fe-2a9ff863c5b4', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you balance the trade-off between feature development speed and technical debt?', N'Junior', N'I communicate the trade-offs to stakeholders, suggesting that we build a working solution now while documenting the necessary improvements. I advocate for allocating dedicated time in subsequent sprints to address the accrued debt, ensuring it does not accumulate to a point where it hinders future development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'244b8a65-924d-4e74-bb44-2aa14de8bf7d', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin''s middleware architecture function, and what are the trade-offs of using it compared to standard library handlers?', N'Middle', N'Gin uses a chain-of-responsibility pattern where each middleware calls the next handler in the sequence via a context object. This allows for powerful request interception and state sharing throughout the request lifecycle. While it offers superior developer productivity and cleaner code organization, it introduces a slight performance overhead due to reflection and context allocation compared to the standard library''s net/http implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd40dd256-aa69-418f-b7b5-2aa242c74e79', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How do Kotlin''s ''sealed classes'' improve type safety and exhaustiveness checking compared to standard inheritance?', N'Senior', N'Sealed classes restrict the class hierarchy to a known set of subclasses defined within the same package or file, enabling the compiler to guarantee exhaustive ''when'' expressions. This architectural constraint prevents unhandled states in complex domain models, eliminating the need for default branches that hide potential logic errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22618f51-c239-4c80-b874-2aa633364095', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte''s compilation process affect debugging?', N'Middle', N'Because Svelte transforms code significantly, debugging can sometimes be harder if the generated code deviates greatly from the source. However, Svelte provides source maps that allow developers to step through their original component code in browser developer tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f13c88ae-ad7e-49a7-9c2f-2aa63e7f7df7', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why does React enforce the ''Rules of Hooks'' regarding call order?', N'Senior', N'React relies on the order in which hooks are called to maintain the internal state of a component across re-renders. If hooks are called conditionally, the internal state pointers would mismatch, leading to bugs where state values are incorrectly assigned to the wrong hooks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4219da4e-a943-4e77-b3ec-2aaa069e3858', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot''s ''Auto-Configuration'' mechanism work internally, and what are the architectural trade-offs when relying heavily on it in a large-scale microservices environment?', N'Senior', N'Auto-configuration leverages the @EnableAutoConfiguration annotation and the SpringFactoriesLoader mechanism to scan for configuration classes defined in META-INF/spring.factories based on classpath dependencies. While it accelerates development, the trade-off is reduced visibility into the bean lifecycle and potential performance overhead during startup due to extensive conditional processing. In large systems, this ''magic'' can make debugging complex dependency conflicts difficult, often necessitating manual exclusions to maintain predictable startup behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ceeac002-76a4-4ec1-a6dc-2aaa3c2df4d4', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why is a component constructor called only once?', N'Fresher', N'React''s _reconciliation_ algorithm assumes that without any information to the contrary, if a custom component appears in the same place on subsequent renders, it''s the same component as before, so reuses the previous instance rather than creating a new one.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd50dac0d-cd55-4176-97fa-2aadf2528ec0', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery handle memory leaks, and why is this a recurring issue in complex Single Page Applications (SPAs)?', N'Senior', N'jQuery can inadvertently retain DOM node references in its internal cache if developers do not explicitly use methods like remove() or empty() to clean up events and data. In long-running SPAs, these orphaned references prevent garbage collection, leading to progressive memory exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa8acd5b-475f-4b36-91d7-2aae5ef9039d', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus provide security?', N'Fresher', N'Quarkus provides security through extensions that support standard protocols like JWT, OAuth2, and OpenID Connect. It allows developers to easily secure REST endpoints by adding simple annotations to define access roles and authentication requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b82b1203-707d-47ba-bfb3-2aaf239b123f', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How does sharding improve database performance?', N'Middle', N'Sharding improves performance by splitting a large dataset into smaller, more manageable chunks distributed across multiple database servers. This horizontal partitioning reduces the load on any single server and allows for parallel processing of queries, though it complicates cross-shard joins and transaction management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9ee7521-dde5-4713-ae53-2ab18d580674', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the primary architectural trade-off when using Redis Cluster compared to a single-node instance?', N'Senior', N'Redis Cluster provides horizontal scalability and high availability through sharding, but it introduces complexity in client-side routing and cross-slot operation limitations. While a single node is simpler to manage, it suffers from vertical scaling constraints and a single point of failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f0b8648-1700-43fe-90e9-2ab1d58ac82f', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does ''eventual consistency'' mean in NoSQL?', N'Intern', N'Eventual consistency is a model where updates to data are not immediately visible to all nodes in a distributed system. The system guarantees that, given enough time without new updates, all nodes will eventually reflect the latest data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'702eaba3-dc92-4003-8aa4-2ab54eeec2b8', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What are the architectural implications of using ''fastify-reply-from'' for proxying requests?', N'Senior', N'This allows for efficient stream-to-stream proxying without loading the entire payload into the application memory. It is highly effective for gateway services but requires careful management of upstream connection pools to avoid resource exhaustion under heavy load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab6b59b3-b5b1-4624-8757-2ab69e8ee28a', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust manage the memory overhead of asynchronous tasks?', N'Senior', N'Rust''s async model is based on state machines generated by the compiler, where all necessary data for a task is stored in a single, compact struct. This allows for highly efficient task switching without the need for segmented stacks or heavy runtime allocation per task.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54ff03da-0388-4a3a-ad24-2ab8ed030ab8', N'075b8862-431c-4678-9767-f55359758a4a', N'Is recommended to use async for computed properties?', N'Middle', N'No, it is not recommended. Computed properties should be synchronous. But if you still use asynchronous actions inside them, they may not work as expected and can lead to an unexpected behaviour. For example, the below usage of async/await is not recommended, Note: If you still prefer to use async computed properties for some reason then you can consider using additional plugin such as vue-async-computed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe003809-525c-4ebb-98cb-2ab8ede00787', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does ''tailrec'' optimization work?', N'Middle', N'The ''tailrec'' modifier instructs the compiler to replace recursive function calls with a standard iterative loop. This prevents stack overflow errors in algorithms that would otherwise require deep recursion, while keeping the code logic expressive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6a03872-f1ae-4247-b00d-2ab956e38687', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle a situation where you realize you will miss a deadline?', N'Intern', N'I would notify my supervisor as soon as I realized the delay was inevitable, rather than waiting until the deadline. I would provide a clear explanation for the delay and suggest a revised timeline based on the remaining work. Proactive communication helps manage expectations and allows the team to adjust plans accordingly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f40bdb48-6f13-4e5c-8f3f-2aba3779166e', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the purpose of the ''schema'' property in a Fastify route definition?', N'Junior', N'The schema property allows you to define JSON schemas for input validation and output serialization. This enables Fastify to automatically validate incoming requests and optimize the serialization of the response, improving performance and security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75ae4766-393a-41a1-97f9-2abb9cd17282', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are the trade-offs of using ''preact/compat''?', N'Middle', N'Using compat allows for seamless integration of the React ecosystem, but it increases the final bundle size. It acts as a compatibility layer that maps React-specific APIs to Preact, sacrificing the core benefit of extreme minimalism for the sake of library support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd74a6e38-863d-44e6-a24b-2abd2ad4e3f1', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the ''void'' pointer?', N'Fresher', N'A void pointer is a generic pointer type that can hold the address of any data type. It cannot be dereferenced directly because the compiler does not know the size or type of the object it points to, so it must be type-casted first.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c60d1023-0339-4f6a-86ce-2abd616c26f9', N'4c000000-0000-0000-0000-000000000005', N'How would you design a system to support high-throughput write requests?', N'Senior', N'Use an append-only log structure for data ingestion to optimize for sequential writes, and offload processing to asynchronous workers via a distributed queue. This approach decouples the acceptance of the request from the expensive processing logic, allowing the system to absorb traffic spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9d3a2ff-a1ef-4127-a385-2abd9d40f7e8', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does context switching between fibers compare to context switching between OS threads?', N'Middle', N'Fiber context switching is significantly faster because it happens entirely in user space. It only requires saving and restoring a small set of registers and the stack pointer, whereas OS thread switching requires a transition to kernel mode and updating hardware-level thread control blocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80b77642-10ea-4dc7-b169-2ac07c79eba0', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain how MongoDB avoids data corruption during power failures.', N'Senior', N'WiredTiger uses journaling to record changes before they are applied to the database files. In the event of a crash, MongoDB replays the journal entries upon restart to recover the database to the last consistent state, ensuring durability for acknowledged writes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54572aa1-cf13-4a77-81c1-2ac10262c2d1', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the purpose of the ''deferred as'' import in Dart?', N'Middle', N'Deferred loading allows a library to be loaded lazily on demand rather than at startup. This is primarily used to reduce the initial size of the application, improving startup times for large web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8385907d-d70d-4b90-951b-2ac140032499', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you manage configuration settings for an application across different environments like staging and production?', N'Middle', N'I use environment variables or centralized configuration services to externalize settings from the code. This ensures that the same artifact can be deployed across different environments without modification. I also ensure that sensitive secrets are handled through a secure secret management vault.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d338005-686a-4b9d-af33-2ac153d3c0ff', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a struct in Go?', N'Intern', N'A struct is a collection of fields that represent a custom data type. It is the primary way to group data together in Go, functioning similarly to a record in other languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56c5c185-ead4-45f1-9e48-2ac1c0eb34a4', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain classes in TypeScript. How are they different from ES6 classes?', N'Fresher', N'While TypeScript and ES6 classes share many similarities, TypeScript''s classes offer additional features and strong typing to make your code more robust. Key Shared Class Features - Inheritance: Subclasses (children) can extend parent classes, inheriting their methods and properties. - Polymorphism: Derived classes can define methods with the same name as their parent. - Encapsulation: Data hiding is supported through access modifiers, such as public, private, and protected. - Constructor: Instantiation starts with a constructor method, if defined. Unique TypeScript Class Features Field Declaration In TypeScript, you can specify fields directly in the class without initializing them. Automatic initialization to undefined occurs during object creation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a9ade45-d286-42c9-87f5-2ac6314cd0cc', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the difference between c.Request and c.Writer in Gin?', N'Intern', N'c.Request represents the incoming HTTP request containing headers, body, and URL data. c.Writer is an interface used to construct and send the HTTP response back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85169e04-0dd5-4150-b903-2ac6babc4c79', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the CSS Box Model and how does the ''box-sizing'' property affect it?', N'Middle', N'The box model defines how elements are rendered, consisting of content, padding, borders, and margins. By default, the width and height only include the content, but setting ''box-sizing'' to ''border-box'' includes padding and borders in the total element dimensions, which simplifies layout calculations significantly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
