INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c04739af-2a45-42d0-bc71-2ac8be9b9978', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript''s structural typing system differ from nominal typing found in languages like Java?', N'Middle', N'TypeScript uses structural typing, meaning types are compatible if they share the same structure, regardless of their explicit declaration. Nominal typing, however, requires explicit inheritance or implementation; even if two objects have identical structures, they would be considered different types if their names don''t match.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
