INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'568eeb9f-c8e6-4581-9690-2acac7d00b6f', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is cargo and how do you create a new Rust project with it?', N'Fresher', N'In Rust, Cargo serves as both a package manager and a build system, streamlining the development process by managing dependencies, compiling code, running related tasks, and providing tools for efficient project management. Key Features - Version Control: Manages packages and their versions using Crates.io. - Dependency Management: Seamlessly integrates third-party crates. - Building & Compiling: Arranges and optimizes the build process. - Tasks & Scripts: Executes pre-defined or custom commands. - Project Generation Tool: Automates project scaffolding. Basic Commands - cargo new MyProject: Initializes a fresh Rust project directory. - cargo build: Compiles the project, generating an executable or library. - cargo run: Builds and runs the project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
