INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0be3065-cf07-48d1-bff9-2ad5240c8507', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the primary architectural difference between Actix and traditional thread-per-request frameworks?', N'Middle', N'Actix is built on the Actor model and utilizes an asynchronous, non-blocking event loop based on Tokio. Unlike thread-per-request frameworks that block a thread for the duration of an I/O operation, Actix handles thousands of concurrent connections on a small number of threads by yielding execution during I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6a8e55c-b8d3-4e04-a857-2ad537cfdd5f', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the ''Layout'' component pattern in Astro?', N'Junior', N'The layout pattern involves creating a reusable component that defines the common structure of your site, such as the head, header, and footer. Other pages then wrap their content inside this layout to ensure a consistent design across the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76271b52-510d-4227-b4a8-2ad630daea59', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How do you handle authentication in Express?', N'Middle', N'Authentication is usually implemented using Passport.js or custom JWT-based middleware that intercepts requests to verify user credentials or tokens. If valid, the user information is attached to the request object for use in downstream authorization checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bee007d9-d277-403c-9179-2ad83fcd44fc', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you check the data type of a variable?', N'Fresher', N'To check the data type of a variable in JavaScript, you can use the typeof operator. For example, typeof variableName will return a string indicating the type of the variable, such as "string", "number", "boolean", "object", "function", "undefined", or "symbol". For arrays and null, you can use Array.isArray(variableName) and variableName === null, respectively. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4adc895f-1a92-4c1f-92c3-2ad8f1894aab', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Why is the use of Alpine.js advantageous for SEO compared to client-side-only SPA frameworks?', N'Middle', N'Since Alpine.js works with standard HTML rendered by the server, search engine crawlers receive fully populated HTML content. This avoids the common SEO issues associated with client-side frameworks where content might be missing until JavaScript is fully executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48798cfe-18d6-4a1d-a02a-2ada048dac84', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Why is the order of packages in the search path critical for stability?', N'Senior', N'The search path determines the order in which R looks for functions and objects; if multiple packages export symbols with the same name, the first one encountered in the search path takes precedence. This can lead to silent bugs or ''masking'' issues where code behavior changes unexpectedly due to package load order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fb37891-edb7-4a1c-8a77-2ae1b294507d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing a microservices architecture, how do you decide between synchronous REST calls and asynchronous event-driven communication?', N'Senior', N'Synchronous communication is easier to reason about but introduces tight coupling and cascading failure risks. Asynchronous communication via message brokers increases system resilience and decoupling but introduces complexity regarding eventual consistency and distributed tracing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eeee883e-f944-4bfe-9ac3-2ae51512dff8', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are AdonisJS Validators?', N'Fresher', N'Validators are a built-in feature used to ensure that the data incoming from client requests meets specific criteria. They help prevent bad data from reaching the database by checking types, lengths, and formats before processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22cb0d22-f2da-4d25-b35d-2ae6527a4813', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web optimize the lifecycle of HTTP connections?', N'Senior', N'Actix-web uses a high-performance HTTP parser and an asynchronous server reactor that keeps connections alive as long as possible. It pipelines requests and manages connection pooling to minimize the handshake overhead associated with TCP and TLS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19f83b22-9b7f-48be-bbda-2ae68344cf86', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are Web Components and how does Lit relate to them?', N'Fresher', N'Web Components are a set of browser-native APIs that allow you to create reusable custom elements with encapsulated functionality. Lit acts as a thin wrapper around these APIs, making it easier to define components and manage their state without the complexity of raw browser APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ed6492c-ca26-401b-9994-2ae7eb42beb0', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does the Kotlin ''Inline'' mechanism for higher-order functions mitigate the overhead of lambda capture?', N'Senior', N'Inlining higher-order functions allows the compiler to insert the lambda''s code directly into the calling function, avoiding the creation of an anonymous object for the function literal. This eliminates both the object allocation overhead and the associated garbage collection pressure, significantly improving performance in tight, frequently executed loops.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c6b894f-1e4c-47b9-9440-2aed6bd7ad19', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the difference between an Exception Filter and a standard Interceptor in NestJS?', N'Middle', N'An Exception Filter is specifically designed to catch unhandled exceptions and transform them into standardized HTTP responses. An Interceptor is more versatile, as it can intercept the flow of a request both before and after a handler is called to modify the input or output.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b7ee031-2c4c-4599-bced-2af11f104923', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is file splitting? When is it used?', N'Intern', N'A monolithic file is fine for solo developers or very small projects. For large projects—sites with multiple layouts and content types, or multiple brands under the same design umbrella—it''s smarter to use a modular approach and split your CSS across multiple files. * reset.css: reset and normalization styles; minimal color, border, or font-related declarations * typography.css: font faces, weights, line heights, sizes, and styles for headings and body text * layouts.css: styles that manage page layouts and segments, including grids * forms.css: styles for form controls and labels * lists.css: list-specific styles * tables.css: table-specific styles * carousel.css: styles required for carousel components * accordion.css: styles for accordion components CSS frameworks such as Foundation and...', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58c82b92-bd9b-41cf-85c0-2af3bf67e9a3', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What does NRT mean in the context of Elasticsearch?', N'Fresher', N'NRT stands for Near Real-Time. It describes the short latency between the time a document is indexed and the time it becomes available for search, typically occurring within one second.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fed0d5d-41b2-448a-a400-2af5f7c4641f', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is DynamoDB Streams and how is it typically used?', N'Middle', N'DynamoDB Streams captures a time-ordered sequence of item-level modifications in a table. It is typically used for real-time data integration, such as triggering serverless functions for downstream processing, cross-region replication, or updating search indexes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecd52218-0b3d-46aa-a393-2af62dccd9e7', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the primary difference between Vue.js and Nuxt.js?', N'Fresher', N'Vue.js is a library focused on building user interfaces and view components. Nuxt.js is a framework that provides an opinionated structure, server-side rendering, and additional configuration on top of Vue to handle complex application requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d794fb0-2b72-47ea-a507-2af87e1a78a1', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the consequence of blocking a handler goroutine in a Fiber application?', N'Senior', N'Blocking a handler goroutine for extended periods consumes a worker from the underlying pool, potentially leading to thread starvation if the application logic involves heavy I/O or long-running computations. This can cascade, eventually causing the server to stop responding to new incoming requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78395b3e-944f-4299-af22-2afb0abbb822', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is an ''Index Intersection'' in MongoDB?', N'Middle', N'Index intersection occurs when the query optimizer uses multiple indexes to satisfy a single query. While sometimes useful, it is generally less efficient than a single compound index that covers the query requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bec0f1c-d51e-4346-9bf9-2afb2d142b0e', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle Error Boundaries differently from standard try-catch blocks?', N'Senior', N'Error Boundaries in SolidJS are declarative components that catch errors occurring within their reactive subtree during the render or effect phase. This allows the application to remain functional by providing a fallback UI instead of crashing the entire reactive execution context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6caeeb23-12ae-4d95-86af-2afb6612bd66', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why is ''body-parser'' no longer needed in newer Express versions, and what are the implications of the change?', N'Senior', N'The body-parsing functionality was integrated directly into the Express core, simplifying setup and reducing dependency bloat. It ensures that standard request bodies are parsed automatically, though developers must still configure limits to prevent memory-based denial-of-service attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74295ae4-f766-467b-a1bc-2afc0cec645e', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you perform Error handling?', N'Fresher', N'If the request fails on the server or fails to reach the server due to network issues, then HttpClient will return an error object instead of a successful response. In this case, you need to handle in the component by passing error object as a second callback to subscribe() method. Let''s see how it can be handled in the component with an example, It is always a good idea to give the user some meaningful feedback instead of displaying the raw error object returned from HttpClient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'449d9cc4-d516-4239-aac2-2afcc6fc0fe1', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is ''Partial Indexing'' and when should it be utilized?', N'Senior', N'Partial indexing creates an index on a subset of a table defined by a conditional clause. It saves storage space and reduces maintenance overhead when queries frequently target only a specific portion of the data, such as active versus archived records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbf9be21-b80c-4e18-8228-2afcefbce782', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is asynchronous programming in Node.js?', N'Intern', N'Asynchronous programming is a form of parallel programming that allows a unit of work to run separately from the primary application thread. When the work is complete, it notifies the main thread (as well as whether the work was completed or failed). There are numerous benefits to using it, such as improved application performance and enhanced responsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32585213-bb61-4190-a2e4-2b0183df6e0f', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are Symfony Environment Variables?', N'Intern', N'Environment variables are configuration settings that change depending on where the application is running, such as development, testing, or production. They are used to store sensitive data like database credentials without hardcoding them in the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c3e45a4-8a78-4903-92aa-2b0210c716a8', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'When would you prefer an event-based consistency model over ACID transactions?', N'Middle', N'Event-based models are preferred in highly distributed, globally available systems where strict latency requirements make synchronous ACID transactions impractical. This approach accepts eventual consistency in exchange for higher availability and partition tolerance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52b54ab1-d126-4f76-bac8-2b04703fe236', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a PostgreSQL schema, and why would you use one?', N'Junior', N'A schema is a namespace within a database that allows you to logically group tables, views, and other objects. Using schemas helps organize database structures and prevents name collisions when multiple applications or modules share the same database instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20b7a1aa-d4f5-4b91-a061-2b0583131525', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle asynchronous error propagation in middleware compared to standard Node.js callbacks?', N'Senior', N'Express uses a specialized next function that accepts an argument to trigger error-handling middleware. Unlike standard callbacks where errors must be manually passed to the first parameter, Express catches errors thrown in synchronous code and allows asynchronous errors to be passed through the next function to reach global error handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c57d208d-26c8-4c4c-9e45-2b05f4b94efc', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are shadowing and illegal shadowing?', N'Intern', N'Both shadowing and illegal shadowing refer to how variable names can "hide" or override others within nested scopes. Shadowing occurs when a variable declared within a certain scope (like a function or block) has the same name as a variable declared in an outer scope. The inner variable shadows the outer one — meaning, the inner variable takes precedence in its own scope. Let''s take an example where the inner a inside func() shadows the outer variable a. Illegal shadowing in JavaScript refers to a syntax error that happens when you try to declare a block-scoped variable (let or const) with the same name as a variable declared using var in the same or an overlapping scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85af09ef-a999-488b-bf80-2b066ed3291f', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the difference between stateless and stateful services in scaling?', N'Middle', N'Stateless services do not store client context between requests, allowing any instance to handle any request, which makes horizontal scaling trivial. Stateful services require session data to be maintained, which complicates scaling because requests must be routed back to the specific node holding that state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5d6369e-6325-4113-b35b-2b0c8df91f8c', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do ''utility types'' like ''Pick'', ''Omit'', and ''Partial'' optimize maintenance in large-scale applications?', N'Senior', N'These utility types allow for the derivation of new types from existing base models, reducing code duplication. By composing these utilities, you can ensure that form inputs, API payloads, and internal state models all remain consistent with the original data model without manual updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70091167-0863-424a-8daa-2b0ef3bca220', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the function of the Micronaut Introduction Advice and how is it implemented?', N'Senior', N'Introduction Advice allows developers to define interfaces that are implemented dynamically at compile time by the framework. Micronaut generates a concrete implementation of these interfaces during the build process, which allows for powerful abstractions like declarative HTTP clients or data repositories without runtime proxy generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77eb4ed1-bb13-42e1-bacc-2b12c70fd71d', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are the limitations of FastAPI''s ''BackgroundTasks'' for high-volume or long-running operations?', N'Middle', N'BackgroundTasks are memory-resident and tied to the application''s lifecycle, meaning they are not persisted if the server crashes or restarts. For long-running or critical tasks, an external task queue system like Celery or RQ is preferred for reliability and horizontal scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5a5f344-aea0-469b-a414-2b16e364eafe', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why is it important to define explicit mappings rather than relying on dynamic mapping?', N'Middle', N'Explicit mappings prevent unexpected behavior where Elasticsearch might infer the wrong data type for a field, which could lead to indexing errors or inefficient query performance. It also allows for granular control over how fields are indexed, analyzed, and stored.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68da179f-3e3b-4dad-97c6-2b183110084a', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the benefits of using ActiveSupport::Concern for code reuse?', N'Middle', N'ActiveSupport::Concern simplifies the process of mixing modules into classes by automatically handling dependencies between included modules and class methods. It allows for cleaner organization of cross-cutting concerns by grouping instance methods and class methods together within a single module.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51c15484-0413-4cbd-b35d-2b18b95c076d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why is it often better to choose a ''boring'' or stable technology over the latest trend?', N'Intern', N'Stable technologies have proven performance, extensive documentation, and a larger support community. The trade-off is choosing reliability and lower risk over the excitement and potential efficiency gains of newer, less-tested tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4931c12f-f75d-4489-a088-2b18bc23b367', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you access form data submitted via a POST request in Flask?', N'Junior', N'You access form data through the ''request.form'' object, which acts like a dictionary. It allows you to retrieve values submitted by HTML form fields by using the ''get'' method with the name of the input field.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16bb6ddc-4e0b-4931-a64f-2b197da0f022', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is Java Reflection API?', N'Intern', N'Reflection API in Java is used to manipulate class and its members which include fields, methods, constructor, etc. at runtime. The java.lang.Class class provides many methods that can be used to get metadata, examine and change the run time behavior of a class. There are 3 ways to get the instance of Class class. * forName() method of Class class * getClass() method of Object class * the .class syntax 1. forName() method: * is used to load the class dynamically. * returns the instance of Class class. * It should be used if you know the fully qualified name of class.This cannot be used for primitive types. Output 2. getClass() method: It returns the instance of Class class. It should be used if you know the type. Moreover, it can be used with primitives. Output 3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e45b466-4886-4d14-89a8-2b1c15cc251d', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are basic types in TypeScript?', N'Fresher', N'Basic types are the fundamental data types used to define variables, such as number, string, boolean, null, undefined, and void. These provide a way to enforce what kind of data can be stored in a variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e17c0820-500c-4a76-8e17-2b1d5a5c27b3', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between a class and an interface?', N'Fresher', N'A class is an object-oriented blueprint that can have both properties and method implementations, and it creates instances at runtime. An interface is a purely conceptual construct used only for type checking and disappears entirely after the code is transpiled to JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62c91415-7741-41bf-9a58-2b1d5ba14a85', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle technical debt while maintaining feature delivery velocity?', N'Senior', N'I treat technical debt as a backlog item, prioritizing it based on the risk it poses to stability and development speed. I advocate for allocating a fixed percentage of each sprint to refactoring and debt reduction to ensure long-term system health alongside product growth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37fc5c5b-3333-4a7c-8c20-2b1dd872c680', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Why is it generally better to use Echo''s logger middleware rather than implementing your own from scratch?', N'Middle', N'Echo''s built-in logger middleware is optimized for performance and provides standard logging formats, including latency, method, path, and status codes. Using the built-in version reduces overhead and ensures consistent observability across the application stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c543732-975d-49f0-bb98-2b1f021c13d8', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the trade-off between feature velocity and technical debt in a fast-paced engineering environment?', N'Middle', N'Prioritizing feature velocity allows for faster market feedback and revenue generation, but accumulating excessive technical debt eventually slows down future development due to increased complexity and bugs. The approach is to consciously incur debt for non-critical paths while enforcing strict quality standards on core infrastructure, periodically scheduling refactoring to pay down debt.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'130bd0d8-473f-4f91-9b43-2b201fe00b29', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket''s ''catchers'' system improve error handling?', N'Middle', N'Catchers allow you to define global or route-specific handlers for specific HTTP error status codes. This centralizes error reporting and response formatting, ensuring that clients receive consistent and meaningful error messages even when things go wrong deep in the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bdeff7d-7ad9-47b8-840d-2b213776f0dd', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you get the metadata of a module', N'Fresher', N'You can use the import.meta object which is a meta-property exposing context-specific meta data to a JavaScript module. It contains information about the current module, such as the module''s URL. In browsers, you might get different meta data than NodeJS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'480f5a65-66b6-481d-a84a-2b23bf191ebe', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do you optimize Svelte performance for large lists?', N'Middle', N'You should use the keyed each block, which helps Svelte track items by a unique identifier rather than their index. This ensures that when the list changes, Svelte performs minimal DOM updates instead of re-rendering the entire list.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'326d8100-26a3-4508-a72f-2b2584bc0787', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why might you choose not to use jQuery in a modern web project?', N'Fresher', N'Modern browsers have significantly improved their native JavaScript support, making many jQuery features available as built-in methods. For small projects or performance-critical applications, avoiding the overhead of the jQuery library can lead to faster load times and fewer dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
