INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3490a984-4cf5-4d82-ac48-2b295a15b76e', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why is it generally recommended to use an auto-incrementing integer as a primary key in InnoDB?', N'Middle', N'Since InnoDB uses a clustered index, inserting rows with an auto-incrementing key ensures that new records are appended to the end of the B-Tree. This prevents page fragmentation and unnecessary data movement that would occur if random values like UUIDs were used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4136cd74-90f8-42a8-a35f-2b299b1afa19', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain how the ''this'' keyword binding differs between arrow functions and traditional functions, and why this matters for architectural design.', N'Senior', N'Traditional functions have dynamic ''this'' binding determined by the call site, while arrow functions capture the ''this'' value from the surrounding lexical scope. This distinction is critical for maintaining correct context in asynchronous callbacks and complex object-oriented design patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a0f2703-b165-4406-bdb0-2b2b63e7a8fc', N'075b8862-431c-4678-9767-f55359758a4a', N'Why should you avoid using arrow functions in lifecycle hooks or methods in the Options API?', N'Middle', N'Arrow functions lexically bind the ''this'' context, meaning they cannot access the component instance''s properties, methods, or data. Using standard functions ensures that ''this'' is correctly bound to the Vue instance, allowing access to the reactive state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1410740-28b1-453e-baee-2b2c9b5194be', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between DROP and TRUNCATE?', N'Intern', N'DROP removes the entire table structure and all its data from the database. TRUNCATE removes all rows from a table but keeps the table structure intact for future use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1aa78405-f0e1-484b-a541-2b2e269848ac', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI facilitate automatic documentation, and what is its impact on frontend integration?', N'Middle', N'FastAPI automatically generates OpenAPI schemas based on Pydantic models and type hints, which are then used to render interactive Swagger UI or ReDoc documentation. This significantly reduces the overhead for frontend teams, as they can rely on the documentation to understand API contracts without manual updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'410a7176-5206-4ec8-a239-2b2f69776ec5', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the difference between a Route and a Controller in Symfony?', N'Junior', N'A Route maps a specific URL pattern to a specific controller action, acting as the entry point for requests. The Controller then contains the logic to process the request and return a response, such as rendering a template or returning JSON.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfca1cc1-98d1-4275-bfd1-2b3233f169c5', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle CSS?', N'Intern', N'Remix treats CSS as a first-class citizen, allowing you to link stylesheets to specific routes. These styles are only loaded when the user visits that route, which helps keep the initial page bundle small.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca2c0ff2-b40b-432d-a786-2b373186c935', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go’s approach to error handling impact long-term maintenance of large codebases?', N'Senior', N'By treating errors as explicit values rather than using exceptions, Go forces developers to handle failure states at every step. While this can lead to verbose code, it makes the control flow explicit and avoids the unpredictable hidden state changes often associated with deep exception stacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01c35cc9-f4de-49c1-bfa6-2b3974bfe335', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is a parameter matcher in SvelteKit?', N'Intern', N'A parameter matcher is a utility used to validate dynamic route segments. It ensures that a URL parameter matches a specific pattern, such as ensuring an ID is only numeric, before the page is rendered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9206615-c41f-4f23-9435-2b403e3734fc', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the advantage of using ''msgspec'' with Litestar?', N'Intern', N'Msgspec is a high-performance library for data validation and serialization. Litestar integrates deeply with it to provide significantly faster processing speeds compared to traditional validation libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c7198b7-c05c-4b79-9f86-2b45afabc7fe', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How do you perform unit testing on an Axum handler without starting a network server?', N'Middle', N'Since handlers are simply functions that take extractors or arguments and return responses, you can test them by manually invoking the function and passing in mock request data. This bypasses the network stack, making tests significantly faster and more isolated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a142b32-7e5a-4fc4-b466-2b4750101781', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does the Node.js event loop prioritize microtasks versus macrotasks?', N'Senior', N'After each phase of the event loop, Node.js processes the microtask queue, which includes promises and process.nextTick. Macrotasks, such as timers and I/O callbacks, are processed in their respective phases. If the microtask queue is too large, it can starve the event loop of macrotask execution, leading to delayed I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'626d7e2a-9f1b-43fd-b5e2-2b47fd569df6', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of the ''refresh_interval'' setting in Elasticsearch, and how does it affect performance?', N'Middle', N'The refresh_interval determines how often the changes made to the index are made visible to search. Increasing this interval improves indexing performance by reducing the frequency of segment creation, but it introduces a longer delay before new documents become searchable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a5419d7-502d-44a5-aa1a-2b492a6b50ed', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach debugging a production issue that is difficult to reproduce in a local environment?', N'Middle', N'I start by gathering comprehensive telemetry, logs, and distributed traces to identify the environmental differences between production and local setups. I then attempt to isolate the issue by creating a canary deployment or a controlled environment that mimics the production configuration. This allows me to observe the state of the system in real-time without risking the stability of the main service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b5f4436-144a-48a1-a4ff-2b4aa8ba6a6a', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the ''DDAU'' pattern in Ember?', N'Intern', N'DDAU stands for Data Down, Actions Up. This architectural pattern means that data flows down from parent components to child components via properties, while child components communicate changes back to the parent by sending actions or events upward.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1784c3ac-30dd-42c9-b4b3-2b4bf3d82714', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why is Rocket''s configuration system considered flexible?', N'Middle', N'Rocket''s configuration system allows for hierarchical settings that can be defined in files or via environment variables. This flexibility enables developers to easily manage different environments, such as development, staging, and production, without changing the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
