INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93375dc2-f574-4fa3-acc2-2b50f67a4fb1', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is Tailwind CSS and how does it differ from traditional CSS frameworks?', N'Fresher', N'Tailwind CSS is a utility-first CSS framework that provides low-level utility classes to build designs directly in your markup. Unlike traditional frameworks like Bootstrap that provide pre-designed components like buttons or navbars, Tailwind focuses on composition using small, single-purpose classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77849b21-a233-4fbf-8d37-2b51a139fe19', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the significance of the ''Future'' and ''Stream'' types in Dart''s asynchronous architecture.', N'Middle', N'Futures represent a single value or error that will be available at some point in the future. Streams represent a sequence of asynchronous events, allowing the program to respond to multiple data arrivals over time, which is essential for handling user input or continuous data flows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
