INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bae2d589-c4e0-480c-9a77-2b5438ca59f6', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What are React Server Components and how do they differ from Client Components?', N'Intern', N'Server Components are rendered exclusively on the server, allowing them to access backend resources like databases directly without sending extra JavaScript to the client. Client Components are rendered on the client and are used for interactive elements that require browser-specific features like state or event listeners.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'309d4daf-654d-4aef-bf33-2b576e537f24', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the difference between decorators and plugins in Fastify?', N'Junior', N'Decorators are used to add custom properties or methods to the Fastify instance, request, or reply objects to make them accessible throughout the application. Plugins, on the other hand, are the primary mechanism for organizing the application structure, allowing you to load code, define routes, and set up configurations in a modular way.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d355699-2776-4a1d-accc-2b585cb6285b', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the function of the ''helmet'' middleware in an Express application?', N'Middle', N'Helmet is a security middleware that sets various HTTP response headers, such as Content-Security-Policy, X-Frame-Options, and HSTS. It helps protect the application from common web vulnerabilities like cross-site scripting, clickjacking, and protocol downgrade attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b459df0-8de5-4589-839c-2b58e954132f', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of database normalization?', N'Intern', N'Database normalization is the process of organizing data to reduce redundancy and improve data integrity. It involves dividing a database into two or more tables and defining relationships between them to ensure that data is stored logically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
