INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd921521-c01e-423f-b146-2b5c56058f93', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are the trade-offs of using a complex Webpack configuration?', N'Middle', N'While a complex configuration offers fine-grained control and optimization, it significantly increases maintenance effort and makes debugging build issues harder. Over-engineered configurations can also lead to slower build times and make it difficult for new team members to understand the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71490d12-e268-404e-9768-2b5cd69077f7', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a closure and how does JavaScript implement it internally?', N'Intern', N'A closure is a function that retains a reference to its lexical environment (the scope in which it was defined) even after that outer scope has finished executing. In V8, when a function is created, the engine attaches a hidden [[Environment]] slot pointing to the current scope''s environment record. As long as the inner function is reachable, the garbage collector keeps the outer environment record alive. Practically: closures "close over" variables — not values. They hold a live reference to the variable binding, so mutations to that variable are visible inside the closure. Real-World Use Case: The Redux store implementation (createStore) uses closures to encapsulate currentState, currentReducer, and listeners.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43b2f38d-e17e-4815-896a-2b5f1edf76ed', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the difference between ''fold'' and ''reduce''?', N'Junior', N'''Reduce'' performs a binary operation on elements of a collection to combine them into a single value, assuming the collection is non-empty. ''Fold'' is similar but requires an explicit starting value, which makes it safer to use with empty collections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aea6aaae-7e5a-411a-a94d-2b611c63d098', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does the 400KB item size limit influence data modeling?', N'Senior', N'The item limit forces designers to decompose large entities into multiple items or store heavy data in external object storage. It necessitates careful planning of attribute sizes to avoid runtime errors when application data grows unexpectedly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a67f40d-51bf-4790-8b09-2b623ae47fc0', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you handle database migrations in a system that requires zero-downtime deployments?', N'Middle', N'Migrations must be additive and backward-compatible, typically involving a multi-step process where the application is updated to support both old and new schema versions. This allows the application to transition smoothly without requiring a hard cutover that causes downtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1aa25dfd-6244-407e-8010-2b62c943ab5a', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is it important for a developer to understand yield points?', N'Intern', N'Yield points are the specific locations in code where a fiber pauses its execution to let others run. If a fiber enters a long-running, non-yielding computation, it can starve other fibers of execution time, leading to performance issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7521e59c-25d0-43f8-95a0-2b69ab36de56', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the benefit of Hono''s ''Hono-RPC'' feature in a monorepo architecture?', N'Middle', N'Hono-RPC allows a frontend to import the type definitions directly from the backend to ensure end-to-end type safety. This eliminates the need for manual API documentation or third-party schema generators, as the client automatically understands the request and response shapes defined on the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10980c45-6941-4872-b7cd-2b6af3026b38', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the benefit of using Astro for a documentation or blog site?', N'Junior', N'Astro excels at these types of sites because they are primarily content-driven rather than application-driven. By eliminating unnecessary JavaScript, Astro ensures fast load times and better search engine optimization, which are critical for content-heavy pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'094b6547-f2fe-4c1e-99a5-2b6e6ed4cc42', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach observability in a distributed system to ensure you can debug production issues?', N'Senior', N'I implement a strategy based on the three pillars: logs for granular context, metrics for system health monitoring, and distributed tracing to follow requests across service boundaries. I ensure all services emit structured telemetry with common correlation IDs to enable end-to-end visibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41d5a9d4-7b77-49e0-81cc-2b700d9a0435', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the trade-offs of using Unsafe or foreign function interfaces in performance-critical code?', N'Senior', N'These allow direct off-heap memory access and interaction with native libraries, bypassing JVM safety checks to achieve near-C performance. However, they introduce significant risks, including segmentation faults, memory leaks, and the loss of portability, as these operations are not protected by the JVM''s type system or GC.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4772a99-575f-4e46-b083-2b75bea581b4', N'954a0331-deff-4399-b588-96f39fec001d', N'What is a service worker and its role in Angular?', N'Intern', N'A service worker is a script that runs in the web browser and manages caching for an application. Starting from 5.0.0 version, Angular ships with a service worker implementation. Angular service worker is designed to optimize the end user experience of using an application over a slow or unreliable network connection, while also minimizing the risks of serving outdated content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d89b0a2-2c83-41a6-9415-2b75f4c5e98f', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the onMount hook?', N'Intern', N'The onMount hook is a helper function that runs a piece of code exactly once after the component has been initially rendered and attached to the DOM. It is primarily used for initialization tasks like fetching data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca683690-0cdd-4ad7-8aa9-2b7860bab52f', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle form submissions compared to standard HTML forms?', N'Fresher', N'Remix enhances standard HTML forms to work without JavaScript enabled. It intercepts the form submission, sends it to the server action, and updates the page state seamlessly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe9c7c73-c15b-4522-8713-2b7a03425379', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is it recommended to avoid heavy cross-partition queries in Cassandra?', N'Senior', N'Cassandra is optimized for partition-key-based lookups; cross-partition queries force the coordinator to query every node in the cluster. This results in massive scatter-gather overhead, high network utilization, and poor performance that does not scale with the cluster size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5593cd1-03b6-4bd8-be1a-2b7a421a65cf', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between Authentication and Authorization?', N'Fresher', N'Authentication is the process of verifying who a user is, such as validating credentials. Authorization is the process of determining what an authenticated user is allowed to do or access within the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a59edcd2-42ec-4b69-bba0-2b7adf0929b3', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why is it important to use ''preload'' in Ecto queries?', N'Middle', N'Preloading is necessary to solve the N+1 query problem by fetching associated data in a separate, optimized query rather than loading it iteratively. Failing to use it correctly can lead to significant performance degradation when traversing complex relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a8a5e27-b296-4ba8-85ae-2b7b108586fa', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Can Litestar return non-JSON responses?', N'Fresher', N'Yes, Litestar can return various types of responses including HTML, plain text, or custom file responses. The framework determines the response type based on the return type annotation or the explicit Response class used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1248e50c-e446-40c7-a917-2b7c1dbe868d', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the purpose of the ''final'' keyword in Dart?', N'Fresher', N'The ''final'' keyword is used to declare a variable that can be set only once. Once a value is assigned to a final variable, it cannot be changed, though the internal state of the object it refers to might still be mutable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99b322bf-47f5-4ff8-8930-2b7ef1dc5e8d', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why does SolidJS not require a dependency array like useEffect?', N'Middle', N'SolidJS uses automatic dependency tracking. When a reactive primitive is accessed inside an effect, the system automatically registers that effect as a subscriber, removing the need for manual dependency lists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
