INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3c2a60c-5093-4af8-878a-2b8272f7bf82', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of the ''static'' keyword when used with local variables?', N'Intern', N'When a local variable is declared as static, its lifetime extends throughout the entire duration of the program rather than being destroyed when the function returns. It retains its value between multiple function calls, though it remains scoped only to the function where it was defined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'987c4a4e-bc7f-4577-b28e-2b854ad5817b', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What are the advantages of using a ''Sidecar'' pattern?', N'Middle', N'The sidecar pattern allows you to attach a helper container to your main application container to handle tasks like logging, monitoring, or networking. This keeps the main application code clean and focused on business logic while delegating infrastructure-related tasks to the sidecar.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d5ad018-c36f-4989-8fed-2b858e31fa3e', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of a ''Directive'' in Angular?', N'Middle', N'Directives are classes that add behavior or transform the appearance of DOM elements. Structural directives change the DOM structure, while attribute directives change the behavior or appearance of an existing element without altering the DOM structure itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1958e7b4-83fb-478e-8b0d-2b86a383e72b', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the Shadow DOM and why is it important in Lit?', N'Fresher', N'The Shadow DOM provides encapsulation for web components by keeping their styles and DOM structure separate from the rest of the page. It ensures that styles defined inside a Lit component do not leak out and affect other elements on the site.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'533948c3-aa28-4890-a249-2b878d7f8297', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Compare the architectural benefits of using R''s ''data.table'' versus base R data frames for large-scale data manipulation.', N'Senior', N'data.table optimizes memory usage through in-place modification and internal memory mapping, whereas base R data frames often trigger full object copies during subsetting or assignment. This makes data.table significantly more scalable for datasets that exceed RAM capacity or require frequent updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'631393f2-9668-40db-b35d-2b87d4154bb6', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the purpose of subscribing to the store?', N'Fresher', N'Subscribing to the store allows you to listen for changes to the state. Whenever an action is dispatched and the state is updated, the subscriber function is called, allowing the UI to re-render or perform specific tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3890a3ce-41ae-4cea-a6e3-2b88817e8f55', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the function of the ''runtimeChunk'' configuration option?', N'Senior', N'The runtimeChunk extracts the Webpack boilerplate code, which manages module loading and resolution, into a separate file. This is crucial for long-term caching, as it prevents the runtime code from changing whenever any part of the application code changes, keeping the main bundle''s hash stable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1290d11c-44e2-4be6-a68a-2b8ae83a87d4', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why is it important to include an alt attribute on an image tag?', N'Junior', N'The alt attribute provides a text alternative for images if they fail to load or are accessed by users with visual impairments using screen readers. It also helps search engines index the content of the image, which contributes to better search engine optimization. It is a fundamental practice for ensuring web content is accessible to all users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2493ad6-335f-47aa-898f-2b8f6cc42cdb', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'When would you prefer a JVM-based deployment over a Native Executable in Quarkus?', N'Middle', N'A JVM-based deployment is preferred when build times are critical, or when the application heavily relies on dynamic features that are difficult to configure for native images. The JVM also provides better JIT optimization for long-running applications that benefit from runtime profile-guided optimizations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f973ea63-3ce1-440d-84b1-2b8fead6e06a', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of ''signals'' in Flask, and what are the trade-offs of using them?', N'Middle', N'Signals allow your application to emit events that other parts of the app can subscribe to, facilitating loose coupling between components. However, they can make the application flow harder to trace and debug because the execution logic becomes non-linear. They should be used sparingly for cross-cutting concerns like logging or analytics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a59c2da3-028a-4687-b2cd-2b8ffd9ef9b9', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does the ''Options pattern'' support hot-reloading of configurations without restarting the application?', N'Senior', N'By using IOptionsMonitor or IOptionsSnapshot, the application can react to changes in configuration files in real-time. This allows for dynamic adjustments to application behavior, such as toggling feature flags or updating log levels, without the need for a full process recycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17228597-4175-480c-b2c4-2b95a1f43234', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the difference between BodyParser and direct body access in Fiber?', N'Junior', N'BodyParser is a helper method that automatically binds the request body into a provided struct based on the content type, such as JSON or form data. Accessing the body directly requires manual parsing and validation, which is more error-prone.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8e0d92d-78c6-4f54-b813-2b95a88f18a3', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the purpose of a staging environment in software development?', N'Junior', N'A staging environment acts as a mirror of the production environment where new features or fixes are tested before the final release. This allows developers to catch configuration issues or bugs that only appear in a production-like setting without affecting actual users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99a60900-747f-4857-b0a8-2b9aeb5921e6', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the primary language used to write Phoenix applications?', N'Intern', N'Phoenix applications are written in Elixir. Elixir is a functional, concurrent language that runs on the Erlang Virtual Machine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cb2ad86-be47-4e8f-bcd3-2b9afd258d97', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why is Svelte''s ''derived'' store considered a functional reactive programming primitive?', N'Senior', N'Derived stores allow for the creation of new state based on the dependencies of other stores, automatically recalculating whenever those dependencies change. This maintains a declarative data flow where complex state transformations are memoized and updated lazily, minimizing redundant computations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0c0570d-4a71-4187-9b49-2b9cd9b118a3', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Describe the concept of ''Capacity Units'' and how they relate to request throttling.', N'Senior', N'Capacity units represent the throughput provisioned for read and write operations. If the actual request rate exceeds the provisioned capacity, DynamoDB throttles the excess requests to maintain system stability, potentially causing application-level errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e91a008-c4df-46d8-9fa2-2b9e363c7604', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Why is message visibility timeout important in queue systems?', N'Middle', N'The visibility timeout prevents other consumers from reading a message while it is currently being processed by one worker. If the worker fails to delete the message within this period, it becomes visible again, allowing another worker to pick it up.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0988ea81-a6d9-4963-8a6e-2b9f4b5fbcd4', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you design a rate-limiting strategy for a distributed system that must handle bursty traffic without dropping legitimate requests?', N'Senior', N'I would implement a distributed token bucket algorithm backed by a fast, centralized key-value store like Redis to maintain state across nodes. To mitigate latency, I would use a local cache for quotas with a background synchronization mechanism, allowing for a soft-limit approach where burst traffic is briefly buffered if the backend capacity permits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b991f37-e536-424c-be0b-2ba01f71dbfb', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Explain how DynamoDB''s Read/Write Capacity Units (RCU/WCU) map to performance.', N'Senior', N'RCUs and WCUs represent the throughput of the database, where one WCU is one 1KB write per second and one RCU is one 4KB eventually consistent read per second. They abstract the underlying hardware, allowing DynamoDB to scale automatically based on provisioned or on-demand throughput settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a76be2b-133d-4a3c-8cf0-2ba029e4a3d0', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono maintain architectural simplicity while supporting complex feature sets like multipart form handling or file uploads?', N'Senior', N'Hono delegates complex tasks to optional, specialized middleware modules rather than embedding them in the core framework. This modular design ensures that the core remains lightweight, while developers can selectively import only the functionality required for their application, keeping the deployment footprint optimized and easy to audit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b05cdff9-ba38-41ff-b15f-2ba222b309d6', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you check whether or not an array includes a particular value', N'Fresher', N'The Array#includes() method is used to determine whether an array includes a particular value among its entries by returning either true or false. Let''s see an example to find an element(numeric and string) within an array.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3390a43-d238-4279-b6db-2ba34f7e6900', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the significance of the ''Phoenix.Template'' compilation process.', N'Senior', N'Phoenix compiles templates into functions at compile-time rather than interpreting them at runtime. This leads to extremely fast rendering speeds and allows the compiler to catch errors in templates early in the development lifecycle, significantly improving both performance and developer productivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8f9de1d-9eec-49eb-9042-2ba475d0c0ec', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the role of the C++ ''One Definition Rule'' (ODR) in distributed system compilation?', N'Senior', N'The ODR mandates that a non-inline function or variable must have exactly one definition across the entire program. In large-scale systems, violating this rule leads to undefined behavior, which is often difficult to debug because it may manifest as inconsistent state or linker errors depending on how different translation units are merged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecb5c531-d96b-41f8-9daa-2ba678b5b76a', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik manage component rendering?', N'Fresher', N'Qwik renders components lazily based on user interaction or state changes. Because of its resumable architecture, it only re-renders the specific parts of the DOM that are affected by state updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'894fcb5d-df2e-497f-aa68-2ba8d58b594f', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Why would you choose MongoDB over a relational database?', N'Junior', N'MongoDB is often chosen for projects with rapidly changing data requirements, large volumes of unstructured data, or needs for horizontal scalability. Its flexible document model allows for faster iteration and development compared to rigid relational schemas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a50cddd6-1644-4fb8-94f8-2badd03b734a', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does the ''interning'' of strings affect Python''s memory management?', N'Senior', N'Python interns certain strings to ensure that multiple references to the same string literal point to the same object in memory. This optimization reduces memory footprint and enables faster comparisons, as the interpreter can use pointer identity instead of character-by-character equality checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e57d8c72-7c49-4ad9-b360-2baf9538448c', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the difference between synchronous and asynchronous endpoints in FastAPI?', N'Fresher', N'Synchronous endpoints block the execution thread until the task is finished, which can lead to performance bottlenecks. Asynchronous endpoints allow the server to handle other incoming requests while waiting for I/O-bound tasks to complete, significantly improving concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb05199a-7a37-48e5-94e0-2bb02b63f0a4', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi manage middleware scope?', N'Middle', N'Middleware in Chi can be applied globally to the entire router, or locally to specific route groups. This scoped application ensures that expensive middleware, like authentication, is only executed for the routes that require it, optimizing overall request latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
