INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28a6dcf7-4db6-4a97-9c5d-2bb5a52354c6', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How do you manage hover, focus, and other states in Tailwind?', N'Junior', N'Tailwind uses state modifiers, which are prefixes added to utility classes to apply styles conditionally. For example, prepending hover: to a class ensures that the style is only applied when the user interacts with the element by hovering over it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7371fa7-1f7f-472a-b488-2bbb21f71fbc', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are the trade-offs of using protocol-oriented programming with existential types versus generic constraints?', N'Senior', N'Generic constraints allow the compiler to generate specialized code at compile-time, enabling optimization and inlining. Existential types, conversely, require type erasure, which forces dynamic dispatch and heap allocation, potentially introducing performance overhead compared to compile-time polymorphism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
