INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23049490-147d-470b-978d-2bbf2134e383', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Describe the difference between Astro''s ''Static'' and ''Server'' output modes in terms of deployment infrastructure.', N'Senior', N'Static mode generates pre-rendered HTML files at build time, suitable for CDN or simple object storage deployment. Server mode requires a Node.js or edge runtime environment to generate pages on-demand, allowing for dynamic data fetching per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e084a18d-a9c6-4588-9df7-2bc2711a2147', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why to use Express.js?', N'Fresher', N'Express.js is a Node.js web application framework that provides broad features for building web and mobile applications. It is used to build a single page, multipage, and hybrid web application. Features of Express.js: * Fast Server-Side Development: The features of node js help express saving a lot of time. * Middleware: Middleware is a request handler that has access to the application''s request-response cycle. * Routing: It refers to how an application''s endpoint''s URLs respond to client requests. * Templating: It provides templating engines to build dynamic content on the web pages by creating HTML templates on the server. * Debugging: Express makes it easier as it identifies the exact part where bugs are.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a29f1da-5cde-4821-a5d1-2bc3b94835af', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What are the trade-offs between using CSS-in-JS versus utility-first CSS frameworks in a large-scale micro-frontend architecture?', N'Senior', N'CSS-in-JS offers high encapsulation and dynamic theming but introduces a runtime overhead for style injection and potential bundle size increases. Utility-first frameworks provide consistent design systems and smaller final CSS footprints but require strict adherence to naming conventions and can lead to bloated HTML markup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4050329a-14f3-47b8-ab0f-2bc3e6d86b7f', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro manage asset optimization?', N'Middle', N'Astro automatically processes assets like images and CSS files, providing features such as automatic image optimization and minification. It treats assets as part of the build pipeline, ensuring they are hashed for cache busting and served efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c40466b0-b60c-4415-afc3-2bc40552a24c', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact differ from React in terms of file size?', N'Intern', N'Preact is designed to be extremely small, typically weighing in at around 3 kilobytes compared to React''s much larger bundle size. This reduction is achieved by removing features that are rarely used or by implementing them more efficiently to keep the library compact.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41ef7c7c-f753-41da-bb71-2bc997551692', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between vertical scaling and horizontal scaling for a high-traffic database?', N'Middle', N'Vertical scaling is simpler to implement but has a hard ceiling defined by hardware limits and often results in downtime during upgrades. Horizontal scaling provides near-infinite capacity and better fault tolerance but adds complexity in data sharding, load balancing, and maintaining consistency across multiple nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6266aa4a-449a-46ec-82e5-2bcb7d5b0f43', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS facilitate distributed tracing in a microservices environment?', N'Senior', N'NestJS can integrate with distributed tracing headers (like W3C Trace Context) through custom interceptors or middleware that propagate correlation IDs across service boundaries. By capturing these headers in the request pipeline, developers can reconstruct the flow of requests across multiple services in systems like Jaeger or Zipkin.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79b10964-8e39-407a-89cf-2bcbb6614587', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the role of Pydantic in FastAPI?', N'Intern', N'Pydantic is used for data validation and settings management. It enforces type hints at runtime and provides user-friendly errors when data is invalid, making it the backbone of request and response handling in FastAPI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'625efc5d-45b3-4043-8007-2bd015365f57', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between an arrow function and a regular function?', N'Junior', N'Arrow functions have a shorter syntax and do not have their own ''this'' context; they inherit ''this'' from the surrounding scope. Regular functions have their own ''this'' value based on how they are called.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5529f760-2bfb-491b-82d8-2bd1a7bf0c3d', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between a table scan and an index seek?', N'Junior', N'A table scan occurs when the database reads every row in a table to find matching data, which is slow for large datasets. An index seek uses a B-tree structure to jump directly to the relevant data, making it significantly faster for queries filtering by indexed columns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a0ac216-9379-43f4-a778-2bd2aa184c34', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing an API, what are the trade-offs between versioning via URI paths versus versioning via custom headers?', N'Senior', N'URI path versioning is highly visible and caches easily through standard proxy configurations, but it can lead to resource bloat. Header-based versioning keeps URIs clean and allows for more nuanced request routing, but it can be harder to debug and may not be supported by all intermediate caching layers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe4b7fc8-9e44-469d-b026-2bd440c2d84e', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Explain the concept of idempotency in API design and why it is important.', N'Middle', N'An idempotent API method ensures that making the same request multiple times produces the same result as a single request. This is critical for network reliability because it allows clients to safely retry requests that may have timed out or failed without causing unintended side effects like duplicate transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6ebbdda-6b4f-42ac-9220-2bd5ce999cf1', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is logical indexing in R?', N'Junior', N'Logical indexing is the practice of subsetting an object using a vector of TRUE and FALSE values. R will return only the elements that correspond to the TRUE positions in the index vector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed13c8a3-6a2d-49bc-b375-2bd8f8af49ce', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why should you avoid ''guessing'' at a fix during a system outage?', N'Intern', N'Guessing at solutions, often called ''shotgun debugging,'' can lead to unintended side effects and further instability in the system. It is safer to rely on data, logs, and logical deduction to understand the cause before applying a change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ad4781c-0a3a-4d94-97ba-2bdb420a7ded', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the impact of a ''Non-Indexed Query'' on a large collection?', N'Senior', N'A non-indexed query forces a full collection scan, where every document in the collection must be loaded and examined. In large datasets, this consumes massive amounts of RAM and disk I/O, leading to severe performance degradation and potential server lockup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffe8da7a-f412-463d-80fc-2bdbe4695ff6', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What are the impacts of object serialization on cache performance?', N'Senior', N'Serialization overhead is a major factor in cache latency, especially with complex objects. Using efficient binary formats like Protobuf or specialized memory-mapped storage can significantly reduce the CPU cycles needed to store and retrieve data from the cache.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'470491a7-d668-42d1-91c4-2bde28514bda', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Why might you choose to use Symbol over a String as a hash key?', N'Middle', N'Symbols are immutable and unique identifiers that are memory-efficient because they are not recreated. Using symbols as hash keys improves performance and memory usage compared to strings, which are mutable and allocated separately each time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
