INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06069a02-83ae-4e42-8c1d-2be801bc3cb7', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the primary difference between a replica set and a sharded cluster in MongoDB?', N'Middle', N'A replica set provides high availability and data redundancy by maintaining multiple copies of data across different nodes. A sharded cluster is used for horizontal scaling, distributing data across multiple replica sets to handle large datasets and high throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e232ca50-7dd8-4375-bd38-2be85d2cf690', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the benefit of using MDX in Astro?', N'Junior', N'MDX allows you to use JSX components inside your Markdown files. This gives you the ability to write rich, interactive content using the simplicity of Markdown while leveraging the power of reusable frontend components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ee45a0f-c0d0-4359-996d-2be923faa98b', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of the ''res.send()'' vs ''res.json()'' method?', N'Junior', N'res.send() can send various types of data, such as a buffer, a string, or an object, and automatically sets the content type based on the input. res.json() explicitly sends a JSON response and always sets the Content-Type header to application/json.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'830ca512-ee7d-431e-b79e-2beaeec272ea', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the role of ''Dispatchers'' in Kotlin coroutines for resource management.', N'Senior', N'Dispatchers determine which thread or thread pool a coroutine runs on, allowing for efficient offloading of blocking I/O tasks from the main thread to background workers. Proper use of dispatchers is essential for responsive system design, ensuring that CPU-bound and I/O-bound tasks do not starve each other of resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'899127a4-51d2-4ec6-a929-2beb58635a39', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is avoiding blocking syscalls important in the context of the Go runtime scheduler?', N'Senior', N'When a goroutine performs a blocking syscall, the runtime may block the underlying OS thread, potentially exhausting the thread pool if not managed correctly. While the scheduler attempts to spawn new threads to maintain concurrency, frequent blocking syscalls increase overhead and reduce the efficiency of the M:N scheduling model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efb0bdb7-b9b1-4216-96aa-2bec7a8d72f1', N'954a0331-deff-4399-b588-96f39fec001d', N'How does Angular handle multi-level lazy loading, and what are the primary performance considerations?', N'Senior', N'Angular uses the router to split the application into chunks that are loaded on demand, minimizing the initial payload size. The primary performance consideration is the strategy used for pre-loading, as aggressive pre-loading improves perceived navigation speed but increases bandwidth usage for the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3a39c70-17e4-4450-887c-2bf1dd71962b', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How do you handle the trade-offs between strong consistency and high availability in a distributed system?', N'Senior', N'According to the CAP theorem, one must choose between consistency and availability during a network partition. In practice, systems often employ eventual consistency through techniques like read-repair or hinted handoff to maintain high availability while accepting that nodes may temporarily reflect stale data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'990ac168-5997-46d1-b10b-2bf3c7e0f18f', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is an Elixir Process in Phoenix?', N'Intern', N'An Elixir process is a lightweight, isolated unit of execution. In Phoenix, each web request is handled within its own process, which ensures that a failure in one request does not affect others.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e008a1c-089b-4415-93a1-2bf478d84ec1', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does the Swift compiler leverage ''Whole Module Optimization'' to improve performance?', N'Senior', N'Whole Module Optimization allows the compiler to analyze all files within a module simultaneously rather than individually. This enables cross-module inlining, dead code elimination, and more aggressive specialization of generic functions, significantly reducing runtime overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
