INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37fac663-cb4e-4b39-8c28-2bf731a178d2', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does an API Gateway improve the security posture of a backend system?', N'Middle', N'An API Gateway acts as a centralized entry point that handles authentication, authorization, and rate limiting before requests reach internal services. By terminating TLS and filtering malicious traffic at the edge, it shields internal infrastructure from direct exposure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
