INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2f6b61b-a605-475f-89db-2bf9608f26e1', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of the ''Database Router'' in Django, and when is it appropriate to use?', N'Senior', N'Database routers allow you to direct queries to different database instances, such as separating reads and writes or sharding data across multiple servers. It is a powerful tool for scaling database I/O, but it introduces significant complexity in ensuring data consistency and managing cross-database transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'850e94d6-3725-4f8c-a048-2bfbe5889653', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of ''F'' expressions in the Django ORM?', N'Middle', N'F expressions allow you to perform database-level operations on field values without fetching them into Python memory. This is essential for preventing race conditions, such as incrementing a counter, because the update is performed atomically by the database engine based on the current value at the time of execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
