INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56ad1956-c6fa-447b-94bd-2c1d2d78739c', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the trade-offs between using unbuffered and buffered channels for inter-goroutine communication?', N'Senior', N'Unbuffered channels provide strong synchronization guarantees by forcing the sender and receiver to rendezvous, which can lead to latency spikes if the consumer is slow. Buffered channels decouple producers and consumers, improving throughput and resilience against bursts, but they introduce the risk of hidden memory pressure if buffers grow indefinitely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'020c671f-81bb-4c42-9c9c-2c1eba37f643', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the difference between Server Components and Client Components in the App Router, and why does this distinction exist?', N'Senior', N'Server Components run exclusively on the server, allowing access to backend resources and reducing the client-side bundle size. Client Components are hydrated on the client, enabling interactivity and browser-specific APIs, with the boundary determining where code execution and data fetching occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6b184c3-a61e-484b-95b1-2c20e7989142', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does backpressure help maintain system stability in a messaging architecture?', N'Middle', N'Backpressure is a feedback mechanism that allows a consumer to signal to the producer or broker that it is overwhelmed. By slowing down the rate of message ingestion, the system prevents memory exhaustion and avoids cascading failures across services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32e021d6-d81b-4f39-8775-2c24ca4d7e8d', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does the C++ compiler handle name lookup in the context of template instantiation?', N'Senior', N'C++ uses two-phase lookup: the first phase checks for non-dependent names in the template definition, and the second phase, performed during instantiation, checks for dependent names. This mechanism ensures that template logic remains consistent with its environment while allowing for specialization and argument-dependent lookup at the point of use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f87b239-367a-4e65-a3b9-2c24f9324cd6', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does write-behind caching affect the durability of the system?', N'Senior', N'Write-behind caching improves system responsiveness but introduces a window of vulnerability between the cache update and the database write. If the cache node crashes during this window, the pending updates may be lost, necessitating robust journaling or replication mechanisms to ensure data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72adf626-2acf-471e-85d4-2c261f34bd78', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery normalize the ''event'' object across different browsers?', N'Middle', N'jQuery creates a cross-browser compatible event object that wraps the native event, ensuring that properties like target, currentTarget, and preventDefault work consistently everywhere. This eliminates the need for developers to write manual checks for browser-specific event standards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c144928b-fc43-429b-9f88-2c26568a50c2', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is the order of middleware registration significant in Fiber?', N'Middle', N'Middleware in Fiber is executed in the order it is registered. This is important because downstream middleware or handlers depend on the data or state modified by upstream middleware, such as authentication headers being validated before the main handler is reached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eaf67133-565f-4bc6-8c07-2c29d0e83611', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What role does the ''Asset Pipeline'' or ''Webpacker/Propshaft'' play in modern Rails deployment?', N'Senior', N'These tools handle the compilation, minification, and fingerprinting of front-end assets to improve page load speeds and enable cache busting. They abstract away complex build processes, ensuring that the application serves optimized, versioned assets in production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee16f669-6b7a-4c3f-885a-2c2bf35008e7', N'075b8862-431c-4678-9767-f55359758a4a', N'Explain the significance of the virtual DOM in Vue.', N'Middle', N'The virtual DOM is a lightweight JavaScript representation of the actual DOM. It allows Vue to calculate the minimum number of changes needed to update the UI, reducing expensive direct browser reflows and repaints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb09b28b-8a2b-432c-8346-2c2cb37851c2', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the directive Hook Arguments?', N'Intern', N'All the hooks have el, binding, and vnode as arguments. Along with that, update and componentUpdated hooks expose oldVnode, to differentiate between the older value passed and the newer value. Below are the arguments passed to the hooks, 1. el: The element the directive is bound to and it can be used to directly manipulate the DOM. 2. binding: An object containing the following properties. 1. name: The name of the directive, without the v- prefix. 2. value: The value passed to the directive. For example in v-my-directive="1 + 1", the value would be 2. 3. oldValue: The previous value, only available in update and componentUpdated. It is available whether or not the value has changed. 4. expression: The expression of the binding as a string.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed21f4b3-7acb-4b03-9869-2c2d02e82fcc', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why is Chi often preferred over large frameworks?', N'Fresher', N'Developers often prefer Chi because it is a minimalist router rather than a full-featured framework. It gives developers the flexibility to choose their own libraries for database access, validation, and serialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
