INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7df30c9-bf0c-428f-bded-2c32e3431951', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the ''Hydration'' process in Nuxt, and what are the common causes of hydration mismatches?', N'Senior', N'Hydration is the process where client-side JavaScript attaches to the server-rendered DOM to make it interactive. Mismatches occur when the server-rendered HTML differs from the initial client-side render, often caused by non-deterministic data like random numbers, timestamps, or client-only logic being rendered during SSR.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'622d84cf-980f-4af6-94c9-2c33f36b8f81', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What does the term ''referential integrity'' mean?', N'Junior', N'Referential integrity is a rule that ensures relationships between tables remain consistent. It prevents actions that would leave orphaned records, such as deleting a parent record that still has active child records linked to it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
