INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f00c46d0-488c-4825-b9b9-2c3ac970bbc7', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Compare vertical and horizontal scaling in the context of NoSQL.', N'Middle', N'Vertical scaling involves increasing the resources of a single server, such as CPU or RAM, while horizontal scaling involves adding more servers to the database cluster. NoSQL databases are designed primarily for horizontal scaling, providing a more cost-effective way to manage massive datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
