INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e59c87e-ec69-4ee4-925a-2c46df5064df', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are the common causes of memory leaks in C?', N'Middle', N'Memory leaks typically occur when dynamically allocated memory is no longer reachable by the program because the pointer to that memory was overwritten or lost before the memory was freed. They also happen when a program fails to call free on allocated memory before the program terminates or the pointer goes out of scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
