INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79089ccf-6fc6-4d89-83aa-2c48c4d7b131', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you break down a complex, large-scale engineering problem into manageable parts?', N'Intern', N'I approach large problems by decomposing them into smaller, independent sub-tasks or modules. I prioritize these tasks based on their dependencies and impact, ensuring that each smaller piece is clearly defined before I attempt to tackle the next.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05bd7692-fa43-4332-9d9b-2c4ab5837fb8', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is type narrowing?', N'Junior', N'Type narrowing is the process of moving from a broader type to a more specific type within a conditional block. TypeScript uses control flow analysis to understand which type a variable is based on checks like typeof or instanceOf.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'783eedf5-9c07-4c8f-947a-2c4b92a8251f', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How can you improve the performance of an Express application that handles high-concurrency requests?', N'Middle', N'Performance can be improved by using clustering to utilize multiple CPU cores, implementing caching strategies like Redis for frequent data, and offloading heavy computational tasks to worker threads or background queues. Additionally, utilizing compression middleware reduces payload sizes for faster network transmission.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'368deb34-3547-4b01-9f85-2c4caf93c646', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the significance of the $ symbol in Qwik''s API?', N'Senior', N'The $ symbol serves as a marker for the Qwik optimizer, indicating that the associated code is a candidate for lazy loading. It tells the compiler to extract the function into a separate chunk that can be lazily imported by the Qwik loader on demand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9caa9f1-ea97-4416-873d-2c4d32b799b0', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS architecture promote modularity and testability compared to a flat Express structure?', N'Senior', N'NestJS enforces a modular architecture using dependency injection, which decouples components and facilitates easier unit testing by allowing the injection of mock dependencies. This structure promotes the separation of concerns by organizing logic into providers, controllers, and modules, preventing the spaghetti code often found in large-scale Express applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a241f274-31cb-4c3a-8ff1-2c4f225b3369', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does the HTTP/2 multiplexing feature improve web performance?', N'Senior', N'HTTP/2 multiplexing allows multiple requests and responses to be sent concurrently over a single TCP connection, eliminating the ''head-of-line blocking'' issue found in HTTP/1.1. This reduces latency by removing the need for multiple parallel connections and better utilizes available network bandwidth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26733922-0e44-484d-ab17-2c5122291204', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of Middleware in Laravel?', N'Intern', N'Middleware acts as a bridge between a request and a response. It provides a convenient mechanism for inspecting and filtering HTTP requests entering your application, such as checking if a user is authenticated before allowing them to access a specific route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb3beac0-10ea-43d9-8f32-2c52f9261d79', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''any'' type, and why should you avoid using it?', N'Junior', N'The ''any'' type disables all type checking for a variable, effectively turning it back into standard JavaScript. Overusing it defeats the purpose of using TypeScript because it hides potential bugs and makes the code less predictable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'815d97c6-3f7f-4a8b-b11a-2c54e947f4d4', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you prioritize tasks when you have multiple assignments with similar deadlines?', N'Fresher', N'I prioritize by assessing the business impact and dependencies of each task, focusing on those that are critical for the team''s progress or have external blockers. I also consider the effort required for each, aiming to complete smaller tasks to gain momentum or tackling the most complex one first to mitigate risk. Maintaining a clear list and communicating priorities with my lead ensures alignment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ab09dba-3c38-41e9-9786-2c550d04fe00', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the role of the nil object in Ruby?', N'Intern', N'The nil object represents the absence of a value or a null reference. It is an instance of the NilClass and is commonly used to signify that a variable has not been initialized or a method has no result to return.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be1b2eda-e48a-4b45-b5c8-2c57b6a94daa', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is a secondary node in a replica set?', N'Intern', N'A secondary node maintains a copy of the primary node''s data set by applying operations from the primary''s oplog. Secondary nodes can be used to serve read traffic, which helps improve the read scalability of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
