INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4f45755-2579-4e47-b24f-2c6239208907', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is the use of jQuery considered a potential anti-pattern in modern SPA frameworks like React or Vue?', N'Middle', N'Modern frameworks rely on a virtual DOM and declarative data binding to manage UI state, whereas jQuery directly mutates the real DOM. Mixing these approaches causes synchronization issues, where jQuery''s manual changes are overwritten by the framework''s reconciliation process, leading to unpredictable application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b6e6b3f-afb1-46a2-990b-2c633e3f07e0', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between ''index signatures'' and ''mapped types'' regarding property access safety?', N'Senior', N'Index signatures provide a broad, catch-all type for dynamic property access, which is often unsafe. Mapped types allow for a more precise, declarative approach to defining properties, ensuring that access to keys is restricted to a known set of allowed values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18947187-4094-42a2-b3c3-2c63a57671a4', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the ''doc_values'' structure improve performance?', N'Middle', N'Doc values are an on-disk, column-oriented storage format that allows for efficient field data access during sorting and aggregations. By keeping this data on disk rather than entirely in the heap, Elasticsearch can handle larger datasets without running out of memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
