INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd90df2b4-bdf2-4fc9-a858-2c64b14e6ee8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between ''const'' and ''let''?', N'Junior', N'''let'' allows you to reassign the variable to a new value later. ''const'' is used for variables that should not be reassigned, though it does not make objects or arrays immutable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a26a99ba-8d35-4566-bcce-2c68e33d417d', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the role of observability in modern troubleshooting compared to traditional monitoring?', N'Middle', N'Monitoring tells you when a system is broken, while observability allows you to understand why it is broken by providing visibility into the internal state of the system. Observability relies on logs, metrics, and distributed traces to create a holistic view of the system. This allows developers to debug complex, distributed problems that cannot be solved by simple health checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d113638-9e29-4910-9886-2c6d8fce03a2', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are the performance considerations when using high numbers of ''Doctrine'' entities in a single Unit of Work?', N'Senior', N'Managing a massive number of entities in a single request can lead to significant memory consumption due to the Identity Map pattern. To mitigate this, developers should use iterate() for large datasets or explicitly clear the EntityManager to free up memory once objects have been processed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f83db77-de35-4298-b678-2c6dac844c00', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of ''UploadFile'' in FastAPI?', N'Middle', N'UploadFile is a specialized FastAPI class for handling file uploads that stores files in memory up to a certain size limit and then buffers them to disk. This approach prevents memory exhaustion when processing large files while providing an easy-to-use interface for reading the file content asynchronously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61ce96c5-241f-4036-a6e5-2c6e6e77892f', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Explain the concept of ''Sharding'' and why it is used.', N'Middle', N'Sharding is a horizontal partitioning technique that splits a large dataset across multiple database instances to distribute the load. It is used to overcome the limitations of a single server''s storage capacity and throughput, enabling linear scalability as the application grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8824d620-2846-41be-893a-2c6f81adc759', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How can you implement cross-cutting concerns like caching or logging across the application without polluting business logic?', N'Senior', N'These concerns can be implemented using Decorator patterns, MediatR pipeline behaviors, or custom action filters. These approaches intercept calls to services or controllers, allowing developers to inject logic before or after execution while keeping the core business classes clean and focused on their primary responsibilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f503f93-ecb6-4622-808f-2c76a98de18f', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does the MongoDB WiredTiger storage engine implement document-level concurrency control?', N'Senior', N'WiredTiger uses optimistic concurrency control with multi-version concurrency control (MVCC) at the document level. By maintaining multiple versions of a document in memory, it allows multiple readers and writers to access the data without blocking, resolving conflicts only at the point of commit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f20000a5-da34-4465-8543-2c7792806a85', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Why is it generally discouraged to use ''async void'' in C#?', N'Middle', N'Async void methods cannot be awaited, which means the caller has no way to catch exceptions thrown within the method or track its completion. This can lead to application crashes or unpredictable behavior because exceptions in async void methods are typically raised directly on the synchronization context, bypassing standard exception handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
