INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'242f3cd9-62e7-4896-a560-2c7ecc7613e2', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket enforce security?', N'Junior', N'Rocket enforces security by design, such as preventing common issues like parameter injection by using type-safe data extraction. It also provides built-in mechanisms for CSRF protection and secure cookie handling to help developers build safer applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc265b9c-b444-467a-93e7-2c7facbcf83f', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why should you use ''fastify-plugin'' for your modules?', N'Junior', N'Using the fastify-plugin utility prevents the plugin from being encapsulated, meaning any decorators or hooks it adds will be available in the parent scope. This is essential when you want to share functionality across different parts of your application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
