INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71933967-9d4d-429e-ac87-2c8513d8656c', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does Node.js handle errors?', N'Intern', N'Node.js typically handles errors using the error-first callback pattern, where the first argument of a callback function is reserved for an error object. In modern code, errors are often handled using try-catch blocks in combination with asynchronous operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'012f86c6-7c47-4515-87db-2c8691b87e9c', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Why is partitioning data by time (time-series) considered a potential anti-pattern for sharding?', N'Senior', N'Partitioning by time often creates a hot spot because all new data is written to the most recent partition. This prevents effective load balancing across the cluster and can lead to performance degradation as the newest shard becomes overloaded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a10efd3-8b99-4e86-b25d-2c870ef27ac1', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What does the term ACID stand for in database transactions?', N'Intern', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably and maintain data integrity even in the event of errors or system failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a675654-f1f0-4516-9350-2c89f6213820', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the ''Idempotency'' requirement for compensating transactions in a Saga?', N'Senior', N'Compensating transactions must be idempotent because they may be executed multiple times in the event of retries due to network failure. If a compensation operation is not idempotent, repeated executions could lead to incorrect data states or double-processing of business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cba4a25-c313-4984-a9d5-2c8c3546dee1', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you optimize a system that is experiencing high latency due to excessive database locking?', N'Senior', N'I would investigate the transaction isolation levels and see if they can be relaxed, or switch to optimistic concurrency control to reduce lock contention. Additionally, I would look for ways to optimize query performance or refactor transactions to be shorter, thereby reducing the duration that locks are held.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
