INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0871fe4-e043-4b09-9038-2c919e7cac07', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach evaluating the logs of a distributed system to trace a single request''s path?', N'Middle', N'I rely on distributed tracing tools that inject a unique correlation ID into every request header. By aggregating logs from all involved services based on this ID, I can reconstruct the entire flow of the request. This allows me to pinpoint exactly which service or network hop introduced the latency or error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
