INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfca6e5d-ce0c-4382-8ddc-2c984adef110', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle CORS (Cross-Origin Resource Sharing)?', N'Middle', N'Gin does not provide a built-in CORS implementation, requiring the use of third-party middleware. This middleware intercepts the OPTIONS request, adds the necessary Access-Control-Allow headers to the response, and ensures the browser permits the subsequent cross-origin call.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'207460d6-412f-4aa2-b3c8-2c9a43375662', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the architectural role of the Coordinator node in a Cassandra cluster?', N'Senior', N'The coordinator node receives a client request, determines which nodes own the requested data based on the partition key, and forwards the request to the appropriate replicas. It then aggregates the responses from the replicas and returns the final result to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a222881-efe6-42ca-913e-2c9beecdf266', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is C''s setjmp/longjmp mechanism considered dangerous for resource management?', N'Senior', N'Longjmp performs a non-local jump that bypasses the normal function return sequence, meaning local variables and automatic resources are not cleaned up. This can lead to resource leaks, such as failure to close file handles or release memory, because the stack unwinding process does not execute cleanup logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc762843-d5ef-46e4-b9b7-2c9e35582b71', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between a struct and a class in Swift, and when should you prefer one over the other?', N'Junior', N'Structs are value types, meaning they are copied when assigned or passed, while classes are reference types that share a single instance. You should prefer structs by default for data modeling because they are safer and more efficient due to thread safety and memory management. Use classes only when you specifically need features like inheritance or identity, such as when managing shared state or specific object lifecycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e14f3b84-6fb1-4329-a726-2c9f829f2f4b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the architectural difference between the microtask and macrotask queues in the event loop.', N'Senior', N'Microtasks, such as promise resolutions, have higher priority and are processed immediately after the current operation finishes, before yielding to the UI thread. Macrotasks, like timers or I/O callbacks, are processed in subsequent event loop iterations. This distinction ensures that high-priority asynchronous updates do not block the browser''s rendering cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07e0ad9f-750a-487b-af83-2ca4b01ad4ea', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of an Assembly in C#?', N'Intern', N'An assembly is the primary building block of a .NET application, acting as the unit of deployment, versioning, and security. It is usually a compiled file, such as a DLL or an EXE, containing code and metadata.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e53d5eb6-e8ce-46ed-a8f6-2ca5b68bdb9d', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the impact of Preact''s render cycle on the browser''s main thread?', N'Senior', N'Preact''s render cycle is synchronous, meaning it will block the main thread for the duration of the component tree update. For highly complex UIs, developers must optimize their component structure to ensure that the render cycle remains short enough to prevent dropped frames.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'186c7c7f-983b-42aa-84b9-2ca7723ccd1a', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is middleware in the context of the Gin framework?', N'Intern', N'Middleware in Gin consists of functions that are executed during the lifecycle of an HTTP request, before or after the main handler. These are commonly used for tasks like logging, authentication, recovery from panics, and modifying request or response headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'887d89b3-5f1c-49d8-8a28-2cab842e0b8f', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the primary benefit of Rust''s ownership model compared to garbage collection?', N'Middle', N'The ownership model eliminates the need for a runtime garbage collector by enforcing memory safety at compile time. This leads to more predictable performance and avoids the non-deterministic pauses associated with garbage collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f71299dd-9fc0-4d60-a75a-2cab9e802f32', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is an Optimistic Concurrency Control?', N'Intern', N'Optimistic concurrency assumes that multiple transactions can complete without interfering with each other. Instead of locking data, the system checks for conflicts only at the time of commit; if a conflict exists, the transaction is aborted and retried.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fed4b8fb-f1ae-40c4-8082-2cb44c33dc8e', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the benefits and drawbacks of using GIN (Generalized Inverted Index) versus GiST (Generalized Search Tree) indexes?', N'Senior', N'GIN is optimized for cases where multiple keys can be mapped to a single index entry, such as full-text search or JSONB, offering faster lookup speeds. GiST is more flexible and supports a wider range of data types like geometric shapes, but it is generally slower for lookups compared to GIN.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab8f62ae-70e9-483c-ae47-2cb604d48113', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between a singular and a plural route in Rails?', N'Intern', N'A plural route represents a collection of resources, such as a list of users, and typically maps to index and create actions. A singular resource route represents a single entity, often used when there is only one instance of that resource for a given context, such as a user''s profile.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f180367-6f1a-4f50-8f15-2cb9735b6c0e', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does the choice of consistency level (e.g., synchronous replication vs. asynchronous replication) affect broker availability?', N'Senior', N'Synchronous replication ensures high durability by waiting for multiple replicas to acknowledge a write, which increases latency and reduces availability if a follower fails. Asynchronous replication provides higher performance and availability but risks data loss if the leader fails before the write is replicated to followers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'351874d1-a5f7-4bf1-9b7a-2cbd285f2b52', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the primary purpose of a database index?', N'Intern', N'An index is a data structure that improves the speed of data retrieval operations on a database table. It functions similarly to an index in a book, allowing the database engine to find specific rows without scanning the entire table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
