INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c3c23f8-b102-491e-a4ef-2cbfa488f60b', N'954a0331-deff-4399-b588-96f39fec001d', N'What is two-way binding and how do you implement it in Angular?', N'Fresher', N'Two-way binding in Angular synchronizes data between the data model and the view in both directions. Any changes in the data model automatically reflect in the view and vice versa. Implementation in Angular Angular primarily uses two-way binding through the [(ngModel)] directive, leveraging the FormsModule or ReactiveFormsModule. Using [(ngModel)] and FormsModule 1. Module Setup: Import the FormsModule in your Angular module. 2. Input Binding: Use [(ngModel)] in the view to enable two-way binding with an input element. 3. Data Model: Define the associated property in the component. This setup ensures that any changes to the input element are reflected in the name property and vice versa.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff8985da-3223-41f8-ab63-2cc353d9e211', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the difference between ''worst-case'' and ''best-case'' estimation?', N'Fresher', N'Best-case estimation assumes everything goes perfectly with no interruptions or technical hurdles, while worst-case accounts for significant roadblocks and external dependencies. A realistic estimate typically falls somewhere in between, weighted toward the more conservative side.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af1bc3e7-ab86-4ad6-94f4-2cc4a0bbf48d', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the difference between a GET and POST request?', N'Junior', N'A GET request is intended to retrieve data from a server without changing its state, while a POST request is used to send data to the server to create or update a resource. Generally, GET requests should be idempotent, whereas POST requests are not.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
