INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90c9a261-2530-4f8e-8d8e-2cc5c863b5d3', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a Progressive Web App (PWA)?', N'Intern', N'A Progressive Web App (PWA) is a highly optimized website built with modern web technologies that delivers a native-like app experience directly through a web browser. It bridges the gap between the reach of traditional websites and the advanced functionality of platform-specific mobile or desktop applications It uses modern web APIs and progressive enhancement strategies to deliver an app-like experience — including offline support, push notifications, and home-screen installation — directly through a browser, without an app store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6a709d0-664f-441b-964d-2cc62540b93a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What are the trade-offs of using serverless functions versus containerized services?', N'Middle', N'Serverless functions offer excellent cost-efficiency for event-driven, sporadic workloads and eliminate infrastructure management, but they can suffer from ''cold starts'' and vendor lock-in. Containerized services provide more control over the runtime environment and consistent performance, but require more operational overhead for cluster management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
