INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51012dee-0afd-4ecf-96be-2cde08c61a58', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why is Elasticsearch considered a NoSQL database?', N'Intern', N'Elasticsearch is considered a NoSQL database because it does not use a fixed schema or traditional SQL for data manipulation. It is designed to handle unstructured data through flexible JSON documents, prioritizing horizontal scalability and search speed over complex relational joins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e9bd052-55f7-4ada-9ea1-2cdf59580a23', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the function of ''url_for'' in Flask?', N'Fresher', N'The ''url_for'' function is used to build URLs dynamically for specific functions. This is preferred over hardcoding URLs because it ensures that if you change a URL route in the future, all links in your application update automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
