INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcadc48b-139a-4e56-aa23-2ce03db73435', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the role of the ''main'' package in Go?', N'Fresher', N'The main package is a special package that tells the Go compiler to build the code as an executable program rather than a shared library. It must contain a function called main, which serves as the entry point for the application execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01061fa3-d8f0-4bc1-bf58-2ce1e5f4dfa1', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Can you explain why memory usage is significantly lower in Quarkus compared to traditional frameworks?', N'Senior', N'By eliminating dynamic class loading and reducing the need for metadata scanning at runtime, Quarkus significantly decreases the heap size required to start and run the application. Native executables further reduce memory usage by removing the overhead of the JVM and its associated garbage collection metadata.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc6d8875-69b1-493e-8ae6-2ce1f56b2c7b', N'075b8862-431c-4678-9767-f55359758a4a', N'What is two-way data binding in Vue?', N'Junior', N'Two-way data binding is implemented primarily via the v-model directive. It synchronizes the state of a form input or component with a data property, ensuring that changes in the UI automatically update the data and vice versa.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f83fa864-2cfb-40df-ae44-2ce22faf75ef', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the role of ''tsconfig.json'' in a project?', N'Middle', N'The ''tsconfig.json'' file defines the root of the project and specifies the compiler options and files to be included or excluded. It acts as the central configuration point that determines how the TypeScript compiler behaves and what level of strictness or environment support is applied.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b48a111-6cb2-4963-a2e9-2ce2bbeddc1b', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the ''N+1 Query Problem'' and how is it typically addressed?', N'Senior', N'The N+1 problem occurs when an application executes one query to fetch parent records and then N individual queries to fetch related child records. This is addressed by using JOINs or eager loading techniques to retrieve all necessary data in a single batch query, reducing round-trip latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'603e07b7-bfec-417b-9233-2ce49862b845', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Why is Quarkus considered ''Kubernetes-native''?', N'Junior', N'Quarkus is optimized for containerized environments by minimizing memory usage and startup time, which are critical for scaling in Kubernetes. It also provides automatic generation of Kubernetes manifests and health check endpoints to facilitate smoother deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67cb9ef4-0c71-4045-acec-2ce4b9e0660d', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the role of the request context in Chi?', N'Intern', N'The request context is used to store and retrieve data associated with a specific request, such as URL parameters or authentication tokens. Chi uses the standard context package to pass this information through the middleware chain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d0630e4-1828-4552-adbc-2ce67c6972f6', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin''s ''sealed classes'' hierarchy enforce exhaustiveness in ''when'' expressions?', N'Senior', N'Sealed classes restrict the class hierarchy to a known set of subclasses defined within the same package or file. The compiler uses this closed-set knowledge to verify that all possible subclasses are covered in a ''when'' expression, eliminating the need for an ''else'' branch and improving type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
