INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'639a678e-b186-4028-9631-2cefc5497531', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the benefit of using ''Provide'' in Litestar for dependency management?', N'Middle', N'The ''Provide'' utility allows for the declaration of injectable dependencies that are automatically resolved and passed to route handlers. This promotes loose coupling and makes it significantly easier to swap implementation details for testing or different environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14ddd352-d00a-4d25-aa94-2cf1a8ed11be', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Why Use Eloquent Over Raw SQL?', N'Fresher', N'1. Readability: Using Eloquent, queries are easier to read and understand than raw SQL. This enhances code maintainability. 2. Portability: Models and the relationships between them make it simple to move code between different database systems (e.g., from MySQL to SQLite or PostgreSQL). 3. Scalability: Eloquent provides a simple and clean way to define relationships between tables, ensuring the code scales effectively. 4. Refactoring: If the database schema changes, often only the model needs to be updated. Eloquent abstracts these changes from the rest of the codebase. Key Eloquent Features 1. Eloquent Models - Basic CRUD Operations: Eloquent makes it simple to create, read, update, and delete records using the familiar object-oriented syntax.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7eda077a-a188-4bc9-a4f7-2cf392d00db8', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript''s ''strict'' flag affect the development experience?', N'Middle', N'The ''strict'' flag is a master switch that enables a suite of strict type-checking options, such as strict null checks and no implicit any. It drastically improves the development experience by catching potential runtime errors early and making the codebase more predictable and self-documenting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1eef477e-db78-4686-b83a-2cf4e24d0fcb', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you evaluate the scalability of a system design?', N'Intern', N'Scalability is evaluated by determining if the system can handle increased load by adding more resources. You look for potential bottlenecks in the architecture and decide if the system should scale vertically, by adding more power, or horizontally, by adding more nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b9faa8f-779d-4289-baba-2cfb4b2e4e6b', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the MVC architectural pattern used in AdonisJS?', N'Fresher', N'MVC stands for Model-View-Controller. It separates the application into three components: the Model handles data logic and database interaction, the View manages the user interface, and the Controller processes incoming requests and orchestrates the interaction between the Model and the View.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0f95597-58ee-4098-933b-2cfd196919c0', N'a2838158-7305-480a-b22b-4dc35776b400', N'What are the trade-offs of using a microservices architecture compared to a monolith?', N'Middle', N'Microservices offer improved scalability, independent deployment, and fault isolation, but introduce significant complexity in networking, distributed transactions, and operational monitoring. A monolith is simpler to develop and deploy initially but becomes difficult to maintain and scale as the codebase grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6dcbb899-db5b-4534-97b0-2cfdcc863f22', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between innerHTML and textContent?', N'Fresher', N'innerHTML and textContent are both properties used to get or set the content of an HTML element, but they serve different purposes. innerHTML returns or sets the HTML markup contained within the element, which means it can parse and render HTML tags. On the other hand, textContent returns or sets the text content of the element, ignoring any HTML tags and rendering them as plain text. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f64ee06-2522-4add-94c6-2cfe62eb4699', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is an exception in Java?', N'Intern', N'An exception is an event that occurs during the execution of a program that disrupts the normal flow of instructions. Java uses an exception handling mechanism to manage these errors gracefully instead of crashing the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5dd7571-1bfb-47de-904a-2cffb18657fe', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the difference between Preact and React regarding Synthetic Events?', N'Fresher', N'React uses a custom Synthetic Event system to normalize events across browsers. Preact uses standard browser events directly, which helps keep the library size smaller while still ensuring consistent behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f4c0e8f-589f-40c9-8ebc-2cffbccebe0f', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the function of the DynamoDB Accelerator (DAX) and when should it be used?', N'Senior', N'DAX is a write-through, in-memory cache for DynamoDB that reduces response times from milliseconds to microseconds for read-heavy workloads. It should be used when the application requires extreme performance or when the same data is read repeatedly. It adds architectural complexity and cost, so it is best reserved for latency-sensitive applications that exceed standard DynamoDB performance capabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64f6ee12-7e8f-493d-9d8d-2d01891204b0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between ''let'' and ''var''?', N'Junior', N'''var'' is function-scoped and can be redeclared, which often leads to bugs. ''let'' is block-scoped, meaning it only exists within the curly braces where it is defined, and it prevents accidental redeclaration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3e6ebcc-5b40-4e4e-929a-2d019d7dcb84', N'954a0331-deff-4399-b588-96f39fec001d', N'When is it appropriate to use an ''AppInitializer'' in Angular, and what are the risks involved?', N'Senior', N'AppInitializer is used to run logic or fetch data before the application fully bootstraps, such as loading user settings or config files. The risk is that it blocks the application startup, potentially leading to a poor user experience if the initialization tasks take too long or fail, so it should be used sparingly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9355da31-06ee-4522-a6f2-2d028202790f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the ternary operator and how is it used?', N'Intern', N'The ternary operator is a shorthand for an if-else statement in JavaScript. It takes three operands: a condition, a result for true, and a result for false. The syntax is condition ? expr1 : expr2. For example, let result = (a > b) ? ''a is greater'' : ''b is greater''; assigns ''a is greater'' to result if a is greater than b, otherwise it assigns ''b is greater''. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'406c226f-5068-44e1-91ff-2d033cd9da19', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Explain the architectural difference between Fastify''s plugin system and the middleware pattern found in Express.', N'Senior', N'Fastify uses a directed acyclic graph (DAG) based encapsulation model where each plugin creates a new context, inheriting the parent''s decorators and hooks. This provides strict isolation and deterministic loading order, unlike Express middleware which operates linearly on a shared request-response object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e1c5b49-51e3-4c06-862d-2d0370fc93ce', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it important to isolate a bug before attempting to fix it?', N'Junior', N'Isolating a bug ensures that you are fixing the root cause rather than just masking the symptoms. This prevents the fix from introducing unintended side effects in other parts of the application and ensures the solution is robust and verifiable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f3c7fca-2cc3-4886-9dbe-2d05806df784', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart handle memory management and garbage collection in a multi-isolate environment?', N'Senior', N'Each isolate maintains its own heap and garbage collector, allowing for independent memory management. This design eliminates contention during garbage collection cycles, as one isolate can perform GC without pausing the execution of other isolates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf4da5e0-d5d1-459e-8d33-2d06d5378694', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a promise?', N'Intern', N'A promise is an object that may produce a single value some time in the future with either a resolved value or a reason that it''s not resolved (for example, network error). It will be in one of the 3 possible states: fulfilled, rejected, or pending. Syntax: Example: Promises are used to handle asynchronous operations. They provide an alternative approach for callbacks by reducing the callback hell and writing the cleaner code. Promises have three states: 1. pending: initial state, neither fulfilled nor rejected. 2. fulfilled: meaning that the operation was completed successfully. 3. rejected: meaning that the operation failed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ce459b8-1505-41d7-8206-2d071a496851', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Does Chi support RESTful API design patterns?', N'Intern', N'Yes, Chi is excellent for RESTful APIs because it makes it simple to map HTTP methods like GET, POST, PUT, and DELETE to specific handler functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffeb8d4f-c488-4663-b1e6-2d081f749c44', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why do we use Webpack instead of just loading script tags?', N'Fresher', N'While script tags work for small projects, Webpack manages complex dependencies and improves load times through bundling and optimization. It also allows developers to use modern JavaScript features and modular code structures that aren''t natively supported by all browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccb42b63-2ff6-4d94-a968-2d097c106d9b', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is Ember Data, and what problem does it solve?', N'Junior', N'Ember Data is a library for managing application data. It provides a standardized way to fetch, update, and delete records from a server, handling the complexities of caching, normalization, and data persistence so developers don''t have to write manual network requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd0b84c2-825f-4f1b-87b8-2d09993346ce', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the ''mongos'' process?', N'Intern', N'The ''mongos'' process is a routing service for MongoDB sharded clusters. It directs queries from the application to the correct shard, abstracting the complexity of the sharded environment from the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c961c7f3-2490-4460-9ded-2d09c4936207', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Discuss the performance implications of Svelte''s transition and animation engine.', N'Senior', N'Svelte''s animation engine uses the web animation API directly and integrates with the framework''s reactive lifecycle. By handling animations at the component level and removing them from the DOM when finished, it prevents the layout thrashing often caused by framework-level animation managers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'661dadd6-2f43-4195-9ac1-2d09dc12a0c1', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the ''Covered Query'' concept in MongoDB?', N'Middle', N'A covered query is one where all the fields in the query are part of an index, and the index contains all the requested output fields. In this case, MongoDB returns the results directly from the index without ever having to access the actual documents on disk, significantly improving performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5234c21f-b3ea-4e9c-98c5-2d0aa5d5fa7d', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What does ''schema-less'' mean in the context of MongoDB?', N'Intern', N'Schema-less means that MongoDB does not require you to pre-define the structure or data types of your documents before inserting them. This flexibility allows developers to evolve their data models easily as application requirements change over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a20780c-2aae-467d-baac-2d0ad35f6a7f', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Explain Hono''s support for validation.', N'Fresher', N'Hono provides built-in validation middleware that checks incoming data against defined schemas. This helps ensure that the data received by the server meets the expected format before the business logic is executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11a2c3be-429f-435a-881b-2d0ad5b27455', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the role of a message queue in decoupling services, and what architectural benefit does it provide regarding traffic spikes?', N'Middle', N'A message queue acts as an intermediary buffer that allows services to communicate asynchronously, removing the need for them to be available simultaneously. This architecture allows the system to handle traffic spikes by queueing requests and processing them at a controlled rate, preventing downstream services from being overwhelmed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c498d32-7359-4647-bb35-2d0f944d48ed', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is a Phoenix Pipeline?', N'Intern', N'A pipeline is a sequence of plugs that are grouped together to handle common tasks for a group of routes. For example, a pipeline might handle authentication or set up the necessary headers for a browser request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'387f00a7-351b-4ef8-b27c-2d0fc2285d55', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the primary difference between a relational (SQL) and a non-relational (NoSQL) database?', N'Junior', N'Relational databases store data in structured tables with predefined schemas and use SQL for operations, making them ideal for complex queries. NoSQL databases are schema-less or have flexible schemas, allowing them to store unstructured or semi-structured data which scales horizontally more easily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8449a6fe-4534-4f3c-a0b3-2d11f683694f', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the advantage of using a Virtual DOM in a framework like Vue?', N'Middle', N'The Virtual DOM allows Vue to calculate the minimum number of changes required to update the real DOM, which is a computationally expensive operation. By batching these changes and applying them efficiently, Vue significantly improves performance in complex applications with frequent state updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'074cb415-c8fe-46fa-b878-2d1280e8e0b5', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle concurrent requests differently than a multi-threaded framework like Java Spring?', N'Senior', N'Express handles concurrency through an event loop and non-blocking I/O, allowing one process to handle thousands of connections simultaneously without the memory overhead of a thread-per-request model. Java Spring typically uses a thread pool, which is better for CPU-heavy workloads but less memory-efficient for high-concurrency I/O tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91e6759f-caee-4f57-b22d-2d13f6c056c2', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the concept of R''s search path.', N'Junior', N'The search path is the order in which R looks for objects and functions when they are called. It typically includes the global environment followed by any loaded packages and the base R packages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06921815-7a6f-4cb1-9f2f-2d15aae7d76b', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is it important to consider mailbox capacity in Actix actors?', N'Senior', N'Mailbox capacity dictates how many messages can be buffered before an actor is overwhelmed, which is critical for backpressure management. If the mailbox fills up, the system must decide whether to drop messages, return an error, or block, preventing uncontrolled memory growth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'560be3f9-9e7a-4b78-857a-2d1750d99b09', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the benefit of using an API Gateway in a microservices architecture?', N'Junior', N'An API Gateway acts as a single entry point for clients, handling cross-cutting concerns like authentication, rate limiting, and request routing. It simplifies client interactions and provides a centralized place to manage security and traffic policies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
