INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a22f85e4-4e9c-4cc0-b5d2-2d19a1930bf7', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the significance of the ''WeakMap'' data structure in memory management for long-lived applications?', N'Senior', N'WeakMap holds ''weak'' references to objects used as keys, meaning if no other references to the key object exist, it can be garbage collected. This is critical for preventing memory leaks when attaching metadata to objects that have an unpredictable lifecycle, as it avoids preventing the collector from reclaiming those objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02733bc7-4d67-4d9d-b14c-2d20b177dd02', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is an idempotent operation and why is it important in microservices?', N'Middle', N'An idempotent operation is one that can be executed multiple times without changing the result beyond the initial application. It is critical in distributed systems because network failures often lead to retries, and idempotency ensures that duplicate requests do not cause data corruption or unintended side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9504930-2120-44e1-bbd5-2d21841242ae', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s Just-In-Time (JIT) compilation differ from Ahead-Of-Time (AOT) compilation regarding development and production workflows?', N'Senior', N'JIT compilation is used during development to enable fast stateful hot reloads by compiling code on the fly. AOT compilation is used for production to generate optimized machine code, which provides faster startup times and predictable performance at the cost of longer build cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07beb3ac-6dc2-4b49-9382-2d2417cf0871', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is it important to test software before deploying it to production?', N'Intern', N'Testing identifies bugs and unintended behaviors that could cause system outages or data corruption. It ensures the software meets requirements and provides a stable experience for end-users, minimizing the risk of expensive post-deployment fixes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c2cf2ab-b612-4c6b-a670-2d2467039bbd', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the role of ''self'' in Ruby?', N'Intern', N'In Ruby, self serves as a "mirror" that reflects the current context. Depending on where it''s used, self can represent different objects. Here''s the breakdown: Self in Different Contexts 1. Instance Methods In this context, self refers to the instance of the object on which the method is called. Consider the following code: The output would be the object reference # . 2. Class Methods Within a class definition, self refers to the class itself. This is why you use self.method_name to define class methods. For instance: The output will be the class MyClass. 3. Method Invocation When a method is missing due to a typo or other reason, Ruby executes method_missing which can help handle such cases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7453f69-fffd-4c90-8085-2d24b9833e48', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How do Alpine''s ''x-transition'' modifiers improve the developer experience compared to CSS-only transitions?', N'Senior', N'x-transition provides a declarative way to handle complex enter and leave animations by applying CSS classes at specific lifecycle stages. This avoids the need for manual class toggling or complex JavaScript timing, which are prone to race conditions. It ensures smooth visual transitions by automatically waiting for the DOM to update before applying the necessary animation classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fc644a7-b559-4192-be4a-2d26866139df', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'An application is running slowly in production but worked fine in development. What is your first step to investigate?', N'Junior', N'I would start by comparing the production environment configuration against the development environment, specifically looking at resource allocation and data volume. Often, performance issues in production arise from larger datasets or lower infrastructure specifications that were not present during local testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdcd37dc-3d26-498f-977e-2d26e6aed33f', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the Startup class in ASP.NET Core?', N'Intern', N'The Startup class is the entry point for configuring the application. It is used to define the request handling pipeline through middleware and to register necessary services in the dependency injection container.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba3e0656-e570-493f-af2d-2d273ab4b937', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do I call a method defined in a base class from a derived class that overrides it?', N'Fresher', N'If you''re using new-style classes, use the built-in super() function: If you''re using classic classes: For a class definition such as class Derived(Base): ... you can call method meth() defined in Base (or one of Base''s base classes) as Base.meth(self,arguments). Here, Base.meth is an unbound method, so you need to provide the self argument.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e14b763-677e-4e35-8497-2d28bfa6f478', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the advantage of using the parent selector (&) in Sass?', N'Fresher', N'The ampersand character represents the parent selector in a nested rule. It is essential for targeting pseudo-classes like hover or state-specific classes without repeating the parent name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1236c8a7-9363-4a8a-ab79-2d2ab8672d2e', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is a computed property in Swift?', N'Fresher', N'A computed property does not store a value directly; instead, it provides a getter and an optional setter to calculate its value every time it is accessed. It is useful for deriving values from other properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcaaad90-cccf-4aec-9887-2d31fa2aaaf3', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Explain the purpose of ''Managed State'' in a Rocket application.', N'Middle', N'Managed State allows you to share data across different request handlers by injecting it into the application at startup. It is typically used for shared resources like database connection pools or configuration objects, ensuring thread-safe access throughout the application''s lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81d826dc-4be4-41aa-a01c-2d337ce31b1c', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the default rendering behavior of Astro?', N'Fresher', N'By default, Astro renders pages to static HTML during the build process. This provides excellent performance and SEO benefits because the browser receives a fully rendered page immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
