INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f92d172-63f0-4e11-b33a-2d34e7f71c65', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How do portals function within the SolidJS reactive graph?', N'Senior', N'Portals allow rendering DOM elements outside the component''s parent hierarchy while maintaining the reactive scope. This ensures that even if the DOM structure is detached, the portal''s content remains reactive to signals defined in the original parent scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36d73551-9550-4dc4-b814-2d3ef69e12da', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony manage session storage in a distributed, multi-node environment?', N'Senior', N'Symfony offloads session storage to external, high-performance backends like Redis or Memcached via the session handler interface. This ensures that session state is shared across all nodes, enabling horizontal scalability by making the application stateless from the server''s perspective.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29fb02de-822c-4dc1-af96-2d4137dd5236', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of the Change Buffer in InnoDB, and how does it optimize write operations?', N'Senior', N'The Change Buffer is a special data structure that caches changes to secondary index pages when those pages are not in the buffer pool. This allows MySQL to perform write operations as sequential updates rather than random disk I/O, merging these changes later when the pages are read into memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2c65661-b888-44c0-92ac-2d42147fb5b9', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How do you evaluate the trade-offs between horizontal and vertical scaling for a stateful database cluster?', N'Senior', N'Vertical scaling increases the capacity of existing nodes, which is simpler to manage but hits a hard hardware ceiling and creates a single point of failure. Horizontal scaling improves resilience and throughput through partitioning, but introduces significant complexity regarding data consistency, cross-shard joins, and network latency overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'148b30ce-ff87-4246-b225-2d442882ff05', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the purpose of Blueprints in Flask and when you should use them.', N'Middle', N'Blueprints are a way to organize a large Flask application into smaller, reusable components or modules. They allow you to group related routes, templates, and static files, which makes the codebase much easier to maintain as it grows. You should use them whenever your application becomes too large to fit into a single file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1975c69-c41f-4f4e-9cce-2d45a8f9f239', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you set up a project with Vue.js?', N'Fresher', N'To initialize a Vue.js project, utilize a package manager (npm or yarn) and the Vue CLI. This empowers you with tools like webpack and Babel, facilitates incremental adoption, and ensures best practices from the beginning. Steps for Project Setup 1. Install Vue CLI: Run the specified command in a terminal. - npm: npm install -g @vue/cli - Yarn: yarn global add @vue/cli 2. Create a Vue Project: Generate a new project using Vue CLI. Select a default preset or customize the setup based on the project''s requirements. After this, navigate into your project folder. 3. Project Structure: Vue CLI sets up the project with a recommended structure including public, src, and various configuration files. 4. Development Server: Boot up a local server to dynamically view project changes. 5.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62e74fe2-5865-4fe9-9f12-2d4b9b104a5b', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the purpose of ''Undo'' and ''Redo'' logs in crash recovery?', N'Senior', N'Redo logs ensure that committed transactions are not lost by re-applying their changes during restart, while Undo logs allow the system to roll back incomplete transactions. Together, they ensure that the database state is consistent with the committed transactions before resuming normal operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8317952-7bf8-4906-bde9-2d4c9d9773d0', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is database redundancy?', N'Intern', N'Redundancy occurs when the same piece of data is held in two separate places within a database. While sometimes used for backups, excessive redundancy leads to wasted storage space and inconsistency issues when updating information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec1b6cc7-7ad3-42fb-87c0-2d4e40043b66', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why is it generally discouraged to perform heavy computations inside the main rendering loop of a page?', N'Middle', N'Performing heavy computations blocks the event loop, which prevents the server from responding to the request efficiently and can increase the Time to First Byte. These operations should be offloaded to background jobs or performed asynchronously to keep the UI responsive and the server performant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9692530-6bfe-48c7-a6c5-2d4fefb4abea', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you describe various dependencies in angular application?', N'Fresher', N'The dependencies section of package.json with in an angular application can be divided as follow, 1. Angular packages: Angular core and optional modules; their package names begin @angular/. 2. Support packages: Third-party libraries that must be present for Angular apps to run. 3. Polyfill packages: Polyfills plug gaps in a browser''s JavaScript implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd55066ca-340d-40e1-81f3-2d5162d59f51', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle event binding?', N'Fresher', N'Preact uses standard browser event listeners, unlike React''s synthetic event system. This makes event handling more predictable and closer to how native HTML behaves in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0601f28-870e-44b8-9e72-2d52ead20e95', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are the trade-offs of using ''iframe'' for embedding third-party content?', N'Senior', N'Iframes provide a robust security boundary via the same-origin policy, protecting the parent document from the child. However, they are heavy on memory consumption, lack full styling control, and make communication between the parent and child complex, often requiring postMessage APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be03c231-fae7-4ade-99be-2d53c50b995d', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Ecto''s ''Queryable'' protocol enable composable database queries?', N'Senior', N'The Queryable protocol allows developers to build complex database queries incrementally by piping functions together. This composability makes it easy to create reusable query fragments, such as filters or orderings, which can be shared across different contexts while maintaining clean, readable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'187cd101-4b55-4d5f-8ecb-2d56451fed0c', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach the problem of data privacy compliance in a global system?', N'Senior', N'I implement data residency controls, such as regional sharding, to keep user data within required geographic boundaries. I also ensure that all data is encrypted at rest and in transit, and that access controls are governed by the principle of least privilege.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'848028a0-8c75-4cee-8a0b-2d56991fc0b5', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the aggregation framework?', N'Intern', N'The aggregation framework is a powerful tool in MongoDB used for data transformation and analysis. It allows users to process data through a pipeline of stages, such as filtering, grouping, and calculating values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
