INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b11cde0b-60a1-434d-be78-2d5b933478af', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What does it mean for a type to be ''Copy''?', N'Junior', N'A type is Copy if its value can be duplicated simply by copying its bits in memory. Simple types like integers and booleans are Copy, meaning they do not move ownership when assigned to a new variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbf1b426-0f90-4b2c-800f-2d61adea9c4f', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit''s ''Task'' controller simplify asynchronous data fetching?', N'Senior', N'The Task controller provides a declarative way to handle asynchronous data by mapping promise states directly to the rendering cycle. It manages loading, success, and error states automatically, reducing the amount of manual state-tracking logic inside components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'124da269-fb1b-4f40-a49e-2d6315ac09a9', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus support security?', N'Middle', N'Quarkus integrates with security providers like OIDC, JWT, and LDAP. It offers a declarative security model where you can enforce authentication and authorization via annotations on endpoints, abstracting the complexity of security protocol handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de58bc2c-753c-4f1a-86fb-2d637301480d', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How do you handle long-running background tasks in PHP?', N'Middle', N'PHP is not natively designed for long-running processes, so tasks are typically offloaded to a message queue system like RabbitMQ or Redis. A separate worker process consumes these tasks asynchronously, keeping the main request-response cycle fast. This decouples time-consuming operations from the user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15f56a0c-da73-41e1-9fbb-2d6415b2ca87', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is Hot Module Replacement?', N'Fresher', N'Hot Module Replacement is a feature that updates modules in the browser at runtime without requiring a full page refresh. This preserves the application state, making the development process much faster and more efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8760bfe4-dd47-4bc4-a126-2d6430903da3', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar''s design prioritize production readiness?', N'Middle', N'Litestar prioritizes production readiness through its focus on explicit configuration, strict type checking, and robust dependency injection. These features reduce hidden runtime errors and provide clear diagnostic information, making it easier to maintain and scale complex applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7dcb9361-53e7-4d69-8319-2d67ba228f92', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between <section> and <div>?', N'Fresher', N'The tag creates independent sections within a webpage having logically connected content. And the tag is an empty container specifying a division or a section. The Element According to the W3C specification, the tag means that the content inside this element is grouped. In other words, the content relates to a single theme. It must be an entry in the outline of the page. Example: The Element The element only represents its child elements and doesn''t have a special meaning. It can be used with the lang, title, and class attributes to add semantics that is common to a group of consecutive elements. This element can also be used in a tag and wrap groups of and elements. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02e9ea15-0974-4c15-8e17-2d699515d4ad', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How do Laravel Events and Listeners promote loose coupling?', N'Middle', N'Events and Listeners allow you to trigger actions without the sender needing to know about the subscribers. This decouples the core application logic from side effects, such as sending notifications or logging, making the system easier to extend.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f801ff8-bd1f-473b-a523-2d6a2e4d9ad9', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does a Content Security Policy (CSP) help prevent XSS attacks?', N'Middle', N'CSP is an HTTP response header that allows site administrators to restrict the resources, such as JavaScript or CSS, that a browser is allowed to load for a page. By whitelisting trusted sources, it effectively blocks malicious scripts from being executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85e7ae53-d16b-42cc-b4e2-2d6bfae76578', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What are the implications of escape analysis in the Go compiler?', N'Senior', N'Escape analysis determines whether a variable can be safely allocated on the stack rather than the heap. If the compiler proves a variable does not outlive its function scope, it allocates it on the stack, significantly reducing garbage collection overhead and improving cache locality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05273e81-7347-4bb1-b7bf-2d6f19bab879', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask handle static files, and what should be done differently in a production environment?', N'Middle', N'In development, Flask serves static files from the ''static'' folder automatically. In production, you should disable this behavior and serve static files directly through a web server like Nginx or a Content Delivery Network, as they are significantly more efficient at handling static content than a Python application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
