INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'525e9738-7d19-4065-951f-2d7030e4b43d', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery''s plugin architecture differ from modern ES modules in terms of dependency resolution?', N'Senior', N'jQuery plugins typically depend on the global jQuery object being present on the window, creating implicit dependencies that are hard to track. ES modules utilize explicit imports, allowing for static analysis, tree-shaking, and better management of dependency graphs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
