INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e94f6bd-d49f-488b-949c-2d7f516d225b', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a Deadlock in a database?', N'Intern', N'A deadlock occurs when two or more transactions are waiting for each other to release locks on resources. Because neither transaction can proceed, the database system must detect the deadlock and abort one of the transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
