INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5ffcc7f-38d3-47b0-a14c-2d805a8d5339', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is it important to use clear and descriptive naming conventions in code?', N'Fresher', N'Clear naming makes the code self-documenting, which significantly reduces the time required for other developers to understand the logic. It minimizes bugs caused by misunderstandings and makes the codebase much easier to maintain over the long term. When code is readable, it is less likely that someone will introduce errors while trying to modify it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09638d99-4d74-4871-9bec-2d807d9d847d', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s handling of ''Recover'' middleware contribute to system resilience?', N'Senior', N'The Recover middleware captures panics occurring within the request handler, preventing the entire application process from crashing. This ensures high availability, though it must be paired with comprehensive logging and alerting to ensure that the underlying issues are diagnosed and fixed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'623d617d-b8da-4abc-b0a0-2d84a95a5dce', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the conventions to be followed for the usage of switch case', N'Intern', N'Below are the list of conventions should be taken care, 1. The expression can be of type either number or string. 2. Duplicate values are not allowed for the expression. 3. The default statement is optional. If the expression passed to switch does not match with any case value then the statement within default case will be executed. 4. The break statement is used inside the switch to terminate a statement sequence. 5. The break statement is optional. But if it is omitted, the execution will continue on into the next case.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'818aeb6a-c4c4-4d09-b2ff-2d85e83fe5c7', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch handle horizontal scaling?', N'Intern', N'Elasticsearch scales horizontally by adding more nodes to the cluster. The system automatically redistributes shards across the new nodes to balance the load and increase total storage capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8879cb25-622b-4bab-8703-2d87f1d51df8', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is a major benefit of Axum''s modularity?', N'Junior', N'The modular design allows developers to compose complex applications from smaller, independent routers. This makes the code easier to test, maintain, and scale as the application grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d1a3396-a46f-4741-a628-2d8c7e56e6fc', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'When should you choose to denormalize your database schema?', N'Middle', N'Denormalization is used to improve read performance by reducing the number of costly JOIN operations. It is appropriate in read-heavy scenarios where the cost of maintaining data consistency during updates is outweighed by the performance gains of faster query execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f4bbb83-6ffc-46aa-82d0-2d8cbcd74530', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the impact of Route Groups on the URL structure and organization of a Next.js project?', N'Senior', N'Route Groups allow for logical grouping of files without affecting the URL path structure. They are primarily used for organizational purposes, such as separating authenticated and public route layouts, allowing developers to apply different layouts to specific segments while maintaining a clean URL hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1e34ae9-b5c0-4707-b12e-2d8f6ecc4422', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket ensure thread safety for shared state without explicit locks in the handler?', N'Senior', N'Rocket utilizes the Rust ownership model and interior mutability patterns to manage shared state safely. By requiring managed state to be thread-safe (implementing Send and Sync), the framework ensures that data access is synchronized at the type level, preventing race conditions without requiring developers to manually manage mutexes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc4a834e-48b7-41f8-aa44-2d908ebcb83a', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does TTL (Time-To-Live) impact system consistency?', N'Middle', N'TTL defines how long an entry remains in the cache before it is invalidated, representing a trade-off between freshness and system load. A short TTL ensures high consistency with the source of truth, while a long TTL reduces database load but increases the risk of serving stale data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d0c7ccf-4446-4f7b-80a8-2d91a66b922c', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the role of a consistent hashing algorithm in distributed database clusters?', N'Senior', N'Consistent hashing minimizes data movement during cluster scaling by ensuring that only a fraction of keys need to be remapped when nodes are added or removed. It evenly distributes data across the cluster while preventing the massive re-sharding overhead associated with simple modulo-based partitioning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'faf4097b-6d30-4855-97d2-2d939f79ead5', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What are the implications of the ''N+1'' query problem in Spring Data JPA?', N'Senior', N'The N+1 problem occurs when fetching a collection of entities results in one initial query followed by N subsequent queries to fetch associations. It can be mitigated using Join Fetch patterns in JPQL or EntityGraphs to fetch associations in a single database round-trip.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8ffc02f-b830-472e-83c0-2d945cb6e327', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a secondary index?', N'Intern', N'A secondary index allows you to query a table by a column that is not part of the primary key. It is generally recommended to use them sparingly because they can impact performance in a distributed environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93c0af51-b445-4757-9bbd-2d96417c5411', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How does Eventual Consistency differ from Strong Consistency?', N'Middle', N'Strong Consistency ensures that all reads return the most recent write, regardless of which node is accessed, but it can increase latency. Eventual Consistency allows for temporary discrepancies between replicas, offering higher availability and performance, with the guarantee that data will eventually converge to the same state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62ad995c-773b-4c38-b3d6-2d9af7f3b845', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the primary reason for avoiding ''Side Effects'' inside Redux reducers?', N'Senior', N'Reducers must be pure functions to ensure that the state remains deterministic and predictable. Introducing side effects like API calls or random number generation would make the state transition dependent on external factors, breaking the ability to reliably replay actions for debugging or testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9dbf28d-5c6c-4aba-b0da-2d9d69825dda', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is an Implicit Parameter?', N'Intern', N'An implicit parameter is a parameter that the compiler can automatically fill in if one is not provided. It allows developers to pass common configurations or context through a program without explicitly writing them in every function call.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
