INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49d402f4-2040-41f2-a2b3-2db08854e10e', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the limitations with web workers?', N'Intern', N'You need to remember two important things when using Web Workers in Angular projects, 1. Some environments or platforms(like @angular/platform-server) used in Server-side Rendering, don''t support Web Workers. In this case you need to provide a fallback mechanism to perform the computations to work in this environments. 2. Running Angular in web worker using @angular/platform-webworker is not yet supported in Angular CLI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd028a5d6-9b35-4306-a1c9-2db1ce1119d1', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a scan operation in DynamoDB?', N'Intern', N'A scan operation reads every single item in a table. It is generally inefficient for large datasets and should be used sparingly, as it consumes a large amount of read capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea0fe503-7e29-4d15-9ed7-2db536ee486a', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you adapt your communication style when explaining a technical problem to a non-technical person?', N'Fresher', N'I avoid technical jargon and focus on the practical impact and the high-level steps taken to address the issue. I use analogies if necessary to make the concepts easier to understand for someone outside the technical team.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72a73aa9-fd74-4fa6-9154-2db682a48666', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does ReactJS work behind the scenes?', N'Fresher', N'ReactJS is a powerful JavaScript library for building user interfaces. While it appears simple on the surface, React performs a lot of complex operations behind the scenes to efficiently update the UI. Here''s an overview of how it works internally: 1. Virtual DOM & Component Rendering React doesn''t manipulate the real DOM directly. Instead, it uses a Virtual DOM — a lightweight JavaScript representation of the UI. When a component renders (e.g., ): * React executes the component function (e.g., App()). * Hooks like useState are registered and tracked in order. * React builds a Virtual DOM tree from the returned JSX. * This virtual DOM is a plain JS object that describes the desired UI. This process ensures fast and efficient rendering before React decides how to update the real DOM. 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
