INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b671d667-1686-4d7b-9258-2dbbacc79c39', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the benefit of checking system health metrics?', N'Fresher', N'Health metrics like CPU, memory, and disk usage provide an overview of the system state. They can quickly indicate if a problem is caused by resource exhaustion rather than a logic error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bbdb84d-d41b-4ae3-94dc-2dbd65bb134b', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is reconciliation in Preact?', N'Intern', N'Reconciliation is the process where Preact compares the current Virtual DOM tree with a new version after a state change. It identifies the differences and applies only the necessary changes to the real DOM to optimize performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4686df0-a391-4b21-bee8-2dc146375059', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does the virtual DOM reconcile differences during a re-render, and what are the limitations of the diffing algorithm?', N'Senior', N'React uses a heuristic O(n) diffing algorithm that assumes component types remain stable and utilizes ''key'' props to identify stable elements in lists. Its main limitation is that it cannot know if a subtree has moved without keys, and it assumes that changes to component structure are infrequent, which can lead to unnecessary re-mounts if keys are not managed correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a51bff40-4ec8-4bd5-b8de-2dc2d38fa2f6', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What are ''DTOs'' (Data Transfer Objects) in the context of Litestar?', N'Junior', N'DTOs in Litestar are used to define the schema for data moving into or out of your application. They act as a contract that defines which fields are required or optional, ensuring that your internal data models remain protected from direct exposure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74fc774e-c83a-4147-aab0-2dc2d9b8fa23', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you decide between using a relational database versus a NoSQL database?', N'Senior', N'I look at the schema structure and the nature of the queries; relational databases excel at complex transactions and structured data with strict integrity requirements. NoSQL databases are preferred when dealing with massive scale, unstructured data, or high-write throughput where horizontal scaling is the primary driver.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
