INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e3f579c-2eaa-43b3-abb6-2dc4da5b9b03', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the role of the binary log (binlog) in MySQL replication?', N'Middle', N'The binary log records all changes to the database structure and data in a serialized format. It is essential for master-slave replication, where the slave reads the binlog from the master and applies the changes to maintain synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
