INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5de6df42-6365-44a0-9854-2ddc94210246', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How do C++ smart pointers manage ownership and prevent dangling references?', N'Senior', N'Smart pointers use RAII to manage object lifetimes; unique_ptr enforces exclusive ownership, while shared_ptr uses reference counting to manage shared ownership. By automating resource release, they prevent memory leaks, and weak_ptr provides a way to observe objects without owning them, allowing for safe detection of object destruction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
