INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80ac4cf5-cdc0-4303-a156-2ddec071bc18', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI leverage Python''s asynchronous capabilities to handle high concurrency compared to traditional synchronous frameworks?', N'Senior', N'FastAPI is built on Starlette and uses the ASGI standard, allowing it to handle asynchronous requests via the event loop. By leveraging ''async def'', it avoids blocking the main thread during I/O-bound operations, which significantly improves throughput and responsiveness compared to WSGI-based frameworks that typically rely on multi-threading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
