INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29d2a077-db45-43c2-b4f6-2de720f789ec', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How to compare two objects in javascript?', N'Fresher', N'Objects are reference types so you can''t just use === or == to compare 2 objects. One quick way to compare if 2 objects have the same key value, is using JSON.stringify(). Another way is using Lodash .isEqual() function. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83a996c0-6a4f-4169-8dfe-2dea03ee8942', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the DRY principle in JavaScript?', N'Intern', N'DRY stands for Don''t Repeat Yourself. It states that every piece of knowledge must have a single, unambiguous, authoritative representation within a system. Duplicated logic makes code harder to maintain because changes must be applied in multiple places. Violation: Applying DRY: DRY vs. WET (Write Everything Twice): DRY does not mean *never write similar-looking code*. Premature abstractions can introduce unnecessary coupling. A practical rule: abstract duplication only when the same logic appears three or more times and the abstraction does not make the code harder to understand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5bd335d-38a5-4a08-848c-2dea2b7c38e2', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do ''Error Budgets'' influence the relationship between engineering and product teams?', N'Senior', N'Error budgets quantify the acceptable amount of unreliability for a service. They create a data-driven framework where engineering can slow down feature deployment if the budget is exhausted, ensuring reliability is treated as a first-class feature.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0819e7d-4fe0-4126-aeb5-2dec7c6b1810', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the benefit of using an Interface in your design when you know you might need different implementations later?', N'Fresher', N'Using an interface decouples the code that uses a service from the specific implementation of that service. This allows me to swap or update the underlying logic without needing to change any of the client code that depends on the interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f861bb2-8707-4a1b-8d66-2deea2aab727', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of the Event Dispatcher component?', N'Fresher', N'The Event Dispatcher allows different parts of the application to communicate by triggering and listening to events. It enables developers to hook into the application''s lifecycle to perform custom actions without modifying core code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab9c89c1-3b83-44f6-a6e8-2df3c7763417', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is strict mode important in TypeScript?', N'Intern', N'Strict mode enables a wide range of type-checking behaviors that result in stronger guarantees of program correctness. It helps catch subtle bugs that would otherwise be ignored by the compiler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b816fc7-fe51-4023-8e93-2df536b6c9d4', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the benefit of explaining your thought process to a peer while solving a problem?', N'Junior', N'Articulating my logic helps me identify gaps in my own reasoning and often leads to discovering the solution while I am talking through it. It also allows my peer to provide early feedback, which can save time by preventing me from heading down the wrong path. This collaborative approach fosters knowledge sharing within the team.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'889c7730-f5c8-4807-8fac-2df569c6ad19', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do you define a static file server in Gin?', N'Fresher', N'Gin provides a dedicated method to serve static files from a specific directory on the server. By mapping a URL path to a local folder, Gin can automatically serve assets like CSS, JavaScript, and images to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5900303d-55d7-4b6b-8e79-2df58abc26d1', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is denormalization, and why might a developer use it?', N'Junior', N'Denormalization is the practice of intentionally adding redundant data to a database. It is used to improve read performance by reducing the number of costly table joins required to fetch complex data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdb945df-5505-4e2b-87ad-2df819a89719', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is Dependency Injection in Quarkus?', N'Intern', N'Dependency Injection is a design pattern where the framework provides the necessary objects to a class instead of the class creating them itself. Quarkus uses a version of CDI to manage these dependencies efficiently at build-time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9396770-e25e-4108-ab28-2e01b5384840', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is a test pyramid?', N'Intern', N'The "Test Pyramid" is a metaphor that tells us to group software tests into buckets of different granularity. It also gives an idea of how many tests we should have in each of these groups. It shows which kinds of tests you should be looking for in the different levels of the pyramid and gives practical examples on how these can be implemented. Mike Cohn''s original test pyramid consists of three layers that your test suite should consist of (bottom to top): 1. Unit Tests 1. Service Tests 1. User Interface Tests', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15cf4d02-be38-4d28-baea-2e026660a59a', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Are Strings mutable or immutable in Java?', N'Fresher', N'Strings are immutable in Java, meaning once a String object is created, its value cannot be changed. Any operation that appears to modify a string actually creates a new String object in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bc92796-6255-4e2c-b0f6-2e03614f6be1', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of a Supervision Tree?', N'Fresher', N'A supervision tree is a hierarchy of processes where supervisors monitor other processes. If a process crashes, the supervisor detects the failure and can restart it based on defined strategies, ensuring application stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28955b39-d02d-4dad-aac6-2e0744d3c695', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the function of the ''Link'' component?', N'Fresher', N'The Link component is used for navigation between pages in a Next.js application. It enables client-side transitions, which makes navigation feel faster because it does not require a full page reload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02efdeed-04ac-4855-bf7a-2e08ad0b8b2c', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the difference between ''classmethod'' and ''staticmethod'' in terms of object interaction.', N'Senior', N'A classmethod receives the class as the first implicit argument, allowing it to modify state that applies to the class rather than a specific instance. A staticmethod behaves like a regular function defined within a class scope, receiving no implicit first argument, and is used solely for logical grouping. Choosing between them depends on whether the method needs access to class-level attributes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87e31d08-f382-4feb-92b0-2e09298e7fce', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How do you test a Chi-based application without starting a real HTTP server?', N'Middle', N'You can use the net/http/httptest package to create a response recorder and a request object, then pass them directly to the Chi router''s ServeHTTP method. This allows for fast unit testing of the entire routing and middleware stack without the overhead of network I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e45d3c4-ed4b-485f-9836-2e093273ab6f', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the role of the ''aria-hidden'' attribute, and what are the risks of overusing it?', N'Middle', N'The ''aria-hidden'' attribute hides content from assistive technology, such as screen readers, without removing it visually. Overusing it is risky because you might inadvertently hide critical information or interactive elements, making the page inaccessible to users who rely on screen readers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'019dfe94-82c2-4170-8d5c-2e0e17d70d6f', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Why is it important to define explicit return types in Litestar route handlers?', N'Senior', N'Defining explicit return types allows Litestar to optimize the response serialization process and ensures the generated OpenAPI specification is accurate. It also assists static analysis tools in catching potential mismatches between the handler''s business logic and the actual API response schema.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7350d2d-17e1-4566-ac5e-2e0ea5139e74', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What techniques do you use to debug high CPU usage in a service that is not experiencing a proportional increase in traffic?', N'Senior', N'I would use a profiler to capture a stack trace snapshot of the active threads to identify if the CPU is being consumed by tight loops, inefficient serialization, or excessive garbage collection. If the CPU is not in the application code, I would investigate kernel-level events or background processes like logging agents or security scanners that might be misconfigured.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'339edc18-e523-4bf4-82ed-2e0fd78f45a4', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the ''AssemblyLoadContext'' in .NET Core?', N'Senior', N'AssemblyLoadContext provides a mechanism for loading, isolating, and unloading assemblies within the same process. It is essential for plugin architectures where different versions of the same dependency need to coexist or where assemblies must be unloaded to free memory without restarting the process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'873e8e82-883e-4b8a-b743-2e101519321b', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is an event listener directive in Alpine.js?', N'Intern', N'An event listener directive, typically written as x-on, is used to listen for browser events like clicks, key presses, or form submissions on an HTML element. When the specified event occurs, it triggers the associated JavaScript expression defined within the directive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
