INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb5df1c5-9c0d-4ec4-82c9-2e166c45c795', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle non-standard HTTP methods or custom verbs?', N'Senior', N'Chi is designed to support the full range of HTTP verbs natively through its router registration methods. Since it respects the underlying http.Request structure, custom verbs are handled consistently, provided the server configuration is aligned with the required method definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a04ca9d6-c794-464e-83b0-2e16dc3d0715', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the primary purpose of the TypeScript compiler?', N'Intern', N'The primary purpose of the TypeScript compiler is to transpile TypeScript code into plain JavaScript that browsers or runtime environments can understand. It also performs static type checking to identify potential errors during development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2947c932-f815-4a5c-b1a6-2e185e036cea', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of ''Materialized Views'' in an OLAP context?', N'Senior', N'Materialized views pre-compute and store the results of complex queries, allowing for near-instant retrieval of expensive aggregations. They trade off storage space and write latency for significantly faster read performance on analytical dashboards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f97168f8-5842-495b-a09e-2e185ebaaab4', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between CHAR and VARCHAR?', N'Intern', N'CHAR is a fixed-length data type, meaning it always uses the defined number of bytes regardless of the input. VARCHAR is a variable-length data type that only uses the amount of storage needed for the actual string content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'034185fe-3831-4d2a-8e21-2e1a44b03cd3', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How do database indexes impact read and write performance?', N'Senior', N'Indexes significantly accelerate read performance by providing efficient search paths to specific records. However, they impose a write performance penalty because every insert, update, or delete operation requires the database to maintain and update the index structures, increasing disk I/O and CPU overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b8383a8-c7c8-4891-9fe4-2e1c817b4e38', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Explain the architectural trade-offs of using jQuery''s custom event system versus native DOM event delegation.', N'Senior', N'jQuery''s event system adds a layer of metadata to elements, which can lead to memory leaks if not explicitly cleaned up. Native event delegation is more performant and memory-efficient because it leverages the event bubbling phase without requiring additional object storage per element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4db088cc-18ca-45f4-9ab4-2e1c8e7bff18', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Explain the performance implications of jQuery''s selector engine compared to native querySelectorAll.', N'Middle', N'jQuery''s selector engine was originally built to provide cross-browser consistency and support for custom CSS-like selectors. Modern native browser methods are highly optimized and significantly faster than jQuery''s wrapper, making jQuery''s overhead unnecessary for standard element selection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'893a7340-d2c4-443e-a961-2e1c976b7eec', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Why is it important to keep Astro components lightweight?', N'Middle', N'Since Astro components are the building blocks of the page, keeping them lightweight ensures the initial HTML payload remains small. Large components can bloat the server-side rendering time and increase the amount of data sent to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdca3ef3-e654-47a8-a546-2e1ca14944a8', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is meant by ''pass-by-value''?', N'Intern', N'Pass-by-value means that the actual value of an argument is copied into the function''s parameter. Consequently, any changes made to the parameter inside the function do not affect the original variable in the calling code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16008f2a-36da-4c5b-92b7-2e1d9942ce45', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix handle shared state across different request threads?', N'Intern', N'Actix uses the Data extractor to share state safely across different threads. By wrapping data in a thread-safe container like an Arc, multiple request handlers can access the same application state without causing memory safety issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66503ca5-4c40-4dea-8b99-2e2016580b1d', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why would you choose to implement caching in a system design?', N'Intern', N'Caching is used to improve performance and reduce latency by storing frequently accessed data in a faster storage layer. It reduces the load on primary databases and APIs, leading to a more responsive user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4bd9cb1-b875-46e9-86d3-2e208014c029', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How do you manage cache versioning to handle schema changes or breaking updates?', N'Senior', N'Versioning involves prefixing keys with a version identifier (e.g., ''v1:user:123''). When the data schema changes, you increment the version number, which effectively invalidates the old cache entries and prevents the application from trying to deserialize incompatible data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ab1615e-7ff2-473e-b7bf-2e23d5c0e6bd', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What are Blade templates?', N'Junior', N'Blade is Laravel''s powerful templating engine that allows you to write plain PHP in your views while providing clean, simple syntax for common tasks. It compiles your templates into raw PHP code and caches them for performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7da7d85-4fa8-4386-aa57-2e2454dfab06', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is Django middleware?', N'Intern', N'Middleware is a framework of hooks into Django’s request/response processing system. It is a series of layers that can modify incoming requests before they reach the view or modify outgoing responses before they reach the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'516d4eb3-4dcc-4e07-aa7f-2e2eaeec7d44', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Can you explain how Fastify handles route matching?', N'Junior', N'Fastify uses a highly optimized tree-based router that evaluates routes much faster than traditional regex-based routers. It matches incoming URL patterns against registered routes and parameters efficiently, which is a significant factor in the framework''s overall speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'030cef8d-2b6b-46d8-8e9e-2e2ef98ff10b', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do CSS Grid and Flexbox differ in their primary use cases?', N'Middle', N'Flexbox is designed primarily for one-dimensional layouts, either as a row or a column, making it ideal for distributing space within a single component. CSS Grid is built for two-dimensional layouts, managing both rows and columns simultaneously, which is better suited for high-level page structures. They are often used together to create complex, responsive interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6068ff30-aa9b-420b-9632-2e30bdfcf534', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Can NoSQL databases store relational data?', N'Intern', N'Yes, NoSQL databases can store relational data, but they do not enforce relationships through foreign keys or joins at the database engine level. If relationships are needed, they are usually managed by the application code or through data embedding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef465370-4145-47f7-b2c8-2e312f2a574b', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala handle dependencies and modularity?', N'Middle', N'Scala uses traits and self-type annotations to define modular components. By composing these traits, developers can create flexible, testable architectures that avoid the rigidity of traditional class-based dependency injection frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd73e8980-e169-4730-b4de-2e33a42a7728', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What are the advantages of using Micronaut''s event-driven architecture for inter-service communication?', N'Senior', N'Micronaut simplifies event-driven communication by providing abstraction layers for message brokers like Kafka or RabbitMQ. This decouples services, enhances scalability by enabling asynchronous processing, and allows for more resilient systems that can handle bursts of traffic without blocking main execution threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2e8c79c-5d1f-4913-a914-2e392764fb82', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the difference between ''Form'' and ''Body'' data in FastAPI?', N'Junior', N'Form data is used when the request content type is ''application/x-www-form-urlencoded'', typically used by HTML forms. Body data is used for ''application/json'' payloads and is the standard way to send structured data to an API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb22852b-67b9-4d27-abad-2e3eb8200f0d', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Does Ember support dependency injection?', N'Fresher', N'Yes, Ember includes a built-in dependency injection system. This allows you to easily inject services or other objects into components and routes, promoting modular code and making it easier to test individual parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e76f3e5d-4741-475b-9b2d-2e40ac9a112b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are some techniques for reducing reflows and repaints?', N'Intern', N'To reduce reflows and repaints, you can minimize DOM manipulations, batch DOM changes, use CSS classes for style changes, avoid complex CSS selectors, and use requestAnimationFrame for animations. Additionally, consider using will-change for elements that will change frequently and avoid layout thrashing by reading and writing to the DOM separately. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the concept of lazy loading and how it can improve performance Lazy loading is a design pattern that delays the loading of resources until they are actually needed. This can significantly improve performance by reducing initial load times and conserving bandwidth. For example, images on a webpage can be lazy-loaded so that they only load when they come into the viewport.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d1bcc88-4430-43d8-b059-2e40ef624ba0', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Does Echo support HTTPS?', N'Intern', N'Yes, Echo supports HTTPS by allowing you to start the server using a TLS configuration. It also provides helper functions to facilitate automatic certificate management via Let''s Encrypt.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fa2f8b1-e5ed-42e7-80bd-2e418d6da9e5', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are the implications of the C standard''s ''effective type'' concept for memory reuse?', N'Senior', N'The effective type determines the type of an object stored in memory, which is crucial for the compiler''s strict aliasing analysis. If memory is reused for a different type, the programmer must ensure the new type is compatible, otherwise, subsequent reads and writes may violate the standard and trigger undefined behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd00adef4-ba2b-44ea-b2bc-2e45a51bc94a', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS support Server-Sent Events (SSE), and what are the primary advantages of using SSE for real-time communication in web applications?', N'Fresher', N'Server-Sent Events (SSE) is a server push technology enabling a client to receive automatic updates from a server via HTTP connection. SSE is a one-way communication channel from server to client. If you need bi-directional communication, you might want to use WebSockets instead. SSE they have been used in Facebook/Twitter updates, stock price updates, news feeds etc. To enable Server-Sent events on a route (route registered within a controller class), annotate the method handler with the @Sse() decorator. In the example above, we defined a route named sse that will allow us to propagate real-time updates. These events can be listened to using the EventSource API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3dbcae9-165d-493a-8908-2e46faa819ab', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the architectural implications of Flask''s thread-local storage mechanism.', N'Senior', N'Flask uses thread-local storage to provide the ''request'' and ''g'' objects, which appear global but are unique to the current thread. While this simplifies development, it can lead to memory leaks or incorrect state if not properly cleaned up, and it makes asynchronous programming with libraries like gevent or asyncio more complex, often requiring context-aware wrappers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83d27450-556c-4c50-af18-2e488a449f82', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is a struct in C#?', N'Intern', N'A struct is a value type that is used to encapsulate small groups of related variables. Unlike classes, structs are stored on the stack and are better suited for lightweight data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c6c1991-ad47-4f54-afe2-2e4924e77c1c', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Why would you choose Echo over the standard net/http library?', N'Middle', N'Echo provides essential features out of the box, such as path parameter extraction, structured middleware, and simplified data binding. It significantly reduces the amount of boilerplate code required for building production-ready RESTful APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b0510d8-e385-42a4-8d91-2e4eb0360eeb', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does ''EventEmitter'' handle errors if they are not caught?', N'Middle', N'If an EventEmitter emits an ''error'' event and there are no registered listeners for it, the Node.js process will throw the error and crash. This is why it is critical to always attach an ''error'' listener to any EventEmitter instance to ensure graceful handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ca8591d-dcc7-4b06-b9f8-2e532941ce12', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the architectural significance of separating ''Domain'' logic from ''Infrastructure'' logic in a Symfony application?', N'Senior', N'Separation of concerns ensures that the business logic remains independent of frameworks, databases, or external APIs, making it easier to test and maintain. By using patterns like Hexagonal Architecture or Domain-Driven Design, you can swap infrastructure implementations without impacting the core business rules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd00579f6-47de-4647-bf20-2e53c4d6ec5b', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Explain the trade-offs between vertical and horizontal scaling for a relational database.', N'Senior', N'Vertical scaling increases the capacity of a single node by adding more CPU, RAM, or storage, which is simpler to manage but hits a physical cost-prohibitive ceiling. Horizontal scaling distributes data across multiple nodes, offering near-infinite scalability, but introduces significant complexity regarding data consistency, query routing, and cross-shard transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91313b45-c4fb-4c16-8dce-2e5611382cae', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Explain the architectural considerations of a ''Global Load Balancing'' strategy for multi-region resilience.', N'Senior', N'Global load balancing must account for health check propagation latency, DNS TTL settings, and cross-region data replication lag. It is designed to redirect traffic during a regional outage, requiring a state-management strategy that ensures the secondary region can handle the incoming load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c2cb698-29bb-4795-8177-2e57442324fe', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the purpose of the ''Recipient'' type in Actix?', N'Middle', N'A ''Recipient'' is a type-erased handle to an actor that can only receive specific types of messages. It decouples the sender from the exact actor type, allowing for more flexible and generic system designs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5a2b70f-5311-4cf0-94b3-2e57c33f2de0', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Explain the interaction between the ''loading=lazy'' attribute and the browser''s image decoding process.', N'Senior', N'The lazy attribute defers image loading until the element is near the viewport, which optimizes initial bandwidth and decreases the time to interactive. Browsers will typically decode these images asynchronously as they approach the viewport, reducing memory pressure during the initial page load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64c31571-0beb-46b8-b46a-2e591b1d7357', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How do you handle CORS in an Express application?', N'Middle', N'CORS should be handled by the ''cors'' middleware, which sets the appropriate headers to allow or restrict cross-origin requests. It can be configured globally to allow all origins or restricted to specific domains for better security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92df7491-4964-4f8b-b289-2e5c7a819012', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is a set in Swift?', N'Intern', N'A set is a collection that stores distinct values of the same type in an unordered way. It is used when the order of elements does not matter, but you need to ensure that every item is unique.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b7d749e-1075-40cb-98c7-2e5df985b5f0', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel''s Eloquent ORM handle the N+1 problem, and what are the architectural considerations when choosing between Eager Loading and Lazy Loading?', N'Senior', N'Eloquent uses Eager Loading to fetch related models in a single secondary query using an ''IN'' statement, preventing the N+1 problem. While Eager Loading is generally preferred for performance, it can lead to high memory consumption with large datasets, necessitating a trade-off between database round-trips and memory overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f90694a-555c-41b7-a326-2e5dfa7f9989', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the benefit of Echo''s data binding feature?', N'Intern', N'Data binding in Echo automatically maps data from an incoming HTTP request, such as JSON bodies or form parameters, into Go structures. This simplifies the development process by removing the need for manual parsing and type conversion of input data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b03a5d72-0474-43db-954e-2e5e8820f332', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the role of the sort key in a composite primary key?', N'Fresher', N'The sort key allows you to store and retrieve multiple items with the same partition key. It enables you to organize data logically and perform range queries, such as retrieving all items within a specific time frame.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efe0cbdd-8c2a-475e-a4ef-2e6013c68a74', N'a2838158-7305-480a-b22b-4dc35776b400', N'Explain the concept of idempotency in distributed APIs.', N'Middle', N'Idempotency ensures that performing the same operation multiple times has the same result as performing it once. This is critical in distributed systems to handle network retries safely without causing unintended side effects like duplicate transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1dd4091-b363-4c20-89f9-2e61bbd3097d', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does transaction logging contribute to durability?', N'Junior', N'Transaction logs record all changes before they are applied to the actual data files. If a crash occurs, the database uses these logs to either complete committed transactions or undo uncommitted ones upon restart, ensuring no data loss.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ffe79ce-680c-45ee-9845-2e63f56c2ce0', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is an ''Asset'' in AdonisJS?', N'Fresher', N'Assets refer to static files like CSS, JavaScript, and images that are served to the client. AdonisJS typically integrates with build tools to compile and manage these files efficiently for the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
