INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b56b49e-ba84-44b0-b502-2e692336db95', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'A user reports that a website feature is broken for them but works for you. How do you start troubleshooting?', N'Junior', N'First, verify the user''s browser, operating system, and any specific error messages they see. Then, attempt to reproduce the issue in an environment that matches theirs, such as using incognito mode or clearing cache, to isolate if it is a local issue or a system-wide bug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1825bc3-ca93-4c8c-b422-2e69bfcbd8fb', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the difference between Quarkus and traditional Java frameworks like Spring?', N'Fresher', N'Traditional frameworks typically perform heavy class scanning and dependency injection at runtime, causing slower starts. Quarkus moves these tasks to build time, resulting in a much smaller memory footprint and near-instant startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69e5ed26-6ed2-47d4-ad3c-2e6a702ac8f0', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When is it appropriate to introduce a service mesh into your architecture?', N'Senior', N'A service mesh is beneficial when the operational overhead of managing cross-cutting concerns like mTLS, observability, and traffic shifting outweighs the complexity of the mesh itself. I would avoid it for smaller environments and focus on implementing these patterns within the application logic or sidecar proxies only when the network topology becomes unmanageable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af85cdb6-2348-4b7e-ab5d-2e6d3b6c3a88', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are the trade-offs of the AdonisJS ''BodyParser'' middleware?', N'Senior', N'The BodyParser provides seamless handling of diverse content types, which simplifies development for heterogeneous clients. However, because it reads the entire request stream into memory, it can pose a security risk for large file uploads; developers must configure size limits to prevent denial-of-service attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8687c51b-b5d1-4e2e-9934-2e6e24c49e5c', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s support for custom HTTP errors impact client-side contract adherence?', N'Senior', N'By returning structured error objects through Echo''s error handler, you ensure that clients receive predictable response schemas regardless of where an error originated. This consistency prevents breaking changes in the API contract and allows for automated client generation tools to reliably parse fault responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c7e89e2-942b-48db-b375-2e6f7e340b90', N'4c000000-0000-0000-0000-000000000005', N'What is the trade-off between synchronous and asynchronous communication in distributed systems?', N'Senior', N'Synchronous communication provides immediate feedback but tightly couples services and limits fault tolerance. Asynchronous communication improves system resilience and throughput through decoupling, though it introduces complexity in managing eventual consistency and distributed tracing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'922e3f33-9741-401a-8338-2e742d1a28dd', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How would you manage shared state between different Echo handlers in a thread-safe manner?', N'Senior', N'You should avoid global state and instead inject dependencies via struct fields or use the context''s ''Set'' and ''Get'' methods for request-scoped data. For cross-request shared state, use thread-safe data structures like sync.Map or external stores like Redis to ensure consistency in a concurrent environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e07b122d-2372-4127-9bde-2e74fa1ab87b', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the difference between ''Local Cache'' and ''Distributed Cache'' regarding latency and data synchronization?', N'Senior', N'Local cache resides within the application process memory, providing sub-millisecond access but creating consistency challenges across multiple application instances. Distributed cache resides on external nodes, providing centralized consistency and global state sharing at the cost of network latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ca2b5cf-616c-470e-833c-2e76660265f2', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Explain the architectural benefits of ''feature folders'' when structuring a Redux application.', N'Senior', N'Feature folders group related actions, reducers, and selectors by domain rather than by type, which improves maintainability and discoverability. This approach scales better as the application grows, as developers can modify a single feature without navigating across large, disconnected directories.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecff2f56-5fde-4526-aa31-2e7727610810', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Can Lit components be used in frameworks like React or Vue?', N'Junior', N'Yes, because Lit components are standard Web Components, they are interoperable with any frontend framework. They behave just like native HTML elements and can be used in any environment that supports custom elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf290391-81f2-4a36-b154-2e77c24946ca', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the primary design philosophy of Django?', N'Fresher', N'Django follows the ''batteries-included'' philosophy, meaning it comes with almost everything a developer might need to build a web application out of the box. It also emphasizes the DRY (Don''t Repeat Yourself) principle and promotes rapid development through reusable components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6e75d05-44a2-40bc-9000-2e7a68bf9d8c', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Describe the difference between Spring''s @Value annotation and @ConfigurationProperties.', N'Senior', N'@Value is best suited for injecting individual properties and supports SpEL, but lacks structure. @ConfigurationProperties allows for type-safe, hierarchical property binding to POJOs, making it the preferred choice for managing complex configuration groups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef2944ab-be3c-4932-9d5b-2e7b0e07968e', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the benefit of keeping a project''s technical debt low?', N'Intern', N'Technical debt is the implied cost of choosing an easy, quick solution over a better, long-term approach. Keeping it low ensures that the codebase remains maintainable, agile, and less prone to bugs as the project evolves.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19a9ca9a-518e-417f-a6b0-2e7b9b275d47', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Describe the mechanism behind SvelteKit''s ''streaming'' data and its impact on Core Web Vitals.', N'Senior', N'SvelteKit allows streaming of data by returning a promise in the ''load'' function, which lets the server send HTML immediately while the promise resolves. This improves the Largest Contentful Paint (LCP) by allowing the browser to render the initial shell while waiting for non-critical data, significantly enhancing perceived performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ad9dbfb-b437-453b-b64e-2e7d6c603cd5', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the implications of using large transactions in MySQL?', N'Senior', N'Large transactions consume significant undo log space, increase the duration of locks, and delay the purging process, which can lead to table bloat and performance degradation. They also increase the risk of replication lag, as replicas must process the entire transaction monolithically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'842ed678-5755-4649-bd4d-2e80bddd18a6', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain the concept of Zones in Angular and why they are sometimes bypassed in high-performance scenarios.', N'Senior', N'Zones monkey-patch asynchronous browser APIs to notify Angular when to trigger change detection. In performance-critical scenarios, developers may run code outside of the Angular zone to prevent unnecessary change detection cycles, thereby reducing overhead during high-frequency events like scrolling or drag-and-drop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b214336c-3c7f-48ef-9a9f-2e89176895da', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why is distributed tracing essential in a microservices architecture involving Phoenix?', N'Senior', N'Distributed tracing provides visibility into request lifecycles as they travel across different services and nodes. It helps pinpoint bottlenecks, identify latency sources, and debug complex failure modes that are difficult to isolate within a single service''s logs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c48fcd4a-facb-4082-b64d-2e89ce9b8f9d', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the difference between functional and class-based views.', N'Middle', N'Functional views are simple and explicit, making them easy to understand for straightforward tasks. Class-based views provide a higher level of abstraction and reusability through inheritance and mixins, making them ideal for complex, repetitive view logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8464f92-92f3-42c1-b554-2e89de636f6d', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the main function of the ''var/'' directory?', N'Junior', N'The ''var/'' directory is used by Symfony to store files generated at runtime, such as the application cache and log files. It is not intended for user-provided files and should be ignored by version control systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4f9b389-016c-49fe-9864-2e8cc2204222', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the purpose of ''cookies'' support in Rocket?', N'Fresher', N'Rocket provides built-in support for cookies, allowing you to easily read and write them within your handlers. This is useful for maintaining session state or storing user preferences.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a97c180-aeff-475b-99ae-2e8d2cf4b3b6', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Can TypeScript be used for backend development?', N'Intern', N'Yes, TypeScript can be used for backend development by running it in a Node.js environment. Since it compiles to JavaScript, it is fully compatible with server-side frameworks and libraries that run on the Node runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a1a9c07-892d-4b4b-bc4b-2e8ed66c8f5f', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why is it important to tune ''work_mem'' effectively in a PostgreSQL environment?', N'Senior', N'Work_mem defines the memory allocated per operation for sorts and hashes before spilling to disk. If set too low, complex queries incur high I/O costs due to temporary files; if set too high, concurrent queries can exhaust system memory, leading to OOM-killer intervention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1997d2e8-38a3-4b06-842c-2e93490aefcd', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between compile-time polymorphism and runtime polymorphism?', N'Fresher', N'There are two types of polymorphism in java: 1. Static Polymorphism also known as Compile time polymorphism 2. Runtime polymorphism also known as Dynamic Polymorphism 1. Static Polymorphism: Method overloading is one of the way java supports static polymorphism. Here we have two definitions of the same method add() which add method would be called is determined by the parameter list at the compile time. That is the reason this is also known as compile time polymorphism. Example: Output 2. Runtime Polymorphism: It is also known as Dynamic Method Dispatch. Dynamic polymorphism is a process in which a call to an overridden method is resolved at runtime, thats why it is called runtime polymorphism. Example: Output:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a7f1d0f-9891-47ed-bc1f-2e947320b598', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does the usage of Redux middleware impact the scalability of state transitions in a large-scale application, and what are the architectural trade-offs?', N'Senior', N'Middleware allows for the decoupling of side effects and cross-cutting concerns like logging or analytics from the core business logic, promoting a cleaner separation of concerns. While it significantly improves testability and maintainability, over-reliance on complex chains can lead to debugging difficulties and performance bottlenecks due to the synchronous nature of dispatch processing. Architects must balance the benefits of centralized side-effect management against the potential overhead of sequential execution and the increased complexity of the dispatch pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb332960-e6c6-4c9a-a213-2e94bd933c38', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the danger of ''gold-plating'' or adding extra features not requested by the user?', N'Junior', N'Gold-plating increases the scope of work unnecessarily, which adds risk, potential bugs, and maintenance effort without providing immediate value to the user. It can also delay the delivery of the core requirements that the business actually needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60bf7fea-5aa2-48fb-ae0f-2e9636751dab', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is a cache-aside pattern, and when is it typically used?', N'Middle', N'In cache-aside, the application code manages the cache manually by checking it before querying the database. If the data is missing, the application fetches it from the database and updates the cache, making it ideal for read-heavy workloads where data doesn''t change very frequently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28b2848b-d731-4056-8796-2e9e3408b1ef', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is Quarkus Panache and why is it used?', N'Junior', N'Panache is an abstraction layer for Hibernate ORM that simplifies database operations. It reduces boilerplate code by providing a simplified API for entity management and data access, making it much easier for junior developers to interact with databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4991f195-8d4b-4d4a-87eb-2e9ed39924af', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How does a Circuit Breaker pattern improve system resilience?', N'Middle', N'A circuit breaker prevents a service from repeatedly trying to execute an operation that is likely to fail. By failing fast and preventing cascading failures, it gives the downstream service time to recover and keeps the overall system responsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'822f3b01-e595-460c-9892-2ea31656692d', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why is immutability important in Redux?', N'Fresher', N'Immutability ensures that the previous state is preserved, allowing Redux to detect changes efficiently. This is essential for features like ''undo'' and helps prevent bugs caused by unexpected side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c7cef9f-a66e-4546-ae84-2ea65dae7dac', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the purpose of the ErrorBoundary component in Remix?', N'Fresher', N'An ErrorBoundary is a special component that catches errors occurring during rendering or data loading. It allows you to display a fallback UI instead of crashing the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2021a924-9b51-4018-bf27-2ea690ee19dc', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why is it important to design for short partition keys?', N'Junior', N'Designing for high-cardinality partition keys prevents ''hot partitions''. If one partition key receives significantly more traffic than others, it can lead to performance bottlenecks and throttling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f65bd38-1b74-4a38-b0e6-2ea6ace9bddb', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why are maps in Go not safe for concurrent use?', N'Middle', N'Making maps thread-safe by default would impose a performance penalty on all map operations, even those that do not require concurrency. Go expects developers to use explicit synchronization primitives like mutexes or sync.Map only when concurrent access is actually required, adhering to the principle of not paying for what you don''t use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc17fe25-0c2a-4190-b7cd-2ea8d1705fe3', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle large-scale state management compared to Redux or Pinia?', N'Middle', N'Svelte uses built-in stores which are lightweight observables, avoiding the boilerplate associated with large-scale state libraries. Since Svelte''s reactivity is fine-grained, state updates are usually more performant without requiring complex memoization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f954a675-e007-4cca-a0f3-2eae65e5f474', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle type-safe path parameters?', N'Junior', N'Rocket allows you to define dynamic path segments in your routes, such as . Because Rocket uses Rust''s type system, if you define the parameter as an integer type, the framework automatically attempts to parse the URL string into that type before calling your function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a0e194a-4666-455e-a3b2-2eaebc3f0792', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does garbage collection work in Ruby?', N'Fresher', N'Ruby employs automatic memory management, which is primarily influenced by garbage collection techniques. Let''s understand the specifics. Mark-and-Sweep Algorithm - Step 1 - Mark: The process starts from the root of object references. The GC traverses memory, marking referenced objects. - Step 2 - Sweep: It scans for unmarked objects and reclaims their memory, making it available for future use. Generational Garbage Collection To optimize the Mark-and-Sweep approach, Ruby introduces generational garbage collection. - Focused on Object Age: Objects are classified based on their age. - Young vs. Old Objects: - New objects start in the Young Generation. - Objects that persist multiple GC cycles move to the Old Generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db9ea145-f289-43d5-8bee-2eb083982425', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the distinction between ''Latency'' and ''Throughput'' in system design?', N'Senior', N'Latency is the time it takes to process a single request, while throughput is the total number of requests the system can handle in a given period. Optimizing for one often impacts the other, as increasing throughput might require parallelization that could slightly increase individual request latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e9f11c7-1732-4360-99f6-2eb1b9fe2e40', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB achieve high availability?', N'Junior', N'High availability is achieved through replica sets, which provide automatic failover. If the primary node becomes unavailable, the remaining secondary nodes hold an election to choose a new primary, ensuring the database remains operational.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
