INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9242c5e0-8297-45c1-99b8-2eb51e3b5f3b', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket ensure type safety for incoming data?', N'Fresher', N'Rocket uses Rust''s strong type system to automatically deserialize incoming request data, such as JSON or form data, into defined Rust structs. If the incoming data does not match the expected type or structure, Rocket rejects the request before it reaches your logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f63e8846-33e6-4746-b7fd-2eb602cc491e', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind CSS handle hover, focus, and other state-based styles?', N'Fresher', N'Tailwind uses variant modifiers to handle state-based styles, such as ''hover:'', ''focus:'', or ''active:''. You simply prefix the utility class with the desired state, and Tailwind handles the corresponding CSS pseudo-class automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6040ea7-ae67-43b0-9ce6-2eb6da0228c5', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the ''Lock'' statement work internally, and what is its overhead?', N'Senior', N'The lock statement uses a Monitor object, which involves a lightweight synchronization primitive that attempts to enter a kernel-level wait if contention is high. While efficient for low contention, it introduces an object header overhead and potential thread context switching. For high-contention scenarios, primitives like ReaderWriterLockSlim or SpinLock may be more appropriate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
