INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efff1c3a-f1dc-452d-94f9-2ee1dd47853b', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why is Chi considered ''lightweight''?', N'Fresher', N'Chi has a very small code footprint and does not impose complex design patterns or heavy dependencies. It provides only the essential tools needed for routing, keeping the binary size and memory overhead minimal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19738254-53b6-406c-af64-2ee3c72e23ea', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the ''Hono'' way of handling static file serving?', N'Junior', N'Hono provides a ''serveStatic'' middleware that maps request paths to local files or remote storage assets. This is useful for serving simple frontend assets directly from the backend application without needing a separate web server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b2fbb6f-d3ed-4b90-bbc2-2ee3e702e77a', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Describe the concept of ''Soft State'' in the BASE model.', N'Middle', N'Soft state refers to the condition where the state of the system may change over time even without new inputs, due to the eventual consistency model. It acknowledges that the data on different nodes might temporarily differ while the system is propagating updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81008a32-b468-4a6e-ae00-2ee8eba26220', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is Redux?', N'Intern', N'Redux is a predictable state container for JavaScript applications, most commonly used with React. It helps you manage and centralize your application’s state in a single source of truth, enabling easier debugging, testing, and maintenance—especially in large or complex applications. Redux core is tiny library(about 2.5kB gzipped) and has no dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39c9aac1-e455-4c24-83c4-2eebf1d28313', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Explain the role of write-ahead logging (WAL) in maintaining data durability.', N'Senior', N'WAL ensures that all modifications to a database are logged to stable storage before being applied to the actual data files. This allows the system to recover the state of the database after a crash by replaying the log, ensuring atomicity and durability without requiring an immediate, expensive disk sync of the primary data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb305a2a-5036-4812-b953-2eecb8f41d3c', N'4c000000-0000-0000-0000-000000000005', N'What is the difference between long polling and WebSockets?', N'Middle', N'Long polling keeps an HTTP connection open until the server has data to send, which is resource-intensive. WebSockets provide a full-duplex, persistent connection that allows for real-time, low-latency communication between client and server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a87413f1-1d95-4460-b7ec-2eef0368995a', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does TTL (Time to Live) work in DynamoDB and what is its impact on storage costs?', N'Senior', N'TTL allows you to define an attribute that specifies when an item should be expired, and DynamoDB automatically deletes it without consuming write capacity. This effectively manages storage costs by pruning old data and reduces the need for manual cleanup scripts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8d51f41-ae89-4dce-ad5d-2ef93e61c8f0', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How can you debug a difficult state-related issue in a production Redux environment?', N'Senior', N'I would utilize Redux DevTools for time-travel debugging and action inspection to identify the specific sequence of events leading to the error. If DevTools is unavailable, I would rely on comprehensive action logging, state snapshots, and monitoring tools to correlate state transitions with reported user behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb84da13-6f4e-43ba-90e8-2efc2c74fc96', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS handle circular dependencies, and what does their presence suggest about system design?', N'Senior', N'NestJS uses forward references to resolve circular dependencies, but their presence often indicates a violation of the Single Responsibility Principle or poor module boundaries. Ideally, circular dependencies should be resolved by refactoring the shared logic into a third, independent module.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
