INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60b8bc37-84c4-4851-a524-2efe6c068f87', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does a WAF (Web Application Firewall) differ from a traditional network firewall?', N'Middle', N'A traditional network firewall filters traffic based on IP addresses and ports at the transport layer. A WAF operates at the application layer to inspect HTTP traffic and protect against web-specific attacks like SQL injection and cross-site scripting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
