INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6bbfabc-b4ec-4dc4-929e-2f2477b35190', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What are the benefits of Astro''s zero-JS-by-default approach?', N'Middle', N'This approach ensures that every page is as fast as possible by default, as the browser only processes HTML and CSS. It eliminates unnecessary overhead and improves accessibility and performance on lower-end devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2fa0ca9-bf47-44cd-9a36-2f271664d70b', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What are the risks of increasing the number of partitions in a topic?', N'Middle', N'While increasing partitions improves throughput, it also increases the overhead on the broker to manage more open file descriptors and metadata. Furthermore, it may complicate the ordering guarantees if you have specific requirements for sequential processing across the entire topic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e74094f5-6fea-4331-9202-2f27d790992c', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle exception propagation compared to traditional try-except blocks in business logic?', N'Senior', N'Litestar uses a centralized exception handling mechanism that translates internal errors into standardized API responses, ensuring consistent error reporting across the application. This decoupling allows business logic to raise descriptive exceptions without needing to worry about the format of the final HTTP response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'586d9a46-9f40-4b1d-b378-2f2a06719fce', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the benefit of Fiber''s zero-allocation design philosophy?', N'Fresher', N'The zero-allocation design aims to reduce memory pressure on the Go garbage collector by reusing objects and minimizing allocations. This leads to lower latency and higher throughput in high-load scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
