INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0360124c-5bc2-450e-9480-2f2c1519de11', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between shallow copy and deep copy in the context of C++ classes?', N'Middle', N'A shallow copy duplicates the object''s member values, which can lead to multiple objects pointing to the same dynamically allocated memory. A deep copy allocates new memory and copies the actual contents, ensuring each object manages its own independent resource.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
