INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbb02d28-2e7b-4114-a883-2f3146534049', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the concept of ''Type Inference'' in Swift.', N'Junior', N'Type inference allows the compiler to automatically deduce the type of an expression by examining the values provided. This reduces the need for explicit type annotations while maintaining the safety of a statically typed language.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
