INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0d7e6ae-7d8d-42e1-ac23-2f3730055bfd', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If a downstream dependency is slow, how do you prevent your entire service from becoming unresponsive?', N'Middle', N'I would implement the circuit breaker pattern to stop requests to the failing dependency once a threshold of errors is reached. Additionally, I would set aggressive timeouts and utilize fallback methods or cached data to provide a degraded but functional user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
