INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca324f4e-b4e5-4ac9-884c-2f4e9d1434ca', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is an array in C and what are its limitations?', N'Fresher', N'An array is a collection of elements of the same data type stored in contiguous memory locations. Its main limitation is that it has a fixed size determined at compile-time, making it difficult to change the number of elements during runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a2482f8-74a9-462f-96a8-2f5496054df3', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why does Vite pre-bundle dependencies, and how does it handle them?', N'Middle', N'Vite uses pre-bundling to convert CommonJS or UMD dependencies into native ESM and to consolidate hundreds of small internal files into a single module. This prevents the browser from being overwhelmed by a massive number of HTTP requests for deep dependency chains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
