INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1905d456-c84d-41ac-ba7d-2f588643643c', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s ''dynamic'' keyword bypass the type system, and what are the associated risks?', N'Senior', N'The ''dynamic'' keyword disables static type checking for a variable, deferring all resolution to the runtime, which effectively turns off the compiler''s safety guarantees. This introduces the risk of runtime type errors and prevents the compiler from performing optimizations like method inlining or member look-up shortcuts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75befba8-d925-4f40-8dc2-2f5a5d856286', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If a system is running slowly, how do you logically approach finding the cause?', N'Junior', N'I start by isolating variables, such as checking logs, monitoring resource usage like CPU or memory, and comparing current performance against a known baseline. I look for the most likely bottleneck first, such as database queries or external API calls, rather than guessing randomly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d300647-7977-496d-9901-2f5b7cb3eb36', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the difference between an action and a component in Svelte?', N'Fresher', N'An action is a function that attaches to an element to handle custom behavior or DOM manipulation, whereas a component is a reusable UI unit containing its own logic and template.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d3149c2-0451-4270-93d7-2f5d743e89a8', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the difference between ''competing consumers'' and ''fan-out'' patterns?', N'Middle', N'Competing consumers share the workload of a single queue, where each message is processed by only one worker. Fan-out broadcasts every message to multiple queues, ensuring each subscriber receives its own copy of every message.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa987e77-0591-4759-8f8e-2f5d8dfe53e5', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your philosophy on logging—how much is too much?', N'Middle', N'I log enough metadata to reconstruct the context of an event without logging sensitive data or flooding the storage with redundant info. I categorize logs by severity and ensure that log aggregation tools can efficiently filter and alert on critical errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0e14546-b06c-4d32-ad33-2f5ef981d573', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the role of the ''webpack.config.js'' file?', N'Intern', N'This file is the configuration file for Webpack where you define how the bundler should behave. It allows you to specify entries, outputs, loaders, plugins, and other settings to customize the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
