INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dafb89f0-94ca-4517-a6dc-2f6472464afe', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the ''Portal'' component in SolidJS?', N'Fresher', N'The Portal component allows you to render children into a different part of the DOM tree, outside the parent component''s hierarchy. This is commonly used for elements like modals, tooltips, or overlays that need to escape the flow of the main layout.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1837d776-ab80-437e-a7f3-2f649aae6d22', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What strategy would you use to handle large data migrations in a microservices environment?', N'Senior', N'Use the ''Dual Write'' or ''Change Data Capture'' (CDC) approach to stream updates from the legacy database to the new service data store while keeping both in sync. Once the new service is validated, perform a cutover and eventually retire the legacy data source.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efa41db9-3d06-4495-af54-2f64a00f3a6f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does the Dart runtime handle the conversion of async/await into state machines?', N'Senior', N'The compiler transforms async functions into state machines that track the execution position, pausing and resuming at await points. This allows the runtime to suspend function execution and return control to the event loop, effectively managing non-blocking concurrency without expensive thread context switches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
