INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14de5ddf-bd6f-4cb1-be4b-2f8a91811b0f', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the role of the ''Supervisor'' in a Phoenix application.', N'Middle', N'The Supervisor is responsible for monitoring and restarting child processes if they fail. By organizing processes into a tree structure, it ensures that if a critical part of the application fails, it can be automatically recovered, which is fundamental to building high-availability systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
