INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'195045ea-4e33-4c42-a3a4-2f8b9d645ad3', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the purpose of the Two-Phase Commit (2PC) protocol and what are its main drawbacks?', N'Senior', N'2PC is a consensus protocol designed to ensure atomic commitment across multiple distributed nodes. Its primary drawback is that it is a blocking protocol; if the coordinator fails during the second phase, participants may remain in a locked state, significantly impacting system availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34703544-5026-4047-8236-2f8e67a59d88', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Discuss the implications of Python''s dynamic typing on performance and tooling.', N'Senior', N'Dynamic typing allows for rapid development and flexibility but prevents the interpreter from performing certain optimizations during compilation. It also makes static analysis harder, though the introduction of Type Hints has significantly improved IDE support and linting capabilities. Type hints provide a way to gain some benefits of static typing without sacrificing the runtime flexibility of the language.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9a81e85-8009-401f-bf21-2f9047a6d7ed', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you balance thoroughness with speed?', N'Intern', N'I aim for a ''minimum viable product'' approach where I fulfill the core requirements first to ensure functionality. Once the foundation is solid, I iterate to improve efficiency and thoroughness if time permits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5a0ea89-a088-473e-9b0f-2f93a19fbf41', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you handle database transactions in Flask without a heavy ORM integration?', N'Middle', N'You can manage database transactions manually by using a ''before_request'' hook to open a connection and an ''after_request'' or ''teardown_request'' hook to commit or rollback the transaction based on the success of the request. This ensures that resources are properly cleaned up and that operations remain atomic even if an error occurs mid-request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed97fe37-af6f-4c68-a1fb-2f95bde09ec9', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How do you ensure accessibility in a dynamic Nuxt environment where content changes frequently?', N'Senior', N'Ensuring accessibility requires managing the focus state manually during programmatic navigation and using live regions for dynamic content updates. Additionally, ensuring that meta-tags and aria-attributes are properly updated on the server during SSR is critical for screen readers to receive the correct document state upon initial load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5afec13a-df83-4ed4-b12d-2f9bb82b2740', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the difference between synchronous and asynchronous API patterns?', N'Middle', N'Synchronous APIs require the client to wait for a response, making them suitable for quick operations. Asynchronous APIs return an immediate acknowledgment, allowing the client to continue other tasks while the server processes the request in the background, which is ideal for long-running operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'329a0438-f0a3-45c1-bd6b-2f9c9b204678', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you estimate the storage capacity needed for a new database system?', N'Intern', N'I would start by identifying the size of a single data entry and estimating the projected number of entries over a specific time frame. I would then account for overhead such as indexing, logs, and potential future growth to arrive at a safe capacity estimate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'767165b1-9bc0-43c1-bc7c-2f9d35c1ab0a', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt handle dynamic routing?', N'Junior', N'Dynamic routes are created by prefixing a filename with an underscore in the pages directory. For example, a file named [id].vue creates a dynamic parameter that can be accessed within the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ffc10d6-77f5-4f8a-ae69-2fa3e46a79a4', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket manage path parameters?', N'Fresher', N'Rocket allows developers to capture segments of a URL path by defining them as variables within the route attribute. These segments are automatically parsed and passed as arguments to the route handler function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5199ec0b-c0d2-48de-a847-2fa7b954b64b', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are the performance implications of using Hono''s built-in JSX rendering vs. traditional server-side template engines?', N'Middle', N'Hono''s JSX rendering is optimized for high-performance streaming directly to the client. Unlike heavy template engines that require significant memory overhead, Hono''s implementation is lightweight and designed to minimize blocking, making it ideal for edge-side rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b00724db-e42a-42cb-aeb7-2faacb8b27e7', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are the advantages of using symbols over strings?', N'Middle', N'Symbols are immutable and unique identifiers that are more memory-efficient because they are not recreated every time they are used. They are typically preferred for hash keys or method names where the content does not need to change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a67b36a9-0826-4839-8c6d-2fac80397c17', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the significance of the Tower ecosystem when working with Axum?', N'Junior', N'Tower is a library for building modular, reusable network services, and it serves as the foundation for Axum. It provides the abstractions for middleware, allowing developers to easily add features like rate limiting, timeouts, and tracing to their applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'334be5ef-5fc5-4d7d-9c2c-2fae100658d8', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are namespaces in PHP and why are they used?', N'Junior', N'Namespaces are a way of encapsulating items such as classes, functions, and constants to prevent name collisions. They allow you to group related code under a specific prefix, making it easier to use third-party libraries without conflicting with your own code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcc710aa-b8d1-4457-a014-2fae2d58a7cc', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Explain the concept of ''Handler'' types in Fiber.', N'Middle', N'A handler is a function that processes an incoming request and returns a response. Fiber uses a specific function signature that accepts the context object, allowing direct access to request headers, bodies, and parameters without needing to wrap them in an interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba6e2bfc-29a3-4580-a1f8-2faef6623f4a', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does the ''publicPath'' configuration affect asset loading?', N'Middle', N'The publicPath specifies the base path for all assets within the application. It is crucial when assets are hosted on a separate server or a CDN, as it ensures that the browser requests files from the correct URL structure regardless of the environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d2b85ee-d954-468f-a266-2fafa974921d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the advantages of using strict mode in a JavaScript application?', N'Middle', N'Strict mode enforces cleaner coding standards by throwing errors for common mistakes like assigning to undeclared variables or using reserved keywords. It also optimizes performance by allowing engines to make better assumptions about code behavior and restricts potentially unsafe features like the ''with'' statement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33453e64-9af7-4615-b574-2fb32e6b1870', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the difference between an Ecto Schema and a database table?', N'Intern', N'A database table is the physical storage structure in the database, while an Ecto Schema is an Elixir module that maps the data in that table to a structured format used within the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7d319c4-9311-477e-bede-2fb3d56c627d', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How do C# ''delegates'' differ from ''events''?', N'Middle', N'A delegate is a type-safe function pointer that can be invoked directly, while an event is a wrapper around a delegate that restricts external access. Events enforce the encapsulation of a delegate by only allowing external code to subscribe or unsubscribe, preventing external classes from invoking the event directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
