INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ef0d3fb-9804-4db9-ba77-2fb448e95c1b', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the benefit of Tailwind''s ''peer'' modifier?', N'Middle', N'The peer modifier allows you to style an element based on the state of a preceding sibling element. This is highly useful for managing UI states in forms, such as showing or hiding error messages based on the focus or validity of an input field.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2f0f737-1679-42d3-98b3-2fb6c53617ff', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why is it important to use unique keys when rendering lists in Preact?', N'Intern', N'Keys help Preact identify which items in a list have changed, been added, or removed during the reconciliation process. Providing unique keys allows Preact to perform more efficient updates and prevents bugs related to element state being incorrectly preserved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
