INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86767266-964c-4b42-8772-2fb9c0f7b8dd', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Can you define multiple routes for the same path in Axum?', N'Fresher', N'Yes, Axum''s router supports associating different HTTP methods like GET, POST, or PUT with the same path. This allows you to build RESTful APIs where different actions are performed on the same endpoint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd4417e5-54ab-4c5e-b16c-2fc010c279bd', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the role of an ''Epoch'' or ''Timestamp'' in distributed transaction ordering?', N'Senior', N'Timestamps or epoch numbers are used to establish a global order of transactions across distributed nodes. They allow systems to resolve conflicts by determining which transaction occurred first, which is critical for maintaining consistency in multi-master or distributed database architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
