INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51420f93-bd5b-4407-9772-2fc1eea591a1', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the difference between client-side and server-side in Nuxt?', N'Fresher', N'Server-side refers to the environment where the initial HTML is generated and data is fetched before the page is sent. Client-side refers to the browser, where the application becomes interactive and handles user events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a478b2b4-8e53-444e-9151-2fc60369c0bd', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you determine the complexity level of a task when the team has varying levels of experience?', N'Middle', N'I use relative sizing, such as story points, where the team discusses the complexity rather than the time. This allows the team to reach a consensus based on the effort required for a developer of average skill, accounting for the collective understanding of the task''s requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18a28fed-5222-4c4e-b4cb-2fc7291389a4', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the trade-offs of using PHP''s FPM (FastCGI Process Manager) compared to mod_php.', N'Middle', N'FPM decouples the PHP interpreter from the web server, allowing for independent scaling, better resource management, and the ability to run different pools with different user permissions. While mod_php is simpler to configure as a module, it is less secure and less flexible because it forces the web server process to handle all PHP execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95cb5e24-b1fa-4616-bf17-2fc9fb94a80c', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the difference between @Inject and @Value?', N'Fresher', N'@Inject is used for dependency injection to provide a bean, while @Value is used to inject configuration values from the application properties files into a field or method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c150ce3-3ebf-4dde-bede-2fcae02c6334', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the purpose of the WHERE clause in SQL?', N'Intern', N'The WHERE clause is used to filter records in a query. It specifies criteria that rows must meet in order to be included in the result set, allowing for targeted data retrieval.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09919efc-eb27-49c6-a9aa-2fcbfc444452', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you stay updated with new technologies and industry trends?', N'Junior', N'I follow technical blogs, participate in online developer communities, and occasionally work on small side projects to experiment with new tools. I also value discussing emerging patterns with my colleagues to understand what is being used in the industry.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97468d15-5fd0-4737-ae65-2fcd80399e19', N'954a0331-deff-4399-b588-96f39fec001d', N'How does Angular handle lazy loading of modules?', N'Middle', N'Lazy loading is a technique that loads feature modules only when the user navigates to the associated route. It reduces the initial bundle size, leading to faster application startup times and improved performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cadff63-d98c-42f6-bed0-2fcf1aff0a69', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why should you include a viewport meta tag in your HTML?', N'Junior', N'The viewport meta tag controls the layout on mobile browsers by setting the width and initial scale of the page. Without it, mobile browsers might render the page at a desktop width and zoom out, making content difficult to read.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd427e84-ada8-4ec5-8ad2-2fd3a19f35f4', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you ensure service-level agreement (SLA) compliance in a microservices system?', N'Senior', N'Monitor performance metrics at each service boundary and implement automated scaling based on defined thresholds. Additionally, enforce latency budgets for inter-service communication to ensure that the cumulative response time remains within the SLA.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'466c66a8-b3ba-4520-b10e-2fd540b9d120', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of the ''providedIn'' property in an injectable service?', N'Junior', N'The providedIn property specifies which injector should provide the service, usually set to root. This allows Angular to optimize the application by removing the service from the build if it is not used anywhere, a process known as tree-shaking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a38d3e2d-8096-4258-b0ae-2fd6681c042b', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is WAL in PostgreSQL?', N'Intern', N'WAL stands for Write-Ahead Logging. It is a standard method for ensuring data integrity by recording changes to data files in a log before the changes are actually applied to the database files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c29573af-e7d4-4ebb-b296-2fd735c75cc8', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What are the trade-offs of using a large number of shards in an Elasticsearch cluster?', N'Middle', N'While many shards allow for greater parallelization, they consume significant heap memory on the master node to manage metadata. Over-sharding can lead to increased overhead, slower cluster state updates, and decreased query performance due to the management burden on the cluster coordinator.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3c3985e-b167-4c71-8946-2fd8f9c306cb', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Does MongoDB support transactions?', N'Intern', N'Yes, MongoDB supports multi-document ACID transactions. While the database is document-based, these transactions allow developers to perform operations on multiple documents while ensuring data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'032501f0-cdd5-48d5-8848-2fdf8667c08c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the concept of ''Hydration'' in modern frameworks and its impact on Core Web Vitals.', N'Senior', N'Hydration is the process of attaching event listeners and state to server-rendered HTML so the page becomes interactive. If the hydration process is too heavy or blocked, it negatively impacts Interaction to Next Paint (INP) and First Input Delay (FID), even if the initial visual load is fast.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6f39bab-5c6d-4cf9-be48-2fe10a94a30d', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What happens if you omit the Webpack configuration file?', N'Fresher', N'Webpack will run using a default configuration. It will look for an entry file at a specific path and output the result to a default folder, but it is rarely sufficient for professional projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb0ac058-9585-465f-b9d7-2fe1545fc128', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go achieve concurrency?', N'Fresher', N'Go achieves concurrency through the use of Goroutines and channels. This follows the philosophy of sharing memory by communicating rather than communicating by sharing memory, which reduces race conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6d2aa39-d9f2-449f-b1ab-2fe1ab9fff15', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you write unit tests for JavaScript code?', N'Fresher', N'To write unit tests for JavaScript code, you typically use a testing framework like Jest or Mocha. First, you set up your testing environment by installing the necessary libraries. Then, you write test cases using functions like describe, it, or test to define your tests. Each test case should focus on a small, isolated piece of functionality. You use assertions to check if the output of your code matches the expected result. Example using Jest: ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the concept of test-driven development (TDD) Test-driven development (TDD) is a software development approach where you write tests before writing the actual code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1d2f733-1d9f-4139-ac5a-2fe26f1e0ae1', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R''s method dispatch handle multiple inheritance in the S4 system?', N'Senior', N'S4 uses a class precedence list to manage multiple inheritance, where the order of inheritance defines the search path for methods. This allows developers to resolve ambiguities systematically when a generic function is called with an object that inherits from multiple base classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bd39a8e-d33b-4529-a51f-2fe31cfc1351', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the primary benefit of using static typing?', N'Intern', N'Static typing allows errors to be detected at compile-time rather than runtime. This leads to more reliable code and better developer tooling support, such as autocompletion and easier refactoring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f32b8510-eecf-4bb0-8b3a-2fe33187ee65', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the default port for a Fiber application?', N'Fresher', N'Fiber does not enforce a default port, but it is standard practice to define one when starting the server. If no port is specified, it may default to 3000 depending on the environment configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0461e8a-22d3-412a-b39d-2fe4e915eefa', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Describe the trade-offs of Go''s static linking strategy.', N'Senior', N'Static linking results in self-contained binaries that simplify deployment and eliminate ''dependency hell'' across different environments. The trade-offs are larger binary sizes and the inability to update shared libraries independently without recompiling and redeploying the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'608618da-75bd-41bc-9f0b-2fec1320180a', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are the trade-offs of using dynamic dispatch with trait objects?', N'Middle', N'Dynamic dispatch, or vtable lookup, allows for heterogeneous collections and runtime polymorphism, which increases flexibility. However, it incurs a small performance penalty due to pointer indirection and prevents the compiler from inlining function calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bccfa1c0-d2d8-42ae-8965-2fed629f94a0', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'When should you choose On-Demand mode over Provisioned capacity mode?', N'Middle', N'On-Demand mode is ideal for workloads with unpredictable or sporadic traffic patterns where you do not want to manage capacity planning. Provisioned mode is generally more cost-effective for steady-state or predictable workloads where you can accurately forecast your throughput needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19a76efe-6003-41c6-ace2-2fedcca0eb66', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro handle static site generation versus server-side rendering?', N'Junior', N'Astro supports both modes. Static site generation builds all HTML pages at build time for maximum speed, while server-side rendering generates HTML on the server for each request, which is useful for pages with dynamic or personalized data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb9d6b4a-b75c-417b-b6b0-2fede7157c95', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How can you schedule tasks in NestJS?', N'Fresher', N'Task scheduling allows you to schedule arbitrary code (methods/functions) to execute at a fixed date/time, at recurring intervals, or once after a specified interval. Nest provides the @nestjs/schedule package, which integrates with the popular Node.js cron package. 1. To implement scheduling, you can install the required dependencies. 2. Then, import the ScheduleModule into your module: 3. Now, you can use the decorators in your service to schedule tasks. Here''s an example: In the above example, handleCron() will be called every 5 seconds. The @Cron() decorator takes a CronExpression which determines the schedule. Remember, the ScheduleModule uses the node-schedule package under the hood, so you can use any cron expression that node-schedule supports.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dddf2fb9-2224-4481-8372-2fee58a91150', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why might you choose a ''Column-oriented Database'' over a ''Row-oriented Database''?', N'Middle', N'Column-oriented databases are optimized for analytical workloads where queries aggregate data across specific columns rather than retrieving entire records. They provide much higher compression ratios and faster performance for large-scale data analysis by reading only the necessary columns from storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5644b5d7-393b-49a7-8daf-2ff0d39b78c6', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Explain the concept of ''distributed tracing'' and why it is necessary.', N'Middle', N'Distributed tracing tracks a single request as it travels across various microservices. It is necessary because it allows developers to visualize the entire request lifecycle, making it easier to identify which specific service is causing latency or errors in a complex architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e64a2ee5-d15c-4381-8200-2ff1150cfdaa', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue''s ''Teleport'' component interact with the DOM and CSS scoping?', N'Senior', N'Teleport renders component content into a different DOM node outside the parent component''s hierarchy while maintaining the component''s logical context and reactivity. It does not affect CSS inheritance, so scoped styles defined within the teleported component remain attached to the component''s own scope regardless of where it is injected in the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92f6e58d-1b3a-4cfb-b31f-2ff33be023e5', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI integrate with database ORMs while maintaining asynchronous performance?', N'Senior', N'FastAPI integrates with asynchronous drivers for ORMs like SQLAlchemy or Tortoise. By ensuring the entire chain of communication—from the event loop to the database driver—is asynchronous, it prevents the thread-blocking common in traditional synchronous database interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0c04c16-3056-46b8-aedd-2ff456ad6ce5', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the concept of an ''Item'' in DynamoDB?', N'Intern', N'An item is a single record within a table, consisting of one or more attributes. It is similar to a row in a relational database, but each item can contain different attributes from others in the same table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e64aedf-3749-4cfc-8bf3-2ff50a433f59', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the architectural benefit of using ''LitElement'' over standard vanilla Web Components?', N'Senior', N'LitElement provides a high-level abstraction that handles the boilerplate of property observation, attribute reflection, and efficient DOM rendering. It encapsulates these low-level API complexities, allowing developers to focus on declarative state management while maintaining the interoperability of standard Web Components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40df8bb4-f2cd-4309-bdb0-2ffc7ee57b45', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you prioritize multiple tasks of equal urgency?', N'Intern', N'I would look at which task has the largest dependency impact on the rest of the team. If one task unblocks a colleague or a subsequent phase of a project, I would prioritize that one to ensure overall team productivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a3b0b61-c36f-41af-a858-2ffd5fa54891', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Explain the performance implications of having a high density of Alpine directives on a single page.', N'Senior', N'Since Alpine initializes components by traversing the DOM tree, having too many directives can increase the time-to-interactive during the initial script execution. While the framework is optimized, deep nesting or excessive reactivity tracking can lead to performance bottlenecks if not managed with lazy initialization techniques.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'513dadcd-6329-44ec-a47f-2fff33cb5bda', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why does Vite use Rollup for production builds?', N'Fresher', N'Vite uses Rollup for production because it is a highly efficient module bundler that performs advanced optimizations like tree-shaking and minification. These processes ensure that the final bundle is as small and performant as possible for the end-user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'238253a9-9801-45e5-98c9-3000b1f01579', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the ''hono/adapter'' concept?', N'Junior', N'Adapters are the glue code that allows Hono to run on different platforms like Node.js, Cloudflare Workers, or Vercel. They translate the platform-specific request and response objects into the standard Web API formats that Hono uses internally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98c5c42c-f28c-40e0-a058-3002c4d55e6c', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How do jQuery plugins affect the extensibility of an application?', N'Middle', N'Plugins allow for rapid implementation of features like sliders or date pickers, but they can lead to dependency hell if they are not well-maintained. Relying on too many plugins creates a rigid architecture that is hard to customize, as you are bound to the plugin''s internal implementation choices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c866d56-4d60-458c-8cf1-30080ba67b1e', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Does Astro support Markdown out of the box?', N'Fresher', N'Yes, Astro has built-in support for Markdown files. You can create .md or .mdx files within the pages directory, and Astro will automatically convert them into web pages using its internal routing system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf5e9745-d785-4367-b51a-30089564c20f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the time taken to execute below timeout callback?', N'Intern', N'- 1: > 10 sec - 2: Immediately - 3: Answer Answer: 1 Even though there is a timer of 5 seconds supplied to setTimeout callback, it won''t get executed until the main thread is free and finished executing the remaining part of the code. In this example, the remaining code(while loop) takes 10seconds to finish it''s execution. In the mean time, the callback will be stored in callback queue upon completion of its 5 seconds timer. After 10 seconds, the callback will be moved to callstack because the callstack is empty by poping out global execution context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a559f1a0-925b-492f-a150-300a75d9bdc0', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How do goroutines differ from OS threads in terms of memory and context switching?', N'Middle', N'Goroutines are multiplexed onto a small number of OS threads and start with a tiny, growable stack that begins at a few kilobytes. This allows Go to support millions of concurrent goroutines, whereas OS threads have a fixed, larger stack size and are much more expensive to create and context switch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22afba2c-d06a-4efa-97d1-3011c0d8c8de', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the primary benefit of using Chi''s middleware stack?', N'Fresher', N'Chi''s middleware stack allows you to wrap handlers with shared functionality like logging, recovery, or authentication. Because it adheres to the standard http.Handler interface, it is highly modular and easy to chain together.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8801cac-cda4-48e4-bff2-3013f898b186', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind help with design consistency?', N'Intern', N'Tailwind provides a predefined design system for spacing, colors, and typography by default. Using these standardized values ensures that your UI remains consistent without needing to manually define every value in your CSS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'176f9092-2b53-45df-a94c-3015194e1e99', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is Coercion in JavaScript?', N'Intern', N'Type coercion is the automatic or implicit conversion of values from one data type to another (such as strings to numbers). Type conversion is similar to type coercion because they both convert values from one data type to another with one key difference — type coercion is implicit whereas type conversion can be either implicit or explicit. Example: In the above example, JavaScript has coerced the 10 from a number into a string and then concatenated the two values together, resulting in a string of 1020. JavaScript had a choice between a string or a number and decided to use a string.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfc49691-63ce-408a-b1e7-3017b423a7f2', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the difference between async mode and concurrent mode?', N'Fresher', N'Both refers the same thing. Previously concurrent Mode being referred to as "Async Mode" by React team. The name has been changed to highlight React’s ability to perform work on different priority levels. So it avoids the confusion from other approaches to Async Rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3dcd6546-d87d-439a-8747-3019ad320766', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why is ''Denormalization'' a standard design pattern in DynamoDB?', N'Senior', N'Because DynamoDB lacks relational joins, denormalization reduces the need for multiple round-trips to the database. By embedding related data or duplicating it across items, you optimize for read performance at the cost of increased complexity during write updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62ef6bfe-87f2-4869-b9ce-3019bfa45666', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the role of Providers in NestJS?', N'Fresher', N'Providers are a fundamental concept in NestJS that can be injected as dependencies into classes. They are classes annotated with the @Injectable decorator and are responsible for business logic, data access, or service interaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'357ed23f-192e-4798-a696-301a98b199b0', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does the COMMIT command do?', N'Fresher', N'The COMMIT command is used to permanently save the changes made during the current transaction. Once a transaction is committed, the modifications are visible to other users and cannot be rolled back.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8c58c75-679e-4b6e-bd10-301d350a2659', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB handle data types compared to JSON?', N'Fresher', N'While JSON only supports basic types like strings, numbers, and booleans, BSON adds support for additional types like dates, binary data, and object IDs. This makes BSON more suitable for database operations than plain JSON.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90c2153e-5947-4d1d-982d-301dba972145', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the Micronaut Application Context?', N'Fresher', N'The Application Context is the central container that holds all the beans and manages their lifecycles. It is responsible for dependency injection, configuration binding, and event handling within the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5195189-0a40-4b20-a926-301e34370c89', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Explain the ''memoization'' mechanism in SolidJS.', N'Senior', N'createMemo creates a derived signal that caches its value until one of its underlying dependencies changes. It is highly efficient for heavy computations, ensuring that expensive logic is only re-evaluated when necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17068af1-4a08-415b-afdd-301f0166bdde', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the ''extend'' directive in Sass?', N'Intern', N'The @extend directive allows one selector to inherit the styles of another selector. It is useful for sharing common properties between elements without having to apply multiple classes to the HTML markup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ece9259-376d-442a-93b2-301fad6843ce', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle error boundaries compared to standard React error boundaries?', N'Senior', N'Remix provides route-specific ErrorBoundary components that catch errors occurring during data loading or rendering for that segment of the tree. This allows for isolated failure modes, ensuring that an error in a secondary route does not crash the entire application layout.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21bffeab-493c-4c43-b70d-3022b72da81c', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off involved in adding more automated tests to a project?', N'Fresher', N'Adding tests increases long-term code quality and reduces regression bugs, but it consumes significant development time upfront. You must balance the cost of writing and maintaining the test suite against the risk of shipping bugs to users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebc78ca8-b084-4b20-a6d1-30247e3239cd', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does the Axum ''Router'' composition allow for better architectural scaling?', N'Senior', N'Router composition allows developers to split large APIs into smaller, logical modules that can be developed and tested independently. By merging these routers at the root, the application maintains a clean hierarchical structure that is easier to navigate and maintain as the codebase grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70c88082-4f22-4fca-a4e3-3027360ac66a', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are streams in Node.js and what types are available?', N'Intern', N'Node.js utilizes streams for efficient handling of input/output data, offering two main varieties: readable and writable. Categories of Streams 1. Standard Streams: Represent standard input, output, and error. These are instances of Readable or Writable streams. 2. Duplex Streams: Facilitate both reading and writing. They can be connected to processes or handling pipelines. 3. Transform Streams: A special type that acts as an intermediary, modifying the data as it passes through. Practical Implementations - HTTP Transactions: HTTP clients use readable and writable streams for sending requests and receiving responses. HTTP servers also apply these streams for similar actions in the opposite direction. - File System: Reading and writing files in Node.js utilizes these streams.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1d795c4-6d10-40fc-96fb-3028d02a678b', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Discuss the architectural considerations for implementing a multi-tenant system in Laravel.', N'Senior', N'Multi-tenancy can be implemented via a single database with a tenant_id column or separate databases per tenant. The latter provides better data isolation and security but increases operational complexity, requiring dynamic connection switching and schema management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec4779bf-ac92-410f-aab6-302c37b03d8a', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why might you choose to use an alias instead of an index name in your application?', N'Middle', N'Aliases provide an abstraction layer that allows you to swap underlying indices without changing your application code. This is essential for zero-downtime operations like index rollovers or performing reindexing tasks in the background.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af16445c-becd-431f-8ca0-302f9f536d00', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a Proper Tail Call', N'Intern', N'First, we should know about tail call before talking about "Proper Tail Call". A tail call is a subroutine or function call performed as the final action of a calling function. Whereas Proper tail call(PTC) is a technique where the program or code will not create additional stack frames for a recursion when the function call is a tail call. For example, the below classic or head recursion of factorial function relies on stack for each step. Each step need to be processed upto n * factorial(n - 1) But if you use Tail recursion functions, they keep passing all the necessary data it needs down the recursion without relying on the stack. The above pattern returns the same output as the first one.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb6d88a8-74f0-4e45-a138-30327d041a53', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you list all properties of an object', N'Fresher', N'You can use the Object.getOwnPropertyNames() method which returns an array of all properties found directly in a given object. Let''s see the usage of this in an example below:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81c1c3e6-d075-4868-820d-303280f3d48c', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Why is ''Database per Service'' a recommended pattern for microservices?', N'Middle', N'This pattern ensures loose coupling by preventing services from accessing another service''s private data directly. It allows each service to choose the most appropriate database technology for its specific workload and enables independent scaling and schema evolution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb0e6956-dc9c-4b85-bfd1-30333ecafb01', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between an element and a tag?', N'Intern', N'A tag is the bracketed part used to mark the start or end of an element, such as a paragraph tag. An element includes the opening tag, the closing tag, and all the content in between, representing a complete component of the document structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c043fb6-836e-46b0-a830-30365af5d791', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why does Vite prefer ''import.meta.env'' over ''process.env''?', N'Senior', N'Vite adheres to the ECMAScript standard for environment variables using import.meta.env, which is natively supported in modern browsers. Process.env is a Node.js-specific global that requires polyfilling or emulation in a browser context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf7e1868-2036-492c-a8ef-3037c1db2479', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What does it mean to perform a binary search when debugging a production issue?', N'Junior', N'This involves splitting the system or the timeline of deployments into halves to narrow down where the error was introduced. By checking if the problem exists in an older version or a different environment, you can systematically eliminate large sections of the application until the source is found.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b0db0ae-81e3-4729-a2b9-3037de49bdc9', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of the ''entry'' configuration property?', N'Junior', N'The entry property tells Webpack which module it should use to begin building its internal dependency graph. From this entry point, Webpack figures out which other modules and libraries the entry point depends on.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'862ef459-f240-4bfa-8837-303b8b19038b', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the significance of the ''Echo'' instance?', N'Fresher', N'The Echo instance is the main entry point of the application. It acts as the central hub where routes are defined, middleware is registered, and the HTTP server is started to listen for incoming traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0263bcc4-e7d8-4c95-93d6-303c2bfc60da', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Describe the function and necessity of the ''Commit Log'' in Cassandra''s durability model.', N'Senior', N'The Commit Log acts as a crash-recovery mechanism, capturing all mutations to disk before updating the memtable. It ensures that data is not lost if a node crashes before the memtable is flushed to an SSTable, providing atomic durability for writes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'add68b66-30da-4b03-b5d9-303df9b40d20', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the purpose of the ''typedef'' keyword in Dart?', N'Fresher', N'The typedef keyword is used to create an alias for a function signature. It makes code more readable by allowing you to define a meaningful name for a specific function type that is used in multiple places.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b339de7a-fe4c-4f86-862c-303fc7830d50', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you ensure observability in a system that is deployed across multiple cloud regions?', N'Senior', N'I would implement centralized logging, metrics aggregation, and distributed tracing that spans all regions. I would use a unified dashboarding tool to monitor health across all environments, ensuring that alerts are aggregated and normalized to provide a single pane of glass for incident response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba69a3aa-7794-42fa-9107-3041c91b250d', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the function of the $lib alias in SvelteKit?', N'Fresher', N'The $lib alias points to the src/lib directory, which is the standard location for shared code, components, and utility functions. Using $lib makes it easy to import files from this directory without writing complex relative file paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
