INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'667bf40d-cc65-45c3-82c6-3042562e2c57', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Explain the difference between Nuxt''s ''Universal Rendering'' and traditional Single Page Application (SPA) rendering.', N'Senior', N'Universal rendering executes the initial request on the server to generate HTML, providing faster Time to First Byte and better SEO, before hydrating into a client-side SPA. A traditional SPA relies entirely on the client-side JavaScript engine to fetch data and construct the DOM, which can lead to layout shifts and poor crawlability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4b84f8a-a9ca-49d5-856d-3042a268348c', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the primary purpose of using Sass in web development?', N'Junior', N'Sass is a CSS preprocessor that extends CSS with features like variables, nested rules, and mixins. It helps make stylesheets more maintainable, organized, and efficient to write compared to standard CSS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1198098b-92b0-4a85-a0bb-3043b3b126ca', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'In the context of Phoenix LiveView, what is the ''stateful'' transition and how does it impact server memory consumption?', N'Senior', N'LiveView maintains a persistent process on the server for every client tab, holding the view''s state in memory. While this enables rich interactivity without complex frontend state management, it places a higher memory burden on the server compared to stateless APIs, requiring careful monitoring of process counts and memory limits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac77ebaf-661c-4b61-909a-30467dad2436', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the relevance score in Elasticsearch?', N'Junior', N'The relevance score, or _score, is a numerical value that represents how well a document matches a specific search query. Higher scores indicate a better match based on the underlying scoring algorithm, typically BM25.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
