INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31bb5412-07ae-4a59-8522-304b0531d159', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of the ''Unsafe'' pointer suite in Swift?', N'Senior', N'The Unsafe pointer suite provides direct memory access for interoperability with C or high-performance low-level operations. It bypasses Swift’s safety guarantees, placing the responsibility on the developer to manage memory lifetimes and pointer validity, which is necessary when working outside the high-level memory management model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f9cdb60-8cbf-407e-86ce-3053bf49b71f', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How do you handle exceptions globally in a Quarkus REST application?', N'Junior', N'Quarkus supports the JAX-RS ExceptionMapper interface, which allows you to define a class that catches specific exceptions and translates them into appropriate HTTP responses. By implementing this interface and annotating it with @Provider, the application can handle errors consistently across all endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5420cacb-a598-4688-a034-305416529669', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why is the Repeatable Read isolation level insufficient for preventing phantom reads?', N'Middle', N'Repeatable Read ensures that if a row is read twice, the values remain the same, but it does not prevent new rows from being added to the range by another transaction. Phantoms occur because standard row-level locking does not lock the entire range of data, allowing new entries to appear between subsequent queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c4bd72c-7c55-4013-a2ac-30541679c114', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does the ''Modifier'' API improve DOM manipulation compared to traditional component lifecycle hooks?', N'Senior', N'Modifiers provide a specialized, reusable way to attach behavior to DOM elements, such as third-party library integrations or complex event handling. By separating this logic from the component''s state management, modifiers make the code more modular and prevent the component from becoming bloated with DOM-specific concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac2aad19-927d-4b63-b3ea-30545e3245ce', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the architectural risks of dynamic scoping in language design and how R avoids it.', N'Senior', N'Dynamic scoping can lead to unpredictable behavior where a function''s outcome depends on the caller''s stack, making it difficult to debug. R strictly enforces lexical scoping, where variable lookup is determined by the function''s definition scope, ensuring consistent and predictable execution paths regardless of the call site.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f0a889d-872a-43e3-a402-30557191c70a', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web achieve zero-cost abstractions through Rust''s type system?', N'Senior', N'Actix-web leverages Rust''s trait system and static dispatch to avoid runtime type checking and dynamic allocation where possible. By defining handlers as generic types that implement specific traits, the compiler can inline code paths, significantly reducing function call overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28b36b15-c7e6-4368-87fa-30564c98a3ab', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the purpose of the ''render'' function in Preact?', N'Fresher', N'The render function is the entry point that mounts a Preact component into the actual browser DOM. It takes the virtual tree and the target container element as arguments to display the interface to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c02d06eb-e6ea-4624-9958-3056fedb1f59', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the reason behind multiple JSX tags to be wrapped?', N'Intern', N'Behind the scenes, JSX is transformed into plain javascript objects. It is not possible to return two or more objects from a function without wrapping into an array. This is the reason you can''t simply return two or more JSX tags from a function without wrapping them into a single parent tag or a Fragment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31d13d3e-35ed-4aa1-bd36-30585f64e7ec', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If you are working on a feature and realize the requirements are incomplete, what do you do?', N'Junior', N'I would stop further development on that specific part and reach out to the project manager or stakeholder to clarify the requirements. It is better to pause and get the right information than to build a feature that doesn''t meet user needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8f9597b-0f98-466b-a94c-3058b800dc3e', N'954a0331-deff-4399-b588-96f39fec001d', N'What is hydration?', N'Intern', N'Hydration is the process that restores the server side rendered application on the client. This includes things like reusing the server rendered DOM structures, persisting the application state, transferring application data that was retrieved already by the server, and other processes. To enable hydration, we have to enable server side rendering or Angular Universal. Once enabled, we can add the following piece of code in the root component. Alternatively we can add providers: [provideClientHydration()] in the App Module', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c5ea208-ceb4-44d4-ade7-30591043da11', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What criteria do you use to select a database technology for a new feature?', N'Senior', N'I evaluate the specific access patterns, such as read-heavy versus write-heavy workloads, and the need for relational integrity versus schema flexibility. I consider the operational overhead of managing the database, the availability of managed services, and how well the data model aligns with the application''s query requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a73218b-fbf4-46a3-80aa-305acc589838', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of the AdonisJS ''Ace'' CLI?', N'Fresher', N'Ace is the command-line interface tool provided by AdonisJS to help developers manage their applications. It is used to generate boilerplate code, run database migrations, start the development server, and execute custom console commands.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f151d602-c2f3-4067-830b-3060e2fb4460', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you notice a teammate is following an inefficient process, how do you handle it?', N'Junior', N'I would approach them privately and in a supportive manner to share an alternative approach or tool that I have found useful. I would frame the conversation as a suggestion for improvement rather than a critique of their current method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4886a8a0-a28b-49f9-a20b-3062235c625f', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Discuss the impact of R''s type system on performance-sensitive code.', N'Senior', N'R''s dynamic typing requires the engine to perform type-checking during runtime, which adds overhead to every operation. To maximize performance, developers must often use type-stable code and interface with typed foreign languages like C++ to bypass R''s dynamic dispatch and boxing of primitives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d383601-e8f5-4320-8d44-30629c8fa731', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are ''Hooks'' in Hono?', N'Intern', N'Hooks are lifecycle functions that allow developers to run logic at specific moments during the request processing flow. They are often used for validation or data transformation before the main handler is reached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'616a6ea6-d78c-44e5-8942-306391f6c2c7', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why might you prefer Svelte over a framework like Vue?', N'Middle', N'Svelte is often preferred for projects where minimal bundle size and runtime performance are critical, as it eliminates the need for a virtual DOM. While Vue is powerful and feature-rich, Svelte''s compilation-first approach offers a unique architectural advantage for resource-constrained environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6efa977-b831-4242-a22c-3063a7fe06af', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is a frozen set in Python?', N'Intern', N'Answer these type of Python Interview Questions with Examples. First, let''s discuss what a set is. A set is a collection of items, where there cannot be any duplicates. A set is also unordered. myset={1,3,2,2} myset {1, 2, 3} This means that we cannot index it. myset[0] Traceback (most recent call last): File " ", line 1, in myset[0] TypeError: ''set'' object does not support indexing However, a set is mutable. A frozen set is immutable. This means we cannot change its values. This also makes it eligible to be used as a key for a dictionary. myset=frozenset([1,3,2,2]) myset frozenset({1, 2, 3}) type(myset)', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7c0af3b-0bd1-4202-a6b4-30663e3f3144', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are some drawbacks of the Python language?', N'Intern', N'The two most common valid answers to this question are: - The Global Interpreter Lock (GIL). CPython (the most common Python implementation) is not fully thread safe. In order to support multi-threaded Python programs, CPython provides a global lock that must be held by the current thread before it can safely access Python objects. As a result, no matter how many threads or processors are present, only one thread is ever being executed at any given time. In comparison, it is worth noting that the PyPy implementation discussed earlier in this article provides a stackless mode that supports micro-threads for massive concurrency. - Execution speed. Python can be slower than compiled languages since it is interpreted. (Well, sort of. See our earlier discussion on this topic.)', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ab4e1c5-6cad-4dd7-9fe2-30697013938f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the primary difference between a compiled language and an interpreted language in the context of Dart?', N'Fresher', N'Dart supports both Ahead-of-Time compilation, which produces machine code for fast startup, and Just-in-Time compilation, which allows for fast development cycles. This hybrid approach enables the hot reload feature during development and high performance in production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b647224a-869a-4815-9099-3069eb42cb89', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What are the performance implications of using Gin''s logger middleware in high-traffic applications?', N'Middle', N'The default logger writes to standard output for every request, which can become an I/O bottleneck under extremely high load. In such cases, it is better to use an asynchronous logger or a high-performance structured logger like Zap or Zerolog to minimize the latency overhead per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db2d1de0-7a65-49f4-8c4c-306e524a5f4b', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of ''Dynamic Mapping'', and why is it often discouraged in production?', N'Senior', N'Dynamic mapping automatically detects field types upon indexing, which is convenient for prototyping. In production, it is discouraged because it can lead to mapping explosions, incorrect type inference, and inefficient storage, as the system might map a field as text when it should be a keyword.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fedeb911-9e1b-4fb0-9098-306e8c58e165', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does a transaction log help with Durability?', N'Junior', N'The database records all changes in a transaction log before applying them to the actual data files. If the system crashes, the database can use this log to recover completed transactions or undo incomplete ones.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aeac2d16-4fad-4fbd-aa0e-306f40b20348', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What does it mean that Go is a statically typed language?', N'Intern', N'Being statically typed means that the type of every variable is known at compile time. This allows the compiler to detect type-related errors before the program is executed, leading to safer and more reliable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0af9a9c2-533e-4247-a9f6-306f4704a30d', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Why is immutability preferred in Scala''s concurrency model, and how does it relate to shared memory?', N'Senior', N'Immutability eliminates the need for locks or synchronization primitives because immutable objects cannot change their state once created, making them inherently thread-safe. This simplifies reasoning about concurrent systems and allows the runtime to safely share data across threads without the risk of race conditions or deadlocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4812c4b-164b-46a8-9ca0-3075eb9cd296', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you handle failure in a microservice?', N'Senior', N'In a microservices architecture, multiple smaller components, or microservices, work together to deliver an application. Consequently, a failure in one of the services can have downstream effects, potentially leading to system-wide failure. To address this, several best practices and resilience mechanisms are implemented. Best Practices for Handling Failure Fault Isolation - Circuit Breaker Pattern: Implement a circuit breaker that isolates the failing service from the rest of the system. This way, the failure doesn''t propagate and affect other services. - Bulkhead Pattern: Use resource pools and set limits on the resources each service can consume. This limits the impact of failure, ensuring that it doesn''t exhaust the whole system''s resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2f8292d-87b2-4737-ba5e-307717946771', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the role of an inverted index in search?', N'Junior', N'An inverted index is a data structure that maps terms to the documents that contain them. It is the core mechanism that allows Elasticsearch to perform extremely fast full-text searches by looking up terms rather than scanning every document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6df0c1c-8fe8-4259-b619-3078742d0c0d', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Are Sass comments preserved in the compiled CSS?', N'Fresher', N'Sass supports both single-line and multi-line comments. Multi-line comments are preserved in the compiled CSS, while single-line comments are stripped out, making them useful for internal developer notes that shouldn''t appear in production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3d140ab-0099-4113-a89a-3078da7e4e30', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the difference between a global middleware and a route-level middleware?', N'Junior', N'Global middleware is mounted using app.use() and executes for every request to the application. Route-level middleware is applied only to specific routes or routers, allowing for targeted logic like authentication for only certain endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25f380d8-5f72-4325-9d24-307bb5eae084', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Describe the difference between Doc Values and fielddata.', N'Senior', N'Doc Values are a disk-based, column-oriented storage format used for sorting and aggregations, designed to be memory-efficient. Fielddata is an in-memory structure that performs a similar function but is highly expensive in terms of heap usage and is generally discouraged for text fields due to its high memory requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acad64b2-615f-45ed-b068-307f95126ad0', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is a Template in Ember?', N'Intern', N'A template in Ember is a file that defines the structure and layout of the user interface using Handlebars syntax. It describes how the data should be displayed to the user and includes logic for conditionally showing elements or iterating over lists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a0f773c-a75e-45c4-9b0e-308063c59b44', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack handle multiple versions of the same library?', N'Senior', N'Webpack treats every module as a separate node in the dependency graph, so if different entry points or dependencies request different versions, Webpack will include both versions in the bundle. This leads to increased bundle size and potential runtime conflicts, which should be resolved by enforcing singleton dependencies via package management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8e1ca6f-a9ae-4adb-809a-30845c5a37b2', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is covariant return type?', N'Intern', N'It is possible to have different return type for a overriding method in child class, but child''s return type should be sub-type of parent''s return type. Overriding method becomes variant with respect to return type. The covariant return type specifies that the return type may vary in the same direction as the subclass. Example: Output:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41db15bd-bcfc-4cf4-adfb-3085f6a6a0bd', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How are query parameters accessed in an Echo handler?', N'Junior', N'Query parameters are retrieved from the Context object using a query method that takes the parameter name as an argument. This allows the application to dynamically adjust its logic based on the URL query string.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
