INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fd06e74-a974-4e1d-9787-30935de82806', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the significance of the null terminator in strings?', N'Intern', N'In C, strings are represented as character arrays terminated by a special null character. This character signals to functions that the string has ended, preventing memory access errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'136b859f-1242-42b7-b036-3093a99c4329', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is an event flow', N'Intern', N'Event flow refers to the order in which events are handled in the browser when a user interacts with elements on a webpage like clicking, typing, hovering, etc. When you click an element that is nested in various other elements, before your click actually reaches its destination, or target element, it must trigger the click event for each of its parent elements first, starting at the top with the global window object. Hence, there are three phases in JavaScript’s event flow: 1. Event Capturing(Top to Bottom): The event starts from the window/document and moves down the DOM tree toward the target element. 2. Target phase: The event reaches the target element — the element that was actually interacted with. 3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc4f2d45-012b-472b-8ce6-3095033f6de2', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the benefit of using ''IHttpClientFactory'' over ''HttpClient''?', N'Middle', N'IHttpClientFactory manages the underlying HttpClientHandler instances to prevent socket exhaustion and DNS issues. It also integrates with Polly for handling transient faults, such as retries and circuit breakers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80129a4c-552d-44a6-9f1c-309a49ea6f15', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How do you handle database connection pooling in a Django application deployed with Gunicorn?', N'Middle', N'Django does not have built-in connection pooling, as it typically opens and closes a connection per request. For high-traffic applications, you should use an external tool like PgBouncer to manage a pool of persistent connections between the application server and the database. This significantly reduces the overhead of establishing new TCP connections for every request, improving overall latency and throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
