INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfd5c0b9-5c0c-42f5-853f-30a23f83039e', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why does Ember use a virtual DOM concept?', N'Intern', N'Ember uses a virtual DOM approach to minimize direct interactions with the browser''s actual DOM, which is slow. By calculating the difference between the current state and the new state, it only updates the specific parts of the page that have changed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac90baed-28f2-4521-b610-30a2fc7e5994', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik manage code size growth as an application scales?', N'Middle', N'Qwik''s architecture ensures that the amount of JavaScript sent to the client is proportional to the number of interactions performed, not the size of the application. This prevents the ''bundle bloat'' commonly seen in large-scale applications built with standard frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c918c9e-b949-4801-aef4-30a59b658ee9', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why is it important to tune the heap size for Elasticsearch nodes?', N'Middle', N'Elasticsearch is highly dependent on the JVM heap for caching and search operations, but it also relies on off-heap memory for Lucene segments. If the heap is set too high, there is insufficient memory for the operating system''s filesystem cache, which degrades overall performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
