INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5630dc9c-2a73-4c86-8a6b-30aaed37136e', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the difference between precision and accuracy in the context of estimation?', N'Intern', N'Accuracy refers to how close an estimate is to the true or actual value, while precision refers to the level of detail or consistency in the estimate. An estimate can be highly precise, such as giving a number to several decimal places, while still being entirely inaccurate if the underlying assumptions are flawed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
