INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f46e5e2-44ef-490a-a064-30ae5cb82943', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of the Django ORM and how does it abstract database interactions?', N'Fresher', N'The Django Object-Relational Mapper (ORM) allows developers to interact with database records using Python classes instead of writing raw SQL queries. It automatically maps Python objects to database tables, enabling operations like creating, retrieving, updating, and deleting data through simple method calls. This abstraction helps keep the code database-agnostic, making it easier to switch between different database engines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba24860d-821d-4032-b897-30aec4bac82f', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle routing compared to basic Go web servers?', N'Fresher', N'Fiber uses an optimized routing engine that supports path parameters, wildcards, and regex-based matching out of the box. Unlike the standard library, which requires more manual parsing for complex routes, Fiber provides a declarative and expressive syntax.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80d20f6a-8aec-4fcd-9449-30b1719f73a6', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the difference between an Element and a Component?', N'Fresher', N'Element: - A React Element is a plain JavaScript object that describes what you want to see on the UI. It represents a DOM node or a component at a specific point in time. - Elements are immutable: once created, you cannot change their properties. Instead, you create new elements to reflect updates. - Elements can be nested within other elements through their props. - Creating an element is a fast, lightweight operation—it does not create any actual DOM nodes or render anything to the screen directly. Example (without JSX): Equivalent JSX syntax: The object returned by React.createElement: Elements are then passed to the React DOM renderer (e.g., ReactDOM.render()), which translates them to actual DOM nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d3b5f3b-bfb7-4b2a-b523-30b1aa400247', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why might you prefer Axum over Actix-web for a new project?', N'Middle', N'Axum provides a more idiomatic experience by leveraging Tower and the standard Hyper ecosystem, leading to better compatibility with generic Rust libraries. Its design prioritizes type safety and composability, which many developers find more intuitive for long-term project maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7c504b3-12d9-4cb2-9ad4-30b243f13a73', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What architectural problem does ''SplitChunksPlugin'' solve, and what are the risks of over-optimizing chunk sizes?', N'Senior', N'It solves the issue of code duplication and caching inefficiency by extracting common dependencies into shared bundles. However, over-splitting can lead to an excessive number of HTTP requests, which may degrade performance on networks with high latency due to the overhead of establishing connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2467d82b-d02c-4d30-8838-30b3714ccca1', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS handle CORS (Cross-Origin Resource Sharing)?', N'Fresher', N'CORS (Cross-Origin Resource Sharing) is a mechanism that allows many resources (e.g., fonts, JavaScript, etc.) on a web page to be requested from another domain outside the domain from which the resource originated. In the context of web development, an API server runs on a different domain or port from the client-side web application. For security reasons, browsers prohibit web pages from making requests to a different domain than the one the web page came from, unless the server supports CORS. By enabling CORS on the server, you''re allowing the server to respond to cross-origin requests. This means that your server''s resources can be accessed from a different domain, protocol, or port than the one your server is hosted on.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09c87de6-67a7-4e42-a6d1-30b6abce5e7a', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the impact of a ''broadcast'' query in a sharded cluster?', N'Middle', N'A broadcast query occurs when the query criteria do not include the shard key, forcing the router to send the request to every shard in the cluster. This negatively impacts performance and scalability, as it consumes resources across all shards instead of targeting a specific subset.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1896fa0e-1b0c-4388-a4ee-30b8eff0de3c', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the role of the transaction log in supporting ''undo'' and ''redo'' operations?', N'Senior', N'Redo logs contain the information necessary to re-apply changes that were committed but not yet written to data files, ensuring durability. Undo logs store the previous values of modified data, allowing the system to roll back incomplete transactions during recovery or aborts, ensuring atomicity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
