INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f410195-7b02-4760-95cf-30bcdd88beb0', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the impact of Fiber''s architecture on horizontal scalability?', N'Senior', N'Fiber itself is stateless, which makes it highly suitable for horizontal scaling in containerized environments. By offloading state to external caches like Redis or databases, multiple Fiber instances can be deployed behind a load balancer to handle massive concurrent traffic loads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13a3ca86-f9b5-4288-944a-30bf2a55507b', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin ensure thread safety when using ''shared mutable state''?', N'Middle', N'Kotlin encourages immutability and the use of channel-based or actor-based communication to avoid shared state. If shared mutable state is unavoidable, developers are expected to use atomic variables, mutexes, or thread-safe collections to synchronize access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87d172a3-01d6-46a0-bb0a-30c3513ead67', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is horizontal scaling in the context of MongoDB?', N'Intern', N'Horizontal scaling, or sharding, involves distributing data across multiple servers or clusters. This allows MongoDB to handle larger datasets and higher throughput by adding more machines rather than just increasing the power of a single server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecd886e6-9fcf-4c38-b4a3-30c5015a52ec', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What are the trade-offs of using SolidJS''s fine-grained reactivity in large-scale applications?', N'Senior', N'The primary benefit is high performance and reduced memory overhead due to the lack of a Virtual DOM. However, the trade-off is the need for strict adherence to reactive patterns, such as avoiding destructuring reactive objects, which can lead to lost reactivity if not managed correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8335735-28ad-4424-9264-30c5a028afa7', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the significance of the ''createEffect'' primitive?', N'Fresher', N'The createEffect primitive is used to perform side effects in response to state changes. It automatically tracks any signals accessed within it and re-runs whenever those signals update.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb6e89b7-b33b-4481-b7d0-30c5aad43554', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the popular React-specific linters?', N'Intern', N'ESLint is a popular JavaScript linter. There are plugins available that analyse specific code styles. One of the most common for React is an npm package called eslint-plugin-react. By default, it will check a number of best practices, with rules checking things from keys in iterators to a complete set of prop types. Another popular plugin is eslint-plugin-jsx-a11y, which will help fix common issues with accessibility. As JSX offers slightly different syntax to regular HTML, issues with alt text and tabindex, for example, will not be picked up by regular plugins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9c8b364-d6fe-4c49-b6ea-30c6e21eeb54', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'In what scenario would you choose Litestar over a framework like FastAPI?', N'Senior', N'Litestar is often chosen for its more rigorous, object-oriented design and cleaner separation of concerns, particularly in large enterprise applications. Its plugin architecture and DTO implementation provide a more structured approach to managing complex data models and dependencies compared to FastAPI''s functional-centric approach.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83dac1d7-1ac6-4d1e-86b0-30cc09c63254', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the primary purpose of Hono in the context of backend development?', N'Intern', N'Hono is a lightweight, high-performance web framework designed to be platform-agnostic. Its primary purpose is to allow developers to build web applications and APIs that can run seamlessly on various JavaScript runtimes, such as Node.js, Cloudflare Workers, and Bun, using a unified API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0670711-429a-4abd-a9b7-30cc793e1d9b', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does C# implement interface dispatch, and what is the cost of interface-based polymorphism?', N'Senior', N'C# uses a Virtual Method Table (vtable) and an Interface Method Table (itable) to resolve method calls at runtime. Interface calls are slightly more expensive than direct or virtual calls because the runtime must perform a lookup in the itable to find the correct method implementation, which can negatively impact branch prediction and CPU cache efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e610bb3-f0d4-416c-ae5b-30ccefa79aad', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the trade-off between using Phoenix LiveView versus traditional REST APIs for a dynamic web application?', N'Middle', N'LiveView provides a more fluid user experience by handling UI updates on the server and pushing only binary diffs over a WebSocket, reducing frontend complexity. However, it requires a persistent connection for every user, which increases server memory usage compared to the stateless nature of REST APIs, which scale horizontally more easily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69a82445-e980-4f7e-8af5-30ce11f4464c', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your process for balancing the need for rapid feature delivery with the necessity of maintaining high system availability?', N'Middle', N'I rely on a robust CI/CD pipeline with automated testing and canary deployments to minimize risk. By breaking features into smaller, deployable chunks, I can monitor system health in real-time and roll back immediately if metrics deviate from established baselines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80a5c812-3cfa-483e-ad23-30d0e2ae363a', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the purpose of the ExecutionContext in NestJS Middleware?', N'Fresher', N'ExecutionContext can be used to access the Request and Response objects, or any other details about the current request-response cycle. This can be useful for tasks like logging, validation, transformation, and other operations that need to be performed before the request reaches the route handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a38b2cb-d720-40b7-951d-30d25b65df82', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery approach cross-browser event normalization?', N'Middle', N'jQuery creates a cross-browser event object that standardizes properties like target, currentTarget, and preventDefault across different browsers. This ensures that the same code behaves consistently regardless of whether the user is on an older version of Internet Explorer or a modern browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ef447eb-0aaf-4041-adeb-30d2e5167053', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the risks of using ''virtual'' in a base class destructor?', N'Senior', N'A non-virtual destructor in a polymorphic base class causes undefined behavior if a derived object is deleted through a base class pointer, as the derived class''s destructor will not be called. Declaring the base destructor as virtual ensures the correct destruction chain is invoked, preventing resource leaks in the derived class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4affdb0a-d8e3-4b2a-89b7-30d36784af16', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is a ''slot'' in Astro?', N'Intern', N'A slot is a placeholder in a component that allows you to inject external content or other components into it. It is how you create reusable layout components that accept varying content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a66b3c3-a219-4f71-9264-30dbb815cdb9', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you design a system to handle a sudden 10x traffic spike for a read-heavy service?', N'Senior', N'I would implement a multi-layered caching strategy using CDNs for static assets and an in-memory cache like Redis for frequent database queries. I would also leverage read replicas to distribute query load and ensure horizontal auto-scaling triggers are configured based on CPU or request rate thresholds to provision additional capacity dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06c99a07-f800-45f3-87a1-30dd8fab3ee9', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the significance of the ''static'' keyword?', N'Intern', N'The static keyword indicates that a member belongs to the class itself rather than to any specific instance of that class. Static variables and methods are shared across all objects created from that class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9e8172e-db9d-48ab-bc2f-30dfc427ccbc', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the role of ''Routing'' in AdonisJS?', N'Fresher', N'Routing defines how the application responds to client requests at specific URLs. It maps a URL path and an HTTP method to a specific controller action or a closure, acting as the entry point for incoming traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa567c22-b649-481a-8c5d-30dfca3833a9', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why does Fiber use Fasthttp instead of the standard library net/http?', N'Junior', N'Fasthttp is optimized for zero-allocation performance by reusing objects and buffers, whereas the standard library creates new objects for every request. Using Fasthttp allows Fiber to handle a significantly higher number of concurrent requests with lower CPU and memory usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49104236-622f-4766-beae-30e02740513f', N'a000805c-e41f-42a9-af12-66b45348f77b', N'When should you use a ''Repository'' pattern in an AdonisJS application?', N'Middle', N'The Repository pattern is useful in complex applications to further decouple the database layer from the business logic. It provides a cleaner abstraction for data access, making the codebase easier to test and maintain when query logic needs to be reused across different services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ce7c394-c036-4893-85c2-30e05653cb9f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the concept of ''Tree Shaking'' in the context of the dart2js compiler.', N'Senior', N'Tree shaking is an optimization process where the compiler analyzes the dependency graph to eliminate unused code paths and unreachable functions. By pruning these dead branches, the compiler produces a significantly smaller and more efficient JavaScript bundle for web deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7afc2d77-8310-467c-bd12-30e0957086c5', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is a path parameter in Echo routing?', N'Fresher', N'A path parameter is a dynamic segment in a URL route, typically denoted by a colon prefix, such as :id. Echo extracts the value provided in the URL at that position and makes it accessible through the Context object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1362b4a7-be5b-4acc-9a2c-30e3b713deb7', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar ensure type safety in JSON serialization?', N'Senior', N'Litestar uses Pydantic or msgspec to enforce type safety during serialization and deserialization. By mapping incoming request bodies directly to typed objects, the framework ensures that the application logic only processes valid, well-formed data, significantly reducing runtime type errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'615e98ef-9b5e-454d-8cb9-30e3c8c3c79c', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are the advantages of using Flask-Migrate for database schema management?', N'Middle', N'Flask-Migrate, which uses Alembic, tracks schema changes over time, allowing for version-controlled database migrations. This ensures consistency across different developer environments and simplifies deploying schema updates to production without manual database manipulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92ab3711-0401-4920-bb9d-30e477b653d4', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is a route parameter in Hono?', N'Intern', N'A route parameter is a dynamic segment in a URL path, usually denoted by a colon prefix. Hono extracts the value of these segments from the URL, allowing developers to use that information in their handler logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a850edb-67e6-4a60-8492-30e65f5b266c', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle event listeners?', N'Intern', N'Instead of attaching event listeners during a hydration process, Qwik uses global event delegation. The Qwik loader listens for events at the document level and then fetches the corresponding code only when an event is triggered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1ff1efb-b604-43db-b3a3-30e82c6af130', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why is Svelte considered ''write less code''?', N'Intern', N'Svelte is designed to minimize boilerplate by providing built-in solutions for reactivity, state management, and DOM updates. By handling these tasks at compile time, developers write fewer lines of code compared to frameworks that require manual configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94e623c0-d21d-4ff6-bd40-30e84a66b255', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do you reactively update an array or object in Svelte?', N'Junior', N'Since Svelte updates rely on assignment, you must reassign the array or object to itself to trigger reactivity. For example, using the spread operator to create a new array instance when pushing a value is the standard approach.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67b7ef34-3452-40ce-953d-30e8c5c1172d', N'4c000000-0000-0000-0000-000000000005', N'Explain the concept of database sharding.', N'Middle', N'Sharding is the process of splitting a large dataset into smaller, more manageable chunks across multiple database instances. It helps overcome the storage and throughput limitations of a single server, though it introduces complexity in cross-shard queries and data rebalancing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f608d873-3973-477f-b5ad-30ea53651cc3', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you ensure that your logs are actually useful during an incident?', N'Middle', N'I enforce a structured logging format like JSON that includes consistent metadata such as correlation IDs, timestamps, and service names. I also ensure that logs capture sufficient context without logging sensitive PII or overwhelming the storage systems with debug-level noise.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8b0838a-1508-42f0-8684-30eb8fe53148', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How do Micronaut''s build-time enhancements impact GraalVM Native Image generation?', N'Senior', N'Micronaut''s AOT architecture is inherently compatible with GraalVM because it does not rely on reflection, dynamic class loading, or runtime bytecode generation. This creates a seamless path to producing highly optimized, small-footprint native executables without requiring extensive manual configuration of reflection metadata.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd020db3d-7863-4144-b949-30ec01f24d83', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the benefit of virtual modules in Vite?', N'Senior', N'Virtual modules allow plugins to generate code in memory that does not exist on the file system. This is useful for passing build-time configuration or dynamic data to the frontend without requiring intermediate physical files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3049cb0-5d2b-4d4b-804b-30ef4913d679', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the primary difference between how SolidJS handles reactivity compared to React?', N'Junior', N'SolidJS uses fine-grained reactivity where components are executed only once, and updates are pushed directly to specific DOM nodes. In contrast, React re-renders entire component trees when state changes, requiring a virtual DOM to compare differences.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e0db105-4730-440c-bef5-30f28b350d61', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle concurrent request processing, and what are the limitations imposed by the underlying net/http server?', N'Senior', N'Echo leverages the standard library''s goroutine-per-request model, meaning each incoming connection is handled by a separate goroutine. Scalability is limited primarily by the operating system''s file descriptor limits and the application''s ability to manage shared state without excessive lock contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e10b128e-94e4-4e22-b6a0-30f493c523f9', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach the estimation of data storage growth when implementing a new event-driven architecture?', N'Senior', N'I calculate the average size of an event, the expected event frequency, and the retention policy, then apply an exponential growth model that accounts for potential spikes in event volume. This allows me to estimate the long-term storage costs and plan for automated data tiering or archival strategies before storage becomes a bottleneck.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04e4a16a-9298-44c0-b05d-30f4cbc2421d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why is it important to consider the ''cost of delay'' when prioritizing engineering tasks?', N'Junior', N'The cost of delay helps quantify the impact of not having a feature ready by a certain time, such as lost revenue or competitive disadvantage. This helps me understand the urgency of a task and allows me to communicate effectively when trade-offs need to be made.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
