INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e4d621d-ab5a-4452-acf0-30f6a91a9a5a', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs of implementing a circuit breaker pattern in a microservices environment?', N'Senior', N'A circuit breaker prevents resource exhaustion during service outages, improving overall system resilience. The trade-off is the added complexity of managing state transitions and the requirement to define appropriate fallback behaviors for when the circuit is open.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8df10cea-b937-4895-8e3d-30f9e301fedb', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a vtable and how is it used?', N'Middle', N'A vtable is a hidden table of function pointers used by the compiler to support dynamic dispatch for virtual functions. Each class with virtual functions has its own vtable, and objects of that class contain a pointer to their respective vtable to resolve function calls at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a873838-71b5-40d3-9abf-30fa0a8f7553', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why is Fastify generally considered faster than Express for high-load production environments?', N'Middle', N'Fastify utilizes a centralized routing engine and optimized JSON serialization through libraries like fast-json-stringify. Its internal architecture minimizes object allocation and function calls during the request-response lifecycle, which allows it to process more requests per second.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3d61e39-dfc7-416e-8dc3-30fdf5d86ebb', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing an API, what factors determine whether you should use REST or GraphQL?', N'Junior', N'I consider the client''s data requirements. REST is better suited for simple, predictable data access where standard caching mechanisms are beneficial. GraphQL is preferable when the client needs to minimize over-fetching or under-fetching by requesting specific nested fields in a single call.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8f83a9c-8d31-4ec6-b60a-30fff9514e2b', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the benefit of using an enum over constant integers?', N'Middle', N'Enums improve code readability by grouping related constants under a single type name and providing semantic meaning. Furthermore, some compilers can use enum information to issue warnings when a switch statement fails to cover all possible values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50eed825-07b5-4435-a7a2-3100298a3389', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Explain the concept of ''API Composition'' versus ''API Aggregation'' in a microservices environment.', N'Senior', N'API composition involves an orchestrator service that calls multiple downstream services to join data, which is simpler but can become a performance bottleneck. Aggregation often refers to using a GraphQL gateway or BFF (Backend for Frontend) to combine results at the edge, offering better performance and abstraction but requiring more complex infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a182b2d4-af4e-4457-b642-3101b54d4c00', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Describe the impact of the ''Selectivity'' of an index on query execution performance.', N'Senior', N'Selectivity refers to the ratio of unique values in an index to the total number of rows. High selectivity indexes allow the query optimizer to filter out most rows efficiently, whereas low selectivity indexes may cause the optimizer to favor a full table scan because the cost of index lookups outweighs the benefits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'037fac9a-baf4-4340-9ab3-310222ce11be', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the ''silent class'' (placeholder) technique?', N'Middle', N'A silent class is defined using the % prefix and will not be compiled into CSS unless it is explicitly extended. This allows you to define shared logic that is only output in the final file when it is actually used, preventing the inclusion of unused code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adfbe33d-a7f8-42d6-a96c-3105df47224a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do closures impact memory management in long-running single-page applications, and what strategies prevent memory leaks?', N'Senior', N'Closures retain references to their lexical scope, which can prevent garbage collection of variables if those closures persist unnecessarily. To prevent leaks, developers should nullify references to large objects no longer in use, avoid circular references, and ensure event listeners are properly removed when components unmount.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96bfaacd-1064-424c-9ff3-3105fa35e796', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why does Qwik favor small JavaScript files?', N'Intern', N'Small JavaScript files are faster to download, parse, and execute. By breaking the application into many small files, Qwik ensures that the browser is never overwhelmed and only processes the code that is strictly necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc40d378-ff61-4199-a3fd-31087fc443d1', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Describe the difference between synchronous and asynchronous validation in the context of Model State.', N'Senior', N'Synchronous validation occurs during the model binding process and is suitable for simple property constraints, while asynchronous validation is necessary when business rules require external lookups, such as database checks. Asynchronous validation prevents blocking the request thread during the model validation phase, maintaining system responsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9cbaaba-dd42-422e-84d3-310bf9632db8', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a database sequence?', N'Fresher', N'A sequence is a special object that generates a series of unique numbers, often used to create primary key values automatically. It ensures that every inserted record receives a distinct identifier.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1f64536-a627-4a14-ac96-310d2f0ef5d2', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it important to check the browser console for frontend issues?', N'Junior', N'The browser console displays client-side errors, network request failures, and warnings that are invisible to the user but critical for the developer. It acts as the first line of defense for diagnosing issues occurring directly within the user interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e75f989-9017-4126-9fbf-310e31d45c1e', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you differentiate between an estimate and a commitment, and how do you communicate this to non-technical partners?', N'Middle', N'An estimate is a probabilistic prediction based on current information, while a commitment is a promise to deliver by a specific date. I communicate this by using confidence intervals or ranges to indicate the level of certainty, helping partners understand that as more information becomes available, the estimate will naturally evolve.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7056013-10a3-4e18-8b6f-310fe010b8c0', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does Sass nesting affect CSS specificity?', N'Middle', N'Deeply nested Sass rules can lead to overly specific and long CSS selectors that are difficult to override. Excessive nesting often results in bloated files and makes it harder to maintain modular components, so it is recommended to keep nesting levels shallow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'238d0f94-0352-4f94-8ab3-311291e28979', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How can you leverage Flask''s middleware capabilities to implement centralized logging and tracing?', N'Senior', N'By wrapping the Flask WSGI app in custom middleware, you can intercept incoming requests and outgoing responses to inject correlation IDs and log performance metrics. This provides a unified observability layer across the application without polluting individual route logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3faa70d6-bad1-4671-b510-3112a28211e5', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is ''Operational Latency'' in the context of NoSQL replication?', N'Senior', N'Operational latency refers to the time delay between when a write is acknowledged by the leader node and when that data becomes visible on all follower replicas. Minimizing this latency is critical for maintaining a low bound on the consistency window in distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37d9955c-dbf7-4848-95c5-31132ab089c5', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the CSS Box Model and which properties does it include?', N'Junior', N'The CSS Box Model is the foundational concept that every element is essentially a rectangular box. It consists of four distinct layers: the content area, padding, border, and margin. Understanding how these layers interact is essential for controlling the spacing, sizing, and layout of elements on a page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8faec61-4811-4ef4-8d35-31134cc883fd', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the difference between a header and a parameter in Rocket?', N'Fresher', N'A header is metadata sent along with the HTTP request, while a parameter is typically part of the URL path or query string. Rocket provides distinct mechanisms to extract both types of information into handler functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d5f02fc-a061-460f-b7e6-311350ebefd9', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the difference between a Twig template and a standard PHP template?', N'Junior', N'Twig is a template engine that provides a cleaner, more secure, and more concise syntax for rendering HTML. It automatically escapes variables to prevent XSS attacks and offers features like template inheritance and filters that standard PHP lacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'323f4742-7fae-4ac7-98fb-311360e6adc1', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are ''Built-in Middlewares'' in Hono?', N'Intern', N'Built-in middlewares are pre-packaged functions provided by the Hono framework to handle common tasks. These include utilities for CORS, JSON parsing, basic authentication, and logging without requiring external dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fe5cec5-548d-4c12-a6c3-311444fbcfba', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does the use of wide partitions impact the performance and stability of a Cassandra node?', N'Senior', N'Wide partitions can grow indefinitely, leading to massive SSTables that are difficult to compact and query efficiently. This creates heap pressure, long garbage collection pauses, and increased latency as the system struggles to load partition indexes into memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01336f5f-0e77-4f87-831b-311586a08bbe', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of the ''override'' specifier?', N'Junior', N'The override specifier is used in derived classes to explicitly indicate that a function is intended to override a virtual function from a base class. It helps the compiler catch errors, such as misspellings or incorrect parameter types, at compile time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efe444e3-6db9-494a-8532-3117a378a995', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono''s context-based dependency injection compare to standard class-based DI frameworks?', N'Senior', N'Hono relies on a request-scoped context object to pass dependencies, which is more lightweight and runtime-agnostic than heavy, decorator-based DI containers. While it offers less boilerplate, it requires developers to be disciplined in how they bind services to the context, often favoring explicit middleware injection over implicit property-based injection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08a6cc52-00d3-4885-86ac-311a3110ceb5', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle CSS pre-processors like Sass?', N'Intern', N'Vite has built-in support for CSS pre-processors like Sass, Less, and Stylus. If the corresponding pre-processor is installed in the project, Vite automatically compiles the files during the build or dev process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'324898f5-57a2-4207-9914-311b0232d010', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony''s caching mechanism improve performance?', N'Middle', N'Symfony caches configuration, routing, and services by compiling them into optimized PHP files, which significantly reduces the overhead of parsing YAML, XML, or annotation files on every request. This minimizes disk I/O and processing time, leading to faster response times in production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'674d4b4f-7b95-4748-86db-311ea8748756', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is schema-on-write?', N'Intern', N'Schema-on-write is a concept used in relational databases where the structure must be defined before any data can be inserted. This enforces strict data quality and consistency by ensuring all incoming data conforms to the predefined rules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c791c8dc-ee3f-4dac-8b39-31223b574695', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the difference between a primary key and a clustering column?', N'Fresher', N'The primary key includes the partition key and optional clustering columns. While the partition key determines which node stores the data, clustering columns determine the sorted order of data within that specific partition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb4df01e-deb2-405d-b00b-3122fa242d01', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the ''Temporal Dead Zone'' relate to the engine''s scope resolution?', N'Senior', N'The TDZ is a consequence of how block-scoped variables are hoisted and initialized in the execution context. The engine tracks these variables in the lexical environment, ensuring that any access before the declaration results in a reference error as per specification.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54bfc612-98a8-45d4-8b18-3124ec84dc6b', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you evaluate the reliability of a third-party vendor''s infrastructure for mission-critical services?', N'Senior', N'I assess their historical uptime, incident response processes, and the availability of granular status reporting. I would also insist on testing their failover capabilities during a disaster simulation and ensure we have an exit strategy or a multi-vendor redundancy plan to mitigate the risk of vendor lock-in.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
