INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12ab93d4-b72b-427b-9474-3133d4af68a1', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the ''JIT Compiler'' decide between interpreting code and compiling it to machine code?', N'Senior', N'The JIT compiler uses profiling data to track execution frequency; functions that are called repeatedly are flagged as ''hot'' and sent to an optimizing compiler. Code that is rarely executed remains interpreted, which saves the overhead of compilation time and memory for non-critical paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
