INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6972cb0-7b8b-4172-bd39-313d6398f9ab', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the significance of the ''catch boundary'' in Remix?', N'Middle', N'The catch boundary is used to handle expected response errors, such as 404s or 401s, returned by the server. It allows developers to render specific UI components for these status codes, keeping the application state clean and providing meaningful feedback to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8731b4d-445c-461c-94e2-313d8ad3d2fe', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How do database transactions improve data integrity in a Laravel application, and what is the trade-off?', N'Middle', N'Transactions ensure that a series of database operations either all succeed or all fail, preventing partial data updates that could lead to inconsistencies. The main trade-off is performance, as keeping a transaction open for too long can hold database locks, potentially leading to deadlocks or increased contention in high-traffic systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2138a434-374c-4ee8-8e66-313e5984cb51', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why would you choose DynamoDB over a relational database?', N'Intern', N'You would choose DynamoDB when you need predictable, high-performance scaling that relational databases might struggle to maintain at massive volumes. It is particularly useful for applications with simple, well-defined access patterns and high-frequency writes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c6b1ead-9a09-47e3-88c6-313f2038d8b0', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you design a system to handle massive, predictable traffic spikes, such as a flash sale?', N'Senior', N'I would implement pre-provisioned auto-scaling based on time-of-day rather than reactive metrics, and place a static content delivery network in front of the application to absorb the majority of the traffic. For the dynamic components, I would use a virtual waiting room to throttle requests and protect the core database from overload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6087c3fe-df4d-4201-9ca8-313f4c42ef49', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between an Action Filter and a Result Filter?', N'Fresher', N'Action filters run before and after an action method is executed, allowing you to manipulate arguments or the result. Result filters run before and after the execution of the action result, which is useful for tasks like modifying the HTTP response or adding custom headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0048ae7-0635-4b40-87c3-314c0a340101', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the benefit of the ''Pimpl'' idiom in terms of compilation time and ABI stability?', N'Senior', N'The Pointer to Implementation (Pimpl) idiom hides the private implementation details of a class behind an opaque pointer in the header file. This breaks the dependency chain, significantly reducing recompilation times when implementation details change and allowing for binary-compatible updates without requiring a full rebuild of dependent modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f728919e-3e29-46ea-8225-314c4b1004e7', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How can Remix be used to implement a ''BFF'' (Backend for Frontend) pattern?', N'Senior', N'Remix acts as a natural BFF because its loaders and actions serve as a dedicated integration layer between the frontend and various backend microservices. By centralizing request orchestration in the route modules, the client receives only the exact data required for the UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f297e0ad-7c04-4d4b-82e1-314d2801ba61', N'954a0331-deff-4399-b588-96f39fec001d', N'What is schematic?', N'Intern', N'It''s a scaffolding library that defines how to generate or transform a programming project by creating, modifying, refactoring, or moving files and code. It defines rules that operate on a virtual file system called a tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89946bb8-80ab-41d9-a180-314dec024efe', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is horizontal scaling in databases?', N'Intern', N'Horizontal scaling, or scaling out, involves adding more servers or nodes to a database cluster to handle increased traffic. This approach is commonly used in NoSQL databases to distribute the workload across multiple machines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afe2ea90-cfbe-43b4-b364-314fe37686fc', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the implications of using ''const assertions'' on the mutability and narrowing of objects and arrays?', N'Senior', N'Const assertions treat expressions as immutable and narrow literal types to their most specific form, effectively freezing the structure for the type checker. This ensures that object properties or array elements are not widened to general types, preserving precision throughout the application flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c817ce4d-1f2b-4585-9b96-315105e7db42', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle multipart form data?', N'Intern', N'Fiber provides methods to parse multipart requests, which are typically used for file uploads. It allows you to access individual files and form fields through the request context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'910afca0-47b3-4619-916c-3151a19d6e19', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What criteria do you use to choose between a SQL and NoSQL database for a new project?', N'Senior', N'I choose SQL databases when the data structure is well-defined, requires complex joins, and demands ACID compliance for financial or transactional integrity. I opt for NoSQL when the data model is highly dynamic, requires extreme write throughput, or needs horizontal partitioning that exceeds what traditional relational engines can efficiently manage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e755274d-e2e8-438d-9e51-3155b417bed3', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is Durability in the context of ACID?', N'Intern', N'Durability guarantees that once a transaction has been committed, it will remain permanent even in the event of a system failure, such as a power outage or crash. This is typically achieved by writing transaction logs to non-volatile storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff8bd2f7-a024-4f6b-b420-315787bcb594', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle cross-origin resource sharing (CORS) configuration?', N'Senior', N'Micronaut provides a declarative approach to CORS, allowing developers to configure permitted origins, headers, and methods via application configuration properties. The framework then applies these filters at the HTTP level to ensure compliance without requiring custom middleware code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82c26b73-eb16-4feb-9374-3159186d816c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Describe the trade-offs of using ''Proxy'' objects for meta-programming.', N'Senior', N'Proxies provide powerful interception capabilities for property access and modification, but they can be significantly slower than direct object access because they introduce an extra layer of indirection. Engines often struggle to optimize proxy traps, meaning they should be used sparingly in performance-critical hot paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62ff9e96-1c00-4330-98ff-315989d284df', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is an aggregation in Elasticsearch?', N'Intern', N'An aggregation is a framework that allows you to summarize and analyze your data. It enables you to perform operations like calculating averages, finding minimum or maximum values, or grouping data into buckets based on field values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fa60062-1ae1-4e40-8027-315aea97f651', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Does Astro require a specific database to run?', N'Intern', N'No, Astro is a frontend framework and does not require a database. You can pull data from any API, CMS, or local file system to populate your pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bb26f91-6ec0-4883-95b4-315ba0efeab6', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Analyze the performance overhead of Ruby''s ''Refinements'' compared to traditional monkey-patching.', N'Senior', N'Refinements provide a scoped approach to modifying classes, ensuring that changes are only visible within a specific block or file, which avoids global state side effects. While safer than monkey-patching, they incur a performance penalty because the VM must check for active refinements during method lookup, making them slower than native method definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55b431a3-2983-4621-9201-31612a6f5e9f', N'4c000000-0000-0000-0000-000000000005', N'How can you implement backpressure in a microservices architecture?', N'Senior', N'Backpressure can be implemented using reactive streams, fixed-size thread pools with rejection policies, or by using message brokers where consumers pull at their own rate. This prevents a downstream service from being overwhelmed by a high-velocity upstream producer, maintaining system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85b883a7-02fa-4c16-9988-31623aaf593f', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between a synchronous and asynchronous route in Flask?', N'Middle', N'Synchronous routes block the worker process until the function returns, which can lead to performance bottlenecks during I/O operations. Asynchronous routes, supported in newer versions, use the await keyword to handle concurrent I/O without blocking the thread. This is particularly beneficial for high-latency tasks like external API calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cfbf526-ce19-4b19-a7a5-31651472ccc7', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is an Express router?', N'Intern', N'An Express router is a mini-application that can be used to modularize route handling. It allows developers to group routes logically, making the codebase cleaner and easier to maintain by separating concerns into different files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89976f26-7992-4417-b07d-3165f776e922', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are the implications of Scala''s ''Uniform Access Principle'' for API design and maintenance?', N'Senior', N'The Uniform Access Principle allows methods without parameters to be defined as fields or methods interchangeably, hiding whether a value is stored or computed. This is powerful for encapsulation because it allows developers to transition from a field to a computation without breaking binary compatibility. However, it can mask expensive computations as simple property accesses, leading to unexpected performance bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1ed3cc5-12cc-4dcf-9c07-316600c20a07', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the significance of the ''Two-Phase Commit'' (2PC) protocol in distributed databases, and why is it often avoided at scale?', N'Senior', N'2PC ensures atomicity across multiple nodes by using a coordinator to prepare and commit transactions. It is avoided at scale because it is a blocking protocol; if the coordinator or a participant fails, resources can remain locked indefinitely, severely impacting availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5a4e798-3473-476c-9bef-3167863d78e7', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle concurrency in a multi-core production environment?', N'Senior', N'Since Python''s Global Interpreter Lock limits execution to one CPU core per process, FastAPI must be deployed using a process manager like Gunicorn with Uvicorn workers. This architecture allows the application to spawn multiple worker processes, each running its own event loop, effectively utilizing all available CPU cores to handle higher volumes of traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4a4c1f6-6515-4ead-a6d3-316c227db68f', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is filter context?', N'Intern', N'Filter context is used for binary questions, such as whether a field matches a value or falls within a range. It does not calculate a relevance score and is generally faster because the results can be cached by the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56dabd55-800b-416b-a95a-316c77675425', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle database migrations, and why are they important?', N'Middle', N'Migrations provide a version-controlled, programmatic way to define and evolve the database schema over time. By using migration files instead of manual SQL execution, teams ensure that the database structure remains consistent across different development, testing, and production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29c7493f-aaea-48bd-8c4f-316d050a1f5c', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of ''Pin'' in asynchronous programming?', N'Middle', N'Pin ensures that a value cannot be moved in memory, which is critical for self-referential structures like async futures. Without pinning, the internal pointers of a future would become invalid if the future were moved to a different memory location.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22db396e-f650-4c36-93fb-31721a08766a', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the heap memory segment used for?', N'Intern', N'The heap is a region of memory used for dynamic memory allocation. Unlike the stack, memory on the heap must be manually allocated and deallocated by the programmer using specific functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b34bc311-0102-4a28-b7f8-317739ad9355', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How are indices handled in R?', N'Fresher', N'R uses 1-based indexing, meaning the first element of a vector or list is accessed using the index 1. This differs from many other programming languages that use 0-based indexing for arrays.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea4313f0-3fe7-4ace-866a-31782a1bd1b1', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How do you optimize Webpack''s build performance for large-scale applications?', N'Senior', N'Optimizations include using persistent caching to store intermediate build results, parallelizing loaders like ''thread-loader'' for CPU-intensive tasks, and limiting the scope of filesystem watchers. Additionally, using modern minifiers and strategically splitting code into smaller, cache-efficient chunks helps manage both build speed and execution performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7df7f630-3729-455e-90e3-317868337f17', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How do ''Value Classes'' differ from ''Case Classes'' in terms of memory layout?', N'Senior', N'Value classes are optimized to be inlined as the underlying type, resulting in no heap allocation, whereas case classes are full objects that always reside on the heap. While case classes provide features like pattern matching and copy methods, they carry the overhead of object headers and pointers. Value classes are used for domain-specific wrappers that add type safety without the performance cost of object instantiation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bf4b3db-1aa6-4818-83bb-317a8ca536c9', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the function of the ''CanActivate'' guard?', N'Middle', N'CanActivate is a router guard used to determine if a user has the authorization to navigate to a specific route. It typically checks for user credentials or permissions and prevents unauthorized access to protected application areas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3c08ccf-1c1e-4b69-a4f1-317ac694d949', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Describe the security considerations when using ''Runtime Config'' in Nuxt.', N'Senior', N'Runtime config separates environment variables into ''public'' and ''private'' keys, which is critical for security. Private keys are only accessible on the server, preventing sensitive data like API secrets from being bundled into the client-side JavaScript, where they would be exposed to end-users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97b9625a-42a3-4518-89c4-317d43fe30ef', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the concept of ''Zvals'' within the Zend Engine''s memory management.', N'Senior', N'A Zval is the fundamental container structure for all PHP variables, holding both the type and the value. Modern versions of PHP have optimized Zvals to be significantly smaller and more memory-efficient, reducing the overall footprint of complex data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4469c99-cd2f-4fad-ac95-317fff2bce02', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the ''dns-prefetch'' and ''preconnect'' hint improve resource loading speed?', N'Senior', N'These hints allow the browser to resolve DNS, establish TCP handshakes, and negotiate TLS connections with a third-party domain before an actual request is made. This eliminates the latency associated with these network steps when the browser eventually requests a resource from that domain, significantly speeding up cross-origin asset loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfd67fee-bd2a-448a-98f8-31807c372ad1', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why does Go not support function overloading?', N'Middle', N'Go prioritizes simplicity and readability, aiming to make code behavior predictable and easy to trace. By disallowing overloading, the language avoids complex resolution rules at compile time and makes it immediately clear which function implementation is being invoked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c650bacc-1b14-45b7-a46a-3181b0d081d7', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the LIKE operator?', N'Fresher', N'The LIKE operator is used in a WHERE clause to search for a specified pattern in a column. It often uses wildcards like the percent sign to represent missing characters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19152d38-03b9-4c75-b3dd-3181c50350c6', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why does Rust distinguish between ''stack'' and ''heap'' allocation, and how does this affect object lifetime management?', N'Senior', N'The stack provides fast, predictable allocation for fixed-size data, while the heap allows for dynamic allocation of objects whose size or lifetime is unknown at compile-time. Rust manages heap memory through the RAII pattern, where ownership determines the exact scope at which a destructor is invoked, ensuring memory is freed immediately when the owner goes out of scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4460eafd-3c52-4ff8-bb41-318285379fa4', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the role of the ''willUpdate'' lifecycle method compared to ''updated''?', N'Senior', N'The ''willUpdate'' method runs before the DOM is updated and allows for local state calculations or property adjustments based on the new values. In contrast, ''updated'' runs after the DOM has been modified, making it the correct place to perform follow-up actions like measuring DOM elements or integrating with non-Lit third-party libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f72a2d2-fd9a-48b7-acde-3184387f168b', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What happens when you run ''npm run build'' in a Vite project?', N'Fresher', N'Running the build command triggers Vite to compile your application for production. It performs tasks like transpilation, CSS minification, asset optimization, and bundling your code into a set of static files ready for deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f978ef6-5bbf-4b61-a224-318918322331', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the trade-off between code reusability and system coupling?', N'Middle', N'Creating highly reusable modules can reduce code duplication, but it often leads to tight coupling where a change in one area forces changes across multiple services. It is often better to prefer duplication over wrong abstractions until the requirements are stable and the boundary of the reusable component is clearly defined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfe1740f-1aea-456a-9f2d-318953c3c121', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is Data Annotation and how is it used?', N'Junior', N'Data Annotations are attributes applied to model properties to define validation rules, such as required fields, string length, or range constraints. The framework uses these attributes to automatically validate incoming data before the controller action is executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
