INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c481eb58-cd49-4253-a7d3-318a2b2aad61', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why is the ''TypedArray'' architecture more memory-efficient than standard JavaScript arrays for large numeric datasets?', N'Senior', N'TypedArrays use fixed-size, contiguous memory buffers managed outside of the standard garbage-collected heap. This allows for direct memory access and predictable data representation, which reduces memory overhead and improves performance by minimizing the need for boxing and unboxing of numeric values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23e04cb5-3c2c-4641-8fff-318ad9bcd44c', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the benefit of using BackgroundTasks in FastAPI, and when should you avoid them?', N'Middle', N'BackgroundTasks allow you to perform post-response operations like sending emails or log processing without making the user wait for completion. However, they should be avoided for critical tasks requiring high durability, as they run in-memory and can be lost if the server restarts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
