INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd582ee1d-a33b-407d-a435-31aa1779dddf', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How can you mitigate the risk of ''Memory Leaks'' when using server-side composables?', N'Senior', N'Memory leaks in Nuxt often occur when global state or external event listeners are not properly cleaned up during the request lifecycle. Developers should ensure that reactive state is scoped to the current instance and avoid appending data to global objects that persist across multiple requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
