INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a89c0c3d-394b-43a0-b8f8-31b25e3a759c', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is a Validation rule?', N'Intern', N'Validation rules are conditions applied to input data to ensure it meets specific criteria before being processed. Laravel provides a wide array of built-in validation rules, such as requiring a field to be an email or checking if a value is unique in the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffd0eb29-686d-45be-9fa1-31b2f6e4b14f', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why would you choose the keyword type over the text type for a field?', N'Middle', N'The keyword type is used for exact matches, sorting, and aggregations, as it treats the entire field as a single unit. The text type is designed for full-text search, where the field is analyzed and broken down into individual terms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b54a4cac-e08e-4e49-8227-31b31d171d84', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind ensure that the generated CSS remains small in production?', N'Junior', N'Tailwind uses a tool that scans your project files for utility classes and removes any unused CSS from the final build. This ensures that even if you have a massive configuration, your production stylesheet only contains the styles actually used in your project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'118c1192-7f59-4e8e-b389-31b62efe34a1', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How do you handle graceful shutdowns in a Node.js server to ensure data integrity and avoid dropped requests?', N'Senior', N'A graceful shutdown involves stopping the server from accepting new connections, finishing existing request/response cycles, and closing persistent connections like database pools. Using signal handlers like SIGTERM, the application can perform cleanup tasks before exiting, ensuring no in-flight transactions are aborted unexpectedly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f6bba09-102b-4e6e-957c-31b7903e4ac2', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why might you use Chi''s ''Route'' method instead of the standard ''Handle'' method?', N'Middle', N'The ''Route'' method allows you to define a sub-router for a specific path prefix, which is essential for creating modular sub-applications. It scopes the routes and middleware to that prefix, whereas the standard ''Handle'' method is intended for single, static endpoint registration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'522492d8-4439-4015-a0bc-31b7c6ee0e1c', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the benefit of AdonisJS being ''opinionated''?', N'Fresher', N'Being opinionated means the framework enforces specific ways of doing things, such as project structure and naming conventions. This reduces the time spent on decision-making and ensures consistency across different developers working on the same project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74a6382f-b2c1-4521-a67c-31b81df1c8c5', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are closures', N'Intern', N'A closure is the combination of a function bundled(enclosed) together with its lexical environment within which that function was declared. i.e, It is an inner function that has access to the outer or enclosing function’s variables, functions and other data even after the outer function has finished its execution. The closure has three scope chains. 1. Own scope where variables defined between its curly brackets 2. Outer function''s variables 3. Global variables Let''s take an example of closure concept, As per the above code, the inner function(i.e, greetingInfo) has access to the variables in the outer function scope(i.e, Welcome) even after the outer function has returned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'940034a7-561f-4ccf-8645-31ba4979866e', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus support reactive programming compared to imperative programming?', N'Middle', N'Quarkus is built on Vert.x, allowing developers to use both imperative and reactive paradigms seamlessly. It provides non-blocking I/O support through Mutiny, enabling high concurrency with fewer threads compared to traditional blocking Servlet-based architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9add249-6e0f-4313-b904-31bae7c166a7', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are the performance implications of using ''source-map'' versus ''eval-source-map'' in a production environment?', N'Senior', N'Source-map generates high-quality, external mapping files that are ideal for production debugging but increase build time and final bundle footprint if uploaded. Eval-source-map is significantly faster during development because it uses data URLs but is unsuitable for production because it drastically increases the bundle size and exposes source code inside the generated JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
