INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8d8eafd-1d63-4af9-b66f-31bef23203e1', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is fine-grained reactivity?', N'Intern', N'Fine-grained reactivity means that the framework knows exactly which part of the DOM depends on which piece of state. This allows SolidJS to update only the affected part of the interface without re-running entire component functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01915330-d40b-449a-9fad-31c075b52325', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the advantages and drawbacks of using Worker Threads for parallel processing in Node.js?', N'Senior', N'Worker Threads allow for true parallel execution of JavaScript code by providing separate V8 instances and event loops, significantly improving performance for CPU-intensive tasks. The main drawback is the memory overhead of spawning new threads and the complexity of managing shared state via MessageChannel or SharedArrayBuffer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
