INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a0b841e-4324-4910-8378-31cc3b2d954a', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of @RequestMapping and its variations?', N'Junior', N'@RequestMapping is used to map HTTP requests to specific handler methods in a controller. Modern variations like @GetMapping, @PostMapping, and @PutMapping provide clearer intent by restricting the mapping to specific HTTP request types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17693df3-3fea-4ec9-a51c-31cf32ca2b3a', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are the performance implications of using ''ValueTask'' over ''Task''?', N'Senior', N'ValueTask is a struct that avoids a heap allocation if the operation completes synchronously. This reduces garbage collector pressure in high-throughput scenarios where asynchronous methods frequently return pre-computed results. However, it should only be used when the result is immediately available, as consuming a ValueTask multiple times or awaiting it concurrently is unsafe.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'334b736b-4ebe-40c5-8f0b-31d0f0c3b018', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle the reconciliation of functional components compared to class components?', N'Senior', N'Preact treats functional components as pure functions that return virtual DOM nodes, which are then diffed directly. Class components involve more lifecycle overhead, requiring the engine to instantiate the class and track internal state, which is slightly more memory-intensive than the stateless functional approach.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c515447b-5b1e-4dcb-a84c-31d34b999874', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the difference between Lit''s ''requestUpdate'' and ''performUpdate'' methods?', N'Middle', N'requestUpdate is a public method used to schedule an asynchronous update for the component when property changes aren''t automatically detected. performUpdate is the internal method that actually executes the update cycle, including calling render and updating the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4fe1f9c-580a-40c1-bf74-31d4bf4de090', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How do you manage error handling in Go?', N'Fresher', N'Go has a unique approach to error handling compared to other languages. It uses explicit error return types. This design choice reduces ambiguity about functions that can potentially fail and obviates the need for try-catch blocks. The Go philosophy stresses transparency and early reporting of issues. To adhere to these principles, the language offers a set of built-in tools and techniques. Best Practices in Go for Managing Errors - Minimize. panic(): Use it for exceptional conditions like unrecoverable internal state - Log Smartly: Specify logging levels selectively. Avoid logging the same message multiple times. - Wrap Errors to Retain Context: Use fmt.Errorf() and errors.New() or the errors package for this. - Validate and Handle Returned Errors: Don''t ignore them without validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4f2e9fa-7723-443b-b4c8-31d60425e597', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the benefit of Sound Null Safety in Dart?', N'Middle', N'Sound Null Safety ensures that variables cannot contain null unless explicitly declared as nullable. This allows the compiler to optimize the generated code significantly, as it does not need to perform runtime null checks on non-nullable types, while also preventing common null-pointer exceptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cceffb16-ebef-4e28-ba47-31d9a72a1a26', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach debugging a service that is intermittently losing state stored in a distributed key-value store?', N'Senior', N'I would start by auditing the write logs to confirm if the operations are being successfully acknowledged by the storage layer or if there is a ''lost update'' scenario due to improper concurrency control. I would then check the TTL settings and eviction policies to ensure that the data isn''t being prematurely removed by automated cleanup processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afb45377-77b9-49a2-84da-31dcce880c53', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is a BSON document in the context of MongoDB?', N'Junior', N'BSON stands for Binary JSON. It is the binary-encoded serialization format used by MongoDB to store documents, which supports more data types than standard JSON, such as dates and raw binary data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af9a0100-c938-4408-a169-31e1c87ff400', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask handle JSON responses?', N'Intern', N'Flask provides a jsonify() function that converts a Python dictionary or list into a valid JSON response with the appropriate MIME type. This makes it easy to build APIs that communicate with frontend frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd6e9297-869f-401a-b70f-31e3d7a9918e', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Why is it important to handle hydration errors in Nuxt?', N'Junior', N'Hydration errors occur when the HTML generated on the server does not match the initial HTML rendered by the client. This typically happens due to mismatched data or dynamic content, which can cause performance issues or unexpected UI behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'679d7cbb-6dc8-4103-9ca5-31e5bc4fcca3', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R''s lexical scoping differ from dynamic scoping?', N'Senior', N'Lexical scoping resolves variables based on the physical location of the function definition in the source code, ensuring predictability. Dynamic scoping, which R supports in specific contexts, would resolve variables based on the call stack, which is generally discouraged due to the difficulty in reasoning about variable state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60649d73-fe7c-4a43-ab7e-31e68e140519', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do you handle ''Backpressure'' in a high-throughput streaming architecture?', N'Senior', N'Backpressure allows a system to signal to upstream components to slow down their production of data when consumers are overwhelmed. Implementing this correctly prevents memory overflow and buffer exhaustion, ensuring the system remains stable under peak load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e907a11-6068-4f6c-ae08-31e8d95b598b', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the ''bulkhead'' pattern in software architecture?', N'Middle', N'The bulkhead pattern isolates system components into separate pools or resource buckets. If one component fails or becomes resource-heavy, the failure is contained within that bulkhead, preventing it from consuming all resources and causing the entire system to fail.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc8b1584-c6a3-455f-975e-31ed5d70ceed', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R manage namespaces in package development?', N'Middle', N'Namespaces are used to control which functions are exported and which are internal to a package, preventing conflicts with other loaded packages. They also define the search path for dependencies, ensuring that a package consistently uses the correct versions of the functions it requires.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2069d126-7a0a-46f8-99c1-31ed77544b68', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What happens if you use x-data on a body tag?', N'Junior', N'Using x-data on the body tag makes that data available to the entire page. While this can be convenient for global state, it is generally better practice to scope data only to the specific parts of the page that actually require it to prevent performance issues and scope pollution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2bdfa78-c6d1-4d2a-ad0f-31eeda86169d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When is it appropriate to trade code readability for performance optimization?', N'Middle', N'Readability should be the default to ensure long-term maintainability and easier onboarding. Performance optimization at the cost of readability is only justified when profiling proves that a specific section of code is a critical bottleneck that directly impacts user experience or operational costs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
