INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c282854-198f-4a4d-9b14-31f4c15c5327', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the role of the ''Coordinator'' in distributed consensus.', N'Middle', N'The coordinator acts as the centralized authority that manages the lifecycle of a distributed transaction. It communicates with participants to ensure that everyone agrees on whether to commit or rollback, acting as the single source of truth for the final outcome of the operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
