INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b178459b-2eb1-4a76-98d9-320161ab06a2', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why is ''CSS Shadow Parts'' important for design systems built with Lit?', N'Senior', N'CSS Shadow Parts allow parent components to style specific internal elements of a Shadow DOM-encapsulated child component. This provides a formal, performant way to expose internal styling hooks without breaking the isolation of the Shadow DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86511b39-9010-4386-947d-320526cd23bf', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the purpose of the Gin Engine?', N'Intern', N'The Engine is the main instance of the Gin framework. It manages the routing rules, the middleware stack, and the configuration settings for the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b753ea59-abec-41d8-b091-32067c020368', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the purpose of the ''layer'' method in Axum?', N'Fresher', N'The layer method is used to apply middleware to a router or a specific group of routes. It allows you to wrap the request-response cycle with additional logic like compression or CORS handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9df3c8d-973c-45c9-b9eb-320712d5d2db', N'075b8862-431c-4678-9767-f55359758a4a', N'What are functional components?', N'Intern', N'The functional components are just simple functions to create simple components just by passing a context. Every functional component follows two rules, 1. Stateless: It doesn''t keep any state by itself 2. Instanceless: It has no instance, thus no this You need to define functional: true to make it functional. Let''s take an example of functional components, Note: The functional components are quite popular in React community too.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e475733d-824d-4e02-84b5-320be6a40c99', N'075b8862-431c-4678-9767-f55359758a4a', N'Why is it dangerous to mutate reactive state directly in an asynchronous callback without careful planning?', N'Senior', N'Directly mutating state across asynchronous boundaries can lead to race conditions where the UI state becomes inconsistent with the underlying data. It is safer to use computed properties or state management actions to ensure that updates are handled predictably and within the expected lifecycle boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'920465b1-6d0e-49a5-ae8a-320c19a41a5b', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Why is the global environment considered a ''dangerous'' place in package development?', N'Senior', N'The global environment is volatile and subject to user modification, which can break code that relies on implicit state or specific variable names. Robust packages must strictly rely on their own namespaces and explicitly imported symbols to ensure they remain isolated from external changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'997bf89c-0e93-4e71-997e-320c53835729', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are the benefits of using the ''Controller'' pattern in Lit?', N'Middle', N'Controllers allow developers to extract stateful logic and lifecycle behavior into reusable modules. This promotes code reuse and separation of concerns, as controllers can hook into the host component''s lifecycle without cluttering the main component class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
