INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c888cbd-7dee-4e91-95ed-3210f16db4f9', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is hydration in SvelteKit?', N'Intern', N'Hydration is the process where the static HTML rendered by the server becomes an interactive Svelte application on the client. It attaches event listeners and makes the page responsive to user interactions after the initial load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
