INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2551c7a-8d16-44ba-817b-321471a55096', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When is it appropriate to sacrifice code readability for the sake of brevity?', N'Fresher', N'This is rarely recommended, but it might occur in extremely resource-constrained environments where binary size is a critical factor. Generally, the trade-off should favor readability to ensure that the code remains maintainable by the team over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da396c5a-55da-413a-917a-321772f1ee49', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Explain the concept of ''tombstones'' in the context of deletions.', N'Senior', N'In Cassandra, deletes are treated as writes that insert a marker called a tombstone. This marker signifies that data has been removed, preventing old data from resurfacing during compaction until the tombstone is eventually purged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1af65b05-9c3e-4bfa-979b-3218d6f7d8e8', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is multi-master replication and what are its risks?', N'Middle', N'Multi-master replication allows multiple nodes to accept write operations, which can increase write throughput. The significant risk is handling write conflicts and ensuring data consistency across nodes, which often requires complex conflict resolution strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6af67189-6849-4fa2-9c2d-321a72671488', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Why is it considered a best practice to implement the Principle of Least Privilege in microservices?', N'Middle', N'It minimizes the blast radius of a security breach by ensuring each service only has the permissions necessary to perform its specific task. If one service is compromised, an attacker cannot easily move laterally or access sensitive data outside that service''s scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38359bae-b09d-4b84-964c-321b3b7310e7', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the advantage of using keyword arguments in Ruby methods?', N'Middle', N'Keyword arguments improve code readability and maintainability by making the purpose of each argument explicit at the call site. They also prevent bugs caused by incorrect argument ordering, which is a common issue with positional arguments. This makes the interface of a method more resilient to future changes in the method signature.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82739599-6e6c-43b7-8b7c-3220a397bddb', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo facilitate graceful shutdown of the server?', N'Middle', N'Echo provides hooks to stop the server listener, allowing you to close database connections and finish inflight requests before exiting. By integrating with OS signals, you can ensure the application terminates cleanly without interrupting active user sessions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'287d72d3-5eb7-4180-9bed-3228c94c654e', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does Python handle namespace resolution, and what is the LEGB rule?', N'Senior', N'Python resolves names by searching scopes in the order: Local, Enclosing, Global, and Built-in (LEGB). This hierarchical approach ensures that local variables shadow globals, and provides a structured way to manage scope visibility across different parts of a program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f1d6d63-f6c8-490a-ba0f-322c130388fb', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What happens if you try to insert a document without an _id field?', N'Fresher', N'If a document is inserted without an _id field, the MongoDB server will automatically generate and insert an ObjectId for that field before saving the document to the collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d048849-55b5-4f4a-bfa5-322c59f7e683', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of the ''explicit'' keyword in constructors?', N'Middle', N'The explicit keyword prevents the compiler from performing implicit conversions using a constructor that takes a single argument. This helps prevent unexpected behavior where a type is automatically converted when the developer likely intended to provide a specific object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3de198ee-9bdc-4c9b-aa49-322effc19046', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a projection expression in a DynamoDB query?', N'Junior', N'A projection expression allows you to specify which attributes you want to return from a query or scan. This reduces the amount of data transferred and lowers the cost of the operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'018a9e83-5d03-4a79-9cc9-322f74f8b23b', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask''s thread-local storage mechanism, specifically the request context, impact application scalability in multi-threaded environments?', N'Senior', N'Flask uses thread-local proxies to manage request and application contexts, allowing global-like access to request data without explicit parameter passing. While this simplifies development, it can become a bottleneck in high-concurrency scenarios if not paired with an asynchronous gateway interface (ASGI) or non-blocking I/O, as each thread consumes significant memory and limits throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e895ef9b-4bfd-43ea-b942-323180709970', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Describe the difference between strict aliasing and type punning in C++.', N'Senior', N'Strict aliasing is a compiler optimization rule that assumes pointers of different types do not point to the same memory location, allowing the compiler to reorder reads and writes. Type punning, such as using reinterpret_cast to access an object''s bytes as a different type, often violates this rule, leading to undefined behavior unless specific exceptions like using char arrays or std::bit_cast are employed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'791eb018-ca1c-4eea-88fb-323416e237fa', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the role of an eviction policy when the cache reaches memory capacity?', N'Senior', N'When the cache is full, an eviction policy determines which existing items must be removed to make space for new incoming data. The choice of policy directly influences the hit rate, as the system must decide which data is least likely to be needed in the immediate future.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bcfa21a-c482-4dec-808e-323713b03465', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What are the benefits of using ''aspect-ratio'' in modern CSS?', N'Middle', N'The aspect-ratio property allows developers to define the proportional relationship between width and height of an element, which is critical for maintaining responsive containers like video players or images. It prevents layout shifts during image loading because the browser can reserve the correct space before the content arrives. This significantly improves core web vitals related to layout stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09b85051-5894-4121-a651-32386957af89', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the concept of ''Context Hierarchy'' in Spring Boot and when it should be used.', N'Senior', N'A context hierarchy allows an application to have multiple, nested ApplicationContexts, where child contexts can inherit beans from parent contexts. This is useful for isolating configurations, such as having a shared parent context for common beans and separate child contexts for different web modules or plugin systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'deecfb99-55cc-442b-84d2-3239392283c4', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do you maintain CSS specificity balance when using Sass mixins?', N'Senior', N'To maintain specificity balance, mixins should be designed to apply styles rather than define complex selectors. By keeping mixins focused on simple property-value pairs and avoiding nested selector generation, you prevent unintended specificity wars that are difficult to debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d85e0ff-c076-477c-88ca-323aaa4b06e8', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi''s middleware execution order influence API security?', N'Senior', N'Middleware in Chi executes in the order it is registered; therefore, security-sensitive middleware like authentication and rate limiting must be placed at the very beginning of the stack. Placing these before business logic ensures that unauthorized or abusive traffic is dropped before it consumes expensive system resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f12b0e0-757d-4896-849a-323afdba9e06', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the difference between horizontal and vertical scaling, and when would you use each?', N'Middle', N'Vertical scaling involves increasing the resources of a single node, while horizontal scaling involves adding more nodes to the system. I would use vertical scaling for simplicity when a workload fits within a single instance, but I would default to horizontal scaling for high-traffic applications to avoid single points of failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61d34497-52ed-4f6f-b046-323c7248ecaa', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the ''partial hydration'' strategy in Astro?', N'Middle', N'Partial hydration means only the interactive pieces of a page receive JavaScript. This reduces the total bundle size significantly compared to frameworks that hydrate the entire DOM tree, resulting in faster ''time to interactive'' metrics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b209cc4a-8393-4de2-b067-323cb63ff41e', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What does the ''inline'' keyword suggest to the compiler?', N'Junior', N'The ''inline'' keyword is a suggestion to the compiler to replace a function call with the actual code of the function body. This can potentially increase performance by eliminating the overhead of the function call mechanism. However, the compiler is free to ignore this suggestion if it determines that inlining would not be beneficial.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd63068f4-a84d-4e4d-bb16-323ccd767611', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the advantages of using streams for handling large files or data sets?', N'Middle', N'Streams allow you to process data in chunks rather than loading the entire file into memory at once. This significantly reduces memory footprint and improves performance when dealing with large datasets, as it enables the application to start processing data as soon as the first chunk arrives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'306d3eda-56e0-4789-876e-324034456518', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go’s type system handle ''nil'' for interfaces?', N'Middle', N'An interface is nil if both its type and value are nil. A common pitfall is assigning a typed nil pointer to an interface; the interface itself will then be non-nil because it holds a type, which can lead to unexpected behavior when checking for nil.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
