INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c35d34d-bbe1-41f5-88f2-326a53a58478', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the primary difference between ''val'' and ''var'' in Kotlin, and how does it relate to immutability?', N'Middle', N'''val'' declares a read-only reference, meaning the variable cannot be reassigned after initialization, whereas ''var'' allows for reassignment. Using ''val'' promotes immutability, which helps reduce side effects and makes code easier to reason about in concurrent environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c485b6da-c2bc-4012-8f0f-326a7ca6f404', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify''s schema validation help in API documentation?', N'Middle', N'Fastify can automatically generate OpenAPI or Swagger documentation directly from the validation schemas provided in route definitions. This keeps the documentation perfectly synchronized with the actual implementation, reducing the risk of discrepancies between the API spec and the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f26e2091-82d3-4dec-9ad0-326fc0a96db3', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the significance of the ''transient'' keyword?', N'Junior', N'The transient keyword is used during serialization. It tells the Java Virtual Machine that a specific variable should not be serialized and should be ignored when saving the object''s state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6255a00-cbd4-4fe2-871a-3271a4c6c475', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If a task is taking longer than you estimated, what should you do?', N'Fresher', N'I would immediately communicate the delay to my manager or team, explaining the specific blockers or technical challenges I encountered. Transparency is critical so that expectations can be adjusted and resources reallocated if necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf050ed3-4e82-4ae5-b9ab-32759071ac6c', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Explain the middleware chain execution order in Echo.', N'Middle', N'Middleware in Echo is executed in the order it is registered. When a request hits the server, it passes through the middleware stack sequentially before reaching the handler, and then travels back through the stack in reverse order during the response phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ef4af30-9558-4fe7-a97a-327628fb221c', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What are the architectural implications of choosing a ''NetworkTopologyStrategy'' over a ''SimpleStrategy'' in a multi-region deployment?', N'Senior', N'NetworkTopologyStrategy allows for rack and data-center awareness, enabling replicas to be placed across different physical failure domains and geographic regions. SimpleStrategy ignores rack and data-center boundaries, making it unsuitable for high-availability production environments that require disaster recovery capabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bf508cb-4f80-4ec2-af62-3278727ebf6c', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the purpose of the ''onClose'' hook in long-running Fastify services?', N'Senior', N'The onClose hook is essential for graceful shutdowns, allowing services to close database connections, flush logs, or finish pending background tasks before the process exits. This prevents data corruption and ensures that all active requests are handled before the server terminates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4017794-91d0-4ff2-b799-327885b1d191', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Explain the performance implications of Preact''s diffing algorithm compared to React''s reconciliation process.', N'Middle', N'Preact uses a highly optimized, lightweight diffing algorithm that minimizes memory allocation and garbage collection overhead by reusing existing nodes more aggressively. While both libraries use virtual DOM diffing, Preact''s approach is designed for faster execution in memory-constrained environments, though it may be less sophisticated than React''s Fiber architecture when handling complex high-frequency updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
