INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a2901a1-35dd-4e36-abec-329d387469a7', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is eventual consistency and why is it used in distributed systems?', N'Middle', N'Eventual consistency is a model where data updates are not immediately reflected across all nodes, but will eventually propagate to all replicas. It is used to achieve high availability and performance, trading off immediate read accuracy for the ability to scale globally under high write loads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
