INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e86c0ede-f432-45f2-b99b-32a27e4c5249', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the InnoDB Redo Log facilitate ACID compliance?', N'Senior', N'The Redo Log ensures durability by recording changes before they are applied to the data files. In the event of a crash, MySQL replays the log to restore the state of the database to the last consistent point, ensuring no committed transaction is lost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f87021b-66f9-4bd1-a4f3-32a69b31318c', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the role of ''tower::ServiceBuilder'' in configuring an Axum application?', N'Senior', N'ServiceBuilder provides a fluent API for composing multiple layers of middleware into a single, cohesive unit. It simplifies the setup of complex stacks, such as adding timeouts, rate limits, and CORS support, before mounting them onto an Axum router.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a5ccb98-f9d3-4c77-a50a-32a86c266042', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How to use constructor functions for inheritance in JavaScript?', N'Fresher', N'Let say we have Person class which has name, age, salary properties and incrementSalary() method. Now we wish to create Employee class which contains all the properties of Person class and wanted to add some additional properties into Employee class. In the example above, Employee type inherits from Person. It does so by assigning a new instance of Person to Employee prototype. After that, every instance of Employee inherits its properties and methods from Person. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cdf269c-b34d-4907-9636-32a96706136a', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does the ''write-behind'' caching strategy differ from ''write-through'' in a Redis-backed system?', N'Senior', N'Write-through updates the cache and the primary database synchronously, ensuring consistency at the cost of higher write latency. Write-behind updates the cache immediately and asynchronously updates the database, offering higher performance but risking data loss if the cache fails before the sync completes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'707f452a-cb9c-412d-afad-32aaa28c8938', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the role of an analyzer in Elasticsearch?', N'Fresher', N'An analyzer is a process that breaks down text into individual terms or tokens during the indexing or search process. It typically involves character filtering, tokenization, and token normalization, such as converting text to lowercase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7145e1d4-9a10-4ab7-9e11-32aad4598c7d', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Discuss the impact of nil-interface comparisons in Go.', N'Senior', N'A nil interface is only equal to a literal nil if both its type and value components are nil. An interface containing a pointer to a nil value is not considered a nil interface, which is a common source of logic errors in Go systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f84c835-e4f5-45fc-9ea4-32ac9e3d5f53', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does the load path ($LOAD_PATH) work in Ruby?', N'Junior', N'The load path is an array of directory paths that Ruby searches when you use the ''require'' or ''load'' methods to import files. When you require a file, Ruby looks through these directories in order to find the specified file name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'faf8c723-d1b0-4289-a397-32afbefedd74', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How do Bloom filters improve performance in NoSQL systems?', N'Senior', N'Bloom filters are probabilistic data structures used to test whether an element is in a set without accessing the disk. By quickly identifying that a key does not exist in a specific data file, the system avoids unnecessary I/O operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0aa8f3f8-5dd0-4ae1-977c-32b2b8726203', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is Cross-Origin Resource Sharing (CORS)?', N'Fresher', N'CORS is a security feature that allows a server to specify which origins are permitted to access resources on its domain. In ASP.NET Core, it is used to prevent unauthorized web pages from making requests to your API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2cd283e-6f05-41b4-99ee-32b2d1112d6f', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What are the limitations of Astro when building highly dynamic, dashboard-like applications?', N'Senior', N'Astro is optimized for content-driven sites; highly interactive, state-heavy dashboards might require extensive custom client-side logic that could negate Astro''s performance benefits. In such cases, the overhead of managing state across isolated islands may become more complex than using a single-page application framework designed for persistent application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c75ef77-4366-4e62-9e4a-32b5ab9b7b86', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are Phoenix LiveView components?', N'Intern', N'LiveView components are reusable UI fragments that manage their own state and behavior. They allow developers to build complex, real-time user interfaces by breaking them down into smaller, manageable pieces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'627b1896-8afb-4e43-97c8-32b6d8e3eef0', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What are the performance implications of having too many Alpine components on a single page?', N'Middle', N'Each Alpine component requires a certain amount of memory to maintain its reactive proxy object and DOM observation. Having a very high number of components can increase the initial page load time and memory footprint, potentially impacting performance on low-end devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc265e9b-3c5d-48a9-8829-32b81a0b1aa8', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is an Accessor in Eloquent?', N'Intern', N'An accessor is a method that allows you to transform or format an Eloquent attribute value when you retrieve it from a model. It provides a clean way to modify how data is presented without changing the underlying value stored in the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6f2aa0f-a213-4a02-b841-32bc86d6d616', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit ensure memory efficiency when handling many instances of the same component?', N'Middle', N'Lit optimizes memory by sharing the compiled template parts and CSSStyleSheet objects across all instances of a component class. Because these resources are static and reused, the memory overhead per instance remains very low compared to frameworks that duplicate template structure logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a2747dd-f367-469e-a3a7-32bd3c13d84a', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are the scalability limitations of a monolith Nuxt application?', N'Senior', N'As the application grows, the monolithic structure can lead to longer build times and complex dependency graphs. Scaling involves breaking the application into multiple micro-frontends or micro-services, and utilizing Nuxt''s ability to act as a gateway or aggregator for backend services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
