INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f638cc11-35e1-49e5-94d3-32be54c6c522', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the purpose of the client:visible hydration directive?', N'Middle', N'This directive delays the loading and hydration of a component until it enters the browser''s viewport. It is an effective performance optimization for components located further down the page, such as footers or comment sections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a7bc0f5-9e77-49b4-98ba-32bf391c3dc6', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum differ from frameworks like Actix-web in terms of its architecture?', N'Junior', N'Axum is built on top of the Tower ecosystem and the Hyper HTTP library, making it highly modular and focused on middleware composition. Unlike some other frameworks that provide an all-in-one suite, Axum relies heavily on generic traits that allow for seamless integration with any Tower-compatible service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
