INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08aabe40-a24c-431b-a383-32bfa7b2ebc5', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your philosophy on logging and observability for a production system?', N'Senior', N'I believe in structured logging that includes contextual metadata for every request, combined with distributed tracing and aggregated metrics. Observability should provide a holistic view of the system''s state, enabling proactive alerting rather than just reactive debugging after an incident.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2144f35-ab13-441d-a437-32c04125fa0e', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why is Preact considered better for mobile performance?', N'Fresher', N'Preact''s small bundle size allows for faster download and parsing times on mobile devices. This reduces the time to interactive, which is crucial for users on slower network connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'494b4313-f46e-4a09-bed8-32c1626db745', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Is Astro a Single Page Application (SPA) framework?', N'Intern', N'No, Astro is primarily a Multi-Page Application (MPA) framework. It focuses on traditional page-to-page navigation, although it can be configured to behave like an SPA using specific client-side routing libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3741cccf-5733-4bb5-8c03-32c1753c9572', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the purpose of the application.properties file in Quarkus?', N'Intern', N'This file serves as the primary configuration location for the application and its extensions. It allows developers to define environment-specific settings, database connections, and framework properties in a centralized way.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0340c9b-1f55-40cb-9e34-32c20da43a76', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the benefit of using ''Self'' (capital S) in protocol requirements?', N'Senior', N'Using Self allows a protocol to refer to the specific type that conforms to it, enabling methods to return the implementing type rather than the protocol itself. This maintains type fidelity in method chaining and complex hierarchies where returning the protocol would lose concrete information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56fef1c1-9f80-451f-9b57-32c2bd054e4d', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the circuit breaker mechanism protect Elasticsearch nodes from OOM errors?', N'Senior', N'Circuit breakers monitor the memory usage of various components, such as field data, request, and parent aggregations, against pre-defined thresholds. If a request would cause memory usage to exceed these limits, the circuit breaker trips and rejects the request, preventing the node from crashing due to heap exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18d004e3-1d3c-4f41-9ae9-32c493f0a3a7', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does the Phoenix ''Presence'' module differ from standard PubSub in terms of distributed state management?', N'Senior', N'Phoenix Presence is designed for tracking the state of distributed system members, such as user availability or activity, across a cluster. Unlike PubSub, which is transient and message-oriented, Presence maintains a replicated CRDT-based state that is consistent across all nodes, ensuring accurate tracking of cluster members.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b8b9d75-38ad-4468-a716-32c5db17abf5', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the ''CAP Theorem'' and how does it relate to system design?', N'Middle', N'The CAP theorem states that a distributed system can only guarantee two out of three properties: Consistency, Availability, and Partition Tolerance. In a network partition, designers must choose between returning the most recent data (Consistency) or providing a response at all (Availability).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'274d2a38-5082-44a8-9aa0-32c69d946eaf', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between an absolute and relative import?', N'Junior', N'An absolute import specifies the full path from the project root to the module. A relative import specifies the location relative to the current module''s position, using dots to navigate up the directory structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c8f903f-295e-405f-97f3-32c6d0d2fbb0', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you evaluate the risk of a single point of failure in a system design?', N'Middle', N'I identify components that, if they fail, would bring down the entire system and assess the likelihood of that failure. I then propose redundancy strategies, such as load balancing or failover mechanisms, and estimate the cost and effort of implementing these mitigations against the impact of potential downtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b97a8f34-649d-4c79-8d5d-32c8f744aa1a', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the benefit of adding temporary diagnostic outputs during debugging?', N'Fresher', N'Adding temporary outputs allows you to track the state of variables or the flow of execution at specific points in time. This visibility helps confirm if your assumptions about how the system is behaving match the reality of the execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f46cb28f-a4d3-442c-8fcf-32d4e5f702a7', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a database transaction, and why are ACID properties important?', N'Middle', N'A transaction is a single logical unit of work that may consist of multiple operations. ACID properties—Atomicity, Consistency, Isolation, and Durability—ensure that transactions are processed reliably, preventing data corruption and inconsistencies even in the event of system failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57648c24-4739-44ba-8aec-32d7bb90766b', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What role does a Content Delivery Network (CDN) play in scalability?', N'Middle', N'A CDN caches static assets like images, CSS, and videos on edge servers geographically closer to the end-users. By serving content from the network edge, it reduces latency and offloads traffic from the primary application servers, enabling the system to serve a larger global user base.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a819694-8df2-467d-b80d-32db65f862e6', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What are API routes in Next.js?', N'Intern', N'API routes allow you to build backend functionality directly within your Next.js project. You can create server-side endpoints to handle requests like form submissions or database queries without needing a separate backend server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e6c48d5-3c73-42af-a92a-32dd4b706f26', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why would you choose to use a Client Component even if Server Components are the default?', N'Junior', N'You should use a Client Component when you need to use interactive browser features like event listeners, React hooks (useState, useEffect), or third-party libraries that rely on browser APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5e3d451-8fc3-442e-8369-32dfa09a062a', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why does Vite serve code via native ESM?', N'Intern', N'By serving code through native ES modules, Vite avoids the need to bundle the entire project before starting the development server. This allows the browser to request only the files it needs, resulting in near-instant startup times regardless of project size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a2b594c-70eb-4304-b925-32e0cc856d67', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt’s auto-import feature impact application performance and bundle size?', N'Middle', N'Nuxt’s auto-import system allows developers to use components, composables, and utilities without explicit imports, improving developer experience. Because Nuxt performs tree-shaking during the build process, unused auto-imported modules are excluded, ensuring that the final bundle size remains optimized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7aa8912-ec0a-4c84-ae6e-32e12ebee03e', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery''s approach to global scope affect the ability to use modern build tools?', N'Senior', N'jQuery was designed to be loaded as a global script, which creates issues when trying to integrate it into modern modular build pipelines. This requires ''shimming'' or ''exposing'' variables, which defeats the purpose of modern module systems and makes tree-shaking impossible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc5aa079-f5d9-4f92-a6cf-32e31cd8d501', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is a native executable?', N'Intern', N'A native executable is a standalone binary file created through Ahead-of-Time compilation that does not require a traditional Java Virtual Machine to run. It contains the application code and necessary library dependencies bundled together.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e33b565-99d9-4710-8fa2-32e59feaf515', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the ''next/link'' component used for?', N'Intern', N'The Link component is used for navigation between different pages in a Next.js application. It provides client-side transitions, which makes navigation feel faster than a standard browser anchor tag refresh.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e207e06e-9667-4b3b-804e-32e8237feb26', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the main advantage of using Echo over the standard library net/http?', N'Intern', N'Echo provides a more developer-friendly API, built-in middleware, better routing capabilities, and easier data binding. It significantly reduces boilerplate code compared to the standard library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a031977-8b30-4309-9dcd-32eb9250a630', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain the concept of ''Proc'' and ''Lambda'' closures in terms of their handling of ''return'' statements and argument checking.', N'Senior', N'Lambdas are lexically scoped and act like methods, where a ''return'' statement exits only the lambda, and they enforce strict argument checking. Procs are more flexible, treating a ''return'' as an exit from the enclosing scope and ignoring extra arguments, which can lead to subtle bugs if the developer expects strict function behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7333e831-2fb1-4a07-a008-32ef92e19a8a', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why does Vite perform ''dependency pre-bundling''?', N'Fresher', N'It helps solve issues with deep import paths in node_modules and improves performance by consolidating many individual small files into a single bundle, reducing the number of HTTP requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'523db6d3-9ed6-4c9f-afb8-32efaf608bdf', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Why is Sass often preferred over native CSS variables?', N'Junior', N'Sass variables are processed at compile time, meaning they are converted to static values in the final CSS. This can be useful for legacy browser support and performant build processes, whereas native CSS variables are dynamic and processed at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e12150a8-67a4-4a16-9e0f-32efea2684b7', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Explain the ''Suspense'' mechanism in SolidJS and how it relates to asynchronous resource loading.', N'Senior', N'Suspense in SolidJS acts as a boundary that monitors for pending asynchronous resources, allowing the UI to show a fallback state until the data is resolved. It works by tracking the reactive context of nested resources, providing a declarative way to handle loading states without manual flag management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd58393e7-53b7-48db-b9d0-32f067a95be3', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the difference between a component''s ''args'' and its local state?', N'Junior', N'Args are properties passed into a component from its parent template, which the component should generally treat as read-only. Local state consists of internal properties managed within the component itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99052155-46da-4939-a7b7-32f128baae5c', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the impact of excessive indexing on a write-heavy database system?', N'Senior', N'Every additional index requires a corresponding write operation during data insertion, update, or deletion, which significantly increases I/O overhead. This degrades write throughput and increases contention, as the database engine must maintain the B-tree structure for every secondary index defined on the table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2c25f50-9c93-4183-9900-32f391ba7a5a', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the primary philosophy behind the design of the Ruby programming language?', N'Intern', N'Ruby was designed by Yukihiro Matsumoto with a focus on programmer happiness. It emphasizes simplicity and productivity by making the language feel natural and intuitive for the developer to write.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e136933-54b7-41e2-bc8a-32f40da33772', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How can CSS specificity be managed in a large project to avoid conflicts?', N'Middle', N'Specificity can be managed by adhering to a consistent naming convention like BEM, avoiding deeply nested selectors, and keeping selectors as flat as possible. Using utility-first CSS frameworks or CSS modules can also enforce scoping at the component level. Avoiding the ''id'' selector in CSS is also a standard practice to keep specificity low.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7dceca54-9f78-4cda-a568-32f43582067e', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a database deadlock?', N'Junior', N'A deadlock occurs when two or more transactions are waiting for each other to release locks on data. As a result, none of the transactions can proceed, and the system must intervene to abort one of them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0ee7c86-358b-4aa1-a0fd-32f4583a4923', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django handle session management?', N'Intern', N'Django provides a session framework that lets you store and retrieve arbitrary data on a per-site-visitor basis. It stores the data on the server side and sends an anonymous session ID to the user''s browser via a cookie.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a40893b-4c26-47a0-85d6-32f6472441e5', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the impact of Rocket''s procedural macros on code maintainability and system complexity?', N'Senior', N'Procedural macros simplify complex routing and data extraction tasks by generating boilerplate code during compilation. While this hides implementation details, it promotes a clean, declarative API that is easier to maintain and audit for correctness, provided developers understand the underlying Rust macro expansion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c88f0b3-2d45-4a21-a71e-32f6aa41705e', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the purpose of the ''serveStatic'' middleware in Hono, and how does it relate to edge caching?', N'Middle', N'The serveStatic middleware allows Hono to serve static assets directly from the runtime''s local storage or integrated KV stores. By serving these assets from the edge node, you reduce latency significantly compared to fetching them from a centralized origin server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a04e04dd-e5ab-4497-872e-32f7b1b992ce', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the ''cluster'' module in Node.js used for?', N'Junior', N'The cluster module allows you to create child processes that share the same server port. This enables a Node.js application to take advantage of multi-core systems by running multiple instances of the event loop in parallel.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa0569e8-1d11-4abc-8ff7-32fa4486611c', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Describe your strategy for ensuring data consistency in a distributed system.', N'Middle', N'I would utilize distributed transaction patterns like the Saga pattern to manage long-lived transactions across microservices. For eventual consistency, I would implement event sourcing or idempotent consumers to ensure that retries do not result in duplicate state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78e2c2ca-5326-4156-a73d-32fb96239903', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is difference between put and patch?', N'Fresher', N'PUT and PATCH are HTTP verbs and they both relate to updating a resource. The main difference between PUT and PATCH requests are in the way the server processes the enclosed entity to modify the resource identified by the Request-URI. In a PUT request, the enclosed entity is considered to be a modified version of the resource stored on the origin server, and the client is requesting that the stored version be replaced. With PATCH, however, the enclosed entity contains a set of instructions describing how a resource currently residing on the origin server should be modified to produce a new version.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c470dc6-d659-4459-a1b4-32fc23824681', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Does Preact support the use of refs?', N'Intern', N'Yes, Preact supports refs, which provide a way to access DOM nodes or React elements created in the render method. This is useful for tasks like manual focus management or integration with third-party DOM libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'972172e4-d72d-4523-a6bc-32fe4ec29366', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are ACID properties in the context of PostgreSQL?', N'Intern', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably, maintaining data integrity even in the event of system failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a906194-9c77-4508-a501-32ff34131efb', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the primary purpose of Kotlin in modern development?', N'Intern', N'Kotlin is a modern, statically typed programming language designed to be fully interoperable with Java. It aims to improve developer productivity by offering concise syntax and enhanced safety features like null safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5082398-d344-4308-9c46-32ff82331273', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Explain how Express handles security headers to prevent common vulnerabilities.', N'Middle', N'Express itself does not provide security headers by default. Developers must use middleware like Helmet to set appropriate HTTP headers, which helps mitigate risks like cross-site scripting, clickjacking, and other common web vulnerabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce8ed028-e3a9-4a87-8ab6-330159d75e77', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach a situation where you need to implement a new feature that will likely introduce significant technical debt?', N'Middle', N'I would first assess if the debt is acceptable based on business urgency and the expected lifespan of the feature. I would then communicate the trade-offs to stakeholders, document the debt clearly, and propose a concrete plan to refactor the code once the immediate business objective is met.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4849b106-0361-436d-8c3f-33017e42553c', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why is it considered a bad practice to put non-serializable data, like functions or promises, into the Redux store?', N'Middle', N'Redux is designed to be serializable, which allows for powerful debugging tools like time-travel debugging and state snapshots. Non-serializable data breaks these tools and can cause issues with state hydration and persistence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5603542e-df41-4dab-8c66-33019c5685ce', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do ''namespace'' and ''module'' differ in modern TypeScript?', N'Middle', N'Namespaces were originally designed to group code and avoid global scope pollution, while modules are the ECMAScript standard for organizing code. Modern TypeScript development favors the module system because it provides clearer dependency management and better integration with build tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55350933-1563-41d5-8392-3301e5e88dbe', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs between using an optimistic locking strategy and a pessimistic locking strategy in a database?', N'Middle', N'Pessimistic locking prevents conflicts by blocking access, which is safe but limits concurrency and can lead to deadlocks. Optimistic locking allows multiple users to read and write simultaneously, only checking for conflicts at the final commit, which is better for performance but requires logic to handle retries when collisions occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfd70ccf-8554-4960-a079-33033f1bdf4c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the advantages of typescript over javascript', N'Intern', N'Below are some of the advantages of typescript over javascript, 1. TypeScript is able to find compile time errors at the development time only and it makes sures less runtime errors. Whereas javascript is an interpreted language. 2. TypeScript is strongly-typed or supports static typing which allows for checking type correctness at compile time. This is not available in javascript. 3. TypeScript compiler can compile the .ts files into ES3,ES4 and ES5 unlike ES6 features of javascript which may not be supported in some browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87bfe882-7dfd-40cb-b47d-3306e9637612', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a subquery, and when would you use one?', N'Intern', N'Definition and Scope A Subquery (or nested query) is an inner SELECT statement embedded within an outer query (e.g., SELECT, INSERT, UPDATE, or DELETE). In modern RDBMS architectures, subqueries are classified based on their interaction with the outer scope: Non-Correlated (independent, executed once) and Correlated (dependent on the outer query, executed once per row). Common Subquery Classifications Scalar Subquery Returns exactly one row and one column. * Use Case: Comparisons against atomic values. * Optimization: Modern optimizers utilize memoization to avoid redundant execution if the subquery is non-correlated. Table (Row/Column) Subquery Returns one or more rows/columns. * Use Case: Providing sets for IN, EXISTS, or ANY/ALL operators.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9c93862-6215-46f7-bf89-330787037a42', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How do Dart''s ''Typedefs'' contribute to code maintainability?', N'Middle', N'Typedefs create aliases for complex function signatures or types, improving code readability. They simplify the declaration of callback signatures, making it easier to ensure consistency across the codebase when functions with identical parameter structures are reused in multiple locations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a20ef8ab-03a5-482c-b5ab-33084d1d2006', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you manage configuration drift in a complex, multi-environment infrastructure?', N'Senior', N'I would treat infrastructure as code (IaC) and enforce strict version control, ensuring all environment changes are peer-reviewed and deployed through automated pipelines. Continuous configuration management tools would be used to audit and automatically revert any manual changes that deviate from the defined state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16126e25-74d8-4d1e-9884-330888283798', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why is it important to avoid ''keys *'' and other O(N) commands in a production Redis environment?', N'Middle', N'Because Redis is single-threaded, executing an O(N) command like ''keys *'' on a large dataset will block the event loop for the duration of the operation. This prevents the server from responding to any other client requests, causing significant latency spikes or service outages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b442641-9b63-42e0-8989-330968a5b5ed', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the function of a Snitch in Cassandra?', N'Junior', N'A snitch determines which data centers and racks nodes belong to. This information is used by Cassandra to intelligently route requests and place replicas, ensuring that data is distributed across different physical locations for disaster recovery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffa396ee-bffc-47ce-8423-330c47b6b99d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is isNaN', N'Intern', N'The isNaN() function is used to determine whether a value is an illegal number (Not-a-Number) or not. i.e, This function returns true if the value equates to NaN. Otherwise it returns false.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
