INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd077dad3-d7e3-4439-a1a2-330e107c6dbc', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How can you implement custom validation for model fields or entire models?', N'Middle', N'You can implement custom validation by defining validator functions for individual fields using the validators argument or by overriding the model''s clean method for cross-field validation. The clean method is typically called during form validation to ensure the integrity of the object before it is saved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d5580ff-a354-4330-b208-33110a7d4447', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the JVM''s Tiered Compilation strategy impact the lifecycle of an application?', N'Senior', N'Tiered compilation begins with the C1 compiler, which quickly generates optimized code with minimal profiling, followed by the C2 compiler, which uses collected profiling data to perform aggressive, high-level optimizations. This approach allows for fast startup while eventually achieving peak performance for long-running processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f62b8a37-582d-4d12-8241-3312730a4b2d', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is conditional rendering in Preact?', N'Intern', N'Conditional rendering is the practice of displaying different UI elements based on certain conditions, such as the value of a variable or a state property. It is typically implemented using standard JavaScript operators like ternary operators or logical AND operators within JSX.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74defda3-e20e-44d2-b125-3317715fb94c', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Explain the significance of the Quarkus ''Substrate'' or ''Native'' build process regarding reflection.', N'Senior', N'Native compilation requires explicit configuration of all classes that will be accessed via reflection, as the compiler cannot statically analyze dynamic paths. Quarkus automates much of this by detecting reflection usage in extensions, but developers must manually register classes if they use advanced reflection or dynamic proxies in their own logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cac2033c-bf51-44d3-8bba-331869cc17f7', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What does ACID mean in the context of PostgreSQL?', N'Intern', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably, maintaining data integrity even in the event of system failures or errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dab5014d-58f4-4ec3-96cb-331a370d5a22', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why does Svelte use a compiler-based approach to scope CSS styles?', N'Middle', N'Svelte scopes CSS by appending unique class hashes to elements during compilation. This prevents style leakage between components without requiring external libraries or performance-heavy runtime style injection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'867d39fe-97a9-4313-9693-331d86202f53', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What impact does Qwik have on Cumulative Layout Shift (CLS)?', N'Senior', N'Since Qwik''s state is serialized into the HTML during SSR, the server sends a fully rendered representation of the DOM. This minimizes the risk of layout shifts that occur when client-side hydration causes content to jump or re-render during the initial load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2757fb7d-f462-4473-92b6-3324cd4a591c', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Describe the mechanism behind NestJS custom pipe validation and how it interacts with the underlying serialization.', N'Senior', N'Pipes operate within the request pipeline to transform and validate incoming data before it reaches the handler. By integrating with class-validator, they ensure data integrity at the edge of the system, effectively decoupling validation logic from the controller''s business logic while ensuring that only sanitized objects reach the service layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c9fbfe6-feae-4395-b11e-3326812adc06', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of the ''static'' keyword for class members?', N'Intern', N'A static member variable is shared among all instances of a class rather than having a separate copy for each object. A static member function can be called without an instance of the class and can only access other static members. It is useful for maintaining global state or utility functions related to a class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bba6e522-510d-4a8b-9632-3328095e3c89', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the role of MicroProfile in Quarkus?', N'Intern', N'MicroProfile is a set of open-source specifications for building microservices in Java. Quarkus implements these standards to ensure that applications are portable and follow industry best practices for configuration, security, and observability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4673282f-5570-472f-8841-3328ae8d7426', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI support database transactions within dependencies?', N'Middle', N'By using a generator function with a ''yield'' statement in a dependency, you can perform setup logic, ''yield'' the database session, and then execute cleanup logic like committing or rolling back the transaction. This ensures that transaction integrity is maintained automatically for every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'327c084f-6763-4874-9de4-332a5b02696c', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does ''overflow: clip'' differ from ''overflow: hidden''?', N'Middle', N'''Overflow: hidden'' triggers a new formatting context and prevents scrolling while still allowing for programmatic scrolling. ''Overflow: clip'' strictly prevents all scrolling and does not establish a new formatting context, which can have different implications for layout containment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ec059f0-ecef-4057-98f9-332c4f7b3c3e', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the purpose of the ''style'' tag in a Svelte component?', N'Intern', N'The style tag contains the CSS rules for the component. Svelte automatically scopes these styles to the component''s HTML elements, ensuring that styles do not leak out or affect other parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f15496c9-7e42-46f0-b04e-33329a4242b8', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are the architectural implications of using Tailwind''s utility-first approach versus traditional BEM or CSS Modules?', N'Senior', N'Utility-first CSS shifts the abstraction layer from naming conventions to composable design tokens. While it eliminates the naming collision and maintenance overhead of BEM, it requires a strict design system (theme) to prevent visual inconsistency and ensure architectural scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b838517-abcc-4607-873e-33330b426769', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why might a developer choose Snapshot Isolation over Serializable isolation?', N'Middle', N'Snapshot Isolation provides a consistent view of the database at the start of a transaction without using read locks, which significantly increases concurrency. It is often preferred because it avoids many performance bottlenecks associated with strict serializability while still preventing most common anomalies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8da58465-521e-451d-a0ab-33367a3231ac', N'4c000000-0000-0000-0000-000000000005', N'What are the risks of using a shared database for multiple microservices?', N'Senior', N'Sharing a database leads to tight coupling between services, as a schema change in one service can break others. It also hampers independent scaling and makes it difficult to enforce domain boundaries, eventually leading to a ''distributed monolith'' that lacks the benefits of a true microservices architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a19d0047-c4fb-4750-8290-3337c74cdd5b', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'In what scenarios would you utilize Symfony''s ''Console'' component as a long-running process, and what memory management strategies are required?', N'Senior', N'Long-running console commands are useful for background workers or event listeners, but they risk memory leaks because PHP is typically designed for short-lived requests. Developers must implement explicit garbage collection and clear internal caches periodically to maintain stable memory usage over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd999332a-7e91-411e-95de-33425492fc90', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS approach server-side rendering (SSR) compared to traditional hydration?', N'Senior', N'SolidJS utilizes a streaming SSR approach that allows for ''hydration-less'' or ''resumable'' patterns. Instead of hydrating the entire tree, it can attach event listeners to the DOM server-side, reducing the initial JavaScript payload and time-to-interactive significantly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6efea12c-f996-4899-b269-3342fb4ba483', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the main entry point of a Dart program?', N'Fresher', N'The main entry point of any Dart application is a top-level function named ''main''. The Dart runtime calls this function to start the execution of the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b94e1881-b6ef-4cf6-bb55-334776e48ebe', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Does Chi require external dependencies outside of the Go standard library?', N'Fresher', N'No, Chi is designed to have zero dependencies beyond the Go standard library. This makes it very lightweight, easy to maintain, and ensures it does not bloat the project''s dependency tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c84181f-465c-4e02-9f19-334bd2b4eddc', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How do ''build tags'' affect the compilation process in Go?', N'Middle', N'Build tags allow developers to include or exclude specific files from the build process based on operating systems, architectures, or custom conditions. This is fundamental for writing portable code that needs to handle platform-specific implementations of the same interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25fec852-619a-41f9-b2b9-334d2fc4f572', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the ''happens-before'' guarantee in relation to concurrent collection classes.', N'Senior', N'Concurrent collections use internal atomic state updates and volatile semantics to establish a ''happens-before'' relationship between threads. This ensures that a write to the collection by one thread is guaranteed to be visible to any thread subsequently reading from the collection, maintaining consistency without external synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9890285f-f53a-44a8-93aa-334ef5ace752', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are the architectural benefits of using Ember’s Engines compared to standard lazy-loading modules?', N'Senior', N'Ember Engines allow for the isolation of routing, templates, and services into independent, routable applications that can be developed, tested, and deployed separately. This provides better organizational boundaries for large teams and enables true independent dependency management, which is more robust than simple code-splitting techniques.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c4da93e-f29b-4c56-b84e-3350e4a0ccfd', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R handle missing values, and what is the primary indicator used for them?', N'Junior', N'R uses the symbol NA to represent missing or unavailable values. It is a logical constant that propagates through most operations, meaning that any arithmetic calculation involving an NA will typically result in NA unless specific functions are used to ignore them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
