INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3bf5018-03c8-45be-8b8e-335d2f75612a', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do mapped types and conditional types interact to facilitate metaprogramming in TypeScript?', N'Senior', N'Mapped types allow you to iterate over keys of an existing type to transform them, while conditional types introduce logic based on type relationships. Combining them enables the creation of complex utility types that can infer, extract, or omit properties based on structural requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7847431-16da-487b-aea2-335ee553a5fe', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s ''associatedtype'' in protocols enable generic programming?', N'Middle', N'Associated types allow a protocol to define a placeholder type that is specified by the conforming type. This enables protocols to be generic and type-safe without needing to know the concrete types ahead of time, facilitating highly flexible and reusable component design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a1077c6-0045-46d7-98ff-336250d620d3', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the common data types in PostgreSQL?', N'Junior', N'PostgreSQL supports various data types including numeric types like integer and decimal, string types like varchar and text, boolean values, and date-time types like timestamp.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3038cb31-0413-420b-8869-3362d2b24b47', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the trade-offs of using ''Utility Types'' (like Pick, Omit) versus manually defined interfaces?', N'Senior', N'Utility types promote DRY principles and reduce boilerplate by deriving new types from existing ones. However, over-reliance on them can make the type system harder to debug, as IDEs might show the utility type name instead of the expanded, readable interface definition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9315fc72-fb64-425c-8166-33637becf6fa', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the role of idempotency in distributed system design?', N'Senior', N'Idempotency is critical for handling network retries and duplicate requests without causing side effects. By designing endpoints that can be called multiple times with the same result, I ensure that the system remains resilient to intermittent connectivity issues and message queue re-deliveries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5649c2f-2677-4ee4-9592-336612ed03af', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Discuss the trade-offs of using jQuery''s animation methods versus CSS transitions.', N'Middle', N'jQuery animations are executed via JavaScript, which runs on the main thread and can be interrupted by other tasks, leading to jank. CSS transitions are handled by the browser''s compositor thread, providing smoother performance and better hardware acceleration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3803cdcb-560d-4ad9-846a-33663e160501', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the primary architectural weakness of the Express router when handling thousands of dynamic routes?', N'Senior', N'The Express router uses a linear matching strategy, where it iterates through route definitions sequentially. As the number of routes grows, route resolution time increases, which can be mitigated by grouping routes, but fundamentally scales poorly compared to trie-based routing algorithms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0098337f-a813-4e2f-af8f-33677973eb14', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If your application experiences a sudden traffic spike, what is your strategy for horizontal scaling?', N'Middle', N'I would rely on an auto-scaling group that monitors CPU and memory utilization to trigger the provisioning of additional service instances. To ensure this is effective, I would ensure the application is stateless, offloading session state to a distributed cache like Redis so that any request can be handled by any instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3d341f7-46a3-454f-ba6c-33685dcd7cdd', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the role of an eviction policy in Redis, and which one is most common?', N'Middle', N'An eviction policy determines which keys to remove when Redis reaches its configured maximum memory limit. The most common policy is allkeys-lru, which removes the least recently used keys to make space for new data, ensuring the cache stays relevant to recent application traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e737843-e8c4-4f31-982b-336a30a2c065', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the role of the Translog in Elasticsearch and how does it ensure data durability?', N'Senior', N'The Translog records every operation that is not yet persisted in a Lucene commit point. If a shard crashes before the index buffer is flushed to disk, the Translog is replayed during recovery to reconstruct missing operations. This provides durability guarantees similar to a Write-Ahead Log in traditional relational databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10e4383a-5064-43de-b989-336d30d4ae0d', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between a vertical or horizontal layout for a mobile app dashboard?', N'Fresher', N'I would choose a vertical layout if the content is hierarchical or requires scrolling, which is natural for mobile devices. A horizontal layout might be used for things like image galleries or swipable cards where space needs to be optimized for specific item views.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8007708-389f-4ea4-9f8f-336d7ae3694c', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Why is the order of middleware registration critical in Gin?', N'Senior', N'Middleware in Gin is executed in the order it is registered. Because each middleware can modify the request, abort the request chain, or alter the response, registering them in the wrong sequence can lead to security vulnerabilities or logical errors, such as a logger missing context added by an auth middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eafb1902-3b44-4210-a30b-336f74da6ddf', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does the Just-In-Time (JIT) engine in Tailwind improve the development experience?', N'Middle', N'The JIT engine generates CSS on-demand as you author your HTML, rather than scanning a pre-defined set of utilities. This allows for arbitrary value support, such as specific pixel values or colors not in the theme, and significantly improves build times by avoiding the generation of unused CSS classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e29ac450-730a-42bd-b421-336fe06f5aac', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the ''task'' controller in Lit and why use it?', N'Middle', N'The ''task'' controller provides a declarative way to handle asynchronous data fetching directly within a component. It manages the loading, error, and completion states, reducing the boilerplate code typically required for manual fetch requests and status tracking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'630e7ff1-8602-436c-8cc0-337650993a91', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does the ''CoroutineScope'' structure ensure proper lifecycle management in distributed systems?', N'Senior', N'CoroutineScope provides a structured concurrency mechanism by binding the lifecycle of coroutines to a specific scope, ensuring that all child coroutines are canceled when the parent scope is destroyed. This prevents resource leaks and dangling background processes, which is critical for maintaining stability in complex, asynchronous application architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1053c8e5-bec4-4c38-b62c-3379fc11aa74', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the function of the ''before_action'' filter?', N'Junior', N'A ''before_action'' is a controller method that runs before specified actions are executed. It is commonly used for tasks like authenticating users, setting up common variables, or checking authorization before allowing access to a page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f337bbf3-c01c-49f4-99ab-337aa2183d93', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the ''Main Thread'' and how does Qwik affect it?', N'Intern', N'The main thread is where the browser executes JavaScript. Qwik keeps the main thread free by delaying the execution of JavaScript until an interaction occurs, preventing the main thread from being blocked during page load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'109bf6c2-0e2c-4cce-9a2b-337c741b22fc', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why should you avoid using SELECT * in production queries?', N'Junior', N'Using SELECT * retrieves all columns from a table, which can lead to unnecessary network traffic and memory usage if only specific data is needed. It also makes the application code fragile, as changes to the table schema might break queries that expect a certain column structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9f5bb2d-35bd-4705-aa01-337c83031a84', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How do you create a simple server in Node.js using the HTTP module?', N'Fresher', N'Let''s look at how to create a simple server in Node.js using the built-in http module. Server Setup First, a few steps are necessary. 1. Import the Module: Use require to load the http module. 2. Define Callback Function: For each request, the server will execute a specific callback function. This function takes two parameters: - request: Represents the HTTP request, from which you can extract any necessary data. - response: Use this parameter to define what the server sends back to the client. 3. Server Initialization: Use the http.createServer method to set up the server and define the callback function. 4. Listen on a Port: Use the .listen method to specify the port the server should "listen" on, waiting for incoming requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6587302-3629-4362-a136-337dbd639403', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle data atomicity?', N'Fresher', N'Redis ensures atomicity by executing commands sequentially in its single-threaded event loop. This means that a command will complete entirely before the next one begins, preventing race conditions during simple operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6aa93bc7-16d1-4485-8cba-337e3d354ed0', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle cookies?', N'Junior', N'Echo provides methods within the Context to read, set, and delete cookies easily. You can access cookie values by name or set new cookies with specific attributes like expiration and security flags.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4903df9-2399-4b7c-a90d-3381bdcab8ee', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of an Attribute in database design?', N'Fresher', N'An attribute is a property or characteristic of an entity. For example, in a ''Student'' entity, ''Name'', ''Age'', and ''Student_ID'' are attributes that describe the entity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb30c29d-b7c9-49ce-b7d9-3381fdf13182', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it useful to review previous bug reports while debugging a new issue?', N'Intern', N'Reviewing past reports can reveal if the current problem is a known issue or a recurrence of a previously solved bug. It provides context on common failure patterns in the system and can suggest proven investigation paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'381d9bf9-d0a0-4cb4-a9b8-3382e0704c21', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why does Remix discourage the use of ''useEffect'' for data fetching?', N'Senior', N'Using useEffect for data fetching leads to network waterfalls and inconsistent state, as the fetch only starts after the component has mounted and rendered. Remix encourages loaders because they trigger the fetch as soon as the route is requested, allowing the server to prepare the data while the browser is busy parsing the document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96a2b1a9-8a33-4c4a-a135-33838e3bc57b', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Why is it important to use ''Environment Variables'' in Laravel?', N'Middle', N'Environment variables allow you to store sensitive configuration data like API keys and database credentials outside of your source code. This keeps secrets secure and allows the application to behave differently depending on the deployment environment, such as local, staging, or production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99d7327b-0749-410d-9723-338471aa38cf', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How can Sass help in cross-browser compatibility?', N'Middle', N'Sass mixins can be used to handle vendor prefixing automatically for experimental or non-standard CSS properties. By wrapping these properties in a standardized mixin, you ensure all necessary prefixes are applied consistently without manually writing them every time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b851cccd-f544-47b0-9901-33851177df97', N'4c000000-0000-0000-0000-000000000005', N'What is database indexing and why is it used?', N'Middle', N'An index is a data structure, typically a B-tree, that improves the speed of data retrieval operations on a database table. While it speeds up reads, it can slow down write operations due to the overhead of updating the index.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44231b77-b1fb-49d2-80ca-3385315e6a90', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the benefit of using ''Interfaces'' for service type-hinting in Symfony?', N'Middle', N'Using interfaces for type-hinting adheres to the Dependency Inversion Principle, allowing you to swap service implementations without changing the dependent classes. This makes the system more flexible and easier to maintain or extend.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1cb72a6-f475-42ae-b0c8-33857468bb22', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Explain the concept of ''Response Models'' in FastAPI.', N'Middle', N'Response models allow developers to declare the structure of the data returned by an endpoint, which FastAPI uses to filter out internal fields and validate the output. This ensures that sensitive data is not leaked and that the API consistently adheres to the defined public contract.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fe55266-bb8b-4db5-81ea-3387e1af9cb7', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Describe the impact of using Partial Indexes on database performance and storage.', N'Senior', N'Partial indexes cover only a subset of table rows defined by a predicate, resulting in a smaller index size and reduced maintenance overhead. This is highly effective for filtering commonly queried subsets, although it requires the query planner to match the predicate exactly to utilize the index.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f43f9ab-ff53-4d5b-93c8-338a08576dbc', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does eBPF enhance observability and security in a Kubernetes cluster?', N'Senior', N'eBPF allows for deep, kernel-level visibility into system calls, network traffic, and file access without modifying application code. This enables security tools to detect anomalous behavior, enforce network policies, and audit system activity with minimal performance overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56e29795-7387-453a-ab2b-338f03625528', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is esbuild and why does Vite use it?', N'Intern', N'Esbuild is an extremely fast JavaScript bundler and minifier written in Go. Vite uses it during development to pre-bundle dependencies and transform TypeScript or JSX into standard JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f927a95e-5146-4e46-b36a-33940ecea831', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is REPL?', N'Intern', N'REPL (READ, EVAL, PRINT, LOOP) is a computer environment similar to Shell (Unix/Linux) and command prompt. Node comes with the REPL environment when it is installed. System interacts with the user through outputs of commands/expressions used. It is useful in writing and debugging the codes. The work of REPL can be understood from its full form: * Read: It reads the inputs from users and parses it into JavaScript data structure. It is then stored to memory. * Eval: The parsed JavaScript data structure is evaluated for the results. * Print: The result is printed after the evaluation. * Loop: Loops the input command. To come out of NODE REPL, press ctrl+c twice Simple Expression', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3bfddff-a118-46a3-855c-33971581a6fd', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the difference between ''web::Data'' and local variables in handlers?', N'Junior', N'Local variables exist only within the scope of a single handler execution, while ''web::Data'' provides a way to share state across different requests and threads. ''web::Data'' is essentially a reference-counted pointer that ensures the data persists for the lifetime of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0971343-af78-41c9-b82f-339c610e46c3', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro help with SEO?', N'Fresher', N'Because Astro generates static HTML on the server, search engine crawlers can easily read the page content without needing to execute JavaScript. This makes Astro sites naturally more SEO-friendly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6a917d5-67dc-4f47-af7e-33a1b724ad89', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the function of the browser''s ''noscript'' tag in a modern client-side rendered architecture?', N'Senior', N'The ''noscript'' tag provides a fallback mechanism for users who have disabled JavaScript or when script execution fails. In a modern architecture, it is essential for progressive enhancement, allowing developers to present basic content or a message informing the user that the site requires JavaScript for core functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f554abb-9449-4c19-a223-33a397d29dc6', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What are Mutiny and Uni/Multi in Quarkus?', N'Junior', N'Mutiny is the reactive programming library used by Quarkus to handle asynchronous data streams. A Uni represents a stream that emits either a single item or a failure, while a Multi represents a stream that can emit zero or more items, offering a simple way to manage non-blocking operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f0ee9b9-c4ba-4875-9c46-33a47c947dfa', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does the Serializer component handle circular references during object normalization?', N'Senior', N'The Serializer component handles circular references by using a reference handler or a circular reference limit. This prevents infinite loops when transforming deep object graphs into JSON or XML, ensuring the process terminates gracefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'950f607f-1009-4a60-a4f6-33a69c8ef3b1', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Explain the trade-offs between a centralized database and a federated database approach.', N'Senior', N'A centralized database is easier to maintain and ensures global consistency but becomes a performance bottleneck and a single point of failure. A federated approach splits data across multiple independent databases, improving isolation and scalability, but complicates cross-database queries and global integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3031681-2dc2-4860-a1e8-33a9b6632962', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are static files in Express?', N'Fresher', N'Static files are assets like images, CSS files, and JavaScript files that are served directly to the client. Express provides a built-in middleware called express.static to serve these files efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b0e652b-9278-4692-905d-33aa25c533f3', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is JSX and how does it work?', N'Intern', N'JSX stands for JavaScript XML. It is a syntax extension for JavaScript that allows you to write HTML-like code within JavaScript. JSX makes it easier to create React components by allowing you to write what looks like HTML directly in your JavaScript code. Under the hood, JSX is transformed into JavaScript function calls, typically using a tool like Babel. For example, Hello, world! in JSX is transformed into React.createElement(''div'', null, ''Hello, world!''). ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a51ea5f9-8683-4f89-8030-33ab2d57e94a', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the function of the Garbage Collector in C#?', N'Intern', N'The Garbage Collector is an automatic memory management feature that reclaims memory occupied by objects that are no longer being used by the application. It prevents memory leaks by periodically identifying and removing unreachable objects from the managed heap.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba9aa3c1-9ede-41f5-9fe4-33af4030cc89', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are route parameters in Express and how do you access them?', N'Junior', N'Route parameters are named URL segments that are used to capture values specified at their position in the URL. You can access these values in your route handler using the req.params object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de79a2ef-6058-4841-8fe0-33b0de2c0b79', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is tail call optimization (TCO) in Scala and why is it important?', N'Middle', N'TCO allows the compiler to replace a recursive method call with a jump instruction if the call is the very last action performed by the function. This prevents stack overflow errors by reusing the current stack frame instead of allocating a new one for every recursive step.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd65798d-a17d-4855-a276-33b2ff49e0eb', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why is it important for a router to be lightweight?', N'Fresher', N'A lightweight router ensures that the overhead added to every incoming request is minimal. This contributes to faster response times and lower memory usage, which is critical for high-performance backend services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9577f934-e256-4c0c-b644-33b3f312a889', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Describe the role of ''Chaos Engineering'' in ensuring reliability.', N'Senior', N'Chaos engineering is the practice of proactively injecting controlled failures into a system to identify hidden weaknesses and verify recovery mechanisms. By proving the system''s ability to withstand common failures, it transforms theoretical reliability models into verified operational resilience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'431f5412-0e8e-423d-887a-33b4e67b0d4c', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why is it important to use ''static get styles()'' for CSS in Lit?', N'Middle', N'Defining styles as a static property allows Lit to parse and create a single CSSStyleSheet object that is shared across all instances of the component. This is much more memory-efficient than including style tags inside the render method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfca6d4a-8a78-47dc-953a-33bb059e2ab4', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix achieve high memory efficiency compared to frameworks in garbage-collected languages?', N'Senior', N'Actix benefits from Rust''s ownership model, which eliminates the need for a garbage collector and reduces memory fragmentation. By managing memory manually through smart pointers and stack allocation, it maintains a small footprint even under heavy concurrent load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6442b98d-c372-4162-aa47-33bc9a67ed29', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you approach learning a new technology or framework for a project?', N'Fresher', N'I would start by reading the official documentation to understand the core concepts and design philosophy. Then, I would build a small, simple prototype to practice the features, gradually increasing the complexity as I become more comfortable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e634c08-d4eb-4219-bafa-33bc9aa934b3', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are the semantic and accessibility implications of using generic containers like ''div'' instead of landmark elements?', N'Senior', N'Landmark elements like main, nav, and section provide structural meaning to assistive technologies, allowing users to navigate content via keyboard shortcuts or screen reader landmarks. Replacing these with generic divs strips away this metadata, forcing users to linearize the entire document to find specific sections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cdca196-c78e-4ac3-8a9f-33c2a3ec283b', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the role of the WSGI middleware in a Flask ecosystem.', N'Senior', N'WSGI middleware acts as a wrapper around the Flask application, intercepting requests and responses to perform cross-cutting concerns like authentication, rate limiting, or request rewriting. By placing these operations in the middleware layer, you keep the core application logic clean and decoupled from infrastructure-level requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f6816e5-e69e-46b3-a9e8-33c93c7605f9', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono support different JavaScript runtimes?', N'Fresher', N'Hono uses a platform-agnostic design that avoids relying on Node.js-specific APIs like ''fs'' or ''path'' by default. By sticking to the standard Fetch API, the same code can run on any runtime that supports those standards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4520a82-6d39-468a-9cfd-33c94ea88a94', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the function of the ''request cache'' versus the ''node query cache'' in Elasticsearch?', N'Senior', N'The node query cache stores the results of filter context queries at the segment level, which are highly reusable across different requests. The request cache stores the results of aggregation and search requests at the shard level, which are useful for identical queries repeated frequently by users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99479c5a-73a0-4362-8781-33ca6cceebc0', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'In what scenario would you choose to extend Echo''s Context rather than using custom middleware for data passing?', N'Senior', N'Extending the context is useful for providing common helper methods or pre-fetched user objects across the request scope. However, for cross-cutting concerns that need to run before or after the handler, middleware remains the standard pattern; use context extension only when you need to expose data directly to multiple handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aed54630-88b1-41dc-88be-33cd63870943', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the ''Observer Effect'' in the context of system monitoring?', N'Senior', N'The observer effect occurs when the act of monitoring or instrumenting a system consumes enough resources to alter the system''s performance or behavior. This can lead to misleading metrics or even induce failures in sensitive, high-load environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd63ff726-d1e0-4553-a8f5-33cf2533ab7d', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the Cassandra Query Language (CQL)?', N'Intern', N'CQL is the primary interface for interacting with Cassandra. It provides a syntax similar to SQL, allowing users to define schemas and manipulate data, though it lacks complex features like joins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa515e56-9350-4842-a336-33cf464a43a5', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind solve the issue of ''dead code'' in CSS compared to traditional BEM methodology?', N'Senior', N'BEM relies on developers manually maintaining class names, often leading to orphaned CSS rules that are never used. Tailwind''s utility-first model coupled with automated purging ensures that if a utility isn''t explicitly used in the markup, it is excluded from the final production bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73e56b2c-c9fb-4e5e-ac94-33d0faec37a1', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of the Replication Factor in Cassandra?', N'Junior', N'The replication factor determines the total number of nodes in the cluster that will store a copy of a specific piece of data. Setting a higher replication factor increases fault tolerance and data availability by ensuring multiple nodes hold the same information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d6d61e1-f78f-4012-be48-33d100b41220', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum manage concurrency compared to traditional thread-per-request frameworks?', N'Middle', N'Axum leverages the Tokio asynchronous runtime to handle thousands of concurrent requests using a small number of system threads. This ''event loop'' approach is significantly more resource-efficient than traditional models that spawn a dedicated thread for every incoming connection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29f6bcab-6209-4417-b5aa-33d1019747da', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the role of the ''pom.xml'' or ''build.gradle'' file in Spring Boot?', N'Junior', N'These files are build configuration files that manage project dependencies and build lifecycle. They define which libraries the project needs and tell the build tool, like Maven or Gradle, how to package and execute the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4110231-10d0-4ddf-b834-33d141115845', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does quorum-based consistency work?', N'Middle', N'Quorum-based consistency requires a minimum number of replicas to acknowledge a read or write operation to consider it successful. By adjusting the read and write quorum levels, developers can tune the balance between consistency and latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcc5f512-6081-43a4-b1c0-33d26f20647e', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is meant by ''Zero Hydration'' in Qwik?', N'Intern', N'Zero hydration means that Qwik does not need to perform a costly ''re-hydration'' phase where the framework rebuilds the application state in the browser. Because the state is serialized into the HTML, the application is ready to use as soon as it arrives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66760181-8fca-4700-946d-33d6cfc89fc4', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'When should you choose a custom ''directive'' over a standard component?', N'Senior', N'Directives should be used for low-level DOM manipulation, performance-critical rendering logic, or reusable logic that doesn''t require its own Shadow DOM encapsulation. If the functionality involves complex state or UI composition, a full web component is usually a more maintainable choice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d8795db-6d6a-42e0-babb-33d86d4b096b', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are the trade-offs of using Fastify versus Express as the underlying adapter for NestJS?', N'Senior', N'Fastify offers significantly higher throughput and lower overhead due to its optimized schema-based serialization and routing. However, Express has a much larger ecosystem of middleware and community support, which may be a deciding factor if your project relies heavily on third-party Express-compatible plugins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d8a66a0-afd1-424e-ad15-33d89136df32', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why is ''String'' in Swift designed as a collection of extended grapheme clusters?', N'Senior', N'Swift''s String design prioritizes correctness in internationalized text processing, ensuring that user-visible characters are treated as atomic units. By representing strings as collections of grapheme clusters rather than raw bytes or code points, the language prevents common bugs related to combining characters and emoji. This abstraction adds a small performance overhead compared to fixed-width strings but is essential for modern, globalized software.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96b122c9-eea4-44ef-a093-33dbf13f6627', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you check if an object has a specific property?', N'Fresher', N'To check if an object has a specific property, you can use the in operator or the hasOwnProperty method. The in operator checks for both own and inherited properties, while hasOwnProperty checks only for own properties. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the difference between mutable and immutable objects in JavaScript Mutable objects allow for modification of properties and values after creation, which is the default behavior for most objects. Immutable objects cannot be directly modified after creation. Their contents cannot be changed without creating an entirely new value. The key difference between mutable and immutable objects is modifiability. Immutable objects cannot be modified after they are created, while mutable objects can be.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed7514c7-4708-4bd2-9f3e-33dd449d9c75', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the difference between a Model and a Migration?', N'Intern', N'A migration defines the structure of the database table, such as column names and data types. A model represents the data inside that table and provides methods to interact with it at the application level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8336edc8-8874-4b0a-845a-33df6f0b2896', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the architectural impact of Alpine.js''s reliance on the DOM as the primary template engine?', N'Senior', N'By using the existing HTML as the template, Alpine eliminates the overhead of virtual DOM reconciliation and template compilation processes. This makes the framework extremely fast to initialize, but it limits the ability to perform advanced abstraction tasks like complex component inheritance or shared layout rendering logic. It forces a tighter coupling between HTML structure and JavaScript logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbe42b79-b1e5-4896-b85c-33e1e67eee99', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does the PHP Zend Engine''s memory management system handle cyclic references, and what are the architectural implications for long-running processes?', N'Senior', N'The Zend Engine utilizes a reference counting mechanism for immediate memory reclamation, supplemented by a cycle collection algorithm that identifies and clears circular references by analyzing root buffers. In long-running processes like those utilizing Swoole or RoadRunner, improper handling of these cycles or global state can lead to memory leaks, necessitating a deep understanding of the engine''s garbage collection triggers and the explicit use of unset or nullifying references to maintain stable heap usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bc0e226-e903-470d-8070-33e39c9e8e53', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does data flow in Ember?', N'Junior', N'Ember follows a data-down, actions-up pattern. Data is passed from parent components to child components via properties, and child components communicate back to parents by triggering actions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36f20c28-c031-409c-993e-33e3d54decc7', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How do you handle pagination in DynamoDB for large query results?', N'Middle', N'DynamoDB returns results in chunks if the response exceeds the 1MB limit per request. The service provides a ''LastEvaluatedKey'' in the response, which the application uses in the next request to fetch the subsequent set of data until the key is null.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28bdb044-9e1a-4f55-ac3b-33e456c44005', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How should one handle panic recovery in a Fiber application?', N'Senior', N'One must implement a recover middleware that captures panics, logs the stack trace, and returns a 500 Internal Server Error response to the client. Without this, a single failing request could crash the entire application process, leading to poor availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5de38cb9-fa7f-498c-9a7b-33e61598a56f', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Discuss the impact of Kotlin''s ''data class'' implementation on memory and object equality.', N'Senior', N'Data classes automatically generate ''equals'', ''hashCode'', and ''toString'' implementations based on constructor parameters, ensuring reliable comparison and logging. While convenient, developers must be aware that using mutable properties in data classes can break the contract of ''hashCode'' if the state changes after an object is added to a hash-based collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82eefde1-7bb9-4a4c-811c-33e9160af31b', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Why is it generally recommended to avoid unbounded arrays in MongoDB documents?', N'Middle', N'Unbounded arrays can lead to performance degradation as documents grow, forcing the storage engine to move the document on disk when it exceeds its allocated space. Furthermore, updating large arrays can trigger expensive data reallocations and increase memory pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
