INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f10edfb8-1c6b-4b87-ab98-33f7280b08e0', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a ''key-value'' store in the context of Redis?', N'Junior', N'A key-value store is a database model where every item is stored as an attribute name, known as a key, along with its corresponding value. In Redis, the key is always a string, while the value can be various data structures like lists, sets, or hashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
