INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9cb0d08a-c71d-4acd-8427-34006daeb5fa', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is a distributed cache and when should it be used?', N'Middle', N'A distributed cache stores frequently accessed data across multiple nodes in memory to reduce latency and database load. It should be used when the cost of fetching data from the primary store is high and the data is read more frequently than it is updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a98c930-964e-481a-a65c-3402dc9e2770', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the role of the VNode in Preact?', N'Intern', N'A VNode is a Virtual DOM node, which is a plain JavaScript object representing a DOM element. Preact creates these objects to represent the UI, which are then compared during the reconciliation process to update the actual browser DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07fd5383-5d86-435b-a31d-34034d018823', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux reconcile its synchronous dispatch model with asynchronous requirements?', N'Senior', N'Redux achieves this through middleware that intercepts actions, executes asynchronous logic, and then dispatches a new synchronous action to update the state once the result is available. This pattern maintains the synchronous, predictable nature of the reducer while abstracting the complexity of side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f3f2591-aa12-4bca-bc16-3404bbf8ffc7', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle a situation where a third-party API your system depends on has an outage?', N'Middle', N'I would implement a fallback mechanism, such as serving cached data or a default response, to maintain partial functionality for the user. I would also use a circuit breaker to stop attempting calls to the failing service, preventing resource exhaustion while the system waits for the third party to recover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a06942e8-6d31-4d18-ad46-3404e6ffb1b8', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How do C structure padding and packing affect cross-platform data serialization?', N'Senior', N'Structure padding is implementation-defined to satisfy alignment requirements, meaning the binary layout of a struct can vary between compilers or architectures. For robust serialization, developers must use fixed-width types and manual padding or packed attributes to ensure an identical binary representation across different systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a29de40b-d30f-456b-a229-34094294ce97', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is log aggregation and why is it necessary?', N'Middle', N'Log aggregation centralizes logs from disparate services into a single searchable platform. It is necessary because searching through individual server logs in a distributed system is unfeasible during an incident.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3254898-a95a-48ca-b175-340ae886083c', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is operator overloading in C++?', N'Intern', N'Operator overloading in C++ allows developers to define custom behaviors for operators when used with user-defined types such as classes and structures. This feature enables the creation of more intuitive and expressive code by extending the functionality of standard operators to work with custom types. Key Concepts - Custom Behavior: Operators can be redefined to perform specific actions for user-defined types. - Syntax Enhancement: Allows for more natural and readable code when working with custom types. - Type-Specific Operations: Enables the implementation of operations that are meaningful for particular classes or structures. Syntax for Operator Overloading Operators can be overloaded using either member functions or non-member functions (often declared as friend functions).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e48acf8d-5354-4b68-9173-340f9736e13c', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of a junction table?', N'Intern', N'A junction table is used to implement a many-to-many relationship between two other tables. It contains the primary keys from both related tables to link them together, breaking the relationship into two one-to-many associations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f815922-c0c1-442c-b4a5-34140c78ff30', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is ''batching'' in the context of SolidJS updates?', N'Middle', N'Batching groups multiple signal updates together to trigger a single re-calculation or DOM update. This prevents unnecessary intermediate states and significantly improves performance during complex state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b178571-d5f4-421c-8b2e-3419881f7758', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the significance of the .vite folder in node_modules?', N'Intern', N'This directory contains the cache for pre-bundled dependencies. Vite stores the transformed versions of your dependencies here so that it does not need to re-process them on every startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
