INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44a6fabd-3144-4c39-ba3d-341e10c37732', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the role of the ''checkpoint'' process in PostgreSQL.', N'Middle', N'A checkpoint is a point in the sequence of transactions at which all data files are updated to reflect the information in the WAL. It balances the need for fast crash recovery with the overhead of writing data to disk, as frequent checkpoints shorten recovery time but consume significant I/O resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efe68f44-669e-471e-8a29-3420f862a3a2', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach debugging a distributed system where a request fails intermittently without clear logs?', N'Middle', N'I would start by implementing distributed tracing to visualize the request path across services. This helps identify which specific node or service is dropping the request. Then, I would analyze the infrastructure metrics of that node, such as CPU spikes or memory pressure, to correlate the failures with system resource exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8ffe5a5-639e-4e00-8c1c-3421cdb8fe19', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the difference between ''managed'' and ''unmanaged'' memory in C# and how ''Span<T>'' bridges this gap.', N'Senior', N'Managed memory is tracked by the GC, while unmanaged memory exists outside its purview. Span provides a unified, type-safe, and bounds-checked abstraction that can represent a contiguous region of memory regardless of whether that memory is on the stack, the heap, or in unmanaged memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
