INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf8f97da-3546-4a8a-a288-342a0044e241', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are the trade-offs of using a CSS-in-JS library versus a Sass-based workflow?', N'Senior', N'CSS-in-JS offers scoped styles, component-level dynamic styling, and tight integration with logic, but it adds a significant runtime performance cost. Sass provides a purely static, performant CSS output that is easier to cache and requires no client-side overhead, though it lacks the dynamic component-level state handling of CSS-in-JS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
