INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b715cae-a4a2-43ae-8bc7-3434ee5cee64', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the difference between ''register'' and ''after'' in Fastify?', N'Junior', N'The ''register'' method is used to add a plugin to the application, while ''after'' is a callback that executes once all currently registered plugins in the current scope have finished loading. Use ''after'' when you need to perform actions that depend on plugins being fully initialized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de7d9875-8d36-479a-ad03-3437dc8fc76f', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How are event modifiers like .prevent used?', N'Intern', N'An event modifier like .prevent is appended to an x-on directive to call the event''s preventDefault method automatically. It is a shorthand way to perform common event handling tasks without writing extra logic in your methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a26c9cbc-c5ac-4ccd-aa5f-34396da738ec', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does the ''body-parser'' middleware function work under the hood regarding stream handling?', N'Middle', N'Body-parser listens for data events on the request stream, buffers the chunks until the entire payload is received, and then parses it based on the Content-Type header. Once fully parsed, it attaches the data to the req.body property for use in subsequent middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
