INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'049e2595-bb7a-4a02-b4d9-34684103c68c', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB provide high availability and disaster recovery?', N'Senior', N'MongoDB ensures high availability and disaster recovery through a robust data architecture and a distributed system model. It integrates various mechanisms to maintain data integrity, uptime assurances, and data redundancy. Key Components 1. Replica Sets: These are clusters of MongoDB nodes that use automatic failover to maintain data consistency. 2. WiredTiger Storage Engine: It powers numerous features including data durability, in-memory storage, and compression. 3. Oplog: Short for "operations log", it records all write operations in an append-only manner. 4. Write Concerns: These are rules that determine the level of acknowledgment required for write operations. 5. Read Preferences: They define which nodes in a cluster can satisfy read operations. 6.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
