INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abffa551-18dc-479b-b1c6-346d6297e92f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is variable shadowing in javascript?', N'Intern', N'Variable shadowing occurs when a variable declared within a certain scope (decision block, method, or inner class) has the same name as a variable declared in an outer scope. This outer variable is said to be shadowed. If there is a variable in the global scope, and you''d like to create a variable with the same name in a function. The variable in the inner scope will temporarily shadow the variable in the outer scope. Example: Block-level shadowing (let/const): var does NOT shadow at block level (only at function level): Nested function shadowing: Note: - Shadowing does not modify the outer variable - let/const shadow at block level; var only at function level - Can cause bugs when unintentional — use distinct variable names to avoid confusion', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
