INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6ff085a-dd06-4e38-ade6-347785334a07', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does the C++ object lifetime model interact with stack-based RAII?', N'Senior', N'RAII binds the lifetime of a resource to the lifetime of an object, ensuring that the destructor is called when the object goes out of scope. This deterministic cleanup mechanism is fundamental to C++ for managing memory, file handles, and mutexes, effectively preventing resource leaks without relying on a garbage collector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26727d06-1d43-4597-bb55-3477b3787f84', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What are the architectural considerations for implementing a multi-region messaging cluster?', N'Senior', N'Key considerations include handling cross-region replication latency, resolving potential write conflicts, and managing partition ownership. Architects must decide between synchronous replication, which impacts performance, and asynchronous replication, which risks data loss during regional failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3849efc-6e7c-45db-8d27-3478d3a59754', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does tail-call optimization work in C, and why is it not guaranteed by the standard?', N'Senior', N'Tail-call optimization allows the compiler to reuse the current stack frame for a function call if it is the final action of the current function. Because the C standard requires unique addresses for each function call and maintains strict stack frame tracking for debugging and stack traces, the compiler cannot always guarantee this optimization. Relying on it for deep recursion can lead to stack overflows unless the compiler''s specific optimization flags are utilized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'798dd4f0-666d-492e-8ce6-347b3dfe1f97', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How can you ensure observability of Echo''s routing performance in a production environment?', N'Senior', N'Integrate Prometheus metrics or similar telemetry within a custom middleware to track the latency and frequency of each route pattern. This provides visibility into which endpoints are the most resource-intensive and helps identify bottlenecks in the routing tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'689d3445-9139-4f75-86ed-347ba95a6b94', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact''s diffing algorithm handle list rendering optimization?', N'Senior', N'Preact uses a key-based diffing strategy to track list items, which is generally efficient for basic UI lists. However, it lacks the advanced heuristic optimizations found in React''s Fiber, meaning that developers must be more diligent about providing unique, stable keys to avoid unnecessary DOM mutations in deep, dynamic lists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7ac63f9-c273-45c1-996a-347d23148f91', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of the ''onMount'' lifecycle hook compared to an effect?', N'Senior', N'onMount is used for code that should execute exactly once after the DOM is first rendered. Unlike createEffect, it is not reactive and will not re-run when dependencies change, making it suitable for one-time setup like third-party library initialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51f577fc-fa0d-4f40-8f3f-347dfb5b7760', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How do you ensure thread safety in Django when using global or static variables?', N'Senior', N'Django handles requests in multiple threads or processes, so global mutable state is inherently unsafe. Thread-local storage can be used for request-specific context, but it must be carefully managed to prevent memory leaks and state contamination between requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9824a80-8403-4cfd-8be4-3481128da216', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does consistent hashing help in distributed database systems?', N'Middle', N'Consistent hashing minimizes the amount of data movement required when nodes are added or removed from a cluster. It maps both data and nodes to a circular hash space, ensuring that only a small fraction of keys need to be remapped during scaling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1413679-1d43-48e8-9b01-348354994b29', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle bean scopes?', N'Fresher', N'Bean scopes define the lifecycle and visibility of a managed object. Micronaut supports standard scopes like Singleton, which creates one instance for the application, and Prototype, which creates a new instance every time the bean is requested.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc713297-152c-4eb5-9669-34858c1cd949', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How do you evaluate the trade-offs between eventual consistency and strong consistency in a distributed NoSQL system regarding latency and availability?', N'Senior', N'Strong consistency requires synchronous coordination across nodes, such as through consensus protocols, which increases latency and reduces availability during network partitions. Eventual consistency allows for local writes and asynchronous propagation, significantly improving write throughput and availability at the cost of potential data staleness. The choice depends on whether the business requirement prioritizes read-your-writes guarantees or maximum system uptime and responsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10439827-8f22-4cb5-aac3-348bfdd21b9f', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the Go runtime scheduler manage M:N mapping of goroutines to OS threads?', N'Senior', N'The Go scheduler uses a G-M-P model where G represents goroutines, M represents OS threads, and P represents logical processors. The P acts as a resource required to execute Go code, allowing the scheduler to distribute Gs across available Ms efficiently. By multiplexing many goroutines onto fewer OS threads, the runtime minimizes the overhead associated with frequent OS-level context switching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6404f66-8878-4e34-b720-348c609f3a41', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust manage the ''async'' state machine for futures?', N'Senior', N'When an async function is called, the compiler transforms it into a state machine that stores variables across await points. This allows the function to be paused and resumed, with the state machine managing the necessary context and memory, ensuring that local variables persist correctly between asynchronous yields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e55c82aa-fd8b-49cd-9f42-348d51d0102f', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the role of ''Backpressure'' in a stream processing system?', N'Senior', N'Backpressure is a mechanism that allows a system to signal to upstream producers to slow down their transmission rate when the consumer is overwhelmed. This prevents the system from crashing due to memory exhaustion and ensures graceful degradation under high load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca5a8b1d-13d3-4ae5-ab33-348d7d79dd0b', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the ''Three-Phase Commit'' (3PC) protocol, and why is it rarely used in practice?', N'Senior', N'3PC introduces a ''pre-commit'' state to remove the blocking nature of 2PC, allowing nodes to proceed if the coordinator fails. However, it is rarely implemented because it requires more network round trips, increasing latency, and it still fails to guarantee consistency in the face of network partitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
