INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4afefc61-7ec0-42b9-ab9c-34a0cded0c8b', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How do you create an ApplicationContext in a Spring application?', N'Fresher', N'The ApplicationContext serves as the core of the Spring IoC container and is fundamental to the setup of any Spring-based application. Ways to Create ApplicationContext 1. ClassPathXmlApplicationContext: Loads the XML file from the classpath. 2. FileSystemXmlApplicationContext: Loads the XML file from the filesystem. 3. XmlWebApplicationContext: Designed for web applications and loads XML from a specified web application context. 4. AnnotationConfigApplicationContext: When employing Java configuration with @Configuration classes. 5. GenericApplicationContext: A flexible option for advanced customizations. 6. GenericXmlApplicationContext: Lets you control how the XML is read. 7. SilentModeApplicationContext: Quiets any startup messages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
