INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ba5a967-db1a-451c-a608-34a85e90e1c4', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does the ''this'' type in TypeScript provide context-sensitive safety in object-oriented code?', N'Senior', N'The ''this'' parameter allows functions to explicitly define the expected type of the calling context. This ensures that methods are only called on objects that possess the necessary state, preventing errors where functions rely on ''this'' properties that do not exist at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8e00431-d2eb-4efb-9e5b-34a8e03f2b25', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the benefit of Vite''s path aliasing?', N'Middle', N'Path aliasing allows developers to map imports to specific directories, avoiding deeply nested relative paths like ''../../components''. This improves code readability and makes refactoring easier by decoupling imports from the physical file structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37fa704c-68ae-45e5-9641-34a93a6304df', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'In a distributed architecture, why is relying on Express''s default memory-based session store a scalability bottleneck?', N'Senior', N'Memory-based stores are tied to a single process instance, making them incompatible with horizontal scaling where traffic is load-balanced across multiple nodes. This leads to session fragmentation, where users are forced to re-authenticate if subsequent requests hit a different server instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c2ad10b-29e8-48d5-a20d-34a94b4cb0c9', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of the @Component annotation?', N'Intern', N'@Component is a generic stereotype annotation that marks a class as a Spring-managed component. The component scanning mechanism will automatically detect classes annotated with @Component and register them as beans in the application context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'999b47a8-a00b-4ba4-b798-34a9aa229daa', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is your approach to incident management during a major production outage?', N'Senior', N'My primary focus is on restoring service availability through mitigation tactics like rolling back recent changes or increasing capacity. Once the system is stable, I conduct a blameless post-mortem to identify the root cause, document the findings, and implement preventative measures to ensure the same issue does not recur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3dc017a4-00a4-4080-9aaa-34a9ae3e5fc2', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the security value of ''Infrastructure as Code'' (IaC) scanning?', N'Senior', N'IaC scanning detects misconfigurations, such as publicly accessible buckets or open security groups, before deployment. By integrating these checks into the CI/CD pipeline, security teams can prevent flawed infrastructure from reaching production, shifting security left.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b72b9493-6099-47fd-8ba8-34aaba33ab41', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the purpose of the working directory?', N'Junior', N'The working directory is the folder on your computer that R uses as the default location to read and write files. Setting it correctly ensures that R can find your data files without needing full file paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52a4124c-5824-4a13-adf4-34aad767d42a', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is jQuery and why was it traditionally used?', N'Fresher', N'jQuery is a fast, small, and feature-rich JavaScript library designed to simplify HTML document traversal, event handling, and animation. It was traditionally used to provide a consistent cross-browser interface that worked the same way regardless of the browser being used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dab5ecec-1989-48df-96ec-34ab8ec5f09e', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle asynchronous operations?', N'Fresher', N'Express handles asynchronous operations through callbacks, promises, or async/await syntax. When an operation is asynchronous, you ensure the request-response cycle is completed by calling the response methods or the next function once the operation resolves.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bd6d911-0beb-4b45-9660-34ac477ff460', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a system that requires strict consistency versus eventual consistency, what are the primary trade-offs you consider?', N'Middle', N'Strict consistency ensures all users see the same data simultaneously but increases latency and reduces availability during network partitions. Eventual consistency prioritizes high availability and low latency, allowing the system to remain responsive even if data is temporarily stale across nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
