INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f3dc3f2-c365-404d-9b8a-34b09d0e944b', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the function of a Plug in Phoenix?', N'Junior', N'A plug is a small, reusable piece of code that sits between the web server and the application. It can inspect, transform, or halt an HTTP request before it reaches the controller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9372287-281b-40ec-a50f-34b20d264b9d', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you handle secrets or sensitive configuration data in a containerized environment?', N'Middle', N'I would use a dedicated secret management service or a vault to store sensitive information encrypted at rest. The application would fetch these secrets at runtime via environment variables or secret volumes, ensuring that credentials are never hardcoded or stored in version control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6876e657-1aeb-4ec4-8972-34b2bc3a12e2', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the purpose of the ''new'' keyword?', N'Fresher', N'The new keyword is a built-in function that allocates memory for a type. It returns a pointer to the zero value of the type, effectively initializing the memory space.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0bb22fa-edb0-4561-83fc-34b34ce218fd', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Is Preact faster than React?', N'Fresher', N'Preact is generally faster in terms of initial load time and memory usage due to its smaller size. While both perform similarly in terms of rendering speed, Preact''s minimal overhead often results in a snappier experience on low-end hardware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
