INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c4d5516-410c-4fb7-80d1-34b9710d6f12', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the difference between a one-to-many and a many-to-many relationship?', N'Junior', N'A one-to-many relationship means one record in a table is associated with multiple records in another. A many-to-many relationship occurs when multiple records in one table can be associated with multiple records in another, typically requiring a join table to manage the links.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'287c0f41-d3f4-4813-9d2b-34bbcf1a5260', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does the PHP OPcache extension improve performance, and what are the trade-offs regarding cache invalidation?', N'Middle', N'OPcache improves performance by storing precompiled script bytecode in shared memory, eliminating the overhead of parsing and compiling PHP scripts on every request. A key trade-off is that when the source code is updated, the cache must be manually or automatically invalidated; if the configuration is set to check for file changes too frequently, it adds I/O overhead, but if set too infrequently, the application will serve stale code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68b4aa7e-1d81-42a5-a0df-34c185080cbb', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Does Astro support using multiple frontend frameworks at once?', N'Fresher', N'Yes, Astro is framework-agnostic, meaning you can use components from different frameworks like React, Vue, Svelte, or Preact within the same project. This allows developers to mix and match technologies based on specific needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
