INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd33c12d-cc95-4bfa-b3a9-34c31cc1b796', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'A feature is taking longer to implement than you originally estimated. How do you handle this?', N'Junior', N'I would immediately communicate the delay to my team or manager, providing a clear explanation of the unexpected complexity I encountered. This transparency allows the team to adjust expectations early, potentially descoping parts of the feature or reallocating resources to keep the project on track.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c6dc08c-3e5f-4ded-bcfe-34c3c068af35', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Explain how the C preprocessor handles conditional compilation.', N'Middle', N'Conditional compilation uses directives like ifdef and ifndef to include or exclude blocks of code based on pre-defined macros. This allows developers to maintain a single codebase that can be tailored for different platforms, build configurations, or debug versus release modes without creating separate files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
