INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'023f2e41-2a94-4f03-a394-34c548fa7d3c', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s routing implementation differ from the standard net/http ServeMux?', N'Middle', N'Echo uses a high-performance radix tree-based router that supports dynamic path parameters and groups. Unlike the standard library, which primarily uses prefix matching, Echo''s router is optimized for fast lookups even with complex, deeply nested path patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed638d00-a5f1-45d0-a826-34c76c543b31', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Explain the role of Hono’s ''Adapter'' pattern in its compatibility with different server runtimes.', N'Senior', N'The adapter pattern abstracts the differences between platform-specific request/response objects (e.g., Cloudflare''s FetchEvent vs. Node''s IncomingMessage). By normalizing these into a unified internal representation, Hono allows business logic to remain identical regardless of whether it runs on a traditional server, a serverless function, or an edge worker.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcba7e77-fd9f-4fd7-b4c5-34c7a13c6252', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Explain the role of middleware in Hono.', N'Fresher', N'Middleware in Hono are functions that execute during the request-response cycle. They can modify the request or response objects, perform authentication, log details, or stop the request flow before it reaches the final handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d4bf119-d6eb-4013-aa61-34c7bf44a9f7', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How would you approach securing a system against basic unauthorized access?', N'Fresher', N'I would implement a robust authentication mechanism to verify user identities and an authorization layer to enforce access control based on user roles. Additionally, I would ensure that sensitive data is encrypted during transmission and storage to prevent unauthorized exposure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'136078f9-8c47-4b83-bf42-34cd22fc2696', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is Cassandra''s ''Write Path'' considered to be more efficient than its ''Read Path''?', N'Senior', N'Writes are optimized as append-only operations to the commit log and memtable, avoiding disk seeks. Reads, conversely, often require fetching and merging data from multiple sources, such as memtables and several SSTables, which involves significant CPU and I/O overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc30d290-7d2a-4bbf-afd2-34d2b807a27c', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'A user reports that a website feature is broken, but it works fine on your machine. What is your first step to investigate?', N'Junior', N'I would first ask the user for their browser type, version, and operating system to see if there is an environmental mismatch. Then, I would check the browser console logs or network tab to see if there are specific errors occurring in their environment that I cannot replicate locally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f126ca5-6f10-4f51-9ffc-34d51a1e2c7a', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does the ''extern'' keyword affect linking in C++?', N'Middle', N'The extern keyword declares that a variable or function is defined in a different translation unit. It allows multiple source files to share the same global variable or function without causing multiple-definition errors during the linking phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfd6bada-9e9d-44ba-98bc-34d6dc360fce', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP handle memory management compared to languages like C?', N'Middle', N'PHP uses an automated reference counting mechanism and a cyclic garbage collector to manage memory. Unlike C, where developers must manually allocate and free memory, PHP developers are shielded from these tasks, though they must still be mindful of memory limits in long-running processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'feeb4da8-f052-4dce-aa67-34d88fa381c8', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of the ''superglobals'' in PHP?', N'Junior', N'Superglobals are built-in variables that are always accessible regardless of scope. Common examples include $_GET, $_POST, and $_SESSION, which are used to retrieve information from user requests and manage session data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46b6cd62-c2b9-4bee-afdd-34db24b24961', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the significance of ''Existential Types'' in Scala and their role in handling Java interop.', N'Senior', N'Existential types allow for the representation of types where the specific parameter is unknown, such as ''List[_]''. They are primarily used to handle Java raw types or generic collections from Java where type information is lost. While they provide necessary compatibility, they are notoriously complex to reason about and are often restricted in modern Scala versions to prevent unsound type-checking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87026c75-1a5a-45d9-9784-34de4c7d22fb', N'075b8862-431c-4678-9767-f55359758a4a', N'What is Vue CLI?', N'Intern', N'Vue CLI is a simple command line interface for scaffolding Vue.js projects. It will be helpful for rapid Vue.js development. You can install the npm package globally as below, You can find the install version using vue --version command. Note: Vue CLI requires Node.js version 8.9 or above (8.11.0+ recommended).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18ad3ae0-cdeb-438f-917d-34df2484da2a', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are TypeScript Interfaces and how are they used?', N'Junior', N'Interfaces are a way to define a contract for the shape of an object. They ensure that objects contain specific properties with defined types, which helps in enforcing consistency across your application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb3407f7-47b8-4655-a8c8-34e007a4daaa', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why might you use ''ProvidePlugin''?', N'Middle', N'ProvidePlugin automatically loads modules whenever an identifier is used in your code, without requiring you to import them manually. This is useful for globally available libraries like jQuery or specific utility functions that are used heavily throughout a legacy codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50aa09c1-275a-4a2b-a663-34e01f367cec', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the primary purpose of using TypeScript over JavaScript?', N'Intern', N'The primary purpose is to catch common programming errors at compile-time rather than runtime. By defining types, developers can identify bugs early, improve code maintainability, and benefit from better IDE support like autocomplete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'124af906-ae11-488d-b29d-34e11657b34e', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the architectural significance of Server Actions in Next.js, and how do they differ from traditional API routes?', N'Senior', N'Server Actions allow you to call server-side functions directly from client components without explicitly creating an API endpoint. This reduces boilerplate and simplifies the data mutation flow, though it requires careful attention to security, as these functions are effectively public API entry points.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29b7c5e8-64d4-44e8-8c03-34e146261599', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What role does the ''internal'' directory play in Go module architecture?', N'Senior', N'The internal directory provides a mechanism for package encapsulation by restricting imports to packages within the same module tree. This allows library maintainers to expose public APIs while keeping implementation details private, preventing external dependencies from relying on unstable internal code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
