INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bdd6dfc-cfe0-47e8-9df3-34e28076d89b', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the primary role of the browser in a Remix application?', N'Intern', N'In Remix, the browser acts as a runtime for the user interface. It focuses on rendering the HTML provided by the server and handling user interactions, while the server handles the heavy lifting of data management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'681b7961-dd24-41ff-bf03-34e2fbde5bdd', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are capture phase events?', N'Intern', N'The onClickCapture React event is helpful to catch all the events of child elements irrespective of event propagation logic or even if the events propagation stopped. This is useful if you need to log every click events for analytics purpose. For example, the below code triggers the click event of parent first followed by second level child eventhough leaf child button elements stops the propagation. The event propagation for the above code snippet happens in the following order: 1. It travels downwards in the DOM tree by calling all onClickCapture event handlers. 2. It executes onClick event handler on the target element. 3. It travels upwards in the DOM tree by call all onClick event handlers above to it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08f64f41-2660-461a-8c10-34e53be19010', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the purpose of Hono''s ''Basic Auth'' middleware?', N'Fresher', N'The Basic Auth middleware provides a simple way to protect specific routes using username and password authentication. It checks the authorization header of incoming requests and returns a 401 error if credentials are missing or incorrect.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'041ef981-3195-4cf3-bbda-34e578d78012', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is static analysis crucial for Qwik''s performance claims?', N'Senior', N'Static analysis allows the build tools to identify which parts of the code are purely functional and which ones rely on state. This enables the framework to automatically generate the necessary serialization metadata and split the code into the smallest possible chunks without manual developer intervention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c83b7bd-f539-409c-a1f4-34e7756c916d', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the difference between @content in a mixin and passing arguments?', N'Senior', N'@content allows you to pass a block of CSS into a mixin, which is then injected at the point where @content is defined, perfect for wrapping styles in media queries or container logic. Arguments, by contrast, are used to pass specific data values that dictate the internal logic or properties of the mixin.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a175ffe-cd69-46d3-947c-34e77ad054cd', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are typed arrays', N'Intern', N'Typed arrays are array-like objects from ECMAScript 6 API for handling binary data. JavaScript provides 12 Typed array types, 1. Int8Array: An array of 8-bit signed integers 2. Uint8Array: An array of 8-bit unsigned integers 3. Uint8ClampedArray: An array of 8-bit unsigned integers clamped to 0-255 4. Int16Array: An array of 16-bit signed integers 5. Uint16Array: An array of 16-bit unsigned integers 6. Int32Array: An array of 32-bit signed integers 7. Uint32Array: An array of 32-bit unsigned integers 8. BigInt64Array: An array of 64-bit signed BigInts 9. BigUint64Array: An array of 64-bit unsigned BigInts 10. Float16Array: An array of 16-bit floating point numbers 11. Float32Array: An array of 32-bit floating point numbers 12.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddc82c87-2ec4-46c4-8691-34e77eecacbc', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is a Replica Set and how does it ensure high availability?', N'Middle', N'A replica set consists of a group of mongod instances that maintain the same data set, providing redundancy and high availability. If the primary node fails, the remaining nodes automatically initiate an election process to select a new primary, ensuring the database remains operational.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a1153d5-cf2b-49d2-8bfb-34ec58f3bfd2', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the ''request'' object in Flask and what does it contain?', N'Junior', N'The request object is a global object that provides access to the incoming data sent by the client. It contains information such as form data, query parameters, headers, and files uploaded with the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36e5bd3d-c43a-427d-a37e-34ec8e9939ae', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does a Cache-Aside pattern work and what is its primary benefit?', N'Middle', N'In Cache-Aside, the application first checks the cache; on a miss, it fetches data from the database, populates the cache, and returns it. Its primary benefit is that the cache remains lightweight, containing only data that is actually requested, and it is resilient to cache failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25dbf050-3065-4612-9ca4-34ec9e02d781', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of the ''Actuator'' module and what security risks does it introduce?', N'Senior', N'Actuator provides production-ready features like health checks, metrics, and environment info via HTTP endpoints. Without proper security configuration, sensitive endpoints like /heapdump or /env can expose internal memory states, configuration properties, or credentials to unauthorized users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0c73523-d97f-4494-83df-34f03482dcd0', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Does Tailwind CSS work with component-based libraries like React or Vue?', N'Intern', N'Yes, Tailwind works perfectly with component-based frameworks. Because Tailwind classes are applied directly in the HTML-like markup of components, it makes styling reusable components very efficient and predictable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd55899ad-75a2-48a3-b254-34f50fc57f3c', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it important to have consistent log formatting across all services in a distributed system?', N'Middle', N'Consistent log formatting allows centralized logging platforms to parse and index the data effectively. This makes it possible to query across multiple services simultaneously, which is critical for tracking a single request as it passes through various parts of the architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61b1d9e2-e57b-4ff7-ad8d-34f61f6babc2', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How do you handle secrets or environment-specific configuration in Quarkus?', N'Middle', N'Quarkus uses the MicroProfile Config specification, allowing configuration to be injected via environment variables, system properties, or external sources like HashiCorp Vault. Properties can be marked as overridable at runtime, providing flexibility for different deployment environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3b3cc56-7231-4774-aa55-34f80d0f8158', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does TTL (Time to Live) work in DynamoDB, and does it impact throughput?', N'Senior', N'TTL automatically deletes expired items based on a timestamp attribute without consuming billed write throughput. The deletion process happens in the background, though it may cause slight latency during reads if a scan happens to hit an expired item before it is purged. It is a cost-effective way to manage storage lifecycle without manual batch deletion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6133610-d993-45f2-9222-34f8327bbd9c', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the ''equal?'' method used for?', N'Fresher', N'The ''equal?'' method checks for object identity, meaning it returns true only if both variables point to the exact same object in memory. It is the most stringent equality check in Ruby.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4e264ec-85f1-41e0-94ca-34fb4be47c35', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the purpose of API documentation in the design process?', N'Intern', N'API documentation serves as a contract between different services or teams, clearly defining how to interact with a system. It reduces ambiguity, speeds up integration, and serves as a reference point for future maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06d19eac-4b2e-4b7e-b673-34ff59e2e402', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the impact of synchronous code within a Fastify route handler?', N'Middle', N'Synchronous code blocks the event loop, preventing the server from processing other concurrent requests. Even in Fastify, if you perform heavy CPU-bound tasks synchronously, the throughput of the entire application will degrade regardless of the framework''s optimized routing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'307ca9af-44c0-4938-8f89-35030d3dc4bf', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How do extensions affect the memory footprint of a type?', N'Middle', N'Extensions add functionality but cannot add stored properties to a type. Because they do not modify the instance layout, they have no impact on the memory size of the objects themselves.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94f68e3e-f3ef-47b7-b2c1-350485e3ae5b', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is an asset module?', N'Intern', N'Asset modules are a type of module that allows you to use asset files like images or fonts without needing additional loaders. They can either emit a separate file or inline the asset as a data URI depending on the configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfe81e8c-35fd-46b8-b141-35064a8b699c', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'When should you consider moving from a relational database to a distributed SQL database?', N'Middle', N'You should consider this transition when the vertical scaling limits of a single-node relational database are reached and the complexity of manual application-level sharding becomes unsustainable. Distributed SQL databases provide the scale of NoSQL with the transactional integrity of relational systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acca3dd2-23d9-40f1-aae3-350752c16843', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of the ''APIRouter'' class in FastAPI?', N'Junior', N'APIRouter allows you to organize your application into multiple files or modules. It helps keep the code maintainable by grouping related endpoints together rather than keeping everything in a single file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8efb3f2-c020-4724-af66-3508d4a7fc34', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do decorators modify function behavior, and what is the importance of ''functools.wraps''?', N'Senior', N'Decorators are essentially wrappers that replace a function with another, adding functionality before or after the original call. Without functools.wraps, the metadata of the original function, such as its name and docstring, would be lost to the wrapper. Using this utility ensures that the decorated function maintains its original identity, which is crucial for introspection and debugging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68aab8a1-d89a-44ea-8da4-35096ddf83ed', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s generics specialization impact binary size?', N'Senior', N'Generics specialization generates multiple versions of the same code for different concrete types, which can lead to ''code bloat'' and increased binary size. While this improves runtime performance by enabling static dispatch and inlining, it requires the compiler to balance binary size against execution speed. Developers must be mindful of this when designing generic-heavy frameworks that might be linked into many applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b84cc25b-55a8-4719-9385-350b7bedf597', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the significance of the ''Soft State'' in BASE?', N'Junior', N'Soft state means the state of the database may change over time without any input, due to the eventual consistency model. This implies that the data might not be stable or accurate at a single point in time across all nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a917a1c-8f1d-455e-a48b-350bbf41aee9', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What does a database schema represent?', N'Intern', N'A database schema is the formal structure or blueprint that defines how data is organized and how the relations among them are associated. It describes the tables, fields, and relationships that exist within the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfd5271a-c623-4460-ad8f-3512815bc325', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you manage schema evolution in a distributed system to avoid breaking consumers?', N'Senior', N'Adopt additive-only changes to schemas, where new fields are optional and existing fields are never removed or renamed without a multi-phase deprecation cycle. Utilize schema registries for event-driven systems to enforce compatibility checks before deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3928efc-b548-4d07-a51e-3513a57f56af', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why might you choose to use a Map over a standard Object for storing key-value pairs?', N'Middle', N'Maps allow for keys of any type, including objects and functions, whereas Object keys must be strings or symbols. Maps also provide better performance for frequent additions and removals of entries and have a built-in size property, making them more suitable for dynamic collections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10eb1cbc-829d-46e8-9c44-3513ff70c74c', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is a ''Catcher'' in Rocket?', N'Intern', N'A catcher is a function that handles specific HTTP error codes, such as 404 Not Found or 500 Internal Server Error. When an error occurs, Rocket triggers the appropriate catcher to return a custom error page or response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4669d5c-91e8-4fb3-af94-3519df0ba58d', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Why is constant lookup in Ruby considered a potential bottleneck in very deep module hierarchies?', N'Senior', N'Constant lookup involves scanning the lexical scope and the entire ancestor chain of the current module, which can be expensive if the chain is long. Repeated lookups for the same constant in a performance-sensitive loop can degrade performance, leading developers to cache constants in local variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
