INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7761474b-7c85-479b-8fd3-351e602b4e9d', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the @each directive in Sass?', N'Intern', N'The @each directive is a loop that allows you to iterate over a list or a map of items. It is frequently used to generate repetitive styles, such as creating a series of color-coded utility classes from a list of color variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4835a3b8-17f9-4b15-9987-351e988af7cb', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is Replication in Mongodb?', N'Intern', N'Replication exists primarily to offer data redundancy and high availability. It maintain the durability of data by keeping multiple copies or replicas of that data on physically isolated servers. Replication allows to increase data availability by creating multiple copies of data across servers. This is especially useful if a server crashes or hardware failure. With MongoDB, replication is achieved through a Replica Set. Writer operations are sent to the primary server (node), which applies the operations across secondary servers, replicating the data. If the primary server fails (through a crash or system failure), one of the secondary servers takes over and becomes the new primary node via election.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a51dcc2e-50b9-4a60-bfd0-351f6ee94fe7', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the impact of long-running transactions?', N'Fresher', N'Long-running transactions hold locks on database resources for extended periods. This can lead to reduced concurrency, performance bottlenecks, and potential blocking of other users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0541c58b-c0e9-45d1-8008-3521593ed117', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How do ''Context Bounds'' simplify the implementation of type-class based patterns?', N'Senior', N'Context bounds provide syntactic sugar for implicitly passing type-class instances, keeping method signatures clean by hiding the evidence parameter. This makes the code more readable while maintaining the power of implicit resolution. It effectively signals that a function requires an instance of a specific type-class to be available in the environment to operate on the generic type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce43f918-0d9a-45df-b5c8-3524cc0cdea6', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What does ''expression-based'' mean in Rust?', N'Fresher', N'In Rust, almost everything is an expression that returns a value. This means that constructs like if-statements and blocks can return values, which allows for concise and functional programming styles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac7a20d3-2da4-48b4-8439-3528b90df309', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is ''Moving'' in the context of Rust ownership?', N'Fresher', N'Moving occurs when the ownership of a value is transferred from one variable to another. After the move, the original variable is no longer considered valid, which prevents double-free errors when the memory is cleaned up.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bdd4d11-3910-44ac-932b-352a4779f219', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of the ''static'' folder in Django?', N'Intern', N'The static folder stores files that are not dynamic, such as CSS, JavaScript, and images. Django serves these files to the browser to ensure the web application has the necessary styling and client-side functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06c2a5ad-9fae-421d-ba9c-352a96c8d3b4', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why is Svelte considered easy to learn for beginners?', N'Intern', N'Svelte is often considered beginner-friendly because it uses standard HTML, CSS, and JavaScript with minimal framework-specific syntax. It removes the complexity of managing a virtual DOM or learning complex boilerplate structures, making the development process feel very close to writing plain web pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07307d05-c6ab-42ef-b0e7-352eb2eda356', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of ''keyof'' operator?', N'Fresher', N'The ''keyof'' operator takes an object type and produces a string or numeric literal union of its keys. It is very useful for creating type-safe functions that operate on object properties by ensuring the keys exist on the object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1de9134a-268d-4d3f-8807-352f5951ce85', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What are the trade-offs of using Gin’s Context object in a concurrent environment?', N'Senior', N'The Gin Context is not thread-safe and is specifically designed for the lifecycle of a single request. If a background goroutine needs access to the context, the developer must use the Copy method to create a shallow clone, otherwise, data races and memory corruption will occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2696a98-1390-4cc3-971e-352fa78bd49d', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does a ''Write-Around'' policy differ from a ''Write-Through'' policy?', N'Senior', N'In a write-around policy, data is written directly to the database, bypassing the cache entirely, which prevents the cache from being polluted with data that might not be read again soon. Write-through updates both simultaneously, which is better if the data has a high likelihood of being read immediately after being written.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3602f60-da82-4f20-a80c-3530f84e9a25', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the importance of ''Definition of Done'' in the context of accurate estimation?', N'Middle', N'A clear Definition of Done prevents scope creep by establishing exactly what level of quality and completeness is required. Without it, estimates vary wildly because one person might consider a feature done when it is functional, while another considers it done only after testing and documentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'507a7926-8192-4183-a877-35310ded1780', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is Service Discovery in Micronaut?', N'Intern', N'Service Discovery is a feature that allows microservices to automatically find and communicate with each other in a dynamic environment. Micronaut integrates with tools like Consul, Eureka, or Kubernetes to maintain a registry of available services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d66bb10-b2d8-41b5-b598-3531a4a7d6bb', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the Ruby interpreter?', N'Intern', N'The Ruby interpreter, known as MRI or CRuby, is the program that reads and executes Ruby source code directly. It translates the code into a format the computer can understand at runtime, rather than compiling it into machine code beforehand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee67a551-502a-4423-9e57-3531c235d933', N'4c000000-0000-0000-0000-000000000005', N'When would you choose an asynchronous message queue over a synchronous REST API call?', N'Middle', N'Asynchronous queues are preferred when a task is time-consuming or requires decoupling between services. They prevent the requesting service from blocking while waiting for a response, which improves system resilience and responsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82721ab0-7a7a-42f1-abdf-3532be0b4f63', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of the ''let'' and ''var'' keywords?', N'Intern', N'The ''let'' keyword is used to declare constants, meaning the value cannot be changed once it is set. The ''var'' keyword is used to declare variables, which allow the value to be modified at any time after the initial assignment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baa0273f-4e82-4910-a333-35331dde299f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does the ''satisfies'' operator improve type safety compared to direct type annotation?', N'Senior', N'The ''satisfies'' operator validates that an expression matches a type without losing the specific inferred information of the expression itself. Unlike direct annotation, which forces the expression to the broader type, ''satisfies'' ensures consistency while preserving the internal structure for further operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fc764b0-aed1-433b-a28d-3535bec9113a', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Can you explain the difference between build-time data fetching and request-time data fetching in Astro?', N'Senior', N'Build-time fetching occurs during the static generation phase, producing immutable HTML files that are fast to serve but require a rebuild for data updates. Request-time fetching happens at runtime on the server, allowing for real-time data integration, though it introduces latency and requires a server to execute the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5467b3b-bf19-44ae-bb7a-3537a194b0d4', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What does the NULL value represent in a database?', N'Fresher', N'A NULL value represents the absence of data or an unknown value in a specific field. It is distinct from a zero value or an empty string.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33715178-e586-4444-8c94-3537ef38710a', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the primary role of the ''nitro'' engine in the Nuxt 3 ecosystem?', N'Senior', N'Nitro is a high-performance server engine built on H3 that allows Nuxt to be platform-agnostic. It handles server-side rendering, API route processing, and middleware, enabling the application to be deployed to almost any environment, including Edge functions, Node.js, or serverless providers, through a unified output format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77820b62-719f-489e-a778-3538ee5bdce2', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Generics, and why would you use them?', N'Junior', N'Generics allow you to create reusable components that work with a variety of types rather than a single specific one. They provide a way to maintain type safety when creating functions or classes that need to handle different data types while keeping the logic consistent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ce7ffac-60ee-46fe-818f-353a19bbc891', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the potential drawbacks of using ''callbacks'' (e.g., after_save) in Rails models?', N'Middle', N'Callbacks can make code flow difficult to trace, as they trigger logic implicitly whenever a record is saved. Over-reliance on them can lead to unexpected side effects, complex dependency chains, and difficulty in testing specific operations in isolation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
