INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08ee8d70-eeb6-431d-8069-3558887b2a87', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Explain the ''waterfall'' problem in data fetching and how Next.js mitigates it.', N'Middle', N'A waterfall occurs when components wait for their parent''s data to finish loading before starting their own fetch. Next.js mitigates this by allowing you to initiate multiple data requests in parallel at the layout or page level, or by using patterns that stream parts of the UI independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
