INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abff4117-2c3c-48a0-bac0-35609d0a6283', N'075b8862-431c-4678-9767-f55359758a4a', N'Why is the order of execution in the Vue lifecycle hooks critical for server-side rendering?', N'Senior', N'In SSR, only the creation-phase hooks like beforeCreate and created are executed on the server. Lifecycle hooks that depend on the DOM, such as onMounted, will not run, necessitating careful design to ensure that data fetching and state initialization happen in hooks compatible with both environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72fb7467-1670-42d6-b9ba-3561fa904acb', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the significance of the ''Kubernetes'' integration in Quarkus?', N'Middle', N'Quarkus provides native support for generating Kubernetes manifests, Helm charts, and Knative services directly from the build configuration. It allows developers to define deployment requirements within the application code, simplifying the transition from local development to cloud-native production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01f46d7b-83fe-4f76-bbc4-35648f3b1496', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Explain how to choose between a push and pull model for real-time data updates.', N'Senior', N'The push model (WebSockets/SSE) provides lower latency and is efficient when data changes are infrequent, but it requires maintaining persistent connections per client. The pull model (polling) is simpler to implement and more scalable if the frequency of updates is predictable and the client can tolerate slight latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9343572f-d583-42c4-8d97-3566ea7f0530', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do context managers work, and why are they preferred for resource management?', N'Middle', N'Context managers use the __enter__ and __exit__ methods to define setup and teardown logic, typically utilized with the with statement. They ensure that resources like file handles or network connections are properly released even if an exception occurs. This pattern promotes cleaner code and prevents resource leaks compared to manual try-finally blocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1fea03b-72e9-464d-8aa1-3568fe21caa6', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How do you handle exceptions in Kotlin?', N'Junior', N'Exceptions are handled using ''try'', ''catch'', and ''finally'' blocks, similar to many other languages. However, in Kotlin, all exceptions are unchecked, meaning you are not forced to declare or catch them explicitly in your method signatures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f0af2b6-c2d1-489d-8d1b-356b26d70223', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What are the trade-offs of using request-response patterns over a message queue?', N'Senior', N'Request-response is simpler to implement for synchronous flows but creates tight temporal coupling between services. Using a message queue allows for asynchronous decoupling, improved resilience, and traffic smoothing, but adds architectural complexity regarding correlation IDs and response handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e27600f-694b-4918-92a7-356eea3c613b', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Explain static generation of React applications and its benefits', N'Fresher', N'Static generation (SSG) pre-renders pages to HTML at build time, instead of rendering them per request. The output is plain files that can be served from a CDN, which makes loads fast and SEO straightforward. Frameworks like Next.js, Remix, Astro, and Gatsby support it; in Next.js''s App Router, fetches are statically generated by default and generateStaticParams enumerates dynamic routes at build. Incremental Static Regeneration (ISR) lets you re-build individual pages in the background after a TTL, so static does not have to mean stale. SSG is best for content that does not vary per user and does not need to be perfectly fresh. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
