INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a8e9567-ad9a-46c4-9139-35733d767f2f', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What architectural patterns should be followed when building a large-scale application in FastAPI to maintain project structure?', N'Senior', N'To maintain scalability, use FastAPI''s ''APIRouter'' to group related endpoints into modules or micro-services. Organize the project by domain rather than by type, and separate business logic from the routing layer to ensure that individual components remain testable and decoupled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
