INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a745afb-286b-4b77-9103-35a37e9272f6', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the main features of React Intl?', N'Intern', N'Below are the main features of React Intl, 1. Display numbers with separators. 2. Display dates and times correctly. 3. Display dates relative to "now". 4. Pluralize labels in strings. 5. Support for 150+ languages. 6. Runs in the browser and Node. 7. Built on standards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05ab5216-6e21-4a7c-8d4a-35a3e58cbc4d', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of foreign keys beyond enforcing referential integrity?', N'Middle', N'Foreign keys serve as documentation of the relationship between entities, which helps developers and tools understand the data model. They also prevent the deletion or modification of parent rows that would leave orphaned records in child tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af701ce2-16f6-4b3d-adb7-35a55bda7963', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How do you distinguish between single-line and multi-line comments in PHP?', N'Fresher', N'Single-line comments are created using two forward slashes or a hash symbol. Multi-line comments are enclosed within a forward slash followed by an asterisk at the start and an asterisk followed by a forward slash at the end.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aeac528d-5070-4d94-b382-35a58c889ea9', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is an immutable update in the context of Redux?', N'Junior', N'An immutable update involves creating a new copy of the state object with the necessary changes rather than modifying the existing object. This is crucial because it allows Redux to perform shallow comparisons to determine if the state has changed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bac0397-9917-485c-82a2-35a601835916', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Describe the impact of ''Normalization'' on read vs. write performance.', N'Senior', N'Normalization reduces data redundancy, which generally improves write performance and data integrity by minimizing update anomalies. However, it often requires complex joins during reads, which can decrease read performance compared to denormalized schemas that store redundant data for faster retrieval.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91d20588-78f1-4d3e-8f17-35a7963a1674', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you design for partial failures in a microservices API chain?', N'Senior', N'Implement circuit breakers to prevent cascading failures and use graceful degradation to return cached or default data if a downstream dependency fails. Ensuring timeouts are set appropriately across the stack prevents resource exhaustion in upstream services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
