INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81664340-a6b3-4241-9fb0-35a81ee481b2', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the difference between Sass and SCSS?', N'Intern', N'Sass is the original syntax that uses indentation and no curly braces, while SCSS is the newer syntax that is fully compatible with standard CSS. SCSS uses curly braces and semicolons, making it the most commonly used version in modern development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ab96241-0b8b-42ed-ab80-35a90eb4746e', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle accessibility (A11y) in the context of Shadow DOM?', N'Senior', N'Because Shadow DOM isolates elements, traditional global accessibility tools may struggle to pierce the shadow boundary. Lit supports ARIA attributes on host elements, and developers should leverage techniques like aria-reflection and slots to ensure the accessibility tree remains correctly connected to the light DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2083b084-6ca1-4839-8a72-35a9833b0006', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are the performance implications of using Sass maps compared to individual variables?', N'Senior', N'Sass maps allow for better organization of related data, such as theme configurations or breakpoints, and can be programmatically iterated over using loops. While there is a negligible performance cost during compilation, the architectural benefit of centralized data structures far outweighs the overhead in complex design systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
