INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'130b4f89-a797-4be9-a103-35b24689d601', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix handle concurrency compared to traditional thread-per-request models?', N'Middle', N'Actix utilizes an asynchronous, event-loop based architecture driven by the Tokio runtime. Instead of blocking threads for I/O, it uses non-blocking operations, allowing a small number of threads to handle thousands of concurrent connections efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'877548c9-6cb5-44f5-837b-35b2bc6ed36b', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Interfaces in TypeScript and how do they work?', N'Intern', N'In TypeScript, an interface defines the structure and types of its members. It acts as a contract for the required properties and methods, ensuring that implementing classes or objects match this structure. Key Features of Interfaces - Type Consistency: Objects that adhere to an interface''s structure are considered compatible with it. - Optional and Readonly Members: Interfaces allow for optional attributes and readonly members with the ? and readonly keywords respectively. - Call Signatures: Interfaces can define method types, specifying function parameter and return types. - Index Signatures: Useful for specifying that an object can have any number of properties, all of a certain type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
