INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84004341-566e-4156-af73-35c731b03766', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the function of the ''Drop'' trait, and how does it facilitate deterministic resource management?', N'Senior', N'The Drop trait allows developers to define custom logic for cleaning up resources when an object is deallocated. It is the core mechanism of RAII in Rust, ensuring that non-memory resources like file handles, sockets, or mutex locks are systematically released the moment an object''s lifetime ends.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
