INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd8a8f34-a5d0-48f2-9bee-35ca88795d2e', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why is the use of global state (e.g., global variables) discouraged in large-scale PHP architecture?', N'Senior', N'Global state creates tight coupling and makes unit testing, parallel processing, and dependency injection difficult. It also interferes with the isolation of the share-nothing architecture, potentially leading to unpredictable side effects and bugs when the same process is reused across requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9b99b0d-78d9-41b4-a688-35ca8890b2cc', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Compare the overhead of using reflection in PHP versus static analysis.', N'Senior', N'Reflection in PHP is expensive because it requires the engine to parse class metadata at runtime, which is resource-intensive. Static analysis tools move this cost to the build phase, offering better performance and earlier detection of architectural flaws without impacting runtime latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7243e001-43aa-4c60-a75e-35d25c68e148', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why should you avoid using ''any'' in a large codebase?', N'Middle', N'Using ''any'' breaks the type safety guarantees of TypeScript, effectively turning off the compiler''s ability to catch bugs related to property access or type mismatches. This can lead to unexpected runtime crashes and makes refactoring significantly more dangerous.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'122ec099-265a-4955-9b1b-35d26cd1c993', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the difference between static and dynamic binding in C++.', N'Middle', N'Static binding occurs at compile-time, where the function call is resolved based on the pointer or reference type. Dynamic binding occurs at runtime through virtual functions, where the call is resolved based on the actual type of the object being pointed to.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'549650f4-89ee-46ce-adc0-35d41ba521c2', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between for..in and for..of?', N'Fresher', N'Both for..of and for..in statements iterate over lists; the values iterated on are different though, for..in returns a list of keys on the object being iterated, whereas for..of returns a list of values of the numeric properties of the object being iterated. * for in: iterates over all enumerable properties of an object that are keyed by strings. * for of: iterates over the values of an iterable objects. including: built-in String, Array, array-like objects (e.g., arguments or NodeList), TypedArray, Map, Set, and user-defined iterables. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e84ff31-03c4-4f0e-85a5-35d42e6512b2', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of a database schema?', N'Intern', N'A database schema is the formal definition or blueprint of how data is organized in a database. It defines the tables, the fields in each table, and the relationships between those tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89d4a127-a074-49a0-9465-35d7adf6ae7b', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the trade-offs of using ''Mapped Types'' versus manual interface definition?', N'Senior', N'Mapped types provide a programmatic way to transform existing types, ensuring that changes to the original source are automatically propagated throughout the system. While they offer superior maintainability and reduce boilerplate, they can result in highly complex, difficult-to-debug type signatures that may impact IDE performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'318aa6cc-1a10-4aa9-8b01-35d9cbae022b', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Does Chi require any external dependencies?', N'Intern', N'No, Chi is designed to have zero external dependencies. It relies only on the Go standard library, which keeps the project lightweight and easy to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6099be0-5213-4c27-9c88-35daae23c582', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What does ''attribute reflection'' mean in Lit?', N'Fresher', N'Attribute reflection is the process where a change to a component property is automatically reflected back to the corresponding DOM attribute. This is useful for styling based on attributes or for accessibility purposes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fa6a2c0-2ccd-4c2f-9e2b-35daf7282bbb', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the N+1 query problem in Rails, and how can it be addressed?', N'Middle', N'The N+1 problem occurs when an application executes one query to fetch parent records and then executes an additional query for each child record. It is typically resolved using the eager loading technique provided by the includes method, which fetches associated data in a single or minimal set of subsequent queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbd80fb6-28d2-42aa-8182-35db72bfb74f', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Does Fastify support middleware?', N'Intern', N'Yes, Fastify supports Express-style middleware through the fastify-express or middie plugins. However, it is generally recommended to use Fastify''s native hook system for better performance and consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7df886f9-6fd2-46cb-bbcb-35dc80eb79e7', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the ''Zone'' concept in Dart and when is it used?', N'Middle', N'Zones represent an execution environment that can capture and handle errors, print statements, or timers within a specific context. They are primarily used for error logging, managing asynchronous operations across a call stack, and providing a unified way to handle exceptions in complex applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e30b1b00-5651-4216-89e7-35e046b76129', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the ''Refreshable'' scope in Micronaut?', N'Junior', N'The @Refreshable scope allows beans to be recreated when a configuration change event occurs. This enables the application to update its state dynamically without requiring a full restart.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc5b9c5c-0c77-4f7a-b202-35e5bd023ced', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does two-way data binding work in Ember?', N'Intern', N'Two-way data binding synchronizes the data between the application''s state and the UI elements. If the user updates an input field, the underlying data model is updated automatically, and vice-versa.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a32cb83d-8357-4b5f-9c00-35e6d27f7c7a', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the security mechanisms available in Node.js?', N'Fresher', N'1. Helmet module: Helmet helps to secure your Express applications by setting various HTTP headers, like: * X-Frame-Options to mitigates clickjacking attacks, * Strict-Transport-Security to keep your users on HTTPS, * X-XSS-Protection to prevent reflected XSS attacks, * X-DNS-Prefetch-Control to disable browsers DNS prefetching. 2. JOI module: Validating user input is one of the most important things to do when it comes to the security of your application. Failing to do it correctly can open up your application and users to a wide range of attacks, including command injection, SQL injection or stored cross-site scripting. To validate user input, one of the best libraries you can pick is joi. Joi is an object schema description language and validator for JavaScript objects. 3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ae9e832-bab4-4a69-963c-35eb5691461a', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why are smart pointers preferred over raw pointers in modern C++?', N'Middle', N'Smart pointers like unique_ptr and shared_ptr automate memory management by using RAII, which ensures that resources are automatically cleaned up when the pointer goes out of scope. Raw pointers do not provide ownership guarantees, making them prone to memory leaks and dangling pointer vulnerabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a01e73d8-db07-451c-89cd-35ed0697cce0', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you balance the need for documentation with the need for writing code?', N'Intern', N'Documentation is a tool to reduce future cognitive load and onboarding time. I treat it as a necessary part of the development process, balancing the two by documenting critical design decisions while keeping routine documentation concise and automated where possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'689c32d5-5a7a-468d-8ad8-35ee4c3509d5', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you optimize static file serving in a production Flask environment?', N'Senior', N'Flask should never serve static files in production; instead, these should be handled by a dedicated web server like Nginx or a Content Delivery Network (CDN). This reduces the load on the Python application, allowing it to focus exclusively on dynamic logic processing and API response generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5a594ec-60b0-43b8-8ff8-35ef7d0ebeaf', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django manage static and media files in production, and why is this different from development?', N'Senior', N'In development, Django serves static/media files directly, which is slow and insecure for production usage. In production, these files must be collected and served by a dedicated high-performance web server like Nginx or offloaded to a CDN to ensure efficient delivery and security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
