INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fffd8d4d-7b56-4474-a8ac-35f3daa48193', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Compare the use of ''find_each'' versus ''all.each'' when processing large datasets.', N'Senior', N'Using ''all.each'' loads the entire dataset into memory at once, which can lead to OOM (Out Of Memory) errors for large tables. ''find_each'' fetches records in batches, significantly reducing memory consumption and allowing for stable processing of millions of records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b28ce14-877d-411c-bdd2-35f3e9fe10c0', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is a ''lifespan'' event in FastAPI and why is it used?', N'Middle', N'Lifespan events allow you to run code before the application starts and after it shuts down, such as initializing database connection pools or closing caches. This ensures that expensive resources are managed correctly throughout the lifecycle of the server process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08dcdf6f-6668-46d6-9aea-35f6f2672107', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Describe the difference between an Exclusive and a Share lock in PostgreSQL.', N'Senior', N'A Share lock allows other transactions to read the data but prevents them from modifying it, commonly used in consistent reads. An Exclusive lock prevents other transactions from both reading and modifying the data, ensuring the holder has complete, isolated control during a write operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2f48947-2581-4765-a5dc-35fb6b904cf6', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Can a transaction contain multiple SQL statements?', N'Fresher', N'Yes, a transaction can consist of one or many SQL statements. All these statements are grouped together to ensure they all succeed or fail as a single unit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e93c5c7-210b-492b-af3e-35fb8e52aced', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is meant by ''high availability'' in MongoDB?', N'Intern', N'High availability means the system is designed to stay operational and accessible even if one or more hardware components fail. MongoDB achieves this through replica sets, which ensure data redundancy and automatic failover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f15290a-dea8-451d-8256-35fc3d35fb01', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach designing a system that must comply with strict data residency laws?', N'Senior', N'I architect the system to be region-aware, ensuring that sensitive data is stored and processed only within the required legal boundaries. I use location-based routing and localized database sharding to ensure compliance while maintaining a global service presence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2ec2b7f-8587-4135-8bf2-3602e4de36bc', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain how Dart''s tree-shaking process works during the compilation phase.', N'Senior', N'The Dart compiler performs static analysis to identify reachable code starting from the entry point, systematically removing unused classes, functions, and libraries. This process is highly effective for reducing the final binary size, provided that reflection-based patterns are avoided as they obscure the reachability graph.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5d40af7-3f53-4500-a36b-3603b90573eb', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Explain the difference between path parameters and query parameters in FastAPI.', N'Middle', N'Path parameters are part of the URL structure and are used to identify specific resources, defined by curly braces in the path. Query parameters are appended to the URL after a question mark and are typically used for filtering, sorting, or pagination of resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a566275-784d-4ca5-b806-36048307838d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs of using an event-driven architecture compared to a request-response model?', N'Senior', N'Event-driven architecture promotes loose coupling and scalability but introduces difficulties in tracing distributed transactions and debugging asynchronous flows. Request-response is intuitive and easier to debug, but often leads to tight coupling and poor performance in deep call chains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cff52f9b-0c84-4bec-8d2c-36091433461d', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a distributed system, how do you handle the trade-off between consistency and availability during a network partition?', N'Senior', N'Apply the CAP theorem to prioritize business requirements. If data integrity is non-negotiable, favor consistency and accept potential downtime, whereas if high uptime is critical for user experience, favor availability and implement eventual consistency mechanisms like conflict resolution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0bfa336-8679-416c-816a-360adc4772c4', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Can you define multiple handlers for a single route in Gin?', N'Junior', N'Yes, Gin supports a chain of handlers for every route. You can pass multiple functions to a route definition, and they will execute sequentially, which is useful for applying route-specific middleware or guards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2836b483-094b-495c-b6d6-360bb529774c', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Why would you implement API versioning, and what are the common strategies?', N'Middle', N'Versioning ensures backward compatibility when breaking changes are introduced to an API. Common strategies include URI versioning, custom header versioning, or media type versioning, each with trade-offs regarding cacheability and client complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6006dc49-736e-4aff-8629-360df4baae99', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Why would you use an index in a MongoDB collection?', N'Junior', N'An index is used to improve the efficiency of read operations by allowing the database to locate specific documents without scanning every single document in a collection. Without an index, MongoDB must perform a full collection scan, which significantly slows down performance as the dataset grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b843c70-f392-4776-b5e5-360e63ecb960', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle middleware in comparison to standard Go net/http handlers?', N'Fresher', N'Chi utilizes a middleware stack that is designed to be fully compatible with the standard net/http interface. It allows you to wrap handlers or entire router groups with common functionality like logging, recovery, or authentication, ensuring that the middleware executes before the final request handler is called.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c0dc176-123f-4238-9025-36108376cbaa', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How should you handle heavy, CPU-bound computations in an Actix-web application?', N'Middle', N'CPU-bound tasks should be offloaded to a dedicated thread pool using the ''web::block'' function. This moves the computation off the main event loop, allowing the runtime to continue handling incoming I/O requests concurrently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c614a410-de81-4a98-a4e1-3611f64cdbee', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the benefit of using Request classes in Laravel?', N'Junior', N'Form Request classes allow you to encapsulate validation logic away from your controllers. This keeps your controller methods clean and readable by ensuring that the request is already validated before the controller logic even begins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4493ccba-be17-4fd1-8fb4-36129f119907', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'When is it appropriate to use ''Channel'' instead of ''SharedFlow''?', N'Middle', N'Channels are primarily used for communication between coroutines where each value is delivered to exactly one receiver. SharedFlow is better suited for broadcasting events to multiple subscribers, making it the preferred choice for event buses or state observation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
