INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'123e08c4-15c7-453e-b4ba-36268c081697', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you handle a scenario where you have to choose between a simple solution that works now versus a more complex, scalable solution?', N'Intern', N'I would evaluate the current project timeline and the likelihood of the system needing to scale in the near future. If the project is in an early prototype phase, I would lean toward the simpler solution to prioritize speed and flexibility. If the requirements clearly indicate high traffic or complex future needs, I would advocate for the scalable architecture while documenting the trade-offs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72665aef-cb2a-4387-a4b5-3629ca24c301', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the risk of excessive foreign key constraints in high-write systems?', N'Middle', N'Excessive foreign key constraints can introduce significant performance bottlenecks because every write operation must verify the integrity of the reference. In high-concurrency environments, this can lead to locking issues and increased latency during transaction processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9908fca1-79a5-42af-90ab-362e09f2c498', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Discuss the challenge of implementing distributed tracing in an Express application compared to framework-native solutions.', N'Senior', N'Since Express does not natively manage request context across asynchronous boundaries, implementing distributed tracing requires manual propagation of trace IDs through the ''req'' object or using heavy-weight instrumentation libraries. Native solutions in other frameworks often handle this context propagation implicitly, simplifying observability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'371076d0-ab9f-400e-9a6c-363632f55724', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between Kestrel and IIS?', N'Intern', N'Kestrel is a lightweight, cross-platform web server included by default in ASP.NET Core applications. IIS is a full-featured web server for Windows that typically acts as a reverse proxy to forward requests to Kestrel.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
