INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac28ed1e-31aa-46e9-a9cb-36374a5a39ac', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is a sealed class in Kotlin?', N'Intern', N'A sealed class is used to represent restricted class hierarchies, where a value can have one of the types from a limited set. It is particularly useful for state management and representing finite sets of options, as it ensures all possibilities are covered in a when expression.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c82b3681-6a9c-4930-a985-363907a1eed2', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the role of the Swift compiler''s ''SIL'' (Swift Intermediate Language) in the compilation pipeline?', N'Senior', N'SIL is a high-level intermediate representation that sits between the AST and LLVM IR, designed to capture Swift-specific semantics. It performs critical optimizations such as ARC optimization, devirtualization, and generic specialization that are difficult to express in lower-level LLVM IR. By operating on SIL, the compiler can optimize Swift code while maintaining the language''s safety and performance characteristics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c69c71c-ca3e-49bd-aff1-363937719f99', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Does useMemo prevent re-rendering of child components?', N'Senior', N'The useMemo hook does not directly prevent re-rendering of child components. Its main purpose is to memoize the result of an expensive computation so that it doesn’t get recalculated unless its dependencies change. While this can improve performance, it doesn’t inherently control whether a child component re-renders. However, useMemo can help prevent re-renders when the memoized value is passed as a prop to a child component that is wrapped in React.memo. In that case, if the memoized value doesn’t change between renders (i.e., it has the same reference), React.memo can skip re-rendering the child. So, while useMemo doesn’t stop renders on its own, it works in combination with tools like React.memo to optimize rendering behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3dbaefaa-d688-41a1-8ea1-363a7bc6b5f5', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How can you mitigate the performance bottlenecks inherent in the Express single-threaded event loop when handling CPU-intensive tasks?', N'Senior', N'Express is not designed for CPU-bound operations, as these block the event loop and stall all incoming requests. To handle these, one should offload tasks to worker threads, external microservices, or message queues, ensuring the main process remains free to handle I/O-bound request routing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'713dff7b-87e1-444c-9a71-363acd9c46b0', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the trade-offs of using ''mapped types'' versus ''indexed access types'' in designing scalable data models?', N'Senior', N'Mapped types are highly effective for transforming entire object shapes, such as making all properties read-only or optional, but can generate complex type signatures that are harder for the compiler to resolve. Indexed access types provide surgical precision for extracting specific property types, offering better performance and clarity when building highly generic utility libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
