INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1f10d37-0aa1-4e08-b65a-363ce2d22555', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Does Chi support grouping routes by prefix?', N'Junior', N'Yes, the Route method allows you to group routes under a common path prefix. This keeps the code clean and allows you to apply common middleware to the entire group.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e6d3d53-9fe3-4fbc-b120-364444fb7222', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik achieve its ''zero-hydration'' goal compared to traditional frameworks?', N'Fresher', N'Traditional frameworks require hydration, a process where the client downloads and executes the entire component tree to attach event listeners and make the page interactive. Qwik avoids this by using lazy-loading mechanisms that only download the specific JavaScript code for an interaction at the exact moment a user triggers it, eliminating the overhead of initial hydration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82bb99bd-5b32-43a8-a5c3-3644ab586942', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt handle routing compared to a standard Vue application?', N'Junior', N'Nuxt uses a file-system based router, meaning it automatically generates routes based on the structure and naming of files inside the pages directory. In a standard Vue application, you must manually define and map every route to a component in a separate router configuration file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98956269-5d71-45f9-ab18-36457f366ea0', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it important to design a system with future growth in mind?', N'Intern', N'Designing for growth ensures that the system can accommodate more users, data, or features as the product becomes successful. It prevents the need for a complete rewrite when the original design limitations are eventually reached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd95940c7-dacf-4e0e-9e25-3645af1b84e3', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How can you implement custom logging in Gin that preserves request context?', N'Senior', N'Custom logging middleware should extract trace IDs or user information from the Gin Context and inject them into a structured logger like Zap or Zerolog. This ensures that logs are context-aware and searchable across distributed log aggregation systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d0aa63e-f310-463a-9e8a-3645b03a8f48', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the performance implications of using ''with'' statements in strict mode and non-strict mode?', N'Senior', N'The ''with'' statement dynamically modifies the scope chain at runtime, which prevents the engine from performing lexical analysis or static scoping optimizations. This forces variables to be resolved via dynamic lookups, effectively disabling JIT optimizations and causing significant performance regressions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38f88f60-8dbb-4b09-84ed-36482bdeb404', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Explain the concept of ''Context Scoping'' in Micronaut and why it is vital for memory management.', N'Senior', N'Context scoping allows beans to be tied to specific lifecycles, such as request, thread, or session scope. By strictly defining these scopes, Micronaut ensures that objects are created and garbage collected appropriately, preventing memory leaks that often occur in long-running services with complex state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f3b5021-a297-467e-af4a-36484e024a68', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the primary difference between traditional Jakarta EE applications and Quarkus applications in terms of startup time?', N'Middle', N'Quarkus performs build-time metadata processing and dependency injection wiring, which significantly reduces the work done at runtime. Traditional frameworks perform these tasks during application startup, leading to longer initialization times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3275a1f8-63b6-4ee0-bcb5-364ceaf3b89d', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the function of the Vite development server?', N'Intern', N'The Vite development server provides a local environment to preview your application. It uses native browser capabilities to serve files rapidly and manages features like Hot Module Replacement to keep development fluid.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d866d6d-ffd1-4231-8e50-364f2e191b78', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What does the range keyword do?', N'Intern', N'In Go, range is a versatile loop construct that simplifies iterating over data structures like arrays, slices, maps, strings, and channels. It efficiently handles different data types and abstracts away the underlying indexing or iteration mechanisms. Key Benefits - Clarity: It makes the code more readable by focusing on elements rather than indices. - Safety: Range loops guard against index out-of-bounds errors and ensure element synchronization in concurrent contexts. - Efficiency: They eliminate the need for manual index management. Iteration Mechanics - Slice/Array: It yields both the current element and its index. - Map: It produces key-value pairs. - Channel: When used in a for loop with a channel, range retrieves data from the channel until it''s closed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26a007bc-e488-40bb-ac7d-3650391b6ae3', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the performance implications of using the KEYS command in a production environment?', N'Senior', N'The KEYS command is an O(N) operation that blocks the entire event loop while scanning the keyspace, which can lead to significant latency spikes. In production, it should be replaced with the SCAN command, which provides an iterative approach to traversing the keyspace without blocking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3e9ca88-fdf7-4a1b-87ce-3650a21a57bc', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is optional chaining in JavaScript?', N'Intern', N'Optional chaining Optional chaining is a feature in JavaScript that allows you to safely access nested object properties or functions without worrying about whether the intermediate properties exist or not. It uses the ?. operator to check for nullish (null or undefined) values and short-circuits the expression if it encounters one. Optional chaining was introduced in ECMAScript 2020 (ES11) and is supported in most modern browsers, but not in older ones. To use it in older browsers, you can use a transpiler like Babel, or write your code with alternative techniques like conditional statements or the && operator. Example', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f44398c-7cdf-464a-b2c0-36513234e324', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How would you implement a multi-tenancy architecture in a Spring Boot application using Hibernate and PostgreSQL?', N'Senior', N'You can implement multi-tenancy by using a discriminator column on shared tables or by using separate database schemas per tenant. Using Hibernate''s CurrentTenantIdentifierResolver and MultiTenantConnectionProvider allows you to dynamically switch the data source context based on the incoming request header or security token.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'503bbc34-7770-449d-885f-3652c9bbf7af', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is a Sealed Trait?', N'Intern', N'A sealed trait is a trait that can only be extended within the same source file where it is defined. This allows the compiler to check for exhaustiveness during pattern matching, ensuring all cases are covered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1e1ef72-2104-4566-aded-36544f982fb3', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'A system is experiencing intermittent latency spikes. How do you approach isolating the root cause?', N'Senior', N'I would start by analyzing observability metrics to correlate spikes with specific events like garbage collection cycles, database locking, or network congestion. By using distributed tracing, I would isolate the specific service or dependency that deviates from the baseline performance profile.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'092a48c8-b2dd-4cf2-a10b-36553c3429bd', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Why does Scala run on the JVM?', N'Fresher', N'Scala was designed to be interoperable with Java and leverage the mature, high-performance ecosystem of the Java Virtual Machine. This allows Scala to use existing Java libraries and run on any platform that supports the JVM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b7550d0-fd84-4472-82e3-365543d34d1f', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is a DTO (Data Transfer Object)?', N'Junior', N'A DTO is an object used to carry data between processes, specifically between the client and the server. Using DTOs helps decouple the internal database model from the external API contract, preventing sensitive internal data from being exposed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c953c041-e6c8-4b0e-87ae-365672e3bd5c', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why is data redundancy considered a problem in database design?', N'Intern', N'Data redundancy occurs when the same piece of information is stored in multiple places, which wastes storage space. It also leads to data inconsistency, because updating information in one location might result in conflicting data if other locations are not updated simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26c6c4f6-daea-4d00-a040-365775d5a970', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between a structure and a union?', N'Intern', N'In a structure, each member has its own dedicated memory location, allowing all members to be stored simultaneously. In a union, all members share the same memory location, meaning only one member can hold a value at any given time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5ad86f9-0734-4d4e-b1ae-3658fd8e1d0f', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the role of the dispatch function?', N'Intern', N'Dispatch is the only way to trigger a state change in Redux. You call it with an action object, which then sends that action to the store''s reducers to update the state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9468e35-5817-45bb-9a02-365ba28cc26c', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How do ''weak'' and ''unowned'' references differ, and when should you use each?', N'Middle', N'Weak references are optional and automatically become nil when the object they point to is deallocated, making them safe for optional relationships. Unowned references assume the object will always exist, providing a non-optional alternative that avoids the overhead of optional unwrapping.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'005feba2-feae-4ec3-8bc4-365fc4f0ee38', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Describe the purpose and scalability benefits of the Phoenix PubSub adapter architecture.', N'Senior', N'The PubSub adapter decouples the message broadcasting mechanism from the application logic. By using distributed backplanes like Redis or PG2/Distributed Erlang, Phoenix allows developers to scale real-time features across multiple physical nodes seamlessly, ensuring messages reach clients regardless of which node they are connected to.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a685a2a-2b17-442e-82f5-36606cdad03f', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the CAP theorem and how does it apply to database design?', N'Middle', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. In the event of a network partition, designers must choose between immediate consistency or continued availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b7d5fd4-de3d-480c-86db-3660ec95ca29', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you manage the trade-off between speed and accuracy in a project?', N'Intern', N'I would determine the consequences of being wrong versus the consequences of being slow. In critical systems, accuracy is paramount, whereas in early-stage prototyping, speed is often more valuable to gather quick feedback.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'113d7a2c-4a6e-42f3-ab2a-3660faa483a0', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of the _id field?', N'Intern', N'The _id field is a unique identifier for a document within an index. It allows you to retrieve, update, or delete a specific document directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c3edc91-9048-46d5-9c49-3661b72512ff', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are the trade-offs of using Dart''s AOT compilation versus JIT compilation?', N'Senior', N'JIT compilation provides fast development cycles with hot reload by compiling code on the fly, but results in slower execution and higher memory overhead. AOT compilation generates optimized machine code for production, offering faster startup times and better performance, at the cost of significantly longer build times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7dc97478-9ef2-464c-8b94-3664ee3d0432', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the benefit of using a multi-datacenter replication strategy?', N'Middle', N'It provides high availability and disaster recovery by ensuring that data exists in geographically separate locations. It also allows local reads and writes, which significantly reduces latency for users spread across different regions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b7ccf7f-4a7e-4ce0-9ac4-36657f3e25cd', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Is R case-sensitive?', N'Intern', N'Yes, R is a case-sensitive language. This means that variable names, function names, and commands must be typed exactly as defined, as ''X'' and ''x'' would be treated as two different identifiers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1565565f-43f9-4f91-8a4e-3665ff26e955', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How do ''Bloom Filters'' optimize database performance?', N'Senior', N'A Bloom filter is a probabilistic data structure used to quickly determine if an element is definitely not in a set or possibly in it. Databases use them to avoid unnecessary disk I/O by checking the filter before attempting to search the actual data files for a specific key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd91a9392-3461-477f-94f3-3666b6a8ad92', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Explain the concept of Code Splitting and why it is beneficial for performance.', N'Middle', N'Code splitting is the process of breaking a large bundle into smaller, chunks that can be loaded on demand or in parallel. This improves performance by reducing the initial load time, as the browser only needs to download the essential code required for the current page rather than the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcc12a84-de24-4ad3-89de-36673926e95b', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the ''Content Type Parser'' in Fastify?', N'Intern', N'It is a mechanism that allows you to define how Fastify should handle different request content types. You can add custom parsers to process data formats other than standard JSON or plain text.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce97fc77-c459-47da-96e1-36675352883a', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the primary benefit of using ''rollover'' indices?', N'Middle', N'Rollover indices allow for automated management of time-series data by creating a new index once the current one reaches a specific size or age. This keeps individual index sizes manageable and simplifies data lifecycle management by allowing older indices to be deleted or moved to cold storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71c45488-2aa0-407b-87ca-36681d8136ee', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery''s event delegation mechanism work, and what are the scalability benefits for dynamic DOM structures?', N'Senior', N'Event delegation attaches a single listener to a high-level ancestor element, utilizing event bubbling to catch triggers from descendants. This is highly scalable because it avoids the memory overhead of attaching individual listeners to thousands of dynamic elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'716bf292-c7d4-45fd-8d9f-366a5e2520d3', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind help prevent the ''CSS Specificity Wars''?', N'Middle', N'Because Tailwind utilities are applied directly to elements and generally use low-specificity selectors, the order of classes in the HTML usually dictates the styling. This eliminates the need for complex selector nesting or !important overrides, which are common causes of specificity issues in traditional CSS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e1d4b62-017c-422c-98bc-366cca6c6e2b', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the ''will-change'' property influence browser memory and GPU usage?', N'Senior', N'The will-change property prompts the browser to promote an element to its own compositor layer. While this prevents layout shifts and improves animation smoothness, overusing it can lead to excessive GPU memory consumption and potentially trigger layer explosion, which degrades overall rendering performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df6b9e0e-c296-4737-a91c-366da9b64d48', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik''s serialization mechanism handle complex objects and closures?', N'Senior', N'Qwik uses a specialized serializer that traverses the component state and replaces functions or complex references with unique identifiers. During runtime, the framework uses these identifiers to map the serialized data back to the actual code chunks that are lazily fetched from the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a29d4192-1db8-4288-b8ca-366f30ee4751', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between Constructor Injection and Setter Injection?', N'Fresher', N'Constructor injection provides dependencies through the class constructor, ensuring the object is fully initialized with its requirements. Setter injection uses setter methods to inject dependencies, which allows for optional dependencies and easier re-configuration after object creation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c9f12e8-7266-44a3-bb99-36724c8e33c6', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Discuss the trade-offs between Preact''s lack of ''Concurrent Mode'' and React''s approach.', N'Senior', N'React''s Concurrent Mode allows for interruptible rendering, which keeps the UI responsive during heavy computations but adds significant runtime complexity. Preact opts for simpler, synchronous rendering, which is predictable and efficient for most applications but may require manual optimization for extremely complex data visualizations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abcd2bc6-18f5-4308-94cd-3673eca03b57', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the role of the Program class in ASP.NET Core?', N'Intern', N'The Program class contains the Main method, which serves as the entry point of the application. It is responsible for building and running the host, which sets up the web server and initializes the application environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c055727-1bd8-4ab2-8dd2-367425ca522b', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How do NoSQL databases handle high availability?', N'Intern', N'NoSQL databases achieve high availability by replicating data across multiple servers. If one server goes down, the system can continue to serve requests from other replicas without interruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47a4cac9-9bd4-490d-b65a-3675b639a51b', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the trade-offs of the Go scheduler''s use of work-stealing.', N'Senior', N'Work-stealing allows idle processors to take tasks from the run queues of busy processors, improving load balancing and CPU utilization. The trade-off is increased overhead due to synchronization primitives required to protect queues and the potential for cache locality degradation when tasks move between processor cores.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8750504-842f-4949-b542-36773f142b6b', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB manage data distribution and partitioning across its underlying infrastructure?', N'Senior', N'DynamoDB uses a consistent hashing algorithm to distribute data across physical partitions based on the partition key. It maintains a partition map to route requests efficiently, and when a partition grows beyond a certain size or throughput limit, DynamoDB automatically splits it to maintain performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76c7382d-b10e-47c3-8cac-36781afd875b', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro optimize the loading of images compared to standard HTML image tags?', N'Senior', N'Astro provides an built-in image optimization service that processes images at build time, handling resizing, format conversion, and attribute generation. This reduces the burden on the browser by serving appropriately sized assets and preventing layout shifts through automated dimension attribution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db2e4457-fee7-46be-b8a5-367c4e1d15ff', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the NULL value?', N'Intern', N'A NULL value represents the absence of data or an unknown value in a specific field. It is distinct from zero or an empty string, indicating that no value has been assigned to that record.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a4fba74-b503-43aa-99c1-367cab900744', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the architectural implications of using a hashed shard key compared to a ranged shard key?', N'Senior', N'A hashed shard key ensures an even distribution of data across shards by randomizing the location of documents, which prevents write hotspots. Conversely, a ranged shard key supports efficient range-based queries but is prone to hotspots when data is inserted in monotonically increasing order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6486a1dd-2ae6-46d7-885c-367d2a5e7cff', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the C memory model handle padding and alignment?', N'Middle', N'Compilers add padding bytes between struct members to ensure that each data type starts at an address consistent with the CPU''s memory access requirements for that type. While this improves performance by allowing efficient word-aligned access, it increases the total memory footprint of the structure and can lead to discrepancies in binary compatibility between different platforms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11caa76a-c59f-4b5a-b988-368021e8600e', N'954a0331-deff-4399-b588-96f39fec001d', N'What is Style function?', N'Intern', N'The style function is used to define a set of styles to associate with a given state name. You need to use it along with state() function to set CSS style attributes. For example, in the close state, the button has a height of 100 pixels, an opacity of 0.8, and a background color of green. Note: The style attributes must be in camelCase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8371a7ae-e6a3-4b44-8555-368115d62118', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason about the estimation of ''innovation'' tasks that have no prior equivalent?', N'Senior', N'I break the innovation into a series of iterative experiments or ''spikes'' with strictly defined success criteria and time-boxes. By treating these as research phases rather than production tasks, I can provide a predictable timeline for discovering feasibility without over-committing to a specific final implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9e6a925-8a19-411c-9f06-3681ec3e4183', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Does the lazy function support named exports?', N'Middle', N'No, currently React.lazy function supports default exports only. If you would like to import modules which are named exports, you can create an intermediate module that reexports it as the default. It also ensures that tree shaking keeps working and don’t pull unused components. Let''s take a component file which exports multiple named components, and reexport MoreComponents.js components in an intermediate file IntermediateComponent.js Now you can import the module using lazy function as below,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73194be8-0ca1-4118-bdae-36823f38350c', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are the trade-offs of using Global Guards versus Route-specific Guards?', N'Middle', N'Global guards are easier to maintain for security policies that apply everywhere but can be harder to override for specific endpoints. Route-specific guards provide fine-grained control but can lead to code duplication if the same security logic is needed across many controllers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1c29c92-08c7-4849-af3e-3683dae26058', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are SvelteKit stores used for?', N'Junior', N'Stores are used to manage application-wide state that needs to be accessed by multiple components. They allow for reactive data sharing across the app without having to pass props through every layer of the component tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be28c69c-622e-494b-ab90-36849c782fd5', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is Kotlin and how does it interoperate with Java?', N'Intern', N'Kotlin is a modern, statically typed language. Having been developed by JetBrains, it targets the JVM, among other platforms. Key Strengths of Kotlin on JVM - Concise Syntax: Kotlin''s compact code minimizes boilerplate. - Null Safety: With its nullable types, Kotlin helps reduce null-pointer exceptions. - Extension Functions: These functions simplify class extension. - Coroutines: Kotlin''s lightweight threads make asynchronous operations more manageable. - Immutability: Kotlin has built-in support for immutable structures through ''val''. Core Java-Kotlin Interoperability Mechanisms Kotlin can use Java Frameworks and libraries. Plus, it offers mechanisms for both Java-to-Kotlin and Kotlin-to-Java interoperability. These mechanisms include: 1.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0565a250-d986-4e91-b744-36872f007e52', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the @Value annotation used for?', N'Intern', N'The @Value annotation is used to inject values from property files or environment variables into fields in a Spring bean. It provides an easy way to access externalized configuration settings within your code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6825e6cd-23d0-403b-8ae6-368759876a99', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of CORS in an ASP.NET Core application?', N'Middle', N'CORS is a security mechanism that allows a server to specify which origins are permitted to access resources via browser requests. It prevents unauthorized scripts from other domains from making requests to your API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25564d73-20ba-48ee-a6a1-3689adc94b16', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the architectural significance of Astro''s ''adapter'' pattern?', N'Senior', N'The adapter pattern decouples Astro''s core build engine from the deployment environment, allowing the same codebase to be deployed as static files, Vercel functions, Netlify edge functions, or Node.js servers. This abstraction ensures portability and allows the build system to generate environment-specific artifacts without changing the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e69c56d-42b0-4954-ab12-368f0f1562d2', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the difference between a Controller and a Route?', N'Junior', N'A route acts as the entry point that maps a specific URL to a piece of logic. A controller is a class that organizes related request handling logic, allowing you to group operations for a specific resource rather than cluttering the route files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc89cff7-4c07-4642-afdf-368f848d6d77', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the function of the alt attribute in an image tag?', N'Junior', N'The alt attribute provides alternative text for an image if it fails to load. It is also essential for accessibility, as screen readers read this text to describe the image to visually impaired users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e25e254-a29b-4479-9e34-3691842c4b87', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of ''createMemo'' and how does it differ from a signal?', N'Middle', N'createMemo is used to derive state from other signals while ensuring the calculation only re-runs when its specific dependencies change. Unlike a signal, it is read-only and provides an optimized way to cache computed values, preventing redundant work during rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'367cc6dd-ec76-4370-96e8-36929c145d88', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the primary benefit of the jQuery .data() method?', N'Intern', N'The .data() method allows you to attach arbitrary data to DOM elements without modifying the HTML itself. It keeps the data separate from the presentation and is useful for storing state information during the application lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5324131-18ea-4002-9ab4-3694c43f087e', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What happens to dynamic imports when using Vite?', N'Middle', N'Vite detects dynamic imports and treats them as code-splitting points. During production builds, it automatically extracts the imported module into a separate chunk, which is then loaded asynchronously by the browser when the import statement is executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29099ba5-6384-47ff-9ad6-3695eeb2c49a', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How do you define a route parameter in AdonisJS?', N'Fresher', N'Route parameters are defined using a colon followed by the parameter name in the route string. This allows you to capture dynamic segments from the URL and pass them as arguments to the controller action.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32f72238-1de7-46e1-9524-369c47003340', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Describe the benefit of using Symfony''s ''autowiring'' feature.', N'Middle', N'Autowiring automatically detects and injects dependencies into service constructors by analyzing type-hints. This significantly reduces the amount of boilerplate configuration required in service definition files, making the project easier to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d9905c1-7ac5-4fc4-8b44-369d2009badc', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Describe the lifecycle hooks provided by Alpine.js.', N'Senior', N'Alpine provides hooks such as x-init and the ability to intercept component initialization via Alpine.data. These hooks allow developers to run setup logic, fetch initial data, or clean up resources, providing enough control for most component-level requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30f07457-7a7e-4e32-abac-369d97bd456c', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How can you pass data between middleware and handlers in Echo?', N'Junior', N'You can use the Set and Get methods on the Echo Context to store and retrieve data. This acts as a key-value store for the duration of a single request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5dde74ad-c404-4274-88a4-369e4d2dc3cb', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt handle auto-imports?', N'Junior', N'Nuxt automatically imports Vue APIs, components, and composables from specific directories. This removes the need to manually write import statements for common functions, keeping your code cleaner.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82fd8340-7ae9-44cf-9615-36a0644a60b6', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does ''Conflict-free Replicated Data Types'' (CRDTs) handle concurrent updates without locks?', N'Senior', N'CRDTs are data structures designed so that concurrent updates on different replicas can always be merged without conflicts. By ensuring operations are commutative and associative, the system guarantees that all replicas will eventually converge to the same state regardless of the order in which updates were applied.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e9ed4ac-4d86-4273-af46-36a2d56b3bbd', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What does the dependency array of useEffect affect?', N'Intern', N'The dependency array of useEffect determines when the effect should re-run. If the array is empty, the effect runs only once after the initial render. If it contains variables, the effect runs whenever any of those variables change. If omitted, the effect runs after every render. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ea80310-d094-439c-972c-36a3eee9b83c', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte optimize build sizes?', N'Junior', N'Because Svelte is a compiler, it only includes the code necessary for your specific application features. It removes unused CSS and logic, resulting in a smaller bundle size compared to frameworks that ship a virtual DOM library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acbf8c86-3ef1-4fc5-8f86-36a584d8e3b9', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is Babel and how does transpilation work?', N'Intern', N'Babel is a JavaScript transpiler (source-to-source compiler) that converts modern JavaScript (ES6+) into a backwards-compatible version for older browsers or environments that don''t support the latest syntax. How it works: 1. Parse — Source code is parsed into an AST (Abstract Syntax Tree). 2. Transform — Plugins traverse and modify the AST (e.g. convert arrow functions to regular functions). 3. Generate — The modified AST is printed back to JavaScript source code. Installation: babel.config.json: Example transformation: Polyfills vs. transpilation: * Transpilation handles *syntax* (arrow functions, destructuring, classes). * Polyfills (core-js, regenerator-runtime) handle missing *runtime APIs* (Promise, Array.from, generators).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e54e770-a689-494f-a106-36a59ae89075', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is meant by ''serialization'' in Fastify?', N'Intern', N'Serialization is the process of converting JavaScript objects into a string format, such as JSON, to be sent over the network. Fastify uses a high-performance library to perform this serialization based on the provided JSON schema, which is much faster than the default native JSON.stringify method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c5ee8a1-0e74-4291-9409-36a6a38c25b5', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Explain the concept of ''Managed State'' in Rocket.', N'Junior', N'Managed State allows you to store data, such as database connection pools or configuration settings, that persists across the application lifetime. You register this state during application startup and inject it into request handlers as needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc598d71-b3a9-4938-ba00-36a8e12c8f55', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you estimate the bandwidth required for a new video streaming service?', N'Fresher', N'I would estimate the average bitrate of the video content and the expected number of concurrent users. Multiplying these two values would give me a baseline estimate for the required bandwidth during peak usage hours.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'193b11da-2e6b-4695-90e8-36a985c5d0f9', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How do you handle secrets in a production environment?', N'Middle', N'Secrets such as API keys and database credentials should never be hard-coded or stored in version control. Instead, they should be managed using dedicated secret management services or environment variables injected at runtime, ensuring they are encrypted at rest and in transit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd09baf4-124e-44cf-8a25-36aad3de8044', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of double exclamation', N'Intern', N'The double exclamation or negation(!!) ensures the resulting type is a boolean. If it was falsey (e.g. 0, null, undefined, etc.), it will be false, otherwise, it will be true. For example, you can test IE version using this expression as below, If you don''t use this expression then it returns the original value. Note: The expression !! is not an operator, but it is just twice of ! operator.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82c1dc36-0cb9-444a-a59e-36aaf152dccd', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a user interface, why is consistency important?', N'Fresher', N'Consistency reduces the cognitive load on the user by allowing them to predict how the application behaves based on past interactions. It creates a professional look and feel, ensuring that the user does not have to relearn how to navigate the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0802ff46-feff-4998-b41a-36ab6ddcac99', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How do you provide default values for path or query parameters?', N'Junior', N'You provide default values by assigning them in the function signature, just like in standard Python. FastAPI will treat the parameter as optional if a default is provided, or as required if no default is assigned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0aee5039-076f-4a65-bd37-36abaa9fb74d', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt’s auto-import system affect tree-shaking and bundle size?', N'Senior', N'Nuxt’s auto-importing relies on unimport to detect usage during build-time. While it improves developer experience, it can occasionally lead to larger bundles if unused composables are accidentally referenced, requiring explicit configuration to prune the dependency graph.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1c74d17-f42c-4b34-b540-36ac5ccf354a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you explain the difference between a GET and a POST request to a non-technical stakeholder?', N'Fresher', N'A GET request is like asking to view a page or fetch information from a library, where you do not change anything. A POST request is like submitting a form or sending a letter, where you are providing new information that the system needs to process and save.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f1861dd-be24-4482-99c0-36ad269cd45b', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Why would you use the Symfony Console component?', N'Junior', N'The Console component is used to create CLI commands for your application, such as database migrations, clearing caches, or running background tasks. It allows you to automate repetitive administrative duties outside of the web server environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8a0221b-effe-4f2e-86b0-36b00125e696', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What architectural patterns help in maintaining API consistency across a distributed microservices environment?', N'Senior', N'Consistency is managed through shared API contracts using schemas like Protocol Buffers or OpenAPI, enforced by an API Gateway or Service Mesh. Centralized schema registries ensure that all services evolve their interfaces compatibly, often utilizing consumer-driven contract testing to prevent breaking changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92644b19-76c2-4ecc-a792-36b07779c5e5', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are the performance implications of using Phoenix LiveView versus a traditional SPA?', N'Middle', N'LiveView reduces the need for complex client-side state management by moving the application logic to the server. While this significantly reduces the amount of JavaScript and API complexity, it increases the memory footprint on the server because each user session maintains a long-lived process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4021d9ec-a7e5-43c4-9ddd-36b405cb051f', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Why is it dangerous to perform long-running blocking tasks inside a Django view, and how should these be handled?', N'Senior', N'Blocking tasks consume worker processes, leading to thread starvation and increased latency for other users in synchronous environments. Long-running tasks should be offloaded to a distributed task queue like Celery to ensure the web worker remains responsive and available for incoming requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
