INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9322077b-b8ed-44c6-8222-36b8043ec262', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik optimize the Main Thread during initial page load?', N'Senior', N'Qwik minimizes Main Thread blocking by shipping nearly zero JavaScript initially. Since the page is resumable and not hydrated, the browser does not need to execute framework-specific initialization logic, keeping the CPU free for critical rendering and user input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
