INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'852874a2-795c-4976-a695-36e38d877c75', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the role of the ''ast'' module in Python''s meta-programming capabilities?', N'Senior', N'The ast module allows developers to parse Python source code into an Abstract Syntax Tree, which can be inspected, modified, and even recompiled. This is a powerful tool for building static analysis tools, custom linters, or code transformation utilities. It provides deep access to the language''s structure without needing to execute the code itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b287699-929e-4001-8152-36e4549ee9f0', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind help with CSS bundle sizes?', N'Intern', N'Tailwind uses a process called tree-shaking to remove all unused CSS from your final production build. By scanning your project files, it ensures that only the utilities you actually used in your HTML are included in the final stylesheet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc9f456f-68dd-41fa-ae96-36e508482f62', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the benefit of Static Site Generation (SSG) in SvelteKit?', N'Fresher', N'SSG generates the HTML files for your application at build time rather than at request time. This results in extremely fast load speeds and makes the site easy to host on simple static file servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e61ffa72-2796-438c-a928-36e863567921', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Should all state be kept in Redux?', N'Intern', N'No, not all state needs to be in Redux. It is generally best to keep truly global state in Redux, while local UI state, such as form inputs or whether a dropdown is open, is better managed within the component itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df4f5cbb-236a-456e-96eb-36f20f95a2c7', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does the DynamoDB replication factor impact durability and availability?', N'Senior', N'DynamoDB typically maintains three replicas across multiple availability zones to ensure high durability and data availability. This replication ensures that even if an entire availability zone fails, data remains accessible and consistent. The architecture prioritizes high availability and partition tolerance over strict, global synchronous consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a1c8b5c-8675-465c-b141-36f3223998fc', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the difference between class methods and instance methods?', N'Fresher', N'Instance methods are called on an object created from a class and have access to instance variables. Class methods are called directly on the class itself and are typically used for utility functions that don''t depend on a specific instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'deb7b529-e375-4ac4-82cd-36f6d378a941', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Compare the performance overhead of using Web Workers versus offloading computation to the main thread.', N'Senior', N'Web Workers allow background execution of scripts, preventing the main thread from blocking, which is essential for maintaining a smooth UI during CPU-intensive tasks. The trade-off is the overhead of structured cloning of data passed between threads, which can become a bottleneck if large data sets are synchronized frequently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6e21eca-0aaf-466c-9bac-36fa2f53d200', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How would you approach a trade-off involving system security versus user convenience?', N'Intern', N'Security and convenience are often inversely related, so I would aim for a balance that protects sensitive data without creating unnecessary friction for the user. I would prioritize security for critical functions while streamlining the user experience elsewhere.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'763cfb60-a767-42ec-bf1e-36fae9334ea1', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you evaluate if a system requires a search engine like Elasticsearch versus standard database indexing?', N'Middle', N'I use a search engine when the application requires advanced features like full-text search, fuzzy matching, or multi-faceted filtering. Standard database indexing is sufficient for exact matches and simple range queries, avoiding the complexity of maintaining a secondary search index.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9300081-6d83-427a-ad09-36fb4ab27653', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo approach testing HTTP handlers?', N'Middle', N'Echo makes testing straightforward by allowing developers to instantiate the Echo context manually with a mock request and response recorder. This isolates the handler logic from the network layer, enabling fast unit tests that verify response status codes and payloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'212f69ab-9aa3-400c-b43f-36fee79e970a', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is data modeling in Cassandra considered query-driven?', N'Middle', N'Unlike normalized relational databases, Cassandra requires you to model data based on the specific queries you intend to run. Since joins are not supported, denormalization is necessary to ensure that data retrieval can be satisfied by a single partition lookup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9030098d-b803-4bb0-b759-37059767dcdc', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What are ''coordinating nodes'' and why are they used?', N'Middle', N'Coordinating nodes act as smart load balancers that receive client requests, broadcast them to the relevant data nodes, and gather the results. By dedicating specific nodes as coordinators, you can offload the processing burden from data-heavy nodes, improving cluster stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
