INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2fca700-a344-450d-82f5-370b7cfc56f8', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is ''Optimistic UI'' in Remix?', N'Fresher', N'Optimistic UI is a pattern where the app updates the interface immediately after a user performs an action, assuming the server request will succeed. Remix provides hooks to easily implement this behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'383e540e-789f-447f-a831-370e08e9f43c', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the significance of the Finalizer and why is it generally discouraged in favor of Cleaners?', N'Senior', N'Finalizers are problematic because they introduce non-deterministic object destruction and can keep objects alive long after they are no longer needed, leading to memory bloat. Cleaners provide a more controlled, explicit mechanism for resource management, reducing the risk of GC pressure and potential deadlocks associated with the finalizer thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78be7f51-35b3-4b18-a344-371199768476', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What are the architectural implications of using a distributed broker versus an embedded message queue?', N'Senior', N'A distributed broker provides fault tolerance and scalability by decoupling producers and consumers through a central cluster, though it introduces network overhead and operational complexity. An embedded queue reduces latency and eliminates network hops, but risks data loss if the host process fails and limits the system''s ability to scale independently of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
