INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf27dcd3-dbfd-4952-9488-3729fa6c07c5', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What happens if you don''t use a bundler like Webpack?', N'Fresher', N'Without a bundler, you would have to manually manage all your script tags in HTML, deal with global namespace pollution, and manage the order of file dependencies. This becomes difficult to maintain as the application grows in complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4eaf4cd-2589-4e30-8214-372c2e3f138b', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the primary architectural difference between TypeScript''s ''type'' aliases and ''interface'' declarations?', N'Senior', N'Interfaces are always open, allowing for declaration merging, and are generally more performant for the compiler to resolve in large projects. Type aliases are closed, support advanced features like union and intersection types, but cannot be merged or used to create polymorphic ''this'' types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbb02850-bdff-4ecf-b82e-372d0b62d2d6', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle server-side data loading to prevent waterfall requests?', N'Senior', N'SvelteKit employs parallelized data fetching by allowing multiple load functions to execute simultaneously on the server. By utilizing the platform''s ability to stream responses, it avoids the sequential bottleneck common in traditional architectures where one request must complete before the next begins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1787dab8-06d4-4257-8259-372deeec686d', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Describe the implications of return value optimization (RVO) and named RVO.', N'Senior', N'RVO allows the compiler to construct an object directly in the memory location of the caller''s target variable, effectively eliminating unnecessary copy or move operations. This optimization is permitted even if the copy constructor has side effects, and it is a critical optimization for returning heavy objects from functions without performance penalties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
