INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31e1def3-b0e6-4628-bad2-3731de691a9c', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If a service is failing under heavy load, how do you decide whether to scale up or scale out?', N'Middle', N'Scaling up is preferred if the application is resource-bound by a single instance and the cost of vertical hardware increases is acceptable. Scaling out is the better long-term choice for fault tolerance and to handle unpredictable traffic spikes by distributing the load across multiple instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff756460-1f0c-4dff-ad80-3736116f13cf', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the benefit of Preact''s small size for mobile users?', N'Intern', N'The small size means less JavaScript for the browser to download, parse, and execute. This results in faster time-to-interactive metrics, which is crucial for users on slower mobile networks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24221f80-bc7a-4622-b335-373940824ef7', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What does the ''Group'' feature in Echo provide?', N'Intern', N'The Group feature allows developers to organize routes that share a common path prefix or set of middleware. This helps in keeping the code modular and makes it easier to manage large APIs by applying specific configurations to a subset of routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa30163f-7f3f-4098-b98c-373a19bf1a0b', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Does Qwik require a specific server-side rendering strategy?', N'Fresher', N'Qwik is designed to be SSR-first, meaning it generates the initial HTML on the server. Because the state is serialized into this HTML, the transition from server to client is seamless and does not require complex state synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf40015a-e755-442d-be23-373c6e9b7140', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it important to document the solution after fixing a bug?', N'Junior', N'Documenting the solution helps the team understand the root cause and the fix, which prevents the same or similar bugs from being handled inefficiently in the future. It serves as a knowledge base that helps new team members learn the system''s common pitfalls and patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9f1f1db-fb2e-47b7-8f30-373d1ef3d75c', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of the @Value annotation?', N'Fresher', N'The @Value annotation is used to inject configuration values from property files or environment variables directly into class fields. This allows developers to externalize settings like database URLs or API keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f91ff93a-de64-41d9-8ad3-37435de3e2e6', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a situation where a service is crashing due to an unhandled exception triggered by bad user input?', N'Middle', N'I would implement robust input validation at the entry points of the service and ensure there are global exception handlers to prevent the process from crashing. I would also log the malformed input that caused the crash to identify the source and add a permanent fix to reject such requests gracefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64e15161-e3cd-475b-84a1-37442e14e5ed', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of the ''Registry'' in Phoenix?', N'Middle', N'The Registry allows you to dynamically register and locate processes by a unique key. It is highly efficient for lookup operations in distributed systems, making it easier to manage and address dynamic processes like user sessions or room participants.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7633b7b8-acb2-404b-b8f4-3745147d1042', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does CSS Grid differ from Flexbox?', N'Junior', N'Flexbox is primarily designed for one-dimensional layouts, either as a row or a column. CSS Grid is a two-dimensional layout system that allows for managing both rows and columns simultaneously, making it better for complex page structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0637df3e-57ad-4369-9bc2-374586a41d08', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are the two modes of compilation in Dart?', N'Fresher', N'The two modes are Just-In-Time (JIT) and Ahead-Of-Time (AOT). JIT compiles code during execution, which is great for fast development cycles, while AOT compiles code to native machine code before execution for better performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a74d6cf-6f98-4eb6-a0ce-3745a15a5cc2', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle asynchronous operations compared to traditional callback-based frameworks?', N'Junior', N'Fastify is built with native support for Promises and async/await syntax. This ensures that asynchronous operations are handled cleanly and errors are properly caught by the internal error handling mechanism without requiring manual callback management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'276fc814-95f7-4b12-a49d-374671f51032', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the risks of ''undefined behavior'' in C++ and how do compilers exploit it?', N'Senior', N'Undefined behavior allows the compiler to make assumptions that the programmer will never trigger certain states, enabling aggressive optimizations such as reordering instructions or eliding code paths. If the programmer violates these assumptions, the generated machine code may produce unpredictable results, security vulnerabilities, or program crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa1fc55f-40bf-4121-b298-3747e2a0145b', N'4c000000-0000-0000-0000-000000000005', N'How do you handle system monitoring and logging in distributed systems?', N'Middle', N'Distributed systems require centralized logging and telemetry to aggregate data from multiple nodes into one view. You should track metrics like latency, error rates, and throughput to gain observability into system health and identify bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
