INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b19b4032-c7df-41c6-9d92-374c6cbe2aab', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'When should you use the JSONB data type instead of JSON?', N'Middle', N'JSONB stores data in a decomposed binary format, which is slightly slower to insert but significantly faster to process and query. It also supports indexing, making it the preferred choice for applications that need to filter or search within JSON documents.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
