INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b1da48d-c5bc-40cf-8abd-3750ba6e3ec9', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the primary concern when using Express for serving static files in high-traffic production environments?', N'Senior', N'Express is not optimized for high-performance static file serving compared to dedicated reverse proxies like Nginx. Serving files directly through Node.js consumes CPU cycles and memory that should be reserved for application logic, and it bypasses the caching optimizations provided by edge servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2476859-ff39-4b10-b76c-375477cb4827', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Why is ''Idempotency'' important for microservice communication?', N'Middle', N'In distributed systems, network retries are common, and requests may be delivered multiple times. Idempotency ensures that performing the same operation multiple times does not change the result beyond the initial successful execution, preventing data corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d620fa0-8425-47d9-ad03-3754d29064c1', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the difference between ''shallowRef'' and ''ref''?', N'Middle', N'ref creates a deeply reactive object, meaning changes to nested properties trigger updates. shallowRef only tracks the reactivity of the value itself, meaning changes to nested properties do not trigger updates, which can be a performance optimization for large data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
