INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42d399c8-5434-4d7b-a63d-3768646c182d', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the benefit of the Next.js Image component?', N'Intern', N'The Image component is designed to optimize images automatically for the web. It handles tasks such as resizing, lazy loading, and serving modern formats, which significantly improves page performance and user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'883fd290-fc6d-4296-99f0-376b03c41b1c', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the difference between active-passive and active-active database replication?', N'Middle', N'Active-passive uses one primary node for writes while replicas stay in standby, simplifying consistency but limiting write capacity. Active-active allows writes across multiple nodes, which increases throughput but introduces complex conflict resolution and synchronization requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbd5a3bd-2b41-4538-b418-376b62efee40', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI achieve high performance?', N'Fresher', N'FastAPI is built on top of Starlette for web parts and Pydantic for data parts. It leverages asynchronous programming using Python''s async and await syntax, which allows it to handle many concurrent connections efficiently without blocking the event loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac95d3a2-413b-4bf4-9023-376c6065a76a', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are Action Filters and when would you use them?', N'Middle', N'Action filters are attributes that allow you to run code before or after specific controller actions. They are ideal for cross-cutting concerns like logging, input validation, or modifying the response before it is returned to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bbbb261-c19a-4eaa-b314-376c96cfda4d', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What are the limitations of jQuery in terms of tree-shaking?', N'Middle', N'jQuery is typically distributed as a single monolithic file, making it impossible for modern bundlers to remove unused code. This forces the browser to download and parse the entire library even if only a few specific features are being utilized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6713bdc6-4603-4512-9b36-376d444dfa16', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is Mutiny and why is it used in Quarkus?', N'Middle', N'Mutiny is an event-driven, reactive programming library used in Quarkus to handle asynchronous streams. It simplifies the complexity of reactive streams by providing a clear, intuitive API for managing data pipelines and handling backpressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03628892-6593-422f-be06-376dce98b117', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is it recommended to avoid using high-cardinality data in clustering columns?', N'Middle', N'Clustering columns define the physical ordering of data on disk within a partition. While they are useful for sorting, having an extremely high number of unique clustering values can lead to large, difficult-to-manage partitions that impact performance during compaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b10303f2-0b82-4bdd-af4c-376eee106204', N'a2838158-7305-480a-b22b-4dc35776b400', N'Explain the role of the Raft consensus algorithm in maintaining a replicated state machine.', N'Senior', N'Raft ensures that a cluster of nodes agrees on a sequence of state transitions by electing a leader who manages log replication. By requiring a majority quorum for every log entry, the system guarantees safety and fault tolerance, allowing it to remain operational even if a minority of nodes fail.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0719611d-a3c1-4ead-9bd3-37715f17e1ce', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Does Cassandra support ACID transactions?', N'Intern', N'Cassandra does not support full ACID transactions in the same way as relational databases. It provides atomicity and isolation at the partition level, but it does not support cross-partition transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd054c3cd-b350-4b89-8231-37733e108208', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the primary goal of the Qwik framework?', N'Intern', N'Qwik aims to provide instant page loading by delivering minimal JavaScript to the browser. It achieves this by focusing on resumability, which allows the application to become interactive without needing to download and execute the entire framework bundle upfront.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e823542-7f82-4e0b-b043-37738b0396d1', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Explain the concept of ''Cache Penetration'' and how to mitigate it in Redis.', N'Middle', N'Cache penetration occurs when requests repeatedly query for non-existent keys that are not in the cache or the database. It can be mitigated by caching empty results for short periods or using a Bloom filter to check if a key exists before querying the primary database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb0d36f6-4ad9-4973-bde6-3773e4884852', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What factors influence the decision to use a message queue versus a synchronous API call for inter-service communication?', N'Middle', N'Synchronous calls are easier to implement and provide immediate feedback but create tight coupling and potential cascading failures. Message queues introduce asynchronous decoupling, improving system resilience and handling traffic spikes through buffering, though they increase architectural complexity and eventual consistency challenges.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
