INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'150eb78d-a9ae-4a0c-aa93-3779b8caabd6', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Explain the significance of the LSM-tree (Log-Structured Merge-tree) in modern database engines.', N'Senior', N'LSM-trees are optimized for high-write throughput by turning random writes into sequential writes in memory, which are later flushed to disk in sorted runs. This architecture is far superior to B-trees for write-heavy workloads, though it makes read performance dependent on compaction processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0a8fb30-72d6-428f-96fa-3779eec5ba0d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is same-origin policy?', N'Intern', N'The same-origin policy is a policy that prevents JavaScript from making requests across domain boundaries. An origin is defined as a combination of URI scheme, hostname, and port number. If you enable this policy then it prevents a malicious script on one page from obtaining access to sensitive data on another web page using Document Object Model(DOM).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5404fe72-16b5-49c2-9051-377a4f2fdd38', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB handle conflict resolution in multi-region deployments?', N'Middle', N'DynamoDB Global Tables use a ''last writer wins'' conflict resolution strategy. When the same item is updated in two different regions simultaneously, the system resolves the conflict based on the timestamp of the write, ensuring eventual consistency across all regions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b74d0cd-eb42-4c12-963e-377c50bb2b84', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is hoisting?', N'Junior', N'Hoisting is the behavior where variable and function declarations are moved to the top of their containing scope during the compilation phase. While function declarations are fully hoisted, variables declared with ''let'' or ''const'' are hoisted but remain in a temporal dead zone until the code reaches their definition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e47216d1-2a4e-4f99-bd1c-377e6b94849b', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you handle API versioning strategy for a public-facing system to minimize breaking changes?', N'Senior', N'The most robust strategy is URI versioning or header-based versioning combined with a deprecation policy. By maintaining parallel major versions, you allow clients to migrate at their own pace while deprecating older endpoints with clear sunset headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe649bef-1ec9-4ade-83c4-377ebde671f9', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Your service is experiencing high latency due to database connection exhaustion. How would you approach diagnosing and resolving this?', N'Middle', N'I would first analyze connection pool metrics to see if connections are being leaked or if the pool size is insufficient for the concurrency level. I would implement circuit breakers to prevent cascading failures and consider introducing a caching layer or read replicas to reduce the direct load on the primary database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79c42729-19de-4578-8e05-378112815ea8', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is an action function in Remix?', N'Intern', N'An action function is a server-side function that handles data mutations, such as form submissions. It processes the incoming request and modifies data, such as updating a database, before triggering a page refresh.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfaf5c94-bcde-44ce-9f68-3782920b3514', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle database transaction integrity across multiple repository operations?', N'Senior', N'AdonisJS provides a transaction manager that allows wrapping multiple operations into a single unit of work by passing a transaction object through repositories. This ensures atomicity and consistency, preventing partial data updates if any step in a multi-stage operation fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd387f82-a618-43f0-bf0f-3783447dccb3', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Explain the difference between vertical scaling and horizontal scaling in the context of stateful database systems.', N'Senior', N'Vertical scaling (scaling up) involves increasing the resources of a single node, which is simpler but limited by hardware capacity and cost. Horizontal scaling (scaling out) involves adding more nodes, which provides theoretically infinite capacity but requires complex data partitioning, cluster management, and distributed transaction handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64b4b3d7-a792-44f4-ae9d-378384a34f9a', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a ''keyword'' field type used for?', N'Junior', N'The keyword field type is used for exact matching, sorting, and aggregations. Unlike text fields, keyword fields are not analyzed, meaning the entire string is stored as a single term.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90f7b472-b064-439a-aacb-37856747f056', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you diagnose a scenario where a distributed cache is frequently invalidating prematurely, causing database stress?', N'Senior', N'I investigate the cache eviction policy and TTL settings to see if they are configured aggressively relative to the workload. I also look for ''thundering herd'' patterns where cache misses trigger simultaneous expensive recomputations that overwhelm the underlying database, potentially requiring request collapsing or distributed locking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fee2b37-b3b0-40e9-8e3a-3789c66a772d', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain how the ''Outbox Pattern'' solves the dual-write problem.', N'Senior', N'The outbox pattern ensures that a database update and the corresponding event publication occur atomically by writing the event to a local table within the same transaction. A separate relay process then polls this table to publish the event to the message broker, guaranteeing at-least-once delivery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37369b7b-d216-4fbe-a0b5-378e008fce83', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If an application works in development but fails in production, what is the first thing you check?', N'Fresher', N'I would check for environmental differences, such as different configuration settings, missing environment variables, or discrepancies in software versions. I would also examine production logs to identify specific errors that might not have appeared in the development environment. Finally, I would verify if the production database has the same schema and permissions as the development database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94f323da-c2d0-4cbb-9b4a-37907de98904', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'In data storage, what is the trade-off between row-oriented and column-oriented databases?', N'Junior', N'Row-oriented databases are optimized for transactional processing where individual records are read or written frequently. Column-oriented databases are superior for analytical queries that aggregate large volumes of data across specific fields, though they are generally slower for individual record insertions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f27bc7b-44a7-4704-beee-379421ad679f', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is Scala and why is it important for machine learning?', N'Senior', N'Scala, short for Scalable Language, is a robust, highly versatile programming language that runs on the Java Virtual Machine (JVM). It combines functional and object-oriented paradigms, offering features beneficial for machine learning. Key Scala Features for Machine Learning Static Typing Scala''s static typing ensures type safety, allowing for more robust and efficient code. For Machine Learning, this can help catch errors early in the development cycle. Functional and Object-Oriented Paradigms - Functional Features: Support for higher-order functions, immutability, and pattern matching. - OOP Features: Encapsulation and inheritance. Conciseness and Readability Scala''s expressive syntax is concise, making it easier to write and understand complex ML algorithms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'959868ac-dcf7-4a2a-a125-379470d6bb7e', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a B-tree index and a GIN index?', N'Middle', N'B-tree indexes are the default and are optimized for equality and range queries on scalar data types. GIN, or Generalized Inverted Indexes, are designed for data types containing multiple elements, such as arrays or JSONB, allowing for efficient searching within the internal contents of those structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acab00e0-5a8b-4068-a9bb-379734b28509', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What does ''nested routing'' mean in Ember?', N'Intern', N'Nested routing allows you to define a hierarchy of routes where child routes are rendered within parent route templates. This helps manage complex layouts where parts of the page remain constant while others change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2eb87f29-2199-40c3-9396-3798bdf612ec', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs in choosing between a multi-tenant and single-tenant architecture for a SaaS platform?', N'Middle', N'Multi-tenant architectures offer significant cost savings and easier management by sharing infrastructure across customers, but they pose risks regarding data isolation and ''noisy neighbor'' performance issues. Single-tenant architectures provide total isolation and customization, but they are significantly more expensive and harder to scale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78834fbf-6a6d-4d01-8d42-379a2fa77989', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Explain the concept of ''Broker-side'' vs ''Client-side'' filtering.', N'Senior', N'Broker-side filtering reduces network traffic by offloading the routing logic to the message broker, but increases the broker''s CPU load and limits the complexity of filtering rules. Client-side filtering provides greater flexibility and allows consumers to handle logic, but increases network bandwidth usage as consumers must receive and discard irrelevant messages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59f2ef9a-430a-49ed-9b9a-379a77424c92', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between ''Array'' and ''ArrayList''?', N'Fresher', N'An array has a fixed size and is strongly typed, making it faster and safer. An ArrayList is a dynamic collection that can store elements of different types, which can lead to performance overhead due to boxing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'827c6e21-5d2a-4bfb-846c-379c2123781a', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is a regression, and why is it important in the context of debugging?', N'Intern', N'A regression is when a previously working feature breaks due to a recent change or fix. It is important because it highlights that a debugging attempt might have inadvertently damaged another part of the system, requiring careful testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c9835bf-7604-4788-9f72-379faa94b11a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you check whether an object can be extendable or not?', N'Fresher', N'The Object.isExtensible() method is used to determine if an object is extensible or not. i.e, Whether it can have new properties added to it or not. *Note: By default, all the objects are extendable. i.e, The new properties can added or modified.* &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c61de09-6a4a-4b22-bd80-379fb224993a', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Can you use Hono with databases?', N'Junior', N'Yes, Hono does not dictate which database you use; it remains compatible with any database client that works within the runtime you have chosen. Developers can use ORMs, query builders, or native drivers to interact with databases from within Hono handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58be2e90-6850-4ffe-8ac4-37a2eae9ba02', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between an enum and a union type in TypeScript?', N'Middle', N'Enums create a distinct type that is essentially a mapping of names to values, often resulting in runtime code generation. Union types are a lightweight way to define a set of allowed values and are strictly a compile-time feature that disappears during transpilation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85d8eec8-1465-4d74-b94e-37a302dd62b1', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you handle the trade-off between adding new features and technical debt reduction?', N'Middle', N'I use a balanced approach by allocating a fixed percentage of each development sprint to technical debt. I prioritize refactoring tasks that block upcoming features or currently cause the most production incidents to ensure the long-term maintainability of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf23b733-dded-4033-89c8-37a41283fdaa', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is Incremental Static Regeneration (ISR) and when should you use it?', N'Middle', N'ISR allows you to update static pages after you have built your site without needing to rebuild the entire application. It is best used for content that changes periodically, allowing the server to regenerate pages in the background as requests come in.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e19aca00-b02e-47c0-af80-37a47f5a9749', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are Phoenix Templates?', N'Intern', N'Templates are files that define the structure and layout of the HTML response sent to the user. They contain static content mixed with dynamic data passed from the view layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48ee2c59-0261-4aa2-8cac-37a4fd255d2b', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Why is it discouraged to perform blocking I/O operations directly within a Gin handler?', N'Senior', N'Gin handlers run in the context of the request goroutine; blocking I/O operations will tie up that goroutine, potentially exhausting the server''s thread pool and increasing latency. For long-running tasks, it is better to offload the work to a worker pool or a background queue to keep the request path responsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'622dfa61-6898-4bbf-ae38-37a5e79e49dd', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Does Gin support multipart/form-data for file uploads?', N'Fresher', N'Yes, Gin provides convenient methods to handle file uploads. It allows you to access individual files sent in a multipart request and save them to the server''s local storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9683862-5027-4011-b7fe-37a620b81cde', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the purpose of an idempotent consumer in a distributed message queue?', N'Senior', N'An idempotent consumer ensures that processing the same message multiple times has the same effect as processing it once. This is critical in distributed systems where ''at-least-once'' delivery is common, as it prevents duplicate side effects when retries occur due to network failures or crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8af3379-9681-4b4c-89e2-37a7534dbd75', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is Type Aliasing?', N'Fresher', N'Type aliasing defines an alternative name for an existing type using the ''typealias'' keyword. It is useful for making complex types more readable or for providing context to a generic type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81648fba-c11d-48ce-ad37-37a77936c42f', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why fragments are better than container divs?', N'Fresher', N'Below are the list of reasons to prefer fragments over container DOM elements, 1. Fragments are a bit faster and use less memory by not creating an extra DOM node. This only has a real benefit on very large and deep trees. 2. Some CSS mechanisms like _Flexbox_ and _CSS Grid_ have a special parent-child relationships, and adding divs in the middle makes it hard to keep the desired layout. 3. The DOM Inspector is less cluttered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f4c5ea8-04d1-42e0-bc27-37a8e024e6e8', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is an index in a database and how does it affect performance?', N'Junior', N'An index is a data structure that allows the database to find rows more quickly without scanning the entire table. While indexes significantly speed up read operations, they can slow down write operations because the index must be updated whenever data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01d96813-65b4-47fa-a4ca-37aa188840f4', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the purpose of the x-cloak directive?', N'Intern', N'The x-cloak attribute is used to prevent the ''flash of unstyled content'' that can occur before Alpine initializes. It is typically combined with CSS to hide an element until Alpine is ready and removes the attribute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98da3ae3-c381-46da-84da-37ad7489b032', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Why is Astro often preferred over frameworks like Next.js for content-heavy marketing sites?', N'Senior', N'Astro is explicitly designed for content-focused performance, avoiding the ''JavaScript tax'' imposed by the hydration of entire page shells. Its ability to ship pure HTML for static content makes it significantly more efficient for SEO and page load speed compared to framework-heavy approaches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'109e8f31-324f-4872-a29a-37ade563de59', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is useEffect hook? How to fetch data with React Hooks?', N'Fresher', N'The useEffect hook is a React Hook that lets you perform side effects in function components. Side effects are operations that interact with the outside world or system and aren''t directly related to rendering UI — such as fetching data, setting up subscriptions, timers, manually manipulating the DOM, etc. In function components, useEffect replaces the class component lifecycle methods(componentDidMount, componentDidUpdate and componentWillUnmount) with a single, unified API. Syntax This effect hook can be used to fetch data from an API and to set the data in the local state of the component with the useState hook’s update function. Here is an example of fetching a list of ReactJS articles from an API using fetch. A popular way to simplify this is by using the library axios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'777d41ba-d7a7-400d-9a0a-37ae4655be6e', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are Active Record validations and why are they important?', N'Junior', N'Active Record validations are rules defined in your models that ensure only valid data is saved to the database. They help maintain data integrity by checking attributes like presence, uniqueness, or format before a record is committed. By using these built-in validations, you prevent invalid or corrupted data from entering your system at the application level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cf85648-a83d-4711-8306-37b1849c9649', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the difference between ''lateinit'' and ''lazy'' initialization?', N'Middle', N'''lateinit'' is used for non-nullable mutable properties that will be initialized later, typically in a lifecycle method. ''lazy'' is used for immutable properties where the value is computed only upon the first access, providing an efficient way to defer initialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eee93918-e75e-4bbc-a515-37b60cdbe6e1', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is ''app.listen'' used for?', N'Intern', N'app.listen is a method that starts the Express server and tells it to listen for incoming connections on a specified port. It is the entry point that binds the application to a network port and starts accepting requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cf357fb-7361-4939-9d9c-37ba31cf7a6f', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Describe the internal structure of a Python dictionary and explain how it achieves average O(1) time complexity.', N'Senior', N'Python dictionaries are implemented as hash tables that use open addressing with perturbation to handle collisions. In recent versions, they are also ordered by insertion, which is achieved by maintaining a separate list of indices. This structure provides high-speed lookup, insertion, and deletion while maintaining memory efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd828e0a7-ebdf-4693-a46c-37ba758dc5ba', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does the AdonisJS ''Body Parser'' handle security risks like mass assignment?', N'Senior', N'The body parser works in tandem with the validator to enforce strict input schemas, preventing clients from injecting unauthorized database fields. By explicitly defining which fields are allowed via validation rules, the framework mitigates mass assignment attacks where malicious actors try to modify protected attributes like user roles or account balances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'085c112d-bd7d-4041-af7b-37c0c38eb08a', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the role of the ''GlobalAlloc'' trait in Rust''s memory management?', N'Senior', N'The GlobalAlloc trait defines the interface for the global memory allocator, allowing developers to replace the default allocator with custom implementations. This is crucial for embedded systems or high-performance applications that require specialized memory management strategies, such as arena allocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e0272cb-8a38-48ec-80a0-37c1c6a6c671', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does message partitioning (or sharding) in a system like Kafka improve performance?', N'Middle', N'Partitioning allows a single topic to be split across multiple brokers, enabling parallel processing by multiple consumers. This horizontal scaling ensures that high-volume data streams can be distributed across a cluster, effectively increasing the overall throughput and balancing the load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'483ba2ac-901c-4c98-bc05-37c3aadf4eea', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between shallow and deep cloning in PHP?', N'Middle', N'A shallow clone copies the object''s properties as-is, meaning nested objects are still shared between the original and the clone. A deep clone involves manually cloning nested objects within the magic __clone method to ensure that the new object is completely independent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c979fcc-b5ff-4f21-82d3-37c605c89af5', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a ''quorum'' in the context of read and write operations?', N'Middle', N'A quorum is the minimum number of nodes that must agree on a read or write operation to consider it successful. By adjusting quorum settings, developers can balance the trade-off between consistency and availability in a distributed system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fa2af59-db26-481f-814b-37c759eea6e4', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does ''strictNullChecks'' fundamentally change the way developers handle undefined states?', N'Senior', N'With ''strictNullChecks'', null and undefined are treated as distinct types that must be explicitly handled. This forces developers to account for missing values at every point of access, significantly reducing the frequency of ''cannot read property of undefined'' runtime exceptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0ec9816-caca-49f6-abe5-37ca5e00d4d9', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How can Flask applications implement Graceful Shutdown to prevent dropped requests?', N'Senior', N'Graceful shutdown is achieved by catching OS signals (like SIGTERM) and instructing the WSGI server to stop accepting new requests while allowing current ones to complete. This is usually managed by the container orchestrator (e.g., Kubernetes) interacting with the WSGI server''s signal handling mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e940340-f9ff-4a3a-b5cf-37caf38538a1', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the primary benefit of using Astro''s built-in Content Collections?', N'Junior', N'Content Collections provide a way to organize, validate, and type-check your local content files like Markdown or MDX. They ensure that your frontmatter data follows a strict schema, preventing errors and improving development experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b4048c2-efca-4a6d-b1f8-37cc910b38fe', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Explain the role of the ''sequence'' helper in SvelteKit hooks.', N'Senior', N'The ''sequence'' helper allows multiple server hooks to be composed into a single chain, ensuring they execute in a specific, predictable order. This is vital for complex applications where tasks like authentication, logging, and performance monitoring must occur in a precise sequence for every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
