INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb899674-935f-42d0-aa38-37dbbfef19cc', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What does the ''static'' keyword do when applied to a class member?', N'Fresher', N'A static class member is shared by all instances of the class rather than belonging to a specific object. It exists independently of any objects and can be accessed using the class name even if no objects of that class have been created.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
