INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78447124-a784-403f-b78e-37e1ca1d672b', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What does ''Data Locality'' mean in the context of database design?', N'Middle', N'Data locality refers to storing related data close together, either on the same physical disk or the same node, to minimize latency during data retrieval. Designing for locality is critical in distributed systems to reduce the overhead of network traffic during complex query processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'262a1400-334d-47f5-abd1-37e2bf4eee46', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is dynamic routing in Nuxt?', N'Intern', N'Dynamic routing allows you to create pages that accept parameters, such as a user ID or a blog post slug. By using square brackets in a file name, Nuxt automatically treats that segment as a variable parameter in the URL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5e298a8-9b02-4ec6-ba51-37e2c7b5cff6', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle component lifecycle events compared to traditional frameworks?', N'Middle', N'Svelte provides lifecycle functions like onMount, beforeUpdate, and onDestroy which are executed at specific phases of a component''s existence. Unlike frameworks that might use complex hooks, Svelte''s lifecycle model is straightforward and tied directly to the DOM insertion and removal process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b300a354-764e-401f-b93f-37e495e1bead', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the recommendations to create new object?', N'Intern', N'It is recommended to avoid creating new objects using new Object(). Instead you can initialize values based on it is type to create the objects. * Assign {} instead of new Object() * Assign "" instead of new String() * Assign 0 instead of new Number() * Assign false instead of new Boolean() * Assign [] instead of new Array() * Assign /()/ instead of new RegExp() * Assign function (){} instead of new Function() Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c87953d-9157-44a9-936a-37e71d7d55a4', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the built-in iterables', N'Intern', N'Below are the list of built-in iterables in javascript, 1. Arrays and TypedArrays 2. Strings: Iterate over each character or Unicode code-points 3. Maps: iterate over its key-value pairs 4. Sets: iterates over their elements 5. arguments: An array-like special variable in functions 6. DOM collection such as NodeList', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afe40a54-987e-4c03-99fc-37e82da7d29c', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the role of the preprocessor in the C compilation process?', N'Intern', N'The preprocessor is the first step of compilation that handles directives starting with a hash symbol. It performs tasks such as including header files, expanding macros, and removing comments before the actual source code is passed to the compiler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acb3b7a5-9da4-47f9-842f-37e9862990ff', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the purpose of a Redis Set?', N'Fresher', N'A Redis Set is an unordered collection of unique strings. It is useful when you need to keep track of items while ensuring there are no duplicates and performing operations like intersections or unions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e61f706-cd19-4be9-9eb8-37ebe309b391', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does the Log-Structured Merge-Tree (LSM) storage engine optimize write performance?', N'Senior', N'LSM trees optimize writes by converting random write patterns into sequential I/O. Data is first written to an in-memory Memtable and then flushed to immutable SSTables on disk, which are periodically compacted to merge updates and reclaim space.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cad143ff-652f-4381-ab75-37ec49a3f60e', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle a scenario where an upstream service suddenly starts sending malformed data that crashes your downstream consumer?', N'Senior', N'I would implement a robust schema validation layer at the ingress point of the consumer and move the message to a dead-letter queue for further inspection. This isolates the problematic messages from the production processing flow and prevents the consumer from crashing due to unexpected input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef2573e4-55a3-4f9f-90d5-37edd135e65b', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Can SvelteKit be used as a Single Page Application (SPA)?', N'Fresher', N'Yes, SvelteKit can be configured to act as an SPA by disabling server-side rendering. This is often done when the application is entirely client-rendered and interacts with an external API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'586b5d3c-35b1-48c2-83d0-37f3b02ba6a0', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why is lazy loading essential for large-scale Ember applications?', N'Middle', N'Lazy loading prevents the browser from downloading the entire application code on the first visit. By splitting the application into chunks or engines, you improve the initial Time to Interactive (TTI) and significantly reduce the memory footprint on mobile devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b43240f-b5ad-4c30-aed2-37f496dba2a0', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What are the trade-offs of storing all application state in a single global Redux store?', N'Middle', N'A centralized store provides a single source of truth, making state management predictable and easy to debug. However, as an application scales, the store can become bloated and complex, potentially leading to performance bottlenecks if not properly normalized or partitioned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9153e23d-2a2f-47a7-a5b6-37f7172faae8', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Explain the significance of the shadow DOM in Lit components.', N'Junior', N'The shadow DOM provides encapsulation for a component''s styles and markup. It ensures that the component''s internal structure and CSS do not leak out to affect the rest of the page, and external styles do not unintentionally affect the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c272e600-7248-443d-96d3-37f861865ac2', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the primary benefit of using a prepared statement?', N'Junior', N'Prepared statements improve performance by pre-compiling the SQL query for reuse with different parameters. They also provide a significant security benefit by preventing SQL injection attacks, as the query structure and data are handled separately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b07eaf7-ae1e-4aa6-99be-37f89bef6110', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What does it mean for Svelte to be a compiler?', N'Intern', N'Being a compiler means Svelte analyzes your code during the build process to understand its dependencies and structure. Instead of shipping a large framework library to the browser, it outputs a small, optimized JavaScript file that performs the required UI updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed15f8f4-fe19-44fc-96e5-37f8b2841e87', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is Middleware in the context of Node.js web frameworks?', N'Intern', N'Middleware consists of functions that execute during the lifecycle of a request-response cycle. They have access to the request and response objects and can modify them or terminate the request early, commonly used for logging, authentication, and parsing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'933e5e15-0f39-4248-840c-37fc1ad2b663', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why is it dangerous to rely on PHP''s internal process execution order in multi-threaded environments?', N'Senior', N'PHP''s execution is not natively thread-safe in the context of persistent request state, and external extensions might introduce race conditions. Since the language design assumes a shared-nothing model, relying on mutable shared state between concurrent requests leads to non-deterministic behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f5f88fe-2387-4b61-9f4c-37fc4df47507', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why should you avoid using external middleware in Fastify if a native plugin exists?', N'Middle', N'Native Fastify plugins are designed to integrate with the framework''s optimized lifecycle and schema system, whereas external middleware often requires an adapter that can add overhead. Native plugins are almost always more performant and offer better compatibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf160602-8ec1-43d6-a37c-37ff167d910f', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does the AdonisJS ''Ace'' CLI architecture influence the development lifecycle in a microservices environment?', N'Senior', N'Ace provides a standardized mechanism for task automation, database migrations, and command-line interactions that remains consistent across the entire application ecosystem. This consistency reduces cognitive load when managing multiple microservices, as developers can rely on uniform tooling for common operational tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
