INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56a617c5-0505-453f-8608-38033afff861', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is jQuery''s approach to DOM manipulation considered harmful in the context of modern reactive frameworks?', N'Senior', N'jQuery relies on direct, imperative DOM mutation, which creates a ''source of truth'' conflict with frameworks that manage state declaratively. In reactive architectures, manual DOM manipulation disrupts the framework''s ability to reconcile the virtual DOM, leading to unpredictable UI states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c50730cc-4f37-44ae-b885-38080350b66e', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How do Extractors work in Actix and why are they considered a powerful design pattern?', N'Middle', N'Extractors are types that can be automatically pulled from an incoming request, such as path parameters, JSON bodies, or headers. They decouple request parsing logic from the business logic of the handler, allowing for clean, reusable, and type-safe argument injection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'874a4a22-0fe1-4ca7-95a8-3809465ee574', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the benefit of Qwik''s approach to JavaScript delivery?', N'Fresher', N'Qwik''s approach significantly reduces the initial load time by sending near-zero JavaScript to the browser initially. Because the application stays inert until interacted with, it achieves high performance scores even on slow mobile devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
