INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7351c364-7bab-473d-ab45-380d9df0d951', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux determine if the UI needs to re-render?', N'Junior', N'When the store state is updated, Redux notifies the connected components. The components then perform a shallow comparison of the selected data; if the data has changed, the component triggers a re-render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69e0ed94-380c-4b96-ad63-380df914254d', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus handle dependency injection compared to standard Spring Boot?', N'Middle', N'Quarkus uses Arc, a CDI-compliant container optimized for build-time resolution. Unlike Spring, which performs much of its dependency wiring dynamically at startup, Arc resolves the entire dependency graph at build time, resulting in faster startup and lower memory usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62371104-fb66-4ca7-90d4-3810ec864562', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does the ''Last Writer Wins'' conflict resolution work in Global Tables?', N'Senior', N'When two updates to the same item occur in different regions, DynamoDB compares the timestamps of the updates. The update with the latest timestamp is preserved, while the other is discarded. This mechanism is simple but means that application-level logic should be designed to handle potential data loss if simultaneous updates are expected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'405760b1-df0f-45ba-afe1-381732919bc8', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is an attribute in database modeling?', N'Intern', N'An attribute is a characteristic or property of an entity. In a database table, attributes are represented as columns that describe specific details about the entity, such as a name, email address, or price.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48ab2886-8f85-4893-848a-38177a4a5ae6', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between ''form_with'' and ''form_for'' in Rails?', N'Junior', N'form_with is the modern, unified helper introduced in Rails 5.1 to handle both model-backed and generic forms, replacing the older form_for and form_tag helpers. It defaults to remote AJAX submissions and is the current standard for Rails development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f8e3c40-de38-4329-be1a-38191a561291', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What does it mean for SvelteKit to be a meta-framework?', N'Intern', N'A meta-framework provides a set of tools and conventions on top of a core library, which in this case is Svelte. While Svelte handles the component logic and reactivity, SvelteKit provides the infrastructure for routing, build processes, and server communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb38f845-7b1f-4724-a51e-381a20a1cfc8', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin''s JSON binding mechanism handle validation, and why is it preferred over manual parsing?', N'Middle', N'Gin utilizes the ''binding'' tag in structs to map request data automatically, often integrating with the validator package. This approach is preferred because it centralizes validation logic, reduces boilerplate code, and ensures type safety before the request reaches the business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f74bede-f94c-42f5-ac67-381a6beacf48', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the difference between an API secret and an API key?', N'Middle', N'An API key is an identifier used to track the caller, while an API secret acts as a password to authenticate the caller''s identity. Using both together provides a two-factor security layer, ensuring that intercepted keys cannot be used without the corresponding secret.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4826105c-ac9d-4d93-835e-381dde3c30fa', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Explain the interaction between Litestar''s DI system and the application''s lifecycle events.', N'Senior', N'Litestar''s DI system can utilize application lifecycle events like ''startup'' and ''shutdown'' to initialize and clean up shared resources like connection pools. This ensures that expensive resources are prepared once during startup and made available for injection throughout the application''s runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01cb1083-a1ec-4f72-b112-381f13749446', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut maintain thread safety in its request-scoped beans?', N'Senior', N'Micronaut manages request-scoped beans by binding them to the current execution context, often leveraging non-blocking thread-local storage or passing context objects through the reactive chain. This ensures that state remains isolated between requests in highly concurrent, asynchronous environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc2bc9e3-3b13-4434-8889-381f1b5a7875', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How do you reference a specific DOM element within a component?', N'Junior', N'You can use the x-ref directive to give an element a name, and then access that element through the $refs magic property. This is useful for direct DOM manipulation when necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01c3a8fd-9120-4541-8b37-3820282f3f1b', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the purpose of cache busting and how can you achieve it?', N'Intern', N'Browsers have a cache to temporarily store files on websites so they don''t need to be re-downloaded again when switching between pages or reloading the same page. The server is set up to send headers that tell the browser to store the file for a given amount of time. This greatly increases website speed and preserves bandwidth. However, it can cause problems when the website has been changed by developers because the user''s cache still references old files. This can either leave them with old functionality or break a website if the cached CSS and JavaScript files are referencing elements that no longer exist, have moved or have been renamed. Cache busting is the process of forcing the browser to download the new files. This is done by naming the file something different to the old file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2783f1f-10a3-48b2-8c32-3823bf76b3b5', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does ''Cache Warming'' affect system stability after a deployment?', N'Senior', N'Cache warming pre-populates the cache with expected data before the system handles production traffic to prevent high latency during the ''cold start'' phase. Without it, the initial traffic spike can cause database overload as every request results in a cache miss.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19f015f4-3e61-4030-be4c-38247b21ddc9', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of the @Transactional annotation and how does it function?', N'Middle', N'The @Transactional annotation defines the scope of a database transaction, ensuring that a series of operations either all succeed or all roll back. It works using Spring AOP, which wraps the method call in a proxy object that handles transaction opening, committing, and rolling back upon encountering runtime exceptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17a21806-833e-4fe8-8a39-382533486de1', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How do R''s promises facilitate lazy evaluation?', N'Senior', N'Promises are the internal mechanism that stores the expression, the environment where it was created, and a value slot for the result. Evaluation occurs only when the value is accessed, allowing for efficient function calls where unused arguments are never computed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3505d501-b553-44a7-845e-38265b153b61', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle component lifecycle methods?', N'Intern', N'In functional components, Preact uses hooks like useEffect to handle lifecycle events such as mounting, updating, and unmounting. In class components, traditional methods like componentDidMount are still available.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd13ea2c-63e0-47a9-b8a1-3827605092b8', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the advantages of using the Java Stream API over traditional loops?', N'Middle', N'The Stream API enables a functional programming style that improves code readability and declarativeness. It simplifies complex collection operations through built-in methods like filter, map, and reduce, and provides built-in support for parallel processing. However, traditional loops may still be more performant for simple, low-latency operations due to reduced object allocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1af7db5-1138-475c-a23e-382793e34b88', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the concept of ''Mass Assignment'' and how Laravel prevents it.', N'Middle', N'Mass assignment occurs when a user passes unexpected HTTP input fields that modify database columns they shouldn''t have access to. Laravel prevents this by requiring developers to explicitly define ''$fillable'' or ''$guarded'' properties on the model to whitelist or blacklist fields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'763f46ae-27d4-4cd4-ba94-3827d283c1ec', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi manage request context?', N'Junior', N'Chi leverages the standard context.Context package to pass request-scoped information. When a route is matched, Chi injects the URL parameters into this context, allowing handlers to access them safely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'027a5f2e-b635-472a-a72e-3828ebd2fae2', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Analyze the performance implications of R''s functional programming paradigm compared to imperative approaches.', N'Senior', N'R''s functional nature encourages vectorization, which leverages highly optimized C/Fortran backends, typically outperforming explicit loops. However, the overhead of creating function closures and applying higher-order functions can introduce latency compared to imperative memory manipulation in lower-level languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
