INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10e7f472-f9a2-400c-b474-383021c53260', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the difference between middleware and interceptors in Express or Fastify?', N'Middle', N'Middleware is a series of functions that have access to the request and response objects, used for modifying them or ending the cycle. Interceptors are typically higher-level abstractions used in frameworks like NestJS to transform the result of a handler or add cross-cutting logic before or after execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
