INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed08e0a0-05cb-43c3-94bd-383a117fa9a3', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does document storage differ from tabular storage?', N'Junior', N'Tabular storage organizes data into fixed rows and columns, requiring a consistent structure across all entries. Document storage allows each record to have its own unique fields and nested structures, providing more flexibility for evolving data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fab7c64b-fd3f-441d-aeda-383d67d7db53', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Discuss the trade-offs of using short-lived vs. long-lived credentials in distributed systems.', N'Senior', N'Short-lived credentials significantly reduce the blast radius of a credential leak because they expire quickly and often require automated renewal, minimizing the utility of stolen tokens. Long-lived credentials are easier to manage but present a significant risk because they require manual rotation and, if compromised, provide attackers with persistent access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4afc2ff-568c-4b38-9960-38408faf3b6d', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why is it important to use ''self'' inside closures?', N'Junior', N'In Swift, you must explicitly use ''self'' when accessing properties or methods within a closure to clarify that you are capturing a reference to the instance. This is especially important for avoiding retain cycles, where you might need to use a capture list to declare ''weak self''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3ac2740-5e6a-4667-96ec-38429c03796c', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the difference between @Controller and @Client?', N'Intern', N'A @Controller is used to define an endpoint that your application exposes to handle incoming requests. A @Client is used to define an interface that your application uses to send requests to external services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72d59507-2ec6-46ce-b9c1-38431f941369', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the benefit of using Alpine.js for a small project?', N'Fresher', N'The main benefit is the reduced complexity and development time. Because there is no build pipeline or complex state management library to configure, you can add interactivity to your site much faster than with larger frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'626268d5-3c77-4559-9af7-384476ec98dd', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the architectural considerations when implementing Transactions in DynamoDB?', N'Senior', N'Transactions in DynamoDB use a two-phase commit protocol under the hood, which effectively doubles the consumed write capacity. They introduce higher latency compared to standard operations and should be used sparingly for critical state updates. Architectural design should favor idempotent operations to avoid the need for transactions whenever possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d357f2f-e3eb-4379-8bc5-38477f7c7dde', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is your reasoning for using ''relative sizing'' (story points) versus ''absolute time'' (hours) in project planning?', N'Senior', N'I prefer relative sizing because it accounts for uncertainty and complexity without the psychological pressure of ticking clocks. It allows teams to focus on the effort and risk involved, which provides a more accurate reflection of velocity over the long term compared to subjective hourly estimates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1cb57bce-133c-4806-b5d4-384dc8649f2e', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a trigger?', N'Intern', N'A trigger is a database object that automatically executes a specified function when a particular event occurs in the database. Events include actions like inserting, updating, or deleting rows in a table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7636f0cb-05fe-4c21-b0b6-384e41cf5bc4', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of properties in C#?', N'Intern', N'Properties provide a flexible mechanism to read, write, or compute the values of private fields while maintaining encapsulation. They use get and set accessors to control how data is accessed and modified externally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afb7f817-30b2-44ab-b009-384f054e0996', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Why is ''Method Missing'' considered a powerful but risky architectural pattern in Ruby?', N'Senior', N'Method missing allows for dynamic proxying and metaprogramming, enabling flexible APIs that react to arbitrary method calls. However, it circumvents static analysis tools, makes debugging difficult due to the lack of explicit definitions, and can introduce performance bottlenecks if the lookup chain is traversed unnecessarily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95976c0d-c0a5-47c1-b898-384f0c32e42a', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is Qwik considered an ''O(1)'' framework regarding time-to-interactive?', N'Senior', N'It is O(1) because the initial execution cost does not depend on the size of the application or the component tree depth. The framework only processes the minimum required logic for a specific interaction, meaning complexity stays flat as the codebase expands.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
