INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'466425e3-a224-4d43-ab52-3853ece1c14c', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Explain the impact of Partitioning (Sharding) on database performance and data consistency.', N'Senior', N'Sharding enables horizontal scalability by distributing data across multiple nodes, significantly increasing throughput and storage capacity. However, it introduces complexity in cross-shard queries and transactions, often requiring a shift toward eventual consistency models and more sophisticated application-level logic for data aggregation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
