INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'136edca1-0c93-479e-8da0-386c2bd81556', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Can a transaction contain only one statement?', N'Fresher', N'Yes, a transaction can consist of a single SQL statement. In many database systems, a single statement is treated as an implicit transaction by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a966e574-0de5-45ce-915b-386c328b304a', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Why might you choose to use a custom ClassLoader instead of the system default?', N'Middle', N'Custom ClassLoaders allow for dynamic loading of classes from non-standard sources like network streams or encrypted files, which is essential for plugin architectures and modular systems. They also enable class isolation, allowing multiple versions of the same library to coexist within a single Java Virtual Machine by keeping them in separate namespaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20375947-6b24-4d73-9a9e-386e9e299bd8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a rest parameter?', N'Intern', N'The rest parameter is used to represent an indefinite number of arguments as an array. The important point here is only the function''s last parameter can be a "rest parameter". This feature has been introduced to reduce the boilerplate code that was induced by the arguments. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9aaf327-39f1-4374-8ae5-38705367566b', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'When should you choose a NoSQL database over a relational database?', N'Middle', N'NoSQL databases are preferred when dealing with unstructured data, massive horizontal scalability requirements, or rapid schema evolution. Relational databases are generally better suited for applications requiring complex transactions, strict consistency, and structured data with complex relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1488836-628c-4ffe-a854-38733e989d96', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the ''Service Level Objective'' (SLO) and how does it differ from an ''SLA''?', N'Middle', N'An SLA is a contractual agreement with a customer regarding uptime, often involving financial penalties. An SLO is an internal target for reliability that guides engineering efforts and helps decide when to trade off features for performance or stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'601793b6-665a-4bce-8238-3873c7373270', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'When is a Key-Value store most appropriate?', N'Fresher', N'A key-value store is ideal for use cases like session management, user profiles, or shopping carts where fast, simple read and write operations are required based on a unique identifier.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95d773f4-1b51-42ce-96c7-38759545f740', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the limitations of using MongoDB?', N'Fresher', N'MongoDB is not ideal for applications requiring complex multi-table joins or strict ACID transactions across multiple documents. It also typically consumes more disk space than relational databases due to the overhead of storing field names in every document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27578003-e874-4088-afb8-3875ccfc9c4c', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Can you nest media queries in Sass?', N'Intern', N'Yes, Sass allows you to nest media queries directly inside the selector they apply to. This keeps the responsive logic bundled with the component''s styles rather than at the bottom of a global file, improving readability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d62056f-96d0-454d-bed6-3877bfbfad08', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are the trade-offs of Preact''s approach to state updates during component lifecycle?', N'Senior', N'Preact prioritizes immediate state updates to keep the UI in sync with the data, which can lead to multiple re-renders if not managed correctly. While this avoids the complexity of internal batching queues found in React, it requires developers to be more explicit with state-update debouncing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59a87a8a-5357-445c-b000-38780a81814d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is currying, and how does it differ from partial application?', N'Intern', N'Currying transforms a function of n arguments into a chain of n unary (single-argument) functions: f(a, b, c) becomes f(a)(b)(c). Each call returns a new function waiting for the next argument until all arguments are supplied. Partial application fixes some arguments of a function, returning a new function that expects the remaining arguments — the result does not have to be unary. The distinction: - Currying always produces unary functions step by step. - Partial application fixes k of n args at once, producing a function of n-k args (which can be > 1). - .bind(null, arg1) is partial application, not currying.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cca49ca-211d-44f8-8dae-387857425752', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How are HTTP errors handled in Axum?', N'Fresher', N'Axum uses the IntoResponse trait to convert return types into HTTP responses. If a handler returns a Result type, the error variant can be mapped to an appropriate HTTP status code, ensuring consistent error reporting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7709e8bf-e66c-43d0-95f5-3878f5ea46bf', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Compaction work and why is it important?', N'Middle', N'Compaction merges multiple SSTables into a single file and discards obsolete data like Tombstones and overwritten versions. This process is critical for reclaiming disk space and improving read performance by reducing the number of files the system must check.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd129ed03-9f8f-41b8-8c1b-3879ede75ee5', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How do database stats influence query performance?', N'Middle', N'The database query optimizer uses statistics to estimate the distribution of data and the selectivity of filter conditions. Accurate, up-to-date stats are essential for the optimizer to choose the most efficient join order and access methods, such as deciding between a nested loop or a hash join.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4958dcc7-7a3d-4f80-9173-387e88ee87d9', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the advantage of ''resumability'' for mobile devices?', N'Middle', N'On mobile, CPU and network resources are often constrained. By avoiding the heavy JavaScript execution required for hydration, Qwik allows mobile browsers to become interactive much faster, providing a better user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c56c191-27f3-44d6-aaef-387e9fb751fc', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Does Hono support TypeScript by default?', N'Intern', N'Yes, Hono is built with TypeScript in mind and offers excellent type safety. This allows developers to catch errors at compile time and enjoy better autocomplete features when writing code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5876422a-f8de-4e82-8d1c-388124a27ce5', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How can you optimize a join between two very large tables?', N'Middle', N'Optimization can involve ensuring proper indexing on join columns, updating statistics to help the planner choose the right join strategy, or using partitioning to reduce the amount of data scanned. In some cases, denormalization or creating a materialized view can also improve performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31fe5668-6dab-4835-903f-38812637f622', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of the AdonisJS Service Provider?', N'Intern', N'A Service Provider is the central place to configure and register parts of an application. It is where you bind services into the application''s IoC container so that they can be used throughout the project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37ad1a6c-4d3d-4e42-be45-3881febcaf76', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is a Flash Message in Symfony?', N'Fresher', N'A flash message is a temporary message stored in the session that is displayed to the user after a redirect. It is commonly used for success or error notifications, such as confirming that a form was submitted successfully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cf949f6-f60e-40a8-8617-38845ed07c93', N'954a0331-deff-4399-b588-96f39fec001d', N'What is a zoneless Angular application and why is this mode significant?', N'Intern', N'A zoneless Angular application is one configured to run without zone.js, the library that traditionally monkey-patches browser async APIs (like setTimeout, addEventListener, fetch) to automatically notify Angular when something _might_ have changed, triggering change detection. The significance of zoneless mode lies in moving away from this automatic, potentially over-eager change detection mechanism. Instead, change detection is triggered explicitly by the developer (e.g., using ChangeDetectorRef.markForCheck()) or, more importantly, reactively by Angular''s new Signals primitive. This approach offers several benefits: - Improved Performance: Change detection runs only when truly necessary, reducing unnecessary checks and improving application speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'917ff6e9-7c53-4c8d-8d44-3887bcfb24fe', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach prioritizing which features to build first in a new project?', N'Fresher', N'I would identify the core functionality that provides the most value to the user and prioritize those as the Minimum Viable Product. By focusing on essential features first, I can get feedback early and ensure the fundamental purpose of the application is sound.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f733d5e5-95cd-4184-a20c-388b761c61dd', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle automatic OpenAPI (Swagger) documentation generation, and why is this useful for large-scale systems?', N'Senior', N'FastAPI introspects route paths, type-annotated parameters, and Pydantic models to construct a valid OpenAPI schema at runtime. This ensures that documentation remains perfectly synchronized with the codebase, facilitating better API contract enforcement and easier consumption by frontend teams or automated client generation tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b8aac2c-5e5a-47ce-9b67-388e1ffce18e', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a primary key in a relational database?', N'Intern', N'A primary key is a specific column or set of columns that uniquely identifies each row in a table. It ensures that every record can be referenced individually and prevents duplicate entries for the same identifier.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81554fc7-2268-4a8f-98b8-38905aec5fc2', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is Ruby, and why is it popular for web development?', N'Intern', N'Ruby is a dynamic, object-oriented programming language known for its simplicity and focus on developer productivity. Its main claim to fame in web development is the web application framework, Ruby on Rails (RoR), which transformed the way web applications are built by promoting convention over configuration. Key Features & Contributions to Web Development - Language Syntax: Ruby''s syntax has an appeasing natural language style. This, paired with its dynamic typing, powerful metaprogramming features, and absence of semicolons, results in clean and expressive code. - Gems: Ruby''s package manager, RubyGems, simplifies library management, making it easy to integrate numerous third-party extensions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3edd2a6-1631-4f03-9a90-38919c9c9830', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the ''Reply'' object in Fastify?', N'Intern', N'The Reply object is an abstraction of the underlying HTTP response. It provides methods to send data, set headers, and manage the status code of the response sent back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7eba9c0c-2d98-4de2-8ace-3892fb57c1b8', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you handle multi-region data replication to ensure low latency and disaster recovery?', N'Senior', N'I categorize data based on sensitivity and consistency requirements, using active-active replication for globally distributed read-heavy services. For write-heavy operations, I use active-passive setups with automated failover, acknowledging the potential for data loss and implementing robust reconciliation processes to fix inconsistencies post-recovery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6320b814-f1f6-4cff-b4be-3895a190f4cb', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the function of the ''nitro'' engine in Nuxt 3?', N'Middle', N'Nitro is a high-performance server engine that powers Nuxt. It allows for cross-platform deployment by providing a consistent server layer that can run on Node.js, edge workers, or serverless environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2623a27c-1890-4e95-a6cb-3897c3fd4a80', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle component lifecycle?', N'Intern', N'Alpine.js provides lifecycle hooks like x-init to execute logic when a component is first initialized. While it does not have as many hooks as larger frameworks, it is sufficient for standard state setup and DOM manipulation tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d742952-b092-47a0-adcb-3898732a5819', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono''s use of Web Standards (Request/Response) impact its portability across different JavaScript runtimes?', N'Senior', N'By adhering strictly to the Fetch API standards rather than Node.js-specific APIs, Hono ensures consistent behavior across diverse environments like Cloudflare Workers, Bun, Deno, and Vercel Edge. This architectural choice decouples the framework from underlying platform-specific syscalls, facilitating seamless migration and multi-cloud deployment strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd02e2379-9464-472f-9fa5-38989cbb51e6', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the architectural risks of over-relying on global event buses in a Vue application?', N'Senior', N'Global event buses create implicit dependencies between unrelated components, making the codebase difficult to trace, debug, and refactor. This pattern obscures the data flow and violates the principle of unidirectional data flow, which is better handled by explicit props or state management stores.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c451f13-1d6b-4891-a4c4-389aa38ce8ca', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What are the architectural benefits and risks of implementing a caching layer (e.g., Redis) in front of a database?', N'Senior', N'A cache layer significantly reduces database load and latency for hot data, improving system responsiveness. The risk is ''cache stampede'' or ''thundering herd'' when a cache entry expires, potentially overwhelming the origin database, which necessitates strategies like jitter, mutex locks, or proactive cache refreshing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12e10cf3-3ff8-4b2c-be5c-389c4f81e668', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does the Svelte compiler manage context propagation?', N'Senior', N'Context API in Svelte allows data to be passed down through the component tree without prop drilling. The framework maintains a reactive context map, ensuring that any subscriber to a context key receives updates when the value provided by a parent changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
