INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd268a58d-c94f-45a1-adcd-38a89ce931a4', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of the ''manager'' in Django models, and how can you create a custom one?', N'Middle', N'A manager is the interface through which database query operations are provided to Django models. You can create a custom manager to encapsulate common query logic, such as filtering by a specific status, to keep your business logic clean and reusable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b6733c2-6520-4ef2-abf9-38a8e593629c', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is AOT compilation and why does it matter for Micronaut?', N'Intern', N'AOT compilation refers to the process of translating code into machine-executable form during the build phase rather than at runtime. For Micronaut, this is critical because it eliminates the need for expensive reflection and proxy generation when the application starts, resulting in faster cold starts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
