INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'520560da-327f-4f88-8d50-38ace220a76f', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the role of SvelteKit in the Svelte ecosystem?', N'Intern', N'SvelteKit is a full-stack framework built on top of Svelte that simplifies the process of building web applications. It provides essential features out of the box, such as routing, server-side rendering, and API endpoint handling, which would otherwise require manual configuration. Essentially, it acts as the structure and toolkit that allows developers to deploy Svelte components into a complete, production-ready application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96e163cf-ea1f-4936-be7d-38af4989ef39', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the primary purpose of Preact in frontend development?', N'Fresher', N'Preact is a lightweight alternative to React that provides the same application programming interface but with a significantly smaller file size. It is designed to be fast and memory-efficient, making it ideal for performance-sensitive web applications or projects with tight bundle size constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3761bf45-4ff3-47ff-9c14-38af63c6e073', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What does ''Hydration'' usually imply in the context of frontend frameworks?', N'Fresher', N'Hydration is the process where a framework attaches event listeners and internal state to static HTML generated by the server. This process is often heavy because the browser must download and execute the entire framework and component logic to make the page interactive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4072dc40-7ee3-401e-be89-38b2531adce8', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is an HTTP method?', N'Intern', N'An HTTP method indicates the desired action to be performed on a resource, such as GET to retrieve data, POST to create data, PUT to update data, and DELETE to remove data. FastAPI uses these methods to map incoming requests to the appropriate function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99199597-7745-4711-8654-38b300129fc0', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How do you define a constant that is computed at runtime in Swift?', N'Fresher', N'In Swift, you can use lazy properties and immediately-invoked closure expressions (IICE) to compute values at runtime, ensuring they are calculated only once. Let''s look at the detailed steps for both approaches. Using Get-Only Computed Properties A get only computed properties are declared using the var keyword but without a set block. They''re calculated when accessed and won''t change afterward, effectively becoming constants after the initial calculation. Implementing Set-Once Computed Properties This method combines a stored property with a didSet observer to handle computations only when the property is initially set. - Pros: Offers an immediate computed value and ensures the computation is done only once. - Cons: Looks lengthier than other options.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'063a274b-ce78-46d7-8b6a-38b58ca88f95', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Explain the trade-offs between Write-Through and Write-Back caching strategies in a distributed system.', N'Senior', N'Write-Through ensures strong consistency by updating the cache and database simultaneously but increases write latency. Write-Back improves performance by updating the cache first and asynchronously persisting to the database, though it introduces a risk of data loss if the cache node fails before the write-back occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'684e9141-d2eb-4fce-9cc2-38b6f1b45361', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the benefit of Tailwind''s ''Content'' configuration in a monorepo structure?', N'Senior', N'The ''Content'' configuration allows the JIT engine to precisely track files across multiple packages or workspaces. This ensures that the build tool correctly identifies and includes utility classes used across different internal libraries, preventing missing styles in a modular codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7ddbb77-ef2f-49f8-a253-38b9070b7322', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a persistent table and a temporary table?', N'Junior', N'A persistent table exists in the database until it is explicitly dropped. A temporary table only exists for the duration of a single database session and is automatically dropped when the session ends.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8495180a-36ed-46af-b0e5-38c190a64c2d', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does it mean to ''commit'' a transaction?', N'Intern', N'Committing a transaction is the act of making all changes performed during that transaction permanent in the database. Once a transaction is committed, it cannot be rolled back.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'983b543d-5c4f-4dbf-b8e0-38c5f6969fca', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP handle memory management, and what is the role of reference counting?', N'Middle', N'PHP uses a reference counting mechanism to track the number of variables pointing to a specific piece of data in memory. When the reference count drops to zero, the engine automatically frees the memory, supplemented by a cyclic garbage collector that cleans up memory leaks caused by circular references.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50ab6446-f7a9-4675-8c41-38c91ccc5902', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are the performance implications of Symfony''s ''Profiler'' in a production environment, and how is this mitigated?', N'Senior', N'The profiler collects extensive data on memory usage, database queries, and event execution, which introduces significant overhead. It is strictly disabled in production environments through environment-specific configuration to ensure maximum throughput and minimal latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'798a5e2b-ecb1-4d73-acea-38cc1b403bca', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Can Qwik applications work without JavaScript?', N'Fresher', N'Qwik is built to be resilient, but it relies on JavaScript for interactivity. However, because it delivers fully rendered HTML first, the content is visible and readable to users and search engines even before the JavaScript is loaded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e29aff30-0b3c-48f5-9189-38cc9b743581', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What impact does a large number of actions have on application maintainability?', N'Senior', N'A large number of actions can lead to ''action bloat'' and difficulty in tracing state flow, especially if actions are not categorized or managed via constants. Scalability is maintained by using feature-based folders, action creators, and well-defined interfaces to keep the action space organized and discoverable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14be3b07-1570-485a-bb1c-38cf92d8d70b', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does the Express middleware chain handle asynchronous errors, and why is this critical for stability?', N'Middle', N'In Express, errors must be passed to the next function with an argument to trigger the centralized error-handling middleware. If an asynchronous error is thrown without being caught or passed to next, the process will encounter an unhandled exception, potentially causing the server to crash. Proper error propagation ensures that the request-response cycle is closed gracefully and the application state remains consistent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89ff97a8-42d1-4660-ad7b-38d10ea486ad', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What are the trade-offs of increasing the number of partitions in a message queue like Kafka?', N'Middle', N'Increasing partitions allows for higher throughput and greater parallelism because more consumers can read simultaneously. However, it also increases the overhead on the broker to manage state and can lead to longer recovery times if a broker fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3439ae2-ffdc-4c8c-bc4d-38d4f93e76f7', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify manage asynchronous error handling differently from callbacks?', N'Senior', N'Fastify is built with first-class support for promises and async/await syntax, ensuring that errors in asynchronous operations are caught and forwarded to the central error handler automatically. This eliminates the need for redundant try-catch blocks in every route and provides a consistent way to handle operational and programmer errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c20ea46-1864-49de-8658-38d6039009fe', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket''s testing framework ensure parity between production and development?', N'Senior', N'Rocket provides a ''local'' client that mimics the entire request-response cycle without requiring an actual network socket. This allows developers to write integration tests that trigger the same routing, guards, and middleware as a live server, ensuring that tests accurately reflect production behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
