INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e236e023-66b4-441e-813f-390d5fd00af7', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'In what scenario would you implement a ''Custom Exception Filter'' over the default one?', N'Senior', N'You implement a custom filter when you need to standardize error responses across a distributed system or log specific error types to an external monitoring service. The default filter is generic, whereas a custom one allows you to map internal domain exceptions to specific, meaningful HTTP status codes and response bodies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18ae0cf4-2d23-4b79-bda2-390feeba1584', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the primary architectural difference between Go''s scheduler and traditional OS thread scheduling?', N'Senior', N'Go uses an M:N scheduler that multiplexes many goroutines onto a smaller number of OS threads. Unlike OS scheduling, which is preemptive and context-heavy, the Go runtime performs user-space context switching, which is significantly cheaper as it only requires swapping a small set of registers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a180f82c-ef84-485e-87e1-3913c2a0c4fe', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a primary advantage of using JSON in NoSQL databases?', N'Intern', N'JSON is a lightweight, human-readable format that is easily parsed by most programming languages. Its hierarchical structure allows developers to represent complex, nested data models naturally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6a687d7-9ccb-4c81-b1ff-39140bc570d6', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you identify the root cause of a recurring issue?', N'Fresher', N'I look for patterns in when and how the issue occurs by reviewing logs and historical data. I then formulate a hypothesis about what might be triggering the error and test that hypothesis in a controlled environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10885732-4494-4622-bec0-39147127bf68', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How do you create a middleware that logs the request method and URL for every request?', N'Fresher', N'In Express.js, middlewares allow you to handle HTTP requests. Here, you will learn how to create a simple logging middleware that records the request method and URL. Setting Up the Express App First, install Express via npm, and set up your app.js file: Creating the Logging Middleware Define a logging function that extracts the request method and URL, and then use app.use() to mount it as middleware. Testing the Setup Use app.get() to handle GET requests, and app.listen() to start the server. When you visit http://localhost:3000/ in your browser and check the server console, you should see the request being logged. Explore all 58 answers here 👉 Devinterview.io - Express.js', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'781893ac-6717-454b-bc04-391644af899e', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is a Join Point in Spring AOP?', N'Intern', N'A Join Point in Spring AOP represents a specific point during the execution of a program, which could be targeted for additional functionality, such as before, after, or around method calls. When a join point is intercepted by a Spring AOP advice, the advice can perform certain actions. The availability of join points differs across diverse AOP methodologies. For example, AspectJ provides more extensive join points than proxy-based AOP in Spring. Common Join Points - Method Execution: This join point signifies execution of a method. - Method Call: Denotes when the method is called from another location in the code. - Class Initialization: Marks when a class is initialized. - Field Access: Represents read or write actions on a field.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9df9c717-0ca0-484f-99fe-39170f09982f', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a Flask session?', N'Intern', N'A session allows the server to store information about a user across multiple requests. It uses cookies to identify the user, enabling the application to remember stateful data like login status or shopping cart contents.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70fbe54b-c684-4795-bafb-391aa1dc8591', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is a layout file in SvelteKit?', N'Intern', N'A layout file, named +layout.svelte, allows you to define shared UI elements like headers or footers that persist across multiple pages. It wraps the content of child pages to maintain a consistent structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f09efffe-7d4d-4cb2-a52d-391ca34a2fbc', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the role of AJV in Fastify''s performance strategy?', N'Senior', N'AJV compiles JSON schemas into highly optimized machine code at startup. By performing validation and serialization at the JIT level, Fastify significantly reduces the CPU cost of data processing compared to runtime reflection-based validators.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'333107bc-0922-4e3c-bab6-391d513d1e01', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does denormalization help with database performance?', N'Middle', N'Denormalization involves intentionally adding redundant data to tables to reduce the need for expensive JOIN operations. This improves read performance at the cost of increased storage usage and more complex update logic to maintain data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'165181c1-56da-49b8-ba51-391d921129ca', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is ''Metadata'' in Next.js?', N'Fresher', N'Metadata is an object exported from a page or layout that defines the page''s SEO information. It is used by Next.js to automatically populate the document head with tags like title, description, and Open Graph data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'930c2611-8642-4aca-b34c-39201b1df0af', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Discuss the role of ''Error Boundaries'' in Remix and how they differ from React-only implementations.', N'Senior', N'While they utilize React''s error boundary concept, Remix Error Boundaries operate at the route level and can handle both client-side and server-side errors. This allows the server to send an error status code while simultaneously rendering a fallback component, ensuring the user sees a valid UI even when a data fetch fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ed0b60d-2a20-49d6-95b1-3926839e64d0', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the role of the ''Outlet'' component in Remix?', N'Fresher', N'The Outlet component is a placeholder in a layout route that tells Remix where to render nested child routes. It allows you to maintain persistent layout elements while swapping out the main content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'230af998-1f7e-4f64-839b-39286e09d593', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the role of the Program.cs file?', N'Intern', N'Program.cs is the main entry point of an ASP.NET Core application. It initializes the web host, sets up the configuration, and starts the application server to begin listening for incoming requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'590878fa-3b52-4f9f-8668-39299bbe00c9', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do Type Guards and Discriminated Unions facilitate type narrowing in complex application states?', N'Senior', N'Discriminated unions use a common literal property to distinguish between variant types, allowing the compiler to narrow the type automatically. Custom type guards provide a mechanism to refine types based on runtime checks, which is essential for handling unpredictable data from APIs or external services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a01af731-5b7e-4dc5-a848-392a1b9921e5', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does hoisting interact with the class declaration?', N'Fresher', N'Class declarations are hoisted to the top of their block scope — like let and const — but they are not initialised until the declaration is evaluated. This means they sit in the Temporal Dead Zone (TDZ) and accessing a class before its declaration throws a ReferenceError, not a TypeError. This is a deliberate choice to prevent confusing inheritance hierarchies from being constructed before base classes are fully defined. Example: Practical implication — class vs. function constructor: Real-World Use Case: When splitting large Node.js services into files with circular require() references, class-based modules that are accessed during the require() cycle before the class declaration evaluates throw ReferenceError.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb31e222-0654-485e-a1f2-392abd7f0e07', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you ensure your work is ''maintainable'' for other team members?', N'Intern', N'I focus on writing clean, well-structured work that follows established team standards and conventions. I also include clear documentation that explains not just what I did, but the ''why'' behind my design decisions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8296a8a-7160-4c2b-9e89-392b495cb139', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the advantage of using ''Reflect-metadata'' in NestJS?', N'Middle', N'It allows NestJS to read metadata attached to classes, methods, or properties via decorators at runtime. This is the core mechanism behind the dependency injection and routing systems, enabling the framework to understand how to wire components together.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67d1be66-7e1b-4474-bfa9-392c62ff3833', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Explain the concept of database sharding and the main architectural trade-off involved.', N'Middle', N'Sharding is the process of splitting a large dataset into smaller, more manageable chunks distributed across multiple database instances. The primary trade-off is increased complexity in data management and the difficulty of performing cross-shard joins or transactions, which can significantly impact application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cd09344-f51a-4fc1-b060-392d633269e0', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How V8 compiles JavaScript code?', N'Fresher', N'Compilation is the process of converting human-readable code to machine code. There are two ways to compile the code * Using an Interpreter: The interpreter scans the code line by line and converts it into byte code. * Using a Compiler: The Compiler scans the entire document and compiles it into highly optimized byte code. The V8 engine uses both a compiler and an interpreter and follows just-in-time (JIT) compilation to speed up the execution. JIT compiling works by compiling small portions of code that are just about to be executed. This prevents long compilation time and the code being compiles is only that which is highly likely to run.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22b6ecb0-22d3-48ea-bb29-392e6ea96134', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Why is it important to use ''min-height'' instead of ''height'' for responsive containers?', N'Middle', N'Using ''height'' forces a fixed size that can lead to content overflow if the text or inner content exceeds that dimension. ''Min-height'' allows the container to grow dynamically based on its content while ensuring a minimum footprint, which is crucial for responsive design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0704ed1e-a7da-4ec8-a520-393165d3922f', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Explain the trade-off between eventually consistent and strongly consistent reads.', N'Middle', N'Eventually consistent reads are cheaper and offer lower latency but may return stale data if an update occurred recently. Strongly consistent reads return the most up-to-date data by ensuring that all prior successful writes are reflected, but they consume twice the read capacity units and have higher latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1ea420f-4532-45bb-a2ea-3932a6d106f5', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack''s tree-shaking mechanism interact with CommonJS modules?', N'Senior', N'Webpack''s tree-shaking relies on the static structure of ES modules, which allows the bundler to analyze imports and exports at compile time. Because CommonJS modules are dynamic and can be required conditionally or based on runtime logic, Webpack cannot safely determine which parts are unused, effectively disabling tree-shaking for those modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7bb816b-da06-4765-964e-3933476d9e5f', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are the architectural implications of the ''as-if'' rule in C compiler optimizations?', N'Senior', N'The as-if rule permits compilers to perform any transformation that preserves the observable behavior of the program, which is defined strictly by volatile accesses and program output. This allows for aggressive reordering and dead-code elimination, provided the final state of these observable entities remains consistent with the sequential execution flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b746057-86cc-4119-a590-39338e8d687e', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does the Sass module system (@use) improve upon the legacy @import rule?', N'Senior', N'The @use rule solves the global namespace pollution problem by namespacing variables, functions, and mixins under the module name. It also ensures that each file is loaded only once, regardless of how many times it is imported, which improves compilation performance and avoids redundant CSS duplication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ec72622-fd8a-4f08-8d9b-393517d4fb11', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Explain the concept of ''progressive enhancement'' in SvelteKit forms and why it is a senior architectural requirement.', N'Senior', N'Progressive enhancement ensures that forms work via standard browser requests before JavaScript has loaded, providing a fallback for unreliable networks. Once the framework initializes, it intercepts these requests to provide a seamless, non-reloading experience, balancing robustness with modern interactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba1a3786-b19d-407a-a1a4-3937000cb1ef', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the role of Isolation in transactional databases?', N'Junior', N'Isolation ensures that the intermediate state of a transaction is invisible to other concurrent transactions. It prevents multiple transactions from interfering with each other, making it appear as if they are executing sequentially.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4013909-f404-4484-a78c-3938ccb0c6c0', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are the advantages of using Sass for large-scale enterprise applications?', N'Middle', N'Sass provides powerful features like partials, nesting, and modular imports that help maintain a clean and scalable file structure. It enables developers to implement design systems through variables and logic, which ensures consistency and reduces code duplication across large codebases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0a3967d-f1b3-42ad-889e-393a02ed92ac', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How do you optimize the critical rendering path in a Nuxt application?', N'Senior', N'Optimizing the critical path involves leveraging Nuxt''s automatic code splitting, preloading essential assets, and minimizing the size of the initial JavaScript bundle. Additionally, utilizing ''Payload Extraction'' and keeping the server-rendered HTML payload lean prevents layout shifts and reduces Time to First Byte (TTFB).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81a7d8e8-2c0b-4111-8ddd-393c0ba2502f', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the architectural implications of using the ''Thread Pool'' plugin in high-concurrency MySQL environments?', N'Senior', N'The thread pool limits the number of active threads executing queries, preventing the resource exhaustion that occurs when thousands of simultaneous connections attempt to context-switch on the CPU. It improves scalability by decoupling the number of client connections from the number of active server threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e24cdbd-ce5c-4115-a5f4-393c0cb9bc56', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js manage the ''n+1'' problem in reactive loops?', N'Senior', N'Alpine''s reactivity engine tracks dependencies at the property level, which helps avoid unnecessary re-renders. However, because it operates on the DOM, developers must be mindful of using x-for loops efficiently to prevent excessive DOM thrashing during large list updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac99277f-f7a0-448f-a3da-393ce049d7a1', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the concept of lazy loading in Flask.', N'Middle', N'Lazy loading refers to initializing resources like database connections or cache clients only when they are first accessed. This reduces startup time and prevents unnecessary resource allocation if those components are not needed during a specific request cycle. It is a common pattern in the app factory approach to keep the application modular.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c559ca6-f4b2-463c-a23b-393ee536253d', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach a task that seems overly complex or poorly defined?', N'Junior', N'I would ask clarifying questions to the person who assigned the task to define the scope and expected outcomes. Breaking the problem down into smaller, logical steps helps turn an overwhelming requirement into a concrete plan of action.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33494a72-1d4e-4c8e-8c72-394287645211', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Describe the function of a ''Database Proxy'' in a high-availability architecture.', N'Senior', N'A database proxy acts as an intermediary that abstracts the physical topology of the database cluster from the application. It handles connection pooling, automatic failover, and read/write splitting, simplifying the application logic needed to interact with complex distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e11523ae-85a1-4e1d-a533-39435d5f209b', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Why might you choose to use ''adapter-static'' for a project?', N'Middle', N'The static adapter is best for projects that do not require server-side logic at runtime, such as documentation sites or blogs. It generates a purely static bundle that can be hosted on any simple CDN or file server, offering maximum performance and low costs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'516f72ac-fe43-4132-8a4e-3944e9185528', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js interact with existing server-side rendered (SSR) templates?', N'Senior', N'Alpine.js is designed to be ''sprinkled'' into existing SSR HTML, treating it as a live document rather than a template to be replaced. It reads the initial state from the DOM, allowing it to work seamlessly with frameworks like Laravel or Django by enhancing static pages with interactivity without requiring a complete rewrite of the frontend architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0db0d859-a044-4115-9bb6-39454952bc0b', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle asynchronous operations differently than Express?', N'Middle', N'Fastify is built from the ground up to support async/await patterns, allowing it to handle promises natively without requiring explicit next-function calls. This results in cleaner stack traces and more predictable error handling when an asynchronous operation fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0ee249e-736d-4b8c-909b-394591d06a70', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are Higher-Order Components in Preact?', N'Intern', N'A Higher-Order Component is a function that takes a component and returns a new component with added functionality. It is a pattern used for code reuse and cross-cutting concerns like logging or authentication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b23a5525-856d-4549-83ff-3947c9cbff5d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What does it mean to ''timebox'' a task, and when is it a useful strategy?', N'Junior', N'Timeboxing involves setting a strict limit on how much time you will spend on a specific problem before stopping to reassess. It is highly effective when you are stuck on a difficult issue, as it prevents ''rabbit-holing'' and forces you to seek help or pivot before losing too much time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4b6d3e3-4e7c-43d4-b59a-3948030d8545', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Explain the architectural trade-off of using Chi''s context vs. passing explicit parameters.', N'Senior', N'Using the request context provides a clean way to pass data down the middleware stack, but it relies on type assertions and key-based retrieval, which is less type-safe than passing explicit parameters. The trade-off is between clean, decoupled code and compile-time type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
