INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e24c76a3-949f-4a8a-baa0-394d2ae35900', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are the trade-offs between using FastAPI''s built-in validation versus manual validation?', N'Senior', N'Built-in validation via Pydantic is declarative, highly readable, and generates documentation automatically, reducing boilerplate. Manual validation offers more granular control over error handling and performance optimizations but increases code complexity, reduces maintainability, and breaks the automatic schema generation that makes FastAPI powerful.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02e48028-1f2d-417b-91ed-394e24e9fc20', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the difference between a Django Model and a Form?', N'Fresher', N'A Model defines the structure of your database tables and how data is stored. A Form is used to handle user input, providing validation, error reporting, and sanitization before the data is processed or saved to a Model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ffac9cd-28e8-46eb-bf70-394f418c6358', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Discuss the trade-offs of using ''dynamic'' versus ''Object?'' in modern Dart.', N'Senior', N'Object? is the top type that forces explicit type checking and casting, supporting sound null safety. Dynamic disables all static type checking, shifting the burden to runtime, which can lead to elusive crashes and prevents the compiler from performing effective optimizations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a40aabf-e49e-4fd3-ac44-395062d3a59b', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the benefits and drawbacks of using ActionCable for real-time features?', N'Senior', N'ActionCable facilitates bi-directional communication, but it consumes server resources significantly more than standard HTTP requests because each connection keeps a process or thread busy. It is best used for specific real-time requirements, while heavy traffic should be offloaded to dedicated infrastructure or external services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4fdd4b8-075c-4494-b22a-39507fd85300', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the Virtual DOM in the context of Preact?', N'Intern', N'The Virtual DOM is a lightweight representation of the actual DOM stored in memory. Preact uses this to compare changes between renders and update only the necessary parts of the real DOM, which improves efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c954d3da-40c5-4b29-9b00-39509f814840', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Discuss the performance trade-offs of using Redis with SSDs versus DRAM.', N'Senior', N'Redis is designed to be an in-memory store; using SSDs as a backing store introduces significant latency due to disk I/O, which negates the performance benefits of Redis. While some configurations allow offloading data to NVMe, the primary architecture assumes sub-millisecond access times only achievable through RAM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90be2795-9964-453d-9654-3950d5a53e76', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If you discover a potential risk while working on a project, what should you do?', N'Intern', N'I would immediately inform my supervisor or the project lead about the risk, providing as much detail as possible. It is better to flag a potential issue early so that the team can adjust the plan than to wait until the risk becomes an actual failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'341328bc-a83b-41f9-ab82-39568325d1c4', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the risks of ''undefined behavior'' in high-performance C++ code?', N'Senior', N'Undefined behavior allows the compiler to assume that such code paths are unreachable, potentially leading to aggressive optimizations that remove necessary checks or reorder instructions unexpectedly. This can result in security vulnerabilities, such as buffer overflows, or unpredictable logic errors that are notoriously difficult to debug in production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57896258-64b3-4b21-b4e5-39578c8043cd', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Are class components supported in Preact?', N'Fresher', N'Yes, Preact supports class components that extend the base Component class. While functional components are more common today, class components are fully supported for legacy code or specific use cases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7902fc0-17f6-4d2d-9b9a-395a0a76eb06', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are Svelte props and how are they used?', N'Intern', N'Props are a mechanism for passing data from a parent component to a child component. In Svelte, they are declared using a specific keyword that marks a variable as accessible from the outside, allowing the parent to provide information to the child.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab126afe-0bc6-43ba-a162-395a85ce89f7', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle errors?', N'Intern', N'Hono allows the definition of custom error handlers that catch exceptions thrown during the request lifecycle. This enables developers to return consistent error responses and log issues without crashing the entire process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'741fda9e-32ed-4bd0-b71a-395bc21fb37f', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When asked to explain a complex problem to a non-technical stakeholder, what is your strategy?', N'Intern', N'I would focus on the ''what'' and ''why'' rather than the ''how,'' using analogies to relate technical concepts to real-world scenarios. I would check for understanding frequently and avoid using jargon that might confuse the audience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a785632-d24c-47ff-b315-39608c716e29', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the role of ''Chaos Engineering'' in preventing production issues?', N'Middle', N'Chaos engineering involves intentionally injecting faults, such as service failures or latency, into a system to test its resilience. By doing this in a controlled manner, teams can identify weaknesses in their monitoring, alerting, and automated recovery processes before a real incident occurs. It turns theoretical troubleshooting into a proactive practice, ensuring the system is truly designed for failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16a09287-60da-42aa-8016-396ce796f2ac', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s Optional type handle null safety compared to other languages?', N'Middle', N'Swift uses a type-safe Optional enum to explicitly declare that a variable might lack a value, forcing developers to handle the ''none'' case. This moves null-pointer errors from runtime to compile-time, significantly increasing application stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c2a210c-d487-496f-b57b-396d1ed119c1', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How do you define a constant in Kotlin?', N'Junior', N'Constants are defined using the ''const val'' modifier at the top level or inside an object. They must be initialized with a primitive or string value at compile time, making them suitable for values that never change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9c7e511-5272-4de8-b575-396f0654557b', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux handle ''batching'' of updates, and why is this significant for performance?', N'Senior', N'Batching ensures that multiple actions dispatched in quick succession only trigger a single UI re-render cycle, preventing layout thrashing. Modern versions of React-Redux automatically handle this in many scenarios, but it remains a critical performance optimization to prevent redundant DOM updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbd3aa26-79fd-4e7f-aa0b-39723e420eed', N'4c000000-0000-0000-0000-000000000005', N'Compare ''Optimistic Locking'' versus ''Pessimistic Locking'' in high-concurrency environments.', N'Senior', N'Pessimistic locking prevents conflicts by locking resources before access, which reduces throughput in high-concurrency systems. Optimistic locking assumes conflicts are rare and verifies the version of a record at commit time, providing much higher performance at the cost of handling occasional retries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a5f52df-3143-4829-96f3-3972800fcaa0', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is a JSON Schema in the context of Fastify?', N'Intern', N'A JSON Schema is a declarative format used to describe the expected structure of JSON data. Fastify uses these definitions to automatically validate incoming data and ensure outgoing responses match the expected format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f21795a-46fa-453c-9af9-3979c0954398', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'In the context of the PACELC theorem, what does the ''ELC'' component represent?', N'Senior', N'PACELC extends the CAP theorem by stating that even when the system is operating normally (no partition), there is a fundamental trade-off between latency and consistency. If a system is consistent, it must sacrifice latency; otherwise, it can prioritize lower latency at the expense of consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f62c5a0-c869-4fa7-b886-397a452e4080', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the difference between a Set and a Sorted Set in Redis?', N'Intern', N'A Set is an unordered collection of unique elements. A Sorted Set is similar, but every member is associated with a score, which is used to keep the elements in a specific order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc5bea72-0f2e-49f0-bf48-397aa1d1097a', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Discuss the architectural strategy for managing background job failures to ensure system idempotency.', N'Senior', N'Idempotency is achieved by ensuring that retrying a job does not cause unintended side effects, often through database unique constraints or state-checking logic. Strategies include utilizing transactional outbox patterns to ensure the job and the preceding database change commit atomically, and implementing deterministic job identifiers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'913c6d09-952f-40e3-9074-397b0c7e79f9', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the role of the ''Event'' system in Micronaut?', N'Middle', N'Micronaut''s event system allows for loose coupling between components by allowing beans to publish and subscribe to application events. It is a synchronous mechanism by default, which ensures that event handling is predictable and easy to trace within the application lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'804098a5-dbf3-432c-a3c9-397b7c1bc7a5', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does the ''struct'' module facilitate communication between Python and low-level C data structures?', N'Senior', N'The ''struct'' module performs conversions between Python values and C structs represented as bytes. This is critical for reading binary data from files or network sockets, as it allows Python to pack and unpack data according to specific C-like memory layouts and endianness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
