INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4039678f-9b13-44c8-95f8-3980e02f0fca', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Compare the memory management characteristics of the Scavenger and Major Mark-Compact collectors in V8.', N'Senior', N'The Scavenger uses a semi-space copying algorithm for the young generation to quickly reclaim memory from short-lived objects. In contrast, the Major Mark-Compact collector handles the old generation by marking live objects and compacting memory to prevent fragmentation, which is a more computationally expensive process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fab9bd9d-10fc-4e4a-9625-398201013cb7', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does the ''final'' keyword affect class and method design?', N'Middle', N'The ''final'' keyword prevents a class from being extended or a method from being overridden. It is used to enforce strict design constraints, protect against unintended implementation changes, and improve security by ensuring specific logic remains constant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
