INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db959f3f-10dc-42b1-8646-398e7f316a30', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the role of the HTML ''rel=preload'' hint in resource prioritization?', N'Senior', N'Preload informs the browser that a specific resource is required for the current page and should be fetched with high priority before the parser encounters it. It is particularly effective for late-discovered resources like fonts or background images that are critical for the initial view.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56ea6725-0d56-4382-bf3a-39971f993e54', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your approach to identifying the root cause of a cascading failure in a distributed system?', N'Senior', N'Begin by analyzing logs and distributed traces to locate the point of initial latency or error. Investigate circuit breaker states and resource saturation metrics to understand how the failure propagated through dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9621c741-64a5-4953-b3a8-399ac97acce9', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How would you perform a blocking operation in an Actix-web handler without blocking the event loop?', N'Middle', N'You should use the ''web::block'' function, which moves the blocking operation to a dedicated thread pool managed by the runtime. This ensures the main event loop remains free to continue processing other incoming HTTP requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'209a3e16-3e7c-4775-becf-399eb93adc9d', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How do C++ modules improve the compilation model compared to legacy header files?', N'Senior', N'C++ modules replace the textual inclusion model of headers with a binary format that includes only the exported interface, preventing the redundant processing of code across translation units. This drastically reduces compilation times and eliminates issues related to macros or non-modular dependencies that frequently plague large-scale header-based projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62047ee6-6fe2-4d45-b19d-39a0e0bd9b13', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How do you register a service in Actix-web?', N'Fresher', N'You register a service using the ''service'' method on the App builder. This is often used to group related routes together under a common path prefix or to structure the application into modular components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
