INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a066bc85-5b06-4cb3-9284-39a17494278d', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What do you do if you finish your assigned tasks earlier than expected?', N'Junior', N'I would check the team backlog for smaller tasks or bugs I can pick up, or offer assistance to other team members who might be struggling. Alternatively, I would spend the time improving documentation or learning more about the technologies used in our stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
