INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09eb5370-074d-464a-b233-39a5bc9f5537', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Is Redis case-sensitive?', N'Fresher', N'Yes, Redis keys are case-sensitive. This means that ''User:1'' and ''user:1'' are treated as two distinct keys in the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a3e365e-64a4-4155-bde2-39a99aecaaa3', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the UseAuthorization and UseAuthentication middleware?', N'Junior', N'Authentication middleware identifies who the user is by validating credentials, while Authorization middleware determines if the identified user has permission to access a specific resource. These are distinct steps in securing an application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d87ab1e-bedc-4529-b367-39ab43acdb3e', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a ''buffered channel'' and how does it differ from an unbuffered one?', N'Junior', N'An unbuffered channel requires both the sender and receiver to be ready at the same time to transfer data. A buffered channel has a fixed capacity, allowing the sender to continue as long as the buffer is not full, which can help decouple producer and consumer speeds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a87c5c81-ef23-4fc8-999a-39ac00ab54a5', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of the ''clean-webpack-plugin'' or the ''clean'' option?', N'Junior', N'These tools are used to remove or clean up the output folder before each new build. This prevents old, unused files from accumulating in your distribution folder after you rename or remove files from your project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1a7bc85-708d-4207-879a-39ad4961085b', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How do components function in SolidJS?', N'Intern', N'Components in SolidJS are simple functions that run only once when they are initialized. They return the UI structure, and the reactivity system handles all future updates within that structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71ce6874-ed8c-49f8-ab36-39ae23c447c3', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is checked, unchecked exception and errors?', N'Intern', N'1. Checked Exception: * These are the classes that extend Throwable except RuntimeException and Error. * They are also known as compile time exceptions because they are checked at compile time, meaning the compiler forces us to either handle them with try/catch or indicate in the function signature that it throws them and forcing us to deal with them in the caller. * They are programmatically recoverable problems which are caused by unexpected conditions outside the control of the code (e.g. database down, file I/O error, wrong input, etc). Example: IOException, SQLException etc. output: After adding IOException output: 2. Unchecked Exception: * The classes that extend RuntimeException are known as unchecked exceptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec8e6e22-9689-40fc-82af-39ae437e6fb4', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS manage stateful vs. stateless authentication strategies within its middleware architecture?', N'Senior', N'AdonisJS provides a modular guard system that abstracts authentication logic, allowing the developer to switch between session-based and token-based strategies without changing the application logic. This abstraction ensures that security policies remain consistent regardless of the underlying transport mechanism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
