INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fd20929-d462-4994-8488-39aebf3bae77', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the ''target'' property in Webpack?', N'Fresher', N'The target property tells Webpack which environment the bundle is intended for, such as ''web'' for browsers or ''node'' for server-side environments. This ensures that Webpack uses the correct built-in modules and compatibility features for that environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8655e0a9-bb3e-4897-94f8-39b50dc77325', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What are the trade-offs of using opaque tokens versus JWTs in API authentication?', N'Senior', N'Opaque tokens are secure and easy to revoke but require a database lookup on every request, which can introduce latency. JWTs are self-contained and stateless, allowing for faster validation, but they are harder to revoke before expiration and can grow in size if they contain excessive claims.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5c304df-1a69-4b26-a6c8-39b7f152c826', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Explain the difference between vertical and horizontal partitioning in terms of scaling.', N'Senior', N'Vertical partitioning involves splitting a table by columns to isolate frequently accessed data, which helps reduce I/O but remains limited by the capacity of a single server. Horizontal partitioning splits rows across multiple servers, allowing the database to scale out indefinitely as the dataset grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f88fac9c-ce55-411b-abef-39baf641fbdf', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the difference between ''externals'' and ''alias'' in Webpack?', N'Middle', N'Externals allow you to prevent certain libraries from being bundled, instead expecting them to be available in the global scope, often used for CDN-hosted files. Aliases create shortcuts for specific file paths, making it easier to import files from deep folder structures without using relative path notation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7375ae1d-a4cb-4008-a91e-39bb29b1796a', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the advantage of using Remix over basic React?', N'Fresher', N'While React is a library for building user interfaces, Remix is a full framework that provides routing, data loading, and form handling. Remix manages the infrastructure so you can focus on building features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56918446-5a6d-45da-ad22-39beb42c3214', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is state mutation and how to prevent it?', N'Fresher', N'State mutation happens when you try to update the state of a component without actually using setState function. This can happen when you are trying to do some computations using a state variable and unknowingly save the result in the same state variable. This is the main reason why it is advised to return new instances of state variables from the reducers by using Object.assign({}, ...) or spread syntax. This can cause unknown issues in the UI as the value of the state variable got updated without telling React to check what all components were being affected from this update and it can cause UI bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f09097f3-a180-44af-b4a9-39bfabf78f66', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How do you handle exceptions in Micronaut?', N'Fresher', N'Micronaut provides ExceptionHandlers that allow you to define global logic for catching and responding to specific exceptions thrown within your application. This ensures consistent error responses are returned to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7e7964c-5419-42b8-91ce-39c3d193840a', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'When should you avoid using a NoSQL database?', N'Junior', N'You should avoid NoSQL when your application requires strong consistency, complex analytical joins, or when your data structure is highly rigid and predictable. In these cases, a traditional relational database is usually the better choice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61a2460c-3924-45fe-968b-39c5e49d452c', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What are the trade-offs of using an LRU (Least Recently Used) eviction policy compared to LFU (Least Frequently Used)?', N'Senior', N'LRU is efficient for workloads with temporal locality, prioritizing items accessed recently, but it can be polluted by periodic bulk scans. LFU prioritizes items accessed most often, making it better for static popularity distributions, but it struggles to adapt to changing access patterns unless aging mechanisms are implemented.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
