INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25652e79-dff5-489d-ab10-39c887cd480c', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle a situation where a project deadline is approaching, but a critical bug remains unresolved?', N'Fresher', N'I would immediately communicate the situation to the project manager or stakeholders, explaining the nature of the bug and the potential impact of delaying the launch. I would then suggest potential workarounds or a phased release strategy to ensure that the core functionality is stable for users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3807234f-afd0-4949-9b8f-39caa966be87', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are Pydantic models, and why are they important in FastAPI?', N'Intern', N'Pydantic models are used to define the structure and data types of request and response bodies. They are essential because they handle automatic data parsing, validation, and error reporting, ensuring that the input received by the server matches the expected format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a542a3b3-a244-437e-b319-39cbdb9901d7', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the impact of Axum''s ''Pin'' and ''Future'' usage on long-lived connections?', N'Senior', N'By using pinned futures, Axum enables efficient state management for long-lived connections like WebSockets. The framework handles the underlying polling mechanism, allowing developers to focus on the message-passing logic while the runtime ensures that memory usage remains predictable and stable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c49dc45d-4906-473e-b3bc-39cf7fc282d2', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Can you define multiple layers in an Axum router?', N'Junior', N'Yes, multiple layers can be added to an Axum router by chaining the layer method. The order in which these layers are added determines the order in which they process the request and response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6348e61-278a-4264-a2ce-39d0abcccbca', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Why is Astro considered SEO-friendly?', N'Intern', N'Astro is SEO-friendly because it delivers fully rendered HTML to the browser. Search engine crawlers can easily parse the content without needing to execute complex JavaScript, which helps improve search rankings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8094cc34-e57a-4f6d-897a-39d242eff331', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are stored properties in Swift?', N'Fresher', N'Stored properties are constants or variables that are stored as part of an instance of a class or structure. They hold specific values that belong to that instance and persist for its lifetime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91583bec-1873-4320-8cb0-39d3c645fb33', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS ensure that the application remains maintainable as it scales?', N'Middle', N'By emphasizing a service-oriented architecture, strict dependency injection, and a modular plugin system, AdonisJS forces developers to write decoupled and testable code. This modularity prevents the ''spaghetti code'' common in larger Node.js projects and makes it easier to replace components as requirements evolve.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b027d266-896b-4943-b444-39d890b86eb7', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Why is ''Domain-Driven Design'' (DDD) recommended when defining microservice boundaries?', N'Senior', N'DDD helps identify ''Bounded Contexts,'' which act as natural boundaries for services. Aligning microservices with business domains ensures that teams have clear ownership and that internal models remain cohesive, reducing cross-service chatter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dab67eb1-ace1-44ef-94d5-39dc363cbb92', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Describe the role of the ''CoroutineDispatcher'' in thread management.', N'Senior', N'A CoroutineDispatcher determines which thread or thread pool a coroutine executes on, decoupling the logic of the coroutine from its hardware execution context. This allows developers to easily switch between background I/O tasks and UI-bound tasks by simply changing the dispatcher, optimizing resource usage and preventing blocking of critical threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f87ff185-73d8-4fdc-8d54-39dc4d64de3f', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the ''N+1 Query Problem'' and how does it impact scaling?', N'Senior', N'The N+1 problem occurs when an application executes one query to fetch parent records and then N individual queries to fetch related child records. This causes excessive database round-trips, which can significantly degrade performance and prevent a system from scaling under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e3d827b-55d8-428e-9a4d-39def1a12fcd', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'Why should an intern document their findings while working on a new problem?', N'Intern', N'Documentation creates a knowledge record that prevents redundant work and helps in debugging later. It also forces the engineer to organize their thoughts logically, which often clarifies the path to the solution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
