INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9dd1931-6abd-4c9d-9108-39e1b8de0846', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the purpose of ''freeze'' in Ruby?', N'Middle', N'The ''freeze'' method prevents an object from being modified, making it immutable. This is useful for ensuring data integrity and can occasionally offer performance optimizations, as the interpreter knows the state of the object will not change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
