INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e24958a-37fa-4fb6-b094-39e83ed51a33', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the advantage of using an ''In-Memory'' NoSQL store?', N'Middle', N'In-memory NoSQL stores keep the entire dataset in RAM rather than on disk, providing sub-millisecond latency for read and write operations. They are ideal for high-throughput applications like real-time bidding, leaderboards, and caching layers where performance is the highest priority.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
