INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7081d72-dff9-4a5e-a578-39ea09c67246', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the ''Glimmer'' engine?', N'Fresher', N'Glimmer is the rendering engine used by Ember to efficiently update the DOM. It optimizes performance by calculating the minimal changes required when data updates, ensuring the application remains fast even as the UI grows more complex.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b6f4d70-b0c8-4ffc-8552-39ea29ee9fb2', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the architectural advantage of Svelte''s ''compile-time'' optimization for global state?', N'Senior', N'By knowing the usage of state at compile time, Svelte can generate highly efficient code to update only the specific UI fragments that depend on that state. This avoids unnecessary re-renders of the entire component tree and provides better performance than context-based state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'004f112c-1b5d-4683-94c2-39ebc3dd3d72', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle performance for large-scale applications compared to React?', N'Senior', N'React scales linearly with the size of the component tree due to hydration overhead, whereas Qwik scales independently of application size. Since Qwik only loads code for the specific components interacted with, the initial load performance remains constant regardless of the total complexity of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ccf2eb4-d1f3-4099-bbd5-39ec93120456', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the role of the master node in an Elasticsearch cluster?', N'Intern', N'The master node is responsible for cluster-wide management tasks, such as creating or deleting indices and tracking which nodes are part of the cluster. It ensures the cluster state remains consistent across all nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ded89baf-72a6-4b94-a432-39ef91833c86', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the primary architectural benefit of using Phoenix Channels for real-time features instead of standard HTTP polling or long-polling?', N'Senior', N'Phoenix Channels provide a persistent, stateful connection layer that facilitates full-duplex communication over WebSockets. This eliminates the latency and overhead of repeated HTTP handshakes, allowing the server to push updates to clients immediately upon state changes while maintaining a clean separation of concerns via pub/sub topics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96876432-4490-4e06-823a-39f048a3b836', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the difference between SQL and NoSQL in the context of Cassandra?', N'Fresher', N'SQL databases are typically relational and follow ACID properties, while Cassandra is a NoSQL database designed for high-volume, unstructured, or semi-structured data. Cassandra favors availability and partition tolerance over strict consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'488ebd16-2069-4f38-bacf-39f2ce573347', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why is it generally recommended to keep the ''use client'' directive as low as possible in the component tree?', N'Middle', N'Keeping ''use client'' low in the tree allows the majority of your application to remain as Server Components. This keeps the bundle size smaller and improves initial page load performance since client-side hydration is restricted to only the necessary interactive sub-trees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
