INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6da845a2-3b40-41e6-8684-39f4073f5b60', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What does ''minify'' mean in the context of Vite''s production build?', N'Junior', N'Minification is the process of removing unnecessary characters like whitespace, comments, and shorting variable names from code. Vite uses esbuild or Terser by default to shrink the size of your production bundles for faster loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd28803b-fba2-4a80-8b92-39f75dfbbef6', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the difference between ''select_related'' and ''prefetch_related''?', N'Junior', N'Select_related performs a SQL JOIN to fetch related data in a single query, while prefetch_related performs separate queries for each relationship and joins them in Python. They are both used to optimize database performance by reducing the number of queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9f1697a-3695-4f46-92fb-39f8fa0de56e', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of the abort() function in Flask?', N'Intern', N'The abort() function is used to stop the execution of a request handler and immediately return an HTTP error response to the client. It is commonly used for handling unauthorized access or missing resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47a10b5e-1358-4380-b10f-39fb51388a5a', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a static file in Flask?', N'Intern', N'Static files are assets like images, CSS stylesheets, and JavaScript files that are served to the browser as they are. Flask looks for these files in a directory named ''static'' by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c68b0e11-220d-4c7e-95ed-39fb86e761f5', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you approach a task that you have never done before?', N'Fresher', N'I would break the task into smaller, manageable components and research the requirements for each part. I would also seek guidance from senior team members or available internal resources to ensure I am following the correct procedures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d441211-4134-4f15-9adb-39fbc7de7321', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the maximum document size in MongoDB?', N'Fresher', N'The maximum size for a single BSON document in MongoDB is 16 megabytes. This limit ensures that individual documents do not use excessive amounts of memory or bandwidth during operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'877a44ee-4509-4c39-8b53-39fc7baf606c', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do you handle vendor prefixing in modern Sass projects?', N'Middle', N'While Sass can generate prefixes using mixins, it is generally considered better practice to write standard CSS and use an automated tool like Autoprefixer. This offloads the maintenance burden of tracking browser support to a PostCSS plugin rather than relying on manual mixins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'463ad91d-0ba4-4d7d-8651-39fc89399558', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Are Axum handlers thread-safe?', N'Fresher', N'Yes, Axum handlers are designed to be thread-safe. Since Axum runs on a multi-threaded Tokio runtime, handlers must be able to execute concurrently, and shared state must be protected by thread-safe primitives like Arc or Mutex.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e5d01be-a447-4ac0-9a6a-39fd259bf794', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does data flow in Ember components?', N'Junior', N'Data flows into components via arguments passed from the parent template, following the ''data down, actions up'' pattern. If a component needs to change data, it triggers an action that sends a message back to the parent to update the state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5ed36f1-0b4c-4762-adce-3a0072503e80', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify differ from Express in terms of performance?', N'Fresher', N'Fastify is architected for high performance and is significantly faster than Express due to its efficient routing and schema-based validation. While Express is flexible and widely used, Fastify is built to minimize overhead, making it a better choice for high-throughput applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22b10298-0938-42a8-8c13-3a01abb0b610', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle navigation between pages?', N'Fresher', N'Qwik handles navigation by fetching only the necessary chunks for the new route. Because of its resumable nature, it can efficiently update the DOM without needing to re-hydrate the entire page structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27b66fda-49fb-42e6-a17b-3a036e7b384d', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is a ''context'' in a Fastify route?', N'Fresher', N'The context in a Fastify route contains the configuration, decorators, and settings inherited from the plugin hierarchy. It provides the environment in which the route handler executes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b34e78f8-a952-40c7-a65d-3a05247173be', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the ''API Composition'' pattern in microservices?', N'Senior', N'API Composition involves a service or gateway fetching data from multiple downstream microservices and aggregating it into a single response. It is a simpler alternative to implementing distributed joins, though it increases the latency of the aggregator service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a505cd56-cb87-46cc-8372-3a056c8f141d', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How would you implement a distributed task queue with Flask to handle long-running operations?', N'Senior', N'For long-running tasks, you should offload the work to a task queue like Celery using a message broker like Redis or RabbitMQ. This prevents the Flask worker from blocking, allowing it to return a response immediately while the background worker processes the task asynchronously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a033a71-9d54-4805-a547-3a08328bfe7d', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Why is the AdonisJS approach to ''error handling'' via centralized exception handlers preferred for distributed systems?', N'Senior', N'Centralized exception handlers catch and normalize all application errors, ensuring that the API returns consistent, masked responses to the client while logging detailed stack traces internally. This prevents information leakage that could assist attackers and ensures that monitoring systems receive consistent error formats for alerting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4219f38c-3bec-4e48-ad1c-3a09b511d5cb', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of a database ''buffer pool'' and how does it affect cache hit ratios?', N'Senior', N'The buffer pool is a dedicated area of memory that caches frequently accessed data pages from disk to minimize slow physical I/O. A higher cache hit ratio significantly boosts performance, making buffer pool sizing and eviction policy tuning critical for optimizing database throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59b70159-bae6-4158-9c91-3a0a386ad265', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the constraints of running Redis in a Docker container regarding persistence?', N'Senior', N'When running in containers, persistence files must be mapped to external persistent volumes, as data is lost when a container is removed. Additionally, resource limits must be strictly enforced via cgroups to prevent a Redis container from consuming host memory and affecting other services on the same node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90ca5270-c637-4af8-bf00-3a0e83dff824', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the role of the ''Flask-Migrate'' extension, and why is it preferred over raw database scripts?', N'Middle', N'Flask-Migrate manages database schema changes incrementally by tracking versions of your model definitions. It is preferred because it automates the creation of migration scripts, ensures database schema consistency across different environments, and allows for easy rollbacks if a deployment goes wrong.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'610024ac-17fe-44e2-85e3-3a0ec90257ba', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is replication in a NoSQL database?', N'Fresher', N'Replication involves copying data across multiple nodes to ensure high availability and data redundancy. If one node fails, the system can continue to serve data from the remaining replicas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b1014ab-ca7c-49ea-8a35-3a0ef9516714', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Hot Module Replacement (HMR) function in Vite compared to Webpack?', N'Senior', N'Vite performs HMR over native ESM, meaning it only replaces the specific module that changed and its direct importers. Because the browser handles the ESM graph, Vite simply invalidates the module and triggers a re-fetch, leading to constant HMR times regardless of the application size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cc9caee-a2bc-4f0d-a25e-3a10ae178ff3', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack create a dependency graph?', N'Fresher', N'Webpack starts at an entry point defined in its configuration. It recursively traverses every dependency found in the code, such as import or require statements, to build a complete graph of all the modules the project needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd79331dd-da84-4aa1-9b81-3a10cc0ac2d9', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the function of the inverted index in Elasticsearch?', N'Middle', N'The inverted index is the core data structure that maps unique terms to the list of documents containing them. This allows the engine to perform high-speed full-text searches by looking up terms directly rather than scanning every document in the index.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0278e7d-32a3-471c-8b75-3a131bfc7112', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How Garbage collector algorithm works?', N'Fresher', N'Garbage collection works on Mark and Sweep algorithm. In Mark phase it detects all the unreachable objects and Sweep phase it reclaim the heap space used by the garbage objects and make the space available again to the program. There are methods like System.gc() and Runtime.gc() which is used to send request of Garbage collection to JVM but it''s not guaranteed that garbage collection will happen. If there is no memory space for creating a new object in Heap Java Virtual Machine throws OutOfMemoryError or java.lang.OutOfMemoryError heap space', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e952bfb-ec35-4a89-9453-3a13a04b5adc', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the advantage of Qwik''s event delegation?', N'Junior', N'Qwik uses global event delegation to listen for user interactions. By attaching a single listener to the document, it can efficiently manage events for the entire page, reducing the memory overhead of attaching individual listeners to every element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f20e857-5ce1-4ac2-86aa-3a13a21d96ac', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the purpose of the ''preValidation'' hook in the Fastify lifecycle?', N'Middle', N'The preValidation hook executes before the request body, query, or params are validated against the defined schema. It is the ideal place to perform authentication or pre-processing tasks that might influence whether the request is valid.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce74ecc3-c43b-4a51-ae0b-3a144fb080ce', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does the Rails ''Strong Parameters'' pattern enhance security compared to mass assignment?', N'Senior', N'Strong Parameters enforce an explicit whitelist of permitted attributes, preventing malicious users from injecting unauthorized parameters to modify sensitive fields. This acts as a critical security layer against mass assignment vulnerabilities that could lead to privilege escalation or data corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b8e2c7f-2b9a-4bc3-99b4-3a18fce14195', N'4c000000-0000-0000-0000-000000000005', N'What are the trade-offs of using a cache in a system?', N'Middle', N'Caching drastically improves read performance and reduces load on the primary database by serving frequent requests from memory. However, it introduces the challenge of cache invalidation, where you must ensure the data in the cache remains synchronized with the source of truth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74243c08-4c9c-422c-b160-3a1981cd2392', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What do you do if you realize you made a mistake that affected production?', N'Junior', N'I immediately inform my manager and the relevant team members, taking full responsibility for the mistake. I focus on quickly rolling back the change or applying a hotfix to stabilize the system, and later I participate in a post-mortem to identify how we can prevent the same issue from recurring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0bf8f4e-bbd9-4a87-8265-3a19a5a22f60', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite''s proxy configuration work?', N'Middle', N'The server.proxy setting in Vite allows developers to redirect API requests from the development server to a backend server. This is a common solution to bypass CORS issues during local development by proxying requests through the local dev server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79df38b5-bbfc-4b44-9c7b-3a1a2e729a6c', N'4c000000-0000-0000-0000-000000000005', N'Discuss the trade-offs of using a centralized logging system versus distributed tracing.', N'Senior', N'Centralized logging provides a comprehensive history of events across the system, useful for auditing and debugging specific service errors. Distributed tracing maps the end-to-end flow of requests across multiple services, which is superior for identifying latency bottlenecks in complex microservice interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1626afed-0f30-446c-a1c0-3a1c07639d31', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What happens if you dispatch an action that no reducer handles?', N'Junior', N'If an action type is not handled by any reducer, the state will simply return the current state unchanged. The application will continue to function normally, but the state will not update in response to that specific action.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2170d8f1-3d30-4f41-b8cc-3a1e572ee48a', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you handle schema evolution in an event-driven API architecture?', N'Senior', N'Schema evolution should be managed using a schema registry that enforces backward and forward compatibility rules. Clients should be designed to ignore unknown fields, and producers must ensure that changes to message formats do not break existing consumers who rely on older versions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93499502-870f-43f8-a52c-3a2019a31e06', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How can you leverage Flask''s CLI integration for operational tasks?', N'Senior', N'Flask''s CLI allows you to define custom commands using the Click library, which can be used for administrative tasks like database migrations, seeding data, or checking system health. This allows for a unified interface that runs within the context of the application without needing a separate management script.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06d9d23a-4b6f-400f-a269-3a2249aeb3f5', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is Kotlin and why was it developed?', N'Fresher', N'Kotlin is a statically-typed, cross-platform programming language designed to be fully interoperable with Java. It was developed to address common shortcomings in Java, such as verbosity and null pointer exceptions, while running on the Java Virtual Machine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d4dec4b-4679-4eae-84d3-3a229da468e4', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Explain the role of the Options pattern in ASP.NET Core configuration.', N'Middle', N'The Options pattern uses strongly-typed classes to represent groups of related configuration settings. It promotes better maintainability and testability by allowing you to inject configuration sections directly into services instead of passing around raw configuration strings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a56c34b-8eb8-4a71-8121-3a286941ae00', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What should you do if your fix introduces a regression in another part of the system?', N'Junior', N'I would immediately revert the changes to restore the system to a stable state for users. After the system is stable, I would analyze why the regression occurred, improve my test coverage, and then re-implement the fix with greater caution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'319e3426-a515-4ebd-acf0-3a2886271d36', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is V8 JavaScript engine', N'Intern', N'V8 is an open source high-performance JavaScript engine used by the Google Chrome browser, written in C++. It is also being used in the node.js project. It implements ECMAScript and WebAssembly, and runs on Windows 7 or later, macOS 10.12+, and Linux systems that use x64, IA-32, ARM, or MIPS processors. Note: It can run standalone, or can be embedded into any C++ application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a995ceca-f242-4ed2-b934-3a2a6eaf7843', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of the ''die'' function?', N'Intern', N'The die function outputs a message and terminates the current script immediately. It is commonly used for error handling when a prerequisite action, such as a database connection, fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'009fbf60-4096-4df1-b62e-3a2db5e904a0', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How can Gin''s middleware execution order impact security implementation?', N'Senior', N'Middleware executes in the order it is registered; therefore, security-critical middleware like CORS, rate limiting, or authentication must be registered before the router or business logic. Incorrect ordering can allow unauthorized requests to bypass security checks or expose sensitive endpoints prematurely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce7011f6-458c-4eaf-a8b5-3a2dda1ba6a3', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing a system, why is choosing between strong consistency and high availability a critical trade-off?', N'Middle', N'According to the CAP theorem, a distributed system cannot simultaneously provide both strong consistency and high availability during a network partition. Choosing strong consistency ensures all nodes see the same data but increases latency and risks unavailability if nodes cannot synchronize, while choosing availability keeps the system responsive but risks serving stale data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7b8772c-99a4-4c4c-88bb-3a2faab2c4eb', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Describe the difference between ''Debouncing'' and ''Throttling'' and identify when to use each for performance optimization.', N'Senior', N'Debouncing ensures a function runs only after a period of inactivity, which is ideal for search inputs. Throttling ensures a function runs at most once in a specified interval, which is best for continuous events like window resizing or scroll tracking to limit the execution frequency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea9bb8c4-01f3-4f46-8110-3a30de7991c6', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the role of ''Managed State'' in Rocket?', N'Intern', N'Managed state allows you to share data across different parts of your application, such as a database connection pool. You register this state at launch, and Rocket makes it available to any handler that requests it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63839395-5d17-4eec-ba4e-3a30e6bd17da', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How do you access data from outside a component?', N'Junior', N'Generally, Alpine components are scoped to their own x-data. To share data globally, you can use Alpine''s store feature, which allows you to define reactive state that can be accessed from any component on the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd49f6ace-0e35-479e-97b0-3a3167edcc16', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the role of the ''tokio'' runtime in an Axum application?', N'Junior', N'Tokio is the asynchronous runtime that powers Axum. It handles the underlying event loop, scheduling asynchronous tasks, and managing I/O operations, which allows Axum to handle many concurrent connections efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c14be969-fe88-4c0e-9f75-3a3179d94bf9', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What does it mean for Fastify to be schema-based?', N'Intern', N'Fastify uses JSON Schema to validate incoming requests and serialize outgoing responses. This ensures data integrity and improves performance by avoiding expensive manual validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9989b241-765a-4d8e-836f-3a327819ff04', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why should you seek feedback on your reasoning process rather than just the final answer?', N'Intern', N'Focusing on the reasoning process helps identify flaws in logic that might lead to errors in future tasks. By sharing the ''how'' and ''why,'' you allow others to critique your methodology, which builds more robust problem-solving skills over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e359cbfa-12b6-47ab-ab92-3a3425e078e0', N'a2838158-7305-480a-b22b-4dc35776b400', N'Compare ''Push'' vs ''Pull'' based monitoring architectures.', N'Senior', N'In a push model, services send metrics to a central collector, which is easier to scale for dynamic ephemeral instances but can overwhelm the collector during traffic spikes. In a pull model, the collector scrapes metrics from targets, which simplifies service discovery and gives the collector control over the load. Pull models are generally more robust but require the collector to know the addresses of all targets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'729a1e68-1cd1-4a84-b772-3a35c50d3652', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why might you favor a flat database schema over a highly normalized one?', N'Junior', N'A normalized schema reduces data redundancy and prevents update anomalies, making it ideal for transaction-heavy systems. A flatter, denormalized schema can be faster for read-heavy applications since it reduces the need for complex joins, though it requires more effort to keep data synchronized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95c28ffb-a8c6-4934-b6dc-3a3625cfc932', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the concept of ''closures'' in R and their role in state preservation.', N'Senior', N'Closures are functions that capture the environment in which they were created, allowing them to access variables from that parent scope even after the parent function has finished execution. This enables the creation of stateful functions that maintain persistent data without requiring global variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d973ed4-2039-40e4-9013-3a39a1356e9f', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the role of the WHERE clause?', N'Intern', N'The WHERE clause is used to filter records in a query. It specifies the criteria that rows must meet to be included in the result set returned by the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbf48aaf-0324-4a9d-967a-3a3a3ccdf570', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What are the performance implications of ''Head-of-Line Blocking'' in HTTP/1.1 versus HTTP/2?', N'Senior', N'In HTTP/1.1, multiple requests sent over a single TCP connection must be processed sequentially, causing a slow request to block subsequent ones. HTTP/2 introduces multiplexing, allowing multiple streams of data to be sent concurrently over one connection, which eliminates application-level head-of-line blocking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b932489a-0aa9-4a79-910b-3a3ce2f20b68', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Why is the ''handleFetch'' hook critical for micro-frontend or multi-service architectures?', N'Senior', N'It allows developers to intercept internal fetch requests made by the server. This is essential for forwarding authentication headers, modifying request URLs for internal service discovery, or adding logging for cross-service communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73fcdcbd-65e5-431c-a425-3a3d076853d3', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite optimize CSS for production builds?', N'Middle', N'Vite automatically extracts CSS from components into separate files to prevent layout shift and improve loading performance. It also handles PostCSS processing and minification automatically, ensuring the output is optimized for production delivery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24d52ce0-01d7-4bf5-b7f5-3a3f6254bfd8', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the purpose of the ''use client'' directive in Next.js?', N'Junior', N'The ''use client'' directive is used to mark a component as a Client Component. It tells Next.js that this part of the application requires browser-only features, such as event listeners, state management, or browser APIs, which cannot run on the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1fd443f-c58d-4834-b880-3a4154f8700e', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'In a micro-frontend architecture, what are the dangers of sharing a single instance of jQuery?', N'Senior', N'Sharing a single jQuery instance creates tight coupling between disparate micro-frontends, where one team''s plugin or modification can break another team''s functionality. This lack of isolation prevents teams from upgrading dependencies independently and violates the principle of architectural autonomy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa55908b-9ab1-479c-a4f0-3a43423373fd', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Describe the architecture of a distributed log compared to a traditional message queue.', N'Senior', N'A distributed log is an append-only, immutable sequence of records that allows multiple consumers to read at their own offsets independently. In contrast, traditional message queues often act as temporary buffers that delete messages once acknowledged, focusing on task distribution rather than event replayability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e60e4d3-50fd-4528-b01b-3a44cef51e2c', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the primary difference between a static library and a dynamic library in C?', N'Middle', N'A static library is linked into the executable at compile time, creating a standalone file. A dynamic library is linked at runtime, allowing multiple programs to share the same library code in memory and reducing the final binary size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9da3d5c1-b7c7-4e36-8f71-3a4750118187', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of the ''application context'' in Spring?', N'Intern', N'The application context acts as the central container that holds all the beans and their configuration. It is the interface that provides the infrastructure for managing beans, resolving resources, and handling events in a Spring application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68e7a225-0956-4adb-95a8-3a4775611269', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the primary difference between ''Vertical'' and ''Horizontal'' scaling?', N'Senior', N'Vertical scaling involves increasing the resources of a single server, such as CPU or RAM, which has a hard ceiling but is simpler to manage. Horizontal scaling involves adding more servers to the pool, which provides theoretically limitless scale but introduces significant complexity in distributed management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66de515f-dff3-4719-862b-3a48110d89cf', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain join() and split() in Python?', N'Fresher', N'.join([]) It takes any iterables into this method. Join method is used to concatenate the elements of any list. join() lets us join characters from a string together by a character we specify. ''1,2,3,4,5'' split() lets us split a string around the character we specify. [''1'', ''2'', ''3'', ''4'', ''5'']', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25bc8e15-6795-44c2-84ac-3a48821039dd', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do Svelte stores handle memory management compared to React''s context API?', N'Middle', N'Svelte stores are simple objects that support subscription patterns, allowing components to subscribe and unsubscribe easily using the auto-subscription syntax. This approach avoids the potential performance overhead of re-rendering an entire tree that can occur with React''s Context API if not managed with memoization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1eb9dbc-0402-431c-9a6b-3a498d959853', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between IConfiguration and IOptions?', N'Junior', N'IConfiguration provides access to raw configuration settings from various sources like JSON files or environment variables. IOptions is a strongly-typed pattern that allows you to bind configuration sections to POCO classes, providing better type safety and cleaner access throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'687a2160-f861-4789-8014-3a4a59f964ba', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Does Remix support CSS?', N'Fresher', N'Yes, Remix supports various styling approaches including standard CSS files, CSS modules, and Tailwind CSS. You can link stylesheets directly within your route modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5910bd16-39e5-4d4f-8e8c-3a4d184b4eac', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the concept of RAII (Resource Acquisition Is Initialization).', N'Middle', N'RAII binds the lifecycle of a resource, such as memory or a file handle, to the lifetime of an object. When the object is constructed, the resource is acquired, and when the object is destroyed, the destructor automatically releases the resource, preventing leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d23c73d-abb2-4320-95fc-3a568c543085', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you use mixins in CLI?', N'Fresher', N'Using Vue CLI, mixins can be specified anywhere in the project folder but preferably within /src/mixins for ease of access. Once these mixins are created in a .js file and exposed with the export keyword, they can be imported in any component with the import keyword and their file paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baa0a026-627b-4c4e-9d0c-3a58a2bfa0ab', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the purpose of the ''SmallRye'' project in Quarkus?', N'Fresher', N'SmallRye is an umbrella project that provides implementations for various MicroProfile specifications. It is the core engine behind many Quarkus features, such as fault tolerance, metrics, and reactive messaging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdab36bc-669c-4d58-a8e4-3a58e1ebefe0', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the function of the C ''restrict'' keyword?', N'Middle', N'The ''restrict'' keyword is a hint to the compiler that a pointer is the sole means of accessing the memory block it points to. This allows the compiler to perform aggressive optimizations, such as reordering instructions, because it can assume no other pointer will modify that memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
