INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c52f4537-9e4c-4c5e-9db7-3a5fce9f6116', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the role of Chi''s ''context'' in terms of dependency injection?', N'Senior', N'Chi uses the request context to carry scoped data, which can serve as a lightweight dependency injection container. This allows middleware to inject database handles, loggers, or user sessions directly into the request flow, making those dependencies available to subsequent handlers without global variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9dd17640-db55-4399-9731-3a61a8630abc', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does MySQL manage memory for sorting operations?', N'Middle', N'MySQL uses a buffer called ''sort_buffer_size'' to perform memory-based sorting for ORDER BY and GROUP BY operations. If the result set is larger than this buffer, MySQL writes the data to temporary files on disk, which is significantly slower.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd419d24-bb84-42ca-abbd-3a620e15554b', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between prioritizing performance versus development speed?', N'Intern', N'You evaluate the business goal and the project stage. If the priority is getting a functional product to market quickly for feedback, speed is favored; if the goal is long-term scalability or high reliability, performance is prioritized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52d75948-d393-4628-84df-3a6406bb5b33', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What are the trade-offs of using Astro''s static site generation versus server-side rendering?', N'Middle', N'Static Site Generation offers the best performance and security by pre-rendering pages at build time, but requires a full site rebuild for content updates. Server-side rendering provides dynamic, real-time content but increases server load and response latency per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d991549-8f91-4a1f-9e7b-3a683fc134bb', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle TypeScript compilation?', N'Middle', N'Vite uses esbuild to transpile TypeScript by stripping type annotations and converting them to JavaScript. It does not perform full type checking during the build, which keeps the process fast, relying instead on the IDE or a separate build step for type validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
