INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'622e5536-d791-48b9-bc09-3a6a342122ae', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''as const'' assertion used for?', N'Junior', N'The ''as const'' assertion tells the compiler to treat an expression as a literal and read-only. This prevents TypeScript from widening types, such as turning a string literal into a general string type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aba07042-239f-41c4-b44f-3a6a34a95f5d', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Describe how Dart''s AOT compiler optimizes polymorphic method calls.', N'Senior', N'The compiler uses devirtualization techniques and inline caching to optimize polymorphic calls by predicting the concrete type of an object. When the compiler can guarantee a type at a call site, it replaces the virtual method lookup with a direct call, significantly reducing execution latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b1e5327-b9d0-4f8c-bafd-3a70c7fb3353', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What are Request Validation classes?', N'Fresher', N'Form Request validation classes are dedicated classes that contain validation logic for incoming HTTP requests. They allow you to keep your controller logic clean by separating the validation rules and error messaging into a reusable class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5e54b80-2adf-4f51-929d-3a7155466f5d', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Explain the difference between RDB and AOF in terms of recovery speed and data safety.', N'Middle', N'RDB allows for faster restarts because it loads a compact snapshot file directly into memory, but it carries a higher risk of data loss between snapshots. AOF provides superior data safety by logging every write, but it is generally slower to recover because the system must replay the entire log to reconstruct the state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7f0b589-4439-45bc-a1c5-3a716698824c', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Explain the performance trade-offs of using Astro''s ''client:*'' hydration directives.', N'Senior', N'Directives like ''client:load'' hydrate immediately, while ''client:idle'' or ''client:visible'' delay hydration until the browser is less busy or the component enters the viewport. This allows developers to prioritize critical interaction over non-essential functionality, effectively managing the main thread''s workload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a0557c5-bcb1-47e3-8159-3a7380478fd7', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why might you prefer ''Write-Around'' caching for certain workloads?', N'Senior', N'Write-Around bypasses the cache for write operations, writing directly to the database. This is beneficial for workloads that involve high-volume writes for data that is rarely read again, as it prevents the cache from being filled with ''one-hit-wonder'' data that displaces useful cache entries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a33f0c4-7a72-4a77-981f-3a74006bf55e', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the purpose of the @if and @else directives in Sass?', N'Fresher', N'These directives allow you to write conditional logic within your stylesheets. They enable you to apply different sets of styles based on specific criteria or variables, providing a more dynamic approach to styling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75423c15-4512-4875-a30d-3a78b5b38acc', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are the scalability implications of using the AdonisJS event emitter in a distributed system?', N'Senior', N'The default AdonisJS event emitter is synchronous and in-process, which can become a bottleneck or a point of failure if events involve long-running tasks. In distributed systems, this should be offloaded to an external message broker to ensure reliability and horizontal scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b87709c-a042-4ad5-85f0-3a7a1660f3cc', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why is Svelte considered ''more web-standard'' compared to other frameworks?', N'Senior', N'Svelte avoids custom abstractions for things like logic flows or event handling, favoring standard JavaScript and HTML syntax where possible. By compiling down to standard DOM APIs, it creates code that is easier to debug and more resilient to changes in the web platform''s evolution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6845690a-042b-41c6-ab82-3a7ee82894fc', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is ''Incremental Static Regeneration'' (ISR) in Nuxt?', N'Middle', N'ISR allows you to generate static pages at build time and then update those pages in the background as requests come in, without needing a full site rebuild. This provides the performance benefits of static sites with the flexibility of dynamic content updates for large-scale applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b4259b2-2acb-44dc-aecb-3a81ad150621', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of the ''SECRET_KEY'' in Flask, and what are the consequences of setting it incorrectly?', N'Middle', N'The ''SECRET_KEY'' is used to cryptographically sign session cookies and other security-sensitive data. If it is guessed or hardcoded in a public repository, an attacker could forge session tokens, leading to session hijacking and potential account takeover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9de3c6ed-1d91-4e9f-927a-3a823ccb4f35', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is a Container Image extension in Quarkus?', N'Fresher', N'These extensions automate the process of building and pushing a Docker or Podman image of the application. It simplifies the deployment workflow by integrating containerization directly into the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11ffa13d-9878-4c27-ac7c-3a82cb9a70a9', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If a feature takes much longer to build than you originally estimated, what should you do?', N'Junior', N'I would communicate the delay to my team lead as soon as I identify the bottleneck. Providing an updated estimate based on the current challenges helps the team adjust project expectations or shift resources to meet deadlines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7caab8bc-cfad-4811-8c8f-3a8416512b18', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does the autoloader pattern contribute to the performance and scalability of modern PHP frameworks?', N'Senior', N'Modern autoloading utilizes the SPL autoloader or PSR-4 standards to load class files only when they are requested, rather than including them all upfront. This drastically reduces initial memory footprint and startup time, allowing frameworks to scale across thousands of classes without performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f8c033a-a634-41c4-b40f-3a85751a2821', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do browser rendering engines handle CSS selector matching, and why does the right-to-left evaluation strategy matter for performance?', N'Senior', N'Browsers evaluate selectors from the rightmost key selector to the left to prune the DOM tree efficiently. By starting with the most specific element, the engine avoids traversing branches of the DOM that do not match, significantly reducing the computational cost of style recalculation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91e8cf1b-9737-4cb2-87cf-3a87056b75a1', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Explain the difference between app.use() and app.get() in Express.', N'Middle', N'app.use() is a general-purpose method that mounts middleware for any HTTP method, often used for global logic like logging or parsing. app.get() is specific to HTTP GET requests and is typically used for defining route-specific handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94d646f3-404b-4800-83c6-3a8e6b41abb4', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte manage component lifecycle transitions without a virtual DOM?', N'Senior', N'Svelte uses internal lifecycle hooks that are invoked by the compiled component code itself. Because the framework knows exactly which DOM nodes belong to a component, it can trigger transition animations and cleanup routines directly on the DOM elements without needing to compare previous and current virtual representations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b33fb01-9738-4b5f-aa8a-3a8f0d08dd6d', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Explain the relationship between shards, indices, and heap memory allocation.', N'Senior', N'Every shard maintains its own metadata, segment information, and caches in the JVM heap, leading to linear memory growth as shard counts increase. Too many shards or indices can lead to heap fragmentation and excessive garbage collection, effectively limiting the cluster''s ability to handle large data volumes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31b24770-1c9f-4499-b895-3a90afbcee33', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is an object in Java?', N'Intern', N'An object is an instance of a class that represents a specific entity with its own state and behavior. While a class is the template, the object is the actual entity created in memory based on that template.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d5927df-cbda-4c42-bec8-3a936e7922ba', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Describe the implications of ''strictFunctionTypes'' and why it mandates bivariance for function parameters.', N'Senior', N'With strictFunctionTypes enabled, TypeScript enforces contravariant parameter checking, which is the mathematically sound way to handle function subtyping. Bivariance is a compromise that allows for flexibility in event handlers and callbacks, but disabling it prevents common runtime errors where a function is called with a narrower type than expected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'447e998e-253e-4bd7-8d58-3a94b3fa9499', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Describe the difference between pessimistic and optimistic concurrency control.', N'Senior', N'Pessimistic concurrency control prevents conflicts by locking resources before modifying them, which is suitable for high-contention environments but reduces throughput. Optimistic concurrency control assumes conflicts are rare and only checks for them at commit time, which performs better under low contention but requires application-level handling for transaction retries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cff3683f-f24d-4bb2-a58f-3a95eb666b2a', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why might a senior developer choose to avoid ''namespaces'' in favor of modern ES modules?', N'Senior', N'Namespaces are a legacy feature designed to handle code organization before standard modules existed, and they often conflict with modern bundler optimizations like tree-shaking. ES modules provide a standard, performant way to manage dependencies and scope that integrates better with modern build tooling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7818da7-8fbd-4656-88a8-3a9670009a02', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the primary difference between Client-Side Rendering and Server-Side Rendering in Next.js?', N'Intern', N'Client-Side Rendering generates content in the user''s browser using JavaScript, which can lead to slower initial page loads. Server-Side Rendering generates the HTML on the server for every request, which improves initial load performance and search engine optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4df46583-667e-4efb-9d13-3a9b9c309bbd', N'954a0331-deff-4399-b588-96f39fec001d', N'What is a routed entry component?', N'Intern', N'The components referenced in router configuration are called as routed entry components. This routed entry component defined in a route definition as below, Since router definition requires you to add the component in two places (router and entryComponents), these components are always entry components. Note: The compilers are smart enough to recognize a router definition and automatically add the router component into entryComponents.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8e462b2-e245-46fb-ac1c-3a9e136634a2', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does HTML5''s ''autofocus'' attribute interact with user experience and accessibility?', N'Senior', N'The ''autofocus'' attribute can improve efficiency for specific workflows, such as search bars or login forms. However, it can disorient users who rely on screen readers if it moves focus unexpectedly, and it is generally discouraged unless it is the primary and expected action of the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04a0e9b5-ac7a-4752-8249-3a9ec2d37701', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is declaration merging and in what scenarios is it useful?', N'Middle', N'Declaration merging occurs when the compiler automatically merges multiple declarations with the same name into a single definition. It is most useful when augmenting third-party libraries or adding properties to the global window object without modifying the original source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f4fd177-353c-495d-a6e2-3aa1fb26b586', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the ''context'' property in Webpack?', N'Intern', N'The context is the base directory for resolving entry points and loaders from the configuration. By default, it is the current directory, but it can be set to ensure consistent file resolution regardless of where the build command is executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc24e1c4-4fc3-4216-8caa-3aa6e9b5bf6d', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What does ''method_missing'' do?', N'Junior', N'The method_missing method is a hook that Ruby calls when you try to invoke a method that does not exist on an object. You can override it to provide dynamic behavior, such as creating methods on the fly or logging errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7bd1707-d066-4fe2-84cb-3aa9589bda1f', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the role of the frontmatter in an Astro file?', N'Fresher', N'Frontmatter is the code block at the top of an Astro file delimited by triple dashes. It allows you to define variables, import components, and set page metadata that will be used in the template section.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3af4923-8bd3-4f79-9537-3aad2f4389f3', N'a2838158-7305-480a-b22b-4dc35776b400', N'How do vector clocks differ from physical timestamps in ordering events?', N'Senior', N'Physical timestamps are unreliable due to clock skew across distributed machines, making it impossible to establish a strict causal order. Vector clocks track logical dependencies between nodes, allowing the system to detect causality and resolve conflicts by identifying concurrent updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b759c3aa-c16d-420f-b8d5-3aadc0a4b15e', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle path parameter extraction for dynamic route segments?', N'Senior', N'Axum extracts path parameters using the ''Path'' extractor, which utilizes Serde to deserialize segments directly into a struct or tuple. This method is type-safe and automatically returns a 400 Bad Request error if the dynamic segments cannot be parsed into the target type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68ca1160-4e56-4a90-9fdb-3ab08ff7f1a2', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the benefit of Hono''s ''RPC'' mode?', N'Fresher', N'Hono''s RPC mode allows the client and server to share type definitions. This enables the frontend to have full autocomplete and type safety when calling API endpoints, significantly reducing integration bugs between the backend and frontend.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
