INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddc2a616-79ac-4cad-8c79-3ab61622cea0', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the difference between ''exports'' and ''module.exports''?', N'Intern', N'module.exports is the actual object returned as the result of a require call. ''exports'' is merely a shortcut or reference to the same object, and assigning a new value to ''exports'' will break the reference to the module.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
