INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a25888c-d8c3-455b-a07d-3abf661f5d3a', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain the concept of Ruby''s Global Interpreter Lock (GIL) and its impact on multi-threaded performance.', N'Middle', N'The GIL ensures that only one thread executes Ruby code at any given time, preventing race conditions within the interpreter''s internal data structures. While it provides thread safety, it prevents true parallel execution of CPU-bound tasks across multiple cores, though I/O-bound tasks can still benefit from concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
