INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9cf6af8-0bae-4bbe-9da8-3ac7dc232ca6', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is Node.js Process Model?', N'Intern', N'The Node.js Process Model is a single-threaded, event-driven architecture designed to handle many concurrent client requests efficiently. Unlike traditional web servers that create a new thread for every request, Node.js uses a Single-Threaded Event Loop to manage all non-blocking operations Features: - Runs in a single process with a single thread, requiring fewer resources than multi-threaded platforms - All incoming requests are handled by that one thread - Blocking I/O (file system, database, network) is handed off asynchronously — the thread doesn''t wait for it to complete - When async work finishes, a callback is queued and executed, and the response is sent back to the client Flow: 1. Client requests arrive and are placed in the Event Queue 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
