INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82611b6f-f4bb-4afe-b4b9-3ad507736a4b', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the concept of platform independence in Java.', N'Fresher', N'Java is platform-independent because it uses the Java Virtual Machine to execute code. The source code is compiled into bytecode, which can run on any device that has a compatible JVM installed, regardless of the underlying operating system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f0dc6c3-1b26-4a36-8133-3ad5ca70e103', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does the Rails connection pool manage database contention in a multi-threaded environment?', N'Senior', N'The connection pool maintains a set of established database connections that threads checkout and checkin. By setting the pool size to match the maximum number of threads per process, you prevent threads from blocking while waiting for a connection, thereby avoiding deadlock and performance degradation under high concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
