INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4256c922-d5bb-470c-b4f1-3adbaf53add0', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does React''s ''key'' prop affect reconciliation performance?', N'Senior', N'Keys help React identify which items in a list have changed, been added, or removed by providing a stable identity for each node. If keys are unstable, such as using array indices, React may perform unnecessary DOM operations or lose component state during reordering, degrading performance and causing UI bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2877afc5-6f24-4b33-9c3c-3adf8ed6f54a', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the trade-offs between using worker threads versus child processes in Node.js?', N'Middle', N'Worker threads share memory space, which makes communication faster but requires careful handling to avoid data races and synchronization issues. Child processes have their own memory space and provide better isolation, though inter-process communication is more expensive due to the need for serialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81e5fc90-02df-4cc2-a236-3ae0cebf37a5', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the implications of using large primary keys in an InnoDB table?', N'Senior', N'Every secondary index stores the primary key value as its pointer. Large primary keys cause all secondary indexes to grow significantly in size, leading to increased memory usage, reduced buffer pool efficiency, and slower disk I/O for secondary index lookups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e653678d-1c8e-4b17-ad70-3ae2e1b01baa', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between a deadlock and a lock wait timeout?', N'Middle', N'A deadlock occurs when two or more transactions hold locks that the others need, creating a cycle that requires one transaction to be rolled back. A lock wait timeout happens when a transaction waits too long for a lock held by another process that is not necessarily in a deadlock state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
