INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'991b05ff-57f1-45a1-9d7b-3ae517e3d545', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does Rails action caching differ from fragment caching, and when is each appropriate?', N'Senior', N'Action caching caches the entire output of an action, whereas fragment caching targets specific portions of a view. Fragment caching is more flexible and preferred in modern Rails, as it allows for granular cache expiration when only part of a page changes, rather than invalidating the entire response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ed10c85-35c8-46c0-a871-3ae67d16d116', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does the C++ volatile keyword differ from atomic operations in a concurrency context?', N'Senior', N'The volatile keyword in C++ is intended for memory-mapped I/O and prevents the compiler from optimizing away reads or writes to a variable. It does not provide atomicity, memory ordering, or visibility guarantees across threads, whereas atomic types specifically provide the synchronization primitives required for safe multithreaded communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
