INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0640a132-8cca-48da-a13c-3aed88b55d22', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What does it mean that AdonisJS is a ''batteries-included'' framework?', N'Intern', N'Being batteries-included means that the framework comes with a comprehensive set of official tools for common tasks like authentication, database management, and email. This reduces the need to rely on third-party packages for essential functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab9f0a5b-17ea-48bd-8e17-3aeeb8bdbbc2', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When asked to estimate a project with high uncertainty, what strategy do you use to communicate risk to stakeholders?', N'Senior', N'I avoid providing single-point estimates and instead use three-point estimation (optimistic, pessimistic, and most likely). I explain the underlying assumptions and constraints, framing the estimate as a probability distribution to manage expectations regarding scope and timeline variability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b10497b4-95b4-401b-82ca-3aef1bcadcdb', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the purpose of the ''Astro.glob'' function?', N'Middle', N'It is a utility for importing multiple files simultaneously from the local file system. It is commonly used for generating dynamic pages or listing content entries from a local directory during the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae572e67-d87e-4e02-8472-3aef8dd67028', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the difference between durable and non-durable message queues?', N'Middle', N'Durable queues persist messages to disk, ensuring they survive broker restarts or system failures. Non-durable queues store messages only in memory, offering lower latency at the expense of data loss if the broker crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f3a1346-64ec-4b50-947c-3aefc0d61716', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the architectural difference between ''Bundles'' and ''Packages'' in modern Symfony development.', N'Senior', N'Bundles are Symfony-specific plugins that can integrate directly into the framework''s configuration and container. Packages are standard PSR-compliant libraries that provide generic functionality, promoting better separation of concerns by keeping core business logic independent of the framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f439ea69-aaab-4ea1-9fd5-3af064d6bf32', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do Conditional Types enable meta-programming within the TypeScript type system?', N'Senior', N'Conditional types allow for type selection based on a boolean condition expressed within the type system, similar to a ternary operator. This enables the creation of highly generic utility types that can transform, filter, or extract information from other types based on their structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13a65e91-9982-43fb-9f1c-3af07448573f', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are constants in Ruby?', N'Intern', N'Constants are variables that begin with an uppercase letter and are intended to hold values that do not change. While Ruby allows them to be reassigned, it will issue a warning if you attempt to change the value of a constant after it has been defined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dacd55c3-b4c6-4521-ba25-3af58cef9332', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain how prototypal inheritance works?', N'Fresher', N'The Prototypal Inheritance is a feature in javascript used to add methods and properties in objects. It is a method by which an object can inherit the properties and methods of another object. In order to get and set the [[Prototype]] of an object, we use Object.getPrototypeOf() and Object.setPrototypeOf(). Nowadays, in modern language, it is being set using proto. Syntax: Example: In the given example, there are two objects ParentUser and ChildUser. The object ChildUser inherits the methods and properties of the object ParentUser and further uses them. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcc13876-d5e0-4a73-8f60-3afcced15ba3', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a situation where a bug is reported in a legacy module you have never worked on?', N'Junior', N'I would first read the existing documentation and look for related tests to understand the intended behavior of the module. Then, I would use logging and debugging tools to observe its execution flow before making any changes, ensuring I understand the impact of my fix.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f7a88cf-9751-4df0-8e2e-3aff123f9930', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Imagine you are tasked with organizing a large set of files. What criteria would you use to decide on a directory structure?', N'Intern', N'I would prioritize logical grouping based on functionality, project phase, or file type to ensure intuitive navigation. A good structure should be scalable, meaning it remains manageable even as more files are added, and it should use clear, consistent naming conventions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'320e7cd3-285f-42b4-80b6-3aff2b85d82b', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus approach the ''Container First'' philosophy?', N'Senior', N'Quarkus is architected to minimize memory consumption and startup latency, making it ideal for high-density container orchestration like Kubernetes. It provides native support for health checks, metrics, and distributed tracing, which are essential for cloud-native observability and reliability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20eb811a-306d-4750-ab24-3b0077b3a4b4', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Explain the role of the ''reducer'' in the Redux pattern.', N'Middle', N'A reducer is a pure function that takes the previous state and an action as arguments and returns a new state object. It must be deterministic, meaning it should not produce side effects or modify the inputs provided to it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c24a7298-c4ab-44b3-9d27-3b0549a29901', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix deal with ''Database Connection Pooling''?', N'Middle', N'Phoenix uses the ''DBConnection'' library, often configured via ''Ecto.Adapters.SQL'', to manage a pool of database connections. This prevents the application from opening too many connections simultaneously, which could exhaust database resources, and allows for efficient reuse of connections across concurrent processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'745dce65-57e5-4640-a6ec-3b069c32d393', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the concept of R''s ''byte-code compilation'' and its performance impact.', N'Senior', N'R includes a built-in compiler that translates high-level code into bytecode, which is then executed by an internal virtual machine. This reduces interpretation overhead and can provide significant speedups for complex functions that are called repeatedly without requiring manual conversion to C++.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8afc866-417b-4aff-8886-3b069d49bdaa', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Explain the significance of ''Write Sharding'' in DynamoDB.', N'Middle', N'Write sharding is a technique where you append a random number to the end of a partition key to spread heavy write traffic across multiple physical partitions. This is essential for preventing hot partitions when a specific key receives an extremely high frequency of updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
