INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'837a3f4e-29e2-480b-9484-3b12bb2afb9e', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How do environments differ from lists in R''s internal architecture?', N'Senior', N'Environments are reference-based hash tables that support lexical scoping and mutable state, while lists are vector-like structures that are typically copied upon modification. Environments are fundamental to the mechanics of namespaces and function closures, whereas lists are designed for heterogenous data storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
