INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c0551c9-60d7-4b3e-9a76-3b189f404acc', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the benefit of using Spring Boot''s profiles?', N'Intern', N'Profiles allow you to define different configurations for different environments, such as development, testing, and production. You can activate specific profiles to load different settings or beans depending on where the application is running.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ffbf15d-9d23-498d-92ba-3b1b78fd9244', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the purpose of an App factory in Actix-web?', N'Intern', N'The App factory is used to register routes, middleware, and shared state for an application. It is called by each worker thread to instantiate the application instance, ensuring each thread has its own context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31c058d9-49eb-4c72-98b2-3b1b86a4e93a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you access the index of an element in an array during iteration?', N'Fresher', N'To access the index of an element in an array during iteration, you can use methods like forEach, map, for...of with entries, or a traditional for loop. For example, using forEach: ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f38815a-8ae6-4dbe-8e01-3b1bd2dbf9c4', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Why do we write if name == "main" in a Python script?', N'Fresher', N'When Python runs a file, it sets the module-level name variable: - To "main" if the file is run directly (python script.py) - To the module name if the file is imported (import script) The guard if name == "main": ensures that certain code (usually the program entry point) only executes when the file is run directly, not when it is imported as a module. Why it matters: - Allows a module to be both importable (library) and directly executable (script) - Prevents side effects (print, sys.exit(), network calls) from triggering on import - Required for multiprocessing on Windows (workers re-import the main module) Use Case: A data pipeline module defines reusable ETL functions at the top level and uses the main guard for a self-test run that seeds a local database — CI runs python etl.py for s...', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8996addc-bf0a-4109-b4f4-3b1d2a32d801', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the difference between synchronous and asynchronous logging, and how does it affect scalability?', N'Senior', N'Synchronous logging blocks the execution flow until the log is written, which adds latency to the request path and limits throughput. Asynchronous logging offloads the I/O operation to a background thread or process, allowing the main application flow to continue, which is crucial for high-performance systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4983b40-0d83-47bf-8a27-3b1dd587ccc5', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How do Service Providers function in the Laravel lifecycle?', N'Junior', N'Service Providers are the central place of all Laravel application bootstrapping. They are responsible for binding services into the service container, registering event listeners, middleware, or routes, and configuring various components before the application starts handling requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebf6ad4a-ae23-4e31-880e-3b23051fe457', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the architectural implications of using Scala''s ''Cake Pattern'' for dependency injection versus using a dedicated framework.', N'Senior', N'The Cake Pattern uses self-type annotations and trait composition to define and wire dependencies at compile-time, ensuring type safety and explicit structure. While it avoids runtime reflection overhead, it often leads to complex trait hierarchies and difficult refactoring. Dedicated frameworks offer more flexibility and easier management of object lifecycles but introduce runtime overhead and potentially hidden dependency issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9aaead8-ec75-4898-ab9f-3b235f361ace', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask handle concurrency and why is it considered a micro-framework?', N'Middle', N'Flask is a micro-framework because it provides only the core essentials like routing and request handling, leaving other features like database ORMs or validation to extensions. It handles concurrency by delegating request processing to a production-grade WSGI server. The framework itself is thread-safe, but the performance depends heavily on the chosen deployment strategy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'476a84a2-6b2c-4ccf-8b89-3b25d327d1dc', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro handle CSS?', N'Intern', N'Astro supports standard CSS and various preprocessors like Sass or Tailwind CSS. By default, Astro scopes CSS to the specific component where it is defined, preventing styles from leaking into other parts of the site.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd689c39-0edf-4959-b324-3b2841b1e8fe', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Describe the function of the Token Ring in Cassandra.', N'Middle', N'The Token Ring is a virtual representation of the cluster where each node is assigned a range of tokens. This mechanism ensures even distribution of data across all nodes by mapping hashes of partition keys to specific points on the ring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2703f23e-6ad5-410a-b69b-3b2a2fb6fcc7', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How can R''s ''futures'' package change the paradigm of asynchronous execution?', N'Senior', N'The ''futures'' package provides a unified interface for asynchronous programming, abstracting away the underlying mechanism, such as multicore, multisession, or cluster backends. It allows developers to write code that is logically parallel while remaining agnostic to the specific execution backend, enhancing scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c783951a-77f7-4215-8e0f-3b2ba9dfd56f', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of the ''match'' expression?', N'Junior', N'The match expression allows you to compare a value against a series of patterns and execute code based on the first match. It is exhaustive, meaning the compiler ensures you have handled every possible case for the input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'567ba527-90fd-4b66-8cd3-3b2d41fa8dfb', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Is it possible to use non-Jakarta EE libraries in Quarkus?', N'Junior', N'Yes, Quarkus is designed to be extensible, and you can include any third-party Java library in your project. As long as the library is compatible with the Java version used, it will function normally within the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b87ff3bd-b411-476e-8e66-3b2d85e9127b', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB''s document-level concurrency control differ from traditional row-level locking?', N'Senior', N'MongoDB uses WiredTiger''s document-level concurrency control, which allows multiple clients to modify different documents within the same collection simultaneously. This significantly improves throughput compared to older engine versions that used collection-level locks, effectively reducing contention in high-concurrency environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6955c959-6c86-4fc7-adf1-3b2d9c8b9ce2', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How can you implement rate limiting in a FastAPI application?', N'Middle', N'Rate limiting is typically implemented using custom middleware or third-party libraries that track request counts in a shared store like Redis. The middleware intercepts incoming requests and returns a 429 Too Many Requests status if the threshold is exceeded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
