INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d190664-1bd1-4214-bcb7-3b2ff7ddf1c5', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of the body-parser middleware?', N'Intern', N'The body-parser middleware is used to parse the incoming request body in a middleware before your handlers. It populates the req.body property with the parsed data, such as JSON or URL-encoded form data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efad3520-814b-46b6-82cd-3b31c0ace7c5', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the potential drawbacks of over-indexing a table?', N'Middle', N'Every index adds overhead during write operations, as the index must be updated whenever rows are inserted, deleted, or updated. Over-indexing consumes extra disk space and memory while potentially confusing the optimizer, which might choose an inefficient index path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74db69fe-b942-46be-8d52-3b32d72cab9d', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you evaluate whether to build a custom solution or buy a managed service?', N'Senior', N'I prioritize buying managed services for undifferentiated heavy lifting—like database hosting or authentication—to reduce operational toil. I only consider building custom solutions when the component provides a unique competitive advantage or when existing vendor offerings fail to meet strict performance or security requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c1000a2-7e68-4ac9-8640-3b33b4e50090', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the risk of having too many logs in a production environment?', N'Junior', N'Excessive logging can consume significant disk space and disk I/O, potentially impacting application performance. Additionally, it can make it difficult to find relevant information among the ''noise'' of unimportant logs, effectively hiding the issue you are trying to find.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fa78e5b-af31-4367-b13c-3b3452175332', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What are the performance implications of Gin''s binding and validation features?', N'Senior', N'Gin''s binding uses reflection to map request data to structs, which is computationally more expensive than manual deserialization. While convenient, in extremely latency-sensitive paths, one might consider custom unmarshaling logic if the reflection overhead becomes a bottleneck in profiling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
