INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f8c8c59-dbe8-4b45-a39f-3b3d38fa4008', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is Qwik often described as a ''Zero-hydration'' framework?', N'Middle', N'It is called zero-hydration because it eliminates the standard hydration step where the framework must traverse the entire component tree to rebuild the virtual DOM. Instead, it uses stored metadata to link existing DOM elements to their interactivity logic, achieving a ''resumed'' state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd88cbb75-4f04-4608-9a8c-3b3dba707bfa', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is Fast Refresh?', N'Fresher', N'Fast Refresh is a feature that provides near-instant feedback when you make changes to your code. It keeps the component state intact while updating the UI, making the development process much faster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
