INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7be48efb-6473-41e2-99de-3b417eb2072e', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does ''denormalization'' differ in NoSQL compared to SQL?', N'Middle', N'In SQL, denormalization is often a performance optimization to avoid joins, whereas in NoSQL, it is a fundamental design pattern. Because NoSQL databases usually lack efficient join capabilities, data is structured to be read in a single request, even if it means duplicating information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ad56f9c-ff91-4203-bb12-3b42b9045c2d', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle feedback that is critical of your work?', N'Intern', N'I view critical feedback as an opportunity to learn and improve my technical skills. I listen objectively, ask clarifying questions to understand the specific concerns, and focus on the technical improvement rather than taking it personally. I then integrate the feedback into my workflow to ensure I don''t repeat the same mistakes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e2b0705-b66a-4747-8eb8-3b42f8c11812', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the advantage of using reactive programming in Quarkus?', N'Junior', N'Reactive programming in Quarkus allows applications to handle more concurrent requests with fewer resources by using non-blocking I/O. This is particularly useful for high-throughput services that perform many I/O-bound operations like database calls or external API requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5946f256-3bc2-4d84-a046-3b43e1950530', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact''s internal architecture differ from React regarding memory allocation?', N'Senior', N'Preact prioritizes a minimal footprint by avoiding large internal object structures and heavy virtual DOM diffing overhead. It uses a more compact reconciliation process that reduces garbage collection pressure by reusing node objects rather than constantly recreating them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6adeed4-a6f5-4d36-bff4-3b440b605ca9', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the function of the ''links'' export in a Remix route?', N'Intern', N'The links function is used to define external resources that the current route needs, such as CSS stylesheets. Remix automatically includes these links in the document head only when the user visits that specific route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0baaa5e6-1ff5-4392-b682-3b4518299e26', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do you obtain the client IP address in Gin?', N'Junior', N'The Context object provides a ClientIP method. This method parses the request headers, considering proxies like X-Forwarded-For, to determine the actual IP address of the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6d7f23f-19da-42ff-bcdf-3b453230a82b', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte''s compiler ensure memory safety and prevent common memory leaks?', N'Senior', N'The compiler automatically manages component destruction by cleaning up event listeners, timers, and subscriptions when a component is unmounted. Because the lifecycle management is baked into the generated code, it significantly reduces the human error factor that often leads to memory leaks in manual lifecycle-managed frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07fe0ee3-e48a-4c57-bb40-3b4662acc20b', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the purpose of ''Layered'' middleware in Litestar?', N'Senior', N'Layered middleware allows developers to apply specific middleware to subsets of the application, such as individual routers or even specific routes. This granular control is essential for performance, as it prevents unnecessary middleware execution on routes that do not require specific functionality like authentication or logging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bf71144-2a9e-495d-a990-3b4784cb75b1', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the architectural significance of the Actix ''Addr'' type?', N'Senior', N'The Addr type acts as a handle for sending messages to an actor''s mailbox. It decouples the sender from the recipient, allowing for location transparency and enabling asynchronous delivery, which is fundamental for scaling distributed-like components within a single process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99a7d40a-1e25-4bc1-8cd2-3b47ec992c11', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Is Qwik suitable for applications that require heavy client-side real-time data?', N'Senior', N'Yes, but it requires careful design of the reactivity graph. Because Qwik is designed to be resumable, state updates must be handled via its reactive primitives, which allows the framework to efficiently update the DOM without needing a full-page re-hydration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38dd42b4-2cf3-4490-945d-3b4acbc89441', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How do you architect for secure automated deployment of infrastructure as code?', N'Senior', N'Security is ensured by integrating static analysis tools into the pipeline to detect misconfigurations in templates before they are applied. Furthermore, the CI/CD service identity must be restricted to the minimum required permissions to modify the infrastructure, following the principle of least privilege.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bbe1bb9-7602-4205-a13a-3b4b4dfb53b3', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How do you manage nested components in Alpine.js?', N'Middle', N'Alpine.js supports nested components, where child components can access parent state through the component scope hierarchy. This allows for modular UI design, though developers should be mindful of dependency depth to avoid performance bottlenecks in reactivity tracking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67136a9b-14f7-4a05-9af8-3b4b9a1c1f0c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'If your application experiences slow response times, how would you begin to diagnose the bottleneck?', N'Junior', N'I would start by checking system metrics like CPU, memory usage, and disk I/O to identify resource exhaustion. Then, I would use distributed tracing or logs to identify which specific service or database query is consuming the most time before investigating potential network issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c1bdc9a-5f33-481a-89e5-3b528cdf93c8', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do you define relationships between models in Rails?', N'Junior', N'Relationships are defined using association macros like belongs_to, has_one, has_many, and has_and_belongs_to_many. These macros allow Rails to automatically handle foreign keys and provide convenient methods to query related records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03e95d4d-3737-4a76-a42a-3b5410814753', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of the ''composer.json'' file in a Laravel project?', N'Fresher', N'The composer.json file is a configuration file used by the PHP package manager, Composer. It lists all the external libraries and dependencies required by the Laravel project, allowing the manager to install and update them automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47245f42-567d-4eac-8cc3-3b541164020d', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar''s ''DTO'' system improve performance during serialization?', N'Middle', N'By using defined DTOs, Litestar can optimize the serialization process by knowing exactly which fields are required. This reduces the amount of data processed and allows the framework to use highly optimized encoders rather than relying on generic reflection-based serialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58842b3e-5fca-47f0-a8ca-3b54142672ba', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is database denormalization and why would you use it?', N'Middle', N'Denormalization is the process of intentionally introducing redundancy into a database design to improve read performance. It is used to reduce the number of expensive join operations in complex queries, though it comes at the cost of increased storage and potential data integrity challenges during write operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35a800c9-9fcc-40f9-aa6b-3b5562ff48a3', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What are the limitations of Snapshot Isolation compared to full Serializability?', N'Senior', N'Snapshot Isolation prevents dirty reads and non-repeatable reads but is susceptible to write skew, where two concurrent transactions read overlapping data and update disjoint sets such that the business invariant is violated. Serializability guarantees that the outcome is equivalent to some sequential execution, effectively eliminating all such anomalies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'794b9ee2-eff3-492f-b2e0-3b55a191aa00', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit maintain performance while working within the Constraints of Web Components?', N'Senior', N'Lit optimizes the bridge between declarative templates and imperative Web Component APIs by minimizing DOM operations and using efficient template cloning. It effectively treats the DOM as the source of truth, avoiding the overhead of maintaining a separate virtual representation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96c17298-c934-407e-acb2-3b571aab460d', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik optimize ''Time to Interactive'' (TTI)?', N'Middle', N'TTI is optimized because Qwik does not execute JavaScript on load. The browser only downloads the specific code required for the user''s immediate interaction, resulting in a very low initial JavaScript execution overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61381299-d16f-490f-9df3-3b59dab86b32', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle request errors?', N'Intern', N'If a request fails validation or a route is not found, Rocket automatically returns a standard HTTP error code. Developers can customize these error responses using catchers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38b05f48-c147-420e-9968-3b5aa91a10ec', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does the Next.js `revalidatePath` utility ensure data consistency in an ISR workflow?', N'Senior', N'The `revalidatePath` function allows developers to manually purge the cache for a specific route or group of routes after a mutation. This ensures that the next user visit triggers a fresh fetch, preventing the delivery of stale data to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40f0db51-41a3-483b-b923-3b5b806afda9', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you design a system to handle a surge in traffic that is 10 times higher than usual?', N'Middle', N'I would utilize an auto-scaling group to dynamically provision more compute resources based on CPU or request rate metrics. Additionally, I would implement load balancing to distribute traffic evenly and use rate-limiting or circuit breakers to protect backend services from being overwhelmed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c3c03c8-3c58-405d-a65a-3b5e32c736e4', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of Spring Profiles?', N'Middle', N'Profiles allow you to isolate configuration settings by environment, such as dev, test, or prod. You can activate specific profiles to load different beans or property values, ensuring the application behaves differently based on the environment it is running in.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbea5576-d117-4188-b6f7-3b65da17415f', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between ''override'' and ''new''?', N'Fresher', N'The override keyword replaces the base class implementation with a new implementation in the derived class, participating in polymorphism. The new keyword hides the base class member, essentially creating a new member that is independent of the base class version.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34042e14-ee34-4ba8-ac5e-3b682ec1fbea', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What happens if a network connection drops during a transaction?', N'Junior', N'If the connection is lost before a commit, the database management system will typically detect the timeout or error and automatically roll back the uncommitted transaction. This ensures the database does not remain in an inconsistent state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'397f8571-9339-47d5-a8c5-3b68ec03fa62', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you handle events in Angular?', N'Fresher', N'Handling events in Angular involves capturing and responding to user or system actions. Angular provides declarative and imperative methods to accomplish this. Declarative Approach Declarative methods involve writing event handlers directly in the Angular template using event binding. Syntax For event binding, Angular uses (event) syntax to listen for DOM events and execute an associated method in the component. (e.g.) Click Event: - Template: - Component: (e.g.) Input Event: - Template: - Component: Event Objects are optionally passed to event handling functions. These objects contain specific properties based on the event type, such as MouseEvent for click events and KeyboardEvent for keyboard-related ones.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed3de14a-00e2-4524-869f-3b694e9237b0', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What does it mean for a function to be ''const'' in Rust?', N'Middle', N'A ''const'' function can be evaluated at compile time if its arguments are also constants. This allows for pre-computation of values, reducing runtime overhead and enabling complex logic during the compilation phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
