INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7776e2e-2abe-46ce-aa63-3b6b58e72407', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How do AdonisJS''s built-in events and listeners facilitate microservices-ready architecture?', N'Senior', N'Events and listeners allow for an asynchronous, decoupled execution of business logic, such as sending emails or updating secondary databases. By moving these tasks out of the main request cycle, the system becomes more resilient and easier to transition into a distributed event-driven architecture later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
