INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7be0fdfe-b7f3-470c-be88-3b722244131b', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the benefit of stack allocation versus heap allocation in the context of Go''s escape analysis.', N'Middle', N'Stack allocation is significantly faster because it simply involves moving a stack pointer, whereas heap allocation requires complex memory management and eventually triggers garbage collection. Go''s compiler uses escape analysis to determine if a variable''s lifetime is confined to a function; if so, it allocates it on the stack to reduce memory pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd4c2961-fe12-4ab2-8ed1-3b733e3cb5c2', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Explain the architectural implications of the ''middleware chain'' pattern in Express regarding performance and error propagation.', N'Senior', N'The middleware chain is a synchronous sequence of functions that can lead to performance bottlenecks if complex logic is executed within them. Error propagation relies on passing errors to the next function; if a developer forgets to call next with an error, the request can hang or leave the application in an inconsistent state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cd5153e-d15a-48b9-a11a-3b7389ddb57e', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the role of a ''Transaction Coordinator'' in a distributed environment?', N'Senior', N'The coordinator manages the outcome of a distributed transaction by communicating with all participating nodes to verify they are ready to commit. It is the single point of truth that decides the final state of the transaction and ensures all participating nodes are synchronized, even if some nodes are slow to respond.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1d64b08-244f-4a12-bc3f-3b7773c2cace', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you optimize a system that is suffering from N+1 query problems?', N'Middle', N'I would identify the repetitive database calls by analyzing query logs and implement batch fetching or eager loading to retrieve related entities in a single request. This significantly reduces network round trips and database load by consolidating multiple small queries into a single efficient operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'589fce1c-cfee-4b52-8489-3b793467195a', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why is the two-phase commit (2PC) protocol often considered unsuitable for highly scalable distributed systems?', N'Senior', N'2PC is a blocking protocol that requires all participants to be available and responsive to complete a transaction, creating a single point of failure. It significantly increases latency and throughput bottlenecks because resources remain locked throughout the entire coordination phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b551bec0-9198-4836-bac3-3b7a04943671', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Why is it important to sanitize data before storing it in a database?', N'Middle', N'Sanitizing data before storage prevents injection attacks, such as SQL injection, where malicious input is interpreted as an executable command by the database engine. This ensures that user input is treated strictly as data and cannot compromise the integrity of the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
