INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b97b3f80-aa84-4681-8623-3b880337ed78', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'In the context of scaling an Express application, why is it critical to keep the application process stateless?', N'Senior', N'Statelessness allows you to scale horizontally by adding more instances behind a load balancer without needing sticky sessions. If local state like session data is stored in-process, requests must be routed to the same server, limiting scalability and creating a single point of failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da9b614d-36ed-4515-af23-3b89772fd6a1', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the Symfony ''Console'' component and why is it useful?', N'Middle', N'The Console component provides tools to create command-line interfaces for your application. It is essential for automating recurring tasks like database migrations, clearing cache, or running background jobs outside the web server context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bbf4c25-3a49-4e8f-bb93-3b897da214fa', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why do some distributed databases use ''Quorum-based'' consistency?', N'Senior', N'Quorum-based consistency allows developers to tune the balance between latency and consistency by specifying how many nodes must acknowledge a read or write. By requiring a majority of nodes to respond, the system ensures that at least one node contains the most recent update, preventing stale reads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88732af2-7f2a-41a5-ac77-3b9022d3b1f0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the browser rendering pipeline, and what triggers a reflow vs. a repaint?', N'Intern', N'The browser rendering pipeline is the sequential process a browser engine follows to convert HTML, CSS, and JavaScript source code into actual pixels on a physical screen The Rendering Pipeline Steps Reflow (Layout): Recalculation of element geometry. Triggered by any change that affects the size or position of elements. It is expensive because it may cascade — changing one element''s size can force recalculation of its entire subtree and ancestors. Repaint: Redrawing pixels where geometry has not changed but visual appearance has (colour, opacity, visibility). Less expensive than reflow but still non-trivial. Compositing only: The cheapest operation — moving or animating a composited layer (using transform or opacity) without triggering layout or paint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49868907-e43f-48fb-8a37-3b93202e1fc8', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the first step you should take when you encounter an unexpected error in a system?', N'Intern', N'The first step is to isolate the issue by reproducing it consistently in a controlled environment. Once reproduction is successful, document the specific steps taken and the exact expected versus actual outcomes to narrow down the scope of the problem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27f6f98d-67b0-4144-87c0-3b960de64409', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the difference between custom management commands and standard view logic?', N'Middle', N'Management commands are designed to be run from the command line for administrative tasks, data migrations, or maintenance scripts. View logic is intended to be triggered by HTTP requests and is part of the request-response cycle, so it is unsuitable for long-running or system-level maintenance operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5456209f-b697-4fce-a6cc-3b96e9fb9b6a', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does the Node.js ''require'' cache mechanism impact memory usage in large-scale modular applications?', N'Senior', N'The ''require'' cache stores module exports in memory after the first load to improve performance. In massive applications with thousands of modules, this cache can consume significant heap space, and because the cache is persistent for the life of the process, it can hinder hot-reloading strategies without manual invalidation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c17ffe6-1019-43be-ad8a-3b96f1c66c6e', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the difference between consistent hashing and traditional modular hashing in distributed systems?', N'Senior', N'Traditional modular hashing causes massive data remapping when the number of nodes changes, leading to cache invalidation storms. Consistent hashing maps both data and nodes to a logical ring, ensuring that only a small fraction of keys need to be remapped when a node is added or removed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a59730d7-ef58-471f-95a0-3b984f5828e5', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi''s routing performance compare to the standard library''s net/http ServeMux?', N'Middle', N'Chi is built on top of the standard library''s net/http and is designed to be lightweight and highly performant. While it provides more advanced routing capabilities like URL parameters and group routing, it maintains performance characteristics very close to the standard library by avoiding unnecessary allocations and using an efficient radix tree implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bad8b6a4-6d7f-415e-90b0-3b99608c0901', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Are functions first-class objects in Dart?', N'Intern', N'Yes, functions in Dart are first-class objects, which means they can be assigned to variables, passed as arguments to other functions, and returned from functions. This enables functional programming patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1d48b5a-3344-4c6a-a320-3b9ae8462d9d', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between ''unknown'' and ''any''?', N'Intern', N'While ''any'' bypasses all type checking, ''unknown'' is type-safe. You cannot perform operations on a variable typed as ''unknown'' until you perform a type check or a type assertion to verify its type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99703348-da06-4b64-b9f6-3b9c11f0d785', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the difference between a shared lock and an exclusive lock?', N'Intern', N'A shared lock allows multiple transactions to read a resource but prevents modification. An exclusive lock grants a transaction sole access to a resource for both reading and writing, preventing any other transaction from accessing it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19b51a56-fa9c-4563-a4a2-3b9cbcd31396', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you determine two values same or not using object', N'Fresher', N'The Object.is() method determines whether two values are the same value. For example, the usage with different types of values would be, Two values are considered identical if one of the following holds: 1. both undefined 2. both null 3. both true or both false 4. both strings of the same length with the same characters in the same order 5. both the same object (means both object have same reference) 6. both numbers and both +0 both -0 both NaN both non-zero and both not NaN and both have the same value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b4ba863-6618-40c3-819d-3b9cc82d8b43', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a system, how do you decide whether to use a push or pull model for data updates?', N'Middle', N'I use a push model when real-time updates are critical and the client needs to be notified immediately. I choose a pull model when the client controls the frequency of updates, which is often more efficient for reducing server load and managing client-side resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e420288f-e5c5-45db-862c-3b9ed0cf8cbb', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Explain the architectural implications of the ''defer'' versus ''async'' script attributes.', N'Senior', N'The defer attribute maintains script execution order and waits for the full HTML document parsing to complete, making it ideal for dependency-heavy bundles. Conversely, async executes scripts as soon as they are downloaded, which is better for independent tracking pixels or analytics, though it risks non-deterministic execution order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc45d273-da88-4df9-a9ec-3b9f3f8e57c8', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you decide between fixing a bug immediately versus investigating it further?', N'Intern', N'The decision depends on the severity and impact of the bug; if it is a critical production outage, a temporary mitigation might be necessary to restore service. However, for non-critical issues, it is better to take the time to investigate and apply a permanent, well-tested fix.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8910f9e-9e3b-44b5-9978-3b9f85afc80e', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you determine if a task is ''too big'' and needs to be split?', N'Junior', N'If I find myself struggling to estimate the time required or if the task has too many moving parts and dependencies, it is likely too large. A task should be small enough to be completed and verified within a relatively short timeframe, such as a day or two. Breaking it down reduces complexity and makes progress easier to track.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e171c44-907b-4a13-b28f-3ba2bc44dd65', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the role of a Controller in Phoenix?', N'Fresher', N'The Controller acts as the intermediary between the user request and the data layer. It receives the request, interacts with the model to fetch or update data, and instructs the view to render the final response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd51337c6-dffb-4e31-9292-3ba6b230b7f7', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How would you declare a comment in Python?', N'Fresher', N'Unlike languages like C++, Python does not have multiline comments. All it has is octothorpe (#). Anything following a hash is considered a comment, and the interpreter ignores it. #line 1 of comment #line 2 of comment In fact, you can place a comment anywhere in your code. You can use it to explain your code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
