INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56f883f5-c9a0-40bb-8122-3baabed71b73', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are server routes in Nuxt?', N'Intern', N'Server routes are files placed in the server directory that allow you to build custom API endpoints directly within your Nuxt project. This enables you to handle backend tasks like database queries or form submissions without a separate backend framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd00f5be-4d4d-4c18-a77c-3bae268f3334', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the ''rule of five'' in C++ resource management?', N'Middle', N'The rule of five states that if you define any of the destructor, copy constructor, copy assignment operator, move constructor, or move assignment operator, you should generally define all five. Failing to do so often leads to resource leaks, dangling pointers, or incorrect object state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
