INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'121db131-9bc4-4e3b-aa5c-3bb470d0b517', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why is Svelte often preferred for performance-critical tasks like data visualization or real-time dashboards?', N'Senior', N'Svelte is preferred because it avoids the overhead of Virtual DOM diffing, which can be a bottleneck during frequent, rapid state updates. Its fine-grained reactivity ensures that only the specific DOM nodes affected by data changes are updated, maintaining 60fps performance even under high-frequency data streams.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
