INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd4b29c3-758e-4321-9d27-3bb7afe28a01', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does consistent hashing improve the performance of a distributed cache when nodes are added or removed?', N'Senior', N'Consistent hashing maps both data and nodes onto a virtual ring, ensuring that only a small fraction of keys need to be remapped when a node changes. This minimizes cache misses and prevents the massive reorganization of data that occurs with traditional modulo-based partitioning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
