INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'469a0f91-05ac-41ea-9f90-3bbb59c545fe', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra handle node failure in a multi-datacenter setup?', N'Middle', N'Cassandra uses replication strategies and gossip protocols to monitor node health. If a node fails, requests are routed to healthy replicas in other data centers or available nodes in the same DC based on the consistency level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'972c2c2e-b179-422e-a27f-3bbdcdf1f8c3', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain the trade-offs between using a monolithic architecture and microservices in Node.js.', N'Middle', N'Monoliths are easier to develop, deploy, and monitor initially but can become difficult to scale and maintain as the codebase grows. Microservices offer better scalability and independent deployment but introduce complexity in terms of network communication, service discovery, and distributed transaction management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
