INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63a82781-15c5-40b7-9e4e-3bc918953fb2', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s ''Memory Layout'' influence the performance of structs?', N'Senior', N'Swift aligns struct members based on their memory requirements to optimize CPU cache performance and memory access speed. Developers must be aware of member ordering, as poor alignment can introduce padding bytes, increasing the memory footprint of the struct and potentially degrading performance in tight loops.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c735d2d7-ba1b-4614-b838-3bccabb0866f', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the mechanics of Python''s reference counting and how the cycle-detecting garbage collector complements it.', N'Senior', N'Reference counting is the primary mechanism for memory management, immediately deallocating objects when their reference count drops to zero. However, it cannot resolve reference cycles where objects point to each other. The cyclic garbage collector periodically scans containers to identify these isolated islands of unreachable objects and reclaims their memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ec91804-4f99-4c28-ad31-3bccd869436a', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is dependency injection?', N'Fresher', N'Dependency injection is a design pattern where class dependencies are ''injected'' into the class through the constructor or methods instead of being hardcoded inside the class. This makes the code more modular, testable, and easier to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d0094a5-cd7c-4c90-9dd4-3bcd4fbe2424', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro''s ''Islands Architecture'' differ from the traditional hydration approach used by SPAs?', N'Senior', N'Traditional SPAs hydrate the entire page, loading JavaScript for every component regardless of interactivity. Astro''s Islands Architecture isolates interactive components, hydrating only those specific parts while shipping zero JavaScript for static content, which significantly reduces the initial payload and improves Time to Interactive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2db68b9f-492c-40ef-a8c5-3bd11f0141a1', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What are the advantages of using Gin over the standard library ''net/http''?', N'Middle', N'Gin offers a significantly better developer experience with features like built-in middleware, easier parameter parsing, structured validation, and a high-performance router. It drastically reduces the amount of boilerplate code required to build production-ready RESTful APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd86fa55-96a1-469d-b5a5-3bd163d07f1f', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a schema?', N'Intern', N'A schema is the formal definition or blueprint of the database structure. It outlines the tables, fields, data types, and the relationships between the various entities in the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a113924b-60c1-4ba3-90cf-3bd396ebdf32', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Discuss the architectural impact of Svelte''s lack of a Virtual DOM.', N'Senior', N'Without a Virtual DOM, Svelte removes the CPU-intensive process of diffing large object trees on every state change. This leads to lower memory consumption and faster execution, especially on low-end mobile devices where garbage collection and processing power are constrained.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ad6da12-76ad-4fb1-918b-3bd4a2a51b30', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between a JAR and a WAR file in Spring Boot?', N'Intern', N'A JAR file is a standalone executable package containing the application and an embedded server. A WAR file is designed to be deployed into an external, standalone application server like Apache Tomcat.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24bc2bbe-d4b9-42a6-95cf-3bd4c276a91f', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of ''Lucid Relationships''?', N'Junior', N'Lucid Relationships allow you to define connections between database tables, such as one-to-one, one-to-many, or many-to-many. This enables you to fetch related data easily using simple method calls on your models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b02aa41-dae2-4946-8e11-3bd4e4428b42', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of the ''controller'' pattern in Lit and how does it promote architectural scalability?', N'Senior', N'Controllers allow developers to extract complex logic, such as data fetching or event listeners, into reusable classes that hook into the component''s lifecycle. This pattern decouples business logic from the component definition, making the codebase easier to test, maintain, and share across different components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d0c0d6d-66b8-46e9-89b2-3bd58c7a80dc', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why is it important to keep the partition key value diverse?', N'Middle', N'Diverse partition key values ensure that request load is balanced across the underlying physical partitions. If a key is not diverse, a single partition could become a bottleneck, leading to throttled requests and inefficient resource utilization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
