INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7de56f2-220d-4b8e-8a29-3bdb7f9439ab', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix optimize static asset delivery?', N'Middle', N'Phoenix uses the ''Plug.Static'' module to serve files, which is designed to be efficient for small to medium-sized projects. For high-traffic production scenarios, it is recommended to place a CDN in front of the application to cache and serve static assets, reducing the load on the Phoenix processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d9c1ac0-2c53-4583-ad37-3bdb84613a07', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the difference between a Signal and a Memo?', N'Intern', N'A Signal is a state container that you manually update, whereas a Memo is a computed value that updates automatically based on other signals. You use a signal for raw state and a memo for derived data that requires caching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7b3ab86-b6f5-4d48-a3b9-3bdc447ebd18', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Compare the maintainability of Tailwind''s utility classes versus CSS-in-JS libraries like Styled Components.', N'Senior', N'Tailwind offers faster build times and smaller runtime overhead compared to CSS-in-JS, which must inject styles dynamically at runtime. However, Tailwind can make HTML markup look cluttered, whereas CSS-in-JS encapsulates logic and styling within component boundaries, which some teams find easier to manage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
