INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24cc0dc3-3747-4f73-abf1-3be2b5ba14b5', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What does it mean for an Actix actor to be ''Send'' and ''Sync''?', N'Middle', N'Being ''Send'' means the actor can be safely transferred between threads, while ''Sync'' means references to it can be shared across threads. These traits are fundamental to Rust''s concurrency model, ensuring that actors can function safely in a multi-threaded execution environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
