INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b76252d-0df4-41ca-8f7a-3be8ccc2613e', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Compare the performance and memory overhead of using standard Spring MVC versus Spring WebFlux for blocking I/O operations.', N'Senior', N'WebFlux is designed for non-blocking, event-loop-based concurrency, which excels at handling high numbers of concurrent connections with low memory footprint. However, using WebFlux with blocking I/O operations negates these benefits and can lead to thread starvation, making Spring MVC a more stable choice for blocking workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b395452b-2eea-4ea2-97c1-3be99e66fd48', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Why is it important to use ''BackgroundTasks'' in FastAPI for side effects?', N'Senior', N'BackgroundTasks allow the application to return an HTTP response to the client immediately while continuing to execute non-critical tasks, such as sending emails or logging, in the background. This improves the perceived latency for the end-user while ensuring that the primary logic completes successfully without waiting for auxiliary operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64266adb-fea3-4574-b803-3be9a45cf69f', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is a write-through cache strategy?', N'Middle', N'In a write-through cache, data is written into the cache and the underlying database simultaneously. This ensures the cache is always synchronized with the database but adds latency to write operations because both systems must be updated before the operation is considered complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb7f1ec7-5c9e-42ee-a9b3-3be9d13dc9d3', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the benefit of using Micronaut''s declarative HTTP client?', N'Intern', N'It allows you to define an interface with annotations representing the REST service you want to call. The framework automatically generates the implementation at compile-time, ensuring type safety and reducing manual code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'684e8abc-efe2-4d33-8171-3bed978d56b2', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the purpose of the ''UpdateItem'' operation?', N'Fresher', N'The UpdateItem operation modifies an existing item in a table. It allows you to add, remove, or change attribute values, or even add a new item if the primary key does not already exist.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c20a3148-c562-477c-8d78-3bedebd2afe9', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What are the architectural risks of mixing jQuery with a modern component-based framework like React or Vue?', N'Senior', N'Both jQuery and modern frameworks attempt to manage the DOM, but they do so with conflicting paradigms; jQuery is imperative while frameworks are declarative. Allowing jQuery to manipulate the DOM underneath a framework''s virtual DOM will cause state desynchronization, leading to unpredictable bugs and rendering issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f7cbc20-9c09-4e27-8bae-3bee0ce774bd', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is ''Index Cardinality'' and why does it matter to the query optimizer?', N'Middle', N'Cardinality refers to the number of unique values in an index relative to the total number of rows. The optimizer uses cardinality to decide whether an index is worth using; if an index has low cardinality, the optimizer may choose a full table scan instead, as the index is not selective enough.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fe2dad8-826a-4a63-b666-3bf01c932336', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the architectural benefits of using ''defineAsyncComponent'' for large-scale applications?', N'Senior', N'It enables code splitting by loading components only when they are needed, reducing the initial JavaScript bundle size. This improves time-to-interactive metrics and allows for better lazy-loading strategies, which is critical for maintaining performance in enterprise-grade applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6434d5ba-1530-4ab4-8c4b-3bf03b4cf506', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why do you need web storage', N'Fresher', N'Web storage is more secure, and large amounts of data can be stored locally, without affecting website performance. Also, the information is never transferred to the server. Hence this is a more recommended approach than Cookies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21655c03-2886-4211-9abe-3bf119131cea', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the impact of ''Shared Libraries'' on microservice autonomy?', N'Senior', N'While shared libraries can reduce code duplication, they often introduce tight coupling. If a library update forces all services to redeploy simultaneously, it negates the benefit of independent deployment, so they should be used sparingly for non-business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'130f14ce-82aa-4adf-8539-3bf13d673c04', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'If you need to ensure data integrity but also require fast access, how do you handle the trade-off?', N'Fresher', N'You should analyze the frequency of read versus write operations. If data integrity is paramount, you might implement stricter validation checks that slightly slow down write speeds, whereas high-speed read requirements might favor caching techniques.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72db9b1e-c566-4731-a56d-3bf479eaeccd', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the purpose of a Provider in NestJS?', N'Intern', N'A provider is a fundamental concept used to abstract business logic, data access, or utility functions. Providers can be injected into controllers or other providers, allowing NestJS to manage their lifecycle and dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d0a0b71-a579-40a7-8f47-3bf4a6a36d23', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of the ''Cache Warmer'' in the Symfony ecosystem?', N'Senior', N'The cache warmer pre-populates the application''s cache, such as generated container classes, routing tables, and metadata, during deployment. This prevents a performance hit for the first user who hits the application, ensuring that the system is fully prepared to handle requests immediately upon deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70d5f9ba-fbdd-4a68-8498-3bf890f20604', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is Laravel and what is its primary role in web development?', N'Intern', N'Laravel is an open-source PHP web framework designed for developing web applications following the model-view-controller (MVC) architectural pattern. Its primary role is to provide a structured, expressive, and efficient environment for developers to build robust backends by automating common tasks like authentication, routing, and database management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb0dc992-c0b3-4225-80e0-3bf8a18b489d', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Mapped Types and why are they useful?', N'Middle', N'Mapped types allow you to create new types by transforming properties of an existing type. They are useful for creating utility types that modify objects, such as making all properties optional or read-only, without manually defining new interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'317408ba-9bdc-4ada-a37a-3bfd1c3646dd', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go''s method dispatch differ from traditional class-based object-oriented languages?', N'Senior', N'Go utilizes implicit interface satisfaction rather than explicit inheritance hierarchies. Method dispatch is handled via itables, which contain the type information and function pointers required to invoke methods on an interface value. This decoupling allows for greater flexibility and composition without the complex vtable overhead found in languages with deep inheritance trees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aad90289-d2e1-4040-8144-3bfde8cae06f', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What are the primary performance advantages of Actix-web''s middleware pipeline?', N'Senior', N'The middleware pipeline is designed to be highly modular and non-blocking, allowing for efficient request/response transformation without stalling the event loop. By using Rust''s zero-cost abstractions, it minimizes the overhead of wrapping multiple layers of logic around each request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'099cd942-97f8-4c19-892b-3bffa8f5ebac', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a replica in Redis?', N'Intern', N'A replica is a copy of a master Redis instance. It is used to create read-only backups or to increase read throughput by distributing read queries across multiple nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
