INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'497a5297-e6fa-460b-933b-3c0257e93188', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the purpose of the ''await'' block in Svelte?', N'Fresher', N'The await block is a built-in feature that simplifies handling asynchronous data. It allows you to display different content based on whether a promise is pending, resolved, or rejected, without needing to manage complex state variables for loading or error states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d6a1e2a-c25e-476b-b70e-3c03c2fb078d', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Explain the architectural trade-offs of using a single global store versus multiple slice-based stores.', N'Senior', N'A single store provides a predictable state tree and facilitates powerful debugging through time-travel, but it can lead to performance bottlenecks if the entire state tree triggers re-renders on every update. Multiple stores could isolate concerns but complicate cross-slice communication and negate the benefits of unified middleware and dev-tool tracking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93bfa13a-3afa-48e5-bcf0-3c065a227714', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the purpose of a load balancer in a distributed system?', N'Intern', N'A load balancer distributes incoming network traffic across multiple servers to ensure no single server becomes a bottleneck. This improves system reliability and availability by routing traffic away from failed or overloaded instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23df73a1-6eae-4861-bf45-3c06b5cb1dc6', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS''s reactivity model differ from React''s virtual DOM reconciliation in terms of memory overhead and update frequency?', N'Senior', N'SolidJS uses fine-grained reactivity based on observables, where individual components run only once and only specific DOM nodes update when their reactive dependencies change. In contrast, React re-renders component trees and performs virtual DOM diffing to identify changes, which consumes more CPU cycles and memory. This architectural difference allows SolidJS to bypass the overhead of managing a virtual DOM entirely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8021aee-e79f-4aa0-ba7e-3c09dabbdf6b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the DRY principle in JavaScript?', N'Intern', N'DRY stands for Don''t Repeat Yourself. It states that every piece of knowledge must have a single, unambiguous, authoritative representation within a system. Duplicated logic makes code harder to maintain because changes must be applied in multiple places. Violation: Applying DRY: DRY vs. WET (Write Everything Twice): DRY does not mean *never write similar-looking code*. Premature abstractions can introduce unnecessary coupling. A practical rule: abstract duplication only when the same logic appears three or more times and the abstraction does not make the code harder to understand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5de4bc5-b1ca-4a97-81e1-3c0a523b4661', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack''s ''Manifest'' file facilitate the integration of build artifacts with backend frameworks?', N'Senior', N'The manifest maps original filenames to the hashed filenames generated by Webpack. This allows backend applications to dynamically look up the correct file paths for static assets during server-side rendering or template generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cf7d69d-29fe-438d-958e-3c0bee3b80b1', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why is it generally better to perform data fetching in Server Components rather than Client Components?', N'Middle', N'Fetching data on the server avoids additional network waterfalls from the client and keeps sensitive API keys or database logic hidden from the browser. It also allows the server to stream the UI to the client as soon as parts of the data are ready, improving Time to First Byte.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9415a302-617c-4a61-b6ea-3c0c24aa5df1', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is useContext? What are the steps to follow for useContext?', N'Intern', N'The useContext hook is a built-in React Hook that lets you access the value of a context inside a functional component without needing to wrap it in a component. It helps you avoid prop drilling (passing props through multiple levels) by allowing components to access shared data like themes, authentication status, or user preferences. The usage of useContext involves three main steps: Step 1 : Create the Context Use React.createContext() to create a context object. You typically export this so other components can import it. Step 2: Provide the Context Value Wrap your component tree (or a part of it) with the Context.Provider and pass a value prop. Now any component inside can access the context value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15c0355b-ec60-40e6-befc-3c0d5e841b2f', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle environment-specific configurations?', N'Junior', N'Micronaut supports environment-specific configuration files, such as application-dev.yml or application-prod.yml. The framework automatically loads these files based on the active environment, allowing for different settings across stages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c917876-7e5e-4f5e-9cf0-3c0d861d0a2c', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R''s garbage collector interact with C/C++ integration via Rcpp?', N'Senior', N'The R garbage collector is unaware of memory allocated directly via C++ pointers within Rcpp, which can lead to memory leaks if not managed manually. Developers must use Rcpp-managed classes like XPtr or smart pointers to ensure that C++ objects are correctly deallocated when the corresponding R object is finalized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
