INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6753fa8-d678-4da9-99cb-3c14ae31c968', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust handle errors compared to exceptions?', N'Fresher', N'Rust uses the Result type for recoverable errors, forcing the developer to handle failure cases explicitly. This avoids the overhead and hidden control flow associated with traditional try-catch exception handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
