INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17053db8-3a21-402c-b25d-3c16cdad65b9', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If a stakeholder demands a hard deadline for a complex project, how do you manage expectations and scoping?', N'Middle', N'I would explain that a fixed deadline requires a flexible scope to ensure quality. I would suggest prioritizing features into must-haves and nice-to-haves, allowing us to deliver a functional MVP by the target date while deferring non-critical items.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'052cc4bb-adac-482c-b9fd-3c176c968dc9', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the significance of the ''meta'' module in Sass?', N'Senior', N'The meta module provides tools for inspecting the properties of values, mixins, and functions during compilation. It is particularly useful for building advanced design tools or libraries that need to introspect user-provided styles, allowing for more dynamic and introspective CSS generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70296246-3616-41d1-8fca-3c18391d4720', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is a ''Chaos Engineering'' experiment, and what is its goal?', N'Senior', N'Chaos engineering involves intentionally injecting failures, such as server terminations or network latency, into a production system. The goal is to uncover hidden weaknesses and confirm that the system''s resilience mechanisms work as expected under stress.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be264b29-4c7d-4975-8e9c-3c189bb89e87', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s ARC manage memory in the context of closure capture lists?', N'Senior', N'ARC manages memory by tracking reference counts, but closures can create retain cycles if they capture self strongly. Capture lists allow developers to explicitly define the ownership semantics, such as weak or unowned, to break these cycles and prevent memory leaks. This mechanism is essential for managing object lifecycles in asynchronous and event-driven architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'702fc18b-1c24-4c7f-a11a-3c1b163089e2', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the architectural considerations when implementing a global state management system in a high-frequency update environment?', N'Senior', N'In high-frequency scenarios, the primary concern is avoiding unnecessary re-renders across the component tree, which can cause significant performance degradation. Architects should utilize techniques like selector-based subscription, atomic state updates, or context splitting to ensure that only components consuming the specific changed slice of state are triggered. It is also critical to evaluate whether the state should reside within React''s render cycle at all, or if external stores outside the React tree are more appropriate for managing rapid, volatile data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd931f263-44f5-4604-aada-3c1c5abba8ee', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte''s compilation process differ from traditional framework runtimes like React or Vue?', N'Middle', N'Svelte is a compiler that shifts the work of framework abstractions from the browser to the build step. It converts components into highly efficient, imperative code that surgically updates the DOM, eliminating the need for a virtual DOM runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05310acc-e709-41ef-945a-3c1cb5c1738d', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What are the trade-offs of using an event-driven architecture versus a request-response pattern?', N'Senior', N'Event-driven architecture promotes high decoupling and asynchronous processing, which enhances system resilience and scalability under heavy load. However, it introduces significant complexity in terms of eventual consistency, distributed tracing, and the difficulty of debugging complex event chains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74628d0f-0d21-41ff-a299-3c1ccb8f0639', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How to validate JSON Object in javascript?', N'Fresher', N'JSON.parse() function will use string and converts to JSON object and if it parses invalidate JSON data, it throws an exception ( Uncaught SyntaxError: Unexpected string in JSON ). &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1aaafa6-bc0b-4376-9ac8-3c2088f7587c', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust achieve safety in FFI (Foreign Function Interface) calls?', N'Senior', N'Rust does not provide safety across FFI boundaries, as the external code is outside the compiler''s control. Developers must manually wrap FFI calls in safe interfaces, ensuring that the external code adheres to Rust''s memory safety invariants, such as lifetime requirements and pointer validity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc41ae7c-1664-43ca-9edf-3c20d3924a4a', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does a database handle concurrent access?', N'Junior', N'Databases use locking mechanisms to handle concurrency. When one transaction modifies data, the database locks those rows to prevent other transactions from making conflicting changes until the first transaction is complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94d25adc-87ce-4a69-8447-3c2255af6cf0', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why is the Remix ''meta'' function important for SEO and social sharing?', N'Senior', N'The meta function executes on the server, allowing for dynamic generation of meta tags based on the data fetched in the loader. This ensures that search engine crawlers and social media bots receive optimized, context-aware metadata for every specific route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed45e352-af7a-4ab2-b17b-3c240b1de040', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS manage component lifecycle?', N'Intern', N'SolidJS lifecycle is simple because components only run once. Instead of traditional lifecycle hooks like ''componentDidMount'', you use effects to perform actions after the component is rendered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eec3aec5-7190-4606-8173-3c24b96881d6', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the significance of the ''Finalizer'' and ''Cleaner'' mechanisms, and why are they generally discouraged?', N'Senior', N'Finalizers and Cleaners are intended for resource reclamation, but they are unreliable due to the non-deterministic nature of the Garbage Collector. They introduce significant performance overhead and risk of memory leaks, which is why the ''try-with-resources'' pattern and explicit ''AutoCloseable'' implementations are the standard for resource management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa3606d4-bb1e-4972-89b6-3c29faa98340', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is a Compound Index and why is the order of fields important?', N'Middle', N'A compound index includes multiple fields in a single index structure. The order is critical because MongoDB uses the index fields to sort and filter data; if the query does not match the leading prefix of the index, the database engine may not be able to use the index effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'855081b4-5dea-4092-9545-3c2a49d42fdb', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'When should you choose a NoSQL document store over a relational database?', N'Middle', N'You should choose a document store when your data model is hierarchical or polymorphic, and you need schema flexibility to handle rapidly evolving data structures. It is also preferred when you need horizontal scalability for large volumes of unstructured or semi-structured data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcd1f9d3-1933-4d39-b33e-3c2d3d69ed69', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is a route module in Remix?', N'Intern', N'A route module is a file that exports the components and functions needed for a specific URL path. It bundles the UI, the data loading logic, and the mutation logic into one convenient location.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f646b495-487f-4e98-83ff-3c2eeeb84b35', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi manage request body limits and security middleware?', N'Senior', N'Chi does not enforce body limits natively, delegating this to standard library middleware or explicit configuration within the handler chain. By keeping the core router lean, it allows developers to implement security layers like rate limiting, timeouts, and payload validation as reusable, composable middleware components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
