INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d25ca05-b781-48f5-8938-3c396641b276', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Describe the difference between BASE and ACID properties.', N'Middle', N'ACID properties focus on immediate consistency and reliability, making them ideal for transactional systems. BASE, which stands for Basically Available, Soft state, and Eventual consistency, prioritizes availability and scalability, accepting that the data might not be perfectly consistent at every exact moment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'360d80f0-ed1a-4294-825d-3c3b2b6582b4', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does the CAP theorem constrain the design of distributed caching layers?', N'Senior', N'Caching usually prioritizes Availability and Partition Tolerance, often sacrificing Consistency. If you require strong consistency, you must accept higher latency for synchronization, which effectively negates the primary advantage of a distributed cache.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2882bd7d-308b-4393-828d-3c3ba8b5b581', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is a ''Catch'' handler in Rocket?', N'Intern', N'Catch handlers are specialized functions used to manage HTTP error codes. When an error occurs, Rocket invokes the corresponding catch handler to provide a user-friendly error response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ffcb861-db82-40aa-b7db-3c3bd5316338', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between ''Array'', ''Set'', and ''Dictionary'' in terms of performance characteristics?', N'Middle', N'Arrays provide O(1) access by index and maintain order, making them ideal for sequences. Sets provide O(1) membership checks via hashing but do not maintain order, while Dictionaries provide O(1) key-based lookups, trading memory overhead for fast data retrieval.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33b7e39e-654c-464b-9adc-3c434e542317', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux''s unidirectional data flow differ from a traditional two-way data binding architecture in terms of debugging and state predictability?', N'Senior', N'Unidirectional data flow ensures that state mutations occur only through explicit actions, creating a single source of truth that is easy to trace. In contrast, two-way binding often leads to implicit side effects where multiple components modify state simultaneously, making the application state unpredictable and significantly harder to debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe1f55c1-d4d5-4170-aa8e-3c445db1892e', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What happens if you dispatch an action that isn''t handled by any reducer?', N'Intern', N'If an action is dispatched that does not match any ''type'' defined in your reducers, the reducer will simply return the current state unchanged. The application state will remain exactly as it was before the action was dispatched.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7a38fb3-0146-4c4e-8038-3c44d1ea7ddc', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you balance the trade-off between system security and user experience?', N'Middle', N'Excessive security controls like frequent MFA or complex password requirements can frustrate users and lead to drop-off. The approach is to apply friction contextually—using risk-based authentication where stricter checks are only triggered during suspicious activity, ensuring a seamless experience for most legitimate users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52020c70-a869-42d2-a982-3c45549abe07', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is JPA in the context of Spring?', N'Junior', N'JPA, or Java Persistence API, is a specification for accessing, persisting, and managing data between Java objects and a relational database. Spring Data JPA simplifies this by providing repository abstractions that eliminate much of the boilerplate code required for database operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74275c7f-cd84-456e-869f-3c46c9608153', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do you handle lists or arrays in Lit templates?', N'Junior', N'Lit provides the ''repeat'' directive for rendering lists. It is optimized to track items by a unique key, which ensures that if the list order changes, Lit only updates the necessary DOM nodes instead of re-rendering everything.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
