INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36e5230c-51d6-4bf5-a32c-3c47466a6158', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why is it important to use ''Event'' bubbling in custom components?', N'Middle', N'Events that bubble through the Shadow DOM boundary are automatically retargeted, making it easier for parent components to listen for child actions. This maintains a clean component hierarchy and avoids tight coupling between distant parent and child components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54f14854-0ecb-423b-9ad9-3c4bac19f694', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript’s structural type system fundamentally differ from nominal type systems in terms of type compatibility?', N'Senior', N'In a structural system, types are compatible if their shapes match, regardless of their explicit declaration or inheritance hierarchy. This contrasts with nominal systems, where compatibility is determined by explicit naming or explicit inheritance, requiring an exact match of the declared type identity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3b53861-cdfd-4004-8ec5-3c4c59f10dd2', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach refactoring existing code?', N'Junior', N'I ensure that there are sufficient tests covering the existing functionality before making any changes. I then refactor in small, incremental steps, running tests frequently to ensure the behavior remains consistent throughout the process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'028be005-abc2-4737-8ddc-3c4e8326ee04', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the event phases of a browser?', N'Intern', N'There are 3 phases in the lifecycle of an event propagation in JavaScript, 1. Capturing phase: This phase goes down gradually from the top of the DOM tree to the target element when a nested element clicked. Before the click event reaching the final destination element, the click event of each parent''s element must be triggered. 2. Target phase: This is the phase where the event originally occurred reached the target element . 3. Bubbling phase: This is reverse of the capturing phase. In this pase, the event bubbles up from the target element through it''s parent element, an ancestor and goes all the way to the global window object. The pictorial representation of these 3 event phases in DOM looks like below, !Screenshot', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
