INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17c61dfb-16ce-43b6-89a6-3cbc051f2284', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the implications of using Redis as a primary data store versus a cache?', N'Senior', N'Using Redis as a primary store requires strict adherence to durability settings like AOF with fsync every second to prevent data loss. As a cache, the priority shifts to eviction policies and performance, where minor data loss during failover is often acceptable compared to the latency overhead of strict persistence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53a5bba0-6ca9-4b70-be90-3cbc27c28223', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What architectural considerations are necessary for securing inter-region traffic in a global system?', N'Senior', N'Inter-region traffic should be encrypted via VPN or TLS, and ideally routed over a private backbone rather than the public internet. Furthermore, identity propagation must be consistent across regions, often requiring a unified global Identity Provider and short-lived, verifiable tokens to ensure authorization remains valid across different physical deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d91df1c-d8e9-4866-8830-3cbee2e0bc43', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the primary role of a Module in NestJS?', N'Intern', N'A module is a class annotated with the @Module decorator. It is used to organize the application structure by grouping related components like controllers and providers into a single unit of functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea425ee8-300c-4206-a198-3cbf2901155d', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is an interface in Go and why is it useful?', N'Junior', N'An interface is a collection of method signatures that define a specific behavior. It is useful because it allows for polymorphism, enabling functions to accept any type that implements the required methods regardless of the concrete type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ea92f20-34fa-431b-b21b-3cbf63216fb7', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain the difference between @ViewChild and @ContentChild.', N'Middle', N'ViewChild is used to access elements or components defined within the component''s own template. ContentChild is used to access elements or components that are passed into the component by a parent through projection using the ng-content slot.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a5fa5d7-e1aa-49be-8e33-3cbff8da4f4a', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is Cassandra considered ''schema-optional'' compared to RDBMS?', N'Fresher', N'Unlike a relational database that requires a strict schema definition for all columns, Cassandra allows you to define tables with different column structures. While you define the table structure, rows can have different sets of columns, providing more flexibility for evolving data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43a22d10-3e1b-4274-8acd-3cc079caf908', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why is it important to keep the store state serializable?', N'Intern', N'Keeping the state serializable ensures that tools like Redux DevTools can work correctly, such as allowing state persistence and time-travel debugging. Non-serializable data, like functions or class instances, can break these features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5bcb71b-0f6d-4d23-aac7-3cc3ce91838a', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the primary risk of using ''runBlocking'' in production code?', N'Middle', N'''runBlocking'' bridges the non-blocking coroutine world to the blocking world by forcing the current thread to wait until the coroutine completes. Using it in production, especially on the main thread, can lead to UI freezes, deadlocks, and performance bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e014d48f-7335-4b61-8728-3cc4132ce4dd', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain how AdonisJS handles environment configuration and why it is superior to manual process.env management.', N'Senior', N'AdonisJS uses an environment variable validator that checks for the existence and type of required variables at startup. This fail-fast mechanism prevents runtime errors caused by missing configuration, which is a common source of instability in cloud-native deployment environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8548a0df-fed0-4a17-9e8f-3cc52e8ebd05', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the primary benefit of using TypeScript in a frontend project?', N'Intern', N'The primary benefit is improved code quality and maintainability through static type checking. It allows developers to identify potential bugs early in the development process and provides better tooling support, such as autocompletion and easier refactoring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34e4bd80-65a8-4ecc-b66b-3cc7e6d4de7b', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the Runtime Errors?', N'Intern', N'The errors which occurs after starting the execution of the programs are known as runtime errors. Runtime errors can occur because of: Invalid Input Invalid Logic Memory issues Hardware failures and so on With respect to every reason which causes to runtime error correspoing runtime error representation class is available Runtime error representation classes technically we call as a exception classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4921b088-eb7c-40e3-8b59-3cca86df86e1', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Extend ES6 Promises by Bluebird:', N'Middle', N'Bluebird extends the ES6 Promises API to avoid the issue in the second solution. This library has a “default” onRejection handler which will print all errors from rejected Promises to stderr. After installation, you can process unhandled rejections and discard a rejection, just handle it with an empty catch', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e40e3b3-1db8-4d1d-924e-3ccd56f0db8b', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why is the separation of ''Request Lifecycle'' from ''Application Lifecycle'' important in PHP architecture?', N'Senior', N'Understanding this separation is crucial because it dictates where state is initialized and destroyed; resources that require expensive initialization, such as database connections, should be managed via persistent pools rather than re-initialized on every request. This architectural distinction is the key to optimizing high-throughput PHP services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b6e4017-62f6-4ffe-bf40-3cce4cad8ce5', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar''s dependency injection system differ from traditional frameworks like FastAPI?', N'Senior', N'Litestar uses a hierarchical dependency injection system that allows for overriding dependencies at the app, router, or route handler levels. Unlike frameworks relying heavily on global state, Litestar''s container is explicit and supports provider caching at different scopes, enhancing testability and resource management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a984621-0151-48fa-b993-3ccea5b222d3', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the role of an InjectionToken in Angular, and why is it preferred over class-based tokens?', N'Senior', N'InjectionToken provides a way to define custom providers for types that do not have runtime representation, such as interfaces or configuration objects. It avoids the ''class as token'' pattern, which would force the inclusion of the class in the final bundle and prevent effective tree-shaking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1361e8f-9875-4d1c-911d-3cd62ac043d1', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'You are tasked with choosing between a library that is very easy to implement but has a large file size, and one that is difficult to implement but very lightweight. How would you approach this decision?', N'Fresher', N'I would first identify the primary goal of the project, specifically whether performance speed or development time is more critical. If the application is for a low-bandwidth environment, I would prioritize the lightweight library despite the extra effort. If the project has a very tight deadline, I would choose the easier library, provided the file size does not break the functional requirements of the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb0caa9d-7ed8-46a2-b3ad-3cd83ef19340', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the primary purpose of the Symfony framework?', N'Intern', N'Symfony is a PHP framework designed to speed up the creation and maintenance of web applications. It provides a set of reusable PHP components and a structured way to build robust, scalable applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15a7cec2-6bf1-420a-906f-3cd91603b5fe', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the rules of React hooks?', N'Intern', N'React hooks have a few essential rules to ensure they work correctly. Always call hooks at the top level of your component or custom hook — never inside loops, conditions, nested functions, or after an early return. Only call hooks from React function components or other custom hooks (whose names must start with use). Lean on eslint-plugin-react-hooks to enforce these rules. The React Compiler (RC/stable by 2026) relaxes the need for some manual memoization, but the rules of hooks themselves still apply. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'501bc260-2d01-4bd8-9b37-3cd98efb146e', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the role of a ''Boundary'' in a well-structured Phoenix application?', N'Middle', N'A boundary defines the interface between your web-facing code and your core business logic. By keeping business rules in separate modules or contexts, you ensure the application remains maintainable and decoupled from the web transport layer, like HTTP or WebSockets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27a896dd-6ebe-483f-bc2b-3cda44dd59db', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony''s ''Serializer'' component handle circular references, and why is this a challenge?', N'Senior', N'Circular references occur when objects reference each other in a loop, which can cause stack overflows during serialization. Symfony handles this by using circular reference handlers or object normalizers that track visited objects, preventing infinite recursion while ensuring the data structure is accurately represented.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'190eec05-19d5-422c-97fd-3cdd0a208b59', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do Lit components handle ''observability'' for nested property changes?', N'Senior', N'Lit''s default reactive system observes top-level properties; it does not automatically detect deep changes within objects or arrays. To handle nested updates, developers must either replace the object/array with a new reference to trigger the update or implement a custom property-change detection strategy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48ee29df-5f5e-45fb-ab7e-3ce210add4b5', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What are ''before_request'' and ''after_request'' hooks?', N'Intern', N'These are lifecycle hooks that allow code to execute immediately before a request handler is called or after a response is generated. They are useful for global tasks like modifying headers or measuring execution time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77d80fea-1cb1-4a2c-9c0a-3ce3a56942b1', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the purpose of ''autoload'' and how does it optimize application startup time?', N'Senior', N'Autoload allows the application to define constants that are only loaded when they are first referenced, rather than at the time of application boot. This reduces memory usage and initial load time by deferring the loading of heavy libraries or rarely used classes until they are actually needed during execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf2fc12d-e1d1-49b0-acfd-3ce5607b96c1', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How would you handle rate limiting at the application level in Express, and what are the drawbacks?', N'Senior', N'Rate limiting can be implemented via middleware using in-memory stores like Redis to track request counts per IP. The drawback is that application-level limiting consumes Node.js resources; it is generally more efficient to handle rate limiting at the API Gateway or edge layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4942208-508b-4f74-8c46-3ce78bdf79ce', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the mechanics of ''deoptimization'' (deopt) in a JIT-compiled environment.', N'Senior', N'Deoptimization occurs when the engine''s speculative assumptions about types or object shapes are invalidated by runtime data. The engine must discard the optimized machine code, revert to the interpreter or a baseline compiler, and potentially re-profile the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bcb7d13-262b-4149-b141-3ce82a732ca1', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the benefit of using MDX over standard Markdown in Astro?', N'Middle', N'MDX allows you to use JSX components directly within your Markdown files. This is useful for creating interactive documentation or blog posts that require custom UI elements, such as data visualizations or interactive code editors, which standard Markdown cannot provide.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3a6f12f-3bde-4a41-b41f-3ce9dfaef0ec', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between an Error and an Exception?', N'Junior', N'An Error represents a serious problem that an application should not try to catch, such as a JVM failure or memory overflow. An Exception represents conditions that a program might want to catch and handle to keep the application running.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e3d1dfc-2f76-4258-ab8b-3cee48e0b5e5', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the best practices for MongoDB Transactions?', N'Senior', N'The multi-document transactions are only supported in the WiredTiger storage engine. For a single ACID transaction, if you try performing an excessive number of operations, it can result in high pressure on the WiredTiger cache. The cache is always dictated to maintain state for all subsequent writes since the oldest snapshot was created. This means new writes will accumulate in the cache throughout the duration of the transaction and will be flushed only after transactions currently running on old snapshots are committed or aborted. For the best database performance on the transaction, developers should consider: 1. Always modify a small number of documents in a transaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48d78edf-b2d2-4218-8cc1-3cee881f4c42', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the purpose of Panache in Quarkus?', N'Junior', N'Panache is a framework built on top of Hibernate ORM that simplifies database interactions. It provides a more fluent and concise API for entity management and data access, significantly reducing the amount of boilerplate code required for CRUD operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79ff83ba-1f6b-43c6-93d6-3cefd44707c8', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between a ''Stop-the-World'' GC pause and a concurrent GC phase?', N'Senior', N'A Stop-the-World pause freezes all application threads to perform critical tasks like root scanning or compaction, ensuring heap consistency. Concurrent phases run alongside the application threads, performing tasks like marking, which reduces total application downtime but requires complex synchronization to handle concurrent modifications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c7fc998-0e7c-4895-95ce-3cf1f0b503d0', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the primary difference between MyISAM and InnoDB storage engines regarding transactional support?', N'Middle', N'InnoDB supports full ACID-compliant transactions, including commit, rollback, and crash recovery, which makes it suitable for data-critical applications. MyISAM does not support transactions, lacks row-level locking, and is generally used for read-heavy workloads where data integrity requirements are lower.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6fd87e1-8663-4be0-b886-3cf725b93749', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What happens if a Svelte variable is not updated using an assignment?', N'Intern', N'Svelte detects state changes by looking for assignments in the code. If a variable is updated by mutating an object or array rather than reassigning it, Svelte may not automatically trigger a UI update, and you might need to perform a reassignment to notify the framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c325bcef-4ad3-4fe3-85a2-3cf76c812254', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why do we need loaders for CSS in Webpack?', N'Fresher', N'Webpack natively only understands JavaScript. By using loaders like css-loader, you allow Webpack to interpret CSS files and inject them into the application bundle, enabling better asset management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
