INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'981d4a47-5fff-4c98-8945-3d03b9d9e059', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What happens if a loader fails in Remix?', N'Intern', N'If a loader encounters an error, Remix stops the rendering process for that route and displays the nearest defined error boundary. This keeps the rest of the application stable while notifying the user of the failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34fbd17b-bf21-4716-95f9-3d04126a816e', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is it generally recommended to avoid overusing the @apply directive?', N'Middle', N'Overusing @apply can lead back to the maintenance issues of traditional CSS, such as creating large, custom class names that are difficult to track. It is best used for small, repetitive UI patterns rather than creating an entire CSS-based abstraction layer over Tailwind.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2c1c578-970f-4470-9c48-3d061e2f4da2', N'075b8862-431c-4678-9767-f55359758a4a', N'What are async components?', N'Intern', N'In large applications, we may need to divide the app into smaller chunks and only load a component from the server when it''s needed. To make this happen, Vue allows you to define your component as a factory function that asynchronously resolves your component definition. These components are known as async component. Let''s see an example of async component using webpack code-splitting feature, Vue will only trigger the factory function when the component needs to be rendered and will cache the result for future re-renders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f46629fb-e0d2-4b8d-be3a-3d08ea785eb9', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the primary benefit of using Buffer objects in Node.js?', N'Middle', N'Buffers allow Node.js to handle binary data efficiently by allocating memory outside of the V8 heap. This is essential for dealing with raw streams of data, such as network packets or file system chunks, without the overhead of converting them into JavaScript strings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
