INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7598999-58c4-4d6d-b0d0-3d1253684583', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are companion objects in Kotlin?', N'Intern', N'A companion object is an object declared inside a class that is marked with the companion keyword. It allows you to define methods and properties that belong to the class itself rather than to instances of the class, similar to static members in other languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
