INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'243b885c-6de8-4420-9258-3d164f755670', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL handle concurrent index creation?', N'Middle', N'By using the CONCURRENTLY keyword, PostgreSQL builds the index without taking a long-term exclusive lock on the table. This allows read and write operations to continue, though the process takes longer and requires two scans of the table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'802e6c24-4d77-457d-838c-3d173573053d', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Explain the trade-offs between using a single large store versus slice-based state management.', N'Senior', N'A single store provides a global source of truth and simplifies state persistence, but it can lead to performance bottlenecks if every action triggers re-renders across the entire app. Slice-based management improves maintainability and scalability by partitioning state, but requires careful handling of cross-slice dependencies and potential synchronization issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
