INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95d3f7ed-74f6-4f6b-ad96-3d182ea5deaa', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does an array differ from a linked list?', N'Fresher', N'An array is a collection of elements stored in contiguous memory locations, allowing fast random access. A linked list consists of nodes where each node points to the next, allowing for dynamic size changes but requiring sequential access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'473f9deb-3ee6-48db-a0db-3d1abf4d4c02', N'075b8862-431c-4678-9767-f55359758a4a', N'Explain the concept of ''prop drilling'' and how to mitigate it.', N'Middle', N'Prop drilling occurs when data is passed through multiple layers of components that do not need the data, just to reach a deeply nested child. It can be mitigated by using state management libraries, composition-based dependency injection, or by restructuring components to use slots.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37516a0f-46bf-4366-9271-3d1c37a9729d', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the core difference between Remix and a traditional client-side React application?', N'Fresher', N'Remix is a full-stack framework that handles data loading and mutations on the server before the page reaches the browser. Unlike a standard client-side app that fetches data after the page loads, Remix ensures the browser receives fully prepared HTML, which improves performance and SEO.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91de438f-ada0-4505-90d7-3d1d139ed81e', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why is Fastify considered ''low overhead''?', N'Intern', N'Fastify is considered low overhead because it minimizes the number of function calls and object allocations during the request lifecycle. It is specifically engineered to reduce the impact of the framework itself on your application''s performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
