INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'161cccda-1bed-497c-85e7-3d1eafd5b1df', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the interaction between the ''Event Loop'' and the ''Task Queue'' when dealing with third-party library orchestration.', N'Senior', N'The event loop manages execution by selecting tasks from the macrotask and microtask queues. When third-party libraries schedule tasks asynchronously, they are effectively competing for the same event loop execution time, meaning a poorly optimized library can starve the main application''s logic or rendering tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'780598b1-eac6-4bfa-a788-3d205542ffc5', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind''s build process handle large-scale monorepos?', N'Senior', N'In a monorepo, Tailwind can be configured to scan multiple package directories for utility usage, ensuring a unified CSS output. This allows for shared design tokens across different applications while maintaining a single source of truth for the styling engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32af2010-24c6-45a8-ae10-3d22a22931aa', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are asked to estimate a task that requires learning a new tool, how do you factor that in?', N'Junior', N'I include a specific research and learning phase in my estimate before the implementation phase begins. I recognize that the learning curve adds overhead and inform the team that the initial work will be slower until I gain the necessary proficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddd3a2ca-35e2-4284-955b-3d23bacdf7f7', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the purpose of ''alias_method'' in Ruby metaprogramming?', N'Middle', N'Alias_method creates a copy of an existing method under a new name, which is essential for wrapping or extending existing functionality. It allows developers to preserve the original method''s behavior while injecting custom code before or after it, a technique commonly used in monkey patching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f57c37d-6021-4fe3-afca-3d23c2d4926d', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between a class method and a scope in ActiveRecord?', N'Middle', N'While they often perform similar tasks, scopes are designed to be chainable and always return an ActiveRecord::Relation object, which is required for lazy loading. Class methods can return any value, but they must explicitly return the scope or use the self keyword in a way that preserves the relation chain to remain compatible with other query methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b615435e-42ca-4f40-81e4-3d269b278a92', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Is Axum synchronous or asynchronous?', N'Fresher', N'Axum is fully asynchronous. It is built to run on the Tokio runtime, which is designed for high-performance, non-blocking I/O operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'371ff054-3d32-49b8-a092-3d274f3dc579', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Can you use Hooks in Preact?', N'Fresher', N'Yes, Preact has full support for Hooks, including useState, useEffect, and others. The hooks API in Preact is designed to be identical to React''s, allowing for the same functional component patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44cb0914-c4db-4e0e-847c-3d2847d5aed7', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Why is ''Hot Reload'' in Quarkus considered superior to standard IDE hotswapping?', N'Senior', N'Standard IDE hotswapping is limited by the JVM''s capability to redefine classes on the fly. Quarkus''s hot reload reconstructs the application state more deeply because it maintains the framework''s build-time metadata, allowing it to adapt to structural changes like adding new beans or changing configuration properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06011688-51bb-4061-8b27-3d2a705dad33', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you design a system to ensure data consistency in a distributed cache environment?', N'Senior', N'I would use a cache-aside or write-through strategy coupled with a robust cache invalidation mechanism, such as event-driven updates via a message bus. To handle race conditions, I would implement distributed locking or versioning for cache keys to ensure that stale data from the database does not overwrite newer cached entries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'702db8da-535a-44a4-8f55-3d2c360bcfc1', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How can closures be used to create private variables?', N'Fresher', N'Closures in JavaScript can be used to create private variables by defining a function within another function. The inner function has access to the outer function''s variables, but those variables are not accessible from outside the outer function. This allows you to encapsulate and protect the variables from being accessed or modified directly. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc7abbd3-63eb-44c3-a736-3d2d4b561645', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL implement MVCC to handle concurrent transactions?', N'Middle', N'PostgreSQL uses Multi-Version Concurrency Control by storing multiple versions of a row, each tagged with transaction IDs. Readers access a version visible to their specific transaction snapshot, ensuring that readers do not block writers and writers do not block readers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db7b1857-b239-4ecd-82b4-3d30df19de9d', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle dependency injection?', N'Middle', N'Express does not have a native dependency injection container. Developers typically implement it by passing dependencies through closure scopes, attaching them to the request object, or using external libraries that handle service registration and resolution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f27eaf26-d53f-4b44-8417-3d33906a04ee', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you communicate a technical issue to a non-technical stakeholder?', N'Fresher', N'I avoid using jargon and focus on the impact the issue has on the end-user or the business process. I explain the situation in terms of what is broken, why it matters, and the estimated time or effort needed to fix it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c35d988-d4be-43eb-a326-3d33a78e2053', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony''s ''Form'' component handle data validation, and why is it separated from the entity?', N'Middle', N'The Form component uses validation constraints to ensure data integrity during binding. By separating validation from the entity, you can apply context-specific constraints, such as requiring different fields for user registration versus profile updates without polluting the domain model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91b42822-9493-49f3-b7e6-3d35a14a1da7', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you handle database connection pooling in a Flask application to prevent connection exhaustion?', N'Senior', N'Flask applications should use a database engine that supports connection pooling, such as SQLAlchemy''s ''QueuePool''. By maintaining a pool of persistent connections, the application avoids the high overhead of establishing a new database handshake for every incoming request, which is critical for maintaining performance under heavy traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9182e26-8a11-42e8-99ce-3d35a3879298', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js protect against XSS (Cross-Site Scripting) vulnerabilities?', N'Middle', N'Alpine.js uses text-node updates for binding, which inherently escapes content and prevents raw HTML injection. However, developers must still be cautious when using directives that explicitly render HTML, ensuring that any user-provided data is properly sanitized before being processed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af0c1a07-8f02-45db-8364-3d3dc443a7d1', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the advantage of using AdonisJS ''Policies'' for authorization?', N'Middle', N'Policies provide a structured way to define authorization logic for specific resources, keeping checks centralized and readable. They allow you to enforce granular permissions, such as ensuring only an owner can update their own profile, without cluttering controllers with conditional checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe94a317-0237-47ea-b34a-3d401f465d58', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is Client-Side Rendering (CSR) in the context of Next.js?', N'Fresher', N'CSR is the process where the browser downloads a minimal HTML file and uses JavaScript to render the page content. In Next.js, this is typically handled by using the ''use client'' directive for specific components that require interactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a2cde57-d09e-4056-a7a5-3d429cbf5501', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How do Go modules handle dependency management and reproducibility?', N'Middle', N'Go modules use a ''go.mod'' file to track dependencies and a ''go.sum'' file to store cryptographic checksums of each module version. This ensures that every build is reproducible and that the project uses the exact intended versions of its dependencies across different environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19244e50-3e48-4e34-b235-3d463e35b037', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How should you approach partial updates in a REST API, and why is PATCH often preferred over PUT?', N'Senior', N'PUT is defined as a full replacement of a resource, while PATCH is intended for partial updates. Using PATCH prevents accidental data loss during concurrent updates and reduces bandwidth consumption, though it requires careful design to define the update semantics, such as JSON Merge Patch or JSON Patch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6897f10-c23d-435a-bd25-3d49b3db0033', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How would you implement sophisticated rate limiting in a Chi-based architecture?', N'Senior', N'The most effective approach is to implement a middleware that interacts with a distributed store like Redis to maintain counters per client identifier. By leveraging Chi''s group-based middleware support, you can selectively apply these limits to sensitive endpoints while bypassing them for public resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2de11735-aa9e-4aee-a176-3d4edbbdca39', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What happens if a user clicks a button before the JavaScript is loaded in Qwik?', N'Intern', N'Qwik uses a global event listener that captures the event and fetches the corresponding JavaScript chunk on demand. Once the code arrives, it executes the handler immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fa4f286-042f-4f65-87ae-3d4f2f36659f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s ''Zone'' handle asynchronous error propagation?', N'Senior', N'Zones capture asynchronous exceptions by wrapping the execution context, allowing developers to set a global error handler for all code running within that zone. This is architecturally superior to manually attaching error handlers to every individual Future, as it provides a centralized mechanism for managing failures in complex async graphs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e45685c-9aaa-4688-a18a-3d5044d1150a', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Explain why properties in Lit are ''reactive'' by default.', N'Middle', N'Properties marked with the property decorator automatically trigger a re-render whenever their value changes. This reactivity ensures the UI always stays in sync with the underlying data model without manual DOM manipulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb4aeba4-793e-42da-9566-3d505772c3da', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Is jQuery still relevant in modern web development?', N'Intern', N'While many modern frameworks like React and Vue have replaced the need for jQuery in complex single-page applications, jQuery remains relevant for maintaining legacy codebases and for quick, small-scale projects where simple DOM manipulation is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'638890e3-7a7c-4761-8c59-3d53b8fc2576', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the danger of ''guessing'' a fix during a production outage, and how can it be avoided?', N'Middle', N'Guessing can lead to side effects that worsen the situation or introduce new, harder-to-find bugs. It is avoided by basing decisions on data, such as logs, metrics, and trace analysis, and by verifying the hypothesis in a non-production environment before applying a fix.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'548c4f7c-2ead-4f0f-ab24-3d55f6c4f0c5', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If you are assigned two tasks with the same deadline, how do you decide which one to do first?', N'Intern', N'I would first assess the impact and dependencies of each task, prioritizing the one that is a blocker for other team members or has higher business value. I would then communicate with my manager to confirm the priority and ensure my approach aligns with team goals. If both are equally critical, I would look for ways to break them down or seek help to ensure both are completed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68eaf602-f9c0-4f98-9f1a-3d5793509a24', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the trade-offs of using Unsafe or foreign memory access APIs in terms of performance and safety?', N'Senior', N'These APIs allow direct memory access and low-level manipulation, which can significantly boost performance by bypassing object overhead and GC constraints. However, they circumvent the JVM''s memory safety guarantees, creating risks of segmentation faults, memory leaks, and undefined behavior that are difficult to debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a1bfb2b-a715-4959-8424-3d57a339ab2f', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Explain the composition pattern in React', N'Fresher', N'The composition pattern in React is the practice of building UIs by combining smaller, reusable components instead of extending them through inheritance. The most common forms are: passing children (props.children), passing components as named props (slots), specialization (a more specific component that wraps a generic one and fixes some props), render props / "children as a function", and compound components (a parent component that exposes a set of related sub-components, e.g. with and ). Composition is React''s main reuse mechanism, alongside custom hooks for behavior. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb4cd1ee-efdf-404f-9182-3d57d8d5577e', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Does Chi provide built-in middleware?', N'Intern', N'Yes, Chi comes with a set of standard middleware, such as logging, recovery from panics, request ID generation, and timeouts. These are commonly used to add essential functionality to any Go web service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7b29f44-3c3b-4944-84c4-3d5af5eb8ed8', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When you realize you have introduced a bug that reached production, what is your immediate course of action?', N'Junior', N'My priority is to report the issue to my team lead or manager immediately to ensure transparency. Once reported, I would help gather information to assess the impact and work on a fix or a rollback to restore service as quickly as possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c783c1d6-3cec-42f2-81d4-3d5ca4be0bec', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the trade-offs of using ''Auto-sharding'' versus ''Manual Sharding''?', N'Senior', N'Auto-sharding simplifies operational management by automatically balancing data based on system metrics, but it can lead to unpredictable query performance if the system makes poor rebalancing decisions. Manual sharding offers full control over data placement, which is beneficial for optimizing complex access patterns, but it places a significant burden on the engineering team to monitor and manually rebalance the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39e2e048-af48-42c4-a9dc-3d5f8e0f89d9', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the types of applications you can build with Node.js?', N'Intern', N'Node.js is a JavaScript runtime environment built upon event-driven programming that enables non-blocking I/O (Input/Output) capable of serving multiple concurrent events in a single thread. Non-blocking I/O makes Node.js very fast, lightweight, scalable, and efficient in handling data-heavy and I/O-heavy workloads characteristic of several types of web applications. Types of applications you can build with Node.js * IoT (Internet of Things) * Real-Time Chat Application * Single-Page Application * Social Media Platform * Streaming App * Online Payment Processor * Remote Collaboration Tool * CRM Tool * Advanced Fintech App * Content Management System * E-Learning Platform * E-Commerce Platform * Ridesharing App * Project Management Tools * Location-Based App * Online Publishing Platforms *...', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcc8903d-2f8a-4dda-9c9d-3d62bd9931f2', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Explain Microdata in HTML5?', N'Fresher', N'Microdata is a standardized way to provide additional semantics in web pages. Microdata lets you define your own customized elements and start embedding custom properties in your web pages. At a high level, microdata consists of a group of name-value pairs. The groups are called items, and each name-value pair is a property. Items and properties are represented by regular elements. Search engines benefit greatly from direct access to this structured data because it allows search engines to understand the information on web pages and provide more relevant results to users. At a high level, microdata consists of a group of name-value pairs * itemscope:- To create an item * itemprop:- To add a property to an item Example', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b98c068-6142-4ec4-a0e3-3d63623508d0', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the benefit of the ''sourcemap'' option in Vite?', N'Middle', N'Enabling sourcemaps creates a mapping between the compiled code and the original source files. This is essential for debugging in the browser console, as it allows you to trace errors back to the exact line in your original TypeScript or CSS files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'914971cf-168a-4e3e-ac33-3d6419f51d8e', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What strategies would you employ to handle database connection pooling in a FastAPI application?', N'Senior', N'You should use a connection pooler, such as those provided by SQLAlchemy or asyncpg, managed via a dependency that initializes the pool at application startup and closes it at shutdown. This ensures efficient resource utilization and prevents connection exhaustion under heavy concurrent load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce35bc4c-bd3c-432c-b12b-3d64c37d581c', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of the ''html'' tag in Lit?', N'Fresher', N'The html tag is a tagged template literal that parses and renders the component''s template. It creates a template that is processed by Lit to efficiently update the DOM during re-renders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b99bc12d-061d-4afc-a4c3-3d6570a10d8a', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the purpose of the hooks.server.ts file?', N'Intern', N'The hooks file allows you to intercept server requests to perform tasks like authentication or modifying headers. It runs for every request made to the server, providing a way to apply global logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3c09ce9-0d81-4bf2-a1ca-3d68ee83124d', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the purpose of Hono''s ''Validator'' middleware?', N'Middle', N'The validator middleware allows for schema-based validation of incoming request data, such as query parameters, headers, or JSON bodies. It ensures that only correctly formatted data reaches the route handler, reducing the need for manual validation logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0b9b5cd-f7fb-4aa1-ab8b-3d692d04cfd4', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the PostgreSQL ''NULL'' value?', N'Intern', N'A NULL value represents the absence of data or an unknown value in a specific field. It is important to distinguish NULL from an empty string or a zero, as it indicates that the information for that specific record is missing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcb55b60-d39c-48e0-8fbe-3d6a7b1b9006', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between structures and classes in Swift?', N'Fresher', N'Structures are value types, meaning they are copied when assigned to a new variable, while classes are reference types, meaning they share a single instance. Additionally, classes support inheritance, allowing one class to inherit the characteristics of another, whereas structures do not.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'721d3e41-456e-423a-b799-3d6a9d3fc2d4', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the difference between channel-based communication and shared memory with mutexes.', N'Middle', N'Channels follow the philosophy of communicating to share memory, rather than sharing memory to communicate. While mutexes are useful for protecting critical sections of shared data, channels provide a higher-level synchronization primitive that helps prevent race conditions and makes data flow more explicit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccb37fbc-c2c3-425c-88dd-3d6b106d6283', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain how Laravel''s ''Pipeline'' pattern can be leveraged for complex business logic processing.', N'Senior', N'The Pipeline pattern allows you to pass an object through a series of classes or closures, where each stage modifies the object or performs a validation check. This is highly effective for complex, multi-step workflows like checkout processes or document processing, as it keeps individual logic steps testable and easily reorderable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'672fb486-f94f-4626-ac48-3d6e9f94c5be', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is an API endpoint in SvelteKit?', N'Fresher', N'API endpoints are server-side routes that handle HTTP requests like GET, POST, or DELETE. They allow you to interact with databases or external services without exposing sensitive logic or credentials to the client-side browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47129239-b8ca-4806-8a0a-3d6eba0c2420', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Why does SvelteKit prefer ''forms'' over manual fetch calls for state mutation?', N'Senior', N'Forms are the native way the web handles state mutations; using them allows SvelteKit to provide features like progressive enhancement, automatic cache invalidation, and seamless integration with server-side form actions. This reduces the amount of boilerplate code needed for error handling and validation compared to manual fetch implementations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6e4991d-871f-4b41-854f-3d6fb5dd6e72', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the role of Guards in the NestJS request lifecycle.', N'Junior', N'Guards are responsible for determining whether a given request should be handled by the route handler based on specific conditions like permissions or roles. They are executed after all middleware but before any interceptor or pipe, and they return a boolean value to allow or deny access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2a6ea2a-715a-4ec1-a843-3d74f85657d9', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt 3''s auto-import system affect the build-time performance and bundle size?', N'Senior', N'Nuxt 3 uses an unplugin-based transformation layer to inject imports at build time. While it simplifies developer experience, it requires careful tree-shaking configuration to ensure unused auto-imported modules are correctly stripped, otherwise, the bundle size can grow unnecessarily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd284e194-1471-490e-a7d8-3d75c587e40a', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How do you manage theme switching (like Dark Mode) in Tailwind?', N'Middle', N'Tailwind provides a dedicated dark mode modifier that allows you to specify styles for light and dark themes using class or media-query strategies. This makes it trivial to toggle themes globally by simply changing a parent class or adjusting the browser''s preferred color scheme setting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56501b30-bebc-4b2f-a7a5-3d7a2f965492', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel''s Service Container implement the Dependency Inversion Principle, and what are the architectural trade-offs of using it extensively?', N'Senior', N'The Service Container acts as a central registry that binds abstractions to concrete implementations, allowing components to depend on interfaces rather than classes. The primary trade-off is increased architectural decoupling and testability, balanced against the overhead of runtime reflection and the potential for ''magic'' that can make the dependency graph difficult to trace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f0f07ce-5b8b-4db9-befa-3d7b4e8ad4d0', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you investigate a service that is reporting high error rates only in one specific availability zone?', N'Senior', N'I check for infrastructure-level issues such as network partition, misconfigured security groups, or localized resource constraints within that zone. I compare the traffic distribution and health check status of instances in that zone against others to rule out localized deployment artifacts or hardware failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47a2f663-b8f8-4274-9ccd-3d7b8b0376ac', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a database view?', N'Intern', N'A view is a virtual table based on the result-set of an SQL statement. It does not store data itself but displays data from one or more underlying tables, providing a simplified or restricted way to look at complex data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'794b797a-c8b9-449d-b657-3d7e691947a3', N'a2838158-7305-480a-b22b-4dc35776b400', N'What role does a message broker play in decoupling services?', N'Middle', N'A message broker acts as an intermediary, allowing producers to send messages without needing to know the location or state of the consumers. This asynchronous communication improves system scalability and resilience by buffering requests during traffic spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f80969b8-7dd3-4e09-bc01-3d811cd74730', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a JOIN in SQL?', N'Intern', N'A JOIN is used to combine rows from two or more tables based on a related column between them. It allows you to query data that is spread across different tables as if it were a single combined dataset.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83dbf5f6-dbae-4703-beed-3d8375aebd43', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is a ''process'' in the Elixir/Phoenix ecosystem?', N'Fresher', N'A process is a small, isolated unit of execution that maintains its own state and communicates with other processes via message passing. They are the fundamental building blocks that allow for high availability and fault tolerance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd889be88-d4f7-4c9a-b7be-3d837fa56f80', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the difference between Wide Rows and Tall Rows?', N'Junior', N'Wide rows have many columns for a single partition key, often used for time-series data. Tall rows have fewer columns but many rows spread across different partition keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d70e2ed-a5ba-470e-86e4-3d845c02ebc9', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How do you decide the appropriate size for a cache?', N'Middle', N'Cache sizing is based on a balance between available memory resources and the hit rate requirements of the application. It involves analyzing the frequency of access for different datasets and ensuring that the most critical or high-traffic items can reside in the cache simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c5f4bfa-2087-4837-a6d6-3d878f6a6df3', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why is Rocket''s preference for ''Zero-Cost Abstractions'' important for backend scalability?', N'Senior', N'Zero-cost abstractions ensure that high-level features like type-safe routing do not impose a runtime performance penalty compared to manual, imperative coding. This allows developers to write expressive, maintainable code without sacrificing the latency or throughput required for high-load production systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'724a5ca3-442d-4089-bcac-3d87f2e6617a', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle concurrent requests?', N'Intern', N'Because Litestar is built on the ASGI standard, it handles requests concurrently using an event loop. This allows the server to manage many connections simultaneously without waiting for one to finish before starting another.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e4f01d2-f99e-479c-91a5-3d8831e3fdcd', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When should you implement a Circuit Breaker pattern?', N'Middle', N'A circuit breaker should be implemented when a service depends on an external resource that is prone to failure or latency issues. It prevents cascading failures by stopping requests to the failing service, allowing it time to recover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'056dd079-79f4-4fd7-b2e4-3d884d290d4d', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby''s garbage collector handle objects?', N'Middle', N'Ruby uses a generational, mark-and-sweep garbage collector that tracks object references. It identifies unreachable objects by traversing the object graph and then reclaims their memory. Because it is a stop-the-world collector, frequent large allocations can cause noticeable latency in high-throughput applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ca33415-3937-4162-af5e-3d8b82f16a39', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the purpose of the ''buffer'' module?', N'Junior', N'The Buffer class is used to handle raw binary data in Node.js. Since JavaScript strings are typically UTF-16, Buffers allow developers to interact with octet streams, which is essential for file system operations or network communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d51eccc-12a1-4f21-87ed-3d90564ad277', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js handle data fetching in the App Router compared to the Pages Router?', N'Middle', N'The App Router utilizes the fetch API directly within Server Components to leverage built-in request memoization and caching. The Pages Router relied on specific data fetching functions like getServerSideProps or getStaticProps, which were tied to individual page files rather than component-level fetching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7dff711-1a19-43c7-92e7-3d950b3e4f1b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is event bubbling?', N'Intern', N'Event bubbling is a type of event propagation where the event first triggers on the innermost target element, and then successively triggers on the ancestors (parents) of the target element in the same nesting hierarchy till it reaches the outermost DOM element. Example: If you click on EM, the handler on DIV runs. Stopping bubbling: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a18461c-3cd9-47be-b80e-3d995b08339f', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket''s use of Rust''s ownership model prevent common backend vulnerabilities?', N'Senior', N'By leveraging Rust''s strict ownership and lifetimes, Rocket ensures that memory is managed automatically without a garbage collector. This eliminates common memory-related security issues, such as buffer overruns and use-after-free errors, which are frequently exploited in C and C++ web servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49a3cf91-01ac-4c90-b4cf-3d9b8365f2b2', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS support microservices?', N'Intern', N'NestJS has a built-in microservices package that allows developers to create applications that communicate over various transport layers like TCP, Redis, or RabbitMQ. It provides a consistent programming model for building distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db549ef0-fd51-4c4b-addb-3d9bbaf7ea4c', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js manage memory usage in large-scale applications with many routes?', N'Senior', N'Next.js uses code splitting to ensure that only the JavaScript required for the current route is loaded. Furthermore, the framework''s efficient caching and deduplication mechanisms prevent redundant data processing, which helps maintain stable memory usage even as the application grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'496c32c5-7272-4e08-9112-3d9ee06546dc', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the primary difference between eventually consistent and strongly consistent reads in DynamoDB?', N'Senior', N'Eventually consistent reads may return stale data as they read from a single replica before all updates have propagated. Strongly consistent reads return the most up-to-date data by reading from a leader node or ensuring quorum, though they consume double the read capacity units.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8819b907-c81e-4182-9c7d-3da017769e2b', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the primary difference between a process and a thread?', N'Fresher', N'A process is an independent program in execution with its own dedicated memory space, while a thread is a smaller unit of execution within a process. Threads share the same memory and resources of the parent process, making them faster to create and easier to communicate between. However, a failure in one thread can potentially crash the entire parent process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bd2f7a7-4693-46fb-a222-3da02204e19a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the main difference between localStorage and sessionStorage', N'Fresher', N'LocalStorage is the same as SessionStorage but it persists the data even when the browser is closed and reopened(i.e it has no expiration time) whereas in sessionStorage data gets cleared when the page session ends.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
