INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a94d803-e1e2-45fa-882a-3da630371b6d', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the impact of V8''s garbage collection on Node.js application performance, and how do you monitor it?', N'Senior', N'V8''s garbage collector can trigger ''stop-the-world'' pauses that stall the event loop, leading to latency spikes in high-throughput applications. You can monitor this using heap snapshots and performance hooks to track GC frequency and duration, adjusting memory limits or optimizing object allocation to mitigate pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
