INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd8fcfdc-cd0e-42c5-aae6-3db6314b75e5', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the significance of the ''progressive enhancement'' principle in SvelteKit?', N'Middle', N'Progressive enhancement ensures that the core functionality of an application remains accessible even if JavaScript fails to load or is disabled. SvelteKit facilitates this by encouraging the use of standard HTML forms and links that function natively, which are then enhanced with client-side interactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e18ca138-b537-47b5-8b25-3db682773f49', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How do you manage Django environment variables and secret management in a secure, containerized deployment?', N'Senior', N'Secrets should never be hardcoded or committed to version control; they should be injected via environment variables or secret management services like HashiCorp Vault. In containerized environments, these secrets can be mounted as ephemeral volumes or injected into the container runtime securely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8dd10bf1-9c56-40d4-be39-3db882e64207', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is polymorphism?', N'Intern', N'Polymorphism allows objects to be treated as instances of their parent class rather than their actual class. It enables a single interface to represent different underlying forms, such as through method overloading or method overriding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d1e795e-79a4-424d-b677-3dc141fa3581', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle environment variable management across different deployment stages?', N'Middle', N'AdonisJS uses a centralized env module that validates required variables against a schema during startup. This prevents the application from booting in an invalid state if essential configuration keys are missing or incorrectly formatted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'751ada43-f087-48a6-894d-3dc6be0f2cef', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why would you choose a relational database over a NoSQL database?', N'Junior', N'You would choose a relational database when your data is highly structured and requires strict consistency. Relational databases are excellent for complex queries, transactions, and scenarios where data integrity is the highest priority.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7fc4d31-183b-439f-b8d5-3dc88f9edae9', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the trade-off of implementing a sidecar pattern in a containerized environment?', N'Middle', N'A sidecar allows you to offload cross-cutting concerns like service discovery, logging, or security to a dedicated process, keeping the application code clean. The downside is increased resource consumption and complexity in managing the lifecycle of the additional container.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de39b2af-1bd4-4294-9d2f-3dcbb797bbb5', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of the ''unsafe'' keyword in Rust?', N'Middle', N'The unsafe keyword provides an escape hatch that allows the programmer to perform operations the compiler cannot verify, such as dereferencing raw pointers or calling FFI functions. It acknowledges that the programmer takes responsibility for maintaining memory safety, as the compiler''s safety guarantees are suspended within that block.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a3fc22b-ac2e-469d-a9e6-3dcc8de09aa2', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why is it generally discouraged to use Express for CPU-bound tasks, and what is the architectural solution?', N'Senior', N'Express runs on the Node.js event loop, which is single-threaded; CPU-intensive tasks block the loop and prevent it from handling other incoming requests. The architectural solution is to offload these tasks to a separate worker pool, message queue, or a dedicated microservice written in a language better suited for concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2bd9079-3dc4-4684-af35-3dcd7b278b60', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a rest parameter in TypeScript functions?', N'Junior', N'A rest parameter allows a function to accept an indefinite number of arguments as an array. In TypeScript, you can explicitly type this parameter to ensure all passed values adhere to a specific type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f1588d6-7c04-4b74-8ca9-3dcf2bb56bd4', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby implement constant lookup?', N'Middle', N'Ruby searches for constants starting in the current scope, then checks the nesting of modules or classes, and finally traverses the inheritance hierarchy. If it still fails, it checks the top-level scope. This can sometimes lead to unexpected results if constants with the same name exist in different lexical scopes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f19e3651-2c63-4869-9e98-3dcf6056648d', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the role of the ''Doctrine UnitOfWork'' in a Symfony application, and how does it impact memory usage?', N'Senior', N'The UnitOfWork keeps track of all loaded entities and their state changes to minimize database writes during flush operations. However, in large batch processes, it can lead to high memory consumption, necessitating manual clearing of the entity manager to free up resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
