INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aab9c9d9-7dc0-4173-a6f7-3dd419878a49', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is ''Taint'' and why was it removed from the Ruby language?', N'Senior', N'Taint was a security mechanism that marked objects originating from untrusted input to prevent their use in sensitive operations. It was removed because it was difficult to implement correctly, provided a false sense of security, and interfered with legitimate library operations, leading the community toward more robust input validation strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e609396f-01b4-4be0-88f0-3ddb3f0603c1', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between ES6 Map and WeakMap?', N'Fresher', N'Map: It is used to associate a key to a value irrespective of the datatype such as strings, numbers, objects etc. To assign values to a map you need to use the set method: Example: &#9885; Try this example on CodeSandbox WeakMap: The WeakMap object is a collection of key/value pairs in which the keys are weakly referenced. In this case, keys must be objects and the values can be arbitrary values. WeakMap accepts only objects but not any primitive values (strings, numbers) Example: &#9885; Try this example on CodeSandbox Difference between Map and WeakMap: 1. A WeakMap accepts only objects as keys whereas a Map, in addition to objects, accepts primitive datatype such as strings, numbers etc. 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
