INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b36e5256-1fcc-42bd-9f35-3dde92a70436', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Why might a database switch from an index scan to a full table scan even when an index exists?', N'Senior', N'If the query requires a large percentage of the table''s rows, the cost of performing random I/O through the index becomes higher than a sequential full table scan. The optimizer evaluates this cost and chooses the sequential approach to maximize throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdd9199a-141a-445f-ab39-3ddf00a0265f', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the significance of the order of route definitions in Chi?', N'Middle', N'Chi processes routes in the order they are defined. If multiple routes overlap, the first one that matches the request path will be executed, so developers must be careful to define more specific routes before general wildcard routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e11027b-8ca4-4b1b-ae30-3de155476a1d', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does the ''Observer'' pattern relate to the way React components interact with the Redux store?', N'Senior', N'Redux acts as an observable subject, and connected components act as observers. When the state changes, the store notifies all subscribers, which then re-evaluate their selector functions to determine if they need to update, effectively implementing the observer pattern to keep the UI in sync with the store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'279e84c6-e782-40d3-acaa-3de8e3a2445f', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What are the risks of ''Dependency Hell'' in microservices and how does it impact reliability?', N'Senior', N'Tight coupling between services creates a ''distributed monolith'' where a failure in one service triggers a chain reaction across the system. Reliability is maintained by enforcing loose coupling through API versioning, asynchronous communication, and defensive programming techniques.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
