INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d73e3b3-6e17-4fe5-af43-3e015a4566c8', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is a ''Repository'' in the context of Doctrine?', N'Junior', N'A Repository is a class dedicated to handling all database queries for a specific entity. It helps keep the database logic organized and separate from the controller logic, providing a clean API for fetching data from the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4da5965-1257-4fd0-bc73-3e02d543006a', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle component boundaries to enable granular partial hydration?', N'Senior', N'Qwik marks component boundaries during the build process, which allows the framework to treat each component as an independent entity. This granularity ensures that state changes in one component do not trigger the re-execution or loading of unrelated components, significantly optimizing performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5b53f9b-339a-4365-812b-3e082cc5d78e', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the benefit of using ''frozen_string_literal: true''?', N'Middle', N'Enabling this directive freezes all string literals in a file, preventing them from being modified and allowing them to be shared in memory. This reduces the number of object allocations performed by the garbage collector, leading to lower memory consumption and improved execution speed. It is a best practice for modern Ruby applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e9c1fef-6061-48f0-805f-3e087afe6d35', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the benefit of Vite''s ''on-demand'' loading?', N'Fresher', N'On-demand loading means Vite only processes the files that are currently needed by the active page. This prevents the tool from having to compile your entire project before you can see your changes, saving significant time as the project grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69a1d89c-d017-4270-9176-3e09591eba1f', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is CSS preprocessor?', N'Intern', N'Pre-processors extend CSS with variables, operators, interpolations, functions, mixins and many more other usable assets. After development, these specific files are compiled into regular CSS that any browser can understand. Pre-processor help writing reusable, easily maintainable and extensible codes in CSS. CSS preprocessors: * SASS (SCSS) * LESS * Stylus * PostCSS Advantages: * CSS is made more maintainable. * Easy to write nested selectors. * Variables for consistent theming. Can share theme files across different projects. * Mixins to generate repeated CSS. * Splitting your code into multiple files. CSS files can be split up too but doing so will require an HTTP request to download each CSS file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e3767e8-d64c-4765-8b52-3e0a03177fc3', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the benefit of using Sass maps?', N'Junior', N'Sass maps are key-value pairs that allow you to group related data, such as a color palette or breakpoints. They make your code cleaner by allowing you to iterate over a collection of values rather than creating individual variables for every item.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33f5f794-095a-449a-bb56-3e0f916ddb94', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'A user reports that a website feature is working for them but not for their colleague. How would you start troubleshooting this?', N'Junior', N'I would first compare the environment details, such as browser versions, operating systems, and network permissions. Then, I would ask the colleague to try reproducing the issue in an incognito window to rule out browser cache or extension interference.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7781a8e-bac3-49ed-a678-3e11816d5451', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is a form in HTML?', N'Intern', N'An HTML form is a container used to collect user input, such as text fields, checkboxes, or radio buttons. The form element acts as a wrapper that allows this data to be sent to a server for processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc318159-200e-48e4-94e1-3e13332eaab3', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the function of the Micronaut Inject annotation?', N'Intern', N'The inject annotation is used to tell the Micronaut container that a dependency should be satisfied by injecting an instance of a bean. It is a standard way to facilitate constructor, field, or method-based injection in the framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91e5a94d-6dd5-4e15-9822-3e1398ef140a', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the jQuery .css() method used for?', N'Intern', N'The .css() method allows you to retrieve the value of a CSS property or set one or more CSS properties for the matched elements. It provides a programmatic way to update the visual appearance of elements dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6bf3343-dad3-4278-b523-3e146dadc61c', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery help with event delegation?', N'Intern', N'jQuery uses the .on() method to attach event handlers to a parent element, which then catches events triggered by its descendants. This is efficient for handling events on elements that are added to the DOM dynamically after the page loads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10c892ad-a0d6-40da-831d-3e1479cf435a', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Why is ''Observability'' essential for maintaining large-scale distributed systems?', N'Senior', N'In large-scale systems, traditional monitoring is insufficient to diagnose non-deterministic bugs or latency issues. Observability via distributed tracing, centralized logging, and metrics provides the necessary visibility into service dependencies and request lifecycles to isolate failures effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'975783b7-aa01-480f-ac80-3e18909e043f', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'When designing a high-concurrency Flask application, why is WSGI typically considered a bottleneck compared to ASGI?', N'Senior', N'WSGI follows a synchronous, one-request-per-process/thread model, which blocks the worker while waiting for I/O operations like database calls or external API requests. ASGI enables asynchronous execution, allowing a single process to handle many concurrent connections by yielding control during I/O wait times, significantly improving throughput for I/O-bound systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bf5722c-b7fb-45a1-a5f8-3e18e03c65ab', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How do C compilers handle dead code elimination?', N'Senior', N'Compilers perform flow analysis to identify blocks of code that are unreachable based on constant folding and path analysis. If a branch is proven never to be taken, the compiler can remove that entire block from the generated machine code to reduce binary size and improve instruction cache efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08f5f1d0-999c-40e8-ad72-3e19353fede6', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is a handler function in Actix?', N'Intern', N'A handler function is a piece of code that receives an HTTP request, processes it, and returns a response. These functions are where the core business logic of an API endpoint resides.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93247356-92a6-4204-879b-3e1af7589de6', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby''s ''load'' differ from ''require''?', N'Middle', N'Require loads a library file once, even if called multiple times, and is used for importing dependencies. Load parses and executes the file every time it is called, which is useful for reloading code during development but generally inefficient for production dependency management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb2ed341-1846-4481-a609-3e1d18b31d2e', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Explain the interaction between Micronaut and GraalVM Native Image.', N'Senior', N'Micronaut was designed with GraalVM in mind, ensuring that all components can be compiled into a native binary without requiring manual configuration files for reflection. Since the framework avoids reflection and dynamic class loading, it eliminates the common barriers to successful native compilation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b2e7279-557f-44a3-88c7-3e1d863daaf3', N'954a0331-deff-4399-b588-96f39fec001d', N'How does Angular handle view encapsulation and what are the different strategies?', N'Fresher', N'Angular''s view encapsulation determines how the component''s styles affect the rest of the application and vice versa. Its main purpose is to isolate component styles to prevent conflicts and make components reusable. There are three strategies: - Emulated (Default): Angular adds unique attributes to component''s host element and its content, then scopes the CSS rules using these attributes. This prevents component styles from leaking out but allows global styles to affect the component. - ShadowDom (Available from Angular 6 onwards): Angular uses the browser''s native Shadow DOM API to attach a shadow root to the component''s host element. The component''s template and styles are placed inside this shadow root, providing true style isolation. - None: No view encapsulation is applied.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'024c72d9-527f-47ec-b52e-3e1f8445cbb5', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle a requirement that seems technically impossible given the current project constraints?', N'Fresher', N'I would research the limitations and document why the requirement cannot be met with the current resources. Then, I would propose alternative solutions or workarounds to the stakeholders that meet the core intent of the requirement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37c8e48b-a75d-45d0-ad2a-3e201979856a', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are ''inline classes'' and why are they used?', N'Middle', N'Inline classes, now renamed to ''value classes'', are a way to wrap a single value in a type-safe manner without the memory overhead of an extra object allocation. They are inlined into the underlying value at runtime, providing type safety with the performance of primitive types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ff23081-951b-490d-bc1c-3e204a6af9b9', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When you encounter an error, how do you prevent yourself from getting frustrated?', N'Intern', N'I view errors as necessary data points that tell me what does not work. Taking a short break allows me to return with a fresh perspective, which is often more effective than forcing a solution while stressed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d0bfefa-937f-4638-b6b5-3e225c938719', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Explain the concept of ''poison pill'' messages and strategies to mitigate them.', N'Senior', N'A poison pill is a malformed message that consistently causes a consumer to crash or fail during processing. Mitigation involves implementing a retry limit, moving failed messages to a DLQ, and ensuring that consumers have comprehensive exception handling to prevent service-wide outages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ed4aa72-2d7e-43b7-9e1b-3e229bd5b8a3', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the role of CSS Houdini in extending browser capabilities?', N'Senior', N'CSS Houdini provides low-level APIs that allow developers to hook into the browser''s rendering pipeline. It enables the creation of custom properties, layout logic, and paint worklets, effectively shifting tasks that previously required JavaScript or hacks into the native rendering engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
