INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33800398-8fbe-4cdf-9360-3e233fe89c32', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the impact of payload size on API throughput?', N'Middle', N'Larger payloads increase serialization and deserialization time, consume more bandwidth, and can lead to higher latency for the end user. Keeping payloads small through data filtering or pagination is essential for maintaining high throughput in high-traffic APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fec98abf-7a5b-4449-9294-3e2794b2487c', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the single source of truth principle?', N'Intern', N'The state of your whole application is stored in an object tree within a single store. This makes it easier to track changes, debug the application, and maintain state synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4919c819-2ae9-4b15-be80-3e2809dab052', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of the Spring Bean lifecycle?', N'Middle', N'The bean lifecycle defines the stages a bean goes through from instantiation to destruction within the Spring container. This allows developers to hook into specific phases using callbacks like @PostConstruct or InitializingBean to perform resource allocation or custom initialization logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b725357e-a917-41c7-af59-3e2967f01b10', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the ''cost of delay'' in project management and how does it affect technical decisions?', N'Intern', N'The cost of delay represents the economic impact of not having a feature or product available by a certain date. It forces engineers to prioritize features that provide immediate value over complex optimizations that could be handled in future releases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'158dfcb3-8307-4ae5-acaf-3e2b9ab213eb', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the role of the ''Validator'' in Echo?', N'Junior', N'Echo allows you to register a custom validator to verify the structure of data after it has been bound. By calling c.Validate, you can ensure that the request payload meets your business logic requirements before proceeding with the handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
