INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'779b60ff-f588-43ee-9e8e-3e5385b00093', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between ''let'' and ''var'' when defining a collection?', N'Intern', N'If you define an array or dictionary with let, the collection itself is immutable, meaning you cannot add, remove, or change its contents. If you define it with var, the collection is mutable and its contents can be modified after creation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90c6d849-6b9c-4e76-8523-3e5901346ed3', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are the trade-offs of using ''Static Site Generation'' (SSG) in Nuxt?', N'Middle', N'SSG offers excellent performance and security because it serves static files. However, it can lead to long build times for very large sites and requires a full rebuild whenever content changes, unlike server-side rendering which is always live.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3dc401c2-1e75-4db4-ac9e-3e5bd507ec59', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach a bug that you cannot reproduce?', N'Junior', N'I gather all available information, such as environment details, user actions, and error logs, to identify a pattern or commonality. If I still cannot reproduce it, I add more detailed logging or monitoring to the system to capture the event the next time it happens.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
