INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dae4740b-e78d-4d3f-99f5-3e5e916f5946', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the C abstract machine model memory visibility in the context of concurrent execution?', N'Senior', N'The C standard defines memory visibility through the concept of sequence points and the memory model introduced in C11. It assumes a single-threaded execution model unless atomic operations and memory fences are explicitly used to establish happens-before relationships across threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebe4a1fd-f476-4cf9-a7b9-3e5f92429dab', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the difference between a primary key and a unique constraint.', N'Middle', N'A primary key uniquely identifies each row and cannot contain null values, with only one allowed per table. A unique constraint ensures that values in a column are distinct, but it allows for null values and multiple unique constraints can exist on a single table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'795a6dd6-fb07-42cf-adc1-3e64d605a8df', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does Python handle memory management?', N'Intern', N'Python uses automatic memory management, primarily through a private heap space that stores all objects and data structures. It employs a reference counting mechanism and a garbage collector to reclaim memory that is no longer in use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b976ecbc-ec49-45b3-b457-3e67bfa86b21', N'075b8862-431c-4678-9767-f55359758a4a', N'Describe the mechanism behind Vue''s ''patch'' function in the virtual DOM diffing process.', N'Senior', N'The patch function compares the old virtual node tree with the new one to determine the minimal set of DOM operations required to update the view. It uses a key-based heuristic for list diffing and performs deep equality checks on props and event listeners to ensure efficient updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
