INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60fde377-74fb-4756-a6f6-3e6a56c2d9cd', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does the ''DispatchReceiver'' in Kotlin extension functions impact memory and object lifecycle?', N'Senior', N'Extension functions are resolved statically based on the declared type of the receiver, not the runtime type, and they do not actually modify the target class. Since they are compiled as static utility methods taking the instance as an argument, they do not add memory overhead to the instance but can lead to confusion regarding polymorphic behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
