INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcef71e6-b835-4ccd-91f3-3e800207831c', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the difference between a stack and a heap in the context of Rust?', N'Intern', N'The stack stores values in the order they get them and removes them in the opposite order, requiring all data stored to have a known, fixed size. The heap is used for data whose size may change at runtime, providing more flexibility but requiring the program to manage memory allocation and deallocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
