INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6042492-6c9f-4929-a328-3e869c3a3e54', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue''s virtual DOM reconciliation algorithm optimize updates in lists?', N'Senior', N'Vue uses a diffing algorithm that compares the new virtual DOM tree with the old one, optimizing list updates via the ''key'' attribute. By using keys, Vue can identify moved, added, or removed nodes rather than re-rendering the entire list, ensuring that components maintain their internal state and lifecycle during DOM mutations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1299eaf-f0ed-46c8-a614-3e8756e20545', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the ''N+1 Problem'' in ORM-based database interactions?', N'Middle', N'The N+1 problem occurs when an application executes one query to fetch parent records and then executes N additional queries to fetch related child records for each parent. This leads to excessive database round-trips and severe performance degradation, which is usually solved by using joins or eager loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
