INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3603776c-d27a-4912-965f-3e8d79eb7b6a', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does horizontal partitioning differ from vertical partitioning in databases?', N'Middle', N'Horizontal partitioning, or sharding, splits rows across multiple tables or databases based on a partition key. Vertical partitioning splits tables by columns, moving frequently accessed data to one table and less frequently accessed data to another to improve query performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd91898ce-d834-4fbb-ae2b-3e8d955b8acf', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'When should you use @Primary versus @Qualifier in Spring dependency injection?', N'Senior', N'Use @Primary to define a default bean when multiple beans of the same type exist, simplifying injection points. Use @Qualifier when you need to explicitly disambiguate between multiple implementations at specific injection sites, offering more precise control over which bean is utilized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f11b0529-9bab-42e5-b4a6-3e8dbf7f72cb', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a ''split-brain'' scenario in a cluster?', N'Middle', N'Split-brain occurs when a network partition causes a cluster to divide into two or more independent groups that cannot communicate. Each group may believe the other has failed, potentially leading to conflicting data updates and loss of consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1aa259a-762c-46fa-b916-3e8f9eb7c6a7', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do you ensure data consistency in an eventually consistent system during a partial outage?', N'Senior', N'You rely on conflict resolution strategies like Last-Write-Wins, vector clocks, or CRDTs to merge states once connectivity is restored. Designers must also implement reconciliation processes or read-repair mechanisms to identify and correct discrepancies that occurred during the partition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b86f809-925e-4fa2-b2ba-3e909428412c', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle CORS?', N'Junior', N'Axum handles Cross-Origin Resource Sharing (CORS) through the tower-http crate. You add the CORS middleware to your router to define allowed origins, methods, and headers for your API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dffcf98a-4585-43cd-9f62-3e90a4d6c6dc', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why is it generally discouraged to perform side effects directly in the component body rather than in useEffect?', N'Senior', N'React may call the component function multiple times during rendering for optimization or concurrent mode. Side effects in the body would execute unpredictably, causing memory leaks, inconsistent UI states, or unnecessary external API requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ea75d69-0ad0-4362-8c37-3e95c06cd179', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Does Remix use a virtual DOM?', N'Fresher', N'Remix uses React as its view library, so it utilizes the virtual DOM for efficient UI updates. However, its primary architectural focus is on server-side data synchronization rather than just managing the virtual DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c13127b0-e7c7-4191-bd2c-3e98dc88bdb3', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the primary trade-off when choosing between a monolithic architecture and microservices?', N'Middle', N'Monoliths are simpler to develop, test, and deploy initially, but they become difficult to maintain and scale as the team grows. Microservices offer better team autonomy, technology diversity, and granular scalability, but introduce significant complexity in deployment, monitoring, and inter-service communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fadabe95-7c30-4dfa-8b1c-3e99f5c3312c', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are the trade-offs of using header files for interface declaration in C?', N'Senior', N'Header files simplify the process of sharing interfaces across multiple translation units, but they can significantly increase build times due to repetitive parsing and inclusion. They also create tight coupling between modules, as changes to a header trigger a recompilation of all dependent files. Modern architectures often mitigate this by using opaque pointers and PIMPL-like patterns to hide implementation details and minimize dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f079349c-d695-4026-b010-3e9a11bc43f7', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are the scalability risks of using Webpack''s ''DllPlugin'' in modern development?', N'Senior', N'DllPlugin pre-builds stable dependencies to speed up subsequent builds. However, it requires manual maintenance and synchronization with the main build, which can lead to stale bundles and complex debugging if dependencies are updated independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40ba2b8c-819e-432f-ba6b-3e9acf44bb57', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the role of the ''createResource'' primitive in handling asynchronous data?', N'Middle', N'createResource is designed to handle asynchronous data fetching by tying a promise to a reactive state. It provides a built-in mechanism for managing loading, error, and data states, allowing the UI to reactively update as the promise resolves without requiring manual state management for each fetch request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8135c971-686b-45dc-a32b-3ea032eefad4', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Why would you choose Echo over a more minimal framework like Chi?', N'Middle', N'Echo is a feature-rich framework that comes with built-in middleware, data binding, and validation utilities out of the box. You would choose it when you want a batteries-included approach that minimizes the need to integrate third-party libraries for common web tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc9b5803-9d0b-45d4-886d-3ea0ec4b29fc', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle asynchronous request processing, and what are the trade-offs when mixing ''def'' and ''async def'' path operations?', N'Middle', N'FastAPI uses Starlette''s asynchronous capabilities to handle concurrent connections, allowing the server to process multiple requests without waiting for I/O operations to complete. When using ''async def'', FastAPI runs the function on the main event loop; if a blocking operation is called there, it freezes the entire application. When using standard ''def'', FastAPI runs the function in an external thread pool to avoid blocking the main loop, which adds a slight overhead but prevents event loop starvation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e185547a-9d08-4722-8c15-3ea2258ff1c4', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle transitions and animations?', N'Fresher', N'Svelte includes a built-in motion module that provides simple directives for applying transitions and animations to elements. These directives allow you to easily define how elements should enter or leave the DOM, managing the transition logic automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
