INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a381399-4f78-4c2f-8383-3ea6ba1c5326', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why should you avoid using the ''autofocus'' attribute in complex web applications?', N'Middle', N'Using ''autofocus'' can be disruptive to users who are navigating the page via screen readers or keyboard shortcuts, as it moves the focus unexpectedly. It can also interfere with the user''s intent if they are attempting to scroll or interact with a different part of the page while it is still loading. It is generally better to handle focus management programmatically after the component has rendered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9409ca20-ae7c-4244-b578-3eaab2382f00', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the significance of the ''synchronized'' keyword in Java?', N'Middle', N'The synchronized keyword provides mutual exclusion, ensuring that only one thread can execute a block of code or a method on a given object at a time. It also establishes a happens-before relationship, ensuring that memory changes made inside the synchronized block are visible to other threads entering the same block. Overuse can lead to performance bottlenecks and deadlocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8cfe318-58d8-4b93-992c-3eabed093dd1', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a buffered channel?', N'Junior', N'A buffered channel has a capacity defined at creation, allowing it to hold a specific number of values without requiring a receiver to be ready immediately. This helps prevent goroutines from blocking when sending data at a bursty rate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
