INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cafb598a-4727-4e24-959e-3eae07101a53', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'When designing an API for mobile clients, why is payload minimization critical?', N'Senior', N'Mobile clients often operate on unreliable or high-latency networks where bandwidth is expensive. Minimizing payload size through techniques like field selection, compression, and efficient data structures directly translates to faster application startup times and improved user engagement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54817f7a-a8ac-40c9-8f7f-3eaff8a2d5ab', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between shallow and deep comparison of objects?', N'Middle', N'Shallow comparison checks if two pointers or references point to the same memory address. Deep comparison involves checking the actual contents or values of the objects, which is often required to verify if two different objects are logically equivalent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ed8faf6-a3c0-4f5e-a333-3eb0d210d1b7', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What does the ''Copy'' trait signify, and how does it differ from ''Clone''?', N'Middle', N'The ''Copy'' trait allows types to be duplicated by simply copying bits, which is implicit and inexpensive. ''Clone'' is an explicit operation used for types that require complex setup, such as allocating heap memory, when being duplicated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa1a3694-4821-46a7-bade-3eb40e87c50c', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Can Astro be used to build a single-page application (SPA)?', N'Intern', N'Astro is primarily built for multi-page applications, but it can be configured to support SPA-like behavior. However, it is generally recommended to use other frameworks if your project is exclusively an SPA.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cfb5a82-b91f-4a36-ab40-3eb46c791fb3', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is children prop?', N'Intern', N'The children prop is a special prop in React used to pass elements between the opening and closing tags of a component. It is commonly used in layout and wrapper componnents. A simple usage of children prop looks as below, Here, everything inside ... is passed as children to the custom div component. The children can be text, JSX elements, fragments, arrays and functions(for advance use case like render props). See Class Note: There are several methods available in the legacy React API to work with this prop. These include React.Children.map, React.Children.forEach, React.Children.count, React.Children.only, React.Children.toArray.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83395e4f-18fe-4def-9980-3eb5ac075ecd', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is type safety a major advantage when designing Actix-based microservices?', N'Senior', N'Rust''s type system ensures that message protocols between actors are strictly defined and checked at compile time. This drastically reduces runtime errors related to malformed messages or unexpected state changes, which are common in loosely typed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e11e4da-c137-46e6-8fc6-3eba6edca23e', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the Scala programming language?', N'Intern', N'Scala is a high-level, statically typed programming language that integrates features of both object-oriented and functional programming. It runs on the Java Virtual Machine, allowing it to interoperate seamlessly with Java code and libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39be4281-405a-45ab-94ba-3ebaba22e026', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How are props passed from a parent component to a child component in Svelte?', N'Junior', N'Props are defined in the child component using the ''export'' keyword before a variable declaration. The parent can then pass data to the child by using the standard HTML attribute syntax.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65734d46-8ce1-4b22-a617-3ebb0ef8ebab', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of the ''updated'' lifecycle method?', N'Junior', N'The updated method is called after the component''s DOM has been updated. It is useful for performing post-render tasks, such as focusing an input field or interacting with third-party libraries that require the DOM to be present.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a02b74a-9f83-4ae4-9a5b-3ebbc1d23a75', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the significance of type narrowing, and how does control flow analysis facilitate it?', N'Senior', N'Type narrowing refines a broader type to a more specific one within a code block using checks like typeof, instanceof, or user-defined guards. Control flow analysis automatically tracks these checks to adjust the type signature at compile time, reducing the need for explicit type assertions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'242cdcaf-fa3e-4c63-8594-3ebc9b880664', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is a Symfony Bundle, and when should you create one?', N'Middle', N'A bundle is a structured directory that groups related features, services, and configuration, acting as a modular plugin for the framework. You should create one when you want to package reusable functionality that can be shared across different projects or to organize large-scale applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dafdb576-4953-4f09-b5dd-3ebcbbc34bb7', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is generator in JS?', N'Intern', N'Generator-Function: A generator-function is defined like a normal function, but whenever it needs to generate a value, it does so with the yield keyword rather than return. The yield statement suspends function''s execution and sends a value back to caller, but retains enough state to enable function to resume where it is left off. When resumed, the function continues execution immediately after the last yield run. Syntax: Generator-Object: Generator functions return a generator object. Generator objects are used either by calling the next method on the generator object or using the generator object in a "for in" loop. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff0ddb75-864a-4042-9f01-3ebcbe154bd6', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is meant by the ''opinionated'' nature of Spring Boot?', N'Intern', N'Spring Boot is opinionated because it makes default choices about frameworks and configurations based on common industry practices. These defaults can be overridden if necessary, but they allow developers to start projects quickly without manual setup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56d6264f-2324-4737-afb6-3ebde4111082', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How do Dart Isolates differ from traditional shared-memory threads?', N'Senior', N'Isolates are independent units of execution that do not share mutable state, communicating exclusively through asynchronous message passing. This architecture eliminates the need for complex locking mechanisms like mutexes or semaphores, effectively preventing race conditions at the language level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccfb7f9a-0986-467f-be27-3ec293763ff6', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle routing?', N'Intern', N'Echo uses a high-performance router that matches incoming request paths to registered handler functions. It supports static routes, path parameters, and query parameters to determine which code should execute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'781c87f7-a67d-45ff-b4f7-3ec87950b77b', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are the advantages and drawbacks of using interior mutability patterns like RefCell?', N'Middle', N'Interior mutability allows you to modify data even when you only have an immutable reference to it, which is useful for complex data structures like graphs. However, it shifts the enforcement of borrow rules from compile time to runtime, meaning that violating these rules will cause the program to panic rather than fail to compile.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7e42bac-e5ee-41cc-b2f7-3ec8ce9f32f2', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you justify the trade-off of introducing technical debt to meet a market deadline?', N'Fresher', N'It is justifiable if the business needs the product to survive or capture the market immediately. The trade-off is only valid if there is a clear, planned commitment to pay off that debt shortly after the release.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35e4573d-f84a-4802-bf9b-3ec97cb6e7cf', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain the features provided by Angular Language Service?', N'Fresher', N'Basically there are 3 main features provided by Angular Language Service, 1. Autocompletion: Autocompletion can speed up your development time by providing you with contextual possibilities and hints as you type with in an interpolation and elements. !ScreenShot 2. Error checking: It can also warn you of mistakes in your code. !ScreenShot 3. Navigation: Navigation allows you to hover a component, directive, module and then click and press F12 to go directly to its definition. !ScreenShot', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ffccd5e-7b69-419e-b26d-3ecbd1541578', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What does the ''sealed'' keyword do when applied to a class?', N'Junior', N'The ''sealed'' keyword prevents a class from being inherited by other classes. This is often used for security reasons or to ensure that the behavior of a specific class remains consistent and cannot be modified by subclasses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ad30137-03bf-4e4c-a809-3ecd3ef95a2a', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does useMemo differ from useCallback?', N'Middle', N'useMemo caches the result of an expensive calculation, returning the memoized value. useCallback caches the function definition itself, returning the memoized function to prevent unnecessary recreation of callbacks passed to child components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c833cf9-a969-4f0e-b904-3ecdd2cd0e9f', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Explain the architectural difference between Vite''s dev server and traditional bundlers like Webpack.', N'Senior', N'Vite leverages native ES modules in the browser to serve source files on-demand without bundling during development. Webpack bundles the entire dependency graph before starting the server, whereas Vite performs pre-bundling only for non-ESM dependencies using esbuild, resulting in significantly faster cold starts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eea027a7-bcff-4344-aaec-3ed3fcfd1bb4', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony''s ''Console'' component handle long-running processes to prevent memory leaks?', N'Senior', N'Long-running console commands must be designed to explicitly clear the EntityManager, reset the internal container services, or periodically exit to allow the operating system to reclaim memory. Failing to manage state in these processes will lead to progressive memory exhaustion, eventually causing the process to crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a885254-8a5e-46e6-a749-3ed416328286', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix handle requests compared to traditional request-response frameworks?', N'Fresher', N'Unlike many frameworks that spawn a new thread per request, Phoenix uses lightweight Elixir processes. This allows the system to handle thousands of concurrent connections with minimal memory overhead, making it highly responsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a6faca5-9196-46c2-ba47-3ed5ef8293be', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the ''Backends for Frontends'' (BFF) pattern?', N'Middle', N'The BFF pattern involves creating a separate backend service for each specific type of client, such as mobile or web. This allows each backend to tailor its API responses and data aggregation to the specific requirements of that client, improving performance and developer experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e32736b9-7c90-49bf-bdb9-3ed8187c7dab', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the primary difference between ''val'' and ''var'' in Kotlin?', N'Junior', N'''val'' is used to declare read-only variables, meaning the reference cannot be changed after initialization. ''var'' is used for mutable variables, allowing the reference to be reassigned to a different value later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd716ec9d-90ef-40ee-9f2a-3ed917bf3059', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Describe the impact of ''strict'' mode in a TypeScript configuration.', N'Middle', N'Enabling ''strict'' mode turns on a suite of strong type-checking options, including noImplicitAny and strictNullChecks. It significantly improves code quality and reduces runtime bugs by enforcing explicit type definitions and preventing null or undefined values where they are not allowed. It is highly recommended for all modern projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'495ed571-9f4d-47a9-aa03-3ed94581d036', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between serverless architecture and containerized services?', N'Senior', N'Serverless is excellent for event-driven workloads or intermittent traffic where costs scale to zero and maintenance is minimal. Containers are chosen for predictable, high-throughput workloads where fine-grained control over the runtime environment, networking, and predictable long-term costs are more important than the convenience of serverless.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4037b26-95a3-451f-a08d-3edf8741bf43', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If you suspect a third-party API is causing an issue, how would you verify this?', N'Junior', N'I would inspect the network traffic to see the requests being sent and the exact responses received from the API. I would then check the API provider''s status page or documentation to see if there is a known service outage or if my request payload is missing required fields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'063e2f83-7585-4c41-88e9-3edfe0d200b3', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Does DynamoDB support transactions?', N'Intern', N'Yes, DynamoDB supports ACID transactions, which allow you to perform multiple read or write operations as a single unit. This ensures that all operations in the transaction either succeed or fail together, maintaining data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'749df316-8d44-4313-babc-3edffed91c3a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you disable right click in the web page', N'Fresher', N'The right click on the page can be disabled by returning false from the oncontextmenu attribute on the body element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b55b587-0861-487d-a21b-3ee19d125186', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is ''Copy-on-Write'' (COW) and how does it optimize performance?', N'Middle', N'COW is an optimization where a value type is only copied when it is actually modified. Until a mutation occurs, multiple variables can point to the same underlying memory, reducing unnecessary allocations and copying.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fc49a15-4819-41a7-a2fc-3ee31019999e', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs between using feature flags for releases versus standard git-branch based deployment strategies?', N'Senior', N'Feature flags enable decoupling deployment from release, allowing for gradual rollouts and instant rollbacks, but they introduce ''dead code'' and complexity in testing combinations. Git-based branching is conceptually simpler but prevents the ability to test in production or toggle functionality without a full deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59dcd48e-6487-4433-813c-3ee453f7f911', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What are Fairings in the Rocket framework?', N'Intern', N'Fairings are middleware components that allow you to execute code at specific points in the application lifecycle. They can be used to inspect, log, or modify requests and responses as they pass through the framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17585c6c-fd69-43d7-ac0b-3ee65b3235d0', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the performance implications of complex type definitions on the TypeScript compiler''s build time?', N'Senior', N'Heavily nested conditional types, recursion, and excessive inference can cause the compiler to spend significant time resolving types. In large codebases, this significantly increases build latency, necessitating optimization strategies like limiting type depth and avoiding unnecessary complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f22df55-0132-4a58-b774-3ee746084abc', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of the ''Events'' system?', N'Junior', N'The events system allows you to decouple parts of your application by broadcasting and listening for specific actions. For example, you can trigger an event when a user registers to send them a welcome email without blocking the registration process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8630eead-5441-4716-955e-3ee91b735eb3', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Describe the architectural challenge of ''distributed state'' in stream processing applications.', N'Senior', N'Stream processing often requires stateful operations like windowing or joins, which are difficult to maintain in a distributed environment. Solutions involve using local state stores backed by a changelog topic to ensure that state can be recovered or migrated if a processing node fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38e916c3-4e55-4708-b6ff-3eea0c10f74d', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is your approach to debugging a system-wide failure that occurs only during a specific deployment window?', N'Senior', N'I would review the CI/CD pipeline logs for any changes in configuration, environment variables, or dependency versions that were rolled out during that window. I would also look for post-deployment automated tasks, such as database migrations or cache warming, that might be causing unexpected load or resource contention on the infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ab71f79-7b12-456b-bf88-3eeab87ea94c', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does the Ember Data library function?', N'Fresher', N'Ember Data is a library that simplifies the process of fetching, updating, and persisting data in an application. It provides a standardized way to communicate with backend APIs and manages the data state between the server and the frontend.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8519e1b-6207-47ec-807b-3effa0b14944', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What does it mean for a system to be ''scalable''?', N'Intern', N'Scalability refers to a system''s ability to handle increased load, such as more users or data, without degrading performance. A scalable system can grow by adding resources rather than requiring a complete redesign.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
