INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1e4cfa3-6f1a-490c-b409-3f01eebf5790', N'4c000000-0000-0000-0000-000000000005', N'What is the benefit of using an event-driven architecture?', N'Middle', N'Event-driven architecture promotes loose coupling between services because producers do not need to know who the consumers are. This enables a highly extensible system where new services can easily subscribe to existing event streams without modifying the producer logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74484fa3-f1ec-4029-a432-3f041363a5ca', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket ensure memory safety for request bodies?', N'Middle', N'Rocket uses buffered reading and strict length limits for incoming requests. By leveraging Rust''s ownership model, the data is safely managed in memory during the request lifecycle and automatically cleaned up, preventing memory leaks or buffer overflow vulnerabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
