INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acf8c4b7-a776-4908-acc2-3f0aad947710', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'When is it appropriate to use a message queue instead of synchronous HTTP calls?', N'Middle', N'A message queue is ideal when the task can be performed asynchronously, when you need to buffer traffic spikes, or when you need to decouple the producer from the consumer. Synchronous HTTP calls are better when immediate feedback or strong request-response guarantees are required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de9b5306-7ef7-474e-babd-3f0c19e263f4', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the trade-off between SQL and NoSQL databases?', N'Middle', N'SQL databases offer ACID compliance and structured data, making them ideal for complex queries and transactional integrity. NoSQL databases prioritize high availability, schema flexibility, and horizontal scalability, making them better suited for unstructured data or rapidly changing requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
