INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09b7664b-437b-4d74-bc01-3f116c887340', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the ''Transaction Isolation Level'' hierarchy?', N'Senior', N'The hierarchy proceeds from Read Uncommitted (lowest isolation), Read Committed, Repeatable Read, to Serializable (highest isolation). Each level progressively restricts the types of anomalies allowed, such as dirty reads, non-repeatable reads, and phantoms, at the expense of decreasing concurrency and performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85ffd825-d070-4528-b5e0-3f16e85a43ff', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What are the limitations of using Alpine.js for complex form handling and validation?', N'Senior', N'Alpine.js provides basic binding capabilities but lacks built-in complex validation schemas, form state management, or error handling middleware. For advanced forms, developers must manually manage dirty states, submission handling, and validation logic, which can lead to significant boilerplate and potential bugs compared to form-specific libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89a55ea2-0cf2-469e-b9ae-3f176246c6b5', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you approach capacity planning for a system with unpredictable traffic patterns?', N'Senior', N'I would utilize historical usage data to establish baselines and then implement aggressive horizontal auto-scaling triggered by predictive metrics rather than just reactive ones. I would also perform regular load testing and chaos engineering to understand the system''s breaking points and ensure that scaling triggers are correctly configured.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7367a05e-ecfb-4f01-920a-3f1aea67e8d2', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the features included in ivy preview?', N'Intern', N'You can expect below features with Ivy preview, 1. Generated code that is easier to read and debug at runtime 2. Faster re-build time 3. Improved payload size 4. Improved template type checking', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b23f34e-1ebf-4acf-98fd-3f1f508e1163', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs between implementing a circuit breaker versus simple retries in a service call?', N'Senior', N'Retries are effective for transient network glitches but can overwhelm a failing service if not combined with exponential backoff. Circuit breakers are essential for preventing cascading failure by stopping requests to an unhealthy service, allowing it time to recover before traffic is restored.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f828de49-a078-44e9-8075-3f22016187bb', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is ''mode'' in Webpack and what are the available options?', N'Intern', N'The mode configuration informs Webpack to use its built-in optimizations corresponding to a specific environment. The available options are ''development'', ''production'', and ''none'', with production mode automatically enabling optimizations like minification.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d91a329-2bb8-4180-abc9-3f2a720ec693', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How is Qwik different from traditional hydration-based frameworks?', N'Intern', N'Traditional frameworks perform hydration by downloading and executing all component JavaScript to attach event listeners. Qwik skips this entirely by serializing the application state into the HTML, allowing it to become interactive only when a user interacts with a specific element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f69ab5de-e604-4aee-912a-3f2cfd5687c2', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the trade-off between readability and utility-first styling?', N'Middle', N'The primary trade-off is that utility-rich HTML can become difficult to read for developers accustomed to traditional CSS. However, this is usually mitigated by using component-based frameworks that hide the styling complexity behind meaningful component names.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b12b6cbd-6774-4d84-8968-3f2f919e93da', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of Pydantic''s ''Field'' function?', N'Junior', N'The ''Field'' function is used to provide extra metadata and validation constraints to model attributes. You can use it to set default values, string lengths, or range restrictions for numerical values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52825c75-c95d-4eb1-8ab9-3f2fa017809b', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How do you optimize Laravel''s performance when dealing with N+1 query problems in complex object graphs?', N'Senior', N'The N+1 problem is mitigated by using eager loading, which fetches related model data in a single secondary query using an ''IN'' clause instead of individual queries per relationship. For complex scenarios, utilizing ''loadMissing'' or custom join clauses can further minimize database round-trips and prevent memory exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1f22b69-db82-40b9-a7e3-3f3203948114', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you create specific number of copies of a string', N'Fresher', N'The repeat() method is used to construct and return a new string which contains the specified number of copies of the string on which it was called, concatenated together. Remember that this method has been added to the ECMAScript 2015 specification. Let''s take an example of Hello string to repeat it 4 times,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'194574ea-86b7-48f6-91e1-3f35692481fd', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Can you use Preact without a build tool like Webpack?', N'Intern', N'Yes, Preact can be used by loading it directly via a script tag in an HTML file. While this is less common for large applications, it is a great way to start simple projects or experiment with the library without complex configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'672d1e7c-c836-44c7-9e3b-3f3dd25ff2f7', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why is ''side effect'' management usually externalized from reducers?', N'Senior', N'Reducers must remain pure functions to ensure predictable state transitions and ease of testing. Side effects, such as API calls or timers, are inherently unpredictable; by moving them to middleware or dedicated effect managers, you maintain the purity of the reducer while keeping the architectural concerns separated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adfa8f06-1e42-47f6-aaac-3f454394fa64', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux handle performance when the store state becomes very large?', N'Middle', N'Performance is managed by normalizing the state structure to avoid deep nesting and using memoized selectors to prevent unnecessary re-renders. Additionally, splitting reducers allows for more granular updates to specific parts of the state tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e13f3df-7976-45e0-be9a-3f467bc7366d', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the relationship between Hyper and Axum?', N'Fresher', N'Hyper is the low-level HTTP implementation that Axum builds upon. While Hyper provides the raw networking capabilities, Axum provides the high-level, developer-friendly abstraction layer for building APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba9378a5-68ec-4e39-9a74-3f516516685e', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is a Response object in Symfony?', N'Intern', N'A Response object represents the HTTP response sent back to the client. It contains the status code, the response headers, and the content body that will be rendered in the user''s browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aeeb04f8-1875-4a99-974d-3f56a946c751', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do databases typically handle recovery after a crash?', N'Junior', N'Databases use a transaction log or write-ahead log to keep track of changes. After a crash, the system replays the log to redo committed transactions that were not yet written to disk and undoes incomplete transactions that were in progress.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'821c5e3a-4ed8-4c79-b85d-3f56ebeeeb9c', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the advantages of using Redis Streams over traditional lists or pub/sub?', N'Middle', N'Redis Streams provide a persistent, append-only log structure that supports consumer groups and acknowledgement mechanisms. Unlike pub/sub, messages in a stream are stored, allowing consumers to process them at their own pace and recover missed data after reconnecting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1591837-6b89-47c4-8904-3f577cbf2533', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between the InnoDB and MyISAM storage engines regarding transaction support?', N'Middle', N'InnoDB is a transaction-safe storage engine that supports ACID compliance, row-level locking, and foreign keys. MyISAM, conversely, is non-transactional and uses table-level locking, which can lead to significant contention in write-heavy environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac677afb-be13-4646-9424-3f5b2ed05eb6', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What are the performance costs associated with using complex CSS selectors compared to class-based styling?', N'Senior', N'Complex selectors, such as deep descendant combinators, force the browser to traverse deeper into the DOM tree during the style recalculation phase. Using flat, class-based selectors allows the browser to perform O(1) lookups in the hash map of styles, which is significantly faster than recursively evaluating DOM relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59e7d693-920d-4f84-ab00-3f62523b6f2c', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How do you set a custom HTTP header in an Echo response?', N'Junior', N'You can set custom headers using the Response object available within the Context. It provides a Header method that allows you to add or modify key-value pairs before the response is sent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8820ab08-7ae8-44ea-b36a-3f63751edb36', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does a distributed lock manager (DLM) facilitate consistency in a sharded database environment?', N'Senior', N'A DLM ensures that distributed transactions or shared resources are accessed by only one process at a time across multiple nodes. While it guarantees correctness, it introduces significant overhead and can become a bottleneck, making it crucial to minimize the scope and duration of locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'552158e3-8d96-4d94-8a97-3f643e9dd411', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the difference between Cache and Session in Laravel?', N'Middle', N'The Cache is used to store data temporarily to improve performance, such as expensive query results. The Session is used to store information about the user across multiple requests, such as authentication status or temporary form data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcec71c0-cb18-4ca2-8d28-3f660ebde1b6', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How can you return a custom status code in Litestar?', N'Junior', N'You can return a custom status code by returning a ''Response'' object directly from your route handler. This object accepts the payload, the status code, and any custom headers you wish to include in the outgoing response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5332681-df6b-4468-9a19-3f6b515a5ca1', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Explain the performance advantages of Hono''s internal router implementation in high-concurrency environments.', N'Middle', N'Hono utilizes a Trie-based router, which provides highly efficient path matching regardless of the number of registered routes. Unlike frameworks that iterate through an array of regular expressions, Hono''s structure allows for O(1) or O(log N) lookup complexity, significantly reducing overhead during high-traffic request handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da5ac505-c39a-4c36-9d28-3f6c94990746', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit''s reactive property system improve performance compared to standard DOM manipulation?', N'Middle', N'Lit uses a reactive property system that triggers an asynchronous update cycle only when specific observed properties change. By batching these updates and utilizing a fast, lightweight virtual DOM-like approach via template literals, it minimizes unnecessary browser reflows and repaints compared to manual DOM updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
