INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a896c57-2cf8-42e5-a0b3-3f6d01bc9f5a', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is a template engine in the context of Express?', N'Intern', N'A template engine allows you to use static template files in your application to generate HTML markup dynamically. At runtime, the template engine replaces variables in a template file with actual values and transforms the template into an HTML file sent to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ef8693a-abbf-49a1-bb85-3f6feb747327', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the primary difference between a relational database and DynamoDB?', N'Intern', N'A relational database uses a structured schema with tables, rows, and columns based on SQL, whereas DynamoDB is a NoSQL, key-value, and document database. DynamoDB is designed for horizontal scalability and high performance at any scale, while relational databases typically prioritize complex queries and data consistency through rigid table relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7782a656-4ec4-4bae-a260-3f72dcc229ff', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django manage memory when processing very large querysets?', N'Senior', N'Django manages memory by using iterators and the .iterator() method, which fetches records in chunks rather than loading the entire result set into memory. Without this, attempting to iterate over a massive queryset will result in a crash due to excessive RAM consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17bd30e4-0617-45e4-b3f8-3f76208290bd', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does the ASP.NET Core request pipeline handle middleware ordering, and what are the architectural consequences of this design?', N'Senior', N'Middleware components are executed in the order they are added to the pipeline, forming a nested delegate chain. This design allows each component to perform logic before and after the next component, enabling powerful cross-cutting concerns like logging, authentication, and error handling to be injected independently of core business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a02402f3-e16b-4fe9-9e2d-3f77ade53a0f', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How should errors be structured in a professional API to support both machine and human readability?', N'Senior', N'Use standard HTTP status codes for high-level classification and a consistent JSON error schema containing a machine-readable error code, a human-readable message, and a trace ID. Including a link to documentation or a support portal helps developers troubleshoot integration issues more effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee053569-dbff-4795-ada3-3f7d48c5a6d2', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the function of ''RequestParts'' in Axum?', N'Middle', N'RequestParts provides a view into the request''s components without consuming the entire request body. This is useful for extractors that need to inspect headers or query parameters before deciding how to handle the payload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a29ce0a-cd4e-459a-872d-3f7dbf396cbf', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs when implementing multi-tenancy at the database level versus the application level?', N'Senior', N'Database-level multi-tenancy (e.g., separate schemas or databases) provides strong data isolation and easier compliance, but it is harder to manage and scale across many tenants. Application-level multi-tenancy (e.g., shared tables with tenant IDs) is easier to scale and maintain but requires extreme caution to prevent data leaks. I choose the approach based on the strictness of the regulatory requirements for the specific industry.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64ba379b-7636-4c3e-9423-3f7f73a9fee3', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is ownership in Rust?', N'Intern', N'Ownership is a set of rules that Rust uses to manage memory through a system of ownership with a set of rules that the compiler checks at compile time. Each value in Rust has a variable that is called its owner, and there can only be one owner at a time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c10a79ba-308d-4ebb-bb17-3f80de445750', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum differ from Actix-web in terms of its architectural foundation?', N'Middle', N'Axum is built directly on top of the Tokio stack and the Tower ecosystem, focusing on type-safe, ergonomic request extraction. Unlike Actix-web, which uses its own actor-based runtime and custom middleware system, Axum prioritizes compatibility with the broader ecosystem of HTTP services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc0b35fd-7407-47bc-b820-3f817fcce8f4', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does a health check endpoint help a load balancer?', N'Middle', N'A health check endpoint allows the load balancer to periodically query a service to verify its operational status. If the service fails to respond correctly, the load balancer removes it from the rotation, preventing traffic from being sent to an unhealthy instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'522953dd-b276-4fcc-b973-3f82e68b1a96', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the purpose of the Bind method?', N'Intern', N'The Bind method is used to map request data, such as JSON or form inputs, into a Go struct. It handles the type conversion and validation logic, reducing the amount of manual parsing required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4273e50-79ae-4779-b20f-3f86e39ca21e', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are middleware functions in the context of an Express.js application?', N'Intern', N'Middleware functions are blocks of code that sit between the raw request coming into the server and the final route handler. They have access to the request and response objects and can perform tasks like logging, authentication, or modifying the request data before it reaches the end controller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2c67183-9355-4bd8-a944-3f883e088ebf', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the Ember lifecycle sequence for a route?', N'Junior', N'When a route is visited, Ember typically calls the model hook, then setupController, and finally renders the template. This sequence ensures data is ready before the user sees the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
