INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f617425b-55bd-4284-96cc-3f977c1198d3', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do you achieve private attributes in Python?', N'Middle', N'Python does not enforce true private access, but it uses name mangling for attributes prefixed with double underscores, such as __var. This makes them harder to access from outside the class by renaming them to include the class name. It is effectively a convention to signal that an attribute should be considered internal to the implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86fa7fc2-7448-4732-b980-3f992d1188f4', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono''s ''validator'' middleware handle data integrity compared to schema-based validation libraries?', N'Senior', N'Hono''s validator middleware is designed to integrate seamlessly with libraries like Zod or Valibot, allowing for declarative schema validation of request bodies, query params, and headers. By validating at the entry point of the route, it ensures that only clean, type-compliant data reaches the business logic, preventing malformed inputs from polluting the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3db75216-aa67-4a3b-83df-3f997b9c8707', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix handle backpressure in actor communication?', N'Senior', N'Actix employs bounded mailboxes for actors. When a mailbox reaches its capacity, the sender is forced to wait or drop messages, effectively signaling the upstream producer to slow down and preventing memory exhaustion from unbounded message queues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
