INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd37b57b8-a5e4-4d6b-8713-3f9e92035aed', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the architectural significance of separating concerns between Express controllers and service layers?', N'Senior', N'Separating concerns keeps controllers focused solely on handling HTTP-specific logic, while service layers contain business rules. This improves testability, allows business logic to be reused across different entry points, and prevents the ''fat controller'' anti-pattern.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
