INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb8aec6d-6378-40f5-926a-3fb267eec88c', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How to kill child processes that spawn their own child processes in Node.js?', N'Fresher', N'If a child process in Node.js spawn their own child processes, kill() method will not kill the child process''s own child processes. For example, if I start a process that starts it''s own child processes via child_process module, killing that child process will not make my program to quit. The program above will not quit if my-command spins up some more processes. PID range hack: We can start child processes with {detached: true} option so those processes will not be attached to main process but they will go to a new group of processes. Then using process.kill(-pid) method on main process we can kill all processes that are in the same group of a child process with the same pid group. In my case, I only have one processes in this group. Please note - before pid.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
