INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac1879d1-f2a0-434b-a8e3-3fb4d2ed59f2', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How do environments differ from lists in R?', N'Middle', N'Environments are reference-based data structures where names are mapped to values, and they possess a parent-child hierarchy for scoping. Unlike lists, which are copied when modified, environments are mutable, meaning changes persist in-place without triggering a memory copy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
