INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bd6ccaa-c364-49ba-bec6-3fbf9b5cc4db', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach API versioning in a public-facing system to minimize client disruption?', N'Senior', N'I prefer URI versioning or header-based versioning to maintain explicit control over the contract. To ensure backward compatibility, I enforce strict schema evolution rules and use deprecation warnings in response headers long before removing support for older versions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86a1388b-dc41-4b9b-94bc-3fc157eff35c', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is try Block?', N'Intern', N'A block which is preceded by the try keyword is known as a try block Syntax: try{ //statements that may cause an exception } The statements which causes to run time errors and other statements which depends on the execution of run time errors statements are recommended to represent in try block While executing try block statement if any exception is raised then immediately try block identifies that exception, receive that exception and forward that exception to except block without executing remaining statements to try block.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e22a5a4b-4f83-44d3-ad43-3fc237e0facf', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is Express.js, and how does it relate to Node.js?', N'Intern', N'Express.js is a web application framework that runs on Node.js. It simplifies the process of building web applications and APIs by providing a range of powerful features, including robust routing, middleware support, and HTTP utility methods. Thanks to its modular design, you can expand its functionality through additional libraries and Node.js modules. Key Features - Middleware: Express.js makes use of middleware functions that have access to the request-response cycle. This allows for a variety of operations such as logging, authentication, and data parsing. - Routing: The framework offers a flexible and intuitive routing system, making it easy to handle different HTTP request methods on various URLs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59d84294-5656-4094-b929-3fc30e5b3a34', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Why is idempotency critical when dealing with message queues?', N'Middle', N'Because messaging systems often guarantee at-least-once delivery, there is a risk that a message might be processed more than once. Idempotency ensures that the system state remains consistent regardless of whether a message is processed once or multiple times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bb7f570-cda2-429e-8f07-3fc393182a63', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB handle data partitioning internally?', N'Middle', N'DynamoDB automatically partitions data based on the partition key value and distributes these partitions across multiple physical servers. As the table grows or traffic increases, DynamoDB automatically splits partitions to maintain performance and capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9267a5ff-3424-4ceb-8d3c-3fc3b65f8716', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why might you introduce a cache into a system design?', N'Intern', N'Caches are used to store frequently accessed data in high-speed memory to reduce latency and decrease the load on the primary database. This improves overall system performance and responsiveness for the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48085f86-7875-4290-9e68-3fc4736b8802', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What are the architectural benefits of Litestar''s ''Controller'' classes compared to function-based views?', N'Senior', N'Controllers allow for better grouping of related business logic and shared configurations, such as dependencies or guards, at the class level. This leads to a more modular codebase where shared state and behavior are encapsulated, improving readability and maintainability in large-scale applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9037b6ea-62c4-40cc-b5bf-3fc4e15f4235', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the Kestrel web server?', N'Fresher', N'Kestrel is a cross-platform, open-source web server included by default in ASP.NET Core projects. It is designed to be fast and lightweight, serving as the primary server that listens for incoming HTTP requests and passes them to the application pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61e2643e-78ec-4a3f-8cc7-3fc79ddc9928', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the role of the ''signals'' feature in Flask?', N'Middle', N'Signals allow decoupled parts of the application to notify each other when specific events occur, such as a request starting or a template rendering. This allows you to add functionality, like logging or analytics, without modifying the core business logic of the view functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56c291bf-5832-47b2-9556-3fca7774d937', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Describe the purpose of FastAPI ''BackgroundTasks'' and when they should be used.', N'Middle', N'BackgroundTasks allow you to run post-response operations, such as sending emails or processing logs, without delaying the response sent to the client. They should be used for lightweight tasks, as they run within the same process and will be terminated if the server process restarts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67a8c87b-2d4a-4d26-80e8-3fcd2be31e0f', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'In what scenario would you favor a Sass function over a mixin?', N'Senior', N'You should use a function when the goal is to perform a calculation or transform data and return a value to be used in a property. A mixin should be used when you need to generate multiple CSS declarations or output blocks of styles based on input arguments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efe9070b-06f7-4461-8f07-3fd09e972cb9', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s router handle path parameter ambiguity, such as conflicting static and dynamic routes?', N'Senior', N'Echo''s router enforces a strict precedence rule where static routes are evaluated before parameterized routes. This prevents ambiguity, but developers must be aware that defining overlapping route patterns will result in the first matching route being selected based on the internal radix tree construction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c37734e0-6ec8-441b-9292-3fd141955a28', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are local and global variables in Python?', N'Junior', N'Local variables are defined inside a function and are only accessible within that specific function scope. Global variables are defined outside any function and can be accessed throughout the entire script, though they should be modified with caution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a5e08b2-4bde-49f9-85f3-3fd1a5cfccd3', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is an Inversion of Control (IoC) container?', N'Intern', N'The IoC container is the core of the Spring Framework, responsible for instantiating, configuring, and assembling objects known as beans. It manages the lifecycle of these objects and handles their dependencies, allowing for loose coupling in the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6ab803c-a134-41ac-b7f0-3fd218758e26', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is a Universal application?', N'Intern', N'A Universal application is an app that can run both on the client and the server. This allows for the benefits of server-side rendering on the initial load and client-side navigation for a fast, app-like experience afterward.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
