INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0213cb7f-d2f1-4044-99e8-3fd390a583f5', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the advantage of using a CDN (Content Delivery Network) for static assets?', N'Junior', N'A CDN caches static assets like images and scripts on servers geographically closer to the end user. This significantly reduces latency and reduces the load on your origin server, improving the overall performance and speed of your application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79442aaa-80ce-463a-853f-3fd4bad87739', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you determine the optimal database technology for a service with high write throughput?', N'Senior', N'I analyze the data access patterns, specifically whether the workload is write-intensive or requires complex relational joins. I often favor LSM-tree based storage engines or NoSQL solutions that decouple writes from reads, and I assess the necessity of ACID properties versus the availability gains of eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aeec26c9-4ac2-4b9e-8467-3fd6bb025caf', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain the purpose of the method lookup path in Ruby''s class hierarchy.', N'Middle', N'When a method is called, Ruby searches for it in the object''s class, then moves up through superclasses and included modules. This mechanism, known as the Ancestors chain, allows for method overriding and modular code reuse. Understanding this path is crucial for debugging why a specific version of a method is being invoked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29e07919-d6c4-4e50-a4ba-3fd6f273128c', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why does Rust require explicit ''Sync'' implementations for types containing ''Cell''?', N'Senior', N'Cell uses interior mutability to provide non-thread-safe mutation, which would lead to data races if shared across threads. Because the compiler cannot prove the safety of these operations in a multi-threaded context, it prevents such types from implementing Sync, effectively blocking their use in concurrent shared state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e92a2d9b-09d3-44d5-84f5-3fd829a846a9', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is a Migration ''rollback''?', N'Fresher', N'A rollback is the process of undoing the last set of migrations that were applied to the database. It is useful when you need to revert changes to the schema or correct errors introduced by a recent migration file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13ab24ca-1a0c-428f-b13a-3fd99f09a92e', N'954a0331-deff-4399-b588-96f39fec001d', N'Why is it important to use ''DestroyRef'' in modern Angular applications instead of the ''ngOnDestroy'' lifecycle hook?', N'Senior', N'DestroyRef allows for the registration of cleanup logic from outside of a class, such as within a functional provider or a standalone utility. This enhances composability and enables the development of cleaner, reusable logic that is not strictly bound to the component class lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3865589-243d-48e0-8986-3fdb0d00c30f', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the primary purpose of a database schema in PostgreSQL?', N'Fresher', N'A schema is a namespace that contains database objects like tables, views, and indexes. It helps in organizing database objects into logical groups and prevents naming conflicts between different tables or objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3591fa7-9257-4c24-983f-3fdce7c4cb5f', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the impact of Chi''s dependency on the standard library for long-term project viability?', N'Senior', N'Because Chi is a thin wrapper around net/http, it is essentially future-proof against changes in the core language. If the standard library evolves, Chi''s reliance on standard interfaces ensures that it remains compatible with future Go versions without requiring extensive refactoring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'324f6c36-e5cb-49c9-835d-3fdd1bcf2080', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are proxies in JavaScript used for?', N'Intern', N'In JavaScript, a proxy is an object that acts as an intermediary between an object and the code. Proxies are used to intercept and customize the fundamental operations of JavaScript objects, such as property access, assignment, function invocation, and more. Here''s a basic example of using a Proxy to log every property access: Use cases include: - Property access interception: Intercept and customize property access on an object. - Property assignment validation: Validate property values before they are set on the target object. - Logging and debugging: Create wrappers for logging and debugging interactions with an object. - Creating reactive systems: Trigger updates in other parts of your application when object properties change (data binding).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b8e1bd0-6d8b-4c76-9e50-3fdd58536736', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are the limitations of Svelte''s build-time approach in the context of dynamic component loading?', N'Senior', N'Since Svelte relies on static analysis, dynamic component instantiation can sometimes be more complex compared to frameworks that resolve component trees entirely at runtime. Developers must ensure that dynamic imports are handled correctly by the bundler, as the compiler needs to know enough about component relationships to generate optimal update code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10cf98f7-a064-4769-a0c7-3fdfefe5b461', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the primary role of the Rocket ''Request Guard'' mechanism?', N'Middle', N'Request Guards are a type-safe mechanism used to validate incoming requests before they reach a handler. They allow you to define custom logic to authenticate users, parse headers, or verify state, ensuring that only valid requests can proceed, which promotes cleaner and safer code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f4a3c66-6374-43f0-ac7e-3fe59418b289', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When faced with two conflicting requirements, how do you decide which one to follow?', N'Fresher', N'I would analyze the business value and the impact on the end user for each requirement. I would then consult with stakeholders or my lead to clarify priorities and ensure my decision aligns with the overall project goals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd9da57f-984a-4045-b852-3fe9d11982ad', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What does ''fault tolerance'' mean in the context of the BEAM?', N'Intern', N'Fault tolerance refers to the ability of the system to continue operating even when one or more components fail. It is achieved through supervision trees that can restart crashed processes automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e0f303f-fbbd-47f6-9ea1-3fee7833e8df', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How does modularity contribute to the long-term maintainability of a system?', N'Intern', N'Modularity divides a system into independent, interchangeable parts that can be developed and tested in isolation. This structure allows teams to upgrade or fix specific segments of the application without needing to understand or redeploy the entire system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dad3ba6d-60b3-47e4-b565-3fef5f3f13b7', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS differ from Express.js?', N'Fresher', N'Express.js is a minimalist, unopinionated framework where developers must choose their own libraries for tasks like ORM or validation. AdonisJS is a full-featured, opinionated framework that provides a standardized set of tools out of the box, enforcing a specific project structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7734d49f-971c-4ac2-b1f5-3ff2f6899c57', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Explain the benefit of Type Hinting in FastAPI for large-scale codebases.', N'Senior', N'Type hints in FastAPI are not just for documentation; they drive the validation engine and enable IDE features like static analysis and autocompletion. In large codebases, this significantly reduces runtime errors, improves developer productivity, and makes the API contract explicit and easier to refactor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94ecbacc-4b13-4642-b566-3ff63645f016', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is a source map and why is it important during development?', N'Junior', N'A source map is a file that maps your compiled, bundled code back to your original source files. It is crucial for debugging because it allows you to see your original, readable code in the browser''s developer tools instead of the minified or transpiled output.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a528b7d-baf8-447b-b555-3ff6d30603eb', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby''s method lookup path work when using modules?', N'Middle', N'When a method is called, Ruby searches the receiver''s class, then its included modules in reverse order of inclusion, and then the superclass. This hierarchy ensures that modules mixed into a class are prioritized over the class''s own superclass methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
