INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44f36a31-9a91-4a84-b0ad-3ffb8d333223', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you decide between server-side rendering and client-side rendering for a web application?', N'Middle', N'I base the decision on SEO requirements and initial page load speed. Server-side rendering is better for content-heavy pages requiring SEO and fast perceived loading, while client-side rendering is often more efficient for highly interactive applications after the initial load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
