INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f24373dd-9d0b-4fc5-b54e-4022a159ff4e', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web manage shared state across different workers in a multi-threaded environment?', N'Senior', N'Actix-web uses an ''AppData'' container, which is shared across all worker threads. To maintain safety, the data must be wrapped in thread-safe primitives like Arc and Mutex or RwLock, ensuring that multiple workers can access the state without violating memory safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a8f980a-da5a-4d62-a417-4022bca0c790', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum relate to the Tower library?', N'Junior', N'Axum is built on top of Tower, which provides a collection of abstractions for building robust networked services. Axum uses Tower services, layers, and filters to handle middleware and request processing, allowing developers to reuse ecosystem-wide components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18091af5-45d5-42d3-b391-40286a83ee2f', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you use various CDNs?', N'Fresher', N'VueJS is available in jsdelivr, unpkg and cdnjs etc CDNs. Normally you can use them for prototyping or learning purposes. For example, you can use them using jsdelivr with latest versions as below, You can use it for native ES modules as below, Note: You can remove version number to get latest version.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ca8d54a-5bac-44bb-9a8c-402b294d70d4', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between an Exception Filter and a Middleware for error handling?', N'Intern', N'Middleware handles errors that occur anywhere in the request pipeline, making it useful for global error catching. Exception filters are specific to controllers or actions and provide more granular control over how errors are handled within those contexts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'671ba9a9-bfaf-4666-9ae9-402baf28b0fb', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a Flask blueprint?', N'Intern', N'A blueprint is a way to organize a Flask application into modular components. It allows developers to group related routes, templates, and static files, making the application easier to maintain and scale as it grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ade07d62-c8d3-4dad-b267-402c96d0c12f', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the significance of the ''App Router'' cache?', N'Senior', N'The App Router cache serves as a client-side memory store that persists navigation data across the session. It allows Next.js to reuse rendered segments of the page, significantly speeding up subsequent navigations and reducing the load on the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf5a5b28-edd5-43e2-9256-402edbb9f7b4', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Why is testing in Nuxt different from standard Vue testing?', N'Middle', N'Testing in Nuxt requires mocking the Nuxt environment, such as the router, runtime config, and global composables. You often need to use ''nuxt-vitest'' or similar tools to ensure that the Nuxt-specific lifecycle hooks and dependencies are correctly initialized in the test environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c21c8d0-43b7-4c5f-a792-403400b820ae', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the purpose of the ''base'' element?', N'Middle', N'The base element specifies the base URL for all relative URLs contained within a document. It is useful when you have many links pointing to the same subdirectory or when you want to force all links to open in a new tab by setting a target. It must be placed inside the head element and there can only be one per page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb87efc0-4b9f-4d34-a38d-4035ad3ab47a', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does database replication improve read scalability?', N'Middle', N'Database replication involves copying data from a primary node to one or more secondary replicas. By directing read-only traffic to these replicas, the system can distribute the query load, allowing the primary node to focus on write operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f116609e-1b54-4a67-b244-403788e9f51d', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the difference between React Node, React Element, and a React Component?', N'Fresher', N'A React Node is anything React can render: a React Element, a string, a number, an array of nodes, a fragment, a portal, null, undefined, false, or true. A React Element is the immutable plain object React produces from JSX or React.createElement describing what to render. A React Component is a function (or, historically, a class) that accepts props and returns React Nodes. Elements describe the UI; components are the factories that produce those elements. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed0d9ada-35d8-4de7-b1f4-403cf897ca52', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the primary architectural advantage of using FastAPI''s asynchronous support?', N'Middle', N'Asynchronous support allows the server to handle high-concurrency I/O-bound tasks, such as database queries or external API calls, without blocking the main execution thread. This significantly improves throughput and resource utilization compared to traditional synchronous frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4a0aaee-e7aa-42da-af5f-403eb36de3c9', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is an object expression in Kotlin?', N'Junior', N'An object expression creates an anonymous object that implements one or more interfaces or extends a class on the fly. It is useful for one-time implementations like interface callbacks or event listeners without creating a separate named class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05889714-cc25-4955-86eb-403f949c01ed', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'In the context of API design, what is the trade-off between a RESTful API and a GraphQL API?', N'Junior', N'REST is simple to implement and takes advantage of standard HTTP caching, but it can lead to over-fetching or under-fetching of data. GraphQL allows clients to request exactly what they need in one call, but it adds complexity to the server-side implementation and makes caching more challenging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b1799bd-3c54-4eaa-abc2-4041d5a009f6', N'a2838158-7305-480a-b22b-4dc35776b400', N'Explain the concept of a Dead Letter Queue (DLQ).', N'Middle', N'A DLQ is a service-level queue that holds messages that could not be processed successfully by a consumer after multiple attempts. It allows developers to inspect and debug problematic messages without blocking the main processing pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a045b6a-72ad-44a8-ad1b-404268745801', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the impact of network latency on microservices?', N'Middle', N'Microservices frequently involve inter-service communication over a network, which introduces latency compared to in-process calls. Excessive service chaining, known as the ''chatty'' service problem, can lead to significant performance degradation, necessitating strategies like data caching or request batching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afeeec5d-c329-4f35-a96e-4043dd90397b', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the difference between .attr() and .prop()?', N'Intern', N'.attr() is used to get or set HTML attributes as they are defined in the HTML markup. .prop() is used to get or set the current state of a property of the DOM object, such as whether a checkbox is currently checked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e58fa399-579a-41bf-b5ee-404434848915', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the most important factor in maintaining trust with stakeholders regarding your estimates?', N'Junior', N'Transparency is the most important factor, especially when things do not go as planned. Providing honest updates early and explaining the ''why'' behind any delays builds a foundation of reliability and demonstrates that I am managing the project responsibly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'236e4974-c970-4797-823e-40451376b090', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Discuss the architectural impact of choosing between synchronous REST and asynchronous event-driven API communication.', N'Senior', N'Synchronous REST provides immediate feedback and is simpler to implement but creates temporal coupling and cascading failure risks. Asynchronous event-driven designs decouple services and increase resilience by allowing for buffering and retries, though they require complex eventual consistency models and distributed tracing to monitor data flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
