INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4976b7a-a949-48a8-9dee-405695bde953', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How do you handle authentication in an Astro project?', N'Middle', N'Authentication is typically handled using server-side cookies or session tokens within middleware. Since Astro supports server-side logic, you can protect routes and validate user sessions before sending the HTML response to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccd0cc08-a9e2-43e2-886b-40588bf0f20f', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using an off-the-shelf library versus building a custom solution?', N'Intern', N'Off-the-shelf libraries save development time and are usually well-tested, but they may include unnecessary features or limit customization. Building a custom solution offers total control and a tailored fit but requires a higher upfront investment in development and ongoing maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a191c0cd-ddc7-4a4d-9b32-405a40a8f00e', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle form submissions without JavaScript?', N'Fresher', N'Remix is built on standard web technologies, so it supports native HTML forms even if JavaScript is disabled in the user''s browser. The server receives the form data directly, processes it via the action function, and redirects the user accordingly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
