INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'255850ed-c5eb-4f52-8380-4061a5d4195f', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is useReducer? Why do you use useReducer?', N'Intern', N'The useReducer hook is a React hook used to manage complex state logic inside functional components. It is conceptually similar to Redux. i.e, Instead of directly updating state like with useState, you dispatch an action to a reducer function, and the reducer returns the new state. The useReducer hook takes three arguments: * reducer: A function (state, action) => newState that handles how state should change based on the action. * initialState: The starting state. * dispatch: A function you call to trigger an update by passing an action. The useReducer hook is used when: * The state is complex, such as nested structures or multiple related values. * State updates depend on the previous state and logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f28fb88-8115-4de6-a2d5-406264ccba40', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the purpose of the ''assets'' folder in Nuxt?', N'Fresher', N'The assets folder is used to store files that require processing by a build tool, such as CSS, SASS, or image files. These files are compiled and optimized during the build process to ensure better performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'824d1695-34f3-4120-92e7-4063a3d661c8', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the function of the HttpServer struct?', N'Fresher', N'The HttpServer struct is responsible for starting the web server, listening for incoming network connections, and dispatching requests to the configured application. It manages the server''s lifecycle and worker threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89d617af-eec4-4952-8f73-4065077aefca', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the ''chi.Context'' used for?', N'Fresher', N'The chi.Context is used to store request-scoped data, such as URL parameters or values set by middleware. It allows this information to be passed along the request chain to the final handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29e98908-a9ac-4e89-9799-40661db020fa', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is strict mode?', N'Intern', N'The Strict Mode is allows you to place a program, or a function, in a strict operating context. This strict context prevents certain actions from being taken and throws more exceptions. Example: Advantages: * Makes it impossible to accidentally create global variables. * Makes assignments which would otherwise silently fail to throw an exception. * Makes attempts to delete undeletable properties throw (where before the attempt would simply have no effect). * Requires that function parameter names be unique. * this is undefined in the global context. * It catches some common coding bloopers, throwing exceptions. * It disables features that are confusing or poorly thought out.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a68fbef7-36f6-4253-a088-406648f6f30f', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the primary purpose of the Swift programming language?', N'Intern', N'Swift is a general-purpose, multi-paradigm programming language developed by Apple. It is designed to be safe, fast, and interactive, primarily for developing applications across Apple platforms like iOS, macOS, watchOS, and tvOS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7426faee-d56f-4295-81ae-406799fbf33d', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why we need to be careful when spreading props on DOM elements?', N'Fresher', N'When we _spread props_ we run into the risk of adding unknown HTML attributes, which is a bad practice. Instead we can use prop destructuring with ...rest operator, so it will add only required props. For example,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed0b516c-c7a1-488f-a278-406a0fd90f88', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is Coercion in JavaScript?', N'Intern', N'Type coercion is the automatic or implicit conversion of values from one data type to another (such as strings to numbers). Type conversion is similar to type coercion because they both convert values from one data type to another with one key difference — type coercion is implicit whereas type conversion can be either implicit or explicit. Example: In the above example, JavaScript has coerced the 10 from a number into a string and then concatenated the two values together, resulting in a string of 1020. JavaScript had a choice between a string or a number and decided to use a string.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a06098d0-a80b-4b04-95ef-406e6031f258', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Why is the default Flask development server unsuitable for production, and what are the architectural requirements for a production-grade deployment?', N'Senior', N'The development server is single-threaded and lacks robust error handling, security features, and process management capabilities. A production deployment requires a production-grade WSGI server like Gunicorn or uWSGI to handle process forking, request queuing, and integration with a reverse proxy like Nginx for SSL termination and static file serving.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4978a2b-3db7-4c0b-9e4e-4072094b99fa', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What does it mean that Ruby is a dynamic language?', N'Intern', N'Being a dynamic language means that code execution happens at runtime, and variables do not require explicit type declarations. The language determines the type of an object during execution, allowing for flexible and adaptable code structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fed0c1de-394a-4f7d-a3a5-40734e923538', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the purpose of the ''Provider'' scope and how does its misuse affect memory usage?', N'Senior', N'The provider scope dictates the lifetime of a dependency, with singleton being the default and most memory-efficient. Misusing ''request'' or ''transient'' scopes causes the DI container to create new instances excessively, which increases memory consumption and impacts the performance of the garbage collector in high-concurrency scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32eefcb7-ae6c-445d-8a1c-4075a510f490', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin''s delegation pattern differ from traditional inheritance?', N'Senior', N'Delegation implements the composition-over-inheritance principle by delegating interface implementation to a specific object instance. This avoids the fragility of deep inheritance hierarchies and allows for dynamic behavior changes at runtime by swapping the delegate object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5e1a595-e0fd-4f5a-b3cf-4075bfd5c5f3', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the purpose of the ''CatchBoundary'' or ''errorElement'' in Remix?', N'Middle', N'These components handle non-error responses like 404 Not Found or 401 Unauthorized status codes. They allow you to show specific UI feedback to the user based on the server response, keeping the application robust and informative.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb3cc2c4-b5a3-4747-8096-40776bea3019', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the role of an adapter in SvelteKit?', N'Fresher', N'An adapter is a plugin that takes your built SvelteKit application and transforms it into a format suitable for a specific deployment platform. Examples include adapters for Node.js, Vercel, Netlify, or static hosting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
