INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5dcae92d-bb79-40cf-92c3-407b2a6565b1', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle dependency injection, and why is this architectural pattern beneficial for large-scale applications?', N'Senior', N'FastAPI provides a built-in dependency injection system that resolves complex object graphs at request time. This promotes modularity, simplifies unit testing by allowing easy mocking of dependencies, and centralizes cross-cutting concerns like authentication or database session management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
