INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'006057aa-c5b7-46d7-b67a-407be6296ce8', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you evaluate whether to use a monolithic architecture or microservices for a new greenfield project?', N'Senior', N'I evaluate based on team size, deployment velocity, and domain complexity. Monoliths are better for early-stage startups to allow for rapid iteration and simple operational overhead, while microservices should only be introduced when organizational scaling requires independent deployment cycles, team autonomy, or specific technology heterogeneity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1480f94c-5571-4103-859d-4081b567e467', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the difference between a class and a module in Ruby?', N'Intern', N'A class is a blueprint for creating objects and supports inheritance, while a module is a collection of methods and constants used to share behavior across different classes. Unlike classes, modules cannot be instantiated to create objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09890b34-ccb8-4f8e-a980-4087b51ebce5', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Why is index cardinality critical for query performance?', N'Senior', N'Cardinality refers to the number of unique values in an indexed column. High-cardinality columns are excellent candidates for indexes because they allow the database to quickly narrow down the result set, whereas low-cardinality columns may be ignored by the optimizer in favor of a full table scan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'212ac9b7-46f2-4b14-a987-408d08dbf0de', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Why is it recommended to use a working directory in R?', N'Junior', N'Setting a working directory ensures that R knows exactly where to look for files you want to import and where to save exported files. It helps organize projects and prevents errors related to incorrect file paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76beb456-d0df-46df-ae3e-408e20a73f83', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Explain the role of ''Layer'' in Axum''s middleware stack.', N'Senior', N'A Layer is an abstraction that wraps a Service and adds functionality to it, such as logging or request transformation. By using Layers, Axum allows you to wrap the entire router or individual routes with middleware, providing a clean separation between infrastructure concerns and business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efd8d727-2292-439b-ad20-408eee8ee534', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is denormalization?', N'Intern', N'Denormalization is the process of intentionally adding redundant data to a database schema to improve read performance. It is often used in data warehousing to reduce the number of joins needed for complex analytical queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18ae6eb4-6ab3-4d93-b2bc-409096e576ce', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do Svelte transitions improve user experience and performance?', N'Middle', N'Svelte transitions are handled by the browser''s animation engine and are declarative, making them easy to implement without external libraries. They improve performance because Svelte manages the lifecycle of the transition, ensuring that elements are correctly removed from the DOM only after the exit animation completes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30fe03f5-3043-4437-9383-4091b6fe859b', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the role of assumptions in technical problem solving?', N'Intern', N'Assumptions serve as placeholders for unknown information, allowing a project to move forward when complete data is unavailable. However, they must be documented and validated as soon as possible. If an assumption turns out to be false, the entire approach may need to be re-evaluated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c64f7eb1-49fb-4aab-a6bd-4092ffb0f743', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum leverage the Tower library?', N'Fresher', N'Axum is built on the Tower library, which provides a standard set of abstractions for building modular and reusable network services. This allows Axum to benefit from a vast ecosystem of existing middleware and service layers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70c586c8-3bd4-4edd-aa12-4093b9250749', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does the C++ linker resolve symbols across multiple translation units?', N'Senior', N'The linker collects all compiled object files and resolves references by matching external function and variable declarations to their definitions. It handles multiple definitions by enforcing the One Definition Rule, ensuring that non-inline functions are defined exactly once and inline functions are merged correctly across units.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52730325-e96b-431f-97f1-4096cd442f4f', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is hydration in Astro?', N'Intern', N'Hydration is the process where client-side JavaScript is loaded to make static HTML interactive. Astro gives developers control over when and how this happens to optimize performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1178a9ce-050f-4160-b852-4097dd1f460b', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What are the architectural trade-offs of using Rocket''s built-in templating engine vs. a headless JSON approach?', N'Senior', N'Using built-in templating couples the view logic to the backend, which is simpler for monolithic apps but creates tight coupling. A headless JSON approach favors clean separation of concerns, allowing for independent scaling and evolution of the backend and frontend, which is preferred for modern microservice architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83565c14-5a57-4ae7-a5c5-4098f48cb5da', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the .NET garbage collector determine if an object is ''reachable'' during a collection?', N'Senior', N'The GC performs a graph traversal starting from roots like static fields, local variables on the stack, and CPU registers. Any object reachable through this chain of references is marked as live, while everything else is considered eligible for reclamation, regardless of its heap location.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3efa4239-7581-4809-8942-4098fe5bdde8', N'954a0331-deff-4399-b588-96f39fec001d', N'What is subscribe in RxJS? How do you unsubscribe?', N'Fresher', N'In RxJS, subscribe is the method used to execute an Observable and start receiving values. An Observable is like a blueprint for a stream of data, but it doesn''t do anything until you subscribe to it. When you call subscribe, you provide an Observer or callback functions (next, error, complete) to handle the emitted values, errors, or completion notifications. The subscribe method returns a Subscription object. It''s crucial to unsubscribe from subscriptions when they are no longer needed, especially in Angular components when the component is destroyed. Failing to unsubscribe can lead to memory leaks and potential errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b73288e-6c73-43be-b6d2-409a24c617d6', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the role of the ''Astro'' file extension in the project structure?', N'Middle', N'The .astro file is a template component syntax that allows developers to mix HTML, CSS, and JavaScript. It is designed to be framework-agnostic, meaning it can render components from other libraries like React, Vue, or Svelte within the same page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdf80963-9a91-4d00-9e62-40a028219b6d', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the primary purpose of a module bundler?', N'Fresher', N'A module bundler resolves dependencies between files and combines them into optimized static assets. This allows developers to organize code into smaller, maintainable modules while ensuring the browser receives a performant bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9f17751-03fb-4691-8daf-40a3a694779d', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does a database backup differ from a database dump?', N'Junior', N'A database backup is a physical copy of the database files, often used for disaster recovery. A database dump is a logical export of the database schema and data into a text file, commonly used for migrations or backups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f447d514-89ee-40e9-9433-40a736a4265b', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are the trade-offs of using built-in body parsing middleware versus external libraries?', N'Middle', N'Built-in middleware is lightweight and maintained by the Express team, ensuring compatibility and security for standard formats like JSON or URL-encoded data. External libraries might be necessary for specialized data formats or advanced features like custom streaming limits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a68d066d-96a0-4f22-9d4c-40a993f9fc63', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What''s a typical use case for anonymous functions in JavaScript?', N'Intern', N'An anonymous function in JavaScript is a function that does not have any name associated with it. They are typically used as arguments to other functions or assigned to variables. They are often used as arguments to other functions, known as higher-order functions, which can take functions as input and return a function as output. Anonymous functions can access variables from the outer scope, a concept known as closures, allowing them to "close over" and remember the environment in which they were created. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
