INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff35bddb-a4c7-469b-8e88-40acf6a3a3cd', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What does the ''prerendering'' feature do?', N'Fresher', N'Prerendering is the process of generating static HTML files for your routes during the build step. This makes pages load extremely fast because they are served as pre-built files rather than being calculated on the server for every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3c9b11f-a7a2-45ba-8c25-40ad3686e34c', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Discuss the impact of memory alignment and padding on high-performance data structures in Go.', N'Senior', N'Memory alignment ensures that data types are stored at addresses that are multiples of their size, which is a requirement for hardware-level efficiency. Improper alignment leads to padding, which increases the overall memory footprint of structs and can cause performance penalties due to cache line splitting; careful field ordering minimizes this overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd110f114-a604-45c5-ba35-40ae06556e2c', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the potential drawbacks of increasing the ''max_connections'' setting in PostgreSQL?', N'Senior', N'Each connection consumes memory for process forks and shared structures, leading to higher context-switching overhead and potential memory exhaustion. High connection counts also increase lock contention on system resources, often resulting in diminishing returns where overall throughput decreases rather than scales.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
