INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05225a58-d563-4386-8b61-40ced62d20ab', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the ''select'' statement in Go?', N'Intern', N'The ''select'' statement allows a Goroutine to wait on multiple communication operations simultaneously. It blocks until one of its cases can run, then executes that case, which is essential for managing multiple channels.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2e118bf-b698-47b1-b6f6-40d1bdc8c66e', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the primary architectural trade-off of the SolidJS reactive model?', N'Senior', N'The primary trade-off is the restriction on how developers interact with state, specifically regarding the need to avoid destructuring signals and the requirement to keep reactive code within the initial setup phase. While this results in highly efficient runtime performance, it requires a steeper learning curve regarding the reactive graph''s lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd6fbd98-f8a3-4590-b918-40d4bc023399', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What does the ''comma-ok'' idiom mean?', N'Junior', N'The comma-ok idiom is a way to check if an operation was successful, such as retrieving a value from a map or receiving from a channel. It uses a second boolean variable to indicate if the result was valid.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed8449f7-8cb6-4344-95e5-40d62ffcb8ed', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the purpose of HATEOAS in RESTful design?', N'Middle', N'HATEOAS, or Hypermedia as the Engine of Application State, allows the server to provide links in its responses that guide the client on available actions. This promotes loose coupling between the client and server, as the client does not need to hardcode API endpoints but can instead discover them dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e65168b2-a946-4401-b3bb-40d6f9acbc34', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the primary purpose of using logging in an application, and why is it better than just printing messages to the console?', N'Junior', N'Logging provides a persistent, structured record of application behavior that can be analyzed after a crash or in a remote environment where console output is inaccessible. Unlike local prints, logs can be categorized by severity levels and filtered to help pinpoint exactly where and when a failure occurred.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb355e1b-f26f-4223-a6e0-40d99398a94e', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go handle memory management compared to languages like C or C++?', N'Intern', N'Go utilizes an automatic garbage collector to manage memory, which periodically identifies and frees memory that is no longer in use by the program. This removes the need for developers to manually allocate and deallocate memory, significantly reducing common errors like memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19e365de-3324-46ae-8afb-40d9dce82bf5', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is an Exception Handler in Spring Boot?', N'Intern', N'An Exception Handler is a mechanism that allows you to globally manage exceptions that occur within your application. By using @ControllerAdvice and @ExceptionHandler, you can provide consistent error responses to clients instead of default stack traces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f76e0161-97fb-4bed-87bd-40da03988602', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is an HTTP status code 404 vs 500?', N'Junior', N'A 404 status code indicates that the requested resource could not be found by the server. A 500 status code indicates an internal server error, meaning the server encountered an unexpected condition that prevented it from fulfilling the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bf2b9c9-43f2-40d2-bd0b-40dd9f2c1d69', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why does Go prefer composition over class-based inheritance, and how does this affect system architecture?', N'Senior', N'Composition avoids the ''fragile base class'' problem and deep, rigid hierarchies that are difficult to refactor. By using struct embedding and interfaces, developers create decoupled, modular systems that are easier to test and maintain as requirements evolve in complex, large-scale distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16b3d7fd-56e3-4efb-a29e-40ddb35c1dc0', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How are resources like database pools typically managed in Actix?', N'Junior', N'Database pools are usually shared among actors by passing a reference to the pool during actor construction. Actors then use this pool to perform database operations asynchronously within their handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12d6ac63-763a-447b-b3bf-40ddc22caef3', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How do SSTables maintain immutability?', N'Middle', N'SSTables are immutable, meaning they are never modified after being written to disk. Instead of updating or deleting, Cassandra writes new data to a new file and uses tombstones to handle deletions, which are eventually resolved during compaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4b59c5a-e8b8-4592-8911-40e06cbabb7a', N'a2838158-7305-480a-b22b-4dc35776b400', N'Explain the difference between optimistic and pessimistic concurrency control in distributed databases.', N'Senior', N'Pessimistic concurrency control locks resources before accessing them to prevent conflicts, which is ideal for high-contention environments but reduces throughput. Optimistic concurrency control assumes conflicts are rare and only checks for them at commit time, which performs better under low contention but requires logic to handle retries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cdc8530-418d-4936-89ba-40e1a968afeb', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are the benefits of using Doctrine''s Unit of Work pattern?', N'Middle', N'The Unit of Work pattern tracks all changes made to entities during a request and synchronizes them with the database in a single transaction. This ensures data integrity and efficiency by minimizing the number of individual database queries executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d8dfd91-180d-41c9-bbda-40e4d63d418b', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is meant by the term ''Reconciliation'' in Preact?', N'Junior', N'Reconciliation is the process by which Preact updates the real DOM to match the new Virtual DOM structure. It uses a diffing algorithm to identify the minimal set of changes required to update the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1246efb3-480c-4d6a-b4c2-40ea8997c04a', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Describe the main differences between CommonJS and ES Modules.', N'Middle', N'CommonJS uses the require function for synchronous loading, which is well-suited for server-side environments. ES Modules use the import/export syntax and support asynchronous loading, providing better support for tree-shaking and static analysis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d8b481b-dc5e-4e4e-acc2-40ed46973b49', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the purpose of the Garbage Collector in Java?', N'Junior', N'The Garbage Collector automatically manages memory by identifying and removing objects that are no longer reachable by the application. This prevents memory leaks and removes the need for manual memory deallocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
