INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddfaa147-d7f3-4e3b-a8f7-4100753be490', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do browser rendering engines calculate the ''Computed Style'' and what are the performance implications of deep CSS selector nesting?', N'Senior', N'Browsers calculate computed styles by matching CSS rules against the DOM tree starting from the rightmost selector and moving left, which is why excessive nesting increases the complexity of selector matching. Deeply nested selectors force the browser to perform more expensive traversals of the DOM hierarchy during the Recalculation Style phase of the critical rendering path. To optimize performance, developers should prefer flat, class-based BEM-style naming conventions to ensure O(1) or near-constant time lookups for the style engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
