INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42dc0dde-e2cf-4d19-ae0b-41061a259e0e', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the main drawback of over-indexing a table?', N'Junior', N'While indexes speed up read operations, they slow down write operations like inserts, updates, and deletes. This is because the database must update the index structure every time the underlying data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c99feec8-039c-4684-93c8-410686903d46', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why is ''Cache Warming'' critical in systems with high read-latency requirements, and what is a common risk?', N'Senior', N'Cache warming pre-populates the cache with frequently accessed data before a system goes live or after a restart to ensure immediate optimal performance. The main risk is an ''over-warming'' strategy that consumes excessive system resources or fills the cache with low-utility data that displaces high-value items.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd7d39e8-f588-4ae5-9acc-4107f553e8bf', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it important to implement logging and monitoring from the start of a project?', N'Junior', N'Logging and monitoring provide the visibility necessary to understand how the system behaves in production. Without them, it is nearly impossible to diagnose issues, track user behavior, or understand the root cause of failures, leading to much longer recovery times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d496302-4a28-4a59-85a9-4109e43a5d75', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why is it considered a best practice to keep state normalized in Redux?', N'Middle', N'Normalized state mimics a database structure, which prevents data duplication and inconsistency. It makes updating complex, nested data structures much simpler and more efficient since you only need to update a single entity by its ID.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42aa06c5-286e-4c99-b944-4117642f3e29', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What does ''lazy evaluation'' mean in Scala?', N'Fresher', N'Lazy evaluation means that a variable or expression is not computed until it is first accessed. This can improve performance by avoiding unnecessary calculations and is declared using the ''lazy val'' keyword.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a60fdd0-8134-4840-a324-4118a8c12329', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is a Tuple?', N'Intern', N'- Tuple Objects can be created by using parenthesis or by calling tuple function or by assigning multiple values to a single variable - Tuple objects are immutable objects - Incision order is preserved - Duplicate elements are allowed - Heterogeneous elements are allowed - Tuple supports both positive and negative indexing - The elements of the tuple can be mutable or immutable', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2c02e3b-7831-40a2-9e03-411c5bac49a9', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the purpose of the ''defer'' keyword?', N'Intern', N'The defer keyword schedules a function call to be run immediately before the surrounding function returns. It is commonly used for cleanup tasks like closing files or releasing locks to ensure they execute regardless of how the function exits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c60b7aa-9cdc-4463-b8b9-411e385cb14e', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What are Gin struct tags?', N'Intern', N'Struct tags are metadata added to Go struct fields that tell the Gin binder how to map request data. For example, the ''json'' or ''form'' tags define which incoming key maps to a specific field in the struct.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd99173d-13d9-4616-b3a3-411f0841848a', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is an Artisan CLI?', N'Intern', N'Artisan is the command-line interface included with Laravel. It provides a number of helpful commands for your use while developing your application, such as generating code scaffolding, managing database migrations, and clearing application caches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ee23bde-fef8-4217-bd71-411fe2a919e1', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is encapsulation and why is it important?', N'Fresher', N'Encapsulation is the bundling of data and the methods that operate on that data into a single unit, usually a class. It is important because it restricts direct access to some of an object''s components, which prevents accidental modification and improves security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e6e0b34-4c81-4a36-a8f2-4121fb15a12f', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum achieve high concurrency compared to traditional thread-per-request models?', N'Senior', N'Axum leverages the Tokio runtime, which uses an M:N scheduler to multiplex thousands of lightweight tasks onto a small pool of OS threads. This non-blocking I/O approach allows the system to handle massive concurrent connections without the memory overhead associated with spawning dedicated threads for each request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a0b4d75-2607-4502-8f98-4125367de59e', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How do you test FastAPI applications effectively, and what role does ''TestClient'' play?', N'Senior', N'The ''TestClient'' is a wrapper around the framework that allows you to trigger requests to your app without starting a network server. It enables fast, reproducible integration tests that exercise the full stack, including validation and dependency injection, in a controlled environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bddbfea-69c4-4aad-956a-41293ca95ff7', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between ''any'' and ''some'' in Swift?', N'Fresher', N'The ''some'' keyword is used for opaque types, meaning the underlying type is hidden but concrete. The ''any'' keyword is used for existential types, which allow for dynamic storage of any type that conforms to a specific protocol.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba5819e3-01b2-4f8d-81bf-4129c13ecf34', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the strategy for handling large datasets that exceed system memory?', N'Fresher', N'I would use pagination, chunking, or streaming techniques to process the data in smaller segments. This prevents the application from crashing due to out-of-memory errors and ensures a smooth user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98fba8ab-fd98-4e74-b089-412b92a4b147', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Why is token revocation a challenge in stateless authentication architectures?', N'Senior', N'Because stateless tokens are self-contained and not checked against a central database, revoking them before expiration requires a secondary mechanism, such as a distributed blocklist or a short-lived token rotation strategy. This introduces state back into the system, which can impact performance and complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc0b3888-62c4-4dc4-b827-412d01e498ff', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the concept of an Ecto Repo.', N'Middle', N'A Repo acts as the interface between the application and the database. It encapsulates all operations such as inserting, updating, deleting, and querying records, providing a consistent API for database interactions regardless of the underlying storage engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4025fcd-d454-4769-8fdf-4130708d3738', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate whether to build a custom solution versus using an existing third-party API or service?', N'Middle', N'The trade-off involves weighing development velocity and maintenance costs against control and long-term flexibility. A third-party service accelerates time-to-market but ties your system to an external provider''s uptime and pricing, whereas a custom solution requires higher upfront engineering effort but offers complete ownership and customization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
