INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e817f388-8326-41b6-8f76-4134ccf265cd', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the primary architectural trade-off between using atomic CSS classes versus semantic class names?', N'Senior', N'Atomic CSS promotes high reusability and eliminates the need to invent naming conventions, which prevents style bloat as the application grows. However, it can lead to massive HTML files with long class strings, which may reduce readability compared to semantic BEM-style classes that describe the underlying component purpose.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
