INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'634e38ea-033f-4601-a8dc-4137796baadb', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the storage event and how can you use Web Storage for cross-tab communication?', N'Intern', N'The browser fires a storage event on the window object of all other tabs/windows at the same origin whenever localStorage is modified. The tab that made the change does not receive the event itself. This makes localStorage a lightweight broadcast channel for cross-tab state synchronisation without a server. The StorageEvent object provides: - key — the changed key (null on clear()) - oldValue — previous value (or null) - newValue — new value (or null on removeItem) - url — the origin URL that triggered the change - storageArea — reference to the affected storage object Example: Real-World Use Case: Banking and enterprise SaaS applications implement global logout using the storage event: when a user logs out in one tab, a flag is written to localStorage, all other open tabs detect the stora...', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
