INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd14a9658-522c-4cde-894e-413d9b2b5b23', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why is Swift considered a type-safe language?', N'Fresher', N'Swift is type-safe because the compiler performs type checks when compiling your code and flags any mismatched types as errors. This prevents mistakes such as passing a string to a function that expects an integer, catching bugs early in the development process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f30cf912-ea2d-4197-8de0-413f0bf8d627', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If you discover that two microservices are experiencing a circular dependency, how do you resolve the architectural issue?', N'Middle', N'I would analyze the communication flow to identify if the dependency can be broken by introducing an event-driven architecture. By using a message broker, I can decouple the services, allowing them to react to events asynchronously rather than waiting for direct synchronous responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
