INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3357139b-82b9-4a46-bc62-414672f229ec', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How do you define a dynamic path parameter in a Litestar route?', N'Junior', N'You define a dynamic path parameter by placing the variable name inside curly braces within the route string. Litestar then automatically extracts this value from the URL and passes it as an argument to the corresponding route handler function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44649a29-5293-470f-ab61-414a3b9c2be8', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Does Rocket require a specific database driver?', N'Junior', N'No, Rocket is database-agnostic. While it provides official support for common databases through libraries like Rocket DB Pools, you can integrate any database driver as long as you can manage its connection lifecycle via managed state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbb5dbe2-d6a4-46f0-9ab1-414a3ca007d2', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix approach search engine optimization?', N'Fresher', N'Because Remix sends fully rendered HTML from the server, search engines can easily crawl and index your content. You can also define dynamic meta tags per route to improve SEO rankings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ceba74e-9ef6-4362-81f6-414b92cd0298', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you ensure your solution is scalable and maintainable?', N'Intern', N'I think about simplicity and modularity, ensuring that each part of the solution performs one clear function. By keeping the design clean and avoiding unnecessary complexity, it becomes easier to update or expand the system later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9543e211-22c5-45ce-b86b-415039fefdd1', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the role of an Interceptor in NestJS?', N'Intern', N'An interceptor is a feature that allows you to bind extra logic to methods before or after they execute. They can transform the result returned from a function, extend basic function behavior, or completely override a function depending on specific conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd24aa5b-d1e3-4105-b909-4152467f36a7', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of the String type versus the str type?', N'Junior', N'String is a growable, heap-allocated UTF-8 encoded buffer owned by the program. In contrast, str is an immutable sequence of UTF-8 bytes, usually seen as a reference, which cannot be resized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a1a1115-51bf-4342-9dd9-4155fb849865', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the purpose of compaction in LSM-tree based databases?', N'Senior', N'Compaction is the process of merging multiple sorted files into a single, optimized file while merging updates and discarding deleted records. This process is essential for reclaiming disk space and improving read performance by reducing the number of files that must be scanned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcc94779-da8e-494b-84f6-415ac7a50046', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the effect of cache pollution?', N'Middle', N'Cache pollution occurs when infrequently accessed or useless data occupies memory, forcing the eviction of frequently accessed data. This significantly lowers the cache hit ratio and is often mitigated by implementing stricter eviction policies or filtering what data is stored.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
