INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc6ee936-753c-439f-a865-41624f766b5c', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the trade-off between synchronous and asynchronous processing in a scalable system?', N'Middle', N'Synchronous processing is easier to implement but can lead to bottlenecks if a service is slow, as the caller must wait for a response. Asynchronous processing decouples services using message queues, improving throughput and fault tolerance at the cost of increased system complexity and eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
