INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ced937e2-db2d-4752-82c8-41783adc4efe', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does BASE stand for in NoSQL systems?', N'Junior', N'BASE stands for Basically Available, Soft state, and Eventual consistency. It is an alternative model to ACID that accepts temporary inconsistencies in exchange for higher performance and better availability in distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'326c882c-c675-4000-8433-41797f9992b1', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the advantages and drawbacks of using Worker Threads over the Cluster module?', N'Middle', N'Worker Threads share memory within a single process, making them more efficient for CPU-intensive tasks like data processing. The Cluster module is better for scaling web servers because it provides process isolation, meaning a crash in one instance does not necessarily bring down the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a07c0ca-abf7-4466-919e-417a7a1b14e4', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If a feature is taking longer to build than estimated, how should you communicate this?', N'Junior', N'Notify your project manager or team lead as soon as you realize the delay, rather than waiting until the deadline. Explain the specific blockers you are facing and provide a revised estimate so the team can adjust expectations or resources accordingly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6299277c-7be1-4b83-aba6-417ab56b67a2', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the ''Recovery'' middleware in Gin?', N'Intern', N'The Recovery middleware is a built-in feature that catches any unexpected panics occurring during request processing. It prevents the entire server from crashing and returns a 500 Internal Server Error to the client instead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'009c413e-4a26-4ed0-9dc5-417d00861cee', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact''s approach to memoization differ from React''s ''useMemo'' and ''React.memo''?', N'Senior', N'While the API is similar, Preact''s internal memoization logic is optimized for smaller memory footprint and faster comparison checks. It avoids complex dependency tracking in favor of a simpler shallow equality check, which is sufficient for most performant UI components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'354bc2e6-e0ec-4f10-99c7-41817b1793ea', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are the benefits of using a configuration file in Tailwind CSS?', N'Intern', N'The configuration file allows developers to customize the framework''s theme, including colors, spacing, fonts, and breakpoints, to match a project''s specific design system. It serves as the single source of truth for the project, ensuring consistency across all components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80695244-8a99-451d-b672-41830d6a214f', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt handle meta tags for SEO?', N'Intern', N'Nuxt provides built-in tools like useHead or app.config to manage meta tags dynamically for each page. This ensures that titles, descriptions, and Open Graph tags are correctly set for search engines and social media sharing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1797ed93-21bc-4aef-92ad-4183e7dbd8bc', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between ''NULL'' and ''void'' pointers?', N'Fresher', N'A NULL pointer is a pointer that explicitly points to no valid memory address. A void pointer is a generic pointer type that can hold the address of any data type but requires typecasting before its value can be accessed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d36d1e8-d425-4505-add8-41877f40bc70', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle server-side rendering?', N'Fresher', N'Qwik performs server-side rendering to generate the initial HTML snapshot of the application. This snapshot includes the necessary serialized state and metadata, ensuring the client can resume exactly where the server left off.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09a30bbc-7c59-431c-80d2-418d423f5547', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL handle multi-version concurrency control (MVCC)?', N'Middle', N'MVCC allows multiple users to read and write to the database simultaneously without blocking each other by maintaining multiple versions of a row. When a row is updated, a new version is created while older transactions continue to see the previous version based on their snapshot.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9baf11c1-a6db-404c-a988-4191c48616d1', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the ''CAP Theorem'' in the context of distributed databases?', N'Junior', N'The CAP Theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. Database designers must choose which two to prioritize based on the requirements of their application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a93630a8-7a67-4bd2-9189-41958ba3deda', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between writing extensive automated tests versus spending more time on new feature development?', N'Fresher', N'Extensive testing ensures long-term stability and easier future changes, reducing the cost of bugs. Skipping tests allows for faster initial delivery but increases the likelihood of regressions and higher maintenance costs later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3247989-40ed-46d6-820b-4195addc25d5', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you support server side XSS protection in Angular application?', N'Fresher', N'The server-side XSS protection is supported in an angular application by using a templating language that automatically escapes values to prevent XSS vulnerabilities on the server. But don''t use a templating language to generate Angular templates on the server side which creates a high risk of introducing template-injection vulnerabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aed0f8c9-bc21-4ad0-9a37-419879c3719b', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How do you handle cross-cutting concerns like logging and recovery in Chi?', N'Senior', N'These are best handled via global middleware at the top level of the router stack. A recovery middleware should capture panics to prevent process termination, while a logging middleware should wrap the request lifecycle to capture metadata like duration and status codes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be2d7aa4-f679-42f0-9368-419b04fae725', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a ''Bloom Filter'' and why is it used in NoSQL databases?', N'Middle', N'A Bloom filter is a space-efficient probabilistic data structure used to test whether an element is present in a set. In NoSQL databases, it is used to quickly determine if a record exists in a specific data file, saving the system from performing expensive disk I/O if the record is definitely not there.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
