INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a07442ec-c3fb-4818-aacd-41a3650e0ab3', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does multi-source replication differ from standard master-slave replication in terms of architectural complexity?', N'Senior', N'Multi-source replication allows a single slave to receive updates from multiple masters, enabling data consolidation or sharding aggregation. The complexity increases significantly regarding conflict resolution, potential binary log bottlenecks, and the necessity of maintaining consistent global transaction identifiers across sources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
