INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9515069a-1876-41e1-8265-41aaac410dd2', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How do event listeners work in Alpine.js compared to standard JavaScript?', N'Junior', N'Alpine.js simplifies event handling by using the x-on directive, which allows you to bind JavaScript expressions directly to DOM events like clicks or inputs. This reduces the need to manually query selectors or write separate addEventListener functions, as the logic is declared right where the event occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
