INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4be4627-58b3-4e53-b6c7-41b1257fcad2', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the Go compiler implement ''inlining'' to optimize performance?', N'Senior', N'The compiler replaces function calls with the actual function body when the function is small, reducing the overhead of stack frame setup and function calling. This optimization improves execution speed but can increase the overall binary size and requires careful heuristics to avoid excessive code bloat.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a141e28f-b125-46c1-84f4-41b44bea32df', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What does ''stateless'' mean in the context of HTTP requests?', N'Fresher', N'Stateless means that each individual HTTP request is independent and the server does not store information about the client between requests. Phoenix handles state through mechanisms like sessions or cookies when required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
