INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa7646c5-203d-4631-8802-41c98bd91ee5', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of a database trigger, and what are the drawbacks?', N'Middle', N'Triggers are procedural code that automatically executes in response to specific events on a table, such as inserts or updates, often used for auditing or enforcing complex business rules. They can be dangerous because they often operate silently, making debugging difficult and potentially creating hidden performance overheads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
