INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d7e6d72-4e00-4d01-90dc-41d2eb03997f', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How do you handle asynchronous errors in Express?', N'Junior', N'In modern Express, you must catch errors in asynchronous functions using a try-catch block and pass the error to the next function. If an error occurs inside an async handler and is not caught, Express might not automatically catch it, potentially leading to an unhandled promise rejection. Passing the error to ''next'' ensures it reaches the application''s centralized error-handling middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
