INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5e8470c-6810-4fdc-9cf1-41f22278d4e2', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the role of middleware in an Express application and how does it affect the request-response cycle?', N'Middle', N'Middleware functions have access to the request object, the response object, and the next middleware function in the application’s request-response cycle. They can execute code, modify request/response objects, end the cycle, or call the next function in the stack, allowing for modular logic like authentication or logging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5704c319-d34b-4473-8fb4-41f298bc2931', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are Coroutines in Kotlin and why are they used?', N'Fresher', N'Coroutines are a way to perform asynchronous or non-blocking operations in a sequential manner. They allow developers to write code that performs long-running tasks, such as network calls or database operations, without blocking the main execution thread, which helps maintain a responsive user interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e05038bc-9f6d-420f-b6c2-41f2fa974ead', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain the architectural significance of the ''Confused Deputy'' problem in the context of cloud IAM roles.', N'Senior', N'The confused deputy problem occurs when a service with higher privileges is tricked by a less-privileged user to perform an unauthorized action. In cloud IAM, this is mitigated by using external IDs and cross-account roles to ensure that the service only acts on behalf of a resource owner who has explicitly granted permission.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8ec459f-9377-4b8c-9e05-41f592122d89', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra handle schema changes across a distributed cluster?', N'Senior', N'Cassandra uses a system of schema versioning via the Gossip protocol to ensure all nodes eventually agree on the cluster''s state. When a schema change is executed, it propagates throughout the cluster, and nodes pause until they achieve consensus on the new definition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
