INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6e07bc6-181b-4c84-b056-42071a7014d7', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Contrast the performance characteristics of String concatenation using the ''+'' operator versus StringBuilder across different Java versions.', N'Senior', N'While older versions of Java required manual use of StringBuilder to avoid excessive temporary object creation, modern compilers automatically optimize string concatenation into efficient StringBuilder or invokedynamic-based instructions. Consequently, the performance difference is now negligible, though StringBuilder remains preferred for complex, loop-based construction logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fc42417-d2d4-4f7d-8e19-42072cea2c30', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does the NestJS dependency injection system handle providers that are defined in multiple modules?', N'Senior', N'If a provider is exported by multiple modules, NestJS will treat them as separate instances unless the module is marked as global or the provider is a singleton shared via a common ''CoreModule''. In a large system, this can lead to unexpected state issues, making it critical to strictly define and manage provider visibility and hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
