INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57854ed4-571b-4aa6-abc1-42084e681e0b', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why is it important to use ''hash'' versus ''chunkhash'' or ''contenthash'' for filenames?', N'Senior', N'Using ''hash'' updates the filename for all output files whenever any part of the project changes, making it poor for caching. ''Chunkhash'' updates files only if the content of that specific chunk changes, while ''contenthash'' is the most precise, updating the filename only when the actual content of the file changes, ensuring maximum cache effectiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
