INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd74c7b97-467b-42e1-a5ec-4212e9aa3688', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does React''s reconciliation algorithm manage large component trees efficiently without re-rendering everything?', N'Senior', N'React uses a heuristic O(n) algorithm that compares the previous and new virtual DOM trees by type and key. By assuming that different component types produce different trees and using keys to track stable children, it minimizes expensive DOM mutations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e61b39b6-fa33-4e36-a5a0-421342c15550', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the difference between LOCAL_QUORUM and EACH_QUORUM consistency levels?', N'Middle', N'LOCAL_QUORUM requires a majority of replicas in the local data center to acknowledge the request. EACH_QUORUM requires a majority of replicas in every data center, providing stronger cross-DC consistency at the cost of higher latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99b2c660-fd9a-431b-b0d5-42138ea6bb26', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Template Literal Types?', N'Middle', N'Template literal types allow you to create new string types by concatenating existing string literal types. They are particularly powerful for modeling complex naming conventions, such as CSS class names or event strings, by ensuring strict adherence to expected patterns at compile time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'929e56f9-e341-446b-97fb-421633c728fe', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s null safety system influence runtime performance and binary size?', N'Senior', N'Null safety moves null-check errors from runtime to compile-time, which allows the compiler to make stronger assumptions about data types. This optimization leads to smaller binary sizes and improved performance because the runtime no longer needs to perform defensive null checks on non-nullable variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1128361a-34d5-47d2-ba17-421661d8ce93', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is sharding in NoSQL?', N'Junior', N'Sharding is the process of splitting a large dataset into smaller, manageable chunks called shards and distributing them across multiple servers. This technique allows a database to handle larger datasets and higher request loads than a single server could manage alone.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e22836cd-2c62-4e50-bf7d-421aa20070fd', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a view in SQL?', N'Intern', N'A view is a virtual table based on the result-set of an SQL statement. It does not store data itself but displays data from one or more underlying tables, providing a simplified or restricted view of the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
