INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53e17f7b-2eb1-405e-bf4f-4228bf2288f1', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift handle memory management for closure capture lists, and what are the risks of retain cycles?', N'Senior', N'Swift uses Automatic Reference Counting to track closure references; if a closure captures an object strongly, it increments the reference count. If that object also holds a strong reference to the closure, a retain cycle occurs, preventing memory deallocation, which must be resolved using capture lists with weak or unowned references.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
