INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbf55bf3-011e-40e7-8436-4246584acbcd', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is an Asynchronous Provider?', N'Intern', N'An asynchronous provider allows for the registration of dependencies that require an asynchronous operation to be completed before they are injected. This is useful for initializing database connections or loading configuration settings from an external source.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4b4ac6f-6d4c-4fed-9c15-4247c1021017', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What are the trade-offs of using Astro''s SSR mode within a serverless environment like Vercel or AWS Lambda?', N'Senior', N'SSR in serverless environments can lead to ''cold starts'' if not properly configured, as the server must execute code to generate the page. However, it allows for dynamic personalization and real-time content delivery that is impossible with static sites, requiring a balance between performance and content freshness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7657b3ad-a122-4523-888c-4249dea6d90e', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the performance impact of using protocol-oriented programming versus class inheritance?', N'Middle', N'Protocol-oriented programming often utilizes witness tables for dynamic dispatch, which is slightly more flexible than class-based vtables. While class inheritance is generally well-optimized, protocols allow for better code composition and avoid the pitfalls of massive base classes, often resulting in more maintainable and testable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'552365ce-d1f7-409d-9dcc-424abf2c3a26', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the <caption> element in HTML tables and why is it important?', N'Intern', N'The element provides a title or description for an HTML table. It must be the first child of . Example: Why it matters: 1. Accessibility — Screen readers announce the caption before reading the table, giving users context about what data follows. This is especially important for complex tables. 2. Discoverability — Users who navigate by tables (using AT shortcuts) see the caption first, helping them decide whether to enter the table. 3. SEO — Provides semantic meaning to search engines about the table''s content. Caption positioning with CSS: > For complex tables, consider also using the summary attribute (HTML4) or aria-describedby (modern approach) to provide a more detailed description of the table''s structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f64907bc-6d1b-43dd-8c6b-424b5580af7f', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are Lit decorators?', N'Intern', N'Decorators are a language feature used in Lit to simplify component definitions. They allow you to easily declare properties, state, and event listeners using a concise syntax.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d0a5794-5c90-4032-9779-424b5951e728', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain the concept of defense-in-depth and why it is critical for system architecture.', N'Middle', N'Defense-in-depth is an architectural strategy that layers multiple security controls so that if one mechanism fails, others remain to protect the system. It ensures that a single point of failure does not lead to a complete compromise of the application or data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1bb4566-73c1-4629-878a-424beea4012d', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the different ways to remove duplicate service registration?', N'Intern', N'If a module defines provides and declarations then loading the module in multiple feature modules will duplicate the registration of the service. Below are the different ways to prevent this duplicate behavior. 1. Use the providedIn syntax instead of registering the service in the module. 2. Separate your services into their own module. 3. Define forRoot() and forChild() methods in the module.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00c023cf-d7dc-4aab-b9e7-424f31b71c68', N'075b8862-431c-4678-9767-f55359758a4a', N'Why would you use a scoped slot in a component?', N'Middle', N'Scoped slots allow a child component to pass data back to the parent''s template. This provides the flexibility for the parent to define how the child''s internal data should be rendered while keeping the logic encapsulated within the child.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4689f89-1800-4356-bcb1-4250039962af', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the difference between ''=='' and ''eql?'' in Ruby?', N'Fresher', N'The ''=='' operator checks for value equality, while ''eql?'' is stricter and often used by Hash keys to ensure both the value and the type are identical. Many classes override ''=='' to provide custom logic, while ''eql?'' is generally more conservative.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f658260-26e1-4ef7-a6d7-4250aac1b2ae', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R handle packages?', N'Junior', N'Packages in R are collections of functions, data, and compiled code that extend the base functionality of the language. They are managed using specific commands to install, load, and update them from repositories like CRAN.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd9f53b5-228e-46b3-9650-42516c5c130c', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why is NoSQL preferred for Big Data applications?', N'Intern', N'NoSQL databases can ingest massive volumes of high-velocity data that lack a uniform structure. Their distributed nature allows them to process this information across clusters of commodity hardware efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
