INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51220a99-e02c-4dbe-bbe4-42545a777b37', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask''s ''session'' mechanism work internally?', N'Middle', N'Flask''s default session uses a client-side approach where data is serialized, encrypted, and stored in a signed cookie on the user''s browser. This makes the session stateless, but it implies that session data should be small and not contain sensitive information that should never be visible to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
