INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2220085d-349d-4eb9-b33a-426b8c9103df', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between optimistic and pessimistic locking in a multi-user environment?', N'Junior', N'Pessimistic locking prevents conflicts by blocking others from accessing data, which ensures data integrity but hurts concurrency and performance. Optimistic locking assumes conflicts are rare and only checks for them upon saving, which improves throughput but requires logic to handle conflicts when they do occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
