INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6ff3247-de5f-42ec-a67c-426f8fe7db82', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a null value?', N'Intern', N'A null value represents the absence of data in a database field. It is not the same as zero or an empty string, but rather indicates that the value is unknown, missing, or not applicable. Handling nulls correctly is essential to avoid errors in calculations or logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76618f9f-ccc5-44f2-a2e7-4274b9aa0f72', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing for high availability, what are the trade-offs between rate limiting at the edge versus at the service level?', N'Senior', N'Rate limiting at the edge is highly efficient for protecting the entire infrastructure from DoS attacks, but it lacks the granularity of service-level limits. Service-level limiting allows for fine-tuned protection based on user importance or specific resource costs, but it requires each service to handle its own throttling logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f861a6cb-ba3d-431c-b590-42755ae81286', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar facilitate testing of complex dependency injection scenarios?', N'Senior', N'Litestar provides a robust test client that allows for dependency overriding, meaning you can swap production dependencies for mocks or stubs during unit tests. This capability enables isolated testing of business logic without needing to mock every external service or database connection explicitly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71c1fed8-7122-4198-aa35-42767ce522e3', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch ensure data consistency?', N'Intern', N'Elasticsearch uses a primary-replica model where all indexing operations happen on the primary shard first. Once the primary completes the operation, it replicates the changes to all active replica shards before confirming success.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21213b35-478e-41d7-a2e0-4276ba7b4342', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What does it mean for a string to be immutable in C#?', N'Fresher', N'An immutable object is one that cannot be changed after it is created. In C#, every time you perform an operation that modifies a string, such as concatenation or replacement, the system creates a brand new string object in memory rather than modifying the original one.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85f98832-ac53-48ae-ad77-42786007c7e9', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the benefit of using functional components in Preact over class components?', N'Senior', N'Functional components are lighter and more idiomatic in Preact, as they do not require an internal instance or lifecycle overhead. They encourage a declarative programming style and are better optimized by Preact''s renderer, leading to cleaner code and slightly better performance metrics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa805b2e-844b-4399-a61a-427f4fb41f73', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What does the ''go run'' command do?', N'Fresher', N'The go run command compiles and executes the specified Go source files in a single step. It is primarily used for quick testing and development rather than building production binaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f80f3f1d-449b-43c3-be21-427fcbd0d9fb', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Explain the architectural implications of Rocket''s managed state system.', N'Senior', N'Rocket''s managed state provides a thread-safe, type-safe container for shared resources like database pools or configuration objects. By injecting these dependencies at runtime through the framework, it simplifies testing and ensures that shared resources are properly initialized and lifecycle-managed across the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'daaf0626-3230-4800-b02d-4283624303f4', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Explain the significance of the ''Request Guards'' mechanism in Rocket''s architecture.', N'Senior', N'Request guards act as a middleware alternative that enforces strict type-based validation on incoming requests. By requiring specific types to be present in function arguments, Rocket ensures that business logic only executes if the request satisfies all security and data integrity constraints before entering the handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63626abe-f50a-4a45-9ba7-42844148857e', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is Edge.js in the context of AdonisJS?', N'Intern', N'Edge.js is the official template engine for AdonisJS. It allows developers to create dynamic HTML pages by injecting data from the server into templates, offering features like loops, conditionals, and component partials.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e570b284-9ff4-47c3-b1d2-4287d8e29a2b', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does the ''with'' statement improve resource management?', N'Middle', N'The ''with'' statement, or context manager, ensures that resources such as files or network sockets are properly acquired and released regardless of whether an exception occurs. It automates the setup and teardown logic, making the code cleaner and more robust against resource leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46f2433d-d35b-4710-8aa1-4289111702a3', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix implement ''prefetching'', and why is it useful?', N'Middle', N'Remix can prefetch data and assets for links on the page when the user hovers over them or when they enter the viewport. This makes navigation feel instantaneous, as the data required for the next page is already available in the browser''s cache before the user clicks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6d2e864-b610-4bd7-be97-42891c92997d', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Why is ''Defense in Depth'' considered an architectural strategy rather than a security product?', N'Senior', N'Defense in depth involves layering multiple security controls to protect data so that the failure of any single component does not lead to a total system compromise. It requires a holistic design that integrates network, application, host, and data-level security to create redundant, non-correlated barriers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
