INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bde16999-69ea-48a8-8d3a-42a8191964b2', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is method overloading versus method overriding?', N'Junior', N'Overloading occurs when multiple methods in the same class share the same name but have different parameter lists. Overriding occurs when a subclass provides a specific implementation for a method that is already defined in its parent class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3677527-8426-448b-bb14-42a95a0f3190', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does ''read repair'' contribute to consistency in a distributed system?', N'Senior', N'Read repair proactively fixes data inconsistencies during a read operation by comparing versions from multiple replicas. If the system detects a mismatch, the coordinator updates the stale nodes with the latest data, effectively pushing data maintenance into the read path to ensure correctness without waiting for background anti-entropy jobs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
