INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b178248-e4af-4e94-b23f-42aed8d64ad3', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a database deadlock and how can it be minimized?', N'Middle', N'A deadlock occurs when two or more transactions hold locks that the others need, creating a circular dependency. It can be minimized by accessing tables in a consistent order, keeping transactions short, and using lower isolation levels where appropriate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
