INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b6a33ec-392f-4378-9542-42b8d4060f69', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What are the architectural considerations when choosing between Spring WebFlux and Spring MVC for high-load services?', N'Senior', N'Spring WebFlux is designed for reactive, non-blocking I/O, making it ideal for high-concurrency scenarios with significant wait times. Spring MVC is better suited for standard, blocking I/O applications where simplicity and the availability of mature blocking libraries are more critical than raw throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'443b073c-c3f0-4d43-8dc4-42b98ab6170a', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between horizontal scaling and vertical scaling for a backend server?', N'Junior', N'Vertical scaling involves increasing the power of a single machine, which is simple to implement but has an upper limit on capacity. Horizontal scaling adds more machines, which provides nearly infinite capacity but increases the complexity of load balancing and data synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
