INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c16e3e61-8da6-4bb0-ad91-42bf19b32653', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Compare ''Parallelism'' in loaders versus ''Thread-loader'' for build performance.', N'Senior', N'Webpack has some internal parallelism, but thread-loader offloads expensive loaders to a worker pool. This is useful for CPU-intensive tasks like transpilation, but it introduces overhead for inter-process communication, so it should only be used for heavy operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92e523cc-2403-4669-9988-42c6ee62d436', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Explain the concept of ''Unsafe Rust'' and why it is a necessary component of the language architecture.', N'Senior', N'Unsafe Rust provides an escape hatch that allows developers to perform operations the compiler cannot verify for safety, such as dereferencing raw pointers or calling FFI functions. It is necessary because low-level systems programming requires interacting with hardware or memory-mapped IO, which are inherently outside the scope of static borrow checking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
