INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e001d07-3306-4afa-a0f8-430cc8c9a60c', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the difference between DELETE and TRUNCATE.', N'Fresher', N'DELETE is a DML command used to remove specific rows from a table based on a condition, and it maintains a log for each deleted row. TRUNCATE is a DDL command that removes all rows from a table at once, which is generally faster but cannot be used with a where clause.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2048d83b-7f0f-424b-b8c4-430f322db2fc', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the significance of Hono''s ''Request'' and ''Response'' objects?', N'Fresher', N'Hono is built upon the standard Web Standards API for Request and Response objects. This makes the framework familiar to anyone who has worked with standard browser APIs or Fetch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'130780bd-cfd1-4fdb-8910-43122f8217af', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why is data integrity important?', N'Fresher', N'Data integrity ensures the accuracy, completeness, and consistency of data throughout its lifecycle. It prevents invalid data from being entered into the database and maintains reliable relationships between tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd1de920-d31f-43df-a589-431e602089ca', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why is it often recommended to use an incrementing integer rather than a UUID for a primary key in InnoDB?', N'Senior', N'InnoDB''s clustered index requires data to be stored in physical order; random UUIDs cause frequent page splits and massive fragmentation. Incrementing integers ensure pages are filled sequentially, optimizing write performance and minimizing the need for expensive page reorganization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e572a68e-6a2b-4170-8450-432086a5e130', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is Dart and what is it primarily used for?', N'Fresher', N'Dart is a client-optimized, object-oriented programming language developed by Google. It is primarily used for building fast, multi-platform applications for mobile, desktop, and the web, especially through the Flutter framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74833afb-e4c7-4105-8dd1-432149062309', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Why is Astro considered a ''multi-page application'' (MPA) framework?', N'Fresher', N'Astro is considered an MPA framework because it follows the traditional web model where each page navigation triggers a full browser refresh. This approach simplifies state management and improves SEO compared to the client-side routing used in many SPAs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e6ad84d-f4e1-43ca-a53a-4322d02867c5', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the trade-offs of using Phoenix View templates versus JSON APIs.', N'Middle', N'View templates render HTML on the server, which is better for SEO and initial load times but requires full page refreshes or LiveView for updates. JSON APIs decouple the backend from the frontend, allowing for multi-platform support, but increase complexity in client-side state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'135faf7e-4cf6-488a-9021-4322d836e5b0', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a wide row in Cassandra?', N'Intern', N'A wide row is a row that contains a large number of columns. Cassandra is optimized to handle these efficiently, unlike relational databases which perform poorly with very high column counts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8985791b-c437-40db-b5cb-432541208283', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix optimize the performance of JSON serialization?', N'Middle', N'Actix integrates with the Serde library, allowing it to leverage Rust''s compile-time code generation for serialization and deserialization. This avoids expensive runtime reflection, resulting in extremely high-throughput JSON processing compared to interpreted languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82fb019b-a57d-491e-81fc-4326c33c3775', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are indexes and how can they improve query performance?', N'Intern', N'Technical Audit: SQL Indexing (2026 Edition) Indexes are auxiliary data structures that decouple physical data storage from logical retrieval patterns. By maintaining a pointer-based reference system, they reduce the search space from $O(n)$ (full table scan) to $O(\log n)$ (tree-based traversal) or $O(1)$ (hash-based lookup). Mechanism of Performance Gains * Logarithmic Complexity: Using balanced tree structures, the engine navigates a height-constrained path to locate specific row identifiers (RIDs) or clustered keys. * Disk I/O Optimization: Indexes permit Index-Only Scans, allowing the database to satisfy a query directly from the index tree without fetching the full data page from secondary storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf011cb1-6b5c-462d-bc45-43278f799c38', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you approach the trade-off between hardware-level optimization and portability?', N'Fresher', N'Hardware-specific optimizations can squeeze maximum performance out of a system but make the software difficult to move to different environments. Portability is generally preferred for broader compatibility, unless the application has extreme performance requirements that only hardware-specific code can meet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbe689e6-7ee7-4a94-a415-432a4bcf2748', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the Symfony ''bin/console'' tool?', N'Junior', N'The console tool is a command-line interface that allows developers to perform common maintenance tasks. It is used for clearing caches, generating boilerplate code, running database migrations, and checking application status.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9cfce2d9-0f4b-49df-8d64-432b6322424c', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is Flask-SQLAlchemy?', N'Intern', N'Flask-SQLAlchemy is an extension that simplifies the use of the SQLAlchemy database toolkit within a Flask application. It handles the setup and configuration required to interact with databases using Python objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de52c919-a6e0-4685-ba1f-432e6c31a3e9', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How do selectors (like reselect) optimize Redux performance?', N'Senior', N'Selectors optimize performance by implementing memoization, which prevents expensive re-computations of derived data when the input state hasn''t changed. They ensure that components only re-render if the specific slice of state they rely on has been updated, significantly reducing unnecessary reconciliation cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a87d9b6a-40dd-4b6d-b6b4-432fe36fe4b3', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS achieve small bundle sizes?', N'Fresher', N'SolidJS achieves small bundle sizes by compiling components into efficient, imperative DOM instructions. Because it does not ship a virtual DOM runtime, the amount of framework code sent to the browser is significantly reduced.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
