INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab0871f9-3636-4172-9f06-4331a9679d41', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Is DynamoDB schema-less?', N'Fresher', N'Yes, DynamoDB is considered schema-less because it does not require you to define the structure of the data before inserting it. You only need to define the primary key, and every other attribute can be added dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2cd548f-b696-4012-8da7-4333b2c70572', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Explain the architectural trade-offs between Redis RDB snapshots and AOF persistence.', N'Senior', N'RDB creates point-in-time snapshots which are efficient for backups and fast restarts but risk data loss between intervals. AOF logs every write operation, providing higher durability at the cost of larger file sizes and potentially slower recovery times due to log replay.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6728229-d5c1-4eb8-9a1f-433531ae93bd', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are the implications of using global state in a high-concurrency PHP application?', N'Senior', N'Global state in PHP is limited to the scope of a single request, but using global variables or static properties can lead to tightly coupled, difficult-to-test code. In multi-threaded environments, global state can also lead to race conditions if not properly managed, though PHP''s request-isolation naturally mitigates the worst of these risks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89f246b7-993a-49cf-8653-433589567d20', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the difference between client-side rendering and server-side rendering?', N'Intern', N'Client-side rendering happens in the browser, where the JavaScript bundle is downloaded and executes to build the UI. Server-side rendering happens on the server, where the initial HTML is built before being sent to the browser, allowing the content to be visible immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad9e1bd5-3337-45e8-964a-43364f3fa1bb', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the difference between a value receiver and a pointer receiver?', N'Fresher', N'A value receiver operates on a copy of the object, while a pointer receiver operates on the actual object. Pointer receivers are used when the method needs to modify the original data or to avoid copying large structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8239deb7-1aa3-45e9-9f36-4336b07b9989', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What role do ''Symbols'' play in Qwik''s architecture?', N'Senior', N'Symbols are unique, stable identifiers used by the Qwik optimizer to map serialized state to lazily-loadable code chunks. They allow the framework to know exactly which file and function to fetch when an event is triggered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf708baf-c86f-4007-bf16-433759b55aa9', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Explain the purpose of the ''viewport'' meta tag and why it is critical for responsive design.', N'Middle', N'The viewport meta tag provides the browser with instructions on how to control the page''s dimensions and scaling on different devices. Without it, mobile browsers often render pages at a desktop width and shrink them to fit, leading to poor readability and requiring users to zoom in manually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99588d2f-0048-4788-abb7-433841ccc3d3', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain the mechanics of the CSS Containment property and how it helps optimize rendering performance.', N'Senior', N'The contain property allows developers to isolate a subtree of the DOM from the rest of the page layout. By signaling that changes within an element do not affect its parent or siblings, the browser can skip expensive style and layout calculations for the entire document, isolating the impact of dynamic updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9daadca0-98f7-4147-953a-433f0fb76262', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the benefit of using a ''factory function'' to initialize Flask extensions?', N'Middle', N'Most Flask extensions provide a ''lazy'' initialization method where you define the extension object globally and then call ''init_app'' inside your factory function. This allows you to attach the extension to the application instance at runtime, which is necessary for the application factory pattern and avoids issues with circular dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
