INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7949fdf8-66f8-4e36-8164-433fd3eba3f0', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What are the performance implications of Chi''s routing tree implementation on memory usage?', N'Senior', N'Chi uses a radix tree-based routing structure, which is memory-efficient and provides O(k) lookup time where k is the length of the path. This approach minimizes allocations during the routing process, making it highly suitable for high-throughput services with a large number of defined endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1993bd7-c4ff-4a85-a9e5-43410dcc0c39', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask''s ''stream_with_context'' function improve memory efficiency for large responses?', N'Senior', N'It allows the application to stream data directly to the client while maintaining the request context, which is essential for processing large datasets that would otherwise exceed RAM limits. By yielding chunks of data, the server keeps its memory footprint low and provides a faster time-to-first-byte for the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9bfdb05-c4d2-42ee-856d-43419cecf415', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the ''base'' keyword?', N'Fresher', N'The base keyword is used to access members of the base class from within a derived class. It is commonly used to call a base class constructor or to invoke a method that has been overridden in the derived class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74b0d79c-927a-40fc-9b1c-43419edfe552', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the significance of the Content-Type header in an API request?', N'Middle', N'The Content-Type header tells the server how to interpret the request body, such as JSON, XML, or form data. It is essential for ensuring that the server correctly parses the input and avoids errors during deserialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'838f961a-e8c5-4941-b5fb-4342b2555f82', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between eager_load, preload, and includes in ActiveRecord?', N'Middle', N'Preload always executes a separate query for associations, while eager_load uses a LEFT OUTER JOIN to fetch everything in one query. Includes is a smart wrapper that decides whether to use preload or eager_load based on the complexity of the query, though it defaults to preload unless references are explicitly provided.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f258ff1-ec86-4b1c-9123-43474f17b821', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are pseudo-class variants in Tailwind CSS?', N'Fresher', N'Pseudo-class variants allow you to apply styles based on the state of an element, such as hover, focus, or active states. You use them by prefixing the utility class with the state name, like hover:bg-blue-500.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37383209-dff5-4474-9d2b-434902a8ca0d', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the heap in memory management?', N'Intern', N'The heap is a large pool of memory used for dynamic memory allocation requested by the programmer during runtime. Unlike the stack, memory on the heap must be manually allocated and deallocated by the programmer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7dba710-55fe-4dbe-b88f-43493d23ee08', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis manage memory fragmentation and what are the architectural implications of its single-threaded event loop on long-running operations?', N'Senior', N'Redis uses the jemalloc allocator to manage memory, and while it provides internal defragmentation capabilities, heavy fragmentation can lead to increased memory overhead and latency spikes. Because Redis operates on a single-threaded event loop, any command with O(n) complexity, such as KEYS or large HGETALL calls, will block the entire server, preventing it from processing other requests and causing significant head-of-line blocking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'357263c5-8753-4a76-8655-434a03b53bfe', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is a Partial Function?', N'Intern', N'A partial function is a function that is only defined for a specific subset of possible input values. It provides a way to define behavior that only applies to certain data while ignoring or handling undefined inputs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e044d0d-f975-460e-863a-434ac90921c9', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle middleware compared to the standard library?', N'Junior', N'Chi provides a built-in middleware stack that allows developers to chain functionality like logging, recovery, and authentication easily. It follows the standard http.Handler interface, ensuring that any middleware compatible with the standard library works seamlessly with Chi.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40fc8b1a-8e54-4bb4-8e5d-434c513e4f38', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the impact of long-running transactions on a database?', N'Middle', N'Long-running transactions hold locks for extended periods, blocking other operations and causing a backlog of queries. This can lead to connection exhaustion and performance degradation, negatively impacting the scalability of the entire system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fad3411-a16c-4ada-95fd-434e4e7d44f9', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the purpose of the @Res() decorator in NestJS controllers?', N'Intern', N'Nest provides @Res() and @Response() decorators. @Res() is simply an alias for @Response(). @Res() or @Response()allows you to directly interact with the response object and use its methods. When using them, you should also import the typings for the underlying library (e.g., @types/express) to take full advantage. Here is an example of using @Res() decorator: Note When you inject either @Res() or @Response() in a method handler, you put Nest into Library-specific mode for that handler, and you become responsible for managing the response. When doing so, you must issue some kind of response by making a call on the response object (e.g., res.json(...) or res.send(...)), or the HTTP server will hang.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56fd9ee2-16ab-430f-8bce-434f9ea39ce5', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the purpose of Dependency Injection in NestJS?', N'Intern', N'Dependency Injection is a design pattern where a class requests its dependencies from an external source rather than creating them itself. In NestJS, this allows the framework to manage the lifecycle of objects, making components easier to test, decouple, and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe340b0b-49da-408c-920b-435406e7e0d5', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the role of a quorum in distributed database operations?', N'Senior', N'Quorum is a mechanism where a majority of nodes must agree on a write or read to ensure consistency. It provides a flexible trade-off between consistency and availability by allowing the system to proceed as long as a minimum number of replicas are reachable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd85fa55-a556-4acd-8f03-4354d7498cd4', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What are the primary trade-offs when implementing database sharding?', N'Senior', N'Sharding increases write throughput and storage capacity by partitioning data across multiple nodes. However, it introduces significant complexity in cross-shard joins, complex transactions, and rebalancing data as the cluster grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91eb4008-cf05-4c68-8f67-4355e3cbe96b', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of ''Health Checks'' in a production ASP.NET Core environment?', N'Middle', N'Health checks provide endpoints that report the status of the application and its dependencies, such as databases or external APIs. These endpoints are used by orchestrators like Kubernetes to determine if an instance is ready to receive traffic or needs to be restarted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'196172f7-f436-4658-b652-435624782096', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte''s event forwarding mechanism maintain encapsulation?', N'Senior', N'Svelte allows components to forward events from internal elements to parent components using a simplified syntax without a corresponding handler. This maintains strict component boundaries while avoiding the need for prop-drilling or complex custom event emitters, keeping the component API clean and predictable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60fe832a-1b87-4f0e-b13e-4357410b4e55', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are Fiber ''Hooks'' and when would you use them?', N'Junior', N'Hooks are lifecycle events that allow you to execute code at specific moments, such as when the application starts or shuts down. They are useful for tasks like initializing database connections, setting up background workers, or closing resources gracefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
