INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd35b6203-ea05-428f-aee0-4358c01d5bf6', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is the use of the volatile keyword important in systems programming, and when should it be used?', N'Middle', N'The volatile keyword prevents the compiler from performing optimizations on a variable that might change outside the program''s control, such as memory-mapped hardware registers or variables modified by signal handlers. It forces the compiler to perform a fresh read from memory every time the variable is accessed, ensuring the code reflects the actual current state of the hardware or external environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e084c0b2-7999-400f-9748-43599a81740d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between monolithic deployments and containerized microservices orchestration?', N'Middle', N'Container orchestration like Kubernetes allows for fine-grained resource management and automated scaling but requires a steep learning curve and constant maintenance. A monolithic deployment on virtual machines is easier to manage for small teams but lacks the resilience and scalability features that modern orchestration provides.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd11e6add-9223-4852-a1dc-4359da3c8881', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the advantage of using the ''Fiber'' framework for a junior developer?', N'Junior', N'Fiber has a very expressive and easy-to-read API that mimics other popular frameworks like Express. This makes it easier for developers to get started with building APIs in Go without needing deep knowledge of low-level networking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3ece24d-2c58-4215-b37f-435b9b74850b', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the difference between a Controller and a Service?', N'Intern', N'A controller is responsible for handling the HTTP layer, such as parsing requests and sending responses. A service is responsible for the internal business logic and data manipulation that occurs between the request and the response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61726602-9900-4d0e-afb8-435c3d52984b', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch achieve horizontal scalability and what is the role of the primary and replica shards?', N'Senior', N'Elasticsearch scales horizontally by distributing shards across a cluster of nodes. Primary shards handle write operations, while replica shards provide high availability and increase read throughput by allowing parallel search requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
