INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'850d28ba-9aba-4cb0-bfc6-43658ff0229f', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a Read Repair in Cassandra?', N'Fresher', N'Read repair is a background process that compares data from multiple replicas during a read request. If it detects inconsistencies, it updates the replicas with the most recent data version.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f05301f-844a-4aa8-981d-436bc0a551df', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a Local Secondary Index?', N'Intern', N'A Local Secondary Index (LSI) has the same partition key as the base table but a different sort key. It must be created at the time the table is created and resides in the same partition as the base table item.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1400ca4-19a6-4098-b8b4-436c406e8207', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What does it mean for Redis to be ''atomic''?', N'Junior', N'Redis operations are atomic, meaning they are processed as a single, indivisible step. Because Redis is single-threaded, it ensures that no other client can interrupt or modify the data in the middle of a command execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf23de81-2f1d-4ab2-9eff-436ddf78f3ab', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Explain the purpose of lifetimes in Rust and why they are necessary.', N'Middle', N'Lifetimes are a compile-time construct that ensure references remain valid for as long as they are used. They prevent dangling pointers by guaranteeing that the data a reference points to outlives the reference itself, allowing the compiler to verify memory safety without a garbage collector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3359bfd8-c96f-4c15-94cb-4370ab120e71', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the purpose of the ''infix'' modifier?', N'Junior', N'The ''infix'' modifier allows a function to be called without using dots or parentheses, using an infix notation instead. This can make code look more like a natural language sentence, improving readability for specific DSL-like scenarios. It can only be used on member functions or extension functions with exactly one parameter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'698edb3a-c324-4468-98a9-43715a008f66', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the purpose of ''retroactive estimation'' or analyzing past tasks?', N'Junior', N'Analyzing past tasks helps identify patterns where estimation was consistently off, allowing the team to improve their accuracy for future planning. It highlights areas where the team might need more training or where processes are causing unexpected delays.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48ef8b02-d2b4-4e61-a782-4373610657b8', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do you manage dependency management in a complex Sass project?', N'Senior', N'Dependency management is handled by creating a clear entry point file that imports modules in a specific order based on their concerns. Using the @use rule ensures that dependencies are loaded only once, and keeping variables and mixins in distinct configuration files helps prevent circular dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
