INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b97a3ec-80e8-4177-b4a2-43760226b950', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does CSS specificity work?', N'Junior', N'Specificity determines which CSS rule is applied by the browser when multiple rules target the same element. Browsers assign a weight to selectors based on their type, such as IDs, classes, and tags, with IDs having the highest priority.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e4daa92-c431-4c42-9bc0-4377c0b5d90c', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What happens if a user interacts with a component before its required JavaScript is downloaded?', N'Senior', N'Qwik handles this by using a small, high-priority listener that buffers the event. Once the required JavaScript chunk is fetched and executed, the framework replays the buffered event, ensuring the user experience remains seamless without dropped interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc0f7d45-afcb-490a-a186-4378380bcea5', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the difference between ''text'' and ''keyword'' data types?', N'Intern', N'The text type is used for full-text search, meaning the field is analyzed before indexing. The keyword type is used for exact matches, sorting, and aggregations, as it is not analyzed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa309772-a24b-4d7e-bc93-4379c5a1e323', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How do you ensure data consistency in a distributed caching environment?', N'Middle', N'Consistency can be managed via cache invalidation, using TTLs to force refreshes, or employing distributed locking mechanisms. Developers must weigh the cost of strict consistency against the performance benefits of eventual consistency depending on the business requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
