INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e37ec051-bde8-4db6-81ca-437fd251e8bc', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Why does AdonisJS prefer a ''Controller-Service'' architecture over ''Fat Models''?', N'Senior', N'By separating business logic into dedicated service layers, the codebase becomes more maintainable and easier to unit test. Fat models lead to tight coupling with the database layer, whereas a service-oriented approach allows for orchestrating multiple models and external APIs without bloating the ORM definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f29fa68-dad8-45d8-b95e-43803761cf20', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between an array and a set?', N'Intern', N'An array is an ordered collection of values that can contain duplicates. A set is an unordered collection of unique values, meaning it does not allow duplicate entries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
