INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'666788f8-d21f-48e2-99ed-4381e52c0848', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the difference between Redux and the React Context API for state management?', N'Middle', N'Context is primarily designed for passing data down the component tree without prop drilling, but it does not provide built-in state management logic. Redux offers a structured, predictable architecture with middleware, dev tools, and optimized performance for complex applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43b5074a-8a98-497e-a4ac-4382cf87ea9c', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does a write-ahead log (WAL) contribute to durability in NoSQL?', N'Middle', N'A write-ahead log records operations in a durable file before they are applied to the main data store. This ensures that in the event of a system crash, the database can replay the log to recover uncommitted transactions, maintaining data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
