INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d79df6c-0ba8-481a-a2bf-43840ff69c9e', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does the Ruby interpreter handle constant lookup, and why can this lead to unexpected behavior in nested modules?', N'Senior', N'Ruby uses a lexical scoping rule combined with the nesting of modules and classes to resolve constants. The lookup first checks the current lexical scope, then traverses the ancestor chain, which can cause shadowing or unexpected resolutions if constants with the same name exist at different levels of the hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8305e120-68b0-4a5f-bdf0-438a921de662', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does hoisting interact with the class declaration?', N'Fresher', N'Class declarations are hoisted to the top of their block scope — like let and const — but they are not initialised until the declaration is evaluated. This means they sit in the Temporal Dead Zone (TDZ) and accessing a class before its declaration throws a ReferenceError, not a TypeError. This is a deliberate choice to prevent confusing inheritance hierarchies from being constructed before base classes are fully defined. Example: Practical implication — class vs. function constructor: Real-World Use Case: When splitting large Node.js services into files with circular require() references, class-based modules that are accessed during the require() cycle before the class declaration evaluates throw ReferenceError.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'926dba05-8f4d-42f7-a9f6-438aad95a085', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is it important to define the ''Content-Type'' explicitly in Fiber responses?', N'Middle', N'While Fiber attempts to infer the content type, explicit definitions prevent browser-side security vulnerabilities like MIME-sniffing. Setting the correct header ensures that client-side applications correctly parse the response data, which is standard practice for robust API development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2df2ad28-a21a-48a0-89c7-438b967874cf', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the benefit of the AdonisJS ''Ace'' CLI from an architectural standpoint?', N'Senior', N'Ace provides a standardized way to execute administrative tasks, migrations, and scaffolding, ensuring consistency across a team. By centralizing management commands, it enforces project conventions and reduces the risk of manual errors in deployment or maintenance scripts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be09374d-74e2-44d8-8b66-438d783ae5cb', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How do Fastify hooks differ from middleware in terms of execution control?', N'Middle', N'While middleware is often executed in a linear chain, Fastify hooks are tightly integrated into the framework''s lifecycle and offer precise control over the request flow. Hooks allow for faster execution because they avoid the overhead of the extra function wrappers typically found in middleware-based frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21627632-b747-4e7b-981c-438e49685555', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What does ''referential transparency'' mean in Scala?', N'Middle', N'Referential transparency is a property of a function where an expression can be replaced by its resulting value without changing the program''s behavior. This indicates that the function has no side effects and is essential for writing pure functional code that is easier to test and parallelize.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'389e8edc-901d-4ff9-8627-438ee96797d6', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the concept of ''Existential Containers'' in Swift.', N'Senior', N'An existential container is the structure used to represent protocol types, containing the value, the witness table for the protocol, and type metadata. When an existential is used, the compiler must box the value, which introduces a runtime cost and limits optimization. Using generic constraints instead of existentials allows the compiler to use static dispatch, avoiding the existential overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7ef96ac-e2d6-4374-aee7-438f8e35b1a3', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the main features of C++?', N'Intern', N'C++ is renowned for its diverse set of features, many of which it inherited from C but also enhanced and expanded upon. These features enable a wide range of programming paradigms, from procedural to object-oriented and generic programming. Key Features Efficiency - Low-Level Access: Pointers, direct memory manipulation. - Resource Management: Smart pointers, deterministic destructors with RAII. - Inline Functions: Eliminates function call overhead. - Move Semantics: Transfers resources rather than copying. Flexibility in Types - Strongly-Typed: Encourages type safety. - Type Inference: auto keyword deduces types. - Concepts (C++20): Constraints and requirements for templates. Multiple Paradigms - Procedural: Functions and control structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5adbf5b-2f3e-4d7f-a835-4393081fb68a', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is a Queue in Laravel?', N'Intern', N'Queues allow you to push time-consuming tasks, such as sending emails or processing images, to a background process. This improves the user experience by allowing the web request to finish quickly without waiting for the task to complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c07d17ef-9dfb-4c9c-9aa5-43964e2d093e', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the benefit of a ''modular'' design approach?', N'Intern', N'A modular design breaks a large system into smaller, self-contained units that can be developed and tested in isolation. This simplifies the development process, allows teams to work in parallel, and makes the system more robust against localized bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97cd4bb4-63b5-4bd3-b660-43966cc1b665', N'954a0331-deff-4399-b588-96f39fec001d', N'What is an observable and how is it used?', N'Intern', N'An Observable represents a stream of data or events over time. It''s a core concept in reactive programming and is used extensively in Angular for handling asynchronous operations like HTTP requests, user input events, and routing changes. Think of it as a producer that pushes multiple values to consumers (called Observers) over time. You subscribe to an Observable to start receiving these values. Key characteristics: - Lazy: Nothing happens until you subscribe - Asynchronous: Designed for operations that complete over time - Multiple values: Can emit zero, one, or many values - Cancellable: Subscriptions can be easily cancelled - Composable: Can be transformed and combined using operators In Angular, you''ll commonly subscribe to Observables returned by the HttpClient for API calls, or Obse...', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbea4d04-e2d5-42f3-8820-43967b85d170', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the advantages of using Redis Sorted Sets for leaderboards compared to relational databases?', N'Senior', N'Sorted Sets allow O(log N) insertion and range retrieval, which is significantly faster than SQL index-based sorting for high-frequency updates. They maintain a strict order and provide efficient rank-based queries, which are computationally expensive to perform in relational tables under high load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acff1c90-f488-47c4-8b53-439d1db44372', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the trade-offs of using a Document store versus a Relational database for highly evolving schemas?', N'Senior', N'Document stores offer schema flexibility, allowing developers to iterate quickly without complex migration scripts, which is ideal for unstructured or polymorphic data. Relational databases enforce strict schemas that provide data integrity and complex querying capabilities, though they require more significant architectural overhead when changing table structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7abb0d16-173c-4224-b60b-43a3b58ac80f', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What does ''convention over configuration'' mean in the Ruby community?', N'Intern', N'This principle suggests that developers should follow established naming and structural patterns rather than writing explicit configuration files. By adhering to these conventions, the language and frameworks can make intelligent assumptions, reducing the amount of setup code required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'499cbcf9-f463-4522-bf0c-43a5f5b90001', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What are Gin middleware functions?', N'Junior', N'Middleware functions are blocks of code that run before or after the actual request handler. They are commonly used for tasks like logging, authentication, error recovery, and modifying request or response headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee1ed99a-c396-47ce-b56a-43a84f6993a5', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the difference between a Phoenix View and a Phoenix Template?', N'Intern', N'A view is a module that contains logic to format data for the user, while a template is the file that contains the HTML structure with embedded code. The view provides the data that the template renders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7857fa03-a880-49d1-bec1-43a9fa429e5f', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How do you set custom HTTP headers in Fiber?', N'Intern', N'Fiber provides methods on the context object to set or append values to HTTP headers. This is commonly used for security policies, caching instructions, or custom application metadata.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1eb20bc-ecef-4614-8dda-43aa2cb04809', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is ''Preflight'' in Tailwind CSS?', N'Intern', N'Preflight is a set of base styles based on modern-normalize that Tailwind injects into your project. Its primary purpose is to smooth out cross-browser inconsistencies and provide a reliable baseline for your layout.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb42b688-33e4-4f11-a1b3-43b355baa704', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the significance of the ''Secure'' flag on cookies?', N'Middle', N'The ''Secure'' flag ensures that a cookie is only transmitted over encrypted (HTTPS) connections. This prevents the cookie from being sent in plain text, which would expose session identifiers to interception over insecure networks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd142245-ac21-4b97-8251-43b3566e8d5d', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the primary benefit of using immutable data structures in Scala?', N'Middle', N'Immutable data structures are inherently thread-safe because their state cannot change after creation. This eliminates the need for complex locking mechanisms in concurrent programming and makes the code easier to reason about and test.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e64a5f4-658f-41ac-b135-43b38dfc95cb', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs between using a queue-based system for load shedding versus rejecting traffic during peak load?', N'Middle', N'Queueing buffers incoming requests to handle bursts, improving overall throughput at the cost of increased latency for those requests. Rejecting traffic ensures that the requests that are processed remain responsive, but it leads to a degraded user experience for the rejected traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e3d6e67-5213-4836-aab2-43b517e1eedf', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When debugging, how do you manage your own frustration?', N'Junior', N'I find that stepping away from the screen for a few minutes helps clear my head and allows me to approach the problem with a fresh perspective. Breaking the problem into smaller, manageable parts also makes the task feel less overwhelming and more actionable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91495d93-84f5-41ca-835e-43b7c4bf73f0', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you balance feature flags and branch-based development in a large engineering team?', N'Senior', N'Feature flags decouple deployment from release, allowing for gradual rollouts and safer experimentation, but they add code complexity and require active lifecycle management to avoid ''flag rot.'' Branch-based development isolates work but can lead to long-lived merge conflicts and integration delays. I prefer feature flags for continuous integration environments to maintain a single source of truth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab259bfe-940d-45b7-b875-43babc44d990', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does the ''Phoenix.Template'' engine contribute to performance compared to string-based concatenation?', N'Senior', N'Phoenix compiles templates into optimized functions at compile-time rather than interpreting them at runtime. This leads to extremely fast rendering, as the server executes pre-compiled code to generate the final response, minimizing CPU cycles during the request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd418e57-ecb8-4151-aa3c-43baca199f52', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the difference between .find() and .children()?', N'Intern', N'.children() only looks at the immediate direct descendants of an element. .find() searches through all descendants of an element, regardless of how deep they are in the DOM tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3436e422-3009-40e3-bd33-43bb5288f511', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the role of the ''noShadow'' static property in Lit?', N'Middle', N'Setting noShadow to true disables the creation of a shadow root for the component. This causes the component''s template to be rendered directly into the light DOM, which is useful when you need global styles to apply to the component or when integrating with specific third-party libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
