INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29a96724-72f0-4303-871f-43c0850e195a', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are constraints in SQL?', N'Fresher', N'Constraints are rules applied to columns of a table to limit the type of data that can be inserted. Common examples include NOT NULL, UNIQUE, PRIMARY KEY, and CHECK, which help maintain data accuracy and integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a2ef873-d884-4345-a190-43c0d885d5a0', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why does Axum require the ''Clone'' trait on shared state?', N'Middle', N'Because handlers may be executed concurrently on different threads, the application state must be shared via a thread-safe reference count. Cloning the state pointer is a cheap operation that allows each request handler to access the shared resource safely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
