INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd077bd4c-c70f-4df3-a577-43cfb0e0f872', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the purpose of the ''yield'' keyword?', N'Fresher', N'The yield keyword is used within a method to invoke a block that was passed to that method. It temporarily pauses the method execution to run the block''s code before returning control to the method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4824f678-d2e3-4ea0-a844-43d36e0a58d2', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does the ''Data Down, Actions Up'' (DDAU) pattern impact scalability in large Ember applications?', N'Senior', N'DDAU enforces a strict unidirectional data flow that makes state transitions predictable and easier to debug. By separating data consumption from mutation logic, it prevents side effects from propagating uncontrollably, which is critical for maintaining consistency in complex component trees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'460745fc-44ad-4f5a-8920-43d571ea824c', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is a ''Plugin'' in the context of Litestar?', N'Intern', N'Plugins in Litestar are used to extend the framework''s functionality. They allow for integration with external libraries, such as database ORMs or authentication systems, by hooking into the application lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6ab8a95-e9a5-4cc7-8cce-43d7ee4343a5', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does the Next.js App Router architecture differ from the Pages Router in terms of server-side data fetching?', N'Senior', N'The App Router leverages React Server Components, allowing data fetching directly within the component tree using async/await patterns. Unlike the Pages Router, which relies on specific lifecycle functions like getServerSideProps, the App Router allows co-location of data logic with UI components, reducing waterfall latency and bundle size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c33a1442-3947-4bab-8070-43dd7fb15b14', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What does ''Nested Routing'' mean in Remix?', N'Fresher', N'Nested routing allows the application UI to be broken down into smaller, hierarchical pieces that match the URL structure. Each segment of the URL corresponds to a component that renders inside the parent layout, making it easy to manage complex page structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee3a3b0a-6290-4ccd-8162-43de00706a80', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How do Rocket''s ''Launch'' and ''Ignite'' phases differ in the application lifecycle?', N'Senior', N'Ignite is the stage where the application is configured, state is managed, and routes are registered, effectively building the server structure. Launch is the final phase where the server starts listening for connections, binding to ports, and executing the server loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e881b4e4-87b1-4fe3-950b-43e2722dfebc', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If your solution fails during testing, what is your process for reacting?', N'Intern', N'I remain calm and document the exact steps that led to the failure. I then compare the actual results to the expected results, isolate the point of failure, and hypothesize potential reasons for the discrepancy before testing a fix.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'457c4ae3-e460-4d4b-91b6-43e2b74065da', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you abort a web request using AbortController in JavaScript?', N'Fresher', N'AbortController is used to cancel ongoing asynchronous operations like fetch requests. Aborting web requests is useful for: - Canceling requests based on user actions. - Prioritizing the latest requests in scenarios with multiple simultaneous requests. - Canceling requests that are no longer needed, e.g. after the user has navigated away from the page. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57d00a44-ed67-4b14-bf2d-43e95a96b75d', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the ''components'' directory used for?', N'Fresher', N'The components directory is where you store your reusable Vue components. Nuxt automatically imports these components, meaning you can use them anywhere in your application without having to write explicit import statements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'708e7180-47e9-438e-9d0a-43e974bb1908', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Describe the ''cluster state'' and why it is a potential bottleneck in very large Elasticsearch clusters.', N'Senior', N'The cluster state contains metadata about all indices, shards, and node mappings. Because it must be kept in memory and replicated across all nodes, an excessively large state—often caused by thousands of indices or millions of shards—can lead to long garbage collection pauses and slow down cluster-wide operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64f0a673-307d-40ba-a40c-43e9fcd92ff0', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle a distributed cache invalidation issue?', N'Middle', N'I would implement a write-through or cache-aside strategy where the database update triggers an invalidation event. If consistency is critical, I would use a distributed locking mechanism or a TTL-based expiration policy to ensure the cache eventually refreshes with the correct data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02aec61e-908e-47ad-b510-43ebe5c8fa26', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle middleware?', N'Intern', N'Chi allows middleware to be easily stacked and applied to specific routes or groups of routes. This enables developers to inject cross-cutting concerns like logging, authentication, and recovery into the request-response lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c7b25f1-5175-4b89-9019-43ec51ad95c2', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why is ''Unsafe'' Rust necessary?', N'Middle', N'Unsafe Rust is required for operations that the borrow checker cannot verify, such as interacting with raw pointers, calling foreign C functions, or performing low-level hardware access. It provides an escape hatch that allows the programmer to override safety checks while maintaining the language''s overall performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
