INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46215a9d-15d1-4e91-ae27-43ec72c64d87', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the advantage of using DTOs (Data Transfer Objects)?', N'Junior', N'DTOs decouple the internal database model from the structure of the data exposed to the client. This prevents exposing sensitive internal fields and allows for cleaner API contracts that do not break when the database schema changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc91209c-4845-4e8d-aa00-43ed8f73b28e', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Discuss the trade-offs of using global module declarations versus explicit imports in large-scale applications.', N'Senior', N'Global declarations are convenient for polyfills or ambient environments but can lead to namespace collisions and unpredictable side effects. Explicit imports are superior for maintainability, as they clearly define dependencies and facilitate better tree-shaking and module isolation within the build pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9da3c7b-2046-4b0f-aa77-43eeed1e17d9', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How can you implement a circuit-breaker pattern within a Hono middleware stack to improve system resiliency?', N'Senior', N'A circuit-breaker can be implemented as a custom middleware that tracks the failure rate of downstream service calls stored in a shared state. If the failure threshold is met, the middleware can immediately return a 503 status code or a cached response, preventing the cascading failure of the primary application while allowing the downstream dependency time to recover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a6937e3-9bff-4a34-904b-43eef992d101', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you stay calm and productive during a production outage?', N'Junior', N'I stay focused by following the established incident response protocol, which helps me stay organized and avoid panic. I prioritize restoring service first and leave deep root-cause analysis for after the system is stable, ensuring clear communication with the team throughout the process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69fcc991-d7d7-4f82-8c41-43f1dd6491f3', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the architectural implications of using Composition API versus Options API in large-scale applications?', N'Senior', N'The Composition API enables better logic reuse through composables and keeps related features grouped together, which significantly improves maintainability in large codebases. The Options API forces a rigid structure based on component properties, which often leads to fragmented code and difficulty in sharing logic across components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6dcf2286-3a75-4b8e-b4d4-43f2e00b1155', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum manage request body buffering and why is this a consideration for large payloads?', N'Senior', N'Axum uses a request body stream that is polled by extractors. For large payloads, developers must be cautious about memory exhaustion, and Axum provides mechanisms like ''ContentLengthLimit'' middleware to protect against malicious or oversized requests before they are fully buffered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a2766d9-a03b-4cc6-b959-43faa69d9840', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the primary architectural bottleneck when using PHP with a traditional blocking I/O model?', N'Senior', N'The blocking I/O model forces the PHP process to sit idle while waiting for network or disk operations to complete, effectively wasting resources. This limits the concurrency per process and requires high process counts to handle heavy traffic, leading to significant memory pressure on the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e643af4-0807-469e-a1a5-43fb4b5da74e', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB handle write contention in high-throughput scenarios?', N'Senior', N'DynamoDB mitigates write contention through its distributed partitioning architecture, which isolates requests to different shards. For high-frequency updates to a single item, it supports atomic counters and conditional expressions to ensure data consistency without requiring heavy application-side locking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02675911-b4f2-4a08-acf8-43fc99f0087d', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s ''Access Control'' (public, internal, private, fileprivate) impact binary size and optimization?', N'Senior', N'Strict access control allows the compiler to perform ''Whole Module Optimization'' by knowing exactly which symbols are visible outside the module. By limiting visibility, the compiler can safely prune unused code and inline internal functions, resulting in smaller binary sizes and improved runtime performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7587a61f-d3ab-4c7b-9f22-43fca9267d2f', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What are the trade-offs of using Qwik compared to a framework like Next.js?', N'Middle', N'Qwik offers superior loading performance for complex apps due to zero hydration, but it requires a different mental model regarding component boundaries. Additionally, the ecosystem and third-party library integration may be less mature than those for established frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73f2e752-c8b9-4799-9df7-43fcdfc0db21', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Why is Alpine.js often called a ''Tailwind for JavaScript''?', N'Fresher', N'This nickname refers to the way Alpine.js allows you to compose behavior directly within your HTML elements, much like Tailwind CSS allows you to compose styles. It focuses on keeping the logic close to the view, promoting a declarative style of development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'821f4ada-bfd1-4726-a61c-43ffda7a885d', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin implement path parameter extraction?', N'Middle', N'Gin uses a radix tree data structure to store route patterns, which allows for O(k) lookup time where k is the length of the path. When a match is found, parameters are parsed and stored in the Context object for easy retrieval.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e8f7507-2c3b-46e7-88b2-44005fab1614', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the primary benefit of using the Layouts system in Next.js?', N'Senior', N'Layouts allow for the persistent UI elements such as headers and navigation to be shared across pages without re-rendering. This prevents unnecessary DOM updates during navigation, preserving the state of the shared components and significantly improving transition performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd33eb15b-e153-466f-a404-44013f45ca4c', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix handle fault tolerance?', N'Fresher', N'Phoenix inherits fault tolerance from the Erlang VM by using supervision trees. If a specific process fails, the supervisor detects the crash and restarts the process to a known good state, preventing the entire application from going down.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a7cd226-bb23-4a0b-9a4e-4401c7af8a55', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Why would you use a ''Form Type'' class instead of building forms in the controller?', N'Middle', N'Form Types encapsulate the definition, validation, and data mapping logic of a form into a reusable class. This keeps the controller thin and allows the same form structure to be used across different parts of the application consistently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'908f2075-ebda-4d6a-8a40-440b3f4f5898', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask''s ''g'' object differ from the session object?', N'Senior', N'The ''g'' object is a temporary storage namespace for the duration of a single request, whereas the session object persists data across multiple requests using a cookie. Data in ''g'' is lost as soon as the request is finished, making it ideal for sharing data between functions during a single execution path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f43d4a6-cd74-4f4f-aca8-440be1dff9a0', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If a system works in a development environment but fails in production, what is the most likely cause?', N'Fresher', N'The most likely cause is an environmental difference, such as configuration settings, permissions, or missing dependencies. You should compare the environments to ensure that the production setup matches the one where the system was successfully tested.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c90228d2-35fd-4ca7-aeb2-440eca9dfae9', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin handle exceptions compared to Java?', N'Fresher', N'Kotlin does not have checked exceptions, meaning you are not forced to catch or declare exceptions in the function signature. This design choice aims to reduce boilerplate code while maintaining safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b3e4a8d-5bd6-434c-b9a6-440f2f9bf06c', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Explain the difference between a UNIQUE constraint and a PRIMARY KEY.', N'Junior', N'A primary key uniquely identifies a row and cannot contain null values, with only one primary key allowed per table. A unique constraint also ensures all values in a column are different, but it allows null values and multiple unique constraints can exist on a single table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c3c0cab-65d7-4762-858c-441084fa22e5', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What are jQuery effects?', N'Intern', N'jQuery effects are built-in methods used to create simple animations, such as fading elements in and out, sliding them up or down, or changing their CSS properties over time. These methods make it easy to add visual feedback without needing deep knowledge of CSS transitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'608ec270-05bc-45a7-9c8f-441219a7d423', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you distinguish between a ''must-have'' feature and a ''nice-to-have'' feature when a deadline is approaching?', N'Junior', N'I define ''must-haves'' as features essential for the core functionality or business value defined in the requirements. ''Nice-to-haves'' are enhancements that improve user experience but are not strictly necessary for the system to function, and these are the first to be deprioritized if time runs out.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bc53a8e-3430-4f50-bf05-4412ee1d388a', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What does the auto_increment attribute do?', N'Fresher', N'The auto_increment attribute is used to generate a unique identity number automatically when a new record is inserted into a table. It is most commonly used for primary key columns to ensure each entry has a unique, sequential identifier.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20546f4b-5aad-4d6b-8ed3-4416124c97bb', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony handle lazy-loading of services to improve memory usage?', N'Senior', N'Symfony uses proxy classes to defer the instantiation of services until they are actually accessed. This prevents the overhead of creating complex object graphs for services that are defined in the container but not required for a specific request execution path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3994ac64-b2f5-4bdb-89ea-4417bbad14e5', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the purpose of ''metadata'' in Next.js?', N'Intern', N'Metadata is used to define page-level information like titles, descriptions, and Open Graph tags for social media. This is essential for improving SEO and controlling how the page looks when shared on platforms like Twitter or Facebook.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
