INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d01fd71-7dfd-4640-ab7b-441b20c39ec0', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS support multi-tenancy at the architectural level?', N'Middle', N'AdonisJS supports multi-tenancy through custom middleware that identifies the tenant from the request context and dynamically switches database connections or filters queries. By leveraging the IoC container, you can inject tenant-specific configurations into your services seamlessly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24272651-152e-4f21-8ed5-441daf3befe1', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Can you use Tailwind with frontend frameworks like React or Vue?', N'Junior', N'Yes, Tailwind integrates perfectly with modern frameworks like React, Vue, and Svelte. Since Tailwind works by scanning your source files for class names, it natively supports component-based architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb908409-8414-4497-bcf2-441dfac9cd37', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are some best practices for handling sensitive data in JavaScript?', N'Senior', N'Handling sensitive data in JavaScript requires careful attention to security practices. Avoid storing sensitive data in client-side storage like localStorage or sessionStorage. Use HTTPS to encrypt data in transit. Implement proper authentication and authorization mechanisms. Sanitize and validate all inputs to prevent injection attacks. Consider using environment variables for sensitive data in server-side code. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the concept of Content Security Policy (CSP) and how it enhances security Content Security Policy (CSP) is a security feature that helps prevent various types of attacks, such as Cross-Site Scripting (XSS) and data injection attacks, by specifying which content sources are trusted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cc3d677-c1b8-4e7d-a589-441f203c65de', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the role of the Zend Engine in the PHP architecture?', N'Middle', N'The Zend Engine acts as the core interpreter for PHP, responsible for parsing source code into opcodes and executing them. It manages memory allocation, object lifecycle, and variables, serving as the bridge between high-level PHP scripts and the underlying system resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'329ab091-64ef-49ae-b376-442094e64313', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the function of the ''Hinted Handoff'' mechanism in Cassandra?', N'Middle', N'Hinted Handoff is a recovery mechanism where a node stores a temporary ''hint'' when a target replica is unreachable during a write operation. Once the target node comes back online, the healthy node delivers the missed write, helping the cluster achieve eventual consistency without immediate manual intervention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e03c1603-5b38-4d7d-a8a6-4420bbad383b', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you isolate a performance regression introduced by a recent deployment without immediate rollback?', N'Senior', N'I would perform an A/B comparison of performance metrics between the new and old versions using canary traffic analysis to identify specific endpoints experiencing degradation. By comparing execution plans, dependency versions, and resource utilization profiles, I can pinpoint if the regression is due to inefficient logic, updated library dependencies, or infrastructure configuration changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36063b7e-ee6d-498c-ac44-4420c19c635c', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you handle schema validation at the input layer in a Flask API to ensure robust data integrity?', N'Senior', N'Schema validation should be handled by a serialization library like Marshmallow or Pydantic, which validates input against defined schemas before the data reaches business logic. Relying on manual dictionary checks is error-prone and leads to inconsistent API behavior and potential security risks like mass assignment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93d84019-6c8a-4513-96ec-442207acfbc5', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the ''internal'' visibility modifier?', N'Junior', N'The ''internal'' modifier restricts the visibility of a class, function, or property to the current module. A module is a set of files compiled together, such as a single Gradle project or a library, providing encapsulation across package boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ec5c251-38c9-46f8-bf7e-4423e33e6976', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do you implement a circuit breaker pattern in a Rails application to handle external service failures?', N'Senior', N'Use a library to wrap calls to external APIs, which monitors failure rates and temporarily stops requests if thresholds are met. This prevents cascading failures and allows your application to fail gracefully rather than exhausting resources waiting for unresponsive services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68e0b8e6-5840-427e-a1ef-4425f24ed99d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why is ''perfect'' code often considered a bad goal in professional engineering?', N'Intern', N'Striving for perfection usually leads to over-engineering and missing deadlines. Engineering is about delivering the most value within given constraints, so ''good enough'' that meets all requirements is often superior to a perfect solution that arrives too late.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
