INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98253796-0eb2-48d9-a506-442c69d1ab91', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does the Active Record Identity Map pattern impact memory usage and data consistency in long-running processes?', N'Senior', N'The Identity Map ensures that only one object instance exists for a specific database row within a single request scope, preventing redundant memory allocation. However, it can lead to stale data if the underlying database state changes, and in long-running processes, it risks memory bloat if not cleared appropriately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94e6d6a9-04b8-493b-a991-443024317a09', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Why is it often discouraged to use a global variable in an R function?', N'Middle', N'Global variables break functional purity, making functions harder to test, document, and reason about because their output depends on external state. Relying on global state can lead to unpredictable behavior and hard-to-track bugs as the application grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
