INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fa9ea42-5049-447b-ac55-443374e1751e', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How do you define a wildcard route in Chi?', N'Fresher', N'Chi supports wildcard routing using the asterisk character in the route path. This matches any remaining part of the URL, which is useful for serving static files or implementing catch-all endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2111eb27-8507-4ac3-8309-4434e3ad1e74', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a primary key in a key-value store?', N'Intern', N'In a key-value store, the primary key is a unique identifier used to retrieve, store, or delete the associated value. It acts as an index that allows the database to locate the data instantly without scanning the entire collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc173589-8e7d-4abf-8bed-44354fdebd2d', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby implement ''Duck Typing'' at the VM level, and what are the performance consequences?', N'Senior', N'Ruby implements duck typing through dynamic method dispatch, where the VM checks for method existence at runtime rather than enforcing type signatures at compile time. While this provides extreme flexibility for polymorphism, it prevents static type optimizations, leading to higher CPU overhead compared to statically typed languages that utilize fixed memory offsets for method calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a72fe29-1235-44a8-972e-4437b8b400d0', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is Redis and how does it store data?', N'Intern', N'Redis is an open-source, in-memory data structure store used as a database, cache, and message broker. Unlike traditional databases that store data on disk, Redis keeps its data entirely in RAM, which allows for extremely fast read and write operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b39a7833-26b9-418f-9863-443a9c877dc8', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why does changing the schema of a large table often cause a ''Table Lock'' in older MySQL versions?', N'Senior', N'Older versions required creating a temporary copy of the entire table and rebuilding all indexes to perform schema changes, which necessitated an exclusive lock. Modern MySQL (via Online DDL) allows most operations to be performed in-place by maintaining an auxiliary log of changes during the rebuild, significantly reducing downtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69a6003b-bab3-4375-b3f6-443dc7377453', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a closure and how does JavaScript implement it internally?', N'Intern', N'A closure is a function that retains a reference to its lexical environment (the scope in which it was defined) even after that outer scope has finished executing. In V8, when a function is created, the engine attaches a hidden [[Environment]] slot pointing to the current scope''s environment record. As long as the inner function is reachable, the garbage collector keeps the outer environment record alive. Practically: closures "close over" variables — not values. They hold a live reference to the variable binding, so mutations to that variable are visible inside the closure. Real-World Use Case: The Redux store implementation (createStore) uses closures to encapsulate currentState, currentReducer, and listeners.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2693b26c-c5b8-4de8-bda2-443eba2947d4', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'When is it appropriate to use Gin''s ''NoRoute'' handler?', N'Middle', N'The NoRoute handler is used to define a fallback function for requests that do not match any registered routes. This allows developers to provide a consistent JSON error response instead of the default 404 plain text page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4af51ed2-382d-4322-aaad-443ef91c7fee', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the difference between synchronous and asynchronous route handlers in Fastify?', N'Intern', N'A synchronous handler returns a value directly, while an asynchronous handler returns a promise that resolves to the response. Fastify handles both natively, but asynchronous handlers are preferred for operations involving I/O to prevent blocking the event loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f46213a9-cfa5-4119-985f-44421bbd25f8', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the difference between POST and GET requests in Gin?', N'Fresher', N'GET requests are used to retrieve data from a server and typically carry parameters in the URL, while POST requests are used to submit data to be processed. Gin provides distinct methods for defining handlers for these specific HTTP verbs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44a24cbd-4c28-405b-b8ec-44429d341102', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are Sass functions and how do they differ from mixins?', N'Junior', N'Functions are used to calculate and return a single value, such as a color manipulation or a math result. Unlike mixins, which output blocks of CSS rules, functions are meant to be used within properties to compute values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fe82def-1147-4157-a77d-4442d6cbb232', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How can you use CSS in SolidJS?', N'Junior', N'SolidJS works with standard CSS files, CSS modules, or CSS-in-JS libraries. Since SolidJS creates real DOM elements, standard web development practices for styling apply directly without framework-specific constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f7c2a50-b294-4cf4-bd6e-44452a75ed21', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide when it is appropriate to use a cache, and what are the risks associated with caching?', N'Senior', N'I use caching for expensive read operations that are not highly sensitive to stale data. The primary risk is cache invalidation and inconsistency, so I implement cache-aside or write-through strategies combined with appropriate TTL settings to maintain data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff4090bb-16aa-4359-87cc-4446987704e3', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why might you use a read-replica in a MySQL deployment?', N'Middle', N'Read-replicas are used to scale read operations by offloading SELECT queries from the primary instance. This improves overall system availability and performance, especially in applications where read traffic significantly exceeds write traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68c13b67-68c4-4e37-a3a7-444702179a68', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Describe the ''Quarkus Extension'' mechanism and its purpose.', N'Senior', N'Extensions are the primary way to integrate third-party libraries and framework features into Quarkus. They contain the build-time logic that allows Quarkus to adapt these libraries to be native-compatible, perform configuration parsing, and optimize resource usage for the final application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c395d133-3d95-425b-9494-4449cefa6914', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Explain the concept of ''Universal Rendering'' in Nuxt and why it is superior to traditional SPAs for SEO.', N'Senior', N'Universal rendering provides fully rendered HTML to the browser on the initial request, which crawlers can parse immediately. Traditional SPAs deliver an empty root div, requiring search engine bots to execute JavaScript, which is unreliable and often negatively impacts indexing performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bb44931-6c15-4a74-8550-444b64fab856', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is a 404 error in Echo?', N'Fresher', N'A 404 error occurs when a client requests a URL path that does not match any defined routes in the Echo application. Echo automatically returns a ''Not Found'' response if no route is found.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
