INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9d501be-44d6-400b-9fb8-446385001700', N'954a0331-deff-4399-b588-96f39fec001d', N'What is HttpClient and its benefits?', N'Intern', N'Most of the Front-end applications communicate with backend services over HTTP protocol using either XMLHttpRequest interface or the fetch() API. Angular provides a simplified client HTTP API known as HttpClient which is based on top of XMLHttpRequest interface. This client is available from @angular/common/http package. You can import in your root module as below: The major advantages of HttpClient can be listed as below, 1. Contains testability features 2. Provides typed request and response objects 3. Intercept request and response 4. Supports Observable APIs 5. Supports streamlined error handling', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f344bf7-8176-48f7-93e7-44654573fc0c', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is code splitting?', N'Intern', N'Code splitting is a feature that allows you to split your code into various bundles which can then be loaded on demand. This improves performance by reducing the initial load time, as the user only downloads the code necessary for the current view.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0de6c7d5-a0e4-4adf-8997-4466896e3b68', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why is it considered a security anti-pattern to use default Express error handlers in a production environment?', N'Senior', N'Default error handlers often output stack traces and internal application state to the client. This information can reveal sensitive infrastructure details, file paths, and library versions, providing attackers with a roadmap for reconnaissance and exploit development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07b5acae-af68-4bde-8cde-4469f66f9151', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is code splitting in the context of Webpack?', N'Intern', N'Code splitting is a feature that allows you to split your code into various bundles which can then be loaded on demand or in parallel. This is useful for improving page load performance by only sending the necessary code to the user at a specific time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e5d4529-8810-4fc4-925f-446acaf60406', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What architectural challenges arise when scaling read-heavy MySQL workloads?', N'Senior', N'Scaling read-heavy workloads requires implementing read replicas, which introduces eventual consistency challenges and potential replication lag. Proper load balancing and application-side logic are required to route queries appropriately and handle the latency between the primary and replicas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a45ec43c-462c-4239-a207-446d462023b3', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How do you add a new capability to a Quarkus project?', N'Fresher', N'You add a new capability by adding the corresponding Quarkus extension to your project''s build file, such as Maven or Gradle. Once added, the extension automatically configures the necessary libraries and provides the required integration code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f653677a-a6ac-45a0-8e68-446f88b216bd', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is an ''if'' block in Svelte?', N'Fresher', N'An if block is a conditional rendering directive that allows you to show or hide parts of the UI based on a boolean condition. If the condition is true, Svelte renders the content inside the block; otherwise, it removes or hides it from the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce2f498e-5924-44bc-9388-44709c4362b5', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''infer'' keyword used for in TypeScript?', N'Middle', N'The ''infer'' keyword is used within conditional types to introduce a type variable that can be inferred from a part of another type. It is commonly used to extract return types from functions or element types from arrays dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0283b7c4-14cb-45b7-af6b-447133cf66ae', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the difference between ''extends'' in interfaces and intersection types.', N'Middle', N'The ''extends'' keyword is used to create a new interface that inherits members from one or more existing interfaces. Intersection types use the ampersand operator to combine multiple types into one, which is more useful for composing types on the fly without declaring a new interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb512716-66c3-4d6f-8f11-44733dda557a', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does structural typing impact the way TypeScript handles compatibility between objects?', N'Senior', N'TypeScript uses structural typing, meaning type compatibility is based on the shape of the object rather than its explicit declaration. As long as a target type contains all the required members of a source type, it is considered compatible, which promotes flexibility but can lead to unexpected behavior if strictness is not enforced.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
