INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86ec1a05-9aac-422d-98c0-4474e1132064', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What are the trade-offs of using a service mesh in a containerized environment?', N'Senior', N'A service mesh provides powerful out-of-the-box features like mTLS, traffic splitting, and observability, significantly reducing boilerplate code. However, it introduces operational complexity, increased latency, and a steeper learning curve, so I only adopt it when the service count is high enough that manual configuration management becomes unsustainable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'911e71af-a565-4316-bf26-44758ed2d1e4', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you handle user inputs and form submissions in Vue.js?', N'Fresher', N'Vue.js simplifies user interactions and form handling through its reactive two-way data binding, utility directives, and validation libraries. Let''s explore these features further. Two-Way Data Binding Vue.js''s two-way data binding ensures that changes in input fields are reflected in corresponding data properties and vice versa. For two-way binding, use the v-model directive: In this example, name is the corresponding data property, and its value is updated as the user types in the input field. Handling Event Vue.js provides the v-on directive to handle user-triggered events, like click, input, or submit. For example: Here, the handleClick method is called when the button is clicked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18b748f8-2809-40f3-9dd5-4477b082d4b3', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Can you use React Hooks with Preact, and how is this achieved?', N'Middle', N'Yes, Preact includes a ''hooks'' package that implements the standard React hooks API. This allows developers to use functional components, state, and effects just as they would in React, maintaining a familiar development workflow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8924796-7f45-420d-aeb6-447a02c7c4b4', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are the trade-offs of using ''cross-origin'' requests in a SvelteKit application?', N'Senior', N'Handling cross-origin requests requires careful management of CORS headers and cookie security. While SvelteKit provides tools to handle these via the ''handle'' hook, it introduces complexities regarding CSRF protection and session synchronization that are not present in same-origin setups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
