INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ebefcd5-9591-4a11-bec7-447dde0df398', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Describe the security and architectural risks associated with Ruby''s ''eval'' family of methods.', N'Senior', N'Methods like ''eval'' execute arbitrary strings as code, creating massive injection vulnerabilities if user input is not strictly sanitized. Architecturally, they hinder static analysis, block common compiler optimizations, and make it nearly impossible to trace the origin of code execution during debugging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17524abd-b179-414a-a88a-447f54358bab', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'When should you choose ''Messenger'' over a synchronous web-hook or REST API call?', N'Senior', N'Messenger should be used when an operation is non-critical to the immediate user response or requires high reliability through retries and failure handling. It is preferred over synchronous calls when you need to decouple services, handle load spikes through queuing, or perform background processing to keep the user interface responsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62a6e708-c50c-4886-b8ab-447f7e567b04', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How do you configure a bean in Spring?', N'Fresher', N'In Spring, a bean represents an object that''s managed by the Spring IoC (Inversion of Control) Container. Developers can configure beans using annotations, XML, or Java code. Key Bean Configuration Elements - Class: Identifies the bean''s type. - ID/Name: Unique identifier for the bean within the IoC container. - Scope: Describes the bean''s lifecycle. - Dependencies: Bean dependencies and corresponding wiring mode. - Additional Settings: Custom properties and configurations. Annotation-Based Bean Configuration Use the @Component family of annotations combined with @Autowired. - @Component: Indicates the class as a Spring-managed component. - @Repository: Specialized for data access. - @Service: For business services. - @Controller: Designed for MVC web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2887d2d-1a9f-4920-ba0a-44802cf1b1b6', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro''s ''Image'' component improve performance over native HTML image tags?', N'Senior', N'The Astro Image component performs build-time optimization, including resizing, format conversion (e.g., to WebP or AVIF), and adding appropriate srcset attributes. This automates the delivery of correctly sized, modern-format images, reducing bandwidth and improving Core Web Vitals without manual effort.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ce7e924-9596-4902-9214-4481fcd72b4f', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi ensure compatibility with standard Go HTTP handlers?', N'Middle', N'Chi is built specifically to be fully compatible with the standard net/http.Handler interface, meaning any handler written for the standard library can be used with Chi without modifications, allowing for easy migration or interoperability with third-party middleware that adheres to standard patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81343386-a122-4a44-957e-4482c81ec4ea', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What informs the decision to use a document store versus a key-value store?', N'Junior', N'A document store is appropriate when you need to query or index data based on its internal fields. A key-value store is ideal for simple, high-performance lookups where the data structure is opaque to the database and you only need to retrieve values by a unique identifier.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c12505cb-423c-48ac-a91e-4482e012ffc0', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What’s the difference between NestJS and Angular?', N'Fresher', N'Angular is a framework for building client-side applications and It provides a way to organize your frontend code using components, modules, services, etc. while NestJS is a framework for building server-side applications. NestJS is built on top of TypeScript and Express, and it aims to provide a more robust and scalable architecture for enterprise-level applications. However It''s heavily inspired by Angular and shares similar concepts like modules, decorators, and dependency injection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c813eb12-203c-4be4-9b36-44841aa54a13', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How can you implement graceful shutdown in an Actix-web server?', N'Middle', N'Graceful shutdown is handled by monitoring system signals like SIGTERM or SIGINT. Upon receiving these, the server stops accepting new connections while allowing existing requests to complete within a defined timeout period before closing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
