INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'689c2bc2-14de-43d6-b5ab-448a26490081', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the Isolation property?', N'Junior', N'Isolation ensures that concurrent execution of transactions leaves the database in the same state that would be obtained if the transactions were executed sequentially. It prevents transactions from interfering with each other.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51516ad4-0221-4538-b26c-448b0482dc8b', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why might one choose Redis over Memcached for caching purposes?', N'Senior', N'Redis offers a richer set of data structures like hashes, lists, and sets, providing more flexibility for complex caching logic compared to Memcached''s simple key-value model. Furthermore, Redis supports persistence and high availability features that are not natively built into Memcached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2993ca2-4e5d-4e8b-9976-4490e96da00e', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the difference between a global scope and a module scope for filters or guards?', N'Middle', N'Module-scoped guards or filters are restricted to a specific module and its controllers, providing fine-grained control. Global-scoped components apply to every route in the application, which is useful for cross-cutting concerns but requires careful management to avoid unintended side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'630161b1-8fe7-4b2f-bb29-449148a2b838', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the significance of the PSR-7/PSR-17 standards within the Symfony ecosystem?', N'Senior', N'These standards provide a common interface for HTTP messages, allowing components to remain decoupled from any specific framework implementation. While Symfony has its own robust HttpFoundation components, supporting PSR interfaces ensures better interoperability with the wider PHP community''s middleware and libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab152a36-afbc-4dda-8c0f-449353b33cc4', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Describe the impact of ''Head-of-Line Blocking'' in HTTP/1.1 and how HTTP/2 addresses it.', N'Senior', N'HTTP/1.1 allows only one request per TCP connection at a time, causing slow requests to block subsequent ones. HTTP/2 uses multiplexing over a single connection to send multiple requests and responses concurrently, significantly improving performance and scalability for resource-heavy web pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0ac3af0-7598-4469-af95-449564b6e9d1', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the ''data down, actions up'' pattern?', N'Junior', N'This pattern ensures that data flows from parent components to children as arguments, while children communicate changes back to parents by triggering actions. This makes the data flow predictable and easier to debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'369c9627-094e-4a7d-aafe-44962cd222dd', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does ASP.NET Core ensure thread safety with dependency injection?', N'Middle', N'ASP.NET Core manages object lifetimes based on the registered scope. Developers are responsible for ensuring that injected services are stateless or thread-safe, especially when using Singleton services, as they are accessed concurrently by multiple requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20cf6fef-a7b0-4200-ac89-44964ad070a5', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket use Rust''s type system to handle web requests?', N'Junior', N'Rocket uses type-safe request routing where the types of function arguments determine how a request is parsed. If a request does not match the expected types defined in the handler, Rocket automatically rejects it before the handler code even runs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bce67a6c-4cde-4bbb-acf0-4498457f532c', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the role of the ''pseudo-class'' vs ''pseudo-element''?', N'Middle', N'A pseudo-class targets an element based on its state or position, such as '':hover'' or '':first-child''. A pseudo-element targets a specific part of an element that isn''t explicitly in the DOM, such as ''::before'' or ''::after'', to insert or style specific content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12ab4b4d-9854-41d6-bc11-449a1fd64a25', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the purpose of the ''slots'' attribute in a class, and what are the trade-offs regarding memory and flexibility?', N'Senior', N'Using __slots__ prevents the creation of a dynamic __dict__ for each instance, significantly reducing memory usage for classes with many objects. The trade-off is the loss of the ability to add arbitrary attributes to instances at runtime. It is a powerful tool for memory optimization in high-performance applications but limits meta-programming flexibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44566a4e-6def-4054-8c4d-449ab568ac93', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Why is idempotency important in API design, especially for POST requests?', N'Middle', N'Idempotency ensures that performing the same operation multiple times has the same effect as performing it once. This is critical for network reliability; if a client receives a timeout, they can safely retry the request without creating duplicate records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35e7fba0-152d-4543-a02d-449b1db95d0c', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the advantages of using JSONB over standard JSON in PostgreSQL?', N'Middle', N'JSONB stores data in a decomposed binary format, which is slower to input but much faster to process and query. It also supports indexing, allowing for efficient searches within the JSON document structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
