INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2094bca-a401-4f5c-9283-44acbde6ad0c', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Why is denormalization often used in large-scale read-heavy systems?', N'Middle', N'Denormalization reduces the need for complex and costly JOIN operations by storing redundant data in a single table. This improves read performance at the expense of increased storage usage and the need to manage data consistency across redundant fields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
