INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4c04c7b-34ea-4630-818a-44b253d72fc2', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What does ''fully managed'' mean in the context of DynamoDB?', N'Fresher', N'Fully managed means that AWS handles administrative tasks like hardware provisioning, software patching, and data replication. As a user, you do not need to manage the underlying infrastructure or servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
