INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9897e9f9-225e-47bb-8d4f-44ba4198c55e', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What are the advantages of Vite''s plugin system compared to Webpack''s loader architecture?', N'Senior', N'Vite''s plugin system is built on top of Rollup''s hook-based architecture, which is generally easier to reason about and provides a more unified API for build-time transformations. Unlike Webpack''s complex loader chains, Vite plugins allow for more predictable execution order and better integration between dev and build processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65423bef-b8c7-49e8-9120-44beddc9a92e', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Why is it difficult to perform ACID transactions across sharded databases?', N'Senior', N'Performing transactions across shards requires two-phase commit (2PC) or similar coordination protocols, which introduce latency and increase the risk of deadlocks. The ''atomic'' and ''isolated'' properties become increasingly difficult to guarantee as the number of involved shards grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1eadb69c-0785-4e2b-b65c-44bfa574bddc', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you perform rolling updates in a microservices environment without downtime?', N'Senior', N'Use a deployment strategy such as Blue-Green or Canary releases orchestrated by the container platform. By gradually shifting traffic from the old version to the new one while monitoring health metrics, you ensure stability and allow for immediate rollback if issues arise.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
