INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b38392f4-80c5-4a67-8ee8-44c9d3af773c', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why is it helpful to document the assumptions made during an estimation?', N'Fresher', N'Documentation provides a trail of the logic used at the time. If the project requirements change or the estimate turns out to be wrong, we can look back at the assumptions to see if the error was due to faulty logic or simply a change in external circumstances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3db900a6-829e-441f-b423-44cdee70a9d3', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle the ''Hydration'' process, and what are the common pitfalls?', N'Senior', N'Remix hydrates the static server-rendered HTML into an interactive SPA by attaching event listeners and initializing React state. A common pitfall is ''hydration mismatch,'' which occurs when server-rendered output differs from the client-side render; this is usually caused by relying on browser-only APIs like window or localStorage during the initial render pass.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa184066-59fa-4a6e-9e8a-44ceb568541f', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the impact of strict typing in modern PHP on application stability and performance?', N'Senior', N'Strict typing allows the engine to perform better optimizations by guaranteeing data types at the boundaries, reducing the need for runtime type coercion. From an architectural perspective, it improves code robustness by catching type-related bugs during development and making the contract of interfaces explicit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38376676-c438-4643-a548-44d0e8623df9', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the significance of the ''State'' pattern in Actix-web?', N'Middle', N'The state pattern allows developers to share mutable or immutable data across the entire application. By registering data in the App instance, it becomes accessible to all handlers, enabling centralized management of external resources like caches or connection pools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a784cb29-9aad-4165-899a-44d1b9958f4d', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Why is ''Immutability'' a core tenet of Scala''s design?', N'Senior', N'Immutability eliminates side effects caused by shared mutable state, which is the primary source of bugs in multi-threaded environments. By favoring immutable data structures, Scala simplifies reasoning about concurrent code and allows for safer parallelization. This paradigm shift aligns with the needs of modern distributed systems where predictability and thread safety are critical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc66e3e4-1121-4a07-89f1-44d2abfea007', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does the R interpreter differentiate between an object name and its value during evaluation?', N'Senior', N'R uses a symbol-to-value lookup mechanism where names are treated as pointers to memory locations containing the actual data. The interpreter evaluates an object by resolving its name within the active environment chain to retrieve the associated value, unless the evaluation context specifically suppresses this step, such as in quote or substitute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f12b178b-4470-4425-84bc-44d2e7e99257', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of the ''static'' keyword for local variables?', N'Junior', N'When applied to a local variable, ''static'' ensures that the variable is initialized only once and retains its value between multiple function calls. It remains in memory for the lifetime of the entire program rather than being destroyed when the function scope ends.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40e66fa0-0199-42f3-bf00-44d309ebbc88', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the impact of Echo''s middleware on request latency?', N'Middle', N'Each middleware adds a small amount of overhead to the request path due to the function call stack and processing logic. While negligible for most use cases, developers should be mindful of heavy computations within middleware, as they directly increase the response time for every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59d316bf-aae5-4154-8737-44d42847209d', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro optimize assets like images?', N'Middle', N'Astro includes a built-in image optimization service that automatically handles resizing, cropping, and format conversion. By leveraging modern image formats like WebP or AVIF, it ensures that images are served at the appropriate size for the user''s device, reducing total page weight.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c467fb17-62b6-4bc0-8dc8-44d4527dbc9d', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik''s architecture handle cache invalidation for lazy-loaded chunks?', N'Senior', N'Since each Qwik component is split into unique, content-hashed files, cache invalidation is handled naturally by the browser''s caching mechanism. If a component''s logic changes, its corresponding chunk''s hash changes, forcing the browser to fetch the updated version without impacting the rest of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
