INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ff2a497-b4a6-4266-9381-44f2ea802795', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the trade-off between using a monolithic repo versus a poly-repo structure for a large engineering organization?', N'Senior', N'A monorepo simplifies dependency management, atomic commits, and cross-project refactoring but requires sophisticated tooling to prevent build times from becoming prohibitive. Poly-repos provide team autonomy and independent deployment cycles but make cross-service consistency and shared library management significantly more difficult.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f37a1bdc-cc8a-4d46-a231-44f3c1fb7dc9', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the difference between static and dynamic dispatch in Rust trait objects?', N'Senior', N'Static dispatch is resolved at compile time through monomorphization, allowing the compiler to perform aggressive inlining. Dynamic dispatch uses trait objects with vtables, enabling heterogeneous collections and polymorphic behavior at the cost of a runtime pointer indirection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0272ce5f-16d7-4a58-aa63-44f3cb1a7f91', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How do you ensure secure data transit in a hybrid cloud environment?', N'Senior', N'Data in transit should be protected by TLS 1.3 for application-level traffic and IPsec or MACsec for network-level tunnels between on-premises data centers and cloud providers. This creates a secure, encrypted overlay that protects traffic from interception across public or shared network segments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4231b7d8-969e-43b0-a742-44f4cccc23c1', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What are CSS pseudo-elements?', N'Junior', N'Pseudo-elements allow you to style specific parts of an element, such as the first letter or line of a paragraph. Common examples include ''::before'' and ''::after'', which let you insert decorative content without adding extra HTML tags.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65690e15-8efe-4f1c-901f-44f58698e99b', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the Ember Inspector?', N'Intern', N'The Ember Inspector is a browser extension tool used to debug Ember applications. It allows developers to view the application''s routes, models, components, and performance metrics in real-time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccc498dc-0fd2-4492-82fd-44f6dcff9c80', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Describe the difference between ''Eventual Consistency'' and ''Strong Consistency'' in the context of the CAP theorem.', N'Senior', N'Strong consistency guarantees that any read returns the most recent write, requiring synchronous coordination between nodes. Eventual consistency prioritizes availability and performance by allowing replicas to diverge temporarily, with the system guaranteeing convergence over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc312c96-e99e-4fd9-a738-44f8ae4909dd', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Compare Write-Through and Write-Back caching strategies in terms of data consistency and latency.', N'Senior', N'Write-Through ensures strong consistency by writing to the cache and the backing store simultaneously, which increases write latency. Write-Back improves write performance by updating only the cache initially, but introduces a risk of data loss if the cache node fails before the write propagates to the persistent store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01310500-84ff-4ebc-a07b-44fa1901bce2', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is code splitting in a React application?', N'Intern', N'Code splitting in a React application is a technique used to improve performance by splitting the code into smaller chunks that can be loaded on demand. This helps in reducing the initial load time of the application. You can achieve code splitting using dynamic import() statements or React''s React.lazy and Suspense. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60e1a491-db0a-4b47-ab7a-44fbf79308bb', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the purpose of the ''AnyVal'' class in Scala?', N'Middle', N'AnyVal is the root class for value types, which are represented as primitives on the JVM whenever possible. This helps reduce memory overhead and improves performance by avoiding unnecessary object boxing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd602e1ea-3885-4ef3-8898-44fd0cddb422', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are getters and setters?', N'Junior', N'Getters and setters are special methods that provide read and write access to an object''s properties. They allow you to encapsulate the internal state of a class and perform validation or logic whenever a property is accessed or updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'945ad59e-d476-49da-b81a-44ff055a4561', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the concept of RAII and its role in C++ memory management.', N'Middle', N'RAII stands for Resource Acquisition Is Initialization, where resource management is tied to object lifetime. When an object goes out of scope, its destructor is automatically called, ensuring resources like memory or file handles are released without needing explicit cleanup calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f21389c-1543-4d4c-a1b8-45006843f14b', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle route versioning?', N'Middle', N'Fastify supports route versioning natively through the ''constraints'' feature, allowing the server to route requests based on headers like Accept-Version. This enables cleaner API evolution without needing to prefix routes manually for every version change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f63e7251-2121-46f3-a968-45010ef41d37', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s ''Records'' feature affect data modeling?', N'Middle', N'Records provide a way to group multiple values into a single object without needing to define a formal class. They improve performance and conciseness when returning multiple values from a function or passing around temporary data structures, as they are immutable and have value-based equality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baa4b505-c92b-4438-be3c-4503a9e1787f', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide which task to prioritize when you have multiple deadlines approaching?', N'Intern', N'I prioritize tasks based on their urgency and impact on the overall project goals. I would list all pending items, evaluate their dependencies, and communicate with stakeholders to confirm which deliverables are most critical to business success.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d0dde6c-55aa-4e0a-b33a-4507e7c6b57a', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why does Remix prefer server-side data fetching?', N'Junior', N'Server-side fetching allows the server to prepare the complete HTML page before sending it to the client. This reduces the time to first paint and prevents the user from seeing a blank screen while the client-side JavaScript processes data requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26402503-c3f8-4a12-aad3-4509959ca294', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the implications of ''stale reads'' in a system with asynchronous replication?', N'Senior', N'Stale reads occur when a client reads from a replica that has not yet received the most recent update from the primary node. This is a common side effect of prioritizing write availability and low latency, requiring developers to design applications that can tolerate or handle outdated data gracefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f2e2c3c-e964-4200-ad56-4509b549610a', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does the Scala compiler handle the translation of higher-kinded types into JVM bytecode?', N'Senior', N'The Scala compiler uses a technique called type erasure along with the generation of synthetic bridge methods and wrapper classes. Since the JVM does not natively support higher-kinded types, the compiler encapsulates type constructor information within the metadata of the generated class files, which the Scala reflection API and compiler can later interpret.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
