INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11bd4201-fbf6-44ed-adde-450d5371b00e', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why does Qwik favor ''server-first'' rendering?', N'Junior', N'Server-first rendering allows the application to send fully functional HTML to the browser immediately. This improves the Largest Contentful Paint metric and ensures that the user sees content before any JavaScript is loaded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'765ba7f6-0946-442e-a6ce-450f14694f9f', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why should you always initialize pointers in C?', N'Junior', N'An uninitialized pointer contains a random memory address, known as a wild pointer. Attempting to dereference such a pointer can lead to undefined behavior, including program crashes or data corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1f7eb43-e3d8-472b-acb6-450fa07002c6', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why is it recommended to keep handlers small in Axum?', N'Middle', N'Small handlers are easier to test, maintain, and reason about in an asynchronous environment. By offloading business logic to dedicated service layers, the handlers remain responsible only for request parsing and response formatting, which simplifies debugging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a3575b6-b782-4ff2-9b2c-450ff478a5e0', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the benefits of using a decorator or presenter pattern over adding helper methods to ActiveRecord models?', N'Senior', N'Decorators separate view-specific logic from the data model, preventing the model from becoming cluttered with formatting concerns. This improves modularity and makes the view layer easier to unit test without needing to mock complex database objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53576ac0-7909-4532-b538-4510e260b38b', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit optimize rendering performance?', N'Intern', N'Lit optimizes performance by only updating the specific parts of the DOM that have changed rather than re-rendering the entire component tree. It uses efficient template processing to minimize DOM interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7adb2172-9f85-45c1-b382-45115c2466d0', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do you communicate CSS technical debt to non-technical stakeholders?', N'Fresher', N'CSS debt is invisible to stakeholders until it causes a visible problem. Your job is to make it tangible in terms of speed, risk, and cost. Strategies: 1. Translate to business impact Don''t say: *"Our specificity graph looks like a skyscraper and we have 47 uses of !important."* Say: *"Updating the button style currently takes half a day because conflicting rules override each other unpredictably. Cleaning up the stylesheet for the checkout flow would reduce that to 15 minutes."* 2. Maintain a visible CSS debt backlog Track debt items in the same issue tracker as features. Tag them with impact (speed, reliability, brand consistency) and estimated effort. This makes it easy to prioritize alongside product work. 3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03494a90-c937-478c-8814-45141a4b1572', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does ''Suspense'' work in SolidJS?', N'Middle', N'Suspense allows you to define a fallback UI while waiting for asynchronous resources to resolve. It tracks the reactive dependencies of its children; if any resource is pending, it displays the fallback, providing a smooth user experience for data-heavy applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a82b342-127d-47eb-a849-45142745340c', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the primary difference between ''source'' and ''load'' in R?', N'Middle', N'Source executes an R script line by line, evaluating expressions and creating objects in the current environment. Load restores saved R objects from a binary file into the current workspace, which is typically faster but less flexible than parsing human-readable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ff0aa2e-fe2d-4538-953f-45175b103a21', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Discuss the memory overhead of Promises compared to callbacks and how it affects garbage collection.', N'Senior', N'Promises introduce object allocation overhead for each link in the chain, which can put pressure on the young generation heap compared to direct callbacks. While modern engines have optimized promise allocation, high-frequency asynchronous operations still benefit from minimizing unnecessary promise creation to reduce GC pause frequency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15b397db-b1cc-45bc-b033-45190a4e4662', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why is it generally discouraged to use SELECT * in production?', N'Junior', N'Using SELECT * retrieves all columns from a table, which can increase network traffic and memory usage unnecessarily. It can also break application code if the table schema changes, such as adding a column that conflicts with the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4df9973a-ed7e-4686-9302-4519cd422b10', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the Go runtime handle stack management compared to languages like Java or C++?', N'Senior', N'Go utilizes segmented, resizable stacks that start small (typically 2KB) and grow or shrink dynamically as needed. Unlike traditional thread-per-request models that allocate a large, fixed-size stack for each thread, Go''s approach allows for high concurrency with millions of goroutines without exhausting memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47714b7a-5190-471b-b0bf-451a71649038', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Explain the concept of ''progressive enhancement'' in the context of using Alpine.js.', N'Middle', N'Progressive enhancement involves building a baseline experience that works without JavaScript, then layering interactivity on top. Alpine.js fits this model perfectly because it allows developers to sprinkle dynamic behavior directly onto existing HTML elements without needing to rewrite the entire UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6fee175-3b6a-48e0-94cc-451c220e39fe', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of common module?', N'Intern', N'The commonly-needed services, pipes, and directives provided by @angular/common module. Apart from these HttpClientModule is available under @angular/common/http.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d8eaae1-4909-4e86-bae6-451df9913122', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix differ from a traditional Client-Side Rendering (CSR) framework?', N'Fresher', N'Traditional CSR frameworks load a blank page and then fetch data to render content in the browser. Remix performs data loading on the server before sending the page to the client, which results in faster initial loading times and better search engine optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'679a7003-cafb-4344-961b-451f3e2c2706', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is a React component?', N'Intern', N'React Component Definition (2026 Standard) A React component is the fundamental building block of modern React applications, encapsulating UI logic and structure. In the current ecosystem (React 19+), components are defined as function components. While class components remain technically supported for legacy compatibility, they are considered deprecated architectural patterns in favor of functional paradigms. Function Components vs. Legacy Class Components * Function Components: The industry standard. These are JavaScript functions that accept props as an argument and return UI elements. They leverage Hooks to manage state, context, and side effects. * Class Components: Legacy structures that use ES6 classes extending React.Component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca884225-6e85-4198-83b0-451fb3318462', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What does the ''virtual'' keyword do in inheritance?', N'Fresher', N'The virtual keyword is used in a base class to enable dynamic dispatch, allowing a derived class to override a base class function. This ensures that the correct version of the function is called at runtime based on the actual type of the object, rather than the pointer type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16fd6639-6e85-4448-a186-452014285229', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is Django?', N'Intern', N'Django is a high-level Python web framework that encourages rapid development and clean, pragmatic design. It follows the model-view-template architectural pattern and includes many built-in features to help developers build secure and scalable websites quickly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'706858a8-f15c-481f-aa1b-4524ef7c0fb9', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the advantage of using ''APIRouter'' in a large FastAPI application?', N'Middle', N'APIRouter allows developers to split a large application into smaller, manageable files or modules grouped by functionality. This improves code organization, enables team collaboration by separating concerns, and makes the codebase easier to navigate and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3904d1a8-f4ae-472c-926b-45294f22cd57', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of clustering columns?', N'Fresher', N'Clustering columns are used to sort data within a partition. They allow for efficient range queries and retrieval of data in a specific order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56d80e01-e43b-45a0-ab8a-452a9d65aeb9', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB handle ''Read Concern: linearizable''?', N'Senior', N'Linearizable read concern ensures that reads return data that reflects all successful writes that completed prior to the start of the read operation. It is the strongest level of consistency but incurs significant latency because it requires communication with a majority of replica set nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79d4e09a-8a64-436a-ad9b-452eb7bcfe06', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What happens during the build process of a SvelteKit app?', N'Intern', N'During the build, SvelteKit compiles your components into highly optimized JavaScript and CSS. It also identifies your routes and generates the necessary assets for deployment based on the selected adapter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e87e754-53fc-4da5-acf1-45303972dc14', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What happens if you do not include a WHERE clause in an UPDATE statement?', N'Junior', N'If the WHERE clause is omitted, the UPDATE statement will apply the changes to every single row in the table. This is a common and dangerous mistake that can lead to unintended data modification.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
