INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0effd5b1-6d68-4484-b13a-4530feaa8e3e', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Is Astro suitable for complex web applications?', N'Fresher', N'Astro is best suited for content-heavy websites like blogs, marketing sites, and documentation. While it can handle some interactivity, it is not primarily designed for highly complex, state-heavy web applications compared to traditional SPA frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce66b87c-de6e-43cc-b65e-4532972fcae9', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Explain the architectural implications of using Fasthttp as the underlying engine for Fiber.', N'Senior', N'Fasthttp provides a non-standard HTTP implementation that prioritizes speed over strict compliance with the net/http interface. While it delivers excellent performance, it necessitates using Fiber-specific abstractions, which can limit portability to other Go frameworks or standard library middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7de98f0b-7b8c-4c75-993c-4533c46fb8a4', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is AdonisJS and how does it differ from other Node.js frameworks?', N'Fresher', N'AdonisJS is a full-stack web framework for Node.js that follows the MVC pattern. Unlike lightweight frameworks like Express, AdonisJS is opinionated and provides a complete ecosystem of first-party tools, including an ORM, authentication, and validation, out of the box.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3163291-974b-4469-927b-45348e87c396', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why is it often recommended to exclude ''node_modules'' in loaders?', N'Middle', N'Excluding node_modules prevents Webpack from wasting time and resources processing third-party libraries that are already pre-compiled. This significantly speeds up the build process during development and production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa496d97-9553-48f7-bcf0-4534c099cbda', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Why is it important to consider reflection when building Quarkus native images?', N'Middle', N'GraalVM native compilation uses static analysis to determine which code is reachable. If an application uses reflection to access classes or methods, those must be explicitly registered so the compiler knows they are required at runtime; otherwise, they may be stripped away.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7356901-8a1d-4680-b9c9-453793c44580', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the ''Dispatch Strategy'' Swift uses for extensions compared to class methods.', N'Senior', N'Methods defined in a class extension are statically dispatched, meaning they cannot be overridden by subclasses, unlike methods defined in the original class body. This distinction is critical for understanding the behavior of polymorphic overrides and ensuring that the expected code path is executed at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e785311-bf87-43e9-9cdb-453834830f6e', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of the ''body-parser'' functionality in Express?', N'Intern', N'The body-parser functionality is used to parse incoming request bodies in a middleware before your handlers. It allows the server to easily access data submitted in formats like JSON or URL-encoded strings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b89e48ee-bb5e-45df-a4ed-4538c6cde27c', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the different types of joins in SQL?', N'Fresher', N'Common joins include INNER JOIN, which returns rows with matches in both tables; LEFT JOIN, which returns all rows from the left table and matched rows from the right; and RIGHT JOIN, which returns all rows from the right table and matched rows from the left.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cb97bcf-b070-492e-817a-453a873fb66c', N'954a0331-deff-4399-b588-96f39fec001d', N'How can you read full response?', N'Fresher', N'The response body doesn''t or may not return full response data because sometimes servers also return special headers or status code, which are important for the application workflow. In order to get the full response, you should use observe option from HttpClient: Now HttpClient.get() method returns an Observable of typed HttpResponse rather than just the JSON data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ec41dd5-2eae-4289-b3ab-453c2057c156', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you ensure data integrity in a distributed system where multiple services might update the same record?', N'Middle', N'I implement distributed locking mechanisms or use optimistic concurrency control with versioning to prevent race conditions. If strong consistency is critical, I might favor a centralized coordinator or a state machine approach. If eventual consistency is acceptable, I rely on idempotent operations and conflict resolution logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be3701f0-74c0-4d5d-9680-453d5b540153', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI manage the automatic generation of OpenAPI documentation, and what is its impact on API development lifecycle?', N'Senior', N'FastAPI introspects the route signatures and Pydantic models to automatically generate OpenAPI-compliant JSON schemas. This eliminates the need for manual API documentation maintenance and enables powerful tools like Swagger UI for interactive testing and automated SDK generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d212c13-eed7-47e9-aa48-453d74c4d963', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is indexing in MongoDB?', N'Intern', N'Indexing is a feature that allows the database to locate data without scanning every document in a collection. Indexes store a small portion of the collection''s data set in a form that is easy to traverse, significantly improving read performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a993e1c5-094c-4637-8cc1-453f1e09f8c0', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do you update the state of a parent component from a child component?', N'Fresher', N'Modernizing React State Synchronization (2026 Standards) React enforces unidirectional data flow, where data descends the tree via props. Updating Parent state from a Child component is fundamentally achieved via Lifting State Up, leveraging callbacks or dependency injection. Primary Methods 1. Props Callback (Standard Pattern): The parent passes a memoized handler function (e.g., useCallback) as a prop. The child invokes this function to trigger a state update in the parent. 2. Context API (via State-Reducer Pattern): Use createContext coupled with useReducer to provide a state dispatcher. This avoids "prop drilling" in deep component trees and is the preferred 2026 standard for intermediate-scale state sharing. Advanced Patterns (2026 Context) 1.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49bf938d-f7ce-4047-ae43-453fed300b85', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between an abstract class and an interface?', N'Fresher', N'An abstract class can provide some implementation and can have fields, while an interface cannot contain any implementation or fields. A class can inherit from only one abstract class but can implement multiple interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee407343-291e-4143-ab8f-45438dcf75a9', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the fundamental data model used by Amazon DynamoDB?', N'Fresher', N'DynamoDB is a NoSQL database that uses a key-value and document data model. It stores data in tables consisting of items, which are collections of attributes, allowing for flexible schema design where different items can have different structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37b597ce-06c3-4e4e-a113-454402435185', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut''s ''Validation'' module work at compile-time?', N'Senior', N'Micronaut uses JSR-303 (Bean Validation) but implements the verification logic through compile-time transformation. This ensures that objects are validated before they reach the business logic layer, avoiding the overhead of runtime reflection-based validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55fc9e0d-d552-4507-b593-4544090c4819', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle static files?', N'Intern', N'Echo provides built-in methods to serve static files like images, CSS, and JavaScript from a specified directory. This allows the application to function as a simple web server for frontend assets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8bdc1db-2502-43e7-9392-4547c618fe48', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How can you leverage Litestar''s ''After Response'' hooks for non-blocking side effects?', N'Senior', N'These hooks execute after the response has been sent to the client, making them ideal for logging, analytics, or triggering asynchronous background tasks. Because they run after the response is finalized, they do not add to the latency experienced by the end-user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bb5b20b-0c0e-44a8-9807-45489db6e658', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the primary advantage of Fastify over Express?', N'Fresher', N'The primary advantage of Fastify is its significantly higher performance and lower overhead due to its efficient routing system and schema-based validation. While Express is minimalist and flexible, Fastify is designed specifically to handle a higher number of requests per second.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3c66fe7-bdca-4e45-899a-454c369c945e', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Explain the difference between event-time and processing-time in the context of data modeling.', N'Senior', N'Cassandra uses client-side timestamps to resolve conflicts during updates, which is effectively event-time. Because of this, clock synchronization via NTP across all nodes is critical; otherwise, an older update could overwrite a newer one if the node clocks drift significantly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
