INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'234f35d4-cc8e-45be-8afb-454e5147abba', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the performance overhead of Chi''s routing compared to a regex-based router?', N'Middle', N'Chi uses a trie-based routing approach, which is significantly faster than regex-based routers because it performs path matching in a single traversal. This makes it highly efficient even as the number of routes in the application grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e1b0172-a871-4088-b0b2-45511211dac0', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a ''Phantom Read'' and how is it prevented in InnoDB?', N'Middle', N'A phantom read occurs when a transaction executes a query twice and sees new rows inserted by another concurrent transaction in between. InnoDB prevents this in the ''Repeatable Read'' isolation level using ''Next-Key Locking,'' which locks the gaps between index records to prevent new insertions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
