INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6f9da2a-ae4c-4bbf-9e59-4561cdc2e2e4', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between static and dynamic polymorphism?', N'Middle', N'Static polymorphism is achieved at compile-time using templates or function overloading, resulting in no runtime overhead. Dynamic polymorphism uses virtual functions and inheritance, allowing for runtime selection of behavior but incurring a slight performance cost due to vtable lookups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
