INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f61dd42-195e-4d88-9ccd-45690d1762ee', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What architectural considerations should be taken when implementing WebSockets in AdonisJS for large-scale real-time apps?', N'Senior', N'Scaling WebSockets requires careful management of state and client connections across multiple nodes, typically necessitating an adapter like Redis Pub/Sub. Without this, messages sent to a specific client connected to node A will not reach them if they are expecting a response that was processed by node B.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16f926f5-8946-49de-a535-4569d9c0bae2', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is slots and when is it useful?', N'Intern', N'In Python, every class can have instance attributes. By default Python uses a dict to store an object''s instance attributes. This is really helpful as it allows setting arbitrary new attributes at runtime. However, for small classes with known attributes it might be a bottleneck. The dict wastes a lot of RAM. Python can''t just allocate a static amount of memory at object creation to store all the attributes. Therefore it sucks a lot of RAM if you create a lot of objects. The usage of slots to tell Python not to use a dict, and only allocate space for a fixed set of attributes. Example: 1. Object without slots: 2. Object with slots:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bda782b7-63c4-406a-8624-456a5771c59c', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Explain the concept of ''Event Loop Lag'' in Express and how to monitor it in production.', N'Senior', N'Event loop lag is the delay between when a task is scheduled and when it is actually executed. It is monitored by measuring the time difference between consecutive iterations of the event loop, indicating if the server is overloaded or performing too many synchronous tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b634a72-1c41-4c3c-9fb0-456ba5a8fc8b', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle DOM updates compared to traditional vanilla JavaScript manipulations?', N'Middle', N'Alpine.js abstracts manual DOM manipulation by binding state directly to HTML attributes. While vanilla JS requires imperative code to select elements and change properties, Alpine uses a declarative approach where the view automatically reflects the current state, reducing human error and code verbosity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3b4c9e5-10ac-49cc-9011-456fd85609c6', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue handle memory leaks when using event listeners in a component?', N'Senior', N'Vue automatically removes event listeners attached via the template syntax when a component is unmounted. However, if listeners are attached manually using native DOM APIs, developers must explicitly remove them in the onUnmounted hook to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ccd645b-5f93-4c6f-aef2-4570d8903000', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Can Go programs be cross-compiled?', N'Fresher', N'Yes, Go makes cross-compilation very easy. By setting specific environment variables for the target operating system and architecture, you can compile a Go program on one machine to run on a completely different platform.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f748a79-02f6-4d6a-9ef9-4570f667d25c', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you use v-for directive with a range?', N'Fresher', N'You can also use integer type(say ''n'') for v-for directive which repeats the element many times. It displays the number 1 to 20.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae2b6671-85c6-42e5-8dbd-4571ed0c38b2', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do distributed databases ensure atomicity across heterogeneous data stores?', N'Senior', N'Ensuring atomicity across heterogeneous stores often requires an external orchestration layer or a distributed transaction coordinator that supports protocols like XA. Alternatively, developers may use the Outbox pattern to ensure that state changes and downstream events remain synchronized without requiring a global lock.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e85a267-513a-42fe-8ff1-457af085f270', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a shard and why is it important for scalability?', N'Junior', N'A shard is a single instance of a Lucene index that acts as a subset of the data within an Elasticsearch index. Sharding allows the system to distribute data across multiple nodes in a cluster, enabling horizontal scaling and parallel processing of queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5257771b-3392-4ff6-a8a4-457bc32ee617', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the tools that help to find bugs or perform static analysis?', N'Intern', N'PyChecker is a static analysis tool that detects the bugs in Python source code and warns about the style and complexity of the bug. Pylint is another tool that verifies whether the module meets the coding standard.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2af725b9-0bb6-4ab7-a0e1-457da3095995', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch ensure high availability?', N'Intern', N'High availability is achieved through the use of replica shards. If a node holding a primary shard fails, Elasticsearch promotes one of the replica shards to become the new primary, ensuring data remains accessible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49b02514-2901-4af3-a0f7-457e41b23353', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Does DynamoDB support joins like SQL databases?', N'Fresher', N'No, DynamoDB does not support joins. It is designed for simple, fast access patterns, and data is typically denormalized to avoid the need for joining tables during read operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2db6ab3b-46a0-480a-92fe-4581f384b5fe', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut support validation?', N'Fresher', N'Micronaut integrates with the Bean Validation API (JSR 380). By using annotations like @NotNull, @Size, or @Email on controller parameters or object fields, the framework automatically validates incoming data before the method logic is executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'400f6c6b-7db0-483e-80f0-4582ebc5bef0', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does ''static typing'' mean in the context of TypeScript?', N'Intern', N'Static typing means that the types of variables are checked during the compilation process, before the code is actually executed. This ensures that values assigned to variables match their declared types, preventing common bugs related to unexpected data types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f26cf1c2-27a8-4316-a3c4-45839a746386', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is Micronaut Data?', N'Intern', N'Micronaut Data is a database access toolkit that simplifies repository implementation. It generates data access code at compile time, reducing the need for runtime reflection and improving performance when interacting with databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48b91e66-930e-401f-a154-45847d8c1fc3', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What are the security implications of Fastify''s default JSON validation?', N'Middle', N'By enforcing strict schema validation, Fastify mitigates common vulnerabilities like mass assignment or injection of unexpected fields. This acts as a primary line of defense, ensuring that only expected data types and structures enter your application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'faa6a5cd-2fc0-4f8e-95a9-4584fa7c053a', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar address the challenge of managing database transactions in async routes?', N'Senior', N'Litestar provides structured ways to wrap route handlers in transaction blocks, often via dependency injection or middleware. This ensures that database sessions are correctly opened, committed, or rolled back, preventing data corruption and connection leaks during concurrent asynchronous execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc85a17a-ce8e-4ea9-8bd2-4585b6f091ca', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the primary purpose of ACID properties in transactions?', N'Intern', N'ACID properties are a set of rules that guarantee data validity and reliability during transactions. They ensure that even in the event of errors, power failures, or other accidents, the database remains in a consistent and stable state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
