INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e020c153-ae09-47ae-945d-45a6aa15cae9', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the difference between SFINAE and Concepts in C++ template metaprogramming.', N'Senior', N'SFINAE (Substitution Failure Is Not An Error) relies on the failure of template argument substitution to silently discard candidate functions, often resulting in cryptic error messages. Concepts provide a language-level mechanism to explicitly constrain template parameters, improving compile-time error reporting and allowing for better overload resolution and code readability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2386da50-d4a6-4a98-825c-45a76846eeda', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the difference between a shallow copy and a deep copy in the context of slices?', N'Junior', N'A slice in Go is a header containing a pointer to an underlying array. Copying a slice creates a new header that points to the same underlying array, which is a shallow copy; changing an element will affect both slices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a0755af-db63-461e-ae73-45a7ce53064c', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why might a query plan change even if the underlying data has not significantly changed?', N'Middle', N'Query plans are highly dependent on table statistics collected by the autovacuum process. If these statistics become outdated or if the system settings like random_page_cost change, the optimizer may decide that a different join algorithm or scan method is more cost-effective based on its updated calculations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbc4c8ee-e0f4-4ccf-8c3e-45a86b4fab51', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you create schematics for libraries?', N'Fresher', N'You can create your own schematic collections to integrate your library with the Angular CLI. These collections are classified as 3 main schematics, 1. Add schematics: These schematics are used to install library in an Angular workspace using ng add command. For example, @angular/material schematic tells the add command to install and set up Angular Material and theming. 2. Generate schematics: These schematics are used to modify projects, add configurations and scripts, and scaffold artifacts in library using ng generate command. For example, @angular/material generation schematic supplies generation schematics for the UI components. Let''s say the table component is generated using ng generate @angular/material:table . 3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76c0f6d6-5855-418d-8840-45ab30dafd10', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Explain the consistency model of DynamoDB and why eventual consistency is the default.', N'Senior', N'DynamoDB uses a leader-based replication mechanism across multiple availability zones to ensure durability. Eventual consistency is the default because it allows for lower latency and higher availability by not requiring a synchronous round-trip to all replicas before acknowledging a write. Strong consistency is an option but incurs higher latency and potential availability risks if a partition is unreachable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'809ecaae-acaa-44ae-b4a7-45ab4abbd153', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a NULL value?', N'Junior', N'A NULL value represents the absence of data or an unknown state in a column. It is not equivalent to zero or an empty string, but rather indicates that no value has been assigned to that field.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aec87d13-b6cb-4b4f-8e68-45b1e68dc531', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are Svelte ''actions'' and when should they be used?', N'Middle', N'Actions are functions attached to DOM elements that run when the element is created or destroyed. They are ideal for integrating non-Svelte third-party libraries or handling complex imperative DOM manipulation that is not standard in the declarative lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ad38ca8-e5be-4ae8-a338-45b2346dc250', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is ''CQRS'' (Command Query Responsibility Segregation) and when should it be applied?', N'Senior', N'CQRS separates the data update (Command) path from the data retrieval (Query) path, often using different models or database technologies for each. It should be applied when the read and write workloads have vastly different scalability or complexity requirements, such as complex search vs. simple state updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe91e9f8-d39e-48ae-a34e-45b54c42db4c', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the router imports?', N'Intern', N'The Angular Router which represents a particular component view for a given URL is not part of Angular Core. It is available in library named @angular/router to import required router components. For example, we import them in app module as below,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba30cf51-9af2-45af-8150-45b55583946e', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is an Optional in Swift?', N'Intern', N'An Optional is a type that can represent either a value or the absence of a value, represented as nil. It is a safety feature that ensures the developer explicitly handles cases where a variable might be empty.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a40e59ca-215a-41aa-8d05-45b8170a24e2', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the procedure to run tests in browser?', N'Intern', N'Below are the steps to run tests in real browser, 1. Install mocha-loader. 2. Configure webpack config entry point to ''mocha-loader!babel-loader!./test.js''. 3. Start webpack-dev-server using the config. 4. Go to localhost:8080/webpack-dev-server/test-bundle to see the test result', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0259a965-9e47-4029-8b52-45bc665a4988', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If an application works in development but fails in production, what might be the cause?', N'Fresher', N'The cause is likely an environment difference, such as production having different configuration settings, restricted permissions, or dependencies that are missing or incompatible. Other factors like data volume differences or network security rules also commonly lead to these discrepancies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0f3f207-2fda-46f2-8d85-45be7738269b', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of the ''app'' directory in an AdonisJS project?', N'Intern', N'The app directory is the primary location for your application''s source code, including controllers, models, and services. It serves as the main workspace for organizing the business logic of your project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6f94986-dadd-4651-9b9a-45be87783798', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does the ''refinement'' feature in Ruby address the issues associated with monkey-patching?', N'Senior', N'Refinements provide a way to modify classes locally within a specific scope, preventing global namespace pollution. By explicitly activating refinements only where needed, developers avoid the side effects and unpredictable behavior inherent in traditional monkey-patching, where changes affect the entire application runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fc3b806-5517-409f-9f17-45bed77620c0', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does the Node.js event loop handle CPU-intensive tasks?', N'Middle', N'The event loop is single-threaded, meaning CPU-intensive tasks will block the execution of all other incoming requests. To handle such tasks, developers should offload work to worker threads or delegate the processing to a separate microservice to keep the main event loop free.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a5d234e-aeee-4703-b166-45c1f94545d3', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the impact of long-running queries on the WiredTiger cache?', N'Middle', N'Long-running or inefficient queries can cause high read pressure, forcing the WiredTiger storage engine to constantly fetch data from disk into the cache. This can lead to cache churn, where frequently accessed data is evicted to make room for new data, slowing down overall system performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc5687ba-463d-43e2-80b1-45c48980100d', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is a ''Query Parameter'' in FastAPI?', N'Intern', N'Query parameters are the set of key-value pairs that appear after the question mark in a URL. They are typically used to sort, filter, or paginate the data being requested from an endpoint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3b8ecc1-a100-4e73-82b9-45c5c2acabdc', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle routing, and how do layout files affect the component hierarchy?', N'Middle', N'SvelteKit uses a file-system based router where directory structures define URL paths. Layout files wrap child routes, allowing developers to persist UI elements like headers and footers across navigation without re-rendering them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07a7ae27-192d-46c4-954e-45c6d596b877', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What happens if you use a signal inside an event handler?', N'Junior', N'Using a signal inside an event handler reads its current value without creating a dependency. This is because event handlers are not reactive tracking scopes, meaning changes to the signal will not cause the handler to re-run, which is usually the desired behavior for user-triggered actions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e5964ad-09fb-406b-89d0-45c89f276285', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the difference between a global middleware and a group-level middleware in Echo?', N'Middle', N'Global middleware is applied to every single route in the application, whereas group-level middleware is only applied to routes defined within a specific route group. This allows for granular control, such as applying authentication only to specific API version paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7a843a1-0ef6-44ce-9d90-45cad177050f', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix manage cache invalidation after an action is performed?', N'Senior', N'Remix automatically revalidates all active loaders on the page after any action is executed. This ensures the UI remains consistent with the server state without requiring manual cache management or global state synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'067acffa-f99e-4b87-8f0e-45cc07bb2d31', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the role of the ''Request'' and ''Response'' types in Axum?', N'Junior', N'These types represent the raw HTTP requests and responses as defined in the ''http'' crate. While you often use extractors to simplify access, these types provide full control over headers, status codes, and bodies when needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f972fe1-9170-49de-87c9-45d58b4014af', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain how Memcached should not be used in your Python project?', N'Fresher', N'Memcached common misuse is to use it as a data store, and not as a cache. Never use Memcached as the only source of the information you need to run your application. Data should always be available through another source as well. Memcached is just a key or value store and cannot perform query over the data or iterate over the contents to extract information. Memcached does not offer any form of security either in encryption or authentication', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'999b5eb5-c0e4-4f98-a308-45d7dbf5a11c', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between ''dev'' and ''prod'' environments in Rails?', N'Fresher', N'The development environment is optimized for coding and debugging, with features like auto-reloading and helpful error pages. The production environment is configured for performance and security, disabling debug tools and optimizing asset delivery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90c16f21-1f5a-4f56-ba9a-45d8dbcc93db', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How do you define a route in Echo?', N'Fresher', N'A route is defined by calling the Echo instance''s method corresponding to the HTTP verb, passing the path string and the handler function as arguments. This mapping tells Echo which function to execute when a specific URL and method are requested.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef64cc60-2b83-45ac-a807-45dbed3a1257', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the role of the tsconfig.json file?', N'Fresher', N'The tsconfig.json file acts as the configuration file for the TypeScript project. It specifies the compiler options, such as target JavaScript version and strictness settings, and defines which files should be included or excluded during the compilation process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a25532d-023b-42f8-8169-45df884537c9', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How does redundancy improve system reliability?', N'Intern', N'Redundancy involves adding duplicate components to a system so that if one part fails, another can take over immediately. It eliminates single points of failure, ensuring that the system remains functional during unexpected outages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ba0bafb-e197-41b9-acce-45e358754905', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are the trade-offs of using ''data class'' in Kotlin?', N'Middle', N'Data classes automatically generate useful methods like equals, hashCode, and toString based on constructor properties, reducing boilerplate code. However, they are restricted in that they cannot be open or abstract, and they are generally intended for holding immutable state, which may not be suitable for all domain models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e03f1ad8-bb09-4ab4-927f-45e426ec1c1c', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How do you handle ''Hot Partitions'' in a sharded database architecture?', N'Senior', N'Hot partitions occur when a disproportionate amount of traffic hits a single shard, usually due to poor sharding key selection. This is addressed by choosing a more granular or synthetic sharding key, implementing cache layers, or re-sharding the data to distribute the load more evenly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
