INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5a7fb0b-8c53-4d31-a537-45ea0cec5cff', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is a ''race condition'' and why is it difficult to debug?', N'Fresher', N'A race condition occurs when the system''s outcome depends on the unpredictable timing or sequence of uncontrollable events. Because these issues do not happen every time, they are difficult to reproduce and often disappear when you try to observe them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
