INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93fcfe71-94dc-4b13-baed-45ed60dead57', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Why is ''Idempotency'' critical in distributed message-driven systems?', N'Senior', N'In distributed systems, network issues often cause messages to be delivered multiple times. Idempotency ensures that processing the same message multiple times does not change the result beyond the initial application, which is essential for maintaining data integrity without complex distributed locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7937229-b257-46b3-8b78-45ef77d86f6f', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the concept of ''Autoconfiguration'' in Symfony and how it reduces configuration maintenance.', N'Senior', N'Autoconfiguration automatically applies tags or interface-based bindings to services based on their class type or implemented interfaces. This eliminates the need for manual service registration in configuration files, keeping the codebase clean and minimizing human error during service definition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
