INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54ccd3a5-be96-4406-aa88-45f9cbe4e0ec', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact manage component state updates, and how does it prevent unnecessary re-renders?', N'Senior', N'Preact uses an asynchronous queue to batch state updates, which prevents multiple re-renders within the same tick. Developers can further optimize performance using memoization techniques or by implementing shouldComponentUpdate, ensuring that only necessary sub-trees are reconciled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
