INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45a354d2-1936-4a2d-acbd-45fec0a13ef0', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the useId hook and when should you use it?', N'Fresher', N'The useId hook is a React hook introduced in React 18 that generates unique IDs that are stable across server and client renders. It''s primarily used for accessibility attributes like linking form labels to inputs. Syntax Example: Accessible Form Input When to Use - Generating unique IDs for form elements (htmlFor, aria-describedby, aria-labelledby) - Creating stable IDs in server-side rendering (SSR) applications - Avoiding ID collisions when the same component is rendered multiple times When NOT to Use - As keys in a list (use data-based keys instead) - As CSS selectors or query selectors - For any purpose that requires the ID to be predictable Note: The IDs generated by useId contain colons (:) which may not work in CSS selectors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d33b503-e623-44a2-8942-46027d222a75', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How do database constraints contribute to data quality?', N'Middle', N'Constraints like NOT NULL, UNIQUE, CHECK, and FOREIGN KEY enforce business rules at the database level. They act as a final layer of validation, ensuring that invalid or inconsistent data cannot be persisted, regardless of how the application layer is coded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecd9210c-1bda-40e7-b0e9-460475fd73df', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut''s architecture facilitate the development of serverless functions?', N'Senior', N'The framework''s minimal startup time and low memory usage make it ideal for AWS Lambda or other FaaS platforms where cold-start latency is a critical concern. By eliminating reflection and classpath scanning, Micronaut allows serverless functions to initialize and execute within the strict time limits of these environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12f27b2e-17e7-4408-ad0f-46052f9e61ab', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How can you implement soft deletes in NestJS using TypeORM, and why might soft deletes be preferred over hard deletes?', N'Fresher', N'Soft deletes in TypeORM are implemented using the @DeleteDateColumn decorator.When you delete an entity that has a @DeleteDateColumn, TypeORM doesn''t actually remove it from the database. Instead, it sets the @DeleteDateColumn to the current timestamp. This is known as a "soft delete". Here''s an example of how you might use @DeleteDateColumn in an entity: In this example, when you call userRepository.softDelete(user.id), TypeORM will set deletedAt to the current timestamp, but the User will remain in the database. Soft deletes can be preferred over hard deletes for a few reasons: 1.Data recovery: If a record is accidentally deleted, it can be easily restored. 1. Audit trail: Soft deletes allow you to keep a history of all records, even ones that are deleted. 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e85e6a0f-38ab-4b2e-97e7-460687b2ffd1', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'In a distributed environment, how should Axum''s timeout middleware be configured?', N'Senior', N'Timeout middleware should be configured with sensible defaults based on the P99 latency of downstream dependencies. It is essential to place timeouts early in the middleware stack to ensure that resources are reclaimed quickly when a downstream service fails to respond, preventing a cascading failure across the architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
