INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce8f454b-7e30-43f0-a5d9-460cbae19a65', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the difference between a GET and POST request in AdonisJS routes?', N'Junior', N'A GET request is typically used to retrieve data from the server without changing its state. A POST request is used to send data to the server to create or update a resource.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ec0574d-cbeb-4438-a959-460f460718f8', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of the ''createSignal'' primitive?', N'Fresher', N'The createSignal primitive is used to create a reactive state variable. It returns a getter function to access the current value and a setter function to update the value and trigger reactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0666fb9b-f286-480a-8981-461369228afa', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do ''Feature Flags'' contribute to both reliability and deployment safety?', N'Senior', N'Feature flags decouple deployment from release, allowing for gradual rollouts and instant rollbacks without redeploying code. They increase reliability by limiting the blast radius of new features and providing a mechanism to disable problematic code segments in real-time during an incident.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b071987-374d-4302-aec5-4615a26f7043', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What are the trade-offs of using ''createMemo'' versus ''createEffect'' for deriving state?', N'Senior', N'createMemo is designed for derived state that caches its result and only re-evaluates when its dependencies change, making it ideal for performance optimization. createEffect is intended for side effects that perform actions like DOM manipulation or network requests and does not return a value for downstream consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'525bdae9-a0a5-4142-bad5-4617ab2e540c', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between value types and reference types in Swift, and how does this affect memory management?', N'Middle', N'Value types, like structs, are copied when assigned or passed, ensuring thread safety and preventing unintended side effects. Reference types, like classes, share a single instance via a pointer, requiring reference counting for memory management and potential synchronization for thread safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'214e619d-b334-49f3-9797-4618066a877c', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the common transaction isolation levels in MySQL and why do they matter?', N'Middle', N'MySQL supports levels like Read Committed, Repeatable Read, and Serializable, which balance data consistency against system performance. Higher isolation levels prevent phenomena like phantom reads and non-repeatable reads but increase locking overhead and reduce concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed4aa3a8-5092-41e3-b24f-461f8f1a8b99', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a GOPATH?', N'Fresher', N'GOPATH is an environment variable that defines the location of your workspace. It specifies the directories where the Go tools look for source code, compiled packages, and executable binaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6877a745-a187-48d9-86dc-4620d365e272', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the purpose of the ''Query Plan Cache''?', N'Senior', N'The plan cache stores the compiled execution plans for frequently run queries to avoid the overhead of parsing, analyzing, and optimizing the same query repeatedly. This significantly reduces latency for repetitive transactional workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce40d2db-f2cc-4fcd-a6ff-462118071f4e', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why does Vite use Rollup for production builds instead of esbuild?', N'Senior', N'While esbuild is faster, Rollup provides a more mature plugin ecosystem and superior code-splitting capabilities. Rollup is better optimized for generating highly efficient, tree-shaken, and production-ready bundles for complex applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df2d4623-87ad-4812-9fd0-46213f8881f2', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do you access imperative API of web components?', N'Fresher', N'Web Components often expose an imperative API to implement its functions. You will need to use a ref to interact with the DOM node directly if you want to access imperative API of a web component. But if you are using third-party Web Components, the best solution is to write a React component that behaves as a wrapper for your Web Component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01ccbe81-66d8-4103-8ab1-462176a5ca6f', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does Isolation mean in a transaction?', N'Fresher', N'Isolation ensures that concurrent transactions do not interfere with each other. It means that the intermediate state of a transaction is invisible to other transactions until it is committed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
