INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82f67517-8400-4387-b647-462859cc3c3f', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between a module and a package?', N'Junior', N'A module is a single Python file containing code, such as functions or classes, that can be imported into other scripts. A package is a directory containing multiple modules and a special file, usually named __init__.py, which allows for a hierarchical structure of code organization. Packages make it easier to manage large projects by grouping related modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
