INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'186f59ff-09cf-4be9-a505-462ad09feb8d', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What does the term ''utility-first'' mean in the context of Tailwind CSS?', N'Intern', N'Utility-first means that the framework provides small, single-purpose classes that each perform one specific styling task, such as setting a margin, color, or font size. By combining these small classes directly on an element, you can create complex designs without writing custom CSS files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bbcc1c6-cff7-4640-9568-462b1fbef4ae', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does Node.js handle child threads?', N'Fresher', N'Node.js employs event-driven architecture and non-blocking I/O for efficiency. While Node.js operates off a single main thread, it can harness the full power of multi-core systems by launching child threads for specific tasks, such as file compression or image processing. Thread Pool and Worker Threads To manage these child threads, Node.js uses a combination of: - A thread pool, powered by the libuv library. - Worker threads for dedicated, offloaded computation. Node.js Event Loop When a task in Node.js is designated to operate on a child thread, the main event loop hands it over to the thread pool. This setup allows Node.js to stay responsive to incoming requests, benefiting from asynchronous I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
