INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a7486d9-0c79-4194-ae6b-463c353a5104', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the concept of immutability in Scala.', N'Fresher', N'Immutability means that once an object is created, its state cannot be modified. In Scala, this is encouraged by using ''val'' and immutable collections, which helps write safer and more predictable code in multi-threaded environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bebb3201-5b89-47da-84a0-463f3ce149d4', N'4c000000-0000-0000-0000-000000000005', N'What is the purpose of database sharding?', N'Middle', N'Sharding is the practice of splitting a large dataset into smaller, more manageable chunks across multiple database instances. It improves performance and capacity by distributing the query load and storage requirements across hardware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a10ea0cb-ed5b-4ae8-af64-46425abb366a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the various data types in JavaScript?', N'Intern', N'In JavaScript, data types can be categorized into primitive and non-primitive types: Primitive data types - Number: Represents both integers and floating-point numbers. - String: Represents sequences of characters. - Boolean: Represents true or false values. - Undefined: A variable that has been declared but not assigned a value. - Null: Represents the intentional absence of any object value. - Symbol: A unique and immutable value used as object property keys. Read more in our deep dive on Symbols. - BigInt: Represents integers with arbitrary precision. Non-primitive (Reference) data types - Object: Used to store collections of data. - Array: An ordered collection of data. - Function: A callable object. - Date: Represents dates and times. - RegExp: Represents regular expressions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf309e06-fe05-4da1-9d4a-46428af6a053', N'954a0331-deff-4399-b588-96f39fec001d', N'What happens if I import the same module twice?', N'Junior', N'If multiple modules imports the same module then angular evaluates it only once (When it encounters the module first time). It follows this condition even the module appears at any level in a hierarchy of imported NgModules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23996c21-8631-49ac-8453-46451543e830', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix manage data revalidation after a mutation?', N'Middle', N'After an action is successfully executed, Remix automatically revalidates all active loaders on the page to ensure the UI stays in sync with the server state. This eliminates the need for manual cache invalidation or state updates, as the framework handles the data refresh cycle automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10e702a3-3bd6-4755-805b-46456a66cad0', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When implementing caching, how do you weigh the benefits of read-through caching versus write-behind caching?', N'Middle', N'Read-through caching reduces latency for frequent reads but adds complexity to cache invalidation strategies to prevent stale data. Write-behind caching improves write performance significantly by updating the database asynchronously, but it carries a higher risk of data loss if the cache node fails before the write completes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6c61d2d-f33d-4895-97b7-4646b806b811', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the role of the ''string interning'' mechanism in C#?', N'Middle', N'String interning is an optimization where the runtime stores only one unique instance of each literal string in a special pool to save memory. While this reduces the memory footprint for duplicate strings, it is handled automatically by the compiler and should not be relied upon for manual memory management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c0ad476-e270-458e-acf7-464c533e0a25', N'075b8862-431c-4678-9767-f55359758a4a', N'What are asset url transform rules?', N'Intern', N'Below are the list of Asset URL transform rules 1. Absolute path: If the URL is an absolute path (for example, /images/loader.png)then it will be preserved as-is. 2. Relative path: If the URL starts with . (for example, ./images/loader.png) then it will be interpreted as a relative module request and resolved based on the folder structure on your file system. 3. URLs starts with ~ symbol: If the URL starts with ~ symbol(for example, ./some-node-package/loader.png) then it is interpreted as a module request. This way it can reference assets inside node modules too. 4. URLs starts with @ symbol: If the URL starts with @ symbol then it is interpreted as a module request. This is useful if your webpack config has an alias for @, which by default points to /src path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a652e5fc-9301-4eaf-9641-464cd3874450', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the purpose of database indexing, and how does it support scaling?', N'Middle', N'Indexing creates data structures that allow the database to find records faster without scanning every row in a table. By improving query performance, indexing reduces the CPU and I/O pressure on the database, allowing it to handle more concurrent requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2d00c1b-ece5-49af-90ac-464cdf724870', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Does Chi handle CORS (Cross-Origin Resource Sharing)?', N'Fresher', N'While Chi does not have a built-in, pre-configured CORS feature, it provides middleware support that allows you to easily plug in standard CORS handling packages. You can apply this middleware globally or to specific groups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1007a9ac-0971-4316-aece-464ef1fe319c', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the difference between a REST resource and a Service in Quarkus?', N'Junior', N'A REST resource is typically a class annotated with @Path that handles incoming HTTP requests and responses. A service is generally a CDI bean that contains the business logic, which is then injected into the resource to perform operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce5c5ae1-2a81-49c3-ba69-464fccddcf22', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is JIT compiler in Java?', N'Intern', N'The Just-In-Time (JIT) compiler is a component of the runtime environment that improves the performance of Java applications by compiling bytecodes to native machine code at run time. Java programs consists of classes, which contain platform-neutral bytecodes that can be interpreted by a JVM on many different computer architectures. At run time, the JVM loads the class files, determines the semantics of each individual bytecode, and performs the appropriate computation. The additional processor and memory usage during interpretation means that a Java application performs more slowly than a native application. The JIT compiler helps improve the performance of Java programs by compiling bytecodes into native machine code at run time. The JIT compiler is enabled by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5834b57e-03e2-48ff-bcd3-46510d0439ce', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Explain the role of the dependency injection system in FastAPI.', N'Middle', N'The dependency injection system allows developers to define reusable logic, such as database sessions or authentication providers, which the framework manages and injects into route handlers. This promotes modularity, makes unit testing easier by allowing mock dependency overrides, and decouples business logic from infrastructure concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74702cea-ab49-4ada-87f6-46514781c2ff', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s actor model ensure thread safety compared to traditional locking mechanisms?', N'Senior', N'Actors provide a synchronization mechanism that guarantees serial access to their mutable state by ensuring only one task can execute on the actor at a time. This eliminates data races by design, replacing error-prone manual locks with a language-level concurrency model. By isolating state and enforcing asynchronous communication, actors simplify the architecture of multi-threaded systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'960b0280-45e3-4d63-b57a-4651d7674c9c', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a database schema in the context of PostgreSQL?', N'Intern', N'A schema is a namespace that allows you to logically organize database objects like tables, views, and functions into groups. Using schemas helps prevent naming conflicts and allows multiple users or applications to share a single database while keeping their data structures separate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0ce2f8b-43d4-4268-86e2-46535db46f8c', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Discuss the scalability challenges of R''s ''in-memory'' data model.', N'Senior', N'R''s default architecture loads datasets entirely into RAM, which imposes a hard physical limit on the size of data that can be processed at once. Scaling to larger datasets requires specialized out-of-memory or distributed computing frameworks that interface with backends like databases or cluster computing environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a07e1fbd-5bfe-4a88-9310-46553baf1167', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What are the performance implications of ''x-for'' lists in Alpine.js?', N'Middle', N'Using x-for creates a reactive loop that updates specific nodes when the underlying collection changes. While highly efficient for small to medium lists, rendering thousands of items can impact performance, so it is recommended to use keys for list items to help Alpine track DOM nodes accurately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e730e5b6-00d9-46b4-ad6e-4656b1b4ca0e', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Does Kotlin support primitive types?', N'Fresher', N'Kotlin does not have primitive types in the way Java does. Instead, it uses classes to represent numbers, characters, and booleans, but the compiler optimizes these into primitives at runtime to ensure high performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'383e142c-89ee-487b-b78e-465c58eff5dc', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of the application.properties file?', N'Intern', N'This file is used to externalize the configuration of your application. It allows you to change settings like server port, database credentials, or logging levels without having to recompile the application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'614a35e4-2c18-4ae6-ab71-465ce968c4fb', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How can you prevent memory leaks when using event emitters in Node.js?', N'Senior', N'Memory leaks occur when event listeners are attached to long-lived objects without being explicitly removed, preventing the garbage collector from reclaiming the listener''s scope. This is mitigated by using ''once'' for one-off events, properly implementing ''removeListener'' in component lifecycles, and monitoring listener counts for potential leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e6e4440-e13c-4cda-a044-465eec798726', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is ''Path Parameter'' in routing?', N'Intern', N'A path parameter is a dynamic segment of a URL, such as an ID, that is captured by the router. It allows a single handler to respond to different URLs by using the dynamic segment as an input variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b4a2e40-1a33-47bb-8946-465ffe8acda3', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do you bind form inputs to component state in Svelte?', N'Fresher', N'Svelte uses the ''bind:'' directive to create two-way data binding between form elements and variables. When the user changes the input value, the associated variable in the script is automatically updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cfca428-ca96-4622-86e4-4660fdaf450c', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Why is observability critical for scalable systems?', N'Middle', N'Observability through logging, metrics, and tracing allows engineers to identify performance bottlenecks and resource exhaustion in real-time. Without these tools, it is impossible to effectively tune the system or plan for the infrastructure capacity needed to scale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ae426dc-0434-497d-b47d-4663398c9190', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why does SolidJS avoid using a Virtual DOM?', N'Middle', N'SolidJS avoids the Virtual DOM to eliminate the overhead of diffing and reconciliation. By compiling code directly to DOM operations, it achieves higher performance and smaller bundle sizes while maintaining a reactive system that updates only what is necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9ad570e-48f8-4e24-8785-46692f258a70', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is a function in PHP?', N'Fresher', N'A function is a block of code designed to perform a specific task that can be called whenever needed. It helps in organizing code, reducing repetition, and making the application easier to maintain by separating logical units.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6785dade-9a02-44f1-8ec1-4669921a227a', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Is Ruby a statically typed or dynamically typed language?', N'Intern', N'Ruby is a dynamically typed language. This means that variable types are checked at runtime rather than at compile time, allowing for more flexibility in how variables are used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a17e7969-bf52-4736-9cf5-466ad185b872', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the trade-off between write amplification and read amplification in LSM-tree implementations?', N'Senior', N'Tuning compaction frequency directly impacts these metrics; frequent compaction reduces read amplification by limiting the number of files to scan but increases write amplification due to constant background data rewriting. Conversely, infrequent compaction lowers write overhead but creates deeper merge trees, forcing readers to probe more files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea57e63c-29fe-41ab-ab3d-466cbd57cf6d', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Explain the difference between undefined behavior and implementation-defined behavior in the C standard.', N'Senior', N'Undefined behavior allows the compiler to assume the situation never occurs, potentially leading to unpredictable program states or total optimization failure. Implementation-defined behavior requires the compiler to document its specific choice, ensuring that while the code is non-portable, the result remains consistent and deterministic within that specific environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71079157-2515-4632-9944-466d410a7d65', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus optimize I/O operations compared to blocking servlet-based architectures?', N'Senior', N'Quarkus is built on top of Vert.x and uses a non-blocking reactive engine by default. This allows it to handle massive concurrent connections with a small number of threads, avoiding the thread-per-request overhead that limits scalability in traditional blocking models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a02727b1-9571-4edc-8719-466f58210a04', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the Scala programming language primarily designed to combine?', N'Intern', N'Scala is designed to integrate features of both object-oriented programming and functional programming. It allows developers to use object-oriented structures like classes while utilizing functional concepts like immutability and higher-order functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09b64623-7053-4608-b6f7-466f826556f9', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why should you avoid using ''ts-ignore'' in your projects?', N'Middle', N'The ''ts-ignore'' comment suppresses type errors for a single line, effectively bypassing the safety mechanisms of TypeScript. Overusing it masks potential bugs and creates technical debt, making the codebase harder to maintain and refactor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55aca1c3-0477-452f-865a-467027d3f85f', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How do you define dynamic routes in Remix?', N'Junior', N'Dynamic routes are defined by using a dollar sign prefix for filenames in the routes directory, such as users/$userId.tsx. This tells Remix that the segment is a variable parameter that can be accessed via the route''s params object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'491457f2-40dd-44da-bfb3-4670bd3e9540', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between @RequestMapping and @GetMapping?', N'Middle', N'While @RequestMapping is a generic annotation that maps requests based on URL, method, and parameters, @GetMapping is a composed annotation specifically for HTTP GET requests. Using composed annotations makes the code more readable and intent-expressive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32c8482e-7671-4a8b-a441-4671e110c3e7', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is your strategy for debugging a service that exhibits ''long tail'' latency only for a small subset of users?', N'Senior', N'I segment the telemetry by user attributes, such as account tier, region, or specific data shards, to see if the latency correlates with specific usage patterns. This often reveals issues like inefficient database queries triggered by complex user data structures or specific cache-miss scenarios limited to those users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bfbea9e-beaf-4c7a-9927-4673f3f92db3', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How do you avoid ''prop drilling'' with Redux?', N'Middle', N'Redux eliminates prop drilling by providing a global store that components can connect to directly. Instead of passing data through multiple layers of intermediate components, any component can access the state it needs regardless of its position in the hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd821bc11-1fb4-402b-b458-4674a369cf32', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is an Ember ''Initializer'' and when should it be used versus an ''Instance Initializer''?', N'Senior', N'Initializers run once at app boot and are meant for setting up global framework configurations. Instance initializers run after the app has booted and have access to the container, making them suitable for setting up services that rely on the application instance state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8323f5d3-075c-40de-b0a7-46762b26cb51', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Under what conditions would you choose an eventual consistency model over strong consistency?', N'Senior', N'Eventual consistency is chosen when high availability and low latency are prioritized over immediate data accuracy, such as in social media feeds or analytics. It allows the system to remain functional despite network partitions or heavy load that would otherwise cause blocking in a strongly consistent system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'115f08fc-74a7-434d-9ab2-467967689aef', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the primary purpose of the Rocket framework in the context of backend development?', N'Intern', N'Rocket is a web framework for the Rust programming language designed to make it simple to write fast, secure, and type-safe web applications. It leverages Rust''s strong type system and ownership model to ensure that common web vulnerabilities, such as memory safety issues, are prevented at compile time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5dae5a8c-792e-4937-9d1d-467c715f7e43', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If you notice a database query is running very slowly in a development environment, what is the first thing you would investigate?', N'Fresher', N'I would check if the database table has proper indexes on the columns being queried, as missing indexes force the database to scan every row. I would also examine the complexity of the query to see if it can be simplified or if it is retrieving more data than is actually necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f509ef1-59c0-4cbf-9c7f-467d2c9a9073', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What does the term ''vectorization'' mean in R?', N'Fresher', N'Vectorization is a feature in R where operations are performed on entire vectors at once rather than using explicit loops to process individual elements. This makes R code more efficient, concise, and often faster to execute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7042cb7e-a024-4518-a225-4680bd0710fd', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the purpose of cache warming?', N'Middle', N'Cache warming is the practice of pre-populating a cache with frequently accessed data before a system goes live or after a restart. This prevents a spike in database load and latency immediately after deployment, ensuring the system performs optimally from the start.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'530b034e-bc8d-46de-9dae-4680da89f666', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the difference between Django’s select_related and prefetch_related, and when do you choose one over the other?', N'Senior', N'select_related performs a SQL JOIN to fetch related objects in a single query, which is efficient for one-to-one or foreign key relationships. prefetch_related executes separate queries and links the results in Python, which is necessary for many-to-many or reverse foreign key relationships where joins would cause a Cartesian product explosion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb4ecfa6-6432-4019-ab1a-468426636797', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the primary purpose of a data frame in R?', N'Junior', N'A data frame is a tabular data structure used to store related variables of different types. It is organized like a spreadsheet where each column represents a variable and each row represents an observation, making it the standard format for most data analysis tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b090cbb3-6098-43d4-a5f6-4686611bf165', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Does Micronaut support dependency injection via constructor, setter, and field?', N'Junior', N'Yes, Micronaut supports all three, but constructor injection is the recommended approach. Constructor injection makes dependencies explicit and promotes immutability, which leads to more testable and robust code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90c949ee-efc2-4c89-ad5e-468817653342', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the difference between an Extractor and a Middleware in Axum?', N'Fresher', N'Extractors are used to parse and validate specific parts of an individual request for use within a handler. Middleware acts as a wrapper around the entire handler process to apply logic globally or to a group of routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7204047-ada5-4e91-af3b-468d40c50c49', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the importance of checking logs when investigating a system error?', N'Fresher', N'Logs provide a chronological record of system events and error messages that might not be visible to the end user. They help narrow down the location of a fault by showing exactly where the process deviated from expected behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27e9a42c-f618-4294-a4e9-468dfd20dda2', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What does ''serialization'' mean in Litestar?', N'Intern', N'Serialization is the process of converting Python objects, such as dictionaries or classes, into a format that can be sent over the network, usually JSON. Litestar performs this automatically based on the return type hint of the route handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2233f7c2-8d32-4b83-b323-46901bbf328a', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why is it important to use ''fastify-plugin'' when creating a database connector plugin?', N'Middle', N'Database connectors usually need to be accessible across the entire application. By using fastify-plugin, you bypass encapsulation, allowing the database client to be decorated onto the Fastify instance so it is available in all routes and plugins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81b86630-4656-495f-8ca9-4690e4d283f7', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the difference between a mixin and @extend?', N'Junior', N'Mixins are best for creating reusable chunks of code that might require arguments or variations. @extend is better for sharing common styling properties between selectors to keep the final CSS file size smaller by grouping them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f22e8172-6d33-40b7-ac6a-469131c18c61', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the benefit of using route groups in Chi for large-scale backend services?', N'Middle', N'Route groups allow for modularizing routes by domain or functionality, enabling the application of specific middleware stacks to isolated segments of the API. This improves readability and prevents the need for global middleware that might not be applicable to all endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aecaaad2-9f7a-4861-83bf-46915a7bfa3d', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the primary trade-offs when choosing between the cluster module and worker threads in a Node.js application?', N'Middle', N'The cluster module creates separate processes, each with its own memory space and event loop, which is ideal for scaling horizontally across multiple CPU cores to handle high traffic. In contrast, worker threads share the same memory space and are designed for CPU-intensive tasks, offering lower overhead for communication but requiring careful synchronization. Use clusters for horizontal scaling and worker threads for offloading computationally expensive synchronous logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7284cf7e-8d2d-4342-8949-4692dd49e7c2', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of the Show component?', N'Intern', N'The Show component is a control flow utility used for conditional rendering. It efficiently toggles the visibility of its children based on a boolean condition provided as a prop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecef313c-8dc1-4e80-99fa-4693145ab196', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How do HTML custom elements affect the browser''s document lifecycle?', N'Senior', N'Custom elements introduce a lifecycle consisting of connected, disconnected, and attribute changed callbacks, which move state management into the DOM. This architectural shift allows developers to bridge the gap between declarative HTML and imperative JavaScript, though it requires careful handling of memory to avoid leaks when elements are detached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'496020ca-a251-4dfc-98b5-469536898d70', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is a Dependency Injection in Litestar?', N'Fresher', N'Dependency Injection is a pattern where the framework provides required objects or services to a handler function automatically. Instead of creating objects inside the function, you define them as parameters, and Litestar resolves them at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
