INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afe380f1-9d6c-4914-abd3-469907b12352', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is an Error handler in Actix-web?', N'Fresher', N'An error handler is a mechanism used to transform internal application errors into user-friendly HTTP error responses. It ensures that the client receives a meaningful status code and error message instead of raw server panic data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
