INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0c6ebd2-ae30-4110-961d-469c98659b17', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is an index in R?', N'Junior', N'Indexing is the process of selecting specific elements from a data structure using their position or name. R uses square brackets to specify the row and column indices for data extraction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e40c22fb-c29b-429f-a4eb-469d9af3efb9', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why is testing in Rocket considered easier than in other frameworks?', N'Middle', N'Rocket provides a local client that mimics the entire request-response lifecycle without needing a network port. This allows for full integration testing of routes, guards, and fairings in a controlled environment, making it simple to assert behaviors without external dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0faf07d8-6bd4-4970-af45-469dff493c32', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle memory management when the server runs out of RAM?', N'Junior', N'Redis uses eviction policies, such as Least Recently Used (LRU), to automatically remove old or unused keys to free up space. Administrators can configure these policies to determine which data should be discarded when the memory limit is reached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a590c97f-b65b-4f89-a98c-46a190618634', N'954a0331-deff-4399-b588-96f39fec001d', N'How does the ''Angular CLI'' leverage Webpack or Esbuild to optimize production builds?', N'Senior', N'The CLI uses these bundlers to perform tree-shaking, code splitting, and minification, turning a modular development environment into an optimized production bundle. Modern versions of Angular have migrated to Esbuild for significantly faster build times compared to Webpack, though the fundamental goal of stripping dead code and optimizing asset delivery remains the same.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'113de036-e349-4549-b4a9-46a28d3ac98f', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why is Chi considered a ''micro-router''?', N'Fresher', N'It is called a micro-router because it focuses strictly on HTTP routing and middleware, leaving other concerns like database access, template rendering, or configuration management to the developer. It provides the routing foundation without dictating the entire application structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f829d1c-d454-4c7d-bbd8-46a6c81cdba9', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you estimate the storage requirements for an image-sharing platform?', N'Intern', N'I would estimate the number of new images uploaded per day and the average file size per image. By multiplying these, I can determine the daily storage growth rate and project it over a monthly or yearly period. This helps in capacity planning and anticipating infrastructure needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8938c688-e51f-4ae9-b415-46a7a3db293d', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the impact of TypeScript''s ''declaration maps'' on developer experience and debugging in a distributed library ecosystem?', N'Senior', N'Declaration maps enable source mapping between generated declaration files and original source files, allowing IDEs to navigate directly to the source code rather than the compiled definition. This significantly improves the developer experience for consumers of libraries, as it facilitates easier inspection of implementation details and underlying logic during debugging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df1131b5-6fb7-495b-8179-46a7ee404871', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How would you approach choosing between a library and a framework for a project?', N'Intern', N'A library gives you control over the flow of the application and allows you to call functions as needed, whereas a framework defines the structure and dictates the flow of control. Choose a library for flexibility in specific tasks and a framework for standardized development and faster setup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcc89251-5be0-4e6f-8797-46a901728f6f', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of normalization in database design?', N'Intern', N'Normalization is the process of organizing data in a database to reduce redundancy and improve data integrity. It involves dividing a database into two or more tables and defining relationships between them to ensure that each piece of data is stored in only one place. This helps prevent anomalies during data insertion, update, or deletion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c150370-cd1b-4cb2-b425-46aa351fdd98', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What role does the ''server'' entry point play in a Remix application?', N'Middle', N'The server entry point acts as the interface between the Remix framework and the underlying platform''s request handler, such as Node.js or edge workers. It allows developers to customize how the application handles requests, including middleware, response headers, and streaming settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b36f39a-32f6-4771-a7f7-46ac3723138e', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are ACID properties?', N'Fresher', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably and maintain data integrity even in the event of errors or power failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e120c78-27e3-4039-b76d-46b1c4d1a916', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the concept of ''ValueTask'' and when it should be used over ''Task''.', N'Middle', N'ValueTask is a struct-based type designed to reduce heap allocations for asynchronous methods that often complete synchronously. It should be used in high-performance scenarios or hot paths where the overhead of creating a Task object for every completion would cause excessive garbage collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
