INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ab8ca02-bd43-4cd5-b7ed-46bbfd6976fa', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the C type system handle strict aliasing and what are the implications for instruction scheduling?', N'Senior', N'The strict aliasing rule prohibits accessing an object through a pointer of a type incompatible with its effective type, excluding character types. By enforcing this, compilers can safely assume that pointers of different types do not refer to the same memory location, enabling more aggressive load/store motion and loop optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8aa317b9-1e93-45c8-8e05-46bdbb9ac662', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is a Signal in SolidJS and why is it the core of its reactivity?', N'Middle', N'A Signal is a primitive that encapsulates a value and provides getter and setter functions. It tracks dependencies automatically, allowing SolidJS to subscribe specific DOM updates to changes in that value without requiring a Virtual DOM reconciliation process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7020d374-f220-433d-b9e0-46bf4464f669', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are the performance implications of using ''Lazy Val'' in Scala within a multi-threaded context?', N'Senior', N'Lazy vals in Scala are thread-safe by default, using a synchronization mechanism that ensures the initialization block is executed exactly once. This introduces a small performance penalty due to the internal locking needed to guard the initialization state. In high-contention scenarios, this can lead to thread blocking, requiring careful consideration of initialization order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9938824e-26ea-46f2-8880-46c1ff8cf26e', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the purpose of partitioning in a database?', N'Middle', N'Partitioning divides large tables into smaller, physically separate segments based on specific criteria like date ranges or hash values. This improves performance for queries that only need to access a specific partition rather than scanning the entire table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ae1fb08-efe4-4e76-8f12-46c3a90d0a6d', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the primary use case for Redis in modern applications?', N'Fresher', N'The most common use case is caching. It sits between an application and a slow primary database to store frequently accessed data, reducing load on the main database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'815054ab-7740-4311-855d-46c3c8b88dc0', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why is there no need for a hook like ''useMemo'' or ''useCallback'' in Svelte?', N'Middle', N'Svelte handles reactivity through assignment and explicit dependencies. Since the compiler understands the data dependencies of your code, it automatically generates the necessary logic to recompute values only when their specific inputs change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b00f7c0-9343-41a3-b55a-46c5089367a6', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are the trade-offs of using ''Arc'' over ''Rc''?', N'Middle', N'Rc is for single-threaded reference counting and is faster because it does not use atomic operations. Arc is for multi-threaded scenarios and uses atomic operations to ensure reference counts are updated safely, which comes with a performance overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1afbc2be-b120-4b64-adf6-46c6aaf5aada', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What are the trade-offs of using Litestar''s built-in message-based architecture versus standard middleware?', N'Senior', N'Middleware in Litestar operates at the ASGI layer, providing broad control over the raw request-response flow, whereas handlers and dependency providers operate within the application layer. While middleware is powerful for cross-cutting concerns, application-level guards are more performant and easier to unit test as they have access to the fully parsed request state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f29e272-ae00-4384-84ec-46c84dfd75b9', N'a2838158-7305-480a-b22b-4dc35776b400', N'What are the primary challenges of implementing distributed transactions using Two-Phase Commit (2PC)?', N'Senior', N'The main challenges are the blocking nature of the protocol, which can lead to system-wide stalls if a participant fails, and the vulnerability to a single point of failure at the coordinator. Additionally, 2PC has poor scalability and high latency due to the multiple rounds of communication required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f52128be-d32f-4c01-8b65-46cbab685b1d', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the significance of the express.static middleware?', N'Fresher', N'express.static is a built-in middleware function that serves static files such as images, CSS files, and JavaScript files. It enables the server to deliver these assets directly to the client without needing custom route handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d293ec3-c2b0-4c82-b5ce-46cbc47a9b42', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is ''Streaming'' in Hono and why is it useful?', N'Junior', N'Streaming in Hono allows you to send a response to the client in chunks rather than waiting for the entire body to be generated. This is useful for improving perceived performance when dealing with large datasets or generating content dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2887adcc-81b8-4c62-b1d6-46cec420f6d1', N'4c000000-0000-0000-0000-000000000005', N'What are the advantages of Event Sourcing compared to traditional CRUD-based state storage?', N'Senior', N'Event Sourcing stores the entire history of state changes as a sequence of immutable events rather than just the current state. This provides a perfect audit log, enables temporal queries, and allows the system to rebuild state or derive new projections from past events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6824fce-78d5-417f-85f6-46cef7ca53d9', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the concept of ''Linearizability'' in the context of distributed transactions.', N'Senior', N'Linearizability provides the illusion that the system has a single copy of data and all operations are atomic and instantaneous. It is a strong consistency model that ensures once a write completes, all subsequent reads see that write, regardless of which node they query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc167aa7-b85d-413b-80e2-46cfcd6f9c30', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is it generally discouraged to use global variables with Fiber''s context?', N'Middle', N'Because Fiber reuses context objects to minimize allocation, global state modifications can lead to data races or leakage between unrelated requests. Thread safety is compromised if state is not explicitly managed within the request scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29a6b5a8-b5c7-4e66-be45-46d190cf5147', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'When should you avoid Alpine.js in favor of a full-stack framework like Next.js or Nuxt?', N'Senior', N'You should avoid Alpine.js when your application requires complex client-side routing, sophisticated middleware, server-side data fetching, or a deeply nested component hierarchy. Alpine is designed for progressive enhancement, and attempting to build a large-scale SPA with it will result in significant technical debt and maintenance challenges.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f74f594e-e120-4cd5-b40a-46d305fb60d9', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a Graph database and how does it differ from a Key-Value store?', N'Middle', N'A Graph database is designed to store and navigate complex relationships between data entities using nodes, edges, and properties. Unlike a Key-Value store which focuses on simple retrieval by key, graph databases prioritize the traversal of interconnected data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77882934-fd45-452e-b634-46d3d5090359', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Can you create an index in an array field in MongoDB?', N'Middle', N'Yes, To index a field that holds an array value, MongoDB creates an index key for each element in the array. Multikey indexes can be constructed over arrays that hold both scalar values (e.g. strings, numbers) and nested documents. MongoDB automatically creates a multikey index if any indexed field is an array. Syntax: For example, consider an inventory collection that contains the following documents: The collection has a multikey index on the ratings field: The following query looks for documents where the ratings field is the array [ 5, 9 ]: MongoDB can use the multikey index to find documents that have 5 at any position in the ratings array. Then, MongoDB retrieves these documents and filters for documents whose ratings array equals the query array [ 5, 9 ].', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ecec59b-6c61-446d-8122-46d5857d9f87', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a system where service discovery is failing to register new nodes?', N'Senior', N'I would check the network connectivity between the new nodes and the service discovery server, specifically looking for firewall rules or misconfigured security groups. I would also review the service discovery logs for registration conflicts or timeout errors that occur when the registry is under high load or experiencing network partitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6549a9b8-010e-4a28-a116-46d83a54d5fa', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Compare Express''s single-threaded nature to worker-thread integration for CPU-intensive tasks.', N'Senior', N'Because Express runs on the main Node.js event loop, CPU-heavy tasks block the entire process, preventing new requests from being accepted. Integrating worker threads is required to offload computational work, but requires careful orchestration to avoid overhead and memory consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a253a4f-48cb-42e7-b2ac-46d8a3efeedf', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Describe how the JavaScript prototype chain impacts memory usage and property lookup performance.', N'Senior', N'The prototype chain allows objects to share methods, reducing memory usage by avoiding duplicate function definitions across instances. However, deep prototype chains increase property lookup time as the engine must traverse the chain to find a property, which can impact performance in hot code paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf8efa86-0fa7-4a4d-affc-46d9fe56d5b4', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does ''Long Polling'' improve the efficiency of pull-based messaging?', N'Senior', N'Long polling reduces latency and unnecessary network overhead by holding a request open on the server until a message becomes available or a timeout occurs. This effectively combines the efficiency of polling with the low-latency characteristics of push-based models, as the server responds immediately upon message arrival.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3c45e64-cd7e-4426-b23f-46da02fb071e', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What are channels in Go?', N'Intern', N'Channels are the pipes that connect concurrent Goroutines. They allow different parts of a program to communicate with each other and synchronize execution by sending and receiving values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a863fbd4-dca3-400f-aa85-46db99e1bc2a', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the role of ''hinted handoff'' in a peer-to-peer distributed database.', N'Senior', N'Hinted handoff is a mechanism to maintain availability when a node is temporarily unreachable. When a write fails due to a node being down, the coordinator stores a ''hint'' on another healthy node, which is then replayed to the original target once it recovers, ensuring eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'add1970b-ae4f-4348-9e52-46ddafe6fb57', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the difference between a class and a case class?', N'Fresher', N'A case class is a regular class with extra features such as immutability by default, built-in support for pattern matching, and automatic generation of methods like equals, hashCode, and toString.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a6a39f7-4ba7-44c0-afbb-46e0ee4ff9fa', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is Durability in a database system?', N'Intern', N'Durability guarantees that once a transaction has been committed, it will remain saved even in the event of a system failure or power loss. The changes are permanently recorded in non-volatile memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebc5b6d4-fdd5-465e-818e-46e16aa0eba0', N'4c000000-0000-0000-0000-000000000005', N'How does load balancing at the OSI Layer 4 compare to Layer 7?', N'Senior', N'Layer 4 load balancing operates at the transport layer, forwarding packets based on IP and port, offering high performance with low overhead. Layer 7 load balancing inspects application content like HTTP headers or paths, enabling sophisticated routing decisions and traffic shaping.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61a03003-4010-4b9c-b259-46e3adcbd198', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Does Alpine.js have a virtual DOM?', N'Fresher', N'No, Alpine.js does not use a virtual DOM. It manipulates the real DOM directly, which is why it is so lightweight and easy to integrate into existing server-rendered HTML pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9201aef-dc44-4ac4-a429-46e73c0d7dde', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Does Redis support indexes like SQL databases?', N'Junior', N'No, Redis does not have traditional indexes. To query by something other than the key, you must manually maintain secondary indexes using other Redis data structures like Sets or Sorted Sets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80c636d6-4918-4fda-b925-46e7d808bd8a', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is an Extractor in Actix-web and why is it used?', N'Middle', N'Extractors are a powerful mechanism to automatically parse incoming request data, such as query parameters, JSON bodies, or headers, into typed Rust structs. They improve type safety and reduce boilerplate code by validating input before the handler is even executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fa098ef-ae72-4b4d-ab86-46ec4799141e', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is it important to use HTTPS instead of HTTP for a web application?', N'Fresher', N'HTTPS encrypts the data transmitted between the user''s browser and the server, protecting sensitive information like passwords or personal details from being intercepted. It also ensures data integrity and confirms the authenticity of the website.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ce38111-7456-46d9-87a9-46f0334b6eb8', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How do you optimize performance in a NestJS application under high load?', N'Middle', N'Optimization involves minimizing request-scoped services, utilizing efficient caching strategies, and offloading heavy tasks to background workers. Additionally, ensuring proper use of fastify instead of express can provide a measurable boost in throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c06a34a-deb2-4950-94f1-46f2dcde6925', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does asynchronous programming work in Dart?', N'Fresher', N'Dart uses the Future and Stream classes to handle asynchronous operations. By using the ''async'' and ''await'' keywords, developers can write non-blocking code that reads similarly to synchronous code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44b923c5-504d-48d2-85ce-46f688a0928b', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the ''Read Repair'' mechanism?', N'Junior', N'Read repair is a process where Cassandra checks multiple replicas during a read operation to see if they contain different versions of the data. If inconsistencies are found, the database automatically updates the outdated replicas with the latest data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5712b45-abbe-4aa5-a916-46f8c17f7ec4', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the architectural purpose of a Web Application Firewall (WAF) compared to an API Gateway?', N'Senior', N'A WAF focuses on filtering Layer 7 traffic to block common web attacks like SQL injection and cross-site scripting based on patterns and signatures. An API Gateway focuses on traffic management, service routing, and identity verification, serving as an orchestration layer rather than a pure security filtering layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'514fa6b4-6e42-4391-8f59-46f99e3d156b', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is a Controller Action?', N'Intern', N'A controller action is a specific method defined within a controller class that corresponds to a particular route. Its primary responsibility is to retrieve data from the model and prepare it for the view, or to trigger a change in the model based on user input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad67ca9b-f6b9-4add-ae06-46f99fc2dc66', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach debugging a legacy system that lacks documentation?', N'Junior', N'I would start by exploring the codebase to understand the flow of data and use existing logs or debugging tools to observe its runtime behavior. I would also look for existing tests to see how the system is intended to function and verify my assumptions about the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73952551-ed1c-49a5-a9fe-46fd53bc4f4e', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is a named slot?', N'Junior', N'A named slot allows a parent component to inject content into multiple specific locations within a child component. You define the slot with a name attribute and reference it in the parent using the slot attribute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ea4b843-8426-421a-921e-46fe9cea3096', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the function of a +page.js or +page.server.js file?', N'Intern', N'These files are used to load data for a specific page before it is rendered. The +page.js file runs on both the server and client, while +page.server.js runs exclusively on the server, which is useful for secure database operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03133a37-c217-4363-a034-47061137377a', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How to use data- attribute in html5?', N'Fresher', N'Any attribute on any element whose attribute name starts with data- is a data attribute. The data-* attributes gives us the ability to embed custom data attributes on all HTML elements. The stored (custom) data can then be used in the page''s JavaScript to create a more engaging user experience. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72635a78-f3c8-47dd-b493-4707a6d4ac15', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you handle the trade-offs between security and usability in an authentication system?', N'Senior', N'I balance security by implementing multi-factor authentication and strict token expiration while optimizing usability through features like single sign-on and seamless session persistence. The goal is to enforce high-security standards that are transparent to the user, ensuring that security is an enabler rather than an obstacle to productivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4c14832-ce6b-4038-94ea-4708dd0b0394', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the purpose of the ''MethodRouter'' in Axum?', N'Middle', N'The MethodRouter allows you to map different HTTP methods to different handlers for the same URL path. It provides a clean, declarative way to define RESTful APIs where a single endpoint might support GET, POST, and DELETE operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea93ec19-4d0f-405a-9e14-4709e782b36b', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is an abstract class?', N'Junior', N'An abstract class is a class that contains at least one pure virtual function, making it impossible to instantiate directly. It serves as a blueprint for derived classes, enforcing that they implement specific behaviors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd43a169f-3dea-415a-9637-470cb6bbb08f', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does Rails middleware stack affect request throughput and latency?', N'Senior', N'The middleware stack processes every incoming request before it reaches the router. A deep or inefficient stack increases the latency for every request; therefore, it is vital to keep custom middleware lightweight and minimize unnecessary chains to maintain high throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c864f6f9-3f59-4c32-8037-470ef09fc63a', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a row-level lock and a table-level lock?', N'Junior', N'A row-level lock restricts access to only a specific record, allowing other users to read or modify different rows in the same table. A table-level lock restricts access to the entire table, preventing other users from performing operations on it until the lock is released.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
