INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b90a599e-b51f-4ef3-b747-471512f80b27', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach designing a system for high write throughput where traditional relational database locking becomes a contention point?', N'Senior', N'I would evaluate moving to a sharded architecture or adopting a NoSQL solution that supports optimized write paths, such as LSM trees. Additionally, I would consider implementing an event-driven ingestion layer using a distributed log to decouple the write acceptance from the underlying data persistence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
