INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e9e9a6a-32d1-424e-9705-4715ccd8e1ff', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the main purpose of using TypeScript instead of plain JavaScript in a frontend project?', N'Junior', N'TypeScript adds static typing to JavaScript, which allows developers to define the shapes of objects and the expected types of function arguments. This helps catch potential errors during development rather than at runtime, leading to more predictable code and better IDE autocompletion. It essentially acts as a documentation layer that ensures your data structures remain consistent throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
