INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eda140bd-a160-45df-90e5-473023418e7e', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle request body streaming, and when is this necessary?', N'Senior', N'FastAPI can process request bodies as streams, which is critical for handling large file uploads. By consuming the stream iteratively, the framework avoids loading the entire payload into RAM, preventing Out-Of-Memory errors in resource-constrained environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c486b86f-6349-4be4-ae98-473077245f78', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the difference between a Database Transaction and a standard query?', N'Junior', N'A database transaction ensures that a set of queries are treated as a single unit of work. If any part of the transaction fails, the entire set is rolled back, ensuring the database remains in a consistent state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e065fedc-8e60-4da5-a5fc-473174761cf2', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the function of the body-parser in Express?', N'Fresher', N'Body-parser is middleware that parses incoming request bodies in a middleware before your handlers. It makes the data available under the req.body property, which is essential for processing JSON, raw, text, or URL-encoded form data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'880f3469-e69f-451b-a3a7-4732b07001a0', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the purpose of the Qwik Optimizer?', N'Intern', N'The Qwik Optimizer is a build-time tool that automatically breaks the application code into small, lazy-loadable chunks. This process creates the foundation for the framework to only load the specific code required for a user''s action.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd10df967-41ac-4b46-bb8b-47331af6807b', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Describe the ''Atomicity'' property and its role in failure recovery.', N'Middle', N'Atomicity guarantees that all operations within a transaction are completed successfully, or none of them are. If a system failure occurs mid-transaction, the database uses undo logs to roll back any partial changes, ensuring the database never remains in a partially updated state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de27eee5-57b0-4789-9fd7-4737115ce77e', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the mechanism and limitations of Template Metaprogramming (TMP).', N'Senior', N'TMP uses the C++ template system as a Turing-complete functional language evaluated at compile time to generate code or perform complex computations. Its main limitations include long compilation times, highly complex error messages that are difficult to interpret, and the tendency to produce excessive template instantiations that can lead to binary bloat.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0620f47-402c-4ded-9ece-473a255f285c', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the primary architectural benefit of using Echo''s Middleware chain?', N'Middle', N'Echo''s middleware allows for the modular execution of cross-cutting concerns like logging, authentication, and error handling before or after the main request handler. By chaining these components, you maintain a clean separation of concerns and ensure that common logic is reused consistently across different routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02cdc658-3502-42a0-bc5d-473b0287ab4c', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What happens if Webpack encounters a file type it does not know how to handle?', N'Intern', N'If no loader is configured for a specific file type, Webpack will throw an error during the build process. You must explicitly tell Webpack how to process that file by installing and configuring a corresponding loader.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46c834e9-1363-4d19-9291-473b88d71ab9', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the ''APIRouter'' class used for?', N'Fresher', N'The ''APIRouter'' class is used to group related path operations together. It helps in organizing the application code by allowing you to define routes in multiple files and then include them in the main application instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d0cc041-8137-4b32-b0c5-473c632f440f', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the concept of ''defer'' in Swift.', N'Fresher', N'The defer statement is used to execute a set of statements just before the current scope is exited, regardless of how the execution leaves the scope. It is commonly used for cleanup tasks like closing files or releasing resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86fe5273-06d9-4d21-aa26-473cf951a2fb', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Describe the concept of ''Eventual Consistency'' in the context of Cassandra.', N'Middle', N'Eventual consistency means that given a period without new updates, all accesses to a specific data item will return the last updated value. In Cassandra, this is managed by configurable consistency levels, allowing developers to trade off between latency and immediate data accuracy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e70e2bd6-dfa7-4c23-9a4a-473d9d2a1a83', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Why does Dart prioritize immutability in its state management philosophy?', N'Senior', N'Immutability simplifies state tracking by ensuring that objects cannot change after creation, which prevents side effects and makes code more predictable. This approach is critical for high-performance UI frameworks where comparing object references is significantly faster than performing deep equality checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39138081-a851-4bf2-9301-473fefab5520', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does ''Quorum-based'' replication ensure consistency in distributed systems?', N'Senior', N'Quorum-based replication defines a read quorum (R) and a write quorum (W) such that R + W > N, where N is the total number of replicas. This mathematical overlap ensures that at least one node in any read operation will contain the most recent write, providing a tunable balance between consistency and availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81e7983f-34be-4e9c-8a40-474062bcb206', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do you handle form data in Lit?', N'Junior', N'Form data is handled by binding component properties to input elements using event listeners. You listen for the input event to update the component''s reactive state whenever the user types or changes a value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'728f2483-04ed-480a-bb32-4740723bb168', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the concept of ''Transaction ID Wraparound'' and how PostgreSQL mitigates this risk.', N'Senior', N'PostgreSQL uses 32-bit transaction IDs that eventually cycle; if they wrap around, the database will treat old data as being in the future. PostgreSQL prevents this by forcing vacuuming on tables that have not been vacuumed for a certain number of transactions to ensure ID freezing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8e0d6c7-37a2-4c4e-9d4c-47416b0767c8', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How do you handle ''Cold Starts'' in a system that relies heavily on a distributed cache?', N'Senior', N'Cold starts can be mitigated by implementing tiered caching, where a local node cache serves requests while the distributed cache is warming up. Additionally, gradual traffic steering (canary deployments) allows the system to build its cache state organically without overwhelming backend resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6915087d-266b-43a7-b6c0-4741b4886776', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the purpose of a post-mortem or retrospective meeting after a project is finished?', N'Intern', N'The purpose is to reflect on what went well and what could be improved in future projects. It helps the team document lessons learned and implement better processes to increase efficiency and avoid repeating past mistakes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23a93017-a502-47ea-ad06-47438b1ecfea', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between an extension and a library in Flask?', N'Intern', N'In the context of Flask, an extension is a library specifically designed to integrate with Flask to add missing functionality, such as database support or authentication. A general library can be used in any Python application regardless of the framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06e913ee-2252-4837-ae42-4744bde6b397', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'When designing an API, how do you determine if a field should be represented as a sub-resource or a query parameter?', N'Senior', N'Sub-resources are appropriate when the entity has its own identity, lifecycle, or requires specific access controls. Query parameters are better for filtering, sorting, or modifying the representation of a primary resource without defining a new URI structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e5acefe-fdb8-4e3b-b842-474a35da5391', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a system for high availability, what should you keep in mind regarding dependencies?', N'Junior', N'You should design for fault tolerance by minimizing single points of failure and ensuring that services can degrade gracefully if a dependency fails. This includes implementing retries with exponential backoff and using timeouts to ensure that one slow dependency doesn''t consume all available resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b52e081-fc3a-4e57-abdc-474b67404e21', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is meant by data redundancy?', N'Junior', N'Data redundancy occurs when the same piece of information is stored in two or more separate places within a database. This can lead to data inconsistencies and wasted storage space, which is why normalization is important.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b01f6901-3263-4c5b-8df0-474bed9b446f', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is a protocol in Swift?', N'Intern', N'A protocol defines a blueprint of methods, properties, or other requirements that a class, struct, or enum must implement. It allows for a flexible design where different types can conform to the same set of rules without sharing a common base class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f645723e-a509-45c5-bddc-474c540e13b5', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are the performance implications of using Django''s template language versus returning JSON from an API?', N'Middle', N'Django templates are rendered server-side, which can increase CPU load on the web server and lead to a tighter coupling between the backend and frontend. Returning JSON decouples the backend, allows for client-side rendering, and is generally more efficient for high-scale APIs, though it requires a separate frontend framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31214758-1666-44cc-86ca-474ec0c34050', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the benefit of using modular routes in Express?', N'Intern', N'Modular routes prevent a single file from becoming too large and difficult to read. By separating concerns into different files using the Express Router, teams can manage and scale the codebase more effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b847d71f-73a3-4310-b13d-4752962e37f5', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS handle database interactions, and what are the supported databases?', N'Fresher', N'NestJS doesn''t directly handle database interactions. Instead, it provides integration with several libraries that do, allowing you to choose the one that best fits your needs. Here are some of the most commonly used ones: TypeORM: This is an Object-Relational Mapping (ORM) library that can be used with a wide variety of databases, including MySQL, PostgreSQL, MongoDB, SQLite, and more. It provides a high-level API for managing database records as JavaScript objects. Mongoose: If you''re working with MongoDB, Mongoose is a great choice. It provides a straight-forward, schema-based solution to model your application data and includes built-in type casting, validation, query building, and business logic hooks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd760101e-9d10-403a-aaaa-475392674e23', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why is it generally faster to use Fastify''s native reply.send() versus returning a raw stream?', N'Middle', N'Fastify''s internal serialization engine optimizes the transformation of objects into JSON strings. By using reply.send(), you allow Fastify to handle content-type detection and serialization efficiently, whereas raw streams bypass these optimizations and require manual header management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b66ea8aa-fc15-4181-a3a0-47548b479b2a', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the concept of ''Write Amplification'' in database storage engines.', N'Senior', N'Write amplification occurs when the physical amount of data written to the storage medium is greater than the logical amount of data requested by the application. This is common in LSM-tree engines due to background compaction and in systems with heavy secondary indexing, where a single insert results in multiple disk writes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36367fc7-00ff-4976-8f42-47563b39591d', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the role of a Transaction Manager in a database architecture?', N'Senior', N'The Transaction Manager coordinates the initiation, execution, and conclusion of transactions, ensuring they adhere to ACID properties. It manages locking, timestamping, and interaction with the recovery manager to maintain consistency and isolation throughout the transaction lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69e15698-6d35-42f1-aba7-47581460089c', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the Rails router?', N'Intern', N'The router recognizes incoming URLs and dispatches them to the appropriate controller action. It acts as the traffic controller of the application, mapping web requests to specific logic defined within the controllers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e64a42c-142d-4f3c-a51f-475b423f397f', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does NoSQL handle unstructured data?', N'Intern', N'NoSQL databases handle unstructured data by not enforcing a rigid structure during the write process. Since they don''t require tables with predefined columns, they can store varied types of information like logs, social media posts, or sensor data in its raw format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4b06c2e-5532-4cc6-881f-475bc8723ce2', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you handle ''Database Refactoring'' when a service is owned by a single team?', N'Senior', N'Since the database schema is encapsulated within the service, refactoring is generally safer than in a monolith. You use standard migration versioning tools to evolve the schema, and if breaking changes are required, you must implement them in phases that support both the old and new schema versions concurrently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61a4d3f9-265a-440e-85f6-4760c3aa924d', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What does it mean that Node.js is single-threaded?', N'Intern', N'Being single-threaded means that Node.js runs all JavaScript code on one main thread. Instead of spawning new threads for every request, it handles operations using an event loop, which prevents the overhead of multi-threaded context switching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a49e094-fd4e-4afb-be12-47656db031da', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the benefit of using @ConfigurationProperties over @Value?', N'Senior', N'@ConfigurationProperties allows for hierarchical, type-safe configuration binding to POJOs, supporting complex structures like lists and maps. @Value is limited to injecting individual fields and lacks the validation and grouping capabilities provided by the binding mechanism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'043ed51a-55a1-44d1-bfb6-47660f9d47d3', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Explain the risk of ''dependency bloat'' in a Webpack build.', N'Senior', N'Dependency bloat occurs when large, unnecessary libraries or multiple versions of the same library are included in the bundle, increasing load times and memory usage. This is often mitigated by using bundle analysis tools to identify large modules and enforcing strict dependency management via resolutions or alias mapping.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ed5e184-ef6c-429f-b7c1-476e326b2e0a', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does the ''Application Factory'' pattern facilitate testing and scalability in a large Flask codebase?', N'Senior', N'The factory pattern prevents the creation of a global application instance at import time, allowing for dynamic configuration injection for different environments like testing, staging, and production. This decoupling makes it trivial to spin up isolated app instances in test suites, avoiding the side effects associated with singleton-style global state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d161ccf-3cd1-4052-acd4-476f2b3d633c', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you approach learning a new technology required for a project?', N'Fresher', N'I would start by reading the official documentation to understand the core concepts and use cases. Then, I would build a small, simple project to gain hands-on experience and seek out tutorials or community resources to address specific challenges.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d0d7c03-8878-46ba-a523-476fe3db3d05', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are the advantages and disadvantages of using PHP traits for code reuse?', N'Middle', N'Traits allow developers to reuse sets of methods across different classes without the limitations of single inheritance. However, they can lead to complex dependency graphs, potential naming conflicts, and reduced readability if overused to bypass proper class composition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a34b557f-4c26-4e1f-94ae-477a730aa31b', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you determine the priority of a bug you are troubleshooting?', N'Intern', N'Priority is determined by the severity of the impact on users, the number of people affected, and whether a workaround exists. High-priority issues are those that cause critical system failures or significant data loss.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f253f85c-d8e6-4d2e-95cb-477ebc8130f3', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How do you handle relationships in a document database?', N'Junior', N'Relationships in document databases are often handled through embedding or referencing. Embedding places related data directly inside the document, while referencing stores the ID of a related document to be fetched separately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
