INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfcc0373-91dc-4368-b1a0-47822a2a7f87', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why are ''keyword'' and ''text'' types treated differently in the inverted index?', N'Senior', N'Text fields are analyzed, meaning the content is tokenized and normalized into individual terms to support full-text search. Keyword fields are not analyzed, storing the entire value as a single term, which makes them ideal for exact matching, sorting, and aggregations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
