INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61f3df1d-a072-4752-82ed-4784562120bb', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the common challenges of maintaining referential integrity in a distributed database?', N'Middle', N'In distributed systems, checking foreign key constraints across different nodes requires expensive cross-node communication or global locks. Most distributed databases trade off strict referential integrity for higher performance, shifting the responsibility of data consistency to the application layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'527bb551-3a4f-44de-a011-4784d914acc6', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the benefit of using ''x-transition'' over CSS-only transitions?', N'Middle', N'x-transition provides a declarative way to handle complex enter and leave animations that are tied to component lifecycle events. It makes it easier to synchronize animations with conditional rendering, ensuring that elements fade or slide correctly during the mounting and unmounting processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac45d8f2-f1fa-4f9f-ad3e-478576286c91', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle navigation state management compared to traditional Single Page Applications (SPAs)?', N'Senior', N'SvelteKit utilizes a built-in router that manages history state and prefetching automatically, reducing the need for external state management libraries. It treats navigation as a progressive enhancement, allowing the app to function as a multi-page application if JavaScript fails while providing a smooth SPA experience during normal operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a97d7497-0cc3-4650-a538-4785da98fbad', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you estimate the impact of introducing a new third-party dependency into your system?', N'Middle', N'I would evaluate the dependency based on its maintenance activity, documentation quality, and performance overhead, while considering the integration complexity. I would estimate the effort by simulating the ''worst-case'' scenario, such as the dependency failing or requiring a significant API migration, to ensure the team can handle the long-term support burden.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd384356-43a6-4d84-87e2-4788600f70f2', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is difference between span tag and div tag?', N'Fresher', N'The primary difference between div and span tag is their default behavior. By default, a is a block-level-element and a is an inline element. * is a block level element which means it will render it on it''s own line with a width of a 100% of the parent element. * is an inline element which means it will render on the same line as the previous element, if it is also an inline element, and it''s width will be determined by it''s content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'187fcb8e-8d9c-469d-9254-4788911a513c', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Explain the architectural difference between Gin''s engine and the standard net/http server.', N'Senior', N'Gin''s engine acts as a high-level wrapper that implements the http.Handler interface, meaning it is compatible with the standard library''s server. The primary difference is the added layer of abstraction for context management, routing, and a structured middleware pipeline that the standard library lacks by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f92f456-9ca1-4c75-b5ff-4788fb3acb2b', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix ensure thread safety without relying heavily on mutexes?', N'Middle', N'Actix relies on the Actor model''s principle of message passing and ownership. By isolating state within an actor and having messages delivered sequentially to its mailbox, it eliminates the need for complex locking mechanisms, as only one thread ever modifies the actor''s state at a time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b0bfde0-6105-4e78-931d-4789a5bf40fb', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the benefit of using ''relative estimation'' instead of absolute time-based estimation?', N'Fresher', N'Relative estimation focuses on comparing the size or complexity of tasks against each other, which is often easier for humans than guessing exact hours. It helps avoid the pressure of specific deadlines early on and encourages team consensus on the effort required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73a2f0c6-9a9b-40a7-bf3f-478a7caff1e0', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django handle database migrations, and how do you manage them in a CI/CD pipeline without causing downtime?', N'Senior', N'Migrations track schema changes via a history table, but they can lock tables during execution, causing outages. Best practices include splitting migrations into additive and destructive phases and using tools to perform non-blocking operations like adding columns with default values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
