INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc1726ad-2d2c-45eb-980b-478e4e863cc6', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you design for observability in a complex distributed system?', N'Senior', N'I prioritize structured logging, distributed tracing, and high-cardinality metrics to ensure full-stack visibility. By implementing trace propagation headers across all service boundaries and establishing clear alerting thresholds, we can correlate failures across systems and significantly reduce the mean time to recovery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c838f2fc-1436-47fe-a47d-478f7ae7fad8', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the purpose of data visualization in R?', N'Intern', N'Data visualization in R involves using built-in or external graphical tools to create plots, charts, and maps. Its primary purpose is to explore patterns, identify trends, and communicate statistical findings effectively through visual representations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee59b790-59d6-4142-b1b2-4792c9942e9e', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Why is it generally recommended to avoid using SELECT * in production queries?', N'Junior', N'Using SELECT * retrieves all columns from a table, which increases network traffic and memory usage if the table contains many or large columns. It also creates a tight dependency on the table schema, meaning any change to the table structure can inadvertently break the application logic that expects specific columns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20bbc432-59b8-444e-b6f8-4793920ca938', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain the concept of ''Secret Management'' in a DevOps pipeline.', N'Middle', N'Secret management involves the secure storage, access, and rotation of sensitive credentials like database passwords and API keys. Using a dedicated secret manager avoids storing these credentials in plaintext configuration files or environment variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89011cc8-0423-4039-9157-4794895d7d0d', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the significance of the ''volatile'' keyword?', N'Junior', N'The volatile keyword ensures that changes to a variable are immediately visible to all threads. It prevents threads from caching the variable value in local memory, ensuring that every read or write operation occurs directly in main memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aac06e47-5b70-493b-9ee1-4795072cee5c', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are Nuxt ''components'' and how do they differ from pages?', N'Fresher', N'Components are small, reusable pieces of UI that can be imported into pages or other components. While pages represent unique routes, components represent building blocks like buttons, cards, or navigation bars.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58ae60ef-6b34-4490-be20-47959b6d61ad', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you handle the trade-offs between optimizing for developer experience (DX) and system performance?', N'Senior', N'I prioritize DX during the early stages of a product to facilitate rapid learning and iteration. As the system matures and reaches scale, I shift focus toward performance optimization, implementing more rigorous abstractions and lower-level code paths only where performance metrics justify the increased development effort.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
