INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1d20e72-543d-4014-886b-479f8eaa8f21', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does C handle signal handling and its impact on async-signal safety?', N'Senior', N'Signal handlers interrupt the normal flow of execution, meaning they must be written to be async-signal safe to avoid deadlocks or data corruption. Only a small subset of library functions are guaranteed to be safe to call from within a signal handler, as most functions rely on shared global state or non-reentrant logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ce8e0dd-2eaa-4275-86e8-47a20115e4e1', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the security value of adopting an Immutable Infrastructure pattern?', N'Senior', N'Immutable infrastructure prevents configuration drift by replacing rather than patching existing components, which ensures that security patches and hardened images are applied consistently. This approach limits the persistence of an attacker because compromised instances are destroyed and replaced by known-good, hardened states on a regular basis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5aac165d-17a3-4248-ba52-47a31f466e94', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between persistent and volatile storage in the context of databases?', N'Junior', N'Persistent storage refers to non-volatile media like hard drives or SSDs where data remains even after the system is powered off. Volatile storage, such as RAM, is used by the database engine for caching and processing to improve speed, but data is lost if the system shuts down.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79f013f0-b190-4b32-ae9e-47a4738f97d4', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you mitigate the ''N+1 query problem'' in API design?', N'Senior', N'Implement data loaders or batching utilities that aggregate multiple data requests into a single database query. Alternatively, design the API to support resource expansion via query parameters, allowing the server to join related data in a single retrieval operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
