INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c54fddbd-6d96-48a3-9316-47b6a4e0fae8', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do Sass mixins differ from placeholders in terms of the generated CSS output?', N'Senior', N'Mixins copy the defined styles into every location where they are included, which can lead to redundant CSS code if used extensively. Placeholders, when used with the extend directive, group selectors together to share the same rule block, resulting in a more efficient and cleaner stylesheet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94815c7a-22f3-47ca-9913-47b906b32bda', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the role of a database management system (DBMS)?', N'Intern', N'A DBMS is software that acts as an interface between the user and the database. It manages data storage, security, concurrency, and retrieval, allowing users to interact with data without needing to know how it is physically stored.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1464fe73-9f67-4f32-b062-47b980ed9ac4', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why would you choose to use a CDN (Content Delivery Network) for your web application?', N'Junior', N'A CDN caches static assets like images, CSS, and JavaScript files on servers geographically closer to the end user. This significantly reduces latency and lowers bandwidth costs by offloading traffic from your origin server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5265903-9f20-4227-99e1-47b9a33da934', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is the jQuery plugin ecosystem considered a liability for security audits?', N'Senior', N'The jQuery ecosystem is vast and largely unmaintained, making it a prime vector for supply chain attacks or legacy vulnerabilities. Because these plugins are often included as separate scripts, they lack the rigorous dependency auditing and automated security scanning available in modern package managers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17aec234-904d-4407-951b-47b9a974c962', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using a REST API or GraphQL for a new frontend feature?', N'Junior', N'REST is generally simpler to implement and uses standard caching mechanisms, making it great for straightforward resources. GraphQL is preferred if the frontend requires specific fields from multiple related resources, as it minimizes over-fetching and reduces the number of network requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
