INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35dad478-9cba-4a46-825c-47ecce25be15', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the purpose of the ''Streaming'' feature in Next.js, and how does it improve Core Web Vitals?', N'Senior', N'Streaming allows the server to send the initial page shell immediately while the rest of the content is fetched and streamed in chunks. This drastically improves the First Contentful Paint (FCP) and Time to Interactive (TTI) by preventing the browser from waiting for all data to be ready before showing UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
