INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff15df8f-82e0-4ade-b555-47ef91025214', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What information should be included in a bug report to help a developer?', N'Junior', N'A good bug report should include a clear summary, steps to reproduce the issue, the expected versus actual behavior, and environmental details like the OS or browser version. Providing this context allows the developer to immediately begin investigating rather than spending time gathering missing information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c78ea79-1390-491f-b859-47f1228fe8df', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the examples of built-in higher order functions?', N'Intern', N'There are several built-in higher order functions exists on arrays, strings, DOM and promise methods in javascript. These higher order functions provides significant level of abstraction. The list of functions on these categories are listed below, 1. arrays: map, filter, reduce, sort, forEach, some etc. 2. DOM: The DOM method element.addEventListener(type, handler) also accepts the function handler as a second argument. 3. Strings: replace() method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c829c05-16d4-41ea-a5e1-47f71fa26fc4', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the function of the LIKE operator?', N'Fresher', N'The LIKE operator is used in a WHERE clause to search for a specified pattern in a column. It often uses wildcards such as percent signs to represent missing characters or substrings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ff3b7f5-3685-4250-bab4-47fa2532a52c', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are the architectural implications of using the ''express-session'' middleware with a default configuration in a production environment?', N'Senior', N'The default MemoryStore is not designed for production as it does not persist data across restarts and lacks the performance capabilities of external stores like Redis. Furthermore, it lacks proper security headers and secure cookie configurations, exposing the application to session hijacking and memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9da9dfe5-9279-4cbe-8c4b-48037847246e', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the MySQL engine?', N'Fresher', N'A storage engine is the software component that a database management system uses to create, read, update, and delete data from a database. MySQL supports multiple engines like InnoDB, which supports transactions, and MyISAM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
