INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9049766f-0170-476d-8a6e-48055953332a', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Explain the concept of ''bindings'' in Hono within the context of Cloudflare Workers.', N'Junior', N'Bindings are variables or services like Key-Value stores or D1 databases that are injected into the Hono application by the runtime. Hono makes these available via the context, allowing the code to interact with platform-specific infrastructure easily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c77198ea-4d0f-4dae-af2f-4805e2a3b0eb', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the concept of Escape Analysis and its role in scalar replacement within the JVM.', N'Senior', N'Escape analysis determines if an object is accessible outside the scope of its creation method. If the object does not escape, the JVM can perform scalar replacement, breaking the object into its individual fields and potentially allocating them on the stack or in registers, significantly reducing heap pressure and GC overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
