INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00cad0b4-036f-432f-8ca1-480dc968a0f9', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix''s ''Plugs'' architecture compare to middleware patterns in other frameworks like Express or Django?', N'Senior', N'Plugs follow a functional composition pattern where each plug is a simple function receiving a connection struct, transforming it, and returning it. Unlike class-based middleware, this functional approach makes the pipeline highly transparent, composable, and easier to test in isolation without hidden shared state or complex inheritance chains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd98be0f4-9e78-465c-989a-480e64832a58', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What are the advantages and disadvantages of using a stateless API?', N'Middle', N'Stateless APIs do not store client context between requests, which makes the system easier to scale horizontally since any request can be handled by any server instance. The downside is that the client must send authentication or state information with every request, slightly increasing payload size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eba7ecd2-aaf9-42ab-a273-48143f67c8f7', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of middleware in an Express application?', N'Junior', N'Middleware functions are functions that have access to the request object, the response object, and the next middleware function in the application''s request-response cycle. They are used to execute code, make changes to the request and response objects, end the request-response cycle, or call the next middleware in the stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
