INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31c65bf0-4cde-4d59-ac2d-4819b478167b', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the primary differences between SQL and NoSQL databases like DynamoDB?', N'Fresher', N'SQL databases are relational and use structured tables with fixed schemas, while NoSQL databases like DynamoDB are non-relational and offer flexible schemas. NoSQL databases are typically optimized for specific data models and horizontal scaling, whereas SQL databases focus on complex queries and data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f26a0163-71b9-4df0-baba-481a2f12b593', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the difference between an interface and an abstract class in Dart.', N'Junior', N'In Dart, there is no explicit interface keyword; every class implicitly defines an interface. An abstract class is a class that cannot be instantiated and can contain both abstract methods and implemented logic, whereas an interface forces the implementing class to provide its own implementation for every member.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2468d40b-e06d-4432-be1e-481afb57f7f8', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the primary trade-off of Go''s garbage collection strategy?', N'Middle', N'Go''s garbage collector is designed for low latency rather than high throughput. By prioritizing short stop-the-world pauses, it ensures consistent performance, but this comes at the cost of higher CPU overhead and potentially larger memory usage compared to generational collectors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
