INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e48c686-e96f-4ce2-a791-481db0a077b7', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Explain the interaction between lifetime elision and function signatures.', N'Senior', N'Lifetime elision is a set of rules that allow the compiler to infer lifetimes in function signatures when they are unambiguous. While it reduces boilerplate, it can hide underlying complexity, and developers must explicitly annotate lifetimes when the compiler cannot determine the relationship between inputs and outputs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03135429-e1dc-4dc7-a22b-481e3da394f1', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the ''inverted index'' structure facilitate efficient full-text search?', N'Senior', N'An inverted index maps terms to a list of documents where they appear, allowing the engine to quickly locate records containing specific words. This eliminates the need to scan every document, drastically reducing search time for full-text queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
