INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f897cb06-8d2c-49a8-998b-4822bfccc9af', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the AdonisJS ''env'' file used for?', N'Intern', N'The .env file is used to store environment-specific configuration variables, such as database credentials, API keys, and application secrets. This keeps sensitive information out of the source code and allows for different configurations in development and production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f075b6f6-02b4-4378-8c64-48248bf75495', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro''s ''server-side islands'' pattern differ from traditional client-side data fetching?', N'Senior', N'Server-side islands fetch data and render HTML on the server before sending it to the client, effectively streaming the content. This avoids the ''loading spinner'' pattern common in client-side data fetching, as the content is delivered to the browser already populated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea315b98-9bd6-4919-ab18-4825c87556a8', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle DOM lifecycle events compared to a Virtual DOM-based framework?', N'Senior', N'Alpine does not have a virtual DOM reconciliation process; instead, it directly manipulates the existing DOM nodes based on directive changes. It relies on standard browser events and MutationObservers to react to changes, which provides high performance for document-centric interactions but can be less efficient for massive, frequently changing datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bde73eab-d3cb-458c-8a3f-482601b2f492', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the benefit of using an ''AsyncPipe'' in templates?', N'Middle', N'The AsyncPipe automatically subscribes to an observable or promise and returns the latest value to the template. It also handles automatic unsubscription when the component is destroyed, reducing boilerplate code and preventing potential memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4377852-fb97-43d6-bd97-4828b6e51bb5', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How do you ensure data integrity in a distributed Laravel application when handling scheduled tasks (Cron)?', N'Senior', N'When running multiple instances, you must use ''onOneServer'' task scheduling to ensure that the cron job executes only once across the entire cluster. Otherwise, you risk duplicate executions, which can lead to data corruption or double-billing if the task performs stateful operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b8c67ee-a44c-4744-9459-48299eb6f274', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the architectural implications of using Laravel''s Queue system with different drivers (e.g., Redis vs. SQS) regarding consistency and delivery guarantees.', N'Senior', N'Redis offers low-latency, high-throughput execution but is prone to data loss if the server crashes before persistence, whereas SQS provides distributed reliability and at-least-once delivery guarantees. Architects must choose based on whether the application requires strict message durability or high-performance asynchronous processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7235378-f364-486a-a9f4-482a3ec69a10', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Describe the function of the Quarkus Dev Services.', N'Senior', N'Dev Services automatically provision and configure necessary infrastructure, such as databases or message brokers, using Testcontainers during development mode. This eliminates manual setup of local environments, allowing developers to focus on business logic while maintaining parity with the production stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
