INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86d8465a-eac7-4505-bb0a-484670aa2036', N'4c000000-0000-0000-0000-000000000005', N'How do you perform a rolling update in a production environment?', N'Middle', N'A rolling update replaces instances of the old service version with the new version one by one. This ensures zero downtime, as the load balancer routes traffic only to updated instances, and allows for an easy rollback if errors are detected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e32fa8c-8f29-411b-a740-48468aee5266', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the relationship between transactions and the database state?', N'Junior', N'Transactions act as transitions between valid database states. By enforcing ACID properties, the database ensures that it never enters an invalid or corrupted state due to partial updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'228316e6-71d5-4408-abd5-484bbe1c4f2f', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How do you achieve ACID transactions in DynamoDB?', N'Junior', N'DynamoDB supports transactions through operations like TransactWriteItems and TransactGetItems. These ensure that multiple operations either all succeed or all fail, maintaining data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adb48c0e-9553-47da-a268-484bec5864a9', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why is it important to treat the state as immutable in Redux?', N'Junior', N'Treating the state as immutable ensures that the application remains predictable and allows Redux to easily track changes. By creating new state objects instead of modifying existing ones, tools like time-travel debugging work correctly and components can efficiently determine if they need to re-render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2b0e47a-6ad6-4b37-9467-484d354286d1', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the function of the Bloom Filter in Cassandra?', N'Middle', N'The Bloom Filter is an off-heap data structure used to quickly determine if a specific row exists in an SSTable. It helps avoid unnecessary disk reads by skipping SSTables that definitely do not contain the requested data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'604339b5-7a91-4623-9686-484ff30bb8fd', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does ''Multi-version Concurrency Control'' (MVCC) operate in document databases?', N'Senior', N'MVCC allows multiple versions of a document to exist simultaneously, with each transaction assigned a timestamp or version ID. This enables readers to access a consistent snapshot of the data without being blocked by concurrent writers, drastically improving system concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bb596e1-add6-4f71-8f08-4850677b6cc0', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Why should the ''equals'' and ''hashCode'' methods be overridden together?', N'Middle', N'The Java contract requires that if two objects are equal according to the equals method, they must return the same integer result from hashCode. If this contract is broken, collections like HashMap will fail to locate objects correctly because they rely on the hash code to determine bucket placement. Overriding both ensures consistent behavior in hash-based data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a297720-b512-49a3-b975-4852b46762cb', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the jQuery ''deferred'' object and how does it relate to Promises?', N'Middle', N'The deferred object is jQuery''s historical implementation of the Promises/A+ specification used to handle asynchronous operations. While it provided a way to manage callbacks before native Promises existed, it is now considered legacy and should be replaced by native Promise or async/await syntax in modern projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a39bcd6-b828-49ef-bb61-48550d027b3b', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why might you prefer Rocket over Axum for a project?', N'Middle', N'Rocket is often preferred for its ease of use, extensive documentation, and ''batteries-included'' philosophy that minimizes boilerplate. Axum is more modular and provides greater flexibility, but Rocket is generally faster for rapid development of standard RESTful APIs due to its integrated feature set.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fd5992f-d7d5-43e1-9555-4855b29978d4', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain the significance of the Will-Change property and its potential for misuse.', N'Senior', N'The will-change property promotes an element to a new compositor layer by informing the browser of upcoming changes. While it improves animation smoothness, overuse causes excessive memory consumption by keeping too many layers in GPU memory, which can lead to browser crashes or performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95b6a704-f6d7-495b-86b5-4857b49eb1e3', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How do you handle background tasks in a Litestar environment?', N'Middle', N'Background tasks should be handled by offloading work to an external task queue like Celery or Dramatiq. While Litestar can run lightweight tasks in the background, offloading ensures the main event loop remains responsive to incoming traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbe97f75-25ae-4ad1-a3eb-485b55078a07', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Compare the cache locality benefits of Data Oriented Design versus Object Oriented Design in C++.', N'Senior', N'Object Oriented Design often leads to fragmented memory layouts due to pointer chasing and polymorphic object hierarchies, which hurt cache locality. Data Oriented Design organizes data into contiguous arrays of structures or structures of arrays, significantly improving cache hit rates by aligning with the CPU''s prefetcher and reducing the number of cache misses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b98059f4-5657-464b-9fd7-485c1e0f5ae3', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What does it mean to ''reproduce a bug,'' and why is it the most important step in troubleshooting?', N'Junior', N'Reproducing a bug means finding a reliable set of steps that cause the error to occur every time. It is crucial because you cannot verify if a fix is successful unless you can reliably trigger the failure and confirm that the fix prevents it from happening.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d40340b-6380-4361-940c-485ce8ea7438', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the difference between a shallow copy and a move in Rust?', N'Junior', N'A move occurs when ownership of a heap-allocated value is transferred to a new variable, invalidating the old one to prevent double-free errors. A copy creates a duplicate of the data, which is only allowed for types that implement the Copy trait.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c092cd8e-b06f-4c7e-aed2-485dd4983334', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the function of the ''void'' type in TypeScript?', N'Fresher', N'The ''void'' type is used to indicate that a function does not return any value. It is commonly used as the return type for functions that perform an action, such as logging a message or updating the DOM, but do not produce a result that needs to be consumed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f2386ac-0af7-471a-a2de-485dec8aad06', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How would you design a system to handle a massive spike in traffic during a seasonal event?', N'Senior', N'Prioritize architectural elasticity through auto-scaling groups and implement load shedding or circuit breakers to protect core services. Offload read-heavy traffic to caching layers and utilize asynchronous processing for non-critical tasks to prevent resource exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f82dee70-c3e8-4482-8d81-485e7f27a2cb', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are optional positional parameters?', N'Junior', N'Optional positional parameters are parameters that do not require a value to be passed during a function call. They are defined by wrapping the parameters in square brackets and can be assigned a default value if not provided.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'527e6718-c226-4d58-83be-485f3596cd3d', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What does it mean for Flask to be a micro-framework?', N'Intern', N'Being a micro-framework means that Flask provides the core functionality needed to handle web requests and routing without including built-in database abstraction or form validation. It allows developers to choose their own tools and libraries for these features, keeping the application lightweight.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2568c73-d9b9-44fa-b210-4860180ec507', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the difference between SQL and NoSQL?', N'Intern', N'SQL databases are relational and use structured tables with predefined schemas. NoSQL databases are non-relational and store data in flexible formats like documents, key-value pairs, or graphs, allowing for more scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0602eecf-d482-4119-a33f-48608f359129', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Explain the concept of ''DOM content loading'' versus ''window load'' events.', N'Middle', N'The ''DOMContentLoaded'' event fires when the initial HTML document has been completely loaded and parsed, without waiting for stylesheets, images, and subframes to finish loading. The ''window load'' event waits for the entire page, including all dependent resources, to finish downloading. Developers typically use ''DOMContentLoaded'' to initialize application logic as soon as the structure is ready.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a7c363b-4659-42f2-b21c-486404f2e29d', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the role of Pydantic in Litestar?', N'Fresher', N'Pydantic is used in Litestar for data validation and parsing. It ensures that the request data matches the defined models and handles automatic conversion to Python types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c253fd6-3588-405d-adcf-4868ca321e5d', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide when to implement caching in an application?', N'Junior', N'I implement caching when I identify read-heavy operations that perform redundant computations or expensive database queries. I prioritize caching for data that does not change frequently, ensuring that the performance gains outweigh the complexity of managing cache invalidation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c70dc44-52b4-4839-989e-4868d68a0ccf', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are loaders in Webpack?', N'Intern', N'Loaders are transformations that are applied to the source code of a module. They allow Webpack to process non-JavaScript files, such as CSS, images, or TypeScript, and convert them into valid modules that can be added to the dependency graph.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6a0df78-be2d-4aa9-b3f3-486b348f056c', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What does it mean for Sass to be a preprocessor?', N'Fresher', N'A preprocessor is a program that takes code written in a specialized syntax and converts it into standard CSS. Since browsers cannot read Sass directly, it must be compiled into a CSS file before being used on a website.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e53537c-6a5a-4a20-83ba-486b79445a63', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain the concept of ''Content Projection'' and how it differs from ''View Encapsulation'' in terms of component styling.', N'Senior', N'Content projection allows components to accept arbitrary DOM structures from a parent, whereas View Encapsulation scopes styles to the component''s internal template. When using shadow DOM encapsulation, projected content may require special CSS selectors like ::ng-deep or host-context to be styled correctly from the parent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2db70fe3-1c97-4139-a787-487281ce8c4e', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Generic Types?', N'Intern', N'Generics allow you to create reusable components that work with a variety of types rather than a single one. They provide a way to maintain type safety while allowing functions or classes to handle different data types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f80e521-b3d1-4477-b525-4873d4fabefb', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the difference between a hash and a chunkhash in Webpack?', N'Middle', N'A hash is specific to the entire build process and changes for every file if any part of the project changes. A chunkhash is specific to a particular chunk, meaning it only changes if the contents of that specific module or its dependencies change, which is much better for cache invalidation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd776a2cd-2f4d-4f45-95c3-4875a80e0e3d', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is an abstract class in PHP?', N'Intern', N'An abstract class is a class that cannot be instantiated on its own and is intended to be inherited by other classes. It can contain both regular methods and abstract methods, which must be defined by the child class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20ac0155-7e5b-4669-b4bc-4877c3f8d7cf', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does ''Data Modeling'' for a Graph database differ from a Relational model?', N'Senior', N'Graph models prioritize the relationships between entities rather than the entities themselves, using nodes and edges to represent data structures. Unlike relational models that rely on expensive joins to reconstruct connections, graph databases traverse pointers directly, making them superior for highly interconnected data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43568d32-6868-45e4-be45-487855451dd0', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the primary architectural bottleneck in high-throughput MySQL master-slave replication?', N'Senior', N'The primary bottleneck is usually the single-threaded nature of the SQL thread on the replica, which must apply events sequentially. If the master has high concurrency, the replica may fall behind unless multi-threaded slave (MTS) replication or logical clock-based parallelization is configured.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f825892f-61b6-4bd6-9cb3-48788c0e21fa', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the difference between clustered and non-clustered indexes in InnoDB and how they impact query performance.', N'Middle', N'In InnoDB, the clustered index is the primary key and physically organizes the table data, meaning every table must have one. Non-clustered indexes store the indexed columns and a pointer to the primary key, requiring a second lookup to retrieve the full row data. This makes primary key lookups significantly faster, while non-clustered indexes provide additional access paths at the cost of increased storage and maintenance overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6b873b8-88de-4c26-8d3f-487a8bf7049b', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is sharding and why is it essential for NoSQL databases?', N'Middle', N'Sharding is the process of breaking up large datasets into smaller, manageable chunks called shards distributed across multiple servers. It is essential for NoSQL because it allows the system to scale linearly and handle massive read/write throughput that would overwhelm a single database instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e664f2c-10b6-465d-be71-487ba048d2c8', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What does the ACID acronym stand for in the context of databases?', N'Junior', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably, maintaining data integrity even in the event of errors or system crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7dd3b6b-bf18-4aad-bc0b-487ba51c627a', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does the AdonisJS query builder handle SQL injection prevention?', N'Senior', N'The query builder uses parameterized queries and prepared statements by default for all user-supplied data. This approach forces the database driver to treat input as literal values rather than executable SQL code, effectively neutralizing the most common SQL injection attack vectors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7763265-2aa2-4279-9a7a-487bb7913b38', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What criteria should guide the selection of a shard key?', N'Middle', N'An ideal shard key should have high cardinality to ensure even data distribution, exhibit write scaling by avoiding monotonically increasing values that cause hot spots, and support common query patterns to minimize broadcast queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5c7da27-f582-4374-acd4-48801344499b', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you balance the need for rapid feature delivery with the necessity of technical debt management?', N'Senior', N'I advocate for a balanced approach where a percentage of every sprint or roadmap cycle is explicitly dedicated to refactoring and infrastructure improvements. This prevents debt from accumulating to a point that stifles innovation and ensures long-term system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0609e36-d98f-47af-8d5b-48802126e229', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What does the doctype declaration do?', N'Junior', N'The doctype declaration tells the browser which version of HTML the document is written in. It ensures that the browser renders the page in standards mode rather than quirks mode, which prevents layout inconsistencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a81a99cb-d01f-4d1c-bb9c-4880e982ed7d', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you determine the appropriate polling frequency for a background worker, and what are the risks of selecting an incorrect value?', N'Senior', N'I base the frequency on the business requirement for freshness versus the cost of system load. A frequency that is too high wastes resources and may overwhelm the data source, while one that is too low causes latency and poor user experience, making an event-driven push architecture a better alternative.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd61f5afe-a4eb-4c28-a56f-48821b490abe', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Readonly properties in TypeScript?', N'Fresher', N'Readonly properties are object members that can be set during initialization but cannot be modified afterwards. This is useful for creating immutable objects or ensuring that certain configuration properties remain constant throughout the lifecycle of an application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bd00973-3ffd-4f61-b299-4882d46b61f2', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the role of the +page.js file in a SvelteKit route?', N'Junior', N'The +page.js file is used to load data for a page before it is rendered. It runs on both the server and the client, allowing you to fetch data from APIs or databases so it is available to the component immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8afb61dc-2cf0-4aa9-bc0a-48832e26c63d', N'a2838158-7305-480a-b22b-4dc35776b400', N'What are the trade-offs of using Consistent Hashing in a distributed cache?', N'Senior', N'Consistent hashing minimizes data movement when nodes are added or removed from a cluster compared to simple modulo hashing. While it scales well, it can lead to non-uniform load distribution if the hash space is not partitioned effectively. Virtual nodes are typically used to mitigate this by ensuring a more granular distribution of keys across physical machines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3229ed56-9f93-4ed6-b73b-48841585da82', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the event loop', N'Intern', N'The event loop is a process that continuously monitors both the call stack and the event queue and checks whether or not the call stack is empty. If the call stack is empty and there are pending events in the event queue, the event loop dequeues the event from the event queue and pushes it to the call stack. The call stack executes the event, and any additional events generated during the execution are added to the end of the event queue. Note: The event loop allows Node.js to perform non-blocking I/O operations, even though JavaScript is single-threaded, by offloading operations to the system kernel whenever possible. Since most modern kernels are multi-threaded, they can handle multiple operations executing in the background.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b31b0ae-b10d-48fc-981a-4891045e5112', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the significance of the ''innodb_flush_log_at_trx_commit'' setting?', N'Senior', N'This setting dictates the trade-off between transaction durability and performance. Setting it to 1 ensures the redo log is flushed to disk on every commit, guaranteeing ACID compliance, whereas lower settings improve throughput by allowing periodic or delayed flushes at the risk of losing recent transactions during a crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c436f113-735a-4412-b920-48962e683492', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is a sealed class?', N'Fresher', N'A sealed class is used to represent restricted class hierarchies, where a value can have one of the types from a limited set. It is often used in when expressions to ensure that all possible cases are handled without needing an else branch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01b3ff26-1b0a-4826-a349-48966d4146b7', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'When designing a large-scale Axum service, how should you manage request-scoped data versus application-scoped data?', N'Senior', N'Application-scoped data should be stored in the shared State, while request-scoped data is best handled via custom extractors or extensions. This separation ensures that global dependencies are immutable and thread-safe, while transient request data remains isolated and short-lived.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5ae7ba2-fc6d-4a1a-bb3e-4899c00a66f7', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix improve the ''waterfall'' problem in data fetching?', N'Junior', N'Remix allows you to load data for all nested routes in parallel on the server. By fetching all required data in a single server request, it eliminates the sequence of network requests that often slows down client-side apps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27a3a87f-edbf-4cf4-afac-489a9c210987', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Explain the significance of the ''keyed'' each block in Svelte.', N'Middle', N'Keyed each blocks associate a unique identifier with every item in a list. This allows the compiler to efficiently reorder or remove DOM nodes instead of re-rendering the entire list when the underlying data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e0d2ed9-eb3d-434b-802b-489b0af148f5', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the IOptions pattern in ASP.NET Core?', N'Middle', N'The IOptions pattern provides a strongly-typed way to access configuration settings. It separates configuration data from the business logic and supports automatic reloading of settings without restarting the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e98a6cc-3f31-497b-9a89-489d6ee59c02', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you explain a technical issue to a non-technical product manager?', N'Junior', N'I would avoid jargon and focus on how the issue affects the user''s workflow and the timeline for a resolution. Using analogies or high-level summaries helps them understand the risk and impact without needing to grasp the underlying technical implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d990ee3-8481-4b1f-a90a-489fb951db84', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the function of the ''render_template'' method?', N'Fresher', N'The render_template method is used to render an HTML file stored in the templates folder. It allows you to pass data from your Python code into the HTML file using the Jinja2 templating engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bad7f265-cf8c-4647-a635-489fc6b4def0', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is an HTTP server worker in Actix?', N'Fresher', N'An HTTP server worker is an independent thread or task that listens for and processes incoming network connections. Actix spawns multiple workers to utilize multiple CPU cores, effectively distributing the load of incoming requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48e78de8-19cb-4bf1-b392-48a150416db0', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the ''merge'' process affect Elasticsearch performance?', N'Middle', N'Merging is the background process that combines smaller segments into larger ones to optimize disk usage and search efficiency. While it is necessary for maintaining performance, the I/O and CPU overhead during merges can temporarily impact the responsiveness of the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'620966d8-a1e1-4455-ad8d-48a98dedd368', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a Token in Cassandra?', N'Intern', N'A token is a 64-bit integer that represents a node''s position on the consistent hashing ring. It determines the range of data for which a node is responsible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fee815ee-a049-4e1b-be4b-48ac5f6b4e6b', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the role of an API contract, and how do you enforce it?', N'Middle', N'An API contract defines the expected request and response formats between services. It is typically enforced using specification tools like OpenAPI or Swagger, which allow for automated testing and documentation to ensure both the producer and consumer remain aligned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc9cc5ae-a19d-4037-9be5-48acd0a918aa', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'In a microservice, why might you bypass Echo''s context and use ''context.Context'' directly in deeper service layers?', N'Senior', N'Passing Echo''s specific context deep into service layers creates tight coupling between your business logic and the web framework. It is better to extract only the necessary data from the Echo context and pass standard Go context objects to service layers, keeping the business logic agnostic of the transport layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6247fdb9-6b95-45d3-869e-48ad98813e2c', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does the ''Double Write Buffer'' mechanism in database engines prevent data corruption?', N'Senior', N'During a crash, a partial page write can occur if the OS crashes while writing a page to disk. The double write buffer writes the page to a contiguous area before updating the actual data file, allowing the system to recover the original page image if the main write is corrupted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68cfd2ce-e464-4add-b12b-48afdf702970', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the primary trade-off when choosing the ''Read Committed'' isolation level over ''Serializable''?', N'Middle', N'Read Committed offers higher performance and concurrency by allowing more overlapping transactions, but it risks data anomalies like non-repeatable reads. Serializable provides the highest data integrity by preventing all concurrency anomalies but significantly reduces throughput due to increased locking or validation overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ce13504-c5a6-4978-a7ec-48b30515cc20', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the pros and cons of promises over callbacks', N'Intern', N'Below are the list of pros and cons of promises over callbacks, Pros: 1. It avoids callback hell which is unreadable 2. Easy to write sequential asynchronous code with .then() 3. Easy to write parallel asynchronous code with Promise.all() 4. Solves some of the common problems of callbacks(call the callback too late, too early, many times and swallow errors/exceptions) Cons: 5. It makes little complex code 6. You need to load a polyfill if ES6 is not supported', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4583948-f103-4c9e-8a17-48b3b24c3edd', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach debugging a ''heisenbug'' that only occurs in production?', N'Middle', N'I increase logging verbosity and use distributed tracing to capture granular state information during the execution flow. I replicate the production environment''s configuration as closely as possible and use synthetic traffic to isolate the specific conditions that trigger the bug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6b8aab9-3006-45b5-8450-48b5ce70216c', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Describe the difference between ''shallow'' and ''deep'' monitoring in the context of Node.js performance profiling.', N'Senior', N'Shallow monitoring involves tracking high-level metrics like CPU usage, memory consumption, and event loop lag. Deep monitoring involves tracing specific function execution times, identifying memory leaks via heap diffs, and analyzing call stacks to pinpoint the exact source of performance bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f26ba73f-88ba-4137-a867-48c2490dedd7', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the properties used to get size of window?', N'Intern', N'1. The screen size: The screen size is the width and height of the screen: a monitor or a mobile screen. Example: 2. The available screen size: The available screen size consists of the width and height of the active screen without the Operating System toolbars. Example: 3. The window outer size: The window outer size consists of the width and height of the entire browser window, including the address bar, tabs bar, and other browser panels. Example: 4. The window inner size: The window inner size (aka viewport size) consists of the width and height of the viewport that displays the web page. Example: 5. The web page size: The web page size consists of the width and height of the page content rendered. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16667761-bd09-45df-9aef-48c32848c433', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What are the architectural benefits of Go''s static linking?', N'Senior', N'Static linking bundles all dependencies into a single binary, eliminating dependency hell and ensuring that the application runs identically across different environments. This simplifies deployment processes and provides a significant security advantage by minimizing the external attack surface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9322f79b-fb7e-43c8-90e7-48c396e1dd30', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are named constructors in Dart?', N'Intern', N'Named constructors allow a class to have multiple constructors with descriptive names. This improves code readability and allows for different ways to initialize an object based on specific requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48ab2c74-959c-4c93-b9c7-48c457963cee', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the primary difference between the ''defer'' and ''async'' attributes when loading external scripts?', N'Middle', N'The ''defer'' attribute ensures scripts are executed in order after the document has been fully parsed, preserving their relative sequence. In contrast, ''async'' executes scripts as soon as they are downloaded, regardless of the document parsing state, which can lead to unpredictable execution order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddb83001-9db6-4709-ada7-48c4d61e2c17', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What does the term ''partition key'' mean in Cassandra?', N'Junior', N'The partition key is the first part of the primary key used to determine which node in the cluster will store a specific row of data. It ensures that related data is distributed across the cluster based on the hash of this key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23eed272-2dcf-4b21-970b-48cb9164da53', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why is the LIMIT clause used in MySQL?', N'Fresher', N'The LIMIT clause is used to specify the maximum number of records to return from a query result. It is commonly used for pagination to avoid retrieving massive datasets at once.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06fa3306-f529-48e1-8950-48cbb652baf6', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What does it mean for a function in R to be a first-class object?', N'Middle', N'In R, functions are treated like any other data type, meaning they can be assigned to variables, stored in lists, passed as arguments to other functions, or returned as output. This property enables functional programming patterns like higher-order functions and closures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5967ba27-3261-46ae-9097-48cbf4ef6a15', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Does Preact support the Context API, and how does it compare to React''s version?', N'Middle', N'Yes, Preact provides a Context API that is functionally equivalent to React''s. It allows for global state passing without prop drilling, though the underlying implementation is more streamlined to maintain Preact''s lightweight nature.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd39f526d-b1e2-469f-8bd9-48d0365401dd', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What does it mean for a function to be ''first-class'' in Scala?', N'Fresher', N'Being first-class means that functions are treated as values, allowing them to be passed as arguments to other functions, returned as values, and stored in variables. This is a core concept that enables functional programming patterns like higher-order functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f50055f-7e71-46d3-b4e0-48d24a1c47d3', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js resolve the issue of ''waterfall'' data fetching in nested component trees?', N'Senior', N'By using React''s parallel data fetching capabilities, Next.js allows multiple components to initiate their data requests simultaneously rather than sequentially. This is further optimized by the framework''s caching layer, which memoizes requests to ensure that duplicate fetches for the same data do not occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5efcc7fd-4ff3-41e7-bcfb-48d3a5042aad', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the main advantage of using a schema-less design in NoSQL?', N'Junior', N'Schema-less design provides high flexibility, allowing developers to add or change data structures without needing to perform complex migrations on existing data. This is particularly useful for rapidly evolving applications or when handling diverse data formats.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dedfe8c7-79f2-4428-a876-48d4538ba85f', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why is it important for a transaction to be isolated?', N'Fresher', N'Isolation is crucial because it prevents data corruption and inconsistencies that could occur if multiple users modified the same information at the same time. Without isolation, the results of one user''s actions might erroneously influence another''s.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3977e9ce-45f1-4898-86ad-48d54f4612a4', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is a Webpack loader, and why is it used?', N'Intern', N'Loaders are transformations applied to the source code of a module. They allow Webpack to process non-JavaScript files, such as CSS, images, or TypeScript, and convert them into valid modules that can be added to your dependency graph.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c2a6c74-6edb-4fb1-b235-48d6690291b9', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How do ''static'' blocks and ''static'' initializers function in class loading?', N'Middle', N'Static blocks are executed once when the class is first loaded into the JVM by the class loader. They are used for complex static variable initialization or setup tasks that require logic beyond a simple assignment. They ensure that all necessary environment configuration is performed before any instances of the class are created.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
