INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9906f2f7-1e53-4cfd-824b-48e2de9e8b0f', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the benefit of Vite''s dependency pre-bundling?', N'Junior', N'Pre-bundling converts CommonJS or UMD dependencies into native ESM and consolidates many small files into a single module. This reduces the number of network requests the browser makes during development, preventing performance bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4546c001-2aac-4aff-8a9b-48e914293192', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to create components in React?', N'Fresher', N'Components are the building blocks of creating User Interfaces(UI) in React. There are two possible ways to create a component. 1. Function Components: This is the simplest way to create a component. Those are pure JavaScript functions that accept props object as the one and only one parameter and return React elements to render the output: 2. Class Components: You can also use ES6 class to define a component. The above function component can be written as a class component:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b6be3ac-adf0-4b1a-8ae6-48eac986a9ee', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does ''CQRS'' (Command Query Responsibility Segregation) improve scalability?', N'Senior', N'CQRS separates the data modification logic from the data retrieval logic. This allows developers to scale read and write paths independently, often using different database technologies optimized for the specific access patterns of each.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9eb7b9c0-fd90-4c85-aef8-48ebb1ca467a', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is a route group in Chi and why is it useful?', N'Intern', N'A route group is a way to cluster routes together to share common middleware or URL prefixes. It is useful for organizing endpoints logically, such as grouping all admin-related routes under a single path prefix with specific authentication middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e74ce7ae-402c-415c-8141-48ec1df31470', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What are the limitations of Vite''s development server regarding CommonJS support?', N'Senior', N'Since Vite relies on native ESM, CommonJS modules must be converted to ESM during the pre-bundling phase. If a dependency relies heavily on dynamic CommonJS exports that cannot be statically analyzed, it may cause issues during the development server startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28fb2b25-7e99-423a-8f3f-48ed9c88da3b', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are Query Parameters and how do they differ from standard route segments?', N'Middle', N'Query parameters allow for state to be encoded in the URL after a question mark, enabling features like filtering, sorting, or pagination that can be bookmarked. Unlike dynamic route segments, they do not change the route''s hierarchy or trigger a full model hook reload by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ea8b17a-1317-4d93-ad35-48f10420ff97', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a Flask context?', N'Intern', N'Flask contexts are objects that provide access to information that is only relevant during the lifecycle of a request. There are two main types: the Application Context, which provides access to application-level data, and the Request Context, which provides access to request-specific data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f0ae385-a2b6-43ad-890a-48f59fd0f0ac', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What are the trade-offs of using Remix''s server-side data loading approach?', N'Middle', N'The primary trade-off is increased server load compared to purely static or client-side rendered apps, as every navigation requires a server round-trip for data. However, this is usually offset by significantly improved perceived performance and a simpler, more robust data flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcbd5d81-18b9-4ea1-a48a-48f684b1f9bc', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a callback function?', N'Junior', N'A callback function is a function passed into another function as an argument, which is then executed inside the outer function. They are frequently used to handle asynchronous operations after a task is finished.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fd49fa5-d305-4be3-97d0-48f7c9112bf0', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you identify and mitigate a single point of failure in a system?', N'Middle', N'I perform a component audit to identify any service or resource that, if unavailable, would cause the entire system to fail. I then introduce redundancy by deploying multiple instances across different availability zones and implementing automated failover mechanisms. Regularly testing these failover scenarios through chaos engineering helps ensure the system remains resilient under stress.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f776025-9253-4ddd-813f-48f859030ea8', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the role of a database proxy in a scaled architecture?', N'Middle', N'A database proxy acts as an intermediary layer that handles connection pooling, query routing, and load balancing. It simplifies client interaction by abstracting the complexity of the underlying database topology.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05c88ee2-3d2b-4940-8327-48f8c2f1b69f', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is an HTTP status code 404?', N'Intern', N'An HTTP 404 status code means ''Not Found''. It indicates that the server cannot find the requested resource or endpoint that the client is trying to access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e59d770d-ea58-4cc6-af1b-48fa45b21c38', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the ''ShouldBind'' method used for in Gin?', N'Fresher', N'ShouldBind is used to parse the request body, such as JSON, XML, or form data, into a Go struct. It automatically validates the input based on tags defined in the struct and returns an error if the binding fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f2551c2-18b7-4b80-b690-48fc47a7bfb4', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why would an intern choose Rocket over other frameworks?', N'Intern', N'Rocket is an excellent choice for learning backend development because it emphasizes safety, clarity, and explicit code. Its strong focus on type-safety acts as a helpful guide for beginners, reducing the likelihood of common bugs and forcing developers to consider the structure of their data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'344c708c-f8e3-4fbb-9d9b-48fd34b56ad8', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the trade-offs of using Value Types versus Reference Types in a highly concurrent Swift environment.', N'Senior', N'Value types eliminate data races by ensuring that each thread works on an independent copy of the data, removing the need for complex synchronization locks. Reference types, conversely, require explicit thread-safety measures like serial queues or actors, which can introduce performance overhead and potential deadlocks but are necessary for shared state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b82df3c-e073-4f98-9d84-48fd85a5295c', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is daemon process?', N'Intern', N'A daemon is a program that runs in background and has no controlling terminal. They are often used to provide background services. For example, a web-server or a database server can run as a daemon. When a daemon process is initialized: * It creates a child of itself and proceeds to shut down all standard descriptors (error, input, and output) from this particular copy. * It closes the parent process when the user closes the session/terminal window. * Leaves the child process running as a daemon. Daemonize Node.js process: * Forever * PM2 * Nodemon * Supervisor * Docker Example: Using an instance of Forever from Node.js', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfbc9f47-e2d7-4df0-aff2-48fe931734df', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the role of Dependency Injection in FastAPI?', N'Junior', N'Dependency Injection is a pattern where the framework provides the necessary components, such as database connections or authentication logic, to a path operation function. This promotes modularity and makes testing easier, as you can easily swap out dependencies for mocks without modifying the core logic of your endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ad16b98-1965-4afb-8587-48ff6661052f', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why is ''Eventual Consistency'' often preferred in high-scale NoSQL systems?', N'Middle', N'Eventual consistency allows systems to remain highly available and performant by not requiring immediate synchronization across replicas. It is preferred in global-scale applications where latency is a concern and business requirements allow for temporary data divergence that resolves over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b7fd45c-bf9b-4a7e-8cc8-48ff754be4f1', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between logging verbosity and system performance?', N'Intern', N'Detailed logging is invaluable for debugging and security auditing. However, excessive logging consumes storage and I/O resources, which can degrade the performance of the system if not managed correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c561716b-93a7-4b30-882e-490032d800e2', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the primary goal of the Svelte compiler?', N'Intern', N'The primary goal is to convert declarative component code into highly efficient, imperative code that directly updates the DOM. This transforms a high-level developer experience into a low-level, performance-optimized execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea82e062-03e7-4391-9c4f-4902ae167f03', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is mapping in Elasticsearch?', N'Intern', N'Mapping is the process of defining how a document and its fields are stored and indexed. It is similar to defining a schema in a relational database, specifying data types like text, keyword, or integer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2f01654-9faf-465f-a69f-4902d53f87af', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle errors or 404 responses?', N'Fresher', N'Rocket provides a catchers mechanism that allows you to define custom error handlers for specific HTTP status codes. This ensures that the application returns a consistent and clean response when a resource is not found or an error occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b11360a-95cb-4e1f-967c-490433c335ef', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the primary difference between a process and a thread in C++?', N'Fresher', N'A process is a self-contained execution environment with its own memory space, while a thread is a segment of a process that shares memory with other threads. Threads are lightweight and faster to create, but they require careful synchronization to avoid data races.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c60c3514-23bb-45dc-9d13-4906c7130146', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between an interface and a type alias?', N'Intern', N'While they are very similar, interfaces are primarily used to define the shape of objects and can be merged through declaration merging. Type aliases are more flexible as they can represent primitives, unions, and tuples in addition to object shapes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'402e168f-fcd7-4263-9236-4908b2ba1d76', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the purpose of Route Handlers in Next.js?', N'Middle', N'Route Handlers allow you to create custom request handlers for a given route using the Web Request and Response APIs. They are typically used for building internal APIs, handling webhooks, or processing data that doesn''t need to return HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46285612-84b9-42e7-b002-4908fc100222', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi''s routing influence documentation generation, such as OpenAPI?', N'Senior', N'Because Chi’s routes are defined in a structured, hierarchical manner, they can be easily parsed to generate API documentation. Tools that inspect the router tree can infer endpoint paths and methods, ensuring that documentation remains in sync with the actual routing implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7028018-182e-4c66-8a09-4909ab3bfa72', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'In a real-world engineering scenario, why is ''good enough'' sometimes the right target?', N'Intern', N'If a feature meets the user''s needs and satisfies safety requirements, further refinement may yield diminishing returns. Spending excessive time on marginal improvements diverts resources from other features that provide more value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f84f376-c9d0-4fdb-94ad-490b8a403405', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do ''Conditional Types'' enable the creation of type-safe function overloading?', N'Senior', N'Conditional types allow for the definition of function return types based on the input argument types. This provides a clean way to implement overloaded behavior without the limitations of traditional overloads, ensuring that outputs are correctly inferred based on specific input variations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'916e7f9c-fda5-4fa4-b94e-490ba43dd223', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why is it dangerous to access a member variable after moving from it?', N'Middle', N'After a move operation, the source object is left in a valid but unspecified state. Accessing its data may return null, empty, or default-initialized values, which can lead to logic errors if the program assumes the object still holds its original data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a5829cf-43a4-4ef8-8d45-490c655f8fb4', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why is ''server-side'' logic important in Remix?', N'Intern', N'Moving logic to the server reduces the amount of code sent to the client''s browser, which improves performance on low-power devices. It also keeps sensitive information, like database credentials and secret API keys, hidden from the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f321ea93-18cf-401f-8342-490e3c856152', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the role of the ''Strangler Fig'' pattern in legacy system migration?', N'Senior', N'The Strangler Fig pattern allows for the incremental replacement of legacy system components with new services. By intercepting calls at the edge and routing them to the new system, you gradually ''strangle'' the old application until it can be retired, reducing the risk of a ''big bang'' migration failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9548d4d3-cf38-454a-84cb-490f129e0e6d', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is an enumeration (enum) in C?', N'Junior', N'An enum is a user-defined data type consisting of a set of named integer constants. It is used to make code more readable by replacing magic numbers with descriptive labels that represent specific states or categories. It improves maintainability because the labels are easier to understand and manage than raw integers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a18c42b9-6443-41ec-a785-49106f3c634f', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS ensure efficient memory usage?', N'Middle', N'Because components aren''t re-executed, there is no garbage collection pressure from creating new closures or objects on every update. The framework keeps references to DOM nodes, allowing for very stable memory consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e8f3f97-24e9-4243-b6c8-491335501a99', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is an optimistic locking strategy?', N'Middle', N'Optimistic locking assumes conflicts are rare and allows multiple transactions to proceed without immediate blocking. It validates at the time of commit whether the data was modified by another process, rolling back if a conflict is detected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4903b5c-5a83-4aa2-afdc-4915ae859c2b', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the advantages of using JSONB over the standard JSON data type?', N'Middle', N'JSONB stores data in a decomposed binary format, which is slightly slower to insert but significantly faster to process because it supports indexing. The standard JSON type stores data as plain text, meaning it must be parsed every time it is queried, making it unsuitable for high-performance retrieval.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7525dc9c-06b8-4a25-8e3b-4915c15d1ae3', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is a ''hot shard'' problem in a sharded database architecture?', N'Middle', N'A hot shard occurs when one specific shard receives a disproportionately high amount of traffic compared to others. This creates a performance bottleneck on that specific node, effectively negating the benefits of horizontal scaling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'746828d5-d19c-4c61-9be5-49175163e9f4', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the interaction between the C API and R''s memory management.', N'Senior', N'The R C API allows developers to extend R with compiled code, but they must strictly adhere to R''s memory management rules, specifically regarding the protection of objects from garbage collection. Failing to use protect and unprotect calls can lead to segmentation faults or memory leaks, as the garbage collector has no visibility into objects created on the C stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35edf30f-5a2e-4603-a7e2-49187e15cfdc', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'When designing for global scale, how do you handle data residency requirements while maintaining performance?', N'Senior', N'I would deploy regional data silos where user data is pinned to the geographical region of origin to comply with residency laws. For global performance, I would use a CDN for edge caching of static content and a geo-distributed database architecture that allows for localized write operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c73cf102-27ee-4db3-b20c-49194f8dfcde', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the role of the ''ExecutionContext'' in Scala''s asynchronous programming.', N'Senior', N'The ExecutionContext acts as a thread pool manager that dictates how and where asynchronous tasks are scheduled and executed. Decoupling the task definition from the execution strategy allows developers to tune the application''s performance by swapping thread pools based on whether the workload is I/O-bound or CPU-bound.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8ade1ea-28bf-48e1-ba10-491aeae46204', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar approach background task management within the request-response lifecycle?', N'Senior', N'Litestar provides an integrated mechanism for background tasks that allows responses to be sent to the client while heavy processing continues asynchronously. This improves perceived performance for the user, though it requires an robust external queue system for true reliability and fault tolerance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b414927-1ec3-4275-96d2-491d9ede3b71', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum manage shared state mutability in a concurrent environment?', N'Senior', N'Axum expects state to be wrapped in thread-safe containers like Arc or specialized synchronization primitives if mutability is required. By enforcing these patterns through the type system, Axum ensures that shared resources are accessed safely across asynchronous tasks without the risk of data races.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cde82d5-6224-46cc-8785-491e0962b038', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix ensure that an actor does not get overwhelmed?', N'Junior', N'Actix mailboxes have a capacity limit. Once the limit is reached, the system will apply backpressure, which helps prevent memory exhaustion by limiting how many messages can be queued for an actor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14f15f9e-4826-4ea6-8633-49200e9c09a4', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Why is ''case class'' preferred for data modeling in Scala?', N'Middle', N'Case classes automatically provide implementations for equality, hashing, and string representation, while also enabling pattern matching. They are immutable by default and designed to simplify the representation of structural data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fa93164-6f2a-4434-b46e-49202105114e', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a document model in the context of DynamoDB?', N'Junior', N'DynamoDB is a NoSQL database that supports document data structures. This means it can store complex, nested data like maps and lists within a single item, offering more flexibility than rigid relational tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23dbc64f-d2df-4cfb-80dc-49202e3065e4', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Can TypeScript be used with existing JavaScript projects?', N'Junior', N'Yes, TypeScript is designed to be incrementally adoptable. You can rename files to .ts and add types gradually, or simply use TypeScript to check existing JavaScript files without needing to rewrite the entire project at once.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d921534-f221-4368-b35d-49203ebcda1f', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the Comprehensive R Archive Network (CRAN)?', N'Intern', N'CRAN is a global network of servers that store identical, up-to-date versions of R code and documentation. It serves as the primary repository for installing official R packages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a577668b-7306-488d-a668-49217755af0f', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the difference between ''def'' and ''val'' for defining members?', N'Intern', N'A ''val'' is evaluated once at the time of definition, making it a constant value. A ''def'' is a method that is re-evaluated every time it is called, which can be useful for dynamic computations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8937fee3-91a0-491a-92fc-4922b182c9c1', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does ''Template Literal Types'' influence the design of type-safe string-based APIs?', N'Senior', N'Template literal types allow for the definition of types based on string patterns, enabling precise validation of complex string formats like CSS units or API endpoints. They shift validation logic from runtime string parsing to compile-time checking, reducing the need for unit tests on string formatting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de68f4d5-2172-4f26-ad2d-4923d5c50118', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Do all NoSQL databases support ACID transactions?', N'Intern', N'No, many NoSQL databases prioritize availability and scalability over strict ACID compliance. While some modern NoSQL systems have introduced transaction support, many follow the BASE model instead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b32fe9c-714b-469f-9b59-4925433755de', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why is Phoenix considered a ''real-time'' framework?', N'Junior', N'Phoenix is considered real-time because of its efficient support for WebSockets via Channels and LiveView. By maintaining long-lived connections, it allows the server to push data to the client immediately without the client needing to poll for updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c94363a2-2234-497d-afe7-49265a837b5e', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the mechanics of ''Inline Classes'' versus ''Value Classes'' and their evolution.', N'Senior', N'Inline classes were an experimental feature that provided zero-cost abstractions by replacing the type with its underlying value at compile time. Value classes are the stable successor, providing a more robust implementation that handles boxing and unboxing more predictably across different JVM execution contexts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee74d634-dee0-4ddb-8a49-492dd0637807', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason through the estimation of a task that has high dependency on other internal teams?', N'Middle', N'I identify the critical path and establish clear communication channels with the external teams to understand their capacity and timelines. I then add a risk-adjusted buffer to my estimate that accounts for potential delays in their delivery, while proactively flagging these dependencies as risks to project stakeholders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'629b8221-580a-45b1-b4b3-49312c912919', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the significance of the descriptor protocol.', N'Middle', N'The descriptor protocol defines how attribute access is managed via the __get__, __set__, or __delete__ methods. By implementing these, objects can control how they are accessed as attributes of other classes, forming the foundation for properties, static methods, and class methods. It allows for advanced customization of attribute behavior and data validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b533fcb-4308-4602-8ba5-493195e02f8b', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between an ''append'' and an ''extend'' method in lists?', N'Junior', N'The ''append'' method adds its entire argument as a single element to the end of the list, regardless of whether it is a list or an object. The ''extend'' method iterates over its argument and adds each individual element to the list. Using ''extend'' effectively merges the contents of two lists, while ''append'' would result in a nested list structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'960deb6b-d1d8-411a-b809-4931b39c9ac9', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is ''Lock Escalation'' and why is it a potential performance bottleneck?', N'Senior', N'Lock escalation occurs when a database converts many fine-grained row-level locks into a single coarse-grained table-level lock to save memory. This significantly reduces concurrency, as one transaction can block all other access to the entire table, leading to contention spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29e4cffa-e70c-4307-aa33-4931b90dce13', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between having a strict schema in an API versus a flexible, evolving schema?', N'Junior', N'A strict schema ensures data consistency and makes integration easier for consumers. A flexible schema allows for faster iteration and evolution, but it requires more robust validation logic on the client or server side to prevent bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'675f5e6c-c566-457a-89c7-4932872257a9', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket achieve type safety in URL path parameters?', N'Middle', N'Rocket uses the FromParam trait to automatically parse and validate path segments. Because the types are specified in the function signature, Rocket attempts to convert the string segment into the requested type, failing the request early if the conversion is impossible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86105d85-5c4d-4d89-ac94-49329e0a0900', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why is NoSQL often considered easier for agile development?', N'Junior', N'NoSQL is agile-friendly because the flexible schema allows developers to iterate quickly. Changes to the data model do not require complex database migrations that would normally require downtime in a traditional SQL environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d2ecdaf-bb23-4bed-b33b-4933843cd389', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a situation where a bug is reported in production but cannot be reproduced in your local development environment?', N'Middle', N'I would compare the production environment''s configuration, infrastructure settings, and traffic patterns against my local environment. I might also implement additional observability, such as verbose logging or custom metrics, in a staging environment that mirrors production closely to capture the hidden state changes causing the bug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'740e8155-7f7d-4c76-b161-4935c51c8bfe', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the main difference between Hono and Express?', N'Junior', N'The main difference is that Hono is built on Web Standards and is designed for edge runtimes like Cloudflare Workers, while Express is built specifically for the Node.js runtime. Hono is also significantly smaller in bundle size and generally faster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72a851ec-e05a-45b2-9dfd-4935f960fa81', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the purpose of the Java reflection API?', N'Middle', N'Reflection allows a program to inspect and modify its own structure at runtime, such as classes, methods, and fields. It is essential for frameworks that need to dynamically load classes, invoke methods, or access private fields without knowing their structure at compile time. However, it is slower than direct code access and can bypass security checks, so it should be used judiciously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d4c39fc-1a6b-4580-bcfc-493a95e4704d', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of Phoenix Channels?', N'Intern', N'Phoenix Channels provide a mechanism for real-time communication between the client and the server. They allow for bidirectional data flow, enabling features like live chat or real-time notifications over WebSockets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1f33fb1-b0d7-4e6a-a912-493cca3fd99f', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix''s ''route module'' pattern simplify project maintenance?', N'Senior', N'By encapsulating the loader, action, and component logic within a single route file, Remix promotes high cohesion. This makes it easier to trace data flow and side effects compared to traditional architectures where these concerns are spread across disparate files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ecb35ae-5bfe-4e47-9fda-493e0a3ccc41', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does client-side navigation work in SvelteKit?', N'Intern', N'After the initial page load, SvelteKit intercepts link clicks to prevent a full browser refresh. Instead, it dynamically loads the necessary data and components to update the page content seamlessly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8f9d84a-aea4-45f9-be53-493e8854ab68', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If a stakeholder requests a feature that you suspect will take three times longer than they anticipate, how do you handle the estimation discrepancy?', N'Senior', N'I would deconstruct the feature into granular technical requirements and highlight the specific complexity drivers, such as integration debt or architectural constraints, that lead to the higher estimate. By presenting a risk-adjusted timeline and offering an incremental delivery approach, I can align stakeholder expectations with realistic engineering delivery without sacrificing system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5789e01-4865-49f0-a732-493ebbc7c2eb', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a situation where a database migration caused a performance degradation after deployment?', N'Middle', N'I would immediately check if the migration introduced missing indexes or sub-optimal query execution plans, then compare the database performance metrics before and after the change. If the impact is critical, I would initiate a rollback to the previous schema version while simultaneously optimizing the new migration in a controlled test environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aee40050-40f9-46cd-8cc1-493eeda96457', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Explain the architectural trade-offs of using a ''Sidecar'' pattern for observability.', N'Senior', N'The sidecar pattern decouples observability logic from the application code, allowing for language-agnostic instrumentation and easier updates. However, it introduces resource overhead for every instance and adds complexity to the networking stack, which can impact overall system latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c32d5b4f-272e-4f89-addc-493fd5bfd140', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'When designing a multi-tier cache (L1/L2), what is the primary architectural challenge regarding data consistency?', N'Senior', N'The primary challenge is keeping the L1 (local) and L2 (distributed) caches synchronized. If an update occurs, you must manage invalidation propagation across all L1 nodes, which often involves a trade-off between strict consistency and the latency overhead of global invalidation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'129893e4-f8b3-4e76-8860-494018c47752', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Explain the difference between ''computed'' and ''effect'' primitives.', N'Senior', N'Computed primitives are intended for derivation and are lazy; they only update when accessed and when their dependencies change. Effects are eager and are intended for side effects, running immediately when their dependencies change, regardless of whether their output is used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
