INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e8b1008-f384-4f7b-84f7-494726e25f2e', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket''s design influence the scalability of a backend service?', N'Middle', N'Rocket''s asynchronous architecture and efficient resource management allow it to handle high concurrency with low overhead. By using non-blocking I/O and efficient type-based routing, it ensures that the backend can scale horizontally without excessive memory or CPU usage per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c44cf6e7-7ca7-40c7-9e7a-494d2acd15d1', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'In the context of Rocket, what are ''Data Guards'' and how do they differ from Request Guards?', N'Senior', N'Data Guards specifically handle the parsing and validation of incoming request bodies, such as JSON or multipart forms. While Request Guards focus on the metadata or authentication of the request, Data Guards focus on the integrity and structure of the payload itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9969369-6184-4d5b-9423-494e7bbc60b8', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle conditional rendering compared to React?', N'Middle', N'SolidJS uses dedicated components like Show or Switch for conditional rendering. This is necessary because Solid does not re-render the component body; these control flow components wrap the content in a reactive scope to toggle DOM nodes efficiently without re-executing parent logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
