INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13dcfd0f-5c64-4c9e-9b94-49516a26c2db', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Describe the impact of using ''eval'' or dynamic code execution on the performance and security of a Node.js application.', N'Senior', N'The use of dynamic code execution prevents V8 from performing static analysis and optimizations, leading to significantly slower execution. From a security perspective, it introduces critical vulnerabilities, including remote code execution, as it allows arbitrary input to be executed within the server''s process context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9a607b5-1b8f-4821-92e6-49535488e5f1', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the purpose of a view in a database?', N'Intern', N'A view is a virtual table based on the result set of an existing query. It does not store data itself but displays data from one or more tables dynamically. Views are useful for simplifying complex queries and restricting access to specific sensitive data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6b57bdb-7838-403d-8801-495415e16b8d', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are the common strategies for securing a Flask application against common web vulnerabilities?', N'Middle', N'You should use extensions like ''Flask-Talisman'' to set secure HTTP headers, implement CSRF protection, sanitize all user inputs to prevent injection attacks, and always use HTTPS in production. Additionally, keeping your dependencies updated and using secure session management are critical components of a defense-in-depth strategy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'130fc7d9-d979-4618-a429-495a156e3bea', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What architectural considerations should be made when using Gin in a microservices environment regarding request tracing?', N'Senior', N'Gin should be integrated with distributed tracing headers (like B3 or W3C TraceContext) via custom middleware. This allows for passing correlation IDs through the middleware chain, ensuring that logs and spans across service boundaries can be linked for observability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc00d2eb-fa08-4140-9c7e-495c7a7d2014', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What does it mean to say that Ruby is an object-oriented language?', N'Fresher', N'In Ruby, everything is treated as an object, including primitive data types like numbers, booleans, and nil. This allows developers to call methods on any value, promoting a consistent and uniform programming model where behavior is encapsulated within objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77b7ba7a-384b-4a6d-85a3-495d4559bd18', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does a database handle ''Phantom Reads''?', N'Senior', N'Phantom reads occur when a transaction re-runs a query and finds new rows added by another committed transaction. To prevent this, databases use range locks or predicate locking, which lock the criteria used in the query rather than just the specific rows present at the time of the first read.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a03ba21d-d86c-44cd-be63-495ec5983f27', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Can components in SolidJS be called as regular functions?', N'Intern', N'Yes, components are just functions in SolidJS. However, it is best practice to use them as tags in JSX so that the framework can correctly set up the reactive graph and manage the component''s lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50195b83-232c-405b-bb4a-495fa09dab36', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum maintain performance while supporting complex JSON serialization?', N'Senior', N'Axum leverages the serde-json crate, which is highly optimized for performance and memory usage. By offloading serialization and deserialization to this battle-tested library and ensuring that data is handled in an async-friendly manner, Axum maintains high throughput even when processing complex, nested JSON payloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88aef592-5dd0-4f7b-a7c0-496130c77956', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Discuss the implications of JIT inlining on the size and frequency of code cache flushes.', N'Senior', N'Aggressive inlining improves performance by removing call stack overhead, but it significantly increases the size of generated machine code. If the code cache becomes full, the JIT compiler must stop compiling new methods, forcing the JVM to interpret code and causing a performance cliff.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bef6d59a-da19-42bb-a124-49635af39e4e', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the primary performance benefits of using fibers for I/O-bound tasks?', N'Middle', N'Fibers allow handling thousands of concurrent connections with minimal memory footprint because each fiber requires a small stack compared to a full OS thread. Since they are user-managed, the CPU avoids the expensive context switching costs associated with kernel-level thread management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25d01a0f-8a8a-4b89-b8aa-4964eaf4cb86', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is prop drilling?', N'Intern', N'Prop Drilling is the process by which you pass data from one component of the React Component tree to another by going through other components that do not need the data but only help in passing it around.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'448bdd73-5053-4251-901a-49651d34e133', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'When should you prefer the standard library over Fiber?', N'Middle', N'You should prefer the standard library when you require long-term stability, strict adherence to the Go interfaces, or when you are building simple services where performance is not the primary bottleneck. The standard library is more predictable and has a smaller dependency footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c27c09c-8cfc-402a-8918-496730cedf2c', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is a RequestBody vs RequestParam?', N'Junior', N'@RequestBody is used to bind the entire HTTP request body to a Java object, typically for JSON payloads. @RequestParam is used to extract query parameters from the URL, such as those found after a question mark in a request path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab595ff3-ec4d-492a-8575-4968a42a4106', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the ''Option'' enum?', N'Fresher', N'The Option enum is used to represent a value that may or may not exist. It has two variants: Some, which contains a value, and None, which indicates the absence of a value, effectively replacing the concept of null.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93d60115-4107-469a-936c-496bcf217128', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do modules work in TypeScript?', N'Fresher', N'Modules allow you to organize code into separate files by using import and export statements. This promotes modularity and prevents global scope pollution by keeping variables and functions contained within their respective files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'868c7143-9599-491f-90eb-496cb2aacb69', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What does the ''x-text'' directive do?', N'Intern', N'The ''x-text'' directive is used to set the text content of an element to the result of a JavaScript expression. It is a safer alternative to innerHTML because it treats the content as plain text, preventing potential security risks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b21af9a0-a6ee-4551-97c8-496d95adffb9', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'When is it appropriate to use an ''After Request'' hook versus a ''Teardown Request'' hook?', N'Senior', N'Use ''after_request'' for operations that modify the response object, such as adding custom headers or security tokens, as it has access to the response. Use ''teardown_request'' for cleanup operations that must run regardless of the request outcome, even if an unhandled exception occurred, as it is guaranteed to execute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8571524-23e4-41d6-bef1-496ed3a28822', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Discuss the trade-offs of using ''ref'' and ''in'' modifiers in method signatures.', N'Senior', N'The ''ref'' modifier allows a method to modify the caller''s variable, while ''in'' ensures the argument is passed by reference without allowing modification, which is useful for large structs to avoid copying. While both improve performance by avoiding data duplication, they complicate the API contract and can lead to side effects if used improperly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5baab7ba-f604-4761-9298-49704ddd8888', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot''s dependency injection work at a high level?', N'Junior', N'Dependency injection is a design pattern where the Spring container manages the creation and lifecycle of objects, known as beans. Instead of a class manually creating its dependencies, the container ''injects'' them, promoting loose coupling and easier testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a63924b5-ec8b-4778-9dd7-4970eb71be40', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber''s concurrency model work?', N'Middle', N'Fiber utilizes Go''s native goroutines to handle each incoming request concurrently. Because the framework is designed to be lightweight, it scales horizontally across CPU cores, allowing it to handle a high volume of simultaneous requests without the overhead of thread-per-request models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
