INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'754284bf-28b1-4749-ab9f-497a9db65311', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the function of the Redo Log in MySQL?', N'Middle', N'The redo log is a disk-based data structure used during crash recovery to correct data written by incomplete transactions. It ensures that committed changes are preserved even if the server crashes before the data was flushed from the memory buffer pool to the main data files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
