INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19de4b07-4f2a-4d57-96c2-4981c3dd180d', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is Dependency Injection in Spring?', N'Intern', N'Dependency Injection is a design pattern where the objects needed by a class are provided by the framework rather than the class creating them itself. This promotes loose coupling and makes the code easier to test and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12809753-15f4-4423-8301-4982be3963c6', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the benefit of the Redis ''Pipeline'' feature?', N'Middle', N'Pipelining allows a client to send multiple commands to the server without waiting for individual replies, significantly reducing network latency caused by multiple round-trips. It is particularly effective for high-throughput scenarios where the client needs to perform many independent operations in quick succession.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8c321da-d7f6-44f8-a5c8-4983d7c1070d', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the ''Coordinator Node'' role impact search performance in a large cluster?', N'Senior', N'A coordinator node receives search requests, distributes them to all relevant shards, and merges the results before returning them to the client. If not properly load-balanced, a single coordinator can become a bottleneck when managing large scatter-gather operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
