INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31e18a2f-5ea0-4f24-8342-498c2b838545', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the impact of having too many indexes in MongoDB?', N'Junior', N'While indexes improve read performance, having too many can negatively impact write performance. This is because every write operation requires the database to update not only the document but also all associated indexes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65e36464-50f6-4c3c-af28-498ff8244cfc', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of compare function while sorting arrays?', N'Fresher', N'The purpose of the compare function is to define an alternative sort order. When the sort() function compares two values, it sends the values to the compare function, and sorts the values according to the returned (negative, zero, positive) value. If omitted, the array elements are converted to strings, then sorted according to each character''s Unicode code point value. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8463a72f-d46f-4d8a-9bdc-499144d1d5b1', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why are backups essential for any data-driven application?', N'Fresher', N'Backups are the last line of defense against data loss caused by system failures, human error, or malicious attacks. Without a reliable backup strategy, a critical incident could result in the permanent loss of business data. Regular backups ensure that the system can be restored to a known good state in the event of a disaster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcf95175-1153-468f-9b06-49945eacf41b', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How do you optimize re-renders in a Preact application?', N'Middle', N'Optimization in Preact is achieved using techniques like memoization via the memo utility, which prevents unnecessary re-renders of components if their props have not changed. Additionally, using Signals allows for granular updates, which avoids re-rendering parent components altogether.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee6b54a3-4802-427d-9533-499712666cbd', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is meant by ''asynchronous'' programming in FastAPI?', N'Intern', N'Asynchronous programming allows the server to handle multiple requests concurrently without waiting for slow operations, like database queries or external API calls, to finish. By using the async and await keywords, FastAPI can pause a task and work on another one, significantly improving performance under high traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2849b3ff-9c5d-4a27-8a3a-4997f880a989', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Define the various types of errors which occur in JavaScript?', N'Intern', N'There are three main types of errors that can occur while compiling a JavaScript program: syntax errors, runtime errors ( also called exceptions ), and logical errors. When an exception occurs, an object representing the error is created and thrown. The JavaScript language defines seven types of built-in error objects. 1. Error: The "Error" type is used to represent generic exceptions. This type of exception is most often used for implementing user defined exceptions. 2. RangeError: "RangeError" exceptions are generated by numbers that fall outside of a specified range. 3. ReferenceError: A "ReferenceError" exception is thrown when a non-existent variable is accessed. These exceptions commonly occur when an existing variable name is misspelled. 4.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adb5be98-32f8-455c-b9e0-49996bf1f23d', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the role of the SolidJS compiler in performance optimization?', N'Middle', N'The compiler transforms JSX into efficient, imperative DOM instructions. By analyzing dependencies at compile time, it eliminates the need for a runtime reconciliation process, resulting in minimal memory overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f926d2f-f08a-4ab0-bb4a-499ad2b56c73', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is a jQuery plugin?', N'Intern', N'A jQuery plugin is a piece of code that extends the core jQuery functionality by adding new methods to the jQuery prototype. Plugins allow developers to share reusable components like image sliders, date pickers, or custom form validations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe7707e2-d1e2-423d-83d4-499b099ac834', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is database sharding and why is it used?', N'Middle', N'Database sharding is a technique of splitting a large dataset into smaller, more manageable chunks called shards, which are distributed across multiple servers. It is used to overcome the storage and throughput limitations of a single database instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bacfdb00-d7fd-4d09-b87d-499d2374c322', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the trade-off between logical and physical database design in large-scale systems?', N'Senior', N'Logical design focuses on normalization to eliminate redundancy and maintain data integrity, which is vital for consistency. Physical design often involves denormalization, partitioning, or sharding to improve query performance and scalability at the cost of data redundancy and increased application-level logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a611f04-c5d5-4245-a02a-49a06ab8b7ac', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you estimate the technical debt payoff effort versus building a new feature with high business value?', N'Middle', N'I evaluate the long-term cost of the technical debt in terms of increased maintenance time and developer friction compared to the projected revenue or user engagement of the new feature. I would prioritize the debt payoff if it is actively blocking the new feature''s development or presents a significant risk to system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74874fba-1905-4872-ab6c-49a22656f8ca', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the benefit of the ''Serializer'' in AdonisJS models?', N'Middle', N'Serializers allow developers to control exactly how model data is transformed into a JSON response, such as hiding sensitive fields like passwords or formatting timestamps. This provides a consistent API contract and prevents accidental exposure of internal database fields to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1e5683c-431a-4e56-8b55-49a2342a672a', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Discuss the trade-offs of using a CDN as a cache layer for dynamic content.', N'Senior', N'CDNs significantly reduce latency by serving content from the edge, but they add complexity in terms of cache invalidation and ensuring that dynamic user-specific data is correctly segmented. They are most effective when the dynamic content can be cached based on specific request attributes or authentication tokens.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'008c6625-45c0-4c92-abff-49a418d52434', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Describe the difference between vertical and horizontal scaling.', N'Middle', N'Vertical scaling involves adding more power, such as CPU or RAM, to an existing machine. Horizontal scaling involves adding more machines to the resource pool, which is generally more flexible and resilient but requires a distributed architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2193d82d-7e05-4d30-95e5-49a7df2c0605', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the role of action creators in a Redux architecture?', N'Middle', N'Action creators serve as a factory pattern for creating action objects. They abstract the creation of action payloads, promoting reusability and ensuring consistent action structure throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef3e0eb7-6a53-450f-b15b-49a931c9f5a2', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Explain the mechanism behind Echo''s ''HTTPErrorHandler'' and why it is a critical component for building robust APIs.', N'Senior', N'The custom HTTPErrorHandler allows developers to centralize the logic for mapping internal application errors to specific HTTP status codes and standardized JSON response bodies. This ensures consistent error reporting across the entire API, simplifying client-side error handling and improving API predictability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa61fe3d-e4a1-4c29-ab7f-49b389d1e144', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the advantage of Go''s fast compilation?', N'Fresher', N'Go''s compiler is designed to be extremely fast, which significantly improves the developer experience by reducing wait times between code changes and testing. This fast feedback loop allows for rapid prototyping and more efficient development cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13f138a5-531c-49bd-9587-49bcbfac0a48', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does the ''key'' prop affect component state?', N'Middle', N'When a key changes, React treats the component as a new instance, unmounting the old one and mounting a fresh one. This resets the internal state of that component, which is useful when you want to force a clean re-initialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c79f664e-ec4a-4be6-9f24-49be2ea7f557', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the purpose of the ''c.Next'' method in Gin middleware?', N'Intern', N'The c.Next method explicitly calls the next handler in the chain within a middleware function. It is used to control the execution flow when you need to perform actions both before and after the subsequent handlers have finished.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05ad9cc1-27fb-4598-a669-49bf2a867a90', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the purpose of the ''group'' functionality in Chi routing?', N'Senior', N'Grouping allows developers to apply common middleware or URL prefixes to a subset of routes. This improves code maintainability and scalability by enforcing cross-cutting concerns like authentication or rate limiting at the resource-group level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a57ae3e1-af4b-459c-bcfc-49bf43f6deef', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why is the use of ''Client Loader'' or ''Client Action'' sometimes necessary?', N'Middle', N'These features are useful when you need to perform data operations that rely strictly on browser APIs or local storage that is not accessible on the server. They provide an escape hatch to perform specific tasks on the client while maintaining the overall route-based architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb177bb1-9eac-4283-9a5b-49bfd38c6188', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How should you handle service discovery in a highly dynamic containerized environment?', N'Senior', N'You should use a client-side or server-side service registry combined with a sidecar proxy pattern. This decouples the service logic from the infrastructure, allowing the service mesh to handle dynamic IP changes, health checks, and load balancing transparently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba14e321-e633-414f-ac4e-49c02762ab00', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the role of the Scala compiler in type erasure.', N'Middle', N'Scala relies on the JVM, which erases generic type information at runtime to maintain backward compatibility. This means generic type parameters are not available during execution, which can lead to issues with pattern matching on specific types unless ClassTags or TypeTags are used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c47e7cf6-12ff-47c1-8814-49c4bbaa4a00', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'When is it appropriate to use an ''API Composition'' pattern vs an ''API Gateway'' pattern?', N'Senior', N'API Composition involves an aggregator service that calls multiple downstream services and combines results into a single response, which is useful when business logic requires orchestration. An API Gateway is primarily for traffic management, routing, and security, rather than complex data aggregation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1f40e58-11d8-47db-a3f4-49c8e05ca594', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle JSON serialization and deserialization?', N'Fresher', N'Rocket integrates seamlessly with the Serde library to handle JSON. It uses specialized types that automatically convert incoming JSON request bodies into Rust structs and convert Rust structs back into JSON responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66657164-921d-4540-8603-49c98c2b69f0', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does C implement separate compilation without a module system?', N'Senior', N'C uses a header file mechanism to share declarations across translation units, while the linker performs name resolution to connect these declarations to their definitions. This model is fragile compared to modern module systems because it relies on the textual inclusion of headers, which can lead to redundant processing and complex dependency chains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc6b6e58-febe-451a-8bba-49d19ac5f58e', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between ''stackalloc'' and normal memory allocation?', N'Junior', N'Stackalloc allocates memory directly on the stack rather than the heap, which is significantly faster and avoids garbage collection overhead. However, it is restricted to small, fixed-size buffers and requires the code to be marked as unsafe.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85945554-0eac-4487-a098-49d25fc87c32', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is Sass and why do developers use it?', N'Intern', N'Sass stands for Syntactically Awesome Style Sheets. It is a CSS preprocessor that extends CSS with features like variables, nesting, and mixins, which help developers write cleaner, more maintainable, and organized stylesheets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6ff944c-934c-4004-86b4-49d5a1dd4544', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is ''Prefetching'' in Qwik and why is it important?', N'Middle', N'Prefetching is a strategy where Qwik identifies the chunks that are likely to be needed next based on user behavior or page structure. By downloading these chunks in the background before the user actually clicks, it further reduces perceived latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a326847f-1d44-4438-9fff-49d5ed603041', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s router handle overlapping routes?', N'Middle', N'Echo follows a strict priority rule where static routes are matched before dynamic path parameters. If multiple routes match, the framework registers them in the order they were defined, and the first match found in the radix tree is executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22f9f010-ceae-462e-9335-49d61b2208e3', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Why does Dart favor composition over inheritance?', N'Middle', N'Composition is more flexible, allowing developers to combine small, discrete behaviors into complex objects without the limitations of a rigid class hierarchy. It results in loosely coupled systems that are easier to test, refactor, and extend as requirements evolve.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67f3c49a-b41a-4c6d-9be1-49d6a7254506', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the difference between a vector and a list in the R programming language?', N'Fresher', N'A vector is a one-dimensional data structure that can only contain elements of the same data type, such as all integers or all characters. In contrast, a list is a more flexible, recursive structure that can contain elements of different types, including other lists, vectors, or data frames.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9efa6ae7-fff3-4ddf-94fb-49db281842f7', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why should you include a doctype declaration at the top of an HTML document?', N'Junior', N'The doctype declaration informs the browser about the version of HTML being used, which ensures the page is rendered in standards mode rather than quirks mode. Rendering in standards mode prevents unexpected layout issues and ensures consistent behavior across different browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97d3d41a-f791-488d-8571-49e1ae7cb326', N'954a0331-deff-4399-b588-96f39fec001d', N'What is JIT?', N'Intern', N'Just-in-Time (JIT) is a type of compilation that compiles your app in the browser at runtime. JIT compilation was the default until Angular 8, now default is AOT. When you run the ng build (build only) or ng serve (build and serve locally) CLI commands, the type of compilation (JIT or AOT) depends on the value of the aot property in your build configuration specified in angular.json. By default, aot is set to true.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be18d5db-e2f0-4e03-b692-49e1afb2f091', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is an atomic operation in Redis?', N'Fresher', N'An atomic operation is one that is executed entirely or not at all, with no partial updates occurring. Because Redis is single-threaded for command execution, most individual commands are atomic, ensuring data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e79c3365-3a57-4faa-bc21-49e77ce3fe38', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are the security implications of using the ''Remember Me'' feature, and how should it be mitigated?', N'Senior', N'Remember Me increases the attack surface by persisting authentication tokens, which could be stolen. Mitigation involves using a secure token generator, enforcing strict cookie security settings, and requiring re-authentication for sensitive actions like password changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'863ad9bd-e626-416d-a257-49e90e54c22f', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Discuss the concept of ''fat models'' versus ''service objects'' in the context of maintaining a large Rails codebase.', N'Senior', N'Fat models often lead to bloated, hard-to-test code that violates the Single Responsibility Principle as the system grows. Service objects extract domain-specific logic into standalone classes, improving testability and modularity, though they require careful design to avoid creating an overly abstract, fragmented architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'904e2afb-a6d0-416b-b17e-49f010fad9f6', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why are ''Initializer'' and ''Instance Initializer'' used in Ember?', N'Middle', N'Initializers run when the application boots to configure the container and inject services globally. Instance initializers run after the app is initialized and have access to the application instance, which is necessary for setting up runtime services like authentication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1318039d-19f5-4188-b239-49f42cf23c13', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What does it mean for Redis to be an in-memory data store?', N'Fresher', N'Being in-memory means that all data resides in the server''s primary memory (RAM) while the application is running. This allows for extremely high-speed data retrieval and modification compared to databases that rely on disk storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26cf8cb2-1e4e-40dc-beb9-49f587c70456', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If you receive negative feedback on your work, how do you respond?', N'Fresher', N'I view it as an opportunity to learn and improve. I listen carefully to understand the specific concerns, ask clarifying questions to ensure I have the right context, and incorporate those insights into my next iteration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c49090f-588d-4325-8113-49f7753718de', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why does Remix prefer server-side operations?', N'Fresher', N'Server-side operations reduce the complexity of the client-side code and prevent the need to build and maintain separate API endpoints. This simplifies the data flow and improves the security of your application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a9f90b1-bbd6-4781-9e52-49f7dde41c70', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the Go runtime?', N'Intern', N'The Go runtime is a library that is linked into every Go executable. It handles tasks like garbage collection, managing Goroutines, and providing support for built-in types and features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b5e910a-3ab4-47f2-93f9-49faa8ae1b54', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is Node.js considered ''non-blocking''?', N'Intern', N'Node.js is considered non-blocking because it does not wait for I/O operations, such as reading a file or querying a database, to complete before moving to the next line of code. Instead, it initiates the request and registers a callback, allowing the program to continue executing other tasks in the meantime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c4946b2-0adc-41c0-bfc0-49fbf0c30387', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it dangerous to guess the cause of a bug instead of verifying it?', N'Fresher', N'Guessing can lead to applying ''band-aid'' fixes that do not address the root cause, potentially introducing new bugs or masking the actual problem. Systematic verification ensures that the fix is robust and truly resolves the underlying issue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd73ed52-9d73-4b8a-878d-49fc9bc193a7', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between ol and ul elements?', N'Junior', N'The ol element is used for ordered lists where the sequence of items matters, typically rendered with numbers. The ul element is used for unordered lists where the order is not important, typically rendered with bullet points.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
