INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c238ef8-158a-4307-81a5-4a0267b73996', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why is it important to use a process manager like PM2 with Express?', N'Middle', N'PM2 keeps the Express application running if it crashes, manages load balancing across multiple CPU cores via clustering, and facilitates zero-downtime restarts. It is standard practice for ensuring high availability and reliability in production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab0a2213-6b3d-4a0f-a292-4a03df92f90c', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the primary function of the Rack interface, and how does it influence Rails application deployment?', N'Senior', N'Rack provides a common interface between web servers and Ruby frameworks, abstracting the details of HTTP requests and responses. This allows Rails applications to be compatible with various web servers and middleware, enabling modular functionality like authentication or logging to be injected into the request pipeline easily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea667d14-45c9-4416-a846-4a068079dfdd', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the role of Isolates in Dart for memory management and concurrency.', N'Middle', N'Isolates are independent units of execution that do not share memory with each other, communicating strictly through message passing. This architecture prevents memory corruption and data races, as each isolate maintains its own heap and garbage-collected memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
