INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e8f9b54-2bd1-42d2-9ecd-4a08059e51e1', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does compaction affect read latency and disk utilization?', N'Senior', N'Compaction merges multiple SSTables into fewer, larger files, which reduces the number of files the read path must scan. While this significantly improves read performance, the process is disk-intensive and can temporarily cause high I/O spikes during the merging phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea8f51e7-5aaa-43ae-9de0-4a08f409b30a', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What are the trade-offs of using ''use client'' in a project?', N'Middle', N'Using ''use client'' breaks the component and its children out of the Server Component execution model, increasing the JavaScript bundle size sent to the browser. It is necessary for interactivity but should be pushed to the leaves of the component tree to keep as much code on the server as possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7808626-8537-4372-900a-4a08f610c5a1', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is boxing and unboxing in C#, and why is it a performance concern?', N'Middle', N'Boxing is the process of converting a value type to an object reference on the heap, while unboxing is the reverse. This process involves memory allocation and type checking, which can cause significant performance degradation when performed inside tight loops.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66c0660e-b865-4650-9baf-4a0a5697228e', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain how Ruby''s ''Fiber'' implementation differs from traditional OS threads in terms of scheduling and state.', N'Senior', N'Fibers are light-weight, cooperative concurrency primitives that require manual context switching, unlike OS threads which are preemptively scheduled by the kernel. This puts the burden of scheduling on the developer but drastically reduces the memory overhead associated with thread stacks, making them ideal for high-concurrency I/O bound tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e9a88b7-2f5c-4818-97b8-4a0b455c5684', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle context updates and why is it sometimes faster than React?', N'Senior', N'Preact''s context implementation is streamlined to update only the affected subscribers through a direct reference check. Because the overall framework overhead is lower, the propagation of context changes encounters less friction and fewer object allocations compared to React''s more feature-rich context provider system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5e27f8c-e34a-46eb-b961-4a1306d90ade', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How do ''Sidecar Caches'' improve microservice architecture compared to embedded library caches?', N'Senior', N'Sidecar caches decouple the caching logic from the application runtime, allowing the cache to be upgraded, scaled, and managed independently. This prevents memory pressure in the application process and enables shared caching state across different language implementations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c7d65db-6350-4057-a1c8-4a13a3f724d0', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you determine the appropriate level of logging and monitoring for a production service?', N'Middle', N'The strategy should balance visibility with performance and cost, ensuring logs contain enough context for incident response without creating excessive storage overhead. Metrics should focus on the ''four golden signals'': latency, traffic, errors, and saturation, to provide a clear health overview.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff2166ae-e73c-4ee7-9a8f-4a14bc59647b', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is your approach to debugging a system experiencing ''jitter'' in request processing time?', N'Senior', N'I would correlate the jitter with infrastructure metrics like context switching frequency, CPU stealing (in virtualized environments), and garbage collection pauses. By mapping the request arrival times against these system events, I can determine if the jitter is caused by internal application work or by external environment contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdbd9b28-040b-4a1d-8afc-4a150a1a32b3', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the difference between a Remix loader and a standard API endpoint?', N'Junior', N'A loader is specifically designed to provide data to a route component within the same application. While they both return data, loaders are tightly integrated with the Remix routing and rendering lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2152af6a-1ddd-4f8c-8c85-4a188be98ec8', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does bulkhead pattern improve system reliability?', N'Middle', N'The bulkhead pattern isolates resources like thread pools or memory for different parts of a system, preventing a failure in one component from consuming all resources and crashing the entire application. It ensures that a localized failure is contained and does not lead to a total system outage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1debe1e-fa7c-4460-a160-4a1be8c71e49', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Describe the impact of the C11 memory model on multi-threaded application performance.', N'Senior', N'The C11 memory model introduced atomics and memory ordering constraints, allowing developers to specify the visibility of memory operations across threads. By providing fine-grained control over synchronization, it replaces the need for expensive platform-specific memory barriers. This enables more efficient lock-free data structures by reducing unnecessary cache coherency traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13e74826-76f7-4ac7-9955-4a1cf0d5bbdc', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why is database design important?', N'Intern', N'Good database design is essential to ensure data consistency, minimize redundancy, and optimize performance. A well-designed database makes it easier to query data and ensures the system can scale as requirements grow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2aa944fc-e5db-4133-9f6a-4a1e95bf0b1d', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What happens if a node fails in a Cassandra cluster?', N'Junior', N'Because Cassandra is decentralized, the cluster continues to function without the failed node. Other nodes take over the responsibility of serving the data that was hosted on the failed node, provided the replication factor is high enough.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffbc88cf-b66d-4df5-b7fb-4a1f75ed92fa', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is ''write amplification'' and how does it affect database performance?', N'Senior', N'Write amplification occurs when the actual amount of data written to the physical storage is greater than the logical amount requested by the application. This is common in log-structured merge-tree storage engines, where frequent background compactions and indexing updates consume IOPS and reduce the effective lifetime of SSDs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c318effc-9677-4845-a947-4a24ac4cb06a', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What are Request and Response objects in Laravel?', N'Intern', N'The Request object represents the data sent by the user, such as form inputs or query parameters. The Response object is the output sent back to the user, such as an HTML page, a JSON object, or a redirect.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4d79073-22a8-4121-8bc0-4a2754ebbca8', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is it often preferred to use ''channels'' over direct actor communication for specific task pipelines?', N'Senior', N'While actors are excellent for stateful components, channels are often lighter and more efficient for simple producer-consumer pipelines. Channels allow for more flexible decoupling where the consumer does not need to be a full actor with a lifecycle and mailbox, reducing architectural overhead for simple tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed9d6fb2-9422-4212-b3a6-4a299e63449f', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle concurrency compared to traditional Flask or Django applications?', N'Middle', N'FastAPI is built on Starlette and is natively asynchronous, allowing it to handle many concurrent connections efficiently using a single-threaded event loop. Traditional frameworks are typically WSGI-based and rely on multi-processing or multi-threading to handle concurrency, which consumes more memory per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
