INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea2d10d3-7887-4102-8fd3-4a2d0392f0a1', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the benefit of using Webhooks compared to polling for real-time updates?', N'Senior', N'Webhooks provide an event-driven mechanism where the server pushes updates to the client as they occur, eliminating the need for inefficient and high-latency polling. This reduces resource consumption on both the client and server while enabling near-instantaneous notification delivery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6eac343-10a6-4dda-bc7a-4a2dfe07a095', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the role of Middleware in the Laravel framework?', N'Fresher', N'Middleware acts as a protective layer that sits between an incoming HTTP request and your application''s routes. It is used to inspect or filter requests, such as verifying if a user is authenticated or checking if a request meets specific conditions before it reaches the controller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
