INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f59c322f-d628-425f-b8c8-4a3bfbdfa989', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What does ''Tunable Consistency'' mean?', N'Middle', N'Tunable consistency allows developers to configure the level of consistency on a per-query basis. For example, a user can choose to read from a single node for speed or require a majority quorum of nodes to agree to ensure the most up-to-date data is returned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f29c7e55-4db4-4573-90f5-4a45365bc587', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the different types of JDBC Driver?', N'Intern', N'JDBC Driver is a software component that enables java application to interact with the database. There are 4 types of JDBC drivers: 1. JDBC-ODBC bridge driver: The JDBC-ODBC bridge driver uses ODBC driver to connect to the database. The JDBC-ODBC bridge driver converts JDBC method calls into the ODBC function calls. This is now discouraged because of thin driver. 1. Native-API driver: The Native API driver uses the client-side libraries of the database. The driver converts JDBC method calls into native calls of the database API. It is not written entirely in java. 1. Network Protocol driver: The Network Protocol driver uses middleware (application server) that converts JDBC calls directly or indirectly into the vendor-specific database protocol. It is fully written in java. 1.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bca3dab5-868e-469b-a634-4a4bc8d36fbd', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why should you validate user input on the server side even if you have already validated it on the client side?', N'Fresher', N'Client-side validation is primarily for user experience, but it can be easily bypassed by malicious users using tools like Postman or browser developer tools. Server-side validation is the final line of defense to ensure data integrity and security before the input is processed or stored in the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a164e2ab-d927-4432-b08a-4a4d8cbf5e87', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How do Redis transactions (MULTI/EXEC) handle atomicity, and why is rollback not supported?', N'Senior', N'Redis transactions ensure that all commands in a block are executed sequentially without interference from other clients, but they do not support traditional rollback on error. The design philosophy favors speed and simplicity, assuming that logic errors should be caught during development rather than handled via complex transaction rollbacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
