INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a96b9fe7-10c6-4051-8769-4a4fe92d7cc1', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the difference between a shallow copy and a deep copy of an object?', N'Fresher', N'A shallow copy creates a new object but references the original memory locations for nested objects, meaning changes to those nested objects affect both. A deep copy recursively duplicates every object in the hierarchy, ensuring the new object is completely independent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'796052eb-3112-4447-901a-4a5326a0b389', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are mapped types, and how do they contribute to DRY (Don''t Repeat Yourself) principles?', N'Middle', N'Mapped types allow you to create new types by transforming the properties of an existing type. They help adhere to DRY principles by enabling the dynamic derivation of types, such as making all properties optional or read-only, without needing to manually redefine the entire structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
