INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7037ac9-a354-4891-b98c-4a593176a5aa', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro handle framework interoperability?', N'Middle', N'Astro uses a framework-agnostic approach that allows developers to mix components from different libraries like React, Vue, Svelte, or Solid within the same project. This is possible because Astro renders these components to static HTML on the server, regardless of their underlying library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6a52b84-f8f3-4f26-8d73-4a5c5e3b3cef', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is a database association?', N'Fresher', N'An association is a connection between two ActiveRecord models, such as one-to-one, one-to-many, or many-to-many. These relationships allow Rails to easily fetch related data between tables without needing complex join queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ef2e77b-5138-4a5c-a676-4a61a3838e1e', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the Middleware pipeline in ASP.NET Core?', N'Intern', N'Middleware components are software parts assembled into an application pipeline to handle requests and responses. Each component chooses whether to pass the request to the next component in the pipeline and can perform work before and after the next component is invoked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
