INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8db1f2bd-8dc1-4cc1-bbed-4a641666bb81', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the trade-offs of using Fasthttp-based frameworks like Fiber regarding standard library compatibility?', N'Middle', N'Since Fiber relies on Fasthttp, it does not strictly adhere to the net/http interface defined by the Go standard library. This means common middleware or third-party packages designed specifically for the standard library cannot be used directly without a compatibility adapter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17a5771a-a957-4c55-9c40-4a6a64eced79', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the architectural impact of using custom middleware for authentication versus using Echo''s built-in JWT middleware?', N'Senior', N'Built-in JWT middleware provides a standardized, battle-tested approach for token validation, reducing implementation risk. However, custom middleware offers better control over complex authentication flows, such as multi-factor authentication or dynamic token refreshing, which the standard middleware may not handle natively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
