INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4617863b-655e-4ddc-8686-4a7275f7b79a', N'075b8862-431c-4678-9767-f55359758a4a', N'What is a property style access?', N'Intern', N'You can access values of store''s getter object(store.getters) as properties. This is known as property style access. For example, you can access todo''s status as a property, The getters can be passed as 2nd argument for other getters. For example, you can derive completed todo''s count based on their status as below, Note: The getters accessed as properties are cached as part of Vue''s reactivity system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
