INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15bee8aa-c7b5-4ab8-821b-4a92d1bff5c1', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the primary purpose of Redux in a frontend application?', N'Intern', N'Redux is a predictable state container designed to help manage the global state of an application. It provides a centralized store where all data resides, making it easier to track changes and debug complex state interactions across different components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2457b3a-9e21-4695-9437-4a943886ce99', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle component lifecycle in a way that minimizes memory overhead?', N'Senior', N'Svelte components are essentially classes that manage their own state and DOM nodes directly. Because the component structure is flattened during compilation, there is no need for a complex framework-level lifecycle management object, allowing for faster initialization and lower memory consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54eb0d02-b411-46eb-8bf7-4a95b64e231e', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the ''ConfigureServices'' and ''Configure'' methods in older startup patterns, and how has this changed in .NET 6+?', N'Middle', N'ConfigureServices was used for dependency injection registration, and Configure was used to set up the middleware pipeline. In .NET 6 and later, these have been consolidated into the Program.cs file using the WebApplicationBuilder pattern for simplicity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'930cdc4c-c2d9-4c74-a77e-4a9bf50f1ee1', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Why is ''Salted Hashing'' insufficient for modern password storage?', N'Senior', N'While salting prevents rainbow table attacks, it does not mitigate brute-force or credential stuffing if the hashing algorithm is too fast. Modern systems must use slow, adaptive hashing algorithms like Argon2 or bcrypt to increase the computational cost of cracking a stolen password database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cf665bb-3a91-4a1b-9de4-4a9d1d5cbc94', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Why is it important to use ''IHttpClientFactory'' instead of directly instantiating ''HttpClient''?', N'Middle', N'Directly instantiating HttpClient can lead to socket exhaustion because the underlying connection is not always released immediately. IHttpClientFactory manages the lifecycle of HttpClient handlers, pooling them efficiently to prevent socket depletion and handle DNS updates correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e57d22a-8215-47a2-81dc-4a9dabc6b9e1', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is JSX and why do we use it in React?', N'Intern', N'JSX in React 19+ JSX (JavaScript XML) is a syntax extension for JavaScript that provides a declarative way to describe the UI structure. While it resembles HTML, it is a syntactic sugar for function calls that compile into the React element tree. Technical Foundations * Syntactic Sugar: JSX is not HTML; it is an abstraction over React.createElement (or the newer jsx() transform introduced in React 17+). * Expression Embedding: Developers can embed arbitrary JavaScript expressions within curly braces {}. The React runtime handles the evaluation and injection of these expressions into the VDOM. * Transpilation: Modern build tools (Vite, SWC, or Babel) transform JSX into standard JavaScript during the build phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32c45605-3ccd-4e75-9e41-4a9de9de24d8', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What does ''reactive'' mean in the context of Lit?', N'Intern', N'In Lit, reactivity means that the component automatically updates its DOM whenever its reactive properties change. This ensures the view stays in sync with the underlying data state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58e41847-ec38-4e37-a0c1-4aa1027e62d1', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik''s dependency injection differ from traditional frameworks?', N'Senior', N'Qwik''s dependency injection is designed to work across the server-client boundary by serializing the state required for the dependency. It ensures that services are available where needed without requiring the full application to be initialized in the browser, maintaining the resumability model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a974655b-90d4-4a60-9245-4aa337f6b951', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the benefit of using ''rel=preload'' for critical assets?', N'Middle', N'Preload tells the browser to fetch a high-priority resource, such as a main CSS file or a hero image, as early as possible. It helps prevent the browser from discovering the asset later in the document parsing process, which would otherwise delay rendering. It should be used sparingly for only the most critical assets to avoid wasting bandwidth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99ebb011-2973-42b2-a622-4aa87e4aa28a', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why should you keep a log of your actual time spent versus your estimated time?', N'Junior', N'Tracking the delta between estimates and actuals helps me identify where I consistently misjudge complexity. Over time, this data allows me to improve my accuracy and provide more reliable estimates for future projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef076dcf-56c7-49d3-a757-4aab195b2d8d', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the concept of an Interface in C#.', N'Fresher', N'An interface is a contract that defines a set of methods and properties without providing their implementation. Any class that implements an interface must provide the specific logic for all the members defined within that interface, allowing for polymorphic behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79b44a67-f35e-415e-bdeb-4aac458dbf8b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the trade-offs of using Web Workers for offloading computational tasks.', N'Senior', N'Web Workers allow parallel execution by running scripts in background threads, preventing main-thread blocking. The primary trade-off is the overhead of structured cloning when passing data between threads and the inability to access the DOM directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28803a3f-a46d-4975-a091-4aadf1d379cb', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach estimating the time required for cross-team dependencies?', N'Middle', N'I would initiate a conversation with the dependent team to understand their roadmap and availability early in the planning process. By factoring in potential wait times or communication overhead, I can build a more realistic timeline that accounts for external constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db587bfc-a123-4bc8-8d00-4ab34507873a', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik optimize network utilization for micro-frontends?', N'Senior', N'Qwik allows micro-frontends to be loaded as independent, granular chunks without needing a central orchestration layer to hydrate the entire tree. This reduces network payload size and prevents a single micro-frontend from blocking the execution of others during startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10babda3-b593-48d6-9b13-4ab607e24832', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What should you do if you realize you cannot meet a deadline?', N'Intern', N'I notify my lead or manager as soon as I identify the risk, providing a clear explanation of why the delay is occurring. I propose a revised timeline or suggest a ''minimal viable'' version of the task that can be completed on time. This proactive communication allows the team to adjust plans accordingly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd92b1952-8842-4b20-bce2-4ab63007f03b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do WeakMaps facilitate better memory management compared to standard Maps in long-lived applications?', N'Senior', N'WeakMaps hold weak references to their keys, meaning they do not prevent garbage collection if the key is no longer reachable elsewhere. This prevents memory leaks in scenarios where metadata needs to be associated with objects that have an independent lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e98067b-6b97-4939-968e-4ab797da2f76', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the function of the Outlet component?', N'Junior', N'The Outlet component acts as a placeholder in a parent route''s layout. It tells Remix exactly where to render the matching child route component based on the current URL path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45141b24-5ddf-4348-b67e-4ab80fa86af5', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a destructor and when must it be virtual?', N'Fresher', N'A destructor is called when an object is destroyed to release resources. It must be declared virtual in a base class if you intend to delete a derived class object through a pointer to the base class, ensuring the derived class''s destructor is also called.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b8df66d-b608-4e3b-af0e-4abbbfe6f1ea', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'In a Phoenix application, how do you handle backpressure when a client consumes data slower than the server produces it?', N'Senior', N'Phoenix leverages the underlying GenStage or Flow abstractions to propagate backpressure signals from the consumer back to the producer. By adjusting the demand, the server can dynamically throttle data generation, preventing memory exhaustion and ensuring system stability under heavy load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
