INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8fdde16-17d0-4572-aa80-4abcdb72925f', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the primary difference between ''Kernel#send'' and ''Object#public_send'' regarding encapsulation?', N'Senior', N'The ''send'' method can invoke private or protected methods, bypassing Ruby''s visibility rules, which is useful for metaprogramming but breaks encapsulation. ''public_send'' respects visibility modifiers and will raise an error if a non-public method is accessed, making it a safer choice for dynamic method invocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10c23200-c92a-4e1b-9835-4ac0ad15b15b', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the main purpose of Alpine.js in a web project?', N'Junior', N'Alpine.js is a lightweight framework designed to provide the reactive behavior of larger frameworks like Vue or React directly within your HTML. It allows developers to add interactivity, such as toggling visibility or handling form inputs, without needing a complex build step or heavy JavaScript bundles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4cb4485-adc1-490d-9ba8-4ac0dc7b6330', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is a ''handler'' function in Rocket?', N'Intern', N'A handler function is a standard function that is associated with a route and is responsible for processing an incoming HTTP request. It accepts arguments derived from the request and returns a value that Rocket converts into an HTTP response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f4d54ba-fc7b-492f-b2f9-4ac2c2a9d21f', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the primary architectural difference between PHP-FPM and traditional mod_php?', N'Middle', N'Mod_php runs the PHP interpreter inside the Apache process, which consumes memory for every request even if it is for a static asset. PHP-FPM operates as a separate FastCGI process manager, allowing for more efficient resource management, better process scaling, and independence from the web server process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'749b6062-83c7-4257-a4a2-4ac7a03ced94', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the purpose of the ''public'' folder in a SvelteKit project?', N'Middle', N'The public folder contains static assets like images, fonts, and robots.txt that are served directly without any processing. Files in this directory are accessed via the root path and remain untouched by the SvelteKit build pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0c44aaf-29ef-4572-8342-4ac94a3c50b2', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are React Server components?', N'Intern', N'React Server Component is a way to write React component that gets rendered in the server-side with the purpose of improving React app performance. These components allow us to load components from the backend. Note: React Server Components is still under development and not recommended for production yet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64d3821f-33d6-48f9-bd2d-4ac9fda9e265', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a system, how do you choose between adding a new feature or refactoring existing technical debt?', N'Junior', N'The decision depends on the business priority and the impact of the technical debt on development velocity. If the debt actively blocks progress or causes frequent bugs, prioritize refactoring; otherwise, balance new feature work with scheduled maintenance sprints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37165bee-fb87-4668-a45a-4aca8314c40a', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How do you retrieve a URL parameter value in a Chi handler?', N'Intern', N'You retrieve parameter values by using the chi.URLParam function, passing in the request object and the name of the key defined in the route pattern.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'474d9e8b-657d-41f2-8e17-4accf3df6b47', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How can index optimization contribute to database scalability?', N'Senior', N'Efficient indexing reduces the I/O required for query execution, allowing the database to handle more requests without additional hardware. However, over-indexing can negatively impact write performance and storage usage, requiring a balanced approach tailored to the specific query patterns of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'711d386b-493b-4457-b397-4ad03da83334', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the major components of State Management Pattern?', N'Intern', N'The state management has state, view and actions as major components. The pattern followed by these components in a application is known as State Management Pattern. Below are the components in a detail, 1. The state, which is the source of truth that drives our app 2. The view, which is just a declarative mapping of the state 3. The actions, which are the possible ways the state could change in reaction to user inputs from the view. Let us take a counter example which follows state management pattern with the above 3 components,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42ddbb5c-a600-4c65-8191-4ad17c964498', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is serialization in the context of FastAPI?', N'Intern', N'Serialization is the process of converting complex data objects, such as database models or Python dictionaries, into a format like JSON that can be transmitted over the network. FastAPI handles this automatically using Pydantic models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30cc5768-262f-43aa-a128-4ad255a289e7', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What happens if you perform a DROP TABLE command?', N'Junior', N'The DROP TABLE command removes the table definition and all data contained within it from the database. This action is permanent and cannot be undone unless a backup exists, so it should be used with caution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb36eb1c-b123-4118-b2e4-4ad412bc73e7', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using an ORM versus raw SQL queries for a new module?', N'Middle', N'I use an ORM for rapid development and simple CRUD operations where performance is not the bottleneck. I opt for raw SQL when dealing with complex, performance-critical analytical queries where the ORM''s abstraction might lead to inefficient execution plans.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fcbec6f-ab24-413d-9464-4ad492cebbdb', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the role of the ''use client'' directive in Next.js?', N'Middle', N'The ''use client'' directive marks a file as a Client Component, which is necessary when using hooks, event listeners, or browser-only APIs. It essentially creates a boundary where the module and its dependencies are bundled for the client, allowing the rest of the application to remain as server-rendered components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'532a9c7f-8e56-4379-8787-4ad569c87853', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How are HTTP status codes typically handled in Litestar?', N'Junior', N'Litestar provides a comprehensive list of constants for HTTP status codes. Developers return these codes along with the response body, or the framework automatically sets them based on the return type of the handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48235103-6a8e-4228-b005-4ad5996cfbc5', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the role of the ''any'' type, and why is it generally discouraged in large-scale projects?', N'Middle', N'The ''any'' type disables type checking, allowing a variable to bypass the compiler''s safety mechanisms. It is discouraged because it breaks the contract of type safety, hides potential bugs, and prevents the tooling from providing accurate autocomplete or refactoring support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93856ce0-e871-4223-8184-4ad609229de5', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are the performance implications of using nested selectors in Sass?', N'Middle', N'Deeply nested selectors can lead to overly specific CSS rules that are difficult to override and increase the size of the final stylesheet. It is generally recommended to keep nesting shallow, ideally no more than three levels deep, to maintain performance and avoid specificity wars.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0daa361a-57df-4e61-a382-4ad6be687959', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the return type of a function that does not return a value?', N'Intern', N'A function that does not return a value has a return type of ''void''. This indicates that the function performs an action but does not produce a data result to be used by the caller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0cea5ec-1b69-43f6-8012-4adc36079ae6', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why is it important to send a response in every route?', N'Junior', N'An HTTP request-response cycle must be completed to prevent the client from waiting indefinitely. If you do not send a response or call next(), the server will remain in a pending state, causing a timeout.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a68ce37-da25-4293-abb2-4adc5a37213c', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the difference between the Vite development server and the production build?', N'Intern', N'The development server uses native ES modules for fast updates, while the production build uses Rollup to bundle, minify, and optimize the code for better performance and browser compatibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'380aa082-fd37-44cf-964d-4adff77e2470', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why is Fastify''s request object considered ''lightweight''?', N'Senior', N'The request object is created once per request and contains only the necessary metadata, avoiding the heavy prototype chain construction found in older frameworks. This minimizes the memory footprint of each concurrent request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b518d80e-f6b4-4070-92da-4ae475f91c9f', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'In a distributed Hono-based microservice architecture, how should global error handling be architected to ensure observability?', N'Senior', N'Global error handling should be centralized through a custom error-handling middleware that intercepts exceptions, maps them to appropriate HTTP status codes, and formats them for logging systems like ELK or Datadog. This ensures that every failure is captured with its request context, preventing ''silent'' failures and facilitating easier root-cause analysis across service boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e24b9a40-3775-4fff-be43-4ae47854297d', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Why is the Java Virtual Machine''s stack size management critical for deeply recursive algorithms?', N'Senior', N'Each thread in the JVM has a fixed-size stack for method frames, and deep recursion can quickly exhaust this limit, leading to a StackOverflowError. Senior architects must balance thread count against stack depth, often necessitating iterative refactoring or increasing the thread stack size parameter to prevent runtime failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'250a76b5-b2de-4e08-8576-4ae588ef0a6e', N'954a0331-deff-4399-b588-96f39fec001d', N'What is an RxJS Subject in Angular?', N'Intern', N'An RxJS Subject is a special type of Observable that allows values to be multicasted to many Observers. While plain Observables are unicast (each subscribed Observer owns an independent execution of the Observable), Subjects are multicast. A Subject is like an Observable, but can multicast to many Observers. Subjects are like EventEmitters: they maintain a registry of many listeners.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce585c2b-6b90-4881-91e0-4ae5a8436cff', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the primary purpose of PHP in web development?', N'Intern', N'PHP is a server-side scripting language designed specifically for web development. It is used to generate dynamic page content, collect form data, and interact with databases before the final output is sent to the user''s browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2e83a76-a047-4db3-82b1-4ae5c109bdc8', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle database transaction isolation, and what are the risks of manual handling?', N'Senior', N'AdonisJS provides a transaction manager that encapsulates connection lifecycle and error handling, ensuring that transactions are properly committed or rolled back. Manual handling risks leaving connections open or hanging if errors occur, which can lead to connection pool exhaustion and database deadlocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60bbbc33-bb9a-4574-a117-4ae6364859ba', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is jQuery''s document ready event considered less critical in modern single-page applications?', N'Middle', N'jQuery''s document ready ensures scripts only execute after the DOM is fully loaded, preventing errors when selecting non-existent elements. In modern applications, scripts are often loaded asynchronously or injected into the body, and logic is usually bound to component lifecycle hooks rather than the global document load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1891f27f-b6bb-4654-8717-4ae6afd2281d', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit differ from a framework like React?', N'Fresher', N'Lit is a library for creating native Web Components, whereas React is a full framework that uses a proprietary virtual DOM implementation. Lit components are standard browser elements that can be used independently of any framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e1c8d68-295f-42ac-9ab4-4ae73aafe9b6', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you ensure data integrity during concurrent updates in a Flask application?', N'Senior', N'You should use database-level locking mechanisms or optimistic concurrency control, where a version column is checked before updating a record. Relying on application-level logic for concurrency is insufficient due to the potential for race conditions in a multi-worker environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3a36b10-b995-4312-ba40-4aea032b89f4', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the concept of ''Covariance'' and ''Contravariance'' in C# generics.', N'Senior', N'Covariance allows using a more derived type than originally specified, typically for read-only interface parameters, while Contravariance allows a less derived type, usually for write-only parameters. These variance mechanisms enable greater flexibility in API design while maintaining type safety at compile time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef22947e-da37-4981-a1fb-4aec7a5168f1', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Can Vite be used to build static websites?', N'Intern', N'Yes, Vite is excellent for building static websites. It compiles your source code, optimizes assets, and outputs a folder of static files that can be deployed to any standard web server or hosting platform.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'633c7873-8af8-4ced-ae0c-4aec7b05890a', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Discuss the complexity of debugging Svelte applications compared to runtime-based frameworks.', N'Senior', N'Because Svelte transforms code into imperative updates, the generated code can sometimes be harder to trace than a virtual DOM tree. Developers often need to rely on source maps and Svelte-specific devtools to understand how state changes map to final DOM updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51efb18b-b803-4975-836c-4aed3de5907c', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How do layouts work in Nuxt?', N'Junior', N'Layouts allow you to create reusable wrappers for your pages, such as headers and footers. You can assign a specific layout to a page, and Nuxt will inject the page content into a defined slot within that layout.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7aefe32-b2e0-4f0c-8f70-4aed5ae75e6e', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the benefit of using Tailwind''s ''arbitrary values'' feature, and what are the potential risks?', N'Middle', N'Arbitrary values allow developers to apply specific, one-off styles that aren''t defined in the design system, providing flexibility for unique edge cases. The risk is that overusing them can lead to a fragmented design language and undermine the consistency benefits of having a strictly defined design system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ffbef28-9dc6-448c-ab0a-4af19272fd1f', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is denormalization, and when might you use it?', N'Junior', N'Denormalization is the process of intentionally adding redundant data or grouping data to improve read performance. It is often used in data warehousing or read-heavy applications to reduce the need for complex joins between multiple tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3fc6f74-a145-4c10-bb9d-4af709f2f017', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the purpose of the ''Request-Scoped'' provider, and why should it be used sparingly?', N'Senior', N'Request-scoped providers are instantiated for every individual incoming request, allowing access to request-specific data like user identity. They should be used sparingly because they significantly impact performance by increasing memory overhead and preventing the singleton optimization of the dependency injection container.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f93e06a-7710-4c3a-8177-4af7727be627', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you justify moving from a server-based architecture to serverless?', N'Senior', N'I justify it based on the TCO (Total Cost of Ownership), specifically focusing on the elimination of idle resource costs and the reduction in operational maintenance. If the workload is event-driven and variable, serverless provides superior cost-efficiency and scalability compared to fixed server capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f9e31f6-741e-4014-896a-4af8fa6a524d', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What happens if a reducer returns undefined?', N'Intern', N'If a reducer returns undefined, Redux will throw an error because the state must always be a valid object. You should always provide an initial state value to ensure the application starts correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57729946-647d-4e7d-bffd-4afb5aa8e6c6', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is a Bean lifecycle?', N'Fresher', N'The bean lifecycle refers to the process from the container instantiating the bean to its eventual destruction. This process includes dependency injection, the execution of initialization callbacks, and the execution of destruction callbacks when the container shuts down.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56ae1f9e-17d1-420b-bfc1-4afd63830dfa', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the main difference between SQL and NoSQL databases regarding schema?', N'Intern', N'SQL databases are schema-based, meaning the data structure must be defined before inserting data into tables. NoSQL databases are schema-less or have flexible schemas, allowing you to insert data without a predefined structure and modify it easily as requirements change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'709a3235-500c-462d-b890-4afd843e5c2e', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Discuss the impact of strict mode on development and production.', N'Senior', N'Strict Mode enables additional checks during development, such as detecting side effects in render methods and identifying deprecated APIs. It does not affect production builds, but it helps catch concurrency-related bugs early by double-invoking lifecycle methods to ensure they are pure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd744c099-e8a2-4786-8d5a-4afea4566843', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between ''nullptr'' and ''NULL''?', N'Junior', N'NULL is typically defined as an integer macro (0), while nullptr is a type-safe keyword introduced in modern C++. Using nullptr helps avoid ambiguity in function overloading and prevents potential errors associated with integer-to-pointer conversions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
