INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1db0d7f-3cca-4324-b3f3-4b0e1ecdd88d', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What are Eloquent Relationships?', N'Intern', N'Eloquent relationships allow you to define the connections between different database tables in your models. Common types include one-to-one, one-to-many, and many-to-many, which allow you to easily retrieve related data using simple method calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25e2fa45-ed4b-4a04-9efe-4b0e442c5fbf', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB achieve horizontal scalability, and what is its role?', N'Middle', N'MongoDB achieves horizontal scalability through sharding, which distributes data across multiple physical instances called shards. This allows the system to handle larger datasets and higher throughput by partitioning data based on a shard key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
