INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89d8ad11-a34c-441e-870b-4b1a7ceafb91', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is it generally discouraged to perform heavy CPU-bound tasks in a Node.js event loop?', N'Middle', N'Since Node.js runs on a single main thread, CPU-intensive tasks block the event loop from processing other incoming requests or callbacks. This leads to increased latency and can make the entire application unresponsive for all users until the task finishes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e2289d2-9c80-4e17-beed-4b1a8a1efd55', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the purpose of the ''Provide'' decorator in Litestar?', N'Middle', N'The Provide decorator is used to define dependency injection providers. It instructs the framework to instantiate or retrieve a specific object when a route handler requires it as an argument, managing the lifecycle of that dependency efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87d15933-8b4f-41c6-8bbe-4b200b8ae914', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket manage state across different handlers?', N'Middle', N'Rocket uses managed state, which is a thread-safe, type-safe container initialized when the application starts. You can inject this state into handlers using the State type, allowing multiple handlers to share access to resources like database pools or configuration objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfbee71a-e976-4b92-a2d9-4b231cdcc39f', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go handle visibility?', N'Intern', N'Go uses the casing of identifiers to control visibility. If an identifier starts with an uppercase letter, it is exported and accessible from other packages; if it starts with a lowercase letter, it is private to the current package.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'540b988e-75f9-42ca-b3f3-4b2343490504', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of the ''Hinted Handoff'' mechanism, and why is it not a substitute for ''Read Repair''?', N'Senior', N'Hinted Handoffs allow a node to store updates for a temporarily unavailable peer, delivering them when the peer returns to improve eventual consistency. It is not a substitute for Read Repair because hints can be lost if the coordinator node fails or if the downtime exceeds the hint window, whereas Read Repair ensures data synchronization during actual data retrieval.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ea34338-eefb-429e-8e16-4b26c222d85b', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why is Rust considered suitable for systems programming despite having a runtime?', N'Senior', N'Rust''s runtime is minimal, primarily providing features like stack unwinding, backtrace generation, and task scheduling for async operations, rather than a full VM or GC. Because this runtime is opt-in or highly predictable, Rust remains suitable for low-level environments like kernel drivers, embedded systems, and performance-critical infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'896077e6-cf7a-41b2-9759-4b26f29a46e3', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does Python’s Global Interpreter Lock (GIL) impact multi-threaded performance, and why can it not be simply removed?', N'Senior', N'The GIL ensures that only one thread executes Python bytecode at a time, preventing race conditions in CPython''s memory management. It cannot be easily removed because CPython''s reference counting mechanism is not inherently thread-safe, requiring extensive modifications or significant performance degradation in single-threaded scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c0627e6-7ca1-4039-8e54-4b26f610c74b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Describe the impact of ''sync'' vs ''async'' script tags on the critical rendering path.', N'Senior', N'Sync scripts block HTML parsing until the script is downloaded and executed, increasing TTI. Async scripts download in the background and execute immediately upon arrival, while defer scripts download in the background and execute only after the document is fully parsed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3a649f6-da61-4020-b9e4-4b272017e4f4', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the role of a message queue in decoupling services?', N'Middle', N'A message queue allows services to communicate asynchronously by placing messages in an intermediary buffer. This decouples the producer and consumer, enabling services to operate independently and smoothing out traffic spikes without requiring immediate responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfa3500e-c34b-43f7-8e22-4b28d90d8603', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How do you handle graceful shutdowns in a FastAPI application?', N'Senior', N'FastAPI provides lifecycle events (startup and shutdown handlers) that allow for the cleanup of resources such as database pools, cache connections, or background task executors. Properly implementing these ensures that pending requests are completed and connections are closed cleanly, preventing data corruption or resource leaks during deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eaf510a0-c8c6-463d-9e02-4b2c82f2fe07', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does the imperative nature of jQuery inhibit the implementation of unit testing?', N'Senior', N'Imperative jQuery code is difficult to test because it relies heavily on the state of the actual DOM, requiring complex JSDOM setups to simulate the environment. Modern frameworks separate concerns by allowing logic to be tested against plain JavaScript objects, independent of the UI layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'843f9e69-eb85-4e58-9064-4b30fa6cfe7a', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the benefit of using Redux in a large application?', N'Intern', N'Redux provides a clear structure and predictable data flow, which makes large applications easier to debug and test. It ensures that state updates are handled in a consistent and centralized manner.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34510934-46da-442a-8424-4b312eacb2a7', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the architectural implications of implementing a Read-Write splitting strategy?', N'Senior', N'Read-Write splitting offloads read operations to replicas, increasing throughput and availability for read-heavy workloads. However, it introduces the challenge of replication lag, requiring the application to handle potential consistency issues where reads may not immediately reflect the most recent writes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94347447-a0b4-48d7-8607-4b3696f89318', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is JIT mode in Tailwind CSS and why is it important?', N'Junior', N'JIT (Just-In-Time) mode generates styles on-demand as you author your HTML, rather than generating all possible utility classes upfront. This results in significantly smaller CSS bundle sizes and faster build times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5c06ed9-ed99-485e-9848-4b3777aac142', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does ''x-model'' achieve data binding?', N'Intern', N'The x-model directive creates two-way data binding between an input element and the data defined in your component. This means that when the user changes the input value, the underlying data updates automatically, and vice-versa.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da42b877-56af-4d86-9b0d-4b38661c5cc1', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain how the query optimizer uses index statistics to generate execution plans.', N'Senior', N'The optimizer gathers cardinality statistics—estimates of the number of unique values in an index—to decide whether an index scan or a full table scan is more efficient. If statistics are stale, the optimizer may choose a sub-optimal plan, necessitating the use of ''ANALYZE TABLE'' to refresh the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64a3e149-c169-4a06-8712-4b3e3de310f5', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What happens if a property value is updated to the same value?', N'Intern', N'Lit performs a strict equality check on property updates. If the new value is identical to the current value, Lit will skip the update cycle to improve performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
