INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa25ba50-9478-4617-b6ed-4b4479c15e4c', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does the ''Async/Await'' model in Rust differ from colored-function models in other languages?', N'Senior', N'Rust uses a poll-based model where futures are lazy and do nothing unless they are driven by an executor. This allows the runtime to be decoupled from the language, providing greater flexibility and enabling the use of different executors depending on the specific requirements of the application, such as embedded or high-throughput servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3937efe9-3009-4efe-8cf4-4b44a4c20783', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does data volatility influence the choice of a caching strategy?', N'Middle', N'Highly volatile data requires frequent invalidation or short TTLs, making it a poor candidate for aggressive caching as it increases the risk of stale data. More static data is ideal for long-term caching, providing significant performance gains with minimal risk to consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a20590f4-8bf0-43f6-8447-4b4524a6107c', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the primary trade-off when choosing between a wide-column store and a document store for time-series data?', N'Senior', N'Wide-column stores excel at high-write throughput and efficient storage of sparse data via column-family grouping, but lack the flexible querying of document stores. Document stores provide richer indexing and retrieval capabilities but can suffer from storage overhead and write amplification due to deep object nesting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f30586f5-a90b-4dc8-bfa4-4b48ea5cb56c', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the purpose of normalizing state in a Redux store?', N'Middle', N'Normalizing state involves storing data in a flat structure, similar to a database table, rather than nesting objects. This prevents data duplication, simplifies updates to related entities, and improves performance by allowing components to select specific items by ID without traversing deep object trees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
