INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe848e58-1b13-4aed-965b-4b543c15358c', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle state persistence across the server-client boundary?', N'Senior', N'Qwik uses a process called serialization to store the application state within the HTML document. When the client takes over, it reconstructs the state object from the serialized data, ensuring that the application resumes exactly where the server left off without requiring a re-render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
