INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89e6ef69-4608-48cc-b7aa-4b562cf9cd90', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit''s reactive property system differ from React''s state management in terms of lifecycle orchestration?', N'Senior', N'Lit uses a fine-grained, decorator-based reactive system that triggers a lifecycle update specifically when a property marked as reactive changes. Unlike React''s top-down reconciliation which can trigger re-renders for entire subtrees, Lit performs localized, schedule-based updates that directly manipulate the Shadow DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a5e7e5c-11ae-4716-8351-4b568fafa627', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the common strategies for implementing rate limiting in a Node.js API?', N'Middle', N'Rate limiting can be implemented using middleware that tracks request counts in memory or an external data store like Redis. By limiting the number of requests a user can make within a specific time window, you protect your infrastructure from brute-force attacks and resource exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
