INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e35dda77-94f2-44a2-8688-4b5a4167f64a', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Explain the role of the App Router and how it differs from the Pages Router in terms of architecture.', N'Middle', N'The App Router uses React Server Components by default, allowing components to run on the server to reduce client-side JavaScript bundle sizes. It introduces advanced features like nested layouts, loading states, and error boundaries through a file-system based routing mechanism. In contrast, the Pages Router relies primarily on client-side components and traditional data fetching methods like getServerSideProps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dec2d91a-4a86-4d5e-909b-4b5f4f4c5577', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the potential drawbacks of using too many Gems in a Rails project?', N'Middle', N'Excessive use of gems can lead to bloat, security vulnerabilities, slower boot times, and dependency hell. It also increases the complexity of the application, making it harder to debug issues that arise within third-party code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b393a8ec-7723-4578-b04c-4b644ef7031a', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the primary benefit of using jQuery''s utility methods (e.g., $.extend, $.map) compared to native ES6+ methods?', N'Middle', N'jQuery utility methods were originally created to provide cross-browser functionality for common tasks like merging objects or iterating arrays. Today, native ES6+ methods like Object.assign and Array.prototype.map provide these features natively with better performance and no library dependency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd910ecff-0d9e-495a-a0be-4b65c6052aae', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why might a team choose not to use ''preact/compat''?', N'Middle', N'A team might avoid ''preact/compat'' to maintain the absolute smallest possible bundle size and to ensure they are not relying on legacy React behaviors. Using only the Preact core encourages adherence to Preact''s specific architectural philosophy and helps avoid hidden performance overheads introduced by the compatibility layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd01d5d5-eb68-4ac0-b8f0-4b69506db965', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When choosing between a relational database and a NoSQL database for a new feature, what is the most important trade-off to consider?', N'Junior', N'The primary trade-off is between structured data consistency and schema flexibility. Relational databases offer ACID compliance and complex querying capabilities, while NoSQL databases provide easier scalability and faster development cycles for unstructured or evolving data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e9a5055-baa0-48dc-8808-4b6cb0dd6f57', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Can you describe the difference between progressive enhancement and graceful degradation?', N'Fresher', N'* Graceful degradation is when you initially serve the best possible user experience, with all modern functionality, but use feature detection to “gracefully degrade” parts of your application with a fallback or polyfill. * Progressive enhancement ensures a page works at the lowest expected abilities of browsers. So if you have a JavaScript web application that enhances a persons ability to send information to a database with features like ajax – at the very least you need to provide the ability for a person to send that same information without JavaScript enabled. In this case a simple form with full-page refresh will do what you need.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'431be3aa-878c-4a23-985f-4b6d4482c23a', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a database connection pool?', N'Junior', N'A connection pool is a cache of database connections maintained so that the connections can be reused when future requests to the database are required. This improves performance by avoiding the overhead of creating a new connection for every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e5757d8-0eaf-4055-a886-4b6e616a6fd4', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the different types of SQL commands?', N'Intern', N'SQL Command Classification (2026 Audit) Modern SQL classification includes a fifth critical category: Transaction Control Language (TCL), which handles atomic state transitions. DQL is now standardly recognized as a subset of DML in formal SQL:2023/2025 specifications, though categorized separately for pedagogical clarity. Data Query Language (DQL) Focused on data retrieval. Modern analytical engines prioritize set-based operations and window functions. Keywords and Operations: - SELECT: Projects data from relations. - FROM: Identifies data sources (Tables, CTEs, Subqueries). - WHERE: Boolean filtering predicates. - GROUP BY: Aggregation grouping. - HAVING: Post-aggregation filtering. - WINDOW FUNCTIONS: (e.g., OVER(), PARTITION BY) perform calculations across related rows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'697ad2b9-1b2f-44ba-ad6a-4b7178a087d6', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of the ''Preload'' file in AdonisJS and when should it be used?', N'Middle', N'The preload file is used to execute logic during the application booting cycle, such as registering global middleware or custom event listeners. It should be used for setup tasks that must run before the server starts accepting HTTP requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38dccb99-958f-419c-8370-4b71c6021522', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you balance the trade-off between code readability and performance optimization?', N'Senior', N'I always prioritize readability first because code is read more often than it is written. I only introduce performance-oriented optimizations—which usually make code less readable—after profiling reveals a bottleneck. Premature optimization is a primary driver of technical debt, so I focus on algorithmic efficiency before moving to low-level micro-optimizations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8569011d-f555-4154-babc-4b74751536a7', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the role of the template layer in Ember?', N'Intern', N'The template layer in Ember uses Handlebars syntax to define the structure of the user interface. It binds data from the application logic to the HTML, allowing for dynamic content rendering and updates as the underlying data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f393263-85e6-4922-8fc5-4b74872853c8', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why does Go favor composition over traditional class-based inheritance?', N'Middle', N'Go utilizes interface-based polymorphism and struct embedding to promote loose coupling. This design avoids the fragility and complexity of deep inheritance hierarchies, making code easier to test, maintain, and refactor as requirements change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da670369-a394-41d5-b8f6-4b79ad305a06', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle CORS and security headers at the application level?', N'Senior', N'Litestar provides built-in middleware for CORS and security header management, which can be configured globally or per-router. This centralizes security policy enforcement, ensuring that all endpoints adhere to the same security standards without requiring individual configuration for every route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc6aa6bc-d11e-4b56-b678-4b7d8312b28d', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the role of the ''preact/compat'' package?', N'Junior', N'The compat package provides an emulation layer that allows you to use existing React libraries with Preact. It maps React-specific APIs to Preact equivalents, making it easier to migrate or use third-party tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d3a87ae-b23f-47fd-b582-4b8211edb4be', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit manage styling within components?', N'Fresher', N'Lit allows developers to define styles using a static styles property, which is then scoped to the component''s Shadow DOM. This ensures that styles are bundled with the component and only apply to the elements within that specific component''s tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6a0acde-36e1-44a7-8c74-4b860943858e', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the $el magic property?', N'Intern', N'The $el property is a magic variable in Alpine.js that provides direct access to the current DOM element where the directive is placed. It is useful for low-level DOM manipulations when necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'226134dd-013c-4e3b-ae40-4b8c6619ddc5', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why does Remix advocate for using standard HTML forms over controlled React state for mutations?', N'Middle', N'Using standard HTML forms allows the application to remain functional even before JavaScript finishes loading, a concept known as progressive enhancement. It also simplifies the development flow by removing the need for local state management, as the browser handles the submission and the server handles the resulting state transition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07a94b58-27e8-4037-a1fc-4b91009cea51', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does garbage collection work in PHP?', N'Junior', N'PHP uses a reference counting mechanism to manage memory. When the reference count of a variable drops to zero, the memory is automatically freed, and PHP also has a cyclic garbage collector to handle circular references.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46b9a364-d2f0-43d4-bc6b-4b911d0d4153', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the purpose of a route handler in Rocket?', N'Junior', N'A route handler is a function that processes an incoming request and returns a response. It is responsible for executing business logic and determining the appropriate HTTP status code and body to send back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b0967ce-3073-40e0-a1d1-4b9170d76544', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Why would you choose AdonisJS over a more lightweight framework like Express?', N'Middle', N'AdonisJS provides a batteries-included architecture with built-in patterns for security, ORM, and validation, which reduces the need for third-party libraries. This consistency makes it easier for teams to maintain large-scale applications compared to the fragmented ecosystem of unopinionated frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ecf7280-fcd6-42f5-9c39-4b92b1f80d4c', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Explain the trade-offs of using Ember Data''s ''store'' versus performing manual fetch requests.', N'Middle', N'Using the store provides built-in benefits like identity mapping, caching, and normalized data management, which significantly reduces boilerplate and ensures data consistency across the app. However, the trade-off is the library''s large bundle size and the complexity of its adapter and serializer layers, which can be overkill for small applications with simple data requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6941e394-85a6-47d4-97cd-4b92e2a6403f', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When debugging a service that intermittently fails to connect to an external API, what is your troubleshooting methodology?', N'Senior', N'I would first check the egress traffic metrics to see if the connection attempts are being throttled by rate limiters or blocked by firewall rules. I would then analyze the TLS handshake logs to determine if there are certificate validation issues or cipher suite mismatches between the client and the external provider.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2fa8a6a-177b-4ec7-ae7b-4b93ef8112ec', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is TypeScript and how does it differ from JavaScript?', N'Intern', N'TypeScript is a statically-typed superset of JavaScript, developed and maintained by Microsoft. It enables enhanced code maintainability and predictability. After compiling, TypeScript code is transpiled into standard, browser-compatible JavaScript. Key distinctions between TypeScript and JavaScript include the use of type annotations, the ability to work with existing JavaScript code, and more. TypeScript Features & Benefits - Type System: Offers static typing, allowing developers to define the type of variables, parameters, and return values. This helps catch errors during development, reducing runtime issues. - Advanced Language Features: Incorporates modern ECMAScript syntax and features, often before they are rolled out in JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12209a52-be71-4bab-82b3-4b94a06e0912', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the difference between `staticmethod`, `classmethod`, and regular instance methods.', N'Senior', N'Instance methods receive the instance as the first argument, class methods receive the class itself, and static methods receive neither. These distinctions allow developers to define the scope of data access, with static methods effectively acting as namespace-organized functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19ebc4b0-6c78-4dd2-b1ba-4b94e55f218e', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Explain the architectural trade-offs of using a centralized store like Redux compared to React Context API.', N'Senior', N'Redux provides a predictable state container with powerful middleware and debugging tools, ideal for complex state logic, whereas Context API is lightweight and built-in, best suited for low-frequency updates like theme or locale. Redux mandates strict architectural patterns that prevent prop drilling but introduce boilerplate, while Context can lead to unnecessary re-renders if not optimized with memoization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d605e7e-7cd2-41af-bdbc-4b95b3c427db', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How do C# finalizers affect the garbage collection lifecycle?', N'Senior', N'Objects with finalizers are promoted to a special ''finalization queue'' rather than being reclaimed immediately. This forces the GC to wait for a dedicated finalizer thread to process the object, typically resulting in the object surviving at least one extra collection cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a60006e4-2738-4ba5-8583-4b974e26b072', N'075b8862-431c-4678-9767-f55359758a4a', N'What are remote presets?', N'Intern', N'You can share a preset with other developers by publishing it in a git repo. The repo can be published in either github, GitLab or BitBucket. The repo will contain below files, 1. preset.json: The main file containing the preset data and it is required. 2. generator.js: A generator that can inject or modify files in the project. 3. prompts.js: A prompts file that can collect options for the generator. You can apply --preset option to use remote presets while creating the project', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95fe6f47-5322-41e1-ba4d-4b9a5c433ee1', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the benefit of using a version control system like Git when troubleshooting a regression?', N'Junior', N'Version control allows me to use techniques like binary search to identify the specific commit that introduced the bug. By comparing the state of the system before and after a change, I can pinpoint exactly what logic was modified to cause the regression.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c200b253-16b3-47ec-a09a-4b9abe01ab2f', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the primary architectural model used by Actix to handle web requests?', N'Intern', N'Actix is built on the Actor model, where independent units called actors encapsulate state and behavior. These actors communicate with each other exclusively by exchanging asynchronous messages, which allows the framework to handle high levels of concurrency efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6400127a-c25a-45ac-88cc-4b9af7575e5b', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js optimize DOM updates compared to a virtual DOM approach?', N'Senior', N'Alpine.js uses a direct-to-DOM update strategy, meaning it updates only the specific elements that are bound to the changed data. By avoiding the overhead of calculating the difference between two large virtual DOM trees, Alpine achieves faster updates for specific UI fragments, though it may become slower than a virtual DOM if a single change necessitates thousands of individual DOM updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57dce848-a352-4938-9cd2-4b9be9f6f22c', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of the ''attribute'' option in a property decorator?', N'Intern', N'The attribute option determines whether a property should reflect its value to an HTML attribute. If set to true, changing the property value updates the attribute on the custom element in the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf833b5d-75f6-4fb5-afbb-4b9df5269308', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are different scenarios causing "Exception in thread main"?', N'Intern', N'Some of the common main thread exception are as follows: * Exception in thread main java.lang.UnsupportedClassVersionError: This exception comes when your java class is compiled from another JDK version and you are trying to run it from another java version. * Exception in thread main java.lang.NoClassDefFoundError: There are two variants of this exception. The first one is where you provide the class full name with .class extension. The second scenario is when Class is not found. * Exception in thread main java.lang.NoSuchMethodError: main: This exception comes when you are trying to run a class that doesn''t have main method. * Exception in thread "main" java.lang.ArithmeticException: Whenever any exception is thrown from main method, it prints the exception is console.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8efb123-59b9-4377-a437-4b9e359a4a3a', N'954a0331-deff-4399-b588-96f39fec001d', N'What are HTTP interceptors and how are they used?', N'Intern', N'HTTP interceptors in Angular are services that you can use to inspect and transform HTTP requests and responses before they are sent or processed. They provide a way to handle HTTP operations globally for your application. You can use them for common tasks like: - Adding authentication tokens to outgoing requests - Logging requests and responses - Handling errors centrally - Caching responses - Modifying request or response headers To create one, you implement the HttpInterceptor interface and provide it using the HTTP_INTERCEPTORS injection token with multi: true. Then, register it in your module''s providers: > Try out Angular coding questions on GreatFrontEnd. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd21796c-1e72-475f-919d-4b9f1d73a181', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of the ''next'' function in Express?', N'Intern', N'The ''next'' function is a callback that, when invoked, passes control to the subsequent middleware function in the stack. If it is not called, the request cycle will hang, and the client will not receive a response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4337824-e6dc-4910-9069-4ba0d27a52f8', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are arbitrary values in Tailwind CSS?', N'Intern', N'Arbitrary values allow you to use custom styles that fall outside the defined design system, such as a specific pixel value or color hex code. You use square brackets within the class name to apply these one-off values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f79b417e-e51c-4a6d-ab36-4ba391a7b2d6', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is an asynchronous action in Redux?', N'Fresher', N'Standard Redux actions are synchronous, but asynchronous actions are used for tasks like fetching data from an API. Since reducers must be pure, middleware is typically used to handle the asynchronous logic before dispatching the final action.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76825150-d1a9-4ba4-a374-4ba41529e090', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are route handlers, and how would you implement them?', N'Intern', N'Route handlers in Express.js are middleware functions designed to manage specific paths in your application. Depending on the HTTP method and endpoint, they can perform diverse tasks, such as data retrieval from a database, view rendering, or HTTP response management. Code Example: Setting Up a Simple Route Handler Here is the code: In this example, the route handler is (req, res) => { res.send(''Hello, World!''); }. It listens for GET requests on the root URL and responds with "Hello, World!".', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08fa1b2b-a535-4ef3-9b2c-4ba500daf39b', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How would you architect a graceful shutdown strategy for an Express application to ensure no requests are dropped?', N'Senior', N'A graceful shutdown involves catching termination signals, stopping the server from accepting new connections, and waiting for existing inflight requests to complete before closing database connections. This ensures data integrity and prevents abrupt client disconnections during deployment cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27db2997-7dc8-4d3f-88c7-4ba81780f0b0', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle routing performance compared to traditional regex-based routers?', N'Middle', N'Hono utilizes a highly optimized trie-based router. This structure allows for constant-time complexity lookups regardless of the number of registered routes, which is significantly faster than linear regex matching as the application grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72cc9020-1800-4078-895a-4ba9b04ab656', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono''s middleware order affect application logic?', N'Middle', N'Middleware in Hono executes in the order it is registered, following a onion-like architecture. If a middleware returns a response or throws an error, subsequent middlewares and the route handler are skipped, which is critical for implementing guards like authentication or rate limiting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7dd1e93c-9acc-43a3-ac56-4ba9d235e70b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you defend against supply chain attacks in a JavaScript ecosystem?', N'Fresher', N'Supply chain attacks target dependencies, build tools, and CDN resources rather than your application code directly. Defending against supply chain attacks in JavaScript requires securing three distinct vectors: * third-party packages (npm), * build-time infrastructure (CI/CD), and * runtime execution (the browser). 1. Lock Down the Registry & Dependencies (Package Time) The primary entry point for malicious code is the npm registry through typosquatting, account takeovers, or compromised dependencies * Enforce Dependency Pinning: Never use loose version ranges (^ or ~). Pin your versions exactly and commit your package-lock.json, pnpm-lock.yaml, or yarn.lock to ensure identical builds across environments. * Run Manifest Validation: Use tools like lockfile-lint in your pre-commit hooks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc2fd912-f5e9-4545-8426-4baa1dc23144', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the memory alignment considerations in Go structs.', N'Senior', N'Go structs are subject to memory alignment rules where fields are placed at offsets that are multiples of their size to ensure efficient CPU access. Padding bytes are inserted between fields to satisfy these constraints, which can impact the overall memory footprint of the struct. Senior developers optimize memory usage by ordering fields from largest to smallest to minimize this padding overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'253089b8-901c-40e9-b55a-4baba56f4cce', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain how to manage application-level state in a multi-process environment.', N'Senior', N'Since Flask processes do not share memory, application-level state must be stored in an external, shared data store like Redis or a database. Attempting to store state in global Python variables will lead to inconsistent behavior as requests are distributed across different worker processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17203aeb-2843-4487-baca-4baeef430662', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Discuss the implications of PHP''s late static binding in class inheritance.', N'Senior', N'Late static binding enables a class to reference the calling class in a static context, rather than the class where the static method is defined. This is essential for building flexible ORM-style architectures where base classes need to access dynamic properties of child classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdf18981-ae2b-4372-8242-4baf9f0019fa', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Explain how Axum''s architecture supports hot-reloading or modular service growth.', N'Senior', N'Axum''s modular routing design allows developers to define independent sub-routers that can be combined into a single application. This structure supports a clean separation of concerns, enabling teams to develop and test different API modules independently before aggregating them into the main service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc781373-937b-490b-90c9-4bb2548db6f8', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart manage ''Isolate'' communication without shared memory?', N'Senior', N'Dart uses ports to send messages between isolates. When a message is sent, the object is serialized and copied or moved to the receiving isolate''s heap, ensuring that no two isolates ever access the same memory location simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'995db071-0ade-40f5-8f29-4bb70396302b', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the purpose of the ''super()'' function in inheritance?', N'Middle', N'The ''super()'' function returns a proxy object that delegates method calls to a parent or sibling class according to the MRO. It is essential for cooperative multiple inheritance, ensuring that every class in the hierarchy is initialized properly and that methods are called in the correct order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
