INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'102a96d7-c525-431e-9e6b-4bb8991701cc', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do variables work in Sass?', N'Intern', N'Variables in Sass allow you to store reusable information like colors, font stacks, or spacing values. You define them using a dollar sign prefix, and they help ensure consistency across your entire project by allowing you to change a value in one place instead of many.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8356094-680d-4e85-ba76-4bbbe2ca9ec4', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the purpose of the ''MethodNotAllowed'' handler in Chi?', N'Intern', N'This handler is triggered when a request matches a defined URL path but uses an HTTP method that is not supported for that specific route. It helps provide clear feedback to the client about allowed actions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb43f581-a90f-4b65-a6bf-4bbe1c096728', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the difference between embedding and referencing in MongoDB data modeling?', N'Junior', N'Embedding stores related data within a single document, which is efficient for read operations. Referencing involves storing related data in separate documents and linking them, which is better for avoiding data duplication and handling large data relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e9f4865-e60f-467b-a1a0-4bc0daf8a33f', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Explain the architectural advantages of using ''Render Props'' for cross-cutting concerns.', N'Senior', N'Render props allow developers to share behavior between components without creating deep inheritance trees. By inverting control, the parent component provides the logic while the child determines the layout, promoting high cohesion and flexibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
