INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b774ad7b-afc1-4af9-ad82-4bc2e8aef329', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'An application is crashing consistently. What is your first step to troubleshoot?', N'Fresher', N'The first step is to isolate the issue by reproducing the crash in a controlled environment. I would check the error logs to identify the specific exception or signal that caused the termination.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'598005bd-ca4e-4293-960b-4bc337174c1d', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What does the .val() method do?', N'Junior', N'The .val() method is primarily used to get or set the current value of form elements such as inputs, selects, and textareas. It is the standard way to retrieve user input from a form field in jQuery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
