INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0abdb79f-9f27-4712-a433-4bc3e167d476', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What happens if you use an undefined variable in Sass?', N'Junior', N'The Sass compiler will throw an error and stop the build process. This is actually a benefit, as it helps catch typos or missing dependencies early in development before the code reaches the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'243a4bb5-b401-4abb-84af-4bc6f2b1a12c', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is a ''hot shard'' problem?', N'Middle', N'A hot shard occurs when one specific shard receives a disproportionately high amount of traffic compared to others. This leads to uneven resource utilization and bottlenecks, requiring better sharding keys or rebalancing strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b20d6f7a-05e6-49c0-8093-4bc92792ffd4', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How do background tasks work in FastAPI, and what is their limitation?', N'Middle', N'Background tasks allow you to execute logic after returning a response to the client, which is useful for sending emails or processing logs. However, these tasks run within the same process memory space; if the server crashes before completion, the tasks are lost, making them unsuitable for mission-critical, persistent jobs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86ca4047-5e50-4682-bae5-4bcb8546e6b7', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the role of the BodyParser middleware?', N'Intern', N'The BodyParser middleware is responsible for parsing the incoming request body. It converts data formats like JSON or form-encoded strings into a readable JavaScript object for use in controllers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab2ff026-a4c4-455c-ad61-4bcbeb1a4596', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go ensure memory safety without a runtime virtual machine?', N'Middle', N'Go enforces strict type safety and bounds checking on arrays and slices to prevent buffer overflows. Combined with garbage collection and the prevention of pointer arithmetic in safe code, these features provide a high-level of memory security while still compiling down to native machine code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6659c399-53b1-4ce1-9bd6-4bcc1b6c8057', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are break and continue statements', N'Intern', N'The break statement is used to "jump out" of a loop. i.e, It breaks the loop and continues executing the code after the loop. The continue statement is used to "jump over" one iteration in the loop. i.e, It breaks one iteration (in the loop), if a specified condition occurs, and continues with the next iteration in the loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bbecd96-e4c5-469c-b1cd-4bd01b635a17', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the purpose of the load function''s ''fetch'' parameter?', N'Junior', N'The fetch parameter provided by SvelteKit is a wrapped version of the standard browser fetch. It allows for server-side data fetching that can handle relative URLs and pass cookies automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5ebd650-6f94-40a3-8306-4bd29ef78d10', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte ensure high performance compared to other frameworks?', N'Junior', N'Svelte achieves high performance by compiling components into highly efficient imperative code that surgically updates the DOM. Because it lacks a runtime virtual DOM diffing process, it consumes less memory and CPU during updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
