INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bf4e35c-2e74-46d7-a8ee-4bd5ab1469f2', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum ensure zero-cost abstractions in its handler architecture?', N'Senior', N'Axum achieves performance through extensive use of generics and the Rust compiler''s ability to monomorphize code. By resolving dependencies at compile-time via traits, it avoids unnecessary dynamic dispatch and runtime lookups, resulting in an execution path that is highly optimized by the backend compiler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad58d6a2-a2d5-4f68-ad27-4bd939bf1ba7', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Describe the trade-offs of using standard VDOM vs. Signals in Preact.', N'Senior', N'VDOM is excellent for general-purpose declarative UIs, but it requires re-calculating the tree on every state change. Signals provide a surgical approach by updating only the affected DOM nodes, which is significantly faster for high-frequency updates but requires more careful management of state dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fdf93e6-1fde-44c2-8869-4bdc3edfae9e', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the difference between a synchronous and asynchronous approach to handling background tasks in Symfony using Messenger?', N'Middle', N'A synchronous approach executes tasks immediately within the current request-response cycle, which can delay the user''s experience. An asynchronous approach offloads these tasks to a message queue handled by background workers, improving performance by allowing the user to receive a response immediately while the task processes in the background.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
