INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fbbe775-a40e-49ae-a2e6-4beccac5c60e', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How do database locks affect concurrency, and what is the difference between pessimistic and optimistic locking?', N'Middle', N'Pessimistic locking prevents conflicts by locking resources as soon as they are accessed, which can reduce throughput. Optimistic locking assumes conflicts are rare and only checks for data changes at the time of the update, which is better for high-concurrency read-heavy environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29cc40ec-38bd-43ab-83af-4bf2896d1cde', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Explain the concept of ''Transaction Contention'' in the context of DynamoDB.', N'Senior', N'Transaction contention occurs when multiple concurrent transactions attempt to modify the same items, leading to lock conflicts and transaction failures. Applications must implement robust retry logic and exponential backoff to handle these transient conflicts gracefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
