INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b7e995c-f068-4235-b5db-4bf7fd3d6d32', N'4c000000-0000-0000-0000-000000000005', N'What are the advantages of using a Message Queue over direct API calls?', N'Senior', N'Message queues enable temporal decoupling, allowing services to process requests at their own pace without overwhelming downstream systems. They also provide built-in buffering and durability, which improves overall system reliability during traffic spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcdc8dde-597d-4384-bc40-4bf83c4a3080', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the ''box-sizing'' property affect layout calculations?', N'Middle', N'The default ''content-box'' model calculates width and height based only on content, with padding and borders adding to the total size. The ''border-box'' model includes padding and borders within the specified width and height, which simplifies layout math significantly. ''Border-box'' is widely considered the industry standard for easier component sizing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd87e7d4f-9a58-4959-bd59-4bf94e801a15', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the role of the ''c'' variable in Hono handlers?', N'Junior', N'The ''c'' variable stands for Context. It is the primary interface used to interact with the request, send responses, handle headers, and access environment variables in every route handler and middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49ac42ba-19ed-4bd7-9c0e-4bfa2bbe5e8a', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How do you handle schema evolution in a NoSQL document database versus a SQL database?', N'Senior', N'SQL databases typically require explicit ALTER TABLE statements that may lock tables, making migrations risky for large datasets. Document databases handle schema evolution implicitly at the application level, allowing for polymorphic data structures, though this requires the code to handle multiple versions of the data schema simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f60eb01-e012-4c23-b854-4bfc3db1e976', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are factories in Dart?', N'Fresher', N'A factory constructor is a special type of constructor used when you do not always want to create a new instance of a class. It can return an existing instance, a cached instance, or an instance of a subclass.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ad068e3-964b-488e-9dea-4c04a0334224', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why should you document your troubleshooting steps even if you fix the problem quickly?', N'Fresher', N'Documenting steps ensures that the solution is recorded for future reference, allowing the team to understand the root cause. It also prevents the same issue from being treated as a new problem if it recurs, saving time in the long run.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1753355f-2986-461e-99d8-4c08e6ba1f35', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you determine if a performance issue is caused by the database or the application layer?', N'Middle', N'I would start by analyzing query execution plans and database connection pool metrics to rule out bottlenecks like missing indexes or long-running transactions. If the database metrics are healthy, I would then profile the application code to identify heavy computation or inefficient data processing occurring in the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcda6de8-22cd-4330-8c2d-4c0965204eb2', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a Relational Database Management System?', N'Intern', N'A Relational Database Management System is software that manages data organized into tables with rows and columns. It uses structured query language to interact with data and ensures relationships between different tables are maintained. Common examples include MySQL, PostgreSQL, and SQL Server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c519a5f-dd70-4678-b7b5-4c0a26f09796', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What are the trade-offs of using horizontal pod autoscaling versus vertical pod autoscaling?', N'Middle', N'Horizontal scaling improves throughput and availability by adding more instances but requires the application to be stateless and the load balancer to support distribution. Vertical scaling is simpler for resource-constrained applications but has a physical limit based on the node size and usually requires a restart to apply changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30bd24c6-d59f-49a8-be2f-4c0db2ac8d77', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'When should you use ''NoTracking'' queries in Entity Framework Core?', N'Middle', N'NoTracking queries should be used when you are only reading data and do not intend to modify it or save changes back to the database. This improves performance because the change tracker does not need to set up snapshots or monitor the entities for changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
