INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b27b3d71-a49a-49f6-a590-4c16e5255b16', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte approach the ''hydration'' problem for SEO and performance?', N'Senior', N'Svelte''s SSR generates static HTML that is immediately crawlable by search engines. The hydration process then maps the static elements to the reactive logic, which is highly efficient because the structure of the DOM is already known, preventing the ''flicker'' associated with heavy client-side rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
