INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed02f575-7571-436e-b9af-4c2159749098', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is it better to fail early in a process rather than late?', N'Junior', N'Failing early allows you to identify issues while the scope of the problem is still small and easy to fix. Waiting until the end of a project makes bugs much more expensive and time-consuming to resolve.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16912fe6-d4b5-456f-8272-4c22e81dac6d', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are the advantages of using ''Fiber'' for concurrency?', N'Middle', N'Fibers are light-weight, cooperatively scheduled primitives that allow for pausing and resuming execution at explicit points. Unlike threads, which are preemptively scheduled by the OS, fibers give the developer manual control over context switching, reducing overhead for I/O-bound tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb3c9090-7fc9-41c2-b40b-4c23081bcf9b', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How do Ruby''s ''Binding'' objects facilitate the implementation of Domain Specific Languages (DSLs)?', N'Senior', N'A Binding object captures the execution context, including local variables and the value of self, at a specific point in time. This allows developers to evaluate code within a controlled scope, which is the foundational mechanism for building DSLs that provide custom syntax while maintaining access to existing state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
