INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f3305b7-7ba6-4517-a0a3-4c2a28f84da4', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix handle errors in handlers?', N'Intern', N'Actix uses the ''ResponseError'' trait to map internal application errors into valid HTTP responses. This allows developers to return custom error types from handlers while ensuring the client receives a meaningful HTTP status code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e51427bc-793a-4a37-907f-4c2c2410eab2', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum utilize Tower middleware compared to standard HTTP middleware?', N'Senior', N'Axum is built directly on the Tower ecosystem, treating middleware as services that transform requests and responses. This allows for fine-grained control over the request lifecycle, enabling developers to compose complex, reusable layers like rate limiting or authentication as modular components that integrate seamlessly into the routing tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c8fa856-941b-4179-84c9-4c2d80ae70ed', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the difference between a context object and a request object in Hono?', N'Fresher', N'In Hono, the context object is a wrapper that provides access to the request, the response, and helper methods for setting status codes or sending JSON data. While the request object contains only raw incoming data, the context object simplifies the process of building the response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0483a7a-3f38-4b26-aebb-4c2db83980d3', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How do you handle errors in a Phoenix application?', N'Junior', N'Phoenix uses a centralized error view module to handle common HTTP errors like 404 Not Found or 500 Internal Server Error. For logic errors, developers typically use pattern matching or check changeset errors to return appropriate feedback.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cba469f0-1223-492c-b703-4c2dc267882d', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How can you implement circuit breakers within a NestJS ecosystem to handle downstream service failures?', N'Senior', N'Circuit breakers can be implemented using custom interceptors or dedicated library wrappers that monitor request success rates to downstream services. If failure thresholds are met, the circuit opens, preventing further requests to the failing service and allowing it time to recover, thus increasing system resilience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'099d7b6e-4886-4d50-94fc-4c3206133557', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How do you handle query parameters in Fastify?', N'Fresher', N'Query parameters are automatically parsed by Fastify and made available in the query property of the request object. You can define a schema for these parameters to ensure that incoming data meets specific requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ac87bb3-7c73-4256-a536-4c325359a849', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the significance of the ''max_wal_size'' setting in the context of system throughput.', N'Senior', N'This setting controls the maximum size the WAL can reach before a forced checkpoint is triggered. A larger value reduces the frequency of checkpoints and improves write throughput, but increases the time required for crash recovery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d4315b5-11f4-404f-80c2-4c32bf86b023', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How do database engines determine whether to use a nested loop join, a hash join, or a merge join, and what are the cost implications for large-scale datasets?', N'Senior', N'The query optimizer evaluates the estimated cardinality of input sets, the availability of indices, and whether data is pre-sorted to select the join algorithm. Nested loop joins are efficient for small datasets or when the inner input is indexed, hash joins are preferred for large, unsorted datasets where a hash table can fit in memory, and merge joins are optimal when both inputs are already sorted. Choosing the wrong algorithm can lead to exponential performance degradation, particularly if a hash join spills to disk or a nested loop results in excessive random I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee31bf02-19e6-4317-8d70-4c358601977f', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik ensure SEO-friendly pages?', N'Middle', N'Since Qwik performs full server-side rendering, it serves complete HTML to search engine crawlers. This ensures that all content is indexed correctly without relying on client-side execution, which is a major advantage over traditional single-page application architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'445f8864-fc04-46ee-8be6-4c35e32f9278', N'4c000000-0000-0000-0000-000000000005', N'What is the ''Thundering Herd'' problem and how do you mitigate it at the architectural level?', N'Senior', N'The thundering herd occurs when many processes wake up simultaneously to handle a task, such as cache expiration, overwhelming the backend. Mitigation involves jittering expiration times, using probabilistic early recomputation, or implementing request coalescing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0618a67-7e4f-40d4-85d1-4c36d77a50d9', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why might you choose a synchronous API over an asynchronous messaging system?', N'Junior', N'Synchronous APIs are simpler to implement and debug because the request and response happen in a single, predictable flow. Asynchronous systems are more resilient and scalable but introduce complexity in tracking status and handling partial failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4a356ba-74ae-4158-ac02-4c3cc31723eb', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does the ''preHandler'' hook differ from the ''preValidation'' hook?', N'Middle', N'PreValidation handles the integrity of the input, while preHandler runs after validation but before the main route handler. PreHandler is the correct place to perform business-specific checks, such as verifying if a user has permission to access a specific resource.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8f71dfe-4f94-488f-93a8-4c42932aebca', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a system for massive scale, how do you handle the trade-off between latency and data freshness?', N'Senior', N'I employ aggressive caching layers and content delivery networks to serve stale data where latency is critical. I then use background asynchronous processes to refresh the cache, ensuring the user experience remains fast while the underlying state eventually converges.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a042bd0c-06c2-4712-bafe-4c42ec868070', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to prevent infinite loops with useEffect?', N'Fresher', N'Infinite loops happen when the effect updates state that’s listed in its own dependency array, which causes the effect to re-run, updating state again and so on. Infinite loop scenario: You need to ensure that setState calls do not depend on values that cause the effect to rerun, or isolate them with a guard.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'295eed1f-fdc7-4849-a3e2-4c4872dcdc33', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you prioritize tasks when you have multiple urgent requests?', N'Intern', N'I would evaluate each task based on its impact on the user, the urgency of the deadline, and its dependencies on other work. I would then consult with my supervisor to align my priorities with the team''s overarching goals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
