INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f43c14c2-2925-42f8-a2f5-4c4bcd0c4859', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are the limitations of Preact regarding support for advanced React ecosystem tooling like Concurrent React or Suspense?', N'Senior', N'While Preact supports Suspense, it does not support full Concurrent rendering, meaning it cannot transition between UI states as fluidly as React in highly complex scenarios. This makes it less suitable for applications requiring heavy data orchestration or complex concurrent UI flows that demand non-blocking rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e528bf1a-9e74-4c9a-882e-4c4dc37ce6a2', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How is memory allocation and garbage collection handled in Python?', N'Fresher', N'In Python, memory allocation and garbage collection are managed automatically by the runtime, primarily through the Python Memory Manager. This system abstracts complex memory operations, ensuring safety and developer productivity. Memory Allocation Python manages a private Heap containing all objects and data structures. The Python Memory Manager controls this heap through several layers: * Hierarchical Allocation: For small objects ($\le 512$ bytes), Python uses a specialized allocator called obmalloc. It organizes memory into Arenas ($256$ KB), which are subdivided into Pools ($4$ KB), and further into Blocks. * Object-Specific Allocators: Certain types (like int or list) use dedicated free lists to speed up allocation and reduce fragmentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5567e62-95d4-4665-9e9b-4c563674817e', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum''s error handling model differ from frameworks that use global exception handlers?', N'Senior', N'Axum encourages local error handling via the ''IntoResponse'' trait, where individual handlers map their specific error types to HTTP responses. This keeps error handling logic coupled to the handler''s business domain, avoiding the maintenance issues of large, monolithic exception-handling structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28cb9e4d-819c-491b-becc-4c5696b46335', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why is Preact often preferred for projects with strict performance budgets?', N'Middle', N'Preact has an incredibly small library size, typically under 4KB, which significantly reduces the time to interactive for mobile users. By minimizing the amount of JavaScript that needs to be parsed and executed, it allows applications to load and become functional much faster on low-end devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2365edac-7934-4c7c-994b-4c57d5b70de6', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the advantage of using Axum''s type-safe routing?', N'Intern', N'Type-safe routing ensures that parameters extracted from a URL or body match the expected types defined in the handler function. This helps catch errors at compile-time rather than runtime, leading to more reliable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f23941e-b0c1-44de-a0cb-4c59236be209', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Describe the trade-off of using Micronaut''s AOT compilation versus the flexibility of runtime-based frameworks.', N'Senior', N'The primary trade-off is that AOT compilation makes it more difficult to dynamically change application behavior at runtime based on external configuration that requires deep introspection. However, the gains in startup speed, memory efficiency, and native image readiness are usually superior for cloud-native architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
