INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef980ee4-53ad-4f64-b5bf-4c5e056a639d', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the ''Isolation'' property''s main objective?', N'Middle', N'The isolation property ensures that the concurrent execution of transactions results in a system state that is the same as if the transactions had been executed serially. It prevents intermediate states of one transaction from being visible to others, maintaining logical independence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'489f9b37-e8f5-46f7-900d-4c5f0f123533', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does the borrow checker help prevent race conditions?', N'Fresher', N'The Rust-type system, especially the borrow checker, ensures memory safety and preemptively addresses issues like race conditions. Data Race in Rust Let''s use the following Rust example. Even though counter is defined in a single-threaded context, if both threads try to modify it simultaneously, it results in a data race. Rust, however, is designed to detect and prevent such scenarios during compilation. Key Points - Ownership Transfer: &mut T references enable exclusive access to T, but with limited scope. This is established through the concept of _owner_ and _borrower_. - Lifetime Annotations: By specifying how long a reference is valid, Rust ensures that references outlive the data they''re accessing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da346481-039a-4641-9206-4c63f5a68be7', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the benefit of breaking down a large task into smaller sub-tasks?', N'Junior', N'Breaking down tasks makes the overall effort easier to estimate and track while providing clear milestones for progress. It also helps in identifying potential blockers early and allows for better focus on solving one specific problem at a time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f219054a-98bd-42ab-9f63-4c6470ca1d45', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the role of the Micronaut Annotation Processor?', N'Intern', N'The annotation processor runs during the compilation phase to analyze the code and generate metadata. This metadata allows the framework to perform dependency injection and routing without relying on slow runtime reflection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29433a22-4ce6-4bab-a8f9-4c665229b75e', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is a ''handler'' in the context of Hono?', N'Fresher', N'A handler is a function that defines the logic to be executed when a specific route is matched by the application. It receives the context as an argument and is responsible for returning a response to the client, such as a JSON object, HTML, or an error message.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43cb96ed-6bfc-43f6-b0e2-4c66821cb889', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Describe how Ember''s ''Testing Helpers'' enable behavior-driven development.', N'Senior', N'Ember provides a suite of testing helpers that simulate user interactions, such as clicking, typing, and waiting for asynchronous assertions. These helpers abstract away the low-level DOM events and timing issues, allowing developers to write tests that describe what the user does rather than how the component internals function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00c0c7a0-60d6-48ba-bb15-4c671ebd4f8d', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Describe the impact of ''Boxing'' on the .NET runtime.', N'Senior', N'Boxing converts a value type into an object, forcing it to be allocated on the heap and wrapping it with metadata. This introduces significant overhead due to memory allocation and subsequent garbage collection. It also adds a layer of indirection, which can hinder CPU cache locality and increase the cost of type checking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d44ef46-c2c9-40cd-8b9d-4c67ae2b9462', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django’s middleware stack affect performance and request latency?', N'Senior', N'Every request passes through the entire middleware stack sequentially, and every response does the same. Heavy operations in middleware—like database lookups or external API calls—add cumulative latency, so middleware should be kept lightweight and used only for cross-cutting concerns like authentication or logging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5df927d1-950d-4d62-aa80-4c691a01dff6', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Does Fiber support static file serving?', N'Intern', N'Yes, Fiber has built-in support for serving static files like images, CSS, and JavaScript from a specified directory. This is typically configured using a dedicated function that maps a virtual path to a folder on the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2c0e348-8cd7-43e2-93b0-4c6b0d2794c8', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the impact of the ''multi/exec'' transaction block on Redis performance?', N'Senior', N'While these commands ensure atomicity for a sequence of operations, they do not provide rollback capabilities in the event of errors. Using them excessively can increase latency because the server must queue all commands before execution, which may block other clients if the transaction is large.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9478e83-282f-4bf0-a7e9-4c6bcece3cc3', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of the @Introspected annotation?', N'Junior', N'The @Introspected annotation tells Micronaut to generate bean introspection metadata at compile time. This is essential for frameworks that need to access bean properties without using reflection, such as JSON serializers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f00acfd-fcef-4964-acb7-4c6d758226b6', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is ''post-mortem'' analysis important in the debugging process?', N'Middle', N'A post-mortem analysis documents the timeline, root cause, and resolution of an incident, which helps the team identify systemic gaps in processes, testing, or architecture. It prevents the same issue from recurring by turning a reactive troubleshooting effort into a proactive improvement in system reliability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3769f30-15ee-4ebd-8be5-4c6f837d9f0e', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the purpose of the $: syntax in Svelte?', N'Fresher', N'The $: syntax is used to define reactive statements. Any code prefixed with this label will automatically re-run whenever the variables referenced inside it change, ensuring that derived state is always kept in sync.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
