INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1585aebc-7a2d-4763-b75a-4c70db13ef9b', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between a DELETE and a TRUNCATE command?', N'Fresher', N'DELETE is a DML command used to remove rows based on a condition and logs each deletion, which is slower. TRUNCATE is a DDL command that removes all rows from a table quickly by resetting the table structure without logging individual row deletions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63596832-c6bc-40ee-bb4a-4c71f3c704ca', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the Go memory allocator utilize ''mspan'' and ''mcache'' to optimize performance?', N'Senior', N'The allocator uses a multi-level structure where ''mcache'' provides thread-local storage for small objects to avoid lock contention, while ''mspan'' manages memory pages. This tiered architecture minimizes synchronization between processor cores and provides efficient allocation patterns for objects of varying sizes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf0e1d05-adb2-4cd4-ba26-4c75a0732924', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut''s ahead-of-time (AOT) compilation model differ from the reflection-based approach used by Spring?', N'Senior', N'Micronaut moves the heavy lifting of dependency injection and bean wiring to compile time rather than runtime. By generating bytecode at build time, it eliminates the need for reflection and classpath scanning during application startup, significantly reducing memory consumption and startup latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
