INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ec2d043-8106-4b08-9448-4c906155dc26', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you design a system that handles long-running background tasks without blocking user requests?', N'Senior', N'I would move long-running operations to an asynchronous worker queue, where the request is immediately acknowledged by the system. The task is then processed by background workers, and the status is tracked via a database or polling mechanism, with the client notified via webhooks or WebSockets upon completion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
