INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2efcf6c6-265e-4300-9185-4c9654a9f0af', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the impact of data modeling in NoSQL compared to relational databases?', N'Middle', N'In relational databases, you model data based on the structure and relationships, often normalizing to reduce redundancy. In NoSQL, you must model data based on your application''s query patterns, often denormalizing or embedding data to optimize for speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
