INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21d9cab0-72dd-4dc5-b2ad-4ca6db950f2a', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the role of ''Result'' types in Swift''s error handling?', N'Middle', N'The Result type is an enum that encapsulates either a success value or a failure error, providing a functional way to handle errors in asynchronous code. Unlike traditional ''do-catch'' blocks, it allows errors to be passed around as first-class values in completion handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9123a7d5-e61a-4e47-bc6f-4ca7a30d8e7c', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the ''Closed World Assumption'' in the context of GraalVM and Quarkus?', N'Senior', N'The Closed World Assumption is a prerequisite for native compilation where the compiler must know all reachable code paths at build time. This prohibits dynamic features like runtime class generation or bytecode manipulation, forcing Quarkus to resolve these statically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2b76ad2-d732-4d85-8b4a-4ca7f50189d0', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the main advantage of the ''HttpFoundation'' component?', N'Middle', N'HttpFoundation provides an object-oriented abstraction over the global PHP superglobals. By wrapping requests and responses in objects, it makes code significantly easier to test, as you can easily mock these objects instead of relying on the server''s global state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3d963c4-8446-4aa2-86eb-4caa4facee16', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between public, private, protected, and default access modifiers?', N'Junior', N'Public access allows visibility from any class, while private restricts access to within the same class only. Protected allows access within the same package and subclasses, and default access limits visibility to only classes within the same package.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fca103f-6528-4efa-aa53-4cab9b1060ff', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a foreign key?', N'Intern', N'A foreign key is a field in one table that links to the primary key of another table. It is used to establish and enforce a relationship between two tables, ensuring referential integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f40d31e-a459-4578-884e-4cac4de15ca8', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the purpose of ''nextTick'' in Vue?', N'Middle', N'Vue performs DOM updates asynchronously after a data change cycle. The nextTick method allows you to execute a callback function after the next DOM update cycle has finished, which is useful when you need to access the DOM elements after Vue has rendered the latest state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'568d46f2-f7dd-4176-b417-4cad02492980', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does ASP.NET Core handle cross-origin resource sharing (CORS) security, and what are the risks of misconfiguration?', N'Senior', N'CORS policies in ASP.NET Core define which origins, methods, and headers are permitted to access the API. Misconfiguration, such as allowing all origins or overly permissive credentials, can lead to unauthorized data access and expose the application to cross-site data theft.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bee7dc1e-2f0e-4d7d-8b8b-4caddd3fdfd1', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does the Dart compiler handle generic type erasure?', N'Senior', N'Dart does not fully erase generic types; it uses reified generics, meaning type information is preserved at runtime. This allows developers to perform type checks like ''is List '' which would be impossible in languages that use complete type erasure, although it does introduce a minor memory overhead for storing type metadata.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79099fc8-a807-4c68-81c4-4cae5d8ef7d7', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you maintain focus when working on a long, repetitive task?', N'Fresher', N'I break the task into small milestones to maintain a sense of accomplishment. I also take short, scheduled breaks to stay refreshed and keep my attention sharp throughout the process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc6fdfdc-bf72-4d5c-b371-4cb0536c3dc5', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind handle vendor prefixing and browser compatibility?', N'Middle', N'Tailwind integrates with Autoprefixer under the hood to automatically add vendor prefixes to the generated CSS. This ensures that the utility classes function consistently across all target browsers defined in the project''s browserlist configuration without manual developer intervention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00ff2b83-ab48-4c64-93d3-4cb343012a59', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What are the trade-offs of using a read replica?', N'Middle', N'Read replicas improve read performance and provide high availability by offloading read traffic from the primary database. The trade-off is the introduction of replication lag, meaning read replicas may not always return the most up-to-date data compared to the primary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06f06720-98f7-4e2a-9087-4cb45ba565d0', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between building a custom internal tool versus adopting an off-the-shelf third-party solution?', N'Senior', N'I evaluate whether the capability is a core differentiator for the business; if it is, I build it to maintain total control and competitive advantage. If the capability is a commodity, such as authentication or payment processing, I prioritize buy-to-integrate to reduce time-to-market and operational maintenance burden.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c185a03-99ee-46ec-9cac-4cb56932e243', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is ''props'' destructuring in SolidJS?', N'Intern', N'In SolidJS, props are reactive objects that should not be destructured using standard JavaScript syntax. Destructuring them would break the reactivity, so the framework provides a specific utility to maintain the reactive connection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4890c2b7-3f61-4a6a-88ff-4cb5cc6908ea', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the distinction between ''Type Widening'' and ''Type Narrowing'', and why is it critical for type safety?', N'Senior', N'Widening occurs when a variable is initialized with a literal that gets promoted to a broader base type, potentially losing specificity. Narrowing uses control flow analysis—such as type guards—to refine a broad type into a more specific one, ensuring operations are safe within a conditional block.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb6d5f5c-abc0-48e1-899d-4cb6e0ad60b9', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Explain the architectural trade-offs of SvelteKit''s ''load'' functions running on the server versus the client.', N'Senior', N'Running load functions on the server allows for secure data fetching with direct database access and reduced client-side latency via initial HTML streaming. Running them on the client minimizes server load but introduces potential security risks if sensitive credentials are leaked and increases the time-to-interactive for data-heavy applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48335aee-2bf1-4080-8557-4cb8cf9a29ee', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the role of the ''action'' function in Remix, and how does it relate to the browser''s native form submission?', N'Middle', N'The action function acts as a server-side handler for mutations such as POST, PUT, or DELETE requests. It mimics the behavior of native HTML forms, allowing the application to function without JavaScript by submitting data directly to the server. When JavaScript is enabled, Remix intercepts these submissions to perform a seamless client-side transition, providing a progressive enhancement architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'347e8c2f-5386-4d58-a84c-4cbc82928da3', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Can you define methods on a single specific object instance?', N'Fresher', N'Yes, Ruby allows for singleton methods, which are methods defined for a specific object instance rather than the entire class. This is done by defining the method directly on the object using its name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a8d7f67-882f-42eb-aec2-4cbdbaf8f074', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the ''Dependency'' class used for?', N'Junior', N'The ''Dependency'' class is used to mark a function parameter as something that should be resolved by the dependency injection system. It tells Litestar that the value should be fetched from the global or request-specific dependency context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fbf589f-73f6-466d-866a-4cbdddcc24a4', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Compare the impact of Express''s error handling middleware versus global ''uncaughtException'' handlers.', N'Senior', N'Express error middleware allows for localized recovery and clean response generation for specific request errors, maintaining process stability. Conversely, global uncaught exception handlers are typically used as a last resort to log errors and exit the process, as the application state may be corrupted after an unhandled exception.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6e71b8b-a1a1-49f3-8966-4cbdf8e0a7ec', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Are Remix routes file-based?', N'Intern', N'Yes, Remix uses a file-based routing system where the file structure inside the routes directory directly maps to the application''s URL paths. This makes it intuitive to understand the navigation structure of the project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa14948e-2268-4b38-8d05-4cbe79190e10', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the concept of a ''Phantom Read'' and how it differs from a ''Non-repeatable Read''.', N'Middle', N'A non-repeatable read occurs when the same row''s data changes between two reads within a transaction. A phantom read occurs when new rows are added or deleted by another transaction, causing the result set of a range query to change between two reads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de373533-8c49-4496-89c6-4cc010e2a0b1', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the difference between a Controller and a LiveView in Phoenix.', N'Junior', N'A Controller follows the traditional request-response cycle where the server renders a template and sends it to the browser. LiveView, conversely, maintains a persistent stateful connection, allowing the server to push UI updates to the browser without a full page reload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3efb8822-d3df-4fac-8d10-4cc4ea9a8b9f', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is it important to use version control systems like Git, even when working on a solo project?', N'Junior', N'Version control provides a history of changes, allowing you to revert to a previous working state if you introduce a mistake. It also acts as a backup and provides a structured way to experiment with new features in separate branches without affecting the main work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0232e35f-9907-47bb-a038-4cc5b379bc22', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What are the trade-offs when choosing between optimistic and pessimistic locking?', N'Middle', N'Optimistic locking is ideal for systems with low contention, allowing higher throughput by not blocking other transactions. Pessimistic locking is necessary for high-contention scenarios where data integrity is paramount and the cost of retries outweighs the performance penalty of blocking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2581c313-4e3e-4610-862a-4cc67dd49511', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle large payload requests, and what are the limitations in an edge environment?', N'Senior', N'Hono handles large payloads by exposing the request stream, allowing for chunked processing rather than buffering. However, edge environments often have strict memory and execution time limits, which can be reached if a large payload requires heavy synchronous computation or extended processing before being piped to an external destination.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05f48a32-a6b9-4ba7-96ed-4cc7582f2d72', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you handle dependency management in a microservices ecosystem?', N'Senior', N'I prefer dynamic discovery and service registries over hard-coded configuration to handle changing service locations. By implementing standardized contract testing, I ensure that changes in one service do not unintentionally break the expectations of its consumers, maintaining a reliable integration path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be659559-407c-494a-9528-4cc9e5d6d2fd', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Describe the impact of ''monomorphization'' on compilation times.', N'Senior', N'Monomorphization generates a unique copy of generic code for every concrete type instantiation, which increases the work for the compiler and significantly extends compilation times for large projects. This is a deliberate trade-off where longer build times are exchanged for optimal runtime performance and static type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3682384-cc39-4e26-9ee0-4cca268c22fa', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi manage state in a stateless architecture?', N'Senior', N'Chi itself is stateless and does not persist request state across connections. It relies on the external context passed through the middleware chain, forcing developers to utilize external stores like Redis or databases for persistent state management between requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0096d7bf-2744-4bbd-bf60-4cca362a1c30', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Compare the thread-safety guarantees of ''lateinit'' versus ''lazy'' delegation.', N'Senior', N'‘lateinit’ is not thread-safe by default and is intended for mutable properties initialized after construction. ‘lazy’ provides thread-safe initialization by default via internal synchronization, ensuring that the initializer block is executed exactly once even when accessed by multiple threads simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd488e399-679c-4901-800b-4ccac0ea956a', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle caching for dependencies during the pre-bundling process?', N'Middle', N'Vite caches pre-bundled dependencies in a hidden directory. It re-runs the bundling process only when the dependency manifest or lockfile changes, ensuring that the development server stays fast while remaining synchronized with installed package versions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2707709-1722-4211-bfaf-4ccb42342c1b', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is ''CORS'' and how does Hono handle it?', N'Fresher', N'CORS, or Cross-Origin Resource Sharing, is a security feature that controls which domains can access your API. Hono provides a built-in middleware to configure these policies easily, preventing unauthorized cross-origin requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13f616aa-797c-4ced-a696-4ccb90ed68c2', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why might you choose a relational database for an application with strong consistency requirements?', N'Junior', N'Relational databases are designed around ACID properties, which guarantee that transactions are processed reliably. If the application requires strict data accuracy, such as financial systems, the inherent consistency mechanisms of relational databases are safer than those of most NoSQL alternatives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2098f91-aad4-4146-9857-4ccefaa2f7bf', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What role does ''scalability'' play in basic engineering problem-solving?', N'Intern', N'Scalability ensures that a solution will continue to perform effectively as the volume of work or data increases. Even for simple tasks, designing with growth in mind prevents the need for complete redesigns in the near future.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b43ccff5-6d53-4ef4-99b9-4cd1dd276e7f', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the ''fetchpriority'' attribute change how browsers handle resource scheduling?', N'Senior', N'Fetchpriority provides a signal to the browser''s resource scheduler to adjust the priority of a request, overriding the browser''s default heuristics. This is useful for ensuring that high-value assets, like an LCP image, are prioritized over less critical assets even when they are discovered simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f843b7bf-f967-4439-95fa-4cd3e74f179d', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why is Chi considered ''idiomatic'' Go?', N'Intern', N'Chi is considered idiomatic because it avoids complex abstractions and heavily relies on the standard library patterns. It follows the design philosophy of simple, readable code that integrates naturally with Go''s built-in toolset.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03060062-fa66-4fdd-96bd-4cd55af36854', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit''s ''load'' function lifecycle differ between server-side and client-side navigation?', N'Senior', N'On the initial request, the ''load'' function runs on the server to populate the HTML, while subsequent navigations execute it on the client. This hybrid approach ensures fast initial page loads via SSR while maintaining SPA-like transitions by fetching data asynchronously without a full page reload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe787dff-d56c-4f6e-a810-4cd66d83a5f4', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Explain the trade-off between using route groups in Chi versus defining all routes globally.', N'Middle', N'Defining routes in groups allows for better organization and the ability to apply specific middleware to subsets of your application, such as only protecting administrative routes. While global routing is simpler for very small projects, grouping improves maintainability and security as the codebase grows by localizing middleware scope and simplifying route path management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'faad5c2c-12f4-4931-bbdd-4cd6eea3432e', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is accessing the DOM via jQuery often referred to as ''expensive''?', N'Middle', N'Every time jQuery queries the DOM, the browser must perform a layout and paint calculation if the DOM has changed. Frequent direct manipulation forces the browser to recalculate styles and re-flow the page, which is resource-intensive compared to state-based updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4679a1ae-7577-481d-92c5-4cd94e0e839e', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is an AdonisJS ''Provider'' and why is it important?', N'Fresher', N'A Provider is the core mechanism for booting services and registering dependencies into the application container. It allows you to initialize classes or third-party packages so they can be injected throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f146663c-0aeb-4b2f-b7e9-4cdadd8bc8c2', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the impact of long-term caching on Webpack''s bundle splitting strategy?', N'Senior', N'Long-term caching requires stable file hashes, usually derived from content, to ensure browsers only re-download files that have actually changed. To achieve this, one must extract the runtime manifest into a separate chunk and use deterministic module IDs, preventing a change in one module from cascading into filename changes for unrelated chunks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'577040c8-9908-468e-a26e-4ce5817672bd', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the benefit of Hono''s ''standard-compliant'' design?', N'Junior', N'Because Hono uses the standard Fetch API, it is highly compatible with modern browser and server-side runtimes. This reduces vendor lock-in and makes it easier for developers to transition between different hosting providers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0da6ecb-a669-42bd-92f6-4ce6a504e82f', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What does the ''unsafe'' keyword signify in Rust?', N'Middle', N'The ''unsafe'' keyword tells the compiler to stop enforcing certain safety guarantees for a specific block of code, allowing operations like dereferencing raw pointers or calling foreign functions. It signals that the developer assumes responsibility for ensuring memory safety within that block.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'198ebb9f-f826-4557-bac1-4ce79585bf33', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Explain the concept of hinted handoff and its role in Cassandra''s availability.', N'Senior', N'Hinted handoff is a mechanism where a node stores a temporary write request for a peer that is currently unavailable. Once the target node recovers, the stored hint is replayed to ensure eventual consistency, preventing data loss during transient network partitions or node failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27956d6a-2645-4c9e-a5d7-4ce998e42339', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does the ''trust proxy'' setting affect Express behavior?', N'Middle', N'The trust proxy setting tells Express that it is behind a reverse proxy, such as Nginx or a cloud load balancer. Enabling it allows the application to correctly identify the client''s original IP address and protocol, which are passed in headers like X-Forwarded-For.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf561771-8b16-46e6-a36c-4ce9eb01ef67', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your approach to learning a new tool or technology to solve a problem?', N'Fresher', N'I start by reviewing official documentation and looking for fundamental examples to understand the core concepts. Then, I apply those concepts to a small part of the problem to verify my understanding before implementing it broadly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5eddd1e8-dd33-48c9-b35e-4cf111b9f94e', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the role of Gin''s ''Engine'' struct in the context of multi-tenant architecture?', N'Senior', N'The Engine struct acts as the central router and configuration hub. In multi-tenant environments, you might instantiate multiple Engine instances or use a single Engine with dynamic routing logic to isolate tenant-specific middleware and configurations, though the latter is generally preferred for resource efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'467efbb9-8f03-4afb-a585-4cf181be147d', N'954a0331-deff-4399-b588-96f39fec001d', N'What is a ''Subject'' versus a ''BehaviorSubject'' in RxJS?', N'Middle', N'A Subject is a basic stream that multicasts values to multiple observers without an initial state. A BehaviorSubject requires an initial value and always emits the current value immediately to new subscribers, making it ideal for representing state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d3f5afb-8a68-4c86-85b0-4cfa56532794', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the difference between a ''has_many :through'' and a ''has_and_belongs_to_many'' association.', N'Middle', N'A ''has_and_belongs_to_many'' association uses a simple join table with no model, making it unsuitable if you need to store extra data on the association itself. ''has_many :through'' uses a full join model, which allows you to add validations, callbacks, and extra attributes to the join relationship, providing much greater flexibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3b00468-057d-4467-97d2-4cfc1002b16e', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between ''interface'' and ''type'' in TypeScript, and when should you prefer one over the other?', N'Middle', N'Interfaces are primarily for defining object shapes and support declaration merging, which is useful for library authors. Types are more versatile as they can represent unions, intersections, and primitive aliases. Generally, use interfaces for public API definitions and types for complex union logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'556076f1-dc5e-4b00-97c0-4cfc576d7bfe', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the significance of the PSR (PHP Standard Recommendation) ecosystem for long-term project maintainability?', N'Senior', N'PSRs establish standardized interfaces for common tasks like logging, caching, and HTTP middleware, promoting interoperability between disparate libraries. This allows developers to swap components easily without locking the architecture into a specific vendor''s implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfe3f81a-778f-41f3-a30f-4d01d5d51e5a', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Explain the performance implications of Chi''s radix tree implementation for routing.', N'Senior', N'Chi uses a radix tree (compact prefix tree) which provides O(k) lookup time, where k is the length of the URL path. This is significantly more efficient than linear array or map-based routing for large API surfaces, ensuring predictable performance as the number of routes grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9368f706-361b-4366-9d65-4d02224ab4f4', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How can you return a JSON response in Hono?', N'Fresher', N'You can return a JSON response by using the helper method provided by the Context object. This method automatically sets the correct content-type header to application/json.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4471276-0ae9-4278-9dd7-4d03115ef590', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Describe the trade-offs of using a Document store versus a Key-Value store.', N'Middle', N'A Key-Value store is optimized for high-speed retrieval of simple data structures using a primary key, making it ideal for caching or session management. A Document store allows for complex, nested data structures and provides better query capabilities over the content of the documents, though it may have slightly more overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98391a1b-9faf-42ef-a536-4d03d173f9f2', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the significance of the ''parent selector'' (&) in Sass?', N'Middle', N'The parent selector (&) refers to the outer selector in a nested rule, allowing you to append pseudo-classes, pseudo-elements, or specific modifiers to the parent. It is essential for maintaining BEM naming conventions and handling states like hover or active without repeating the parent class name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c900f85a-87d5-4393-92fb-4d06aac79b81', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the role of the ''app'' directory in Nuxt 3?', N'Middle', N'The ''app'' directory serves as the main entry point for the application structure, including the root component, layouts, and plugins. It allows developers to customize the core application behavior and structure in a centralized location.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff9bcf08-0856-4b34-8d2b-4d07afbe22b5', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Is it possible to use Tailwind alongside existing legacy CSS, and what are the architectural challenges?', N'Senior', N'Yes, it is possible, but it requires careful management of the CSS cascade. The main challenge is CSS specificity conflicts between legacy global styles and Tailwind''s utilities, which often necessitates the use of a prefix to ensure Tailwind styles do not accidentally override critical legacy components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2104eef-0315-400f-8be0-4d07c3101950', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are Django migrations and why are they important?', N'Junior', N'Migrations are a way to propagate changes you make to your models into your database schema. They serve as a version control system for your database, ensuring that your database structure stays in sync with your model definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b11c395f-f1f4-48b6-89e3-4d07f046b936', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why might a ''bool'' query with many clauses perform poorly, and how can you optimize it?', N'Senior', N'Each clause in a bool query adds to the complexity of the internal bitset processing and scoring calculation. To optimize, you should move static or non-scoring criteria into filter clauses, use constant score queries when relevance isn''t needed, and refine the query logic to reduce the search space early.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44a7fd3a-3762-4383-870b-4d0d6e0b4871', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the purpose of decorators in Python and describe the trade-offs of using them.', N'Middle', N'Decorators are a structural pattern used to modify or extend the behavior of functions or classes without permanently changing their source code. They are highly useful for cross-cutting concerns like logging, authentication, or caching. However, they can make debugging more complex by obscuring the original function signature and can introduce performance overhead if improperly implemented or overused.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'553bdfe2-6b7c-4e54-955c-4d0d7b23ed15', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is the final CSS file size in Tailwind CSS typically very small?', N'Fresher', N'Tailwind uses a tool that scans your project files for utility classes and removes any unused CSS from the final build. Because only the classes you actually use in your HTML are included in the production bundle, the file remains lightweight.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69eb5d5f-fa92-4c7d-a335-4d0de2a8070e', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to ensure hooks followed the rules in your project?', N'Fresher', N'React team released an ESLint plugin called eslint-plugin-react-hooks that enforces Hook''s two rules. It is part of Hooks API. You can add this plugin to your project using the below command, And apply the below config in your ESLint config file, This plugin also provide another important rule through react-hooks/exhaustive-deps. It ensures that the dependencies of useEffect, useCallback, and useMemo hooks are correctly listed to avoid potential bugs. The recommended eslint-config-react-app preset already includes the hooks rules of this plugin. For example, the linter enforce proper naming convention for hooks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c2e3a25-f4f3-4fb3-adaa-4d0ee2951298', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What happens when you import a CSS file in a Vite project?', N'Junior', N'When you import a CSS file, Vite injects the styles into the document head via a style tag during development. For production builds, Vite automatically extracts these styles into a single, minified CSS file linked in your HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7f76135-a5b3-4d6f-8db1-4d101b9e81dc', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the difference between local state and global state?', N'Intern', N'Local state is data managed within a single component, while global state is data that needs to be accessed by many different components throughout the application. Redux is used to manage this global state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f60a25a-5ca0-47ee-b552-4d1041e02d7e', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Is jQuery suitable for modern PWA development, and why or why not?', N'Senior', N'jQuery is generally unsuitable for PWAs because it lacks the necessary primitives for offline-first data synchronization, complex state hydration, and code-splitting. Modern PWA development requires a modular architecture that jQuery, being a monolithic DOM utility, cannot provide.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
