INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'823eafb4-a7f4-4288-b1e0-4d1789c8dc0e', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When considering security, what is the typical trade-off between user convenience and system protection?', N'Intern', N'Enhanced security features, such as multi-factor authentication or strict password requirements, protect data but add friction to the user login process. The trade-off involves determining the acceptable level of risk versus the potential impact on user retention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
