INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db8b12b5-2e19-4a65-a767-4d1f11c682de', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the purpose of database connection pooling?', N'Middle', N'Connection pooling maintains a cache of database connections that can be reused for future requests, rather than creating a new connection for every query. This significantly reduces the overhead of establishing TCP handshakes and authentication for every database interaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99a46f58-4a4f-48c5-bc74-4d1f70dd0cc7', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is Redux Thunk?', N'Intern', N'_Redux Thunk_ middleware allows you to write action creators that return a function instead of an action. The thunk can be used to delay the dispatch of an action, or to dispatch only if a certain condition is met. The inner function receives the store methods dispatch() and getState() as parameters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7af2b46e-bd61-4db1-9b00-4d2359c839fc', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are the trade-offs of using the ''adapter-static'' versus ''adapter-node'' in SvelteKit?', N'Middle', N'Adapter-static creates a fully static site suitable for CDN hosting, but it cannot handle dynamic server-side logic like API routes or dynamic headers. Adapter-node requires a running Node.js server, enabling full dynamic capabilities, server-side data fetching, and real-time processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d05f8fb-6d29-4ef9-9111-4d29c110b519', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What does ''static'' mean when applied to a variable?', N'Intern', N'A static variable retains its value between function calls rather than being destroyed. If a static variable is used inside a function, it stays in memory for the entire lifecycle of the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37be8d3d-7a9d-4fe5-a27e-4d2b69ed0891', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are the implications of using ''Middleware'' for route guarding versus using ''Layouts''?', N'Senior', N'Middleware is best suited for logic-driven access control, such as redirecting unauthenticated users based on state. Layouts are intended for UI structure, such as changing the shell of a page based on user roles or specific navigation needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'186067f0-1d65-48fb-ac03-4d2e2a9d8377', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What are the risks of using the ''Default'' refresh interval (1s) in a large-scale system?', N'Senior', N'A 1-second refresh interval forces the creation of a new segment every second, which leads to massive overhead in segment merging and high CPU usage. In large-scale systems, this often results in disk I/O saturation and prevents the system from handling high throughput efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'816e3365-213b-4f92-a79b-4d3308dc09a0', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the function of the ''static'' files in Django?', N'Junior', N'Static files are assets like CSS, JavaScript, and images that do not change dynamically. Django uses a specific storage and collection process to serve these files efficiently in both development and production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'353d1d32-ebc2-4b94-8e17-4d3446443c0d', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP handle exceptions versus errors, and why should one be preferred for control flow?', N'Middle', N'Errors in PHP often represent fatal runtime problems, whereas exceptions are intended for recoverable business logic errors. Using exceptions allows for clean separation of concerns through try-catch blocks, whereas relying on error handling for logic flow makes code difficult to trace and manage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6098ee37-659e-4c85-b24a-4d3684781ac6', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your philosophy on ''fail-fast'' in distributed systems?', N'Senior', N'Fail-fast is essential for preventing the accumulation of invalid state and reducing the time spent processing doomed requests. By validating inputs early and failing immediately upon resource exhaustion or logical errors, we preserve system health and provide clearer feedback to the calling service or user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99d259c3-8995-424f-a917-4d373fb3ea41', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the benefit of build-time processing in Quarkus?', N'Intern', N'Build-time processing shifts heavy tasks like classpath scanning and metadata analysis from startup to the build phase. This results in a significantly reduced memory footprint and faster application readiness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'452435d4-c41c-4095-9c83-4d3c93c494bd', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How can you restrict a plugin to only load in certain environments?', N'Junior', N'You can use standard JavaScript logic within your register calls to check environment variables before loading a plugin. This allows you to conditionally load development-only tools or production-specific configurations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c61d3e2-dac5-472e-bfa4-4d3ded78cf17', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the Virtual DOM and how does it function in Preact?', N'Intern', N'The Virtual DOM is a lightweight representation of the actual browser DOM that sits in memory. Preact uses it to calculate the minimum number of changes needed to update the UI, applying only those specific differences to the real DOM to improve rendering performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbd56a40-2978-4d23-a5c3-4d3eddb7f315', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How do Tailwind''s group-hover modifiers work?', N'Middle', N'Group-hover modifiers allow you to style a child element based on the hover state of a parent element. By adding a specific class to the parent, you can trigger style changes on children, which is essential for complex interactive components like navigation menus or cards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54a05497-3ee7-4604-a35f-4d414385dff6', N'954a0331-deff-4399-b588-96f39fec001d', N'What is State function and Style function?', N'Intern', N'In Angular animations, state() and style() are functions used to define the visual appearance of an element at specific points in an animation. - state(): This function defines a named state for an element, associating a name (like ''open'' or ''closed'') with a specific set of CSS styles. It takes a state name (string) and a style() definition as arguments. - style(): This function defines a set of CSS-like properties and their values that describe the appearance of an element at a particular moment. It''s used within state(), transition(), and keyframes() to specify styles. It takes an object literal where keys are style properties and values are their desired settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10d656e5-c2b1-49ad-8830-4d44eb3e9123', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the primary benefit of Svelte performing work at build time?', N'Fresher', N'By compiling components during the build process, Svelte eliminates the need for a virtual DOM. This results in smaller bundle sizes and faster performance because the browser does not have to reconcile complex state trees at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92a07343-de57-4479-bef6-4d471976240d', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit optimize the loading of static assets?', N'Senior', N'SvelteKit processes static assets through a build pipeline that supports fingerprinting and content hashing for cache busting. This ensures that browsers always fetch the latest version of assets while maximizing cache efficiency for unchanged files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'444f92e6-6941-47ed-b6cf-4d49b6f5a0a7', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are the performance implications of using Ember Observers, and why are they generally discouraged in modern Ember?', N'Senior', N'Observers can lead to unpredictable side effects and infinite loops because they react to property changes without explicit triggers. Modern Ember encourages using tracked properties or computed properties, which are more declarative and easier for the system to optimize.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f40bb09-0853-4cbb-9eec-4d4a287f1b8d', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Discuss the impact of Flask''s synchronous nature on high-concurrency microservices.', N'Senior', N'Flask is inherently synchronous, meaning one request per worker thread. For I/O-bound microservices, this can lead to thread exhaustion under high load, so architectures often incorporate async-capable frameworks or offload heavy I/O to background workers to prevent blocking the main request thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e484ead-c480-4713-b77d-4d53b523511f', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the role of a message broker in a microservices architecture?', N'Middle', N'The broker acts as an intermediary that decouples the producer from the consumer, allowing them to operate independently in terms of availability and scaling. It also buffers incoming traffic, protecting downstream services from spikes in request volume.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23bbf997-0935-439e-905c-4d559d743334', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is ''SharedArrayBuffer'' useful, and what security considerations must be implemented when using it?', N'Senior', N'SharedArrayBuffer allows multiple threads to access the same memory region, enabling efficient data sharing without expensive serialization. Due to security risks like Spectre-style side-channel attacks, modern browsers and Node.js environments require cross-origin isolation headers to be set before allowing the use of this feature.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38e26eb1-4d45-4d62-a568-4d55e6bd5949', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is ECMAScript', N'Intern', N'ECMAScript is the scripting language that forms the basis of JavaScript. ECMAScript standardized by the ECMA International standards organization in the ECMA-262 and ECMA-402 specifications. The first edition of ECMAScript was released in 1997.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21f43dab-33f9-415c-965f-4d579f3c333e', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are the architectural benefits of the R ''condition'' system over simple return values?', N'Senior', N'The condition system decouples the detection of an event from its handling, allowing for complex recovery strategies without cluttering the main logic with error-checking code. By allowing handlers to ''muffle'' or ''resume'' execution, it provides a more flexible control flow mechanism than simple boolean return codes, which would otherwise require propagation through every nested function call.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7833945d-c831-43a4-aa58-4d5839f0c031', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is ''feature detection'' preferred over the ''browser sniffing'' patterns often associated with older jQuery plugins?', N'Senior', N'Browser sniffing relies on mutable user-agent strings that are unreliable and difficult to maintain as new browsers emerge. Feature detection checks if the current environment supports a specific API, leading to more robust and future-proof code that works regardless of the browser brand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3904d398-ea04-47f2-8241-4d585bdae28f', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust handle null values compared to other languages?', N'Fresher', N'Rust does not have a traditional null value, which prevents common errors like null pointer dereferencing. Instead, it uses the Option enum, which explicitly forces the programmer to handle the case where a value might be missing. This forces developers to address the absence of a value at compile time rather than encountering runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
