INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be551517-51cc-44df-b16a-4d5bdde40245', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you assess the trade-offs between batch processing and stream processing?', N'Senior', N'Batch processing is efficient for massive, non-time-sensitive data aggregation jobs and is simpler to monitor and debug. Stream processing is required when the business value is tied to immediate action based on incoming data, despite the increased complexity of windowing, state management, and ordering guarantees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40c19a8f-4a21-441e-8f34-4d5cc3a7208a', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between ''type'' assertion and type casting?', N'Middle', N'In TypeScript, type assertion is a way to tell the compiler to treat a value as a specific type, but it does not perform any runtime conversion or checking. Unlike traditional casting in other languages, it is purely a compile-time construct that assumes the developer knows more about the value''s structure than the compiler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
