INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6966c0d9-157c-43df-932f-4d66bbd3c3e8', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why is it generally recommended to avoid superglobals like $_GET and $_POST directly in business logic?', N'Middle', N'Accessing superglobals directly couples business logic to the web transport layer, making code difficult to unit test and prone to security vulnerabilities like XSS or injection. Using request objects or abstractions allows for proper validation, filtering, and easier mocking during testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6bd49f4-4eb4-4d2d-b897-4d6de5fd7f5c', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does the jQuery ''data()'' method interact with the DOM, and what are its drawbacks?', N'Middle', N'The data method stores data in an internal jQuery cache linked to DOM elements rather than directly on the element''s attributes. This can lead to memory leaks if elements are removed from the DOM without being properly cleaned up by jQuery, as the cached data persists in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cc3a57b-fb5e-42a2-8e34-4d73fdd07ad4', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL handle case sensitivity?', N'Junior', N'By default, PostgreSQL identifiers like table and column names are folded to lowercase unless they are enclosed in double quotes. String data comparisons are case-sensitive unless specific functions or operators are used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac7a65b1-2224-4a17-8961-4d74d4bfd3b5', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are primitive data types in Java?', N'Intern', N'Primitive data types are the most basic data types provided by Java, such as int, char, boolean, and double. They store actual values directly in memory rather than storing references to objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db4200e4-19c0-4e06-9f6c-4d74f25a81b2', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Is dispatch from useReducer asynchronous and does it update state immediately?', N'Middle', N'The dispatch function returned by useReducer is not asynchronous — it is a synchronous function call. When you call dispatch(action), React synchronously invokes your reducer with the current state and the action, computes the new state, and schedules a re-render. However, the state variable does not update immediately within the same render cycle. The updated state is only available in the next render. This behavior is similar to useState''s setState — React batches state updates for performance optimization, meaning the component does not re-render immediately after each dispatch call. Instead, React processes all dispatched actions and re-renders once with the final state. Key Points 1. dispatch is synchronous: The reducer runs immediately when dispatch is called. 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6e600b6-2aa6-40fb-9dfb-4d77d7984b86', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the advantage of using Redux?', N'Fresher', N'Redux makes state management predictable and easier to debug because the state flow is unidirectional. It also allows for easier testing and the ability to implement advanced features like time-travel debugging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce11d60c-1523-4a17-95e7-4d7d5b38f867', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What are the considerations when choosing between a cache-aside and write-through caching strategy?', N'Middle', N'Cache-aside is generally more flexible and resilient to cache failures, making it better for read-heavy applications where stale data is acceptable. Write-through ensures high data consistency between the cache and database but introduces higher latency on writes and increases the complexity of the write path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be93652f-33a2-4ff5-b199-4d7ddfc163cb', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis ensure data safety during a master crash?', N'Middle', N'Redis ensures safety through a combination of replication and persistence. If a master fails, Sentinel or Cluster promotes a replica; if the entire system restarts, RDB or AOF files are used to reload the data back into memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1625b87-60b4-4b07-8072-4d805a2ce623', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js implement automatic code splitting, and how can developers influence this behavior?', N'Senior', N'Next.js automatically splits code based on route boundaries, creating separate bundles for each page. Developers can further optimize this by using dynamic imports to defer the loading of heavy components or third-party libraries until they are actually needed in the viewport or interaction flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1878751d-14da-4feb-9f26-4d813d4e7ee7', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the difference between a route handler and a request guard?', N'Fresher', N'A route handler performs the main business logic of the endpoint, while a request guard acts as a middleware that validates the request before the handler is even executed. Guards are typically used for security and validation checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
