INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6218a2e5-f0aa-4ff5-8866-4d8419896ceb', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why is it important to keep the Redux state tree as flat as possible?', N'Middle', N'A flat state tree simplifies data access and reduces the complexity of update logic. Deeply nested state makes it difficult to update specific properties immutably and often leads to performance bottlenecks in component re-rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
