INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98de1c52-3fb0-4bff-8828-4d92659ac655', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the purpose of the ''aria-live'' attribute?', N'Middle', N'The ''aria-live'' attribute notifies screen readers that the content within an element is dynamic and may change without the user triggering a page refresh. By setting it to ''polite'' or ''assertive'', developers can control how urgently the screen reader announces these updates to the user. This is crucial for maintaining accessibility in single-page applications where content updates happen asynchronously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
