INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12863562-7add-4201-b595-4d9c1cf6e7c1', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If asked to estimate the number of cars that pass through a toll booth in a day, what data points would you need?', N'Fresher', N'I would need the average traffic flow during peak and off-peak hours and the total operational time of the booth. I might also look for data on seasonal or weekend variations to refine the estimate. By segmenting the day into time blocks with different traffic densities, I can calculate a more accurate total.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fbcde24-1330-44be-9e86-4d9c1f8efa98', N'954a0331-deff-4399-b588-96f39fec001d', N'Discuss the impact of Angular''s modularity (NgModule) vs. Standalone Components on bundle size and maintainability.', N'Senior', N'Standalone components remove the requirement for intermediate NgModules, reducing boilerplate and simplifying the dependency graph for developers. This shift facilitates better tree-shaking and allows for a more intuitive mental model, as dependencies are explicitly listed within the component''s own metadata.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f44a0225-42d1-43ed-8852-4da1e55ea8ed', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the difference between strong and eventual consistency in a cached system?', N'Middle', N'Strong consistency ensures that all reads receive the most recent write, usually requiring expensive invalidation protocols between the cache and the database. Eventual consistency allows for a delay in data propagation, offering better performance but accepting that users may temporarily see outdated values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c01ac215-c651-48f8-b9e4-4da42dc1500a', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of the ''setupController'' hook in a route?', N'Junior', N'The setupController hook allows you to manually pass the model to the controller or perform additional logic after the model has been fetched. It is a useful place to prepare data before the template is rendered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1413b11c-8575-4e54-9925-4da9eaa2ee9e', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do you listen to events in Lit templates?', N'Junior', N'You can listen to events in Lit templates using the @event-name syntax directly on an element within the render method. This is a shorthand for adding an event listener that automatically manages binding the correct context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa914d5b-62b5-4e8b-8037-4da9fd4e9a3b', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring handle asynchronous task execution?', N'Middle', N'Spring provides the @Async annotation, which allows a method to run in a separate thread, enabling non-blocking execution. This is typically configured via a TaskExecutor, which manages the thread pool used to execute these tasks, improving application responsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bfc16be-1c7c-42da-8555-4daa33fd4ff3', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Can you use Gin to render HTML templates?', N'Intern', N'Yes, Gin supports rendering HTML templates using the standard Go html/template library. You can load template files into the engine and use the HTML method on the context to render them with dynamic data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a616196-9f8d-4332-a2b0-4dac7a50d857', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are the architectural risks of C''s lack of automatic bounds checking?', N'Senior', N'The lack of bounds checking shifts the responsibility of memory safety entirely to the programmer, creating vulnerabilities like buffer overflows. These are architectural risks because they allow arbitrary code execution by overwriting return addresses or function pointers in memory, which cannot be mitigated by the language semantics themselves.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e23a8370-ede0-4be1-ae0a-4db298c9906e', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are SvelteKit ''Actions''?', N'Fresher', N'Actions are functions in +page.server.js files that handle form submissions. They provide a simple way to perform server-side operations like database updates or authentication without needing an explicit API endpoint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ce39341-5921-47bd-9bf9-4db4eea2acec', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does hoisting behave differently for function declarations versus function expressions and arrow functions?', N'Fresher', N'- Function declaration (function foo() {}): The entire function — name and body — is hoisted. The function is callable anywhere in its scope, even before the line it appears on. - Function expression (const foo = function() {}): Only the variable declaration is hoisted (if var); the assignment — the function value itself — is not. Calling it before the line throws TypeError (not ReferenceError) because the variable exists but holds undefined. - Arrow function (const foo = () => {}): Same as function expression — it is always assigned to a variable, so the same rules apply. Example: Real-World Use Case: In large React component files, developers often define helper arrow functions (const formatDate = (d) => ...) after the component function that uses them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4911bdbc-a6af-4ddc-b669-4db70d5f8132', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle accessibility (a11y) within Shadow DOM?', N'Middle', N'Shadow DOM can create barriers for accessibility because IDs inside the shadow root are not visible to the document-level labels or ARIA attributes. Lit developers must use techniques like ''aria-labelledby'' with cross-root ID references or utilize the ElementInternals API to properly expose component state to assistive technologies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'008ceee4-44cc-4bdd-a8d8-4db965584f78', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Discuss the challenges of implementing distributed transactions across microservices using the Saga pattern with messaging.', N'Senior', N'Sagas manage consistency by coordinating a series of local transactions via messaging, but they lack the isolation property of ACID transactions. This necessitates careful design of compensating transactions to roll back changes and handle ''dirty reads'' where intermediate states might be visible to other services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf394c8b-5bab-4bd3-a0ec-4db97647596a', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Can Vite process TypeScript files automatically?', N'Intern', N'Yes, Vite has built-in support for TypeScript. It uses transpilation to remove type annotations, allowing your project to run without needing a separate manual build step for types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ee63b54-380c-43ac-b78c-4dbb02572912', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Describe the function of the ''error.js'' file.', N'Middle', N'The error file defines an error boundary for a route segment, allowing you to gracefully handle unexpected issues. It catches errors within its child components and allows you to display a fallback UI, such as a try-again button, without crashing the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a68b9ac6-3171-4534-9d84-4dbc8fbefce5', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the impact of C''s ''common initial sequence'' rule for structures?', N'Senior', N'This rule allows developers to safely access the initial members of different structures if they share an identical layout, effectively enabling a form of structural inheritance. This is frequently used for implementing polymorphic behavior in C by casting pointers to different structure types that begin with the same header. It is a fundamental technique for building object-oriented frameworks within the constraints of the C language.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cee94a0-170d-4043-8765-4dbd38bb9945', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain the performance trade-offs of using CSS-based animations versus requestAnimationFrame.', N'Senior', N'CSS animations are declarative and can be optimized by the browser''s internal engine, often running off the main thread. requestAnimationFrame allows for more complex, logic-heavy animations in JavaScript, but it runs on the main thread and can be blocked by heavy computation, leading to jank.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f1dde87-8d7c-44d7-94b1-4dbe59d45f60', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the primary function of the ''hasChanged'' property option?', N'Middle', N'The hasChanged function allows developers to implement custom logic to determine if a property change should trigger a re-render. This is particularly useful for preventing updates when deep objects or arrays are modified but the semantic value remains the same.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad74d4bb-be65-4aa2-8da1-4dbe85ed9edd', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s ''dynamic'' type differ from ''Object''?', N'Middle', N'The dynamic type disables type checking, allowing for any operations to be performed on the object, which is resolved at runtime. Object is the root of the class hierarchy, and while any object can be assigned to it, the compiler still enforces type safety, requiring explicit casting before calling specific methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f233cc13-1a3d-4c5d-85cc-4dbedd4b8a04', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is a block in Ruby?', N'Intern', N'A block is a chunk of code enclosed between braces or ''do'' and ''end'' keywords that can be passed to a method. It allows for the deferred execution of logic, which is commonly used for iterating over collections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca8501ac-fa0e-4e3f-859e-4dbfd9cb730a', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte optimize bundle size for large-scale enterprise applications?', N'Senior', N'Svelte achieves small bundle sizes by omitting a runtime library, as the framework logic is baked into the component code during compilation. By only including the code necessary for the specific components used in the application, Svelte inherently supports tree-shaking and reduces the overhead associated with heavy framework runtimes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b45d34bc-a54d-4f5b-a6ee-4dc04f495be8', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the role of esbuild in Vite?', N'Intern', N'Esbuild is a high-performance JavaScript bundler written in Go that Vite uses to perform dependency pre-bundling and TypeScript transpilation. Its extreme speed allows Vite to start servers almost instantly compared to traditional tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a03f5ba-e510-44dd-af55-4dc2e7ed842d', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between semantic and non-semantic HTML elements?', N'Junior', N'Semantic elements clearly describe their meaning to both the browser and the developer, such as header, footer, or article. Non-semantic elements, like div and span, provide no information about the content they contain. Using semantic tags improves accessibility for screen readers and helps search engines understand the structure of your page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24388343-6efc-4561-92b8-4dc4d922109a', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Explain the concept of ''progressive enhancement'' in the context of HTML development.', N'Middle', N'Progressive enhancement is a design philosophy that prioritizes the core content and functionality first, ensuring it works on all browsers. More advanced features are then layered on top for browsers that support them, ensuring a functional experience even if modern features fail.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'603030c4-1fd0-41e1-b11f-4dc57d52e102', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is a before_action filter?', N'Intern', N'A before_action is a method in a controller that runs before a specific action is executed. It is commonly used to perform tasks like checking if a user is logged in or setting up shared variables for multiple actions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa1837e4-3d72-483e-a7d6-4dca14a7580d', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix handle ''Hot Code Reloading'' in production, and what are the associated risks?', N'Senior', N'Phoenix uses the Erlang VM''s capability to swap module versions at runtime without stopping the process. While this allows for zero-downtime updates, it carries the risk of state corruption if the new code expects a different data structure than what is currently held in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53654466-3dd9-4e90-928d-4dccad2e2cac', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the purpose of the Echo ''Group'' functionality?', N'Middle', N'Groups allow for the logical organization of routes that share common path prefixes or middleware. This improves code maintainability by enabling the application of specific authentication or logging policies to a subset of endpoints without duplicating configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01103120-8287-48fd-9907-4dd085ee9f38', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Client-Side Rendering (CSR) work in Next.js?', N'Fresher', N'In CSR, the browser downloads a minimal HTML page and a JavaScript bundle. The browser then executes the JavaScript to fetch data and render the UI components, which is useful for highly interactive parts of an application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cde00596-38b7-4b1b-9bfb-4dd32584a03d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of clearTimeout method?', N'Intern', N'The clearTimeout() function is used in javascript to clear the timeout which has been set by setTimeout() function before that. i.e, The return value of setTimeout() function is stored in a variable and it''s passed into the clearTimeout() function to clear the timer. For example, the below setTimeout method is used to display the message after 3 seconds. This timeout can be cleared by clearTimeout() method. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4024c984-2d84-435b-be7d-4dd34099bdd2', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do you conduct effective CSS code reviews?', N'Fresher', N'Code reviews for CSS focus on long-term maintainability, performance, and consistency, not just whether styles look correct in a browser. What to check in a CSS PR: * Specificity: Are selectors as simple as possible? Are ID selectors or !important avoided? * Magic numbers: Are hard-coded values (e.g., margin-top: 37px) replaced with design tokens or custom properties? * Responsiveness: Does every new layout change include media query coverage? Are breakpoints consistent with the shared breakpoint scale? * Accessibility: Does color contrast meet WCAG AA (4.5:1 for normal text)? Are focus styles visible and not suppressed (outline: none without a replacement)?', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf9daa9a-cb0b-4162-9efd-4dd346e53615', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do you manage complex data structures in Lit properties to avoid unnecessary re-renders?', N'Senior', N'Since Lit uses strict equality checking, mutable objects and arrays will not trigger updates if only their internal values change. To handle this, developers should use immutable patterns or trigger a manual ''requestUpdate'' when the data structure''s contents are modified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93f276c0-42d8-47f5-bec1-4dd4e6f84598', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a default value in PostgreSQL?', N'Fresher', N'A default value is a value assigned to a column automatically if no value is specified during an insert operation. It helps maintain data consistency when certain information is not provided by the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c9bdee3-8614-4ec6-95ce-4dd684cf0ed1', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are Rails Helpers?', N'Intern', N'Helpers are modules that provide methods to be used inside view templates to keep them clean and readable. They are typically used for formatting data, generating complex HTML structures, or performing small logic tasks that don''t belong in the controller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e013af8-6a66-42ec-a0a0-4dd8d93241a1', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the role of the Astro content collection API?', N'Middle', N'Content collections provide a type-safe way to organize, validate, and query markdown or MDX files. It allows developers to define schemas for frontmatter, ensuring consistency and better developer experience when managing site content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'676129a9-5b85-4137-bff1-4dddb5754048', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the impact of a low TTL (Time-To-Live) value on system performance?', N'Middle', N'A low TTL ensures that data remains fresh, reducing the risk of stale reads, but it increases the load on the backing database as the cache expires and requires re-population more frequently. It is a balancing act between data accuracy and system throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce68893c-451d-4df3-8b07-4dddbe29d59d', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How do ''hidden classes'' in V8 affect Node.js performance?', N'Senior', N'V8 creates ''hidden classes'' internally to optimize property access in objects. If object shapes change dynamically by adding or deleting properties, V8 de-optimizes, falling back to a slower dictionary-mode lookup. Keeping object structures consistent across instances helps the JIT compiler generate more efficient machine code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42ffb1e6-a352-4eab-9d81-4ddea75ca05d', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the role of ES modules in Vite?', N'Intern', N'ES modules are the official standard format for packaging JavaScript code for reuse. Vite uses these native browser capabilities to load individual files as requested, avoiding the need to bundle every single file before the development server starts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc228fd6-52b2-43f5-a8d1-4de0a12c16ca', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the primary difference between let and var in Swift?', N'Fresher', N'The let keyword is used to declare constants, meaning the value cannot be changed once assigned. The var keyword is used to declare variables, which allows the value to be modified at any point in the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cf069dc-47ac-4b49-aa81-4de0ae5b31b7', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you create custom validators in Angular?', N'Fresher', N'Custom validators in Angular allow you to define specific validation rules beyond the built-in ones like required or minLength. You create a custom validator as a function that takes an AbstractControl (representing the form control, group, or array) as an argument and returns either: - null if the control''s value is valid - A ValidationErrors object (e.g., { ''myError'': true }) if the value is invalid There are two types: - Synchronous validators: Return ValidationErrors | null immediately. - Asynchronous validators: Return Promise or Observable . These are used for validations that require time, like checking against a server API. In Reactive Forms, you pass these validator functions directly when creating FormControl, FormGroup, or FormArray instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93d2c5e2-90cf-414c-a888-4de1995c5387', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are asyncData and fetch in Nuxt?', N'Junior', N'These are methods used to fetch data before the component is rendered. AsyncData is used to return data that populates the component''s state, while fetch is typically used to fill the store or component data after the instance is initialized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9265436a-ae85-4ec2-a5c9-4de658cf1e7b', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut''s declarative HTTP client reduce architectural complexity?', N'Senior', N'By using interfaces annotated with request details, Micronaut automatically generates the implementation code to handle HTTP calls, retries, and circuit breaking. This enforces a consistent communication pattern across microservices and offloads the handling of distributed system failure modes to the framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52af9a3b-4b92-4ae7-8464-4de680b2a739', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the ''url_for'' function used for?', N'Fresher', N'The ''url_for'' function generates a URL for a specific function name. This is better than hardcoding URLs because if the URL structure changes in the future, the code will automatically update to reflect the new path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7009d1e-3d92-40a8-af09-4de6ae8da080', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js handle client-side navigation optimization compared to traditional anchor tag links?', N'Senior', N'Next.js uses the Link component to prefetch linked pages in the background when they enter the viewport. This makes navigation feel instantaneous because the necessary data and code are already available in the browser cache before the user clicks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd48eaf6e-18c6-4354-9ec5-4de8c9118d62', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle error boundaries?', N'Junior', N'Preact supports Error Boundaries via the componentDidCatch lifecycle method in class components. This allows you to catch JavaScript errors anywhere in your child component tree and display a fallback UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9811bfba-f17d-438d-b7ba-4dedff538342', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the concept of ''Template Literal Types'' and how they improve the safety of string-based API patterns.', N'Senior', N'Template literal types allow for the creation of complex string types by interpolating smaller string literals. This ensures that dynamic strings, such as CSS class names or event names, are validated at compile-time, reducing runtime errors associated with typos in string-based configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6ea4558-ad7c-47e8-9afd-4defdcdb2307', N'075b8862-431c-4678-9767-f55359758a4a', N'What is vue router and their features?', N'Intern', N'Vue Router is a official routing library for single-page applications designed for use with the Vue.js framework. Below are their features, 1. Nested route/view mapping 2. Modular, component-based router configuration 3. Route params, query, wildcards 4. View transition effects powered by Vue.js'' transition system 5. Fine-grained navigation control 6. Links with automatic active CSS classes 7. HTML5 history mode or hash mode, with auto-fallback in IE9 8. Restore scroll position when going back in history mode', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fda65d15-d2e1-4f4f-b695-4df27e9b2bac', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI perform data validation?', N'Intern', N'FastAPI performs data validation by inspecting the type hints defined in your function signatures and Pydantic models. If the incoming request data does not match the specified types, FastAPI automatically returns a 422 Unprocessable Entity error to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'662dcd49-c7ce-4023-92ea-4df2be38e882', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why are fibers considered more scalable than threads?', N'Intern', N'Because fibers have a much smaller memory footprint and lower overhead for creation and switching, a single server can handle hundreds of thousands of fibers simultaneously. This level of concurrency is difficult to achieve with OS threads due to their larger memory stacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'345f61e7-08ef-423c-86b9-4df2e94a70c2', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go’s interface implementation differ from languages like Java or C++?', N'Middle', N'Go uses implicit interface implementation, meaning a type satisfies an interface simply by implementing its methods. This promotes loose coupling and allows developers to define interfaces where they are consumed rather than where they are defined, avoiding intrusive inheritance hierarchies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'672c46a4-cbd7-40ec-863b-4df41361e2ea', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the difference between ''=='' and ''eq'' in Scala?', N'Junior', N'The ''=='' operator checks for structural equality, meaning it compares the values of two objects, while ''eq'' checks for referential equality, meaning it checks if both references point to the exact same object in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5998e2bd-2ee0-4985-a941-4df80c7afcbf', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Why should developers avoid ''box-shadow'' and ''border-radius'' on large numbers of elements?', N'Senior', N'These properties are computationally expensive during the paint phase because they require complex math to calculate non-rectangular clipping or blurred shadows. Applying them to many elements simultaneously can cause scrolling performance issues, especially on lower-end devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ce83ddc-d765-43bf-b4be-4dfd399553e3', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a Quorum in Cassandra?', N'Intern', N'Quorum is a consistency level that requires a majority of replicas to acknowledge a read or write operation. It provides a balance between performance and data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f09f001-24e0-47f2-8fc3-4dfdc539ea81', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery handle AJAX requests differently than the native Fetch API?', N'Middle', N'jQuery''s AJAX method provides a simplified, monolithic interface that handles cross-browser JSONP and serialization automatically. The native Fetch API is more modular and uses Promises, allowing for better integration with modern async/await patterns and more granular control over request headers and streams.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a4319a9-0739-4305-9a10-4e010576d6f3', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the benefit of using SvelteKit''s built-in fetch?', N'Intern', N'SvelteKit provides a specialized fetch function that works seamlessly on both the server and the client. It automatically handles authentication cookies and relative URLs, making data fetching more consistent across the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21c0b539-9954-4ee4-a130-4e0438dd9f39', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the risks of ''Serializable'' isolation level compared to ''Repeatable Read''?', N'Senior', N'Serializable isolation level prevents phantom reads and serialization anomalies by monitoring for dependency cycles between transactions. This increases the likelihood of serialization failures, where the application must be prepared to retry transactions that conflict with concurrent writes, adding complexity to the application layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92a89933-7252-4577-a232-4e0449731ebb', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are ''design tokens'' in the context of Tailwind CSS?', N'Junior', N'Design tokens are the underlying values that define your design system, such as specific color palettes, spacing scales, and typography settings. In Tailwind, these are configured in the configuration file, allowing you to enforce brand consistency across your entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edb647fa-2140-409f-ab3f-4e09b6fae4ce', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix facilitate progressive enhancement in form handling?', N'Senior', N'Remix forms work without JavaScript by relying on standard HTML form submissions that the server processes via actions. Once JavaScript hydrates, Remix intercepts these submissions to provide a smoother, non-refreshing experience, ensuring the application remains usable on low-end devices or in poor network conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7fab6d5-e175-4fbe-94f3-4e0a0f965b77', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How do you handle side effects in Redux?', N'Fresher', N'Side effects, such as API calls or timers, are handled using middleware. Middleware allows you to execute asynchronous logic before dispatching the final action that will actually update the state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'886e173c-bc07-4c29-a28e-4e0ce49bed9f', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How do you implement custom authentication in Axum?', N'Senior', N'Custom authentication is best implemented as a middleware Layer that inspects the request headers, validates tokens, and injects the user context into the request extensions. This allows downstream handlers to easily extract the user information without needing to perform redundant verification logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c662b6e2-d515-4f82-896b-4e0ff15f8a9c', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How do Interceptors in NestJS enable AOP (Aspect-Oriented Programming) and what are the performance impacts of chaining multiple interceptors?', N'Senior', N'Interceptors wrap the execution of route handlers, allowing for the injection of extra logic before or after a method is called. While powerful for logging or response transformation, chaining multiple interceptors adds overhead to the request stack and increases complexity in tracing the execution flow, which can complicate debugging in distributed environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b635b044-ac23-47ea-a711-4e0fff8d2459', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of the __init__.py file in a directory?', N'Intern', N'The __init__.py file tells Python that the directory should be treated as a package. In Django, it is essentially empty but required for Python to import modules from that folder.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b14fa352-870c-4ce9-8e4c-4e10b28c7963', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is Autowiring in Symfony?', N'Intern', N'Autowiring is a feature of the Service Container that automatically detects and injects dependencies into class constructors based on type-hints. It eliminates the need to manually configure every single service in the configuration files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9356530-d0b5-451a-87c6-4e1767adb0e5', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you organize your code?', N'Fresher', N'I organize my code by following a modular approach, using a clear folder structure, and adhering to coding standards and best practices. I separate concerns by dividing code into different layers such as components, services, and utilities. I also use naming conventions and documentation to ensure code readability and maintainability. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer What are some of the advantages and disadvantages of using TypeScript and compile-to-JavaScript languages Using languages that compile to JavaScript (most commonly TypeScript today, but historically also CoffeeScript, ReScript, Elm, and ClojureScript) can offer several advantages such as improved syntax, type safety, and better tooling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3c32992-0f30-46c8-be92-4e1877669de0', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How do signal-based updates in Qwik differ from standard state management libraries?', N'Senior', N'Unlike traditional state management that often triggers top-down re-renders, Qwik''s signal-based system is localized. It updates only the specific DOM elements bound to the signal, which minimizes the need for ''memoization'' or ''shouldComponentUpdate'' logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33999dc3-0ba0-4419-bcdd-4e19d00a4a15', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the function of the & character in Sass nesting?', N'Intern', N'The ampersand is used as a parent selector reference. It allows you to refer to the outer selector within a nested block, which is commonly used for pseudo-classes like hover or for BEM-style element naming.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
