INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c6966e6-b120-4de3-9472-4e1a9d59120a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the uses of closures?', N'Intern', N'Closures are a powerful feature in programming languages like JavaScript. They allow functions to retain access to variables from their containing (enclosing) scope even after the outer function has finished executing. This means that a function defined within another function can access variables from the outer function, even if the outer function has already returned. Here are some common use cases of closures: - Data Privacy: Closures can be used to create private variables and methods. By defining variables within a function''s scope and returning inner functions that have access to those variables, you can create a form of encapsulation, limiting access to certain data or functionality. - Function Factories: Closures are often used to create functions with pre-set parameters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f03c9bf5-ad37-4800-aa09-4e2011cd4046', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of Phoenix LiveView?', N'Intern', N'LiveView allows developers to build rich, real-time user experiences with server-rendered HTML. It maintains a persistent connection between the client and server to update the UI without needing custom JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4870b909-3a24-4e33-ac84-4e2023f60377', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is a layout file (+layout.svelte) used for?', N'Junior', N'A layout file is used to define common UI elements that persist across multiple pages, such as navigation bars, footers, or sidebars. By defining these in a parent layout, you avoid repeating the same code in every individual page component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
