INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2c5d12f-37c0-4a8c-b138-4e2345d065be', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue manage the reactivity of props in child components?', N'Senior', N'Props are reactive in the child component, but they are strictly read-only to enforce one-way data flow. If a child needs to modify a prop, it must emit an event to the parent, ensuring the state change is explicit and traceable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aeb593d4-d010-4812-b21a-4e2761aa66b9', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What are the architectural challenges of achieving ''Observability'' in serverless environments?', N'Senior', N'The ephemeral nature of serverless functions limits the ability to use traditional host-level monitoring agents. Observability must instead rely on distributed tracing headers and structured logging sent to external aggregators, which can introduce cold start latency and vendor-specific instrumentation requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
