INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4777b286-9439-4bd6-a954-4e2962eba030', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach a situation where a third-party API is failing intermittently but their status page says everything is green?', N'Senior', N'I would implement detailed request/response logging for the external service to capture the actual status codes and latency patterns occurring during the failures. I would then check our own egress proxy logs to see if the issue is limited to specific geographic regions or IP ranges, which often indicates localized routing or ISP-level issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'351e50f4-e905-4f9c-af2b-4e2973099866', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the role of the ClassLoader in the JVM.', N'Middle', N'The ClassLoader is responsible for loading class files from the file system, network, or other sources into the JVM memory. It follows a delegation model where a loader asks its parent to load a class before attempting to load it itself. This ensures that core Java classes are loaded by the bootstrap loader, maintaining security and consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
