INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'008ee613-c3ae-4601-beba-4e2c87225f84', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Describe the architecture of ''Project References'' and their utility in monorepo management.', N'Senior', N'Project references allow a large codebase to be split into smaller, independent sub-projects that can be compiled in isolation. This architecture improves build performance through incremental compilation and provides clearer dependency boundaries between different modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fffa5d20-b94b-43a6-812b-4e2d39142aa9', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Why is ''message replayability'' a critical feature for event-driven systems?', N'Senior', N'Replayability allows developers to re-process historical data in the event of a bug fix, system migration, or to bootstrap a new service with the state derived from past events. It requires the broker to maintain a persistent log of messages with a retention policy longer than the standard processing duration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
