INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d315776-3abb-4384-acff-4e2dc30e3233', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the browser support for react applications?', N'Intern', N'React supports all popular browsers, including Internet Explorer 9 and above, although some polyfills are required for older browsers such as IE 9 and IE 10. If you use es5-shim and es5-sham polyfill then it even support old browsers that doesn''t support ES5 methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5cea84b-0e3e-4243-900e-4e30eadf37cc', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Explain how consistent hashing helps in distributed caching.', N'Middle', N'Consistent hashing minimizes data movement when the number of cache nodes changes by mapping both keys and nodes onto a circular hash ring. When a node is added or removed, only a small fraction of keys need to be remapped to different nodes, ensuring system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7de4caf7-50ce-48e8-80c9-4e31e546939d', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the Quarkus ''REST'' extension?', N'Fresher', N'The REST extension, often using RESTEasy Reactive, allows developers to create RESTful web services. It is designed to be highly performant and non-blocking, making it efficient for handling HTTP requests in high-traffic applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4349d2a5-ea33-4263-9a30-4e321c139b93', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why might you use an expression index?', N'Middle', N'An expression index allows you to index the result of a function or calculation performed on a column. This is useful when queries frequently filter data based on computed values, as it allows the planner to use an index instead of performing the computation for every row during a scan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84dec406-ae14-4bd3-a30e-4e36de2a3b34', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the role of an Action in Remix?', N'Fresher', N'An action is a server-side function used to handle data mutations, such as form submissions or API updates. It processes the incoming request and modifies the data before the page reloads to show the new state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81d5b79b-6a33-4a91-b6fa-4e373d8f4c85', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What criteria do you use to determine whether to build a custom solution or use an existing open-source tool?', N'Senior', N'I evaluate the total cost of ownership, including long-term maintenance, security patching, and team expertise. If the requirement is core to our competitive advantage, building is often better; otherwise, I favor mature open-source solutions that can be integrated quickly and benefit from community support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cad307ca-2a70-4cbc-8605-4e375747b35d', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin handle the concept of variables compared to Java?', N'Fresher', N'Kotlin uses two distinct keywords for variable declaration: val for read-only, immutable references and var for mutable references. Unlike Java, where variables are mutable by default unless marked with final, Kotlin encourages immutability by prompting developers to use val whenever possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da40f0d7-4d73-41fc-acc4-4e382ee4226b', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are the primary data structures available in R?', N'Fresher', N'R supports several data structures, including vectors, matrices, arrays, lists, and data frames. Vectors are the most basic, while data frames are the most commonly used for storing tabular data with different types of variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e535a604-5dea-4e30-b467-4e393ae9ec14', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If a task is highly ambiguous, what is your first step?', N'Fresher', N'My first step is to ask clarifying questions to reduce the ambiguity. I would aim to define the core requirements and success criteria, as it is impossible to provide a meaningful estimate without a clear understanding of what ''done'' looks like.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e742d13-fe9b-43a3-ac16-4e3cb06a7c65', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach mitigating the risk of a single point of failure in a critical system?', N'Senior', N'I conduct a failure mode and effects analysis (FMEA) to identify single points of failure. I then prioritize redundancy implementation, such as multi-zone deployments and load balancing, to ensure that no single component failure can cause a total system outage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf2ab5ef-c3e6-4f6a-9788-4e3dd176f479', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the Symfony Service Container?', N'Intern', N'The Service Container is a powerful tool for managing the instantiation and configuration of objects, known as services. It implements dependency injection to decouple classes from their dependencies, making the code easier to test and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'514d1ef5-bff1-4357-a91b-4e41bca305a9', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a data dictionary?', N'Fresher', N'A data dictionary is a centralized repository of information about data, such as table names, column definitions, data types, and constraints. It serves as a reference for database administrators and developers to understand the structure and metadata of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a930c69-9d38-4a3e-b8a9-4e46237d3374', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Discuss the impact of ''deoptimization'' on the execution of JIT-compiled JavaScript code.', N'Senior', N'Deoptimization occurs when the engine''s speculative assumptions about object shapes or types prove false at runtime. The engine must discard the optimized machine code and revert to an interpreter or baseline compiler, causing a temporary but noticeable latency spike.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38288a27-0f71-47e1-85b4-4e47f940b581', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the purpose of the Quarkus Health extension?', N'Intern', N'The Health extension provides endpoints to report the status of the application, which is crucial for orchestrators like Kubernetes. It allows the platform to know if the application is alive and ready to receive traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9eb5090b-68f4-4a71-8e6e-4e4867ea6763', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is Pattern Matching in Scala?', N'Intern', N'Pattern matching is a mechanism for checking a value against a sequence of patterns. It is a more powerful version of a switch statement that can deconstruct complex data structures and extract specific values during the evaluation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd5a129a-110c-4f3b-b279-4e4e15e5c97a', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis achieve high performance despite being single-threaded?', N'Middle', N'Redis achieves high performance by keeping the entire dataset in RAM, which avoids disk I/O bottlenecks. Additionally, its non-blocking I/O multiplexing allows it to handle many concurrent connections efficiently without the need to spawn threads for every client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fed7d18-ae6b-46af-a761-4e4f311f8f03', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the role of a Controller in Symfony?', N'Fresher', N'A Controller is a PHP function or method that receives a request object, processes the application logic, and returns a response object. It acts as the bridge between the routing layer and the application data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8a93ecb-62cf-430d-ae46-4e5381a65127', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What are the benefits of using a CDN in a web architecture?', N'Middle', N'A Content Delivery Network (CDN) caches static assets like images, CSS, and JavaScript files on globally distributed servers closer to the end user. This reduces latency, decreases the load on the origin server, and significantly improves the overall performance and reliability of content delivery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2fc62b6-ad09-46e8-bf9d-4e541b632b2b', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the ''For'' component used for?', N'Fresher', N'The For component is a built-in utility for rendering lists. It is highly optimized to track changes in an array and update only the modified items in the DOM rather than re-rendering the whole list.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0d7225e-e3cd-48c2-b2f0-4e55ecfc5fe2', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Describe the function of the client:idle hydration directive.', N'Middle', N'The client:idle directive hydrates a component only after the page has finished loading and the browser is idle. This prioritizes the initial page load speed while still ensuring interactivity for secondary components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e1f3324-8a98-40c3-ac63-4e5613f79705', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How do Go interfaces differ from those in languages like Java or C#?', N'Middle', N'Go interfaces are satisfied implicitly rather than explicitly. A type does not need to declare that it implements an interface; if it provides the required methods, it is considered an implementation, which decouples the implementation from the interface definition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4004fa8-ad26-4ddc-aa24-4e5acd50ae94', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why is Ember considered a ''batteries-included'' framework?', N'Intern', N'Ember is called ''batteries-included'' because it provides almost everything a developer needs to build a complete application out of the box. This includes routing, data management, testing tools, and project scaffolding, reducing the need to rely on many separate third-party libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e01b248-333a-4dc3-afc2-4e5b39aee87c', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach a bug that you cannot reproduce locally?', N'Fresher', N'I would first gather all available logs, error reports, and environment details from the user or production system. Then, I would analyze the code path related to the reported issue and look for edge cases or dependencies that might differ between the environments. If possible, I would add instrumentation or logging to gather more data points during the next occurrence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48980401-7395-468c-af72-4e5e41d323de', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What are the limitations of type-safe extractors in complex request scenarios?', N'Senior', N'While extractors are powerful, they can lead to complex type signatures that are difficult to read and maintain. Furthermore, if multiple extractors attempt to consume the same part of the request, such as the body, it can lead to runtime errors, requiring developers to carefully manage extractor order and requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8259667a-d5eb-4d4c-81fb-4e5f6bd77cff', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How should one implement graceful shutdown in a Gin-based application?', N'Senior', N'Graceful shutdown is achieved by wrapping the Gin engine in an ''http.Server'' instance and listening for OS signals like SIGINT or SIGTERM. Upon receiving a signal, the application should call the server''s ''Shutdown'' method, which stops accepting new connections and waits for active requests to complete before terminating.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bd50a72-c6e2-41e6-b5ca-4e62b231fc84', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle large request payloads?', N'Senior', N'Axum allows for configuring body size limits via middleware, such as the ''DefaultBodyLimit'' layer, to prevent memory exhaustion attacks. This ensures that the server does not attempt to buffer excessively large requests into memory, protecting system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44182901-06e1-45cb-8042-4e64630dd6eb', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Does Litestar support OpenAPI documentation?', N'Intern', N'Yes, Litestar has built-in, automated support for generating OpenAPI specifications. It creates documentation dynamically based on your route handlers and type hints, allowing you to view your API documentation via tools like Swagger UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
