INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd96b623c-f7aa-4eb8-8670-4e681f9343b2', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the advantage of Axum''s ''Service'' trait over other frameworks?', N'Middle', N'The ''Service'' trait is a standardized, low-level abstraction that allows Axum to be used as a drop-in component in any framework supporting Tower. This creates high interoperability and allows the reuse of services between different web servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd394c949-f10c-4394-a649-4e74167d9a94', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte''s approach to reactivity compare to Proxy-based systems like Vue 3?', N'Senior', N'Svelte uses compile-time static analysis to track dependencies, whereas Vue uses runtime Proxies to intercept property access. Svelte''s approach avoids the overhead of wrapping objects in Proxies and works predictably with native JavaScript structures, though it requires an explicit assignment to trigger reactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dffd5a5a-3803-4684-81c2-4e7421a396d9', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the purpose of load balancing?', N'Middle', N'Load balancing distributes incoming network traffic across multiple servers to ensure no single server becomes overwhelmed. This improves responsiveness, increases reliability through redundancy, and allows for seamless scaling of application capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf432a53-be39-49c8-a469-4e74778e8ee1', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Is it possible to have a transaction that only performs a read?', N'Fresher', N'Yes, read-only transactions are common. They are used to ensure that a set of data remains consistent while it is being viewed or processed, even if no changes are being saved to the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89ab99ab-d971-401c-8a1f-4e7591066abe', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does rate limiting protect a system?', N'Middle', N'Rate limiting restricts the number of requests a user or client can make within a specific timeframe to prevent abuse and denial-of-service attacks. It ensures that system resources remain available for legitimate traffic by capping usage from single sources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53791284-f37b-4bb4-be52-4e7658a637c4', N'954a0331-deff-4399-b588-96f39fec001d', N'What are template statements?', N'Intern', N'A template statement responds to an event raised by a binding target such as an element, component, or directive. The template statements appear in quotes to the right of the = symbol like (event)="statement". Let''s take an example of button click event''s statement In the above expression, editProfile is a template statement. The below JavaScript syntax expressions are not allowed. 1. new 2. increment and decrement operators, ++ and -- 3. operator assignment, such as += and -= 4. the bitwise operators | and & 5. the template expression operators --------------------------------------', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea7bc8cf-8011-4606-91e7-4e7737618e01', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you manage the trade-off between using a proprietary vendor tool versus an open-source alternative?', N'Senior', N'Proprietary tools usually come with premium support and reduced integration effort, shifting the cost to licensing. Open-source offers transparency, community support, and no vendor lock-in, but requires an internal investment in expertise to manage upgrades, security, and potential custom patching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a22f9bf-b4ff-4a6d-8ef9-4e7752cecedd', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why is it beneficial to document your assumptions during an estimation task?', N'Intern', N'Documenting assumptions makes your thought process transparent and allows others to review your logic. It also makes it easier to update the estimate later if the underlying assumptions are proven to be incorrect.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'153227bf-5eac-4bf5-8fb4-4e7c81ce424c', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle synthetic events?', N'Junior', N'Preact does not use a synthetic event system like React. It uses standard DOM events directly, which helps reduce the library size and complexity while improving performance by avoiding the overhead of event delegation layers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
