INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a01aa6c-ea18-4d03-9314-4e7cbe181ca8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the freeze method', N'Intern', N'The freeze() method is used to freeze an object. Freezing an object does not allow adding new properties to an object, prevents removing, and prevents changing the enumerability, configurability, or writability of existing properties. i.e. It returns the passed object and does not create a frozen copy. Remember freezing is only applied to the top-level properties in objects but not for nested objects. For example, let''s try to freeze user object which has employment details as nested object and observe that details have been changed. Note: It causes a TypeError if the argument passed is not an object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bb90f0f-f89c-492e-84be-4e7e83f1db1e', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the purpose of the ''layout.js'' file in the App Router?', N'Intern', N'The layout file is used to define a shared UI structure that persists across multiple pages, such as navigation bars or footers. It allows you to maintain state and preserve the UI during navigation transitions between different pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
