INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e5b6462-dd42-4321-97ce-4e804f52c1ab', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between ''mutating'' and non-mutating methods?', N'Fresher', N'In structs and enums, methods cannot modify their properties by default. The ''mutating'' keyword allows a method to modify the instance''s properties, effectively creating a new instance behind the scenes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a44a06b-c21a-4918-8145-4e8499c0a2ab', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How would you optimize Actix for high-throughput static file serving?', N'Senior', N'Use Actix-files, which leverages efficient system calls like sendfile for zero-copy file transmission. Configuring correct cache headers and utilizing a reverse proxy in front of the application are also recommended to reduce the load on the Actix runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef83fa67-4f03-4c25-87e7-4e84ff6f7e84', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the purpose of ''yielding'' in a cooperative fiber system?', N'Middle', N'Yielding is the mechanism that allows a fiber to relinquish control to the scheduler, ensuring fairness. It allows the runtime to pick another ready-to-run fiber, which is essential for maintaining responsiveness in a system where I/O operations might take time to complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86d9b763-de90-4ed3-9a28-4e8778985cd6', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut address the ''Fat Jar'' issue common in other Java frameworks?', N'Senior', N'Micronaut’s AOT design results in smaller binary sizes because it excludes unnecessary reflection-based metadata and runtime scanning infrastructure. This leads to faster container deployment times and reduced storage requirements in the container registry.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'982d8e06-0264-4c92-bacb-4e883a4475a7', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What happens if you return a Promise from useEffect??', N'Middle', N'You should NOT return a Promise from useEffect. React expects the function passed to useEffect to return either nothing (undefined) or a cleanup function (synchronous function). i.e, It does not expect or handle a returned Promise. If you still return a Promise, React will ignore it silently, and it may lead to bugs or warnings in strict mode. Incorrect: Correct:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92d03193-4a6e-4ad3-b876-4e884e928999', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you handle distributed transactions across microservices to maintain data consistency?', N'Senior', N'Since distributed transactions like 2PC are non-scalable, you should utilize the Saga pattern. Sagas manage distributed transactions through a sequence of local transactions, each with a corresponding compensating transaction to roll back changes if a step fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95a012ea-f824-419d-b12e-4e897083aeed', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How does ''Bulkheading'' improve system reliability?', N'Middle', N'Bulkheading isolates resources, such as thread pools or memory, for different parts of an application. If one service or feature fails due to excessive load, the bulkhead ensures that the failure is contained and does not consume all available resources, keeping the rest of the system functional.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'234a5184-cb3e-4ae5-a95e-4e89d08a4f03', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is difference between document.getElementById() and document.querySelector()?', N'Fresher', N'1. document.getElementById(): Returns an element object representing the element whose id property matches the specified string. Since element IDs are required to be unique if specified, they''re a useful way to get access to a specific element quickly. 2. document.querySelector(): Returns the first matching Element node within the node''s subtree. If no matching node is found, null is returned. 3. document.querySelectorAll(): Returns a NodeList containing all matching Element nodes within the node''s subtree, or an empty NodeList if no matches are found. *Note: querySelector() is more useful when we want to use more complex selectors*.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca7a7f5c-3082-4133-b283-4e8a2e071fae', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why is ''Keyspace Notifications'' a useful feature?', N'Middle', N'Keyspace notifications allow clients to subscribe to Pub/Sub channels to receive events when specific keys are modified or expire. This is useful for building reactive systems, such as triggering cache invalidations or performing cleanup tasks when data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baa3b186-62ba-40e8-9003-4e8b443f00de', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are operators in C# and can you provide examples?', N'Intern', N'Operators in Care symbols or keywords responsible for specific program actions, such as basic arithmetic, logical evaluations, or assignment. Basic Operators Arithmetic Operators - Addition: + - Subtraction: - - Multiplication: * - Division: / - Modulus: % (remainder of division) Comparison Operators - Equal to: == - Not equal to: != - Greater than: > - Less than: = - Less than or equal to: > Assignment Operators - Simple assignment: = - Add then assign: += - Subtract then assign: -= - Multiply then assign: *= - Divide then assign: /= - Modulus then assign: %= - AND then assign: &= - OR then assign: |=', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e177d7c-af3c-4e42-bfad-4e8bead052d9', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Can you use different response types in Litestar?', N'Intern', N'Yes, Litestar supports various response types, including JSON, HTML, plain text, and redirect responses. You can specify the desired response type by returning specific response objects or by setting the appropriate content-type headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca2c9486-9a41-48d8-aeca-4e8c497c2a92', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember’s router handle asynchronous data loading for nested routes?', N'Senior', N'The router utilizes the ''model'' hook to manage asynchronous lifecycle transitions. By returning promises, the router pauses the transition until the data is fetched, ensuring that components are never rendered in an invalid state while simultaneously enabling concurrent data loading for parallel route segments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7777d22a-14ca-4dca-8b9d-4e8cba7a2e95', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does the ''client:only'' directive fundamentally change how a component interacts with the server?', N'Senior', N'The ''client:only'' directive forces the component to skip server-side rendering entirely, executing only on the client. This is essential for components that depend on browser-only APIs like window, document, or local storage that do not exist in the server environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd2d0df3-5495-407e-b0dc-4e8db29a81fd', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a Clustering Column in Cassandra?', N'Fresher', N'Clustering columns determine the sort order of data within a specific partition. They allow for efficient retrieval of data in a specific sequence, such as sorting logs by timestamp within a user ID partition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa5edfe4-bc2c-4aa7-9cc1-4e8f834df2af', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Describe the scope and lifecycle of an Alpine.js component.', N'Middle', N'A component is defined by a DOM element containing the data directive. Its lifecycle starts when the framework initializes the element, making the data object available to all its descendants, and ends when the element is removed from the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e6dd795-f351-4920-930f-4e91ed8322fa', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a virtual function, and why is it used?', N'Fresher', N'A virtual function is a member function in a base class that you expect to redefine in derived classes. It is used to achieve runtime polymorphism, ensuring that the correct function implementation is called based on the actual object type rather than the pointer type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'813fc311-11f1-48ee-a2b8-4e973a582968', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is Tailwind considered a ''low-level'' framework?', N'Intern', N'It is called low-level because it gives you the building blocks for design rather than dictating how a component should look. You are responsible for assembling those blocks to create the final appearance of your interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6124486e-3892-4748-864f-4e98de5c9ecb', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Why should you avoid tight coupling in software design?', N'Middle', N'Tight coupling makes systems difficult to modify, test, and deploy because changes in one component force changes in others. Loose coupling enables independent development and evolution of services, reducing the risk of side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a05a691-1552-4ca2-8c36-4e9ce1e9d72a', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What are the performance implications of using complex DTOs in Litestar?', N'Senior', N'While DTOs provide significant maintainability benefits, complex transformations add overhead during request processing. Architects must balance the granularity of DTOs with the latency requirements of the specific endpoint to ensure that data mapping does not become a bottleneck.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e154e3be-b856-43db-ba29-4e9cf6c75828', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Why is the distinction between ''def'' and ''async def'' in FastAPI path operations critical for performance?', N'Senior', N'If you define a path operation with ''def'', FastAPI runs it in a separate thread pool to prevent blocking the event loop. Using ''async def'' allows the operation to run directly on the event loop; if a synchronous, blocking function is defined as ''async def'', it will stall the entire event loop, causing severe performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4dbe99ad-fe10-4317-b850-4e9d29207985', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How do you set a status code in an Express response?', N'Intern', N'You set the HTTP status code by using the res.status() method before sending the response. For example, res.status(404).send() sends a 404 error back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e955786b-abc8-4f55-a33c-4e9fd1b38f5a', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the @Introspected annotation used for?', N'Fresher', N'The @Introspected annotation tells Micronaut to generate bean introspection metadata at compile-time. This allows the framework to access properties of a class without using slow runtime reflection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6096c1af-9d00-4eb2-91a0-4e9ff07cd9a0', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does tree shaking work in Dart''s AOT compilation?', N'Middle', N'Tree shaking is an optimization process where the compiler analyzes the dependency graph to remove unused code. By excluding classes, functions, or variables that are never referenced, the final executable size is significantly minimized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bdda815-5efc-49c4-acee-4ea012e71677', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you manage shared configuration across multiple microservices?', N'Middle', N'Shared configuration is best managed using a centralized configuration server or a distributed key-value store. This approach allows developers to update application settings in real-time across all service instances without needing to rebuild or redeploy the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
