INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d20ba02-f529-432c-90d1-4ea369143242', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain what a protocol is in Swift.', N'Junior', N'A protocol defines a blueprint of methods, properties, or other requirements that a class, struct, or enum must implement. It allows for a design pattern where different types can be treated polymorphically based on the capabilities they provide rather than their specific class hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
