INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a091b0a-c97a-417f-a59a-4eaa8bc0e3ff', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is eventual consistency and when is it appropriate?', N'Middle', N'Eventual consistency is a model where data updates are propagated to all nodes over time, but reads may return stale data temporarily. It is appropriate for systems where high availability and low latency are prioritized over strict real-time data accuracy, such as social media feeds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
