INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7dd0dfab-bb23-4abb-988c-4eb4fda26066', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between an interface and a class in Dart?', N'Fresher', N'In Dart, every class implicitly defines an interface containing all its instance members. While a class can be instantiated, an interface is a contract that a class must implement, meaning it must provide an implementation for every member defined in that interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
