INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9df455e-3b8f-46c7-9028-4ec03615cbcd', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the core philosophy behind Qwik?', N'Intern', N'Qwik is designed for instant loading by focusing on resumability. It aims to deliver minimal JavaScript to the browser initially and only loads more code when the user interacts with the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b53103ac-f76d-4d78-9071-4ec26cbd1746', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why is idempotent design critical in distributed message processing?', N'Middle', N'Distributed systems often rely on ''at-least-once'' delivery guarantees to ensure messages are not lost. Idempotency ensures that processing the same message multiple times does not change the result beyond the initial application, preventing data corruption from retries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'380c3d39-c6ea-4a5c-abba-4ec2d700da6c', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the primary purpose of Next.js compared to a standard React application?', N'Fresher', N'Next.js is a React framework that enables server-side rendering and static site generation, whereas standard React primarily focuses on client-side rendering. By rendering pages on the server, Next.js improves initial load performance and search engine optimization for web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
