INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c283347-68cb-48b2-8871-4ec3c0dac807', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the role of the ''proxy'' object in JavaScript?', N'Middle', N'A Proxy allows you to define custom behavior for fundamental operations on objects, such as property lookup, assignment, or function invocation. It is a powerful tool for implementing reactivity, validation, or logging without modifying the original object structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eba2a561-a5b0-4886-97bd-4ec46045e8ca', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt handle concurrent requests on the server without cross-pollinating user state?', N'Senior', N'Nuxt utilizes asynchronous context storage to ensure that each request has its own isolated context. By relying on Vue''s composable pattern, state is tied to the specific request lifecycle, preventing accidental sharing of user-specific data between concurrent server-side execution threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'975053e9-7006-40f5-aad7-4ec8d7acb59a', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is ASGI and how does it relate to FastAPI?', N'Intern', N'ASGI stands for Asynchronous Server Gateway Interface. It is the specification that allows Python web frameworks like FastAPI to communicate with web servers in an asynchronous manner.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c517ca9-3b80-4e7b-aff3-4ecbfb61a7c2', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off in automated testing coverage?', N'Fresher', N'High test coverage increases confidence and reduces regression bugs, but it requires significant time to write and maintain those tests. Lower coverage saves time during development but increases the risk of defects reaching the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c65b11d6-fcc2-4f78-993c-4ececf1e2fd8', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Can Lit components communicate with parent elements?', N'Intern', N'Yes, Lit components communicate with parent elements by dispatching standard DOM events. Parents can listen for these events to react to changes occurring inside the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
