INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fbdbaf7-0065-4984-bec5-4ed18aece0ae', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the benefit of having a single project for frontend and backend?', N'Fresher', N'A unified project eliminates the need to maintain separate codebases or complex API contracts between the frontend and backend. It allows for faster development cycles, easier data sharing, and a more cohesive architectural approach.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f81fe14c-4af4-44f0-9041-4ed6a3b03df1', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the benefit of keeping a task simple instead of over-engineering?', N'Junior', N'Simple solutions are easier to read, maintain, and debug, which reduces the likelihood of introducing new bugs. Over-engineering adds unnecessary complexity that can make the system harder to change or adapt as requirements evolve.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f02773f6-1646-46a0-aadb-4ed74c5b9ffd', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the purpose of the Buffer Pool in InnoDB.', N'Middle', N'The Buffer Pool is a memory area that caches table and index data as it is accessed. It improves performance by allowing frequent data operations to occur in RAM rather than requiring constant disk I/O, which is significantly slower.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03058ed6-4ad8-4613-95e4-4ed94650f3c8', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the trade-offs between using a Rails concern versus a service object for shared logic?', N'Middle', N'Concerns are best for mixing shared behavior directly into models or controllers to keep them DRY, but they can lead to bloated classes and hidden dependencies if overused. Service objects move business logic out of the model, promoting better separation of concerns and testability, though they introduce more boilerplate and require manual instantiation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55e18d41-9070-4659-91f5-4edc7080e669', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Why is it important to use ''HTTPException'' instead of raising standard Python exceptions in FastAPI?', N'Middle', N'Raising an ''HTTPException'' allows you to pass specific HTTP status codes and detail messages to the client in a standard format. Standard Python exceptions may cause internal server errors or return generic 500 status codes, which do not provide meaningful information to the API consumer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6994c313-21d3-4959-89a6-4edc9776542e', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between a process and a thread in the context of Python''s multiprocessing module?', N'Senior', N'Threads share the same memory space and are restricted by the GIL, making them unsuitable for CPU-bound tasks in Python. Processes have their own memory space and Python interpreter instance, allowing them to bypass the GIL and leverage multiple CPU cores for true parallel execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'742198b7-b832-4e04-99e5-4ede6865982f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the ''Map'' collection in Dart?', N'Fresher', N'A Map is a collection of key-value pairs where both keys and values can be of any type. Each key must be unique, and it provides an efficient way to retrieve values based on their associated keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c95b70d3-3b3b-4d68-b2d9-4ee2bde6f4e6', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the impact of the browser''s style recalculation phase on the critical rendering path?', N'Senior', N'Style recalculation is the process of matching CSS selectors to DOM elements to compute styles. If the DOM tree is deep or selectors are overly specific, this phase can become a performance bottleneck, blocking the main thread and delaying the First Contentful Paint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fef5ba59-afc1-4ffb-8580-4ee2f523e4f0', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the role of the ''Netty'' server in Micronaut and why is it preferred over traditional servlet containers?', N'Senior', N'Netty is a high-performance, asynchronous event-driven network application framework that powers the Micronaut HTTP server. Unlike traditional servlet containers that require a thread per request, Netty uses non-blocking I/O, allowing for higher throughput and lower resource consumption under heavy concurrent load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a0cf592-826f-4ae3-a658-4ee35794be0f', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a cache, and why is Redis a popular choice for it?', N'Junior', N'A cache is a high-speed data storage layer that stores a subset of data so that future requests for that data can be served faster. Redis is popular for caching because its in-memory architecture provides extremely low latency and it supports expiration policies for stale data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88af8753-e7be-433a-9bd8-4ee5d6a2a460', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix handle the ''thundering herd'' problem during system startup?', N'Senior', N'Actix does not inherently solve the thundering herd problem at the infrastructure level, so developers must implement strategies like staggered actor startup or initialization delays. By staggering the start times of resource-intensive actors, the system avoids spikes in CPU and memory usage that could trigger OOM kills.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5ad8c3e-c971-4fae-aa5f-4ee9f4cb68ec', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Why is the use of ''important'' in CSS generally discouraged in large-scale design systems?', N'Senior', N'The !important flag bypasses the standard CSS specificity hierarchy, creating an ''arms race'' of styles that becomes impossible to manage at scale. It prevents natural overrides, necessitates further use of !important to fix subsequent issues, and leads to tightly coupled, brittle codebases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61705629-400f-432c-9631-4eefc168927c', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the trade-offs when using ''Cluster'' module versus process managers like PM2 for scaling Node.js applications?', N'Senior', N'The Cluster module provides a built-in way to spawn child processes sharing the same port, which is effective for multi-core utilization. PM2 adds a layer of process management, offering features like process monitoring, auto-restart on failure, log management, and zero-downtime reloads, which are critical for production-grade reliability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4082edd0-2ccb-414d-b5e9-4eeff4158441', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the benefit of Svelte''s small bundle size?', N'Intern', N'Because Svelte compiles components into vanilla JavaScript and does not require a large framework runtime library to be shipped to the browser, the resulting application files are smaller. Smaller bundles lead to faster download and parsing times, improving the user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
