INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f69351bd-e9f2-45c2-8862-4ef8a7ecf815', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the purpose of the ''dynamic'' type in Dart?', N'Intern', N'The dynamic type tells the Dart compiler to disable static type checking for a specific variable. It allows a variable to hold any type of value and defers type validation until the program is actually running.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
