INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'773c7c7f-87b4-4f4e-9720-4efd65b14185', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the impact of Python’s dynamic nature on JIT compilation performance?', N'Senior', N'The extreme dynamism of Python, such as the ability to modify classes and methods at runtime, makes it difficult for JIT compilers to perform aggressive optimizations like static dispatch. This leads to overhead compared to statically typed languages, as the interpreter must perform type checks and dictionary lookups frequently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db48599d-b513-4cb4-8c1b-4f0019abac1f', N'954a0331-deff-4399-b588-96f39fec001d', N'What is Component Test Harnesses?', N'Intern', N'A component harness is a testing API around an Angular directive or component to make tests simpler by hiding implementation details from test suites. This can be shared between unit tests, integration tests, and end-to-end tests. The idea for component harnesses comes from the PageObject pattern commonly used for integration testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88a86e19-4fc7-4b22-8c05-4f00ca0e0c57', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS achieve ''Concurrent Rendering''?', N'Middle', N'SolidJS uses a scheduler that can prioritize different reactive updates. It allows the framework to transition between states without blocking the main thread, maintaining UI responsiveness during heavy computation or data loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11ee1a03-8d74-4555-b427-4f01df7a1bc7', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is ''Write Skew'' and why does it occur in Snapshot Isolation?', N'Senior', N'Write skew happens when two transactions read the same data, but update disjoint sets that together violate a global business constraint. It occurs in snapshot isolation because the system only checks for write-write conflicts on the same row, failing to detect conflicts based on shared read data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72804011-ea35-4c47-bacc-4f02221e2208', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does schema flexibility in NoSQL differ from relational databases?', N'Intern', N'Relational databases require a predefined, rigid schema where all rows must follow the same structure. NoSQL databases are schema-less or schema-flexible, allowing each record to have a different set of fields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ddf801f-fcf4-442d-a7b5-4f0231ac107c', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How do constraints help in database design?', N'Junior', N'Constraints are rules applied to table columns that restrict the type of data that can be entered. They help maintain data quality and integrity by enforcing rules like uniqueness, non-null values, and default values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c30c138f-e90f-4886-a950-4f02fe36b2b8', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How do you handle API key compromise in a high-traffic environment?', N'Senior', N'The system should support immediate key invalidation and have a robust versioning strategy that allows for seamless key rotation. Additionally, monitoring and alerting on anomalous usage patterns allow for automated detection and suspension of compromised keys before significant data exfiltration occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20dd2ce9-b459-43ab-8391-4f030b442b95', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Explain the significance of the ''no virtual DOM'' approach in SolidJS for performance.', N'Senior', N'By eliminating the virtual DOM, SolidJS avoids the overhead of creating, diffing, and patching a shadow tree structure. Instead, it compiles template expressions into direct DOM manipulations, significantly reducing memory allocation and CPU cycles during updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e7cb392-09da-4ba7-b630-4f03463f770c', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What does the ''c.JSON'' method do in Gin?', N'Junior', N'The c.JSON method is used to serialize a Go object or map into JSON format and send it as the HTTP response. It automatically sets the ''Content-Type'' header to application/json for the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3e4f56d-fa55-4bf2-abcf-4f03d7630ba3', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is an App object in Actix?', N'Fresher', N'The App object is the core component of an Actix web application used to register routes, middleware, and shared application state. It acts as a factory that creates instances of the application for every worker thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b8d6eb6-b309-4bae-8afd-4f052d68a6ec', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do you handle links in SvelteKit?', N'Fresher', N'SvelteKit uses standard anchor tags for navigation. When a user clicks a link, SvelteKit intercepts the request and performs client-side navigation, which is faster and maintains the application state without a full page reload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52844bd6-7d05-4e57-ba67-4f092f89b7c3', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the concept of optional binding.', N'Fresher', N'Optional binding is a safe way to check if an optional contains a value and, if so, extract that value into a temporary constant or variable. It is typically performed using ''if let'' or ''guard let'' syntax.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9605ab4f-97e2-4894-94a1-4f0d2a2eb3f7', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do you create HOC using render props?', N'Fresher', N'You can implement most higher-order components (HOC) using a regular component with a render prop. For example, if you would prefer to have a withMouse HOC instead of a component, you could easily create one using a regular with a render prop. This way render props gives the flexibility of using either pattern.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'543da4af-9609-4308-9450-4f0d66404a46', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it important to handle errors gracefully rather than letting an application crash?', N'Fresher', N'Graceful error handling keeps the application stable and provides a better user experience by informing the user of the issue instead of just failing. It also allows the system to log the error for developers to fix while preventing the application from entering an inconsistent or dangerous state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8583db4d-c797-41d7-a75f-4f0ddd342194', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the trade-off between optimistic and pessimistic locking?', N'Middle', N'Pessimistic locking prevents conflicts by locking data for the duration of a transaction, which ensures consistency but reduces concurrency. Optimistic locking assumes conflicts are rare and only checks for them during the commit phase, allowing for higher throughput but requiring logic to handle potential conflicts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e330904-d4fb-45ab-8a0f-4f0f303bc193', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the main differences between CHAR and VARCHAR data types?', N'Intern', N'CHAR is a fixed-length data type, meaning it will always occupy the defined amount of space regardless of the input size. VARCHAR is a variable-length data type that only uses as much storage as the data entered requires, plus a small overhead for length tracking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'642ae3e8-a1e7-4f0a-91c2-4f1102338a31', N'075b8862-431c-4678-9767-f55359758a4a', N'Explain the role of ''custom directives'' in extending Vue''s capabilities.', N'Senior', N'Custom directives provide a way to hook into the low-level DOM lifecycle of an element, such as focusing an input or integrating with non-Vue libraries. They are best used for logic that directly manipulates the DOM, as their scope is restricted to the element they are bound to.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'555220f8-c1b0-45d0-a524-4f1112c96087', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the primary difference between v-if and v-show?', N'Junior', N'v-if is a conditional rendering directive that adds or removes elements from the DOM based on the expression''s truthiness. v-show keeps the element in the DOM but toggles its CSS display property, making it more efficient for elements that need to be toggled frequently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8602870a-df48-45ff-a3a7-4f1117e256a6', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'In what scenarios would you choose Redux over React Context API, and what are the primary performance implications?', N'Senior', N'Redux is preferred when managing complex, frequently updating global state, as it provides sophisticated dev tools, middleware support, and optimized subscription mechanisms. React Context lacks a built-in mechanism for selective re-rendering, meaning any change to a context provider value triggers a re-render of all consuming components, which can lead to performance bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01d7366b-0381-42f6-b0ae-4f128fa7c566', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between ''Unit Testing'' and ''Integration Testing'' in Rails?', N'Middle', N'Unit tests focus on verifying the behavior of individual methods or classes in isolation, usually models or services. Integration tests verify how different parts of the application work together, such as the interaction between controllers, views, and database records during a full HTTP request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'995675f6-a85d-4f88-ad42-4f161dea0d9a', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the benefit of using Lit over vanilla web components?', N'Junior', N'Lit simplifies the boilerplate required to create custom elements. It provides built-in tools for reactive state management, efficient rendering, and property observation that would otherwise need to be manually implemented in vanilla JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
