INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'463810ac-8d67-410d-827c-4f1a783d9d31', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the significance of the ''split brain'' scenario in a cluster?', N'Middle', N'Split brain occurs when network issues cause a cluster to partition into two separate groups, both believing they are the master. Modern Elasticsearch versions prevent this by requiring a minimum quorum of master-eligible nodes to form a functional cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40ec4f5a-f056-4668-8dac-4f1b49925200', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the purpose of the Echo Logger middleware?', N'Intern', N'The Logger middleware is a built-in utility that automatically records details about every incoming HTTP request, such as the status code, latency, and path. This is essential for monitoring application performance and debugging issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78ed86e0-e36d-4633-927d-4f1ced8092c5', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain how Phoenix manages memory consumption during large file uploads.', N'Senior', N'Phoenix uses stream-based file handling to process uploads in chunks, preventing the entire file from being loaded into memory at once. This avoids memory spikes and allows the system to remain responsive even when handling multiple large file transfers simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2c01197-1605-4ee4-b004-4f1e37cf9fd8', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of the ''Redo Log''?', N'Middle', N'The redo log ensures durability by recording all changes made to the data pages before they are flushed to the disk. In the event of a crash, MySQL uses the redo log to replay these changes, ensuring that committed transactions are not lost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bdbaf1d-24fc-4572-8d14-4f20e97bb856', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Does Chi include a built-in web server?', N'Fresher', N'No, Chi is strictly a router. It relies on the standard library''s http.ListenAndServe function to actually start and manage the web server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'735ef115-d9c7-4165-9b99-4f2342f9365d', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the MySQL ''Flush'' mechanism handle dirty pages?', N'Senior', N'The master thread or page cleaner threads periodically flush dirty pages from the buffer pool to the data files. This process is throttled to balance the need to free up clean pages with the impact on overall system I/O latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94f79280-89f4-43db-9e2a-4f23615f5bae', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify''s startup time compare to other frameworks, and why does it matter in serverless environments?', N'Senior', N'Fastify''s focus on low overhead and minimal dependencies leads to faster cold-start times compared to monolithic frameworks. This is crucial for serverless deployments where initialization latency directly impacts user-perceived performance and cost efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'657b55fc-8b85-4f34-ac2f-4f264c5ff832', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How do you calculate Read Capacity Units (RCU) for your table?', N'Middle', N'One RCU represents one strongly consistent read per second for an item up to 4 KB, or two eventually consistent reads per second. You calculate the required RCUs by dividing the total expected read size by the capacity unit size and adjusting for the consistency model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a17a1e81-1e04-410d-9cd5-4f2979cd5a85', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do browser engines handle invalid CSS properties within a declaration block?', N'Senior', N'Browsers follow the ''error handling'' principle where they ignore individual invalid declarations but continue to parse the rest of the rule. This allows for forward compatibility, enabling developers to use newer CSS features wrapped in feature queries while maintaining support for older browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f45ebfc5-2a5e-412e-9a4e-4f2ab3656697', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the purpose of the ''c.JSON'' method in Echo?', N'Junior', N'The c.JSON method is used to send a JSON response to the client. It automatically sets the appropriate Content-Type header to application/json and encodes the provided struct or map into a JSON string.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20a38bbf-0fe7-4691-ae3b-4f2bfe3f53b8', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why is it important to use ''Unregister'' or cleanup logic in component hooks?', N'Middle', N'Failing to clean up event listeners or timers created in a component can lead to memory leaks and unexpected behavior. Using the ''willDestroy'' hook or modifier teardown logic ensures that these resources are properly released when the component is removed from the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d0c2fdd-811c-46c3-af2a-4f2f2b26bf71', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does the ''Atomicity'' property ensure in a transaction?', N'Middle', N'Atomicity ensures that a transaction is treated as a single ''all-or-nothing'' unit of work. If any part of the transaction fails, the entire transaction is rolled back, leaving the database in its original state before the transaction began.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3884638c-c141-45ed-831a-4f30b8def5bd', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the significance of the Hono ''serve'' function in different runtime environments?', N'Middle', N'The serve function is an abstraction layer that interfaces with the specific server implementation of the underlying runtime. It ensures that the Hono application can be deployed to diverse environments like Cloudflare Workers or Bun without changing the core application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b25f4ad8-f138-4632-a0dc-4f34a375c169', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are template literals', N'Intern', N'Template literals or template strings are string literals allowing embedded expressions. These are enclosed by the back-tick (`) character instead of double or single quotes. In ES6, this feature enables using dynamic expressions as below, In ES5, you need break string like below, Note: You can use multi-line strings and string interpolation features with template literals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e5c4ef5-e3b5-42ac-90e4-4f352a5af942', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does the ''N+1 query problem'' manifest in application-to-database communication?', N'Senior', N'The N+1 problem occurs when an application executes one query to fetch parent records and then executes N additional queries to fetch children for each parent. This results in excessive network round-trips and high latency, which should be mitigated using joins, eager loading, or batch fetching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7d34c42-b640-4b51-aa8c-4f378e79d1b2', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Module Federation change the architectural approach to micro-frontend scaling?', N'Senior', N'Module Federation allows multiple independent builds to share dependencies and modules at runtime without a central monolith. This enables teams to deploy micro-frontends autonomously while reducing bundle duplication by sharing common vendor libraries via a remote container.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9db3bdc-4f71-4dd7-baea-4f38dffc6462', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the benefit of the ''preSerialization'' hook in a data-heavy application?', N'Senior', N'The preSerialization hook allows for the modification or transformation of data before it is converted to a string for the response. This is ideal for masking sensitive fields or injecting metadata globally without having to update every individual route handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20aeca50-78b1-4ff0-be2c-4f3a276c9489', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is RESTful routing?', N'Intern', N'RESTful routing is a design approach that maps standard HTTP verbs (GET, POST, PATCH, DELETE) to specific controller actions. This standardizes how an application handles resources, making the API intuitive and predictable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97287913-b4da-4cde-b7b2-4f3a7ced6a4d', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the benefit of Redis being single-threaded?', N'Intern', N'The single-threaded nature simplifies the architecture and eliminates the overhead of context switching and locking mechanisms. This allows Redis to remain highly performant and predictable without the complexity of managing thread synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
