INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68fe2891-0683-46f4-a588-4f52a94548a3', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain the role of the Event Loop in Node.js and how it handles asynchronous operations.', N'Middle', N'The Event Loop is a single-threaded mechanism that orchestrates the execution of callbacks, promises, and I/O tasks. It offloads non-blocking operations like file system access or network requests to the underlying system kernel or worker threads, then processes the results once they are ready.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
