INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ec69919-f96e-44a5-b33c-4f5efaa7f716', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why is it important to include testing and documentation in your initial estimates?', N'Junior', N'Testing and documentation are essential parts of a complete, maintainable feature, not secondary add-ons. Omitting them leads to inaccurate estimates and results in a project that is difficult to support or scale, ultimately costing more time in the long run.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
