INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f15860ba-9dbd-4738-bc46-4f64ed6ba252', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why is it often discouraged to store UI state (like modal visibility) in the global Redux store?', N'Senior', N'Global stores are best suited for domain data that needs to be shared across many components. Storing transient UI state in Redux increases the frequency of store updates, which can cause performance degradation and bloat the debugging logs with irrelevant information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59cce007-d755-4767-abd5-4f65baad4291', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are the three service lifetimes in ASP.NET Core?', N'Intern', N'The three lifetimes are Transient, Scoped, and Singleton. Transient services are created every time they are requested, Scoped services are created once per client request, and Singleton services are created the first time they are requested and last for the lifetime of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
