INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8493b7b-446c-4b15-8783-4f6afd225935', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the difference between Channels and standard HTTP requests in Phoenix.', N'Middle', N'HTTP requests are stateless, follow a request-response cycle, and close after the response is sent. Channels provide persistent, bidirectional, real-time communication using WebSockets, allowing the server to push updates to clients asynchronously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
