INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ec41707-506c-42a9-b937-4f6e5f9f5e13', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is TypeScript compilation, often called transpilation?', N'Fresher', N'Since browsers and environments like Node.js cannot execute TypeScript directly, it must be compiled into standard JavaScript. This process, known as transpilation, strips away the type annotations and converts modern syntax into a version of JavaScript compatible with the target environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
