INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b76ccc2-7a7e-49d8-ab0c-4f929f0fa264', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How do B-Tree and LSM-Tree storage engines differ in terms of write amplification and read latency?', N'Senior', N'B-Trees perform in-place updates, leading to higher write amplification due to page splits and random I/O, but offer predictable point-lookup performance. LSM-Trees batch writes into sequential log-structured files, significantly reducing write amplification at the cost of higher read latency, as the system must merge multiple levels of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
