INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4f9c2f0-9ad1-4cd5-b7fe-4f97a6c45906', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Why might you choose Astro over a framework like Next.js?', N'Junior', N'You might choose Astro if your project is content-focused and performance is the highest priority. Astro''s default behavior of removing JavaScript makes it significantly lighter for sites that don''t need complex, state-heavy application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e73e4f1-2626-4b5a-9ceb-4f98814cdba3', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the ''sizeof'' operator work?', N'Fresher', N'The sizeof operator returns the size in bytes of a variable or a data type. It is evaluated at compile-time and is useful for ensuring code portability across different hardware architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2d948ca-4896-4e29-8b15-4f9a2a0f20ea', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If two tasks seem equally difficult, how do you decide which one to estimate as taking longer?', N'Junior', N'I look for hidden complexities such as integration points, testing requirements, or the need for external documentation. If one task involves touching legacy systems or unfamiliar areas, I would estimate it as taking longer due to the increased risk of complications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'838c9a40-c4f3-47c0-982a-4f9a82f90e62', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why does Fastify avoid using global middleware?', N'Junior', N'Fastify avoids global middleware to prevent hidden dependencies and ensure that every part of the application is explicitly defined and encapsulated. This makes it easier to trace where specific logic is applied and improves overall performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb524bb3-acd1-4f10-9422-4f9b1150e043', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why does Lit use ''lit-html'' as its templating engine instead of standard JSX?', N'Middle', N'lit-html uses tagged template literals, which allows the browser to parse the template once as a static string. This approach is highly efficient because it updates only the dynamic parts of the DOM rather than re-evaluating an entire virtual DOM tree, resulting in smaller bundle sizes and faster runtime performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acda7ab1-fbc9-463a-9607-4f9b62e88e47', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How do C++ concepts improve the design of generic libraries?', N'Senior', N'Concepts allow developers to specify constraints on template parameters directly in the code, providing clear interfaces and better error messages when those constraints are not met. They simplify the implementation of generic algorithms by replacing complex SFINAE tricks with readable, compiler-verified requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4722dbff-2441-4f78-9f02-4fa0f282c12d', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Explain the difference between Echo''s Group and standard route registration.', N'Middle', N'Route groups allow you to organize routes under a common path prefix and apply specific middleware to that subset. This improves code organization and ensures that authentication or logging is only applied to necessary endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
