INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb0d05a6-44d4-48c6-9dab-4fa2ac336b5b', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the primary goal of a prototype during the design phase?', N'Intern', N'The goal of a prototype is to validate key assumptions and test the feasibility of a design with minimal investment. It helps identify potential issues early and provides stakeholders with a tangible model to review before full-scale development begins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2be502c-43e7-4221-9e66-4fa2e070abe6', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is a workspace image in R?', N'Junior', N'A workspace image is a snapshot of all objects currently in the R environment, usually saved as a binary file with an RData extension. It allows users to save their current progress and restore all variables and functions exactly as they were in a future session.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1622a430-136f-483e-8ede-4fa6eccd99b3', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How can you return JSON data from an Actix-web handler?', N'Junior', N'You can return JSON by using the Json struct provided by Actix-web. By deriving the Serialize trait on your Rust data structure, Actix automatically handles the serialization of your struct into a JSON response body.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5193df3c-e035-4c6c-a334-4fa70066704d', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of a virtual table (vtable)?', N'Middle', N'A vtable is a mechanism used by the compiler to support dynamic dispatch for virtual functions. Each class with virtual functions has a vtable containing pointers to those functions, and objects of that class contain a hidden pointer to the vtable to determine which implementation to execute at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'beba26ac-e89a-4670-a75a-4fafe71d07e9', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Describe the impact of position-independent code (PIC) on binary execution.', N'Senior', N'PIC allows a shared library to be loaded at any address in the process''s address space without requiring relocation updates. It is achieved by using a Global Offset Table (GOT) to access global data and a Procedure Linkage Table (PLT) to call functions via indirection, introducing a slight performance overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed63d55a-d85e-4b44-8da4-4fb0bc3c6187', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is your strategy for migrating a monolithic legacy database to a microservices architecture without downtime?', N'Senior', N'I would use the Strangler Fig pattern to gradually move functionality, employing a dual-write mechanism or change data capture (CDC) to keep the old and new databases synchronized. Once the new service is validated, I would flip traffic via feature flags or a service mesh, eventually decommissioning the legacy schema after a verification period.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'002e90e9-bbac-4884-b2fa-4fb4a4faa6ae', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the primary advantage of using Micronaut''s ahead-of-time (AOT) compilation compared to traditional reflection-based frameworks?', N'Junior', N'Micronaut uses AOT compilation to perform dependency injection and proxy generation at build time rather than at runtime. This significantly reduces application startup time and memory consumption because the framework does not need to scan the classpath or use reflection when the application starts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6cdd261-49f7-4b96-adaa-4fb64c9276b9', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why should you avoid storing session state on the web server in a system intended for scaling?', N'Fresher', N'Storing session state on the server makes it ''sticky,'' meaning the user must return to the same server for subsequent requests. This hinders the ability to distribute traffic across multiple servers effectively. Storing session information in an external, shared database or cache allows any server instance to process the request, which is necessary for horizontal scaling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10869cf1-95e1-4a10-b530-4fbc3cb98f34', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How do NestJS ''Pipes'' improve data integrity compared to manual validation inside controllers?', N'Senior', N'Pipes centralize validation and transformation logic, ensuring that data is sanitized or schema-validated before it ever reaches the controller. This keeps controllers lean and ensures that the system fails early and consistently if the incoming payload is malformed or invalid.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c1f8d16-686a-419b-94a0-4fbc43027190', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Explain the difference between a Route and a Component in Ember.', N'Middle', N'A Route is responsible for loading data from the model hook and determining which template to render, effectively acting as the controller for a URL state. A Component is a reusable UI element that encapsulates its own logic and template, focusing solely on how data is presented.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4e1a545-c5ec-44eb-9b05-4fbe1a5c7f80', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Why is it important to implement a custom HTTP error handler in Echo?', N'Middle', N'A custom error handler allows you to centralize error logging, monitoring, and standardized response formatting for all application errors. Without one, Echo defaults to a generic plain-text response, which might expose internal implementation details or fail to match your API''s expected JSON error schema.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
