INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b921c86f-0ac9-465b-9b1d-4fc638f9c0f5', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the difference between ''require'' and ''load''?', N'Intern', N'''require'' loads a file only once, even if called multiple times, which is ideal for libraries. ''load'' executes the file every time it is called, which is useful during development if you want to reload changes without restarting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5795aeb0-d09f-4534-ab14-4fc73c5447fd', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi maintain compatibility with the Go standard library?', N'Intern', N'Chi is built on top of the standard net/http package. It accepts and returns the standard Handler interface, meaning any middleware or handler designed for the standard library will work with Chi.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'754c9022-b5d9-41c1-82bb-4fc74d55931c', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why is Redis considered single-threaded, and what are the performance implications?', N'Middle', N'Redis uses a single-threaded event loop to process commands, which eliminates the overhead of context switching and locking mechanisms associated with multi-threading. While this makes it extremely fast for O(1) operations, blocking commands can stall the entire server, so long-running operations must be avoided.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2a4efbb-fe9a-4b98-8505-4fc75aa3da5b', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact manage global state in a way that differs from React?', N'Middle', N'Preact does not impose a specific global state management pattern, but it supports the standard Context API identical to React. Because Preact is smaller, developers often choose lighter-weight state management solutions like Signals, which provide fine-grained reactivity and better performance than traditional reducer-based approaches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a967624b-2c35-4c2f-8cf0-4fca96d7dee7', N'954a0331-deff-4399-b588-96f39fec001d', N'How can I translate attribute?', N'Fresher', N'You can translate attributes by attaching i18n-x attribute where x is the name of the attribute to translate. For example, you can translate image title attribute as below, By the way, you can also assign meaning, description and id with the i18n-x=" | @@ " syntax.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75aef0c1-10e5-42c6-9921-4fccc309a468', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Can Elasticsearch handle unstructured data?', N'Intern', N'Yes, Elasticsearch is excellent at handling unstructured data like logs, social media posts, and text documents. It uses full-text search capabilities to make this data searchable and analytical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f261c2a-bdc7-4d87-bd73-4fcdf9de40df', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is React Suspense and what does it enable?', N'Intern', N'React Suspense is a feature that allows you to handle asynchronous operations in your React components more gracefully. It enables you to show fallback content while waiting for something to load, such as data fetching or code splitting. You can use it with React.lazy for code splitting and with libraries like react-query for data fetching. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73b7447f-5268-4354-aff3-4fce5ff0e320', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Does Kotlin support checked exceptions?', N'Intern', N'No, Kotlin does not have checked exceptions. All exceptions in Kotlin are unchecked, meaning the compiler does not force you to catch or declare them in the function signature.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93d0db85-3d40-459f-994a-4fd21eb7f6e3', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using a centralized configuration management system versus environment variables?', N'Junior', N'Centralized systems allow for real-time updates and auditing across many services, but add an external point of failure. Environment variables are simple, portable, and require no extra infrastructure, but updating them often requires restarting the application and makes secret management harder.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90dfc981-d9e7-462c-8e98-4fd666a48294', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle asynchronous data fetching?', N'Middle', N'Asynchronous operations are handled using native JavaScript promises within Alpine directives or component methods. By setting component state inside the .then() or await block, Alpine''s reactivity system automatically triggers a DOM update once the data is returned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10077819-17f6-4996-b40f-4fd977fff24e', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony''s ''ParamConverter'' facilitate cleaner controller logic, and what are the trade-offs of using it extensively?', N'Senior', N'ParamConverters automate the transformation of request data directly into domain objects, reducing boilerplate code in controllers. However, over-reliance can lead to hidden side effects and make debugging difficult if the conversion logic fails or behaves inconsistently across complex entity relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd68f6d4d-08c8-40ed-b168-4fdb0a5c44bd', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How can we create an immutable class in Java?', N'Fresher', N'Immutable class means that once an object is created, we cannot change its content. In Java, all the wrapper classes (like Integer, Boolean, Byte, Short) and String class is immutable. Rules to create immutable classes: * The class must be declared as final * Data members in the class must be declared as final * A parameterized constructor * Getter method for all the variables in it * No setters', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91c996eb-6790-458c-9b1f-4fdba5a6b732', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does Bloom filter usage improve read performance in storage engines?', N'Senior', N'Bloom filters provide a space-efficient way to determine if a specific key exists within a data file without actually reading the file from disk. By eliminating unnecessary disk I/O for keys that are not present in a segment, they significantly reduce latency for read operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a60c9efe-6087-489b-8e91-4fe21d423056', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s ''spread operator'' contribute to code conciseness?', N'Middle', N'The spread operator allows for the insertion of elements from one collection directly into another, reducing the need for manual loops or imperative addition methods. This leads to cleaner, more declarative code when working with lists, maps, or sets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fac9ece1-52d1-4470-b45d-4fe970abd906', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle ''progressive enhancement'' in form actions by default?', N'Senior', N'SvelteKit uses the native browser form submission behavior as the fallback, ensuring functionality even if JavaScript fails to load or execute. When JavaScript is active, it intercepts the form submission to provide a seamless SPA experience, showing how SvelteKit prioritizes robustness and accessibility at the architecture level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
