INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f99a9d9-eba3-4895-988a-4fe994ad0d1f', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Why is it important to use ''set.seed()'' in R for reproducible research?', N'Middle', N'R''s random number generators are pseudo-random, meaning they follow a deterministic sequence based on an initial state. Setting the seed ensures that this sequence is identical every time the code is run, which is essential for producing reproducible results in statistical modeling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd0172f3-9b9e-49d1-8f6a-4feac726e9cd', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Why might you introduce a caching layer like Redis in front of a relational database?', N'Middle', N'Caching reduces the load on the primary database by serving frequently accessed read requests directly from memory. This latency improvement prevents the database from becoming a bottleneck during traffic spikes and allows for better overall system throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ab4774a-f8d2-42f1-91aa-4ff0497fc6ed', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What are the advantages of using CSS containment?', N'Middle', N'The ''contain'' property allows developers to isolate a subtree of the DOM from the rest of the page. This prevents layout or paint changes in one part of the document from triggering a global re-render, significantly improving performance in complex applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67a807d2-3c62-4754-b08d-4ff100d2b8ff', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Does Remix require a specific backend language?', N'Junior', N'No, Remix is a web framework built on standard Web Fetch APIs. While it typically uses Node.js or similar environments to run the server, it is designed to be platform-agnostic and can run on various serverless or edge environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d20ac52-1035-471b-8833-4ff148742c5e', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum manage state sharing across different handlers?', N'Junior', N'Axum uses a shared application state that is passed through the router. Handlers can access this state by using the State extractor, which provides read or write access to shared data like database pools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d5d968f-6352-48a2-ae32-4ff1c37329db', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain the purpose of ''Data Transfer Objects'' (DTOs) in an AdonisJS application.', N'Middle', N'DTOs are used to define the structure of data passing between different layers of the application, such as from the controller to a service. They provide type safety and ensure that service methods receive only the data they require, decoupling them from raw request objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc91370e-cd44-4aca-918e-4ff5866a4439', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why are Go interfaces considered ''implicit'' and what are the architectural consequences?', N'Senior', N'Interfaces are implicit because types do not need to explicitly declare they implement an interface, reducing coupling between packages. This allows for ''duck typing'' at compile time, which enables developers to define interfaces where they are used rather than where they are implemented, promoting cleaner, more modular code design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6094a734-70ac-4e60-83dc-4ff7653e7831', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between a Concern and a Cross-cutting Concern in Spring AOP?', N'Fresher', N'Cross-cutting concerns are aspects of software development that affect the entire application, yet are largely kept separate from the core business logic. This separation improves the modularity, maintainability, and reusability of the codebase. Spring Aspect-Oriented Programming (AOP) is tailored for managing cross-cutting concerns. While a "concern" is a more general term, referring to anything that requires the application''s attention, a "cross-cutting concern" specifically relates to the aspects that cut across different modules or layers of a software system. Examples of Cross-Cutting Concerns - Logging: The need to log method invocations or business operations. - Security: Centralized control for authentication and authorization mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adbf6701-7037-45c9-b3be-4ff8bec65858', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Explain the trade-offs between using React.memo versus useMemo in a performance-critical application.', N'Senior', N'React.memo is a higher-order component used to prevent re-renders of entire components based on prop shallow comparison. useMemo is a hook designed to memoize the result of expensive calculations within a component to avoid re-running logic on every render, thus optimizing computational overhead rather than tree traversal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e704709e-14d4-49fe-9a4c-4ffc2e04f690', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How can you share data between different middlewares in Hono?', N'Junior', N'You can share data by attaching properties to the ''c.set'' and ''c.get'' methods on the Context object. This acts as a request-scoped storage bucket, allowing downstream middlewares or route handlers to access data processed earlier in the pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94fe1e9b-4f09-4e37-b53a-4ffc8ab7c995', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the lifecycle of an Ember component?', N'Fresher', N'The lifecycle consists of various hooks that execute at different stages of a component''s existence, such as when it is initialized, rendered, or destroyed. These hooks allow developers to trigger specific logic at the right time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5345b9c7-05d0-44f7-a1cd-4ffcac00c483', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is meant by ''multi-master'' replication?', N'Middle', N'Multi-master replication allows write operations to be performed on any node in the cluster, which are then synchronized to all other nodes. While it improves write availability and performance, it significantly increases the complexity of conflict resolution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'143f2f0a-6e3b-43bb-8340-4ffeaf389e50', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why is Vite faster than older bundlers like Webpack?', N'Intern', N'Vite is faster because it leverages native browser ESM and performs dependency pre-bundling with esbuild. Unlike older bundlers that must process the entire application before starting, Vite only compiles code as it is requested by the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85553568-2407-4180-a518-4ffeeef0eb23', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the role of the property decorator''s ''type'' option?', N'Fresher', N'The type option informs Lit about the expected data type of a property. This allows Lit to correctly convert attribute strings into the specified JavaScript type, such as Boolean, Number, or Array.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8b2d239-93cb-4c9c-9f1a-5002b6d55d05', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB implement pagination?', N'Middle', N'When a query or scan operation returns a large dataset, DynamoDB returns a ''LastEvaluatedKey'' in the response. The application must use this key as the ''ExclusiveStartKey'' in the next request to fetch the subsequent page of results until no further data remains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'953a0f9f-f070-4a87-9b44-500332c7e8d2', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are tasked with estimating the time to complete a feature you have never built before, what steps would you take to provide a realistic estimate?', N'Fresher', N'I would start by breaking the feature down into smaller, manageable sub-tasks to identify potential complexities. Next, I would research the necessary technologies or consult with senior team members to understand the risks and dependencies involved. Finally, I would provide a range based on these findings, accounting for a buffer for unexpected challenges rather than giving a single, optimistic deadline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27251dde-c38d-4453-b774-50034ce8cca5', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the primary purpose of an Angular Module?', N'Junior', N'An Angular Module organizes an application into cohesive blocks of functionality. It helps manage dependencies, configure providers, and define the scope of components, directives, and pipes available to the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'129f8c00-a88e-4f69-9e77-5005cbc607d9', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Difference between Function, Method and Constructor calls in JavaScript?', N'Middle', N'1. Functions: The simplest usages of function call: 2. Methods: in JavaScript are nothing more than object properties that are functions. 3. Constructors: Like function and method, constructors are defined with function. Unlike function calls and method calls, a constructor call new Employee(''Drishya Sama'', 28) creates a new object and passes it as the value of this, and implicitly returns the new object as its result. The primary role of the constructor function is to initialize the object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33565b4f-9e1a-4a0d-bb56-5006208f1431', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the difference between a public and private item in Rust?', N'Junior', N'By default, all items in Rust are private to the module they reside in. To make an item accessible outside of its module, you must explicitly use the pub keyword.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06d83586-6c22-403e-aca7-5006274ee722', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do ''Utility Types'' like Pick, Omit, and Partial improve code maintainability?', N'Senior', N'These utility types allow developers to derive new types from existing ones without manual duplication, which ensures that changes to the base model automatically propagate throughout the system. This reduces the risk of type drift and makes the codebase significantly easier to refactor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f37b5691-0bd9-498a-bf0e-5008825ec553', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Compare the performance impact of JSON serialization in Phoenix versus using binary protocols like Protobuf.', N'Senior', N'JSON serialization is text-based and computationally expensive to parse at high throughput. Binary protocols like Protobuf reduce payload size and drastically lower CPU consumption during serialization and deserialization, making them ideal for high-frequency, performance-critical real-time communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69ed8c4f-f50c-4d38-b621-500e63aa2bdc', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How do Swift''s protocols facilitate generic programming compared to C++ templates?', N'Senior', N'Swift uses protocol-oriented programming with witness tables for existential types, allowing for type erasure and separate compilation. C++ templates use monomorphization, which generates specialized code for every type, resulting in faster execution but larger binary sizes. Swift''s approach balances flexibility and binary size by using dynamic dispatch for protocols and static specialization where appropriate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2da60469-4c6f-4dae-939b-50101f9cff5f', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the significance of the ''Primary Key'' selection in a distributed database?', N'Senior', N'In distributed systems, the primary key often determines the data distribution across nodes. A poorly chosen key can lead to uneven data distribution, causing some nodes to become overloaded while others remain idle, ultimately bottlenecking the entire cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a6690b6-6697-4621-801e-5013fbcb7a01', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt’s ''Code Splitting'' work, and how can developers optimize it for large-scale applications?', N'Senior', N'Nuxt automatically splits code based on page routes and dynamic imports to reduce the size of the initial bundle. Developers can further optimize this by using lazy loading for components or heavy libraries that are not required for the above-the-fold content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8436f8e-1004-4243-8593-5014e2f4b459', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Why is Astro considered good for SEO?', N'Intern', N'Astro is great for SEO because it generates standard, static HTML that search engine crawlers can easily read. Additionally, the fast load times provided by its architecture are a key ranking factor for search engines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf9f2b37-e340-4eed-bab8-50155f5edd24', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the difference between static and dynamic dispatch in Swift and how the compiler decides between them.', N'Senior', N'Static dispatch happens at compile-time via direct function calls, while dynamic dispatch uses virtual method tables or witness tables to resolve calls at runtime. The compiler prefers static dispatch for performance, reserving dynamic dispatch for class methods, protocols, or when types are not fully known at compile-time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbd4e06f-a07f-4994-82b5-5017335bdcea', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the benefit of Lit''s update cycle?', N'Junior', N'The update cycle ensures that DOM modifications are batched and performed efficiently. By waiting until the next microtask to render changes, Lit avoids unnecessary re-renders and improves application performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0dfac653-cd94-4249-ae18-50192574def1', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide between building a custom solution versus using a third-party library?', N'Junior', N'I consider the complexity and maintenance burden of building a custom solution versus the trade-offs of introducing a new dependency. If the library is well-maintained, widely used, and solves a standard problem, it is usually better to use it rather than reinventing the wheel.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c691c26a-4b8b-4bff-aa35-501af8f6e31a', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How would you handle global state in a large-scale Lit application?', N'Senior', N'Global state is best handled using a centralized store combined with the Context API or a reactive controller. This allows components to subscribe to specific pieces of state and trigger updates only when their relevant data changes, maintaining high performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d8e9774-31c8-40d0-90ee-501c29ae0e6e', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the difference between secret injection at runtime and build-time for containerized applications?', N'Senior', N'Build-time injection risks embedding secrets into container images, which may be stored in registries and leaked through image history. Runtime injection, using tools like Vault or Kubernetes Secrets, ensures that sensitive credentials remain ephemeral and are only available to the container during execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1efbdb5d-eebc-4d62-b902-501fddc7a66e', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is ''Hot Module Replacement'' (HMR) in Nuxt?', N'Junior', N'HMR is a development feature that updates modules in the browser as soon as you save a file without requiring a full page reload. This preserves the application state and significantly speeds up the development workflow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55b6bfde-9752-4f3d-ae37-5020a8bd7562', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does the NestJS lifecycle hook system aid in managing external resource connections during server startup and shutdown?', N'Senior', N'Lifecycle hooks like OnModuleInit and OnModuleDestroy provide deterministic points to initialize or clean up connections to databases, caches, or message brokers. This ensures that resources are gracefully closed during server termination, preventing data corruption or connection leaks in the infrastructure layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26c880b3-1194-4b59-a5d6-5020e3ca51d3', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Describe the impact of False Sharing in Java and how it can be mitigated.', N'Senior', N'False sharing occurs when multiple threads modify variables residing on the same CPU cache line, causing unnecessary cache coherency traffic. It can be mitigated by padding data structures to ensure that frequently accessed, independent variables are located on different cache lines, thereby improving performance in highly concurrent systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'930bcf9b-431c-47d0-8ffa-502313bfb373', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of Ecto Changesets?', N'Junior', N'Changesets are used to filter, cast, and validate data before it is sent to the database. They ensure that incoming data meets the required criteria and help track changes made to a record, providing a safe way to handle database operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae0f8993-2514-410a-8a42-50274aa2315f', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Describe the difference between optimistic and pessimistic locking in ActiveRecord.', N'Middle', N'Pessimistic locking uses database-level locks (SELECT FOR UPDATE) to prevent other transactions from modifying a record until the current transaction is complete. Optimistic locking adds a version column to the table to detect concurrent modifications, raising an error if a record was changed by someone else before the current save operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e05f123c-a783-46ac-8a94-50295d9573db', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What are the architectural implications of using a message queue for inter-service communication versus a service mesh?', N'Senior', N'Messaging queues provide temporal decoupling, allowing services to interact without being simultaneously online. Service meshes prioritize direct request-response communication, which is better suited for real-time operations requiring immediate feedback but lacks the inherent buffering and resilience of queues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7dff6891-e321-475a-b715-502a44b1c493', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What does it mean for a database transaction to be ACID compliant?', N'Junior', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably, meaning either the entire operation succeeds or none of it does, and the data remains in a valid state even in the event of system failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de9aff3f-16ac-42f4-a4ab-502a8346ba55', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What are the trade-offs of using symmetric versus asymmetric encryption?', N'Middle', N'Symmetric encryption is faster and better suited for large datasets, but it requires a secure way to share the same key. Asymmetric encryption uses a public-private key pair, making key distribution easier, but it is computationally more expensive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6892768d-baff-47cc-9525-502c685bb9ba', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is it important to use ''environment variables'' for sensitive configuration settings?', N'Intern', N'Using environment variables keeps sensitive data, like passwords or API keys, out of the source code. This prevents secrets from being accidentally shared or committed to shared repositories where unauthorized people could access them. It is a fundamental security practice for protecting application credentials.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8726004c-0e7b-4ca7-bd48-502e967221f9', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the architectural difference between R''s ''shallow'' and ''deep'' copying?', N'Middle', N'R generally uses shallow copies for performance, where the structure of an object is duplicated but the underlying data might be shared until a modification occurs. Deep copying would involve duplicating all nested data structures, which is safer but significantly more resource-intensive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e823fa81-6578-4bbe-8de5-502fb5144877', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you evaluate if a third-party API integration is ''reliable enough'' for production?', N'Senior', N'I analyze the provider''s historical uptime records, the quality of their documentation, and the availability of sandbox environments for testing. I also evaluate the necessity of implementing a local cache or a circuit breaker pattern to protect my system from the provider''s potential instability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a0b9647-56cc-4375-a741-50309935f4a7', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of a ''routing'' key in Elasticsearch?', N'Middle', N'Routing allows you to control which shard a document is placed on by providing a custom value. By ensuring related documents are stored on the same shard, you can significantly improve search performance for queries that filter by that routing key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1773678c-9e41-4be4-91b5-50384b7a2c36', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is a Health Check in Quarkus?', N'Intern', N'A health check is a feature that allows the application to report its status, such as whether it is ''up'' or ''ready'' to receive traffic. This is critical for orchestrators like Kubernetes to decide if a container needs to be restarted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e45d64a-f44a-4e8d-9746-5039e8f26076', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do browser vendors determine the order of CSS properties in the cascade when specificity is equal?', N'Senior', N'When specificity is identical, the browser applies the rule that appears last in the stylesheet or the one that was loaded last in the document. This is known as the source order, and it serves as the final tie-breaker in the cascade resolution process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a07a6723-7042-4c17-8470-503b6f6a63c8', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Does Remix provide built-in support for environment variables?', N'Intern', N'Yes, Remix allows you to access environment variables on the server. However, you must explicitly define which variables should be exposed to the client to ensure sensitive information remains secure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1226c077-63f6-48ad-830b-503da13a8277', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a wide-column store?', N'Intern', N'A wide-column store is a NoSQL database that organizes data into tables, rows, and dynamic columns. Unlike relational tables, each row can have a different number of columns, making it flexible for large datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81c21b35-f7ef-4e8d-8ef8-503fc3a09fb2', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do you include a partial file in a main Sass file?', N'Fresher', N'You use the @import or @use rule followed by the name of the partial file. You do not need to include the underscore or the file extension when referencing the file in the import statement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b449c1e-f0b0-48d9-9bab-503fcedea20f', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the difference between an ''App'' level middleware and a ''Router'' level middleware in Litestar?', N'Middle', N'App-level middleware wraps the entire application and executes for every single request, while Router-level middleware is scoped to specific sub-paths. Using router-level middleware improves performance by only executing code for the routes that actually require it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b32ac66c-18bb-422d-8642-5041b181a4e5', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the benefit of zero-hydration for mobile users?', N'Fresher', N'Mobile users often have slower network connections and less powerful hardware. By removing hydration, Qwik ensures that the device does not spend time processing large JavaScript files, leading to a much smoother and faster user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edf4ce37-6d3f-4947-863f-50429be989b2', N'954a0331-deff-4399-b588-96f39fec001d', N'Why would you use a Resolver in Angular routing?', N'Middle', N'Resolvers are used to fetch data before navigating to a route, ensuring that the component has all required data before it is rendered. This provides a better user experience by preventing empty states or flickering, though it can delay the route transition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4045c6d-3db5-4ba3-b649-5042b7dfd956', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is an Ember Service?', N'Intern', N'An Ember Service is a singleton object that is available throughout the entire application. Services are typically used to manage shared state or logic, such as user authentication status, shopping carts, or application-wide configuration settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c1c2695-2470-4fdf-b5f1-5042d1840cfe', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the concept of ''Type Erasure'' in Scala.', N'Middle', N'Type erasure occurs during compilation where generic type information is removed to maintain compatibility with the JVM. Because of this, runtime checks cannot distinguish between different generic types, such as a list of integers versus a list of strings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ff7b092-aaea-457e-94d6-5044ef7c2b32', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What does it mean for Cassandra to be an ''AP'' system in the context of the CAP theorem?', N'Intern', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. Cassandra is categorized as an AP system, meaning it prioritizes availability and partition tolerance, often providing eventual consistency rather than immediate, strong consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e379dcc-2bcd-4ed2-8a66-5044f8440285', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is next()?', N'Intern', N'- next(): A callback function that, when called within a middleware, passes control to the next middleware in the stack. - next() is typically invoked to signal that a middleware has completed its tasks and that the request should move on to the next middleware. - If a middleware doesn''t call next(), the request flow can get stuck, and the subsequent middlewares won''t be executed. Use-Cases 1. Regular Flow: Invoke next() to move the request and response objects through the middleware stack. 2. Error Handling: If a middleware detects an error, it can short-circuit the regular flow and jump directly to an error-handling middleware (defined with app.use(function(err, req, res, next) {})). This is achieved by calling next(err), where err is the detected error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3a16d37-e05d-4d52-b676-50486bd0bb23', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why does Web Storage only support strings, and how do you safely store and retrieve complex data?', N'Fresher', N'The Web Storage API stores all values as plain strings. Passing a non-string value calls .toString() on it implicitly — which for objects produces "[object Object]" and for arrays produces a comma-joined string — silently corrupting the data. The correct solution is to serialise with JSON.stringify before writing and deserialise with JSON.parse after reading. JSON.stringify has limitations: it drops undefined values, converts Date objects to ISO strings (losing the Date type), cannot serialise functions, and throws on circular references. A robust storage utility must handle these edge cases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28b9a0f0-4d7c-4623-a9dc-50499daaf19d', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the impact of Preact''s small size on tree shaking?', N'Middle', N'Preact''s modular design and small codebase make it highly tree-shakeable. Modern bundlers can easily remove unused features, ensuring that only the code necessary for the application''s functionality is included in the final production build.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87e8780a-985b-4501-a05d-50504eb4d251', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the var keyword in C#?', N'Intern', N'Introduced in C3.0 along with the Language-Integrated Query (LINQ) features, the var keyword primarily serves to reduce redundancy. Key Benefits - Code Conciseness: It streamlines code by inferring types, especially with complex types or generic data structures. - Dynamic and Anonymous Types Support: It''s useful when using dynamic types or initializing objects with an anonymous type; a feature useful in LINQ queries. Avoid Misusing var It''s important to use var with caution to prevent these issues: - Type Clarity: Incorporating explicit type declarations can enhance code clarity, especially for beginners or when working with inherited code. - Code Readability for Method Chaining: Avoid using var excessively when chaining methods to maintain readability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb2d97ce-203f-4248-acdb-5051fe84666b', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the downsides of Redux compared to Flux?', N'Fresher', N'While Redux offers a powerful and predictable state management solution, it comes with a few trade-offs when compared to Flux. These include:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ced39da-f7b4-4b77-82be-505554909fae', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the concept of ''Spring Boot Starter'' dependencies.', N'Middle', N'Starters are a set of convenient dependency descriptors that you can include in your application to quickly get all the necessary dependencies for a specific technology. They simplify build configuration by managing version compatibility and reducing the number of manual dependencies you need to define.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48dbe807-5762-45c5-bf61-5055738e1b9e', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Can Tailwind CSS be used in a project that already has a large legacy CSS codebase?', N'Middle', N'Yes, Tailwind can be integrated alongside legacy CSS by using a custom prefix for its utility classes. This prevents class name collisions and allows for a gradual migration path where new components are built with Tailwind while legacy components remain untouched.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7344b970-a0eb-4254-a121-505a2370823a', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the stack differ from the heap in terms of memory management?', N'Middle', N'The stack is used for static memory allocation and local variables, managed automatically by the CPU with very fast access. The heap is used for dynamic memory allocation, requiring manual management via functions like malloc and free, which offers more flexibility but carries a risk of memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd7df008-b32e-437d-82fb-505abcc7c726', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How do fibers affect the observability and debugging of a backend application?', N'Middle', N'Observability becomes more complex because traditional stack traces may not represent the full execution history across fiber yields. Debuggers must be fiber-aware to correctly show the state of individual fibers rather than just the state of the underlying OS threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'508b5e9c-10e2-41b2-9386-505ae08054b2', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What does ''progressive hydration'' usually refer to, and how is it different from Qwik?', N'Fresher', N'Progressive hydration attempts to hydrate parts of the page over time to improve performance. Qwik is different because it avoids hydration entirely, preferring a resumable model where code is only loaded on interaction, not just based on priority.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'884b209e-cdb2-4ccf-a002-505be5cd59e0', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the benefit of using Symfony''s ''Messenger'' component over standard synchronous processing?', N'Middle', N'Messenger allows for asynchronous task execution by decoupling the message producer from the consumer. This improves performance for long-running tasks by moving them to background workers and enhances system reliability through built-in retry mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'182731bd-dc55-48ff-b215-505cefbaa484', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs when choosing between asynchronous and synchronous communication in a distributed system?', N'Senior', N'Synchronous communication provides immediate feedback and simplifies error handling but creates tight coupling and risks cascading failures. Asynchronous communication via message queues decouples services and increases system resilience, but it requires addressing eventual consistency and implementing robust retry and dead-letter queue mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06b5cd0f-efec-4f6d-8287-50628e130b81', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the role of Pydantic in FastAPI''s request validation and serialization process?', N'Senior', N'Pydantic performs data validation and type enforcement at runtime using Python type hints. It automatically parses incoming request bodies, validates them against defined schemas, and handles error reporting, effectively decoupling business logic from manual input validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcf799f0-f5a4-4914-a94f-50646ffe6449', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are JavaScript object property flags and descriptors?', N'Intern', N'In JavaScript, property flags and descriptors manage the behavior and attributes of object properties. Property flags Property flags are used to specify the behavior of a property on an object. Here are the available flags: - writable: Specifies whether the property can be written to. Defaults to true. - enumerable: Specifies whether the property is enumerable. Defaults to true. - configurable: Specifies whether the property can be deleted or its attributes changed. Default is true. Property descriptors These provide detailed information about an object''s property, including its value and flags. They are retrieved using Object.getOwnPropertyDescriptor() and set using Object.defineProperty().', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae74ccba-e0b9-43a0-80b9-5069083810b4', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle event listeners compared to standard frameworks?', N'Fresher', N'Qwik uses a global event listener at the document level that intercepts events. Instead of attaching listeners to every individual DOM element during hydration, Qwik uses the information serialized in the HTML to identify and execute the required function only when an event occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7250975-60ff-4a7f-930c-506a9097fccc', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the primary architectural benefit of Nuxt''s modular system?', N'Middle', N'Modules allow you to extend the core functionality of Nuxt without modifying the base code, promoting a plugin-based architecture. This enables teams to share functionality like authentication, analytics, or UI libraries across multiple projects consistently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc99da7a-e880-4fc6-bc79-506d8b230462', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a gossip protocol?', N'Intern', N'The gossip protocol is a peer-to-peer communication mechanism that Cassandra nodes use to discover each other and share state information. It allows nodes to know which other nodes are active or dead without a central server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba56c0e0-6bf1-4c81-b35a-506f77162865', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why is Axum considered an asynchronous framework?', N'Junior', N'Axum is built on the Tokio runtime, which provides an asynchronous execution model for Rust. This allows Axum to handle many concurrent connections efficiently without blocking threads while waiting for I/O operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e5c7fd3-fa2b-4483-a4c7-506fe7177e51', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI''s handling of pydantic models differ from traditional ORM model serialization?', N'Senior', N'FastAPI uses Pydantic for data validation and schema-based serialization, which is optimized for API contracts rather than database mapping. While ORMs focus on database state, Pydantic focuses on the structure of the data transmitted over the wire, providing a clear separation between the persistence layer and the presentation layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0251b00f-351c-440a-af2a-5070596179b6', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do you handle user events in Svelte?', N'Intern', N'User events, such as clicks or input changes, are handled using the on: directive followed by the event name. You assign a function or an inline statement to this directive to define what happens when the event is triggered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a086d5e1-d597-4bf1-8f4e-50717f8120c6', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it important to follow the principle of least privilege in system design?', N'Intern', N'The principle of least privilege limits the access rights of users and applications to only what is strictly necessary to perform their tasks. This minimizes the potential security impact of a compromised account or a system error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c11fd9d-4884-4e2f-9020-507200db2cda', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'When should you use ''client:idle'' instead of ''client:load''?', N'Senior', N'The ''client:idle'' directive waits until the browser''s main thread is free before hydrating the component, which is ideal for non-critical, interactive elements that shouldn''t compete for resources during initial page load. It is a user-centric optimization that ensures the most important content is ready before background tasks start processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bedc022-c925-4af3-a706-5075161b7295', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the purpose of an error tracking system?', N'Junior', N'An error tracking system automatically logs and groups software exceptions, providing developers with stack traces and user context. This helps prioritize bugs based on how often they occur and how many users they impact.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ec5ce09-e1d9-4c3e-a41f-50769e61050c', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are the trade-offs of using a ''Shared Module'' versus a ''Global Module'' in NestJS?', N'Senior', N'Shared modules are imported explicitly where needed, making the dependency graph explicit and easy to trace. Global modules are automatically available everywhere, which simplifies development but obscures dependencies, making it harder to identify which services are actually relying on specific functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26981943-6c3a-458a-a9ec-507778da5bc4', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS handle Exception Filters?', N'Middle', N'Exception filters catch unhandled exceptions across the application and transform them into standardized JSON responses. They allow developers to maintain a consistent API error structure and handle specific error types globally or at a controller level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
