INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa68be05-40f2-4624-ae44-507ad8a0fa24', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What are the implications of using a cache-aside pattern on system availability during database downtime?', N'Senior', N'Cache-aside relies on the database for cache population; if the database fails, cache misses cannot be resolved, leading to total system failure for those requests. Using a resilient strategy like serving stale data during outages can maintain availability, provided the business requirements allow for eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
