INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f700714e-1e5d-481b-b92a-5083b2153fc4', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix handle backpressure when dealing with high-traffic spikes?', N'Senior', N'Phoenix benefits from the Erlang VM''s built-in message queueing and process scheduling, which inherently throttles execution based on available resources. Additionally, developers can use GenStage or Flow to implement explicit backpressure mechanisms, preventing the system from being overwhelmed by decoupling producers from consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd76cdb1c-4c4d-40ec-ba1b-5086108dd5ce', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between internal and external linkage, and how do they affect variable visibility?', N'Middle', N'External linkage allows a variable or function to be visible and accessible across different translation units, usually by using the extern keyword. Internal linkage restricts the scope to a single translation unit, typically achieved by using the static keyword, which prevents naming conflicts and limits the visibility of implementation details.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
