INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c50320f4-f40c-459a-8a6f-508a8c6aec5b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the concept of prototypal inheritance and how it differs from classical inheritance.', N'Middle', N'Prototypal inheritance allows objects to inherit properties and methods directly from other objects via a prototype chain. Unlike classical inheritance, which requires defined classes as blueprints, prototypal inheritance is dynamic, meaning objects can be linked to new prototypes at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
