INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0f334d4-5d83-4bc7-ad2c-508c9d552c3c', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro''s ''Islands Architecture'' differ from the hydration models used by frameworks like Next.js or Nuxt?', N'Senior', N'Astro defaults to zero-client-side JavaScript, shipping only the necessary components as interactive islands while rendering the rest as static HTML. Unlike traditional frameworks that hydrate the entire page tree, Astro isolates hydration to specific components, significantly reducing the main-thread blocking time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5fe8e5e-8a5b-46fd-868d-508d8f7a23bc', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the types of Indexes available in MongoDB?', N'Intern', N'MongoDB supports the following types of the index for running a query. 1. Single Field Index: MongoDB supports user-defined indexes like single field index. A single field index is used to create an index on the single field of a document. With single field index, MongoDB can traverse in ascending and descending order. By default, each collection has a single field index automatically created on the _id field, the primary key. Example: We can define, a single field index on the age field. With this kind of index we can improve all the queries that find documents with a condition and the age field, like the following: 2. Compound Index: A compound index is an index on multiple fields. Using the same people collection we can create a compound index combining the city and age field.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'466d18a0-d070-4768-8a3d-508eabb42eef', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the difference between a cluster, a node, and a shard?', N'Junior', N'A cluster is a collection of nodes that work together to hold data, while a node is a single server instance that is part of a cluster. A shard is a smaller, self-contained portion of an index that allows data to be distributed across multiple nodes for scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea4e952c-5618-4797-b06c-508fe8756010', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the role of the ''using'' directive in C#?', N'Intern', N'The ''using'' directive allows you to use types defined in a namespace without specifying the fully qualified name of the type. It essentially tells the compiler to look for types within the referenced namespace during the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
