INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cde11c07-8a2b-4c38-aa13-509413e2aba2', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the role of the NestJS DI container in facilitating unit testing and how it differs from traditional dependency injection in other frameworks.', N'Senior', N'The DI container allows for the seamless replacement of real service implementations with mocks or stubs during test execution. Unlike more static frameworks, NestJS''s DI system is dynamic and modular, allowing for fine-grained control over the dependency graph during module instantiation, which simplifies testing complex service hierarchies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
