INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92153c19-b782-4a54-9259-50959526b197', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Describe the security implications of utilizing a Sidecar proxy pattern for service mesh security.', N'Senior', N'The sidecar pattern decouples security logic like TLS termination and policy enforcement from the application code, ensuring consistent security posture across polyglot services. However, it increases the attack surface of the sidecar container itself and introduces complexity in lifecycle management and patching of the proxy infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7249a44f-e2ac-488f-9dd2-5098d3456a8d', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the architectural benefits and drawbacks of using Nominal typing patterns within TypeScript?', N'Senior', N'Since TypeScript is inherently structural, nominal typing must be simulated using techniques like ''branded'' or ''opaque'' types. These provide stronger domain modeling and prevent accidental mixing of incompatible types, but they introduce boilerplate and may complicate interoperability with standard library functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4503f1e1-5ee6-4150-bce1-509950c4677f', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is a Bundle in Symfony and why is it used?', N'Fresher', N'A Bundle is a structured directory that contains a set of files that implement a specific feature or functionality, such as user authentication or a blog system. Bundles are designed to be reusable and shareable across different projects. By organizing code into bundles, developers can keep their application modular and maintainable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd49cc4de-e29c-4b79-ab33-509b3fa9dd4b', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between UseRouting and UseEndpoints?', N'Middle', N'UseRouting marks the point in the pipeline where the request URL is matched to an endpoint. UseEndpoints is where the actual code for that endpoint, such as a controller action or minimal API, is executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19a24a6c-2c7a-492a-aeca-509bc2b948f0', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain the architectural concept of ''Facade Pattern'' in Angular state management.', N'Senior', N'A Facade acts as a simplified entry point to complex service or store logic, hiding the underlying implementation details from the component. This creates a clean separation of concerns and makes components easier to test, as they only interact with the Facade interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
