INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27690708-c8d6-4b24-96ea-50ab22e6ff20', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do you distinguish between symptoms and root causes when observing a distributed system experiencing a high-latency spike?', N'Senior', N'Symptoms are external indicators such as high p99 latency or increased error rates, while root causes are the underlying technical failures like resource exhaustion or deadlock. To differentiate, utilize distributed tracing to correlate request paths with infrastructure metrics, allowing you to isolate the specific component or dependency causing the bottleneck. This separation prevents addressing cosmetic alerts rather than the structural flaw.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
