INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f7184bd-428c-42df-b14e-50b82fcf154f', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you implement Idempotency in a distributed API system, and why is it critical?', N'Senior', N'Idempotency ensures that repeating a request multiple times results in the same state as the first request. It is critical for handling network retries where a client is unsure if a previous request succeeded, typically implemented using a unique Idempotency-Key header tracked in a fast-access store like Redis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4cdc937-6330-4db1-addb-50b94ec684b2', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Describe the purpose of the ''Micronaut Data'' project.', N'Middle', N'Micronaut Data automates repository implementation by generating database queries at compile-time rather than runtime. This improves performance by avoiding reflection and allows for the detection of query errors during the build process instead of at execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd091c30a-f7c2-44c0-a392-50bade17055e', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the difference between ''at-least-once'' and ''exactly-once'' delivery semantics in message brokers?', N'Senior', N'At-least-once delivery ensures a message is processed by re-sending it if an acknowledgement is not received, which can lead to duplicates. Exactly-once delivery requires idempotent processing or complex distributed coordination to ensure that even if a message is delivered multiple times, the side effects occur only once.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a39c5b0-ee4c-48e1-ba53-50bce46ee636', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What criteria do you use to determine the boundaries for a microservice?', N'Senior', N'I use Domain-Driven Design principles, specifically Bounded Contexts, to ensure each service owns a distinct business capability. I verify that the service has high cohesion and low coupling, meaning it can be deployed and scaled independently without requiring frequent coordination with other teams.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d0811a0-532a-431e-9f80-50c154821860', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is JSON and its common operations', N'Intern', N'JSON (JavaScript Object Notation) is a lightweight, text-based data format that uses JavaScript object syntax for structuring data. It was popularized by Douglas Crockford and is widely used for transmitting data between a server and a client in web applications. JSON files typically have a .json extension and use the MIME type application/json. Common Operations with JSON 1. Parsing: Transforming a JSON-formatted string into a native JavaScript object. - Example: 2. Stringification: Converting a JavaScript object into a JSON-formatted string, commonly used for data transmission or storage. - Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24e87396-1748-404b-9e6a-50c1cdb70261', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Compare the performance implications of Redux selectors vs. raw state access in components.', N'Senior', N'Selectors, especially memoized ones, prevent unnecessary re-computations by caching results based on input state arguments. Accessing raw state directly forces components to re-evaluate logic on every store update, whereas memoized selectors ensure that downstream components only re-render if the specific slice of data they depend on has changed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf53ae14-8226-4193-9689-50c64edceb24', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When working on a project, how do you keep track of your progress and ensure you are meeting requirements?', N'Intern', N'I keep track of progress by maintaining a task list or project roadmap that aligns with the initial requirements. I regularly compare my current work against the project goals and ask for feedback during check-ins to ensure I am still on the right track.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abc78cb3-e22c-4260-9cc8-50c7b1f3de6a', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind manage dark mode and theme switching compared to CSS variables?', N'Senior', N'Tailwind leverages CSS variables within its configuration, which allows for seamless integration with theme-switching logic. By toggling classes on the root element, Tailwind updates the underlying CSS variables, providing a performant way to change global styles without re-rendering the entire DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb8dd04c-924c-48ed-86ad-50c897559c82', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of ''part'' and ''exportparts'' in the context of custom elements?', N'Senior', N'These attributes allow developers to expose specific internal elements of a Shadow DOM to external CSS styling while maintaining encapsulation. This provides a controlled API for theming without breaking the boundaries of the component''s shadow tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9127023-ce17-4ba5-a7b0-50ce7758dea6', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How will you remove last object from a list?', N'Fresher', N'list.pop(obj=list[-1]) − Removes and returns last object or obj from list.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebfb64f6-0afc-417d-8fa3-50d12e4f8b97', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of the ''context'' property in the Webpack config?', N'Intern', N'The context is the base directory for resolving entry points and loaders from the configuration. By default, it is the current working directory, but it can be set to a specific path to make the configuration more portable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'437c6758-baf6-45d6-8092-50d665e77252', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are ''plugins'' in Tailwind CSS?', N'Intern', N'Plugins are external modules that extend Tailwind''s functionality. They can be used to add new utilities, components, or custom variants that are not included in the framework by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1135fc29-2039-49b6-b8b3-50da514b4961', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are the common ways to embed PHP into HTML?', N'Intern', N'While there are several ways to embed PHP within HTML, the ) - Advantages: More concise and readable. - Drawbacks: Not always enabled; deprecated after PHP v7.0. ASP-Style Tags ( , , ) - Advantages: Familiar to ASP developers. - Drawbacks: Not default behavior; must be enabled. Script Tags ( ... ) - Advantages: Can be useful in very specific cases. - Drawbacks: phpBB and Bugs. Apache Server Embedding ( ) - Advantages: No need for PHP module. - Drawbacks: Integration concerns. Basic PHP Tag ( ) These tags are always a safe choice and offer the highest compatibility across platforms. Syntax It''s worth noting that', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02eea668-cca3-4f9a-9c10-50dd48d66cf0', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What does ''Framework Agnostic'' mean for Qwik?', N'Intern', N'While Qwik is a framework itself, it is designed to be compatible with various backend infrastructures and deployment strategies. It does not force developers into a single specific hosting provider or server architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d494645-5a09-45d8-a658-50dde8399551', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are generators in Python?', N'Intern', N'The way of implementing iterators are known as generators. It is a normal function except that it yields expression in the function. Python generator produces a sequence of values to iterate on. This way, it is kind of an iterable. We define a function that ''yields'' values one by one, and then use a for loop to iterate on it. 1 4 9 16 25 36 49', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c91c530-9e7b-475d-978f-50ddfdd7dbdc', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are the benefits and drawbacks of using Flask''s ''json'' module versus third-party alternatives for high-throughput APIs?', N'Senior', N'Flask''s built-in JSON support is convenient but can be slow for massive payloads. For high-throughput APIs, using faster libraries like ''orjson'' or ''ujson'' can significantly reduce CPU overhead and serialization time, though this requires careful handling of custom object encoders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8dc8e9b9-716a-4b48-a139-50de4e9a40e2', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What mechanism does Phoenix use to ensure low-latency performance in a distributed environment during deployment?', N'Senior', N'Phoenix leverages the Erlang VM''s ability to perform hot code swapping and distributed node discovery. By using tools like libcluster, nodes can automatically join the cluster, and the PubSub system can route messages across nodes, allowing the application to scale horizontally without significant downtime during deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdaf7656-a64d-43db-9b07-50df1ac1f98f', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Can you explain the function of the & character in Sass?', N'Fresher', N'The & character is a parent selector used within nested rules to refer to the parent selector of the current block. It is commonly used for pseudo-classes like hover or for creating BEM-style class modifiers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9687ee72-1ae1-4370-8498-50df517808e9', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the role of an inverted index?', N'Junior', N'An inverted index is a data structure that maps terms to the documents that contain them. Instead of searching every document for a word, Elasticsearch looks up the term in this index to instantly identify all relevant documents, enabling rapid full-text search.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc2869af-3f8a-4777-9569-50e24c67c9d7', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'When should you implement custom Eloquent ''Scopes'' versus ''Query Builders''?', N'Senior', N'Scopes are ideal for reusable, domain-specific query constraints that are meant to be chained on Eloquent models. Custom query builders should be used when you need to replace core framework logic or perform highly specialized database operations that exceed standard model functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bbfd486-44ae-4480-bef6-50e65209c89e', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are the trade-offs of using Scala''s ''Future'' for concurrency?', N'Middle', N'Futures provide a high-level abstraction for asynchronous computations, making it easier to compose and chain operations without blocking threads. However, they are eager and can be difficult to manage regarding resource exhaustion and backpressure compared to more robust reactive streaming libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3f431f3-a14a-4642-bcf7-50e6bfcc6a60', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is memoization in JavaScript?', N'Intern', N'Memoization is a programming technique which attempts to increase a function''s performance by caching its previously computed results. Each time a memoized function is called, its parameters are used to index the cache. If the data is present, then it can be returned, without executing the entire function. Otherwise the function is executed and then the result is added to the cache. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fb5e2de-a7a0-4a08-9492-50e91ff94c78', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle HTTP/2 and what architectural advantages does it provide?', N'Senior', N'Fastify supports HTTP/2 out-of-the-box, allowing for multiplexing and header compression that significantly improve performance on high-latency networks. By managing streams efficiently, Fastify enables better resource utilization when serving multiple assets to a single client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d697355-165d-4b75-8e67-50eaf3431980', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the difference between dirty reads and lost updates.', N'Middle', N'A dirty read occurs when a transaction reads uncommitted data from another transaction that might later roll back. A lost update occurs when two transactions read the same data, both modify it, and the final write of one transaction overwrites the other, causing the first update to be lost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b69552b-7ef8-462c-90a0-50ec4a4b2b5d', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle serialization of responses?', N'Fresher', N'Fastify uses a fast serialization process by compiling JSON schemas into optimized functions. By knowing the structure of the data beforehand via a schema, it avoids expensive reflection-based serialization, resulting in faster response times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00980339-aef1-477d-abf4-50ede1b9063e', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How do distributed databases handle clock skew issues?', N'Middle', N'Clock skew, where different nodes have slightly different timestamps, is handled using techniques like vector clocks or logical clocks to establish a causal order of events. This ensures that the system can correctly identify the sequence of updates in a distributed environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbba4fb3-9ab6-46d0-bdd6-50f3e74a9414', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are Sass partials and how do you define them?', N'Junior', N'Partials are Sass files that contain snippets of CSS meant to be imported into other files. They are defined by starting the filename with an underscore, which tells the Sass compiler not to generate a separate CSS file for them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'285e5c4f-7704-44dd-9362-50f5eca8816a', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI implement CORS (Cross-Origin Resource Sharing)?', N'Junior', N'FastAPI provides a CORSMiddleware class that can be added to the application to control which origins are allowed to access your API. This is necessary for browser-based applications to securely communicate with a backend hosted on a different domain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
