INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c5b2065-bedb-461c-a82b-50fd261decb3', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the significance of the ''Finalizer'' and the ''IDisposable'' pattern.', N'Senior', N'Finalizers are non-deterministic cleanup mechanisms invoked by the GC, leading to delayed resource release. The IDisposable pattern provides a deterministic way to release unmanaged resources immediately via the ''using'' block. Relying on finalizers is discouraged because it unnecessarily extends the lifetime of objects and increases GC pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'549c831d-7da6-4de7-919f-50fe304df419', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What does the ''flushall'' command do in Redis?', N'Junior', N'The flushall command deletes all keys from all existing databases in the Redis instance. It is a very destructive operation and is typically used only for clearing data during testing or system resets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
