INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6d0f194-4694-443a-ba74-5100e8135927', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do you handle authentication in an Ember application?', N'Middle', N'Authentication is typically managed via an Ember Service that stores the user session and token. This service can be injected into any route or component to guard access to specific parts of the app or to dynamically update the UI based on the user''s login status.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38f301c5-dd1e-413b-832e-510259880433', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is a dictionary?', N'Intern', N'A dictionary is a collection of key-value pairs where each key is unique. It allows you to store and retrieve values based on an associated identifier rather than by an index.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65fae77b-0f10-4a90-8928-5102695ef8ab', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte ensure high performance?', N'Fresher', N'Svelte achieves high performance by compiling components into efficient code that knows exactly which parts of the DOM need to change when state updates. This fine-grained reactivity avoids the performance cost of re-rendering entire component trees or diffing virtual structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4aa49366-e41a-4589-affb-51042e91c8da', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How can you implement CORS in an Express application?', N'Junior', N'CORS, or Cross-Origin Resource Sharing, is typically implemented by using the ''cors'' middleware package. It allows you to configure which domains are permitted to access your API by setting the appropriate HTTP headers on responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'322554bc-3d19-4bed-8f91-510517934272', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the difference between app.use() and specific route methods like app.get()?', N'Intern', N'The app.use() method is used to mount middleware functions that execute for every request or for requests matching a specific path prefix. Conversely, methods like app.get() or app.post() are restricted to specific HTTP verbs and are used to define precise routes for handling specific types of client requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bd15988-cc0d-461c-aa1b-510750b76cd1', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot handle ''Dependency Injection''?', N'Fresher', N'Spring Boot utilizes the Spring Framework''s Inversion of Control container to manage the creation and lifecycle of objects. It automatically injects required dependencies into classes, usually through constructor or field injection, which promotes loose coupling and makes the code easier to test.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61cc4264-4838-4dc2-a605-510b290ffab5', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix ensure high availability during deployment using ''Hot Upgrades''?', N'Senior', N'Phoenix applications can leverage OTP releases to perform hot code upgrades, where the application state is migrated to a new version without dropping existing connections. This allows for zero-downtime deployments, though it requires careful management of process state and module versioning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b857a1e6-5125-4b0c-8429-510c2b628de6', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the difference between ''universal'' and ''spa'' rendering modes?', N'Fresher', N'Universal mode uses server-side rendering to provide initial content, while SPA mode renders the entire application on the client side. Universal is better for SEO, while SPA mode is simpler to deploy if SEO is not a requirement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18f3dbc4-27ad-4250-b448-510cf37dbfb4', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are dark mode variants in Tailwind?', N'Junior', N'Dark mode variants are special prefixes, typically dark:, that allow you to define styles specifically for when a user''s system preference is set to dark mode. Tailwind toggles these styles automatically based on the user''s OS settings or a specific class applied to the root element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee28bdf0-c23b-4e9a-ac62-510cf7f815a5', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of the app.use() function?', N'Intern', N'In Express.js, the app.use() function is a powerful tool for middleware management. It can handle HTTP requests and responses, as well as prepare data or execute processes in between. Key Functions - Global Middleware: Without a specified path, the middleware will process every request. - Route-specific Middleware: When given a path, the middleware will only apply to the matched routes. Common Use-Cases - Body Parsing: To extract data from incoming requests, especially useful for POST and PUT requests. - Handling CORS: Useful in API applications to manage cross-origin requests. - Static File Serving: For serving files like images, CSS, or client-side JavaScript. - Logging: To record request details for debugging or analytics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c0c59c9-fca6-4702-bc64-510d1621568d', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Why is it important to consider ''data locality'' in a sharded architecture?', N'Senior', N'Data locality involves keeping related pieces of information on the same physical shard to minimize network round-trips during queries. Poor locality forces the system to perform distributed joins or scatter-gather operations, which drastically increase query latency and network congestion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8e67e07-d66a-4ac7-b42e-510e040aae36', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the drawbacks of excessive indexing in a write-heavy database?', N'Senior', N'Every index adds overhead to data modification operations because the engine must update the index tree for every insert, update, or delete. Too many indexes lead to increased storage usage, longer transaction execution times, and higher lock contention on index pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
