INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f628a0be-22a3-4faf-b193-511298ffd5f8', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Discuss the scalability challenges of Flask’s global configuration object.', N'Senior', N'The global config object can become a bottleneck or a source of configuration drift if it becomes overly complex or is modified at runtime. For scalable architectures, it is better to use environment-specific configuration files or external secret management systems to ensure immutable and consistent application state across different deployment environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
