INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'177d6c9b-b360-476a-a1c2-5118e4a37ae6', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the ''N+1 query problem'' and how can database design mitigate it?', N'Senior', N'The N+1 problem occurs when an application executes one query to fetch parent records and then N additional queries to fetch related child records. This is mitigated at the design level by employing proper relationship modeling, denormalization, or using batch fetching mechanisms to reduce round-trip latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8c1c354-4a5d-4607-9427-511a5c67ce6d', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are the memory trade-offs when using many small Lit components versus a single monolithic component?', N'Senior', N'Using many small components increases the number of custom elements and Shadow DOM roots, which consumes more memory and can increase the time required for browser layout calculation. However, smaller components improve encapsulation, testability, and the ability to re-render only specific sub-sections of the UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20e939ee-d731-4ff0-abca-511dcd6fb568', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is an entity-relationship (ER) diagram?', N'Junior', N'An ER diagram is a visual representation of the entities within a system and the relationships between them. It is used in the database design phase to model the logical structure of the database before implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b9e488c-d25f-40ce-82dd-51222ac701b1', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are the architectural benefits of using Span<T> in memory-constrained .NET applications?', N'Senior', N'Span provides a type-safe, memory-contiguous view over arbitrary memory, including stack memory, heap-allocated arrays, or unmanaged buffers. It enables slicing and high-performance parsing without requiring additional heap allocations or copying data, significantly reducing the frequency of garbage collection cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'902cc7c5-3e01-4be0-849c-5123b8761228', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a Column-family store?', N'Fresher', N'A column-family database stores data in columns rather than rows, allowing for efficient access to specific data fields. This model is highly effective for analytical queries on large datasets by grouping related columns together.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4819c81b-a51d-4444-b63f-512645b4df1e', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you handle constructive criticism during a project review?', N'Intern', N'I view constructive criticism as an opportunity to learn and improve the quality of my work. I listen to the feedback without becoming defensive and ask clarifying questions to ensure I understand the suggested improvements. My goal is to apply the feedback effectively to achieve the best result for the team.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'597fd1f0-80c1-4aa0-906e-51272341884a', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What does it mean for Echo to be ''extensible''?', N'Intern', N'Extensibility means that the framework is designed to allow developers to easily add custom functionality or integrate third-party libraries. You can create your own middleware or custom renderers to fit specific project requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ea3060c-54e3-4c07-9d7f-5127bd95738e', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Describe the utility of ''web::Data'' versus ''App::app_data'' in service configuration.', N'Senior', N'App::app_data is used to share state across the entire application, while web::Data is used for injecting dependencies into specific handlers. This distinction allows for fine-grained control over which services have access to specific shared resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e81b2fd-75f5-49fc-82fd-5129425a4270', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Ecto''s ''Repo.preload'' affect query performance and the N+1 problem?', N'Senior', N'Preloading allows fetching associated data in efficient, batched queries rather than individual queries per record, which is the standard solution to the N+1 problem. While powerful, developers must be careful not to over-fetch data, as loading complex association trees into memory can lead to performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'835682b4-cf1f-4673-b136-5129896f5c06', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the concept of ''Type Profiling'' in JavaScript engines.', N'Senior', N'Type profiling involves recording the types of variables at specific execution points to inform speculative optimization. This historical data allows the JIT compiler to generate specialized machine code paths for the most common data types encountered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1976bbcc-ed91-4e82-b64d-5129a6dbd359', N'954a0331-deff-4399-b588-96f39fec001d', N'Discuss the architectural impact of ''Global CSS'' vs ''Component-scoped CSS''.', N'Senior', N'Global CSS is easy to manage for high-level design systems but risks unintended styling leaks across the application. Scoped CSS ensures component isolation and predictability but can lead to duplication of styles and increased bundle sizes if not managed via shared stylesheets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcdeb93a-5f19-4f4c-a3e7-5129a882738b', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the ::placeholder pseudo-element?', N'Intern', N'::placeholder styles the placeholder text of an or element — the hint text shown when the field has no value. Example: > Note: Only a subset of CSS properties reliably apply to ::placeholder (color, font, opacity). Avoid using it to replace a proper element for accessibility reasons.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d96b68c-0dca-488d-b104-5129fdfb94e5', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux help with application testing?', N'Middle', N'Because reducers are pure functions, they are extremely easy to unit test by passing in a state and an action and asserting the expected output. This allows for comprehensive logic testing without needing to mock complex UI components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01c268e5-88b2-42dc-bfdd-512d8ae0ba59', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the purpose of main element?', N'Intern', N'The HTML element represents the dominant content of the of a document. The main content area consists of content that is directly related to or expands upon the central topic of a document, or the central functionality of an application. *Note: A document mustn''t have more than one element that doesn''t have the hidden attribute specified.*', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81045069-aa52-4daf-ab8b-5130b943988d', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a database user account?', N'Intern', N'A database user account is a security identity that defines who can connect to the database and what actions they are permitted to perform. It allows administrators to manage access levels and protect sensitive information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a64f43f-2f90-405c-bab3-5132f0633e23', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s architecture support horizontal scaling behind a load balancer?', N'Senior', N'Since Echo is stateless by design, it scales horizontally by simply deploying more instances behind a load balancer. The only state management required is in external layers like databases or caches, ensuring that any Echo instance can handle any request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b341e6ec-4cf0-4ca0-9ab1-51366b668342', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the role of the ''Global Object'' in the context of different JavaScript environments like Node.js and browsers.', N'Senior', N'The global object provides an execution context for code, but its implementation varies: it is ''window'' in browsers and ''global'' in Node.js. Modern standards introduced ''globalThis'' to provide a unified, environment-agnostic way to access the global scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc3747ff-cf4d-4309-9497-513bda643d79', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does Python manage memory for objects?', N'Junior', N'Python uses a private heap to manage memory and employs a built-in garbage collector to handle object lifecycles. The primary mechanism for reclaiming memory is reference counting, which automatically deletes objects when their reference count drops to zero.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a01c2b49-0d6b-4dd9-a6bd-513fc9a720a3', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How do you check if an element exists using jQuery?', N'Junior', N'You can check the length property of the jQuery object returned by your selector. If the length is greater than zero, the element exists in the DOM; if it is zero, no match was found.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17441c74-43fa-4f3b-98f1-513ff3820695', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the function of the Spring Boot Starter POMs?', N'Fresher', N'Starter POMs are pre-configured sets of dependency descriptors that simplify build configuration. By including a single starter, you automatically get all the required libraries to support a specific technology, such as web development or database access, without manual version management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbd4a222-8647-48e4-af79-51418ded97c7', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Is Preact suitable for large-scale applications?', N'Intern', N'Yes, Preact is used in many large-scale applications because of its stability and performance. Its minimal size ensures that even complex applications remain performant and fast to load for the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6570f140-34a3-4f61-bb3c-51419a32d15f', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the primary architectural benefit of Fastify''s encapsulation model?', N'Middle', N'Encapsulation allows developers to create isolated plugin contexts with their own configurations, decorators, and hooks. This prevents side effects between different parts of a large application and ensures that settings in one plugin do not leak into another.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b77b68e-bae0-4a85-962c-5142fad2b675', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What are Remix ''Meta'' tags?', N'Fresher', N'Meta tags are used to define information about your page, such as the title and description, for search engines and social media. In Remix, you can export a meta function from your route to set these dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4b81728-ed21-4099-902c-5143bb441a34', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery handle event delegation, and why is it beneficial for performance?', N'Middle', N'jQuery''s on method allows developers to attach a single event listener to a parent element that triggers for current and future children. This is memory-efficient because it avoids attaching individual listeners to every single child element, especially in dynamic lists where items are added or removed frequently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25cb3f1b-9ca4-4cd0-865e-5149a491001c', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus implement fault tolerance?', N'Junior', N'Quarkus uses the SmallRye Fault Tolerance extension, which implements the MicroProfile Fault Tolerance specification. It allows developers to easily add features like retries, circuit breakers, timeouts, and bulkheads to methods using simple annotations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f3084e0-9b16-46c8-9eb5-5149f19fe9c6', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the advantages and disadvantages of using a background job processor like Sidekiq?', N'Middle', N'Background processing offloads time-consuming tasks from the request-response cycle, improving user-perceived performance. The trade-off is increased architectural complexity, the need to manage a secondary process like Redis, and the requirement to handle job failures and state consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51185492-0eb1-4fd0-81ff-514b4c72f6bb', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why is NoSQL considered more agile for developers?', N'Intern', N'NoSQL allows developers to modify data models without downtime because they are not constrained by fixed database schemas. This flexibility supports continuous integration and rapid prototyping workflows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1e332ce-4058-4771-8a99-5152713cb022', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do you implement versioning in a Gin-based API?', N'Senior', N'Versioning is best handled via route groups, allowing you to mount different handler sets under distinct base paths. This architectural approach keeps the codebase clean by separating logic for different API versions while sharing common middleware across the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee0fc356-f104-4c60-8638-51530030dc77', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the benefit of using a message queue for load leveling?', N'Middle', N'A message queue acts as a buffer between producers and consumers, allowing the system to handle traffic surges by queuing requests. This prevents downstream services from being overwhelmed and ensures that tasks are processed at a manageable, steady rate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
