INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'043c3a4f-4258-4a36-aa6d-515cbd6ba5b1', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How can you implement Caching in NestJS?', N'Fresher', N'Caching is a great and simple technique that helps improve your app''s performance. It acts as a temporary data store providing high performance data access. NestJS supports caching through various mechanisms, including the use of caching libraries like cache-manager and built-in decorators such as @CacheKey and @CacheTTL. By incorporating caching strategies in your application, you can enhance performance and reduce response times for frequently requested data. In order to enable caching, import the CacheModule and call its register() method To interact with the cache manager instance, inject it to your class using the CACHE_MANAGER token, as follows: > The get method is used to retrieve items from the cache. If the item does not exist in the cache, null will be returned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22c2bbc8-3f04-4c63-9219-515d090e5c61', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does monomorphization impact compile times and binary size?', N'Senior', N'Monomorphization generates a unique copy of generic functions for every concrete type used, which enables extensive optimization and inlining. The trade-off is longer compilation times and increased binary size due to the duplication of code for each variant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'424116b4-16e5-4760-9f3a-515e1da36329', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the advantage of using the Django User model?', N'Junior', N'Django comes with a robust, built-in authentication system that manages users, passwords, and permissions. Using this pre-built model saves significant time and follows security best practices for hashing passwords and managing user sessions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'930cbcee-c16e-484a-b7ed-516350e77eb2', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Why is it generally discouraged to use ''Finalizers'' in C# if ''IDisposable'' is available?', N'Middle', N'Finalizers are non-deterministic and rely on the garbage collector to run, which can lead to resource exhaustion if you wait for the GC to clean up unmanaged objects. IDisposable provides a deterministic way to release resources immediately via the Dispose method, and implementing it allows the developer to suppress the finalizer, improving overall application performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76381c86-357e-4f99-938b-5164021aa08e', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the ''debug'' tag in Svelte?', N'Junior', N'The ''{@debug}'' tag allows you to inspect variables within your templates during development. When the variables listed in the tag change, it triggers a breakpoint in the browser''s debugger, letting you see the current state values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7f29bba-23d3-4db1-83d2-516601e4a021', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are the limitations of ''isolates'' regarding CPU-bound vs. I/O-bound tasks?', N'Senior', N'Isolates are highly effective for CPU-bound tasks, as they allow offloading heavy computation to separate threads without blocking the main UI loop. However, for simple I/O-bound tasks, the overhead of spawning an isolate and serializing data may outweigh the benefits compared to using asynchronous non-blocking I/O primitives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ee436ff-8c8c-4fea-a824-5173017f49b8', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why is ''constexpr'' more than just a compile-time constant?', N'Senior', N'Constexpr allows functions and constructors to be evaluated at compile-time if their inputs are known, shifting computational work from runtime to the build phase. This enables complex data structures and algorithms to be computed during compilation, improving runtime performance and allowing for exhaustive compile-time validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fe0f9eb-1a1f-4b54-83b6-5173a1a879d8', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain the use of next in Node.js?', N'Fresher', N'The next is a function in the Express router which executes the middleware succeeding the current middleware. Example: To load the middleware function, call app.use(), specifying the middleware function. For example, the following code loads the myLogger middleware function before the route to the root path (/). &#9885; Try this example on CodeSandbox *Note: The next() function is not a part of the Node.js or Express API, but is the third argument that is passed to the middleware function. The next() function could be named anything, but by convention it is always named “next”. To avoid confusion, always use this convention.*', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be74166b-8ad3-4c1e-920b-5178f50c7b49', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R''s garbage collector interact with C++ code via Rcpp?', N'Middle', N'Rcpp provides a bridge between R and C++ memory management by wrapping C++ objects in R-compatible structures. When the garbage collector removes the R wrapper, the underlying C++ destructor is called, ensuring that memory allocated in C++ is correctly cleaned up.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab9b31db-7919-4244-bc7d-517b0c38fedc', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the difference between R''s copy-on-modify semantics and traditional pass-by-value.', N'Senior', N'While R behaves as if it is pass-by-value, it utilizes copy-on-modify semantics to optimize memory. Objects are not actually copied until a modification is attempted, allowing efficient memory management for large datasets unless a specific object is altered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
