INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da6eafbb-8d70-45db-a26c-518112887860', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the primary difference between ''Fiber.Ctx.Locals'' and global state?', N'Middle', N'Fiber.Ctx.Locals provides a request-scoped key-value store, making it safe for passing data between middleware and handlers within the same request lifecycle. Global state, conversely, is shared across all concurrent requests and requires synchronization primitives like mutexes to prevent race conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b167e78-d8b3-4507-bd4a-5185a4b91e95', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Explain the role of ''adapters'' in SvelteKit and how they influence the deployment architecture of an application.', N'Middle', N'Adapters are responsible for transforming the build output of a SvelteKit project into a format compatible with specific deployment environments like Node.js, Vercel, or static hosting. They abstract away the platform-specific server implementation, allowing developers to switch deployment targets or switch between server-side and static site generation without rewriting the core application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
