INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b031e2e0-f39e-4e8e-9e0a-5194dc82333c', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the role of the nuxt.config.js or nuxt.config.ts file?', N'Fresher', N'This file serves as the central configuration hub for your Nuxt application. You use it to define global settings, such as meta tags, plugin registrations, build modules, and environment variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9963ed79-3f21-4dbe-a44b-519698b899bd', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between a class and a protocol?', N'Junior', N'A class is a blueprint for objects that includes data and behaviors, whereas a protocol only defines a requirement for methods or properties. A class can inherit from one superclass, but it can conform to multiple protocols simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5c33a08-24f3-4f65-88f9-5196cb101ed7', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a sudden increase in P99 latency in a microservices architecture?', N'Senior', N'I start by analyzing the request path using service mesh telemetry to isolate which specific dependency or hop is introducing delay. I then investigate resource saturation metrics like CPU throttling, lock contention, or connection pool exhaustion to determine if the latency is caused by internal processing or external blocking calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35890f70-41a3-4718-8e8e-5196ce087131', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the role of the C++ reference variable compared to a pointer?', N'Junior', N'A reference is an alias for an existing variable and must be initialized when created, whereas a pointer holds a memory address and can be reassigned to point elsewhere. References are generally safer because they cannot be null and require less syntax to access the underlying value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51e8b4f5-25a9-4656-b30f-519f02143c06', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How do Ruby blocks, procs, and lambdas differ in their handling of arguments and return statements?', N'Middle', N'Lambdas are strict about argument counts and return control to the calling method, behaving like local functions. Procs are lenient with argument counts and return control immediately from the enclosing scope, while blocks are anonymous chunks of code that are passed to methods and cannot be stored as standalone objects without conversion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59e23830-f81e-4bfc-b878-51a01432f3c1', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the primary advantage of Micronaut over Spring Boot?', N'Intern', N'The main advantage is faster startup time and lower memory footprint because Micronaut does not rely on runtime reflection. This makes it particularly well-suited for serverless environments like AWS Lambda where cold starts are a concern.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34edb4c1-c614-4f35-8eb0-51a0d2ceda51', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the ''static'' modifier?', N'Junior', N'The ''static'' modifier indicates that a member or class belongs to the type itself rather than a specific instance. Static members are shared across all instances of the class and can be accessed without creating an object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
