INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'273f7158-f115-4ba0-b819-51c90cbf7312', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What architectural challenge does reflection pose for native compilation, and how does Quarkus solve it?', N'Senior', N'Native compilation uses static analysis to determine reachable code, which is incompatible with runtime reflection. Quarkus solves this by allowing developers and extension authors to register classes and methods for reflection at build time, ensuring the native compiler knows they must be included in the final binary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4561f48-8226-4545-9f8d-51c9c9c523d2', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is rendering in JavaScript?', N'Intern', N'JavaScript-powered content needs to be rendered before it can output meaningful code and be displayed for the client. These are the different steps involved in the JavaScript rendering process: 1. JavaScript: Typically JavaScript is used to handle work that will result in visual changes. 2. Style calculations: This is the process of figuring out which CSS rules apply to which elements. They are applied and the final styles for each element are calculated. 3. Layout: Once the browser knows which rules apply to an element it can begin to calculate how much space it takes up and where it is on screen. 4. Paint: Painting is the process of filling in pixels. It involves drawing out text, colors, images, borders, and shadows, essentially every visual part of the elements. 5.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51b57673-cf32-40a8-856a-51ca592d5b1a', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle concurrent request processing?', N'Middle', N'Rocket is built on top of asynchronous runtimes, allowing it to handle multiple concurrent requests efficiently using non-blocking I/O. It leverages the Rust task-based concurrency model, where each request is processed in an async block, enabling high throughput without needing one thread per connection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a08d180e-4b0a-4d83-a564-51cdac1817ac', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is ''standard'' web API compliance in Hono?', N'Intern', N'Hono is built using standard Web API interfaces like Request and Response objects. This makes it highly compatible with modern browsers and various serverless JavaScript environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9bdf6fa-6cd9-49ce-a33d-51cef07edb94', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the difference between a Hook and a Plugin in Fastify?', N'Fresher', N'A plugin is used to extend the application''s functionality or add routes, while a hook is used to intercept the request lifecycle to perform actions like validation or logging. Plugins are generally used for structure, while hooks are used for behavior during request processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed553027-c620-4b97-b167-51d2146bc0f9', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the purpose of the Litestar application object?', N'Fresher', N'The application object is the central registry for your web service. It holds the configuration, route definitions, middleware, and dependency providers required to run the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2514aa58-b6b1-4fe3-b5d4-51d550787eba', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What are the primary performance concerns when using REST over HTTP for inter-service communication?', N'Middle', N'REST over HTTP carries the overhead of text-based formats like JSON and the verbosity of HTTP headers. Additionally, it is inherently blocking, which can lead to high latency and thread exhaustion if not managed with non-blocking I/O or connection pooling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'012af2b1-287f-45f8-8e60-51d565c44a0e', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why is it important not to mutate state directly in Redux?', N'Intern', N'Mutating the state directly prevents Redux from detecting changes efficiently, which can break features like time-travel debugging and optimized component re-rendering. Redux relies on identifying new state object references to determine if a UI update is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e933ed3-7790-40ea-9c08-51d9826c7914', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are the trade-offs of using ''lazy loading'' via dynamic imports?', N'Senior', N'Lazy loading improves the initial page load time by splitting the application into smaller chunks that are loaded on demand. However, it introduces the need for managing loading states, potential latency when a user triggers a route that requires a new chunk, and added complexity in handling network errors during chunk fetching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
