INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'072511ba-5100-481b-ba65-51edc27e1220', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Explain the significance of ''Read-Your-Writes'' consistency.', N'Senior', N'Read-your-writes consistency guarantees that a user will see their own updates immediately, preventing user confusion in applications like banking or messaging. Achieving this in a distributed system often requires routing the user''s read requests to the same node where their latest write was processed or utilizing versioning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
