INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7285f00e-58ef-4ae1-9d64-51f85a3725b3', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the primary trade-offs when choosing between a G1 Garbage Collector and ZGC for low-latency applications?', N'Senior', N'G1 GC balances throughput and pause time by partitioning the heap into regions, but it can suffer from stop-the-world events during large compaction cycles. ZGC uses colored pointers and load barriers to perform most work concurrently, significantly reducing pause times to sub-millisecond levels at the cost of higher CPU overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30b0e441-4279-4cf7-9282-51fa51e94392', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does monomorphization impact compilation time in large Rust projects?', N'Senior', N'Monomorphization generates a unique copy of generic functions for every concrete type instantiation, which increases the amount of code the backend must optimize. This leads to longer compile times as the project grows, though it enables significant performance gains through type-specific optimizations like inlining.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1179e71-d914-46e3-b2a8-51fb4d99561e', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS differ from frameworks that use ''useState''?', N'Fresher', N'While frameworks like React use ''useState'' to trigger a full component re-render, SolidJS signals use fine-grained reactivity. This means only the specific DOM nodes subscribed to the signal update, rather than re-executing the component function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
