INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab24d561-8448-4d10-8cc0-51fe01b0c6c5', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the benefit of Actix-web''s use of the Tokio runtime?', N'Fresher', N'Tokio is an asynchronous runtime for Rust that provides the underlying infrastructure for non-blocking I/O. By using Tokio, Actix-web can efficiently manage thousands of concurrent connections with minimal resource overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bc19cd6-1d40-42f0-a438-51ffbbeee8ba', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express interact with the underlying Node.js ''http'' module, and what does this mean for performance tuning?', N'Senior', N'Express acts as a wrapper that simplifies the API of the native Node.js ''http'' module. Performance tuning often requires looking past the Express layer to optimize the underlying server''s connection handling, socket timeouts, and buffer management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1be7226-95df-42f6-a4ac-5202f8bab1cc', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you change the style of a HTML element', N'Fresher', N'You can change inline style or classname of a HTML element using javascript DOM-manipulation 1. Using style property: You can modify inline style using style property 2. Using ClassName property: It is easy to modify element class using className property', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82359bed-ae3f-4bc3-9495-520481bca1ab', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What should you do if you realize your current debugging hypothesis is incorrect?', N'Intern', N'You should discard the incorrect hypothesis, document why it was wrong, and formulate a new one based on the information gathered during the failed attempt. Debugging is an iterative process where failed hypotheses provide valuable data that helps refine future theories.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37195459-3329-4af1-b487-5205a66d7c1d', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the ''inline'' keyword used for?', N'Fresher', N'The ''inline'' keyword tells the compiler to copy the function body directly to the call site instead of performing a standard function call. This can improve performance when using higher-order functions by reducing the overhead of creating function objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc0b187c-4ac8-4589-9e6e-5205f88af78b', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why is it recommended to use ''fast-json-stringify'' with Fastify instead of native JSON serialization?', N'Senior', N'Native serialization requires the engine to infer types at runtime, which is computationally expensive for large objects. Fast-json-stringify uses the provided schema to create a static path for string conversion, avoiding reflection and significantly improving response throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75c9bbd5-fd85-44dc-8a05-5206caad065d', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the ''combineReducers'' utility function?', N'Junior', N'combineReducers is a helper function that allows you to split your state management into smaller, independent reducers based on specific domain logic. It then combines these smaller reducers into a single root reducer that the store can use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91da2873-d1ff-4305-925a-520746f676cd', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What does ''Dependency Management'' mean in Spring Boot?', N'Fresher', N'Dependency management refers to the framework''s ability to automatically manage the versions of all related dependencies. This ensures that the libraries being used are compatible with each other, preventing conflicts and reducing the effort required to maintain the build configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61f92746-e01f-415b-81fd-520748642491', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of Form Requests in Laravel?', N'Junior', N'Form Requests are custom request classes that contain validation logic for incoming HTTP requests. They keep your controllers clean by separating the validation rules and authorization logic from the main application flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8786a63-c6a1-4cbe-90ff-520865b01fe1', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle CORS management?', N'Middle', N'Hono provides a built-in CORS middleware that can be configured with specific origins, methods, and headers. This allows for simple and secure management of cross-origin requests directly within the server configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0afea124-84ac-470e-977e-5209c54ca77f', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Does Qwik rely on a Virtual DOM, and why or why not?', N'Senior', N'Qwik does not use a Virtual DOM in the traditional sense because it does not need to reconcile a full component tree during hydration. It updates the DOM surgically by tracking dependencies at the granular level, allowing it to bypass the overhead of comparing large object trees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff573d32-f834-48d1-8edd-520bb83e6c71', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why would you choose a document-oriented database like MongoDB over a key-value store like Redis?', N'Junior', N'A document database is better suited for complex data structures where you need to query specific fields or perform nested lookups. Key-value stores are optimized for high-speed retrieval of simple data based on a unique identifier but lack advanced querying capabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87044745-4884-401c-b1a9-520c09c44178', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is TypeScript considered a superset of JavaScript?', N'Fresher', N'It is called a superset because all valid JavaScript code is also valid TypeScript code. TypeScript extends JavaScript by adding additional features like static typing, interfaces, and namespaces that are not part of the standard JavaScript language.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e79989c7-05e6-4ebe-b985-5210128029e1', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle event delegation?', N'Middle', N'Qwik uses a global event listener at the document level. When a user interacts with an element, the global listener captures the event, looks up the associated symbol in the HTML, and lazy-loads the required code to handle that specific event.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4743b712-23a0-427b-9960-5210449394f6', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are the security implications of Flask''s default session cookie implementation?', N'Senior', N'Flask''s default session cookie is cryptographically signed but not encrypted, meaning the contents are visible to the client. Using it to store sensitive data is dangerous, and failing to rotate the SECRET_KEY regularly can allow attackers to forge session tokens if the key is compromised.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf5fa5d3-8251-4b1e-8749-5210dbad1a50', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the benefit of using Tailwind CSS over standard CSS for maintaining a large project?', N'Junior', N'Tailwind eliminates the need to constantly name and maintain custom CSS classes, which prevents issues like class name collisions. It also keeps styles co-located with your markup, making it easier to understand the visual structure of a component without switching files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1cde2c0-6696-4418-9445-52187d063454', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the different types of NoSQL databases?', N'Intern', N'NoSQL is a non-relational DBMS, that does not require a fixed schema, avoids joins, and is easy to scale. The purpose of using a NoSQL database is for distributed data stores with humongous data storage needs. NoSQL is used for Big data and real-time web apps. Types of NoSQL Databases: * Document databases * Key-value stores * Column-oriented databases * Graph databases 1. Document databases: A document database stores data in JSON, BSON , or XML documents. In a document database, documents can be nested. Particular elements can be indexed for faster querying. Documents can be stored and retrieved in a form that is much closer to the data objects used in applications, which means less translation is required to use the data in an application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'981faf8b-36bc-47d7-a809-521b633efab0', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why are unit tests important in software development?', N'Fresher', N'Unit tests ensure that individual components of the software function exactly as intended in isolation. They act as a safety net that allows developers to refactor or update code with the confidence that existing functionality will not break.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a3423a4-5bb2-4b1b-a227-521bfdadde74', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is a sanity check in the context of troubleshooting?', N'Intern', N'A sanity check is a quick, basic test to ensure that the fundamental components of a system are working as expected. It helps rule out obvious failures, like a disconnected cable or a service that failed to start, before diving into complex logic analysis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de4a8819-e1ef-4162-9fce-521e6d6ec794', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is a Factory in Laravel?', N'Intern', N'Factories are used to define a blueprint for your database models. They allow you to easily create multiple test records with random data, which is essential for seeding and unit testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc439c56-e374-4f71-8238-521f9ae83d50', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is a ''universal'' load function?', N'Fresher', N'A universal load function is defined in a +page.js or +layout.js file and is executed on the server during the initial request and on the client during subsequent navigation. It is ideal for fetching public data that does not require server-side secrets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9263566-7422-4a38-b179-5221e4fe809e', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does template instantiation impact binary size in C++?', N'Senior', N'Templates are instantiated for every unique set of template arguments, which can lead to significant code bloat if the same logic is compiled for many different types. While this allows for optimal machine code for each type, it increases the total binary size and can negatively affect instruction cache locality in large applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c15d00e0-0266-454e-97ee-52228ba96a91', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle request routing?', N'Fresher', N'Axum uses a router object to map HTTP methods and paths to specific handler functions. The router supports nested routes and can be composed of multiple smaller routers to keep the application organized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de92420a-c973-4510-bc97-5225c36c89db', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the primary benefit of using Rust for a backend framework like Rocket?', N'Fresher', N'The primary benefit is memory safety without a garbage collector. This ensures that the backend application is highly performant and free from common memory-related bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'754f964d-5d17-492c-84e0-5227f6dfe703', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono manage memory consumption differently than Node.js frameworks like NestJS or Express?', N'Senior', N'Hono is designed to be extremely lightweight, with no heavy internal dependencies, which results in a very small bundle size and minimal memory allocation per request. This is particularly advantageous for serverless functions where memory usage is directly tied to cost and startup latency, allowing for faster cold boots.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70226925-1873-49c9-b16c-5228a9c2b9ff', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the primary advantage of Tailwind''s ''group'' and ''peer'' modifiers for interactive states?', N'Middle', N'These modifiers allow you to style an element based on the state of its parent or sibling without needing custom JavaScript or complex CSS selectors. This significantly simplifies hover, focus, and active state management for complex UI components like dropdowns or cards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
