INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4603881-e5b4-4297-98ca-5228e4ecfb75', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript manage module resolution?', N'Middle', N'TypeScript follows Node.js module resolution strategies, looking for files based on ''import'' statements. It uses configuration flags like ''baseUrl'' and ''paths'' to map module imports to specific physical directories. This allows for clean, alias-based imports instead of complex relative paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a496853-c859-4a67-a7db-522a31163c55', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the advantage of using factory constructors in Dart?', N'Middle', N'Factory constructors provide control over object instantiation, allowing a class to return an existing instance, a cached instance, or a subtype of the class. This is useful for implementing the Singleton pattern or returning pre-computed values without creating a new object every time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7385711-9e2a-41de-a57f-522e910ce4ed', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the ''N+1'' query problem in the context of database design and how can it be mitigated?', N'Middle', N'The N+1 problem occurs when an application executes one query to fetch parent records and then individual queries for each parent to fetch related child records. It can be mitigated by using eager loading, join queries, or batching requests to retrieve all required data in a single round trip.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3266491d-c7f2-4663-b83c-522f0d01fa61', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of the ''assets'' folder?', N'Fresher', N'The ''assets'' folder stores front-end source files such as JavaScript, CSS, and images. Phoenix uses build tools to process and bundle these files for the client side.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7051534-d1cd-43d7-b5af-5230fa3be779', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does C handle signal safety, and why is it difficult to implement correctly?', N'Senior', N'Signal handlers interrupt the normal flow of execution, meaning they can be invoked at almost any point, including while the program is in a non-reentrant state. To remain signal-safe, a handler must only call functions that are explicitly documented as async-signal-safe and avoid modifying shared state. This constraint makes writing robust signal handlers extremely challenging, often requiring the use of lock-free primitives or atomic flags.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2b068d0-99c9-4118-8d64-5231654962d0', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is a nullable type?', N'Fresher', N'A nullable type is a type that can explicitly hold a null value, represented by adding a question mark to the type name. This forces the developer to handle the null case, effectively preventing runtime null pointer exceptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0eb74a4f-f12a-45da-8dd7-52318a7f48a9', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the role of the ''preHandler'' hook?', N'Fresher', N'The preHandler hook runs after the request has been parsed and validated, but before the main route handler is executed. It is commonly used for tasks like checking user permissions or performing additional request processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd662f04-7703-4757-8c73-5231c977faea', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the benefit of SolidJS''s compilation step?', N'Intern', N'The compilation step transforms JSX into highly optimized, vanilla JavaScript DOM manipulations. By doing this work at build time, the runtime overhead is significantly reduced compared to frameworks that do this in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6822247-1a3e-475c-8b0f-5235fecaf74d', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the difference between a broadcast message and a multicast message in messaging?', N'Middle', N'Broadcast sends a message to every consumer in the entire system, while multicast targets a specific group of subscribers interested in a particular subject. Multicast is generally more efficient as it reduces unnecessary network traffic to uninterested parties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbe2cc04-0950-44e8-86cb-5238b356cd2f', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What does it mean for Axum to be type-safe?', N'Intern', N'Axum leverages Rust''s strong type system to ensure that handlers receive the exact data they expect. If a request does not match the expected structure, the framework automatically handles the error, preventing invalid data from reaching the handler logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f05ceb50-ae91-487d-94d3-52393e6c6e6c', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What are Extractors in Axum?', N'Intern', N'Extractors are a mechanism in Axum used to pull data out of an incoming HTTP request. They allow developers to easily access parts of a request, such as path parameters, query strings, or JSON body content, by declaring them as function arguments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2825765-cd8c-43a5-9258-523aa75f30c9', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the significance of the ''Id'' field in every MongoDB document?', N'Middle', N'The ''id'' field is a mandatory unique identifier for every document, typically implemented as an ObjectId. It serves as the primary key for the collection and is automatically indexed, ensuring that every document is uniquely addressable within the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa66bdb3-6fe2-40da-8186-523c85d15b83', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What does ''opinionated framework'' mean?', N'Intern', N'An opinionated framework provides a set of established conventions, structures, and tools for building applications. It restricts some freedom to ensure that developers follow a consistent and proven approach.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd25aca95-0d7b-44c4-b676-523da113b93f', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is the distinction between ''asynchronous'' and ''synchronous'' message handling fundamental in Actix?', N'Senior', N'Asynchronous handlers allow the actor to remain responsive to other messages while waiting for I/O, whereas synchronous handlers block the entire actor''s execution thread. Misidentifying a blocking operation as asynchronous leads to thread starvation, which can collapse the performance of the entire system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f86ac86-0a1a-4804-8286-523dd9dc51f5', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What are dynamic routes?', N'Intern', N'Dynamic routes allow you to create pages that share the same layout but display different content based on a URL parameter. For example, a profile page URL could include a user ID, which is then used to fetch the specific data for that user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17063a15-07e6-4588-8da8-5242c989898d', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the trade-offs between using declaration files (.d.ts) and implementing types directly in source code?', N'Senior', N'Declaration files decouple type definitions from implementation, which is essential for type-checking legacy JavaScript libraries. However, they introduce a risk of type-implementation drift where the definitions no longer accurately reflect the underlying runtime behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
