INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29bf32fb-44d8-49ef-9fa3-5245bcef8f45', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What are the advantages of using an in-process cache versus an external caching service?', N'Senior', N'In-process caches offer the lowest possible latency by avoiding network hops and serialization. External caching services, however, provide shared state across multiple application instances and are easier to scale independently from the application nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df969f94-dce4-4081-aab1-52466a1c8fc8', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What are the security risks associated with asynchronous event-driven architectures?', N'Senior', N'Event-driven systems introduce risks such as unauthorized event injection, message tampering, and information disclosure through logs. Security must be enforced by signing and encrypting event payloads, validating the identity of the event producer, and implementing strict access control on the message broker itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92c01596-3a51-4bba-ac22-524ba8ab2d53', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch maintain data consistency?', N'Middle', N'Elasticsearch ensures consistency by sending write requests to the primary shard and then propagating them to all active replicas. A write is considered successful only after the primary shard and the required number of replicas have acknowledged the operation, providing consistency at the cost of some latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ace1f55-c490-4446-b47a-524d4be96010', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between abstraction and encapsulation?', N'Fresher', N'In Java, Abstraction is supported using interface and abstract class while Encapsulation is supported using access modifiers e.g. public, private and protected. Abstraction solves the problem at design level while Encapsulation solves it implementation level. Abstraction is about hiding unwanted details while giving out most essential details, while Encapsulation means hiding the code and data into a single unit e.g. class or method to protect inner working of an object from outside world. Difference: Abstraction Encapsulation Abstraction is a process of hiding the implementation details and showing only functionality to the user. Encapsulation is a process of wrapping code and data together into a single unit Abstraction lets you focus on what the object does instead of how it does it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
