INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ae3eb51-0bd8-4c81-9601-524fed66f072', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the benefits of ''constexpr'' compared to ''const''?', N'Middle', N'Constexpr allows expressions to be evaluated at compile-time, which can improve runtime performance by shifting calculation costs to the compilation phase. While const only ensures immutability, constexpr guarantees the value can be computed during compilation, enabling it to be used in contexts like template arguments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
