INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3492812-1119-42ff-ab5c-5250a3489d5d', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS achieve platform independence?', N'Middle', N'NestJS uses an abstraction layer that allows it to work with different underlying HTTP servers like Express or Fastify. By using an adapter pattern, the core framework remains decoupled from the specific server implementation details.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aef0de09-2325-453c-a79d-525735570c13', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is Data Redundancy?', N'Fresher', N'Data redundancy occurs when the same piece of data is stored in two or more separate places in a database. This can lead to data inconsistency and wasted storage space, which normalization aims to minimize.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebfa819a-9913-45e3-9f61-525b35e0864c', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why is health checking important in a microservices deployment?', N'Middle', N'Health checks allow orchestration tools to monitor the state of individual service instances. If a service becomes unresponsive, the system can automatically restart it or stop routing traffic to it, ensuring overall system availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecdc8f28-b76a-46c4-9e99-525d4f928b6f', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why do NoSQL databases often relax ACID guarantees?', N'Senior', N'To achieve horizontal scalability and high availability, NoSQL databases often follow the CAP theorem, choosing partition tolerance and availability over strict consistency. By relaxing ACID, they avoid the overhead of distributed locks and consensus protocols, allowing for faster processing at the cost of eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7c7f408-9fc7-4e02-a802-525de16c9c02', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the ''N+1'' query problem in Django and how can you identify or prevent it?', N'Middle', N'The N+1 problem occurs when an application executes one query to fetch a parent object and then executes an additional query for every related object in a loop. You can prevent this by using select_related or prefetch_related to fetch all required data in a single batch, which significantly improves database performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'378a36c8-0b4e-4e96-8280-5260022536f7', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the purpose of modularizing code during the design phase?', N'Fresher', N'Modularization breaks a large problem into smaller, manageable, and reusable units. This improves collaboration, as different team members can work on separate modules simultaneously without interfering with each other.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
