INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1503b59c-05e4-4b8d-9b5d-526a7bf456ed', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Does AdonisJS support database seeding?', N'Fresher', N'Yes, AdonisJS provides a seeder system to populate the database with dummy or initial data. This is particularly useful for setting up development environments or ensuring required records exist after a migration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5467f6d-a7c1-4225-a33c-526b452b709f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the ''isolate'' model in Dart?', N'Fresher', N'Isolates are independent workers that do not share memory. They communicate by passing messages, which allows Dart applications to perform concurrent operations without the risks associated with shared-memory multithreading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ce6118b-a8fc-448a-97e8-526cb7fec96e', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the difference between a load function in ''+page.js'' and ''+page.server.js''?', N'Fresher', N'A load function in ''+page.js'' runs on both the server and client, whereas a load function in ''+page.server.js'' runs exclusively on the server. Using the server file is necessary if you need to access secure data or a database directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb59bc83-b026-4e55-8fa6-527072d52dd6', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why do some NoSQL databases prefer ''Eventual Consistency'' over ''Strong Consistency''?', N'Senior', N'Eventual consistency significantly improves availability and system responsiveness by allowing local reads and writes without waiting for global synchronization. This is preferred in large-scale systems where the latency penalty of synchronous cross-data-center replication would be unacceptable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
