INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20a89df2-6d80-490e-a2d8-5279cd756e08', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'When should you choose a NoSQL database over MySQL?', N'Middle', N'NoSQL is generally preferred when dealing with unstructured data, rapidly changing schemas, or extreme write-throughput requirements that exceed a single MySQL instance. If your application requires massive horizontal scalability and eventual consistency is acceptable, NoSQL systems often provide a more flexible architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d6f429d-e9dd-45de-a640-527b44e5d137', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the hoisting behaviour inside let/const blocks, and how does it affect switch statements?', N'Intern', N'let and const are block-scoped and hoisted within their block to the TDZ. A switch statement''s {} is a single block — all case clauses share the same block scope. This causes a subtle bug: a let declared in one case is technically in scope (hoisted) for all other cases in the same switch block, causing a SyntaxError if another case attempts to declare the same name. Example: Real-World Use Case: This exact bug has appeared in production Redux reducers where developers switched from var to let during a linting migration. All case branches in a reducer''s switch share one block, so re-declaring let draft in multiple cases causes a SyntaxError caught only at parse time — blocking the entire app from loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
