INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18b4ad67-230c-42b2-bd44-52a3f013f6d1', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why should you avoid using defer inside a tight loop?', N'Senior', N'Each defer statement registers a function call on the goroutine''s stack to be executed upon return, which incurs both CPU and memory overhead. Within a tight loop, this can lead to significant performance degradation and stack exhaustion compared to executing the cleanup logic immediately or using a closure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
