INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56c815a3-5b91-47d9-9883-52adf80694f0', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra ensure that writes are atomic?', N'Middle', N'Cassandra provides atomicity at the row level. A single write operation to a row is guaranteed to be atomic, meaning the entire row is updated successfully or not at all, preventing partial updates to individual columns within that row.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
