INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b816d3f6-9cb1-4dfc-aac0-52b98b33bfb0', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What are the architectural trade-offs of using jQuery plugins compared to modular npm packages?', N'Senior', N'jQuery plugins often rely on global namespace pollution and side-effect-heavy initialization, making dependency management difficult. Conversely, modern modular packages leverage ES modules for tree-shaking, better encapsulation, and explicit dependency injection, which improves build performance and code maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c4b1d9f-f770-4ee8-ad42-52bb887941c6', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the role of a service mesh in microservices?', N'Middle', N'A service mesh provides a dedicated infrastructure layer for service-to-service communication, handling traffic management, security, and observability. It offloads these network-level concerns from the application code to a fleet of sidecar proxies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'592049bc-7c7a-4329-a73d-52bcd4e7b795', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Describe the trade-offs of using Doctrine ORM''s Unit of Work pattern in a high-concurrency environment.', N'Senior', N'The Unit of Work tracks object state changes and performs batch updates, which reduces database round-trips. However, in high-concurrency environments, long-lived Unit of Work states can consume significant memory and lead to optimistic locking conflicts if not managed with short-lived transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29c2f0c3-ec99-4e75-89e8-52bf2e95f103', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Are Chi handlers thread-safe?', N'Junior', N'Yes, Chi handlers are thread-safe as long as the code inside them does not share mutable state without proper synchronization. Since every request in Go runs in its own goroutine, you should always handle shared data with mutexes or atomic operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
