INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fce26d22-d870-46da-9e77-52c3b6d2df09', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If you notice a memory leak in a production environment, what steps do you take to identify the source?', N'Middle', N'I would capture a heap dump to analyze object allocation patterns and identify which classes are occupying the most memory over time. I would also correlate memory growth with specific service endpoints to see if a particular code path or third-party library is failing to release resources properly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'819b4c78-234a-4dea-be37-52c5686a14ea', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'In a highly available architecture, what are the trade-offs between implementing circuit breakers versus retries with exponential backoff?', N'Senior', N'Retries with exponential backoff are effective for transient network failures but can exacerbate cascading failures by placing additional load on an already struggling downstream service. Circuit breakers provide a fail-fast mechanism that protects the downstream service by stopping requests entirely during periods of instability, allowing the system to recover. A robust design often combines both, using retries for minor glitches and circuit breakers for systemic degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58b5e4a4-5639-44bc-ae36-52c627945009', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is ''process.nextTick'' often considered dangerous in high-concurrency Node.js applications?', N'Senior', N'Process.nextTick fires immediately after the current operation completes, before the event loop proceeds to the next phase. If used recursively or excessively, it can starve the I/O event loop, preventing it from processing timers or I/O callbacks, effectively causing a process hang.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5747a71-db54-4b2e-8a61-52c662e7b7b6', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What happens if an error occurs in a Fastify route handler?', N'Intern', N'If an error is thrown in a route handler, Fastify catches it and passes it to the central error handler. This ensures that the server does not crash and that a standard error response is returned to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
