INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24dfb5b1-ce31-4ba1-8fea-52ca27d901ab', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'When would you prefer a Wide-Column store over a Document store?', N'Senior', N'Wide-Column stores are better suited for massive datasets requiring high write throughput and efficient storage of sparse data where many rows may have different sets of columns. Document stores are generally more flexible for hierarchical, polymorphic data models that require complex indexing on nested fields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15dcc188-ba1e-4de1-9ed8-52cbd23be78a', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Explain your methodology for identifying a root cause in a system where data consistency issues appear sporadically across a distributed database.', N'Senior', N'I would trace the replication lag metrics and verify the consistency levels configured for both read and write operations. If the system supports multi-leader or asynchronous replication, I would look for race conditions in the application logic that assume immediate linearizability and evaluate if distributed locks or idempotent operations are necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
