INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1cd7987-36bf-48c0-8349-52ce87e77407', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you choose a serialization format like JSON, Protobuf, or Avro for internal communication?', N'Middle', N'JSON is best for debugging and general interoperability due to its human-readability. I choose binary formats like Protobuf or Avro when performance and bandwidth efficiency are critical in high-traffic services. These formats also provide stronger schema enforcement, which helps prevent compatibility issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
