INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90cb7b26-447b-4fd3-98ba-530e8632e058', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you handle partial failures in a system where one API request depends on multiple downstream service calls?', N'Senior', N'Use the circuit breaker pattern to stop requests to failing services and return a fallback response or a degraded state. Implement bulkhead patterns to isolate resource pools, ensuring one failing service does not consume all available threads, and use timeouts to prevent long-tail latency from cascading upstream.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'106ce7c0-312b-4048-91e9-5312795ad07a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a RegExp object?', N'Intern', N'A regular expression is an object that describes a pattern of characters. The JavaScript RegExp class represents regular expressions, and both String and RegExp define methods that use regular expressions to perform powerful pattern-matching and search-and-replace functions on text. Syntax: * pattern − A string that specifies the pattern of the regular expression or another regular expression. * attributes − An optional string containing any of the "g", "i", and "m" attributes that specify global, case-insensitive, and multi-line matches, respectively. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ae5ba19-f57f-4217-a968-5313d62aa848', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why do NoSQL databases often relax ACID properties?', N'Fresher', N'NoSQL databases often prioritize high availability and horizontal scalability over strict ACID compliance. They frequently follow the BASE model, which favors eventual consistency to improve performance in distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acac5d4a-40ce-4b1d-abf8-5318636b45d2', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the benefit of Automatic Inlining of Fonts?', N'Intern', N'During compile time, Angular CLI will download and inline the fonts that your application is using. This performance update speed up the first contentful paint(FCP) and this feature is enabled by default in apps built with version 11.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0ee40c5-f8e4-4bdf-9566-531ec98015a2', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What are CSS variables and why are they useful?', N'Junior', N'CSS variables, or custom properties, allow you to store reusable values like colors or spacing units in one place. They make it easier to maintain consistency across a project because changing one variable updates every element that references it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2e4d772-2186-44ee-99bf-531ee461cdd0', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Can Hooks be used in class components?', N'Middle', N'No, Hooks cannot be used inside class components. They are specially designed for function components. This is because hooks depend on the sequence in which they are called during a component’s render, something that''s only guaranteed in functional components. However, both class and function components can coexist in the same application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49c658c5-2499-4913-b3fd-531fad2b3b32', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is SolidJS?', N'Intern', N'SolidJS is a declarative JavaScript library for building user interfaces. Unlike many other frameworks, it does not use a Virtual DOM but instead compiles components into real DOM nodes and reactive primitives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ade047d-bdc0-4a66-99e6-532200c5403e', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the difference between a synchronous and asynchronous path operation in FastAPI?', N'Fresher', N'A synchronous path operation is defined with ''def'' and runs in a separate thread pool to prevent blocking the main loop. An asynchronous path operation uses ''async def'' and runs directly on the event loop, which is more efficient for non-blocking I/O operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50ac39ce-f1d1-48ca-bdce-5322a0c6005b', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are the trade-offs of using Ruby''s metaprogramming capabilities like define_method?', N'Middle', N'Metaprogramming allows for highly flexible and DRY code that can adapt to dynamic requirements. However, it often makes code harder to read, prevents static analysis tools from working correctly, and can lead to performance overhead during the definition phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e8e2903-f1a0-4215-a8c0-532502fbc795', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why is ''proxy-based'' reactivity preferred over ''getter/setter'' reactivity?', N'Senior', N'Proxy objects allow trapping a wider range of operations, including property addition and deletion, which are difficult to intercept with traditional defineProperty getters/setters. This provides a more robust and complete observation mechanism for complex data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'899539dd-04cd-4e09-99f6-5326461ce6db', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the difference between a Model and a Resource in Laravel?', N'Junior', N'A Model represents the data structure and business logic associated with a database table. An API Resource acts as a transformation layer that formats the model''s data into a specific JSON structure before sending it to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac54c12d-ef04-43cd-8ba2-53274327a05b', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are wide-column stores?', N'Intern', N'Wide-column stores organize data into flexible columns rather than rows. This allows each row to have a different number of columns, making them highly efficient for storing massive datasets across many servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b764757-b500-43bc-b01a-5327f58376f6', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of the Ember ''Engine'' architecture?', N'Senior', N'Engines allow an Ember application to be split into distinct, independently deployable or lazy-loadable units. This architecture is vital for large-scale micro-frontend strategies, enabling teams to develop, test, and deploy features in isolation while sharing common core services and utilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e72b21ba-cad3-42c3-9db1-532f00395f59', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you architect a system to handle sudden, massive spikes in traffic without manual intervention?', N'Senior', N'I rely on a combination of horizontal auto-scaling, aggressive caching at the CDN and edge layers, and asynchronous request processing using message queues. By offloading heavy compute tasks to background workers, the system maintains responsiveness while the auto-scaler provisions additional capacity to meet demand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc4914ac-ac1b-4493-898d-5332360325ed', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Why is ''string'' considered immutable in C#?', N'Middle', N'Strings are immutable to ensure thread safety and consistent behavior when passed around the application. Because a string cannot be modified once created, any operation that appears to change it actually results in the creation of a new string object in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62f028ef-69c3-40b2-ba25-533361378cf5', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is a Phoenix Migration?', N'Intern', N'A migration is a version-controlled way to modify the database schema over time. It allows developers to define changes, such as adding tables or columns, in a script that can be run reliably across different environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a69a072f-d103-4eb6-bef4-53350a14bed0', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What happens when a validation error occurs in Fastify?', N'Intern', N'If an incoming request does not match the defined JSON schema, Fastify automatically returns a 400 Bad Request error. This prevents invalid data from reaching your business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97ba81b7-2b7a-4bce-8d06-533761e2acd2', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle a failing background job that processes critical user data?', N'Middle', N'I would implement a robust retry policy with exponential backoff and jitter to avoid overwhelming the system. If the job continues to fail, it should be moved to a dead-letter queue (DLQ) for manual inspection, ensuring that data is not lost and that developers are alerted to the failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86fdcb2b-d319-4c12-8e65-533cdc867dde', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the impact of Echo’s ''Group'' routing feature on application modularity and security?', N'Senior', N'Echo Groups allow for logical separation of API versions and specific middleware application, such as requiring authentication for an entire subset of routes. This improves maintainability and reduces the risk of accidental exposure of unauthorized endpoints by centralizing security policy definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b02ff39-737e-4593-9533-533d5a43346b', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt’s ''Island'' architecture (Server Components) change the paradigm of hydration?', N'Senior', N'Server components allow parts of a page to be rendered exclusively on the server without shipping any JavaScript for those specific sections to the client. This drastically reduces the hydration load and the total bundle size, as non-interactive elements remain static HTML, decoupling them from the reactive component tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62ec502e-57b2-4ed2-9278-5340c60ab04f', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the ''is'' operator used for?', N'Junior', N'The ''is'' operator is used to check if an object is compatible with a given type or matches a specific pattern. It returns a boolean value and is frequently used to safely perform type casting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53e29a6b-f87b-41b4-87d4-534100beb1f3', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What happens if you use a blocking operation in an ''async def'' function?', N'Junior', N'Using a blocking operation in an async function will stop the entire event loop, preventing the server from handling other concurrent requests. This negates the performance benefits of using FastAPI''s asynchronous capabilities and should be avoided or run in a separate thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9677183f-d8e3-4ec5-9d97-5342f10428e9', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you manage configuration drift across a fleet of thousands of servers?', N'Senior', N'I enforce infrastructure-as-code principles where the state of the environment is defined in version control and applied by automated configuration management tools. I periodically run reconciliation loops to detect and automatically revert any manual changes made outside of the defined deployment pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c99ef9aa-0b70-4e37-8ce3-53430a1cc6d0', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How do you trigger a custom event in Alpine.js?', N'Junior', N'You can use the $dispatch magic method to trigger a custom event that can be listened for by other Alpine components or standard JavaScript event listeners. This is a common pattern for communicating between components that are not directly related.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'695214ba-5d61-44c7-866d-53459c81c757', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the Go runtime handle a panic in a goroutine?', N'Middle', N'If a panic is not recovered within the goroutine, it will cause the entire application to terminate immediately. This is a deliberate design choice that prevents the application from continuing in an inconsistent or undefined state after a critical error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60748165-1393-4a74-9fd9-5345bcf9fda6', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of the ''publicPath'' configuration?', N'Junior', N'The publicPath setting specifies the base path for all assets within your application. It is particularly important when your assets are hosted on a CDN or when your application is deployed to a sub-directory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72ff6eb2-45e1-4fde-9601-53467b02eaed', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a scenario where a deployment introduces a regression that is not immediately obvious?', N'Middle', N'I would immediately roll back the deployment to restore service and then compare the metrics of the current version with the previous version. I would review the change set to identify potential areas that impact performance or correctness. Once identified, I would create a regression test to ensure the issue is caught in the future and does not reoccur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f60b6d4-3f08-4f73-a286-534ac6286280', N'a2838158-7305-480a-b22b-4dc35776b400', N'How do you handle the trade-off between consistency and availability during a network partition in a distributed system?', N'Senior', N'According to the CAP theorem, you must choose either consistency or availability. In a CP system, you stop accepting writes to maintain data integrity, while in an AP system, you allow writes to different partitions and resolve conflicts later using techniques like vector clocks or CRDTs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b6be69c-973d-49c1-9ce8-534bebd021d0', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does Python handle variable scope using the LEGB rule?', N'Middle', N'Python searches for names in the Local scope, then the Enclosing scope (like nested functions), then the Global scope, and finally the Built-in scope. This hierarchy ensures that inner scopes can shadow names defined in outer scopes without affecting them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc62656f-1fe7-487f-8847-534c2d9c7c9e', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of the ''CanMatch'' guard in Angular routing, and how does it compare to ''CanLoad''?', N'Senior', N'CanMatch allows the router to decide whether to even consider a route definition based on application state, effectively blocking it from being matched. It is superior to CanLoad because it supports multiple routes for the same path, allowing for more flexible routing logic without pre-loading lazy modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08cb301c-e9ff-41cf-8cf8-534ec0ca4be6', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the primary motivation for choosing Preact over React?', N'Junior', N'Preact is designed to be a lightweight alternative to React, focusing on a significantly smaller bundle size. It is ideal for performance-sensitive applications or projects where minimizing the initial load time is a priority.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93bf4d07-437d-4f75-9fcb-534ee9063586', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the primary difference between Sass and SCSS syntax?', N'Middle', N'SCSS is a superset of CSS that uses curly braces and semicolons, making it fully compatible with existing CSS files. The original Sass syntax uses indentation instead of braces and removes semicolons, which can be cleaner but requires a stricter writing style.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fc5ec10-ca45-4e13-a3e5-53502af1a232', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of a controller action?', N'Junior', N'A controller action is a method inside a controller that handles a specific web request. Its job is to interact with the model to fetch or manipulate data and then decide which view to render or where to redirect the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c938ebf0-462d-40af-99de-535125f9b95a', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Does Preact support React hooks?', N'Fresher', N'Yes, Preact has full support for standard React hooks like useState, useEffect, and useMemo. They function in the same way as they do in React, allowing for familiar functional component development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e37c12ec-dee1-4bca-b6c4-53537f429e65', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How can you detect if your caching strategy is effectively reducing backend load?', N'Senior', N'Effectiveness is measured by monitoring the ''Cache Hit Ratio'' and observing the correlation between cache throughput and backend database CPU/IO utilization. A declining hit ratio while traffic remains stable indicates a need to tune TTLs, keyspace sizing, or invalidation logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c26af37-c264-4cfa-83f0-5354a44ab604', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Is Rocket suitable for beginners?', N'Fresher', N'Rocket is often considered beginner-friendly for those who have a basic understanding of Rust. Its clear documentation and intuitive API design help newcomers build robust web applications without needing to manage complex server configurations manually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
