INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2178708-23bf-40a4-8fe6-535de76bfce5', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the advantage of using ''Router::merge'' in Axum?', N'Middle', N'The merge method allows developers to combine multiple routers into a single, cohesive API structure. This promotes a modular architecture where different team members or services can define their own routes independently before aggregating them at the application root.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1cfeece5-2bd4-48f9-81ef-535f49f7b585', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are namespaces used for?', N'Junior', N'Namespaces are used to organize code into logical groups and prevent name collisions in large projects. By placing code inside a named namespace, you ensure that identifiers do not clash with those in other parts of the program or external libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
