INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b664f0f9-1f34-4cef-bdda-53605a1bc430', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to use styles in React?', N'Fresher', N'The style attribute accepts a JavaScript object with camelCased properties rather than a CSS string. This is consistent with the DOM style JavaScript property, is more efficient, and prevents XSS security holes. Style keys are camelCased in order to be consistent with accessing the properties on DOM nodes in JavaScript (e.g. node.style.backgroundImage).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'143ac742-929e-48aa-b440-53623e46733a', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why is it important to use ''super.connectedCallback()'' in custom lifecycle methods?', N'Junior', N'Calling super.connectedCallback() ensures that Lit''s internal setup logic for the component lifecycle executes correctly. Skipping this call can prevent the component from functioning as expected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'daed86c4-62fe-4455-beda-5362b0dfadae', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Explain the trade-offs between ''at-least-once'' and ''exactly-once'' delivery semantics in distributed message queues.', N'Senior', N'At-least-once delivery ensures no message is lost but risks duplicates, requiring downstream systems to be idempotent. Exactly-once delivery typically requires distributed transactions or atomic commits across the producer, broker, and consumer, which significantly increases latency and reduces overall system throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6df1d851-bda9-4dcf-95b2-536424fc3d1a', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is middleware in the context of Axum?', N'Intern', N'Middleware is a layer that wraps an Axum service to perform actions on requests or responses before they reach the handler. Common uses include logging, authentication, and modifying request headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe025365-7730-4919-b5b7-5368e406fbdd', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a Foreign Key constraint and a Trigger in terms of performance?', N'Senior', N'Foreign Keys are highly optimized, declarative constraints that the query planner can leverage for join elimination or planning. Triggers are executed procedurally for every row, which introduces significant overhead and is typically much slower than built-in constraint checking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2ddbf6d-bfd7-4d56-b328-536b2b2d1450', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Explain the utility of ''shallow routing'' in SvelteKit and when it should be architecturally preferred.', N'Senior', N'Shallow routing allows for URL updates that change the browser state without triggering a full page transition or re-running load functions. This is ideal for managing UI-only states like modals or tab selections that should be bookmarkable without incurring the overhead of a full route lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
