INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac121e67-2c8a-49c7-a591-536eb19c956c', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a unique key?', N'Intern', N'A unique key is a constraint that ensures all values in a specific column are different from each other. Unlike a primary key, a unique key can allow null values depending on the database system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22a16041-fbad-4b1b-8eb4-536f3fc3b019', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Describe the impact of Express middleware on request latency and how to instrument it for observability.', N'Senior', N'Every middleware added to the stack increases the call stack depth and adds latency to the request-response cycle. Observability can be achieved by implementing a timing middleware that logs the time elapsed between receiving the request and sending the response, integrated with distributed tracing tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fde9c7cb-b7c8-4eda-a9a7-536f93567290', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Explain the role of the Tailwind configuration file in enforcing a design system at scale.', N'Senior', N'The configuration file acts as the single source of truth for design tokens, such as spacing, colors, and typography. By centralizing these values, it ensures that developers consume a unified set of constraints, preventing ''magic numbers'' and ensuring consistent UI patterns across distributed teams.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce42b7b3-ee51-47dc-a22f-5370a7535b03', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the role of the partition key in Cassandra?', N'Fresher', N'The partition key is a specific part of the primary key used to determine which node in the cluster will store a particular row of data. It ensures that related data is grouped together on the same physical node, which helps in optimizing read and write performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83bf81cc-f777-4bc4-940d-53722e283367', N'a2838158-7305-480a-b22b-4dc35776b400', N'Compare the performance implications of ''Read-Repair'' versus ''Read-Only'' quorum strategies.', N'Senior', N'Read-repair improves data consistency by comparing versions across replicas during a read and updating stale ones, but it adds latency to the read request. A read-only quorum strategy focuses purely on retrieving the most recent value based on timestamps or versions without attempting to fix inconsistencies immediately. Read-repair is better for background consistency, while quorum-only reads are optimized for low-latency retrieval.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cbaf044-5691-4eec-8e72-537257a1e23e', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of ''Depends'' in FastAPI?', N'Intern', N'The ''Depends'' class is used to declare a dependency in a function signature. It tells FastAPI to execute the dependency function first and provide its return value as an argument to the main route handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66a79f4b-026c-4ec9-9396-5373515929d2', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What are the limitations of using the Fastify plugin system for very large projects?', N'Middle', N'While the plugin system is powerful for modularity, an overly complex nested dependency tree can lead to difficult debugging scenarios regarding scope and registration order. Developers must maintain clear boundaries to prevent circular dependencies or unexpected property overrides.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d1f188c-ccc6-41f9-b4de-53736b5c440b', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the purpose of a caching strategy in system design?', N'Intern', N'Caching is used to improve performance by storing frequently accessed data in a faster, temporary storage layer. It reduces the load on primary databases and decreases latency for end-users, though it introduces the complexity of maintaining cache consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f3a6868-cb19-429c-93f4-5374c0c67761', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to debug your React Native?', N'Fresher', N'Follow the below steps to debug React Native app: 1. Run your application in the iOS simulator. 2. Press Command + D and a webpage should open up at http://localhost:8081/debugger-ui. 3. Enable _Pause On Caught Exceptions_ for a better debugging experience. 4. Press Command + Option + I to open the Chrome Developer tools, or open it via View -> Developer -> Developer Tools. 5. You should now be able to debug as you normally would.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c804209-75a7-476a-b616-5377b2940cef', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the purpose of the ''apply'' directive, and when should it be avoided?', N'Middle', N'The apply directive allows you to extract complex utility patterns into a custom CSS class for better readability. It should be avoided when it leads to recreating CSS-like structures, as it can hide the benefits of utility-first development and make it harder to identify which styles are applied to an element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dce0907f-efaa-4a9b-97a4-5377f5c247e3', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle a situation where a third-party API provider experiences frequent, unpredictable outages?', N'Senior', N'I would implement a robust abstraction layer or ''anti-corruption layer'' with defensive programming techniques like timeouts, circuit breakers, and fallback mechanisms. If the API is mission-critical, I might also consider a caching strategy or a multi-provider failover approach to reduce dependency risks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97a210ed-c527-4d99-9b83-53780381e9a6', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is an index in MongoDB?', N'Intern', N'An index is a special data structure that stores a small portion of the collection''s data set in an easy-to-traverse form. It is used to improve the performance of read operations by allowing the database to find documents quickly without scanning every document in a collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e58fd1f4-cf91-4d53-8ad0-5378ef7dad4a', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Explain the difference between stack and heap allocation in the context of Rust.', N'Middle', N'Stack allocation is fast and uses a LIFO structure for local variables with known sizes at compile time. Heap allocation is used for data with sizes that may change or are unknown at compile time, requiring manual or automated deallocation managed by Rust''s ownership system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0be3645a-8ec1-4cb4-9f4e-537be2521f33', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of an alias in a SQL query?', N'Junior', N'An alias is a temporary name given to a table or a column in a query result. It makes the output more readable or helps distinguish between columns when performing complex joins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5703950-2f5c-4d77-80d2-537bf9d6e4ce', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is a closure in Python?', N'Intern', N'In Python, a closure is a function object that has access to variables in its enclosing lexical scope, even when the function is called outside that scope. In other words, a closure allows a function to remember and access the values of the variables in the environment where it was created, even if those variables are no longer in scope when the function is called. Closures are created when a nested function references a value from its enclosing function. The enclosing function returns the nested function, which maintains a reference to the enclosed value. The enclosed value is stored in the closure, which is attached to the nested function object. Here''s an example of a closure in Python: 7', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80dc7d81-85e0-49e7-a7d7-537e88a8e6c6', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact maintain its small size while supporting complex features like Suspense?', N'Senior', N'Preact implements Suspense through a deferred rendering mechanism that handles promise resolution without requiring a heavy concurrent engine. By isolating the logic needed for async loading, Preact provides the benefits of modern UX patterns without bloating the core library with unnecessary complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a187d1d-b9ff-47e9-8e76-5387d79fff1a', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the Time to Live (TTL) feature?', N'Fresher', N'TTL allows you to define an expiration timestamp for your data. Once the time passes, DynamoDB automatically deletes the expired items, which helps save storage costs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b77b46a8-c35f-4d96-b275-5387dcda989f', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the applications of HTTP interceptors?', N'Intern', N'The HTTP Interceptors can be used for different variety of tasks, 1. Authentication 2. Logging 3. Caching 4. Fake backend 5. URL transformation 6. Modifying headers', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f48575e-0635-44a4-89af-538bee3686b0', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the impact of using ''eager_load'' versus ''preload'' in Active Record?', N'Senior', N'Preload performs separate queries for associations, whereas eager_load uses a LEFT OUTER JOIN to fetch everything in one query. Eager_load is useful when you need to filter the main record based on the associated table, while preload is generally more efficient for memory and avoids the Cartesian product problem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c245c6a-c0af-47e4-9586-538dce592427', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle 404 Not Found or 405 Method Not Allowed errors?', N'Intern', N'Chi provides default handlers for these errors, but they can be easily customized by defining custom NotFound and MethodNotAllowed functions on the router. This allows for consistent error responses across the entire API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'418a154f-2031-4e0d-b482-538ed91a24a2', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the difference between a Model and a Template?', N'Junior', N'A Model defines the structure of your data and how it is stored in the database, while a Template determines how that data is visually presented to the user in a browser. Models handle the backend data logic, whereas templates focus on the user interface and HTML rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
