INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fb62033-6a79-4957-b6f4-53970f78536f', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does the ''Refinements'' feature address the issue of monkey patching global scope?', N'Senior', N'Refinements restrict the scope of method modifications to specific files or modules, preventing global namespace pollution. This provides a safer alternative to traditional monkey patching by ensuring that changes are only active within the lexical scope where the refinement is explicitly activated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4103d9f-be9c-4112-a9a0-539ad2911954', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle graceful shutdowns, and why is this critical for high-availability systems?', N'Senior', N'Axum integrates with Tokio''s signal handling to catch termination signals, allowing the server to stop accepting new requests while finishing in-flight operations. This is vital for maintaining data integrity and ensuring that clients do not experience abrupt connection resets during deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07d028f8-8e99-4b8e-8e10-539b9d8350da', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of ''@escaping'' in closure parameters?', N'Middle', N'The @escaping attribute indicates that a closure can be called after the function it was passed to has already returned. This is essential for asynchronous operations or completion handlers where the closure is stored for later execution, as the compiler must manage the closure''s lifecycle differently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
