INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'347b4668-58ae-43f2-8cb6-53a0eb507d36', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the difference between a page and an endpoint in SvelteKit?', N'Intern', N'A page is a route that renders HTML for a user to see in the browser. An endpoint is a route that returns data, such as JSON or other formats, and is typically used for API purposes or handling background tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
