INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd880e77a-cc95-4f14-b5e5-53a7cb526fc7', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the security implications of using Django’s auto-escaping in templates.', N'Senior', N'Auto-escaping protects against Cross-Site Scripting (XSS) by converting special characters into HTML entities. While robust, developers must be careful when manually overriding this with the safe filter or mark_safe, as doing so incorrectly can introduce vulnerabilities by rendering untrusted user input as executable HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97f2b861-fd0a-4e7d-acfd-53ad893f7b2c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the limitations of ''Object.freeze'' regarding memory and optimization?', N'Senior', N'Freezing an object signals to the engine that the object shape is immutable, which can allow for deeper optimizations like constant folding. However, it incurs runtime overhead for enforcement and may hinder engines that rely on dynamic shape changes for performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bdb1222-6a82-4cd0-8b9b-53af6d6cf9f2', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is an asynchronous operation?', N'Intern', N'An asynchronous operation allows a program to start a potentially long-running task and move on to other tasks before the first one finishes. Once the task is complete, the program is notified, usually through a callback, promise, or async-await.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f12e4ff-9319-4242-ba84-53b05e8fd897', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the role of the ''Composer'' tool in modern PHP development?', N'Middle', N'Composer is a dependency manager that simplifies the process of installing, updating, and managing third-party libraries. It uses a centralized repository to handle versioning and autoloader generation, ensuring consistency across different development and production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
