INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7ebf8c1-c1dd-4b2d-9c2f-53bd17441dfe', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are the advantages of using Hono over a large framework like NestJS?', N'Intern', N'Hono is significantly smaller and faster, specifically optimized for edge computing and low-latency environments. NestJS is a feature-rich, opinionated framework suited for complex, enterprise-grade applications, often with a larger memory and startup footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd255bb8a-c62a-4a99-8310-53c25ad2fcea', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does database normalization improve data integrity?', N'Middle', N'Normalization reduces data redundancy by organizing tables into a structure that minimizes update anomalies. By ensuring each piece of data is stored in only one place, you prevent inconsistencies that arise when updating the same information across multiple locations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
