INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7c0d157-9c18-4bc2-943e-53c50c79231b', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Explain the role of a Dead Letter Queue (DLQ) in a robust messaging architecture.', N'Senior', N'A DLQ serves as a storage destination for messages that cannot be successfully processed after a predefined number of retries. It prevents ''poison pills'' from blocking the entire pipeline while allowing engineers to inspect and debug failed messages without stopping the flow of valid data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48fb3bd5-1483-430d-816b-53c6a550612c', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What does ACID stand for in the context of relational databases?', N'Intern', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These are the four key properties that guarantee database transactions are processed reliably, ensuring that even in the event of errors or power failures, the data remains accurate and consistent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77f8ec7f-2633-47fd-8d58-53c8484a4990', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When implementing a caching strategy, what is the trade-off between cache hit rate and cache freshness?', N'Junior', N'A long time-to-live setting increases the cache hit rate and reduces load on the backend, but it risks serving outdated information to the user. A short time-to-live ensures data freshness but leads to more frequent cache misses and higher backend load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
