INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73e5859b-9e39-41b3-9a75-53c91fd4e590', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the difference between the dollar sign symbol and jQuery in the context of the library?', N'Fresher', N'In jQuery, the dollar sign is simply an alias for the jQuery function itself. They are functionally identical, and using either one will trigger the library''s main entry point to select elements or execute code. The alias is primarily used to provide a shorter, more readable syntax for developers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebcd0a06-d4b7-4ae0-9f66-53c94d250ebc', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the ''merge'' process affect cluster performance?', N'Middle', N'Merging combines small segments into larger ones to optimize search performance and reclaim space from deleted documents. While beneficial, merging is an I/O and CPU-intensive background task that can compete with indexing and query operations if not properly tuned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
