INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdaf80a8-a8d3-401a-b65c-53cfdddcad24', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go handle defer statements internally to ensure efficiency?', N'Senior', N'Go stores deferred function calls in a linked list structure associated with the goroutine''s frame. In modern versions, the compiler often performs open-coded defers by inlining the deferred calls directly into the function exit path if possible. This optimization avoids heap allocation for the defer structure, significantly reducing the overhead of deferred operations in performance-critical paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1343906-8069-4e9b-a550-53d60303ee7a', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the relationship between an event loop and a fiber scheduler?', N'Middle', N'A fiber scheduler often integrates directly with an event loop to resume fibers when I/O events occur. When a fiber waits for network data, the event loop monitors the socket, and once the data arrives, it signals the scheduler to wake up the associated fiber.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cb88ab6-f925-4c87-830d-53dd1fbe8c04', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Explain the concept of ''chaining'' in jQuery and its impact on code maintainability.', N'Middle', N'Chaining allows multiple methods to be called on the same set of elements by returning the jQuery object itself after each operation. While it makes code concise, excessive chaining can lead to monolithic, hard-to-debug blocks of code that violate the principle of single responsibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7381e394-f722-48c4-ac33-53e02f050d53', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the role of GraalVM Native Image in the Quarkus ecosystem, and what are the trade-offs involved?', N'Middle', N'GraalVM Native Image compiles Java bytecode into a standalone native executable, allowing for near-instant startup and minimal memory consumption. The trade-offs include significantly longer build times and the requirement to explicitly configure reflection, dynamic proxies, or serialization, as the compiler must know all reachable code paths ahead of time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47b71507-bff7-4d98-b3c3-53e08867a306', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the architectural risk of storing secrets in environment variables versus a dedicated Secrets Management service?', N'Senior', N'Environment variables are often logged, visible to child processes, and easily exposed through debugging tools, making them insecure for sensitive credentials. A dedicated Secrets Management service like HashiCorp Vault provides dynamic secret generation, automatic rotation, and granular audit logging, which are essential for ephemeral infrastructure security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90523a47-4aab-43e5-bcb8-53e140fa37db', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it better to use a database transaction when performing multiple related operations?', N'Junior', N'Transactions ensure that either all operations succeed or none of them do, preventing the database from ending up in a partially updated or inconsistent state. This is crucial for maintaining data integrity during operations like financial transfers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afbb9157-23f2-4971-8f01-53e329802c0e', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you prioritize multiple tasks that all seem urgent?', N'Intern', N'I would categorize tasks based on their impact on overall project goals and their dependencies on other work. I would then focus on the tasks that are ''blockers'' for others or have the highest impact, and discuss the priorities with my team to ensure alignment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'346afb10-8626-4b79-96ae-53e3ed71196b', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain the role of the ''Sidecar'' pattern in a service mesh architecture.', N'Senior', N'The sidecar pattern decouples infrastructure-related tasks like logging, security, and traffic routing from the core application logic. By running these processes in a separate container within the same pod, developers can standardize cross-cutting concerns across polyglot services without modifying the application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc1e5c91-21a4-4bcf-ac35-53e4865e9d80', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does escape analysis influence Go''s memory allocation strategy?', N'Senior', N'Escape analysis is a compiler optimization that determines if a variable can be safely allocated on the stack instead of the heap. If the compiler can prove the variable does not outlive the current function scope, it allocates it on the stack, reducing garbage collector pressure and allocation latency. This is a critical factor in Go''s performance, as it minimizes the number of heap-allocated objects that the collector must track.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9db53744-8c1d-4767-91d7-53e595cf05a4', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why might you use ''dynamic'' imports in a Next.js application?', N'Middle', N'Dynamic imports allow you to defer the loading of components or libraries until they are actually needed, reducing the initial bundle size. This is particularly effective for heavy components like charts or editors that are not required during the initial page load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb1de164-7a6f-405f-aae2-53eaa16a0e55', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the role of a content delivery network (CDN) in scaling a global web application?', N'Middle', N'A CDN caches static assets at edge locations closer to the user, significantly reducing latency and offloading traffic from the origin server. This improves performance for global users and provides a layer of protection against certain types of DDoS attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c9db45b-3bad-46de-8740-53eba12ee3cc', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What does the ''Copy'' trait represent in Rust?', N'Intern', N'The Copy trait indicates that a type can be copied by simply duplicating its memory bytes. Types that implement Copy do not move ownership when assigned to a new variable, but instead create a shallow copy of the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4515b247-d6d5-4a03-9575-53ed660381fd', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are asked to estimate how many pages are in a book by just looking at it, what indicators would you use?', N'Fresher', N'I would estimate the number of pages in a small section, such as ten or twenty pages, and see how much physical space that occupies. Then, I would compare that thickness to the total thickness of the book to calculate the total number of pages. This proportional reasoning allows for a quick and reasonably accurate estimation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5746b0b5-1a82-410e-bfda-53f06e1a49d4', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Explain the concept of ''Binary Search'' as a debugging strategy.', N'Fresher', N'Binary search debugging involves disabling half of the newly added features or code blocks at a time to determine where the error lies. By repeatedly splitting the suspected area in half, you can quickly pinpoint the exact component causing the failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'049842da-1fa0-4cbc-9d57-53f351fae5bf', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the role of the ''WiredTiger'' storage engine in MongoDB and how does it handle concurrency?', N'Senior', N'WiredTiger utilizes document-level concurrency control rather than database-level locking, which significantly increases throughput for write-heavy workloads. It achieves this by using optimistic concurrency control and snapshot isolation, allowing multiple threads to modify different documents within the same collection simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c99c3252-6ba6-4816-83e9-53f47a533199', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the risks of using the ''vm'' module in Node.js for executing user-provided code?', N'Senior', N'The ''vm'' module is not a security mechanism and does not provide a true sandbox. It is susceptible to prototype pollution and access to the global scope if not strictly isolated. Executing untrusted code in a ''vm'' context can lead to remote code execution or data exfiltration from the host process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70b3b2ce-6b4e-4ffa-861e-53f777b79b03', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is meant by ''Convention over Configuration'' in Spring Boot?', N'Junior', N'This principle means that Spring Boot assumes sensible defaults for common tasks, significantly reducing the amount of manual configuration needed. You only need to provide custom configuration if you want to override these established default behaviors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0aa80a5-5504-4b0d-8b10-53f82e9d6f2a', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are ''params'' in SvelteKit routing?', N'Fresher', N'Params are dynamic segments in a URL path, denoted by square brackets in the folder name, such as [id]. These allow you to create generic routes that can capture specific values from the URL to fetch corresponding data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77d66359-96c5-4bc0-8c31-53f8df799569', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS handle DI under the hood, and what are the limitations of its module-based resolution?', N'Senior', N'NestJS uses a metadata-driven DI container leveraging the Reflect Metadata library to inject dependencies at runtime. A limitation is that all providers must be registered within a module''s scope, which can lead to circular dependency issues if not managed carefully with forward references, and runtime performance overhead during the initial instantiation of the dependency graph.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8734a6f-aee0-4f3c-b8fd-53fd20e938fe', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Describe the architecture of Micronaut''s HTTP server and why it is considered non-blocking.', N'Senior', N'The server is built on Netty, an asynchronous, event-driven networking framework that uses event loops to handle high concurrency with few threads. By leveraging non-blocking I/O, it prevents thread starvation, allowing the application to scale efficiently under heavy load without needing a thread-per-request model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5445996-1676-4186-a86f-53fd9670f592', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus manage database connection pooling in high-concurrency scenarios?', N'Senior', N'Quarkus uses Agroal, a lightweight and highly efficient connection pool designed for high performance. It integrates tightly with the framework to ensure minimal overhead and proper management of connections in both blocking and reactive contexts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09f4f12d-67e4-4af9-9382-54010c995094', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What are the risks of ''Chatty'' microservices communication?', N'Senior', N'Chatty services lead to high network latency, increased overhead, and performance bottlenecks due to frequent small requests. This is typically mitigated by implementing API aggregation or using GraphQL to fetch all necessary data in a single round trip.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'727c6e55-6b83-4369-a045-5404840b2b91', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack handle CSS processing?', N'Middle', N'Webpack handles CSS by using loaders like style-loader and css-loader to resolve imports and inject styles into the DOM. For production, MiniCssExtractPlugin is typically used to extract CSS into separate files to prevent flash of unstyled content and allow for parallel loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72125094-71f1-46fc-baf9-540486fd5a73', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB handle write contention?', N'Middle', N'DynamoDB uses optimistic locking, which allows applications to perform conditional updates to ensure an item has not changed since it was last read. This prevents lost updates in high-concurrency environments without requiring traditional database locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'372d3177-740b-41f6-930c-5405f011329c', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik resolve the ''hydration mismatch'' problem?', N'Senior', N'Since Qwik does not hydrate, it cannot have a hydration mismatch. The state is serialized on the server and deserialized on the client, ensuring the client-side state is a perfect mirror of the server-side state at the moment of completion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9627fbcd-d8fb-4273-b05e-5406543b70ee', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the ''Buffer Pool Hit Ratio'' influence database performance?', N'Senior', N'A high hit ratio means most data requests are satisfied by memory, minimizing slow disk I/O. If the hit ratio drops, it indicates the working set exceeds memory capacity, forcing the system to perform frequent page swaps and causing a significant performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c34135c7-15d9-4c9a-99f9-5407b5fe4c4f', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of the preprocessor, and how does it influence the compilation process?', N'Middle', N'The preprocessor handles text-based transformations before the actual compilation occurs, including macro substitution, file inclusion, and conditional compilation. It allows developers to create platform-specific code and modularize headers, though it lacks type safety and debugging visibility compared to the compiler itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
