INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91b02000-8800-4978-9b66-540ca15ee581', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Explain the ''Tracked'' system in Ember Octane.', N'Middle', N'The tracked system is Ember''s reactivity mechanism that automatically monitors property changes. When a tracked property is modified, Ember schedules a re-render of only the parts of the DOM that consume that specific property.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acf4d7cf-2989-4798-89fd-540d3025cb0d', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL manage row-level locking without a centralized lock manager for data?', N'Senior', N'PostgreSQL stores lock information directly in the tuple header within the data pages, specifically using the xmin and xmax transaction IDs. This decentralized approach allows for high concurrency but requires visibility checks to confirm if a row is currently locked or if a transaction has finished, ensuring data integrity without a global bottleneck.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79ee4762-a41e-4ee7-b8d0-540da3ed40f9', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is a ''Multi-Document Transaction'' in MongoDB, and what are its limitations?', N'Middle', N'Multi-document transactions allow atomic operations across multiple documents or collections. While powerful, they incur a performance penalty and should be used sparingly, as they require more resources than single-document atomic operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8164fe2e-094b-4815-86ef-540e1e5d35c2', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the role of the ''public'' folder?', N'Fresher', N'The public folder is used to store static assets like images, fonts, or files like robots.txt. Files placed here can be accessed directly by the browser using the root URL path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58a6105c-c2ec-4799-83c3-5410b287dca9', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Are Go maps safe for concurrent use?', N'Junior', N'No, standard Go maps are not safe for concurrent reads and writes. If multiple goroutines need to access a map simultaneously, you must use synchronization primitives like sync.Mutex or sync.RWMutex.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b5cf695-881b-4370-8ff2-54119cbddf5a', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the purpose of a Write-Ahead Log (WAL) in transaction durability?', N'Middle', N'A Write-Ahead Log ensures durability by recording all changes to a stable storage medium before the actual data files are updated. In the event of a system crash, the database uses these logs to replay committed transactions or undo incomplete ones, ensuring the system returns to a consistent state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdf07825-edae-478d-a8ec-54120d4ade4b', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does data masking differ from encryption?', N'Middle', N'Encryption is a reversible process that protects data, while data masking is generally irreversible and used to hide sensitive information by replacing it with realistic but fake data. Masking is typically used in non-production environments to protect PII while allowing testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0cb6dc5-8c7c-4729-95e9-5412b1468e54', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact''s reconciliation process handle DOM updates?', N'Junior', N'Preact compares the new virtual DOM tree with the previous one during the reconciliation process. It identifies the minimum set of changes required and applies only those specific updates to the actual browser DOM, minimizing expensive operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8859b8c0-2734-4148-b5ca-5414a80c6e60', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How can you make sure your dependencies are safe?', N'Fresher', N'The only option is to automate the update / security audit of your dependencies. For that there are free and paid options: 1. npm outdated 2. Snyk 3. npm audit 4. npm audit fix', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4b7cd6b-66d2-4240-aa25-54198c21db73', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Explain the ''Circuit Breaker'' pattern and how it is implemented in ASP.NET Core applications.', N'Senior', N'The Circuit Breaker pattern prevents an application from repeatedly attempting an operation that is likely to fail, such as a down remote service. It is implemented using libraries like Polly, which track failures and transition the circuit to an ''open'' state to fail fast, reducing system stress and allowing for recovery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29212a02-f5fb-41e0-8fc3-541b341141a5', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux differ from local component state in React?', N'Fresher', N'Let''s look at the key differences between using Local Component State and Redux for managing state in React. Why Use Global State Management Managing state globally: - Is especially useful for larger applications, as it streamlines access and updates to state across components. - Simplifies data sharing between components located at different levels of component hierarchy. Advantages and Limitations of Local Component State Advantages - Simplicity: It''s quick and easy to set up local state within a component. - Scoped Updates: Changes to local state are contained within the component, making it easier to manage and reason about. Limitations - State Duplication: Keeping similar state in sync across multiple components can lead to inconsistencies and bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38acbb60-656b-4fe7-8429-541ebd04d16a', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are the risks of dynamic function calls and variable variables in PHP?', N'Middle', N'Dynamic function calls and variable variables make static analysis and refactoring extremely difficult for IDEs and automated tools. They can also introduce security vulnerabilities if user input is allowed to influence which function is called or which variable is accessed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb672aa8-fd8b-44a7-b693-541fa82d8fbb', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why is caching dynamic content more challenging than static content?', N'Middle', N'Dynamic content is often personalized based on user identity, permissions, or real-time state, meaning it cannot be shared across different users. Caching this requires complex key structures that include user-specific identifiers, which significantly reduces the effective cache hit ratio compared to static assets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce836251-3550-41c9-b0bf-54201a7f059a', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What are the performance implications of using ''next/image'' compared to standard HTML image tags?', N'Middle', N'The Next.js image component automatically optimizes images by resizing, compressing, and converting them to modern formats like WebP or AVIF based on the user''s browser. It also provides lazy loading by default, which significantly improves Core Web Vitals like Largest Contentful Paint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b842c395-0666-4bf4-8ec6-542043fcc46e', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the browser''s CSSOM construction differ from DOM construction?', N'Senior', N'DOM construction is incremental as HTML is parsed, whereas CSSOM is blocking; the browser cannot render any content until all CSS has been parsed. Because CSS is a render-blocking resource, large or unoptimized CSS files directly delay the time-to-interactive and initial visual feedback.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c849a556-8db5-4995-84b1-5420b5e0961e', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you determine the appropriate level of logging for a production application?', N'Junior', N'You want enough logging to reconstruct the state of the application during a bug, but not so much that you overwhelm your storage or generate noise. Focus on logging errors, critical lifecycle events, and essential audit trails while using different log levels to filter output based on environment needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a888a21e-7c16-4bca-8109-5422a8256c90', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What are middleware in Laravel?', N'Intern', N'Middleware act as a firewall between the incoming HTTP requests and the application logic. They provide a mechanism to filter, inspect, and possibly alter the incoming data. Laravel has built-in middleware for various common tasks, and it also allows developers to create custom middleware tailored to application-specific requirements. Middleware in Action When an HTTP request hits your Laravel application, it moves through several middleware before reaching the intended controller or view. These are some frequently-seen operations achieved by middleware: - Authentication: Ensure that the user issuing the request is authenticated before reaching the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65a3a25f-f6bf-46bd-a6cb-5424fbb0e8c3', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Explain the concept of ''Zero-Cost Abstractions'' in Rust.', N'Middle', N'Zero-cost abstractions mean that features like iterators, closures, and generics do not impose a runtime performance penalty compared to manually written, non-abstracted code. The compiler optimizes these high-level constructs into efficient machine code that matches hand-tuned implementations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe269e3f-bdd4-49b5-9058-54258dc3b395', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Explain the architectural implications of Hono''s middleware composition model versus Express''s traditional approach.', N'Senior', N'Hono utilizes a middleware pattern built on the Fetch standard, which is inherently asynchronous and non-blocking, making it highly efficient for edge computing. Unlike Express''s callback-heavy, mutable request-response object paradigm, Hono''s approach favors functional composition and immutable objects, which reduces side effects and improves predictability in highly concurrent, distributed environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2383f4be-1f92-4dbf-a89c-5425a95ac797', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How can you implement versioning in a Chi-based API?', N'Middle', N'Versioning is best handled in Chi by using route groups, where each group represents a specific version prefix. This allows you to apply different middleware stacks or handler versions to specific segments of the API, keeping the codebase clean and version-specific logic isolated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4c148f1-993a-445a-a747-542647c1b700', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are ''Tag Helpers'' in ASP.NET Core?', N'Fresher', N'Tag Helpers allow server-side code to participate in creating and rendering HTML elements in Razor files. They make the HTML cleaner and more readable by providing a syntax that looks like standard HTML but is processed by the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd99e06b3-e74e-4e23-b149-54269fa2452a', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is React Router?', N'Intern', N'React Router is a powerful routing library built on top of React that helps you add new screens and flows to your application incredibly quickly, all while keeping the URL in sync with what''s being displayed on the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b452f0fc-33bc-45de-8a98-5427730b469c', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember handle template rendering?', N'Junior', N'Ember uses the Handlebars templating engine to render the UI. Templates are automatically updated when the underlying data properties change, ensuring the view remains consistent with the application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83a26d8c-3f13-4b20-9f08-5429d9d65581', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB calculate consumed capacity for read requests?', N'Middle', N'Consumed read capacity is calculated based on the item size and the consistency model. Strongly consistent reads consume one read capacity unit for up to 4 KB of data, whereas eventually consistent reads consume only 0.5 units for the same size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce6f0718-5128-48dc-8b6b-542b1384b6cd', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the ''Copy-on-Write'' optimization in Swift collections.', N'Middle', N'Copy-on-Write is an optimization where Swift collections like Arrays share the same underlying memory buffer until a modification is requested. If a mutation occurs, the collection creates a unique copy of the buffer, ensuring performance efficiency without unnecessary memory allocations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05e6ed8e-1f10-4f8c-b827-542b4d9b610f', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your strategy for optimizing a system that is experiencing high tail latency?', N'Senior', N'Use distributed tracing to identify the specific services or components contributing to the p99 latency. Focus on eliminating blocking calls, optimizing heavy database queries, and ensuring resource contention is minimized in multi-threaded processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'909e5aa6-b81d-43ca-878a-542b5c1d9624', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is a case class in Scala?', N'Intern', N'A case class is a special type of class that is optimized for use in pattern matching and data modeling. They automatically provide useful methods like equals, hashCode, and toString, and are immutable by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'858879cd-d44f-4ae1-a3a6-542bdab98450', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono''s ''c.set'' and ''c.get'' mechanism handle variable passing between middleware?', N'Senior', N'The context object provides a type-safe storage mechanism for variables that persist for the duration of the request. This avoids passing arguments through function signatures and allows for cleaner, decoupled middleware components that can access shared request data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2edef026-cc66-45ff-bd3d-542c605e4a49', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the impact of ''Prop Polishing'' or spreading large objects as props on performance?', N'Senior', N'Spreading large objects creates new object references on every render, which can break memoization optimizations in child components. It also obscures the component''s data requirements, making it harder for developers to understand the dependency graph.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5619a004-b709-41d0-94b6-54317e6085cd', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the advantages of Jest over Jasmine?', N'Intern', N'There are couple of advantages compared to Jasmine: - Automatically finds tests to execute in your source code. - Automatically mocks dependencies when running your tests. - Allows you to test asynchronous code synchronously. - Runs your tests with a fake DOM implementation (via jsdom) so that your tests can be run on the command line. - Runs tests in parallel processes so that they finish sooner.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04cab61c-ffa7-40fb-b10f-543184cc9d8a', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the benefit of breaking down a large project into smaller milestones?', N'Intern', N'Breaking a project down reduces psychological pressure and allows for regular check-ins to monitor progress. It provides clearer indicators of whether the project is on track and allows for course correction at each milestone.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f01f83d-27b0-4ca6-9e01-54330156cea6', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix leverage the Erlang VM (BEAM) to provide fault tolerance during request handling?', N'Middle', N'Phoenix utilizes the supervision tree architecture of the BEAM, where every request or connection runs in its own lightweight, isolated process. If one process crashes due to an unhandled error, it does not affect other users or the parent processes, and supervisors can automatically restart the failed component to restore service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90651089-db2d-464c-afb5-54330c7836e8', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'In data storage, what is the trade-off between using SQL and NoSQL databases?', N'Intern', N'SQL databases provide strong consistency and structured data relationships, which are great for complex transactions. NoSQL databases offer higher flexibility and scalability for unstructured data, but they often sacrifice strict consistency for performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb4887cf-2934-42eb-8af5-543611103ed1', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'When is it appropriate to use Redux in a project?', N'Junior', N'Redux is beneficial for large-scale applications with complex state, shared data across many components, or frequent state updates. For small applications with simple data requirements, the built-in React state management or Context API is usually sufficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8124b01-da44-4c3d-85a1-543647ef30ea', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is an event loop in relation to fibers?', N'Intern', N'An event loop is a mechanism that monitors I/O events and schedules the appropriate fibers to process those events when they are ready. It works in tandem with fibers to ensure that the system remains responsive even when waiting for network or disk operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c16c1703-0b4c-427a-94f4-5438c6c7ea61', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the ''updated'' lifecycle method used for?', N'Intern', N'The updated method is called after the component''s DOM has been updated and rendered. It is the appropriate place to perform actions that depend on the updated DOM, such as measuring elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3d9ce96-9354-4f6c-87ff-5439da008981', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the impact of high ''refresh_interval'' settings on real-time data ingestion?', N'Senior', N'Increasing the refresh interval reduces the number of segments created, which lowers I/O pressure and improves indexing throughput. However, the trade-off is that data remains invisible to searches for a longer period, breaking the near real-time requirement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7784fa73-48a5-4066-91b9-543a695f97df', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle schema validation?', N'Intern', N'Fastify uses JSON Schema to validate incoming requests and outgoing responses. By defining a schema, the framework automatically validates data and improves performance by compiling the schema into highly optimized code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28ba897b-77a7-49ca-a574-543ab14f3fc9', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the role of the InnoDB Buffer Pool and how does its size affect performance?', N'Middle', N'The Buffer Pool is a memory area that caches table and index data as it is accessed, minimizing disk I/O. A larger buffer pool allows more data to remain in memory, which significantly improves read and write performance, but it must be balanced against available system memory to avoid swapping.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7366a7d6-000c-4b64-927a-543e65383c61', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Is Preact suitable for building complex, long-running single-page applications?', N'Middle', N'Yes, Preact is fully capable of handling complex SPAs. Its efficiency often makes it a better choice for SPAs where performance and load times are critical, provided that the necessary library ecosystem is compatible or available via the compat layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71fe5d51-211e-4429-9dd6-543f0ce630f5', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the primary architectural benefit of Micronaut''s reflection-free design regarding memory consumption?', N'Senior', N'By eliminating runtime reflection, Micronaut avoids the overhead of caching metadata for classes and methods at startup. This results in significantly lower heap usage and a predictable memory footprint, which is critical for deployments in resource-constrained containerized environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5ab5fd7-5ce8-49bd-b0b5-543f8ad19c0d', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do you dispatch custom events from a child to a parent in Svelte?', N'Fresher', N'You use an event dispatcher function provided by Svelte to send messages from a child component to its parent. The parent can then listen for these custom events using the standard event handler syntax.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69354b7b-d851-4dfa-ae95-54412fb07fc4', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How should a developer handle long-running tasks in a Fiber application to avoid blocking the event loop?', N'Senior', N'Since Fiber is non-blocking at the transport layer, long-running tasks should be offloaded to a worker pool or a dedicated goroutine. Blocking the main handler goroutine for extended periods can exhaust the available thread pool or lead to slow request processing for subsequent clients.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f41e3b2-1ef5-44f8-a5a8-5441a01d4a0a', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between g and session in Flask?', N'Middle', N'The g object is a temporary storage namespace for data that should persist only during the lifetime of a single request. In contrast, the session object stores data across multiple requests by serializing information into a cookie or server-side store. Use g for request-specific variables and session for user-specific state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad9a932a-42e5-4f79-a112-5443a3589081', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'In the context of Chi, why is the use of context.Context preferred over custom request headers for middleware data?', N'Senior', N'Using context.Context allows for type-safe, scoped data propagation through the request lifecycle. It prevents namespace pollution in headers and ensures that middleware-injected data is automatically garbage collected once the request context is canceled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a38ef465-4f53-46b3-ab10-5445405f3c86', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle exceptions?', N'Fresher', N'Litestar provides global and local exception handling mechanisms. It allows developers to map specific Python exceptions to HTTP status codes, ensuring the client receives a structured error response instead of a raw stack trace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'074dddcd-fa2a-4cf3-8b38-5448911ecaba', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of the ''defer'' and ''only'' methods in the Django ORM?', N'Middle', N'These methods are used to optimize performance by retrieving only a subset of columns from the database instead of the full object. ''Only'' specifies the fields to load, while ''defer'' specifies fields to exclude, both reducing the amount of data transferred and memory usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afb9dac1-db19-45f5-a52f-544902d988d2', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does object allocation affect Ruby''s garbage collection?', N'Middle', N'Frequent object allocation increases pressure on the garbage collector, leading to more frequent pauses. Efficient memory management in Ruby involves minimizing unnecessary object creation, especially in hot loops, to maintain application throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aaca4058-4f5b-4760-b367-5449039b6992', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between an interface and an abstract class?', N'Intern', N'An abstract class can contain both abstract and concrete methods, while an interface primarily contains abstract methods. A class can implement multiple interfaces but can only extend one abstract class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5c4f167-d596-44bf-ab78-54493fa0e328', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle component state initialization?', N'Junior', N'Qwik serializes the initial state of components into the HTML document as JSON. When the application resumes, it reads this state from the DOM, meaning it does not need to re-run the initialization logic that occurred on the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26325920-fa18-4426-afad-544ab12a36a3', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a debugger statement', N'Intern', N'The debugger statement invokes any available debugging functionality, such as setting a breakpoint. If no debugging functionality is available, this statement has no effect. For example, in the below function a debugger statement has been inserted. So execution is paused at the debugger statement just like a breakpoint in the script source.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b7d2f0a-4b03-48d4-9e90-544d209306e8', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How does ''Event Sourcing'' differ from traditional state-based storage?', N'Senior', N'Instead of storing the current state of an object, event sourcing stores every change as a sequential series of immutable events. This provides a perfect audit trail and allows the system to reconstruct state at any point in time by replaying the event log.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc6d33fb-8915-408f-a7bf-545064ef75be', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'When is it appropriate to use an HSM (Hardware Security Module) versus a Cloud KMS?', N'Senior', N'HSMs offer physical security guarantees and are often required for regulatory compliance in sensitive industries, but they are harder to scale and manage. Cloud KMS provides a highly scalable, developer-friendly interface that is sufficient for most general-purpose cloud applications, offering a better trade-off between operational overhead and security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4818be14-a114-4a6d-b392-545349a4bd76', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you prepare for a meeting where you need to present your progress?', N'Junior', N'I summarize my key accomplishments, note any blockers, and prepare for potential questions about my approach. I ensure I have clear metrics or examples to demonstrate the progress made and keep the presentation focused on outcomes relevant to the team.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edff9706-21cb-4de0-8f58-54561d72fa11', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'When should you use x-model vs x-bind?', N'Middle', N'Use x-model for two-way data binding on form inputs, where the data state should update as the user types. Use x-bind for one-way binding, where you want to dynamically update HTML attributes or classes based on the component''s state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d54b5d6-6abd-4e60-a388-545713458794', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you diagnose a system where the primary bottleneck is high disk I/O wait?', N'Senior', N'I would use system diagnostic tools to identify the specific processes and files contributing to the high I/O wait, looking for excessive logging, swapping, or inefficient database writes. I would then evaluate whether the I/O pattern can be improved through better caching, batching of write operations, or migrating to faster storage media.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd38174f1-0558-42c2-a497-545ac6135e20', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the impact of a security patch on system performance?', N'Senior', N'I would deploy the patch to a staging environment that mirrors production and perform benchmark tests comparing throughput and latency metrics before and after the application. This ensures that any performance degradation is quantified and mitigated before a wider rollout.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'163b2f23-57a5-4490-94e7-545c858d9ce7', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does the plugin system in Fastify support application scalability?', N'Junior', N'The plugin system allows you to encapsulate application logic into isolated contexts. By using the ''register'' method, you can create encapsulated scopes where plugins, hooks, and decorators are inherited down the tree but do not leak into parent scopes, making the codebase easier to maintain as it grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'915b8783-240b-4416-95b2-545f0af7de79', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is strict mode?', N'Intern', N'The Strict Mode is allows you to place a program, or a function, in a strict operating context. This strict context prevents certain actions from being taken and throws more exceptions. Example: Advantages: * Makes it impossible to accidentally create global variables. * Makes assignments which would otherwise silently fail to throw an exception. * Makes attempts to delete undeletable properties throw (where before the attempt would simply have no effect). * Requires that function parameter names be unique. * this is undefined in the global context. * It catches some common coding bloopers, throwing exceptions. * It disables features that are confusing or poorly thought out.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd21ebcab-15e9-4071-9fac-545f2e1caad3', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the impact of excessive middleware on performance in an ASP.NET Core application?', N'Senior', N'Every middleware component adds a layer to the request delegate chain, which introduces minor overhead for each request. While usually negligible, an excessive number of middlewares or poorly implemented logic within them can increase latency and CPU usage, so it is best to keep the pipeline as lean as possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be788d4b-d1f0-4af4-9c00-545f6b78a809', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the role of Fasthttp in Fiber?', N'Fresher', N'Fasthttp is the underlying engine that Fiber uses to handle HTTP requests. It is designed to minimize garbage collection overhead and provide high-concurrency request processing compared to the standard library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2643cb13-bd2f-4b60-b688-545fedb51687', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the role of Rocket''s configuration system?', N'Intern', N'The configuration system allows developers to define settings such as the server address, port, and environment variables. It helps keep environment-specific settings separate from the core application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0373537-f05c-4efb-9c09-54608c7d58f0', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How would you handle high-throughput, non-blocking tasks in NestJS without blocking the event loop?', N'Senior', N'You should offload CPU-intensive tasks to worker threads or external task queues like BullMQ or Redis-based background workers. NestJS services should remain thin, delegating heavy processing to background processes to ensure the main event loop remains free to handle incoming HTTP requests efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77090426-4352-46fc-bf34-54630d5d591a', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What happens if you use the ''let:'' directive on a component?', N'Junior', N'The let: directive is used with slots to pass data from a child component back up to the parent. It allows the child to expose internal properties to the slot content defined in the parent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2e89c4b-55e2-4a0d-a333-5469c2ef1b30', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why is it often unnecessary to use an external Task Queue like Sidekiq or Celery in a standard Phoenix architecture?', N'Senior', N'Because the Erlang VM provides robust primitives for concurrency, such as Tasks and GenServers, developers can execute background jobs directly within the same node. This eliminates the need for external serialization, message brokers, and additional infrastructure for simple asynchronous tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13b3be69-774c-415b-bd65-546b506b0b2b', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of an inverted index?', N'Intern', N'An inverted index is a data structure used by Elasticsearch to allow for fast full-text searches. It maps unique words found in documents to the list of document IDs that contain them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dddfc01b-191f-496c-a2e3-546da76d9cc7', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are custom providers and how do they differ from standard Providers in Nest.js?', N'Intern', N'Providers are essential in NestJS as they form the backbone of the dependency injection system. Their primary role is to create and manage instances of classes that can be injected into different components, promoting modularity and testability. By using providers, NestJS ensures a robust and organized approach to handling dependencies. A standard provider in NestJS is typically a class decorated with @Injectable(). This class can have dependencies, which are injected through the constructor. Here''s an example: In this case, CatsService is a standard provider that can be injected into other classes, and it has a dependency on CatsRepository. But not all providers are services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ad8d35b-69d1-4f95-9669-546e8b0be2ea', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What does re-rendering mean in React?', N'Intern', N'Re-rendering in React refers to the process where a component updates its output to the DOM in response to changes in state or props. When a component''s state or props change, React triggers a re-render to ensure the UI reflects the latest data. This process involves calling the component''s render method again to produce a new virtual DOM, which is then compared to the previous virtual DOM to determine the minimal set of changes needed to update the actual DOM. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'644094cc-1120-40c1-a474-546e908c4b8b', N'4c000000-0000-0000-0000-000000000005', N'Why is it important to implement observability in a distributed system?', N'Middle', N'Observability through logging, metrics, and tracing is essential for identifying bottlenecks and root causes of failures. In a complex, distributed environment, you cannot debug issues without centralized visibility into how requests move across services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cadfb3f-c631-4cd4-9489-5473f3b80d6f', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What are the trade-offs of using ''fastify-plugin'' versus standard registration?', N'Senior', N'Using fastify-plugin allows a plugin to share its context with the parent scope, effectively bypassing the default encapsulation boundaries. While this is necessary for shared decorators or hooks, it increases the risk of tight coupling and scope pollution, whereas standard registration maintains strict isolation for better modularity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4a4665e-b7fc-4a2e-a2c3-5474de641a4b', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle form data?', N'Intern', N'FastAPI supports form data via the ''Form'' dependency class. It allows the API to receive data sent as ''application/x-www-form-urlencoded'', which is common for traditional HTML forms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bd4dbb1-eb3d-4733-a720-5476f4b1c060', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is the ''unknown'' type generally preferred over ''any'' in a strictly typed architecture?', N'Senior', N'The ''unknown'' type acts as a type-safe analog to ''any'' by forcing the developer to perform type narrowing or assertions before accessing values. It preserves type safety at the boundaries of external data consumption, preventing the implicit ''any'' propagation that undermines the integrity of the entire type system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25769f3f-4567-49b6-9962-547804ffa5b9', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the ''Serializable'' isolation level?', N'Intern', N'Serializable is the highest level of isolation, ensuring that concurrent transactions result in a state that is equivalent to executing them one after the other. It effectively prevents dirty reads, non-repeatable reads, and phantom reads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'649a0fc7-1943-419c-96b5-54782ef69432', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the ''next'' argument in an Express middleware function?', N'Fresher', N'The ''next'' argument is a function that, when invoked, tells Express to move to the next middleware or route handler in the stack. If it is not called, the request cycle will hang, and the client will not receive a response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a67ee62-68f3-4c11-a2b6-547a428ac4c1', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between ''self'' and ''Self''?', N'Intern', N'Self (lowercase) refers to the current instance of a type. SELF (uppercase) refers to the type itself, which is often used in protocols to refer to the conforming type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebef8745-67ac-418f-89db-547a54f6ba63', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a Commit Log?', N'Fresher', N'The commit log is a crash-recovery mechanism where all incoming writes are appended before being written to memory. If the node crashes, Cassandra can replay the commit log to restore data that had not yet been flushed to disk.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c9fa347-2acb-484c-90d5-547a64130a6b', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the primary motivation behind Preact''s design?', N'Intern', N'The primary motivation is performance and size efficiency. By stripping away rarely used features and optimizing the core engine, Preact achieves a high-performance rendering experience with minimal overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'907f45c3-251e-488e-8d37-547d33d1cc0d', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain the CSS containment property and why it is useful for performance.', N'Middle', N'The containment property allows developers to isolate a subtree of the DOM from the rest of the page. By signaling to the browser that the subtree''s size or style does not affect external elements, it limits the scope of style recalculations and layout shifts. This significantly improves performance on complex pages by reducing the work required during reflow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07a0c032-9665-4a15-a241-547d4d9837df', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between HTMLCollection and NodeList?', N'Fresher', N'HTMLCollection An HTMLCollection is a list of nodes. An individual node may be accessed by either ordinal index or the node''s name or id attributes. Collections in the HTML DOM are assumed to be live meaning that they are automatically updated when the underlying document is changed. NodeList A NodeList object is a collection of nodes. The NodeList interface provides the abstraction of an ordered collection of nodes, without defining or constraining how this collection is implemented. NodeList objects in the DOM are live or static based on the interface used to retrieve them Difference An HTMLCollection is a list of webpage elements (div, p, ul, li, img objects, etc…) which form part of the DOM, and are of a specific node type usually referred to as an element node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'161dafd8-0c47-424d-bcc0-547eba21c4cc', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the primary purpose of Alpine.js?', N'Intern', N'Its primary purpose is to provide a declarative way to handle frontend interactions like toggling elements, managing state, and simple data binding. It is designed to be embedded directly into HTML documents to keep logic close to the user interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a69aa88d-2ae5-45b8-a8c4-5485b6a4a4b9', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the architectural risks of using too many third-party dependencies in a large-scale Node.js application?', N'Senior', N'Over-reliance on external packages increases the attack surface for supply-chain vulnerabilities, complicates dependency management, and can lead to ''dependency hell'' or bloated bundle sizes. It also introduces hidden performance costs if those packages are poorly optimized or contain synchronous blocking code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0649f21f-d8ab-4f89-8a01-5485c0c7eaa1', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Explain why ''Deadlock Detection'' is a critical background process in an RDBMS.', N'Senior', N'Deadlocks occur when two or more transactions hold locks that the others need, creating a circular dependency. The system must periodically scan the lock graph to identify these cycles and forcibly abort one of the transactions to allow the others to proceed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3d1a166-83d5-4cf4-bff5-54882679bd9e', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is the ''register'' storage class specifier mostly ignored by modern compilers?', N'Senior', N'Modern register allocation algorithms are far more sophisticated than manual hints, as they can track live ranges and data flow across entire functions. Compilers typically disregard the keyword in favor of their own data-flow analysis to decide which variables are best suited for registers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd14aee56-97b9-42ac-a180-5489521abc35', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Explain the concept of ''FastBoot'' and its role in improving SEO and performance.', N'Senior', N'FastBoot runs the Ember application in a Node.js environment to render the HTML before sending it to the client. This allows search engines to crawl the full content immediately and provides users with a faster initial paint, significantly improving both SEO and performance metrics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa668457-d552-41a8-8c08-548ad3d36d8f', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle incomplete information when making a technical decision?', N'Intern', N'I would identify the missing pieces of information and determine if they are critical to the decision. If they are, I would seek to gather that information through research or testing. If the information cannot be obtained, I would make a decision based on the best available data while explicitly documenting the assumptions made.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a10446d-e034-4c63-a4f3-548d40cdbd3a', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Explain the role of ''links'' functions in Remix for asset management.', N'Senior', N'The links function allows developers to define route-specific assets like stylesheets or pre-fetch tags. This ensures that assets are only loaded when they are actually needed, preventing global CSS bloat and improving performance for large applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bda9f51c-8852-4fd5-a842-54901774b11d', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the primary difference between a Relational Database (RDBMS) like MySQL and a NoSQL database?', N'Fresher', N'A relational database stores data in structured tables with predefined schemas and enforces relationships using foreign keys. In contrast, NoSQL databases are schema-less or have flexible schemas, allowing them to store unstructured or semi-structured data such as documents or key-value pairs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da802424-70d7-4589-ade6-5490ded738b9', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is type narrowing?', N'Intern', N'Type narrowing is the process of refining a variable''s type within a specific code block, usually through conditional checks. This allows the compiler to know exactly which type a variable holds at a particular point in the execution flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb3efee2-cac7-4d71-b3cf-54916d3b8c65', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What does the ''Bind'' method do in Echo?', N'Intern', N'The Bind method parses the request body and populates a provided variable, such as a struct, with the data. It supports different formats like JSON, XML, and form data based on the Content-Type header.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff4deaae-c9c6-45e0-91df-54945f0d8fe5', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the trade-offs of using Laravel''s ''Events'' versus ''Observers'' for model-based side effects.', N'Senior', N'Observers are tightly coupled to the model''s lifecycle events, making them good for simple data synchronization, but they can easily lead to ''fat models'' and hidden side effects. Events are more decoupled and allow for multiple listeners, making them better for complex, cross-domain side effects that should be managed independently of the model''s persistence logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6428714c-75ce-433f-90e9-549461515203', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the architectural purpose of Rocket''s ''Form'' type in handling input?', N'Senior', N'The Form type provides automatic, type-safe deserialization of form-encoded data into structured Rust objects. It combines input retrieval and validation, ensuring that if a handler is invoked, the input data is guaranteed to be well-formed according to the struct definition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a221ad1-9f5a-4210-af0b-5494697c3b9a', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus handle dependency injection differently than Spring?', N'Middle', N'Quarkus uses ArC, a CDI-compliant dependency injection framework designed specifically for build-time resolution. Unlike Spring, which performs most dependency scanning and wiring at runtime, ArC resolves almost all beans at build time, improving startup performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e6e319d-e675-4dde-b374-549504476381', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the significance of the ''connectedCallback'' and ''disconnectedCallback'' hooks?', N'Middle', N'These lifecycle methods manage the component''s attachment to the DOM document. They are essential for resource management, such as adding or removing global event listeners, timers, or network subscriptions to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7162024-79b5-4b13-a2f5-5496194e3238', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the advantages of using TTL (Time to Live) in DynamoDB?', N'Middle', N'TTL automatically deletes expired items from the table without consuming provisioned throughput. This is useful for managing session data, event logs, or temporary caches, reducing costs and manual maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb3b8cc9-e944-4a39-8643-54969b8cbcca', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Compare Lit''s event delegation approach to standard DOM event bubbling.', N'Senior', N'Lit leverages standard browser event bubbling for interaction, but provides decorators to bind events directly to component methods. This makes managing complex event listeners more declarative and easier to clean up during component destruction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'628bc937-0579-490c-b0ab-5498f7f119ba', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the primary trade-off between Write-Through and Write-Back caching strategies?', N'Middle', N'Write-Through ensures strong data consistency by updating the cache and database simultaneously, but it increases write latency. Write-Back improves performance by writing to the cache first and syncing to the database asynchronously, but it risks data loss if the cache node fails before the sync.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'064fd59c-60fd-4883-b4da-549c331371f7', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle component lifecycles?', N'Fresher', N'SolidJS uses a simpler lifecycle model than frameworks like React. Because components are only executed once, you generally use primitives like onMount for initialization or onCleanup for teardown logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78f14109-c102-4f6f-ae06-549de49e85be', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Explain the role of ''Payload Extraction'' in Nuxt''s SSG (Static Site Generation) mode.', N'Senior', N'Payload extraction allows Nuxt to generate both the static HTML and a corresponding JSON payload for each page. When navigating between pages in the browser, Nuxt fetches only the JSON payload, effectively turning the static site into a fast SPA without needing to re-fetch full HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa18700d-b9c1-4955-9c3d-549e5b3c6a1f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do ''indexed access types'' help in maintaining DRY principles?', N'Senior', N'Indexed access types allow you to look up a property type from another type, ensuring that changes to the base type automatically propagate. This avoids manual duplication of types and reduces the risk of out-of-sync type definitions when the data structure evolves.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f5ae9cb-d422-4b60-83d3-54a0ef90c46a', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How can you prevent a ''cascading failure'' in a microservices architecture?', N'Middle', N'Cascading failures can be mitigated by implementing timeouts, retries with exponential backoff, and circuit breakers. Additionally, using bulkhead patterns to isolate resources ensures that a failure in one area does not consume the resources needed for the rest of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13324044-2df0-4ad5-9cf6-54a132d9f9ad', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you design a rate-limiting strategy that balances service protection with multi-tenant fairness?', N'Senior', N'A robust strategy uses a token bucket or leaky bucket algorithm applied via a distributed cache like Redis to track usage across instances. To ensure fairness, implement tiered rate limits based on client identity or subscription levels, and return standard status codes to signal throttling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
