INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e81ac6e7-39c5-49ee-a5db-54a41201960f', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin optimize memory allocation for JSON serialization?', N'Middle', N'Gin utilizes the standard library''s encoding/json by default but allows for the integration of faster third-party encoders like jsoniter. It minimizes unnecessary allocations by reusing buffers and context objects throughout the request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f258054-35a1-4afb-b532-54a5b564c101', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the significance of alignment in C++ structures and how does it affect memory layout?', N'Senior', N'Alignment ensures that data members are placed at memory addresses that are multiples of their size, optimizing hardware access speed. The compiler inserts padding between members to satisfy these requirements, which increases the total size of the structure and must be considered when designing memory-constrained systems or binary file formats.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c8cc3cb-0b40-4881-9ec0-54a746d7406b', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js differ from jQuery?', N'Fresher', N'Unlike jQuery, which is an imperative library focused on DOM manipulation, Alpine.js is a declarative framework focused on state management. In Alpine, you update the data, and the framework automatically updates the DOM for you.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8331ba32-12bb-4fd6-8ba1-54a7d1701a61', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Discuss the challenges of cache invalidation in a multi-region distributed system.', N'Senior', N'Maintaining cache consistency across regions involves significant network latency and potential race conditions during propagation. Architects often trade off strict consistency for eventual consistency, using mechanisms like TTLs, versioning, or pub/sub invalidation buses to manage the state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e964aa45-73f6-4f8a-909a-54a92e8e6971', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle static assets like images?', N'Intern', N'Vite treats static assets as modules. When you import an image file in your JavaScript, Vite returns the public URL of that asset, which can then be used in your components or templates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8fe9ea6-0047-41f3-a0b4-54a93367e96e', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the different phases of component lifecycle?', N'Fresher', N'The component lifecycle has three distinct lifecycle phases: 1. Mounting: The component is ready to mount in the browser DOM. This phase covers initialization from constructor(), getDerivedStateFromProps(), render(), and componentDidMount() lifecycle methods. 2. Updating: In this phase, the component gets updated in two ways, sending the new props and updating the state either from setState() or forceUpdate(). This phase covers getDerivedStateFromProps(), shouldComponentUpdate(), render(), getSnapshotBeforeUpdate() and componentDidUpdate() lifecycle methods. 3. Unmounting: In this last phase, the component is not needed and gets unmounted from the browser DOM. This phase includes componentWillUnmount() lifecycle method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ae843c8-0866-477d-8847-54a9aad01676', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the role of reactive declarations in Svelte, and how do they function?', N'Middle', N'Reactive declarations, defined using the syntax, automatically re-run whenever the variables they depend on change. They function as an efficient alternative to computed properties or memoized hooks in other frameworks, ensuring that derived state is always kept in sync.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e658c75-e26c-48e0-87f5-54b3a3f7463e', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the architectural implications of using custom allocators in C++ containers?', N'Senior', N'Custom allocators allow developers to control how memory is allocated and deallocated, enabling optimizations such as arena allocation, object pooling, or tracking memory usage. This is essential in real-time systems or high-performance applications where standard heap allocation is either too slow or prone to fragmentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
