INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40ad606e-c67d-4e2c-a7a0-54ca3e67f388', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How do secondary indexes impact performance in a distributed database?', N'Senior', N'Secondary indexes in Cassandra are local to each node, meaning a query against an indexed value often requires a scatter-gather operation across the entire cluster. This can cause significant latency and performance degradation, making them unsuitable for high-cardinality data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
