INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95663a18-ad07-4ded-80f1-54d453d94d9e', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Explain the trade-off between ''Size Tiered'' and ''Leveled'' compaction strategies.', N'Senior', N'Size Tiered Compaction is write-optimized and triggers when files reach similar sizes, making it ideal for write-heavy workloads. Leveled Compaction organizes data into fixed-size levels to minimize read amplification, making it more suitable for read-heavy workloads at the expense of higher write overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef3236ad-314f-426e-8937-54d4a1a78583', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the difference between immutable and read-only collections?', N'Junior', N'In Kotlin, read-only collections are views of a collection that do not expose methods to modify the contents, but the underlying collection might still be mutable. True immutable collections are completely unchangeable, ensuring thread safety and preventing accidental modifications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f360a32-8904-4eb2-a1d7-54d4c0a094d3', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why is the order of member initialization in a constructor list important?', N'Middle', N'Members are initialized in the order they are declared in the class definition, regardless of the order in the initializer list. Misaligning these can lead to undefined behavior if a member is initialized using the value of another member that has not yet been constructed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
