INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8d9738b-8b9c-4a4d-bbee-54dd354b0e6c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is function composition and how do compose and pipe work?', N'Intern', N'Function composition is the mathematical concept of chaining functions such that the output of one becomes the input of the next: (f ∘ g)(x) = f(g(x)). In JavaScript this is implemented with two conventions: - compose(f, g, h) — applies right-to-left: f(g(h(x))) (mathematical convention) - pipe(f, g, h) — applies left-to-right: h(g(f(x))) (more readable for imperative programmers) Both require unary functions (single argument) for clean composition. Multi-argument functions must be curried first. Example: Real-World Use Case: Redux middleware (applyMiddleware) and compose utility implement pipeline composition — compose(logger, thunk, devTools)(createStore) stacks middlewares right-to-left.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bd2ffe4-b127-43d1-b81e-54dd73c714e7', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is ''Tail Call'' optimization, and does the C# compiler support it?', N'Senior', N'Tail call optimization allows the runtime to reuse the current stack frame for a function call if it is the very last operation performed. While the C# compiler emits the ''tail'' IL prefix, the JIT compiler only applies this optimization in specific scenarios, primarily on 64-bit platforms, due to security and stack-trace complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24937b0e-ceb7-4a27-8963-54ddccb31879', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What are the trade-offs of using a framework like Chi versus a more ''batteries-included'' framework like Gin or Echo?', N'Middle', N'Chi is designed to be a minimalist router that strictly adheres to the standard library''s net/http interface, offering high compatibility and control. Frameworks like Gin or Echo often include built-in features like validation and JSON binding, which trade off some simplicity and standard library adherence for increased developer velocity in early project stages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c3d5d2f-df13-4029-a314-54e092e21efa', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you ensure the security of an API that handles sensitive user information?', N'Middle', N'I implement defense-in-depth by enforcing strict authentication and authorization protocols like OAuth2.0 and JWT. I ensure all data is encrypted both in transit using TLS and at rest, while applying input validation and rate limiting to prevent common attacks like injection or brute-forcing. Regular security audits and dependency scanning are also essential parts of the process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
