INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4312c7d8-3324-49ff-9dbb-54e2f916707c', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are the trade-offs of using lazy evaluation in function arguments?', N'Middle', N'Lazy evaluation allows arguments to be computed only when they are actually accessed, which can save resources if an argument is not needed. However, it can lead to confusing debugging scenarios if variable values change before the argument is evaluated, or if side effects are expected to occur immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c655435c-cb44-4d15-8c48-54e3351ffbce', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How can you validate user input in Echo?', N'Fresher', N'Echo supports custom validator interfaces that can be registered with the framework. Once configured, you can call the validate method on the context to ensure the bound data meets your business rules before processing it in the handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07f1646c-9e93-4948-b3be-54e36c7e879e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the two types of loops in javascript', N'Intern', N'1. Entry Controlled loops: In this kind of loop type, the test condition is tested before entering the loop body. For example, For Loop and While Loop comes under this category. 2. Exit Controlled Loops: In this kind of loop type, the test condition is tested or evaluated at the end of the loop body. i.e, the loop body will execute at least once irrespective of test condition true or false. For example, do-while loop comes under this category.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fc77af4-dfed-49eb-baa4-54e383203a86', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the difference between horizontal and vertical scaling in system architecture?', N'Senior', N'Vertical scaling increases the resources of a single node, which is simpler to implement but hits hard physical limits. Horizontal scaling adds more nodes to the system, offering theoretically infinite capacity but requiring complex load balancing, state management, and data partitioning strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dae8f91a-1c01-4f84-99c8-54e3b6dd0655', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Why is the asyncData hook specific to page components in Nuxt?', N'Middle', N'The asyncData hook is designed to fetch data before the component is initialized, ensuring that the necessary data is available for server-side rendering. By restricting it to page components, Nuxt can effectively manage the data fetching lifecycle during route transitions and server-side request processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f5d7b17-2759-4de1-9fc0-54e691304b7f', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the wild card route?', N'Intern', N'The wildcard route in Angular, represented by the path , is a special route that the Angular router uses as a fallback. It matches any URL that doesn''t match any of the previously defined routes in your application''s routing configuration. Its primary purpose is to handle unknown or invalid URLs, typically by redirecting the user to a 404 "Page Not Found" page or sometimes back to the application''s home page. It must always be the _last_ route defined in your routes array so that the router checks all specific routes first before falling back to the wildcard. > Try out Angular coding questions on GreatFrontEnd. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad1a67bd-daa1-48d8-bd3e-54e70d5d67ef', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How do you define path parameters in Echo?', N'Intern', N'Path parameters are defined by using a colon followed by the parameter name in the route string, such as /users/:id. Echo then allows you to retrieve the value of this parameter using the context object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a62db8ca-2cae-48f7-8810-54ed8906a296', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Compare the performance impacts of using ''nested'' objects versus ''parent-child'' relationships.', N'Senior', N'Nested objects store child documents within the same Lucene document, which is faster for queries but costly to update because the entire document must be reindexed. Parent-child relationships store documents in separate indices, allowing for independent updates at the cost of significantly higher memory and CPU overhead during join operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf8f4407-9e8a-42ee-9847-54f1184b53d4', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Explain the concept of ''undefined behavior'' in the C standard and its impact on compiler design.', N'Senior', N'Undefined behavior describes scenarios where the C standard imposes no requirements on the implementation, allowing compilers to assume the condition never occurs. This enables aggressive optimizations, such as removing code paths that theoretically trigger undefined behavior, but it places the burden of correctness entirely on the developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afcbc966-fb93-4469-8361-54f177623da7', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the difference between synchronous and asynchronous database drivers in FastAPI?', N'Middle', N'Synchronous drivers block the entire event loop while waiting for a database response, which defeats the purpose of an async framework. Asynchronous drivers, such as those used with SQLAlchemy''s async engine, allow the application to handle other incoming requests while waiting for the database, maximizing overall throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b45e488-af33-4c53-9a00-54f450e6eb18', N'4c000000-0000-0000-0000-000000000005', N'Why is ''Denormalization'' often necessary in NoSQL systems?', N'Senior', N'In distributed systems, joins are prohibitively expensive due to network latency and data distribution. Denormalization stores related data together in a single record, optimizing for read performance by reducing the number of lookups required to satisfy a request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af234c42-b7b3-4428-a523-54f8023bd90c', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut achieve fast startup time compared to other frameworks?', N'Intern', N'Micronaut achieves fast startup by using ahead-of-time compilation for dependency injection, rather than performing reflection at runtime. This allows the framework to determine bean dependencies during the build process instead of during application startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea28d8be-3e03-4fac-9525-54f9268d1206', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does ''at-least-once'' delivery guarantee affect system architecture?', N'Middle', N'At-least-once delivery ensures no message is lost, but it introduces the risk of duplicate processing. Systems must implement idempotency logic in the consumer layer to ensure that processing the same message multiple times does not result in incorrect state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fff4ae6c-48ff-45c0-830e-54fcb112baca', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Explain the benefit of Micronaut’s ''Client-Side Load Balancing'' for microservices architectures.', N'Senior', N'Micronaut provides integrated, native support for client-side load balancing, which removes the need for an external sidecar proxy like Envoy in simple deployments. This reduces network hops and infrastructure complexity by allowing the service client to query discovery services directly and route requests efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcc81a12-f550-420e-8f11-54fcbc8fa295', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the Symfony Profiler?', N'Intern', N'The Profiler is a development tool that collects and displays detailed information about the execution of a request. It provides insights into database queries, memory usage, template rendering, and event execution, which is essential for debugging and performance optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8316f8c2-8b34-4303-ad98-550180e47e54', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How do you implement a secure and scalable authentication strategy in a Nuxt application?', N'Senior', N'A secure strategy involves using HttpOnly cookies to store session tokens to prevent XSS-based theft, combined with server-side middleware to validate session integrity on every request. This ensures that sensitive tokens are never exposed to client-side JavaScript, maintaining a robust security boundary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76048875-6083-47c9-9698-5501c715a1da', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How do you define a dynamic path variable in a REST endpoint?', N'Junior', N'You use the @PathVariable annotation within the mapping method signature. By placing a placeholder like {id} in the mapping URL, Spring maps the value provided in the request URL directly to the corresponding method parameter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2274b27-f5b4-4fd4-bcfe-5501ec9ea726', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is service discovery in a dynamic environment?', N'Middle', N'Service discovery is a mechanism where services automatically register their network locations with a central registry. This allows other services to locate them dynamically, which is essential in cloud environments where instances are frequently created and destroyed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6927ab8-d67a-4802-856f-550301b6080d', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Why is the Database-per-Service pattern considered a best practice in microservices?', N'Senior', N'This pattern ensures loose coupling by preventing services from sharing a database schema, which would create hidden dependencies. It enforces service autonomy, allowing each team to choose the optimal database technology and schema for their specific domain requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23ff33ad-1489-47ef-a0c4-550377e66d8b', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus handle transaction management in a reactive environment?', N'Senior', N'Quarkus uses the Narayana transaction manager, which has been adapted for reactive streams. It ensures ACID compliance across distributed services and supports the JTA (Java Transaction API) specification, even when interacting with asynchronous databases or message brokers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e60068c-3054-4b6c-92f8-5504d6afea42', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django handle database connection pooling, and why is it often necessary to use external tools?', N'Senior', N'Django opens a new connection per request and closes it at the end by default. For high-traffic applications, this introduces significant overhead, so developers often use external tools like PgBouncer to pool connections and reduce the latency associated with TCP handshakes and database authentication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43dedaf8-1190-42a0-a03d-550607368f10', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When justifying an infrastructure upgrade, how do you estimate the ROI for the engineering organization?', N'Senior', N'I quantify the current ''tax'' paid in terms of manual operational labor, system downtime incidents, and slow development velocity caused by the current infrastructure. I compare this to the projected reduction in these costs and the potential for increased revenue due to better system reliability, creating a clear business case for the investment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd32f01ff-6097-4ef9-8ecb-550e08592919', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the ''visibility map'' and how does it optimize index-only scans?', N'Senior', N'The visibility map tracks which pages contain only tuples visible to all active transactions. During an index-only scan, PostgreSQL checks this map to determine if it can return data directly from the index without needing to fetch the corresponding heap page, significantly reducing disk I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0224450a-c925-4879-b364-550f576b4f8f', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain how to design an immutable infrastructure to improve security posture.', N'Senior', N'Immutable infrastructure involves deploying pre-hardened, read-only images that are never modified in place after deployment. If a configuration change or security update is needed, a new image is built and deployed, which eliminates configuration drift and makes it significantly harder for attackers to establish persistence on a host.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59c5682e-e71d-4565-b635-550f6152a00c', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is a ''middleware stack''?', N'Intern', N'A middleware stack is the sequence of middleware functions that a request passes through from the moment it enters the application until a response is sent. Each function in the stack performs its task and then passes control to the next function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8e1449b-7f97-490d-b7a7-5510bb8637cc', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Why is containerization often paired with microservices?', N'Middle', N'Containers provide a consistent, isolated environment for each microservice, ensuring that it runs the same way regardless of the host machine. This portability simplifies deployment, scaling, and the management of dependencies across diverse development and production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03eb083e-f45b-4878-9fd1-551210cd4dc5', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If a user reports an error that you cannot see in your internal logs, what could be the problem?', N'Junior', N'It is possible the error is occurring on the client side, such as a browser-specific issue or a network failure that never reaches the server. I would ask the user for their browser console logs or network trace to see if the request was blocked before it even hit our infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cac6077d-0a84-49fb-b27b-55123f8f1a00', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What are the trade-offs of using synchronous versus asynchronous communication between services?', N'Middle', N'Synchronous communication is easier to implement and provides immediate feedback but tightly couples services and creates a single point of failure. Asynchronous communication decouples services and improves system resilience and throughput, but introduces complexity in tracking request state and managing eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e19ad9be-1f1b-4c73-aa0b-551548e7584a', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using a local database or a cloud-based storage service for a small application?', N'Fresher', N'A local database is simpler and free to start, making it ideal for prototypes or single-user tools. A cloud-based service is better if you need the application to be accessible from multiple locations or if you want to offload the burden of data backups and maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8350e9d0-fd70-48a2-b0bc-55161fa32404', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber manage request timeouts compared to the standard library?', N'Senior', N'Fiber leverages Fasthttp''s configuration settings to enforce read and write timeouts at the connection level, which is more efficient than the net/http approach of managing timeouts per request. This provides a global safety net against slow-loris attacks and stalled clients.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33807274-a79c-4439-852a-55178d51c739', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the primary role of the Tower library in the Axum ecosystem?', N'Middle', N'Tower provides the foundational abstraction for modular, reusable network services. Axum leverages these abstractions to implement its middleware stack, allowing developers to compose request handling logic through a unified interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
