INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2169510-82ef-4838-a9a5-551ee1f97994', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between a class method and an instance method in a model?', N'Junior', N'An instance method is called on a specific object and operates on its attributes, representing behavior of a single record. A class method is called on the class itself and usually performs operations related to the entire collection of records, such as searching or filtering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'662e2f83-2060-4868-bb5e-551f54e67ab3', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS differ from React regarding component rendering?', N'Intern', N'In React, component functions re-execute whenever state changes to generate a new Virtual DOM tree. In SolidJS, component functions run only once during initialization, and the individual reactive parts update independently thereafter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
