INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e244c9bc-c06d-4d60-8142-554171c187f2', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the function of the @property decorator in Lit?', N'Junior', N'The @property decorator declares a reactive property on a component. When the value of a property decorated this way changes, Lit automatically triggers a re-render of the component to reflect the new state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1423f46-b24b-4710-a358-55475e84e477', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Is Redis a relational database management system?', N'Intern', N'No, Redis is not a relational database, meaning it does not use tables, rows, or columns, and it does not support SQL. It is classified as a NoSQL database because it uses a more flexible, non-relational model for storing data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b74b6c30-1143-4fd6-bb6e-55483feb665f', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do Python generators differ from standard functions, and what are their primary advantages regarding memory management?', N'Middle', N'Generators use the yield keyword to return values one at a time, pausing their execution state between each call rather than computing all values and storing them in memory at once. This lazy evaluation is highly advantageous when processing large datasets because it maintains a minimal memory footprint. Unlike standard functions that return the entire result set, generators allow for infinite data streams and efficient memory usage in iterative operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b006d909-68ed-4c45-aa31-5548b51d856b', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Explain the difference between a Unique Index and a Primary Key.', N'Middle', N'A primary key is a logical constraint that uniquely identifies a row and implicitly creates a unique index; it also forbids null values. A unique index ensures all values in a column are distinct, but it can typically allow one or more null values depending on the database engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd64e3583-ee63-4f32-8746-554ba446f0fe', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How do distributed consensus algorithms like Paxos or Raft ensure data consistency in a partitioned network?', N'Senior', N'These algorithms allow nodes to agree on a sequence of operations even if some nodes fail or the network is partitioned. By requiring a quorum of nodes to commit a state change, the system maintains consistency by ensuring that only one version of the truth is accepted by the majority.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bd0fdea-9988-4b05-be15-554f585e2ffc', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus ensure thread safety in a reactive environment?', N'Middle', N'Quarkus encourages the use of event loops and non-blocking code, which helps avoid issues related to thread contention and synchronization. By utilizing reactive streams and asynchronous processing, it limits the need for shared state across threads, which inherently reduces thread-safety risks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66ecf1cf-9f88-4b28-b3e5-5550abc293a6', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is event capturing?', N'Intern', N'Event capturing is a type of event propagation where the event is first captured by the outermost element and then successively triggers on the descendants (children) of the target element in the same nesting hierarchy till it reaches the inner DOM element. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cb470be-4b17-4dec-8db2-5554bda1ff0b', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the ''Lost Update'' problem and how can it be mitigated?', N'Middle', N'The lost update problem occurs when two transactions read the same data, calculate new values, and then update the row, causing the first update to be overwritten. It can be mitigated by using atomic operations, database-level row locking, or optimistic concurrency control with version tracking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6e1f991-30e0-49cf-a719-55554f6490d9', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are the trade-offs of using ''LiveView'' for high-frequency data updates compared to a traditional React/Vue SPA?', N'Senior', N'LiveView minimizes the need for client-side state synchronization and avoids the ''API-to-frontend'' orchestration layer, simplifying development and reducing data transfer. However, it requires a persistent socket connection for every user, which can increase server memory usage and latency sensitivity compared to static SPAs that offload computation to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55246b5f-0c8f-4009-bb43-5555cd82ca0f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does JavaScript handle concurrency despite being single-threaded?', N'Middle', N'JavaScript achieves concurrency by offloading non-blocking operations to the underlying runtime environment, such as Web APIs or the libuv library in Node.js. Once these operations complete, the results are queued, and the event loop coordinates their execution back onto the main thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'872d8c1f-33dd-4ece-9c08-5556eb48f81b', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the purpose of a ''spike'' in software development estimation?', N'Junior', N'A spike is a time-boxed research task used to investigate an unknown or reduce uncertainty before committing to a full estimate. It allows the team to gather enough information to make a reliable decision without spending too much time on a potentially wrong path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b31b981-6523-479e-acd0-555d64531a5d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you use javascript libraries in typescript file', N'Fresher', N'It is known that not all JavaScript libraries or frameworks have TypeScript declaration files. But if you still want to use libraries or frameworks in your TypeScript files without getting compilation errors, the only solution is declare keyword along with a variable declaration. For example, let''s imagine you have a library called customLibrary that doesn’t have a TypeScript declaration and have a namespace called customLibrary in the global namespace. You can use this library in typescript code as below, In the runtime, typescript will provide the type to the customLibrary variable as any type. The another alternative without using declare keyword is below', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83a80c93-b5e8-40c3-83e7-555f04a5463f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are replaceAll(), padStart() and padEnd() string methods?', N'Intern', N'1. String.prototype.replaceAll(): The replaceAll() method returns a new string with all matches of a pattern replaced by a replacement. Unlike replace(), it replaces every occurrence without needing a global regex flag. 2. String.prototype.padStart(): The padStart() method pads the current string with another string from the start until it reaches the given length. 3. String.prototype.padEnd(): The padEnd() method pads the current string with another string from the end until it reaches the given length.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccd51bc0-6dc7-4483-9f38-5560c663c0e4', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does the ''by'' keyword function in delegated properties?', N'Middle', N'The ''by'' keyword delegates the getter and setter logic of a property to an external object that implements specific ''getValue'' and ''setValue'' methods. This is a powerful way to implement reusable logic like lazy loading, observable properties, or reading values from a map.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa62391e-4c6f-434a-a007-556123bdb3b8', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite optimize the delivery of large vendor bundles in production?', N'Senior', N'Vite leverages Rollup''s manualChunks configuration to split large third-party dependencies into separate vendor files. This improves caching efficiency, as vendor code typically changes less frequently than application-specific business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c83c6e1a-a30c-4368-8b04-556271ac7edc', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the advantage of using ''context'' in Go applications?', N'Middle', N'The context package provides a standardized way to pass deadlines, cancellation signals, and request-scoped values across API boundaries and goroutines. It is essential for preventing resource leaks and ensuring that long-running operations are terminated gracefully when no longer needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9784ecd8-29d1-44ec-8a62-556322b3324c', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What does ''Imperative'' mean in the context of Quarkus web services?', N'Intern', N'Imperative refers to the traditional synchronous programming model where each request is handled by a dedicated thread. In Quarkus, this is the standard way to write code, which is intuitive and easy to debug for most developers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37b99ec8-1949-466a-825f-55641949504c', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is it dangerous to use type assertions (''as'') frequently in a large application?', N'Senior', N'Type assertions bypass the compiler''s safety checks and tell it to trust the developer''s manual type definition. Excessive use undermines the benefits of using TypeScript, as it can hide underlying bugs that would have been caught by the type checker during compilation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b8f7595-2fa8-47c0-a89c-556669b2494b', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Discuss the impact of ''Island Architecture'' within the Nuxt ecosystem.', N'Senior', N'Islands architecture allows developers to isolate specific interactive parts of a page as independent components, while the rest remains static. This significantly reduces the total amount of hydration required, leading to better performance on low-power devices and faster overall page load times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f4a9172-2a6e-4680-9ae4-55667788c662', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How do you log information in a Fastify application?', N'Junior', N'Fastify comes with a built-in logger based on the Pino library. You can access this logger from the Fastify instance, request object, or reply object to log events with high performance and low overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d836cce-962e-4f4f-9ac2-5566a9253010', N'a2838158-7305-480a-b22b-4dc35776b400', N'Explain the CAP theorem and its practical implications for distributed systems.', N'Middle', N'The CAP theorem states that a distributed system can only guarantee two out of three properties: Consistency, Availability, and Partition Tolerance. Since network partitions are inevitable in distributed systems, architects must choose between prioritizing strong consistency or high availability during a partition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ccf1c7f-55a4-4d81-933f-5566f4fc5cff', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'When should you use the ''app.use'' versus ''app.get'' (or other methods) in Hono?', N'Middle', N'Use ''app.use'' for global or route-group middleware that should run regardless of the HTTP method, such as logging or CORS. Use specific methods like ''app.get'' or ''app.post'' to define logic that should only execute for that specific request method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6f690de-04c8-4968-92ef-556942e17a34', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you design a retry policy for an unreliable third-party API?', N'Middle', N'I would implement retries with exponential backoff and jitter to prevent overwhelming the downstream service during a recovery phase. It is also important to limit the maximum number of retries and use a dedicated bulkhead to prevent these retries from consuming all available threads in the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'981ffe9b-ce23-4254-993e-55697c7a3631', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How do you handle secrets like database passwords in Django?', N'Junior', N'Sensitive information should be stored in environment variables rather than hardcoded in the settings.py file. This keeps passwords and API keys out of version control systems like Git.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd96fb9d3-079f-41db-8ff8-5569c8030f91', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the defer statement?', N'Intern', N'The defer statement schedules a function call to run immediately before the surrounding function returns. It is commonly used for cleanup tasks like closing files or releasing network connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'573f6bf7-b8a9-4234-a28d-556e245daa12', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a transaction isolation level, and why does PostgreSQL default to Read Committed?', N'Middle', N'Isolation levels define how changes made by one transaction are visible to others. Read Committed is the default because it balances high concurrency with a reasonable consistency model, preventing dirty reads while avoiding the significant performance overhead associated with stricter levels like Serializable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0541b2ff-4731-4278-8239-556fa08ad390', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'In Swift, how are switch statements more powerful compared to other languages?', N'Middle', N'Swift takes the typical switch statement to a new level by allowing for rich pattern-matching and asserting complex conditions in each case. Several unique features make Swift''s switch statement stand out: Enhanced Pattern Matching - Value Binding: Extracts and assigns associated values or collection elements for later use. - Case Matching: Handles a wide range of cases, including tuple, range, and type matching. - Where Clauses: Allows custom conditions for case selection. Exhaustiveness and Unreachability Swift enforces that _enum cases_ are fully handled in a switch statement. It flags any incomplete coverage as a compile-time error. This prevents against unintentional bugs arising from missing case handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98e271c6-d862-4082-9523-5571a4283a48', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP handle memory management?', N'Fresher', N'PHP uses a reference counting mechanism for memory management. When a variable''s reference count reaches zero, the memory is automatically freed by the engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'194d09b8-0c49-4936-9fb3-5572e9e4b939', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the purpose of ''Respond'' trait in Actix-web?', N'Middle', N'The Responder trait defines how a type can be converted into an HTTP response. By implementing this trait for custom types, developers can easily return complex objects or errors from handlers as standard JSON or other formats.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1466e21d-3e5a-4162-ab0b-55730bfa68b3', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit facilitate server-side rendering (SSR) and hydration?', N'Senior', N'Lit supports SSR by rendering templates to static HTML strings that include Declarative Shadow DOM, allowing the browser to render the structure before the JavaScript loads. Hydration then attaches the Lit component lifecycle to these pre-rendered elements to restore interactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8d906b4-aa2c-435f-af05-5574c24407e7', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How do ''Reactive Streams'' (Project Reactor) improve scalability compared to traditional thread-per-request models?', N'Senior', N'Reactive Streams implement non-blocking backpressure, allowing producers to signal their pace to consumers to prevent resource overload. This allows the application to handle significantly more concurrent connections using a fixed number of threads, as threads are not blocked waiting for I/O operations to complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58e8f28e-ee98-4612-a186-557980a92fec', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What are the performance implications of using JSON serialization in Axum handlers?', N'Middle', N'Serialization/deserialization is CPU-intensive and can become a bottleneck under high load. Using high-performance libraries like Serde with optimized configuration is essential, and offloading heavy processing to background tasks can help maintain low response latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f87fdd8-1e78-4892-bae3-55798d886bb0', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle data loading states during navigation?', N'Intern', N'Remix tracks the state of data fetching automatically using a hook that provides information about whether a navigation or submission is currently in progress. This allows developers to easily show loading indicators to the user without managing complex state variables manually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb45d78a-e867-495f-a9e8-5579dc882764', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What happens when you exceed your provisioned throughput?', N'Junior', N'DynamoDB will throttle your requests, returning an error message to the application. You should implement retry logic with exponential backoff to handle these temporary rate limits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf03a3ac-c1e7-4a5e-a15e-557b12da082c', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How would you handle a scenario where a third-party API dependency becomes unreliable?', N'Senior', N'Implement defensive programming patterns such as circuit breakers and fallbacks to prevent the dependency from exhausting local system resources. Introduce caching layers to serve stale data and utilize message queues to decouple the dependency from the critical request path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60a80b41-5fa2-464e-abd9-557b6e84ddf9', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Can Vite be used to develop multiple pages (Multi-Page Apps)?', N'Junior', N'Yes, Vite supports multi-page applications by allowing you to specify multiple entry HTML files in the build configuration. This lets you build complex projects with several distinct HTML pages while still benefiting from Vite''s optimization features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1da2d07-1823-4804-bdd2-557f98ae26a1', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum ensure type-safe JSON serialization and deserialization?', N'Middle', N'Axum integrates with the ''serde'' library, requiring that request and response models implement serializable traits. This ensures that any data entering or leaving the application is validated against the defined schema, reducing runtime errors caused by malformed JSON.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2768df68-a8fa-458b-82b1-558077b81b38', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What are the primary factors that determine the ''relevance'' of a document in a search result?', N'Senior', N'Relevance is determined by the similarity algorithm, typically BM25, which calculates scores based on term frequency (how often a term appears in a document) and inverse document frequency (how rare the term is across the entire index). These factors are combined to weight the importance of matches within specific fields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a5bfe1a-f45e-4a17-a4e3-55820a0c1146', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the browser''s ''style invalidation'' process?', N'Senior', N'Style invalidation occurs when the DOM changes, forcing the browser to mark affected elements as needing a style recalculation. Browsers attempt to optimize this by only recalculating the subtrees that are impacted, rather than the entire document, whenever possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d49a2b1-2aad-49df-86e3-558238006a8b', N'954a0331-deff-4399-b588-96f39fec001d', N'What is Renderer2 and why would you use it?', N'Intern', N'Renderer2 is an Angular service that provides an abstraction layer over the DOM manipulation API. You use it to safely interact with the DOM or other rendering environments (like server-side rendering or web workers) without directly accessing the native elements via ElementRef.nativeElement. Using Renderer2 is preferred over direct DOM manipulation because: - It makes your application compatible with server-side rendering (SSR) and web workers, where the native DOM might not exist. - It provides a layer of security by sanitizing values when setting properties or attributes. - It abstracts away platform-specific details, making your code more portable. Common methods include createElement, appendChild, setProperty, setAttribute, addClass, removeClass, setStyle, and listen.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67a6046c-f8ef-402d-b21d-55857431f714', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala''s implicit resolution mechanism impact compilation time and system maintainability?', N'Senior', N'Implicit resolution forces the compiler to search the lexical scope and companion objects, which can significantly increase compilation times as project complexity grows. From a maintainability perspective, it creates ''magic'' dependencies that can be difficult to debug, necessitating strict conventions to ensure code readability and predictability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd48f2d5e-c038-4904-adb2-558765e41229', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the primary security benefit of using an API Gateway?', N'Middle', N'An API Gateway acts as a centralized entry point that enforces security policies such as rate limiting, authentication, and SSL termination. By offloading these tasks from backend services, it ensures consistent security enforcement and reduces the attack surface of individual services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
