INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a093a0e0-fccc-4c47-8813-558e8c7e7527', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a ''buffer cache hit'' and a ''disk read'' in query execution?', N'Senior', N'A buffer cache hit occurs when the required data page is already in memory, enabling near-instant access. A disk read occurs when the page is not in memory, necessitating a high-latency I/O operation, which is the primary bottleneck for most database queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a0e69b9-d7b6-450e-bc63-5592581083c8', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the performance implications of ''Binary'' vs ''String'' handling in Elixir/Phoenix when dealing with large payloads.', N'Senior', N'In Elixir, strings are UTF-8 encoded binaries; however, large binaries are stored in a special heap area and shared between processes, which is highly efficient. When passing large data, the VM avoids copying the binary, instead passing a reference, which significantly reduces overhead compared to languages that perform deep copies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03e09e00-5aad-462f-9e99-5592d761057a', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the architectural difference between ''Parallel Routes'' and ''Intercepting Routes'' in Next.js?', N'Senior', N'Parallel routes allow you to render multiple pages simultaneously within the same layout, while intercepting routes allow you to load a route from another part of the app within the current layout. These patterns are essential for building complex UI like modals or dashboards without full page reloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59e3816c-5876-4e79-94ce-5597a9a3dde5', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the primary purpose of Vite in frontend development?', N'Intern', N'Vite is a build tool designed to provide a faster and leaner development experience for modern web projects. It leverages native browser ES modules to serve code instantly during development, significantly reducing startup time compared to traditional bundlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f091c166-b8d8-44ff-958f-5598129ad4da', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are the performance implications of using ''hasChanged'' for custom property validation?', N'Middle', N'The ''hasChanged'' function allows developers to skip the update cycle if the new value is considered identical to the old one, even if it is a different reference. This is a powerful performance optimization for complex objects or arrays where deep equality checks are needed to prevent redundant renders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd93653ec-2e8d-4d55-9fec-5598816a4396', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Does Dart use a garbage collector, and why is it important?', N'Intern', N'Yes, Dart uses an automatic garbage collector to manage memory. It is important because it automatically reclaims memory occupied by objects that are no longer in use, which helps prevent memory leaks and reduces the need for manual memory management by the developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3766d4a-45bf-4ba2-9449-55990fdfa1d2', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Why is it important to perform input validation on the server side even if client-side validation exists?', N'Middle', N'Client-side validation is primarily for user experience and can be easily bypassed by attackers using tools like proxy interceptors or direct API calls. Server-side validation is the final authoritative check that ensures only sanitized, expected data enters the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
