INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c6654fc-5e64-4c89-ac94-559bc7f37047', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s null safety impact runtime performance?', N'Middle', N'Null safety allows the compiler to make stronger assumptions about the types of variables, which can lead to smaller and faster machine code. By eliminating null reference errors at compile time, it reduces the need for defensive null checks at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d4f0cf8-c381-48bc-9118-559db608a608', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How does a database index improve query performance, and what is the trade-off?', N'Middle', N'An index is a data structure that provides a fast lookup path to specific rows in a table, significantly reducing the amount of data the database must scan. The primary trade-off is that indexes consume extra storage space and slow down write operations, as the index must be updated every time data is inserted, updated, or deleted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac981935-ec7c-4f0a-bd4e-559e31354a75', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind help in maintaining consistent spacing?', N'Junior', N'Tailwind uses a standardized spacing scale for properties like padding, margin, and gap. By using these predefined increments, developers avoid the inconsistency of choosing arbitrary pixel values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9271b59b-557c-4edd-a648-559e4605d510', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What are the trade-offs of choosing native compilation in Quarkus?', N'Middle', N'Native compilation yields near-instant startup and low memory usage, but it significantly increases build times and restricts the use of dynamic Java features like deep reflection and proxying. It also requires target-specific compilation, meaning you must build the binary for the specific OS you intend to deploy on.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fc2bcd2-9b99-4962-aad9-55a070ab7db9', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What role does idempotency play in the design of payment or financial APIs?', N'Senior', N'In financial APIs, idempotency is mandatory to prevent double-charging or duplicate transactions during network failures. By requiring clients to send a unique idempotency key, the server can safely retry operations without side effects, guaranteeing that a request is processed exactly once.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5366241-a3fb-4150-8eef-55a17e2c46ab', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the primary constraint when writing code inside a $ function?', N'Senior', N'Code inside a $ function must be serializable. This means you cannot rely on local closure variables that are not captured and serialized, and you must avoid using non-serializable objects like complex classes or internal browser state that cannot be reconstructed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a27dc2b6-ac65-4dbe-8552-55a2049ceac3', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle query parameters compared to path parameters?', N'Middle', N'Path parameters are defined in the route pattern using a colon prefix and accessed via the context, while query parameters are parsed from the raw URL string. Echo provides convenient helper methods to retrieve both types of parameters efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af31bdfa-fb5c-4f23-b8bc-55a5fbae421d', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Why does Kotlin use ''sealed classes'' instead of simple enums for state management?', N'Middle', N'Sealed classes allow for restricted hierarchies where each subclass can hold its own unique state and data, unlike enums which are limited to a single instance per type. This makes them ideal for representing complex states in finite state machines or exhaustive pattern matching with ''when'' expressions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1a55a91-5f50-4f20-b7c1-55a63d4f1690', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the concept of ''structural equality'' vs ''referential equality''.', N'Middle', N'Structural equality is checked using the ''=='' operator, which internally calls the equals method to compare the content of objects. Referential equality is checked using the ''==='' operator, which determines if two references point to the exact same object instance in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'241256c1-02bd-4e95-ac63-55a696630bde', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is an index in MySQL and why is it used?', N'Fresher', N'An index is a data structure that improves the speed of data retrieval operations on a table. It works like an index in a book, allowing the database to find specific rows without scanning the entire table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'965eb4d9-07b1-48d2-b8ee-55a86bfd3f48', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the purpose of ACID properties in a database transaction?', N'Junior', N'ACID properties ensure that database transactions are processed reliably. Atomicity guarantees that all parts of a transaction succeed or none do, Consistency ensures the database remains in a valid state, Isolation prevents concurrent transactions from interfering with each other, and Durability ensures that once a transaction is committed, it remains saved even in the event of a system failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bf2a0c7-2038-43e4-bbb0-55a90b1c1c41', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the benefit of using ''typedef''?', N'Junior', N'The ''typedef'' keyword creates a new name for an existing data type, which can make code more readable and easier to maintain. It is particularly useful for simplifying complex declarations, such as pointers to functions or long struct names. It does not create a new type but provides a meaningful alias.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'027fcd8b-d65b-4561-8115-55ab0d3d8c55', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the advantage of Remix''s data loading approach?', N'Junior', N'By loading data on the server, Remix avoids the ''waterfall'' effect where components fetch data sequentially in the browser. This results in faster initial page rendering and a better user experience, as the page is ready as soon as the HTML is received.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20ba8260-68b6-4837-8ac8-55ac454d24b5', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the ''deadlock_timeout'' configuration?', N'Senior', N'This setting dictates how long the system waits before checking for deadlocks after a lock request has been queued. A shorter time detects deadlocks faster, but constant deadlock checking consumes CPU resources, so it must be balanced based on the application''s contention patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
