INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c7f1620-b335-4585-a14c-55b56296f0d6', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit''s approach to error handling differ between server-side and client-side execution?', N'Senior', N'Server-side errors are caught by the framework and can be mapped to custom error pages or status codes, while client-side errors are managed via ''error boundaries'' or lifecycle events to prevent the entire app from crashing. This unified error handling ensures a graceful degradation of the user experience regardless of where the failure occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
