INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0acd86ff-e0ab-405c-905e-55c32e272ecf', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why would you choose NoSQL over a relational database for a specific project?', N'Junior', N'You would choose NoSQL when you need high horizontal scalability, flexible schemas, or low-latency performance for massive amounts of unstructured or semi-structured data. Relational databases are better for complex joins and strict data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24f6798c-35d6-415d-8f21-55c39afa8b76', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What does it mean for a C function to be recursive?', N'Junior', N'A recursive function is one that calls itself during its execution. Each call creates a new stack frame, and the process continues until a defined base condition is met to stop the recursion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c7efec1-7d9d-4d61-8942-55c3d7e8351c', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How can you implement rate limiting in a scalable way using Fastify?', N'Senior', N'You should use a plugin that integrates with a distributed store like Redis to track request counts across multiple server instances. Implementing it as a Fastify plugin ensures it is applied consistently across all routes and can be easily toggled per scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'905961ec-c3b7-40f4-b162-55c444914b91', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is an object initializer', N'Intern', N'An object initializer is an expression that describes the initialization of an Object. The syntax for this expression is represented as a comma-delimited list of zero or more pairs of property names and associated values of an object, enclosed in curly braces ({}). This is also known as literal notation. It is one of the ways to create an object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b1f885e-fbd1-4ca8-8f8b-55c54b440fe6', N'954a0331-deff-4399-b588-96f39fec001d', N'What are pipes and how is it used?', N'Intern', N'Pipes in Angular are a way to transform data for display directly within your templates. They take data as input and return transformed data as output, without changing the original data source. You use the pipe operator (|) in template expressions: Angular provides built-in pipes like DatePipe, CurrencyPipe, UpperCasePipe, JsonPipe, and AsyncPipe. You can also create custom pipes by implementing the PipeTransform interface and decorating the class with @Pipe. Pipes help keep your component logic clean by moving presentation logic to the template. > Try out Angular coding questions on GreatFrontEnd. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'264bb726-52a8-49fd-8326-55c56a67590a', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the primary benefit of using jQuery''s ''each'' method over a native array loop?', N'Middle', N'The jQuery each method is designed to iterate over collections of DOM elements, providing the context and the element itself to the callback. While native array methods are faster for data, the jQuery each method simplifies syntax when dealing with jQuery-wrapped DOM elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d4d4000-f479-47cd-a2d9-55c741cca8e7', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the architectural trade-offs between PHP''s ''share-nothing'' architecture versus persistent memory models found in languages like Java or Go.', N'Senior', N'PHP''s share-nothing model isolates each request, providing inherent stability and easier resource cleanup, but prevents direct in-memory state sharing between requests. In contrast, persistent models allow for complex object caching and connection pooling in memory but introduce risks related to memory leaks and cross-request state contamination.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e45d1183-c9e9-48c9-b147-55c7fec3d6cd', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are the <figure> and <figcaption> elements?', N'Intern', N'represents self-contained content (images, diagrams, code blocks, charts) that is referenced from the main content but could be moved without affecting the document flow. provides a caption for the figure. Example: Why it matters: + creates an accessible, semantic association between a visual/media element and its description — something + does not do structurally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9da9490b-6f34-469d-9cc5-55c8e0b8b382', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the CAP theorem?', N'Junior', N'The CAP theorem states that a distributed database can only provide two of three guarantees: Consistency, Availability, and Partition tolerance. Designers must decide which two are most critical for their specific application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e43246d6-b47d-47d7-b326-55ca1a3293aa', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are the trade-offs between using a Protocol-Oriented approach versus Class Inheritance?', N'Middle', N'Protocol-oriented programming favors composition over inheritance, preventing the ''massive base class'' problem and allowing types to conform to multiple behaviors. Inheritance creates a rigid, single-parent hierarchy that can lead to tight coupling and fragile base classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f3eb2dc-40bc-41f8-8a66-55cdf4e804f2', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How do you handle secrets and configuration in Phoenix across different environments?', N'Middle', N'Phoenix uses environment-specific configuration files that load settings based on the MIX_ENV variable. Sensitive secrets should be loaded at runtime from environment variables or a secret management service to avoid committing them to version control, ensuring security compliance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab264643-e326-4501-8fea-55d6c7183522', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you respond when a stakeholder asks for a feature that contradicts security best practices?', N'Junior', N'I would explain the security risks associated with the request and propose a more secure alternative that still meets the user''s need. Being a partner in the solution rather than just saying no helps build trust while maintaining system integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfed2c27-111f-4d37-8618-55d789a74411', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt handle CSS and assets compared to a standard Vue CLI setup?', N'Middle', N'Nuxt provides an automated assets pipeline that handles preprocessing, optimization, and code splitting for CSS and static files by default. It manages global styles and imports automatically based on the directory structure, reducing the configuration overhead typically required in custom Webpack or Vite setups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f78fab68-a65b-4716-8a90-55d789ddeb06', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What are the trade-offs of using event-driven architecture versus request-response in a high-throughput system?', N'Senior', N'Event-driven architecture provides superior decoupling, fault tolerance, and responsiveness, but introduces complexity in eventual consistency and observability. Request-response is easier to debug and reason about, but creates tight coupling and synchronous bottlenecks that limit total system throughput under heavy load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'902f0401-4bc3-4c57-a777-55d7c2f76167', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is a connection pool in the context of Actix?', N'Intern', N'A connection pool maintains a set of open connections to a database, ready for use by handlers. It avoids the overhead of opening and closing a new database connection for every incoming request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd851848e-6fe4-465a-abb1-55d94bce39ca', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the ''onReady'' hook in Fastify?', N'Intern', N'The onReady hook is triggered when all plugins have been registered and the server is about to start listening for connections. It is useful for performing final setup tasks like verifying database connectivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dee5fa12-4998-44ad-9697-55db5da57170', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is an SSTable?', N'Intern', N'An SSTable, or Sorted String Table, is an immutable data file on disk where Cassandra stores data after it has been flushed from memory. Once created, these files cannot be modified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'996b3995-dae6-4d95-8ebc-55dbe7276bc0', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Why is it often recommended to use a separate ''DTO'' (Data Transfer Object) layer instead of passing Doctrine entities directly to forms or API endpoints?', N'Senior', N'Using DTOs decouples the internal database schema from the external public API or UI requirements. This prevents over-posting attacks, avoids exposing sensitive internal fields, and allows the domain model to evolve independently of the request/response contract.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4939a05-8825-4fba-8d3e-55def93835af', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the significance of the ''AnyVal'' class in Scala''s type system.', N'Middle', N'AnyVal is the root class for value types, which allows the compiler to optimize performance by avoiding heap allocation. These types are represented as primitive types in the underlying JVM bytecode whenever possible, reducing memory overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82582412-605e-490d-adc3-55e030bae949', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is meant by type inference in TypeScript?', N'Intern', N'Type inference is the ability of the TypeScript compiler to automatically determine the type of a variable based on its value and usage. This means you do not always have to explicitly declare types, as the compiler can often figure them out on its own.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62b62b09-7aab-4f87-a003-55e0b560cf47', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the role of the Astro middleware and how does it affect page generation performance?', N'Senior', N'Astro middleware allows for request interception and response modification, enabling features like authentication checks or internationalization redirects at the edge. While it adds a small layer of overhead to each request, it prevents unnecessary full-page redirects and allows for dynamic content personalization without sacrificing the performance of static assets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9615cb1-9a67-4cd0-9088-55e0be5d9639', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Describe the impact of Preact''s lack of a Fiber-like reconciliation engine on UI responsiveness.', N'Senior', N'Without a complex scheduler like React''s Fiber, Preact performs reconciliation synchronously and in one go. While this simplifies the engine, it means long-running updates could block the main thread, necessitating careful component decomposition to maintain smooth frame rates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c05d1e9-62fb-474f-806d-55e20d1ffb25', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is a Service Class in Laravel and when should you implement one?', N'Middle', N'A Service Class is a design pattern used to encapsulate complex business logic that doesn''t fit neatly into a Controller or Model. You should use them when your controllers become too bloated or when logic needs to be reused across multiple parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a71db1ff-01a7-4acd-a5e0-55e3b25c7111', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does graceful degradation improve system reliability?', N'Middle', N'Graceful degradation involves designing a system to maintain partial functionality when certain components fail. Instead of a total service outage, the system provides a limited user experience, such as showing cached data instead of real-time results, keeping the service available.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9957d0a8-a978-4f31-8613-55e6dc538736', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Why is rate limiting essential for public-facing APIs?', N'Middle', N'Rate limiting protects your infrastructure from abuse, such as DoS attacks or accidental spikes in traffic from buggy clients. It ensures fair resource allocation among users and maintains overall service availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74f3043b-543e-49e5-970c-55f0301419bc', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What are the implications of using absolute positioning versus Flexbox for layout?', N'Senior', N'Absolute positioning removes elements from the normal document flow, requiring manual spacing and often leading to overlapping issues. Flexbox maintains the natural document flow, allowing the browser to handle sizing and wrapping calculations, which is much more robust for responsive, dynamic interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8b7bdc2-597f-4fdf-aab3-55f5f7507c0b', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the significance of the ''void'' keyword?', N'Fresher', N'The void keyword is used to indicate that a function does not return any value or that a function takes no arguments. It can also be used to define a generic pointer that can point to data of any type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac91e3a1-93ed-4ae3-8d0d-55f8ffef0900', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'When would you choose to use a custom ''Binder'' in Echo?', N'Middle', N'A custom binder is necessary when you need to support non-standard media types or implement complex transformation logic during data binding. For example, if you need to decrypt incoming payloads or map non-standard naming conventions, custom binding allows you to extend Echo''s default behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a00f1ec9-3a84-4483-8be0-55fa56d7b327', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the types of injector hierarchies?', N'Intern', N'There are two types of injector hierarchies in Angular 1. ModuleInjector hierarchy: It configure on a module level using an @NgModule() or @Injectable() annotation. 2. ElementInjector hierarchy: It created implicitly at each DOM element. Also it is empty by default unless you configure it in the providers property on @Directive() or @Component().', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20aa51aa-b516-4c49-9109-55fac4aadcee', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is vertical scaling in databases?', N'Intern', N'Vertical scaling, or scaling up, involves increasing the capacity of an existing server by adding more CPU, RAM, or storage. This is the traditional way to improve performance in many relational database systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1e33091-e9f8-4818-94f1-55faca57644f', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What are Micronaut ''Scopes'' and why are they used?', N'Junior', N'Scopes define the lifecycle and visibility of a bean within the application. Common scopes include singleton, which creates a single instance for the entire application, and request scope, which creates a new instance for every HTTP request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1020dbe-6ff1-4c59-8ca2-55fb6d713ac5', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When troubleshooting a complex system failure, what is your systematic process?', N'Junior', N'I start by establishing a timeline of events and identifying the most recent changes to the system. I then isolate components one by one to verify their health, working from the outside in, such as checking network connectivity before diving into deep application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eeffc8ed-8d0b-4cad-8718-5607867ccf65', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik implement fine-grained reactivity?', N'Senior', N'Qwik uses a signal-based reactivity system where each piece of state tracks its own subscribers. When a signal changes, Qwik only updates the specific DOM nodes that depend on that signal, avoiding re-renders of parent or sibling components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0591de8-125f-4a6c-b495-5608058d5cb3', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is Dart and why was it created?', N'Fresher', N'Dart is a client-optimized programming language designed for fast app development on any platform. It was created by Google to provide a productive development experience while maintaining high performance for both mobile and web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'deee16cc-4e22-4519-b072-560b112266d3', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a replica set in the context of Elasticsearch?', N'Fresher', N'A replica set refers to the primary shard and all its associated replicas. It ensures that if a node hosting a primary shard fails, a replica can be promoted to primary, preventing data loss.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0113b57c-b1b8-4475-9d53-560bc9b07e5f', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why would you choose a NoSQL database over SQL?', N'Fresher', N'You would choose NoSQL when dealing with large volumes of unstructured data, when the data structure is expected to change frequently, or when rapid development cycles are a priority. It is also useful when simple horizontal growth is needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58d07e41-3e03-498e-9157-561443ffabf5', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the capacity requirements for a distributed system that expects a non-linear growth in traffic?', N'Senior', N'I would perform load testing using scaled-up traffic patterns to identify the inflection point where resource saturation occurs. By analyzing the relationship between throughput and latency, I can establish a mathematical model for resource consumption and build in sufficient safety margins for horizontal scaling triggers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2c03278-a9c6-4cd2-8868-5614cfa1af64', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the difference between ''res.send()'' and ''res.json()'' in Express?', N'Junior', N'Res.send can send various types of data, such as a Buffer, a string, or an object, and it automatically sets the Content-Type based on the input. Res.json specifically sends a JSON response and ensures the Content-Type header is set to application/json.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af194411-47cb-462f-b75b-561602977570', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does synchronous iteration works', N'Fresher', N'Synchronous iteration was introduced in ES6 and it works with below set of components, Iterable: It is an object which can be iterated over via a method whose key is Symbol.iterator. Iterator: It is an object returned by invoking [Symbol.iterator]() on an iterable. This iterator object wraps each iterated element in an object and returns it via next() method one by one. IteratorResult: It is an object returned by next() method. The object contains two properties; the value property contains an iterated element and the done property determines whether the element is the last element or not. Let''s demonstrate synchronous iteration with an array as below', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02b6378e-d82a-423b-a489-56168cff9bc9', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the various statements in error handling', N'Intern', N'Below are the list of statements used in an error handling, 1. try: This statement is used to test a block of code for errors 2. catch: This statement is used to handle the error 3. throw: This statement is used to create custom errors. 4. finally: This statement is used to execute code after try and catch regardless of the result.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'050431dd-b252-4f4e-99eb-561f432ab0bb', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the role of the ''onMount'' lifecycle function?', N'Junior', N'The onMount function runs after the component is first rendered to the DOM. It is the standard place to perform side effects like fetching data or initializing third-party libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f8b5f2e-ebc0-444d-b943-561f6ec9e4b5', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is ''long double'' often problematic for cross-platform applications?', N'Senior', N'The size and precision of the ''long double'' type are implementation-defined and vary between compilers and architectures. Some platforms use an 80-bit extended precision format, while others map it to 64-bit doubles or 128-bit quad-precision, making binary-level data portability unreliable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'165016fe-4314-4f61-9930-5621852037ca', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the significance of the PHP opening and closing tags.', N'Fresher', N'PHP tags signal to the web server that the content inside must be processed by the PHP interpreter rather than being sent directly to the browser as plain HTML. Everything outside these tags is treated as static HTML and is ignored by the PHP engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d9894d4-fe2a-4469-a9e7-5621f0781b61', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS''s ''Auth'' package provide flexible authentication?', N'Middle', N'The Auth package uses a modular ''Guard'' system that supports various authentication methods like session-based, token-based, or basic auth. This allows developers to easily switch or combine authentication strategies without rewriting the core login logic or modifying model structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c40b9d4b-9216-4d12-a09f-5624921f8e90', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does the compiler optimize ''enum'' memory layout in Swift?', N'Senior', N'Swift enums are optimized by using unused bit patterns from their payload to represent additional cases, often resulting in a size equal to the largest payload plus a small tag. This allows for highly compact memory representations, especially for enums with optionals or small sets of states. This level of optimization ensures that enums remain efficient even when they represent complex, multi-state logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5937eb8-41ef-40e4-8478-5625c2a175af', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What steps do you take when a service experiences a sudden spike in latency without a corresponding increase in traffic?', N'Middle', N'I would investigate resource saturation, such as CPU throttling, thread pool exhaustion, or database connection pool starvation. Additionally, I would check for external factors like underlying infrastructure degradation, dependency slowdowns, or scheduled background tasks that might be locking shared resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f9b9ce0-cb1b-4a62-99cc-56298d207666', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a race condition that only reproduces under extreme load?', N'Senior', N'I would analyze the concurrency primitives used in the affected components, looking for unprotected shared state or improper synchronization mechanisms. I would then use stress testing tools to simulate the load in a staging environment while increasing the verbosity of thread and lock contention metrics to pinpoint the exact sequence of operations leading to the inconsistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a82e220d-17b0-4b07-ba2b-562daed11f3a', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What are the benefits of using nested layouts in Next.js?', N'Middle', N'Nested layouts allow you to preserve state and avoid unnecessary re-renders when navigating between sibling routes. By sharing common UI across multiple pages, you reduce code duplication and keep the layout persistent even when the content within it changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32411f8e-ad6e-4176-abac-562e0f5f6cee', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Explain the trade-offs between using Webpack''s ''Module Federation'' versus traditional monorepo shared libraries.', N'Senior', N'Module Federation enables runtime dependency sharing and independent deployment of micro-frontends, reducing build times by decoupling applications. In contrast, traditional monorepo shared libraries offer compile-time type safety and easier refactoring but require a full rebuild and redeployment of all consuming applications when a shared dependency changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa110084-c43d-4c66-92ac-563001d58a52', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Type Guards and how do they work?', N'Middle', N'Type guards are expressions that perform a runtime check to guarantee the type of a value within a specific scope. They can be implemented using ''typeof'', ''instanceof'', ''in'' operators, or custom user-defined type predicates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adbc6347-a246-469e-9db1-563003709815', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the purpose of keys in Preact lists?', N'Intern', N'Keys are unique identifiers used when rendering lists of elements. They help Preact efficiently track which items have changed, been added, or been removed, ensuring that the DOM updates are accurate and performant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a301565a-6330-4e64-88c5-56342af4b294', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum utilize the ''Tower'' ecosystem?', N'Fresher', N'Axum is built on top of Tower, which provides a set of abstractions for building robust networked services. It allows Axum to use middleware components that are compatible with the broader Tower ecosystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e94b67ad-1724-4ad2-8d7e-5636dab4aafb', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel''s caching abstraction layer simplify working with multiple cache backends?', N'Senior', N'The cache abstraction provides a unified API for interacting with different drivers like Redis, Memcached, or DynamoDB. This allows developers to switch infrastructure providers by changing a single configuration value without altering the application code, which is essential for environment-agnostic development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2353f2a1-2dd9-4216-99a3-56387a1c81bd', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift ensure memory safety through Automatic Reference Counting (ARC)?', N'Junior', N'ARC is a memory management mechanism that automatically tracks and manages your app''s memory usage by counting the number of references to each class instance. When the reference count drops to zero, ARC automatically deallocates the memory used by that instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fe30cde-92b8-4456-bbcb-5638a3b8488f', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are Svelte actions and why are they useful for DOM manipulation?', N'Middle', N'Actions are functions that run when an element is created, providing a way to integrate third-party libraries or perform custom DOM manipulation. They keep component logic clean by decoupling element-specific lifecycle tasks from the main component script.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ec17687-1a88-4a6a-b720-5638e0b956fa', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'When would you choose a NoSQL database over a relational database?', N'Junior', N'A NoSQL database is often chosen when the data structure is highly dynamic, when the volume of data is extremely large, or when the application requires high write throughput and horizontal scalability. Relational databases are usually preferred for complex queries and strict data consistency requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07233881-8a33-4a45-bea9-56391b01a907', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the will-change property and when should you use it?', N'Fresher', N'will-change is a CSS property that hints to the browser which properties of an element are likely to change, allowing the browser to set up optimisations (such as promoting the element to its own compositor layer) before the change actually occurs. When to use: - Only apply it to elements that will definitely animate (not as a blanket performance fix). - Remove it after the animation is complete (via JavaScript) to free GPU memory. Common values: auto, transform, opacity, scroll-position, or any other animatable CSS property. > Warning: Overusing will-change can harm performance by consuming excessive memory. Apply it sparingly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46611d7c-a5e4-44b0-a7a1-563aa8cf4aa5', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is meant by inheritance in Sass?', N'Fresher', N'Inheritance occurs when a selector shares the style properties of another selector, typically via the @extend directive. This helps keep code DRY by avoiding the duplication of shared visual properties across different components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8befe66b-6538-45c7-870d-563eb71a0742', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is render hijacking in react?', N'Intern', N'The concept of render hijacking is the ability to control what a component will output from another component. It means that you decorate your component by wrapping it into a Higher-Order component. By wrapping, you can inject additional props or make other changes, which can cause changing logic of rendering. It does not actually enable hijacking, but by using HOC you make your component behave differently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97b5b742-94fc-4743-8986-563eee232caa', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony''s ''Serializer'' component differ from manual object-to-array mapping?', N'Senior', N'The Serializer component provides a robust, metadata-driven approach to mapping complex object graphs to various formats, handling circular references and type conversion automatically. Manual mapping is prone to errors, hard to maintain as schemas evolve, and lacks the extensibility provided by the component''s normalizer and encoder architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a51b4ae9-76df-4f4c-8863-56428c7b68d8', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Explain the complexity of O(N) commands and why they are discouraged for production.', N'Senior', N'O(N) commands, such as processing large sets or hashes, have execution time proportional to the number of elements. Because Redis is single-threaded, these commands block all other clients, leading to cascading latency issues across the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70fc2bb9-8a53-446b-953a-5642e50c7176', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle automatic documentation?', N'Intern', N'FastAPI automatically generates interactive API documentation using OpenAPI standards. It provides two built-in user interfaces, Swagger UI and ReDoc, which allow developers to test API endpoints directly from the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7435b3fd-bee0-4b87-9b6d-5643377555bf', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the four ACID properties in a database?', N'Intern', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably and maintain data integrity even in the event of errors or system failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0714173-515a-4062-a27d-5643bd944e14', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the difference between a route group and a single route in Chi?', N'Intern', N'A single route points to a specific handler for a specific path, while a route group allows you to bundle multiple routes together. Groups are useful for applying shared middleware or common path prefixes to a set of related endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e093fd5e-ccdc-4e2c-8d7c-5645cfa36c7a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you explain the concept of an API to a non-technical person?', N'Fresher', N'An API is like a waiter in a restaurant who takes your order to the kitchen and brings your food back to you. It acts as a bridge that allows two different software systems to communicate, enabling them to request and exchange information without needing to know how the other system is built.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f244d7ed-6f1a-494f-87ca-56472e5f75bf', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the interaction between transaction isolation levels and index locking.', N'Senior', N'To prevent phantom reads, databases often use gap locking or next-key locking, which locks the index ranges between records. This prevents other transactions from inserting data into the ranges that a current transaction has scanned, thereby maintaining the consistency of the original result set.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48d020b3-b8cf-465d-97a7-56480ea8617d', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut support service discovery?', N'Middle', N'Micronaut provides built-in client-side load balancing and service discovery through integrations with tools like Consul, Eureka, or Kubernetes. This allows service instances to register themselves and discover others dynamically without needing a central hardware load balancer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b194599-53ce-4fa7-b133-56494225dbf3', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What are ''Ref'' objects in SolidJS?', N'Middle', N'Refs are used to gain direct access to a specific DOM element. They are primarily used for imperative actions like focusing an input, measuring element dimensions, or integrating with non-reactive third-party libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'298090ae-db72-418d-be1c-564a5c7843c4', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro manage dynamic routing?', N'Middle', N'Astro uses file-based routing where files with bracket syntax represent dynamic parameters. During the build, you provide a function to generate the necessary paths, allowing Astro to map dynamic URLs to specific content templates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92135234-03f0-40a1-9fdd-564befe5e9bd', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the ''next/font'' optimization?', N'Fresher', N'The next/font module automatically optimizes web fonts by inlining the font CSS at build time. This prevents layout shifts and improves performance by removing external network requests for fonts during initial load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fadd771a-41ab-4727-aa51-564c7df955ba', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Why is it important to use asynchronous programming in ASP.NET Core?', N'Junior', N'Asynchronous programming allows the web server to handle more concurrent requests by freeing up threads while waiting for I/O-bound operations like database queries or external API calls. This prevents thread starvation and significantly improves the scalability and responsiveness of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f36fa17-8179-40ff-8335-564c8127b60b', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the preferred method of resolving unhandled exceptions in Node.js?', N'Intern', N'Unhandled exceptions in Node.js can be caught at the Process level by attaching a handler for uncaughtException event. Process is a global object that provides information about the current Node.js process. Process is a listener function that is always listening to events. Few events are : 1. Exit 1. disconnect 1. unhandledException 1. rejectionHandled', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee2f8bd4-f463-47e5-888c-565393613279', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux Toolkit simplify Redux development?', N'Middle', N'Redux Toolkit reduces boilerplate by providing utilities like ''createSlice'', which combines actions and reducers, and by configuring the store with sensible defaults. It also includes built-in support for immutability via Immer, making it easier to write clean, maintainable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fb22cfd-4faa-46d1-8929-56582cb47f97', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you add, remove, and update elements in an array?', N'Fresher', N'To add elements to an array, you can use methods like push, unshift, or splice. To remove elements, you can use pop, shift, or splice. To update elements, you can directly access the array index and assign a new value. Note: If you try to console.log(arr) after each operation in some environments (like Chrome DevTools), you may only see the final state of arr. This happens because the console sometimes keeps a live reference to the array instead of logging its state at the exact moment. To see intermediate states properly, store snapshots using console.log([...arr]) or print values immediately after each operation. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
