INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a0faa9f-8b77-4ac2-a6ba-565af9a90cae', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why is Fastify often compared to Express?', N'Fresher', N'Fastify is often compared to Express because both are popular Node.js web frameworks. However, Fastify is built with a focus on higher performance, stricter schema validation, and a more structured plugin architecture compared to the more middleware-heavy approach of Express.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b304a745-9800-491d-9dfb-565b83d813dd', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Describe the architectural challenge of session management in Flask when deploying across multiple server instances.', N'Senior', N'Flask''s default session implementation stores data in a client-side signed cookie, which can become problematic if the session size exceeds cookie limits or if sensitive data needs to be stored server-side. For distributed systems, moving to server-side session stores like Redis or Memcached is necessary to maintain consistency and security across load-balanced nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c33bc0d2-11bd-4068-9d6d-565c78212609', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a document ID?', N'Intern', N'A document ID is a unique identifier for a document within an index. You can provide your own ID or allow Elasticsearch to automatically generate one upon indexing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2d07587-c7c3-42e7-b20b-565ce341ab37', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the identity map pattern in ActiveRecord, and why was it removed from Rails?', N'Senior', N'An identity map ensures that a single database record is represented by only one object instance within a single request. It was removed because it introduced significant complexity in cache invalidation and memory management without providing a clear performance benefit for most Rails applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12cd0f11-d1d4-4c53-ab19-565db3ac1866', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are hidden classes?', N'Intern', N'Since JavaScript is a dynamic programming language, you can add or remove properties and methods from objects on the fly at runtime. This nature of JavaScript increases the dynamic dictionary lookups(because objects implemented as HashTables in memory) for retrieving a property on an object. Let''s consider the following example to see how the additional properties age and gender added at runtime. As a result, this behavior leads to lower JavaScript performance compared to the contiguous buffer method used in non-dynamic languages. The V8 engine provided a solution named hidden classes to optimize the access time when retrieving a property on an object. This optimization is achieved by sharing hidden classes among objects created in a similar fashion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7df8647a-34f1-4c1a-9641-565ffb87be32', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP''s Just-In-Time (JIT) compiler differ from the traditional Opcode execution model?', N'Senior', N'JIT translates bytecode into machine code at runtime, allowing the CPU to execute instructions directly rather than interpreting them via the Zend VM. This provides significant performance gains for CPU-intensive mathematical operations while offering little benefit to typical I/O-bound web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f6b9049-5681-4e28-87e6-56652edf21a4', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How can you implement caching in Spring Boot?', N'Middle', N'Caching is implemented by using the @EnableCaching annotation and annotating methods with @Cacheable, @CachePut, or @CacheEvict. You must also provide a cache manager implementation, such as Caffeine, Redis, or Ehcache, which handles the underlying storage and expiration logic for the cached data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd697194-a16c-4a16-8cfe-5665cc6e1236', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are ''higher-order functions'' and why are they fundamental to Scala?', N'Middle', N'Higher-order functions are functions that take other functions as parameters or return them as results. They are central to Scala because they enable powerful abstractions like composition and transformation, allowing developers to write more concise and reusable logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52a51126-133e-4f4a-ad5f-56688bcf858d', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does sharding by ''Hash'' differ from ''Range'' in terms of scalability and hotspots?', N'Senior', N'Range sharding allows for efficient range-based queries but is prone to hotspots when data is accessed sequentially. Hash sharding provides a uniform distribution of data across nodes, effectively preventing hotspots, but it makes range queries across the entire dataset prohibitively expensive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58a82180-8b04-4fe5-9855-5668c90c15a0', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are Webpack plugins?', N'Intern', N'Plugins are tools used to perform a wider range of tasks that loaders cannot handle, such as bundle optimization, asset management, and environment variable injection. They hook into the entire build lifecycle to modify the output or perform additional cleanup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
