INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f9094ef-ae11-4759-aedc-566f58bd50dd', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the impact of using ''Buffer'' middleware in Axum?', N'Middle', N'The Buffer middleware adds a bounded mpsc channel in front of a service, which helps manage load and prevents overwhelming a resource. It is useful for services that are not inherently thread-safe or that need to limit the number of concurrent executions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7b25524-ef0f-4810-87c8-5670f07810d0', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the role of Dependency Injection in Quarkus?', N'Intern', N'Dependency Injection is the mechanism used to manage object lifecycles and wire components together. Quarkus uses a CDI-compliant system that is optimized at build time to ensure that injections are resolved efficiently without needing complex reflection at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe6015be-a2fd-4e53-8a14-567275597ddb', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How does a load balancer improve the reliability of a web application?', N'Fresher', N'A load balancer distributes incoming traffic across multiple servers, ensuring that no single server becomes overwhelmed. If one server fails or needs maintenance, the load balancer directs traffic to the remaining healthy servers, keeping the application available to users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
