INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fa4a97a-5a51-4b65-9836-5677e5777b5f', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Why would you implement a read-replica strategy, and what are the primary challenges regarding ''read-after-write'' consistency?', N'Senior', N'Read replicas scale read-heavy workloads by distributing traffic across multiple database nodes, significantly increasing performance. The main challenge is replication lag, where a write may not be immediately visible to a subsequent read, requiring the application to handle potential stale data or force reads to the primary node for critical paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
