INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'800a7281-d132-484c-b89c-568430ca22c9', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask''s thread-local storage mechanism, specifically the request context, impact the scalability and testing of an application?', N'Middle', N'Flask uses proxy objects that allow request-specific data to be accessed globally within a thread or greenlet. While this simplifies development, it can complicate testing because these proxies are only active during an active request context, requiring developers to manually push contexts in test suites. For scalability, this approach relies on the underlying server''s ability to handle concurrent threads or processes, which can become a bottleneck under high load compared to fully asynchronous frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33c7db9f-80c1-42f3-9b55-56848a09e719', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the primary purpose of a partition key in Apache Cassandra?', N'Junior', N'The partition key determines which node in the cluster will store a specific row of data. By using a hash of the partition key, Cassandra distributes data evenly across the cluster to ensure efficient read and write operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
