INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8356381f-2b9a-4760-bade-56865eb33ed7', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the trade-offs of using UUIDs versus BigInts as primary keys in a clustered index?', N'Senior', N'BigInts are monotonically increasing, which keeps B-Tree index pages packed and reduces page splits. UUIDs, if not sequential, cause random insertions, leading to fragmented index pages, poor cache locality, and significant performance degradation as the database grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
