INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0f42cb6-24e5-4da6-9d1e-568a92cdef27', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How Do You Use useRef to Access a DOM Element in React? Give an example.', N'Fresher', N'The useRef hook is commonly used in React to directly reference and interact with DOM elements — like focusing an input, scrolling to a section, or controlling media elements. When you assign a ref to a DOM element using useRef, React gives you access to the underlying DOM node via the .current property of the ref object. Example: Focus an input Note: The DOM reference is only available after the component has mounted — typically accessed in useEffect or event handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'458bfc15-0c43-451d-9588-568b2313ad43', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the primary difference between a Lucene index and an Elasticsearch shard?', N'Middle', N'A Lucene index is the fundamental storage unit that handles read and write operations for a specific set of documents. An Elasticsearch shard is a wrapper around a Lucene index that adds distributed capabilities, such as replication and the ability to be moved across different nodes in a cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6709e3a5-fc40-459b-9fb7-569190d6c8f8', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is ''at-least-once'' delivery, and how is it usually achieved?', N'Middle', N'At-least-once delivery ensures that a message is never lost, though it might be delivered multiple times. It is achieved by requiring the consumer to send an explicit acknowledgement back to the message broker after successfully processing the message.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6ca3c42-52fd-4abe-a2b0-5691bd107388', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the significance of the Redis ''MULTI/EXEC'' block in ensuring command atomicity?', N'Senior', N'MULTI/EXEC blocks ensure that all commands in a transaction are executed sequentially as a single atomic operation, preventing other clients from interleaving commands. It is important to note that this does not provide rollback functionality; if a command fails during execution, the others will still complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34ff456d-9a5c-4551-bd56-5692b5f77c9f', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the function of a C# ''partial'' class?', N'Middle', N'A partial class allows the definition of a single class to be split across multiple files. This is particularly useful for separating auto-generated code from manual developer modifications, ensuring that changes to one do not overwrite the other during build processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3927024-2b0c-4424-9ce8-5694a3177f6f', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why should you avoid using Scan operations in production?', N'Middle', N'Scan operations read every single item in a table, which is extremely expensive and slow as the dataset grows. They consume significant read capacity and should be replaced by Query operations using index keys whenever possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d4b7c57-709f-4554-9c5e-569a8d815ddf', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the advantage of using AdonisJS''s ''Container'' for unit testing?', N'Middle', N'The IoC container allows for easy mocking or swapping of dependencies during testing, enabling developers to isolate the unit of code under test from external systems like databases or third-party APIs. This leads to more reliable, faster tests that focus on business logic rather than infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c6bb506-bf0d-4ae4-a806-569b256b173d', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you ensure your work is accessible to users with disabilities?', N'Intern', N'I follow standard accessibility guidelines during the design and implementation phases to ensure the interface is navigable by assistive technologies. This includes considering keyboard navigation, screen readers, and color contrast.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ad2aebc-afe8-485b-b7e2-569de540d939', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between pass-by-value and pass-by-reference in C?', N'Junior', N'Pass-by-value copies the actual value of an argument into the function, so changes made to the parameter do not affect the original variable. Pass-by-reference passes the memory address of the variable, allowing the function to modify the original data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b9fbd32-d333-4f07-b7f8-569e8096975d', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is it important to avoid blocking operations inside an Actix actor message handler?', N'Middle', N'Actix handlers run on the event loop; if a handler performs a blocking operation like synchronous file I/O or a heavy computation, it blocks the entire event loop thread. This prevents the event loop from processing other incoming requests or events, leading to a significant drop in throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e6c4222-5230-46bb-b980-569f8dc3cf2b', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Can you use React ecosystem libraries with Preact?', N'Fresher', N'Yes, through a compatibility layer called preact-compat or preact/compat. This allows you to use most existing React libraries in a Preact project without needing to rewrite them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d8cc9a8-05a3-4e4f-9875-56a0d113c888', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the primary architectural advantage of using Fiber over the standard net/http library?', N'Intern', N'The primary advantage is performance, specifically memory management. Fiber uses Fasthttp, which minimizes memory allocation by reusing objects, leading to significantly lower garbage collection overhead and higher throughput for concurrent requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fc9e280-39d2-43c2-b0c5-56a12a9c743e', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain how NestJS facilitates the implementation of a CQRS pattern and why it is beneficial for high-read applications.', N'Senior', N'NestJS provides a dedicated CQRS module that separates the read and write operations, allowing for different data models and scaling strategies for each. This is beneficial for high-read applications because it allows for read-optimized database views or caching strategies to be implemented independently of the write-side business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0071269-09d2-4bbf-b33f-56a49d3d9935', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind CSS improve developer productivity?', N'Fresher', N'It improves productivity by removing the need to come up with meaningful class names for every single element. Developers can build and iterate on interfaces instantly without leaving their HTML files or managing complex CSS specificity issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86baadcb-4eb5-4b93-b691-56a60159f63c', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why are components in SolidJS only called once?', N'Intern', N'SolidJS components are setup functions that run only once when initialized to establish the reactive graph. Subsequent updates are handled by the individual reactive primitives rather than re-executing the component function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85acb309-2cc4-4636-805a-56a6531f9893', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the maximum size of a single item in DynamoDB?', N'Intern', N'The maximum size of a single item, including all attributes and attribute names, is 400 KB. If your data exceeds this, you should store large blobs in Amazon S3 and store the reference link in DynamoDB.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b784faf-580d-4225-a03a-56b04270cf74', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the ''diffing'' algorithm in Preact?', N'Fresher', N'The diffing algorithm is the process Preact uses to compare the new virtual tree with the previous one. It identifies exactly what has changed and updates only those parts of the real DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4314ff42-3dd1-4697-8e53-56b371d511d2', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If two people provide vastly different estimates for the same task, how would you reconcile the difference?', N'Intern', N'I would ask both parties to explain the assumptions they made and the specific steps they included in their calculations. By comparing these methodologies, we can identify which factors one person included that the other missed, allowing us to build a more comprehensive and shared understanding of the task.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f209764-1363-477d-abf7-56b3e1296a66', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain serialization and deserialization / Pickling and unpicking?', N'Fresher', N'Pickle module accepts any Python object and converts it into a string representation and dumps it into a file by using dump function, this process is called pickling. While the process of retrieving original Python objects from the stored string representation is called unpickling. To create portable serialized representations of Python objects, we have the module ''pickle''. It accepts a Python object (remember, everything in Python is an object). It then converts it into a string representation and uses the dump() function to dump it into a file. We call this pickling. In contrast, retrieving objects from this stored string representation is termed ''unpickling''. The pickle module implements binary protocols for serializing and deserializing a Python object structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3b2751b-4bea-410e-9fd3-56b513ab050e', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the function of the ''lib'' folder in a Phoenix project?', N'Fresher', N'The lib folder contains the source code for the application logic. This is where the core functionality, such as contexts, controllers, and schemas, is stored and organized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c415deaf-548d-4739-a7e6-56bab480bb50', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the ''sealed'' modifier?', N'Intern', N'The sealed modifier prevents a class from being inherited by other classes. It is also used on methods or properties to prevent them from being overridden in derived classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'785cef34-a68d-43d7-832d-56babacacb47', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the architectural implications of using descriptors in Python?', N'Senior', N'Descriptors allow objects to define custom behavior for attribute access, assignment, and deletion by implementing specific magic methods. They form the foundation of core language features like properties, methods, and class methods, enabling fine-grained control over object state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'451dd15f-5adf-4fdd-954c-56bb2d1fb419', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you keep your technical knowledge current for problem-solving?', N'Fresher', N'I read industry blogs, follow documentation updates, and engage in small practice projects to stay familiar with current tools. This helps me recognize a wider variety of potential solutions when faced with new problems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d0679fc-7474-4ddf-ae17-56bb4c29ea01', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between ''string'' and ''StringBuilder''?', N'Fresher', N'A string is immutable, meaning any modification creates a new string object in memory. StringBuilder is mutable and allows for efficient modification of character strings without creating multiple temporary objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
