INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3e3def9-6c90-4782-b3e7-56be7a4cceff', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the benefit of using ''Value Classes'' in Kotlin?', N'Middle', N'Value classes allow wrapping a single value in a type-safe wrapper without the overhead of additional object allocation at runtime. The compiler replaces the wrapper with the underlying value wherever possible, providing the benefits of domain-specific types without the memory cost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'123db6c9-86e9-469c-8b59-56be9b60f0c0', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel''s database ''read-write'' splitting work, and what are the risks regarding replica lag?', N'Senior', N'Laravel allows configuring multiple database connections for read and write operations, automatically routing selects to replicas and writes to the primary. The primary risk is replica lag, where a client might perform a write and immediately attempt to read the data before the replication process has completed, leading to data inconsistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc9d96f3-b8cb-4c69-977d-56bfec19a6c3', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a service worker', N'Intern', N'A Service worker is basically a script (JavaScript file) that runs in the background, separate from a web page and provides features that don''t need a web page or user interaction. Some of the major features of service workers are Rich offline experiences(offline first web application development), periodic background syncs, push notifications, intercept and handle network requests and programmatically managing a cache of responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce547060-9525-4eae-bbd1-56c261cfd6a3', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift enable encapsulation within classes and structs?', N'Fresher', N'Both classes and structs in Swift provide encapsulation through access control modifiers. Swift has several access control levels, such as open, public, internal, fileprivate, and private, to determine the visibility and accessibility of properties and methods. Key Access Control Levels - Open (for classes and their members) means the entity is accessible and can be subclassed outside its defining module. This level allows the most freedom but is also the most open. - Public indicates that the entity can be used and accessed outside the defining module, but not subclassed. - Internal is the default. It signifies that properties and methods are accessible within the defining module but not from outside. - Fileprivate makes the entity visible only within the same file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7eed5879-2c50-4b97-9a40-56c2838b40a9', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why is it important to define a ''lang'' attribute on the root HTML element?', N'Middle', N'The ''lang'' attribute identifies the primary language of the page content, which is used by screen readers to select the correct speech synthesis voice and pronunciation. It also helps search engines categorize the page content correctly. Failing to specify this can lead to poor accessibility and incorrect language detection for browser-based translation tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1327ccf7-9c0c-44db-8ff4-56c5202e59a7', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the primary difference between physical and logical replication in terms of recovery and flexibility?', N'Senior', N'Physical replication copies the raw data blocks, which is faster and ensures an exact replica, but prevents schema modifications on the secondary. Logical replication copies row-level changes, offering higher flexibility for partial replication or cross-version upgrades at the cost of higher CPU overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab5f3be8-d844-4bdf-a8af-56ca2a021848', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the significance of the ''pino'' logger in Fastify?', N'Fresher', N'Pino is the default logger used by Fastify, chosen for its extreme speed and low overhead. It is integrated into the framework to provide structured logging, which is essential for debugging and monitoring production applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e818f5ff-51af-4500-860d-56cc5f6e4286', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus handle security, and what is the role of OIDC?', N'Middle', N'Quarkus provides a robust security layer that integrates seamlessly with OpenID Connect (OIDC) and JSON Web Tokens (JWT). It allows developers to secure endpoints using standard annotations and external identity providers, centralizing authentication and authorization logic outside the core application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05fef825-580a-43a4-8679-56cfe7bdd9df', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is a ''Scope'' in Actix routing?', N'Intern', N'A scope is a way to group related routes under a common path prefix. This helps in organizing code and applying specific middleware to a subset of application endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93b9eacb-71e5-47ed-9780-56d0b6c5c9c2', N'4c000000-0000-0000-0000-000000000005', N'How do you handle service discovery in a dynamic, containerized environment?', N'Senior', N'Service discovery is typically handled by a central registry or service mesh control plane that tracks the IP addresses of ephemeral instances. Clients query this registry or use a transparent proxy to route requests to healthy service instances automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc31f98a-5565-4391-9c9b-56d1c9b5cbb1', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is a hash in Webpack filenames?', N'Fresher', N'A hash is a unique string appended to the filename of an output bundle, typically based on the file content. It is used for cache busting, ensuring that the browser downloads the latest version of the file when the code changes instead of using a stale version from the cache.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc40e7e0-40b0-496e-b1ce-56d21a257790', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How do you handle state management in a distributed Node.js system given its event-driven nature?', N'Senior', N'Since local memory is not shared across processes or nodes, state must be externalized using distributed caches like Redis or persistent databases. This ensures that horizontal scaling remains possible without violating the principle of stateless application design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03edced4-84fa-4c9e-8980-56dad4ea1ecb', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are access modifiers in TypeScript classes?', N'Intern', N'Access modifiers define the visibility of class members. ''Public'' members are accessible everywhere, ''private'' members are only accessible within the class, and ''protected'' members are accessible within the class and its subclasses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1339f588-ddfb-4337-939e-56dbfc8735fc', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What are the advantages of using message queues for inter-service communication?', N'Middle', N'Message queues enable asynchronous communication, which decouples services and allows them to operate independently without waiting for immediate responses. This improves system resilience by buffering spikes in traffic and ensures that tasks can be processed at a controlled rate without overwhelming downstream services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a5fc317-0fe9-43a7-8a52-56ddf804fea6', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What strategies does Micronaut provide for load balancing in microservice communication?', N'Senior', N'Micronaut supports client-side load balancing through discovery clients that return a list of available service instances. The framework can then apply various strategies like round-robin or custom load-balancing logic to distribute requests effectively across the infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7b99b42-144a-4a90-90de-56de87c8e25b', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of ''std::weak_ptr'' in smart pointer management?', N'Middle', N'A ''std::weak_ptr'' provides a way to observe an object managed by a ''std::shared_ptr'' without incrementing its reference count. This is essential for breaking cyclic references that would otherwise prevent objects from being properly deleted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41bbeeb9-4fae-48f3-9e76-56dfb275c021', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the architectural considerations when choosing between document-oriented and key-value stores?', N'Senior', N'Key-value stores provide simple, highly scalable access optimized for primary key lookups with minimal overhead. Document stores offer richer query capabilities, such as secondary indexing and complex filtering on nested fields, but typically introduce higher storage overhead and increased complexity in maintaining index consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72ee850f-815f-43a2-a746-56e08e25219d', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between a ''Component'' and a ''Bean''?', N'Junior', N'A @Component is a class-level annotation used for automatic bean detection via component scanning. A ''Bean'' is the resulting object instance managed by the container, which can also be created manually via @Configuration methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e75ac219-bbdc-4170-9afb-56e4b2440063', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does the CAP theorem influence the architectural design of a distributed NoSQL database?', N'Senior', N'The CAP theorem forces architects to choose between consistency and availability during a network partition. Systems are categorized as CP, prioritizing data integrity at the cost of downtime, or AP, ensuring the system remains responsive by potentially serving stale data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a3751e4-d59d-4500-8ac6-56e4ee0f8908', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of Ember''s Service layer, and when should you prefer it over component-level state?', N'Middle', N'Services are singleton objects that persist for the duration of the application lifecycle, making them ideal for managing global state, such as authentication status or user preferences. You should prefer services over component-level state when data needs to be shared across multiple routes or components that do not share a common parent, avoiding the need for deep prop drilling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73abe4c6-13af-4f98-8061-56eb06eafe9b', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the ''recover'' function in Go?', N'Intern', N'The ''recover'' function is a built-in tool used to regain control of a panicking Goroutine. It is only useful when called inside a deferred function to stop the panic sequence and allow the program to resume normal execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9418b17-07bb-4f13-9627-56ebb07a0a7f', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the primary architectural difference between Astro''s ''Islands Architecture'' and a standard Single Page Application (SPA) framework?', N'Middle', N'Astro defaults to a server-first approach that renders content as static HTML, delivering zero JavaScript to the client by default. In contrast, SPAs typically ship the entire framework and application bundle to the browser before rendering. The Islands Architecture allows developers to hydrate only specific interactive components while keeping the rest of the page as static, lightweight HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd131832-8690-4986-8e6a-56ec215384d7', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript achieve type safety with union types and discriminated unions compared to traditional sum types?', N'Senior', N'TypeScript uses control flow analysis to narrow down types within a union based on common literal properties known as discriminants. This allows for exhaustive checking during compile-time, ensuring that all possible variants are handled without requiring a complex runtime tag system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aae97526-980a-464d-bd18-56ed795fb263', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How does team size influence technical trade-offs?', N'Fresher', N'Small teams might prioritize speed and simplicity to stay agile, while larger teams often prioritize standardized processes and documentation to keep everyone aligned. The trade-off is between agility and coordination overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'874a7ad0-5b1e-4f61-bda6-56ee50927311', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of the tsconfig.json file?', N'Intern', N'The tsconfig.json file defines the compiler options and the files that should be included or excluded in a TypeScript project. It acts as the configuration hub for how the compiler processes your code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f8ff649-49e3-4f20-945e-56f03473ff8d', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How do you mitigate the risk of ''Event Loop Blockage'' when processing large JSON payloads in Express?', N'Senior', N'Large JSON parsing is synchronous and blocks the event loop; for massive payloads, it is better to stream the request body or use worker threads for parsing. Configuring limits on payload size via middleware is the first line of defense to prevent memory-related crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8502c257-5a05-4ac0-9331-56f2592ce850', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What are the risks of over-engineering a solution early in the project?', N'Fresher', N'Over-engineering adds unnecessary complexity and takes more time than required, which can make the system harder to maintain later. It is better to start with a simple, flexible solution that meets current needs and iterate as the project grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01e3a65b-cb6c-4fa7-9538-56f46221c9ae', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle event listening?', N'Fresher', N'Alpine.js uses the x-on directive to listen for browser events like clicks, input changes, or key presses. When the specified event occurs on the element, it executes the provided JavaScript expression.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd00c270-7130-4cde-8296-56f6d7d63d17', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify ensure high performance?', N'Fresher', N'Fastify ensures performance by using a highly optimized router, avoiding unnecessary object creation, and using fast JSON serialization. It also minimizes the overhead of context switching and processing by utilizing efficient internal data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64e8cce3-b4e7-41d2-b966-56f76b8c158f', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of Micronaut''s ''Introduction Advice''?', N'Intern', N'Introduction advice is a way for Micronaut to implement interfaces automatically at compile time. This is often used for features like data repositories or client interfaces where the implementation is generated based on the interface definition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75cdf225-5823-41cb-abbd-56f89b34af19', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle the ''Content-Type'' header during response serialization?', N'Middle', N'Express automatically sets the ''Content-Type'' header based on the data passed to methods like res.json() or res.send(). If a plain object is passed to res.send(), it defaults to JSON, whereas a string defaults to HTML or plain text.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8789eed3-a32a-4c0d-b08d-56f8ff51a0a5', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact''s approach to server-side rendering (SSR) compare to React''s regarding stream throughput?', N'Senior', N'Preact provides a lightweight SSR implementation that serializes the VDOM directly to string format without the overhead of heavy hydration metadata. This results in faster time-to-first-byte and reduced server-side CPU utilization, though it requires precise coordination for client-side hydration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cbd56c1-d9e2-4d98-99b5-56f9134fb3b6', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the role of a rollback in a transaction?', N'Intern', N'A rollback is used to undo the changes made during a transaction if an error occurs before the commit. It returns the database to the state it was in before the transaction began.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd89d441-c504-4c36-bfc0-56f9db9ced6a', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When faced with a choice between speed of development and code quality, how should an engineer approach the trade-off?', N'Intern', N'An engineer should consider the long-term impact on technical debt versus the immediate business need for a feature. If the priority is a quick prototype, speed may be favored, but for a stable production system, prioritizing quality is essential to avoid future maintenance burdens.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'166a06df-a4bb-46dc-98ea-56fd2d1b2845', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'When would you prefer using ''CSS Shadow Parts'' over global CSS?', N'Middle', N'CSS Shadow Parts allow a component to explicitly expose specific internal elements to be styled from the outside. It is a more robust and performant alternative to global CSS or deep piercing selectors, maintaining strict encapsulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d5baf12-4981-40e5-8409-56ff476bc014', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the benefit of using a utility-first framework versus writing standard CSS?', N'Intern', N'Utility-first frameworks eliminate the need to invent class names and manage large, complex CSS files. This consistency makes it easier to maintain styles across a large project and prevents the global scope issues common with traditional CSS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e637587f-092a-4ea5-87fd-56ffde224380', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the difference between an embedded data model and a referenced data model?', N'Middle', N'An embedded model stores related data within a single document, which is highly efficient for read performance and atomic updates. A referenced model uses manual or DBRefs to link separate documents, which is better for avoiding data duplication and handling many-to-many relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf8f0566-2c37-428d-8e0d-57000d2c1fe2', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why is ''schema flexibility'' considered a major advantage of NoSQL databases?', N'Fresher', N'Schema flexibility allows developers to insert data without having to define a rigid structure or column types beforehand. This is particularly useful for applications where data requirements change frequently or where the data objects vary significantly in format, as it eliminates the need for complex database migrations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94cd86f6-2c67-4aee-8de7-57004a2767ea', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is Virtual DOM?', N'Intern', N'The _Virtual DOM_ (VDOM) is a lightweight, in-memory representation of _Real DOM_ used by libraries like React to optimize UI rendering. The representation of a UI is kept in memory and synced with the "real" DOM. It''s a step that happens between the render function being called and the displaying of elements on the screen. This entire process is called _reconciliation_.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8799f27b-2249-45e7-bfde-57021cd844fc', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket''s ''Route'' discovery mechanism work at start-up?', N'Senior', N'At start-up, Rocket collects all routes and mounts them into a routing tree during the application initialization phase. This phase performs validation checks, such as verifying route overlap or invalid parameter types, ensuring that the application cannot start in an invalid state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2acf4c6a-4064-40b8-a8d2-57033fdb3e50', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How can you optimize database performance in Django when dealing with large datasets?', N'Middle', N'You can optimize performance by using database indexing on fields frequently used for filtering, utilizing values or values_list for partial data retrieval, and employing pagination to avoid loading large result sets into memory at once.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a26472f9-9ebb-473b-b894-5704fdada8a0', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik maintain state during the transition from server to client?', N'Fresher', N'Qwik serializes the application state into the HTML itself during the server-side rendering process. When the application resumes in the browser, it reads this serialized state directly from the DOM, avoiding the need to re-fetch or re-initialize data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f518acda-be67-4851-a939-57052afcf414', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'When designing an Express middleware for authentication, why is it better to use a stateless token approach rather than stateful sessions?', N'Senior', N'Stateless tokens (like JWTs) remove the need for a shared session store, enabling the application to scale horizontally without synchronization overhead. However, they require careful implementation of token revocation strategies since the server cannot easily invalidate a token once issued.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fc34ce2-4701-4396-b4e7-57060c2d17ba', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the advantages of Bazel tool?', N'Intern', N'Below are the list of key advantages of Bazel tool, 1. It creates the possibility of building your back-ends and front-ends with the same tool 2. The incremental build and tests 3. It creates the possibility to have remote builds and cache on a build farm.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'caa3c9b1-4b67-47d0-bb6d-5707ecb4582b', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi facilitate graceful shutdown and recovery in production environments?', N'Senior', N'Chi integrates natively with standard Go server management patterns, allowing developers to implement middleware that recovers from panics and logs the stack trace. By wrapping the main handler with a recovery middleware, the server can remain resilient against unexpected runtime errors during request processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe7e08e3-ae9f-448e-b6a1-570840e2897d', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between an Action Filter and Middleware?', N'Junior', N'Middleware runs for every request and response in the pipeline, providing broad functionality like security headers or error handling. Action Filters are more specific and run only within the context of MVC controller actions, allowing you to execute code specifically before or after an action executes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
