INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a884cb2-bb22-4b3e-a23b-5710a61aa3d8', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono differ from Express in terms of its core dependency usage?', N'Junior', N'Express is built specifically for the Node.js runtime and relies on its internal APIs. Hono is built on the Fetch API standard, making it lightweight and highly portable across modern edge computing environments and serverless platforms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'468a195b-83cb-42ce-bc21-571362a35601', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the trade-offs of denormalization in NoSQL databases?', N'Middle', N'Denormalization stores related data together in a single record to eliminate the need for costly joins, significantly improving read performance. However, it increases storage overhead and can lead to data inconsistency if the same information is duplicated across multiple documents.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63887654-9a91-4803-aee5-57144bbb11ce', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the ''is'' operator in C#?', N'Fresher', N'The is operator is used to check if an object is compatible with a given type. It returns true if the object is an instance of the type or can be cast to it, and false otherwise.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e970dc37-9287-4c2f-abb7-5714d41b065c', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the trade-offs of using Redis as a primary database versus a cache?', N'Middle', N'Using Redis as a primary database provides extreme speed but risks data loss during failures if persistence is not tuned correctly. Using it as a cache is safer because the source of truth resides in a disk-based database, allowing for easier recovery if the Redis data is lost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'635ba77b-2cb3-45f3-ae6d-57179c96f942', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why is it important for Remix to be ''platform-agnostic''?', N'Middle', N'Being platform-agnostic ensures that Remix applications can be deployed to any environment that supports the Web Fetch API. This prevents vendor lock-in and allows developers to choose the hosting infrastructure that best fits their performance and scalability requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8715d0d-0467-437a-89a6-57191d6d186e', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go''s garbage collector handle the ''stop-the-world'' phase?', N'Senior', N'The stop-the-world phase is a brief pause where the runtime halts all goroutines to perform specific tasks, such as stack scanning or finalization. Modern Go versions have minimized this phase to sub-millisecond durations by keeping it restricted to root scanning. The primary goal is to ensure that the heap state is consistent before transitioning into the concurrent marking phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'256dc708-bf97-4cd7-869e-571ea8bc54be', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the function of the MySQL Query Cache and why is it often disabled in modern versions?', N'Middle', N'The Query Cache stored the results of SELECT statements to speed up identical future requests. It was deprecated because it creates a global lock contention point in multi-core systems, making it a bottleneck rather than a performance booster under high write loads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd725eaf2-90f6-4d70-b09c-57216b89a73f', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember''s Router handle nested state, and why is this useful for complex applications?', N'Senior', N'The Ember Router uses a hierarchical state machine approach, where URL segments map directly to nested routes and their corresponding templates. This architecture allows for predictable UI state management and simplifies data loading by enabling each route level to manage its own model fetching logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afb86dc5-1d9b-4bb8-aeb9-5725527f6fdc', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What does ''Island hydration'' mean?', N'Intern', N'Hydration is the process of attaching JavaScript to static HTML to make it interactive. In Astro, this only happens for the specific ''islands'' that you explicitly mark, rather than the whole page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f58424a-e78e-45b1-b049-572878a1ebd9', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the significance of the .GlobalEnv in R.', N'Middle', N'The .GlobalEnv is the top-level workspace where user-defined variables and functions are stored during an interactive session. It is the final environment searched in the scoping chain and is generally discouraged in package development to avoid polluting the global namespace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f47e60a-f7bd-46df-8eaa-572879b5916a', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Explain how Gin''s ''Abort'' mechanism works and its effect on the middleware chain.', N'Senior', N'The ''Abort'' method sets the index of the middleware chain to a high value, effectively skipping all subsequent pending handlers. It does not stop the current function execution, so developers must explicitly return from the handler after calling ''Abort''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3c0d75b-11d5-4d0e-b3b7-5729ce775e5b', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does the ''Trait'' concept in Scala differ from an Interface in Java?', N'Junior', N'While both allow for defining common behavior, a Scala trait is more powerful because it can contain both abstract and concrete method implementations. Additionally, classes can mix in multiple traits to achieve a form of multiple inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e12f222-7f35-43df-8312-572b72d16cc9', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Describe the concept of Multi-Version Concurrency Control (MVCC) and its benefits.', N'Senior', N'MVCC allows multiple versions of a data item to coexist, enabling readers to access a consistent snapshot of the data without being blocked by concurrent writers. This significantly increases system concurrency and prevents read-write contention, which is critical for high-performance transaction processing systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0a632b2-55ea-4fc6-8300-572be87b1414', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the difference between an API and a UI, and why does that matter for debugging?', N'Junior', N'The API handles the data and business logic, while the UI handles the visual presentation and user interaction. If a feature fails, knowing the difference helps determine if the error is in the data retrieval process or a visual layout issue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14d23983-71e8-425e-8248-572e6320c9db', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does ''Partition Tolerance'' influence the design of distributed locking mechanisms?', N'Senior', N'In the face of network partitions, distributed locking requires consensus protocols like Paxos or Raft to avoid split-brain scenarios. These protocols ensure that only one partition can hold the lock, but they introduce significant latency and reduce system availability if a majority of nodes cannot be reached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfd651af-1ffe-4370-bbfb-573053f30cfe', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What does it mean for a Rocket handler to be ''asynchronous''?', N'Fresher', N'An asynchronous handler allows the server to process other incoming requests while waiting for I/O operations like database queries or file reads to complete. This improves the overall throughput of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74b5f203-1cdf-4bf0-a0d2-57305e4c0a45', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the impact of using Fiber''s ''Next'' function in middleware?', N'Middle', N'The ''Next'' function is used to pass control to the next middleware or handler in the chain. If a middleware decides to return a response without calling ''Next'', the subsequent handlers in the stack will not be executed, effectively terminating the request lifecycle at that point.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e86c0382-ea4d-4568-92d1-573247d23b35', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach a problem where the variables are interdependent?', N'Intern', N'I would identify the most influential variable and analyze how changes in that variable ripple through the system to affect others. By mapping these dependencies, I can avoid the mistake of isolating variables that are actually linked, leading to a more holistic and accurate model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee026014-ecbf-4c23-a653-5733216d71bf', N'954a0331-deff-4399-b588-96f39fec001d', N'What are directives and what are its types?', N'Intern', N'Directives in Angular are classes that add behavior to elements in your application. They allow you to manipulate the DOM, change the appearance of elements, or modify their structure. There are three main types of directives: - Component directives: These are directives with a template. They are the most common type and are essentially custom HTML elements with associated logic and rendering. - Structural directives: These directives change the DOM layout by adding, removing, or manipulating elements. They are typically prefixed with an asterisk (*). Examples include *ngIf, *ngFor, and *ngSwitch. - Attribute directives: These directives change the appearance or behavior of an existing element, component, or another directive. They are applied as attributes to elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b81db76-6d59-47c6-91f6-57334c127b44', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the C preprocessor differ from the compiler?', N'Middle', N'The preprocessor handles text-based transformations before the actual compilation, such as macro expansion and including header files. The compiler then translates these processed files into machine code, checking for syntax and semantic errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c570bb7e-a8b0-4f1a-a9dc-573388cdf05f', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between the id and class attributes?', N'Intern', N'An id is used to uniquely identify a single element on a page, and it must be unique across the entire document. A class can be used to group multiple elements together, allowing developers to apply the same styles or behaviors to several items.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
