INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cf638a2-795e-477a-8864-5734119ad382', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What factors do you consider when estimating the ''cost of ownership'' for a new microservice?', N'Middle', N'I consider the overhead of infrastructure management, monitoring, logging, and the effort required to maintain service contracts and deployments. I reason about these by looking at the lifecycle of our existing services and determining if the operational burden will require additional headcount or improved automation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0ab41d2-65d7-42dc-99de-57351a2314a4', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of the ''void'' type?', N'Intern', N'The ''void'' type is typically used as a function return type to indicate that the function does not return any value. It signifies that the function performs an action but does not provide a result to the caller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a2eceec-b072-489c-b6c1-5736196ddc38', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why does TypeScript perform structural typing instead of nominal typing?', N'Junior', N'TypeScript uses structural typing to check if the shape of an object matches the expected type, regardless of its name or inheritance hierarchy. This approach is more flexible and aligns better with the dynamic nature of JavaScript objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa9214d9-ffe0-467e-bce0-5739e4ea3ca0', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the difference between constructor injection and field injection, and why constructor injection is preferred.', N'Middle', N'Field injection uses reflection to set dependencies, which makes testing difficult and masks circular dependencies. Constructor injection is preferred because it ensures that beans are immutable, facilitates easier unit testing by allowing manual dependency injection, and makes required dependencies explicit during class instantiation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b6872df-a936-4211-b27d-573ca2ecbe56', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do generics improve the scalability of a frontend codebase?', N'Senior', N'Generics enable the creation of reusable components and utilities that maintain type safety without sacrificing flexibility. By abstracting over specific types, developers can write logic that handles various data structures while ensuring the compiler preserves type information throughout the transformation process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ae051f2-172f-40de-9634-573e842613db', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle authentication state management, and what are the implications for stateless REST APIs?', N'Senior', N'AdonisJS uses an extensible ''Auth'' provider that supports various strategies, including session-based and token-based (JWT) authentication. For stateless APIs, it is critical to configure the guard to bypass session persistence, ensuring the server does not rely on local memory or cookie storage, which is essential for horizontal scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9632a1f-3506-4583-9555-573ecaf961a1', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When asked to estimate a project with vague requirements, what is your strategy?', N'Middle', N'I would break the project down into smaller, manageable chunks and provide a range-based estimate rather than a single fixed number. I would also explicitly document the assumptions made and highlight the specific areas where requirements need clarification before a more precise estimate can be provided.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a76faf89-ea3a-4492-aef2-573fb36287cf', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does the ''Cake Pattern'' achieve dependency injection, and why is it often criticized in modern Scala development?', N'Senior', N'The Cake Pattern uses self-types and mixin composition to assemble complex object graphs at compile time by layering traits. While it provides strong type safety and eliminates the need for reflection, it is criticized for increasing compile times, creating rigid dependency structures, and making testing difficult due to the complexity of the self-type hierarchy. Modern Scala development typically favors constructor-based dependency injection or reader monads to achieve better decoupling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab967b1e-8dbf-4754-9bf4-5740d8e74c08', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why does Rust distinguish between ''mut'' and immutable references?', N'Middle', N'This distinction enforces the principle of aliasing XOR mutability, which prevents data races. By ensuring that you can have either multiple read-only references or exactly one mutable reference at any given time, the compiler guarantees thread safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0e44909-88fb-4098-a708-5741e357c05a', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What are Validation rules in Laravel?', N'Intern', N'Validation rules are used to ensure that the data submitted by users meets specific requirements, such as checking if a field is required, is a valid email format, or meets a minimum length. Laravel provides a simple way to define these rules for any input data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a13852e-0d41-4906-bd3e-574a9defd8e1', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why should you avoid putting non-serializable data, like functions or promises, into the Redux store?', N'Middle', N'Non-serializable data breaks core Redux features like state persistence, time-travel debugging, and hot reloading. Storing these values can also cause unexpected behavior in state serialization tools used by developers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86c7216e-68de-4400-aaa8-574cf8ae83a3', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the trade-offs between synchronous and asynchronous replication in PostgreSQL?', N'Middle', N'Synchronous replication ensures that a transaction is not considered committed until the standby server has acknowledged the write, providing zero data loss at the cost of higher latency. Asynchronous replication allows the primary to commit immediately after writing locally, offering better performance but carrying a risk of data loss if the primary fails before the standby catches up.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd01648fc-f68e-4461-bba6-574d7cb48c97', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the ''Cascade Layers'' feature (@layer) affect large-scale architectural management of CSS?', N'Senior', N'Cascade Layers allow developers to define explicit priority groups for styles, regardless of selector specificity. This eliminates ''specificity wars'' where developers use overly specific selectors just to override existing styles, resulting in cleaner, more maintainable stylesheets in large-scale applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'087c4c3b-60be-415d-b0d8-574e14d0bb5b', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the architectural implications of using Write-Ahead Logging (WAL) for durability?', N'Senior', N'WAL ensures data integrity by appending changes to a log before updating the main data files. This allows the system to survive crashes by replaying the log, effectively decoupling the sequential write performance of the disk from the random access nature of database file updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb631cd0-e14b-4c4f-8656-574ed656dbf5', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the ''refresh'' parameter in an index request, and why should it be avoided in bulk indexing?', N'Senior', N'The ''refresh'' parameter forces an immediate index refresh to make new data searchable, which creates many small segments and places heavy load on the system. During bulk indexing, this causes significant performance degradation; it is better to let the default background refresh process handle index consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5a9d119-e730-4815-8c06-574f771417bd', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the ''event loop starvation'' problem and how is it detected?', N'Senior', N'Starvation occurs when a long-running synchronous block or excessive microtask execution prevents the event loop from moving to the next phase. This is detected using performance monitoring tools that measure ''event loop lag'' or ''latency''—the time elapsed between scheduled events and their actual execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75d4e025-d600-46a5-8e78-5750b5700313', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is TypeScript called a ''superset'' of JavaScript?', N'Fresher', N'TypeScript is called a superset because all valid JavaScript code is also valid TypeScript code. It builds upon JavaScript by adding features like static types, but it does not remove or change the core behavior of the underlying JavaScript language.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'067e416b-899e-486f-ab62-575282f5573a', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the concept of a Foreign Key.', N'Fresher', N'A foreign key is a column that creates a link between two tables by referencing the primary key of another table. It is used to maintain referential integrity, ensuring that relationships between data remain consistent across the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8b4b762-d7d1-4da4-8aa2-5753a50f1204', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is ''Split-Brain'' syndrome and how can it be mitigated?', N'Senior', N'Split-brain occurs when a cluster is partitioned into two or more independent sub-clusters that each believe they are the primary, leading to data corruption. It is typically mitigated by using quorum-based voting mechanisms or a third-party witness node that prevents any partition without a majority from performing writes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94c8b6fd-3de4-490e-932b-5754711f4dfc', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is the order of middleware registration significant in Actix?', N'Senior', N'Middleware in Actix acts like an onion skin; the registration order determines the sequence in which requests pass through them. Incorrect ordering can lead to issues where security middleware is bypassed or logging captures incorrect request states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19021dc3-a778-42be-996a-5754913794a3', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Is Webpack only for JavaScript files?', N'Fresher', N'No, Webpack is designed to bundle any static asset. By using appropriate loaders, it can process and bundle CSS, Sass, images, fonts, and even data files like JSON.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a051345e-5d20-4dc3-a82d-5754db82ef31', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Why does Java use a JIT compiler instead of interpreting bytecode directly?', N'Middle', N'The Just-In-Time compiler translates frequently executed bytecode into native machine code during runtime. This significantly improves performance by allowing the JVM to optimize code based on actual execution patterns rather than relying on slower interpretation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d16f4a1-1223-466b-94b2-575551dd4501', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Can you use standard browser events in Preact?', N'Intern', N'Yes, Preact allows you to use standard browser events like click or change directly in JSX. Preact uses synthetic event delegation to handle these events efficiently across different browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e57f7e4a-ca19-40e5-8ccc-576063d78a70', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the purpose of ''getServerSideProps''?', N'Intern', N'getServerSideProps is a function that fetches data on every request to the server. It is useful for pages that require up-to-date data that changes frequently and cannot be known at build time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d2bcde4-94e9-4ae4-8abb-5762bf0db08c', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Why is it important to implement rate limiting on an API, and what are common strategies to achieve it?', N'Middle', N'Rate limiting protects backend services from spikes in traffic, prevents resource exhaustion, and discourages abuse. Common strategies include the token bucket or leaky bucket algorithms, which can be implemented at the API gateway or load balancer level to enforce quotas per user or IP address.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b6ec23f-be52-48ee-b45f-57690910abfe', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What architectural challenges arise when implementing a custom ClassLoader for hot-swapping code?', N'Senior', N'The primary challenge is managing state transition and ensuring that references to the old class versions are garbage collected without causing memory leaks. If static fields or internal caches hold references to classes loaded by a discarded loader, those classes and their associated metadata remain permanently in the metaspace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbb98e18-310c-4d66-b9c4-576a170e828e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between native, host and user objects', N'Fresher', N'Native objects are objects that are part of the JavaScript language defined by the ECMAScript specification. For example, String, Math, RegExp, Object, Function etc core objects defined in the ECMAScript spec. Host objects are objects provided by the browser or runtime environment (Node). For example, window, XmlHttpRequest, DOM nodes etc are considered as host objects. User objects are objects defined in the javascript code. For example, User objects created for profile information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83b9bce5-4435-4011-8e22-576ab487d81e', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why would you use Webpack instead of just linking multiple script tags in HTML?', N'Intern', N'Using multiple script tags can lead to performance issues, global scope pollution, and complex dependency management. Webpack automates the process, handles dependencies, optimizes file sizes, and makes it easier to manage large-scale projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa4f4b11-0e27-4b5f-a90f-576b2533ea2f', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Can you use global CSS in Astro?', N'Fresher', N'Yes, you can define global CSS files and import them into your base layout component. This ensures that styles are applied across all pages that use that layout.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e364e2fe-ed4a-4874-ab40-576b62d1c5a3', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you ensure strong consistency in a distributed system when an API request spans multiple services?', N'Senior', N'Strong consistency across services often requires distributed transactions, such as the Saga pattern or Two-Phase Commit. Sagas are generally preferred in microservices to avoid long-lived locks, using compensating transactions to handle failures and maintain eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0fa6484-d6c3-4488-b94a-576cd5c52a59', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What are the limitations of the actor model in Actix for distributed systems?', N'Senior', N'The standard Actix actor model is designed for a single-process, multi-threaded context and does not natively support transparent actor distribution across multiple nodes. Scaling horizontally requires additional infrastructure like message brokers or RPC frameworks to bridge the gap between process boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
