INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25a82d75-dd82-4282-b88f-576f6b7bac10', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch achieve high availability?', N'Intern', N'Elasticsearch achieves high availability through sharding and replication. Data is split into shards, and copies of these shards are distributed across multiple nodes in a cluster to ensure data remains accessible if a node fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02fcb8fd-ecee-4cee-a41e-576f8a0af1d4', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the role of the Service Container in Symfony and why is it important?', N'Middle', N'The Service Container manages the instantiation and lifecycle of services within the application. It promotes dependency injection, which decouples components, makes code more testable, and allows for easier configuration management without hardcoding dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37a160f5-a0e4-405d-99e5-576fbddf07aa', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Explain the role of ''APIRouter'' in organizing a growing FastAPI application.', N'Middle', N'APIRouter allows you to group related endpoints into separate modules or files, preventing a single file from becoming unmanageable. This modularity is essential for large-scale applications, as it promotes better code separation and easier team collaboration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3e68287-1d47-4fd3-b6d1-5771727962b6', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is an ''HTTPServer'' in Actix-web?', N'Intern', N'The HTTPServer is the component responsible for listening on a network port, accepting incoming TCP connections, and passing them to the application for processing. It manages the pool of worker threads that serve the requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5246b220-cb92-4403-bc86-5773ac858149', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the role of request validation in API security?', N'Middle', N'Request validation ensures that incoming data conforms to expected types, lengths, and formats before reaching business logic. This prevents common attacks like SQL injection and cross-site scripting by ensuring only clean, expected data is processed by the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bdaa685-478e-4b4b-8577-5773b7f7c8f3', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How would you handle a scenario where a consumer is consistently slower than the producer?', N'Middle', N'You should scale the consumer group horizontally by adding more instances to share the workload. If the architecture allows, you could also optimize the consumer processing logic or increase the number of partitions to enable more concurrent consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10316795-ecb5-4684-b7c2-5773e5f5f311', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a shard in Elasticsearch?', N'Intern', N'A shard is a single instance of a Lucene index, which acts as a low-level worker unit that holds a slice of the data. Sharding allows Elasticsearch to distribute data across multiple nodes in a cluster to handle large datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'129a5ff4-4190-4aff-b902-577589a7090c', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the primary architectural difference between using ''def'' and ''async def'' in FastAPI path operations?', N'Middle', N'Using ''def'' causes the function to run in an external thread pool to prevent blocking the main event loop, while ''async def'' allows the function to be called directly by the event loop. ''Async def'' is more efficient for I/O-bound operations as it avoids the overhead of context switching between threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f7b0155-b806-412e-99c0-57763c51b661', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle DOM-based scope inheritance, and what are the implications for performance?', N'Senior', N'Alpine.js uses a hierarchical scope chain where nested components inherit data from parent components via the DOM tree. While this is intuitive for developers, deep nesting can lead to performance overhead during data resolution because the engine must traverse up the DOM tree to find property definitions, which can be expensive if not managed carefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd91d770d-b43e-4563-b9bc-5777df2eb02c', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do you share styles across multiple Lit components?', N'Junior', N'You can share styles by creating a CSSResult object using the ''css'' tag and exporting it. This constant can then be included in the ''styles'' array of any component that needs those specific styles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2568eaa0-8a1a-49a1-83a1-57781682e5c3', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Does Hono support TypeScript?', N'Intern', N'Yes, Hono is written in TypeScript and provides excellent type support out of the box. This allows for better developer experience, including autocompletion and type safety for routes and middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54e1f6a1-79df-4b13-b90f-577b335277b0', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Explain the role of the Startup class.', N'Intern', N'The Startup class is the entry point for configuring the application''s request pipeline and services. It allows developers to define middleware components and register services in the dependency injection container.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb4b9fd9-b384-4b3e-a9cc-577b352c9bc0', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Why is it important to monitor ''deadlocks'' in a database?', N'Middle', N'Deadlocks occur when two or more transactions hold locks that the others need, causing them to wait indefinitely. Monitoring helps identify poorly designed transactions or missing indexes that contribute to these cycles, allowing for performance tuning and improved concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1cb2576-d687-456a-bcff-577bb6d25039', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle memory fragmentation, and why does it matter?', N'Middle', N'Memory fragmentation occurs when the memory allocator cannot reuse small, freed blocks of memory, leading to wasted space. Redis exposes metrics to monitor fragmentation, and it can be mitigated by configuring the memory allocator or periodically restarting instances to reclaim allocated memory from the operating system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd76dface-cb70-4da9-a108-577d908d0dde', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the impact of using Gin''s ''ShouldBind'' versus ''Bind'' methods in terms of request validation?', N'Senior', N'The ''Bind'' method automatically writes a 400 Bad Request status if validation fails, while ''ShouldBind'' returns the error to the caller without modifying the response. ''ShouldBind'' is preferred in production for finer control over error formatting and status code customization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd31e53b-f5d1-404e-98ac-577deb9e0269', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How do Redis eviction policies like LRU and LFU handle memory pressure?', N'Senior', N'LRU (Least Recently Used) evicts keys that have not been accessed for the longest time, while LFU (Least Frequently Used) tracks access frequency to evict less popular keys. These policies allow Redis to maintain a fixed memory footprint by automatically removing less valuable data when limits are reached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26efa2db-a61e-4713-8dc3-5780e2f70a8b', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are the security implications of using FastAPI''s dependency injection for authentication?', N'Senior', N'Dependency injection allows for clean, reusable security schemes like OAuth2 or API keys. By centralizing authentication logic in dependencies, you ensure consistent security enforcement across endpoints, reducing the risk of human error or bypassed checks in new routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
