INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc066918-9b09-4f2c-94d7-57863e7578a2', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why should you avoid using the ''goto'' statement?', N'Junior', N'The ''goto'' statement allows jumping to arbitrary points in code, which often leads to ''spaghetti code'' that is difficult to read and debug. It breaks the structured flow of control, making it hard to follow the execution path. Most logic can be expressed more cleanly using standard loops and conditional statements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
