INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd648e437-6dcd-43a5-baf1-578744f591e2', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the Atomicity property of a transaction.', N'Junior', N'Atomicity ensures that a transaction is treated as a single ''all-or-nothing'' unit. If any part of the transaction fails, the entire transaction is aborted, and the database is rolled back to its state before the transaction started.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d43fad7-576a-47de-bc83-5788025a6a87', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of the Ember Run Loop?', N'Middle', N'The Run Loop is a mechanism that batches and sequences tasks such as DOM updates, data binding synchronization, and event processing. By grouping these tasks, Ember minimizes browser reflows and ensures that the application state remains consistent during complex operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a150dad-cadd-49b0-bf9c-578bd8f7459c', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Explain the role of ''Middlewares'' in the Actix-web request lifecycle.', N'Middle', N'Middlewares wrap the request/response lifecycle, allowing developers to execute code before a handler is called or after a response is generated. They are commonly used for logging, request validation, authentication, and modifying headers globally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65d349d1-c934-413c-a803-578d309b9e39', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the Rails ''strong parameters'' feature?', N'Middle', N'Strong parameters prevent mass assignment vulnerabilities by requiring developers to explicitly whitelist the attributes that can be updated via web requests. This ensures that malicious users cannot modify sensitive fields, such as administrative flags, by injecting extra parameters into the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43007e5f-6f5f-4aec-bfb2-578f0f1f6b91', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the ROLLBACK command?', N'Fresher', N'The ROLLBACK command is used to undo changes made during the current transaction that have not yet been committed. It returns the database to the state it was in before the transaction began.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee3274de-2be1-464d-8735-5790ac7a6c0b', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you ensure data integrity in a system that relies on eventual consistency?', N'Senior', N'I implement compensating transactions or sagas to handle failure scenarios where distributed transactions are not feasible. I also incorporate idempotent operations and periodic reconciliation jobs to detect and correct discrepancies between disparate data stores.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41292ed4-5b6e-4040-975c-5794ccf7605f', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why is schema flexibility considered a primary advantage of NoSQL?', N'Middle', N'Schema flexibility allows developers to store data without a predefined, rigid structure, accommodating evolving data requirements without downtime or complex migrations. This is particularly beneficial for agile development cycles and applications dealing with unstructured or polymorphic data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed04891a-f85d-4b16-b8a0-5795272ae798', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What architectural patterns help protect against SQL injection beyond simple parameterized queries?', N'Senior', N'Architectural defenses include using ORMs that abstract database interactions, implementing strict input validation at the API layer, and enforcing the principle of least privilege on database service accounts. Furthermore, utilizing database firewalls and monitoring for anomalous query patterns provides an additional layer of detection and prevention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'757c75b5-d573-4c42-9ab0-5797d07b0590', N'954a0331-deff-4399-b588-96f39fec001d', N'How does the ''DestroyRef'' utility improve upon the traditional ''ngOnDestroy'' lifecycle hook?', N'Senior', N'DestroyRef allows for the registration of cleanup logic outside of a component''s lifecycle methods, making it highly useful for functional composition and reusable utilities. It prevents the need to clutter component classes with lifecycle hooks, enabling cleaner implementation of cleanup logic for subscriptions, timers, or event listeners.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6810e7f6-ee07-4a75-b791-57a09932aa95', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is PostgreSQL''s write-ahead logging (WAL)?', N'Intern', N'WAL is a standard method for ensuring data integrity by recording changes to data files before the changes are actually applied. This allows the database to recover to a consistent state after a crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbe27749-6c5f-490a-b0c5-57a3eb218352', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Does Vite provide a way to proxy API requests during development?', N'Intern', N'Yes, Vite allows you to configure a proxy server to redirect API requests. This is useful for bypassing CORS issues during development by pointing local requests to a backend server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5d42af1-186e-4795-9c4d-57a4462cc1bb', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of the Swift ''Result'' type in terms of error propagation and type safety?', N'Senior', N'The Result type encapsulates the outcome of an operation into a discrete success or failure case, forcing the caller to explicitly handle the error path. This improves type safety by replacing implicit error propagation with a formal, exhaustive pattern-matching requirement at compile time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1504dc30-28d7-44b3-9b59-57a44e1cefb2', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle property reflection to attributes and what are the performance considerations?', N'Senior', N'Property reflection keeps the DOM attribute in sync with the JavaScript property, which is necessary for CSS attribute selectors and accessibility labels. However, it involves synchronous DOM writes which can be expensive if triggered frequently, so it should be used sparingly for data that needs to be accessed by external scripts or CSS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78ab2190-fc2f-48c3-bac0-57a48d3b5a8b', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro handle API routes and server-side logic?', N'Senior', N'Astro supports API routes via server-side endpoints, which are executed during build time for SSG or at request time for SSR. This allows developers to handle data fetching, authentication, and database interactions within the same project structure without needing a separate backend service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c1a8329-7dd6-4749-a838-57a4a9616841', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Can you define custom status codes in Fastify?', N'Junior', N'Yes, you can set a custom status code by using the reply.code() method before sending your response. This gives you full control over the HTTP status returned to the client for any given route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97cc1ced-db15-4708-99f1-57a58eab4b48', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is a ''load'' function''s ''event'' object?', N'Intern', N'The event object passed to a load function contains useful information about the request, such as parameters from the URL, cookies, and local data. It provides the necessary context to fetch the right data for the current page request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7455ad0-31a0-4237-b28e-57a6c60b1235', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Is Echo thread-safe for concurrent requests?', N'Junior', N'Yes, Echo is designed to handle concurrent requests by spawning a new goroutine for each incoming HTTP request. Because it does not maintain global state in the router, it is safe to use in a multi-threaded environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a4e0cf3-f7fa-425e-aa65-57a6ea98ebb9', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why is ''Denormalization'' a common practice in DynamoDB design?', N'Middle', N'Since DynamoDB does not support complex joins, data is denormalized to store all required information for a specific access pattern in a single item or a small number of items. This improves read performance by allowing a single request to retrieve all necessary data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a0cfc04-1af7-4f35-b1f5-57a7256177b9', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the benefit of Hono''s ''app.mount'' functionality?', N'Middle', N'The mount functionality allows developers to combine multiple Hono applications into a single entry point. This promotes a modular architecture where different services or sub-applications can be developed independently and then composed together.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11abcf97-93b0-4b5f-83a3-57a99e69a9bb', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the update lifecycle in Lit?', N'Intern', N'The update lifecycle is the process Lit follows when a reactive property changes. It includes checking if an update is needed, performing the update by calling the render method, and then updating the DOM to match the new template.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03b4e337-1fa2-4a6b-8771-57ab0feab1b5', N'4c000000-0000-0000-0000-000000000005', N'Why is database replication used?', N'Middle', N'Replication involves copying data from a primary database to one or more replicas to improve read performance and provide high availability. If the primary node fails, a replica can be promoted to take over, minimizing downtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'851f267b-7970-4106-a1b7-57ac078b0830', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of the express.json() middleware?', N'Intern', N'The express.json() middleware is a built-in function that parses incoming requests with JSON payloads. It is necessary to populate the request body property with the parsed data so that it can be accessed by route handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fd2e803-8862-4aea-8149-57ae77bd0088', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django’s caching framework work and what are the benefits of using a distributed cache like Redis?', N'Middle', N'Django provides a unified interface to store frequently accessed data in memory to reduce database load. Using a distributed cache like Redis is superior to local memory caching because it persists data across multiple application server instances and supports complex data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e12a17ba-35f2-459b-9756-57b0b29de7c3', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Describe the trade-offs of using Symfony''s ''Serializer'' component for API development versus custom hydration logic.', N'Senior', N'The Serializer provides a powerful, configurable way to map complex objects to formats like JSON, significantly reducing manual transformation code. The trade-off is higher abstraction complexity and potentially slower performance compared to hand-written hydration logic for extremely simple or high-throughput endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba6607a7-f72a-43d8-9669-57b0f32a3ad8', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is a source map?', N'Intern', N'A source map is a file that maps the bundled, minified code back to the original source files. It is essential for debugging because it allows developers to see the original code in browser developer tools instead of the transformed production code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'595f4de9-cdaf-48a4-b163-57b32d2ce05a', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why does Go prefer static linking by default?', N'Middle', N'Static linking bundles all necessary libraries into a single binary, making deployment simple and eliminating dependency hell on the target machine. This is a cornerstone of Go''s philosophy, enabling easy distribution of portable binaries that run reliably across different operating systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62ef7a39-8fec-4df9-9209-57b372cfeea1', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are the trade-offs in using R''s ''serialize'' and ''unserialize'' for inter-process communication?', N'Senior', N'These functions allow R objects to be converted into a machine-independent binary stream, which is essential for distributed computing and saving state. However, the overhead of serialization can be substantial for very large objects, and it does not inherently support sharing memory between processes without external data stores.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6dd330e9-689d-4104-904c-57b45ebc74c3', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the ''proxy'' setting in Vite?', N'Fresher', N'The proxy setting is used during development to redirect API requests to a backend server. This helps avoid CORS issues by making the browser think the API request is coming from the same origin as the Vite dev server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03d70492-020d-4069-9756-57b615d4d7c1', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are the trade-offs of using Svelte''s built-in animation and transition engine?', N'Middle', N'Using the built-in engine provides a declarative way to handle complex UI transitions with minimal code and high performance. The trade-off is that it can increase the final bundle size and is less flexible than using specialized animation libraries for highly complex, physics-based simulations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d68d882-b259-474f-ab82-57b6e2c25159', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is hydration in Nuxt?', N'Intern', N'Hydration is the process where the static HTML sent by the server becomes interactive in the browser. It involves attaching event listeners and initializing the Vue.js framework so the page responds to user actions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7444a1c-b8e8-4cda-a457-57b8a6bed057', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the role of the meta function?', N'Junior', N'The meta function allows you to define document metadata, such as the page title and description tags, for each route. This is essential for SEO and how your page appears when shared on social media.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbcc509b-e31b-4c0e-b8b5-57bb60e3d861', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift achieve protocol-oriented programming?', N'Middle', N'Protocol-oriented programming allows developers to define behavior through protocols rather than class hierarchies. By using protocol extensions, developers can provide default implementations for methods, enabling code reuse across different types without the limitations of single inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c213c00c-12b4-4807-b220-57bde7f8a175', N'a2838158-7305-480a-b22b-4dc35776b400', N'Explain the concept of ''Causal Consistency'' and its utility in distributed social networks.', N'Senior', N'Causal consistency ensures that operations that are causally related are seen by all nodes in the same order, while concurrent operations can be seen in different orders. It is a stronger model than eventual consistency but less restrictive than linearizability. It is ideal for social networks, where it is important that a reply to a comment is always seen after the comment itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79d7e3fc-ca1b-4735-bac7-57bebb2926be', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you optimize the performance of async validators?', N'Senior', N'Since all validators run after every form value change, it creates a major impact on performance with async validators by hitting the external API on each keystroke. This situation can be avoided by delaying the form validity by changing the updateOn property from change (default) to submit or blur. The usage would be different based on form types, 1. Template-driven forms: Set the property on ngModelOptions directive 2. Reactive-forms: Set the property on FormControl instance', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25f0814b-c291-4da9-ba30-57bec92569a1', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the benefits of using arrow function over es5 function?', N'Intern', N'Arrows is a new syntax for functions, which brings several benefits: * Arrow syntax automatically binds this to the surrounding code''s context * The syntax allows an implicit return when there is no body block, resulting in shorter and simpler code in some cases * Last but not least, => is shorter and simpler than function, although stylistic issues are often subjective Example 01: Arrow Function with No Argument If a function doesn''t take any argument, then you should use empty parentheses. Example 02: Arrow Function with One Argument If a function has only one argument, you can omit the parentheses. Example 03: Arrow Function as an Expression You can also dynamically create a function and use it as an expression.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed6abd69-1c8b-4293-8515-57c1be00ed3f', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the relationship between Qwik and TypeScript?', N'Junior', N'Qwik is built with TypeScript and provides excellent support for it. Type safety is encouraged throughout the application, ensuring that state objects, loaders, and props are correctly defined and validated during development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29861fdd-5ef9-4d9e-83f8-57c3e47b8f83', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How do you define a route that handles multiple HTTP methods in Chi?', N'Junior', N'You can use the Method method to specify multiple HTTP verbs for a single handler. Alternatively, you can define separate routes for each method if the logic for each verb is significantly different.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbcb896f-ec65-44b7-942d-57c5f4fb00f3', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What does a database backup do?', N'Junior', N'A backup creates a copy of the database data at a specific point in time. This copy can be used to restore the database in the event of hardware failure, corruption, or human error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1300ad98-4637-4093-b17b-57c675e0d93c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you access history in javascript?', N'Fresher', N'The window.history object allows you to access the history stack of the browser. To navigate to a URL in the history, you use the back(), forward(), and go() methods. The history.length returns the number of URLs in the history stack. 1. Move backward: 2. Move forward: 3. Move to a specific URL in the history: To move to a specific URL in the history stack, you use the go() method. The go() method accepts an integer that is the relative position to the current page. The current page''s position is 0. 4. Check history stack:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de553368-7846-446e-bb23-57c6cb1f0824', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the main advantage of using a message broker like RabbitMQ compared to a distributed log like Apache Kafka?', N'Middle', N'RabbitMQ is designed as a traditional message broker with complex routing capabilities and support for multiple exchange types. Kafka acts as a distributed commit log, which excels at high-throughput event streaming and allows consumers to replay messages from specific offsets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56b21702-9455-4e07-a889-57cd5e3f5f63', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What makes Hono ''fast''?', N'Fresher', N'Hono is fast because it is built with a highly optimized router and avoids heavy dependencies. It focuses on doing only what is necessary, which minimizes overhead and maximizes execution speed on constrained environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'967de329-641d-4aae-b154-57ce6e9ae030', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the role of the EventDispatcher component in a decoupled architecture.', N'Senior', N'The EventDispatcher implements the mediator pattern, allowing components to communicate without direct dependencies by triggering and listening for events. This promotes a plugin-based architecture where third-party bundles can alter application behavior without modifying the core codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30ea435a-c281-449f-9a5f-57ce854d4298', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is an ObjectId?', N'Intern', N'An ObjectId is a 12-byte identifier used as the default value for the _id field. It is designed to be globally unique, generated using a combination of a timestamp, machine ID, process ID, and an incrementing counter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2153d06b-7e38-483a-a18f-57cfe48a96a8', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Why would you use a database index?', N'Junior', N'An index is used to speed up the retrieval of data from a database table. It functions like an index in a book, allowing the database engine to find specific rows much faster without having to scan every row in the table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
