INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f076600-808b-4c23-9db5-57d2a48b7db3', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do you handle ''this'' context in TypeScript classes or functions?', N'Middle', N'TypeScript allows you to specify the ''this'' parameter in a function signature, which defines the expected context for the function. For classes, you can use arrow functions for methods to lexical-bind ''this'' to the class instance. This prevents common bugs where the ''this'' reference is lost during callbacks or event handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
