INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b3e6b53-69bc-426a-9a73-57d81a084c87', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What does ''duck typing'' mean in Ruby?', N'Intern', N'Duck typing is a concept where the type of an object is determined by the methods it responds to rather than its actual class. If it walks like a duck and quacks like a duck, it is treated as a duck, regardless of its inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08c90a5c-f519-4c57-881d-57d9189d6e82', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How are exceptions handled globally in ASP.NET Core?', N'Fresher', N'ASP.NET Core uses global exception handling middleware to catch unhandled exceptions that occur during the request pipeline. This allows developers to log errors and return a consistent, user-friendly error response instead of exposing internal stack traces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a22bf59-adc3-4d32-bcfc-57da202cd4c4', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the PYTHONPATH variable?', N'Intern', N'PYTHONPATH is the variable that tells the interpreter where to locate the module files imported into a program. Hence, it must include the Python source library directory and the directories containing Python source code. You can manually set PYTHONPATH, but usually, the Python installer will preset it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3303baa-cc16-4e57-865f-57daf2361038', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What are the trade-offs of using ''Heartbeat'' mechanisms for failure detection?', N'Senior', N'Heartbeats are simple to implement for verifying node liveness, but they can generate significant network traffic in large clusters. Furthermore, they are susceptible to ''false positives'' if network congestion delays the heartbeat, potentially triggering unnecessary and expensive failover procedures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c02d3f3-f4f2-4b1c-9da7-57de9b89bba7', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What are the performance implications of using Alpine''s ''x-init'' for complex data fetching?', N'Senior', N'Using ''x-init'' to trigger data fetching couples the component''s lifecycle directly to external API calls, which can lead to issues if the component is mounted and unmounted frequently. If not carefully managed with abort controllers or state flags, it can cause race conditions or unnecessary network traffic. It is often better to pass initialized data to the component rather than having it handle its own data fetching logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87b02875-fb14-43a6-af75-57e153d42360', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Under what circumstances would you choose Redis Streams over Pub/Sub or Lists?', N'Senior', N'Redis Streams are preferred when message persistence, consumer groups, and acknowledgment tracking are required for reliable message processing. Unlike Pub/Sub, streams store messages in memory, allowing clients to consume missed data and track progress through consumer groups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81e5fbd5-6cc8-43f9-9088-57e47f275df2', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is Cassandra''s write performance generally faster than its read performance?', N'Intern', N'Cassandra uses an append-only architecture for writes, which avoids expensive disk seeks by writing to the commit log and memtable. Reads often require checking multiple SSTables, which can involve disk I/O, making them more resource-intensive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'600eb636-6447-441b-86a1-57e5ddde798c', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the trade-offs of using pointers in Go compared to passing by value.', N'Middle', N'Passing by value creates a copy of the data, which is safe but can be expensive for large structs. Pointers avoid copying but introduce potential side effects and require care to ensure the referenced data remains valid for the duration of its use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9af0a94f-5a0c-47ef-8ad6-57e7a878fb50', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''keyof'' operator?', N'Intern', N'The ''keyof'' operator takes an object type and produces a string or numeric literal union of its keys. It is very useful for functions that need to safely access object properties based on dynamic keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
