INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb9ca4af-00b5-448b-a6f1-57f168e9a3f8', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux differ from the React Context API?', N'Fresher', N'Redux is a standalone library for complex state management with features like middleware and dev tools, while Context API is a built-in React feature for simple prop drilling avoidance. Redux is better for large-scale global state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35ee456a-d899-4f1f-96dc-57f5cced8131', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Why is it important to consider the ''Painting'' phase when optimizing CSS animations?', N'Senior', N'Animations that change properties like height, width, or top/left trigger a layout reflow on every frame, which is extremely expensive. Animating properties like transform or opacity allows the browser to offload the work to the compositor thread, resulting in smooth 60fps performance without recalculating the DOM layout.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ccb5cb7-b390-47dd-aa4d-57f896a604de', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does the `traceback` module interact with the Python interpreter''s stack unwinding process?', N'Senior', N'When an exception is raised, the interpreter traverses the call stack to find a handler, building a traceback object along the way. The `traceback` module provides tools to inspect these objects, allowing for custom logging or presentation of the call stack at the point of failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9ffb182-c8d0-4647-a964-57fc0501820f', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the purpose of the ''print'' function?', N'Intern', N'The print function is used to display the value of an object or a message in the R console. It is often used within functions or loops to output progress updates or results to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07a8df4f-90c4-43be-9e1a-57fd507b85cf', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle event listeners?', N'Intern', N'Events are handled by adding standard browser event listeners to elements within the render method. Lit makes this easy by allowing you to bind event handlers directly in the template using the at-sign syntax.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b73ff710-3c5e-4922-a84f-57fd655617e1', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What are the trade-offs of using Litestar''s automatic OpenAPI schema generation?', N'Middle', N'The primary benefit is reduced boilerplate and guaranteed synchronization between code and documentation. However, it requires strict adherence to type hinting, and complex data structures might require explicit schema configuration to be documented accurately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4dbb9d82-6bd4-4f53-91b3-57fdeb940aeb', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the benefit of using React Server Components (RSC) in a Next.js application regarding performance?', N'Middle', N'RSC significantly improves performance by keeping large dependencies and data-fetching logic on the server, ensuring they are never sent to the client''s browser. This reduces the total JavaScript bundle size, leading to faster execution and improved Core Web Vitals. Additionally, since server components can query databases directly, it eliminates the need for extra API endpoints and reduces the waterfall of network requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d47d104-706c-43cc-9d48-57ff80eb90b3', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the architectural role of Swift''s ''Existential Containers''?', N'Senior', N'Existential containers are the internal implementation detail for protocol types, storing a value of any conforming type and its corresponding witness table. They provide runtime polymorphism, but they incur a performance cost due to the indirection required to access the underlying value and its methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f08e8a16-c0f5-4831-a200-58012609da14', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Explain the trade-offs of using JIT (Just-in-Time) mode compared to the traditional AOT (Ahead-of-Time) generation.', N'Senior', N'JIT mode generates styles on-demand based on the source files, enabling arbitrary values and significantly faster build times for large projects. AOT generation processes the entire utility set upfront, which can result in massive CSS files unless aggressive purging is configured.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cd900b5-9b26-4bff-b547-58013417183a', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you weigh the trade-offs of using a schema-less design versus a strictly typed schema?', N'Senior', N'Strictly typed schemas provide strong validation and better performance through database optimization, which is vital for long-term data integrity. Schema-less designs offer rapid iteration for early-stage prototypes, but they place the burden of data validation on the application layer, which often leads to technical debt as the data grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2e1b26c-ffb4-4ba3-ba3e-58018cf6348f', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the significance of the ''Start'' method in Echo?', N'Intern', N'The Start method initializes the HTTP server and begins listening for incoming requests on a specified network address. It is the entry point that keeps the application running.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e63630d1-50c9-4f2d-9623-58024088dff1', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of the ''Response'' class in FastAPI?', N'Fresher', N'The Response class is the base class for all responses in FastAPI. It allows you to manually control the response content, status code, and headers if the automatic JSON serialization is not sufficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd12057cf-3f79-4010-bd7d-5803ba5ccf39', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the role of the ''Repository'' pattern when used with Litestar?', N'Middle', N'While not strictly required, the repository pattern is often used with Litestar to decouple the business logic from the database implementation. This makes unit testing easier, as you can replace the database repository with an in-memory version without changing the handler logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2343d358-3b33-4c14-a0b0-5805ec0cd43a', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the impact of V8''s hidden classes and inline caching on Node.js performance?', N'Senior', N'V8 optimizes property access by creating hidden classes for objects with the same structure, allowing for faster property lookups. If objects change shape dynamically, V8 de-optimizes the code to dictionary mode, significantly slowing down performance. Maintaining consistent object shapes is critical for high-performance Node.js applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c524f4d5-5b93-4eec-91ba-580601511ba0', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind''s approach to ''Style Encapsulation'' differ from Shadow DOM?', N'Middle', N'Tailwind does not provide style encapsulation by default; it relies on standard CSS global scoping. Shadow DOM provides true style isolation by creating a boundary that prevents outside CSS from affecting the component, whereas Tailwind simply provides a consistent way to write styles that are globally applicable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70174ada-70da-4642-a69a-5806d391a269', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are the architectural implications of Ruby''s Global Interpreter Lock (GIL) on concurrency and parallelism?', N'Senior', N'The GIL prevents multiple native threads from executing Ruby bytecode simultaneously, effectively limiting CPU-bound tasks to a single core per process. While it simplifies memory management and C extension safety, it forces developers to use multi-process architectures like Unicorn or Puma cluster mode to achieve true parallelism for compute-intensive workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7efad4c7-8065-4079-a76b-580763b5b996', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the benefit of using ''Edge'' template engine?', N'Junior', N'Edge provides a clean syntax for writing HTML templates with features like layouts, components, and partials. It is designed to be secure by automatically escaping output to prevent cross-site scripting attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45efe0fa-5bb9-4625-85cf-5808886f8a8b', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do Ember''s ''Modifiers'' improve the management of DOM-related side effects?', N'Senior', N'Modifiers provide a clean way to attach behavior to specific DOM elements, such as third-party library initializations or event listeners. They cleanly separate DOM-specific logic from the component''s state, ensuring that resources are cleaned up automatically when the element is removed from the template.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd89b69f0-962a-4446-ae92-58088c6bc6da', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the impact of the ''Flush Log'' setting (innodb_flush_log_at_trx_commit) on ACID compliance versus throughput.', N'Senior', N'Setting this to 1 ensures full ACID compliance by flushing the redo log to disk at every commit, but it creates a massive I/O bottleneck. Values of 0 or 2 improve performance significantly by delaying the flush, but they introduce the risk of losing up to one second of transactions in a crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c65c9fe-416b-445a-90e3-5808a7f99a97', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you evaluate the trade-off between consistency and availability in a distributed system during a network partition?', N'Senior', N'I analyze the business requirements to determine if stale data is acceptable or if the system must prioritize correctness. I would then implement strategies like tunable consistency levels or eventual consistency models, ensuring the chosen architecture aligns with the specific failure tolerance thresholds of the service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a0f931a-441e-4464-826f-580bff437207', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the purpose of database connection pooling in a scalable application?', N'Middle', N'Connection pooling maintains a cache of database connections that can be reused for future requests, rather than opening a new connection each time. This reduces the overhead of establishing connections, preventing the database from becoming a bottleneck as the number of concurrent users grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
