INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6069df9-a9a0-4fbf-902c-5811a6087a43', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What does it mean for C++ to be a statically typed language?', N'Intern', N'Being statically typed means that variable types are checked during the compilation process rather than while the program is running. This allows the compiler to catch type-related errors early and optimizes memory allocation for those specific types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'065dabd0-0401-4bf0-a3f7-581388436902', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Discuss the implications of Chi’s routing pattern matching on security, specifically regarding path traversal.', N'Senior', N'Chi provides strict path cleaning and normalization, which mitigates common path traversal vulnerabilities. By ensuring that requested URLs are sanitized before route matching, it prevents attackers from exploiting directory navigation patterns that might otherwise bypass intended authorization layers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2513dda9-f713-49b5-aa25-5813e2cbdffd', N'075b8862-431c-4678-9767-f55359758a4a', N'Explain the concept of ''prop drilling'' and how it is solved in Vue.', N'Middle', N'Prop drilling occurs when data must be passed through multiple layers of components that do not need it. It is solved using provide/inject for dependency injection or state management libraries like Pinia for global state accessibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2ee4751-f17e-4eec-a7d2-5815b6373085', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the differences between ES6 class and ES5 function constructors?', N'Intern', N'Classes are a template for creating objects. They encapsulate data with code to work on that data. Classes in JS are built on prototypes but also have some syntax and semantics that are not shared with ES5 class-like semantics. ES6 Classes formalize the common JavaScript pattern of simulating class-like inheritance hierarchies using functions and prototypes. They are effectively simple sugaring over prototype-based OO, offering a convenient declarative form for class patterns which encourage interoperability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18c3542a-82b2-4e87-b8c3-5817c521591b', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How can you define a route parameter in Gin?', N'Intern', N'Route parameters are defined by using a colon followed by a name in the URL path, such as ''/user/:id''. Gin captures the value provided in that position and allows you to access it using the Param method on the context object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b4a3738-73bb-46e1-83d3-5818de66fc1c', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the role of the ''Consumer Group'' pattern in distributed queues, and how does it affect scalability?', N'Senior', N'The consumer group pattern enables horizontal scalability by partitioning a message stream across multiple consumers, ensuring each message is processed by only one instance within the group. By increasing the number of partitions and associated consumers, the system can parallelize throughput to match the workload, provided the processing logic is thread-safe and stateless.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2f6dac0-4bba-48c5-9c69-581977f91611', N'075b8862-431c-4678-9767-f55359758a4a', N'What are plugins in vue CLI?', N'Intern', N'Vue CLI uses a plugin-based architecture where each plugin can modify the internal webpack configuration and inject commands to vue-cli-service. i.e, Each feature is implemented as a plugin. This architecture makes Vue CLI flexible and extensible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d0a30c0-3e0a-44d5-b46a-581a94aa367d', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between a constructor and a method?', N'Junior', N'A constructor is a special type of method used to initialize objects, and it has the same name as the class with no return type. A regular method is used to define the behavior of an object and must have a return type or void.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7036f7ce-4e38-4a70-9648-581d86bcb3e3', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar approach the ''N+1'' query problem within its serialization and response pipeline?', N'Senior', N'Litestar does not implicitly solve the N+1 problem, but its DTO and serialization architecture encourages the use of data transfer objects that can be pre-fetched or optimized before response construction. Architects must implement efficient data fetching strategies in the service layer to ensure that the serialization process does not trigger excessive database roundtrips.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fbb964e-f99b-4355-8eb9-581e43f69c24', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to add Bootstrap to a react application?', N'Fresher', N'Bootstrap can be added to your React app in a three possible ways, 1. Using the Bootstrap CDN: This is the easiest way to add bootstrap. Add both bootstrap CSS and JS resources in a head tag. 2. Bootstrap as Dependency: If you are using a build tool or a module bundler such as Webpack, then this is the preferred option for adding Bootstrap to your React application 3. React Bootstrap Package: In this case, you can add Bootstrap to our React app is by using a package that has rebuilt Bootstrap components to work particularly as React components. Below packages are popular in this category, 1. react-bootstrap 2. reactstrap', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88d36314-f44a-4b05-aa00-581eb46409b6', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are Webpack aliases?', N'Junior', N'Aliases are a way to create shorter or easier names for import paths in your project. They help avoid deep relative path nesting, such as using @components instead of ../../components/.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4cb601f-7f4d-426a-8eaa-58208dde8650', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are input types in HTML?', N'Intern', N'Input types define the nature of the data a user can enter into a form field, such as text, password, email, or date. Specifying the correct type helps browsers provide the appropriate interface for the user, like a calendar picker for dates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'751d6913-a90f-44cf-959b-5821259cbb87', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the main benefit of using ''Controllers'' in Litestar?', N'Junior', N'Controllers allow for object-oriented organization of route handlers. By grouping related endpoints in a class, you can share common dependencies and configuration, making your codebase easier to navigate and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28bd4b0c-22c4-4de1-957c-5823954d1664', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is a pointer, and why is it useful?', N'Junior', N'A pointer is a variable that stores the memory address of another variable. Pointers are essential for dynamic memory management, efficient array manipulation, and passing large data structures to functions without copying them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e737fe18-c664-4812-9f1f-582410c40345', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What does the ''c.Redirect'' method do in Echo?', N'Junior', N'The c.Redirect method instructs the client to navigate to a different URL. It typically sets the Location header and returns a 3xx status code to the browser or API client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f2e23de-85be-45d1-98e3-58259a77a99b', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is it important to include guard clauses in header files?', N'Junior', N'Guard clauses, usually implemented with #ifndef and #define directives, prevent a header file from being included multiple times in the same compilation unit. This avoids errors caused by double definitions of variables or functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'009b53b1-00f6-408e-97e8-5827c5674c01', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of database sharding?', N'Middle', N'Sharding is a horizontal partitioning strategy that divides a large dataset into smaller, more manageable chunks across multiple database servers. It is used to distribute the load, increase write throughput, and bypass the storage limitations of a single machine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c76a3980-03c6-4fb1-87b9-582befc9e113', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Explain the mechanism of Hot Module Replacement (HMR) in Vite and its performance implications.', N'Senior', N'Vite performs HMR over native ESM via WebSocket connections. When a file changes, Vite invalidates the module chain and instructs the browser to re-fetch only the affected module, ensuring consistent state updates without a full page reload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d20c1ed-a28b-49e2-84d9-582c76c00877', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the main challenge of implementing a microservices architecture in a small team?', N'Middle', N'The primary challenge is the significant operational overhead, including managing deployment pipelines, service monitoring, and infrastructure complexity. For small teams, the cost of managing these distributed systems often outweighs the benefits of modularity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb4612e2-6822-480e-9fa4-582cd14c1440', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the difference between a service and a controller?', N'Intern', N'A controller is a specific type of service focused on handling incoming HTTP requests and returning responses. A service is a general-purpose class that contains specific business logic, utility functions, or database interactions that can be reused throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e841698b-f071-49d7-a757-5830df769146', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify''s plugin loading order affect the application lifecycle and dependency resolution?', N'Senior', N'Fastify loads plugins sequentially based on the order of declaration, ensuring that parent contexts are fully registered before child plugins execute. This deterministic ordering is critical for managing dependencies, such as database connections or authentication layers, that must be ready before route handlers are invoked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd30491eb-9bbf-4aa7-941a-58322a163304', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How do Tailwind''s ''arbitrary values'' impact the strictness of a frontend design system?', N'Senior', N'Arbitrary values allow for one-off design adjustments that bypass the predefined design system tokens. In a senior-level architecture, these should be strictly governed or linted against, as excessive use leads to design drift and violates the core intent of using a utility-first framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8b9deb9-2059-436f-adad-5833efed2f82', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the primary metric Qwik aims to improve?', N'Junior', N'Qwik is primarily focused on improving the Time to Interactive (TTI) and Largest Contentful Paint (LCP). By eliminating hydration, it keeps the main thread free for user interaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76b1e25c-bacd-4cb3-932b-583715ac6894', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the architectural difference between synchronous and asynchronous processing for long-running tasks in Rails.', N'Senior', N'Synchronous processing blocks the web request thread, resulting in poor user experience and potential timeout errors under high load. Asynchronous processing moves tasks to background workers, improving responsiveness and system throughput, though it introduces complexity regarding distributed state and eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1366f91-2680-4a6e-a7ea-583a825ca952', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What happens if an error occurs in an Actix request handler?', N'Fresher', N'If a handler returns a result containing an error, Actix-web converts that error into an HTTP response. Developers can implement custom error types to provide specific status codes and messages to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bdde374-61d9-43dc-a3d7-583b6e540c5e', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are Django signals?', N'Intern', N'Signals allow certain senders to notify a set of receivers when some actions have taken place. They are useful when multiple pieces of code need to be triggered by the same event, such as sending an email when a user registers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23090819-20fd-4e36-bf89-583b9380065c', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is inheritance via @extend in Sass?', N'Intern', N'The @extend rule allows one selector to inherit the styles of another selector. This is useful for sharing a base set of styles across multiple elements without duplicating the actual CSS code in the final output.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5eab0f6-22f2-401a-b9a5-583d7f79f855', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason about the trade-off between building a custom solution versus integrating a third-party service?', N'Senior', N'I evaluate the decision based on core competency, long-term maintenance costs, and time-to-market. I favor third-party services for commodity functions to save engineering hours, but I build custom when the feature provides a unique competitive advantage or requires deep integration that would lead to vendor lock-in.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b22ee885-56e3-4ca4-bcd5-583f60e209dd', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the ''observability'' pillar known as ''Golden Signals''?', N'Middle', N'The four golden signals are latency, traffic, errors, and saturation. Monitoring these four metrics provides a comprehensive overview of a service''s health and performance from the perspective of the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b4ac59f-91b3-42d8-958c-5840192037d0', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is Server-Side Rendering (SSR) in Nuxt?', N'Intern', N'SSR is a process where the server generates the full HTML content of a page for every request. This improves initial page load speed and ensures that search engines can easily crawl and index the application content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'134818c6-fa67-41df-9d8f-5845c69b05d6', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a NoSQL database and how does it differ from a traditional relational database?', N'Intern', N'A NoSQL database is a non-relational data management system that does not require a fixed table schema. Unlike relational databases that use structured rows and columns, NoSQL databases are designed to store unstructured or semi-structured data using models like documents, key-values, or graphs, offering greater flexibility for scaling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'481ec92a-faca-44b6-b6a3-58481a31bc9a', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''never'' type used for?', N'Junior', N'The ''never'' type represents values that will never occur. It is often used as the return type for functions that always throw an error or contain an infinite loop, signaling that the function will not return a value normally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'822a3cf3-feeb-4208-bd48-584cda32accb', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Why is the companion object concept important in Scala?', N'Middle', N'A companion object provides a place for static-like members, factory methods, and utility functions associated with a class. It shares the same name and scope as the class, allowing them to access each other''s private members.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d1a5f35-dbab-48e6-ae3d-584f48f541f8', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the purpose of the Tower library in Axum?', N'Intern', N'Tower is a library for creating modular and reusable network services in Rust. Axum uses Tower services to handle cross-cutting concerns like timeouts, rate limiting, and request tracing in a standardized way.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ce8de1d-844c-4fa6-a0d0-58512e3fd1e5', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Can Fiber be used to build a REST API?', N'Intern', N'Absolutely, Fiber is widely used for building RESTful APIs. It provides all the necessary tools for routing, handling HTTP methods, and managing request and response data in a standard format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'506e235b-6158-489b-aa28-585292a40e0f', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are Redis transactions and are they ACID compliant?', N'Middle', N'Redis transactions allow a sequence of commands to be executed as a single isolated operation using the MULTI/EXEC block. While they provide atomicity and isolation, they do not support true rollback in the event of errors, meaning they are not strictly ACID compliant like relational databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a60745c1-92ae-497c-9d71-5852d81ecc65', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'Why is it important to understand the ''why'' behind a requirement before starting a task?', N'Junior', N'Understanding the ''why'' allows me to identify potential edge cases and suggest more efficient solutions that align with the project''s broader goals. It ensures that the work I produce solves the actual business problem rather than just fulfilling a literal request. This context helps me make better decisions regarding implementation details.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ae28641-c08e-42b7-9f13-585862723b1d', N'4c000000-0000-0000-0000-000000000005', N'What are the trade-offs of using a ''Shared-Nothing'' architecture?', N'Senior', N'A shared-nothing architecture minimizes contention by ensuring each node manages its own resources and data. This allows for linear scalability, but it shifts the burden of coordination and data consistency to the application layer, which can increase overall system complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57eba7b9-0404-499b-963d-585883dd3d6a', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Can FastAPI handle both synchronous and asynchronous functions?', N'Intern', N'Yes, FastAPI supports both standard functions defined with ''def'' and asynchronous functions defined with ''async def''. If a standard function is used, FastAPI runs it in an external thread pool to avoid blocking the main server loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2df9dcaf-eb63-494d-b6b3-585a6e6476b7', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the benefit of data denormalization in Cassandra?', N'Junior', N'Denormalization involves duplicating data across tables to optimize for specific read queries. This avoids the need for joins, allowing the database to serve complex data requirements with a single, highly efficient read operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68b9ff65-f963-4d32-aea0-586414cb03e8', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the significance of the ''volatile'' keyword in C#?', N'Middle', N'The volatile keyword ensures that the most up-to-date value of a field is always read from memory rather than a cached version from a processor''s register. It prevents the compiler and the CPU from reordering operations involving that field, making it essential for multi-threaded scenarios where multiple threads access the same variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3270e002-578e-48ba-a7db-5864560a0c96', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the purpose of the ''Sealed'' modifier on traits or classes?', N'Middle', N'The sealed modifier ensures that all subclasses must be defined in the same source file. This allows the compiler to perform exhaustive pattern matching checks, ensuring that no cases are missed in match expressions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'200580cc-21f3-4d23-9441-58662722fb74', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What happens if you have a naming conflict in Sass when using @import?', N'Junior', N'When using @import, all variables and mixins are merged into the global scope. If two files define the same variable name, the one loaded last will overwrite the previous one, which can lead to hard-to-debug layout issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8dac08c-e605-467e-b37c-586652380dbc', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the ''Sidecar'' pattern and how does it assist in service architecture?', N'Senior', N'The sidecar pattern attaches a secondary container to the main application container to handle cross-cutting concerns like logging, service mesh proxying, or security. It allows developers to offload infrastructure logic from the application code, simplifying maintenance and upgrades.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'019e8dcd-4367-47c2-b545-586665d677a4', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle the complexity of configuration management?', N'Senior', N'Rocket uses a hierarchical configuration system that supports environment variables, configuration files, and hard-coded defaults. This allows for seamless transitions between development, testing, and production environments without requiring changes to the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a55aaf85-4bc0-4ef3-bc5c-5866bcb556bb', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why shouldn''t you mutate the state directly in Redux?', N'Junior', N'Direct mutation prevents Redux from detecting changes efficiently, which can lead to UI components failing to re-render. Redux relies on comparing state references to determine if an update is necessary, so returning a new object is required for change detection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09580488-559e-4b27-a1dd-58687eded043', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does idempotency mitigate the risks associated with message retries?', N'Senior', N'Idempotency ensures that performing the same operation multiple times results in the same final state. By designing service logic to be idempotent, developers can safely retry message processing without worrying about side effects like duplicate database entries or repeated billing cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5e12e59-ba58-4011-8989-586b2ed4fd4c', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does a ''Read Replica'' pattern help with scaling read-heavy applications?', N'Senior', N'Read replicas offload query traffic from the primary instance, allowing the system to scale horizontally by adding nodes. However, this introduces eventual consistency, meaning applications must be designed to handle scenarios where the replica data is slightly stale compared to the primary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fc2b9e1-4948-48b0-a687-586c7e04c37c', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is your process for investigating a sudden increase in disk I/O wait times on a database server?', N'Senior', N'I would first identify if the I/O is read-heavy or write-heavy and check for recent changes in query execution plans or indexing strategies. I would then evaluate if the storage backend is throttling requests due to IOPS limits or if background processes like backups, data compaction, or log rotation are contending with production traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b272e2f6-9bee-4a90-9233-587494e792e7', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is an index in a database and how does it improve performance?', N'Junior', N'An index is a data structure, similar to an index in the back of a book, that allows the database to find specific rows without scanning the entire table. It significantly improves read performance, though it can slightly slow down write operations because the index must be updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f1563c9-924a-42e7-b18b-587641fde785', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the primary purpose of Flask in web development?', N'Junior', N'Flask is a micro-framework designed to be lightweight and modular. It provides the essential tools to build web applications without enforcing a strict project structure or requiring specific libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb916401-2351-4176-91f4-587686e44bfb', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is module and package in Python?', N'Intern', N'In Python, module is the way to structure program. Each Python program file is a module, which imports other modules like objects and attributes. The folder of Python program is a package of modules. A package can have modules or subfolders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1eb2668-f57b-4bb3-abbd-587758d43664', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the purpose of the front-matter section in an Astro file?', N'Fresher', N'The front-matter is the fenced code block at the top of an Astro file used for server-side logic. It allows developers to define variables, import components, and fetch data before the page is rendered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1141a0a9-6496-498b-9484-5878883cdc41', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is encapsulation?', N'Fresher', N'Encapsulation is the practice of bundling data and the methods that operate on that data into a single unit or class. It restricts direct access to some of an object''s components, which helps prevent unintended interference and misuse of the internal state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0830e1e-93ab-475f-9372-587a1da56e69', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the role of a ''Fencing Token'' in distributed locking mechanisms?', N'Senior', N'A fencing token is a monotonically increasing number provided by a lock service to a client when it acquires a lock. When the client later writes to a storage system, it must include this token; the storage system rejects any requests with a token lower than the one it previously processed. This prevents delayed or ''zombie'' processes from corrupting data after their lock has expired or been revoked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f5b4a7e-48c9-4972-8e15-587f3b5683f4', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What are selectors and why should they be used?', N'Middle', N'Selectors are functions that encapsulate the logic of retrieving specific data from the state. They improve maintainability by decoupling the UI from the state structure and allow for memoization to prevent expensive recalculations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'988e0e73-fc0e-45c4-90ea-5880debb64d9', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the difference between an error and a warning in logs?', N'Fresher', N'An error indicates that a critical process has failed and the operation cannot complete, whereas a warning signals that something unexpected occurred but the system was able to continue. Errors require immediate investigation, while warnings may just suggest potential future issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8db9dd44-7e59-4fee-8c9d-5881ccef96a4', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the role of an Astro component?', N'Fresher', N'An Astro component is a building block that acts as a template for generating HTML. It contains both the logic for building the structure and the markup itself, and it is processed entirely at build time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f508d4c-4e21-43a9-a16f-58838a2019e6', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Why are sequences preferred over collections for large data processing chains?', N'Middle', N'Collections process data eagerly, creating intermediate collections for every transformation step, which is memory-intensive. Sequences use lazy evaluation, meaning operations are performed only when the terminal operation is called, processing elements one by one without intermediate storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b7a6345-8267-4077-bed4-588589b558fc', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between ''=='' and ''identical'' in Dart?', N'Fresher', N'The ''=='' operator checks for logical equality between two objects, which can be overridden in classes. The ''identical'' function checks whether two references point to the exact same object instance in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfed8b12-c421-4e68-b939-5885a9d59eea', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is a ''loading'' function in SvelteKit?', N'Intern', N'A loading function is a piece of code that runs before a page is rendered to fetch necessary data. The data returned by this function is made available to the page component as a property.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f799fd20-e6d5-4db4-9dad-588627cf2118', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the significance of ''Structured Concurrency'' in managing asynchronous lifecycles.', N'Senior', N'Structured concurrency ensures that coroutines are launched within a defined scope with a clear parent-child relationship, preventing leaked tasks. If a parent scope is cancelled, all children are automatically cancelled, providing a predictable and safe mechanism for resource management compared to managing individual thread lifecycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'556d864f-17e8-4038-8f82-588643d26a14', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Why is Quarkus often described as ''Kubernetes Native''?', N'Senior', N'Quarkus is designed specifically for Kubernetes by including features like automated health checks, metrics, and distributed tracing out of the box. It also provides capabilities for generating Kubernetes manifests and Dockerfiles automatically, streamlining the deployment pipeline from development to production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22d8610f-9064-40b5-8858-588785cd0bb4', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the function of the ''aspect-ratio'' property?', N'Middle', N'The ''aspect-ratio'' property allows developers to set a preferred ratio for an element, ensuring it maintains a specific width-to-height proportion regardless of its actual size. This is particularly useful for maintaining the layout integrity of media elements like videos or images during responsive resizing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cac91cd2-5e82-4a1f-8600-5887ec62c1c3', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'A microservice handling high-frequency financial transactions is experiencing intermittent latency spikes due to database contention. How would you diagnose and address this without simply increasing hardware capacity?', N'Middle', N'I would start by analyzing database execution plans and lock contention metrics to identify slow queries or poorly indexed tables that hold locks for too long. To mitigate the issue, I would implement read-write splitting to offload read operations to replicas and introduce a caching layer for static or frequently accessed data. If the contention remains, I would consider sharding the database by a specific tenant or transaction ID to distribute the load across multiple instances, thereby reducing the scope of individual locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7f46962-c5e3-44da-84a1-588889d6e106', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is mobile-first design and why is it recommended?', N'Intern', N'Mobile-first design means writing base CSS for the smallest screen first and then progressively enhancing the layout for larger screens using min-width media queries. Why it is recommended: 1. Performance: Mobile devices receive only the base styles; larger screens load additional styles on top. Unused CSS is minimised for the most bandwidth-constrained devices. 2. Progressive enhancement: Forces you to prioritise core content and functionality before adding enhancements. 3. Simpler CSS: Overriding simple mobile styles upward is usually less complex than overriding complex desktop styles downward. 4. SEO & Google: Google uses mobile-first indexing, so mobile-friendly pages rank better. Example — mobile-first layout:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'000c09aa-91e8-4746-b965-5888be881db3', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro achieve better performance compared to traditional SPAs?', N'Fresher', N'Astro achieves high performance by removing JavaScript from the final page load by default. Instead of sending a large bundle of framework code, it only hydrates the specific components that require interactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13bf8a72-5b46-4451-84a7-588968f14df6', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle dependency injection without reflection?', N'Fresher', N'Micronaut uses annotation processors to analyze the code during compilation. It generates the necessary factory and injection classes, allowing the application to wire dependencies directly at runtime without scanning the classpath.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61d1534d-9e0d-4e46-bd02-588b5f4c9a59', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a Global Secondary Index (GSI)?', N'Intern', N'A GSI is an index with a partition key and sort key that can be different from those on the base table. It allows you to query data across the entire table using different access patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b328dfe7-3fca-4ac5-9890-588cef8dd5d7', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How are URL parameters accessed in Hono?', N'Fresher', N'URL parameters are extracted from the request path and made available through the context object''s parameter method. This allows for dynamic routing, where parts of the URL are used as variables within the handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4e27c15-4a14-4f7e-aa40-58902f3e2163', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are the differences between req.query and req.params?', N'Intern', N'In Express.js, req.query is used to access GET request parameters, while req.params is used to capture parameters defined in the URL path. Understanding Express.js Routing Express.js uses app.get() and similar functions to handle different types of HTTP requests. - app.get(''/users/:id''): Matches GET requests to /users/123 where 123 is the :id parameter in the path. Accessing Request Data - req.query: Utilized to extract query string parameters from the request URL. Example: For the URL /route?id=123, use req.query.id to obtain 123. - req.params: Used to retrieve parameters from the request URL path. For the route /users/:id, use req.params.id to capture the ID, such as for /users/123. Code Example: Request Data Here is the Express.js server setup:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad5c1a88-e91b-48f2-a707-589211b982b3', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does the Saga pattern manage distributed transactions without using 2PC?', N'Senior', N'The Saga pattern breaks a long-lived distributed transaction into a sequence of local transactions, each updating the database and publishing an event. If one step fails, the Saga executes a series of compensating transactions to undo the changes made by previous steps, maintaining eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3085c587-5835-42f6-9cdd-58944028d5da', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Can you use Qwik for static site generation?', N'Intern', N'Yes, Qwik supports static site generation as well as server-side rendering. This allows developers to choose the best rendering strategy for their specific application needs while maintaining the performance benefits of Qwik.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32c2b17c-0d21-4cfe-a051-58977eae6f0f', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why is it generally advised to keep Redis data structures small when using hashes or sets?', N'Senior', N'Redis uses specialized encodings like ziplists or intsets for small collections to minimize memory overhead. When these collections grow beyond certain thresholds, Redis converts them to standard hash tables or skiplists, which consume significantly more memory and may impact performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fbc4ff1-7275-44f3-8d83-589944e4e155', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain the architectural difference between OAuth 2.0 and SAML in terms of trust delegation.', N'Senior', N'OAuth 2.0 is an authorization framework designed for API access delegation where a client is granted limited access to resources. SAML is an XML-based framework primarily focused on identity federation and single sign-on by exchanging authentication assertions between an identity provider and a service provider.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
