INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db6e188e-a347-4906-9c65-589bd651df35', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does ''Active-Active'' replication differ from ''Active-Passive'' in a global context?', N'Senior', N'Active-Active allows writes to any node in the cluster, providing low-latency access and high availability, but it requires conflict resolution mechanisms like Last-Write-Wins or CRDTs. Active-Passive directs all writes to a single source, which is simpler but limits write scalability and introduces geographic latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9db5af3-11f0-49de-accd-589bf167c802', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Can you have data races in a fiber-based environment?', N'Intern', N'Yes, even though fibers are cooperative, data races can still occur if multiple fibers access shared memory concurrently without proper synchronization. Developers must still use synchronization primitives like mutexes or channels to manage shared state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
