INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d7b2f12-2309-4308-a245-589e648711c7', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What does the ''Reactive Properties'' system do in Lit?', N'Fresher', N'Reactive properties are class fields that automatically trigger a component update when their values change. When a property marked as reactive is modified, Lit schedules a re-render to update the component''s DOM efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8973f271-7f74-4b7f-8247-589f1d0fe02b', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why is it generally better to avoid high cardinality fields in aggregations?', N'Junior', N'High cardinality fields, such as unique IDs, have many distinct values, which can consume significant memory and CPU when used in aggregations. Calculating aggregations on such fields can slow down the cluster and lead to performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c5e5d44-ea5d-442b-b88f-58a0b1d19c31', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is a Controller in the MVC structure?', N'Fresher', N'A Controller handles incoming HTTP requests, performs the necessary logic by communicating with the Model, and determines which View should be returned to the user. It keeps the business logic separated from the routing and the presentation layers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27d91021-5153-4e60-9d07-58a1056d39b1', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the risks of ''Lock Escalation'' in a database?', N'Senior', N'Lock escalation occurs when the system converts many fine-grained row locks into a single page or table lock to save memory. While it reduces lock manager overhead, it significantly increases the risk of blocking concurrent transactions and creates potential contention bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b370a68-f5ab-4d63-8004-58a28f5c73be', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the difference between Django''s session backends and their impact on scalability?', N'Senior', N'Session backends range from local file storage to database or cache-based storage like Redis. For horizontal scaling, local file storage is unsuitable; database or Redis storage is necessary to ensure session persistence across multiple application server instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bff63249-8c24-4601-9488-58a3a60142a4', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the ''fielddata'' cache differ from ''doc_values'' in terms of memory utilization?', N'Senior', N'Fielddata loads data into the JVM heap for aggregations and sorting, which is expensive and often causes OOM errors. Doc values are a disk-based, columnar storage format that is immutable and highly optimized, allowing the operating system to cache them effectively without consuming JVM heap.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'def78148-d558-47d3-b9ce-58a613fd85ff', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Explain the concept of ''Optimistic UI'' in the context of Remix actions.', N'Senior', N'Optimistic UI in Remix is achieved by using the useNavigation or useFetcher hooks to detect pending form submissions and updating the UI state immediately before the server confirms the mutation. This hides network latency, making the application feel instantaneous while keeping the backend as the final source of truth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37c6b31c-c258-4ce4-b008-58a73c7c98f5', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the advantage of using a Redis Hash over a simple String for objects?', N'Fresher', N'Using a Hash allows you to access individual fields of an object without retrieving the entire data structure. This is more memory-efficient and faster when you only need to update or read one specific attribute of an object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'478ccdd9-4440-41b0-89e0-58a7df3f178e', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Why is the @debug directive useful during development?', N'Middle', N'The @debug directive prints the value of a Sass expression to the terminal during compilation. It is a critical tool for debugging complex mixins or functions, allowing developers to inspect the state of variables without affecting the final CSS output.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b5b4e8f-1bce-4e50-8984-58aa635042d4', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is vectorized operation in R?', N'Intern', N'Vectorized operations allow R to perform calculations on entire vectors at once without needing explicit loops. This is a fundamental feature of R that makes it both efficient and concise for mathematical computations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'416ca96c-f42c-4bf7-b43e-58aba1262826', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you verify that your fix actually works?', N'Junior', N'I verify the fix by running existing tests to ensure no regressions were introduced and by creating a new test case that specifically targets the bug I just fixed. Finally, I perform manual validation in a staging environment that mirrors production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10ba0a41-53bb-4c7c-bb45-58aba396532f', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the function of ''ABI Stability'' in the context of the Swift runtime.', N'Senior', N'ABI stability ensures that code compiled with different versions of the Swift compiler can interact correctly at the binary level. It fixes the layout of metadata, protocol witness tables, and heap objects, allowing the Swift runtime to be embedded in the OS rather than the application bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43d20eb2-5edf-4538-bdbc-58b19669959e', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide whether to build a custom solution or use an existing managed service?', N'Middle', N'I weigh the cost of ownership, including maintenance, security, and operational overhead, against the flexibility provided by a custom build. If the functionality is a core differentiator for the business, I lean towards custom; for commodity tasks like logging or infrastructure, I prefer managed services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77b13886-c962-4a8e-8848-58b6611a0f63', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How a browser determines what elements match a CSS selector?', N'Fresher', N'Browsers match selectors from rightmost (key selector) to left. Browsers filter out elements in the DOM according to the key selector and traverse up its parent elements to determine matches. The shorter the length of the selector chain, the faster the browser can determine if that element matches the selector. For example with this selector p span, browsers firstly find all the elements and traverse up its parent all the way up to the root to find the element. For a particular , as soon as it finds a , it knows that the matches and can stop its matching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc78dfa6-b485-4614-86ee-58b77011d9e1', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite''s SSR (Server-Side Rendering) support differ from its client-side approach?', N'Senior', N'In SSR mode, Vite provides a server-side entry point and disables the standard HMR and browser-based ESM transformations. It focuses on providing a clean environment to execute framework rendering logic and streaming the output HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3338d089-590e-41e4-a947-58b8d6430709', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is tree shaking in the context of Webpack?', N'Junior', N'Tree shaking is a term commonly used in the JavaScript context for dead-code elimination. It relies on the static structure of ES6 module syntax to identify and remove unused exports from your final bundle, resulting in a smaller file size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'516a9301-44ca-49fb-9d65-58bd89c51245', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the difference between an ''AfterRequest'' and an ''AfterResponse'' hook?', N'Middle', N'An AfterRequest hook runs before the response is sent to the client and can modify the response object, while an AfterResponse hook runs after the response has been sent. AfterResponse is typically used for background tasks or logging that should not delay the client response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e27f438-fee4-4501-9024-58bec08d4b79', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Can you change the partition key of an existing table?', N'Middle', N'No, the partition key and sort key must be defined when the table is created and cannot be changed later. If a different key structure is required, you must create a new table and migrate the data using tools like AWS Data Pipeline or custom scripts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7e86b53-3999-4658-b2e4-58bfdb2e1582', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Discuss the architectural limitations of jQuery''s AJAX implementation regarding modern asynchronous patterns.', N'Senior', N'jQuery''s AJAX module uses its own Deferred object implementation, which predates the native Promise specification. This creates interoperability issues with modern async/await syntax and makes it difficult to compose complex asynchronous workflows using standard JavaScript tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'224e04e2-7991-4267-a1f8-58c12b3b84ae', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django’s session framework handle security when using a database-backed session store?', N'Senior', N'Django serializes session data into the database and uses a signed cookie to store the session ID on the client. It protects against session hijacking by rotating session IDs on login and using secure, HttpOnly, and SameSite cookie attributes to prevent unauthorized access via scripts or cross-site requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e873fe73-0b74-4d73-b1fa-58c1d7a78efc', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is jQuery considered less suitable for high-frequency UI updates compared to reactive frameworks?', N'Senior', N'High-frequency updates require efficient diffing algorithms, such as a Virtual DOM, to minimize actual DOM mutations. jQuery lacks such a mechanism and will trigger expensive browser reflows and repaints for every single mutation request, degrading performance rapidly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a47e4b1-0a18-4b93-9292-58c1f5cc3941', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the difference between INNER JOIN and LEFT JOIN?', N'Fresher', N'An INNER JOIN returns only the rows where there is a match in both tables. A LEFT JOIN returns all rows from the left table and the matching rows from the right table, or null values if no match is found.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b73843b-2f86-4e66-8949-58c287ba5773', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What are the trade-offs of using ''Leveled Compaction Strategy'' (LCS)?', N'Middle', N'LCS organizes SSTables into levels with fixed sizes, which significantly improves read performance by minimizing the number of files searched. However, it requires higher disk I/O overhead compared to Size-Tiered Compaction due to more frequent file operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'409e2ef9-49db-4aeb-8d6d-58c42c783cc3', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit''s client-side router handle performance compared to traditional multi-page apps?', N'Middle', N'SvelteKit uses prefetching to download the JavaScript and data for linked pages before the user even clicks them. This makes navigation feel instantaneous because the browser doesn''t have to perform a full page reload or network request upon the interaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cad35c5-7fd3-437c-b729-58c45e076b58', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What does ''Dependency Pre-bundling'' mean in Vite?', N'Fresher', N'Dependency pre-bundling is a process where Vite converts CommonJS or UMD dependencies into ESM format during the first startup. This ensures that the browser can load these dependencies efficiently using native ESM imports.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff58a045-65c8-4eda-8438-58c5ef9d1b91', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the benefit of using the ''next/image'' component?', N'Middle', N'The Image component provides automatic image optimization, including resizing, compressing, and serving modern formats like WebP or AVIF based on the user''s browser. It also prevents layout shift by requiring width and height attributes and supports lazy loading by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0422918-d255-489e-a334-58c670540277', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the ''using'' statement function in C#, and why is it used?', N'Junior', N'The using statement provides a convenient syntax that ensures the correct usage of IDisposable objects. It automatically calls the dispose method on the object as soon as the execution leaves the scope of the statement block, even if an exception occurs. This is critical for managing unmanaged resources, such as file handles or database connections, by ensuring they are released promptly to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6de94541-3db7-4e01-9fe6-58caca201447', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does the ''Provider'' component work in Redux?', N'Middle', N'The Provider component uses React Context to pass the Redux store down to all components in the application tree. This ensures that any connected component or hook can access the store without needing to pass it through props manually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4b38844-f388-4951-b8b1-58cb2a6819fd', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the primary differences between the Options API and the Composition API in Vue, and when would you prefer one over the other?', N'Middle', N'The Options API organizes code by logical properties like data, methods, and computed properties, which is intuitive for beginners or smaller components. The Composition API organizes code by logical concerns using functions, which significantly improves code reuse and readability in large, complex components. You should prefer the Composition API for large-scale applications where logic needs to be shared across multiple components via composables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11e8cfef-329c-4c2e-ba3c-58cb5c13f7cd', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If a mentor gives you feedback that contradicts your approach, how do you handle it?', N'Intern', N'I would listen actively and ask questions to understand the reasoning behind their perspective. Since mentors have more experience, their feedback is a learning opportunity to see a better or more efficient way to approach the problem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c9f6aae-6651-48dd-9a88-58cdfc1e1214', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does the ''late'' keyword work in Dart?', N'Junior', N'The ''late'' keyword tells the compiler that a non-nullable variable will be initialized at a later time, after its declaration. This allows developers to use variables that are not initialized at the moment of construction but are guaranteed to be ready before use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33289e9e-95e1-4177-8e1c-58ce40defa66', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle polyfills and browser compatibility for production?', N'Senior', N'Vite uses the @vitejs/plugin-legacy to generate dual-bundle outputs: one for modern browsers using native ESM, and one for legacy browsers using SystemJS with transpilation. This approach ensures that performance is not penalized for modern users while maintaining a wide support surface for older environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ad83313-ee66-4dc8-a441-58d09e36c829', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is a Sass map?', N'Intern', N'A Sass map is a data structure that stores key-value pairs, similar to objects in JavaScript. Maps are useful for grouping related settings like color palettes or breakpoints, making them easy to iterate over or reference dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e4fb952-8e4e-4ba1-b00c-58d1ed75651d', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel protect against CSRF attacks?', N'Junior', N'Laravel automatically generates a CSRF token for each active user session managed by the application. The framework checks that the current user is the one actually making the requests to the application, blocking any unauthorized cross-site requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26a041ad-90b1-492f-b798-58d2dcc3a01c', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you ensure your estimates remain neutral and are not influenced by pressure to deliver faster?', N'Junior', N'I rely on the technical breakdown and my previous experience rather than external deadlines to determine the effort required. If I feel pressured, I explain the technical requirements and risks clearly so that the focus remains on the feasibility of the work rather than just speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ed58842-5775-41b1-956d-58d3a09341ee', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is an object in R?', N'Intern', N'Everything in R is considered an object, including variables, functions, data structures, and models. Each object has a class that determines how it is handled and what operations can be performed on it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19b3d46d-69ba-4076-a162-58d3e3080b51', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix''s ''LiveView'' differ from traditional server-side rendering?', N'Middle', N'LiveView maintains a persistent stateful connection between the client and server. It pushes only the incremental DOM changes over a WebSocket, allowing for real-time, interactive user experiences without requiring a full page reload or complex JavaScript state management on the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93137168-0de1-463d-9f67-58d53d10b692', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Generics in TypeScript and why are they used?', N'Fresher', N'Generics allow you to create reusable components that work with a variety of types rather than a single one. They provide a way to maintain type safety while keeping functions or classes flexible enough to handle different data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6170c2a4-f2da-4435-97c8-58d662b3d5a4', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Describe the impact of CAP theorem on choosing a database for a global e-commerce platform.', N'Senior', N'The CAP theorem forces a choice between consistency and availability during a network partition. For an e-commerce platform, a system may prioritize consistency during checkout to prevent overselling, while favoring availability for product browsing to ensure a seamless user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7bb8440-9854-4769-bf62-58d86c902dc5', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your process for breaking down a large, complex feature request into manageable tasks?', N'Junior', N'I start by identifying the core functional requirements and mapping out the necessary dependencies. I then break these down into smaller, logical sub-tasks that can be completed and tested independently. This approach helps me track progress more effectively and identify potential blockers early on.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db73a16e-9b83-4705-9c75-58de31d1b03f', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'In what scenario would you choose to use Alpine.js over a framework like Vue for a specific feature?', N'Middle', N'Alpine.js is the preferred choice when you need lightweight interactivity on a page that is primarily driven by server-side rendering, such as a Laravel or Django application. It avoids the performance penalty and complexity of hydrating a full-blown framework when only a few interactive elements, like dropdowns or modals, are needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e2171a7-663d-4dfe-a4da-58e3f4962c52', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does the C++ ''Rule of Five'' relate to resource management efficiency?', N'Senior', N'The Rule of Five mandates that if a class manages a resource, it should define the destructor, copy constructor, copy assignment operator, move constructor, and move assignment operator. Adhering to this ensures that resources are transferred efficiently through move semantics rather than being copied, which is critical for performance when dealing with large objects like containers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'495f87e0-0c59-46d6-9303-58e5b9c3d271', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus simplify database access?', N'Fresher', N'Quarkus simplifies database access through the Hibernate ORM extension and Panache. Panache provides an active record pattern or repository pattern that reduces the amount of boilerplate code required to perform CRUD operations on a database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e69b24ae-bbcb-4354-a10a-58e762df8f7d', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How do you extract query parameters in Echo?', N'Junior', N'Query parameters are extracted using the QueryParam method on the Echo Context object. You provide the name of the parameter as a string, and Echo returns the corresponding value from the URL query string.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82dffd78-faf3-49d7-ac43-58e85881264b', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind CSS facilitate the implementation of dark mode versus traditional CSS approaches?', N'Senior', N'Tailwind simplifies dark mode by using a ''dark:'' variant modifier that toggles styles based on a root class or media query. This is more declarative than maintaining separate dark-mode-specific CSS files or complex variable swapping schemes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da20ff52-7ed5-420b-ba82-58e9c13a5c03', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the significance of ''separation of concerns'' in software design?', N'Intern', N'Separation of concerns involves organizing a system into distinct sections, where each section addresses a specific responsibility. This approach makes the code easier to understand, test, and modify since changes in one area do not unexpectedly affect others.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d5a472b-14c8-4d85-83aa-58ea04541c57', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is it important to understand the layout of structs in memory for performance-critical applications?', N'Senior', N'Data alignment and field ordering impact the memory footprint and CPU cache efficiency of a struct due to padding bytes inserted by the compiler. Rearranging fields from largest to smallest can significantly reduce the size of the struct, improving cache locality and reducing the overall memory pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b312a31d-8d89-4c8a-9277-58ea34503695', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of the ''Task'' controller in Lit?', N'Middle', N'The Task controller simplifies asynchronous data fetching within components by managing loading, error, and success states automatically. It reduces the boilerplate code required to handle promises and keeps the component logic clean.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c7b8a61-e165-4f71-9241-58eaaaf81be5', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How can you create a module in Python?', N'Fresher', N'You can create a Python module through the following standard methods: - Define: Save a Python file with a .py extension. This file acts as a module, where the filename (without the extension) serves as the module name. - Package Initialization: To organize multiple modules into a package, place an init.py file inside the directory. While implicit namespace packages exist, including this file explicitly marks a directory as a regular package and allows for package-level initialization. Next, use the import statement to access the module and its functionality within your project. Code Example: Creating a math_operations Module Module Definition Save the below code as a file named math_operations.py.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffc1b8d9-0768-4906-903a-58eb22adb5b1', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the impact of blocking operations inside an Actix actor''s message handler on the system''s throughput?', N'Senior', N'Since actors run on a single-threaded executor by default, a blocking operation halts the entire thread, preventing other actors assigned to that thread from processing messages. This creates a bottleneck that effectively neutralizes the benefits of asynchronous concurrency, necessitating the use of specialized blocking thread pools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f77df23-2643-4003-8ac0-58eb243b62a0', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How do you share a database connection pool across Actix-web handlers?', N'Junior', N'You typically wrap the pool in an Arc or directly pass it into the App''s data configuration using the app_data method. This makes the pool accessible to any handler that requests it via the Data extractor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae1ca17c-4cc1-4b8d-b450-58ebf0c86ede', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What are transaction isolation levels?', N'Intern', N'Isolation levels define how strictly the database manages the visibility of changes made by one transaction to others. They are used to balance the trade-off between data consistency and system performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4daac587-d8cf-43e2-9e05-58f2812da486', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the V8 engine?', N'Intern', N'V8 is a high-performance open-source JavaScript engine developed by Google for Chrome and Node.js. It compiles JavaScript directly into native machine code, which allows Node.js to execute code very quickly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ad7bdbf-ba62-415b-b54b-58f3ddf31ae2', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain the security risks associated with overly broad IAM policies.', N'Senior', N'Broad policies violate the principle of least privilege, increasing the blast radius if an identity is compromised. If a service account has administrative access, an attacker who exploits that service can escalate privileges to destroy resources or exfiltrate data across the entire cloud environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05abe356-3db1-4550-b522-58f6657761a4', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix handle concurrency compared to request-per-thread models?', N'Middle', N'Phoenix runs on the Erlang VM, which uses lightweight processes rather than OS threads. This allows it to handle hundreds of thousands of concurrent connections with minimal memory overhead, as each process is isolated and garbage-collected independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e528540e-3982-4482-a557-58f679703a35', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the purpose of ''Time Synchronization'' in a distributed system, especially for logs?', N'Middle', N'In distributed systems, logs from multiple servers must be correlated by time to reconstruct the sequence of events. If clocks are not synchronized via protocols like NTP, it becomes impossible to determine the correct order of events, making root cause analysis very difficult.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06ddb901-7b18-4f82-a481-58f795d4a9e1', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why does Ember prefer ''Convention over Configuration''?', N'Middle', N'This philosophy reduces the need for manual setup by providing sensible defaults based on file names and directory structures. It accelerates development and makes it easier for new developers to understand the architecture of an existing project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82149ee5-9716-4864-a7eb-58fca324161f', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing a high-traffic system, how do you decide between strong consistency and eventual consistency?', N'Middle', N'The decision hinges on the business requirement for data accuracy versus system availability during network partitions. If the application requires immediate data integrity, such as financial transactions, strong consistency is necessary despite the increased latency and potential for unavailability. If user experience and uptime are prioritized over real-time accuracy, eventual consistency allows for higher throughput and fault tolerance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6c40146-99aa-47a0-8daf-58fce29e6352', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact optimize the reconciliation of text nodes?', N'Senior', N'Preact treats text nodes as simple VNode types and directly updates their ''textContent'' property when a change is detected. This avoids the cost of creating new DOM nodes and keeps the update process focused on direct property mutation, which is highly efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a26598b2-3b74-4816-9e65-59002ca6d60a', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What are the security implications of using a shared database across multiple microservices?', N'Senior', N'A shared database creates a strong coupling that breaks the principle of least privilege, as each service requires access to the entire schema. This increases the blast radius of a security compromise, as an attacker gaining control of one service can potentially access or modify data belonging to other domains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40fceaf2-d701-4d05-91a8-590098584f76', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the benefit of using an opinionated framework?', N'Fresher', N'An opinionated framework provides standard ways to perform common tasks, which reduces decision fatigue. It ensures that projects follow a consistent structure, making it easier for new developers to understand the codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ac98677-bbe6-497b-9a51-5901f6c925ad', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What does it mean for Rocket to be ''Type-Safe''?', N'Intern', N'Type safety means that Rocket uses Rust''s compiler to ensure that the data passed between the web request and your code is valid. This prevents many common bugs, such as mismatched data types or missing parameters, at compile time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'477d9aee-ac78-4818-a8fc-5905e8c40422', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the concept of function overloading in C++.', N'Fresher', N'Function overloading allows multiple functions to share the same name, provided they have different parameter lists. The compiler determines which function to call based on the number and type of arguments passed during the call.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35d7fc15-87fb-49a8-856a-59066f3cbd4e', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does the ''Replication Factor'' (RF) influence cluster design?', N'Senior', N'The Replication Factor defines how many copies of each piece of data exist in the cluster. A higher RF increases fault tolerance and read capacity but consumes more storage space and requires more background work to keep replicas synchronized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63b8452e-f7ce-4e03-b143-590bb607fb3d', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How would you design a caching strategy for a service where data changes frequently but requires low latency read access?', N'Senior', N'I would utilize a write-through or cache-aside strategy combined with short TTLs and a robust invalidation mechanism, such as event-based cache busting. To prevent cache stampedes, I would implement request collapsing or probabilistic early expiration to ensure the origin store is not overwhelmed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'501a4eab-8c53-46c0-8bc1-590cdbcb66e3', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why we need to pass a function to setState()?', N'Fresher', N'The reason behind for this is that setState() is an asynchronous operation. React batches state changes for performance reasons, so the state may not change immediately after setState() is called. That means you should not rely on the current state when calling setState() since you can''t be sure what that state will be. The solution is to pass a function to setState(), with the previous state as an argument. By doing this you can avoid issues with the user getting the old state value on access due to the asynchronous nature of setState(). Let''s say the initial count value is zero. After three consecutive increment operations, the value is going to be incremented only by one. If we pass a function to setState(), the count gets incremented correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9842919c-b04b-415b-bf4e-590d6a709322', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are Streams in Node.js and why are they useful?', N'Junior', N'Streams are collections of data that are processed piece by piece rather than loading the entire object into memory. They are highly efficient for handling large files or continuous data streams, such as network requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1380f184-ba24-495f-b7ac-590e8fe6b9e3', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the difference between ''extending'' and ''overriding'' in the Tailwind config?', N'Middle', N'Extending adds your custom values to the default Tailwind theme, keeping the original utilities intact. Overriding completely replaces the default theme, which is useful if you want to strictly enforce a specific color palette or spacing scale without having extra unused defaults.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd68fc65b-d1d2-49e4-91e2-590ef661534b', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is a jQuery deferred object?', N'Junior', N'A deferred object is a chainable utility object that can register multiple callbacks into callback queues. It is primarily used to manage the state of asynchronous operations, providing a way to execute functions when an AJAX request succeeds or fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ead37672-bd1b-4f48-ae5a-5910c74b72f4', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Does Fiber support asynchronous programming?', N'Fresher', N'While Go itself handles concurrency via goroutines, Fiber''s internal design is synchronous by default per request. However, because Go is inherently concurrent, Fiber handles thousands of concurrent requests by spawning lightweight goroutines for every connection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da7b6903-a266-4712-beeb-5917637c6e77', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the implications of enabling ''strictNullChecks'' in a large, legacy project?', N'Senior', N'Enabling strictNullChecks forces developers to explicitly handle null and undefined values, which significantly reduces runtime errors caused by accessing properties on missing objects. While it improves reliability, it often requires a massive refactoring effort to resolve widespread type mismatches across the codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
