INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b16049b1-185b-4650-8a56-591bee77a1cf', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it important to document the steps taken to solve a bug?', N'Fresher', N'Documentation helps prevent future occurrences of the same issue and serves as a knowledge base for the team. It also allows others to understand the reasoning behind a specific fix if similar problems arise later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e64f29fc-0aa2-4131-8d47-591bfee65d55', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the purpose of push() and replace() methods of history?', N'Intern', N'A history instance has two methods for navigation purpose. 1. push() 2. replace() If you think of the history as an array of visited locations, push() will add a new location to the array and replace() will replace the current location in the array with the new one.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5b424a3-fb61-44ff-a7d6-591c1fa74455', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack handle environment variables?', N'Fresher', N'Webpack can use the DefinePlugin to replace specific strings in your code with environment variables at compile time. This is commonly used to toggle features or configuration settings based on whether the build is for development or production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ae1cc26-fd81-4194-83ef-5923af06500c', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is PHP primarily used for in web development?', N'Intern', N'PHP is a server-side scripting language primarily used for web development. It is designed to generate dynamic page content, collect form data, and manage databases on the server before sending the result to the client''s browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2eea5804-f54d-4b65-a751-59243a46c89d', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is event delegation in HTML?', N'Intern', N'Event delegation is a technique where a single event listener is attached to a parent element instead of adding listeners to each child element individually. It leverages event bubbling to handle events from child elements. Why use it: - Fewer event listeners → better memory performance - Works for dynamically added elements - Cleaner code Example without delegation (inefficient): Example with delegation (efficient): Dynamic elements also work because the parent listener is already in place when new elements are added.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3b62d49-7f0c-4c7f-acc4-5927695baec3', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why is ''read-through'' caching often combined with a write-through strategy?', N'Senior', N'Combining these ensures the cache remains synchronized with the database in both directions, simplifying the application logic by treating the cache as the primary data store. This consistency comes at the cost of higher latency for every write operation, making it suitable only for read-heavy or consistency-critical workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'445256d7-07de-408d-940c-5929cfb79964', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the Flexbox layout model primarily used for?', N'Junior', N'Flexbox is a layout model designed for distributing space along a single dimension, either as a row or a column. It makes aligning items, changing their order, and managing responsive alignment much simpler than traditional block-based methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9dc90e65-378d-4540-840a-592b8cce3ce6', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you monitor and maintain the health of a distributed system?', N'Senior', N'I implement a multi-layered monitoring strategy covering infrastructure metrics, application-level logs, and business-focused distributed tracing. I define Service Level Objectives (SLOs) and configure automated alerting based on error budgets, ensuring that the team focuses on issues that actually impact the end-user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2601931f-2956-404e-a621-592d7590dbd1', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does ''Eventual Consistency'' complicate system monitoring?', N'Senior', N'Eventual consistency makes it difficult to define the ''correct'' state of the system at any given moment, often resulting in stale data being reported in dashboards. Monitoring systems must be designed to account for replication lag and should provide views that reflect the window of inconsistency to avoid false alerts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a066cb87-8c94-4e7e-bab8-592e24ba5050', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle style scoping?', N'Junior', N'Lit uses the Shadow DOM to scope CSS styles strictly to the component. This allows you to write simple CSS selectors without worrying about naming collisions or global style overrides in other parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78352c21-356c-4591-84ad-5932f0c1b2c5', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the role of the ''static'' keyword when applied to a local variable?', N'Junior', N'When ''static'' is used on a local variable, it changes its lifetime to persist for the entire duration of the program. Unlike a regular local variable, which is recreated every time a function is called, a static variable retains its value between function calls. It remains private to the function scope but effectively acts like a global variable in terms of persistence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c070c840-7cd2-4c89-9dc8-59365cce0454', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Describe how Micronaut implements AOP (Aspect-Oriented Programming) without runtime proxies.', N'Senior', N'Micronaut uses compile-time bytecode transformation to apply aspects, such as transactions or security, directly to the target classes. By modifying the generated bytecode during compilation, it avoids the performance penalty and complexity associated with creating dynamic proxies at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'631c76cc-b65b-47e3-834a-593817db549a', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the trade-offs of denormalization?', N'Junior', N'Denormalization involves intentionally adding redundant data to a database to speed up complex read queries. While it improves performance by reducing the need for expensive joins, it increases the risk of data inconsistency and makes update operations more complex because the same data may need to be updated in multiple places.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1980d9be-25f3-496a-8ffa-593e9ddc781c', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Is Chi suitable for high-throughput microservices?', N'Middle', N'Yes, Chi is excellent for high-throughput services because it introduces negligible latency and overhead compared to the standard library. Its lightweight nature allows the CPU and memory to focus on business logic rather than framework abstractions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff64b3e1-3e0d-4c06-a96d-593ed37dfe09', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Discuss the scalability of Gin''s routing tree when dealing with thousands of dynamic routes.', N'Senior', N'While the radix tree is highly efficient, having thousands of dynamic routes can increase memory usage and startup time. For massive route counts, performance is generally stable due to the tree structure, but architectural complexity in route organization and middleware application becomes the primary maintenance challenge.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ec84bbc-8131-45c8-9a2e-593fc7f1404a', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What considerations are necessary when migrating a legacy Webpack project to Vite?', N'Senior', N'Migration requires mapping Webpack loaders to equivalent Vite plugins and updating environment variable access. Additionally, developers must adapt to the ESM-first philosophy and potentially refactor code that relies on Webpack-specific features like require.context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cae2d6a0-7906-40bc-913c-5941365930cd', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is a Model in the Ember framework?', N'Fresher', N'A model represents the data structure of your application, usually mapped to a resource on a backend server. It defines the attributes and relationships associated with a specific piece of information, such as a user or a blog post.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'900eb74f-e9e4-403b-ae2b-594193df513f', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Why is the use of the ''...'' (ellipsis) argument considered a design pattern for function composition and extension?', N'Senior', N'The ellipsis allows functions to pass arbitrary sets of arguments to inner functions or methods without explicit definition, facilitating flexible API design. It is critical for wrapping generic methods or creating decorators, though it can obscure function signatures and make static analysis more difficult.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'793d3711-6025-4edd-8361-594295131baf', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide when to implement a rate-limiting strategy for an API?', N'Middle', N'I implement rate limiting when I need to protect the service from malicious actors, noisy neighbors, or accidental resource exhaustion by clients. I define limits based on historical usage patterns and prioritize the stability of the system over the needs of excessive consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bd13551-b546-479d-9942-594659c5759a', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a Tombstone?', N'Fresher', N'A tombstone is a marker that Cassandra places on a piece of data to indicate that it has been deleted. Because SSTables are immutable, data cannot be deleted immediately; the tombstone ensures the data is ignored during reads and eventually removed during compaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2435b219-c73b-40c4-a01c-5947d70ca4f5', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What factors do you consider when choosing between a push-based or pull-based monitoring system?', N'Senior', N'Pull-based systems are generally more resilient to target failures as they centralize configuration, while push-based systems excel in dynamic environments with short-lived tasks like serverless functions. I choose based on the network topology and the necessity for service discovery integration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59920bd4-5e6c-4bf6-9201-594dea2dcb32', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the difference between a GET and a POST request in Echo?', N'Intern', N'A GET request is typically used to retrieve data from the server without modifying any state. A POST request is used to submit new data to be processed or stored by the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9222ba56-6b53-4374-abd0-594ff0522f14', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Describe the mechanism behind Swift''s ''Reflection'' capabilities and its performance cost.', N'Senior', N'Reflection in Swift is provided via the Mirror type, which inspects the metadata of an instance at runtime. Because it bypasses compile-time type checking and requires traversing metadata structures, it is significantly slower than direct property access and should be avoided in performance-critical paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3dfe0277-4169-49ad-96ac-595498414b7c', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Does Micronaut support asynchronous programming?', N'Intern', N'Yes, Micronaut has first-class support for asynchronous and non-blocking programming. It integrates with project Reactor and RxJava to help handle high-concurrency workloads efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fe6dcc8-cc9a-455b-b7ec-59551bcd9dd0', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is a router ''middleware'' in Chi?', N'Junior', N'Middleware in Chi is a function that wraps an HTTP handler to perform operations before or after the main handler logic. Common use cases include logging, authentication, recovery from panics, and setting request timeouts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'129de2d4-fb1d-4ad8-90bd-5957c1eca79c', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Does Qwik require hydration?', N'Intern', N'No, Qwik explicitly avoids hydration. Hydration is the process of re-executing framework logic on the client to attach event listeners; Qwik uses resumability to achieve interactivity without this expensive overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f027fd25-21c4-4833-8926-5959c0311e77', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is your process for evaluating the scalability of a third-party API integration?', N'Senior', N'I would assess the API''s rate limits, SLA guarantees, and failure modes, ensuring we build robust retry mechanisms with exponential backoff. I would also design the integration to be circuit-broken, preventing external performance degradation from blocking internal threads or exhausting local resource pools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
