INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'969b6119-5dfc-497b-bdfe-59689bcfd2f8', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What are the architectural risks of placing non-serializable data, such as Promises or Classes, into the Redux store?', N'Senior', N'Redux relies on serialized state for features like time-travel debugging, state persistence, and snapshot testing. Storing non-serializable data breaks these tools, makes the state harder to hydrate from local storage, and can cause unexpected serialization errors during debugging sessions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bea5c0a-0a7e-4421-ae4d-596980450a2e', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle health checks and why are they vital for orchestration platforms like Kubernetes?', N'Senior', N'Micronaut provides a built-in health indicator framework that exposes the status of various components like databases, caches, and remote services. Kubernetes relies on these endpoints to perform liveness and readiness probes, ensuring that traffic is only routed to healthy service instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e67373a9-f399-4359-b73e-597368114cc0', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the function of the ''Depends'' class?', N'Fresher', N'The ''Depends'' class is used to declare dependencies for a path operation. When the function is called, FastAPI executes the dependency function, collects the result, and passes it as an argument to your route function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5433522-3d62-4b25-a4f2-59768d5cfaef', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why does Go treat errors as values rather than using exceptions?', N'Middle', N'Errors-as-values force developers to acknowledge and handle failure cases explicitly at the call site, leading to more predictable code. This avoids the hidden control flow inherent in exception-based models, which often makes it difficult to track where an error might be caught or ignored.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3255ef5-c66b-42eb-862a-5977f199ed40', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between ''=='' and ''==='' in PHP?', N'Intern', N'The ''=='' operator checks for equality of value, potentially performing type juggling to compare different types. The ''==='' operator checks for both equality of value and identity of type, ensuring that the types match perfectly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b752646-621a-4ffb-a0f8-5978b6863a30', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Explain the trade-offs of using UUIDs versus Incremental Integers as primary keys in distributed databases.', N'Senior', N'Incremental integers are space-efficient and provide better B-tree index locality, but they expose business metrics and are difficult to merge across shards. UUIDs facilitate decentralized ID generation and horizontal partitioning, but their lack of sequentiality causes significant fragmentation and page splits in clustered indexes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd44e33a4-aebb-4ba8-a685-597a1d376562', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is a compile time constant in Java?', N'Intern', N'If a primitive type or a string is defined as a constant and the value is known at compile time, the compiler replaces the constant name everywhere in the code with its value. This is called a compile-time constant. Compile time constant must be: * Declared final * Primitive or String * Initialized within declaration * Initialized with constant expression They are replaced with actual values at compile time because compiler know their value up-front and also knows that it cannot be changed during run-time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9fd2ef3-b485-457a-852d-597a99efd78a', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do SQL and NoSQL databases generally differ in their approach to handling transactions?', N'Fresher', N'SQL databases are typically built on ACID properties, prioritizing strong data consistency and reliability for complex operations. In contrast, many NoSQL databases prioritize availability and scalability, often following the BASE model which allows for eventual consistency instead of immediate, strict transactional integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e20a377e-7ec2-47f8-bc51-597d2a8c7b51', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the purpose of a JOIN in SQL?', N'Junior', N'A JOIN is used to combine rows from two or more tables based on a related column between them. It allows you to retrieve data that is split across different tables into a single result set.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ae83837-f5e7-4221-a6f7-597d4746413f', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What does the useNavigation hook allow you to do?', N'Junior', N'The useNavigation hook provides information about the current page transition, such as whether a form is currently submitting or a page is loading. It is commonly used to show loading indicators or disable buttons during async operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6f40b1b-776c-47e0-b6ca-597f68e79915', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is structural typing in TypeScript?', N'Intern', N'TypeScript uses a structural type system, meaning that two types are compatible if they have the same structure. If an object has all the required properties of an interface, it is considered to be of that type, regardless of its explicit declaration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
