INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0e79275-64fb-4a63-ac32-5983070ffada', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How can you mitigate the risk of SSRF (Server-Side Request Forgery) in cloud-native applications?', N'Senior', N'Mitigation involves strictly validating all user-supplied URLs against an allowlist and ensuring the application runs with an IAM role that follows the principle of least privilege. Additionally, network-level egress filtering should restrict the application''s ability to communicate with internal metadata services or unintended internal endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9da0f2f-0910-48c3-b025-598440ac7d55', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does the Rails transactional outbox pattern help with distributed system consistency?', N'Senior', N'The outbox pattern ensures that database changes and event publishing occur atomically. By saving an event to an ''outbox'' table in the same transaction as the record update, an asynchronous process can later publish the event to a message broker, ensuring event delivery even if the external system is temporarily unavailable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a725636c-8c26-47b1-9033-5985715ce75c', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What does it mean for Scala to be a hybrid language?', N'Intern', N'Being a hybrid language means Scala treats every value as an object while also supporting functional programming concepts like immutable data structures and first-class functions. This allows developers to choose the best paradigm for the problem at hand, whether it be object-oriented design or functional transformation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
