INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed50fdf3-a74b-4bcc-af14-59bb5087f55f', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between ''List'' and ''Array''?', N'Junior', N'An array has a fixed size defined at creation, making it difficult to resize. A List is a dynamic collection that automatically resizes as you add or remove elements, providing more flexibility for data manipulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a95f92fe-6b00-4311-819a-59c0e63e6fce', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the purpose of the Fastify ''Logger''?', N'Intern', N'Fastify comes with a built-in logger called Pino, which is highly performant. It is used to track events, errors, and request details throughout the application lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17d15b20-f139-4dd1-bac8-59c4ffad94a2', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the benefit of breaking a large system into smaller, independent services?', N'Fresher', N'Breaking a system into smaller services allows for easier maintenance and testing, as each part can be developed and managed independently. It also prevents a failure in one small component from bringing down the entire system. This modular approach makes it easier to understand individual parts of the system and troubleshoot specific issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cc39f05-308f-42dd-bc8b-59c55cc640ca', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the architectural significance of the ''suspend'' modifier in Kotlin Coroutines?', N'Senior', N'The ''suspend'' modifier transforms a function into a continuation-passing style state machine. This allows the runtime to pause execution without blocking the underlying thread, enabling cooperative multitasking and efficient resource management in asynchronous I/O operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf1bf7a2-d375-4b40-b861-59c5d347da39', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a cascading failure in a distributed system where services are failing due to timeouts?', N'Senior', N'I would identify the ''patient zero'' service that initiated the failure and evaluate if it triggered a feedback loop through retry storms or circuit breaker tripping. I would then implement or tune back-pressure mechanisms and rate limiting to shed load, ensuring that downstream services can recover gracefully without being overwhelmed by pending requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc350d86-c1e9-4c1f-a66e-59c74850d3c6', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How do you ensure secure secret management in a highly dynamic containerized environment?', N'Senior', N'Secrets should never be hardcoded or passed via environment variables, which can be logged or leaked. Instead, use a centralized vault service that injects secrets directly into the application''s memory at runtime or via a mounted secure volume, ensuring secrets are encrypted at rest and in transit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
