INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1ba10b2-3924-4559-b264-59cc2c33944b', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the role of the EventDispatcher component in decoupling system architecture?', N'Senior', N'The EventDispatcher implements the Observer pattern, allowing decoupled components to communicate by dispatching and listening for specific domain or system events. This architecture allows developers to extend core functionality or integrate third-party bundles without modifying the original source code, adhering strictly to the Open-Closed Principle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
