INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0305a0c-68a8-46b2-a302-59cfd863b706', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between stack and heap allocation regarding object lifetime?', N'Middle', N'Stack allocation is managed automatically and follows a strict LIFO scope, meaning objects are destroyed immediately when they go out of scope. Heap allocation requires manual management or smart pointers, allowing objects to persist beyond the scope in which they were created.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f130cba-b176-4b40-a0cb-59d1350ecf35', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle DOM updates for arrays and objects?', N'Middle', N'Svelte tracks changes to variables through simple assignments. For arrays or objects, the compiler looks for assignment operators to trigger updates, meaning you must ensure that the reference is updated or assigned to trigger the reactivity system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6778ad0-ea86-4ca7-9fa4-59d1aab16dd4', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the default port for an Express server?', N'Fresher', N'Express does not have a default port. You must explicitly define the port using the app.listen method, usually by referencing an environment variable like process.env.PORT or a hardcoded number like 3000.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cc6dac5-dcb2-4719-8a0a-59d3cc316777', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do you address the ''N+1'' query problem when dealing with polymorphic associations?', N'Senior', N'You must use the ''includes'' method with a hash that specifies the polymorphic associations to force eager loading. Without explicit loading, Active Record cannot predict the table structure for polymorphic types, resulting in separate queries for each associated record type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbd865d5-c93a-4bcf-b3ae-59d6419f4f26', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is horizontal scaling versus vertical scaling?', N'Junior', N'Vertical scaling involves adding more power, such as CPU or RAM, to an existing machine. Horizontal scaling involves adding more machines to a cluster to distribute the load, which is the primary scaling strategy for MongoDB via sharding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6293c8f8-66f8-45ce-a183-59d7e3cdcf45', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you investigate a situation where an application is experiencing high disk I/O wait times?', N'Senior', N'I would use system-level tools to identify which specific processes are performing the heavy read/write operations and verify if they are related to logging, database operations, or swap activity. I would then cross-reference this with the application''s configuration to see if it is performing excessive synchronous disk writes that could be optimized with buffering or asynchronous I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b083d86-c358-4e69-b5e6-59d85d894ef7', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does the PHP Zend Engine implement memory management to prevent leaks in long-running processes?', N'Senior', N'The Zend Engine utilizes a reference counting mechanism combined with a cycle collector. When a variable''s reference count reaches zero, memory is immediately freed, while the cycle collector periodically scans for and clears circular references that cannot be resolved by simple counting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5de65b93-7596-467a-9adb-59d8e399daa8', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is ''Witness Table'' dispatch and how does it differ from a V-Table?', N'Senior', N'A witness table is used for protocol method dispatch, mapping protocol requirements to concrete implementations within a type. While a V-Table is tied to class inheritance hierarchies and is fixed for the duration of the program, witness tables are constructed for types conforming to protocols. This allows for more flexible, non-hierarchical polymorphism compared to the rigid structure of V-Tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1addbf96-695f-4f6d-a838-59d9f8f1e543', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the ''this'' keyword behave differently in arrow functions compared to regular functions?', N'Middle', N'In regular functions, ''this'' is determined by how the function is called, which can lead to unexpected behavior in callbacks. In arrow functions, ''this'' is lexically bound to the scope in which the function was defined, ensuring it remains consistent regardless of how the function is invoked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1967d05a-5d0a-4bdd-8f64-59da8c6cea23', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are the trade-offs of using Svelte compared to a framework with a Virtual DOM?', N'Middle', N'Svelte''s compiler approach provides faster DOM updates and smaller bundles, but it lacks the mature ecosystem and vast library support of React. Furthermore, Svelte''s custom syntax requires a learning curve for developers accustomed to standard JSX.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61cf9f00-6f4a-4284-976e-59da97a19197', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How can you architecturally protect against ''Broken Object Level Authorization'' (BOLA) at scale?', N'Senior', N'BOLA is mitigated by moving authorization logic out of the client and ensuring that every API request validates that the authenticated user has explicit ownership or permission for the specific resource ID being accessed. This should be enforced at the service layer using structured access control lists or Policy-as-Code engines like Open Policy Agent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
