INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6edd867d-81a5-4157-95e1-59dfbd5f8f58', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How do C# delegates interact with the garbage collector regarding object lifetimes?', N'Senior', N'Delegates hold a reference to the target object instance if the method is an instance method. If a delegate is stored in a long-lived object, it can inadvertently prevent the target object from being garbage collected, potentially causing memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdcb93b8-b0ad-4038-bf54-59e1abde466e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is an IIFE (Immediately Invoked Function Expression)?', N'Intern', N'An IIFE (Immediately Invoked Function Expression) is a JavaScript function that is defined and executed immediately after its creation. It is a design pattern used to execute code immediately and isolate variables from the global scope. Syntax: Example 01: Example 02: Create a private scope Use cases: * Data Privacy: Variables declared inside an IIFE cannot be accessed from the outside world. This protects your code from polluting the global scope. * Avoiding Naming Collisions: It prevents variables from accidentally overwriting other variables in third-party libraries or scripts. * State Preservation: Historically, it was used inside loops to lock in the current value of a variable during asynchronous operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
