INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bed77d29-3554-4507-9d36-59e6c1ce846c', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is Redis Pub/Sub?', N'Junior', N'Pub/Sub stands for Publish/Subscribe, a messaging paradigm where senders (publishers) send messages to channels, and receivers (subscribers) listen to those channels. It allows for real-time messaging between different parts of an application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a00bf394-c2b8-4c13-8841-59e9a5a1b3ff', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the difference between 1NF, 2NF, and 3NF?', N'Fresher', N'1NF requires atomic values and unique rows. 2NF builds on 1NF by removing partial dependencies. 3NF builds on 2NF by ensuring that all non-key attributes depend only on the primary key, eliminating transitive dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
