INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0675d8f2-39c7-47b8-adbf-59ee523193f5', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What does the term ''referential integrity'' mean?', N'Intern', N'Referential integrity is a property of data which ensures that all foreign key references are valid. It prevents the creation of orphan records by ensuring that a value in a foreign key column must match an existing value in the parent table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
