INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'264ca430-abb8-4508-89b6-59f6a7ec154d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is web storage', N'Intern', N'Web storage is an API that provides a mechanism by which browsers can store key/value pairs locally within the user''s browser, in a much more intuitive fashion than using cookies. The web storage provides two mechanisms for storing data on the client. 1. Local storage: It stores data for current origin with no expiration date. 2. Session storage: It stores data for one session and the data is lost when the browser tab is closed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
