INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'701dd594-d2e3-4c21-901e-5a17bde5b16b', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the role of the ''static'' folder in a Flask project?', N'Junior', N'The static folder is reserved for files that do not change, such as CSS stylesheets, JavaScript files, and images. Flask automatically provides a route to serve these files so that the frontend can easily access them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'928905a0-f301-4f4e-a7f0-5a18987130a3', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the difference between +page.svelte and +layout.svelte?', N'Intern', N'A +page.svelte contains the specific content for a single route, while a +layout.svelte contains common structure that wraps multiple pages. Layouts are useful for recurring UI elements like sidebars or navigation menus.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6139724-614c-43b0-b607-5a1e6666bc72', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a map in Go?', N'Intern', N'A map is a built-in data structure that associates keys with values. It allows for efficient lookups, updates, and deletions based on a unique key, similar to a dictionary or hash table in other languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6dc209f4-88ae-44b6-a577-5a2083073f7d', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Can Express serve multiple static directories?', N'Intern', N'Yes, you can call the express.static middleware multiple times for different directories. Express will look for files in the order that the middleware functions are mounted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e207045-66de-400c-9958-5a20b2f597c9', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is a ''Micronaut Feature'' or ''Module''?', N'Junior', N'A feature or module in Micronaut is a set of pre-configured dependencies and settings that provide specific functionality, such as database access, security, or messaging. Using these features simplifies project setup by automatically including the necessary libraries and configurations for common backend tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'549873d7-3df7-4024-8d39-5a25be3160db', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go handle errors compared to traditional exception handling?', N'Fresher', N'Go does not use try-catch blocks for error handling; instead, it treats errors as values that are explicitly returned by functions. Developers are expected to check these returned error values immediately after a function call to handle potential failures gracefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f1e5553-c332-4748-8122-5a271315e01a', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket facilitate horizontal scaling of backend services?', N'Senior', N'Rocket is inherently stateless, as it does not rely on local session storage or sticky sessions by default. This makes it ideal for deployment in containerized environments like Kubernetes, where instances can be scaled out horizontally behind a load balancer without shared session state issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9720656e-9a36-44b5-bee6-5a284a86aaa9', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Explain how Vite manages cache invalidation during development.', N'Senior', N'Vite appends a timestamp or a module hash to the request URL for modified files, forcing the browser to bypass its cache and fetch the latest version. This ensures that the developer always sees the most recent changes without needing to manually clear browser storage or perform hard refreshes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64808f1c-56af-4c36-b11f-5a2a2db2c1c2', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle HTTP methods like GET and POST?', N'Intern', N'Axum provides specific methods on the router to associate paths with HTTP verbs. Developers use these routing methods to ensure that only the correct HTTP method triggers a specific handler function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2362a910-b351-45dd-b2f2-5a2bf1533baf', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle concurrency and asynchronous task execution?', N'Senior', N'Litestar is built natively on ASGI, ensuring non-blocking operations for I/O-bound tasks. It manages concurrency by allowing handlers to be defined as asynchronous functions, which the event loop executes concurrently, effectively handling high-throughput scenarios without blocking the main execution thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97b8eab0-feb4-41cc-8bb6-5a2c74d97725', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is Middleware in ASP.NET Core?', N'Intern', N'Middleware are components that are assembled into an application pipeline to handle requests and responses. Each component chooses whether to pass the request to the next component in the pipeline and can perform work before and after the next component is invoked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f15c146-6967-4fb2-bf28-5a2ee07bd16c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you create self string using special characters', N'Fresher', N'The self string can be formed with the combination of []()!+ characters. You need to remember the below conventions to achieve this pattern. 1. Since Arrays are truthful values, negating the arrays will produce false: ![] === false 2. As per JavaScript coercion rules, the addition of arrays together will toString them: [] + [] === "" 3. Prepend an array with + operator will convert an array to false, the negation will make it true and finally converting the result will produce value ''1'': +(!(+[])) === 1 By applying the above rules, we can derive below conditions Now the character pattern would be created as below,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a42c38fe-e52a-4fb1-b6c9-5a2fc951fba4', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are the trade-offs of using an inline SVG versus an img tag for icons?', N'Middle', N'Inline SVGs allow for easier styling and animation via CSS or JavaScript because the elements are part of the DOM. However, inline SVGs can increase the overall HTML file size and prevent browser-level caching of the icon, unlike external image files. Use inline for icons that require interactivity and img tags for static icons that benefit from caching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5b3b28a-2800-4a5b-b72d-5a32605aaa78', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the role of ''CORS'' middleware in a Fiber application?', N'Middle', N'CORS middleware manages Cross-Origin Resource Sharing headers to control which domains are authorized to access the API. It is essential for web-based front-ends interacting with APIs hosted on different domains, ensuring security by enforcing browser-level access policies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5de89e8a-1391-4c6d-ac31-5a34825075c9', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are the performance implications of using ''contenteditable'' on large DOM trees?', N'Senior', N'Contenteditable forces the browser to manage a complex internal state for selection and input, which can lead to significant memory overhead and layout thrashing. For large documents, it is more performant to implement a custom virtualized editor or use a specialized library to avoid the limitations and inconsistencies of the browser''s native implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd663f593-7861-4776-b207-5a3ef38279f2', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala''s tail-call optimization work?', N'Middle', N'The compiler detects methods where the last action is a recursive call to the same function and replaces the recursion with a jump instruction. This prevents stack overflow errors by reusing the current stack frame instead of allocating a new one for each iteration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea903686-a6da-4628-a9b0-5a426126e6c4', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the role of the ''config'' folder?', N'Fresher', N'The config folder contains all of the application''s configuration files. These files allow you to manage settings for various services like database connections, mail servers, file systems, and session drivers in a centralized location.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
