INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3dd35a9f-7c4c-45e3-848f-5a4456377125', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between ''malloc'' and ''calloc''?', N'Intern', N'Both functions are used for dynamic memory allocation, but they differ in initialization. Malloc allocates a block of memory without clearing it, while calloc allocates a block and initializes all its bytes to zero.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6db2f878-7ee6-4ec7-8506-5a495728bc5e', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the impact of using non-blocking I/O on client-side connection pooling?', N'Senior', N'Because Redis is single-threaded and uses non-blocking I/O, client-side connection pooling is essential to minimize the overhead of establishing new TCP connections. Properly managed pools allow for the reuse of existing connections, which significantly reduces latency compared to creating a new socket for every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f9710f4-69f5-4cce-8cfa-5a49f0543049', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is structural typing?', N'Intern', N'TypeScript uses a structural type system, meaning that type compatibility is determined by the members of the type rather than its explicit name. If two objects have the same structure, they are considered compatible, regardless of their declared types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
