INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc97f73f-6243-40b9-b9cf-5a4e919a2824', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the role of GraalVM in the context of Quarkus applications?', N'Intern', N'GraalVM acts as a high-performance JDK that allows Quarkus applications to be compiled into native executables. This process, known as Ahead-of-Time compilation, removes the need for a standard Java Virtual Machine at runtime, significantly reducing startup latency and memory footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f89d863-cf67-413b-82e6-5a54792d2c36', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Why would you choose AdonisJS''s built-in validation system over manual schema validation?', N'Middle', N'The built-in validation system provides a declarative way to define data requirements that integrates directly with request inputs. It ensures consistent error handling, simplifies the controller code, and provides a centralized way to manage data integrity before it reaches your business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da710f8b-bce6-410f-bd39-5a580c8c7a91', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Why would you choose Astro over a traditional SPA framework for a blog?', N'Junior', N'Astro is better for a blog because it generates static HTML, which is easier for search engines to crawl and loads faster for users. SPAs often require large JavaScript bundles that are unnecessary for simple content websites.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bc4c69b-18f3-45d6-9bfe-5a5ab40a5005', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How do you handle error checking in C functions?', N'Middle', N'Error checking in C is typically handled through return values, where a function returns a specific error code or a null pointer to indicate failure. The caller is then responsible for checking these return values and implementing appropriate error handling or recovery logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
