INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33e3a309-d9c6-4fe1-a193-5a5cdce05153', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is Hibernate ORM in the context of Quarkus?', N'Fresher', N'Hibernate ORM is an extension in Quarkus used for database interaction. Quarkus optimizes it to work with native compilation, allowing developers to use familiar JPA annotations to manage database entities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9580091-4e85-4e47-9a74-5a5f51f57d89', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you address the ''N+1 query problem'' in API design?', N'Senior', N'The N+1 problem occurs when an API makes one request for a list and then N additional requests for related data. Mitigate this by using eager loading, data loaders to batch multiple requests into a single query, or by designing the API to allow clients to request nested resources within a single call.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4cdebaf-42b0-4ac3-ad1e-5a61fa05d803', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby manage memory, and what role does the Garbage Collector play?', N'Middle', N'Ruby uses a mark-and-sweep garbage collector that identifies objects that are no longer reachable from the root set. It periodically pauses execution to reclaim memory from these unreachable objects, helping manage the heap without requiring manual memory allocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73ddde0c-608a-4a5a-9ab4-5a66cec9cd91', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How do you handle distributed transactions in a sharded environment?', N'Senior', N'Distributed transactions are typically managed using the Two-Phase Commit (2PC) protocol or Sagas for long-lived processes. 2PC provides atomicity but impacts performance and availability, while Sagas decompose transactions into a series of local steps with compensating actions to handle failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5064d98-096c-416d-b12f-5a677710cc4f', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the architectural implications of using ValueTask instead of Task in high-throughput asynchronous C# systems.', N'Senior', N'ValueTask is a struct-based type that reduces heap allocations when an asynchronous operation completes synchronously. It is ideal for performance-critical paths where tasks frequently return cached results, though it carries risks of misuse, such as awaiting it multiple times or capturing it in a way that violates its single-use constraint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f9d9024-fdae-4006-9e8d-5a67bf1efd77', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the purpose of a ''back-of-the-envelope'' calculation in engineering?', N'Intern', N'A back-of-the-envelope calculation is used to quickly determine the feasibility or scale of a problem without needing high precision. It helps engineers decide if a proposed solution is in the right ballpark or if it is clearly unworkable. This saves time by filtering out poor ideas early in the design phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3409f7f9-92be-4447-b825-5a6821edfbe8', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to listen to state changes?', N'Fresher', N'The componentDidUpdate lifecycle method will be called when state changes. You can compare provided state and props values with current state and props to determine if something meaningful changed. Note: The previous releases of ReactJS also uses componentWillUpdate(object nextProps, object nextState) for state changes. It has been deprecated in latest releases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15f635fc-0934-4787-8aff-5a688b4e226e', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Why is it important to use ''final'' classes in a Symfony application?', N'Senior', N'Using ''final'' prevents unnecessary extension of services, promoting composition over inheritance. This creates more robust, predictable codebases where service behavior is easily traceable and not prone to accidental modification through subclassing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d9ef89b-6bbf-42e0-bc51-5a6be828402b', N'4c000000-0000-0000-0000-000000000005', N'Explain the ''Quorum'' model in distributed databases.', N'Senior', N'A quorum (W + R > N) ensures that the read set and write set overlap, providing strong consistency in a distributed system. By adjusting N, R, and W, architects can tune the system between latency, availability, and consistency requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
