INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93af95d5-eea1-46d3-ab27-5a8f50ad9089', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a ''hot key'' in Redis and how can it impact system performance?', N'Middle', N'A hot key is a single key that receives a disproportionately high volume of traffic, potentially causing a bottleneck on the specific shard holding that key. This can lead to CPU spikes on that node and uneven cluster load, which is often addressed by caching the key at the application level or splitting the key into multiple sub-keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
