INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6626382f-cf72-4ecf-a48f-5a94eb287499', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is monkey patching in Python?', N'Middle', N'Monkey patching refers to the practice of dynamically modifying or extending classes or modules at runtime. While it can be useful for debugging or patching third-party libraries, it often leads to fragile code that is difficult to debug and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1084c1c-8fb1-433e-8c00-5a97734e2b7c', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the difference between an exchange and a queue in RabbitMQ?', N'Middle', N'An exchange receives messages from producers and determines how to route them to queues based on routing keys and rules. A queue is the final buffer where messages are stored until they are pulled by a consumer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ae997bf-63f2-4c42-b505-5a977b464add', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Describe the difference between request-level and application-level middleware.', N'Middle', N'Application-level middleware is bound to the entire app object using app.use(), affecting every incoming request. Request-level middleware is bound to a specific route or router instance, only executing when a request matches that particular path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c65d2fb-d0a3-4762-a196-5a9a037a0ae1', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Explain the role of the ''lang'' attribute in HTML and its impact on search engines and accessibility.', N'Senior', N'The ''lang'' attribute specifies the language of the element''s content, which is critical for screen readers to select the correct speech synthesizer and pronunciation. Additionally, it helps search engines index content correctly and allows translation tools to provide more accurate results.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b1c8aab-c75e-4bb3-a5db-5a9c5a70d645', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is ''tower'' and its relationship with Axum?', N'Fresher', N'Tower is a library of modular and reusable components for building robust network services in Rust. Axum is built on top of Tower, meaning it can leverage middleware, services, and utilities provided by the Tower ecosystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2eb0c901-4ad5-4d9c-b060-5a9ce7763a17', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the difference between path parameters and query parameters in FastAPI, and how are they defined?', N'Middle', N'Path parameters are part of the URL structure and are defined as variables within the path string, while query parameters are appended after a question mark in the URL. FastAPI automatically differentiates between them based on whether the argument is declared in the path string or as an additional function parameter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a142f1a4-02a7-494e-9a19-5a9f0a338999', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the difference between development and production environments in Symfony?', N'Intern', N'The development environment is optimized for debugging, featuring detailed error messages and the profiler. The production environment is optimized for security and performance, disabling debug tools and caching configuration for faster execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e23e1906-a096-4e07-ae5e-5a9f4fb931f2', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If you are asked to use a technology you have never worked with before, how do you approach learning it?', N'Intern', N'I would start by reviewing official documentation or reputable tutorials to understand the core concepts and basic use cases of the technology. Then, I would attempt to build a small, isolated project to apply what I have learned, which helps me identify gaps in my understanding and gain practical familiarity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'527b8d05-dea4-4f6a-b5f0-5aa02626c341', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How do you manage database migrations in a Spring Boot application?', N'Middle', N'Tools like Flyway or Liquibase are commonly integrated into Spring Boot to manage schema evolution. They track migration scripts in a dedicated database table, ensuring that schema changes are applied consistently and sequentially across different environments, preventing state drift.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b17f41e9-ebac-4d2b-a39f-5aa2e7501833', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the benefit of Svelte''s compile-time approach?', N'Intern', N'By doing the work during the build phase, Svelte produces a small, efficient bundle that does not include the overhead of a framework runtime. This leads to faster page load times and better performance on lower-end devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee8aa1be-240f-489d-98e1-5aa9ac6065b8', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the difference between require() and import?', N'Intern', N'require() is part of the CommonJS module system traditionally used in Node.js for synchronous module loading. import is part of the ES Modules standard, which supports asynchronous loading and is the modern way to handle modules in JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ac250b9-a184-4337-b8a2-5aa9e4e1231c', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle a scenario where a database migration is causing unexpected performance degradation on a production system?', N'Middle', N'I would immediately pause the migration if possible to mitigate impact and assess the resource utilization of the database. If the degradation is caused by lock contention or inefficient queries, I would consider reverting the changes, optimizing the migration strategy, or running the operation during off-peak hours.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c8c85a0-b34b-4ffb-b3af-5aaa4cee1b5d', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Describe how you would handle a schema migration in a massive database without incurring downtime.', N'Senior', N'I would use an expand-and-contract pattern where the database schema is updated to support both old and new versions simultaneously. Application code is deployed in phases to write to both formats, followed by a background migration of existing records, and finally, the removal of the old schema once the transition is complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'793bf884-0b70-49c5-b6a8-5aaf0268ba71', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is Composer in the context of Laravel?', N'Intern', N'Composer is a dependency manager for PHP that Laravel uses to manage its own framework dependencies and third-party libraries. It ensures that all required packages for your project are installed and updated correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c13f383-448a-4678-98ff-5ab1c5eac62d', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is jQuery chaining?', N'Intern', N'Chaining is a feature that allows multiple jQuery methods to be called on the same set of elements in a single statement. Each method returns the jQuery object itself, which allows the next method to be immediately appended to the sequence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d06879f-e50a-486b-b43b-5ab4bc55744c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is scope in javascript', N'Intern', N'Scope is the accessibility of variables, functions, and objects in some particular part of your code during runtime. In other words, scope determines the visibility of variables and other resources in areas of your code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04147af6-e0e7-4b11-be05-5ab76521ad0a', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the significance of the ''ThreadLocal<T>'' class?', N'Middle', N'ThreadLocal provides storage for data that is unique to each individual thread. This is useful for avoiding locking mechanisms in scenarios where each thread needs its own instance of an object to perform calculations independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'887bc84c-ea46-4e63-a3ec-5abb3de19cec', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the four common types of NoSQL databases?', N'Fresher', N'The four common types are document stores, key-value stores, wide-column stores, and graph databases. Each type is optimized for specific data structures and access patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c18646e6-38af-4a2a-95d6-5abd35109445', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does HTML5''s ''hidden'' attribute differ from CSS ''display: none'' in terms of accessibility and behavior?', N'Senior', N'The ''hidden'' attribute is a semantic instruction that indicates the element is not relevant, causing user agents to omit it from the accessibility tree and rendering. Unlike ''display: none'', which is purely a styling concern, ''hidden'' provides a clearer intent for assistive technology and can be overridden by CSS, though such practices are discouraged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa1462b0-6d63-443b-8d2a-5abe0203172f', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the ''Thundering Herd'' problem and how can you mitigate it?', N'Middle', N'The thundering herd problem occurs when a large number of requests hit a service simultaneously after it recovers or after a cache expiration. It can be mitigated by using jitter, which introduces randomized delays into the client retry logic to spread the load over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14bfadb2-3bf1-40de-8a90-5abe3dcaff75', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus handle application metrics?', N'Middle', N'Quarkus integrates with MicroProfile Metrics to expose application data in a format compatible with monitoring tools like Prometheus. This allows for real-time observability of application performance and health without custom instrumentation code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b9a43e2-a1e7-4f15-8ea2-5abe8ec507a6', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js handle middleware execution, and what are the performance implications of complex logic in the middleware layer?', N'Senior', N'Middleware runs before a request is completed, executing in an isolated V8 runtime at the edge. Heavy computation or long-running database queries in middleware can increase the Time to First Byte (TTFB) globally, so logic should be restricted to lightweight tasks like authentication checks or path rewrites.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f9cae61-a727-49eb-a011-5ac07c878295', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What does it mean that Hono is ''Web Standard'' based?', N'Intern', N'Being Web Standard based means Hono uses native APIs like Request, Response, and URLPattern instead of custom implementations. This allows it to run seamlessly across different JavaScript runtimes without requiring heavy polyfills.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e9fa32e-5e77-4e7f-97c4-5ac2dcad363b', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is data independence?', N'Intern', N'Data independence is the ability to change the schema at one level without affecting the schema at the next higher level. - Physical data independence – move/resize data files without changing the logical schema. - Logical data independence – add columns to a table without breaking views or applications. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c304c29-ac37-4ee6-8671-5ac4582bbb97', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the role of Composer in a PHP project''s dependency management.', N'Middle', N'Composer acts as a package manager that resolves version dependencies and handles the autoloading of classes via a standardized autoloader. By centralizing library management, it ensures consistent environments across development and production. It prevents dependency hell by enforcing strict version constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acf2e1de-818b-47b9-84d7-5ac7b65f5d7b', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Describe the mechanism of the ''Address'' lifecycle and how it relates to actor termination.', N'Senior', N'The address is a handle to the actor''s mailbox; when all addresses to an actor are dropped, the actor receives a signal to stop. This ensures that the system can gracefully shut down components once they are no longer reachable or needed by the rest of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f3ba428-e0f7-4660-9587-5ac7e17dfcf9', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you manage stakeholder expectations when an estimate needs to be revised upward?', N'Middle', N'I provide the revised estimate as soon as the new information is available, explaining the specific technical challenges or complexities that caused the change. I then offer options, such as de-scoping non-essential features, to help the stakeholders achieve their core objectives within the original timeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a288288d-f0f7-4f80-a04d-5ac7e7594da4', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What are the advantages of Route Groups in the App Router?', N'Middle', N'Route groups allow you to organize files into logical groups without affecting the URL path structure. They are useful for applying specific layouts to a subset of routes while keeping the folder structure clean and organized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5ba9dc0-a51a-4e62-a070-5acfdf430a82', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the Symfony Kernel?', N'Intern', N'The Kernel is the heart of a Symfony application, responsible for handling the request-response lifecycle. It receives an HTTP request, passes it through the system''s various components—like the router and event listeners—to eventually return an HTTP response. It serves as the primary gateway that boots the application and manages its execution flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'469a7c23-982f-4a3b-9055-5ad144378fc5', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is Ember.js?', N'Intern', N'Ember.js is an open-source JavaScript framework used for creating ambitious single-page web applications. It follows the model-view-controller architectural pattern and emphasizes convention over configuration to simplify development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa61d056-ddd4-465a-833f-5ad3d95debce', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do you optimize background job processing for high-throughput queues?', N'Senior', N'Optimization involves adjusting concurrency settings, scaling worker processes independently based on queue depth, and ensuring jobs are idempotent. Additionally, grouping small jobs or using priority queues can prevent critical tasks from being stuck behind low-priority background work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b175bfb1-44e8-44fe-9e78-5ad6e6e31a64', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Explain the concept of tree shaking and how it works in Webpack.', N'Middle', N'Tree shaking is a dead-code elimination technique that removes unused exports from the final bundle. It relies on the static structure of ES6 module syntax, which allows Webpack to detect which exports are not imported or used by any other part of the application during the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'364bfc60-7c63-4fd7-859f-5ad715ee8057', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the purpose of ''middleware.ts'' in Next.js?', N'Middle', N'Middleware allows you to run code before a request is completed, enabling tasks like redirects, URL rewrites, or header modifications. It is executed on the edge, making it an efficient place to perform authentication checks or geo-based localization before the page content is rendered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6e4232a-2f1d-410e-8d96-5ad861d3e9be', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the JVM ensure memory consistency for volatile fields without using heavy locks?', N'Senior', N'Volatile fields rely on hardware-level memory barriers or fences to prevent the CPU from reordering memory access around the variable. This ensures that the thread reading the variable sees the most recent write performed by any other thread, providing visibility without the overhead of full monitor acquisition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b77f1ebd-0223-4b7b-afd8-5adaa2ab0a33', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the ''hono/validator'' feature?', N'Intern', N'The validator feature in Hono allows developers to define rules for incoming request data, such as headers, queries, or body content. It ensures that the data meets expected formats before it reaches the core business logic, preventing processing errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
