INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fb1f4d1-0a5d-4a8c-b2c4-5afe62f84e95', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does ''Lazy Evaluation'' in Scala improve performance for resource-intensive objects?', N'Senior', N'Lazy evaluation delays the initialization of an object or value until it is first accessed, preventing unnecessary computations or memory allocation. This is particularly valuable for large data structures or expensive network connections that might not be needed in every execution branch. However, it introduces subtle complexity regarding thread safety and initialization order that must be carefully managed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
