INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00d9ee22-bfdb-4071-a20e-5b15bf225c48', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How do you prevent ''thundering herd'' problems when a database node fails?', N'Senior', N'To prevent a thundering herd, implement exponential backoff with jitter on the client side and use request collapsing or caching at the proxy level. This ensures that when a node recovers or is replaced, it is not immediately overwhelmed by a massive surge of simultaneous connection requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
