INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b15dbc2-9055-4d03-8b8b-5b171f0da2a5', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of the main function in a C program?', N'Fresher', N'The main function serves as the entry point for the execution of any C program. When a program is run, the operating system calls this function first, and the program terminates once the main function finishes execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ac27972-d0cd-47d2-a6ab-5b1a44f72e1b', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do database checkpoints work to balance recovery time and runtime overhead?', N'Senior', N'Checkpoints periodically flush modified data pages to disk and record a known consistent point in the transaction log. Frequent checkpoints reduce recovery time after a crash but increase disk I/O load, while infrequent checkpoints improve runtime performance at the cost of longer recovery cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99ade9d5-5585-4206-aec5-5b1bae947853', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are SvelteKit ''hooks''?', N'Intern', N'Hooks are functions that allow you to intercept and modify the behavior of requests and responses. They are commonly used for tasks like authentication, authorization, or setting custom headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e4d1e41-ab8c-41c3-b594-5b1d7cf26e4e', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How do extension functions affect the design of public APIs?', N'Senior', N'Extension functions allow for the addition of functionality to existing classes without modifying their source code, which enables a more modular and fluent API design. However, they are resolved statically, meaning they cannot be overridden polymorphically, which is an important trade-off to consider when building libraries that rely on inheritance-based customization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3938962d-ed3e-4baf-b6ee-5b24c6cec859', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How do jQuery selectors differ from standard CSS selectors?', N'Junior', N'jQuery selectors use the same syntax as CSS selectors to identify elements, but they also support additional custom pseudo-selectors provided by the library. While CSS selectors are used for styling, jQuery selectors are used to fetch DOM elements for interaction and manipulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
