INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01b88cd3-78d9-4948-a85d-5b2ae54d431d', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is a Webpack ''manifest'' and why is it useful?', N'Middle', N'A manifest is a JSON file that maps the original file names to the final, hashed output files generated by Webpack. It is useful for server-side rendering or complex build pipelines where other tools need to know the correct, hashed paths of the generated assets to load them correctly in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
