INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ee51a18-1f3a-4726-bd7b-5b34bbf86ac0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of the this keyword in JavaScript?', N'Intern', N'The this keyword in JavaScript refers to the object that is executing the current function. Its value is determined by how a function is called, not where it is defined. this is essential for writing object-oriented and event-driven code, as it allows methods to interact with the data of the object they belong to. Example 1: this in a Global Context - In a global context, this refers to the global object (e.g., window in a browser). Example 2: this in a Function - In a regular function, this refers to the global object(window in browser and global in nodejs) for non-strict mode. In strict mode, it''s value is undefined. Example 3: this in a Method - In a method, this refers to the object that owns the method (person in the case).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
