INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ceb5485b-d57e-4b31-9e0f-5b37b61902b0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you avoid receiving postMessages from attackers', N'Fresher', N'Since the listener listens for any message, an attacker can trick the application by sending a message from the attacker’s origin, which gives an impression that the receiver received the message from the actual sender’s window. You can avoid this issue by validating the origin of the message on the receiver''s end using the “message.origin” attribute. For example, let''s check the sender''s origin http://www.some-sender.com on receiver side www.some-receiver.com,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
