INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75a3fa47-2dc5-4dc1-8ea7-5b3b7bbaccbe', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does ''Database Replication Lag'' impact system design when implementing Read-Write splitting?', N'Senior', N'Read-write splitting directs writes to a primary node and reads to replicas, which introduces eventual consistency. If the application requires ''read-your-writes'' consistency, the architecture must account for lag by routing the user to the primary node for a short window after a write or using sticky sessions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
