INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4eb1cf30-fb03-4f87-a914-5b41b7866aff', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What does Server-Side Rendering (SSR) mean in the context of Nuxt?', N'Intern', N'SSR means that the server generates the HTML for a page on each request instead of the browser building it from scratch. This ensures that users see the content faster and search engines can easily index the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ff1d8f9-d5de-49a5-9bc2-5b43083105ae', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the browser''s CSS rendering pipeline determine specificity and order of precedence?', N'Middle', N'The browser calculates specificity based on the types of selectors used, such as IDs, classes, and elements, and applies the rules with the highest weight. If specificity is equal, the document order takes precedence, with the last defined rule winning. Additionally, origin and importance, such as ''!important'' tags, override these standard calculations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db3f92d3-2246-40be-91dc-5b451a9c20b3', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Explain the architectural impact of the Shadow DOM on global CSS styles.', N'Senior', N'Shadow DOM provides true style encapsulation by creating a boundary between the main document and the custom element''s subtree. This prevents global CSS from leaking into the component and prevents the component''s internal styles from affecting the rest of the application, effectively mitigating CSS specificity wars.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88a00726-2986-4156-adef-5b453e39a0ba', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are the trade-offs of using Hono''s ''RPC'' mode compared to traditional REST APIs?', N'Middle', N'RPC mode allows for end-to-end type safety between the client and server by sharing type definitions. The main trade-off is the tighter coupling between the client and server codebase, which may increase build complexity compared to a loosely coupled REST approach.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'278aa037-2e41-4800-9914-5b46a5d96e4e', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle DOM fragmentation and its effect on browser reflows?', N'Senior', N'Since Alpine.js modifies the DOM directly, every directive change potentially triggers a browser reflow or repaint. Senior developers must minimize these impacts by using x-show for visibility toggling instead of x-if for elements that frequently change, as x-if completely destroys and recreates DOM nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60ba023b-cd3d-4fd4-89e7-5b46cd4dac3e', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the concept of ACID properties?', N'Intern', N'ACID stands for Atomicity, Consistency, Isolation, and Durability, which are the properties that ensure reliable transaction processing. These properties guarantee that database operations are completed successfully and remain reliable even in the event of system failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'103d4189-2d43-4ea8-af49-5b4773151a78', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the difference between physical and logical replication?', N'Senior', N'Physical replication copies the actual data blocks, making it very fast but requiring identical database versions and hardware configurations. Logical replication decodes transactions into row-level operations, allowing for greater flexibility, such as replicating between different database versions or filtering specific tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3e6f709-f1bb-4a19-a512-5b49b733a7e3', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does the ''Durability'' property survive hardware failures?', N'Middle', N'Durability is achieved by ensuring that once a transaction is committed, its effects are written to non-volatile storage, such as disk or SSD. Even if the system crashes immediately after, the database recovery process can restore the committed changes using the transaction logs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87354ebc-fde7-493f-9faf-5b4b396d4a6f', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Does Axum support asynchronous programming?', N'Intern', N'Yes, Axum is built natively on top of the Tokio runtime, which provides asynchronous I/O. Every handler function in Axum is asynchronous, allowing the server to handle many concurrent connections efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bce730d-01ea-41ac-b29b-5b4cbc153e5b', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What makes Qwik ''O(1)'' regarding bundle size?', N'Middle', N'Qwik is considered ''O(1)'' because the amount of JavaScript downloaded is constant regardless of the application''s size. As you add more features, you are simply adding more code chunks that are only loaded when accessed, rather than increasing the initial bundle size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'669d919b-5a28-4604-87de-5b4ce9159f28', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between an ''internal'' function and a ''userland'' function in the context of PHP execution?', N'Senior', N'Internal functions are compiled directly into the PHP binary as C code, offering significantly faster execution with minimal overhead. Userland functions are parsed from PHP source into opcodes that must be interpreted by the Zend VM, incurring a performance penalty compared to internal counterparts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'927dbfbc-76fa-4742-9b11-5b4d0c48e853', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How do C++ memory models handle the interaction between the compiler''s instruction reordering and hardware-level memory consistency?', N'Senior', N'C++ uses a formal memory model that defines a happens-before relationship to provide a contract between the developer and the compiler. The compiler and hardware are restricted from reordering operations that would violate this model, provided the developer uses appropriate atomic operations and memory barriers. This ensures that multi-threaded programs exhibit predictable behavior despite aggressive platform-specific optimizations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03357c57-991a-478a-a91f-5b4e5dbc3513', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Compare Tailwind''s approach to ''component style encapsulation'' with Shadow DOM.', N'Senior', N'Tailwind relies on standard global CSS, which can be affected by the cascade, whereas Shadow DOM provides strict style isolation. While Tailwind classes can be used within Shadow DOM, they must be injected into every shadow root, which can increase the total memory footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee3c231f-7176-4cf3-aba1-5b5097d8c28f', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the primary benefit of using a ''prepared transaction'' in a two-phase commit scenario?', N'Senior', N'Prepared transactions allow a transaction to be stored in a ready-to-commit state across different nodes in a distributed system. This ensures atomicity across multiple databases by allowing a coordinator to verify that all participants are ready before finalizing the change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a48d2a6a-5e81-4210-aab8-5b51897e0ecb', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch handle the ''split-brain'' scenario in a distributed cluster?', N'Senior', N'Elasticsearch prevents split-brain by requiring a quorum of master-eligible nodes to elect a leader. Modern versions use an internal cluster coordination sub-system that enforces strict voting configurations, ensuring that only one partition of the cluster can act as the master at any given time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4c1c8ca-ea36-4059-b299-5b52e0972925', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Why is Astro considered a ''Content-Driven'' framework, and how does this affect its utility in enterprise applications?', N'Middle', N'Astro is optimized for content-heavy sites like documentation, blogs, and marketing pages where SEO and performance are paramount. While it supports complex UI via framework integrations like React or Vue, it lacks the built-in state management and runtime overhead of those frameworks, making it less ideal for highly interactive, state-heavy dashboard applications. Its strength lies in orchestrating multiple UI libraries within a performant, static-first shell.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7407b7c-c7fc-4e33-a205-5b5670418dcb', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are properties in C# and how do they differ from fields?', N'Junior', N'Properties provide a flexible mechanism to read, write, or compute the values of private fields using accessors like get and set. They offer more control over data access, such as adding validation logic, compared to public fields which expose raw data directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74a48291-599e-47d0-be4f-5b56c2a7bdec', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Does Quarkus support reactive programming?', N'Intern', N'Yes, Quarkus is built on a reactive foundation using Vert.x. It supports non-blocking input/output, which allows applications to handle a large number of concurrent connections with fewer system resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ce1a1e4-20dc-4838-b7f3-5b56d63a1d6d', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the role of the ''GCHandle'' structure?', N'Middle', N'GCHandle allows a programmer to create a handle to a managed object that the garbage collector can track. It is primarily used to pass managed objects to unmanaged code, ensuring that the object is not moved or collected while the unmanaged code is using it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
