INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3bb5d67-317e-4691-8bb8-5b586f667db5', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are the limitations of using standard Express error-handling middleware?', N'Middle', N'Standard error middleware is synchronous in nature and does not automatically handle errors thrown inside event emitters or external callbacks unless wrapped correctly. It also lacks built-in mechanisms for centralized logging or structured error reporting without custom implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e80f634a-517b-4d9b-bd37-5b59b63becea', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the difference between lexical scoping and dynamic scoping in the context of R?', N'Middle', N'R primarily uses lexical scoping, where the value of a free variable is determined by the environment in which the function was defined, not where it is called. This predictable behavior allows for functions to maintain private states through closures. While some base R functions simulate dynamic-like behavior, relying on lexical scoping is fundamental for writing modular and maintainable R code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c02657c-115d-4750-9b62-5b5bb35eac09', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the risks associated with moving from a monolithic database to a polyglot persistence strategy?', N'Senior', N'I evaluate the complexity of maintaining multiple storage engines and the overhead of data synchronization across services. I estimate the risk of data inconsistency, operational complexity, and the requirement for specialized expertise against the performance benefits of using the right tool for each data type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'744c7585-6a31-4e03-970c-5b5ed35fbddd', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Describe the function of the InnoDB Transaction System (trx_sys).', N'Senior', N'The transaction system manages the global state of all active transactions, including the assignment of transaction IDs and the maintenance of the read view. It is critical for MVCC, as it allows each transaction to determine which versions of data it is permitted to see based on its snapshot timestamp.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
