INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf7769bb-1d71-4675-9942-5b638519f93d', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What factors influence your choice between horizontal and vertical scaling?', N'Middle', N'Vertical scaling is often simpler but capped by hardware limits and creates a single point of failure. Horizontal scaling is preferred for long-term growth and high availability because it allows adding commodity hardware and improves fault tolerance through redundancy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
