INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af9960ee-572d-4afc-9318-5b66e95e79e4', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the significance of the ''transaction ID wraparound'' issue.', N'Senior', N'PostgreSQL uses a 32-bit integer for transaction IDs, which eventually exhausts its range. The system prevents data loss by forcing a freeze operation, where old tuples are marked as permanently visible to all transactions, effectively resetting their ID age before the wraparound limit is reached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32cb66fd-aa56-4e4c-86ec-5b67bc9fe460', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the function of the __destruct method?', N'Junior', N'The __destruct method is a magic method called automatically when an object is destroyed or the script execution ends. It is typically used to perform cleanup tasks, such as closing file handles or database connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0459e4ff-77d3-40b7-b8b3-5b6ab6ebfcae', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI leverage Python''s type hints to improve application performance and reliability?', N'Middle', N'FastAPI uses type hints to perform automatic data validation and serialization via Pydantic. By enforcing types at the entry point, the framework reduces the likelihood of runtime errors and allows for the generation of accurate OpenAPI documentation without manual effort.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb2e3256-4240-45cd-b3e8-5b6c77efe5aa', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why is it important to consider the ''Read Capacity Unit'' (RCU) and ''Write Capacity Unit'' (WCU) calculations during design?', N'Senior', N'Capacity units define the throughput and cost of the database; miscalculating these leads to either performance bottlenecks or unnecessary over-provisioning. Designing for efficient access patterns ensures that the number of items read or written per request is minimized, directly impacting both latency and operational expense.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1de8c64-a057-4ab5-96d7-5b6d683e272b', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the ''Read Repair'' mechanism, and when does it trigger?', N'Senior', N'Read Repair compares data across replicas when a client request is made and updates any inconsistent replicas to the latest version. It is triggered during a read operation based on the ''read_repair_chance'' configuration or when a read request spans multiple replicas, helping to maintain eventual consistency without explicit background repairs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fccaebec-0554-4056-bc58-5b6da26d81df', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are Defer statements used for?', N'Fresher', N'The defer statement is used to execute a set of statements just before the current scope is exited. It is commonly used for cleanup tasks, such as closing file handles or resetting variables, regardless of how the function scope is exited.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8104cb86-6926-4e3b-b649-5b6e8f5ede26', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of the EventDispatcher component?', N'Junior', N'The EventDispatcher implements the observer pattern, allowing different parts of the application to communicate by triggering and listening to events. It enables developers to hook into the lifecycle of an application, such as performing actions before or after a request is handled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b98e011-2603-420a-9d50-5b6f388f7fbf', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit optimize the loading of assets and JavaScript?', N'Middle', N'SvelteKit uses code-splitting to ensure that only the JavaScript required for the current page is sent to the client. This reduces the initial bundle size and speeds up the time to interactive, as the browser only downloads what is necessary for the current view.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'119318b2-8f59-42d5-a9b0-5b6fb1e69bb5', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the significance of the Send and Sync traits in Actix-web?', N'Intern', N'Send and Sync are Rust marker traits that define thread safety. Actix-web requires shared state to implement these traits to ensure that data can be safely moved or referenced across different threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'797080c6-abde-48e0-8b02-5b7538a7cd9c', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a database constraint?', N'Fresher', N'A constraint is a rule applied to a table column to limit the type of data that can be inserted. Common examples include NOT NULL, UNIQUE, CHECK, and PRIMARY KEY.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
