INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a179f9d-3282-4954-9144-5b7736d6cfe7', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between an environment in Rails?', N'Intern', N'Environments are different settings configurations for the application, typically divided into development, test, and production. Each environment allows you to isolate settings like database credentials, logging levels, and feature flags to ensure the application behaves appropriately in each stage of development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'070bc31b-9b9b-406c-b8ee-5b777451651a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What steps would you take to optimize a slow database query?', N'Middle', N'I would analyze the query execution plan to identify missing indexes, full table scans, or inefficient joins. Based on the analysis, I would add appropriate indexes, optimize the query structure, or denormalize data if read performance is the primary concern.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e138a7a-100b-4dfa-8117-5b77fb5b7f72', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the purpose of ''Group'' routing in Fiber?', N'Fresher', N'Group routing allows developers to organize routes that share a common prefix or middleware. This is useful for versioning APIs, such as grouping all routes under ''/api/v1'', or applying specific security constraints to a set of related endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0080f6a-e3ff-4159-bc1e-5b7843939633', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Explain how Lit handles server-side rendering (SSR) and hydration.', N'Middle', N'Lit supports SSR by rendering templates to a string on the server, which is then sent to the client. Upon loading, the client-side ''hydrate'' function attaches event listeners and reactive logic to the existing static DOM, avoiding a full re-render and significantly improving the First Contentful Paint metrics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd30398f2-9f89-4dcb-860b-5b786d8d8a20', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of the ''jsonify'' helper function?', N'Middle', N'The ''jsonify'' function serializes a Python dictionary or list into a JSON string and sets the appropriate application/json content-type header. It simplifies the process of returning API responses by ensuring the data is properly formatted and the headers are set correctly. It is a standard practice for consistency in JSON-based backend services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3d1c25d-ec91-4268-9ec0-5b7ee2fa772b', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the benefit of using Quarkus for serverless computing?', N'Intern', N'In serverless environments, applications must start quickly to avoid latency during ''cold starts'' and stay within memory limits. Quarkus is ideal for this because its native compilation provides near-instant startup and very low memory overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a28497c7-4187-481a-8afa-5b7f49d78d58', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How can Redux middleware be used to implement global logging or analytics without polluting component logic?', N'Senior', N'Middleware acts as a pipeline between the dispatch call and the reducer, allowing you to intercept and inspect every action. By creating a custom middleware, you can cleanly extract specific action data and send it to logging services or analytics platforms without touching individual UI components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ed55cb2-62db-4f42-809a-5b80023ac1f3', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Discuss the impact of Hono’s small bundle size on infrastructure costs.', N'Senior', N'The minimal bundle size reduces the cold-start initialization time, which is particularly beneficial in serverless environments where execution time is billed. Lower cold-start times lead to fewer function invocations timing out or needing warm-up, directly reducing infrastructure costs in high-traffic, bursty applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'253643b5-77e1-4ca4-8728-5b80104fca8c', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the difference between an application-level middleware and a route-level middleware in Hono?', N'Junior', N'Application-level middleware runs for every single request that enters the application, while route-level middleware is only executed when a request matches a specific path or group of routes. This distinction allows for fine-grained control over which security or logging logic is applied.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90e275ec-319f-4573-971e-5b805f277005', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you verify that a fix has actually solved a problem?', N'Fresher', N'Verification involves running the steps that previously caused the error to ensure they no longer produce the same fault. Additionally, you should perform regression testing to ensure the fix did not unintentionally break other parts of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ab01b2a-7873-4a8e-9e44-5b866ba96a73', N'954a0331-deff-4399-b588-96f39fec001d', N'How does the ''Platform-agnostic'' nature of Angular influence its ability to support different environments like Web Workers or NativeScript?', N'Senior', N'Angular separates the framework core from the rendering layer (the platform), allowing the same business logic and components to run in different environments. By swapping the platform provider, you can render an app to the DOM, a server environment, or even native mobile components, providing a unified architecture across different targets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
