INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b815457-02da-4e7d-a414-5b983b286308', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the purpose of an idempotent consumer in event-driven architectures?', N'Senior', N'Idempotent consumers ensure that processing the same event multiple times does not result in unintended side effects or duplicate data. This is critical in distributed systems where ''at-least-once'' delivery guarantees often result in retried messages reaching the consumer after a network partition or timeout.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcf6dc42-e5cb-4605-b006-5b9de1eb4781', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Why is ''data class'' restricted from being inherited?', N'Senior', N'Data classes are designed primarily as pure data containers. Allowing inheritance would break the structural equality (equals/hashCode) and data-copying mechanics that rely on a known, fixed set of properties defined at the class level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3655528-6a9f-4188-a1c2-5b9de269d159', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the role of the ''hooks.server.js'' file in a SvelteKit application?', N'Middle', N'Hooks are interceptors that allow you to modify or inspect every request coming into the server. They are commonly used for authentication checks, setting custom response headers, or transforming the data before it reaches the page load functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'525a5ea8-57c8-41bb-908d-5ba101738d99', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What trade-offs are involved when choosing Chi for a high-performance microservice?', N'Middle', N'Chi is highly performant because it is lightweight and has zero dependencies, making it faster than many ''batteries-included'' frameworks. The main trade-off is that it does not provide built-in solutions for features like ORMs, validation, or dependency injection, requiring the developer to select and integrate these libraries independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59793a27-32dc-4a17-a141-5ba19924d056', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Does Qwik require a specific server-side environment?', N'Intern', N'Qwik is designed to be platform-agnostic and can run in various server environments, including Node.js, edge functions, and serverless platforms. This flexibility makes it easy to deploy on modern cloud infrastructures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3c16e09-85c1-4f3a-b7d6-5ba2a797a31b', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is a request handler in Rocket?', N'Fresher', N'A request handler is a function decorated with a route attribute that processes an incoming HTTP request. It receives input from the request, performs logic, and returns a response to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f764d49b-7277-4b8b-a5a2-5ba2de9ac41d', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is ''hydration'' in the context of Preact?', N'Intern', N'Hydration is the process where Preact takes over the static HTML generated by a server and attaches event listeners to it. This makes the page interactive without needing to re-render the entire DOM structure from scratch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4f6acd6-002b-4cbe-a42c-5ba5107f3d89', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle navigation?', N'Intern', N'Qwik City handles navigation using directory-based routing. It provides a file-system-based router that makes defining page structures and nested layouts straightforward for developers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5325b1e9-abd6-4641-8980-5ba5b6d75f05', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL handle deadlocks?', N'Middle', N'PostgreSQL detects deadlocks automatically using a background process that monitors lock wait queues. When a cycle of dependencies is detected, the database aborts one of the transactions involved, allowing the others to proceed and preventing the system from freezing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b03bcd31-ade5-41cf-a430-5ba6fdea0dd9', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Explain the difference between ''Synthetic Monitoring'' and ''Real User Monitoring'' (RUM).', N'Middle', N'Synthetic monitoring uses scripts to simulate user interactions at regular intervals to test availability from different locations. RUM collects performance data from actual users interacting with the application in real-time, offering a more accurate picture of the real-world user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd72c81c6-1a9f-489c-a821-5ba71b816ccc', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the advantages and disadvantages of using *args and **kwargs?', N'Middle', N'These allow functions to accept a variable number of positional and keyword arguments, providing great flexibility for wrapper functions or decorators. However, overuse can make the function signature opaque, making it difficult for developers to know what arguments are expected without inspecting the implementation. They should be used judiciously to maintain code readability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b72884e-6a9e-42cc-b946-5ba98bef102d', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are the trade-offs of using ''deferred loading'' in a large-scale Dart application?', N'Senior', N'Deferred loading allows for lazy loading of libraries, which significantly reduces the initial application bundle size and improves startup time. The trade-off is the introduced complexity of handling asynchronous loading states and the potential for runtime errors if a deferred library fails to load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9cadcd6b-3fa6-4105-91f5-5bacb8c79cae', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How can you leverage NestJS ''Testing'' utilities to isolate services from their external infrastructure dependencies?', N'Senior', N'The NestJS Testing module allows you to create a mock DI container where you can replace real service implementations with mocks, stubs, or fakes. By isolating the unit under test from its real database or network clients, you ensure tests are fast, deterministic, and focus solely on the business logic of the service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'353c8a73-aae5-46f8-b0bb-5bacc2f05a07', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain how JavaScript handles string interning and its impact on memory.', N'Senior', N'String interning stores only one instance of a string literal, reducing memory usage when the same string appears multiple times. This is particularly effective for property names and small, repeated strings, though it requires careful management during string concatenation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a3585de-e295-4510-a361-5bb02ad2e45d', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does health checking differ from liveness and readiness probes?', N'Middle', N'A liveness probe checks if a service is running and should be restarted if it fails. A readiness probe checks if a service is prepared to accept traffic, preventing it from receiving requests before it has finished its initialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad798fc4-6730-4c13-bbf5-5bb7064e101e', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between a physical and a logical database backup?', N'Middle', N'Physical backups copy the raw data files directly, which is faster for large databases but requires the same database version for restoration. Logical backups use commands to export data into SQL format, which is more flexible, portable across versions, and allows for selective object recovery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
