INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'062641f7-724f-4f36-81a6-5bba189126ce', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of the Symfony Dependency Injection container, and why is it useful for a developer?', N'Junior', N'The Dependency Injection container is a tool that manages the instantiation and lifecycle of objects within an application. It allows developers to define services as independent units and inject them where needed, which makes the code more modular, easier to test, and reduces tight coupling between different parts of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
