INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e5d6912-e165-4656-822e-5bbed32df784', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Describe the trade-offs of using Chi''s sub-router pattern for modular service design.', N'Senior', N'Sub-routers enable excellent logical separation of concerns, allowing teams to own specific API versions or modules. However, excessive nesting can make tracing request paths slightly more complex, and one must be careful with middleware inheritance to avoid unintended side effects across different modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c0df374-e3bc-4b6f-bb0d-5bc0bdb14888', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is middleware in Express and why is it used?', N'Junior', N'Middleware functions are functions that have access to the request object, the response object, and the next middleware function in the application''s request-response cycle. They are used to execute code, make changes to request and response objects, end the cycle, or call the next middleware in the stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6583f36e-32aa-4396-bf48-5bc27c2c70df', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the ''thundering herd'' problem, and how can it be mitigated?', N'Middle', N'The thundering herd occurs when a large number of requests hit a backend system simultaneously, usually after a cache expiration. It can be mitigated by implementing request collapsing, using randomized cache expiration times, or pre-warming the cache.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06f36856-e26a-496e-b0a3-5bc2ebdb14ad', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are collection types in Scala?', N'Intern', N'Scala collections are data structures like lists, sets, and maps that are categorized into mutable and immutable variants. Most developers prefer the immutable versions by default to ensure thread safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbdb26fc-3531-4ce9-b99a-5bc753d47b96', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does the Zend Engine''s Opcache mechanism affect the execution lifecycle of a PHP script?', N'Senior', N'Opcache bypasses the expensive compilation step by caching precompiled bytecode in shared memory. By storing the parsed script in memory, the engine avoids redundant disk I/O and lexical analysis, allowing subsequent requests to execute directly from the cached bytecode.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c694716-834c-44d3-8a10-5bc7b0b00e84', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the ApplicationContext in Spring?', N'Intern', N'The ApplicationContext is at the core of Spring, serving as a container for managing and configuring the application''s beans (components) and their lifecycle. The ApplicationContext is crucial for Inversion of Control (IoC) and Dependency Injection (DI). How It Works - Configuration Management: This is a central repository for bean definitions, either specified in XML configuration, Java annotations, or XML configuration. - Bean Instantiation and Injection: The ApplicationContext is responsible for creating and wiring beans based on the provided configuration. - Lifecycles: The container manages bean lifecycles, initializing and destroying them when the application starts or shuts down. Bean Scopes - Singleton: The default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb532e5e-cc59-4433-baaa-5bcc212b7c75', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why would you use ''externals'' in a Webpack configuration?', N'Senior', N'Externals allow you to exclude specific dependencies from the bundle, such as libraries loaded via CDN. This reduces bundle size and allows leveraging browser caching for common libraries while preventing them from being bundled repeatedly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfaebd57-6ef4-4923-a81a-5bccfa2f4c9b', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the function of the ''explicit'' keyword in constructors?', N'Middle', N'The explicit keyword prevents the compiler from performing implicit type conversions using a constructor. This helps avoid unintended behaviors where a value might be automatically converted into an object type when it was not explicitly intended by the developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbe5cf6a-482b-4c8f-a4c7-5bcd63682e9b', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What are struct tags?', N'Junior', N'Struct tags are metadata attached to the fields of a struct. They are commonly used by libraries, such as JSON encoders or database mappers, to define how the fields should be processed during serialization or mapping.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44125f25-02f5-4ebe-a547-5bd102a5450d', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the Django signal mechanism and when should you avoid using it?', N'Middle', N'Signals allow certain senders to notify a set of receivers that some action has taken place elsewhere in the framework. You should avoid them when the logic can be handled explicitly in a model''s save method or a service layer, as signals can make the code flow harder to trace and debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5a46c61-b9ba-4020-8bba-5bd52e299656', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When storing data, what is the trade-off between normalization and denormalization?', N'Fresher', N'Normalization reduces data redundancy and prevents anomalies but often requires complex queries to join multiple tables. Denormalization simplifies read operations and improves speed by duplicating data, though it increases the risk of data inconsistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a165d3bc-3b18-42bc-9668-5bd5e93bf38a', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the difference between props and data in a Vue component?', N'Junior', N'Data represents the internal state of a component, which is defined and managed within the component itself. Props are properties passed down from a parent component to a child component, making them read-only for the child. This flow ensures one-way data binding, which helps maintain predictable state across the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab52cb70-9f94-4cdb-b68b-5bd641083921', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the role of environments in R and why they are critical for memory management and encapsulation.', N'Middle', N'Environments are hash-map-like structures that store symbol-value pairs, serving as the backbone for R''s scoping rules and package system. They allow developers to create encapsulated namespaces that prevent name collisions between different packages or script components. Because environments are reference objects, they allow for in-place modification, which can be used to bypass the standard copy-on-modify behavior for specific memory efficiency needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ee00a56-8875-4e8f-924a-5bd836c7a6b8', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the benefit of using the Portal component?', N'Junior', N'The Portal component allows you to render a portion of your UI into a different part of the DOM tree, usually outside the main application container. This is useful for elements like modals or tooltips that need to avoid CSS overflow restrictions or z-index issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'829d9a24-6afd-44c6-b1a9-5bdb39825fdb', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the purpose of database locking?', N'Fresher', N'Locking is a mechanism used to control concurrent access to data. It prevents multiple transactions from modifying the same data simultaneously, which helps maintain data integrity and isolation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf2ede18-935e-4e7e-a691-5bdb968f5803', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Explain the benefit of ''Edge Computing'' for latency-sensitive applications.', N'Senior', N'Edge computing processes data at the network periphery, closer to the source, which reduces bandwidth consumption and latency. This is particularly beneficial for applications requiring real-time responses, such as IoT devices or interactive media streaming.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'612ee48e-d655-44e9-94e9-5bdc7bbcc229', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between ''unknown'' and ''any''?', N'Fresher', N'The ''unknown'' type is a type-safe counterpart to ''any'' that requires developers to perform type checking or assertions before using the value. It prevents accidental operations on potentially unsafe data, whereas ''any'' allows almost any operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c34edc64-2307-40ca-ac41-5bdfb13c0c31', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the difference between a Choreography-based and Orchestration-based Saga?', N'Middle', N'In choreography, services exchange events without a central controller, which is decentralized but harder to track. In orchestration, a central ''orchestrator'' service tells each participant exactly what to do and when, providing better visibility and control at the cost of tighter coupling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eda71298-2069-44b2-9175-5bdfb6afb7a3', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is Flask in the context of backend development?', N'Intern', N'Flask is a lightweight web framework for Python classified as a micro-framework. It provides the essential tools and libraries required to build web applications without enforcing a specific project structure or database dependency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25ed158e-7d0b-40dd-8d10-5be1d5bba548', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix optimize the loading of multiple resources?', N'Middle', N'Remix uses resource route patterns and parallel data loading to fetch multiple pieces of data simultaneously. By splitting the UI into nested routes, it ensures that each part of the page fetches its specific data independently, preventing a single slow data source from blocking the entire page render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3331e3c9-53c4-4cd1-b018-5be3d1478bf9', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro handle framework-agnostic component integration?', N'Middle', N'Astro uses a compiler-based approach that allows you to use components from various frameworks like React, Vue, or Svelte in the same project. It handles the integration by rendering these components on the server and injecting the necessary runtime scripts only for the components marked for hydration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cea0121f-70e5-4f1c-9cc1-5be5f2b03eb4', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do Sass functions differ from mixins, and when should you choose one over the other?', N'Senior', N'Mixins are used to generate CSS blocks, including property-value pairs and nested selectors, while functions are designed to return a single value for use within properties. You should use a function when performing calculations or data transformation and a mixin when you need to inject multiple CSS declarations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'184b7422-f48b-4696-84fb-5be5f4ee26c5', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the advantage of horizontal scaling in Cassandra?', N'Intern', N'Horizontal scaling allows you to increase the capacity of your database by adding more nodes to the cluster. This makes it easy to handle growing data volumes and traffic without needing to upgrade existing hardware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bebbf5a-83d9-4487-aef1-5bec3f757d77', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Compare Remix''s server-side rendering (SSR) strategy to Next.js''s static site generation (SSG).', N'Senior', N'Remix prioritizes dynamic SSR to ensure fresh data at the time of request, whereas SSG relies on build-time snapshots. While SSG can be faster for static content, Remix’s approach is generally more robust for highly dynamic, user-authenticated applications where stale data is unacceptable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8d0f534-30e8-4468-a335-5bedc46f715c', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What happens when the state of a Preact component changes?', N'Fresher', N'When state changes, Preact schedules a re-render of the component. It generates a new Virtual DOM tree, compares it with the old one, and applies only the necessary updates to the actual browser DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70a9d144-e587-46e1-b002-5bedce47186c', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of routing in a Flask application?', N'Intern', N'Routing is the process of mapping a specific URL path to a corresponding function that executes logic and returns a response. It tells the application how to handle incoming web traffic based on the requested endpoint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8639660f-e840-47f8-828b-5bef7bbb7ae7', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is Node.js considered suitable for I/O-intensive applications?', N'Intern', N'Node.js is ideal for I/O-intensive tasks because its non-blocking architecture allows it to handle many concurrent connections without needing to create a separate thread for each one. This makes it highly efficient for real-time applications like chat services or data streaming.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a346c22a-96ee-4cc8-ae32-5beffa32f478', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the role of the @SpringBootApplication annotation.', N'Fresher', N'This annotation is a convenience annotation that combines @Configuration, @EnableAutoConfiguration, and @ComponentScan. It tells Spring Boot to start the application context, scan for components, and apply auto-configuration logic based on the classpath.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58e38137-fb1e-4330-8cfb-5bf6db1934b2', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle data replication?', N'Intern', N'Redis uses a primary-replica replication model. The primary node sends a stream of commands to replicas to keep them in sync, which helps in scaling read traffic and providing data redundancy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae9d01be-3cb4-4032-963f-5bfd308ed179', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Describe the difference between Global and Local Pipes.', N'Middle', N'Global pipes are applied to every route handler in the application, while local pipes are applied specifically to a method or parameter. Global pipes are ideal for cross-cutting concerns like validation, while local pipes allow for granular control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2cb2536-df45-4b3a-938c-5bfe35bac62e', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is it important to test an application under ''load'' or ''stress'' conditions?', N'Intern', N'Testing under load helps identify how a system behaves when it is pushed to its limits, such as during a traffic spike. It reveals bottlenecks or weaknesses that might not be apparent under normal usage. This allows engineers to fix these issues before they cause real-world outages for users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
