INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ac17a23-0359-49af-9353-5c04fc1261c3', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a service that is failing to authenticate requests intermittently?', N'Senior', N'I would investigate the clock drift across the distributed servers to ensure tokens aren''t being rejected prematurely due to time synchronization issues. I would also check the load balancer configuration to see if it''s misrouting requests or if the authentication service itself is experiencing intermittent connectivity or state consistency issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ce09aec-96a9-4307-b94a-5c054d303ff1', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the ''Golden Signal'' framework for monitoring?', N'Middle', N'The Golden Signals provide a standard for monitoring service health based on four metrics: Latency, Traffic, Errors, and Saturation. Focusing on these ensures you cover the most critical indicators of user experience and system capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
