INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5de49b48-c683-4ba0-978c-5c133fcf1512', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Why is it important to use a persistent message store in a production environment?', N'Middle', N'Persistence ensures that messages survive broker restarts or hardware failures by writing them to disk. Without persistence, messages stored only in memory would be lost if the broker crashes, leading to data inconsistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4867b67a-ec8f-499d-afa4-5c164c554711', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the role of ''Idempotency Keys'' in messaging systems?', N'Senior', N'Idempotency keys allow consumers to identify and ignore duplicate messages by checking if the unique identifier has already been processed in their local store. This is a standard architectural pattern to safely implement ''at-least-once'' delivery while achieving the functional outcome of ''exactly-once'' processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2b04f72-3170-434f-b845-5c182cdd1cc2', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the ''Visibility Map'' in PostgreSQL, and how does it optimize query performance?', N'Senior', N'The Visibility Map tracks which pages contain only tuples visible to all active transactions, allowing index-only scans to retrieve data without visiting the heap. By avoiding heap fetches, it significantly reduces I/O pressure for read-heavy workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
