INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd17b113a-bea6-46bc-99d4-5c20d6c24d99', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis ensure that multiple clients do not interfere with each other during a transaction?', N'Middle', N'Redis uses optimistic locking with the ''WATCH'' command to track changes to keys. If a watched key is modified by another client before the ''EXEC'' command is called, the transaction will fail, allowing the application to retry the operation and ensure data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf5151a1-6d11-4964-bb71-5c211fb184fb', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach choosing between a monolithic architecture and a microservices architecture for a growing application?', N'Middle', N'I start with a monolith for faster initial development and deployment. I consider moving to microservices only when the team size increases significantly, specific components require independent scaling, or the codebase becomes too coupled to deploy reliably and quickly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
