INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36e95369-242d-4dd9-8e1a-5c271143d91e', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'When should you choose a GIN index over a B-tree index?', N'Middle', N'A B-tree index is optimal for standard scalar values and equality or range queries. A GIN index is designed for data types that contain multiple elements, such as arrays, JSONB, or full-text search tokens, allowing efficient indexing of internal components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e5176df-8a52-49f2-9a61-5c28dfb5e217', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the trade-off between client-side and server-side processing?', N'Fresher', N'Client-side processing improves responsiveness for the user but depends on the user''s device capabilities and exposes logic to the client. Server-side processing is more secure and consistent across devices but increases latency because it requires network round-trips.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'061f2d3b-0ba6-45b9-bfca-5c29475a23c7', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is Classloader in Java?', N'Intern', N'The Java ClassLoader is a part of the Java Runtime Environment that dynamically loads Java classes into the Java Virtual Machine. Java code is compiled into class file by javac compiler and JVM executes Java program, by executing byte codes written in class file. ClassLoader is responsible for loading class files from file system, network or any other source. Types of ClassLoader: 1. Bootstrap Class Loader: It loads standard JDK class files from rt.jar and other core classes. It loads class files from jre/lib/rt.jar. For example, java.lang package class. 2. Extensions Class Loader: It loads classes from the JDK extensions directly usually JAVA_HOME/lib/ext directory or any other directory as java.ext.dirs. 3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0c0b059-1198-4456-af26-5c29b1a3aaa9', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the significance of the ''AOF rewrite'' process in Redis?', N'Senior', N'As the AOF file grows, it becomes inefficient to replay the entire log during recovery, so Redis triggers a background rewrite. This process generates a compact AOF file that represents the current state of the dataset by executing a snapshot-like reconstruction, discarding intermediate operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
