INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c5337f4-c5da-4a41-b593-5c29ec7855fc', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle memory fragmentation, and why is it a concern?', N'Senior', N'Redis uses its own memory allocator, which can lead to internal fragmentation as keys are added and deleted. If the allocator cannot reuse freed segments effectively, the physical memory usage grows significantly beyond the actual data size, potentially triggering OOM errors or system-level swapping.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
