INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62a377fa-1e3e-4c20-8d57-5c31908d8c95', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind affect the ''Tree Shaking'' process in a modern JavaScript build pipeline?', N'Senior', N'Since Tailwind produces a static CSS file based on project usage, it does not interfere with JavaScript tree shaking. Instead, it complements it by ensuring that only the used CSS is bundled, preventing the inclusion of unused styles that would otherwise remain in a standard CSS library or framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0c03836-ff24-4620-8d63-5c31ddfe6cb6', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'In what scenario would you use ''defer'' in a Remix loader?', N'Middle', N'You use defer to stream non-essential, slow-loading data to the client after the initial HTML has been sent. This improves the perceived performance by allowing the main content to render immediately while waiting for slower parts of the page to resolve.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'669ac0da-ed32-4bff-8e32-5c34807ca82a', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How do you manage environment-specific configurations in Express?', N'Middle', N'Environment variables are typically managed using libraries like ''dotenv'' to load settings from a file or the system environment. This approach allows developers to keep sensitive credentials outside the codebase and change configurations between development, staging, and production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e992404-114e-4bc9-af1f-5c38b3f29c7b', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a transaction in PostgreSQL, and why is it important?', N'Junior', N'A transaction is a sequence of operations performed as a single logical unit of work. It is important because it ensures data integrity through ACID properties, meaning that if any part of the transaction fails, the entire sequence is rolled back to prevent inconsistent states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'277ae3a6-216d-42fe-a4c8-5c39cef487ad', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the advantage of using ''readonly'' fields?', N'Middle', N'The ''readonly'' modifier ensures that a field can only be assigned a value during declaration or inside the constructor of the class. This enforces immutability for the field, which makes the code safer in multi-threaded environments and easier to reason about.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
