INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ccd2227-0be9-4638-b1d1-5c3aafd3140c', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the trade-off of using Chi''s automatic recovery middleware?', N'Middle', N'The recovery middleware prevents the entire server from crashing during a panic by catching it and returning a 500 error. The trade-off is that it hides the immediate stack trace from the client, but it requires careful logging implementation to ensure developers still have visibility into the cause of the crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd75e89ac-2f1f-4cac-8363-5c3acac094f5', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'When is a ''Graph Database'' more appropriate than a ''Relational Database''?', N'Middle', N'A graph database is superior when the data is highly interconnected and the primary use case involves navigating complex relationships, such as social networking connections or fraud detection. Relational databases struggle with deep recursive joins, whereas graph databases store relationships as first-class entities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46d02aa8-c54d-423a-821c-5c3d3e85ce42', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using a REST API and GraphQL for a new project?', N'Middle', N'REST is a standard, easy to cache, and simple to implement for straightforward resources. I choose GraphQL when the client needs to fetch data across complex, nested relationships or when reducing over-fetching and under-fetching is critical for performance. The choice depends on the specific flexibility requirements of the frontend clients.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b51d812-3a4f-424e-923f-5c40b163839e', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Does Gin support different HTTP methods?', N'Fresher', N'Yes, Gin provides explicit methods to handle all common HTTP verbs, including GET, POST, PUT, PATCH, DELETE, and OPTIONS. This makes it straightforward to design RESTful web services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
