INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e702101-9fd2-44cd-9ca7-5c4453f1fefa', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Data JPA optimize database interactions through the Persistence Context?', N'Senior', N'The Persistence Context acts as a first-level cache, tracking changes to managed entities and batching SQL updates during transaction commit. This reduces unnecessary round-trips to the database and allows for dirty checking, which automatically synchronizes the state of entities with the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2906a1b2-b4f7-462f-b598-5c48021f3595', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the role of the appsettings.json file?', N'Fresher', N'The appsettings.json file is a configuration file used to store application settings, such as database connection strings, logging levels, and custom configuration variables. It allows developers to change environment-specific settings without modifying the underlying application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63efc3cf-0423-4e6a-90b8-5c48c641573f', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How do you optimize Alpine.js for mobile performance?', N'Middle', N'Optimizing for mobile involves minimizing the number of observers and keeping the component logic lightweight to reduce main-thread blocking. Because mobile devices have more constrained resources, offloading heavy computations to web workers or using smaller, focused components is recommended.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3dea302b-d6b4-4d9e-960d-5c48e6eb41bf', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the concept of ''Inline Caching'' and how it optimizes dynamic property access.', N'Senior', N'Inline caching is a technique where the engine records the type of an object and the offset of the property accessed at a specific call site. On subsequent executions, the engine assumes the object shape remains unchanged and uses the cached offset, skipping the costly lookup process until a shape mismatch occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
