INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'963c9abe-475e-4a0f-a7cd-5c4bb5ba032f', N'4c000000-0000-0000-0000-000000000005', N'How does a Message Queue improve system decoupling?', N'Middle', N'Message queues allow services to communicate asynchronously by decoupling the sender from the receiver. This prevents a spike in traffic from overwhelming downstream services, as requests are buffered and processed at a manageable rate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
