INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3d701d8-928b-45a1-945b-5c4e824b3487', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you evaluate whether to build a custom solution versus integrating a third-party service for a core system component?', N'Middle', N'I compare the long-term maintenance costs, development velocity, and the degree of customization required. Building is preferred if the feature is a core competitive advantage that requires unique logic, while buying is better for commoditized services where external vendors provide superior reliability and faster time-to-market.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9baceb71-480f-42b1-b3d3-5c4feec5f563', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is it dangerous to reference request data outside of a Fiber handler''s scope?', N'Senior', N'Fiber, through Fasthttp, reuses request and response objects to reduce GC pressure. If data is accessed asynchronously or after the handler returns, the underlying memory buffer may have been overwritten by a new request, leading to data races and corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a92685a-3295-4e42-9e08-5c506931882e', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the difference between call-by-value and call-by-name parameters in Scala, and when should you prefer one over the other?', N'Middle', N'Call-by-value evaluates the argument once before the function body executes, while call-by-name evaluates the argument every time it is referenced within the function. Call-by-value is generally more efficient for expensive computations, whereas call-by-name is useful for implementing custom control structures or lazy logging where the argument should only be evaluated if a specific condition is met.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dac872e9-6f15-4a6d-b4ff-5c544e371d47', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Why might you choose to use Astro''s ''Server Islands'' feature?', N'Middle', N'Server Islands allow you to defer the rendering of specific components to the server even when the rest of the page is static or cached. This is useful for personalized content, such as a user profile or a shopping cart, that cannot be statically generated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'585b4a89-4368-4613-9299-5c5652c6c256', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the differences between spread operator and rest parameter', N'Intern', N'Rest parameter collects all remaining elements into an array. Whereas Spread operator allows iterables( arrays / objects / strings ) to be expanded into single arguments/elements. i.e, Rest parameter is opposite to the spread operator.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3226edd-ed3f-4fe0-a76c-5c57aaf9bdb8', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the risk of ''Deadlock'' in a system using strict two-phase locking?', N'Senior', N'Strict two-phase locking requires transactions to hold all exclusive locks until the transaction completes, which can lead to circular wait conditions where multiple transactions are blocked indefinitely. Systems must implement deadlock detection mechanisms or use timeouts to abort and restart one of the involved transactions to break the cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ace240f6-8433-42de-b838-5c5838ae0bcc', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you weigh the cost of technical debt against the need for rapid feature delivery?', N'Middle', N'The decision should be based on the project lifecycle stage and the criticality of the code. If rapid delivery is essential for market validation, taking on technical debt is a valid strategic choice, provided there is a documented plan to refactor or pay down that debt once the business goal is achieved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e87ecb24-f1d7-49f6-bdf6-5c5c1897dd7a', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery''s selector engine interact with modern Shadow DOM encapsulation?', N'Senior', N'jQuery''s Sizzle engine is not designed to traverse the Shadow DOM boundary, often failing to find elements encapsulated within shadow roots. This incompatibility makes it ineffective for modern component libraries that rely on Web Components or Shadow DOM for style and structure isolation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae56966b-6fe5-4ac6-95b5-5c5dc42dccb3', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is Dependency Injection in the context of NestJS?', N'Intern', N'Dependency Injection is a design pattern where a class requests its dependencies from an external source rather than creating them itself. NestJS uses an internal container to automatically instantiate and provide these dependencies to classes, making code easier to test and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd8589d4-0dd1-4e0d-beae-5c5e77096331', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What does ''concurrency'' mean in the context of Go?', N'Intern', N'Concurrency in Go refers to the ability of a program to handle multiple tasks at the same time by coordinating independent processes. It focuses on the structure of the program to allow efficient execution, often supported by Goroutines and channels.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
