INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'752bd2ee-9e0b-40a7-8c02-5c68c0377d23', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is Hot Swapping in the context of Phoenix/Erlang?', N'Intern', N'Hot swapping is the ability to update or replace code in a running application without stopping or restarting the server. This is a core feature of the Erlang VM, allowing for zero-downtime deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7289be8-1ad5-4ece-bd42-5c6939703d0c', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are the advantages and limitations of Django''s built-in caching framework in a distributed environment?', N'Senior', N'Django''s caching framework supports various backends, but the local memory cache is not thread-safe or process-safe across multiple server instances. For distributed scalability, a shared cache like Redis or Memcached is required to ensure consistent state across all application nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'298039f3-a33d-442f-b514-5c69b3476df6', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you decide between two different approaches for solving a technical problem when both seem viable?', N'Fresher', N'I would evaluate both approaches based on their complexity, the time required to implement them, and how easily they can be maintained. I would also consider which approach is more readable and aligns better with the project requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84b55791-ceff-414e-afbf-5c6b1a01c590', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the primary architectural trade-off of using Alpine.js instead of a framework like React for complex application state?', N'Senior', N'Alpine.js lacks a centralized state management architecture and a virtual DOM, which makes it excellent for simple interactivity but challenging for maintaining large-scale, complex state. As application complexity grows, the lack of structured data flow and component lifecycle hooks in Alpine can lead to difficult-to-debug spaghetti code compared to the predictable unidirectional data flow of React.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9d98f49-291e-4382-993c-5c6c5bc2bf7b', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What does it mean to identify the ''root cause'' of an issue?', N'Intern', N'Identifying the root cause means digging past the superficial symptoms of a problem to find the underlying factor that created the issue in the first place. By addressing the root cause, you prevent the problem from recurring in the future.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a967892-763c-42fc-adb7-5c705033b9b7', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What does the ''Context'' object mean for concurrency in Echo?', N'Intern', N'In Go, each request in Echo is handled in its own goroutine. The Context object is designed to be safe for this concurrent model, allowing multiple requests to be processed simultaneously without interfering with each other.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2d0aec6-13b9-47cb-a3ee-5c709a0b4951', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the ''Config'' object in Rocket?', N'Fresher', N'The Config object holds settings for the Rocket server, such as the address and port it should listen on. It can be loaded from configuration files or defined programmatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd107144a-31bd-4409-8512-5c73e2e1a6ba', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the primary benefit of using Tailwind CSS for maintenance?', N'Intern', N'The primary benefit is that you do not have to worry about naming CSS classes or managing large stylesheets that grow over time. Because styles are applied directly to the elements, you can change them without the risk of breaking other parts of your application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4b5588a-fb7c-4a69-8f38-5c77809263d3', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are ''slots'' in Svelte and how do they impact component composition?', N'Middle', N'Slots are placeholders that allow parent components to inject content into child components. They enable flexible component composition by allowing you to define a layout structure in the child while leaving specific areas open for dynamic content from the parent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adff59c1-b2ec-4453-83ce-5c78f1b1bf77', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the main benefit of shipping zero JavaScript by default in Astro?', N'Intern', N'Shipping zero JavaScript by default significantly improves the Time to Interactive and First Contentful Paint metrics. Since browsers do not need to parse or execute heavy scripts for static content, the page loads much faster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'feb73c68-4cdf-410e-bff3-5c7aa71fb0d1', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Why should you prefer using variables in Sass over CSS custom properties?', N'Middle', N'Sass variables are processed at compile-time, meaning they are replaced with static values in the final CSS output. CSS custom properties exist at runtime, allowing for dynamic updates via JavaScript or media queries, which is better for theming but lacks the computational flexibility of Sass variables during build.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5506f03b-8e03-48a6-a89e-5c7b89ca17df', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you balance the need for accuracy with the need for speed in estimation?', N'Fresher', N'I use ''time-boxing'' to ensure I don''t spend too long on the estimate itself, focusing on identifying the major components rather than getting lost in minor details. For most tasks, a reasonably accurate estimate made quickly is more valuable than a ''perfect'' estimate that takes too long to produce.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'324b4307-395c-48fa-9a4c-5c7daf5d071a', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does the ''SSTable'' structure in LSM-trees optimize write-heavy workloads?', N'Senior', N'LSM-trees convert random writes into sequential I/O by buffering them in memory before flushing them as immutable Sorted String Tables (SSTables) to disk. This architecture avoids the expensive random disk seeks associated with B-Trees, making it highly efficient for write-intensive applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0a9988f-d78c-4174-a390-5c7db2d9dc05', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why is it generally considered bad practice to use C-style casts in C++?', N'Middle', N'C-style casts are overly permissive and can perform dangerous conversions, such as stripping away const-correctness or performing reinterpret casts without clear intent. C++ named casts like static_cast or dynamic_cast provide compile-time safety and make the programmer''s intent explicit for code reviewers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73cb5367-a94c-4c7c-bace-5c7f0554fd25', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are computed properties in Ember?', N'Intern', N'Computed properties are functions that appear as simple properties but are calculated based on other properties. They automatically recompute when their dependent properties change, making it easy to derive new values from existing data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49687260-3748-4feb-aee7-5c826486fa75', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js ensure consistency when multiple directives modify the same DOM element simultaneously?', N'Senior', N'Alpine processes directives in a specific, deterministic order based on their priority levels to prevent race conditions. Directives are evaluated and applied during the next tick, ensuring that even if multiple directives act upon a single element, the final DOM state is predictable. This priority-based evaluation prevents non-deterministic behavior during complex UI updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0f683e1-dc5a-4686-8e58-5c847f618151', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do you handle attribute-to-property binding in Lit?', N'Intern', N'Lit automatically handles attribute-to-property binding by observing HTML attributes and reflecting them to component properties. When an attribute on the custom element changes, Lit updates the corresponding property in the class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4513640c-ce69-4e63-9ad2-5c84d2bbe59a', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How would you handle a situation where you discover a bug in a feature you recently completed just before the deadline?', N'Fresher', N'I would immediately inform my supervisor about the issue and provide an honest assessment of the time needed to fix it. Instead of rushing, I would isolate the cause of the bug to ensure the fix is stable and does not introduce new issues. My priority would be to balance the need for a correct, functional solution with the project timeline, even if it requires discussing a potential delay.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c1a4df3-9dba-4561-acdc-5c85332e0bb1', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you assess the trade-off between microservices and a monolith for a new product?', N'Middle', N'I look at the team size and the domain complexity; a monolith is usually better for early-stage products to allow for rapid iteration and simplified deployments. I would only shift toward microservices once the team grows, the domain becomes clearly bounded, and we face specific scaling bottlenecks that justify the increased operational complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56fd5620-f8c9-4cab-bd55-5c85ed814527', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle validation?', N'Fresher', N'Micronaut uses the Java Bean Validation specification to enforce constraints on object fields. By using annotations like @NotNull or @Size, the framework automatically validates input data before passing it to the controller method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21a9e8b8-6b65-4291-8ee9-5c87fd3f9afc', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the difference between static and dynamic routing in Astro?', N'Intern', N'Static routing involves creating pages for known paths at build time, while dynamic routing allows for generating pages from data sources, such as a CMS or a list of files, by using path parameters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf637f24-4dcc-478b-af81-5c8a0199e599', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the functional interfaces Consumer<T>, DoubleConsumer, IntConsumerand LongConsumer?', N'Intern', N'Consumer (consumer) - the interface through which a function is implemented that receives an instance of the class as an input T, performs some action with it, and returns nothing. * DoubleConsumer- the consumer receiving the input Double; * IntConsumer- the consumer receiving the input Integer; * LongConsumer- the consumer receiving the input Long.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa671056-194d-4f3d-b8ba-5c8a8514cda8', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why might a team choose an eventual consistency model over strong consistency in a global system?', N'Middle', N'Strong consistency requires synchronous coordination across all nodes, which significantly increases latency, especially over long geographic distances. Eventual consistency allows for local read and write operations, drastically improving performance and availability at the cost of requiring application logic to handle potential data conflicts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'689ca2d9-6162-4b2e-8222-5c8b0064a3b0', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of the Symfony EventDispatcher component?', N'Intern', N'The EventDispatcher component allows different parts of an application to communicate by triggering and listening to events. When a specific action occurs, such as a user logging in, an event is dispatched, and any registered listeners can execute their own logic in response. This allows for highly decoupled code where features can be added without modifying existing core logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f22566d-f529-4a95-b8fb-5c8c4cedb935', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Why might a Large Page configuration improve performance for memory-intensive applications?', N'Senior', N'Large pages reduce the number of entries in the Translation Lookaside Buffer (TLB), leading to fewer TLB misses when accessing large data structures. This reduces the overhead of address translation during memory operations, which is particularly beneficial for applications with a massive memory footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'445a3030-1cba-43f3-a7e6-5c8d47de719a', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does the ''Three-Phase Commit'' (3PC) improve upon 2PC?', N'Senior', N'3PC introduces a ''pre-commit'' phase that separates the decision to commit from the actual commit, making the protocol non-blocking in the event of coordinator or participant failure. While it improves availability, it is rarely used in practice due to increased latency and complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c360ff7-778c-4b8c-b040-5c8d6217a476', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What does it mean that Ruby is a purely object-oriented language?', N'Intern', N'In Ruby, everything is treated as an object, including primitive data types like numbers, booleans, and nil. This means every value has methods and properties that can be accessed and manipulated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1bd416a-dd39-4ce4-bc98-5c8e28da70d2', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember''s Glimmer VM improve rendering performance?', N'Middle', N'The Glimmer VM converts templates into a low-level bytecode that is executed by a high-performance virtual machine. This approach minimizes DOM updates by calculating the smallest possible change set, significantly reducing browser reflows and repaints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b7edf2f-fb0e-4d7d-b13b-5c8e536e4375', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of the ''any'' type in TypeScript?', N'Intern', N'The ''any'' type tells the TypeScript compiler to disable type checking for a specific variable. It effectively opts out of the type system, which should be used sparingly because it eliminates the safety benefits of TypeScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd622fde-ab56-495f-8643-5c9073ba455e', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL implement ''Serializable'' isolation, and what is the performance cost?', N'Senior', N'PostgreSQL uses SSI (Serializable Snapshot Isolation) to monitor for read-write dependencies that could lead to serialization anomalies. While it allows for high concurrency, it requires applications to handle serialization failure errors by retrying transactions, which can increase latency under high contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85ac7e18-e523-43a2-b577-5c9131902186', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it important to implement logging in your application from the start of the design phase?', N'Fresher', N'Logging is critical for diagnosing issues, tracking user behavior, and monitoring system health after deployment. If logs are not implemented, it becomes nearly impossible to reconstruct the sequence of events that led to a bug or failure. Proper logging provides the visibility needed for effective debugging and proactive system maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'120a31b3-fc40-446f-a759-5c92c8cef81d', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of a Phoenix layout?', N'Junior', N'A layout is a template that provides a common wrapper for multiple views, such as headers, footers, and navigation menus. It allows developers to define a consistent look and feel for the entire application in one place.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c953bfe9-6a7c-424b-866c-5c9332c48254', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the primary advantage of Astro''s multi-page architecture?', N'Intern', N'It allows each page to be independent, meaning a crash or error in one component doesn''t break the entire application. It also allows for better browser caching of individual pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'758953f5-3340-4f79-90db-5c9441a2b19c', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does a ''Sidecar'' caching pattern improve system modularity?', N'Senior', N'The sidecar pattern offloads caching logic to a separate container or process that runs alongside the application. This allows developers to update caching policies and configurations without modifying the primary application code, promoting better separation of concerns and simpler deployment pipelines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac48eaec-4b21-403f-bca8-5c9782bbb0a7', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is pipelining in Redis and when would you use it?', N'Intern', N'Pipelining in Redis enables multiple commands to be sent in a single network request, boosting performance. By reducing round-trips between clients and the server, pipelining offers improved efficiency, particularly in situations where latency or the number of requests are a concern. Key Components - Queue: Commands awaiting a response - TCP Connection: Data transfer medium - Client: Initiator of pipelined commands - Server: Pipelining-compatible Redis instance. Advantages - Performance: Reduced overhead from round-trips speeds up overall execution. - Network Efficiency: Less frequent network interactions. - Atomicity: Pipelined sequences are atomic; either all commands succeed or none does. - Synchronization: Pipelining maintains command order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfa899ff-fe7a-452d-971e-5c99b28af221', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a ''void'' return type in a function?', N'Junior', N'The ''void'' type signifies that a function does not return any value. It is the default inference for functions that finish execution without reaching a return statement, ensuring that callers do not attempt to use an undefined result.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd21deb64-f640-4531-a779-5c99cfdc58f2', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the impact of a database indexing strategy on write performance versus read latency?', N'Senior', N'I analyze the write amplification factor caused by index updates and compare it against the query speed improvement for the most frequent read operations. I then run a benchmark on a production-like dataset to measure the actual latency shift, allowing me to strike a balance that aligns with the system''s primary access patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'604662e1-c787-4189-a70c-5c9a61374e0f', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the ''yield return'' keyword, and how does it affect memory usage?', N'Middle', N'The ''yield return'' keyword enables deferred execution by creating an iterator that maintains the state of a method across multiple calls. It reduces memory usage by processing elements one at a time instead of loading an entire collection into memory at once, which is particularly beneficial for large datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e0372e1-ea39-4eb8-89c9-5c9b61bef0aa', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is inheritance?', N'Intern', N'Inheritance is a mechanism where a new class acquires the properties and behaviors of an existing class. It promotes code reusability by allowing a subclass to build upon the functionality defined in a superclass.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea9a4ade-4860-4655-9932-5c9ef3adc38b', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What does the ''NoRoute'' handler do in Gin?', N'Junior', N'The ''NoRoute'' handler is a custom function that Gin executes when a client requests a URL that does not match any defined routes. This is commonly used to return a user-friendly 404 Not Found response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d249dec-d638-49ee-90fb-5ca05eff9566', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the benefit of using the Quarkus ''Extension'' model?', N'Middle', N'Extensions are the primary way to integrate third-party libraries into Quarkus. They provide the necessary configuration and build-time logic to ensure libraries work efficiently with the Quarkus container and GraalVM native image generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2c2ddf4-8b87-4102-b396-5ca18988df40', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the Temporal Dead Zone (TDZ)?', N'Intern', N'In ES6, let bindings are not subject to "variable hoisting", which means that let declarations do not move to the top of the current execution context. Referencing the variable in the block before the initialization results in a ReferenceError (contrary to a variable declared with var, which will just have the undefined value). The variable is in a "temporal dead zone" from the start of the block until the initialization is processed. Real-World Use Case: TDZ prevents a subtle bug in module initialisation cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f44bbd9-5643-4daa-8fca-5ca452010f63', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Discuss the trade-offs of using Pydantic''s ''BaseModel'' for request validation versus manual JSON parsing.', N'Senior', N'Pydantic provides declarative, type-safe validation that acts as documentation and runtime enforcement. While manual parsing might offer a marginal speed increase, Pydantic''s structured approach significantly reduces development time, eliminates boilerplate, and prevents common injection vulnerabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'451d9418-fc86-442a-9533-5ca6b9b23169', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is a partial class?', N'Junior', N'A partial class allows the definition of a single class to be split across multiple files. This is commonly used by code generators to separate auto-generated code from developer-written logic, keeping the source files clean.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58dee90b-9f07-45bd-bbba-5caa31fea910', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does the Image component in Next.js improve performance?', N'Junior', N'The Image component automatically optimizes images by resizing, compressing, and serving them in modern formats like WebP based on the user''s device. It also prevents layout shifts by requiring width and height dimensions and enables lazy loading by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'028db3d4-0081-4c8b-93e4-5cb2ff38fa67', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Analyze the memory overhead of capturing variables in Kotlin lambdas.', N'Senior', N'When a lambda captures variables from its surrounding scope, the compiler generates a class that stores those variables as fields, which results in additional heap allocation. If the captured variable is mutable, the compiler wraps it in a ''Ref'' object to allow the lambda to modify the original variable, further increasing memory pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd081be02-b09e-49a6-bd35-5cb5ca8abeb9', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Analyze the security risks associated with jQuery''s DOM manipulation methods like html() or append().', N'Senior', N'Methods like html() can easily introduce Cross-Site Scripting (XSS) vulnerabilities if they process unsanitized user input. While modern browsers offer some protection, reliance on jQuery''s internal string parsing for HTML injection often bypasses stricter sanitization practices required for high-security applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd89e465-756e-4890-9a22-5cb6b227087e', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the trade-offs between using C++ exceptions versus error codes in the context of system-level resource management and predictable latency.', N'Senior', N'Exceptions provide a structured way to separate error handling from business logic but introduce non-deterministic latency and require strict adherence to RAII to prevent resource leaks during stack unwinding. Conversely, error codes offer predictable performance and explicit control flow, which is crucial for real-time systems, but they often lead to verbose code and can be easily ignored by developers. The choice depends on whether the system prioritizes developer productivity and maintainability or strict latency guarantees and binary size optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98c3299e-5168-44c3-bd55-5cb6bad83176', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the primary factor in determining when to introduce an asynchronous processing layer into an existing synchronous workflow?', N'Senior', N'Introduce it when response latency exceeds user expectations or when processing requirements fluctuate unpredictably. Asynchronous patterns allow for better resource utilization and fault tolerance by decoupling producer and consumer speeds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f86f948-0a32-41ce-87be-5cb90de5b93a', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How can you implement custom logging in Chi?', N'Middle', N'You can implement a custom logger by creating a middleware that wraps the ''next'' handler. Within this middleware, you can capture the request method, URL, and duration, then log the information before or after calling the next handler in the chain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fe1ffdf-380b-43ca-a21a-5cba2d554295', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the role of ''strict'' mode in TypeScript?', N'Fresher', N'Strict mode is a compiler flag that enables a wide range of type-checking behaviors, including strict null checks and strict property initialization. Enabling it ensures a higher level of type safety and helps developers write more robust and error-resistant code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68c943f2-0963-4e64-845d-5cbbff729bee', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Why might you choose CSS Variables over Sass variables in a dynamic application?', N'Middle', N'CSS Variables are scoped to the DOM and can be changed at runtime via JavaScript, allowing for real-time theme switching without a page reload. Sass variables, conversely, are processed at compile-time and are static once the CSS is generated, making them unsuitable for runtime state updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
