INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2db9364-53ba-4035-be05-5cbd177b4ed4', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the primary purpose of the Model-View-Template (MVT) architecture in Django?', N'Intern', N'The MVT architecture separates the application into three distinct parts: the Model handles data and database logic, the Template manages the user interface, and the View acts as the bridge that processes user requests and returns responses. This separation ensures that logic, presentation, and data management remain independent for better maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
