INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5face4ad-6644-4a92-983e-5cbfb57f0c3a', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why should you avoid mutating state directly in Redux?', N'Junior', N'Redux relies on shallow comparison to detect changes. If you mutate the state directly, the reference to the object remains the same, and the application may fail to re-render because it does not realize the data has changed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd857014c-7ccd-4dde-9f04-5cc20bbed156', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between substring and substr methods?', N'Fresher', N'Both substring and substr are used to extract parts of a string, but there are subtle differences between the substring() and substr() methods in terms of syntax and behavior. 1. substring(start, end) - Parameters: - start: The index to start extracting (inclusive). - end: The index to stop extracting (exclusive). - Behavior: - If start > end, it swaps the arguments. - Negative values are treated as 0. 2. substr(start, length) _(Deprecated)_ - Parameters: - start: The index to start extracting. - length: The number of characters to extract. - Behavior: - If start is negative, it counts from the end of the string. - If length is omitted, it extracts to the end of the string. Note: substr() is considered a legacy feature in ECMAScript, so it is best to avoid using it if possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
