INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c2d7a78-7da5-46c1-91d1-5ccce9cafeaa', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the difference between ChangeDetectionStrategy.Default and ChangeDetectionStrategy.OnPush, and how does this affect application performance?', N'Middle', N'The Default strategy performs change detection on every component whenever any asynchronous event occurs in the application, which can lead to performance bottlenecks in large trees. The OnPush strategy limits change detection to only occur when the component''s input references change, an event is emitted from within the component, or an observable linked via the async pipe emits a new value. Using OnPush significantly reduces the number of checks performed by the framework, leading to a more efficient and scalable application architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
