INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a411f5a-b897-41a5-9d89-5cd456d6fd66', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How can you detect and mitigate ''event loop lag'' in a production application?', N'Senior', N'Event loop lag is detected by measuring the time difference between scheduled timers and their actual execution. If the lag exceeds a certain threshold, the application is overloaded or a task is blocking the loop. Mitigation involves offloading heavy processing to worker threads, breaking down large synchronous loops, or adding more horizontal instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
