INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5180509-c7fa-416c-a553-5cd8d59fc1b8', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How do loaders and plugins differ in Webpack, and why is this distinction important for the build process?', N'Middle', N'Loaders are responsible for transforming specific file types, like converting TypeScript to JavaScript or processing CSS, so that Webpack can understand them. Plugins, on the other hand, operate at a higher level and can perform a wider range of tasks, such as bundle optimization, asset management, and environment variable injection. Understanding this distinction is crucial because loaders focus on individual file transformations during the module resolution phase, while plugins tap into the entire compilation lifecycle to modify the final output.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'890f9eb2-91bf-41b4-abba-5cd945b40b22', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does the ''Sidecar'' pattern assist in managing scalable microservices?', N'Middle', N'The sidecar pattern involves attaching a helper container to a service to handle non-functional tasks like logging, monitoring, or service mesh traffic routing. This allows the primary service to focus on business logic while offloading cross-cutting concerns to a standardized, reusable component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17450254-38f3-4cf7-8387-5cdc177e2bb5', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between an lvalue and an rvalue?', N'Fresher', N'An lvalue refers to an object that occupies an identifiable location in memory, meaning it has an address. An rvalue is a temporary value that does not have a persistent memory address, typically appearing on the right side of an assignment operator.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
