INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61139243-60a4-4e31-9ff3-5cdd9b9b6585', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle error boundaries, and why is this approach beneficial for complex applications?', N'Middle', N'Remix uses Error Boundaries at the route level, allowing developers to catch rendering or data-loading errors within specific parts of the component tree. This prevents a single failed component or data fetch from crashing the entire application. By isolating errors, the UI can remain functional in other regions, providing a more resilient user experience compared to a global application-level error catch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21e7ce9b-a66a-4d76-873c-5cde55489bd3', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the role of the ''IntoResponse'' trait?', N'Intern', N'The IntoResponse trait defines how a Rust type should be converted into an HTTP response. Axum uses this trait to allow developers to return various types—such as strings, status codes, or JSON objects—from handler functions, simplifying the response process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b485bc9-f1cc-43be-a7f2-5cde7b967a04', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the difference between a query string and a route parameter?', N'Intern', N'Route parameters are part of the URL path itself, usually represented by a colon, while query strings appear after a question mark at the end of the URL. Route parameters are typically used for identifying specific resources, whereas query strings are often used for filtering or sorting results.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6cb1049-b7d0-4e20-a9af-5cdf44ca3c80', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is it often recommended to avoid creating many custom CSS classes when using Tailwind?', N'Middle', N'Creating too many custom classes defeats the purpose of the utility-first approach and introduces the same maintenance overhead as traditional CSS. It is better to use the built-in utilities directly, as they are tested, documented, and part of a unified system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a190d835-0029-42db-98e5-5cdfed5ff30d', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the security risk of using deprecated libraries or frameworks?', N'Middle', N'Deprecated or outdated software often contains known, unpatched vulnerabilities that are easy to exploit. Regularly auditing and updating dependencies is critical to maintaining a secure system posture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87b4b6ea-73f8-416a-8c8a-5ce11bba7ffe', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the purpose of Atomicity in ACID?', N'Junior', N'Atomicity ensures that a transaction is treated as an ''all-or-nothing'' unit. If any part of the transaction fails, the entire transaction is aborted and the database is rolled back to its state before the transaction began.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da6efa0b-ee96-45ad-b7d0-5ce12911a5c8', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the common aggregate functions in MySQL?', N'Junior', N'Common aggregate functions include COUNT, which counts the number of rows; SUM, which totals a numeric column; AVG, which calculates the average; and MIN or MAX, which find the smallest or largest values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e98cbb7-ba31-4280-aa09-5ce2c91557ce', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the difference between Flow and PropTypes?', N'Fresher', N'Flow is a _static analysis tool_ (static checker) which uses a superset of the language, allowing you to add type annotations to all of your code and catch an entire class of bugs at compile time. PropTypes is a _basic type checker_ (runtime checker) which has been patched onto React. It can''t check anything other than the types of the props being passed to a given component. If you want more flexible typechecking for your entire project Flow/TypeScript are appropriate choices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ec00108-1e8c-4fb7-ad93-5ce940aaaf8e', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is your strategy for conducting a blameless post-mortem after a major production incident?', N'Senior', N'The goal is to focus on systemic failures rather than human error, analyzing what led to the mistake to improve processes or tooling. I encourage open discussion to identify root causes and assign actionable follow-up tasks that prevent recurrence without fostering a culture of fear.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7361d817-d921-42ea-9b74-5cea8954219a', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Can Nuxt be used as a purely static site generator?', N'Junior', N'Yes, by running the ''nuxt generate'' command, Nuxt creates a static version of your entire application. This is ideal for sites that do not require server-side logic for every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4225d1ea-d80f-4e0d-9b3a-5ceaac2ca455', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the benefit of using the @query decorator?', N'Junior', N'The @query decorator allows you to easily select and reference DOM elements inside your component''s shadow root. It simplifies the process of interacting with specific child elements without needing to write manual querySelector calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b577183-6d6e-4827-b0ee-5ceb7e2c1754', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide between a microservices architecture and a monolithic architecture for a new product?', N'Middle', N'I evaluate the team size, the projected complexity of the domain, and the deployment frequency requirements. For early-stage products where rapid iteration is key, a monolith is often better due to its simplicity. As the product grows and team boundaries become clearly defined, transitioning to microservices can help scale development teams and isolate failure domains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63ac6f09-d73f-48a1-8338-5cec6a2bc738', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using an array and a linked list for a specific feature?', N'Fresher', N'Choose an array when you need fast, index-based access to elements and the size is relatively predictable. Use a linked list when you frequently need to insert or delete elements in the middle of the collection, as it avoids shifting overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'075133da-7476-4d41-8c4a-5cefb1e75dbb', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'When should you use Gin''s ''ShouldBind'' versus ''Bind'' methods?', N'Middle', N'ShouldBind returns an error if the request body or parameters fail validation, allowing the developer to handle the error manually and return a custom response. Bind automatically triggers a 400 Bad Request error if validation fails, which is less flexible but faster for simple implementations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
