INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8db79e69-df3d-41e7-8014-5cf818009b9a', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are the trade-offs of using void pointers in C?', N'Middle', N'Void pointers allow for generic programming, enabling functions to handle data of any type, which is useful for creating flexible libraries like memory allocators. However, they bypass C''s type-checking mechanism, which increases the risk of programming errors and makes the code harder to maintain and debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9402fc98-8c3d-41ac-8da4-5cf84731e1b3', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'When is it appropriate to use a ''database view'' instead of Ecto queries?', N'Middle', N'Database views are useful when you need to perform complex analytical queries or joins that are expensive to compute on every request. By defining the view in the database, you can treat it as a standard table in Ecto, simplifying the application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'629999b2-ad77-4c22-9661-5d0174114d39', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the interaction between ''internal'' visibility and module-level encapsulation.', N'Senior', N'The ''internal'' modifier restricts access to members within the same module, which is defined by a set of files compiled together. This provides a mechanism for encapsulation that is stronger than Java''s package-private visibility, allowing libraries to expose a clean public API while hiding complex implementation details from consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
