INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78368e7a-515b-4ff5-93d9-5d07f8751f72', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Explain the difference between a Hono app and a Hono base instance.', N'Middle', N'A Hono app is the primary instance handling routing and middleware, while a base instance is often used when creating modular sub-apps or mounting multiple applications under different paths. This enables a micro-service-like architecture within a single project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57dc0a4c-0bef-41a2-948e-5d0a470a8a63', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What are the benefits of Qwik''s ''No-Hydration'' approach for battery-constrained devices?', N'Senior', N'By eliminating the need to parse and execute large bundles of JavaScript to hydrate the application, Qwik significantly reduces CPU usage. This leads to lower power consumption and improved device performance, which is particularly beneficial on mobile devices with limited hardware resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c93892a-abf4-48ce-8efc-5d0aa3bc85d0', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of the Django cache framework?', N'Middle', N'The cache framework allows you to store expensive-to-compute data in a temporary, fast-access location to speed up site performance. It can be used at various levels of granularity, such as caching entire views, specific template fragments, or individual database query results.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
