INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'417ec823-afd1-483e-9ef0-5d10a6289b36', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do you handle state in Svelte components?', N'Fresher', N'State is handled by declaring variables at the top level of the script section within a component. These variables are reactive by default, meaning any change made to them will automatically trigger an update to the DOM elements that reference them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f5bdf5f-1502-460e-a4e1-5d14d35f8612', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is a ''Service Mesh''? How does it aid in managing microservices?', N'Senior', N'A Service Mesh is a dedicated infrastructure layer that simplifies network requirements for microservices, making communication more reliable, secure, and efficient. It is designed to reduce the operational burden of communication between microservices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9dd3586-e219-41c9-97f5-5d163799462b', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the role of the ''Router'' in Axum?', N'Fresher', N'The Router in Axum is responsible for matching incoming HTTP requests to specific handler functions based on their URL path and HTTP method. It acts as the central hub for defining the API surface of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fe3b521-fd40-4598-bbc8-5d16a1ea73ac', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the benefit of using Redis modules for custom data types?', N'Senior', N'Modules extend Redis functionality by allowing developers to implement new data structures and commands in C. This provides the performance of core Redis while enabling domain-specific functionality like full-text search or time-series analysis without needing external middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dba5a7a7-5325-4912-8072-5d1745aefd85', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the advantages of move semantics over copy semantics?', N'Middle', N'Move semantics allow resources owned by a temporary object to be transferred to another object without performing a deep copy. This significantly reduces unnecessary allocations and memory operations, leading to substantial performance improvements for complex objects like strings or vectors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f15a6a26-a71c-4800-aab6-5d1769e7ccde', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle JSON binding for incoming requests?', N'Junior', N'Echo provides the Bind method, which automatically maps incoming request payloads to a Go struct. It inspects the Content-Type header and deserializes the JSON data into the provided struct fields based on JSON tags.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37ce1cb0-0f5d-45c7-9312-5d17ded9ad47', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How do you handle API versioning in a Laravel application?', N'Middle', N'API versioning is typically handled by segregating routes into different files or controller namespaces based on the version. This allows you to maintain backward compatibility for existing clients while introducing new features or breaking changes in newer versions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab0918dc-3f1a-44f1-9ece-5d18ccec5884', N'075b8862-431c-4678-9767-f55359758a4a', N'Discuss the trade-offs of using ''provide/inject'' versus a state management library like Pinia in a large-scale enterprise application.', N'Senior', N'Provide/inject is ideal for component composition and dependency injection, but it lacks centralized state observability and devtool support. Pinia provides a structured, globally accessible, and type-safe state container that simplifies debugging, persistence, and complex cross-module state orchestration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e9f3cb6-e050-4ef5-b067-5d1b0435f9c0', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are Lit lifecycle callbacks?', N'Junior', N'Lifecycle callbacks are methods that run at specific points in a component''s existence, such as when it is connected to the document, disconnected, or after it updates. They allow developers to perform setup or cleanup tasks at the appropriate time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db4e0abd-c694-4513-8f43-5d1e30158858', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What role do ''Astro Integrations'' play in the project''s build architecture?', N'Senior', N'Integrations are hooks that allow developers to tap into the Astro build lifecycle, such as adding custom Vite plugins, injecting scripts, or modifying the final HTML output. They are the primary mechanism for extending framework functionality without modifying the core engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'805b884c-ec2c-44be-bcc7-5d220e21b041', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the role of the ''unsafe'' package in Go''s type system?', N'Senior', N'The unsafe package allows programs to bypass the type safety and memory management guarantees of the Go compiler. It is primarily used for low-level system programming, such as interfacing with C code or implementing highly optimized memory-mapped structures, at the cost of potential memory corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'888feadb-7509-4596-af52-5d22d3b20b93', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the effect of the ''slots'' attribute in a class?', N'Middle', N'The ''slots'' attribute restricts the creation of a dynamic dictionary for instance attributes, forcing the class to use a fixed-size array structure instead. This significantly reduces memory consumption for objects with few attributes but prevents the dynamic addition of new attributes at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33420e32-3ca7-4322-b11b-5d2396566b72', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are the performance implications of using a data frame compared to a data table?', N'Middle', N'While standard data frames are the default, they often involve excessive copying and slower subsetting due to their underlying structure. Data tables provide in-place modification and optimized indexing, significantly reducing memory usage and computation time for large-scale data manipulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3e287fe-8826-44dc-b870-5d240dc30df1', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What are environment variables in Vite?', N'Intern', N'Environment variables allow developers to store configuration settings that change based on the deployment target, such as API URLs. In Vite, these files must be prefixed with VITE_ to be exposed to the client-side code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76eda150-a18f-41b3-b4e7-5d27d3a0b612', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the purpose of ''runtimeConfig''?', N'Fresher', N'runtimeConfig is used to provide private and public environment variables to your application. It allows you to inject configuration values that can be accessed both on the server and the client, while keeping sensitive keys safe on the server side.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4da9d444-85d7-4834-abf7-5d29e2f08315', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Hot Module Replacement (HMR) function in Vite, and how does it differ from Webpack''s approach?', N'Senior', N'Vite performs HMR over native ESM via a WebSocket connection. When a file changes, Vite invalidates the module graph and sends a message to the browser to refetch the specific module, keeping the update localized and efficient without reloading the entire page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8566a07-f0a7-464a-a0d3-5d29e7162e36', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is a ''val'' in Scala and how does it differ from a ''var''?', N'Intern', N'A ''val'' is an immutable variable that cannot be reassigned once it is initialized, promoting safer functional programming practices. In contrast, a ''var'' is a mutable variable that can be changed or reassigned throughout the life of the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0ae99ae-2e00-4b80-bb54-5d2a06805174', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Describe the trade-offs of using Incremental Static Regeneration (ISR) compared to traditional Server-Side Rendering (SSR).', N'Senior', N'ISR provides the performance benefits of static sites with the ability to update content without a full rebuild, whereas SSR ensures data is always fresh on every request. ISR is ideal for high-traffic content that changes periodically, while SSR is necessary for highly dynamic, user-specific data that cannot be cached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f6ea006-eb6b-41a5-8626-5d2b538d2d9b', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Explain the role of the ''h'' function in Preact.', N'Middle', N'The ''h'' function, or hyperscript, is responsible for creating virtual DOM nodes. It takes the tag name, attributes, and children as arguments to return a VNode object that the renderer uses to update the actual DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e749c307-299d-4329-b1a2-5d2ca1006aae', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Does Vite require a bundler for the final production build?', N'Fresher', N'Yes, Vite uses Rollup internally to bundle the application for production. While it uses native ES modules during development for speed, it bundles the code for production to ensure optimal performance, tree-shaking, and compatibility with older browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22ace6fc-f5be-4b95-81cf-5d2f66d55250', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What are Echo''s built-in HTTP error handlers?', N'Junior', N'Echo includes a centralized error handling mechanism that converts returned errors from handlers into appropriate HTTP responses. You can customize the global error handler to ensure consistent error formats across the entire API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4dbf59df-d926-4d00-a713-5d302c7abe1e', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What happens if you modify the state directly in a reducer?', N'Junior', N'Directly modifying the state violates the principle of immutability. This can cause bugs where components do not re-render correctly because the reference to the state object remains the same, preventing Redux from detecting that a change occurred.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c72d21a3-04e7-4889-b869-5d31af88d646', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why is Elasticsearch considered a schemaless or flexible-schema database?', N'Junior', N'Elasticsearch is considered flexible because it can index JSON documents without requiring a strictly predefined schema. It automatically detects data types and creates mappings, allowing developers to add new fields dynamically as application needs evolve.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74f10617-6038-401c-8e50-5d33cc4fba2a', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Why is it important to consider the ''Timeout'' settings of an Echo server when calling upstream microservices?', N'Senior', N'If an Echo server waits indefinitely for an upstream service, it can lead to resource exhaustion due to goroutine leakage. Explicitly setting timeouts ensures that slow upstream dependencies do not degrade the performance of the entire system, adhering to the fail-fast principle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fb06c1e-ce6e-4b20-bffc-5d35c4bc4a01', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a deadlock and how can it occur?', N'Junior', N'A deadlock occurs when two or more transactions are waiting for each other to release locks on resources. This creates a cycle where no transaction can proceed, requiring the database engine to detect the situation and abort one of the transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d339ba8-9b38-4106-8526-5d3705b1ab4e', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle time-sensitive data expiration?', N'Senior', N'Redis uses a combination of passive and active expiration strategies. Passive expiration occurs when a client attempts to access a key, while active expiration periodically samples random keys with TTLs set and deletes those that have expired, balancing CPU usage and memory reclamation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94a7f611-d7e3-4a0e-97b6-5d3a018acf4f', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis Sentinel achieve high availability, and what is the risk of split-brain scenarios?', N'Senior', N'Sentinel provides monitoring, notification, and automatic failover by reaching a quorum among distributed nodes. Split-brain occurs if the network partitions the cluster, potentially leading to multiple masters; Redis mitigates this by requiring a majority quorum to elect a new master.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce82ce7b-821e-40eb-bbd2-5d3a789ec8c6', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you approach the trade-off between technical debt and shipping features quickly?', N'Senior', N'I frame technical debt as a financial loan with interest that accumulates over time, impacting future velocity. The decision to incur debt must be a conscious strategic choice, documented with a clear plan to repay it before it compromises system stability or developer productivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2dd88f1-4370-4a09-b5a5-5d3b0015f003', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the benefit of using ''ValueTask'' over ''Task'' in asynchronous programming?', N'Middle', N'ValueTask is a struct-based type that can reduce heap allocations when a method completes synchronously. It is highly efficient for scenarios where an operation often results in a cached value, helping to reduce garbage collector overhead in high-performance paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3ad8c9e-7894-492b-a815-5d3bdfd958a8', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the performance implications of Django''s QuerySet evaluation mechanism.', N'Senior', N'QuerySets are lazy, meaning they are only evaluated when the data is accessed, allowing for complex query chaining. However, frequent, unintentional evaluation—such as iterating over a QuerySet multiple times—can lead to redundant database hits that degrade performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d30cbd7-9182-48d6-a323-5d3f37597b22', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of the ''alias'' feature in Elasticsearch?', N'Middle', N'Aliases provide a layer of abstraction that allows you to point multiple indices to a single name or swap indices without updating application code. This is essential for zero-downtime index rotation, such as when using Time-Based Indices or reindexing data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8eea6c8c-c3d8-4e7b-b2a7-5d406a184533', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does ''readonly'' do in an interface?', N'Intern', N'The readonly keyword prevents a property from being reassigned after its initial creation. This helps ensure that certain data remains immutable throughout the application''s lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40962d2e-4247-40ad-b970-5d42dcec55c8', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using a database index and insertion speed?', N'Fresher', N'Indexes significantly speed up data retrieval by providing a shortcut to records. However, every time you insert or update data, the index must also be updated, which creates a performance overhead on write-heavy operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39353633-2c18-492a-bf63-5d459dd155cb', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix handle cross-origin resource sharing (CORS)?', N'Middle', N'CORS is handled via dedicated middleware that inspects requests and injects the necessary headers. It allows developers to define complex policies based on origins, methods, and headers to control how browser-based clients interact with the API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfcd84c8-f0b0-4af6-af02-5d45dbae8b51', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Does Vite use a bundler for production builds?', N'Intern', N'Yes. While Vite avoids bundling during development for speed, it uses Rollup to bundle, minify, and optimize the code for production. This ensures the final output is efficient and compatible with older browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b96a80c0-420e-4c78-850d-5d4a0fc76765', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the 400KB limit in DynamoDB?', N'Junior', N'The 400KB limit refers to the maximum size of a single item in a DynamoDB table. This includes the total size of all attribute names and values combined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66c7382e-5083-4407-8c5f-5d4a77a7328b', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are Webpack ''chunks'' and how do they relate to performance?', N'Middle', N'Chunks are the resulting output files generated by Webpack after processing the dependency graph. Splitting the application into multiple chunks allows for better caching and enables the browser to download only the necessary code for a specific route, improving performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48c4c022-a6cf-4397-b1e2-5d4baca8623a', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the purpose of the ''Mount'' function in Chi?', N'Intern', N'The Mount function is used to attach a sub-router to a specific path prefix. Any request starting with that prefix will be handled by the mounted router.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc393cc2-5316-4364-999b-5d4cf06f29ba', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the concept of Type Safety in Swift.', N'Fresher', N'Type safety means the language encourages or requires you to be clear about the types of values your code can work with. If part of your code expects a string, it cannot pass an integer by mistake, as the compiler will catch this error during development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
