INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df76e558-0631-48df-b499-5d4dd218aba5', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is a symbol and how does it differ from a string?', N'Junior', N'A symbol is an immutable identifier that is represented by a colon prefix, while a string is a mutable sequence of characters. Symbols are memory-efficient because they are only stored once in memory, whereas every string object is a unique instance even if the text content is identical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb3fa99b-9727-4bef-ae66-5d5659d84538', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the ''lock'' statement used for?', N'Junior', N'The ''lock'' statement is used in multi-threaded programming to ensure that a block of code is only executed by one thread at a time. It prevents race conditions by acquiring a mutual exclusion lock on a specific object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3024d3be-5a53-456b-ad86-5d5b08f6d107', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi support versioning in a RESTful API architecture?', N'Senior', N'Versioning is typically handled by creating sub-routers for each API version, such as ''/v1'' and ''/v2''. This allows the application to maintain different sets of middleware and handlers for each version, facilitating a smooth deprecation path for older clients.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c441d9e6-90b4-4a01-9a21-5d5b62605762', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using an off-the-shelf SaaS solution versus building a custom internal tool?', N'Senior', N'SaaS solutions trade off customization and long-term cost for rapid integration and external maintenance. Building custom tools provides perfect alignment with business logic and long-term ownership, but introduces significant engineering overhead. I generally choose SaaS for commodity functions and build custom solutions only when the feature is a core competitive differentiator.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e4f28df-4f29-4692-b05e-5d5e9a1bf6da', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you manage API deprecation gracefully?', N'Middle', N'Graceful deprecation involves announcing the end-of-life well in advance, providing clear migration guides, and using custom headers like ''Warning'' or ''Sunset'' to notify developers. Monitoring usage of deprecated endpoints allows you to contact specific users who have not yet migrated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68a9bc35-0101-40b9-8f07-5d5ec89c87d6', N'954a0331-deff-4399-b588-96f39fec001d', N'What are observables?', N'Intern', N'Observables are declarative which provide support for passing messages between publishers and subscribers in your application. They are mainly used for event handling, asynchronous programming, and handling multiple values. In this case, you define a function for publishing values, but it is not executed until a consumer subscribes to it. The subscribed consumer then receives notifications until the function completes, or until they unsubscribe.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'722a2e5f-05fb-4e36-ad67-5d629242dc7c', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of Enums?', N'Junior', N'Enums allow developers to define a set of named constants, making the code more readable and self-documenting. They are particularly useful for representing a group of related values, such as status codes or directions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3822b4c3-e494-47b4-a4fb-5d63150d155d', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How can you implement rate limiting in Express, and why is it important?', N'Middle', N'Rate limiting is implemented using middleware that tracks request counts per IP address over a specific window of time. It is crucial for protecting the server from brute-force attacks, denial-of-service attempts, and excessive API consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34775563-c44b-4814-9d94-5d63c7572f39', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How do mapping explosions occur, and why are they dangerous?', N'Senior', N'A mapping explosion happens when an index contains too many unique field names, often caused by dynamic mapping of arbitrary keys. This consumes excessive memory in the cluster state and slows down indexing, potentially making the index unmanageable or crashing the master node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cccf20f3-285e-4b14-a95c-5d64db555734', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is Hot Module Replacement (HMR) and how does it improve the developer experience?', N'Middle', N'HMR allows the application to update modules in the browser without requiring a full page reload. This improves the developer experience by preserving the application state, such as form inputs or scroll position, while reflecting code changes almost instantly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55b0c5cd-a247-4226-89ad-5d672746a89b', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the trade-offs of setting the `hz` (server cron frequency) parameter in Redis?', N'Senior', N'A higher `hz` value allows Redis to perform background tasks like key expiration and cluster maintenance more frequently, reducing latency during these cycles. However, it also increases CPU usage, which can affect the throughput for processing client requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
