INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98e1dab5-6497-463e-b7bf-5d6896db353a', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How does documentation impact the long-term success of a technical project?', N'Intern', N'Documentation serves as a knowledge base that helps team members understand the design decisions, usage patterns, and troubleshooting steps of a system. It prevents information silos and ensures that the project remains maintainable even as the original team members transition out of the role.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0998609f-8cc2-4868-9414-5d6ad62ab111', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the function of the loading.js file?', N'Junior', N'The loading.js file creates a loading UI that is automatically displayed while the contents of a route segment are being fetched. It uses React Suspense under the hood to show a fallback, such as a spinner, during the data loading process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29e7ad65-79c7-4ddb-841f-5d6ce5a1ea01', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the primary advantage of NoSQL for big data?', N'Intern', N'The primary advantage is its ability to scale horizontally across commodity servers, which is much more cost-effective for massive datasets. Additionally, its flexible schema allows for rapid development cycles when dealing with data that changes frequently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66a81b82-6f6a-4a4c-8ca7-5d6dfb12b0a9', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How do ''Tasks'' and ''Agents'' serve as alternatives to complex GenServer implementations in Phoenix?', N'Senior', N'Tasks are designed for one-off concurrent operations, while Agents provide a simple way to manage state. They reduce boilerplate code for simpler scenarios where the full power of a GenServer (like complex message handling and system integration) is not required, keeping the codebase cleaner and more maintainable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65b2b7c1-b409-47ab-9e09-5d6f54a1abb2', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Does Go support object-oriented programming like Java or C++?', N'Fresher', N'Go is not a traditional object-oriented language because it lacks classes and inheritance. Instead, it uses structs to define data structures and interfaces to define behavior, promoting composition over inheritance to achieve modular and reusable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85668bd3-75ee-4848-9584-5d710205007c', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the purpose of the Plug pipeline in Phoenix.', N'Middle', N'Plugs are composable modules that sit between the web server and the application, transforming the connection at each step. The pipeline defines a sequence of these plugs that handle tasks like authentication, session management, and parameter parsing before the request reaches the controller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8fe296e-05f3-4875-a555-5d73d555f3e5', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Is it possible to use native CSS variables in Sass?', N'Fresher', N'Yes, Sass supports native CSS variables fully. You can define them as you would in standard CSS, and Sass will simply pass them through to the output, allowing you to combine the benefits of Sass''s pre-processing with the dynamic nature of CSS custom properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0909841d-9ab4-4c42-a422-5d74291436e6', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Explain the role of ''hooks.server.js'' in a SvelteKit application.', N'Middle', N'The server hooks file allows developers to intercept and modify every request made to the server. It is commonly used for authentication checks, setting custom response headers, or modifying the event object before it reaches the load functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adaa9e48-4467-47a4-88dc-5d7552a64c3d', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the ''refresh'' operation?', N'Intern', N'The refresh operation makes the changes currently held in memory buffers available for searching. It creates a new searchable segment in the index.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c16d4a4-4f5b-450d-9d93-5d795bf42c08', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Explain the concept of ''Build-time Metadata'' in Quarkus.', N'Middle', N'Build-time metadata refers to the information gathered by Quarkus during the Maven or Gradle build process to pre-configure beans and extensions. By resolving configurations and scanning classes before the application starts, Quarkus eliminates the need for expensive runtime classpath scanning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c0c71bd-b959-4ff2-9184-5d7a355496e9', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is a Life Cycle Hook in NestJS?', N'Intern', N'Life cycle hooks are methods provided by NestJS that allow you to tap into key events in the application''s lifecycle, such as module initialization or application shutdown. Examples include onModuleInit and onApplicationBootstrap.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21369151-e8f5-41ff-86d0-5d810e636c13', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are the performance implications of deep component nesting in Lit?', N'Senior', N'While Lit is efficient, deeply nested components create many individual update cycles. Developers should aim for a flat architecture where possible and use memoization or shared controllers to prevent propagation of updates throughout the component tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e98d6d2-a5e5-4dec-9b3e-5d81872cc504', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the purpose of an index in a NoSQL database?', N'Fresher', N'An index is a data structure that improves the speed of data retrieval operations on a database table or collection. Without indexes, a database would have to scan every document to find the requested data, which is inefficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb7382b6-fa29-47e8-9ee6-5d8cc67ec99d', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is jQuery and why was it originally created?', N'Intern', N'jQuery is a fast, small, and feature-rich JavaScript library. It was created to simplify HTML document traversal, event handling, and animation by providing an easy-to-use API that works across a multitude of browsers, abstracting away inconsistencies between them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ff8e37c-be74-4cc0-851b-5d8d71e81045', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are Lit decorators used for?', N'Junior', N'Decorators are a JavaScript feature used in Lit to define reactive properties, query DOM elements, and register custom elements. They provide a concise and readable syntax for configuring component features without needing manual boilerplate code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdd713de-55c7-4517-9aa2-5d8de66df461', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the cache system in Symfony?', N'Fresher', N'The cache system stores computed data, such as compiled configuration or Twig templates, to improve application performance. By storing these results, the framework avoids recalculating complex logic on every incoming request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd25da434-2a12-467d-8972-5d8ea46c5bf1', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik optimize performance for different page routes?', N'Fresher', N'Qwik optimizes performance by ensuring that each page route only loads the JavaScript code specific to that route. Since code is split into small chunks, navigation between pages only requires fetching the minimal code needed for the new view.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d7c1030-0dcb-42c5-9e19-5d90d0c16f18', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby''s method lookup path (ancestor chain) function when singleton classes are involved?', N'Senior', N'When a method is called, Ruby first searches the object''s singleton class. If not found, it continues through the class hierarchy, including any prepended modules, the class itself, included modules, and finally the superclasses, ending at BasicObject.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'904620e0-98bf-403a-a490-5d90fe3d274c', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is a ''cold start'' in caching, and how does it affect system behavior?', N'Middle', N'A cold start happens when a cache is empty, forcing all initial requests to bypass the cache and hit the backend database. This results in an initial period of high latency and high load on the database until the cache is adequately populated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fa2c2b6-b0e4-4433-8168-5d9202ee12d9', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus manage Health Checks?', N'Junior', N'Quarkus uses the MicroProfile Health specification to expose endpoints that report the application''s status. Liveness probes indicate if the container is running, while readiness probes signal if the application is prepared to receive traffic, both of which are easily configured using annotations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbe602c0-3eb9-4270-940a-5d93b02a1f12', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin handle interoperability with Java?', N'Intern', N'Kotlin is designed to work seamlessly with existing Java code. You can call Java code from Kotlin and vice versa, allowing developers to use Kotlin in projects that already contain large amounts of Java code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'297b3cff-c451-4879-bd2a-5d947a49f9f9', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is ''Optimistic UI'' in the context of Remix?', N'Middle', N'Optimistic UI is a pattern where the application updates the interface immediately after a user triggers an action, assuming the server will succeed. Remix simplifies this by using the navigation state to track pending submissions, allowing the UI to reflect the intent before the server confirms completion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
