INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca4e94c6-09a8-48f7-9302-5d9784f2facb', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the role of a collection in a document database?', N'Fresher', N'A collection acts as a grouping of similar documents, similar to a table in a relational database. It serves as a container for documents that share a common purpose or data type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff7dafde-d761-4b2d-9a18-5d97fa5e81e8', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle technical debt in a project?', N'Junior', N'I would document the technical debt and bring it to the attention of the team lead to determine if it should be addressed in the current sprint. If it is not a priority, I ensure that any new work I do doesn''t worsen the debt and plan to tackle it when there is capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5801955-7393-4579-9d9d-5d99b575624d', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of the Symfony Kernel?', N'Intern', N'The Kernel is the heart of a Symfony application that handles every request. Its primary role is to take an incoming HTTP request, pass it through various listeners, determine the correct controller to execute, and return the final HTTP response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7216c341-f200-48aa-a1e8-5da4f4bd21b3', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain the CAP theorem and its implications for distributed systems.', N'Middle', N'The CAP theorem states that a distributed system can only guarantee two out of three properties: Consistency, Availability, and Partition Tolerance. In the presence of a network partition, designers must choose between immediate consistency or high availability, making this a fundamental trade-off in database selection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49c0a39b-8f04-44a7-b28f-5da5b13afd44', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is ''security'' considered an ongoing process rather than a one-time setup?', N'Intern', N'New vulnerabilities are discovered constantly, and technology evolves, meaning old security measures can become outdated. Ongoing monitoring and updates are required to defend against new threats and adapt to changing environments. Consistent maintenance ensures that the system remains protected over its entire lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8897d458-cca4-4cc1-b541-5da5eebd5497', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why should you avoid using ''SELECT *'' in Cassandra?', N'Junior', N'Retrieving all columns can be inefficient because Cassandra is designed to read only the specific columns required for a query. Furthermore, large tables can cause performance issues if too much data is pulled into memory at once during a broad scan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd35de2b-b47d-4e85-8c60-5daaadd8d87e', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between the ''id'' and ''class'' attributes in terms of document structure?', N'Middle', N'The ''id'' attribute must be unique within an entire HTML document and is often used for fragment identifiers or specific DOM targeting. The ''class'' attribute is intended for groups of elements that share similar styles or behaviors, allowing for high reusability across a page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
