INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b408730e-df4e-4cdd-9033-5dc7eab07f75', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain the difference between Read Concern ''local'' and ''majority''.', N'Middle', N'Read concern ''local'' returns the most recent data available on the node, which may be rolled back if the primary fails. ''Majority'' ensures that the data returned has been acknowledged by a majority of the replica set members, providing stronger consistency guarantees against rollbacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
