INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d18efbd-a4f2-400b-b010-5dd6bd4e398f', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How would you implement a distributed task queue system in a Flask application while maintaining high availability?', N'Senior', N'You should offload long-running tasks to a background worker system like Celery or RQ using a message broker like Redis or RabbitMQ. To maintain high availability, ensure the broker is deployed in a clustered configuration and the workers are scaled independently based on queue depth metrics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37db8166-13f4-4154-a060-5dd990a485d6', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the importance of ''Type-safe'' configuration in Quarkus?', N'Middle', N'Type-safe configuration allows developers to map properties to Java objects, ensuring that application settings are validated at startup. This prevents runtime failures caused by malformed or missing configuration, providing immediate feedback if the environment setup is incorrect.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0242449f-018f-4002-8483-5dda5b9f7341', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between IConfiguration and Options pattern?', N'Fresher', N'IConfiguration is a low-level interface to access raw key-value pairs from configuration files. The Options pattern is a strongly-typed approach that maps configuration sections to C# classes, making settings easier to inject and use throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f6ce294-0d8a-4d5b-bc50-5ddaa1db4967', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono support RPC (Remote Procedure Call) features?', N'Junior', N'Hono allows developers to share type definitions between the backend and the frontend. By using a client-side wrapper, the frontend can call API endpoints as if they were local functions, providing automatic type safety and autocompletion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5193674-350e-4efb-aca6-5ddaabe251a4', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a ''key'' in Redis?', N'Intern', N'A key is a unique string used to identify and access a specific value in Redis. Keys are case-sensitive and can contain almost any binary sequence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2f5eac8-84db-4a5a-9a5a-5ddbab2ff4b3', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How can you trigger a re-render if a non-primitive value, like an array, is updated?', N'Junior', N'Since Svelte reactivity is triggered by assignment, simply pushing to an array will not trigger a UI update. You must reassign the array variable to itself or create a new copy to ensure Svelte detects the change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd45e85e6-8e3d-413f-8124-5ddf31940db4', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the primary difference between Rust''s ownership model and garbage collection?', N'Middle', N'Ownership uses a compile-time system of rules to manage memory, where each value has a single owner that determines its lifetime. Unlike garbage collection, which periodically scans and cleans up memory at runtime, ownership enforces safety through static analysis, eliminating the need for a runtime overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd652af75-319e-4737-9327-5ddf55a0c679', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are the limitations of the C stack management model in deeply recursive systems?', N'Senior', N'C relies on a fixed-size contiguous stack segment, making it susceptible to stack overflow errors during deep recursion. Since the language does not mandate tail-call optimization, recursive functions consume stack frames linearly, unlike functional languages that can optimize tail-recursive calls into jumps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3278ad7f-8f20-4093-8816-5de21cea5196', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Explain the presentational vs container component pattern in React', N'Fresher', N'The presentational vs container component pattern (also known as "dumb vs smart components") splits components into two roles: presentational components decide how things look and receive everything via props, while container components decide how things work — they fetch data, hold state, and pass props down. Dan Abramov, who popularized the pattern in 2015, updated his original article in 2019 to say he no longer recommends splitting components this way: hooks (especially custom hooks) cover the same separation of concerns without forcing you to introduce a wrapper component. The vocabulary is still useful for talking about responsibilities, but in modern React the "container" layer is usually a custom hook. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e87cb7a3-f3e5-4d3b-9186-5de32015a3b3', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why are indexes in Cassandra not always recommended for high-cardinality columns?', N'Middle', N'Secondary indexes in Cassandra are local to each node and can lead to significant latency spikes if they require scanning the entire cluster. For high-cardinality data, they often perform poorly compared to creating a dedicated table specifically for that query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'681d99c0-bb40-46de-8463-5de457fc0e86', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is meant by ''fault tolerance'' in Phoenix?', N'Fresher', N'Fault tolerance refers to the ability of the system to continue operating even when parts of it fail. In Phoenix, this is achieved through supervision trees where parent processes can restart failed child processes automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7650df2d-4e88-41ee-9e8a-5de4b5c96797', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Describe how the ''Query Optimizer'' selects an index for a given query.', N'Senior', N'The query optimizer evaluates potential query plans by running them in parallel for a short period or using cached statistics. It selects the plan that demonstrates the lowest execution cost, typically measured by the number of documents scanned, and caches this plan for future use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b4abab7-7931-4935-9675-5de6fc4dc795', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does it mean for TypeScript to be a superset of JavaScript?', N'Intern', N'Being a superset means that all valid JavaScript code is also valid TypeScript code. TypeScript extends JavaScript by adding features like static typing and interfaces, which are then compiled down to plain JavaScript for browsers to execute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71a0ab61-ec99-49f0-81b8-5de970c4b6ca', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro support different UI frameworks?', N'Fresher', N'Astro is framework-agnostic, meaning it allows you to use components from frameworks like React, Vue, Svelte, or Solid within the same project. You can mix and match these components on the same page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ecbcf3a-adef-434e-8b8f-5deaae3ae139', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the role of a ''tsconfig.json'' file?', N'Intern', N'The tsconfig.json file acts as the configuration file for the TypeScript compiler. It specifies the root files and various compiler options that control how the project is compiled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ccd2d2a-1ae3-4c3e-bde8-5dec5ad6a221', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle client-side HTTP calls?', N'Fresher', N'Micronaut provides a declarative HTTP client that allows you to define interfaces for external API calls. The framework implements these interfaces at compile-time, making external service integration simple and efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a3069e7-35d8-44f1-8e94-5dec7c70c574', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is ''Deserialization'' in the context of Rocket?', N'Intern', N'Deserialization is the reverse of serialization, where incoming data like JSON is converted back into Rust data structures. This allows you to work with incoming request bodies as type-safe objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60d4c2c1-7c43-4bf8-89d0-5dee59a9f4f1', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the ::selection pseudo-element?', N'Intern', N'::selection applies styles to the portion of a document that has been highlighted (selected) by the user, such as by clicking and dragging over text. Supported CSS properties (only a subset is allowed): * color * background-color * text-shadow * text-decoration (in some browsers) Example: > Note: The ::-moz-selection vendor prefix was required for Firefox in older versions but is no longer needed in modern browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b7916d3-0b4d-46ca-bcfb-5df1860f7cc1', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the concept of Variance (Covariance and Contravariance) in Scala.', N'Middle', N'Variance defines how the subtyping relationship of complex types relates to their component types. Covariance allows a more specific type to be used where a general one is expected, while contravariance allows a more general type to be used where a specific one is expected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e255540-6cb8-4ad7-a838-5df5ceaa915f', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the G1 Garbage Collector manage heap fragmentation differently than the CMS collector?', N'Senior', N'G1 partitions the heap into equal-sized regions and performs evacuations, which involve copying live objects from one region to another to compact memory. Unlike CMS, which uses a free-list approach that can lead to significant fragmentation, G1''s evacuation strategy inherently maintains contiguous free space, improving allocation performance for large objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd88f80ae-d383-457b-a80c-5df859df6fa7', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What does CRUD stand for?', N'Intern', N'CRUD stands for Create, Read, Update, and Delete. These are the four basic functions that are required to manage data in most web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e324f42-e0cf-468a-8677-5df897176bd3', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is ''Code Splitting'' in Qwik?', N'Intern', N'Code splitting is the process of dividing the application into smaller, granular chunks. Qwik performs this automatically at a very fine-grained level, ensuring that only the specific code needed for a component or event is downloaded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a702e911-1632-4bc4-9f63-5dfb5b65d09d', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the ''invalidate'' function used for in SvelteKit?', N'Middle', N'The invalidate function is used to force a reload of data for a specific route or dependency. It is commonly called after a successful form submission to ensure the page displays the latest state from the server without needing a full page refresh.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e62c79f-87e5-498a-ab02-5dfc7f2a55db', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you resolve a situation where a third-party API is experiencing frequent downtime that impacts your service?', N'Middle', N'I would implement circuit breakers and local fallback mechanisms to prevent the downtime from impacting the user experience. Additionally, I would work on a more resilient integration strategy, such as implementing retry policies with exponential backoff or caching the API results.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
