INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0fc863a-26f3-4092-bc04-5e0a58699d18', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you search a string for a pattern?', N'Fresher', N'1. Using test() It searches a string for a pattern, and returns true or false, depending on the result. 2. Using exec() It searches a string for a specified pattern, and returns the found text as an object. If no match is found, it returns an empty (null) object. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e382701e-55fb-440f-9da3-5e0a75966634', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are the trade-offs of using metaprogramming in Ruby?', N'Middle', N'Metaprogramming allows for highly flexible and DRY code by generating methods at runtime. However, it can make code significantly harder to debug, navigate, and understand for other developers, and it often bypasses static analysis tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3481d859-5275-4fe2-aaf2-5e0cb32bc986', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the role of the file-based router in SvelteKit?', N'Fresher', N'SvelteKit uses the directory structure of the src/routes folder to define the application''s URL paths. Each folder represents a route segment, and specific file names like page.svelte determine the content displayed for that route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5a9c568-bfc7-4ec7-8df1-5e0cddd29726', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you approach the trade-off between standardizing on a single programming language versus allowing polyglot environments?', N'Senior', N'Standardization reduces the cognitive load for team rotations and simplifies tooling and hiring. Polyglot environments allow teams to use the best tool for the specific job, improving performance or developer productivity, but they increase the cost of infrastructure maintenance and shared knowledge silos.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b30212b-63fd-4105-ad8f-5e0ce9420b07', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Does Preact support Fragments and Portals?', N'Middle', N'Yes, Preact provides support for Fragments to group multiple elements without adding extra nodes to the DOM. It also supports Portals, which allow rendering children into a different part of the DOM tree, such as for modals or tooltips, just like in React.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b0127f1-41e0-44b0-954c-5e10a3a50dfd', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why is the OPCache extension critical for production PHP scalability?', N'Senior', N'OPCache compiles PHP scripts into bytecode and stores them in shared memory. This eliminates the overhead of repeatedly parsing and compiling source files into opcodes on every request, significantly reducing CPU cycles and latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2184ef3c-cf65-4cce-9a41-5e10b4722619', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the difference between client-side and server-side navigation?', N'Junior', N'Server-side navigation happens when the browser requests a new page from the server, causing a full page refresh. Client-side navigation, handled by Next.js, updates the UI without a refresh, making the app feel faster and more responsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e4e3876-67d2-4edf-a558-5e1284e77f24', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the role of the createSignal function?', N'Intern', N'The createSignal function initializes a new reactive signal. It returns a pair consisting of a getter function to access the current value and a setter function to update that value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8815e21-6a9d-43d3-bc39-5e13caf14f0d', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Explain the architectural implications of implementing distributed tracing using sampled data versus full-fidelity tracing in a high-throughput system.', N'Senior', N'Full-fidelity tracing provides complete observability but imposes significant overhead on network bandwidth and storage infrastructure, potentially impacting system performance. Sampling reduces this overhead significantly but risks missing rare, sporadic errors or edge-case anomalies that occur in infrequent request paths. The architectural choice depends on the balance between cost-efficiency and the business requirement for debugging intermittent, hard-to-reproduce issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ee8dd39-5404-4f46-9831-5e14b344cb8b', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What are ''Tags'' in the context of Gin data binding?', N'Intern', N'Tags are metadata attached to struct fields that tell the Gin binder how to map incoming data to the fields. For example, a JSON tag specifies the key name in the incoming JSON object that should populate that specific field.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee8789ee-868d-4f82-97e7-5e156fcc37b9', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your strategy for managing secrets and configuration in a distributed cloud environment?', N'Senior', N'I utilize centralized secret management services that offer dynamic rotation and granular access control via IAM roles. Configurations are injected at runtime through immutable containers, ensuring environmental parity and preventing sensitive credentials from being committed to version control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04c36614-7480-41b5-8095-5e16c3bc6a23', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Does Chi replace the standard Go http.ServeMux?', N'Fresher', N'Yes, Chi acts as a replacement for the standard library''s request multiplexer. It provides more advanced routing capabilities while remaining compatible with standard http.Handler interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
