INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab593a4f-072f-473a-819b-5e1e964ecedf', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Describe the mechanism Redis uses to achieve master-replica synchronization.', N'Senior', N'Redis uses a non-blocking replication process where the master creates an RDB snapshot and buffers incoming writes to send to the replica. Once the initial synchronization is complete, the master streams the command buffer, and subsequent operations are propagated via an asynchronous replication stream.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6747891c-e8c4-4454-bf10-5e200645b96c', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Can Vite be used with frameworks other than Vue?', N'Intern', N'Yes, Vite is framework-agnostic. While it is often associated with Vue, it provides official templates for React, Svelte, Preact, and others, and can be used with plain JavaScript or TypeScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38ed54d1-3c25-4cde-9021-5e200b6c5423', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What happens if you dispatch an action that no reducer is interested in?', N'Junior', N'The store will still receive the action, and it will be passed to every reducer in the application. However, because no reducer matches the action type, the state will simply return its current value and remain unchanged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
