INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f254038f-31b8-46e4-9df9-5e2435ddeea6', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are the architectural implications of using Nuxt modules for extending application functionality?', N'Senior', N'Nuxt modules allow for modular architecture by hooking into the Nuxt lifecycle to inject templates, register plugins, or modify build configurations. This promotes code reuse and separation of concerns, though excessive reliance on third-party modules can lead to ''black box'' issues where debugging becomes difficult due to hidden configuration overrides.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'176e0e5d-b70b-4456-b98e-5e244cc599e8', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between ''this'' and ''super'' keywords?', N'Junior', N'The ''this'' keyword refers to the current instance of the class, while ''super'' is used to access members or constructors of the parent class. Both are primarily used to resolve naming conflicts or invoke specialized behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21e063ea-7eef-47a4-83b7-5e25b7ae3305', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle debugging a complex integration issue with an external third-party API that claims everything is fine on their end?', N'Senior', N'I implement rigorous logging of the raw request and response headers at the gateway level to capture exact timestamps and payloads. If necessary, I use a sidecar proxy to mirror traffic and compare it against the expected API contract, providing concrete evidence of discrepancies to the partner.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
