INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'049cee55-013d-45aa-9d19-5e25e4ef69b1', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the significance of the ''maxTimeMS'' parameter?', N'Middle', N'The maxTimeMS parameter sets a time limit for a specific operation. If the operation exceeds this limit, MongoDB terminates it, which helps prevent long-running queries from locking resources or consuming excessive CPU and memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa040e26-e3ca-40c1-887d-5e260d6ff07a', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you bind inline styles in a Vue template?', N'Fresher', N'In Vue.js, you can bind inline styles to an element through several methods like templates with v-bind, dynamic class bindings, and JS object-style declarations. Inline Style Binding Approaches 1. Using the :style Directive: You can define an object with CSS styles and then bind it to the element. Each key-value pair represents a style property and its value. 2. Binding Inline Styles Directly: This approach is useful when the style values need to be dynamic. However, it''s less modular than using a style object. 3. CSS Modules: Places styles in a separate file, processes them with Vue Loader, and requires modular scoped styles in components. This approach provides isolation and reusability. 1. Create a styles.module.css file 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63cf6c3a-32de-4a0d-9256-5e26a6829bd3', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember handle data binding?', N'Intern', N'Ember uses a bidirectional data binding system that automatically keeps the model and the template in sync. When the model updates, the template updates, and user inputs in the template can update the underlying model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cc69972-173b-4e97-9db3-5e2723dd20ad', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the differences between WeakMap and Map', N'Intern', N'The main difference is that references to key objects in Map are strong while references to key objects in WeakMap are weak. i.e, A key object in WeakMap can be garbage collected if there is no other reference to it. Other differences are, 1. Map can store any key type whereas WeakMap can store only collections of key objects 2. WeakMap does not have size property unlike Map 3. WeakMap does not have methods such as clear, keys, values, entries, forEach. 4. WeakMap is not iterable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45ee7098-3775-4772-88fc-5e27c2add0a0', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle data persistence if it stores everything in RAM?', N'Intern', N'Redis offers persistence through two main mechanisms: RDB (Redis Database Backup) which creates point-in-time snapshots of the data, and AOF (Append Only File) which logs every write operation to disk to reconstruct the data upon restart.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a9dac22-2998-43e2-9825-5e2cb87f77a9', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'When designing for data-at-rest encryption, what are the architectural trade-offs between application-level and disk-level encryption?', N'Senior', N'Disk-level encryption protects against physical theft of hardware but leaves data exposed while the OS is running and the volume is mounted. Application-level encryption ensures that data remains encrypted even if the database layer or OS is compromised, though it requires more complex key management and can impact searchability of data fields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e073e6a-930f-474b-bbd7-5e2e93872caf', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Why is it generally discouraged to use Django’s ORM for bulk operations, and what is the alternative?', N'Senior', N'The ORM creates an individual object instance for every record fetched, which causes massive memory overhead and slow performance for large datasets. For bulk operations, one should use raw SQL or the bulk_create and bulk_update methods to minimize memory consumption and database round-trips.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6df127d0-8cc7-436c-9c64-5e2ee013b636', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why might you choose a fiber-based framework over an async/await-based framework?', N'Middle', N'Fibers often allow for more imperative-style code that avoids the ''function coloring'' problem associated with async/await. This makes the code easier to read and maintain, as you do not need to propagate async keywords through the entire call stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab98985d-54d9-47a0-a8c4-5e30722c443c', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How can you test Alpine.js components effectively?', N'Middle', N'Testing should focus on the component''s public interface, such as clicking buttons and asserting DOM changes, using tools like Cypress or Playwright. Since Alpine logic is tightly coupled with the DOM, integration tests are generally more effective than unit tests for verifying behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54b43aad-9374-45c1-92df-5e318e925e3f', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why might you choose a micro-framework approach over a monolithic Express application for specific services?', N'Senior', N'A micro-framework provides a smaller footprint and fewer built-in features, which reduces the attack surface and minimizes startup time. This is beneficial for serverless environments where cold-start performance and memory overhead are critical success factors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aef7c442-61a7-4490-a416-5e33b094269d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between logging too much versus too little information?', N'Junior', N'Logging too much provides excellent visibility for debugging but can consume excessive storage and impact system performance. Logging too little saves resources but makes it nearly impossible to diagnose production incidents when they occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1fc0990-36cd-4f20-a35c-5e34423443df', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is Bundler and why is it used?', N'Intern', N'Bundler is a tool that manages an application''s dependencies by ensuring that the exact versions of the required libraries (gems) are installed. This ensures that the application runs consistently across different development and production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13d27325-983c-4927-9bd8-5e35fc6f15da', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do you navigate between pages in SvelteKit without a full browser refresh?', N'Junior', N'You use the built-in anchor tag. SvelteKit automatically intercepts these links to perform client-side navigation, which makes the transition between pages feel faster and smoother.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14f964df-379d-4b80-b736-5e3a49759d50', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you balance the cost of cloud infrastructure with performance requirements?', N'Senior', N'I perform cost-benefit analysis by matching instance types to workload profiles and utilizing auto-scaling to match supply with actual demand. I also focus on optimizing high-cost bottlenecks—such as database query efficiency or data transfer costs—before pursuing general performance improvements that may have diminishing returns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62dc379e-0c75-4e02-a64d-5e3a7190ae7a', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the primary difference between ''extend'' and ''include'' in Ruby?', N'Middle', N'The ''include'' method mixes module methods into a class as instance methods, making them available to all objects of that class. The ''extend'' method mixes module methods into the class as singleton methods, making them available as class-level methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6f921c9-b906-41c3-818f-5e3d2727f3cd', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs of using a client-side rendering (CSR) strategy versus server-side rendering (SSR)?', N'Middle', N'CSR provides a fluid user experience after the initial load and reduces server load, but it often struggles with initial load times and SEO. SSR ensures faster initial content delivery and better SEO rankings but places a higher computational load on the server and increases the time-to-interactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfd1e484-c65f-485f-a3da-5e3d71ee6aec', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the Symfony Cache component used for?', N'Junior', N'The Cache component provides a unified interface for storing and retrieving data in various backends, such as Redis or the filesystem. It is used to cache expensive operations or database results to improve the overall speed and responsiveness of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b091954-aff3-4893-81a9-5e4039e7b83f', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does the ''Saga'' pattern leverage messaging to manage distributed transactions?', N'Senior', N'Sagas decompose a long-running transaction into a series of local transactions coordinated via asynchronous messages or events. Each step is followed by a success event triggering the next step, or a compensating event if a failure occurs, ensuring eventual consistency across microservices without needing global distributed locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e0c54dd-d6c7-4a8e-9521-5e4360790f21', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the architectural implications of moving state high up in the component tree versus using a state management library?', N'Senior', N'Lifting state high leads to ''prop drilling'' and unnecessary re-renders across large subtrees whenever the state changes. State management libraries provide an external store to decouple data logic from the view layer, enabling granular subscription models that avoid the performance penalties of excessive component tree traversals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b3668e7-80f6-4f46-8c31-5e43db800f46', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What are the trade-offs of using Qwik in a highly dynamic application?', N'Middle', N'While Qwik excels at initial load performance, it requires more complex build-time tooling and strict adherence to serialization rules. Developers must ensure that all state can be serialized, which can occasionally limit the use of certain complex objects or circular data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
