INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d309a2a-8271-4fe7-b571-5e44f71cdc1a', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber''s reliance on Fasthttp affect the implementation of HTTP/2 or HTTP/3 support?', N'Senior', N'Because Fasthttp does not use the standard library''s net/http implementation, it does not automatically inherit the latest HTTP/2 or HTTP/3 support provided by the Go team. This necessitates relying on third-party proxies like Nginx or Envoy to handle newer protocols and terminate TLS efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
