INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18044e14-6c7b-44a9-a127-5e4b9007d97c', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are the trade-offs of using AdonisJS ''Hooks'' versus ''Events''?', N'Middle', N'Hooks are tightly coupled to the lifecycle of a specific model, making them ideal for data-specific logic like hashing passwords before saving. Events are decoupled and better suited for side effects that do not need to block the main flow, such as sending welcome emails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aec983e3-10b7-410e-a9be-5e50b2ab96fd', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the role of a message queue in an asynchronous architecture?', N'Middle', N'A message queue acts as a buffer between services, allowing them to communicate asynchronously by decoupling the producer from the consumer. This prevents the producer from being blocked while waiting for a task to complete, improves system resilience during traffic spikes, and enables better load leveling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
