INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbc9e10b-d2af-4040-98f6-5e5337f3bfd3', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is ''covariance'' and ''contravariance'' in the context of function arguments and return types?', N'Senior', N'Covariance allows a type to be replaced by a subtype, typically applicable to return types, while contravariance allows a type to be replaced by a supertype, which applies to function arguments. TypeScript''s function parameter checking is bivariant by default for flexibility, though strict settings can enforce safer behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f626451-c96f-481d-99b4-5e56e05fdd20', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the trade-off of using Phoenix''s ''LiveView'' regarding server-side memory usage?', N'Middle', N'Because LiveView maintains the state of the UI on the server, it consumes more memory per user connection compared to a traditional stateless API. This can become a scaling constraint if you have a massive number of concurrent users with very large, long-lived states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80017ee5-a410-4563-96a4-5e58db13016d', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Explain the concept of ''Hooks'' in Fastify.', N'Fresher', N'Hooks are lifecycle events that allow you to execute custom logic at specific stages of a request''s lifecycle. Examples include before handling a request, after sending a response, or when an error occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9c0d209-ac38-4de2-8f14-5e5966e9324b', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is a ''proxy'' in Vite configuration?', N'Fresher', N'A proxy is a development-only configuration that redirects API requests from the Vite server to a backend server. This is commonly used to bypass CORS issues during development when your frontend and backend are running on different ports.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5e35fd8-ce52-4e16-8c29-5e59cdaf3036', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why might you choose asynchronous message processing over synchronous HTTP requests in an inter-service communication design?', N'Middle', N'Asynchronous messaging decouples services, increasing system resilience and allowing for better handling of traffic spikes through buffering. The trade-off is increased system complexity, the requirement for robust error handling for message delivery, and the difficulty of tracking distributed state compared to the simplicity of request-response patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e089dd3d-d969-4725-8ab1-5e5a840b02c7', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is ''Distributed Tracing'' and why is it necessary in microservices?', N'Senior', N'Distributed tracing tracks a single request as it propagates through various services and databases. It is essential for debugging performance bottlenecks and identifying failure points in complex systems where logs from individual services are insufficient to reconstruct the transaction path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'349fe686-61bd-4e44-8b65-5e5c8494634e', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Explain the concept of ''Thunks'' and how they differ from ''Sagas'' in terms of side-effect handling.', N'Senior', N'Thunks are simple functions that allow for delayed action dispatching, making them easy to implement but sometimes difficult to manage for complex, parallel, or cancelable flows. Sagas use generator functions to manage side effects, providing a more robust, declarative approach that excels at handling complex concurrency, race conditions, and event-based workflows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39bfcad1-2198-4998-9a4d-5e5ca83775dd', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a Transpiler in the context of TypeScript?', N'Intern', N'A transpiler is a tool that converts source code from one high-level language to another. TypeScript uses a transpiler called the TypeScript Compiler to transform TypeScript code into standard JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa9b795f-f1ef-43e8-afd1-5e5cccc30c48', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What are the limitations of Qwik in terms of third-party library integration?', N'Middle', N'Qwik requires libraries to be compatible with its lazy-loading and serialization patterns. Libraries that rely heavily on global scope, synchronous initialization, or non-serializable object patterns may require wrappers or custom configurations to function correctly within the Qwik ecosystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c6994df-f446-4243-89ba-5e5db7759015', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What are web sockets, and does Axum support them?', N'Intern', N'Web sockets provide a persistent, full-duplex communication channel over a single TCP connection. Axum supports web sockets through the ''axum::extract::ws'' module, allowing for real-time applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca0d0b05-d56b-495a-9cba-5e5ed1953340', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is the use of ''void *'' pointers considered both a strength and a weakness of C?', N'Senior', N'It is a strength because it provides a mechanism for generic programming, allowing functions to operate on any data type. It is a weakness because it sacrifices type safety, forcing the programmer to manually track the underlying data type and increasing the risk of illegal memory access or casting errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c68dac29-9b9b-4037-94f2-5e618a2493da', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the primary purpose of the @SpringBootApplication annotation?', N'Junior', N'This annotation is a convenience that combines @Configuration, @EnableAutoConfiguration, and @ComponentScan. It marks the main entry point of the application and tells Spring Boot to start the automatic configuration process and component scanning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
