INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a99ff9e9-07bc-4057-aa5e-5e6638a59485', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of a database management system (DBMS)?', N'Intern', N'A DBMS is software that acts as an interface between the database and the end-users or programs. It allows users to create, read, update, and delete data while managing security, access, and performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea30d3de-44d6-4032-b0a5-5e66749071eb', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does the ''readonly'' property modifier in modern PHP improve data integrity?', N'Middle', N'The ''readonly'' modifier ensures that a property can only be initialized once, preventing accidental modifications after the object has been created. This is crucial for creating immutable value objects, which leads to safer, more predictable code by eliminating side effects from unexpected state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8211fbb8-65aa-49b1-b0a7-5e67a00bba36', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the purpose of the ''copy-on-modify'' mechanism in R?', N'Middle', N'Copy-on-modify ensures that R objects appear to have pass-by-value semantics even though they are frequently passed by reference internally. When an object is modified, R creates a copy in memory only if the object is shared, preventing unintended side effects in other parts of the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cefe0436-dcf2-4000-9d86-5e6d477119f8', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the purpose of channels in Go?', N'Junior', N'Channels are the pipes that connect concurrent goroutines. They allow you to send and receive values between goroutines, ensuring safe communication and synchronization without the need for explicit locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f70266e-2065-468c-9347-5e6e0a70f9de', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How do AdonisJS ''View'' engines impact application performance?', N'Senior', N'AdonisJS leverages efficient server-side rendering engines that compile templates into functions for faster execution. To maximize performance, one should utilize caching for compiled templates and minimize complex logic within the views, keeping them strictly focused on presentation and offloading data computation to the controller or service layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e002ed0-f1c7-4041-bf03-5e70817992bb', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is meant by scoping in Svelte CSS?', N'Intern', N'Svelte automatically scopes CSS styles defined within a component to that component only. This ensures that styles do not leak out or affect other parts of the application, preventing naming conflicts and accidental style overrides.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee3bd009-a555-488e-907a-5e72237245e1', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do JavaScript modules (ESM) affect the loading and parsing strategy of an application?', N'Senior', N'ESM allows for static analysis of dependencies, enabling the engine to perform tree-shaking and fetch modules asynchronously before execution begins. This improves startup time compared to traditional script loading, which requires sequential parsing and execution that blocks the main thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'979df59f-e30d-4dcd-8672-5e72eb0a57c5', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is ''Code Splitting'' and why does Vite use it?', N'Intern', N'Code splitting is the technique of breaking your application into smaller chunks so that the browser only downloads what is necessary for the current page. Vite automatically manages code splitting during production builds to improve application performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7017495e-4c61-4f31-994e-5e78c47c645c', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you verify a fix for a bug without introducing a regression?', N'Middle', N'I would ensure that the fix includes a targeted automated test case that specifically addresses the bug''s scenario. I would then run a comprehensive suite of regression tests to ensure existing functionality remains unaffected by the changes. Ideally, I would also perform canary testing in production to observe the fix''s impact on a small subset of traffic before a full rollout.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31997215-8751-4f2e-9df6-5e7923702b03', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What does it mean for a PHP function to be pure?', N'Middle', N'A pure function always returns the same output for the same input and produces no side effects, such as modifying global state or writing to a database. Pure functions are easier to test, debug, and reason about, leading to more reliable code. They are a core concept in functional programming styles now often adopted within modern PHP.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f2e5f2d-a962-45dd-bcc1-5e7c183f730a', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot an issue where authentication tokens are expiring prematurely?', N'Middle', N'I would inspect the token lifecycle management logic to ensure the expiration timestamps are being calculated correctly and consistently across all services. I would also check for clock drift between the authentication server and the resource servers, which can cause premature token invalidation if the time synchronization is not accurate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'564ae667-c7c3-48b6-8aeb-5e82db94fc1e', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the difference between React Native and React?', N'Fresher', N'React is a JavaScript library, supporting both front end web and being run on the server, for building user interfaces and web applications. React Native is a mobile framework that compiles to native app components, allowing you to build native mobile applications (iOS, Android, and Windows) in JavaScript that allows you to use React to build your components, and implements React under the hood.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd77b673-261a-4170-83b4-5e85ce559ace', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is a ''Middleware'' in the context of Hono?', N'Fresher', N'Middleware in Hono is a function that sits between the incoming request and the final route handler. It can modify the request or response, perform authentication, or log information before passing control to the next function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95fa4405-79e7-4d41-be12-5e87bf2154d0', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the purpose of the ''!important'' declaration?', N'Junior', N'The !important rule overrides the normal specificity rules, forcing a property to take precedence over any other declarations. It should be used sparingly, as it makes debugging and maintaining stylesheets significantly more difficult.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdf896a4-9077-4add-9b94-5e881d952743', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Why is the use of the !default flag important for themeable libraries?', N'Middle', N'The !default flag allows you to assign a fallback value to a variable, which will only be used if the variable has not been defined yet. This is crucial for library authors, as it allows users to override default settings by defining their own variables before importing the library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2c1afe3-aaa6-42cb-a9d3-5e8c237e6409', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why is the Next.js App Router architecture considered superior for complex applications compared to the Pages Router regarding data fetching?', N'Senior', N'The App Router uses React Suspense and Server Components to support streaming, allowing parts of the page to render and hydrate independently as data arrives. The Pages Router requires blocking data fetching at the page level, leading to a ''waterfall'' effect where the entire page waits for the slowest data source.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37818a26-77e9-4590-b271-5e906fa25880', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How do ''extension functions'' work under the hood?', N'Middle', N'Extension functions are implemented as static methods that accept the receiver object as the first parameter. Because they are resolved statically based on the declared type rather than the runtime type, they do not actually modify the original class and cannot access private members.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'220bba6f-9fb4-4a82-adb4-5e9211623134', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a Savepoint in a transaction?', N'Fresher', N'A savepoint is a marker within a transaction that allows you to roll back part of the transaction without aborting the entire process. It provides a way to define intermediate points to which you can return if specific parts of a complex operation fail.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6e6a580-cdd4-436e-8e35-5e92b05a3bf4', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How do portals work in SolidJS, and why might they be used?', N'Senior', N'Portals allow rendering of DOM elements outside the current component''s hierarchy, such as for modals or tooltips. This is useful for CSS layout constraints like ''z-index'' or ''overflow: hidden'' that would otherwise clip the component if rendered in its parent''s DOM container.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a93f268c-945d-46f4-bf68-5e953b834d7b', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Explain the concept of ''Cold Start'' in Vite and why it scales better than traditional bundlers.', N'Senior', N'A cold start in Vite is independent of the project size because it does not pre-process the entire application codebase before the server becomes responsive. It only resolves modules as the browser requests them, allowing the development server to start almost instantaneously even in massive repositories.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c093c1b0-6253-4dac-852a-5e95c4517b5b', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you create app shell in Angular?', N'Fresher', N'An App shell is a way to render a portion of your application via a route at build time. This is useful to first paint of your application that appears quickly because the browser can render static HTML and CSS without the need to initialize JavaScript. You can achieve this using Angular CLI which generates an app shell for running server-side of your app.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'323c2f73-a111-4543-a1c4-5e9697863cf9', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How do ''hidden'' and ''display: none'' differ in terms of accessibility?', N'Middle', N'The ''hidden'' attribute is a standard HTML feature that hides an element and removes it from the accessibility tree, meaning screen readers will ignore it entirely. While ''display: none'' in CSS has a similar visual effect, ''hidden'' is semantically explicit about the intent to hide content from all users. It is preferred for managing the visibility of UI components that are not currently relevant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e435eada-4e07-4e5b-aa92-5e9a41dd834f', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why is the ''Cache'' mechanism important in Next.js?', N'Middle', N'The cache mechanism stores the result of data fetches and rendered components to avoid redundant work and reduce latency. Proper configuration of caching strategies ensures that the application remains fast while maintaining data consistency across user sessions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9cb5a5d5-ef37-4361-9f7e-5e9a778e4d3e', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of the ''listen'' method in Express?', N'Intern', N'The listen method is used to start the Express server and make it listen for incoming connections on a specific port. It binds the application to the network interface, allowing it to begin accepting HTTP requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd758ea34-473e-4c9b-8c58-5ea13b487b33', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart support single inheritance versus multiple inheritance?', N'Junior', N'Dart supports single class inheritance, meaning a class can only extend one parent class. To achieve functionality similar to multiple inheritance, developers use Mixins or implement multiple interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c79597ea-fa2b-42fd-8e2c-5ea2060e15c5', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is it important to initialize variables in C?', N'Junior', N'In C, local variables are not automatically initialized to zero and will contain whatever arbitrary data happened to be in that memory location previously. Using an uninitialized variable leads to undefined behavior, as the program will process unpredictable garbage values. Always assigning an initial value ensures consistency and stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45ff30a0-5aba-45db-8f63-5ea603fcbc77', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'When should you prefer embedding over referencing in MongoDB document design?', N'Middle', N'Embedding should be used for data that is frequently accessed together and has a ''one-to-few'' relationship. Referencing is better suited for ''one-to-many'' or ''many-to-many'' relationships, or when the related data is very large and accessed independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e265db2-8e0f-44de-a456-5ea6b03e6edf', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach debugging a problem where the cause is unknown?', N'Fresher', N'I start by isolating the issue through reproduction steps and examining logs or error messages. I then use a systematic approach, changing one variable at a time to identify the root cause rather than guessing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bbb1bbe-17f0-4c01-95e4-5ea71600dc26', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are the accessibility implications of using the ''aria-hidden'' attribute versus the ''hidden'' attribute?', N'Senior', N'The ''hidden'' attribute removes an element from both the visual layout and the accessibility tree, whereas ''aria-hidden'' only hides the element from screen readers while keeping it visually present. Using ''aria-hidden'' inappropriately can create a disconnect between visual users and assistive technology users, leading to a degraded experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b1d9144-de61-408a-95a2-5eacefeb372e', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why is Preact considered ''developer friendly''?', N'Fresher', N'Preact is considered developer-friendly because it has a small, predictable API that feels exactly like React. Developers already familiar with React can switch to Preact with almost zero learning curve while gaining significant performance benefits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6e4a250-9cb3-4f17-8161-5ead02934eb0', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s ''Actor'' model prevent data races compared to traditional thread-locking mechanisms?', N'Senior', N'Actors provide isolation by ensuring that their internal state can only be accessed sequentially through an asynchronous interface, effectively serializing access to the data. This avoids the manual complexity of managing locks or mutexes and prevents common concurrency bugs like priority inversion or race conditions by design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b8507fe-fe94-46d9-836d-5eaf6c2bb70e', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the implications of ''Name Mangling'' in C++ for cross-language interoperability?', N'Senior', N'Name mangling is the process of encoding type information into function names to support function overloading, which varies between compilers. Because there is no universal standard for mangling, linking code compiled with different compilers or languages requires the use of ''extern C'' blocks to suppress mangling and provide a stable C-compatible interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6067f228-e811-4dc4-9700-5eb122b5603a', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the primary trade-offs when choosing between embedding and referencing in MongoDB data modeling?', N'Middle', N'Embedding provides high read performance by retrieving all related data in a single operation and avoids complex joins, but it can lead to document size limits and data duplication. Referencing allows for better data normalization and prevents document growth, but it requires multiple queries to fetch related data and shifts the burden of data integrity to the application layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d426132-d80b-4545-8d24-5eb6211df62d', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Explain the role of the ASGI protocol in FastAPI''s capability to handle WebSocket connections.', N'Senior', N'ASGI allows for long-lived connections and asynchronous communication, which are requirements for WebSockets. FastAPI leverages this protocol to manage bi-directional event streams, allowing the server to push updates to clients independently of standard HTTP request-response patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58c544ec-18a2-44aa-83b8-5eb656a6266d', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What are the trade-offs of using asynchronous messaging queues compared to synchronous REST API calls?', N'Middle', N'Asynchronous messaging improves system decoupling and resilience by allowing services to process requests at their own pace, which helps during traffic spikes. However, it introduces complexity in error handling, message ordering, and achieving eventual consistency compared to the direct, immediate feedback loop of synchronous REST calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04d089e1-c2a6-4f1a-9387-5eb7f9ef9906', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web manage logging?', N'Junior', N'Actix-web integrates with the standard Rust logging facade. By using the Logger middleware, you can automatically log details about every incoming request, including the HTTP method, path, status code, and processing duration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
