INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b806cc2-06cc-4b55-af8a-5ebbb7d0634e', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is a ''gem'' in the Ruby ecosystem?', N'Junior', N'A gem is a self-contained package of Ruby code that provides specific functionality, such as a library or framework. Gems are managed by RubyGems and allow developers to easily share and reuse code across projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'190895d1-48bd-4828-8d29-5ebd87faed13', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Does jQuery improve accessibility in modern web applications?', N'Middle', N'jQuery does not inherently improve accessibility; in some cases, it can hinder it if developers use it to create non-semantic UI components that lack proper ARIA roles. Accessibility is primarily determined by HTML structure and browser capabilities, not the library used to manipulate the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd35aa3a7-eb2a-4e1e-ba5d-5ebe3c4224d5', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is letter-spacing and word-spacing?', N'Intern', N'- letter-spacing: Controls the space between individual characters (tracking). - word-spacing: Controls the space between words. Both accept length values (px, em, rem) and can be negative. Use cases: letter-spacing is often used for ALL-CAPS headings or logo text; word-spacing for justified text adjustments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d9b7d42-4760-4f3f-b9c4-5ebe4471e1ba', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is meant by ''Middleware'' in Actix-web?', N'Intern', N'Middleware consists of components that sit between the incoming request and the final handler. They can perform tasks like logging, authentication, or modifying requests and responses before they reach the destination.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c13f634d-4ac1-4f7d-ba2e-5ebe884e5f94', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What happens if a handler function returns an error in Actix-web?', N'Fresher', N'If a handler returns a type that implements the ResponseError trait, Actix-web automatically converts that error into a valid HTTP error response. This ensures that the client receives a structured response instead of the server crashing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5cbdc09-b39b-45a7-aaee-5ebe8e0bbb0f', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the primary benefit of Remix''s ''Error Boundaries'' in a production environment?', N'Senior', N'Error Boundaries allow developers to catch rendering or data-fetching failures at specific route levels rather than crashing the entire application. This provides a resilient user experience where only the affected portion of the UI displays an error message.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'006849de-ceec-4181-9d02-5ebebdb6e321', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between an embedded container and an external one?', N'Middle', N'An embedded container, like Tomcat in Spring Boot, is part of the application''s executable package, allowing it to run as a standalone process. An external container requires the application to be packaged as a WAR file and deployed into an existing server, which is less flexible for modern cloud-native deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5e6ce48-6373-4073-9dde-5ec35d27a722', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the significance of the Litestar ''Router''?', N'Intern', N'A router is used to group related routes into a single unit. It allows developers to organize large applications into smaller, manageable modules by grouping routes under a shared path prefix.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d8d5e2e-f36c-46c3-be64-5ec46077b643', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra achieve high availability compared to traditional RDBMS?', N'Middle', N'Cassandra is a peer-to-peer distributed system with no single point of failure. By using a decentralized architecture and configurable replication, the system remains operational even if multiple nodes go offline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9e9d4d1-0930-46f9-9e17-5ec510722e72', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono deal with cross-platform compatibility issues?', N'Middle', N'Hono avoids platform-specific APIs (like Node''s ''fs'' or ''net'' modules) unless explicitly required by a plugin. By relying on the Fetch API and standard JavaScript globals, it ensures that your application code is portable across any runtime that supports the ECMAScript standard.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5afbf28a-5378-4033-817c-5ec8e47c83d9', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the primary architectural bottleneck when updating the DOM with jQuery in a large list?', N'Senior', N'jQuery performs direct, granular DOM updates for every change, which can trigger layout shifts and style recalculations repeatedly. Modern frameworks batch these updates and use efficient diffing algorithms to minimize DOM interaction, significantly reducing the performance cost of rendering large datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'095b99ea-2cad-47b5-9066-5ec99282e301', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Why is a reverse proxy like Nginx or IIS used with Kestrel?', N'Junior', N'While Kestrel is a capable web server, a reverse proxy provides additional features like load balancing, SSL termination, and protection against certain types of attacks. It acts as a gateway to forward requests to Kestrel, adding a layer of security and stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c9dd168-bfd4-4b72-b3a5-5eca407e62ac', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Can you use Tailwind with any frontend framework?', N'Intern', N'Yes, Tailwind is framework-agnostic. It works with any web project, including React, Vue, Angular, or even plain HTML, because it operates by scanning files for class names and generating CSS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81dffdf0-3523-42ec-89b5-5ed56738bb09', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the role of the recovery middleware in Fiber?', N'Fresher', N'The recovery middleware is used to catch panics that occur during the execution of a request handler. It prevents the entire server from crashing and allows the application to return a graceful error response instead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd45317d0-149e-457e-b77f-5ed8c1b5365a', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the difference between an element and a component?', N'Intern', N'An element is a plain object describing what you want to see on the screen, while a component is a function or class that returns those elements. Elements are the ''what'' and components are the ''how'' for building UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9713ee1f-2ddb-4ad0-8423-5ed974758896', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js manage the lifecycle of a component?', N'Middle', N'Alpine.js handles the lifecycle through specific phases: initialization, reactivity setup, and teardown. It monitors the DOM for elements with Alpine directives, injects reactivity, and cleans up event listeners or observers when elements are removed from the document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f540c871-03b0-4843-b930-5ed9db579c52', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the ''default'' keyword in C# generics?', N'Middle', N'The ''default'' keyword is used to provide a default value for a generic type parameter, which could be null for reference types or zero for numeric value types. It is necessary because the compiler does not know the specific type at compile-time and cannot assume a value for initialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c34c8e14-3e84-46ee-b5aa-5eda0c3c8c27', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the purpose of an ''Air-Gapped'' network segment in a secure architecture?', N'Middle', N'An air-gapped segment is physically or logically isolated from the internet and other untrusted networks to protect highly sensitive systems. This physical separation prevents remote exploitation, ensuring that the system can only be accessed through strictly controlled, local physical interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4345af5a-f3e1-4c02-8a37-5edcffeab8c1', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Discuss the performance trade-offs of ''Flow'' versus ''SharedFlow'' and ''StateFlow''.', N'Senior', N'Cold Flows are lazy and execute per-subscriber, which is ideal for one-to-one streams. SharedFlow and StateFlow are hot, maintaining state or broadcasting events to multiple subscribers, which requires careful management of buffer sizes and backpressure to avoid memory leaks or data loss.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
