INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef47b171-4e48-4bd0-8a82-5ee2c6422bee', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s type system handle covariance and contravariance?', N'Middle', N'Dart''s generic types are generally invariant by default, which ensures type safety in collections. However, Dart supports covariance for parameters in overridden methods, allowing a subclass to override a method with a more specific type than the superclass, which can be useful for flexible API design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
