INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98b308b4-fb68-4484-a0c2-5eedb101d28b', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What are the risks of using a ''hot shard'' in a partitioned database?', N'Senior', N'A hot shard occurs when one partition receives a disproportionately high amount of traffic compared to others, leading to performance degradation or node failure. This typically happens when the partition key is poorly chosen, such as using a high-cardinality ID that is heavily queried in a specific region or time window.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5666990-ad14-40a3-8c99-5eeec277661d', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the ''will-change'' property work and what are the risks of overusing it?', N'Senior', N'The will-change property signals to the browser that an element will undergo specific changes, allowing it to promote the element to its own compositor layer for GPU acceleration. Overusing this property leads to excessive memory consumption and can actually degrade performance by preventing the browser from performing its own optimizations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
