INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03d71c87-d84c-4dcc-86aa-5ef716df5188', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you prioritize your daily tasks when everything seems urgent?', N'Fresher', N'I use a priority matrix to categorize tasks by urgency and importance. I focus on high-impact tasks that block others first, and I communicate with my manager if the workload exceeds my capacity to ensure expectations are managed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c438253-dc1c-4e74-af18-5eff5ae8ff71', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the function of the @Value annotation?', N'Fresher', N'The @Value annotation is used to inject values from properties files or environment variables directly into class fields. It provides an easy way to read configuration settings defined in application.properties or application.yml.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2276bee2-1448-4a29-8c72-5f01914baa8c', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does denormalization help with database scaling?', N'Middle', N'Denormalization reduces the need for complex joins by storing related data in a single table or by duplicating data across tables. This speeds up read operations, although it introduces challenges with data consistency and increased storage requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba52e982-87b6-493f-9144-5f0501e519f4', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle query parameters?', N'Intern', N'Hono provides methods on the Context object to retrieve query parameters from the URL string. This allows developers to easily access search filters or pagination settings sent by the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'041939d9-d67c-446b-b92b-5f05088377f2', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the difference between a bug and a feature request?', N'Intern', N'A bug is an unintended behavior that deviates from the established technical requirements or expected performance. A feature request is a proposal for a new functionality or an enhancement to existing behavior that was not previously part of the scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d528e2e-fef1-40d0-99c9-5f05fb3d71dc', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the purpose of the ''Provide'' object?', N'Junior', N'The ''Provide'' object is used to define a dependency that can be injected into route handlers. It acts as a factory that specifies how to create or retrieve the required resource whenever a handler requests it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe72baf2-40d9-4418-a8bb-5f0afbf2f3d1', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the core philosophy of Qwik regarding JavaScript execution?', N'Junior', N'Qwik is designed around the concept of resumability, which minimizes the amount of JavaScript sent to the browser. It aims to achieve near-zero initial hydration by only loading code when a user interacts with a component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8093a379-581b-4de8-902f-5f0c156182d6', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Discuss the performance implications of ''slot'' elements in Lit.', N'Senior', N'Slots enable content projection, allowing parent components to pass DOM trees into children. While powerful, overuse of complex slots can lead to performance overhead as the browser must manage the flattened tree; therefore, slots should be used primarily for layout composition rather than dynamic data-driven lists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17c7a3b9-661a-4203-9a1d-5f0ec9cb2d85', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'You are assigned a task you have never worked on before. What is your first step?', N'Junior', N'I would start by breaking the task down into smaller, manageable components and reviewing existing documentation or similar code patterns within the codebase. If I still feel stuck after an initial investigation, I would reach out to a senior team member for guidance on the best approach.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ce33cff-c08c-4aec-be0f-5f0f707aaeb8', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the architectural purpose of the ''optimization.splitChunks'' configuration?', N'Senior', N'This configuration automatically identifies shared dependencies across multiple entry points or dynamic imports and extracts them into common chunks. This prevents code duplication and maximizes browser caching, as common libraries aren''t re-downloaded when navigating between different parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b5ecae2-a4b1-4c00-b65d-5f11a34d9ac3', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the advantage of using a distributed cache like Redis in a large system?', N'Middle', N'A distributed cache provides a centralized, high-speed data store accessible by all application nodes. This ensures data consistency across the cluster and prevents individual nodes from having to maintain local caches, which is vital for scaling horizontal deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
