INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e7ed3d5-e076-4490-8278-5f26dbd37ef4', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Explain the architectural purpose of SvelteKit''s ''hooks.server.js'' and its implications for security.', N'Senior', N'Hooks act as a middleware layer that intercepts every request to the server, allowing for centralized authentication, authorization, and header manipulation. By handling these concerns globally, developers ensure consistent security policies across the application and can prevent unauthorized access before any page logic executes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68a0ac55-8393-4512-83e3-5f29696c4a5e', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How do you ensure your Symfony application remains testable?', N'Middle', N'Testability is maintained by adhering to SOLID principles, keeping services small and focused, and avoiding direct dependencies on global state or the container within business logic. Injecting dependencies through constructors and utilizing interfaces allows you to easily swap real services for mocks in your test suite.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1284e9d1-4a9c-4109-8f94-5f29929cae3f', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'When is it appropriate to use Redis as a Message Broker?', N'Middle', N'Redis is appropriate as a message broker for high-throughput, low-latency requirements where data persistence can be relaxed or managed via Streams. Its built-in data structures like Lists and Streams offer flexible ways to implement task queues compared to traditional, heavier messaging systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64aaa934-8052-4d8d-a492-5f2b6d9fb37c', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is function template?', N'Fresher', N'A function template is a blueprint for generating a family of functions that work with different data types. It allows you to write a single function that can handle various types, with the compiler generating specific versions as needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e58b0e52-80f5-4b66-9f82-5f2c3e687ff9', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why would you use ''Lazy Engines'' in a monolith-style Ember application?', N'Senior', N'Lazy Engines allow you to defer the loading of large portions of the application code until the user navigates to a specific route. This significantly reduces the initial payload size and improves time-to-interactive, which is essential for maintaining performance as the application grows in complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2397644d-b966-46f5-b696-5f2dcb12a62f', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How does database sharding help with performance, and what are the trade-offs?', N'Middle', N'Sharding improves performance by splitting a large database into smaller, more manageable pieces distributed across multiple servers, which increases write throughput. The trade-off is significantly increased complexity in application logic for querying across shards and difficulty in performing cross-shard joins or transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53d1d7c6-e445-442c-8ffb-5f307846e527', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is a ''Handler'' in Hono?', N'Intern', N'A handler is a function that processes an HTTP request and returns a response. It is the final destination for a request after it has passed through any applicable middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'752b8de8-7ea9-4a3c-93ae-5f309601695c', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the advantage of using ''Catchers'' in Rocket?', N'Middle', N'Catchers are dedicated error handlers that allow you to define custom responses for specific HTTP status codes. This keeps error handling logic separate from primary business logic and ensures consistent error messaging across the entire API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb917106-d068-4ccb-a4c9-5f30baadb0ea', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How should you handle global errors in an Echo application?', N'Middle', N'You can define a custom HTTP error handler using the Echo instance''s HTTPErrorHandler field. This centralizes error logging and response formatting, ensuring that all errors return a consistent JSON structure to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1ea227f-33d2-4b85-ae9c-5f30d7151b19', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut support multi-tenancy at the architectural level?', N'Senior', N'Micronaut provides a tenant resolver interface that allows developers to identify the current tenant from headers, cookies, or database fields. The framework can then scope beans and data sources per tenant, ensuring data isolation and configuration modularity without requiring custom interceptors for every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd0b7d04-9a70-4171-b32e-5f33d8374dab', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the architectural implications of the ''Zero-cost async/await'' implementation?', N'Senior', N'Async/await is implemented via state machines generated by the transpiler or engine. It avoids the overhead of creating new execution contexts for every step, instead using promise chaining and microtask queues to schedule continuations, which minimizes memory allocation compared to manual callback nesting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
