INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6973814d-5365-489e-b0ea-5f35cfa6769d', N'a2838158-7305-480a-b22b-4dc35776b400', N'What does a consensus algorithm like Raft or Paxos achieve?', N'Middle', N'These algorithms allow a group of distributed nodes to agree on a single state or value even if some nodes fail or communication is delayed. They are foundational for building reliable distributed systems that require strong consistency and fault tolerance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'843fe56e-afe3-4495-82cc-5f37d9a93b09', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'In the context of Cassandra''s distributed architecture, what is the role of the ''Gossip Protocol''?', N'Senior', N'The Gossip Protocol is a peer-to-peer communication mechanism used to exchange state information about the cluster, including node membership, health status, and schema versions. It enables a decentralized topology where every node is aware of the cluster state without requiring a central master node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
