INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba30d246-977f-4ca9-87f7-5f3b458026da', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'When should you use ''Global'' modules in NestJS?', N'Middle', N'Global modules are used for providers that need to be available everywhere, such as database connections or logging services. They eliminate the need to import the module into every child module, reducing boilerplate code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
