INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0dd133cb-d776-43d6-9bea-5f434b4b75ef', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the purpose of rotating secrets and keys?', N'Middle', N'Key rotation limits the window of opportunity for an attacker if a credential is compromised. By periodically replacing keys, the system ensures that old or leaked credentials eventually become useless, maintaining long-term security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39038c1d-43f2-4f8a-be90-5f4373855eed', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are some common pitfalls when doing data fetching in React?', N'Intern', N'Common pitfalls when doing data fetching in React include not handling loading and error states, leaking requests by not aborting them on unmount, ignoring race conditions when props or query params change, fetching during render (which loops), and triggering request waterfalls. In modern React (18+), use AbortController for cleanup, account for StrictMode''s intentional double-invoke in development, and prefer purpose-built libraries like TanStack Query, SWR, or RTK Query for caching and deduplication. React 19''s use() hook plus Suspense, and Server Components, are now the recommended way to read promises in components. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2af51874-2db9-4729-847f-5f458619f1ba', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit manage environment variables for different deployment stages?', N'Senior', N'SvelteKit uses dynamic and static environment variables, allowing developers to distinguish between variables available only on the server and those exposed to the client. This prevents the accidental exposure of sensitive API keys by enforcing strict boundaries at the build configuration level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
