INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'691d2dcf-ddef-4058-9221-5f590ad54ddb', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is meant by the term ''Vectorization'' in R?', N'Intern', N'Vectorization is a programming style in R where operations are applied to entire vectors at once rather than using explicit loops to process individual elements. This approach is generally more efficient and results in cleaner, more readable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc284073-d3e8-4143-baba-5f5b25ec0f4d', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are Python generators and why would you use them?', N'Junior', N'Generators are a simple way to create iterators using functions that yield values one at a time instead of returning a complete list. They are highly memory-efficient because they do not store all values in memory at once, generating them on the fly. This is particularly useful when processing large datasets or infinite sequences.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c783c3e-4e07-437e-9f76-5f5cd836aa1c', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle background tasks and what are the trade-offs regarding reliability?', N'Senior', N'FastAPI provides a background tasks utility that runs code after returning a response to the client. While convenient for lightweight operations, it is memory-resident and lacks persistence; for high-reliability systems, it is recommended to use dedicated task queues like Celery or Dramatiq to ensure durability and retries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acc64574-7ae8-44ca-9f92-5f5d360a918c', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the difference between interpolated content and innerHTML?', N'Fresher', N'The main difference between interpolated and innerHTML code is the behavior of code interpreted. Interpolated content is always escaped i.e, HTML isn''t interpreted and the browser displays angle brackets in the element''s text content. Where as in innerHTML binding, the content is interpreted i.e, the browser will convert characters as HTMLEntities. For example, the usage in template would be as below, and the property defined in a component. Even though innerHTML binding create a chance of XSS attack, Angular recognizes the value as unsafe and automatically sanitizes it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'262d750d-8cba-45ba-952f-5f5d7f43137d', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is Domain-Driven Design (DDD) and how is it related to microservices?', N'Senior', N'Domain-Driven Design (DDD) provides a model for designing and structuring microservices around specific business domains. It helps teams reduce complexity and align better with domain experts. Context Boundaries In DDD, a Bounded Context establishes clear boundaries for a domain model, focusing on a specific domain of knowledge. These boundaries help microservice teams to operate autonomously, evolving their services within a set context. Ubiquitous Language Ubiquitous Language is a shared vocabulary that unites developers and domain experts. Microservices within a Bounded Context are built around this common language, facilitating clear communication and a deeper domain understanding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da23408a-906d-40b2-8802-5f5e2bf50beb', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the advantages and disadvantages of using UUIDs as primary keys compared to auto-incrementing integers?', N'Middle', N'Auto-incrementing integers are compact and perform well with B-Tree indexes, but they can expose sensitive record counts and make merging databases difficult. UUIDs provide global uniqueness and security, but their random nature can cause index fragmentation and slower insertion performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32508084-2473-4248-b4f2-5f64a030de0d', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the trade-offs of using ''constructor injection'' versus ''field injection''.', N'Middle', N'Constructor injection is preferred because it allows for immutable components and makes testing easier by facilitating dependency mocking without requiring a reflection-based framework. Field injection is more concise but hides dependencies, makes unit testing difficult without a Spring context, and can lead to circular dependency issues that are harder to detect.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a481920-9bdc-4dfd-8851-5f66fc3cd989', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When designing a new system, how do you decide whether to prioritize horizontal or vertical scaling?', N'Middle', N'Vertical scaling is often faster to implement initially but hits hardware limits, whereas horizontal scaling provides better fault tolerance and near-infinite growth potential. I would evaluate the cost of refactoring for distributed state versus the immediate need for resource capacity to make the trade-off decision.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ddc78bf-e48a-45da-8c7e-5f6bfa6ae000', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What are the trade-offs of using a multi-leader replication strategy in a globally distributed system?', N'Senior', N'Multi-leader replication allows for lower latency writes as clients can write to the nearest data center, but it introduces complex conflict resolution requirements. It is best suited for scenarios where write availability is critical and occasional data conflicts can be resolved via application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a26b4d1-a458-4ca5-8bff-5f6c271ec9a2', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does the choice of consistency model (e.g., Eventual vs. Strong) impact the design of an application''s read-path?', N'Senior', N'Strong consistency requires the read-path to verify the latest state, often involving quorum reads or locking, which increases latency. Eventual consistency allows the read-path to return data from the nearest replica, significantly improving performance and availability, but requires the application to handle potential stale data scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfff380f-4588-4ce1-bd20-5f6e7cbc2fac', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the purpose of the ''dispatch'' method in Redux?', N'Intern', N'The dispatch method is the only way to trigger a state change in Redux. By calling dispatch with an action, you tell the store to run the reducer function to process the action and update the state accordingly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91bae1de-8de1-4a9b-83f9-5f6f7e0610e8', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the purpose of message TTL (Time To Live)?', N'Middle', N'TTL defines how long a message remains valid in the queue before it is expired and discarded. This is useful for time-sensitive data, such as real-time market updates or temporary notifications, that lose value if not processed quickly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'597a2250-7ff8-4820-80a8-5f741452659a', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript''s ''moduleResolution'' strategy influence how type packages are discovered?', N'Senior', N'The module resolution strategy determines how the compiler locates type definitions and source files based on standard node-like or bundler-specific algorithms. Choosing the correct strategy is vital for ensuring that the compiler correctly associates imported modules with their respective type declarations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f36c7fa3-5d4d-4256-bf4f-5f767ab2a4b2', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why is it often recommended to use a reverse proxy like Nginx in front of an Express application?', N'Middle', N'Express is not optimized for serving static assets, handling SSL termination, or managing complex load balancing compared to specialized web servers. A reverse proxy offloads these resource-intensive tasks, protects the application from common network-level attacks, and provides a buffer that improves overall security and scalability. This architecture allows the Express application to focus exclusively on business logic and API processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff9f9508-980e-4926-8e42-5f785dc103d0', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Compare the performance overhead of using Redis Lua scripting versus multiple individual commands.', N'Senior', N'Lua scripts reduce network round-trips by executing multiple operations atomically on the server side. However, they block the event loop for the duration of the script, meaning overly complex or long-running scripts can severely degrade overall system latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c8a6ba2-b55b-4637-9bf8-5f7bd267422c', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the role of a ''memo'' in SolidJS?', N'Fresher', N'A memo is used to optimize performance by storing the result of a computation. It prevents redundant calculations by re-executing the logic only when the source signals it depends on have actually changed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
