INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d1e09af-4989-4bc2-9a7c-5f82ec814d47', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi''s request context handling differ from standard Go practices?', N'Senior', N'Chi integrates deeply with context.Context to store route parameters, which are retrieved using a dedicated URL parameter key. This design ensures that route metadata is propagated through the request lifecycle in a type-safe manner without polluting the global request state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'012c2eb7-d0d9-4176-a50b-5f849f13ea0e', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack''s ''manifest'' file facilitate long-term caching?', N'Senior', N'The manifest tracks the mapping between chunk names and their hashed filenames. By extracting this manifest into a separate JSON file, the application can load the correct assets even when entry point hashes change, preventing cache invalidation of the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
