INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'025d9afe-46bd-4054-9825-5f85fca3e0f4', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are the performance considerations of using ''Flow'' versus ''SharedFlow'' in high-throughput reactive streams?', N'Senior', N'Flow is a cold stream that starts execution on collection, making it ideal for point-to-point data delivery with lazy initialization. SharedFlow is a hot stream that supports multiple subscribers and state broadcast, requiring careful management of buffer sizes and backpressure strategies to prevent memory leaks in high-throughput systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eacde1a0-c8bd-4bc7-b617-5f8829b67763', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is Just-in-Time (JIT) compilation in Tailwind CSS?', N'Intern', N'JIT compilation is a process where Tailwind generates CSS on-demand as you author your HTML, rather than shipping a massive pre-generated stylesheet. This allows for faster build times and ensures that only the CSS you actually use in your project is included in the final bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dfd4953-c963-419d-8b5a-5f896b28e5ad', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does the ''client:visible'' directive improve performance?', N'Middle', N'It delays the loading and hydration of a component until it enters the user''s viewport. This is an effective optimization for heavy components located at the bottom of a page, as it prevents unnecessary work until the user actually interacts with that section.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'636c5576-5168-4453-a57a-5f8d582a57a5', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is context in Svelte?', N'Fresher', N'The context API allows data to be passed from a parent component to all its descendants without passing props through every intermediate component. It is useful for providing configuration or themes to a deep component tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f6cdba0-546c-46d4-8afb-5f8ea705c8f5', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why might a developer choose Fiber over a full-featured framework like Gin?', N'Fresher', N'A developer might choose Fiber for its extreme performance, low memory footprint, and Express-like developer experience. While Gin is also popular and fast, Fiber''s reliance on Fasthttp often gives it an edge in raw throughput benchmarks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
