INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13322cc8-67d2-4fe9-9fa7-5f9427ffa7c6', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does auto-scaling improve cost efficiency in cloud environments?', N'Middle', N'Auto-scaling automatically adds or removes server instances based on real-time traffic demand. This ensures the system has enough capacity during peaks while minimizing costs during periods of low usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb59f341-2156-4ab1-abb6-5f947d09d2e3', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What does the ''app.run()'' function do?', N'Junior', N'The ''app.run()'' function starts the built-in Flask development server. It should only be used during local development, as it is not intended for the high-concurrency and security requirements of a live production environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e71d57e9-d62c-4a08-bbd7-5f94a743461d', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between database user authentication and authorization?', N'Junior', N'Authentication is the process of verifying who a user is, typically through usernames and passwords. Authorization determines what a verified user is allowed to do, such as reading, inserting, or deleting data within specific tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'941d671c-2188-479b-97b1-5f955566aa08', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do you handle different HTTP methods in Gin?', N'Intern', N'Gin provides specific functions for each standard HTTP verb like GET, POST, PUT, DELETE, and PATCH. Each method is called on the engine instance or route group to register a handler for that specific verb.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7214aedc-6472-4549-929b-5f9602aa170f', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs of using a serverless architecture compared to managed container services?', N'Middle', N'Serverless offers lower operational overhead and automatic scaling with a pay-per-use cost model, which is excellent for unpredictable workloads. Managed containers provide more control over the runtime environment, consistent performance without cold starts, and better portability across different cloud providers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45657e12-7494-4813-a2a6-5f965ec2c0ab', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the command to create a controller in Laravel?', N'Intern', N'To create a controller in Laravel, use the following artisan command: Here YourControllerName specifies the desired controller name. You can also use dot-notation for nested directories (Folder/YourControllerName). Controller Generation Options - Resource Controllers: Laravel can create resource controlles that handle typical RESTful operations for you. - API Resource Controllers: These are specifically for RESTful APIs, providing a reduced set of actions compared to full resource controllers. - Invokable Controllers: If you need a single-action controller, you can use the --invokable flag. This is useful, for example, when working with Route::resource. - Controller with Model: To combine model and controller creation, you can use -m or --model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30083aec-f632-4c49-8519-5f9814b6bb75', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why is it important to design for idempotency in database updates?', N'Middle', N'Idempotency ensures that performing the same operation multiple times produces the same result as performing it once, which is critical for fault tolerance in distributed systems. If a network failure occurs during an update, the application can safely retry the operation without causing inconsistent data states or duplicate entries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3009cb31-e780-4598-83db-5f98295954f6', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Describe how the C standard library handles locale-specific behavior in a multi-threaded application.', N'Senior', N'Standard C locales are global objects, meaning changes to the locale affect the entire process, which is inherently thread-unsafe. Modern multi-threaded applications must use thread-local storage or extended locale-specific library functions to avoid race conditions when performing locale-sensitive operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
