INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'519b328b-f1df-495a-8a97-5f9d48c78c41', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the benefit of using ''defer'' blocks in Swift?', N'Middle', N'The defer block ensures that a piece of code is executed regardless of how a scope is exited, whether through a return, a break, or an error. It is essential for resource management, such as closing files or releasing locks, ensuring that cleanup logic is always executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e130e03f-8ea4-4b8a-9bb9-5f9d65bb9717', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between 401 Unauthorized and 403 Forbidden?', N'Intern', N'401 Unauthorized means the user is not authenticated and must provide credentials to prove their identity. 403 Forbidden means the server understands the request, but the authenticated user does not have the necessary permissions to access the resource.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
