INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4ff4f0b-dc39-4e7d-802c-5fa7ce58a6ac', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are different event loops', N'Intern', N'In JavaScript, there are multiple event loops that can be used depending on the context of your application. The most common event loops are: 1. The Browser Event Loop 2. The Node.js Event Loop - Browser Event Loop: The Browser Event Loop is used in client-side JavaScript applications and is responsible for handling events that occur within the browser environment, such as user interactions (clicks, keypresses, etc.), HTTP requests, and other asynchronous actions. - The Node.js Event Loop is used in server-side JavaScript applications and is responsible for handling events that occur within the Node.js runtime environment, such as file I/O, network I/O, and other asynchronous actions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f68a167-444c-465f-8a24-5fa8a483eb54', N'954a0331-deff-4399-b588-96f39fec001d', N'How does Zone.js monkey-patching impact application scalability and what is the alternative?', N'Senior', N'Zone.js wraps asynchronous browser APIs to notify Angular when to run change detection, but it introduces overhead by tracking every microtask globally. For high-performance requirements, developers can disable Zone.js and use the ''onPush'' strategy combined with manual change detection triggers via ChangeDetectorRef to gain finer control over the execution cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'039f793a-95dd-4baa-8797-5fab29e1c276', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the difference between physical and logical data models?', N'Fresher', N'A logical data model describes the data and its relationships in a way that is independent of the database software. A physical data model describes how the data is actually stored on the storage media using the specific database management system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
