INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21bf34af-f37e-435a-ad13-5faf4ce62c0d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you determine if a feature is ''over-engineered''?', N'Intern', N'A feature is over-engineered if it is more complex, flexible, or powerful than the current or foreseeable requirements demand. It becomes a liability because it requires more time to maintain and test without providing tangible value to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ab83b70-7fd8-4f57-b51b-5fb13e7d27df', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you prepare for a deployment to production?', N'Junior', N'I ensure that all my changes have passed local tests, verify the functionality in a staging or UAT environment, and confirm that the deployment documentation is up to date. I also make sure I am available during the deployment window to monitor for any immediate issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43eec548-dc06-49eb-a906-5fb2da8898ae', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do you handle events in React?', N'Fresher', N'Handling Events in React (2026 Standards) React handles events via SyntheticBaseEvent, a cross-browser wrapper around the native browser event. This abstraction ensures consistent interface behavior across environments (DOM, React Native) and provides performance optimizations. Synthetic Events React normalizes events so that they have the same properties across all browsers. As of React 19, synthetic events are not pooled, eliminating the need to call event.persist() to access event properties asynchronously. Event Subscription - Naming Conventions: React uses camelCase for event handlers (e.g., onClick, onKeyDown) instead of the native HTML lowercase (e.g., onclick). - Function References: You pass a function as the event handler rather than a string.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95ec454a-8209-4d9d-8ffa-5fb3bf924336', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the role of CRAN in the R ecosystem?', N'Intern', N'CRAN, which stands for Comprehensive R Archive Network, is a global network of servers that store identical, up-to-date versions of R code and documentation. It serves as the primary repository for R packages, allowing users to easily download and install extensions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7726df7-f8ec-4867-8303-5fb58f7f73f0', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How should one approach versioning in a large Litestar API application?', N'Senior', N'Versioning should be handled by grouping routes under versioned paths or routers, leveraging Litestar''s modular design to keep different versions isolated. This allows for the simultaneous support of multiple API versions while keeping the codebase clean and preventing cross-contamination of logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dc4bcbb-8a94-4cae-8f87-5fb9414ecb4b', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of differential loading in CLI?', N'Intern', N'From Angular8 release onwards, the applications are built using differential loading strategy from CLI to build two separate bundles as part of your deployed application. 1. The first build contains ES2015 syntax which takes the advantage of built-in support in modern browsers, ships less polyfills, and results in a smaller bundle size. 2. The second build contains old ES5 syntax to support older browsers with all necessary polyfills. But this results in a larger bundle size. Note: This strategy is used to support multiple browsers but it only load the code that the browser needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55007069-c53b-4e11-bbc7-5fbb9142f4d5', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Describe a scenario where you would use a ''before_first_request'' hook and why it might be problematic in some deployment environments.', N'Senior', N'This hook is useful for one-time initialization, such as warming up a cache or establishing a connection to a remote service. However, it can be problematic in multi-process environments like Gunicorn, where the hook may execute once per worker process rather than once per application lifecycle, leading to redundant work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9ed639f-298c-4a56-995b-5fc146ebf64d', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB handle data consistency?', N'Junior', N'MongoDB provides tunable consistency. By default, it offers strong consistency for single-document operations, but allows developers to adjust read and write concerns to balance consistency, availability, and performance based on application needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22686e91-a25d-4faf-a09b-5fc3c1b174db', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What does it mean for Scala to be a statically typed language?', N'Intern', N'Being statically typed means that the type of every variable and expression is known at compile time. This allows the compiler to detect type-related errors before the program is executed, leading to safer and more reliable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e46964d-ada4-409c-9c60-5fc7ec452bc3', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What approach do you take when you encounter a problem that seems impossible to solve?', N'Intern', N'I break the problem down into smaller, more manageable components to see if I can solve parts of it individually. If I remain stuck, I document my progress and the specific roadblocks encountered, then seek guidance from a peer or lead to gain a fresh perspective.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'365304fd-f390-44cd-a44b-5fca1dc63c94', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How do Nuxt middleware work, and what are the common use cases?', N'Middle', N'Middleware are functions that run before a route is navigated to, allowing for intercepting and modifying the navigation process. Common use cases include enforcing authentication checks, redirecting unauthorized users, or pre-loading essential data before the page component renders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44db9cd5-a1c9-4614-bd53-5fcbdf809017', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Can R perform object-oriented programming?', N'Fresher', N'Yes, R supports object-oriented programming through several systems, most notably S3 and S4. These systems allow users to create classes and methods that define how different types of objects should behave in specific contexts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3e15012-bc87-4812-b217-5fcc4e71878e', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the purpose of preact-render-to-string?', N'Junior', N'This utility is used for server-side rendering. It allows you to convert your Preact component tree into a static HTML string that can be sent from the server to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'807704cb-f0bf-4ca9-8083-5fcdd35843db', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you implement zero timeout in modern browsers', N'Fresher', N'You can''t use setTimeout(fn, 0) to execute the code immediately due to minimum delay of greater than 0ms. But you can use window.postMessage() to achieve this behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78d49206-ea35-4fb8-b8ea-5fd01c904da2', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do you handle graceful shutdowns in a Gin application?', N'Middle', N'To perform a graceful shutdown, you should run the Gin server using the standard http.Server struct''s ListenAndServe method rather than Gin''s helper methods. This allows you to call the Shutdown method when receiving an interrupt signal, ensuring pending requests are finished before the process exits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f61b492-5dfe-4a09-94da-5fd13b2d3d75', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the primary trade-off between consistency and availability in the context of the CAP theorem during a network partition?', N'Middle', N'The CAP theorem states that a distributed system can only provide two out of three guarantees: Consistency, Availability, and Partition Tolerance. During a network partition, you must choose between consistency, where you return an error or time out to ensure all nodes have the same data, or availability, where you return the most recent available version of data even if it might be stale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe935135-3fb3-4272-b1ae-5fd30ac9540c', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How would you approach a situation where a third-party service seems to be failing?', N'Intern', N'First, check the status page of the service provider to see if they are experiencing a known outage. If not, use diagnostic tools to test the connection and verify that your own requests are formatted correctly according to the service''s API documentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4695888-035f-4d03-b914-5fd450a7e7fa', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How do you ensure secure data fetching in a Nuxt application?', N'Middle', N'Secure data fetching should be handled within server routes or server-side plugins to hide private API keys. By using the ''nitro'' runtime configuration to store credentials, you ensure that sensitive information is never exposed to the client-side bundle or browser network requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0aa45206-8da1-4432-a4f8-5fd7e11c8e52', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is a ''scoped'' style in Lit?', N'Fresher', N'A scoped style is a set of CSS rules that only applies to a specific component. Because Lit uses Shadow DOM, these styles are automatically isolated, preventing them from accidentally affecting other parts of the document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30a8d906-81a4-4fdb-8765-5fd7e7868e13', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the significance of the Fastify ''ready'' lifecycle event?', N'Middle', N'The ''ready'' event signals that all plugins have been registered and the server is initialized and ready to accept connections. Waiting for this event is crucial in testing and startup sequences to ensure that all database connections or external services are properly configured.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdee8380-0898-4433-8b16-5fdbb07af874', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are the trade-offs of using Ecto.Multi for database transactions?', N'Middle', N'Ecto.Multi allows you to group multiple database operations into a single atomic transaction. The main trade-off is the increased complexity in error handling, as you must define how to handle intermediate failures within the chain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcb5ad87-d2ee-4740-8cd6-5fdbd3a80092', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the benefit of Micronaut''s modularity?', N'Intern', N'Modularity allows developers to include only the specific features they need as separate dependencies. This keeps the final application size small and prevents unnecessary code from being included in the deployment artifact.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9f0a863-cc53-4d9a-bd14-5fe6734858e6', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of the ''createResource'' primitive?', N'Fresher', N'CreateResource is designed for handling asynchronous data fetching. It manages the loading state, error state, and the resulting data from an API call, making it easier to integrate external data into the UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fa942ce-fcc7-470a-a745-5fe6f772c9f5', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What are ''layers'' in the context of Axum?', N'Intern', N'Layers are the primary way to apply middleware in Axum. They wrap the application''s service stack, allowing for the injection of shared behavior like request logging or CORS headers across all or specific routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01a3ad90-8273-403f-9838-5fe74e23dc5f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the function of the Dart Kernel (dill) in the compilation pipeline?', N'Senior', N'The Dart Kernel is an intermediate representation that acts as a common language format across different compilation backends. By using this platform-agnostic format, Dart can decouple the frontend analysis from specific backend code generators, facilitating easier support for multiple target architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aea0646f-0d9f-4075-a85e-5fe7a971551d', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the risks of using a poorly designed partition key?', N'Middle', N'A poor partition key can lead to uneven data distribution and query performance degradation. If the key is not granular enough, it leads to massive data skew, forcing one node to do all the work while others remain idle, effectively nullifying the benefits of a distributed architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b566956-5126-4701-9e9c-5feafbe5f171', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is a ''Native Executable'' in the context of Quarkus?', N'Junior', N'A native executable is a self-contained binary file produced by GraalVM that does not require a traditional JVM to run. It contains only the application code and the necessary parts of the Java runtime, making it highly efficient for containerized deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb154d6b-3892-480c-959e-5ff426fb836c', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the benefit of using a distributed database over a single-node database?', N'Middle', N'Distributed databases offer higher fault tolerance and the ability to scale beyond the limits of a single physical machine. They are essential for applications requiring high availability and the ability to handle massive data volumes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'908a8af4-8003-4c7b-9acb-5ff61c346d11', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you manage breaking changes in an API to avoid disrupting existing clients?', N'Middle', N'Breaking changes should be handled by introducing a new version of the endpoint while maintaining the old one for a transition period. Communicating these changes well in advance via deprecation warnings allows clients sufficient time to migrate before the old version is eventually decommissioned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'861ee05a-0ab2-47f2-9608-5ffa6a3070fe', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'In a microservices mesh, how does Fastify handle upstream service timeout propagation?', N'Senior', N'You can utilize the ''onTimeout'' hook and configure global request timeouts to ensure that slow dependencies do not cause an accumulation of pending requests. This prevents cascading failures by failing fast and freeing up event loop resources for healthy requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2b4ffdd-f6f7-4ba8-be1f-5ffaa6c4aafb', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How can you debug performance issues in a Django application without external monitoring tools?', N'Senior', N'Performance issues can be profiled using tools like Django Debug Toolbar or by analyzing logs generated by the database slow query log. Additionally, one can use Python''s cProfile module to identify hotspots in the execution code and the ORM''s connection.queries attribute to inspect the exact SQL being executed per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ff86532-2e3b-439f-912a-5ffeb951ec25', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is CORS and how do you enable it in FastAPI?', N'Fresher', N'CORS (Cross-Origin Resource Sharing) is a security feature that allows a web application to request resources from a different domain. It is enabled in FastAPI by adding the ''CORSMiddleware'' to the application instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db0d7142-eb42-4b65-81fb-60041e400c40', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is Redis Cluster?', N'Intern', N'Redis Cluster is a built-in feature that allows you to automatically split your dataset among multiple Redis nodes. It provides horizontal scalability by allowing you to add more servers to handle larger amounts of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb4434ba-b104-4196-9bd1-6004c556e06a', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of the refresh interval?', N'Fresher', N'The refresh interval determines how often the changes made to an index are made visible to search. A shorter interval makes data searchable faster but requires more system resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'802f51ce-12c4-405e-a57d-6007fd938b6a', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the purpose of the ''Fail-Safe'' or ''Graceful Degradation'' design principle?', N'Middle', N'This principle ensures that a system continues to operate, perhaps with reduced functionality, even when some of its components fail. Instead of a total crash, the system gracefully disables non-essential features, keeping core functionality available for the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d4d763e-eede-4b78-88a4-6008ec7886a5', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the function of a ''Coordinator Node'' in a distributed database cluster?', N'Senior', N'The coordinator node acts as the entry point for client requests, parsing the query, routing it to the appropriate data nodes based on the shard key, and aggregating the responses. It manages the lifecycle of the request, including handling retries and coordinating consensus or consistency checks before returning the final result.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ede96c1-0142-4962-a949-60091089be30', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the primary difference between horizontal and vertical scaling for databases?', N'Middle', N'Vertical scaling involves increasing the capacity of a single server by adding more CPU, RAM, or storage. Horizontal scaling involves adding more servers to the system and distributing the data or load across them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7856287-a0ee-43ab-9720-600a5a42bc43', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the advantage of using interfaces in object-oriented design?', N'Fresher', N'Interfaces define a contract that classes must follow, allowing for polymorphism and better testability. They allow you to swap implementations without changing the code that consumes those implementations, promoting flexibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05cc1cd3-917b-4ab5-9b27-600a97b3da55', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is a ''service'' in the context of Axum?', N'Fresher', N'A service is an abstraction that takes a request and returns a future that resolves to a response. Axum routes are essentially services, and all middleware and handlers are designed to comply with this abstraction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c223507c-6a1f-4182-887a-600ac8f16169', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Does every NoSQL database support ACID transactions?', N'Intern', N'No, many NoSQL databases were designed for scalability and performance over traditional ACID compliance. While many modern NoSQL databases have added support for ACID transactions, some still offer only eventual consistency or single-record atomicity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8daa007-43c1-4d2d-8e3e-600d48fccfc1', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the significance of the ''response_model'' parameter in FastAPI?', N'Middle', N'The ''response_model'' parameter defines the schema used for the outgoing response, allowing FastAPI to automatically filter, validate, and serialize the returned data. This ensures that internal database models are not leaked to the client and that the response matches the API contract.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db153db8-1776-4121-a63e-600eff4c5282', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Explain the significance of the ''heap'' versus ''stack'' allocation in Go''s escape analysis.', N'Senior', N'Escape analysis determines if a variable''s lifetime extends beyond its function scope; if it does, the compiler allocates it on the heap. Minimizing heap allocations is critical for performance, as heap objects must be managed by the GC, whereas stack allocations are automatically reclaimed upon function return.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5a686f5-3567-4300-bfa0-600f09f65fd8', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is meant by vectorized operations in R?', N'Fresher', N'Vectorized operations allow R to perform calculations on entire vectors at once without requiring explicit loops. This makes code more concise and significantly improves computational efficiency by pushing the iteration to low-level compiled code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e061d51c-61f2-48ac-954a-600f3487e264', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the architectural trade-offs between using Scala''s ''Future'' versus ''ZIO'' or ''Cats Effect'' fibers.', N'Senior', N'Scala''s standard Future is eager and non-cancellable, creating a tight coupling between the execution context and the task, which can lead to thread starvation under load. ZIO and Cats Effect implement lightweight fiber-based concurrency, which provides cooperative multitasking, explicit resource management, and fine-grained cancellation support. This architecture significantly improves scalability and resilience by decoupling the logical process from underlying thread pool limitations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17ef50c7-5ef3-4965-8716-601211aa4068', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you adjust your project plans when you realize your team is suffering from burnout?', N'Senior', N'I immediately reduce the workload by cutting non-essential scope and pausing new initiatives to allow the team time to recover. I also review our processes to eliminate friction and ensure that the team is not being subjected to unrealistic, high-pressure deadlines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'459f22b9-b94b-4435-83e6-6013ff636589', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Why is it generally recommended to use an application factory pattern in Flask projects?', N'Middle', N'The application factory allows for the creation of multiple instances of an app with different configurations, which is essential for testing and running multiple environments. It avoids global state issues and ensures that extensions are properly initialized only when the app is created.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
