INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70145eac-bc05-4611-bc07-601a1afe6690', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Discuss the trade-offs of enabling ''Compression'' at the storage engine level.', N'Senior', N'Compression reduces disk footprint and improves I/O performance by transferring fewer bytes from storage to memory. However, it increases CPU utilization as the system must compress data on write and decompress it on read, which may be a bottleneck for CPU-bound applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
