INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61f0d11a-ffff-4601-9050-601fd34e4113', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Explain the concept of ''loaders'' as a transformation pipeline.', N'Senior', N'Loaders function as a chain of processors that take a source file as input and transform it into a format Webpack understands, such as JavaScript. They are executed from right to left or bottom to top, allowing for complex orchestration where the output of one loader serves as the input to the next.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c23c235-1791-431a-ad77-60201533eb7b', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you ensure data integrity during a disaster recovery scenario?', N'Senior', N'I would implement cross-region asynchronous data replication and maintain automated, immutable backups with regular restoration drills. The recovery point objective and recovery time objective should be clearly defined, with automated failover procedures that verify data consistency before traffic is routed to the standby region.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
