INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6de8f49-a4e3-4263-81ef-6030e0b217da', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is a dev service in Quarkus?', N'Intern', N'Dev services are automatically provisioned containers, such as databases or message brokers, that start up when the application is running in Dev Mode. They eliminate the need for developers to manually install and configure external infrastructure locally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd33a235b-9720-49ed-9424-6031eb77c029', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a refresh operation in Elasticsearch?', N'Intern', N'A refresh operation makes the changes made to an index available for search. By default, Elasticsearch performs this automatically every second, which is why it is considered a near real-time system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dac0a10-0e55-4648-9d15-603c0ff25534', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the role of the ''transient'' keyword in Java?', N'Middle', N'The transient keyword marks a member variable to be ignored during the default serialization process. This is useful for fields that contain sensitive data, derived values that can be recomputed, or objects that are not serializable. When the object is deserialized, these fields will be initialized to their default values, such as null or zero.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bf71791-ed1f-4de3-a3cb-603e48ab337d', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Describe the function of the ''Cake Pattern'' and why it has fallen out of favor.', N'Senior', N'The Cake Pattern uses self-types and trait composition to inject dependencies at compile-time, creating a modular architecture. It is often criticized for being overly complex, difficult to refactor, and prone to issues with circular dependencies, leading many to prefer implicit-based dependency injection or reader monads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cdda59a-affa-474c-af08-603ef4f5f0b8', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle asynchronous operations in route handlers, and what happens if an error is not caught?', N'Middle', N'Express handles asynchronous operations through callbacks or promises. If an error in an async function is not explicitly caught and passed to the next function, the process may experience an unhandled promise rejection, which can lead to unpredictable application states or crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74f10b8a-0fa5-4ab2-9979-604006b37381', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the advantage of using ''Externalized Configuration'' in Spring Boot for containerized environments?', N'Senior', N'Externalized configuration allows the same application artifact to be deployed across different environments (dev, staging, prod) without modification. It enables the injection of configuration via environment variables, system properties, or config servers, which aligns with the Twelve-Factor App methodology for cloud-native applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9bfbfbb-2f7d-4c13-a356-60413eb36c03', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is struct padding necessary in C?', N'Middle', N'Struct padding is used to align data members in memory according to the CPU''s architecture requirements, as accessing unaligned data can be slower or even cause hardware exceptions. The compiler inserts hidden bytes between members to ensure each field starts at an address that is a multiple of its size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b1981d7-c189-491d-9c48-6042308ece84', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the purpose of the ''comma, ok'' idiom when interacting with maps and type assertions?', N'Middle', N'The idiom provides a safe way to distinguish between a zero-value result and the actual absence of a key or failed type conversion. It prevents logic errors by allowing the caller to explicitly check if an operation was successful before relying on the returned value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1b4f863-b3ac-4258-87df-60456a2b882f', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does the Qwik optimizer handle lexical scoping when splitting code?', N'Senior', N'The optimizer performs static analysis to detect variables captured by functions marked with $. It automatically moves these variables into a persistent store, ensuring they are accessible when the function is lazily loaded from a different chunk later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64728a28-a1b2-4e73-8cec-604739642ebd', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the maximum size of an individual item in DynamoDB?', N'Junior', N'The maximum size for an individual item in DynamoDB is 400 KB. This includes the attribute names and values, so large binary data or text should be stored in Amazon S3 with a reference link in the table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0c1fe57-f671-4c2a-ace4-6047e0c9349f', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono''s approach to error handling differ from standard Node.js frameworks?', N'Middle', N'Hono provides a centralized ''onError'' handler that catches exceptions globally. This allows for consistent error responses and logging across the entire application without needing repetitive try-catch blocks in every route handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dec858c8-279e-4781-bb59-604a10053830', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the common benefits of using NoSQL?', N'Fresher', N'The primary benefits include flexibility in data modeling, high scalability, improved performance for large datasets, and the ability to handle various data formats easily. It also reduces development time due to the lack of strict schema management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'451b0bfa-9a79-4690-9ffb-604d9c937297', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the ''EXPLAIN'' statement used for?', N'Middle', N'The EXPLAIN statement provides a breakdown of how the MySQL optimizer intends to execute a specific query. It shows information such as the join order, which indexes are being used, and the number of rows the engine expects to examine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02edead5-59fe-4f5c-ac70-604fc73dd27f', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What does it mean for an API to be stateless?', N'Junior', N'A stateless API means that the server does not store any client context or session state between requests. Every request from the client must contain all the information necessary for the server to understand and process that request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'686e6a9e-c9b6-470e-8dad-60544ae3fe50', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the impact of heavy client-side plugins on the Nuxt startup sequence?', N'Senior', N'Plugins are executed before the application mounts, meaning heavy plugins can delay the initial paint and increase the time to interactive. They should be used sparingly and optimized for async execution where possible to prevent blocking the main thread during the hydration phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eca670c8-a853-421f-8fe0-605506ca0640', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Explain the trade-offs of using ''Box<dyn Trait>'' versus generic trait bounds.', N'Senior', N'Using ''Box '' employs dynamic dispatch via vtables, which introduces a runtime performance overhead and prevents monomorphization. Generic bounds use static dispatch, which allows the compiler to inline code and optimize based on concrete types, though it can lead to increased binary size due to code bloat.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
