INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cfe2e75-9427-4cb2-a070-60606e03470e', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Describe the trade-offs of using Flask''s built-in development server versus a production-grade WSGI server like Gunicorn or uWSGI.', N'Senior', N'The built-in server is single-threaded and lacks the robust security and concurrency features required for production environments. Production WSGI servers provide process management, support for multiple worker types, and better handling of slow clients, which are critical for maintaining application stability and throughput under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eca5f98b-ced7-4301-9a21-6060ad57f8e3', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB handle schema evolution?', N'Middle', N'MongoDB is schema-flexible, meaning it does not enforce a strict structure on documents within a collection. This allows developers to add new fields or change document structures on the fly without performing expensive database migrations or downtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c02a089d-e6fc-49e0-aa14-606361d18e04', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach a task that is outside of your current skill set?', N'Junior', N'I view it as a professional development opportunity and start by researching the core concepts and best practices associated with the task. I break the work into small, manageable parts to minimize risk and allow for iterative progress. I also proactively ask for guidance or resources from senior members to ensure I am heading in the right direction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7d37a37-e724-4382-8481-6065d3da69cc', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS manage server-side rendering (SSR) compared to client-side?', N'Middle', N'On the server, SolidJS renders components to an HTML string immediately. On the client, it ''hydrates'' this static HTML by attaching event listeners and reactivity to the existing DOM nodes, ensuring the application becomes interactive without re-rendering everything from scratch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fec18707-99f1-439b-824c-6066977d142a', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the advantage of using ''Data Transfer Objects'' (DTOs) or ''Changesets'' in Phoenix over raw database models?', N'Senior', N'Changesets provide a strict, functional layer for data validation and casting that is decoupled from the raw database schema. This separation ensures that only valid, sanitized data reaches the database, providing protection against mass assignment vulnerabilities and business logic errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70fa9409-1502-4e3c-b9c7-6067089fb5e5', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the ''Undo Log'' and why is it necessary?', N'Middle', N'The undo log contains old versions of data, which are used to roll back transactions if needed. It is also a core component of MVCC, enabling consistent reads by providing older versions of rows to transactions that started before a modification occurred.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
