INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1831a2e-c98f-427d-ab22-60681e7f3366', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you balance learning new technologies with completing your assigned tasks?', N'Junior', N'I dedicate a portion of my time to learning by exploring new concepts that are relevant to my current projects. I prioritize finishing my assigned tasks first and view learning as a way to improve the quality and efficiency of those tasks in the future.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50e8efbf-448b-4582-8ce2-607050ee85f6', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a trigger in MySQL?', N'Intern', N'A trigger is a set of instructions that automatically execute when a specific event, such as an insert, update, or delete, occurs on a table. It is used to maintain logs, enforce complex business rules, or update related data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
