INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9316aa35-ad0b-4a67-94e6-60735b60bc42', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are the risks of using ''request.state'' for data storage?', N'Senior', N'The ''request.state'' object is meant for ephemeral storage during the request-response lifecycle. Storing large objects or sensitive information here is risky as it can lead to memory leaks if not cleared and offers no type safety, making it a poor substitute for explicit parameter passing or structured dependency injection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4f4eaef-44e6-4223-b365-6075add9a5d4', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the C language handle function overloading?', N'Middle', N'C does not support function overloading. Because there is no name mangling to distinguish functions by their argument types, the linker would be unable to resolve which specific version of a function to call if multiple functions shared the same name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b99954e-b13b-4bc6-afe4-6076eb63c050', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of a Bloom filter in Cassandra''s read path?', N'Senior', N'A Bloom filter is a memory-efficient probabilistic data structure that allows Cassandra to quickly determine if a partition key exists in an SSTable. This avoids unnecessary disk I/O by skipping files that definitely do not contain the requested data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4538164f-e9fa-4325-9765-60778db09ea6', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How do you handle feature flags or conditional logic in Symfony?', N'Middle', N'Feature flags can be handled via environment variables, dedicated configuration files, or a database-backed service. By injecting a feature-flag service into your application, you can toggle behavior dynamically without modifying core business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80cca0c2-ff70-454f-b92a-607e35aeb95b', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why is Next.js considered SEO-friendly?', N'Fresher', N'Next.js is SEO-friendly because it renders content on the server or pre-generates it as static HTML. This ensures that web crawlers can easily read the page content immediately upon loading, which is more difficult with traditional client-side rendered applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acb32eca-b8a9-40bf-ac3b-607ea5c97f8a', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the benefit of using Echo over the standard Go ''net/http'' library?', N'Fresher', N'While the standard library is powerful, Echo provides a higher-level abstraction that reduces boilerplate code. It includes built-in features like easy routing, powerful middleware support, and simplified JSON serialization that would otherwise require significant custom implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'faf3ad29-3afe-4bb0-931d-607ee772a5b3', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is object-oriented programming in C++?', N'Intern', N'Object-Oriented Programming (OOP) is a programming paradigm that organizes code into reusable and self-contained units called objects. Each object groups data attributes (characteristics) and methods (behaviors) that operate on the data. The Four Pillars of OOP 1. Encapsulation: Objects hide their internal state and behavior, exposing a controlled public interface. 2. Inheritance: Defines an "is-a" relationship, allowing objects of a derived class to access attributes and behaviors of a base class. 3. Polymorphism: Enables objects to be treated as instances of their parent class while exhibiting their own behaviors. 4. Abstraction: Simplifies complex systems by focusing on high-level actions while hiding implementation details.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4dbb5f24-16b4-4bb1-b216-608208986fb2', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What does the ''x-show'' directive do?', N'Intern', N'The x-show directive toggles the visibility of an element by adding or removing the display CSS property based on a boolean expression. If the expression evaluates to true, the element is shown; otherwise, it is hidden.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd0d5817-7197-432e-9560-608293b4e84a', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Why should you avoid logging sensitive data like passwords or PII?', N'Middle', N'Logging sensitive data creates a secondary storage point that is often less protected than the primary database. If logs are compromised, attackers can easily harvest credentials or personal information, leading to widespread security breaches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
