INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'673af844-8329-4af7-bad8-6083db9f91a0', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What strategy do you use to debug a service that is ''flapping'' between healthy and unhealthy states in a cluster?', N'Senior', N'I would analyze the health check probe logs to see if the health endpoint is timing out due to occasional resource spikes or if the load balancer is misinterpreting response latency. I would also investigate if the service is failing to maintain its state or if it is being killed by the orchestrator due to failure to meet resource thresholds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d9ba522-650b-4c29-aa92-608e4d74e653', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs between using a centralized logging system versus distributed logs per service?', N'Middle', N'A centralized logging system is essential for searching and correlating logs across a microservices environment, but it introduces a single point of failure and potential data privacy concerns. Distributed logs are easier to set up and provide local access, but they make cross-service debugging nearly impossible during an incident.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
