INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1a4bd5f-9df6-471a-b7e3-60934e013e65', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain limitations of MongoDB Transactions?', N'Fresher', N'MongoDB transactions can exist only for relatively short time periods. By default, a transaction must span no more than one minute of clock time. This limitation results from the underlying MongoDB implementation. MongoDB uses MVCC, but unlike databases such as Oracle, the “older” versions of data are kept only in memory. 1. You cannot create or drop a collection inside a transaction. 2. Transactions cannot make writes to a capped collection 3. Transactions take plenty of time to execute and somehow they can slow the performance of the database. 4. Transaction size is limited to 16MB requiring one to split any that tends to exceed this size into smaller transactions. 5.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
