INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03190836-0119-4907-b9ad-60a21cd1d0d1', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why do you need a promise', N'Fresher', N'Promises are used to handle asynchronous operations, especially in languages like JavaScript, which often work with non-blocking operations such as network requests, file I/O, and timers. When an operation is asynchronous, it doesn''t immediately return a result; instead, it works in the background and provides the result later. Handling this in a clean, organized way can be difficult without a structured approach. Promises are used to: 1. Handle asynchronous operations. 2. Provide a cleaner alternative to callbacks. 3. Avoid callback hell. 4. Make code more readable and maintainable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60d5d860-8b05-4432-b80b-60a3416f3ca6', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How does a distributed cache like Redis improve system performance?', N'Middle', N'A distributed cache stores frequently accessed data in memory across multiple servers, providing extremely fast read and write speeds. By serving data from RAM rather than disk-based databases, it drastically reduces latency and database load for high-traffic applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
