INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78037c26-1351-4d5a-9133-60a3d0774ca7', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of the ''url_for'' function?', N'Intern', N'The url_for function is used to dynamically build URLs for specific functions. Using this instead of hardcoding URLs ensures that if your URL structure changes, the links in your application remain valid.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54cf984d-6e39-4266-be78-60a4960cb3a6', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the purpose of Type Guards in TypeScript.', N'Middle', N'Type guards are expressions that perform a runtime check which guarantees the type in a specific scope. They allow the compiler to narrow down the type of a variable from a broader union type to a specific one, enabling safe access to properties or methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53cc2ea3-8999-4bfc-a474-60a5b8ad0dc9', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is ''progressive enhancement'' in the context of SvelteKit form actions?', N'Middle', N'Progressive enhancement ensures that forms work even if JavaScript is disabled in the browser by utilizing standard HTML form submission. SvelteKit''s enhance action then intercepts this submission to provide a seamless, asynchronous user experience without requiring a page reload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef70c332-71cd-420a-9285-60a5e3441744', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the array mutation methods?', N'Intern', N'JavaScript array methods can be categorized into two groups: 1. Mutating methods: These are the methods that directly modify the original array. 1. Non-mutating methods: These methods return a new array without altering the original one. There are 9 methods in total that mutate the arrays, 1. push: Adds one or more elements to the end of the array and returns the new length. 2. pop: Removes the last element from the array and returns that element. 3. unshift: Adds one or more elements to the beginning of the array and returns the new length.. 4. shift: Removes the first element from the array and returns that element. 5. splice: Adds or removes elements from the array at a specific index position. 6. sort: Sorts the elements of the array in-place based on a given sorting criteria. 7.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'464d103e-4021-46fa-9ad9-60a63569f524', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Does overflow: hidden create a new block formatting context?', N'Middle', N'Yes. overflow property deals with the content if content size exceeds the allocated size for the content. You can make extra content visible, hidden, scroll or auto (viewport default behavior).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77f646a8-5877-4920-8e04-60a74ffa1a0e', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When choosing between a managed database service and self-hosting a database, what is the primary consideration?', N'Junior', N'Managed services handle backups, patching, and scaling, which saves significant operational time for the team. Self-hosting provides full control and can be cheaper at extreme scales, but it requires dedicated expertise to maintain high availability and data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'537a84dd-b32a-4c31-986a-60a90c633bdb', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is it important to use environment variables for sensitive configuration?', N'Middle', N'Environment variables prevent sensitive data like API keys, database credentials, and secret tokens from being hardcoded in the source code. This improves security, allows for easier configuration changes across different environments without code modifications, and adheres to 12-factor app principles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f47680ed-14d3-4dfb-8798-60aa43ba12ae', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the role of the Spring Boot Starter dependency?', N'Intern', N'Starters are a set of convenient dependency descriptors that you can include in your application. They aggregate all the necessary dependencies for a specific technology, such as web or database support, ensuring version compatibility and reducing manual configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25510259-f768-4ee2-b086-60ac1ddea58c', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the purpose of the ''Scan'' operation, and why should it be avoided in production?', N'Senior', N'A Scan operation reads every item in a table, which is highly resource-intensive and can consume all available throughput capacity. In production environments, it is typically an anti-pattern because it does not scale well with table size and significantly increases latency and costs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1f55bdc-6226-4534-b8be-60b6bbcefafd', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you secure a public-facing API against Distributed Denial of Service (DDoS) attacks?', N'Senior', N'I would deploy a cloud-native WAF and DDoS protection service at the edge to filter volumetric traffic before it reaches my infrastructure. Internally, I would implement rate limiting, request throttling, and authentication at the API gateway layer to prevent unauthorized or excessive requests from consuming system resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c191c3a-c9f5-40e2-ba6e-60bb69aac5ea', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do Multi-Version Concurrency Control (MVCC) mechanisms impact database storage and cleanup?', N'Senior', N'MVCC maintains multiple versions of data rows to allow readers and writers to operate simultaneously without blocking. This requires a background process, such as vacuuming or garbage collection, to identify and remove obsolete row versions that are no longer visible to any active transaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
