INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95b13959-0414-4f7b-92d5-60bf7801825a', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack handle circular dependencies, and why can they cause runtime failures?', N'Senior', N'Webpack does not prevent circular dependencies during the build, but they often result in an ''undefined'' export when one module tries to access an export of another that hasn''t finished executing. This occurs because the JavaScript engine executes modules sequentially, and a circular reference creates a situation where a module is accessed before its exports are initialized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac23b6cf-deeb-4c03-8c4d-60bfd99e9509', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the role of a ''timeout'' configuration in service-to-service communication?', N'Middle', N'Timeouts prevent a service from waiting indefinitely for a response from a downstream dependency that might be hanging or overloaded. By enforcing strict timeouts, you prevent resource exhaustion on the calling service, allowing it to fail fast and maintain its own stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
