INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24e340fa-868d-4ab8-92e9-60c7c857f536', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain the ''Election Protocol'' in a replica set and the role of ''priority'' in voting.', N'Senior', N'When a primary fails, remaining nodes hold an election to select a new leader; nodes with higher priority values are more likely to win if they are caught up with the Oplog. Priority ensures that specific nodes, such as those in more performant data centers, are preferred for primary duties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de670ffe-1a20-4e6c-b5e9-60c7f7544fa8', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is your approach when a database index is not being used as expected after a schema update?', N'Senior', N'I analyze the query execution plan to understand why the optimizer is choosing a full table scan over an index seek. I check for data type mismatches, implicit casting that prevents index usage, or updated statistics that might be misleading the optimizer about the distribution of values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
