INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bc3ac44-20cd-413b-876c-60cc880898cc', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you manage configuration settings in a Flask application as it moves through environments?', N'Middle', N'You should use a class-based configuration system where a base configuration class holds common settings and subclasses override specific values for development, testing, and production. This allows you to load the appropriate configuration object based on environment variables, ensuring that sensitive data is kept out of the codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db64fb42-1c10-4f2a-88c8-60cd88e6fb83', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How would you debug a scenario where a service deployment causes an increase in 4xx errors without any changes to the application code?', N'Senior', N'I would investigate differences in the environment configuration, such as updated environment variables, dependency versions, or infrastructure-level changes like load balancer timeouts or ingress controller settings. I would also compare the current traffic profile against the previous version to see if the new deployment is failing to handle specific request headers or content types that were previously tolerated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3b6971e-862d-4fa9-a36e-60ce1a41f81b', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery handle animation?', N'Fresher', N'jQuery provides built-in animation methods to change CSS properties over a specified duration. It allows developers to create effects like fading, sliding, and custom property transitions without complex manual timing logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7da118f0-7377-4bd5-8069-60cfc8636e23', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why would you choose to use a transaction when performing multiple related database updates?', N'Fresher', N'A transaction ensures that all related operations succeed together or none of them do, which maintains data consistency. If one part of the operation fails, the database can roll back to its original state, preventing partial updates that could corrupt the data. This is essential for operations like bank transfers, where multiple steps must be atomic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98395ba6-5350-43f3-8fa6-60d04777dc0f', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is DynamoDB''s data model?', N'Junior', N'DynamoDB is a NoSQL key-value and document database. It stores data as items, which are collections of attributes, without requiring a fixed schema for every item.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26181805-7103-424d-94a8-60d0490b519a', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is it important to use header guards or pragma once in C header files?', N'Middle', N'Header files are often included multiple times through complex dependency trees, which can lead to redefinition errors for types, functions, or variables. Header guards or the pragma once directive ensure that the contents of a header file are processed only once during a single compilation unit, preventing these conflicts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88bd29de-2037-4a97-b982-60d21d9192a9', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a Deadlock?', N'Junior', N'A deadlock occurs when two or more transactions are waiting for each other to release locks, creating a circular dependency. The database must detect this and abort one of the transactions to allow the others to proceed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c58e1613-0091-4f76-ab62-60d663cfe9f6', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Explain the difference between transient, scoped, and singleton service lifetimes and the risks of captive dependencies.', N'Senior', N'Transient services are created every time they are requested, scoped services are created once per client request, and singleton services are created once for the entire application lifetime. A captive dependency occurs when a longer-lived service holds a reference to a shorter-lived service, preventing the shorter-lived service from being disposed of correctly and potentially causing memory leaks or state inconsistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e72876e0-e83b-4c60-9f47-60d8044bbda7', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does micro-segmentation enhance network security?', N'Senior', N'Micro-segmentation divides the network into granular security zones, effectively isolating individual workloads or services. This prevents attackers from moving laterally through the network if they successfully breach one part of the infrastructure, as traffic between segments is restricted by default-deny policies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1406e120-e1e5-4cc3-a20a-60d92ef461b9', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the ''Use'' method used for in Chi?', N'Fresher', N'The Use method is used to register a middleware function that will be executed for all requests processed by that specific router or group. It ensures that the middleware runs before reaching the final handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b39ab8c3-a9c1-4b27-8d6a-60daa5b88865', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you create directives using CLI?', N'Fresher', N'You can use CLI command ng generate directive to create the directive class file. It creates the source file(src/app/components/directivename.directive.ts), the respective test file .spec.ts and declare the directive class file in root module.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca630351-8808-41e1-bc92-60dbf0ae6c7b', N'4c000000-0000-0000-0000-000000000005', N'How does the CAP theorem influence the design of a globally distributed database?', N'Senior', N'The theorem forces a choice between consistency and availability during network partitions. In practice, designers often aim for ''PACELC'' trade-offs, choosing between latency and consistency even when no partition exists, typically favoring high availability for user-facing systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ced2c221-4e10-47fe-8e59-60e0f3403e39', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is Nuxt and how does it relate to Vue.js?', N'Fresher', N'Nuxt is a meta-framework built on top of Vue.js designed to make web development intuitive and powerful. It provides a structured environment and additional features like server-side rendering, static site generation, and file-based routing that are not present in core Vue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7de6efa1-9e01-40d2-910e-60e68d7ff832', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does a bulkhead pattern improve system resilience?', N'Senior', N'The bulkhead pattern isolates different parts of a system into ''compartments'' so that a failure in one service or resource pool does not propagate to others. By limiting the number of concurrent requests to a specific downstream service, the rest of the application remains functional even if that service goes down.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2db6fbc2-9424-4f19-8760-60e79e6be3aa', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are partial classes and why would you use them?', N'Middle', N'Partial classes allow the definition of a single class to be split across multiple files. They are commonly used in auto-generated code scenarios, allowing developers to extend generated files without their custom code being overwritten.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7f5d462-a315-4a10-86c8-60e7bd1a65f8', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What does ''referential transparency'' mean in Scala functional programming?', N'Middle', N'Referential transparency means that a function call can be replaced with its resulting value without changing the program''s behavior. This property is crucial for reasoning about code, testing, and applying compiler optimizations like common subexpression elimination.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff3580ad-1e39-4971-811b-60e7e9f37843', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain the concept of ''hidden classes'' in V8 and how it relates to writing performance-optimized Node.js code.', N'Senior', N'V8 creates ''hidden classes'' to keep track of object shapes to speed up property access. Modifying objects by adding or deleting properties dynamically changes their shape, forcing V8 to create new hidden classes and de-optimizing access, which can be mitigated by initializing objects with consistent structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c39a915-2205-4e27-abbf-60e9cdcace91', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'If you need to store user preferences that change frequently but don''t require complex relationships, would you choose a SQL or NoSQL database? Why?', N'Fresher', N'I would choose a NoSQL database because it offers a flexible schema that easily accommodates changing data structures. Since user preferences often don''t require complex joins or strict consistency, a document-based store allows for faster development and easier scalability for this specific use case.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efac5571-62f1-485b-bb6c-60ee7fb8f945', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Describe the impact of the ''Plug'' architecture on the request-response lifecycle.', N'Senior', N'Plug is a specification for composable modules that sit between the web server and the application, allowing for a standardized pipeline of transformations. This architecture enables developers to build modular, reusable middleware that can be easily plugged into specific routes or the entire application stack, promoting clean separation of concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19a5e037-5c6e-4ba5-b53d-60f0259e6519', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Does SolidJS use a Virtual DOM?', N'Intern', N'No, SolidJS does not use a Virtual DOM. It compiles templates into real DOM nodes and sets up fine-grained updates, which makes it significantly faster and more memory-efficient than libraries that rely on virtual diffing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0db3ae0c-83fa-40d0-8105-60f244ba2ed6', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the ''useHead'' composable used for?', N'Intern', N'The useHead composable allows you to manage the document head of your application dynamically. It is commonly used to set page titles, meta descriptions, and link tags for individual pages to improve SEO.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb0c88f8-aa78-4b57-9889-60f4d763fc14', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is an HTTP header in Actix-web?', N'Intern', N'An HTTP header is a piece of metadata included in an HTTP request or response. Actix-web provides mechanisms to inspect incoming headers or add custom headers to outgoing responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fd5b75d-e963-4460-9380-60f66fb01a6d', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you design a system to handle a high volume of write operations for analytics data?', N'Middle', N'I would implement a buffering layer using a distributed message queue like Kafka to ingest the stream of writes. This decouples the ingestion process from the database write process, allowing me to batch operations and smooth out traffic spikes without overloading the storage engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'facc967c-f224-440a-aa12-60f785c7a91c', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Explain the concept of ''progressive enhancement'' in the context of Remix.', N'Fresher', N'Progressive enhancement is a design strategy that ensures core functionality works for all users, regardless of their browser capabilities or network speed. Remix supports this by allowing forms and links to function using standard HTML features before enhancing them with JavaScript for a faster, smoother experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aba421dc-ec51-4535-b851-60f88e75f838', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the concept of ''Linearizability'' in the context of distributed systems.', N'Senior', N'Linearizability provides the illusion that the system has only one copy of the data and that every operation appears to take effect instantaneously at some point between its invocation and completion. It is a strict consistency model that is stronger than sequential consistency and is essential for systems where the order of operations must be globally visible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d185ed0-4a57-4a09-b218-60f97e4f00a2', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Does the browser run Sass files directly?', N'Intern', N'No, browsers do not understand Sass directly. Sass files must be compiled or ''transpiled'' into standard CSS files before they can be linked to an HTML page and rendered by a browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'876a2bf4-dc3a-4918-804e-60fad40df84c', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does the use of Vite in Astro impact the development workflow?', N'Senior', N'Vite provides hot module replacement and lightning-fast dev server startup, which significantly improves feedback loops. Because Vite is used for both development and production, the environment remains consistent, minimizing discrepancies between local testing and deployment builds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afeb13b5-674d-4c18-a326-60fd303267e1', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How does service mesh impact system latency and operational complexity?', N'Senior', N'A service mesh introduces additional network hops and sidecar resource consumption, which can increase overall system latency. Operationally, it simplifies service discovery, mTLS, and observability, but adds significant management overhead that often outweighs benefits unless the environment reaches a sufficient scale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'824d631c-ca16-4af0-b1a3-60fe9d5c207d', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the role of the ''Cargo'' build system in ensuring reproducible builds?', N'Senior', N'Cargo manages dependencies and build configurations through a lockfile, which records the exact versions and checksums of every dependency in the tree. This ensures that the build environment remains consistent across different machines, preventing the ''it works on my machine'' problem by guaranteeing bit-for-bit identical dependency resolution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2504766-c49d-4d40-bd88-61008d067640', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Why is it important to understand the ''load'' function''s ''fetch'' method?', N'Senior', N'The ''fetch'' provided by the ''load'' function is a special wrapper that can handle credentials and relative paths automatically, whether running on the server or the client. Using this instead of the global ''fetch'' is essential to ensure that API calls are correctly authorized and correctly routed in both environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9624bcf-f1c4-482e-8ece-61020ffbf2d4', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is it important to use ''dotenv'' in a Node.js project?', N'Junior', N'dotenv is a module that loads environment variables from a .env file into process.env. This allows developers to maintain separate configurations for different environments without hardcoding sensitive information into the version control system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f895ce67-777e-4ead-b671-6103b210a302', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot handle ''Profiles'' and why are they essential for CI/CD pipelines?', N'Senior', N'Profiles allow grouping bean definitions and configurations by environment, such as dev, test, or production. They enable the same artifact to be deployed across different environments with environment-specific settings, ensuring consistency while maintaining environmental isolation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2314d84c-3904-4792-9e67-6103e4d24483', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is it important to keep the Event Loop unblocked, and what are the consequences of blocking it?', N'Middle', N'Since Node.js runs on a single main thread, blocking the event loop with synchronous, heavy computation prevents the server from responding to any other incoming requests. This leads to increased latency, dropped connections, and an overall unresponsive application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'264ffad6-2604-49ce-aefb-61053efeadda', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do portals function at the architectural level, and why are they useful for accessibility?', N'Senior', N'Portals allow a component to render its children into a DOM node located outside the parent component''s DOM hierarchy. This is essential for modals, tooltips, and dropdowns because it enables proper z-index management and focus handling while maintaining the logical component structure in the React tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9756174-2c3e-456c-bebc-610af5f38a22', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does cache invalidation differ in a distributed system versus a single-node system?', N'Senior', N'In a single-node system, cache invalidation is straightforward due to shared memory access. In a distributed system, invalidation requires coordinated messaging, such as Pub/Sub mechanisms or distributed locks, to ensure all cache nodes remain consistent with the source of truth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48965bc5-67eb-42b4-9537-610cbb54c62d', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle constructive criticism about your problem-solving process?', N'Intern', N'I view criticism as an investment in my professional growth. I reflect on the feedback to see how I can improve my methodology and explicitly apply those lessons to my next task.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'424a1c35-6d06-4967-8ea7-6110c11dc1aa', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'When should you use useImperativeHandle?', N'Middle', N'The useImperativeHandler hook will be used in below cases: * You want to expose imperative methods from a child component - Custom input controls exposing focus, clear, or validate methods - Modal components exposing open() and close() methods - Scroll containers exposing scrollToTop() or scrollToBottom() methods * You want to hide internal implementation but provide controlled external access. * You''re building reusable component libraries (e.g., inputs, modals, form controls).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'364de401-078a-4bef-a190-611517494911', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the danger of ''analysis paralysis'' when making technical trade-offs?', N'Intern', N'Analysis paralysis occurs when you spend too much time comparing options, leading to delayed decisions and stalled progress. It is better to make a ''good enough'' decision quickly than to spend excessive time searching for the perfect one.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cec8ab5a-650d-496f-8a17-61184a6837a8', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the difference between ''def'' and ''val'' for functions?', N'Fresher', N'A ''def'' defines a method that is evaluated every time it is called. A ''val'' defines a function as a value, meaning it is evaluated once upon assignment and then treated as an immutable object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45162ee5-8f67-460d-bc16-611a84db2862', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When building a solution, why is it better to start simple?', N'Intern', N'Starting simple allows you to confirm that the basic logic works before adding layers of complexity. It is much easier to improve a working basic model than to troubleshoot a complex system that is failing from the start.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e5ca50e-d368-4625-891d-611ef083dc13', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are SvelteKit adapters and why are they necessary?', N'Fresher', N'Adapters are plugins that transform your built SvelteKit application into a format compatible with specific deployment environments. They allow the framework to remain platform-agnostic, enabling you to deploy to services like Vercel, Netlify, or a standard Node.js server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80cf7dfc-ec27-40b1-976f-612104b021dd', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of the untrack function?', N'Intern', N'The untrack function allows you to read a signal without creating a reactive dependency. This is useful when you want to use a value inside an effect or component without triggering a re-run when that specific value changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebdc3455-9ff6-4e01-809b-61264e87613c', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is an App in a Django project?', N'Junior', N'An App is a modular, self-contained package of code that performs a specific function within a project, such as a blog or a user management system. This structure makes it easier to keep code organized and allows apps to be reused across different projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65ffc7b1-d4e4-46dd-b658-6127bb483741', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is a Layer in Axum?', N'Intern', N'A layer is a pattern provided by the Tower library that allows you to wrap a service with additional functionality. In Axum, layers are used to apply middleware globally or to specific groups of routes within a router.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d7624e3-33d9-4fc0-8a98-61293065a882', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery’s approach to global scope pollution affect the modularity of a modern frontend architecture?', N'Senior', N'jQuery historically relies on attaching itself to the global ''window'' object, which makes it harder to manage dependencies and avoid side effects. Modern architectures prefer isolated, module-scoped code that is imported explicitly, ensuring better predictability and easier dependency tracking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3baa19ba-5ac5-4437-84e5-612a5d0010f5', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is a Vite plugin and how does it extend functionality?', N'Middle', N'A Vite plugin is a JavaScript object that hooks into the Vite build pipeline during specific stages. Plugins can modify how files are loaded, transform code, or integrate with other tools like frameworks, linters, or UI libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54b48b9a-cff7-437e-9d35-612cb4c79752', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the purpose of the useActionData hook?', N'Junior', N'The useActionData hook provides access to the data returned by the action function after a form submission. It is commonly used to display validation errors or success messages back to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e346a46-f14a-491a-82d1-612efdc50106', N'075b8862-431c-4678-9767-f55359758a4a', N'Why is it dangerous to perform heavy computations directly within the ''setup'' function?', N'Senior', N'The ''setup'' function runs during the component''s initialization phase; heavy blocking operations will delay component mounting and block the main thread. This leads to a poor user experience as the UI becomes unresponsive, requiring such logic to be moved to asynchronous tasks or offloaded to Web Workers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edae4052-c859-4744-ae91-6133999ee371', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the ''session'' object?', N'Intern', N'The session object is used to persist data across multiple HTTP requests for a specific user. It is commonly used for features like user authentication, allowing the application to remember who the user is as they navigate between different pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b5d02d0-f4a6-4f20-a6fb-61355253a62e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are tasks in event loop', N'Intern', N'A task is any javascript code/program which is scheduled to be run by the standard mechanisms such as initially starting to run a program, run an event callback, or an interval or timeout being fired. All these tasks are scheduled on a task queue. Below are the list of use cases to add tasks to the task queue, 1. When a new javascript program is executed directly from console or running by the element, the task will be added to the task queue. 2. When an event fires, the event callback added to task queue 3. When a setTimeout or setInterval is reached, the corresponding callback added to task queue', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eba87150-154f-499a-b22c-61363758bd98', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does chi handle middleware compared to the standard library''s net/http?', N'Junior', N'Chi provides a built-in middleware stack that makes it very easy to chain common functionality like logging, recovery, and authentication. Unlike the standard library, which requires manual wrapping, chi allows you to apply middleware globally or to specific groups of routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7670eb7a-ec43-4fe9-b7ec-61379ad724c5', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain the architectural trade-offs of the AdonisJS ''Service Provider'' pattern compared to standard module imports.', N'Senior', N'Service providers allow for deferred booting and lifecycle management of services, which reduces the overhead of initializing unnecessary components during the request cycle. While this adds a layer of abstraction and complexity, it ensures that expensive resources are only initialized when explicitly required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2dbcba4-97b4-4e76-9f73-6137b3826dea', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'When is it appropriate to use a PUT request vs. a PATCH request?', N'Middle', N'PUT is used for replacing an entire resource with a new representation, while PATCH is used for applying partial updates to a resource. PATCH is generally more efficient for large resources where only a single field needs to be changed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57c83208-feec-4c1a-9a78-6138335eda44', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the benefit of using ''Portal'' in SolidJS?', N'Middle', N'Portals allow you to render children into a different part of the DOM tree, outside the current component''s parent hierarchy. This is crucial for UI elements like modals, tooltips, or dropdowns that need to escape overflow or z-index constraints of their parent containers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b07d643-53e8-4ad6-ac63-613970374b24', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is CSRF protection and why is it important?', N'Junior', N'CSRF protection prevents attackers from tricking users into performing actions they did not intend to take on a web application. In Flask, this is typically handled by extensions that ensure every state-changing request includes a secure, unique token.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15d97717-5100-4fcb-9991-613a12f033e8', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the Startup class or Program.cs configuration?', N'Junior', N'These files are the entry point of the application where services are registered in the DI container and the request processing pipeline is configured. In modern ASP.NET Core versions, this configuration is often consolidated into the Program.cs file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c8a8bb6-a22f-4b7b-bb09-613a53dfc0ca', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the purpose of a CSS reset or normalize file?', N'Junior', N'Browsers have different default styles for elements, which can cause inconsistencies across platforms. Reset or normalize files strip away these defaults or standardize them to ensure the design looks consistent in every browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b87d848b-d571-4cc4-9717-613f751bb5db', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber''s routing engine handle performance compared to standard implementations?', N'Middle', N'Fiber uses a highly optimized radix tree routing algorithm, which provides faster lookups and lower memory overhead compared to linear or map-based routing. This allows the framework to process thousands of route definitions without a significant performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a9df64c-6560-46ba-b52a-6140d0ae743c', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why does Rust forbid dangling references?', N'Junior', N'Rust''s borrow checker ensures that references never outlive the data they point to. This prevents memory safety bugs where a pointer might reference memory that has already been deallocated or overwritten.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1163ce90-4882-465e-b078-61415eb8b5c4', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How do you determine if a slow query is caused by missing indexes?', N'Middle', N'You can use the EXPLAIN command to check the ''type'' and ''key'' columns; if the type is ''ALL'' and the key is ''NULL'', it indicates a full table scan. Additionally, examining the Slow Query Log helps identify queries that exceed a defined execution time threshold, which are often prime candidates for indexing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1537187-8ae2-4562-9646-6142b0042ddf', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the concept of ''event delegation'' and its performance benefits.', N'Middle', N'Event delegation involves attaching a single event listener to a parent element rather than individual listeners to multiple children. It improves memory performance by reducing the number of active event listeners and allows for dynamic handling of child elements that are added or removed after the initial load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71063626-b57f-4614-a11c-6144c8bd8e8e', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is hydration in the context of Nuxt?', N'Intern', N'Hydration is the process where client-side JavaScript attaches to the server-rendered HTML to make the page interactive. It transforms the static HTML delivered by the server into a fully functional Vue application by adding event listeners and state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76f6b596-d032-45ee-9bf9-61464a310ad0', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is an attribute in a database model?', N'Fresher', N'In a database model, an attribute is a property or characteristic of an entity. For example, if ''Employee'' is an entity, its attributes might include ''Name'', ''Date of Birth'', and ''Employee ID''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73e61a0b-a58f-4287-8565-6146c9267472', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why is the Image component in Next.js preferred over a standard HTML img tag?', N'Junior', N'The Next.js Image component automatically optimizes images by resizing them, compressing them, and serving them in modern formats like WebP. It also provides lazy loading by default, which prevents images from loading until they are about to enter the viewport.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40fb1962-0a02-409e-afd4-614a60c3aef1', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Discuss the trade-offs of using ''Database Notifications'' versus ''Redis/PubSub'' for real-time updates.', N'Senior', N'Database notifications provide persistence and easy auditing but are slower for real-time delivery due to polling or database I/O. Redis/PubSub is significantly faster for ephemeral real-time messaging but lacks built-in persistence, requiring a hybrid approach for mission-critical notifications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04d488d5-072c-4ad7-afd1-614a90adad17', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the architectural significance of Echo''s support for custom HTTP engines?', N'Senior', N'Echo allows swapping the underlying HTTP engine, which is useful for specialized use cases like high-performance networking or specific protocol support. It provides flexibility to evolve the infrastructure without needing to rewrite the application-level routing or middleware logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec08b5b8-1f62-4f83-9ab6-614b1364b4f2', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does exception safety in C++ relate to the ''noexcept'' specifier?', N'Middle', N'The ''noexcept'' specifier informs the compiler that a function will not throw exceptions, allowing for specific optimizations. If an exception is thrown from a ''noexcept'' function, the program calls ''std::terminate'', which provides a clear boundary for error handling strategy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ecb8b83-f3aa-4d89-8194-614eb8398d35', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is an ''error boundary'' in React/Next.js?', N'Intern', N'An error boundary is a component that catches JavaScript errors anywhere in its child component tree. It logs the error and displays a fallback UI instead of showing a blank screen or a broken application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79b64c0f-b485-49a7-9682-61504960dd26', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What architectural considerations should be made when using ''Module#prepend'' versus ''Module#include''?', N'Senior', N'Prepend inserts a module before the class in the lookup chain, allowing it to override class methods and call ''super'' to reach the original implementation, whereas include places the module after the class. Prepend is a powerful tool for decoration and cross-cutting concerns, but it makes the inheritance structure less intuitive and harder to predict during deep debugging sessions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37ea7460-fa0c-4510-80d0-6150e5b5d73b', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the constraints of using a Global Table versus a local table in terms of consistency?', N'Senior', N'Global Tables provide multi-region, multi-active replication using asynchronous conflict resolution based on ''last writer wins''. This means that strong consistency is not guaranteed across regions, and conflicts can lead to data overwrites. Local tables offer stronger consistency guarantees within a single region, making them safer for applications requiring strict sequential integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2e7d7b9-791a-429d-9007-6152ed0e391d', N'075b8862-431c-4678-9767-f55359758a4a', N'What is a slot in Vue?', N'Junior', N'A slot is a placeholder in a child component that allows a parent to inject custom content into the child''s template. This makes components more flexible and reusable by allowing the parent to define the structure or content of specific areas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26561590-9d08-4c0a-aff6-61531a029654', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the C# runtime implement Method Table and VTable lookups for virtual method dispatch?', N'Senior', N'When a method is called on an object, the runtime accesses the object''s method table pointer to locate the appropriate entry in the virtual method table. This constant-time lookup ensures efficient polymorphism, though it introduces a minor overhead compared to direct calls due to the necessary pointer indirection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea7fe7d9-e7de-4b7c-8899-61557b060b43', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What are the advantages of Axum over older Rust web frameworks in terms of API ergonomics?', N'Senior', N'Axum leverages modern Rust features like GATs and improved type inference to provide a more intuitive and composable API. It reduces boilerplate code significantly compared to older frameworks by providing high-level extractors that handle complex tasks like path parameter parsing and body deserialization automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25eafa3c-de36-4ec2-a206-61579d68c690', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Why is it considered a best practice to use short-lived access tokens instead of long-lived ones in API security?', N'Middle', N'Short-lived tokens minimize the window of opportunity for an attacker if a token is intercepted or leaked. By requiring frequent refreshes through a secure process, you can invalidate compromised sessions quickly without needing to revoke long-term user credentials.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
