INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fb014fa-08f6-4c85-a7d6-615c438f9bd4', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the primary risk of using optimistic locking in a high-contention distributed system?', N'Senior', N'Optimistic locking relies on version checks to detect concurrent modifications, which frequently fail in high-contention environments. This leads to high abort rates and excessive retries, causing significant latency and wasting computational resources compared to pessimistic locking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42da4d87-3b6f-47e0-ba77-615d343e6a48', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the role of ''babel-loader''?', N'Junior', N'Babel-loader allows Webpack to transpile modern JavaScript (ES6+) into older versions of JavaScript that are compatible with older browsers. It uses Babel to ensure that your application code works across all targeted browser environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de57af8d-8785-452d-b000-615dd36f7828', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does the principle of ''Immutable Infrastructure'' contribute to improved system security?', N'Senior', N'By treating infrastructure as disposable and non-modifiable, you eliminate configuration drift and make it easier to patch vulnerabilities by replacing instances rather than updating them. This prevents attackers from establishing long-term persistence in the environment, as any unauthorized changes are wiped during the next deployment cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'848e4f87-07c8-424a-9be7-615fc5419e51', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the Go compiler handle dead code elimination?', N'Middle', N'The Go linker and compiler perform tree shaking and dead code elimination to remove unused functions and variables from the final binary. This keeps the binary size minimal, which is particularly beneficial for containerized microservices and edge computing environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5dae3413-d865-4b82-8175-6162b00aa7ae', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'You are designing an API that needs to support both mobile and web clients. How do you handle versioning to ensure backward compatibility?', N'Middle', N'I would implement versioning through the URI path, such as including the major version number in the endpoint, to provide clear and explicit contract definitions. This approach allows the backend to support multiple versions simultaneously while ensuring that existing clients are not disrupted by breaking changes. I would also maintain a deprecation policy and communicate changes in advance to help clients migrate to newer versions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f600d0b4-0680-4d09-ac96-616383bf31f8', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What does the following code output?', N'Intern', N'def extendList(val, list=[]): list.append(val) return list list1 = extendList(10) list2 = extendList(123,[]) list3 = extendList(''a'') list1,list2,list3 Ans. ([10, ''a''], [123], [10, ''a'']) You''d expect the output to be something like this: ([10],[123],[''a'']) Well, this is because the list argument does not initialize to its default value ([]) every time we make a call to the function. Once we define the function, it creates a new list. Then, whenever we call it again without a list argument, it uses the same list. This is because it calculates the expressions in the default arguments when we define the function, not when we call it. Let''s revise the Basis of Python Programming', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb64d18c-1538-4524-9888-61649a583661', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the architectural impact of choosing Hono over a full-stack framework like Next.js for a backend-only service?', N'Senior', N'Hono offers a significantly smaller bundle size and faster cold-start times because it lacks the heavy client-side rendering and build-time overhead of full-stack frameworks. It is architecturally superior for lightweight APIs or microservices where memory usage and performance are critical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecf04892-3c2f-4ef8-b26f-6167d023fe34', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is ''memoization'' in the context of Redux selectors?', N'Middle', N'Memoization caches the result of a selector based on its inputs, so that the computation is only re-run if the inputs change. This is critical for performance, especially when performing expensive transformations on store data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff66169e-960e-46ea-87f1-61689d41239e', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are request headers and how are they accessed in Fiber?', N'Junior', N'Request headers contain metadata about the client or the request itself. In Fiber, they are accessed using the Get method on the context object, allowing you to retrieve specific header values by their case-insensitive key name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a9f30a4-c385-41f7-8e66-6168ff0ed1f0', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What does it mean for Svelte to be ''runtime-less''?', N'Intern', N'Being runtime-less means that after the application is compiled, the browser does not need to download a large framework library to interpret your code. The compiled output contains only the necessary logic to run your specific application, leading to smaller bundle sizes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a03f4d09-a6d7-419d-a2df-616af1c2fb2f', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the difference between a synchronous and asynchronous operation in Express?', N'Intern', N'Synchronous operations block the execution of the main thread until they complete, which can degrade performance in a server. Asynchronous operations allow the server to continue handling other requests while waiting for a task, such as a database query, to finish.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'866839fc-d20d-4907-99bc-616c64f14922', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the ''extension'' feature in Dart?', N'Intern', N'Extensions allow developers to add new functionality to existing classes without modifying the original class source code. This is useful for adding utility methods to built-in types or third-party library classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8536115f-3760-4009-9e27-616cf2af743a', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the advantages and disadvantages of using a microservices architecture with Node.js?', N'Middle', N'Microservices allow for independent scaling, technology diversity, and easier deployment cycles for specific features. The trade-offs include increased operational complexity, challenges with distributed data consistency, and the necessity of managing inter-service network communication latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b90e8559-065d-4f17-960e-616d0813abe2', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How can you optimize a Laravel application for high traffic?', N'Middle', N'Optimization involves caching configuration and routes using Artisan commands, utilizing opcache for PHP code, and offloading heavy tasks to background workers. Additionally, implementing database indexing, utilizing Redis for caching, and horizontal scaling of web servers are essential strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5eb74b97-082b-4977-8600-616d545fea18', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What considerations are important when designing for multi-tenancy in a SaaS application?', N'Senior', N'I would consider data isolation strategies, ranging from logical separation using a ''tenant_id'' column to physical separation using dedicated databases per tenant. I must also ensure resource quotas are enforced so that one tenant''s heavy workload does not impact the performance of others.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cca15c77-acaf-4f3d-a242-616d66becc8e', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does the ''Phantom Read'' anomaly differ from a ''Non-Repeatable Read''?', N'Middle', N'A non-repeatable read happens when a row is updated or deleted by another transaction between two reads of the same row. A phantom read occurs when a new row appears in a result set due to an insertion by another transaction, changing the total count of rows returned by a query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95e185c5-4ec6-4b53-8462-616da1edaf05', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Is Actix-web synchronous or asynchronous?', N'Junior', N'Actix-web is built as an asynchronous framework. Most handler functions are marked as async, allowing the server to perform non-blocking I/O operations and handle many requests concurrently on a small number of threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1302d825-dab2-47a9-ba17-616e55dc9125', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off when deciding between synchronous and asynchronous operations?', N'Fresher', N'Synchronous operations are easier to reason about and follow a linear flow, but they can block the execution thread. Asynchronous operations keep the system responsive but introduce complexity in managing state and handling errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2db5c5d8-ed1e-41ce-9888-6171bd749d6e', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Explain the challenges of managing global state in an environment that prioritizes React Server Components.', N'Senior', N'Server Components cannot hold state, meaning global state must be encapsulated within Client Components. This requires careful architectural planning to avoid ''prop drilling'' or unnecessary re-renders, often necessitating the use of Context providers or external state management libraries positioned at the leaf nodes of the component tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2207416-eb5a-4bcc-a4ce-61732702bb1a', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar manage dependency caching?', N'Middle', N'Litestar supports dependency caching by allowing a dependency to be marked as ''cached'' within the request scope. This ensures that if multiple parts of the application require the same dependency, it is only computed once, improving overall request latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25efe03e-66d7-4694-9007-61742b324225', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Why is ''volatile'' used in C#, and how does it relate to the memory model?', N'Senior', N'The volatile keyword instructs the compiler and hardware not to reorder memory operations around the marked field and ensures the most up-to-date value is read from memory. It prevents threads from using cached values, which is necessary for low-level synchronization but does not provide the full atomicity guarantees of a lock or Interlocked methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e564135a-4880-4d52-831a-6177bd30051b', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a decorator in the context of Flask?', N'Intern', N'A decorator is a Python feature used to modify the behavior of a function. In Flask, decorators like the route decorator are used to register functions as handlers for specific URL patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c40c513c-8169-4d6b-999f-6177fe7b4987', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle CSS pre-processing and why is it more efficient than manual loaders?', N'Senior', N'Vite has built-in support for CSS pre-processors like Sass or Less, automatically resolving import paths and injecting HMR support for CSS changes. By treating CSS as first-class modules, it allows for granular styling updates without requiring a full page reload or a complete re-bundling of the JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ee49a57-b8b0-4030-8889-6178e571321e', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery''s ''Deferred'' object function compared to modern JavaScript Promises?', N'Middle', N'jQuery''s Deferred object was an early implementation of asynchronous control flow before Promises were standardized. While they share similar concepts, Deferred objects are not fully compatible with modern Promise APIs and lack the error-handling standard defined in the ES6 specification.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'477c127e-fd10-44e9-93dc-61798a269c0a', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of the ''APIRouter'' class?', N'Junior', N'APIRouter allows you to group related path operations into separate modules, which helps keep the main application file clean and organized. It is essential for building scalable applications where different features are split into distinct files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bba4bd94-9751-4860-bdf4-6179959de00d', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does React''s batching mechanism differ between React 17 and React 18+?', N'Senior', N'In React 17 and below, batching only occurred within React event handlers, while asynchronous callbacks bypassed it. React 18 introduced Automatic Batching, which batches state updates regardless of their origin, significantly improving performance by reducing the number of render cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'494d5f11-f532-4a0f-89f4-617bf28112f8', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle streaming responses compared to standard SSR?', N'Senior', N'SvelteKit supports streaming by allowing the server to send the initial HTML shell immediately, followed by the actual data results as they become available. This improves the ''time to first byte'' and perceived performance, as the user sees the page layout before the full data payload is ready.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5226f747-2799-42e7-9b2c-617c6d3c816f', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the var() fallback and how does it work?', N'Intern', N'The var() function accepts an optional second argument as a fallback value, used when the referenced custom property is not defined or is invalid. Syntax: Fallbacks can themselves be var() calls, allowing chained fallbacks. Example: > Note: The fallback is not used when the variable is defined but has an invalid value. In that case the property reverts to its initial or inherited value. This is called the "guaranteed-invalid" value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b58fef9b-8400-40e1-b126-617f74313074', N'4c000000-0000-0000-0000-000000000005', N'What is the purpose of the ''Sidecar Pattern'' in service meshes?', N'Senior', N'The sidecar pattern offloads cross-cutting concerns like logging, service discovery, TLS termination, and monitoring into a separate process co-located with the application. This decouples infrastructure logic from business code, allowing for polyglot services and easier maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1d9c013-2fde-42ca-a313-617f7df9f03f', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the role of the ''context'' API in Svelte?', N'Middle', N'The context API allows data to be passed down through a component tree without the need for prop drilling. It is intended for sharing state between a parent and its deeply nested children, providing a clean way to manage dependency injection in component hierarchies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e3118a6-c1d0-4e65-8470-618117a457fb', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle error catching?', N'Junior', N'Rocket provides catchers that are functions triggered when an error occurs during request processing, such as a 404 Not Found. You define these catchers with specific status code attributes, allowing you to return custom error pages or JSON responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3367ed37-e228-4d49-9f87-61819266fc57', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle a situation where you discover a critical bug in production just before a release?', N'Fresher', N'I would immediately notify my lead or manager to discuss the severity of the bug. If the bug is critical, the best approach is to halt the release, fix the issue, and thoroughly test the patch before attempting to deploy again.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3a7e2ee-671a-4e49-a8ae-61895bee0cbf', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the different types of errors in JavaScript?', N'Intern', N'In JavaScript, there are three main types of errors: syntax errors, runtime errors, and logical errors. Syntax errors occur when the code violates the language''s grammar rules, such as missing a parenthesis. Runtime errors happen during code execution, like trying to access a property of undefined. Logical errors are mistakes in the code''s logic that lead to incorrect results but don''t throw an error. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4ff36a4-b4d7-4d45-a938-618a88af8284', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How do you define a URL parameter in a Chi route path?', N'Intern', N'URL parameters are defined by wrapping a key name in curly braces within the path string, such as /users/{userID}. Chi then parses this segment and stores it in the request context for later retrieval.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9341f6cb-6875-41b4-976d-618c07384e1c', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'When should you use ''useLayoutEffect'' instead of ''useEffect''?', N'Middle', N'useLayoutEffect runs synchronously after DOM mutations but before the browser paints the screen. It should be used only when you need to measure DOM nodes or perform manual DOM changes that must be visible to the user before the next frame.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e5e8516-d82e-4a9c-9a83-618c4b716fff', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does Python''s method resolution order (MRO) handle multiple inheritance conflicts?', N'Senior', N'Python employs the C3 Linearization algorithm to determine a deterministic order for traversing the inheritance hierarchy. This algorithm ensures monotonicity and local precedence, preventing ambiguity when a class inherits from multiple parents that share a common ancestor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'017bcc6b-8a21-49e0-bd09-618ca14db506', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is Lucid ORM in the context of AdonisJS?', N'Fresher', N'Lucid is the first-party Object-Relational Mapper provided by AdonisJS. It provides an abstraction layer over SQL databases, allowing developers to interact with database records using JavaScript objects rather than writing raw SQL queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35cc5bed-5dd8-44f8-804c-618e7e1cd965', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain NEGATIVEINFINITY in JavaScript?', N'Fresher', N'The Number.NEGATIVE_INFINITY property represents the negative Infinity value. Syntax: * Negative infinity is a number in javascript, which is derived by ''dividing negative number by zero''. * A number object needs not to be created to access this static property. * The value of negative infinity is the same as the negative value of the infinity property of the global object. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eed19b4a-d8c8-493a-804f-618f1c7ff248', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite perform code splitting?', N'Middle', N'Vite automatically performs code splitting by identifying dynamic imports in the application. It creates separate chunks for these modules, which are loaded on-demand, reducing the initial bundle size and improving performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afb4b54f-d8fe-42ab-a4af-619344aa5626', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is on-demand mode in DynamoDB?', N'Intern', N'On-demand mode is a billing option where you pay only for the read and write requests your application performs. It is ideal for unpredictable workloads where capacity planning is difficult.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7deceb78-0e54-4d96-9c47-61958c513e67', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why is it important to use virtual destructors in base classes?', N'Middle', N'If a base class pointer is used to delete a derived class object, a non-virtual destructor will only call the base class destructor, potentially causing memory leaks. A virtual destructor ensures the derived class destructor is executed first, allowing for proper cleanup of derived resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'008684fb-1a5f-4976-9c34-61969a4bb79d', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the significance of the ''body-parser'' becoming part of the Express core, and how does it relate to request handling?', N'Senior', N'Integrating body parsing into the framework streamlines the process of handling JSON and URL-encoded data, which are standard for most APIs. It ensures that the request body is available as a parsed object, though developers must still implement limits on payload sizes to prevent memory exhaustion attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b29f259-0105-4b0e-8ae2-619afbda5a11', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does an API Gateway enhance the security posture of an internal service mesh?', N'Senior', N'An API Gateway acts as the edge security enforcement point, handling SSL termination, rate limiting, and initial authentication via OAuth2/OIDC. It offloads these cross-cutting concerns from individual microservices, allowing them to focus on business logic while enforcing a consistent security perimeter before traffic enters the private network.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'580c0f44-72c2-4d5d-881b-61a052472898', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is difference between async or defer keyword in JavaScript?', N'Fresher', N'1. async Attribute The async attribute is used to indicate to the browser that the script file can be executed asynchronously. The HTML parser does not need to pause at the point it reaches the script tag to fetch and execute, the execution can happen whenever the script becomes ready after being fetched in parallel with the document parsing. * Script downloads in parallel with HTML parsing * Executes immediately when download completes (pauses HTML parsing) * No guaranteed order between multiple async scripts * Best for independent scripts (e.g., analytics, ads) 2. defer Attribute The defer attribute tells the browser not to wait for the script. Instead, the browser will continue to process the HTML, build DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8159a1f-f586-4be1-93c5-61a311c57440', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the difference between constructor and ngOnInit?', N'Fresher', N'The Constructor is a default method of the class that is executed when the class is instantiated and ensures proper initialisation of fields in the class and its subclasses. Angular, or better Dependency Injector (DI), analyses the constructor parameters and when it creates a new instance by calling new MyClass() it tries to find providers that match the types of the constructor parameters, resolves them and passes them to the constructor. ngOnInit is a life cycle hook called by Angular to indicate that Angular is done creating the component. Mostly we use ngOnInit for all the initialization/declaration and avoid stuff to work in the constructor. The constructor should only be used to initialize class members but shouldn''t do actual "work".', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3bc99e6-01d2-4a08-bc7f-61a3b8f98672', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the ''mutable'' keyword used for?', N'Fresher', N'The mutable keyword is used to allow a member variable of a const object to be modified. It is typically used for internal state that doesn''t affect the logical constness of the object, such as a mutex or a cache counter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'020c3532-2c01-4677-9be6-61a48729d1e4', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is meant by ''read-only'' properties in TypeScript?', N'Fresher', N'Read-only properties are fields that can only be assigned a value during object initialization. Once set, their values cannot be changed, which helps enforce immutability within the application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'701204e7-01ff-4696-b81f-61aabe43f172', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between shallow and deep copying in the context of Dart objects?', N'Middle', N'A shallow copy creates a new instance and copies the references of the original object''s fields, meaning nested objects are shared between the original and the copy. A deep copy recursively duplicates all nested objects, ensuring that modifications to the copy do not affect the original data structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b94d2a6-1c61-430c-a26c-61ad06f5e254', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Discuss the challenges of portability in C across different architectures.', N'Middle', N'Portability issues often arise from differences in integer sizes, byte order (endianness), and structure padding between various hardware architectures. Writing portable C code requires strict adherence to the C standard and careful handling of platform-specific features, often using conditional compilation directives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cda85711-5efe-4680-ad33-61afdab439a8', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How do you handle query parameters in Litestar?', N'Junior', N'Query parameters are handled by adding arguments to your route handler function that match the names defined in the URL. Litestar automatically parses the URL query string and converts the values into the correct Python types based on the function''s type hints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee4153f8-b20d-472b-a8cb-61b190dc5775', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is Tailwind CSS often described as ''design agnostic''?', N'Junior', N'Tailwind does not enforce a specific visual style or pre-made component aesthetic like other frameworks. It provides the tools to build any design, making it highly adaptable to unique branding requirements rather than forcing a ''Bootstrap-like'' look.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db888786-2ee9-4a26-ace0-61b1fbdcef47', N'4c000000-0000-0000-0000-000000000005', N'How does a Content Delivery Network (CDN) improve system performance?', N'Middle', N'A CDN caches static assets like images and videos on edge servers located closer to the end-user. This reduces latency and offloads traffic from the origin server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db9b28ba-1f0e-48c7-b6ac-61b692773d85', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of the Cache component?', N'Fresher', N'The Cache component provides a unified interface for storing and retrieving frequently accessed data to improve application performance. By storing expensive computations or database results in memory, the application responds faster to subsequent requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23494b47-dcfc-42ce-b6fa-61b81a165ec8', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the purpose of an abstraction layer in software architecture?', N'Middle', N'An abstraction layer separates the implementation details from the interface, allowing components to interact without knowing how the underlying system works. This improves maintainability and testability because individual parts of the system can be swapped or updated without affecting other modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9584b58b-f789-4bd2-b000-61b81cf38e69', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is an ''Exception Handler'' in AdonisJS?', N'Intern', N'The Exception Handler is a global class that catches errors occurring during the request-response cycle. It allows developers to format error responses consistently and log issues without crashing the entire server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'888c153d-d108-408c-bf87-61bc0dc497fe', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are ''peer dependencies'' in the context of Webpack bundling?', N'Middle', N'Peer dependencies define modules that your package expects the host application to provide. In Webpack, if you are building a library, you should treat these as external to ensure that the host application is not forced to include duplicate versions of the same library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f36fceb-ec0f-4f8a-b916-61bc8748c231', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Does Litestar support OpenAPI generation?', N'Intern', N'Yes, Litestar automatically generates an OpenAPI schema based on your route handlers, type hints, and DTOs. This documentation is exposed via built-in UIs like Swagger UI or Redoc without requiring manual configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d187b63-9d20-42e6-bdff-61be438192c7', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Describe the segment merging process and the performance trade-offs involved.', N'Senior', N'Segment merging is a background process that combines smaller Lucene segments into larger ones to optimize disk usage and search performance. While it reduces the number of segments to query, the process is CPU and I/O intensive, potentially causing performance spikes if not managed correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41e685ae-2e5b-4e70-bc65-61be5f663697', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is database federation?', N'Middle', N'Database federation involves splitting tables into separate databases based on functional domains, such as splitting user data, product data, and order data into distinct database instances. It is a way to scale by isolating traffic by service area.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24a6e959-e043-4116-8b34-61c04e69d3c4', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What are the trade-offs of using GraphQL over REST for microservices?', N'Senior', N'GraphQL provides a flexible query interface that reduces over-fetching and under-fetching of data by allowing clients to request exactly what they need. However, it introduces complexity in rate limiting, security, and caching compared to the standard resource-oriented approach of REST.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd120ff31-3ac7-4a5f-b5fb-61c086ab1617', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How do you optimize FastAPI for extremely low-latency requirements?', N'Senior', N'Optimization involves minimizing middleware chains, using asynchronous database drivers, avoiding global state, and utilizing connection pooling. Additionally, offloading expensive operations to external services and using optimized JSON serializers like orjson instead of the standard library can yield significant performance gains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c9aab7e-d508-4980-85fe-61c26dd7200b', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI''s middleware stack impact request processing?', N'Senior', N'Middleware in FastAPI wraps every request and response, allowing for cross-cutting concerns like CORS, compression, or request tracing. However, because middleware executes for every single request, complex or inefficient logic inside middleware can introduce significant latency, making it vital to keep such operations as lightweight as possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e020f69b-203e-4b5a-b24d-61c3919828d1', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of ''Ember Concurrency'' and why is it preferred over raw Promises for async tasks?', N'Senior', N'Ember Concurrency wraps asynchronous tasks in managed objects that handle cancellation, concurrency limiting, and state tracking (like loading or error states). It prevents common bugs like memory leaks or race conditions that occur when component state updates after a component has been destroyed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b5d773c-7c42-4360-87d5-61c3dcc354b1', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Discuss the role of Ecto''s Multi and why it is preferred over standard database transactions in complex Phoenix business logic.', N'Senior', N'Ecto.Multi provides a composable way to define a sequence of database operations that succeed or fail as a single unit. It is preferred because it separates the definition of the transaction from its execution, allows for easy error handling and logging at each step, and promotes cleaner, more modular business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c231ecec-1c03-463f-a544-61c54a457cdd', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle request validation and why is it preferred over manual checks?', N'Middle', N'AdonisJS uses dedicated Validator classes that leverage a schema-based approach to ensure input integrity before it reaches the controller. This separates business logic from data sanitization, ensures consistent error handling across the application, and provides type-safe access to the validated data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b5ac748-9f6d-4336-8bc6-61c54a617548', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When you are asked to estimate, how do you handle the pressure to give a shorter timeline than you feel is realistic?', N'Junior', N'I would explain the technical risks and the specific work involved that justifies my original estimate. I would ask the requester which parts of the scope could be reduced or simplified to meet the desired, shorter timeline without compromising quality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'426fb525-d6db-492f-8b33-61c6d61f2953', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP''s shared-nothing architecture affect state management?', N'Middle', N'Because PHP destroys all memory and state after a request finishes, it inherently prevents memory leaks from accumulating between requests. However, this requires developers to use external storage like Redis or databases to maintain session state. This design makes scaling horizontally across multiple servers much simpler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd29f4f7e-2400-4ca3-814f-61ca08f00cc9', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why is ''Cache Poisoning'' a critical security concern, and how do you prevent it in a public-facing API?', N'Senior', N'Cache poisoning happens when malicious or malformed input causes the cache to store incorrect responses, which are then served to subsequent users. Prevention involves strict input validation, normalization of request headers, and ensuring that cache keys are derived from a whitelist of safe request parameters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c61ded40-765e-4406-bc5d-61cadc3f7487', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you balance the need for comprehensive automated testing with the requirement for fast delivery cycles?', N'Middle', N'Comprehensive testing is essential for stability, but an excessive number of slow, end-to-end tests can bottleneck the CI/CD pipeline. The strategy is to prioritize a test pyramid with many fast unit tests, fewer integration tests, and a minimal number of high-value end-to-end tests to achieve a balance between confidence and speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10a81df5-c713-4709-abbb-61cbee70732e', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Does Svelte use a virtual DOM?', N'Fresher', N'No, Svelte does not use a virtual DOM. Instead, it compiles components into highly efficient imperative code that updates the real DOM directly when state changes, which eliminates the overhead of comparing virtual trees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45f6d977-64ed-4391-b8eb-61cd2ce965ee', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the CSS ''cascade''?', N'Intern', N'The cascade is the mechanism that determines which CSS rules apply to an element when multiple conflicting rules exist. It evaluates rules based on origin, specificity, and the order in which they appear in the stylesheet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1a49111-4134-4f00-a2e8-61d043b5dcdf', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is SvelteKit and how does it relate to Svelte?', N'Fresher', N'SvelteKit is a full-stack framework built on top of the Svelte compiler. While Svelte handles component-level logic and reactivity, SvelteKit provides the structure, routing, and server-side features needed to build complete web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1cfe0b4-c49d-4a06-93f9-61d21966dec4', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you manage documentation while working on a time-sensitive project?', N'Fresher', N'I treat documentation as a core part of the task rather than an afterthought. I write down key decisions and logic as I go, which helps me stay organized and avoid forgetting details. Even if documentation is brief during the active phase, capturing the ''why'' behind decisions is essential for future maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60cf0131-428c-45cd-9582-61d3b0c29dbc', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does the TypeScript compiler handle the transformation of code into a format that browsers can understand?', N'Fresher', N'Browsers cannot execute TypeScript code directly because they only understand JavaScript. The TypeScript compiler, known as tsc, performs a process called transpilation where it strips away the type annotations and converts the modern syntax into standard JavaScript. This ensures the output code is compatible with the target browser environments specified in the configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'274e18e3-9987-43e4-bf9d-61dbe9606fc8', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Are Qwik components similar to React components?', N'Junior', N'Yes, Qwik components follow a similar mental model to React components, using a declarative syntax. The main difference lies in how they are bundled and executed under the hood.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae477c14-9359-4b26-a77d-61e2e1055389', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the role of the ''app'' object in a Fiber application?', N'Intern', N'The app object is the central instance of the Fiber application. It is used to define routes, register middleware, configure settings, and ultimately start the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6936705-d4d2-4ff1-a42d-61e3a5d3b6b4', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the role of the JIT compiler''s tiered compilation strategy in the JVM.', N'Senior', N'Tiered compilation balances startup time and peak performance by using the C1 compiler to quickly generate instrumented machine code and the C2 compiler to perform aggressive optimizations on hot methods. This approach allows the JVM to identify frequently executed paths and apply heavy-duty optimizations like loop unrolling and inlining only where they provide the most benefit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2ed50bf-5aae-4209-90c8-61e476c90c18', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the benefit of caching responses at the API level?', N'Middle', N'Caching reduces the load on backend services and databases by serving frequently requested data directly from memory. This significantly decreases response latency and improves the overall scalability of the API under high traffic conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'892fb001-0179-4f59-81cc-61ea0bbb9c15', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the difference between a mixin and a composable?', N'Middle', N'Mixins are object-based, prone to naming collisions, and lack clear data sources, making them difficult to debug. Composables are function-based, use standard JavaScript imports, and provide explicit dependency management, making them the preferred modern alternative.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'889b5235-d2ff-4ac2-aa48-61ea1cd5d43f', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are request parameters and query strings in Express?', N'Fresher', N'Request parameters are named URL segments used to capture values specified at their position in the URL, usually accessed via the params object. Query strings are the part of a URL that follows a question mark, providing key-value pairs used to filter or sort data, accessible via the query object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0670d97-d06c-4245-bd24-61ebe05e514a', N'a2838158-7305-480a-b22b-4dc35776b400', N'How do Vector Clocks differ from Lamport Timestamps in tracking causality?', N'Senior', N'Lamport timestamps provide a partial ordering of events but cannot determine if two events are concurrent or causally related. Vector clocks maintain a list of counters for every node in the system, allowing the architecture to detect causality and identify concurrent operations. This makes vector clocks superior for conflict resolution in systems like Dynamo-style key-value stores.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f55077b-ae70-434e-860e-61ee7e368983', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the primary benefit of JSON-based storage?', N'Fresher', N'JSON-based storage is human-readable and maps directly to data structures in modern programming languages. This makes it intuitive for developers to serialize and deserialize data objects during application development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15faf3f4-02fa-4788-927a-61f017d99c19', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why does Tailwind CSS encourage HTML over CSS?', N'Fresher', N'It shifts the focus to HTML because it treats the markup as the source of truth for the UI. By keeping styles coupled with the structure, developers can understand and modify the component''s appearance without context-switching to a separate file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'467d0850-e515-4a64-8f68-61f15a40ed2b', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does batching messages improve performance in a high-traffic messaging system?', N'Middle', N'Batching reduces the overhead of network round-trips and disk I/O operations by grouping multiple messages into a single request. This significantly increases system throughput, though it may introduce a small amount of latency for the individual messages within the batch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f5a21e5-8691-4745-90c2-61f364dc6ddf', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How do you handle rate limiting in a FastAPI application?', N'Middle', N'Rate limiting is typically handled via custom middleware or dependency injection, often backed by a storage layer like Redis. Middleware intercepts every request before it reaches the endpoint, checking the request count against a limit to either allow or reject the traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f35da5a5-4e4f-4bf4-b684-61f4368d3378', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does Global Tables provide multi-region resilience?', N'Senior', N'Global Tables use asynchronous replication to keep data consistent across multiple AWS regions, enabling low-latency access for globally distributed users. It simplifies disaster recovery and provides a path for active-active database architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2095f05c-ee4c-4d37-9030-61f4ea90209c', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is a pull request and why is the review process important?', N'Junior', N'A pull request is a way to notify team members about changes you have made to a branch. The review process is important because it allows peers to catch bugs, ensure code quality, and share knowledge across the team.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7470579c-b275-407e-9eea-61fb9c818b93', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the purpose of a Dead Letter Queue (DLQ) in a messaging architecture?', N'Middle', N'A DLQ acts as a holding area for messages that could not be processed successfully after a predefined number of retries. It prevents problematic messages from blocking the main queue and allows developers to inspect, debug, and manually resolve failures without interrupting system flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11563ebc-d883-49d9-abae-61fde03f3db1', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What approach would you take to ensure data consistency in a system with multiple services?', N'Junior', N'I would favor eventual consistency for most distributed operations because it is easier to scale and manage. For critical operations requiring strong consistency, I would implement patterns like the Saga pattern or distributed transactions, while acknowledging the increased complexity and potential for system latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'322ef0c5-4f95-4073-80e7-61fe8a367edd', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle asynchronous requests?', N'Intern', N'Axum is fully asynchronous and runs on the Tokio runtime. It uses the Rust ''async'' and ''await'' syntax to handle concurrent requests without blocking the execution thread, allowing the application to scale efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
