INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f25b219e-1b05-4a07-b3cd-6200104052c5', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the impact of the ''inert'' attribute on accessibility and event handling?', N'Senior', N'The inert attribute effectively removes an element and its subtree from the accessibility tree and prevents user interactions such as focus and click events. This is highly effective for managing modal dialogs or off-screen navigation where you need to prevent focus trapping without manually iterating through every child element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09aec877-6b5d-46fb-bdc2-62005daba7d4', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Explain how Litestar handles streaming responses and its impact on memory usage.', N'Senior', N'Litestar supports streaming responses using asynchronous generators, which allow for transmitting large datasets without loading the entire content into server memory. This is critical for high-concurrency systems handling large file uploads or extensive report generation where memory exhaustion is a risk.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b02e1a67-da81-442b-8b8c-6200f88ca3bd', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Describe the ''Finalizer'' in C# and explain why it should be used sparingly.', N'Middle', N'A finalizer is a method called by the Garbage Collector before an object is reclaimed, primarily used to release unmanaged resources. It should be used sparingly because it delays object reclamation, increases the workload on the GC, and can cause significant performance issues if not implemented correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
