INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'948cb79f-f4b0-44e2-95a7-62194b950baf', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why are you not required to use inheritance?', N'Fresher', N'In React, it is recommended to use composition over inheritance to reuse code between components. Both Props and composition give you all the flexibility you need to customize a component’s look and behavior explicitly and safely. Whereas, If you want to reuse non-UI functionality between components, it is suggested to extract it into a separate JavaScript module. Later components import it and use that function, object, or class, without extending it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cf9b0fe-0028-4957-bbee-621bcdfb53fa', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why should you avoid using ''using namespace std;'' in header files?', N'Middle', N'Using a namespace directive in a header file forces that namespace into the global scope of every file that includes it. This leads to namespace pollution and potential name collisions, making the code fragile and difficult to maintain as the project grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5a6d9e2-55be-4519-a910-621c77ab62dc', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is memory fragmentation?', N'Intern', N'Memory fragmentation occurs when free memory is broken into small, non-contiguous blocks due to repeated allocation and deallocation. This can make it difficult to find a large enough contiguous block for new allocations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29cee0f1-88f3-4118-8269-621d035bf336', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Describe the function of the Global Environment and its role in lexical scoping.', N'Senior', N'The Global Environment serves as the top-level workspace where user-defined objects reside and acts as the entry point for lexical scoping lookups. When a symbol is not found within a function''s local frame, R traverses the enclosure chain, eventually reaching the Global Environment, which establishes the final scope before searching loaded namespaces and the base package.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a05b6498-64bd-4637-8d71-621d49127dbe', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web handle template rendering or static file serving?', N'Middle', N'Actix-web provides specialized middleware and services for static file serving and integration with template engines. These are typically configured via the ''App'' service registration, allowing for optimized delivery of assets and dynamic content generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d850106-2415-4b3c-a4b6-621d81d62ea4', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between the stack and the heap in memory management?', N'Intern', N'The stack is a region of memory used for automatic variables and function call management, where memory allocation and deallocation occur automatically. The heap is a region of memory used for dynamic allocation, where the programmer must manually request and release memory using specific functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7e546b1-ce74-4cff-a7d9-621ea4378e62', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the benefits of using a State Management library like NgRx in a large application?', N'Middle', N'NgRx provides a predictable, centralized state container that makes complex data interactions easier to debug and test. It helps manage state consistency across the application by using a unidirectional data flow with actions and reducers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8570a544-cff7-470b-a81e-6221d25e108f', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is an Embedded MongoDB Document?', N'Intern', N'An embedded, or nested, MongoDB Document is a normal document that is nested inside another document within a MongoDB collection. Embedding connected data in a single document can reduce the number of read operations required to obtain data. In general, we should structure our schema so that application receives all of its required information in a single read operation. Example: In the normalized data model, the address documents contain a reference to the patron document. Embedded documents are particularly useful when a one-to-many relationship exists between documents. In the example shown above, we see that a single customer has multiple addresses associated with him.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c7058be-d88e-4629-a0c0-622349ea1b99', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of the Django ORM?', N'Intern', N'The Object-Relational Mapper (ORM) allows developers to interact with database records using Python objects instead of raw SQL queries. It abstracts the database operations, making the code more portable and easier to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91f50e77-9b2d-4312-b90d-6224a46883be', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between ''const'' and ''#define''?', N'Fresher', N'A const variable is a read-only variable that follows scope rules and is checked by the compiler. A #define is a preprocessor macro that performs text replacement throughout the code before compilation, and it does not have a specific data type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f73a600-bd00-45c4-bb63-6227c4951af4', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How can you version your API in Fastify?', N'Junior', N'Fastify supports API versioning out of the box through route constraints. You can specify a version in the route options, and Fastify will route the request based on the version header or other configured criteria.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa8101d9-871c-4023-8a15-622b032e0bfb', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the CAP Theorem as it relates to transactions?', N'Intern', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. In the context of transactions, prioritizing strong consistency often limits availability during network partitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a52b178-08a2-4cf2-bc09-622bc8e023e5', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is routing in Fiber?', N'Intern', N'Routing is the process of mapping specific URL paths and HTTP methods to dedicated handler functions. Fiber allows developers to define these routes using various methods like GET, POST, PUT, and DELETE to determine how the application responds to client requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0565d5da-9ffb-4cc3-aec9-622cb05370cb', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What are the common scopes for beans in Micronaut?', N'Fresher', N'The most common scopes are Singleton, which creates a single instance for the entire application, and Prototype, which creates a new instance every time the bean is requested. Other scopes include Request and Session, which manage bean lifecycles based on web interaction context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
