INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6786a2a-c54c-44ce-8d39-6232776e87f3', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the cost implication of using Global Secondary Indexes?', N'Middle', N'GSIs have their own provisioned throughput settings separate from the base table. Every write to the base table that affects an item indexed by the GSI will result in additional write costs, as the index must be updated synchronously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'342bf4e3-0f7e-43aa-9316-62328d7d4ab7', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of the Micronaut ''Annotation Processor''?', N'Junior', N'The annotation processor is the engine that scans your source code during the build process to generate the necessary metadata and proxy classes. It is the key component that makes Micronaut''s compile-time dependency injection possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7423260-44e3-4c74-9499-62331a5de11c', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the concept of ''Conflict-Free Replicated Data Types'' (CRDTs) as an alternative to transactions.', N'Senior', N'CRDTs are data structures designed to be replicated across nodes such that concurrent updates are mathematically guaranteed to converge to a consistent state without complex locking or conflict resolution. They replace the need for traditional transactions in scenarios where eventual consistency is acceptable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dc5b9f3-fbf6-4ea7-96a2-62375cc69139', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you ensure a new deployment does not degrade system performance?', N'Senior', N'I employ automated canary deployments where the new version is exposed to a small subset of traffic while monitoring key performance indicators. I compare these metrics against the baseline version, and if deviations are detected, I trigger an automated rollback to minimize impact.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
