INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72207552-b32b-4475-be45-62380ca3ada5', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What are the trade-offs of using a NoSQL database compared to a relational database?', N'Middle', N'NoSQL databases offer high flexibility, easier horizontal scaling, and faster performance for unstructured or semi-structured data. However, they often sacrifice strict ACID compliance and complex join capabilities found in relational databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa226695-ca1a-40d9-8141-623c02e88c4c', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What does the ''clean'' option do in Webpack?', N'Fresher', N'The clean option, typically used within the output configuration, tells Webpack to automatically delete the contents of the output directory before generating new bundles. This ensures that old, unused files do not persist in your build folder.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
