INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e6f0cf4-0095-4446-942b-623c9ec0c409', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby handle method visibility?', N'Fresher', N'Ruby uses public, protected, and private keywords to control method access. Public methods can be called from anywhere, private methods can only be called within the class, and protected methods can be called by instances of the same class or subclasses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3ee7e78-2cb5-4d34-8908-623f53c29337', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How do replica shards contribute to both high availability and search throughput?', N'Senior', N'Replicas provide redundancy, allowing the cluster to recover if a primary shard fails or a node goes offline. Furthermore, because search requests can be distributed across primary and replica shards, adding replicas horizontally increases the total search capacity of the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
