INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'923cb2f4-d148-45b1-bb19-6246ebd6e2fb', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Explain the difference between ''controlled'' and ''uncontrolled'' components in terms of form state management.', N'Senior', N'Controlled components sync form data with React state, ensuring the source of truth is always within the component tree, which facilitates instant validation and conditional logic. Uncontrolled components rely on the DOM itself to store state, which can be more performant for large forms but harder to integrate with complex state logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
