INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e83e48d9-696b-4625-8686-624a6a070840', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the benefit of using Ecto over a traditional ORM?', N'Fresher', N'Ecto separates the concerns of data mapping and database querying, providing more explicit control over how data is processed. It avoids some of the common performance pitfalls found in traditional ORMs by being more transparent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca77c773-f3d0-4a3b-a900-624aebfd1b44', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain method overriding in Ruby.', N'Junior', N'Method overriding occurs when a subclass defines a method that already exists in its superclass. When the method is called on an instance of the subclass, the subclass''s version is executed instead of the superclass''s version.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85614818-4811-4fa7-95e5-624b1a850f81', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the benefit of Svelte''s compiler-based approach regarding bundle size?', N'Junior', N'Because Svelte compiles code away, it does not need to bundle a large framework runtime into the final output. This typically results in smaller bundle sizes and faster load times compared to frameworks that ship a virtual DOM library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ad34640-0b4e-4049-8475-624c14005c70', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Why is testing important in Django, and what is the difference between unit tests and integration tests?', N'Middle', N'Testing ensures code reliability and prevents regressions during refactoring. Unit tests focus on isolating individual functions or methods to verify logic, while integration tests verify that different components—like the ORM, views, and middleware—work together correctly in a real environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42fc5554-3798-4aae-b00f-624e7e655f17', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you sort elements in an array', N'Fresher', N'The sort() method is used to sort the elements of an array in place and returns the sorted array. The default sort order is ascending, based on the string Unicode order. The example usage would be as below, Beware: sort() is changing the original array.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a0a7bb7-57ba-4ce2-a160-6250fb3b6e12', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing a system, what is the trade-off between high availability and data consistency?', N'Junior', N'According to the CAP theorem, in the event of a network partition, you must choose between availability and consistency. Prioritizing consistency ensures all users see the same data, but might lead to service outages; prioritizing availability ensures the system remains functional, but users might encounter temporarily inconsistent information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69aa330b-048d-42f2-b4f8-62519fc53c99', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What does it mean to design for ''maintainability''?', N'Intern', N'Designing for maintainability means creating solutions that are easy to understand, modify, and extend in the future. This involves using clear structures, avoiding unnecessary complexity, and documenting the reasoning behind design choices. It ensures that future developers can work on the system without requiring a complete rewrite.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b83a87c2-0558-42ba-81ce-6251d1358704', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What does ''fault-tolerant'' mean in Phoenix?', N'Intern', N'Fault tolerance means the system is designed to handle errors and failures gracefully without crashing the entire application. Phoenix achieves this through isolated processes and supervision trees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff5fb43b-2c10-4a77-a560-6251fbc6304f', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is meant by the term ''Dependency Pre-bundling'' in Vite?', N'Intern', N'Dependency pre-bundling is a process where Vite uses esbuild to convert CommonJS or UMD dependencies into ESM format. This improves page load speed and avoids the browser having to manage hundreds of small network requests for external libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52aed0e5-6e27-4e1f-8d09-6252da061ca0', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What are the ACID properties in the context of database transactions?', N'Intern', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. Atomicity ensures a transaction is processed as a single unit, either succeeding completely or failing entirely. Consistency ensures the database remains in a valid state, Isolation prevents concurrent transactions from interfering with each other, and Durability guarantees that committed data is saved permanently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9476b0fa-2099-430e-999f-6257d14710cc', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How can you implement custom metrics in Spring Boot and why should you avoid high-cardinality tags?', N'Senior', N'You can use the Micrometer library to expose custom counters or gauges via Actuator. High-cardinality tags, such as those including unique user IDs or timestamps, cause a combinatorial explosion in the metrics storage, leading to severe performance degradation in monitoring systems like Prometheus.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d593cfd-469f-4c32-b0af-62596442975f', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why does Vite prefer Rollup for production builds instead of sticking with esbuild?', N'Middle', N'While esbuild is incredibly fast, Rollup offers a more mature plugin ecosystem and superior output configuration options. Rollup provides better support for complex production features like advanced code splitting, legacy browser compatibility, and CSS optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cafe98ca-73c3-46e1-97f5-625a40ec9b79', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you watch for nested data changes?', N'Fresher', N'You can use deep watcher by setting deep: true in the options object. This option enables us to detect nested value changes inside Objects. Note: This is not required to listen for Array mutations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f093b8ff-4c7e-4e67-906e-625dd400b30d', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'When should you prefer a CQRS (Command Query Responsibility Segregation) pattern over a standard CRUD approach?', N'Senior', N'CQRS is beneficial when the read and write workloads have drastically different scaling needs or complex security requirements. By separating these concerns, you can optimize the read path with specialized materialized views or caching while scaling the write path independently to handle high throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'334fe118-b6e5-4ab5-9c1d-625e0b7f8bc7', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is Go and what are its primary design goals?', N'Fresher', N'Go is an open-source, statically typed programming language developed by Google. Its primary design goals are simplicity, efficiency, high performance, and fast compilation times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c96c5803-3c2b-4dbd-8f72-62613c2ad1f8', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you handle a scenario where an upstream service sends data in an incompatible format?', N'Middle', N'I would implement an Anti-Corruption Layer (ACL) in my service to translate or transform the incoming data into a format that my internal domain models can understand. This prevents the external dependency''s schema from leaking into and polluting my internal codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10f930ab-103b-480d-891d-62638a6e118b', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the architectural trade-offs of using C-extensions for performance-critical Python code?', N'Senior', N'C-extensions offer native performance for compute-intensive tasks by bypassing the overhead of the Python interpreter and the GIL. However, they significantly increase complexity, require manual memory management, and make the codebase harder to maintain and port across platforms. They should only be used when profiling confirms that Python-level optimizations are insufficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6593241e-2f13-48a1-8b26-62643b65b981', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What distinguishes Svelte''s ''module'' context from the standard component script?', N'Senior', N'The ''context=module'' block runs once when the module is initialized, rather than every time a component instance is created. This is ideal for defining shared logic, constants, or state that should be persisted across all instances of a component throughout the application lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b335ab5-1816-467c-8e88-6264ae314299', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the Command pattern and how is it used?', N'Intern', N'The Command pattern is a behavioral design pattern that turns a request into a stand-alone object containing all information about the request. This transformation allows for parameterization of methods with different requests, queuing of requests, and logging of requests. It also supports undoable operations. In JavaScript, it can be implemented by creating command objects with execute and undo methods. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01d0325d-cff9-49bd-88c5-6264b239aa56', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a materialized view in NoSQL?', N'Junior', N'A materialized view is a precomputed result set that is stored and maintained by the database to speed up complex queries. Instead of computing the result on the fly, the database reads the precomputed data, which is especially useful for read-heavy applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'190feaa6-a172-4a07-833b-626590b45690', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono''s middleware composition model differ from traditional Express-style middleware in terms of execution flow?', N'Senior', N'Hono utilizes a recursive Promise-based composition model similar to Koa. This allows middleware to perform operations both before and after the downstream handlers execute, enabling more robust request lifecycle management compared to the linear next-based callback approach.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'233e2a4b-b130-454e-80bd-6266b72cfe90', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does Node.js handle garbage collection, and can it cause performance issues?', N'Middle', N'Node.js uses the V8 engine''s garbage collector, which automatically manages memory by reclaiming space from unused objects. Frequent or large-scale garbage collection cycles can cause ''stop-the-world'' pauses, potentially leading to noticeable latency spikes in high-throughput applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2352902b-01b2-4100-ba01-6267711106b7', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is a struct in Swift?', N'Intern', N'A struct is a value type used to group related properties and methods into a single unit. When you assign a struct to a new variable, it creates a copy of the data rather than sharing a reference.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f329fe3-dd83-4047-8e53-626b5271c150', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What are the performance benefits of Remix''s route-based code splitting?', N'Middle', N'Remix automatically splits code based on routes, ensuring the browser only downloads the JavaScript required for the current view. Because the framework manages these chunks, it minimizes the initial bundle size and speeds up time-to-interactive for the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27aa4ac3-593a-4c4a-bf3e-626cdca8b353', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the benefit of using esbuild in Vite?', N'Junior', N'Esbuild is written in Go and is significantly faster than JavaScript-based bundlers. Vite uses it to pre-bundle dependencies and transform TypeScript or JSX/TSX files into plain JavaScript at high speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9f60c98-ab10-4a15-9a50-626f51c5eeba', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Does Fiber support HTTP/2 natively?', N'Junior', N'Fiber itself does not implement the HTTP/2 protocol directly because it relies on the underlying Fasthttp library. To use HTTP/2 with Fiber, developers typically place a reverse proxy like Nginx in front of the application to handle TLS termination and protocol upgrading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c666918c-8401-4277-8893-6270e4ef699d', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the primary difference between JIT and AOT compilation in Quarkus?', N'Intern', N'JIT (Just-In-Time) compilation happens while the application is running, which is the traditional Java approach. AOT (Ahead-Of-Time) compilation happens during the build phase, creating a native executable that starts instantly without needing a full JVM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a00b0219-2146-4f3c-afa3-6272b468aad1', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How can Axum''s middleware be used to implement custom authentication schemes?', N'Senior', N'Middleware can intercept the request, validate credentials against a service, and inject the authenticated identity into the request extensions. This pattern keeps authentication logic out of the business handlers and ensures that all protected routes are enforced by a consistent, reusable policy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5136d60f-116b-4520-95dc-62735f071e58', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the purpose of getDerivedStateFromProps() lifecycle method?', N'Fresher', N'The new static getDerivedStateFromProps() lifecycle method is invoked after a component is instantiated as well as before it is re-rendered. It can return an object to update state, or null to indicate that the new props do not require any state updates. This lifecycle method along with componentDidUpdate() covers all the use cases of componentWillReceiveProps().', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a2bae0c-cd83-440e-a40f-6275cc4a6c83', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you approach choosing between a relational and a NoSQL database for a new microservice?', N'Senior', N'I evaluate the data consistency requirements, schema flexibility, and access patterns. If the service requires complex transactions and strict relational integrity, a relational database is preferred, whereas NoSQL is better suited for high-write throughput, horizontally scalable systems with unstructured or rapidly evolving data models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'505394a5-0acc-4c8a-80d1-6277851594d7', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Describe the mechanism behind Svelte''s ''actions'' and how they facilitate third-party library integration.', N'Senior', N'Actions provide a lifecycle hook for elements, allowing developers to attach custom behavior to DOM nodes when they are created or destroyed. This is the idiomatic way to integrate non-Svelte libraries, as it encapsulates the integration logic cleanly within the DOM element''s lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ff088d7-0d0e-4c3f-86c0-6277934192ee', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the primary difference between message queuing and publish-subscribe messaging patterns?', N'Middle', N'In message queuing, messages are sent to a queue and typically processed by a single consumer, ensuring point-to-point delivery. In pub-sub, a message is published to a topic and broadcast to all subscribers, allowing multiple independent services to react to the same event.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'784158ee-49da-40e3-a723-6279353cda57', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you handle API documentation for internal and external teams?', N'Middle', N'Standardized formats like OpenAPI (Swagger) allow for automated documentation generation and interactive testing. Keeping documentation in sync with code is crucial, often achieved by generating it directly from the API source or annotations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a634ee94-3bca-4f8e-a8ac-627e220bd588', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of Twig in Symfony?', N'Junior', N'Twig is the default template engine for Symfony, designed to be secure and efficient for generating HTML. It provides a clean syntax for writing templates while automatically escaping output to prevent common security vulnerabilities like cross-site scripting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f85c2c2-af10-4bfb-976a-627e8634d4f5', N'954a0331-deff-4399-b588-96f39fec001d', N'How does the Angular Ivy compiler''s locality principle improve build performance and modularity?', N'Senior', N'Ivy processes each component independently, meaning a change to one component only requires recompiling that specific file rather than the entire application. This decoupling reduces incremental build times and allows for better tree-shaking by removing unused instructions at the call site.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ca2f573-63d4-4273-a9cf-627fb8fd058c', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the advantage of using NestJS over plain Express?', N'Junior', N'NestJS provides a structured, opinionated architecture that promotes modularity and testability. It simplifies dependency management and includes built-in support for TypeScript, making it easier to maintain large-scale applications compared to the unopinionated nature of Express.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ce00f5f-f093-475d-acb4-62874540dc69', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the primary architectural difference between a generator and a standard function?', N'Middle', N'A standard function executes to completion and returns a value, whereas a generator uses the yield keyword to pause execution and produce a sequence of values lazily. This approach allows generators to handle large datasets efficiently by keeping only the current element in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdb90d4c-9f72-4544-9812-62892d656dd4', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the main architectural challenge when migrating an existing React app to Qwik?', N'Senior', N'The main challenge is the paradigm shift from ''hydration'' to ''resumability.'' Developers must refactor component logic to be fully serializable and adapt to Qwik''s specific reactive primitives, as they cannot simply move over patterns that rely on standard React useEffect hooks or complex context providers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa1ac355-2080-48c4-8a1d-628e7230106a', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus perform memory optimization?', N'Intern', N'Quarkus optimizes memory by removing unused classes and metadata during the build process. By resolving dependencies at compile-time, it avoids the memory overhead associated with runtime reflection and dynamic scanning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e28b79d2-25ae-41cc-ac45-6290bb4142cc', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Explain the architectural challenge of testing jQuery-based applications versus component-based frameworks.', N'Senior', N'Testing jQuery applications requires simulating a full DOM environment, which is slow and brittle. Component-based testing allows for isolated unit testing of logic without the overhead of the DOM, leading to faster, more reliable test suites.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65c993e0-3650-4c88-8962-62933015c22f', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do you remove the leading whitespace in a string?', N'Fresher', N'Leading whitespace in a string is the whitespace in a string before the first non-whitespace character. To remove it from a string, we use the method lstrip(). ''Ram '' As you can see, this string had both leading and trailing whitespaces. lstrip() stripped the string of the leading whitespace. If we want to strip the trailing whitespace instead, we use rstrip(). '' Ram'' - How would you convert a string into lowercase? We use the lower() method for this. ''ramayan'' To convert it into uppercase, then, we use upper(). ''RAMAYAN'' Also, to check if a string is in all uppercase or all lowercase, we use the methods isupper() and islower(). False True True True True So, characters like @ and $ will suffice for both cases. Also, istitle() will tell us if a string is in title case. True', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b75bce5b-f366-45a6-bcfd-6293be38dbe1', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the difference between a ''FastAPI'' app instance and an ''APIRouter''?', N'Junior', N'The ''FastAPI'' instance is the main entry point for the application that handles server-level configuration and lifecycle events. ''APIRouter'' is a child component used to segment the API into logical sections without needing to create a separate application instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb3da561-8289-44ea-9ffa-629403ce3e8a', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Why is it often discouraged to use Sass to generate large amounts of utility classes?', N'Senior', N'Generating massive amounts of utility classes via Sass loops significantly increases the size of the final CSS bundle, potentially impacting First Contentful Paint. Modern approaches favor atomic CSS-in-JS or build-time tools like Tailwind, which perform tree-shaking to only include used utilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c775c43-3192-4d69-95d6-6294d535161c', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Explain the role of ''tracking scopes'' in SolidJS and why they are critical for preventing memory leaks in complex reactive applications.', N'Senior', N'Tracking scopes define the boundaries where reactive signals are automatically collected as dependencies by effects or memos. If these scopes are not managed correctly, such as when signals are accessed outside of a reactive context, the framework cannot establish the necessary cleanup logic, leading to orphaned subscriptions. Properly scoped reactivity ensures that when a component or effect is disposed of, all associated listener references are garbage collected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31fd9b06-6578-4b5c-aef3-62964442160a', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does the autovacuum daemon determine when to run?', N'Middle', N'Autovacuum is triggered based on thresholds related to the number of updated or deleted rows in a table. These thresholds are defined by the scale factor and the minimum number of changes, which ensure the system performs maintenance before bloat becomes critical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8931f94-d3d5-402e-93ac-6298eaf3bf36', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB handle write conflicts during concurrent updates?', N'Senior', N'DynamoDB uses optimistic locking via Conditional Expressions to prevent lost updates. By checking if an attribute value matches the expected state before applying a change, the system ensures that updates only proceed if no conflicting modification has occurred.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a69c98bc-4b47-4d55-ba86-629b8b9b0427', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between ''composition'' and ''inheritance'' in object-oriented design?', N'Middle', N'Inheritance establishes an ''is-a'' relationship, which is rigid and can lead to fragile base classes. Composition establishes a ''has-a'' relationship, providing greater flexibility by allowing behavior to be changed at runtime through dependency injection. Composition is generally preferred in modern development because it promotes loose coupling and avoids the limitations of single inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6ee507e-8179-41dd-94b4-629c31662a84', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the benefit of using the ''reply.send()'' method instead of returning values directly?', N'Middle', N'While returning values is supported for simplicity, using reply.send gives developers more explicit control over the response lifecycle. It allows for setting custom headers, status codes, and handling stream-based responses more effectively in complex scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ca10eab-0eab-4fbf-b714-629c53b68e98', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum''s design influence the choice between ''Arc'' and ''Box'' for state management?', N'Senior', N'Axum requires state to be thread-safe, so shared state must be wrapped in ''Arc'' to satisfy the ''Clone + Send + Sync'' bounds required for concurrent handler execution. ''Box'' is typically used for heap allocation or dynamic dispatch, but it does not facilitate the shared ownership required for application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc89ae44-4c98-436a-9cfd-629ecc207501', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the difference between ''clientLoader'' and a standard ''loader'' in Remix?', N'Middle', N'A standard loader runs on the server to provide data for SSR, while a clientLoader runs in the browser. Using clientLoaders allows for scenarios where data is fetched directly from client-side caches or APIs after the initial page load, potentially bypassing the server for faster subsequent interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6abf68c7-13f2-4619-a0a1-62a16c56ef71', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What does ''Zero-Bundle-Size'' mean in the context of Astro?', N'Intern', N'Zero-bundle-size refers to Astro''s ability to render components on the server and strip away all non-essential JavaScript before sending the page to the client. This results in significantly faster page load times because the browser has less code to download and parse.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7dc5e02-0393-4bc4-ad46-62a2463ce0c6', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are React Fragments used for?', N'Intern', N'React Fragments are used to group multiple elements without adding extra nodes to the DOM. This is useful when you want to return multiple elements from a component''s render method without wrapping them in an additional HTML element. You can use the shorthand syntax <>... or the React.Fragment syntax. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f9ce57c-f111-4050-9f0e-62a3b8b6b47a', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is an execution plan in PostgreSQL?', N'Junior', N'An execution plan is a roadmap generated by the database engine showing how it intends to retrieve the requested data. It details the steps the query planner takes, such as which indexes it will use and how it will join tables, helping developers debug slow queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4b5dc14-ff6d-470d-b0d4-62a561652d58', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle logging?', N'Junior', N'Fiber includes a built-in Logger middleware that records details about every incoming request, such as the HTTP method, status code, and execution time. This middleware can be customized to output logs in different formats, such as JSON or standard text.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'057c20b7-4cda-47aa-b506-62a7ae2c2836', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you approach a situation where two teammates disagree on a technical implementation?', N'Junior', N'Listen to both perspectives objectively, focusing on the pros and cons of each approach regarding performance, maintainability, and timeline. If a consensus cannot be reached, consult a senior team member or lead to make a final decision based on the project''s long-term goals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'730050e5-d09b-4a62-a02b-62a99bc65e7d', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does the ACID acronym stand for in the context of databases?', N'Fresher', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These are the four fundamental properties that ensure a database transaction is processed reliably.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e660cecd-a0b7-4180-b71a-62aa7ae7533b', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain the difference between the libuv thread pool and the V8 engine in the context of Node.js performance.', N'Senior', N'V8 is the JavaScript engine responsible for compilation and execution of code, while libuv provides the asynchronous I/O abstraction and a background thread pool for operations that cannot be handled by the kernel. The thread pool is specifically used for blocking tasks like file system operations and cryptographic functions, preventing them from stalling the main thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c43c6fc-eae0-49b1-ab7e-62ac63e9cbaa', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the advantages of using partitions in large tables?', N'Middle', N'Partitioning divides a large table into smaller, more manageable pieces based on a specific rule, such as a date range. This can improve performance by allowing the optimizer to prune unnecessary partitions and can make maintenance tasks like data purging much faster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2f97bb9-7138-47a7-b534-62aedabaaa7e', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does the Global Interpreter Lock (GIL) impact multi-threaded CPU-bound programs in CPython?', N'Senior', N'The GIL ensures that only one thread executes Python bytecode at a time, preventing concurrent access to internal object structures. Consequently, CPU-bound tasks in a single process cannot utilize multiple cores effectively, forcing developers to use the multiprocessing module to bypass these constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b7824f2-c10a-4e17-9d17-62b2ed7e207d', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What do you do if you notice a teammate is struggling with their task?', N'Intern', N'I would offer to help them brainstorm ideas or look over their work if I have the capacity to do so. If the task is outside my expertise, I would encourage them to talk to a mentor or lead to ensure they get the right support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9ce6d64-0f6d-4ee5-ba6e-62b540711bdb', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the impact of using the KEYS command in a production environment?', N'Middle', N'The KEYS command is a blocking operation that scans the entire keyspace, which can freeze the Redis server for several seconds if the dataset is large. It is considered dangerous in production because it blocks all other incoming requests, and should be replaced by the SCAN command, which iterates over keys incrementally without blocking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f38dcb67-bd4c-4cd0-9b84-62b60d4a5050', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the role of the Ingest Node?', N'Intern', N'An ingest node allows you to transform and enrich documents before they are indexed. It can perform tasks like renaming fields, removing fields, or parsing data using pre-defined pipelines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9983bb64-f372-40b3-9e07-62b742fe2157', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle form submissions without a custom API?', N'Intern', N'Remix uses action functions to handle data mutations, such as form submissions, directly on the server. Instead of needing a separate API endpoint, the action function processes the submitted form data and then automatically reloads the page data to keep the UI in sync.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9858fe3a-5ffb-4dd8-ac5d-62b8568ff8bc', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the benefit of using fibers in a web server?', N'Intern', N'Fibers allow a web server to handle thousands of concurrent client connections without needing thousands of heavy OS threads. This significantly reduces memory consumption and improves the server''s ability to remain responsive under high load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
