INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38e2512a-3bc7-42f2-bfd6-62bb96bd66f6', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Do Hooks replace render props and higher order components?', N'Middle', N'Both render props and higher-order components render only a single child but in most of the cases Hooks are a simpler way to serve this by reducing nesting in your tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bbd9aa6-56e0-4a19-8275-62bf02775ac8', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the timing features of Node.js?', N'Intern', N'The Timers module in Node.js contains functions that execute code after a set period of time. Timers do not need to be imported via require(), since all the methods are available globally to emulate the browser JavaScript API. Some of the functions provided in this module are 1. setTimeout(callback, delay, ...args) Executes the callback once after at least delay milliseconds. Returns a Timeout object usable with clearTimeout(). Syntax: Example: 2. setImmediate(callback, ...args) Executes the callback once, at the end of the current event loop iteration — after I/O events but before timers. Syntax: Example: 3. setInterval(callback, delay, ...args) Executes the callback repeatedly every delay milliseconds until stopped with clearInterval(). Syntax: Example: 4.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56968cb2-7b71-4539-8bd1-62c0c740c411', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Does Tailwind CSS provide pre-built components?', N'Fresher', N'Tailwind CSS does not provide pre-built components out of the box like traditional frameworks. Instead, it provides the building blocks to create your own unique components, although the official Tailwind UI library offers pre-designed components built with Tailwind.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0aad2578-9c94-42d7-90f7-62c126a38bd9', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Describe the impact of Quarkus''s ''Uber-JAR'' versus native executable deployment.', N'Senior', N'An Uber-JAR is a standard Java archive containing all dependencies, which is portable and runs on any JVM but requires a longer startup time. A native executable is OS-specific, contains no external JVM dependencies, and provides near-instant startup, though it is significantly harder to build and debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44007290-a0af-4b5a-8687-62c1681fdd9c', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between a string literal and a character array?', N'Fresher', N'A string literal is a constant sequence of characters enclosed in double quotes, stored in read-only memory. A character array is a mutable sequence of characters that occupies memory on the stack or heap.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da17a3d2-483b-4f17-bde4-62c36df62a14', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of the ''Hooks'' feature in Lucid models?', N'Middle', N'Hooks allow developers to execute logic automatically at specific points in a model''s lifecycle, such as before saving or after deleting a record. They are ideal for cross-cutting concerns like hashing passwords, clearing caches, or triggering background jobs without cluttering the controller logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31d5266f-f6c4-44e8-958b-62c6128e92ea', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the function of the application controller?', N'Intern', N'The ApplicationController is the base class from which all other controllers in the application inherit. It is the place to define common logic, such as authentication methods or global before-action filters, that should apply to every controller in the app.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe72a0bf-4905-4a67-a638-62c6a39e8ab4', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the significance of the @ApplicationScoped annotation in Quarkus?', N'Middle', N'This annotation defines the lifecycle of a bean, ensuring that a single instance is created for the entire duration of the application. It is the default scope for many Quarkus components, facilitating efficient resource management and preventing unnecessary object instantiation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56e37a93-50d4-4f41-b197-62ceb382d4c1', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Explain the concept of undefined behavior in the C standard.', N'Middle', N'Undefined behavior refers to situations where the C standard does not mandate any specific behavior, such as accessing an out-of-bounds array index or dereferencing a null pointer. This allows compilers to make aggressive optimization assumptions, meaning the program might crash, produce garbage data, or appear to work correctly depending on the optimization level and platform.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72086172-ff1c-4ba4-a673-62d3f60b7f83', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the primary architectural benefit of using Gin''s Radix tree-based router compared to a standard linear map-based router?', N'Middle', N'Gin uses a compressed Radix tree, which provides highly efficient path matching with O(k) complexity, where k is the length of the URL. This is significantly faster than linear searching, especially when handling a large number of routes with common prefixes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23c43b62-f959-40fc-ae37-62d5b9ce1f53', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Why is ''Write-Ahead Logging'' (WAL) critical for database durability?', N'Senior', N'WAL ensures durability by recording all changes to a persistent log before they are applied to the actual data files. In the event of a system crash, the database can reconstruct its state by replaying the log, ensuring no committed data is lost even if the main data files were not yet updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bcbb9a0-2ae4-4712-b2b1-62d9ed938449', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the purpose of the ''z-index'' property?', N'Junior', N'The z-index property controls the vertical stacking order of elements that overlap. It only works on elements that have a position value other than static, with higher numbers appearing on top of lower numbers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b04e4c79-0fe8-4124-baa0-62dc84bca5ef', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is a CSRF token in the context of Symfony forms?', N'Junior', N'A CSRF token is a unique, secret value generated by Symfony and embedded in a form to prevent Cross-Site Request Forgery attacks. It ensures that the form submission originated from your application and not from a malicious third-party site.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9160d3a8-c02b-45f3-92b6-62de1756657f', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What does ''binding'' mean in Echo?', N'Intern', N'Binding is the process of mapping data from an HTTP request—such as form values, query parameters, or JSON bodies—into a Go variable or struct. This abstracts away the manual parsing of raw request data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7d137cf-ad30-42bd-a16c-62ded560aea1', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the purpose of using a salt when hashing passwords?', N'Middle', N'A salt is a unique, random string appended to a password before it is hashed to prevent the use of precomputed rainbow tables. It ensures that identical passwords result in different hash values, making it much harder for attackers to crack passwords in bulk.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad271e03-3484-44e2-9931-62e3b5d144e6', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What are the architectural benefits of using CSS variables over preprocessor variables?', N'Senior', N'CSS variables (Custom Properties) are resolved at runtime and can be scoped to the DOM, allowing for dynamic theme changes without recompilation. Unlike preprocessor variables, they can be updated via JavaScript and inherit through the DOM, providing a more powerful and flexible architectural tool for theming.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'949150da-b048-4c7d-8cca-62e4dfae961f', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the _source field?', N'Fresher', N'The _source field contains the original JSON document body that was passed when the document was indexed. It is stored as a single block and is used to return the original data when a document is retrieved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04e6c20a-c9dc-407b-94bf-62e6d495a927', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the benefit of strict mode?', N'Intern', N'The will be helpful in the below cases, 1. To find the bugs caused by impure rendering where the components will re-render twice. 2. To find the bugs caused by missing cleanup of effects where the components will re-run effects one more extra time. 3. Identifying components with unsafe lifecycle methods. 4. Warning about legacy string ref API usage. 5. Detecting unexpected side effects. 6. Detecting legacy context API. 7. Warning about deprecated findDOMNode usage', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39121eee-8bc5-477a-b675-62e8190322a5', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the possible side-effects in javascript?', N'Intern', N'A side effect is the modification of the state through the invocation of a function or expression. These side effects make our function impure by default. Below are some side effects which make function impure, - Making an HTTP request. Asynchronous functions such as fetch and promise are impure. - DOM manipulations - Mutating the input data - Printing to a screen or console: For example, console.log() and alert() - Fetching the current time - Math.random() calls: Modifies the internal state of Math object', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd378c655-ae8c-4932-b0e9-62e85036c068', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are DynamoDB read consistency models?', N'Intern', N'DynamoDB offers two consistency models: eventually consistent reads and strongly consistent reads. Eventually consistent reads maximize throughput but may reflect stale data, while strongly consistent reads return the most up-to-date data at the cost of higher latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76bd25db-2faf-48a8-99e7-62ec65d27151', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Describe the mechanism Svelte uses to prevent memory leaks in store subscriptions.', N'Senior', N'Svelte provides an auto-subscription syntax using the dollar sign prefix, which automatically manages the subscription lifecycle. When the component is destroyed, Svelte generates code to unsubscribe from the store, preventing the common issue of dangling references found in manual subscription patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7966b2ab-c58d-4283-ae2d-62ee22451d55', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the difference between SCSS and the original Sass syntax?', N'Intern', N'SCSS is the modern, CSS-compatible syntax that uses curly braces and semicolons, making it easier for developers familiar with CSS to learn. The original Sass syntax, known as indented syntax, uses indentation instead of braces and omits semicolons.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a24696a1-0ac3-478f-8f75-62ef00387780', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What does ''mutating'' mean in a struct?', N'Intern', N'Because structs are value types, their properties cannot be modified by default within their methods. The ''mutating'' keyword allows a method to modify the properties of the struct instance it belongs to.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa9af1a0-f2a1-44dc-b0d2-62efb921da89', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of the ''serializer'' layer in Ember Data?', N'Middle', N'The serializer is responsible for transforming the raw JSON payload from your API into the format expected by Ember Data''s internal record store. It allows you to normalize inconsistent API responses into a unified structure that your application models can consume.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e6bca33-1a43-4124-927f-62f29b9c0356', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is Hoisting', N'Intern', N'Hoisting is JavaScript''s default behavior where variable and function declarations are moved to the top of their scope before code execution. This means you can access certain variables and functions even before they are defined in the code. Example of variable hoisting: Example of function hoisting: Because of hoisting, functions can be used before they are declared.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
