INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a50fda29-5b69-4de8-af63-62f7601e26df', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are given a task with an unknown timeline, what is your process for estimating the completion date?', N'Intern', N'I would first break the task down into smaller, manageable sub-tasks to understand the scope. I would then research each sub-task to identify potential dependencies or technical hurdles. Finally, I would create a timeline that includes a buffer for unexpected issues, while communicating the assumptions behind my estimate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
