INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20f1458d-2cb5-4a24-ac82-630da180a896', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle static site generation (SSG)?', N'Fresher', N'SvelteKit supports static site generation by pre-rendering routes during the build process. Instead of generating pages on the fly, it creates static HTML files that can be served directly from a CDN, resulting in very fast load times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af578812-b89a-4f4e-9a74-630df581ab15', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit achieve ''hydration'' of the page?', N'Middle', N'After the server sends the pre-rendered HTML to the browser, SvelteKit ''hydrates'' the page by attaching the Svelte runtime to the static elements. This makes the page interactive by initializing event listeners and state management without re-rendering the entire DOM tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66a1b144-f091-4438-a6d9-631015da0adb', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are Python ''sets'' and when should you use them?', N'Junior', N'A set is an unordered collection of unique elements. You should use sets when you need to store items where duplicates are not allowed or when you need to perform mathematical set operations like unions, intersections, or differences. Because sets are implemented using hash tables, they offer very fast lookup speeds for checking if an item exists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
