INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c63b27e3-6c4c-42b8-8cb9-6318a629b8fc', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does Sass integration with CSS variables differ from using Sass variables?', N'Senior', N'Sass variables are compiled into static values during build time, meaning they cannot be updated dynamically by the browser. CSS variables, however, exist in the DOM, allowing for real-time updates via JavaScript or media queries, making them superior for dynamic theming and runtime UI state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df8e9d91-fc3d-4bc8-9eb8-6320c6158b54', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Explain the concept of ''lifting state up''.', N'Middle', N'Lifting state up involves moving shared state to the closest common ancestor of the components that need it. This ensures that data remains synchronized across multiple components by keeping the source of truth in a single location.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
