INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e7bde5f-3dba-4cb1-a835-6353e0f0b2dc', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle routing?', N'Intern', N'Axum uses a router object to map specific URL paths and HTTP methods to their corresponding handler functions. This router acts as a central registry that directs incoming traffic to the correct application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4fceaee-7675-4c06-ba00-6354b850d8fa', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a scenario where the application cache is returning stale data?', N'Middle', N'I would investigate the cache invalidation logic to see if it is triggered correctly upon data updates. I would also check the time-to-live settings and ensure that the application handles cache misses and updates consistently across all nodes in the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d284bab-72fb-4c86-98da-6355d0704087', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Can you define custom extractors in Actix-web?', N'Junior', N'Yes, you can create custom extractors by implementing the FromRequest trait for your own types. This allows you to encapsulate complex logic, such as validating a custom API token, directly into the handler signature.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1966868-835f-40d1-b6d5-635820c2551d', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the orphan rule in trait implementation?', N'Middle', N'The orphan rule states that you can only implement a trait for a type if either the trait or the type is defined in your current crate. This prevents conflicts where different crates might define different implementations for the same trait-type pair.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'333b6e87-0f48-416c-a238-635a73f9fe46', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of ''Object.freeze'' versus ''Object.seal'', and how do they impact object mutation?', N'Senior', N'Object.seal prevents adding or removing properties but allows modification of existing ones. Object.freeze makes an object entirely immutable, preventing any changes to its structure or values, which is useful for maintaining state integrity in complex applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb686304-d3c9-4c78-a758-635b43074e8a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle constructive criticism regarding your work?', N'Intern', N'I would view constructive criticism as an opportunity to learn and improve my skills rather than as a personal attack. I would listen carefully to the feedback, ask clarifying questions, and integrate the suggestions into my future work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'740ee671-6fa4-4d11-9ef4-635b6c226400', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Explain the trade-offs of using ''app.use'' for global middleware versus route-specific middleware.', N'Senior', N'Global middleware ensures consistent behavior across all endpoints but can degrade performance for routes that do not require specific logic, such as health checks. Route-specific middleware optimizes execution time and reduces the complexity of request processing for lighter endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'013b443f-0f83-4538-95a7-63603c67005d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between batch processing and real-time processing?', N'Fresher', N'Batch processing is highly efficient for handling large volumes of data with lower overhead. Real-time processing provides immediate results, which is essential for user-interactive tasks, but it is much more resource-intensive and complex to manage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2cf1aa8-fbf0-48c6-8f1b-6360d8d3bbf7', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the purpose of the hooks.server.js file?', N'Intern', N'This file allows you to intercept server requests to perform tasks like authentication or modifying headers. It runs every time a request is made to the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a3089d8-d7e0-4484-bbe3-63629105b875', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Does Actix-web support WebSockets?', N'Fresher', N'Yes, Actix-web provides built-in support for WebSockets through the actix-web-actors crate. This allows developers to create real-time, bi-directional communication channels between the server and the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'870c1776-bf0d-426e-bb7e-63646726ef13', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Is MongoDB case-sensitive?', N'Intern', N'Yes, MongoDB is case-sensitive regarding field names and collection names. For example, a collection named ''Users'' is considered different from a collection named ''users''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa8e3b74-2e24-4ff1-8e14-6364f3e1ab49', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is TkInter?', N'Intern', N'TkInter is Python library. It is a toolkit for GUI development. It provides support for various GUI tools or widgets (such as buttons, labels, text boxes, radio buttons, etc) that are used in GUI applications. The common attributes of them include Dimensions, Colors, Fonts, Cursors, etc.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'719b6d74-598c-424b-975e-63659cc83761', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What are the primary performance implications of using jQuery''s DOM manipulation methods compared to modern native APIs?', N'Middle', N'jQuery methods often involve additional overhead due to cross-browser normalization and wrapper object creation. Modern native APIs like querySelector and classList are significantly faster and more lightweight because they operate directly on the browser''s DOM implementation without the abstraction layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'049bc5f6-674c-4ad8-b049-63685fe711d8', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does a distributed consensus algorithm like Raft ensure log consistency across nodes?', N'Senior', N'Raft ensures consistency by electing a single leader who manages the replicated log. All changes must pass through the leader, who replicates entries to followers and only commits them once a majority of nodes have acknowledged receipt, ensuring all nodes eventually converge on the same state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c4064a3-bb06-4dd1-8792-6369f0e7c52d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When faced with conflicting priorities from stakeholders, how do you determine which tasks to estimate first?', N'Middle', N'I would evaluate tasks based on their business value and risk profile. By prioritizing tasks that resolve high-uncertainty technical blockers or provide significant product value, I ensure that the estimation process directly supports the most critical project goals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
