INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc447004-2794-4607-90a2-6371ca3116ff', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the MVC pattern in the context of Laravel?', N'Intern', N'MVC stands for Model, View, and Controller. The Model manages data and business logic, the View handles the user interface, and the Controller acts as an intermediary that processes user input from the view and updates the model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f77a54b-c1af-4689-b619-6371f7b18428', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'When should you implement database replication?', N'Middle', N'Replication is used to improve read scalability by distributing read-only queries across multiple read-replicas and to provide high availability by enabling failover in case the primary node goes down. It is essential for disaster recovery and handling large amounts of global traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baeadec8-cd34-46d3-be72-637357dadda2', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between firstChild and firstElementChild?', N'Fresher', N'1. firstChild: The firstChild property returns the first child node of the specified node, as a Node object. 2. firstElementChild: The firstElementChild property returns the first child element of the specified element. Difference: firstChild returns the first child node (an element node, a text node or a comment node). Whitespace between elements are also text nodes. firstElementChild returns the first child element (not text and comment nodes).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67e32e19-a3f5-4ffe-b706-6374f0dc0d13', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the purpose of Dev Mode in Quarkus?', N'Intern', N'Dev Mode provides a live-coding experience where changes to the source code are reflected immediately in the running application without a manual restart. This significantly speeds up the development cycle by allowing instant feedback.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
