INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91d166cc-477d-45c2-a52a-637a484b559d', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the benefit of using template engines in Express?', N'Middle', N'Template engines like EJS or Pug allow for server-side rendering of HTML pages by injecting dynamic data into predefined templates. While less common in API-only architectures, they are useful for full-stack applications requiring SEO-friendly page delivery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd34dda31-33b0-46fa-8354-637a4a67b0ba', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Does Webpack work with TypeScript out of the box?', N'Junior', N'No, Webpack needs a loader to process TypeScript files. You typically use a loader like ts-loader or a transpiler like Babel to convert TypeScript into standard JavaScript that Webpack can bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66709985-ea97-4c98-82f8-637adc0cbee8', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the function of the PHP garbage collector?', N'Intern', N'The garbage collector is a mechanism that automatically manages memory by identifying and removing objects that are no longer in use. It helps prevent memory leaks by freeing up resources that are no longer accessible to the script.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e79d61fd-82b9-46af-adf1-637c83cd412c', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is meant by ''Zero-Bundle JavaScript'' in Astro?', N'Intern', N'Zero-bundle JavaScript means that by default, Astro strips out all JavaScript from your final page output. This ensures that the page remains a static HTML document unless you explicitly add interactive components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0edef040-7264-4ae3-8b47-638385338d21', N'954a0331-deff-4399-b588-96f39fec001d', N'How does Angular support internationalization (i18n) of applications?', N'Fresher', N'Angular provides built-in support for internationalization (i18n) primarily through a build-time process. You mark text and attributes in your templates and code for translation using the i18n attribute or the $localize tagged template literal. The Angular CLI command ng extract-i18n is then used to collect all these marked messages into a translation file (like XLIFF or XMB). This file is given to translators. Once translated, you configure your angular.json file or use CLI arguments (--localize) to tell Angular which translation files to use for specific locales. When you build or serve your application for a particular locale, Angular replaces the original messages with the translated ones, creating locale-specific versions of your application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dd19f71-e004-48fb-be65-638b5576423c', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the impact of using ''panic!'' in a production application?', N'Middle', N'A panic causes the thread to unwind or abort, which can lead to incomplete data processing or application crashes if not handled correctly. In production, it is generally preferred to return ''Result'' types to allow the caller to handle failures gracefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd2e2f61-f8fd-406d-b83a-638d2f530d79', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does ACID compliance affect database performance?', N'Middle', N'ACID compliance ensures data reliability and consistency through strict transaction management. The overhead of logging, locking, and synchronization required to maintain these guarantees can reduce throughput compared to databases that prioritize performance over strict transactional consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03affaf2-807f-4358-9dff-639297fb45c4', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Why is the circuit breaker pattern important for system reliability?', N'Middle', N'The circuit breaker pattern prevents a system from repeatedly trying to execute an operation that is likely to fail. By tripping the circuit, it stops cascading failures, gives the failing service time to recover, and allows the calling service to return a fallback response instead of hanging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1013af4-c60a-451d-a235-6392ec83ff9a', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the primary architectural benefit of Astro''s ''Islands Architecture''?', N'Junior', N'Astro''s Islands Architecture improves performance by shipping only the necessary JavaScript to the client while rendering the rest of the page as static HTML. By isolating interactive components, it reduces the total amount of code the browser needs to download and execute, leading to faster page loads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'095ebdbd-7499-4959-b542-6395ca460a53', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the purpose of S3 classes in R?', N'Middle', N'S3 is a simple, informal object-oriented system based on generic functions that dispatch methods based on the class of the first argument. It is highly flexible and widely used in base R, though it lacks strict formal definitions and encapsulation compared to more rigid systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'031c67db-1c77-489b-85f1-6396453c7962', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS support asynchronous programming?', N'Junior', N'NestJS is built on top of Node.js, which is non-blocking by design. The framework fully supports asynchronous operations by allowing route handlers and providers to return promises or use the async/await syntax, which is essential for database queries and external API calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8dd7bf84-45f1-4e9b-8029-6396fa6334f9', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is middleware in Echo?', N'Intern', N'Middleware in Echo are functions that are executed during the request-response lifecycle. They can perform tasks such as logging, authentication, recovery from panics, or modifying request/response headers before reaching the final handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4ba46e3-c966-4d53-a75d-63987e77469c', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the role of the ''rocket_contrib'' or official libraries?', N'Intern', N'While the core Rocket framework provides the base routing and server logic, official libraries or community-maintained crates extend this functionality. These often include support for database connection pooling, template rendering, and authentication helpers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16a38cea-d683-4b86-b731-639a651ab089', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does C''s ''static'' storage class duration differ from its role in linkage control?', N'Senior', N'The static keyword provides two distinct functions: it defines an object as having a lifetime spanning the duration of the entire program, and it limits the scope of identifiers to the current translation unit. These are orthogonal concepts, where the former manages memory persistence and the latter manages namespace isolation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5583e8a3-dbc2-45ac-a482-639ba4214907', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why is it important to document the assumptions made during an estimation process?', N'Intern', N'Documenting assumptions ensures that the reasoning behind an estimate is transparent and traceable. If the project requirements change or the original conditions are proven false, it allows others to quickly update the estimate by adjusting the specific assumptions affected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd25b6d6d-741b-43aa-8ed1-63a3afe4cc50', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the primary architectural advantage of using FastAPI over traditional frameworks like Flask?', N'Junior', N'FastAPI is built on top of Starlette and Pydantic, providing native support for asynchronous programming using async/await syntax. This allows the framework to handle a high volume of concurrent connections efficiently, making it significantly faster for I/O-bound tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'597ebf04-0b8d-4da3-955a-63a5544f3282', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the VDOM in the context of Preact?', N'Fresher', N'The Virtual DOM is a lightweight representation of the actual DOM in memory. Preact uses it to calculate the minimum number of changes needed to update the real DOM, which improves rendering efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
