INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebbb8aee-463f-4928-b4f7-63a9d8524398', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How do you manage cross-cutting concerns like logging or profiling in Symfony?', N'Middle', N'Cross-cutting concerns are best handled using the EventDispatcher or by creating decorators for services. These patterns allow you to inject secondary logic like logging or performance tracking without cluttering the primary business logic of the service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e8a0a1c-291f-4faf-998e-63ac00c124d6', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the ''rel=preload'' hint interact with the browser''s resource priority queue?', N'Senior', N'The preload hint informs the browser that a resource is required for the current page load before the browser''s scanner would otherwise discover it. This elevates the resource''s priority in the fetch queue, ensuring it is requested sooner, but excessive preloading can compete with other critical assets and actually degrade load performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a5f9127-2918-4c4a-9610-63ad86a86605', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'When should you use an ''Interceptor'' for response transformation?', N'Middle', N'Interceptors are ideal for standardizing the API response format across all endpoints. By using an interceptor, you can wrap every successful response in a consistent structure, such as adding metadata or status indicators, without repeating logic in every controller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'017231d6-8499-4999-b140-63ada521b021', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you manage your time when you have multiple competing tasks?', N'Junior', N'Prioritize tasks based on urgency and impact, focusing on the items that block others or carry the highest risk. Use a system like a task list to track progress and communicate with your lead if your capacity is exceeded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d7df6f7-cf2d-4864-b01b-63ae045e02f2', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the importance of ''error budgets'' in the context of troubleshooting and reliability?', N'Middle', N'Error budgets define the acceptable threshold for system failure, balancing the need for rapid feature delivery against system stability. When the budget is exhausted, it signals the need to pause new feature work and prioritize reliability improvements and debugging efforts. This framework prevents reactive troubleshooting from becoming the norm by forcing a structured focus on system health.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc19afe1-8260-4d70-b88e-63b0539d4074', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are ''prerendering'' routes?', N'Junior', N'Prerendering is the process of generating static HTML files for routes during the build time. This allows the server to serve these pages instantly without needing to run any logic at request time, significantly improving speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a727de03-3f75-4e57-a4da-63b0ff4a528a', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the purpose of a Circuit Breaker in a microservices system?', N'Middle', N'A circuit breaker prevents a service from repeatedly trying to execute an operation that is likely to fail. It monitors for failures and, once a threshold is met, trips the circuit to immediately reject subsequent requests, allowing the failing service time to recover and protecting the system from resource exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0107229d-a4ef-4578-8266-63b10749e586', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'When is it appropriate to use arbitrary values in Tailwind CSS?', N'Middle', N'Arbitrary values should be used when you need a specific, one-off value that isn''t included in your theme configuration, such as a precise pixel value for a background image or a unique z-index. They should be used sparingly to maintain design consistency and avoid cluttering the codebase with non-standard values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37f783ce-7691-4497-8cb1-63b140fd37f6', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of the ''static'' keyword in C?', N'Fresher', N'The static keyword changes the storage duration and scope of a variable. A static local variable retains its value between function calls, while a static global variable limits its visibility to the current file only.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08dc6531-ea3b-4c84-826b-63b3c9531303', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the limitations of Fiber''s ''Fasthttp'' foundation regarding header keys?', N'Middle', N'Fasthttp enforces strict adherence to header formatting and case-sensitivity to avoid extra allocations during parsing. This can sometimes lead to issues if a client sends non-standard or improperly formatted headers that the standard library might handle more leniently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9eb48198-a49e-4052-88f1-63b3e87a0522', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why does Rust require explicit handling of the Result enum?', N'Junior', N'Rust enforces explicit error handling to ensure developers acknowledge potential failures. By forcing the use of Result, the language prevents common bugs caused by ignoring error states that could lead to unexpected behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f18085c-08b8-45aa-8859-63b414607f4c', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of the Service Container in Symfony, and why is it important for dependency management?', N'Middle', N'The Service Container manages the instantiation and lifecycle of objects, known as services, by injecting their dependencies automatically. This promotes decoupling, as classes do not need to know how to construct their own dependencies, making the application more modular, testable, and maintainable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'043f1abd-e09b-49b8-8b10-63b41aa283a0', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a pointer in Go?', N'Intern', N'A pointer holds the memory address of a value. Using pointers allows functions to modify the original variable rather than working on a copy, which can improve performance for large data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a13a2d2-87ab-4010-9bcd-63b489cc8525', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What are the architectural trade-offs of using Spring Boot''s embedded servlet container versus a traditional external deployment?', N'Senior', N'Embedded containers promote immutability and simplified deployment by packaging the server with the artifact, which is ideal for cloud-native microservices. However, external deployments offer better resource sharing across multiple applications on the same host and allow infrastructure teams to manage the runtime environment independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4315285e-4250-42f8-a071-63b69986573b', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between a compiler and an interpreter?', N'Fresher', N'A compiler translates the entire source code into machine code before execution, resulting in a standalone executable file. An interpreter translates and executes the source code line-by-line, which generally makes the debugging process easier but often leads to slower execution speeds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'484034c0-b4d5-42c6-b108-63b6a89c77ed', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is a covered query?', N'Junior', N'A covered query is a query where all the fields requested are present in an index. Because the database can satisfy the request entirely from the index without having to load the actual documents from disk, it is extremely fast.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36820109-769f-41a6-9915-63b7489983e2', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is a ''bundle'' in the context of Webpack?', N'Intern', N'A bundle is a single file or a small set of files generated by Webpack after processing all the modules in a project. It combines multiple source files into a format that reduces the number of network requests needed by the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c34da44a-bd9c-43a3-98d5-63b841dc8f3d', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the global keyword?', N'Intern', N'Ans. Like we saw in the previous question, the global keyword lets us deal with, inside any scope, the global version of a variable. The problem: a=7 def func(): print(a) a+=1 print(a) The solution: a=7 def func(): global a print(a) a+=1 print(a) func()', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fece391-2a9b-43e1-abf2-63ba439e329e', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Why is the distinction between ''call-by-value'' and ''call-by-name'' important for DSL design?', N'Senior', N'Call-by-name allows for the implementation of custom control structures that look like native language features, as the code block is passed unevaluated. This is essential for DSLs where delaying or conditional execution of blocks is required, though it comes with the trade-off of potentially repeated evaluation if not managed correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7eee679c-39e8-43a3-bdf5-63bd04aa74d1', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle initialization logic?', N'Intern', N'Alpine.js provides the x-init directive to run code when a component is initialized. This is useful for fetching data from an API or setting up initial values for your component state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05d2b2ec-09c1-4795-9171-63c069fb2ca5', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the implications of using ''eval()'' in JavaScript?', N'Middle', N'The ''eval()'' function executes a string as code, which poses significant security risks if the input is unsanitized. Furthermore, it prevents the JavaScript engine from performing optimizations like variable renaming or scope analysis, leading to significant performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'330ab8d6-8807-44b8-a6a5-63c14f689084', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do ''Initializer'' and ''Instance Initializer'' differ in an Ember application?', N'Senior', N'Initializers run once when the application boots to register services or modify the environment, while Instance Initializers run every time an application instance is created, such as in testing or server-side rendering. This distinction is vital for ensuring that state is properly initialized for each context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44652470-b396-48cf-84f0-63c41a4c535f', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you determine if a task should be treated as a high priority?', N'Junior', N'I assess the impact of the task on the user experience, system stability, and business objectives. If the task prevents users from accessing core features or represents a significant security risk, it is prioritized over smaller improvements or non-critical features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0983e46c-95e0-4446-a163-63c4b61540cc', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Is Astro suitable for dynamic web applications?', N'Fresher', N'Astro is best suited for content-driven sites like blogs, marketing pages, or documentation. While it can handle dynamic data, it is not primarily designed for complex state-heavy applications like a social network dashboard.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de9e4a5a-db71-42fe-bd8a-63c5935762da', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why should you prefer value types over reference types in multi-threaded environments?', N'Middle', N'Value types are copied when passed, ensuring that each thread works with its own independent instance. This eliminates the need for complex synchronization mechanisms like locks or semaphores, as there is no shared mutable state to cause data races.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01667f04-0a91-4f71-aca0-63c807c85333', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Explain the trade-offs of using Gin''s built-in Recovery middleware in a production environment.', N'Middle', N'The Recovery middleware catches panics and prevents the entire server process from crashing, which is essential for uptime. However, it should be paired with robust logging to ensure that the stack traces are captured, otherwise, critical bugs might be masked and difficult to debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3c264ac-d1c5-412d-994f-63c8b6066df5', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What does it mean for a web framework to be ''Express-inspired''?', N'Intern', N'It means the framework follows the design patterns and API structure popularized by the Node.js Express framework. This includes the use of middleware, routing mechanisms, and a clear request-response cycle that is easy for developers to understand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd16bfde5-f86d-4e91-a384-63ca0794f3b9', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the fundamental architectural difference between Vite and traditional bundlers like Webpack?', N'Middle', N'Vite leverages native ES modules in the browser to serve source code during development, eliminating the need for a full bundle on startup. Traditional bundlers process the entire application before starting the server, whereas Vite only transforms and serves files on demand as requested by the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'849dc7ab-3f73-4287-80ec-63cb4127d520', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is a Path extractor?', N'Fresher', N'A Path extractor is used to capture variables directly from the URL path. For example, if a route is defined as ''/users/{id}'', the Path extractor can pull the ''id'' value into a variable for use in the handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ff412e0-259b-4745-a6c4-63cba032644b', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Does Scala support multiple inheritance?', N'Fresher', N'Scala supports a form of multiple inheritance through traits. A class can extend multiple traits, allowing it to inherit behavior and fields from several sources, which helps avoid the complexities associated with the traditional diamond problem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51189cd4-9637-4a90-bb3c-63cc0d009452', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between an API and a Web App in ASP.NET Core?', N'Junior', N'An API typically returns data, usually in JSON format, for consumption by client applications or other services. A Web App usually returns HTML views to be rendered in a web browser, often utilizing Razor pages or MVC views.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c880dde-f3e8-408b-b351-63cd6c349f4a', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the main advantage of using type hints in a dynamically typed language like Python?', N'Middle', N'Type hints improve code readability and maintainability by making expected data structures explicit to developers and IDEs. They enable static analysis tools to catch potential type-related errors before runtime, though they do not enforce type safety during actual execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'007368bf-bc3b-4cd4-85ad-63cf4d1c18a5', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why is it important to keep the Redux state tree as shallow as possible?', N'Senior', N'Deeply nested state increases the complexity of selectors and updates, making the code harder to maintain and prone to bugs. Shallow state structures simplify data access, improve performance by reducing the depth of object traversal, and make it easier to implement granular updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d7ba37c-3b11-4dd3-b650-63d1f2ac806a', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar use type hints?', N'Intern', N'Litestar uses type hints to automatically validate incoming request data and serialize outgoing responses. By inspecting these hints, the framework ensures that the data structure matches what your application expects, reducing the need for manual validation code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20a609d0-400a-49f3-bf47-63d1ff4cbbc7', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are the trade-offs between S3 and S4 object-oriented systems in R?', N'Middle', N'The S3 system is informal, flexible, and relies on convention, making it very easy to implement for simple dispatch needs but prone to runtime errors due to a lack of strict structure. In contrast, S4 is a formal system that requires rigorous class definitions and method signatures, offering better type safety and reliability for complex, large-scale software projects. S4 provides stricter control over data integrity at the cost of significantly higher development complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e89f2080-17ad-4804-9fc8-63d2d5d6cff4', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Does Go support traditional class-based inheritance like Java or C++?', N'Intern', N'No, Go does not support traditional class-based inheritance. Instead, it uses composition through struct embedding and interfaces to achieve polymorphism and code reuse.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ebbb90d-fed7-46d4-b944-63d58e8c3204', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the role of an API Gateway in a microservices ecosystem?', N'Senior', N'The API Gateway acts as a single entry point that abstracts the internal architecture from the client, handling cross-cutting concerns like authentication, rate limiting, logging, and request transformation. It simplifies client interactions and provides a centralized point to enforce security and monitoring policies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a4d83a8-8703-49c9-9670-63d5b16f998f', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle static property declarations like ''propTypes''?', N'Middle', N'Preact supports standard property type checking if the compatibility layer is used, but it does not include built-in prop validation by default. Developers are encouraged to use TypeScript for static type checking, which is the modern standard for ensuring prop consistency without the runtime overhead of prop-types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8963ee6-b47a-4c27-af6b-63d92d7a0678', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Why is Dart''s ''spread operator'' useful for immutability?', N'Middle', N'The spread operator allows for the creation of new collections by shallow-copying the contents of existing ones, which is essential for functional programming paradigms. It enables developers to construct new lists or maps without mutating the original source, maintaining pure state transitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2279f185-f916-42aa-a1d1-63d99de0d0c2', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Describe the internal structure of a slice in Go and its performance implications.', N'Senior', N'A slice is a header containing a pointer to an underlying array, a length, and a capacity. Because slices are just descriptors, passing them to functions is cheap, but modifying the length or capacity may trigger array reallocation, which is an O(N) operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a265b3e-8c8e-4e2f-98ba-63db726ce054', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are Rails validations and where should they be placed?', N'Junior', N'Validations ensure that only valid data is saved into your database, preventing issues like empty fields or incorrect formats. They should be placed within the Model class to ensure they are enforced regardless of which controller or interface creates the record.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02484baa-f2a2-4d54-bca9-63dc9d62583d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between == and === operators', N'Fresher', N'JavaScript provides two types of equality operators: - Loose equality (==, !=): Performs type conversion if the types differ, comparing values after converting them to a common type. - Strict equality (===, !==): Compares both value and type, without any type conversion. Strict Equality (===) - Two strings are strictly equal if they have exactly the same sequence of characters and length. - Two numbers are strictly equal if they have the same numeric value. - Special cases: - NaN === NaN is false - +0 === -0 is true - Two booleans are strictly equal if both are true or both are false. - Two objects are strictly equal if they refer to the same object in memory. - null and undefined are not strictly equal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd89a11a2-1a4d-469f-8b89-63e023030980', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of the AdonisJS IoC container?', N'Intern', N'The Inversion of Control container is a central registry that manages the lifecycle of classes and objects in an application. It facilitates dependency injection, allowing components to be easily shared and managed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
