INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3690743-4702-4a46-906f-63ed54fc476d', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Discuss the trade-offs of using ''ActiveSupport::Concern'' in large-scale Ruby on Rails applications.', N'Senior', N'Concern simplifies the inclusion of modules by handling dependencies and callbacks, but it encourages a ''god-object'' pattern where business logic is scattered across various mixins. While it improves readability, deep chains of concerns can make the inheritance hierarchy opaque, increasing the difficulty of refactoring and static analysis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37ee2d2e-2259-4dfb-b53f-63f2e685ea68', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the purpose of indexes in MongoDB?', N'Fresher', N'Indexes are special data structures that store a small portion of the collection''s data set in an easy-to-traverse form. They significantly improve the speed of read operations by allowing the database to locate documents without scanning every single record.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd617ec8e-e426-4d57-a2e1-63f3386303d5', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does React Suspense integrate with the Next.js App Router to improve perceived performance?', N'Senior', N'Suspense enables streaming of partial UI components from the server to the client. Instead of waiting for the entire page to fetch data, Next.js can stream individual components as they are ready, significantly improving the Time to First Byte and the perceived loading speed for end users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'713ce33b-ac4e-45e6-9179-63f3c7caf9e6', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt ensure that state is correctly hydrated on the client side?', N'Middle', N'When data is fetched on the server, Nuxt serializes the state into the initial HTML document. When the client-side JavaScript loads, it ''hydrates'' by reading this serialized state, preventing a second data fetch and ensuring the client and server remain in sync.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
