INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdcca833-28d4-439e-81c9-6406dbe43e2c', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How are exceptions handled in Ruby?', N'Fresher', N'Ruby uses ''begin'', ''rescue'', ''else'', and ''ensure'' blocks to handle exceptions. When an error occurs within the ''begin'' block, the code execution jumps to the ''rescue'' block to handle the error gracefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3cc3070-6f26-4b51-8224-640d8a9af204', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What are Fastify ''hooks'' and when should they be used?', N'Junior', N'Hooks are lifecycle events that allow you to execute custom logic at specific points in the request-response lifecycle, such as before a handler runs or after a response is sent. They are commonly used for authentication, logging, or modifying request data globally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb5685b7-d650-46a2-8430-6413da0d441b', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is Qwik?', N'Intern', N'Qwik is a modern frontend framework designed for instant page loads by delivering minimal JavaScript to the browser. It focuses on achieving high performance by delaying the execution of code until it is actually needed by the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2e79ee6-2a94-4738-8c7c-6415f501de89', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Can you use other frameworks like React or Vue in Astro?', N'Intern', N'Yes, Astro supports ''UI Framework Integration,'' which allows developers to use components from React, Vue, Svelte, or others. Astro renders these components to static HTML on the server and only hydrates them if explicitly requested.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c664ec34-d5da-4caa-8970-64163ba1d2c8', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are middlewares in the context of NestJS?', N'Intern', N'Middleware is a function which is called before the route handler. Middleware functions have access to the request and response objects, and the next() middleware function in the application’s request-response cycle. The next middleware function is commonly denoted by a variable named next. Middlewares can be used for a variety of purposes, such as logging, authentication, and authorization. These functions are used to execute any code, make changes to the request and the response objects, end the request-response cycle, or call the next middleware function in the stack. Middlewares can perform the following tasks: 1. Execute any code. 2. Make changes to the request and the response objects. 3. End the request-response cycle. 4. Call the next middleware function in the stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f866b4cf-eda9-4cc5-a9ce-641a491578aa', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is the jQuery ''extend'' method insufficient for deep object merging in complex state management?', N'Senior', N'While jQuery''s extend is useful for simple object merging, it lacks the immutability features required for modern state management patterns like Redux. Modifying objects in place can lead to side effects and bugs in frameworks that rely on shallow comparison to determine when to re-render UI components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f81bb135-3e10-4ef4-bbca-641a8c677918', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does type inference work in Scala?', N'Intern', N'Type inference allows the Scala compiler to automatically determine the data type of an expression based on its context. This reduces the need for explicit type declarations, making the code more concise while still maintaining the benefits of static typing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d8695e3-ab70-4e7e-978e-641ae01ae301', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a situation where a user reports a bug that you cannot replicate on your local machine?', N'Fresher', N'I would ask the user for specific details like their operating system, browser version, and exact steps taken to trigger the issue. Often, differences between the development environment and the user''s environment, such as network settings or cached data, are the cause.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aafc57fa-ac61-48ad-9bd2-641bc5f07bb9', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Discuss the implications of using ''const assertions'' for object literal immutability.', N'Senior', N'Const assertions instruct the compiler to infer the most specific literal type rather than a broad primitive, effectively freezing the structure and values at the type level. This is essential for building type-safe state machines and configuration objects where the exact value is as important as the structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbe1daf7-3858-4deb-a7c5-641c128a1f6e', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle environment variables?', N'Junior', N'Remix allows you to access environment variables on the server during the build or runtime. You must explicitly expose specific variables if you want them to be accessible in the client-side bundle for security reasons.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
