INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'feae9c8b-5542-409a-a03a-641e0307bcb8', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why are NoSQL databases considered better for big data?', N'Intern', N'NoSQL databases are designed to handle distributed, large-scale data sets that do not fit neatly into rows and columns. Their architecture allows for massive parallel processing and expansion across commodity hardware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a0b7b8c-790e-4bde-914a-641f80dcb4b9', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the purpose of ''sanity checking'' an estimate?', N'Fresher', N'A sanity check involves stepping back to see if the final estimate feels logical and aligns with common sense or historical project performance. It helps catch significant calculation errors or omissions that might have occurred during the detailed breakdown. It is a final review step to ensure the estimate is defensible and realistic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
