INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ae337ae-2732-430c-ba6a-64228bd48581', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js update the UI when data changes?', N'Junior', N'Alpine.js uses a reactivity system that tracks data changes automatically. When a property defined in x-data is modified, Alpine detects the change and updates only the specific parts of the DOM that depend on that property.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7e05dc9-a3c6-4068-b0c6-642309b5d54f', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the primary advantage of a cooperative multitasking scheduler in the context of high-concurrency backend services?', N'Senior', N'Cooperative scheduling allows the runtime to switch tasks at well-defined points, such as channel operations or function calls, rather than relying on preemptive interrupts from the OS kernel. This minimizes the performance penalty of frequent context switching and enables more efficient utilization of CPU caches for active tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'745cd68c-a570-47ee-834f-6423d01a2e5d', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are header parameters in FastAPI?', N'Fresher', N'Header parameters allow you to define and extract HTTP headers from a request. You can declare them in your function parameters using the Header class to access metadata like authentication tokens or content types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'415272c3-663f-41e2-9db0-6426defac8f2', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does the ''Responder'' trait improve flexibility in Actix?', N'Middle', N'The Responder trait allows any custom type to be returned from a handler, provided it knows how to convert itself into an HTTP response. This makes it easy to return domain objects directly, as the framework handles the transformation to the appropriate status code, headers, and body format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bfb77ce-34fe-4bba-b486-64274e3a54f6', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the implications of Python''s dynamic typing system for testing?', N'Middle', N'Dynamic typing means that type errors are typically discovered at runtime rather than compile-time, necessitating more comprehensive unit and integration testing. Developers must rely on robust test suites and, increasingly, type hints with static analysis tools like Mypy to catch errors early. This approach provides flexibility but shifts the burden of type safety from the compiler to the developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7d1c559-05eb-4820-989c-6428005a88eb', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the purpose and performance implications of using ''reified'' type parameters in Kotlin.', N'Middle', N'Reified type parameters allow you to access the type information of a generic parameter at runtime, which is normally erased due to JVM type erasure. This is achieved by inlining the function and copying the actual type into the call site, though it requires the function to be marked as inline and increases the final binary size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65d26eba-d225-4853-b0b1-642a7e135814', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the difference between ''web::Data'' and other extractors?', N'Junior', N'The web::Data extractor is specifically used to retrieve shared application state that was registered during the application setup. Other extractors, such as Path or Query, are used to pull dynamic data directly from the structure of the incoming HTTP request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cd5eb68-4519-4723-9fb3-642c2147a7f0', N'4c000000-0000-0000-0000-000000000005', N'Explain the difference between synchronous and asynchronous processing.', N'Middle', N'Synchronous processing requires the client to wait for a response before proceeding, which is simple but can lead to bottlenecks. Asynchronous processing allows the system to accept a request and process it later, improving throughput and system responsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cb45dbd-f411-4b76-b90f-642e21e5a21e', N'4c000000-0000-0000-0000-000000000005', N'How does a CDN improve system performance?', N'Middle', N'A Content Delivery Network caches static content like images and CSS files on geographically distributed servers closer to the end user. By reducing the physical distance data must travel, it significantly lowers latency and offloads traffic from the origin server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7571a91-fa8a-404f-99f3-642f515310f9', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the purpose of the ''hooks.server.js'' file in a SvelteKit application?', N'Middle', N'Hooks act as an entry point for every request made to the server, allowing developers to intercept the request and response lifecycle. It is commonly used for authentication checks, setting custom headers, or modifying the response before it is sent to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5168de1-2300-4afc-8a80-6437fc1fc520', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is data security considered a design-level decision rather than an afterthought?', N'Intern', N'Integrating security at the design phase ensures that protections like encryption, access control, and logging are woven into the system architecture. Retrofitting security into a finished system is significantly more difficult, expensive, and prone to human error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
