INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'038004b5-889e-4b49-983a-64387e07c35d', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the primary architectural goal of Fastify?', N'Junior', N'The primary goal of Fastify is to provide a highly performant web framework with minimal overhead. It achieves this by focusing on low architectural overhead and efficient plugin architecture to handle requests faster than traditional frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70774105-9b8b-4917-a499-643946f63f0e', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Describe the impact of PHP''s ''share-nothing'' architecture on web development.', N'Middle', N'The share-nothing architecture means that every request starts with a clean slate, with no shared state between requests unless explicitly stored in external systems. This design inherently simplifies scaling, as any server can handle any request, but it necessitates external state management for user sessions and caches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28d646ff-e3c0-4fab-98aa-6439b1344e6d', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Read Repair help maintain consistency in Cassandra?', N'Senior', N'Read Repair compares the data versions returned by multiple replicas during a read request. If a discrepancy is detected, the coordinator initiates a write to the out-of-date replicas to synchronize them, ensuring consistency without requiring an explicit anti-entropy repair process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8573b957-e23a-4734-98fe-643a870a7d87', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why would you use a proxy server like Nginx in front of an Express app?', N'Middle', N'Nginx acts as a reverse proxy to handle SSL termination, load balancing, static file serving, and caching. This offloads resource-intensive tasks from the Express application, improving performance and adding an extra layer of security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c34aeeb-3ae1-40dd-a0ac-643d981dfe39', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why is it dangerous to use Redis as a message broker without considering memory limits?', N'Senior', N'If message producers outpace consumers, the memory usage of the list or stream can grow unboundedly until the server triggers an eviction policy or crashes. This requires implementing strict monitoring and potentially using capping strategies like trimming streams to prevent memory exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad693b61-a677-4ec1-8975-643eb5b4f31e', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are the advantages of using sub-applications (APIRouter) in FastAPI?', N'Middle', N'APIRouter allows you to organize your application into smaller, modular components based on domain logic. This improves code maintainability, enables grouping of shared dependencies or prefixes, and makes the codebase easier to navigate as it grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'788f03d2-a5ae-4b5f-a4e4-643fd1a08f5c', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What happens if a network connection is lost during a transaction?', N'Junior', N'If the connection is lost before a commit, the database server will eventually detect the timeout or disconnect. The transaction will then be automatically rolled back to maintain the integrity of the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c7d4dee-c60e-40f1-9a25-6442b95c95f5', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does Python handle ''name mangling'' in classes, and what is its intended purpose?', N'Senior', N'Name mangling is a mechanism where attributes prefixed with two underscores are automatically renamed to include the class name. This is intended to prevent name clashes in subclasses, not to enforce true private access. It acts as a safety mechanism for internal class members rather than a strict security barrier.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea6377b2-7171-44a3-83e9-6443ca191b4a', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the default isolation level in many SQL databases?', N'Junior', N'Many relational databases, such as SQL Server or PostgreSQL, default to ''Read Committed'' isolation. This level prevents dirty reads but allows non-repeatable reads and phantom reads to occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38dae976-15c5-4633-95fc-6444a919bdc5', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between local variables and global variables regarding storage class?', N'Middle', N'Local variables are typically stored on the stack and have automatic storage duration, meaning they are created when a function is entered and destroyed when it exits. Global variables have static storage duration and are stored in the data or BSS segment, existing for the entire duration of the program''s execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'572d17b5-15e5-4c91-a604-64451b33cf5e', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What are the architectural considerations when implementing a ''Bulkhead'' pattern?', N'Senior', N'The bulkhead pattern isolates elements of an application into separate pools so that if one fails, the others continue to function. Implementing this requires careful resource partitioning, such as using separate thread pools, memory regions, or distinct database instances to limit the blast radius of failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c20ac52e-5871-4fc7-b469-6447050ab728', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is Dependency Injection (DI) and why is it used?', N'Middle', N'DI is a design pattern where a class receives its dependencies from an external source rather than creating them itself. This promotes loose coupling, enhances testability by allowing for easier mocking, and simplifies the management of object lifetimes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2aea201d-37b7-4346-98fc-6447208e9043', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the purpose of the Quarkus ''Dev Mode'' and how does it improve developer productivity?', N'Middle', N'Dev Mode enables hot reloading, where changes in the source code are automatically detected and applied without restarting the application process. This drastically shortens the feedback loop by keeping the application container running while updating only the modified classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0220440-4517-4a4f-aa6e-64480db4fd6c', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the trade-offs of using synchronous versus asynchronous replication?', N'Middle', N'Synchronous replication ensures that a transaction is not considered committed until the standby has acknowledged the data, preventing data loss at the cost of higher latency. Asynchronous replication offers better performance by allowing the primary to commit immediately, but carries a risk of data loss if the primary fails before the changes reach the standby.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a1905bd-c498-4e9b-bd4a-644944565728', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is an R environment?', N'Intern', N'An environment in R is a data structure that functions like a collection of symbol-value pairs. It acts as the context or scope in which variables are stored and looked up during code execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a414ccb7-a60f-4c40-9d1e-644c42fce3e9', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the architectural role of a ''Security Information and Event Management'' (SIEM) system in a cloud environment?', N'Senior', N'A SIEM centralizes logs from infrastructure, applications, and network components to provide real-time analysis and alerting on security threats. It is critical for detecting patterns of malicious activity that are not visible when looking at individual service logs, such as lateral movement or credential stuffing attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65d5c796-be30-4316-a19b-644caae5e868', N'a2838158-7305-480a-b22b-4dc35776b400', N'Define ''Backpressure'' and explain why it is vital in stream processing.', N'Senior', N'Backpressure is a feedback mechanism where a consumer signals to a producer that it is being overwhelmed and needs the rate of data flow to decrease. It is vital in distributed stream processing to prevent buffer overflows, excessive memory usage, and eventual system crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8355734d-744d-40d8-ad84-644de36f0ab4', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the impact of ''Compaction'' strategy on read amplification?', N'Senior', N'Compaction merges multiple SSTables to remove duplicates and tombstones. Aggressive compaction reduces read amplification by limiting the number of files a read request must scan, but it increases write amplification and CPU usage due to the constant merging of background files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fba54f25-26d4-4784-b72e-64535cadb74e', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the purpose of logging in an application?', N'Intern', N'Logs provide a historical record of events within an application, which is vital for troubleshooting errors and understanding user behavior. They allow engineers to reconstruct the sequence of events leading up to a crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc9b05da-52ba-4ee9-b41a-6453b7be301b', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why is ''splitProps'' necessary when building reusable components in SolidJS?', N'Senior', N'Since reactive properties must be accessed via getters to maintain their reactivity, standard JavaScript destructuring would break this connection. splitProps allows developers to safely destructure props into multiple objects while preserving the underlying signal getters, ensuring reactivity remains intact.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6e41dfd-e1b2-429f-8d27-64545f3e3620', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How do you implement authentication in Rocket?', N'Middle', N'Authentication is best implemented using Request Guards. A guard verifies the token or session cookie from the request headers and returns the authenticated user object, allowing handlers to assume the user is authorized if the guard successfully executes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'958ca521-4e9e-40a5-84c5-64550eea3275', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How do you retrieve a URL parameter inside a handler in Chi?', N'Junior', N'You use the chi.URLParam function, passing the request object and the parameter key defined in the route. It returns the value as a string, which you then parse or convert as needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9158fa0-2789-4340-9b59-645629a8ec73', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is meant by the ''Iron Triangle'' of project management in engineering?', N'Intern', N'The Iron Triangle refers to the constraint of scope, time, and cost. It implies that changing one of these factors inevitably impacts the others, forcing a trade-off to maintain the project''s feasibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ef42fe1-d749-48a3-8eb5-6456901cef47', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What does async and defer refer in script tag?', N'Intern', N'1. Async: Downloads the script file during HTML parsing and will pause the HTML parser to execute it when it has finished downloading. Example: 2. Defer: Defer downloads the script file during HTML parsing and will only execute it after the HTML parser has completed. Not all browsers support this. Example: The async attribute is used to indicate to the browser that the script file can be executed asynchronously. The HTML parser does not need to pause at the point it reaches the script tag to fetch and execute, the execution can happen whenever the script becomes ready after being fetched in parallel with the document parsing. The defer attribute tells the browser to only execute the script file once the HTML document has been fully parsed. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b0fa830-406d-4d86-980f-6456a2ff80d6', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle status codes?', N'Fresher', N'FastAPI allows you to specify a status code for each response using the ''status_code'' parameter in the decorator. If not specified, it defaults to 200 for successful requests, but you can explicitly define others like 201 for created or 404 for not found.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3db96ca8-60f0-43ea-87b8-645798ac9f33', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle query string parsing?', N'Fresher', N'Fastify uses a fast query string parser by default to convert URL parameters into JavaScript objects. This parsing happens automatically before the request reaches the handler, ensuring that data is ready for immediate use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0097d3c0-5ea6-4af7-b6e5-6458409725e0', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason about data consistency in a multi-region deployment?', N'Senior', N'I evaluate the business requirement for read-after-write consistency versus the need for low-latency access. I would choose between synchronous replication, which impacts latency, and asynchronous replication, which risks data loss during regional failure, based on the specific tolerance of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'579d7290-fa84-4fe7-a856-645a6df2b804', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Explain the difference between Quarkus extensions and traditional Java libraries.', N'Middle', N'Quarkus extensions are more than just libraries; they contain metadata that informs the Quarkus build tool how to integrate, configure, and optimize the library for the Quarkus runtime. This allows third-party frameworks to benefit from build-time optimization and native image support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0ae59ec-55d3-4fc0-9b83-645af7413b33', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the ''module'' property in a Webpack configuration?', N'Fresher', N'The module property is used to define the rules for how different types of files are handled. Within this property, you specify which loaders should be applied to specific file types based on their extension.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea16699e-1d92-42b7-956e-645c63f66ad7', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of a ''before_action'' filter in a controller?', N'Junior', N'A before_action is a callback that runs a specific method before a controller action is executed. It is commonly used for tasks like enforcing authentication, authorizing users, or setting up shared variables for multiple actions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94e08863-9bd9-4417-bb14-645deb3f37e1', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the benefit of a ''minimal reproduction'' of a bug?', N'Fresher', N'A minimal reproduction strips away all non-essential code and configuration, leaving only the parts necessary to trigger the bug. This makes it significantly easier to isolate the cause and allows others to verify the fix without dealing with unrelated complexities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac8e2a5b-17bf-4334-9c1e-64627b5b4bdd', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Describe the role of descriptors in Python''s object model.', N'Middle', N'Descriptors are objects that define how attribute access, assignment, and deletion are handled in other classes. By implementing the descriptor protocol, developers can intercept attribute lookups to add custom logic like validation, caching, or computed properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fdafa9d-dde6-4f75-bf48-646544124eee', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What does ''untrack'' do in SolidJS?', N'Intern', N'The untrack function allows you to read a signal''s value without creating a reactive dependency. This is useful when you want to access a value inside an effect without the effect re-running when that value changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87dda9a8-6355-489b-adc0-646a34698a4c', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between a HashMap and a TreeMap?', N'Junior', N'A HashMap provides constant-time performance for basic operations and does not guarantee the order of elements. A TreeMap stores elements in a sorted order based on their keys, but operations take logarithmic time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c0335aa-154d-47d4-b7cd-646d42a49542', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between a relational database and a NoSQL database for a new project?', N'Intern', N'A relational database is preferred when data is highly structured and requires strong consistency through ACID transactions. NoSQL is a better choice when dealing with unstructured data, rapid growth requirements, or horizontal scaling needs where strict schema compliance is less critical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b0fbcf2-1172-4dac-9726-646d48ee4816', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does virtual DOM in React work? What are its benefits and downsides?', N'Fresher', N'The virtual DOM in React is a lightweight copy of the actual DOM. When the state of a component changes, React creates a new virtual DOM tree and compares it with the previous one using a process called "reconciliation." Only the differences are then updated in the actual DOM, making updates more efficient. The benefits include improved performance and a more declarative way to manage UI. However, it can add complexity and may not be as performant for very simple applications. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7cc7270-920d-4eb3-9807-646d65266725', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is meant by ''Zero Config'' in Quarkus?', N'Intern', N'Zero Config refers to the framework''s ability to provide sensible defaults, minimizing the amount of manual configuration a developer needs to write. It enables the application to work immediately with minimal setup for common use cases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab23b978-f8de-45f4-a898-646e60fc1ae6', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain the significance of the ''working set'' in MongoDB sizing.', N'Middle', N'The working set represents the subset of data and indexes that the application accesses most frequently. For optimal performance, the server should have enough RAM to keep the entire working set in memory to avoid costly disk I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f21580b-2979-470c-863e-646e65ef839b', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does the ''onMount'' lifecycle hook behave in SolidJS compared to ''useEffect'' in React?', N'Middle', N'onMount runs only once when the component is first rendered and inserted into the DOM. Unlike useEffect, which requires a dependency array and can trigger multiple times or respond to state changes, onMount is strictly for setup logic that needs to occur exactly once during the initial mount phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fcda5cf-51f7-461a-896c-646e90dea6c3', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do context managers interact with the interpreter''s exception handling mechanism?', N'Senior', N'Context managers use the __exit__ method to guarantee that cleanup operations occur regardless of whether an exception is raised within the block. This ensures robust resource management for external handles like files or network sockets, effectively acting as an automated finally block.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e296bdbc-e9a6-4976-b170-646f850f1c63', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What are Micronaut Advice annotations?', N'Fresher', N'Advice annotations, such as @Around or @Async, are used for Aspect-Oriented Programming (AOP). They allow developers to add cross-cutting concerns like logging, transaction management, or retries without modifying the core business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'938e164f-c4b2-4d1d-af0b-646fd7c60b15', N'4c000000-0000-0000-0000-000000000005', N'What is the main advantage of using a GraphQL API over REST?', N'Middle', N'GraphQL allows clients to request exactly the data they need in a single round trip, preventing over-fetching or under-fetching. This is more efficient for mobile clients with limited bandwidth compared to REST, which often requires multiple requests to different endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
