INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'004c5795-5d80-4b69-8b8b-64722646b40a', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain the difference between absolute and relative units in CSS and their importance for accessibility.', N'Senior', N'Absolute units like pixels are fixed, which can lead to poor readability if users adjust their browser''s default font size. Relative units like rem and em are proportional to the user''s settings, ensuring that the interface scales gracefully and remains accessible to users with visual impairments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35266c81-185f-48b0-9485-6474d315e3e0', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the ''Optimizer'' in the Qwik ecosystem?', N'Middle', N'The Optimizer is a build-time tool that automatically transforms code to enable lazy loading. It extracts component logic into separate chunks, allowing the framework to only download the code needed for a specific interaction instead of the entire bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c6c72e1-d42c-44ff-92dd-647a594796f5', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is cookies in html5?', N'Intern', N'A cookie is an amount of information that persists between a server-side and a client-side. A web browser stores this information at the time of browsing. A cookie contains the information as a string generally in the form of a name-value pair separated by semi-colons. It maintains the state of a user and remembers the user''s information among all the web pages. Example 01: Create a Cookies Example 02: Cookie with expiry date Example 03: Read Cookie Example 04: Update Cookie Example 05: Delete Cookie', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5679df28-159f-4bd4-a85f-647da252e0b5', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the role of the Sort Key?', N'Intern', N'The sort key allows you to store and query related data items together in a specific order within the same partition. It enables efficient retrieval of ranges of data, such as finding all orders placed by a specific user within a certain date range.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'257711b2-d6e2-41ac-8e9e-64855b1e7426', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel handle CSRF protection for API-based authentication?', N'Senior', N'For stateful web sessions, Laravel uses CSRF tokens to verify requests. However, for token-based API authentication like Sanctum or Passport, CSRF protection is typically disabled for the API routes, as these rely on ''Authorization'' headers which are not automatically sent by the browser in the same way as cookies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c222ffc5-da6d-4221-9717-64855bbf1819', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the ''ErrorBoundary'' component in Remix?', N'Intern', N'The ErrorBoundary is a special component that catches errors occurring during the rendering or data loading process for a specific route. It prevents the entire application from crashing and allows you to display a fallback UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cf2b50a-19b4-431b-87fb-6487231e933c', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do you test asynchronous behavior in Ember?', N'Middle', N'Ember''s testing framework provides specialized test helpers that automatically wait for the Run Loop to settle and for data promises to resolve. This ensures that assertions are only made after all pending background operations have completed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'095bdc67-1596-4cab-b6de-6487999ce724', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do time-stamping mechanisms ensure transaction ordering in a distributed environment?', N'Senior', N'Global timestamps allow nodes to order operations chronologically, ensuring that transactions respect the order in which they arrived. Challenges include clock skew between nodes, which is often addressed using hardware-assisted clocks, logical clocks like Lamport timestamps, or hybrid logical clocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf5368d3-0438-412b-b1b1-648bb6752100', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is an Isolation Level?', N'Intern', N'An isolation level defines the degree to which one transaction must be isolated from data modifications made by other concurrent transactions. Higher isolation levels provide more data integrity but can reduce system performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fb4bca9-8a5b-40a9-9102-64921927ef68', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does header-based caching work in HTTP?', N'Middle', N'HTTP caching uses headers like Cache-Control, ETag, and Last-Modified to instruct browsers and intermediate proxies on how to cache resources. By validating resources with ETags, the system can avoid re-downloading data if the server confirms the resource has not changed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19c00554-1fef-408e-bdfb-6492cb86bc37', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How would you handle distributed transactions in a microservices architecture using Spring Boot if you cannot use XA/JTA?', N'Senior', N'You should implement the Saga pattern, using either choreography-based events or orchestration-based command coordination. This approach ensures eventual consistency across services by managing local transactions and compensating transactions in case of failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
