INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd276a592-fa0d-42f0-8fc1-64af2dcb769d', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do database systems ensure the Atomicity property in ACID compliance during a system crash?', N'Middle', N'Atomicity is typically maintained through Write-Ahead Logging (WAL). Before any data is modified on the disk, the changes are recorded in a log; if a system crashes mid-transaction, the database uses these logs to roll back incomplete operations or replay committed ones during the recovery process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
