INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d86328e-b53d-49e7-a7f4-64b9be5d70bd', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is it often inefficient to query the DOM repeatedly within a loop using jQuery?', N'Middle', N'Every time you call a jQuery selector, the library must traverse the DOM tree, which is a computationally expensive operation. Caching the selector result in a variable outside the loop significantly improves performance by reducing the number of costly DOM lookups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
