INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd42bf43f-4a40-4d20-9845-64be177007df', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Discuss the architectural strategy for handling ''any'' types in a legacy codebase migrating to strict mode.', N'Senior', N'The strategy involves a tiered approach: utilizing ''unknown'' as a type-safe top type to force narrowing, implementing incremental strictness via config overrides, and employing automated linting to gradually replace ''any'' with specific interfaces. This prevents a ''big bang'' migration that would paralyze development, focusing instead on stabilizing interfaces at the boundaries of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22a42db5-e34b-46cf-ba9a-64c041d4135a', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Why would you choose to use a Form Action in SvelteKit over a standard fetch request?', N'Middle', N'Form Actions provide a native way to handle data mutations that works even if JavaScript is disabled in the browser. They simplify state management by utilizing the native browser form submission lifecycle and automatically integrate with SvelteKit''s built-in progressive enhancement features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5a04f73-64e1-4525-b967-64c104d5b7f0', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why is ''Tail Latency'' a critical metric for NoSQL databases at scale?', N'Senior', N'Tail latency measures the performance experienced by the slowest percentage of requests, which often determines the overall responsiveness of a distributed application. In large-scale systems, a single slow node can disproportionately increase tail latency, necessitating strategies like speculative execution or hedging requests to mask these outliers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'775832cc-153c-4b35-b350-64c2b6433689', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Describe the impact of ''Indexes'' on write performance.', N'Senior', N'While indexes dramatically improve read performance, they introduce overhead on every insert, update, or delete operation because the database must update the index structures in addition to the data pages. Excessive indexing can lead to significant write amplification and degradation of overall system performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02f09f7f-baa1-4f22-98ec-64c4120b4c96', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the Go runtime handle stack growth for goroutines?', N'Senior', N'Go goroutines start with a small, contiguous stack that is dynamically resized as needed. When a stack overflow is detected, the runtime allocates a new, larger memory segment and copies the existing stack frames to the new location, updating pointers to reflect the change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f85da262-5270-4e4b-9572-64c489575d49', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle CORS (Cross-Origin Resource Sharing) at the middleware level?', N'Senior', N'CORS is effectively managed in Chi by applying a global or group-specific middleware that inspects the Origin header and sets the appropriate Access-Control headers. This centralized approach ensures consistent policy enforcement across the entire application or specific API segments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'908ddbba-4adf-46b7-af1b-64c81099b157', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between @Component, @Service, and @Repository in Spring Boot?', N'Middle', N'Technically, they are all specialized versions of @Component used for component scanning. @Service is used for business logic layers, and @Repository is specifically for DAO layers, offering automatic exception translation for database-related errors. Using these specific annotations helps with code readability and allows for future AOP features or framework enhancements to target specific layers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5019f2e-674c-4cbb-89b7-64caefcbff74', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach observability design for a distributed system to ensure actionable incident response?', N'Senior', N'I focus on the triad of metrics, logs, and distributed tracing, ensuring they share a common correlation ID. I emphasize high-cardinality metrics for debugging and structural logs for auditing, while ensuring that the observability pipeline itself is sampled appropriately to avoid massive ingestion costs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2ae1f90-569f-4e31-b4f5-64d4b470cf5e', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is an index in PostgreSQL and why is it used?', N'Intern', N'An index is a data structure that improves the speed of data retrieval operations on a table. Without an index, PostgreSQL must perform a full table scan to find specific rows, which is slow for large datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0262799-85be-494e-a51c-64d4d7dde26f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the advantages of using ''Discriminated Unions'' over simple union types?', N'Senior', N'Discriminated unions include a common literal property, called a tag, which allows the compiler to narrow the entire union type based on the tag''s value. This leads to exhaustive type checking in switch statements and more readable, type-safe logic compared to checking for the existence of unique properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bef8a4a-62d9-4601-a243-64d66149a1eb', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the role of the ''volatile'' keyword regarding the memory model.', N'Senior', N'Volatile prevents the compiler and hardware from reordering memory access operations and ensures that the most recent value is always read from main memory. It provides a lightweight synchronization mechanism for simple flag-based signaling, but it does not provide atomicity for complex operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f48f9adb-994a-4797-90f9-64d7cc8d1548', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the role of the ''Depends'' function?', N'Intern', N'The ''Depends'' function is used to declare a dependency in the function arguments of an endpoint. It instructs FastAPI to execute the dependency function and provide its return value to the endpoint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e239279-8aba-40ee-b96c-64d8ba739da0', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s middleware chain implementation differ from standard net/http middleware patterns?', N'Senior', N'Echo utilizes a custom chain of handlers where each middleware wraps the next handler in a recursive-like structure. This allows for fine-grained control over the request-response lifecycle compared to the standard net/http middleware which relies heavily on wrapping the entire ServeHTTP method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'896bfe5a-90c1-47cd-93c5-64d94477f4a5', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do JavaScript closures affect memory management, and what is a ''memory leak'' scenario involving them?', N'Senior', N'Closures retain references to their lexical environment, preventing garbage collection of variables within that scope as long as the closure exists. A memory leak occurs when closures are unnecessarily attached to long-lived objects, preventing the garbage collector from reclaiming memory for large datasets that are no longer needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b1b6395-bef5-402e-b4b3-64dc6d3acf42', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the concept of ''Strong Parameters'' in Rails.', N'Junior', N'Strong Parameters is a security feature that prevents malicious users from submitting unexpected data to your application. It requires developers to explicitly define which attributes are permitted to be mass-assigned from the request parameters to a model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b926d755-b1a7-4be9-b5ec-64de80d69d89', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are the performance implications of Svelte''s ''if'' and ''each'' blocks?', N'Middle', N'Svelte''s control flow blocks are compiled into efficient DOM manipulation instructions rather than being evaluated at runtime. This results in direct, optimized updates to the specific DOM nodes affected by the change, avoiding the overhead of re-rendering entire lists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39ab06f1-2a27-4073-ac7b-64dff8e48c96', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web''s ''Extractor'' pattern work?', N'Senior', N'Extractors are a mechanism that automatically parses and validates request data, such as headers, JSON bodies, or query parameters, before passing them to a handler. This separates the concern of input parsing from business logic, ensuring handlers only receive well-formed, typed data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea486764-e153-4030-9613-64e3710ad405', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the primary performance advantages of Log-Structured Merge (LSM) trees over B-trees for write-heavy workloads?', N'Senior', N'LSM trees transform random writes into sequential disk I/O by buffering updates in memory and flushing them to sorted files on disk. This avoids the random seek penalty associated with B-tree page updates, making LSM trees significantly more efficient for high-throughput ingestion workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e31a11b1-6791-4626-8a39-64e53102b3f6', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix approach ''Error Boundaries''?', N'Middle', N'Remix uses Error Boundaries to handle runtime errors at specific levels of the route hierarchy. If a route or its nested component fails, the ErrorBoundary component renders instead of the entire page, allowing the rest of the application to remain functional.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e137b54a-090b-4f45-a1c7-64e5e98a5c2a', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you handle API versioning, and what are the pros and cons of URI versioning?', N'Middle', N'API versioning can be handled via URI, header, or media type. URI versioning is the most common and visible approach, making it easy to route traffic and cache responses, but it breaks the principle that a URI should represent a resource rather than a specific version of that resource.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b12437e-e016-4115-b6cc-64e878ddc2cd', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R manage memory compared to low-level languages like C++?', N'Middle', N'R manages memory automatically through a garbage collector, which tracks object references and frees memory when it is no longer in use. While this prevents manual memory management errors like memory leaks or dangling pointers, it provides less control over performance and memory allocation patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa5489e4-a82e-4a5d-b8dd-64e8c0daf98d', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the purpose of a Dead Letter Queue (DLQ) and how should it be monitored in a high-scale architecture?', N'Senior', N'A DLQ stores messages that cannot be processed after multiple attempts, preventing ''poison pills'' from blocking the main pipeline. Monitoring should focus on the rate of entry and root cause analysis, as a growing DLQ indicates systemic failures in consumer logic or data schema compatibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
