INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80f45f7c-c6d5-4024-b72b-64e8f611f0a5', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is an empty statement and purpose of it', N'Intern', N'The empty statement is a semicolon (;) indicating that no statement will be executed, even if JavaScript syntax requires one. Since there is no action with an empty statement you might think that it''s usage is quite less, but the empty statement is occasionally useful when you want to create a loop that has an empty body. For example, you can initialize an array with zero values as below,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc0f059d-44a8-48c7-90f1-64eb4dcc0244', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the benefit of using AJV with Fastify?', N'Intern', N'AJV is a high-performance JSON schema validator used by Fastify to check the structure of incoming data. It ensures that the data meets the requirements defined in your schemas before the handler function is even executed, reducing errors and improving security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36e0dc06-be72-4300-a41f-64ee3e387daf', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What causes ''Lock Wait Timeout'' in high-traffic MySQL systems?', N'Senior', N'This usually occurs when a transaction holds an exclusive lock on a row or index range, and other transactions are queued behind it for too long. It is often a symptom of long-running queries, poor transaction management, or contention on heavily accessed indexes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70e13ef9-d389-4d5c-ba7e-64f005d24512', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the difference between ''throws'' and ''rethrows'' in Swift functions.', N'Middle', N'A function marked ''throws'' indicates it can throw an error during execution. A function marked ''rethrows'' is used when the function only throws if one of the closures passed into it throws, allowing the compiler to omit error handling if the provided closure is guaranteed not to throw.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e207180c-a5a7-42cf-b24f-64f352f00cdf', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the use of stopPropagation method?', N'Intern', N'The stopPropagation method is used to stop the event from bubbling up the event chain. For example, the below nested divs with stopPropagation method prevents default event propagation when clicking on nested div(Div1)', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5880318c-f8bf-472c-bc6f-64f6a2e9a2c9', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Can TypeScript be used for server-side development?', N'Fresher', N'Yes, TypeScript is widely used for server-side development through Node.js. Since TypeScript compiles to JavaScript, it can be executed in any environment that runs JavaScript, including servers, after the transpilation process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7967b54a-55c6-44ba-83ba-64f722ab5549', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What strategy would you employ to manage data lifecycle and storage costs in large-scale Elasticsearch deployments?', N'Senior', N'I would implement Index Lifecycle Management (ILM) policies to automate moving indices through Hot, Warm, Cold, and Frozen phases based on age or size. This strategy offloads older, less frequently accessed data to cheaper storage tiers and uses searchable snapshots to reduce the total storage footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3dd4c098-a29b-47a7-808a-64f867f6330e', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the difference between an ''associated type'' and a ''generic parameter'' in a trait?', N'Senior', N'Associated types are fixed for a specific implementation of a trait, making the API cleaner and enforcing a single implementation per type. Generic parameters allow a type to implement the same trait multiple times with different types, providing more flexibility at the cost of more complex type signatures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd427318-56db-45d2-9021-64f879ff9d59', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the benefit of a ''post-mortem'' or ''incident report'' after a major system failure?', N'Middle', N'A post-mortem shifts the focus from blaming individuals to understanding systemic weaknesses and gaps in the existing safety nets. By documenting the incident timeline, root cause, and remediation steps, the team can implement preventative measures to stop the issue from recurring. It fosters a culture of continuous improvement and shared knowledge within the engineering team.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e9038e7-9d40-4b82-9446-6501dac41a41', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the security considerations when accessing DynamoDB?', N'Middle', N'Access to DynamoDB is managed via IAM policies, which enforce fine-grained permissions at the table and even attribute level. It is also recommended to use VPC endpoints to keep traffic within the AWS network and enable encryption at rest to protect sensitive data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14519166-4b16-4aca-9770-6502e2dc1333', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the significance of the loader function being ''read-only''?', N'Middle', N'Loaders are intended for data retrieval only, which allows the framework to safely pre-fetch data or re-run loaders without side effects. This separation of concerns ensures that state mutations are strictly handled by actions, preventing accidental data modification during navigation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed8c3084-d9b6-40bd-855f-65034b7924a6', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the purpose of the ''app.Listen'' method?', N'Fresher', N'The ''app.Listen'' method starts the HTTP server on a specified port and begins listening for incoming connections. It blocks the main thread, keeping the application running until it receives a shutdown signal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b144d71a-5847-4648-972a-6504534f44ab', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of ''std::move'' and why does it not actually ''move'' anything?', N'Senior', N'std::move is a cast that converts an lvalue to an rvalue reference, signaling that the object is a candidate for a move operation. It does not perform any data transfer itself; rather, it allows the compiler to select the move constructor or move assignment operator, which then performs the actual resource transfer by stealing the internal state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ec5ee49-95bd-4dd6-8bc2-6505e55a0561', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is babel', N'Intern', N'Babel is a JavaScript transpiler to convert ECMAScript 2015+ code into a backwards compatible version of JavaScript in current and older browsers or environments. Some of the main features are listed below, 1. Transform syntax 2. Polyfill features that are missing in your target environment (using @babel/polyfill) 3. Source code transformations (or codemods)', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43f5147e-68e7-40ba-9b58-6505ec6eee06', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How do you handle errors in Actix-web request handlers?', N'Junior', N'Actix-web handlers can return a Result type that implements the ResponseError trait. This allows you to map internal errors into specific HTTP status codes and error messages for the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b62237e5-01ca-43b1-864a-650662ae8f78', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the role of the Django View?', N'Fresher', N'A view is a Python function or class that receives a web request and returns a web response. It acts as the bridge between the model, which handles the data, and the template, which handles the presentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89c11f44-d8cc-4072-8f39-650ae82f7fce', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle exceptions globally, and why is this useful for robust API design?', N'Senior', N'FastAPI provides exception handlers that catch specific error types throughout the application. This allows developers to standardize error responses, ensuring that the client always receives a predictable JSON structure even when unexpected server-side failures occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6551ee7e-b0f1-49ea-98c7-650b82781456', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How can partitioning strategies like consistent hashing improve system scalability?', N'Middle', N'Consistent hashing allows for distributing data across a cluster of servers while minimizing remapping when nodes are added or removed. This ensures that the system remains balanced and stable as it scales horizontally, preventing massive data reshuffling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7765c84-1a50-4237-b526-65154008da9e', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do database systems recover from a crash while a transaction is in progress?', N'Senior', N'Using the ARIES recovery algorithm, the database performs three phases: Analysis, Redo, and Undo. The system replays the log to restore the state to the point of failure and then rolls back any transactions that were active but not committed, ensuring the database returns to a consistent state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8845d190-f929-49d9-85f8-6515a7f28108', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How can ''Tree Shaking'' be negatively affected by non-ESM imports?', N'Senior', N'Tree shaking depends on the static nature of ES modules. If a project uses CommonJS require statements, the compiler cannot definitively determine which parts of the module are used, causing it to include the entire module in the bundle to avoid breaking potential dynamic references.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4efaaf4-aaa8-4fc5-82d3-651773a7ebe8', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of ''children'' in SolidJS components?', N'Intern', N'The children property is a special prop that allows a component to receive and render the elements passed between its opening and closing tags. It is typically used for layout components like wrappers or cards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1120c372-80b2-446c-99fd-6517f54d4c3c', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Explain server-side rendering of React applications and its benefits', N'Fresher', N'Server-side rendering (SSR) in React involves rendering React components on the server and sending the resulting HTML to the client. The browser displays that HTML immediately, then hydrateRoot attaches event handlers so the page becomes interactive. Modern React supports streaming SSR via renderToPipeableStream (Node) and renderToReadableStream (Web), and React Server Components let parts of the tree render only on the server. Benefits include faster perceived loads and better SEO; tradeoffs include a slower TTFB, the cost of hydration, and the risk of hydration mismatches. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98aeae9a-9bff-4d9b-8a32-65189d0882aa', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How do R''s closures facilitate functional programming?', N'Middle', N'Closures are functions that capture and store the environment in which they were created, including the values of local variables. This allows for the creation of function factories and maintains state across multiple calls without needing global variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'085aa2cb-e9bb-4361-aa43-651be8a7ec24', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the purpose of ''loading'' states in SvelteKit?', N'Fresher', N'Loading states allow you to provide visual feedback to users while data is being fetched. Because SvelteKit handles routing asynchronously, you can display spinners or skeleton screens to improve the user experience during network delays.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e215adf-fd65-461b-bd13-651c16d36c8d', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the advantage of using a ''controller'' pattern in an Express application?', N'Middle', N'The controller pattern separates the routing logic from the business logic. It improves code organization by keeping route files clean and focusing them purely on request handling, while delegating complex operations to service layers or controllers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
