INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c92eec1-f71d-4447-a93e-65211c2660fc', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach a problem that seems impossible to solve with the resources you have?', N'Intern', N'I would start by re-evaluating the requirements to see if any can be relaxed or simplified. I would then research alternative, more efficient ways to achieve the desired outcome or reach out for guidance to see if I am missing a fundamental concept. Breaking the problem into smaller, more achievable milestones often makes an overwhelming task manageable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec64c946-a771-43f6-90b1-6522b61218e7', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you isolate a problem when a system is failing but the error message is generic?', N'Fresher', N'You should use the process of elimination by isolating components. Disable features or modules one by one to see if the error persists, which helps narrow down whether the issue lies in the input, the logic, or the environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'161a5d4f-c8be-492e-b748-65242891a700', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the role of Response Caching middleware in ASP.NET Core?', N'Senior', N'Response Caching middleware enables the server to store and serve responses based on defined criteria, reducing the load on backend processing. It relies on standard HTTP headers like Cache-Control and Vary to determine if a request can be satisfied from the cache, improving overall system throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
