INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5046777d-e434-4052-8839-652711629bf0', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What does it mean for a variable to be immutable by default in Rust?', N'Intern', N'In Rust, once a value is bound to a variable, you cannot change that value unless you explicitly mark the variable as mutable. This default behavior promotes safer code by making it clear which parts of your program are intended to change state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'328867b5-8880-4467-9745-652817129a48', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'You are tasked with redesigning a high-throughput microservices architecture that is currently suffering from cascading failures during traffic spikes. How do you approach diagnosing and mitigating this architectural bottleneck?', N'Senior', N'I would start by implementing distributed tracing and observability to identify the specific service or resource contention point causing the latency amplification. My mitigation strategy would focus on decoupling services through asynchronous messaging patterns and implementing circuit breakers and bulkhead patterns to prevent failure propagation. Finally, I would evaluate the necessity of auto-scaling groups and global rate limiting to ensure the system remains resilient under extreme load while maintaining service level objectives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f2aa6cf-fa86-4422-8287-652948606620', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the difference between ''display: none'' and ''visibility: hidden''?', N'Intern', N'Display: none removes the element from the document flow entirely, meaning it occupies no space. Visibility: hidden hides the element from view, but it still occupies the same space and affects the layout of surrounding elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d708d78-8fb4-4a32-83f8-652c5a869c65', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind impact the long-term maintainability of a large-scale project?', N'Middle', N'Tailwind improves maintainability by removing the ''cascading'' aspect of CSS, which prevents accidental style leakage and global side effects. Because styles are local to the markup, developers can safely delete or modify an element without worrying about breaking styles in distant parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1440d477-ad6d-4b4c-b001-65311d84fcba', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When planning a system migration, how do you estimate the ''point of no return'' for a rollback strategy?', N'Senior', N'I identify dependencies and state synchronization requirements that make a rollback destructive. I estimate the time and data loss associated with a rollback, and ensure that the migration architecture includes a dual-write or feature flag mechanism to facilitate safe testing and rapid recovery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6664384-f40e-42c3-8bcd-653258c1ae98', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Is it possible to return different response types from the same handler?', N'Junior', N'Yes, you can return a type that implements the Responder trait, which can be an enum representing different possible outcomes. This allows a single handler to return, for example, either a success JSON response or an error response based on internal logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c1a3c5d-eb36-4c0f-89d1-6534bbd04519', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is a ''bloom filter'' and how is it used to improve cache efficiency?', N'Senior', N'A bloom filter is a space-efficient probabilistic data structure used to check if an item exists in a set. It is used in front of caches to prevent ''negative cache lookups'' for items that do not exist, protecting the database from unnecessary queries for non-existent keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe4a499c-fbe0-4719-933e-65357fb5c233', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why is ''Read Uncommitted'' generally discouraged in production environments?', N'Senior', N'Read Uncommitted allows transactions to read data that has been modified by other transactions but not yet committed, leading to dirty reads. This can cause applications to base business logic on invalid data that might be rolled back later, leading to data integrity issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2bc7dd2-1342-4fd7-a176-6536e1a21b41', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the architectural challenges of sharing complex types between a Node.js backend and a React frontend?', N'Senior', N'The primary challenge is maintaining a single source of truth for shared interfaces without introducing circular dependencies or coupling the two environments too tightly. Using a dedicated ''shared'' package or monorepo workspace allows for centralized type definitions, but it requires rigorous discipline to avoid leaking backend-specific types into the frontend bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1939e02c-c2fe-438a-884f-65378f92ba1b', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the role of the ''Global Transaction Identifier'' (GTID) in modern MySQL replication.', N'Senior', N'GTIDs provide a unique identifier for every transaction across the entire cluster, simplifying replication topology and failover. They eliminate the need to track specific binary log file positions, making it trivial to promote a new master without complex coordinate calculations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cc73524-2960-4751-85c2-6542d4e70f22', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the primary difference between a struct and a class in Swift regarding memory management?', N'Middle', N'Structs are value types stored on the stack or inline within other types, meaning they are copied when passed. Classes are reference types stored on the heap, requiring reference counting to manage their lifetime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f1cb6f9-54b7-42b1-8e4a-6543464010f8', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Explain the concept of ''Build-time'' processing in Quarkus.', N'Junior', N'Quarkus performs much of its configuration and dependency injection logic during the application build phase rather than at runtime. This allows the application to discard unnecessary metadata and code, leading to significantly faster startup times and lower memory usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'007cd319-9a62-4d03-b1e5-6543e03ccd1d', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the difference between eager loading and lazy loading in Eloquent?', N'Junior', N'Lazy loading retrieves related models only when you access the relationship property, which can lead to the N+1 query problem. Eager loading retrieves all necessary related models at once using a single additional query, which significantly improves performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
