INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d0b9de1-1f36-43c4-8f06-65518a93b4c5', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How do you monitor the health of a messaging system?', N'Middle', N'Health monitoring should focus on consumer lag, which indicates if consumers are falling behind producers, and broker resource utilization like CPU, memory, and disk I/O. Additionally, tracking queue depth and error rates in the DLQ is essential for proactive maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00ccff51-3a43-42e7-af6f-6552487b00dd', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain the ''Error-First Callback'' pattern and why it is used.', N'Middle', N'This pattern requires the first argument of a callback to be an error object, while the second contains the data. This provides a standardized way to handle asynchronous errors, ensuring that the developer explicitly checks for failure before processing the results.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf6835df-d9b9-4234-b85f-65561382cc44', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'When would you prefer an asynchronous architecture over a synchronous one?', N'Middle', N'Asynchronous architectures are preferred when the system needs to handle high latency tasks, improve overall throughput, or maintain high availability. They decouple the sender from the receiver, allowing the system to remain responsive even when parts of it are slow or temporarily down.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
