INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2a5b646-659e-4b10-8e97-655934b49694', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between the ''abort'' function and returning a response?', N'Fresher', N'The ''abort'' function immediately stops the execution of the current request and triggers an error response based on the provided status code. Returning a response is a standard way to send data back to the client after successful processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b1b65da-7e9f-4bd3-9449-65594c5d9d01', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Does reading data change the state of a database?', N'Fresher', N'Generally, reading data does not change the state of the database, but it is still often part of a transaction. The transaction ensures that the data read remains consistent throughout the duration of the task.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7236b446-db51-4914-bc5e-6559e351560d', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify''s approach to routing enhance performance?', N'Middle', N'Fastify uses a radix tree-based router that provides extremely fast path matching regardless of the number of registered routes. This is significantly more efficient than linear array-based routing, which slows down as the application grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'355a50ec-6364-491e-bea0-655cff4877da', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why would you choose to use a ''resource route'' in Remix?', N'Middle', N'A resource route does not export a component and is used purely to handle server-side logic like file downloads, webhooks, or JSON APIs. It allows you to expose endpoints within your Remix application without needing a separate backend service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eba8cea3-4e87-47cc-a1d7-655e489a5755', N'4c000000-0000-0000-0000-000000000005', N'What are the benefits of using a sidecar pattern in Kubernetes?', N'Senior', N'The sidecar pattern allows you to extend or enhance the functionality of a primary container without modifying its code. It is ideal for logging, monitoring, proxying, or security agents, as it keeps the main application container lean and focused on its primary responsibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afe6fca8-12ca-4572-8334-6560a701faf3', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of ''Exceptions'' handling in AdonisJS?', N'Fresher', N'AdonisJS uses a centralized exception handler to catch errors that occur during the request lifecycle. This allows the application to gracefully handle failures and return consistent, meaningful error messages to the client instead of crashing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd90fbc0a-acba-446c-bbae-656227d22d7b', N'4c000000-0000-0000-0000-000000000005', N'How do you decide between a monolithic architecture and microservices in a high-growth environment?', N'Senior', N'Choose monoliths initially to optimize for development velocity and simplified deployment. Transition to microservices when organizational scale creates team coupling, or when specific sub-systems require independent scaling and technology stacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bba0345-89d7-4baa-8343-65631d99ce5a', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify minimize garbage collection overhead compared to other Node.js frameworks?', N'Senior', N'Fastify minimizes object creation by reusing request and reply objects within its internal lifecycle and by using efficient serialization functions that avoid frequent allocations. By reducing the number of short-lived objects, it significantly lowers the pressure on the V8 garbage collector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcff7620-b83a-4b8b-b3c7-6563bd7fc015', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of the ''ngOnDestroy'' lifecycle hook?', N'Middle', N'The ngOnDestroy hook is used for cleanup operations such as unsubscribing from observables, clearing timers, or removing event listeners. Implementing this is crucial to prevent memory leaks in a Single Page Application where components are created and destroyed dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b8a206a-1cb9-4458-a214-6566be6a985e', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s ''const'' constructor mechanism contribute to runtime efficiency?', N'Senior', N'Const constructors enable compile-time constant expressions, allowing the compiler to perform canonicalization where multiple instances of an object with the same values are represented by a single instance in memory. This reduces heap allocation overhead and speeds up equality checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f81cd068-6ca8-46a5-b033-65674e9ce39d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach capacity planning for a system with highly unpredictable, bursty traffic patterns?', N'Senior', N'I prioritize implementing robust autoscaling policies and circuit breakers, and I use stress testing to determine the system''s breaking point rather than just its average capacity. I then base my estimates on the cost of over-provisioning for safety versus the risk of cascading failures during unpredicted spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fdcd764-cfa7-4863-9e55-6567eb76cee2', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the purpose of the +error.svelte file?', N'Intern', N'The +error.svelte file is a specialized component used to display a custom UI when an error occurs while loading a route. It allows developers to provide a friendly fallback experience instead of showing a blank screen or a default browser error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e567c6bf-46ad-44bc-98fb-65682d121159', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar manage security regarding user authentication?', N'Junior', N'Litestar provides extensible authentication backends. You can implement custom logic to verify tokens or sessions and integrate this with Guards to protect specific routes or controllers from unauthorized access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e85e3a7-db7e-4660-835e-656c5a6c6b46', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut approach the management of ''Configuration Properties'' for production-grade applications?', N'Senior', N'It provides type-safe configuration binding where settings are mapped directly to POJOs at compile-time. This ensures that the application will fail to start if the configuration is invalid or missing, providing a ''fail-fast'' mechanism that is much safer than dynamic runtime parsing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae30760e-c304-42d5-be39-656e01bf57a9', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does the ''I'' in BASE represent compared to ACID?', N'Fresher', N'In the BASE model, which is common in NoSQL, the ''E'' stands for Eventually Consistent. Unlike ACID which enforces strict consistency, BASE systems allow for temporary inconsistencies to prioritize high availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'280ab8ff-00b0-4292-818f-656e65d049a9', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Can you define routes for different HTTP methods for the same path in Chi?', N'Junior', N'Yes, Chi makes it very easy to define different handlers for the same path based on the HTTP method. You can chain methods like Get, Post, Put, and Delete directly on the router instance for a specific path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'168f0d69-7459-4bbd-9888-656eb4c423c6', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the advantage of Vite''s dependency pre-bundling?', N'Intern', N'Vite pre-bundles dependencies using esbuild during startup. This converts dependencies that might be in different formats into a single ESM format, which improves performance and avoids overwhelming the browser with too many network requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c9ae66d-facf-4f71-81e2-656f8251db1a', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What does CORS stand for and what issue does it address?', N'Intern', N'Cross-Origin Resource Sharing (CORS) is a W3C spec that allows cross-domain communication from the browser. By building on top of the XMLHttpRequest object, CORS allows developers to work with the same idioms as same-domain requests. CORS gives web servers cross-domain access controls, which enable secure cross-domain data transfers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c418594-7426-41a7-a220-65717f3d8b8a', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the benefit of using an event bus versus a state management library like Pinia?', N'Middle', N'An event bus provides a simple way to communicate between distant components but creates tight coupling and makes debugging difficult as the app grows. Pinia offers a centralized, predictable state container with better debugging tools, developer experience, and clear separation of concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f513961-f310-48e7-8e70-6572fb42ec15', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Describe the security benefits of Rocket''s ''Data'' guard system.', N'Senior', N'The Data guard enforces strict limits on request body sizes and types before they are fully consumed. This provides a built-in defense against memory exhaustion attacks and malformed payload injection, ensuring the server remains stable under malicious traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'470e658d-ee76-4c20-8f10-657ad6bc4708', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle dependency injection?', N'Junior', N'FastAPI uses a built-in dependency injection system that allows you to define shared logic, such as database connections or authentication, as dependencies. These are automatically resolved and injected into your route functions when called, promoting code reusability and testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3602a97f-a55a-4129-8052-657ca52853e7', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What are Server Components in Next.js?', N'Fresher', N'Server Components are components that render exclusively on the server. They reduce the amount of JavaScript sent to the client, improving performance by keeping data fetching logic and heavy dependencies off the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bc5ce35-f0c4-478c-88a4-657df92a415b', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the purpose of continuous integration (CI)?', N'Junior', N'Continuous integration is the practice of automatically building and testing code changes as soon as they are pushed to a shared repository. This ensures that integration issues are caught early and that the project remains in a deployable state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c25d02a-e082-471a-8f57-657e9cf9cf9b', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do you handle global CSS styles in a Lit component that uses Shadow DOM?', N'Middle', N'Since Shadow DOM encapsulates styles, global styles do not penetrate it by default. Developers can use CSS custom properties (variables) to theme components or import shared style sheets into the component''s ''styles'' array, which allows for controlled styling of the Shadow root.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06dd15ed-da89-41fb-a6dd-657ee82d1520', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the architectural purpose of ''Taint'' and ''Safe'' levels in older versions of Ruby, and why were they deprecated?', N'Senior', N'These features were intended to provide a mechanism for tracking the flow of untrusted data and restricting sensitive operations, but they proved to be practically ineffective against security threats. They were deprecated because they provided a false sense of security while introducing significant performance overhead and complexity in the standard library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0aedd90b-1f5a-4066-9884-657f03a08546', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the difference between data frames and matrices in R?', N'Junior', N'Both are two-dimensional structures, but a matrix must contain elements of the same data type. A data frame can hold columns of different types, such as numeric, character, and logical, making it the standard structure for tabular data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e70794e-99c5-43aa-96a2-65807fd61896', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between ''as?'', ''as!'', and ''as'' in casting?', N'Intern', N'The ''as'' operator is for upcasting to a superclass. ''as?'' is a conditional cast that returns an optional, while ''as!'' is a forced cast that triggers a runtime error if the cast fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0b632f7-0d50-4ced-9e48-6582b3557d4e', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the purpose of the ''slot'' element in Svelte?', N'Junior', N'The ''slot'' element acts as a placeholder inside a component that allows parent components to inject custom HTML content. This makes components more reusable by allowing them to wrap different content structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78410971-f5ef-4ad1-8c08-6585f6d832cc', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What are Spring Boot DevTools?', N'Fresher', N'Spring Boot DevTools is a set of tools that improves the development experience by providing features like automatic application restarts when code changes. It also disables template caching, allowing developers to see UI changes instantly without restarting the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77a011e5-5378-4a38-b15c-65866d3ccb08', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the history behind React evolution?', N'Intern', N'The history of ReactJS started in 2010 with the creation of XHP. XHP is a PHP extension which improved the syntax of the language such that XML document fragments become valid PHP expressions and the primary purpose was used to create custom and reusable HTML elements. The main principle of this extension was to make front-end code easier to understand and to help avoid cross-site scripting attacks. The project was successful to prevent the malicious content submitted by the scrubbing user. But there was a different problem with XHP in which dynamic web applications require many roundtrips to the server, and XHP did not solve this problem. Also, the whole UI was re-rendered for small change in the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72859f60-0235-4e9a-882d-6588a3157f06', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a primary replica in a database cluster?', N'Intern', N'The primary replica is the main node that accepts both read and write requests in a database system. Other replicas, known as secondary or read-only replicas, receive copies of the data to handle read traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
