INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c541c27f-6a34-4a92-9ebd-6592ff35ca8d', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How do you ensure exactly-once delivery semantics in a distributed messaging system?', N'Senior', N'Exactly-once delivery requires a combination of idempotent consumers and transactional producer writes. The consumer must track processed message IDs in a persistent store, while the producer utilizes sequence numbers and deduplication logic at the broker level to prevent duplicate processing during retries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
