INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4845c71-fe3e-4fe3-8f81-659ff6950dce', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you compare two date objects?', N'Fresher', N'Two dates can be compared by converting them into numeric values using date.getTime() method to correspond to their time. Also, the relational operators , >= can be used to compare JavaScript dates. However, the equality operators ==, !=, ===, !== cannot be used to compare (the value of) dates because: * Two distinct objects are never equal for either strict or abstract comparisons. * An expression comparing Objects is only true if the operands reference the same Object. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0f2634b-76c1-41a8-80f4-65a082ee958e', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How do non-blocking synchronization primitives, such as CAS (Compare-And-Swap), improve scalability in high-concurrency Java applications?', N'Senior', N'CAS operations allow multiple threads to update shared memory without traditional locking, avoiding the overhead of thread context switching and blocking. By leveraging hardware-level atomic instructions, these primitives increase throughput and reduce contention, making them essential for building scalable concurrent data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
