INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c63aa023-3a15-4929-bae5-65a3c69c3b66', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle routing performance differently than traditional frameworks when dealing with a high number of routes?', N'Senior', N'Hono uses a Trie-based router, which provides O(n) performance relative to the depth of the URL path rather than the number of registered routes. This makes the framework highly performant even in complex applications with thousands of endpoints, as the time complexity remains stable regardless of the routing table size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9e8d3db-62d1-4c43-a423-65a3de7c9299', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the difference between an interface and a concrete type in terms of memory allocation and method dispatch?', N'Senior', N'Interfaces are implemented as a two-word structure containing a pointer to the type information and a pointer to the data. Method calls on interfaces require dynamic dispatch (itab lookup), which is slightly slower than direct method calls on concrete types, and may trigger heap allocations if small values are boxed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7682f8fb-2769-463e-9ec1-65a7e010c6d2', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is a Content Delivery Network (CDN) and what problem does it solve?', N'Middle', N'A CDN is a geographically distributed network of proxy servers that cache content closer to the end-user. It solves the problem of network latency by reducing the physical distance data must travel, which improves load times and reduces the bandwidth burden on the origin server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
