INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20be7f95-fe81-4f44-8035-65b03712794c', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala''s Higher-Kinded Types (HKT) capability enable advanced abstraction in library design?', N'Senior', N'Higher-Kinded Types allow abstraction over type constructors, enabling the creation of generic structures like Monads or Functors that work across different container types. This capability is foundational for functional programming libraries, allowing developers to write highly reusable, modular logic that is independent of the underlying data representation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cac7cd9b-c7d2-4190-b3ff-65b21ae3fbed', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Compare the memory consumption of a Qwik application versus a hydrated React application.', N'Senior', N'A hydrated React application keeps the entire component tree and framework internals in memory to manage potential updates. Qwik significantly reduces memory consumption by keeping only the active components and their state in memory, allowing the browser to garbage collect inactive parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
