INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6eaa4080-2d4c-4f22-92f1-65b3cb52d596', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is your approach to estimating the throughput capacity of a messaging queue system under peak load conditions?', N'Senior', N'I calculate the message size and arrival rate, then determine the processing latency per consumer instance. I estimate the horizontal scaling threshold by identifying bottlenecks like disk I/O, network bandwidth, or consumer group synchronization overheads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a139b167-8b1d-46a6-abf5-65b50bbc1955', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How do NestJS Guards differ from Interceptors?', N'Middle', N'Guards are primarily used for authorization and authentication to determine if a request should proceed to the route handler. Interceptors are more flexible and can be used to transform the result returned from a function, transform the exception thrown, or extend basic method behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8266eb69-a85a-43d9-b45a-65b5bf0c0421', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What are Redux DevTools?', N'Fresher', N'Redux DevTools is a browser extension that allows developers to inspect the state of the store, view dispatched actions, and time-travel through state history. It is a powerful tool for debugging and understanding how the state evolves over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f91b3f67-2a64-4fa1-97b4-65b79c136eae', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'If you have a limited timeline, how do you decide which features to prioritize for a release?', N'Fresher', N'You use trade-off analysis to identify ''must-have'' versus ''nice-to-have'' features based on business value and user impact. By focusing on core functionality, you ensure the product is functional and stable by the deadline, even if some secondary features are omitted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a8a502f-9006-4c0a-8e51-65b7fc894924', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How do C++ smart pointers manage ownership and prevent memory leaks in complex object graphs?', N'Senior', N'Smart pointers use RAII to automate the lifecycle of heap-allocated objects; unique_ptr enforces exclusive ownership, while shared_ptr uses reference counting to manage shared ownership. To prevent leaks in cyclic graphs, weak_ptr is necessary to break circular dependencies, ensuring that the reference count can reach zero for proper resource deallocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e9ff2bb-3741-4ab4-9c12-65ba8c430c69', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What are the implications of network partitions (CAP theorem) for a distributed message queue?', N'Senior', N'A message queue must choose between consistency and availability during a network partition. Systems prioritizing consistency will stop accepting writes if a quorum cannot be formed, while systems prioritizing availability may accept writes locally, leading to potential data divergence or conflicts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4ffc7a3-cb90-41ac-abde-65bafda22419', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach a complex problem that seems overwhelming at first glance?', N'Fresher', N'I would apply the ''divide and conquer'' strategy by breaking the large problem into smaller, logical, and independent components. By solving or estimating each part separately, the overall problem becomes less intimidating and easier to manage. This approach also allows me to identify which parts I can handle immediately and which might require additional research.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b740ff6b-61bb-4222-a487-65be9f6158b2', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why does Cassandra enforce a limit on the number of columns per partition?', N'Senior', N'Limiting the number of columns and the size of partitions prevents the storage engine from hitting memory constraints during memory-intensive operations like compaction or secondary indexing. Keeping partitions small ensures predictable latency and prevents the performance degradation associated with ''fat'' partitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce4aece2-2341-405f-8ae1-65bf81167b0d', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin manage context cancellation?', N'Intern', N'Gin integrates with the standard library''s context package. If a client disconnects, the request context is canceled, allowing the handler to stop processing and free up resources immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efeb9c5e-7cea-4691-98cf-65c0cccba538', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Compare ''Database per Service'' versus ''Shared Database'' in terms of service autonomy.', N'Senior', N'Database per service enforces strict boundaries, enabling independent schema evolution and technology selection, which is essential for true service autonomy. A shared database forces services to coordinate all schema changes, creating an operational bottleneck and violating the principle of encapsulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6323ba7-3aac-4cf1-9099-65c76b5ad2cd', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Explain the difference between Redis RDB and AOF persistence mechanisms regarding data safety and recovery time.', N'Senior', N'RDB creates point-in-time snapshots of the dataset at specified intervals, offering fast recovery but potential data loss between snapshots. AOF logs every write operation to disk, providing better durability at the cost of larger file sizes and potentially slower recovery due to command re-execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ad7cb9a-a214-4ea1-968c-65c7b4815d25', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you ensure your work is reliable before handing it off to the team?', N'Fresher', N'I perform thorough self-testing using various inputs, including edge cases and invalid data, to ensure the logic holds up. I also review my work against the initial requirements and coding standards to ensure consistency with the rest of the project. Finally, I document my changes clearly so the next person can easily understand and maintain the solution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34dbfb6b-e7e0-4884-bce7-65c9f2d0b0fe', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you report missing translations?', N'Fresher', N'By default, When translation is missing, it generates a warning message such as "Missing translation for message ''somekey''". But you can configure with a different level of message in Angular compiler as below, 1. Error: It throws an error. If you are using AOT compilation, the build will fail. But if you are using JIT compilation, the app will fail to load. 2. Warning (default): It shows a ''Missing translation'' warning in the console or shell. 3. Ignore: It doesn''t do anything. If you use AOT compiler then you need to perform changes in configurations section of your Angular CLI configuration file, angular.json. If you use the JIT compiler, specify the warning level in the compiler config at bootstrap by adding the ''MissingTranslationStrategy'' property as below,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd1638b2-e005-4ed0-9191-65ca7cab5b1f', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the purpose of an ''Expression Attribute Name''?', N'Junior', N'An Expression Attribute Name is used as a placeholder in expressions to avoid conflicts with reserved words in DynamoDB. It also allows you to reference attribute names that contain special characters or spaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'387b1104-1b07-4852-900b-65ce2b7755db', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are some tools and techniques for identifying security vulnerabilities in JavaScript code?', N'Fresher', N'To identify security vulnerabilities in JavaScript code, you can use static code analysis tools like ESLint with security plugins, dynamic analysis tools like OWASP ZAP, and dependency checkers like npm audit. Additionally, manual code reviews and adhering to secure coding practices are essential techniques. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc3f88e7-f7ac-414a-9827-65ce7ca1d70e', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the difference between a ''static'' and ''dynamic'' route in Phoenix.', N'Middle', N'A static route matches a specific path exactly, while a dynamic route contains parameters that allow the application to extract information from the URL path. Dynamic routes are essential for resource-based routing, where part of the URL identifies a specific object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bfcde55-ad1b-4c78-961f-65ceea512251', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is Apache Cassandra and how is it classified?', N'Intern', N'Apache Cassandra is an open-source, distributed NoSQL database management system designed to handle large amounts of data across many commodity servers. It is classified as a wide-column store, which provides high availability with no single point of failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfcef606-80ab-48e7-be43-65cf35d362bf', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is a negative cache, and why is it useful?', N'Middle', N'A negative cache stores the result of a failed lookup, such as when a record does not exist in the database. This prevents the system from repeatedly querying the database for non-existent keys, thereby protecting the backend from unnecessary load during high-traffic periods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db435ec9-49b8-4b08-aa8a-65cf68760956', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the ''params'' object?', N'Junior', N'The ''params'' object is a hash-like structure in a controller that contains data sent by the client, such as URL parameters, query string variables, and form data. It is the primary way that a Rails application receives information from the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3adbadb4-90ec-4b5f-82a6-65cfa1985044', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How do you apply styles to a group of elements based on a parent state in Tailwind?', N'Fresher', N'You can use the ''group'' class on a parent element and the ''group-hover'' variant on child elements. This allows the child element to change its appearance whenever the user hovers over the parent container.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6570da6f-0264-49c3-9e33-65d0df23d4b7', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js differ from frameworks like React or Vue?', N'Intern', N'Unlike React or Vue, which are component-based frameworks that often require complex build setups and virtual DOM management, Alpine.js is designed to be minimal and operate directly on existing HTML. It is much smaller in size and focuses on enhancing static HTML rather than replacing it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'882f7e04-e6fe-4d94-97d5-65d243e119c8', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo integrate with OpenAPI/Swagger specifications, and what are the architectural advantages?', N'Senior', N'Echo can be integrated with OpenAPI through middleware that performs request validation against a schema. This acts as a contract enforcement layer, ensuring that incoming requests adhere to defined specifications before hitting the application logic, which reduces defensive coding and improves API documentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c29aa234-a315-4e37-b2d7-65d2783e668e', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is a Middleware in Hono?', N'Intern', N'Middleware in Hono is a function that sits between the incoming request and the final route handler. It can perform tasks like logging, authentication, or modifying the request and response objects before they reach the main application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0cb9feb-fba5-4597-92f8-65d5b3ecdc25', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Describe the role of a ''Coordinator Node'' in a decentralized database cluster.', N'Senior', N'The coordinator node receives a client request and determines which nodes in the cluster are responsible for the requested data based on the partitioning scheme. It then routes the request, aggregates the responses, and returns the result to the client, abstracting the complexity of the distributed topology.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1664cbc0-094f-4a0f-bf2a-65d706f3aed7', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the ''Qwik City'' framework?', N'Intern', N'Qwik City is a meta-framework built on top of Qwik that provides additional features like routing, data fetching, and layouts. It is intended to be the standard way to build full-stack applications using Qwik.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6ad3045-1f1c-4c12-9735-65d903f13fd6', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the importance of ''Observability'' versus ''Monitoring'' when troubleshooting complex system failures?', N'Middle', N'Monitoring tells you when a system is broken by tracking predefined metrics, whereas observability allows you to understand why it is broken by exploring the internal state through logs, traces, and metrics. Observability is crucial for troubleshooting ''unknown unknowns'' where the failure mode was not anticipated during the design of standard monitoring dashboards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'539c6ee1-3272-4430-8b9b-65dae2142c7a', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What does ''dispatching an action'' mean?', N'Intern', N'Dispatching an action is the act of sending an object to the store to trigger a state change. It is the process of notifying the Redux system that something has happened in the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6669e8a1-89bf-4c1f-b7e1-65dbe41b2ad2', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you ensure your work remains organized and easy for others to understand?', N'Fresher', N'I follow standard naming conventions and keep my work modular. I also document my thought process or the logic behind my choices, which makes it easier for others to review my work later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9a81c99-7aa1-4cb4-b0a1-65dd0948e245', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What architectural challenges arise when implementing custom authentication flows in SvelteKit?', N'Senior', N'The primary challenge involves maintaining session synchronization between the server-side handle hook and the client-side session store. Developers must ensure that cookie-based sessions are securely validated on the server for every request while keeping the client''s local store updated to reflect the current authentication state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70d3cb15-ebf3-46aa-bb8f-65e200622abf', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the role of the NestJS Logger service?', N'Middle', N'The Logger service provides a consistent way to output logs across the application. It can be easily replaced with third-party logging libraries to support features like structured logging, log levels, and log aggregation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90a61cb5-047c-41eb-911b-65e6b246d36f', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why is it generally recommended to avoid mapping explosions?', N'Junior', N'A mapping explosion happens when an index has too many fields, which puts a significant strain on the cluster''s memory and performance. Keeping the number of fields managed and controlled ensures the cluster remains stable and search queries remain fast.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34689df6-1fa8-420c-bc11-65ebae1732b3', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How do you handle CSS in Vite?', N'Fresher', N'Vite has built-in support for CSS. You can import CSS files directly into your JavaScript, and Vite will inject them into the document head or handle them as separate files during production builds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7444945-f7a5-4d09-96ff-65f1a02d10bb', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Explain the role of the CommitLog in ensuring durability.', N'Senior', N'The CommitLog is an append-only log that records all incoming writes before they are applied to the Memtable. If a node crashes, the system replays the CommitLog during startup to recover data that had not yet been flushed to SSTables, ensuring durability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56dfc8b2-4a65-4fa1-baf3-65f513beaad8', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Discuss the performance overhead of Gin''s Context copying in large middleware chains.', N'Senior', N'Copying the Context object involves duplicating several fields and pointers, which adds slight overhead to every request. While usually negligible, in systems with massive middleware chains and extremely high throughput, minimizing the number of middleware layers can provide marginal performance gains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14752066-69ac-4b85-a6fe-65f592814a79', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does Consistency ensure data integrity?', N'Fresher', N'Consistency ensures that a transaction brings the database from one valid state to another valid state, maintaining all predefined rules, constraints, and triggers. If a transaction violates any data integrity rules, it is aborted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5dad24f-bc24-44d8-968d-65f64a8efe3a', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is middleware in the context of Express.js?', N'Intern', N'Middleware functions are functions that have access to the request object, the response object, and the next middleware function in the application’s request-response cycle. They can execute code, modify requests, or end the cycle by sending a response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de8cf6cd-bbfa-4f6f-8993-65fb26fa3114', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the architectural benefit of Hono''s support for RPC (Remote Procedure Call) patterns in a frontend-backend ecosystem?', N'Senior', N'Hono''s RPC feature allows the frontend to import the backend''s type definitions directly, creating a seamless contract between the two tiers without needing external tools like OpenAPI generators. This leads to a synchronized development lifecycle where schema changes in the backend are immediately reflected in the frontend''s type-checked code, minimizing runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
