INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dba353ab-0853-456f-854c-65fe916b1300', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the primary difference between a fiber and a thread?', N'Intern', N'Threads are managed by the operating system and are preemptively scheduled, meaning the OS can interrupt them at any time. Fibers are managed by the application, meaning they voluntarily yield control, which reduces the overhead of context switching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80ae5c33-c3bd-485a-8233-65ff8aaecbbe', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the V8 ''Ignition'' interpreter improve startup time compared to older compilation strategies?', N'Senior', N'Ignition generates bytecode, which is much smaller and faster to produce than machine code. This allows the engine to begin execution almost immediately while the ''TurboFan'' compiler works in the background to generate optimized machine code for hot paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fa9a70f-882c-4699-b13d-66031e41dad5', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you manage the trade-off between system observability and the performance overhead of instrumentation?', N'Senior', N'I balance depth with efficiency by implementing sampling strategies for traces and logs rather than capturing every event. I also prioritize observability at the edge and critical service boundaries to maximize insight while keeping resource consumption within acceptable thresholds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b975e73-79e8-4b12-879a-6603bec4229c', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why is it important to use ''MiniCssExtractPlugin'' in production builds?', N'Middle', N'This plugin extracts CSS into separate files rather than injecting it into the DOM via JavaScript. This improves performance by allowing the browser to load CSS and JavaScript in parallel and prevents a flash of unstyled content during initial page load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b44dc573-921a-4eff-996f-6606a2b79f01', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot handle database migrations?', N'Middle', N'Spring Boot integrates with tools like Flyway or Liquibase to manage database schema versions. These tools automatically apply SQL scripts or migration files on startup, ensuring that the database schema is kept in sync with the application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50ef9f1b-af35-4910-9a29-6606f43ed509', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you determine the appropriate level of test coverage for a new feature?', N'Middle', N'I focus on a risk-based approach, prioritizing high-coverage for critical business logic, edge cases, and complex integrations. While unit tests provide fast feedback for individual components, I ensure that integration tests cover the interaction between services. I aim for a balance where the effort spent writing tests provides sufficient confidence to deploy without significantly slowing down the development cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bf1ac3d-e1c5-4d13-ad08-66092fa95b01', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the primary architectural difference between an event-driven architecture and a traditional request-response microservices pattern?', N'Senior', N'Request-response architectures rely on synchronous, point-to-point coupling which can lead to cascading failures and high latency. Event-driven architectures use asynchronous messaging via brokers, enabling temporal decoupling and superior scalability at the cost of increased complexity in managing eventual consistency and distributed tracing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35030110-03aa-4b4e-8df9-660be8a80ecd', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the difference between a static route and a dynamic route in Hono?', N'Fresher', N'A static route matches a fixed URL path exactly, while a dynamic route contains placeholders that can capture variable data from the URL. This allows for flexible API structures where individual resources are identified by IDs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e42dae27-be59-4679-bf8a-660c5483f6fd', N'954a0331-deff-4399-b588-96f39fec001d', N'What is zone.js and NgZone?', N'Intern', N'zone.js is a library that patches asynchronous browser APIs like setTimeout, addEventListener, and Promise to create execution contexts called "zones". It allows tracking when asynchronous operations start and finish. Angular uses zone.js to automatically detect when potential changes might have occurred in your application''s data. When an asynchronous event tracked by zone.js completes (like a button click, an HTTP response, or a timer firing), zone.js notifies Angular, which then triggers its change detection mechanism to update the UI if necessary. NgZone is an injectable Angular service that wraps zone.js. It provides methods to explicitly run code _inside_ Angular''s zone (run()) or _outside_ Angular''s zone (runOutsideAngular()).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'041fc530-4769-49ee-a18b-660ca8b883e7', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does Sass handle vendor prefixes?', N'Fresher', N'Sass makes vendor prefixing easier by using mixins to group the prefix versions of a property together. You define the mixin once and apply it wherever the property is needed, ensuring consistent cross-browser compatibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a6f27c5-897a-4bec-a693-660cedaea638', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Describe the internal mechanism of the AdonisJS Lucid ORM query builder and its impact on performance.', N'Senior', N'Lucid maps database records to active record instances, providing an abstraction layer over raw SQL. While this simplifies development, it can introduce performance overhead due to object instantiation; for high-throughput scenarios, developers should leverage raw query execution or query projections to minimize memory consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e6dc218-cb92-49d4-8f8c-6611a6fd8213', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'When should you choose a LiveView over a traditional SPA architecture?', N'Middle', N'LiveView is ideal when you want to minimize client-side complexity by handling state and DOM updates on the server. It is preferred when the application requires real-time interactivity but you want to avoid managing a complex JavaScript framework or an extensive API layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
