INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'358403eb-db36-4046-9e08-661459be6bba', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When troubleshooting a memory leak, what kind of information are you looking for?', N'Junior', N'I would look for patterns where memory usage grows steadily over time without being released, often indicated by frequent garbage collection cycles or ''out of memory'' errors. I would use monitoring tools to observe object allocation and identify which parts of the application are retaining references to objects that should have been discarded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b7c3be1-3d2a-469c-99ab-66152776f964', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How do you enforce type safety in a Redux architecture using TypeScript?', N'Senior', N'Type safety is enforced by defining interfaces for the state, action types, and payload structures. By creating custom hooks for selectors and dispatch, you ensure that components receive typed data, preventing runtime errors caused by mismatched property names or unexpected data types in the store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ba9a012-00a1-402b-a6d7-6624142a4d54', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Discuss the strategy for handling backpressure in Node.js stream-based architectures.', N'Senior', N'Backpressure occurs when a readable stream produces data faster than a writable stream can consume it. Failing to handle this causes internal buffers to grow, leading to high memory usage and potential process crashes. Using the pipe method handles this automatically, but custom stream implementations must explicitly implement the drain and pause mechanisms to respect buffer limits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ec000c5-1769-427d-b51a-6626a689e8e4', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Compare the impact of ''at-least-once'' versus ''at-most-once'' delivery guarantees.', N'Senior', N'At-least-once guarantees ensure no data loss by re-sending messages until acknowledgment, but require consumers to be idempotent. At-most-once favors performance and simplicity by not retrying, making it suitable for loss-tolerant telemetry data where duplication is undesirable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a494055-0c5d-4ad8-a6a1-662826337ad5', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the function of the Large Object Heap (LOH) in the .NET garbage collector, and why is it problematic?', N'Senior', N'The LOH stores objects larger than 85,000 bytes, which are allocated in a separate segment to avoid expensive generational compaction. Because the LOH is not compacted by default, it suffers from memory fragmentation, which can eventually trigger OutOfMemory exceptions even when sufficient total memory exists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9f42ec1-35ac-4a35-a969-6629f6b0e1d7', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of the Eloquent ORM ''Lazy Loading'' versus ''Eager Loading''?', N'Middle', N'Lazy loading retrieves related models only when they are accessed, which often results in the N+1 query problem. Eager loading retrieves all necessary related models in a single additional query using the ''with'' method, significantly improving performance for large datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'661e5f97-c8ea-45ad-92b0-662aa85ea0a7', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does the ''const'' keyword differ from ''final''?', N'Fresher', N'The ''const'' keyword represents a compile-time constant, meaning its value must be known before the program runs. While ''final'' variables are set once at runtime, ''const'' variables are implicitly final and must be assigned values that are fixed during compilation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7f8c770-e68d-46aa-9343-662acd81a8cb', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of the ''flask run'' command?', N'Junior', N'The ''flask run'' command is a built-in CLI tool that starts the development WSGI server. It automatically detects the application instance defined in your environment variables and serves the app locally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0164e7a-7b79-40ca-84ce-662c25536937', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you manage your time when working on a task with a tight deadline?', N'Fresher', N'I prioritize the most critical features that provide core functionality first. I keep the implementation simple to ensure completion, leaving complex optimizations for after the primary objective is met.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'749be2f7-2496-4b05-8150-662c6c300ea4', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is an Extractor in Actix-web?', N'Intern', N'An extractor is a mechanism used to pull specific data out of an incoming HTTP request, such as query parameters, JSON body content, or path variables. It automatically handles the parsing and validation of that data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a541016-67e7-48b6-8de8-662d8b12ba36', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you use hot reloading?', N'Fresher', N'The vue loader plugin internally uses hot reloading. If you are scaffolding project with vue-cli, hot reloading comes out of the box but if you are manually setting up the project then hot reloading is enabled by default with webpack-dev-server --hot command.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8616897b-26b1-4a66-895d-662e1cf34db4', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the role of a message partition in a high-throughput queue?', N'Middle', N'Partitioning divides a queue into smaller segments, allowing the load to be distributed across multiple broker nodes and consumers. This enables horizontal scaling and improves throughput by allowing concurrent processing of independent message streams.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd24c7d24-e38f-4ee9-a636-66308ace449f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Discuss the performance trade-offs of using ''eval'' or ''new Function'' in production.', N'Senior', N'These constructs prevent the engine from performing lexical scope optimizations because the code structure cannot be statically determined. Furthermore, they force the engine to keep the compiler active, preventing various de-optimizations and increasing memory consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6083506f-a4a7-470d-a76f-6630996643bf', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the difference between R and RStudio?', N'Intern', N'R is the actual programming language and the engine that executes the code. RStudio is an Integrated Development Environment (IDE) that provides a user-friendly interface with tools to make writing, debugging, and managing R code easier.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
