INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3e2c05f-643a-41df-90d3-66372b4fa2dd', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Discuss the trade-offs of using Nuxt''s built-in ''useFetch'' versus a standalone library like Axios.', N'Senior', N'useFetch is optimized for Nuxt''s lifecycle, handling request deduplication and payload serialization automatically for SSR. A standalone library offers more control over complex interceptor chains and specific request configurations, but it requires manual handling of state dehydration to avoid redundant network calls during hydration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
