INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8c30fe3-5300-4b3b-a12d-66403fdc0bd1', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does the Node.js Event Loop handle asynchronous I/O operations despite being single-threaded?', N'Middle', N'Node.js offloads I/O operations to the system kernel or the libuv thread pool whenever possible. When an operation completes, the kernel or thread notifies the event loop by placing a callback in the appropriate queue, which the loop then executes once the call stack is clear.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
