INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8f86bb2-b6bd-4c28-966d-6673f5ebdd92', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does multi-version concurrency control (MVCC) solve the reader-writer blocking problem?', N'Senior', N'MVCC maintains multiple versions of data rows, allowing readers to access a consistent snapshot of the database without being blocked by concurrent writers. This architecture eliminates read-write contention, though it necessitates a background garbage collection process to remove obsolete row versions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88da81d2-d248-48e7-8c97-6674175a362c', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What does the ''next'' function do?', N'Fresher', N'The next function is a callback that, when invoked, tells Express to pass control to the next middleware function in the stack. If it is not called and the current middleware does not end the request-response cycle, the request will be left hanging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecb047ae-3236-4448-91cc-66742f06326d', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What are the common strategies for splitting the Redux store when the application size becomes unmanageable?', N'Senior', N'The primary strategy is using ''combineReducers'' to split the root reducer into smaller, feature-specific functions. This modular approach keeps individual files small and allows team members to work on different slices of the state independently without causing merge conflicts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8991b164-587f-4589-ad1f-6675056d07f1', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why is it generally bad practice to store redundant data?', N'Junior', N'Storing redundant data leads to data inconsistency, where a change in one location is not reflected in another. It also wastes storage space and makes data maintenance much more difficult and error-prone.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6d2d4d5-a337-4140-9396-6675a4e7b82f', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the architectural implications of using Fiber''s handler pool versus standard net/http handler allocation?', N'Senior', N'Fiber utilizes a custom object pool for request and response contexts to minimize allocations and reduce GC pressure significantly compared to the standard library''s approach of allocating new objects per request. This optimization improves performance in high-throughput systems but requires strict adherence to not retaining references to context objects after the handler returns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c913fd5-7a5a-471f-8e20-6678f835a802', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of the ''{{outlet}}'' keyword?', N'Junior', N'The outlet is a placeholder in a template where a nested route''s template will be rendered. It allows for the creation of nested layouts, where a parent route can wrap multiple child views.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9680d4a2-8856-45dd-ac1f-667918e110f2', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is a reactive scope in SolidJS?', N'Junior', N'A reactive scope is a context where signal access is tracked. When you access a signal inside an effect, memo, or component template, the framework creates a subscription that links the current scope to that signal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6107926f-01ea-4a6e-9a67-66792226719b', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Describe the concept of ''Write Skew'' and why it is not prevented by standard Snapshot Isolation.', N'Senior', N'Write skew occurs when two concurrent transactions read overlapping sets of data but update disjoint sets, violating a business invariant that neither transaction could have foreseen. Snapshot isolation only detects write-write conflicts on the same record, failing to recognize that the logical dependency between the read-set and write-set has been broken.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43d639b9-6c00-48c7-880a-667c78b08f0c', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Does Redux work with libraries other than React?', N'Intern', N'Yes, Redux is a standalone library and is not bound to React. It can be used with any other JavaScript framework or even in plain JavaScript applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a6f9206-c570-4805-b0ea-667ca076c088', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle global singleton services compared to traditional frameworks?', N'Senior', N'Qwik uses a dependency injection system that serializes services and their state. This ensures that services can be shared across the application without forcing the entire service logic to be loaded into the browser memory at once.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91956214-1fcb-4da1-9c84-667e3ac45ada', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How do you package a Quarkus application for deployment?', N'Junior', N'Quarkus provides build tools for Maven or Gradle that package the application into a JAR file for JVM execution. Alternatively, these tools can be configured to generate a native executable for deployment as a lightweight container image.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
