INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0516083-062d-4aaf-a537-6681b2b91974', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the function of the Cluster Health API?', N'Fresher', N'The Cluster Health API provides status information about the cluster, index, and shard health. It reports whether the cluster is in a green, yellow, or red state based on the availability of primary and replica shards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f1e7ed0-ad0d-4d30-a88a-66831fa592da', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the different types of joins in PostgreSQL?', N'Fresher', N'The main types of joins include INNER JOIN, which returns rows with matching values in both tables, and OUTER JOINS (LEFT, RIGHT, and FULL), which return matching rows plus unmatched rows from one or both tables. Joins are used to combine records from two or more tables based on a related column.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a47a20f7-4179-4750-9c6e-6685edd1baf1', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between the button tag and the input tag with type=''button''?', N'Junior', N'The button tag is more flexible because it can contain HTML content like images or icons within it, whereas the input tag is a self-closing element that only accepts text in its value attribute. Both function similarly for triggering actions, but button elements are generally preferred for more complex styling and content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a4004ab-ac48-42c3-a391-66877740fec7', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte''s compiler handle ''slot'' composition, and why is this efficient?', N'Senior', N'Svelte compiles slots into direct DOM node placements rather than creating complex wrapper components. This allows for flexible component composition with zero runtime overhead, as the relationship between parent and child slots is resolved at build time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8757e98-b005-4180-af3e-668810f69e51', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle server-side rendering (SSR) compared to Next.js?', N'Senior', N'While Next.js performs SSR and then hydrates the page on the client, Qwik performs SSR and then ''resumes'' the application state on the client. Qwik omits the hydration step entirely, leading to significantly lower initial CPU usage in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3742159c-857d-4338-928f-668c28ca0096', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Explain the concept of ''Singleton'' scope in Micronaut.', N'Fresher', N'A singleton bean is created only once by the Micronaut container. Every time that bean is requested, the same instance is returned throughout the application lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
