INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b97feee9-0a56-4062-a3e9-6695e899b8fd', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Why does Dart treat ''Future'' as a non-blocking operation despite it running on a single thread?', N'Senior', N'Dart uses an event loop to handle non-blocking I/O. When a Future is awaited, the current execution stack is suspended, and the event loop continues processing other events until the Future completes, at which point the original task is resumed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
