INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a301d37-7742-43c8-beda-669829cd405c', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the purpose of a meta tag?', N'Intern', N'Meta tags provide metadata about the HTML document, such as the page description, keywords, author, and character encoding. This information is not visible to users on the page but is used by browsers and search engines to process the content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df0c6e81-c60e-46a5-93e5-66983a7903d8', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the role of the recovery middleware in Gin?', N'Intern', N'The recovery middleware is a built-in feature that catches any panics that occur during the request processing. It prevents the entire server from crashing and returns a 500 Internal Server Error to the client instead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5ca97e8-7044-4d80-bba1-669b04d807bc', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How does the choice of an error handling strategy impact system robustness?', N'Fresher', N'A strategy that crashes on every error ensures nothing continues in an inconsistent state, but it hurts availability. A strategy that attempts to recover gracefully maintains availability but risks propagating corrupt data through the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55d2f7b3-bc61-4f3b-b51b-669b767e75c6', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the difference between physical and logical replication?', N'Senior', N'Physical replication copies the exact data blocks from the source to the replica, which is fast and ensures an identical disk state but is restrictive regarding hardware or version mismatches. Logical replication transmits the actual changes (SQL or DML events), allowing for more flexibility in data transformation and multi-version or heterogeneous database environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd16344e1-418e-4226-9a8b-669cf386c750', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the Tokio runtime and why does Axum use it?', N'Intern', N'Tokio is an asynchronous runtime for Rust that provides the necessary infrastructure to execute non-blocking code. Axum uses Tokio because it allows the framework to handle thousands of concurrent connections efficiently, which is essential for modern high-performance backend services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c4f72d0-ab3a-43a6-a9f9-669e271447e4', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the purpose of rate limiting, and how would you implement it at scale?', N'Middle', N'Rate limiting protects infrastructure from abuse and ensures fair usage among clients. At scale, I would implement it at the API gateway layer using a distributed cache like Redis to maintain counters for specific client identifiers across multiple instances of the gateway.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd86a4b4f-1a0e-4a6a-9010-669fab2a25e6', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the benefit of the Next.js Font optimization?', N'Fresher', N'Next.js automatically optimizes fonts, including custom Google Fonts, at build time. This prevents layout shifts and reduces network requests, leading to better performance and visual stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5988f88-bc75-411e-864f-669fc5e1d0a9', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the benefit of Vite''s ''Code Splitting'' feature?', N'Junior', N'Code splitting breaks your application into smaller chunks so that the browser only downloads the code necessary for the current page. This improves initial load times and overall performance for the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea9ed54b-8987-4301-95ee-66a0f6d500c6', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why might a company choose to use a managed cloud service over hosting their own infrastructure?', N'Junior', N'Managed services significantly reduce operational overhead and maintenance tasks, allowing the team to focus on core product features. The trade-off is higher long-term costs and potential vendor lock-in compared to self-hosted solutions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
