INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c262b225-b05b-4cfd-947c-66ae4704c033', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How to implement Memcached in Node.js?', N'Fresher', N'Memcached is a general-purpose distributed memory caching system. It is often used to speed up dynamic database-driven websites by caching data and objects in RAM to reduce the number of times an external data source (such as a database or API) must be read. Memcached is free and open-source software, licensed under the Revised BSD licence. Memcached runs on Unix-like operating systems (at least LINUX and OS X) and on Microsoft windows. We can store data to memcached server in key pair format. So whenever any request come from the app can be matched with memcached server without any query from mysql/Nosql server. This increases the performance of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'418ac588-03c3-46d4-8704-66b1e7f8c46a', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Why is ''Observability'' distinct from ''Monitoring'' in complex systems?', N'Senior', N'Monitoring tracks predefined metrics to tell you if the system is healthy, whereas observability provides the ability to understand internal system states by analyzing logs, metrics, and traces. Observability is crucial for debugging ''unknown unknowns'' that occur in unpredictable, large-scale distributed environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc6be6a8-ce85-434f-a789-66b1f19615cb', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the primary differences between Type Erasure and Reified Generics in terms of runtime introspection?', N'Senior', N'Java uses type erasure, which removes generic type information at compile time to maintain backward compatibility with pre-generic bytecode. Consequently, the runtime cannot inspect generic parameters directly, whereas languages with reified generics preserve this type information in the metadata, allowing for dynamic type checking and more robust reflection capabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8456989-03eb-4681-9ded-66b3c2250f45', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the significance of SvelteKit''s ''shallow routing'' or ''goto'' behavior regarding state persistence?', N'Senior', N'SvelteKit''s router maintains the application state during navigation by updating the URL and fetching necessary data without forcing a full page reload. This preserves component state and scroll position, providing a smooth transition that feels like a native desktop application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e801a817-ee88-40b1-8763-66b603bd86b3', N'4c000000-0000-0000-0000-000000000005', N'How do message queues help in handling traffic spikes?', N'Middle', N'Message queues act as a buffer that decouples the producer of requests from the consumer, allowing the system to ingest a high volume of requests without overwhelming the backend services. This ensures that the system can process tasks at a steady rate even when the arrival rate of incoming requests exceeds the system''s immediate processing capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a79616fc-adce-4236-b1c2-66b69b2a6b4e', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does the ''Hono'' router handle path parameters?', N'Middle', N'The router uses a pattern-matching algorithm that extracts parameters directly from the URL path. These are then injected into the context object, allowing for clean and readable access to dynamic segments of the URL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
