INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77cb6270-2c05-4e65-996d-66bb35a56570', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the role of the ActiveSupport::Notifications instrumentation system in monitoring large-scale Rails applications.', N'Senior', N'ActiveSupport::Notifications provides a pub/sub mechanism that allows developers to hook into the internals of the framework to track execution time and event frequency. It is essential for building custom observability tools, enabling granular performance tracing across the request lifecycle without modifying core framework code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6903f0d7-0183-4205-9673-66bbce4114d1', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does the EventEmitter works in Node.js?', N'Fresher', N'EventEmitter maintains an internal registry (a plain object) mapping event names to arrays of listener functions. When you emit an event, it looks up that array and calls each function synchronously in registration order. * Event Emitter emits the data in an event called message * A Listened is registered on the event message * when the message event emits some data, the listener will get the data Building Blocks: * .emit() - this method in event emitter is to emit an event in module * .on() - this method is to listen to data on a registered event in node.js * .once() - it listen to data on a registered event only once. * .addListener() - it checks if the listener is registered for an event. * .removeListener() - it removes the listener for an event. Example 01: Example 02:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1503e15-62ac-45c3-9126-66bd652462a0', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What happens if you have a circular dependency in Webpack?', N'Junior', N'A circular dependency occurs when two or more modules depend on each other. While Webpack can often handle this, it can lead to unexpected behavior or ''undefined'' values for exports; it is generally considered a design flaw to avoid.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdccd07f-4144-4b49-b17e-66becf4d5d2f', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the ''public'' folder used for in Next.js?', N'Junior', N'The ''public'' folder is used to store static assets like images, fonts, and robots.txt files. These files are served from the root path of your website and are not processed by the build tool.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c80c773-a095-4514-97b5-66c48d550a44', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are computed properties?', N'Intern', N'Computed properties do not store a value directly but instead provide a getter and an optional setter to calculate or derive a value. They are useful for encapsulating logic that depends on other properties or external states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44c92d1c-dd6f-461c-971e-66c58c14e442', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are some common security headers and their purpose?', N'Fresher', N'Security headers are HTTP response headers that help protect web applications from various attacks. Some common security headers include: - Content-Security-Policy (CSP): Prevents cross-site scripting (XSS) and other code injection attacks by specifying allowed content sources. - X-Content-Type-Options: Prevents MIME type sniffing by instructing the browser to follow the declared Content-Type. - Strict-Transport-Security (HSTS): Enforces secure (HTTPS) connections to the server. - X-Frame-Options: Prevents clickjacking by controlling whether a page can be displayed in a frame. - X-XSS-Protection: Enables the cross-site scripting (XSS) filter built into most browsers. - Referrer-Policy: Controls how much referrer information is included with requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a13b2ccc-7976-4449-b5f3-66c65918da92', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the cluster state work and why is it critical to keep it lightweight?', N'Senior', N'The cluster state contains metadata about indices, mappings, and node assignments, maintained by the master node and propagated to all nodes. If the state becomes too large, cluster operations like shard allocation and node joining become slow, potentially leading to instability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c30be3e-6e5f-4d71-82bf-66c8b839e97b', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Compare the ''middleware'' approach in Express to the ''interceptor'' pattern in more modern backend frameworks.', N'Senior', N'Express middleware is a linear chain where each link must call ''next'', which is prone to human error. Interceptor patterns in modern frameworks are often more declarative and provide cleaner lifecycle hooks, making it easier to ensure cross-cutting concerns are applied consistently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c0d9bc0-c7e0-419b-8324-66ca86658265', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is a Qwik ''Component''?', N'Intern', N'A Qwik component is a building block of the user interface that is designed to be lazy-loaded. Unlike traditional frameworks, Qwik components are split into separate parts so that the component''s structure can be rendered without downloading the logic for its interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4331f78-265c-4492-afb9-66caa3297d5e', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How can you detect if a message consumer is lagging?', N'Middle', N'You can monitor the consumer lag, which is the difference between the latest produced message offset and the latest consumed message offset in a partition. A growing lag indicates that the consumer cannot keep up with the producer rate and requires scaling or optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ea3fe58-f460-4b08-86da-66cb1cd18bfc', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the purpose of a keep-alive component?', N'Middle', N'The keep-alive component caches the state of dynamic components when they are toggled, preventing them from being destroyed and re-initialized. This is useful for preserving user input or scroll position when navigating between tabs or views.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea90b0ca-04e4-4dde-928e-66cb42250ebe', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the benefit of using the Elixir language for Phoenix?', N'Junior', N'Elixir provides a clean, functional syntax that is easy to read while maintaining the power of the Erlang VM. It is designed for high-availability systems, making it ideal for the high-concurrency needs of modern web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0778f833-f0f6-4e93-b6bf-66ce51067135', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the UNION operator used for?', N'Junior', N'The UNION operator is used to combine the result sets of two or more SELECT statements into a single result set. It removes duplicate rows by default, whereas UNION ALL includes all duplicates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f2636be-69fa-48c1-b745-66cea5ba9866', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are error boundaries in React for?', N'Intern', N'Error boundaries in React are components that catch JavaScript errors thrown during rendering, in lifecycle methods, and in constructors of their child component tree, then display a fallback UI instead of crashing the whole application. They are implemented as class components using static getDerivedStateFromError (to render a fallback) and optionally componentDidCatch (for logging). Since React 16, an uncaught error unmounts the entire React tree, which makes error boundaries effectively required for production apps. Error boundaries do not catch errors inside event handlers, asynchronous code, or server-side rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dde09d6b-bed4-4ee3-b036-66cf793a613a', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of the ''void'' keyword when used as a return type?', N'Intern', N'When used as a return type, ''void'' indicates that a function does not return any value to the caller. It signifies that the function performs an action rather than calculating and providing a result.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'720e919d-d7b1-465b-bf40-66d03e5bbbc7', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How can one optimize the AdonisJS event emitter for high-throughput background processing?', N'Senior', N'The default event emitter is synchronous, which can cause significant bottlenecking if used for blocking tasks. For high-throughput requirements, developers should integrate a persistent message broker like Redis or RabbitMQ to handle asynchronous event dispatching, ensuring the main request-response cycle remains unblocked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8eb76a53-23fe-4419-84b4-66d09a792bad', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it important to check the logs before trying to fix a software bug?', N'Fresher', N'Logs provide historical context and specific details about the system state at the time of the failure. They often contain stack traces or error codes that point directly to the module or function where the error originated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4df5965d-0fb9-4c6c-80b1-66d10bae3eeb', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How do AdonisJS ''Migrations'' ensure database consistency across environments?', N'Middle', N'Migrations act as version control for your database schema, allowing you to track and apply structural changes in a deterministic order. They ensure that all developers and environments share an identical schema state, eliminating issues with manually updated databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1c6232c-7a71-4623-bc9f-66d3bd66f02c', N'954a0331-deff-4399-b588-96f39fec001d', N'What is a service in Angular and how do you create one?', N'Fresher', N'An Angular service is a class used to encapsulate logic, data fetching, or shared functionality that isn''t directly tied to the user interface. They promote separation of concerns, making your code more modular, reusable, and testable. You typically create a service using the Angular CLI: This command creates a class decorated with @Injectable(). The @Injectable() decorator marks the class as a potential target for dependency injection and, when used with providedIn: ''root'', makes the service a singleton available throughout your application. You then inject the service into components or other services that need to use its functionality via their constructors. > Try out Angular coding questions on GreatFrontEnd. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'826619a4-cdef-4c2a-8170-66d53b00a0bf', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript handle conditional types when applied to union types?', N'Senior', N'When conditional types act on a generic type that is a union, they become ''distributive,'' meaning the condition is applied to each member of the union individually. This results in the final output being a union of the conditional results, which is a powerful tool for filtering or mapping complex types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21e8d0e6-55f4-4a7d-9663-66d72ba30e15', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How are properties passed from parent to child components in SolidJS?', N'Intern', N'Properties are passed as an object to the child component. Because SolidJS components only run once, these properties act as getters that the child can use to react to changes from the parent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e3814ae-5ad8-443b-84be-66d7587f5693', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain the role of the Oplog in a MongoDB replica set.', N'Middle', N'The Oplog is a capped collection that stores a rolling record of all operations that modify the data stored in the database. Secondary nodes read from the primary''s Oplog to replicate data changes, ensuring that all members of the replica set stay synchronized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'484c9765-4f13-45d0-ae46-66dabd942179', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are the trade-offs of using Pydantic models versus raw dictionaries in FastAPI?', N'Middle', N'Pydantic models provide strict schema validation, type coercion, and IDE autocompletion, which improves code maintainability. While raw dictionaries offer slightly less overhead, they lack automatic validation and documentation, leading to fragile code that is prone to runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8c676ac-061a-4117-a48f-66dd2c535d96', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is inheritance and why is it used?', N'Junior', N'Inheritance is an object-oriented concept where a subclass acquires the properties and behaviors of a parent class. It promotes code reusability and allows for the creation of hierarchical relationships between classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32b14c3f-047f-473c-b6fe-66e5be9b5f37', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro''s ''Islands Architecture'' differ from the hydration strategy used in traditional Single Page Applications?', N'Senior', N'Traditional SPAs typically hydrate the entire DOM tree on the client, regardless of interactivity needs. Astro''s Islands Architecture isolates interactive components, hydrating only those specific parts while treating the rest of the page as static HTML, which significantly reduces the initial JavaScript payload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8765d5da-7113-48db-88dd-66e7563521a1', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Describe the impact of class loading on application startup latency.', N'Senior', N'Class loading involves reading bytecode, verifying integrity, and resolving symbols, all of which occur before execution. A large number of classes leads to high I/O and CPU overhead, which is why techniques like Class Data Sharing (CDS) are used to preload and map class metadata into memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bbe1eef-b34c-42b8-8654-66e7a699897d', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact''s architecture differ from React regarding bundle size and performance?', N'Senior', N'Preact is designed as a lightweight alternative that strips out non-essential features like synthetic event systems and unnecessary prop type checking. It prioritizes a minimal footprint by leveraging browser-native DOM APIs and a highly optimized diffing algorithm, resulting in significantly faster mount times and reduced memory overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9dba2f1f-5088-4764-8334-66ea5d2d2534', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between a feature-rich product and a minimal viable product (MVP)?', N'Fresher', N'An MVP is better for testing assumptions and getting feedback from real users early, reducing the risk of building unwanted features. A feature-rich product aims to provide a complete solution immediately but risks over-engineering based on unverified requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2e2241f-fddd-452d-a89d-66ea82f72b86', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the primary trade-off when implementing distributed tracing in a high-throughput system?', N'Senior', N'The primary trade-off is the overhead of data ingestion and storage versus the resolution of visibility. Sampling is typically employed to manage the volume of trace data, which means you may lose visibility into rare or edge-case request paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fdd9be6-822a-4b9d-8f86-66ef7a6ef621', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What are the potential performance risks of long-running transactions?', N'Middle', N'Long-running transactions hold locks for extended periods, leading to increased contention and blocking other processes. They also prevent the garbage collection of old data versions in MVCC systems, which can lead to storage bloat and increased scan latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b1fb6c9-a019-48b3-8573-66f18538c8bc', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the primary role of the Tower middleware ecosystem in Axum?', N'Middle', N'Tower provides a modular abstraction for service-based middleware that Axum builds upon. It allows developers to compose functionality like timeouts, rate limiting, and authentication into a request-response pipeline without modifying the core business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3525416e-0b05-4b97-a637-66f2c59b6c1e', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the difference between an Astro component and a framework component?', N'Intern', N'Astro components are rendered exclusively on the server and result in zero overhead. Framework components, like those from React, are rendered by the client library to provide interactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a496e603-5841-4a6a-9a1f-66f54740e5be', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the advantage of using a Columnar storage format for OLAP databases?', N'Senior', N'Columnar storage stores data by column rather than row, which allows for massive I/O reduction when queries only need a subset of fields. It also benefits from high compression ratios due to the homogeneous nature of column data, making it ideal for aggregate analytical queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98c331c8-e2c7-440c-af55-66f8479fcdbb', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Why is the absence of a global ''App'' instance in Hono considered a design improvement for testing?', N'Senior', N'By encouraging the creation of isolated instances, Hono makes it trivial to spin up a fresh server environment for each integration test. This eliminates state leakage between tests and allows for parallel execution, which is essential for maintaining a fast CI/CD pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d83d561-ade7-40f3-a73a-66ff0269fa72', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a surrogate key?', N'Intern', N'A surrogate key is an artificial primary key created by the database designer, often a simple auto-incrementing integer. It has no business meaning and is used solely to identify records uniquely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1adc86e-88c0-4f3a-a5b9-6703a5373dd5', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How do you optimize a Spring Boot application for performance?', N'Middle', N'Performance can be optimized by tuning the embedded web server, managing connection pools, using lazy loading for database entities, and optimizing cache usage. Additionally, monitoring metrics via Actuator and analyzing heap dumps can help identify memory leaks or bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3127ee58-24a2-4251-9882-6704b8243041', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the role of the Write-Ahead Logging (WAL) protocol in crash recovery?', N'Middle', N'WAL ensures durability by recording all modifications to the data in a persistent log before applying them to the actual data files. If the system crashes, the database can use this log to replay committed transactions or undo uncommitted ones to restore consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18dcd927-674a-42c3-bdb3-6705c5facd19', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the benefit of Tailwind CSS''s focus on ''composition'' over ''abstraction''?', N'Fresher', N'Composition allows developers to create complex UIs by combining simple utility classes directly in the HTML. This avoids the need to maintain large, separate CSS files and prevents the naming fatigue associated with creating custom class names for every small element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88f15454-b976-49db-999f-67064066e13e', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'When designing a large-scale Nuxt application, what are the primary considerations for ''Middleware'' performance?', N'Senior', N'Since global middleware runs on every route change, expensive operations should be avoided. Use lazy loading for middleware if possible and ensure that the code is as efficient as possible to prevent bottlenecks in client-side navigation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08f3287d-1aa6-4d78-9666-67069b7b0362', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is it dangerous to pass the Fiber context (ctx) to a separate goroutine?', N'Middle', N'The context object is strictly owned by the main request handler and is returned to an object pool once that handler returns. Accessing or modifying the context inside an asynchronous goroutine after the handler has finished will cause data races and memory corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80cd861e-caae-4d33-9523-670893b7d8a4', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between ''final'' and ''const'' when applied to a class member?', N'Junior', N'A ''final'' field must be initialized when the object is constructed and cannot be changed later. A ''const'' field at the class level must be declared as ''static const'', as it represents a compile-time constant shared by all instances of the class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e37c2586-7964-4820-8ef4-670abe99aa93', N'954a0331-deff-4399-b588-96f39fec001d', N'Describe the concept of ''Hydration'' in modern Angular and how it improves user experience.', N'Senior', N'Hydration is the process where the client-side application initializes over the static HTML delivered by the server. Modern Angular hydration preserves DOM nodes created during SSR instead of destroying and re-rendering them, which prevents screen flickering and drastically improves the Time to Interactive metric.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4814d052-582d-400c-9bf6-67108d876e15', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What are the trade-offs of using Echo''s built-in validation compared to a dedicated validation service?', N'Senior', N'Built-in validation using struct tags is convenient for simple schema checks but lacks the flexibility of a dedicated service. A dedicated validation service is better for complex business rules that require database lookups or inter-service communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6beb0b91-697b-4e30-8fd3-6713edb2c725', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What does it mean for a framework to be ''Progressively Hydratable''?', N'Intern', N'While Qwik is non-hydrating, the concept of progressive hydration involves loading parts of a page over time. Qwik takes this further by ensuring that only the specific code for the exact interaction is loaded, rather than hydrating whole sections of the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2363d58-b97a-4647-9d03-6716918d1bd6', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What makes Fastify''s router fast?', N'Fresher', N'Fastify''s router uses a Radix Tree implementation, which is highly efficient for pattern matching URL paths. This allows the framework to find the correct route handler extremely quickly, even with a large number of defined routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e893f568-8b9f-41fe-9b6b-6719246a478e', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain how Node.js streams implement backpressure and why it is critical for system stability.', N'Senior', N'Backpressure occurs when a readable stream produces data faster than a writable stream can consume it. Node.js signals this via the return value of the write method, allowing the producer to pause until the buffer drains, preventing unbounded memory growth and potential crashes under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c1dddda-0c50-4b2e-9d62-671a83d99fcd', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How do Phoenix ''GenServers'' contribute to maintaining system state without external cache layers?', N'Senior', N'GenServers act as isolated, stateful processes that can hold data in memory, effectively serving as an in-memory database or cache. This allows for low-latency state access without the network overhead of calls to external systems like Redis, provided the state can be adequately managed and recovered if the node restarts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df014d5f-44e6-4a29-a5cb-671c0b810109', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How can you verify that your fix truly resolved the issue?', N'Junior', N'I would verify the fix by running the reproduction steps that originally caused the error and ensuring the outcome is now correct. Additionally, I would run existing unit and integration tests to ensure that the fix has not introduced any regressions in other parts of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93fea68f-a1c7-400c-826b-671c3b0c4fae', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of the Lucid ORM in AdonisJS?', N'Fresher', N'Lucid is the built-in Object-Relational Mapper for AdonisJS. It allows developers to interact with database records using JavaScript objects and classes instead of writing raw SQL queries, making database operations more readable and maintainable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8980fe35-9589-4cb3-a7e1-671e90c9f3b2', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is a Radix tree in the context of Gin''s routing?', N'Fresher', N'A Radix tree is a space-optimized trie data structure used by Gin to store URL paths. It allows for extremely fast route matching by traversing the tree based on path segments rather than iterating through a list of routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c9268b3-cf86-4e9d-9149-6720870164ca', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the primary architectural benefit of implementing an Event-Driven Architecture (EDA) compared to request-response patterns?', N'Senior', N'EDA facilitates loose coupling and asynchronous processing, allowing services to operate independently without waiting for immediate responses. This pattern improves system resilience and responsiveness, though it requires sophisticated handling of distributed tracing and eventual consistency management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec952b96-df5f-4838-b8ca-672106c6d6c4', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How do you ensure consistent observability in a FastAPI microservice?', N'Senior', N'Consistency is achieved by implementing middleware that injects a correlation ID into every request, which is then passed to all downstream services. Integrating structured logging, OpenTelemetry for distributed tracing, and exposing a Prometheus metrics endpoint allows for comprehensive monitoring and debugging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5da3ea5c-a22a-488c-b802-67221ce9ae51', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle a scenario where two microservices have a circular dependency?', N'Middle', N'I would refactor the architecture to introduce an intermediary message broker or a shared data store to decouple the services. If that is not possible, I would extract the shared functionality into a third, independent service that both can consume.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ad0bebe-660c-4af2-9b29-672266f542e7', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the significance of the Thread Pool''s hill-climbing algorithm?', N'Senior', N'The hill-climbing algorithm dynamically adjusts the number of threads in the pool based on throughput metrics to maximize CPU utilization. It attempts to balance the cost of context switching against the need for concurrency, throttling thread creation when it detects diminishing returns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd49c0039-932e-4fd8-976c-6723b654de2d', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the benefit of Alpine.js''s ''reactive'' nature?', N'Intern', N'The reactivity in Alpine.js means that when the underlying data in a component changes, the UI automatically updates to reflect those changes. This removes the need for manual DOM manipulation to sync the state with the visual representation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81fd304e-75f4-44c4-ac1a-6727083b7e19', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is Static Site Generation (SSG)?', N'Intern', N'Static Site Generation is a method where HTML pages are generated at build time rather than at request time. These pre-rendered pages are then served to users, which results in extremely fast load speeds and reduced server load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
