INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a6320e7-2a66-4d87-81e9-672cc55c9ec3', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How do you handle ''Backpressure'' in a Phoenix application?', N'Middle', N'Backpressure is managed by using GenStage or by limiting the number of concurrent processes that handle input. This prevents a system from being overwhelmed by requests, ensuring that the application processes data at a sustainable rate rather than crashing under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
