INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8caba8a0-a406-4264-874f-67371d2698fc', N'954a0331-deff-4399-b588-96f39fec001d', N'Is it all components generated in production build?', N'Senior', N'No, only the entry components and template components appears in production builds. If a component isn''t an entry component and isn''t found in a template, the tree shaker will throw it away. Due to this reason, make sure to add only true entry components to reduce the bundle size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16244a64-a799-4bca-aab3-6739089c9215', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the purpose of memoized selectors (e.g., using Reselect)?', N'Middle', N'Memoized selectors prevent unnecessary re-computations of derived data. If the input state hasn''t changed, the selector returns the previously calculated result, which is crucial for performance when dealing with complex data transformations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ded5621-841a-424d-be83-673acaa0c8eb', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain the trade-off of the CAP theorem.', N'Middle', N'The CAP theorem states that a distributed system can only provide two out of three guarantees: Consistency, Availability, and Partition tolerance. In the presence of a network partition, a system architect must choose between maintaining strict data consistency or ensuring the system remains available.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
