INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0965a05d-7d2e-4dc2-94b9-67503baafa29', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Why would you use a ValidationPipe?', N'Junior', N'ValidationPipe is a built-in pipe that automatically validates input data against a DTO using decorators. It ensures that the application only processes data that meets the specified schema, preventing errors caused by invalid input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc01461b-a4aa-4208-9099-67506665ec64', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the ''Circuit Breaker'' pattern and when should it be used?', N'Middle', N'The Circuit Breaker pattern prevents a cascading failure by stopping requests to a service that is known to be failing or unresponsive. It provides a fallback mechanism, allowing the system to degrade gracefully rather than exhausting resources on doomed requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19df4862-fa52-446e-8891-675196854707', N'4c000000-0000-0000-0000-000000000005', N'How would you design a system to ensure strong consistency in a globally distributed database?', N'Senior', N'Use consensus algorithms like Paxos or Raft to synchronize state across nodes. While this ensures strong consistency, it significantly increases latency due to cross-region round trips, so it should only be used when absolute data integrity is more critical than availability and performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecb79c2f-96c0-4777-833f-675385ce7d19', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is a dynamic route in Nuxt?', N'Junior', N'A dynamic route is defined by using underscores in a filename, such as _id.vue. This tells Nuxt that the segment is a variable, allowing you to access parameters from the URL within your component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85223095-fe9a-403b-b05f-6753ec986dc2', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB handle horizontal scaling?', N'Intern', N'DynamoDB scales horizontally by automatically partitioning data across many different storage servers. As your data grows, the database splits these partitions to distribute the load evenly, allowing for unlimited storage and throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e955ab21-091f-4fc6-879f-6754c471609c', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does CSS painting order work with stacking contexts?', N'Middle', N'Stacking contexts are layers created by certain CSS properties, like z-index, opacity, or transform, that dictate the order in which elements are rendered on the screen. Elements within a stacking context are rendered relative to their parent context rather than the entire document. Understanding these contexts is essential for managing complex overlaps and modal overlays.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf4a11bf-6489-4e01-88f6-67553cea5d93', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Describe the impact of Scala''s lazy evaluation on resource management.', N'Senior', N'Lazy evaluation defers the computation of expressions until they are accessed, which is useful for initializing expensive resources or building infinite data structures. While it saves resources, it can also lead to hidden performance bottlenecks and non-deterministic initialization order issues that are difficult to debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12690651-36fd-4072-99a7-675574d1cad4', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide between fixing a bug immediately versus prioritizing a new feature request?', N'Junior', N'I evaluate the bug''s severity and impact on users versus the business value of the new feature. If the bug prevents critical functionality, it should be prioritized, but if it is minor, I would consult with my lead to balance quick fixes with roadmap goals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25cdab40-9172-436e-a46b-67570cde48ab', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What architectural challenges arise when implementing multi-region replication in a NoSQL database?', N'Senior', N'The primary challenges are network latency between geographic regions and the complexity of maintaining write order across wide-area networks. This often necessitates asynchronous replication, which introduces the risk of data loss during regional failover and increases the window for conflict resolution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa7c60c1-ab6a-4dd0-b9a8-67584edf03d3', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What are the trade-offs of using Vite''s development approach compared to a fully bundled dev server?', N'Middle', N'The main trade-off is the discrepancy between the development and production environments, as Vite uses native ESM in development and Rollup in production. While this rarely causes issues with standard code, it can occasionally lead to inconsistencies with environment-specific plugin behaviors or complex path resolution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9a73533-be57-4d3c-8f8d-67589da893df', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the ''Lucid Model'' pattern and how does it handle database queries?', N'Middle', N'The Lucid Model is an implementation of the Active Record pattern, where each class represents a table and instances represent individual rows. It provides a fluent query builder interface that abstracts SQL generation, allowing for readable and maintainable database interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56a65a37-3928-4769-91ac-675b04fb2003', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of the ''render_template'' function?', N'Intern', N'The render_template function is used to load and display HTML files stored in the templates folder. It allows developers to inject dynamic data from Python variables into HTML pages using the Jinja2 templating engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6402baf-fc0b-4b68-be04-675ba4b12d31', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is a ''Global Middleware'' in Hono?', N'Intern', N'A global middleware is a function that is applied to every request received by the application, regardless of the route. It is often used for global tasks like initializing request IDs, logging, or setting common security headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ee7db17-3e6d-4d21-8274-675c74ec4450', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are lifecycle methods in Preact class components?', N'Junior', N'Lifecycle methods are special hooks like ''componentDidMount'' or ''componentWillUnmount'' that allow you to run code at specific points in a component''s existence. In functional components, these are replaced by the useEffect hook.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d9c70f2-476c-4829-8e60-675da7914a7b', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How do you handle database migration conflicts when multiple developers are working on the same codebase?', N'Senior', N'Conflicts arise when multiple developers generate different migration files with the same dependency parent. These must be resolved by manually merging the migration files, often by squashing or re-generating the migrations to ensure a linear and consistent migration history.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53522a7a-7861-46ba-b26b-675e61000dc4', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why would you choose to use an Ember Engine over a standard addon?', N'Middle', N'Ember Engines allow for lazy-loading distinct parts of an application, which is beneficial for large-scale projects to reduce the initial bundle size. Unlike addons, engines provide isolated routing and dependency management, making them ideal for complex, modular architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f52ef083-810a-4a67-875a-676095758fec', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the purpose of the @forward rule?', N'Middle', N'The @forward rule allows you to bundle multiple modules together and expose them through a single entry point. It is typically used in index files to organize a component library, allowing users to import one file while gaining access to all relevant mixins and functions without exposing internal helpers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15e57099-bc17-4259-97bb-67643fd2943e', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the purpose of the Actix HttpServer?', N'Intern', N'The HttpServer is the component responsible for listening for incoming TCP connections and delegating them to the application logic. It manages the underlying event loop to handle many simultaneous connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c303f6fc-3d81-4db9-b047-6764c1b6e363', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How do ''Read-Repair'' strategies in distributed caches help maintain data integrity?', N'Senior', N'Read-repair detects inconsistencies between multiple replicas or between the cache and the database during a read operation. When a mismatch is identified, the system proactively updates the stale replica or cache entry, ensuring data accuracy without requiring a full system scan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0190f27d-9eda-4d62-8ca2-6765fb458f25', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Describe the architectural implications of implementing HATEOAS in a high-scale production API.', N'Senior', N'HATEOAS promotes discoverability and loose coupling by providing navigation links within the response. However, it significantly increases payload size and adds complexity to the client-side implementation, which is why many high-scale systems favor static documentation like OpenAPI over dynamic hypermedia.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fb2ccb3-543a-4002-ab2f-676a0393b91b', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the visibility map?', N'Middle', N'The visibility map keeps track of which pages in a table contain only tuples that are visible to all active transactions. This allows the database to perform index-only scans, where the system fetches data directly from the index without needing to visit the actual heap table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3db7162-85df-45f9-af39-676ccdb0d551', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Explain the difference between ''Metadata'' and ''Static Metadata'' in Next.js.', N'Middle', N'Static metadata is defined as a constant object exported from a file, suitable for fixed page titles and descriptions. Dynamic metadata uses the generateMetadata function, which allows you to fetch data from an API or database to create page-specific tags based on dynamic route parameters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'544efb64-d981-4bb0-992a-676e97305526', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between an Enum and a Const Object in TypeScript?', N'Middle', N'Enums create a distinct type and runtime object, which can lead to larger bundle sizes and less predictable behavior. Const objects with ''as const'' provide a lightweight, type-safe way to define sets of constants without the extra runtime overhead of enums.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8984b0cb-2d4c-467c-a109-6773017f1e8c', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of the ''Kernel'' class in Laravel?', N'Middle', N'The Kernel is the heart of the application lifecycle, defining both the HTTP and Console middlewares or commands. It controls the order in which requests are processed and ensures that global services are loaded before any request reaches the router.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3afa5da5-c154-4a12-b371-677542b393ad', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is a ''Mailbox'' in the Actix actor system?', N'Middle', N'A mailbox is a message queue associated with an actor that buffers incoming messages. It ensures that messages are processed sequentially by the actor, providing a thread-safe way to manage state changes without requiring explicit locks or mutexes within the actor logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9145093-e7bf-48a7-bc73-67754609f878', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is ''async'' and ''await''?', N'Junior', N'These keywords are used to perform asynchronous programming, allowing code to execute without blocking the main thread. ''async'' marks a method as asynchronous, while ''await'' pauses the method execution until the task completes, improving responsiveness in UI and web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afded0fb-ef9c-4538-8708-67778f8bc9a9', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of the ''break'' and ''continue'' statements in loops?', N'Fresher', N'The ''break'' statement terminates the execution of a loop immediately, exiting the structure entirely. The ''continue'' statement skips the remainder of the current iteration and jumps back to the beginning of the loop to process the next item.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5e5bd83-23cb-4d5e-9f69-67794560665f', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Discuss the scalability implications of using Preact in a large-scale enterprise application.', N'Senior', N'Scalability in Preact is excellent for performance-critical UIs, but it requires more discipline regarding state management and architectural patterns. Since Preact lacks the robust, built-in experimental features of React, teams must often curate their own ecosystem of libraries for complex data flows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2019627-5519-490e-bdb4-677a4ca1855b', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What does it mean for an Actix-web handler to be ''thread-safe''?', N'Intern', N'A handler must be thread-safe because it might be executed concurrently across different worker threads. This means any shared data accessed by the handler must implement specific Rust markers like Sync and Send.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20906d2a-6c7f-4273-8556-677ae6bf891d', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the primary difference between Server Components and Client Components in Next.js?', N'Junior', N'Server Components are rendered exclusively on the server, reducing the amount of JavaScript sent to the client. Client Components are rendered on the server but also hydrate on the client to allow for interactivity like event listeners and state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c0cd6c0-1c66-4756-992a-677c08bb67b4', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a microservice that has high memory consumption despite low request volume?', N'Middle', N'I would check for background tasks or cache buildup that might not be tied directly to incoming request volume. I would also investigate if the service is holding onto large objects or connections due to a slow memory leak occurring during background processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ece8b580-45d6-4e79-8582-677e686f589f', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Is Kotlin an object-oriented language?', N'Intern', N'Yes, Kotlin is an object-oriented language. It supports features like classes, objects, inheritance, and interfaces similar to other object-oriented languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8db68f2-e0e9-4341-b45e-677eb4ea9775', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the significance of the Micronaut ''Retry'' annotation in a distributed system?', N'Senior', N'The Retry annotation provides a declarative way to handle transient failures by automatically re-executing a method based on configurable policies like backoff and maximum attempts. This pattern is essential in distributed systems to improve availability when downstream services or network connections are temporarily unstable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'587f832b-a53b-499c-9e7e-677faec0ae99', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is an event flow?', N'Intern', N'Event flow is the order in which event is received on the web page. When you click an element that is nested in various other elements, before your click actually reaches its destination, or target element, it must trigger the click event each of its parent elements first, starting at the top with the global window object. There are two ways of event flow * Top to Bottom (Event Capturing) * Bottom to Top (Event Bubbling)', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb6dd77e-294f-4da6-9f35-6780a6c95b8a', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle request validation compared to manual validation logic?', N'Middle', N'AdonisJS uses a centralized Validator schema that enforces data integrity before the controller logic executes. This approach keeps controllers clean by separating the concern of request sanitization and validation from business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
