INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'030e52a6-8f2e-4569-afb5-678a48b971b6', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What filters are available in Rails controllers and how do you use them?', N'Junior', N'Filter methods in Ruby on Rails provide a powerful means to run code either before or after specific controller actions, or as a "catch-all" for multiple actions. Prefilters Prefilters, which include before_action, prepend_before_action, define methods that execute before the associated action(s). Code Example: Using before_action In this example, the authenticate_user! method is run before OrdersController#show. Postfilters Postfilters, including after_action and prepend_after_action, run methods after the respective action is executed. Code Example: Using after_action Here, log_invoice_creation is invoked after the InvoicesController#create action.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'549f9c99-5e94-4cb5-b5f2-678b51a8c9a2', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar maintain API contract stability during refactoring?', N'Senior', N'By separating the domain layer from the API layer via DTOs and using strict type hints, Litestar minimizes the impact of internal refactoring on external consumers. If an internal model changes, you only need to update the mapping logic in the DTO, keeping the public-facing interface unchanged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06e8d409-1f72-41c0-a03e-678b57e04aff', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Why is testing in R often focused on unit tests for functions?', N'Middle', N'Because R is an interactive and functional language, testing individual functions ensures that the core logic is sound regardless of the environment context. Frameworks like testthat facilitate this by providing structured testing environments that check for expected outputs, errors, and warnings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
