INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0f4ab6e-e3dc-4156-b172-6790f89f839a', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does tree-shaking function internally within Webpack, and what prevents it from working?', N'Senior', N'Tree-shaking relies on the static structure of ES modules to perform dead-code elimination by traversing the dependency graph. It fails if code uses dynamic exports, side-effectful imports, or if the transpiler converts ES modules to CommonJS, which hides the dependency structure from Webpack''s static analysis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6c59f84-6a68-4391-a9c8-6791268def32', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the data flow followed by props?', N'Intern', N'All props follows a one-way-down binding between the child property and the parent one. i.e, When the parent property is updated then that latest prop value will be passed down to the child, but not the otherway(child to parent) around. The child component should not mutate the prop otherwise it throws a warning in the console. The possible mutation cases can be solved as below, 1. When you try to use parent prop as initial value for child property: In this case you can define a local property in child component and assign parent value as initial value 2. When you try to transform the parent prop: You can define a computed property using the prop''s value,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'712edbcd-dc87-424d-b67c-67915ef1d79a', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does the lack of TypeScript support in original jQuery code impact modern developer productivity?', N'Senior', N'The original jQuery library lacks native type definitions, leading to poor IDE autocompletion and a lack of compile-time safety. While ''DefinitelyTyped'' definitions exist, they are often incomplete or imprecise, forcing developers to rely on ''any'' types, which negates the safety benefits of a strongly typed development environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3af3807-8976-46b3-ab0d-67932f5887f7', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of a status code in an Express response?', N'Intern', N'A status code is a three-digit integer sent by the server to inform the client about the outcome of their request. For example, 200 indicates success, while 404 indicates that the requested resource could not be found.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7bb90d9-7515-4590-878f-6794aeb42d26', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the InnoDB Buffer Pool improve database performance?', N'Middle', N'The Buffer Pool caches frequently accessed data and indexes in memory to minimize expensive disk I/O operations. By keeping hot data in RAM, the database can serve read requests much faster and perform write operations in memory before flushing them to disk.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fcee2a0-9b41-4509-bf78-6794c67e9462', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you determine if a performance bottleneck is caused by the application code or the infrastructure?', N'Middle', N'I isolate the problem by correlating application-level telemetry with infrastructure-level monitoring tools. If application latency remains high despite low infrastructure resource utilization, the issue is likely in the code logic or database queries; otherwise, it is an infrastructure configuration or resource constraint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bd50f39-8714-42a4-81b2-679797474030', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does the ''readonly'' modifier do in TypeScript?', N'Fresher', N'The ''readonly'' modifier prevents a property of an object or an interface from being modified after it is initialized. This is useful for creating immutable data structures and ensuring that specific properties remain constant throughout the lifecycle of an object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d0e7911-3c27-489f-ac97-6797fadee7c5', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Explain some of the pros and cons for CSS animations versus JavaScript animations?', N'Fresher', N'Regarding optimization and responsiveness the debate bounces back and forth but, the concept is: * CSS animations allows the browser to choose where the animation processing is done, CPU or the GPU. (Central or Graphics Processing Unit) * That said, adding many layers to a document will eventually have a performance hit. * JS animation means more code for the user to download and for the developer to maintain. * Applying multiple animation types on an element is harder with CSS since all transforming power is in one property transform * CSS animations being declarative are not programmable therefore limited in capability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cf9acb4-d692-410a-82d3-67988c71f912', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When estimating the impact of introducing a new microservice, what architectural factors do you prioritize?', N'Senior', N'I focus on the cascading impact on downstream dependencies, potential increases in inter-service latency, and the additional operational overhead for observability and distributed tracing. By modeling the service''s resource consumption patterns against the existing cluster utilization, I can predict whether it will necessitate infrastructure expansion or performance optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4cee50f-53f6-44b2-a6ab-679abd78740e', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How do you bind an event handler in jQuery?', N'Junior', N'You can bind events using standard methods like .on(), .click(), or .hover(). The .on() method is generally preferred as it is the most flexible and supports attaching event handlers to elements that are added to the DOM dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa42d949-bd57-4019-bef7-679c2da40457', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does C# handle exception handling performance?', N'Middle', N'Exception handling in C# is relatively expensive because it involves unwinding the stack and capturing state information. Therefore, exceptions should be reserved for truly exceptional conditions rather than used for flow control in the application''s main logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cbb6316-304f-4eb6-9904-67a0f093f87f', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of the Flask application object?', N'Intern', N'The application object is the central registry for the Flask project. It stores configuration settings, registers URL routes, and handles the request-response cycle for the entire web application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97ecf18b-ff71-443e-9bcd-67a462007d51', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain the concept of Routing in AdonisJS.', N'Fresher', N'Routing is the mechanism that maps a specific URL and HTTP method to a controller action or a closure. It acts as the entry point for incoming requests, directing them to the appropriate logic within the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24fb0ebc-fdab-4568-b877-67a4c8d18289', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is an identifier?', N'Intern', N'An identifier is a user-defined name given to variables, functions, or arrays. Identifiers must follow specific naming rules, such as starting with a letter or underscore and containing only letters, digits, or underscores.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e44e9e0-a80c-48c3-b1c1-67a6f81897c3', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How can you test asynchronous code in JavaScript?', N'Fresher', N'To test asynchronous code in JavaScript, you can use testing frameworks like Jest or Mocha. These frameworks provide built-in support for handling asynchronous operations. You can use async/await or return promises in your test functions. For example, in Jest, you can write: Alternatively, you can use callbacks and the done function to signal the end of an asynchronous test. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f0b4088-537b-4ec3-9ae9-67a92da67341', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why is the Vite ecosystem considered ''future-proof''?', N'Senior', N'Vite is built on modern web standards like native ESM and Browser APIs, which are increasingly adopted by browsers and the Node.js runtime. By aligning with these standards rather than relying on custom proprietary bundling logic, Vite ensures longevity and easier maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32e791ec-02af-4fa9-b193-67a9bd807134', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are event listeners and how are they used?', N'Intern', N'Event listeners are functions that wait for specific events to occur on elements, such as clicks or key presses. They are used to execute code in response to these events. You can add an event listener to an element using the addEventListener method. For example: ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the event phases in a browser In a browser, events go through three phases: capturing, target, and bubbling. During the capturing phase, the event travels from the root to the target element. In the target phase, the event reaches the target element. Finally, in the bubbling phase, the event travels back up from the target element to the root. You can control event handling using addEventListener with the capture option.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b238df1a-343c-4212-b3a2-67a9c60a36e1', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the primary difference between Remix''s data loading model and a standard client-side SPA approach?', N'Middle', N'Remix uses server-side data loading where loaders execute on the server before the page is rendered. This eliminates request waterfalls by fetching data in parallel on the server, whereas SPAs typically fetch data after the component mounts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04fe0426-19f3-4bf5-9253-67aa7564a713', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the difference between the ''serve'' and ''build'' commands in Vite?', N'Fresher', N'The ''serve'' command starts a development server with HMR for local coding. The ''build'' command uses Rollup to create an optimized, production-ready version of your application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2f6fa0f-1922-4b38-8ab4-67aaa085b011', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Discuss the trade-offs of using ''Constructor Injection'' versus ''Field Injection''.', N'Senior', N'Constructor injection enables immutability, facilitates testing by allowing easy mocking, and ensures that dependencies are satisfied before the bean is used. Field injection is more concise but hides dependencies, makes unit testing difficult, and violates encapsulation principles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc23b216-294e-4b97-b69e-67ac86c457a6', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is Redis and how does it store data differently from a traditional relational database?', N'Fresher', N'Redis is an open-source, in-memory data structure store used as a database, cache, and message broker. Unlike relational databases that store data primarily on disk using tables, Redis stores data directly in the system''s RAM, which allows for extremely fast read and write performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9699aec0-79fe-439c-a0d1-67ac96694ae1', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you explain the difference between a high-level language and machine code to a non-technical stakeholder?', N'Intern', N'A high-level language is written in a way that humans can easily read and understand, using logical structures. Machine code consists of binary instructions that the computer hardware executes directly, which is essentially unreadable to humans.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2eec1950-c2e7-4d27-8ea8-67acc7eefe73', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS differ from React in its rendering strategy?', N'Middle', N'Unlike React, which uses a Virtual DOM and re-renders component functions repeatedly, SolidJS compiles templates into real DOM nodes and uses fine-grained reactivity. It executes component functions only once, updating specific DOM nodes directly when their underlying data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
