INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63f76680-758a-4a9e-b8f4-67af231a7792', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Why is the use of ''Strict'' mode in AdonisJS configuration encouraged?', N'Middle', N'Strict mode ensures that your application configuration is validated against predefined schemas at startup. This prevents runtime errors caused by missing environment variables or invalid configuration types, leading to a more stable and predictable deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac8784f2-cdde-4d1b-88e9-67b336d3041f', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the difference between a request guard and a data guard in Rocket?', N'Intern', N'A request guard validates aspects of the request like headers or authentication, while a data guard is specifically used to parse and validate the body of a request. Both act as filters that must succeed for the handler to run.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
