INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0dcda5b8-5fee-474c-8ed7-67bd47c187e6', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin''s ''Flow'' architecture handle backpressure compared to Reactive Streams?', N'Senior', N'Kotlin Flows are fundamentally sequential and cold, meaning they only emit values when collected, which naturally handles backpressure through suspension rather than complex buffer overflow strategies. By suspending the producer until the consumer is ready, the system maintains a synchronous-like flow that is easier to reason about while remaining fully non-blocking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
