INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d8b9685-b463-4d34-af5e-67e2253eaf95', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of the volatile keyword in the context of memory-mapped I/O?', N'Middle', N'In memory-mapped I/O, hardware registers are accessed as memory addresses. The volatile keyword is essential here because it ensures the compiler performs an actual memory read or write operation for every access, rather than optimizing out the operation or using a cached value, which is critical for interacting with hardware state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
