INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e36e3a38-d3cf-4d87-93d2-67e534529140', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is TypeScript and how does it differ from JavaScript?', N'Intern', N'TypeScript is a statically-typed superset of JavaScript, developed and maintained by Microsoft. It enables enhanced code maintainability and predictability. After compiling, TypeScript code is transpiled into standard, browser-compatible JavaScript. Key distinctions between TypeScript and JavaScript include the use of type annotations, the ability to work with existing JavaScript code, and more. TypeScript Features & Benefits - Type System: Offers static typing, allowing developers to define the type of variables, parameters, and return values. This helps catch errors during development, reducing runtime issues. - Advanced Language Features: Incorporates modern ECMAScript syntax and features, often before they are rolled out in JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
