INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10478537-e620-4ac2-a899-67f63074c1a2', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the difference between a request and a reply object in Fastify?', N'Intern', N'The request object represents the incoming HTTP request, containing data like headers, parameters, and the body. The reply object is used to build and send the HTTP response, providing methods to set headers, status codes, and the payload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
