INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7edd7bd2-e0ca-4602-8fa5-67f915a885a1', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the role of ''Hono''s Router''?', N'Junior', N'The router is responsible for matching an incoming request''s method and URL pattern to the corresponding handler function. Hono uses an efficient trie-based routing algorithm, which allows for fast lookups even as the number of defined routes grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e825dec-4e4c-414c-b427-67f9712829b5', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is optional chaining?', N'Intern', N'According to MDN official docs, the optional chaining operator (?.) permits reading the value of a property located deep within a chain of connected objects without having to expressly validate that each reference in the chain is valid. The ?. operator is like the . chaining operator, except that instead of causing an error if a reference is nullish (null or undefined), the expression short-circuits with a return value of undefined. When used with function calls, it returns undefined if the given function does not exist.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'662d1727-62a6-41c6-bed0-67f990affff9', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain the concept of ''backpressure'' in Node.js streams.', N'Middle', N'Backpressure occurs when the source of a stream produces data faster than the destination can consume it. To prevent memory issues, the stream mechanism signals the source to slow down or pause, ensuring that the buffer does not overflow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'151eae57-4833-4e55-ac17-67fb966d7264', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the difference between ''def'' and ''val'' when defining functions?', N'Intern', N'A ''def'' defines a method that is evaluated every time it is called. A ''val'' defines a function as a value, meaning the function body is evaluated once when the variable is initialized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef06fd00-83e3-4b5a-924d-67fc8ee6d1b4', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between ''interface'' and ''type'' regarding performance?', N'Middle', N'The performance difference is generally negligible for small to medium projects, but interfaces are often faster for the compiler to process because they are cached. Type aliases can be more complex to evaluate, especially when they involve complex recursive or conditional types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20ef32e7-59e6-419e-aec2-67fc8f5d109a', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the benefit of using a Content Delivery Network (CDN) for static assets?', N'Intern', N'A CDN caches static files like images and stylesheets on servers geographically closer to the end user. This significantly reduces latency and lowers the bandwidth costs for the origin server by serving content from a nearby location.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0821eea-9b98-4251-ad7c-67fe093bf948', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the architectural impact of moving from Options API to Composition API?', N'Senior', N'The Options API organizes code by component property (data, methods, computed), which often leads to fragmented logic as components grow. The Composition API organizes code by logical concern, facilitating better code reuse through composables and allowing for a more modular, testable, and type-safe architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ac894d5-5f1c-4581-975f-6802bcd8ee66', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain the concept of ''Least Privilege'' in system design.', N'Middle', N'The principle of least privilege dictates that any module, process, or user should only have access to the information and resources necessary for its legitimate purpose. This minimizes the potential impact if a specific component is compromised.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c7f75eb-3c25-4535-af4a-6804f23bc17a', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is an interface in C++?', N'Junior', N'C++ does not have a formal ''interface'' keyword, but it is implemented using an abstract class that contains only pure virtual functions. It defines a contract that derived classes must fulfill by providing their own implementations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3897197-f1c5-4a41-ad7d-6806158a2b26', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is database normalization and why is it important?', N'Junior', N'Normalization is the process of organizing data in a database to reduce redundancy and improve data integrity. It involves dividing large tables into smaller, related tables to ensure that each piece of data is stored in only one place.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00955d88-67d9-4a4b-855a-68069d55468d', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of the LIMIT clause?', N'Intern', N'The LIMIT clause is used to restrict the number of rows returned by a query. It is commonly used for pagination to ensure that a manageable amount of data is retrieved at once.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bdd0888-50c2-4472-88a9-6806eb8b3725', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle request bodies?', N'Fresher', N'Axum provides extractors like Bytes, String, or Json to read the request body. These extractors handle the task of reading the incoming stream of data and converting it into a usable format for the handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd545864a-b23f-4af2-92fa-68086e03619b', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI''s handling of database connections influence application scalability?', N'Senior', N'FastAPI does not include a built-in ORM, leaving connection management to the developer via dependencies. Proper scalability requires using connection pooling, typically handled by libraries like SQLAlchemy or Tortoise, to manage resource constraints and prevent connection exhaustion under heavy load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34faf858-172b-48d0-bbbe-6809516d3382', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of a configuration file in Flask?', N'Fresher', N'A configuration file is used to manage application settings such as database URIs, secret keys, and debug modes. This separates environmental settings from the application logic, making the code more portable and secure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33efb280-d0cf-4941-a7a1-68098b5ea55f', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What happens if a Fastify route handler throws an error?', N'Fresher', N'If a handler throws an error, Fastify automatically catches it and triggers the error handling pipeline. The response will be sent with an appropriate error status code, usually 500, unless a custom error handler is configured.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e6dd4be-b41f-4ee2-bddb-680a26c9bc1c', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle timeouts?', N'Fresher', N'Fiber allows developers to configure read and write timeouts through the server settings. This helps prevent resources from being held open indefinitely by slow or malicious clients.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f54e8a12-f107-4c07-8e56-680f7a34d346', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does z-index work with non-positioned elements?', N'Fresher', N'z-index has no effect on elements with position: static (the default). For z-index to work, the element must have a position value of relative, absolute, fixed, or sticky. Example: Natural stacking order without z-index (back to front): 1. Background and borders of root element 2. Block-level descendants (non-positioned) 3. Floating descendants 4. Inline descendants (non-positioned) 5. Positioned descendants (z-index: auto or z-index: 0) 6. Positioned descendants with positive z-index', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eadac964-54a9-49f0-99ce-681183d7b35e', N'4c000000-0000-0000-0000-000000000005', N'How does sharding affect the performance and complexity of join operations?', N'Senior', N'Sharding distributes data across nodes, making cross-shard joins extremely expensive as they require coordinating data from multiple physical locations. Architects must often denormalize data or move join logic into the application layer to maintain acceptable latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e5c9345-cb3c-455e-aa50-68125e2d2c0c', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How would you diagnose a performance bottleneck in a microservices architecture that involves multiple asynchronous message queues?', N'Senior', N'I would implement distributed tracing to visualize the request lifecycle across service boundaries. By analyzing queue depth metrics and consumer processing times, I can isolate whether the bottleneck stems from producer saturation, consumer throughput limitations, or downstream database contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'413c9092-7b18-4c8b-8b65-6812b79f931b', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Why is testing in R often more challenging than in compiled languages?', N'Middle', N'Because R is dynamically typed and relies on lazy evaluation, many errors are only caught at runtime rather than during compilation. Effective testing requires comprehensive unit testing frameworks to validate edge cases and ensure that dynamic dispatch behaves as expected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'613a4cdf-e6bb-48fa-9b8c-68173a7a70b3', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How does CQRS (Command Query Responsibility Segregation) benefit microservices?', N'Middle', N'CQRS separates the data modification operations from the data retrieval operations into different models. This allows developers to optimize the write side for consistency and the read side for performance, enabling independent scaling and customized data views for different service needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4f9ce69-89a5-44d2-ac21-6818676d2693', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to use innerHTML in React?', N'Fresher', N'The dangerouslySetInnerHTML attribute is React''s replacement for using innerHTML in the browser DOM. Just like innerHTML, it is risky to use this attribute considering cross-site scripting (XSS) attacks. You just need to pass a html object as key and HTML text as value. In this example MyComponent uses dangerouslySetInnerHTML attribute for setting HTML markup:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86da3df8-1297-45e7-8b4d-6821a4d47240', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you handle API request tracing in a polyglot microservice environment?', N'Senior', N'Implement distributed tracing by injecting unique correlation IDs into headers at the API Gateway or ingress point. These IDs must be propagated across all downstream service calls, allowing tools to reconstruct the full request lifecycle across the distributed system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cebfa2b4-aeec-4d18-beba-6821ffedf28a', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the benefit of using ''IntoResponse'' in Axum?', N'Middle', N'The IntoResponse trait provides a unified way to convert various custom types into an HTTP response. It allows developers to define domain-specific error types that automatically map to appropriate HTTP status codes and body formats.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
