INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b31da6de-faa8-466d-8973-68245ea006c6', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of an Ember Model?', N'Fresher', N'An Ember Model represents the data structures within an application. It defines the attributes of an object and its relationships with other models, serving as the source of truth for the application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d880f1f-5c2c-420d-aff4-6824a470fc0d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason about the trade-off between ''perfect code'' and ''shipping fast'' in a startup environment?', N'Senior', N'I use a risk-based approach: if the code is in the critical path for security or core financial logic, it must be robust. For experimental features, I prioritize speed but insist on technical debt tracking so that if the feature succeeds, it can be refactored before it becomes a liability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'436c7ea8-6fe3-402f-9211-682616a4f86c', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Describe the impact of the fillfactor setting on table and index performance.', N'Senior', N'The fillfactor determines the percentage of space utilized in a page, leaving the remainder for future updates. A lower fillfactor reduces page splits and bloat during frequent updates at the cost of increased storage footprint and potentially slower sequential scans due to reduced data density.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a285008f-f874-4193-97f5-68271f050f30', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are the advantages of using Sass over standard CSS?', N'Fresher', N'Sass provides advanced features like logic, math operations, and better organizational tools like nesting and modules. These features reduce repetitive code, improve file maintenance, and allow for a more structured approach to managing large style projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f9be568-b760-45f2-9338-68279eedc72b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does ''Tail Call Optimization'' influence recursion in JavaScript, and what is its current status in modern engines?', N'Senior', N'Tail Call Optimization allows engines to reuse the current stack frame for recursive calls, preventing stack overflows. However, it is rarely implemented in modern JavaScript engines due to its complexity and its tendency to obscure stack traces, making it unreliable for developers to depend on.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67fb9a9a-9ec7-41df-8df3-6828c8f5bfdb', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'When should you use a Nuxt ''Plugin'' versus a ''Composable''?', N'Middle', N'Plugins are best used for global registration, such as injecting third-party libraries or adding Vue directives that need to be available throughout the entire app lifecycle. Composables are intended for encapsulating reactive logic and state that can be shared between components as needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e81a662-2947-493b-b8f0-682a38a13727', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a lock in database transactions?', N'Intern', N'A lock is a mechanism that restricts access to a piece of data, such as a row or table, to prevent conflicts. It ensures that only one transaction can modify or read specific data at a time, depending on the lock type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb022735-2d4d-4b19-93f3-682df7415feb', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo support static files?', N'Intern', N'Echo includes functionality to serve static files like images, CSS, and JavaScript from a specific directory on the server. This allows the backend to host front-end assets directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0f096a6-d5e3-40e8-9ff9-682e227cb3a7', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala handle multiple inheritance?', N'Intern', N'Scala handles multiple inheritance through traits. A class can extend one class but mix in multiple traits to inherit their methods and fields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1cd67fb3-30d1-4190-8116-683160c81975', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'In a scenario where a system is running slowly, how would you begin to investigate?', N'Intern', N'I would start by checking system resource metrics like CPU usage, memory consumption, and network latency to see if there is a clear bottleneck. Once a resource is identified as the culprit, I would investigate the processes or services consuming that resource.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c86d05f-5c09-4a44-a002-683634095a16', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the purpose of the ''Context'' object in Gin?', N'Intern', N'The Context object is the central structure in Gin that holds data about the current HTTP request and response. It allows developers to retrieve parameters, read request bodies, set response headers, and send data back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2ea6592-d1cf-41b1-a365-683a1c7d9bee', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring AOP work?', N'Middle', N'Spring AOP uses proxies to intercept method calls, allowing developers to inject cross-cutting concerns like logging, security, or transaction management. It dynamically creates a wrapper around the target bean, executing the aspect logic before, after, or around the actual method invocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd6157e2-e710-4228-ab9e-683a37ed10ee', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What are the trade-offs of having too many shards in an Elasticsearch cluster?', N'Middle', N'Having too many shards leads to high overhead for the cluster state because each shard requires memory and CPU to manage. It can also cause slow recovery times and increased heap pressure, potentially leading to cluster instability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
