INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29e2b66c-808b-426c-a2db-683de4383e15', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is Starlette and how does it relate to FastAPI?', N'Intern', N'Starlette is a lightweight ASGI framework/toolkit that serves as the foundation for FastAPI. FastAPI builds on top of Starlette to provide advanced features like automatic documentation and data validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50941bb3-0bc2-4e6b-bb81-6841ac7d9aea', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you manage cross-origin resource sharing (CORS) in a Flask application?', N'Middle', N'You should use the ''Flask-CORS'' extension to handle CORS headers, which allows you to define which origins, methods, and headers are permitted to access your API. This is essential for secure web applications where the frontend and backend may be hosted on different domains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
