INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af3a3c4d-3ab0-4cf8-8451-6846b897262d', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the difference between ''register'' and simply importing modules in Fastify?', N'Junior', N'The register method is used to load plugins and ensures that the plugin''s context is correctly encapsulated within the current server scope. Using register allows Fastify to manage dependencies and lifecycle events, whereas direct imports do not provide this framework-level integration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16a9f400-2fee-40a1-8d67-684865cb047c', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the difference between a database schema and a database instance?', N'Fresher', N'A schema is the overall blueprint or logical structure of the database that defines how data is organized. An instance is a snapshot of the database at a specific moment in time, representing the actual data stored in the schema.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'037e2a16-d9ce-46fd-8588-68496e923d2a', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does the Fiber framework differ from the standard net/http library in terms of architectural philosophy?', N'Senior', N'Fiber is built on top of Fasthttp, which is designed to minimize memory allocations and garbage collection overhead by reusing request and response objects. In contrast, the standard library follows a more traditional, allocation-heavy approach that prioritizes idiomatic Go patterns and strict adherence to the HTTP specification over raw performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f5f0c00-a280-4cd4-a101-684a5f670b9f', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle performance when rendering large lists?', N'Middle', N'Lit provides the ''repeat'' directive, which uses a tracking key to identify list items. This allows the framework to reorder or patch the DOM instead of re-rendering the entire list when an item is added, removed, or moved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbad43dd-9f59-4183-a797-684c35ef3baf', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How would you handle asynchronous tasks in a Flask application?', N'Middle', N'Since Flask is synchronous, long-running tasks should be offloaded to a background task queue like Celery. This prevents the request-response cycle from blocking, allowing the server to return a response to the client immediately while the task processes independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cb98485-21de-4995-abe1-684c61d5096d', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does Raft or Paxos consensus affect the performance of distributed transaction commits?', N'Senior', N'Consensus algorithms ensure that a majority of nodes agree on the transaction log order, providing strong durability and consistency. However, they introduce latency because every write must wait for a network round-trip to achieve a quorum before the transaction can be acknowledged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b8f5790-5002-4fc6-a8f9-684e3f9afd83', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala''s ''Variance'' (covariance/contravariance) maintain type safety in generic collections?', N'Senior', N'Variance annotations define how subtyping relationships of complex types relate to their component types, preventing dangerous runtime type errors. Covariance allows for safe ''read-only'' access to sub-types, while contravariance is essential for defining safe ''write-only'' consumers, ensuring that the compiler catches invalid assignments at compile-time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55fae801-0b44-44c0-a8c9-685121ba269c', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is Hono in the context of web development?', N'Intern', N'Hono is a lightweight, high-performance web framework designed for edge computing environments. It is built to be platform-agnostic, meaning it can run on various runtimes like Cloudflare Workers, Deno, Bun, and Node.js.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32342033-a16e-4525-b516-6851fdb41d7b', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Why would you implement a custom ParamConverter, and what architectural problem does it solve?', N'Senior', N'A custom ParamConverter allows for the automatic transformation of request attributes into complex objects before the controller is executed. It solves the architectural problem of controller bloat by moving data retrieval and validation logic out of the controller and into a reusable, decoupled service layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc9ea8d2-1010-414a-9047-68588830d7a1', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript handle ''this'' context within classes and arrow functions?', N'Senior', N'In classes, ''this'' refers to the instance, but it can be lost when passing methods as callbacks. TypeScript allows you to annotate the ''this'' type in a function signature to catch context-related bugs at compile time, whereas arrow functions lexically bind ''this'' to the surrounding scope, avoiding the need for manual binding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a05c80cf-8962-42f9-adb9-685a4d9c98d2', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Explain the difference between at-most-once and exactly-once delivery guarantees.', N'Middle', N'At-most-once ensures messages are delivered zero or one time, prioritizing speed over reliability. Exactly-once is a more complex guarantee achieved through coordination between the broker and consumer to ensure that even in the face of failures, the effect of processing a message occurs only once.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7192a99b-f9a6-4407-bbbb-685ce07910ab', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the difference between a DOM element and a jQuery object?', N'Intern', N'A DOM element is a native browser object representing a node in the document, while a jQuery object is a custom structure that wraps DOM elements to provide extra functionality. You cannot call jQuery methods directly on a native DOM element without wrapping it first.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac0abca1-161f-4cd6-8ea1-685d32147d1d', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the purpose of the ''will-change'' property and why should it be used sparingly?', N'Middle', N'The ''will-change'' property informs the browser that an element is likely to change, allowing it to perform optimizations like promoting the element to its own compositor layer. It should be used sparingly because creating too many compositor layers consumes excessive memory and can lead to performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
