INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7da0933-3e47-4538-80a3-685f60a77249', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between ''null'' and ''undefined'' in TypeScript?', N'Intern', N'In TypeScript, ''undefined'' means a variable has been declared but has not yet been assigned a value. ''Null'' is an intentional absence of any object value, and they are distinct types in strict mode.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
