INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16a51fb6-291a-4270-8963-685fd1126fa8', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How do you achieve multi-tenancy in a Spring Boot application?', N'Senior', N'You can implement multi-tenancy by using a custom AbstractRoutingDataSource that determines the target database connection based on a tenant identifier. This identifier is typically extracted from an HTTP header or a security context attribute at the start of each request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f395e430-aad9-478f-b525-686013140af6', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between shallow and deep copying?', N'Middle', N'A shallow copy creates a new object and copies the non-static fields of the original, but if a field is a reference type, only the reference is copied. A deep copy creates a new object and recursively copies all objects referred to by the original, ensuring the new object is entirely independent of the original.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e8029a1-061c-49f4-bce8-686045cecfbb', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between public, private, and protected access specifiers?', N'Intern', N'Public members are accessible from anywhere outside the class. Private members are only accessible within the class itself, providing data hiding. Protected members are accessible within the class and by classes derived from it, allowing for controlled access during inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc3925cc-073b-4c0e-be89-68612938391d', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between ''count'', ''size'', and ''length'' in Active Record?', N'Junior', N'''count'' performs a SQL query to count records in the database. ''length'' loads all records into memory and counts the Ruby array elements. ''size'' is smart enough to choose between the two based on whether the data is already loaded in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
