INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a690f4d1-3464-4495-b9b6-6871c948d9aa', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Describe the impact of ''scatter-gather'' queries in a sharded environment.', N'Senior', N'A scatter-gather query is one that does not include the shard key in the filter, forcing the mongos router to broadcast the query to every shard in the cluster. This is highly inefficient and creates significant latency, as the router must wait for all shards to respond and then merge the results.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
