INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc0bfba1-7a1b-408f-b335-687a5322593f', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the difference between a GET and a POST request in FastAPI?', N'Intern', N'GET requests are typically used to retrieve data from a server, while POST requests are used to send new data to the server to be created or processed. In FastAPI, these are defined using decorators that correspond to standard HTTP methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
