INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d854f6e-d3a9-4f7e-9d6b-68839e2068dc', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between an object and a class?', N'Intern', N'A class is a blueprint or template that defines the structure and behavior of objects, while an object is an actual instance of that class. You define the class once, and you can create many objects from it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0499ffd-cf61-47ed-9296-6883e31730ad', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why is ''Idempotency'' critical when dealing with message-driven database updates?', N'Senior', N'Idempotency ensures that applying the same operation multiple times results in the same state, which is vital when network retries can cause duplicate message delivery. Without it, duplicate processing can lead to data corruption or incorrect business state in distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c500298-1e4c-4bf5-af1c-688c912becb9', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is memoization and how do you implement it correctly for production use?', N'Senior', N'Memoization is a caching technique that stores the return value of a pure function keyed by its arguments. On subsequent calls with the same arguments, the cached result is returned without re-executing the function. It is the programmatic application of the mathematical concept that pure functions are referentially transparent (same input → same output). Production concerns beyond the naïve implementation: 1. Cache key strategy — JSON.stringify fails for non-serialisable args (functions, circular refs, Symbols, undefined). A WeakMap keyed on object identity avoids this. 2. Cache eviction — unbounded caches grow without limit. LRU (Least Recently Used) eviction is standard. 3. Async memoization — memoize the Promise itself, not the resolved value, to prevent duplicate in-flight requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a88ea798-0d97-4729-bfa0-688ed45a500c', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How do you handle dependency injection in a Chi application?', N'Middle', N'Dependency injection is typically managed at the application setup level, where handlers are initialized with necessary services as struct fields. These handlers are then assigned to routes, allowing the router to remain agnostic of the underlying application logic and dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e2e608a-4435-4772-b88a-68911be4de87', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R handle missing values during mathematical calculations?', N'Junior', N'By default, R returns NA if any input in a mathematical operation is NA. To bypass this and perform calculations on the remaining values, one must typically use specific arguments like na.rm = TRUE.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
