INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fe4b3f3-dca0-4923-88f1-68b0e809af1c', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is Flask & its benefits?', N'Intern', N'Python Flask, as we''ve previously discussed, is a web microframework for Python. It is based on the ''Werkzeug, Jinja 2 and good intentions'' BSD license. Two of its dependencies are Werkzeug and Jinja2. This means that it has around no dependencies on external libraries. Due to this, we can call it a light framework. A session uses a signed cookie to allow the user to look at and modify session contents. It will remember information from one request to another. However, to modify a session, the user must have the secret key Flask.secret_key. Flask is a web micro framework for Python based on "Werkzeug, Jinja 2 and good intentions" BSD licensed. Werkzeug and jingja are two of its dependencies. Flask is part of the micro-framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62082117-8890-4c40-83a6-68b346c78600', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js handle internationalization (i18n), and what are the performance implications of different routing strategies?', N'Senior', N'Next.js supports i18n through sub-path or domain-based routing. Sub-path routing is generally easier to cache at the CDN level, whereas domain-based routing requires more complex DNS and SSL management but provides better SEO isolation for regional markets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
