INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd772bd0a-c580-4404-aee1-68b7b8f666c0', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Is Echo synchronous or asynchronous?', N'Intern', N'Echo is built on top of Go''s standard net/http library, which handles each incoming request in its own goroutine. This makes it highly concurrent and capable of handling multiple requests simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d21fe07-ecb2-4e51-a0ce-68b811c47d67', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the relationship between browser layer creation and CSS property choice?', N'Senior', N'Browsers create compositor layers for elements that have specific properties like 3D transforms, opacity, or filters. Managing these layers is a balancing act; too few layers can lead to excessive repaints, while too many layers consume significant GPU memory and can lead to performance regressions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21267c86-9e58-4e49-a4d0-68b8cbe2f672', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the ''observer effect'' in monitoring?', N'Middle', N'The observer effect occurs when the act of monitoring a system consumes enough resources to alter the system''s performance. It highlights the need to keep monitoring overhead low to avoid skewing the very metrics being measured.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ccb3ed3-0c56-4005-923a-68b99c9efd61', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are the limitations of PHP''s error handling mechanism in distributed systems?', N'Senior', N'PHP''s error handling is request-scoped, meaning errors do not automatically propagate across distributed service boundaries. Effective error management in a microservices architecture requires structured logging and distributed tracing, as native PHP exceptions remain local to the runtime execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2329cd1f-0bdb-4f0c-9d4a-68bba30e58a3', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you determine if a performance issue is a result of code inefficiency or infrastructure constraints?', N'Middle', N'I use profiling tools and monitoring metrics to correlate resource usage with specific execution paths. If CPU or memory spikes align with specific functions, it is likely a code issue; if performance is degraded across the board despite low usage, it suggests an infrastructure bottleneck like network latency or database locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'090f1ed7-ed3d-473c-8554-68bbc673b583', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the convention over configuration principle?', N'Intern', N'Convention over Configuration is a foundational principle in Ruby on Rails that streamlines development through pre-defined rules, reducing the need for explicit configurations. This design philosophy centers around the concept of defaults and predictable naming conventions, effectively cutting down on repetitive code and providing a more unified structure to Rails projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfa35af3-f0c3-44a5-a0d5-68bc8875e608', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why is the mapping explosion problem a significant risk in large-scale Elasticsearch clusters?', N'Senior', N'Mapping explosion occurs when too many unique field names are created, causing the cluster state to become bloated and slow to update. This leads to increased memory pressure on the master node and can eventually crash the entire cluster due to the overhead of managing the global mapping metadata.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39d5530e-d06d-4ff5-812a-68bd450c46ad', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between a push or pull model for a data synchronization task?', N'Middle', N'The push model is ideal for real-time updates where low latency is required, but it can overwhelm consumers if not properly rate-limited. The pull model allows consumers to control the consumption rate based on their current load, which is more robust for batch processing or heavy data synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ff92b9a-6ae6-4a91-b180-68bfd97cbf65', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is Litestar and how does it differ from other Python web frameworks?', N'Fresher', N'Litestar is a modern, high-performance asynchronous web framework for Python built on top of Starlette and Pydantic. It differentiates itself by offering a strong emphasis on type safety, dependency injection, and a more structured, object-oriented approach to building APIs compared to frameworks like Flask or FastAPI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6beed417-78bc-461b-ae44-68c0038b801b', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How can ''Transaction Timeouts'' improve system stability?', N'Middle', N'Transaction timeouts prevent long-running or stalled transactions from holding locks indefinitely, which could otherwise lead to system-wide resource exhaustion. By automatically aborting stuck transactions, the database can free resources and maintain overall system responsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e92628e1-baef-4df8-8e0c-68c46d5f83d1', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the fundamental architectural difference between Qwik''s resumability and traditional hydration?', N'Senior', N'Traditional hydration requires downloading, parsing, and executing the entire component tree to attach event listeners, which is O(n) relative to app size. Qwik''s resumability serializes the application state and event metadata into the HTML itself, allowing the application to become interactive instantly without executing initial JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37570394-e3b8-4295-9fdf-68c73b7d5fa2', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the difference between ''web::resource'' and ''web::route''?', N'Junior', N'A resource is a higher-level abstraction that can map multiple HTTP methods to different handlers for the same URL path. A route is typically a more direct way to bind a specific HTTP method to a specific handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3294c6ff-e8fa-483f-8d93-68c875df0edc', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the JVM ensure that volatile variables are visible across different CPU cores?', N'Senior', N'The volatile keyword forces the compiler and hardware to insert memory barriers (fences) that prevent instruction reordering and ensure that the value is flushed to main memory. This guarantees that any thread reading the variable will see the most recent write, maintaining cross-core visibility at the cost of some performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e79c0d7-3311-44dc-9ad7-68ca125be658', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the benefit of ''Partial Functions'' over standard functions regarding domain modeling?', N'Senior', N'Partial functions provide a way to define operations that are only valid for a specific subset of the input domain, explicitly handling cases where the input is undefined. This allows for more expressive domain modeling and safer code through combinators like ''isDefinedAt'' and ''orElse''. It forces the developer to consider the total domain of the function, reducing runtime errors associated with unexpected inputs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afe3691f-0a15-4786-84bd-68ca85c90e83', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide whether to store state in a database or in a distributed cache?', N'Middle', N'I store state in a database when it requires long-term persistence, high integrity, and complex querying capabilities. I use a distributed cache only for transient, high-read data where performance is more critical than guaranteed persistence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
