INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'daa63202-81a5-4f29-b4ad-68d15708e2b0', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does the ''tombstone'' mechanism affect read performance in Cassandra?', N'Senior', N'Tombstones are markers used to represent deleted data in immutable SSTables. During reads, the engine must scan over these tombstones to determine which data is visible, which can lead to increased CPU and memory overhead if the number of tombstones is excessive, eventually triggering read timeouts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
