INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d47d1be-1817-47ec-8928-68d6a4906320', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus manage thread pools for blocking versus non-blocking operations?', N'Senior', N'Quarkus separates the execution of blocking tasks, which run in a worker thread pool, from non-blocking reactive operations that run on the Vert.x event loop. This prevents event loop starvation, ensuring that long-running database or I/O operations do not block the application''s ability to accept new requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afc69889-b47b-4ff3-8f69-68dadda432bd', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between ''static_cast'' and ''dynamic_cast''?', N'Middle', N'Static_cast is performed at compile-time and is used for standard type conversions, while dynamic_cast is performed at runtime and is used for safe downcasting in an inheritance hierarchy. Dynamic_cast requires the base class to have at least one virtual function and returns null or throws an exception if the cast is invalid.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
