INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f22d9550-498d-45fb-9452-68df69e7cc54', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'When would you prefer a partial index over a standard index?', N'Middle', N'A partial index only includes documents that meet a specified filter expression, which reduces index size and performance overhead. It is ideal for queries that only target a subset of documents, such as indexing only active users in a collection that contains both active and inactive records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a124033-d737-44c6-a946-68e0fde0e50c', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What role does the ''Stream'' trait play in Actix-web''s handling of request bodies?', N'Senior', N'The Stream trait allows Actix-web to process request bodies as a series of asynchronous chunks rather than loading the entire payload into memory. This is critical for handling large file uploads or streaming data without incurring massive memory overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'752218d0-3228-4149-ad47-68e14ff8c84e', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What are the trade-offs of using Fastify''s encapsulation model in a large-scale microservice?', N'Senior', N'Encapsulation allows for strict plugin scoping, preventing pollution of the global namespace and facilitating better isolation of configuration and routes. However, it can make it more difficult to share global state or common utilities across the entire application tree without explicit decoration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d60c95a-1602-469b-ab7e-68e2e5b3aa95', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does the Cassandra write path differ from a traditional RDBMS?', N'Middle', N'Cassandra uses an append-only commit log and an in-memory structure called a Memtable. Unlike RDBMS, it does not perform random disk I/O for updates, which allows for extremely high write throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2651bf63-199a-422a-a038-68e5fb504e92', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the concept of a route module in Remix?', N'Intern', N'A route module is a file that exports the component to be rendered for a specific URL, along with the data-loading and data-mutation functions for that route. This keeps everything related to a specific part of the interface organized in one place.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17e0210f-2efa-4201-a6e9-68e67e486db8', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the limitations of Redis Cluster regarding multi-key operations?', N'Middle', N'In Redis Cluster, multi-key operations are only supported if all keys involved hash to the same slot. If keys are located on different nodes, cross-slot operations will fail, requiring the application to either manage key placement or perform those operations at the application layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'549d21df-e801-4b64-a912-68e898a2d80a', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you estimate how many people are browsing the internet in your country at this moment?', N'Fresher', N'I would start with the total population, filter by the percentage of people with internet access, and then estimate the average percentage of those users who are active online during the current time of day. This gives a reasonable order-of-magnitude estimate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b8c00b6-3655-4261-9e2d-68e9c61402f9', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the ''Quarkus Platform'' BOM?', N'Junior', N'The Bill of Materials (BOM) is a central file that manages the versions of all Quarkus extensions and dependencies. It ensures that all libraries used in your project are compatible with each other, preventing dependency version conflicts during the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de7054e7-f7da-4b8e-9bf8-68ebe58924ad', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does a database prevent two transactions from modifying the same data simultaneously?', N'Intern', N'Databases typically use locking mechanisms to manage concurrent access. When one transaction locks a record, other transactions must wait until the lock is released, preventing conflicts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b60337ba-c73b-4e26-a632-68ec54cd37df', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What are Alpine.js modifiers and why are they used?', N'Junior', N'Modifiers are suffixes added to directives, such as .prevent or .once, that alter the behavior of an event listener. For example, .prevent calls the default event preventDefault, which is a common pattern for handling form submissions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8230b64-9517-4433-bddb-68ed94260563', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How do you secure a Spring Boot application?', N'Middle', N'Spring Security is the standard framework used to protect applications by providing authentication and authorization mechanisms. It integrates with existing identity providers and allows developers to define access control rules for specific URL paths or individual methods using annotations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
