INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7939ff8c-f2d8-4473-a684-68efbd5ff61f', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Why might you choose to use Reference Classes (RC) over S4?', N'Middle', N'Reference Classes provide encapsulated state and mutable methods, behaving similarly to object-oriented patterns in languages like Java or Python. They are preferred when you need to maintain internal state that is modified over time, avoiding the constant copying associated with standard R objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f339963-689e-4bd3-940c-68efeb164f68', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is GraalVM?', N'Intern', N'GraalVM is a high-performance JDK that supports ahead-of-time compilation. It allows Quarkus applications to be compiled into a standalone native executable, which provides near-instant startup and extremely low memory usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ed00ca6-e2fb-47c6-8bc0-68f3c2384ee5', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the benefit of using Qwik over a framework that relies on hydration?', N'Junior', N'The primary benefit is a significantly smaller Time to Interactive (TTI) metric. Because there is no hydration phase, the browser does not need to spend time executing heavy JavaScript on startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36dc8a5f-5790-47a5-a55a-68f8199fb30c', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When faced with a race condition that only reproduces under heavy load, how do you debug it?', N'Middle', N'Since race conditions are hard to reproduce, I focus on analyzing thread dumps taken during high-load periods to identify contention or deadlock scenarios. I also review the synchronization mechanisms in the affected code, such as locks or atomic variables, to ensure thread safety. Simulation through stress testing in a staging environment that mirrors production traffic volume is often necessary to isolate the timing issue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab89eb79-1e96-4fd1-ae2e-68f8df97cf03', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the configuration server in a sharded cluster?', N'Junior', N'Configuration servers store the metadata and configuration settings for the entire sharded cluster. They maintain the mapping between data ranges and the specific shards where that data is stored.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69967cc6-e9ea-4a84-82ab-68fbe19c20cb', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why is it discouraged to have very large shards in an Elasticsearch cluster?', N'Middle', N'Large shards make cluster recovery significantly slower because moving a single large shard across the network takes more time during node failure or rebalancing. Smaller, more numerous shards are generally preferred for better management and faster recovery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
