INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4674bc8-6505-4003-ba46-68fcd01df9b4', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'In what scenarios would you choose Remix over a pure static site generation approach?', N'Senior', N'Remix is superior for applications with highly dynamic, user-specific data that cannot be predicted at build time. It avoids the ''build time explosion'' associated with large-scale static sites while maintaining excellent SEO and performance through server-side rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd8930b2-2afa-46fa-839d-68fdb8ecb567', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the attributes provided by a property descriptor', N'Intern', N'A property descriptor is a record which has the following attributes 1. value: The value associated with the property 2. writable: Determines whether the value associated with the property can be changed or not 3. configurable: Returns true if the type of this property descriptor can be changed and if the property can be deleted from the corresponding object. 4. enumerable: Determines whether the property appears during enumeration of the properties on the corresponding object or not. 5. set: A function which serves as a setter for the property 6. get: A function which serves as a getter for the property', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54198a47-876d-43fe-8991-68fdd9d3bcac', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you decide between vertical and horizontal scaling for a specific component?', N'Senior', N'I choose vertical scaling when the application is inherently stateful or when the cost of refactoring for distributed operation outweighs the benefits. I prefer horizontal scaling for most modern systems, as it provides better fault tolerance, higher availability, and the ability to scale incrementally based on demand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3db3a324-b9ea-4ae2-bf28-68fe11cbc126', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are the trade-offs of using Flask-SQLAlchemy versus a raw driver for database interactions?', N'Senior', N'Flask-SQLAlchemy provides an ORM that simplifies complex queries and model management, significantly increasing developer productivity. However, it can introduce performance overhead for simple operations, making raw drivers more suitable for extreme low-latency requirements or scenarios where highly optimized, database-specific SQL is necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
