INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ee0379f-13a9-42ad-8f79-6907a1a7dbcb', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is a jQuery object?', N'Intern', N'A jQuery object is a wrapper around one or more DOM elements. It provides methods that allow you to perform actions on all selected elements at once without needing to manually loop through them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d82b85d-f50e-4127-9de7-690aaa049b42', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Explain the trade-offs of using a composite primary key.', N'Middle', N'A composite primary key uses multiple columns to uniquely identify a row, which is useful for modeling many-to-many relationships or natural keys. However, it can complicate indexing and foreign key constraints, often making it less efficient than using a single surrogate primary key like a UUID or auto-incrementing integer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'622e0e94-c5cb-4938-8ed0-690bdaab3808', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the fundamental difference between Tailwind CSS and traditional CSS-in-JS libraries like Styled Components?', N'Middle', N'Tailwind is a utility-first framework that relies on pre-defined CSS classes applied directly to HTML elements, whereas CSS-in-JS libraries generate unique class names dynamically at runtime based on component state. Tailwind promotes reusability through composition of existing classes, while CSS-in-JS focuses on encapsulating styles within the component logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79cc7216-c997-41cd-974e-690c06f01033', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the principle of least knowledge (Law of Demeter) in architecture?', N'Senior', N'The principle of least knowledge (LoD), also known as the law of Demeter, emphasizes reducing the dependencies between modules and classes to make systems more modular, easier to maintain, and less prone to errors. Core Tenets The Law of Demeter distills the following key principles: - Locality of Knowledge: Each module has detailed knowledge about its immediate collaborators. - Black Box Design: A module''s internal state is considered its private information, and interactions are based on public interfaces. Verbal Expressions The Law of Demeter has been formulated using several verbal expressions, offering different perspectives on its core tenets: "Don''t talk to strangers" This phrase is an analogue for the principle that objects or methods should have limited access to other entities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79fc061a-2920-48fd-8d82-690f97f22d70', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the role of a write-ahead log (WAL) in database reliability?', N'Middle', N'A WAL records all changes to the database before they are applied to the actual data files. This allows the database to recover to a consistent state after a crash by replaying the logs, ensuring durability without needing to flush data to disk after every single operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96b711e4-4f7f-4733-aa23-69124b772991', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What happens if a component is rendered only on the client in a Nuxt application?', N'Middle', N'If a component is wrapped in '' '', it will not be rendered on the server, leaving an empty placeholder in the initial HTML. This is useful for components that rely on browser-only features, preventing hydration errors during the server rendering phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'922611b2-8ee9-419c-b36f-69148769d1f7', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why is near real-time (NRT) search an important feature?', N'Junior', N'NRT means there is a slight delay, usually one second, between when a document is indexed and when it becomes available for search. This balance allows Elasticsearch to maintain high performance while ensuring that data is searchable almost immediately after it is written.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18840f05-4cce-49a1-937e-6914a2c7242c', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How can Echo be integrated with an external distributed tracing system like Jaeger or OpenTelemetry, and where should this be injected?', N'Senior', N'Tracing should be integrated via a custom middleware injected at the very beginning of the Echo middleware chain. This ensures that the trace context is captured for the entire request lifecycle, allowing for accurate span propagation across service boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7467aeab-21ca-4a45-81a5-691585c43292', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the significance of the ''Astro.props'' object?', N'Middle', N'Astro.props is the mechanism for passing data from parent components to child components. It provides a clean way to define component interfaces, ensuring that the static site generation process receives the correct data during the build.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a760fd9b-63d8-42c0-b050-691a340e6022', N'4c000000-0000-0000-0000-000000000005', N'What is the benefit of using a service mesh?', N'Middle', N'A service mesh handles service-to-service communication, load balancing, and observability through a sidecar proxy. It offloads these responsibilities from the application code, allowing developers to focus on business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13f063ec-93e6-40dd-89c1-691ae3a22ee7', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the ''N+1'' problem and how does it relate to database queries?', N'Middle', N'The N+1 problem occurs when an application executes one query to fetch a parent record and then executes N additional queries to fetch related child records. It significantly degrades performance due to excessive network round-trips and can be mitigated by using JOINs or eager loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b40fc9b-eef8-47d1-bbd2-691c0fcd2b83', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why might a system choose BASE over ACID?', N'Intern', N'A system might choose BASE to achieve higher performance, horizontal scalability, and availability in distributed environments. Strict ACID compliance often requires complex locking that can become a bottleneck in large-scale systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db40a3cb-3eff-4afa-b04c-691e242cef5a', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue''s reactivity system avoid infinite loops in watchers?', N'Senior', N'Vue tracks dependencies during the execution of a watcher''s callback, but it also employs a scheduling mechanism that prevents a watcher from triggering itself if it modifies the same state it is currently observing. This ensures that the system resolves to a stable state without entering into recursive re-evaluation cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43ec0ce5-e628-4303-b95a-691e57fd28d2', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the ''next/script'' component?', N'Fresher', N'The script component is used to manage the loading of third-party scripts, such as analytics or advertising tags. It allows you to define a loading strategy, such as loading the script in the background or after the page becomes interactive, to improve site performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd14e5371-52da-4210-9a60-69247a30a5e3', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do you render a list of items in Svelte?', N'Fresher', N'List rendering is performed using the #each block. You provide an array or iterable to the block, and Svelte will repeat the inner HTML structure for every item within that collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cf8047c-666b-4ed0-8b6f-69253ad563e4', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason about the impact of a breaking API change on downstream consumers?', N'Middle', N'I evaluate the versioning strategy to ensure that consumers can migrate at their own pace. If a breaking change is unavoidable, I plan for a transition period where both versions are supported, accompanied by clear communication and migration guides to minimize disruption for the consumer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ce5d2ed-22bd-4eea-b431-6926762c7e15', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is difference between String, StringBuffer and StringBuilder?', N'Fresher', N'1. Mutability Difference: String is immutable, if you try to alter their values, another object gets created, whereas StringBuffer and StringBuilder are mutable so they can change their values. 2. Thread-Safety Difference: The difference between StringBuffer and StringBuilder is that StringBuffer is thread-safe. So when the application needs to be run only in a single thread then it is better to use StringBuilder. StringBuilder is more efficient than StringBuffer. Example: Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f519aec-fe8f-44d8-959d-692ac1cb001e', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the purpose of the ''interface'' keyword?', N'Intern', N'An interface is a construct used to define a contract for classes. It can contain both abstract methods and methods with implementations, allowing for a form of multiple inheritance of behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'563ca4a2-13c9-434f-9dca-692cbb69bf06', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the benefit of using custom elements?', N'Intern', N'Custom elements allow you to extend HTML by creating your own tags. This makes your code more modular, readable, and reusable across different projects and frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98efdb81-7314-4c53-a0db-6935766b8d20', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of the ''mutating'' keyword in Swift protocols and structs?', N'Middle', N'Since structs are value types, methods are not allowed to modify their properties by default. The mutating keyword explicitly marks a method as one that changes the instance''s state. It is required because the compiler must generate a new instance under the hood when a mutation occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acea2c4e-988c-4206-a0cd-6938d89f2ec1', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of Django Forms?', N'Junior', N'Django Forms handle data validation, HTML form rendering, and conversion of input data into Python types. They provide built-in protection against common security risks like CSRF attacks and ensure that user-submitted data conforms to specified constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a452f095-5083-4b5d-88b7-693ab3a8b530', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of ''onMount'' versus an effect that runs on the first render?', N'Senior', N'onMount is explicitly designed for code that should run only once after the component is rendered to the DOM, typically for initialization tasks. While an effect can achieve this if handled correctly, onMount provides a cleaner, semantically explicit lifecycle hook for DOM-dependent operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f04d38f3-81d1-4028-abce-693e0130cea1', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is memoized selection, and why is it important in Redux?', N'Middle', N'Memoized selectors, often implemented with libraries like Reselect, cache the results of expensive computations based on input arguments. This prevents unnecessary re-calculations and re-renders when the relevant state slice hasn''t changed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd83a981b-3ccd-4e25-ae96-693e228c81a2', N'a2838158-7305-480a-b22b-4dc35776b400', N'Describe the impact of the ''split-brain'' scenario on a distributed system and how to mitigate it.', N'Senior', N'Split-brain occurs when a network partition causes a cluster to divide into two or more independent groups, each believing it holds the primary authority. This can lead to data corruption if multiple nodes perform conflicting writes. Mitigation usually involves quorum-based voting mechanisms, such as Paxos or Raft, which require a majority to commit, ensuring only one partition can proceed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'951baa93-15e8-45fc-9bb3-693eec30c87b', N'954a0331-deff-4399-b588-96f39fec001d', N'How does the ''TrackBy'' function in an ngFor loop optimize DOM manipulation?', N'Senior', N'Without TrackBy, Angular re-renders the entire list if the array reference changes, which is computationally expensive. TrackBy allows Angular to identify items by a unique identifier, meaning it only updates the DOM nodes that actually changed, significantly improving performance for large lists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4342dde1-0ece-4a57-897c-693fff87f152', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does Atomicity mean in a transaction?', N'Fresher', N'Atomicity ensures that all operations within a transaction are completed successfully. If any part of the transaction fails, the entire transaction is aborted, and the database is returned to its previous state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db58eda3-a932-4fc8-a07c-69419edf7bcc', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What does the term NoSQL stand for?', N'Intern', N'NoSQL stands for ''Not Only SQL''. It refers to a broad category of database management systems that do not rely on the traditional relational model used by SQL databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9e3b726-30c6-4b30-8678-6947dc6e4ced', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind handle specificity conflicts, and why is this design choice advantageous for large-scale applications?', N'Senior', N'Tailwind uses a single-class utility system, meaning that specificity is largely flat and predictable. By avoiding nested selectors and deep specificity chains, it eliminates the ''CSS specificity wars'' that often plague large-scale, long-lived stylesheets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
