INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'151f89e0-2efc-455f-b6a5-695e0df7ccec', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Why would you choose Flask over a framework like Django for a microservices architecture?', N'Middle', N'Flask is a ''micro'' framework that provides only the essentials, allowing you to choose your own libraries for database, authentication, and validation. This flexibility and lightweight footprint make it ideal for microservices where you want minimal overhead and specific component choices for each service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
