INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ca7f49c-2108-4830-9050-6979f9eb36ee', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are the architectural implications of C''s strict aliasing rule?', N'Senior', N'Strict aliasing dictates that pointers of incompatible types cannot point to the same memory location, allowing compilers to perform type-based alias analysis. This enables optimizations such as keeping values in registers longer, as the compiler can safely assume that a write to one type does not modify the memory of another. Violating this rule can lead to unpredictable behavior when the compiler generates machine code that assumes no memory overlap exists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
