INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b69ab8a-3014-4f37-bc5d-697ca8baf651', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the concept of ''Reverse Relations'' in Django ORM.', N'Middle', N'Reverse relations allow you to access the ''many'' side of a relationship from the ''one'' side, even if a relationship field is only defined on the ''many'' side. Django automatically creates these managers, usually named with the lowercase model name followed by ''_set'', allowing you to query related objects in the opposite direction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd889751-37a2-4355-ba9e-697ccd3247ab', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the differences between InnoDB and MyISAM storage engines?', N'Fresher', N'InnoDB is the default engine that supports transactions, row-level locking, and foreign key constraints, making it ideal for data integrity. MyISAM is an older engine that supports table-level locking and does not support transactions or foreign keys, but it is sometimes faster for read-heavy operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
