INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecc8c519-698d-485e-b237-697f1d9c0a35', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What are the primary trade-offs between REST and GraphQL for a public-facing API?', N'Middle', N'REST is highly cacheable and follows standard HTTP semantics, making it predictable and easy to integrate with existing infrastructure. GraphQL provides flexibility by allowing clients to request exactly the data they need, reducing over-fetching, but it complicates caching and makes rate-limiting more difficult to implement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfa2db50-9a8c-4353-aec5-697f443b2350', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the benefit of the ''Optional'' container over returning null?', N'Middle', N'Optional provides a type-safe way to represent the presence or absence of a value, forcing developers to explicitly handle the empty case. This reduces the frequency of NullPointerExceptions and makes APIs more expressive by documenting that a method might not return a result. It encourages a more functional and cleaner style of error handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
