INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aee2fe1d-60b8-48d2-8c4a-6983e0c6b37b', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the primary-replica shard model in Elasticsearch maintain consistency during concurrent writes?', N'Senior', N'Elasticsearch uses an optimistic concurrency control mechanism based on sequence numbers and primary terms. Every write operation is assigned a sequence number, and the primary shard sequences these operations before replicating them to replica shards, ensuring that all copies reach the same state regardless of network latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a07bf030-208c-4742-bd7c-69845a2ad033', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Why is the String class in Java considered immutable?', N'Junior', N'String objects are immutable because their internal character array cannot be modified after creation. This design choice enhances security, allows for String pooling in memory, and makes Strings inherently thread-safe since they cannot be changed by multiple threads simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6a39858-8d93-4b76-9b1a-6984b51b56e2', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle memory leaks in the context of persistent middleware or closures?', N'Senior', N'Express does not inherently manage memory leaks caused by developer error, such as storing data in global state or closures within middleware. Senior developers must ensure that state is scoped correctly to the request object and avoid long-lived references that prevent garbage collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c2ffcf0-168c-469b-b98d-6986b881b202', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the role of the ''new'' and ''delete'' operators?', N'Fresher', N'The new operator is used to dynamically allocate memory for an object or array on the heap and returns its address. The delete operator is used to deallocate that memory when it is no longer needed to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2a82107-cac2-43a2-afa5-6987c33e224a', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are Request Headers in Hono?', N'Intern', N'Request headers are key-value pairs that contain metadata about the HTTP request, such as the content type or authentication tokens. Hono allows easy access to these headers via the context object to help inform how the server should process the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65e8169a-9195-4b48-9504-6987d37fe021', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the significance of ''Sized'' and ''Unsized'' types in Rust''s type system?', N'Senior', N'The Sized trait indicates that a type has a known size at compile-time, which is required for stack allocation and function passing. Unsized types, like slices or trait objects, require indirection through pointers because their size is only known at runtime, making them ''dynamically sized types'' that are handled differently by the borrow checker.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82dfebde-20c0-40fc-950e-698824bed48f', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Describe the trade-offs of using Capped Collections in MongoDB.', N'Senior', N'Capped collections provide high-performance insertion and automatic deletion of old documents by maintaining a fixed size. The trade-off is that they do not support document deletion or growth, and they are inherently limited in size, making them unsuitable for data that must be kept indefinitely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9647c95a-3738-462c-bac1-698ae41cecfa', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Describe the security implications of moving data-fetching logic to the server in Remix.', N'Senior', N'Moving data fetching to the server is inherently more secure because sensitive API keys, database credentials, and internal business logic are never exposed to the client bundle. This reduces the surface area for attacks and prevents leaking information that is not strictly necessary for the UI to function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a98ffb0a-1dc0-4c0b-80e6-698bf6681fae', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What design pattern is reflected in Echo''s approach to middleware execution?', N'Senior', N'Echo follows the Chain of Responsibility pattern, where each middleware has the power to either execute the next handler or terminate the chain early. This allows for powerful request-intercepting capabilities like authentication, logging, and response modification to be applied modularly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00503a05-754c-44a8-b51f-698e4f22ba95', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Discuss the ''Double Invocation'' of components in Strict Mode and its purpose in development.', N'Senior', N'React calls components twice in Strict Mode to detect impure side effects that could cause issues in concurrent rendering. It helps developers identify non-deterministic logic that would otherwise be difficult to debug in production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'915274ce-4f66-447e-a9ef-698f3d8de5ee', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why would you choose a strongly typed language over a dynamically typed one in a large project?', N'Fresher', N'Strongly typed languages help catch errors during compilation, which improves long-term reliability and code readability in large teams. Dynamically typed languages offer faster prototyping but can lead to harder-to-track bugs as the project scales.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'200aa7f8-3320-4f3e-80ec-698f458d1cff', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the role of the Actix ''App'' object?', N'Intern', N'The App object is the entry point for an Actix web application. It is used to register routes, middleware, and shared state that the application will use to handle incoming HTTP requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3f5e182-d3f1-4078-a2e2-698fc1e23575', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket maintain type safety when dealing with dynamic request parameters?', N'Senior', N'Rocket uses the ''FromParam'' and ''FromSegments'' traits to safely deserialize string segments from a URL into strongly typed Rust types. If the conversion fails, Rocket automatically returns a 404 response, ensuring that handlers never receive malformed or unexpected data types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35db7f22-b722-4ce0-a91e-699019246612', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the purpose of ''Event Sourcing'' in microservices?', N'Middle', N'Event Sourcing stores the state of a system as a sequence of state-changing events rather than just the final current state. This provides a complete audit log, allows for easier debugging, and enables the reconstruction of past states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6e4a262-ce09-456f-8195-699250aebb91', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the performance implications of having a very large item size in DynamoDB?', N'Senior', N'DynamoDB has a 400KB limit per item, and larger items consume more read and write capacity units. Fetching large items increases latency and can lead to inefficient bandwidth usage, making it better to offload large binary data to S3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4d46bb5-1979-4056-917f-6993d00198ae', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Why is Netty important for Micronaut?', N'Junior', N'Netty is the underlying non-blocking, event-driven HTTP server engine used by Micronaut. It enables the framework to handle a high volume of concurrent connections efficiently, which is critical for modern reactive microservices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47fbe3f1-6d97-40e4-95a2-699617d713ff', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What are the security considerations for implementing database multi-tenancy?', N'Senior', N'Multi-tenancy requires strict logical or physical isolation to prevent cross-tenant data leakage. Row-level security (RLS) policies at the database layer are essential to ensure that a tenant''s query can only access records associated with their unique identifier, even if an application-level bug occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81477440-a3e9-4cdf-b760-699dab8beb32', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What does it mean for Chi to be ''compositional''?', N'Intern', N'Compositional means that Chi allows you to build complex routing trees by nesting smaller routers within larger ones. This enables developers to organize code into logical modules or sub-services that are easier to maintain and test.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b054ee1-9c17-4f82-b05a-699fbf9716a1', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How do you decide between a Normalized (3NF) schema and a Denormalized schema in a distributed system?', N'Senior', N'Normalization is preferred for write-heavy systems to maintain data integrity and reduce anomalies. Denormalization is chosen for read-heavy distributed systems to minimize expensive joins and improve latency by co-locating data, despite the overhead of maintaining consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af771940-0b3d-4bff-8454-69aab2266f99', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Why might you use Hono''s ''Adapter'' pattern?', N'Middle', N'The adapter pattern allows Hono to interface with specific runtime features that aren''t part of the standard Web API. It provides a way to leverage platform-specific capabilities, such as specific storage or networking features, while keeping the core application logic clean.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17a940f0-dacd-4e22-8e99-69aca8593024', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the function of a Pipe in NestJS?', N'Junior', N'Pipes serve two purposes: transformation and validation. They can transform input data into a desired format or validate incoming data to ensure it meets specific criteria before reaching the route handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7d6375c-46c1-460e-ad9d-69ada8bdcf57', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Describe the impact of sound null safety on Dart''s compiler optimizations.', N'Senior', N'Sound null safety allows the compiler to make stronger assumptions about variable states, enabling aggressive optimizations such as the removal of runtime null checks. This results in smaller, faster binaries and allows developers to catch null-dereference errors at compile-time rather than runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3330dff-6cf5-4f76-a480-69b071c8fce1', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does the ''Middleware'' layer in NestJS differ from ''Interceptors'' in terms of accessing the execution context?', N'Senior', N'Middleware has access to the raw request and response objects but lacks context about the specific route handler or its metadata. Interceptors, on the other hand, operate closer to the handler and can access class and method-level metadata, making them better suited for request transformation or handler-specific logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fa4215c-d5ce-4b0e-8f7a-69b080875e2c', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why Use Lifting State Up?', N'Fresher', N'- Data Synchronization: Ensures child components react to the same state updates, preventing disparate or "stale" UI states. - Derived State Efficiency: Simplifies logic where multiple children depend on a single state variable; the parent calculates derived values, reducing redundant computations. Core Mechanism: React 19 Standards In modern React (19+), functional components and hooks have superseded class-based components. State is managed via useState and synchronized via prop drilling or React Context for deep component trees. Modernized Code Implementation (React 19) Parent Component: RectangleAreaCalculator Child Components: ShapeInput and ShapeArea Advantages - SSOT Integrity: Prevents state duplication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'450c06f1-d167-40ad-9538-69b296bd1915', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Describe the internal memory management strategy in Dart.', N'Senior', N'Dart utilizes a generational garbage collection strategy that separates objects into a young generation and an old generation. Short-lived objects are quickly reclaimed by a scavenger, while long-lived objects are promoted to the old space, which is managed by a more thorough mark-sweep or mark-compact collector to minimize latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9638ae88-17bf-451d-8282-69b407399648', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of the ''requirements.txt'' file?', N'Intern', N'A requirements.txt file lists all the Python packages and their specific versions required to run a Django project. This allows other developers to easily install the exact environment needed to work on the project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'071d2dbb-30f1-4514-92b9-69b61e91eed6', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What architectural patterns would you use to improve the latency of a globally distributed application?', N'Senior', N'I would employ edge computing to process requests closer to the user, implement a multi-region deployment strategy, and utilize read replicas to serve local data. Additionally, I would leverage aggressive caching layers at both the edge and application levels to minimize round-trips to the origin server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d398a10-0c70-4596-90c0-69bb9c1cef9b', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How do Tailwind''s ''Variants'' improve the developer experience for complex states?', N'Senior', N'Variants allow developers to define styles for states like ''active'', ''disabled'', or ''first-child'' using simple prefixes. This makes complex, state-driven UI logic easily readable within the component structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d10b47c-572d-41df-af91-69c152299198', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro maintain component isolation to prevent style leakage?', N'Senior', N'Astro scopes CSS by default, automatically generating unique hashes for class names during the build process. This prevents global style collisions, which is particularly useful in large projects where multiple developers contribute components independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15a23af3-e3d7-4cd9-a37a-69c3a6680b2b', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What are ''Qwik Bundles''?', N'Fresher', N'Qwik bundles are small, discrete pieces of JavaScript code generated by the optimizer. Because the application is split into many small files, the browser only downloads the specific logic needed for the current user action, significantly reducing the initial payload size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eef0e1b5-3169-449b-bc86-69c405c3b365', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the ''Apply'' method used for?', N'Junior', N'The ''apply'' method is a special convention in Scala that allows an object or class instance to be called like a function. If you implement ''apply'' in a companion object, you can instantiate the class without using the ''new'' keyword.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15f7ac6d-d9a8-4a96-bbfa-69c5267c9e32', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus handle configuration properties compared to traditional Java EE?', N'Senior', N'Quarkus uses the MicroProfile Config specification, which allows for unified configuration across environment variables, system properties, and files. Because configuration is processed at build time where possible, it allows for static optimization of settings while maintaining the flexibility to override values at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
