INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e6d71fd-9938-4d6b-abab-69c52bdeee4e', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle incoming HTTP requests using decorators?', N'Intern', N'Rocket uses procedural macros, often called decorators or attributes, to map incoming HTTP requests to specific handler functions. These attributes define the request path, the HTTP method, and the expected data types, allowing the framework to automatically route traffic and validate input without manual parsing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e7372bd-7eb4-4e8f-994d-69c613e1251b', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit''s ''Task'' controller differ from standard reactive properties?', N'Middle', N'The Task controller provides a declarative way to manage asynchronous operations like network requests while handling loading, success, and error states automatically. It simplifies the logic compared to manually managing promises and reactive flags within the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a23cf788-fd75-4d74-9668-69c79ef30e9e', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the benefit of using an alias in Webpack?', N'Intern', N'An alias allows you to create shorter or more intuitive paths for importing modules within your project. This prevents the need for long, messy relative paths like ''../../../../components/button''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2ceb079-ec54-482e-911d-69c913e2c8c0', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Why is stateless architecture preferred for horizontal scaling?', N'Middle', N'Stateless architecture ensures that any server can handle any request because no client session data is stored locally on the server. This makes it trivial to add or remove instances in a load-balanced environment without worrying about losing user state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd74f5f10-baf1-43b7-89a7-69cd4fb122f3', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between a shallow copy and a deep copy of a structure?', N'Middle', N'A shallow copy duplicates the structure''s members as they are, which means if the structure contains a pointer, both copies will point to the same memory location. A deep copy allocates new memory and duplicates the actual data pointed to, ensuring the two structures are entirely independent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76ecc855-ae9c-4548-9f60-69ce958b49eb', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the difference between ''React.memo'' and ''useMemo''?', N'Senior', N'React.memo is a higher-order component used to prevent a functional component from re-rendering if its props have not changed. useMemo is a hook used to cache the result of a specific calculation within a component, preventing that calculation from running on every render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b294d20e-70c7-4e4a-acff-69d3ac263b9b', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the difference between Events and Callbacks?', N'Fresher', N'1. Events: Node.js events module which emits named events that can cause corresponding functions or callbacks to be called. Functions ( callbacks ) listen or subscribe to a particular event to occur and when that event triggers, all the callbacks subscribed to that event are fired one by one in order to which they were registered. All objects that emit events are instances of the EventEmitter class. The event can be emitted or listen to an event with the help of EventEmitter Example: 2. Callbacks: A callback function is a function passed into another function as an argument, which is then invoked inside the outer function to complete some kind of routine or action.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fba3f606-1484-4cf6-94f9-69d6224e800e', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is Model Binding?', N'Intern', N'Model binding is the process where ASP.NET Core automatically maps data from an HTTP request to controller action parameters. It can extract data from form fields, query strings, and request headers to populate objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de0d601a-90c2-41b0-955c-69d6f7f4ae8d', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Evaluate the use of ''Decorators'' in AdonisJS for metadata-driven development.', N'Senior', N'Decorators allow for a clean, declarative way to define routing, validation, and serialization rules without cluttering the business logic. While this improves readability, it can make the control flow harder to trace for developers unfamiliar with the framework''s internal reflection mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96817433-b3e7-4b79-9d55-69d8500f5316', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the Difference Between Methods & Constructors?', N'Fresher', N'Methods - Method name can be any name. - With respect to one object one method can be called for ''n'' members of lines - Methods are used to represent business logic to perform the operations Constructor - Constructor will be executed automatically whenever we create a object. - With respect to one object one constructor can be executed only once - Constructors are used to define & initialize the non static variable', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a760f5ed-d801-468e-8b4d-69d87e77d62c', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why is it important to use ''Arc'' when sharing State in Axum?', N'Middle', N'Axum handlers are executed concurrently, meaning the application state must be shared across multiple threads. Using an Atomic Reference Counter ensures that the state remains valid as long as at least one handler is referencing it, providing thread-safe access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f1b0aff-4032-4e0e-b328-69dc9cb52b3d', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are optional properties in an interface?', N'Intern', N'Optional properties are fields in an interface that may or may not be provided by an object. They are indicated by adding a question mark after the property name, allowing the object to remain valid even if that property is missing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'838a859b-ce40-4f03-8db2-69e0e5611d45', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the role of ''DTOs'' in Litestar and why are they preferred over raw Pydantic models in API design?', N'Middle', N'DTOs in Litestar provide a structured way to separate the internal domain representation of data from the public-facing API schema. They allow developers to define specific data transfer patterns, handle partial updates, and enforce stricter validation rules independently of the underlying persistence models, which prevents leaking sensitive database fields to clients.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee2d96fe-f366-400a-8c95-69e1250f3597', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is horizontal scaling, and why is it preferred in NoSQL?', N'Junior', N'Horizontal scaling, or scaling out, involves adding more servers or nodes to a database cluster to handle increased load. NoSQL databases are designed for this because they can distribute data across multiple machines easily, whereas SQL databases typically rely on vertical scaling, which is upgrading a single server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe9e75ba-c6f4-45a6-b39e-69e573d75a4a', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the purpose of the ''Entity'' decorator in NestJS when using TypeORM?', N'Middle', N'The Entity decorator marks a class as a database table. It maps the class properties to database columns, allowing the ORM to perform CRUD operations automatically based on the class definition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23a72fa5-10b7-490e-8e08-69e61887f026', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut achieve its performance benefits?', N'Intern', N'Micronaut achieves performance benefits by using ahead-of-time (AOT) compilation to perform dependency injection and aspect-oriented programming. Unlike traditional frameworks that use heavy reflection at runtime, Micronaut generates the necessary metadata during the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
