INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42c4f7b7-b39f-4f2f-9113-69f1f397e538', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the role of the Metaspace in Java 8+ and how it differs from the older PermGen space.', N'Senior', N'Metaspace stores class metadata in native memory rather than the heap, eliminating the common OutOfMemoryError associated with fixed-size PermGen. This allows the JVM to dynamically resize the metadata area based on the available system memory, providing better stability for applications with heavy class loading patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a4bf92d-948d-4972-9686-69f1fa4a0056', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Explain the performance implications of jQuery''s Sizzle engine compared to native browser DOM APIs.', N'Senior', N'While Sizzle provided critical cross-browser consistency in the past, it relies on complex regex and manual parsing of CSS selectors. Native methods like querySelectorAll are implemented in C++ and benefit from browser-level optimizations, making them significantly faster than the abstraction layer provided by jQuery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'514b718f-5802-4eb1-88c5-69f6ade13c63', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are adapter-auto, adapter-node, and adapter-static?', N'Fresher', N'Adapters are plugins that translate SvelteKit''s output into a format suitable for specific deployment environments. They allow you to deploy the same application to different platforms like Vercel, Node.js servers, or as a static site.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'115e52d0-22a5-49ac-a8b9-69f7b22773ce', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is a Property in C#?', N'Intern', N'A property is a member that provides a flexible mechanism to read, write, or compute the value of a private field. Properties use get and set accessors to control how data is accessed and modified, providing a layer of abstraction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae6f0303-1f33-4d92-804b-69f8a75ff7c0', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI''s exception handling mechanism allow for centralized error management?', N'Senior', N'FastAPI provides global exception handlers that allow you to catch specific exceptions raised anywhere in the application and map them to standardized HTTP responses. This promotes consistent error reporting across the entire API and prevents sensitive internal stack traces from leaking to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
