INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ef557c3-161f-4f6e-9b1a-69fcadf85417', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the purpose of a Web Application Firewall (WAF)?', N'Middle', N'A WAF sits in front of web applications and monitors, filters, and blocks malicious HTTP traffic. It is specifically designed to protect against common web exploits such as SQL injection, cross-site scripting, and other layer seven attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50c099b3-e68c-4473-8832-69feba8c393f', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you handle data migration between two different database technologies?', N'Middle', N'I would use a dual-write approach where the application writes to both the old and new systems while performing a background migration of historical data. After validating data integrity, I would switch the read path to the new system, keeping the old one as a fallback for a period.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b680ea99-f597-4379-bc70-6a01ccd9c9e1', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the architectural trade-offs of using ''Declaration Merging'' in large-scale applications.', N'Senior', N'Declaration merging allows extending existing types or interfaces, which is useful for plugins or augmenting third-party libraries. However, it can lead to global namespace pollution and hidden side effects, making it harder to track the origin of type definitions in a large codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5147a819-d6a7-45f8-809c-6a01d8b0b943', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis achieve persistence if it is an in-memory store?', N'Middle', N'Redis offers two main persistence mechanisms: RDB, which creates point-in-time snapshots of the dataset at specified intervals, and AOF, which logs every write operation received by the server. Combining both provides a balance between fast recovery times and minimal data loss in the event of a crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'547f7dfe-3bc7-4cc7-a445-6a0a6a561928', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel handle database transactions?', N'Fresher', N'Laravel provides a simple interface for database transactions using the DB facade. This allows you to group multiple database operations into a single unit, ensuring that if any operation fails, the entire set of changes can be rolled back to maintain data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df3b44ce-70e4-4c6b-b39a-6a0cf9810577', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does the ''readonly'' modifier do?', N'Intern', N'The ''readonly'' modifier prevents a property of an object or an element of an array from being reassigned after initialization. It helps ensure data immutability within your program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fbcafdf-f1aa-4c22-a241-6a0de56931db', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does the C++ move constructor optimize performance compared to a standard copy constructor?', N'Middle', N'A move constructor transfers ownership of resources from a temporary object to a new one by simply copying pointers and nullifying the source, rather than performing a deep copy of the underlying data. This significantly reduces performance costs by avoiding expensive heap allocations and data duplication, especially when handling large containers or complex objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
