INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22d3ea53-312f-4719-9ed3-6a1932509234', N'075b8862-431c-4678-9767-f55359758a4a', N'What are differences between mutations and actions?', N'Intern', N'Actions are similar to mutations, but there are two main differences, 1. Mutations perform mutations on the state, actions commit mutations. 2. Actions can contain arbitrary asynchronous operations unlike mutations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22239050-aec7-4bca-995d-6a1e115580ac', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the role of NestJS middleware in the context of Microservices and provide a scenario where middleware is beneficial in a Microservices setup?', N'Fresher', N'Middleware is a function that is executed before the route handler. Middleware functions have access to the request and response objects, and the next() middleware function in the application’s request-response cycle. They can execute any code, make changes to the request and the response objects, end the request-response cycle, and call the next middleware function in the stack. In the context of microservices, middleware can play several important roles: 1. Request Logging: Middleware can be used to log details of incoming requests. This can be useful for debugging, as well as for tracking usage patterns and user behavior. 2. Authentication and Authorization: Middleware can verify a user''s identity and permissions before a request reaches a service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ece1c8b5-a8d3-4857-ba15-6a1effdfa0fd', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is normalization in the context of databases?', N'Junior', N'Normalization is the process of organizing data to reduce redundancy and improve data integrity. It involves dividing large tables into smaller, related tables and defining relationships between them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fee8a494-c392-4aec-b88b-6a207307f78d', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik compare to frameworks that use Island Architecture?', N'Middle', N'Qwik is similar to Island Architecture in that it attempts to ship only necessary code. However, while Islands usually require each component to be hydrated separately, Qwik''s resumability model allows the entire application to exist as one unified, resumable entity without needing individual hydration triggers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
