INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e355f77-0f0e-466a-bc08-6a224f48cfd0', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What does it mean for Redis to be a key-value store?', N'Intern', N'A key-value store is a type of database where every piece of data is associated with a unique key. You retrieve information by requesting the specific key, which allows for very efficient lookups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
