INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'151b1072-1b01-4985-8b51-6a2c4279bb30', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery maintain element sets, and why can this lead to memory leaks?', N'Middle', N'jQuery keeps a collection of DOM nodes in memory whenever you wrap them in a jQuery object. If these objects are stored in long-lived variables and the associated DOM nodes are removed from the document, they may not be garbage collected, leading to memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
