INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ac80285-1efb-428a-bd44-6a41d71532e9', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do you update nested objects inside state?', N'Fresher', N'You cannot simply use spread syntax for all kinds of objects inside state. Because spread syntax is shallow and it copies properties for one level deep only. If the object has nested object structure, UI doesn''t work as expected with regular JavaScript nested property mutation. Let''s demonstrate this behavior with an example of User object which has address nested object inside of it. If you try to update the country nested field in a regular javascript fashion(as shown below) then user profile screen won''t be updated with latest value. This issue can be fixed by flattening all the fields into a top-level object or create a new object for each nested object and point it to it''s parent object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
