INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c2781d7-78ff-4434-99e5-6a4e0456a2d1', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the role of the Primary node in a MongoDB replica set?', N'Fresher', N'The Primary node is the only member in a replica set that receives all write operations. All other members, known as Secondaries, replicate the data from the Primary to ensure consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
