INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03d0263a-2ab6-49f5-9214-6a60d56d87d0', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is Type Casting and what are its types in C#?', N'Intern', N'Type casting, in the context of C#, refers to the explicit and implicit conversion of data types. While explicit casting might lead to data loss, implicit casting is carried out by the Ccompiler, ensuring safe conversion. Implicit Casting This form of casting is automatic and occurs when there is no risk of data loss. For instance, an int can be automatically cast to a long as there is no possibility of truncation. Explicit Casting This form of casting must be done manually and is necessary when there is a risk of data loss. For example, when converting a double to an int, data loss due to truncation could occur. Crequires you to explicitly indicate such conversion, and if the conversion is not possible, it throws a System.InvalidCastException.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b098f7e0-9aee-4864-8b63-6a6113607d2b', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is Hot Module Replacement (HMR) and how does Vite handle it?', N'Fresher', N'HMR is a feature that allows modules to be updated in a running application without a full page reload. Vite performs HMR over native ES modules, ensuring that when a file is edited, only the specific module that changed is replaced, which keeps the update process extremely fast.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'868fa91a-bf03-4b5e-8885-6a61493834bb', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why does C require a strict aliasing rule, and how do compilers enforce it?', N'Senior', N'Strict aliasing dictates that an object should only be accessed through an lvalue of its own type or a compatible type. This rule allows the compiler to assume that pointers of different types do not refer to the same memory location, facilitating better optimization of load and store operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4dca8a19-5d76-4bf3-b901-6a635d9d2f73', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What happens when a user navigates to a Remix route?', N'Junior', N'When a user navigates, Remix fetches the necessary data via a loader, renders the corresponding component on the server, and sends the HTML to the browser. Once the JavaScript loads, subsequent navigations are handled via client-side transitions to improve performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d2e2078-3be1-4ace-9d4f-6a65285e648d', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a ''rollback'' in the context of a transaction?', N'Junior', N'A rollback is an operation that undoes all changes made during the current transaction. It is typically triggered when an error occurs, ensuring the database returns to its previous stable state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e7f45ac-39bc-4881-a796-6a69169565db', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the primary difference between a Transient, Scoped, and Singleton service lifetime in ASP.NET Core dependency injection?', N'Middle', N'Transient services are created every time they are requested, making them lightweight and stateless. Scoped services are created once per client request, ensuring consistency across that specific request''s lifecycle. Singleton services are created the first time they are requested and then every subsequent request uses the same instance for the lifetime of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd75a7554-860f-4a78-9f89-6a6a8bd89f3a', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the primary purpose of Webpack?', N'Intern', N'Webpack is a module bundler for modern JavaScript applications. Its main job is to take various assets like JavaScript, CSS, and images, resolve their dependencies, and bundle them into optimized files that a browser can easily load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1824c651-ef85-4d35-8783-6a6af9437839', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is function overloading?', N'Intern', N'Function overloading allows multiple functions to have the same name provided they have different parameter lists. The compiler determines which version of the function to call based on the number and type of arguments passed. This improves code readability and provides flexibility in function usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c7edf86-0913-4190-83db-6a6cd6d8ee44', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between synchronous and asynchronous commits?', N'Middle', N'Synchronous commits ensure that a transaction is written to the WAL on disk before the client receives a success message, guaranteeing durability. Asynchronous commits return success to the client as soon as the transaction finishes locally, which improves performance but poses a small risk of data loss during a power failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'048aa2be-9b86-4ab5-9080-6a6e3d9570d6', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you evaluate the trade-offs between eventual consistency and strong consistency in a distributed system?', N'Senior', N'I analyze the business requirements for latency and data accuracy. Strong consistency often mandates synchronous coordination which increases latency and reduces availability, whereas eventual consistency improves throughput and fault tolerance but introduces the risk of stale reads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3806d105-95e8-4264-9619-6a6ec47ef681', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the concept of Type Narrowing.', N'Middle', N'Type narrowing is the process of refining a broader type into a more specific type within a conditional block. TypeScript achieves this through mechanisms like type guards, control flow analysis, and equality checks, allowing the compiler to safely treat a variable as a specific subtype.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f2b7e3e-57fc-4496-aca4-6a70d80dec98', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the trade-offs of using Flask''s built-in development server in production.', N'Middle', N'The built-in development server is designed solely for ease of use during local development and lacks security features like robust request handling and protection against denial-of-service attacks. Using it in production is highly insecure and inefficient, as it cannot handle multiple concurrent connections or provide the performance necessary for a live environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e31f386-2029-4e67-823a-6a728cdb1719', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis ensure data safety during an AOF rewrite?', N'Middle', N'During an AOF rewrite, Redis creates a new, compact version of the log file by traversing the current in-memory data. While the rewrite is in progress, any new incoming writes are appended to an in-memory buffer and the existing AOF file, ensuring that the new file is fully consistent once the process completes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1158cd44-82d5-421c-a9c5-6a72d75d51b6', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the role of the R evaluation environment in lexical scoping?', N'Senior', N'R uses lexical scoping, where variable lookups are determined by the physical structure of the code rather than the call stack. The evaluation environment maintains a chain of parent environments, allowing functions to access variables defined in their enclosing scopes, which is fundamental to supporting closures and functional programming patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8d79184-14e3-4bc0-96e2-6a757cdf92f1', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle graceful shutdown, and what is its relationship with Tokio?', N'Senior', N'Axum relies on the underlying Hyper server to listen for signals, which are typically managed via Tokio''s signal handling tasks. When a shutdown signal is received, the server stops accepting new connections and waits for existing in-flight requests to finish, ensuring no data loss during deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41bb8d6e-9346-4581-851d-6a7742c958e8', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does the ''slots'' attribute influence object memory usage in Python?', N'Senior', N'By default, objects store attributes in a dynamic dictionary (__dict__), which consumes significant memory. Defining __slots__ restricts the object to a fixed set of attributes, allowing Python to allocate a compact array instead of a dictionary, significantly reducing memory overhead for objects created in large quantities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd245504-5e53-4aed-b1df-6a77e554218d', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why is Webpack considered a module bundler and not a task runner?', N'Fresher', N'Webpack focuses on analyzing the dependency graph and bundling modules together. While task runners like Gulp are designed to automate repetitive tasks like file renaming, Webpack''s core goal is managing code dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
