INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6599efe3-ac61-460b-b76a-6a807638adea', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Explain the concept of ''lazy deletion'' (lazyfree) in Redis.', N'Senior', N'Lazy deletion allows Redis to offload the expensive memory reclamation of large objects to background threads instead of blocking the main thread. This is crucial for maintaining performance when deleting large collections like hashes or sets that would otherwise take significant time to clear.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86c31af9-065a-4abb-8ed9-6a807ac6e6d6', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle a scenario where a database index is causing high write latency, but removing it would break search performance?', N'Senior', N'I evaluate the query patterns to determine if I can replace the index with a specialized search engine that is better optimized for read-heavy workloads. If that is not possible, I might explore partial indexing or read replicas to offload the query pressure from the primary write database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
