INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2302f580-a751-4cc9-b9ad-6a88580a08d8', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How can you implement a singleton pattern in Ruby?', N'Middle', N'The most idiomatic way is to include the standard library''s Singleton module in a class, which prevents direct instantiation and provides a global access point. Alternatively, one can define a module with module methods, which acts as a global namespace for utility functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
