INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83c76383-eeb6-4c9b-963b-6a8ef0ccac4d', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What happens if a user disables JavaScript in the browser when using Alpine.js?', N'Middle', N'If JavaScript is disabled, Alpine.js will not execute, and the UI will remain in its initial server-rendered state. This makes it critical to ensure that core functionality is still accessible or at least gracefully degraded via standard HTML elements like links and forms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5bc2e64-00a2-4763-8e5f-6a90e231818c', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django handle database transactions, and why should you use them?', N'Middle', N'Django uses the ''atomic'' decorator or context manager to ensure that a block of code either succeeds entirely or fails entirely, maintaining data integrity. This is crucial for operations involving multiple related database updates to prevent partial data commits in case of errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f47aefe8-25a0-44e7-bb89-6a919697c67a', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How do distributed transactions affect database performance?', N'Middle', N'Distributed transactions require two-phase commits to ensure atomicity across multiple nodes, which involves significant locking and network communication. This creates a bottleneck that drastically reduces write throughput and increases latency in scaled systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80445a2a-0d48-45d5-969a-6a94f7b374b2', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why is it important to use a virtual destructor in a base class?', N'Junior', N'A virtual destructor ensures that when a derived class object is deleted through a pointer to the base class, the destructor of the derived class is called first. Without this, only the base class destructor would execute, potentially causing memory leaks if the derived class allocated additional resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
