INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa6334a8-bd5a-406b-b271-6a9bfa8227f2', N'a2838158-7305-480a-b22b-4dc35776b400', N'What are the advantages of using ''Event Sourcing'' over traditional state storage?', N'Senior', N'Event Sourcing stores the sequence of state-changing events rather than the current state, providing a perfect audit log and the ability to reconstruct state at any point in time. This enables complex debugging, temporal queries, and easy integration with event-driven architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9aa0f1cf-c049-48a5-a4bf-6a9dc50009ba', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why is it important to provide a range rather than a single number when estimating the time for a project task?', N'Fresher', N'Estimating software tasks involves inherent uncertainty due to potential complexities or dependencies. Providing a range, such as a minimum and maximum, accounts for these unknowns and helps set realistic expectations for stakeholders. It reflects a professional understanding that effort can fluctuate based on unforeseen technical hurdles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55da1c08-5feb-4510-a8a8-6aa167bbe7b6', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does the Go runtime decide when to trigger a garbage collection cycle?', N'Senior', N'The GC is triggered based on the heap growth ratio defined by the GOGC environment variable, which represents the percentage of heap growth allowed since the last collection. This balance allows developers to tune the system for either lower memory usage or lower CPU consumption depending on their service requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cf4d7eb-cebc-4f4a-9e7c-6aa1b58fc93d', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you get the current route?', N'Fresher', N'In Angular, there is an url property of router package to get the current route. You need to follow the below few steps, 1. Import Router from @angular/router 2. Inject router inside constructor 3. Access url parameter', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e845c4e-00d3-4354-80b4-6aa27c89e4ce', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Why is FastAPI considered a ''high-performance'' framework?', N'Middle', N'FastAPI is built on Starlette for web handling and Pydantic for data validation, both of which are highly optimized. By combining modern Python asynchronous capabilities with these efficient libraries, it achieves performance levels comparable to Node.js or Go.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'363c2b6c-7e5c-45b1-8d45-6aa9b2c695e6', N'a2838158-7305-480a-b22b-4dc35776b400', N'Under what conditions would you choose a gossip protocol over a centralized membership service?', N'Senior', N'Gossip protocols are preferred for large-scale, dynamic systems where nodes frequently join or leave, as they avoid the single point of failure and bottleneck associated with a centralized coordinator. They provide eventual consistency in membership information with low overhead. However, they are unsuitable when immediate, global state knowledge is required due to the inherent propagation delay.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77248cfe-505c-4a2e-98fd-6aad09e88881', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Why is it important to use Artisan commands?', N'Junior', N'Artisan is the command-line interface included with Laravel that automates repetitive programming tasks. It allows developers to quickly generate boilerplate code, manage database migrations, clear caches, and perform other maintenance tasks efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4b2351c-ab4e-4425-bf9a-6aaea170ceaf', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the architectural significance of Astro being ''framework agnostic''?', N'Senior', N'Being framework agnostic allows teams to migrate gradually by incorporating new framework components into existing projects or using different frameworks for different islands. It avoids vendor lock-in and allows developers to choose the best tool for specific requirements without rewriting the entire application architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a62b64b0-dec0-4859-b770-6ab2f813bba1', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the Quarkus ''Reactive'' programming model?', N'Intern', N'The reactive model is non-blocking and event-driven, allowing a small number of threads to handle a large volume of concurrent requests. It is built on the Vert.x toolkit and is highly efficient for high-throughput applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'808b9bfb-093a-4c63-b59d-6ab4c9136c52', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are Ruby''s accessor methods?', N'Intern', N'In Ruby, accessor methods allow you to manipulate object attributes. There are three types of accessor methods: attr_reader, attr_writer, and attr_accessor, each serving a specific role in the attribute''s lifecycle Attribute Methods - attr_reader: Generates a simple getter method for an attribute. It can be accessed but not modified externally. - attr_writer: Generates a basic setter method. The attribute can be modified but not read externally. - attr_accessor: Combines both getter and writer methods in one. This creates a full-fledged getter and setter for the attribute. Code Example: Accessor Methods Here is the Ruby code:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74458af2-1a23-45e7-b54a-6ab55cd1e361', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a pure function?', N'Intern', N'Pure functions are functions that accept an input and returns a value without modifying any data outside its scope(Side Effects). Its output or return value must depend on the input/arguments and pure functions must return a value. Example: Pure Function It is a pure function because you always get a Hello as output for the pass as an input. Example: Not Pure Function The function''s output now depends on an outer state called greeting. What if someone changes the value of the greeting variable to Hola? It will change the output of the sayGreeting() function even when you pass the same input. A function must pass two tests to be considered pure: * Same inputs always return same outputs * No side-effects Benefits: * Predictable: It produces a predictable output for the same inputs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2635af83-22c1-4b35-9cb0-6ab60c73a87e', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do Sass variables differ from standard CSS variables?', N'Junior', N'Sass variables are processed at compile time and do not exist in the final browser output. Native CSS variables are processed at runtime in the browser, allowing for dynamic updates via JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'477a52c5-78c2-48c2-a4da-6abbf2c033d1', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why is it important to consider item size limits in DynamoDB?', N'Middle', N'DynamoDB has a strict limit of 400KB per item. If an application attempts to store an item larger than this, the operation will fail, which necessitates careful data modeling and potential strategies like offloading large blobs to S3 and storing only the reference URL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'031f7bd5-1033-4ea2-a7c0-6abf5787593e', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Explain the distinction between Gin''s ''Handle'' function and standard Go ''http.Handler'' interface.', N'Senior', N'Gin''s ''Handle'' function uses a specific ''gin.HandlerFunc'' type which includes the custom context. This is fundamentally different from the standard library''s ''http.Handler'' interface, meaning Gin handlers are not directly interoperable with standard Go middleware without using an adapter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd95cb377-defd-46e9-a396-6ac283a6c2b3', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a partition hot spot and how can it be avoided?', N'Middle', N'A hot spot occurs when a single partition receives a disproportionately high amount of traffic compared to others. It is usually avoided by choosing a high-cardinality partition key that ensures an even distribution of data across the cluster nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc76c9f7-f0b8-43ad-b758-6ac2851ddc49', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Can you run a Flask application in debug mode in production?', N'Junior', N'No, you should never run a Flask application in debug mode in production. Debug mode enables an interactive debugger that allows arbitrary code execution, which poses a severe security risk if exposed to the public internet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a678585e-400e-43eb-b946-6ac373e9438d', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix handle failure isolation using supervisors and the ''Let it Crash'' philosophy?', N'Senior', N'Phoenix relies on the OTP supervisor tree, where processes are grouped into hierarchies that monitor and restart sub-processes upon failure. By isolating functionality within separate processes, a crash in one request or component does not destabilize the entire system, allowing for self-healing behavior without manual recovery logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af948f9b-a709-4040-a050-6ac6d36fa664', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik''s ''server-first'' philosophy impact the development lifecycle?', N'Senior', N'The server-first approach forces developers to be conscious of where code executes, encouraging a clear separation between data fetching and UI logic. It simplifies state synchronization but requires developers to adapt to strict serialization rules for shared data between the server and client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80d77f7a-2b58-47a9-8ffe-6ac731547b0a', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Explain the significance of Svelte''s ''module'' context.', N'Middle', N'The module context allows code to run once when the component module is first loaded, rather than once per component instance. It is useful for defining shared logic, constants, or data that should persist across all instances of a component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0826720-4be1-4961-b814-6ac7bb751d6b', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Why is it recommended to use ''env'' variables for configuration instead of hardcoding?', N'Middle', N'Hardcoding secrets or environment-specific URLs makes the application insecure and difficult to deploy across different environments. Using environment variables allows the same code base to adapt to various infrastructure setups while keeping sensitive credentials out of version control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efc3fb8c-51a4-4d4b-b26f-6ac8cf124762', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What happens to performance when a table has many indexes?', N'Middle', N'Each index adds overhead to write operations like INSERT, UPDATE, and DELETE because every index must be updated whenever the underlying table data changes. While indexes speed up read queries, an excessive number of them can significantly degrade the write throughput of the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
