INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bc44d84-a695-4d3d-b8ba-6acf5f40700d', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does the AdonisJS configuration system handle environment-specific settings?', N'Middle', N'AdonisJS uses a strict environment variable validation system that prevents the application from starting if required configuration is missing or malformed. Settings are then mapped to configuration files, providing a type-safe and centralized way to access environment-specific values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'421c0e23-63a1-4690-b6ae-6ad80f555e4c', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the impact of biased locking and why has it been deprecated in recent JVM releases?', N'Senior', N'Biased locking was an optimization that allowed a thread to acquire a lock without atomic instructions if it was the only thread accessing the object, which reduced overhead in single-threaded scenarios. It was deprecated because it added significant complexity to the synchronization subsystem and provided diminishing returns given the improvements in uncontended lock performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b47a25a3-b1d4-46b8-9bb8-6ad923ad223e', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What does Auto-configuration mean in Spring Boot?', N'Intern', N'Auto-configuration automatically configures your Spring application based on the dependencies present in your classpath. It intelligently guesses what features you might need and sets up standard configurations, which you can override if necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2977fb0b-6aa2-4188-9f60-6ad93c5618fc', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact optimize DOM updates?', N'Fresher', N'Preact optimizes updates by batching changes and performing them in a single pass. By updating the DOM only when necessary and minimizing the number of operations, it provides a smooth user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c594294e-b238-4fde-86b3-6ada891e9add', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is database scalability?', N'Intern', N'Database scalability is the ability of a database system to handle an increasing amount of work or data. It can be achieved through vertical scaling, by adding more power to an existing server, or horizontal scaling, by adding more servers to a distributed system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4d2a0eb-4259-4dc0-8b5a-6adca457f83f', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Analyze the performance overhead of Method Handles versus traditional Reflection.', N'Senior', N'Method Handles provide a type-safe, more performant alternative to reflection by allowing the JVM to inline and optimize the call site more effectively. While reflection incurs a significant cost due to repeated permission checks and boxing, method handles are designed to be linked and JIT-compiled similarly to direct method invocations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f7dc4bc-12f5-46d8-baea-6adccdc8bc96', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the function of the ''Micronaut Context''?', N'Middle', N'The Micronaut Context serves as the central container for managing bean lifecycles and dependency injection. It is responsible for resolving dependencies at runtime, even though the bean definitions were prepared during the compile-time phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d4daabd-a63a-4c54-a5a4-6add531ba864', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the mechanics of Dart''s isolate-based concurrency model compared to traditional thread-based systems.', N'Senior', N'Dart uses an actor-model approach where isolates run in their own memory space and do not share mutable state. This eliminates the need for locks, mutexes, or semaphores, thereby preventing race conditions and deadlocks while enabling highly scalable parallel execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee64e235-1346-4db8-b546-6ade9cecf558', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Explain the trade-off of using Hono''s ''RPC Mode'' for client-server communication.', N'Middle', N'RPC Mode provides end-to-end type safety between the backend and frontend without generating complex OpenAPI documentation. The trade-off is a tight coupling between the client and server codebases, which can make independent deployments slightly more complex if not managed via shared packages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'709927c9-7411-46cc-b203-6ae442b77e57', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Compare Async-Await and Generators usage to achive same functionality?', N'Middle', N'1. Generators/Yield: Generators are objects created by generator functions — functions with an * (asterisk) next to their name. The yield keyword pauses generator function execution and the value of the expression following the yield keyword is returned to the generator''s caller. It can be thought of as a generator-based version of the return keyword. Example: 2. Async/Await: Async keyword is used to define an asynchronous function, which returns a AsyncFunction object. Await keyword is used to pause async function execution until a Promise is fulfilled, that is resolved or rejected, and to resume execution of the async function after fulfillments. When resumed, the value of the await expression is that of the fulfilled Promise. Key points: 1.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3514ed0-ea6b-4f94-b71e-6aea3b427945', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How can you copy an object in Python?', N'Fresher', N'To copy an object in Python, you can try copy.copy () or copy.deepcopy() for the general case. You cannot copy all objects but most of them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'350262dc-3c8a-4003-b6f3-6aec521a71dd', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the significance of the ''implicit'' resolution mechanism and how it differs from standard dependency injection.', N'Senior', N'The implicit mechanism resolves dependencies at compile-time based on the lexical scope and type constraints, essentially serving as a type-directed search. Unlike runtime dependency injection, this approach ensures type safety and eliminates the need for manual plumbing, though it can lead to complex debugging if the implicit search space is not carefully managed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
