INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b3c7d2d-7f02-4dd0-813b-6b10983c411f', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Discuss the trade-offs of using Nuxt''s ''Universal Rendering'' compared to ''Client-Side Rendering''.', N'Senior', N'Universal rendering provides superior SEO and faster perceived initial load times by delivering pre-rendered HTML. Client-side rendering reduces server infrastructure complexity and costs, but it requires the browser to execute the full JavaScript bundle before content becomes visible, potentially hurting search engine indexing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd911d55a-c4cb-4ff1-a7cb-6b113481c175', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is CSRF protection in Rails?', N'Intern', N'CSRF stands for Cross-Site Request Forgery. Rails provides built-in protection by requiring an authenticity token on non-GET requests, ensuring that the request originated from your own application and not a malicious third-party site.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c6348b9-85ff-4ea5-a0dc-6b143a2a7a2d', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach debugging a non-deterministic, intermittent production issue that does not leave clear log traces?', N'Senior', N'I would first focus on increasing observability by implementing high-resolution distributed tracing and correlation IDs to isolate the request path. Simultaneously, I would perform a statistical analysis of the environment metadata to identify patterns related to resource contention, deployment cycles, or external dependency latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'568d0230-4ba1-4264-8142-6b1830e64c57', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the benefit of using ''LitElement'' as a base class?', N'Fresher', N'LitElement provides a solid foundation for creating web components by automating property observation, template rendering, and shadow DOM management. It reduces the amount of boilerplate code required to create standard-compliant web components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e1b2e9a-c617-4326-9747-6b1f66f28663', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the architectural trade-offs when choosing between a Wide-Column store and a Document store for time-series data?', N'Senior', N'Wide-column stores excel at write throughput and storage efficiency for time-series data due to their ability to optimize data layout by row keys and column families. Document stores offer greater schema flexibility and easier indexing for varied query patterns, but they often incur higher storage costs and overhead compared to the structured, predictable nature of wide-column schemas in high-velocity ingestion scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1636b337-d723-4376-9ad9-6b2677c27864', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is an aggregate function in SQL?', N'Junior', N'An aggregate function performs a calculation on a set of values and returns a single summary value. Common examples include SUM, AVG, COUNT, MAX, and MIN, which are often used in conjunction with grouping clauses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8b8a7c3-aaae-4ebd-80e3-6b288dd7a265', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does the C++ ''inline'' keyword interact with the linker?', N'Senior', N'The ''inline'' keyword is a suggestion to the compiler to embed the function code directly into the caller, but it also alters the linker''s behavior regarding the One Definition Rule. It allows the same function to be defined in multiple translation units without causing link-time errors, as the linker will merge these definitions into a single instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc7abaaa-3e4e-40a5-abba-6b2ed5d3d3c7', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are synthetic events in React?', N'Intern', N'SyntheticEvent is a cross-browser wrapper around the browser''s native event. Its API is same as the browser''s native event, including stopPropagation() and preventDefault(), except the events work identically across all browsers. The native events can be accessed directly from synthetic events using nativeEvent attribute. Let''s take an example of BookStore title search component with the ability to get all native event properties List of common synthetic events are: * onClick * onChange * onSubmit * onKeyDown, onKeyUp * onFocus, onBlur * onMouseEnter, onMouseLeave * onTouchStart, onTouchEnd', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3019dff3-52b6-456e-bb51-6b2ef141b946', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the benefit of using a distributed cache like Redis?', N'Middle', N'A distributed cache stores frequently accessed data in memory, significantly reducing latency and the load on backend databases. It allows for fast read operations and ensures that cached data is accessible across multiple application nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db71d7b5-33b3-4ef4-8adc-6b30e88fcb8e', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How does the Strangler Fig pattern assist in refactoring a monolithic application?', N'Senior', N'This pattern involves incrementally replacing specific functionalities of the monolith with new microservices. Over time, the new services ''strangle'' the monolith until it can be retired, allowing for a low-risk, phased migration rather than a high-risk ''big bang'' rewrite.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae68fc4c-1ba8-4e04-b4c5-6b3440815e23', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the primary difference between the MyISAM and InnoDB storage engines in MySQL?', N'Junior', N'The main difference is that InnoDB supports ACID-compliant transactions and row-level locking, making it safer for data integrity. MyISAM, by contrast, only supports table-level locking and does not support transactions, which can lead to performance issues in write-heavy environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'356ae47f-362b-4522-bf76-6b37eca4aec7', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When faced with a cascading failure in a production environment, what is your immediate strategy for mitigation?', N'Senior', N'I prioritize stabilizing the system by implementing circuit breakers and rate limiting to prevent further resource exhaustion. Once the system is contained, I shift focus to identifying the root cause through logs and metrics before performing a controlled rollout of a fix or a rollback to the last known stable state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
