INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1b45d8f-f22b-46d5-904b-6b3c87cc31be', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is a QuerySet in Django and how is it used?', N'Intern', N'In Django, a QuerySet represents a collection of database queries that can be chained and lazily executed. It provides an intuitive way to retrieve and manipulate data from the database using Python. QuerySet Basics - Initializationic: QuerySets are generated automatically when you interact with a Django model using its Manager. - Chaining: Multiple methods can be chained together before the QuerySet is evaluated. - Lazy Evaluation: QuerySets are only executed when data is required, such as when iterating through the results or explicitly calling evaluation methods like list() or count(). - Immutability After Evaluation: Once a QuerySet is evaluated, its results cannot be altered. For instance, you can''t add more items to a list after it''s been created.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
