INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5dd514cf-ed63-4722-8970-6b5aa02bf927', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why might someone choose Tailwind over traditional CSS files?', N'Intern', N'Tailwind is often chosen for faster development speed and easier maintenance. It avoids the ''CSS bloat'' of large projects by reusing existing classes and provides a consistent set of design constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8790bf4-d70b-4dd5-88c1-6b5b9d5c0008', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do migrations ensure schema consistency across multiple development and production environments?', N'Senior', N'Migrations provide a version-controlled, programmatic way to evolve the database schema, ensuring that all environments remain synchronized. They allow for incremental updates and rollbacks, minimizing the risk of deployment errors, though they require careful handling of lock times during execution in high-traffic production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3651f6d-cb3c-4093-bbdd-6b618b1f5804', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a database transaction?', N'Fresher', N'A transaction is a single logical unit of work that consists of one or more database operations. A transaction must either be fully completed or not performed at all to ensure the database remains in a consistent state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'245431bf-db30-4739-9550-6b653b7f29d7', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of ''index lifecycle management'' (ILM)?', N'Middle', N'ILM automates the management of indices based on their age and size, allowing for actions like moving data to cheaper storage or deleting old indices. This is critical for managing logs and time-series data to control costs and maintain performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fdd0a5a-2473-46dd-ac63-6b655f654786', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you design an API to handle bulk updates efficiently?', N'Senior', N'Use a transactional batch endpoint that accepts an array of operations, ensuring the operation is atomic if the underlying data store supports it. If atomicity is not possible, design the endpoint to return partial success responses that detail which individual operations failed and why, allowing the client to retry just the failed items.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b7b7c96-0aa0-46df-abbe-6b65f47094c7', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is normalization in Redux state structure?', N'Middle', N'Normalization is the practice of storing data in a flat structure, similar to a database table, rather than deeply nested structures. This prevents data duplication and simplifies the logic required to update specific items in the state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bddd97f2-a1bc-4344-aa06-6b66add2a173', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you explain the concept of ''refactoring time'' to a stakeholder who wants a new feature built quickly?', N'Junior', N'I explain that refactoring is an investment in the long-term health of the software, which prevents future bugs and makes it easier to add features later. If we skip it now, the cost of building future features will increase, eventually slowing down the entire project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69b55648-de31-426a-8629-6b674b6dbd2d', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'When should you avoid using Fiber?', N'Middle', N'You might avoid Fiber if your application requires strict compatibility with the standard Go ''net/http'' library or if the project needs to run in an environment where the specific optimizations of Fasthttp provide no measurable benefit. In cases where extreme simplicity and standard compliance are prioritized over performance, the standard library is a better choice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06d55e5b-f2ec-49b0-b6dd-6b69a808b793', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why is the build step important in Svelte?', N'Intern', N'The build step is essential because it is where the transformation from declarative Svelte syntax to optimized imperative JavaScript occurs. Without this compilation phase, Svelte would not be able to achieve its performance goals or scope CSS correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76b26239-8afe-4d6e-9f4c-6b6d64108159', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the role of the ''Dispatch'' function and why must it be synchronous in standard Redux?', N'Senior', N'The dispatch function is the only way to trigger a state change, and it must be synchronous to ensure that the state transition process is deterministic and traceable. By enforcing synchronous execution, Redux ensures that the order of actions is strictly maintained, which is essential for accurate state debugging and predictable middleware behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
