INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7afed5f-fec4-45fe-9c45-6b72560470fa', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach debugging a distributed system where a request fails intermittently across multiple microservices?', N'Middle', N'I would start by implementing distributed tracing to visualize the request lifecycle across service boundaries. By analyzing trace IDs and logs for latency spikes or error codes in specific spans, I can isolate the failing node or network segment. This approach helps determine if the issue is a race condition, a timeout, or a configuration mismatch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60e11967-2adf-4c85-9094-6b72e30c37a6', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the purpose of the Event Loop in Dart, and how does it handle asynchronous tasks?', N'Middle', N'The Event Loop is the mechanism that executes code, collects events, and schedules tasks. It manages two queues: the microtask queue for short, high-priority actions, and the event queue for I/O, timers, and gesture events, ensuring non-blocking execution in a single-threaded environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d598e48-8a9d-48ce-b8ae-6b784d0d7efd', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is an ACID property in the context of databases?', N'Fresher', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably and maintain data integrity even in the event of errors or system failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd663a2b6-5517-4376-aad3-6b7b4356e04b', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between a function declaration and a function definition?', N'Fresher', N'A declaration informs the compiler about the function name, return type, and parameters without providing the body. A definition provides the actual implementation or logic of the function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d06a424-c236-43e8-bd8c-6b7b5b57a76a', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'If you need to store configuration settings that change rarely but are read frequently, would you choose a relational database or a flat file?', N'Junior', N'A flat file or a simple key-value store is often better for infrequent writes and high-frequency reads. It reduces the overhead of database connections and complex query execution, making the configuration loading faster and more reliable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
