INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc1dfd49-32b7-4886-8241-6b85070b3d1b', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does rate limiting protect a system from cascading failures?', N'Senior', N'Rate limiting restricts the number of requests a user or service can perform within a specific timeframe, preventing individual clients from monopolizing system resources. This prevents DoS scenarios, whether malicious or accidental, ensuring that available capacity remains distributed among all users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6ef4e45-9ef8-42b0-acac-6b88ace5890f', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What does ''compile-time'' mean in the context of Micronaut''s speed?', N'Fresher', N'It means the framework does the heavy lifting, such as generating proxy classes and dependency resolution, when you build the code. Because this work is already finished before the app runs, the application starts much faster than frameworks that do this work during startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6561786e-d088-4f75-aac9-6b89a4330b82', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between ''break'' and ''continue''?', N'Junior', N'The ''break'' statement terminates the current loop entirely and moves control to the next part of the code. The ''continue'' statement skips the current iteration of the loop and moves immediately to the next iteration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4deedbf8-a7cd-488c-a6cc-6b8b136a77f9', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between app.run() and using the flask CLI?', N'Junior', N'Calling app.run() directly in the script is an older approach used for quick testing, while the flask CLI is the modern, recommended way to run applications. The CLI provides a more robust environment and better integration with development tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05a3d794-ecde-4775-bba7-6b8d97da3301', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is Object.freeze() for?', N'Intern', N'Object.freeze() is used to make an object immutable. Once an object is frozen, you cannot add, remove, or modify its properties. This is useful for creating constants or ensuring that an object remains unchanged throughout the program. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c08e6a05-d962-49e0-888c-6b8e15ece5d2', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'When would you prefer an LFU (Least Frequently Used) eviction policy over LRU?', N'Middle', N'LFU is preferred when access patterns are static and you want to prioritize items that are accessed most often regardless of when they were last used. LRU is better suited for dynamic workloads where the most recent access is a strong predictor of future interest.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30baf048-eb39-4f8c-beba-6b8ec164dcd7', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the difference between vertical and horizontal scaling.', N'Middle', N'Vertical scaling increases the capacity of a single machine, such as adding more CPU or RAM, which has a physical limit. Horizontal scaling adds more machines to the pool, allowing for virtually unlimited growth and improved fault tolerance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd1864b3-6bf6-459e-9bcd-6b8fe84a2b61', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why is ''Ecto'' considered a separate entity from Phoenix rather than a traditional ORM?', N'Middle', N'Ecto is designed as a database wrapper and query composer rather than a strict ORM. It separates the concepts of data mapping, validation, and database querying, which provides more explicit control over performance and database constraints compared to traditional ORMs that often hide SQL complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ec6bd58-c97a-4416-bd6f-6b916ff2cd5e', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask handle sessions?', N'Fresher', N'Flask uses client-side sessions by default, where session data is stored in a signed cookie on the user''s browser. This allows the server to remember user information across multiple requests without storing it in a database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26b3dd23-1831-4a44-a885-6b92ae23d083', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How can you optimize Rails application memory usage when processing large datasets?', N'Senior', N'Use batch processing methods like find_each or find_in_batches to load records into memory in smaller segments. Avoid loading full ActiveRecord objects when only specific attributes are needed by using pluck or select to reduce object allocation overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef50c070-6230-4b4a-9219-6b964dd1de37', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is ''Copy-on-Write'' optimization in Swift?', N'Middle', N'Copy-on-Write is a mechanism used by collection types like Arrays and Dictionaries to improve performance. It ensures that data is only copied when it is actually modified, rather than when it is assigned or passed, minimizing unnecessary memory allocation and CPU cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
