INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d11a764-c277-445a-8f96-6b9b6b56d5ec', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Explain the significance of the ''Vary'' header in HTTP caching for APIs.', N'Senior', N'The Vary header informs caches that the response depends on specific request headers, such as Accept-Encoding or Authorization. Without proper Vary headers, a cache might serve the wrong representation of a resource to different clients, leading to security vulnerabilities or data inconsistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
