INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'913430d8-939b-4969-a926-6b9e9bb787e8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are workers in JavaScript used for?', N'Intern', N'Workers in JavaScript are background threads that allow you to run scripts in parallel with the main execution thread, without blocking or interfering with the user interface. Their key features include: - Parallel processing: Workers run in a separate thread from the main thread, allowing your web page to remain responsive to user interactions while the worker performs its tasks. It''s useful for moving CPU-intensive work off the main thread and freeing you from JavaScript''s single-threaded nature. - Communication: Uses postMessage() and onmessage/''message'' event for messaging. - Access to web APIs: Workers have access to various Web APIs, including fetch(), IndexedDB, and Web Storage, allowing them to perform tasks like data fetching and persisting data independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfa11c13-5534-4067-9864-6ba09b58ca49', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS manage state in a stateless HTTP environment?', N'Senior', N'AdonisJS leverages session drivers, such as Redis or database-backed storage, to persist state across stateless requests. By abstracting the session driver, it allows architects to scale horizontally by offloading session persistence to external high-availability stores, ensuring session consistency across multiple application nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe3d45fe-0e65-43cb-af03-6ba1ae678908', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro support different hosting platforms?', N'Middle', N'Astro uses ''Adapters'' to bridge the gap between its build output and specific hosting providers like Vercel, Netlify, or Node.js servers. These adapters ensure that the site is optimized for the specific runtime environment of the host.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72f2991c-3e55-43c6-8ee8-6ba245c7aa88', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between micro-optimizing a single function and improving the overall system architecture?', N'Junior', N'Micro-optimizations can provide minor performance gains in specific areas but often add complexity and reduce code readability. Improving architecture usually yields higher overall system performance and maintainability, making it the better long-term investment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
