INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5aa0696-bf62-47b1-b57a-6ba831ff1eda', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the purpose of the ''weakref'' module in Python, and when is it necessary?', N'Senior', N'The ''weakref'' module allows the creation of references that do not increase an object''s reference count. This is essential for implementing caches or observer patterns where you want to reference an object without preventing it from being garbage collected when no strong references remain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2ecb4be-b74d-4163-b60f-6bacd1183acb', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are the architectural trade-offs of using Phoenix Channels for real-time communication versus standard HTTP long-polling?', N'Senior', N'Channels maintain long-lived stateful connections over WebSockets, which eliminates the overhead of repeated HTTP headers and handshake procedures per request. While this drastically reduces latency and server load for real-time updates, it requires more complex state management and resource monitoring on the server to handle connection lifecycle and message buffering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdd3d782-371c-4d2b-8e40-6bb1910ed858', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What happens if you forget to free dynamically allocated memory?', N'Junior', N'Forgetting to free dynamically allocated memory results in a memory leak. This means the allocated memory remains occupied and cannot be reused by the program for the duration of its execution. Over time, this can cause a program to consume excessive system memory, potentially leading to performance degradation or crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93b63fd7-40b3-459b-b6ed-6bb19f27a8e3', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the function of the ''oplog'' in a MongoDB replica set?', N'Middle', N'The oplog is a capped collection that stores a rolling record of all operations that modify data in the database. Secondary members of a replica set pull these operations from the oplog and apply them to their own datasets to maintain eventual consistency with the primary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b1d2861-f047-4b02-aaf8-6bb201f76ca0', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Discuss the implications of using Spring''s Open Session in View (OSIV) pattern in a high-concurrency microservices architecture.', N'Senior', N'OSIV keeps the database connection open during the entire request-response cycle to facilitate lazy loading of entities in the view layer. In high-concurrency environments, this pattern leads to connection pool exhaustion and increased latency, making it unsuitable for architectures that require high throughput and optimized database utilization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a157544a-9684-48f9-b90b-6bb8501241bb', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between prioritizing system reliability versus feature richness?', N'Intern', N'Reliability is generally foundational; a feature-rich product is useless if it is unstable. I would prioritize reliability first to build a solid base, then incrementally add features to ensure the system remains dependable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'634ed401-8f23-41b3-a81f-6bb8fe447670', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How is the GOPATH environment variable used?', N'Fresher', N'In Go, the GOPATH environmental variable is crucial, serving as the root for both package management and your code repository, and separating your development area from your installed packages. Workflow without Modules (Go 1.10 and before) 1. Source Files Location: - Your Go source files likely reside in the bin, pkg, and src directories inside your GOPATH directory. - Inside the src directory, you generally organize your code using your module path. 2. Installing Packages: - The go get command is responsible for fetching and installing packages. For example, running go get from anywhere in your workspace installs the package to the global package cache. 3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5f35d16-5817-44cb-ad90-6bb9e8fbd84c', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the function of an Abstract Class versus an Interface?', N'Middle', N'An abstract class is used to share code among closely related classes and supports state through instance variables. An interface defines a contract for behavior that unrelated classes can implement, focusing on what an object can do rather than what it is. Java allows for multiple interface implementation, whereas a class can only extend one abstract class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'207179b8-d505-47b8-a5b5-6bbff22f64dd', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of the TypeScript compiler?', N'Fresher', N'The TypeScript compiler, often called tsc, is responsible for transpiling TypeScript code into standard JavaScript. Since browsers and Node.js environments do not understand TypeScript directly, the compiler strips away the type annotations and converts modern syntax into a version of JavaScript that can run in any environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9779452f-e482-4abe-9f0e-6bc010394621', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What does ''Ember Object'' refer to?', N'Intern', N'Ember Object is the base class for most objects in the framework. It provides features like computed properties, observers, and a robust system for managing object properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acea929a-3107-4742-857e-6bc02d226906', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does the ''use'' keyword affect namespace resolution in PHP?', N'Middle', N'The ''use'' keyword imports classes, interfaces, or functions into the current file scope, allowing them to be referenced by their short names instead of their fully qualified names. It is a compile-time alias mechanism and does not affect the actual loading of files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a82dd21a-2bdd-4195-9e05-6bc1607b724b', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the primary difference between horizontal and vertical scaling, and when should each be preferred?', N'Middle', N'Vertical scaling involves increasing the power of an existing machine, while horizontal scaling adds more machines to a resource pool. Vertical scaling is simpler to implement but has a hard physical ceiling, making horizontal scaling the preferred choice for distributed systems requiring high availability and elastic growth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da37a01c-4dd0-4eb0-a9d4-6bc1b599db1e', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does the size of the jQuery library affect the Critical Rendering Path (CRP)?', N'Senior', N'Loading the jQuery library adds a significant block to the critical rendering path, especially on low-bandwidth mobile devices. Because it is a large file that must be parsed and executed before any DOM manipulation can occur, it increases the Time to Interactive (TTI) without providing benefits that cannot be achieved with smaller, native-only code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f554d36-5cfd-4bc7-a4f3-6bc576ef2a81', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the purpose of x-html?', N'Junior', N'The x-html directive allows you to set the inner HTML of an element based on a data property. This is useful for rendering content that contains HTML tags, but it should be used carefully to avoid cross-site scripting vulnerabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37aa32b8-ae08-476a-b406-6bc5b0689a9b', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis prevent data loss during a power failure when using AOF?', N'Senior', N'Redis allows configuring the `fsync` policy, which determines how often the AOF buffer is flushed to physical disk. Setting `fsync` to `everysec` provides a balance between performance and durability, ensuring that at most one second of data is lost in the event of a system crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cd3f75d-c643-4ec6-9c3a-6bca91aa0303', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of the scope resolution operator (::)?', N'Junior', N'The scope resolution operator allows access to static members, constants, and overridden properties or methods of a class. It is used when you need to access these elements without instantiating an object of that class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bea916a5-7413-46c0-8bd1-6bcb469303ee', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the difference between a Django ModelForm and a regular Form?', N'Junior', N'A Form is used to handle data input and validation that is not necessarily tied to a database model. A ModelForm is a subclass that automatically generates form fields based on the fields defined in a specific Django model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a3e90b6-62c9-404b-9d13-6bd2e50cd28a', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript handle type erasure in the context of runtime reflection, and what architectural patterns compensate for this limitation?', N'Senior', N'TypeScript removes all type annotations during compilation, meaning types do not exist at runtime. Architects compensate for this by implementing manual runtime validation schemas, using decorators for metadata storage, or leveraging libraries that generate runtime validators from static interfaces to bridge the gap between static analysis and runtime data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07505108-3785-4d8f-b716-6bd60cf396d0', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a system, why do you prioritize loose coupling?', N'Middle', N'Loose coupling ensures that changes to one service do not force changes in others, allowing teams to deploy and evolve components independently. It improves the system''s overall maintainability and reduces the risk of ripple-effect bugs during updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ae3b109-6c52-4b87-b43f-6bdabafaed99', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the mapping rules between Angular component and custom element?', N'Intern', N'The Component properties and logic maps directly into HTML attributes and the browser''s event system. Let us describe them in two steps, 1. The createCustomElement() API parses the component input properties with corresponding attributes for the custom element. For example, component @Input(''myInputProp'') converted as custom element attribute my-input-prop. 2. The Component outputs are dispatched as HTML Custom Events, with the name of the custom event matching the output name. For example, component @Output() valueChanged = new EventEmitter() converted as custom element with dispatch event as "valueChanged".', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e0e8bac-aec9-442a-99b0-6bde9d081489', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the zero value of a variable in Go?', N'Intern', N'In Go, variables automatically initialize to their zero values if not explicitly set. Zero values provide sensible defaults, especially when dealing with dynamically allocated variables like pointers. Zero Value Definitions - Uninitialized Variables: Variables declared but left unassigned will take on their zero values. - Slices and Maps: Their zero values are nil, indicating that no underlying data is assigned. - Pointers: Their zero value is also nil. - Interfaces: Their state is nil unless initialized to a specific type with a non-nil value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eba4a4d8-a28d-4e65-853b-6be4f6b32823', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the ''app.UseRouting()'' and ''app.UseEndpoints()'' methods?', N'Junior', N'UseRouting marks the point in the pipeline where the request path is matched to an endpoint, while UseEndpoints executes the logic associated with that matched endpoint. Separating these allows for other middleware to run between the matching and execution phases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1a7b121-ab18-4170-ae0b-6be5e1c003cb', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does ASP.NET Core handle cross-origin requests?', N'Fresher', N'ASP.NET Core uses Cross-Origin Resource Sharing (CORS) policies to manage how browsers interact with resources on different domains. It allows developers to explicitly permit or restrict requests from specific origins through middleware configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd379b872-6a72-4cfe-866b-6be6a0b271aa', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is dependency injection?', N'Junior', N'Dependency injection is a design pattern where an object''s dependencies are provided to it rather than the object creating them itself. This promotes loose coupling, easier testing, and better maintainability by decoupling class creation from class usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53c362e4-bc87-4272-bd52-6be89c81eb9a', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does a message queue facilitate asynchronous logging or auditing?', N'Middle', N'By pushing log events into a queue, the application can offload the I/O-intensive task of writing to storage. A separate worker process can then consume these messages and write them to a database or data lake without impacting the performance of the main application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ba8ff17-8590-4bd0-a72e-6be94daf2f09', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Why might you choose a NoSQL database over a relational database for a highly scalable system?', N'Middle', N'NoSQL databases are often designed for horizontal scalability and schema flexibility, making them easier to distribute across clusters. They are preferred when the data model is not strictly relational or when high write throughput is required that exceeds the capabilities of a single relational instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04fa8be1-00f0-4831-8d57-6bea0c6c6e5a', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'In a distributed system, how do you handle partial failures to ensure system reliability?', N'Middle', N'I implement patterns like circuit breakers to prevent cascading failures and retries with exponential backoff for transient issues. Additionally, I ensure the system is designed for graceful degradation, allowing it to provide limited functionality rather than failing completely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a8bab4d-088d-4e64-b162-6bf01f783759', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are the performance implications of using ''dynamic'' in Dart?', N'Middle', N'Using ''dynamic'' tells the compiler to disable static type checking and perform checks at runtime. This leads to slower performance because the runtime must inspect the object''s type before every operation, and it also increases the risk of runtime type errors that the compiler would have otherwise caught.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'404f66d6-69eb-4f61-aad4-6bf20aa95982', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is Provisioned capacity mode?', N'Intern', N'Provisioned capacity mode requires you to specify the number of reads and writes per second that you expect your application to require. You pay for the throughput you provision, which is cost-effective for predictable, steady traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
