INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e0410a5-78cb-4340-85bd-6bf34d9a2cef', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the significance of the ''Application'' callback in a Phoenix project?', N'Middle', N'The application callback is defined in the project''s supervision tree and acts as the entry point for starting the application. It ensures that all necessary services, such as database connections and PubSub, are initialized in the correct order when the node starts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c664bc1-7f05-4990-b2c1-6bf46073879f', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the primary purpose of a web framework like Echo in backend development?', N'Intern', N'Echo is a web framework designed to simplify the process of building web applications and APIs. It provides tools for routing requests, handling middleware, and managing HTTP responses, which allows developers to focus on business logic rather than low-level network programming.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4eed19d-035b-40cf-867f-6bf547010738', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is meant by immutability in Scala?', N'Intern', N'Immutability means that an object''s state cannot be modified after it is created. This simplifies concurrency and helps prevent bugs caused by unexpected state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'269fbac5-0570-4f33-86d8-6bf6a8d305bd', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are nesting templates', N'Intern', N'The nesting template is a feature supported within template literals syntax to allow inner backticks inside a placeholder ${ } within the template. For example, the below nesting template is used to display the icons based on user permissions whereas outer template checks for platform type, You can write the above use case without nesting template features as well. However, the nesting template feature is more compact and readable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04929fbf-1c9e-4774-bf36-6bf765b4d43d', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does an API Gateway improve the security of a microservices architecture?', N'Middle', N'An API Gateway acts as a single entry point that centralizes security functions such as authentication, rate limiting, and SSL termination. By offloading these concerns, it prevents individual internal services from needing to implement security logic, reducing the attack surface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6ca4cf2-7d05-45cf-827d-6bf784cbbac7', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is Tailwind CSS?', N'Intern', N'Tailwind CSS is a utility-first CSS framework that provides low-level utility classes. Instead of writing custom CSS files, you build designs directly in your markup by combining these pre-defined classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5dcf2a18-63fe-4331-828e-6bfacc3a9d62', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between ''AddMvc'' and ''AddControllers'' in ASP.NET Core?', N'Middle', N'AddMvc adds all services related to both Controllers and Views/Razor Pages, which is larger and more feature-heavy. AddControllers is a more lightweight approach intended for Web API applications that do not require view-rendering capabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ce108d8-b0a5-4297-91a2-6bfc573e4b7d', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the purpose of ACID properties?', N'Intern', N'ACID ensures transactions are processed reliably. Without these properties, concurrent transactions could corrupt data (dirty reads, lost updates, phantom reads).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54a9231e-5632-4be3-811b-6bff828217d2', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'In a microservices architecture, why might you prefer Echo over a heavier framework like standard net/http or more opinionated frameworks?', N'Senior', N'Echo offers a balance between performance and developer productivity by providing essential features like routing, binding, and middleware without the bloat of a full-stack framework. It is lightweight enough to maintain low latency, which is critical when chaining multiple network calls across microservices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'976738b8-0dd2-4db2-aa46-6c0298680469', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What factors influence your decision on how to handle database migrations in a production environment?', N'Middle', N'I ensure that migrations are backward compatible so the application can function during the transition. I prefer additive changes, such as adding new columns rather than renaming existing ones, and I use feature flags to decouple schema updates from code deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8f9608c-5b42-4327-bf85-6c0599cc7151', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle environmental variables?', N'Fresher', N'AdonisJS uses an environment configuration file and a specific validator to manage environment variables. This ensures that the application has all necessary settings, like database credentials or API keys, before the server starts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7ae4e07-a7fa-4e4d-9664-6c05a5c52514', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite''s development server leverage native ES modules compared to traditional bundlers?', N'Middle', N'Vite serves source code over native ESM, allowing the browser to handle module resolution during development. This eliminates the need for bundling every file upon change, resulting in near-instant server start times regardless of application size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21911ca4-7980-4108-bcf4-6c069833b35f', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Why are functional interfaces important in Java 8+?', N'Middle', N'Functional interfaces define a single abstract method, allowing them to be implemented using lambda expressions or method references. They are the foundation of functional programming in Java, enabling concise, readable code for tasks like filtering, mapping, and event handling. They essentially treat code as data, making the language more versatile and modern.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ef40dd8-1f60-40ec-a4ae-6c0a4265f839', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'When would you implement API caching, and where should it occur?', N'Middle', N'Caching should be used for frequently accessed, slow-changing data to reduce backend load and response time. It can occur at the client side, in intermediate proxies, or at the CDN level to serve content closer to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d965cca-efe9-4e86-be57-6c1203f0807d', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why does Rust distinguish between ''Send'' and ''Sync'' traits, and how do they relate to thread safety?', N'Middle', N'The Send trait indicates that ownership of a type can be safely transferred between threads, while the Sync trait indicates that it is safe to share a reference to a type between multiple threads. These marker traits allow the compiler to prevent data races by ensuring that non-thread-safe types cannot be accidentally moved or shared across thread boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9d451d2-6bb3-4d12-9d33-6c1285e1f9f6', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What happens if you don''t specify a return type for a function?', N'Junior', N'If you don''t explicitly specify a return type, TypeScript will attempt to infer it based on the return statements within the function. If the function has multiple return paths with different types, TypeScript will infer a union type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ada98d9-e70f-4a5b-b505-6c12e473e630', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does the Python iterator protocol facilitate memory-efficient stream processing?', N'Senior', N'The iterator protocol relies on the __next__ method to yield values on demand, eliminating the need to load entire datasets into memory. By decoupling the generation of data from its consumption, it enables the processing of infinite or massive sequences with constant memory complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fda36fc4-ad1c-4e39-b411-6c1417b2d447', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi facilitate the implementation of RESTful design patterns?', N'Middle', N'Chi provides a clean and readable way to map HTTP methods (GET, POST, PUT, DELETE) to specific handlers. Its support for URL parameters and sub-routing makes it easy to structure resources hierarchically, which is a core tenet of REST.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd91a8ab8-a4cc-4e14-95b2-6c1949b50d14', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What role does logging play in troubleshooting a live system?', N'Junior', N'Logging provides an audit trail of application behavior, which is essential for reconstructing the sequence of events that led to a failure. Without logs, it is nearly impossible to diagnose intermittent issues or understand the internal state of the system at the time of an error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f3029b4-c1f7-4d04-900d-6c1a15b71f5f', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How do C macros differ from inline functions in terms of type safety and debugging?', N'Senior', N'Macros perform textual replacement without type checking, which can lead to subtle bugs if arguments have unexpected side effects or types. Inline functions, by contrast, are parsed by the compiler, allowing for standard type checking and generating better debugging information. While macros offer more flexibility for code generation, inline functions are preferred in modern C for their safety and better integration with tooling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'168afc7a-2a4d-4a9a-9f60-6c1adff4853d', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle static file serving, and why is this efficient?', N'Middle', N'Echo provides a dedicated file system middleware and router methods that leverage the standard library''s http.ServeFile functionality. By using these abstractions, Echo efficiently handles mime-type detection and caching headers while maintaining compatibility with the underlying HTTP server''s optimized file descriptors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b88881ce-e1f1-433d-bc5d-6c1e2268b377', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you communicate the ''hidden'' costs of technical debt to non-technical stakeholders?', N'Senior', N'I translate the technical debt into business outcomes, such as increased time-to-market for new features or higher incident rates during peak traffic. I present it as an ''interest payment'' on a loan that prevents the team from investing in growth-oriented work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70189f8d-c11f-4813-8ed1-6c1fb889a271', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the trade-offs of using DynamoDB Streams for change data capture?', N'Senior', N'Streams provide a reliable, ordered sequence of modifications to items, enabling integration with Lambda or external systems for downstream processing. The trade-off is the added architectural complexity and potential for latency in event-driven workflows, as the stream is near-real-time rather than instantaneous.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f9f23c2-7b05-4483-b3fa-6c20ba5cfb90', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the type of below function?', N'Intern', N'- 1: Pure function - 2: Impure function Answer Answer: 2 Eventhough the above function returns the same result for the same arguments(input) that are passed in the function, the console.log() statement causes a function to have side effects because it affects the state of an external code. i.e, the console object''s state and depends on it to perform the job. Hence, the above function considered as impure function. ---', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19fda76a-7bdf-487d-8b66-6c2118f0eb40', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the difference between a primary and secondary node in a replica set?', N'Junior', N'The primary node receives all write operations and records all changes to its oplog. Secondary nodes replicate the primary''s data and can be used for read operations, but they cannot accept write operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8792fbd-7fc9-4e3e-abc5-6c2133fe972f', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle service discovery?', N'Intern', N'Micronaut provides built-in support for service discovery, allowing microservices to locate each other dynamically. It supports various discovery mechanisms such as Consul, Eureka, and Kubernetes, which helps in scaling and managing distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd9b4476-f129-49e1-ab15-6c2c6cdd21b7', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle background tasks?', N'Junior', N'FastAPI provides a BackgroundTasks class that allows you to queue functions to run after returning a response to the client. This is useful for time-consuming operations like sending emails or processing logs that do not need to block the immediate API response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf29f2da-ea5c-4229-bd7b-6c2eb8f0b2bd', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery''s architecture impact the global namespace, and why is this problematic for modern modular applications?', N'Senior', N'jQuery attaches itself to the global window object, which can lead to conflicts if multiple versions are loaded or if other libraries use the same aliases. In modern modular environments, this pollutes the global scope and hinders tree-shaking, as the entire library is bundled regardless of actual usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cff872d2-0c3c-4400-91f4-6c2ee21ecbb6', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are source maps in Webpack?', N'Intern', N'Source maps are files that map your bundled, minified code back to your original source files. They are essential for debugging, as they allow developers to see the original code in the browser''s developer tools instead of the compiled version.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1af78650-16ff-46fc-b16e-6c32548ed1ad', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does the ''useAsyncData'' composable handle data fetching, and why is it preferred over ''onMounted'' for initial loads?', N'Senior', N'useAsyncData manages the lifecycle of data fetching during SSR, ensuring the fetched state is serialized and transferred to the client to prevent hydration mismatches. Using onMounted for initial data would result in a waterfall effect, where the client must wait for the component to mount before triggering a fetch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7a67514-62f0-410d-8a97-6c3345fae149', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How events are different in React?', N'Fresher', N'Handling events in React elements has some syntactic differences: 1. React event handlers are named using camelCase, rather than lowercase. 2. With JSX you pass a function as the event handler, rather than a string.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b45ca90f-5ba9-4044-8c3c-6c351e326367', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of ''onMount''?', N'Junior', N'OnMount is a lifecycle primitive that runs exactly once after the component has been rendered and added to the DOM for the first time. It is the ideal place to perform initial setup tasks like fetching data or initializing third-party libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'343c41c5-5e81-443a-a96c-6c35e4396bac', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle context compared to the standard library''s net/http package?', N'Middle', N'Echo introduces a custom Context interface that extends the standard http.ResponseWriter and *http.Request. This abstraction provides convenient helper methods for binding request data, rendering responses, and managing the request lifecycle, significantly reducing boilerplate code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80f4348a-ccc0-44b5-a200-6c381a51b8b7', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'When should you choose to use Redux over React Context?', N'Junior', N'Redux is generally better for complex applications with large amounts of global state, advanced debugging requirements, or frequent state updates. React Context is often sufficient for simple data sharing like themes or user preferences where global state management complexity is not needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14839f79-1938-409f-ac3f-6c3a92db53f1', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What does ''lazy loading'' mean in the context of R packages?', N'Junior', N'Lazy loading is a mechanism where objects in a package are only loaded into memory when they are explicitly called. This helps keep the R session lightweight by not consuming memory for unused package components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
