INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c2ff0ec-ff13-42fd-a42e-6c435d4279a5', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'If an API is slow, what is the first thing you would investigate?', N'Fresher', N'I would first investigate the database queries to see if they are missing indexes or performing inefficient joins. If the database is fine, I would look at the network latency, the processing time of the server-side logic, and whether any external dependencies are causing delays.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
