INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd363c250-a225-4e5f-a8dc-6c5eafc988bb', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does the Ember build pipeline (Ember CLI) differ from standard Webpack-based setups?', N'Senior', N'Ember CLI is built on top of Broccoli, which uses a directed acyclic graph to model the build process. This allows for superior caching of intermediate build steps and efficient incremental rebuilds, as only the specific nodes in the graph affected by a file change need to be reprocessed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57213b77-5acc-40ab-b777-6c5f0dba47ed', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How does load balancing impact system performance?', N'Middle', N'Load balancers distribute incoming network traffic across multiple servers to ensure no single server becomes a bottleneck. This increases the responsiveness of the application and ensures high availability by routing traffic away from failed nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
