INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1be7b1e6-b8b9-4edc-8f73-6c66ebffa5b7', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does the ''TracePoint'' API function and what are the performance impacts of its use?', N'Senior', N'TracePoint allows for hooks into various events within the Ruby VM, such as method calls and class definitions. Because it monitors the internal state of the interpreter, it introduces significant performance degradation and should generally be reserved for debugging, profiling, or introspection tools rather than application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e20586df-930a-4318-bbd0-6c6a63fed5d2', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the difference between local (in-memory) caching and distributed caching?', N'Middle', N'Local caching resides on the application server''s RAM, providing extremely low latency but limited capacity and lack of data synchronization across multiple nodes. Distributed caching runs on a separate cluster, allowing for shared state and high scalability across many application instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35f25ada-5002-492b-a884-6c6b215b4158', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the impact of using ''default_scope'' in Rails, and why is it often discouraged?', N'Senior', N'Default scopes are automatically applied to every query for a model, which makes them difficult to override and prone to unexpected side effects in complex queries. They are often discouraged because they hide query behavior, making debugging and maintenance significantly harder as the codebase grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
