INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd906159-3734-4dd2-8948-6c9814b41d65', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How bootstrap class loader works in java?', N'Fresher', N'Bootstrap ClassLoader is repsonsible for loading standard JDK classs files from rt.jar and it is parent of all class loaders in java. There are three types of built-in ClassLoader in Java: 1. Bootstrap Class Loader: It loads JDK internal classes, typically loads rt.jar and other core classes for example java.lang.* package classes 2. Extensions Class Loader: It loads classes from the JDK extensions directory, usually $JAVA_HOME/lib/ext directory. 3. System Class Loader: It loads classes from the current classpath that can be set while invoking a program using -cp or -classpath command line options.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f61a126e-4f10-4108-9906-6c99239313b2', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is ''Shadowing'' (or Dark Launching) in the context of testing?', N'Middle', N'Shadowing involves routing a copy of live production traffic to a new service version without returning the response to the user. This allows developers to test the performance and reliability of new code against real-world traffic patterns without impacting the actual user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49996a1d-c35b-43e4-a5b7-6c9d0bc4c28d', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is meant by ''persistence'' in the context of Redis?', N'Intern', N'Persistence refers to the ability to save data from the volatile RAM to non-volatile disk storage. This ensures that data is not lost if the Redis server restarts or loses power.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
