INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6ed787b-c8dc-4e89-86a4-6ca4e8fc828f', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does a database lock do during a transaction?', N'Junior', N'A lock is a mechanism that restricts access to a resource, such as a row or table, to prevent concurrent transactions from modifying the same data simultaneously. This helps maintain data integrity and isolation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
