INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'108b0756-ddfd-4c6b-9d5e-6ca843aa6816', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is the const keyword useful for pointer parameters?', N'Middle', N'Using const in a pointer parameter acts as a contract, informing the caller that the function will not modify the data pointed to by that pointer. This improves code safety and documentation, and it allows the function to accept pointers to constant data that would otherwise be rejected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c87cc753-8d0e-461b-9b92-6caa12cb349d', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why is it important to monitor shared buffers usage?', N'Middle', N'Shared buffers represent the memory area where PostgreSQL caches data pages. If the buffer cache is too small, the database will frequently rely on disk I/O, which is significantly slower; if it is too large, it may starve the operating system of memory for other tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
