INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81c4d160-655e-45dd-ac7a-6cb5d872aba3', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you maintain data consistency across microservices without relying on distributed transactions like 2PC?', N'Senior', N'Implement the Saga pattern, which manages distributed transactions as a sequence of local transactions. Each local transaction updates the database and publishes an event or message to trigger the next transaction, using compensating transactions to undo changes if a step fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
