INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb832eca-689f-4049-a4b8-6cb7b7eb7acf', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit manage the ''waterfall'' problem during server-side rendering?', N'Senior', N'SvelteKit mitigates waterfalls by allowing multiple data dependencies to be fetched in parallel within the ''load'' function. By aggregating data requirements before the component tree renders, it avoids the sequential request patterns often found in client-side-only architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
