INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'126da83d-3a24-4e99-aadd-6cd0ff572805', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R''s copy-on-modify mechanism affect memory management?', N'Middle', N'R objects are generally immutable by default, meaning that when you modify an object, R creates a new copy in memory. This ensures that functions do not have side effects on original data, though it can lead to significant memory overhead when working with large datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90918f42-9c33-489f-9ab5-6cd2694f2709', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the significance of the ''revalidatePath'' function?', N'Middle', N'RevalidatePath is used to purge the Next.js cache for a specific route or path. It is often triggered after a server action updates data, ensuring that the next user request receives the latest version of the content instead of the cached stale version.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4692f7c8-4257-49c8-82c0-6cd30507f453', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web manage connection pooling for database interactions?', N'Senior', N'Actix-web uses extractors to share a thread-safe connection pool instance across various workers. Since the pool itself handles thread-safe request queuing, the application can perform concurrent database queries without manual locking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c2a0bf2-dfbc-437a-ae48-6cd53d5960d0', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is a Module''s ''providers'' array?', N'Intern', N'The providers array in a module definition lists the services or classes that will be available for injection within that module. Any service added here can be used by controllers or other services defined in the same module.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43152fe5-6636-4482-bb18-6cd72bfad583', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the benefit of Tailwind’s constraints-based design system?', N'Junior', N'It prevents developers from using arbitrary spacing or colors that fall outside the agreed-upon design language. By limiting options to a predefined set of values, the interface remains consistent across different pages and components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1f3838b-a1bd-4481-a8a1-6cd938372705', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the purpose of the ''Pub/Sub'' feature in Redis?', N'Intern', N'Pub/Sub stands for Publish and Subscribe, which is a messaging paradigm. It allows different parts of an application to communicate by sending messages to channels without needing to know who the subscribers are.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35282c6d-7d9b-4796-9f96-6cda4de48157', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the Zeitwerk autoloader, and how does it differ from the legacy eager loading mechanism?', N'Senior', N'Zeitwerk provides a thread-safe, predictable approach to constant resolution by mapping file paths to class names based on standard conventions. Unlike the legacy mechanism that relied on constant missing hooks, Zeitwerk avoids potential race conditions and provides faster boot times through more efficient file structure analysis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbdac576-b221-4e3c-ab64-6cdc9584ec23', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the main advantage of using Ember''s built-in testing tools?', N'Intern', N'Ember provides a robust testing suite that includes support for unit, integration, and acceptance tests. Using these built-in tools ensures that code is reliable, bugs are caught early, and the application remains stable as new features are added.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4b58869-d449-4e76-bb92-6cdfefe94bd8', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is session management in Django?', N'Fresher', N'Session management allows you to store and retrieve arbitrary data on a per-site-visitor basis. It uses a cookie on the client side to keep track of the session, linking the user to data stored on the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7e1d20c-d12e-43ea-a1ab-6ce0807a68ef', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the role of the database administrator?', N'Intern', N'A database administrator is responsible for the performance, integrity, and security of a database. Their duties include planning, development, troubleshooting, and performing regular backups. They ensure that data is accessible to authorized users while maintaining system efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4515e3a0-1339-4d28-8ca6-6ce0ecfea7cf', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between transient and volatile variable in Java?', N'Fresher', N'1. Transient: The transient modifier tells the Java object serialization subsystem to exclude the field when serializing an instance of the class. When the object is then deserialized, the field will be initialized to the default value; i.e. null for a reference type, and zero or false for a primitive type. Example: 2. Volatile: The volatile modifier tells the JVM that writes to the field should always be synchronously flushed to memory, and that reads of the field should always read from memory. This means that fields marked as volatile can be safely accessed and updated in a multi-thread application without using native or standard library-based synchronization. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b457bb0c-477c-4864-8348-6ce284627a94', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you manage the complexity of distributed transactions?', N'Senior', N'I avoid distributed transactions whenever possible by designing systems around the principle of atomicity within a single service boundary. If necessary, I use the Saga pattern with compensating transactions to manage distributed state changes while maintaining eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1a664c0-dcde-4361-9cc5-6ce4555b096b', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the main advantage of the ''next/script'' component?', N'Middle', N'The Script component gives you fine-grained control over when third-party scripts load, such as ''beforeInteractive'', ''afterInteractive'', or ''lazyOnload''. This helps prioritize critical application code and improves the loading performance of the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e30c6769-52a7-4b02-88b7-6ce6dbc6b403', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra handle data storage compared to a traditional relational database?', N'Intern', N'Unlike relational databases that use tables with strict schemas and joins, Cassandra is a wide-column store that uses a partition-based model. It is designed to handle massive amounts of data across multiple data centers by prioritizing write performance and linear scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e9226d8-f31c-4ae9-a9bb-6ce6ffae5340', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are Higher-Order Components?', N'Intern', N'A _higher-order component_ (_HOC_) is a function that takes a component and returns a new enhanced component with additional props, behavior, or data. It’s a design pattern based on React’s compositional nature, allowing you to reuse logic across multiple components without modifying their internals. We consider HOCs pure components because they don’t mutate or copy behavior from the original component—they simply wrap it, enhance it, and pass through the necessary props. The wrapped component remains decoupled and reusable. Let''s take an example of a withAuth higher-order component (HOC) in React. This HOC will check if a user is authenticated and either render the wrapped component if authenticated or redirect (or show a message) if not.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10c5fb2f-b6e1-41e4-9364-6ce8b71a6cd2', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are ACID properties in the context of databases?', N'Intern', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably, maintaining data integrity even in the event of system errors or failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'809d82d3-2c9d-4bd4-b1f8-6cecad300e28', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between get and defineProperty', N'Fresher', N'Both have similar results unless you use classes. If you use get the property will be defined on the prototype of the object whereas using Object.defineProperty() the property will be defined on the instance it is applied to.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b78a8339-a94e-4333-ab01-6ced6ef3669f', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is a typedef?', N'Intern', N'Typedef is a keyword used to create an alias for an existing data type. It makes the code more readable by allowing you to define descriptive names for complex types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f9aed01-7273-4bba-8fc5-6cee1deefa75', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does ''Dead Letter Queue'' (DLQ) contribute to system reliability?', N'Senior', N'A DLQ is a storage area for messages that cannot be processed successfully after multiple attempts. It prevents these messages from blocking the main processing pipeline and allows engineers to inspect, debug, and potentially replay them without impacting the live system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b364a1a0-f4b1-44e6-8e9e-6ceff64ce680', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you manage secrets and configuration in a highly regulated, distributed environment?', N'Senior', N'I would utilize a centralized, encrypted secrets management service that supports dynamic secret rotation and fine-grained access control. Configuration should be externalized from the application code and injected at runtime, with environment-specific overrides managed through a secure, version-controlled repository.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71f22434-7b6c-4c72-b406-6cf0e93a7dc0', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the significance of ''expected behavior'' in bug reports?', N'Fresher', N'The expected behavior provides the baseline for success by defining what the system should do under specific inputs. Without this, it is impossible to objectively determine if the system is failing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7009e160-68aa-4a29-8ff1-6cf472eaeac1', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the impact of network partitioning on a messaging cluster?', N'Middle', N'Network partitions can cause split-brain scenarios where nodes cannot communicate, potentially leading to inconsistencies. Systems must be configured for either high availability (allowing partial writes) or strong consistency (stopping writes if a quorum cannot be reached).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08188c6b-0bb3-4f9c-a1a0-6cf4c32bdfed', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the primary trade-off when deciding between a monolithic application and a microservices approach for a small startup?', N'Fresher', N'A monolith is easier to develop and deploy initially, which is better for speed. Microservices offer better long-term scalability and modularity but introduce significant operational overhead and complexity that a small team may not be ready for.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08748c95-2b71-4aa8-86f0-6cf6e4a5cd92', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does the implementation of the observer pattern in Redux impact memory management in large-scale applications?', N'Senior', N'Redux relies on a subscription model where the store holds references to listener functions. If components are unmounted without unsubscribing from the store, it creates memory leaks by preventing garbage collection of those components, necessitating careful lifecycle management or hooks that auto-unsubscribe.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd93c6df2-3ec9-4d21-bb9c-6cfa1e84bfc9', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How do you handle memory management in Redis?', N'Junior', N'Memory management is handled by configuring the maxmemory limit and choosing an appropriate eviction policy. This ensures that the server does not crash when memory is exhausted and that the most important data remains available.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcdd9b36-df3b-4e98-b555-6cfc3150b36c', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain why you would choose Flask over a ''batteries-included'' framework like Django.', N'Middle', N'Flask is a micro-framework that provides only the essentials, giving developers full control over which libraries to use for database ORM, authentication, and form validation. This is ideal for smaller services, custom architectures, or situations where you want to minimize dependencies and keep the footprint small.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1aaf129e-4447-495b-92d5-6cfd6dbced75', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between Function constructor and function declaration', N'Fresher', N'The functions which are created with Function constructor do not create closures to their creation contexts but they are always created in the global scope. i.e, the function can access its own local variables and global scope variables only. Whereas function declarations can access outer function variables(closures) too. Let''s see this difference with an example, Function Constructor: Function declaration:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9903f9c0-adaf-4029-a977-6cfeb6de0d45', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the purpose of the ''nitro'' engine in Nuxt?', N'Intern', N'Nitro is the high-performance server engine that powers Nuxt. It is responsible for handling server-side rendering, generating static sites, and managing API routes, ensuring the application is fast and lightweight.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3236f974-037d-42dc-8dbc-6d021f398f58', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket manage asynchronous execution?', N'Middle', N'Rocket is built on top of the Tokio runtime, treating handlers as asynchronous tasks by default. This allows the framework to handle a high volume of concurrent connections efficiently by yielding execution during I/O-bound operations without blocking the thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6aad0675-b41c-4281-ac09-6d032e260995', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are the limitations of Dart''s FFI (Foreign Function Interface) when interacting with C libraries?', N'Senior', N'FFI requires managing the bridge between the Dart heap and the C stack, which involves overhead in data marshalling and memory pinning. Furthermore, calling into native code can block the current isolate if not handled correctly, potentially causing frame drops in UI-intensive applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'148a49f8-8b68-440a-adc5-6d0584b83c11', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the role of ''Phoenix.Socket'' in managing different transport protocols?', N'Senior', N'The Socket module abstracts the underlying transport mechanism, allowing the application to handle both WebSockets and Long-polling interchangeably. This abstraction ensures that business logic remains agnostic to the specific transport protocol, simplifying cross-browser compatibility and fallback strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b40cd797-d709-4717-9244-6d06878a880f', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are the security implications of debug mode being enabled in a production environment?', N'Senior', N'When DEBUG is True, Django displays detailed traceback information, including environment variables, local variables, and database queries, upon encountering an error. This exposes sensitive system configuration and internal logic, providing attackers with a roadmap to exploit the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
