INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1fd7963-10e6-4da6-9002-6d29a2d9faca', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do database-level constraints compare to Active Record validations regarding data integrity in a distributed environment?', N'Senior', N'Active Record validations are application-level checks that are convenient but prone to race conditions in concurrent environments. Database-level constraints, such as unique indexes and check constraints, are the final source of truth and are necessary to guarantee data integrity when multiple app instances interact with the same data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
