INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86f6dfbd-fb01-479f-8d83-6d313203c072', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus implement live coding, and what is its impact on developer velocity?', N'Senior', N'Quarkus uses a sophisticated hot-reload mechanism that detects file changes and incrementally recompiles only the affected classes without restarting the entire JVM. This enables an immediate feedback loop where changes are reflected in the running application in milliseconds, drastically reducing the development cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8d8c3b8-140e-4b87-b00c-6d34f275ed80', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Why is ''Backpressure'' important in stream processing systems?', N'Middle', N'Backpressure is a mechanism that allows a system to signal to upstream producers that it is overloaded and cannot keep up with the data rate. This prevents the system from crashing due to memory exhaustion and allows for more graceful handling of traffic spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e5d1983-bd99-45a1-a59b-6d3c2a9a6bed', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How does data consistency impact design decisions in a global application?', N'Intern', N'Maintaining strong consistency across global regions can lead to high latency because of the time required for data synchronization. Designers often choose ''eventual consistency'' to improve performance, accepting that different parts of the system might temporarily show slightly different data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24f2bc8d-49e9-4659-8e3c-6d3c69f5c5d6', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How do you perform type assertions in Go?', N'Junior', N'A type assertion provides access to an interface value''s underlying concrete value. You use the syntax that checks if the interface holds a specific type, which returns the value and a boolean indicating if the assertion succeeded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b61fabfa-427e-46fe-a3e5-6d3d9f335c21', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you prioritize multiple tasks with similar deadlines?', N'Intern', N'I evaluate each task based on its impact on the project''s overall critical path and the dependency others have on my output. I communicate with my lead to confirm these priorities and manage expectations if a conflict arises.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ae27119-d415-4bd2-bcc6-6d3ea166253a', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the function of the +layout.svelte file?', N'Intern', N'The +layout.svelte file is used to define common UI elements that persist across multiple pages, such as navigation bars, footers, or sidebars. By placing it in a specific directory, it automatically wraps all child pages within that route structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ed1498a-ca60-421a-b9fa-6d41ffdc67d1', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you decide whether to fix a minor bug or work on a new feature request when both are in your backlog?', N'Junior', N'I would evaluate the impact and urgency of each item by considering how many users are affected by the bug versus the value the new feature provides to the business. I would then consult with my lead or product manager to align these priorities with the current sprint goals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'410c6a83-086d-4ce9-a6fc-6d4215c16d74', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How do ''Deref'' and ''DerefMut'' traits impact ergonomics?', N'Middle', N'These traits allow custom types to behave like references, enabling automatic dereferencing when calling methods or accessing fields. This significantly reduces boilerplate code for smart pointers and custom containers, making them feel like native language features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54981957-c7a4-41ed-ac9b-6d47bcdb3fad', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What does ''Atomicity'' mean in the context of ACID?', N'Junior', N'Atomicity ensures that all operations within a transaction are completed successfully. If any part of the transaction fails, the entire transaction is aborted, and the database is left unchanged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'986d1bc7-c76d-4cf7-9cec-6d48cd7f41c7', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Why is salting passwords important before hashing them?', N'Middle', N'Salting adds a unique, random string to each password before hashing, which prevents attackers from using precomputed rainbow tables to crack passwords. It ensures that two users with the same password will have different resulting hash values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b063f3b-fa1a-462f-9a26-6d4a84fb02ff', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is optional chaining?', N'Intern', N'Optional chaining is a process for querying and calling properties, methods, and subscripts on an optional that might currently be nil. If the optional contains a value, the call succeeds; if it is nil, the call returns nil.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ce23868-68d6-421e-a0b5-6d4dbbdc9442', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How do you determine the optimal TTL for cached objects in a highly dynamic system?', N'Senior', N'Optimal TTL is a balance between data freshness requirements and the allowable load on the backend storage. You determine it by analyzing the rate of change of the underlying data and the impact of serving stale data versus the latency penalty of frequent cache misses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17b854ee-793a-448c-b67d-6d4e308a62a7', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the differences of vuex store and plain global object?', N'Intern', N'Below are the two major differences between vuex store and plain global object, 1. Vuex stores are reactive: If the store''s state changes then vue components will reactively and efficiently get updated 2. Cannot directly mutate the store''s state: The store''s state is changed by explicitly committing mutations to ensure that every state change leaves a track-able record for tooling purpose', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c67555f8-0d06-47ed-beb4-6d4efd02b422', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask protect against CSRF attacks?', N'Middle', N'Flask does not include built-in CSRF protection by default, so developers often use extensions like Flask-WTF. This extension generates a unique token for every form submission that must be validated by the server. This ensures that the request originated from a trusted source rather than a malicious third-party site.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd88dc32f-191e-4caf-a507-6d4ffa7225a8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you empty an array', N'Fresher', N'You can empty an array quickly by setting the array length to zero.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f747d36-b3a8-4c4b-9101-6d5260a3a74f', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the function of the JIT compiler''s Tiered Compilation strategy?', N'Senior', N'Tiered compilation allows the JIT to emit code quickly with minimal optimization for the first execution and subsequently recompile ''hot'' methods with more aggressive optimizations. This balances fast application startup times with high peak performance for frequently executed code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'480d495d-7aa5-4df1-a69e-6d52c16235cc', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the role of ''Secondary Indexes'' in a distributed database and what is the cost?', N'Senior', N'Secondary indexes enable efficient queries on non-primary fields but introduce significant write-amplification and consistency challenges. In a distributed system, they must either be updated synchronously, which slows down writes, or asynchronously, which leads to index staleness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8e086fd-9f0f-4701-8682-6d5360087dc9', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the significance of the ''.env'' file in a Laravel project?', N'Middle', N'The .env file is used to store environment-specific configuration variables like database credentials, API keys, and debug settings. It keeps sensitive configuration data out of the version control system and allows the application to behave differently in development, staging, and production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40b2c34a-4f59-4fe0-830e-6d54c5289a75', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle content negotiation?', N'Fresher', N'Rocket automatically inspects the ''Accept'' header of a request to determine the preferred response format. It can then select the appropriate responder to serve the content in the format requested by the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af8ba5bb-5357-44af-b934-6d55cf8f8a30', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the role of the ''package-lock.json'' file in a production environment?', N'Middle', N'It ensures deterministic builds by locking the exact versions of dependencies and their sub-dependencies. This prevents ''it works on my machine'' issues by ensuring that every environment installs the exact same dependency tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9224f7e2-4281-41ef-9f93-6d55eb5e9e41', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you reuse information across service worker restarts', N'Fresher', N'The problem with service worker is that it gets terminated when not in use, and restarted when it''s next needed, so you cannot rely on global state within a service worker''s onfetch and onmessage handlers. In this case, service workers will have access to IndexedDB API in order to persist and reuse across restarts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'806ae11a-9716-4640-b7bb-6d5903e234d2', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle HTTP status codes?', N'Intern', N'Litestar automatically maps successful return values to HTTP 200 OK by default. Developers can explicitly define status codes by using the status_code parameter in the route decorator or by returning a custom response object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a07b67d-a47f-4384-bb90-6d5a2a856015', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the ''virtual'' and ''override'' keywords?', N'Junior', N'The ''virtual'' keyword allows a method in a base class to be overridden by a derived class. The ''override'' keyword is used in the derived class to explicitly replace the base class implementation with new logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e05e462b-6152-4107-b807-6d5b2af71ade', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What steps do you take when you realize you have accidentally pushed a breaking change to a shared development branch?', N'Junior', N'I would immediately notify the team to prevent others from pulling the broken state and then revert the commit or apply a fix as soon as possible. After the issue is resolved, I would perform a post-mortem to understand why my testing didn''t catch the error and adjust my workflow to prevent recurrence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95dcff5a-82af-4db8-be03-6d5b4300b84f', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does the ''Typeclass'' pattern in Scala enable ad-hoc polymorphism?', N'Senior', N'The typeclass pattern decouples behavior from data by defining an interface as a trait and providing implementations for specific types via implicit instances. This allows developers to add new functionality to existing types without modifying the original class source code, effectively solving the expression problem. It provides a more modular alternative to traditional inheritance-based polymorphism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4d79040-51ea-41d4-89c7-6d5f8ed4e177', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why should you document your reasoning during a design or troubleshooting process?', N'Fresher', N'Documentation creates a knowledge trail that helps others understand the ''why'' behind a decision, not just the ''how.'' It is essential for future maintenance and helps prevent team members from repeating the same mistakes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e26edb6f-2ebe-49b6-b155-6d62195d8044', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify manage asynchronous operations?', N'Fresher', N'Fastify natively supports asynchronous route handlers using the ''async/await'' syntax. If a promise is returned or an async function is used, Fastify automatically waits for completion before sending the response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
