INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a030cd1-d6c6-4451-9352-6d68405237e1', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a hot partition?', N'Junior', N'A hot partition occurs when a large number of requests target a single partition, often due to an poorly chosen partition key. This leads to uneven distribution of traffic and can cause performance throttling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa9e23a5-3bee-4b94-a4d7-6d6ab0da7dc1', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of Middleware?', N'Junior', N'Middleware provides a convenient mechanism for inspecting and filtering HTTP requests entering your application. For example, Laravel includes middleware to verify if a user is authenticated; if they are not, they are redirected to the login page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ad7ad9a-c92b-473d-9739-6d6c2c4fef53', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Explain the concept of ''consistent hashing'' in the context of database partitioning.', N'Senior', N'Consistent hashing maps both data keys and nodes onto a circular space, minimizing data movement when nodes are added or removed. It prevents the need to re-shard the entire dataset, which would be required if using simple modulo-based partitioning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a37d883-ee16-44d4-8837-6d6e2a7054ac', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is a Repository in Symfony?', N'Fresher', N'A Repository is a class dedicated to handling database queries for a specific entity. It provides a structured way to fetch, filter, and sort data from the database while keeping the controller clean and focused on request handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4540e3a-d1d1-480a-a96b-6d75ea117688', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between ASP.NET Core MVC and Web API?', N'Intern', N'MVC is designed for building web applications that return views, while Web API is specifically designed to build services that return data, typically in JSON format. Both share the same underlying framework and routing mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f74420fd-3a17-4007-89eb-6d76251ace98', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What does it mean for C to be a compiled language?', N'Intern', N'Being a compiled language means that the source code is translated by a compiler into machine-readable binary code before the program can be executed. This process typically makes C programs faster and more efficient compared to interpreted languages because the translation happens once, prior to runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c2ed879-8982-4415-a5c7-6d77daab3672', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle the trade-off between type safety and dynamic routing?', N'Senior', N'Axum uses sophisticated trait bounds and procedural macros to enforce type safety during route definition. While this creates a slightly steeper learning curve, it provides compile-time guarantees that the requested parameters match the handler function signatures, significantly reducing runtime errors related to data structure mismatches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fa1152f-6366-4711-bf11-6d783b23df47', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What strategies would you employ to secure a public-facing API beyond basic HTTPS?', N'Senior', N'Implement OAuth 2.0 with OpenID Connect for delegated authorization, use JWTs for stateless session validation, and enforce strict CORS policies. Additionally, integrate API gateways to perform mutual TLS, input validation, and anomaly detection to mitigate common threats like injection or mass assignment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd00cd9a9-f4cb-400e-87a9-6d784720b90e', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the role of Dependency Injection in Micronaut?', N'Fresher', N'Dependency Injection is a design pattern where objects receive their dependencies from an external source rather than creating them. In Micronaut, this is handled via annotations that allow the framework to manage the lifecycle and wiring of beans automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfba90f0-bf0e-47aa-8a56-6d7db7d25f45', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Why is exception handling important in ASP.NET Core?', N'Junior', N'Proper exception handling prevents the application from crashing and ensures that sensitive server information is not exposed to the end-user. Using global exception handling middleware allows for consistent error reporting and graceful degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb2dbc5b-4e4a-45df-98b6-6d7e477b9eaa', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a schema in PostgreSQL?', N'Intern', N'A schema is a namespace that contains database objects like tables, views, and indexes. It helps organize database objects into logical groups and allows multiple users to work in the same database without naming conflicts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc521693-52fc-43f6-b8c7-6d7e9680b297', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why is it important to choose the appropriate data type for a column?', N'Middle', N'Selecting the smallest appropriate data type optimizes storage space and improves cache efficiency in memory. It also impacts query performance, as smaller data types allow more rows to be processed per CPU instruction and reduce I/O overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20fb0ea5-0775-4a48-8b18-6d7f75124b1e', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'Why is it important to understand the ''why'' behind a requirement?', N'Fresher', N'Understanding the ''why'' allows me to suggest better solutions that might not have been obvious in the initial requirements. It helps me prioritize the most important aspects of the task and ensures that my implementation actually solves the underlying business problem. When developers understand the goal, they can make smarter decisions throughout the development process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4322fdf4-5ea2-43b1-ab28-6d802258552c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is lexical scope in JavaScript, and how does it differ from dynamic scope?', N'Intern', N'Lexical scope (also called static scope) means that the scope of a variable is determined at author time — by where the function is written in the source code, not where it is called from. JavaScript uses lexical scoping exclusively. When the JavaScript engine (V8) parses the source, it builds a scope chain based on the physical nesting of functions and blocks; this chain never changes at runtime. Dynamic scope, by contrast, resolves variable references based on the call stack at runtime. Languages like Bash and early Lisp dialects use dynamic scope. JavaScript has no dynamic scope (though this is sometimes confused for it because it is determined by the call site — this binding is separate from scope).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85d09ba4-0439-4fb1-b212-6d83d7e1182d', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the concept of inheritance in Java and its primary purpose.', N'Junior', N'Inheritance allows a class to acquire the properties and behaviors of another class, facilitating code reuse. It establishes an ''is-a'' relationship between a parent class and a child class. This helps organize code into hierarchies and promotes polymorphism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'986af284-24be-45d9-8033-6d8703121f20', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is Glimmer in Ember?', N'Intern', N'Glimmer is the rendering engine used by Ember.js. It is designed for high performance, utilizing a virtual DOM approach to efficiently update only the parts of the web page that have actually changed, rather than re-rendering everything.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f6ba483-3532-4385-a036-6d8797ac2060', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Why is it generally discouraged to modify core classes (monkey patching) in production Ruby applications?', N'Middle', N'Monkey patching changes the behavior of global objects, which can lead to unpredictable side effects and conflicts with other libraries or future versions of Ruby. It breaks the principle of encapsulation and makes the codebase significantly harder to debug and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ea0bc7d-9061-4443-a637-6d8a470aa1f2', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'In a distributed team, why is it often necessary to decouple ''d.ts'' files from the source code?', N'Senior', N'Decoupling declaration files allows for independent versioning and distribution of type definitions for JavaScript-only libraries. This ensures that consuming projects receive type safety without requiring the source code, facilitating a cleaner separation of concerns between library authors and consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3d3ebbd-1829-4e41-bd89-6d8bbc92e197', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is a major advantage of using Preact for mobile web development?', N'Fresher', N'The primary advantage is the small file size, which results in faster download and parse times. This is especially beneficial for users on slow mobile networks, as it allows the application to become interactive much sooner.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b258f58d-cf07-47fc-9daf-6d8fa5862ec1', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Explain the difference between RDB and AOF persistence methods in Redis.', N'Middle', N'RDB (Redis Database Backup) creates point-in-time snapshots of the dataset at specified intervals, which is efficient for backups but risks losing data since the last snapshot. AOF (Append Only File) logs every write operation received by the server, providing better durability at the cost of larger file sizes and potentially slower recovery times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce8c6bd1-9470-4b14-83de-6d90ef736604', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the impact of Litestar’s ''Message'' handling on high-throughput WebSocket communication?', N'Senior', N'Litestar provides native, structured support for ASGI message passing, which minimizes the overhead of manual connection management and event loop blocking. This allows for highly scalable real-time communication by offloading low-level frame handling to the framework while maintaining a clean, type-safe interface for application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
