INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0de29812-4caf-4173-ad6e-6d92076e943f', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the architectural benefits of using ''Scoped Slots''?', N'Senior', N'Scoped slots allow a child component to pass data to its parent''s template, enabling highly flexible component design where the parent determines how the child''s data is rendered. This promotes a clean separation of concerns, where the child handles the logic and the parent handles the UI presentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8691011-c981-4340-89a9-6d9bc64bb000', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you estimate the number of people in a large stadium?', N'Intern', N'I would count the number of seats in a single section and multiply that by the number of sections in the stadium. I would then adjust this number based on the observed percentage of empty seats to reach a realistic final estimate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
