INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b2bf39d-bbb5-401b-a3ab-6da456a60fc0', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide between two different approaches for a task?', N'Fresher', N'I compare them based on simplicity, readability, and performance requirements. I choose the approach that is easiest to maintain while still meeting the functional constraints of the project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'855d40d4-43cb-4e6f-9635-6da4716d38c1', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do you manage secret credentials in a Rails application deployed across multiple environments?', N'Senior', N'Use the built-in Rails credentials system, which encrypts secrets at rest and allows per-environment configuration. Avoid checking sensitive keys into version control and prefer injecting environment-specific secrets via environment variables or a dedicated secret management service in production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c92f4b36-c7a9-4700-a016-6da4ea1afada', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is it important to avoid ''any'' in a production TypeScript codebase?', N'Middle', N'Using ''any'' circumvents the TypeScript type system, effectively turning off static analysis for those parts of the code. This increases the risk of runtime errors, makes the code harder to refactor, and negates the primary benefits of using TypeScript for large-scale application development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a844e034-371e-4dd7-96f7-6da73e7c4bc5', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the role of ''untrack'' in complex SolidJS applications?', N'Senior', N'Untrack is used to temporarily disable dependency tracking within a specific scope. This is useful when you want to read a signal''s value inside an effect without creating a dependency that would trigger the effect upon that signal''s update.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcd8681f-c492-4372-b6bf-6da8bc7e02f1', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Why Use object over companion object?', N'Fresher', N'If a class doesn''t require an instance or has a single instance throughout the application, object is the most succinct and expressive solution. In contrast, companion object is suitable when non-static methods or properties need to interact with the singleton. It''s pertinent to classes you instatiate but have a single instance for per application. object Versus Traditional Singletons Kotlin''s object offers several advantages over traditional singletons, including automatic management of thread safety, lazy initialization, and streamlined syntax. It''s a recommended approach for modern Kotlin development. Traditional Java singletons also had complications with lazy initialization and thread safety, which are non-issues with Kotlin''s object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6826ef2c-bc34-4329-8002-6da90525c53d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Give an example of a web worker', N'Junior', N'You need to follow below steps to start using web workers for counting example 1. Create a Web Worker File: You need to write a script to increment the count value. Let''s name it as counter.js Here postMessage() method is used to post a message back to the HTML page 2. Create a Web Worker Object: You can create a web worker object by checking for browser support. Let''s name this file as web_worker_example.js and we can receive messages from web worker 3. Terminate a Web Worker: Web workers will continue to listen for messages (even after the external script is finished) until it is terminated. You can use the terminate() method to terminate listening to the messages. 4. Reuse the Web Worker: If you set the worker variable to undefined you can reuse the code', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b8dfa2e-c56a-4a43-b552-6dab8bc59866', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the purpose of the ''c'' function in R?', N'Intern', N'The ''c'' function stands for combine. It is used to create vectors by taking a sequence of arguments and joining them together into a single vector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef7762dc-2a67-44ce-b5ae-6dae57a84e60', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum achieve type-safe request handling compared to frameworks using dynamic typing?', N'Middle', N'Axum uses the ''Extractor'' pattern, which leverages Rust''s strong type system to automatically deserialize request data into specific types. This ensures that a handler only executes if the incoming request meets the structural requirements defined in the function signature.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c8b4688-e4cf-45ed-bed0-6daefe43586b', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Why is it important to keep the working set in memory in MongoDB?', N'Middle', N'The working set is the portion of data and indexes that the application accesses most frequently. If the working set fits entirely in RAM, the database can serve requests without expensive disk I/O operations, which is critical for maintaining high performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2e96d14-0359-4bd6-82e7-6dafb11a3a17', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Can Svelte components be used without a build step?', N'Junior', N'While Svelte is designed to be compiled, you can technically use it in a browser environment, but it is not recommended for production applications. A build step is required to transform Svelte components into standard JavaScript that browsers can execute efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48bec0c8-209f-4cab-a857-6db08ef23294', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the role of ''Blittable'' types in Interop scenarios.', N'Senior', N'Blittable types have an identical representation in both managed and unmanaged memory, allowing them to be passed to native code without conversion. Non-blittable types require the runtime to marshal the data, creating a copy in a compatible format. Minimizing marshaling by using blittable types is critical for low-latency performance in P/Invoke calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'892ac42a-c79e-4f1c-ae4f-6db179a0bcd7', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How do PHP''s internal arrays differ from standard hash maps in other languages?', N'Senior', N'PHP arrays are implemented as ordered hash maps, which maintain both the insertion order and the key-value associations. This implementation provides O(1) average time complexity for access while consuming more memory than a simple indexed array found in lower-level languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a599cf3-a66e-4952-a807-6db1c44176c1', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is a library in the context of R?', N'Intern', N'A library is a directory on your computer that contains installed R packages. You use the library command to load these packages into your current session so that their functions become available for use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4cad30e-d005-4ab1-9e5d-6db211f6cf6d', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle database migrations in a CI/CD pipeline?', N'Senior', N'AdonisJS migrations are version-controlled and idempotent, allowing them to be run automatically during the deployment phase. By using the CLI to execute migrations against the production database, the application ensures that the schema state is always synchronized with the code, preventing runtime failures due to missing columns or tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e31dc81f-a015-41d0-a7cc-6db5c7110515', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are the advantages of using ''Record'' types in ASP.NET Core for DTOs?', N'Senior', N'Record types provide built-in value-based equality, immutability, and concise syntax, which are ideal for Data Transfer Objects (DTOs). They reduce boilerplate code and prevent accidental side effects, ensuring that data structures remain thread-safe and consistent throughout the request pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a78baa11-1c85-48a0-bd4c-6db8a34ef5c9', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What happens if you destructure props in SolidJS?', N'Fresher', N'Destructuring props in SolidJS breaks reactivity because it extracts the current value rather than maintaining the reactive getter. To keep props reactive, you must use the splitProps utility or access the properties directly from the props object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5cc1231-eaf0-4e47-b251-6db9bc3e15dc', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s router handle trailing slashes, and why is this a relevant configuration choice?', N'Senior', N'Echo provides a strict configuration for trailing slashes, which can lead to 404 errors if not handled consistently. Choosing to enforce or ignore them globally is critical for SEO and client-side consistency, preventing broken links and ensuring that routing logic remains predictable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95a1eda5-c01f-44e3-b7af-6dbb1e14830e', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the performance implications of the Small Object Optimization in standard library containers?', N'Senior', N'Small Object Optimization stores small elements directly within the container''s internal storage buffer instead of heap-allocating memory. This reduces the frequency of memory allocations and improves cache locality, significantly speeding up operations on containers holding small or short-lived objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58f4e16f-773f-4f40-a8c5-6dbb2bb28345', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the role of Middleware in the context of a Litestar application?', N'Junior', N'Middleware in Litestar acts as a wrapper around the request-response cycle. It allows you to intercept incoming requests or outgoing responses to perform tasks like logging, modifying headers, or implementing cross-cutting concerns like CORS and authentication before the request reaches the specific route handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'303c9a97-212d-4d69-a3dd-6dc3a08dd27a', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a clustered index?', N'Junior', N'A clustered index determines the physical order of data in a table. Because the data rows themselves are stored in the order of the clustered index, a table can only have one.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bddb25b-3a17-410f-9e8d-6dc3a7c730e6', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is a symbol in Ruby?', N'Intern', N'A symbol is an immutable identifier that acts as a label for a specific name or string. Symbols are memory-efficient because they are created only once and reused throughout the application, often used as hash keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'924ca912-1ae2-484b-bbf4-6dc3e591c52c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When developing a feature that requires data validation, why should you perform validation on both the client and the server?', N'Fresher', N'Client-side validation provides immediate feedback to the user, improving the user experience. However, since it can be bypassed, server-side validation is mandatory to ensure data integrity and security. The server acts as the final source of truth to prevent malicious or malformed data from entering the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a0f2c6b-13fd-4c77-a218-6dc5b9896487', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach the design of an asynchronous event-driven architecture versus synchronous REST/gRPC APIs?', N'Senior', N'I prioritize synchronous communication for request-response cycles where immediate feedback is required. I shift to event-driven architectures when decoupling services, improving system responsiveness through parallelism, or handling high-burst traffic patterns that would otherwise overwhelm downstream synchronous dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6882642-ee4a-4e7b-9047-6dc5f27269b5', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are sealed classes used for?', N'Intern', N'Sealed classes are used to represent restricted class hierarchies where a value can only be one of the types from a predefined set. They are particularly useful when using ''when'' expressions to ensure all possible cases are covered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84b67af6-d548-4576-b2a9-6dc60e9236d6', N'4c000000-0000-0000-0000-000000000005', N'How do you handle ''hot partitions'' in a partitioned database system?', N'Senior', N'Hot partitions occur when specific keys receive a disproportionate amount of traffic, overloading a single node. Mitigate this by implementing finer-grained partitioning, adding read replicas, or using application-level caching to offload the burden from the database layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a82fd5d8-b7ec-468c-9d98-6dca25a92ca1', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the difference between an ID and a class in CSS?', N'Junior', N'An ID is used to style a single unique element on a page and has higher specificity. A class is designed to be reusable and can be applied to multiple elements throughout the document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'210b4913-ab9a-418d-ba58-6dcd029903e3', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What does it mean for DynamoDB to be a schemaless database?', N'Intern', N'Being schemaless means that DynamoDB does not require a predefined data structure for items within a table, unlike traditional relational databases that require rigid table schemas. Each item can have a different number of attributes, allowing for greater flexibility when storing evolving data formats.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5247ea2c-c0cc-4d4e-9f31-6dcfee34a7ef', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Explain the concept of ''Covering Index'' vs ''Included Columns''.', N'Senior', N'A covering index contains all data needed for a query in its B-tree structure. Included columns are non-key columns added to a non-clustered index to enable covering without increasing the overhead of the B-tree navigation, as they are only stored at the leaf level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55c7b635-269c-46de-856f-6dd08b3606d4', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Discuss the impact of ''hidden classes'' on JavaScript''s dynamic nature.', N'Senior', N'Hidden classes allow engines to treat dynamic objects like fixed-layout structures found in statically typed languages. This enables the use of efficient machine code offsets, but adding or deleting properties dynamically can trigger shape transitions, forcing the engine to deoptimize.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3a470a8-937a-458d-b014-6dd198f7bd32', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are key-value stores?', N'Intern', N'Key-value stores are the simplest type of NoSQL database where every data item is stored as a unique key linked to a specific value. They are highly efficient for fast lookups and are commonly used for caching or session management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca9d842f-dffd-4a52-968a-6dd1da20d464', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the difference between an action and a reducer?', N'Middle', N'An action is a plain object that describes a change or an event that occurred in the application. A reducer is a function that takes the current state and an action, then returns a new state object based on the action type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f0e43fd-797e-49ed-bc2a-6dd33c71fabc', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the benefit of using Webpack over manual script inclusion?', N'Fresher', N'Manual script inclusion is error-prone and requires managing script ordering and global variables. Webpack automates dependency management, allows for modern module syntax, and optimizes the final output for better performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffd62355-051e-428d-a43f-6dd3e06b0be6', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Explain the role of ''Echo.Logger'' and why one might swap it for a structured logging library like Zap or Zerolog.', N'Senior', N'Echo''s default logger is simple and lacks structured output, which is essential for effective log aggregation and analysis in production. Swapping it for a structured logger allows for high-performance, machine-readable logs that include contextual metadata, significantly improving incident response times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f16fd47f-a5c3-4051-8a7b-6dd43c3b76e5', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar manage state in a distributed environment given its ASGI nature?', N'Senior', N'Litestar is inherently stateless, relying on external stores like Redis or databases for persistent state management across instances. Architects must ensure that any global state or session information is offloaded to external, distributed backends to maintain horizontal scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c748844-a441-4e11-a0b5-6dd4fb4061ab', N'954a0331-deff-4399-b588-96f39fec001d', N'What is a provider?', N'Intern', N'A provider is an instruction to the Dependency Injection system on how to obtain a value for a dependency(aka services created). The service can be provided using Angular CLI as below, The created service by CLI would be as below,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b77945d8-0f22-49c2-87f8-6dd6f941b848', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Discuss the impact of ''noexcept'' on compiler optimization.', N'Senior', N'The noexcept specifier acts as a contract telling the compiler that a function will not throw exceptions. This allows the compiler to omit exception-handling stack unwinding information, resulting in smaller binary sizes and enabling more aggressive optimizations, such as moving non-throwing types instead of copying them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c55cf247-d9cc-4e43-be99-6dd7d94d212f', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the benefit of using Remix''s resource routes?', N'Intern', N'Resource routes allow you to create server-side endpoints that return data like JSON, images, or PDFs instead of HTML. This is useful for building APIs or handling file downloads directly within your application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d6ba106-4041-4609-a874-6dd90f94fe44', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What does ''single-threaded'' mean in terms of Redis architecture?', N'Intern', N'Redis uses a single-threaded event loop to process commands, meaning it executes one command at a time. This design simplifies the architecture and avoids the overhead and complexity of managing locks or thread synchronization, which helps keep operations very fast.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96ef3a38-00e3-4eef-aa87-6dd98520542f', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why does Remix prioritize server-side rendering?', N'Junior', N'Server-side rendering ensures that the initial HTML is fully prepared before reaching the browser, which improves performance and SEO. It allows the application to function even if JavaScript fails to load or is temporarily disabled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b38c193-1854-4816-a5f6-6dda340440e1', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite manage environment variables?', N'Middle', N'Vite exposes environment variables through the import.meta.env object. It automatically loads variables from .env files, but only those prefixed with VITE_ are exposed to the client-side code to prevent sensitive server-side secrets from leaking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a52be4fe-fae6-4449-96e6-6ddd6afefd1a', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How do you handle test automation for an Alpine.js-driven interface?', N'Senior', N'Since Alpine relies on DOM manipulation, end-to-end testing with tools like Playwright or Cypress is the most reliable approach. Unit testing the logic within Alpine is best achieved by extracting complex business logic into pure JavaScript functions that are then invoked within the Alpine directives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'022a493f-57d6-41e7-b3eb-6dde6bfd0ce2', N'954a0331-deff-4399-b588-96f39fec001d', N'How do RxJS cold and hot observables differ in the context of an Angular service-based architecture?', N'Senior', N'Cold observables start their execution flow upon subscription, making them ideal for HTTP requests where each subscriber needs its own stream. Hot observables exist independently of subscribers, which is useful for shared application state or events like mouse movements where multiple components need to react to a single source.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9e89c6d-8dd8-4726-8ed7-6ddecc013650', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the Temporal Dead Zone (TDZ)?', N'Intern', N'In ES6, let bindings are not subject to "variable hoisting", which means that let declarations do not move to the top of the current execution context. Referencing the variable in the block before the initialization results in a ReferenceError (contrary to a variable declared with var, which will just have the undefined value). The variable is in a "temporal dead zone" from the start of the block until the initialization is processed. Real-World Use Case: TDZ prevents a subtle bug in module initialisation cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33145406-7f6f-46df-9222-6de3cdfc2327', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between a static nested class and an inner class?', N'Middle', N'A static nested class is associated with its outer class but does not have access to non-static members of the outer class, behaving like a top-level class. An inner class is associated with a specific instance of the outer class and can access all its members. Inner classes hold an implicit reference to the outer instance, which can lead to memory leaks if not managed carefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c71a20e-85b1-4cd2-90f2-6de54ab43b3f', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do you handle user events in Lit?', N'Junior', N'Events are handled by adding standard HTML event listeners directly within the template using the @event syntax. This allows you to bind component methods to specific user interactions like clicks or input changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c94a8a2-deb5-46f5-8586-6de6814cf386', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the difference between an explicit and implicit transaction?', N'Intern', N'An implicit transaction is automatically started and committed by the database system for single statements. An explicit transaction requires the user to manually issue commands to start and complete the transaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37c7d50a-f9cf-4ee5-b2b0-6de68547b0e4', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What happens if a Redis server runs out of memory?', N'Intern', N'When Redis runs out of memory, it can be configured to use eviction policies. The most common policy is LRU (Least Recently Used), which automatically removes older or less frequently accessed keys to make room for new data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b106a8c3-e7c5-4f79-9b09-6deaa776ead5', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What are the trade-offs of using ''body'' extractors in Axum?', N'Middle', N'Body extractors consume the request stream, which means the body can typically only be read once. If you need to access the body multiple times, you must either buffer it into memory or use specialized middleware to clone the request body.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6443b93-08d4-443b-9a02-6deabc6f9dd2', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Describe the role of the ''Run Loop'' and why it is critical for Ember''s performance.', N'Senior', N'The Run Loop is a scheduling mechanism that batches DOM updates, data synchronization, and event processing into specific queues to prevent layout thrashing. By deferring and grouping these tasks, it ensures that the browser only performs expensive reflows once per frame, significantly optimizing the rendering pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07ca9942-0d8a-4a19-89fe-6deb2459dff5', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the primary role of middleware in an Express application?', N'Intern', N'Middleware functions are blocks of code that have access to the request object, the response object, and the next middleware function in the application’s request-response cycle. They are used to execute code, make changes to the request and response objects, end the request-response cycle, or call the next function in the stack. This modular approach allows developers to easily inject features like logging, authentication, and body parsing into the application flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'243dc09f-a41a-4e64-b935-6deb290f02f5', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why would you use a devServer in Webpack?', N'Junior', N'Webpack DevServer provides a local development environment with features like live reloading and hot module replacement. It serves your files from memory rather than writing them to the disk, which significantly speeds up the development feedback loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e77f528c-2e55-41a4-b21c-6debe1d310a1', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are Preact Hooks and why are they used?', N'Fresher', N'Hooks are functions that allow you to use state and other React features in functional components without writing a class. They help developers write cleaner, more reusable logic by allowing state management and side-effect handling directly within function components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6abeaecb-3a6c-47b8-9594-6debfabb1918', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How do Rust''s macros improve meta-programming compared to C-style preprocessors?', N'Senior', N'Rust macros are hygienic, meaning they operate on the syntax tree rather than raw text, preventing variable name collisions and ensuring scope integrity. This allows for powerful code generation while maintaining the safety guarantees and debuggability of the rest of the language.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7730f8b5-1300-412a-901d-6debfedece4b', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Under what conditions would you choose a NoSQL database over a relational database for scaling?', N'Senior', N'You would choose NoSQL when your data model is highly fluid, requires massive horizontal write throughput, or involves unstructured data that does not benefit from complex relational integrity. NoSQL databases often relax strict consistency requirements to provide higher availability and lower latency at scale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4d9dffc-74f6-4530-b308-6df547727ee9', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the primary benefit of Hono''s ''Event'' based architecture?', N'Middle', N'The event-based architecture is designed to handle requests as discrete events, which is the native model for serverless functions. This makes Hono a natural fit for event-driven architectures where functions are triggered by network requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc827ca4-f27a-4d03-85bd-6dfbb1328a4e', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is an extension method?', N'Junior', N'An extension method allows you to add new methods to an existing type without modifying, recompiling, or creating a new derived type. They are defined as static methods but can be called as if they were instance methods on the target type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7aadae37-f895-4ccc-a70f-6dfc84f1713f', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI perform type checking?', N'Junior', N'FastAPI leverages Python''s type hints to perform validation. By defining types for function parameters, FastAPI automatically checks if the incoming request matches those types and raises a clear error if they do not match.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
