INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7496798a-5c88-4f3b-8ad2-6e06f326fdce', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it important to consider ''edge cases'' during the debugging process?', N'Intern', N'Edge cases often trigger unexpected behaviors that are not covered by standard operational logic. Considering scenarios like empty inputs, extreme values, or network timeouts helps identify vulnerabilities that would not be apparent under normal usage conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a864b4a0-b80f-451f-9c33-6e07ae22dacf', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between ''find'' and ''find_by'' in ActiveRecord?', N'Fresher', N'The ''find'' method raises an error if the record is not found, typically returning a 404. The ''find_by'' method returns nil if the record is not found, allowing you to handle the missing data gracefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8864ee1d-449c-4865-8d06-6e080c826dfd', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle CORS (Cross-Origin Resource Sharing)?', N'Middle', N'Axum provides a dedicated CORS middleware through the Tower library. This allows you to declaratively define allowed origins, methods, and headers, ensuring that the server correctly responds to preflight requests and enforces browser security policies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
