INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9f0d569-3f35-4757-8167-6e3d674635e4', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between an assignment operator and an equality operator?', N'Intern', N'The assignment operator is used to set the value of a variable. The equality operator is a logical operator used to compare two values to see if they are the same.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6dae78b4-daf0-4da2-8593-6e3ecc11bbc4', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does the Ruby Global Interpreter Lock (GIL) affect concurrency in MRI?', N'Senior', N'The GIL ensures that only one thread executes Ruby bytecode at a time, preventing race conditions within the interpreter''s internal data structures. While it simplifies memory management, it prevents true parallel execution of Ruby code on multi-core processors, necessitating the use of multi-process architectures for CPU-bound tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4424b8fe-d080-4111-aee3-6e42370bcc56', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle errors during component rendering?', N'Middle', N'Svelte does not have a native ''Error Boundary'' component like React. Error handling must be managed using standard JavaScript try-catch blocks or by implementing custom wrapper components that catch errors in their child slots.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f88f1bd-c15e-4e31-8210-6e45e9ab24f2', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why is it important to consider ''edge cases'' during the design phase?', N'Intern', N'Edge cases are unusual scenarios that, if ignored, often lead to system failures or unexpected behavior in production. Addressing them early prevents costly rework and ensures the solution is robust enough to handle data or user inputs outside of the standard range.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'894c5ef2-5a4e-4cd5-a7a2-6e49de49eb4d', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What does ''Deadlock'' mean in a database?', N'Junior', N'A deadlock occurs when two or more transactions are waiting for each other to release locks on resources. The database system must detect this state and abort one of the transactions to allow the others to proceed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'529a39ae-1459-4423-838c-6e4d3ae5fd34', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What does the BASE model stand for?', N'Intern', N'BASE stands for Basically Available, Soft state, and Eventual consistency. It is the core philosophy for many NoSQL databases, emphasizing high availability and system responsiveness over immediate data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd26aebb0-04fe-4959-8c25-6e4d9f4a04d1', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is ''Task Local Storage'' and when should it be used in concurrent Swift?', N'Senior', N'Task Local Storage allows values to be associated with the current task''s execution context, making them accessible throughout the task''s call tree. It is intended for propagating contextual data, such as security tokens or request IDs, without explicitly passing them through every function signature. However, it should be used sparingly, as it can introduce hidden dependencies and complicate the flow of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28f36c44-5c3c-443b-81d3-6e4df91c2c2a', N'954a0331-deff-4399-b588-96f39fec001d', N'How does the ''Platform-Browser'' vs ''Platform-Server'' distinction enable Server-Side Rendering (SSR)?', N'Senior', N'The platform abstraction allows Angular to run in environments without a DOM by swapping out the rendering engine. This enables the server to serialize the application state into HTML, which drastically improves SEO and initial paint times for the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
