INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'153bc45e-f969-486d-9a5c-6e63e8a95ca0', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle the trade-off between keeping logic in HTML and maintaining separation of concerns?', N'Senior', N'Alpine adopts the ''separation of concerns'' model where logic is treated as a property of the view, rather than separating them into distinct file types. While this can lead to ''spaghetti HTML'' in large components, it keeps behavior and structure tightly coupled for easier comprehension. For complex logic, the recommended architecture is to move business logic into external JavaScript files or helper objects, using Alpine only for the binding layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa3816eb-fafd-470a-8f8c-6e675eac52b0', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the difference between React context and React Redux?', N'Fresher', N'You can use Context in your application directly and is going to be great for passing down data to deeply nested components which what it was designed for. Whereas Redux is much more powerful and provides a large number of features that the Context API doesn''t provide. Also, React Redux uses context internally but it doesn''t expose this fact in the public API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60ed70df-eaa7-476b-a5ff-6e6a53fc33d6', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the benefits of using a middleware function in Express.js?', N'Junior', N'Middleware functions have access to the request object, the response object, and the next middleware function in the application''s request-response cycle. They are beneficial for modularizing code, such as logging, authentication, or parsing request bodies, before reaching the final route handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50e42166-8bed-4903-adcd-6e705e674ddd', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How is Cassandra different from a Relational Database?', N'Fresher', N'Unlike relational databases that focus on ACID compliance and complex joins, Cassandra is designed for high write throughput and massive horizontal scalability. It lacks support for complex table joins and is optimized for specific query patterns rather than general-purpose reporting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
