INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c9450b7-9bad-4708-91ac-6e789fdf4792', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What does implicit interface implementation mean?', N'Intern', N'In Go, a type implements an interface simply by implementing all the methods declared in that interface. There is no explicit ''implements'' keyword; if the methods exist, the type satisfies the interface automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e069499d-a65d-47a0-876b-6e79cc95e313', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Does Go support object-oriented programming features like inheritance?', N'Fresher', N'Go does not support traditional class-based inheritance found in languages like Java or C++. Instead, it promotes composition through struct embedding and defines behavior using interfaces, which allows for polymorphism without a rigid class hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11ca83e9-0be2-4aaf-8e39-6e7ba4e0ac09', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Explain the difference between ''IntoResponse'' and ''FromResponse'' in Axum.', N'Middle', N'The ''IntoResponse'' trait defines how a type can be converted into an HTTP response, allowing custom structs to be returned directly from handlers. ''FromResponse'' is used to extract data from a response, which is primarily useful when building middleware that inspects or modifies outgoing responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99f89848-3649-4716-bbe0-6e7bdb60a56e', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why ReactDOM is separated from React?', N'Fresher', N'The React team worked on extracting all DOM-related features into a separate library called _ReactDOM_. React v0.14 is the first release in which the libraries are split. By looking at some of the packages, react-native, react-art, react-canvas, and react-three, it has become clear that the beauty and essence of React has nothing to do with browsers or the DOM. To build more environments that React can render to, React team planned to split the main React package into two: react and react-dom. This paves the way to writing components that can be shared between the web version of React and React Native.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9496981-f009-467b-9e26-6e7dc2d6aecd', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit''s data invalidation strategy work when using ''invalidate'' and ''invalidateAll''?', N'Senior', N'SvelteKit tracks the dependencies of each load function; when an invalidation is triggered, the framework automatically re-runs the affected load functions. This granular control allows developers to refresh specific pieces of data without reloading the entire page or losing user-input state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3b01b29-e583-4adb-a480-6e7e3d4397ac', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the purpose of the ''useRuntimeConfig'' composable?', N'Junior', N'useRuntimeConfig provides a way to access environment variables and configuration settings at runtime. It allows you to keep sensitive keys on the server and expose only necessary configuration to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fc5e7ed-10f9-440c-a0e5-6e7ea45dc5f6', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'When is it appropriate to use cache-aside with a refresh-ahead strategy?', N'Middle', N'Refresh-ahead is used when you want to proactively update a cache entry before it expires, based on predicted access patterns. This is appropriate for data that is extremely expensive to generate and has highly predictable usage, as it keeps the cache warm without the latency penalty of a cache miss.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90fae3eb-a61d-42cc-b480-6e7f77318504', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the purpose of the ''context'' package when used with Chi?', N'Fresher', N'In Chi, the request context is used to carry request-scoped values, such as the URL parameters extracted from the path. It allows handlers to access data passed down through the middleware chain or extracted by the router.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7366307c-e168-434c-ab12-6e805b79945f', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the architectural trade-offs between using Kotlin''s ''inline'' keyword versus standard function calls.', N'Senior', N'Inlining reduces function call overhead and enables the use of reified types or non-local returns, but it can lead to significant bytecode bloat if overused. Excessive inlining increases the size of the binary and can negatively impact instruction cache performance, necessitating careful selection of functions to inline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77d8211f-7139-466e-b6f0-6e8469f6e8a2', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How does the ''five whys'' technique help in root cause analysis?', N'Intern', N'The five whys technique involves asking ''why'' five times in succession to peel away layers of symptoms. This process forces you to look past the surface-level observation and find the fundamental cause of the problem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b75da709-f6e1-45d8-a538-6e84d0513259', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is List Comprehensions feature of Python used for?', N'Intern', N'List comprehensions help to create and manage lists in a simpler and clearer way than using map(), filter() and lambda. Each list comprehension consists of an expression followed by a for clause, then zero or more for or if clauses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64b74d24-fe59-4217-84a1-6e870d2e266b', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How would you design a multi-tenant Flask application architecture?', N'Senior', N'Multi-tenancy can be achieved via separate database schemas, row-level security, or entirely separate database instances per tenant. The choice depends on the isolation requirements and the scale of the user base, typically implemented by inspecting the request header or URL and dynamically switching the database context in a ''before_request'' hook.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3d1a1c9-83f2-4519-bd11-6e89dd6341d6', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the REST API in Elasticsearch?', N'Fresher', N'The REST API is the primary interface used to interact with Elasticsearch. It allows users to perform operations like indexing, searching, and managing clusters using standard HTTP methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b87c09e4-2e62-45b7-b8b0-6e8da74cf774', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of the ''Bloom Filter'' in the context of Cassandra reads?', N'Senior', N'A Bloom filter is a probabilistic data structure stored in memory that indicates whether a specific partition key exists in a given SSTable. It allows the database to skip reading SSTables that definitely do not contain the requested data, significantly reducing disk I/O operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
