INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2a80064-80a7-4a1c-bce6-6e908e69ef4d', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Explain how Alpine.js handles nested scopes and variable shadowing.', N'Senior', N'Alpine uses a prototype-based chain to resolve variables within nested scopes, where child components inherit the state of their parents. When a variable name is duplicated, the child component shadows the parent''s value, which is useful for localized overrides. This scoping mechanism allows for powerful data inheritance patterns while maintaining clear boundaries for component-specific logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a62bd43b-bc20-450b-b0e8-6e91c5888dee', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix maintain the ''web standards'' philosophy during client-side transitions?', N'Senior', N'Remix prevents default browser behaviors for navigation and form submission, replacing them with client-side fetch calls that mimic the behavior of a full page load. This provides the snappy feel of an SPA while ensuring that the application logic remains consistent with how the browser handles standard HTTP requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29f4ce27-45bc-4c67-a57d-6e91eb1715bf', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Describe the mechanism behind Gin’s recovery middleware and its role in process stability.', N'Senior', N'The recovery middleware acts as a global panic handler that catches unhandled exceptions during the request cycle. By recovering from panics and returning a 500 status code, it prevents the entire application process from crashing, ensuring high availability during unexpected runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd2e8fd4-f9d4-470d-9230-6e924e754f79', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is an entity-relationship diagram (ERD)?', N'Intern', N'An ERD is a visual representation of the entities within a system and the relationships between those entities. It is used as a blueprint for designing the logical structure of a database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3aa664c-173f-4efa-aba7-6e92dcee2d6f', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the difference between ''push'' and ''pull'' based consumption models?', N'Middle', N'In a push model, the broker actively sends messages to consumers, which is efficient for real-time delivery but can overwhelm the consumer. In a pull model, consumers poll the broker for messages, allowing them to control the flow and process data based on their current load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7be5bff7-7987-4043-9c9b-6e935bfb56ba', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Why might you choose a document store over a relational database for a rapidly changing schema?', N'Middle', N'Document stores allow for flexible, schema-less data structures, which eliminates the need for expensive ''ALTER TABLE'' operations. This is beneficial for iterative development where the data model evolves frequently, preventing downtime associated with database migrations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'502af397-a113-4b52-9828-6e99134f77af', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why does Rust prefer composition over inheritance?', N'Middle', N'Rust favors composition through traits because it avoids the fragile base class problem and deep, complex hierarchy structures found in traditional object-oriented languages. Traits define shared behavior without enforcing a rigid memory layout, making the code more modular and easier to refactor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
