INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b59aa3bc-be78-4c8a-9766-6e9abc53262e', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala''s tail-call optimization (TCO) interact with the JVM''s bytecode limitations?', N'Senior', N'The JVM lacks native support for tail-call optimization, meaning Scala can only perform TCO if a method calls itself directly. This restriction forces developers to use trampolining or explicit iteration when dealing with mutually recursive calls, as the compiler cannot rewrite arbitrary tail-recursive structures into jumps without native runtime support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82313da2-6804-4b3a-8dda-6e9c9aefb460', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Explain the architectural trade-offs of using Echo’s context object (echo.Context) versus the standard library''s context.Context.', N'Senior', N'Echo''s context is an interface that bundles request and response metadata, making it developer-friendly but tightly coupled to the framework. While it provides convenience methods for binding and rendering, it can make unit testing harder compared to using standard library context, which is designed for request-scoped values and cancellation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fedc74a-3b3f-44f6-9c9f-6e9dbb1667ed', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Discuss the impact of jQuery''s plugin ecosystem on modern dependency management and tree-shaking.', N'Senior', N'The jQuery ecosystem is not designed for modern module bundling, meaning it is difficult to perform tree-shaking to remove unused functions. Consequently, projects often carry the weight of the entire library even when only a small fraction of its features are utilized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4313fc14-f07b-4add-8905-6e9e34fd611e', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you handle user authentication in a distributed system?', N'Senior', N'Use a centralized identity provider with stateless tokens like JWTs to allow services to verify user identity without constant database lookups. Ensure robust handling of token revocation and public key rotation to maintain security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a434d36-965a-4397-a4c3-6e9f6f0dc4d0', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is Replica Set in MongoDB?', N'Intern', N'It is a group of mongo processes that maintain same data set. Replica sets provide redundancy and high availability, and are the basis for all production deployments. A replica set contains a primary node and multiple secondary nodes. The primary node receives all write operations. A replica set can have only one primary capable of confirming writes with { w: "majority" } write concern; although in some circumstances, another mongod instance may transiently believe itself to also be primary. The secondaries replicate the primary''s oplog and apply the operations to their data sets such that the secondaries'' data sets reflect the primary''s data set. If the primary is unavailable, an eligible secondary will hold an election to elect itself the new primary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9848fdd1-adec-47d8-a254-6e9f8941b1b0', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Does Hono include a built-in logger?', N'Intern', N'Yes, Hono provides a logger middleware that automatically logs incoming requests to the console. This is a standard tool used during development to track traffic and debug issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9d3a893-9a28-4026-a77c-6ea0d0f1efbf', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'When should you prefer native DOM methods over jQuery methods?', N'Middle', N'You should prefer native methods when performance is critical or when you want to reduce dependency overhead in a lightweight application. Native methods are faster and provide a more predictable API that doesn''t rely on the specific version of a library, making the code more future-proof.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8571afa-f9c4-453b-a582-6ea2a28c7099', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How do you achieve default arguments for functions?', N'Junior', N'Kotlin allows you to assign a default value to a parameter in a function signature using the assignment operator. This allows the caller to omit that argument during the function call, using the default value instead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98e4b51a-c61e-4928-a56b-6ea2fc7fb7d7', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the difference between getStaticProps and getServerSideProps?', N'Junior', N'getStaticProps is used for fetching data at build time, making it ideal for static content that does not change frequently. getServerSideProps is used to fetch data on every request, making it suitable for dynamic data that needs to be updated in real-time for each user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cca67410-6f9d-423d-97a3-6ea40e1539cc', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Does Lit require a build tool?', N'Fresher', N'While not strictly required for simple applications, using a build tool like Vite or Webpack is highly recommended with Lit. These tools help with transpilation, bundling, and optimizing the code for production deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86a1c242-bcb9-4376-b05b-6ea457218c2c', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you manage API breaking changes without breaking client integrations?', N'Middle', N'Breaking changes should be managed by maintaining multiple versions of the API simultaneously, allowing clients to migrate at their own pace. Deprecation notices should be communicated well in advance, and eventually, older versions can be sunsetted after a transition period.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4c35f58-1eeb-44f8-8bb5-6ea5143158bb', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony''s ''Proxy'' pattern work in Doctrine, and why is it necessary for performance?', N'Senior', N'Proxy objects allow Doctrine to implement lazy loading by creating lightweight placeholders for entities that are not yet needed. This prevents the application from fetching entire object graphs from the database upfront, drastically reducing memory usage and initial query latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36ac5408-1a5b-4c60-ae4b-6ea5bd15177a', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How do read replicas impact the overall architecture of a system?', N'Senior', N'Read replicas offload read-heavy traffic from the primary node, improving scalability and providing redundancy. However, they introduce the risk of reading stale data due to replication lag, which must be addressed at the application level or through read-your-writes consistency guarantees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd106427c-1853-4a6f-bd29-6ea6f993981e', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does a load balancer contribute to system scalability?', N'Middle', N'A load balancer distributes incoming network traffic across multiple backend servers. This prevents any single server from becoming overwhelmed and allows for the seamless addition or removal of servers as traffic demands change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c96a60cd-b44e-4697-826b-6ea7d94e8656', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are access control levels in Swift?', N'Intern', N'Access control levels restrict which parts of your code can access properties and methods. Common levels include public, which allows access from any source file, and private, which restricts access to the enclosing scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a835d09-a3a4-423f-965c-6eab00a4192e', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is your strategy for identifying a memory leak in a long-running production service?', N'Senior', N'I would analyze heap dumps taken at different intervals to identify objects that are not being garbage collected. I look for growing retention trees and analyze reference chains to determine which components or caches are holding onto references unnecessarily, then correlate these findings with traffic patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b73b140-fcd1-4643-a122-6eac7e9f1e69', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the significance of the ''Quarkus Platform'' BOM?', N'Middle', N'The Platform BOM (Bill of Materials) ensures that all extensions and libraries used in a project are tested and verified to work together. It prevents version conflicts and ensures compatibility across the diverse ecosystem of Quarkus components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'319e3eed-422a-4ce3-a304-6ead2089539a', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Discuss the consistency model of Redis when using asynchronous replication.', N'Senior', N'Redis provides eventual consistency in a distributed setup because data is propagated to replicas asynchronously after the master processes the write. This means that a read from a replica might return stale data if the replication lag is high, sacrificing strong consistency for low latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a96b0ea-986a-429c-90ee-6ead4d562f23', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is a ''Memo'' and when should it be used?', N'Middle', N'A Memo is a reactive primitive that caches the result of a computation based on its dependencies. It should be used for expensive derived calculations to prevent redundant re-evaluation when the underlying signals update.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9ad1a68-3ab1-41ff-a67f-6eaf21a6dc68', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you account for ''context switching'' costs when estimating the capacity of a team working on multiple parallel streams?', N'Senior', N'I apply a productivity discount factor based on the number of concurrent workstreams, as context switching introduces cognitive load and overhead. By transparently incorporating this efficiency loss into the planning process, I can provide more accurate timelines that reflect the reality of multi-tasking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80438e0f-904f-47d8-9502-6eaffb7f676b', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a Write-Ahead Log (WAL) and why is it critical for PostgreSQL performance and reliability?', N'Middle', N'WAL is a log file that records all data modifications before they are applied to the actual data files. It ensures data integrity in the event of a crash by allowing the system to replay transactions upon restart, while also improving performance by flushing changes to disk sequentially rather than randomly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c6e7ece-c6af-48a4-bbf6-6eb18736a858', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you perform testing in vuejs?', N'Fresher', N'You can perform testing in two ways, 1. Using vue-cli: It offers pre-configured unit testing and e2e testing setups 2. Manual setup: You can manually setting up unit tests for *.vue files using either mocha-webpack or jest', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96776083-13a3-42dc-947d-6eb273a42afd', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the ''attr_accessor'' method used for?', N'Junior', N'The ''attr_accessor'' method is a shortcut that automatically generates both reader and writer methods for an instance variable. It eliminates the need to manually write methods to retrieve or update the value of an object''s attribute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da7d9e09-cf8a-4687-a99e-6eb4a2baa2ad', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is ''Saga'' pattern in the context of distributed transactions?', N'Middle', N'A Saga is a sequence of local transactions where each step updates the database and triggers the next step. If a step fails, the Saga executes a series of compensating transactions to undo the changes made by previous steps, providing an alternative to long-running distributed locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc7f302f-d7db-4f94-b6cb-6eb70350d0f8', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the purpose of vertical partitioning?', N'Middle', N'Vertical partitioning involves splitting a table''s columns into separate tables based on usage frequency. This allows you to store rarely accessed columns on slower storage or separate them to reduce row size, which can improve query performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2b32f62-7ecb-4135-9220-6eb887fc3f4d', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is a Redirect in Gin?', N'Fresher', N'A redirect is a mechanism where the server tells the client''s browser to go to a different URL. Gin provides a simple method on the context to perform these HTTP redirects efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6c5c9dc-23ea-4433-9531-6eb9351f8b9a', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte ensure that derived state is computed efficiently?', N'Senior', N'Derived state is computed lazily or reactively based on the dependency graph constructed by the compiler. By tracking which variables contribute to a specific derived value, Svelte ensures that calculations only occur when the underlying source data actually changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cc4b22a-e3c2-4b93-9268-6eba00ba84e0', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the purpose of a ''binary search'' approach to debugging?', N'Intern', N'A binary search approach involves dividing the system or the codebase into two halves to determine which section contains the error. By repeatedly splitting the suspected area in half, you can quickly locate the root cause in a large system with minimal effort.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78c73941-e6ae-484f-8184-6eba93f7b4e1', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the function of the ''Request Services'' container in the context of middleware?', N'Senior', N'The request services container provides a scoped dependency injection container for the current HTTP request. It allows middleware and controllers to resolve services that are scoped to the lifetime of the request, ensuring data consistency throughout the entire request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1741a58-f260-4fe7-8c91-6ebe7f33c77c', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the difference between a pointer receiver and a value receiver in method definitions?', N'Middle', N'A value receiver operates on a copy of the object, which is safe but can be expensive for large structs and does not allow modifications to the original. A pointer receiver operates on the actual object, allowing for state changes and better performance for large types by avoiding copying.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d2cead5-56d0-46f2-b7cb-6ec0d649ec11', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What happens if you perform a join without a join condition?', N'Junior', N'Without a join condition, the database performs a Cartesian product, also known as a cross join. This results in a combination of every row from the first table with every row from the second table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57ba0d09-4e86-4fe4-a0aa-6ec283db9850', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Explain the concept of ''silent'' classes in Sass and their utility in library development.', N'Senior', N'Silent classes, defined with a percent sign, are not compiled into the final CSS unless they are explicitly extended. This makes them ideal for building utility libraries or base classes that provide common styles without cluttering the compiled output with unused selectors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b85de0b3-eb84-4978-8c7a-6ec465d5f17e', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is Artisan in Laravel?', N'Intern', N'Artisan is the command-line interface included with Laravel. It provides a number of helpful commands for your use while developing your application, such as creating controllers, running migrations, and clearing caches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65cb3932-49a7-4592-8e21-6ec5c8f53146', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Describe the benefit of using ''pipelining'' in Redis.', N'Senior', N'Pipelining allows a client to send multiple commands to the server without waiting for the response to each individual request, and then read the replies in a single step. This significantly reduces the network round-trip time, which is often the bottleneck in high-throughput Redis applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9d7fd21-c8fd-40c6-a2bd-6ec5f6795824', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between HTMLCollection and NodeList?', N'Fresher', N'HTMLCollection An HTMLCollection is a list of nodes. An individual node may be accessed by either ordinal index or the node''s name or id attributes. Collections in the HTML DOM are assumed to be live meaning that they are automatically updated when the underlying document is changed. NodeList A NodeList object is a collection of nodes. The NodeList interface provides the abstraction of an ordered collection of nodes, without defining or constraining how this collection is implemented. NodeList objects in the DOM are live or static based on the interface used to retrieve them Difference An HTMLCollection is a list of webpage elements (div, p, ul, li, img objects, etc…) which form part of the DOM, and are of a specific node type usually referred to as an element node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7ba3c98-e273-4f5e-8dba-6ec779419523', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask''s application context differ from the request context, and why is this separation important?', N'Senior', N'The request context tracks data specific to a single HTTP request, like headers and parameters, while the application context tracks project-level data, such as configuration and database connections. This separation allows Flask to handle multiple requests concurrently without polluting the global state, ensuring thread safety and easier testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d699df2-b17a-41dc-8d3b-6ec8309f926c', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the difference between client-side and server-side validation?', N'Fresher', N'Client-side validation provides immediate feedback to the user, improving the experience by catching errors before submission. Server-side validation is mandatory for security, as it ensures that data integrity is maintained even if someone bypasses the front-end checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2af4aadf-61a3-4089-a480-6ec89666c52b', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the difference between a function and a mixin regarding the return value?', N'Middle', N'A mixin does not return a value but rather outputs a block of CSS code. A function is explicitly designed to return a single value, such as a calculation result, which is then used as a property value in a CSS declaration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c22f5465-5737-43ba-a233-6ecbcdb8e003', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'When would you choose a document-oriented database over a relational one?', N'Junior', N'You would choose a document database when your data is hierarchical, evolving, or does not have a strictly uniform structure. It is well-suited for content management systems or applications that require fast iteration of data models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42e636ca-97cd-44a6-8cbd-6ece5910dbb1', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the ''Conditional'' attribute affect method execution?', N'Senior', N'The ''Conditional'' attribute tells the compiler to omit calls to the decorated method if the specified preprocessor symbol is not defined. This allows for cleaner diagnostic or logging code that disappears entirely from production builds without needing manual preprocessor directives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'927de796-3c8f-4359-81a8-6ed15286b640', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you choose between an iterative and a waterfall approach to a project?', N'Fresher', N'Iterative approaches are better for projects with changing requirements or high uncertainty, allowing for frequent feedback. Waterfall is only suitable for small projects where requirements are clearly defined and unlikely to change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'668d08be-e30d-4fc6-92a6-6ed17230c232', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does Node.js handle backpressure in streams, and why is it important for memory management?', N'Senior', N'Backpressure occurs when a readable stream produces data faster than a writable stream can process it, potentially causing memory buffers to grow uncontrollably. Node.js handles this by signaling the readable stream to pause until the writable stream''s internal buffer drains, preventing heap overflow and application crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b09e68e-c233-47f9-9d34-6ed1e7e1108e', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is a vector in the context of R?', N'Intern', N'A vector is the most basic data structure in R, representing an ordered collection of elements of the same data type. It can store numeric, character, or logical values, and it is the building block upon which more complex data structures are constructed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85879ff6-1faa-4626-8de8-6ed31c4ddf92', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the purpose of a Load Balancer in a distributed architecture?', N'Middle', N'A load balancer acts as a reverse proxy that distributes incoming network traffic across multiple backend servers. Its primary goal is to optimize resource use, maximize throughput, minimize response time, and ensure high availability by routing requests away from failed nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9cf252a-1bce-4468-95d1-6ed378ffbdbd', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain the concept of ''CSS-in-JS'' and its main trade-offs.', N'Middle', N'CSS-in-JS involves defining styles within JavaScript files, often leveraging component-based architecture to scope styles automatically. The trade-offs include improved modularity and dynamic styling, balanced against the runtime overhead of injecting styles and increased bundle sizes. It also removes the traditional separation of concerns between structure and presentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89300133-75b8-43cb-88a0-6ed95b88e0c5', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Is Litestar strictly typed?', N'Fresher', N'Litestar is designed to be highly compatible with Python''s static type checking. While it does not enforce types at compile time, it uses type annotations at runtime to perform validation and reflection, promoting a ''type-safe'' development style.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
