INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67ace027-9f93-4b1e-a217-6edc9db30156', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle error propagation and response formatting?', N'Senior', N'FastAPI uses exception handlers to catch specific errors and convert them into standard HTTP responses, ensuring consistent error contracts across the API. This decoupling allows business logic to raise domain-specific exceptions, which are then translated into meaningful API responses without polluting the core service code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55b1413b-0405-4343-8427-6edd01851d85', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the difference between move and copy semantics in Rust?', N'Junior', N'Move semantics transfer ownership of a value from one variable to another, invalidating the original variable. Copy semantics occur for types that implement the Copy trait, where the value is duplicated instead of moved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d78c2c2-9755-43c8-a2ab-6edd662ac45d', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How can you group routes together in Chi?', N'Fresher', N'Chi allows the use of route groups using the Route method, which creates a sub-router for a specific path prefix. This is useful for grouping related endpoints, such as all API v1 routes, and applying specific middleware to that entire group.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4408e679-863e-446f-bfa6-6edf2764ae2c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is optional chaining in JavaScript?', N'Intern', N'Optional chaining Optional chaining is a feature in JavaScript that allows you to safely access nested object properties or functions without worrying about whether the intermediate properties exist or not. It uses the ?. operator to check for nullish (null or undefined) values and short-circuits the expression if it encounters one. Optional chaining was introduced in ECMAScript 2020 (ES11) and is supported in most modern browsers, but not in older ones. To use it in older browsers, you can use a transpiler like Babel, or write your code with alternative techniques like conditional statements or the && operator. Example', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f6a254a-13ff-4e7e-a6d6-6ee15af90037', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How do you monitor and debug performance bottlenecks in a large-scale Next.js application?', N'Senior', N'Performance monitoring should include tracking Core Web Vitals, analyzing bundle sizes with tools like webpack-bundle-analyzer, and using distributed tracing to identify slow server-side data fetching. Monitoring the cache hit ratio for ISR and static pages is also vital for identifying unexpected server load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3281e644-cae3-4f38-a158-6ee6cc476fb6', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the ''app.set'' method used for?', N'Intern', N'The app.set method is used to assign a setting name to a value. It is commonly used to configure application-level settings, such as the view engine, the directory for views, or environment-specific configurations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4ec0bb2-8db7-4ae5-9b2b-6ee8a876a631', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What architectural considerations should be made when using Chi in a serverless function environment?', N'Senior', N'In serverless environments, cold start times and memory footprint are critical; Chi''s minimal dependency tree and low overhead make it an excellent choice. Its lightweight nature ensures that the routing initialization logic does not add significant latency to the execution of the function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2485a30b-9bbe-482f-84e8-6eec65356af5', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket prevent common web vulnerabilities like CSRF or XSS by default?', N'Senior', N'Rocket provides a robust framework that encourages secure practices, such as strict type enforcement and template auto-escaping. While it does not automatically include specific anti-CSRF tokens, it offers the necessary hooks and middleware capabilities to implement these security measures consistently across all routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'953153de-1324-4724-98f9-6eed28b6f9a6', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does pointer arithmetic work in C?', N'Middle', N'Pointer arithmetic is scaled by the size of the data type the pointer points to. When you increment a pointer, the address increases by the size of the underlying type, ensuring that the pointer correctly navigates through contiguous memory structures like arrays.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f34fd788-b289-469c-a4c1-6ef328dd9579', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Explain the significance of the Fastify encapsulation model in large-scale applications.', N'Senior', N'Encapsulation allows developers to create isolated plugin contexts where specific configurations, decorators, and hooks are scoped only to the registered plugin and its children. This prevents side effects and global namespace pollution, enabling teams to build modular, maintainable microservices where components can be safely composed without unintended dependency leakage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'446fa4c1-b20d-47d3-afae-6ef69b2948c6', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle data validation for incoming requests?', N'Junior', N'Litestar uses Pydantic or Msgspec to define data schemas. When a request arrives, the framework automatically validates the body, path parameters, or query parameters against these schemas, raising an error if the data is malformed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d7ca5eb-baa3-41c9-93a1-6ef7cfbc578d', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does Python''s ''import'' mechanism work, and what is the role of ''sys.modules''?', N'Senior', N'When a module is imported, Python checks ''sys.modules'' to see if it has already been loaded. If not, it searches the file system, compiles the source to bytecode if necessary, and executes the module code in a new namespace before storing the result in ''sys.modules'' for subsequent imports.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fff54e12-8ddd-4e2f-8072-6ef87dcdabe9', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the primary purpose of a Gin router?', N'Intern', N'The router in Gin is responsible for mapping incoming HTTP requests to specific handler functions based on the request method and URL path. It uses a radix tree-based algorithm to perform fast and efficient path matching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f70c8e27-cc93-4cd5-a2ca-6ef96c6f5a4b', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the cost-benefit of refactoring a legacy module versus building a new one?', N'Middle', N'I assess the technical debt, maintenance overhead, and the frequency of bugs in the current module. I compare the long-term operational savings of a refactor against the immediate development cost and risk of introducing regressions, choosing the option that offers the best return on investment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'187f2355-52bd-41e9-9a0d-6ef9d309d4e9', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the impact of a third-party API update on your system stability?', N'Senior', N'I assess the API''s change log and conduct a dependency analysis to determine which system modules are exposed. I then mandate a regression testing phase and implement circuit breakers to insulate our system from any potential breaking changes or outages in the external service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acddb48f-cf4c-454e-9630-6efb489d0a32', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js handle partial prerendering and what are its performance implications?', N'Senior', N'Partial Prerendering allows a page to serve a static shell immediately while deferring dynamic content to be streamed in later. This improves performance by providing a fast First Contentful Paint while maintaining the ability to serve personalized or real-time data within the same request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8888c22c-fc96-443b-8801-6eff2b83115b', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of the ''require'' and ''include'' statements, and how do they differ?', N'Junior', N'Both statements are used to import external files into a script. The primary difference is that ''require'' will throw a fatal error and stop script execution if the file is missing, whereas ''include'' only produces a warning and allows the script to continue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c25caed9-db70-448e-80af-6efff43be556', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle ref management?', N'Middle', N'Preact supports the standard ref pattern, allowing direct access to DOM nodes or class instances. It handles the lifecycle of these refs automatically, ensuring they are attached after mounting and cleaned up when components are unmounted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b74c7ebd-9df2-48ac-b795-6f038aa11eef', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the role of a Content Delivery Network (CDN) in scaling web applications?', N'Middle', N'A CDN caches static assets like images, CSS, and JavaScript files on globally distributed edge servers. This reduces the distance between the user and the content, improving load times and reducing the bandwidth consumption of the origin server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae523765-994f-435c-ac38-6f0c192b18d7', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is meant by ''concurrency'' in the context of Fiber?', N'Intern', N'Fiber leverages Go''s ability to handle many connections concurrently using goroutines. Because it is built on Fasthttp, it is highly efficient at managing these concurrent requests without exhausting system resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
