INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'293f3acd-a299-4d82-a9b8-6f1bc0b14052', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a one-to-one relationship?', N'Intern', N'A one-to-one relationship occurs when a single record in one table is associated with only one record in another table. For example, a person might have only one unique social security number.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db54409e-e252-4eaa-89b7-6f1e8e8b2f3c', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using a monolithic architecture versus microservices for a startup product?', N'Junior', N'A monolith is easier to develop, deploy, and debug in the early stages due to its simplicity and lack of network overhead. Microservices offer better scalability and independent deployment cycles for large teams, but they introduce significant operational complexity and the challenge of distributed system management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1303909-e49e-496e-b5d6-6f224a05eaa6', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is horizontal scaling in the context of NoSQL?', N'Intern', N'Horizontal scaling, or scaling out, involves adding more servers to a distributed system to handle increased load. This is a primary feature of many NoSQL databases, allowing them to manage massive datasets by spreading data across multiple nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14859899-cf50-4c71-b5c5-6f24d6fbaa11', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between ''debouncing'' and ''throttling'' in the context of event handling, and when should each be used?', N'Senior', N'Debouncing postpones execution until a period of silence has passed, making it ideal for search inputs or window resizing. Throttling limits the frequency of execution to a fixed rate, which is better suited for scroll events or mouse tracking where consistent feedback is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0553e344-d50f-4289-ae63-6f28ce140212', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What happens when DOCTYPE is not given?', N'Junior', N'The web page is rendered in quirks mode. The web browsers engines use quirks mode to support older browsers which does not follow the W3C specifications. In quirks mode CSS class and id names are case insensitive. In standards mode they are case sensitive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
