INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c90e0fd7-d4ad-4e71-8286-6f35133d31ed', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a primary key in PostgreSQL?', N'Intern', N'A primary key is a column or a set of columns that uniquely identifies each row in a table. It cannot contain null values and must be unique across the entire table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db6fe800-86ab-428e-acbd-6f375e54c61f', N'075b8862-431c-4678-9767-f55359758a4a', N'What are vuex getters??', N'Intern', N'Vuex getters acts as computed properties for stores to compute derived state based on store state. Similar to computed properties, a getter''s result is cached based on its dependencies, and will only re-evaluate when some of its dependencies have changed. Let''s take a todo example which as completedTodos getter to find all completed todos, Note: Getters receive state as first argument.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9e43615-8009-4fb9-b1b9-6f3c76173bb2', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How do Litestar''s ''Middleware'' components interact with the ASGI server''s event loop?', N'Senior', N'Middleware components in Litestar are ASGI-compliant, meaning they wrap the application and manipulate the scope, receive, and send channels. They operate within the same event loop, so any blocking synchronous code inside middleware will stall the entire event loop, negatively impacting all concurrent requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60552516-5c5f-43df-9a81-6f3d289fa815', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Describe the architectural pattern of ''Cache Hierarchies'' and their primary use case.', N'Senior', N'Cache hierarchies involve layering caches with different speeds and capacities, such as L1 (local memory), L2 (distributed cache), and L3 (persistent storage). This pattern balances extreme low-latency access for hot data with the ability to handle larger working sets that cannot fit in the fastest storage tier.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'664e61c8-c3b8-4c12-8c34-6f404688496c', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the purpose of the ''hono/jsx'' package?', N'Intern', N'The ''hono/jsx'' package provides a lightweight JSX engine that allows developers to write HTML templates directly within their code. It is designed to be very fast and does not require a heavy virtual DOM implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8971feaf-83f9-493c-b6d3-6f40a2422a91', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the significance of the ''this'' keyword in arrow functions compared to standard functions regarding context binding?', N'Senior', N'Arrow functions capture the ''this'' value from the surrounding lexical scope at the time of definition, making them immutable to standard binding methods. Standard functions define ''this'' based on how the function is invoked, which provides dynamic context but often requires explicit binding or closure workarounds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69164f10-55aa-44f4-8e45-6f4619170d53', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum leverage Rust''s type system for request handling?', N'Junior', N'Axum uses Rust''s type system to ensure type safety during request processing. By defining parameters in handler functions, the framework enforces that the incoming request data matches the expected data structures at compile time or during extraction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58670503-048e-469c-aef8-6f4931ff8924', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the primary drawback of using jQuery''s data() method for storing state on DOM elements?', N'Senior', N'Storing data directly on DOM nodes creates hidden memory overhead and makes the state difficult to track or serialize compared to a centralized JavaScript object store. Furthermore, it tightly couples UI elements to application logic, complicating unit testing and state debugging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0f9b771-0b94-453c-95c0-6f50678b2803', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a Polyfill?', N'Intern', N'Polyfill A polyfill is a piece of code (usually a JavaScript library) that provides modern functionality on older browsers that do not support it. It is a way to bring new features to old browsers by mimicking the behavior of modern JavaScript APIs. For example, Object.values() was introduced in ES2017 and is not supported in some older browsers such as Internet Explorer and Safari 9. However, you can use a polyfill to add support for it in older browsers. Example This code checks if the Array.prototype.includes() method is available in the current environment, and if not, it provides an implementation of the method that emulates the behavior of the modern API. This allows you to use the Array.prototype.includes() method in older browsers, even though it is not natively supported.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bcd3c47-c99c-4040-8c1f-6f5250706dd9', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What are the advantages of using Echo''s ''Bind'' over manual JSON unmarshaling?', N'Middle', N'Echo''s Bind method is content-type aware, automatically selecting the appropriate decoder based on the request headers like JSON, XML, or form-data. This abstraction makes the handler code cleaner and allows for seamless support of multiple data formats without changing the business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd740d291-a803-493e-ae9b-6f53a5f49acc', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is middleware in FastAPI?', N'Intern', N'Middleware is a function that runs for every request before it reaches the specific endpoint and for every response before it is sent to the client. It is commonly used for tasks like logging, adding security headers, or measuring request time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c1e62ba-0b87-41f5-8456-6f55721facaa', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are the trade-offs of using reference counting (Rc/Arc) compared to standard stack-based ownership?', N'Senior', N'Reference counting enables shared ownership, allowing multiple parts of a program to own the same data, which is essential for complex graph-like structures. The trade-off is the runtime overhead of atomic or non-atomic reference counter updates and the potential for memory leaks if cyclic references are created.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a688df49-16ae-4348-9ee5-6f55e23decad', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery''s ''filter'' method contribute to efficient DOM selection?', N'Middle', N'The filter method allows you to narrow down an existing collection of elements based on specific criteria without performing a new DOM traversal. This is more efficient than re-running a full selector query to find elements within an already cached set.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'980c455a-bad4-49b3-9e9a-6f565e43f617', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Why is Hono considered ''fast''?', N'Fresher', N'Hono is fast because of its minimalist design and highly optimized router implementation. By minimizing the overhead and avoiding heavy dependencies, it performs fewer operations per request compared to larger, feature-heavy frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ecdde37-8076-419f-baaa-6f58d2cbe8bf', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is a Micronaut Feature?', N'Intern', N'A feature is a predefined module or capability that can be added to a Micronaut project, such as support for a specific database, messaging system, or security provider. Features are typically selected during project generation to include necessary libraries and configurations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2edf1005-00f2-4608-92b1-6f5cd6a4ee74', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does Rails handle sessions?', N'Fresher', N'Rails sessions allow you to store small amounts of data across multiple requests from the same user. By default, they are stored in cookies on the client side, allowing the application to remember user state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3186ae2-e930-42e7-8f0c-6f5dc44f718f', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What are the performance implications of ''Cache Fragmentation'' in long-running processes?', N'Senior', N'In-memory caches can suffer from memory fragmentation where large, unused gaps prevent the allocation of new objects, eventually leading to performance degradation or OOM errors. Using slab allocators or pre-allocated object pools can help stabilize memory usage in high-frequency caching systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcf4de0e-a103-4e0d-ac2a-6f5f26266960', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the consequence of using Alpine.js for complex data-heavy applications?', N'Senior', N'For data-heavy applications with complex state transitions, the lack of a formal architectural pattern in Alpine can lead to ''spaghetti code'' where logic is scattered across HTML attributes. It is generally better to use a structured framework like Vue or React for applications where the business logic outweighs the UI interactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9d390e9-53d4-46b7-95b6-6f60d28baaaf', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is a mount point in Rocket?', N'Junior', N'A mount point is a base URL path under which a set of routes is grouped. It allows you to organize your application by prefixing related routes, such as grouping all API routes under a single base path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f5b8d49-4f8b-4b24-a58f-6f638efba592', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide between using an existing library versus building your own solution?', N'Fresher', N'I evaluate the cost of maintenance, the reliability of the library, and whether it perfectly matches my requirements. If the library is widely supported and solves the problem efficiently, it is usually better to use it rather than reinventing the wheel.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
