INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6991415b-450e-44f2-ae2e-6f651aeea7a2', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If a server is running out of disk space, what is your step-by-step approach to diagnosing the cause?', N'Intern', N'First, I would use system utilities to identify which directories or partitions are consuming the most space. Then, I would look for large log files, temporary caches, or orphaned data that can be safely cleared. Finally, I would analyze whether the storage growth is an anomaly or a sign that the system needs a capacity upgrade.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdf65b28-61a8-40d0-8fa7-6f68cc260506', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of Phoenix Plugs?', N'Fresher', N'Plugs are small, reusable modules that perform transformations on web requests and responses. They act as a pipeline, allowing developers to modularize functionality like authentication, logging, or session management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0707dca-b391-460b-b23d-6f73f060ebe3', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does the ''any'' type represent in TypeScript?', N'Intern', N'The ''any'' type tells the TypeScript compiler to disable type checking for a specific variable or expression. It essentially allows a value to take any form, which bypasses the benefits of static typing and should be avoided whenever possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3582e937-bc70-4948-9a17-6f751c37e471', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What are the benefits of using Spring Cloud Config over local property files?', N'Senior', N'Spring Cloud Config centralizes configuration management across multiple services, allowing for dynamic updates without restarting applications. It supports version control via Git and provides a secure way to manage sensitive credentials across different environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bdbb318-4f50-449c-841d-6f7877830495', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Explain the role of the ''h'' function in Preact and how it relates to the Virtual DOM.', N'Senior', N'The ''h'' function, or hyperscript, is the factory function that creates VNodes, which are plain JavaScript objects representing the UI tree. It serves as the bridge between JSX transpilation and the VDOM, allowing the renderer to efficiently compare tree structures during the reconciliation process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed19d3cd-f0c7-43da-a2eb-6f7ab4656088', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What are Go''s key features compared to other programming languages?', N'Fresher', N'Go (Golang) offers several features that set it apart from other programming languages: 1. Concurrently Using Goroutines and Channels: Go excels in multi-threading and concurrency management through goroutines (lightweight threads) and channels (communication mechanism between goroutines). 2. Simplicity in Syntax: Go employs C-like syntax with a subtle touch of its own design. While the language sets clear style guidelines, it''s more lenient compared to others, such as Python. 3. Goroutines: These lightweight threads serve for concurrent execution. Go''s run-time scheduler maps them to OS threads, optimizing performance. 4. Robust Standard Library: Go''s standard library is extensive and maintains a consistent design, making it more developer-friendly. 5.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16cd07ae-606e-4af9-a969-6f7e026cee63', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut manage profiles?', N'Intern', N'Profiles allow you to define different configurations for different environments, such as development, test, and production. You can use separate configuration files to override settings based on the active profile.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f41b3d06-6a4b-44e5-9a1f-6f7f81b30b1e', N'a2838158-7305-480a-b22b-4dc35776b400', N'Explain the CAP theorem and its trade-offs.', N'Middle', N'The CAP theorem states that a distributed data store can only provide two of three guarantees: Consistency, Availability, and Partition tolerance. In the presence of a network partition, a system must choose to either cancel the operation to preserve consistency or proceed to maintain availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df56b04a-6133-44a6-b88d-6f800596de7c', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the role of the Data Protection API in ASP.NET Core?', N'Middle', N'The Data Protection API provides a secure way to encrypt and decrypt sensitive data, such as authentication cookies or CSRF tokens. It manages key rotation automatically, ensuring that cryptographic keys are protected and updated over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'132e6692-151d-4979-9735-6f86da50e161', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does the Preact router differ from standard React-based routing solutions?', N'Senior', N'The Preact router is designed to be as minimal as possible, focusing on basic path matching and component switching without the overhead of heavy state management. It is optimized for speed and simplicity, whereas React routers often include extensive features for deep nesting and history management that are not always needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c855e3ca-1b1a-47b7-9057-6f87404fb2be', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Why would you use a ''Seeder'' in AdonisJS?', N'Junior', N'Seeders are used to populate the database with initial or dummy data. They are helpful for setting up default application values or creating test data for development environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e2acdd7-fe10-4230-a46e-6f8805298181', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does the Python virtual machine handle variable-length arguments in function calls?', N'Senior', N'The interpreter packs positional arguments into a tuple and keyword arguments into a dictionary before passing them to the function frame. This abstraction allows for flexible function signatures while requiring the runtime to perform additional dictionary lookups and tuple unpacking overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ad7ed6d-1096-407a-8c1b-6f8b5d97d5c7', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are Webpack ''resolve'' extensions?', N'Junior', N'The resolve extensions option tells Webpack which file extensions to attempt to resolve automatically. This allows you to import files without writing the extension, such as importing a file as ''import App from ''./App''', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9811625-85ed-408e-afbc-6f8b6c72bb53', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you handle transactional consistency across multiple microservices when designing a single API endpoint?', N'Senior', N'Avoid distributed transactions like 2PC, which impact availability. Instead, use the Saga pattern where a series of local transactions are executed, supported by compensating transactions to roll back state if a subsequent step fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a959abe-c129-4d08-81d4-6f8d983383e8', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Explain the concept of ''Filter Pipelines'' in MVC and how they differ from middleware.', N'Senior', N'Filters run within the MVC action invocation pipeline, providing hooks to run logic before or after specific actions, controllers, or results. Unlike middleware, which operates on the entire HTTP request pipeline, filters are context-aware of the MVC routing and action execution lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cb648ed-2f12-46c5-aba2-6f9135e56789', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How do R namespaces prevent ''shadowing'' during package development?', N'Senior', N'Namespaces explicitly define which symbols are exported and which are imported, creating a private scope for each package. This ensures that even if a user defines a function with the same name as one in a library, the package''s internal calls will resolve to its own version, maintaining the integrity of the logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'352eef9c-dc58-44b0-9929-6f93eb9d4962', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Explain the trade-offs of using read replicas in a master-slave architecture.', N'Senior', N'Read replicas improve read scalability and provide high availability through failover, but they introduce replication lag, which can lead to eventual consistency issues. Developers must decide whether to route traffic to the primary for strong consistency or accept potentially stale data from replicas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65802bd3-fe8b-48c3-b6b3-6f986d3d3473', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the purpose of the ''hooks.server.ts'' file in an enterprise-grade SvelteKit application?', N'Senior', N'It serves as the central entry point for request interception, allowing for the implementation of cross-cutting concerns like session management, authorization, and custom error handling. By centralizing this logic, it ensures consistency and maintainability across the entire application''s request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9165b7f3-0709-4c0f-912e-6f99596c30a5', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why does Go prohibit circular dependencies in package imports?', N'Senior', N'Circular dependencies are disallowed to ensure a directed acyclic graph of package compilation, which simplifies the build process and dependency resolution. This constraint forces developers to modularize code effectively and prevents the complex, non-deterministic initialization issues seen in languages that allow cyclic imports. It also allows the compiler to optimize the linking phase by knowing the exact order of package initialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcb964d0-6d6b-4300-a687-6f9b699642dd', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does the error boundary differ from the catch boundary?', N'Middle', N'While catch boundaries handle expected responses with error codes, error boundaries catch unexpected runtime exceptions that occur during rendering or data loading. An error boundary acts as a last line of defense to prevent the entire page from crashing by rendering a fallback UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0db8bba5-dc02-462e-8f47-6f9e537e46c7', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the primary design philosophy of Go regarding language simplicity?', N'Intern', N'Go prioritizes simplicity by keeping the language specification small and avoiding complex features like inheritance, operator overloading, or pointer arithmetic. This design aims to make code easy to read, maintain, and compile quickly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cafa0a6-b99d-4484-882f-6f9f67492a41', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is a major downside of using GraphQL compared to REST?', N'Middle', N'GraphQL makes it difficult to implement traditional HTTP caching because all requests typically hit a single POST endpoint. Furthermore, designing effective query complexity analysis is necessary to prevent malicious users from executing resource-intensive nested queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4033786-7ef8-4bd3-887a-6fa4149f29cc', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Describe the security implications of the AdonisJS ''Bouncer'' system.', N'Senior', N'Bouncer provides a unified authorization layer that prevents logic fragmentation across the application. By centralizing access policies, it ensures that authorization checks are consistent, reducing the risk of insecure direct object reference (IDOR) vulnerabilities that often arise when developers manually implement checks in controllers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd88c5e63-8baf-4c92-a1c0-6fa71f748fcd', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the BEM methodology and why is it used in CSS architecture?', N'Middle', N'BEM stands for Block, Element, and Modifier and is a naming convention designed to make CSS code more maintainable and modular. It prevents naming collisions and clarifies the relationship between DOM elements, making it easier for teams to understand the structure and purpose of styles without deep CSS knowledge.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ff00373-f8ac-4b20-9943-6fa79e9edb67', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why does Swift''s ''Final'' keyword improve performance in class-based designs?', N'Senior', N'The final keyword prevents method overriding, which allows the compiler to bypass virtual table lookups and use static dispatch. By eliminating the need for dynamic dispatch, the compiler can inline the method call, significantly improving execution speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7985513d-e874-4a4c-aa69-6fa91bcd0552', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How do you decide between a monolithic and a microservices architecture for a new system?', N'Senior', N'Choose a monolith initially to optimize for rapid development and simplified deployment, especially when domain boundaries are unclear. Move to microservices only when organizational scaling requires independent team velocity, or when specific services demand distinct resource scaling and isolation guarantees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13cbae8f-a175-481f-907b-6fa95b8c4af7', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the role of the NestJS Execution Context in building platform-agnostic guards and interceptors?', N'Senior', N'The Execution Context provides a unified abstraction over different underlying platforms like Express or Fastify. By using the ''switchToHttp'' or ''switchToRpc'' methods, developers can write logic that is independent of the specific framework implementation, ensuring code portability across different transport layers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06980b9a-7221-4e17-85ef-6fb1f740f518', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the advantage of using Chi over a heavy framework?', N'Junior', N'The main advantage is the small footprint and lack of ''magic''. Because it adheres to the standard library, it is easier to understand, debug, and maintain without needing to learn a framework-specific way of doing things.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5220ec5-02b1-4780-90d3-6fb231ea323e', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the significance of version control in a collaborative development environment?', N'Fresher', N'Version control allows multiple developers to work on the same project simultaneously without overwriting each other''s work. It provides a history of changes, making it easy to track who made a change and to revert to a previous working state if a bug is introduced.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2c69350-09c4-4c3f-9df8-6fb372e8b778', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'In a distributed system, how do you handle clock skew between nodes when ordering events?', N'Senior', N'I avoid relying on system clocks for causal ordering and instead use logical clocks, such as Lamport timestamps or vector clocks. Alternatively, I use a centralized sequencer or a distributed consensus algorithm to provide a global ordering for critical events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b716a1e3-7192-4003-81d9-6fb70793103b', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How Do Implicits Work?', N'Fresher', N'Declaration You use the implicit keyword before the parameter and value declarations: Lookup Rules 1. Local Scope: If you provide an implicit declaration within the same scope where the function is being called, that declaration will be used. If there are multiple valid candidates, ambiguity arises. 2. Companion Objects: For implicit classes, the compiler checks the companion object of the class for implicit definitions. 3. Enclosing Scope: If no implicit is found in the local scope or the companion object for an implicit parameter, the compiler searches up the scope chain. Disambiguation When the compiler encounters multiple valid candidates for an implicit, it results in ambiguity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44abd24d-f452-4f10-beab-6fba11ea0bc6', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What happens if you have a syntax error in your Sass file?', N'Fresher', N'If there is a syntax error, the Sass compiler will stop the compilation process and throw an error message in your terminal or console. The CSS file will not be updated until the error is corrected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0b28434-3993-4ed2-a047-6fbd622066e8', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the purpose of the ''extension'' keyword?', N'Fresher', N'The extension keyword allows you to add new functionality to existing libraries or classes without modifying their original source code. This is useful for adding utility methods to built-in types like String or List.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27e85124-164e-4f5b-9a2a-6fbe1895fc21', N'4c000000-0000-0000-0000-000000000005', N'Explain the trade-offs between SAGA orchestrator-based and choreography-based sagas.', N'Senior', N'Orchestration provides a centralized controller, making it easier to manage complex workflows and visualize state, but it introduces a single point of failure and coupling. Choreography is decentralized and loosely coupled, offering better scalability, but it becomes difficult to track distributed state and debug as the number of services grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6be9182-3ec6-4b66-9250-6fbfd30ae85e', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How does service discovery improve the flexibility of a microservices system?', N'Middle', N'Service discovery allows services to find each other dynamically without hardcoding network locations, which is critical in environments with ephemeral instances or auto-scaling. It enables the system to maintain connectivity even when individual service instances are added, removed, or relocated during runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0af66e9e-ae9a-45dd-99ff-6fc0867f4340', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using feature flags versus separate branches for feature development?', N'Junior', N'Feature flags allow you to merge code to the main branch early, reducing ''merge hell'' and enabling gradual rollouts. The trade-off is the added technical debt of managing the flags and ensuring the code remains clean once the feature is fully launched.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3be5e92f-a791-49bb-a08b-6fc19d67d3c3', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does two-way data binding work in Alpine.js?', N'Fresher', N'Two-way data binding is achieved using the x-model directive. This directive synchronizes the value of an input element with a piece of data in your Alpine component, meaning changes to the input automatically update the data, and changes to the data update the input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79da057c-21b9-4367-9c69-6fc2712ab2b4', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch store data compared to a traditional RDBMS?', N'Fresher', N'Elasticsearch stores data as JSON documents rather than rows and columns. While RDBMS is optimized for transactional integrity, Elasticsearch is optimized for full-text search and analytical queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3132100a-0edf-4a63-b3d3-6fc39a7a4ef5', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of the HAVING clause?', N'Fresher', N'The HAVING clause is used to filter records after an aggregate function has been applied. It acts as a filter for the results generated by a GROUP BY clause, where the WHERE clause cannot be used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36d27275-9e68-410a-8ba8-6fc3c4451fd5', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What architectural patterns help avoid ''Mailbox Overflow'' in high-throughput Actix systems?', N'Senior', N'Developers can mitigate mailbox overflow by implementing dynamic load balancing across multiple actor instances, increasing buffer limits, or using external message queues like Redis to offload processing. Monitoring mailbox size is essential to identifying bottlenecks before they cause system instability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe1957d5-f4b6-4534-8ff6-6fc560d2c834', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of a PSR-7 Request/Response object, and why is it useful?', N'Middle', N'PSR-7 provides standardized interfaces for HTTP messages, allowing different PHP frameworks and libraries to communicate using the same request and response objects. This promotes interoperability, enabling the use of middleware that can be dropped into any compliant framework to handle tasks like authentication or logging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
