INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd1f6416-d33d-460e-8f23-6fc87fb115cb', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is the use of jQuery for layout calculations considered an anti-pattern in modern responsive design?', N'Senior', N'jQuery-based layout logic often forces synchronous reflows by reading and writing to the DOM in rapid succession, which is a major performance killer. Modern layouts should rely on CSS Flexbox, Grid, and media queries, which are handled by the browser''s optimized rendering engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
