INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42fe2946-fe20-4b24-a61f-6fdacd8e98c7', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are the semantic meanings for <section>, <article>, <aside>, <nav>, <header>, <footer> and how should each be used in structuring html markup?', N'Intern', N'* is used to contain introductory and navigational information about a section of the page. This can include the section heading, the author''s name, time and date of publication, , or other navigational information. * is meant to house a self-contained composition that can logically be independently recreated outside of the page without losing it''s meaning. Individual blog posts or news stories are good examples. * is a flexible container for holding content that shares a common informational theme or purpose. * is used to hold information that should appear at the end of a section of content and contain additional information about the section. Author''s name, copyright information, and related links are typical examples of such content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e30d068c-3ed0-46e8-96ff-6fdb83cf4d1d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the time required for a feature when you have little information about the underlying legacy system?', N'Middle', N'I would perform a time-boxed spike to explore the relevant modules and identify dependencies. This allows for a more informed estimate by uncovering hidden complexities or technical debt that would otherwise lead to an underestimation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22192cfd-2614-4106-a037-6fdf2bdfa88e', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between a shallow copy and a deep copy in Python?', N'Middle', N'A shallow copy creates a new object but inserts references into it to the objects found in the original, meaning nested objects are still shared. A deep copy recursively copies the original object and all objects found within it, ensuring complete independence from the original structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f04b813-4d0d-4608-a747-6fdf57661121', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why is the separation of ''Request'' and ''Data'' guards important for API security?', N'Senior', N'Separating these guards allows for the authentication of a request before the body is even read. This prevents large, potentially malicious payloads from being buffered in memory if the user is not authorized, providing a layer of protection against DoS attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b2d0cf8-1f91-4e58-b0bf-6fe2a59dc1a2', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Describe the mechanism of ''Transition'' in SolidJS and its impact on UI consistency.', N'Senior', N'Transitions allow for marking state updates as non-urgent, enabling the framework to render the new state in the background while keeping the current UI interactive. This prevents inconsistent UI states where part of the page updates while another part remains stale during a large data load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5aa9a20-ca1c-40c9-a1eb-6fe2ebb2b6aa', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why should you avoid hardcoding sensitive information like passwords or API keys?', N'Junior', N'Hardcoding sensitive information exposes credentials if the source code is ever shared or leaked. Instead, these values should be stored in secure environment variables or secret management services to keep them separate from the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baac9c27-e692-4a88-84e3-6fe38ce0e0a0', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the purpose of the Image component?', N'Intern', N'The Image component is an extension of the standard HTML image tag designed for automatic performance optimization. It automatically handles image resizing, compression, and lazy loading to improve page performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94e1719a-6531-4c83-91ac-6fea30e781cc', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why would you use an Ember Addon?', N'Fresher', N'An Ember Addon is a package of reusable code, such as UI libraries, testing tools, or integrations. Using addons allows developers to extend the functionality of their application without writing code from scratch, saving significant development time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffcbee5b-0954-4546-b52b-6fed9ef72a8a', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'When would you prefer using a ''Router'' over a ''Controller'' in Litestar?', N'Middle', N'A Router is typically used to group multiple controllers or sets of routes into a specific URL namespace. While a controller is best for grouping related endpoints, a router is better for organizing large, multi-versioned, or multi-service API structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc800924-074c-4124-9c6b-6ff05ae9ce16', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the Model-View-Controller (MVC) architectural pattern in Ruby on Rails?', N'Intern', N'MVC is a design pattern that separates an application into three interconnected components. The Model manages data and business logic, the View handles the user interface and display, and the Controller acts as an intermediary that processes user input and coordinates between the Model and the View.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dda598c4-235d-4bb7-8731-6ff3d42829c0', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why is it important to use the ''next/link'' component instead of a standard anchor tag for internal navigation?', N'Middle', N'The Link component performs client-side transitions, which prevents a full page reload and allows the browser to maintain the application state. It also automatically pre-fetches the linked page in the background as it enters the viewport, making navigation feel instantaneous.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67d8111d-8181-469b-817b-6ffc61cdffc6', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Describe the mechanism behind ASP.NET Core''s Options pattern and why it is preferred over raw configuration access.', N'Senior', N'The Options pattern uses strongly-typed classes to bind configuration settings, promoting separation of concerns and testability. It supports features like validation, post-configuration, and change tracking, which raw configuration access lacks, making it easier to manage complex settings across the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2c3ca6d-eb2c-46b6-a17f-6ffc7e73bc73', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the role of the ''Sized'' trait in generic programming?', N'Senior', N'The ''Sized'' trait marks types whose size is known at compile time, which is required for placing them on the stack. Most generics are implicitly ''Sized'', but developers can opt-out using ''?Sized'' to handle dynamically sized types like slices or trait objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac9bc48a-0fba-484c-a47f-6ffc91446967', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What are React Server Components and why are they used in Next.js?', N'Junior', N'Server Components are components that render exclusively on the server, meaning they do not send JavaScript to the client. This reduces the bundle size and improves performance because the client browser has less code to download and execute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a97823f6-2c96-4691-989a-6ffcb5cd4008', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your process for choosing between a third-party service and building a custom solution?', N'Junior', N'I assess whether the functionality is a core differentiator for our business. If it is a commodity task like authentication or payment processing, I prefer a third-party service to save development time and maintenance. If the feature is unique to our product''s value proposition, I recommend building it internally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82c57784-d17e-4ce3-9a66-6fff8cb31dee', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does the ''onMount'' lifecycle hook behave in SolidJS?', N'Middle', N'The onMount hook runs once after the component is rendered and the DOM elements are attached to the document. It is specifically designed for initialization tasks that require access to the DOM, such as measuring elements or integrating with third-party libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15ec4c70-3fdc-484c-8866-6fff9d7e9503', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Why is it generally discouraged to use mutable default arguments?', N'Middle', N'In Python, default arguments are evaluated only once at the time of function definition, not during each function call. If a mutable object like a list or dictionary is used as a default, all subsequent calls share the same instance, leading to unexpected state persistence. It is safer to use None as the default and initialize the mutable object inside the function body.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c1ce0f3-ec34-46a0-ba61-7001e5b02466', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why is it important to use the css tagged template literal?', N'Junior', N'The css tag ensures that styles are parsed once per component class rather than once per instance. This provides better performance and allows Lit to optimize the application of styles across multiple instances of the same component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
