INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cce0f45-2e91-44a1-ac08-70039456492b', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS handle routing?', N'Fresher', N'NestJS uses decorators like @Get, @Post, @Put, and @Delete on controller methods to define routes. When a request matches the path and method defined by these decorators, the corresponding method is executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92efed27-f2d3-4c42-8615-7006bb326b77', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is difference between append() vs appendChild()?', N'Fresher', N'* ParentNode.append() allows you to also append DOMString object, whereas Node.appendChild() only accepts Node objects. * ParentNode.append() has no return value, whereas Node.appendChild() returns the appended Node object. * ParentNode.append() can append several nodes and strings, whereas Node.appendChild() can only append one node. The main difference is that appendChild() is a DOM function meanwhile append() is a JavaScript function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2118b7ba-c9d9-4464-970b-7006f9ac571d', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What does it mean that Cassandra is a distributed database?', N'Intern', N'Being distributed means that Cassandra stores data across multiple nodes in a cluster. This architecture allows the system to scale horizontally by adding more nodes, ensuring data remains accessible even if individual nodes fail.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3c58140-d12d-49e5-b87b-70086aadee32', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are the architectural benefits of Svelte''s ''Tick'' function?', N'Senior', N'The tick function allows developers to wait for the next microtask after state changes have been flushed to the DOM. This is essential for scenarios where one must interact with the DOM immediately after a reactive update has been applied.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6af5f191-181e-47ba-a633-700a8a597e67', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a secondary index in a NoSQL database?', N'Fresher', N'A secondary index is a data structure that allows for efficient querying on non-primary fields. It enables searching by attributes other than the main key, though it may require additional storage and maintenance overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b59dba5b-c693-4ec2-a657-700d55ad8c5c', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the benefit of using the Express Router?', N'Intern', N'The main benefit is code organization and maintainability. By separating routes into different files, you prevent the main application file from becoming too large and complex, which makes the codebase easier to navigate and scale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71b10685-0fe9-46db-97c3-700d983ef2a6', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When considering data migration, what is the trade-off between a ''big bang'' cutover and a phased migration?', N'Senior', N'A ''big bang'' migration is faster and cheaper but carries high risk if something fails. A phased migration is safer and allows for incremental validation, but it significantly increases complexity due to the need for dual-writing and synchronization between old and new systems. I almost always choose phased migrations for mission-critical systems to minimize the blast radius of failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55c97dc0-c960-44ca-82af-700e13da6e6d', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the purpose of the App object in Fiber?', N'Junior', N'The App object is the main instance of the Fiber application. It is used to define routes, register global middlewares, configure settings, and start the HTTP server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a39ef44-87b4-4348-974c-700f4cd6728e', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the primary goal of testing in the software development lifecycle?', N'Intern', N'The goal of testing is to identify defects or unexpected behaviors in a system before it is deployed to users. By finding and fixing these issues early, we ensure the product is reliable, secure, and functions as intended.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a15a41c3-1975-408a-a873-70135c29f86b', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Compare the performance and architectural implications of using System.Text.Json versus Newtonsoft.Json in ASP.NET Core.', N'Senior', N'System.Text.Json is built into the framework with a focus on high performance and low memory allocation, leveraging Span and Utf8JsonReader/Writer. Newtonsoft.Json is more feature-rich and flexible regarding complex object graphs, but it generally incurs higher overhead and memory pressure compared to the optimized System.Text.Json.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'292a1609-14b0-4ab7-b914-70139aab498a', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is Astro SSR mode?', N'Fresher', N'SSR stands for Server-Side Rendering, which allows Astro to render pages on the fly when a user requests them. This is useful for dynamic content that changes frequently, such as user-specific dashboards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2260a59d-8e21-431b-8777-701438cf3376', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is Static Site Generation (SSG) in Nuxt?', N'Intern', N'SSG is a process where Nuxt generates all your pages as static HTML files during the build process. These files are then deployed to a server or CDN, resulting in extremely fast load times since no server-side logic is needed at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9b5d7d9-823e-4fef-bf3b-70158a4bc959', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Explain the significance of the update lifecycle in Lit components.', N'Middle', N'The update lifecycle ensures that component states are synchronized with the DOM efficiently. It batches property changes, runs the rendering process, and updates the DOM only when necessary, minimizing layout thrashing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'597dd8bf-aeee-4854-bdd8-7017703d45ab', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is a Reducer in the context of Redux?', N'Intern', N'A reducer is a pure function that takes the current state and an action as arguments and returns a new state object. It determines how the application state changes in response to actions sent to the store, ensuring that the state remains immutable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'856acad1-10d1-4569-b710-70179886a812', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of the ''inline'' keyword?', N'Intern', N'The inline keyword is a suggestion to the compiler to replace the function call with the actual code of the function body. This can eliminate the overhead associated with function calls, potentially improving performance for small, frequently called functions. The compiler may choose to ignore this suggestion depending on the complexity of the function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b4d20f0-4019-4c68-8668-7019c2b01500', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the significance of the Qwik City framework?', N'Middle', N'Qwik City is a meta-framework built on top of Qwik that provides essential features for production applications, such as file-based routing, layout management, and data fetching. It simplifies the development of complex web applications by providing a structured environment for server-side rendering and static site generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b658f34e-06d0-4416-a3ce-701a0cacea90', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why should you avoid performing side effects directly in the ''render'' method?', N'Middle', N'The render method is designed to be pure and should only describe the UI based on the current state. Performing side effects here can lead to infinite loops or inconsistent UI states, as render can be called multiple times during the lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69426450-51c3-41bf-90d7-701a53999a8f', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What are the memory management benefits of using Fastify''s schema compilation?', N'Middle', N'By compiling schemas, Fastify reuses the same validation logic across many requests rather than parsing and interpreting the schema structure on every call. This reduces garbage collection pressure and minimizes the memory footprint of the application under high load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11bb122d-136e-4d3e-9722-701f40bd68bb', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the purpose of the ''assets'' directory in a Nuxt project?', N'Intern', N'The assets directory is used to store uncompiled resources that need to be processed by build tools like Vite or Webpack. This typically includes files such as CSS stylesheets, SASS files, or images that require optimization and bundling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e44c8c9a-e74e-42e4-a342-701ffc16d34f', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of ''Validators'' in AdonisJS and how do they differ from simple type checking?', N'Middle', N'Validators provide a declarative way to enforce complex business rules and data constraints, such as uniqueness in the database or conditional field requirements. They offer more robust error reporting and structured input sanitization than standard TypeScript type checking, which only validates structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3539e530-fce2-4b4d-b64d-7020b0c3fd72', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Explain the role of ''Sidecars'' in service meshes for observability.', N'Senior', N'A sidecar proxy intercepts all network traffic for a service, allowing it to collect metrics, logs, and trace data without requiring application-level code changes. This standardizes observability across polyglot services and ensures consistent telemetry gathering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3548676f-579a-4484-a76c-7020ca4bdae1', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If a stakeholder requests a feature mid-sprint, how do you estimate its impact on the existing delivery schedule?', N'Middle', N'I would assess the complexity of the new request against the current sprint goals and determine if it can be accommodated without compromising quality. If it cannot, I would present a trade-off analysis, showing which existing items must be deprioritized or moved to a later sprint to maintain the committed delivery date.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
