INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc27f1b9-548f-40f4-a89f-7031d9cabfc0', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How can you use Docker Compose with NestJS, and what is its role in a multi-container setup?', N'Fresher', N'Docker Compose Docker Compose is a tool for defining and running multi-container applications. Compose simplifies the control of your entire application stack, making it easy to manage services, networks, and volumes in a single, comprehensible YAML configuration file. Then, with a single command, you create and start all the services from your configuration file. Here''s a basic example of a docker-compose.yml file for a NestJS application with a PostgreSQL database: In this example, there are two services: app and db. The app service is built using the Dockerfile in the current directory, and it exposes port 3000. The db service uses the postgres:13-alpine image and sets some environment variables to configure the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba0561a5-bee3-41c6-9c70-70327ff449e1', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are the scalability implications of SvelteKit''s ''prerendering'' at scale?', N'Senior', N'Prerendering creates static files that can be cached on CDNs globally, dramatically reducing server load and response times for high-traffic applications. However, at extreme scale, excessive build times for thousands of pages must be managed using partial prerendering or incremental static regeneration strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e9743f2-1083-4d5f-b1db-703aabaf1856', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Discuss the strategy for optimizing initial load time in a large-scale Ember application.', N'Senior', N'Performance can be optimized through lazy loading of routes or engines, code splitting, and using fastboot for server-side rendering. These strategies reduce the size of the initial bundle and improve the perceived performance by delivering rendered HTML to the browser faster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abedbd99-45d8-442d-97b4-703cea4764d0', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Describe the difference between ''ref'', ''in'', and ''out'' parameters in terms of memory semantics.', N'Senior', N'Ref parameters pass a reference to a variable, allowing modifications to propagate back to the caller. Out parameters are similar but require assignment before the method returns. In parameters provide read-only access by reference, allowing the compiler to optimize by avoiding defensive copies of large structs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd22edf5-695c-426a-b167-70406cd5edc8', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut differ from traditional frameworks like Spring Boot?', N'Intern', N'Traditional frameworks typically use reflection and dynamic proxies at runtime to manage dependencies, which can increase memory usage and startup time. Micronaut performs dependency injection and AOP using ahead-of-time compilation, resulting in faster startup and a smaller memory footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
