INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e07f7d2a-dff1-4fdf-9255-7041af206f50', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the difference between a Partition Key and a Sort Key in DynamoDB?', N'Intern', N'A Partition Key is a required attribute that determines the physical storage location of data, while a Sort Key is an optional attribute used to organize and query related items within the same partition. Together, they form the primary key of a table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
