INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6c0cef0-5806-41c2-9db3-70493c4e0775', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does Consistency mean in a database transaction?', N'Intern', N'Consistency ensures that a transaction brings the database from one valid state to another, maintaining all predefined rules and constraints. It prevents the database from being left in an invalid or corrupted state due to partial execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
