INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a83ed081-09b2-4c57-b9a1-704d6d9a3a69', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of cookies in PHP?', N'Fresher', N'Cookies are small files stored on the user''s computer by the browser. They are used to identify a user or remember preferences, and they persist even after the browser is closed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef4d15c0-1640-40ad-b39c-704d761830e9', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is oplog?', N'Intern', N'The OpLog (Operations Log) is a special capped collection that keeps a rolling record of all operations that modify the data stored in databases. MongoDB applies database operations on the primary and then records the operations on the primary''s oplog. The secondary members then copy and apply these operations in an asynchronous process. All replica set members contain a copy of the oplog, in the local.oplog.rs collection, which allows them to maintain the current state of the database. Each operation in the oplog is idempotent. That is, oplog operations produce the same results whether applied once or multiple times to the target dataset. Example: Querying The OpLog', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd46e7c7b-7052-4fbc-bf4b-704f42ba4434', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the primary architectural trade-off when using MDX instead of standard Markdown in Astro?', N'Senior', N'MDX allows the inclusion of interactive components inside content files, which adds significant power. However, it increases build complexity and bundle size, as the MDX compiler must handle component imports and state, which may lead to slower build times compared to plain, static Markdown.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9512c195-5743-4767-aec8-704fe877f667', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How do you ensure data durability in a distributed NoSQL system?', N'Middle', N'Durability is ensured by committing data to a write-ahead log or similar persistent storage before confirming a write, combined with replicating that data across multiple physical nodes. This ensures that even if a server fails, the data persists on other nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb9a0375-609c-43f2-b126-70538e7fc9f9', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is a closure in R?', N'Middle', N'A closure is a function that remembers the environment in which it was created, even after that environment has been removed from the call stack. This allows functions to maintain persistent state across multiple calls without relying on global variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5642deb2-e62f-4557-bafb-7055ed6dc799', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does the Query Optimizer determine the execution plan for a compound index?', N'Senior', N'The optimizer uses a trial-run approach where it executes multiple candidate plans in parallel for a limited duration. It selects the plan that completes the fastest and caches it for future use, occasionally re-evaluating if performance statistics or index structures change significantly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'786b3699-daeb-43fa-97c7-7056e6779b09', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the primary purpose of the ''createSignal'' primitive?', N'Middle', N'createSignal is the fundamental building block for state management in SolidJS. It returns a getter function for reactive access and a setter function for updates, allowing the framework to track dependencies automatically without needing a component re-render cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d2a8d16-b3d9-4527-9314-705c384c667f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Is Dart a statically typed or dynamically typed language?', N'Intern', N'Dart is a statically typed language, meaning the type of a variable is known at compile time. However, it also supports dynamic typing through the use of the dynamic keyword, allowing for more flexibility when needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5d234d7-59b5-4056-9aa4-705cd7b9278c', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust handle trait dispatch, and what are the performance trade-offs between static and dynamic dispatch?', N'Senior', N'Rust uses monomorphization for static dispatch, which generates specialized code for each type at compile-time, enabling aggressive inlining and optimization. Conversely, dynamic dispatch uses trait objects with vtables, which introduces a small runtime overhead for pointer indirection but allows for heterogeneous collections and reduced binary size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc19d6c6-5baa-41e6-b4e7-705da269f913', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does the read repair mechanism work in Cassandra and what are its trade-offs?', N'Senior', N'Read repair compares data versions across replicas during a read operation if the consistency level is met. If inconsistencies are found, the coordinator updates the stale replicas, which ensures eventual consistency but increases latency for the initial read request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77bb7d9d-a48a-470b-983c-705e8088613c', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Can you perform transactions in DynamoDB?', N'Middle', N'Yes, DynamoDB supports ACID transactions through TransactWriteItems and TransactGetItems APIs. These ensure that multiple operations across one or more tables succeed or fail as a single unit, providing atomicity, consistency, isolation, and durability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ecd3f3b-6969-47c5-8a18-705ebd5ab0ed', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux handle state immutability, and why is it critical for performance?', N'Senior', N'Redux relies on immutability to ensure that state changes are detectable via shallow equality checks. By preventing direct mutation, the framework allows UI components to perform efficient shallow comparisons, triggering re-renders only when the object reference changes, which is fundamental to React''s reconciliation process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd6bc9b6-9298-417c-a249-7060ecdd97fe', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is Qwik''s approach to ''Hydration'' considered an anti-pattern by its authors?', N'Senior', N'The authors argue that hydration is a workaround for the limitations of frameworks that require the full application tree to be present to become interactive. By contrast, Qwik views the browser as a stateless environment where the application state should be carried forward from the server, making the concept of ''hydrating'' redundant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
