INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17730f16-19b3-4ee4-b0d5-7061b0d094ea', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How do distributed caches like Redis improve scalability beyond just speed?', N'Senior', N'Beyond reducing response times, distributed caches act as a buffer that protects the primary data store from read-heavy workloads. This effectively reduces the load on the database, allowing it to dedicate more resources to write operations and critical transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
