INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db2535d5-5b4e-40ff-a427-70640a6aa6e8', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is Actix-web considered fast?', N'Fresher', N'It is considered fast because it is built on Rust''s high-performance runtime, uses an efficient asynchronous I/O model, and has minimal memory overhead. It avoids the garbage collection pauses that can impact other web frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38e17c0a-e60b-47e7-8a6f-7065561958be', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the features of stylelint?', N'Intern', N'Below are the list of major stylelint features 1. It has more than 160 built-in rules to catch errors, apply limits and enforce stylistic conventions 2. Understands latest CSS syntax including custom properties and level 4 selectors 3. It extracts embedded styles from HTML, markdown and CSS-in-JS object & template literals 4. Parses CSS-like syntaxes like SCSS, Sass, Less and SugarSS 5. Supports Plugins for reusing community plugins and creating own plugins', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3368533-2890-453d-a0b0-70659f99e554', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How do you ensure data integrity without foreign keys?', N'Middle', N'Since DynamoDB does not enforce referential integrity or foreign keys, integrity must be managed at the application level. Developers should use transactional operations to ensure atomicity or implement patterns like ''write-ahead logging'' to maintain consistency across related items.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
