INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'726682d1-c63c-4479-80cf-70684966b7a1', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'In what scenario would you choose Chi over a more feature-heavy framework like Gin?', N'Middle', N'Chi is ideal when you want to minimize dependencies and keep the application close to the standard library while still requiring advanced routing features. It is a better choice when you prefer composition over the ''batteries-included'' approach, as it does not enforce a specific project structure or unnecessary abstractions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46c28743-1070-430e-8a37-706a904e9741', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL ensure data consistency during a crash recovery?', N'Senior', N'During startup after a crash, PostgreSQL replays the WAL from the last checkpoint to ensure that all committed transactions are reflected in the data files. Any uncommitted transactions are rolled back using information stored in the transaction status log, ensuring the database returns to a consistent state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a40c5e7-8ff7-496d-8032-706b2d16a039', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Can you use Preact with existing state management libraries like Redux?', N'Junior', N'Yes, Preact is compatible with most React-based state management libraries. Since Preact''s API is designed to mirror React, libraries that rely on standard Context or Provider patterns will generally work seamlessly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce2c23f2-891b-478b-acba-706ca58224d4', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the difference between the dev mode and build mode in Vite?', N'Intern', N'Dev mode utilizes a local server that serves files individually via ES modules for fast feedback. Build mode uses Rollup to concatenate, minify, and tree-shake the code into a production-ready package.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b6e3234-35c8-4c7b-b566-706fbbc76b6c', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What happens if a node in a Cassandra cluster goes down?', N'Junior', N'If a node goes down, the other nodes in the cluster can take over its responsibilities based on the replication factor. The cluster continues to operate, and once the failed node returns, it can synchronize missing data from its peers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30ebeeae-8fb2-4802-a181-7072c1274233', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the purpose of the ''open'' keyword in Kotlin?', N'Junior', N'By default, Kotlin classes and methods are final, meaning they cannot be inherited or overridden. The ''open'' keyword explicitly marks a class or member as extendable, allowing other classes to inherit from it or override its behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b8a6f9a-cd65-4276-8808-70752900a365', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Describe the internal representation of an interface value in Go.', N'Senior', N'An interface value is represented as a two-word structure containing a pointer to the type information and a pointer to the actual data. The type information includes the method table, allowing the runtime to perform dynamic dispatch at invocation. This structure is immutable once assigned, ensuring that the dynamic type behavior remains consistent throughout the interface''s lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
