INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21d908b2-bef8-4c78-8a93-707dacbc56bd', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How does ''optimism bias'' affect the estimation process?', N'Fresher', N'Optimism bias leads people to underestimate the time and resources required for a task because they focus on the best-case scenario. I counteract this by consciously looking for potential pitfalls and asking for a ''second opinion'' from peers to get a more objective view.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f15bd24-c701-4eea-95ad-707fa45b2a1c', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the primary architectural difference between sharding and partitioning, and when would you choose one over the other?', N'Senior', N'Partitioning typically refers to splitting data within a single database instance to improve performance, while sharding involves distributing data across multiple physical database nodes. Sharding is essential for horizontal scaling when a single server can no longer handle the write throughput or storage capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
