INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1360effd-1acf-4cfe-b033-708bec247e61', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik''s ''resumability'' differ from traditional hydration in frameworks like React or Vue?', N'Middle', N'Traditional hydration requires downloading and executing the entire JavaScript bundle to attach event listeners and reconstruct the component state. Qwik achieves resumability by serializing the application state and event handlers into the HTML, allowing the browser to execute only the specific code needed for an interaction without re-running the component initialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1359a08a-840f-4de1-90f9-708c0cf33943', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What role does the ''app.html'' file play in the SvelteKit build pipeline?', N'Senior', N'The app.html file serves as the master template for the application, defining the shell that surrounds the rendered content. It allows for the injection of global meta tags, scripts, and fonts, acting as the structural foundation that the framework populates during both server-side and client-side rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
