INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f987987-7285-410c-8bc2-708d3e242078', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Describe the ZVAL container structure in PHP and how it contributes to memory management.', N'Senior', N'A ZVAL is a structure that stores a variable''s type and its value, along with reference counting and cycle collection information. PHP''s engine uses reference counting to track how many variables point to a specific value, freeing memory automatically when the count drops to zero to prevent leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25acace6-e48e-427c-bece-70924ea587b9', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Why is it recommended to use Doctrine''s ''Proxy'' objects in large applications?', N'Middle', N'Proxy objects allow for lazy loading of related entities, which significantly reduces memory usage and database queries. By only fetching data when it is explicitly accessed, the application avoids loading unnecessary graph data into memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71819710-b13e-4113-a94f-7094158736d8', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript''s ''Discriminated Union'' pattern improve type-safe state management?', N'Senior', N'Discriminated unions use a common literal property across union members to allow the compiler to uniquely identify which specific type is present. This enables exhaustive checking in switch statements, ensuring that all possible states are handled and reducing runtime errors in state-driven architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'961b25e1-c752-4123-b6fa-70957dea1e2f', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is meant by ''Hydration'' in Astro?', N'Fresher', N'Hydration is the process of making static HTML interactive by attaching JavaScript event listeners to it. Astro defers or controls this process so that it only occurs for the specific parts of the page that need it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dceb6163-503e-4df1-8da9-7095d6c74b5a', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is SvelteKit''s ''adapter-auto''?', N'Intern', N'Adapter-auto is a tool that attempts to detect your deployment environment and automatically configures the project accordingly. It is the default choice for new projects to simplify the initial setup process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0bb3c86-52a5-4273-b2a2-709617764d89', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are the main advantages of using Tailwind CSS in a large-scale team environment?', N'Middle', N'Tailwind provides a standardized design system out of the box, which reduces design inconsistencies across a large codebase. It also prevents the ''cascading'' issues common in large CSS files, as utility classes are locally scoped to the element they are applied to.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95fddae6-282e-4d04-a558-70990f2dd344', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of i18n attribute?', N'Intern', N'The Angular i18n attribute marks translatable content. It is a custom attribute, recognized by Angular tools and compilers. The compiler removes it after translation. Note: Remember that i18n is not an Angular directive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86c0806e-20ba-46b4-b61d-70997b9a2049', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of the Webpack ''manifest'' file?', N'Middle', N'The manifest is a mapping of source file names to their corresponding output files, including any generated hashes. It is used by the application or server to determine which files to load, ensuring that assets are correctly referenced even when filenames change due to caching strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8505c4e-487f-4561-8bac-709a6bae1d74', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the trade-offs of using ''SharedArrayBuffer'' and ''Atomics'' for multi-threaded communication?', N'Senior', N'These allow threads to share raw memory directly, avoiding the overhead of structured cloning of large data structures. The trade-off is the complexity of managing memory safety, requiring the use of atomic operations to prevent data races and ensuring cache coherency across threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68e5bc33-869f-4bf0-887e-709a7d20034e', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the Gemfile?', N'Fresher', N'The Gemfile is a configuration file used by Bundler to manage dependencies for a Ruby project. It lists all the external libraries or gems that the application requires to function, along with their specific versions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1b55456-6db6-463f-9e43-709eb8f4815d', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro''s build process handle dead-code elimination?', N'Senior', N'Astro performs tree-shaking on the build output, ensuring that only the code required for the specific islands on a page is included in the final bundle. By analyzing dependencies at the component level, it eliminates unused framework code and utility libraries, resulting in minimal JavaScript payloads per page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1b117a8-88c1-4354-864c-70a0e46f0433', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the ''Database-per-service'' pattern in microservices, and what are its challenges?', N'Middle', N'This pattern ensures each microservice owns its private database, promoting loose coupling and independent scaling. The primary challenge is performing complex joins across services and ensuring data consistency across boundaries, which often necessitates distributed transaction patterns or saga patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76bc7323-c2b7-441a-aadc-70a17c3e38f1', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the significance of the ''disconnectedCallback'' in a Lit component''s lifecycle?', N'Senior', N'This method is triggered when a component is removed from the DOM, providing a critical hook for resource cleanup. It is essential for preventing memory leaks by clearing intervals, removing event listeners on global objects like the window, and cancelling pending asynchronous tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1a108e6-a6b9-405b-8127-70a593126d50', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the optimization techniques of V8 engine?', N'Senior', N'V8 engine uses the below optimization techniques. 1. Inline expansion: It is a compiler optimization by replacing the function calls with the corresponding function blocks. 2. Copy elision: This is a compiler optimization method to prevent expensive extra objects from being duplicated or copied. 3. Inline caching: It is a runtime optimization technique where it caches the execution of older tasks those can be lookup while executing the same task in the future.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7194ec0-6a89-4687-ab1a-70a6467a9f42', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why is Svelte considered more beginner-friendly than other frameworks?', N'Fresher', N'Svelte uses syntax that closely resembles standard HTML, CSS, and JavaScript. Because it avoids complex framework-specific abstractions and boilerplate, developers can build applications using their existing web knowledge with a shorter learning curve.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'526f1023-afb9-4682-ba81-70a701ff0f87', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you bind data to the view in Vue.js?', N'Fresher', N'In Vue.js, Data Binding establishes a connection between the model and the view, ensuring that changes in one are reflected in the other. Vue offers three primary binding types: - One-time: Ideal for scenarios where data doesn''t change, and you want to initialize the view with it. Using this option can increase performance. - One-way: Data changes are propagated from the model to the view. It''s beneficial in ensuring that the model is the single source of truth, simplifying the understanding of your application flow. - Two-way: This type of binding relationship is more dynamic, enabling changes made in either the view or the model to be reflected in the opposite entity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8f129b4-11ca-4919-ae97-70a790dc5dde', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Explain the difference between ''attribute'' and ''property'' in the context of Lit components.', N'Middle', N'Attributes are the initial values passed via HTML tags as strings, while properties are the actual JavaScript class members. Lit manages the flow between these two, ensuring that property changes can update attributes and vice versa when configured.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fc980cf-60d3-40bf-8559-70a8e41a2796', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the primary difference between Vite and older bundlers like Webpack?', N'Intern', N'Older bundlers typically bundle the entire application before starting the development server, which gets slower as the app grows. Vite uses native ES modules to serve files instantly, only compiling the specific code needed at the moment of request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08a1c860-e27b-488d-929d-70ad61062b2b', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux handle asynchronous operations like API calls?', N'Junior', N'Redux itself is synchronous, so it uses middleware like Redux Thunk to handle asynchronous operations. Middleware allows you to dispatch functions instead of plain objects, enabling you to perform API calls before dispatching the final result to the store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
