INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19bec2e6-8206-4456-bdb4-70afc1569660', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel''s Task Scheduling function in a distributed server environment?', N'Senior', N'Standard cron-based scheduling on multiple servers can lead to duplicate job execution. To prevent this, you should use a ''withoutOverlapping'' constraint combined with an atomic cache lock or migrate to a centralized scheduler that ensures only one instance of the task runs across the entire cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a58988a4-68a4-4eec-adb2-70b67c3eb693', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you decide between using a relational database versus a NoSQL database for a new, highly scalable service?', N'Senior', N'The decision hinges on the data structure and access patterns. If the data is highly relational with strict ACID requirements, an RDBMS is preferred, whereas NoSQL is better suited for high-volume, schema-flexible data where horizontal scaling and low-latency reads take priority.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94c85a47-1524-46bd-90e1-70b8dd72a974', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is denormalization encouraged in Cassandra data modeling?', N'Middle', N'Cassandra is designed for read performance based on query patterns rather than data relationships. By duplicating data across different tables optimized for specific queries, you avoid expensive joins which are not supported at the engine level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec1a53a0-1281-47e7-923b-70bb0fbc340e', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the role of Declaration Files (.d.ts) in TypeScript projects.', N'Middle', N'Declaration files contain type information for JavaScript code that lacks built-in types, such as legacy libraries or standard browser APIs. They allow TypeScript to understand the shape of external code without needing to rewrite it. This is essential for maintaining type safety when using third-party packages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
