INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8aeeaa06-ac42-41bf-a400-70c04c08bfd6', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact manage state in functional components?', N'Fresher', N'Preact manages state using the useState hook, just like React. When state is updated, Preact triggers a re-render of the component and updates the virtual DOM to reflect the new state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90ad64ad-4f2a-49c4-bf84-70c173cfab13', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Why is it important to use ''Copy'' on a Gin Context when passing it to a goroutine?', N'Middle', N'The Context object is reused by Gin after the handler returns to optimize performance. If you access the context inside a spawned goroutine after the main handler finishes, you will encounter race conditions or data corruption; calling Copy() creates a safe, read-only snapshot for the background process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f4660c8-48d6-4ef1-8edf-70c27c79b1f8', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are the advantages of using the Mediator pattern via libraries like MediatR in an ASP.NET Core web API?', N'Senior', N'The Mediator pattern promotes loose coupling by separating the command/query logic from the controllers. It simplifies the controller layer, makes the business logic easier to test in isolation, and provides a centralized place for cross-cutting concerns like logging, validation, and transaction management via pipeline behaviors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d888eb0-4542-4db9-9ab0-70c467a0e9d5', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Explain the concept of database normalization and its purpose.', N'Middle', N'Normalization is the process of organizing data to minimize redundancy and dependency by dividing large tables into smaller, related ones. Its primary purpose is to ensure data integrity and reduce anomalies during insert, update, or delete operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd95bccf7-ef6e-4c78-b419-70c471e00fb9', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Is Hono suitable for building REST APIs?', N'Fresher', N'Yes, Hono is highly suitable for building RESTful APIs due to its clean routing, middleware support, and efficient request handling. It is widely used for creating performant backends.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ff2ce73-3c78-4287-ad70-70c5109a09b5', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the role of the ''Companion Object'' in Scala?', N'Middle', N'A companion object provides a place to define static-like members, such as factory methods or constants, that are associated with a class. Because it shares the same name and file as the class, it has access to the class''s private members, facilitating clean encapsulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bb006d9-9d8a-4922-8f54-70c5ca9d9e24', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you determine the appropriate level of logging for production systems?', N'Senior', N'Balance diagnostic utility against storage costs and performance overhead by using structured logging and log levels. Implement dynamic log level adjustments to capture detailed information during incidents without permanently bloating storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e02577d-38b2-40c2-b346-70c5f1e0ce81', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between AddTransient, AddScoped, and AddSingleton in ASP.NET Core dependency injection?', N'Middle', N'AddTransient creates a new instance every time it is requested. AddScoped creates an instance once per client request, and AddSingleton creates a single instance that is shared across the entire application lifetime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'924c25f5-06c6-4db0-b2f4-70c776f185b4', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are given a task with vague requirements, how do you proceed?', N'Intern', N'I would start by documenting my current understanding of the requirements and identifying the specific areas that are ambiguous. Then, I would schedule a meeting with the stakeholder to ask targeted questions to clarify the goals before beginning any work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16d8161a-c426-49be-8bf1-70c8536af888', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When designing for high availability, how do you decide on the trade-off between consistency and availability?', N'Middle', N'I evaluate the business requirements using the CAP theorem; if the business can tolerate eventual consistency for better performance, I prioritize availability. If the data is financial or sensitive and requires strict order, I accept the latency hit associated with strong consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7dccaf80-74d7-4644-89a4-70c9879039ee', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are the performance benefits of Lit''s templating system compared to standard innerHTML?', N'Middle', N'Lit uses tagged template literals to create static parts of the DOM once and only update the dynamic parts that actually change. This significantly reduces the overhead of parsing and rebuilding the entire DOM tree during every render cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a881923-16dd-409d-a2a8-70cb1aa938c1', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of the ''app'' object in Express?', N'Fresher', N'The app object represents the Express application. It is used to set configuration settings, define middleware, route HTTP requests, and start the HTTP server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc33776b-4869-498b-969f-70cb742ae953', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is splitting in MongoDB?', N'Intern', N'Splitting is a process that keeps chunks from growing too large. When a chunk grows beyond a specified chunk size, or if the number of documents in the chunk exceeds Maximum Number of Documents Per Chunk to Migrate, MongoDB splits the chunk based on the shard key values the chunk represent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
