INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a57e07f0-26f9-4cc3-91ac-70cc117d02cc', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you approach the retirement of legacy code while keeping the system running?', N'Senior', N'I would use the Strangler Fig pattern, gradually migrating functionality from the legacy system to a new service one module at a time. This allows for incremental validation and rollback if necessary, eventually rendering the legacy system obsolete without a risky ''big bang'' migration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd828b0dd-6a1b-440f-85fd-70cd3da49f24', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the primary architectural purpose of the ''composable'' pattern in Vue 3?', N'Senior', N'The composable pattern is used to encapsulate and reuse stateful logic across multiple components. By returning reactive state and methods from a function, it allows for clean separation of concerns and facilitates testing of business logic independent of the UI layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'648fc14b-9562-4625-80b4-70ceabcc2ee6', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Describe the impact of the ''FLUSHALL'' command in a production environment.', N'Middle', N'The FLUSHALL command deletes all keys across all databases in a Redis instance, resulting in immediate and total data loss for that instance. In production, this can lead to massive cache misses, effectively causing a ''cold start'' and potentially crashing the backend database due to a sudden surge in traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
