INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d6aa146-7883-4651-9306-70dca04456fd', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are the performance implications of using ''IEnumerable'' versus ''IQueryable'' in Entity Framework?', N'Middle', N'IEnumerable executes the query in memory by fetching all data from the database first, which can lead to high memory consumption and poor performance with large tables. IQueryable translates the query into a database-level command, allowing the filtering and sorting to occur on the database server, which is significantly more efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
