INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f524cda4-fa39-4f13-80e3-70def8fa40af', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Is Redis suitable for storing large amounts of relational, highly structured data?', N'Junior', N'No, Redis is not designed for relational data or complex joins. It is best suited for scenarios requiring high-speed access to simple data or specific data structures, rather than managing complex relationships between large datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce0b9b7e-8eb0-4b94-9ee8-70e26d9542f9', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the primary advantage of using Chi over the default net/http ServeMux?', N'Intern', N'The primary advantage is its expressive routing syntax, which supports URL parameters, wildcards, and regex. It also provides a cleaner way to organize routes into groups, which is not natively supported by the standard ServeMux.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0b54e5f-a05f-4154-afa1-70e3cd14b4c0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How to get responses of multiple api calls, when some API fails?', N'Fresher', N'Promise.allSettled(): To handle failures in multiple API calls, Promise.allSettled() method can be used. The method returns a Promise that resolves after all of the given promises have either resolved or rejected. It returns an array of objects with two properties: status and value. The status property is either "fulfilled" or "rejected", depending on whether the promise was resolved or rejected. The value property is the value of the promise if it was resolved or the reason for rejection if it was rejected. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bca571cb-7787-4f9e-ad07-70e46b7785dd', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the primary advantage of using a document-oriented database like MongoDB over a relational database?', N'Fresher', N'The main advantage is flexibility, as document databases allow for hierarchical data storage and varying structures within the same collection. This makes it easier to model complex, evolving data models without the rigid constraints of predefined table schemas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bba1866-5a6d-4c76-aaaa-70e59e2bb902', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the primary difference between client-side rendering and server-side rendering in Remix?', N'Intern', N'Client-side rendering happens in the browser after the initial load, while server-side rendering happens on the server before the page is sent to the browser. Remix prioritizes server-side rendering to ensure content is available immediately upon page load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a61dae4f-b64a-4bd0-affe-70e90015fe55', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the primary purpose of MySQL?', N'Intern', N'MySQL is an open-source RDBMS used for storing and managing data in web applications. It serves as the backend for many websites, allowing users to efficiently save, search, and update information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b09200b8-8ce1-40b4-8d0c-70e9a9765764', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Explain the concept of ''Scoped Registries'' in the context of Web Components.', N'Middle', N'Scoped registries allow custom elements to be defined locally within a specific shadow root rather than globally on the custom elements registry. This helps prevent naming collisions in large applications with multiple teams or micro-frontends.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ca1b808-92e8-438e-82a6-70e9ac8ece25', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is a Django QuerySet and why is it ''lazy''?', N'Middle', N'A QuerySet represents a collection of objects from your database that can be filtered and ordered. It is ''lazy'' because creating or modifying a QuerySet does not trigger an actual database hit until the data is evaluated, such as by iterating over it or calling specific methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8545e4db-a8a6-4a77-a944-70e9bd5ebd64', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do CSS Custom Properties differ from preprocessor variables in terms of scope and runtime capabilities?', N'Senior', N'CSS Custom Properties are live, runtime-evaluated variables that participate in the cascade and can be updated via JavaScript without re-parsing the stylesheet. Preprocessor variables are static and resolved at compile time, meaning they lack the ability to react to dynamic changes in the DOM or theme context after the CSS has been delivered to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da3bf1ee-4efd-478f-afe7-70ebb79852c6', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the advantage of Qwik''s fine-grained code splitting?', N'Intern', N'Fine-grained code splitting breaks the application into tiny, granular pieces rather than a few large bundles. This ensures that the browser only downloads the exact code needed for the current view, drastically reducing the amount of data transferred.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'638e915d-cfd8-415f-817b-70ed2c8338ca', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What are the architectural benefits of using a ''Sidecar'' pattern in service meshes?', N'Senior', N'The sidecar pattern offloads cross-cutting concerns like logging, service discovery, TLS termination, and monitoring from the application logic to a separate container. This allows these features to be managed and scaled independently while maintaining a unified interface for the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65c77411-5e90-45f1-909a-70f0f66a2050', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the purpose of ''runtime.Gosched()'' and when should it be used?', N'Senior', N'Gosched yields the processor, allowing other goroutines to run while the current one is paused. It is rarely needed in modern Go, as the runtime scheduler is highly efficient; however, it can be useful in extremely tight, compute-bound loops to prevent starvation of the scheduler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14a34873-3808-4e9d-a82b-70f1718143d0', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is a ''fan-out'' exchange in messaging terminology?', N'Middle', N'A fan-out exchange broadcasts every message it receives to all queues bound to it, ignoring any routing keys. It is typically used for broadcasting events to multiple independent services simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'212671d2-5604-456b-b421-70f18a49a3ec', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the common ways to handle static files in Fiber?', N'Junior', N'Static files are typically served using a dedicated middleware or function provided by Fiber that maps a URL path to a directory on the server. This allows images, CSS, and JavaScript files to be accessed directly by the client browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ade3fb3a-c9f3-4690-8179-70f20cee1daa', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Analyze the impact of jQuery''s monolithic file size on the Core Web Vitals, specifically Largest Contentful Paint (LCP).', N'Senior', N'Including the entire jQuery library adds significant blocking JavaScript to the main thread, which delays the parsing and execution required for rendering. This increases the Time to Interactive and can negatively impact LCP by forcing the browser to spend resources on library initialization instead of painting content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1d113e0-0746-4c8e-9d99-70f403282468', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono approach error handling across the middleware stack to ensure robust system recovery?', N'Senior', N'Hono provides a centralized error-handling mechanism where custom error handlers can be registered to catch exceptions thrown by any part of the middleware chain. This allows for consistent error formatting and logging, ensuring that the system gracefully handles failures without exposing sensitive implementation details to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e17037fc-d546-4700-a201-710371b535c5', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the primary use case for ''Route Groups'' in AdonisJS?', N'Middle', N'Route groups allow you to apply middleware, prefixes, or namespaces to a set of routes collectively. This reduces code duplication and helps logically organize the API surface area.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
