INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fad815ae-92e9-4472-a1f4-710e2fd3bab8', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a virtual function?', N'Intern', N'A virtual function is a member function in a base class that is expected to be redefined by derived classes. It enables runtime polymorphism, ensuring that the correct function implementation is called based on the actual type of the object rather than the pointer type. This is essential for achieving dynamic dispatch in C++.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
