INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa992557-2de1-4b40-9993-71110ed4425e', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is technical debt, and why is it sometimes a conscious design decision?', N'Intern', N'Technical debt represents the cost of choosing an easy or quick solution now instead of a better, more robust approach that takes longer to implement. It is a strategic choice when speed-to-market is prioritized, provided the team plans to refactor the code later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c183e7d-5743-41ee-8e1f-71114ddaec58', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB handle throughput throttling?', N'Middle', N'Throttling occurs when an application exceeds the provisioned read or write capacity units for a table or index. To handle this, DynamoDB returns an exception, and developers should implement exponential backoff and retry logic in their application code to gracefully manage the traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edb0a86b-f28e-4a84-8374-71143d0675c4', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How can CSS be leveraged to improve Cumulative Layout Shift (CLS) in an image-heavy application?', N'Senior', N'By using the aspect-ratio property or providing explicit width and height attributes in CSS, developers can reserve space for media elements before they load. This prevents the layout from jumping when images or iframes are injected into the DOM, thereby improving Core Web Vitals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0292901a-43d9-4e69-aa99-7115f76d4a00', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the default scope of a Spring Bean?', N'Intern', N'The default scope for a Spring bean is ''singleton''. This means that the Spring container creates exactly one instance of the bean for the entire application, and that same instance is shared whenever the bean is requested.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ed2f3e9-1812-4564-9c2e-711626370214', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why is the lack of SyntheticEvents in Preact considered an advantage for modern web development?', N'Senior', N'Modern browsers have reached a level of parity where standard DOM events are highly performant and consistent across platforms. By relying on native events, Preact avoids the overhead of maintaining a cross-browser event normalization layer, resulting in smaller bundles and better performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b910e17a-369d-4cd5-830b-7116c7a25a4b', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What does the ''yield return'' statement do in a method?', N'Middle', N'The yield return statement allows a method to act as an iterator, producing elements of a collection one by one on demand. It maintains the state of the method between iterations, which is more memory-efficient than building and returning an entire collection at once.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
