INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8a30db5-cc37-4396-b26f-71241869d237', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How does environment parity affect troubleshooting?', N'Fresher', N'Environment parity ensures that development, testing, and production environments are as similar as possible. Discrepancies between these environments are a common source of bugs that work in one place but fail in another.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45e47cf5-a832-4d39-9455-7124a91449d0', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus simplify testing?', N'Junior', N'Quarkus provides a built-in testing framework based on JUnit 5 that supports `@QuarkusTest`. This annotation automatically starts the application, handles dependency injection, and allows for testing endpoints via RestAssured, making it simple to write integration tests for your services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a8e1dcb-7af5-49f1-831f-7128c9b46e25', N'4c000000-0000-0000-0000-000000000005', N'Why is idempotency critical in distributed message processing?', N'Senior', N'Distributed systems often rely on ''at-least-once'' delivery guarantees, meaning messages may be processed multiple times due to network retries. Idempotency ensures that processing the same message repeatedly does not alter the system state beyond the initial application, preventing data corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e750cbd-e376-4773-8c97-7128e2e68bb8', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How do you achieve multi-tenancy in a NestJS application?', N'Middle', N'Multi-tenancy is typically achieved by using request-scoped services or custom interceptors that identify the tenant from a request header or sub-domain. You then dynamically configure the database connection or context for that specific request scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
