INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0102f5c1-6f23-4783-b678-712aa5fb1d29', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How do Rust''s iterators achieve high performance?', N'Middle', N'Rust iterators are implemented as lazy wrappers that compile down to simple loops, often eliminating bounds checks through optimization. Because they do not allocate memory and are subject to aggressive inlining, they are as fast as manual loops while remaining more readable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
