INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6453ad03-ed59-430f-bab8-712b6698afa2', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby manage memory for strings compared to other languages?', N'Middle', N'Ruby strings are mutable by default, which allows for in-place modifications to save memory. While this improves performance for certain operations, it can lead to side effects if string references are shared across different parts of an application. Developers often use frozen strings to enforce immutability and prevent unintended state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
