INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b620c565-2597-4dc9-84cf-71424a003434', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How do circuit breakers prevent node instability during heavy memory usage?', N'Senior', N'Circuit breakers monitor memory consumption for specific operations, such as aggregations or search requests. If memory usage exceeds defined thresholds, the breaker trips to reject the request, preventing an OutOfMemoryError that would crash the node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'734c4574-1bae-4821-bc9a-71436d7c75ed', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the purpose of persistence in Redis if it stores data in RAM?', N'Intern', N'Persistence is a feature that allows Redis to occasionally save its in-memory data to the physical disk. This ensures that the data is not permanently lost if the system experiences a power failure or a server restart, providing a balance between speed and data durability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
