INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3faeb18-800f-4e7e-a1b8-7146a164ab47', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you determine if a task should be handled synchronously or asynchronously?', N'Junior', N'If the user needs to see the result of an action immediately, I perform it synchronously. If the task is long-running, like processing a large file or sending batch emails, I push it to an asynchronous task queue to keep the user interface responsive and avoid request timeouts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63212b6a-f2a5-4187-a6e3-7147ceda3468', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Explain the trade-offs of using ''LocalQuorum'' versus ''EachQuorum'' in a multi-datacenter deployment.', N'Senior', N'LocalQuorum ensures consistency within a single datacenter, providing lower latency and higher availability by not waiting for cross-region communication. EachQuorum requires confirmation from all datacenters, which guarantees stronger global consistency but introduces significant latency and increases the risk of request failure if any remote datacenter is partitioned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e5bed3f-cf3f-4b51-8720-7148fdc6cbd8', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Can Redis persist data to disk?', N'Fresher', N'Yes, although Redis is primarily an in-memory store, it offers persistence options like RDB (Redis Database Backup) and AOF (Append Only File). These features allow the data to be saved to disk periodically or after every write operation, ensuring data recovery after a restart.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fe2b4b3-984b-4f7e-97ab-7149347007d7', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the difference between horizontal and vertical scaling for API performance?', N'Middle', N'Vertical scaling increases the resources of a single server, such as CPU or RAM, which is often limited by hardware ceilings. Horizontal scaling adds more instances to the infrastructure, allowing for better load distribution and high availability, making it the preferred approach for modern cloud-based APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4d2e62b-7b30-4ed9-a8cf-7149852b9754', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is a closure in the context of Ruby blocks?', N'Middle', N'A closure is a block or proc that remembers the scope in which it was defined, including access to local variables from its outer environment. Even when the block is passed to a different method or executed later, it retains access to the variables that existed when it was created.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a27617ad-77fb-430d-a620-71498b7d557d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do JavaScript generators facilitate lazy evaluation and memory-efficient data processing?', N'Senior', N'Generators allow functions to pause and resume execution, producing values on-demand rather than computing an entire collection at once. This lazy evaluation is memory-efficient for processing large data streams, as it keeps only the current state in memory instead of the entire dataset.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c1d81b2-d346-4e8b-822f-714c795b586b', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Evaluate the architectural trade-offs of using PHP for long-running CLI tasks.', N'Senior', N'While convenient, long-running PHP processes require careful management of memory usage and connection persistence. Developers must manually trigger garbage collection or periodically restart the worker to prevent memory leaks, as the runtime environment is not optimized for infinite loops.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6bb51a2-23c1-4eb7-87e8-714d18631a1a', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the Java Garbage Collector determine which objects are eligible for collection?', N'Middle', N'The JVM uses a reachability analysis algorithm, starting from root objects like active threads and static references. Any object that cannot be reached through a chain of references from these roots is considered unreachable and eligible for garbage collection. This approach effectively handles cyclic references that simple reference counting cannot solve.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f326de01-2aa4-40df-8c4a-714fb90c6f41', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does ''Least Recently Used'' (LRU) differ from ''Least Frequently Used'' (LFU) eviction policies?', N'Senior', N'LRU evicts the entry that hasn''t been accessed for the longest time, making it effective for workloads with temporal locality. LFU evicts the entry with the lowest access count, which is better for scenarios where specific items remain popular over long periods regardless of recent usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afe08b21-f57e-4bef-88f3-715302184ef2', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Describe the lifecycle of a Svelte component and its main hooks.', N'Middle', N'The lifecycle includes hooks like onMount, beforeUpdate, afterUpdate, and onDestroy. These allow developers to execute logic at specific phases of the component''s existence, such as initializing data or cleaning up event listeners.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a411f0b8-0c5d-4ce7-ac8a-715359d139d2', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why might clearing a cache be a valid troubleshooting step?', N'Junior', N'Applications often store temporary data in caches to improve performance, but these can sometimes hold outdated versions of data or logic. Clearing the cache ensures the application is working with the most recent data and code, which helps rule out stale state as the source of a bug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b5af096-e0fe-4c5a-9c87-7154c47dfd02', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the primary trade-off of Go''s fast compilation speed?', N'Middle', N'Go achieves fast compilation by limiting the complexity of its type system and avoiding heavy template or macro processing. The trade-off is that developers must often write more boilerplate code, as the language does not provide powerful meta-programming features like those found in more complex languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d9eea04-5621-4ab5-a6e2-715690935c3f', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How do you design for one-to-many relationships in DynamoDB?', N'Middle', N'You can model one-to-many relationships by using a composite primary key where the partition key represents the ''one'' entity and the sort key represents the ''many'' entities. Alternatively, you can use GSIs to project child data or store related items in the same partition if they are always accessed together.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a4ac2a2-348e-4ecc-bec4-715cc10e9f6e', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the trade-offs of having too many indexes on a table?', N'Junior', N'While indexes speed up read operations, they slow down write operations because the index must be updated every time data is inserted, deleted, or modified. Additionally, excessive indexes consume extra disk space and memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25ec8a97-e8b6-4add-8231-715f1dbf033e', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Why does SvelteKit''s build process perform static analysis on components, and what benefits does it yield?', N'Senior', N'Static analysis allows the compiler to understand the component''s reactivity graph at build time, enabling it to generate surgically precise DOM updates. This eliminates the need for a runtime reconciliation engine, resulting in smaller bundle sizes and faster execution speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85a425b7-fbce-42df-a7aa-716066bdc50a', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs when choosing between a micro-frontend architecture and a unified frontend application?', N'Senior', N'Micro-frontends allow independent teams to ship features in isolation, reducing the risk of global regressions, but they introduce challenges in consistent styling, shared state management, and asset loading. A unified frontend is easier to maintain and keeps dependencies consistent but can become a bottleneck for large organizations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c31b5bc-fa21-456d-ae2f-7163d9b3621c', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What are the advantages and risks of using database-level vs. application-level constraints?', N'Senior', N'Database-level constraints provide the ultimate guarantee of data integrity, protecting against inconsistencies if other services access the same database. Application-level constraints, such as Laravel''s Form Requests, offer a better developer experience and provide immediate feedback to users but are not sufficient on their own for mission-critical data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c17a741-44bc-49f4-9800-7166ba9c6207', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How do you group routes in Hono?', N'Junior', N'Routes can be grouped using the ''hono.route'' method or by creating sub-routers using the ''new Hono()'' constructor. This allows developers to modularize their application code by separating features into different files or modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'118028c8-bd0e-4015-a34b-7167059c0bdb', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a long-running transaction?', N'Intern', N'A long-running transaction is a transaction that remains open for a significant period of time. These are generally discouraged because they hold locks for too long, which can cause performance bottlenecks and concurrency issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ceece6a-6bbd-40ae-af77-7168fb50a08e', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the impact of cache fragmentation on system performance?', N'Middle', N'Cache fragmentation occurs when memory is allocated and deallocated in a way that leaves small, unusable holes, making it difficult to store large objects. This can lead to decreased cache efficiency and increased latency as the system struggles to find contiguous memory space for new entries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e1c5751-ff7b-46ac-a0bb-716fdbd9c76d', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are Guards in NestJS?', N'Intern', N'Guards are classes responsible for determining whether a given request should be handled by the route handler or not. They are commonly used for authentication and authorization checks to protect specific routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0808761-513d-4633-a86d-716feb10863b', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain the trade-offs of using ''majority'' write concern in a replica set.', N'Senior', N'Using ''majority'' write concern ensures that data is persisted to a majority of the replica set members before acknowledging the write. While this provides strong durability guarantees and prevents rollbacks during failover, it increases write latency as the primary must wait for network round-trips to the secondaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5d6a457-09d7-492a-bf83-717055b1caa9', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain the trade-offs of using a ''Service Mesh'' compared to client-side load balancing.', N'Senior', N'A service mesh provides infrastructure-level traffic management and security without requiring code changes in the service, but it introduces operational overhead and potential latency. Client-side load balancing is simpler to implement but forces infrastructure logic into the application code and requires consistent implementation across different languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd42b035-64b9-4bb4-96cd-7170c517f8ec', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between vertical and horizontal scaling?', N'Junior', N'Vertical scaling is a quick, short-term fix to handle increased load by upgrading hardware, but it has a physical ceiling. Horizontal scaling is the long-term design choice for distributed systems, as it allows for adding more machines to share the load and provides better fault tolerance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd001fc34-18ae-4121-8517-7171d5baf904', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the difference between ''let'' and ''var'' in Swift.', N'Junior', N'The ''let'' keyword is used to declare a constant, meaning its value cannot be changed once it is set. The ''var'' keyword is used to declare a variable, which allows the value to be reassigned or modified later in the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdefe271-8fc5-47b3-abee-7173c88a03f5', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the architectural trade-off of using Django''s ORM versus raw SQL in high-throughput systems?', N'Senior', N'The ORM provides developer productivity and database abstraction but can generate inefficient queries, such as the N+1 problem, if not carefully managed. In high-throughput systems, raw SQL or query optimization techniques are often required to bypass the overhead of object instantiation and complex JOIN generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'239cfd01-8364-4d2b-bd53-717450f48e7e', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the impact of heavy client-side middleware on the ''Time to Interactive'' metric?', N'Senior', N'Heavy client-side middleware blocks the main thread during navigation, preventing the browser from processing user interactions. When complex logic is executed in middleware, it delays the readiness of the application, directly negatively impacting the Time to Interactive and overall user responsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be5c80c8-224a-49b5-abb3-7174993219cc', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the difference between ''server'' and ''client'' plugins in Nuxt?', N'Middle', N'Server plugins run only during the initial server-side rendering phase, while client plugins execute only in the browser. Using the correct type prevents issues where browser-specific APIs, like ''window'' or ''localStorage'', are called during server-side execution, which would cause crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ad108e4-c1b2-455e-a208-7174e0989677', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'In a distributed system, how do you handle the failure of a remote service?', N'Junior', N'I implement retry mechanisms with exponential backoff for transient issues and use circuit breakers to stop requesting a service that is consistently failing. This prevents the failure from cascading through the system and gives the struggling service time to recover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c12e5717-23d6-475c-af97-7176bcaf30d9', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you choose between using an existing library versus building a custom solution?', N'Fresher', N'You weigh the speed of development and reliability of a library against the control and performance optimization of a custom build. A library is usually better for common tasks, while a custom solution is preferred when unique requirements cannot be met by standard tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fb15a1d-24fc-4715-82e1-7176cb0128db', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What are the security considerations when designing a serverless architecture?', N'Senior', N'In serverless, the primary concern is the increased attack surface created by event-driven triggers and the loss of visibility into the underlying infrastructure. Security must focus on strict IAM role granularity for each function and ensuring secure handling of environment variables that often contain sensitive configurations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'287b07b4-70da-492a-961c-7177e137e53c', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why is the use of ''splitProps'' recommended?', N'Junior', N'splitProps is a utility function used to safely separate props into different objects without losing reactivity. It is particularly helpful when you need to pass some props to a child component and keep others for the current component''s logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c99c77f-d7ff-4e0c-89ba-7178e605906e', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Does Actix support WebSockets?', N'Intern', N'Yes, Actix has built-in support for WebSockets, which allow for full-duplex communication channels over a single TCP connection. This is useful for real-time applications like chat or live data feeds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a526b399-2c82-4c38-a757-71797f53e0ff', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What determines the cost of a DynamoDB table?', N'Middle', N'The cost is primarily determined by the storage volume, the read and write capacity consumed (or requested), and additional features like backups, Streams, or Global Tables. Choosing the right capacity mode is the most significant factor in optimizing monthly costs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'965ec5d7-2969-46ff-8f2d-717b0695cd2e', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the architectural benefit of using a FastCGI Process Manager (PHP-FPM) over a standard CGI implementation.', N'Senior', N'A standard CGI implementation forks a new process for every single request, which is extremely expensive in terms of system resources. PHP-FPM maintains a pool of persistent worker processes that reuse the same environment, drastically reducing the overhead of process creation and initialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f97c2490-0477-4e8b-8d12-717c8006e77a', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of the g object in Flask?', N'Intern', N'The g object is a special namespace for storing data that needs to be accessed by multiple functions during a single request. It is cleared automatically at the end of every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'faacbfb3-185a-4368-a837-717e756512f8', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why would you choose a message queue over a direct API call?', N'Middle', N'Message queues enable asynchronous processing, which decouples the producer and consumer and allows for better load smoothing during traffic spikes. They also provide reliable message delivery, ensuring that tasks are processed even if the consumer is temporarily offline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45e696c9-b3c3-48da-839a-717ea36cb239', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are the rules regarding references in Rust?', N'Fresher', N'At any given time, you can have either one mutable reference or any number of immutable references. Furthermore, references must always be valid and cannot outlive the data they point to.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72a07f25-fd57-44af-8083-717faf7d0ee4', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do you style a Lit component?', N'Fresher', N'Lit components are styled using the css tagged template literal. Styles defined this way are scoped to the component''s shadow root, meaning they only affect elements within that specific component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8d2d927-a9e2-4db0-84ac-718071b048d6', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is database latency?', N'Intern', N'Database latency refers to the time delay between a request being made to the database and the response being received. High latency can be caused by inefficient queries, hardware limitations, or network congestion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da30f267-cbb4-40be-afd6-71811a96827a', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the purpose of the ''static'' keyword?', N'Intern', N'The static keyword indicates that a member belongs to the class itself rather than to any specific instance of the class. Static members are shared by all objects created from that class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e68bfcba-0f77-4f24-8b29-718153663276', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the importance of ''isolation'' in troubleshooting?', N'Intern', N'Isolation narrows the scope of the problem to a specific component, module, or layer of the system. By ruling out working parts, you reduce the surface area you need to investigate, making it significantly easier to locate the source of the error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f46427ea-80c0-4e9d-b99f-71852c9a467f', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does tail sampling improve observability costs?', N'Middle', N'Instead of keeping every trace, tail sampling waits for a trace to complete before deciding whether to keep it. This allows you to keep 100% of errors or high-latency requests while discarding the majority of successful, low-latency requests, significantly reducing storage costs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b5309e7-39d2-4171-8fc4-7185ec9636ba', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does the ''Plug'' middleware pipeline architecture influence the request lifecycle in Phoenix?', N'Senior', N'Plug provides a standardized, composable interface for request transformation, allowing developers to inject functionality at specific points in the pipeline. By layering plugs, one can cleanly separate concerns like authentication, logging, and parameter parsing, ensuring that each step of the lifecycle is isolated and testable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a51bd79b-4e9e-420d-92b7-7189d21fed29', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the architectural implications of using Flask''s thread-local storage for context objects.', N'Senior', N'Flask uses context locals to make global objects like request and session available without passing them explicitly through function signatures. While this simplifies API design, it introduces complexity in asynchronous or multi-threaded environments where developers must ensure contexts are properly pushed and popped to avoid data leakage between concurrent operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af2c8bdc-14b7-479b-84c5-718e51327488', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'When should you prefer Redis Streams over Pub/Sub?', N'Middle', N'Redis Streams should be used when you require message persistence and the ability for consumers to acknowledge processing status. Unlike Pub/Sub, Streams allow consumers to read historical data and resume processing from a specific point, making it suitable for event sourcing and reliable task queues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe1c3583-ecaa-40cb-a60a-7191e2606463', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Why are default mutable arguments considered a design trap in Python?', N'Middle', N'Default arguments are evaluated only once at the time of function definition, not during each function call. If a mutable object like a list or dictionary is used as a default, changes made to it persist across subsequent calls, leading to unexpected state leakage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4dfa36cb-de4e-4d8d-a81d-71921c3a7829', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the architectural advantage of Hono’s explicit type-safety for request bodies and params?', N'Senior', N'By forcing explicit type definitions, Hono catches data-mismatch errors at compile-time rather than runtime, which is critical for large-scale backend stability. This approach forces developers to document their API contract through code, ensuring that the backend implementation remains strictly aligned with the expected request structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e1cc0fc-f195-4227-b6db-7192eb040cd8', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the primary purpose of SvelteKit in the context of Svelte?', N'Fresher', N'SvelteKit is a full-stack framework built on top of Svelte that provides structure for building web applications. It handles routing, server-side rendering, and data fetching, which allows developers to create complete applications rather than just isolated components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd258038b-6fff-4340-afb7-71946f39cfb7', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the purpose of the ''Secure'' middleware in Echo?', N'Middle', N'The Secure middleware adds various HTTP security headers, such as X-Content-Type-Options or Content-Security-Policy, to responses. This helps protect the application from common web vulnerabilities like XSS and content sniffing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0ff05c4-9a95-4ac9-97a0-71948ec6436a', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is a POST request in PHP?', N'Intern', N'A POST request is a method used to send data from a web form to the server. Unlike GET requests, POST data is sent in the body of the HTTP request, making it more secure for transmitting sensitive information like passwords.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab6e8810-5990-4e7c-8db4-7197e8f6cd38', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the primary difference between a SPA and Server-Side Rendering (SSR) in Nuxt?', N'Fresher', N'In a Single Page Application, the browser downloads a minimal HTML file and renders the content using JavaScript. In Server-Side Rendering, the server generates the full HTML content for the page and sends it to the browser, which improves initial load speed and search engine optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73613a10-b739-42c1-a99d-719ad7fd36a9', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the main differences between SQL and NoSQL?', N'Intern', N'SQL databases are relational, use structured tables with fixed schemas, and prioritize ACID compliance. NoSQL databases are non-relational, use flexible data models like documents or graphs, and are designed for horizontal scalability and high-velocity data ingestion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b141bfcc-e8af-4ee2-bc60-719daa869814', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why might a query use a temporary table?', N'Middle', N'MySQL creates temporary tables when it encounters complex operations that cannot be resolved using indexes alone, such as using ''GROUP BY'' on non-indexed columns or complex ''UNION'' operations. Excessive use of temporary tables on disk can significantly slow down query execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10c6c7c5-8ffd-4b50-bec9-719df4ef7025', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why is the ''converter'' property useful in Lit property decorators?', N'Middle', N'The converter property allows you to define custom logic for parsing an attribute string into a specific JavaScript type. This is essential when a property needs to accept complex data from an HTML attribute, which natively only supports strings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'465f1852-677d-4881-891f-71a0bfec24ba', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a high-traffic system, how do you decide whether to implement a synchronous or asynchronous communication pattern between services?', N'Middle', N'Synchronous communication is appropriate when the calling service needs an immediate response to proceed, though it creates tight coupling and potential bottlenecks. Asynchronous communication via a message broker is preferred for performance-critical systems as it decouples services, improves fault tolerance, and allows for better load leveling during traffic spikes. I would choose asynchronous patterns whenever strong consistency requirements allow for eventual consistency to improve overall system availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df9f3211-aa53-4fc7-8336-71a152fece2c', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the effect of using the ''is'' operator compared to ''==''?', N'Middle', N'The ''=='' operator checks for value equality, determining if the content of two objects is the same. The ''is'' operator checks for object identity, verifying if both variables point to the exact same memory address.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d5d51cb-d4d2-42f8-938b-71a244ff1321', N'954a0331-deff-4399-b588-96f39fec001d', N'Describe the difference between ''Eager'' and ''Lazy'' loading strategies in the context of Angular modules and the impact on initial bundle size.', N'Senior', N'Eager loading pulls all modules into the main bundle, causing a large initial download that slows down the ''Time to Interactive''. Lazy loading splits the application into smaller chunks that are downloaded on demand, significantly improving initial load times for large-scale enterprise applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4615556c-9fd4-4ed8-b710-71a46db8a3d0', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does the ''readonly'' modifier do?', N'Intern', N'The readonly modifier prevents a property of an object or an element in an array from being reassigned after its initial creation. It ensures that data remains immutable, which helps prevent accidental side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
