INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3cc0c01-e757-4d42-81b0-71ab5011ee70', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is an action creator?', N'Intern', N'An action creator is a function that creates and returns an action object. Using action creators makes code more maintainable and easier to test compared to writing raw action objects manually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e777b707-e562-40ac-839a-71ac24611ed0', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the Symfony Request-Response cycle?', N'Intern', N'The cycle describes how Symfony handles an incoming HTTP request and returns an HTTP response. The request is passed through the kernel to find the matching route, the controller processes the logic, and the resulting response object is sent back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b8fc2fd-6632-48e7-8236-71b1a5b69fae', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the role of the ''Value Class'' in Kotlin, and how does it interact with the JVM''s type system?', N'Senior', N'Value classes provide a way to wrap a single value in a type-safe manner without the heap allocation overhead of standard wrapper objects. The compiler attempts to inline the underlying value wherever possible, though it may box the value when used as a generic type or interface, potentially leading to performance inconsistencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73d9cc2a-5630-4659-ba59-71b58e1585a4', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the function of the GROUP BY clause?', N'Fresher', N'The GROUP BY clause is used with aggregate functions to group rows that have the same values into summary rows. It is commonly used to perform calculations like counting or summing data across categories.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35746b49-0603-42b8-9a80-71b5c2e67097', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How do you mitigate the ''N+1 query problem'' in an ORM-based database design?', N'Senior', N'The N+1 problem occurs when an application executes one query for a parent record and then N additional queries for each child record. It is mitigated by using eager loading or join-fetching to retrieve all necessary data in a single batch query, reducing network round-trips and database load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9b8b7fe-de6c-43fb-b205-71b7414ae62e', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between a struct and a class in C++?', N'Intern', N'The only difference is the default access level for members. In a class, members are private by default, while in a struct, they are public by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d347fc4-77be-4836-9556-71b85155d774', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the ''Response Model'' parameter used for?', N'Fresher', N'The response model parameter is used to define the structure of the data returned by an API endpoint. It ensures that the output is validated against the specified schema before being sent back to the client, effectively masking internal fields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b9a396d-35ab-455c-9194-71b90e106a65', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the role of the JavaScript engine''s JIT (Just-In-Time) compiler?', N'Middle', N'The JIT compiler improves performance by compiling JavaScript code into machine code during execution rather than interpreting it line-by-line. It monitors frequently executed code paths and optimizes them, significantly speeding up repetitive operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
