INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fac1a4d-649d-4002-9659-71bf748d3015', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does the ''x-init'' directive differ from standard component lifecycle hooks found in heavier frameworks?', N'Senior', N'The x-init directive acts as a rudimentary constructor that executes when a component is initialized, but it lacks the granular lifecycle control found in frameworks like React or Vue. Because it is bound to the DOM node''s existence, it does not provide explicit ''beforeUpdate'' or ''beforeDestroy'' hooks, limiting the ability to perform complex cleanup or integration with third-party libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27f837ee-e0b2-4405-8948-71c2f4606c16', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are the three service lifetimes in ASP.NET Core, and when should you use each?', N'Middle', N'Transient services are created every time they are requested, suitable for lightweight stateless services. Scoped services are created once per client request, ideal for database contexts or unit-of-work patterns. Singleton services are created once and shared across the entire application lifetime, typically for caching or configuration providers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a606616-c793-45c2-bcb1-71c3ebda17e0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you check if a string starts with another string?', N'Fresher', N'You can use String.prototype.startsWith() method to check if a string starts with another string or not. It is fully supported in all modern browsers. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f3bbcfa-0a93-4a75-b2f1-71c5c164de3a', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How are variables different in Rust compared to other languages?', N'Fresher', N'In Rust, variables are immutable by default, meaning their values cannot be changed once assigned. To make a variable mutable, a developer must explicitly use the ''mut'' keyword, which makes the code''s intent clearer and safer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd25c3634-95c9-495f-93cb-71c642efd41a', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why is ''undefined behavior'' a central concept in C++ optimization?', N'Senior', N'Undefined behavior allows the compiler to assume that certain conditions never occur, enabling aggressive optimizations like constant folding, dead code elimination, and instruction reordering. If a programmer violates these assumptions, the compiler''s optimizations may lead to unpredictable runtime execution because the generated code relies on the invalid premise.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b93e2e80-54a9-49b8-a12e-71c94b7039bb', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why is extending built-in JavaScript objects not a good idea?', N'Fresher', N'Extending a built-in/native JavaScript object means adding properties/functions to its prototype. While this may seem like a good idea at first, it is dangerous in practice. Imagine your code uses two libraries that both extend the Array.prototype by adding the same contains method; the implementations will overwrite each other and your code will have unpredictable behavior if these two methods do not work the same way. The only time you may want to extend a native object is when you want to create a polyfill, essentially providing your own implementation for a method that is part of the JavaScript specification but might not exist in the user''s browser due to it being an older browser. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a814887-20b0-474b-af34-71ce7f0f7ab9', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the difference between ''start'' and ''create'' for actors?', N'Junior', N'The start method creates and starts the actor in the current execution context. The create method is often used to define how the actor should be instantiated, which is then invoked by the system to begin execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f80fef1c-dd19-4764-8901-71cecc297e28', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When building a UI, what is the trade-off between pixel-perfect design and component reusability?', N'Junior', N'Pixel-perfect design ensures the UI matches the exact vision, which is great for branding. However, prioritizing reusability through a design system makes the application easier to maintain and faster to build, even if it requires minor compromises in unique styling per page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
