INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da35d09e-bbec-4020-a287-71d3f048b89b', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the difference between ''open'' and ''public'' visibility modifiers?', N'Middle', N'Public is a visibility modifier that determines who can access a class or member, while open is a restriction modifier that allows a class or member to be overridden. By default, Kotlin classes and members are final, so they must be explicitly marked as open to be extended.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf394964-3e7d-418a-9064-71d469f97d5d', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'A user reports that a web page is loading very slowly. How would you start investigating the cause?', N'Fresher', N'I would first inspect the network tab in the browser developer tools to determine which specific assets, such as large images or scripts, are taking the longest to download. I would then check if the delay is happening on the client side during rendering or on the server side during data processing. This helps identify if the bottleneck is due to resource size, network latency, or inefficient backend logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baadbadc-996b-4cba-9c0f-71d470a359a2', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of Phoenix''s ''Router'' and how does it compare to standard HTTP routing?', N'Middle', N'The Phoenix Router is highly optimized, using a compiled trie structure to match routes rapidly. It allows for advanced features like nested scopes, pipeline plugging for specific sets of routes, and easy integration with LiveView, making it more performant and feature-rich than basic regex-based routers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c56e2dc8-e2dc-465e-a236-71d9f61c2bd4', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the ''Either'' type used for?', N'Fresher', N'The Either type is used to represent a value that can be one of two possible types, often used for error handling. It typically holds a ''Left'' value for errors and a ''Right'' value for successful outcomes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebd27c65-51a3-40c8-aac9-71daf1e54aa9', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of a null pointer?', N'Junior', N'A null pointer is a pointer that points to no valid memory address. It is used to indicate that the pointer is not currently referencing any valid data, which is a safe way to initialize pointers or signal the absence of an object. Checking for a null pointer before dereferencing it is essential to prevent segmentation faults.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65f29f9c-7d41-4886-bd88-71dc445c9776', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the benefit of using type hints in Litestar?', N'Junior', N'Type hints are essential for Litestar because the framework uses them for introspection. They allow the framework to automatically validate inputs, serialize outputs, and generate interactive API documentation like Swagger without requiring extra configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee8c73b9-a5e4-4ef0-bc63-71dc9b3a7356', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are the limitations of using ''destructuring declarations'' in complex data models?', N'Senior', N'Destructuring relies on the ''componentN'' functions generated for data classes, which depend strictly on the order of properties in the constructor. If the order is changed, downstream destructuring code will break without a compiler error, creating a potential source of regression in large, evolving codebases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'938d18de-0743-4b2b-8532-71dd8fe64e49', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the concept of template metaprogramming in C++.', N'Middle', N'Template metaprogramming uses the compiler to execute code during the build process, enabling complex computations or logic generation at compile-time. This can result in highly optimized code that moves runtime overhead to the compilation phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77d44f0a-d559-4aab-bbac-71e05bf3fa77', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How do ''reified'' type parameters work in Kotlin, and why are they only available for inline functions?', N'Middle', N'Reified types allow access to the actual type information at runtime, which is usually lost due to type erasure. They are only available for inline functions because the compiler replaces the type parameter with the actual class type at every call site during the inlining process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ab99576-6509-4eab-8f5c-71e7a9449305', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why is Rocket considered ''type-safe'' compared to dynamic language frameworks?', N'Middle', N'Rocket leverages Rust''s strong typing to ensure that route parameters, headers, and body payloads are validated at compile time or during parsing. This prevents many common runtime errors, such as missing parameters or incorrect type casting, which are typical in dynamic language web frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fb3b9be-48e6-45d1-a4cd-71eb0e984669', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you design for failure in a distributed system?', N'Senior', N'I assume that components will fail, so I design for graceful degradation, retries with exponential backoff, and timeouts on all external calls. I also implement bulkheads to isolate failures and ensure that one failing subsystem does not consume all resources and bring down the entire architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b4a46b8-998e-402a-acdc-71ef21f408de', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Explain the concept of ''progressive enhancement'' as implemented in SvelteKit form actions.', N'Middle', N'Progressive enhancement allows forms to work without JavaScript by relying on standard browser form submission. SvelteKit enhances these forms by using JavaScript to intercept the submission, providing a smoother user experience with loading states and validation without a full page reload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9118324-248b-4f56-9ca8-71ef606214d0', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Describe the difference between a QuerySet''s evaluation and its lazy nature.', N'Middle', N'Django QuerySets are lazy, meaning they do not hit the database until an action is performed, such as iteration, slicing, or calling len(). This allows developers to chain filters and exclusions without triggering multiple database queries until the final result set is actually required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62a23abe-9621-4e00-98d1-71f0e154df83', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What are ''Quarkus Profiles'' used for beyond environment settings?', N'Junior', N'Beyond environment settings, profiles can be used to enable or disable specific features or extensions depending on the build target. This helps in managing different application behaviors for different deployment scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f447c3d-692d-4a37-8525-71f106fb9117', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a column alias?', N'Intern', N'A column alias is a temporary name given to a table or a column in a query result. It is used to make the output headers more readable or to distinguish between columns when joining tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc012fe5-dee0-4bfe-b43a-71f1bb3f902c', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Why might you choose a microservices architecture using Flask over a monolithic structure?', N'Senior', N'Microservices offer independent scalability, technology diversity, and fault isolation, making them suitable for complex, large-scale systems. However, they introduce significant operational overhead in terms of service communication, distributed tracing, and consistency management compared to a monolith.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72c3d84c-80fa-453c-a037-71f286e9fd56', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the difference between BASE and ACID properties.', N'Middle', N'ACID emphasizes strict consistency, atomicity, isolation, and durability, typical of relational databases. BASE stands for Basically Available, Soft state, and Eventual consistency, prioritizing high availability and scalability over immediate consistency, which is common in NoSQL systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77cd24b3-198f-4d46-bd7b-71f4765dc625', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Explain the concept of ''Move'' semantics.', N'Junior', N'Move semantics mean that when ownership of a heap-allocated value is assigned to a new variable, the old variable is invalidated. This prevents multiple variables from trying to free the same memory when they go out of scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'560bdb46-98c7-4675-839f-71f57f8b245e', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a Near Real-Time (NRT) search in Elasticsearch?', N'Intern', N'NRT search refers to the slight delay between the time a document is indexed and the time it becomes searchable. This delay is typically around one second because Elasticsearch must refresh the index to make new data visible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb5de223-95d3-4aa3-8be5-71fa7b2ff06d', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle global CSS?', N'Junior', N'Global CSS is typically imported into your root layout file or a global stylesheet. Because it is imported at the top level, those styles are applied to every page in the application, ensuring a consistent design system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f47abb7-031b-4b64-9f91-71faeb7eb4a4', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Can Hono be used with Node.js?', N'Intern', N'Yes, Hono includes a specific adapter that allows it to run on Node.js. While it is optimized for edge runtimes, the platform-agnostic design ensures it functions correctly within a Node.js server environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f782a7bc-aeb0-4744-8728-71ffe6ef5c07', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does the ''writeConcern'' configuration impact data durability?', N'Middle', N'WriteConcern determines the level of acknowledgment requested from MongoDB for write operations. Setting it to ''majority'' ensures the write is committed to the disk of a majority of nodes, providing a higher guarantee of data durability compared to ''w: 1'', which only confirms receipt by the primary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4db692f-2dcd-4c76-bde3-7204233a3c95', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the benefit of using dependency injection containers?', N'Middle', N'Dependency injection containers automate the instantiation and wiring of objects and their dependencies. This reduces coupling between classes, making the system more modular and easier to unit test. It centralizes configuration and simplifies the management of complex object graphs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e28d7d1-f950-4cdc-aa13-72045e1c7858', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the difference between ''blocking'' and ''non-blocking'' I/O in Quarkus?', N'Fresher', N'Blocking I/O waits for an operation to complete before proceeding, which can consume more threads. Non-blocking I/O uses an event-loop model to handle multiple concurrent requests with fewer threads, making it highly efficient for high-concurrency scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'169b8ced-d365-442e-b142-7207fa3f0eb9', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik maintain state between server and client?', N'Intern', N'Qwik maintains state by serializing the application data into the HTML as part of the initial server response. When the client takes over, it reads this serialized state directly from the DOM, effectively ''resuming'' the state where the server left off.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7b80a31-3b12-41e6-8871-720854d9fed8', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of the ''Adapter'' in Ember Data, and how does it handle persistence strategy?', N'Senior', N'The Adapter defines how the application interacts with the backend server, such as URLs, headers, and request methods. It decouples the data structure from the transport layer, allowing the application to support multiple APIs or storage strategies concurrently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86a1f37a-912a-4ad4-a2ff-7208ff928567', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between Promise and AJAX?', N'Fresher', N'A Promise is an interface for asynchronous operations. They keep track of when asynchronous operations complete and what their results are and let you coordinate that completion and those results (including error conditions) with other code or other asynchronous operations. They aren''t actually asynchronous operations in themselves. An Ajax (Asynchronous JavaScript and XML) call is a specific asynchronous operation that can be used with with a traditional callback interface or wrapped in a promise interface. We can make an Ajax call either with a traditional callback using the XMLHttpRequest() interface or we can make an Ajax call (in modern browsers), using a promise with the fetch() interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82fb2497-01b1-4953-a502-7209030827ca', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why is the Lua scripting capability significant in Redis?', N'Middle', N'Lua scripting allows developers to execute multiple commands on the server side as a single atomic operation. This reduces network round-trips by bundling logic into a single request and ensures that no other command is executed while the script is running, providing a powerful way to implement complex server-side business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63a8883e-0802-4dc6-8a6e-720cfb5988a3', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Why is the choice of sharding key critical for system performance?', N'Senior', N'A poor sharding key can lead to ''hotspots'' where a single shard receives a disproportionate amount of traffic, nullifying the benefits of scaling. An ideal key should provide high cardinality and uniform data distribution to ensure load is balanced across all nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89637c64-6bbd-4568-8128-720d7b7b9242', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain how Write-Ahead Logging (WAL) ensures durability in ACID transactions.', N'Senior', N'WAL ensures durability by forcing all transaction modifications to a persistent log on disk before the changes are applied to the actual data files. If the system crashes, the database can reconstruct the state by replaying the log, ensuring no committed data is lost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e30794c-f7b8-4a24-b20d-720f98a3ad9b', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the impact of using global variables in R packages?', N'Middle', N'Global variables can lead to unpredictable side effects, make code harder to test, and break the encapsulation of a package. Best practices involve using closures, environments, or explicitly passing necessary variables to functions to ensure code purity and modularity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'354c366d-433b-4df0-897c-721142150efe', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why is it important to define reactive properties in Lit?', N'Junior', N'Defining reactive properties allows Lit to monitor them for changes. Without explicit declaration, Lit would not know that updating a property should trigger a re-render of the component''s template.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7665835-12f7-4035-aab1-72145fd1a0d0', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the impact of using too many unique CSS classes on the browser''s style matching engine?', N'Senior', N'A large number of unique CSS classes increases the complexity of the style rule tree, requiring the browser to perform more extensive lookups during each recalculation. While modern engines are highly optimized, an excessive number of rules can still contribute to minor latency in style resolution, particularly on low-end devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14114a17-8b77-4640-9831-72180d29ede5', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Does TypeScript exist in the browser?', N'Intern', N'No, browsers cannot execute TypeScript directly. TypeScript code must be transpiled into standard JavaScript before it can run in a browser environment, as browsers only understand JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec7150b1-3e11-4761-bd03-72189e1fdf37', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of Rust''s lifetime elision rules?', N'Senior', N'Lifetime elision is a set of deterministic rules that allow the compiler to infer the lifetimes of function arguments and return values in common patterns. These rules reduce the verbosity of function signatures while maintaining safety, as the compiler still enforces the same strict checking as if the lifetimes were explicitly annotated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30e8c7e4-90ec-4e1b-81f7-7219f40567a5', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the purpose of callback function argument format of setState() in React and when should it be used?', N'Fresher', N'The callback (or updater function) form of setState — both this.setState(prev => ...) in classes and setX(prev => ...) with useState — guarantees that each update is computed from the latest queued state rather than the value captured in your closure. Use it whenever the next state depends on the previous state, especially when you call the setter more than once in the same event handler or when the update may run after an await/timeout/promise. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c15bcc9-f49c-4238-8d6e-721a4ac4ca3e', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the ''sunk cost fallacy'' and how does it affect trade-off analysis?', N'Intern', N'The sunk cost fallacy occurs when an engineer continues a project or design path simply because they have already invested significant time into it. To perform an effective trade-off analysis, one must focus on future outcomes rather than past investments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7be423a8-db50-491b-974b-721a5486a5a5', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'When should you use F expressions in Django ORM?', N'Middle', N'F expressions are used to perform database operations that reference model field values directly in the database rather than in Python memory. They are essential for avoiding race conditions when updating fields based on their current value, such as incrementing a counter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'caa1e94f-1577-4b66-a44d-721aef6b597b', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the primary difference between ''x-bind'' and ''x-model''?', N'Middle', N'The ''x-bind'' directive is used for one-way data flow, where the DOM attribute is updated based on the state. The ''x-model'' directive provides two-way data binding, synchronizing the input element''s value with the state, which is essential for form inputs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43736a04-4f4d-494f-8c45-721cb1f2d907', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik differ from traditional frameworks regarding hydration?', N'Fresher', N'Traditional frameworks require hydration, which involves downloading all JavaScript and re-executing the component tree to attach event listeners. Qwik replaces this with resumability, which avoids the overhead of re-executing code by simply resuming from the server-rendered state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9efae8a9-bacc-4f4d-9c0d-721d099cdce0', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Can Echo be used to build RESTful APIs?', N'Fresher', N'Yes, Echo is specifically designed to be an excellent tool for building RESTful APIs. Its routing capabilities and support for JSON binding make it highly effective for creating services that interact with frontend applications or mobile devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34d8af86-e104-44c4-9aae-7225370e8feb', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Why is it dangerous to perform business logic inside a database migration, and how should it be handled instead?', N'Senior', N'Migrations are intended for schema changes; performing business logic inside them creates a dependency on the current state of the code, which can cause migrations to fail as the codebase evolves. Instead, use dedicated Data Seeder classes or console commands to transform or migrate business data, keeping the migration history focused purely on structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60850853-9519-496b-958e-7226c9774a62', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Explain the mechanism behind ASP.NET Core''s Filter pipeline and how it differs from Middleware.', N'Senior', N'Middleware operates at the global pipeline level, processing every request and response, whereas filters are action-oriented and scoped to controllers or specific endpoints. Filters allow for fine-grained control over execution flow, such as authorization, model validation, and exception handling, specifically within the MVC/API framework layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ba8ac36-18f1-4851-9584-722755b71be5', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'When would you prefer an asynchronous message broker over synchronous REST/gRPC calls?', N'Senior', N'Use asynchronous messaging for long-running processes, high-throughput ingestion, or when decoupling the producer from the consumer is necessary for availability. Synchronous calls are better for simple request-response operations where immediate confirmation is required and latency is not a critical bottleneck.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6793223-9242-4cd2-b8f0-722775b9a12a', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is Astro''s approach to CSS?', N'Junior', N'Astro supports standard CSS files, preprocessors like SASS, and scoped CSS via the style tag within components. By default, styles defined in an Astro component are scoped to that component to prevent styling conflicts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce10a2ff-27ba-4858-8935-7227c01aa7c9', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Can you define signals outside of components?', N'Junior', N'Yes, signals can be defined outside of components, which makes them effective for managing global state. Because they are independent of the component lifecycle, they can be shared across multiple components to keep data synchronized throughout the app.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98deedcd-9157-4c95-b53e-72287271773f', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between ''as'' and a direct cast?', N'Junior', N'The ''as'' operator attempts to cast an object to a type and returns null if the cast fails, rather than throwing an exception. A direct cast will throw an InvalidCastException if the conversion is not possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'316a51e9-29b2-4af7-845b-722a095871c2', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the role of a Partition Key?', N'Fresher', N'The partition key is the first part of a primary key and is used by DynamoDB to determine the physical location of the data. It helps the database distribute data across multiple storage partitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc2efa51-1c7c-451a-8ef8-722a3c4c53b3', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you compare Object and Map?', N'Fresher', N'1. Object: A data structure in which data is stored as key value pairs. In an object the key has to be a number, string, or symbol. The value can be anything so also other objects, functions, etc. An object is a nonordered data structure, i.e. the sequence of insertion of key value pairs is not remembered. Example: 2. ES6 Map: A data structure in which data is stored as key value pairs. In which a unique key maps to a value. Both the key and the value can be in any data type. A map is an iterable data structure. This means that the sequence of insertion is remembered and that we can access the elements in e.g. a for..of loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2d900ce-7666-454d-912d-722c29d15d9d', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS implement server-side rendering (SSR) compared to traditional hydrate-heavy frameworks?', N'Senior', N'SolidJS uses a streaming SSR approach that generates HTML strings directly from reactive components. Because SolidJS components don''t re-render, the hydration process is minimal, often involving only attaching event listeners to existing DOM nodes rather than rebuilding the entire component tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63606321-8339-4633-a339-722d935011b6', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is a Type Class in Scala?', N'Middle', N'A type class is a design pattern that allows you to add new behavior to existing types without modifying their source code. It is implemented using traits and implicit parameters, providing a flexible alternative to traditional inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3969dec3-29c6-4acb-a704-722e410867b7', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the benefit of using Mutiny in Quarkus?', N'Junior', N'Mutiny is the reactive programming library integrated into Quarkus for handling asynchronous data streams. It provides an intuitive and readable API for composing non-blocking operations, making reactive development more accessible for backend developers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa86e9b4-c92f-4889-9e10-722e83b3e39b', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is the use of global variables generally discouraged in C?', N'Middle', N'Global variables make code harder to reason about because they can be modified from anywhere, leading to hidden dependencies and side effects. They increase the difficulty of maintaining thread safety and make it nearly impossible to implement reentrant functions, which are essential for robust and scalable systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'540b6a03-3d6e-438f-848c-722f38766674', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How would you implement high-availability logging in a distributed Flask environment?', N'Senior', N'Instead of writing to local files, the application should use a structured logging approach where logs are emitted to stdout or a centralized collector like Fluentd or Logstash. This ensures that logs are aggregated from multiple Flask instances, allowing for real-time monitoring and alerting across the entire infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
