INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68b9f5e7-6d1a-43f1-a71f-722fc8ea95fe', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the role of a ''Cluster'' in Cassandra?', N'Junior', N'A cluster is the outermost container for data in Cassandra, representing the entire collection of nodes. It encompasses all data, configuration, and keyspaces, acting as a single logical database instance spread across multiple physical servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8cdcacf-567b-4069-8d37-7231013d1c6f', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the advantage of SolidJS''s compilation step?', N'Senior', N'The compiler transforms JSX into highly optimized, vanilla DOM code. This removes the need for a runtime diffing engine, allowing for a smaller bundle size and faster execution speeds by shifting work from the user''s browser to the build time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd69bec76-d6c1-4bf6-92c7-723377c8c0c0', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Compare SvelteKit''s ''prerendering'' with traditional Static Site Generation (SSG).', N'Senior', N'SvelteKit''s prerendering converts routes into static HTML files at build time, similar to SSG, but it integrates seamlessly with dynamic routes. Unlike traditional SSG, SvelteKit allows you to selectively prerender specific pages while keeping others dynamic, providing a highly flexible hybrid rendering model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87f16e35-9fdb-4e1b-be95-723838eb2fe9', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why are web workers used in JavaScript, and what are their limitations?', N'Middle', N'Web workers allow execution of CPU-intensive scripts in a background thread to prevent blocking the main UI thread. Their primary limitation is that they do not have direct access to the DOM and must communicate with the main thread via message passing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33cd64e9-6dcf-4e17-9afe-72388fce8ef3', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why is the use of a load balancer important in a distributed system architecture?', N'Middle', N'A load balancer distributes incoming network traffic across multiple backend servers to ensure no single server becomes a bottleneck. This improves application responsiveness, prevents system failure due to overload, and allows for seamless scaling of backend resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f909c141-bf40-4959-a64f-723c1e3f249a', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Does Vite support multi-page applications, and how is it configured?', N'Middle', N'Yes, Vite supports multi-page applications by allowing the configuration of multiple input HTML files in the build options. Each entry point is treated as an independent application, and Vite will generate the appropriate assets and bundles for each one.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'024c96d6-0d0e-4c18-beb7-723ff3351fde', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Describe your strategy for debugging a memory leak in a production environment where restarts are not a viable long-term solution.', N'Senior', N'I would first capture heap dumps from multiple instances to perform a comparative analysis to identify leaking object types. Then, I would analyze the object reference tree to find unintended long-lived references, such as static collections or orphaned event listeners, while simultaneously monitoring garbage collection logs for signs of memory pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a72e169-6944-4a9a-b00e-72416991b5a5', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'In a distributed system, how does Rocket''s stateless design benefit scaling?', N'Senior', N'Rocket is designed to be stateless, meaning that requests do not depend on stored server-side session data that is pinned to a specific instance. This allows Rocket-based services to be easily replicated behind a load balancer, enabling horizontal scaling without the need for complex session synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b74e950-8a82-49f7-af3c-724310c403d4', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the return type of an Axum handler?', N'Intern', N'An Axum handler must return a type that implements the IntoResponse trait. This trait defines how a Rust object should be converted into an HTTP response, including status codes and body content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
