INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fadeea10-fcca-46ef-9728-724b7119a5fa', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the use of setInterval?', N'Intern', N'The setInterval() method is used to call a function or evaluates an expression at specified intervals (in milliseconds). The setInterval() method continues calling the function until clearInterval() is called, or the window is closed. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e29e128-c736-4bf8-b5ea-7254af18c8b6', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is fiber-based concurrency considered ''cooperative'' rather than ''preemptive''?', N'Middle', N'In cooperative multitasking, a fiber must voluntarily yield control back to the scheduler, typically at specific suspension points. Preemptive multitasking allows the OS to interrupt threads at any time, which requires complex locking mechanisms to prevent race conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'577acd55-d2d2-4aab-abcd-72553b2c42ed', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What are signals in SolidJS, and why are they important?', N'Fresher', N'Signals are the primitive units of state in SolidJS that represent a value that can change over time. When a signal is accessed within a tracking scope, SolidJS automatically tracks it as a dependency, allowing the UI to update precisely when that specific signal changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
