INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fcdef0e-92bd-4cc9-b8fe-72586e6b84e3', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do ''Read Replicas'' improve system reliability?', N'Senior', N'Read replicas distribute query load away from the primary database, preventing bottlenecks and improving read availability. If the primary instance fails, replicas can potentially be promoted to primary, reducing downtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
