INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89b2fc7b-e135-4ebd-8546-725ac2f1c9f6', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the difference between synchronous and asynchronous processing in terms of scalability?', N'Middle', N'Synchronous processing forces the client to wait for a task to complete, which can tie up resources and limit throughput. Asynchronous processing allows the system to acknowledge a request immediately while performing the work in the background, significantly increasing system responsiveness and scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdd7482d-1aef-4114-9b8d-725b350dbc00', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What happens if you use a class that doesn''t exist in Tailwind?', N'Intern', N'If you mistype a class name, Tailwind will ignore it, and the style will simply not be applied to the element. Since Tailwind doesn''t have a massive stylesheet by default, it doesn''t break anything, but the UI will look unstyled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
