INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'347aac7d-4a9e-4e84-b331-726893e63086', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What are the performance implications of Rocket''s use of ''FromData'' and ''FromForm'' traits?', N'Senior', N'These traits enable zero-cost abstractions for data parsing and validation. Because the logic is generated at compile-time, there is minimal runtime reflection, allowing for high-throughput deserialization of complex structures directly into memory-safe types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae19eb79-b563-4578-951b-7268c9c31f32', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle concurrency and scheduling compared to React''s Fiber architecture?', N'Senior', N'SolidJS uses a synchronous, push-based reactive system that updates the DOM immediately, prioritizing efficiency over the interruptible rendering model found in React. While React relies on scheduling and time-slicing to manage large updates, SolidJS relies on the precision of its reactive graph to ensure minimal work is performed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b9e9b2c-e130-42da-b900-726919c23cd8', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust''s ''Trait'' system enable composition over inheritance?', N'Senior', N'Rust favors composition by allowing developers to define traits that describe behavior independently of data structures, then implementing these traits for any type. This approach avoids the ''diamond problem'' and complex class hierarchies, leading to a more modular architecture where functionality is added via trait implementation rather than deep inheritance trees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6da90b0d-b4f0-4f71-ba49-726a516e705a', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the difference between an Angular Directive and a Component in terms of their role in an architecture?', N'Senior', N'Components are specialized directives with an associated template, used to build UI elements with encapsulated state and styles. Directives are meant for augmenting existing elements with behavior or appearance changes, adhering to the Single Responsibility Principle by keeping UI components clean of generic DOM-manipulation logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99e2b6fd-e6df-4991-81a9-726b97f732d0', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does the ''Phantom Read'' phenomenon differ from a ''Non-repeatable Read''?', N'Middle', N'A non-repeatable read occurs when a row''s values change between two reads within the same transaction. A phantom read occurs when the set of rows returned by a query changes because another transaction inserted or deleted rows that match the search criteria.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74e33f16-4ace-406d-b25f-726ce06865e9', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the Spring Data JPA starter?', N'Fresher', N'Spring Data JPA is a library that simplifies the implementation of data access layers by providing an abstraction over JPA (Java Persistence API). It reduces boilerplate code for database operations by allowing developers to define repository interfaces that automatically implement basic CRUD functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4178bafa-8d2a-457e-b17a-726e14c9d7f5', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the pros and cons of for loops', N'Intern', N'The for-loop is a commonly used iteration syntax in javascript. It has both pros and cons Pros 1. Works on every environment 2. You can use break and continue flow control statements Cons 3. Too verbose 4. Imperative 5. You might face off-by-one errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85542bac-219f-4aa0-b3f5-72729743f25a', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the role of the GROUP BY clause?', N'Junior', N'The GROUP BY clause is used to arrange identical data into groups, often in combination with aggregate functions like COUNT, SUM, or AVG. It collapses rows with the same values in specified columns into single summary rows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca6d6c8e-a317-4032-85ab-727467651b5c', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the significance of the visibility map in PostgreSQL.', N'Senior', N'The visibility map tracks which pages contain only tuples visible to all active transactions, allowing index-only scans to retrieve data without checking the heap. This reduces I/O by avoiding unnecessary visibility checks on data pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cbb23e6-ab04-4015-9631-7277f3c680c4', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is a parameter in Symfony service configuration?', N'Junior', N'Parameters are scalar values or arrays used to store configuration settings, such as database credentials or API keys. They allow developers to define values in one place and inject them into multiple services, making the application easier to configure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0aeac026-ac24-4fe7-92a9-72781b4bcfad', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How can you implement performance testing for Lit components?', N'Middle', N'Performance testing involves measuring the time taken for the initial render, the frequency of re-renders, and the time spent in the update lifecycle. Tools like Chrome DevTools Performance tab and Lighthouse are used to audit these metrics during development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7cb382a-4469-4c89-9aab-727845fc90b3', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Describe the strategy for handling database migrations in a CI/CD environment with zero downtime.', N'Senior', N'Zero-downtime deployments require backward-compatible migrations, meaning you must split changes into multiple steps: first adding a column, then updating the code to handle both old and new schemas, and finally dropping the old column. This ensures that old and new code versions can coexist during the deployment window.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1b6fe93-b3a7-4f97-a796-727887dcbc1a', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What do you do if you find a major flaw in a design after you have already started implementation?', N'Fresher', N'I would pause the implementation and document the specific flaw I discovered, along with the potential impact on the project. I would then present this finding to my lead or the team, along with suggestions for how to address it. It is always better to raise the issue early and correct the design than to continue working on a fundamentally broken solution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb790cd3-782f-413b-830e-727928d6c542', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the primary role of the Phoenix Framework in the Elixir ecosystem?', N'Intern', N'Phoenix is a web development framework designed for building scalable and maintainable applications. It leverages the Erlang VM to handle many concurrent connections efficiently, making it particularly well-suited for real-time features like live updates and chat systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'267b241b-c1a2-439b-9d6f-727cd6373d2e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What architectural challenges arise when implementing deep object cloning in JavaScript?', N'Senior', N'Deep cloning must handle circular references, non-enumerable properties, and specialized types like Maps or Sets, which simple JSON serialization misses. Furthermore, recursively traversing large object graphs can cause call stack overflows, necessitating iterative approaches or specialized libraries for robust performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80a3249c-dbf6-40c6-8e39-7285cf055b92', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the ZGC (Z Garbage Collector) achieve sub-millisecond pause times?', N'Senior', N'ZGC uses colored pointers and load barriers to perform most of its work concurrently with the application threads. By marking and relocating objects while the application continues to run, ZGC ensures that pause times do not scale with the size of the heap, making it ideal for low-latency systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c757528-9627-4911-b3fb-72895ccd3400', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the difference between onDestroy and beforeUpdate?', N'Junior', N'onDestroy runs when a component is removed from the DOM, useful for cleaning up intervals or event listeners. beforeUpdate runs right before the DOM is updated, allowing you to capture the state of the DOM before changes occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29acdcd2-028e-4025-8f38-7289ad2f43da', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the benefit of using Phoenix Templates (HEEx)?', N'Junior', N'HEEx templates are HTML-aware, allowing for safer rendering and better performance. They integrate closely with LiveView to provide efficient DOM updates by only sending changed parts of the page to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18e92144-5720-4ba8-9c94-728c11188bfb', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between ''super'' and ''this''?', N'Middle', N'The ''this'' keyword refers to the current instance of the class, allowing access to its members. The ''super'' keyword refers to the immediate parent class, allowing access to methods or constructors defined in the superclass.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
