INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bba6f79-060e-4f08-aebe-72905f4e7c0e', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why is it important to revisit estimates during the lifecycle of a project?', N'Fresher', N'As work progresses, uncertainty decreases because more information becomes available. Revisiting estimates allows for correcting early errors and provides stakeholders with updated, more accurate timelines, which is essential for managing overall project expectations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb46ce92-14ab-4810-a62b-7291210318ed', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle schema-based serialization, and why is it faster than standard JSON.stringify?', N'Senior', N'Fastify uses the Fast-JSON-Stringify library to pre-compile serialization functions based on JSON schemas. By generating optimized code that bypasses generic object traversal, it significantly reduces the CPU time required to serialize responses compared to native stringification.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'947bc4d4-01a5-45d7-b35b-7294faa53b4e', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the trade-offs of using ''std::shared_ptr'' compared to ''std::unique_ptr''?', N'Middle', N'std::unique_ptr provides exclusive ownership with zero runtime overhead, making it the preferred default. std::shared_ptr allows shared ownership via reference counting, which introduces atomic operation overhead and potential circular reference issues that require weak pointers to resolve.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6af7e30-b8cc-4397-995e-7297063b5238', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are Symfony Environments and why do they exist?', N'Junior', N'Environments are different configurations for your application, typically ''dev'', ''prod'', and ''test''. They allow you to toggle features like debug bars or error logging, ensuring that development tools are not exposed in production and that production performance is optimized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07a948f9-983f-460a-9ced-72977550a228', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is Dependency Injection in the context of Spring?', N'Intern', N'Dependency Injection is a design pattern where an object receives its dependencies from an external source rather than creating them itself. In Spring, the framework manages the creation and lifecycle of these objects, known as beans, and injects them where needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc08eb94-2ebe-47c9-9fb6-729d00c7134d', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the purpose of the useSelector hook?', N'Intern', N'The useSelector hook allows you to extract data from the Redux store state in a functional component. It automatically subscribes the component to the store, so it re-renders whenever the selected state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46f2f596-516c-46d1-a61f-729df756d299', N'075b8862-431c-4678-9767-f55359758a4a', N'What are lifecycle hooks and why are they important?', N'Middle', N'Lifecycle hooks allow developers to execute code at specific stages of a component''s existence, such as creation, mounting, updating, or unmounting. They are essential for tasks like fetching initial data, setting up event listeners, or cleaning up resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e868eda-5e60-45b4-8550-72a129775bf8', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a sudden increase in CPU usage on a web server?', N'Middle', N'I would check the system metrics to see if the CPU usage corresponds to a spike in incoming traffic or a specific background task. If it is high traffic, I would analyze the logs to see if a particular endpoint is being abused or if there is a loop in the code. I would also use profiling tools to identify which functions or threads are consuming the most CPU cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0979192b-f49f-4bed-87e4-72a1ca38f80b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is bind method in javascript?', N'Intern', N'The bind() method creates a new function, when invoked, has the this sets to a provided value. The bind() method allows an object to borrow a method from another object without making a copy of that method. This is known as function borrowing in JavaScript. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45fb81ff-2172-45d2-aa0c-72a4f2d88a8a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Explain the concept of an API in simple terms.', N'Fresher', N'An API acts as a messenger that allows two different software applications to talk to each other. It provides a defined set of rules and protocols so one system can request information or actions from another without needing to understand its internal workings. It is essentially an interface that hides complexity while exposing necessary functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'458dda98-16fc-4edd-8ea6-72a6dc40ca1c', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What are the limitations of Go''s built-in ''testing'' package compared to third-party frameworks?', N'Middle', N'The standard library''s testing package is minimalist and focuses on simplicity, lacking advanced features like built-in mocking or complex assertion helpers. While this promotes consistency across the ecosystem, developers often supplement it with external tools to handle complex BDD-style or integration testing requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b78d5a4-f079-4d76-958e-72a70d2ded1c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is promise chaining?', N'Intern', N'The process of executing a sequence of asynchronous tasks one after another using promises is known as Promise chaining. It allows you to chain on another then call which will run when the second promise is fulfilled. The .catch() can still be called to handle any errors that might occur along the way. Example: In the above handlers, the result is passed to the chain of .then() handlers with the below work flow, * The initial promise resolves in one second, * After that .then() handler is called by logging the result(10) and then return a promise with the value of result + 20. * After that the value passed to the next .then() handler by logging the result(20) and return a promise with result + 30. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c67f42c-2457-417b-9cec-72aaf6e47143', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the role of the WiredTiger storage engine in MongoDB?', N'Middle', N'WiredTiger is the default storage engine that provides document-level concurrency control and native compression. It uses a cache to store data in memory and employs checkpoints to ensure data durability on disk, allowing for efficient write operations and reduced storage footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4149b139-b577-41c5-b38a-72abe44adaa2', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle reconciliation compared to React?', N'Middle', N'Preact uses a simpler and more synchronous reconciliation process that iterates through the component tree and updates the DOM only when necessary. By reducing the complexity of the diffing algorithm, Preact achieves faster render cycles at the cost of some advanced scheduling features found in React''s concurrent mode.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'762f9577-1568-4232-a029-72ad20ad2f71', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the function of a ''Service Mesh'' in a large-scale architecture?', N'Senior', N'A service mesh offloads cross-cutting concerns like service discovery, load balancing, mutual TLS encryption, and observability from the application code to a dedicated infrastructure layer. This allows developers to focus on business logic while ensuring consistent policy enforcement and reliable communication between services. However, it introduces latency and operational complexity due to the sidecar proxy overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b948400-2e58-4130-bd36-72ad2e0aefaf', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is database denormalization and when is it appropriate?', N'Middle', N'Denormalization involves intentionally adding redundant data or grouping data to reduce the number of joins required for complex queries. It is appropriate in read-heavy scenarios where the performance cost of joins outweighs the overhead of managing data redundancy and potential update anomalies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b0818c4-4970-45ef-8465-72ae1b28baae', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue ensure that component instances remain isolated?', N'Middle', N'Vue ensures isolation by requiring the ''data'' option to be a function that returns a fresh object instance for each component usage. This prevents different instances of the same component from sharing the same data reference in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32a39146-8e1a-40a9-9e51-72af76ee2434', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the ''splitProps'' utility used for?', N'Junior', N'splitProps is used to separate a single props object into multiple objects based on keys. This is essential when passing specific subsets of props to children or utility components while maintaining their reactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11636159-c168-4ca3-9cbf-72afe06bf0c0', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the purpose of the ''session_start()'' function.', N'Fresher', N'This function is used to either start a new session or resume an existing one based on a session identifier passed via a request. It must be called before any output is sent to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68252418-eef3-4b95-8677-72b02500c80f', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the difference between Astro and a Single Page Application (SPA) framework?', N'Fresher', N'SPA frameworks like React or Vue typically render the entire page in the browser using JavaScript. Astro renders the content into static HTML on the server, resulting in faster initial page loads and better SEO.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
