INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e27247f8-cc5f-47c4-866d-72b52dd37d1a', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Why are static constructors in C# thread-safe by design?', N'Senior', N'The runtime guarantees that a static constructor is executed only once per type, and it uses internal locking mechanisms to ensure that all threads wait until the initialization is complete. This provides a robust, built-in way to perform one-time type initialization without requiring manual synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
