INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04cc09e2-51c2-47ed-b7c4-72d7db0f91cc', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Does Alpine.js require a build process?', N'Intern', N'No, Alpine.js does not require a build process. You can include it in your project via a simple script tag in your HTML file, making it very easy to get started without configuring tools like Webpack or Vite.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'721cf7fd-6e44-4326-b40e-72df9877017b', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Explain the concept of ''Virtual Modules'' in Vite and provide a common use case.', N'Senior', N'Virtual modules are files that do not exist on the disk but are generated by plugins during the build or development process. They are frequently used for injecting configuration data, dynamic environment settings, or framework-specific metadata into the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6492da58-24c7-4256-bd75-72e352e6fe69', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Why is it important to use ''Tagged Services'' in Symfony?', N'Middle', N'Tagged services allow you to group multiple services under a common tag to be processed collectively by a compiler pass. This makes the system highly extensible, as you can add new functionality simply by creating a class and tagging it, without modifying existing orchestration code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b11bfeb4-00a2-4210-a97f-72e37f7f45c6', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do database locks affect transaction performance?', N'Junior', N'Locks prevent concurrent access to data to ensure integrity, but they can slow down the system. Excessive locking can lead to contention, where many transactions are queued waiting for the same resource, reducing throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f1c9bd9-c73e-40fa-b82f-72e38d9b51ef', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Explain the trade-offs between Micronaut''s Netty-based non-blocking architecture versus a traditional Servlet-based blocking model.', N'Middle', N'The Netty-based non-blocking model allows a small number of threads to handle a high volume of concurrent requests by not blocking threads during I/O operations. While this is highly scalable, it requires developers to be disciplined about not performing blocking operations in the event loop, which can be more complex to debug compared to the traditional thread-per-request model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'670aca4a-98fb-4287-8a37-72e3b6b30475', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of the ''config'' directory?', N'Fresher', N'The config directory contains files that define environment-specific settings for the application. This includes configurations for database connections, logging, and external API credentials.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1aa2bbd4-8815-430f-ba56-72e8b4df90b9', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the ''Problem Details'' standard in ASP.NET Core APIs?', N'Middle', N'Problem Details, based on RFC 7807, provides a standardized machine-readable format for representing errors in HTTP APIs. It allows clients to consistently parse error information such as type, title, status, and detail across different endpoints and services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecba93f8-3ee5-4be4-b9bd-72e8ccb2c4f8', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is sharding and why is it essential for horizontal scaling in NoSQL?', N'Middle', N'Sharding is the process of splitting a large dataset into smaller chunks, known as shards, and distributing them across multiple servers. It is essential for horizontal scaling because it prevents any single node from becoming a bottleneck by spreading the storage and processing load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c46f01c0-b490-499e-a80b-72e9d021f922', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What does the ''assets'' directory do?', N'Junior', N'The assets directory is intended for files that need to be processed by build tools, such as CSS files, fonts, or images that require optimization. These files are bundled and transformed during the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0d80ba8-8621-44d5-bdf0-72eb91062c7e', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the purpose of the ''Timeout'' middleware in Fiber?', N'Middle', N'The Timeout middleware is used to enforce a strict limit on the execution time of a request handler. It prevents a slow external dependency or a stuck process from consuming worker pool slots indefinitely, which helps maintain system responsiveness under failure conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'090ea11e-afe2-475f-8033-72f1f60b9d67', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the purpose of the ''resolve.extensions'' configuration in Vite, and why is it often discouraged?', N'Senior', N'This configuration tells Vite which file extensions to try when a file path lacks an extension. It is discouraged because it can significantly slow down the module resolution process and complicate the build graph for tools like TypeScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95b9faa4-be0a-4ef8-a70c-72f25c2fab15', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the role of the Eloquent ORM and why you would use it.', N'Middle', N'Eloquent provides an active record implementation for working with databases, allowing you to interact with tables using object-oriented syntax. It simplifies complex queries and relationships while providing built-in methods for data validation and model events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e2f4a3a-46a2-4fde-bfea-72f2f245c196', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is a loading.js file in the App Router?', N'Fresher', N'The loading.js file is used to create a loading UI that automatically appears while the page content is being fetched. It helps improve the perceived performance by showing a spinner or skeleton screen to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21a7a7b1-cc4a-462c-afc9-72f44c5df4b1', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the significance of ''Request Localization'' in a globalized ASP.NET Core application?', N'Senior', N'Request localization automatically detects the user''s culture from headers, cookies, or query strings and sets the CurrentCulture for the execution thread. This enables the framework to handle date, time, currency, and string formatting automatically, ensuring a consistent and localized experience for global users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a636a74f-099b-42f6-acd0-72f5e35164c1', N'4c000000-0000-0000-0000-000000000005', N'What is the CAP theorem, and why is it important in distributed system design?', N'Middle', N'The CAP theorem states that a distributed data store can only simultaneously provide two out of three guarantees: Consistency, Availability, and Partition Tolerance. In the presence of a network partition, designers must choose between consistency, where all nodes see the same data at the same time, or availability, where the system remains responsive even if data might be stale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e43a6fb2-be67-40a0-a6e4-72f6d4d2bf10', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain relationships in MongoDB?', N'Fresher', N'Relationships in MongoDB are used to specify how one or more documents are related to each other. In MongoDB, the relationships can be modelled either by Embedded way or by using the Reference approach. These relationships can be of the following forms: * One to One * One to Many * Many to Many Example: Let us consider the case of storing addresses for users. So, one user can have multiple addresses making this a 1:N relationship. User Collection Address Collection 1. Modeling Embedded Relationships In the embedded approach, we will embed the address document inside the user document. This approach maintains all the related data in a single document, which makes it easy to retrieve and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50d31f8a-f9ab-496a-b638-72f8efcd9d56', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are asked to estimate how many tennis balls fit into a Boeing 747, how do you begin?', N'Intern', N'I would break the problem into two parts: estimating the total volume of the airplane cabin and the volume of a single tennis ball. I would then divide the cabin volume by the ball volume and apply a ''packing factor'' to account for the empty space between the spheres.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'830b5c1e-967d-4ba7-a5f9-72fac5a77c64', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What happens if a transaction fails during the middle of execution?', N'Middle', N'If a transaction fails, the database performs a rollback operation using the undo logs to revert any changes made by that transaction. This ensures that the database returns to the exact state it was in before the transaction started, upholding the atomicity guarantee.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1209ac1b-1860-401f-8326-72fe1669544a', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is a constructor in PHP?', N'Intern', N'A constructor is a special method in a class that is automatically called when an object of that class is created. Its primary purpose is to initialize object properties or perform setup tasks when the object is instantiated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85ce60e6-ba53-4c28-a1e7-7303377c15b1', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why would you choose to use a message queue in your system architecture?', N'Junior', N'Message queues are used to decouple services, allowing them to communicate reliably without being available simultaneously. They also help smooth out traffic spikes by acting as a buffer, ensuring that backend systems are not overwhelmed by incoming requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a2f43b2-3e85-4153-8388-7306d00660d7', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What does res.status().send() do?', N'Junior', N'res.status() sets the HTTP status code for the response, such as 200 for success or 404 for not found. Following it with .send() transmits the data body, allowing you to chain methods to return a specific code along with a message or data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cc515ec-5e16-48ab-ae6c-7307ebdaa9cb', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle dependency injection differently than frameworks relying on runtime reflection?', N'Senior', N'Micronaut uses a compile-time dependency injection engine that creates visitor classes for every bean. This eliminates the need for runtime introspection, allowing the application to resolve the dependency graph immediately upon initialization without scanning the entire classpath.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ca282ab-ddef-4041-ae70-730c6faccb7a', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the primary difference between the standard Go net/http package and Fiber?', N'Fresher', N'The standard net/http package is the built-in library provided by Go for building web servers, while Fiber is a web framework built on top of Fasthttp. Fiber is designed to be highly performance-oriented and provides a more expressive, minimalist API similar to Express.js, making it easier to handle routing and middleware compared to the standard library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
