INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53227167-10c4-47b0-b425-730e38137af3', N'4c000000-0000-0000-0000-000000000005', N'Explain the concept of service discovery.', N'Middle', N'Service discovery is a mechanism where services in a dynamic environment can automatically find the network locations of other services. It is essential in microservices, where instances are frequently created and destroyed, rendering hardcoded IP addresses unusable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b7bbc67-c4ae-4182-8b12-730f24ce6856', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the benefit of Axum''s ''Router'' nesting?', N'Fresher', N'Nesting routers allows developers to group related routes together, making the codebase easier to maintain. It also permits the application of specific middleware or state to only a subset of endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fd12748-efa0-429d-a18b-7310745f9129', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using a single large database versus multiple small databases in a microservices architecture?', N'Middle', N'A single database simplifies cross-entity joins and transaction management but creates a single point of failure and makes scaling difficult. Separate databases ensure service autonomy and fault isolation but introduce complexity in maintaining data consistency across services and require patterns like sagas or eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa778de9-e9ce-4037-bd56-7310cc649895', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the lifecycle of a Preact component?', N'Intern', N'A component''s lifecycle includes phases such as mounting, updating, and unmounting. Preact provides methods or hooks that allow developers to execute code at specific points during these stages, such as when a component is first added to the screen.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b58cbeb7-4c32-4b6b-a15d-7312111c9b2e', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you manage secrets and configuration in a highly regulated, multi-environment infrastructure?', N'Senior', N'I would use a dedicated secrets management tool like HashiCorp Vault to inject secrets at runtime, ensuring they are encrypted at rest and in transit. Configurations would be managed via externalized key-value stores or sidecars, allowing for environment-specific overrides without rebuilding application binaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dcb645a-cb32-4444-aa7c-7313712a14aa', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the potential pitfalls of using closures?', N'Intern', N'Closures can lead to memory leaks if not managed properly, especially when they capture variables that are no longer needed. They can also make debugging more difficult due to the complexity of the scope chain. Additionally, closures can cause performance issues if they are overused or used inappropriately, as they keep references to variables in their scope, which can prevent garbage collection. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the difference between global scope, function scope, and block scope Global scope means variables are accessible from anywhere in the code. Function scope means variables are accessible only within the function they are declared in. Block scope means variables are accessible only within the block (e.g., within {}) they are declared in.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f68667c3-5233-4d67-909a-7313a95a0075', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why does Rust forbid data races while allowing race conditions?', N'Senior', N'Rust''s type system and ownership rules prevent data races by ensuring that memory cannot be modified concurrently without synchronization. However, race conditions are a logical concurrency issue related to the order of operations, which the language cannot detect at compile time, as they depend on the specific application logic and timing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38b16835-278a-4632-91be-7316d27a12b7', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember handle route transitions?', N'Middle', N'Route transitions are managed by the router, which resolves models and triggers hooks in a specific sequence. If a model hook returns a promise, the transition remains pending until it resolves, allowing the application to display loading states gracefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8fabb99-dc49-47fa-b45d-73183b2dc975', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the difference between ''app'' and ''router'' in Express?', N'Junior', N'The ''app'' object is the main entry point representing the entire Express application. The ''router'' object is a mini-application instance used to modularize routes, allowing you to group related endpoints together and mount them onto the main application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4a14e74-f7ea-49a0-b079-7319c16dd038', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is BOM?', N'Intern', N'The Browser Object Model (BOM) allows JavaScript to "talk to" the browser. It consists of the objects navigator, history, screen, location and document which are children of window. The Browser Object Model is not standardized and can change based on different browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26c0ac34-9b8d-48c0-9192-731ba90e5558', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How do you handle distributed transactions in a microservices architecture using Spring?', N'Senior', N'Distributed transactions should be avoided in favor of the Saga pattern or TCC (Try-Confirm-Cancel) patterns. Spring Cloud can help coordinate these via messaging queues, ensuring eventual consistency instead of relying on atomic global transactions like XA/JTA which are not scalable in microservices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68c0994c-17e9-464d-92e9-7320ef3f3a83', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why do we use the ORDER BY clause?', N'Fresher', N'The ORDER BY clause is used to sort the result set of a query in either ascending or descending order. It helps in presenting data in a structured and readable format based on one or more columns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ffa25aa-5365-4341-b4ad-73216ae7e7b9', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix ensure secure communication in its Channel implementation?', N'Senior', N'Phoenix Channels utilize standard WebSocket authentication mechanisms, such as token-based auth during the initial handshake. Once established, the server can verify the identity of the process, and developers can implement authorization logic within the ''join'' function to restrict access to specific topics based on user permissions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10793af3-067a-4d5d-965a-7325cd6048e9', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the role of a task queue in a web application''s scalability?', N'Middle', N'A task queue offloads time-consuming or resource-intensive tasks from the main request-response cycle. By processing these tasks in the background, the web application remains responsive and can handle a much higher volume of concurrent user traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54f81710-9067-482a-a5ea-7326bfe724ef', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle data migrations in a production environment without causing downtime?', N'Middle', N'I use a multi-phase approach that involves keeping the old and new schemas in sync for a period of time. I first deploy code that writes to both locations, then backfill existing data, and finally switch the reads to the new structure. This allows me to verify data integrity before decommissioning the old system and provides an easy rollback path if errors occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ec43f7a-c09c-4d6a-bc02-7329f31a8bbf', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the significance of ''Suspense'' for data fetching in a modern React application?', N'Senior', N'Suspense provides a declarative way to handle loading states by allowing components to ''suspend'' rendering while waiting for asynchronous resources. It decouples the loading logic from the component code, enabling a cleaner architecture where the parent manages the fallback UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
