INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4902556-2bd7-44b9-a31e-732c0982ed86', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the ''box-sizing: border-box'' property affect element sizing?', N'Junior', N'By default, padding and borders are added to an element''s specified width and height. Setting box-sizing to border-box includes padding and borders within the defined width and height, making layout calculations much easier.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
