INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5eebc2d-a866-4afe-be39-7331ade73c86', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How would you implement a custom extractor in Axum for a specialized authorization header?', N'Senior', N'You would implement the ''FromRequestParts'' trait for your custom type, allowing it to inspect the request headers before the handler is invoked. This custom extractor can then be added as a function argument, enabling modular and reusable auth logic across multiple handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4792c056-0ed9-4d71-a9ef-73320d59154a', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Does Gin support grouping routes?', N'Intern', N'Yes, Gin allows developers to group routes together, which is useful for organizing endpoints with common prefixes. This feature also enables the application of specific middleware to an entire group of routes at once.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f4aad76-1aca-4dc7-b965-7332472c7c03', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the benefit of Svelte''s ''immutable'' prop optimization?', N'Senior', N'By setting the immutable attribute, the developer tells Svelte that props will not be mutated in place, allowing the framework to perform reference equality checks instead of deep comparisons. This reduces the computational overhead during reconciliation, which is highly beneficial for data-intensive applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9a8fb3e-7e20-435d-97ca-73328dc9a4e2', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify''s internal routing algorithm differ from traditional Express-style routing?', N'Middle', N'Fastify uses a radix tree-based router, which provides O(k) lookup time where k is the length of the path. This is significantly more efficient than the linear array traversal used by frameworks like Express, especially as the number of defined routes grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed85d12b-05f2-42df-95ab-7332b597b281', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS support authentication and authorization?', N'Fresher', N'Nest supports authentication and authorization through various ways: 1. Passport.js Integration: NestJS integrates smoothly with Passport.js, a popular authentication middleware for Node.js. Passport supports a variety of authentication strategies, such as OAuth, JWT, and local (username and password). 2. JWT Module: NestJS provides a JWT module (@nestjs/jwt) for generating and validating JSON Web Tokens, which are commonly used for stateless, server-side authentication. 3. Guards: In NestJS, guards are classes that control whether a given request is allowed to proceed to the route handler. They''re often used to implement authorization checks. 4. Decorators: Custom decorators can be used to provide metadata about routes, such as required roles for accessing a route. 5.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'085f3172-3d9d-49f3-8de2-73330bc03bb0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are some best practices for writing maintainable and effective tests in JavaScript?', N'Senior', N'To write maintainable and effective tests, ensure they are clear, concise, and focused on a single behavior. Use descriptive names for test cases and avoid hardcoding values. Mock external dependencies and keep tests isolated. Regularly review and refactor tests to keep them up-to-date with the codebase. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the concept of code coverage and how it can be used to assess test quality Code coverage is a metric that measures the percentage of code that is executed when the test suite runs. It helps in assessing the quality of tests by identifying untested parts of the codebase. Higher code coverage generally indicates more thorough testing, but it doesn''t guarantee the absence of bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2f06d8e-8699-42c2-a876-7336f4e8326b', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the benefit of using React.memo?', N'Middle', N'React.memo is a higher-order component that performs a shallow comparison of props to prevent unnecessary re-renders of functional components. It is a performance optimization tool useful when a component renders frequently with the same props.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcd1fee1-0e1e-440c-aa62-733ea6a9e58c', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you approach the trade-off between static and dynamic configuration in a distributed system?', N'Middle', N'Static configuration is simple and immutable, making the system state predictable, but it requires redeployments for changes. Dynamic configuration allows for runtime updates without restarts, which is crucial for high availability, but it introduces the risk of ''configuration drift'' and makes debugging environment-specific issues more difficult.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'943924d1-7814-4459-9e18-73402dae8e4b', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why does Ember emphasize ''Convention over Configuration''?', N'Middle', N'This principle reduces the decision-making overhead for developers by providing a standard structure for files and naming. It allows developers to switch between projects easily and ensures that the framework can perform ''magic'' like automatic route mapping and template resolution without manual configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'228ca778-5ef0-4ba0-9208-7341a3ad141b', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the performance implications of secondary indexes in NoSQL?', N'Middle', N'While secondary indexes improve read performance for queries filtering on non-primary fields, they introduce a write penalty. Every time a document is updated, the associated secondary indexes must also be updated, which can increase latency in write-heavy workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bd339f0-c31d-4c0a-ac9a-7343875bec91', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does the ''EventEmitter'' pattern facilitate decoupled architecture?', N'Middle', N'The EventEmitter pattern allows different parts of an application to communicate by emitting and listening for events without having direct references to each other. This reduces tight coupling, making the codebase easier to maintain, test, and extend with new functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'450bea3a-c98d-4d37-b77b-73447adea625', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does InnoDB manage thread concurrency to prevent CPU thrashing?', N'Senior', N'InnoDB uses an internal thread concurrency limit to prevent too many threads from accessing the engine simultaneously. By restricting the number of active threads, it reduces context switching and contention for internal mutexes, stabilizing performance under heavy load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e997a20-a736-49a7-951c-734590c5aa75', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If a system is running slowly, what is your approach to identifying the bottleneck?', N'Fresher', N'I would use monitoring tools to check resource utilization, such as CPU, memory, and disk I/O usage. Identifying which resource is hitting a limit helps determine if the issue is related to inefficient processing, memory leaks, or hardware constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'547f9553-1119-4316-85f5-73476c518583', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the Ember CLI?', N'Intern', N'Ember CLI is the command-line interface tool used to create, build, and maintain Ember applications. It provides a standardized project structure, automated testing utilities, and commands to generate boilerplate files quickly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6308ad0c-8c6f-4ee6-9054-73484480caf2', N'954a0331-deff-4399-b588-96f39fec001d', N'What is Sanitization? Does Angular support it?', N'Intern', N'Sanitization is the inspection of an untrusted value, turning it into a value that''s safe to insert into the DOM. Yes, Angular supports sanitization. It sanitizes untrusted values for HTML, styles, and URLs but sanitizing resource URLs isn''t possible because they contain arbitrary code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9a35f83-a344-4b1f-9855-73498e20a3bf', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Can you perform math in Sass?', N'Intern', N'Yes, Sass supports standard mathematical operators like addition, subtraction, multiplication, and division. This allows you to calculate spacing, widths, and font sizes relative to other values in your stylesheet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd29ffc6e-6dc0-455e-a8d8-734c24b37f00', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What does ''utility-first'' mean in the context of Tailwind?', N'Intern', N'Utility-first means that the framework provides small, single-purpose classes that do one thing, such as setting a margin or text color. Developers compose these classes together to create complex UI components without leaving their HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0f43490-c644-40cd-afda-734edb2ec141', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are the implications of using reified type parameters in Kotlin regarding bytecode generation?', N'Senior', N'Reified type parameters allow access to type information at runtime that is otherwise lost due to type erasure in the JVM. The compiler achieves this by inlining the function and copying the type information directly into the call site, which effectively preserves the type metadata at the cost of increased bytecode size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
