INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'461ce92b-8308-4b5f-a0ad-735335e3d45b', N'954a0331-deff-4399-b588-96f39fec001d', N'What is folding?', N'Intern', N'The compiler can only resolve references to exported symbols in the metadata. Where as some of the non-exported members are folded while generating the code. i.e Folding is a process in which the collector evaluate an expression during collection and record the result in the .metadata.json instead of the original expression. For example, the compiler couldn''t refer selector reference because it is not exported Will be folded into inline selector Remember that the compiler can’t fold everything. For example, spread operator on arrays, objects created using new keywords and function calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a2f19cd-bf75-4b5a-8d1b-7356d89e6935', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the difference between unit, integration, and acceptance testing in Ember?', N'Middle', N'Unit tests focus on a single object or function, integration tests check how a component interacts with the DOM and its template, and acceptance tests simulate full user scenarios across multiple routes. A healthy testing strategy uses a pyramid approach with a focus on acceptance and integration tests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e91ccf81-a4eb-47cf-bb3d-73579608ded7', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why is it important to choose between time complexity and space complexity when designing a simple algorithm?', N'Fresher', N'Resources like memory and processing power are finite. Choosing one over the other depends on whether the system is memory-constrained, such as an embedded device, or requires high-speed execution for real-time tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da82da35-c978-432e-bddc-7357f6280316', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the difference between SQL and MongoDB?', N'Intern', N'SQL databases are relational and use tables with fixed schemas, while MongoDB is a NoSQL document database that uses flexible collections. SQL databases are generally better for complex joins and ACID transactions, whereas MongoDB excels at handling diverse, rapidly changing data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8630397-c318-4ffe-bc47-735c9e14f744', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How do you handle background tasks or asynchronous processing in NestJS?', N'Middle', N'Background tasks are typically handled using a message broker like BullMQ or by utilizing built-in event emitters for local events. For longer-running tasks, offloading work to a separate worker process or queue ensures the main request-response cycle remains non-blocking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
