INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19bd1c6c-8ba9-4192-b1f2-7364c5bb4388', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a type predicate and when should you use one?', N'Middle', N'A type predicate is a function return type that takes the form ''parameterName is Type'', which informs the compiler about the specific type of a variable after a function call. They are used to create custom type guards when built-in narrowing techniques like ''typeof'' are insufficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'505bfd89-5a02-4793-9c55-7365de3cac43', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite resolve CSS imports compared to standard browser behavior?', N'Middle', N'Vite treats CSS files as modules, allowing them to be imported directly into JavaScript files. During development, Vite injects the styles into the DOM via style tags, while in production, it extracts them into optimized, minified CSS files to improve loading performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6096ba13-47b2-426a-93a3-73668212e845', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the purpose of the ''Astro.props'' object?', N'Junior', N'The ''Astro.props'' object allows you to receive data passed into a component from a parent component. It makes your components reusable by allowing them to accept dynamic content as configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'332f2a52-7584-4372-ad88-736886d9c53b', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the role of a database in a PHP application?', N'Intern', N'A database acts as the storage layer for a PHP application, holding structured data like user profiles, posts, or product information. PHP connects to the database using extensions to retrieve, insert, update, or delete data based on user actions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd67511b5-8273-4b4f-a50e-736987527eea', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the benefit of using Sass placeholders over mixins when generating repetitive CSS patterns?', N'Senior', N'Placeholders allow for ''DRY'' code by using selector grouping, which results in smaller CSS files compared to the code duplication caused by mixins. However, they lack the ability to accept arguments, making them better suited for static shared styles rather than dynamic component logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e603ba50-0a91-41c1-900e-7369f69d38ef', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain how Django''s ORM handles database-level locking.', N'Senior', N'Django provides the select_for_update() method, which generates a ''SELECT FOR UPDATE'' SQL query to lock rows until the end of the transaction. This is crucial for preventing race conditions in concurrent write scenarios, though it must be used sparingly to avoid deadlocks and performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'225ca534-94e1-48ff-acfb-736a08f7c38f', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the impact of the CSS cascade on bundle size and how can it be mitigated in a modular architecture?', N'Senior', N'The cascade allows styles to be shared globally, which can lead to redundant code if not managed via clear architectural patterns like BEM or CSS Modules. To mitigate this, developers should employ tree-shaking for CSS, modularize styles by component, and avoid deeply nested global overrides that force high specificity throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e61bb460-4eec-4b30-9d6a-736c30090786', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket manage configuration?', N'Intern', N'Rocket uses configuration files or environment variables to manage settings like port numbers, database URLs, and logging levels. This allows developers to change application behavior without modifying the source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5100320f-a136-443a-a45d-736d1a5459d2', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does the ''alpine:init'' event help in architecting large-scale Alpine applications?', N'Senior', N'The ''alpine:init'' event provides a hook to configure the framework, register custom directives, or define global data stores before the components begin initializing. This is crucial for modularizing large apps, as it allows for the orchestration of dependencies and global setup routines. It ensures that custom functionality is available globally before any component attempts to utilize it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d962a53-0f02-4b56-9f85-73704bcca3ae', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How can I organize my code to make it easier to change the base class?', N'Fresher', N'You could define an alias for the base class, assign the real base class to it before your class definition, and use the alias throughout your class. Then all you have to change is the value assigned to the alias. Incidentally, this trick is also handy if you want to decide dynamically (e.g. depending on availability of resources) which base class to use. Example: BaseAlias = class Derived(BaseAlias): def meth(self): BaseAlias.meth(self).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1bf90cc-c5f4-44cc-9fde-73724bdfee37', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the purpose of the ''x-init'' directive, and when should it be avoided?', N'Middle', N'The ''x-init'' directive is used to run code when a component is initialized, such as fetching data or setting up event listeners. It should be avoided for heavy initialization tasks that could block the main thread, as it executes synchronously during the component''s setup phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2e6a6b8-14cc-455f-9a2e-7372638b21d8', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does the Scala memory model handle tail-call optimization in the presence of the JVM''s stack limitations?', N'Senior', N'The Scala compiler can only perform tail-call optimization if the method is marked as final or is a private method, as these can be safely rewritten into a jump instruction. Because the JVM bytecode does not support general tail-call optimization, recursive calls that are not in a final position or are polymorphic cannot be optimized, leading to potential stack overflow errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5ad7c65-f342-4f08-a2d6-7373c0744f82', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the primary role of the Tower service trait in the Axum framework?', N'Middle', N'The Tower trait defines an asynchronous interface for processing requests and returning responses. It acts as the foundational abstraction that allows Axum to compose middleware, routing, and handlers into a unified request-processing pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd120512d-d6a9-4db2-b119-7375064233ed', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP handle variable typing?', N'Intern', N'PHP is a loosely typed language. This means you do not need to declare the data type of a variable when creating it, as the language automatically assigns the type based on the value assigned to the variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b479dc2-cb9f-421c-bb06-7376e7d054ef', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the advantage of Remix being framework-agnostic regarding the server?', N'Intern', N'Because Remix uses standard web APIs, it can be deployed to many different environments like Node.js, Cloudflare Workers, or Deno. You are not locked into a specific server infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2129c3cc-4104-4f0e-aebf-73777065a950', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are Promises in Node.js?', N'Intern', N'It allows to associate handlers to an asynchronous action''s eventual success value or failure reason. This lets asynchronous methods return values like synchronous methods: instead of the final value, the asynchronous method returns a promise for the value at some point in the future. Promises in node.js promised to do some work and then had separate callbacks that would be executed for success and failure as well as handling timeouts. Another way to think of promises in node.js was that they were emitters that could emit only two events: success and error.The cool thing about promises is you can combine them into dependency chains (do Promise C only when Promise A and Promise B complete). The core idea behind promises is that a promise represents the result of an asynchronous operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7df801ed-652e-4123-8957-7378d022af33', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does the C++ type system enforce const-correctness?', N'Senior', N'Const-correctness is a design discipline where objects are marked as immutable whenever possible, allowing the compiler to enforce read-only access at compile time. This improves code robustness, facilitates better optimization, and provides clear documentation about the intended usage of data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1917f7e-0b4c-4c91-8ed6-73791face5cd', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the concept of ''deferred loading'' in Dart and its impact on application architecture.', N'Senior', N'Deferred loading allows developers to load libraries asynchronously at runtime, which is a key strategy for reducing the initial bundle size of large applications. By splitting code into chunks that are fetched on-demand, architects can improve cold-start performance, though it necessitates careful handling of asynchronous state transitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
