INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6017547f-b01d-4575-9af9-737d773b1c87', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the role of Rollup in the Vite ecosystem?', N'Middle', N'While Vite uses esbuild for development, it delegates the final production build to Rollup. Rollup provides more mature and flexible tree-shaking, code-splitting, and output optimization features that are better suited for static assets in production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'487a6eb2-fdbb-48d7-9186-7383c7c42e00', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How does ''Data Locality'' affect architectural design in distributed systems?', N'Senior', N'Data locality involves placing data close to the compute resources that process it to reduce network latency and bandwidth consumption. In distributed systems, ignoring data locality leads to performance bottlenecks caused by heavy data movement across network partitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f54a5171-d443-4081-9658-738437335106', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why use Elasticsearch instead of a database for searching?', N'Fresher', N'Elasticsearch is specifically optimized for full-text search, relevance scoring, and handling unstructured data. Databases like MySQL are typically slower for complex text searches and lack advanced features like tokenization and fuzzy matching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
