INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf562942-f894-409a-ac8c-738d4aeffea3', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Why is ''constant lookup'' in Ruby considered dynamic?', N'Middle', N'Constant lookup follows the nested lexical scope of the code and the inheritance chain of the class. Because Ruby allows classes and modules to be reopened at runtime, the value or existence of a constant can change, making lookup behavior more flexible than in strictly compiled languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd59bb2e7-d57e-4f41-9334-738e28120fc6', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus optimize the Hibernate ORM for cloud-native environments?', N'Senior', N'Quarkus optimizes Hibernate by performing static analysis of mapping metadata at build time. It pre-calculates the necessary metamodels, reducing the memory overhead and time required to initialize the persistence layer during application startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c38172b-490c-4a5f-a551-738f2f5a9320', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is meant by the term ''routing'' in Flask?', N'Fresher', N'Routing is the process of mapping a specific URL to a particular function in your application. When a user visits a URL, the Flask router determines which function should be executed to generate the response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf9c7ae3-19f9-4617-852d-7393bdb5cc05', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When choosing an error handling strategy, what is the trade-off between failing fast and retrying?', N'Middle', N'Failing fast prevents the system from wasting resources on doomed operations and keeps the system responsive, but it requires the client to handle the error. Retrying can mask transient failures and improve reliability, but if not implemented with backoff and jitter, it can lead to cascading failures and overload a struggling downstream service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db114b02-5b50-4f61-b52d-7398470796ad', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis perform compared to memcached?', N'Middle', N'Redis supports a wider variety of complex data structures like lists, sets, and sorted sets, whereas memcached is strictly a key-value store. Additionally, Redis supports native persistence and replication, making it more versatile for complex architectural needs compared to the simpler, memory-only design of memcached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97888cbd-732f-4154-8662-739850c87eb0', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is an ORM and how does it work in Django?', N'Fresher', N'An Object-Relational Mapper (ORM) is a technique that allows you to interact with your database using Python classes instead of writing raw SQL queries. Django''s ORM maps Python objects to database tables, allowing developers to perform CRUD operations using built-in methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f77a6a8-ec99-4b63-8d6a-73990cc6b397', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the ''Event Loop'' prioritize tasks when multiple sources (timers, I/O, user input) are active?', N'Senior', N'The event loop prioritizes user-initiated events and microtasks to maintain perceived responsiveness, while macrotasks like timers are processed based on their delay and queue position. This scheduling logic ensures that the UI remains interactive even under heavy background processing loads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'058e2251-a481-43a8-824e-739ac467519c', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the @Repository annotation used for?', N'Fresher', N'The @Repository annotation is a marker for any class that fulfills the role of a data access object (DAO). It also provides an exception translation mechanism, converting low-level database exceptions into Spring''s unified DataAccessException hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'423c9749-3e05-4b96-87da-739b9b4fd403', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus achieve ''Native Executable'' support, and what are the trade-offs?', N'Middle', N'Quarkus uses GraalVM Native Image to compile Java bytecode into a standalone machine-code executable using ahead-of-time compilation. The trade-offs include significantly longer build times and the requirement to handle dynamic features like reflection, serialization, and proxying manually through configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
