INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fee9d552-8e3e-4b03-8eb4-739e70703074', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Explain the concept of ''Partial Hydration'' as implemented in Astro.', N'Senior', N'Partial hydration is the selective execution of JavaScript for individual components on a page. By only hydrating components that require interactivity, Astro prevents the entire page from being locked by the framework''s runtime initialization, leading to a much faster interactive state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb82e364-f5cc-44ff-b465-73a049847a6d', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin''s approach to operator overloading differ from other languages, and what are the risks?', N'Senior', N'Kotlin restricts operator overloading to a predefined set of function names mapped to symbolic operators, ensuring consistency and predictability. While this improves readability for domain-specific languages, overusing it can lead to confusion if the semantic meaning of the operator does not align with the developer''s expectations of the underlying mathematical or logical operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
