INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e02f4a40-70a0-47a9-8f87-73b12c2b02a9', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the difference between a shallow copy and a deep copy.', N'Junior', N'A shallow copy creates a new object but inserts references into it for the objects found in the original, meaning nested objects are still linked. A deep copy creates a new object and recursively copies all objects found in the original, ensuring that the new copy is completely independent of the original. This is important when working with mutable nested structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
