INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2bc7ff8-4da8-44c7-84e2-73c864ec1cdb', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain the architectural challenge of ''Uncaught Exceptions'' in Node.js and the recommended production strategy.', N'Senior', N'An uncaught exception puts the Node.js process in an undefined state where memory corruption or resource leakage may occur. The recommended production strategy is to log the error, perform a graceful shutdown of the process, and rely on an orchestrator like Kubernetes to automatically restart the failed instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bee967b0-d76b-4197-ae95-73ce4b246466', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What are the implications of Go''s memory model regarding synchronization primitives?', N'Senior', N'Go''s memory model defines the conditions under which reads of a variable in one goroutine can be guaranteed to observe values produced by writes in another. It relies on explicit synchronization primitives like channels or mutexes to establish ''happens-before'' relationships, as compiler and CPU reordering can otherwise lead to data races.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96f08ab0-2491-4635-8ba2-73cedf8466cd', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is a ''partial'' hydration strategy?', N'Intern', N'Partial hydration is the process of loading JavaScript only for the parts of the page that require interactivity. This prevents the browser from having to download and parse unnecessary scripts for static elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1cc0280-b7ad-4a8e-8446-73cf5a8ddc50', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the function of the Program.cs file in modern ASP.NET Core?', N'Junior', N'The Program.cs file serves as the entry point for the application. It is responsible for configuring the web host, setting up dependency injection services, and defining the middleware pipeline that processes incoming requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd90b8a90-a692-4be6-a698-73cf83155255', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is Redux Form?', N'Intern', N'_Redux Form_ works with React and Redux to enable a form in React to use Redux to store all of its state. Redux Form can be used with raw HTML5 inputs, but it also works very well with common UI frameworks like Material UI, React Widgets and React Bootstrap.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'222a5e64-7950-4e54-a439-73cf9cc4ecfc', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a bug that occurs intermittently?', N'Junior', N'Intermittent bugs, or ''heisenbugs,'' often relate to race conditions or resource contention. I would focus on gathering as much contextual data as possible during the failure events, such as system load or concurrent user activity, to find a pattern.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f7afaf1-b85f-4768-ac7f-73d0079ab60d', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle environment variables and what is the security trade-off?', N'Senior', N'Vite exposes environment variables through import.meta.env, prefixing only those starting with VITE_ to the client bundle to prevent accidental leakage of sensitive server-side credentials. Developers must be careful never to expose secrets that should remain server-side, as these values are statically replaced during the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'641d7a08-9ba2-4f34-bf94-73d0eaeafc7e', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the difference between static site generation (SSG) and server-side rendering (SSR) in Astro?', N'Intern', N'Static site generation renders pages once at build time, creating static files for deployment. Server-side rendering generates pages dynamically on the server every time a user requests a specific route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebb8f9d2-fd45-4bad-9d86-73d1d8421417', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What architectural risks are introduced by using mutable state in a Scala application?', N'Senior', N'Mutable state breaks referential transparency, making it significantly harder to test, parallelize, and reason about the system''s behavior. In a concurrent environment, mutable state necessitates explicit synchronization, which often leads to performance bottlenecks and difficult-to-reproduce concurrency bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6abc622-3230-4901-951c-73d2bae76d1b', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of ''Anti-Forgery Tokens''?', N'Middle', N'Anti-forgery tokens are used to prevent Cross-Site Request Forgery (CSRF) attacks. They ensure that a request was intentionally initiated by an authorized user from your own web application rather than a malicious third-party site.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb5dbedb-bbab-450d-8896-73d72a05cd5b', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why does Lit use template literals?', N'Intern', N'Lit uses tagged template literals to define HTML templates in a way that is both readable and efficient. These templates are parsed once and then updated dynamically, which is much faster than standard string manipulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18a3d72b-5105-427b-b4a8-73d97ce5307d', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Describe the hydration process in Next.js and why ''Hydration Mismatch'' errors occur.', N'Senior', N'Hydration is the process where React attaches event listeners and state to the server-rendered HTML on the client. A mismatch occurs when the server-rendered DOM structure differs from what React expects during the initial client-side render, often caused by non-deterministic content like timestamps or browser-specific data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0379ce23-cdaf-4cf0-924a-73db42f3b503', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are the trade-offs of using Annotations versus Attributes for metadata?', N'Middle', N'Annotations rely on parsing docblocks via third-party libraries, which can be slower and more prone to syntax errors. Attributes are native to modern PHP, offer better IDE support, provide static analysis benefits, and are generally more performant because they are parsed by the PHP engine itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
