INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4de64bcd-7c73-4154-a893-73e3ac0d734c', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the ''Observer Effect'' in distributed systems monitoring?', N'Senior', N'The observer effect occurs when the act of monitoring or tracing a system consumes enough resources to alter the behavior or performance of the system being monitored. This can lead to misleading telemetry data, especially in latency-sensitive applications where the monitoring overhead creates artificial bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14a5d0ba-8d03-43e4-81eb-73e56b86558d', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle graceful degradation in the event of high traffic?', N'Senior', N'Chi itself is just a router, so graceful degradation must be implemented through middleware like circuit breakers or rate limiters. By applying these policies at the router level, you can protect downstream resources and ensure the application fails gracefully when saturated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
