INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba8fa4cb-0c72-4607-85c9-73f04f22ee6b', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is Cassandra considered an AP system in the CAP theorem?', N'Junior', N'Cassandra prioritizes Availability and Partition tolerance over strong Consistency. This means the system is designed to always be writable and readable even during network partitions, though it may occasionally return slightly stale data until synchronization occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
