INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd05f228c-efa5-4c58-a1cf-73f16578ea94', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs of using an ORM versus writing raw SQL queries?', N'Junior', N'An ORM abstracts database operations into objects, increasing developer productivity and reducing repetitive code. Writing raw SQL offers better performance and full control over complex queries but requires more effort and makes the code less portable across different database systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ee8f169-060c-445a-a7dc-73f25fbea938', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Compare the ''SSR'', ''CSR'', and ''Static'' rendering modes in SvelteKit.', N'Senior', N'SSR renders content on the server for speed and SEO, CSR renders in the browser for dynamic interactive apps, and Static generates content at build time for maximum performance. SvelteKit allows mixing these on a per-route basis, enabling developers to choose the best rendering strategy for each part of their application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f55a3347-8724-4673-a075-73f8231cd547', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the role of the volatile keyword and its impact on memory visibility.', N'Middle', N'The volatile keyword ensures that changes made to a variable are immediately visible to all threads by preventing compiler optimizations that cache values in local registers. It establishes a happens-before relationship for memory writes, ensuring thread safety for simple flag variables without the full overhead of synchronization locks, though it does not provide atomicity for compound operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93a09887-bbf6-4e62-a8ed-73fca5953d95', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Is Redux tied only to React?', N'Intern', N'No, Redux is a standalone library that can be used with any framework or even with plain JavaScript. It is most commonly associated with React because of its ability to manage state in component-based architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01d11694-f6b9-4021-9b7f-73fe3e819be0', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do ''Dependency Maps'' assist in incident response?', N'Senior', N'Dependency maps provide a visual representation of service relationships and traffic flows, which is critical during an outage to determine the blast radius. They allow responders to quickly identify the root cause by highlighting which downstream services are experiencing failures or latency spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94e4090e-6373-48e5-bda0-73feacbb26e8', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin''s delegation pattern improve code architecture?', N'Middle', N'Delegation allows a class to satisfy an interface by forwarding calls to an internal object, effectively favoring composition over inheritance. This promotes cleaner code by allowing objects to adopt behavior from multiple sources without the limitations of single inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03c96e5c-0dca-4a2c-9d5a-73ff0a203680', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why is ''Streaming'' in the App Router critical for perceived performance?', N'Senior', N'Streaming allows the server to send the initial HTML shell immediately while the rest of the content, such as slow database queries, is streamed as it becomes available. This prevents the browser from waiting for the entire page to render, significantly improving the Largest Contentful Paint metric.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18b5fdee-a829-42ed-b2bd-740676b0f113', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is the use of ''eval'' or dynamic code execution considered a security and performance risk in Node.js?', N'Senior', N'Using eval exposes the application to code injection vulnerabilities if untrusted input is processed. From a performance perspective, it prevents V8 from performing static analysis and optimizations, leading to significantly slower execution. Strict CSP and avoiding dynamic compilation are standard security and performance practices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a06baf70-bcd5-4503-99e1-740798e4b0b2', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is a replica set?', N'Intern', N'A replica set is a group of MongoDB instances that maintain the same data set. It typically consists of one primary node that receives all write operations and several secondary nodes that replicate the data from the primary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'767ebe97-d335-41d8-8d35-740866287600', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the significance of the One Definition Rule (ODR)?', N'Middle', N'The ODR states that objects and functions must have exactly one definition within a program, though they can have multiple declarations. Violating this rule leads to linker errors or undefined behavior, as the compiler cannot determine which version of the symbol to use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f983f82b-03be-43fe-823d-7408ec76af45', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'When would you choose Astro over a framework like Next.js?', N'Middle', N'Astro is preferred for content-focused sites like blogs, documentation, or marketing pages where performance and SEO are critical. Next.js is often better for complex, highly dynamic web applications that require frequent state changes and server-side logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7590b2d-d07a-4b6d-93f1-740e2f8b54c6', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a destructor?', N'Intern', N'A destructor is a special member function that is automatically called when an object goes out of scope or is explicitly deleted. It is used to release resources, such as memory, that were acquired by the object during its lifetime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ca9d604-028e-42fe-bb32-740effeccb2b', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle JSON request bodies?', N'Junior', N'Rocket provides a built-in JSON type that acts as a data guard. When used as a function parameter, it automatically attempts to deserialize the incoming request body into your provided Rust struct, returning an error if the format is invalid.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c7502d4-eac5-4fa7-917f-740ff29c59f6', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the ''diffing'' strategy when lists are rendered in Preact?', N'Middle', N'Preact uses a keyed diffing algorithm to track list items efficiently. By using unique keys, it minimizes DOM operations by reusing existing elements instead of destroying and recreating them, which is critical for maintaining performance in dynamic lists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4cb209b-c453-4d4e-9817-74105ff5e1ee', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is a route parameter?', N'Junior', N'Route parameters are named URL segments that are used to capture the values specified at their position in the URL. The captured values are populated in the req.params object, with the name of the route parameter specified in the path as their respective keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91480951-e82e-4f87-8d0e-7410ba53b949', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why is it beneficial to separate the Webpack runtime into a distinct chunk?', N'Senior', N'The runtime contains the logic for loading and connecting modules, which changes whenever the dependency graph is updated. By separating it, the runtime code remains isolated from the content hashes of your application code, preventing the main bundle''s filename from changing unless the runtime logic itself is modified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'152469a5-9c6a-4277-ba45-74116cac1248', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of a constructor in C#?', N'Intern', N'A constructor is a special method called automatically when an instance of a class is created. Its primary purpose is to initialize the state of the object, such as setting default values for its fields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b998498-c7c6-4540-b204-741213eefd4c', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS differ from React in terms of rendering?', N'Fresher', N'React uses a virtual DOM and re-renders components whenever state changes. SolidJS compiles components into direct DOM updates, meaning it only runs the component code once and updates specific parts of the DOM when dependencies change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad204ff4-7a4a-4c56-b39d-7413ed17f318', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the difference between ''Eventual Consistency'' and ''Strong Consistency'' in caching?', N'Middle', N'Strong consistency ensures that every read returns the most recent write, usually requiring expensive synchronization between the cache and database. Eventual consistency allows temporary discrepancies for the sake of higher performance and availability, trusting that the system will synchronize over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07ef87d0-e6fb-4877-9b04-741527da182c', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Why do databases use ''Buffer Pools'' or ''Page Caches''?', N'Senior', N'Buffer pools act as an in-memory cache for frequently accessed disk pages, reducing the need for expensive physical disk I/O. By keeping hot data in memory, the database can service read and write operations at RAM speeds, significantly improving overall system responsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'963e7185-8ad7-40be-bfad-74156d2c397d', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the Java Memory Model (JMM) ensure memory visibility across threads in a multi-core architecture?', N'Senior', N'The JMM defines the happens-before relationship, which establishes a formal partial ordering on memory operations. It mandates that actions performed by a thread are visible to other threads only when synchronized through volatile variables, locks, or concurrent utilities, effectively flushing local CPU caches to main memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'990f5f38-807d-4f62-bf95-741db5a2fd42', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is global scope pollution a concern when using jQuery plugins?', N'Middle', N'Many older jQuery plugins attach themselves to the global jQuery object or the window object, which can lead to naming conflicts in large applications. This makes it difficult to manage dependencies and increases the risk of side effects when multiple scripts are loaded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'207f942f-3c8a-4fcd-9628-741ecab27bbc', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What does cooperative multitasking mean in relation to fibers?', N'Intern', N'Cooperative multitasking means that each fiber must explicitly yield control back to the scheduler when it reaches a point where it can wait. This prevents the system from having to forcibly interrupt tasks, leading to more predictable execution flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4c46da4-e265-439c-8f5f-741f28748ed5', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Is Qwik suitable for high-interactivity applications?', N'Middle', N'Yes, Qwik is well-suited for high-interactivity apps because it keeps the main thread free by delaying the execution of non-essential code. This makes the UI feel responsive even if the total application size is massive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7be9414-b095-425e-9b62-7421d81dcb5b', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the primary architectural difference between React and Preact regarding the virtual DOM?', N'Middle', N'Preact utilizes a much smaller, more efficient virtual DOM implementation compared to React. It avoids some of the complex reconciliation overhead found in React, focusing on a lightweight diffing algorithm that prioritizes speed and minimal bundle size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cd67da6-6160-49c7-8581-7422c850303a', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Explain the concept of ''hot keys'' in Redis and how to mitigate their impact on cluster performance.', N'Senior', N'Hot keys occur when a single key receives a disproportionately high volume of traffic, creating a bottleneck on the specific node holding that key. Mitigation strategies include client-side caching to reduce requests to Redis, or distributing the key by appending random suffixes to create multiple shards for the same logical data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73166332-f995-47b0-b41e-74243ef5ce1f', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a GIN index and when is it preferred?', N'Middle', N'GIN (Generalized Inverted Index) is designed for handling data types where a single value can contain multiple elements, such as arrays or JSONB documents. It is preferred when you need to perform efficient searches for individual elements within these complex, composite data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
