INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'034f2ab1-810a-4b3f-9d7d-74274681bf84', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the benefit of using the ''Map'' data type?', N'Fresher', N'A Map allows you to store a collection of key-value pairs as a single attribute. This is useful for representing JSON-like structures directly inside a DynamoDB item.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe09a75e-3cbd-442c-bbd2-7427ae0c0fa3', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle logging?', N'Intern', N'Fastify includes a built-in logger called Pino, which is designed for high performance. It logs information about requests and responses automatically and can be configured to output logs in various formats, such as JSON.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0a21317-02c7-47cc-85c1-7429650431d9', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a database deadlock?', N'Intern', N'A deadlock occurs when two or more transactions are waiting for each other to release locks on resources. Because neither transaction can proceed, the database system must detect and terminate one of them to resolve the conflict.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5567eae-0e3c-49a5-99db-74297abb60cf', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What approach do you take to improve system observability in a legacy monolith without significant refactoring?', N'Senior', N'I introduce sidecar proxies or instrumentation wrappers to collect metrics and traces at the network level without altering core application logic. I then focus on aggregating logs into a centralized system to create dashboards that provide visibility into the monolith''s health and performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b441522-6bb6-4f18-b793-742a4e537479', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What does ''schema-less'' mean in NoSQL?', N'Intern', N'Schema-less means that the database does not require a predefined structure for the data before it is inserted. This allows for flexibility as the data structure can evolve over time without needing to modify the entire database design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46cd53ec-8915-4924-8f6b-742bf37a74e2', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is eventual consistency in Cassandra?', N'Fresher', N'Eventual consistency means that while all replicas of a data item will eventually be consistent with each other, they may not be identical at a specific point in time. Cassandra allows users to tune this consistency level based on their application needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ee5f6f4-ba1f-4abd-a84a-742ebdfef0c3', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Why would you choose to use an interface over an abstract class?', N'Middle', N'Interfaces allow for multiple inheritance of behavior, as a class can implement any number of interfaces. Abstract classes are better suited for defining a base identity for objects that share a significant amount of implementation logic. Use interfaces when you need to define a contract that unrelated classes can fulfill.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d6f683a-3bef-46ec-ae08-742ec56947ca', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'When designing an API, how do you manage versioning to minimize breaking changes for consumers?', N'Middle', N'I prefer using URI versioning for major changes to ensure clear separation and backward compatibility. For minor, non-breaking changes, I follow the principle of additive design, ensuring that new fields or endpoints do not disrupt existing client expectations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1b1b4ee-a5b7-4dbf-8288-742f38327c2f', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is an inner class?', N'Junior', N'An inner class is a class defined within another class. It has access to all members of the outer class, including private ones, and is used to logically group classes that are only used in one place.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afa9f92a-8edb-4fd1-bff0-7430ef02c955', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the Task Scheduling feature in Laravel?', N'Intern', N'Task Scheduling allows you to define your scheduled tasks fluently and expressively within the application itself. It replaces the need to create individual Cron entries on your server, providing a clean interface to manage recurring tasks like email notifications or database cleanups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e84746c-0e47-4a4e-85ad-743295c8d97c', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the difference between a retry and a fallback?', N'Middle', N'A retry attempts the same operation again, hoping for a transient success. A fallback executes a different, usually simpler or cached, operation when the primary operation fails, ensuring the user still gets a response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0feeed30-d798-4eb7-8266-74347c6d638a', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'When should you choose DynamoDB over a Relational Database (RDBMS)?', N'Middle', N'DynamoDB is preferred for applications requiring predictable, single-digit millisecond latency at any scale and those with massive throughput requirements. It is best suited for workloads with simple access patterns, whereas RDBMS is better for complex joins and multi-table transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b41acc3d-d3d6-464a-8778-7435ad86927f', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the significance of the PSR-7 and PSR-17 standards in the context of the HttpFoundation component?', N'Senior', N'While Symfony''s HttpFoundation is the framework''s native implementation, PSR-7 and PSR-17 provide standardized interfaces for HTTP messages and factories. Adopting these allows for better interoperability between Symfony and other libraries, facilitating the use of middleware-based architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'452fc4c2-fd50-408a-b4f0-7438b423452b', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery handle memory management differently than modern frameworks in single-page applications?', N'Senior', N'jQuery''s manual manipulation often leads to detached DOM nodes and memory leaks if event listeners are not explicitly unbound during component destruction. Modern frameworks automate lifecycle management, ensuring that event listeners and references are cleaned up when elements are removed from the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
