INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b1a30f5-1735-4516-8e2f-743e6e04b5f0', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why is ''perfect'' code often considered a poor goal for a project?', N'Fresher', N'Chasing perfection often leads to ''over-engineering,'' which wastes time and budget without providing proportional value. A balanced approach focuses on delivering high-quality, maintainable code that meets requirements within the project''s constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b57d1c6b-5b4d-4dde-8e03-744041e06cf0', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the function of the Commit Log in Cassandra?', N'Middle', N'The Commit Log acts as a crash-recovery mechanism that records all incoming write operations before they are applied to the Memtable. In the event of a node failure, Cassandra replays the commit log to restore data that was not yet flushed to SSTables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96297634-eaed-4386-99a8-74418870288f', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the risk of a ''cache stampede'' or ''thundering herd'' problem in Redis?', N'Middle', N'A cache stampede occurs when a highly popular key expires, causing multiple concurrent requests to simultaneously miss the cache and overwhelm the underlying database. This is typically mitigated by using distributed locks or by implementing probabilistic early expiration strategies to refresh the cache before it expires.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
