INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6758032c-6864-4b75-b9ae-74431cd225c0', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does the AdonisJS ''View'' engine contribute to application security?', N'Senior', N'The templating engine automatically escapes output by default, providing built-in protection against Cross-Site Scripting (XSS) attacks. By abstracting the rendering process, it ensures that security best practices are applied consistently without developer intervention for every output point.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5430af24-f02c-4445-a38d-7445c7f10d89', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are the architectural implications of using Symfony Messenger for asynchronous task processing?', N'Senior', N'Messenger decouples the execution of time-consuming tasks from the request-response lifecycle by serializing messages and pushing them to a transport layer. This improves system scalability and responsiveness, though it introduces the requirement for handling eventual consistency and designing idempotent consumers to recover from potential failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7452ebb8-09b6-4385-bac8-744a95f79ce2', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the purpose of a covered query in MongoDB?', N'Middle', N'A covered query is one where all fields in the query and the projection are part of an index. Because the database can satisfy the request entirely from the index, it avoids scanning the actual documents on disk, resulting in significantly faster performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
