INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78b99130-4a26-4737-b0a3-7454e1f60d9b', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Describe the impact of ''false sharing'' on performance in multi-core Go applications.', N'Senior', N'False sharing occurs when multiple goroutines modify independent variables that reside on the same CPU cache line, causing the cache to be invalidated across cores repeatedly. This forces synchronization at the hardware level, leading to significant performance degradation that can be mitigated by padding data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b974b7f-7e25-468c-879b-745608cdbae7', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Are arrays in R homogeneous or heterogeneous?', N'Fresher', N'Arrays in R are homogeneous, meaning all elements within the array must be of the same data type. They can be multi-dimensional, allowing for data storage beyond two dimensions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4eae3535-907f-406b-88d0-745948850d49', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the difference between ''onReady'' and ''onListen'' hooks?', N'Junior', N'The ''onReady'' hook is triggered when all plugins have been registered and the application is ready to start, while ''onListen'' is triggered when the server has successfully started listening on the specified port.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54e645e1-3584-4442-9ebb-7459e2e8c8cb', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Why is ''String.Intern'' generally discouraged in modern high-performance C# applications?', N'Senior', N'String interning stores all interned strings in a global, permanent pool that is never cleared by the GC, potentially causing memory bloat if used with dynamic data. It also introduces lock contention because the intern pool must be synchronized for thread-safe access during string lookups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'082f90bc-9628-4a93-839c-745b67801ede', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket ensure type safety for input data?', N'Fresher', N'Rocket uses Rust''s type system to bind incoming data like form fields or JSON bodies to strongly typed structs. If the incoming data does not match the expected structure, the request is automatically rejected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ac2a9f4-c8fa-4b8f-b12e-745dfa5a804c', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the function of a Foreign Key?', N'Junior', N'A foreign key is a column or group of columns that provides a link between data in two tables. Its primary purpose is to maintain referential integrity, ensuring that the data in the child table matches the data in the parent table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77a3e550-2745-4c2b-b2b0-745e7a818727', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why should you initialize a pointer after declaring it?', N'Junior', N'If a pointer is not initialized, it will contain a random memory address, known as a dangling or wild pointer. Dereferencing such a pointer leads to undefined behavior, which is a common source of difficult-to-track bugs. Initializing it to NULL or a valid address ensures safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4f09158-9799-4265-bf6d-74602f8dc97d', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit''s update lifecycle handle batching to prevent unnecessary DOM mutations?', N'Senior', N'Lit schedules updates asynchronously using a microtask queue, which allows multiple property changes to be batched into a single render cycle. This prevents redundant DOM writes and ensures the component only reconciles with the DOM once per task.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02ae2410-df5f-4c1f-8b63-7460c8623616', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL handle data types?', N'Fresher', N'PostgreSQL is a strongly typed database, meaning every column must be defined with a specific data type such as integer, text, or boolean. This ensures that only valid data is stored in specific columns, which helps prevent data corruption and improves query performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed94061b-d99f-4b11-8a04-7460e075d069', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is File Handling?', N'Intern', N'File is a named location on the disk, which stores the data in permanent manner. Python language provides various functions and methods to provide the communication between python programs and files. Python programs can open the file, perform the read or write operations on the file and close the file We can open the files by calling open function of built-in-modules At the time of opening the file, we have to specify the mode of the file Mode of the file indicates for what purpose the file is going to be opened(r,w,a,b)', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7a04ff2-764e-4e19-9674-7460e18f1c63', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind handle specificity issues compared to standard CSS?', N'Middle', N'Tailwind avoids specificity wars by using a flat, utility-based structure where styles are applied directly to elements. Since utility classes are designed to be atomic, you rarely run into the complex nested selector issues common in traditional stylesheets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36a1bc48-cf5e-4103-821b-746154811df0', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the benefit of Chi''s ''Mux'' being an implementation of http.Handler?', N'Middle', N'Because Mux implements the standard handler interface, you can nest Chi routers inside other Chi routers or even pass a Chi router to another standard Go server implementation. This composability allows for building complex microservices that can be easily merged or refactored.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
