INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9921622f-6836-44f4-9ae1-747735f43147', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you determine if a caching layer is necessary for a high-traffic endpoint?', N'Middle', N'I look at the read-to-write ratio and the latency requirements of the endpoint. If the data is read-heavy and does not need to be perfectly real-time, implementing a cache like Redis significantly reduces database load and improves response times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
