INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'147a6050-d34f-4fb9-81ea-74885c09d4bf', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why is Redis often described as a key-value store rather than a relational database?', N'Junior', N'Redis organizes data as simple key-value pairs where every piece of data is associated with a unique key. It lacks the concept of tables, rows, and columns found in SQL databases, focusing instead on high-speed access to specific data points.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20504b9d-1079-42b6-82f5-748be54d813f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the architectural trade-offs of using mapped types versus utility types for type transformations?', N'Senior', N'Mapped types provide granular control over key iteration and transformation, making them highly powerful for building generic APIs. Utility types offer standardized, readable abstractions for common transformations but may hide complexity that could be better handled by specific mapped logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9a55c03-25ff-411b-9b40-748ca2c27f39', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is it important to keep blocking operations out of Actix handlers?', N'Middle', N'Actix runs on an event loop that must remain non-blocking to handle concurrent requests efficiently. If a blocking operation is performed directly in a handler, it stalls the entire event loop thread, preventing the framework from processing other pending requests until the blocking task completes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95b6836a-c46c-47a9-bbba-74914d59bb0c', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the difference between synchronous and asynchronous replication in Redis?', N'Middle', N'Redis replication is primarily asynchronous, where the master sends commands to replicas without waiting for acknowledgement to maintain low latency. While this is fast, there is a small window of data loss risk if the master fails before the replica receives the latest updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0823dde-540f-45bf-bd0a-74937e1894ec', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why is it considered a bad practice to mutate state directly in Redux?', N'Middle', N'Direct mutation prevents Redux from detecting state changes correctly, which breaks change detection mechanisms used by UI libraries like React. Immutability ensures that the store can efficiently determine if a component needs to re-render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbad6107-c5dd-4d88-a928-7496bbee0883', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the architectural benefit of decoupling the ''View'' layer from the ''Controller''?', N'Senior', N'Decoupling ensures that controllers remain focused on handling requests and coordinating services, while views only concern themselves with representation. This separation allows for easier swapping of frontend frameworks, such as moving from Blade templates to an API-driven SPA, without modifying the underlying business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42e5b386-168f-4ecb-8b3f-7498448cc9e5', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the array detection mutation methods?', N'Intern', N'As the name suggests, mutation methods modifies the original array. Below are the list of array mutation methods which trigger view updates. 1. push() 2. pop() 3. shift() 4. unshift() 5. splice() 6. sort() 7. reverse() If you perform any of the above mutation method on the list then it triggers view update. For example, push method on array named ''todos'' trigger a view update,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d43ab3d-d95a-4da2-87e0-749c73de989f', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does the ''TypedHeader'' extractor improve API reliability?', N'Senior', N'TypedHeader automates the parsing and validation of HTTP headers, converting them into strongly typed structures. This eliminates the boilerplate of manual string parsing and provides immediate feedback if a client sends invalid headers, moving validation logic to the edge of the request processing pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2a956e5-cec6-4588-a09c-74a231dc4f89', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of the Service Container in Symfony?', N'Intern', N'The Service Container is a tool used to manage the instantiation and injection of objects, known as services, throughout an application. It promotes loose coupling by allowing components to request their dependencies rather than creating them manually. This central management makes the code easier to maintain, test, and configure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c732bda-911c-4dbb-abf1-74a246a35a2e', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does the SAVEPOINT command work?', N'Fresher', N'A savepoint is a marker within a transaction that allows you to roll back part of the transaction without canceling the entire process. You can return to a specific savepoint while keeping the work done before that point intact.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa340986-5b71-4506-b6c3-74a77a1f307b', N'954a0331-deff-4399-b588-96f39fec001d', N'What are router events?', N'Intern', N'During each navigation, the Router emits navigation events through the Router.events property allowing you to track the lifecycle of the route. The sequence of router events is as below, 1. NavigationStart, 2. RouteConfigLoadStart, 3. RouteConfigLoadEnd, 4. RoutesRecognized, 5. GuardsCheckStart, 6. ChildActivationStart, 7. ActivationStart, 8. GuardsCheckEnd, 9. ResolveStart, 10. ResolveEnd, 11. ActivationEnd 12. ChildActivationEnd 13. NavigationEnd, 14. NavigationCancel, 15. NavigationError 16. Scroll', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'566487ae-4c87-4469-8533-74ace925c215', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the storage event and how can you use Web Storage for cross-tab communication?', N'Intern', N'The browser fires a storage event on the window object of all other tabs/windows at the same origin whenever localStorage is modified. The tab that made the change does not receive the event itself. This makes localStorage a lightweight broadcast channel for cross-tab state synchronisation without a server. The StorageEvent object provides: - key — the changed key (null on clear()) - oldValue — previous value (or null) - newValue — new value (or null on removeItem) - url — the origin URL that triggered the change - storageArea — reference to the affected storage object Example: Real-World Use Case: Banking and enterprise SaaS applications implement global logout using the storage event: when a user logs out in one tab, a flag is written to localStorage, all other open tabs detect the stora...', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'598a87fe-3c58-42be-ba00-74ae43acb9df', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the advantage of using a native executable in Quarkus?', N'Intern', N'Native executables do not require a separate JVM to run, as the necessary code is bundled directly into the executable. This results in nearly instantaneous startup times and significantly lower memory consumption compared to running on a standard JVM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6118581-e7be-41f8-8d4e-74af01732086', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the routes file in Rails?', N'Intern', N'The routes file, located in the config folder, acts as the map for your application. It matches incoming HTTP requests (like URLs and methods) to the specific controller actions that should handle them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75f3c792-5101-4016-b091-74afbcf69735', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When scaling a team, how do you account for the ''communication overhead'' in your project estimations?', N'Senior', N'I apply a productivity degradation factor to the total capacity, acknowledging that as teams grow, the number of communication channels increases quadratically. I mitigate this by structuring teams into small, autonomous pods that minimize cross-team dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eae5b00a-185c-445d-9511-74afd6e63210', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is the purging process (Tree Shaking) critical for Tailwind in production?', N'Senior', N'The full Tailwind CSS library contains thousands of utility classes that are rarely used in a single project. Purging scans the project files to remove unused CSS, transforming a massive development file into a lightweight production stylesheet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fefa2f1-607f-4c82-a993-74b00400d7fb', N'954a0331-deff-4399-b588-96f39fec001d', N'Why is it important to unsubscribe from Observables, and what are the architectural consequences of failing to do so?', N'Senior', N'Observables that are not unsubscribed create memory leaks because the subscription keeps the component instance in memory long after it is destroyed. This can lead to cumulative performance degradation and unexpected side effects when the application continues to execute logic for components that are no longer in the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'445c0eb3-f048-4fb4-a57c-74b02d9c75b5', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the difference between .hide() and .remove()?', N'Intern', N'The .hide() method changes the CSS display property to ''none'', making the element invisible while keeping it in the DOM. The .remove() method deletes the element and its descendants from the DOM entirely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'795ea564-96ac-4628-9c95-74b9b42ab039', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the significance of the ''prerendering'' feature in SvelteKit?', N'Middle', N'Prerendering generates static HTML files at build time for specific routes. This results in extremely fast load times and reduced server load, as the server serves static files instead of executing logic, though it is only suitable for content that does not change frequently per user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9f6d51f-49e8-4d72-87e1-74bed6fec6e8', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a Redis ''List''?', N'Intern', N'A Redis list is a collection of strings sorted by the order of insertion. You can add or remove elements from either the head or the tail of the list, making them useful for message queues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1492f8ba-d9d7-4dfa-ac60-74c12d69ddb4', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte ensure that DOM updates are efficient?', N'Fresher', N'Svelte knows exactly which parts of the application depend on which variables due to the analysis performed during compilation. This allows it to generate precise code that only touches the necessary DOM nodes when state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d0aadcd-1747-4f28-a7a7-74c23987b0ae', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Why does AdonisJS prefer a ''Controller-Service'' architecture?', N'Senior', N'This separation ensures that controllers only handle request orchestration while services contain the core business logic. This makes the business logic reusable across multiple entry points, such as CLI commands, cron jobs, and HTTP requests, enhancing the maintainability of the codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2bb7faa-6803-4fb1-a441-74c40d88366e', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the ''appConfig'' file in Nuxt?', N'Fresher', N'The appConfig file is used to expose configuration variables that can be updated at runtime. It is intended for values that might need to be changed without needing to rebuild the entire application, such as theme settings or public API endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'190a3f94-fe54-4dc7-b037-74c94eda3d58', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does the ASP.NET Core request pipeline handle middleware ordering, and why is it critical for performance and security?', N'Senior', N'Middleware components are executed in the order they are added to the pipeline, forming a nested structure. If a middleware fails to call the next delegate, the pipeline short-circuits, which is useful for authentication but can lead to silent failures if ordered incorrectly. Proper ordering is essential to ensure that cross-cutting concerns like logging and exception handling wrap the specific business logic correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b2d2c6e-79bb-4a25-a984-74ca1e171022', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'In a scenario where memory is severely limited, how would you approach data storage?', N'Fresher', N'I would prioritize using primitive data types over complex objects and avoid keeping unnecessary data in memory. I would also consider streaming data processing instead of loading entire datasets at once to minimize the memory footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6b67361-a879-4745-affb-74cbc2868fde', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the advantage of using ''url_for'' over hardcoding URLs?', N'Middle', N'Using ''url_for'' dynamically builds URLs based on function names and parameters defined in your routes. If you change a URL path in your route configuration, all links generated by ''url_for'' will automatically update. This prevents broken links and makes your application much easier to refactor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80242987-eec2-4ac2-b8a4-74cc4f8ba799', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the primary architectural advantage of using the Redux Toolkit (RTK) over vanilla Redux?', N'Senior', N'RTK reduces boilerplate by abstracting common patterns like action creators and reducer generation into a single slice object. It also enforces best practices, such as using Immer to handle immutability internally and including sensible defaults for middleware like Thunk, leading to more maintainable and concise code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f7c3074-623a-40d7-8bdd-74cd87d04e03', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does ''Two-Phase Commit'' (2PC) maintain atomicity across distributed nodes?', N'Senior', N'2PC uses a coordinator to ensure all participating nodes are prepared to commit before finalizing a transaction across multiple shards. It guarantees atomicity but is vulnerable to blocking if the coordinator fails during the protocol, creating a single point of failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f25cf303-cb03-4804-8507-74d53e5cf998', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the ''proxy'' feature in Vite configuration used for?', N'Junior', N'The proxy feature is used to redirect API requests from your development server to a different backend server. This helps bypass CORS issues during local development by making it appear as if the API requests are coming from the same origin.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'408ae3d9-a25f-4043-88f6-74d8a61bd74b', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the primary architectural pattern used by the underlying Actix framework?', N'Intern', N'Actix is based on the Actor model. In this model, independent units called actors encapsulate state and communicate exclusively through asynchronous message passing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bc6bf0d-46ab-4dcc-a87e-74d8fb27106c', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What role does documentation play in the engineering problem-solving process?', N'Intern', N'Documentation serves as a record of decisions, assumptions, and constraints, which is crucial for knowledge sharing and team alignment. It allows others to understand the ''why'' behind a solution, making it easier to maintain or improve later. Without it, valuable insights are lost, leading to redundant work or confusion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27a6e282-d370-42a7-b9e5-74dbad63da8c', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What does ''partitioning'' mean in Cassandra?', N'Intern', N'Partitioning is the process of distributing data across different nodes in a cluster. Cassandra uses a partition key to determine which node will store a specific piece of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b1b56c8-6e5f-4c53-be0b-74dcbce1f3be', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the impact of using Gin''s Abort() method?', N'Senior', N'Calling Abort() prevents subsequent handlers in the chain from executing, but it does not stop the current handler from finishing its execution. It simply sets an index in the context to prevent further iteration through the middleware stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'319766de-53cb-4838-8098-74dd750da044', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Explain the difference between ''Nested Loop'', ''Hash Join'', and ''Merge Join'' algorithms.', N'Senior', N'Nested loop is efficient for small datasets or when an index is available on the join key. Hash joins are ideal for large, unsorted datasets where a hash table can be built, while merge joins are most effective when both input datasets are already sorted by the join key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de1a0901-6d19-4e95-b875-74ddc5cc7409', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the purpose of ''Index Covering'' in query optimization?', N'Senior', N'Index covering occurs when all the columns required for a query are present within the index itself, allowing the database to satisfy the query without performing a lookup into the base table. This significantly improves performance by reducing random I/O operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b4c5a6e-c168-4e67-97be-74df81e664a7', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is JSON serialization in the context of APIs?', N'Intern', N'JSON serialization is the process of converting a .NET object into a JSON-formatted string that can be sent over the network. This is the standard format used by web APIs to communicate data between the server and the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73e329e8-7cf4-45dd-a984-74e21f43509e', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Can you use jQuery alongside other JavaScript libraries?', N'Intern', N'Yes, jQuery can coexist with other libraries. If there is a naming conflict with the dollar sign, jQuery provides a noConflict() method that releases the control of the dollar sign back to other libraries, allowing them to work together.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0667fd8f-400f-4ad8-bb5d-74e26a435003', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Describe the impact of the ''restrict'' keyword on the compiler''s ability to optimize pointer-heavy algorithms.', N'Senior', N'The restrict keyword acts as a promise to the compiler that the pointer is the sole means of accessing the underlying memory block. This eliminates the necessity for the compiler to generate multiple load instructions to account for potential pointer aliasing, facilitating better vectorization and loop pipelining.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'269325b3-c567-4c77-a9fd-74e4e621d864', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the difference between stack and heap allocation in Rust, and when is each used?', N'Middle', N'Stack allocation is used for values with a known, fixed size at compile time, providing fast access and automatic cleanup. Heap allocation is used for data with dynamic or unknown sizes at compile time, offering more flexibility but requiring manual or managed management of the memory lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'335dfd65-1104-4099-b0d7-74e56761bbbb', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How are Alpine.js directives different from standard HTML attributes?', N'Intern', N'Alpine.js directives are special attributes prefixed with x- that instruct the framework to perform specific behaviors. Standard HTML attributes are static and do not trigger any framework-level functionality on their own.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d7417ee-eccf-4c9a-96c6-74e711a877b6', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is non-standard evaluation (NSE) and how does it enable R''s domain-specific languages?', N'Senior', N'NSE allows functions to capture the expression of an argument rather than its value, enabling the creation of expressive interfaces like those found in tidyverse packages. While powerful for interactive analysis, it complicates programming by breaking standard evaluation rules and requiring explicit unquoting mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'066edf71-fc36-4340-9ec6-74ea82fbf905', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is event bubbling', N'Intern', N'Event bubbling is a type of event propagation in which an event first triggers on the innermost target element (the one the user interacted with), and then bubbles up through its ancestors in the DOM hierarchy — eventually reaching the outermost elements, like the document or window. By default, event listeners in JavaScript are triggered during the bubbling phase, unless specified otherwise. Here, at first, the event triggers on the child button. Thereafter it bubbles up and triggers the parent div''s event handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d59fb3c-0704-4e5c-a4de-74eb05db447d', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle static asset caching, and why is this important for production?', N'Senior', N'Vite adds content hashes to filenames for static assets, which allows for aggressive long-term browser caching. When the content of a file changes, the hash updates, forcing the browser to fetch the new version while old versions remain cached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5ce83d2-8232-4970-99d9-74ecab7357b7', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the primary difference between Micronaut and traditional frameworks like Spring regarding dependency injection?', N'Intern', N'Traditional frameworks typically use reflection and runtime proxies for dependency injection, which increases startup time and memory usage. Micronaut performs dependency injection at compile-time, resulting in faster startup speeds and a lower memory footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e318fb39-0bfc-44dc-82b2-74f0368546e3', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How do partition keys and sort keys influence data distribution and query performance in DynamoDB?', N'Middle', N'The partition key determines the physical storage location of an item through a hash function, ensuring data is spread across multiple partitions to scale horizontally. The sort key allows for efficient range queries and data grouping within a single partition. Choosing an effective composite primary key is critical to prevent ''hot partitions'' and ensure balanced throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09b741c9-ba82-44ff-bb86-74f054ffe648', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is meant by ''Opinionated Defaults'' in Spring Boot?', N'Intern', N'Opinionated defaults mean that Spring Boot makes sensible choices about the tools and configuration needed for a standard application. It assumes a certain way of working, which speeds up development by removing the need for manual setup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
