INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3666122a-3a1d-45cf-a4df-74f29a0dbd95', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the Echo framework and what is it primarily used for?', N'Fresher', N'Echo is a high-performance, minimalist web framework for the Go programming language. It is primarily used to build robust and scalable RESTful APIs and web applications by providing a lightweight structure for routing, middleware, and request handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37be746d-21ba-4b3e-b9c2-74f7f83a88a2', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust achieve memory safety without a garbage collector?', N'Middle', N'Rust uses an ownership system with a set of rules that the compiler checks at compile time. Memory is automatically deallocated when an object goes out of scope, a concept known as RAII, which eliminates the need for a runtime garbage collector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26066a6a-d737-46c2-87d5-74f806485c27', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel implement atomic database operations across multiple connections, and what are the limitations of the framework''s transaction management?', N'Senior', N'Laravel facilitates transactions via the database manager, but it cannot natively guarantee distributed atomicity (2PC) across multiple physical database servers. For cross-service consistency, one must implement patterns like the Saga pattern or Outbox pattern, as the framework''s transactions are scoped to single database connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1259fced-964b-4e59-8bc8-74f904232531', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of the ''application'' route?', N'Intern', N'The application route is the top-level route that remains active for the entire duration of the application. It is typically used for defining global UI elements like navigation bars or footers that are visible on every page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfbe338c-adb4-4614-99f8-74fb0cf9795e', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the concept of ''type inference'' and its limitations in complex generic functions.', N'Senior', N'Type inference allows the compiler to deduce types based on values and context, reducing the need for explicit annotations. However, in complex generic scenarios, the compiler may default to ''any'' or fail to resolve specific types, necessitating explicit generic arguments to provide the necessary type hints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6e10a7f-15d2-40a2-950b-750333c6a2de', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack ensure deterministic builds for long-term caching?', N'Senior', N'Deterministic builds are achieved by using consistent hashing (e.g., contenthash) and keeping module IDs stable. By using plugins like ''HashedModuleIdsPlugin'', Webpack ensures that file names only change when their actual content changes, maximizing browser cache hit rates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6673296a-6f1b-4f69-bdf7-7503bf4591c7', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What are the limitations of Gin''s default JSON rendering?', N'Senior', N'Gin uses the standard encoding/json package, which uses reflection and is slower than alternative libraries like easyjson or segmentio/encoding. For high-throughput services, replacing the default JSON encoder with a faster implementation can yield significant CPU savings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c4e0a2e-d545-4736-a6eb-7505c612e5bf', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is cache warming, and when should it be implemented?', N'Middle', N'Cache warming is the process of pre-populating a cache with anticipated data before the system receives actual user requests. It is typically used before planned high-traffic events to prevent the performance degradation associated with cold caches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'488506ea-edce-4df6-801e-750b8503fa94', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why might you avoid using Redux for high-frequency state updates like mouse positions?', N'Senior', N'Redux involves overhead from dispatching, middleware processing, and listener notifications, which can lead to performance bottlenecks if triggered too frequently. High-frequency updates are better handled via local state or refs, which bypass the store and provide the low-latency performance required for fluid UI interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74cf0099-918b-40e1-b008-750f37953a07', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is it often considered a best practice to avoid mixing jQuery with modern reactive frameworks like React or Vue?', N'Middle', N'Mixing them creates a conflict in how the DOM is managed. jQuery manipulates the DOM directly, while frameworks maintain a virtual DOM or a reactive state that expects full control over the UI, leading to unpredictable synchronization issues and memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0b71e91-d2a6-4529-8286-750f9d808dc6', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the difference between .bind(), .live(), .delegate(), and .on()?', N'Intern', N'.on() is the modern and preferred method for attaching event handlers in jQuery. Older methods like .bind(), .live(), and .delegate() have been deprecated or superseded because .on() provides a unified way to handle both direct and delegated events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2323793-f9ce-4cfc-9878-7513b2f0f76d', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What happens under the hood when a method is marked with @Async?', N'Senior', N'Spring creates a proxy for the bean and submits the method call to a TaskExecutor. This decouples the method execution from the calling thread, allowing the main process to continue immediately while the task runs in a separate thread pool.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7ff8bfb-3454-4a74-98a6-7516bd2531b0', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the ''Outlet'' component in Remix?', N'Intern', N'The Outlet component is a placeholder used in parent layout routes. It tells Remix where to render the child route''s content, enabling the nested routing structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5986baa4-576e-449f-97f0-7518b9386e7d', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does the WiredTiger storage engine handle concurrency?', N'Middle', N'WiredTiger utilizes document-level concurrency control, which allows multiple clients to modify different documents within the same collection simultaneously. This significantly improves performance compared to collection-level locking by reducing write contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b015f83-f5f9-463c-a787-751dc29aa212', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the purpose of the RubyGems system?', N'Intern', N'RubyGems is the standard package manager for Ruby. It provides a centralized repository for hosting gems and a command-line utility to install, update, and manage dependencies for Ruby applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ecceb8f-0488-4c1d-b9f3-751ea2c2970a', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How do you ensure type safety when using custom transport strategies in NestJS microservices?', N'Senior', N'Type safety is maintained by sharing DTOs or interface definitions between the client and the service via a shared library or monorepo structure. By using these common types in message patterns, the developer ensures that the payload structure is consistent across the network boundary, reducing runtime deserialization errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d318f31-c8b2-489c-a45b-7526ea355016', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach learning a new tool required for a project?', N'Intern', N'I start by identifying the core functionality of the tool and finding reputable official documentation or tutorials. I then create a small, isolated test case to practice using the tool''s features. Once I understand the basics, I apply it to the actual project while keeping the documentation handy for troubleshooting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b4ebf7d-5f94-4166-afcb-752c7df493c8', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the benefit of Go''s approach to compilation compared to interpreted languages?', N'Middle', N'As a statically compiled language, Go produces a single, self-contained binary containing all necessary runtime components. This simplifies deployment significantly by removing the need for external runtime environments or dependency installations on the host system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3d22132-580b-40e3-b9e7-752c9ea35a03', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is Dependency Injection and why is it used in Symfony?', N'Junior', N'Dependency Injection is a design pattern where an object receives its dependencies from an external source rather than creating them itself. In Symfony, this promotes loose coupling, making services easier to swap out or mock during unit testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37e6b001-e5fa-42f5-8171-752cb475fadf', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you handle horizontal scalability in a Flask application, given that the framework is inherently synchronous and WSGI-based?', N'Senior', N'Since Flask is synchronous, horizontal scaling is achieved by deploying multiple instances behind a load balancer using a production-grade WSGI server like Gunicorn or uWSGI with multiple worker processes or threads. To handle stateful operations, you must externalize session management to a distributed store like Redis to ensure consistency across nodes. For long-running or I/O-bound tasks, you must offload work to a distributed task queue like Celery to prevent blocking the worker threads and degrading response latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30f0e9f4-55da-402d-8386-752d1acf12c7', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the primary architectural pattern used by Actix?', N'Fresher', N'Actix is based on the Actor model. In this pattern, every component is an actor that processes messages in isolation, communicating with others only through asynchronous messaging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ba1fb0d-81ac-43e0-84ff-75326b772b52', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What impact do long-running transactions have on database performance?', N'Middle', N'Long-running transactions hold locks on database rows for extended periods, causing contention and blocking other concurrent operations. This leads to increased latency, decreased throughput, and potential system-wide performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fb4fa4b-2fe8-47d7-ba5c-75363943fc05', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Can Hono run on Node.js, and how does it achieve this?', N'Junior', N'Yes, Hono runs on Node.js using an adapter that translates the standard Web Fetch API requests into Node-style request and response objects. This allows developers to use the same Hono code in both edge environments and traditional server environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96f46a8a-ea9d-4416-8363-75371a51047a', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are the limitations of Hono''s ''zero-dependency'' philosophy for complex enterprise projects?', N'Senior', N'The primary limitation is that common features, such as advanced database ORM integrations or complex file uploads, may require additional boilerplate code compared to ''batteries-included'' frameworks. Developers must take responsibility for selecting and integrating third-party libraries for these specialized functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0afe1d26-8db1-4818-a130-753d1560ab4c', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When asked to provide a rough estimate for a large-scale project, what is your process for managing expectations?', N'Middle', N'I provide an ''order of magnitude'' estimate and explicitly state the assumptions and the level of uncertainty involved. I emphasize that as we progress through the initial phases, the estimate will be refined, and I commit only to providing regular updates rather than a fixed deadline this early in the process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'237727ca-b128-45cf-9212-753d5220ff0c', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are ''generic'' types?', N'Fresher', N'Generics allow you to write code that works with multiple types instead of being restricted to one. This reduces code duplication by allowing you to define functions or structs that are flexible regarding the data types they handle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb03e42c-2d29-4e75-acbc-753dfd5d8061', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the role of Pydantic in a FastAPI application?', N'Fresher', N'Pydantic is used for data validation and settings management. In FastAPI, it defines the data schemas for incoming request bodies, automatically validating the types and structure of the data before it reaches the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b7693e0-3710-4e3b-a713-753ff9a5170b', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does the import system in Python handle circular dependencies?', N'Senior', N'Python uses a module cache (sys.modules) to track imports; when a module is imported, it is added to the cache before its body is executed. If a circular import occurs, the importing module sees the partial module object, which can lead to runtime errors if names are accessed before their definitions are processed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd762379-e914-4b35-8127-754090f4fda8', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does a NoSQL database differ from a Relational Database (RDBMS)?', N'Fresher', N'Relational databases use tables with fixed schemas and enforce strict relationships between data, while NoSQL databases use flexible schemas and store data in formats like documents or graphs. NoSQL is generally better suited for rapidly changing data requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'022b8bf2-2f5d-4d2c-b279-7541bb5cee8e', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What are the risks of having ''too many'' alerts in a monitoring system?', N'Middle', N'Excessive alerting leads to ''alert fatigue,'' where operators become desensitized to notifications and may start ignoring them. This increases the risk that genuine, critical incidents are overlooked or delayed in response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae333a0c-2f65-47ad-a0f2-7543ce72c124', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is Atomicity in the context of ACID?', N'Intern', N'Atomicity ensures that a transaction is treated as a single ''all or nothing'' unit. If any part of the transaction fails, the entire transaction is aborted and the database is left unchanged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b913600-7782-4fcb-87a3-75462273f10f', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are the limitations of Svelte''s compile-time reactivity?', N'Senior', N'The primary limitation is that Svelte requires the compiler to see the source code to perform its magic. This can make it challenging to use highly dynamic, runtime-generated UI structures or complex functional patterns that rely heavily on reflection or dynamic variable creation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd418c44b-b2ed-48c8-b670-754c64fd919a', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain the role of ''C Extensions'' in Ruby''s architecture and their impact on portability.', N'Senior', N'C extensions allow Ruby to leverage existing C libraries and gain performance for low-level tasks, but they bypass the Ruby VM''s safety features and memory management. This introduces risks of segmentation faults and complicates cross-platform compatibility, as the extension must be compiled for every target architecture and Ruby version.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51811e98-7d2b-4dcb-91b9-7552c707ba5a', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How do you manage error handling across different handlers in Axum?', N'Middle', N'Error handling is typically managed by returning a custom error type that implements ''IntoResponse''. This allows developers to map internal domain errors to specific HTTP status codes and response bodies in a centralized, consistent manner.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2494165-d97f-4769-95a4-75534a323b69', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How can deadlock detection and prevention be handled in database systems?', N'Senior', N'Deadlock prevention often involves imposing an ordering on lock acquisition to avoid cyclic dependencies. Deadlock detection involves maintaining a wait-for graph and periodically searching for cycles, at which point the system must kill one of the transactions to break the cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a6155eb-b2c3-40fa-9b64-75567e82bf07', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Describe the trade-offs of using Fastify''s ''encapsulation'' feature in a large-scale microservices architecture.', N'Senior', N'Encapsulation allows for clean separation of concerns and prevents configuration leakage, which is essential for maintaining large codebases. However, it can introduce complexity when shared resources or global decorators need to be accessed across deep plugin boundaries, requiring careful dependency injection design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e818d7ed-6e07-4a12-9536-755897962202', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you install plugins in an existing Vue CLI project?', N'Fresher', N'You can install a plugin into an already created project with the vue add command. You can also add options for plugin If a plugin is already installed, you can skip the installation and only invoke its generator with the vue invoke command.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b225e7f-dee7-4c1d-943c-755bf6e48420', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the difference between a global middleware and a route-specific middleware?', N'Fresher', N'A global middleware is defined using app.use() and runs for every incoming request. A route-specific middleware is passed as an argument directly into a specific route definition and only runs when that route is matched.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'285862c9-e7b4-428f-9512-75615a28fbe1', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a primary key and what are its main requirements?', N'Intern', N'A primary key is a specific column or set of columns that uniquely identifies each record in a database table. To be valid, a primary key must contain unique values and cannot contain null values. Each table can have only one primary key to ensure clear identification of rows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'537b9063-4583-492f-81f8-7562082e7b60', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Does Rust use a garbage collector?', N'Intern', N'No, Rust does not use a garbage collector. Instead, it uses a system of ownership and borrowing to manage memory, which allows for predictable performance and low memory overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f24c636a-21ad-4c09-8906-75646453f52b', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact''s event bubbling implementation affect complex component compositions?', N'Senior', N'Because Preact uses a synthetic event system that delegates to the root, it ensures consistent behavior regardless of the nesting depth of components. This abstraction simplifies event propagation logic, preventing issues where native events might behave inconsistently due to shadow DOM boundaries or complex z-index layering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'704abfce-1185-4755-92f2-75657a19aa0e', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the advantage of using Hono''s built-in ''Logger'' middleware?', N'Fresher', N'The logger middleware automatically prints details about incoming requests, such as the method, path, and duration, to the console. This is essential for debugging and monitoring the traffic flow through the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec518c98-bc56-45e5-af44-75659b14f91b', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the concept of ''lazy loading'' in R packages.', N'Middle', N'Lazy loading allows packages to load their data and functions only when they are first accessed rather than at the moment the package is attached. This significantly reduces startup time and lowers the memory footprint of R sessions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
