INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3a8e157-2870-43c4-b69e-75685e362eb3', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is Elasticsearch?', N'Intern', N'Elasticsearch is a distributed, open-source search and analytics engine built on top of Apache Lucene. It is designed for horizontal scalability, reliability, and real-time search capabilities across large volumes of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'725b3698-413e-4eb4-9db0-756a767b08cc', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is a leader-follower database replication model?', N'Middle', N'In this model, one node is designated as the leader to handle all writes, while one or more follower nodes replicate the data for read operations. This architecture improves read performance and redundancy but introduces a potential single point of failure if the leader goes down.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9227cf9-b8ff-4815-954a-756b3850b5f8', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between ''never'' and ''void''?', N'Intern', N'Void indicates that a function does not return any meaningful value, often implying it returns undefined. Never indicates that a function will never reach its end, such as a function that always throws an error or runs an infinite loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bb2a885-a3a8-47dc-979d-756c957c3db1', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript''s ''strict'' mode affect the compiler''s behavior?', N'Middle', N'The ''strict'' mode enables a wide range of type-checking behaviors that result in stronger guarantees of program correctness. It includes settings like strict null checks, strict property initialization, and consistent ''this'' checking, significantly reducing the likelihood of common runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63363cc0-f41a-4923-9296-756d7a0b582a', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the benefit of using the Template pattern (e.g., RestTemplate) in Spring?', N'Middle', N'Template classes abstract away the repetitive, low-level technical code involved in performing operations like HTTP requests or database queries. By hiding the ceremony of handling connections and resource cleanup, they allow developers to focus on the business logic of the operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fde4cc34-bf28-415a-b1f5-756d7fd3cbd9', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the ''useActionData'' hook used for?', N'Intern', N'The useActionData hook allows a component to receive the result of an action function. It is commonly used to show success messages or validation errors after a user submits a form.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac0c14fe-0026-4bca-9b53-756e248a7305', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the difference between a handler and middleware in Echo?', N'Fresher', N'A handler is the terminal function that processes the business logic of a specific route and returns a response. Middleware, conversely, acts as a wrapper that performs tasks like authentication or logging before or after the handler runs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70eab77f-3dba-491a-a134-756e47e15c38', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is the Tailwind bundle size generally smaller than Bootstrap''s?', N'Fresher', N'Bootstrap includes all of its CSS components in the bundle regardless of whether you use them. Tailwind, through its purging process, only includes the styles you actually used in your project, resulting in a much smaller footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b64f6705-f44d-4206-8c8a-756e7997fa53', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the primary purpose of HTML?', N'Intern', N'HTML stands for HyperText Markup Language and serves as the standard markup language for creating the structure and content of web pages. It uses tags to define elements like headings, paragraphs, links, and images, which the browser then interprets to display the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5477b90f-8b89-4fb5-8551-756f17df724c', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Compare the architectural benefits of using Nuxt modules versus custom plugins.', N'Senior', N'Nuxt modules operate at the build-time hook level, allowing them to modify the application''s configuration, inject templates, or extend the build process itself. Plugins, conversely, operate at runtime within the Vue lifecycle, making them better suited for injecting global instances or services that depend on the active application instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b882aa9-6774-4cb1-8873-7571066524a3', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the purpose of the JOIN clause?', N'Intern', N'The JOIN clause is used to combine rows from two or more tables based on a related column between them. It allows users to retrieve data that is spread across different tables in a single result set.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61bbfe93-ef79-46de-9dea-7571de04a72e', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Explain the concept of ''Read-only replicas'' in a distributed Redis setup.', N'Senior', N'Read-only replicas scale read traffic by serving requests independently of the master, which handles all write operations. This architecture improves throughput for read-heavy workloads but requires the application to handle the eventual consistency model of the replication link.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f54a5509-70b2-471a-8a30-757261caf28a', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the ''defer'' keyword impact function execution flow at the machine level?', N'Senior', N'Defer pushes a function call onto a stack-like list managed by the runtime for the current function frame. When the surrounding function returns, the runtime executes these deferred calls in LIFO order, which introduces a small performance overhead compared to direct execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60b1d44f-9e6f-4b58-ba77-75769827c13d', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How do Interceptors in NestJS differ from Middleware, and when would you choose one over the other?', N'Senior', N'Middleware executes before the route handler and has access to the raw request and response objects, making it ideal for logging or authentication. Interceptors wrap the route handler execution, allowing for logic both before and after the method call, making them better for response transformation, caching, or exception mapping.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e7e3dfe-5589-4350-b9be-75782bc03073', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are declaration files (.d.ts)?', N'Intern', N'Declaration files are used to describe the types of existing JavaScript code that does not have TypeScript source files. They provide type information so that TypeScript can understand and check the usage of third-party JavaScript libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e578e6c-e84f-40e1-b70f-757e6a535699', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why are global secondary indexes often discouraged in highly distributed NoSQL architectures?', N'Senior', N'Global secondary indexes require cross-shard coordination to maintain consistency during writes, which introduces significant latency and limits scalability. They turn a localized write operation into a distributed transaction, creating a single point of contention that violates the performance design goals of most NoSQL databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'591ee98e-6745-4e7f-81f0-757e9108b246', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What happens if a route handler does not return a value or send a response?', N'Junior', N'If a handler fails to send a response or return a value, the request will hang, eventually resulting in a timeout. Fastify expects either a return value that can be serialized or an explicit call to the reply methods to terminate the request-response cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c644c9d5-07ad-4e61-a6e9-757ecb7d78bf', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the role of the Gemfile in a Rails application?', N'Junior', N'The Gemfile is a configuration file used by the Bundler tool to define all the external libraries, or gems, that your application depends on. It specifies which versions of these gems are required to ensure the environment remains consistent across development and production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d27c38c-dd2a-444d-a15f-757efe32c0a4', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do Conditional Types work in TypeScript?', N'Middle', N'Conditional types act like ternary operators for types, allowing the selection of one of two possible types based on a condition. They are fundamental in creating flexible, reusable utility types that can transform inputs based on their structure or constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0df78d8f-d275-413c-b6c2-757fb31d4617', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt handle CSS and styling?', N'Middle', N'Nuxt supports PostCSS, Sass, and Less out of the box and allows global CSS files to be defined in the configuration. It automatically injects required CSS for components, ensuring that only the styles needed for the currently rendered components are loaded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a94ef873-0718-4234-9a36-7582cb4944ae', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is a module bundler and why do we need one?', N'Fresher', N'A module bundler is a tool that takes multiple separate files and dependencies and combines them into a single file. We need one because browsers historically struggled to manage many small files efficiently, and bundling improves performance and organization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f28f3bd6-a2bb-4e58-bcf2-75865e2efaeb', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does MySQL''s Adaptive Hash Index (AHI) work, and under what conditions might it become a bottleneck?', N'Senior', N'AHI automatically creates hash indexes in memory for frequently accessed B-tree pages to speed up lookups. It can become a bottleneck under high-concurrency workloads due to lock contention on the hash index structure, necessitating its disabling in certain read-heavy scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d53fffd-36c3-403c-89e6-75867c81db73', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the difference between a TemplateRef and a ViewContainerRef?', N'Middle', N'TemplateRef represents an embedded template that is not rendered by default, acting as a blueprint. ViewContainerRef acts as a placeholder where one or more views can be attached or dynamically instantiated within the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c29824b-55c0-4f09-967a-7586c379820f', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How can you use x-transition in Alpine.js?', N'Junior', N'The x-transition directive provides an easy way to apply CSS transitions to elements when they are shown or hidden. It automatically adds and removes CSS classes at the appropriate stages of an element''s entry or exit from the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9f103f1-acfc-4695-b2cf-75892c7b6411', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What are the trade-offs of using Alpine.js for a very large, data-heavy application?', N'Middle', N'While Alpine.js is excellent for interactivity, it lacks robust tools for managing complex global state, routing, and large-scale data handling found in frameworks like React. As an application grows, the lack of a component-based build system can lead to disorganized code and maintenance challenges.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80580f15-0157-4c5f-9a51-758973a41417', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the purpose of the ''maxmemory-policy'' configuration in Redis?', N'Middle', N'The maxmemory-policy determines how Redis evicts keys when the memory limit is reached. Options like LRU (Least Recently Used) or LFU (Least Frequently Used) help manage memory by removing less important data to make space for new writes, ensuring the cache remains effective.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd06060c4-c1e9-461e-91f0-7589886ecff5', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does the PostgreSQL planner decide between a Nested Loop, Hash Join, and Merge Join?', N'Senior', N'The planner estimates costs based on row counts, index availability, and data distribution statistics. Nested loops are preferred for small datasets with indexes, Hash Joins are optimal for large, unsorted datasets, and Merge Joins are chosen when both inputs are pre-sorted or indexed on the join key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'837e2824-6ab7-45e5-a8b5-7589a2aa7cde', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the <Router> components of React Router v6?', N'Intern', N'React Router v6 provides below 4 components: 1. :Uses the HTML5 history API for standard web apps. 2. :Uses hash-based routing for static servers. 3. :Uses in-memory routing for testing and non-browser environments. 4. :Provides static routing for server-side rendering (SSR). The above components will create _browser_, _hash_, _memory_ and _static_ history instances. React Router v6 makes the properties and methods of the history instance associated with your router available through the context in the router object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10069611-b1d8-4b7f-9d8b-758f37846f01', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the purpose of the @nestjs/swagger ApiProperty(), ApiOperation() decorators?', N'Fresher', N'The @nestjs/swagger package provides several decorators to help with creating Swagger documentation for your API. Two of these decorators are @ApiProperty() and @ApiOperation(). @ApiProperty(): This decorator is used within DTO (Data Transfer Object) classes to provide metadata for properties. This metadata is used to generate the Swagger documentation for the model that the API expects in the request body or returns in the response. The @ApiProperty is used to indicate that id and name are properties of the CreateUserDto @ApiOperation(): This decorator is used within controller methods to provide metadata for operations (API endpoints). This metadata is used to generate the Swagger documentation for the operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ad020ff-1ee6-4e76-9fb2-75911c499007', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the ''Hono RPC'' feature?', N'Intern', N'Hono RPC allows for end-to-end type safety between the client and the server. By sharing the type definitions of the API, developers can ensure that the client knows exactly what data the server expects and returns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'707af42f-d765-4f4e-a1c3-759123421346', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Describe the mechanics of ClassLoader delegation and how it impacts isolation in modular systems.', N'Senior', N'The delegation model ensures that a class loader first delegates the search for a class to its parent before attempting to load it, maintaining a hierarchical structure that prevents duplicate class definitions. This architecture enables modularity and isolation, allowing different parts of an application or container to use conflicting versions of the same library without runtime collisions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2eaedca1-0c24-41e2-8b46-75964278b84d', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the primary goal of Rust''s ownership model?', N'Fresher', N'The primary goal is to ensure memory safety without needing a garbage collector. It does this by enforcing strict rules at compile time regarding how memory is accessed and managed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dca4ecd-ba6c-4e8d-ae01-7596b5202f46', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the purpose of the @InjectRepository() decorator in NestJS.', N'Fresher', N'The @InjectRepository() decorator in NestJS is used to inject a repository instance into a service or controller. It is commonly used with TypeORM for database interaction, allowing the injection of repositories for specific entities. A repository in TypeORM is a way to manage entities: it provides methods to insert, update, remove, and load entities. By injecting a repository, you can use these methods in your service or controller. Here is an example: In the above example @InjectRepository(User) is used to inject a repository for the User entity. This repository is then used in the findAll method to load all users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea3220bd-198e-4564-9ec4-759883a61d92', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify address the ''thundering herd'' problem during request validation?', N'Senior', N'Fastify validates requests before the user function is executed, ensuring that malformed requests are rejected at the edge of the application logic. This prevents expensive business logic from running on invalid payloads, protecting internal resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1aa84a96-5ed3-4ba1-934c-7598f43af58e', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the role of the ''Global'' scope in NestJS modules.', N'Middle', N'A global module makes its exported providers available throughout the entire application without needing to import the module into every child module. While convenient, it should be used sparingly to avoid making dependencies implicit and harder to track.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7051278c-8ce1-463e-9a2a-759a2e7a2e16', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle Hot Module Replacement (HMR) during development?', N'Middle', N'Vite performs HMR over native ESM. When a file is edited, Vite accurately invalidates the chain between the changed module and its closest HMR boundary, ensuring only the affected module is reloaded without refreshing the entire page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ca32e8f-f4cc-41c8-af65-759c9bb79be8', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the role of the ''App'' instance configuration in Fiber performance?', N'Middle', N'Fiber provides granular control over settings like idle timeouts, read/write buffers, and maximum request body sizes. Tuning these parameters is vital for optimizing resource utilization based on the specific traffic patterns and hardware constraints of the production environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dda4b339-c342-430b-9264-759cca76162d', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are validations in ActiveRecord models?', N'Fresher', N'Validations ensure that only valid data is saved into your database. They allow you to define rules, such as presence, uniqueness, or format constraints, which are checked before an object is saved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'def6826d-d375-4e97-8d0c-75a019339427', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis Cluster achieve data sharding, and what are the implications for multi-key operations?', N'Senior', N'Redis Cluster uses hash slots to partition data across nodes, mapping keys to specific slots using a CRC16 algorithm. Multi-key operations are only permitted if all keys hash to the same slot, which necessitates careful key design using hash tags to ensure related data resides on the same shard.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'481c4f56-cc95-4697-8806-75a099ad88b0', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between ''work_mem'' and ''maintenance_work_mem''?', N'Senior', N'work_mem is the memory allocated for internal sort operations and hash tables per operation within a query, while maintenance_work_mem is reserved for maintenance tasks like VACUUM, CREATE INDEX, and ALTER TABLE. High settings for work_mem can lead to out-of-memory errors if many complex queries run concurrently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ade3823-45f6-41f5-96c3-75a1cb9bd466', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach a problem that seems too large to solve in one sitting?', N'Fresher', N'I break the large problem into smaller, manageable sub-tasks. By tackling one component at a time, I can track progress more effectively and gain a better understanding of the overall system as I build it up.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'becab8c5-e46b-45fa-9532-75a360dd581a', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the difference between procs and lambdas in Ruby regarding argument handling and control flow?', N'Middle', N'Lambdas are strict about argument counts and will raise an error if called with the wrong number of arguments, whereas procs will return nil for missing arguments. Additionally, a return statement inside a lambda exits only the lambda, while a return inside a proc exits the surrounding scope in which the proc was defined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b45b6bd9-ecd9-44f6-9747-75a3f02278d9', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does partition rebalancing impact availability in a distributed queue?', N'Senior', N'Rebalancing involves redistributing partition ownership among available consumers, which often results in a temporary ''stop-the-world'' event where processing pauses. Frequent rebalancing can lead to significant latency spikes, necessitating strategies like sticky partitioning or incremental rebalancing to minimize the impact on throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab5797f7-de9d-4296-88f7-75a5133f9ff3', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you distinguish between a network issue and an application logic issue?', N'Fresher', N'You can test connectivity to the server or database using basic diagnostic tools; if the connection fails, it is likely a network issue. If the connection is successful but the data returned is incorrect or causes an error, it is likely an application logic issue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6275c511-dcc7-4f64-8b40-75a66a8fc3ce', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Discuss the nuances of the C integer promotion rules and their impact on expression evaluation.', N'Senior', N'Integer promotion automatically converts smaller integer types to int or unsigned int before arithmetic operations occur. While this ensures consistent behavior across architectures, it can lead to subtle bugs when performing bitwise operations on signed types, as sign extension may occur unexpectedly during promotion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'646f716f-c130-4100-ab99-75a70d983048', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is replication in Cassandra?', N'Intern', N'Replication is the process of storing copies of the same data on multiple nodes across the cluster. This ensures that if a node goes down, the data remains available from other nodes that hold the replicas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdbcd5af-9f4a-4888-9a22-75aea844a669', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the architectural role of a ''Portal'' in React?', N'Senior', N'Portals provide a way to render children into a DOM node that exists outside the current component''s parent hierarchy. This is essential for UI elements like modals, tooltips, or popovers that need to break out of overflow-hidden containers or maintain a specific z-index context while remaining logically part of the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72687696-393a-4d27-bd03-75b42a79c67e', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Why is idempotency important in API design?', N'Middle', N'Idempotency ensures that performing the same operation multiple times has the same effect as performing it once. This is critical for distributed systems to handle network failures gracefully, as it allows a client to safely retry a request without worrying about duplicate side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd4eccc3-2725-47ed-95b5-75ba46b5498d', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is recursion?', N'Intern', N'Recursion is a programming technique in which a function calls itself to solve a problem. The idea is to break down a complex problem into smaller, simpler problems and solve them in a recursive manner until the base case is reached. The base case is a condition that stops the recursion and returns a value. A common example of a recursive function is the factorial function, which calculates the product of all positive integers up to a given number. Here''s an example of a recursive factorial function in Python: 24', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b32c233-1716-469a-93d8-75bf138499ce', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Explain the concept of ''Zero Allocation'' as it relates to Fiber''s performance.', N'Middle', N'Zero allocation refers to the design goal of reusing buffers and objects instead of constantly allocating new memory on the heap. By minimizing allocations, Fiber reduces the frequency and duration of garbage collection cycles, which directly translates to lower latency and higher throughput under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6820eb0-6347-4b48-b7e0-75bf4a11ac2b', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why would you choose Redis over a disk-based cache like Memcached?', N'Junior', N'Redis offers more complex data structures, built-in persistence, and high-availability features like replication and clustering. Memcached is strictly a simple key-value store, whereas Redis is more versatile for modern application requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29421e87-0972-468d-b1e2-75c0779e6de3', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is ''Eventual Consistency'' and in which scenarios is it acceptable?', N'Middle', N'Eventual consistency means that while all replicas will eventually reflect the latest data, they may not do so immediately. It is acceptable in systems where high availability and low latency are prioritized over absolute correctness, such as social media feeds, likes counters, or product recommendations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ee2deb6-7478-4ae1-a3ac-75c72ae9ffd4', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the benefit of using the Messenger component over synchronous processing?', N'Middle', N'The Messenger component allows you to dispatch tasks to a queue, enabling asynchronous execution of time-consuming operations like sending emails or processing images. This improves the user experience by allowing the HTTP response to be returned immediately while the background task completes independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f8f38ec-8129-42e7-b2a2-75c91f8729dc', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is bundle size important in Qwik?', N'Intern', N'Smaller bundle sizes lead to faster download and parse times. By splitting code into tiny, granular pieces, Qwik ensures the browser only works on what is strictly necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3e29356-4e14-4322-97cf-75c9ae1fa96f', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the concept of Type Inference in Scala.', N'Fresher', N'Type inference allows the Scala compiler to automatically deduce the data type of an expression or variable based on its initialization. This reduces the need for explicit type declarations, making the code more concise while maintaining type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b22a31e1-77a5-40fd-a6a9-75cb169b2243', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When faced with two competing architectural solutions, what framework do you use to choose one?', N'Middle', N'I evaluate both options based on performance requirements, team familiarity, operational overhead, and long-term scalability. I document these findings in a design document to solicit feedback, ensuring the final choice is objective and aligned with our current and future engineering constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10e34e4b-4630-4acb-9bdc-75cbce96d26c', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the difference between ''val'' and ''var'' in Scala?', N'Intern', N'A ''val'' defines an immutable variable, meaning its reference cannot be changed once assigned. A ''var'' defines a mutable variable, allowing its value to be reassigned later in the program execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df532453-1873-40a4-b69f-75ccfa96ecb2', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is ''error.js'' in Next.js?', N'Intern', N'The error file is used to handle runtime errors in your application gracefully. By creating this file, you can display a custom error UI to the user instead of letting the application crash or show a blank screen.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f3df8bd-a670-43ed-9413-75cd535ef4e4', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How would you troubleshoot a scenario where a database becomes unresponsive during a specific daily batch job?', N'Senior', N'I would analyze the execution plans of the queries involved to determine if the batch job is causing table-level locking or excessive index fragmentation. I would also monitor the database''s resource utilization during that window to check for CPU saturation or memory pressure caused by large result set sorting or temporary table creation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86f86bde-32ec-44ca-9c68-75d8029c8a9d', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the significance of null safety in Kotlin?', N'Fresher', N'Null safety is a core feature that aims to eliminate the danger of null references, which is a common source of crashes in languages like Java. By distinguishing between nullable and non-nullable types at compile time, Kotlin forces developers to handle potential null values explicitly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ba88261-0e0b-4804-a4fa-75dab588c469', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the role of Cargo in the Rust ecosystem?', N'Intern', N'Cargo is Rust''s official build system and package manager. It handles tasks such as downloading library dependencies, compiling packages, and running tests, simplifying the development workflow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4708be25-18e4-40c3-991e-75e6d9abba21', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you capture browser back button', N'Fresher', N'The beforeunload event is triggered when the window, the document and its resources are about to be unloaded. This event is helpful to warn users about losing the current data and detect back button event. You can also use popstate event to detect the browser back button. Note: The history entry has been activated using history.pushState method. In the preceeding code, When the box element clicked, its background color appears in blue color and changed to while color upon clicking the browser back button using popstate event handler. The state property of popstate contains the copy of history entry''s state object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9b8debd-4fb0-4d12-b473-75e75f0c81aa', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the function of a shard in Elasticsearch?', N'Intern', N'A shard is a single instance of a Lucene index that acts as a container for a portion of the data. Sharding allows Elasticsearch to distribute data across multiple nodes to improve performance and storage capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f95b5325-1da4-44a4-aae0-75e9011b195f', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is Micronaut''s approach to configuration?', N'Fresher', N'Micronaut uses a hierarchical configuration system, typically utilizing YAML, JSON, or properties files. It allows for environment-specific configurations and supports binding configuration values directly into classes using annotations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2ec8447-1c25-4ac1-b5b2-75ef174590b0', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'When would you choose to use the Memory storage engine over InnoDB?', N'Senior', N'The Memory engine is appropriate only for transient data like ephemeral session caches or temporary look-up tables where extreme speed is required. It is rarely used in production due to lack of crash recovery, table-level locking, and fixed-length row requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'907db497-eae6-4e65-92d3-75f63ff60bd1', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the role of the ''QRL'' in Qwik?', N'Fresher', N'A QRL, or Qwik Resource Locator, is a specific URL format used by the framework to identify which code chunk needs to be loaded for a specific action. It acts as a pointer to the lazy-loaded code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a64d228-39c8-499d-9577-75f7b30d826a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the benefits of using arrow function over es5 function?', N'Intern', N'Arrows is a new syntax for functions, which brings several benefits: * Arrow syntax automatically binds this to the surrounding code''s context * The syntax allows an implicit return when there is no body block, resulting in shorter and simpler code in some cases * Last but not least, => is shorter and simpler than function, although stylistic issues are often subjective Example 01: Arrow Function with No Argument If a function doesn''t take any argument, then you should use empty parentheses. Example 02: Arrow Function with One Argument If a function has only one argument, you can omit the parentheses. Example 03: Arrow Function as an Expression You can also dynamically create a function and use it as an expression.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d8b8600-5818-4e56-8d34-75fd1632e234', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the difference between client components and server components?', N'Intern', N'Server components run only on the server and do not support browser-specific features like state or effects. Client components are rendered on the client, allowing for interactivity, event handling, and access to browser APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68fc6699-a80c-497a-b80d-760145e04fa8', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery''s method queueing work for animations?', N'Middle', N'jQuery maintains an internal queue for animations on each element, ensuring that effects occur sequentially. This prevents overlapping animations from conflicting, but it can make complex, non-linear animation sequences difficult to manage compared to CSS-based keyframes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'748d9569-18b9-4b30-a42c-7601a45bcb03', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is TypeScript and how does it relate to JavaScript?', N'Intern', N'TypeScript is a strongly typed superset of JavaScript that adds static type definitions to the language. It compiles into plain JavaScript, allowing it to run in any environment that supports JavaScript while providing enhanced tooling and error checking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37a9ea22-95fb-4e0d-8798-7605b774b19f', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar ensure type safety across the application?', N'Middle', N'Litestar relies heavily on Python type hints, which are used for request validation, dependency injection, and schema generation. By enforcing strict typing, the framework catches potential errors early and improves the developer experience through IDE autocompletion and static analysis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd02bc6bf-e55c-4a86-b74a-760a361f547f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a generic constraint and why is it useful?', N'Middle', N'Generic constraints restrict the types that can be passed to a generic parameter using the ''extends'' keyword. This ensures that the generic type has certain members or properties, allowing you to access those members safely within the function body while maintaining type flexibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ae3dc77-1a5a-48c3-a2fc-760e8d107ccb', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why does Preact favor functional components and hooks over class-based components in modern architectures?', N'Senior', N'Functional components allow for better tree-shaking and smaller bundle sizes because they eliminate the need for class boilerplate and inheritance. Furthermore, hooks provide a cleaner composition model that aligns with Preact''s goal of keeping the runtime as minimal as possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
