INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe72eb04-5f42-48f5-b133-761305eac032', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How do you add a static asset like an image in Vite?', N'Fresher', N'You can import static assets directly into your JavaScript files or reference them in your HTML. Vite will automatically process these files, add hashes for versioning, and handle the path resolution during the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e426e7e-4e2d-4ab6-8fb7-76152ae55ce1', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the role of the Rust compiler, rustc?', N'Intern', N'The rustc compiler is responsible for translating Rust source code into machine code. During this process, it performs extensive checks to ensure memory safety, type correctness, and adherence to ownership rules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c57a159e-a994-4b72-bc8b-7617dfc2e446', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Explain the role of ''Mounting'' in Chi and when it should be used.', N'Middle', N'Mounting allows you to compose multiple independent routers into a single application tree. It is best used for modularizing large applications, where specific sub-domains or API versions are handled by separate router instances, keeping the codebase organized and maintainable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28367caf-f5ed-4060-b1ff-76195a5fed08', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the purpose of the @forward rule in modular architecture?', N'Middle', N'@forward allows you to bundle several files together and expose their members through a single entry point. It is essential for creating library-like structures where you want to export specific parts of a module to other files while keeping internal helpers private.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddf8f1b8-aa82-400f-9d9f-761a28629513', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle request body parsing, and what are the implications for memory usage with large payloads?', N'Senior', N'Gin uses reflection-based binding to map request bodies to structs, which is convenient but can be CPU-intensive for very large payloads. Since the body is often buffered into memory for parsing, processing massive request bodies can lead to memory exhaustion unless limits are explicitly set or streaming approaches are used for file uploads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ddf7341-964c-4d6a-9b0a-761c453d5d48', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the difference between a find and an aggregation in MongoDB?', N'Junior', N'A find operation is used to retrieve documents that match specific criteria. An aggregation is a more powerful framework that allows for processing, transforming, and calculating results from documents, such as grouping or counting data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4af9e94c-d241-45f2-ad88-761d69b94ed2', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What are path parameters?', N'Fresher', N'Path parameters are dynamic segments within a URL path. Litestar allows you to define these using curly braces in the route string, and they are automatically parsed and passed as arguments to the handler function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'244c2814-18dd-4fec-bac5-76276888f533', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Compare the use cases for Redis as a database versus Redis as a cache.', N'Middle', N'As a cache, Redis is used to store temporary, transient data that can be recomputed from a primary database if lost. As a primary database, Redis stores unique, long-term data, requiring developers to rely on RDB or AOF persistence to prevent permanent data loss in the event of failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd02e666-f427-44a5-adc2-762cc050155b', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify''s router handle wildcard and parameter matching?', N'Middle', N'Fastify uses a radix tree-based routing algorithm, which provides O(1) or O(log n) lookup times regardless of the number of routes. This is significantly more efficient than the regex-based matching used by older frameworks as the route count grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
