INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98e31247-85eb-4827-8d8d-7634ca7d7c92', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'When should you choose a local component state over the global Redux store?', N'Senior', N'Local state is preferred for transient data that doesn''t need to be shared across the application or persisted, such as form inputs or UI-specific toggles. Moving this data to Redux creates unnecessary global coupling and adds complexity to the state tree without providing architectural benefit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1895f14-7808-47e0-a45f-7634ef3bedd6', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of the copy-and-swap idiom in C++?', N'Senior', N'The copy-and-swap idiom is a technique used to implement robust assignment operators that provide strong exception guarantees. It works by creating a temporary copy of the source object, swapping the current object''s internal state with the copy, and letting the temporary object''s destructor clean up the old resources, ensuring the original object remains valid if an allocation fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
