INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70f16902-e47c-4df6-8104-7637b31d2639', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Explain the concept of ''observability'' versus ''monitoring'' in troubleshooting.', N'Middle', N'Monitoring focuses on identifying when a system is unhealthy by tracking predefined metrics, while observability is the ability to understand the internal state of a system by examining its outputs. Observability is superior for troubleshooting because it allows you to ask novel questions about complex, unforeseen system behaviors. Monitoring tells you that something is broken, while observability helps you understand why it is broken.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05b72219-1d4f-4f98-ae77-763996996b48', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Why is it generally discouraged to put business logic inside Rails controllers?', N'Middle', N'Controllers should ideally only handle request parameters, initiate service actions, and render responses. Keeping business logic out of controllers makes the code easier to test, promotes the DRY principle, and allows the same logic to be reused in background jobs, console tasks, or API endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3baa77a6-52e8-4619-b70d-763d9c50af38', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you optimize a database that has become the primary bottleneck for your application?', N'Senior', N'I would start by analyzing query execution plans to identify missing indexes or inefficient joins. If the load remains high, I would implement read-write splitting, introduce caching layers to reduce database hits, and eventually consider database sharding to distribute the data load across multiple instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0eee7f6c-d52f-47c0-9a67-763db1b34b54', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs regarding security when using third-party integrations?', N'Junior', N'Third-party services allow you to leverage specialized tools quickly, but they increase your security surface area. You are effectively delegating trust to the provider and must manage the risk of their potential vulnerabilities impacting your own system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
