INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60303d79-a932-40b0-8265-7644efa1e92c', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the main advantage of using Redux in a large-scale project?', N'Fresher', N'The main advantage is predictability and maintainability. Because state changes are centralized and strictly controlled via actions and reducers, it is much easier to manage complex data flows and track down bugs as the application grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e6bce6d-1083-4993-bbe3-76479561e195', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Explain the trade-offs of using ''Edge Runtime'' versus ''Node.js Runtime'' for API routes.', N'Senior', N'The Edge Runtime is built on V8 and offers extremely low latency by running near the user, but it lacks access to many Node.js APIs and has smaller memory limits. The Node.js runtime is more versatile and supports complex libraries but is restricted to specific geographic regions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
