INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'001ddec8-c161-4368-9ee3-7653ab442cf1', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s ''Sendable'' protocol enforce thread safety across concurrency boundaries?', N'Senior', N'The Sendable protocol marks types as safe to pass between concurrency domains by ensuring they are either immutable, internally synchronized, or value types. It allows the compiler to perform static analysis, flagging any attempt to pass non-thread-safe data across task boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
