INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86ddcab3-f599-4920-a242-765469577665', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why is it important to break down a large project into smaller tasks before estimating?', N'Fresher', N'Breaking a project into smaller tasks reduces complexity and makes it easier to identify hidden dependencies or risks. It allows for more granular estimation, which is generally more accurate than trying to estimate a large, monolithic task at once.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
