INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ca78bae-f0e7-4fb7-b318-765e49aed469', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the purpose of the ''default'' flag in Sass variables?', N'Middle', N'The !default flag allows you to assign a value to a variable only if it has not already been assigned a value. This is extremely useful in library development, as it allows users to override default settings globally before importing the library''s main files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f8ca2fa-577d-4234-9c66-7666f1969b9a', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of the Micronaut ''Introspection'' feature?', N'Middle', N'Introspection provides a way to access class metadata without using Java reflection. By generating an ''Introspector'' class at compile time, Micronaut allows for efficient serialization, object mapping, and property access, which significantly improves performance in resource-constrained environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15a3cc17-0a88-4518-b869-766704976409', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the difference between console.log() and console.dir()?', N'Fresher', N'* console.log() prints the element in an HTML-like tree Output * console.dir() prints the element in a JSON-like tree Output', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86d24ba6-0d45-4a26-82a5-766edc5743d7', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the ''Bulkhead'' pattern in microservice architecture?', N'Senior', N'The bulkhead pattern isolates resources such as thread pools or connections for different services or workloads. This ensures that if one service experiences a surge or failure, it consumes only its allocated resources, preventing the failure from propagating to the entire system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5c14955-c74c-4b51-a41f-766f77b06017', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What does the ''mut'' keyword do?', N'Fresher', N'By default, all variables in Rust are immutable, meaning their values cannot change once assigned. The ''mut'' keyword allows a variable to be mutable, meaning its value can be modified after it is initially set.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83b0016f-9158-4e24-a5a2-7671a0ca9c47', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a Foreign Key, and what role does it play?', N'Fresher', N'A foreign key is a field that links one table to another by referencing the primary key of the related table. Its primary role is to maintain referential integrity, ensuring that data across different tables remains consistent and connected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93c7b3eb-631e-4e03-8b4f-767257f28137', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'In a distributed system, how does Litestar''s ''DTO'' layer improve data integrity compared to raw Pydantic models?', N'Senior', N'Litestar''s DTOs decouple the external API contract from internal domain models, preventing over-posting vulnerabilities and implementation leakage. By enforcing strict transformation schemas, they ensure that internal model changes do not break external client contracts, providing a robust layer for API versioning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
