INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'867e2e69-df87-4051-b235-767ad34215a5', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the limitations of using a scan operation in DynamoDB?', N'Middle', N'A scan operation reads every single item in the entire table, which is highly inefficient and expensive for large datasets. It consumes significant read throughput and can lead to performance degradation, so it should be avoided in favor of Query operations whenever possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cb13741-fe4e-423b-a1a3-768190ceb822', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi''s routing mechanism differ from the standard net/http ServeMux in terms of performance and feature set?', N'Middle', N'Chi utilizes a radix tree-based routing algorithm, which provides significantly faster lookup times for complex routing patterns compared to the standard library''s linear path matching. Additionally, Chi offers built-in support for URL parameters, grouping, and a robust middleware stack, whereas the standard library requires manual implementation or external packages for these advanced routing requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2a28bfd-4ef2-4b44-8cbd-768290393d5b', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What does the ''static'' keyword do when applied to a local variable?', N'Intern', N'When applied to a local variable, ''static'' causes the variable to maintain its value between multiple function calls. Instead of being recreated each time the function is called, the variable is initialized only once and persists for the lifetime of the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e97de4c-9ef4-4b09-8753-768326ed77e1', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the error.js file used for?', N'Junior', N'The error.js file defines an error boundary for a route segment. If a runtime error occurs within that segment or its children, Next.js displays the content of this file, allowing you to handle errors gracefully and provide a way for the user to try again.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
