INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19810e1d-9b12-4a02-960e-7687b6169046', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus handle database connection pooling in a reactive context?', N'Senior', N'Quarkus provides reactive database drivers (e.g., Reactive PostgreSQL) that are non-blocking. This allows the application to perform database queries without tying up a thread, which is essential for maintaining high throughput in reactive pipelines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'322d84ab-6ef4-4eb8-ae55-768a3b687ce5', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why is it important to use ''button'' elements for interactive UI rather than ''div'' or ''span''?', N'Senior', N'The ''button'' element provides native keyboard accessibility, such as activation via the Enter and Space keys, and is correctly identified by screen readers as an interactive element. Using a ''div'' or ''span'' requires manually adding ''tabindex'', event handlers, and ARIA roles, which often fails to replicate the complete native behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e279cc6-54ab-4e80-9e36-76950916f83f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of a union type in TypeScript?', N'Junior', N'A union type allows a variable to hold values of several different types, separated by a pipe symbol. It is useful when a function or property can accept multiple possible data types, such as a string or a number.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea99364c-2c7b-4a24-9787-7695615d67ff', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Why is it important to use `defer()` and `only()` in Django QuerySets for large datasets?', N'Senior', N'These methods allow you to exclude or include specific database columns, reducing the amount of data transferred and the memory required to represent the models. This is critical for performance when dealing with tables containing large text or binary fields that are not needed for every query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04e8d65f-172b-4eba-ae88-76979046333c', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between Response Caching and Output Caching in ASP.NET Core, and when should each be used?', N'Senior', N'Response Caching middleware uses HTTP headers to control caching behavior at the client or proxy level, whereas Output Caching stores the actual generated response body on the server. Output Caching is more powerful as it allows the server to serve content without re-executing the entire request pipeline, significantly improving performance for dynamic content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afe67089-4015-4484-a123-7698d7373554', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the benefit of Tailwind''s ''arbitrary variants'' feature for complex UI interactions?', N'Senior', N'Arbitrary variants allow developers to define custom CSS selectors or media queries on the fly without updating the configuration. This is powerful for handling edge cases like complex parent-child interactions or target-specific browser behaviors, providing the flexibility of native CSS while staying within the Tailwind ecosystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0cea6da-8b5f-4100-9213-769c7fb31064', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the purpose of the ''tailwind.config.js'' file?', N'Intern', N'This file is used to customize the default theme of Tailwind CSS. You can extend the default configuration, add custom plugins, or override specific values like colors and fonts to tailor the framework to your project needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15416dfa-669e-478c-bdd4-769d5ef617a3', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle WebSocket connections differently than standard HTTP request-response cycles?', N'Senior', N'Axum treats WebSockets as an upgrade protocol, where a standard HTTP request is transformed into a persistent bidirectional stream. By utilizing extractors to handle the handshake and providing a dedicated WebSocket stream type, Axum allows for seamless integration of real-time features within the same unified routing structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27c7b91e-8d83-4b06-8f9e-76a54e256cbf', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is a Django project and how is it different from a Django app?', N'Intern', N'Django Project is the high-level umbrella under which you build a web application. It encompasses multiple components such as settings, URLs, and can host several apps. In contrast, a Django App is a standalone module designed to serve a specific functionality or business area, following the concept of "application" as a group of related features. Key Components of a Django Project - Settings: Configuration options for the project and its apps. - URLs: Defines the endpoint mappings using urls.py. - WSGI/ASGI: Entry points for the web server to serve the project, handling HTTP and WebSocket requests, respectively. Key Components of a Django App - Models: Data layer, defining data structures using models.py. - Views: Business logic and presentation layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a9d6284-53ee-4ff3-b49a-76a5e7c4abbe', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Does DynamoDB support relational joins?', N'Fresher', N'No, DynamoDB does not support joins. Because it is a NoSQL database, it is optimized for high-speed single-table operations rather than complex queries across multiple tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'527d1210-967e-4b3f-bd97-76a8109bbcdb', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'When should you move logic from a component to a Redux action or middleware?', N'Middle', N'You should move logic to Redux when it involves complex business rules, shared side effects, or data processing that needs to be consistent across multiple parts of the application. Keeping components ''dumb'' and focused on rendering is generally preferred.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
