INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fdb0e9b-f8e9-4888-8374-76ac80448525', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How do PHP generators contribute to memory efficiency in processing large datasets?', N'Senior', N'Generators allow for the iteration of data sets without loading the entire collection into memory, by yielding one item at a time through the stack. This transforms an O(N) memory complexity operation into an O(1) operation, enabling the processing of massive files or database result sets that would otherwise exceed the memory limit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33a6b927-8027-493f-8560-76b2d335b217', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are Entities in Doctrine?', N'Fresher', N'Entities are plain PHP objects that represent rows in a database table. They contain properties that map to table columns and are used by Doctrine to persist data into the database and retrieve it back as objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b394242c-3955-485f-ad3e-76b80c232bb9', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the impact of ''blocking=render'' on the document''s initial layout?', N'Senior', N'The blocking attribute on elements like scripts or stylesheets tells the browser to pause rendering until the resource is downloaded and processed. While this ensures that no unstyled content is shown, excessive use can lead to a blank screen or a poor user experience if the network is slow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
