INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad8e0ea1-ea51-4f1f-b0c6-76c041243319', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How do goroutines differ from traditional OS threads?', N'Junior', N'Goroutines are lightweight threads managed by the Go runtime rather than the operating system. They have a significantly smaller initial stack size and are multiplexed onto a smaller number of OS threads, which allows a single application to efficiently run thousands or even millions of concurrent tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
