INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'572e8623-d564-4558-b909-76c7b7af6039', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'When is it appropriate to use an asynchronous messaging pattern versus synchronous REST/gRPC?', N'Senior', N'Asynchronous messaging is preferred for long-running processes or decoupling services to improve scalability and fault tolerance. Synchronous communication is better suited for operations that require an immediate response or where the user experience depends on synchronous confirmation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
