INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68edac6f-be3b-4be5-873e-76ca320cd8a0', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Why is ''Design for Failure'' a fundamental principle in microservices?', N'Senior', N'Because microservices rely on a network, failures are inevitable. Designing for failure means creating systems that gracefully degrade, use retries, and employ circuit breakers to ensure the entire system remains functional even when individual components are unreachable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3c631f8-f528-4365-9066-76cb264d7675', N'4c000000-0000-0000-0000-000000000005', N'Discuss the trade-offs of using a message broker versus direct HTTP calls between services.', N'Senior', N'Message brokers provide temporal decoupling, load leveling, and improved fault tolerance, but they introduce infrastructure complexity and eventual consistency. Direct HTTP calls are easier to implement and provide immediate feedback, but they create tight coupling and are prone to cascading failures if not managed with circuit breakers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
